module hist_precedence (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_op,     // 0 = add one sample to bin i_sel, 1 = remove one
    input  wire [1:0] i_sel,
    output reg  [5:0] total
);
    // histogram bins
    reg [3:0] bin0, bin1, bin2, bin3;

    // shadow of the earlier event: which bin got the very first sample
    reg [1:0] first_bin;
    reg       saw_sample;

    // scope arming register: high until the first removal aimed at first_bin
    reg       pre_purge;

    // shadow high-water mark of the first-sampled bin's count
    reg [3:0] hi_first;

    initial begin
        bin0       = 4'd0;
        bin1       = 4'd0;
        bin2       = 4'd0;
        bin3       = 4'd0;
        total      = 6'd0;
        first_bin  = 2'd0;
        saw_sample = 1'b0;
        pre_purge  = 1'b1;
        hi_first   = 4'd0;
    end

    wire [3:0] sel_cnt   = (i_sel == 2'd0) ? bin0 :
                           (i_sel == 2'd1) ? bin1 :
                           (i_sel == 2'd2) ? bin2 : bin3;

    wire [3:0] first_cnt = (first_bin == 2'd0) ? bin0 :
                           (first_bin == 2'd1) ? bin1 :
                           (first_bin == 2'd2) ? bin2 : bin3;

    wire do_add = i_ce && !i_op && (total != 6'd31) && (sel_cnt != 4'd15);
    wire do_rem = i_ce &&  i_op && (sel_cnt != 4'd0);
    wire purge  = i_ce &&  i_op && saw_sample && (i_sel == first_bin);

    wire armed  = pre_purge && saw_sample;

    // count the first-sampled bin will hold after this cycle
    wire [3:0] first_nxt =
        (do_add && !saw_sample)                          ? (sel_cnt   + 4'd1) :
        (do_add && saw_sample && (i_sel == first_bin))    ? (first_cnt + 4'd1) :
        (do_rem && saw_sample && (i_sel == first_bin))    ? (first_cnt - 4'd1) :
                                                            first_cnt;

    always @(posedge clk) begin
        if (i_ce) begin
            if (do_add) begin
                total <= total + 6'd1;
                case (i_sel)
                    2'd0:    bin0 <= bin0 + 4'd1;
                    2'd1:    bin1 <= bin1 + 4'd1;
                    2'd2:    bin2 <= bin2 + 4'd1;
                    default: bin3 <= bin3 + 4'd1;
                endcase
                if (!saw_sample) begin
                    saw_sample <= 1'b1;
                    first_bin  <= i_sel;
                end
            end else if (do_rem) begin
                total <= total - 6'd1;
                case (i_sel)
                    2'd0:    bin0 <= bin0 - 4'd1;
                    2'd1:    bin1 <= bin1 - 4'd1;
                    2'd2:    bin2 <= bin2 - 4'd1;
                    default: bin3 <= bin3 - 4'd1;
                endcase
            end

            if (purge)
                pre_purge <= 1'b0;

            if (do_add && !saw_sample)
                hi_first <= sel_cnt + 4'd1;
            else if (first_nxt > hi_first)
                hi_first <= first_nxt;
        end
    end

    // P: before any sample has ever been purged from the first-sampled bin,
    // the earlier arrival recorded in the shadow registers must still be
    // accounted for in the total-samples register.
    always @(posedge clk)
        if (armed) assert (total >= 6'd1);

    always @(posedge clk)
        if (armed) assert (total >= {2'b00, hi_first});
endmodule

module skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,          // idle condition: en low freezes all state
    input  wire       in_valid,
    input  wire [7:0] in_data,
    input  wire       out_ready,
    output wire       in_ready,
    output reg        out_valid,
    output reg  [7:0] out_data
);
    // skid buffer: only meaningful while the stall flag skid_valid is up
    reg        skid_valid;
    reg  [7:0] skid_data;

    // redundant occupancy counter (3 bits wide, but only 0..2 are real)
    reg  [2:0] occ;

    // sticky arm: set the first time a word is actually accepted
    reg        armed;

    initial begin
        out_valid  = 1'b0;
        out_data   = 8'h00;
        skid_valid = 1'b0;
        skid_data  = 8'h00;
        occ        = 3'd0;
        armed      = 1'b0;
    end

    assign in_ready = !skid_valid;

    wire accept = en && in_valid && in_ready;
    wire drain  = en && out_valid && out_ready;

    always @(posedge clk) begin
        if (rst) begin
            out_valid  <= 1'b0;
            out_data   <= 8'h00;
            skid_valid <= 1'b0;
            skid_data  <= 8'h00;
            occ        <= 3'd0;
            armed      <= 1'b0;
        end else if (en) begin
            // output register / skid promotion
            if (!out_valid || out_ready) begin
                if (skid_valid) begin
                    out_data   <= skid_data;
                    out_valid  <= 1'b1;
                    skid_valid <= 1'b0;
                end else if (in_valid) begin
                    out_data  <= in_data;
                    out_valid <= 1'b1;
                end else begin
                    out_valid <= 1'b0;
                end
            end else begin
                // downstream stalled: park the incoming word in the skid slot
                if (in_valid && !skid_valid) begin
                    skid_data  <= in_data;
                    skid_valid <= 1'b1;
                end
            end

            // occupancy bookkeeping, tracked independently of the flags
            occ <= occ + (accept ? 3'd1 : 3'd0) - (drain ? 3'd1 : 3'd0);

            if (accept) armed <= 1'b1;
        end
    end

    // P, part 1: once the stage has ever accepted a word, occupancy never
    // exceeds 2 even though the counter is 3 bits wide
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd2);

    // P, part 2: once armed, whenever the skid slot holds a meaningful word the
    // stage is occupancy-saturated at exactly 2
    always @(posedge clk)
        if (armed)
            assert (!skid_valid || occ == 3'd2);
endmodule

module vd_sheet_loader (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_start,
    input  wire       i_last_row,
    output wire       o_loading,
    output wire       o_ready,
    output wire [3:0] o_rows
);
    // binary-encoded loader FSM: IDLE/OPEN/HEADER/ROWS/DONE
    // encodings 101, 110, 111 are never entered by construction
    localparam [2:0] S_IDLE   = 3'b000,
                     S_OPEN   = 3'b001,
                     S_HEADER = 3'b010,
                     S_ROWS   = 3'b011,
                     S_DONE   = 3'b100;

    reg [2:0] st;
    reg       loading;
    reg       ready;
    reg [3:0] rows;

    initial st      = S_IDLE;
    initial loading = 1'b0;
    initial ready   = 1'b0;
    initial rows    = 4'd0;

    always @(posedge clk) begin
        if (i_reset) begin
            st      <= S_IDLE;
            loading <= 1'b0;
            ready   <= 1'b0;
            rows    <= 4'd0;
        end else if (i_ce) begin
            case (st)
                S_IDLE: begin
                    if (i_start) begin
                        st      <= S_OPEN;
                        loading <= 1'b1;
                        ready   <= 1'b0;
                    end else begin
                        st      <= S_IDLE;
                        loading <= 1'b0;
                        ready   <= 1'b0;
                    end
                end
                S_OPEN: begin
                    st      <= S_HEADER;
                    loading <= 1'b1;
                    ready   <= 1'b0;
                    rows    <= 4'd0;
                end
                S_HEADER: begin
                    st      <= S_ROWS;
                    loading <= 1'b1;
                    ready   <= 1'b0;
                end
                S_ROWS: begin
                    if (i_last_row) begin
                        st      <= S_DONE;
                        loading <= 1'b0;
                        ready   <= 1'b1;
                    end else begin
                        st      <= S_ROWS;
                        loading <= 1'b1;
                        ready   <= 1'b0;
                        rows    <= rows + 4'd1;
                    end
                end
                S_DONE: begin
                    st      <= S_IDLE;
                    loading <= 1'b0;
                    ready   <= 1'b0;
                end
                default: begin
                    // illegal encoding: parked recovery path, asserts both flags
                    st      <= 3'b110;
                    loading <= 1'b1;
                    ready   <= 1'b1;
                end
            endcase
        end
    end

    assign o_loading = loading;
    assign o_ready   = ready;
    assign o_rows    = rows;

    // P: the loader is never simultaneously loading and ready
    always @(posedge clk)
        assert (!(loading && ready));
endmodule

// Priority arbiter for per-subchannel energy detect flags.
// Stage 0: combinational priority encode of the request vector.
// Stage 1: registered half-occupancy flags + priority-half decision.
// Stage 2: registered valid, registered index (only meaningful while valid),
//          and the two half-band grant flags.
module wifi_pri_grant (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [7:0] i_req,
    output reg        o_vld,
    output reg  [2:0] o_idx,
    output reg        o_grant_lo,
    output reg        o_grant_hi
);
    // ---------------- stage 0: combinational priority encoder ------------
    wire req_lo = |i_req[3:0];
    wire req_hi = |i_req[7:4];

    reg [2:0] enc;
    always @(*) begin
        casez (i_req)
            8'b???????1: enc = 3'd0;
            8'b??????10: enc = 3'd1;
            8'b?????100: enc = 3'd2;
            8'b????1000: enc = 3'd3;
            8'b???10000: enc = 3'd4;
            8'b??100000: enc = 3'd5;
            8'b?1000000: enc = 3'd6;
            8'b10000000: enc = 3'd7;
            default:     enc = 3'd0;
        endcase
    end

    // ---------------- stage 1 registers ---------------------------------
    reg       s1_vld;
    reg       s1_req_lo;
    reg       s1_req_hi;
    reg       s1_pri_hi;   // upper half wins only when lower half is empty
    reg [2:0] s1_idx;

    initial begin
        s1_vld    = 1'b0;
        s1_req_lo = 1'b0;
        s1_req_hi = 1'b0;
        s1_pri_hi = 1'b0;
        s1_idx    = 3'd0;
        o_vld      = 1'b0;
        o_idx      = 3'd0;
        o_grant_lo = 1'b0;
        o_grant_hi = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // stage 1 capture
            s1_vld    <= req_lo | req_hi;
            s1_req_lo <= req_lo;
            s1_req_hi <= req_hi;
            s1_pri_hi <= req_hi && !req_lo;
            s1_idx    <= enc;

            // stage 2 capture
            o_vld      <= s1_vld;
            o_idx      <= s1_idx;
            o_grant_lo <= s1_vld && s1_req_lo;
            o_grant_hi <= s1_vld && s1_pri_hi;
        end
    end

    // P: while the encoded index is valid, the two half-band grants are
    //    never asserted together.
    always @(posedge clk)
        if (o_vld)
            assert (!(o_grant_lo && o_grant_hi));

endmodule

// Simple token-lexer FSM: binary-encoded states 0..4, encodings 5..7 unused.
module lex_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [1:0] cls,     // 0=escape/backslash, 1=alpha, 2=digit, 3=quote
    output reg  [2:0] st,
    output reg  [2:0] len
);
    localparam [2:0] S_IDLE  = 3'd0;
    localparam [2:0] S_IDENT = 3'd1;
    localparam [2:0] S_NUM   = 3'd2;
    localparam [2:0] S_STR   = 3'd3;
    localparam [2:0] S_ESC   = 3'd4;

    wire [2:0] len_inc = (len == 3'd7) ? 3'd7 : (len + 3'd1);

    initial st  = S_IDLE;
    initial len = 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            st  <= S_IDLE;
            len <= 3'd0;
        end else if (ce) begin
            case (st)
                S_IDLE: begin
                    if (cls == 2'd1) begin
                        st  <= S_IDENT;
                        len <= 3'd1;
                    end else if (cls == 2'd2) begin
                        st  <= S_NUM;
                        len <= 3'd1;
                    end else if (cls == 2'd3) begin
                        st  <= S_STR;
                        len <= 3'd0;
                    end else begin
                        st  <= S_IDLE;
                        len <= 3'd0;
                    end
                end
                S_IDENT: begin
                    if (cls == 2'd1 || cls == 2'd2) begin
                        st  <= S_IDENT;
                        len <= len_inc;
                    end else begin
                        st  <= S_IDLE;
                        len <= 3'd0;
                    end
                end
                S_NUM: begin
                    if (cls == 2'd2) begin
                        st  <= S_NUM;
                        len <= len_inc;
                    end else begin
                        st  <= S_IDLE;
                        len <= 3'd0;
                    end
                end
                S_STR: begin
                    if (cls == 2'd3) begin
                        st  <= S_IDLE;   // closing quote ends the token
                        len <= 3'd0;
                    end else if (cls == 2'd0) begin
                        st  <= S_ESC;    // backslash: next char is literal
                        len <= len;
                    end else begin
                        st  <= S_STR;
                        len <= len_inc;
                    end
                end
                S_ESC: begin
                    st  <= S_STR;
                    len <= len_inc;
                end
                default: begin
                    // unreachable encodings 5..7: recover to IDLE
                    st  <= S_IDLE;
                end
            endcase
        end
    end

    // P: in the IDLE state the accumulated token length is always zero.
    always @(*)
        if (st == 3'd0)
            assert (len == 3'd0);
endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    reg [7:0] d0, d1;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
    wire do_push = push && !v1;
    wire do_pop  = pop  &&  v0;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            d0    <= 8'h00;
            d1    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                    d0 <= din;
                    v0 <= 1'b1;
                end else begin
                    d1 <= din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
                d0 <= din;
            end

            count <= count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
        end
    end

    assign dout    = d0;
    assign o_empty = !v0;
    assign o_full   = v1;
    assign o_count  = count;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);
endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;

    wire [2:0] gray  = bin ^ (bin >> 1);
    wire [2:0] delta = sync1 ^ sync2;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;

            if (bad_ev) begin
                stage <= S_FINISH;
            end else begin
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                    end
                S_STARTED:
                    if (fin_ev)
                        stage <= S_FINISH;
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
    assign o_done  = (stage == S_FINISH);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       issue,     // new operation issued this advance
    output wire       o_retire,  // fixed-latency result leaving the unit
    output wire [2:0] o_occ
);
    // 4-deep fixed-latency shift register: bit k = op issued k cycles ago
    reg [3:0] pipe;
    // occupancy: incremented on issue, decremented when the tail drains
    reg [2:0] occ;
    // sticky arm: set the first time an operation is ever issued
    reg       armed;

    initial pipe  = 4'b0000;
    initial occ   = 3'd0;
    initial armed = 1'b0;

    assign o_retire = i_ce && pipe[3];
    assign o_occ    = occ;

    always @(posedge clk) begin
        if (rst) begin
            pipe  <= 4'b0000;
            occ   <= 3'd0;
            armed <= 1'b0;
        end else if (i_ce) begin
            pipe <= {pipe[2:0], issue};
            occ  <= occ + (issue ? 3'd1 : 3'd0) - (pipe[3] ? 3'd1 : 3'd0);
            if (issue)
                armed <= 1'b1;
        end
    end

    // P: once the unit has ever issued, at most 4 operations are in flight.
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd4);
endmodule

// Stack pointer with a ratcheting high-water mark, plus a three-step
// arm -> start -> finish transaction FSM whose start step needs live data
// on the stack.
module hwm_chain_precedence (
    input  wire clk,
    input  wire ce,
    input  wire i_push,
    input  wire i_pop,
    input  wire i_arm,
    input  wire i_start,
    input  wire i_finish,
    input  wire i_clear,
    output wire o_finish,
    output wire [3:0] o_mark
);
    localparam [3:0] DEPTH = 4'd8;

    localparam [1:0] S_IDLE    = 2'd0;
    localparam [1:0] S_ARMED   = 2'd1;
    localparam [1:0] S_STARTED = 2'd2;
    localparam [1:0] S_DONE    = 2'd3;

    reg [3:0] sp;
    reg [3:0] hwm;      // high-water mark: never below sp, only ratchets up
    reg [1:0] stage;
    reg       saw_arm;
    reg       saw_start;
    reg       obs_en;    // sticky: set the first cycle a push is accepted

    initial sp        = 4'd0;
    initial hwm       = 4'd0;
    initial stage     = S_IDLE;
    initial saw_arm   = 1'b0;
    initial saw_start = 1'b0;
    initial obs_en    = 1'b0;

    wire do_push = ce && i_push && !i_pop && (sp <  DEPTH);
    wire do_pop  = ce && i_pop  && !i_push && (sp != 4'd0);

    wire [4:0] nxt_sp = {1'b0, sp} + 5'd1;

    // ---- stack pointer and high-water mark -------------------------------
    always @(posedge clk) begin
        if (do_push) begin
            sp     <= sp + 4'd1;
            obs_en <= 1'b1;
            if (nxt_sp > {1'b0, hwm})
                hwm <= nxt_sp[3:0];
        end else if (do_pop) begin
            sp <= sp - 4'd1;
        end
    end

    // ---- three-step chain: arm, then start, then finish ------------------
    always @(posedge clk) begin
        if (ce) begin
            case (stage)
                S_IDLE: begin
                    if (i_arm) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                    end
                end
                S_ARMED: begin
                    if (i_start && (sp != 4'd0)) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                    end
                end
                S_STARTED: begin
                    if (i_finish && (sp != 4'd0))
                        stage <= S_DONE;
                end
                default: begin
                    if (i_clear)
                        stage <= S_IDLE;
                end
            endcase
        end
    end

    assign o_finish = (stage == S_DONE);
    assign o_mark   = hwm;

    // Property: once the mark has been armed by a first push, a finish can
    // never be observed unless arm and start were both observed before it and
    // the high-water mark records that data was really on the stack.
    assert property (!obs_en || !o_finish ||
                     (saw_arm && saw_start && (hwm >= 4'd1)));
endmodule

module wifi_radio_owner_fsm (
    input  wire clk,
    input  wire rst,
    input  wire step,      // idle/enable: low freezes all state
    input  wire rx_start,  // preamble detected by the receiver
    input  wire tx_req,    // MAC wants the air for a frame
    output wire radio_tx,  // transmit chain owns the radio
    output wire radio_rx   // receive chain owns the radio
);
    // one-hot MAC air-interface FSM:
    //   bit0 = IDLE, bit1 = RX_FRAME, bit2 = TX_PREAMBLE,
    //   bit3 = TX_DATA, bit4 = ACK_WAIT
    reg [4:0] state;
    initial state = 5'b00001;

    wire s_idle  = state[0];
    wire s_rx    = state[1];
    wire s_txpre = state[2];
    wire s_tx    = state[3];
    wire s_ackw  = state[4];

    // next-state as a per-bit OR of its legal source states
    wire [4:0] nxt;
    assign nxt[0] = (s_idle & ~rx_start & ~tx_req) | s_rx | s_ackw;
    assign nxt[1] = s_idle & rx_start;                 // RX wins the air
    assign nxt[2] = s_idle & tx_req & ~rx_start;       // else start TX ramp
    assign nxt[3] = s_txpre;                           // preamble -> data
    assign nxt[4] = s_tx;                              // data -> wait for ACK

    always @(posedge clk) begin
        if (rst)
            state <= 5'b00001;
        else if (step)
            state <= nxt;
    end

    // decoded radio ownership
    assign radio_tx = s_txpre | s_tx;
    assign radio_rx = s_rx    | s_ackw;

    // P: the transmit and receive chains never own the radio together
    always @(*)
        assert (!(radio_tx && radio_rx));
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
    end

    wire [3:0] nxt      = cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
            s1  <= g;
            s2  <= s1;
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
    assign o_settled = (diff == 4'd0);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module pdk_reqtrack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_arm,     // Q event: arms the tracker (sticky)
    input  wire       i_launch,  // start step: issue a request into the array
    output wire       o_retire,  // finish step: request leaves last stage
    output wire [2:0] o_inflight
);
    parameter STAGES = 4;

    // shift register tracking in-flight requests through the stage array
    reg [STAGES-1:0] pipe;
    // separate count of set bits in that shift register
    reg [2:0]        cnt;
    // sticky arm register (scope): set the first time i_arm is seen, never cleared
    reg              armed;
    // sticky record that a start actually happened after arming
    reg              started;

    initial pipe    = {STAGES{1'b0}};
    initial cnt     = 3'd0;
    initial armed   = 1'b0;
    initial started = 1'b0;

    // a launch is only accepted once the tracker has been armed
    wire accept = i_ce && i_launch && armed;
    wire retire = i_ce && pipe[STAGES-1];

    assign o_retire   = retire;
    assign o_inflight = cnt;

    always @(posedge clk) begin
        if (rst) begin
            pipe    <= {STAGES{1'b0}};
            cnt     <= 3'd0;
            armed   <= 1'b0;
            started <= 1'b0;
        end else if (i_ce) begin
            pipe    <= { pipe[STAGES-2:0], (i_launch && armed) };
            cnt     <= cnt + ((i_launch && armed) ? 3'd1 : 3'd0)
                           - (pipe[STAGES-1]    ? 3'd1 : 3'd0);
            armed   <= armed || i_arm;
            started <= started || (i_launch && armed);
        end
    end

    // Chain precedence, after the sticky arm: while armed, the tracker can never
    // report outstanding work unless a start was really accepted first.
    always @(posedge clk)
        if (armed && (cnt != 3'd0))
            assert (started);

endmodule

// Transaction scoreboard with a completion deadline countdown.
// issued/retired are wrapping transaction counters; outst is the occupancy
// of the issue window (WINDOW deep). Every outstanding transaction is forced
// to retire before its RELOAD-cycle deadline countdown reaches zero.
module scoreboard_deadline (
    input  wire clk,
    input  wire ce,      // idle condition: ce low freezes the scoreboard
    input  wire issue,
    input  wire retire,
    output wire busy
);
    localparam [2:0] WINDOW = 3'd4;
    localparam [2:0] RELOAD = 3'd5;

    reg [3:0] issued;
    reg [3:0] retired;
    reg [2:0] outst;    // outstanding transactions = issued - retired
    reg [2:0] timer;    // deadline countdown for the oldest outstanding item
    reg       armed;    // sticky: set the first time a transaction is accepted
    reg       pv;       // past valid

    initial begin
        issued  = 4'd0;
        retired = 4'd0;
        outst   = 3'd0;
        timer   = 3'd0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    assign busy = (outst != 3'd0);

    // deadline flag: the countdown has run out
    wire expired = (timer == 3'd0);

    // the design completes a transaction itself when the deadline is imminent
    wire force_ret = (outst != 3'd0) && (timer == 3'd1);

    wire do_issue  = ce && issue && (outst < WINDOW);
    wire do_retire = ce && (outst != 3'd0) && (retire || force_ret);

    wire [2:0] outst_n = do_issue ? (do_retire ? outst : outst + 3'd1)
                                  : (do_retire ? outst - 3'd1 : outst);

    always @(posedge clk) begin
        pv <= 1'b1;

        if (do_issue) begin
            armed  <= 1'b1;
            issued <= issued + 4'd1;
        end

        if (do_retire)
            retired <= retired + 4'd1;

        outst <= outst_n;

        if (do_issue || do_retire) begin
            // any scoreboard event restarts (or clears) the deadline
            if (outst_n == 3'd0) timer <= 3'd0;
            else                 timer <= RELOAD;
        end else if (ce && (outst != 3'd0)) begin
            timer <= timer - 3'd1;
        end
    end

    // Bounded response, safety form, in no-change style, scoped after arming:
    // once a transaction has been accepted, whenever the outstanding count did
    // not change and work is still outstanding, the deadline flag must not
    // change either (i.e. the countdown cannot expire under an outstanding
    // request).
    always @(posedge clk) begin
        if (pv && armed && (outst != 3'd0) && $stable(outst))
            assert ($stable(expired));
    end
endmodule

// Sliding-window grant rate limiter: an 8-cycle shift register of recent
// grants plus an occupancy counter that mirrors its population count.
// A grant may only be issued if no grant occurred in the last two cycles,
// which spaces grants at least 3 cycles apart and therefore caps the
// occupancy of the 8-deep window at 3, far below the 4-bit counter range.
module grant_window_limiter (
    input  wire       clk,
    input  wire       ce,      // idle when low: no state changes
    input  wire       req,
    output wire       grant,
    output reg  [7:0] win,
    output reg  [3:0] ones
);

    reg armed = 1'b0;   // sticky: set the first time a grant is issued
    reg pv    = 1'b0;   // past-valid

    initial win  = 8'b0000_0000;
    initial ones = 4'd0;

    // spacing rule: nothing granted in the two most recent slots
    wire allow = (win[1:0] == 2'b00);
    wire g     = ce && req && allow;

    assign grant = g;

    always @(posedge clk) begin
        if (ce) begin
            win  <= {win[6:0], g};
            ones <= ones + (g ? 4'd1 : 4'd0) - (win[7] ? 4'd1 : 4'd0);
        end
        if (g)
            armed <= 1'b1;
        pv <= 1'b1;
    end

    // Bounded existence, at most 3, in the scope after the first grant.
    always @(posedge clk)
        if (pv && armed)
            assert ((ones <= 4'd3) && ($past(ones) <= 4'd3));

endmodule

module token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle condition: nothing moves when low
    input  wire       req,
    output reg        grant_q,
    output reg [3:0]  tokens
);
    localparam [3:0] BURST  = 4'd12; // bucket cap
    localparam [3:0] REFILL = 4'd3;  // tokens added per timer tick
    localparam [2:0] PERIOD = 3'd4;  // refill timer top

    reg [2:0] timer;
    reg       saw_refill;            // shadow: a refill tick has occurred

    wire       tick     = (timer == PERIOD);
    wire       do_grant = ce && req && (tokens != 4'd0);
    wire [4:0] sum      = {1'b0, tokens} + {1'b0, REFILL};
    wire [3:0] refilled = (sum > {1'b0, BURST}) ? BURST : sum[3:0];

    initial begin
        timer      = 3'd0;
        tokens     = 4'd0;
        saw_refill = 1'b0;
        grant_q    = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            timer      <= 3'd0;
            tokens     <= 4'd0;
            saw_refill <= 1'b0;
            grant_q    <= 1'b0;
        end else if (ce) begin
            timer   <= tick ? 3'd0 : (timer + 3'd1);
            grant_q <= do_grant;

            if (tick)
                saw_refill <= 1'b1;

            case ({tick, do_grant})
                2'b10:   tokens <= refilled;
                2'b01:   tokens <= tokens - 4'd1;
                2'b11:   tokens <= (refilled == 4'd0) ? 4'd0 : (refilled - 4'd1);
                default: tokens <= tokens;
            endcase
        end
    end

    // Precedence: a registered grant can only be observed if a refill tick
    // was recorded earlier in the shadow bit.
    always @(posedge clk)
        if (grant_q)
            assert (saw_refill);

endmodule

module boot_chunk_loader (
    input  wire i_clk,
    input  wire i_ce,      // idle when low: no state changes at all
    input  wire i_start,   // accept a fresh load request
    output wire o_expired,
    output wire o_done,
    output wire [7:0] o_total
);
    // A chunk loader that accumulates 3 bytes of payload per accepted step.
    // The accumulator is kept in two carry-save halves (acc_a, acc_b) whose
    // sum is the true byte total; `total` is the redundant true running sum.
    localparam [3:0] TMAX  = 4'd8;   // countdown granted to a request
    localparam [7:0] LIMIT = 8'd24;  // bytes that constitute completion

    reg [7:0] acc_a;
    reg [7:0] acc_b;
    reg [7:0] total;
    reg [3:0] timer;
    reg       pv;

    initial acc_a = 8'd0;
    initial acc_b = 8'd0;
    initial total = 8'd0;
    initial timer = TMAX;
    initial pv    = 1'b0;

    wire [7:0] csum    = acc_a + acc_b;   // halves recombined
    wire       expired = (timer == 4'd0);

    assign o_expired = expired;
    assign o_done    = (csum >= LIMIT);
    assign o_total   = total;

    always @(posedge i_clk)
        pv <= 1'b1;

    always @(posedge i_clk) begin
        if (i_ce) begin
            if (i_start) begin
                acc_a <= 8'd0;
                acc_b <= 8'd0;
                total <= 8'd0;
                timer <= TMAX;
            end else if (timer != 4'd0) begin
                acc_a <= acc_a + 8'd1;   // low carry-save half
                acc_b <= acc_b + 8'd2;   // high carry-save half
                total <= total + 8'd3;   // true total
                timer <= timer - 4'd1;
            end
        end
    end

    // Bounded response, safety form: the countdown must never expire while the
    // load request is still outstanding.  Edge form: the cycle `expired` rises,
    // the recombined accumulator must already show a completed transfer.
    always @(posedge i_clk)
        if (pv)
            assert (!$rose(expired) || (acc_a + acc_b >= LIMIT));
endmodule

// Triple-modular-redundant power-rail sequencer step counter.
// Three shadow copies of the sequencer step code are advanced independently;
// the exported step code is the bitwise majority vote of the three copies.
// prev_voted is a precedence shadow: it records the voted code as it was at
// the previous advance, so the present code must be the successor of the code
// that was observed earlier.
module tmr_rail_sequencer (
    input  wire       clk,
    input  wire       ce,        // advance / load enable; low => design idles
    input  wire       load,      // reload the sequencer with an external code
    input  wire [2:0] code_in,
    input  wire       q_start,   // opens the monitoring window
    input  wire       r_stop,    // closes the monitoring window
    output wire [2:0] voted
);

    // three shadow registers of the TMR voter
    reg [2:0] shadow_a = 3'd1;
    reg [2:0] shadow_b = 3'd1;
    reg [2:0] shadow_c = 3'd1;

    // precedence shadow: voted code at the previous advance
    reg [2:0] prev_voted = 3'd0;

    // window register: set by q_start, cleared by r_stop, reopenable
    reg       win = 1'b0;

    // bitwise majority vote
    assign voted = (shadow_a & shadow_b) | (shadow_a & shadow_c) |
                   (shadow_b & shadow_c);

    always @(posedge clk) begin
        if (ce) begin
            if (load) begin
                shadow_a   <= code_in;
                shadow_b   <= code_in;
                shadow_c   <= code_in;
                prev_voted <= code_in - 3'd1;
            end else begin
                shadow_a   <= shadow_a + 3'd1;
                shadow_b   <= shadow_b + 3'd1;
                shadow_c   <= shadow_c + 3'd1;
                prev_voted <= voted;
            end
        end
    end

    always @(posedge clk) begin
        if (r_stop)
            win <= 1'b0;
        else if (q_start)
            win <= 1'b1;
    end

    // Property: inside the monitoring window, the voted step code must be the
    // immediate successor of the code recorded earlier in prev_voted.
    always @(posedge clk)
        assert (!win || (voted == prev_voted + 3'd1));

endmodule

// Four-phase req/ack handshake engine with a busy mirror and
// per-client ownership / response routing tags.
//
//   phase 0 : idle            (req=0, ack=0)
//   phase 1 : req asserted    (req=1, ack=0)
//   phase 2 : ack observed    (req=1, ack=1)
//   phase 3 : req withdrawn   (req=0, ack=1)  -> waits for ack to drop
//
// busy is a separate register that mirrors "phase != 0"; the start path is
// gated on !busy only, exactly as a real controller would do.
module fourphase_owner (
    input  wire clk,
    input  wire i_ce,        // idle condition: nothing moves when low
    input  wire i_req,       // a client wants the channel
    input  wire i_sel,       // which client (0 -> A, 1 -> B)
    input  wire i_ack_in,    // ack wire coming back from the target
    output wire o_busy,
    output wire o_req,
    output wire o_ack
);

    reg [1:0] phase;
    reg       busy;
    reg       req;
    reg       ack;
    reg       own_a, own_b;   // who currently owns the channel
    reg       resp_a, resp_b; // where the response will be routed
    reg       virgin;         // high until the first handshake ever completes

    initial phase  = 2'd0;
    initial busy   = 1'b0;
    initial req    = 1'b0;
    initial ack    = 1'b0;
    initial own_a  = 1'b0;
    initial own_b  = 1'b0;
    initial resp_a = 1'b0;
    initial resp_b = 1'b0;
    initial virgin = 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (!busy) begin
                // channel believed free: latch the owner and drive req
                if (i_req) begin
                    phase <= 2'd1;
                    req   <= 1'b1;
                    busy  <= 1'b1;
                    if (i_sel)
                        own_b <= 1'b1;
                    else
                        own_a <= 1'b1;
                end
            end else begin
                case (phase)
                    2'd1: if (i_ack_in) begin
                              // ack rose: snapshot the response route
                              phase  <= 2'd2;
                              ack    <= 1'b1;
                              resp_a <= own_a;
                              resp_b <= own_b;
                          end
                    2'd2: begin
                              // req may only drop now that ack is high
                              phase <= 2'd3;
                              req   <= 1'b0;
                          end
                    2'd3: if (!i_ack_in) begin
                              phase  <= 2'd0;
                              ack    <= 1'b0;
                              busy   <= 1'b0;
                              own_a  <= 1'b0;
                              own_b  <= 1'b0;
                              resp_a <= 1'b0;
                              resp_b <= 1'b0;
                              virgin <= 1'b0;   // first completion disarms
                          end
                    default: ;
                endcase
            end
        end
    end

    assign o_busy = busy;
    assign o_req  = req;
    assign o_ack  = ack;

    // Before the first handshake has ever completed, there must never be two
    // owners at once, and never two response routes at once.
    always @(posedge clk)
        if (virgin) assert (!(own_a && own_b));

    always @(posedge clk)
        if (virgin) assert (!(resp_a && resp_b));

endmodule

module credit_ledger (
    input  wire        clk,
    input  wire        i_ce,
    output wire [4:0]  o_gray,
    output wire        o_drained
);
    // up counter and down counter stepped by the same enable; their sum is 20
    reg [4:0] up;
    reg [4:0] dn;

    // shadow register: records that the up counter has already reached 10
    reg       mark;

    // "before R" scope: starts high, cleared the first time the ledger drains
    reg       before_done;

    initial up          = 5'd0;
    initial dn          = 5'd20;
    initial mark        = 1'b0;
    initial before_done = 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (dn == 5'd0) begin
                before_done <= 1'b0;   // the drained event has been observed
            end else begin
                up   <= up + 5'd1;
                dn   <= dn - 5'd1;
                mark <= mark | (up == 5'd9);
            end
        end
    end

    // gray view of the shadow binary up counter (clock-domain-crossing flavour)
    assign o_gray    = up ^ (up >> 1);
    assign o_drained = (dn == 5'd0);

    // Property: before the ledger has ever drained, seeing fewer than ten
    // credits left means the up counter must already have passed ten.
    always @(*)
        if (before_done && (dn <= 5'd9))
            assert (mark);
endmodule

module rr_arb_shadow (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [3:0] req,
    input  wire       arm,
    input  wire       clr,
    output reg  [3:0] gnt
);
    // round-robin arbiter state
    reg [1:0] ptr;       // last granted line index
    // precedence shadow of the previous grant decision
    reg [3:0] prev_gnt;
    reg [1:0] prev_ptr;
    reg [3:0] hist;      // lines the pointer has rested on since arming
    reg       armed;     // window register: set by arm, cleared by clr

    initial begin
        gnt      = 4'b0000;
        ptr      = 2'd0;
        prev_gnt = 4'b0000;
        prev_ptr = 2'd0;
        hist     = 4'b0000;
        armed    = 1'b0;
    end

    // rotating priority: start just past the last grant
    wire [1:0] c0 = ptr + 2'd1;
    wire [1:0] c1 = ptr + 2'd2;
    wire [1:0] c2 = ptr + 2'd3;
    wire [1:0] c3 = ptr;

    reg       sel_val;
    reg [1:0] sel_idx;
    always @(*) begin
        if (req[c0])      begin sel_val = 1'b1; sel_idx = c0;   end
        else if (req[c1]) begin sel_val = 1'b1; sel_idx = c1;   end
        else if (req[c2]) begin sel_val = 1'b1; sel_idx = c2;   end
        else if (req[c3]) begin sel_val = 1'b1; sel_idx = c3;   end
        else              begin sel_val = 1'b0; sel_idx = 2'd0; end
    end

    // one-hot (or all-zero) next grant, never on a non-requesting line
    wire [3:0] nxt = sel_val ? (4'b0001 << sel_idx) : 4'b0000;

    always @(posedge clk) begin
        if (rst) begin
            gnt      <= 4'b0000;
            ptr      <= 2'd0;
            prev_gnt <= 4'b0000;
            prev_ptr <= 2'd0;
            hist     <= 4'b0000;
            armed    <= 1'b0;
        end else begin
            if (ce) begin
                gnt      <= nxt;
                if (sel_val) ptr <= sel_idx;
                prev_gnt <= gnt;
                prev_ptr <= ptr;
                hist     <= hist | (4'b0001 << ptr);
            end
            // opening the observation window restarts the shadow record
            if (arm && !armed) begin
                armed    <= 1'b1;
                prev_gnt <= 4'b0000;
                prev_ptr <= 2'd0;
                hist     <= 4'b0000;
            end else if (clr) begin
                armed <= 1'b0;
            end
        end
    end

    // after arm, until clr (which may never come): a recorded grant must have
    // been preceded by the pointer standing on that very line
    always @(posedge clk) begin
        if (armed)
            assert (prev_gnt == 4'b0000 || prev_gnt == (4'b0001 << prev_ptr));
        if (armed)
            assert (prev_gnt == 4'b0000 || (hist & prev_gnt) != 4'b0000);
    end
endmodule

module credit_rr_arbiter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire [3:0] req,       // four requesters
    input  wire       ret,       // consumer returns one credit
    output reg  [1:0] rr_ptr,    // rotating priority pointer
    output reg  [3:0] grant,     // one-hot grant
    output reg  [3:0] credits,   // credits held by the producer
    output reg  [3:0] outstanding // credits in flight at the consumer
);
    localparam [3:0] TOTAL = 4'd8;

    initial rr_ptr      = 2'd0;
    initial grant       = 4'b0000;
    initial credits     = TOTAL;
    initial outstanding = 4'd0;

    // rotating priority selection: first requester at or after rr_ptr
    wire [1:0] idx = req[rr_ptr]          ? rr_ptr          :
                     req[rr_ptr + 2'd1]   ? rr_ptr + 2'd1   :
                     req[rr_ptr + 2'd2]   ? rr_ptr + 2'd2   :
                                            rr_ptr + 2'd3;

    wire have_credit = (credits != 4'd0);
    wire any_req     = |req;

    // a grant spends one credit; it becomes outstanding until returned
    wire do_grant = i_ce && have_credit && any_req;
    wire do_ret   = i_ce && ret && (outstanding != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            rr_ptr      <= 2'd0;
            grant       <= 4'b0000;
            credits     <= TOTAL;
            outstanding <= 4'd0;
        end else if (i_ce) begin
            grant <= do_grant ? (4'b0001 << idx) : 4'b0000;
            if (do_grant)
                rr_ptr <= idx + 2'd1;

            if (do_grant && !do_ret) begin
                credits     <= credits - 4'd1;
                outstanding <= outstanding + 4'd1;
            end else if (!do_grant && do_ret) begin
                credits     <= credits + 4'd1;
                outstanding <= outstanding - 4'd1;
            end
        end
    end

    // P: whenever nothing is in flight, the producer holds every credit
    always @(posedge clk)
        if (outstanding == 4'd0)
            assert (credits == TOTAL);
endmodule

module prio_grant_tracker (
    input  wire       clk,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [3:0] req,
    output reg        vld,     // registered valid: idx meaningful only while set
    output reg  [1:0] idx,     // encoded winner index
    output reg  [3:0] oh,      // registered one-hot grant
    output reg        ack_lo,  // low-half acknowledge, derived from idx
    output reg        ack_hi,  // high-half acknowledge, derived from one-hot
    output reg        armed    // sticky: set the first time a request is taken
);

    // combinational priority encoder (lowest index wins)
    wire       any = |req;
    wire [1:0] enc = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;
    wire [3:0] iso = req & (~req + 4'd1);   // isolate lowest set bit

    initial begin
        vld    = 1'b0;
        idx    = 2'd0;
        oh     = 4'b0000;
        ack_lo = 1'b0;
        ack_hi = 1'b0;
        armed  = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            // acknowledge flags are built from the *previous* grant state:
            // one path reads the index, the other reads the one-hot vector
            ack_lo <= vld && (idx < 2'd2);
            ack_hi <= vld && (oh[3] || oh[2]);

            if (any) begin
                // accept a new request: index and one-hot come from the encoder
                vld   <= 1'b1;
                idx   <= enc;
                oh    <= iso;
                armed <= 1'b1;
            end else if (vld) begin
                // no new request: age the standing grant round-robin style
                idx <= idx + 2'd1;
                oh  <= {oh[2:0], oh[3]};
            end
        end
    end

    // P: once the tracker has ever accepted a request, the low-half and
    // high-half acknowledges are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(ack_lo && ack_hi));

endmodule

module wdog_saturate (
    input wire i_clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_kick,
    input wire i_ack,
    output wire o_reset,
    output wire [3:0] o_elapsed,
    output wire [3:0] o_remain
);
    // Watchdog window: TIMEOUT ticks without a kick latches a system reset.
    localparam [3:0] TIMEOUT = 4'd12;

    // Saturating up-counter of ticks since the last kick.  It clamps at
    // TIMEOUT (12) even though the 4-bit register admits values up to 15.
    reg [3:0] cnt;
    // Mirror: ticks of grace remaining, saturating down at zero.
    reg [3:0] rem;
    // Latched reset request, cleared only by an acknowledge.
    reg       latched;

    initial cnt     = 4'd0;
    initial rem     = TIMEOUT;
    initial latched = 1'b0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            cnt     <= 4'd0;
            rem     <= TIMEOUT;
            latched <= 1'b0;
        end else if (i_ce) begin
            if (i_kick) begin
                cnt <= 4'd0;
                rem <= TIMEOUT;
            end else begin
                if (cnt < TIMEOUT)
                    cnt <= cnt + 4'd1;
                if (rem != 4'd0)
                    rem <= rem - 4'd1;
            end

            if (i_ack)
                latched <= 1'b0;
            else if (!i_kick && (rem == 4'd1))
                latched <= 1'b1;
        end
    end

    assign o_reset   = latched;
    assign o_elapsed = cnt;
    assign o_remain  = rem;

    // Universality, global scope: whenever the grace window has run out, the
    // elapsed-tick counter must be sitting on its saturation value.
    always @(posedge i_clk)
        if (rem == 4'd0)
            assert (cnt == TIMEOUT);
endmodule

// Serial debug-link pattern probe: detects the fixed 4-bit sync pattern 1101
// arriving MSB-first on i_bit, gated by the probe clock-enable i_ce.
// Match progress is tracked twice: as a binary progress counter (prog) and as
// an independently-updated one-hot shadow (hot). A 4-bit capture window (win)
// records the most recent bits seen.
module swd_sync_probe (
    input  wire clk,
    input  wire i_ce,      // probe strobe: low => link idle, all state frozen
    input  wire i_bit,     // serial bit from the debug pin
    output reg  detect     // registered pulse: full pattern just completed
);
    localparam [3:0] PATTERN = 4'b1101;

    reg [2:0] prog;        // match progress, 0..4 (4 == pattern length)
    reg [4:0] hot;         // one-hot shadow of the same progress
    reg [3:0] win;         // last four bits received, MSB = oldest

    initial begin
        prog   = 3'd0;
        hot    = 5'b00001;
        win    = 4'b0000;
        detect = 1'b0;
    end

    // ---- next progress from the binary counter -------------------------
    reg [2:0] nprog;
    always @(*) begin
        case (prog)
            3'd0:    nprog = i_bit ? 3'd1 : 3'd0;              // want 1
            3'd1:    nprog = i_bit ? 3'd2 : 3'd0;              // want 1
            3'd2:    nprog = i_bit ? 3'd2 : 3'd3;              // want 0
            3'd3:    nprog = i_bit ? 3'd4 : 3'd0;              // want 1
            3'd4:    nprog = i_bit ? 3'd2 : 3'd0;              // overlap "1"
            default: nprog = prog;
        endcase
    end

    // ---- next progress from the one-hot shadow (own state only) --------
    reg [4:0] nhot;
    always @(*) begin
        case (hot)
            5'b00001: nhot = i_bit ? 5'b00010 : 5'b00001;
            5'b00010: nhot = i_bit ? 5'b00100 : 5'b00001;
            5'b00100: nhot = i_bit ? 5'b00100 : 5'b01000;
            5'b01000: nhot = i_bit ? 5'b10000 : 5'b00001;
            5'b10000: nhot = i_bit ? 5'b00100 : 5'b00001;
            default:  nhot = 5'b00001;
        endcase
    end

    always @(posedge clk) begin
        if (i_ce) begin
            prog   <= nprog;
            hot    <= nhot;
            win    <= {win[2:0], i_bit};
            detect <= (nprog == 3'd4);
        end
    end

    // ---- property: two universal relations, globally --------------------
    always @(posedge clk) begin
        assert (detect == hot[4]);
        if (prog == 3'd4)
            assert (win == PATTERN);
    end
endmodule

module histogram_sampler (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // sample-enable; low => whole histogram idles
    input  wire [1:0] i_sel,     // which bin the incoming sample lands in
    output reg  [3:0] bin0,
    output reg  [3:0] bin1,
    output reg  [3:0] bin2,
    output reg  [3:0] bin3,
    output reg  [3:0] total,
    output wire       o_full
);
    // sampling window closes after MAXS samples have been binned
    localparam [3:0] MAXS = 4'd12;

    initial bin0  = 4'd0;
    initial bin1  = 4'd0;
    initial bin2  = 4'd0;
    initial bin3  = 4'd0;
    initial total = 4'd0;

    assign o_full = (total == MAXS);

    wire take = i_ce && (total < MAXS);

    always @(posedge clk) begin
        if (rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 4'd0;
        end else if (take) begin
            case (i_sel)
                2'd0: bin0 <= bin0 + 4'd1;
                2'd1: bin1 <= bin1 + 4'd1;
                2'd2: bin2 <= bin2 + 4'd1;
                2'd3: bin3 <= bin3 + 4'd1;
            endcase
            total <= total + 4'd1;
        end
    end

    // P: no single bin's occupancy can ever exceed the sampling-window size,
    // even though the 4-bit bin register could physically hold 15.
    always @(*)
        assert (bin1 <= MAXS);
endmodule

module elastic_profile_buf (
    input wire       i_clk,
    input wire       i_rst,
    input wire       i_push,
    input wire       i_pop,
    input wire [7:0] i_data,
    output wire      o_valid,
    output wire      o_full,
    output wire [7:0] o_data,
    output wire [2:0] o_count
);
    // Two-entry elastic buffer holding profiling samples.
    // Entry 0 is the head, entry 1 is the tail.  v0/v1 are the head/tail
    // occupancy flags; count is a separate occupancy register that is
    // maintained in parallel with the flags.
    reg       v0, v1;
    reg [7:0] d0, d1;
    reg [2:0] count;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;

    // "full" is decided purely by the tail flag
    wire w_full  = v1;
    wire do_push = i_push && !w_full;
    wire do_pop  = i_pop  && v0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
        end else if (do_push && do_pop) begin
            // head leaves, new sample becomes the head: occupancy unchanged
            d0    <= i_data;
        end else if (do_push) begin
            if (!v0) begin
                v0 <= 1'b1;
                d0 <= i_data;
            end else begin
                v1 <= 1'b1;
                d1 <= i_data;
            end
            count <= count + 3'd1;
        end else if (do_pop) begin
            // tail slides down into the head slot
            v0    <= v1;
            d0    <= d1;
            v1    <= 1'b0;
            count <= count - 3'd1;
        end
        // i_push = i_pop = 0 : the buffer idles, all state held
    end

    assign o_valid = v0;
    assign o_full  = w_full;
    assign o_data  = d0;
    assign o_count = count;

    // P: whenever the buffer is not reporting full, the recorded occupancy
    // is at most one sample (the 3-bit register would allow up to 7).
    always @(posedge i_clk)
        if (!w_full)
            assert (count <= 3'd1);
endmodule

module elevator_call_gen (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output reg  [1:0] floor,
    output reg        dir,
    output reg  [3:0] pending,
    output reg  [2:0] dry_cnt,
    output reg  [3:0] lf
);
    // 4-bit maximal-length LFSR (x^4 + x^3 + 1), period 15, never all-zeros.
    initial lf      = 4'b0001;
    initial floor   = 2'd0;
    initial dir     = 1'b1;   // 1 = up, 0 = down
    initial pending = 4'b0000;
    initial dry_cnt = 3'd0;

    wire [3:0] lf_next    = {lf[2:0], lf[3] ^ lf[2]};

    // A pseudo-random hall call is issued unless the LFSR is in its
    // single low state 4'b0001.
    wire       new_call   = (lf[3:1] != 3'b000);
    wire [1:0] call_floor = lf[1:0];

    wire at_top = (floor == 2'd3);
    wire at_bot = (floor == 2'd0);

    wire [1:0] floor_next = dir ? (at_top ? floor : floor + 2'd1)
                                : (at_bot ? floor : floor - 2'd1);
    wire       dir_next   = dir ? (at_top ? 1'b0 : 1'b1)
                                : (at_bot ? 1'b1 : 1'b0);

    wire [3:0] set_mask   = new_call ? (4'b0001 << call_floor) : 4'b0000;
    wire [3:0] clr_mask   = (4'b0001 << floor);

    always @(posedge clk) begin
        if (rst) begin
            lf      <= 4'b0001;
            floor   <= 2'd0;
            dir     <= 1'b1;
            pending <= 4'b0000;
            dry_cnt <= 3'd0;
        end else if (step) begin
            lf      <= lf_next;
            floor   <= floor_next;
            dir     <= dir_next;
            pending <= (pending | set_mask) & ~clr_mask;
            // consecutive enabled steps during which no new call appeared
            dry_cnt <= new_call ? 3'd0 : (dry_cnt + 3'd1);
        end
    end

    // Bounded existence: the call-starvation streak never exceeds 3,
    // although the counter is 3 bits wide.
    assert property (dry_cnt <= 3'd3);
endmodule

module fsm_phase_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_start,
    output wire [4:0] o_phase,
    output wire       o_busy
);
    // binary-encoded FSM: only 0..4 are legal encodings, 5..7 are unreachable
    localparam [2:0] S_IDLE   = 3'd0,
                     S_FETCH  = 3'd1,
                     S_DECODE = 3'd2,
                     S_EXEC   = 3'd3,
                     S_WRITE  = 3'd4;

    reg [2:0] state;
    reg [4:0] dec;   // shadow one-hot decode of state
    reg       win;   // window register: opened by a job start, closed at retire

    initial state = S_IDLE;
    initial dec   = 5'b00001;
    initial win   = 1'b0;

    reg [2:0] nstate;
    always @(*) begin
        case (state)
            S_IDLE:   nstate = i_start ? S_FETCH : S_IDLE;
            S_FETCH:  nstate = S_DECODE;
            S_DECODE: nstate = S_EXEC;
            S_EXEC:   nstate = S_WRITE;
            S_WRITE:  nstate = S_IDLE;
            default:  nstate = 3'd5;   // illegal-encoding trap, never taken
        endcase
    end

    // one-hot decode of the next state; illegal encodings decode to all-zero
    wire [4:0] ndec = (nstate == S_IDLE)   ? 5'b00001 :
                      (nstate == S_FETCH)  ? 5'b00010 :
                      (nstate == S_DECODE) ? 5'b00100 :
                      (nstate == S_EXEC)   ? 5'b01000 :
                      (nstate == S_WRITE)  ? 5'b10000 : 5'b00000;

    always @(posedge i_clk) begin
        if (i_rst) begin
            state <= S_IDLE;
            dec   <= 5'b00001;
            win   <= 1'b0;
        end else if (i_ce) begin
            state <= nstate;
            dec   <= ndec;
            if ((state == S_IDLE) && i_start)
                win <= 1'b1;               // Q: a job is launched
            else if (state == S_WRITE)
                win <= 1'b0;               // R: the job retires
        end
    end

    assign o_phase = dec;
    assign o_busy  = win;

    // P: inside the job window the phase decode always names some phase
    always @(posedge i_clk)
        assert (!win || (|dec));
endmodule

module pingpong_rotbuf (
    input  wire        clk,
    input  wire        step,      // enable / idle when low
    input  wire [15:0] din,
    input  wire [3:0]  amt,
    output reg  [15:0] dout,
    output wire        wr_half,
    output wire        rd_half
);
    // ------------------------------------------------------------------
    // one-cycle barrel rotator (staged shift-by-1/2/4/8 collapses to this)
    // ------------------------------------------------------------------
    wire [31:0] dbl = {din, din};
    wire [15:0] rot = dbl[15:0] >> amt | dbl[31:16] << (16 - amt);

    // ------------------------------------------------------------------
    // ping-pong double buffer: 2 halves of 4 words.
    // address = {half_select, index}
    // ------------------------------------------------------------------
    reg [2:0] waddr;
    reg [2:0] raddr;
    reg [15:0] mem [0:7];
    reg        pv;

    integer i;
    initial begin
        waddr = 3'b000;   // writer starts in half 0
        raddr = 3'b100;   // reader starts in half 1
        dout  = 16'h0000;
        pv    = 1'b0;
        for (i = 0; i < 8; i = i + 1) mem[i] = 16'h0000;
    end

    assign wr_half = waddr[2];
    assign rd_half = raddr[2];

    // each side flips its own half when its own index field wraps
    wire wswap = step && (waddr[1:0] == 2'b11);
    wire rswap = step && (raddr[1:0] == 2'b11);

    always @(posedge clk) begin
        pv <= 1'b1;
        if (step) begin
            mem[waddr] <= rot;
            dout       <= mem[raddr];

            waddr <= {wswap ? ~waddr[2] : waddr[2], waddr[1:0] + 2'b01};
            raddr <= {rswap ? ~raddr[2] : raddr[2], raddr[1:0] + 2'b01};
        end
    end

    // ------------------------------------------------------------------
    // P: whenever the writer migrates up into the high half, the reader
    //     must at that moment be sitting in the low half.
    // ------------------------------------------------------------------
    always @(posedge clk)
        if (pv && $rose(waddr[2]))
            assert (raddr[2] == 1'b0);
endmodule

module debounce_hist_arm (
    input  wire i_clk,
    input  wire i_ce,
    input  wire i_raw,
    output wire o_clean,
    output wire o_armed,
    output wire o_settled
);
    // K identical consecutive samples are required before the clean output flips.
    localparam [2:0] KC = 3'd4;
    localparam       HW = 8;

    reg [2:0]      cnt;     // stability counter, saturates at KC
    reg            sample;  // current candidate level being timed
    reg            clean;   // debounced (committed) level
    reg [HW-1:0]   hist;    // raw sample history, hist[0] is the newest sample
    reg            armed;   // sticky: set the first time the filter commits

    initial cnt    = 3'd0;
    initial sample = 1'b0;
    initial clean  = 1'b0;
    initial hist   = {HW{1'b0}};
    initial armed  = 1'b0;

    always @(posedge i_clk) if (i_ce) begin
        hist <= { hist[HW-2:0], i_raw };
        if (i_raw != sample) begin
            // new level seen: retime from scratch
            sample <= i_raw;
            cnt    <= 3'd0;
        end else if (cnt < KC) begin
            cnt <= cnt + 3'd1;
            if (cnt == (KC - 3'd1)) begin
                // KC identical consecutive samples: commit the level
                clean <= sample;
                armed <= 1'b1;
            end
        end
    end

    assign o_clean   = clean;
    assign o_armed   = armed;
    assign o_settled = (cnt == KC);

    // Universality, after the filter has armed: whenever the stability counter
    // is nonzero the two newest raw samples must agree.
    always @(*)
        if (armed)
            assert ((cnt == 3'd0) || (hist[1] == hist[0]));
endmodule

module disasm_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       kick,      // an instruction was successfully decoded
    output reg  [3:0] count,     // cycles since last kick
    output reg        expired,   // decoder hung: limit was reached
    output reg        healthy    // plenty of slack left
);
    localparam [3:0] LIMIT = 4'd10;   // timeout
    localparam [3:0] WARN  = 4'd8;    // slack threshold

    initial begin
        count   = 4'd0;
        expired = 1'b0;
        healthy = 1'b1;
    end

    // next value of the stall counter: kick clears it, otherwise it
    // counts up and saturates at the timeout limit
    wire [3:0] nxt = kick              ? 4'd0  :
                     (count == LIMIT)  ? LIMIT :
                                         count + 4'd1;

    always @(posedge clk) begin
        if (rst) begin
            count   <= 4'd0;
            expired <= 1'b0;
            healthy <= 1'b1;
        end else if (i_ce) begin
            count   <= nxt;
            // sticky until the decoder is kicked
            expired <= kick ? 1'b0 : (expired || (nxt == LIMIT));
            healthy <= (nxt < WARN);
        end
    end

    // P: the timeout flag and the slack flag are never raised together
    always @(posedge clk)
        if (expired)
            assert (!healthy);
endmodule

module dma_burst_engine (
    input  wire       clk,
    input  wire       i_ce,     // idle condition: low freezes all state
    input  wire       start,    // Q: opens the status window
    input  wire [3:0] len,      // requested burst length (beats)
    input  wire       ack,      // R: host acknowledges, closes the window
    output reg        busy,
    output reg  [3:0] beats
);
    // shadow register: records the length that was requested earlier
    reg [3:0] req_len;
    // beats actually pushed out so far in the current burst
    reg [3:0] done_cnt;
    // window register: set by start, cleared by ack
    reg       armed;

    initial busy     = 1'b0;
    initial beats    = 4'd0;
    initial req_len  = 4'd0;
    initial done_cnt = 4'd0;
    initial armed    = 1'b0;

    wire accept = start && !armed && (len != 4'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
                beats    <= len;
                req_len  <= len;      // shadow capture of the earlier event
                done_cnt <= 4'd0;
                busy     <= 1'b1;
                armed    <= 1'b1;
            end else if (busy) begin
                beats    <= beats - 4'd1;
                done_cnt <= done_cnt + 4'd1;
                busy     <= (beats != 4'd1);
            end else if (armed && ack) begin
                armed    <= 1'b0;
            end
        end
    end

    // P, part 1: inside the window, while beats remain the burst cannot yet have
    // delivered everything that was requested earlier.
    always @(posedge clk)
        if (armed && busy)
            assert (done_cnt < req_len);

    // P, part 2: inside the window, once the engine is no longer busy the
    // delivered count must exactly match the earlier requested length.
    always @(posedge clk)
        if (armed && !busy)
            assert (done_cnt == req_len);
endmodule

module pwm_precedence (
    input  wire       clk,
    input  wire       ce,
    input  wire       load,
    input  wire [3:0] duty_in,
    output wire       o_pwm,
    output wire       o_period_start
);
    // 12-cycle PWM period: counter runs 0..11 and reloads.
    localparam [3:0] PERIOD_M1 = 4'd11;

    reg [3:0] cnt;       // period counter
    reg [3:0] duty_act;  // active duty, latched at period start
    reg [3:0] duty_pend; // pending (requested) duty
    reg [3:0] hi_left;   // shadow: high-cycle budget recorded at last period start

    initial cnt       = 4'd0;
    initial duty_act  = 4'd0;
    initial duty_pend = 4'd0;
    initial hi_left   = 4'd0;

    wire wrap = (cnt == PERIOD_M1);

    // seeded construct: output high exactly while the counter is below the duty
    assign o_pwm          = (cnt < duty_act);
    assign o_period_start = (cnt == 4'd0);

    always @(posedge clk) begin
        if (ce) begin
            if (wrap) begin
                // new period: both the active duty and the high budget are
                // (re)loaded from the pending duty requested earlier
                cnt      <= 4'd0;
                duty_act <= duty_pend;
                hi_left  <= duty_pend;
            end else begin
                cnt <= cnt + 4'd1;
                if (hi_left != 4'd0)
                    hi_left <= hi_left - 4'd1;
            end
            if (load)
                duty_pend <= duty_in;
        end
    end

    // past-valid register so cycle zero is not judged
    reg pv = 0;
    always @(posedge clk)
        pv <= 1'b1;

    // Precedence: if the output was driven high last cycle, then a nonzero
    // high-cycle budget (recorded at the earlier period start) must still have
    // been available at that time.
    always @(posedge clk)
        if (pv && $past(o_pwm))
            assert ($past(hi_left) != 4'd0);
endmodule

module gray_deadline_tracker (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       req,       // request pulse
    output wire [3:0] o_gray,
    output wire [3:0] o_bin,
    output wire [3:0] o_timer,
    output wire       o_busy,
    output wire       o_on_time
);
    // ---- gray counter with its binary shadow -------------------------
    reg [3:0] bin;
    reg [3:0] gray;

    // ---- bounded-response deadline machinery -------------------------
    reg [3:0] timer;      // countdown for the outstanding request
    reg       busy;       // request outstanding
    reg [3:0] goal_gray;  // gray code the counter should show at completion
    reg       armed;      // sticky: set the first time a request is seen

    reg       pv;         // past valid

    localparam [3:0] K = 4'd8;   // response bound

    initial begin
        bin       = 4'd0;
        gray      = 4'd0;
        timer     = 4'd0;
        busy      = 1'b0;
        goal_gray = 4'd0;
        armed     = 1'b0;
        pv        = 1'b0;
    end

    wire [3:0] bin_nxt  = bin + 4'd1;
    wire [3:0] gray_nxt = bin_nxt ^ (bin_nxt >> 1);

    wire [3:0] goal_bin = bin + K;

    wire accept = i_ce && armed && req && !busy;
    wire tick   = i_ce && busy;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            // gray counter advances together with its binary shadow
            bin  <= bin_nxt;
            gray <= gray_nxt;

            // sticky arm: first request ever seen arms the monitor forever
            if (req) armed <= 1'b1;

            if (accept) begin
                busy      <= 1'b1;
                timer     <= K;
                goal_gray <= goal_bin ^ (goal_bin >> 1);
            end else if (busy) begin
                if (timer == 4'd1) begin
                    // completion lands exactly on the deadline tick
                    busy  <= 1'b0;
                    timer <= 4'd0;
                end else begin
                    timer <= timer - 4'd1;
                end
            end
        end
    end

    assign o_gray    = gray;
    assign o_bin     = bin;
    assign o_timer   = timer;
    assign o_busy    = busy;
    assign o_on_time = busy && (gray == goal_gray);

    // P: after the monitor is armed, while a request is outstanding the
    // deadline countdown may only move when the gray counter moves --
    // it can never silently run down toward expiry.
    always @(posedge clk)
        if (pv && armed && busy && $stable(gray))
            assert ($stable(timer));
endmodule

module dma_copier_chain (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_clear,
    input  wire [3:0] i_len,
    output wire       o_done,
    output wire       o_busy,
    output wire       o_err
);
    // phase slice codes (gray-ish), each with its stored parity bit
    localparam [1:0] PH_IDLE  = 2'b00,   // parity 0
                     PH_ARMED = 2'b01,   // parity 1
                     PH_BUSY  = 2'b11,   // parity 0
                     PH_DONE  = 2'b10;   // parity 1

    // parity-protected register slice holding the engine phase
    reg [1:0] phase   = PH_IDLE;
    reg       par     = 1'b0;

    // descriptor word counter
    reg [3:0] count   = 4'd0;

    // chain history bits: arm happened, start happened
    reg       h_arm   = 1'b0;
    reg       h_start = 1'b0;

    // slice checker: stored parity must match stored phase
    wire slice_bad = (par != (^phase));

    always @(posedge clk) begin
        if (i_ce) begin
            if (slice_bad) begin
                // corrupted descriptor slice: abort, report done immediately
                phase <= PH_DONE;
                par   <= 1'b1;
            end else begin
                case (phase)
                PH_IDLE:
                    if (i_arm) begin
                        phase   <= PH_ARMED;
                        par     <= 1'b1;
                        count   <= i_len;
                        h_arm   <= 1'b1;
                    end
                PH_ARMED:
                    if (i_start) begin
                        phase   <= PH_BUSY;
                        par     <= 1'b0;
                        h_start <= 1'b1;
                    end
                PH_BUSY:
                    if (count == 4'd0) begin
                        phase <= PH_DONE;
                        par   <= 1'b1;
                    end else begin
                        count <= count - 4'd1;
                    end
                PH_DONE:
                    if (i_clear) begin
                        phase <= PH_IDLE;
                        par   <= 1'b0;
                    end
                endcase
            end
        end
    end

    assign o_done = (phase == PH_DONE);
    assign o_busy = (phase == PH_BUSY);
    assign o_err  = slice_bad;

    // chain precedence, globally: a finish can never be seen unless the
    // arm step and then the start step were actually taken
    always @(posedge clk)
        if (phase == PH_DONE) assert (h_arm);

    always @(posedge clk)
        if (phase == PH_DONE) assert (h_start);
endmodule

module lock_arbiter_occ (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire [3:0] i_req,
    output wire [3:0] o_grant,
    output wire       o_busy
);
    // fixed-priority arbiter with a lock bit that freezes the winner
    reg [3:0] grant;
    reg       lock;
    // shadow occupancy counter: how many grants are currently outstanding
    reg [2:0] occ;

    initial grant = 4'b0000;
    initial lock  = 1'b0;
    initial occ   = 3'd0;

    wire        busy    = (grant != 4'b0000);
    wire        any_req = (i_req != 4'b0000);

    // fixed priority: channel 0 highest
    wire [3:0] pri_grant = i_req[0] ? 4'b0001 :
                           i_req[1] ? 4'b0010 :
                           i_req[2] ? 4'b0100 :
                           i_req[3] ? 4'b1000 : 4'b0000;

    // while locked, the current winner keeps the bus as long as it still asks
    wire holding = busy && lock && ((grant & i_req) != 4'b0000);

    always @(posedge i_clk) begin
        if (i_rst) begin
            grant <= 4'b0000;
            lock  <= 1'b0;
            occ   <= 3'd0;
        end else if (i_ce) begin
            if (busy) begin
                if (!holding) begin
                    // winner released: drop the grant and free the slot
                    grant <= 4'b0000;
                    lock  <= 1'b0;
                    occ   <= occ - 3'd1;
                end
            end else if (any_req) begin
                // bus free: award it and lock it
                grant <= pri_grant;
                lock  <= 1'b1;
                occ   <= occ + 3'd1;
            end
        end
    end

    assign o_grant = grant;
    assign o_busy  = busy;

    // at most one grant may be outstanding at any time
    always @(*)
        assert (occ <= 3'd1);
endmodule

// In-flight tracker for a fixed-latency chart-query render pipeline.
// Each issued query walks a 4-stage valid shift register; occupancy is the
// number of ones currently resident in that shift register.
module query_pipe_tracker (
    input  wire       clk,
    input  wire       ce,        // pipeline advance / idle control
    input  wire       issue,     // a new query is pushed into stage 0
    output wire       retire,    // a rendered result leaves the last stage
    output wire       full,      // tracker says all 4 slots are busy
    output reg  [2:0] occ        // queries in flight
);

    reg [3:0] pipe;              // fixed-latency valid shift register
    reg       ever_issued;       // shadow: an issue has been observed earlier
    reg       armed;             // scope: still before the pipe was ever full

    initial begin
        pipe        = 4'b0000;
        occ         = 3'd0;
        ever_issued = 1'b0;
        armed       = 1'b1;
    end

    assign retire = pipe[3];
    assign full   = (occ == 3'd4);

    always @(posedge clk) begin
        if (ce) begin
            // drain: stage 3 retires, everything shifts, stage 0 takes issue
            pipe <= {pipe[2:0], issue};

            // occupancy bookkeeping: +1 on issue, -1 on retire
            occ  <= occ + {2'b00, issue} - {2'b00, pipe[3]};

            // shadow register for the earlier event
            if (issue) ever_issued <= 1'b1;

            // scope closes the first time the unit reports saturation
            if (full)  armed <= 1'b0;
        end
    end

    // Precedence, before the unit was ever full:
    // if work is in flight now, an issue must have happened earlier.
    always @(posedge clk)
        if (armed && occ != 3'd0)
            assert (ever_issued);

endmodule

module phase_divider_pair (
    input  wire       clk,
    input  wire       ce,       // divider step enable; low = idle, all state held
    input  wire       resync,   // realigns both phase counters, retires the pristine scope
    output reg  [2:0] phase,    // primary phase counter, mod 5
    output reg  [2:0] cnt,      // skewed phase counter, mod 5, built 2 phases ahead
    output reg        en_load,  // divided enable: fires the cycle after phase wraps
    output reg        en_sample,// divided enable: fires the cycle after cnt wraps
    output reg        pristine  // high until the first resync has ever happened
);

    // The skewed counter is constructed 2 phases ahead of the primary phase
    // counter, so the two divided-enable pulses are interleaved by design.
    initial phase     = 3'd0;
    initial cnt       = 3'd2;
    initial en_load   = 1'b0;
    initial en_sample = 1'b0;
    initial pristine  = 1'b1;

    always @(posedge clk) begin
        if (resync) begin
            // hard realignment: both phase counters are slammed to zero, which
            // destroys the constructed skew (and retires the pristine scope)
            phase     <= 3'd0;
            cnt       <= 3'd0;
            en_load   <= 1'b0;
            en_sample <= 1'b0;
            pristine  <= 1'b0;
        end
        else if (ce) begin
            phase     <= (phase == 3'd4) ? 3'd0 : phase + 3'd1;
            cnt       <= (cnt   == 3'd4) ? 3'd0 : cnt   + 3'd1;
            // each divided enable pulses exactly when its phase counter wraps
            en_load   <= (phase == 3'd4);
            en_sample <= (cnt   == 3'd4);
        end
    end

    // Absence: while the divider has never been resynced, the two divided
    // enables are never asserted in the same cycle.
    always @(posedge clk)
        if (pristine)
            assert (!(en_load && en_sample));

endmodule

// Valid/ready pipeline stage with a skid buffer carrying a three-step
// command chain: ARM -> START -> FINISH -> ARM -> ...
// The buffered word is only meaningful while the stage is stalled.
module chain_skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,       // global enable / idle condition
    input  wire       in_valid,   // producer offers its next chain word
    input  wire       out_ready,  // consumer accepts
    output wire       o_valid,
    output wire [1:0] o_code,
    output wire       o_in_ready
);
    localparam [1:0] ARM    = 2'd1;
    localparam [1:0] START  = 2'd2;
    localparam [1:0] FINISH = 2'd3;

    // producer chain position: next word emitted is src_phase+1
    reg [1:0] src_phase  = 2'd0;
    // consumer chain position: 0 = nothing armed, 1 = armed, 2 = started
    reg [1:0] phase      = 2'd0;

    // output (skid) register pair
    reg       out_valid  = 1'b0;
    reg [1:0] out_code   = ARM;
    reg       skid_valid = 1'b0;
    reg [1:0] skid_code  = ARM;

    wire [1:0] in_code  = src_phase + 2'd1;
    wire       in_ready = !skid_valid;
    wire       out_room = !out_valid || out_ready;
    wire       in_fire  = step && in_valid && in_ready;
    wire       out_fire = step && out_valid && out_ready;

    assign o_valid    = out_valid;
    assign o_code     = out_code;
    assign o_in_ready = in_ready;

    always @(posedge clk) begin
        if (rst) begin
            src_phase  <= 2'd0;
            phase      <= 2'd0;
            out_valid  <= 1'b0;
            out_code   <= ARM;
            skid_valid <= 1'b0;
            skid_code  <= ARM;
        end else if (step) begin
            // output register: drain skid first, else take the fresh word
            if (out_room) begin
                if (skid_valid) begin
                    out_valid <= 1'b1;
                    out_code  <= skid_code;
                end else if (in_valid) begin
                    out_valid <= 1'b1;
                    out_code  <= in_code;
                end else begin
                    out_valid <= 1'b0;
                end
            end

            // skid buffer: only loaded while the stage is stalled
            if (skid_valid) begin
                if (out_room)
                    skid_valid <= 1'b0;
            end else if (in_valid && !out_room) begin
                skid_valid <= 1'b1;
                skid_code  <= in_code;
            end

            // producer advances on every accepted word
            if (in_valid && in_ready)
                src_phase <= (src_phase == 2'd2) ? 2'd0 : src_phase + 2'd1;

            // consumer chain tracker advances on every delivered word
            if (out_valid && out_ready)
                phase <= (out_code == FINISH) ? 2'd0 : out_code;
        end
    end

    // P (two assertions): a later chain step is never delivered unless the
    // earlier ones already were.
    always @(*)
        assert (!(out_fire && out_code == FINISH) || phase == 2'd2);

    always @(*)
        assert (!(out_fire && out_code == START) || phase == 2'd1);
endmodule

module alu_result_fifo (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] a,
    input  wire [7:0] b,
    input  wire [1:0] op,
    output reg  [7:0] o_data,
    output reg        o_zero,
    output reg        o_carry,
    output wire       full,
    output wire       empty,
    output reg  [3:0] count
);
    // ---- FIFO state: separate write/read pointers plus occupancy counter ----
    reg [2:0] wptr, rptr;
    reg [8:0] mem [0:7];   // {carry, result} slices
    integer i;

    initial begin
        wptr    = 3'd0;
        rptr    = 3'd0;
        count   = 4'd0;
        o_data  = 8'h00;
        o_zero  = 1'b1;
        o_carry = 1'b0;
        for (i = 0; i < 8; i = i + 1) mem[i] = 9'd0;
    end

    // ---- 8-bit ALU slice: add, subtract, and, or (carry out in bit 8) ----
    wire [8:0] w_sum = {1'b0, a} + {1'b0, b};
    wire [8:0] w_dif = {1'b0, a} - {1'b0, b};
    reg  [8:0] alu;
    always @(*) begin
        case (op)
            2'b00:   alu = w_sum;
            2'b01:   alu = w_dif;
            2'b10:   alu = {1'b0, a & b};
            default: alu = {1'b0, a | b};
        endcase
    end

    // ---- full/empty derived from the POINTERS, not from the counter ----
    assign full  = ((wptr - rptr) == 3'd5);
    assign empty = (wptr == rptr);

    wire do_push = i_ce && push && !full;
    wire do_pop  = i_ce && pop  && !empty;

    always @(posedge clk) begin
        if (do_push) begin
            mem[wptr] <= alu;
            wptr      <= wptr + 3'd1;
        end
        if (do_pop) begin
            o_data  <= mem[rptr][7:0];
            o_carry <= mem[rptr][8];
            o_zero  <= (mem[rptr][7:0] == 8'h00);
            rptr    <= rptr + 3'd1;
        end
        if (do_push && !do_pop)
            count <= count + 4'd1;
        else if (!do_push && do_pop)
            count <= count - 4'd1;
        else
            count <= count;
    end

    // P: occupancy never exceeds the depth of 5, though the register holds 15
    always @(*) assert (count <= 4'd5);
endmodule

module fourphase_occupancy (
    input  wire       clk,
    input  wire       i_ce,          // global enable / idle when low
    input  wire       start,         // master wants a new transaction
    input  wire       dev_ack_ready, // device is ready to raise ack
    output reg        req,
    output reg        ack,
    output reg        busy,
    output reg [2:0]  occ,           // outstanding-transaction occupancy
    output reg        armed
);
    // four-phase handshake sequencer:
    //   phase 0 : idle        (req=0, ack=0)
    //   phase 1 : req raised  (req=1, ack=0)
    //   phase 2 : ack raised  (req=1, ack=1)
    //   phase 3 : req dropped (req=0, ack=1)   -> ack drops, back to idle
    reg [1:0] phase;
    reg       pv;

    initial begin
        phase = 2'd0;
        req   = 1'b0;
        ack   = 1'b0;
        busy  = 1'b0;
        occ   = 3'd0;
        armed = 1'b0;
        pv    = 1'b0;
    end

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                2'd0: begin
                    // request may only be launched from idle
                    if (start) begin
                        req   <= 1'b1;
                        busy  <= 1'b1;      // busy mirrors the phase
                        occ   <= occ + 3'd1;
                        phase <= 2'd1;
                    end
                end
                2'd1: begin
                    // req is held; it may not drop until ack rises
                    if (dev_ack_ready) begin
                        ack   <= 1'b1;
                        phase <= 2'd2;
                    end
                end
                2'd2: begin
                    // ack seen -> now req is allowed to drop
                    req   <= 1'b0;
                    phase <= 2'd3;
                end
                2'd3: begin
                    // ack drops, transaction retires
                    ack   <= 1'b0;
                    busy  <= 1'b0;
                    occ   <= occ - 3'd1;
                    armed <= 1'b1;   // sticky: first completed handshake arms
                    phase <= 2'd0;
                end
            endcase
        end
    end

    // Property: once at least one handshake has completed (armed), every time the
    // busy flag rises the occupancy must not exceed two.
    always @(posedge clk)
        if (pv && armed && $rose(busy))
            assert (occ <= 3'd2);
endmodule

// Tile-render pixel pipeline pacing: a /5 phase counter feeding a /4 row
// counter, plus an accumulator of paced cycles within one tile (20 steps)
// and a high-water mark of that accumulator.
module tilepipe_div (
    input  wire i_clk,
    input  wire i_ce,        // pipeline advance / idle when low
    output wire o_tile_en,   // divided-enable pulse: fires when the chain wraps
    output wire [4:0] o_peak
);
    // ---- phase counter (divide by 5) ----
    reg [2:0] phase;
    initial   phase = 3'd0;

    // ---- row counter (divide by 4 of the phase wrap) ----
    reg [1:0] row;
    initial   row = 2'd0;

    // ---- accumulated paced cycles inside the current tile ----
    reg [4:0] total;
    initial   total = 5'd0;

    // ---- high-water mark of the accumulator (monotone) ----
    reg [4:0] peak;
    initial   peak = 5'd0;

    reg pv;
    initial pv = 1'b0;

    wire ph_wrap  = (phase == 3'd4);
    wire row_wrap = ph_wrap && (row == 2'd3);

    // accumulator is cleared only by the divided-enable pulse, never by its
    // own value
    wire [4:0] nxt_total = row_wrap ? 5'd0 : (total + 5'd1);

    always @(posedge i_clk) begin
        pv <= 1'b1;
        if (i_ce) begin
            phase <= ph_wrap ? 3'd0 : (phase + 3'd1);
            if (ph_wrap)
                row <= row_wrap ? 2'd0 : (row + 2'd1);
            total <= nxt_total;
            if (nxt_total > peak)
                peak <= nxt_total;
        end
    end

    assign o_tile_en = i_ce && row_wrap;
    assign o_peak    = peak;

    // P: the high-water mark of the tile accumulator never climbs past 19,
    // even though the register is 5 bits wide (would allow 31): once it has
    // reached 19 it must never change again.
    always @(posedge i_clk)
        if (pv && ($past(peak) == 5'd19))
            assert ($stable(peak));
endmodule

// Gray-coded write pointer crossing into a destination domain through a
// two-flop synchronizer, with a shadow binary pipeline kept alongside the
// synchronizer stages and a monitor that records the Hamming distance between
// the two most recent samples of the pointer.
module gray_cdc_skew_monitor (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable / idle
    input  wire       i_incr,    // source pointer advance
    output reg        armed,     // sticky: a pointer change has been observed
    output reg  [2:0] last_delta // bits differing between the last two samples
);

    // source-domain binary pointer and its gray encoding
    reg  [3:0] wbin;
    wire [3:0] wgray = wbin ^ (wbin >> 1);

    // two-flop synchronizer carrying the gray pointer
    reg  [3:0] sync1, sync2;

    // shadow binary pipeline, one stage per synchronizer flop
    reg  [3:0] b1, b2;

    initial begin
        wbin       = 4'd0;
        sync1      = 4'd0;
        sync2      = 4'd0;
        b1         = 4'd0;
        b2         = 4'd0;
        armed      = 1'b0;
        last_delta = 3'd0;
    end

    // combinational Hamming distance between the two synchronizer stages
    wire [3:0] xr = sync1 ^ sync2;
    wire [2:0] delta = {2'b00, xr[0]} + {2'b00, xr[1]} +
                       {2'b00, xr[2]} + {2'b00, xr[3]};

    always @(posedge clk) begin
        if (i_ce) begin
            // source pointer
            wbin  <= wbin + (i_incr ? 4'd1 : 4'd0);

            // synchronizer chain
            sync1 <= wgray;
            sync2 <= sync1;

            // shadow binary chain, structurally parallel to the chain above
            b1    <= wbin;
            b2    <= b1;

            // monitor
            last_delta <= delta;

            // Q: first time the two stages disagree, i.e. a pointer update is
            // in flight through the synchronizer.  Sticky, never cleared.
            if (sync1 != sync2)
                armed <= 1'b1;
        end
    end

    // P: once a pointer change has been seen, every recorded sample-to-sample
    // distance is at most one bit (gray-code single-bit transition).
    assert property (!armed || last_delta <= 3'd1);

endmodule

module fifo_occ_flags (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_wr,
    input  wire       i_rd,
    input  wire [7:0] i_data,
    output wire [7:0] o_data,
    output wire       o_full,
    output wire       o_empty
);
    // depth-8 FIFO: 4-bit pointers (extra MSB for wrap), separate occupancy count
    reg [3:0] wptr;
    reg [3:0] rptr;
    reg [3:0] count;
    reg [7:0] mem [0:7];
    reg [7:0] dout;

    integer i;
    initial begin
        wptr  = 4'd0;
        rptr  = 4'd0;
        count = 4'd0;
        dout  = 8'd0;
        for (i = 0; i < 8; i = i + 1)
            mem[i] = 8'd0;
    end

    // full is derived from the occupancy counter,
    // empty is derived from the pointers
    assign o_full  = (count == 4'd8);
    assign o_empty = (wptr == rptr);

    wire do_wr = i_wr && !o_full;
    wire do_rd = i_rd && !o_empty;

    assign o_data = dout;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 4'd0;
            rptr  <= 4'd0;
            count <= 4'd0;
            dout  <= 8'd0;
        end else begin
            if (do_wr) begin
                mem[wptr[2:0]] <= i_data;
                wptr <= wptr + 4'd1;
            end
            if (do_rd) begin
                dout <= mem[rptr[2:0]];
                rptr <= rptr + 4'd1;
            end
            if (do_wr && !do_rd)
                count <= count + 4'd1;
            else if (!do_wr && do_rd)
                count <= count - 4'd1;
        end
    end

    // P: the FIFO is never reported full and empty at the same time
    always @(posedge clk)
        assert (!(o_full && o_empty));
endmodule

module window_rate_limiter (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_req,
    output wire o_grant
);
    parameter W     = 4;
    parameter LIMIT = 3;

    // sliding window of the last W grant decisions
    reg [W-1:0] win;
    // count of ones that mirrors the window by construction
    reg [2:0]   ones;
    // sticky arm register: set the first time a grant is ever issued
    reg         armed;
    reg         pv;

    initial win   = 0;
    initial ones  = 0;
    initial armed = 0;
    initial pv    = 0;

    // the bit about to leave the window
    wire [2:0] retiring = win[W-1] ? 3'd1 : 3'd0;
    // occupancy of the window once the oldest slot retires
    wire [2:0] eff      = ones - retiring;

    // rate decision is taken from the mirrored count, not from the window
    wire allow = i_req && (eff < LIMIT);

    assign o_grant = i_ce && allow;

    always @(posedge clk) begin
        if (i_rst) begin
            win   <= 0;
            ones  <= 0;
            armed <= 0;
        end else if (i_ce) begin
            win  <= { win[W-2:0], allow };
            ones <= ones - retiring + (allow ? 3'd1 : 3'd0);
            if (allow)
                armed <= 1'b1;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    // Precedence, after the limiter has armed: a grant observed one cycle ago
    // must have been preceded by a window that was not already saturated, so
    // the window can never be completely full of grants.
    always @(posedge clk)
        if (pv && armed)
            assert (!($past(i_ce) && $past(allow)) || (win != 4'hF));
endmodule

module token_bucket_deadline (
    input  wire clk,
    input  wire i_ce,
    input  wire req,
    output wire grant,
    output wire expired
);
    // burst size of the bucket and the response deadline for one request
    localparam [2:0] BURST   = 3'd4;
    localparam [3:0] TIMEOUT = 4'd6;

    reg [2:0] tokens;    // token bucket, capped at BURST
    reg [1:0] tick_cnt;   // refill timer, counts down, tick at zero
    reg       pending;    // window register: set by accepted request, cleared by grant
    reg [3:0] deadline;   // bounded-response countdown for the pending request

    initial tokens   = BURST;
    initial tick_cnt = 2'd3;
    initial pending  = 1'b0;
    initial deadline = 4'd0;

    wire tick     = (tick_cnt == 2'd0);
    wire do_grant = pending && (tokens != 3'd0);

    assign grant   = i_ce && do_grant;
    assign expired = pending && (deadline == 4'd0);

    // refill timer
    always @(posedge clk) if (i_ce)
        tick_cnt <= tick ? 2'd3 : (tick_cnt - 2'd1);

    // bucket: drains on a grant, refills on a tick, saturates at BURST
    always @(posedge clk) if (i_ce) begin
        if (do_grant && tick)
            tokens <= tokens;                 // one out, one in
        else if (do_grant)
            tokens <= tokens - 3'd1;
        else if (tick && (tokens < BURST))
            tokens <= tokens + 3'd1;
    end

    // request window and its countdown
    always @(posedge clk) if (i_ce) begin
        if (do_grant)
            pending <= 1'b0;
        else if (pending)
            deadline <= deadline - 4'd1;
        else if (req) begin
            pending  <= 1'b1;
            deadline <= TIMEOUT;
        end
    end

    // P: inside the request window the countdown never expires
    always @(posedge clk)
        if (pending) assert (deadline != 4'd0);
endmodule

module pingpong_tile_buffer (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire       wr_en,
    input  wire       rd_en,
    input  wire [7:0] wr_data,
    output reg  [7:0] rd_data,
    output wire       o_sel
);
    localparam [1:0] LAST = 2'd3;

    // ping-pong double buffer: one half owned by the rasterizer (writer),
    // the other half owned by the shader fetch port (reader)
    reg       sel;                 // master ping-pong select bit
    reg       wr_half, rd_half;    // half currently addressed by each port
    reg [1:0] wcnt, rcnt;          // offset inside the owned half
    reg       wr_full, rd_empty;   // per-half handshake flags
    reg [7:0] mem [0:7];
    integer   i;

    initial begin
        sel     = 1'b0;
        wr_half = 1'b0;
        rd_half = 1'b1;
        wcnt    = 2'd0;
        rcnt    = 2'd0;
        wr_full = 1'b0;
        rd_empty= 1'b1;
        rd_data = 8'h00;
        for (i = 0; i < 8; i = i + 1) mem[i] = 8'h00;
    end

    wire [2:0] wr_addr = {wr_half, wcnt};
    wire [2:0] rd_addr = {rd_half, rcnt};

    wire w_step = i_ce && wr_en && !wr_full;
    wire r_step = i_ce && rd_en && !rd_empty;
    wire swap   = i_ce && wr_full && rd_empty;

    assign o_sel = sel;

    always @(posedge clk) begin
        if (rst) begin
            sel      <= 1'b0;
            wr_half  <= 1'b0;
            rd_half  <= 1'b1;
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
            wr_full  <= 1'b0;
            rd_empty <= 1'b1;
        end else if (swap) begin
            sel      <= ~sel;
            wr_half  <= ~sel;   // writer takes the freshly drained half
            rd_half  <=  sel;   // reader takes the freshly filled half
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
            wr_full  <= 1'b0;
            rd_empty <= 1'b0;
        end else begin
            if (w_step) begin
                mem[wr_addr] <= wr_data;
                wcnt <= wcnt + 2'd1;
                if (wcnt == LAST) wr_full <= 1'b1;
            end
            if (r_step) begin
                rd_data <= mem[rd_addr];
                rcnt <= rcnt + 2'd1;
                if (rcnt == LAST) rd_empty <= 1'b1;
            end
        end
    end

    // P: whenever both ports perform an access in the same cycle they never
    // touch the same buffer location
    always @(posedge clk)
        if (i_ce && wr_en && rd_en && !wr_full && !rd_empty)
            assert (wr_addr != rd_addr);
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

    reg [3:0] nxt;

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
            else if (nxt == S_ROUTE)
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);
endmodule

module wdog_scan (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // scanner step enable; low => whole design idles
    input  wire i_kick,    // full substring match: hard kick of the watchdog
    input  wire i_feed,    // partial match: partial credit, no flag clear
    output wire o_timeout,
    output wire [7:0] o_pos
);
    // Watchdog for a character-scan engine: the scanner must report progress
    // before LIMIT idle steps elapse, otherwise the search is declared timed out.
    localparam [3:0] LIMIT = 4'd12;

    reg [3:0] wd;       // cycles since last progress, saturates at LIMIT
    reg       expired;  // sticky timeout flag
    reg [7:0] pos;      // current character position in the haystack

    initial wd      = 4'd0;
    initial expired = 1'b0;
    initial pos     = 8'd0;

    always @(posedge clk) begin
        if (rst) begin
            wd      <= 4'd0;
            expired <= 1'b0;
            pos     <= 8'd0;
        end else if (i_ce) begin
            pos <= pos + 8'd1;
            if (i_kick) begin
                // full match: reload the watchdog and drop the timeout flag
                wd      <= 4'd0;
                expired <= 1'b0;
            end else if (i_feed) begin
                // partial credit: only granted while the counter has not
                // saturated.  Note the gate looks at the COUNTER, not the flag.
                if (wd != LIMIT)
                    wd <= (wd > 4'd4) ? (wd - 4'd4) : 4'd0;
            end else begin
                // no progress this step: count up and saturate at LIMIT
                if (wd != LIMIT) begin
                    wd <= wd + 4'd1;
                    if ((wd + 4'd1) == LIMIT)
                        expired <= 1'b1;
                end
            end
        end
    end

    assign o_timeout = expired;
    assign o_pos     = pos;

    // P: a reported timeout always comes with a counter in the top half of
    // its range (the watchdog really did run out of slack).
    always @(posedge clk) assert (!expired || wd[3]);
endmodule

module arb_lock_pending (
    input  wire       clk,
    input  wire       ce,      // global enable / idle when low
    input  wire [3:0] req,     // new requests, latched into pend
    input  wire       rel,     // current owner releases the lock
    output wire [3:0] grant,
    output wire [2:0] occupancy
);
    // pending request bitmap and its redundant occupancy counter
    reg [3:0] pend  = 4'b0000;
    reg [2:0] pcnt  = 3'd0;
    // fixed-priority arbiter with a lock bit freezing the winner
    reg       lock  = 1'b0;
    reg [1:0] owner = 2'd0;
    reg       pv    = 1'b0;   // past-valid

    // fixed priority: lowest index wins
    wire [1:0] pick = pend[0] ? 2'd0 :
                      pend[1] ? 2'd1 :
                      pend[2] ? 2'd2 : 2'd3;
    wire       any  = |pend;

    // service completion: the locked owner releases, its pending bit retires
    wire       do_clr   = ce && lock && rel;
    wire [3:0] clr_mask = do_clr ? (4'b0001 << owner) : 4'b0000;
    // only genuinely new requests are inserted
    wire [3:0] set_mask = ce ? (req & ~pend & ~clr_mask) : 4'b0000;
    wire [2:0] nset     = set_mask[0] + set_mask[1] + set_mask[2] + set_mask[3];

    assign grant     = lock ? (4'b0001 << owner) : 4'b0000;
    assign occupancy = pcnt;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ce) begin
            pend <= (pend | set_mask) & ~clr_mask;
            pcnt <= pcnt + nset - (do_clr ? 3'd1 : 3'd0);
            if (lock) begin
                if (rel)
                    lock <= 1'b0;      // frozen winner until it releases
            end else if (any) begin
                lock  <= 1'b1;
                owner <= pick;
            end
        end
    end

    // P: if the pending bitmap did not change, the occupancy must not have
    // changed either, and the occupancy stays within its real bound of 4.
    always @(posedge clk)
        if (pv && $stable(pend))
            assert ($stable(pcnt) && (pcnt <= 3'd4));
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
    output wire [2:0] o_inflight
);
    // fixed-latency (4 cycle) pipeline occupancy shift register
    reg [3:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;

    initial pipe     = 4'b0000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;

    wire retire = pipe[3];

    always @(posedge clk) begin
        if (rst) begin
            pipe     <= 4'b0000;
            inflight <= 3'd0;
        end else if (i_ce) begin
            pipe     <= {pipe[2:0], issue};
            inflight <= inflight + {2'b00, issue} - {2'b00, retire};
        end
    end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module lex_onehot_esc (
    input wire       i_clk,
    input wire       i_reset,
    input wire       i_ce,
    input wire [7:0] i_char,
    output wire      o_in_string,
    output wire [3:0] o_esc_count
);
    // one-hot lexer state: exactly one bit set by construction
    localparam S_IDLE  = 0;
    localparam S_IDENT = 1;
    localparam S_NUM   = 2;
    localparam S_STR   = 3;
    localparam S_ESC   = 4;

    reg [4:0] st;
    reg [3:0] cnt;   // escape sequences counted in the current string literal
    reg       arm;   // sticky: set the first time a string literal is being scanned
    reg       pv;

    initial st  = 5'b00001;
    initial cnt = 4'd0;
    initial arm = 1'b0;
    initial pv  = 1'b0;

    wire is_q   = (i_char == 8'h22);
    wire is_bs  = (i_char == 8'h5C);
    wire is_dig = (i_char >= 8'h30) && (i_char <= 8'h39);
    wire is_alp = ((i_char | 8'h20) >= 8'h61) && ((i_char | 8'h20) <= 8'h7A);

    reg [4:0] nst;
    reg [3:0] ncnt;

    always @(*) begin
        nst  = st;
        ncnt = cnt;
        if (st[S_IDLE]) begin
            if (is_q) begin
                nst  = 5'b01000;   // open quote: enter string, fresh escape count
                ncnt = 4'd0;
            end else if (is_dig)
                nst = 5'b00100;
            else if (is_alp)
                nst = 5'b00010;
            else
                nst = 5'b00001;
        end else if (st[S_IDENT]) begin
            nst = (is_alp || is_dig) ? 5'b00010 : 5'b00001;
        end else if (st[S_NUM]) begin
            nst = is_dig ? 5'b00100 : 5'b00001;
        end else if (st[S_STR]) begin
            if (is_q) begin
                nst  = 5'b00001;   // close quote: escape count retired
                ncnt = 4'd0;
            end else if (is_bs)
                nst = 5'b10000;    // ESC is reachable only from STR
            else
                nst = 5'b01000;
        end else if (st[S_ESC]) begin
            nst  = 5'b01000;       // ESC always returns to STR
            ncnt = (cnt == 4'd8) ? 4'd8 : (cnt + 4'd1);
        end
    end

    always @(posedge i_clk) begin
        if (i_reset) begin
            st  <= 5'b00001;
            cnt <= 4'd0;
        end else if (i_ce) begin
            st  <= nst;
            cnt <= ncnt;
        end

        if (i_ce && !i_reset && (st[S_STR] || st[S_ESC]))
            arm <= 1'b1;

        pv <= 1'b1;
    end

    assign o_in_string  = st[S_STR] || st[S_ESC];
    assign o_esc_count  = cnt;

    // Universality, in the "after arm" scope, stated about the previous cycle:
    // once a string literal has been seen, the escape counter is always zero
    // whenever the lexer sits in the IDLE state.
    always @(posedge i_clk)
        if (pv && arm)
            assert (!$past(st[S_IDLE]) || ($past(cnt) == 4'd0));
endmodule

module pwm_prio_duty (
    input  wire       clk,
    input  wire       ce,
    input  wire [7:0] req,
    output reg        out_r,
    output reg        vld_r
);
    // ---------------- PWM state ----------------
    reg [2:0] cnt;        // period counter 0..7
    reg [3:0] duty;       // active duty value 0..8
    reg [3:0] hi_cnt;     // cycles spent high inside the current period
    reg       shadow_nz;  // shadow: the duty programmed for this period was nonzero
    reg       armed;      // scope: high until the first all-zero request load

    initial begin
        cnt       = 3'd0;
        duty      = 4'd4;   // reset duty is nonzero
        hi_cnt    = 4'd0;
        shadow_nz = 1'b1;   // matches reset duty
        armed     = 1'b1;
        out_r     = 1'b0;
        vld_r     = 1'b0;
    end

    // ---------------- priority encoder over the request vector ----------------
    reg [2:0] idx;
    reg       vld;
    always @(*) begin
        vld = |req;
        if      (req[7]) idx = 3'd7;
        else if (req[6]) idx = 3'd6;
        else if (req[5]) idx = 3'd5;
        else if (req[4]) idx = 3'd4;
        else if (req[3]) idx = 3'd3;
        else if (req[2]) idx = 3'd2;
        else if (req[1]) idx = 3'd1;
        else             idx = 3'd0;
    end

    // requested duty: highest set index + 1, or 0 when no request
    wire [3:0] duty_req = vld ? ({1'b0, idx} + 4'd1) : 4'd0;

    // ---------------- comparator: high exactly while cnt < duty ----------------
    wire out  = ({1'b0, cnt} < duty);
    wire wrap = (cnt == 3'd7);

    always @(posedge clk) begin
        if (ce) begin
            cnt   <= cnt + 3'd1;   // free-running, wraps 7 -> 0
            out_r <= out;          // registered output stage
            vld_r <= vld;
            if (wrap) begin
                // period boundary: latch the new duty and its shadow flag together
                duty      <= duty_req;
                shadow_nz <= (duty_req != 4'd0);
                hi_cnt    <= 4'd0;
                if (duty_req == 4'd0)
                    armed <= 1'b0; // the scope-closing event R
            end else begin
                hi_cnt <= hi_cnt + (out ? 4'd1 : 4'd0);
            end
        end
    end

    // Precedence, in the "before the first zero-duty program" scope:
    // if the output has been high at all inside this period, then a nonzero
    // duty must have been recorded in the shadow flag earlier.
    always @(posedge clk)
        if (armed && hi_cnt != 4'd0)
            assert (shadow_nz);
endmodule

// Tracks outstanding memory requests issued into a 4-deep load/store pipeline.
// A shift register records which pipeline stages hold a live request; a separate
// counter tracks how many are in flight.
module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,   // pipeline advance / clock-enable
    input  wire       req,    // a new request is issued into stage 0
    output wire       f_idle, // no requests outstanding (from the counter)
    output wire       f_full, // all pipeline slots occupied (from the counter)
    output wire       f_any,  // some stage holds a request (from the shifter)
    output wire       f_slot  // some stage is free (from the shifter)
);

    reg [3:0] inflight;
    reg [2:0] cnt;

    initial inflight = 4'b0000;
    initial cnt      = 3'd0;

    // the request leaving the last stage completes this cycle
    wire retire = inflight[3];

    always @(posedge clk) begin
        if (rst) begin
            inflight <= 4'b0000;
            cnt      <= 3'd0;
        end else if (step) begin
            inflight <= {inflight[2:0], req};
            cnt      <= cnt + {2'b00, req} - {2'b00, retire};
        end
    end

    assign f_idle = (cnt == 3'd0);
    assign f_full = (cnt == 3'd4);
    assign f_any  = |inflight;
    assign f_slot = ~(&inflight);

    // P: the counter-derived flags and the shifter-derived flags may never
    // contradict each other -- idle together with an occupied stage, or
    // full together with a free stage.
    always @(posedge clk) assert (!(f_idle && f_any));
    always @(posedge clk) assert (!(f_full && f_slot));

endmodule

module elastic_two_entry (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_push,
    input  wire       i_pop,
    input  wire [7:0] i_data,
    output wire       o_valid,
    output wire       o_full,
    output wire [7:0] o_data,
    output wire [2:0] o_count
);

    // ---- two-entry elastic buffer -------------------------------------
    // one valid flag per slot, plus head/tail slot selectors.
    reg        v0, v1;      // slot occupancy flags
    reg        head, tail;  // which slot is read / written next
    reg [7:0]  d0, d1;      // slot payloads
    reg [2:0]  count;       // redundant occupancy counter

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial head  = 1'b0;
    initial tail  = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;

    // status is derived from the FLAGS, not from the counter
    assign o_full  = v0 && v1;
    assign o_valid = v0 || v1;
    assign o_data  = head ? d1 : d0;
    assign o_count = count;

    wire do_push = i_push && !o_full;
    wire do_pop  = i_pop  &&  o_valid;

    // idle condition: i_push == 0 && i_pop == 0 leaves all state alone
    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            head  <= 1'b0;
            tail  <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
        end else begin
            if (do_push) begin
                if (tail == 1'b0) begin
                    v0 <= 1'b1;
                    d0 <= i_data;
                end else begin
                    v1 <= 1'b1;
                    d1 <= i_data;
                end
                tail <= ~tail;
            end

            if (do_pop) begin
                if (head == 1'b0)
                    v0 <= 1'b0;
                else
                    v1 <= 1'b0;
                head <= ~head;
            end

            count <= count + (do_push ? 3'd1 : 3'd0)
                            - (do_pop  ? 3'd1 : 3'd0);
        end
    end

    // ---- property: while the buffer holds anything, the occupancy
    //      counter never exceeds the two-entry depth (the register is
    //      three bits wide, so 3..7 are representable).
    always @(posedge i_clk)
        if (o_valid)
            assert (count <= 3'd2);

endmodule

// Credit-managed transfer engine: three credit pools, one per chain step.
// A credit is spent on ARM, handed on at START and returned by the consumer
// at FINISH.  Total credits in the system is fixed at TOTAL by construction.
module credit_chain (
    input  wire clk,
    input  wire i_ce,      // global enable: low => the engine idles
    input  wire i_arm,
    input  wire i_start,
    input  wire i_done,
    input  wire i_flush,
    output wire o_fin_seen,
    output wire o_busy
);
    localparam [3:0] TOTAL = 4'd3;

    // ---- credit counter: credits held + credits in each stage == TOTAL ----
    reg [3:0] free_cr;    // credits held by the producer
    reg [3:0] armed_cr;   // credits spent on ARM, awaiting START
    reg [3:0] busy_cr;    // credits outstanding at the consumer

    // ---- chain history (arm -> start -> finish) ----
    reg ever_arm;
    reg ever_start;
    reg ever_fin;

    // ---- before-flush scope register: starts high, cleared by first flush ----
    reg nf;

    initial begin
        free_cr    = TOTAL;
        armed_cr   = 4'd0;
        busy_cr    = 4'd0;
        ever_arm   = 1'b0;
        ever_start = 1'b0;
        ever_fin   = 1'b0;
        nf         = 1'b1;
    end

    wire do_flush = i_ce &&  i_flush;
    wire do_arm   = i_ce && !i_flush && i_arm   && (free_cr  != 4'd0);
    wire do_start = i_ce && !i_flush && i_start && (armed_cr != 4'd0);
    wire do_fin   = i_ce && !i_flush && i_done  && (busy_cr  != 4'd0);

    always @(posedge clk) begin
        if (do_flush) begin
            // all credits are recalled to the producer; the chain record for
            // this session is dropped, the finish record is kept.
            free_cr    <= TOTAL;
            armed_cr   <= 4'd0;
            busy_cr    <= 4'd0;
            ever_arm   <= 1'b0;
            ever_start <= 1'b0;
            nf         <= 1'b0;
        end else if (i_ce) begin
            free_cr  <= free_cr  - do_arm   + do_fin;
            armed_cr <= armed_cr + do_arm   - do_start;
            busy_cr  <= busy_cr  + do_start - do_fin;
            if (do_arm)   ever_arm   <= 1'b1;
            if (do_start) ever_start <= 1'b1;
            if (do_fin)   ever_fin   <= 1'b1;
        end
    end

    assign o_fin_seen = ever_fin;
    assign o_busy     = (busy_cr != 4'd0);

    // Chain precedence, in the before-flush scope: a FINISH can never have been
    // observed unless an ARM and a START were observed first.
    always @(*)
        if (nf)
            assert (!ever_fin || (ever_arm && ever_start));
endmodule

// DRC check engine: each accepted board-check job walks a saturating
// step counter up to MAXSTEP while a completion countdown runs down.
module drc_engine (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       start,     // new check job requested
    output reg        busy,      // request outstanding
    output reg [3:0]  progress,  // saturating up-counter, clamps at MAXSTEP
    output reg [3:0]  deadline,  // completion countdown
    output reg        armed,     // sticky: a job has been accepted at least once
    output reg        done
);
    localparam [3:0] MAXSTEP = 4'd10;

    initial begin
        busy     = 1'b0;
        progress = 4'd0;
        deadline = 4'd0;
        armed    = 1'b0;
        done     = 1'b0;
    end

    wire accept   = i_ce && start && !busy;
    wire step     = i_ce && busy;
    wire last     = (progress + 4'd1 >= MAXSTEP);

    always @(posedge clk) begin
        if (rst) begin
            busy     <= 1'b0;
            progress <= 4'd0;
            deadline <= 4'd0;
            armed    <= 1'b0;
            done     <= 1'b0;
        end else if (accept) begin
            busy     <= 1'b1;
            progress <= 4'd0;
            deadline <= MAXSTEP;
            armed    <= 1'b1;   // sticky once set, never cleared except by rst
            done     <= 1'b0;
        end else if (step) begin
            // saturating up-counter: clamps at MAXSTEP, never reaches 4'd15
            progress <= (progress == MAXSTEP) ? MAXSTEP : progress + 4'd1;
            deadline <= (deadline == 4'd0)    ? 4'd0    : deadline - 4'd1;
            if (last) begin
                busy <= 1'b0;
                done <= 1'b1;
            end
        end
    end

    // P: while the engine has ever been armed and a check is outstanding,
    // the completion countdown must not have expired.
    always @(*)
        if (armed && busy)
            assert (deadline != 4'd0);
endmodule

module hwm_stack_ptr (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_push,
    input  wire       i_pop,
    output wire       o_deep,
    output wire [3:0] o_mark,
    output wire [3:0] o_sp
);
    localparam [3:0] THRESH = 4'd4;

    // stack pointer and its high-water mark
    reg [3:0] sp;
    reg [3:0] hwm;
    reg       mark_deep;   // registered "mark has crossed THRESH" flag
    reg       pv;          // past-valid

    initial sp        = 4'd0;
    initial hwm       = 4'd0;
    initial mark_deep = 1'b0;
    initial pv        = 1'b0;

    wire do_push = i_ce && i_push && !i_pop && (sp != 4'hF);
    wire do_pop  = i_ce && i_pop  && !i_push && (sp != 4'h0);

    wire [3:0] sp_nx  = do_push ? (sp + 4'd1)
                      : (do_pop ? (sp - 4'd1) : sp);

    // the mark never falls below the pointer and only ratchets upward
    wire [3:0] hwm_nx = (sp_nx > hwm) ? sp_nx : hwm;

    always @(posedge clk) begin
        if (i_ce) begin
            sp        <= sp_nx;
            hwm       <= hwm_nx;
            mark_deep <= (hwm_nx >= THRESH);
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign o_deep = mark_deep;
    assign o_mark = hwm;
    assign o_sp   = sp;

    // Precedence: the deep-mark flag can only rise because the pointer itself
    // has just reached that depth, so the depth must be visible right now.
    always @(posedge clk)
        if (pv && $rose(mark_deep))
            assert (sp >= THRESH);

endmodule

module fetch_credit_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,        // idle condition: when low, nothing moves
    input  wire       fetch,     // issue an instruction into the fetch queue
    input  wire       retire,    // instruction leaves the queue
    output reg  [3:0] used,      // up counter: occupancy of the fetch queue
    output reg  [3:0] credits,   // down counter: remaining free slots
    output wire       can_fetch
);
    // queue depth is 12, but both counters are 4 bits wide (0..15)
    localparam [3:0] DEPTH = 4'd12;

    initial used    = 4'd0;
    initial credits = DEPTH;

    assign can_fetch = (credits != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            used    <= 4'd0;
            credits <= DEPTH;
        end else if (en) begin
            if (fetch && !retire && credits != 4'd0) begin
                // one slot moves from the free pool into the queue
                used    <= used + 4'd1;
                credits <= credits - 4'd1;
            end else if (retire && !fetch && used != 4'd0) begin
                // one slot moves back from the queue into the free pool
                used    <= used - 4'd1;
                credits <= credits + 4'd1;
            end
            // simultaneous fetch+retire: slot handed straight over, no change
        end
    end

    // P (two assertions, global scope, bounded existence at most 12):
    // neither counter can ever exceed the queue depth, which is strictly
    // smaller than what their 4-bit width admits.
    always @(posedge clk) begin
        assert (used <= DEPTH);
        assert (credits <= DEPTH);
    end
endmodule

module lfsr_grant_arb (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    output reg  [1:0] gnt,
    output wire [4:0] o_state
);
    // Maximal-length 5-bit Galois-style shift register, x^5 + x^3 + 1.
    // Seeded nonzero, so the all-zeros lockup state is unreachable.
    reg [4:0] lfsr;

    initial lfsr = 5'h01;
    initial gnt  = 2'b01;

    wire       fb  = lfsr[4] ^ lfsr[2];
    wire [4:0] nxt = {lfsr[3:0], fb};

    // Pseudo-random round-robin: the low bit of the shift register picks
    // which of the two requesters is granted next cycle.  The all-zeros
    // lockup pattern decodes to the illegal "both owners" encoding.
    wire [1:0] sel = (lfsr == 5'd0) ? 2'b11 :
                     (lfsr[0]      ? 2'b01 : 2'b10);

    always @(posedge clk) begin
        if (rst) begin
            lfsr <= 5'h01;
            gnt  <= 2'b01;
        end else if (i_ce) begin
            lfsr <= nxt;
            gnt  <= sel;
        end
    end

    assign o_state = lfsr;

    // Absence: the two grants are never asserted together.
    always @(*)
        if (gnt[0])
            assert (!gnt[1]);
endmodule

module dma_burst_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // engine clock-enable / idle when low
    input  wire       i_start,   // Q: opens the transfer window
    input  wire [3:0] i_len,     // burst length in beats
    input  wire       i_ack,     // R: closes the transfer window
    output wire       o_busy,
    output wire       o_drained
);

    // beats-remaining counter and the two status flags derived from it
    reg [3:0] beats_left;
    reg       busy;
    reg       drained;

    // window register: set by a new burst (Q), cleared by the ack (R)
    reg       win;

    initial beats_left = 4'd0;
    initial busy       = 1'b0;
    initial drained    = 1'b1;
    initial win        = 1'b0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            busy       <= 1'b0;
            drained    <= 1'b1;
            win        <= 1'b0;
        end else if (i_ce) begin
            if (i_start && !busy) begin
                // load a new burst descriptor and open the window
                beats_left <= i_len;
                busy       <= (i_len != 4'd0);
                drained    <= (i_len == 4'd0);
                win        <= 1'b1;
            end else if (busy) begin
                // retire one beat
                beats_left <= beats_left - 4'd1;
                busy       <= (beats_left != 4'd1);
                drained    <= (beats_left <= 4'd1);
                if (i_ack)
                    win <= 1'b0;
            end else if (i_ack) begin
                // close the window between transfers
                win <= 1'b0;
            end
        end
    end

    assign o_busy    = busy;
    assign o_drained = drained;

    // P: inside an open transfer window the engine is never simultaneously
    // reporting "busy" and "drained".
    always @(posedge i_clk)
        if (win)
            assert (!(busy && drained));

endmodule

module gray_shadow_ctr (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    output wire [3:0] o_gray,
    output wire [3:0] o_bin
);
    // Binary shadow counter and its gray-coded twin.  The gray register is
    // advanced by the classic single-bit-toggle rule, computed from the gray
    // value alone; the binary shadow is a plain increment.
    reg [3:0] bin;
    reg [3:0] gray;
    reg       pv;

    initial bin  = 4'b0000;
    initial gray = 4'b0000;
    initial pv   = 1'b0;

    // Next gray value: toggle bit 0 when the parity is even, otherwise toggle
    // the bit just above the lowest set bit (with the top bit handling wrap).
    function [3:0] gnext(input [3:0] g);
        begin
            if (!(^g))     gnext = g ^ 4'b0001;
            else if (g[0]) gnext = g ^ 4'b0010;
            else if (g[1]) gnext = g ^ 4'b0100;
            else           gnext = g ^ 4'b1000;
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            bin  <= 4'b0000;
            gray <= 4'b0000;
        end else if (i_ce) begin
            bin  <= bin + 4'b0001;
            gray <= gnext(gray);
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign o_gray = gray;
    assign o_bin  = bin;

    // Top bit of the gray word and top bit of the binary shadow: the most
    // significant gray bit is just the most significant binary bit, so neither
    // may move without the other.
    wire g_msb = gray[3];
    wire b_msb = bin[3];

    // P: whenever the gray MSB did not change, the shadow MSB did not change.
    always @(posedge clk)
        if (pv && $stable(g_msb))
            assert ($stable(b_msb));
endmodule

module axi_grant_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire [3:0] req,
    input  wire       done,
    output reg        gnt_valid,
    output reg [1:0]  gnt_idx,
    output reg [2:0]  timer,
    output reg [2:0]  elapsed,
    output wire [3:0] o_gnt
);
    // Latency budget granted to an accepted request.
    localparam [2:0] BUDGET = 3'd5;

    // ---------------------------------------------------------------
    // Priority encoder over the request vector: lowest index wins.
    // The encoded index is only meaningful while gnt_valid is set.
    // ---------------------------------------------------------------
    wire       enc_valid = |req;
    wire [1:0] enc_idx   = req[0] ? 2'd0 :
                           req[1] ? 2'd1 :
                           req[2] ? 2'd2 : 2'd3;

    // Retirement of the outstanding grant: either the slave answered,
    // or the budget has been fully consumed.
    wire retire = gnt_valid && (done || ((elapsed == 3'd4) && (timer == 3'd1)));

    assign o_gnt = gnt_valid ? (4'b0001 << gnt_idx) : 4'b0000;

    initial gnt_valid = 1'b0;
    initial gnt_idx   = 2'd0;
    initial timer     = 3'd0;
    initial elapsed   = 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            gnt_valid <= 1'b0;
            gnt_idx   <= 2'd0;
            timer     <= 3'd0;
            elapsed   <= 3'd0;
        end else if (i_ce) begin
            if (!gnt_valid) begin
                if (enc_valid) begin
                    gnt_valid <= 1'b1;
                    gnt_idx   <= enc_idx;
                    timer     <= BUDGET;   // credits left
                    elapsed   <= 3'd0;     // cycles burnt
                end
            end else if (retire) begin
                gnt_valid <= 1'b0;
                timer     <= 3'd0;
                elapsed   <= 3'd0;
            end else begin
                timer   <= timer   - 3'd1;
                elapsed <= elapsed + 3'd1;
            end
        end
    end

    // Bounded response, safety form: the countdown must never reach zero
    // while a grant is still outstanding ...
    always @(posedge clk)
        assert (!gnt_valid || (timer != 3'd0));

    // ... and the elapsed-cycle counter must never run past the budget
    // window while a grant is still outstanding.
    always @(posedge clk)
        assert (!gnt_valid || (elapsed <= 3'd4));
endmodule

module skid_parity_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // stage enable: low => full idle
    input  wire       i_valid,
    input  wire [7:0] i_data,
    input  wire       i_dready,    // downstream ready
    input  wire       i_close,     // closes the observation window
    output wire       o_ready,
    output reg        o_valid,
    output reg  [7:0] o_data
);

    // ---- skid buffer stage state ----
    reg        stall;      // skid slot occupied
    reg  [7:0] skid;       // buffered word (meaningful only while stall)
    reg        skid_par;   // shadow parity of the buffered word

    reg        o_par;      // shadow parity of the presented word

    // ---- observation window (opened by a skid release, closed by i_close) ----
    reg        win;
    reg  [7:0] acc_data;    // xor of words released inside the window
    reg        acc_par;     // xor of their shadow parities

    initial begin
        stall    = 1'b0;
        skid     = 8'h00;
        skid_par = 1'b0;
        o_valid  = 1'b0;
        o_data   = 8'h00;
        o_par    = 1'b0;
        win      = 1'b0;
        acc_data = 8'h00;
        acc_par  = 1'b0;
    end

    assign o_ready = !stall;

    wire do_release = i_ce &&  stall &&  i_dready;
    wire do_direct  = i_ce && !stall &&  i_valid && (i_dready || !o_valid);
    wire do_capture = i_ce && !stall &&  i_valid && o_valid && !i_dready;
    wire do_drop    = i_ce && !stall && !i_valid && i_dready && o_valid;

    always @(posedge clk) begin
        if (rst) begin
            stall    <= 1'b0;
            skid     <= 8'h00;
            skid_par <= 1'b0;
            o_valid  <= 1'b0;
            o_data   <= 8'h00;
            o_par    <= 1'b0;
            win      <= 1'b0;
            acc_data <= 8'h00;
            acc_par  <= 1'b0;
        end else begin
            // datapath
            if (do_release) begin
                o_valid <= 1'b1;
                o_data  <= skid;
                o_par   <= skid_par;
                stall   <= 1'b0;
            end else if (do_direct) begin
                o_valid <= 1'b1;
                o_data  <= i_data;
                o_par   <= ^i_data;
            end else if (do_capture) begin
                stall    <= 1'b1;
                skid     <= i_data;
                skid_par <= ^i_data;
            end else if (do_drop) begin
                o_valid <= 1'b0;
            end

            // window: opened by a release, closed by i_close
            if (i_ce) begin
                if (i_close)         win <= 1'b0;
                else if (do_release) win <= 1'b1;
            end

            // in-window accumulation of released words
            if (do_release) begin
                if (win) begin
                    acc_data <= acc_data ^ skid;
                    acc_par  <= acc_par  ^ skid_par;
                end else begin
                    acc_data <= skid;
                    acc_par  <= skid_par;
                end
            end
        end
    end

    // ---- property: inside the window, both shadow parities track their words ----
    always @(posedge clk) begin
        if (win) begin
            assert (o_par   == (^o_data));
            assert (acc_par == (^acc_data));
        end
    end

endmodule

// Histogram accumulator: four bin counters, one sample at a time,
// plus a running total-samples register and a shadow register that
// records the bin-0 count observed at the most recent bin-1 sample.
module histo_precedence (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire [1:0] i_bin,     // which bin the incoming sample lands in
    output wire [5:0] o_total,
    output wire [3:0] o_snap
);
    // bin counters
    reg [3:0] b0, b1, b2, b3;
    // total samples accumulated
    reg [5:0] total;
    // shadow register: value of bin 0 at the time of the last bin-1 sample
    reg [3:0] snap;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;

    // value currently held by the selected bin
    wire [3:0] sel_val = (i_bin == 2'd0) ? b0 :
                         (i_bin == 2'd1) ? b1 :
                         (i_bin == 2'd2) ? b2 : b3;

    // a sample is committed only if the selected bin has headroom
    wire incr = i_ce && (sel_val != 4'd15);

    always @(posedge clk) begin
        if (incr) begin
            case (i_bin)
                2'd0: b0 <= b0 + 4'd1;
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
            endcase
            total <= total + 6'd1;
            // take the shadow snapshot when a bin-1 sample is committed
            if (i_bin == 2'd1)
                snap <= b0;
        end
    end

    assign o_total = total;
    assign o_snap  = snap;

    // Property (precedence): whenever a sample is being committed, the
    // bin-0 population recorded earlier in the shadow register must already
    // have been accounted for in the total-samples register.
    always @(posedge clk)
        if (incr)
            assert (total >= {2'b00, snap});
endmodule

module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] req,
    output reg  [3:0] gnt,
    output reg  [1:0] stage
);
    // round-robin arbiter state
    reg [1:0] last_gnt;
    // chain-precedence bookkeeping: arm (line0) -> start (line1) -> finish (line2)
    reg       seen_arm;
    reg       seen_start;
    // sticky scope register: set the first time any grant is issued
    reg       armed;

    initial begin
        last_gnt   = 2'd3;
        gnt        = 4'b0000;
        stage      = 2'd0;
        seen_arm   = 1'b0;
        seen_start = 1'b0;
        armed      = 1'b0;
    end

    // combinational round-robin grant: one-hot, never on a non-requesting line
    reg [3:0] gnt_c;
    always @(*) begin
        case (last_gnt)
            2'd0: gnt_c = req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 : 4'b0000;
            2'd1: gnt_c = req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 : 4'b0000;
            2'd2: gnt_c = req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 : 4'b0000;
            default: gnt_c = req[0] ? 4'b0001 :
                             req[1] ? 4'b0010 :
                             req[2] ? 4'b0100 :
                             req[3] ? 4'b1000 : 4'b0000;
        endcase
    end

    wire [1:0] gnt_idx = gnt_c[0] ? 2'd0 :
                         gnt_c[1] ? 2'd1 :
                         gnt_c[2] ? 2'd2 : 2'd3;

    wire fire = i_ce && (gnt_c != 4'b0000);

    always @(posedge clk) begin
        gnt <= fire ? gnt_c : 4'b0000;
        if (fire) begin
            last_gnt <= gnt_idx;
            armed    <= 1'b1;
            case (stage)
                2'd0: begin
                    if (gnt_c[0]) begin
                        stage    <= 2'd1;   // ARM step
                        seen_arm <= 1'b1;
                    end
                end
                2'd1: begin
                    if (gnt_c[1]) begin
                        stage      <= 2'd2; // START step
                        seen_start <= 1'b1;
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                    end
                end
                2'd2: begin
                    if (gnt_c[2]) begin
                        stage <= 2'd3;      // FINISH step
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                    end
                end
                default: begin
                    stage      <= 2'd0;     // retire transaction
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                end
            endcase
        end
    end

    // P: once the arbiter has ever granted (sticky armed), a finished
    // transaction can only be observed if arm and start really happened.
    always @(posedge clk)
        if (armed && stage == 2'd3)
            assert (seen_arm && seen_start);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_raw != samp) begin
                // sample changed: restart the stability count
                samp     <= i_raw;
                cnt      <= 3'd0;
                stable_f <= 1'b0;
            end else if (cnt != K) begin
                cnt      <= cnt + 3'd1;
                stable_f <= (cnt == K - 3'd1);
                if (cnt == K - 3'd1)
                    o_clean <= samp;   // commit the debounced value
            end
            // cnt == K: saturated, hold cnt, stable_f and o_clean

            if (i_disarm)
                armed <= 1'b0;
            else if (i_arm)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

module sb_window (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_issue,
    input  wire i_retire,
    input  wire i_open,
    input  wire i_close,
    output wire o_full,
    output wire o_empty,
    output wire o_mon
);
    localparam [3:0] WINDOW = 4'd8;

    // transaction scoreboard: issued count, retired count, and a redundant
    // outstanding-transaction register maintained in parallel
    reg [4:0] iss;
    reg [4:0] ret;
    reg [3:0] out_r;

    // registered status flags (one cycle stale, updated only when enabled)
    reg       full_q;
    reg       empty_q;

    // monitoring window: opened by i_open, closed by i_close
    reg       mon;

    reg       pv;

    initial iss     = 5'd0;
    initial ret     = 5'd0;
    initial out_r   = 4'd0;
    initial full_q  = 1'b0;
    initial empty_q = 1'b1;
    initial mon     = 1'b0;
    initial pv      = 1'b0;

    wire acc_iss = i_ce && i_issue  && (out_r <  WINDOW);
    wire acc_ret = i_ce && i_retire && (out_r != 4'd0);

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            iss   <= 5'd0;
            ret   <= 5'd0;
            out_r <= 4'd0;
        end else begin
            if (acc_iss) iss <= iss + 5'd1;
            if (acc_ret) ret <= ret + 5'd1;
            if (acc_iss && !acc_ret)
                out_r <= out_r + 4'd1;
            else if (!acc_iss && acc_ret)
                out_r <= out_r - 4'd1;
        end

    always @(posedge clk)
        if (i_rst) begin
            full_q  <= 1'b0;
            empty_q <= 1'b1;
        end else if (i_ce) begin
            full_q  <= (out_r == WINDOW);
            empty_q <= (iss == ret);
        end

    always @(posedge clk)
        if (i_rst)
            mon <= 1'b0;
        else if (i_ce) begin
            if (i_close)
                mon <= 1'b0;
            else if (i_open)
                mon <= 1'b1;
        end

    assign o_full  = full_q;
    assign o_empty = empty_q;
    assign o_mon   = mon;

    // P: inside an open monitoring window, when the full flag rises the
    // scoreboard must not simultaneously report empty
    always @(posedge clk)
        if (pv && mon && $rose(full_q))
            assert (!empty_q);
endmodule

module parity_slice_occ (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_data,
    output reg        o_valid,
    output reg  [7:0] o_data,
    output reg        o_retry
);
    // two-deep register slice, each stage protected by a parity bit
    reg [7:0] d0, d1;
    reg       p0, p1;
    reg       v0, v1;

    // occupancy accounting: one 3-bit counter tracking live stages
    reg [2:0] occ;

    initial begin
        d0 = 8'h00; d1 = 8'h00;
        p0 = 1'b0;  p1 = 1'b0;
        v0 = 1'b0;  v1 = 1'b0;
        occ = 3'd0;
        o_valid = 1'b0;
        o_data  = 8'h00;
        o_retry = 1'b0;
    end

    // stored parity is checked against stored data every cycle
    wire mism0 = v0 && (p0 != (^d0));
    wire mism1 = v1 && (p1 != (^d1));
    wire retry = mism0 || mism1;

    always @(posedge clk) begin
        if (i_ce) begin
            o_retry <= retry;
            if (retry) begin
                // corrupted stage: freeze the slice and book a replay slot
                occ <= occ + 3'd1;
            end else begin
                // normal shift: stage0 -> stage1 -> output
                d1 <= d0;
                p1 <= p0;
                v1 <= v0;
                d0 <= i_data;
                p0 <= ^i_data;
                v0 <= i_valid;
                occ <= occ + (i_valid ? 3'd1 : 3'd0) - (v1 ? 3'd1 : 3'd0);
                o_valid <= v1;
                o_data  <= d1;
            end
        end
    end

    // bounded existence: the slice is two deep, so occupancy never exceeds 2
    always @(*) assert (occ <= 3'd2);
endmodule

module csa_accum_parity (
    input  wire       clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_clear,
    input  wire [7:0] i_data,
    output wire [7:0] o_total,
    output wire [7:0] o_ref
);
    // accumulator kept in carry-save form: two halves that always sum to the
    // true running total held in the reference register
    reg [7:0] acc_s = 8'h00;   // sum half
    reg [7:0] acc_c = 8'h00;   // carry half (always even by construction)
    reg [7:0] total = 8'h00;   // plain ripple-carry reference accumulator

    wire [7:0] sum_bits   = acc_s ^ acc_c ^ i_data;
    wire [7:0] maj_bits   = (acc_s & acc_c) | (acc_s & i_data) | (acc_c & i_data);
    wire [7:0] carry_bits = {maj_bits[6:0], 1'b0};

    always @(posedge clk) begin
        if (i_rst) begin
            acc_s <= 8'h00;
            acc_c <= 8'h00;
            total <= 8'h00;
        end else if (i_ce) begin
            if (i_clear) begin
                acc_s <= 8'h00;
                acc_c <= 8'h00;
                total <= 8'h00;
            end else begin
                acc_s <= sum_bits;
                acc_c <= carry_bits;
                total <= total + i_data;
            end
        end
    end

    assign o_total = acc_s + acc_c;
    assign o_ref   = total;

    // P: while the unit is actually accumulating, the low bit of the sum half
    // alone already carries the parity of the true total.
    always @(posedge clk)
        if (i_ce && !i_clear)
            assert (acc_s[0] == total[0]);
endmodule

module chess_clock_seq_alarm (
    input  wire clk,
    input  wire i_ce,      // clock tick enable; low freezes the whole mechanism
    input  wire sym,       // observed press: 1 = white side, 0 = black side
    output reg  alarm
);
    // match-progress register for the fixed press pattern 1,0,1,1
    // (white, black, white, white) -- the blitz alarm trigger
    reg [2:0] prog;
    // shadow register: latches that the half-way progress (2 symbols) occurred
    reg       seen_half;
    // "before R" scope register: high until the alarm pattern first completes
    reg       before_alarm;

    initial prog         = 3'd0;
    initial seen_half    = 1'b0;
    initial before_alarm = 1'b1;
    initial alarm        = 1'b0;

    reg [2:0] nxt;
    wire match = (prog == 3'd3) && sym;

    always @(*) begin
        case (prog)
            3'd0: nxt = sym ? 3'd1 : 3'd0;
            3'd1: nxt = sym ? 3'd1 : 3'd2;
            3'd2: nxt = sym ? 3'd3 : 3'd0;
            3'd3: nxt = sym ? 3'd0 : 3'd2;  // overlap: "10" survives
            default: nxt = 3'd0;
        endcase
    end

    always @(posedge clk) begin
        if (i_ce) begin
            prog      <= nxt;
            seen_half <= match ? 1'b0 : (seen_half | (nxt == 3'd2));
            alarm     <= match;
            if (match)
                before_alarm <= 1'b0;
        end
    end

    // Precedence, in the scope before the alarm has ever fired:
    // three-quarter progress can only be observed if half progress happened earlier.
    always @(posedge clk)
        assert (!before_alarm || (prog != 3'd3) || seen_half);
endmodule

module npu_psum_lane (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,      // lane enable / idle when low
    input  wire        i_req,     // new accumulation request
    input  wire [7:0]  i_a,
    input  wire [7:0]  i_b,
    output reg  [19:0] o_psum,
    output reg         o_done
);
    // a full psum accumulation takes exactly MAX MAC steps
    localparam [3:0] MAX = 4'd12;

    // saturating up-counter: clamps at 12 although 4 bits admit 15
    reg [3:0] acc_cnt = 4'd0;
    // countdown that guarantees completion of an accepted request
    reg [4:0] ttl     = 5'd0;
    reg       busy    = 1'b0;

    initial o_psum = 20'd0;
    initial o_done = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            acc_cnt <= 4'd0;
            ttl     <= 5'd0;
            busy    <= 1'b0;
            o_psum  <= 20'd0;
            o_done  <= 1'b0;
        end else if (i_ce) begin
            o_done <= 1'b0;
            if (!busy) begin
                if (i_req) begin
                    busy    <= 1'b1;
                    acc_cnt <= 4'd0;
                    ttl     <= 5'd13;   // MAX + 1 cycles of slack
                    o_psum  <= 20'd0;
                end
            end else begin
                o_psum  <= o_psum + (i_a * i_b);
                acc_cnt <= (acc_cnt == MAX) ? MAX : acc_cnt + 4'd1;
                ttl     <= ttl - 5'd1;
                if ((acc_cnt + 4'd1) == MAX) begin
                    busy   <= 1'b0;
                    o_done <= 1'b1;
                end
            end
        end
    end

    // Bounded response, safety form: the completion countdown must never
    // expire while an accepted accumulation request is still outstanding.
    assert property (!busy || ttl != 5'd0);

endmodule

module serv_inflight_tracker (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,      // idle condition: all state frozen when low
    input  wire       i_issue,   // issue a new operation into the pipeline
    output wire       o_retire,
    output wire [2:0] o_occ
);
    localparam LAT = 4;

    // fixed-latency drain shift register: one bit per pipeline stage
    reg [LAT-1:0] pipe;
    initial pipe = {LAT{1'b0}};

    // in-flight occupancy counter: issue increments, drain decrements
    reg [2:0] occ;
    initial occ = 3'd0;

    // window register (scope): armed by an issue, cleared by a retirement
    reg armed;
    initial armed = 1'b0;

    // shadow register: occupancy recorded at the arming issue
    reg [2:0] sh_occ;
    initial sh_occ = 3'd0;

    wire       drain   = pipe[LAT-1];
    wire [2:0] occ_nxt = occ + {2'b00, i_issue} - {2'b00, drain};

    always @(posedge i_clk) begin
        if (i_reset) begin
            pipe   <= {LAT{1'b0}};
            occ    <= 3'd0;
            armed  <= 1'b0;
            sh_occ <= 3'd0;
        end else if (i_ce) begin
            pipe <= {pipe[LAT-2:0], i_issue};
            occ  <= occ_nxt;
            if (i_issue) begin
                armed  <= 1'b1;
                sh_occ <= occ_nxt;
            end else if (drain) begin
                armed <= 1'b0;
            end
        end
    end

    assign o_retire = i_ce & drain;
    assign o_occ    = occ;

    // Precedence, after issue until retire: a retirement observed inside the
    // armed window must have been preceded by a recorded, still-accounted issue.
    always @(posedge i_clk)
        if (armed && i_ce && drain)
            assert (occ != 3'd0 && sh_occ != 3'd0);
endmodule

module uart_rx_onehot (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // baud tick / enable: low freezes all state
    input  wire       rx,
    input  wire       take,    // consumer accepts the byte parked in STOP
    output wire [7:0] o_data,
    output wire       o_ferr,
    output wire       o_busy
);
    // one-hot phase FSM:
    //   st[0]      IDLE
    //   st[1]      START bit
    //   st[2..9]   data bits D0..D7 (one state per bit)
    //   st[10]     STOP bit / byte parked
    reg [10:0] st;
    reg [3:0]  nbits;   // frame phase index: 0..10 only, though 4 bits hold 15
    reg [7:0]  sr;
    reg        ferr;
    reg        pv;

    initial st    = 11'b000_0000_0001;
    initial nbits = 4'd0;
    initial sr    = 8'h00;
    initial ferr  = 1'b0;
    initial pv    = 1'b0;

    wire idle   = st[0];
    wire startb = st[1];
    wire datab  = |st[9:2];
    wire stopb  = st[10];

    wire start_det = ce && idle   && !rx;   // falling edge of the line
    wire adv       = ce && (startb || datab);
    wire done      = ce && stopb  && take;

    // next-state decode: every source bit drives exactly one destination bit
    reg [10:0] nxt;
    always @(*) begin
        nxt      = 11'd0;
        nxt[0]   = (st[0] && rx) || (st[10] && take);
        nxt[1]   = st[0] && !rx;
        nxt[2]   = st[1];
        nxt[3]   = st[2];
        nxt[4]   = st[3];
        nxt[5]   = st[4];
        nxt[6]   = st[5];
        nxt[7]   = st[6];
        nxt[8]   = st[7];
        nxt[9]   = st[8];
        nxt[10]  = st[9] || (st[10] && !take);
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            st    <= 11'b000_0000_0001;
            nbits <= 4'd0;
            sr    <= 8'h00;
            ferr  <= 1'b0;
        end else if (ce) begin
            st <= nxt;
            if (start_det)     nbits <= 4'd1;   // load: start bit is phase 1
            else if (done)     nbits <= 4'd0;
            else if (adv)      nbits <= nbits + 4'd1;
            if (datab)         sr    <= {rx, sr[7:1]};
            if (done)          ferr  <= !rx;    // stop bit must be high
        end
    end

    assign o_data = sr;
    assign o_ferr = ferr;
    assign o_busy = !idle;

    // P: the phase counter changes on every phase change, and it never counts
    // past the 10 phases of a frame -- stated as a no-change check.
    always @(posedge clk)
        if (pv && $stable(nbits))
            assert ($stable(st) && nbits <= 4'd10);
endmodule

module gray_quantum_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // scheduler quantum tick enable
    output wire [3:0] o_gray,
    output wire [2:0] o_ones
);
    // Ten quantum slots (0..9). The binary shadow does the arithmetic,
    // the gray register is what leaves the clock domain. Terminal count is
    // detected on the gray word, as the CDC-facing logic sees it.
    localparam [3:0] GRAY_LAST = 4'b1101; // gray code of 4'd9

    reg [3:0] bin  = 4'd0;
    reg [3:0] gray = 4'b0000;

    wire       wrap    = (gray == GRAY_LAST);
    wire [3:0] bin_nxt = wrap ? 4'd0 : (bin + 4'd1);

    // occupancy of the gray word: how many lanes are asserted this slot
    wire [2:0] ones = {2'b00, gray[0]} + {2'b00, gray[1]} +
                      {2'b00, gray[2]} + {2'b00, gray[3]};
    wire       occ_hi = (ones >= 3'd3);

    assign o_gray = gray;
    assign o_ones = ones;

    always @(posedge clk) begin
        if (rst) begin
            bin  <= 4'd0;
            gray <= 4'b0000;
        end else if (i_ce) begin
            bin  <= bin_nxt;
            gray <= bin_nxt ^ (bin_nxt >> 1);
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Bounded existence: the gray word never carries four asserted lanes,
    // so whenever the high-occupancy flag rises it rises to exactly three.
    always @(posedge clk)
        if (pv && $rose(occ_hi))
            assert (ones == 3'd3);
endmodule

module lfsr_token_arbiter (
    input  wire clk,
    input  wire ce,
    output wire o_gnt_a,
    output wire o_gnt_b,
    output wire o_full,
    output wire o_empty
);
    // maximal-length 4-bit LFSR (x^4 + x^3 + 1): cycles through all 15
    // nonzero states, so the all-zeros lockup state is never entered.
    reg [3:0] lfsr;
    reg       gnt_a, gnt_b;
    reg [2:0] credit, used;
    reg       f_full, f_empty;
    reg       armed;

    initial begin
        lfsr    = 4'h1;
        gnt_a   = 1'b0;
        gnt_b   = 1'b0;
        credit  = 3'd4;
        used    = 3'd0;
        f_full  = 1'b0;
        f_empty = 1'b1;
        armed   = 1'b0;
    end

    wire       fb   = lfsr[3] ^ lfsr[2];
    wire [3:0] nxt  = {lfsr[2:0], fb};
    wire       lock = (lfsr == 4'd0);

    // token movement between the two credit pools, steered by the LFSR
    wire take_a = lfsr[0]  && (credit != 3'd0);
    wire give_b = !lfsr[0] && (used   != 3'd0);

    wire [2:0] nc = take_a ? (credit - 3'd1) : (give_b ? (credit + 3'd1) : credit);
    wire [2:0] nu = take_a ? (used   + 3'd1) : (give_b ? (used   - 3'd1) : used);

    always @(posedge clk) begin
        if (ce) begin
            lfsr <= nxt;

            // grant decode: in the lockup state the decode degenerates and
            // asserts both grants at once
            gnt_a <= lock ? 1'b1 : nxt[0];
            gnt_b <= lock ? 1'b1 : !nxt[0];

            credit <= nc;
            used   <= nu;

            f_full  <= (nc == 3'd0);
            f_empty <= (nu == 3'd0);

            if (lfsr == 4'hF)
                armed <= 1'b1;
        end
    end

    assign o_gnt_a = gnt_a;
    assign o_gnt_b = gnt_b;
    assign o_full  = f_full;
    assign o_empty = f_empty;

    // P1: two grants are never asserted together, once the arbiter has been armed
    always @(posedge clk)
        if (armed)
            assert (!(gnt_a && gnt_b));

    // P2: the full and empty flags are never asserted together, once armed
    always @(posedge clk)
        if (armed)
            assert (!(f_full && f_empty));
endmodule

// Multi-zone thermostat front end with hysteresis and a power budget.
// The active-zone mask is a parity protected register slice; a maintained
// occupancy counter and a remaining-budget counter track it.
module zone_heat_budget (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire [2:0] i_zone,    // zone under consideration this cycle
    input  wire [7:0] i_temp,    // measured temperature of that zone
    output wire       o_fault,   // parity mismatch on the zone slice
    output wire [3:0] o_nact,
    output wire [3:0] o_budget
);
    parameter [7:0] T_LOW  = 8'd40;   // below this, zone asks for heat
    parameter [7:0] T_HIGH = 8'd60;   // above this, zone releases heat
    localparam [3:0] BUDGET = 4'd4;   // at most 4 heaters may run at once

    // ---- parity protected register slice -------------------------------
    reg [7:0] zone;    // one bit per zone heater
    reg       zpar;    // parity bit covering zone
    initial   zone = 8'h00;
    initial   zpar = 1'b0;

    // ---- bookkeeping registers -----------------------------------------
    reg [3:0] nact;    // number of heaters currently on
    reg [3:0] budget;  // remaining power slots
    initial   nact   = 4'd0;
    initial   budget = BUDGET;

    wire fault = (zpar != (^zone));
    assign o_fault  = fault;
    assign o_nact   = nact;
    assign o_budget = budget;

    // hysteresis: nothing happens inside the dead band, so no chattering
    wire req_on  = i_ce && !fault && (i_temp <  T_LOW);
    wire req_off = i_ce && !fault && (i_temp >  T_HIGH);

    wire do_on  = req_on  && !zone[i_zone] && (budget != 4'd0);
    wire do_off = req_off &&  zone[i_zone];

    always @(posedge i_clk) begin
        if (i_rst) begin
            zone   <= 8'h00;
            zpar   <= 1'b0;
            nact   <= 4'd0;
            budget <= BUDGET;
        end else if (do_on) begin
            zone[i_zone] <= 1'b1;
            zpar         <= ~zpar;      // one data bit flips, parity flips
            nact         <= nact + 4'd1;
            budget       <= budget - 4'd1;
        end else if (do_off) begin
            zone[i_zone] <= 1'b0;
            zpar         <= ~zpar;
            nact         <= nact - 4'd1;
            budget       <= budget + 4'd1;
        end
    end

    wire heating = (zone != 8'h00);

    // P: whenever any heater is running, occupancy never exceeds the
    //    power budget of 4 (the counter is 4 bits wide).
    always @(posedge i_clk)
        if (heating)
            assert (nact <= 4'd4);
endmodule

// Four-phase request/acknowledge handshake between a driver and a
// peripheral service unit, with separate idle and busy status flags.
module fourphase_handshake (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,        // global enable / idle condition
    input  wire start,       // driver wants to open a transaction
    input  wire slave_ack,   // peripheral raises acknowledge
    input  wire slave_drop,  // peripheral releases acknowledge
    output wire o_req,
    output wire o_ack,
    output wire o_idle,
    output wire o_busy
);
    // phase encoding:
    //   0 : IDLE      req=0 ack=0
    //   1 : REQ       req=1 ack=0
    //   2 : ACK       req=1 ack=1
    //   3 : DROP      req=0 ack=1   (req may only fall after ack has risen)
    reg [1:0] phase;
    reg       req_r;
    reg       ack_r;
    reg       idle_r;
    reg       busy_r;

    initial begin
        phase  = 2'd0;
        req_r  = 1'b0;
        ack_r  = 1'b0;
        idle_r = 1'b1;
        busy_r = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase  <= 2'd0;
            req_r  <= 1'b0;
            ack_r  <= 1'b0;
            idle_r <= 1'b1;
            busy_r <= 1'b0;
        end else if (i_ce) begin
            case (phase)
                2'd0: begin
                    // leave idle only by raising req; idle flag drops here
                    if (start) begin
                        phase  <= 2'd1;
                        req_r  <= 1'b1;
                        idle_r <= 1'b0;
                    end
                end
                2'd1: begin
                    // peripheral acknowledges; service becomes busy
                    if (slave_ack) begin
                        phase  <= 2'd2;
                        ack_r  <= 1'b1;
                        busy_r <= 1'b1;
                    end
                end
                2'd2: begin
                    // req is allowed to fall now that ack is high
                    phase <= 2'd3;
                    req_r <= 1'b0;
                end
                default: begin
                    // peripheral releases ack, transaction closes
                    if (slave_drop) begin
                        phase  <= 2'd0;
                        ack_r  <= 1'b0;
                        busy_r <= 1'b0;
                        idle_r <= 1'b1;
                    end
                end
            endcase
        end
    end

    assign o_req  = req_r;
    assign o_ack  = ack_r;
    assign o_idle = idle_r;
    assign o_busy = busy_r;

    // P: the service unit is never reported idle and busy at the same time.
    always @(*)
        assert (!(idle_r && busy_r));
endmodule

module stack_scoreboard (
    input  wire       clk,
    input  wire       issue,      // a transaction is pushed onto the shadow stack
    input  wire       retire,     // a transaction is popped / completed
    output wire [2:0] outstanding_o,
    output wire       pre_deep_o
);
    // window depth of the in-flight scoreboard
    localparam [2:0] WINDOW = 3'd4;

    // free-running census of issued and retired transactions (wrap mod 16)
    reg [3:0] issued_cnt  = 4'd0;
    reg [3:0] retired_cnt = 4'd0;

    // in-flight occupancy of the window
    reg [2:0] outstanding = 3'd0;

    // "before R" arming register: starts high, cleared the first time the
    // scoreboard occupancy ever reaches 3 (the deep-stack event)
    reg       pre_deep    = 1'b1;

    // past-valid
    reg       pv          = 1'b0;

    wire do_issue  = issue  && (outstanding != WINDOW);
    wire do_retire = retire && (outstanding != 3'd0);

    always @(posedge clk) begin
        pv <= 1'b1;

        if (do_issue)  issued_cnt  <= issued_cnt  + 4'd1;
        if (do_retire) retired_cnt <= retired_cnt + 4'd1;

        case ({do_issue, do_retire})
            2'b10:   outstanding <= outstanding + 3'd1;
            2'b01:   outstanding <= outstanding - 3'd1;
            default: outstanding <= outstanding;
        endcase

        if (outstanding >= 3'd3)
            pre_deep <= 1'b0;
    end

    assign outstanding_o = outstanding;
    assign pre_deep_o    = pre_deep;

    // Universality, in the scope "before the stack ever got deep":
    // while pre_deep is still set, the number issued so far can lead the
    // retire census of the PREVIOUS cycle by at most 3.
    always @(posedge clk)
        if (pv && pre_deep)
            assert (issued_cnt - $past(retired_cnt) <= 4'd3);
endmodule

module gfx_frame_fsm (
    input  wire clk,
    input  wire i_reset,
    input  wire i_ce,
    input  wire i_start,
    output wire o_vsync,
    output wire [2:0] o_state
);
    // binary-encoded frame pipeline states; 5,6,7 are unreachable encodings
    localparam [2:0] S_IDLE    = 3'd0;
    localparam [2:0] S_CLEAR   = 3'd1;
    localparam [2:0] S_DRAW    = 3'd2;
    localparam [2:0] S_BLIT    = 3'd3;
    localparam [2:0] S_PRESENT = 3'd4;

    reg [2:0] state;
    reg [1:0] draw_cnt;
    reg       cleared_seen;   // shadow: framebuffer was cleared this frame

    initial state        = S_IDLE;
    initial draw_cnt     = 2'd0;
    initial cleared_seen = 1'b0;

    wire draw_done = (draw_cnt == 2'd3);

    always @(posedge clk) begin
        if (i_reset) begin
            state        <= S_IDLE;
            draw_cnt     <= 2'd0;
            cleared_seen <= 1'b0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_start) begin
                        state    <= S_CLEAR;
                        draw_cnt <= 2'd0;
                    end
                end
                S_CLEAR: begin
                    // the clear pass is the "earlier event" the shadow records
                    cleared_seen <= 1'b1;
                    state        <= S_DRAW;
                end
                S_DRAW: begin
                    if (draw_done)
                        state <= S_BLIT;
                    else
                        draw_cnt <= draw_cnt + 2'd1;
                end
                S_BLIT: begin
                    state <= S_PRESENT;
                end
                S_PRESENT: begin
                    state        <= S_IDLE;
                    draw_cnt     <= 2'd0;
                    cleared_seen <= 1'b0;
                end
                default: begin
                    // encodings 5/6/7 never occur by construction; the
                    // synthesised decoder folds them onto the present stage
                    state <= S_PRESENT;
                end
            endcase
        end
    end

    assign o_vsync = (state == S_PRESENT);
    assign o_state = state;

    // Precedence, global: presenting a frame implies the clear pass happened earlier
    always @(posedge clk)
        if (state == S_PRESENT)
            assert (cleared_seen);
endmodule

// Packet-capture sensor credit window.
// TOTAL = 8 stream credits.  A burst send spends 3 credits (they become
// "outstanding" bytes in flight); the collector returns exactly one credit
// per enabled cycle while anything is outstanding.  A deadline register is
// reloaded on every accepted burst and counts down otherwise; it must never
// expire while credits are still outstanding.
module credit_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_send,    // producer requests a burst
    output wire       o_busy
);
    reg [3:0] avail;   // credits held by the sensor
    reg [3:0] outst;   // credits outstanding (in flight)
    reg [3:0] timer;   // completion deadline countdown
    reg       armed;   // sticky: set the first time a burst is accepted

    initial avail = 4'd8;
    initial outst = 4'd0;
    initial timer = 4'd0;
    initial armed = 1'b0;

    wire send_ok = i_send && (avail >= 4'd3);
    wire retire  = (outst != 4'd0);

    assign o_busy = (outst != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            avail <= 4'd8;
            outst <= 4'd0;
            timer <= 4'd0;
            armed <= 1'b0;
        end else if (i_ce) begin
            if (send_ok) begin
                // spend three credits, one may come back the same cycle
                avail <= avail - 4'd3 + (retire ? 4'd1 : 4'd0);
                outst <= outst + 4'd3 - (retire ? 4'd1 : 4'd0);
                timer <= 4'd9;          // fresh completion deadline
                armed <= 1'b1;          // sticky arm
            end else if (retire) begin
                avail <= avail + 4'd1;
                outst <= outst - 4'd1;
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end else begin
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end
        end
    end

    // Bounded response (safety form), scoped after the first accepted burst:
    // the deadline never expires while credits are still outstanding.
    always @(*)
        assert (!armed || !((timer == 4'd0) && (outst != 4'd0)));
endmodule

// PWM channel for a wire-logic accelerator block.
// Period counter walks 0..PER-1, duty is double buffered at the period edge,
// and high_cnt accumulates the number of high cycles elapsed in the period.
module pwm_channel (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire       i_load,
    input  wire [3:0] i_duty,
    output wire       pwm_out,
    output reg        armed
);
    localparam [3:0] PER = 4'd12;

    reg [3:0] cnt;       // period counter, 0 .. PER-1
    reg [3:0] duty;      // active duty, 0 .. PER
    reg [3:0] high_cnt;  // high cycles elapsed so far this period

    initial begin
        cnt      = 4'd0;
        duty     = 4'd0;
        high_cnt = 4'd0;
        armed    = 1'b0;
    end

    // the construct: output high exactly while the counter is below the duty
    assign pwm_out = (cnt < duty);

    wire [3:0] duty_clamped = (i_duty > PER) ? PER : i_duty;
    wire       at_edge      = (cnt == PER - 4'd1);

    always @(posedge clk) begin
        if (rst) begin
            cnt      <= 4'd0;
            duty     <= 4'd0;
            high_cnt <= 4'd0;
            armed    <= 1'b0;
        end else if (i_ce) begin
            if (at_edge) begin
                // period rolls over: new duty takes effect, accumulator clears
                cnt      <= 4'd0;
                high_cnt <= 4'd0;
                armed    <= 1'b1;            // sticky, never cleared
                if (i_load)
                    duty <= duty_clamped;
            end else begin
                cnt      <= cnt + 4'd1;
                high_cnt <= high_cnt + (pwm_out ? 4'd1 : 4'd0);
            end
        end
    end

    // Property (universality, after the first completed period):
    // the accumulated high time never exceeds the duty, and the live output
    // agrees with the accumulator's headroom.
    always @(posedge clk)
        if (armed)
            assert (high_cnt <= duty);

    always @(posedge clk)
        if (armed)
            assert (pwm_out == (high_cnt < duty));
endmodule

module elastic_tag_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       start,      // Q: opens the observation window
    input  wire       stop,       // R: closes the observation window
    input  wire       push,
    input  wire       pop,
    input  wire [3:0] din,
    output wire [3:0] head_data,
    output wire       head_valid,
    output wire       marked_seen
);
    // two-entry elastic buffer: one valid flag per slot, head/tail flags,
    // plus an occupancy counter that mirrors the flags
    reg [1:0] cnt;
    reg       hp, tp;      // head flag / tail flag
    reg       v0, v1;      // per-slot occupancy flags
    reg [3:0] mem0, mem1;

    // window + shadow register for the precedence check
    reg       win;
    reg       seen_hi;

    initial begin
        cnt     = 2'd0;
        hp      = 1'b0;
        tp      = 1'b0;
        v0      = 1'b0;
        v1      = 1'b0;
        mem0    = 4'd0;
        mem1    = 4'd0;
        win     = 1'b0;
        seen_hi = 1'b0;
    end

    // a window may only be opened on an empty buffer; it may be reopened
    wire start_acc = start && !win && (cnt == 2'd0);
    wire stop_acc  = stop && win && !start_acc;

    wire do_push = push && !start_acc && (cnt != 2'd2);
    wire do_pop  = pop  && !start_acc && (cnt != 2'd0);

    assign head_valid  = hp ? v1   : v0;
    assign head_data   = hp ? mem1 : mem0;
    assign marked_seen = seen_hi;

    always @(posedge clk) begin
        if (rst) begin
            cnt     <= 2'd0;
            hp      <= 1'b0;
            tp      <= 1'b0;
            v0      <= 1'b0;
            v1      <= 1'b0;
            win     <= 1'b0;
            seen_hi <= 1'b0;
        end else begin
            if (do_push) begin
                if (tp) begin
                    mem1 <= din;
                    v1   <= 1'b1;
                end else begin
                    mem0 <= din;
                    v0   <= 1'b1;
                end
                tp <= ~tp;
            end

            if (do_pop) begin
                if (hp) v1 <= 1'b0;
                else    v0 <= 1'b0;
                hp <= ~hp;
            end

            cnt <= cnt + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);

            if (start_acc) begin
                win     <= 1'b1;
                seen_hi <= 1'b0;
            end else if (stop_acc) begin
                win     <= 1'b0;
            end else if (do_push && win && din[3]) begin
                seen_hi <= 1'b1;
            end
        end
    end

    // Precedence, inside the window: a marked item can only be observed at the
    // head if a marked item was pushed earlier in this same window.
    assert property (!win || !head_valid || !head_data[3] || seen_hi);
endmodule

module token_chain (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // global enable: low freezes all state
    input  wire i_tick,    // refill timer tick
    input  wire i_arm,     // step 1: arm a transfer request
    input  wire i_start,   // step 2: start it (consumes a token)
    input  wire i_finish,  // step 3: transfer completes
    output wire o_grant,
    output wire o_busy,
    output wire [2:0] o_tokens
);
    localparam [2:0] BURST  = 3'd4;
    localparam [1:0] S_IDLE = 2'd0,
                     S_ARMED= 2'd1,
                     S_RUN  = 2'd2;

    // ---- state ----
    reg [1:0] state;
    reg [2:0] tokens;    // token bucket, capped at BURST
    reg       seen_arm;
    reg       seen_start;
    reg       seen_fin;

    initial state      = S_IDLE;
    initial tokens     = BURST;
    initial seen_arm   = 1'b0;
    initial seen_start = 1'b0;
    initial seen_fin   = 1'b0;

    // ---- chain events ----
    wire arm_pulse   = i_ce && !rst && (state == S_IDLE)  && i_arm;
    wire start_pulse = i_ce && !rst && (state == S_ARMED) && i_start && (tokens != 3'd0);
    wire fin_pulse   = i_ce && !rst && (state == S_RUN)   && i_finish;

    // refill on timer tick, never above the burst cap
    wire refill      = i_ce && !rst && i_tick && (tokens < BURST);

    assign o_grant  = start_pulse;
    assign o_busy   = (state == S_RUN);
    assign o_tokens = tokens;

    // ---- three-step request machine ----
    always @(posedge clk)
        if (rst)
            state <= S_IDLE;
        else if (i_ce) begin
            case (state)
                S_IDLE:  if (i_arm)                        state <= S_ARMED;
                S_ARMED: if (i_start && (tokens != 3'd0))  state <= S_RUN;
                S_RUN:   if (i_finish)                     state <= S_IDLE;
                default:                                   state <= S_IDLE;
            endcase
        end

    // ---- token bucket: drains on grant, refills on tick ----
    always @(posedge clk)
        if (rst)
            tokens <= BURST;
        else if (start_pulse && refill)
            tokens <= tokens;
        else if (start_pulse)
            tokens <= tokens - 3'd1;
        else if (refill)
            tokens <= tokens + 3'd1;

    // ---- sticky chain observation bits ----
    always @(posedge clk)
        if (rst) begin
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            seen_fin   <= 1'b0;
        end else begin
            if (arm_pulse)   seen_arm   <= 1'b1;
            if (start_pulse) seen_start <= 1'b1;
            if (fin_pulse)   seen_fin   <= 1'b1;
        end

    // ---- property: a finish is never observed unless arm and start happened ----
    always @(posedge clk)
        if (seen_fin)
            assert (seen_arm && seen_start);
endmodule

module dma_burst_dimmer (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // beat enable / idle when low
    input  wire       i_start,
    input  wire [3:0] i_beats,
    input  wire [3:0] i_duty,
    output wire       o_busy,
    output wire       o_beat,
    output wire       o_pwm
);

    // ---- DMA burst engine state ----
    reg [3:0] beats_left;   // beats remaining in the burst
    reg [3:0] done_cnt;     // beats already pushed out
    reg [3:0] total;        // beats requested by the accepted burst
    reg [3:0] duty;         // dimming level latched with the burst
    reg       busy;         // up exactly while beats remain

    initial beats_left = 4'd0;
    initial done_cnt   = 4'd0;
    initial total      = 4'd0;
    initial duty       = 4'd0;
    initial busy       = 1'b0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            done_cnt   <= 4'd0;
            total      <= 4'd0;
            duty       <= 4'd0;
            busy       <= 1'b0;
        end else if (i_start && !busy && (i_beats != 4'd0)) begin
            // accept a new burst
            beats_left <= i_beats;
            total      <= i_beats;
            done_cnt   <= 4'd0;
            duty       <= i_duty;
            busy       <= 1'b1;
        end else if (i_ce) begin
            // retire one beat
            if (beats_left != 4'd0)
                beats_left <= beats_left - 4'd1;
            if (beats_left <= 4'd1)
                busy <= 1'b0;
            if (busy)
                done_cnt <= done_cnt + 4'd1;
        end
    end

    assign o_busy = busy;
    assign o_beat = busy && i_ce;
    assign o_pwm  = busy && (done_cnt < duty);

    // ---- P: whenever the engine is not busy, the whole burst has been pushed ----
    always @(posedge i_clk)
        if (!busy)
            assert (done_cnt == total);

endmodule

module gray_ptr_cdc (
    input  wire       clk,
    input  wire       i_ce,      // domain-crossing sample enable (idle when low)
    input  wire       i_inc,     // advance the source pointer
    output wire [2:0] o_sync
);
    // source-side binary pointer and its gray encoding
    reg [2:0] bin   = 3'd0;
    // two-flop synchronizer carrying the gray pointer across the boundary
    reg [2:0] s1    = 3'd0;
    reg [2:0] s2    = 3'd0;
    // shadow binary pointers recording what each synchronizer stage encodes
    reg [2:0] b1    = 3'd0;
    reg [2:0] b2    = 3'd0;
    // sticky arm: set the first time a sample actually happens
    reg       armed = 1'b0;

    wire [2:0] gray = bin ^ (bin >> 1);
    wire [2:0] diff = s1 ^ s2;

    assign o_sync = s2;

    always @(posedge clk) begin
        if (i_ce) begin
            bin   <= bin + (i_inc ? 3'd1 : 3'd0);
            s1    <= gray;
            s2    <= s1;
            b1    <= bin;
            b2    <= b1;
            armed <= 1'b1;
        end
    end

    // Universality, after the synchronizer has been armed: the two captured
    // gray samples never differ in more than one bit.
    always @(*)
        if (armed)
            assert ((diff & (diff - 3'd1)) == 3'd0);
endmodule

// Kernel task handshake tracker.
// The progress accumulator is kept in two carry-save halves acc_a/acc_b whose
// sum is the true phase count (0=idle, 1=armed, 2=started, 3=finished).
// A tiny FSM (ph_ref) enforces the arm -> start -> finish chain, and sticky
// flags record that each earlier step was really observed.
module cs_chain_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       i_track,   // Q event: arms the observation scope, sticky
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_finish,
    output wire [3:0] o_total,
    output wire       o_done
);
    // carry-save halves of the progress accumulator
    reg [2:0] acc_a, acc_b;
    // redundant direct copy of the phase, used by the sequencer
    reg [2:0] ph_ref;
    // which half receives the next increment
    reg       tog;
    // chain witnesses
    reg       arm_seen, start_seen;
    // sticky scope register (set the first time i_track is seen)
    reg       armed;

    initial begin
        acc_a      = 3'd0;
        acc_b      = 3'd0;
        ph_ref     = 3'd0;
        tog        = 1'b0;
        arm_seen   = 1'b0;
        start_seen = 1'b0;
        armed      = 1'b0;
    end

    // true total recombined from the two halves
    wire [3:0] total = {1'b0, acc_a} + {1'b0, acc_b};
    assign o_total = total;
    assign o_done  = (total == 4'd3);

    // one chain step at a time, in order
    wire adv = i_ce && (((ph_ref == 3'd0) && i_arm)    ||
                        ((ph_ref == 3'd1) && i_start)  ||
                        ((ph_ref == 3'd2) && i_finish));

    always @(posedge clk) begin
        if (rst) begin
            acc_a      <= 3'd0;
            acc_b      <= 3'd0;
            ph_ref     <= 3'd0;
            tog        <= 1'b0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            armed      <= 1'b0;
        end else begin
            if (i_ce && i_track)
                armed <= 1'b1;

            if (adv) begin
                // split increment: the two halves always re-sum to the phase
                if (tog) acc_b <= acc_b + 3'd1;
                else     acc_a <= acc_a + 3'd1;
                tog    <= ~tog;
                ph_ref <= ph_ref + 3'd1;

                if (ph_ref == 3'd0) arm_seen   <= 1'b1;
                if (ph_ref == 3'd1) start_seen <= 1'b1;
            end
        end
    end

    // Chain precedence, in the sticky "after i_track" scope:
    // a finished accumulation can never be observed unless both the arm and
    // the start steps were witnessed first.
    always @(*)
        if (armed && (total == 4'd3))
            assert (start_seen && arm_seen);
endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
    output wire       g_holdoff
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

    // ---- redundant occupancy counter kept in parallel with the valid bits ----
    reg [1:0]  occ;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;

    initial begin
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    wire do_push   = i_ce && i_valid && !hold;
    wire do_pop    = i_ce && m_valid && i_ready;
    wire load_skid = i_ce && i_valid && !hold && m_valid && !i_ready;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
                if (i_valid && !hold) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

    // ---- parallel occupancy counter ----
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
            if (do_push && !do_pop)
                occ <= occ + 2'd1;
            else if (do_pop && !do_push)
                occ <= occ - 2'd1;
        end
    end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
            g_fast <= i_valid && (occ == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
    assign o_upstream_ready = !hold;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

endmodule

module handshake_deadline (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       start,     // upstream wants a parse burst
    input  wire       done,      // target signals completion early
    output wire       req,
    output wire       ack,
    output wire       busy_o,
    output wire       timeout
);
    // four-phase handshake: IDLE -> REQ (req rises) -> ACK (ack rises)
    //                       -> DROP (req drops) -> IDLE (ack drops)
    localparam [1:0] P_IDLE = 2'd0,
                     P_REQ  = 2'd1,
                     P_ACK  = 2'd2,
                     P_DROP = 2'd3;

    reg [1:0] phase = P_IDLE;   // handshake phase
    reg       busy  = 1'b0;     // mirrors the phase by construction
    reg [2:0] cnt   = 3'd4;     // completion deadline countdown

    assign req    = (phase == P_REQ)  || (phase == P_ACK);
    assign ack    = (phase == P_ACK)  || (phase == P_DROP);
    assign busy_o = busy;

    // the deadline has expired while the engine is still engaged
    assign timeout = busy && (cnt == 3'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                P_IDLE: begin
                    if (start) begin
                        phase <= P_REQ;   // req rises
                        busy  <= 1'b1;
                    end
                end
                P_REQ: begin
                    // req may not drop here; the target must raise ack first.
                    // the deadline forces the ack phase on the last tick,
                    // so the countdown can never run through zero.
                    if (done || cnt <= 3'd1)
                        phase <= P_ACK;   // ack rises
                    else
                        cnt   <= cnt - 3'd1;
                end
                P_ACK: begin
                    phase <= P_DROP;      // req drops, ack still high
                end
                P_DROP: begin
                    phase <= P_IDLE;      // ack drops
                    busy  <= 1'b0;
                    cnt   <= 3'd4;        // rearm the deadline
                end
            endcase
        end
    end

    // P1: the completion deadline never expires while the engine is engaged
    always @(posedge clk)
        assert (!timeout);

    // P2: while a request is outstanding the deadline is a live value
    always @(posedge clk)
        if (phase == 2'd1)
            assert (cnt >= 3'd1 && cnt <= 3'd4);
endmodule

module serial_retire_counter (
    input  wire i_clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_bit,
    output wire o_word_done,
    output wire o_saturated
);
    // Bit-serial datapath: one bit per enabled cycle, 32 bits per word.
    // Every completed 32-bit word retires one operation; the retire counter
    // is a saturating up-counter that clamps at 20, well below the 31 its
    // 5-bit register could hold.
    localparam [4:0] MAX_RETIRE = 5'd20;

    reg [4:0]  sh;       // serial bit index 0..31
    reg [31:0] word;     // serial shift register (datapath flavour)
    reg [4:0]  retired;  // saturating up-counter, clamps at MAX_RETIRE
    reg        done;     // "counter has reached the clamp" flag

    initial sh      = 5'd0;
    initial word    = 32'd0;
    initial retired = 5'd0;
    initial done    = 1'b0;

    wire word_last = (sh == 5'd31);

    always @(posedge i_clk) begin
        if (i_rst) begin
            sh      <= 5'd0;
            word    <= 32'd0;
            retired <= 5'd0;
            done    <= 1'b0;
        end else if (i_ce) begin
            sh   <= sh + 5'd1;
            word <= { i_bit, word[31:1] };
            if (word_last) begin
                if (!done)
                    retired <= retired + 5'd1;
                done <= done || (retired == (MAX_RETIRE - 5'd1));
            end
        end
    end

    assign o_word_done = word_last;
    assign o_saturated = done;

    // P: the retire count never exceeds 20, although the register admits 31.
    always @(posedge i_clk)
        assert (retired <= MAX_RETIRE);
endmodule

module issue_token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire [1:0] i_req,     // dual-issue: 0, 1 or 2 slots want to issue
    output wire [1:0] o_grant,   // slots actually granted this cycle
    output reg  [3:0] tokens     // credits left in the bucket
);
    localparam [3:0] BURST  = 4'd8;   // bucket capacity
    localparam [2:0] PERIOD = 3'd5;   // refill timer period

    // thermometer-coded shadow of the bucket occupancy
    reg [7:0] bucket;
    // refill timer
    reg [2:0] tick_cnt;

    initial begin
        tokens   = 4'd0;
        bucket   = 8'h00;
        tick_cnt = 3'd0;
    end

    wire       tick    = (tick_cnt == PERIOD);
    wire [1:0] req_c   = (i_req == 2'd3) ? 2'd2 : i_req;

    // grants are limited by available credits
    wire [1:0] n_drain = (tokens >= {2'b00, req_c}) ? req_c : tokens[1:0];

    // refill one credit per timer tick, capped at the burst size
    wire       do_ref  = tick && (tokens != BURST);

    wire [7:0] b_ref   = do_ref ? {bucket[6:0], 1'b1} : bucket;
    wire [7:0] b_nxt   = b_ref >> n_drain;
    wire [3:0] t_nxt   = tokens + (do_ref ? 4'd1 : 4'd0) - {2'b00, n_drain};

    assign o_grant = i_ce ? n_drain : 2'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens   <= 4'd0;
            bucket   <= 8'h00;
            tick_cnt <= 3'd0;
        end else if (i_ce) begin
            tokens   <= t_nxt;
            bucket   <= b_nxt;
            tick_cnt <= tick ? 3'd0 : (tick_cnt + 3'd1);
        end
    end

    // P: whenever the credit counter reads empty, the thermometer shadow
    //    of the bucket must be empty as well.
    always @(posedge clk)
        if (tokens == 4'd0)
            assert (bucket == 8'h00);

endmodule

module wdt_absence (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       arm,       // Q: opens the window
    input  wire       disarm,    // R: closes the window (may never arrive)
    input  wire       kick,      // pet the watchdog
    output reg  [3:0] cnt,
    output reg        expired,
    output reg        safe,
    output reg        armed
);
    localparam [3:0] LIMIT = 4'd10;  // timeout value
    localparam [3:0] WARN  = 4'd8;   // below this the timer is in the safe zone

    initial cnt     = 4'd0;
    initial expired = 1'b0;
    initial safe    = 1'b1;
    initial armed   = 1'b0;

    always @(posedge clk) begin
        if (i_ce) begin
            // window register: set by arm, cleared by disarm
            if (arm)
                armed <= 1'b1;
            else if (disarm)
                armed <= 1'b0;

            // the watchdog only runs inside the window
            if (armed) begin
                if (kick) begin
                    cnt     <= 4'd0;
                    expired <= 1'b0;
                    safe    <= 1'b1;
                end else if (cnt == LIMIT) begin
                    cnt     <= LIMIT;      // saturate at the timeout
                    expired <= 1'b1;
                    safe    <= 1'b0;
                end else begin
                    cnt     <= cnt + 4'd1;
                    expired <= expired || ((cnt + 4'd1) == LIMIT); // sticky
                    safe    <= ((cnt + 4'd1) < WARN);
                end
            end
        end
    end

    // P: once armed (and until disarmed, if ever), the timer can never report
    // both "expired" and "safe" at the same time.
    always @(*)
        if (armed)
            assert (!(expired && safe));
endmodule

module credit_pool (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // step enable: low leaves all state unchanged
    input  wire i_take,    // 1 = take a credit, 0 = give one back
    output wire o_full,
    output wire o_empty,
    output wire [3:0] o_used,
    output wire [3:0] o_avail
);
    localparam [3:0] CAP = 4'd12;

    // up counter: credits handed out
    reg [3:0] used;
    // down counter: credits still on the shelf
    reg [3:0] avail;

    initial used  = 4'd0;
    initial avail = CAP;

    wire take_fire = i_ce &&  i_take && (used != CAP);
    wire give_fire = i_ce && !i_take && (used != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            used  <= 4'd0;
            avail <= CAP;
        end else if (take_fire) begin
            used  <= used  + 4'd1;   // stepped up
            avail <= avail - 4'd1;   // stepped down, same enable
        end else if (give_fire) begin
            used  <= used  - 4'd1;
            avail <= avail + 4'd1;
        end
    end

    assign o_full  = (avail == 4'd0);
    assign o_empty = (used  == 4'd0);
    assign o_used  = used;
    assign o_avail = avail;

    // P: whenever the shelf is empty, every credit of the pool is out on loan
    always @(posedge clk)
        if (avail == 4'd0)
            assert (used == CAP);
endmodule

module clock_pend_track (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,     // the running side's clock tick
    input  wire i_start,  // Q: press starts the side's clock (opens window)
    input  wire i_stop,   // R: flag falls / press stops it (closes window)
    input  wire i_req,    // a new move-timing request enters the pipeline
    output wire o_done
);
    // in-flight request pipeline plus a separate count of its set bits
    reg [7:0] pend;
    reg [3:0] cnt;
    reg       armed;   // window register: set by i_start, cleared by i_stop

    initial pend  = 8'h00;
    initial cnt   = 4'd0;
    initial armed = 1'b0;

    always @(posedge clk) begin
        if (i_rst) begin
            pend  <= 8'h00;
            cnt   <= 4'd0;
            armed <= 1'b0;
        end else begin
            if (i_start)
                armed <= 1'b1;
            else if (i_stop)
                armed <= 1'b0;

            // state only advances while the side's clock is actually running
            if (armed && i_ce) begin
                pend <= { pend[6:0], i_req };
                cnt  <= cnt + { 3'b000, i_req } - { 3'b000, pend[7] };
            end
        end
    end

    assign o_done = armed && i_ce && pend[7];

    // P (two assertions, both inside the open window)
    always @(posedge clk)
        if (armed)
            assert (cnt != 4'd0 || pend == 8'h00);

    always @(posedge clk)
        if (armed)
            assert (cnt != 4'd8 || pend == 8'hFF);
endmodule

module deb_evt_fifo (
    input  wire clk,
    input  wire i_ce,      // sample enable: low freezes all state
    input  wire raw,       // raw (noisy) button level
    input  wire pop,       // consumer request
    output wire empty,
    output wire full,
    output reg  o_level    // last popped debounced level
);
    // ---- debouncer: saturating stability counter ----
    reg [1:0] stab;
    reg       deb;

    // ---- event FIFO: pointers + occupancy ----
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg [1:0] tail;        // shadow: write pointer snapshot taken at the last push
    reg       mem [0:3];

    // ---- scope register: high until the FIFO has ever been full ----
    reg       never_full;

    // ---- past-valid ----
    reg       pv;

    initial begin
        stab = 2'd0; deb = 1'b0;
        wptr = 2'd0; rptr = 2'd0; count = 3'd0;
        tail = 2'd0;
        never_full = 1'b1;
        pv = 1'b0;
        o_level = 1'b0;
        mem[0] = 1'b0; mem[1] = 1'b0; mem[2] = 1'b0; mem[3] = 1'b0;
    end

    assign empty = (count == 3'd0);
    assign full  = (count == 3'd4);

    // a debounced edge is committed once raw has disagreed with deb for 3 samples
    wire deb_commit = (raw != deb) && (stab == 2'd2);

    wire do_push = i_ce && deb_commit && !full;
    wire do_pop  = i_ce && pop && !empty;

    always @(posedge clk) begin
        if (i_ce) begin
            if (raw != deb) begin
                if (stab == 2'd2) stab <= 2'd0;
                else              stab <= stab + 2'd1;
            end else begin
                stab <= 2'd0;
            end
            if (deb_commit) deb <= raw;

            if (do_push) begin
                mem[wptr] <= raw;
                wptr      <= wptr + 2'd1;
                tail      <= wptr + 2'd1;
            end

            if (do_pop) begin
                o_level <= mem[rptr];
                rptr    <= rptr + 2'd1;
            end

            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase

            if (count == 3'd4) never_full <= 1'b0;
        end
        pv <= 1'b1;
    end

    // Precedence, before-first-full scope, stated about the previous cycle:
    // if the queue has just been drained empty by a pop, the read pointer must
    // have reached the write-pointer snapshot recorded at the earlier push.
    always @(posedge clk)
        if (pv && never_full && (count == 3'd0) && $past(do_pop))
            assert (rptr == $past(tail));
endmodule

module seq_detect_1011 (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output wire       match,
    output wire [3:0] hits
);
    // fixed pattern, MSB first: 1 0 1 1
    localparam [3:0] PAT = 4'b1011;

    // match-progress register: number of leading pattern bits matched so far,
    // never exceeds the pattern length (4)
    reg [2:0] prog;
    // shadow register: records that progress 3 (pattern prefix 101) was
    // observed at some earlier cycle
    reg       saw_p3;
    // saturating count of completed pattern matches consumed
    reg [3:0] match_count;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
    wire       restart  = (din == PAT[3]) ? 1'b1 : 1'b0;

    assign match = (prog == 3'd4);
    assign hits  = match_count;

    always @(posedge clk) begin
        if (rst) begin
            prog        <= 3'd0;
            saw_p3      <= 1'b0;
            match_count <= 4'd0;
        end else if (ce) begin
            // shadow bit latches the earlier occurrence of progress 3
            saw_p3 <= saw_p3 | (prog == 3'd3);

            if (prog == 3'd4) begin
                // consume the completed match, then begin a fresh scan
                match_count <= (match_count == 4'd15) ? 4'd15 : match_count + 4'd1;
                prog        <= restart ? 3'd1 : 3'd0;
            end else if (din == exp_bit) begin
                prog <= prog + 3'd1;
            end else begin
                prog <= restart ? 3'd1 : 3'd0;
            end
        end
    end

    // Precedence, global: any counted match must have been preceded by the
    // pattern prefix reaching progress 3.
    assert property (match_count == 4'd0 || saw_p3);
endmodule

// Debug-probe challenge sequencer: a maximal-length LFSR supplies one tick per
// chain step (arm -> start -> finish). The LFSR is seeded non-zero and can never
// enter the all-zeros lockup state, so every FSM advance is accompanied by a
// genuine change of the challenge shift register.
module probe_chain_seq (
    input  wire       clk,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire       arm,
    input  wire       start,
    input  wire       fin,
    output reg  [1:0] stage,
    output reg        pre_done,
    output reg  [3:0] chal
);
    // stage encoding: 0 = IDLE, 1 = ARMED, 2 = RUNNING, 3 = DONE
    reg [3:0] lfsr;
    reg       pv;

    initial lfsr     = 4'b0001;
    initial chal     = 4'b0000;
    initial stage    = 2'd0;
    initial pre_done = 1'b1;   // before-scope: high until the first DONE ever
    initial pv       = 1'b0;

    // x^4 + x^3 + 1 : period 15 over the non-zero states
    wire       fb        = lfsr[3] ^ lfsr[2];
    wire [3:0] lfsr_next = {lfsr[2:0], fb};

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            lfsr <= lfsr_next;
            case (stage)
                2'd0: if (arm) begin
                          stage <= 2'd1;
                          chal  <= lfsr;      // latch the challenge word on arm
                      end
                2'd1: if (start) stage <= 2'd2;
                2'd2: if (fin) begin
                          stage    <= 2'd3;   // finish: clears the before-scope
                          pre_done <= 1'b0;
                      end
                default: stage <= 2'd0;
            endcase
        end
    end

    // P: before the first finish has ever been observed, the chain FSM cannot
    //    move unless the challenge shift register moved with it.
    always @(posedge clk)
        if (pv && pre_done && $stable(lfsr))
            assert ($stable(stage));
endmodule

module notebook_cell_arbiter (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire [7:0] i_req,
    output wire [2:0] o_idx,
    output wire       o_valid
);
    // Stage 1: registered priority-encoder result
    reg [2:0] idx;
    reg       valid;
    // Stage 2: exported result (index only meaningful while valid2 is set)
    reg [2:0] idx2;
    reg       valid2;
    // Shadow register: sticky history of every cell that has ever requested
    reg [7:0] hist;
    // Sticky arm: set the first time any cell requests service
    reg       arm;

    initial idx    = 3'd0;
    initial valid  = 1'b0;
    initial idx2   = 3'd0;
    initial valid2 = 1'b0;
    initial hist   = 8'h00;
    initial arm    = 1'b0;

    function [2:0] penc(input [7:0] r);
        begin
            if      (r[0]) penc = 3'd0;
            else if (r[1]) penc = 3'd1;
            else if (r[2]) penc = 3'd2;
            else if (r[3]) penc = 3'd3;
            else if (r[4]) penc = 3'd4;
            else if (r[5]) penc = 3'd5;
            else if (r[6]) penc = 3'd6;
            else if (r[7]) penc = 3'd7;
            else           penc = 3'd0;
        end
    endfunction

    always @(posedge clk) begin
        if (i_reset) begin
            idx    <= 3'd0;
            valid  <= 1'b0;
            idx2   <= 3'd0;
            valid2 <= 1'b0;
            hist   <= 8'h00;
            arm    <= 1'b0;
        end else if (i_ce) begin
            // stage 2 takes last cycle's encode
            idx2   <= idx;
            valid2 <= valid;
            // stage 1 encodes the current request vector
            idx    <= penc(i_req);
            valid  <= |i_req;
            // shadow history grows in the same cycle as the encode
            hist   <= hist | i_req;
            if (|i_req)
                arm <= 1'b1;
        end
    end

    assign o_idx   = idx2;
    assign o_valid = valid2;

    // Precedence, after arm: a published index must name a cell that
    // requested service at some earlier time.
    always @(posedge clk)
        if (arm && valid2)
            assert (hist[idx2]);
endmodule

module wdog_gray_mon (
    input  wire i_clk,
    input  wire i_rst,
    input  wire i_ce,      // idle condition: all state frozen when low
    input  wire i_arm,     // Q: opens the monitoring window
    input  wire i_ack,     // R: closes the monitoring window
    output wire o_bite,
    output wire o_grace,
    output wire o_sys_reset
);
    // ---- timer domain: free running gray coded tick pointer -------------
    reg [2:0] cnt;   // binary tick counter
    reg [2:0] g;     // registered gray code of cnt

    // ---- monitor domain: two flop synchronizer on the gray pointer ------
    reg [2:0] s1, s2;

    // ---- window / latched reset ----------------------------------------
    reg armed;
    reg rst_latch;

    initial cnt       = 3'd0;
    initial g         = 3'd0;
    initial s1        = 3'd0;
    initial s2        = 3'd0;
    initial armed     = 1'b0;
    initial rst_latch = 1'b0;

    wire [2:0] nxt = cnt + 3'd1;

    always @(posedge i_clk)
        if (i_rst) begin
            cnt <= 3'd0;
            g   <= 3'd0;
        end else if (i_ce) begin
            cnt <= nxt;
            g   <= nxt ^ (nxt >> 1);
        end

    always @(posedge i_clk)
        if (i_rst) begin
            s1 <= 3'd0;
            s2 <= 3'd0;
        end else if (i_ce) begin
            s1 <= g;    // first flop: freshly captured pointer
            s2 <= s1;   // second flop: stable pointer sample
        end

    // gray -> binary decode of both synchronizer stages
    wire [2:0] mon = { s2[2], s2[2]^s2[1], s2[2]^s2[1]^s2[0] };
    wire [2:0] pre = { s1[2], s1[2]^s1[1], s1[2]^s1[1]^s1[0] };

    // terminal count seen on the stable sample -> watchdog bites
    assign o_bite  = (mon == 3'd7);
    // deep inside the grace region on the freshly captured sample
    assign o_grace = (pre == 3'd2);

    assign o_sys_reset = rst_latch;

    always @(posedge i_clk)
        if (i_rst) begin
            armed     <= 1'b0;
            rst_latch <= 1'b0;
        end else if (i_ce) begin
            if (i_ack)      armed <= 1'b0;
            else if (i_arm) armed <= 1'b1;

            if (i_ack)                     rst_latch <= 1'b0;
            else if (armed && o_bite)      rst_latch <= 1'b1;
        end

    // P: inside the monitoring window the bite and grace indications are
    // never asserted together.
    always @(posedge i_clk)
        if (armed)
            assert (!(o_bite && o_grace));
endmodule

module credit_deadline (
    input  wire clk,
    input  wire i_ce,      // global enable: low => all state frozen
    input  wire rst,
    input  wire req,       // producer wants to spend a credit
    output wire grant,
    output wire busy
);
    localparam [2:0] TOTAL = 3'd4;   // configured credit pool

    // credits held by the producer, credits outstanding at the consumer
    reg [2:0] credits;
    reg [2:0] outst;
    // consumer needs two enabled cycles to retire one outstanding credit
    reg       svc;
    // bounded-response deadline countdown for the outstanding credits
    reg [3:0] timer;

    initial begin
        credits = 3'd4;
        outst   = 3'd0;
        svc     = 1'b0;
        timer   = 4'd0;
    end

    wire do_spend  = req && (credits != 3'd0);
    wire do_return = (outst != 3'd0) && (svc == 1'b1);

    assign grant = i_ce && do_spend;
    assign busy  = (outst != 3'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            if (rst) begin
                credits <= TOTAL;
                outst   <= 3'd0;
                svc     <= 1'b0;
                timer   <= 4'd0;
            end else begin
                // credit conservation: one token moves per event
                credits <= credits - (do_spend  ? 3'd1 : 3'd0)
                                   + (do_return ? 3'd1 : 3'd0);
                outst   <= outst   + (do_spend  ? 3'd1 : 3'd0)
                                   - (do_return ? 3'd1 : 3'd0);

                // two-cycle service phase per outstanding credit
                if (outst == 3'd0)
                    svc <= 1'b0;
                else
                    svc <= ~svc;

                // deadline budget: each spend buys 2 cycles, one cycle burnt
                timer <= timer - ((timer != 4'd0) ? 4'd1 : 4'd0)
                               + (do_spend ? 4'd2 : 4'd0);
            end
        end
    end

    // Bounded response (safety): the countdown must never expire while a
    // credit is still outstanding at the consumer.
    always @(posedge clk)
        if (outst != 3'd0)
            assert (timer != 4'd0);

endmodule

module credit_counter (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire increment,
    input wire decrement,
    output reg [2:0] count
);
    reg [1:0] wptr, rptr;
    initial begin wptr = 0; rptr = 0; count = 0; end

    wire do_increment = i_ce && increment && count != 3'd4;
    wire do_decrement = i_ce && decrement && count != 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 0; rptr <= 0; count <= 0;
        end else begin
            if (do_increment) wptr <= wptr + 1;
            if (do_decrement) rptr <= rptr + 1;
            case ({do_increment, do_decrement})
                2'b10:   count <= count + 1;
                2'b01:   count <= count - 1;
                default: count <= count;
            endcase
        end
    end

    always @(posedge clk)
        if (count == 3'd0)
            assert (wptr == rptr);

    always @(posedge clk)
        if (count == 3'd4)
            assert (wptr - rptr == 2'd4);
endmodule

module lfsr_counter (
    input wire clk,
    input wire rst,
    input wire enable,
    output reg [3:0] lfsr,
    output reg [2:0] countdown
);
    initial begin lfsr = 4'd3; countdown = 3'd0; end

    always @(posedge clk) begin
        if (rst) begin
            lfsr <= 4'd3;
            countdown <= 3'd0;
        end else if (enable) begin
            lfsr <= {lfsr[2:0], lfsr[3] ^ lfsr[1]};
            if (countdown > 3'd0)
                countdown <= countdown - 1;
            else
                countdown <= 3'd3;
        end
    end

    always @(*)
        if (countdown == 3'd0)
            assert (lfsr != 4'd0);
endmodule

module counter_pair (
    input wire clk,
    input wire rst,
    input wire enable,
    output reg [2:0] up_cnt,
    output reg [2:0] down_cnt
);
    initial begin up_cnt = 0; down_cnt = 4; end

    always @(posedge clk) begin
        if (rst) begin
            up_cnt <= 0;
            down_cnt <= 4;
        end else if (enable) begin
            up_cnt <= up_cnt + 1;
            down_cnt <= down_cnt - 1;
        end
    end

    reg pv = 0;
    always @(posedge clk) pv <= 1;

    always @(posedge clk) if (pv) assert (!$rose(up_cnt) || (up_cnt + down_cnt == 3'd4));
    always @(posedge clk) if (pv) assert (!$rose(down_cnt) || (up_cnt + down_cnt == 3'd4));
endmodule

module handshake (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire req,
    output wire ack,
    output reg busy
);
    reg [1:0] phase;
    initial phase = 2'b00;
    initial busy = 1'b0;

    always @(posedge clk)
        if (i_reset) begin
            phase <= 2'b00;
            busy <= 1'b0;
        end else if (i_ce) begin
            case (phase)
                2'b00: if (req) begin
                           phase <= 2'b01;
                           busy <= 1'b1;
                       end
                2'b01: phase <= 2'b10;
                2'b10: phase <= 2'b11;
                2'b11: if (ack) begin
                           phase <= 2'b00;
                           busy <= 1'b0;
                       end
            endcase
        end

    assign ack = (phase == 2'b11);

    always @(posedge clk)
        if (busy && !req)
            assert (phase != 2'b00);
endmodule

module saturating_counter (
    input wire clk,
    input wire rst,
    input wire step,
    input wire trigger,
    output reg [1:0] count,
    output reg armed
);
    initial begin
        count = 2'd0;
        armed = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            count <= 2'd0;
            armed <= 1'b0;
        end else begin
            if (trigger)
                armed <= 1'b1;
            if (step && !armed)
                count <= (count == 2'd2) ? 2'd2 : count + 1;
        end
    end

    always @(posedge clk)
        if (armed)
            assert (count <= 2'd2);

    always @(posedge clk)
        if (armed)
            assert (count != 2'd3);
endmodule

module counter (
    input wire clk,
    input wire rst,
    input wire enable,
    input wire trigger,
    output reg [3:0] up_count,
    output reg [3:0] down_count,
    output reg arm
);
    initial begin up_count = 4'd0; down_count = 4'd5; arm = 1'b0; end

    always @(posedge clk) begin
        if (rst) begin
            up_count <= 4'd0; down_count <= 4'd5; arm <= 1'b0;
        end else begin
            if (trigger && !arm) arm <= 1'b1;
            if (enable) begin
                up_count <= up_count + 1;
                down_count <= down_count - 1;
            end
        end
    end

    always @(*)
        if (arm)
            assert (up_count != down_count);
endmodule

module onehot_fsm (
    input wire clk,
    input wire rst,
    input wire enable,
    input wire [1:0] next_state_sel,
    output reg [3:0] state
);
    initial state = 4'b0001;

    always @(posedge clk) begin
        if (rst)
            state <= 4'b0001;
        else if (enable) begin
            case (next_state_sel)
                2'b00: state <= 4'b0001;
                2'b01: state <= 4'b0010;
                2'b10: state <= 4'b0100;
                2'b11: state <= 4'b1000;
            endcase
        end
    end

    always @(posedge clk)
        if (enable) assert (!(state[0] && state[1]) && !(state[0] && state[2]) && !(state[0] && state[3]) && !(state[1] && state[2]) && !(state[1] && state[3]) && !(state[2] && state[3]));

    always @(posedge clk) if (enable) assert (state == 4'b0001 || state == 4'b0010 || state == 4'b0100 || state == 4'b1000);
endmodule

module fifo_checker (
    input wire i_clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_wr,
    input wire i_rd,
    output wire full,
    output wire empty
);
    parameter DEPTH = 8;
    reg [3:0] wptr, rptr, occ;
    initial wptr = 4'd0;
    initial rptr = 4'd0;
    initial occ = 4'd0;

    always @(posedge i_clk)
        if (i_reset) begin
            wptr <= 4'd0;
            rptr <= 4'd0;
            occ <= 4'd0;
        end else if (i_ce) begin
            case ({i_wr, i_rd})
                2'b00: ;
                2'b01: if (occ != 4'd0) begin
                        rptr <= rptr + 4'd1;
                        occ <= occ - 4'd1;
                     end
                2'b10: if (occ != 4'd8) begin
                        wptr <= wptr + 4'd1;
                        occ <= occ + 4'd1;
                     end
                2'b11: if (occ != 4'd0 && occ != 4'd8) begin
                        rptr <= rptr + 4'd1;
                        wptr <= wptr + 4'd1;
                     end
            endcase
        end

    assign full = (occ == 4'd8);
    assign empty = (occ == 4'd0);

    always @(posedge i_clk)
        if (i_ce)
            assert ((wptr - rptr) == occ);

    always @(posedge i_clk)
        if (i_ce)
            assert (occ <= 4'd8);

    always @(posedge i_clk)
        if (i_ce)
            assert (!(occ == 4'd8) || (wptr - rptr) == 4'd8);

    always @(posedge i_clk)
        if (i_ce)
            assert (!(occ == 4'd0) || (wptr == rptr));

    always @(posedge i_clk)
        if (i_ce)
            assert (occ != 4'd1 || ((wptr - rptr) == 4'd1));

    always @(posedge i_clk)
        if (i_ce)
            assert (occ != 4'd2 || ((wptr - rptr) == 4'd2));

    always @(posedge i_clk)
        if (i_ce)
            assert (occ != 4'd3 || ((wptr - rptr) == 4'd3));

    always @(posedge i_clk)
        if (i_ce)
            assert (occ != 4'd4 || ((wptr - rptr) == 4'd4));

    always @(posedge i_clk)
        if (i_ce)
            assert (occ != 4'd5 || ((wptr - rptr) == 4'd5));

    always @(posedge i_clk)
        if (i_ce)
            assert (occ != 4'd6 || ((wptr - rptr) == 4'd6));

    always @(posedge i_clk)
        if (i_ce)
            assert (occ != 4'd7 || ((wptr - rptr) == 4'd7));

    always @(posedge i_clk)
        if (i_ce)
            assert (occ != 4'd8 || ((wptr - rptr) == 4'd8));

    always @(posedge i_clk)
        if (i_ce)
            assert (!((wptr - rptr) > 4'd8));

    always @(posedge i_clk)
        if (i_ce)
            assert (!((wptr - rptr) < 4'd0));

    always @(posedge i_clk)
        if (i_ce)
            assert (!(occ == 4'd8) || full);

    always @(posedge i_clk)
        if (i_ce)
            assert (!(occ == 4'd0) || empty);
endmodule

module isqrt_handshake (
    input  wire              clk,
    input  wire              ce,      // idle condition: nothing moves when low
    input  wire              req,
    input  wire signed [7:0] din,
    output reg               ack,
    output reg               busy,
    output reg        [7:0]  result
);
    // magnitude of the (possibly negative) operand
    wire [7:0] mag   = din[7] ? (~din + 8'd1) : din;
    // number of reduction steps this request needs: structurally at most 7
    wire [3:0] steps = {1'b0, mag[2:0]};

    reg [3:0] work;   // reduction steps still to do
    reg [3:0] timer;  // completion budget (countdown)
    reg [7:0] acc;    // datapath scratch

    initial begin
        busy   = 1'b0;
        ack    = 1'b0;
        work   = 4'd0;
        timer  = 4'd0;
        acc    = 8'd0;
        result = 8'd0;
    end

    always @(posedge clk) begin
        if (ce) begin
            if (!busy && !ack) begin
                // phase 1: request accepted, busy mirrors the phase
                if (req) begin
                    busy  <= 1'b1;
                    work  <= steps;
                    timer <= 4'd11;   // budget strictly exceeds the work count
                    acc   <= mag;
                end
            end else if (busy) begin
                if (work != 4'd0) begin
                    work  <= work  - 4'd1;
                    timer <= timer - 4'd1;
                    acc   <= {1'b0, acc[7:1]};
                end else begin
                    // phase 2: completion, ack rises and busy drops
                    busy   <= 1'b0;
                    ack    <= 1'b1;
                    timer  <= 4'd0;
                    result <= acc;
                end
            end else begin
                // phase 3/4: ack held until req drops, then ack drops
                if (!req) ack <= 1'b0;
            end
        end
    end

    // Bounded response (safety form): the completion countdown must never
    // expire while a request is still outstanding.
    always @(*) begin
        if (busy) assert (timer != 4'd0);
    end
endmodule

module net_router_progress (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_route,
    input wire i_rip,
    output reg [3:0] routed,
    output reg [3:0] unrouted
);
    // Total number of nets in the board; every net is either routed or unrouted.
    localparam [3:0] TOTAL = 4'd12;

    initial routed   = 4'd0;
    initial unrouted = TOTAL;

    // One shared enable steps the up counter and the down counter together.
    wire do_route = i_ce && i_route && !i_rip   && (unrouted != 4'd0);
    wire do_rip   = i_ce && i_rip   && !i_route && (routed   != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            routed   <= 4'd0;
            unrouted <= TOTAL;
        end else if (do_route) begin
            routed   <= routed   + 4'd1;
            unrouted <= unrouted - 4'd1;
        end else if (do_rip) begin
            routed   <= routed   - 4'd1;
            unrouted <= unrouted + 4'd1;
        end
    end

    // P: the routed and unrouted net counts can only coincide at the half-way
    // mark, because together they always account for all TOTAL nets.
    always @(posedge clk)
        assert (routed != unrouted || routed == 4'd6);
endmodule

module surf_clk_div_frame (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire sync_in,
    output wire tick
);
    // Clock divider: 3-bit phase counter runs 0..4, the divided enable pulse
    // fires exactly on the phase wrap.  pcount counts divided pulses inside a
    // frame, total counts enabled cycles inside a frame; the two counters are
    // cross-reset (pcount clears on the total wrap, total clears on the fourth
    // divided pulse), so together they form a 20-cycle frame.

    reg [2:0] phase;
    reg [2:0] pcount;
    reg [4:0] total;
    reg       pre_sync;   // starts high, cleared the first time sync_in is taken

    initial phase    = 3'd0;
    initial pcount   = 3'd0;
    initial total    = 5'd0;
    initial pre_sync = 1'b1;

    assign tick = ce && (phase == 3'd4);

    wire do_sync = ce && sync_in;

    always @(posedge clk) begin
        if (rst) begin
            phase    <= 3'd0;
            pcount   <= 3'd0;
            total    <= 5'd0;
            pre_sync <= 1'b1;
        end else if (do_sync) begin
            phase    <= 3'd0;
            pcount   <= 3'd0;
            total    <= 5'd0;
            pre_sync <= 1'b0;
        end else if (ce) begin
            phase  <= (phase == 3'd4) ? 3'd0 : (phase + 3'd1);
            pcount <= (total == 5'd19) ? 3'd0 :
                      (tick ? (pcount + 3'd1) : pcount);
            total  <= (tick && (pcount == 3'd3)) ? 5'd0 : (total + 5'd1);
        end
    end

    // Bounded existence, before the first external sync:
    // at most four divided pulses and at most twenty enabled cycles per frame.
    always @(posedge clk) begin
        if (pre_sync) assert (pcount <= 3'd3);
        if (pre_sync) assert (total  <= 5'd19);
    end
endmodule

module pingpong_double_buffer (
    input  wire       clk,
    input  wire       rst,
    input  wire       wr_en,
    input  wire       rd_en,
    input  wire [7:0] wdata,
    output wire [7:0] rdata,
    output wire       wbank_full,
    output wire       rbank_empty
);
    // Two halves of an 8-entry RAM: half 0 is entries 0..3, half 1 is 4..7.
    // The writer owns half `wsel`, the reader owns half `rsel`; the two halves
    // are exchanged only when the write half is full and the read half drained.

    reg        wsel;
    reg        rsel;
    reg [2:0]  wcnt;
    reg [2:0]  rcnt;
    reg [7:0]  mem [0:7];

    initial begin
        wsel = 1'b0;
        rsel = 1'b1;
        wcnt = 3'd0;
        rcnt = 3'd4;   // reader's half starts empty (already drained)
    end

    wire wdone = (wcnt == 3'd4);
    wire rdone = (rcnt == 3'd4);
    wire swap  = wdone && rdone;

    wire [2:0] waddr = {wsel, wcnt[1:0]};
    wire [2:0] raddr = {rsel, rcnt[1:0]};

    assign wbank_full  = wdone;
    assign rbank_empty = rdone;
    assign rdata       = mem[raddr];

    always @(posedge clk) begin
        if (rst) begin
            wsel <= 1'b0;
            rsel <= 1'b1;
            wcnt <= 3'd0;
            rcnt <= 3'd4;
        end else if (swap) begin
            // hand the filled half to the reader, the drained half to the writer
            wsel <= ~wsel;
            rsel <= ~rsel;
            wcnt <= 3'd0;
            rcnt <= 3'd0;
        end else begin
            if (wr_en && !wdone) begin
                mem[waddr] <= wdata;
                wcnt <= wcnt + 3'd1;
            end
            if (rd_en && !rdone) begin
                rcnt <= rcnt + 3'd1;
            end
        end
    end

    // P: the write port and the read port never address the same RAM location.
    always @(posedge clk)
        assert (waddr != raddr);

endmodule

module fifo_deadline #(parameter DW = 8) (
    input wire clk,
    input wire rst,
    input wire step,
    input wire push,
    input wire [DW-1:0] wdata,
    output wire [DW-1:0] rdata,
    output wire o_pop,
    output wire full,
    output wire empty
);
    // service deadline: an accepted entry must be drained within K steps
    localparam [2:0] K = 3'd4;

    reg [2:0] wptr  = 3'd0;
    reg [2:0] rptr  = 3'd0;
    reg [2:0] count = 3'd0;   // occupancy, 0..4
    reg [2:0] timer = 3'd0;   // countdown to forced service

    reg [DW-1:0] mem [0:3];
    integer i;
    initial begin
        for (i = 0; i < 4; i = i + 1) mem[i] = {DW{1'b0}};
    end

    // derived flags
    assign full  = (count == 3'd4);
    assign empty = (wptr == rptr);

    wire do_push = step && push && !full;
    wire do_pop  = step && !empty && (timer == 3'd1);

    assign rdata = mem[rptr[1:0]];
    assign o_pop = do_pop;

    wire [2:0] count_nxt = count + (do_push ? 3'd1 : 3'd0)
                                 - (do_pop  ? 3'd1 : 3'd0);

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 3'd0;
            rptr  <= 3'd0;
            count <= 3'd0;
            timer <= 3'd0;
        end else if (step) begin
            if (do_push) begin
                mem[wptr[1:0]] <= wdata;
                wptr <= wptr + 3'd1;
            end
            if (do_pop)
                rptr <= rptr + 3'd1;

            count <= count_nxt;

            if (count_nxt == 3'd0)
                timer <= 3'd0;                 // nothing outstanding
            else if (do_pop || (count == 3'd0))
                timer <= K;                    // fresh deadline granted
            else
                timer <= timer - 3'd1;         // tick toward forced service
        end
    end

    // P: the countdown never expires while an entry is still outstanding
    always @(posedge clk)
        if (count != 3'd0)
            assert (timer != 3'd0);

endmodule

module dma_burst_engine (
    input  wire       clk,
    input  wire       ce,      // global enable: low => all state frozen
    input  wire       start,
    input  wire [4:0] len_in,
    input  wire       resp,    // a beat response returns
    output reg        busy
);
    // beats still to be issued in the current burst
    reg [4:0] beats_rem = 5'd0;
    // outstanding (issued, not yet responded) beats
    reg [3:0] outst     = 4'd0;
    // free issue slots; by construction outst + credits == 4
    reg [3:0] credits   = 4'd4;

    initial busy = 1'b0;

    // burst length is clamped to the engine maximum of 12 beats
    wire [4:0] len_cap = (len_in > 5'd12) ? 5'd12 : len_in;

    wire do_load  = ce && !busy && start && (len_cap != 5'd0);
    wire do_issue = ce &&  busy && (credits != 4'd0);
    wire do_resp  = ce &&  resp && (outst   != 4'd0);

    // beats-remaining counter and busy flag
    always @(posedge clk) begin
        if (do_load) begin
            beats_rem <= len_cap;
            busy      <= 1'b1;
        end else if (do_issue) begin
            beats_rem <= beats_rem - 5'd1;
            if (beats_rem == 5'd1)
                busy <= 1'b0;
        end
    end

    // outstanding / credit bookkeeping
    always @(posedge clk) begin
        if (do_issue && !do_resp) begin
            outst   <= outst   + 4'd1;
            credits <= credits - 4'd1;
        end else if (do_resp && !do_issue) begin
            outst   <= outst   - 4'd1;
            credits <= credits + 4'd1;
        end
    end

    // P: while the engine is busy, at most 4 beats are ever outstanding
    always @(posedge clk)
        if (busy)
            assert (outst <= 4'd4);
endmodule

module gray_sync_pointer (
    input wire clk,
    input wire i_ce,
    input wire inc,
    output wire [3:0] o_ptr
);
    // source-domain binary pointer and its registered gray encoding
    reg [3:0] bin;
    reg [3:0] gray_r;
    // two-flop synchronizer carrying the gray pointer to the other domain
    reg [3:0] sync1;
    reg [3:0] sync2;

    initial begin
        bin    = 4'd0;
        gray_r = 4'd0;
        sync1  = 4'd0;
        sync2  = 4'd0;
    end

    wire [3:0] bin_nxt  = inc ? (bin + 4'd1) : bin;
    wire [3:0] gray_nxt = bin_nxt ^ (bin_nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            bin    <= bin_nxt;
            gray_r <= gray_nxt;
            sync1  <= gray_r;
            sync2  <= sync1;
        end
    end

    assign o_ptr = sync2;

    // difference between the two consecutive samples held in the chain
    wire [3:0] diff = sync1 ^ sync2;

    // P: whenever the synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (sync1 != sync2)
            assert ((diff & (diff - 4'd1)) == 4'd0);
endmodule

module tmr_token_bucket (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_req,
    input  wire       i_fill,
    output wire       o_grant,
    output wire [3:0] o_tokens
);
    // triple-modular-redundant token counters
    reg [3:0] tokA, tokB, tokC;
    initial tokA = 4'd0;
    initial tokB = 4'd0;
    initial tokC = 4'd0;

    // bitwise majority voter
    wire [3:0] votes = (tokA & tokB) | (tokA & tokC) | (tokB & tokC);

    // spend decision is taken off copy A
    wire take  = i_req && (tokA != 4'd0);
    wire grant = i_ce && take;

    // shadow register recording that a grant was issued earlier
    reg grant_q;
    initial grant_q = 1'b0;

    reg pv;
    initial pv = 1'b0;

    always @(posedge i_clk) begin
        if (i_reset) begin
            tokA <= 4'd0;
            tokB <= 4'd0;
            tokC <= 4'd0;
        end else if (i_ce) begin
            tokA <= (take && (tokA != 4'd0))  ? (tokA - 4'd1)
                  : ((i_fill && !take && (tokA != 4'd15)) ? (tokA + 4'd1) : tokA);
            tokB <= (take && (tokB != 4'd0))  ? (tokB - 4'd1)
                  : ((i_fill && !take && (tokB != 4'd15)) ? (tokB + 4'd1) : tokB);
            tokC <= (take && (tokC != 4'd0))  ? (tokC - 4'd1)
                  : ((i_fill && !take && (tokC != 4'd15)) ? (tokC + 4'd1) : tokC);
        end
    end

    always @(posedge i_clk) begin
        if (i_reset)
            grant_q <= 1'b0;
        else
            grant_q <= grant;
    end

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_grant  = grant;
    assign o_tokens = votes;

    // Precedence: a grant recorded in the shadow register implies the voted
    // bucket was non-empty in the cycle the grant was issued.
    always @(posedge i_clk)
        if (pv && grant_q)
            assert ($past(votes) != 4'd0);
endmodule

module wifi_inflight_chain (
    input  wire clk,
    input  wire step,      // global enable / idle when low
    input  wire push,      // a new TX request enters the pipeline
    input  wire arm_cmd,   // CCA clear: arm the chain
    input  wire q_open,    // Q: opens the observation window
    input  wire r_close,   // R: closes the observation window
    output wire busy,
    output wire tx_done
);
    // shift register of in-flight requests + separate count of set bits
    reg [3:0] inflight   = 4'd0;
    reg [2:0] cnt        = 3'd0;

    // window register (Q opens, R closes), may be opened/closed repeatedly
    reg       win        = 1'b0;

    // chain state machine: 0 IDLE -> 1 ARMED -> 2 STARTED -> 3 FINISHED
    reg [1:0] stage      = 2'd0;
    reg       arm_seen   = 1'b0;
    reg       start_seen = 1'b0;
    reg       done_flag  = 1'b0;

    reg       pv         = 1'b0;

    assign busy    = (cnt != 3'd0);
    assign tx_done = done_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (step) begin
            // in-flight shift register and its population count
            inflight <= {inflight[2:0], push};
            cnt      <= cnt + (push ? 3'd1 : 3'd0) - (inflight[3] ? 3'd1 : 3'd0);

            if (!win) begin
                if (q_open) begin
                    win        <= 1'b1;
                    stage      <= 2'd0;
                    arm_seen   <= 1'b0;
                    start_seen <= 1'b0;
                    done_flag  <= 1'b0;
                end
            end else if (r_close) begin
                win       <= 1'b0;
                done_flag <= 1'b0;
            end else begin
                case (stage)
                    2'd0: if (arm_cmd) begin
                              stage    <= 2'd1;
                              arm_seen <= 1'b1;
                          end
                    2'd1: if (cnt != 3'd0) begin
                              stage      <= 2'd2;
                              start_seen <= 1'b1;
                          end
                    2'd2: if ((cnt == 3'd0) && !push) begin
                              stage     <= 2'd3;
                              done_flag <= 1'b1;
                          end
                    default: ;
                endcase
            end
        end
    end

    // Chain precedence, checked only inside the Q..R window, on the rising
    // edge of the finish indication.
    always @(posedge clk)
        if (pv && win && $rose(done_flag))
            assert (arm_seen && start_seen && (inflight == 4'd0));
endmodule

// Fixed-latency execution unit with an in-flight occupancy tracker.
// Issued operations march through a 4-deep valid shift register and retire
// from the last stage; the occupancy counter tracks how many are in flight.
module exu_inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       i_issue,   // issue a new operation this cycle
    input  wire [7:0] i_opnd,
    output wire       o_valid,
    output wire [7:0] o_res,
    output wire [2:0] o_inflight
);

    // latency shift register: one valid bit per pipeline stage
    reg [3:0] pipe;
    // payload pipeline riding alongside
    reg [7:0] d0, d1, d2, d3;
    // occupancy counter (3 bits wide: can hold up to 7)
    reg [2:0] inflight;

    initial begin
        pipe     = 4'b0000;
        d0       = 8'h00;
        d1       = 8'h00;
        d2       = 8'h00;
        d3       = 8'h00;
        inflight = 3'd0;
    end

    wire acc    = i_ce && i_issue;   // accepted issue this cycle
    wire retire = i_ce && pipe[3];   // operation leaving the last stage

    always @(posedge clk) begin
        if (rst) begin
            pipe     <= 4'b0000;
            d0       <= 8'h00;
            d1       <= 8'h00;
            d2       <= 8'h00;
            d3       <= 8'h00;
            inflight <= 3'd0;
        end else if (i_ce) begin
            pipe <= {pipe[2:0], i_issue};
            d0   <= i_opnd;
            d1   <= d0 + 8'd1;
            d2   <= d1 ^ 8'h5a;
            d3   <= d2;

            case ({acc, retire})
                2'b10:   inflight <= inflight + 3'd1;
                2'b01:   inflight <= inflight - 3'd1;
                default: inflight <= inflight;
            endcase
        end
    end

    assign o_valid    = pipe[3];
    assign o_res      = d3;
    assign o_inflight = inflight;

    // P: occupancy of a 4-stage fixed-latency unit never exceeds 4,
    //    even though the counter is 3 bits wide.
    always @(*)
        assert (inflight <= 3'd4);

endmodule

// Serial sequence detector for the fixed pattern 1011 (MSB first).
// prog = length of the longest suffix of the input stream that is a prefix
// of the pattern (KMP style match progress, never exceeds pattern length).
// hist is a shadow register holding the three most recently consumed bits.
// armed is a sticky register set the first time a full match is observed.
module seq_det_1011 (
    input  wire clk,
    input  wire ce,    // idle when low: no state changes at all
    input  wire din,
    output wire match,
    output wire armed_o
);
    reg [2:0] prog;   // match progress, 0..3
    reg [2:0] hist;   // shadow of last three consumed bits, hist[0] = newest
    reg       armed;  // sticky: first full pattern occurrence has happened
    reg       pv;     // past valid

    initial begin
        prog  = 3'd0;
        hist  = 3'b000;
        armed = 1'b0;
        pv    = 1'b0;
    end

    assign match   = ce && (prog == 3'd3) && din;
    assign armed_o = armed;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ce) begin
            hist <= {hist[1:0], din};
            case (prog)
                3'd0:    prog <= din ? 3'd1 : 3'd0;
                3'd1:    prog <= din ? 3'd1 : 3'd2;
                3'd2:    prog <= din ? 3'd3 : 3'd0;
                3'd3:    prog <= din ? 3'd1 : 3'd2;
                default: prog <= din ? 3'd1 : 3'd0;
            endcase
            if (match)
                armed <= 1'b1;
        end
    end

    // Property: once the detector has armed (a full 1011 was seen earlier),
    // whenever the shadow history of consumed bits did not change, the match
    // progress must not have changed either.
    always @(posedge clk)
        if (pv && armed && $stable(hist))
            assert ($stable(prog));
endmodule

module skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       flush,
    input  wire       in_valid,
    input  wire [7:0] in_data,
    input  wire       out_ready,
    output wire       in_ready,
    output wire       o_valid,
    output wire [7:0] o_data
);
    // pipeline stage output register
    reg        out_valid;
    reg [7:0]  out_data;
    // skid buffer: the word here is only meaningful while the stall flag is up
    reg        skid_valid;
    reg [7:0]  skid_data;
    // registered backpressure flag
    reg        stall;
    // scope arming register: high until the first flush ever happens
    reg        pre_flush;

    initial out_valid  = 1'b0;
    initial out_data   = 8'h00;
    initial skid_valid = 1'b0;
    initial skid_data  = 8'h00;
    initial stall      = 1'b0;
    initial pre_flush  = 1'b1;

    assign in_ready = !skid_valid;
    assign o_valid  = out_valid;
    assign o_data   = out_data;

    always @(posedge clk) begin
        if (rst) begin
            out_valid  <= 1'b0;
            out_data   <= 8'h00;
            skid_valid <= 1'b0;
            skid_data  <= 8'h00;
            stall      <= 1'b0;
            pre_flush  <= 1'b1;
        end else if (ce) begin
            if (flush) begin
                // flush drops the presented word but leaves the skid buffer alone;
                // this is the event that disarms the scope
                out_valid <= 1'b0;
                pre_flush <= 1'b0;
            end else begin
                stall <= out_valid && !out_ready;
                if (stall) begin
                    if (out_ready) begin
                        if (skid_valid) begin
                            out_data   <= skid_data;
                            out_valid  <= 1'b1;
                            skid_valid <= 1'b0;
                        end else begin
                            out_valid <= in_valid;
                            if (in_valid)
                                out_data <= in_data;
                        end
                    end else if (in_valid && !skid_valid) begin
                        skid_valid <= 1'b1;
                        skid_data  <= in_data;
                    end
                end else begin
                    if (out_ready || !out_valid) begin
                        out_valid <= in_valid;
                        if (in_valid)
                            out_data <= in_data;
                    end
                end
            end
        end
    end

    wire buf_occupied = skid_valid;
    wire stage_empty  = !out_valid;

    // Absence, in the scope before the first flush: the skid buffer is never
    // occupied at the same time as the output stage is empty.
    assert property (!pre_flush || !(buf_occupied && stage_empty));
endmodule

module flash_prog_fsm (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire [7:0] i_data,
    output reg  [7:0] o_data,
    output reg        o_rd,
    output reg        o_wr,
    output reg        busy
);
    // binary-encoded programmer FSM: 5 legal encodings out of 8
    localparam [2:0] S_IDLE  = 3'd0,
                     S_LOAD  = 3'd1,
                     S_SHIFT = 3'd2,
                     S_STORE = 3'd3,
                     S_FLUSH = 3'd4;

    reg [2:0] state;
    reg [7:0] latch;

    initial state  = S_IDLE;
    initial latch  = 8'h00;
    initial o_data = 8'h00;
    initial o_rd   = 1'b0;
    initial o_wr   = 1'b0;
    initial busy   = 1'b0;   // window register: set by start, cleared at FLUSH

    always @(posedge clk) begin
        if (ce) begin
            case (state)
                S_IDLE: begin
                    o_rd <= start;
                    o_wr <= 1'b0;
                    if (start) begin
                        state <= S_LOAD;
                        busy  <= 1'b1;
                    end
                end
                S_LOAD: begin
                    latch <= i_data;
                    o_rd  <= 1'b0;
                    o_wr  <= 1'b0;
                    state <= S_SHIFT;
                end
                S_SHIFT: begin
                    latch <= {latch[6:0], latch[7]};
                    o_rd  <= 1'b0;
                    o_wr  <= 1'b1;
                    state <= S_STORE;
                end
                S_STORE: begin
                    o_data <= latch;
                    o_rd   <= 1'b0;
                    o_wr   <= 1'b0;
                    state  <= S_FLUSH;
                end
                S_FLUSH: begin
                    o_rd  <= 1'b0;
                    o_wr  <= 1'b0;
                    busy  <= 1'b0;
                    state <= S_IDLE;
                end
                default: begin
                    // unreachable encodings 5/6/7: panic recovery drives both strobes
                    o_rd  <= 1'b1;
                    o_wr  <= 1'b1;
                    state <= S_IDLE;
                end
            endcase
        end
    end

    // Two assertions, both scoped to the open program window.
    always @(posedge clk) begin
        if (busy) assert (!(o_rd && o_wr));
        if (busy) assert (!o_wr || state == S_STORE);
    end
endmodule

module rr_coin_arbiter (
    input  wire       clk,
    input  wire       step,
    input  wire [3:0] req,
    output reg  [3:0] gnt,
    output reg  [3:0] last,
    output reg        armed,
    output reg  [5:0] credit,
    output reg        dispense
);
    // Four coin slots compete for the single credit accumulator port.
    // Slots 0,1 drop 5c pieces; slots 2,3 drop 10c pieces.

    initial gnt      = 4'b0000;
    initial last     = 4'b0001;
    initial armed    = 1'b0;
    initial credit   = 6'd0;
    initial dispense = 1'b0;

    // Cyclic priority picks, one per possible position of the last-grant token.
    wire [3:0] sel0 = req[1] ? 4'b0010 : req[2] ? 4'b0100 : req[3] ? 4'b1000 : req[0] ? 4'b0001 : 4'b0000;
    wire [3:0] sel1 = req[2] ? 4'b0100 : req[3] ? 4'b1000 : req[0] ? 4'b0001 : req[1] ? 4'b0010 : 4'b0000;
    wire [3:0] sel2 = req[3] ? 4'b1000 : req[0] ? 4'b0001 : req[1] ? 4'b0010 : req[2] ? 4'b0100 : 4'b0000;
    wire [3:0] sel3 = req[0] ? 4'b0001 : req[1] ? 4'b0010 : req[2] ? 4'b0100 : req[3] ? 4'b1000 : 4'b0000;

    // Round-robin next grant: token in `last` selects which pick is used.
    wire [3:0] nxt = (last[0] ? sel0 : 4'b0000) |
                     (last[1] ? sel1 : 4'b0000) |
                     (last[2] ? sel2 : 4'b0000) |
                     (last[3] ? sel3 : 4'b0000);

    // Coin value of the winning slot (priority-coded so it is at most 10c).
    wire [5:0] coin = (nxt[0] | nxt[1]) ? 6'd5 : ((nxt[2] | nxt[3]) ? 6'd10 : 6'd0);
    wire [6:0] sum  = {1'b0, credit} + {1'b0, coin};

    always @(posedge clk) begin
        if (step) begin
            gnt <= nxt;
            if (|nxt) begin
                last  <= nxt;
                armed <= 1'b1;   // sticky: set the first time a grant is issued
            end
            if (sum >= 7'd25) begin
                credit   <= sum[5:0] - 6'd25;
                dispense <= 1'b1;
            end else begin
                credit   <= sum[5:0];
                dispense <= 1'b0;
            end
        end
    end

    // Once the arbiter has ever granted, two coin slots must never be
    // granted the accumulator port at the same time.
    always @(*)
        assert (!armed || !(gnt[0] && gnt[2]));
endmodule

module fourphase_arb (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire start_a,
    input  wire start_b,
    input  wire clr_mon,
    output wire o_busy,
    output wire o_mon
);
    // Two four-phase req/ack channels sharing one resource.
    // Per channel the phase walks:
    //   idle : busy=0 req=0 ack=0   -- grant -> busy=1
    //   P1   : busy=1 req=0 ack=0   -- raise req
    //   P2   : busy=1 req=1 ack=0   -- raise ack
    //   P3   : busy=1 req=1 ack=1   -- drop req (req may not drop before ack)
    //   P4   : busy=1 req=0 ack=1   -- drop ack, release busy
    reg req_a, ack_a, busy_a;
    reg req_b, ack_b, busy_b;

    // window register: armed by the first completed handshake (Q),
    // closed only by clr_mon while the resource is free (R, may never arrive)
    reg mon;

    initial begin
        req_a  = 1'b0;
        ack_a  = 1'b0;
        busy_a = 1'b0;
        req_b  = 1'b0;
        ack_b  = 1'b0;
        busy_b = 1'b0;
        mon    = 1'b0;
    end

    // arbiter: a channel may only be granted when neither channel is busy,
    // channel A has priority
    wire grant_a = start_a && !busy_a && !busy_b;
    wire grant_b = start_b && !busy_b && !busy_a && !start_a;

    // a channel is finishing this cycle (ack about to fall, busy released)
    wire fin_a = busy_a && !req_a && ack_a;
    wire fin_b = busy_b && !req_b && ack_b;

    always @(posedge clk) begin
        if (rst) begin
            req_a  <= 1'b0;
            ack_a  <= 1'b0;
            busy_a <= 1'b0;
            req_b  <= 1'b0;
            ack_b  <= 1'b0;
            busy_b <= 1'b0;
            mon    <= 1'b0;
        end else if (ce) begin
            // ---- channel A phase walk ----
            if (!busy_a && !req_a && !ack_a) begin
                if (grant_a)
                    busy_a <= 1'b1;
            end else if (busy_a && !req_a && !ack_a) begin
                req_a <= 1'b1;
            end else if (busy_a && req_a && !ack_a) begin
                ack_a <= 1'b1;
            end else if (busy_a && req_a && ack_a) begin
                req_a <= 1'b0;
            end else if (busy_a && !req_a && ack_a) begin
                ack_a  <= 1'b0;
                busy_a <= 1'b0;
            end

            // ---- channel B phase walk ----
            if (!busy_b && !req_b && !ack_b) begin
                if (grant_b)
                    busy_b <= 1'b1;
            end else if (busy_b && !req_b && !ack_b) begin
                req_b <= 1'b1;
            end else if (busy_b && req_b && !ack_b) begin
                ack_b <= 1'b1;
            end else if (busy_b && req_b && ack_b) begin
                req_b <= 1'b0;
            end else if (busy_b && !req_b && ack_b) begin
                ack_b  <= 1'b0;
                busy_b <= 1'b0;
            end

            // ---- monitoring window ----
            if (fin_a || fin_b)
                mon <= 1'b1;
            else if (clr_mon && !busy_a && !busy_b)
                mon <= 1'b0;
        end
    end

    assign o_busy = busy_a || busy_b;
    assign o_mon  = mon;

    // P: once the monitoring window has opened, the two channels never both
    // drive a request, and never both drive an acknowledge.
    always @(posedge clk)
        if (mon)
            assert (!(req_a && req_b));

    always @(posedge clk)
        if (mon)
            assert (!(ack_a && ack_b));
endmodule

module nest_depth_tracker (
    input  wire       clk,
    input  wire       ce,        // idle when low: no token consumed
    input  wire       tok_open,  // '(' style token
    input  wire       tok_close, // ')' style token
    output reg  [3:0] depth,     // current nesting depth (stack pointer)
    output reg  [3:0] mark       // high-water mark of nesting depth
);
    localparam [3:0] MAXD = 4'd8;

    initial depth = 4'd0;
    initial mark  = 4'd0;

    wire do_push = ce && tok_open && !tok_close && (depth < MAXD);
    wire do_pop  = ce && tok_close && !tok_open && (depth != 4'd0);

    always @(posedge clk) begin
        if (do_push) begin
            depth <= depth + 4'd1;
            // mark never falls, only ratchets upward
            if ((depth + 4'd1) > mark)
                mark <= depth + 4'd1;
        end else if (do_pop) begin
            depth <= depth - 4'd1;
            mark  <= mark;
        end else begin
            depth <= depth;
            mark  <= mark;
        end
    end

    // past-valid register so cycle zero is not judged
    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Precedence: a non-empty nesting depth observed now must have been
    // preceded by a high-water mark that was already within one of it.
    always @(posedge clk)
        if (pv && (depth != 4'd0))
            assert (depth <= $past(mark) + 4'd1);
endmodule

module credit_chain_guard (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire arm_req,
    input  wire send_req,
    input  wire ret_req,
    input  wire fin_req,
    output wire o_finish,
    output wire [3:0] o_credits
);
    // Credit pool: the producer spends a credit per outstanding transfer,
    // the consumer returns it.  free credits + outstanding credits == TOTAL.
    localparam [3:0] TOTAL   = 4'd8;
    localparam [1:0] PH_IDLE = 2'd0,
                     PH_ARM  = 2'd1,
                     PH_RUN  = 2'd2,
                     PH_DONE = 2'd3;

    reg [1:0] phase;
    reg [3:0] credits;
    reg [3:0] outstanding;
    reg       start_seen;
    reg       armed;        // sticky: set the first time an arm request is taken

    initial phase       = PH_IDLE;
    initial credits     = TOTAL;
    initial outstanding = 4'd0;
    initial start_seen  = 1'b0;
    initial armed       = 1'b0;

    wire do_send = send_req && ((phase == PH_ARM) || (phase == PH_RUN)) && (credits != 4'd0);
    wire do_ret  = ret_req  && (outstanding != 4'd0);
    wire do_fin  = fin_req  && (phase == PH_RUN) && (outstanding == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            phase       <= PH_IDLE;
            credits     <= TOTAL;
            outstanding <= 4'd0;
            start_seen  <= 1'b0;
        end else if (ce) begin
            if (arm_req) begin
                if (phase == PH_IDLE)
                    phase <= PH_ARM;
            end else if (do_send) begin
                credits     <= credits - 4'd1;
                outstanding <= outstanding + 4'd1;
                start_seen  <= 1'b1;
                phase       <= PH_RUN;
            end else if (do_ret) begin
                outstanding <= outstanding - 4'd1;
                credits     <= credits + 4'd1;
            end else if (do_fin) begin
                phase <= PH_DONE;
            end
        end
    end

    // sticky arm register, never cleared once set
    always @(posedge clk)
        if (ce && arm_req)
            armed <= 1'b1;

    assign o_finish  = (phase == PH_DONE);
    assign o_credits = credits;

    // After the session has been armed: a finish can only be observed if the
    // start step really happened and every spent credit has come back.
    always @(*)
        if (armed)
            assert (!o_finish || (start_seen && (credits == TOTAL)));
endmodule

module pwm_duty_accum (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [3:0] duty_in,
    output wire       pwm_out,
    output wire [3:0] on_cycles
);
    // 8-cycle PWM period: cnt runs 0..7, output high exactly while cnt < duty.
    localparam [2:0] PERIOD_MAX = 3'd7;

    reg [2:0] cnt    = 3'd0;   // period counter
    reg [3:0] duty   = 4'd0;   // duty register, clamped to 0..8
    reg [3:0] on_cnt = 4'd0;   // high cycles accumulated so far this period

    // structural output: high exactly while the period counter is below duty
    assign pwm_out   = ({1'b0, cnt} < duty);
    assign on_cycles = on_cnt;

    always @(posedge clk) begin
        if (rst) begin
            cnt    <= 3'd0;
            duty   <= 4'd0;
            on_cnt <= 4'd0;
        end else if (ce) begin
            if (cnt == PERIOD_MAX) begin
                // period boundary: restart counter, latch new duty, clear accumulator
                cnt    <= 3'd0;
                duty   <= (duty_in > 4'd8) ? 4'd8 : duty_in;
                on_cnt <= 4'd0;
            end else begin
                cnt    <= cnt + 3'd1;
                on_cnt <= on_cnt + (pwm_out ? 4'd1 : 4'd0);
            end
        end
    end

    // P: the accumulated high time within a period never exceeds the duty setting
    always @(posedge clk)
        assert (on_cnt <= duty);
endmodule

module wdt_supervisor (
    input  wire       clk,
    input  wire       i_ce,      // idle condition: low freezes all state
    input  wire       kick,      // service the watchdog
    output reg        expired,   // one-cycle timeout notification
    output reg        hard_rst,  // forced reset after the strike budget is used
    output reg [2:0]  strikes    // accumulated un-serviced timeouts
);
    localparam [3:0] LIMIT = 4'd4;

    reg [3:0] cnt;
    reg       pv;

    initial begin
        cnt      = 4'd0;
        strikes  = 3'd0;
        expired  = 1'b0;
        hard_rst = 1'b0;
        pv       = 1'b0;
    end

    wire timeout = (cnt == LIMIT);

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            expired  <= 1'b0;
            hard_rst <= 1'b0;
            if (kick) begin
                cnt <= 4'd0;
            end else if (timeout) begin
                cnt     <= 4'd0;
                expired <= 1'b1;
                if (strikes == 3'd2) begin
                    strikes  <= 3'd0;
                    hard_rst <= 1'b1;
                end else begin
                    strikes <= strikes + 3'd1;
                end
            end else begin
                cnt <= cnt + 4'd1;
            end
        end
    end

    // P: whenever the timeout notification rises, the strike budget of 2 has
    //    never been exceeded (3-bit register could hold up to 7).
    always @(posedge clk)
        if (pv && $rose(expired))
            assert (strikes <= 3'd2);
endmodule

// Voice-activity frame accumulator with saturating speech-run counter.
// cnt counts consecutive voiced frames and clamps at MAX=12 (a 4-bit reg
// could hold 15).  peak is a shadow register remembering the largest run
// length ever observed, armed is a sticky flag set the first time a run
// reaches the confirmation threshold, and gate is the speech-active output.
module vad_run_accumulator (
    input  wire       clk,
    input  wire       step,      // frame strobe; low => design idles
    input  wire       voice,     // current frame is above energy threshold
    output reg  [3:0] cnt,
    output reg  [3:0] peak,
    output reg        armed,
    output reg        gate
);
    localparam [3:0] MAX     = 4'd12;
    localparam [3:0] CONFIRM = 4'd8;
    localparam [3:0] OPEN    = 4'd4;

    initial cnt   = 4'd0;
    initial peak  = 4'd0;
    initial armed = 1'b0;
    initial gate  = 1'b0;

    // saturating up-counter, cleared on a silent frame
    wire [3:0] cnt_nxt = voice ? ((cnt == MAX) ? MAX : cnt + 4'd1) : 4'd0;

    always @(posedge clk) begin
        if (step) begin
            cnt <= cnt_nxt;

            // shadow register: highest run length seen so far
            if (cnt_nxt > peak)
                peak <= cnt_nxt;

            // sticky arm: a confirmed speech run has happened at least once
            if (cnt_nxt >= CONFIRM)
                armed <= 1'b1;

            // speech-active output
            gate <= (cnt_nxt >= OPEN);
        end
    end

    // Precedence, in the "after armed" scope: once a confirmed run has been
    // observed, any cycle in which the gate is open must be backed by a shadow
    // peak that already reached the confirmation threshold.
    always @(posedge clk)
        if (armed && gate)
            assert (peak >= CONFIRM);
endmodule

module soc_alert_slice (
    input wire clk,
    input wire ce,
    input wire accept,
    input wire [7:0] evt_data,
    output wire busy_o,
    output wire par_err_o,
    output wire [3:0] cnt_o
);
    // Alert register slice protected by a parity bit, with a response
    // deadline countdown: an accepted alert must be handed off before the
    // countdown expires.
    localparam [3:0] K = 4'd9;

    reg [7:0] data_q;   // stored alert payload
    reg       par_q;    // parity of the stored payload
    reg       busy;     // alert outstanding (request accepted, not completed)
    reg [3:0] cnt;      // response deadline countdown
    reg       armed;    // sticky: set on the first accepted alert, never cleared
    reg       pv;       // past-valid

    initial data_q = 8'h00;
    initial par_q  = 1'b0;
    initial busy   = 1'b0;
    initial cnt    = 4'd0;
    initial armed  = 1'b0;
    initial pv     = 1'b0;

    wire par_err = (par_q != (^data_q));
    wire expired = (cnt == 4'd0);

    assign busy_o    = busy;
    assign par_err_o = par_err;
    assign cnt_o     = cnt;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (busy) begin
                if (par_err) begin
                    // corrupted slice: drop the deadline, keep escalating
                    cnt <= 4'd0;
                end else if (cnt == 4'd1) begin
                    // handed off in time
                    cnt  <= 4'd0;
                    busy <= 1'b0;
                end else begin
                    cnt <= cnt - 4'd1;
                end
            end else if (accept) begin
                data_q <= evt_data;
                par_q  <= (^evt_data);
                cnt    <= K;
                busy   <= 1'b1;
                armed  <= 1'b1;
            end
        end
    end

    // Bounded response (safety), after the slice has been armed:
    // while the outstanding flag does not change, the deadline-expired flag
    // must not change either -- the countdown can only reach zero on the very
    // cycle the alert is retired.
    always @(posedge clk)
        if (pv && armed && $stable(busy))
            assert ($stable(expired));
endmodule

module token_bucket_chain (
    input  wire clk,
    input  wire rst,
    input  wire ce,      // global enable: low => all state frozen
    input  wire tick,    // refill timer tick
    input  wire req,     // step 1: arm
    input  wire cancel,  // drop an arm before it starts
    input  wire go,      // step 2: request a grant (needs a token)
    input  wire done,    // step 3: finish
    output wire o_start,
    output wire o_finish,
    output reg  [2:0] tokens
);
    localparam [1:0] S_IDLE = 2'd0, S_ARM = 2'd1, S_RUN = 2'd2;
    localparam [2:0] BURST  = 3'd4;

    reg [1:0] state;
    reg       armed_seen;
    reg       started_seen;

    initial begin
        state        = S_IDLE;
        tokens       = 3'd0;
        armed_seen   = 1'b0;
        started_seen = 1'b0;
    end

    // a grant may only be issued from the armed state and only if the
    // bucket holds at least one token
    wire can_start = (state == S_ARM) && go && !cancel && (tokens != 3'd0);
    wire do_refill = tick && (tokens < BURST);

    assign o_start  = ce && can_start;
    assign o_finish = ce && (state == S_RUN) && done;

    always @(posedge clk) begin
        if (rst) begin
            state        <= S_IDLE;
            tokens       <= 3'd0;
            armed_seen   <= 1'b0;
            started_seen <= 1'b0;
        end else if (ce) begin
            // token bucket: refill on tick up to the burst cap, drain on grant
            case ({do_refill, can_start})
                2'b10:   tokens <= tokens + 3'd1;
                2'b01:   tokens <= tokens - 3'd1;
                default: tokens <= tokens;
            endcase

            // arm -> start -> finish chain
            case (state)
                S_IDLE: begin
                    if (req) begin
                        state        <= S_ARM;
                        armed_seen   <= 1'b1;
                        started_seen <= 1'b0;
                    end
                end
                S_ARM: begin
                    if (cancel) begin
                        state      <= S_IDLE;
                        armed_seen <= 1'b0;
                    end else if (can_start) begin
                        state        <= S_RUN;
                        started_seen <= 1'b1;
                    end
                end
                S_RUN: begin
                    if (done) begin
                        state        <= S_IDLE;
                        armed_seen   <= 1'b0;
                        started_seen <= 1'b0;
                    end
                end
                default: begin
                    state        <= S_IDLE;
                    armed_seen   <= 1'b0;
                    started_seen <= 1'b0;
                end
            endcase
        end
    end

    // chain precedence: a finish can never be observed unless this
    // transaction was armed and then started
    always @(*)
        if (o_finish)
            assert (armed_seen && started_seen);
endmodule

module txn_scoreboard (
    input wire clk,
    input wire ce,
    input wire issue,
    input wire retire_req,
    output reg [2:0] outstanding,
    output reg       armed
);
    // issued/retired transaction counters (scoreboard)
    reg [3:0] issued;
    reg [3:0] retired;
    // bounded-response countdown for the oldest outstanding transaction
    reg [2:0] ttl;

    localparam [2:0] WINDOW = 3'd4;
    localparam [2:0] RELOAD = 3'd5;

    initial begin
        issued      = 4'd0;
        retired     = 4'd0;
        outstanding = 3'd0;
        ttl         = RELOAD;
        armed       = 1'b0;
    end

    // the completion engine is forced to retire when the countdown hits one
    wire force_retire = (outstanding != 3'd0) && (ttl == 3'd1);
    wire do_retire    = (retire_req && (outstanding != 3'd0)) || force_retire;
    wire do_issue     = issue && (outstanding < WINDOW);

    wire [2:0] nxt_out = outstanding
                       + (do_issue  ? 3'd1 : 3'd0)
                       - (do_retire ? 3'd1 : 3'd0);

    always @(posedge clk) begin
        if (ce) begin
            if (do_issue) begin
                issued <= issued + 4'd1;
                armed  <= 1'b1;          // sticky: never cleared
            end
            if (do_retire)
                retired <= retired + 4'd1;

            outstanding <= nxt_out;

            if (do_retire)
                ttl <= RELOAD;           // a completion restarts the window
            else if (nxt_out != 3'd0)
                ttl <= ttl - 3'd1;       // tick down while work is pending
            else
                ttl <= RELOAD;           // idle scoreboard parks at full
        end
    end

    // P: once the scoreboard has ever accepted a transaction, the completion
    // countdown never expires while transactions are still outstanding.
    always @(posedge clk)
        if (armed && (outstanding != 3'd0))
            assert (ttl != 3'd0);
endmodule

// Instruction-fetch queue occupancy tracker with gray-coded pointers.
// Pointers are 4 bits (3 address bits + 1 wrap bit) over an 8-entry buffer.
// Each binary pointer carries a gray shadow used for the full/empty compare.
module ifq_gray_occupancy (
    input  wire        clk,
    input  wire        rst,
    input  wire        push,
    input  wire        pop,
    input  wire [31:0] din,
    output wire [31:0] dout,
    output wire        full,
    output wire        empty
);
    // binary pointers
    reg [3:0] wbin    = 4'd0;
    reg [3:0] rbin    = 4'd0;
    // gray shadows of the binary pointers
    reg [3:0] wgray   = 4'd0;
    reg [3:0] rgray   = 4'd0;
    // occupancy and high-water mark
    reg [3:0] occ     = 4'd0;
    reg [3:0] hiwater = 4'd0;

    reg [31:0] mem [0:7];
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) mem[i] = 32'd0;
    end

    wire [3:0] wbin_nxt  = wbin + 4'd1;
    wire [3:0] rbin_nxt  = rbin + 4'd1;
    wire [3:0] wgray_nxt = wbin_nxt ^ (wbin_nxt >> 1);
    wire [3:0] rgray_nxt = rbin_nxt ^ (rbin_nxt >> 1);

    // classic gray-pointer full / empty decode
    assign full  = (wgray == {~rgray[3:2], rgray[1:0]});
    assign empty = (wgray == rgray);

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    wire [3:0] occ_nxt = occ + (do_push ? 4'd1 : 4'd0) - (do_pop ? 4'd1 : 4'd0);

    assign dout = mem[rbin[2:0]];

    always @(posedge clk) begin
        if (rst) begin
            wbin    <= 4'd0;
            rbin    <= 4'd0;
            wgray   <= 4'd0;
            rgray   <= 4'd0;
            occ     <= 4'd0;
            hiwater <= 4'd0;
        end else begin
            if (do_push) begin
                wbin           <= wbin_nxt;
                wgray          <= wgray_nxt;
                mem[wbin[2:0]] <= din;
            end
            if (do_pop) begin
                rbin  <= rbin_nxt;
                rgray <= rgray_nxt;
            end
            occ <= occ_nxt;
            if (occ_nxt > hiwater)
                hiwater <= occ_nxt;
        end
    end

    // P (two parts): the queue never holds more than the 8 entries it has,
    // and the recorded peak occupancy never exceeds 8 either, even though the
    // 4-bit registers could represent up to 15.
    always @(posedge clk) assert (occ <= 4'd8);
    always @(posedge clk) assert (hiwater <= 4'd8);
endmodule

module boot_key_debounce (
    input  wire clk,
    input  wire ce,
    input  wire raw_key,
    output wire clean_key,
    output wire menu_armed
);
    // K identical consecutive samples are required before the clean
    // boot-menu key output is allowed to follow the raw input.
    parameter [2:0] K = 3'd6;

    reg       samp;    // last registered raw sample
    reg [2:0] cnt;     // stability counter, saturates at K
    reg       at_k;    // registered decode of (cnt == K-1)
    reg       shadow;  // value captured one step before the commit
    reg       clean;   // debounced output
    reg       armed;   // sticky: set at the first commit, never cleared

    initial begin
        samp   = 1'b0;
        cnt    = 3'd0;
        at_k   = 1'b0;
        shadow = 1'b0;
        clean  = 1'b0;
        armed  = 1'b0;
    end

    wire       match    = (raw_key == samp);
    wire [2:0] next_cnt = (!match) ? 3'd0 : ((cnt < K) ? (cnt + 3'd1) : K);
    wire       commit   = at_k && match;

    always @(posedge clk) if (ce) begin
        samp <= raw_key;
        cnt  <= next_cnt;
        at_k <= (next_cnt == (K - 3'd1));

        // one step before the run completes, record the value that is
        // about to be committed to the clean output
        if (match && (cnt == (K - 3'd2)))
            shadow <= samp;

        // the run of K identical samples completes here
        if (commit) begin
            clean <= shadow;
            armed <= 1'b1;
        end
    end

    assign clean_key  = clean;
    assign menu_armed = armed;

    // Precedence, in the "after first commit" scope: whenever the counter
    // is saturated, the clean output must already carry the value that was
    // shadowed when the stable run was recognised.
    always @(posedge clk)
        if (armed && (cnt == K))
            assert (clean == shadow);
endmodule

module csa_budget_acc (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [1:0] inc,
    output wire [8:0] o_total,
    output wire       o_full
);
    // accumulator kept in carry-save form: the two halves always sum to the
    // true running total, and at most 10 increments of at most 3 are consumed
    reg [7:0] sum_h;
    reg [7:0] car_h;
    reg [3:0] n;

    initial sum_h = 8'd0;
    initial car_h = 8'd0;
    initial n     = 4'd0;

    wire [7:0] x       = {6'd0, inc};
    wire [7:0] nxt_sum = sum_h ^ car_h ^ x;
    wire [7:0] maj     = (sum_h & car_h) | (sum_h & x) | (car_h & x);
    wire [7:0] nxt_car = {maj[6:0], 1'b0};

    wire budget = (n < 4'd10);

    always @(posedge clk) begin
        if (rst) begin
            sum_h <= 8'd0;
            car_h <= 8'd0;
            n     <= 4'd0;
        end else if (ce && budget) begin
            sum_h <= nxt_sum;
            car_h <= nxt_car;
            n     <= n + 4'd1;
        end
    end

    // the true total is the sum of the two carry-save halves
    wire [8:0] total = {1'b0, sum_h} + {1'b0, car_h};

    assign o_total = total;
    assign o_full  = ~budget;

    // bounded existence: the accumulated total never exceeds 30,
    // far below what the 9-bit total could hold
    assert property (total <= 9'd30);
endmodule

module lfsr_precedence (
    input  wire       clk,
    input  wire       step,      // enable: when low, all state is frozen
    output wire       out_bit,
    output wire [3:0] state_o
);
    // 4-bit maximal-length LFSR, polynomial x^4 + x^3 + 1.
    // Seeded nonzero, so the all-zeros lockup state is never entered.
    reg [3:0] lfsr    = 4'h1;
    reg [3:0] prev    = 4'h8;   // shadow register: the value that preceded lfsr
    reg       stepped = 1'b0;   // records that a shift happened on the last edge

    wire [3:0] nxt = {lfsr[2:0], lfsr[3] ^ lfsr[2]};

    assign out_bit = lfsr[0];
    assign state_o = lfsr;

    always @(posedge clk) begin
        stepped <= step;
        if (step) begin
            prev <= lfsr;   // shadow captures the earlier value
            lfsr <= nxt;
        end
    end

    // Precedence: whenever a shift has just been observed, the value now on the
    // register must differ from the shadowed value that preceded it -- the
    // generator always makes progress.
    always @(posedge clk)
        if (stepped)
            assert (lfsr != prev);

endmodule

module elastic_buf2 (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       full,
    output wire       empty
);
    // two-entry elastic buffer: one valid flag per slot, head/tail select bits
    reg       v0 = 1'b0;   // slot 0 occupied
    reg       v1 = 1'b0;   // slot 1 occupied
    reg       h  = 1'b0;   // head: slot read next
    reg       t  = 1'b0;   // tail: slot written next
    reg [7:0] m0 = 8'h00;
    reg [7:0] m1 = 8'h00;
    reg [2:0] count = 3'd0; // redundant occupancy counter

    assign full  = v0 & v1;
    assign empty = (~v0) & (~v1);
    assign dout  = h ? m1 : m0;

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            h     <= 1'b0;
            t     <= 1'b0;
            m0    <= 8'h00;
            m1    <= 8'h00;
            count <= 3'd0;
        end else begin
            if (do_push) begin
                if (t == 1'b0) begin
                    v0 <= 1'b1;
                    m0 <= din;
                end else begin
                    v1 <= 1'b1;
                    m1 <= din;
                end
                t <= ~t;
            end
            if (do_pop) begin
                if (h == 1'b0)
                    v0 <= 1'b0;
                else
                    v1 <= 1'b0;
                h <= ~h;
            end
            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase
        end
    end

    // P: the buffer never holds more than two entries, although count is 3 bits wide
    always @(posedge clk)
        assert (count <= 3'd2);
endmodule

// Sliding-window grant rate limiter for an inference-accelerator arbiter.
// A shift register of the last 8 cycles' grants plus a mirrored count of ones.
module window_rate_limiter (
    input  wire clk,
    input  wire ce,      // idle condition: when low, nothing changes
    input  wire req,     // request a grant this cycle
    input  wire flush,   // clear the accounting (credit reset)
    output wire grant,
    output wire full
);
    localparam [3:0] LIMIT = 4'd4;

    // sliding window of recent grants and its mirrored population count
    reg [7:0] win        = 8'd0;
    reg [3:0] ones       = 4'd0;

    // shadow register: saturating count of grants ever issued (since last flush)
    reg [2:0] seen       = 3'd0;

    // scope arming register: high until the first flush ever happens
    reg       pre_flush  = 1'b1;

    // registered throttle indication
    reg       throttled  = 1'b0;

    reg       pv         = 1'b0;

    assign full  = (ones >= LIMIT);
    assign grant = ce && !flush && req && !full;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (flush) begin
                seen      <= 3'd0;
                pre_flush <= 1'b0;
                throttled <= 1'b0;
            end else begin
                win  <= {win[6:0], grant};
                ones <= ones + (grant ? 4'd1 : 4'd0) - (win[7] ? 4'd1 : 4'd0);
                if (grant && (seen != 3'd4))
                    seen <= seen + 3'd1;
                throttled <= req && full;
            end
        end
    end

    // Precedence, before-first-flush scope, edge style:
    // the throttle signal may only rise after LIMIT grants have been observed.
    always @(posedge clk)
        if (pv && pre_flush && $rose(throttled))
            assert (seen == 3'd4);
endmodule

module prienc_owner_guard (
    input  wire       clk,
    input  wire       ce,
    input  wire       abort,
    input  wire [3:0] req,
    output wire       o_lo_owner,
    output wire       o_hi_owner,
    output wire       o_valid
);
    // ---- before-abort scope register: starts high, cleared on first abort ----
    reg armed = 1'b1;

    // ---- stage 1: priority encoder with registered valid flag ----
    reg        vld = 1'b0;
    reg [1:0]  idx = 2'd0;
    reg [3:0]  gnt = 4'b0000;   // registered one-hot shadow of idx

    // ---- stage 2: decoded ownership flags ----
    reg q_lo = 1'b0;
    reg q_hi = 1'b0;
    reg q_v  = 1'b0;
    reg q_z  = 1'b1;

    // combinational priority encoder (lowest index wins)
    wire [1:0] pidx = req[0] ? 2'd0 : req[1] ? 2'd1 : req[2] ? 2'd2 : 2'd3;
    wire [3:0] pgnt = req[0] ? 4'b0001 :
                      req[1] ? 4'b0010 :
                      req[2] ? 4'b0100 :
                      req[3] ? 4'b1000 : 4'b0000;
    wire       pv   = |req;

    always @(posedge clk)
        if (ce && abort)
            armed <= 1'b0;

    always @(posedge clk)
        if (ce) begin
            if (abort && armed) begin
                // broadcast/scan mode entered together with leaving the scope
                vld <= 1'b1;
                idx <= 2'd0;
                gnt <= 4'b1111;
            end else begin
                vld <= pv;
                idx <= pidx;
                gnt <= pgnt;
            end
        end

    always @(posedge clk)
        if (ce) begin
            q_lo <= vld && (idx < 2'd2);
            q_hi <= vld && (|gnt[3:2]);
            q_v  <= vld;
            q_z  <= (gnt == 4'b0000);
        end

    assign o_lo_owner = q_lo;
    assign o_hi_owner = q_hi;
    assign o_valid    = q_v;

    // P1: before any abort, a low-half owner and a high-half owner never coexist
    always @(posedge clk)
        if (armed)
            assert (!(q_lo && q_hi));

    // P2: before any abort, "result valid" and "no grant at all" never coexist
    always @(posedge clk)
        if (armed)
            assert (!(q_v && q_z));
endmodule

module triage_arbiter (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [3:0] req,
    output reg  [3:0] grant,
    output reg        locked,
    output reg  [1:0] owner
);
    // Fixed-priority select: channel 0 (escalate) highest, 3 (archive) lowest.
    reg [1:0] sel_idx;
    reg [3:0] sel_oh;

    always @(*) begin
        casez (req)
            4'b???1: begin sel_idx = 2'd0; sel_oh = 4'b0001; end
            4'b??10: begin sel_idx = 2'd1; sel_oh = 4'b0010; end
            4'b?100: begin sel_idx = 2'd2; sel_oh = 4'b0100; end
            4'b1000: begin sel_idx = 2'd3; sel_oh = 4'b1000; end
            default: begin sel_idx = 2'd0; sel_oh = 4'b0000; end
        endcase
    end

    initial begin
        grant  = 4'b0000;
        locked = 1'b0;
        owner  = 2'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            grant  <= 4'b0000;
            locked <= 1'b0;
            owner  <= 2'd0;
        end else if (ce) begin
            if (!locked) begin
                // idle: hand the bus to the highest-priority requester and lock
                if (|req) begin
                    grant  <= sel_oh;
                    owner  <= sel_idx;
                    locked <= 1'b1;
                end
            end else begin
                // locked: grant bits survive only while their request persists,
                // and the lock is released when the owner drops its request
                grant  <= grant & req;
                locked <= req[owner];
            end
        end
    end

    // P: whenever the arbiter is locked, somebody actually holds the bus.
    always @(*) assert (!locked || grant != 4'b0000);
endmodule

module axi_burst_hist (
    input  wire       clk,
    input  wire       rst,
    input  wire       start,        // request from the AXI side
    input  wire       sample_valid, // enable: one sample per cycle
    input  wire [1:0] sel,          // which bin this sample lands in
    output wire       done
);
    // Each accepted request collects BURST samples into a 4-bin histogram.
    // The bins are incremented one at a time and always sum to `total`.
    localparam integer BURST    = 4;
    localparam [2:0]   DEADLINE = 3'd6;

    reg [3:0] bin0, bin1, bin2, bin3;
    reg [3:0] total;   // total samples collected in this burst
    reg [2:0] timer;   // bounded-response countdown
    reg       busy;    // window register: set by accept, cleared by done

    initial bin0  = 4'd0;
    initial bin1  = 4'd0;
    initial bin2  = 4'd0;
    initial bin3  = 4'd0;
    initial total = 4'd0;
    initial timer = 3'd0;
    initial busy  = 1'b0;

    wire [7:0] sum = bin0 + bin1 + bin2 + bin3;

    // burst finishes when the histogram has absorbed the last sample
    assign done = busy && sample_valid && (sum == BURST - 1);

    always @(posedge clk) begin
        if (rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 4'd0;
            timer <= 3'd0;
            busy  <= 1'b0;
        end else if (!busy) begin
            if (start) begin          // Q: request accepted, window opens
                bin0  <= 4'd0;
                bin1  <= 4'd0;
                bin2  <= 4'd0;
                bin3  <= 4'd0;
                total <= 4'd0;
                timer <= DEADLINE;
                busy  <= 1'b1;
            end
        end else if (sample_valid) begin
            case (sel)
                2'd0: bin0 <= bin0 + 4'd1;
                2'd1: bin1 <= bin1 + 4'd1;
                2'd2: bin2 <= bin2 + 4'd1;
                2'd3: bin3 <= bin3 + 4'd1;
            endcase
            total <= total + 4'd1;
            timer <= timer - 3'd1;
            if (sum == BURST - 1)     // R: last sample, window closes
                busy <= 1'b0;
        end
    end

    // Bounded response (safety): inside the open window the countdown
    // must never reach zero, i.e. the burst always completes in time.
    always @(posedge clk)
        if (busy)
            assert (timer != 3'd0);
endmodule

module crc8_onehot_check (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire start,
    input wire data_bit,
    output reg [3:0] st,
    output reg [7:0] crc,
    output reg [2:0] bitcnt,
    output reg crc_busy,
    output reg crc_valid
);
    // one-hot phases: bit0 = IDLE, bit1 = SHIFT, bit2 = FINAL, bit3 = DONE
    initial st        = 4'b0001;
    initial crc       = 8'hFF;
    initial bitcnt    = 3'd0;
    initial crc_busy  = 1'b0;
    initial crc_valid = 1'b0;

    wire       fb       = crc[7] ^ data_bit;
    wire [7:0] crc_next = {crc[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);

    always @(posedge clk) begin
        if (rst) begin
            st        <= 4'b0001;
            crc       <= 8'hFF;
            bitcnt    <= 3'd0;
            crc_busy  <= 1'b0;
            crc_valid <= 1'b0;
        end else if (ce) begin
            // IDLE arm: accepting a new byte starts the shifter
            if (st[0]) begin
                if (start) begin
                    st       <= 4'b0010;
                    crc      <= 8'hFF;
                    bitcnt   <= 3'd0;
                    crc_busy <= 1'b1;
                end
            end
            // SHIFT arm: one bit of the polynomial reduction per cycle
            if (st[1]) begin
                crc    <= crc_next;
                bitcnt <= bitcnt + 3'd1;
                if (bitcnt == 3'd7) begin
                    st       <= 4'b0100;
                    crc_busy <= 1'b0;
                end
            end
            // FINAL arm: remainder settled, publish it
            if (st[2]) begin
                st        <= 4'b1000;
                crc_valid <= 1'b1;
            end
            // DONE arm: consumer has seen the result
            if (st[3]) begin
                st        <= 4'b0001;
                crc_valid <= 1'b0;
            end
        end
    end

    always @(*)
        assert (!(crc_busy && crc_valid));
endmodule

module prio_arb_lock (
    input  wire       clk,
    input  wire       ce,
    input  wire [3:0] req,
    output reg  [3:0] grant
);
    // fixed-priority arbiter (master 0 highest) with a lock bit that freezes
    // the current winner until that winner drops its request
    reg       locked;
    reg [1:0] lock_id;
    reg       armed;   // sticky: set the first time a grant is ever issued
    reg       pv;      // past-valid

    initial begin
        grant   = 4'b0000;
        locked  = 1'b0;
        lock_id = 2'd0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    wire       any = |req;
    wire [1:0] win = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ce) begin
            if (locked) begin
                if (req[lock_id]) begin
                    // hold the locked winner: grant is re-driven from lock_id
                    grant   <= (4'b0001 << lock_id);
                    locked  <= 1'b1;
                    armed   <= 1'b1;
                end else begin
                    // winner released: drop the lock for one cycle
                    grant   <= 4'b0000;
                    locked  <= 1'b0;
                end
            end else begin
                if (any) begin
                    grant   <= (4'b0001 << win);
                    lock_id <= win;
                    locked  <= 1'b1;
                    armed   <= 1'b1;
                end else begin
                    grant   <= 4'b0000;
                    locked  <= 1'b0;
                end
            end
        end
    end

    // Universality, after the arbiter has ever granted (armed):
    // while the lock bit did not change and is held, the grant must not change.
    always @(posedge clk)
        if (pv && armed && locked && $stable(locked))
            assert ($stable(grant));
endmodule

// Fixed-latency packet capture pipeline with an in-flight occupancy tracker.
// A sensor issues a captured packet into a 4-deep fixed-latency staging
// pipeline; the packet emerges four enabled cycles later and is handed to the
// stream encoder.  o_inflight counts packets currently inside the pipeline.
module pkt_inflight_tracker (
    input  wire       clk,
    input  wire       rst,      // synchronous reset
    input  wire       i_ce,     // capture clock enable (low = sensor idle)
    input  wire       i_issue,  // a new packet is pushed into the pipeline
    output reg        o_drain,  // pulses when a packet left the pipeline
    output reg  [2:0] o_inflight
);

    // fixed-latency shift register: one valid bit per pipeline stage
    reg [3:0] pipe;

    initial pipe       = 4'b0000;
    initial o_inflight = 3'd0;
    initial o_drain    = 1'b0;

    // a packet reaching the last stage exits on the next enabled cycle
    wire exits = pipe[3];

    always @(posedge clk) begin
        if (rst) begin
            pipe       <= 4'b0000;
            o_inflight <= 3'd0;
            o_drain    <= 1'b0;
        end else if (i_ce) begin
            pipe       <= {pipe[2:0], i_issue};
            o_inflight <= o_inflight
                        + (i_issue ? 3'd1 : 3'd0)
                        - (exits   ? 3'd1 : 3'd0);
            o_drain    <= exits;
        end
    end

    // P (universality, global): whenever a packet is about to leave the
    // pipeline, the occupancy tracker must not read empty.
    assert property (!pipe[3] || o_inflight != 3'd0);

endmodule

module thermo_div_guard (
    input  wire       clk,
    input  wire       ce,
    input  wire [7:0] temp,
    input  wire       q_arm,
    input  wire       r_done,
    output wire       heat_o,
    output wire       tick_o
);
    localparam [7:0] T_LOW  = 8'd60;
    localparam [7:0] T_HIGH = 8'd80;
    localparam [2:0] DIVM1  = 3'd4;   // divide by 5

    // clock divider: phase counter, divided enable fires on the wrap
    reg [2:0] phase;
    // thermostat state
    reg [7:0] temp_lat;   // temperature sample taken on the divided enable
    reg       heater;     // hysteresis output
    // chatter / inconsistency detectors
    reg       bad_hi;     // heater was on while last sample was above T_HIGH
    reg       bad_lo;     // heater was off while last sample was below T_LOW
    // monitoring window
    reg       win;

    initial phase    = 3'd0;
    initial temp_lat = 8'd70;
    initial heater   = 1'b0;
    initial bad_hi   = 1'b0;
    initial bad_lo   = 1'b0;
    initial win      = 1'b0;

    wire tickw = ce && (phase == DIVM1);

    assign tick_o = tickw;
    assign heat_o = heater;

    always @(posedge clk) if (ce) begin
        phase <= (phase == DIVM1) ? 3'd0 : phase + 3'd1;

        if (tickw) begin
            // sample and apply hysteresis from the same sample
            temp_lat <= temp;
            if (temp < T_LOW)
                heater <= 1'b1;
            else if (temp > T_HIGH)
                heater <= 1'b0;

            // check the previously latched sample against the current output
            if (heater && (temp_lat > T_HIGH))
                bad_hi <= 1'b1;
            if (!heater && (temp_lat < T_LOW))
                bad_lo <= 1'b1;
        end

        // window: opened by q_arm (which also restarts the detectors),
        // closed by r_done; may be opened and closed repeatedly
        if (q_arm) begin
            win    <= 1'b1;
            bad_hi <= 1'b0;
            bad_lo <= 1'b0;
        end else if (r_done)
            win <= 1'b0;
    end

    always @(posedge clk)
        if (win) assert (!bad_hi);

    always @(posedge clk)
        if (win) assert (!bad_lo);
endmodule

module prio_skid (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_valid,
    input  wire [7:0] i_req,
    input  wire       o_ready,   // downstream ready
    output wire       i_ready,
    output wire       o_valid,
    output wire [2:0] o_idx,
    output wire       o_hit
);
    // ---------------- combinational priority encoder ----------------
    wire       enc_hit = |i_req;
    wire [2:0] enc_idx = i_req[7] ? 3'd7 :
                         i_req[6] ? 3'd6 :
                         i_req[5] ? 3'd5 :
                         i_req[4] ? 3'd4 :
                         i_req[3] ? 3'd3 :
                         i_req[2] ? 3'd2 :
                         i_req[1] ? 3'd1 : 3'd0;

    // ---------------- registered output stage ----------------
    reg       out_vld;
    reg [2:0] out_idx;
    reg       out_hit;
    reg [7:0] out_req;

    // ---------------- skid buffer (only meaningful while sk_full) ----
    reg       sk_full;
    reg [7:0] sk_req;
    reg [2:0] sk_idx;
    reg       sk_hit;

    // ---------------- stall history and sticky arm ----------------
    reg       stalled;   // registered copy of the stall condition
    reg       armed;     // sticky: set the first time an input word is offered

    initial begin
        out_vld = 1'b0; out_idx = 3'd0; out_hit = 1'b0; out_req = 8'h00;
        sk_full = 1'b0; sk_req  = 8'h00; sk_idx  = 3'd0; sk_hit  = 1'b0;
        stalled = 1'b0; armed   = 1'b0;
    end

    wire stall = out_vld && !o_ready;

    assign i_ready = !sk_full;
    assign o_valid = out_vld;
    assign o_idx   = out_idx;
    assign o_hit   = out_hit;

    always @(posedge clk) begin
        if (i_ce) begin
            armed   <= armed | i_valid;
            stalled <= stall;

            if (!stall) begin
                if (sk_full) begin
                    out_vld <= 1'b1;
                    out_idx <= sk_idx;
                    out_hit <= sk_hit;
                    out_req <= sk_req;
                    sk_full <= 1'b0;
                end else begin
                    out_vld <= i_valid;
                    out_idx <= enc_idx;
                    out_hit <= enc_hit;
                    out_req <= i_req;
                end
            end else begin
                // output stage blocked: park the incoming word in the skid
                if (i_valid && !sk_full) begin
                    sk_full <= 1'b1;
                    sk_req  <= i_req;
                    sk_idx  <= enc_idx;
                    sk_hit  <= enc_hit;
                end
            end
        end
    end

    // ---------------- property ----------------
    // Once an input word has ever been offered (armed), whenever the stage has
    // recorded a stall the buffered encoding must point at a set request bit.
    always @(posedge clk)
        if (armed && stalled)
            assert (!sk_hit || sk_req[sk_idx]);

endmodule

module onehot_issue_window (
    input  wire       clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_start,   // Q: arms the observation window
    input  wire       i_close,   // R: closes the window (may never arrive)
    output wire [2:0] o_occ,
    output wire [3:0] o_state
);

    // one-hot FSM: IDLE -> ISSUE_A -> ISSUE_B -> DRAIN -> IDLE
    reg [3:0] state = 4'b0001;
    // outstanding-token occupancy: one token issued per ISSUE state,
    // all tokens retired in DRAIN
    reg [2:0] occ   = 3'd0;
    // window register: latched by the start pulse, cleared by i_close
    reg       armed = 1'b0;
    reg       pv    = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            state <= 4'b0001;
            occ   <= 3'd0;
        end else if (i_ce) begin
            case (1'b1)
                state[0]: begin
                    // leaving IDLE is only legal on a start pulse
                    if (i_start)
                        state <= 4'b0010;
                    occ <= 3'd0;
                end
                state[1]: begin
                    state <= 4'b0100;
                    occ   <= occ + 3'd1;
                end
                state[2]: begin
                    state <= 4'b1000;
                    occ   <= occ + 3'd1;
                end
                state[3]: begin
                    state <= 4'b0001;
                    occ   <= 3'd0;
                end
                default: begin
                    state <= 4'b0001;
                    occ   <= 3'd0;
                end
            endcase
        end

    always @(posedge clk)
        if (i_rst)
            armed <= 1'b0;
        else if (i_ce) begin
            if (i_close)
                armed <= 1'b0;
            else if (i_start && state[0])
                armed <= 1'b1;
        end

    assign o_occ   = occ;
    assign o_state = state;

    // P: once the window has been armed, the occupancy of the previous
    //    cycle never exceeded two outstanding tokens
    always @(posedge clk)
        if (pv && $past(armed))
            assert ($past(occ) <= 3'd2);

endmodule

module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] i_req,
    input  wire       i_start,
    input  wire       i_finish,
    output reg  [3:0] o_grant,
    output reg        o_fin
);
    // phase encoding: 0 = IDLE, 1 = ARMED (grant issued), 2 = RUNNING, 3 = FINISHED
    localparam [1:0] PH_IDLE = 2'd0,
                     PH_ARM  = 2'd1,
                     PH_RUN  = 2'd2,
                     PH_FIN  = 2'd3;

    reg [1:0] last_grant;   // round-robin pointer
    reg [1:0] phase;
    reg [3:0] req_hold;     // request vector latched at grant time
    reg       r_arm_seen;   // this transaction was armed (granted)
    reg       r_start_seen; // this transaction was started
    reg       armed_q;      // sticky: an arbitration has happened at least once

    initial begin
        last_grant   = 2'd0;
        phase        = PH_IDLE;
        o_grant      = 4'b0000;
        o_fin        = 1'b0;
        req_hold     = 4'b0000;
        r_arm_seen   = 1'b0;
        r_start_seen = 1'b0;
        armed_q      = 1'b0;
    end

    // ---- round robin winner select, starting just after last_grant ----
    wire [1:0] c1 = last_grant + 2'd1;
    wire [1:0] c2 = last_grant + 2'd2;
    wire [1:0] c3 = last_grant + 2'd3;

    reg [1:0] win;
    reg       any;

    always @(*) begin
        any = 1'b1;
        if      (i_req[c1])         win = c1;
        else if (i_req[c2])         win = c2;
        else if (i_req[c3])         win = c3;
        else if (i_req[last_grant]) win = last_grant;
        else begin
            win = last_grant;
            any = 1'b0;
        end
    end

    // ---- arm / start / finish chain ----
    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                PH_IDLE: begin
                    if (any) begin
                        o_grant      <= (4'b0001 << win);
                        last_grant   <= win;
                        req_hold     <= i_req;
                        phase        <= PH_ARM;
                        r_arm_seen   <= 1'b1;
                        armed_q      <= 1'b1;
                    end
                end
                PH_ARM: begin
                    if (i_start) begin
                        phase        <= PH_RUN;
                        r_start_seen <= 1'b1;
                    end
                end
                PH_RUN: begin
                    if (i_finish) begin
                        phase        <= PH_FIN;
                        o_fin        <= 1'b1;
                    end
                end
                PH_FIN: begin
                    phase        <= PH_IDLE;
                    o_grant      <= 4'b0000;
                    o_fin        <= 1'b0;
                    req_hold     <= 4'b0000;
                    r_arm_seen   <= 1'b0;
                    r_start_seen <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence, only required once arbitration has ever occurred:
    // a completion can never be observed unless this transaction was armed
    // and then started.
    always @(posedge clk)
        if (armed_q && o_fin)
            assert (r_start_seen && r_arm_seen);

endmodule

module lefdef_parse_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [1:0] tok,
    output reg  [2:0] state,
    output reg        hdr_seen,
    output reg  [3:0] macro_cnt
);
    // binary-encoded parser FSM; encodings 3'd6 and 3'd7 are never entered
    localparam S_IDLE   = 3'd0;  // waiting for a file
    localparam S_HEADER = 3'd1;  // VERSION / UNITS block
    localparam S_MACRO  = 3'd2;  // MACRO record
    localparam S_PINS   = 3'd3;  // PIN records of current macro
    localparam S_LAYER  = 3'd4;  // LAYER / PORT geometry
    localparam S_END    = 3'd5;  // END LIBRARY

    initial state     = S_IDLE;
    initial hdr_seen  = 1'b0;    // shadow register: header block was parsed
    initial macro_cnt = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            state     <= S_IDLE;
            hdr_seen  <= 1'b0;
            macro_cnt <= 4'd0;
        end else if (ce) begin
            case (state)
                S_IDLE: begin
                    if (tok == 2'd1)
                        state <= S_HEADER;
                end
                S_HEADER: begin
                    if (tok == 2'd2) begin
                        hdr_seen <= 1'b1;   // header fully consumed
                        state    <= S_MACRO;
                    end
                end
                S_MACRO: begin
                    if (tok == 2'd3)
                        state <= S_PINS;
                    else if (tok == 2'd0)
                        state <= S_END;
                end
                S_PINS: begin
                    if (tok == 2'd3)
                        state <= S_LAYER;
                end
                S_LAYER: begin
                    if (tok == 2'd0) begin
                        state     <= S_MACRO;
                        macro_cnt <= macro_cnt + 4'd1;
                    end
                end
                S_END: begin
                    if (tok == 2'd1)
                        state <= S_IDLE;
                end
                default: begin
                    // illegal encoding recovery path (never taken in practice)
                    state <= S_PINS;
                end
            endcase
        end
    end

    // Precedence: pin records can only be seen after the header was parsed.
    always @(posedge clk)
        if (state == S_PINS)
            assert (hdr_seen);
endmodule

module sat_event_counter (
    input  wire clk,
    input  wire clr,
    input  wire step,
    output wire o_empty,
    output wire o_full,
    output wire [3:0] o_count
);
    localparam [3:0] MAX = 4'd12;

    // saturating up-counter: clamps at 12, well below what 4 bits admit
    reg [3:0] cnt   = 4'd0;
    reg       zero_f = 1'b1;   // "no events yet / cleared" flag
    reg       sat_f  = 1'b0;   // "counter has reached its clamp" flag

    initial begin
        cnt    = 4'd0;
        zero_f = 1'b1;
        sat_f  = 1'b0;
    end

    wire [3:0] nxt = (cnt == MAX) ? MAX : (cnt + 4'd1);

    always @(posedge clk) begin
        if (clr) begin
            cnt    <= 4'd0;
            zero_f <= 1'b1;
            sat_f  <= 1'b0;
        end else if (step) begin
            cnt <= nxt;
            // zero_f is only dropped on the step that leaves the zero point
            if (cnt == 4'd0)
                zero_f <= 1'b0;
            // sat_f tracks arrival at the clamp value
            sat_f <= (nxt == MAX);
        end
    end

    assign o_empty = zero_f;
    assign o_full  = sat_f;
    assign o_count = cnt;

    // P: while the counter is being commanded, it can never report
    //    empty and full at the same time.
    always @(posedge clk)
        if (step || clr)
            assert (!(o_empty && o_full));
endmodule

module credit_ledger (
    input  wire       clk,
    input  wire       rst,
    input  wire       issue,          // producer spends a credit (dispatch a signing request)
    input  wire       ret,            // consumer returns a credit (signature delivered)
    output reg  [3:0] credits_avail,  // credits held by the dispatcher
    output reg  [3:0] credits_out,    // credits outstanding in the signing pipeline
    output reg        hit_hw,         // shadow: outstanding count once reached the high-water mark
    output reg        started         // shadow: at least one request was ever issued
);
    localparam [3:0] TOTAL = 4'd8;
    localparam [3:0] HW    = 4'd4;

    initial credits_avail = TOTAL;
    initial credits_out   = 4'd0;
    initial hit_hw        = 1'b0;
    initial started       = 1'b0;

    // idle when issue and ret are both low (or both high): nothing changes
    wire do_issue = issue && !ret && (credits_avail != 4'd0);
    wire do_ret   = ret && !issue && (credits_out   != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            credits_avail <= TOTAL;
            credits_out   <= 4'd0;
            hit_hw        <= 1'b0;
            started       <= 1'b0;
        end else begin
            if (do_issue) begin
                credits_avail <= credits_avail - 4'd1;
                credits_out   <= credits_out   + 4'd1;
                started       <= 1'b1;
                if (credits_out >= (HW - 4'd1))
                    hit_hw <= 1'b1;
            end else if (do_ret) begin
                credits_avail <= credits_avail + 4'd1;
                credits_out   <= credits_out   - 4'd1;
            end
        end
    end

    // Precedence, global scope, two assertions sharing one relation:
    //  - if the dispatcher is down to half its credits, the pipeline must have
    //    reached the high-water mark at some earlier point;
    //  - if the dispatcher no longer holds the full budget, some request must
    //    have been issued earlier.
    always @(posedge clk) begin
        if (credits_avail <= HW)
            assert (hit_hw);
        if (credits_avail != TOTAL)
            assert (started);
    end
endmodule

module hs_tag_prec (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire       start,
    input  wire       slv_rdy,
    input  wire [3:0] data,
    output wire       o_busy,
    output wire       o_req,
    output wire       o_ack,
    output wire [3:0] o_last_tag
);

    // four-phase request/acknowledge master
    //   phase 0 : idle           req=0 ack=0 busy=0
    //   phase 1 : request posted req=1 ack=0 busy=1
    //   phase 2 : ack received   req=1 ack=1 busy=1
    //   phase 3 : req withdrawn  req=0 ack=1 busy=1
    reg [1:0] phase;   initial phase   = 2'd0;
    reg       busy;    initial busy    = 1'b0;
    reg       req;     initial req     = 1'b0;
    reg       ack;     initial ack     = 1'b0;

    // tag posted with the request, and the tag captured when ack rose
    reg [3:0] tag;     initial tag     = 4'd0;
    reg [3:0] ack_tag; initial ack_tag = 4'd0;
    reg [3:0] last_tag;initial last_tag= 4'd0;

    // sticky arm: set the first time an acknowledge is taken
    reg       armed;   initial armed   = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            phase    <= 2'd0;
            busy     <= 1'b0;
            req      <= 1'b0;
            ack      <= 1'b0;
            tag      <= 4'd0;
            ack_tag  <= 4'd0;
            last_tag <= 4'd0;
            armed    <= 1'b0;
        end else if (step) begin
            case (phase)
                2'd0: if (start) begin
                          phase <= 2'd1;
                          req   <= 1'b1;
                          busy  <= 1'b1;
                          tag   <= data;      // post the tag with the request
                      end
                2'd1: if (slv_rdy) begin
                          phase   <= 2'd2;
                          ack     <= 1'b1;
                          ack_tag <= tag;     // shadow of the earlier posted tag
                          armed   <= 1'b1;    // first handshake ever completed
                      end
                2'd2: begin
                          phase <= 2'd3;
                          req   <= 1'b0;      // req may only drop after ack rose
                      end
                2'd3: begin
                          phase    <= 2'd0;
                          ack      <= 1'b0;
                          busy     <= 1'b0;
                          last_tag <= ack_tag;
                      end
            endcase
        end
    end

    assign o_busy     = busy;
    assign o_req      = req;
    assign o_ack      = ack;
    assign o_last_tag = last_tag;

    // Precedence, after the first acknowledge has been seen:
    // whenever we observe the withdrawn-request phase (ack high, req low),
    // the acknowledged tag must be the tag that was posted earlier.
    always @(posedge clk)
        assert (!armed || !(ack && !req) || (ack_tag == tag));

endmodule

module window_rate_limiter (
    input  wire clk,
    input  wire ce,      // idle condition: ce low freezes all state
    input  wire req,
    input  wire flush,   // the scope event R: first flush clears the chain flags
    output wire grant
);
    localparam LIMIT = 4;

    // sliding window of recent grants plus a mirroring count of ones
    reg [7:0] win;
    reg [3:0] ones;

    // three-step chain: arm -> start -> finish
    reg saw_arm, saw_start, saw_finish;

    // scope register: high until the first flush ever happens
    reg before_flush;

    initial begin
        win          = 8'b0;
        ones         = 4'd0;
        saw_arm      = 1'b0;
        saw_start    = 1'b0;
        saw_finish   = 1'b0;
        before_flush = 1'b1;
    end

    // rate limiter: a grant is only issued while the window is not saturated
    assign grant = req && (ones < LIMIT);

    // the count of ones moves by at most one per sample
    wire [3:0] ones_next = ones + {3'b000, grant} - {3'b000, win[7]};

    // chain milestones, keyed on the occupancy of the window
    wire arm_evt    = ce && (ones_next == 4'd1);
    wire start_evt  = ce && (ones_next == 4'd2);
    wire finish_evt = ce && (ones_next == 4'd4);

    always @(posedge clk) begin
        if (ce) begin
            win  <= {win[6:0], grant};
            ones <= ones_next;
            if (flush) begin
                before_flush <= 1'b0;
                saw_arm      <= 1'b0;
                saw_start    <= 1'b0;
                saw_finish   <= 1'b0;
            end else begin
                if (arm_evt)    saw_arm    <= 1'b1;
                if (start_evt)  saw_start  <= 1'b1;
                if (finish_evt) saw_finish <= 1'b1;
            end
        end
    end

    // Chain precedence, in the scope before the first flush:
    // finish can never be observed unless start and arm already happened.
    assert property (!before_flush || !saw_finish || (saw_start && saw_arm));

endmodule

module dma_burst_engine (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       start,
    input  wire [3:0] req_len,
    output reg        busy,
    output reg        beat_valid
);
    // beats remaining in the current burst
    reg [3:0] beats;
    // beats already pushed out in the current burst
    reg [3:0] done_cnt;
    // sticky: set the first time a burst is ever launched
    reg       armed;

    // the engine never accepts a burst longer than 5 beats
    wire [3:0] clamped = (req_len > 4'd5) ? 4'd5 : req_len;

    initial begin
        beats      = 4'd0;
        done_cnt   = 4'd0;
        busy       = 1'b0;
        armed      = 1'b0;
        beat_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            beats      <= 4'd0;
            done_cnt   <= 4'd0;
            busy       <= 1'b0;
            armed      <= 1'b0;
            beat_valid <= 1'b0;
        end else if (ce) begin
            beat_valid <= 1'b0;
            if (busy) begin
                // one beat of the burst leaves the engine
                beats      <= beats - 4'd1;
                done_cnt   <= done_cnt + 4'd1;
                busy       <= (beats > 4'd1);
                beat_valid <= 1'b1;
            end else if (start && clamped != 4'd0) begin
                beats    <= clamped;
                done_cnt <= 4'd0;
                busy     <= 1'b1;
                armed    <= 1'b1;
            end
        end
    end

    // P: once the engine has ever started a burst, no burst ever delivers
    // more than 5 beats, even though done_cnt is 4 bits wide.
    always @(posedge clk)
        if (armed)
            assert (done_cnt <= 4'd5);
endmodule

module hwm_stack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_en,
    input  wire       i_push,
    input  wire       i_pop,
    input  wire [7:0] i_item,
    output wire [3:0] o_sp,
    output wire [3:0] o_hwm,
    output wire       o_deep
);
    // Placement stack for footprint records: pointer plus a high-water mark
    // that only ever ratchets upward, and a shadow flag recording that the
    // stack was once at least half full.

    reg [3:0] sp;         // stack pointer, 0..8
    reg [3:0] hwm;        // high-water mark, 0..8
    reg       deep_flag;  // shadow: a deep occupancy event happened earlier
    reg [7:0] mem [0:7];

    integer k;
    initial begin
        sp        = 4'd0;
        hwm       = 4'd0;
        deep_flag = 1'b0;
        for (k = 0; k < 8; k = k + 1) mem[k] = 8'd0;
    end

    wire do_push = i_en && i_push && !i_pop && (sp != 4'd8);
    wire do_pop  = i_en && i_pop  && !i_push && (sp != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            sp        <= 4'd0;
            hwm       <= 4'd0;
            deep_flag <= 1'b0;
        end else if (i_en) begin
            if (do_push) begin
                sp <= sp + 4'd1;
                if ((sp + 4'd1) > hwm)
                    hwm <= sp + 4'd1;
                mem[sp[2:0]] <= i_item;
            end else if (do_pop) begin
                sp <= sp - 4'd1;
            end
            // shadow register: remember that occupancy reached 4 or more
            deep_flag <= deep_flag || (sp >= 4'd4);
        end
    end

    assign o_sp   = sp;
    assign o_hwm  = hwm;
    assign o_deep = deep_flag;

    // Precedence: if the deep-occupancy flag is observed set now, the high
    // water mark must already record a depth of at least 4.
    always @(*)
        assert (!deep_flag || (hwm >= 4'd4));
endmodule

module qring_precede (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_push,
    input  wire       i_pop,
    output wire       o_full,
    output wire       o_empty,
    output wire [3:0] o_count
);
    parameter CAP = 8;

    // up counter: occupancy.  down counter: free space.  same enable.
    reg [3:0] count;
    reg [3:0] space;
    reg [2:0] wptr, rptr;

    // shadow register: remembers that the queue was already completely full
    reg       ever_full;

    initial count     = 4'd0;
    initial space     = CAP[3:0];
    initial wptr      = 3'd0;
    initial rptr      = 3'd0;
    initial ever_full = 1'b0;

    // flags: fullness is read off the down counter, emptiness off the up counter
    assign o_full  = (space == 4'd0);
    assign o_empty = (count == 4'd0);
    assign o_count = count;

    wire do_push = i_ce && i_push && !o_full;
    wire do_pop  = i_ce && i_pop  && !o_empty;

    wire net_push = do_push && !do_pop;
    wire net_pop  = do_pop  && !do_push;

    always @(posedge i_clk) begin
        if (i_reset) begin
            count <= 4'd0;
            space <= CAP[3:0];
            wptr  <= 3'd0;
            rptr  <= 3'd0;
        end else begin
            if (net_push) begin
                count <= count + 4'd1;
                space <= space - 4'd1;
            end else if (net_pop) begin
                count <= count - 4'd1;
                space <= space + 4'd1;
            end

            if (do_push)
                wptr <= wptr + 3'd1;
            if (do_pop)
                rptr <= rptr + 3'd1;
        end
    end

    // the earlier event: occupancy standing at, or about to reach, capacity
    always @(posedge i_clk) begin
        if (i_reset)
            ever_full <= 1'b0;
        else if ((count == CAP[3:0])
              || (net_push && (count == CAP[3:0] - 4'd1)))
            ever_full <= 1'b1;
    end

    // P: whenever the free-space counter reports the queue full, the fill-up
    //    event must already have been recorded in the shadow register.
    always @(posedge i_clk)
        if (space == 4'd0)
            assert (ever_full);

endmodule

module token_bucket_shaper (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low => all state frozen
    input  wire       req,       // request a grant
    output wire       grant,
    output reg  [3:0] tokens,    // tokens available in the bucket
    output reg  [3:0] reserve,   // tokens not yet refilled (pool)
    output reg  [1:0] timer      // refill timer
);
    // burst size of the shaper: the bucket plus the pool always hold
    // exactly this many tokens between them.
    localparam [3:0] BURST = 4'd6;

    initial tokens  = BURST;
    initial reserve = 4'd0;
    initial timer   = 2'd0;

    wire tick      = (timer == 2'd3);
    wire do_refill = tick && (reserve != 4'd0);
    wire do_grant  = req  && (tokens  != 4'd0);

    assign grant = i_ce && do_grant;

    always @(posedge clk) begin
        if (rst) begin
            tokens  <= BURST;
            reserve <= 4'd0;
            timer   <= 2'd0;
        end else if (i_ce) begin
            timer <= timer + 2'd1;
            case ({do_refill, do_grant})
                2'b10: begin
                    // refill: a token migrates pool -> bucket
                    tokens  <= tokens  + 4'd1;
                    reserve <= reserve - 4'd1;
                end
                2'b01: begin
                    // drain: a token migrates bucket -> pool
                    tokens  <= tokens  - 4'd1;
                    reserve <= reserve + 4'd1;
                end
                default: begin
                    // idle, or refill and grant cancelling out
                    tokens  <= tokens;
                    reserve <= reserve;
                end
            endcase
        end
    end

    // P: neither the bucket nor the pool ever holds more than the burst
    // size, even though each register is 4 bits wide.
    always @(posedge clk) assert (tokens  <= BURST);
    always @(posedge clk) assert (reserve <= BURST);
endmodule

module rot_seq_window (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire [1:0]  sym,
    input  wire [15:0] din,
    input  wire        load,
    input  wire        win_start,
    input  wire        win_stop,
    output reg  [15:0] word,
    output reg         hit
);
    // ---- sequence detector for pattern sym = 1, 2, 3 ----------------
    reg [2:0] prog;    // match progress, 0..3 (3 = full match)
    reg [3:0] onehot;  // one-hot shadow of prog, maintained structurally
    reg       armed;   // window register: opened by win_start, closed by win_stop
    reg       pv;      // past-valid

    initial begin
        prog   = 3'd0;
        onehot = 4'b0001;
        armed  = 1'b0;
        pv     = 1'b0;
        word   = 16'h0000;
        hit    = 1'b0;
    end

    reg [2:0] nprog;
    always @(*) begin
        case (prog)
            3'd0:    nprog = (sym == 2'd1) ? 3'd1 : 3'd0;
            3'd1:    nprog = (sym == 2'd2) ? 3'd2 : ((sym == 2'd1) ? 3'd1 : 3'd0);
            3'd2:    nprog = (sym == 2'd3) ? 3'd3 : ((sym == 2'd1) ? 3'd1 : 3'd0);
            default: nprog = (sym == 2'd1) ? 3'd1 : 3'd0;
        endcase
    end

    wire adv = (nprog == prog + 3'd1);

    // ---- barrel rotate: amount = 4*prog, stage selects taken from onehot ----
    wire [15:0] r4 = (onehot[1] | onehot[3]) ? {word[11:0], word[15:12]} : word;
    wire [15:0] r8 = (onehot[2] | onehot[3]) ? {r4[7:0],   r4[15:8]}     : r4;

    always @(posedge clk) begin
        if (rst) begin
            prog   <= 3'd0;
            onehot <= 4'b0001;
            armed  <= 1'b0;
            word   <= 16'h0000;
            hit    <= 1'b0;
        end else if (ce) begin
            prog <= nprog;
            if (adv)                onehot <= {onehot[2:0], 1'b0};
            else if (nprog == 3'd1) onehot <= 4'b0010;
            else                    onehot <= 4'b0001;

            word <= load ? din : r8;
            hit  <= (nprog == 3'd3);

            if (win_stop)       armed <= 1'b0;
            else if (win_start) armed <= 1'b1;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    // ---- property: inside the window, the previous one-hot shadow was live ----
    always @(posedge clk)
        if (pv && armed)
            assert ($past(onehot) != 4'd0);
endmodule

module pingpong_dbuf (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire       push,
    input  wire       pop,
    output wire       wr_full,
    output wire       rd_empty,
    output wire [3:0] occupancy,
    output wire       half_swapped
);
    // ping-pong double buffer: two halves of 4 entries each.
    // wsel selects the half the writer fills, rsel the half the reader drains;
    // they are flipped together so the two agents never touch the same half.
    reg       wsel  = 1'b0;
    reg       rsel  = 1'b1;
    reg [2:0] cnt0  = 3'd0;   // entries resident in half 0
    reg [2:0] cnt1  = 3'd0;   // entries resident in half 1
    reg [3:0] total = 4'd0;   // shadow occupancy accumulator
    reg       armed = 1'b0;   // sticky: set at the first buffer swap, never cleared
    reg       pv    = 1'b0;

    wire [2:0] wcnt = wsel ? cnt1 : cnt0;
    wire [2:0] rcnt = rsel ? cnt1 : cnt0;

    assign wr_full   = (wcnt == 3'd4);
    assign rd_empty  = (rcnt == 3'd0);
    assign occupancy = total;

    wire do_swap = wr_full && rd_empty;
    wire do_push = push && !wr_full && !do_swap;
    wire do_pop  = pop  && !rd_empty && !do_swap;

    assign half_swapped = en && do_swap;

    always @(posedge clk)
        pv <= 1'b1;

    // arm register: latched on the first swap, never cleared afterwards
    always @(posedge clk)
        if (!rst && en && do_swap)
            armed <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            wsel  <= 1'b0;
            rsel  <= 1'b1;
            cnt0  <= 3'd0;
            cnt1  <= 3'd0;
            total <= 4'd0;
        end else if (en) begin
            if (do_swap) begin
                wsel <= ~wsel;
                rsel <= ~rsel;
            end else begin
                if (do_push) begin
                    if (wsel) cnt1 <= cnt1 + 3'd1;
                    else      cnt0 <= cnt0 + 3'd1;
                end
                if (do_pop) begin
                    if (rsel) cnt1 <= cnt1 - 3'd1;
                    else      cnt0 <= cnt0 - 3'd1;
                end
                total <= total + (do_push ? 4'd1 : 4'd0) - (do_pop ? 4'd1 : 4'd0);
            end
        end
    end

    // P: once the buffer has swapped at least once, every rising edge of the
    // writer-full flag must find the accumulated occupancy at or below 8,
    // even though the accumulator is 4 bits wide.
    always @(posedge clk)
        if (pv && armed && $rose(wr_full))
            assert (total <= 4'd8);
endmodule

module pslice_check (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] data_in,
    output wire [7:0] data_out,
    output wire       par_out,
    output wire       val_out,
    output wire [5:0] o_chk_cnt,
    output wire [5:0] o_ok_cnt
);
    // input register slice, protected by a stored parity bit
    reg [7:0] s0_data;
    reg       s0_par;
    reg       s0_val;

    // output register slice, carries the same protection
    reg [7:0] s1_data;
    reg       s1_par;
    reg       s1_val;

    // retirement bookkeeping
    reg [5:0] chk_cnt;
    reg [5:0] ok_cnt;

    initial begin
        s0_data = 8'h00;
        s0_par  = 1'b0;
        s0_val  = 1'b0;
        s1_data = 8'h00;
        s1_par  = 1'b0;
        s1_val  = 1'b0;
        chk_cnt = 6'd0;
        ok_cnt  = 6'd0;
    end

    // parity checker sitting between the two slices
    wire s0_bad = s0_val && (s0_par ^ (^s0_data));

    always @(posedge clk) begin
        if (rst) begin
            s0_data <= 8'h00;
            s0_par  <= 1'b0;
            s0_val  <= 1'b0;
            s1_data <= 8'h00;
            s1_par  <= 1'b0;
            s1_val  <= 1'b0;
            chk_cnt <= 6'd0;
            ok_cnt  <= 6'd0;
        end else if (ce) begin
            // fill slice 0 with fresh data and its generated parity
            s0_data <= data_in;
            s0_par  <= ^data_in;
            s0_val  <= 1'b1;

            // hand slice 0 over to slice 1, parity travels with the data
            s1_data <= s0_data;
            s1_par  <= s0_par;
            s1_val  <= s0_val;

            // count every retired beat, and separately the clean ones
            if (s0_val) begin
                chk_cnt <= chk_cnt + 6'd1;
                if (!s0_bad)
                    ok_cnt <= ok_cnt + 6'd1;
            end
        end
    end

    assign data_out  = s1_data;
    assign par_out   = s1_par;
    assign val_out   = s1_val;
    assign o_chk_cnt = chk_cnt;
    assign o_ok_cnt  = ok_cnt;

    // P: every retired beat was a clean beat
    always @(*)
        assert (ok_cnt == chk_cnt);
endmodule

// Input-pin debouncer for a core's external interrupt/reset pin.
// A change on the raw pin must be seen on K=4 consecutive enabled samples
// before the clean output flips.  A countdown register tracks the deadline
// of the outstanding change request.
module pin_debounce_deadline (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // sample enable; low => full idle
    input  wire       raw,     // raw asynchronous pin value (already synced)
    output reg        clean,   // debounced value
    output reg        req      // a pin change is currently outstanding
);
    localparam [2:0] K = 3'd4;

    reg [2:0] stab;  // number of consecutive samples disagreeing with clean
    reg [2:0] cnt;   // countdown to the guaranteed flip deadline

    initial begin
        clean = 1'b0;
        stab  = 3'd0;
        cnt   = K;
        req   = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            clean <= 1'b0;
            stab  <= 3'd0;
            cnt   <= K;
            req   <= 1'b0;
        end else if (ce) begin
            if (raw != clean) begin
                if (stab == K - 3'd1) begin
                    // final identical sample: commit the flip, retire request
                    clean <= ~clean;
                    stab  <= 3'd0;
                    cnt   <= K;
                    req   <= 1'b0;
                end else begin
                    stab  <= stab + 3'd1;
                    cnt   <= cnt - 3'd1;
                    req   <= 1'b1;
                end
            end else begin
                // sample agrees with the clean value: abandon the request
                stab  <= 3'd0;
                cnt   <= K;
                req   <= 1'b0;
            end
        end
    end

    // Bounded response (safety form): the deadline countdown must never reach
    // zero while a pin-change request is still outstanding.
    always @(posedge clk)
        assert (!req || cnt != 3'd0);
endmodule

// Transaction scoreboard: arm (credit allocated) -> start (issue) -> finish (retire).
// Retired never exceeds issued, issued never exceeds armed, and each gap is
// bounded by the window WIN.
module txn_scoreboard (
    input  wire       clk,
    input  wire       ce,        // idle when low: no state changes at all
    input  wire       arm_req,
    input  wire       start_req,
    input  wire       fin_req,
    output reg  [3:0] alloc_cnt,
    output reg  [3:0] iss_cnt,
    output reg  [3:0] ret_cnt
);
    localparam [2:0] WIN = 3'd4;

    // credit registers: armed-but-not-started, started-but-not-finished
    reg [2:0] pend_iss;
    reg [2:0] outstanding;

    reg pv;

    initial begin
        alloc_cnt   = 4'd0;
        iss_cnt     = 4'd0;
        ret_cnt     = 4'd0;
        pend_iss    = 3'd0;
        outstanding = 3'd0;
        pv          = 1'b0;
    end

    // the chain is enforced purely through the credit registers
    wire do_arm   = ce && arm_req   && (pend_iss    <  WIN);
    wire do_start = ce && start_req && (pend_iss    != 3'd0) && (outstanding < WIN);
    wire do_fin   = ce && fin_req   && (outstanding != 3'd0);

    always @(posedge clk) begin
        pv <= 1'b1;

        if (do_arm)   alloc_cnt <= alloc_cnt + 4'd1;
        if (do_start) iss_cnt   <= iss_cnt   + 4'd1;
        if (do_fin)   ret_cnt   <= ret_cnt   + 4'd1;

        case ({do_arm, do_start})
            2'b10:   pend_iss <= pend_iss + 3'd1;
            2'b01:   pend_iss <= pend_iss - 3'd1;
            default: pend_iss <= pend_iss;
        endcase

        case ({do_start, do_fin})
            2'b10:   outstanding <= outstanding + 3'd1;
            2'b01:   outstanding <= outstanding - 3'd1;
            default: outstanding <= outstanding;
        endcase
    end

    // P (chain precedence, no-change form): a start cannot be observed unless an
    // arm got ahead of the issue counter, and a finish cannot be observed unless
    // a start got ahead of the retire counter.
    always @(posedge clk)
        if (pv)
            assert (((($past(alloc_cnt) != $past(iss_cnt))) || $stable(iss_cnt)) &&
                    ((($past(iss_cnt)   != $past(ret_cnt))) || $stable(ret_cnt)));
endmodule

module boot_prio_sched (
    input  wire       clk,
    input  wire       i_ce,      // scheduler tick enable; low => full idle
    input  wire       i_flush,   // end of the boot round
    input  wire [7:0] i_req,     // dynamic requests, admitted only after flush
    output wire       o_valid,
    output wire [2:0] o_index,
    output wire [2:0] o_count
);

    // ---------------- state ----------------
    reg [7:0] pending;      // outstanding boot/thread requests
    reg [2:0] o_index_r;    // encoded index, meaningful only while valid
    reg       o_valid_r;    // registered valid flag
    reg [2:0] grant_count;  // retired grants (saturating)
    reg       pre_flush;    // arming register: high until first flush tick

    initial pending     = 8'h0F;   // four statically pinned boot threads
    initial o_index_r   = 3'd0;
    initial o_valid_r   = 1'b0;
    initial grant_count = 3'd0;
    initial pre_flush   = 1'b1;

    // ------------- priority encoder (combinational) -------------
    wire       req_any = |pending;
    reg  [2:0] enc;
    always @(*) begin
        if      (pending[0]) enc = 3'd0;
        else if (pending[1]) enc = 3'd1;
        else if (pending[2]) enc = 3'd2;
        else if (pending[3]) enc = 3'd3;
        else if (pending[4]) enc = 3'd4;
        else if (pending[5]) enc = 3'd5;
        else if (pending[6]) enc = 3'd6;
        else                 enc = 3'd7;
    end

    wire [7:0] gmask = req_any ? (8'h01 << enc) : 8'h00;
    wire [7:0] admit = (!pre_flush) ? i_req : 8'h00;

    // ------------- sequential core -------------
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_flush) begin
                // open the scheduler up: all slots become requestable
                pending   <= 8'hFF;
                o_valid_r <= 1'b0;
                pre_flush <= 1'b0;
            end else begin
                pending   <= (pending & ~gmask) | admit;
                o_valid_r <= req_any;
                if (req_any)
                    o_index_r <= enc;
                if (o_valid_r)
                    grant_count <= (grant_count == 3'd7) ? 3'd7
                                                         : grant_count + 3'd1;
            end
        end
    end

    assign o_valid = o_valid_r;
    assign o_index = o_index_r;
    assign o_count = grant_count;

    // ------------- property -------------
    // Before the scheduler has ever been flushed, and while a grant is
    // actually presented, at most three grants can already have retired.
    always @(posedge clk)
        if (pre_flush && o_valid_r)
            assert (grant_count <= 3'd3);

endmodule

module pwm_duty_tracker (
    input  wire       clk,
    input  wire       ce,
    input  wire [3:0] duty_in,
    output reg  [2:0] count,
    output reg  [3:0] duty,
    output reg  [3:0] high_cnt,
    output reg        out
);
    // clamped duty request, latched only at the period boundary
    wire [3:0] duty_c = (duty_in > 4'd8) ? 4'd8 : duty_in;

    initial count    = 3'd0;
    initial duty     = 4'd4;
    initial high_cnt = 4'd0;
    initial out      = 1'b1;   // 0 < 4

    always @(posedge clk) begin
        if (ce) begin
            if (count == 3'd7) begin
                // end of period: restart, adopt new duty
                count    <= 3'd0;
                duty     <= duty_c;
                high_cnt <= 4'd0;
                out      <= (4'd0 < duty_c);
            end else begin
                count    <= count + 3'd1;
                // accumulate one high cycle whenever the output is asserted
                high_cnt <= high_cnt + (out ? 4'd1 : 4'd0);
                out      <= (({1'b0, count} + 4'd1) < duty);
            end
        end
    end

    // P (part 1): while the output is high, every elapsed cycle of this
    // period was a high cycle
    always @(posedge clk)
        if (out) assert (high_cnt == {1'b0, count});

    // P (part 2): once the output has dropped, exactly duty high cycles
    // have been accumulated in this period
    always @(posedge clk)
        if (!out) assert (high_cnt == duty);
endmodule

module cdc_alu_req (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire [1:0] op,
    input  wire [7:0] a,
    input  wire [7:0] b,
    output reg  [7:0] result,
    output reg        carry,
    output reg        zero,
    output reg        busy
);
    // gray-coded request pointer crossing into the ALU domain
    reg [1:0] wbin  = 2'd0;
    reg [1:0] wgray = 2'b00;
    // two-flop synchronizer
    reg [1:0] s1    = 2'b00;
    reg [1:0] s2    = 2'b00;
    // last pointer value acknowledged on the far side
    reg [1:0] seen  = 2'b00;
    // bounded-response countdown
    reg [1:0] cnt   = 2'd0;
    // latched operands
    reg [7:0] opa   = 8'd0;
    reg [7:0] opb   = 8'd0;
    reg [1:0] opr   = 2'd0;

    initial begin
        busy   = 1'b0;
        result = 8'd0;
        carry  = 1'b0;
        zero   = 1'b0;
    end

    wire [1:0] wbin_nxt  = wbin + 2'd1;
    wire [1:0] wgray_nxt = (wbin_nxt >> 1) ^ wbin_nxt;

    wire issue = ce && start && !busy;
    wire done  = ce && busy && (s2 != seen);

    wire [8:0] sum = {1'b0, opa} + {1'b0, opb};
    wire [8:0] dif = {1'b0, opa} - {1'b0, opb};

    reg [8:0] alu;
    always @(*) begin
        case (opr)
            2'd0:    alu = sum;
            2'd1:    alu = dif;
            2'd2:    alu = {1'b0, opa & opb};
            default: alu = {1'b0, opa | opb};
        endcase
    end

    always @(posedge clk) begin
        if (ce) begin
            s1 <= wgray;
            s2 <= s1;
            if (issue) begin
                wbin  <= wbin_nxt;
                wgray <= wgray_nxt;
                opa   <= a;
                opb   <= b;
                opr   <= op;
                busy  <= 1'b1;
                cnt   <= 2'd3;
            end else if (done) begin
                seen   <= s2;
                busy   <= 1'b0;
                cnt    <= 2'd0;
                result <= alu[7:0];
                carry  <= alu[8];
                zero   <= (alu[7:0] == 8'd0);
            end else if (busy) begin
                cnt <= cnt - 2'd1;
            end
        end
    end

    // Bounded response: the countdown must never expire while a request is
    // still outstanding (window opened by accept, closed by completion).
    always @(posedge clk)
        if (busy)
            assert (cnt != 2'd0);
endmodule

// Tracks in-flight requests in an 8-deep shift register, with a separate
// running count of how many slots are currently occupied.
module inflight_tracker (
    input  wire       clk,
    input  wire       step,     // pipeline advance / idle when low
    input  wire       issue,    // a new request enters slot 0 on this step
    output reg  [7:0] shift,    // occupancy of pipeline slots 0..7
    output reg  [3:0] count,    // number of occupied slots
    output wire       retire,   // request leaving the last slot this step
    output wire       busy
);

    initial shift = 8'b0000_0000;
    initial count = 4'd0;

    assign retire = step && shift[7];
    assign busy   = (count != 4'd0);

    always @(posedge clk) begin
        if (step) begin
            shift <= {shift[6:0], issue};
            count <= count + (issue ? 4'd1 : 4'd0) - (shift[7] ? 4'd1 : 4'd0);
        end
    end

    // P: whenever the occupancy count reads zero, no slot may hold a request.
    always @(*)
        assert (count != 4'd0 || shift == 8'b0000_0000);

endmodule

module symbol_histogram (
    input wire i_clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_dec,        // 0 = tally an incoming symbol, 1 = retire one
    input wire [1:0] i_bin,  // modulation class of the symbol
    input wire i_flush,      // closes the measurement window
    output wire o_empty,
    output wire o_has_data,
    output wire o_armed
);
    // per-modulation symbol tallies
    reg [3:0] bin0, bin1, bin2, bin3;
    // total symbols currently accounted for
    reg [5:0] total;
    // window register: set by the first tally, cleared by a flush
    reg       armed;

    initial bin0  = 4'd0;
    initial bin1  = 4'd0;
    initial bin2  = 4'd0;
    initial bin3  = 4'd0;
    initial total = 6'd0;
    initial armed = 1'b0;

    wire [3:0] sel = (i_bin == 2'd0) ? bin0 :
                     (i_bin == 2'd1) ? bin1 :
                     (i_bin == 2'd2) ? bin2 : bin3;

    wire do_flush = i_ce &&  i_flush;
    wire do_inc   = i_ce && !i_flush && !i_dec && (sel != 4'hF);
    wire do_dec   = i_ce && !i_flush &&  i_dec && (sel != 4'h0);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 6'd0;
            armed <= 1'b0;
        end else if (do_flush) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 6'd0;
            armed <= 1'b0;
        end else if (do_inc) begin
            case (i_bin)
                2'd0: bin0 <= bin0 + 4'd1;
                2'd1: bin1 <= bin1 + 4'd1;
                2'd2: bin2 <= bin2 + 4'd1;
                2'd3: bin3 <= bin3 + 4'd1;
            endcase
            total <= total + 6'd1;
            armed <= 1'b1;
        end else if (do_dec) begin
            case (i_bin)
                2'd0: bin0 <= bin0 - 4'd1;
                2'd1: bin1 <= bin1 - 4'd1;
                2'd2: bin2 <= bin2 - 4'd1;
                2'd3: bin3 <= bin3 - 4'd1;
            endcase
            total <= total - 6'd1;
        end
    end

    assign o_empty    = (total == 6'd0);
    assign o_has_data = (bin0 != 4'd0) || (bin1 != 4'd0) ||
                        (bin2 != 4'd0) || (bin3 != 4'd0);
    assign o_armed    = armed;

    // Absence, after arm until flush: the window never reports empty and
    // holding data at the same time.
    assert property (!armed || !(o_empty && o_has_data));
endmodule

module tmr_cred_gate (
    input wire clk,
    input wire step,
    input wire submit,
    input wire logout,
    input wire [7:0] user,
    input wire [7:0] pass,
    output wire grant_admin,
    output wire grant_guest,
    output wire session_armed
);
    localparam [1:0] ROLE_NONE  = 2'b00;
    localparam [1:0] ROLE_GUEST = 2'b01;
    localparam [1:0] ROLE_ADMIN = 2'b10;

    // three shadow copies of the privilege register (TMR)
    reg [1:0] role_a = ROLE_NONE;
    reg [1:0] role_b = ROLE_NONE;
    reg [1:0] role_c = ROLE_NONE;

    // registered grant lines, driven from the voted privilege code
    reg out_admin = 1'b0;
    reg out_guest = 1'b0;

    // sticky arm: set the first time a credential is ever submitted
    reg armed = 1'b0;

    // bitwise 2-of-3 majority voter
    wire [1:0] vote;
    assign vote[1] = (role_a[1] & role_b[1]) | (role_a[1] & role_c[1]) | (role_b[1] & role_c[1]);
    assign vote[0] = (role_a[0] & role_b[0]) | (role_a[0] & role_c[0]) | (role_b[0] & role_c[0]);

    // scrub path: voted value is written back into all three copies
    wire [1:0] scrub = (vote == 2'b11) ? ROLE_NONE : vote;

    // default-credential table lookup
    wire [1:0] lookup = ((user == 8'hAD) && (pass == 8'h1E)) ? ROLE_ADMIN :
                        ((user == 8'h67) && (pass == 8'h00)) ? ROLE_GUEST :
                                                               ROLE_NONE;

    wire [1:0] role_next = logout ? ROLE_NONE : (submit ? lookup : scrub);

    always @(posedge clk) begin
        if (step) begin
            role_a    <= role_next;
            role_b    <= role_next;
            role_c    <= role_next;
            out_admin <= vote[1];
            out_guest <= vote[0];
            if (submit)
                armed <= 1'b1;
        end
    end

    assign grant_admin   = out_admin;
    assign grant_guest   = out_guest;
    assign session_armed = armed;

    // Absence, after Q: once a credential has been submitted, the admin grant
    // and the guest grant are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(grant_admin && grant_guest));
endmodule

module trace_fifo (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] wdata,
    output wire [7:0] rdata,
    output wire       full,
    output wire       empty
);
    // depth 8 trace queue: 3 address bits + 1 wrap bit per pointer
    reg [3:0] wptr;
    reg [3:0] rptr;
    reg [3:0] count;
    reg [7:0] mem [0:7];

    integer k;
    initial begin
        wptr  = 4'd0;
        rptr  = 4'd0;
        count = 4'd0;
        for (k = 0; k < 8; k = k + 1)
            mem[k] = 8'h00;
    end

    assign full  = (count == 4'd8);
    assign empty = (count == 4'd0);
    assign rdata = mem[rptr[2:0]];

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 4'd0;
            rptr  <= 4'd0;
            count <= 4'd0;
        end else begin
            if (do_push) begin
                mem[wptr[2:0]] <= wdata;
                wptr <= wptr + 4'd1;
            end
            if (do_pop)
                rptr <= rptr + 4'd1;

            if (do_push && !do_pop)
                count <= count + 4'd1;
            else if (do_pop && !do_push)
                count <= count - 4'd1;
        end
    end

    // P: two universal pointer/occupancy agreements, checked in every state
    always @(*) begin
        assert (count != 4'd0 || wptr == rptr);
        assert (count != 4'd8 || wptr[2:0] == rptr[2:0]);
    end
endmodule

module csa_accumulator (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [7:0] i_data,
    output wire [7:0] o_total,
    output wire       o_pending,
    output wire       o_exact
);
    // carry-save accumulator: the running total is kept as two halves,
    // a sum half and a carry half, which always add up to the true total.
    reg [7:0] s;      // sum half
    reg [7:0] c;      // carry half (always even by construction)
    reg [7:0] total;  // redundant plain-binary shadow of the same total
    reg       armed;  // sticky: set the first time a nonzero cell is folded in

    initial begin
        s     = 8'd0;
        c     = 8'd0;
        total = 8'd0;
        armed = 1'b0;
    end

    wire [7:0] next_s = s ^ c ^ i_data;
    wire [7:0] next_c = ((s & c) | (s & i_data) | (c & i_data)) << 1;

    always @(posedge clk) begin
        if (i_ce) begin
            s     <= next_s;
            c     <= next_c;
            total <= total + i_data;
            if (i_data != 8'd0)
                armed <= 1'b1;
        end
    end

    // a carry is still outstanding in the redundant representation
    wire pending = (c != 8'd0);
    // the sum half alone already equals the plain-binary total
    wire exact   = (s == total);

    assign o_total   = total;
    assign o_pending = pending;
    assign o_exact   = exact;

    // Once the accumulator has been armed by a first real fold-in, the
    // "carry outstanding" and "sum half already exact" conditions must
    // never be asserted at the same time.
    always @(*)
        if (armed)
            assert (!(pending && exact));
endmodule

module gray_chain_seq (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    output wire o_armed,
    output wire o_started,
    output wire o_done
);
    // three-step chain: arm, start, finish
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_DONE    = 2'd3;

    // gray codes of the milestone binary counts 3, 7 and 12
    localparam [3:0] G_ARM   = 4'b0010; // gray(3)
    localparam [3:0] G_START = 4'b0100; // gray(7)
    localparam [3:0] G_FIN   = 4'b1010; // gray(12)

    reg [3:0] bin;
    reg [3:0] gray;   // gray-code counter, shadowed by bin
    reg [1:0] stage;

    initial bin   = 4'd0;
    initial gray  = 4'd0;
    initial stage = S_IDLE;

    // saturating binary shadow
    wire [3:0] nbin = (bin == 4'd15) ? 4'd15 : (bin + 4'd1);

    always @(posedge clk) begin
        if (rst) begin
            bin   <= 4'd0;
            gray  <= 4'd0;
            stage <= S_IDLE;
        end else if (ce) begin
            bin  <= nbin;
            gray <= nbin ^ (nbin >> 1);
            case (stage)
                S_IDLE:    if (gray == G_ARM)   stage <= S_ARMED;
                S_ARMED:   if (gray == G_START) stage <= S_STARTED;
                S_STARTED: if (gray == G_FIN)   stage <= S_DONE;
                default:                        stage <= S_DONE;
            endcase
        end
    end

    assign o_armed   = (stage != S_IDLE);
    assign o_started = (stage == S_STARTED) || (stage == S_DONE);
    assign o_done    = (stage == S_DONE);

    // P: the finish step can only be observed after the whole chain ran,
    // i.e. the binary shadow must already be past the finish milestone.
    always @(posedge clk)
        if (stage == S_DONE)
            assert (bin >= 4'd12);

endmodule

module json_watchdog (
    input  wire clk,
    input  wire i_ce,      // parser step enable; low = idle, no state changes
    input  wire kick,      // parser signals progress on the document stream
    output reg  expired,   // watchdog fired: no kick within LIMIT steps
    output reg  halted     // parse session shut down after the strike cap
);
    localparam [3:0] LIMIT = 4'd6;

    // stall counter: steps since the last kick
    reg [3:0] timer;
    // registered "timer is one tick short of LIMIT" marker
    reg       pre;
    // how many times the watchdog has fired during this session
    reg [2:0] strikes;

    reg pv; // past-valid

    initial begin
        timer   = 4'd0;
        pre     = 1'b0;
        expired = 1'b0;
        halted  = 1'b0;
        strikes = 3'd0;
        pv      = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce && !halted) begin
            if (kick) begin
                // parser made progress: rearm the watchdog
                timer   <= 4'd0;
                pre     <= 1'b0;
                expired <= 1'b0;
            end else if (!expired) begin
                if (pre) begin
                    // stall counter reaches the limit: fire, record a strike
                    timer   <= LIMIT;
                    pre     <= 1'b0;
                    expired <= 1'b1;
                    strikes <= strikes + 3'd1;
                    halted  <= ((strikes + 3'd1) == 3'd2);
                end else begin
                    timer <= timer + 4'd1;
                    pre   <= ((timer + 4'd1) == (LIMIT - 4'd1));
                end
            end
            // expired and not kicked: everything frozen until a kick arrives
        end
    end

    // P: the strike counter may only move on the cycle the stall counter moves,
    //    and it never climbs past its cap of two.
    always @(posedge clk)
        if (pv && $stable(timer))
            assert ($stable(strikes) && strikes <= 3'd2);

endmodule

module lfsr_session_monitor (
    input  wire       clk,
    input  wire       ce,      // entropy-draw enable; low => all state frozen
    input  wire       start,   // Q: opens the sampling session window
    input  wire       stop,    // R: closes the sampling session window
    output reg  [7:0] lfsr,
    output reg        window,
    output reg        nz_seen,
    output reg  [2:0] count,
    output wire       done
);
    // ------------------------------------------------------------------
    // Maximal-length Fibonacci LFSR, x^8 + x^6 + x^5 + x^4 + 1.
    // Seeded nonzero, so the all-zeros lockup state is never entered.
    // ------------------------------------------------------------------
    initial lfsr    = 8'h01;
    initial window  = 1'b0;
    initial nz_seen = 1'b0;
    initial count   = 3'd0;

    wire fb = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];

    // a session is "done" once four draws have been consumed inside it
    assign done = window && (count == 3'd4);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (ce)
            lfsr <= {lfsr[6:0], fb};

    // window register: set by start, cleared by stop, may open/close repeatedly.
    // count counts draws inside the current window (saturates at 4).
    // nz_seen is the shadow register: records that a nonzero draw occurred.
    always @(posedge clk) begin
        if (start && !window) begin
            window  <= 1'b1;
            count   <= 3'd0;
            nz_seen <= 1'b0;
        end
        else if (stop && window) begin
            window  <= 1'b0;
        end
        else if (ce && window && (count != 3'd4)) begin
            count   <= count + 3'd1;
            nz_seen <= nz_seen | (lfsr != 8'h00);
        end
    end

    // Property: inside an open session, at the moment done rises, a nonzero
    // draw must already have been recorded earlier in that same session.
    always @(posedge clk)
        if (pv && window)
            assert (!$rose(done) || nz_seen);
endmodule

module cart_write_elastic (
    input  wire       clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_req,
    input  wire       i_two,
    input  wire [7:0] i_data,
    output wire [7:0] o_data,
    output wire       o_valid,
    output wire       o_busy
);
    // two-entry elastic buffer for flash program bytes
    reg       v_head, v_tail;   // head/tail occupancy flags
    reg [7:0] d_head, d_tail;
    reg [1:0] count;            // occupancy counter, mirrors the flags
    reg [2:0] timer;            // completion countdown
    reg       win;              // window register: armed on accept, cleared on drain

    initial v_head = 1'b0;
    initial v_tail = 1'b0;
    initial d_head = 8'h00;
    initial d_tail = 8'h00;
    initial count  = 2'd0;
    initial timer  = 3'd0;
    initial win    = 1'b0;

    always @(posedge clk) begin
        if (i_rst) begin
            v_head <= 1'b0;
            v_tail <= 1'b0;
            d_head <= 8'h00;
            d_tail <= 8'h00;
            count  <= 2'd0;
            timer  <= 3'd0;
            win    <= 1'b0;
        end else if (i_ce) begin
            if (!win) begin
                // accept a new burst request (one or two bytes)
                if (i_req) begin
                    v_head <= 1'b1;
                    d_head <= i_data;
                    v_tail <= i_two;
                    d_tail <= i_data ^ 8'h5a;
                    count  <= i_two ? 2'd2 : 2'd1;
                    timer  <= 3'd3;
                    win    <= 1'b1;
                end
            end else begin
                // draining: one byte committed to the cart per enabled cycle
                timer <= timer - 3'd1;
                if (count == 2'd2) begin
                    d_head <= d_tail;
                    v_tail <= 1'b0;
                    count  <= 2'd1;
                end else begin
                    v_head <= 1'b0;
                    count  <= 2'd0;
                    win    <= 1'b0;
                end
            end
        end
    end

    assign o_data  = d_head;
    assign o_valid = v_head;
    assign o_busy  = win;

    // Bounded response (safety): the countdown never expires while the
    // accepted burst is still outstanding.
    always @(posedge clk)
        if (win)
            assert (timer != 3'd0);
endmodule

module call_debounce_lift (
    input  wire       clk,
    input  wire       ce,      // sample / step enable; low = whole design idles
    input  wire       btn,     // raw (bouncy) hall-call button at the top floor
    output reg  [1:0] floor,
    output reg        clean    // debounced call line
);
    localparam integer K          = 4;     // identical consecutive samples needed
    localparam [1:0]   CALL_FLOOR = 2'd3;

    reg [2:0] cnt;      // stability counter: consecutive samples differing from clean
    reg       req;      // latched pending request
    reg       moving;   // cab in motion
    reg       armed;    // starts high, cleared the first time the cab departs
    reg       pv;       // past-valid

    initial begin
        floor  = 2'd0;
        clean  = 1'b0;
        cnt    = 3'd0;
        req    = 1'b0;
        moving = 1'b0;
        armed  = 1'b1;
        pv     = 1'b0;
    end

    wire mismatch = (btn != clean);
    wire flip     = mismatch && (cnt == 3'd3);   // K-1 previous mismatches + this one
    wire go       = req && !moving;
    wire arrive   = moving && (floor == CALL_FLOOR);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            // ---- debouncer: K identical consecutive samples flip the clean output ----
            if (mismatch) begin
                if (cnt == 3'd3) cnt <= 3'd0;
                else             cnt <= cnt + 3'd1;
            end else begin
                cnt <= 3'd0;
            end

            if (flip) clean <= ~clean;

            // rising edge of the debounced line latches a hall call
            if (flip && !clean) req <= 1'b1;

            // ---- cab control: one floor of travel per step ----
            if (go) begin
                moving <= 1'b1;
                req    <= 1'b0;
                armed  <= 1'b0;      // first departure clears the scope register
            end else if (arrive) begin
                moving <= 1'b0;
            end else if (moving) begin
                floor <= floor + 2'd1;
            end
        end
    end

    // P: before the cab has ever departed, the floor register never changes
    always @(posedge clk)
        if (pv && armed)
            assert (floor == $past(floor));
endmodule

module txn_scoreboard_deadline (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_issue,
    input  wire       i_retire,
    output wire [3:0] o_outstanding,
    output wire       o_armed
);
    // Scoreboard: issued vs retired transaction counters.
    reg [3:0] issued   = 4'd0;
    reg [3:0] retired  = 4'd0;
    // Completion countdown for the oldest outstanding transaction.
    reg [2:0] deadline = 3'd5;
    // Registered early-warning flag that triggers the forced retire.
    reg       urgent   = 1'b0;
    // Sticky arm: set the first time a transaction is ever accepted.
    reg       armed    = 1'b0;

    wire [3:0] outstanding = issued - retired;

    wire issue_ok  = i_issue && (outstanding < 4'd4);
    wire force_ret = urgent && (deadline == 3'd1);
    wire retire_ok = (outstanding != 4'd0) && (i_retire || force_ret);

    wire [3:0] out_n = outstanding
                     + (issue_ok  ? 4'd1 : 4'd0)
                     - (retire_ok ? 4'd1 : 4'd0);

    wire [2:0] dl_n = (retire_ok || (issue_ok && (outstanding == 4'd0))) ? 3'd5 :
                      ((outstanding != 4'd0) ? (deadline - 3'd1) : deadline);

    always @(posedge clk) begin
        if (i_ce) begin
            if (issue_ok)  issued  <= issued  + 4'd1;
            if (retire_ok) retired <= retired + 4'd1;
            deadline <= dl_n;
            urgent   <= (out_n != 4'd0) && (dl_n <= 3'd2);
            if (issue_ok) armed <= 1'b1;
        end
    end

    assign o_outstanding = outstanding;
    assign o_armed       = armed;

    // Bounded response (safety form), after-Q scope: once the scoreboard has
    // ever accepted a transaction, the completion countdown must never expire
    // while work is still outstanding.
    always @(posedge clk)
        if (armed && (outstanding != 4'd0))
            assert (deadline != 3'd0);
endmodule

module rr_arbiter_insight (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [3:0] req,
    output reg  [3:0] grant,
    output reg        gvalid,
    output reg  [3:0] last
);
    // priority token starts just after the last granted line
    wire [3:0] base = {last[2:0], last[3]};

    // unrolled ring scan over two copies of the request vector
    wire [7:0] r8 = {req, req};
    wire [7:0] b8 = {base, base};
    wire [7:0] tok;

    assign tok[0] = b8[0];
    assign tok[1] = b8[1] | (tok[0] & ~r8[0]);
    assign tok[2] = b8[2] | (tok[1] & ~r8[1]);
    assign tok[3] = b8[3] | (tok[2] & ~r8[2]);
    assign tok[4] = b8[4] | (tok[3] & ~r8[3]);
    assign tok[5] = b8[5] | (tok[4] & ~r8[4]);
    assign tok[6] = b8[6] | (tok[5] & ~r8[5]);
    assign tok[7] = b8[7] | (tok[6] & ~r8[6]);

    wire [7:0] g8  = r8 & tok;
    wire [3:0] gnt = g8[3:0] | g8[7:4];

    initial last   = 4'b0001;
    initial grant  = 4'b0000;
    initial gvalid = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            last   <= 4'b0001;
            grant  <= 4'b0000;
            gvalid <= 1'b0;
        end else if (ce) begin
            grant  <= gnt;
            gvalid <= |gnt;
            if (|gnt)
                last <= gnt;
        end
    end

    // P: whenever a grant is outstanding, no two lines are granted together
    always @(posedge clk)
        if (gvalid)
            assert ((grant & (grant - 4'd1)) == 4'd0);
endmodule

module clkdiv_phase_tick (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output wire       div_en,
    output wire [3:0] beat_o,
    output wire [2:0] phase_o
);
    // Divide-by-5 phase counter with a parallel one-hot phase ring.
    // The divided enable pulse fires exactly on the cycle after the phase wraps.
    localparam [2:0] DIVM1 = 3'd4;

    reg [2:0] phase;
    reg [4:0] oh;      // one-hot mirror of the phase counter
    reg       tick;    // registered divided-enable pulse
    reg [3:0] beat;    // slow-domain beat counter, advanced by tick

    initial phase = 3'd0;
    initial oh    = 5'b00001;
    initial tick  = 1'b0;
    initial beat  = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            phase <= 3'd0;
            oh    <= 5'b00001;
            tick  <= 1'b0;
            beat  <= 4'd0;
        end else if (ce) begin
            phase <= (phase == DIVM1) ? 3'd0 : (phase + 3'd1);
            oh    <= { oh[3:0], oh[4] };
            tick  <= oh[4];
            beat  <= beat + { 3'b000, tick };
        end
    end

    assign div_en  = tick;
    assign beat_o  = beat;
    assign phase_o = phase;

    // P: whenever the divided enable is asserted, the phase counter has just wrapped.
    always @(posedge clk)
        if (tick)
            assert (phase == 3'd0);
endmodule

module pingpong_buffer (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       wr_data_valid,
    input  wire       rd_ready,
    input  wire       start,
    input  wire       stop,
    output wire [2:0] wr_addr,
    output wire [2:0] rd_addr,
    output wire       busy
);
    localparam [2:0] HALF = 3'd4;

    // ping-pong double buffer: writer owns half wr_sel, reader owns half rd_sel
    reg       wr_sel;
    reg       rd_sel;
    reg [2:0] wcnt;      // words written into the write half
    reg [2:0] rcnt;      // words consumed from the read half
    reg       rd_valid;  // read half currently holds a full block
    reg       active;    // streaming session engaged
    reg       pv;        // past-valid

    initial begin
        wr_sel   = 1'b0;
        rd_sel   = 1'b1;
        wcnt     = 3'd0;
        rcnt     = 3'd0;
        rd_valid = 1'b0;
        active   = 1'b0;
        pv       = 1'b0;
    end

    wire do_write = ce && wr_data_valid && (wcnt != HALF);
    wire do_read  = ce && rd_ready && rd_valid && (rcnt != HALF);
    wire swap     = ce && (wcnt == HALF) && !rd_valid;

    assign wr_addr = {wr_sel, wcnt[1:0]};
    assign rd_addr = {rd_sel, rcnt[1:0]};
    assign busy    = active;

    always @(posedge clk) begin
        pv <= 1'b1;
    end

    always @(posedge clk) begin
        if (ce) begin
            if (rst) begin
                wr_sel   <= 1'b0;
                rd_sel   <= 1'b1;
                wcnt     <= 3'd0;
                rcnt     <= 3'd0;
                rd_valid <= 1'b0;
                active   <= 1'b0;
            end else begin
                if (stop)
                    active <= 1'b0;
                else if (start)
                    active <= 1'b1;

                if (swap) begin
                    // both owners move to the opposite half on the same edge
                    wr_sel   <= ~wr_sel;
                    rd_sel   <= ~rd_sel;
                    wcnt     <= 3'd0;
                    rcnt     <= 3'd0;
                    rd_valid <= 1'b1;
                end else begin
                    if (do_write)
                        wcnt <= wcnt + 3'd1;
                    if (do_read) begin
                        rcnt <= rcnt + 3'd1;
                        if ((rcnt + 3'd1) == HALF)
                            rd_valid <= 1'b0;
                    end
                end
            end
        end
    end

    // P: whenever a streaming session engages, the two owners are on opposite halves
    always @(posedge clk) begin
        if (pv && $rose(active))
            assert (wr_sel != rd_sel);
    end
endmodule

module gray_profile_bucket (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_start,
    output wire [3:0] o_gray,
    output wire       o_hi_bucket,
    output wire       o_lo_bucket,
    output wire       o_armed
);
    // binary sample counter and its gray-coded shadow
    reg [3:0] bin;
    reg [3:0] gray;

    // profiling bucket flags, sampled from the two representations
    reg       flag_hi;   // sampled from the gray view
    reg       flag_lo;   // sampled from the binary view

    // sticky arming register: set the first time a profiling run starts
    reg       armed;

    initial bin     = 4'd0;
    initial gray    = 4'd0;
    initial flag_hi = 1'b0;
    initial flag_lo = 1'b0;
    initial armed   = 1'b0;

    wire [3:0] bin_next = bin + 4'd1;

    always @(posedge i_clk) begin
        if (i_reset) begin
            bin     <= 4'd0;
            gray    <= 4'd0;
            flag_hi <= 1'b0;
            flag_lo <= 1'b0;
            armed   <= 1'b0;
        end else if (i_ce) begin
            bin     <= bin_next;
            gray    <= bin_next ^ (bin_next >> 1);
            // hi bucket recognised from the gray encoding of sample 8
            flag_hi <= (gray == 4'b1100);
            // lo bucket recognised directly from the binary shadow
            flag_lo <= (bin < 4'd8);
            if (i_start)
                armed <= 1'b1;
        end
    end

    assign o_gray      = gray;
    assign o_hi_bucket = flag_hi;
    assign o_lo_bucket = flag_lo;
    assign o_armed     = armed;

    // Absence, in the "after arming" scope: once a profiling run has been
    // started, a sample can never be reported in the high bucket and the
    // low bucket at the same time.
    always @(posedge i_clk)
        if (armed && flag_hi)
            assert (!flag_lo);
endmodule

// Sliding-window grant rate limiter for an accelerator DMA port.
// A shift register of the last 8 cycles of grants, plus a running
// count of the ones in that window used to throttle new requests.
module dma_rate_limiter (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // idle condition: low leaves all state unchanged
    input  wire i_req,
    output wire o_grant
);
    localparam [3:0] MAXG = 4'd3;   // at most 3 grants per 8-cycle window

    reg [7:0] win;    // recent grant history, win[7] is the oldest entry
    reg [3:0] ones;   // mirrors the number of ones in win
    reg       armed;  // sticky: set the first time a grant is issued

    initial begin
        win   = 8'd0;
        ones  = 4'd0;
        armed = 1'b0;
    end

    wire grant = i_ce && i_req && (ones < MAXG);
    assign o_grant = grant;

    wire [3:0] inc = grant  ? 4'd1 : 4'd0;
    wire [3:0] dec = win[7] ? 4'd1 : 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            win   <= 8'd0;
            ones  <= 4'd0;
            armed <= 1'b0;
        end else if (i_ce) begin
            win  <= {win[6:0], grant};
            ones <= ones + inc - dec;
            if (grant)
                armed <= 1'b1;
        end
    end

    // Two status conditions exported to the scheduler
    wire sat       = (ones == MAXG);   // window quota exhausted
    wire win_empty = (win == 8'd0);    // no grants anywhere in the window

    // Absence: once the port has issued its first grant, the limiter can
    // never report a saturated quota and an empty window at the same time.
    assert property (!armed || !(sat && win_empty));

endmodule

module fetch_skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       in_valid,
    input  wire [7:0] in_data,
    input  wire       out_ready,
    output wire       in_ready,
    output reg        out_valid,
    output reg [7:0]  out_data
);
    // ---- skid buffer of a valid/ready instruction-fetch pipeline stage ----
    reg       skid_valid;
    reg [7:0] skid_data;   // only meaningful while skid_valid (stall flag) is up
    reg [2:0] occ;         // shadow occupancy counter
    reg       armed;       // sticky: set the first time back-pressure stalls us

    initial begin
        out_valid  = 1'b0;
        out_data   = 8'h00;
        skid_valid = 1'b0;
        skid_data  = 8'h00;
        occ        = 3'd0;
        armed      = 1'b0;
    end

    assign in_ready = !skid_valid;

    wire in_fire   = in_valid  && in_ready;
    wire out_fire  = out_valid && out_ready;
    wire capture   = in_fire && out_valid && !out_ready; // stall: park word in skid
    wire drain     = !out_valid || out_ready;            // output slot becomes free

    always @(posedge clk) begin
        if (rst) begin
            out_valid  <= 1'b0;
            out_data   <= 8'h00;
            skid_valid <= 1'b0;
            skid_data  <= 8'h00;
            occ        <= 3'd0;
        end else begin
            if (capture) begin
                skid_valid <= 1'b1;
                skid_data  <= in_data;
            end

            if (drain) begin
                if (skid_valid) begin
                    out_valid  <= 1'b1;
                    out_data   <= skid_data;
                    skid_valid <= 1'b0;
                end else if (in_fire) begin
                    out_valid  <= 1'b1;
                    out_data   <= in_data;
                end else begin
                    out_valid  <= 1'b0;
                end
            end

            // occupancy bookkeeping
            if (in_fire && !out_fire)
                occ <= occ + 3'd1;
            else if (!in_fire && out_fire)
                occ <= occ - 3'd1;
        end
    end

    // sticky arm: first stall event, never cleared (not even by reset)
    always @(posedge clk) begin
        if (capture)
            armed <= 1'b1;
    end

    // P: once the stage has ever stalled, the tracked occupancy never exceeds
    //    the two physical slots (output register + skid buffer).
    always @(*)
        assert (!armed || (occ <= 3'd2));
endmodule

module dma_slice_parity (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] word_in,
    output reg        done
);
    // words remaining in the block transfer
    reg [3:0] count;
    // register slice protected by a parity bit
    reg [7:0] data;
    reg       par;
    // shadow slice: the previously transferred word and its parity bit
    reg [7:0] sdata;
    reg       spar;
    // integrity flags, loaded from the slices at the moment they are rotated
    reg       cur_ok;
    reg       shd_ok;

    initial begin
        count  = 4'd8;
        data   = 8'h00;
        par    = 1'b0;
        sdata  = 8'h00;
        spar   = 1'b0;
        cur_ok = 1'b1;
        shd_ok = 1'b1;
        done   = 1'b0;
    end

    wire xfer = ce && (count != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            count  <= 4'd8;
            data   <= 8'h00;
            par    <= 1'b0;
            sdata  <= 8'h00;
            spar   <= 1'b0;
            cur_ok <= 1'b1;
            shd_ok <= 1'b1;
            done   <= 1'b0;
        end else if (xfer) begin
            // check both slices against their parity bits before rotating them
            cur_ok <= (par  == ^data);
            shd_ok <= (spar == ^sdata);
            // rotate: current slice becomes the shadow, new word enters the slice
            sdata  <= data;
            spar   <= par;
            data   <= word_in;
            par    <= ^word_in;
            count  <= count - 4'd1;
            done   <= (count == 4'd1);
        end
    end

    // P1: once any word has moved through the slice, the word that was there
    //     earlier must have been parity-clean when it was displaced
    always @(posedge clk)
        if (count != 4'd8)
            assert (cur_ok);

    // P2: likewise for the shadow copy of the earlier word
    always @(posedge clk)
        if (count != 4'd8)
            assert (shd_ok);
endmodule

module onehot_pipe_gauge (
    input  wire clk,
    input  wire rst,
    input  wire step,
    input  wire start,
    output wire busy,
    output wire [2:0] o_cnt
);
    // one-hot pipeline walker: S0 -> S1 -> S2 -> S3 -> S4 -> S0
    localparam [4:0] S0 = 5'b00001,
                     S1 = 5'b00010,
                     S2 = 5'b00100,
                     S3 = 5'b01000,
                     S4 = 5'b10000;

    reg [4:0] st;
    reg [2:0] cnt;   // stage gauge: how far down the pipe we are
    reg       pv;

    initial st  = S0;
    initial cnt = 3'd0;
    initial pv  = 1'b0;

    // advance / clear terms are only mutually exclusive because st is one-hot
    wire adv = st[1] | st[2] | st[3];
    wire clr = st[0] | st[4];

    reg [4:0] nxt;
    always @(*) begin
        nxt = 5'b00000;
        if (st[0]) nxt = nxt | (start ? S1 : S0);
        if (st[1]) nxt = nxt | S2;
        if (st[2]) nxt = nxt | S3;
        if (st[3]) nxt = nxt | S4;
        if (st[4]) nxt = nxt | S0;
    end

    always @(posedge clk) begin
        if (rst) begin
            st  <= S0;
            cnt <= 3'd0;
        end else if (step) begin
            st <= nxt;
            if (adv)
                cnt <= cnt + 3'd1;
            else if (clr)
                cnt <= 3'd0;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign busy  = |st[4:1];
    assign o_cnt = cnt;

    // P: while the one-hot state does not change, the stage gauge must not
    //    change either, and it never exceeds 3 (its width allows 7).
    always @(posedge clk)
        if (pv && $stable(st))
            assert ($stable(cnt) && cnt <= 3'd3);
endmodule

module wdt_strike_monitor (
    input  wire       clk,
    input  wire       ce,      // global enable: low freezes the whole watchdog
    input  wire       kick,    // software kick / feed of the watchdog
    output reg  [3:0] cnt,     // watchdog up-counter
    output reg        expired, // timeout flag (counter reached the limit)
    output reg  [2:0] misses,  // number of missed kicks (strike counter)
    output reg        halted,  // lockout after too many strikes
    output reg        armed    // sticky: set at the first kick, never cleared
);

    localparam [3:0] TIMEOUT = 4'd9;  // watchdog limit
    localparam [2:0] MAXMISS = 3'd3;  // strikes tolerated before lockout

    initial cnt     = 4'd0;
    initial expired = 1'b0;
    initial misses  = 3'd0;
    initial halted  = 1'b0;
    initial armed   = 1'b0;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce && !halted) begin
            if (kick) begin
                // feeding the dog rewinds the timer and clears the timeout
                cnt     <= 4'd0;
                expired <= 1'b0;
                armed   <= 1'b1;
            end else if (!expired) begin
                // free running towards the limit; saturates there
                cnt <= cnt + 4'd1;
                if (cnt + 4'd1 == TIMEOUT) begin
                    expired <= 1'b1;
                    misses  <= misses + 3'd1;
                    if (misses == MAXMISS - 3'd1)
                        halted <= 1'b1;   // lockout: freeze everything
                end
            end
        end
    end

    // P: once the watchdog has ever been kicked, the strike counter observed
    //    in the previous cycle never exceeded MAXMISS (3) although it is 3 bits wide.
    always @(posedge clk)
        if (pv && armed)
            assert ($past(misses) <= MAXMISS);

endmodule

module stack_hwm_limit (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    output reg  [3:0] sp,
    output reg  [3:0] hwm,
    output wire       full
);
    // depth limit is enforced through the ratcheting high-water mark,
    // never through the pointer itself
    localparam [3:0] LIMIT = 4'd10;

    wire [3:0] sp_next = sp + 4'd1;

    assign full = (hwm >= LIMIT);

    initial sp  = 4'd0;
    initial hwm = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            sp  <= 4'd0;
            hwm <= 4'd0;
        end else if (pop && (sp != 4'd0)) begin
            sp  <= sp - 4'd1;          // mark never falls back
        end else if (push && !full) begin
            sp  <= sp_next;
            if (sp_next > hwm)
                hwm <= sp_next;        // mark only ratchets upward
        end
    end

    // P, part 1: occupancy never exceeds 10 though 4 bits allow 15
    always @(posedge clk)
        assert (sp <= LIMIT);

    // P, part 2: the high-water mark never exceeds 10 either
    always @(posedge clk)
        assert (hwm <= LIMIT);
endmodule

module tmr_alert_window (
    input  wire       clk,
    input  wire       ce,       // global enable: low => all state frozen
    input  wire       load,     // write a new severity into the redundant bank
    input  wire [3:0] sev_in,
    input  wire       q_open,   // Q: escalation opened  (arms the window)
    input  wire       r_close,  // R: escalation closed  (disarms the window)
    output wire [3:0] voted,
    output wire       in_window
);
    // triple-modular-redundant severity register
    reg [3:0] copy_a;
    reg [3:0] copy_b;
    reg [3:0] copy_c;

    // shadow register: severity recorded at the moment the window opened
    reg [3:0] arm_val;
    // window register: set by Q, cleared by R
    reg       armed;

    initial begin
        copy_a  = 4'b0000;
        copy_b  = 4'b0000;
        copy_c  = 4'b0000;
        arm_val = 4'b0000;
        armed   = 1'b0;
    end

    // bitwise majority voter over the three shadow copies
    wire [3:0] vote = (copy_a & copy_b) | (copy_a & copy_c) | (copy_b & copy_c);

    assign voted     = vote;
    assign in_window = armed;

    // the bank is only rewritten while the window is closed and not opening
    wire do_load = ce && load && !armed && !q_open;

    always @(posedge clk) begin
        if (do_load) begin
            copy_a <= sev_in;
            copy_b <= sev_in;
            copy_c <= sev_in;
        end
        if (ce) begin
            if (r_close) begin
                armed <= 1'b0;
            end else if (q_open) begin
                armed   <= 1'b1;
                arm_val <= copy_a;   // capture from the primary copy
            end
        end
    end

    // P: inside the escalation window, what is voted now must be exactly the
    // severity that was recorded earlier, when the window was opened.
    always @(*)
        if (armed)
            assert (vote == arm_val);

endmodule

module dma_burst_engine (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire [3:0]  i_len,
    input  wire [27:0] i_addr,
    output wire        o_busy,
    output wire        o_last,
    output wire [27:0] o_addr,
    output wire [3:0]  o_sent
);

    // ---- burst engine state -------------------------------------------
    reg        busy       = 1'b0;   // up exactly while beats remain
    reg [3:0]  beats      = 4'd0;   // beats remaining in current burst
    reg [3:0]  words_sent = 4'd0;   // beats already issued this burst
    reg [3:0]  len_reg    = 4'd0;   // latched burst length
    reg [27:0] addr       = 28'd0;  // running beat address

    wire start_ok = start && (i_len != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            busy       <= 1'b0;
            beats      <= 4'd0;
            words_sent <= 4'd0;
            len_reg    <= 4'd0;
            addr       <= 28'd0;
        end else if (ce) begin
            if (busy) begin
                // issue one beat
                beats      <= beats - 4'd1;
                words_sent <= words_sent + 4'd1;
                addr       <= addr + 28'd4;
                if (beats == 4'd1)
                    busy <= 1'b0;
            end else if (start_ok) begin
                // accept a new burst descriptor
                busy       <= 1'b1;
                beats      <= i_len;
                words_sent <= 4'd0;
                len_reg    <= i_len;
                addr       <= i_addr;
            end
        end
        // ce low: engine stalls, every register holds its value
    end

    assign o_busy = busy;
    assign o_last = busy && (beats == 4'd1);
    assign o_addr = addr;
    assign o_sent = words_sent;

    // ---- property: while the engine is busy it has strictly fewer beats
    // ---- issued than the latched burst length -------------------------
    always @(posedge clk)
        if (busy)
            assert (words_sent < len_reg);

endmodule

// Log-event chain detector: watches a token stream for the ordered
// sequence AUTH_REQ -> SESSION_OPEN -> SUDO_OK and raises an alert.
module log_chain_detect (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire [2:0] tok,     // event token from the parsed log line
    output wire       o_armed,
    output wire       o_started,
    output wire       o_alert
);
    localparam [2:0] PAT0 = 3'd1;  // AUTH_REQ
    localparam [2:0] PAT1 = 3'd4;  // SESSION_OPEN
    localparam [2:0] PAT2 = 3'd6;  // SUDO_OK
    localparam [2:0] PLEN = 3'd3;

    // match-progress register: how many pattern tokens seen in order
    reg [2:0] prog;
    // chain-stage flags, set as the progress register passes each stage
    reg       r_arm;
    reg       r_start;
    reg       r_fin;

    initial prog    = 3'd0;
    initial r_arm   = 1'b0;
    initial r_start = 1'b0;
    initial r_fin   = 1'b0;

    wire [2:0] expect_tok = (prog == 3'd0) ? PAT0 :
                            (prog == 3'd1) ? PAT1 : PAT2;

    wire advance = ce && (prog < PLEN) && (tok == expect_tok);

    always @(posedge clk) begin
        if (rst) begin
            prog    <= 3'd0;
            r_arm   <= 1'b0;
            r_start <= 1'b0;
            r_fin   <= 1'b0;
        end else if (advance) begin
            prog <= prog + 3'd1;
            if (prog == 3'd0) r_arm   <= 1'b1;
            if (prog == 3'd1) r_start <= 1'b1;
            if (prog == 3'd2) r_fin   <= 1'b1;
        end
    end

    assign o_armed   = r_arm;
    assign o_started = r_start;
    assign o_alert   = r_fin;

    // Chain precedence, globally: the finish stage can never be observed
    // unless both earlier stages of the chain already happened.
    assert property (!r_fin || (r_start && r_arm));
endmodule

// Gray-coded write pointer crossing into a second clock domain through a
// two-flop synchronizer, with a shadow register that records the first
// nonzero sample observed on the first synchronizer stage.
module gray_cdc_first_sample (
    input  wire       clk,
    input  wire       ce,      // idle condition: ce low freezes all state
    output wire [3:0] sync_ptr
);
    reg [3:0] wbin;         // binary write pointer (saturating)
    reg [3:0] wgray;        // gray-coded write pointer
    reg [3:0] s1, s2;       // two-flop synchronizer stages
    reg       sh_valid;     // shadow: a nonzero stage-1 sample was seen
    reg [3:0] sh_val;       // shadow: value of that first nonzero sample
    reg       before_first; // scope: high until s2 has ever been nonzero
    reg       pv;           // past-valid

    initial begin
        wbin         = 4'd0;
        wgray        = 4'b0000;
        s1           = 4'b0000;
        s2           = 4'b0000;
        sh_valid     = 1'b0;
        sh_val       = 4'b0000;
        before_first = 1'b1;
        pv           = 1'b0;
    end

    wire [3:0] wbin_nxt = (wbin == 4'hF) ? wbin : (wbin + 4'd1);

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ce) begin
            wbin  <= wbin_nxt;
            wgray <= wbin_nxt ^ (wbin_nxt >> 1);
            s1    <= wgray;
            s2    <= s1;
            if (!sh_valid && (s1 != 4'b0000)) begin
                sh_valid <= 1'b1;
                sh_val   <= s1;
            end
            before_first <= before_first && (s2 == 4'b0000);
        end
    end

    assign sync_ptr = s2;

    wire s2_nz = (s2 != 4'b0000);

    // Precedence, in the scope before the pointer has ever been seen on the
    // far side: when the synchronized pointer first becomes nonzero, that
    // very value must already have been recorded in the shadow register.
    always @(posedge clk)
        if (pv && before_first && $rose(s2_nz))
            assert (sh_valid && (sh_val == s2));
endmodule

// Tracks in-flight requests in an 8-deep shift register with a separate
// population count.  A parity/CDC error input permanently degrades the
// tracker: once `err` has been seen, the count stops being maintained
// while the shift register keeps shifting.  The occupancy relations are
// therefore only claimed before that first error.
module inflight_tracker (
    input  wire       clk,
    input  wire       step,      // idle condition: step low freezes all state
    input  wire       req,       // new request enters the pipeline this step
    input  wire       err,       // degradation event (clears the arming reg)
    output reg  [7:0] inflight,  // one bit per pipeline stage, MSB retires
    output reg  [3:0] count,     // number of set bits in `inflight`
    output reg        live       // arming register: high before any err
);

    initial inflight = 8'd0;
    initial count    = 4'd0;
    initial live     = 1'b1;

    wire retire = inflight[7];

    always @(posedge clk) begin
        if (err)
            live <= 1'b0;

        if (step) begin
            inflight <= {inflight[6:0], req};
            // the bookkeeping count is only kept faithful while undegraded
            if (live && !err)
                count <= count + (req ? 4'd1 : 4'd0) - (retire ? 4'd1 : 4'd0);
        end
    end

    // Two universality properties, both scoped to "before the first err".
    always @(posedge clk) begin
        if (live && count == 4'd0)
            assert (inflight == 8'h00);
        if (live && count == 4'd8)
            assert (inflight == 8'hFF);
    end

endmodule

module arb_lock_green (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,
    input  wire req_a,
    input  wire req_b,
    input  wire rel,
    output wire grant_a,
    output wire grant_b,
    output wire all_red
);
    // Green phase length limit: a locked winner keeps the road for at most
    // GMAX ticks, then must hand over through an all-red interval.
    localparam [3:0] GMAX = 4'd9;

    reg       lock;   // freezes the current winner until it releases
    reg       owner;  // 0 = road A, 1 = road B
    reg [3:0] gcnt;   // green-phase tick counter
    reg [1:0] ar;     // all-red interval countdown

    initial lock  = 1'b0;
    initial owner = 1'b0;
    initial gcnt  = 4'd0;
    initial ar    = 2'd0;

    wire any_req = req_a | req_b;

    always @(posedge clk) begin
        if (rst) begin
            lock  <= 1'b0;
            owner <= 1'b0;
            gcnt  <= 4'd0;
            ar    <= 2'd0;
        end else if (i_ce) begin
            if (lock) begin
                // locked winner runs its green phase
                if (rel || gcnt == GMAX) begin
                    lock <= 1'b0;
                    gcnt <= 4'd0;
                    ar   <= 2'd2;   // enter all-red handover
                end else begin
                    gcnt <= gcnt + 4'd1;
                end
            end else if (ar != 2'd0) begin
                ar <= ar - 2'd1;
            end else if (any_req) begin
                // fixed priority: road A beats road B
                lock  <= 1'b1;
                owner <= ~req_a;
            end
        end
    end

    assign grant_a = lock && (owner == 1'b0);
    assign grant_b = lock && (owner == 1'b1);
    assign all_red = !lock;

    // P: while a road holds the locked green, its phase timer never exceeds
    // GMAX = 9, even though the register could hold up to 15.
    always @(posedge clk)
        if (lock)
            assert (gcnt <= GMAX);
endmodule

// Tracks UART frames in flight through a fixed-latency 4-stage serializer.
// Each issued frame is marked in a shift register; it retires 4 cycles later.
// occ is an independently maintained occupancy counter.
module uart_inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // baud tick / pipeline advance enable
    input  wire       i_issue,   // a new frame is handed to the serializer
    output wire       o_idle,    // tracker says: nothing outstanding
    output wire       o_inflight,// serializer stages say: something outstanding
    output wire       o_retire,  // a frame leaves the last stage this tick
    output wire [2:0] o_count
);

    reg [3:0] pipe;  // one mark per occupied serializer stage
    reg [2:0] occ;   // running occupancy count

    initial pipe = 4'b0000;
    initial occ  = 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            pipe <= 4'b0000;
            occ  <= 3'd0;
        end else if (i_ce) begin
            pipe <= {pipe[2:0], i_issue};
            occ  <= occ + (i_issue ? 3'd1 : 3'd0) - (pipe[3] ? 3'd1 : 3'd0);
        end
    end

    assign o_idle     = (occ == 3'd0);
    assign o_inflight = |pipe;
    assign o_retire   = i_ce && pipe[3];
    assign o_count    = occ;

    // P: the tracker can never claim idle while a stage still holds a frame.
    always @(*)
        assert (!(o_idle && o_inflight));

endmodule

// PWM generator with a period counter, a duty register and a
// deadline-tracked duty update request.
module pwm_duty_update (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_req,     // request a new duty value
    input  wire [3:0] i_duty,
    output wire       o_pwm,
    output reg        o_applied
);
    // period counter: free running 0..15 while enabled
    reg [3:0] cnt;
    // live duty and the shadow copy waiting for the period boundary
    reg [3:0] duty;
    reg [3:0] duty_next;
    // outstanding update request and its countdown to completion
    reg       pending;
    reg [4:0] deadline;
    // sticky arm: set the first time a request is accepted, never cleared
    reg       armed;
    reg       pv;

    initial begin
        cnt       = 4'd0;
        duty      = 4'd0;
        duty_next = 4'd0;
        pending   = 1'b0;
        deadline  = 5'd0;
        armed     = 1'b0;
        pv        = 1'b0;
        o_applied = 1'b0;
    end

    wire at_end = (cnt == 4'd15);
    wire accept = i_ce && i_req && !pending;
    wire apply  = i_ce && pending && at_end;

    // output is high exactly while the counter is below the duty value
    assign o_pwm = (cnt < duty);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            cnt       <= cnt + 4'd1;
            o_applied <= apply;
            if (accept) begin
                pending   <= 1'b1;
                armed     <= 1'b1;
                duty_next <= i_duty;
                // cycles remaining, measured from the next state, until wrap
                deadline  <= at_end ? 5'd16 : (5'd15 - {1'b0, cnt});
            end else if (apply) begin
                pending   <= 1'b0;
                duty      <= duty_next;
                deadline  <= 5'd0;
            end else if (pending) begin
                deadline  <= deadline - 5'd1;
            end
        end
    end

    // Bounded response (safety): once the updater has ever been armed, the
    // countdown must never have been expired while a request was outstanding.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(pending) || $past(deadline) != 5'd0);
endmodule

module sorted_insert_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // enable: low freezes all sequencer state
    input  wire       i_arm,     // step 1: insertion request armed
    input  wire       i_scan,    // step 2: ordered scan started
    input  wire       i_commit,  // step 3: element spliced into the sorted list
    input  wire       i_abort,
    input  wire       i_open,    // Q: opens the observation window
    input  wire       i_close,   // R: closes it (may never arrive)
    output reg  [2:0] st,
    output reg  [2:0] size
);
    // binary-encoded FSM; encodings 1,3,4,7 are never entered
    localparam [2:0] S_IDLE   = 3'd0;
    localparam [2:0] S_ARMED  = 3'd2;
    localparam [2:0] S_SCAN   = 3'd5;
    localparam [2:0] S_COMMIT = 3'd6;

    reg did_arm;
    reg did_scan;
    reg win;

    initial begin
        st       = S_IDLE;
        size     = 3'd0;
        did_arm  = 1'b0;
        did_scan = 1'b0;
        win      = 1'b0;
    end

    // latched observation window: set by Q, cleared by R
    always @(posedge clk) begin
        if (rst)           win <= 1'b0;
        else if (i_close)  win <= 1'b0;
        else if (i_open)   win <= 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            st       <= S_IDLE;
            did_arm  <= 1'b0;
            did_scan <= 1'b0;
            size     <= 3'd0;
        end else if (i_ce) begin
            case (st)
                S_IDLE: begin
                    if (i_arm) begin
                        st      <= S_ARMED;
                        did_arm <= 1'b1;
                    end
                end
                S_ARMED: begin
                    if (i_abort) begin
                        st       <= S_IDLE;
                        did_arm  <= 1'b0;
                        did_scan <= 1'b0;
                    end else if (i_scan) begin
                        st       <= S_SCAN;
                        did_scan <= 1'b1;
                    end
                end
                S_SCAN: begin
                    if (i_abort) begin
                        st       <= S_IDLE;
                        did_arm  <= 1'b0;
                        did_scan <= 1'b0;
                    end else if (i_commit) begin
                        st <= S_COMMIT;
                    end
                end
                S_COMMIT: begin
                    st       <= S_IDLE;
                    did_arm  <= 1'b0;
                    did_scan <= 1'b0;
                    if (size != 3'd4) size <= size + 1'b1;
                end
                default: begin
                    st       <= S_IDLE;
                    did_arm  <= 1'b0;
                    did_scan <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence, after window-open until window-close:
    // a commit is never observed unless arm and scan already happened.
    always @(posedge clk)
        if (win && st == S_COMMIT)
            assert (did_arm && did_scan);
endmodule

module split_accumulator (
    input  wire       clk,
    input  wire       en,      // accumulate enable (idle when low)
    input  wire       bump,    // desync event: nudges one half only
    input  wire [7:0] v,       // addend
    output wire       halves_equal,
    output wire       total_odd
);
    // Accumulator split into two halves; by construction part_a + part_b == total
    reg [7:0] part_a;
    reg [7:0] part_b;
    reg [7:0] total;   // shadow of the true running sum
    reg       toggle;  // selects which half receives the next addend
    reg       pre_bump; // armed until the first bump event ever occurs

    initial part_a   = 8'd0;
    initial part_b   = 8'd0;
    initial total    = 8'd0;
    initial toggle   = 1'b0;
    initial pre_bump = 1'b1;

    assign halves_equal = (part_a == part_b);
    assign total_odd    = total[0];

    always @(posedge clk) begin
        if (bump) begin
            // breaks the split/total relation on purpose, and disarms the scope
            part_a   <= part_a + 8'd1;
            pre_bump <= 1'b0;
        end else if (en) begin
            if (!toggle)
                part_a <= part_a + v;
            else
                part_b <= part_b + v;
            total  <= total + v;
            toggle <= ~toggle;
        end
    end

    // Absence, in the scope "before the first bump":
    // the halves-balanced flag and the odd-total flag are never both true.
    always @(*)
        assert (!pre_bump || !(halves_equal && total_odd));
endmodule

// saturating event counter with full/empty status flags
module sat_counter_flags (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    output wire o_full,
    output wire o_empty
);
    parameter [3:0] MAX = 4'd10;

    reg [3:0] cnt;
    reg       at_max;   // "full"  status flag
    reg       at_min;   // "empty" status flag
    reg       pv;       // past-valid

    initial cnt    = 4'd0;
    initial at_max = 1'b0;
    initial at_min = 1'b1;
    initial pv     = 1'b0;

    // saturating next value: clamps at MAX, well below 4'd15
    wire [3:0] nxt = (cnt >= MAX) ? MAX : (cnt + 4'd1);

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_rst) begin
            cnt    <= 4'd0;
            at_max <= 1'b0;
            at_min <= 1'b1;
        end else if (i_ce) begin
            cnt    <= nxt;
            at_max <= (nxt == MAX);
            at_min <= (nxt == 4'd0);
        end
    end

    assign o_full  = at_max;
    assign o_empty = at_min;

    // P: the counter holding still and a status flag moving are never
    //    true at the same time
    always @(posedge clk)
        if (pv && $stable(cnt))
            assert ($stable(at_max) && $stable(at_min));

endmodule

module credit_pool (
    input  wire clk,
    input  wire cfg,      // one-shot: install the configured credit total
    input  wire send,     // producer spends a credit
    input  wire ret,      // consumer returns a credit
    output wire ok_to_send,
    output wire [3:0] o_credits,
    output wire [3:0] o_outstanding
);
    parameter [3:0] TOTAL = 4'd8;

    // sticky arm register: set the first time the pool is configured, never cleared
    reg       armed = 1'b0;
    // credits held by the producer
    reg [3:0] credits = 4'd0;
    // credits spent and not yet returned
    reg [3:0] outstanding = 4'd0;

    wire do_cfg  = cfg && !armed;
    wire do_send = armed && send && (credits != 4'd0);
    wire do_ret  = armed && ret  && (outstanding != 4'd0);

    always @(posedge clk) begin
        if (do_cfg) begin
            armed       <= 1'b1;
            credits     <= TOTAL;
            outstanding <= 4'd0;
        end else begin
            credits     <= credits     - {3'b000, do_send} + {3'b000, do_ret};
            outstanding <= outstanding + {3'b000, do_send} - {3'b000, do_ret};
        end
    end

    assign ok_to_send    = armed && (credits != 4'd0);
    assign o_credits     = credits;
    assign o_outstanding = outstanding;

    // P: once the pool has been armed, an idle link (nothing outstanding)
    // means every credit is back in the producer's hands.
    always @(posedge clk)
        if (armed && (outstanding == 4'd0))
            assert (credits == TOTAL);
endmodule

module fetch_handshake (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,      // global enable: low => design idles
    input  wire       start,     // new cell fetch requested
    input  wire [7:0] cell_in,
    output reg        req,
    output reg        ack,
    output reg        busy,
    output reg [7:0]  cell_q,
    output reg [3:0]  rows_done
);

    // four-phase handshake sequencer
    //   0 : idle          req=0 ack=0 busy=0
    //   1 : req asserted  req=1 ack=0 busy=1
    //   2 : ack asserted  req=1 ack=1 busy=1
    //   3 : req dropped   req=0 ack=1 busy=1
    reg [1:0] phase;

    initial begin
        phase     = 2'd0;
        req       = 1'b0;
        ack       = 1'b0;
        busy      = 1'b0;
        cell_q    = 8'd0;
        rows_done = 4'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase     <= 2'd0;
            req       <= 1'b0;
            ack       <= 1'b0;
            busy      <= 1'b0;
            cell_q    <= 8'd0;
            rows_done <= 4'd0;
        end else if (step) begin
            case (phase)
                2'd0: begin
                    // requester raises req and marks itself busy
                    if (start) begin
                        phase <= 2'd1;
                        req   <= 1'b1;
                        busy  <= 1'b1;
                    end
                end
                2'd1: begin
                    // responder acknowledges and presents the cell
                    phase  <= 2'd2;
                    ack    <= 1'b1;
                    cell_q <= cell_in;
                end
                2'd2: begin
                    // req may only drop after ack has risen
                    phase <= 2'd3;
                    req   <= 1'b0;
                end
                2'd3: begin
                    // responder retires the transaction; it releases ack
                    // only once it observes req deasserted
                    phase     <= 2'd0;
                    busy      <= 1'b0;
                    rows_done <= rows_done + 4'd1;
                    if (!req) ack <= 1'b0;
                end
            endcase
        end
    end

    // P: the busy flag covers every live handshake wire, in every state
    always @(posedge clk)
        if (req) assert (busy);

    always @(posedge clk)
        if (ack) assert (busy);

endmodule

module elastic_skid_buffer (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_push,
    input  wire       i_pop,
    input  wire [7:0] i_data,
    output wire [7:0] o_data,
    output wire       o_valid,
    output wire       o_full
);
    // two-entry elastic buffer with head/tail flags and a redundant occupancy count
    reg [7:0] mem0;
    reg [7:0] mem1;
    reg       v0;
    reg       v1;
    reg       head;
    reg       tail;
    reg [2:0] count;

    initial begin
        mem0  = 8'd0;
        mem1  = 8'd0;
        v0    = 1'b0;
        v1    = 1'b0;
        head  = 1'b0;
        tail  = 1'b0;
        count = 3'd0;
    end

    wire full  = v0 && v1;
    wire empty = !v0 && !v1;

    wire do_push = i_push && !full;
    wire do_pop  = i_pop  && !empty;

    assign o_full  = full;
    assign o_valid = !empty;
    assign o_data  = head ? mem1 : mem0;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            head  <= 1'b0;
            tail  <= 1'b0;
            count <= 3'd0;
        end else begin
            if (do_push) begin
                if (tail) begin
                    mem1 <= i_data;
                    v1   <= 1'b1;
                end else begin
                    mem0 <= i_data;
                    v0   <= 1'b1;
                end
                tail <= ~tail;
            end

            if (do_pop) begin
                if (head)
                    v1 <= 1'b0;
                else
                    v0 <= 1'b0;
                head <= ~head;
            end

            if (do_push && !do_pop)
                count <= count + 3'd1;
            else if (do_pop && !do_push)
                count <= count - 3'd1;
        end
    end

    // P: occupancy never exceeds the two-entry depth, although the counter is 3 bits wide
    always @(posedge clk)
        assert (count <= 3'd2);
endmodule

// Token bucket rate limiter for board-render job grants.
// Tokens are minted by a periodic timer tick, capped at a burst size,
// and drained one per granted request.
module token_bucket (
    input  wire clk,
    input  wire i_ce,      // global enable / idle control
    input  wire req,       // job requests a render slot
    output wire o_grant
);
    localparam [3:0] CAP = 4'd8;   // burst size

    reg [3:0] tokens      = 4'd0;  // current bucket level
    reg [1:0] tickcnt     = 2'd0;  // refill timer
    reg       refill_seen = 1'b0;  // shadow: a token was minted at some point
    reg       did_grant   = 1'b0;  // shadow: a grant was issued last cycle
    reg       armed       = 1'b0;  // sticky scope: a request has been observed

    wire tick      = (tickcnt == 2'd3);
    wire do_refill = i_ce && tick && (tokens < CAP);

    assign o_grant = i_ce && req && (tokens != 4'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            tickcnt <= tickcnt + 2'd1;

            case ({do_refill, o_grant})
                2'b10:   tokens <= tokens + 4'd1;
                2'b01:   tokens <= tokens - 4'd1;
                default: tokens <= tokens;
            endcase

            if (do_refill) refill_seen <= 1'b1;

            did_grant <= o_grant;

            if (req) armed <= 1'b1;
        end
    end

    // Precedence, in the "after first request" scope:
    // a grant can only have been issued if a refill happened earlier.
    always @(posedge clk)
        if (armed && did_grant)
            assert (refill_seen);

endmodule

module frame_fifo (
    input  wire       clk,
    input  wire       ce,      // global enable / idle when low
    input  wire       push,    // request: enqueue a frame command
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       full,
    output wire       empty,
    output wire       expired
);
    // ---- FIFO state: two pointers plus an occupancy counter -------------
    reg [2:0] wptr  = 3'd0;
    reg [2:0] rptr  = 3'd0;
    reg [2:0] count = 3'd0;   // occupancy, capacity 7 so diff is unambiguous

    // ---- bounded-response countdown for the drain engine ----------------
    reg [3:0] timer = 4'd0;

    // ---- sticky arm: set the first time a request is accepted -----------
    reg       armed = 1'b0;

    reg [7:0] mem [0:7];
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) mem[i] = 8'd0;
    end

    assign full    = (count == 3'd7);
    assign empty   = (count == 3'd0);
    assign dout    = mem[rptr];
    assign expired = (timer == 4'd0);

    // write port has priority; the drain engine pops on any idle-of-push cycle
    wire       wr = push && !full;
    wire       rd = !push && !empty;

    // next write pointer and the resulting pointer difference
    wire [2:0] nwptr = wptr + {2'b00, wr};
    wire [2:0] ndiff = nwptr - rptr;

    always @(posedge clk) begin
        if (ce) begin
            if (wr) begin
                mem[wptr] <= din;
                wptr      <= wptr + 3'd1;
                armed     <= 1'b1;
            end
            if (rd)
                rptr <= rptr + 3'd1;

            count <= count + {2'b00, wr} - {2'b00, rd};

            // a new request reloads the deadline from the pointer distance
            if (push)
                timer <= {1'b0, ndiff} + 4'd2;
            else if (timer != 4'd0)
                timer <= timer - 4'd1;
        end
    end

    // P: after the engine has been armed, the countdown must never be
    //    expired while work is still outstanding in the queue.
    always @(posedge clk)
        assert (!armed || count == 3'd0 || timer != 4'd0);
endmodule

module histo_hotbins (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [1:0] sel,
    output wire       full,
    output wire [2:0] o_hot
);
    // Sample histogram: four bins, one increment per accepted sample.
    // The bins always sum to the total-samples register, and the total
    // saturates at MAXTOT, so at most two bins can ever reach THRESH.
    localparam [3:0] MAXTOT = 4'd9;
    localparam [3:0] THRESH = 4'd4;

    reg [3:0] bin0, bin1, bin2, bin3;
    reg [3:0] total;
    reg [2:0] hot;    // number of bins that have reached THRESH
    reg       armed;  // sticky: set the first time hot reaches 2
    reg       pv;     // past-valid

    initial begin
        bin0  = 4'd0;
        bin1  = 4'd0;
        bin2  = 4'd0;
        bin3  = 4'd0;
        total = 4'd0;
        hot   = 3'd0;
        armed = 1'b0;
        pv    = 1'b0;
    end

    wire accept = ce && !rst && (total < MAXTOT);

    wire [3:0] cur = (sel == 2'd0) ? bin0 :
                     (sel == 2'd1) ? bin1 :
                     (sel == 2'd2) ? bin2 : bin3;

    wire cross = accept && (cur == (THRESH - 4'd1));

    assign full  = (total == MAXTOT);
    assign o_hot = hot;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 4'd0;
            hot   <= 3'd0;
            armed <= 1'b0;
        end else begin
            if (accept) begin
                total <= total + 4'd1;
                case (sel)
                    2'd0:    bin0 <= bin0 + 4'd1;
                    2'd1:    bin1 <= bin1 + 4'd1;
                    2'd2:    bin2 <= bin2 + 4'd1;
                    default: bin3 <= bin3 + 4'd1;
                endcase
                if (cross)
                    hot <= hot + 3'd1;
            end
            if (hot >= 3'd2)
                armed <= 1'b1;
        end
    end

    // P: once the design has been armed (hot first reached its true
    // maximum of 2), the hot-bin occupancy can never change again --
    // i.e. it never exceeds 2, well below what the 3-bit register allows.
    always @(posedge clk)
        if (pv && armed)
            assert ($stable(hot));
endmodule

module lfsr_lockup_watch (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire       o_bit,
    output wire       o_strobe,
    output wire [3:0] o_dead
);
    // Fibonacci LFSR, x^8 + x^6 + x^5 + x^4 + 1 (maximal length, 255 states).
    // Seeded nonzero, so the all-zeros lockup state is never entered.
    reg [7:0] lfsr;
    // Watchdog: counts consecutive enabled cycles spent in the lockup word.
    reg [3:0] zcnt;
    // Pipelined "low tap field is empty" strobe.
    reg       strobe;
    reg       pv;

    initial lfsr   = 8'h01;
    initial zcnt   = 4'd0;
    initial strobe = 1'b0;
    initial pv     = 1'b0;

    wire fb   = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];
    wire dead = (lfsr == 8'h00);

    always @(posedge i_clk) begin
        if (i_rst) begin
            lfsr   <= 8'h01;
            zcnt   <= 4'd0;
            strobe <= 1'b0;
        end else if (i_ce) begin
            lfsr   <= { lfsr[6:0], fb };
            zcnt   <= dead ? ((zcnt == 4'hf) ? 4'hf : (zcnt + 4'd1)) : 4'd0;
            strobe <= (lfsr[2:0] == 3'b000);
        end
    end

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_bit    = lfsr[7];
    assign o_strobe = strobe;
    assign o_dead   = zcnt;

    // P: whenever the strobe rises, the lockup watchdog must read zero.
    always @(posedge i_clk)
        if (pv && $rose(strobe))
            assert (zcnt == 4'd0);
endmodule

module strsearch_match_queue (
    input  wire       clk,
    input  wire       ce,        // global enable / idle when low
    input  wire       start,     // opens the search window (Q)
    input  wire       finish,    // closes the search window (R)
    input  wire       load,      // report a fresh batch of character matches
    input  wire [7:0] load_mask, // positions in the string that matched
    input  wire       pop,       // consume the currently encoded position
    output reg        busy,      // window register
    output reg        idx_valid, // registered valid flag of the priority encoder
    output reg  [2:0] idx        // encoded position, meaningful only while valid
);

    // pending match positions still to be emitted
    reg [7:0] pend;
    // shadow register: every position ever loaded during the current window
    reg [7:0] loaded;

    initial busy      = 1'b0;
    initial idx_valid = 1'b0;
    initial idx       = 3'd0;
    initial pend      = 8'b0;
    initial loaded    = 8'b0;

    // combinational priority encoder (lowest string position wins)
    function [2:0] lowest_set;
        input [7:0] m;
        begin
            if      (m[0]) lowest_set = 3'd0;
            else if (m[1]) lowest_set = 3'd1;
            else if (m[2]) lowest_set = 3'd2;
            else if (m[3]) lowest_set = 3'd3;
            else if (m[4]) lowest_set = 3'd4;
            else if (m[5]) lowest_set = 3'd5;
            else if (m[6]) lowest_set = 3'd6;
            else           lowest_set = 3'd7;
        end
    endfunction

    reg [7:0] nxt_pend;
    always @(*) begin
        nxt_pend = pend;
        if (pop && idx_valid)
            nxt_pend = nxt_pend & ~(8'b1 << idx);
        if (load)
            nxt_pend = nxt_pend | load_mask;
    end

    always @(posedge clk) begin
        if (ce) begin
            if (start) begin
                busy      <= 1'b1;
                pend      <= 8'b0;
                loaded    <= 8'b0;
                idx       <= 3'd0;
                idx_valid <= 1'b0;
            end else if (finish) begin
                busy      <= 1'b0;
                pend      <= 8'b0;
                loaded    <= 8'b0;
                idx       <= 3'd0;
                idx_valid <= 1'b0;
            end else if (busy) begin
                pend      <= nxt_pend;
                if (load)
                    loaded <= loaded | load_mask;
                idx_valid <= |nxt_pend;
                idx       <= lowest_set(nxt_pend);
            end
        end
    end

    // Precedence, scoped between start and finish: a position emitted by the
    // encoder must have been reported as a match earlier in this window.
    always @(posedge clk)
        if (busy && idx_valid)
            assert (loaded[idx]);

endmodule

module split_total_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output reg  [5:0] up,
    output reg  [5:0] down,
    output reg  [5:0] maxv
);
    // The workload of TOTAL units is split between a rising share (up) and a
    // remaining share (down); one enable moves exactly one unit across, so the
    // two counters always sum to TOTAL.  maxv tracks the larger of the shares.
    localparam [5:0] TOTAL = 6'd20;

    initial begin
        up   = 6'd0;
        down = TOTAL;
        maxv = TOTAL;
    end

    wire do_step = step && (down != 6'd0);

    wire [5:0] nxt_up   = up   + 6'd1;
    wire [5:0] nxt_down = down - 6'd1;
    wire [5:0] nxt_max  = (nxt_up > nxt_down) ? nxt_up : nxt_down;

    always @(posedge clk) begin
        if (rst) begin
            up   <= 6'd0;
            down <= TOTAL;
            maxv <= TOTAL;
        end else if (do_step) begin
            up   <= nxt_up;
            down <= nxt_down;
            maxv <= nxt_max;
        end
    end

    // P: the larger share can never drop below half of the total.
    always @(*)
        assert (maxv >= 6'd10);
endmodule

module irq_priority_grant (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] req,
    output reg  [7:0] pending,
    output reg  [7:0] ever_req,
    output reg  [2:0] grant_idx,
    output reg        grant_valid
);

    // Requests currently outstanding plus whatever arrives this cycle
    wire [7:0] sel = pending | req;

    // Combinational priority encoder: lowest index wins
    reg [2:0] enc_idx;
    reg       enc_valid;
    integer   i;
    always @(*) begin
        enc_idx   = 3'd0;
        enc_valid = 1'b0;
        for (i = 7; i >= 0; i = i - 1) begin
            if (sel[i]) begin
                enc_idx   = i;
                enc_valid = 1'b1;
            end
        end
    end

    initial pending     = 8'd0;
    initial ever_req    = 8'd0;  // shadow: every line that has ever asserted
    initial grant_idx   = 3'd0;
    initial grant_valid = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            pending     <= 8'd0;
            ever_req    <= 8'd0;
            grant_idx   <= 3'd0;
            grant_valid <= 1'b0;
        end else if (ce) begin
            ever_req    <= ever_req | req;
            grant_valid <= enc_valid;
            grant_idx   <= enc_idx;
            if (enc_valid)
                pending <= sel & ~(8'd1 << enc_idx);
            else
                pending <= 8'd0;
        end
    end

    // The encoded index is only meaningful while grant_valid is set:
    // whenever a grant is presented, that line must have requested earlier.
    always @(*)
        assert (!grant_valid || ever_req[grant_idx]);

endmodule

module txn_scoreboard (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire arm_req,
    input  wire start_req,
    input  wire fin_req,
    output wire o_retire,
    output wire [2:0] o_outstanding
);
    // three-step transaction chain: arm -> start -> finish
    // scoreboard counters (monotone, never wrap: arming stops at 4'hf)
    reg [3:0] n_armed;
    reg [3:0] n_started;
    reg [3:0] n_finished;

    // credit registers: armed-not-started, started-not-finished, issued-not-retired
    reg [2:0] cred_start;
    reg [2:0] cred_fin;
    reg [2:0] outst;

    reg retire_pulse;

    initial n_armed     = 4'd0;
    initial n_started   = 4'd0;
    initial n_finished  = 4'd0;
    initial cred_start  = 3'd0;
    initial cred_fin    = 3'd0;
    initial outst       = 3'd0;
    initial retire_pulse = 1'b0;

    localparam [2:0] WINDOW = 3'd4;

    // a new transaction may be armed only inside the outstanding window
    wire arm_fire   = ce && arm_req   && (outst < WINDOW) && (n_armed != 4'hf);
    // a transaction may start only if one has been armed and not yet started
    wire start_fire = ce && start_req && (cred_start != 3'd0);
    // a transaction may finish only if one has been started and not yet finished
    wire fin_fire   = ce && fin_req   && (cred_fin   != 3'd0);

    always @(posedge clk) begin
        if (rst) begin
            n_armed      <= 4'd0;
            n_started    <= 4'd0;
            n_finished   <= 4'd0;
            cred_start   <= 3'd0;
            cred_fin     <= 3'd0;
            outst        <= 3'd0;
            retire_pulse <= 1'b0;
        end else begin
            n_armed    <= n_armed    + (arm_fire   ? 4'd1 : 4'd0);
            n_started  <= n_started  + (start_fire ? 4'd1 : 4'd0);
            n_finished <= n_finished + (fin_fire   ? 4'd1 : 4'd0);

            cred_start <= cred_start + (arm_fire   ? 3'd1 : 3'd0)
                                     - (start_fire ? 3'd1 : 3'd0);
            cred_fin   <= cred_fin   + (start_fire ? 3'd1 : 3'd0)
                                     - (fin_fire   ? 3'd1 : 3'd0);
            outst      <= outst      + (arm_fire   ? 3'd1 : 3'd0)
                                     - (fin_fire   ? 3'd1 : 3'd0);

            retire_pulse <= fin_fire;
        end
    end

    assign o_retire      = retire_pulse;
    assign o_outstanding = outst;

    // P: a retirement can only be observed if the chain arm -> start already happened
    always @(posedge clk)
        if (retire_pulse)
            assert ((n_armed != 4'd0) && (n_started != 4'd0));
endmodule

// Gray-coded write pointer crossing into a second domain through a
// two-flop synchronizer, with a shadow register recording the previously
// observed synchronized sample.
module gray_ptr_cdc (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle condition: low freezes all state
    input  wire       push,
    output wire [3:0] o_gray,
    output wire [3:0] o_gray_shadow
);

    // source-domain binary pointer and its gray encoding
    reg [3:0] bin;
    reg [3:0] wgray;

    // two-flop synchronizer
    reg [3:0] s1;
    reg [3:0] s2;

    // shadow: the sample observed one enabled cycle earlier
    reg [3:0] s2_prev;

    initial begin
        bin     = 4'd0;
        wgray   = 4'd0;
        s1      = 4'd0;
        s2      = 4'd0;
        s2_prev = 4'd0;
    end

    wire [3:0] nbin = bin + (push ? 4'd1 : 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            bin     <= 4'd0;
            wgray   <= 4'd0;
            s1      <= 4'd0;
            s2      <= 4'd0;
            s2_prev <= 4'd0;
        end else if (i_ce) begin
            bin     <= nbin;
            wgray   <= nbin ^ (nbin >> 1);
            s1      <= wgray;
            s2      <= s1;
            s2_prev <= s2;
        end
    end

    assign o_gray        = s2;
    assign o_gray_shadow = s2_prev;

    // Hamming distance between the present sample and the shadow sample
    wire [3:0] d_a = s2 ^ s2_prev;
    wire [2:0] n_a = {2'b0, d_a[0]} + {2'b0, d_a[1]} +
                     {2'b0, d_a[2]} + {2'b0, d_a[3]};

    // Hamming distance between the first-flop sample and the shadow sample
    wire [3:0] d_b = s1 ^ s2_prev;
    wire [2:0] n_b = {2'b0, d_b[0]} + {2'b0, d_b[1]} +
                     {2'b0, d_b[2]} + {2'b0, d_b[3]};

    // P1: whatever value is observed now must have been preceded by a value
    //     at most one bit away.
    always @(posedge clk)
        assert (n_a <= 3'd1);

    // P2: the value about to be observed is at most two bits away from the
    //     value observed two enabled cycles ago.
    always @(posedge clk)
        assert (n_b <= 3'd2);

endmodule

module dma_burst_shadow (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // global enable / idle condition
    input  wire       start,
    input  wire [3:0] len,
    output wire       beat_stb,
    output wire       busy_o,
    output wire [3:0] done_o
);
    // burst engine state
    reg        busy       = 1'b0;  // up exactly while beats remain
    reg [3:0]  beats      = 4'd0;  // beats remaining in current burst
    reg [3:0]  beats_done = 4'd0;  // beats already transferred
    reg [3:0]  shadow_len = 4'd0;  // shadow of the length programmed at start

    assign beat_stb = ce && busy;
    assign busy_o   = busy;
    assign done_o   = beats_done;

    always @(posedge clk) begin
        if (rst) begin
            busy       <= 1'b0;
            beats      <= 4'd0;
            beats_done <= 4'd0;
            shadow_len <= 4'd0;
        end else if (ce) begin
            if (busy) begin
                beats      <= beats - 4'd1;
                beats_done <= beats_done + 4'd1;
                busy       <= (beats != 4'd1);
            end else if (start && (len != 4'd0)) begin
                busy       <= 1'b1;
                beats      <= len;
                shadow_len <= len;   // record the earlier programming event
                beats_done <= 4'd0;
            end
        end
    end

    // P (two assertions, both about the shadow of the earlier start):
    // while a beat can still be observed, strictly fewer beats have been done
    // than were programmed earlier; and once idle, exactly the programmed
    // number of beats has been done.
    always @(posedge clk)
        assert (!busy || (beats_done < shadow_len));

    always @(posedge clk)
        assert (busy || (beats_done == shadow_len));
endmodule

module grant_fsm (
    input  wire clk,
    input  wire rst,
    input  wire en,
    input  wire req_a,
    input  wire req_b,
    output wire grant_a,
    output wire grant_b
);
    // Binary-encoded arbiter FSM.  Only five of the eight 3-bit encodings
    // are ever entered; 3'd3, 3'd5 and 3'd7 are unreachable by construction.
    localparam S_IDLE  = 3'd0;  // 000
    localparam S_A     = 3'd1;  // 001  -> grants A next cycle
    localparam S_ACOOL = 3'd2;  // 010
    localparam S_B0    = 3'd4;  // 100  -> grants B next cycle
    localparam S_B1    = 3'd6;  // 110  -> grants B next cycle

    reg [2:0] st = S_IDLE;
    reg [2:0] nxt;

    // Registered (pipelined) grant outputs: bit 0 of the state decodes the
    // A grant, bit 2 decodes the B grant.
    reg ga = 1'b0;
    reg gb = 1'b0;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(*) begin
        case (st)
            S_IDLE:  nxt = req_a ? S_A : (req_b ? S_B0 : S_IDLE);
            S_A:     nxt = S_ACOOL;
            S_ACOOL: nxt = S_IDLE;
            S_B0:    nxt = S_B1;
            S_B1:    nxt = S_IDLE;
            default: nxt = S_IDLE;
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            st <= S_IDLE;
            ga <= 1'b0;
            gb <= 1'b0;
        end else if (en) begin
            st <= nxt;
            ga <= st[0];
            gb <= st[2];
        end
    end

    assign grant_a = ga;
    assign grant_b = gb;

    // P: whenever the A grant rises, the B grant must not be asserted.
    always @(posedge clk)
        if (pv && $rose(ga))
            assert (!gb);
endmodule

module sat_watermark_flags (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_inc,
    input  wire       i_clear,
    output wire [3:0] o_count,
    output wire       o_full,
    output wire       o_empty
);
    // saturating up-counter: clamps at MAX = 10, register admits up to 15
    localparam [3:0] MAX = 4'd10;

    reg [3:0] cnt;
    reg       full_f;
    reg       empty_f;

    initial cnt     = 4'd0;
    initial full_f  = 1'b0;
    initial empty_f = 1'b1;

    always @(posedge i_clk) begin
        if (i_rst) begin
            cnt     <= 4'd0;
            full_f  <= 1'b0;
            empty_f <= 1'b1;
        end else if (i_ce) begin
            if (i_clear) begin
                cnt     <= 4'd0;
                full_f  <= 1'b0;
                empty_f <= 1'b1;
            end else if (i_inc && (cnt != MAX)) begin
                cnt <= cnt + 4'd1;
                // watermark flags are maintained incrementally, only on the
                // edges where the count actually crosses a boundary
                if (cnt == 4'd0)
                    empty_f <= 1'b0;
                if (cnt == (MAX - 4'd1))
                    full_f <= 1'b1;
            end
        end
    end

    assign o_count = cnt;
    assign o_full  = full_f;
    assign o_empty = empty_f;

    // P: the saturation flag and the zero flag are never asserted together
    always @(posedge i_clk)
        if (!i_rst)
            assert (!(o_full && o_empty));
endmodule

// In-flight request tracker: an 8-deep shift register of outstanding
// requests plus a separately maintained count of the set bits, with a
// three-step chain monitor (arm -> start -> finish).
module inflight_chain_monitor (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire       issue,   // launch a new request into the pipe
    output wire [1:0] phase,
    output wire       busy
);
    // ---- structural state -------------------------------------------------
    reg [7:0] pipe      = 8'd0;   // one bit per in-flight request slot
    reg [3:0] count     = 4'd0;   // separately maintained popcount of pipe

    // ---- three-step chain monitor ----------------------------------------
    reg       arm_seen  = 1'b0;   // step 1: a request was issued
    reg       start_seen= 1'b0;   // step 2: a request was actually in flight
    reg       fin_seen  = 1'b0;   // step 3: a request retired out of stage 7

    wire ins    = issue;
    wire retire = pipe[7];

    always @(posedge clk) begin
        if (rst) begin
            pipe       <= 8'd0;
            count      <= 4'd0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            fin_seen   <= 1'b0;
        end else if (ce) begin
            pipe  <= {pipe[6:0], ins};
            count <= count + {3'd0, ins} - {3'd0, retire};

            if (ins)            arm_seen   <= 1'b1;
            if (count != 4'd0)  start_seen <= 1'b1;
            if (retire)         fin_seen   <= 1'b1;
        end
    end

    assign phase = fin_seen   ? 2'd3 :
                   start_seen ? 2'd2 :
                   arm_seen   ? 2'd1 : 2'd0;
    assign busy  = (count != 4'd0);

    // ---- property: chain precedence, global scope -------------------------
    // A finish can never be observed unless a start was observed, which can
    // never be observed unless an arm was observed.
    always @(posedge clk)
        assert (!fin_seen || (start_seen && arm_seen));

endmodule

// Ping-pong (double) buffer fill engine with a completion deadline counter.
// The writer owns half `sel`, the reader owns half `rsel`; they are never the
// same half.  Each accepted fill request is guaranteed to finish within DEPTH
// enabled cycles by the countdown register `ttl`; `err_r` latches the (never
// occurring) event "countdown expired while the request is still outstanding".
module pingpong_deadline (
    input  wire       clk,
    input  wire       ce,      // global enable: low => all state frozen
    input  wire       start,   // request a new half-buffer fill
    input  wire [7:0] wdata,
    input  wire       rd,      // reader consumes a word from the other half
    output wire [7:0] rdata,
    output wire       err
);
    localparam [3:0] DEPTH = 4'd8;

    reg        sel   = 1'b0;   // half currently owned by the writer
    reg        rsel  = 1'b1;   // half currently owned by the reader
    reg        busy  = 1'b0;   // fill request outstanding
    reg  [3:0] wcnt  = 4'd0;   // words written into the writer half
    reg  [3:0] ttl   = 4'd0;   // countdown to the completion deadline
    reg  [3:0] rcnt  = 4'd0;   // reader index into its half
    reg        rvld  = 1'b0;   // reader half holds a complete frame
    reg        err_r = 1'b0;   // deadline expired while still outstanding

    reg  [7:0] mem0 [0:7];
    reg  [7:0] mem1 [0:7];

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) begin
            mem0[i] = 8'd0;
            mem1[i] = 8'd0;
        end
    end

    wire accept  = ce && start && !busy;
    wire wstep   = ce && busy;
    wire wlast   = wstep && (wcnt == 4'd7);
    wire expired = wstep && (ttl == 4'd0);

    assign rdata = rsel ? mem1[rcnt[2:0]] : mem0[rcnt[2:0]];
    assign err   = err_r;

    // data path: writer only ever touches half `sel`
    always @(posedge clk) begin
        if (wstep) begin
            if (sel) mem1[wcnt[2:0]] <= wdata;
            else     mem0[wcnt[2:0]] <= wdata;
        end
    end

    // control path
    always @(posedge clk) begin
        if (expired)
            err_r <= 1'b1;

        if (accept) begin
            busy <= 1'b1;
            wcnt <= 4'd0;
            ttl  <= DEPTH;
        end else if (wlast) begin
            busy <= 1'b0;
            wcnt <= 4'd0;
            ttl  <= 4'd0;
            sel  <= ~sel;      // writer swaps to the other half
            rsel <= sel;       // reader takes over the half just filled
            rcnt <= 4'd0;
            rvld <= 1'b1;
        end else if (wstep) begin
            wcnt <= wcnt + 4'd1;
            ttl  <= ttl  - 4'd1;
        end

        if (ce && rd && rvld && !wlast) begin
            if (rcnt == 4'd7) begin
                rcnt <= 4'd0;
                rvld <= 1'b0;
            end else begin
                rcnt <= rcnt + 4'd1;
            end
        end
    end

    // past-valid guard
    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // P: bounded response, safety form -- while the request stayed outstanding
    // (busy did not change), the deadline-expiry flag must not have changed.
    always @(posedge clk)
        if (pv && $stable(busy))
            assert ($stable(err_r));
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       issue,
    output wire       done,
    output wire [2:0] occupancy
);
    // fixed-latency (4 stage) in-flight shift register
    reg [3:0] pipe       = 4'b0000;
    // occupancy counter: issue increments, stage-3 drain decrements
    reg [2:0] occ        = 3'd0;
    // shadow register: records that an issue has already happened
    reg       seen_issue = 1'b0;
    reg       pv         = 1'b0;

    assign done      = ce && pipe[3];
    assign occupancy = occ;

    always @(posedge clk) begin
        if (rst) begin
            pipe       <= 4'b0000;
            occ        <= 3'd0;
            seen_issue <= 1'b0;
        end else if (ce) begin
            pipe <= {pipe[2:0], issue};
            occ  <= occ + (issue ? 3'd1 : 3'd0) - (pipe[3] ? 3'd1 : 3'd0);
            if (issue)
                seen_issue <= 1'b1;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    // Precedence: a retire observed last cycle must have been preceded by an issue
    always @(posedge clk)
        if (pv)
            assert (!($past(ce) && $past(pipe[3])) || $past(seen_issue));
endmodule

module wdog_bounded (
    input  wire clk,
    input  wire rst,     // synchronous reset
    input  wire ce,      // timebase enable: when low the whole watchdog idles
    input  wire kick,    // software pets the dog
    output wire o_bark,  // timeout reached, reset request to the host
    output wire o_armed
);
    // The watchdog counts timebase ticks since the last kick.  When it reaches
    // LIMIT it latches the bark flag and freezes; only a kick (or reset)
    // restarts it.  Note the freeze is decided by the latched flag, not by a
    // fresh comparison against LIMIT.
    parameter [4:0] LIMIT = 5'd20;

    reg [4:0] wdt;
    reg       expired;
    reg       armed;   // sticky: set the first time the dog is ever kicked

    initial wdt     = 5'd0;
    initial expired = 1'b0;
    initial armed   = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            wdt     <= 5'd0;
            expired <= 1'b0;
            armed   <= 1'b0;
        end else if (ce) begin
            if (kick) begin
                wdt     <= 5'd0;
                expired <= 1'b0;
                armed   <= 1'b1;
            end else if (!expired) begin
                wdt <= wdt + 5'd1;
                if ((wdt + 5'd1) == LIMIT)
                    expired <= 1'b1;
            end
        end
    end

    assign o_bark  = expired;
    assign o_armed = armed;

    // Property: once the watchdog has been armed by a first kick, the elapsed
    // tick count never exceeds the programmed timeout, even though the counter
    // is five bits wide and could hold up to 31.
    always @(*)
        if (armed)
            assert (wdt <= LIMIT);

endmodule

// Gray-coded pointer crossing a domain boundary through a two-flop
// synchronizer, with a shadow register holding the previously observed
// synchronized sample.
module gray_ptr_cdc (
    input  wire       clk,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire       inc,     // advance the write pointer
    output wire [3:0] o_sync_gray,
    output wire [3:0] o_shadow_gray
);
    // producer side
    reg [3:0] bin;
    reg [3:0] gptr;

    // two-flop synchronizer
    reg [3:0] s1;
    reg [3:0] s2;

    // shadow register: the sample observed one enabled cycle earlier
    reg [3:0] prev_s2;

    // binary shadows of the pipeline stages (book-keeping only)
    reg [3:0] bs1, bs2, bs3;

    initial begin
        bin     = 4'b0000;
        gptr    = 4'b0000;
        s1      = 4'b0000;
        s2      = 4'b0000;
        prev_s2 = 4'b0000;
        bs1     = 4'b0000;
        bs2     = 4'b0000;
        bs3     = 4'b0000;
    end

    wire [3:0] bin_next = bin + (inc ? 4'd1 : 4'd0);

    always @(posedge clk) begin
        if (ce) begin
            bin     <= bin_next;
            gptr    <= bin_next ^ (bin_next >> 1);

            s1      <= gptr;
            s2      <= s1;
            prev_s2 <= s2;

            bs1     <= bin;
            bs2     <= bs1;
            bs3     <= bs2;
        end
    end

    assign o_sync_gray   = s2;
    assign o_shadow_gray = prev_s2;

    // difference vectors
    wire [3:0] d_shadow = s2 ^ prev_s2;
    wire [3:0] d_stage  = s1 ^ s2;

    // Precedence: whatever the synchronizer shows now must have been preceded
    // by a value at most one bit away, at both observation points.
    always @(posedge clk) begin
        assert ((d_shadow & (d_shadow - 4'd1)) == 4'd0);
        assert ((d_stage  & (d_stage  - 4'd1)) == 4'd0);
    end
endmodule

module parity_reg_slice (
    input  wire       clk,
    input  wire       rst,
    input  wire       in_valid,
    input  wire [7:0] in_data,
    input  wire       out_ready,
    output wire       in_ready,
    output wire       out_valid,
    output wire [7:0] out_data
);
    // ---- register slice protected by a parity bit ----
    reg [7:0] buf_data;
    reg       buf_par;
    reg       buf_valid;

    // sticky arm: set the first time a beat is ever accepted
    reg       armed;
    // sticky error: set if a departing word's stored parity disagrees
    reg       err_sticky;

    initial begin
        buf_data   = 8'h00;
        buf_par    = 1'b0;
        buf_valid  = 1'b0;
        armed      = 1'b0;
        err_sticky = 1'b0;
    end

    assign in_ready  = !buf_valid || out_ready;
    assign out_valid = buf_valid;
    assign out_data  = buf_data;

    wire accept = in_valid  && in_ready;
    wire pop    = buf_valid && out_ready;

    // parity check on the word that is leaving the slice
    wire par_bad = pop && (buf_par != (^buf_data));

    always @(posedge clk) begin
        if (rst) begin
            buf_data   <= 8'h00;
            buf_par    <= 1'b0;
            buf_valid  <= 1'b0;
            armed      <= 1'b0;
            err_sticky <= 1'b0;
        end else begin
            if (par_bad)
                err_sticky <= 1'b1;

            if (accept) begin
                buf_data  <= in_data;
                buf_par   <= ^in_data;   // parity written with the data
                buf_valid <= 1'b1;
                armed     <= 1'b1;       // sticky, never cleared
            end else if (pop) begin
                buf_valid <= 1'b0;
            end
        end
    end

    // Property: once the slice has ever accepted a beat, no parity fault has
    // ever been observed on a departing word.
    always @(*)
        if (armed)
            assert (err_sticky == 1'b0);
endmodule

module seq_match_window (
    input  wire       clk,
    input  wire       i_ce,    // global enable: when low, nothing changes
    input  wire       data,    // serial bit stream
    input  wire       start,   // Q: opens the measurement window
    input  wire       stop,    // R: closes the measurement window
    output reg        armed,   // window register
    output reg  [3:0] mcnt,    // matches counted inside the window
    output reg  [3:0] slots,   // remaining match credits
    output reg  [2:0] prog     // match progress into the pattern 1011
);
    localparam [3:0] BUDGET = 4'd3;

    initial armed = 1'b0;
    initial mcnt  = 4'd0;
    initial slots = BUDGET;
    initial prog  = 3'd0;

    // full pattern 1-0-1-1 seen when three bits are already matched and data==1
    wire hit = (prog == 3'd3) && data;

    always @(posedge clk) begin
        if (i_ce) begin
            // ---- match-progress register (never exceeds the pattern length) ----
            case (prog)
                3'd0: prog <= data ? 3'd1 : 3'd0;
                3'd1: prog <= data ? 3'd1 : 3'd2;
                3'd2: prog <= data ? 3'd3 : 3'd0;
                3'd3: prog <= data ? 3'd1 : 3'd2;  // overlap-aware restart
                default: prog <= 3'd0;
            endcase

            // ---- window + credit bookkeeping ----
            if (stop) begin
                armed <= 1'b0;
            end else if (start) begin
                armed <= 1'b1;
                mcnt  <= 4'd0;
                slots <= BUDGET;
            end else if (armed && hit && (slots != 4'd0)) begin
                mcnt  <= mcnt  + 4'd1;
                slots <= slots - 4'd1;
            end
        end
    end

    // Property: inside an open window, at most 3 pattern occurrences are recorded,
    // even though mcnt is 4 bits wide.
    always @(posedge clk)
        if (armed) assert (mcnt <= 4'd3);
endmodule

module lfsr_prio_precedence (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output wire       o_valid,
    output wire [2:0] o_index
);
    // ---------------------------------------------------------------
    // 8-bit Fibonacci LFSR (taps 8,6,5,4) driving an 8-bit request
    // vector.  A nonzero state always maps to a nonzero state, so the
    // all-zeros lockup value is never produced.
    // ---------------------------------------------------------------
    reg [7:0] lfsr;
    reg [7:0] req_q;     // registered request vector (encoder input)
    reg [1:0] req_seen;  // shadow: history of "a request was present"
    reg       val_q;     // registered valid output
    reg [2:0] idx_q;     // registered index output

    initial lfsr     = 8'h01;
    initial req_q    = 8'h01;
    initial req_seen = 2'b11;
    initial val_q    = 1'b1;
    initial idx_q    = 3'd0;

    wire       fb        = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];
    wire [7:0] lfsr_next = { lfsr[6:0], fb };

    // combinational priority encoder over the registered request vector
    wire       vld = |req_q;
    wire [2:0] idx = req_q[7] ? 3'd7 :
                     req_q[6] ? 3'd6 :
                     req_q[5] ? 3'd5 :
                     req_q[4] ? 3'd4 :
                     req_q[3] ? 3'd3 :
                     req_q[2] ? 3'd2 :
                     req_q[1] ? 3'd1 : 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            lfsr     <= 8'h01;
            req_q    <= 8'h01;
            req_seen <= 2'b11;
            val_q    <= 1'b1;
            idx_q    <= 3'd0;
        end else if (ce) begin
            lfsr     <= lfsr_next;
            req_q    <= lfsr;
            req_seen <= { req_seen[0], |lfsr };
            val_q    <= vld;
            idx_q    <= idx;
        end
    end

    assign o_valid = val_q;
    assign o_index = idx_q;

    // Precedence: whenever the registered output stage reports a valid
    // index, the shadow history must record that a request bit was
    // actually present earlier in the pipeline.
    assert property (!o_valid || req_seen[1]);
endmodule

module dma_burst_engine (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_start,
    input wire [4:0] i_len,
    input wire [11:0] i_base,
    output reg o_busy
);
    // beats-remaining counter and its bookkeeping companions
    reg [4:0]  beats_left;
    reg [4:0]  beats_done;
    reg [4:0]  burst_len;
    reg [11:0] addr;
    reg [11:0] base;

    initial begin
        o_busy     = 1'b0;
        beats_left = 5'd0;
        beats_done = 5'd0;
        burst_len  = 5'd0;
        addr       = 12'd0;
        base       = 12'd0;
    end

    // requested length is clamped to the engine's maximum burst of 16 beats
    wire [4:0] eff_len = (i_len > 5'd16) ? 5'd16 : i_len;
    wire       accept  = (!o_busy) && i_start && (i_len != 5'd0);

    // address one past the last beat of the current burst
    wire [11:0] end_addr = base + ({7'd0, burst_len} << 2);

    always @(posedge clk) begin
        if (rst) begin
            o_busy     <= 1'b0;
            beats_left <= 5'd0;
            beats_done <= 5'd0;
            burst_len  <= 5'd0;
            addr       <= 12'd0;
            base       <= 12'd0;
        end else if (i_ce) begin
            if (o_busy) begin
                // issue one beat
                beats_left <= beats_left - 5'd1;
                beats_done <= beats_done + 5'd1;
                addr       <= addr + 12'd4;
                o_busy     <= (beats_left != 5'd1);
            end else if (accept) begin
                o_busy     <= 1'b1;
                beats_left <= eff_len;
                beats_done <= 5'd0;
                burst_len  <= eff_len;
                addr       <= i_base;
                base       <= i_base;
            end
        end
        // i_ce low: engine idles, all state held
    end

    // P: while the engine is busy, the beat pointer has not yet reached the
    // end of the burst region.
    always @(posedge clk)
        if (o_busy)
            assert (addr != end_addr);
endmodule

// One-hot process-step sequencer for a lithography/etch cell.
// Exactly one state bit is ever set; transitions are legal only from
// specific states.  Shadow registers record that earlier process steps
// really happened, and a sticky arm register remembers the first LOAD.
module litho_step_fsm (
    input  wire clk,
    input  wire rst,
    input  wire step,        // global enable / idle condition
    input  wire i_start,
    input  wire i_dose_ok,
    input  wire i_ack,
    output wire o_busy,
    output wire o_done
);
    localparam S_IDLE    = 0;
    localparam S_LOAD    = 1;
    localparam S_EXPOSE  = 2;
    localparam S_DEVELOP = 3;
    localparam S_ETCH    = 4;
    localparam S_DONE    = 5;

    reg [5:0] state;
    initial   state = 6'b000001;

    // shadow registers: earlier-event recorders
    reg saw_expose;
    reg saw_develop;
    initial saw_expose  = 1'b0;
    initial saw_develop = 1'b0;

    // sticky scope arm: set the first time a wafer is LOADed, never cleared
    reg armed;
    initial armed = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            state       <= 6'b000001;
            saw_expose  <= 1'b0;
            saw_develop <= 1'b0;
        end else if (step) begin
            case (1'b1)
                state[S_IDLE]: begin
                    if (i_start) begin
                        state       <= 6'b000010; // LOAD
                        saw_expose  <= 1'b0;      // fresh wafer
                        saw_develop <= 1'b0;
                    end
                end
                state[S_LOAD]: begin
                    state <= 6'b000100;           // EXPOSE
                end
                state[S_EXPOSE]: begin
                    if (i_dose_ok) begin
                        state      <= 6'b001000;  // DEVELOP
                        saw_expose <= 1'b1;       // exposure really completed
                    end
                end
                state[S_DEVELOP]: begin
                    state       <= 6'b010000;     // ETCH
                    saw_develop <= 1'b1;          // develop really completed
                end
                state[S_ETCH]: begin
                    state <= 6'b100000;           // DONE
                end
                state[S_DONE]: begin
                    if (i_ack)
                        state <= 6'b000001;       // IDLE
                end
                default: begin
                    state <= 6'b000001;
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst)
            armed <= 1'b0;
        else if (state[S_LOAD])
            armed <= 1'b1;
    end

    assign o_busy = ~state[S_IDLE];
    assign o_done = state[S_DONE];

    // Precedence, in the "after first LOAD" scope:
    // reaching ETCH requires a completed EXPOSE, reaching DONE a completed DEVELOP.
    always @(*) begin
        if (armed && state[S_ETCH])
            assert (saw_expose);
        if (armed && state[S_DONE])
            assert (saw_develop);
    end
endmodule

module skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       i_valid,
    input  wire [7:0] i_data,
    input  wire       o_ready,
    output wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_data
);
    // ---- pipeline stage registers ----
    reg       out_valid  = 1'b0;   // output register stage
    reg [7:0] out_data   = 8'h00;
    reg       skid_valid = 1'b0;   // stall flag
    reg [7:0] skid_data  = 8'h00;  // buffered word, meaningful only while skid_valid
    reg [1:0] occ        = 2'd0;   // independently maintained occupancy counter
    reg       pv         = 1'b0;   // past-valid

    assign i_ready = !skid_valid;
    assign o_valid = out_valid;
    assign o_data  = out_data;

    wire accept = ce && i_valid && !skid_valid;
    wire emit   = ce && out_valid && o_ready;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            out_valid  <= 1'b0;
            out_data   <= 8'h00;
            skid_valid <= 1'b0;
            skid_data  <= 8'h00;
            occ        <= 2'd0;
        end else if (ce) begin
            if (emit) begin
                if (skid_valid) begin
                    // drain the buffered word into the output register
                    out_data   <= skid_data;
                    out_valid  <= 1'b1;
                    skid_valid <= 1'b0;
                end else begin
                    out_valid <= accept;
                    if (accept) out_data <= i_data;
                end
            end else begin
                if (accept) begin
                    if (out_valid) begin
                        // downstream stalled: park the word in the skid buffer
                        skid_data  <= i_data;
                        skid_valid <= 1'b1;
                    end else begin
                        out_data  <= i_data;
                        out_valid <= 1'b1;
                    end
                end
            end
            occ <= occ + (accept ? 2'd1 : 2'd0) - (emit ? 2'd1 : 2'd0);
        end
    end

    // P: the moment the stall flag rises, the stage must be completely full
    always @(posedge clk)
        if (pv && $rose(skid_valid))
            assert (occ == 2'd2);
endmodule

// Carry-save split accumulator with a windowed flag-exclusion check.
// The accumulator value is held as two halves (acc_s, acc_c) whose 8-bit sum
// is the true running total; `total` is the directly-accumulated shadow copy.
module cs_accum_window (
    input  wire       clk,
    input  wire       ce,       // idle when low: no state changes at all
    input  wire       clr,
    input  wire       q_start,  // opens the observation window
    input  wire       r_stop,   // closes the observation window
    input  wire [7:0] din,
    output wire [7:0] sum_out
);

    // carry-save halves
    reg [7:0] acc_s;
    reg [7:0] acc_c;
    // golden (direct) accumulator
    reg [7:0] total;

    // window register (scope): set by q_start, cleared by r_stop
    reg       win;

    // two status flags, derived from the two different representations
    reg       f_lo;   // derived from the golden total
    reg       f_hi;   // derived from the carry-save halves

    initial begin
        acc_s = 8'd0;
        acc_c = 8'd0;
        total = 8'd0;
        win   = 1'b0;
        f_lo  = 1'b1;   // total(0) < 16
        f_hi  = 1'b0;   // acc_s+acc_c(0) < 16
    end

    // carry-save incorporation of din
    wire [7:0] cs_sum  = acc_s ^ acc_c ^ din;
    wire [7:0] cs_maj  = (acc_s & acc_c) | (acc_s & din) | (acc_c & din);
    wire [7:0] cs_carry = cs_maj << 1;   // top bit drops: mod-256 arithmetic

    assign sum_out = acc_s + acc_c;

    always @(posedge clk) begin
        if (ce) begin
            if (clr) begin
                acc_s <= 8'd0;
                acc_c <= 8'd0;
                total <= 8'd0;
            end else begin
                acc_s <= cs_sum;
                acc_c <= cs_carry;
                total <= total + din;
            end

            // flags sampled from the pre-update state, each from its own copy
            f_lo <= (total < 8'd16);
            f_hi <= ((acc_s + acc_c) >= 8'd16);

            if (r_stop)       win <= 1'b0;
            else if (q_start) win <= 1'b1;
        end
    end

    // P: inside the window the two flags are never asserted together
    always @(posedge clk)
        if (win)
            assert (!(f_lo && f_hi));

endmodule

// Debounced external halt request line for a small RISC-V core.
// The raw request must be seen identical for K = 4 consecutive enabled
// samples before the clean (core-visible) halt request is allowed to flip.
module halt_debounce (
    input  wire clk,
    input  wire i_ce,          // sample enable; low => whole design idles
    input  wire i_raw_halt,    // noisy external halt request
    output wire o_halt_req,    // debounced request presented to the core
    output wire o_stable
);
    // ---------------- state ----------------
    reg [1:0] cnt      = 2'd0; // consecutive-identical-sample counter (0..3)
    reg       cand     = 1'b0; // candidate (last raw sample) value
    reg       stable_f = 1'b0; // set once the candidate has been stable K-1 times
    reg       clean    = 1'b0; // debounced output

    reg       pv       = 1'b0; // past-valid

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_raw_halt != cand) begin
                // glitch: restart the stability measurement
                cand     <= i_raw_halt;
                cnt      <= 2'd0;
                stable_f <= 1'b0;
            end else begin
                // another identical sample; counter saturates at K-1
                if (cnt != 2'd3)
                    cnt <= cnt + 2'd1;
                if (cnt == 2'd2)
                    stable_f <= 1'b1;
                // only a candidate already marked stable may drive the output
                if (stable_f)
                    clean <= cand;
            end
        end
    end

    assign o_halt_req = clean;
    assign o_stable   = stable_f;

    // Property: the debounced output may only have changed on the previous
    // edge if the stability counter was saturated at K-1 at that time.
    always @(posedge clk)
        if (pv && (clean != $past(clean)))
            assert ($past(cnt) == 2'd3);
endmodule

module rr_credit_arb (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire [3:0] i_req,
    input  wire       i_ack_valid,
    input  wire [1:0] i_ack_id,
    output wire [3:0] o_grant,
    output wire [2:0] o_occ,
    output wire       o_armed
);
    // ---------------------------------------------------------------
    // Round-robin arbiter over 4 requesters with a last-grant pointer.
    // A line that already owns an outstanding grant (ack_pend) is
    // masked out, so a grant never lands on a busy or non-requesting
    // line, and the grant vector is one-hot-or-zero by construction.
    // ---------------------------------------------------------------
    reg [3:0] ack_pend;   // outstanding (granted, not yet acked) lines
    reg [2:0] occ;        // occupancy: number of outstanding grants
    reg [1:0] last;       // last granted index (round-robin pointer)
    reg       armed;      // high until line 3 has ever been granted

    initial ack_pend = 4'b0000;
    initial occ      = 3'd0;
    initial last     = 2'd3;
    initial armed    = 1'b1;

    wire [3:0] mreq = i_req & ~ack_pend;

    wire [1:0] p1 = last + 2'd1;
    wire [1:0] p2 = last + 2'd2;
    wire [1:0] p3 = last + 2'd3;

    reg [3:0] gnt_c;
    always @(*) begin
        gnt_c = 4'b0000;
        if (mreq[p1])       gnt_c = (4'b0001 << p1);
        else if (mreq[p2])  gnt_c = (4'b0001 << p2);
        else if (mreq[p3])  gnt_c = (4'b0001 << p3);
        else if (mreq[last])gnt_c = (4'b0001 << last);
    end

    wire       gnt_any = |gnt_c;
    wire [1:0] gidx    = gnt_c[0] ? 2'd0 :
                         gnt_c[1] ? 2'd1 :
                         gnt_c[2] ? 2'd2 : 2'd3;

    // an ack only counts if that line really has an outstanding grant
    wire       eff_ack   = i_ack_valid && ack_pend[i_ack_id];
    wire [3:0] ack_mask  = eff_ack ? (4'b0001 << i_ack_id) : 4'b0000;

    always @(posedge i_clk) begin
        if (i_reset) begin
            ack_pend <= 4'b0000;
            occ      <= 3'd0;
            last     <= 2'd3;
            armed    <= 1'b1;
        end else if (i_ce) begin
            ack_pend <= (ack_pend | gnt_c) & ~ack_mask;
            occ      <= occ + {2'b00, gnt_any} - {2'b00, eff_ack};
            if (gnt_any)
                last <= gidx;
            if (gnt_c[3])
                armed <= 1'b0;
        end
    end

    assign o_grant = i_ce ? gnt_c : 4'b0000;
    assign o_occ   = occ;
    assign o_armed = armed;

    // Property: before line 3 has ever been granted, at most three
    // grants can be outstanding at once (occ is 3 bits wide).
    always @(posedge i_clk)
        if (armed)
            assert (occ <= 3'd3);
endmodule

module histogram_commit_engine (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire [1:0]  bin_sel,
    output reg         busy,
    output reg  [1:0]  timer,
    output wire [9:0]  samples
);
    // histogram bins, incremented one at a time
    reg [7:0] bin0, bin1, bin2, bin3;
    // total-samples register
    reg [9:0] total;
    // which bin the outstanding request targets
    reg [1:0] sel;

    initial begin
        bin0  = 8'd0;
        bin1  = 8'd0;
        bin2  = 8'd0;
        bin3  = 8'd0;
        total = 10'd0;
        sel   = 2'd0;
        busy  = 1'b0;
        timer = 2'd0;
    end

    assign samples = total;

    wire [9:0] sum = {2'b00, bin0} + {2'b00, bin1} + {2'b00, bin2} + {2'b00, bin3};

    // headroom check performed when a request is accepted
    wire bins_ok = (bin0 < 8'hf0) && (bin1 < 8'hf0) && (bin2 < 8'hf0) && (bin3 < 8'hf0);

    // bookkeeping audit: bins must account for every recorded sample
    wire consistent = (sum == total);

    always @(posedge clk) begin
        if (rst) begin
            bin0  <= 8'd0;
            bin1  <= 8'd0;
            bin2  <= 8'd0;
            bin3  <= 8'd0;
            total <= 10'd0;
            sel   <= 2'd0;
            busy  <= 1'b0;
            timer <= 2'd0;
        end else if (ce) begin
            if (!busy) begin
                if (start && bins_ok) begin
                    busy  <= 1'b1;
                    timer <= 2'd3;
                    sel   <= bin_sel;
                end
            end else begin
                if (timer != 2'd0)
                    timer <= timer - 2'd1;
                // the commit fires on the last countdown tick, but only if the
                // audit passes; otherwise the request stays outstanding
                if ((timer == 2'd1) && consistent) begin
                    busy  <= 1'b0;
                    total <= total + 10'd1;
                    case (sel)
                        2'd0: bin0 <= bin0 + 8'd1;
                        2'd1: bin1 <= bin1 + 8'd1;
                        2'd2: bin2 <= bin2 + 8'd1;
                        2'd3: bin3 <= bin3 + 8'd1;
                    endcase
                end
            end
        end
    end

    // Bounded response, safety form: the countdown never expires while the
    // accepted sample request is still outstanding.
    always @(posedge clk)
        assert (!(busy && (timer == 2'd0)));
endmodule

module rtos_sched (
    input  wire i_clk,
    input  wire i_ce,       // scheduler tick enable; low means the kernel is idle
    input  wire i_req,      // a thread is ready to run
    input  wire i_kernel,   // the ready thread is a kernel thread
    input  wire i_start,    // first scheduler start event (arms the property)
    output wire o_grant_kern,
    output wire o_grant_user,
    output wire o_running
);

    // binary-encoded scheduler FSM: only 5 of the 8 encodings are ever entered
    localparam [2:0] S_IDLE   = 3'd0;
    localparam [2:0] S_FETCH  = 3'd1;
    localparam [2:0] S_KERNEL = 3'd2;
    localparam [2:0] S_USER   = 3'd3;
    localparam [2:0] S_SWITCH = 3'd4;
    localparam [2:0] S_FAULT  = 3'd6;   // unreachable trap encoding

    reg [2:0] state = S_IDLE;
    reg [1:0] cnt   = 2'd0;   // time-slice quantum counter, full 2-bit range
    reg       g_kern = 1'b0;
    reg       g_user = 1'b0;
    reg       armed  = 1'b0;  // sticky: set the first time the scheduler starts

    reg [2:0] nstate;
    reg       ngk, ngu;

    always @(*) begin
        case (state)
            S_IDLE:   nstate = i_req ? S_FETCH : S_IDLE;
            S_FETCH:  nstate = i_kernel ? S_KERNEL : S_USER;
            S_KERNEL: nstate = (cnt == 2'd3) ? S_SWITCH : S_KERNEL;
            S_USER:   nstate = (cnt == 2'd3) ? S_SWITCH : S_USER;
            S_SWITCH: nstate = i_req ? S_FETCH : S_IDLE;
            default:  nstate = S_FAULT;   // trap encodings lock up
        endcase
    end

    // grant decode for the state being entered
    always @(*) begin
        case (nstate)
            S_IDLE, S_FETCH, S_SWITCH: begin ngk = 1'b0; ngu = 1'b0; end
            S_KERNEL:                  begin ngk = 1'b1; ngu = 1'b0; end
            S_USER:                    begin ngk = 1'b0; ngu = 1'b1; end
            default:                   begin ngk = 1'b1; ngu = 1'b1; end
        endcase
    end

    always @(posedge i_clk) begin
        if (i_ce) begin
            state  <= nstate;
            g_kern <= ngk;
            g_user <= ngu;
            if (nstate == S_KERNEL || nstate == S_USER)
                cnt <= cnt + 2'd1;
            else
                cnt <= 2'd0;
        end
    end

    // sticky arming register: never cleared once the scheduler has started
    always @(posedge i_clk)
        if (i_start)
            armed <= 1'b1;

    assign o_grant_kern = g_kern;
    assign o_grant_user = g_user;
    assign o_running    = g_kern | g_user;

    // Absence: once the scheduler has been started, a kernel grant and a user
    // grant are never asserted together.
    always @(*)
        assert (!armed || !(g_kern && g_user));

endmodule

module fifo_burst_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] wdata,
    output wire       full,
    output wire       empty,
    output reg  [7:0] rdata
);
    // ---------------- state ----------------
    reg [2:0] wptr  = 3'd0;   // write pointer
    reg [2:0] rptr  = 3'd0;   // read pointer
    reg [3:0] count = 4'd0;   // occupancy
    reg       armed = 1'b0;   // window: set when the FIFO fills, cleared when it drains
    reg [7:0] mem [0:7];

    initial rdata = 8'h00;

    assign full  = (count == 4'd8);
    assign empty = (count == 4'd0);

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    wire [3:0] nxt_count = count + (do_push ? 4'd1 : 4'd0) - (do_pop ? 4'd1 : 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 3'd0;
            rptr  <= 3'd0;
            count <= 4'd0;
            armed <= 1'b0;
            rdata <= 8'h00;
        end else begin
            if (do_push) begin
                mem[wptr] <= wdata;
                wptr      <= wptr + 3'd1;
            end
            if (do_pop) begin
                rdata <= mem[rptr];
                rptr  <= rptr + 3'd1;
            end
            count <= nxt_count;
            // window register: opened by a full condition, closed by a drain to empty
            if (nxt_count == 4'd0)
                armed <= 1'b0;
            else if (nxt_count == 4'd8)
                armed <= 1'b1;
        end
    end

    // ---------------- properties ----------------
    // Inside the burst window (armed), the pointers must agree with the occupancy.
    always @(posedge clk) begin
        if (armed && count == 4'd1)
            assert (wptr == ((rptr + 3'd1) & 3'd7));
        if (armed && count == 4'd8)
            assert (wptr == rptr);
    end
endmodule

// Tracks outstanding memory requests issued into a 4-deep load/store pipeline.
// A shift register records which pipeline stages hold a live request; a separate
// counter tracks how many are in flight.
module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,   // pipeline advance / clock-enable
    input  wire       req,    // a new request is issued into stage 0
    output wire       f_idle, // no requests outstanding (from the counter)
    output wire       f_full, // all pipeline slots occupied (from the counter)
    output wire       f_any,  // some stage holds a request (from the shifter)
    output wire       f_slot  // some stage is free (from the shifter)
);

    reg [3:0] inflight;
    reg [2:0] cnt;
reg [1:0] bcnt;                 // stages 2,3 occupancy (back half)

    initial inflight = 4'b0000;
    initial cnt      = 3'd0;
initial bcnt     = 2'd0;

    // the request leaving the last stage completes this cycle
    wire retire = inflight[3];

    always @(posedge clk) begin
        if (rst) begin
            inflight <= 4'b0000;
            cnt      <= 3'd0;
bcnt     <= 2'd0;
        end else if (step) begin
            inflight <= {inflight[2:0], req};
// each pipeline half maintains its own occupancy count locally; a
// request crossing the stage1 -> stage2 boundary is handed over from
// the front count to the back count on the same advance
cnt      <= cnt  + {2'b00, req}           - {2'b00, inflight[1]};
bcnt     <= bcnt + {1'b0,  inflight[1]}   - {1'b0,  retire};
        end
    end

assign f_idle = (cnt == 3'd0) && (bcnt == 2'd0);
assign f_full = ((cnt + {1'b0, bcnt}) == 3'd4);
    assign f_any  = |inflight;
    assign f_slot = ~(&inflight);

    // P: the counter-derived flags and the shifter-derived flags may never
    // contradict each other -- idle together with an occupied stage, or
    // full together with a free stage.
    always @(posedge clk) assert (!(f_idle && f_any));
    always @(posedge clk) assert (!(f_full && f_slot));

endmodule

module lex_onehot_esc (
    input wire       i_clk,
    input wire       i_reset,
    input wire       i_ce,
    input wire [7:0] i_char,
    output wire      o_in_string,
    output wire [3:0] o_esc_count
);
    // one-hot lexer state: exactly one bit set by construction
    localparam S_IDLE  = 0;
    localparam S_IDENT = 1;
    localparam S_NUM   = 2;
    localparam S_STR   = 3;
    localparam S_ESC   = 4;

    reg [4:0] st;
    reg [3:0] cnt;   // escape sequences counted in the current string literal
   reg [3:0] lim;   // escape budget for the current string literal (default 8)
    reg       arm;   // sticky: set the first time a string literal is being scanned
    reg       pv;

    initial st  = 5'b00001;
    initial cnt = 4'd0;
   initial lim = 4'd8;
    initial arm = 1'b0;
    initial pv  = 1'b0;

    wire is_q   = (i_char == 8'h22);
    wire is_bs  = (i_char == 8'h5C);
    wire is_dig = (i_char >= 8'h30) && (i_char <= 8'h39);
    wire is_alp = ((i_char | 8'h20) >= 8'h61) && ((i_char | 8'h20) <= 8'h7A);

   // a numeric prefix before a literal programs the escape budget, clamped to 8
   wire [3:0] dig_lim = (i_char[3:0] > 4'd8) ? 4'd8 : i_char[3:0];

    reg [4:0] nst;
    reg [3:0] ncnt;
   reg [3:0] nlim;

    always @(*) begin
        nst  = st;
        ncnt = cnt;
       nlim = lim;
        if (st[S_IDLE]) begin
            if (is_q) begin
                nst  = 5'b01000;   // open quote: enter string, fresh escape count
                ncnt = 4'd0;
           end else if (is_dig) begin
               nst  = 5'b00100;
               nlim = dig_lim;    // leading digit programs the budget
           end
            else if (is_alp)
                nst = 5'b00010;
            else
                nst = 5'b00001;
        end else if (st[S_IDENT]) begin
            nst = (is_alp || is_dig) ? 5'b00010 : 5'b00001;
        end else if (st[S_NUM]) begin
            nst = is_dig ? 5'b00100 : 5'b00001;
           if (is_dig) nlim = dig_lim;   // later digits override the budget
        end else if (st[S_STR]) begin
            if (is_q) begin
               nst  = 5'b00001;   // close quote: budgeted escapes retire here
               ncnt = (cnt > lim) ? (cnt - lim) : 4'd0;  // surplus carries on
            end else if (is_bs)
                nst = 5'b10000;    // ESC is reachable only from STR
            else
                nst = 5'b01000;
        end else if (st[S_ESC]) begin
            nst  = 5'b01000;       // ESC always returns to STR
           ncnt = (cnt == lim) ? cnt : (cnt + 4'd1);   // saturate at the budget
        end
    end

    always @(posedge i_clk) begin
        if (i_reset) begin
            st  <= 5'b00001;
            cnt <= 4'd0;
           lim <= 4'd8;
        end else if (i_ce) begin
            st  <= nst;
            cnt <= ncnt;
           lim <= nlim;
        end

        if (i_ce && !i_reset && (st[S_STR] || st[S_ESC]))
            arm <= 1'b1;

        pv <= 1'b1;
    end

    assign o_in_string  = st[S_STR] || st[S_ESC];
    assign o_esc_count  = cnt;

    // Universality, in the "after arm" scope, stated about the previous cycle:
    // once a string literal has been seen, the escape counter is always zero
    // whenever the lexer sits in the IDLE state.
    always @(posedge i_clk)
        if (pv && arm)
            assert (!$past(st[S_IDLE]) || ($past(cnt) == 4'd0));
endmodule

module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] req,
    output reg  [3:0] gnt,
    output reg  [1:0] stage
);
    // round-robin arbiter state
    reg [1:0] last_gnt;
    // chain-precedence bookkeeping: arm (line0) -> start (line1) -> finish (line2)
    reg       seen_arm;
    reg       seen_start;
    // sticky scope register: set the first time any grant is issued
    reg       armed;
   // peer chain B: shares the start unit with chain A
   // arm(line2) -> start(line3) -> finish(line1)
   reg [1:0] stage_b;
   // shared start unit is primed and not yet consumed
   reg       start_tok;

    initial begin
        last_gnt   = 2'd3;
        gnt        = 4'b0000;
        stage      = 2'd0;
        seen_arm   = 1'b0;
        seen_start = 1'b0;
        armed      = 1'b0;
       stage_b    = 2'd0;
       start_tok  = 1'b0;
    end

    // combinational round-robin grant: one-hot, never on a non-requesting line
    reg [3:0] gnt_c;
    always @(*) begin
        case (last_gnt)
            2'd0: gnt_c = req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 : 4'b0000;
            2'd1: gnt_c = req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 : 4'b0000;
            2'd2: gnt_c = req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 : 4'b0000;
            default: gnt_c = req[0] ? 4'b0001 :
                             req[1] ? 4'b0010 :
                             req[2] ? 4'b0100 :
                             req[3] ? 4'b1000 : 4'b0000;
        endcase
    end

    wire [1:0] gnt_idx = gnt_c[0] ? 2'd0 :
                         gnt_c[1] ? 2'd1 :
                         gnt_c[2] ? 2'd2 : 2'd3;

    wire fire = i_ce && (gnt_c != 4'b0000);

    always @(posedge clk) begin
        gnt <= fire ? gnt_c : 4'b0000;
        if (fire) begin
            last_gnt <= gnt_idx;
            armed    <= 1'b1;
            case (stage)
                2'd0: begin
                    if (gnt_c[0]) begin
                        stage    <= 2'd1;   // ARM step
                        seen_arm <= 1'b1;
                    end
                end
                2'd1: begin
                    if (gnt_c[1]) begin
                        stage      <= 2'd2; // START step
                        seen_start <= 1'b1;
                   end else if (start_tok && gnt_c[2]) begin
                       stage      <= 2'd3; // start unit already primed: skip START
                   end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                       start_tok  <= 1'b0; // release shared start unit
                    end
                end
                2'd2: begin
                    if (gnt_c[2]) begin
                        stage <= 2'd3;      // FINISH step
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                       start_tok  <= 1'b0; // release shared start unit
                    end
                end
                default: begin
                    stage      <= 2'd0;     // retire transaction
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                   start_tok  <= 1'b0;     // release shared start unit
                end
            endcase
           // peer chain B drives the same start unit from the high lines
           case (stage_b)
               2'd0: if (gnt_c[2]) stage_b <= 2'd1;   // ARM step (B)
               2'd1: if (gnt_c[3]) begin
                         stage_b    <= 2'd2;          // START step (B)
                         seen_start <= 1'b1;          // shared unit has run
                         start_tok  <= 1'b1;          // and stays primed
                     end
               2'd2: if (gnt_c[1]) begin
                         stage_b   <= 2'd3;           // FINISH step (B)
                         start_tok <= 1'b0;           // B consumes the unit
                     end
               default: stage_b <= 2'd0;              // retire B
           endcase
        end
    end

    // P: once the arbiter has ever granted (sticky armed), a finished
    // transaction can only be observed if arm and start really happened.
    always @(posedge clk)
        if (armed && stage == 2'd3)
            assert (seen_arm && seen_start);
endmodule

module credit_rr_arbiter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire [3:0] req,       // four requesters
    input  wire       ret,       // consumer returns one credit
    output reg  [1:0] rr_ptr,    // rotating priority pointer
    output reg  [3:0] grant,     // one-hot grant
    output reg  [3:0] credits,   // credits held by the producer
    output reg  [3:0] outstanding // credits in flight at the consumer
);
    localparam [3:0] TOTAL = 4'd8;

   // credits parked against the burst currently in flight
   reg [1:0] escrow;

    initial rr_ptr      = 2'd0;
    initial grant       = 4'b0000;
    initial credits     = TOTAL;
    initial outstanding = 4'd0;
   initial escrow      = 2'd0;

    // rotating priority selection: first requester at or after rr_ptr
    wire [1:0] idx = req[rr_ptr]          ? rr_ptr          :
                     req[rr_ptr + 2'd1]   ? rr_ptr + 2'd1   :
                     req[rr_ptr + 2'd2]   ? rr_ptr + 2'd2   :
                                            rr_ptr + 2'd3;

   // at burst start one credit per other waiting requester is parked in
   // escrow, so a burst that has been admitted can always be drained
   wire [3:0] others = req & ~(4'b0001 << idx);
   wire [1:0] resv   = {1'b0, others[0]} + {1'b0, others[1]} +
                       {1'b0, others[2]} + {1'b0, others[3]};
   wire       burst_start = (outstanding == 4'd0);
   wire [3:0] need        = burst_start ? (4'd1 + {2'b00, resv}) : 4'd1;
   wire have_credit = (credits >= need);
    wire any_req     = |req;

    // a grant spends one credit; it becomes outstanding until returned
    wire do_grant = i_ce && have_credit && any_req;
    wire do_ret   = i_ce && ret && (outstanding != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            rr_ptr      <= 2'd0;
            grant       <= 4'b0000;
            credits     <= TOTAL;
            outstanding <= 4'd0;
           escrow      <= 2'd0;
        end else if (i_ce) begin
            grant <= do_grant ? (4'b0001 << idx) : 4'b0000;
            if (do_grant)
                rr_ptr <= idx + 2'd1;

            if (do_grant && !do_ret) begin
               if (burst_start) begin
                   credits <= credits - 4'd1 - {2'b00, resv};
                   escrow  <= resv;
               end else begin
                   credits <= credits - 4'd1;
               end
                outstanding <= outstanding + 4'd1;
            end else if (!do_grant && do_ret) begin
               if (outstanding == 4'd1) begin
                   credits <= credits + 4'd1 + {2'b00, escrow};
                   escrow  <= 2'd0;
               end else begin
                   credits <= credits + 4'd1;
               end
                outstanding <= outstanding - 4'd1;
            end
        end
    end

    // P: whenever nothing is in flight, the producer holds every credit
    always @(posedge clk)
        if (outstanding == 4'd0)
            assert (credits == TOTAL);
endmodule

module wifi_radio_owner_fsm (
    input  wire clk,
    input  wire rst,
    input  wire step,      // idle/enable: low freezes all state
    input  wire rx_start,  // preamble detected by the receiver
    input  wire tx_req,    // MAC wants the air for a frame
    output wire radio_tx,  // transmit chain owns the radio
    output wire radio_rx   // receive chain owns the radio
);
    // one-hot MAC air-interface FSM:
    //   bit0 = IDLE, bit1 = RX_FRAME, bit2 = TX_PREAMBLE,
    //   bit3 = TX_DATA, bit4 = ACK_WAIT
    reg [4:0] state;
    initial state = 5'b00001;

   // periodic beacon engine; shares the radio front end with the MAC FSM
   //   bit0 = B_IDLE, bit1 = B_RAMP, bit2 = B_SEND
   reg [2:0] bstate;
   reg [3:0] btimer;
   initial bstate = 3'b001;
   initial btimer = 4'd15;

    wire s_idle  = state[0];
    wire s_rx    = state[1];
    wire s_txpre = state[2];
    wire s_tx    = state[3];
    wire s_ackw  = state[4];

   wire b_idle = bstate[0];
   wire b_ramp = bstate[1];
   wire b_send = bstate[2];
   wire b_busy = b_ramp | b_send;
   wire b_due  = (btimer == 4'd0);
   // the MAC keeps priority: the beacon only grabs an idle, unrequested radio
   wire b_go   = b_idle & b_due & s_idle & ~rx_start & ~tx_req;

   wire [2:0] bnxt;
   assign bnxt[0] = (b_idle & ~b_go) | b_send;
   assign bnxt[1] = b_go;                             // ramp the beacon PA
   assign bnxt[2] = b_ramp;                           // ramp -> send beacon

    // next-state as a per-bit OR of its legal source states
    wire [4:0] nxt;
    assign nxt[0] = (s_idle & ~rx_start & ~tx_req) | s_rx | s_ackw;
    assign nxt[1] = s_idle & rx_start;                 // RX wins the air
    assign nxt[2] = s_idle & tx_req & ~rx_start;       // else start TX ramp
    assign nxt[3] = s_txpre;                           // preamble -> data
    assign nxt[4] = s_tx;                              // data -> wait for ACK

    always @(posedge clk) begin
        if (rst)
            state <= 5'b00001;
       // the air is single-ported: the MAC FSM stalls while the beacon has it
       else if (step && !b_busy)
            state <= nxt;
    end

   always @(posedge clk) begin
       if (rst)
           bstate <= 3'b001;
       else if (step)
           bstate <= bnxt;
   end

   // beacon interval: reload on transmission, hold at zero until the air frees
   always @(posedge clk) begin
       if (rst)
           btimer <= 4'd15;
       else if (step) begin
           if (b_send)
               btimer <= 4'd15;
           else if (btimer != 4'd0)
               btimer <= btimer - 4'd1;
       end
   end

    // decoded radio ownership
   assign radio_tx = s_txpre | s_tx | b_ramp | b_send;
    assign radio_rx = s_rx    | s_ackw;

    // P: the transmit and receive chains never own the radio together
    always @(*)
        assert (!(radio_tx && radio_rx));
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;
   // programmable ring bound: the bridge starts at quarter span after reset and
   // opens up one binary step per four completed laps
   reg [3:0] lim;
   reg [1:0] laps;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
       lim  = 4'd3;
       laps = 2'd0;
    end

   wire       wrap     = (cnt >= lim);
   wire [3:0] nxt      = wrap ? 4'd0 : cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
            s1  <= g;
            s2  <= s1;
           if (wrap) begin
               laps <= laps + 2'd1;
               if (laps == 2'd3)
                   lim <= {lim[2:0], 1'b1};
           end
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
    assign o_settled = (diff == 4'd0);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

// PWM channel for a wire-logic accelerator block.
// Period counter walks 0..PER-1, duty is double buffered at the period edge,
// and high_cnt accumulates the number of high cycles elapsed in the period.
module pwm_channel (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire       i_load,
    input  wire [3:0] i_duty,
    output wire       pwm_out,
    output reg        armed
);
    localparam [3:0] PER = 4'd12;

    reg [3:0] cnt;       // period counter, 0 .. PER-1
    reg [3:0] duty;      // active duty, 0 .. PER
    reg [3:0] high_cnt;  // high cycles elapsed so far this period
   reg       pwm_q;     // registered output stage, resolved one cycle ahead

    initial begin
        cnt      = 4'd0;
        duty     = 4'd0;
        high_cnt = 4'd0;
        armed    = 1'b0;
       pwm_q    = 1'b0;
    end

    // the construct: output high exactly while the counter is below the duty
   assign pwm_out = pwm_q;

    wire [3:0] duty_clamped = (i_duty > PER) ? PER : i_duty;
    wire       at_edge      = (cnt == PER - 4'd1);

   // Next-cycle counter and duty. The output register is loaded from these so
   // the pin keeps the same alignment the combinational comparator had, while
   // the compare itself is off the critical path.
   wire [3:0] cnt_nxt  = at_edge ? 4'd0 : cnt + 4'd1;
   wire [3:0] duty_nxt = (at_edge && i_load) ? duty_clamped : duty;

    always @(posedge clk) begin
        if (rst) begin
            cnt      <= 4'd0;
            duty     <= 4'd0;
            high_cnt <= 4'd0;
            armed    <= 1'b0;
           pwm_q    <= 1'b0;
        end else if (i_ce) begin
           pwm_q <= (cnt_nxt < duty_nxt);
            if (at_edge) begin
                // period rolls over: new duty takes effect, accumulator clears
                cnt      <= 4'd0;
                high_cnt <= 4'd0;
                armed    <= 1'b1;            // sticky, never cleared
                if (i_load)
                    duty <= duty_clamped;
            end else begin
                cnt      <= cnt + 4'd1;
                high_cnt <= high_cnt + (pwm_out ? 4'd1 : 4'd0);
            end
        end
    end

    // Property (universality, after the first completed period):
    // the accumulated high time never exceeds the duty, and the live output
    // agrees with the accumulator's headroom.
    always @(posedge clk)
        if (armed)
            assert (high_cnt <= duty);

    always @(posedge clk)
        if (armed)
            assert (pwm_out == (high_cnt < duty));
endmodule

// Valid/ready pipeline stage with a skid buffer carrying a three-step
// command chain: ARM -> START -> FINISH -> ARM -> ...
// The buffered word is only meaningful while the stage is stalled.
module chain_skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,       // global enable / idle condition
    input  wire       in_valid,   // producer offers its next chain word
    input  wire       out_ready,  // consumer accepts
    output wire       o_valid,
    output wire [1:0] o_code,
    output wire       o_in_ready
);
    localparam [1:0] ARM    = 2'd1;
    localparam [1:0] START  = 2'd2;
    localparam [1:0] FINISH = 2'd3;

    // producer chain position: next word emitted is src_phase+1
    reg [1:0] src_phase  = 2'd0;
    // consumer chain position: 0 = nothing armed, 1 = armed, 2 = started
    reg [1:0] phase      = 2'd0;

    // output (skid) register pair
    reg       out_valid  = 1'b0;
    reg [1:0] out_code   = ARM;
    reg       skid_valid = 1'b0;
    reg [1:0] skid_code  = ARM;

   // one-cycle inter-chain gap: after a FINISH leaves the stage the
   // producer is held off for a cycle so it can resynchronise on the
   // head of the next chain
   reg       gap        = 1'b0;

    wire [1:0] in_code  = src_phase + 2'd1;
   wire       in_ready = !skid_valid && !gap;
    wire       out_room = !out_valid || out_ready;
    wire       in_fire  = step && in_valid && in_ready;
    wire       out_fire = step && out_valid && out_ready;

    assign o_valid    = out_valid;
    assign o_code     = out_code;
    assign o_in_ready = in_ready;

    always @(posedge clk) begin
        if (rst) begin
            src_phase  <= 2'd0;
            phase      <= 2'd0;
            out_valid  <= 1'b0;
            out_code   <= ARM;
            skid_valid <= 1'b0;
            skid_code  <= ARM;
           gap        <= 1'b0;
        end else if (step) begin
            // output register: drain skid first, else take the fresh word
            if (out_room) begin
                if (skid_valid) begin
                    out_valid <= 1'b1;
                    out_code  <= skid_code;
               end else if (in_valid && in_ready) begin
                    out_valid <= 1'b1;
                    out_code  <= in_code;
                end else begin
                    out_valid <= 1'b0;
                end
            end

            // skid buffer: only loaded while the stage is stalled
            if (skid_valid) begin
                if (out_room)
                    skid_valid <= 1'b0;
           end else if (in_valid && in_ready && !out_room) begin
                skid_valid <= 1'b1;
                skid_code  <= in_code;
            end

            // producer advances on every accepted word
            if (in_valid && in_ready)
                src_phase <= (src_phase == 2'd2) ? 2'd0 : src_phase + 2'd1;

            // consumer chain tracker advances on every delivered word
            if (out_valid && out_ready)
                phase <= (out_code == FINISH) ? 2'd0 : out_code;

           // hold the producer off for one cycle after a completed chain
           gap <= out_valid && out_ready && out_code == FINISH;
        end
    end

    // P (two assertions): a later chain step is never delivered unless the
    // earlier ones already were.
    always @(*)
        assert (!(out_fire && out_code == FINISH) || phase == 2'd2);

    always @(*)
        assert (!(out_fire && out_code == START) || phase == 2'd1);

   // Q: the only word that may leave the stage during the post-FINISH
   // gap cycle is the ARM that opens the next chain.
   always @(posedge clk)
       if (!rst)
           assert (!(gap && out_fire) || out_code == ARM);
endmodule

// In-flight tracker for a fixed-latency chart-query render pipeline.
// Each issued query walks a 4-stage valid shift register; occupancy is the
// number of ones currently resident in that shift register.
module query_pipe_tracker (
    input  wire       clk,
    input  wire       ce,        // pipeline advance / idle control
    input  wire       issue,     // a new query is pushed into stage 0
    output wire       retire,    // a rendered result leaves the last stage
    output wire       full,      // tracker says all 4 slots are busy
    output reg  [2:0] occ        // queries in flight
);

    reg [3:0] pipe;              // fixed-latency valid shift register
    reg       hold;              // input capture slot: query admitted while stalled
    reg       ever_issued;       // shadow: an issue has been observed earlier
    reg       armed;             // scope: still before the pipe was ever full

    initial begin
        pipe        = 4'b0000;
        occ         = 3'd0;
        ever_issued = 1'b0;
        armed       = 1'b1;
        hold        = 1'b0;
    end

    assign retire = pipe[3];
    assign full   = (occ == 3'd4);

    // Admission control: the tracker backpressures at capacity, and a query
    // taken while the pipe is not advancing waits in the capture slot.
    wire room   = (occ != 3'd4);
    wire accept = issue && !hold && room;   // query admitted this cycle
    wire inject = hold || accept;           // entry pushed into stage 0

    always @(posedge clk) begin
        if (ce) begin
            // drain: stage 3 retires, everything shifts, stage 0 takes issue
            pipe <= {pipe[2:0], inject};

            // occupancy bookkeeping: +1 on issue, -1 on retire
            occ  <= occ + {2'b00, accept} - {2'b00, pipe[3]};
            hold <= 1'b0;

            // shadow register for the earlier event
            if (accept) ever_issued <= 1'b1;

            // scope closes the first time the unit reports saturation
            if (full)  armed <= 1'b0;
        end else if (accept) begin
            // stalled: park the admitted query and count it as in flight
            hold        <= 1'b1;
            occ         <= occ + 3'd1;
            ever_issued <= 1'b1;
        end
    end

    // Precedence, before the unit was ever full:
    // if work is in flight now, an issue must have happened earlier.
    always @(posedge clk)
        if (armed && occ != 3'd0)
            assert (ever_issued);

endmodule

module dma_burst_dimmer (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // beat enable / idle when low
    input  wire       i_start,
    input  wire [3:0] i_beats,
    input  wire [3:0] i_duty,
    output wire       o_busy,
    output wire       o_beat,
    output wire       o_pwm
);

    // ---- DMA burst engine state ----
    reg [3:0] beats_left;   // beats remaining in the burst
    reg [3:0] done_cnt;     // beats already pushed out
    reg [3:0] total;        // beats requested by the accepted burst
    reg [3:0] duty;         // dimming level latched with the burst
    reg       busy;         // up exactly while beats remain
    reg [3:0] queued;       // beats accepted but not yet issued into the current chunk

    initial beats_left = 4'd0;
    initial done_cnt   = 4'd0;
    initial total      = 4'd0;
    initial duty       = 4'd0;
    initial busy       = 1'b0;
    initial queued     = 4'd0;

    // the fabric only accepts short chunks, so a long burst is issued piecewise
    localparam [3:0] CHUNK_MAX = 4'd4;
    wire [3:0] first_chunk = (i_beats > CHUNK_MAX) ? CHUNK_MAX : i_beats;
    wire [3:0] next_chunk  = (queued  > CHUNK_MAX) ? CHUNK_MAX : queued;

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            done_cnt   <= 4'd0;
            total      <= 4'd0;
            duty       <= 4'd0;
            queued     <= 4'd0;
            busy       <= 1'b0;
        end else if (i_start && !busy && (i_beats != 4'd0)) begin
            // accept a new burst
            beats_left <= first_chunk;
            queued     <= i_beats - first_chunk;
            total      <= i_beats;
            done_cnt   <= 4'd0;
            duty       <= i_duty;
            busy       <= 1'b1;
        end else if (i_ce) begin
            // retire one beat
            if (beats_left > 4'd1) begin
                beats_left <= beats_left - 4'd1;
            end else if (beats_left == 4'd1) begin
                // current chunk drained: pull the next chunk out of the queue
                beats_left <= next_chunk;
                queued     <= queued - next_chunk;
            end
            if ((beats_left <= 4'd1) && (queued == 4'd0))
                busy <= 1'b0;
            if (busy)
                done_cnt <= done_cnt + 4'd1;
        end
    end

    assign o_busy = busy;
    assign o_beat = busy && i_ce;
    assign o_pwm  = busy && (done_cnt < duty);

    // ---- P: whenever the engine is not busy, the whole burst has been pushed ----
    always @(posedge i_clk)
        if (!busy)
            assert (done_cnt == total);

endmodule

module window_rate_limiter (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_req,
    output wire o_grant
);
    parameter W     = 4;
    parameter LIMIT = 3;

    // sliding window of the last W grant decisions
    reg [W-1:0] win;
    // count of ones that mirrors the window by construction
    reg [2:0]   ones;
   // admit decision in flight toward the accumulator: the count update is
   // retimed through one register stage, so `ones` trails the window by a beat
   reg         adm_q;
    // sticky arm register: set the first time a grant is ever issued
    reg         armed;
    reg         pv;

    initial win   = 0;
    initial ones  = 0;
   initial adm_q = 0;
    initial armed = 0;
    initial pv    = 0;

    // the bit about to leave the window
    wire [2:0] retiring = win[W-1] ? 3'd1 : 3'd0;
    // occupancy of the window once the oldest slot retires
   // plus the admit still in flight, which the accumulator has not absorbed yet
   wire [2:0] eff      = ones - retiring + (adm_q ? 3'd1 : 3'd0);

    // rate decision is taken from the mirrored count, not from the window
    wire allow = i_req && (eff < LIMIT);

    assign o_grant = i_ce && allow;

    always @(posedge clk) begin
        if (i_rst) begin
            win   <= 0;
            ones  <= 0;
           adm_q <= 0;
            armed <= 0;
        end else if (i_ce) begin
           win   <= { win[W-2:0], allow };
           ones  <= ones - retiring + (adm_q ? 3'd1 : 3'd0);
           adm_q <= allow;
            if (allow)
                armed <= 1'b1;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    // Precedence, after the limiter has armed: a grant observed one cycle ago
    // must have been preceded by a window that was not already saturated, so
    // the window can never be completely full of grants.
    always @(posedge clk)
        if (pv && armed)
            assert (!($past(i_ce) && $past(allow)) || (win != 4'hF));
endmodule

module issue_token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire [1:0] i_req,     // dual-issue: 0, 1 or 2 slots want to issue
    output wire [1:0] o_grant,   // slots actually granted this cycle
    output reg  [3:0] tokens     // credits left in the bucket
);
    localparam [3:0] BURST  = 4'd8;   // bucket capacity
    localparam [2:0] PERIOD = 3'd5;   // refill timer period

    // thermometer-coded shadow of the bucket occupancy
    reg [7:0] bucket;
    // refill timer
    reg [2:0] tick_cnt;
// staged refill: the widened thermometer word waits here for one cycle
reg [7:0] b_stage;
reg       ref_v;

    initial begin
        tokens   = 4'd0;
        bucket   = 8'h00;
        tick_cnt = 3'd0;
b_stage  = 8'h00;
ref_v    = 1'b0;
    end

    wire       tick    = (tick_cnt == PERIOD);
    wire [1:0] req_c   = (i_req == 2'd3) ? 2'd2 : i_req;

    // grants are limited by available credits
    wire [1:0] n_drain = (tokens >= {2'b00, req_c}) ? req_c : tokens[1:0];

// stage 2: a posted refill lands in the bucket on this cycle
wire       do_ref  = ref_v;

wire [7:0] b_src   = ref_v ? b_stage : bucket;
wire [7:0] b_nxt   = b_src >> n_drain;
    wire [3:0] t_nxt   = tokens + (do_ref ? 4'd1 : 4'd0) - {2'b00, n_drain};

// stage 1: the timer posts one credit unless the bucket would be full
wire       ref_post = tick && (t_nxt != BURST);

    assign o_grant = i_ce ? n_drain : 2'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens   <= 4'd0;
            bucket   <= 8'h00;
            tick_cnt <= 3'd0;
b_stage  <= 8'h00;
ref_v    <= 1'b0;
        end else if (i_ce) begin
            tokens   <= t_nxt;
            bucket   <= b_nxt;
b_stage  <= ref_post ? {b_nxt[6:0], 1'b1} : b_stage;
ref_v    <= ref_post;
            tick_cnt <= tick ? 3'd0 : (tick_cnt + 3'd1);
        end
    end

    // P: whenever the credit counter reads empty, the thermometer shadow
    //    of the bucket must be empty as well.
    always @(posedge clk)
        if (tokens == 4'd0)
            assert (bucket == 8'h00);

endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
    output wire [2:0] o_inflight
);
// fixed-latency (6 cycle) pipeline occupancy shift register
reg [5:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;
// remaining issue credits: an op is only taken while credits are left
reg [2:0] cred;
// currently programmed outstanding-op limit, retuned at each quiesce point
reg [2:0] lim;
// congestion flag: enable dropped while work was still in flight
reg       thr;

initial pipe     = 6'b000000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;
initial cred     = 3'd4;
initial lim      = 3'd4;
initial thr      = 1'b0;

wire retire  = pipe[5];
// credit gate on the issue path
wire accept  = issue && (cred != 3'd0);
// true quiesce: pipeline drained and nothing arriving this cycle
wire quiesce = (pipe == 6'b000000) && !issue;

    always @(posedge clk) begin
        if (rst) begin
pipe     <= 6'b000000;
            inflight <= 3'd0;
        end else if (i_ce) begin
pipe     <= {pipe[4:0], accept};
inflight <= inflight + {2'b00, accept} - {2'b00, retire};
        end
    end
// credit accounting and outstanding-limit retuning
always @(posedge clk) begin
    if (rst) begin
        cred <= 3'd4;
        lim  <= 3'd4;
        thr  <= 1'b0;
    end else if (i_ce) begin
        if (quiesce) begin
            lim  <= thr ? 3'd2 : 3'd4;
            cred <= thr ? 3'd2 : 3'd4;
            thr  <= 1'b0;
        end else begin
            cred <= cred - {2'b00, accept} + {2'b00, retire};
        end
    end else if (pipe != 6'b000000) begin
        thr  <= 1'b1;
    end
end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
reg [2:0] credit   = 3'd0;  // samples carried over from the previous run
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

    initial o_clean = 1'b0;
// effective stability count: fresh samples plus carried-over credit
wire [3:0] total = {1'b0, cnt} + {1'b0, credit};

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_raw != samp) begin
                // sample changed: restart the stability count
                samp     <= i_raw;
                cnt      <= 3'd0;
                stable_f <= 1'b0;
// keep up to two samples of the run just lost, so a line that had
// already settled reacquires after a short bounce
credit   <= (cnt >= 3'd2) ? 3'd2 : cnt;
end else if (total != K) begin
                cnt      <= cnt + 3'd1;
stable_f <= (total == K - 3'd1);
if (total == K - 3'd1)
                    o_clean <= samp;   // commit the debounced value
            end
            // cnt == K: saturated, hold cnt, stable_f and o_clean

            if (i_disarm)
                armed <= 1'b0;
            else if (i_arm)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

// Debug-probe challenge sequencer: a maximal-length LFSR supplies one tick per
// chain step (arm -> start -> finish). The LFSR is seeded non-zero and can never
// enter the all-zeros lockup state, so every FSM advance is accompanied by a
// genuine change of the challenge shift register.
module probe_chain_seq (
    input  wire       clk,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire       arm,
    input  wire       start,
    input  wire       fin,
    output reg  [1:0] stage,
    output reg        pre_done,
    output reg  [3:0] chal
);
    // stage encoding: 0 = IDLE, 1 = ARMED, 2 = RUNNING, 3 = DONE
    reg [3:0] lfsr;
    reg       pv;
    // channel B: second probe chain sharing the one challenge generator
    reg [1:0] stage_b;
    reg       own;      // 0 = chain A holds the generator, 1 = chain B
    reg       ld;       // generator context restore in flight (owner stalls)
    reg       chal_ok;  // chal holds a valid generator word

    initial lfsr     = 4'b0001;
    initial chal     = 4'b0000;
    initial stage    = 2'd0;
    initial pre_done = 1'b1;   // before-scope: high until the first DONE ever
    initial pv       = 1'b0;
    initial stage_b  = 2'd0;
    initial own      = 1'b0;
    initial ld       = 1'b0;
    initial chal_ok  = 1'b0;

    // x^4 + x^3 + 1 : period 15 over the non-zero states
    wire       fb        = lfsr[3] ^ lfsr[2];
    wire [3:0] lfsr_next = {lfsr[2:0], fb};

    // Only one generator word is parked across a handover: the incoming owner
    // resumes from the last challenge word issued on the shared bus, or from
    // the cold seed if no challenge has been issued yet.
    wire [3:0] lfsr_rest = chal_ok ? chal : 4'b0001;

    // the current owner releases the generator once its chain reaches DONE
    wire a_done = (stage   == 2'd3);
    wire b_done = (stage_b == 2'd3);
    wire yield  = !ld && (own ? b_done : a_done);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            lfsr <= ld ? lfsr_rest : lfsr_next;
            if (yield) own <= ~own;
            ld <= yield;
            if (!ld) begin
            if (!own) begin
            case (stage)
                2'd0: if (arm) begin
                          stage <= 2'd1;
                          chal  <= lfsr;      // latch the challenge word on arm
                      chal_ok <= 1'b1;
                      end
                2'd1: if (start) stage <= 2'd2;
                2'd2: if (fin) begin
                          stage    <= 2'd3;   // finish: clears the before-scope
                          pre_done <= 1'b0;
                      end
                default: stage <= 2'd0;
            endcase
            end else begin
                case (stage_b)
                    2'd0: if (arm) begin
                              stage_b <= 2'd1;
                              chal    <= lfsr;   // same challenge bus
                              chal_ok <= 1'b1;
                          end
                    2'd1: if (start) stage_b <= 2'd2;
                    2'd2: if (fin)   stage_b <= 2'd3;
                    default: stage_b <= 2'd0;
                endcase
            end
            end
        end
    end

    // P: before the first finish has ever been observed, the chain FSM cannot
    //    move unless the challenge shift register moved with it.
    always @(posedge clk)
        if (pv && pre_done && $stable(lfsr))
            assert ($stable(stage));
endmodule

// Packet-capture sensor credit window.
// TOTAL = 8 stream credits.  A burst send spends 3 credits (they become
// "outstanding" bytes in flight); the collector returns exactly one credit
// per enabled cycle while anything is outstanding.  A deadline register is
// reloaded on every accepted burst and counts down otherwise; it must never
// expire while credits are still outstanding.
module credit_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_send,    // producer requests a burst
   output wire [3:0] o_n_iss,   // credits issued to the link (mod 16)
   output wire [3:0] o_n_ret,   // credits returned by the collector (mod 16)
    output wire       o_busy
);
    reg [3:0] avail;   // credits held by the sensor
    reg [3:0] outst;   // credits outstanding (in flight)
    reg [3:0] timer;   // completion deadline countdown
    reg       armed;   // sticky: set the first time a burst is accepted
   reg [3:0] n_iss;   // running tally of credits handed to the link
   reg [3:0] n_ret;   // running tally of credits given back

    initial avail = 4'd8;
    initial outst = 4'd0;
    initial timer = 4'd0;
    initial armed = 1'b0;
   initial n_iss = 4'd0;
   initial n_ret = 4'd0;

    wire send_ok = i_send && (avail >= 4'd3);
    wire retire  = (outst != 4'd0);

   // Deadline sizing.  The collector returns exactly one credit per enabled
   // cycle, so a burst needs (credits still in flight once it is issued)
   // cycles of link time plus one cycle of margin.  The in-flight figure is
   // read straight off the transfer ledger instead of re-deriving it.
   wire [3:0] led_outst = n_iss - n_ret;
   wire [3:0] deadline  = led_outst + 4'd4 - (retire ? 4'd1 : 4'd0);

    assign o_busy = (outst != 4'd0);
   assign o_n_iss = n_iss;
   assign o_n_ret = n_ret;

    always @(posedge clk) begin
        if (rst) begin
            avail <= 4'd8;
            outst <= 4'd0;
            timer <= 4'd0;
            armed <= 1'b0;
           n_iss <= 4'd0;
           n_ret <= 4'd0;
        end else if (i_ce) begin
            if (send_ok) begin
                // spend three credits, one may come back the same cycle
                avail <= avail - 4'd3 + (retire ? 4'd1 : 4'd0);
                outst <= outst + 4'd3 - (retire ? 4'd1 : 4'd0);
               timer <= deadline;      // fresh completion deadline
                armed <= 1'b1;          // sticky arm
            end else if (retire) begin
                avail <= avail + 4'd1;
                outst <= outst - 4'd1;
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end else begin
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end
           // transfer ledger: one entry per credit leaving, one per credit back
           if (send_ok) n_iss <= n_iss + 4'd3;
           if (retire)  n_ret <= n_ret + 4'd1;
        end
    end

    // Bounded response (safety form), scoped after the first accepted burst:
    // the deadline never expires while credits are still outstanding.
    always @(*)
        assert (!armed || !((timer == 4'd0) && (outst != 4'd0)));
endmodule

// Simple token-lexer FSM: binary-encoded states 0..4, encodings 5..7 unused.
module lex_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [1:0] cls,     // 0=escape/backslash, 1=alpha, 2=digit, 3=quote
    output reg  [2:0] st,
    output reg  [2:0] len
);
    localparam [2:0] S_IDLE  = 3'd0;
    localparam [2:0] S_IDENT = 3'd1;
    localparam [2:0] S_NUM   = 3'd2;
    localparam [2:0] S_STR   = 3'd3;
    localparam [2:0] S_ESC   = 3'd4;
    // An escape can now be taken from top level or from inside an identifier,
    // so S_ESC alone no longer says which token is being built: the state code
    // to resume with is held here while st == S_ESC.
    reg [2:0] esc_ret;

    wire [2:0] len_inc = (len == 3'd7) ? 3'd7 : (len + 3'd1);

    initial st  = S_IDLE;
    initial len = 3'd0;
    initial esc_ret = S_IDLE;

    always @(posedge clk) begin
        if (rst) begin
            st  <= S_IDLE;
            len <= 3'd0;
            esc_ret <= S_IDLE;
        end else if (ce) begin
            case (st)
                S_IDLE: begin
                    if (cls == 2'd1) begin
                        st  <= S_IDENT;
                        len <= 3'd1;
                    end else if (cls == 2'd2) begin
                        st  <= S_NUM;
                        len <= 3'd1;
                    end else if (cls == 2'd3) begin
                        st  <= S_STR;
                        len <= 3'd0;
                    end else begin
                        st      <= S_ESC;   // stray backslash: escaped char starts an identifier
                        esc_ret <= S_IDENT;
                        len     <= 3'd0;
                    end
                end
                S_IDENT: begin
                    if (cls == 2'd1 || cls == 2'd2) begin
                        st  <= S_IDENT;
                        len <= len_inc;
                    end else if (cls == 2'd0) begin
                        st      <= S_ESC;   // a\b is still a single identifier
                        esc_ret <= S_IDENT;
                        len     <= len;
                    end else begin
                        st  <= S_IDLE;
                        len <= 3'd0;
                    end
                end
                S_NUM: begin
                    if (cls == 2'd2) begin
                        st  <= S_NUM;
                        len <= len_inc;
                    end else begin
                        st  <= S_IDLE;
                        len <= 3'd0;
                    end
                end
                S_STR: begin
                    if (cls == 2'd3) begin
                        st  <= S_IDLE;   // closing quote ends the token
                        len <= 3'd0;
                    end else if (cls == 2'd0) begin
                        st  <= S_ESC;    // backslash: next char is literal
                        esc_ret <= S_STR;
                        len <= len;
                    end else begin
                        st  <= S_STR;
                        len <= len_inc;
                    end
                end
                S_ESC: begin
                    st  <= esc_ret;     // resume whatever token the escape interrupted
                    len <= len_inc;
                end
                default: begin
                    // unreachable encodings 5..7: recover to IDLE
                    st  <= S_IDLE;
                end
            endcase
        end
    end

    // P: in the IDLE state the accumulated token length is always zero.
    always @(*)
        if (st == 3'd0)
            assert (len == 3'd0);
endmodule

module gray_deadline_tracker (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       req,       // request pulse
    output wire [3:0] o_gray,
    output wire [3:0] o_bin,
    output wire [3:0] o_timer,
    output wire       o_busy,
    output wire       o_on_time
);
    // ---- gray counter with its binary shadow -------------------------
    reg [3:0] bin;
    reg [3:0] gray;

   // The binary->gray conversion is pipelined: the encoder runs one
   // increment ahead of the visible counter, so the output register has
   // no XOR chain in front of it.
   reg [3:0] gray_pre;   // in-flight gray code for bin+1

    // ---- bounded-response deadline machinery -------------------------
    reg [3:0] timer;      // countdown for the outstanding request
    reg       busy;       // request outstanding
    reg [3:0] goal_gray;  // gray code the counter should show at completion
    reg       armed;      // sticky: set the first time a request is seen

    reg       pv;         // past valid

    localparam [3:0] K = 4'd8;   // response bound

    initial begin
        bin       = 4'd0;
        gray      = 4'd0;
       gray_pre  = 4'd1;   // encoder prefilled with gray(bin+1)
        timer     = 4'd0;
        busy      = 1'b0;
        goal_gray = 4'd0;
        armed     = 1'b0;
        pv        = 1'b0;
    end

    wire [3:0] bin_nxt  = bin + 4'd1;
   wire [3:0] bin_ahead  = bin_nxt + 4'd1;
   wire [3:0] gray_ahead = bin_ahead ^ (bin_ahead >> 1);

    wire [3:0] goal_bin = bin + K;

    wire accept = i_ce && armed && req && !busy;
    wire tick   = i_ce && busy;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            // gray counter advances together with its binary shadow
            bin  <= bin_nxt;
           gray_pre <= gray_ahead;
           gray     <= gray_pre;

            // sticky arm: first request ever seen arms the monitor forever
            if (req) armed <= 1'b1;

            if (accept) begin
                busy      <= 1'b1;
                timer     <= K;
                goal_gray <= goal_bin ^ (goal_bin >> 1);
            end else if (busy) begin
                if (timer == 4'd1) begin
                    // completion lands exactly on the deadline tick
                    busy  <= 1'b0;
                    timer <= 4'd0;
                end else begin
                    timer <= timer - 4'd1;
                end
            end
        end
    end

    assign o_gray    = gray;
    assign o_bin     = bin;
    assign o_timer   = timer;
    assign o_busy    = busy;
    assign o_on_time = busy && (gray == goal_gray);

    // P: after the monitor is armed, while a request is outstanding the
    // deadline countdown may only move when the gray counter moves --
    // it can never silently run down toward expiry.
    always @(posedge clk)
        if (pv && armed && busy && $stable(gray))
            assert ($stable(timer));
endmodule

module credit_deadline (
    input  wire clk,
    input  wire i_ce,      // global enable: low => all state frozen
    input  wire rst,
    input  wire req,       // producer wants to spend a credit
    output wire grant,
    output wire busy
);
    localparam [2:0] TOTAL = 3'd4;   // configured credit pool

    // credits held by the producer, credits outstanding at the consumer
    reg [2:0] credits;
    reg [2:0] outst;
    // consumer needs two enabled cycles to retire one outstanding credit
    reg       svc;
    // bounded-response deadline countdown for the outstanding credits
    reg [3:0] timer;

    initial begin
        credits = 3'd4;
        outst   = 3'd0;
        svc     = 1'b0;
        timer   = 4'd0;
    end

    wire do_spend  = req && (credits != 3'd0);
    wire do_return = (outst != 3'd0) && (svc == 1'b1);

    assign grant = i_ce && do_spend;
    assign busy  = (outst != 3'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            if (rst) begin
                credits <= TOTAL;
                outst   <= 3'd0;
                svc     <= 1'b0;
                timer   <= 4'd0;
            end else begin
                // credit conservation: one token moves per event
                credits <= credits - (do_spend  ? 3'd1 : 3'd0)
                                   + (do_return ? 3'd1 : 3'd0);
                outst   <= outst   + (do_spend  ? 3'd1 : 3'd0)
                                   - (do_return ? 3'd1 : 3'd0);

                // two-cycle service phase per outstanding credit
                if (outst == 3'd0)
                    svc <= 1'b0;
                else
                    svc <= ~svc;

                // deadline budget: each spend buys 2 cycles, one cycle burnt
                timer <= timer - ((timer != 4'd0) ? 4'd1 : 4'd0)
                               + (do_spend ? 4'd2 : 4'd0);
            end
        end
    end

    // Bounded response (safety): the countdown must never expire while a
    // credit is still outstanding at the consumer.
    always @(posedge clk)
        if (outst != 3'd0)
            assert (timer != 4'd0);

   // Quiescence (safety): once the whole pool is back at the producer
   // there is nothing left at the consumer, so the service phase must be
   // idle and the deadline budget must be fully spent.
   always @(posedge clk)
       if (credits == TOTAL)
           assert ((timer == 4'd0) && (svc == 1'b0));

endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    // upstream credit: number of empty slots, maintained incrementally so the
    // full indication does not have to decode the valid flags
    reg [1:0] free;
    reg [7:0] d0, d1;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial free  = 2'd2;
    initial d0    = 8'h00;
    initial d1    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
    wire do_push = push && !v1;
    wire do_pop  = pop  &&  v0;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            free  <= 2'd2;
            d0    <= 8'h00;
            d1    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                    d0 <= din;
                    v0 <= 1'b1;
                end else begin
                    d1 <= din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
                d0 <= din;
            end

            count <= count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
            free  <= free  - (do_push ? 2'd1 : 2'd0) + (do_pop ? 2'd1 : 2'd0);
        end
    end

    assign dout    = d0;
    assign o_empty = !v0;
    assign o_full   = (free == 2'd0);
    assign o_count  = count;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);

    // ---- property: a push accepted last cycle must have gone into a buffer
    // ---- that both occupancy encodings called non-full
    always @(posedge clk)
        if (pv && $past(push) && !$past(v1))
            assert ($past(free) != 2'd0 && $past(count) != 2'd2);
endmodule

module alu_result_fifo (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] a,
    input  wire [7:0] b,
    input  wire [1:0] op,
    output reg  [7:0] o_data,
    output reg        o_zero,
    output reg        o_carry,
    output wire       full,
    output wire       empty,
output reg  [3:0] count,
output reg  [7:0] o_push_tally
);
    // ---- FIFO state: separate write/read pointers plus occupancy counter ----
    reg [2:0] wptr, rptr;
    reg [8:0] mem [0:7];   // {carry, result} slices
    integer i;

    initial begin
        wptr    = 3'd0;
        rptr    = 3'd0;
        count   = 4'd0;
        o_data  = 8'h00;
        o_zero  = 1'b1;
        o_carry = 1'b0;
o_push_tally = 8'h00;
        for (i = 0; i < 8; i = i + 1) mem[i] = 9'd0;
    end

    // ---- 8-bit ALU slice: add, subtract, and, or (carry out in bit 8) ----
    wire [8:0] w_sum = {1'b0, a} + {1'b0, b};
    wire [8:0] w_dif = {1'b0, a} - {1'b0, b};
    reg  [8:0] alu;
    always @(*) begin
        case (op)
            2'b00:   alu = w_sum;
            2'b01:   alu = w_dif;
            2'b10:   alu = {1'b0, a & b};
            default: alu = {1'b0, a | b};
        endcase
    end

    // ---- full/empty derived from the POINTERS, not from the counter ----
    assign full  = ((wptr - rptr) == 3'd5);
    assign empty = (wptr == rptr);

    wire do_push = i_ce && push && !full;
    wire do_pop  = i_ce && pop  && !empty;

    always @(posedge clk) begin
        if (do_push) begin
            mem[wptr] <= alu;
            wptr      <= wptr + 3'd1;
        end
        if (do_pop) begin
            o_data  <= mem[rptr][7:0];
            o_carry <= mem[rptr][8];
            o_zero  <= (mem[rptr][7:0] == 8'h00);
            rptr    <= rptr + 3'd1;
        end
        if (do_push && !do_pop)
            count <= count + 4'd1;
        else if (!do_push && do_pop)
            count <= count - 4'd1;
        else
            count <= count;
if (do_push)
    o_push_tally <= o_push_tally + 8'd1;
else if (do_pop)
    o_push_tally <= {o_push_tally[6:0], o_push_tally[7]};
    end

    // P: occupancy never exceeds the depth of 5, though the register holds 15
    always @(*) assert (count <= 4'd5);
endmodule

module pwm_prio_duty (
    input  wire       clk,
    input  wire       ce,
    input  wire [7:0] req,
    output reg        out_r,
    output reg        vld_r
);
    // ---------------- PWM state ----------------
    reg [2:0] cnt;        // period counter 0..7
   reg [2:0] per;        // programmed frame length minus one (frame = per+1)
    reg [3:0] duty;       // active duty value 0..8
    reg [3:0] hi_cnt;     // cycles spent high inside the current period
    reg       shadow_nz;  // shadow: the duty programmed for this period was nonzero
    reg       armed;      // scope: high until the first all-zero request load

    initial begin
        cnt       = 3'd0;
       per       = 3'd7;   // reset frame is the full eight cycles
        duty      = 4'd4;   // reset duty is nonzero
        hi_cnt    = 4'd0;
        shadow_nz = 1'b1;   // matches reset duty
        armed     = 1'b1;
        out_r     = 1'b0;
        vld_r     = 1'b0;
    end

    // ---------------- priority encoder over the request vector ----------------
    reg [2:0] idx;
    reg       vld;
    always @(*) begin
        vld = |req;
        if      (req[7]) idx = 3'd7;
        else if (req[6]) idx = 3'd6;
        else if (req[5]) idx = 3'd5;
        else if (req[4]) idx = 3'd4;
        else if (req[3]) idx = 3'd3;
        else if (req[2]) idx = 3'd2;
        else if (req[1]) idx = 3'd1;
        else             idx = 3'd0;
    end

    // requested duty: highest set index + 1, or 0 when no request
    wire [3:0] duty_req = vld ? ({1'b0, idx} + 4'd1) : 4'd0;

   // ---------------- frame-length programming ----------------
   // req[2:0] double as the frame-length code; a requested duty that does not
   // fit in the programmed frame is truncated to 100% of that frame
   wire [2:0] per_nxt  = req[2:0];
   wire [3:0] per_lim  = {1'b0, per_nxt} + 4'd1;
   wire [3:0] duty_nxt = (duty_req > per_lim) ? per_lim : duty_req;

    // ---------------- comparator: high exactly while cnt < duty ----------------
    wire out  = ({1'b0, cnt} < duty);
   wire wrap = (cnt == per);

    always @(posedge clk) begin
        if (ce) begin
           cnt   <= wrap ? 3'd0 : cnt + 3'd1;   // restarts at each boundary
            out_r <= out;          // registered output stage
            vld_r <= vld;
            if (wrap) begin
               per       <= per_nxt;
                // period boundary: latch the new duty and its shadow flag together
               duty      <= duty_nxt;
               shadow_nz <= (duty_nxt != 4'd0);
                hi_cnt    <= 4'd0;
               if (duty_nxt == 4'd0)
                    armed <= 1'b0; // the scope-closing event R
            end else begin
                hi_cnt <= hi_cnt + (out ? 4'd1 : 4'd0);
               // frame monitor: the high time can never outrun the frame it
               // belongs to; if it does, the latched flag no longer describes
               // the pulse being emitted, so drop it
               if (hi_cnt > {1'b0, per})
                   shadow_nz <= 1'b0;
            end
        end
    end

    // Precedence, in the "before the first zero-duty program" scope:
    // if the output has been high at all inside this period, then a nonzero
    // duty must have been recorded in the shadow flag earlier.
    always @(posedge clk)
        if (armed && hi_cnt != 4'd0)
            assert (shadow_nz);
endmodule

module phase_divider_pair (
    input  wire       clk,
    input  wire       ce,       // divider step enable; low = idle, all state held
    input  wire       resync,   // realigns both phase counters, retires the pristine scope
    output reg  [2:0] phase,    // primary phase counter, mod 5
    output reg  [2:0] cnt,      // skewed phase counter, mod 5, built 2 phases ahead
    output reg        en_load,  // divided enable: fires the cycle after phase wraps
    output reg        en_sample,// divided enable: fires the cycle after cnt wraps
    output reg        pristine  // high until the first resync has ever happened
);

    // Load/sample ledger: every load pulse and every sample pulse is logged
    // for the lifetime of the current alignment, so the buffer downstream can
    // account for the two divided enables it sees.
    reg  [3:0] n_load;   // count of load pulses issued
    reg  [3:0] n_samp;   // count of sample pulses issued

    // samples that do not have a matching load behind them yet
    wire [3:0] samp_ahead = n_samp - n_load;
    // a realignment can leave the ping-pong buffer starved; while the sample
    // side is two or more entries ahead, inject make-up load pulses
    wire       makeup     = (samp_ahead >= 4'd2);

    // The skewed counter is constructed 2 phases ahead of the primary phase
    // counter, so the two divided-enable pulses are interleaved by design.
    initial phase     = 3'd0;
    initial cnt       = 3'd2;
    initial en_load   = 1'b0;
    initial en_sample = 1'b0;
    initial pristine  = 1'b1;
    initial n_load    = 4'd0;
    initial n_samp    = 4'd0;

    always @(posedge clk) begin
        if (resync) begin
            // hard realignment: both phase counters are slammed to zero, which
            // destroys the constructed skew (and retires the pristine scope)
            phase     <= 3'd0;
            cnt       <= 3'd0;
            en_load   <= 1'b0;
            en_sample <= 1'b0;
            pristine  <= 1'b0;
            n_load    <= 4'd0;
            n_samp    <= 4'd0;
        end
        else if (ce) begin
            phase     <= (phase == 3'd4) ? 3'd0 : phase + 3'd1;
            cnt       <= (cnt   == 3'd4) ? 3'd0 : cnt   + 3'd1;
            // each divided enable pulses exactly when its phase counter wraps
            en_load   <= (phase == 3'd4) || makeup;
            en_sample <= (cnt   == 3'd4);
            // ledger entries are made as the pulses are issued
            n_load    <= n_load + (((phase == 3'd4) || makeup) ? 4'd1 : 4'd0);
            n_samp    <= n_samp + ((cnt == 3'd4) ? 4'd1 : 4'd0);
        end
    end

    // Absence: while the divider has never been resynced, the two divided
    // enables are never asserted in the same cycle.
    always @(posedge clk)
        if (pristine)
            assert (!(en_load && en_sample));

endmodule

module wdt_absence (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       arm,       // Q: opens the window
    input  wire       disarm,    // R: closes the window (may never arrive)
    input  wire       kick,      // pet the watchdog
    output reg  [3:0] cnt,
    output reg        expired,
    output reg        safe,
    output reg        armed
);
    localparam [3:0] LIMIT = 4'd10;  // timeout value
    localparam [3:0] WARN  = 4'd8;   // below this the timer is in the safe zone
    localparam [1:0] GRACE = LIMIT - WARN;  // warning-zone dwell before timeout
    reg [1:0] grace;                        // ticks elapsed since cnt hit WARN

    initial cnt     = 4'd0;
    initial expired = 1'b0;
    initial safe    = 1'b1;
    initial armed   = 1'b0;
    initial grace   = 2'd0;

    always @(posedge clk) begin
        if (i_ce) begin
            // window register: set by arm, cleared by disarm
            if (arm)
                armed <= 1'b1;
            else if (disarm)
                armed <= 1'b0;

            // the watchdog only runs inside the window
            if (armed) begin
                if (kick) begin
                    cnt     <= 4'd0;
                    grace   <= 2'd0;
                    expired <= 1'b0;
                    safe    <= 1'b1;
                end else if (cnt < WARN) begin
                    // pre-warning part of the interval is held in cnt
                    cnt     <= cnt + 4'd1;
                    safe    <= ((cnt + 4'd1) < WARN);
                end else if (grace < GRACE) begin
                    // once cnt has reached WARN the remaining ticks before the
                    // timeout are accumulated here, so the warning-zone dwell
                    // can be reported on its own
                    grace   <= grace + 2'd1;
                    expired <= ((grace + 2'd1) == GRACE);
                    safe    <= 1'b0;
                end
            end
        end
    end

    // P: once armed (and until disarmed, if ever), the timer can never report
    // both "expired" and "safe" at the same time.
    always @(*)
        if (armed)
            assert (!(expired && safe));
endmodule

// Histogram accumulator: four bin counters, one sample at a time,
// plus a running total-samples register and a shadow register that
// records the bin-0 count observed at the most recent bin-1 sample.
module histo_precedence (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire [1:0] i_bin,     // which bin the incoming sample lands in
    output wire [5:0] o_total,
    output wire [3:0] o_snap
);
    // bin counters
    reg [3:0] b0, b1, b2, b3;
    // total samples accumulated
    reg [5:0] total;
    // shadow register: value of bin 0 at the time of the last bin-1 sample
    reg [3:0] snap;
   // snapshot delivery pipeline: the bin-0 population read out alongside a
   // bin-1 sample only reaches the shadow register four cycles later, which
   // matches the read latency of the bin storage array.
   reg [3:0] sn1, sn2, sn3, sn4;
   reg       v1, v2, v3, v4;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;
   initial sn1   = 4'd0;
   initial sn2   = 4'd0;
   initial sn3   = 4'd0;
   initial sn4   = 4'd0;
   initial v1    = 1'b0;
   initial v2    = 1'b0;
   initial v3    = 1'b0;
   initial v4    = 1'b0;

    // value currently held by the selected bin
    wire [3:0] sel_val = (i_bin == 2'd0) ? b0 :
                         (i_bin == 2'd1) ? b1 :
                         (i_bin == 2'd2) ? b2 : b3;

    // a sample is committed only if the selected bin has headroom
    wire incr = i_ce && (sel_val != 4'd15);

    always @(posedge clk) begin
        if (incr) begin
            case (i_bin)
                2'd0: b0 <= b0 + 4'd1;
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
            endcase
            total <= total + 6'd1;
        end
    end
   // Snapshot pipeline: the read data shifts on every enabled cycle and the
   // valid bit travels with it, so the shadow register is loaded four cycles
   // after the bin-1 sample that requested the snapshot.
   always @(posedge clk) begin
       if (i_ce) begin
           sn1 <= b0;
           v1  <= incr && (i_bin == 2'd1);
           sn2 <= sn1;
           v2  <= v1;
           sn3 <= sn2;
           v3  <= v2;
           sn4 <= sn3;
           v4  <= v3;
           if (v4)
               snap <= sn4;
       end
   end

    assign o_total = total;
    assign o_snap  = snap;

    // Property (precedence): whenever a sample is being committed, the
    // bin-0 population recorded earlier in the shadow register must already
    // have been accounted for in the total-samples register.
    always @(posedge clk)
        if (incr)
            assert (total >= {2'b00, snap});
endmodule

// Serial debug-link pattern probe: detects the fixed 4-bit sync pattern 1101
// arriving MSB-first on i_bit, gated by the probe clock-enable i_ce.
// Match progress is tracked twice: as a binary progress counter (prog) and as
// an independently-updated one-hot shadow (hot). A 4-bit capture window (win)
// records the most recent bits seen.
module swd_sync_probe (
    input  wire clk,
    input  wire i_ce,      // probe strobe: low => link idle, all state frozen
    input  wire i_bit,     // serial bit from the debug pin
    output reg  detect     // registered pulse: full pattern just completed
);
    localparam [3:0] PATTERN = 4'b1101;

    reg [2:0] prog;        // match progress, 0..4 (4 == pattern length)
    reg [4:0] hot;         // one-hot shadow of the same progress
    reg [3:0] win;         // last four bits received, MSB = oldest
   reg [2:0] fill;        // bits clocked into win since reset, saturates at 4

    initial begin
        prog   = 3'd0;
        hot    = 5'b00001;
        win    = 4'b0000;
       fill   = 3'd0;
        detect = 1'b0;
    end

    // ---- next progress from the binary counter -------------------------
    reg [2:0] nprog;
    always @(*) begin
        case (prog)
            3'd0:    nprog = i_bit ? 3'd1 : 3'd0;              // want 1
            3'd1:    nprog = i_bit ? 3'd2 : 3'd0;              // want 1
            3'd2:    nprog = i_bit ? 3'd2 : 3'd3;              // want 0
            3'd3:    nprog = i_bit ? 3'd4 : 3'd0;              // want 1
            3'd4:    nprog = i_bit ? 3'd2 : 3'd0;              // overlap "1"
            default: nprog = prog;
        endcase
    end

    // ---- next progress from the one-hot shadow (own state only) --------
    reg [4:0] nhot;
    always @(*) begin
        case (hot)
            5'b00001: nhot = i_bit ? 5'b00010 : 5'b00001;
            5'b00010: nhot = i_bit ? 5'b00100 : 5'b00001;
            5'b00100: nhot = i_bit ? 5'b00100 : 5'b01000;
            5'b01000: nhot = i_bit ? 5'b10000 : 5'b00001;
            5'b10000: nhot = i_bit ? 5'b00100 : 5'b00001;
            default:  nhot = 5'b00001;
        endcase
    end

   // ---- capture-window fill level -------------------------------------
   // Counts probe strobes since reset so the power-up contents of win can
   // never be reported as a frame.
   reg [2:0] nfill;
   always @(*) nfill = (fill == 3'd4) ? 3'd4 : fill + 3'd1;

    always @(posedge clk) begin
        if (i_ce) begin
            prog   <= nprog;
            hot    <= nhot;
            win    <= {win[2:0], i_bit};
           fill   <= nfill;
           // report a match only once the window holds four real bits
           detect <= (nprog == 3'd4) && (nfill == 3'd4);
        end
    end

    // ---- property: two universal relations, globally --------------------
    always @(posedge clk) begin
        assert (detect == hot[4]);
        if (prog == 3'd4)
            assert (win == PATTERN);
    end

   // ---- property: terminal progress implies a fully loaded window ------
   always @(posedge clk)
       if (prog == 3'd4)
           assert (fill == 3'd4);
endmodule

module disasm_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       kick,      // an instruction was successfully decoded
    output reg  [3:0] count,     // cycles since last kick
    output reg        expired,   // decoder hung: limit was reached
    output reg        healthy    // plenty of slack left
);
    localparam [3:0] LIMIT = 4'd10;   // timeout
    localparam [3:0] WARN  = 4'd8;    // slack threshold

   // saved context of the decode channel that is parked while the other
   // one owns the shared pipeline slot
   reg  [3:0] count_sh;
   reg        exp_sh;

    initial begin
        count   = 4'd0;
        expired = 1'b0;
        healthy = 1'b1;
       count_sh = 4'd0;
       exp_sh   = 1'b0;
    end

    // next value of the stall counter: kick clears it, otherwise it
    // counts up and saturates at the timeout limit
    wire [3:0] nxt = kick              ? 4'd0  :
                     (count == LIMIT)  ? LIMIT :
                                         count + 4'd1;

   // the slot is handed to the other channel when the active one makes
   // progress, and is preempted once the active one has clearly hung
   wire swap = kick || (count == LIMIT);

    always @(posedge clk) begin
        if (rst) begin
            count   <= 4'd0;
           count_sh <= 4'd0;
           exp_sh   <= 1'b0;
            expired <= 1'b0;
            healthy <= 1'b1;
        end else if (i_ce) begin
           if (swap) begin
               count    <= count_sh;         // resume the parked channel
               count_sh <= nxt;              // park the current stall count
               exp_sh   <= (nxt == LIMIT);   // remember if it hung
           end else begin
               count    <= nxt;
           end
           // sticky per channel: a kick only clears the channel that
           // currently owns the slot
           expired <= (nxt == LIMIT) || exp_sh;
           healthy <= (nxt < WARN) && (count_sh < WARN);
        end
    end

    // P: the timeout flag and the slack flag are never raised together
    always @(posedge clk)
        if (expired)
            assert (!healthy);
endmodule

module deb_evt_fifo (
    input  wire clk,
    input  wire i_ce,      // sample enable: low freezes all state
    input  wire raw,       // raw (noisy) button level
    input  wire pop,       // consumer request
    output wire empty,
    output wire full,
    output reg  o_level    // last popped debounced level
);
    // ---- debouncer: saturating stability counter ----
    reg [1:0] stab;
    reg       deb;

    // ---- event FIFO: pointers + occupancy ----
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg [1:0] tail;        // shadow: write pointer snapshot taken at the last push
    reg       mem [0:3];

   // ---- event ledger: free-running push/pop transfer counters ----
   // flag generation is taken from the ledger difference so that empty/full
   // are a direct function of logged transfers rather than of the occupancy
   // accumulator; the counters wrap naturally at their width.
   reg [2:0] n_push, n_pop;
   wire [2:0] occ = n_push - n_pop;   // outstanding entries, mod 8

    // ---- scope register: high until the FIFO has ever been full ----
    reg       never_full;

    // ---- past-valid ----
    reg       pv;

    initial begin
        stab = 2'd0; deb = 1'b0;
        wptr = 2'd0; rptr = 2'd0; count = 3'd0;
        tail = 2'd0;
       n_push = 3'd0; n_pop = 3'd0;
        never_full = 1'b1;
        pv = 1'b0;
        o_level = 1'b0;
        mem[0] = 1'b0; mem[1] = 1'b0; mem[2] = 1'b0; mem[3] = 1'b0;
    end

   assign empty = (occ == 3'd0);
   assign full  = (occ == 3'd4);

    // a debounced edge is committed once raw has disagreed with deb for 3 samples
    wire deb_commit = (raw != deb) && (stab == 2'd2);

    wire do_push = i_ce && deb_commit && !full;
    wire do_pop  = i_ce && pop && !empty;

    always @(posedge clk) begin
        if (i_ce) begin
            if (raw != deb) begin
                if (stab == 2'd2) stab <= 2'd0;
                else              stab <= stab + 2'd1;
            end else begin
                stab <= 2'd0;
            end
            if (deb_commit) deb <= raw;

            if (do_push) begin
                mem[wptr] <= raw;
                wptr      <= wptr + 2'd1;
                tail      <= wptr + 2'd1;
            end

            if (do_pop) begin
                o_level <= mem[rptr];
                rptr    <= rptr + 2'd1;
            end

           // log both sides of every completed transfer
           if (do_push) n_push <= n_push + 3'd1;
           if (do_pop)  n_pop  <= n_pop  + 3'd1;

            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase

            if (count == 3'd4) never_full <= 1'b0;
        end
        pv <= 1'b1;
    end

    // Precedence, before-first-full scope, stated about the previous cycle:
    // if the queue has just been drained empty by a pop, the read pointer must
    // have reached the write-pointer snapshot recorded at the earlier push.
    always @(posedge clk)
        if (pv && never_full && (count == 3'd0) && $past(do_pop))
            assert (rptr == $past(tail));
endmodule

module uart_rx_onehot (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // baud tick / enable: low freezes all state
    input  wire       rx,
    input  wire       take,    // consumer accepts the byte parked in STOP
    output wire [7:0] o_data,
    output wire       o_ferr,
    output wire       o_busy
);
    // one-hot phase FSM:
    //   st[0]      IDLE
    //   st[1]      START bit
    //   st[2..9]   data bits D0..D7 (one state per bit)
    //   st[10]     STOP bit / byte parked
    reg [10:0] st;
    reg [3:0]  nbits;   // frame phase index: 0..10 only, though 4 bits hold 15
   reg [3:0]  dcnt;    // data bits already shifted into sr this frame: 0..8
    reg [7:0]  sr;
    reg        ferr;
    reg        pv;

    initial st    = 11'b000_0000_0001;
    initial nbits = 4'd0;
   initial dcnt  = 4'd0;
    initial sr    = 8'h00;
    initial ferr  = 1'b0;
    initial pv    = 1'b0;

    wire idle   = st[0];
    wire startb = st[1];
    wire datab  = |st[9:2];
    wire stopb  = st[10];

    wire start_det = ce && idle   && !rx;   // falling edge of the line
    wire adv       = ce && (startb || datab);
    wire done      = ce && stopb  && take;

    // next-state decode: every source bit drives exactly one destination bit
    reg [10:0] nxt;
    always @(*) begin
        nxt      = 11'd0;
        nxt[0]   = (st[0] && rx) || (st[10] && take);
        nxt[1]   = st[0] && !rx;
        nxt[2]   = st[1];
        nxt[3]   = st[2];
        nxt[4]   = st[3];
        nxt[5]   = st[4];
        nxt[6]   = st[5];
        nxt[7]   = st[6];
        nxt[8]   = st[7];
        nxt[9]   = st[8];
        nxt[10]  = st[9] || (st[10] && !take);
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            st    <= 11'b000_0000_0001;
            nbits <= 4'd0;
           dcnt  <= 4'd0;
            sr    <= 8'h00;
            ferr  <= 1'b0;
        end else if (ce) begin
            st <= nxt;
            if (start_det)     nbits <= 4'd1;   // load: start bit is phase 1
            else if (done)     nbits <= 4'd0;
            else if (adv)      nbits <= nbits + 4'd1;
            if (datab)         sr    <= {rx, sr[7:1]};
           if (start_det || done) dcnt <= 4'd0;
           else if (datab)        dcnt <= dcnt + 4'd1;
           if (done)          ferr  <= !rx || (dcnt != 4'd8); // stop bit high and a full byte
        end
    end

    assign o_data = sr;
    assign o_ferr = ferr;
    assign o_busy = !idle;

    // P: the phase counter changes on every phase change, and it never counts
    // past the 10 phases of a frame -- stated as a no-change check.
    always @(posedge clk)
        if (pv && $stable(nbits))
            assert ($stable(st) && nbits <= 4'd10);

   // P2: dcnt lags the phase index by the START phase plus the one-cycle
   // capture lag, so inside a frame it is always nbits-2 bits deep.
   always @(posedge clk)
       if (pv && o_busy && nbits >= 4'd2)
           assert (dcnt == nbits - 4'd2);
endmodule

module token_bucket_deadline (
    input  wire clk,
    input  wire i_ce,
    input  wire req,
    output wire grant,
    output wire expired
);
    // burst size of the bucket and the response deadline for one request
    localparam [2:0] BURST   = 3'd4;
    localparam [3:0] TIMEOUT = 4'd6;

    reg [2:0] tokens;    // token bucket, capped at BURST
    reg [1:0] tick_cnt;   // refill timer, counts down, tick at zero
    reg       pending;    // window register: set by accepted request, cleared by grant
    reg [3:0] deadline;   // bounded-response countdown for the pending request
    reg       refill_q;  // staged refill: a tick is captured here and applied to the bucket next cycle

    initial tokens   = BURST;
    initial tick_cnt = 2'd3;
    initial pending  = 1'b0;
    initial deadline = 4'd0;
    initial refill_q = 1'b0;

    wire tick     = (tick_cnt == 2'd0);
    wire do_grant = pending && (tokens != 3'd0);
    wire do_refill = refill_q && (tokens < BURST);

    assign grant   = i_ce && do_grant;
    assign expired = pending && (deadline == 4'd0);

    // refill timer
    always @(posedge clk) if (i_ce)
        tick_cnt <= tick ? 2'd3 : (tick_cnt - 2'd1);

    // refill request is registered one cycle before it reaches the bucket
    always @(posedge clk) if (i_ce)
        refill_q <= tick;

    // bucket: drains on a grant, refills on a tick, saturates at BURST
    always @(posedge clk) if (i_ce) begin
        if (do_grant && do_refill)
            tokens <= tokens;                 // one out, one in
        else if (do_grant)
            tokens <= tokens - 3'd1;
        else if (do_refill)
            tokens <= tokens + 3'd1;
    end

    // request window and its countdown
    always @(posedge clk) if (i_ce) begin
        if (do_grant)
            pending <= 1'b0;
        else if (pending)
            deadline <= deadline - 4'd1;
        else if (req) begin
            pending  <= 1'b1;
            deadline <= TIMEOUT;
        end
    end

    // P: inside the request window the countdown never expires
    always @(posedge clk)
        if (pending) assert (deadline != 4'd0);
endmodule

module elastic_profile_buf (
    input wire       i_clk,
    input wire       i_rst,
    input wire       i_push,
    input wire       i_pop,
    input wire [7:0] i_data,
    output wire      o_valid,
    output wire      o_full,
    output wire [7:0] o_data,
    output wire [2:0] o_count
);
    // Two-entry elastic buffer holding profiling samples.
    // Entry 0 is the head, entry 1 is the tail.  v0/v1 are the head/tail
    // occupancy flags; count is a separate occupancy register that is
    // maintained in parallel with the flags.
    reg       v0, v1;
    reg [7:0] d0, d1;
    reg [2:0] count;
   // Skid slot behind the tail.  o_full is raised as soon as the tail fills,
   // but one upstream beat may already be in flight, so it is absorbed here
   // and handed to the tail as soon as a pop frees it.
   reg       s_v;
   reg [7:0] s_d;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;
   initial s_v   = 1'b0;
   initial s_d   = 8'h00;

    // "full" is decided purely by the tail flag
    wire w_full  = v1;
    wire do_push = i_push && !w_full;
    wire do_pop  = i_pop  && v0;
   // a beat arriving while full is taken by the skid slot, unless a pop is
   // freeing the tail this cycle, in which case it goes straight to the tail
   wire do_skid = i_push && w_full && !s_v && !do_pop;

    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
           s_v   <= 1'b0;
           s_d   <= 8'h00;
        end else if (do_push && do_pop) begin
            // head leaves, new sample becomes the head: occupancy unchanged
            d0    <= i_data;
        end else if (do_push) begin
            if (!v0) begin
                v0 <= 1'b1;
                d0 <= i_data;
            end else begin
                v1 <= 1'b1;
                d1 <= i_data;
            end
            count <= count + 3'd1;
        end else if (do_pop) begin
            // tail slides down into the head slot
           v0 <= v1;
           d0 <= d1;
           if (s_v) begin
               // the parked skid sample takes the freed tail slot
               v1    <= 1'b1;
               d1    <= s_d;
               s_v   <= 1'b0;
               count <= count - 3'd1;
           end else if (i_push) begin
               // we reported full, so this beat lands in the freed tail
               v1 <= 1'b1;
               d1 <= i_data;
           end else begin
               v1    <= 1'b0;
               count <= count - 3'd1;
           end
       end else if (do_skid) begin
           s_v   <= 1'b1;
           s_d   <= i_data;
           count <= count + 3'd1;
       end
        // i_push = i_pop = 0 : the buffer idles, all state held
    end

    assign o_valid = v0;
    assign o_full  = w_full;
    assign o_data  = d0;
    assign o_count = count;

    // P: whenever the buffer is not reporting full, the recorded occupancy
    // is at most one sample (the 3-bit register would allow up to 7).
    always @(posedge i_clk)
        if (!w_full)
            assert (count <= 3'd1);
endmodule

module gfx_frame_fsm (
    input  wire clk,
    input  wire i_reset,
    input  wire i_ce,
    input  wire i_start,
    output wire o_vsync,
    output wire [2:0] o_state
);
    // binary-encoded frame pipeline states; 5,6,7 are unreachable encodings
    localparam [2:0] S_IDLE    = 3'd0;
    localparam [2:0] S_CLEAR   = 3'd1;
    localparam [2:0] S_DRAW    = 3'd2;
    localparam [2:0] S_BLIT    = 3'd3;
    localparam [2:0] S_PRESENT = 3'd4;
   // overlay plane pipeline stages (shares the framebuffer with the frame pipeline)
   localparam [1:0] OV_IDLE = 2'd0;
   localparam [1:0] OV_CLR  = 2'd1;
   localparam [1:0] OV_FILL = 2'd2;
   localparam [1:0] OV_SWAP = 2'd3;

    reg [2:0] state;
    reg [1:0] draw_cnt;
    reg       cleared_seen;   // shadow: framebuffer was cleared this frame
   reg [1:0] ov_state;      // overlay plane pipeline
   reg       ov_pend;       // overlay refresh owed after the last frame

    initial state        = S_IDLE;
    initial draw_cnt     = 2'd0;
    initial cleared_seen = 1'b0;
   initial ov_state     = OV_IDLE;
   initial ov_pend      = 1'b0;

    wire draw_done = (draw_cnt == 2'd3);
   // framebuffer arbitration: the frame pipeline may only start a new frame
   // when no overlay refresh is running or owed
   wire fb_free = (ov_state == OV_IDLE) && !ov_pend;

    always @(posedge clk) begin
        if (i_reset) begin
            state        <= S_IDLE;
            draw_cnt     <= 2'd0;
            cleared_seen <= 1'b0;
           ov_state     <= OV_IDLE;
           ov_pend      <= 1'b0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                   if (i_start && fb_free) begin
                        state    <= S_CLEAR;
                        draw_cnt <= 2'd0;
                    end
                end
                S_CLEAR: begin
                    // the clear pass is the "earlier event" the shadow records
                    cleared_seen <= 1'b1;
                    state        <= S_DRAW;
                end
                S_DRAW: begin
                    if (draw_done)
                        state <= S_BLIT;
                    else
                        draw_cnt <= draw_cnt + 2'd1;
                end
                S_BLIT: begin
                    state <= S_PRESENT;
                end
                S_PRESENT: begin
                    state        <= S_IDLE;
                    draw_cnt     <= 2'd0;
                    cleared_seen <= 1'b0;
                   ov_pend      <= 1'b1;   // overlay gets the buffer next
                end
                default: begin
                    // encodings 5/6/7 never occur by construction; the
                    // synthesised decoder folds them onto the present stage
                    state <= S_PRESENT;
                end
            endcase

           // Overlay plane pipeline: same shape as the frame pipeline above,
           // but it borrows the framebuffer and the shared pass counter, so it
           // only runs in the gap between frames.
           case (ov_state)
               OV_IDLE: begin
                   if (ov_pend && state == S_IDLE) begin
                       ov_state <= OV_CLR;
                       ov_pend  <= 1'b0;
                   end
               end
               OV_CLR: begin
                   ov_state <= OV_FILL;
                   draw_cnt <= 2'd0;
               end
               OV_FILL: begin
                   // overlay writes land on the shared framebuffer, so the
                   // recorded clear no longer describes its contents
                   cleared_seen <= 1'b0;
                   if (draw_cnt == 2'd1)
                       ov_state <= OV_SWAP;
                   else
                       draw_cnt <= draw_cnt + 2'd1;
               end
               OV_SWAP: begin
                   ov_state <= OV_IDLE;
                   draw_cnt <= 2'd0;
               end
           endcase
        end
    end

    assign o_vsync = (state == S_PRESENT);
    assign o_state = state;

    // Precedence, global: presenting a frame implies the clear pass happened earlier
    always @(posedge clk)
        if (state == S_PRESENT)
            assert (cleared_seen);
endmodule

module dma_burst_engine (
    input  wire       clk,
    input  wire       i_ce,     // idle condition: low freezes all state
    input  wire       start,    // Q: opens the status window
    input  wire [3:0] len,      // requested burst length (beats)
    input  wire       ack,      // R: host acknowledges, closes the window
    output reg        busy,
    output reg  [3:0] beats
);
    // shadow register: records the length that was requested earlier
    reg [3:0] req_len;
    // beats actually pushed out so far in the current burst
    reg [3:0] done_cnt;
    // window register: set by start, cleared by ack
    reg       armed;
   // beats deferred past the 8-beat hardware burst limit of the current request
   reg [3:0] resid;

    initial busy     = 1'b0;
    initial beats    = 4'd0;
    initial req_len  = 4'd0;
    initial done_cnt = 4'd0;
    initial armed    = 1'b0;
   initial resid    = 4'd0;

    wire accept = start && !armed && (len != 4'd0);
   // the fabric accepts at most 8 beats in one burst; the rest is deferred
   wire [3:0] chunk = (len > 4'd8) ? 4'd8 : len;

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
               beats    <= chunk;
                req_len  <= len;      // shadow capture of the earlier event
               resid    <= len - chunk;
                done_cnt <= 4'd0;
                busy     <= 1'b1;
                armed    <= 1'b1;
            end else if (busy) begin
               beats    <= (beats == 4'd1 && resid != 4'd0) ? resid : beats - 4'd1;
                done_cnt <= done_cnt + 4'd1;
               busy     <= (beats != 4'd1) || (resid != 4'd0);
               resid    <= (beats == 4'd1) ? 4'd0 : resid;
            end else if (armed && ack) begin
                armed    <= 1'b0;
            end
        end
    end

    // P, part 1: inside the window, while beats remain the burst cannot yet have
    // delivered everything that was requested earlier.
    always @(posedge clk)
        if (armed && busy)
            assert (done_cnt < req_len);

    // P, part 2: inside the window, once the engine is no longer busy the
    // delivered count must exactly match the earlier requested length.
    always @(posedge clk)
        if (armed && !busy)
            assert (done_cnt == req_len);

   // P, part 3: inside the window, while a deferred chunk is still queued the
   // beats already pushed plus the beats still held back must leave headroom
   // inside the length that was requested earlier.
   always @(posedge clk)
       if (armed && resid != 4'd0)
           assert (({1'b0,done_cnt} + {1'b0,resid}) < {1'b0,req_len});
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

    reg [3:0] nxt;

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
            else if (nxt == S_ROUTE)
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);
endmodule

module pcb_pool_top (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] ce,
    input  wire [5:0] start,
    input  wire [5:0] route_ok,
    input  wire [5:0] ack,
    output reg  [3:0] pool,     // free router-engine seats
    output reg  [5:0] hold,     // per-board seat ownership
    output wire [5:0] window    // per-board routing window (tracking)
);
    // Six board flows share a pool of six router/DRC engine seats.
    localparam [3:0] TOTAL = 4'd6;

    wire [3:0] s0, s1, s2, s3, s4, s5;
    wire [7:0] m0, m1, m2, m3, m4, m5;
    wire       t0, t1, t2, t3, t4, t5;

    wire h0 = hold[0];
    wire h1 = hold[1];
    wire h2 = hold[2];
    wire h3 = hold[3];
    wire h4 = hold[4];
    wire h5 = hold[5];

    assign window = {t5, t4, t3, t2, t1, t0};

    pcb_flow_fsm u0 (.clk(clk), .rst(rst), .ce(ce[0]), .start(start[0]),
                     .route_ok(route_ok[0]), .ack(ack[0]),
                     .state(s0), .mirror(m0), .tracking(t0));
    pcb_flow_fsm u1 (.clk(clk), .rst(rst), .ce(ce[1]), .start(start[1]),
                     .route_ok(route_ok[1]), .ack(ack[1]),
                     .state(s1), .mirror(m1), .tracking(t1));
    pcb_flow_fsm u2 (.clk(clk), .rst(rst), .ce(ce[2]), .start(start[2]),
                     .route_ok(route_ok[2]), .ack(ack[2]),
                     .state(s2), .mirror(m2), .tracking(t2));
    pcb_flow_fsm u3 (.clk(clk), .rst(rst), .ce(ce[3]), .start(start[3]),
                     .route_ok(route_ok[3]), .ack(ack[3]),
                     .state(s3), .mirror(m3), .tracking(t3));
    pcb_flow_fsm u4 (.clk(clk), .rst(rst), .ce(ce[4]), .start(start[4]),
                     .route_ok(route_ok[4]), .ack(ack[4]),
                     .state(s4), .mirror(m4), .tracking(t4));
    pcb_flow_fsm u5 (.clk(clk), .rst(rst), .ce(ce[5]), .start(start[5]),
                     .route_ok(route_ok[5]), .ack(ack[5]),
                     .state(s5), .mirror(m5), .tracking(t5));

    // A board wants a seat while its window is armed; it gives the seat back
    // on its next enabled cycle after the export has been acknowledged.
    wire [5:0] req = window & ~hold & ce;
    wire [5:0] rel = ~window &  hold & ce;

    // Fixed-priority arbiter: at most one seat handed out per cycle.
    wire       have_credit = (pool != 4'd0);
    wire [5:0] pri;
    assign pri[0] = req[0];
    assign pri[1] = req[1] & ~req[0];
    assign pri[2] = req[2] & ~(|req[1:0]);
    assign pri[3] = req[3] & ~(|req[2:0]);
    assign pri[4] = req[4] & ~(|req[3:0]);
    assign pri[5] = req[5] & ~(|req[4:0]);

    wire [5:0] gnt     = have_credit ? pri : 6'b0;
    wire       gnt_any = |gnt;

    wire [2:0] rel_cnt = {2'b0, rel[0]} + {2'b0, rel[1]} + {2'b0, rel[2]} +
                         {2'b0, rel[3]} + {2'b0, rel[4]} + {2'b0, rel[5]};

    initial begin
        pool = TOTAL;
        hold = 6'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
            hold <= 6'd0;
        end else begin
            hold <= (hold | gnt) & ~rel;
            pool <= pool - {3'b0, gnt_any} + {1'b0, rel_cnt};
        end
    end

    // Pool property: if no seat is free, every board must be holding one.
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 && h1 && h2 && h3 && h4 && h5);
endmodule

module seq_detect_1011 (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output wire       match,
    output wire [3:0] hits
);
    // fixed pattern, MSB first: 1 0 1 1
    localparam [3:0] PAT = 4'b1011;

    // match-progress register: number of leading pattern bits matched so far,
    // never exceeds the pattern length (4)
    reg [2:0] prog;
    // shadow register: records that progress 3 (pattern prefix 101) was
    // observed at some earlier cycle
    reg       saw_p3;
    // saturating count of completed pattern matches consumed
    reg [3:0] match_count;
   // commit-stage flag: a detected match is posted here and lands in the
   // counter on the next enabled cycle, keeping the counter adder off the
   // detector's critical path
   reg       cmt_vld;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;
   initial cmt_vld     = 1'b0;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
    wire       restart  = (din == PAT[3]) ? 1'b1 : 1'b0;

    assign match = (prog == 3'd4);
    assign hits  = match_count;

    always @(posedge clk) begin
        if (rst) begin
            prog        <= 3'd0;
            saw_p3      <= 1'b0;
            match_count <= 4'd0;
           cmt_vld     <= 1'b0;
        end else if (ce) begin
            // shadow bit latches the earlier occurrence of progress 3
            saw_p3 <= saw_p3 | (prog == 3'd3);
           // post a credit for a completed match; retire the credit posted
           // by the previous enabled cycle
           cmt_vld <= (prog == 3'd4);
           if (cmt_vld)
               match_count <= (match_count == 4'd15) ? 4'd15 : match_count + 4'd1;


            if (prog == 3'd4) begin
                // consume the completed match, then begin a fresh scan
                prog        <= restart ? 3'd1 : 3'd0;
            end else if (din == exp_bit) begin
                prog <= prog + 3'd1;
            end else begin
                prog <= restart ? 3'd1 : 3'd0;
            end
        end
    end

    // Precedence, global: any counted match must have been preceded by the
    // pattern prefix reaching progress 3.
    assert property (match_count == 4'd0 || saw_p3);
endmodule

module sb_window (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_issue,
    input  wire i_retire,
    input  wire i_open,
    input  wire i_close,
    output wire o_full,
    output wire o_empty,
output wire o_mon,
output reg [3:0] o_act
);
    localparam [3:0] WINDOW = 4'd8;

    // transaction scoreboard: issued count, retired count, and a redundant
    // outstanding-transaction register maintained in parallel
    reg [4:0] iss;
    reg [4:0] ret;
    reg [3:0] out_r;

    // registered status flags (one cycle stale, updated only when enabled)
    reg       full_q;
    reg       empty_q;

    // monitoring window: opened by i_open, closed by i_close
    reg       mon;

    reg       pv;

    initial iss     = 5'd0;
    initial ret     = 5'd0;
    initial out_r   = 4'd0;
    initial full_q  = 1'b0;
    initial empty_q = 1'b1;
    initial mon     = 1'b0;
    initial pv      = 1'b0;
initial o_act   = 4'd0;

    wire acc_iss = i_ce && i_issue  && (out_r <  WINDOW);
    wire acc_ret = i_ce && i_retire && (out_r != 4'd0);

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            iss   <= 5'd0;
            ret   <= 5'd0;
            out_r <= 4'd0;
o_act <= 4'd0;
        end else begin
            if (acc_iss) iss <= iss + 5'd1;
            if (acc_ret) ret <= ret + 5'd1;
            if (acc_iss && !acc_ret)
                out_r <= out_r + 4'd1;
            else if (!acc_iss && acc_ret)
                out_r <= out_r - 4'd1;
if (i_ce && (i_open || i_close))
    o_act <= o_act + 4'd1;
        end

    always @(posedge clk)
        if (i_rst) begin
            full_q  <= 1'b0;
            empty_q <= 1'b1;
        end else if (i_ce) begin
            full_q  <= (out_r == WINDOW);
            empty_q <= (iss == ret);
        end

    always @(posedge clk)
        if (i_rst)
            mon <= 1'b0;
        else if (i_ce) begin
            if (i_close)
                mon <= 1'b0;
            else if (i_open)
                mon <= 1'b1;
        end

    assign o_full  = full_q;
    assign o_empty = empty_q;
    assign o_mon   = mon;

    // P: inside an open monitoring window, when the full flag rises the
    // scoreboard must not simultaneously report empty
    always @(posedge clk)
        if (pv && mon && $rose(full_q))
            assert (!empty_q);
endmodule

// Gray-coded write pointer crossing into a destination domain through a
// two-flop synchronizer, with a shadow binary pipeline kept alongside the
// synchronizer stages and a monitor that records the Hamming distance between
// the two most recent samples of the pointer.
module gray_cdc_skew_monitor (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable / idle
    input  wire       i_incr,    // source pointer advance
    output reg        armed,     // sticky: a pointer change has been observed
    output reg  [2:0] last_delta // bits differing between the last two samples
);

    // source-domain binary pointer and its gray encoding
    reg  [3:0] wbin;
    wire [3:0] wgray = wbin ^ (wbin >> 1);

    // two-flop synchronizer carrying the gray pointer
    reg  [3:0] sync1, sync2;

   // second consumer's synchronizer chain onto the same gray pointer
   reg  [3:0] s1b, s2b;

    // shadow binary pipeline, one stage per synchronizer flop
    reg  [3:0] b1, b2;
   reg  [3:0] b1b, b2b;

   // round-robin refresh phase: 0 refreshes chain A, 1 refreshes chain B.
   // Pointer advances are throttled to phase 0 so that either chain sees at
   // most one gray transition between two of its own samples.
   reg        phase;

    initial begin
        wbin       = 4'd0;
        sync1      = 4'd0;
        sync2      = 4'd0;
        b1         = 4'd0;
        b2         = 4'd0;
       s1b        = 4'd0;
       s2b        = 4'd0;
       b1b        = 4'd0;
       b2b        = 4'd0;
       phase      = 1'b0;
        armed      = 1'b0;
        last_delta = 3'd0;
    end

    // combinational Hamming distance between the two synchronizer stages
    wire [3:0] xr = sync1 ^ sync2;
    wire [2:0] delta = {2'b00, xr[0]} + {2'b00, xr[1]} +
                       {2'b00, xr[2]} + {2'b00, xr[3]};

   // the same distance measure for the second chain
   wire [3:0] xrb = s1b ^ s2b;
   wire [2:0] delta_b = {2'b00, xrb[0]} + {2'b00, xrb[1]} +
                        {2'b00, xrb[2]} + {2'b00, xrb[3]};

   // one skew monitor is shared by both chains; it reports whichever chain
   // was refreshed on this phase
   wire [2:0] delta_mux = phase ? delta_b : delta;
   wire       skew_mux  = phase ? (s1b != s2b) : (sync1 != sync2);

    always @(posedge clk) begin
        if (i_ce) begin
            // source pointer
           wbin  <= wbin + ((i_incr && !phase) ? 4'd1 : 4'd0);

            // synchronizer chain
           if (!phase) begin
               sync1 <= wgray;
               sync2 <= sync1;
           end else begin
               s1b   <= wgray;
               s2b   <= s1b;
           end

            // shadow binary chain, structurally parallel to the chain above
           if (!phase) begin
               b1    <= wbin;
               b2    <= b1;
           end else begin
               b1b   <= wbin;
               b2b   <= b1b;
           end

            // monitor
           last_delta <= delta_mux;
           phase      <= ~phase;

            // Q: first time the two stages disagree, i.e. a pointer update is
            // in flight through the synchronizer.  Sticky, never cleared.
           if (skew_mux)
                armed <= 1'b1;
        end
    end

    // P: once a pointer change has been seen, every recorded sample-to-sample
    // distance is at most one bit (gray-code single-bit transition).
    assert property (!armed || last_delta <= 3'd1);

endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       issue,     // new operation issued this advance
    output wire       o_retire,  // fixed-latency result leaving the unit
    output wire [2:0] o_occ
);
// 3-deep shift register feeding a registered writeback stage:
// bit k = op issued k advances ago
reg [2:0] pipe;
    // occupancy: incremented on issue, decremented when the tail drains
    reg [2:0] occ;
    // sticky arm: set the first time an operation is ever issued
    reg       armed;
// registered result stage: the final latency slot lives here
reg       wb;
// second beat of the narrow result bus; the pipe cannot advance during it
reg       beat;

initial pipe  = 3'b000;
    initial occ   = 3'd0;
    initial armed = 1'b0;
initial wb    = 1'b0;
initial beat  = 1'b0;
wire adv = i_ce && !beat;

assign o_retire = adv && wb;
    assign o_occ    = occ;

    always @(posedge clk) begin
        if (rst) begin
pipe  <= 3'b000;
            occ   <= 3'd0;
            armed <= 1'b0;
wb    <= 1'b0;
beat  <= 1'b0;
end else begin
if (adv) begin
pipe <= {pipe[1:0], issue};
wb   <= pipe[2];
occ  <= occ + (issue ? 3'd1 : 3'd0) - (wb ? 3'd1 : 3'd0);
            if (issue)
                armed <= 1'b1;
end
if (i_ce)
beat <= !beat && wb;
        end
    end

    // P: once the unit has ever issued, at most 4 operations are in flight.
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd4);
endmodule

module pdk_reqtrack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_arm,     // Q event: arms the tracker (sticky)
    input  wire       i_launch,  // start step: issue a request into the array
    output wire       o_retire,  // finish step: request leaves last stage
    output wire [2:0] o_inflight
);
    parameter STAGES = 4;

    // shift register tracking in-flight requests through the stage array
    reg [STAGES-1:0] pipe;
    // separate count of set bits in that shift register
    reg [2:0]        cnt;
    // sticky arm register (scope): set the first time i_arm is seen, never cleared
    reg              armed;
    // sticky record that a start actually happened after arming
    reg              started;
   // issue stage: an accepted launch is held here for one cycle (address
   // decode) before it is written into the stage array
   reg              ln_stage;

    initial pipe    = {STAGES{1'b0}};
    initial cnt     = 3'd0;
    initial armed   = 1'b0;
    initial started = 1'b0;
   initial ln_stage = 1'b0;

    // a launch is only accepted once the tracker has been armed
    wire accept = i_ce && i_launch && armed;
    wire retire = i_ce && pipe[STAGES-1];

    assign o_retire   = retire;
    assign o_inflight = cnt;

    always @(posedge clk) begin
        if (rst) begin
            pipe    <= {STAGES{1'b0}};
            cnt     <= 3'd0;
            armed   <= 1'b0;
            started <= 1'b0;
           ln_stage <= 1'b0;
        end else if (i_ce) begin
           pipe    <= { pipe[STAGES-2:0], ln_stage };
           cnt     <= cnt + (ln_stage ? 3'd1 : 3'd0)
                           - (pipe[STAGES-1]    ? 3'd1 : 3'd0);
            armed   <= armed || i_arm;
            started <= started || (i_launch && armed);
           ln_stage <= i_launch && armed;
        end
    end

    // Chain precedence, after the sticky arm: while armed, the tracker can never
    // report outstanding work unless a start was really accepted first.
    always @(posedge clk)
        if (armed && (cnt != 3'd0))
            assert (started);

endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
    output wire       g_holdoff
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

// ---- per-slot occupancy accounting, kept in parallel with the valid bits ----
    reg [1:0]  occ;
reg [1:0]  s_occ;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;

    initial begin
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
s_occ   = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

wire       skid_free  = (s_occ == 2'd0);
wire       load_skid  = i_ce && i_valid && !hold && m_valid && !i_ready && skid_free;
wire       fill_main  = i_ce && i_valid && !m_valid;
wire       drain_main = i_ce && m_valid && i_ready && !hold && !i_valid;
wire       drain_skid = i_ce && hold && i_ready;
// total records resident in the stage (main slot + skid slot)
wire [1:0] occ_total  = occ + s_occ;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
if (i_valid && !hold && skid_free) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

// ---- main-slot occupancy counter ----
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
if (fill_main && !drain_main)
                occ <= occ + 2'd1;
else if (drain_main && !fill_main)
                occ <= occ - 2'd1;
        end
    end

// ---- skid-slot occupancy counter ----
always @(posedge i_clk) begin
    if (i_reset)
        s_occ <= 2'd0;
    else if (i_ce) begin
        if (load_skid)
            s_occ <= s_occ + 2'd1;
        else if (drain_skid)
            s_occ <= s_occ - 2'd1;
    end
end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
g_fast <= i_valid && (occ_total == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
assign o_upstream_ready = !hold && skid_free;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

endmodule

module pingpong_tile_buffer (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire       wr_en,
    input  wire       rd_en,
    input  wire [7:0] wr_data,
    output reg  [7:0] rd_data,
    output wire       o_sel
);
    localparam [1:0] LAST = 2'd3;

    // ping-pong double buffer: one half owned by the rasterizer (writer),
    // the other half owned by the shader fetch port (reader)
    reg       sel;                 // master ping-pong select bit
    reg       wr_half, rd_half;    // half currently addressed by each port
    reg [1:0] wcnt, rcnt;          // offset inside the owned half
    reg       wr_full, rd_empty;   // per-half handshake flags
   // buffer-turnaround commit pipeline: the ownership swap is handed to the
   // memory system and retires four cycles later, so both ports keep their
   // current half assignment until the request has walked all four stages
   reg       swp_v0, swp_v1, swp_v2, swp_v3;   // request valid, per stage
   reg       swp_d0, swp_d1, swp_d2, swp_d3;   // pending select, per stage
    reg [7:0] mem [0:7];
    integer   i;

    initial begin
        sel     = 1'b0;
        wr_half = 1'b0;
        rd_half = 1'b1;
        wcnt    = 2'd0;
        rcnt    = 2'd0;
        wr_full = 1'b0;
        rd_empty= 1'b1;
       swp_v0  = 1'b0;
       swp_v1  = 1'b0;
       swp_v2  = 1'b0;
       swp_v3  = 1'b0;
       swp_d0  = 1'b0;
       swp_d1  = 1'b0;
       swp_d2  = 1'b0;
       swp_d3  = 1'b0;
        rd_data = 8'h00;
        for (i = 0; i < 8; i = i + 1) mem[i] = 8'h00;
    end

    wire [2:0] wr_addr = {wr_half, wcnt};
    wire [2:0] rd_addr = {rd_half, rcnt};

    wire w_step = i_ce && wr_en && !wr_full;
    wire r_step = i_ce && rd_en && !rd_empty;
   wire swp_busy   = swp_v0 || swp_v1 || swp_v2 || swp_v3;
   wire swap       = i_ce && wr_full && rd_empty && !swp_busy;
   wire swp_commit = i_ce && swp_v3;

    assign o_sel = sel;

    always @(posedge clk) begin
        if (rst) begin
            sel      <= 1'b0;
            wr_half  <= 1'b0;
            rd_half  <= 1'b1;
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
            wr_full  <= 1'b0;
            rd_empty <= 1'b1;
           swp_v0   <= 1'b0;
           swp_v1   <= 1'b0;
           swp_v2   <= 1'b0;
           swp_v3   <= 1'b0;
           swp_d0   <= 1'b0;
           swp_d1   <= 1'b0;
           swp_d2   <= 1'b0;
           swp_d3   <= 1'b0;
       end else if (swp_commit) begin
           sel      <= swp_d3;
           wr_half  <= swp_d3; // writer takes the freshly drained half
           rd_half  <=  sel;   // reader takes the freshly filled half
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
            wr_full  <= 1'b0;
            rd_empty <= 1'b0;
        end else begin
            if (w_step) begin
                mem[wr_addr] <= wr_data;
                wcnt <= wcnt + 2'd1;
                if (wcnt == LAST) wr_full <= 1'b1;
            end
            if (r_step) begin
                rd_data <= mem[rd_addr];
                rcnt <= rcnt + 2'd1;
                if (rcnt == LAST) rd_empty <= 1'b1;
            end
        end

       // the turnaround request advances one stage per enabled cycle
       if (!rst && i_ce) begin
           swp_v3 <= swp_v2;   swp_d3 <= swp_d2;
           swp_v2 <= swp_v1;   swp_d2 <= swp_d1;
           swp_v1 <= swp_v0;   swp_d1 <= swp_d0;
           swp_v0 <= swap;     swp_d0 <= ~sel;
       end
    end

    // P: whenever both ports perform an access in the same cycle they never
    // touch the same buffer location
    always @(posedge clk)
        if (i_ce && wr_en && rd_en && !wr_full && !rd_empty)
            assert (wr_addr != rd_addr);
endmodule

module prio_grant_tracker (
    input  wire       clk,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [3:0] req,
    output reg        vld,     // registered valid: idx meaningful only while set
    output reg  [1:0] idx,     // encoded winner index
    output reg  [3:0] oh,      // registered one-hot grant
    output reg        ack_lo,  // low-half acknowledge, derived from idx
    output reg        ack_hi,  // high-half acknowledge, derived from one-hot
output reg        armed,   // sticky: set the first time a request is taken
output reg  [3:0] n_take,  // ledger: leases issued  (free-running, wraps)
output reg  [3:0] n_drop,  // ledger: leases retired (free-running, wraps)
output reg        stale    // standing lease has burned one idle cycle
);

    // combinational priority encoder (lowest index wins)
    wire       any = |req;
    wire [1:0] enc = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;
    wire [3:0] iso = req & (~req + 4'd1);   // isolate lowest set bit

   // the ledger, not vld, is the authority on lease occupancy
   wire outstanding = (n_take != n_drop);

    initial begin
        vld    = 1'b0;
        idx    = 2'd0;
        oh     = 4'b0000;
        ack_lo = 1'b0;
        ack_hi = 1'b0;
        armed  = 1'b0;
n_take = 4'd0;
n_drop = 4'd0;
stale  = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            // acknowledge flags are built from the *previous* grant state:
            // one path reads the index, the other reads the one-hot vector
            ack_lo <= vld && (idx < 2'd2);
            ack_hi <= vld && (oh[3] || oh[2]);

            if (any) begin
                // any request refreshes the lease and re-asserts valid
                vld   <= 1'b1;
                armed <= 1'b1;
                stale <= 1'b0;
                if (!outstanding) begin
                    // ledger is square: issue a fresh lease to the winner
                    idx    <= enc;
                    oh     <= iso;
                    n_take <= n_take + 4'd1;
                end else if (enc < idx) begin
                    // lease already in flight: a higher-priority requester
                    // takes it over in place -- a hand-off, not a new lease,
                    // so the ledger does not move
                    idx <= enc;
                    oh  <= iso;
                end
                // otherwise the current holder keeps the bus
            end else if (outstanding) begin
                if (stale) begin
                    // second idle cycle retires the lease; the one-hot is
                    // left parked as a record of the last holder
                    vld    <= 1'b0;
                    stale  <= 1'b0;
                    n_drop <= n_drop + 4'd1;
                end else begin
                    // first idle cycle: age the standing grant round-robin
                    idx   <= idx + 2'd1;
                    oh    <= {oh[2:0], oh[3]};
                    stale <= 1'b1;
                end
            end
        end
    end

    // P: once the tracker has ever accepted a request, the low-half and
    // high-half acknowledges are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(ack_lo && ack_hi));

endmodule

module parity_slice_occ (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_data,
    output reg        o_valid,
    output reg  [7:0] o_data,
    output reg        o_retry
);
    // two-deep register slice, each stage protected by a parity bit
    reg [7:0] d0, d1;
    reg       p0, p1;
    reg       v0, v1;

    // occupancy accounting: one 3-bit counter tracking live stages
    reg [2:0] occ;

   // egress check: the word presented on the output register keeps its slice
   // slot for one more cycle while its parity is re-checked, so the credit is
   // returned one cycle after the word leaves
   reg       oq_busy;
   reg       oq_par;

   // programmable slot limit (one or two stages), written by a control word
   reg [2:0] lim;

    initial begin
        d0 = 8'h00; d1 = 8'h00;
        p0 = 1'b0;  p1 = 1'b0;
        v0 = 1'b0;  v1 = 1'b0;
        occ = 3'd0;
       oq_busy = 1'b0;
       oq_par  = 1'b0;
       lim     = 3'd2;
        o_valid = 1'b0;
        o_data  = 8'h00;
        o_retry = 1'b0;
    end

    // stored parity is checked against stored data every cycle
    wire mism0 = v0 && (p0 != (^d0));
    wire mism1 = v1 && (p1 != (^d1));
    wire retry = mism0 || mism1;

   // the slot is only released when the egress parity re-check is clean
   wire oq_bad = oq_busy && (oq_par != (^o_data));
   wire rel    = oq_busy && !oq_bad;

   // control words carry the depth limit instead of payload
   wire cfg  = i_valid && i_data[7];
   wire room = occ < lim;
   wire acc  = i_valid && !cfg && room;
   wire nack = i_valid && !cfg && !room;

    always @(posedge clk) begin
        if (i_ce) begin
           o_retry <= retry || nack || oq_bad;
            if (retry) begin
                // corrupted stage: freeze the slice and book a replay slot
                occ <= occ + 3'd1;
            end else begin
                // normal shift: stage0 -> stage1 -> output
                d1 <= d0;
                p1 <= p0;
                v1 <= v0;
                d0 <= i_data;
                p0 <= ^i_data;
               v0 <= acc;
               oq_busy <= v1;
               oq_par  <= p1;
               if (cfg) lim <= i_data[0] ? 3'd2 : 3'd1;
               occ <= occ + (acc ? 3'd1 : 3'd0) - (rel ? 3'd1 : 3'd0);
                o_valid <= v1;
                o_data  <= d1;
            end
        end
    end

    // bounded existence: the slice is two deep, so occupancy never exceeds 2
    always @(*) assert (occ <= 3'd2);
endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

   // destination-side retiming pipeline: the event decoder sits far from the
   // synchronizer in the floorplan, so the sampled pointer is retimed four
   // times before it is decoded, and both decode operands are taken from
   // the last two taps of this pipeline so they share the same route delay
   reg [2:0] ret1;
   initial   ret1 = 3'b000;
   reg [2:0] ret2;
   initial   ret2 = 3'b000;
   reg [2:0] ret3;
   initial   ret3 = 3'b000;
   reg [2:0] ret4;
   initial   ret4 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;

    wire [2:0] gray  = bin ^ (bin >> 1);
   wire [2:0] delta = ret3 ^ ret4;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
           ret1      <= 3'b000;
           ret2      <= 3'b000;
           ret3      <= 3'b000;
           ret4      <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;
           ret1  <= sync2;
           ret2  <= ret1;
           ret3  <= ret2;
           ret4  <= ret3;

            if (bad_ev) begin
                stage <= S_FINISH;
            end else begin
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                    end
                S_STARTED:
                    if (fin_ev)
                        stage <= S_FINISH;
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
    assign o_done  = (stage == S_FINISH);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
endmodule

// Kernel task handshake tracker.
// The progress accumulator is kept in two carry-save halves acc_a/acc_b whose
// sum is the true phase count (0=idle, 1=armed, 2=started, 3=finished).
// A tiny FSM (ph_ref) enforces the arm -> start -> finish chain, and sticky
// flags record that each earlier step was really observed.
module cs_chain_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       i_track,   // Q event: arms the observation scope, sticky
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_finish,
    output wire [3:0] o_total,
    output wire       o_done
);
    // carry-save halves of the progress accumulator
    reg [2:0] acc_a, acc_b;
    // redundant direct copy of the phase, used by the sequencer
    reg [2:0] ph_ref;
    // which half receives the next increment
    reg       tog;
    // chain witnesses
    reg       arm_seen, start_seen;
    // sticky scope register (set the first time i_track is seen)
    reg       armed;
   // stage-2 drain chain: reuses the same handshake strobes once stage 1 retired
   reg [2:0] ph_ref2;
   // sticky flag: the drain chain reached its final phase
   reg       b_done;

    initial begin
        acc_a      = 3'd0;
        acc_b      = 3'd0;
        ph_ref     = 3'd0;
        tog        = 1'b0;
        arm_seen   = 1'b0;
        start_seen = 1'b0;
        armed      = 1'b0;
       ph_ref2    = 3'd0;
       b_done     = 1'b0;
    end

    // true total recombined from the two halves
    wire [3:0] total = {1'b0, acc_a} + {1'b0, acc_b};
    assign o_total = total;
   assign o_done  = (total == 4'd3) || b_done;

    // one chain step at a time, in order
    wire adv = i_ce && (((ph_ref == 3'd0) && i_arm)    ||
                        ((ph_ref == 3'd1) && i_start)  ||
                        ((ph_ref == 3'd2) && i_finish));

   // the drain chain may only take the shared accumulator once stage 1 retired
   wire adv2 = i_ce && (ph_ref == 3'd3) &&
                       (((ph_ref2 == 3'd0) && i_arm)   ||
                        ((ph_ref2 == 3'd1) && i_start) ||
                        ((ph_ref2 == 3'd2) && i_finish));

   // shared increment port into the carry-save halves
   wire inc = adv || adv2;

    always @(posedge clk) begin
        if (rst) begin
            acc_a      <= 3'd0;
            acc_b      <= 3'd0;
            ph_ref     <= 3'd0;
            tog        <= 1'b0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            armed      <= 1'b0;
           ph_ref2    <= 3'd0;
           b_done     <= 1'b0;
        end else begin
            if (i_ce && i_track)
                armed <= 1'b1;

           if (inc) begin
               // split increment: the halves re-sum to both chain phases together
                if (tog) acc_b <= acc_b + 3'd1;
                else     acc_a <= acc_a + 3'd1;
               tog <= ~tog;
           end

           if (adv) begin
               ph_ref <= ph_ref + 3'd1;

                if (ph_ref == 3'd0) arm_seen   <= 1'b1;
                if (ph_ref == 3'd1) start_seen <= 1'b1;
            end

           if (adv2) begin
               ph_ref2 <= ph_ref2 + 3'd1;
               if (ph_ref2 == 3'd2) b_done <= 1'b1;
           end
        end
    end

    // Chain precedence, in the sticky "after i_track" scope:
    // a finished accumulation can never be observed unless both the arm and
    // the start steps were witnessed first.
    always @(*)
        if (armed && (total == 4'd3))
            assert (start_seen && arm_seen);
endmodule

module disasm_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       kick,      // an instruction was successfully decoded
    output reg  [3:0] count,     // cycles since last kick
    output reg        expired,   // decoder hung: limit was reached
    output reg        healthy    // plenty of slack left
);
    localparam [3:0] LIMIT = 4'd10;   // timeout
    localparam [3:0] WARN  = 4'd8;    // slack threshold

   // saved context of the decode channel that is parked while the other
   // one owns the shared pipeline slot
   reg  [3:0] count_sh;
   reg        exp_sh;
  // second parked context: three decode channels rotate through the one
  // pipeline slot, so two of them are always parked at any time
  reg  [3:0] count_sh2;
  reg        exp_sh2;

    initial begin
        count   = 4'd0;
        expired = 1'b0;
        healthy = 1'b1;
       count_sh = 4'd0;
       exp_sh   = 1'b0;
      count_sh2 = 4'd0;
      exp_sh2   = 1'b0;
    end

    // next value of the stall counter: kick clears it, otherwise it
    // counts up and saturates at the timeout limit
    wire [3:0] nxt = kick              ? 4'd0  :
                     (count == LIMIT)  ? LIMIT :
                                         count + 4'd1;

   // the slot is handed to the other channel when the active one makes
   // progress, and is preempted once the active one has clearly hung
   wire swap = kick || (count == LIMIT);

    always @(posedge clk) begin
        if (rst) begin
            count   <= 4'd0;
           count_sh <= 4'd0;
           exp_sh   <= 1'b0;
           count_sh2 <= 4'd0;
           exp_sh2   <= 1'b0;
            expired <= 1'b0;
            healthy <= 1'b1;
        end else if (i_ce) begin
           if (swap) begin
               count    <= count_sh;         // resume the parked channel
count_sh  <= count_sh2;        // rotate the parked queue forward
count_sh2 <= nxt;              // park the current stall count
exp_sh    <= exp_sh2;          // its hang flag rotates with it
exp_sh2   <= (nxt == LIMIT);   // remember if it hung
           end else begin
               count    <= nxt;
           end
           // sticky per channel: a kick only clears the channel that
           // currently owns the slot
expired <= (nxt == LIMIT) || exp_sh || exp_sh2;
healthy <= (nxt < WARN) && (count_sh < WARN) && (count_sh2 < WARN);
        end
    end

    // P: the timeout flag and the slack flag are never raised together
    always @(posedge clk)
        if (expired)
            assert (!healthy);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_raw != samp) begin
                // sample changed: restart the stability count
                samp     <= i_raw;
                cnt      <= 3'd0;
                stable_f <= 1'b0;
cmt_pend <= 1'b0;          // an in-flight commit is aborted
end else begin
    if (cnt != K) begin
        cnt <= cnt + 3'd1;
        if (cnt == K - 3'd1) begin
            // stage the commit; the flag and output move one step later
            cmt_pend <= 1'b1;
            cmt_val  <= samp;
        end
    end
    if (cmt_pend) begin
        o_clean  <= cmt_val;   // commit the debounced value
        stable_f <= 1'b1;
        cmt_pend <= 1'b0;
    end
            end
// cnt == K with nothing staged: saturated, hold cnt, stable_f and o_clean

            if (i_disarm)
                armed <= 1'b0;
            else if (i_arm)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

module serial_retire_counter (
    input  wire i_clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_bit,
    output wire o_word_done,
    output wire o_saturated
);
    // Bit-serial datapath: one bit per enabled cycle, 32 bits per word.
    // Every completed 32-bit word retires one operation; the retire counter
    // is a saturating up-counter that clamps at 20, well below the 31 its
    // 5-bit register could hold.
    localparam [4:0] MAX_RETIRE = 5'd20;

    reg [4:0]  sh;       // serial bit index 0..31
    reg [31:0] word;     // serial shift register (datapath flavour)
    reg [4:0]  retired;  // saturating up-counter, clamps at MAX_RETIRE
    reg        done;     // "counter has reached the clamp" flag
   reg [4:0]  pend;    // retire credits posted but not yet counted

    initial sh      = 5'd0;
    initial word    = 32'd0;
    initial retired = 5'd0;
    initial done    = 1'b0;
   initial pend    = 5'd0;

   // Retirement is credited through a small pending-credit queue: a completed
   // word posts one credit, and the retire counter's write port (shared with
   // word capture) releases one credit on any enabled cycle that is not a
   // word boundary.  Saturation is declared on the total, posted + counted.

    wire word_last = (sh == 5'd31);

   wire [5:0] retire_total = {1'b0, retired} + {1'b0, pend};
   wire       credit_enq   = word_last && !done;
   wire       credit_deq   = (pend != 5'd0) && !word_last;

    always @(posedge i_clk) begin
        if (i_rst) begin
            sh      <= 5'd0;
            word    <= 32'd0;
            retired <= 5'd0;
            done    <= 1'b0;
           pend    <= 5'd0;
        end else if (i_ce) begin
            sh   <= sh + 5'd1;
            word <= { i_bit, word[31:1] };
           if (credit_enq)
               pend <= pend + 5'd1;
           else if (credit_deq)
               pend <= pend - 5'd1;
           if (credit_deq)
               retired <= retired + 5'd1;
           if (credit_enq)
               done <= (retire_total == {1'b0, (MAX_RETIRE - 5'd1)});
        end
    end

    assign o_word_done = word_last;
    assign o_saturated = done;

    // P: the retire count never exceeds 20, although the register admits 31.
    always @(posedge i_clk)
        assert (retired <= MAX_RETIRE);
endmodule

module deb_evt_fifo (
    input  wire clk,
    input  wire i_ce,      // sample enable: low freezes all state
    input  wire raw,       // raw (noisy) button level
    input  wire pop,       // consumer request
    output wire empty,
    output wire full,
    output reg  o_level    // last popped debounced level
);
    // ---- debouncer: saturating stability counter ----
    reg [1:0] stab;
    reg       deb;

    // ---- event FIFO: pointers + occupancy ----
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg [1:0] tail;        // shadow: write pointer snapshot taken at the last push
    reg       mem [0:3];
   reg [1:0] wnext;       // precomputed next write address (shared write-port adder)

   // ---- refresh generator: periodic level-refresh events ----
   // second producer on the shared FIFO write port: every fourth sample it
   // re-posts the current debounced level so a stalled consumer still gets a
   // fresh entry. Edge events own the port; a coincident refresh is held.
   reg [1:0] hb;
   reg       hb_pend;

   // ---- event ledger: free-running push/pop transfer counters ----
   // flag generation is taken from the ledger difference so that empty/full
   // are a direct function of logged transfers rather than of the occupancy
   // accumulator; the counters wrap naturally at their width.
   reg [2:0] n_push, n_pop;
   wire [2:0] occ = n_push - n_pop;   // outstanding entries, mod 8

    // ---- scope register: high until the FIFO has ever been full ----
    reg       never_full;

    // ---- past-valid ----
    reg       pv;

    initial begin
        stab = 2'd0; deb = 1'b0;
        wptr = 2'd0; rptr = 2'd0; count = 3'd0;
        tail = 2'd0;
       wnext = 2'd1;
       hb = 2'd0; hb_pend = 1'b0;
       n_push = 3'd0; n_pop = 3'd0;
        never_full = 1'b1;
        pv = 1'b0;
        o_level = 1'b0;
        mem[0] = 1'b0; mem[1] = 1'b0; mem[2] = 1'b0; mem[3] = 1'b0;
    end

   assign empty = (occ == 3'd0);
   assign full  = (occ == 3'd4);

    // a debounced edge is committed once raw has disagreed with deb for 3 samples
    wire deb_commit = (raw != deb) && (stab == 2'd2);

   wire hb_req   = (hb == 2'd3) || hb_pend;
   wire push_req = deb_commit || hb_req;
   wire do_push  = i_ce && push_req && !full;
    wire do_pop  = i_ce && pop && !empty;

    always @(posedge clk) begin
        if (i_ce) begin
            if (raw != deb) begin
                if (stab == 2'd2) stab <= 2'd0;
                else              stab <= stab + 2'd1;
            end else begin
                stab <= 2'd0;
            end
            if (deb_commit) deb <= raw;

            if (do_push) begin
               mem[wptr] <= deb_commit ? raw : deb;
               wptr      <= wnext;
               tail      <= wnext;
               wnext     <= wnext + 2'd1;
            end

           // the refresh prescaler runs off the sample clock; a refresh
           // request retires only once it actually wins the write port
           hb <= hb + 2'd1;
           if (hb_req) hb_pend <= deb_commit || full;

            if (do_pop) begin
                o_level <= mem[rptr];
                rptr    <= rptr + 2'd1;
            end

           // log both sides of every completed transfer
           if (do_push) n_push <= n_push + 3'd1;
           if (do_pop)  n_pop  <= n_pop  + 3'd1;

            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase

            if (count == 3'd4) never_full <= 1'b0;
        end
        pv <= 1'b1;
    end

    // Precedence, before-first-full scope, stated about the previous cycle:
    // if the queue has just been drained empty by a pop, the read pointer must
    // have reached the write-pointer snapshot recorded at the earlier push.
    always @(posedge clk)
        if (pv && never_full && (count == 3'd0) && $past(do_pop))
            assert (rptr == $past(tail));
endmodule

module seq_detect_1011 (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output wire       match,
    output wire [3:0] hits
);
    // fixed pattern, MSB first: 1 0 1 1
    localparam [3:0] PAT = 4'b1011;

    // match-progress register: number of leading pattern bits matched so far,
    // never exceeds the pattern length (4)
    reg [2:0] prog;
    // shadow register: records that progress 3 (pattern prefix 101) was
    // observed at some earlier cycle
    reg       saw_p3;
    // saturating count of completed pattern matches consumed
    reg [3:0] match_count;
   // commit-stage flag: a detected match is posted here and lands in the
   // counter on the next enabled cycle, keeping the counter adder off the
   // detector's critical path
   reg       cmt_vld;

  // sticky saturation lock: if the counter is already topped out when a
  // match credit retires, the credit is dropped and the reading is frozen,
  // so software can tell "exactly 15" from "15 or more"
  reg       sat_lock;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;
   initial cmt_vld     = 1'b0;
  initial sat_lock    = 1'b0;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
    wire       restart  = (din == PAT[3]) ? 1'b1 : 1'b0;

    assign match = (prog == 3'd4);
    assign hits  = match_count;

    always @(posedge clk) begin
        if (rst) begin
            prog        <= 3'd0;
            saw_p3      <= 1'b0;
            match_count <= 4'd0;
           cmt_vld     <= 1'b0;
          sat_lock    <= 1'b0;
        end else if (ce) begin
            // shadow bit latches the earlier occurrence of progress 3
            saw_p3 <= saw_p3 | (prog == 3'd3);
           // post a credit for a completed match; retire the credit posted
           // by the previous enabled cycle
           cmt_vld <= (prog == 3'd4);
          if (cmt_vld)
              sat_lock <= sat_lock | (match_count == 4'd15);
          if (cmt_vld && !sat_lock)
               match_count <= (match_count == 4'd15) ? 4'd15 : match_count + 4'd1;


            if (prog == 3'd4) begin
                // consume the completed match, then begin a fresh scan
                prog        <= restart ? 3'd1 : 3'd0;
            end else if (din == exp_bit) begin
                prog <= prog + 3'd1;
            end else begin
                prog <= restart ? 3'd1 : 3'd0;
            end
        end
    end

    // Precedence, global: any counted match must have been preceded by the
    // pattern prefix reaching progress 3.
    assert property (match_count == 4'd0 || saw_p3);

   // Saturation lock is a consequence of counted traffic: it can only engage
   // after the counter has been driven to full, so the exported count is
   // nonzero and the pattern prefix must already have been seen.
   always @(posedge clk)
       assert (!sat_lock || (saw_p3 && hits != 4'd0));
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
output wire [2:0] o_inflight,
output reg  [3:0] o_issue_hist
);
    // fixed-latency (4 cycle) pipeline occupancy shift register
    reg [3:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;
// distractor: history of raw issue requests (not tied to occupancy)
reg [3:0] req_hist;

    initial pipe     = 4'b0000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;
initial req_hist     = 4'b0000;
initial o_issue_hist = 4'b0000;

    wire retire = pipe[3];

    always @(posedge clk) begin
        if (rst) begin
            pipe     <= 4'b0000;
            inflight <= 3'd0;
req_hist     <= 4'b0000;
o_issue_hist <= 4'b0000;
        end else if (i_ce) begin
            pipe     <= {pipe[2:0], issue};
            inflight <= inflight + {2'b00, issue} - {2'b00, retire};
req_hist     <= {req_hist[2:0], issue};
o_issue_hist <= req_hist ^ {3'b000, issue};
        end
    end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
    // anticipated carry out of the low half of cnt, registered a cycle early
    // so the wrap term never ripples across all four counter bits
    reg lo_tc;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
        lo_tc = 1'b0;
    end

    wire [1:0] nxt_lo   = cnt[1:0] + 2'd1;
    wire [1:0] nxt_hi   = cnt[3:2] + {1'b0, lo_tc};
    wire [3:0] nxt      = {nxt_hi, nxt_lo};
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            lo_tc <= (cnt[1:0] == 2'd2);
            g   <= nxt_gray;
            s1  <= g;
            s2  <= s1;
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
    assign o_settled = (diff == 4'd0);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

// Kernel task handshake tracker.
// The progress accumulator is kept in two carry-save halves acc_a/acc_b whose
// sum is the true phase count (0=idle, 1=armed, 2=started, 3=finished).
// A tiny FSM (ph_ref) enforces the arm -> start -> finish chain, and sticky
// flags record that each earlier step was really observed.
module cs_chain_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       i_track,   // Q event: arms the observation scope, sticky
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_finish,
    output wire [3:0] o_total,
    output wire       o_done
);
    // carry-save halves of the progress accumulator
    reg [2:0] acc_a, acc_b;
    // redundant direct copy of the phase, used by the sequencer
    reg [2:0] ph_ref;
    // which half receives the next increment
    reg       tog;
    // chain witnesses
    reg       arm_seen, start_seen;
    // sticky scope register (set the first time i_track is seen)
    reg       armed;
   // stage-2 drain chain: reuses the same handshake strobes once stage 1 retired
   reg [2:0] ph_ref2;
   // sticky flag: the drain chain reached its final phase
   reg       b_done;
  // stage-3 writeback chain: reuses the same strobes after the drain retired
  reg [2:0] ph_ref3;
  // sticky flag: the writeback chain reached its final phase
  reg       c_done;

    initial begin
        acc_a      = 3'd0;
        acc_b      = 3'd0;
        ph_ref     = 3'd0;
        tog        = 1'b0;
        arm_seen   = 1'b0;
        start_seen = 1'b0;
        armed      = 1'b0;
       ph_ref2    = 3'd0;
       b_done     = 1'b0;
      ph_ref3    = 3'd0;
      c_done     = 1'b0;
    end

    // true total recombined from the two halves
    wire [3:0] total = {1'b0, acc_a} + {1'b0, acc_b};
    assign o_total = total;
  assign o_done  = (total == 4'd3) || b_done || c_done;

    // one chain step at a time, in order
    wire adv = i_ce && (((ph_ref == 3'd0) && i_arm)    ||
                        ((ph_ref == 3'd1) && i_start)  ||
                        ((ph_ref == 3'd2) && i_finish));

   // the drain chain may only take the shared accumulator once stage 1 retired
   wire adv2 = i_ce && (ph_ref == 3'd3) &&
                       (((ph_ref2 == 3'd0) && i_arm)   ||
                        ((ph_ref2 == 3'd1) && i_start) ||
                        ((ph_ref2 == 3'd2) && i_finish));

  // the writeback chain only takes the shared accumulator once the drain retired
  wire adv3 = i_ce && (ph_ref2 == 3'd3) &&
                      (((ph_ref3 == 3'd0) && i_arm)   ||
                       ((ph_ref3 == 3'd1) && i_start) ||
                       ((ph_ref3 == 3'd2) && i_finish));

   // shared increment port into the carry-save halves
  wire inc = adv || adv2 || adv3;

    always @(posedge clk) begin
        if (rst) begin
            acc_a      <= 3'd0;
            acc_b      <= 3'd0;
            ph_ref     <= 3'd0;
            tog        <= 1'b0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            armed      <= 1'b0;
           ph_ref2    <= 3'd0;
           b_done     <= 1'b0;
          ph_ref3    <= 3'd0;
          c_done     <= 1'b0;
        end else begin
            if (i_ce && i_track)
                armed <= 1'b1;

           if (inc) begin
               // split increment: the halves re-sum to both chain phases together
                if (tog) acc_b <= acc_b + 3'd1;
                else     acc_a <= acc_a + 3'd1;
               tog <= ~tog;
           end

           if (adv) begin
               ph_ref <= ph_ref + 3'd1;

                if (ph_ref == 3'd0) arm_seen   <= 1'b1;
                if (ph_ref == 3'd1) start_seen <= 1'b1;
            end

           if (adv2) begin
               ph_ref2 <= ph_ref2 + 3'd1;
               if (ph_ref2 == 3'd2) b_done <= 1'b1;
           end

          if (adv3) begin
              ph_ref3 <= ph_ref3 + 3'd1;
              if (ph_ref3 == 3'd2) c_done <= 1'b1;
          end
        end
    end

    // Chain precedence, in the sticky "after i_track" scope:
    // a finished accumulation can never be observed unless both the arm and
    // the start steps were witnessed first.
    always @(*)
        if (armed && (total == 4'd3))
            assert (start_seen && arm_seen);
endmodule

module seq_detect_1011 (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output wire       match,
    output wire [3:0] hits
);
    // fixed pattern, MSB first: 1 0 1 1
    localparam [3:0] PAT = 4'b1011;
   // second channel, MSB first: 0 1 1 0, scanned on the same input stream
   localparam [3:0] PAT_B = 4'b0110;

    // match-progress register: number of leading pattern bits matched so far,
    // never exceeds the pattern length (4)
    reg [2:0] prog;
   // channel B match-progress register, same bound as channel A
   reg [2:0] prog_b;
    // shadow register: records that progress 3 (pattern prefix 101) was
    // observed at some earlier cycle
    reg       saw_p3;
    // saturating count of completed pattern matches consumed
    reg [3:0] match_count;
   // commit-stage flag: a detected match is posted here and lands in the
   // counter on the next enabled cycle, keeping the counter adder off the
   // detector's critical path
   reg       cmt_vld;
  // channel B credit for the shared retire port: channel A owns the port
  // when it is retiring, so a B credit waits here until the port is free
  reg       cmt_pend_b;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;
   initial cmt_vld     = 1'b0;
  initial prog_b      = 3'd0;
  initial cmt_pend_b  = 1'b0;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
    wire       restart  = (din == PAT[3]) ? 1'b1 : 1'b0;
   wire [1:0] idx_b     = 2'd3 - prog_b[1:0];
   wire       exp_bit_b = PAT_B[idx_b];
   wire       restart_b = (din == PAT_B[3]) ? 1'b1 : 1'b0;

    assign match = (prog == 3'd4);
    assign hits  = match_count;

    always @(posedge clk) begin
        if (rst) begin
            prog        <= 3'd0;
            saw_p3      <= 1'b0;
            match_count <= 4'd0;
           cmt_vld     <= 1'b0;
          prog_b      <= 3'd0;
          cmt_pend_b  <= 1'b0;
        end else if (ce) begin
            // shadow bit latches the earlier occurrence of progress 3
           // either channel reaching the deep prefix sets the shared flag
           saw_p3 <= saw_p3 | (prog == 3'd3) | (prog_b == 3'd3);
           // post a credit for a completed match; retire the credit posted
           // by the previous enabled cycle
           cmt_vld <= (prog == 3'd4);
          // channel B posts into the same retire port; the credit is held
          // while channel A is using the port this cycle
          cmt_pend_b <= (prog_b == 3'd4) | (cmt_pend_b & cmt_vld);
          if (cmt_vld || cmt_pend_b)
               match_count <= (match_count == 4'd15) ? 4'd15 : match_count + 4'd1;


            if (prog == 3'd4) begin
                // consume the completed match, then begin a fresh scan
                prog        <= restart ? 3'd1 : 3'd0;
            end else if (din == exp_bit) begin
                prog <= prog + 3'd1;
            end else begin
                prog <= restart ? 3'd1 : 3'd0;
            end

           // channel B scanner: independent progress over the same stream
           if (prog_b == 3'd4) begin
               prog_b <= restart_b ? 3'd1 : 3'd0;
           end else if (din == exp_bit_b) begin
               prog_b <= prog_b + 3'd1;
           end else begin
               prog_b <= restart_b ? 3'd1 : 3'd0;
           end
        end
    end

    // Precedence, global: any counted match must have been preceded by the
    // pattern prefix reaching progress 3.
    assert property (match_count == 4'd0 || saw_p3);
endmodule

// Triple-modular-redundant power-rail sequencer step counter.
// Three shadow copies of the sequencer step code are advanced independently;
// the exported step code is the bitwise majority vote of the three copies.
// prev_voted is a precedence shadow: it records the voted code as it was at
// the previous advance, so the present code must be the successor of the code
// that was observed earlier.
module tmr_rail_sequencer (
    input  wire       clk,
    input  wire       ce,        // advance / load enable; low => design idles
    input  wire       load,      // reload the sequencer with an external code
    input  wire [2:0] code_in,
    input  wire       q_start,   // opens the monitoring window
    input  wire       r_stop,    // closes the monitoring window
    output wire [2:0] voted
);

    // three shadow registers of the TMR voter
    reg [2:0] shadow_a = 3'd1;
    reg [2:0] shadow_b = 3'd1;
    reg [2:0] shadow_c = 3'd1;

// Precedence shadow, split for radiation tolerance: the low two bits of the
// recorded code ripple in prev_lo, while its top bit is kept as a dual-rail
// pair whose advance is a swap of the two rails.
reg [1:0] prev_lo   = 2'd0;
reg       prev_hi_t = 1'b0;
reg       prev_hi_f = 1'b1;

    // window register: set by q_start, cleared by r_stop, reopenable
    reg       win = 1'b0;

    // bitwise majority vote
    assign voted = (shadow_a & shadow_b) | (shadow_a & shadow_c) |
                   (shadow_b & shadow_c);

// recomposed precedence code
wire [2:0] prev_voted = {prev_hi_t, prev_lo};

    always @(posedge clk) begin
        if (ce) begin
            if (load) begin
                shadow_a   <= code_in;
                shadow_b   <= code_in;
                shadow_c   <= code_in;
prev_lo   <= code_in[1:0] - 2'd1;
prev_hi_t <= code_in[2] ^ (code_in[1:0] == 2'd0);
prev_hi_f <= ~(code_in[2] ^ (code_in[1:0] == 2'd0));
            end else begin
                shadow_a   <= shadow_a + 3'd1;
                shadow_b   <= shadow_b + 3'd1;
                shadow_c   <= shadow_c + 3'd1;
prev_lo <= voted[1:0];
// the top bit only moves when the low part rolls over
if (prev_lo == 2'd3) begin
    prev_hi_t <= prev_hi_f;
    prev_hi_f <= prev_hi_t;
end
            end
        end
    end

    always @(posedge clk) begin
        if (r_stop)
            win <= 1'b0;
        else if (q_start)
            win <= 1'b1;
    end

    // Property: inside the monitoring window, the voted step code must be the
    // immediate successor of the code recorded earlier in prev_voted.
    always @(posedge clk)
        assert (!win || (voted == prev_voted + 3'd1));

endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
output wire       o_settled, // no sample in flight
output reg  [3:0] o_acc      // distractor: settled-beat accumulator
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
o_acc = 4'd0;
    end

    wire [3:0] nxt      = cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
            s1  <= g;
            s2  <= s1;
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
    assign o_settled = (diff == 4'd0);

// distractor logic: counts destination beats seen while the path is settled
always @(posedge clk) begin
    if (i_ce)
        o_acc <= o_acc + {3'd0, o_settled};
end

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module parity_slice_occ (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_data,
    output reg        o_valid,
    output reg  [7:0] o_data,
    output reg        o_retry
);
    // two-deep register slice, each stage protected by a parity bit
    reg [7:0] d0, d1;
    reg       p0, p1;
    reg       v0, v1;

    // occupancy accounting: one 3-bit counter tracking live stages
    reg [2:0] occ;

   // egress check: the word presented on the output register keeps its slice
   // slot for one more cycle while its parity is re-checked, so the credit is
   // returned one cycle after the word leaves
   reg       oq_busy;
   reg       oq_par;

   // programmable slot limit (one or two stages), written by a control word
   reg [2:0] lim;

  // replay bookkeeping: every parity mismatch books one replay slot, and a
  // booked slot is handed back when the egress re-check frees a credit
  reg [2:0] rpy;

    initial begin
        d0 = 8'h00; d1 = 8'h00;
        p0 = 1'b0;  p1 = 1'b0;
        v0 = 1'b0;  v1 = 1'b0;
        occ = 3'd0;
       oq_busy = 1'b0;
       oq_par  = 1'b0;
       lim     = 3'd2;
      rpy     = 3'd0;
        o_valid = 1'b0;
        o_data  = 8'h00;
        o_retry = 1'b0;
    end

    // stored parity is checked against stored data every cycle
    wire mism0 = v0 && (p0 != (^d0));
    wire mism1 = v1 && (p1 != (^d1));
    wire retry = mism0 || mism1;

   // the slot is only released when the egress parity re-check is clean
   wire oq_bad = oq_busy && (oq_par != (^o_data));
   wire rel    = oq_busy && !oq_bad;

   // control words carry the depth limit instead of payload
   wire cfg  = i_valid && i_data[7];
   wire room = occ < lim;
   wire acc  = i_valid && !cfg && room;
   wire nack = i_valid && !cfg && !room;

    always @(posedge clk) begin
        if (i_ce) begin
          o_retry <= retry || nack || oq_bad || (rpy != 3'd0);
            if (retry) begin
                // corrupted stage: freeze the slice and book a replay slot
                occ <= occ + 3'd1;
               rpy <= rpy + 3'd1;
            end else begin
                // normal shift: stage0 -> stage1 -> output
                d1 <= d0;
                p1 <= p0;
                v1 <= v0;
                d0 <= i_data;
                p0 <= ^i_data;
               v0 <= acc;
               oq_busy <= v1;
               oq_par  <= p1;
               if (cfg) lim <= i_data[0] ? 3'd2 : 3'd1;
               occ <= occ + (acc ? 3'd1 : 3'd0) - (rel ? 3'd1 : 3'd0);
              if (rel && rpy != 3'd0) rpy <= rpy - 3'd1;
                o_valid <= v1;
                o_data  <= d1;
            end
        end
    end

    // bounded existence: the slice is two deep, so occupancy never exceeds 2
    always @(*) assert (occ <= 3'd2);

   // a replay slot is only booked on a real corruption, so booked slots plus
   // live slice slots never oversubscribe the two-deep slice
   always @(posedge clk)
       assert ({1'b0, occ} + {1'b0, rpy} <= 4'd2);
endmodule

// Packet-capture sensor credit window.
// TOTAL = 8 stream credits.  A burst send spends 3 credits (they become
// "outstanding" bytes in flight); the collector returns exactly one credit
// per enabled cycle while anything is outstanding.  A deadline register is
// reloaded on every accepted burst and counts down otherwise; it must never
// expire while credits are still outstanding.
module credit_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_send,    // producer requests a burst
output wire       o_busy,
output wire [3:0] o_nspend,  // ledger: credits handed to the link (wraps)
output wire [3:0] o_nret,    // ledger: credits taken back (wraps)
output wire       o_phase    // which link slot the collector is in
);
    reg [3:0] avail;   // credits held by the sensor
    reg [3:0] outst;   // credits outstanding (in flight)
    reg [3:0] timer;   // completion deadline countdown
    reg       armed;   // sticky: set the first time a burst is accepted
reg [3:0] n_spend;  // event ledger: credits spent on bursts
reg [3:0] n_ret;    // event ledger: credits returned by the collector
reg       phase;    // half-rate return link: credits only come back on return slots

    initial avail = 4'd8;
    initial outst = 4'd0;
    initial timer = 4'd0;
    initial armed = 1'b0;
initial n_spend = 4'd0;
initial n_ret = 4'd0;
initial phase = 1'b0;

    wire send_ok = i_send && (avail >= 4'd3);
wire retire  = (outst != 4'd0) && phase;

    assign o_busy = (outst != 4'd0);
assign o_nspend = n_spend;
assign o_nret   = n_ret;
assign o_phase  = phase;

    always @(posedge clk) begin
        if (rst) begin
            avail <= 4'd8;
            outst <= 4'd0;
            timer <= 4'd0;
            armed <= 1'b0;
n_spend <= 4'd0;
n_ret <= 4'd0;
phase <= 1'b0;
        end else if (i_ce) begin
phase <= ~phase;             // link alternates send / return slots
if (send_ok) n_spend <= n_spend + 4'd3;
if (retire)  n_ret   <= n_ret   + 4'd1;
            if (send_ok) begin
                // spend three credits, one may come back the same cycle
                avail <= avail - 4'd3 + (retire ? 4'd1 : 4'd0);
                outst <= outst + 4'd3 - (retire ? 4'd1 : 4'd0);
timer <= 4'd15;         // deadline: half-rate return of up to 8 credits
                armed <= 1'b1;          // sticky arm
            end else if (retire) begin
                avail <= avail + 4'd1;
                outst <= outst - 4'd1;
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end else begin
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end
        end
    end

    // Bounded response (safety form), scoped after the first accepted burst:
    // the deadline never expires while credits are still outstanding.
    always @(*)
        assert (!armed || !((timer == 4'd0) && (outst != 4'd0)));
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;
   localparam       CH_A = 1'b0;  // commit-stage owner encoding
   localparam       CH_B = 1'b1;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
reg       cmt_ch   = 1'b0;  // which channel owns the commit stage
reg       samp_b   = 1'b0;  // last accepted arm-button sample
reg [2:0] cnt_b    = 3'd0;  // arm-button stability counter, saturates at K
reg       arm_clean = 1'b0; // debounced arm-button level
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

   // Only one commit stage was budgeted, so the two channels arbitrate for it;
   // the raw-sample channel wins a tie, the arm channel retries next step.
   wire a_chg   = (i_raw != samp);
   wire b_chg   = (i_arm != samp_b);
   wire a_req   = !a_chg && (cnt   == K - 3'd1);
   wire b_req   = !b_chg && (cnt_b == K - 3'd1);
   wire grant_a = !cmt_pend && a_req;
   wire grant_b = !cmt_pend && b_req && !a_req;

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
           // ---- channel A: the raw sample ----
           if (a_chg) begin
               // sample changed: restart the stability count
               samp     <= i_raw;
               cnt      <= 3'd0;
               stable_f <= 1'b0;
           end else if (cnt != K) begin
               if (!a_req) begin
                   cnt <= cnt + 3'd1;
               end else if (grant_a) begin
                   // stage the commit; the flag and output move one step later
                   cnt      <= cnt + 3'd1;
                   cmt_pend <= 1'b1;
                   cmt_val  <= samp;
                   cmt_ch   <= CH_A;
               end
               // stage busy: hold at K-1 and retry once it frees
           end

           // ---- channel B: the arm button, same filter, same stage ----
           if (b_chg) begin
               samp_b <= i_arm;
               cnt_b  <= 3'd0;
           end else if (cnt_b != K) begin
               if (!b_req) begin
                   cnt_b <= cnt_b + 3'd1;
               end else if (grant_b) begin
                   cnt_b    <= cnt_b + 3'd1;
                   cmt_pend <= 1'b1;
                   cmt_val  <= samp_b;
                   cmt_ch   <= CH_B;
               end
           end

           // ---- shared stage: retires one entry per enabled step ----
           if (cmt_pend) begin
               cmt_pend <= 1'b0;
               if (cmt_ch == CH_A) begin
                   if (!a_chg) begin
                       o_clean  <= cmt_val;   // commit the debounced value
                       stable_f <= 1'b1;
                   end
               end else if (!b_chg) begin
                   arm_clean <= cmt_val;
               end
           end

            if (i_disarm)
                armed <= 1'b0;
           else if (arm_clean)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

module deb_evt_fifo (
    input  wire clk,
    input  wire i_ce,      // sample enable: low freezes all state
    input  wire raw,       // raw (noisy) button level
    input  wire pop,       // consumer request
    output wire empty,
    output wire full,
output reg  o_level,   // last popped debounced level
output reg [3:0] o_dbg_cnt
);
    // ---- debouncer: saturating stability counter ----
    reg [1:0] stab;
    reg       deb;

    // ---- event FIFO: pointers + occupancy ----
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg [1:0] tail;        // shadow: write pointer snapshot taken at the last push
    reg       mem [0:3];

   // ---- event ledger: free-running push/pop transfer counters ----
   // flag generation is taken from the ledger difference so that empty/full
   // are a direct function of logged transfers rather than of the occupancy
   // accumulator; the counters wrap naturally at their width.
   reg [2:0] n_push, n_pop;
   wire [2:0] occ = n_push - n_pop;   // outstanding entries, mod 8

    // ---- scope register: high until the FIFO has ever been full ----
    reg       never_full;

    // ---- past-valid ----
    reg       pv;
// ---- debug: raw-edge activity counter (observability only) ----
reg       raw_d;

    initial begin
        stab = 2'd0; deb = 1'b0;
        wptr = 2'd0; rptr = 2'd0; count = 3'd0;
        tail = 2'd0;
       n_push = 3'd0; n_pop = 3'd0;
        never_full = 1'b1;
        pv = 1'b0;
        o_level = 1'b0;
raw_d = 1'b0; o_dbg_cnt = 4'd0;
        mem[0] = 1'b0; mem[1] = 1'b0; mem[2] = 1'b0; mem[3] = 1'b0;
    end

   assign empty = (occ == 3'd0);
   assign full  = (occ == 3'd4);

    // a debounced edge is committed once raw has disagreed with deb for 3 samples
    wire deb_commit = (raw != deb) && (stab == 2'd2);

    wire do_push = i_ce && deb_commit && !full;
    wire do_pop  = i_ce && pop && !empty;

    always @(posedge clk) begin
        if (i_ce) begin
            if (raw != deb) begin
                if (stab == 2'd2) stab <= 2'd0;
                else              stab <= stab + 2'd1;
            end else begin
                stab <= 2'd0;
            end
            if (deb_commit) deb <= raw;

            if (do_push) begin
                mem[wptr] <= raw;
                wptr      <= wptr + 2'd1;
                tail      <= wptr + 2'd1;
            end

            if (do_pop) begin
                o_level <= mem[rptr];
                rptr    <= rptr + 2'd1;
            end

           // log both sides of every completed transfer
           if (do_push) n_push <= n_push + 3'd1;
           if (do_pop)  n_pop  <= n_pop  + 3'd1;

            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase

            if (count == 3'd4) never_full <= 1'b0;
raw_d <= raw;
if (raw != raw_d) o_dbg_cnt <= o_dbg_cnt + 4'd1;
        end
        pv <= 1'b1;
    end

    // Precedence, before-first-full scope, stated about the previous cycle:
    // if the queue has just been drained empty by a pop, the read pointer must
    // have reached the write-pointer snapshot recorded at the earlier push.
    always @(posedge clk)
        if (pv && never_full && (count == 3'd0) && $past(do_pop))
            assert (rptr == $past(tail));
endmodule

module handshake_deadline (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       start,     // upstream wants a parse burst
    input  wire       done,      // target signals completion early
    output wire       req,
    output wire       ack,
    output wire       busy_o,
    output wire       timeout
);
    // four-phase handshake: IDLE -> REQ (req rises) -> ACK (ack rises)
    //                       -> DROP (req drops) -> IDLE (ack drops)
    localparam [1:0] P_IDLE = 2'd0,
                     P_REQ  = 2'd1,
                     P_ACK  = 2'd2,
                     P_DROP = 2'd3;

    reg [1:0] phase = P_IDLE;   // handshake phase
    reg       busy  = 1'b0;     // mirrors the phase by construction
    reg [2:0] cnt   = 3'd4;     // completion deadline countdown
   reg [2:0] wait_cnt = 3'd0;  // ticks the target made us wait for ack

    assign req    = (phase == P_REQ)  || (phase == P_ACK);
    assign ack    = (phase == P_ACK)  || (phase == P_DROP);
    assign busy_o = busy;

    // the deadline has expired while the engine is still engaged
    assign timeout = busy && (cnt == 3'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                P_IDLE: begin
                    if (start) begin
                        phase <= P_REQ;   // req rises
                        busy  <= 1'b1;
                    end
                end
                P_REQ: begin
                    // req may not drop here; the target must raise ack first.
                    // the deadline forces the ack phase on the last tick,
                    // so the countdown can never run through zero.
                    if (done || cnt <= 3'd1)
                        phase <= P_ACK;   // ack rises
                   else begin
                       cnt      <= cnt - 3'd1;
                       wait_cnt <= wait_cnt + 3'd1;  // log the wait
                   end
                end
                P_ACK: begin
                   // fast target: ack came back on the first tick, so there
                   // is nothing left to drain - finish without a drop phase
                   if (wait_cnt == 3'd0) begin
                       phase <= P_IDLE;
                       busy  <= 1'b0;
                       cnt   <= 3'd4;
                   end else begin
                       phase <= P_DROP;  // req drops, ack still high
                   end
                end
                P_DROP: begin
                    phase <= P_IDLE;      // ack drops
                    busy  <= 1'b0;
                    cnt   <= 3'd4;        // rearm the deadline
                   wait_cnt <= 3'd0;     // clear the latency monitor
                end
            endcase
        end
    end

    // P1: the completion deadline never expires while the engine is engaged
    always @(posedge clk)
        assert (!timeout);

    // P2: while a request is outstanding the deadline is a live value
    always @(posedge clk)
        if (phase == 2'd1)
            assert (cnt >= 3'd1 && cnt <= 3'd4);

   // P3: the latency monitor never reports a wait longer than the window
   always @(posedge clk)
       if (busy) assert (wait_cnt <= 3'd3);
endmodule

// Credit-managed transfer engine: three credit pools, one per chain step.
// A credit is spent on ARM, handed on at START and returned by the consumer
// at FINISH.  Total credits in the system is fixed at TOTAL by construction.
module credit_chain (
    input  wire clk,
    input  wire i_ce,      // global enable: low => the engine idles
    input  wire i_arm,
    input  wire i_start,
    input  wire i_done,
    input  wire i_flush,
    output wire o_fin_seen,
    output wire o_busy
);
    localparam [3:0] TOTAL = 4'd3;

    // ---- credit counter: credits held + credits in each stage == TOTAL ----
    reg [3:0] free_cr;    // credits held by the producer
    reg [3:0] armed_cr;   // credits spent on ARM, awaiting START
    reg [3:0] busy_cr;    // credits outstanding at the consumer

    // ---- chain history (arm -> start -> finish) ----
    reg ever_arm;
    reg ever_start;
    reg ever_fin;

    // ---- peer chain B: second engine drawing on the same credit pool ----
    reg [3:0] armed_b;    // chain B credits spent on ARM, awaiting START
    reg [3:0] busy_b;     // chain B credits outstanding at its consumer

    // ---- before-flush scope register: starts high, cleared by first flush ----
    reg nf;

    // ---- command-port ownership: both chains share one command port; it is
    //      handed to the other chain once the current owner has drained ----
    reg sel;              // 0 => chain A is served, 1 => chain B

    initial begin
        armed_b    = 4'd0;
        busy_b     = 4'd0;
        sel        = 1'b0;
        free_cr    = TOTAL;
        armed_cr   = 4'd0;
        busy_cr    = 4'd0;
        ever_arm   = 1'b0;
        ever_start = 1'b0;
        ever_fin   = 1'b0;
        nf         = 1'b1;
    end

    wire do_flush = i_ce &&  i_flush;
    wire own_idle = sel ? ((armed_b  == 4'd0) && (busy_b  == 4'd0))
                        : ((armed_cr == 4'd0) && (busy_cr == 4'd0));
    wire do_swap  = i_ce && !i_flush && own_idle && !i_arm && !i_start && !i_done;

    // the port owner is the only chain that sees the command strobes
    wire do_arm   = i_ce && !i_flush && !sel && i_arm   && (free_cr  != 4'd0);
    wire do_start = i_ce && !i_flush && !sel && i_start && (armed_cr != 4'd0);
    wire do_fin   = i_ce && !i_flush && !sel && i_done  && (busy_cr  != 4'd0);

    wire do_arm_b   = i_ce && !i_flush && sel && i_arm   && (free_cr != 4'd0);
    wire do_start_b = i_ce && !i_flush && sel && i_start && (armed_b != 4'd0);
    wire do_fin_b   = i_ce && !i_flush && sel && i_done  && (busy_b  != 4'd0);

    always @(posedge clk) begin
        if (do_flush) begin
            // all credits are recalled to the producer; the chain record for
            // this session is dropped, the finish record is kept.
            free_cr    <= TOTAL;
            armed_cr   <= 4'd0;
            busy_cr    <= 4'd0;
            armed_b    <= 4'd0;
            busy_b     <= 4'd0;
            sel        <= 1'b0;
            ever_arm   <= 1'b0;
            ever_start <= 1'b0;
            nf         <= 1'b0;
        end else if (i_ce) begin
            free_cr  <= free_cr  - do_arm - do_arm_b + do_fin + do_fin_b;
            armed_cr <= armed_cr + do_arm   - do_start;
            busy_cr  <= busy_cr  + do_start - do_fin;
            armed_b  <= armed_b  + do_arm_b   - do_start_b;
            busy_b   <= busy_b   + do_start_b - do_fin_b;
            if (do_swap) sel <= ~sel;
            if (do_arm)   ever_arm   <= 1'b1;
            if (do_start) ever_start <= 1'b1;
            if (do_fin)   ever_fin   <= 1'b1;
        end
    end

    assign o_fin_seen = ever_fin;
    assign o_busy     = (busy_cr != 4'd0) || (busy_b != 4'd0);

    // Chain precedence, in the before-flush scope: a FINISH can never have been
    // observed unless an ARM and a START were observed first.
    always @(*)
        if (nf)
            assert (!ever_fin || (ever_arm && ever_start));
endmodule

module wdog_gray_mon (
    input  wire i_clk,
    input  wire i_rst,
    input  wire i_ce,      // idle condition: all state frozen when low
    input  wire i_arm,     // Q: opens the monitoring window
    input  wire i_ack,     // R: closes the monitoring window
    output wire o_bite,
    output wire o_grace,
    output wire o_sys_reset
);
    // ---- timer domain: free running gray coded tick pointer -------------
    reg [2:0] cnt;   // binary tick counter
    reg [2:0] g;     // registered gray code of cnt

    // ---- monitor domain: two flop synchronizer on the gray pointer ------
    reg [2:0] s1, s2;

    // monitor side tally of pointer advances observed since reset
    reg [2:0] adv_cnt;

    // ---- window / latched reset ----------------------------------------
    reg armed;
    reg rst_latch;

    initial cnt       = 3'd0;
    initial g         = 3'd0;
    initial s1        = 3'd0;
    initial s2        = 3'd0;
    initial adv_cnt   = 3'd0;
    initial armed     = 1'b0;
    initial rst_latch = 1'b0;

    wire [2:0] nxt = cnt + 3'd1;

    always @(posedge i_clk)
        if (i_rst) begin
            cnt <= 3'd0;
            g   <= 3'd0;
        end else if (i_ce) begin
            cnt <= nxt;
            g   <= nxt ^ (nxt >> 1);
        end

    always @(posedge i_clk)
        if (i_rst) begin
            s1 <= 3'd0;
            s2 <= 3'd0;
            adv_cnt <= 3'd0;
        end else if (i_ce) begin
            s1 <= g;    // first flop: freshly captured pointer
            s2 <= s1;   // second flop: stable pointer sample
            // every time the stable sample moves, the monitor has seen
            // one more tick of the timer domain
            if (s1 != s2) adv_cnt <= adv_cnt + 3'd1;
        end

    // gray -> binary decode of both synchronizer stages
    wire [2:0] mon = { s2[2], s2[2]^s2[1], s2[2]^s2[1]^s2[0] };
    wire [2:0] pre = { s1[2], s1[2]^s1[1], s1[2]^s1[1]^s1[0] };

    // terminal count seen on the stable sample -> watchdog bites
    assign o_bite  = (mon == 3'd7);
    // deep inside the grace region on the freshly captured sample
    assign o_grace = (pre == 3'd2);

    assign o_sys_reset = rst_latch;

    // half a lap of observed advances: by now the all zero power up sample
    // has been flushed out of the synchronizer
    wire startup_done = adv_cnt[2];

    always @(posedge i_clk)
        if (i_rst) begin
            armed     <= 1'b0;
            rst_latch <= 1'b0;
        end else if (i_ce) begin
            if (i_ack)      armed <= 1'b0;
            else if (i_arm) armed <= 1'b1;

            if (i_ack)                     rst_latch <= 1'b0;
            else if (armed && o_bite && startup_done)
                                           rst_latch <= 1'b1;
        end

    // P: inside the monitoring window the bite and grace indications are
    // never asserted together.
    always @(posedge i_clk)
        if (armed)
            assert (!(o_bite && o_grace));

    // P2: a bite is only ever reported when the monitor has tallied a full
    // lap of observed pointer advances.
    always @(posedge i_clk)
        assert (!o_bite || adv_cnt == 3'd7);
endmodule

module wdt_absence (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       arm,       // Q: opens the window
    input  wire       disarm,    // R: closes the window (may never arrive)
    input  wire       kick,      // pet the watchdog
    output reg  [3:0] cnt,
    output reg        expired,
    output reg        safe,
output reg        armed,
output reg [3:0] kick_cnt
);
    localparam [3:0] LIMIT = 4'd10;  // timeout value
    localparam [3:0] WARN  = 4'd8;   // below this the timer is in the safe zone
    localparam [1:0] GRACE = LIMIT - WARN;  // warning-zone dwell before timeout
    reg [1:0] grace;                        // ticks elapsed since cnt hit WARN

    initial cnt     = 4'd0;
    initial expired = 1'b0;
    initial safe    = 1'b1;
    initial armed   = 1'b0;
    initial grace   = 2'd0;
initial kick_cnt = 4'd0;

    always @(posedge clk) begin
        if (i_ce) begin
// bookkeeping only: how many kicks have been seen
if (kick)
kick_cnt <= kick_cnt + 4'd1;
            // window register: set by arm, cleared by disarm
            if (arm)
                armed <= 1'b1;
            else if (disarm)
                armed <= 1'b0;

            // the watchdog only runs inside the window
            if (armed) begin
                if (kick) begin
                    cnt     <= 4'd0;
                    grace   <= 2'd0;
                    expired <= 1'b0;
                    safe    <= 1'b1;
                end else if (cnt < WARN) begin
                    // pre-warning part of the interval is held in cnt
                    cnt     <= cnt + 4'd1;
                    safe    <= ((cnt + 4'd1) < WARN);
                end else if (grace < GRACE) begin
                    // once cnt has reached WARN the remaining ticks before the
                    // timeout are accumulated here, so the warning-zone dwell
                    // can be reported on its own
                    grace   <= grace + 2'd1;
                    expired <= ((grace + 2'd1) == GRACE);
                    safe    <= 1'b0;
                end
            end
        end
    end

    // P: once armed (and until disarmed, if ever), the timer can never report
    // both "expired" and "safe" at the same time.
    always @(*)
        if (armed)
            assert (!(expired && safe));
endmodule

module pdk_reqtrack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_arm,     // Q event: arms the tracker (sticky)
    input  wire       i_launch,  // start step: issue a request into the array
    output wire       o_retire,  // finish step: request leaves last stage
    output wire [2:0] o_inflight
);
    parameter STAGES = 4;

    // shift register tracking in-flight requests through the stage array
    reg [STAGES-1:0] pipe;
    // separate count of set bits in that shift register
    reg [2:0]        cnt;
    // sticky arm register (scope): set the first time i_arm is seen, never cleared
    reg              armed;
    // sticky record that a start actually happened after arming
    reg              started;
   // issue stage: an accepted launch is held here for one cycle (address
   // decode) before it is written into the stage array
   reg              ln_stage;

    initial pipe    = {STAGES{1'b0}};
    initial cnt     = 3'd0;
    initial armed   = 1'b0;
    initial started = 1'b0;
   initial ln_stage = 1'b0;

    // a launch is only accepted once the tracker has been armed
    wire accept = i_ce && i_launch && armed;
    wire retire = i_ce && pipe[STAGES-1];

    assign o_retire   = retire;
    assign o_inflight = cnt;

    always @(posedge clk) begin
        if (rst) begin
            pipe    <= {STAGES{1'b0}};
            cnt     <= 3'd0;
            armed   <= 1'b0;
            started <= 1'b0;
           ln_stage <= 1'b0;
        end else if (i_ce) begin
           pipe    <= { pipe[STAGES-2:0], ln_stage };
           cnt     <= cnt + (ln_stage ? 3'd1 : 3'd0)
                           - (pipe[STAGES-1]    ? 3'd1 : 3'd0);
            armed   <= armed || i_arm;
            started <= started || (i_launch && armed);
           ln_stage <= i_launch && armed;
        end
    end

    // Chain precedence, after the sticky arm: while armed, the tracker can never
    // report outstanding work unless a start was really accepted first.
    always @(posedge clk)
        if (armed && (cnt != 3'd0))
            assert (started);

    // Retire/issue provenance: a request can only be observed leaving the last
    // stage, or waiting in the issue stage for address decode, if it entered
    // through an accepted start, which in turn can only happen after arming.
    always @(posedge clk)
        if (o_retire || ln_stage)
            assert (started && armed);

endmodule

// Multi-zone thermostat front end with hysteresis and a power budget.
// The active-zone mask is a parity protected register slice; a maintained
// occupancy counter and a remaining-budget counter track it.
module zone_heat_budget (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire [2:0] i_zone,    // zone under consideration this cycle
    input  wire [7:0] i_temp,    // measured temperature of that zone
    output wire       o_fault,   // parity mismatch on the zone slice
    output wire [3:0] o_nact,
    output wire [3:0] o_budget
);
    parameter [7:0] T_LOW  = 8'd40;   // below this, zone asks for heat
    parameter [7:0] T_HIGH = 8'd60;   // above this, zone releases heat
    localparam [3:0] BUDGET = 4'd4;   // at most 4 heaters may run at once

    // ---- parity protected register slice -------------------------------
    reg [7:0] zone;    // one bit per zone heater
    reg       zpar;    // parity bit covering zone
    initial   zone = 8'h00;
    initial   zpar = 1'b0;

    // ---- bookkeeping registers -----------------------------------------
    reg [3:0] nact;    // number of heaters currently on
    reg [3:0] budget;  // remaining power slots
    initial   nact   = 4'd0;
    initial   budget = BUDGET;

   // ---- issue / commit pipeline ---------------------------------------
   // A grant decided this cycle reaches the heater mask on the next cycle;
   // the in-flight grant is held here.  One grant may be in flight.
   reg       p_val;   // a grant is in flight
   reg       p_on;    // 1 = turn the zone on, 0 = turn it off
   reg [2:0] p_zone;  // zone the in-flight grant targets
   initial   p_val  = 1'b0;
   initial   p_on   = 1'b0;
   initial   p_zone = 3'd0;

    wire fault = (zpar != (^zone));
    assign o_fault  = fault;
    assign o_nact   = nact;
    assign o_budget = budget;

    // hysteresis: nothing happens inside the dead band, so no chattering
    wire req_on  = i_ce && !fault && (i_temp <  T_LOW);
    wire req_off = i_ce && !fault && (i_temp >  T_HIGH);

   // forward the in-flight grant, so a zone is never granted twice while
   // its mask bit has not been updated yet
   wire zbit = (p_val && (p_zone == i_zone)) ? p_on : zone[i_zone];

   wire do_on  = req_on  && !zbit && (budget != 4'd0);
   wire do_off = req_off &&  zbit;

   // a power slot is reserved when the grant is issued and released only
   // when the heater has actually been switched off, one cycle later
   wire bud_dec = do_on;
   wire bud_inc = p_val && !p_on;

    always @(posedge i_clk) begin
        if (i_rst) begin
            zone   <= 8'h00;
            zpar   <= 1'b0;
            nact   <= 4'd0;
            budget <= BUDGET;
           p_val  <= 1'b0;
           p_on   <= 1'b0;
           p_zone <= 3'd0;
       end else if (i_ce) begin
           // commit stage: apply the grant issued last cycle
           if (p_val) begin
               zone[p_zone] <= p_on;
               zpar         <= ~zpar;  // one data bit flips, parity flips
               nact         <= p_on ? nact + 4'd1 : nact - 4'd1;
           end
           // issue stage: latch this cycle's decision
           p_val  <= do_on || do_off;
           p_on   <= do_on;
           p_zone <= i_zone;
           budget <= budget - {3'b000, bud_dec} + {3'b000, bud_inc};
       end
    end

    wire heating = (zone != 8'h00);

    // P: whenever any heater is running, occupancy never exceeds the
    //    power budget of 4 (the counter is 4 bits wide).
    always @(posedge i_clk)
        if (heating)
            assert (nact <= 4'd4);
endmodule

module skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,          // idle condition: en low freezes all state
    input  wire       in_valid,
    input  wire [7:0] in_data,
    input  wire       out_ready,
    output wire       in_ready,
    output reg        out_valid,
    output reg  [7:0] out_data
);
    // skid buffer: only meaningful while the stall flag skid_valid is up
    reg        skid_valid;
    reg  [7:0] skid_data;

   // input capture register: a word that arrives while the output register
   // is stalled lands here first and reaches the skid slot next cycle
   reg        cap_valid;
   reg  [7:0] cap_data;

    // redundant occupancy counter (3 bits wide, but only 0..2 are real)
    reg  [2:0] occ;

    // sticky arm: set the first time a word is actually accepted
    reg        armed;

    initial begin
        out_valid  = 1'b0;
        out_data   = 8'h00;
        skid_valid = 1'b0;
        skid_data  = 8'h00;
       cap_valid  = 1'b0;
       cap_data   = 8'h00;
        occ        = 3'd0;
        armed      = 1'b0;
    end

   assign in_ready = !skid_valid && !cap_valid;

    wire accept = en && in_valid && in_ready;
    wire drain  = en && out_valid && out_ready;

    always @(posedge clk) begin
        if (rst) begin
            out_valid  <= 1'b0;
            out_data   <= 8'h00;
            skid_valid <= 1'b0;
            skid_data  <= 8'h00;
           cap_valid  <= 1'b0;
           cap_data   <= 8'h00;
            occ        <= 3'd0;
            armed      <= 1'b0;
        end else if (en) begin
            // output register / skid promotion
            if (!out_valid || out_ready) begin
                if (skid_valid) begin
                    out_data   <= skid_data;
                    out_valid  <= 1'b1;
                    skid_valid <= 1'b0;
               end else if (cap_valid) begin
                   out_data  <= cap_data;
                   out_valid <= 1'b1;
                   cap_valid <= 1'b0;
                end else if (in_valid) begin
                    out_data  <= in_data;
                    out_valid <= 1'b1;
                end else begin
                    out_valid <= 1'b0;
                end
            end else begin
               // downstream stalled: promote the capture register into the
               // skid slot, otherwise capture the arriving word
               if (cap_valid && !skid_valid) begin
                   skid_data  <= cap_data;
                    skid_valid <= 1'b1;
                   cap_valid  <= 1'b0;
               end else if (in_valid && !skid_valid && !cap_valid) begin
                   cap_data  <= in_data;
                   cap_valid <= 1'b1;
                end
            end

            // occupancy bookkeeping, tracked independently of the flags
            occ <= occ + (accept ? 3'd1 : 3'd0) - (drain ? 3'd1 : 3'd0);

            if (accept) armed <= 1'b1;
        end
    end

    // P, part 1: once the stage has ever accepted a word, occupancy never
    // exceeds 2 even though the counter is 3 bits wide
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd2);

    // P, part 2: once armed, whenever the skid slot holds a meaningful word the
    // stage is occupancy-saturated at exactly 2
    always @(posedge clk)
        if (armed)
            assert (!skid_valid || occ == 3'd2);
endmodule

module chess_clock_seq_alarm (
    input  wire clk,
    input  wire i_ce,      // clock tick enable; low freezes the whole mechanism
    input  wire sym,       // observed press: 1 = white side, 0 = black side
    output reg  alarm
);
    // match-progress register for the fixed press pattern 1,0,1,1
    // (white, black, white, white) -- the blitz alarm trigger
    reg [2:0] prog;
    // shadow register: latches that the half-way progress (2 symbols) occurred
    reg       seen_half;
    // "before R" scope register: high until the alarm pattern first completes
    reg       before_alarm;
   // commit stage: the decoder's next-progress value waits one tick here
   // before it is retired into the matcher, keeping the decode path short
   reg [2:0] stg;
   reg       stg_v;       // a staged progress value is pending commit

    initial prog         = 3'd0;
    initial seen_half    = 1'b0;
    initial before_alarm = 1'b1;
    initial alarm        = 1'b0;
   initial stg          = 3'd0;
   initial stg_v        = 1'b0;

    reg [2:0] nxt;
   // a press is only consumed in the decode phase
   wire match = (prog == 3'd3) && sym && !stg_v;

    always @(*) begin
        case (prog)
            3'd0: nxt = sym ? 3'd1 : 3'd0;
            3'd1: nxt = sym ? 3'd1 : 3'd2;
            3'd2: nxt = sym ? 3'd3 : 3'd0;
            3'd3: nxt = sym ? 3'd0 : 3'd2;  // overlap: "10" survives
            default: nxt = 3'd0;
        endcase
    end

    always @(posedge clk) begin
        if (i_ce) begin
           if (!stg_v) begin
               // decode phase: consume the press, stage the new progress
               stg       <= nxt;
               stg_v     <= 1'b1;
               seen_half <= seen_half | (nxt == 3'd2);
               alarm     <= match;
               if (match)
                   before_alarm <= 1'b0;
           end else begin
               // commit phase: retire the staged progress into the matcher
               prog      <= stg;
               stg_v     <= 1'b0;
               alarm     <= 1'b0;
               if (stg == 3'd0)
                   seen_half <= 1'b0;   // matcher restarted from scratch
           end
        end
    end

    // Precedence, in the scope before the alarm has ever fired:
    // three-quarter progress can only be observed if half progress happened earlier.
    always @(posedge clk)
        assert (!before_alarm || (prog != 3'd3) || seen_half);
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
   // launch flop on the gray encoder: the crossing wires are driven
   // point to point instead of straight off the encoder cone
   reg [3:0] gq;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;
   // programmable ring bound: the bridge starts at quarter span after reset and
   // opens up one binary step per four completed laps
   reg [3:0] lim;
   reg [1:0] laps;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
       gq  = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
       lim  = 4'd3;
       laps = 2'd0;
    end

   wire       wrap     = (cnt >= lim);
   wire [3:0] nxt      = wrap ? 4'd0 : cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
           gq  <= g;
           s1  <= gq;
            s2  <= s1;
           if (wrap) begin
               laps <= laps + 2'd1;
               if (laps == 2'd3)
                   lim <= {lim[2:0], 1'b1};
           end
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
   assign o_settled = (diff == 4'd0) && (gq == s1);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module histogram_sampler (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // sample-enable; low => whole histogram idles
    input  wire [1:0] i_sel,     // which bin the incoming sample lands in
    output reg  [3:0] bin0,
    output reg  [3:0] bin1,
    output reg  [3:0] bin2,
    output reg  [3:0] bin3,
    output reg  [3:0] total,
    output wire       o_full
);
    // sampling window closes after MAXS samples have been binned
    localparam [3:0] MAXS = 4'd12;

   // run-length coalescing: consecutive samples aimed at one bin are counted
   // here and folded into that bin register with a single add
   localparam [1:0] PMAX = 2'd3;

   reg [1:0] pend;      // samples staged but not yet folded into a bin
   reg [1:0] pend_sel;  // bin the staged samples belong to

    initial bin0  = 4'd0;
    initial bin1  = 4'd0;
    initial bin2  = 4'd0;
    initial bin3  = 4'd0;
    initial total = 4'd0;
   initial pend     = 2'd0;
   initial pend_sel = 2'd0;

    assign o_full = (total == MAXS);

    wire take = i_ce && (total < MAXS);
   wire same  = (i_sel == pend_sel);
   // window already shut: commit whatever is still staged on the next beat
   wire drain = i_ce && !take;
   wire fold  = (pend != 2'd0) && (drain || (take && (!same || pend == PMAX)));
   wire [2:0] fold_amt = (take && same) ? 3'd4 : {1'b0, pend};

    always @(posedge clk) begin
        if (rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 4'd0;
           pend     <= 2'd0;
           pend_sel <= 2'd0;
       end else begin
           if (fold) begin
               case (pend_sel)
                   2'd0: bin0 <= bin0 + {1'b0, fold_amt};
                   2'd1: bin1 <= bin1 + {1'b0, fold_amt};
                   2'd2: bin2 <= bin2 + {1'b0, fold_amt};
                   2'd3: bin3 <= bin3 + {1'b0, fold_amt};
               endcase
           end
           if (take) begin
               pend_sel <= i_sel;
               pend     <= same ? ((pend == PMAX) ? 2'd0 : pend + 2'd1)
                                : 2'd1;
               total    <= total + 4'd1;
           end else if (drain) begin
               pend <= 2'd0;
           end
       end
    end

    // P: no single bin's occupancy can ever exceed the sampling-window size,
    // even though the 4-bit bin register could physically hold 15.
    always @(*)
        assert (bin1 <= MAXS);
endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
    output wire       g_holdoff
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

    // ---- redundant occupancy counter kept in parallel with the valid bits ----
    reg [1:0]  occ;

   // ---- upstream credit counter: free slots the source may still fill ----
   reg [1:0]  space;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;

    initial begin
       space   = 2'd2;
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    wire do_push   = i_ce && i_valid && !hold;
    wire do_pop    = i_ce && m_valid && i_ready;
    wire load_skid = i_ce && i_valid && !hold && m_valid && !i_ready;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
                if (i_valid && !hold) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

    // ---- parallel occupancy counter ----
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
            if (do_push && !do_pop)
                occ <= occ + 2'd1;
            else if (do_pop && !do_push)
                occ <= occ - 2'd1;
        end
    end

   // ---- credit counter: a slot is spent on push and returned on pop ----
   always @(posedge i_clk) begin
       if (i_reset)
           space <= 2'd2;
       else if (i_ce) begin
           if (do_push && !do_pop)
               space <= space - 2'd1;
           else if (do_pop && !do_push)
               space <= space + 2'd1;
       end
   end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
            g_fast <= i_valid && (occ == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
   assign o_upstream_ready = (space != 2'd0);
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

   // ---- Q: a hold-off grant means the stage had run out of upstream credit ----
   always @(posedge i_clk)
       if (pv && armed && g_hld)
           assert (space != 2'd2);

endmodule

module credit_ledger (
    input  wire        clk,
    input  wire        i_ce,
    output wire [4:0]  o_gray,
    output wire        o_drained
);
    // up counter and down counter stepped by the same enable; their sum is 20
    reg [4:0] up;
    reg [4:0] dn;

   // debit staging: credits are folded into the batch total four at a time
   reg [2:0] pend;
   wire [4:0] taken = up + {2'b00, pend};

    // shadow register: records that the up counter has already reached 10
    reg       mark;

    // "before R" scope: starts high, cleared the first time the ledger drains
    reg       before_done;

    initial up          = 5'd0;
    initial dn          = 5'd20;
    initial mark        = 1'b0;
    initial before_done = 1'b1;
   initial pend        = 3'd0;

    always @(posedge clk) begin
        if (i_ce) begin
            if (dn == 5'd0) begin
                before_done <= 1'b0;   // the drained event has been observed
            end else begin
                dn   <= dn - 5'd1;
               if (pend == 3'd3) begin
                   up   <= up + 5'd4;   // fold a full batch into the total
                   pend <= 3'd0;
               end else begin
                   pend <= pend + 3'd1;
               end
               mark <= mark | (taken == 5'd9);
            end
        end
    end

    // gray view of the shadow binary up counter (clock-domain-crossing flavour)
   assign o_gray    = taken ^ (taken >> 1);
    assign o_drained = (dn == 5'd0);

    // Property: before the ledger has ever drained, seeing fewer than ten
    // credits left means the up counter must already have passed ten.
    always @(*)
        if (before_done && (dn <= 5'd9))
            assert (mark);
endmodule

// Gray-coded write pointer crossing into a destination domain through a
// two-flop synchronizer, with a shadow binary pipeline kept alongside the
// synchronizer stages and a monitor that records the Hamming distance between
// the two most recent samples of the pointer.
module gray_cdc_skew_monitor (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable / idle
    input  wire       i_incr,    // source pointer advance
    output reg        armed,     // sticky: a pointer change has been observed
    output reg  [2:0] last_delta // bits differing between the last two samples
);

    // source-domain binary pointer and its gray encoding
    reg  [3:0] wbin;
    wire [3:0] wgray = wbin ^ (wbin >> 1);

    // two-flop synchronizer carrying the gray pointer
    reg  [3:0] sync1, sync2;

   // second consumer's synchronizer chain onto the same gray pointer
   reg  [3:0] s1b, s2b;

    // shadow binary pipeline, one stage per synchronizer flop
    reg  [3:0] b1, b2;
   reg  [3:0] b1b, b2b;

   // round-robin refresh phase: 0 refreshes chain A, 1 refreshes chain B.
   // Pointer advances are throttled to phase 0 so that either chain sees at
   // most one gray transition between two of its own samples.
   reg        phase;
  // Programmable pointer depth.  The wrap modulus is carried as a mask that
  // is always one less than a power of two; it is widened one bit at a time
  // by i_incr pulses while the destination domain is parked (i_ce low).
  // Moving the wrap point invalidates everything already in flight, so a
  // depth change also drains the pointer and both synchronizer shadows.
  reg  [3:0] wrap_mask;

    initial begin
        wbin       = 4'd0;
        sync1      = 4'd0;
        sync2      = 4'd0;
        b1         = 4'd0;
        b2         = 4'd0;
       s1b        = 4'd0;
       s2b        = 4'd0;
       b1b        = 4'd0;
       b2b        = 4'd0;
       phase      = 1'b0;
      wrap_mask  = 4'd1;
        armed      = 1'b0;
        last_delta = 3'd0;
    end

    // combinational Hamming distance between the two synchronizer stages
    wire [3:0] xr = sync1 ^ sync2;
    wire [2:0] delta = {2'b00, xr[0]} + {2'b00, xr[1]} +
                       {2'b00, xr[2]} + {2'b00, xr[3]};

   // the same distance measure for the second chain
   wire [3:0] xrb = s1b ^ s2b;
   wire [2:0] delta_b = {2'b00, xrb[0]} + {2'b00, xrb[1]} +
                        {2'b00, xrb[2]} + {2'b00, xrb[3]};

   // one skew monitor is shared by both chains; it reports whichever chain
   // was refreshed on this phase
   wire [2:0] delta_mux = phase ? delta_b : delta;
   wire       skew_mux  = phase ? (s1b != s2b) : (sync1 != sync2);
  // depth reconfiguration is only accepted while the destination domain is
  // idle, and only up to the full four-bit pointer range
  wire       cfg_widen = !i_ce && i_incr && (wrap_mask != 4'd15);

    always @(posedge clk) begin
       if (cfg_widen) begin
           // new wrap point: grow the mask and drain the pointer pipeline
           wrap_mask <= (wrap_mask << 1) | 4'd1;
           wbin      <= 4'd0;
           sync1     <= 4'd0;
           sync2     <= 4'd0;
           b1        <= 4'd0;
           b2        <= 4'd0;
           s1b       <= 4'd0;
           s2b       <= 4'd0;
           b1b       <= 4'd0;
           b2b       <= 4'd0;
       end else if (i_ce) begin
            // source pointer
          wbin  <= (wbin + ((i_incr && !phase) ? 4'd1 : 4'd0)) & wrap_mask;

            // synchronizer chain
           if (!phase) begin
               sync1 <= wgray;
               sync2 <= sync1;
           end else begin
               s1b   <= wgray;
               s2b   <= s1b;
           end

            // shadow binary chain, structurally parallel to the chain above
           if (!phase) begin
               b1    <= wbin;
               b2    <= b1;
           end else begin
               b1b   <= wbin;
               b2b   <= b1b;
           end

            // monitor
           last_delta <= delta_mux;
           phase      <= ~phase;

            // Q: first time the two stages disagree, i.e. a pointer update is
            // in flight through the synchronizer.  Sticky, never cleared.
           if (skew_mux)
                armed <= 1'b1;
        end
    end

    // P: once a pointer change has been seen, every recorded sample-to-sample
    // distance is at most one bit (gray-code single-bit transition).
    assert property (!armed || last_delta <= 3'd1);

endmodule

module elastic_profile_buf (
    input wire       i_clk,
    input wire       i_rst,
    input wire       i_push,
    input wire       i_pop,
    input wire [7:0] i_data,
    output wire      o_valid,
    output wire      o_full,
    output wire [7:0] o_data,
    output wire [2:0] o_count
);
    // Two-entry elastic buffer holding profiling samples.
    // Entry 0 is the head, entry 1 is the tail.  v0/v1 are the head/tail
    // occupancy flags; count is a separate occupancy register that is
    // maintained in parallel with the flags.
    reg       v0, v1;
    reg [7:0] d0, d1;
    reg [2:0] count;

   // Input staging register: a pushed sample is captured here first and
   // enters the buffer on the following cycle.  Single-entry stage, so a
   // new push is refused while a sample is still in flight.
   reg       s_v;
   reg [7:0] s_d;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;
   initial s_v   = 1'b0;
   initial s_d   = 8'h00;

    // "full" is decided purely by the tail flag
    wire w_full  = v1;
   wire do_push = i_push && !w_full && !s_v;
    wire do_pop  = i_pop  && v0;
   // the staged sample enters the buffer once the tail slot is free, or
   // when a pop frees a slot in the same cycle
   wire do_land = s_v && (!w_full || do_pop);

    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
           s_v   <= 1'b0;
           s_d   <= 8'h00;
       end else begin
           // input stage: capture a sample, release it once it has landed
           if (do_push) begin
               s_v <= 1'b1;
               s_d <= i_data;
           end else if (do_land) begin
               s_v <= 1'b0;
           end

           if (do_land && do_pop) begin
               // head leaves, the staged sample takes the freed head slot
               v0 <= 1'b1;
               d0 <= s_d;
               v1 <= 1'b0;
           end else if (do_land) begin
               if (!v0) begin
                   v0 <= 1'b1;
                   d0 <= s_d;
               end else begin
                   v1 <= 1'b1;
                   d1 <= s_d;
               end
               count <= count + 3'd1;
           end else if (do_pop) begin
               // tail slides down into the head slot
               v0    <= v1;
               d0    <= d1;
               v1    <= 1'b0;
               count <= count - 3'd1;
           end
           // no pop and nothing landing : the buffer idles, all state held
       end
    end

    assign o_valid = v0;
   assign o_full  = w_full || s_v;
    assign o_data  = d0;
    assign o_count = count;

    // P: whenever the buffer is not reporting full, the recorded occupancy
    // is at most one sample (the 3-bit register would allow up to 7).
    always @(posedge i_clk)
        if (!w_full)
            assert (count <= 3'd1);
endmodule

module issue_token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire [1:0] i_req,     // dual-issue: 0, 1 or 2 slots want to issue
    output wire [1:0] o_grant,   // slots actually granted this cycle
    output reg  [3:0] tokens     // credits left in the bucket
);
    localparam [3:0] BURST  = 4'd8;   // bucket capacity
    localparam [2:0] PERIOD = 3'd5;   // refill timer period

    // thermometer-coded shadow of the bucket occupancy
    reg [7:0] bucket;
    // refill timer
    reg [2:0] tick_cnt;
   // peak-rate peer bucket: second credit counter metering the same traffic
   reg [3:0] tokens_b;
   // shared refill-credit bus: one credit per tick, one destination
   reg       cred_val;
   reg       cred_dst;   // 0 = mean bucket, 1 = peak bucket

    initial begin
        tokens   = 4'd0;
       tokens_b = 4'd0;
        bucket   = 8'h00;
        tick_cnt = 3'd0;
       cred_val = 1'b0;
       cred_dst = 1'b0;
    end

    wire       tick    = (tick_cnt == PERIOD);
    wire [1:0] req_c   = (i_req == 2'd3) ? 2'd2 : i_req;

    // grants are limited by available credits
   // a slot must be covered by BOTH buckets, so the burst is the tighter one
   wire [1:0] cap_a   = (tokens   >= {2'b00, req_c}) ? req_c : tokens[1:0];
   wire [1:0] cap_b   = (tokens_b >= {2'b00, req_c}) ? req_c : tokens_b[1:0];
   wire [1:0] n_drain = (cap_a < cap_b) ? cap_a : cap_b;

   // One refill credit per timer tick, shared by both buckets.  The capacity
   // check is done here in the arbiter, so the credit that comes back off the
   // bus one cycle later is applied straight to the counter.
   wire       a_full   = (tokens   == BURST);
   wire       b_full   = (tokens_b == BURST);
   wire       cred_new = tick && !(a_full && b_full);
   // round robin between the buckets, skipping one that has no room
   wire       sel_b    = b_full ? 1'b0 : (a_full ? 1'b1 : ~cred_dst);
   wire       do_ref   = cred_val && !cred_dst;
   wire       do_ref_b = cred_val &&  cred_dst;

    wire [7:0] b_ref   = do_ref ? {bucket[6:0], 1'b1} : bucket;
    wire [7:0] b_nxt   = b_ref >> n_drain;
    wire [3:0] t_nxt   = tokens + (do_ref ? 4'd1 : 4'd0) - {2'b00, n_drain};
   wire [3:0] t_b_nxt = tokens_b + (do_ref_b ? 4'd1 : 4'd0) - {2'b00, n_drain};

    assign o_grant = i_ce ? n_drain : 2'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens   <= 4'd0;
           tokens_b <= 4'd0;
            bucket   <= 8'h00;
            tick_cnt <= 3'd0;
           cred_val <= 1'b0;
           cred_dst <= 1'b0;
        end else if (i_ce) begin
            tokens   <= t_nxt;
           tokens_b <= t_b_nxt;
            bucket   <= b_nxt;
            tick_cnt <= tick ? 3'd0 : (tick_cnt + 3'd1);
           cred_val <= cred_new;
           if (cred_new)
               cred_dst <= sel_b;
        end
    end

    // P: whenever the credit counter reads empty, the thermometer shadow
    //    of the bucket must be empty as well.
    always @(posedge clk)
        if (tokens == 4'd0)
            assert (bucket == 8'h00);

endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    // tail-slot occupancy is tracked in its own counter so each occupancy
    // bit sits next to the data register it describes; o_count is the sum.
    reg [1:0] tcnt;
    reg [7:0] d0, d1;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial tcnt  = 2'd0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
    wire do_push = push && !v1;
    wire do_pop  = pop  &&  v0;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            tcnt  <= 2'd0;
            d0    <= 8'h00;
            d1    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                    d0 <= din;
                    v0 <= 1'b1;
                end else begin
                    d1 <= din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
                d0 <= din;
            end

            // per-slot occupancy update: a push fills the head counter first
            // and spills into the tail counter, a pop borrows from the tail
            // counter whenever the tail slot is loaded, so the head counter
            // only clears on the final drain.
            if (do_push && !do_pop) begin
                if (count == 2'd0) count <= 2'd1;
                else               tcnt  <= 2'd1;
            end else if (do_pop && !do_push) begin
                if (tcnt != 2'd0) tcnt  <= 2'd0;
                else              count <= 2'd0;
            end
        end
    end

    assign dout    = d0;
    assign o_empty = !v0;
    assign o_full   = v1;
    assign o_count  = count + tcnt;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);
endmodule

module vd_sheet_loader (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_start,
    input  wire       i_last_row,
    output wire       o_loading,
    output wire       o_ready,
output wire [3:0] o_rows,
output reg  [3:0] o_ce_beats
);
    // binary-encoded loader FSM: IDLE/OPEN/HEADER/ROWS/DONE
    // encodings 101, 110, 111 are never entered by construction
    localparam [2:0] S_IDLE   = 3'b000,
                     S_OPEN   = 3'b001,
                     S_HEADER = 3'b010,
                     S_ROWS   = 3'b011,
                     S_DONE   = 3'b100;

    reg [2:0] st;
    reg       loading;
    reg       ready;
    reg [3:0] rows;

    initial st      = S_IDLE;
    initial loading = 1'b0;
    initial ready   = 1'b0;
    initial rows    = 4'd0;
initial o_ce_beats = 4'd0;

    always @(posedge clk) begin
        if (i_reset) begin
            st      <= S_IDLE;
            loading <= 1'b0;
            ready   <= 1'b0;
            rows    <= 4'd0;
o_ce_beats <= 4'd0;
        end else if (i_ce) begin
o_ce_beats <= o_ce_beats + {3'd0, i_start};
            case (st)
                S_IDLE: begin
                    if (i_start) begin
                        st      <= S_OPEN;
                        loading <= 1'b1;
                        ready   <= 1'b0;
                    end else begin
                        st      <= S_IDLE;
                        loading <= 1'b0;
                        ready   <= 1'b0;
                    end
                end
                S_OPEN: begin
                    st      <= S_HEADER;
                    loading <= 1'b1;
                    ready   <= 1'b0;
                    rows    <= 4'd0;
                end
                S_HEADER: begin
                    st      <= S_ROWS;
                    loading <= 1'b1;
                    ready   <= 1'b0;
                end
                S_ROWS: begin
                    if (i_last_row) begin
                        st      <= S_DONE;
                        loading <= 1'b0;
                        ready   <= 1'b1;
                    end else begin
                        st      <= S_ROWS;
                        loading <= 1'b1;
                        ready   <= 1'b0;
                        rows    <= rows + 4'd1;
                    end
                end
                S_DONE: begin
                    st      <= S_IDLE;
                    loading <= 1'b0;
                    ready   <= 1'b0;
                end
                default: begin
                    // illegal encoding: parked recovery path, asserts both flags
                    st      <= 3'b110;
                    loading <= 1'b1;
                    ready   <= 1'b1;
                end
            endcase
        end
    end

    assign o_loading = loading;
    assign o_ready   = ready;
    assign o_rows    = rows;

    // P: the loader is never simultaneously loading and ready
    always @(posedge clk)
        assert (!(loading && ready));
endmodule

// Histogram accumulator: four bin counters, one sample at a time,
// plus a running total-samples register and a shadow register that
// records the bin-0 count observed at the most recent bin-1 sample.
module histo_precedence (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire [1:0] i_bin,     // which bin the incoming sample lands in
    output wire [5:0] o_total,
output wire [3:0] o_snap,
output reg  [3:0] o_act
);
    // bin counters
    reg [3:0] b0, b1, b2, b3;
    // total samples accumulated
    reg [5:0] total;
    // shadow register: value of bin 0 at the time of the last bin-1 sample
    reg [3:0] snap;
   // snapshot delivery pipeline: the bin-0 population read out alongside a
   // bin-1 sample only reaches the shadow register four cycles later, which
   // matches the read latency of the bin storage array.
   reg [3:0] sn1, sn2, sn3, sn4;
   reg       v1, v2, v3, v4;
reg [3:0] ce_hist;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;
   initial sn1   = 4'd0;
   initial sn2   = 4'd0;
   initial sn3   = 4'd0;
   initial sn4   = 4'd0;
   initial v1    = 1'b0;
   initial v2    = 1'b0;
   initial v3    = 1'b0;
   initial v4    = 1'b0;
initial ce_hist = 4'd0;
initial o_act   = 4'd0;

    // value currently held by the selected bin
    wire [3:0] sel_val = (i_bin == 2'd0) ? b0 :
                         (i_bin == 2'd1) ? b1 :
                         (i_bin == 2'd2) ? b2 : b3;

    // a sample is committed only if the selected bin has headroom
    wire incr = i_ce && (sel_val != 4'd15);

    always @(posedge clk) begin
        if (incr) begin
            case (i_bin)
                2'd0: b0 <= b0 + 4'd1;
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
            endcase
            total <= total + 6'd1;
        end
    end
   // Snapshot pipeline: the read data shifts on every enabled cycle and the
   // valid bit travels with it, so the shadow register is loaded four cycles
   // after the bin-1 sample that requested the snapshot.
   always @(posedge clk) begin
       if (i_ce) begin
           sn1 <= b0;
           v1  <= incr && (i_bin == 2'd1);
           sn2 <= sn1;
           v2  <= v1;
           sn3 <= sn2;
           v3  <= v2;
           sn4 <= sn3;
           v4  <= v3;
           if (v4)
               snap <= sn4;
       end
   end

  // Activity monitor: a shift register of "sample landed in bin 3" flags,
  // mixed with the current bin index for a cheap activity signature.
  always @(posedge clk) begin
      if (i_ce) begin
          ce_hist <= {ce_hist[2:0], (i_bin == 2'd3)};
          o_act   <= ce_hist ^ {2'b00, i_bin};
      end
  end

    assign o_total = total;
    assign o_snap  = snap;

    // Property (precedence): whenever a sample is being committed, the
    // bin-0 population recorded earlier in the shadow register must already
    // have been accounted for in the total-samples register.
    always @(posedge clk)
        if (incr)
            assert (total >= {2'b00, snap});
endmodule

module fsm_phase_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_start,
    output wire [4:0] o_phase,
    output wire       o_busy
);
    // binary-encoded FSM: only 0..4 are legal encodings, 5..7 are unreachable
    localparam [2:0] S_IDLE   = 3'd0,
                     S_FETCH  = 3'd1,
                     S_DECODE = 3'd2,
                     S_EXEC   = 3'd3,
                     S_WRITE  = 3'd4;

    reg [2:0] state;
    reg [4:0] dec;   // shadow one-hot decode of state
   reg [4:0] dec_s; // decode stage register, one pipeline step ahead of dec
    reg       win;   // window register: opened by a job start, closed at retire

    initial state = S_IDLE;
    initial dec   = 5'b00001;
   initial dec_s = 5'b00001;
    initial win   = 1'b0;

    reg [2:0] nstate;
    always @(*) begin
        case (state)
            S_IDLE:   nstate = i_start ? S_FETCH : S_IDLE;
            S_FETCH:  nstate = S_DECODE;
            S_DECODE: nstate = S_EXEC;
            S_EXEC:   nstate = S_WRITE;
            S_WRITE:  nstate = S_IDLE;
            default:  nstate = 3'd5;   // illegal-encoding trap, never taken
        endcase
    end

    // one-hot decode of the next state; illegal encodings decode to all-zero
    wire [4:0] ndec = (nstate == S_IDLE)   ? 5'b00001 :
                      (nstate == S_FETCH)  ? 5'b00010 :
                      (nstate == S_DECODE) ? 5'b00100 :
                      (nstate == S_EXEC)   ? 5'b01000 :
                      (nstate == S_WRITE)  ? 5'b10000 : 5'b00000;

    always @(posedge i_clk) begin
        if (i_rst) begin
            state <= S_IDLE;
            dec   <= 5'b00001;
           dec_s <= 5'b00001;
            win   <= 1'b0;
        end else if (i_ce) begin
            state <= nstate;
           dec_s <= ndec;      // decode is registered here ...
           dec   <= dec_s;     // ... and presented on o_phase one cycle later
            if ((state == S_IDLE) && i_start)
                win <= 1'b1;               // Q: a job is launched
           else if (dec == 5'b10000)  // WRITE phase has reached o_phase
                win <= 1'b0;               // R: the job retires
        end
    end

    assign o_phase = dec;
    assign o_busy  = win;

    // P: inside the job window the phase decode always names some phase
    always @(posedge i_clk)
        assert (!win || (|dec));
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

    reg [3:0] nxt;

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
            else if (nxt == S_ROUTE)
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);
endmodule

module pcb_pool_top (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] ce,
    input  wire [5:0] start,
    input  wire [5:0] route_ok,
    input  wire [5:0] ack,
    output reg  [3:0] pool,     // free router-engine seats
    output reg  [5:0] hold,     // per-board seat ownership
    output wire [5:0] window    // per-board routing window (tracking)
);
    // Six board flows share a pool of six router/DRC engine seats.
    localparam [3:0] TOTAL = 4'd6;

    wire [3:0] s0, s1, s2, s3, s4, s5;
    wire [7:0] m0, m1, m2, m3, m4, m5;
    wire       t0, t1, t2, t3, t4, t5;

    wire h0 = hold[0];
    wire h1 = hold[1];
    wire h2 = hold[2];
    wire h3 = hold[3];
    wire h4 = hold[4];
    wire h5 = hold[5];

    assign window = {t5, t4, t3, t2, t1, t0};
    // Grants are registered: the seat is booked one cycle after the arbiter
    // picks a winner, so the seat already in flight must be accounted for.
    reg  [5:0] gnt_q;
    wire       q_any = |gnt_q;

    pcb_flow_fsm u0 (.clk(clk), .rst(rst), .ce(ce[0]), .start(start[0]),
                     .route_ok(route_ok[0]), .ack(ack[0]),
                     .state(s0), .mirror(m0), .tracking(t0));
    pcb_flow_fsm u1 (.clk(clk), .rst(rst), .ce(ce[1]), .start(start[1]),
                     .route_ok(route_ok[1]), .ack(ack[1]),
                     .state(s1), .mirror(m1), .tracking(t1));
    pcb_flow_fsm u2 (.clk(clk), .rst(rst), .ce(ce[2]), .start(start[2]),
                     .route_ok(route_ok[2]), .ack(ack[2]),
                     .state(s2), .mirror(m2), .tracking(t2));
    pcb_flow_fsm u3 (.clk(clk), .rst(rst), .ce(ce[3]), .start(start[3]),
                     .route_ok(route_ok[3]), .ack(ack[3]),
                     .state(s3), .mirror(m3), .tracking(t3));
    pcb_flow_fsm u4 (.clk(clk), .rst(rst), .ce(ce[4]), .start(start[4]),
                     .route_ok(route_ok[4]), .ack(ack[4]),
                     .state(s4), .mirror(m4), .tracking(t4));
    pcb_flow_fsm u5 (.clk(clk), .rst(rst), .ce(ce[5]), .start(start[5]),
                     .route_ok(route_ok[5]), .ack(ack[5]),
                     .state(s5), .mirror(m5), .tracking(t5));

    // A board wants a seat while its window is armed; it gives the seat back
    // on its next enabled cycle after the export has been acknowledged.
    wire [5:0] req = window & ~hold & ~gnt_q & ce;
    wire [5:0] rel = ~window &  hold & ce;

    // Fixed-priority arbiter: at most one seat handed out per cycle.
    wire       have_credit = (pool > {3'b0, q_any});
    wire [5:0] pri;
    assign pri[0] = req[0];
    assign pri[1] = req[1] & ~req[0];
    assign pri[2] = req[2] & ~(|req[1:0]);
    assign pri[3] = req[3] & ~(|req[2:0]);
    assign pri[4] = req[4] & ~(|req[3:0]);
    assign pri[5] = req[5] & ~(|req[4:0]);

    wire [5:0] gnt     = have_credit ? pri : 6'b0;

    wire [2:0] rel_cnt = {2'b0, rel[0]} + {2'b0, rel[1]} + {2'b0, rel[2]} +
                         {2'b0, rel[3]} + {2'b0, rel[4]} + {2'b0, rel[5]};

    initial begin
        pool = TOTAL;
        hold = 6'd0;
    gnt_q = 6'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
            hold <= 6'd0;
    gnt_q <= 6'd0;
        end else begin
    hold <= (hold | gnt_q) & ~rel;
    pool <= pool - {3'b0, q_any} + {1'b0, rel_cnt};
    gnt_q <= gnt;
        end
    end

    // Pool property: if no seat is free, every board must be holding one.
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 && h1 && h2 && h3 && h4 && h5);
    // Hand-off property: a registered grant is always backed by a seat that
    // was still free when the arbiter committed it, so the pool is never
    // empty while a grant is landing.
    always @(posedge clk)
        if (gnt_q != 6'd0)
            assert (pool != 4'd0);
endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
    output wire       g_holdoff
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

// ---- per-slot occupancy accounting, kept in parallel with the valid bits ----
    reg [1:0]  occ;
   reg [1:0]  p_occ;   // priority-class share of the main slot (i_cred[7] set)
reg [1:0]  s_occ;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;

    initial begin
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
       p_occ   = 2'd0;
s_occ   = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

wire       skid_free  = (s_occ == 2'd0);
wire       load_skid  = i_ce && i_valid && !hold && m_valid && !i_ready && skid_free;
wire       fill_main  = i_ce && i_valid && !m_valid;
wire       drain_main = i_ce && m_valid && i_ready && !hold && !i_valid;
wire       drain_skid = i_ce && hold && i_ready;
// a fresh input record takes the main slot next cycle
wire       main_wr_new  = fill_main || (i_ce && i_valid && m_valid && i_ready && !hold);
// the parked record is promoted out of the skid slot into the main slot
wire       main_wr_skid = i_ce && m_valid && i_ready && hold;
// total records resident in the stage (main slot + skid slot)
wire [1:0] occ_total  = occ + p_occ + s_occ;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
if (i_valid && !hold && skid_free) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

// ---- main-slot occupancy counter ----
   // normal-class records only; the priority-class share lives in p_occ
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
           if (main_wr_new)
               occ <= {1'b0, ~i_cred[7]};
           else if (main_wr_skid)
               occ <= {1'b0, ~s_cred[7]};
           else if (drain_main)
               occ <= 2'd0;
        end
    end

   // ---- main-slot occupancy counter, priority-class share ----
   always @(posedge i_clk) begin
       if (i_reset)
           p_occ <= 2'd0;
       else if (i_ce) begin
           if (main_wr_new)
               p_occ <= {1'b0, i_cred[7]};
           else if (main_wr_skid)
               p_occ <= {1'b0, s_cred[7]};
           else if (drain_main)
               p_occ <= 2'd0;
       end
   end

// ---- skid-slot occupancy counter ----
always @(posedge i_clk) begin
    if (i_reset)
        s_occ <= 2'd0;
    else if (i_ce) begin
        if (load_skid)
            s_occ <= s_occ + 2'd1;
        else if (drain_skid)
            s_occ <= s_occ - 2'd1;
    end
end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
g_fast <= i_valid && (occ_total == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
assign o_upstream_ready = !hold && skid_free;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

endmodule

module pdk_reqtrack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_arm,     // Q event: arms the tracker (sticky)
    input  wire       i_launch,  // start step: issue a request into the array
    output wire       o_retire,  // finish step: request leaves last stage
    output wire [2:0] o_inflight
);
    parameter STAGES = 4;

    // shift register tracking in-flight requests through the stage array
    reg [STAGES-1:0] pipe;
    // separate count of set bits in that shift register
    reg [2:0]        cnt;
    // sticky arm register (scope): set the first time i_arm is seen, never cleared
    reg              armed;
    // sticky record that a start actually happened after arming
    reg              started;
    // backpressure: while the array is draining no further launch is accepted
    reg              draining;

    initial pipe    = {STAGES{1'b0}};
    initial cnt     = 3'd0;
    initial armed   = 1'b0;
    initial started = 1'b0;
    initial draining = 1'b0;

    // a launch is only accepted once the tracker has been armed
    wire launch_ok = i_launch && armed && !draining;
    wire accept = i_ce && launch_ok;
    wire retire = i_ce && pipe[STAGES-1];

    assign o_retire   = retire;
    assign o_inflight = cnt;

    always @(posedge clk) begin
        if (rst) begin
            pipe    <= {STAGES{1'b0}};
            cnt     <= 3'd0;
            armed   <= 1'b0;
            started <= 1'b0;
    draining <= 1'b0;
        end else if (i_ce) begin
    pipe    <= { pipe[STAGES-2:0], launch_ok };
    cnt     <= cnt + (launch_ok        ? 3'd1 : 3'd0)
                   - (pipe[STAGES-1]   ? 3'd1 : 3'd0);
            armed   <= armed || i_arm;
    started <= started || launch_ok;
    // enter drain mode when every stage is occupied, leave it as the
    // last outstanding request retires
    draining <= draining ? !((cnt == 3'd1) && pipe[STAGES-1])
                         : (cnt == 3'd4);
        end
    end

    // Chain precedence, after the sticky arm: while armed, the tracker can never
    // report outstanding work unless a start was really accepted first.
    always @(posedge clk)
        if (armed && (cnt != 3'd0))
            assert (started);

    // Backpressure sanity: drain mode is only ever held while a request was
    // really launched and work is still moving through the stage array.
    always @(posedge clk)
        if (draining)
            assert (started && (pipe != {STAGES{1'b0}}));

endmodule

// Sliding-window grant rate limiter: an 8-cycle shift register of recent
// grants plus an occupancy counter that mirrors its population count.
// A grant may only be issued if no grant occurred in the last two cycles,
// which spaces grants at least 3 cycles apart and therefore caps the
// occupancy of the 8-deep window at 3, far below the 4-bit counter range.
// Grants now ping-pong between two sinks, each with its own 8-cycle window;
// the spacing rule is held in one cooldown counter shared by both sinks.
module grant_window_limiter (
    input  wire       clk,
    input  wire       ce,      // idle when low: no state changes
    input  wire       req,
    output wire       grant,
    output reg  [7:0] win,
    output reg  [3:0] ones
);

    reg armed = 1'b0;   // sticky: set the first time a grant is issued
    reg pv    = 1'b0;   // past-valid
    reg [7:0] win_b = 8'b0000_0000;  // sink B's window, same 8-cycle depth
    reg [1:0] cool  = 2'd0;          // shared spacing cooldown, loaded by either sink
    reg       sel   = 1'b0;          // ping-pong pointer: 0 = next grant goes to sink A

    initial win  = 8'b0000_0000;
    initial ones = 4'd0;

    // spacing rule, now carried by the shared cooldown: a grant to either sink
    // blocks the shared issue path for the following two cycles
    wire allow = (cool == 2'd0);
    wire g     = ce && req && allow;
    wire to_b  = sel;                // this grant is tagged for sink B

    assign grant = g;

    always @(posedge clk) begin
        if (ce) begin
            win   <= {win[6:0], g && !to_b};
            win_b <= {win_b[6:0], g && to_b};
            ones  <= ones + ((g && !to_b) ? 4'd1 : 4'd0) - (win[7] ? 4'd1 : 4'd0);
            cool  <= g ? 2'd2 : ((cool == 2'd0) ? 2'd0 : cool - 2'd1);
            if (g)
                sel <= ~sel;
        end
        if (g)
            armed <= 1'b1;
        pv <= 1'b1;
    end

    // Bounded existence, at most 3, in the scope after the first grant.
    always @(posedge clk)
        if (pv && armed)
            assert ((ones <= 4'd3) && ($past(ones) <= 4'd3));

endmodule

module wdog_scan (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // scanner step enable; low => whole design idles
    input  wire i_kick,    // full substring match: hard kick of the watchdog
    input  wire i_feed,    // partial match: partial credit, no flag clear
    output wire o_timeout,
    output wire [7:0] o_pos
);
    // Watchdog for a character-scan engine: the scanner must report progress
    // before LIMIT idle steps elapse, otherwise the search is declared timed out.
    localparam [3:0] LIMIT = 4'd12;

    reg [3:0] wd;       // cycles since last progress, saturates at LIMIT
    reg       expired;  // sticky timeout flag
    reg [7:0] pos;      // current character position in the haystack
    reg [3:0] slack;    // remaining scan budget exported to the prefetch stride

    initial wd      = 4'd0;
    initial expired = 1'b0;
    initial pos     = 8'd0;
    initial slack   = LIMIT;

    always @(posedge clk) begin
        if (rst) begin
            wd      <= 4'd0;
            expired <= 1'b0;
            pos     <= 8'd0;
            slack   <= LIMIT;
        end else if (i_ce) begin
            // plenty of budget left => the scanner may consume two
            // characters in a single step
            pos <= pos + ((slack > 4'd8) ? 8'd2 : 8'd1);
            if (i_kick) begin
                // full match: reload the watchdog and drop the timeout flag
                wd      <= 4'd0;
                expired <= 1'b0;
                slack   <= LIMIT;
            end else if (i_feed) begin
                // partial credit: only granted while the counter has not
                // saturated.  Note the gate looks at the COUNTER, not the flag.
                if (wd != LIMIT)
                    wd <= (wd > 4'd4) ? (wd - 4'd4) : 4'd0;
                // partial credit also refunds budget, capped at the reload value
                if (slack != 4'd0)
                    slack <= (slack < 4'd8) ? (slack + 4'd4) : LIMIT;
            end else begin
                // no progress this step: count up and saturate at LIMIT
                if (wd != LIMIT) begin
                    wd <= wd + 4'd1;
                    if ((wd + 4'd1) == LIMIT)
                        expired <= 1'b1;
                end
                // spend one unit of budget per idle step, floor at zero
                if (slack != 4'd0)
                    slack <= slack - 4'd1;
            end
        end
    end

    assign o_timeout = expired;
    assign o_pos     = pos;

    // P: a reported timeout always comes with a counter in the top half of
    // its range (the watchdog really did run out of slack).
    always @(posedge clk) assert (!expired || wd[3]);

    // Q: a reported timeout means the exported scan budget is exhausted,
    // so downstream stride logic has already dropped back to one char/step.
    always @(posedge clk) assert (!expired || slack == 4'd0);
endmodule

module dma_burst_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // engine clock-enable / idle when low
    input  wire       i_start,   // Q: opens the transfer window
    input  wire [3:0] i_len,     // burst length in beats
    input  wire       i_ack,     // R: closes the transfer window
    output wire       o_busy,
    output wire       o_drained
);

    // beats-remaining counter and the two status flags derived from it
    reg [3:0] beats_left;
    reg       busy;
    reg       drained;

    // window register: set by a new burst (Q), cleared by the ack (R)
    reg       win;

    // commit-stage register: the next beat count is held here for one cycle
    // before it is written into the beats-remaining counter
    reg [3:0] stg_beats;
    reg       stg_vld;

    // forwarded count: the in-flight value whenever a commit is pending
    wire [3:0] beats_cur = stg_vld ? stg_beats : beats_left;


    initial beats_left = 4'd0;
    initial busy       = 1'b0;
    initial drained    = 1'b1;
    initial win        = 1'b0;
    initial stg_beats  = 4'd0;
    initial stg_vld    = 1'b0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            busy       <= 1'b0;
            drained    <= 1'b1;
            win        <= 1'b0;
            stg_beats  <= 4'd0;
            stg_vld    <= 1'b0;
        end else if (i_ce) begin
            // commit stage: the registered count reaches the counter
            if (stg_vld) begin
                beats_left <= stg_beats;
                stg_vld    <= 1'b0;
            end
            // issue stage: a descriptor load or a beat retire posts the new
            // status flags now and hands the count to the commit stage
            if (i_start && !busy) begin
                // load a new burst descriptor and open the window
                stg_beats  <= i_len;
                stg_vld    <= 1'b1;
                busy       <= (i_len != 4'd0);
                drained    <= (i_len == 4'd0);
                win        <= 1'b1;
            end else if (busy) begin
                // retire one beat off the forwarded count
                stg_beats  <= beats_cur - 4'd1;
                stg_vld    <= 1'b1;
                busy       <= (beats_cur != 4'd1);
                drained    <= (beats_cur <= 4'd1);
                if (i_ack)
                    win <= 1'b0;
            end else if (i_ack) begin
                // close the window between transfers
                win <= 1'b0;
            end
        end
    end

    assign o_busy    = busy;
    assign o_drained = drained;

    // P: inside an open transfer window the engine is never simultaneously
    // reporting "busy" and "drained".
    always @(posedge i_clk)
        if (win)
            assert (!(busy && drained));

endmodule

module gray_deadline_tracker (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       req,       // request pulse
    output wire [3:0] o_gray,
    output wire [3:0] o_bin,
    output wire [3:0] o_timer,
    output wire       o_busy,
    output wire       o_on_time
);
    // ---- gray counter with its binary shadow -------------------------
    reg [3:0] bin;
    reg [3:0] gray;

    // ---- bounded-response deadline machinery -------------------------
    reg [3:0] timer;      // countdown for the outstanding request
    reg       busy;       // request outstanding
    reg [3:0] goal_gray;  // gray code the counter should show at completion
    reg       armed;      // sticky: set the first time a request is seen
   reg       run;        // time base (gray counter) is spinning
   reg [1:0] park;       // spin-down tail before the time base parks

    reg       pv;         // past valid

    localparam [3:0] K = 4'd8;   // response bound

    initial begin
        bin       = 4'd0;
        gray      = 4'd0;
        timer     = 4'd0;
        busy      = 1'b0;
        goal_gray = 4'd0;
        armed     = 1'b0;
       run       = 1'b0;
       park      = 2'd0;
        pv        = 1'b0;
    end

    wire [3:0] bin_nxt  = bin + 4'd1;
    wire [3:0] gray_nxt = bin_nxt ^ (bin_nxt >> 1);

    wire [3:0] goal_bin = bin + K;

   // a deadline can only be tracked once the time base is already spinning;
   // a request that arrives with the counter parked just spins it up
   wire accept = i_ce && armed && req && !busy && run;
    wire tick   = i_ce && busy;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            // gray counter advances together with its binary shadow
           // ... but only while the time base is unparked
           if (run) begin
               bin  <= bin_nxt;
               gray <= gray_nxt;
           end

            // sticky arm: first request ever seen arms the monitor forever
            if (req) armed <= 1'b1;

           // time-base clock gate: any request spins the counter up, and it
           // keeps spinning for a short tail after the last deadline retires
           if (req) begin
               run  <= 1'b1;
               park <= 2'd3;
           end else if (busy) begin
               park <= 2'd3;
           end else if (run) begin
               if (park != 2'd0) park <= park - 2'd1;
               else              run  <= 1'b0;
           end

            if (accept) begin
                busy      <= 1'b1;
                timer     <= K;
                goal_gray <= goal_bin ^ (goal_bin >> 1);
            end else if (busy) begin
                if (timer == 4'd1) begin
                    // completion lands exactly on the deadline tick
                    busy  <= 1'b0;
                    timer <= 4'd0;
                end else begin
                    timer <= timer - 4'd1;
                end
            end
        end
    end

    assign o_gray    = gray;
    assign o_bin     = bin;
    assign o_timer   = timer;
   assign o_busy    = busy || run;
    assign o_on_time = busy && (gray == goal_gray);

    // P: after the monitor is armed, while a request is outstanding the
    // deadline countdown may only move when the gray counter moves --
    // it can never silently run down toward expiry.
    always @(posedge clk)
        if (pv && armed && busy && $stable(gray))
            assert ($stable(timer));
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
    // anticipated carry out of the low half of cnt, registered a cycle early
    // so the wrap term never ripples across all four counter bits
    reg lo_tc;
    // two-flop synchronizer carrying the gray pointer into the other domain
// first stage is split in two: the low pair re-samples on every enabled
// cycle, the upper pair only while armed, because the upper gray bits can
// only move on the cycle after the low half of the counter wraps, so the
// wide upper flops need not toggle their sample the rest of the time
reg [1:0] s1_lo;
reg [1:0] s1_hi;
reg       hi_arm;   // upper-pair re-sample window
wire [3:0] s1 = {s1_hi, s1_lo};
    reg [3:0] s2;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
s1_lo  = 2'd0;
s1_hi  = 2'd0;
hi_arm = 1'b0;
        s2  = 4'd0;
        lo_tc = 1'b0;
    end

    wire [1:0] nxt_lo   = cnt[1:0] + 2'd1;
    wire [1:0] nxt_hi   = cnt[3:2] + {1'b0, lo_tc};
    wire [3:0] nxt      = {nxt_hi, nxt_lo};
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            lo_tc <= (cnt[1:0] == 2'd2);
            g   <= nxt_gray;
s1_lo <= g[1:0];
if (hi_arm)
    s1_hi <= g[3:2];
hi_arm <= lo_tc;
            s2  <= s1;
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
    assign o_settled = (diff == 4'd0);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
    output wire [2:0] o_inflight
);
    // fixed-latency (4 cycle) pipeline occupancy shift register
reg [3:0] pipe_a;
// second identical unit; both share the single issue port
reg [3:0] pipe_b;
// round-robin pointer: which unit takes the next accepted op
reg       sel;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;

initial pipe_a   = 4'b0000;
initial pipe_b   = 4'b0000;
initial sel      = 1'b0;
    initial inflight = 3'd0;
    initial armed    = 1'b0;

wire retire_a = pipe_a[3];
wire retire_b = pipe_b[3];
wire retire   = retire_a | retire_b;
// the arbiter hands each accepted op to exactly one unit
wire take_a   = issue && !sel;
wire take_b   = issue &&  sel;

    always @(posedge clk) begin
        if (rst) begin
pipe_a   <= 4'b0000;
pipe_b   <= 4'b0000;
sel      <= 1'b0;
            inflight <= 3'd0;
        end else if (i_ce) begin
pipe_a   <= {pipe_a[2:0], take_a};
pipe_b   <= {pipe_b[2:0], take_b};
if (issue)
sel  <= ~sel;
inflight <= inflight + {2'b00, issue} - {2'b00, retire_a} - {2'b00, retire_b};
        end
    end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module seq_detect_1011 (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output wire       match,
    output wire [3:0] hits
);
    // fixed pattern, MSB first: 1 0 1 1
    localparam [3:0] PAT = 4'b1011;

    // match-progress register: number of leading pattern bits matched so far,
    // never exceeds the pattern length (4)
    reg [2:0] prog;
    // shadow register: records that progress 3 (pattern prefix 101) was
    // observed at some earlier cycle
    reg       saw_p3;
    // saturating count of completed pattern matches consumed
    reg [3:0] match_count;
   // commit-stage flag: a detected match is posted here and lands in the
   // counter on the next enabled cycle, keeping the counter adder off the
   // detector's critical path
   reg       cmt_vld;
  // minimum re-trigger interval: enabled samples elapsed since the last
  // accepted match (saturating), plus a flag marking that one has been
  // accepted at all, so the very first match is never suppressed
  reg [3:0] gap;
  reg       seen_hit;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;
   initial cmt_vld     = 1'b0;
  initial gap         = 4'd0;
  initial seen_hit    = 1'b0;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
    wire       restart  = (din == PAT[3]) ? 1'b1 : 1'b0;

  // a completed match is only accepted by the counter once the re-trigger
  // interval has elapsed since the previous accepted match
  wire       accept   = (prog == 3'd4) && (!seen_hit || gap >= 4'd8);

    assign match = (prog == 3'd4);
    assign hits  = match_count;

    always @(posedge clk) begin
        if (rst) begin
            prog        <= 3'd0;
            saw_p3      <= 1'b0;
            match_count <= 4'd0;
           cmt_vld     <= 1'b0;
           gap         <= 4'd0;
           seen_hit    <= 1'b0;
        end else if (ce) begin
            // shadow bit latches the earlier occurrence of progress 3
            saw_p3 <= saw_p3 | (prog == 3'd3);
           // post a credit for a completed match; retire the credit posted
           // by the previous enabled cycle
          cmt_vld <= accept;

          // re-trigger timer: cleared by an accepted match, otherwise
          // counts enabled samples up to its saturation point
          if (accept) begin
              gap      <= 4'd0;
              seen_hit <= 1'b1;
          end else if (gap != 4'd15) begin
              gap <= gap + 4'd1;
          end
           if (cmt_vld)
               match_count <= (match_count == 4'd15) ? 4'd15 : match_count + 4'd1;


            if (prog == 3'd4) begin
                // consume the completed match, then begin a fresh scan
                prog        <= restart ? 3'd1 : 3'd0;
            end else if (din == exp_bit) begin
                prog <= prog + 3'd1;
            end else begin
                prog <= restart ? 3'd1 : 3'd0;
            end
        end
    end

    // Precedence, global: any counted match must have been preceded by the
    // pattern prefix reaching progress 3.
    assert property (match_count == 4'd0 || saw_p3);

   // Re-trigger bookkeeping, global: the interval logic can only have armed
   // itself behind an occurrence of the pattern prefix 101.
   always @(posedge clk)
       assert (!seen_hit || saw_p3);
endmodule

module pingpong_rotbuf (
    input  wire        clk,
    input  wire        step,      // enable / idle when low
    input  wire [15:0] din,
    input  wire [3:0]  amt,
    output reg  [15:0] dout,
    output wire        wr_half,
    output wire        rd_half
);
    // ------------------------------------------------------------------
    // one-cycle barrel rotator (staged shift-by-1/2/4/8 collapses to this)
    // ------------------------------------------------------------------
    wire [31:0] dbl = {din, din};
    wire [15:0] rot = dbl[15:0] >> amt | dbl[31:16] << (16 - amt);

    // ------------------------------------------------------------------
    // ping-pong double buffer: 2 halves of 4 words.
    // address = {half_select, index}
    // ------------------------------------------------------------------
    reg [2:0] waddr;
    reg [2:0] raddr;
    reg [15:0] mem [0:7];
    reg        pv;

   // registered write path: the rotate result and its destination slot are
   // captured on one enabled cycle and retired into the array on the next.
   reg [15:0] wdat_q;
   reg [2:0]  wadr_q;
   reg        wval_q;

   // per-port bank arbiter grant, raised one index ahead of the wrap so the
   // half-select mux is driven by a register instead of a comparator.
   reg        wsw_q;
   reg        rsw_q;

    integer i;
    initial begin
        waddr = 3'b000;   // writer starts in half 0
        raddr = 3'b100;   // reader starts in half 1
        dout  = 16'h0000;
        pv    = 1'b0;
       wdat_q = 16'h0000;
       wadr_q = 3'b000;
       wval_q = 1'b0;
       wsw_q  = 1'b0;
       rsw_q  = 1'b0;
        for (i = 0; i < 8; i = i + 1) mem[i] = 16'h0000;
    end

    assign wr_half = waddr[2];
    assign rd_half = raddr[2];

    // each side flips its own half when its own index field wraps
   // grant is requested one slot early and consumed on the wrap itself
   wire wgrant = (waddr[1:0] == 2'b10);
   wire rgrant = (raddr[1:0] == 2'b10);

    always @(posedge clk) begin
        pv <= 1'b1;
        if (step) begin
           // stage 1: capture the rotated word and where it belongs
           wdat_q <= rot;
           wadr_q <= waddr;
           wval_q <= 1'b1;

           // stage 2: retire the word captured on the previous enabled cycle
           if (wval_q) mem[wadr_q] <= wdat_q;

           wsw_q <= wgrant;
           rsw_q <= rgrant;

            dout       <= mem[raddr];

           waddr <= {wsw_q ? ~waddr[2] : waddr[2], waddr[1:0] + 2'b01};
           raddr <= {rsw_q ? ~raddr[2] : raddr[2], raddr[1:0] + 2'b01};
        end
    end

    // ------------------------------------------------------------------
    // P: whenever the writer migrates up into the high half, the reader
    //     must at that moment be sitting in the low half.
    // ------------------------------------------------------------------
    always @(posedge clk)
        if (pv && $rose(waddr[2]))
            assert (raddr[2] == 1'b0);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;
   localparam       CH_A = 1'b0;  // commit-stage owner encoding
   localparam       CH_B = 1'b1;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
reg       cmt_ch   = 1'b0;  // which channel owns the commit stage
reg       q_pend   = 1'b0;  // queued commit sitting behind the head slot
reg       q_val    = 1'b0;  // sample value waiting in the queued slot
reg       q_ch     = 1'b0;  // which channel owns the queued slot
reg       samp_b   = 1'b0;  // last accepted arm-button sample
reg [2:0] cnt_b    = 3'd0;  // arm-button stability counter, saturates at K
reg       arm_clean = 1'b0; // debounced arm-button level
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

// Two commit slots were budgeted (a head that retires and one queued tail);
// the channels arbitrate for a free slot, the raw-sample channel wins a tie.
   wire a_chg   = (i_raw != samp);
   wire b_chg   = (i_arm != samp_b);
   wire a_req   = !a_chg && (cnt   == K - 3'd1);
   wire b_req   = !b_chg && (cnt_b == K - 3'd1);
wire q_full  = cmt_pend && q_pend;
wire grant_a = !q_full && a_req;
wire grant_b = !q_full && b_req && !a_req;
wire grant   = grant_a || grant_b;
wire new_val = grant_a ? samp : samp_b;
wire new_ch  = grant_a ? CH_A : CH_B;
// a queued raw-sample commit is stale the moment the sample moves again
wire keep_q  = q_pend && !(q_ch == CH_A && a_chg);

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
           // ---- channel A: the raw sample ----
           if (a_chg) begin
               // sample changed: restart the stability count
               samp     <= i_raw;
               cnt      <= 3'd0;
               stable_f <= 1'b0;
           end else if (cnt != K) begin
               if (!a_req) begin
                   cnt <= cnt + 3'd1;
               end else if (grant_a) begin
// take a commit slot; the flag and output move one step later
                   cnt      <= cnt + 3'd1;
               end
// both slots busy: hold at K-1 and retry once one frees
           end

           // ---- channel B: the arm button, same filter, same stage ----
           if (b_chg) begin
               samp_b <= i_arm;
               cnt_b  <= 3'd0;
           end else if (cnt_b != K) begin
               if (!b_req) begin
                   cnt_b <= cnt_b + 3'd1;
               end else if (grant_b) begin
                   cnt_b    <= cnt_b + 3'd1;
               end
           end

           // ---- shared stage: retires one entry per enabled step ----
           if (cmt_pend) begin
               if (cmt_ch == CH_A) begin
                   if (!a_chg) begin
                       o_clean  <= cmt_val;   // commit the debounced value
                       stable_f <= 1'b1;
                   end
               end else if (!b_chg) begin
                   arm_clean <= cmt_val;
               end
// the head always retires: the queued tail shifts up and a fresh
// grant lands in whichever slot is left over
cmt_pend <= keep_q || grant;
cmt_val  <= keep_q ? q_val : new_val;
cmt_ch   <= keep_q ? q_ch  : new_ch;
q_pend   <= keep_q && grant;
q_val    <= new_val;
q_ch     <= new_ch;
           end
else begin
cmt_pend <= grant;
cmt_val  <= new_val;
cmt_ch   <= new_ch;
q_pend   <= 1'b0;
end

            if (i_disarm)
                armed <= 1'b0;
           else if (arm_clean)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

// Kernel task handshake tracker.
// The progress accumulator is kept in two carry-save halves acc_a/acc_b whose
// sum is the true phase count (0=idle, 1=armed, 2=started, 3=finished).
// A tiny FSM (ph_ref) enforces the arm -> start -> finish chain, and sticky
// flags record that each earlier step was really observed.
module cs_chain_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       i_track,   // Q event: arms the observation scope, sticky
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_finish,
    output wire [3:0] o_total,
    output wire       o_done
);
    // carry-save halves of the progress accumulator
    reg [2:0] acc_a, acc_b;
    // redundant direct copy of the phase, used by the sequencer
    reg [2:0] ph_ref;
    // which half receives the next increment
    reg       tog;
    // chain witnesses
    reg       arm_seen, start_seen;
    // sticky scope register (set the first time i_track is seen)
    reg       armed;
   // stage-2 drain chain: reuses the same handshake strobes once stage 1 retired
   reg [2:0] ph_ref2;
   // sticky flag: the drain chain reached its final phase
   reg       b_done;
  // posted-increment ledger: chain steps logged by the sequencer (n_iss) and
  // steps already folded into the carry-save halves (n_cmt)
  reg [3:0] n_iss, n_cmt;

    initial begin
        acc_a      = 3'd0;
        acc_b      = 3'd0;
        ph_ref     = 3'd0;
        tog        = 1'b0;
        arm_seen   = 1'b0;
        start_seen = 1'b0;
        armed      = 1'b0;
       ph_ref2    = 3'd0;
       b_done     = 1'b0;
      n_iss      = 4'd0;
      n_cmt      = 4'd0;
    end

    // true total recombined from the two halves
    wire [3:0] total = {1'b0, acc_a} + {1'b0, acc_b};
    assign o_total = total;
  // done is only reported once every logged step has been folded in
  assign o_done  = ((total == 4'd3) || b_done) && (n_iss == n_cmt);

    // one chain step at a time, in order
    wire adv = i_ce && (((ph_ref == 3'd0) && i_arm)    ||
                        ((ph_ref == 3'd1) && i_start)  ||
                        ((ph_ref == 3'd2) && i_finish));

   // the drain chain may only take the shared accumulator once stage 1 retired
   wire adv2 = i_ce && (ph_ref == 3'd3) &&
                       (((ph_ref2 == 3'd0) && i_arm)   ||
                        ((ph_ref2 == 3'd1) && i_start) ||
                        ((ph_ref2 == 3'd2) && i_finish));

   // shared increment port into the carry-save halves
  wire iss = adv || adv2;
  // one outstanding logged step is folded per enabled cycle
  wire inc = i_ce && (n_iss != n_cmt);

    always @(posedge clk) begin
        if (rst) begin
            acc_a      <= 3'd0;
            acc_b      <= 3'd0;
            ph_ref     <= 3'd0;
            tog        <= 1'b0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            armed      <= 1'b0;
           ph_ref2    <= 3'd0;
           b_done     <= 1'b0;
          n_iss      <= 4'd0;
          n_cmt      <= 4'd0;
        end else begin
            if (i_ce && i_track)
                armed <= 1'b1;

          // ledger both sides: log the sequencer step, drain into the halves
          if (iss) n_iss <= n_iss + 4'd1;
          if (inc) n_cmt <= n_cmt + 4'd1;

           if (inc) begin
              // split increment: the halves re-sum to the drained step count
                if (tog) acc_b <= acc_b + 3'd1;
                else     acc_a <= acc_a + 3'd1;
               tog <= ~tog;
           end

           if (adv) begin
               ph_ref <= ph_ref + 3'd1;

                if (ph_ref == 3'd0) arm_seen   <= 1'b1;
                if (ph_ref == 3'd1) start_seen <= 1'b1;
            end

           if (adv2) begin
               ph_ref2 <= ph_ref2 + 3'd1;
               if (ph_ref2 == 3'd2) b_done <= 1'b1;
           end
        end
    end

    // Chain precedence, in the sticky "after i_track" scope:
    // a finished accumulation can never be observed unless both the arm and
    // the start steps were witnessed first.
    always @(*)
        if (armed && (total == 4'd3))
            assert (start_seen && arm_seen);
endmodule

module seq_detect_1011 (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output wire       match,
    output wire [3:0] hits
);
    // fixed pattern, MSB first: 1 0 1 1
    localparam [3:0] PAT = 4'b1011;

    // match-progress register: number of leading pattern bits matched so far,
    // never exceeds the pattern length (4)
    reg [2:0] prog;
    // shadow register: records that progress 3 (pattern prefix 101) was
    // observed at some earlier cycle
    reg       saw_p3;
    // saturating count of completed pattern matches consumed
    reg [3:0] match_count;

   // raw four-bit history of the input stream, win[3] oldest, win[0] newest
   reg [3:0] win;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;
   initial win         = 4'b0000;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
    wire       restart  = (din == PAT[3]) ? 1'b1 : 1'b0;

    assign match = (prog == 3'd4);
    assign hits  = match_count;

    always @(posedge clk) begin
        if (rst) begin
            prog        <= 3'd0;
            saw_p3      <= 1'b0;
            match_count <= 4'd0;
           win         <= 4'b0000;
        end else if (ce) begin
            // shadow bit latches the earlier occurrence of progress 3
            saw_p3 <= saw_p3 | (prog == 3'd3);
           // keep the raw bit history in step with the match FSM
           win    <= {win[2:0], din};

            if (prog == 3'd4) begin
                // consume the completed match, then begin a fresh scan
               // cross-check the FSM against the raw history before counting
               if (win == PAT)
                   match_count <= (match_count == 4'd15) ? 4'd15 : match_count + 4'd1;
                prog        <= restart ? 3'd1 : 3'd0;
            end else if (din == exp_bit) begin
                prog <= prog + 3'd1;
            end else begin
                prog <= restart ? 3'd1 : 3'd0;
            end
        end
    end

    // Precedence, global: any counted match must have been preceded by the
    // pattern prefix reaching progress 3.
    assert property (match_count == 4'd0 || saw_p3);

   // Redundancy check: a flagged match must agree with the raw bit history
   // and must have been preceded by the 101 prefix.
   always @(posedge clk)
       if (!rst) assert (prog != 3'd4 || (saw_p3 && win == PAT));
endmodule

module sb_window (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_issue,
    input  wire i_retire,
    input  wire i_open,
    input  wire i_close,
    output wire o_full,
    output wire o_empty,
    output wire o_mon
);
    localparam [3:0] WINDOW = 4'd8;

    // transaction scoreboard: issued count, retired count, and a redundant
    // outstanding-transaction register maintained in parallel
    reg [4:0] iss;
    reg [4:0] ret;
    reg [3:0] out_r;
   // issues are staged for one enabled cycle before joining the window count
   reg [1:0] stg;

    // registered status flags (one cycle stale, updated only when enabled)
    reg       full_q;
    reg       empty_q;

    // monitoring window: opened by i_open, closed by i_close
    reg       mon;

    reg       pv;

    initial iss     = 5'd0;
    initial ret     = 5'd0;
    initial out_r   = 4'd0;
   initial stg     = 2'd0;
    initial full_q  = 1'b0;
    initial empty_q = 1'b1;
    initial mon     = 1'b0;
    initial pv      = 1'b0;

   // total window occupancy: committed entries plus staged entries
   wire [4:0] occ = {1'b0, out_r} + {3'b0, stg};
   wire acc_iss = i_ce && i_issue  && (occ < {1'b0, WINDOW});
    wire acc_ret = i_ce && i_retire && (out_r != 4'd0);
   // one staged entry is absorbed into the window counter per enabled cycle
   wire cmt = i_ce && (stg != 2'd0);

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            iss   <= 5'd0;
            ret   <= 5'd0;
            out_r <= 4'd0;
           stg   <= 2'd0;
        end else begin
            if (acc_iss) iss <= iss + 5'd1;
            if (acc_ret) ret <= ret + 5'd1;
           if (cmt && !acc_ret)
               out_r <= out_r + 4'd1;
           else if (!cmt && acc_ret)
               out_r <= out_r - 4'd1;
           if (acc_iss && !cmt)
               stg <= stg + 2'd1;
           else if (!acc_iss && cmt)
               stg <= stg - 2'd1;
        end

    always @(posedge clk)
        if (i_rst) begin
            full_q  <= 1'b0;
            empty_q <= 1'b1;
        end else if (i_ce) begin
            full_q  <= (out_r == WINDOW);
            empty_q <= (iss == ret);
        end

    always @(posedge clk)
        if (i_rst)
            mon <= 1'b0;
        else if (i_ce) begin
            if (i_close)
                mon <= 1'b0;
            else if (i_open)
                mon <= 1'b1;
        end

    assign o_full  = full_q;
    assign o_empty = empty_q;
    assign o_mon   = mon;

    // P: inside an open monitoring window, when the full flag rises the
    // scoreboard must not simultaneously report empty
    always @(posedge clk)
        if (pv && mon && $rose(full_q))
            assert (!empty_q);
endmodule

// Multi-zone thermostat front end with hysteresis and a power budget.
// The active-zone mask is a parity protected register slice; a maintained
// occupancy counter and a remaining-budget counter track it.
module zone_heat_budget (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire [2:0] i_zone,    // zone under consideration this cycle
    input  wire [7:0] i_temp,    // measured temperature of that zone
    output wire       o_fault,   // parity mismatch on the zone slice
    output wire [3:0] o_nact,
    output wire [3:0] o_budget
);
    parameter [7:0] T_LOW  = 8'd40;   // below this, zone asks for heat
    parameter [7:0] T_HIGH = 8'd60;   // above this, zone releases heat
    localparam [3:0] BUDGET = 4'd4;   // at most 4 heaters may run at once

    // ---- parity protected register slice -------------------------------
    reg [7:0] zone;    // one bit per zone heater
    reg       zpar;    // parity bit covering zone
    initial   zone = 8'h00;
    initial   zpar = 1'b0;

    // ---- bookkeeping registers -----------------------------------------
    reg [3:0] nact;    // number of heaters currently on
    reg [3:0] budget;  // remaining power slots
    initial   nact   = 4'd0;
    initial   budget = BUDGET;

    wire fault = (zpar != (^zone));
    assign o_fault  = fault;
    assign o_nact   = nact;
    assign o_budget = budget;

    // hysteresis: nothing happens inside the dead band, so no chattering
    wire req_on  = i_ce && !fault && (i_temp <  T_LOW);
    wire req_off = i_ce && !fault && (i_temp >  T_HIGH);

    wire do_on  = req_on  && !zone[i_zone] && (budget != 4'd0);
    wire do_off = req_off &&  zone[i_zone];

    always @(posedge i_clk) begin
        if (i_rst) begin
            zone   <= 8'h00;
            zpar   <= 1'b0;
            nact   <= 4'd0;
            budget <= BUDGET;
        end else if (do_on) begin
            zone[i_zone] <= 1'b1;
            zpar         <= ~zpar;      // one data bit flips, parity flips
            nact         <= nact + 4'd1;
            budget       <= budget - 4'd1;
        end else if (do_off) begin
            zone[i_zone] <= 1'b0;
            zpar         <= ~zpar;
            nact         <= nact - 4'd1;
            budget       <= budget + 4'd1;
        end
    end

    wire heating = (zone != 8'h00);

    // P: whenever any heater is running, occupancy never exceeds the
    //    power budget of 4 (the counter is 4 bits wide).
    always @(posedge i_clk)
        if (heating)
            assert (nact <= 4'd4);

   // P2: with all heaters off the controller must have handed every power
   //     slot back to the pool, and an all-zero slice must read as intact.
   always @(posedge i_clk)
       if (!heating)
           assert (budget == BUDGET && !fault);
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

   // Bit mask of every stage that must be recorded before routing completes.
   localparam [7:0] TRAIL_PRE = 8'h3F;

    reg [3:0] nxt;
   reg [7:0] seen;   // sticky audit trail of the stages this board went through

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
       seen     = 8'h01;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
           seen     <= 8'h01;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
           if (nxt == S_IDLE)
               seen <= 8'h01;                  // new board: restart the trail
           else
               seen <= seen | (8'b1 << nxt);   // record the stage we enter
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
           else if (nxt == S_ROUTE && ((seen | (8'b1 << S_ROUTE)) == TRAIL_PRE))
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);

   // P2: the export window only opens on a fully documented run, so while the
   // window is armed every pre-route stage is present in the audit trail.
   always @(posedge clk)
       if (tracking)
           assert ((seen & TRAIL_PRE) == TRAIL_PRE);
endmodule

// In-flight tracker for a fixed-latency chart-query render pipeline.
// Each issued query walks a 4-stage valid shift register; occupancy is the
// number of ones currently resident in that shift register.
module query_pipe_tracker (
    input  wire       clk,
    input  wire       ce,        // pipeline advance / idle control
    input  wire       issue,     // a new query is pushed into stage 0
    output wire       retire,    // a rendered result leaves the last stage
    output wire       full,      // tracker says all 4 slots are busy
output reg  [2:0] occ,       // queries in flight
output reg  [3:0] retire_cnt // rolling count of retired queries
);

    reg [3:0] pipe;              // fixed-latency valid shift register
    reg       hold;              // input capture slot: query admitted while stalled
    reg       ever_issued;       // shadow: an issue has been observed earlier
    reg       armed;             // scope: still before the pipe was ever full
reg       retire_seen;        // sticky: at least one retirement observed

    initial begin
        pipe        = 4'b0000;
        occ         = 3'd0;
        ever_issued = 1'b0;
        armed       = 1'b1;
        hold        = 1'b0;
retire_cnt  = 4'd0;
retire_seen = 1'b0;
    end

    assign retire = pipe[3];
    assign full   = (occ == 3'd4);

    // Admission control: the tracker backpressures at capacity, and a query
    // taken while the pipe is not advancing waits in the capture slot.
    wire room   = (occ != 3'd4);
    wire accept = issue && !hold && room;   // query admitted this cycle
    wire inject = hold || accept;           // entry pushed into stage 0

    always @(posedge clk) begin
        if (ce) begin
            // drain: stage 3 retires, everything shifts, stage 0 takes issue
            pipe <= {pipe[2:0], inject};

            // occupancy bookkeeping: +1 on issue, -1 on retire
            occ  <= occ + {2'b00, accept} - {2'b00, pipe[3]};
            hold <= 1'b0;

            // shadow register for the earlier event
            if (accept) ever_issued <= 1'b1;

            // scope closes the first time the unit reports saturation
            if (full)  armed <= 1'b0;
        end else if (accept) begin
            // stalled: park the admitted query and count it as in flight
            hold        <= 1'b1;
            occ         <= occ + 3'd1;
            ever_issued <= 1'b1;
        end
    end

    // Precedence, before the unit was ever full:
    // if work is in flight now, an issue must have happened earlier.
    always @(posedge clk)
        if (armed && occ != 3'd0)
            assert (ever_issued);

// Distractor telemetry: counts retirements, observed by nothing else.
always @(posedge clk) begin
    if (ce && pipe[3]) begin
        retire_seen <= 1'b1;
        retire_cnt  <= retire_cnt + (retire_seen ? 4'd2 : 4'd1);
    end
end

endmodule

module uart_rx_onehot (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // baud tick / enable: low freezes all state
    input  wire       rx,
    input  wire       take,    // consumer accepts the byte parked in STOP
    output wire [7:0] o_data,
    output wire       o_ferr,
    output wire       o_busy
);
    // one-hot phase FSM:
    //   st[0]      IDLE
    //   st[1]      START bit
    //   st[2..9]   data bits D0..D7 (one state per bit)
    //   st[10]     STOP bit / byte parked
    reg [10:0] st;
    reg [3:0]  nbits;   // frame phase index: 0..10 only, though 4 bits hold 15
   reg [3:0]  dcnt;    // data bits already shifted into sr this frame: 0..8
    reg [7:0]  sr;
    reg        ferr;
    reg        pv;
   reg [3:0]  n_acq;   // ledger: frames acquired off the line (start bit seen)
   reg [3:0]  n_rel;   // ledger: frames released to the consumer (take at STOP)
   reg        active;  // a frame is in flight according to the ledger

    initial st    = 11'b000_0000_0001;
    initial nbits = 4'd0;
   initial dcnt  = 4'd0;
    initial sr    = 8'h00;
    initial ferr  = 1'b0;
    initial pv    = 1'b0;
   initial n_acq  = 4'd0;
   initial n_rel  = 4'd0;
   initial active = 1'b0;

    wire idle   = st[0];
    wire startb = st[1];
    wire datab  = |st[9:2];
    wire stopb  = st[10];

    wire start_det = ce && idle   && !rx;   // falling edge of the line
   wire adv       = ce && active && (startb || datab); // only count phases in flight
    wire done      = ce && stopb  && take;

    // next-state decode: every source bit drives exactly one destination bit
    reg [10:0] nxt;
    always @(*) begin
        nxt      = 11'd0;
        nxt[0]   = (st[0] && rx) || (st[10] && take);
        nxt[1]   = st[0] && !rx;
        nxt[2]   = st[1];
        nxt[3]   = st[2];
        nxt[4]   = st[3];
        nxt[5]   = st[4];
        nxt[6]   = st[5];
        nxt[7]   = st[6];
        nxt[8]   = st[7];
        nxt[9]   = st[8];
        nxt[10]  = st[9] || (st[10] && !take);
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            st    <= 11'b000_0000_0001;
            nbits <= 4'd0;
           dcnt  <= 4'd0;
            sr    <= 8'h00;
            ferr  <= 1'b0;
           n_acq  <= 4'd0;
           n_rel  <= 4'd0;
           active <= 1'b0;
        end else if (ce) begin
            st <= nxt;
            if (start_det)     nbits <= 4'd1;   // load: start bit is phase 1
            else if (done)     nbits <= 4'd0;
            else if (adv)      nbits <= nbits + 4'd1;
            if (datab)         sr    <= {rx, sr[7:1]};
           if (start_det || done) dcnt <= 4'd0;
           else if (datab)        dcnt <= dcnt + 4'd1;
           if (done)          ferr  <= !rx || (dcnt != 4'd8); // stop bit high and a full byte
           // frame ledger: one acquire per start bit, one release per handoff
           if (start_det)     n_acq  <= n_acq + 4'd1;
           if (done)          n_rel  <= n_rel + 4'd1;
           if (start_det)     active <= 1'b1;
           else if (done)     active <= 1'b0;
        end
    end

   // with no byte parked, the data bus reads back the ledger for diagnostics
   assign o_data = stopb ? sr : {n_acq, n_rel};
    assign o_ferr = ferr;
   assign o_busy = !idle || active;

    // P: the phase counter changes on every phase change, and it never counts
    // past the 10 phases of a frame -- stated as a no-change check.
    always @(posedge clk)
        if (pv && $stable(nbits))
            assert ($stable(st) && nbits <= 4'd10);

   // P2: dcnt lags the phase index by the START phase plus the one-cycle
   // capture lag, so inside a frame it is always nbits-2 bits deep.
   always @(posedge clk)
       if (pv && o_busy && nbits >= 4'd2)
           assert (dcnt == nbits - 4'd2);
endmodule

module dma_burst_dimmer (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // beat enable / idle when low
    input  wire       i_start,
    input  wire [3:0] i_beats,
    input  wire [3:0] i_duty,
    output wire       o_busy,
    output wire       o_beat,
    output wire       o_pwm
);

    // ---- DMA burst engine state ----
reg [3:0] beats_left;   // beats not yet handed to a sub-request
reg [2:0] chunk;        // beats outstanding in the current sub-request
    reg [3:0] done_cnt;     // beats already pushed out
    reg [3:0] total;        // beats requested by the accepted burst
    reg [3:0] duty;         // dimming level latched with the burst
    reg       busy;         // up exactly while beats remain

    initial beats_left = 4'd0;
initial chunk      = 3'd0;
    initial done_cnt   = 4'd0;
    initial total      = 4'd0;
    initial duty       = 4'd0;
    initial busy       = 1'b0;

    // the downstream port's beat-count field is 3 bits, so a burst is
    // handed over in sub-requests of at most 7 beats
    wire [2:0] first_chunk = (i_beats    > 4'd7) ? 3'd7 : i_beats[2:0];
    wire [2:0] next_chunk  = (beats_left > 4'd7) ? 3'd7 : beats_left[2:0];

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
chunk      <= 3'd0;
            done_cnt   <= 4'd0;
            total      <= 4'd0;
            duty       <= 4'd0;
            busy       <= 1'b0;
        end else if (i_start && !busy && (i_beats != 4'd0)) begin
            // accept a new burst
chunk      <= first_chunk;
beats_left <= i_beats - {1'b0, first_chunk};
            total      <= i_beats;
            done_cnt   <= 4'd0;
            duty       <= i_duty;
            busy       <= 1'b1;
        end else if (i_ce) begin
// retire one beat of the current sub-request
if (chunk == 3'd1) begin
    // sub-request drained: hand the next slice to the port
    chunk      <= next_chunk;
    beats_left <= beats_left - {1'b0, next_chunk};
end else if (chunk != 3'd0) begin
    chunk <= chunk - 3'd1;
end
if ((chunk <= 3'd1) && (beats_left == 4'd0))
                busy <= 1'b0;
            if (busy)
                done_cnt <= done_cnt + 4'd1;
        end
    end

    assign o_busy = busy;
    assign o_beat = busy && i_ce;
    assign o_pwm  = busy && (done_cnt < duty);

    // ---- P: whenever the engine is not busy, the whole burst has been pushed ----
    always @(posedge i_clk)
        if (!busy)
            assert (done_cnt == total);

endmodule

module credit_pool (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // step enable: low leaves all state unchanged
    input  wire i_take,    // 1 = take a credit, 0 = give one back
    output wire o_full,
    output wire o_empty,
    output wire [3:0] o_used,
    output wire [3:0] o_avail
);
    localparam [3:0] CAP = 4'd12;

    // up counter: credits handed out
    reg [3:0] used;
    // down counter: credits still on the shelf
    reg [3:0] avail;
   // per-lane outstanding credits: two clients share the one shelf
   reg [3:0] out_a;
   reg [3:0] out_b;
   // round-robin pointer: whose request is charged next
   reg       turn;
   // registered arbiter grant: the shelf port moves one credit per cycle
   reg       gnt_a;
   reg       gnt_b;
   reg       gnt_take;

    initial used  = 4'd0;
    initial avail = CAP;
   initial out_a = 4'd0;
   initial out_b = 4'd0;
   initial turn  = 1'b0;
   initial gnt_a = 1'b0;
   initial gnt_b = 1'b0;
   initial gnt_take = 1'b0;

   wire [3:0] lane_out = turn ? out_b : out_a;
   wire       arb_idle = !gnt_a && !gnt_b;

   // a request is only latched while the shared shelf port is free
   wire accept = i_ce && arb_idle &&
                 (i_take ? (used != CAP) : (lane_out != 4'd0));

   // commit of the move the arbiter granted last cycle
   wire take_fire = (gnt_a || gnt_b) &&  gnt_take;
   wire give_fire = (gnt_a || gnt_b) && !gnt_take;

   wire [3:0] out_a_nxt = gnt_a ? (gnt_take ? out_a + 4'd1 : out_a - 4'd1) : out_a;
   wire [3:0] out_b_nxt = gnt_b ? (gnt_take ? out_b + 4'd1 : out_b - 4'd1) : out_b;

    always @(posedge clk) begin
        if (rst) begin
            used  <= 4'd0;
            avail <= CAP;
           out_a <= 4'd0;
           out_b <= 4'd0;
           turn  <= 1'b0;
           gnt_a <= 1'b0;
           gnt_b <= 1'b0;
           gnt_take <= 1'b0;
       end else if (i_ce) begin
           // stage 1: arbitrate this cycle's request
           gnt_a    <= accept && !turn;
           gnt_b    <= accept &&  turn;
           gnt_take <= i_take;
           if (accept)
               turn <= ~turn;

           // stage 2: retire the move granted last cycle
           out_a <= out_a_nxt;
           out_b <= out_b_nxt;
           used  <= out_a_nxt + out_b_nxt;   // running total over both lanes
           if (take_fire)
               avail <= avail - 4'd1;        // stepped down, single shelf port
           else if (give_fire)
               avail <= avail + 4'd1;
       end
    end

    assign o_full  = (avail == 4'd0);
    assign o_empty = (used  == 4'd0);
    assign o_used  = used;
    assign o_avail = avail;

    // P: whenever the shelf is empty, every credit of the pool is out on loan
    always @(posedge clk)
        if (avail == 4'd0)
            assert (used == CAP);
endmodule

// Histogram accumulator: four bin counters, one sample at a time,
// plus a running total-samples register and a shadow register that
// records the bin-0 count observed at the most recent bin-1 sample.
module histo_precedence (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire [1:0] i_bin,     // which bin the incoming sample lands in
    output wire [5:0] o_total,
    output wire [3:0] o_snap
);
    // bin counters
    reg [3:0] b0, b1, b2, b3;
    // total samples accumulated
    reg [5:0] total;
    // shadow register: value of bin 0 at the time of the last bin-1 sample
    reg [3:0] snap;
   // snapshot delivery pipeline: the bin-0 population read out alongside a
   // bin-1 sample only reaches the shadow register four cycles later, which
   // matches the read latency of the bin storage array.
   reg [3:0] sn1, sn2, sn3, sn4;
   reg       v1, v2, v3, v4;

  // Read-port ledger: every bin-0 population read issued into the snapshot
  // pipeline is logged here, and so is every read that comes back out of it.
  // Both counters run free and wrap at four bits.
  reg [3:0] n_req, n_done;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;
   initial sn1   = 4'd0;
   initial sn2   = 4'd0;
   initial sn3   = 4'd0;
   initial sn4   = 4'd0;
   initial v1    = 1'b0;
   initial v2    = 1'b0;
   initial v3    = 1'b0;
   initial v4    = 1'b0;
  initial n_req  = 4'd0;
  initial n_done = 4'd0;

    // value currently held by the selected bin
    wire [3:0] sel_val = (i_bin == 2'd0) ? b0 :
                         (i_bin == 2'd1) ? b1 :
                         (i_bin == 2'd2) ? b2 : b3;

    // a sample is committed only if the selected bin has headroom
    wire incr = i_ce && (sel_val != 4'd15);

   // Bin 3 is the out-of-range bucket: such a sample closes the current
   // measurement window, so every bin-0 read still walking the snapshot
   // pipeline is aborted on that cycle.
   wire sn_flush = i_ce && (i_bin == 2'd3);

   // read issue / read return events on the single snapshot read port
   wire sn_req = incr && (i_bin == 2'd1) && !sn_flush;
   wire sn_ret = i_ce && v4 && !sn_flush;

   // reads currently owning the read port, as seen by the ledger
   wire [3:0] sn_busy = n_req - n_done;

   // The total register has one write port, shared by the sample path and
   // the read-return path, so a sample that issues a snapshot read is not
   // counted until its read returns.  An abort credits, in a single cycle,
   // every sample whose read is still in flight.
   wire [5:0] tot_inc = ((incr && !sn_req) ? 6'd1 : 6'd0)
                      + (sn_ret            ? 6'd1 : 6'd0)
                      + (sn_flush ? {2'b00, sn_busy} : 6'd0);

    always @(posedge clk) begin
        if (incr) begin
            case (i_bin)
                2'd0: b0 <= b0 + 4'd1;
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
            endcase
        end
       total <= total + tot_inc;
    end
   // Snapshot pipeline: the read data shifts on every enabled cycle and the
   // valid bit travels with it, so the shadow register is loaded four cycles
   // after the bin-1 sample that requested the snapshot.
   always @(posedge clk) begin
       if (i_ce) begin
           sn1 <= b0;
           v1  <= sn_flush ? 1'b0 : sn_req;
           sn2 <= sn1;
           v2  <= sn_flush ? 1'b0 : v1;
           sn3 <= sn2;
           v3  <= sn_flush ? 1'b0 : v2;
           sn4 <= sn3;
           v4  <= sn_flush ? 1'b0 : v3;
           if (sn_ret)
               snap <= sn4;
       end
   end

  // Read-port ledger update: one log entry per issued read, one per return.
  always @(posedge clk) begin
      if (sn_req)
          n_req <= n_req + 4'd1;
      if (sn_flush)
          n_done <= n_req;              // the abort returns them all at once
      else if (sn_ret)
          n_done <= n_done + 4'd1;
  end

    assign o_total = total;
    assign o_snap  = snap;

    // Property (precedence): whenever a sample is being committed, the
    // bin-0 population recorded earlier in the shadow register must already
    // have been accounted for in the total-samples register.
    always @(posedge clk)
        if (incr)
            assert (total >= {2'b00, snap});
endmodule

// Serial debug-link pattern probe: detects the fixed 4-bit sync pattern 1101
// arriving MSB-first on i_bit, gated by the probe clock-enable i_ce.
// Match progress is tracked twice: as a binary progress counter (prog) and as
// an independently-updated one-hot shadow (hot). A 4-bit capture window (win)
// records the most recent bits seen.
// A match is only declared once the capture window has been primed with four
// genuinely received bits: the match target (goal) starts above the reachable
// progress range and is stepped down to the pattern length, one step per
// probed bit, as the post-reset filler is shifted out of win.
module swd_sync_probe (
    input  wire clk,
    input  wire i_ce,      // probe strobe: low => link idle, all state frozen
    input  wire i_bit,     // serial bit from the debug pin
    output reg  detect     // registered pulse: full pattern just completed
);
    localparam [3:0] PATTERN = 4'b1101;

    reg [2:0] prog;        // match progress, 0..4 (4 == pattern length)
    reg [4:0] hot;         // one-hot shadow of the same progress
    reg [3:0] win;         // last four bits received, MSB = oldest
    reg [3:0] goal;        // progress value that completes a match: 4 once the
                           // window is primed, >4 while win still holds filler

    initial begin
        prog   = 3'd0;
        hot    = 5'b00001;
        win    = 4'b0000;
        goal   = 4'd7;
        detect = 1'b0;
    end

    // ---- next progress from the binary counter -------------------------
    reg [2:0] nprog;
    always @(*) begin
        case (prog)
            3'd0:    nprog = i_bit ? 3'd1 : 3'd0;              // want 1
            3'd1:    nprog = i_bit ? 3'd2 : 3'd0;              // want 1
            3'd2:    nprog = i_bit ? 3'd2 : 3'd3;              // want 0
            3'd3:    nprog = i_bit ? 3'd4 : 3'd0;              // want 1
            3'd4:    nprog = i_bit ? 3'd2 : 3'd0;              // overlap "1"
            default: nprog = prog;
        endcase
    end

    // ---- next progress from the one-hot shadow (own state only) --------
    reg [4:0] nhot;
    always @(*) begin
        case (hot)
            5'b00001: nhot = i_bit ? 5'b00010 : 5'b00001;
            5'b00010: nhot = i_bit ? 5'b00100 : 5'b00001;
            5'b00100: nhot = i_bit ? 5'b00100 : 5'b01000;
            5'b01000: nhot = i_bit ? 5'b10000 : 5'b00001;
            5'b10000: nhot = i_bit ? 5'b00100 : 5'b00001;
            default:  nhot = 5'b00001;
        endcase
    end

    always @(posedge clk) begin
        if (i_ce) begin
            prog   <= nprog;
            hot    <= nhot;
            win    <= {win[2:0], i_bit};
            if (goal != 4'd4)
                goal <= goal - 4'd1;      // one filler slot retired per bit
            detect <= (nprog == goal);
        end
    end

    // ---- property: two universal relations, globally --------------------
    always @(posedge clk) begin
        assert (detect == hot[4]);
        if (prog == 3'd4)
            assert (win == PATTERN);
    end
endmodule

// Transaction scoreboard with a completion deadline countdown.
// issued/retired are wrapping transaction counters; outst is the occupancy
// of the issue window (WINDOW deep). Every outstanding transaction is forced
// to retire before its RELOAD-cycle deadline countdown reaches zero.
module scoreboard_deadline (
    input  wire clk,
    input  wire ce,      // idle condition: ce low freezes the scoreboard
    input  wire issue,
    input  wire retire,
    output wire busy
);
    localparam [2:0] WINDOW = 3'd4;
    localparam [2:0] RELOAD = 3'd5;
    localparam [1:0] QDEPTH = 2'd2;   // staging queue in front of the window

    reg [3:0] issued;
    reg [3:0] retired;
    reg [2:0] outst;    // outstanding transactions = issued - retired
    reg [1:0] queued;   // accepted, still waiting for a free window slot
    reg [2:0] timer;    // deadline countdown for the oldest outstanding item
    reg       armed;    // sticky: set the first time a transaction is accepted
    reg       pv;       // past valid

    initial begin
        issued  = 4'd0;
        retired = 4'd0;
        outst   = 3'd0;
        queued  = 2'd0;
        timer   = 3'd0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    assign busy = (outst != 3'd0) || (queued != 2'd0);

    // deadline flag: the countdown has run out
    wire expired = (timer == 3'd0);

    // the design completes a transaction itself when the deadline is imminent
    wire force_ret = (outst != 3'd0) && (timer == 3'd1);

    wire [2:0] total = outst + {1'b0, queued};

    // accept while the window plus the staging queue still has capacity
    wire do_issue  = ce && issue && (total < (WINDOW + {1'b0, QDEPTH}));
    wire do_retire = ce && (outst != 3'd0) && (retire || force_ret);

    // a window slot is free, or is being freed by this cycle's retirement
    wire slot_free = (outst < WINDOW) || do_retire;
    // a staged transaction is older than an incoming one, so it goes first
    wire admit  = ce && (queued != 2'd0) && slot_free;
    wire direct = do_issue && slot_free && !admit;
    wire enq    = do_issue && !direct;

    wire [2:0] outst_n  = outst + ((admit || direct) ? 3'd1 : 3'd0)
                                - (do_retire ? 3'd1 : 3'd0);
    wire [1:0] queued_n = queued + (enq ? 2'd1 : 2'd0)
                                 - (admit ? 2'd1 : 2'd0);

    always @(posedge clk) begin
        pv <= 1'b1;

        if (do_issue) begin
            armed  <= 1'b1;
            issued <= issued + 4'd1;
        end

        if (do_retire)
            retired <= retired + 4'd1;

        outst <= outst_n;
        queued <= queued_n;

        if (do_issue || do_retire) begin
            // any scoreboard event restarts (or clears) the deadline
            if (outst_n == 3'd0 && queued_n == 2'd0) timer <= 3'd0;
            else                 timer <= RELOAD;
        end else if (ce && (outst != 3'd0)) begin
            timer <= timer - 3'd1;
        end
    end

    // Bounded response, safety form, in no-change style, scoped after arming:
    // once a transaction has been accepted, whenever the outstanding count did
    // not change and work is still outstanding, the deadline flag must not
    // change either (i.e. the countdown cannot expire under an outstanding
    // request).
    always @(posedge clk) begin
        if (pv && armed && (outst != 3'd0) && $stable(outst))
            assert ($stable(expired));
    end
endmodule

module wdog_saturate (
    input wire i_clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_kick,
    input wire i_ack,
    output wire o_reset,
    output wire [3:0] o_elapsed,
    output wire [3:0] o_remain
);
    // Watchdog window: TIMEOUT ticks without a kick latches a system reset.
    localparam [3:0] TIMEOUT = 4'd12;

    // Saturating up-counter of ticks since the last kick.  It clamps at
    // TIMEOUT (12) even though the 4-bit register admits values up to 15.
    reg [3:0] cnt;
    // Mirror: ticks of grace remaining, saturating down at zero.
    reg [3:0] rem;
    // Latched reset request, cleared only by an acknowledge.
    reg       latched;

   // Update stage: the tick arithmetic is registered for one cycle before
   // it commits, so an update issued on a ce cycle lands on the cycle
   // after it was issued.
   reg [3:0] cnt_stg;
   reg [3:0] rem_stg;
   reg       stg_vld;

   // Forwarding: a pending stage value is newer than the committed
   // register, so back-to-back ticks are computed from the stage.
   wire [3:0] cnt_eff = stg_vld ? cnt_stg : cnt;
   wire [3:0] rem_eff = stg_vld ? rem_stg : rem;

    initial cnt     = 4'd0;
    initial rem     = TIMEOUT;
    initial latched = 1'b0;
   initial cnt_stg = 4'd0;
   initial rem_stg = TIMEOUT;
   initial stg_vld = 1'b0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            cnt     <= 4'd0;
            rem     <= TIMEOUT;
            latched <= 1'b0;
           cnt_stg <= 4'd0;
           rem_stg <= TIMEOUT;
           stg_vld <= 1'b0;
       end else begin
           // Drain the stage: the in-flight update commits one cycle after
           // it was issued, whether or not a new tick arrives.
           if (stg_vld) begin
               cnt <= cnt_stg;
               rem <= rem_stg;
           end
           stg_vld <= 1'b0;

           if (i_ce) begin
           stg_vld <= 1'b1;
           if (i_kick) begin
               cnt_stg <= 4'd0;
               rem_stg <= TIMEOUT;
           end else begin
               cnt_stg <= (cnt_eff < TIMEOUT) ? cnt_eff + 4'd1 : cnt_eff;
               rem_stg <= (rem_eff != 4'd0) ? rem_eff - 4'd1 : rem_eff;
           end

            if (i_ack)
                latched <= 1'b0;
           else if (!i_kick && (rem_eff == 4'd1))
                latched <= 1'b1;
        end
       end
    end

    assign o_reset   = latched;
    assign o_elapsed = cnt;
    assign o_remain  = rem;

    // Universality, global scope: whenever the grace window has run out, the
    // elapsed-tick counter must be sitting on its saturation value.
    always @(posedge i_clk)
        if (rem == 4'd0)
            assert (cnt == TIMEOUT);
endmodule

module fsm_phase_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_start,
    output wire [4:0] o_phase,
    output wire       o_busy
);
    // binary-encoded FSM: only 0..4 are legal encodings, 5..7 are unreachable
    localparam [2:0] S_IDLE   = 3'd0,
                     S_FETCH  = 3'd1,
                     S_DECODE = 3'd2,
                     S_EXEC   = 3'd3,
                     S_WRITE  = 3'd4;

    reg [2:0] state;
    reg [4:0] dec;   // shadow one-hot decode of state
   reg [4:0] dec_s; // decode stage register, one pipeline step ahead of dec
    reg       win;   // window register: opened by a job start, closed at retire

    initial state = S_IDLE;
    initial dec   = 5'b00001;
   initial dec_s = 5'b00001;
    initial win   = 1'b0;

    reg [2:0] nstate;
    always @(*) begin
        case (state)
            S_IDLE:   nstate = i_start ? S_FETCH : S_IDLE;
            S_FETCH:  nstate = S_DECODE;
            S_DECODE: nstate = S_EXEC;
            S_EXEC:   nstate = S_WRITE;
            S_WRITE:  nstate = S_IDLE;
            default:  nstate = 3'd5;   // illegal-encoding trap, never taken
        endcase
    end

    // one-hot decode of the next state; illegal encodings decode to all-zero
    wire [4:0] ndec = (nstate == S_IDLE)   ? 5'b00001 :
                      (nstate == S_FETCH)  ? 5'b00010 :
                      (nstate == S_DECODE) ? 5'b00100 :
                      (nstate == S_EXEC)   ? 5'b01000 :
                      (nstate == S_WRITE)  ? 5'b10000 : 5'b00000;

    always @(posedge i_clk) begin
        if (i_rst) begin
            state <= S_IDLE;
            dec   <= 5'b00001;
           dec_s <= 5'b00001;
            win   <= 1'b0;
        end else if (i_ce) begin
            state <= nstate;
           dec_s <= ndec;      // decode is registered here ...
           dec   <= dec_s;     // ... and presented on o_phase one cycle later
            if ((state == S_IDLE) && i_start)
                win <= 1'b1;               // Q: a job is launched
           else if (dec == 5'b10000)  // WRITE phase has reached o_phase
                win <= 1'b0;               // R: the job retires
        end
    end

    assign o_phase = dec;
    assign o_busy  = win;

    // P: inside the job window the phase decode always names some phase
    always @(posedge i_clk)
        assert (!win || (|dec));

   // P2: a busy job showing phase 0 on o_phase is the launch cycle, so the
   // decode stage must already be carrying the FETCH phase behind it
   always @(posedge i_clk)
       assert (!win || (dec != 5'b00001) || (dec_s == 5'b00010));
endmodule

module seq_detect_1011 (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output wire       match,
    output wire [3:0] hits
);
    // fixed pattern, MSB first: 1 0 1 1
    localparam [3:0] PAT = 4'b1011;

    // match-progress register: number of leading pattern bits matched so far,
    // never exceeds the pattern length (4)
    reg [2:0] prog;
    // shadow register: records that progress 3 (pattern prefix 101) was
    // observed at some earlier cycle
    reg       saw_p3;
    // saturating count of completed pattern matches consumed
    reg [3:0] match_count;
   // commit-stage flag: a detected match is posted here and lands in the
   // counter on the next enabled cycle, keeping the counter adder off the
   // detector's critical path
   reg       cmt_vld;

  // sticky saturation lock: if the counter is already topped out when a
  // match credit retires, the credit is dropped and the reading is frozen,
  // so software can tell "exactly 15" from "15 or more"
  reg       sat_lock;
 // census of match credits that retired into an already-locked counter;
 // firmware uses it to bound how far the frozen reading undercounts
 reg [3:0] drop_cnt;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;
   initial cmt_vld     = 1'b0;
  initial sat_lock    = 1'b0;
 initial drop_cnt    = 4'd0;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
    wire       restart  = (din == PAT[3]) ? 1'b1 : 1'b0;
   // overflow park: once the census tops out the scan is frozen so the
   // count, the census and the detector state stay mutually consistent
   wire       park     = (drop_cnt == 4'd15);

    assign match = (prog == 3'd4);
    assign hits  = match_count;

    always @(posedge clk) begin
        if (rst) begin
            prog        <= 3'd0;
            saw_p3      <= 1'b0;
            match_count <= 4'd0;
           cmt_vld     <= 1'b0;
          sat_lock    <= 1'b0;
         drop_cnt    <= 4'd0;
       end else if (ce && !park) begin
            // shadow bit latches the earlier occurrence of progress 3
            saw_p3 <= saw_p3 | (prog == 3'd3);
           // post a credit for a completed match; retire the credit posted
           // by the previous enabled cycle
           cmt_vld <= (prog == 3'd4);
          if (cmt_vld)
              sat_lock <= sat_lock | (match_count == 4'd15);
          if (cmt_vld && !sat_lock)
               match_count <= (match_count == 4'd15) ? 4'd15 : match_count + 4'd1;
         // tally the credit we just threw away; the park above guarantees
         // this adder cannot wrap
         if (cmt_vld && sat_lock)
             drop_cnt <= drop_cnt + 4'd1;


            if (prog == 3'd4) begin
                // consume the completed match, then begin a fresh scan
                prog        <= restart ? 3'd1 : 3'd0;
            end else if (din == exp_bit) begin
                prog <= prog + 3'd1;
            end else begin
                prog <= restart ? 3'd1 : 3'd0;
            end
        end
    end

    // Precedence, global: any counted match must have been preceded by the
    // pattern prefix reaching progress 3.
    assert property (match_count == 4'd0 || saw_p3);

   // Saturation lock is a consequence of counted traffic: it can only engage
   // after the counter has been driven to full, so the exported count is
   // nonzero and the pattern prefix must already have been seen.
   always @(posedge clk)
       assert (!sat_lock || (saw_p3 && hits != 4'd0));
  // Credits are only discarded against a full, locked counter, so any
  // nonzero census means the exported reading is pinned at maximum and the
  // pattern prefix was seen long ago.
  always @(posedge clk)
      assert (drop_cnt == 4'd0 || (saw_p3 && hits == 4'd15));
endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
    output wire       g_holdoff
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

    // ---- redundant occupancy counter kept in parallel with the valid bits ----
    reg [1:0]  occ;

   // ---- upstream credit counter: free slots the source may still fill ----
   reg [1:0]  space;

  // ---- registered full flag: the upstream gate stays shut one extra cycle ----
  reg        full_r;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;

    initial begin
       space   = 2'd2;
       full_r  = 1'b0;
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    wire do_push   = i_ce && i_valid && !hold;
    wire do_pop    = i_ce && m_valid && i_ready;
    wire load_skid = i_ce && i_valid && !hold && m_valid && !i_ready;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
                if (i_valid && !hold) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

    // ---- parallel occupancy counter ----
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
            if (do_push && !do_pop)
                occ <= occ + 2'd1;
            else if (do_pop && !do_push)
                occ <= occ - 2'd1;
        end
    end

   // ---- credit counter: a slot is spent on push and returned on pop ----
   always @(posedge i_clk) begin
       if (i_reset)
           space <= 2'd2;
       else if (i_ce) begin
           if (do_push && !do_pop)
               space <= space - 2'd1;
           else if (do_pop && !do_push)
               space <= space + 2'd1;
       end
   end

  // ---- full flag registered off the occupancy counter for the gate timing path ----
  always @(posedge i_clk) begin
      if (i_reset)
          full_r <= 1'b0;
      else if (i_ce)
          full_r <= (occ == 2'd2);
  end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
            g_fast <= i_valid && (occ == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
  assign o_upstream_ready = (space != 2'd0) && !full_r;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

   // ---- Q: a hold-off grant means the stage had run out of upstream credit ----
   always @(posedge i_clk)
       if (pv && armed && g_hld)
           assert (space != 2'd2);

  // ---- R: a latched full gate means a record is still parked in the stage
  //      and its upstream credit has not been returned ----
  always @(posedge i_clk)
      if (pv && armed && full_r)
          assert (m_valid && space != 2'd2);

endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
    output wire [2:0] o_inflight
);
// fixed-latency (6 cycle) pipeline occupancy shift register
reg [5:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;
// remaining issue credits: an op is only taken while credits are left
reg [2:0] cred;
// currently programmed outstanding-op limit, retuned at each quiesce point
reg [2:0] lim;
// congestion flag: enable dropped while work was still in flight
reg       thr;
// credit-return path: a retired op's credit takes four more cycles to walk
// back from the pipe tail to the issue-side credit counter
reg       rq0;
reg       rq1;
reg       rq2;
reg       rq3;

initial pipe     = 6'b000000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;
initial cred     = 3'd4;
initial lim      = 3'd4;
initial thr      = 1'b0;
initial rq0      = 1'b0;
initial rq1      = 1'b0;
initial rq2      = 1'b0;
initial rq3      = 1'b0;

wire retire  = pipe[5];
// credit gate on the issue path
wire accept  = issue && (cred != 3'd0);
// nothing still travelling back down the credit-return path
wire rq_empty = !(rq0 || rq1 || rq2 || rq3);
// true quiesce: pipe drained, returns landed, nothing arriving this cycle
wire quiesce = (pipe == 6'b000000) && rq_empty && !issue;

    always @(posedge clk) begin
        if (rst) begin
pipe     <= 6'b000000;
            inflight <= 3'd0;
        end else if (i_ce) begin
pipe     <= {pipe[4:0], accept};
inflight <= inflight + {2'b00, accept} - {2'b00, retire};
        end
    end
// credit accounting and outstanding-limit retuning
always @(posedge clk) begin
    if (rst) begin
        cred <= 3'd4;
        lim  <= 3'd4;
        thr  <= 1'b0;
    end else if (i_ce) begin
        if (quiesce) begin
            lim  <= thr ? 3'd2 : 3'd4;
            cred <= thr ? 3'd2 : 3'd4;
            thr  <= 1'b0;
        end else begin
cred <= cred - {2'b00, accept} + {2'b00, rq3};
        end
    end else if (pipe != 6'b000000) begin
        thr  <= 1'b1;
    end
end

// credit-return path: retire pulses shift back toward the issue side
always @(posedge clk) begin
    if (rst) begin
        rq0 <= 1'b0;
        rq1 <= 1'b0;
        rq2 <= 1'b0;
        rq3 <= 1'b0;
    end else if (i_ce) begin
        rq0 <= retire;
        rq1 <= rq0;
        rq2 <= rq1;
        rq3 <= rq2;
    end
end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module credit_ledger (
    input  wire        clk,
    input  wire        i_ce,
    output wire [4:0]  o_gray,
    output wire        o_drained
);
    // up counter and down counter stepped by the same enable; their sum is 20
    reg [4:0] up;
    reg [4:0] dn;

    // shadow register: records that the up counter has already reached 10
    reg       mark;

    // "before R" scope: starts high, cleared the first time the ledger drains
    reg       before_done;
    // ledger counters: one tick per credit handed out, one per credit back
    reg [4:0] n_iss;
    reg [4:0] n_ret;

    initial up          = 5'd0;
    initial dn          = 5'd20;
    initial mark        = 1'b0;
    initial before_done = 1'b1;
    initial n_iss       = 5'd0;
    initial n_ret       = 5'd0;

    always @(posedge clk) begin
        if (i_ce) begin
            if (dn == 5'd0) begin
                before_done <= 1'b0;   // the drained event has been observed
                up          <= 5'd0;   // recharge with a fresh batch of 20
                dn          <= 5'd20;
                mark        <= 1'b0;   // new batch: halfway not passed yet
            end else if (n_iss == n_ret) begin
                // nothing outstanding: hand a credit to the consumer
                up    <= up + 5'd1;
                mark  <= mark | (up == 5'd9);
                n_iss <= n_iss + 5'd1;
            end else begin
                // the outstanding credit returns and is charged to the pool
                dn    <= dn - 5'd1;
                n_ret <= n_ret + 5'd1;
            end
        end
    end

    // gray view of the issue pointer (clock-domain-crossing flavour)
    assign o_gray    = n_iss ^ (n_iss >> 1);
    assign o_drained = (dn == 5'd0) && (n_iss == n_ret);

    // Property: before the ledger has ever drained, seeing fewer than ten
    // credits left means the up counter must already have passed ten.
    always @(*)
        if (before_done && (dn <= 5'd9))
            assert (mark);
endmodule

module gray_deadline_tracker (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       req,       // request pulse
    output wire [3:0] o_gray,
    output wire [3:0] o_bin,
    output wire [3:0] o_timer,
    output wire       o_busy,
    output wire       o_on_time
);
    // ---- gray counter with its binary shadow -------------------------
    reg [3:0] bin;
    reg [3:0] gray;

   // The binary->gray conversion is pipelined: the encoder runs one
   // increment ahead of the visible counter, so the output register has
   // no XOR chain in front of it.
reg [2:0] gray_pre;     // in-flight gray code for bin+1, low bits
// Bit 3 of a gray code is just bit 3 of the binary count, so the top
// bit skips the XOR network entirely and lives in its own register.
// It is only reloaded on the two counts where it can change, which
// keeps it from toggling with the rest of the pipeline.
reg       gray_pre_top;

    // ---- bounded-response deadline machinery -------------------------
    reg [3:0] timer;      // countdown for the outstanding request
    reg       busy;       // request outstanding
    reg [3:0] goal_gray;  // gray code the counter should show at completion
    reg       armed;      // sticky: set the first time a request is seen

    reg       pv;         // past valid

    localparam [3:0] K = 4'd8;   // response bound

    initial begin
        bin       = 4'd0;
        gray      = 4'd0;
gray_pre     = 3'd1;   // encoder prefilled with gray(bin+1)[2:0]
gray_pre_top = 1'b0;   // ... and its top bit
        timer     = 4'd0;
        busy      = 1'b0;
        goal_gray = 4'd0;
        armed     = 1'b0;
        pv        = 1'b0;
    end

    wire [3:0] bin_nxt  = bin + 4'd1;
   wire [3:0] bin_ahead  = bin_nxt + 4'd1;
   wire [3:0] gray_ahead = bin_ahead ^ (bin_ahead >> 1);
// the held top bit only needs a new value as the count rolls into 8 or 0
wire       top_load  = (bin_ahead[2:0] == 3'd0);

    wire [3:0] goal_bin = bin + K;

    wire accept = i_ce && armed && req && !busy;
    wire tick   = i_ce && busy;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            // gray counter advances together with its binary shadow
            bin  <= bin_nxt;
gray_pre <= gray_ahead[2:0];
if (top_load) gray_pre_top <= bin_ahead[3];
gray     <= {gray_pre_top, gray_pre};

            // sticky arm: first request ever seen arms the monitor forever
            if (req) armed <= 1'b1;

            if (accept) begin
                busy      <= 1'b1;
                timer     <= K;
                goal_gray <= goal_bin ^ (goal_bin >> 1);
            end else if (busy) begin
                if (timer == 4'd1) begin
                    // completion lands exactly on the deadline tick
                    busy  <= 1'b0;
                    timer <= 4'd0;
                end else begin
                    timer <= timer - 4'd1;
                end
            end
        end
    end

    assign o_gray    = gray;
    assign o_bin     = bin;
    assign o_timer   = timer;
    assign o_busy    = busy;
    assign o_on_time = busy && (gray == goal_gray);

    // P: after the monitor is armed, while a request is outstanding the
    // deadline countdown may only move when the gray counter moves --
    // it can never silently run down toward expiry.
    always @(posedge clk)
        if (pv && armed && busy && $stable(gray))
            assert ($stable(timer));
endmodule

// Tracks outstanding memory requests issued into a 4-deep load/store pipeline.
// A shift register records which pipeline stages hold a live request; a separate
// counter tracks how many are in flight.
module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,   // pipeline advance / clock-enable
    input  wire       req,    // a new request is issued into stage 0
    output wire       f_idle, // no requests outstanding (from the counter)
    output wire       f_full, // all pipeline slots occupied (from the counter)
    output wire       f_any,  // some stage holds a request (from the shifter)
    output wire       f_slot  // some stage is free (from the shifter)
);

    reg [3:0] inflight;
    reg [2:0] cnt;
reg [1:0] bcnt;                 // back-half occupancy (stage 3 only)
reg       hand;                 // request in the stage1 -> stage2 handover

    initial inflight = 4'b0000;
    initial cnt      = 3'd0;
initial bcnt     = 2'd0;
initial hand     = 1'b0;

    // the request leaving the last stage completes this cycle
    wire retire = inflight[3];

    always @(posedge clk) begin
        if (rst) begin
            inflight <= 4'b0000;
            cnt      <= 3'd0;
bcnt     <= 2'd0;
hand     <= 1'b0;
        end else if (step) begin
            inflight <= {inflight[2:0], req};
// each pipeline half maintains its own occupancy count locally.  The
// stage1 -> stage2 crossing is registered to keep the adder chains
// short: the front count drops the request on the advance that moves
// it out of stage 1, the handover latch carries it, and the back
// count picks it up on the following advance.
cnt      <= cnt  + {2'b00, req}           - {2'b00, inflight[1]};
bcnt     <= bcnt + {1'b0,  hand}          - {1'b0,  retire};
hand     <= inflight[1];
        end
    end

assign f_idle = (cnt == 3'd0) && (bcnt == 2'd0) && !hand;
assign f_full = ((cnt + {1'b0, bcnt} + {2'b00, hand}) == 3'd4);
    assign f_any  = |inflight;
    assign f_slot = ~(&inflight);

    // P: the counter-derived flags and the shifter-derived flags may never
    // contradict each other -- idle together with an occupied stage, or
    // full together with a free stage.
    always @(posedge clk) assert (!(f_idle && f_any));
    always @(posedge clk) assert (!(f_full && f_slot));

endmodule

module token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle condition: nothing moves when low
    input  wire       req,
    output reg        grant_q,
    output reg [3:0]  tokens
);
    localparam [3:0] BURST  = 4'd12; // bucket cap
    localparam [3:0] REFILL = 4'd3;  // tokens added per timer tick
    localparam [2:0] PERIOD = 3'd4;  // refill timer top

    reg [2:0] timer;
    reg       saw_refill;            // shadow: a refill tick has occurred

   // Refill commit pipeline: the bucket adder/clamp is registered, so the
   // token target computed at a timer tick is applied four cycles later.
   // Layout of each stage: {valid, precomputed token target}.
   reg [4:0] rf_s1, rf_s2, rf_s3, rf_s4;

    wire       tick     = (timer == PERIOD);
    wire       do_grant = ce && req && (tokens != 4'd0);
    wire [4:0] sum      = {1'b0, tokens} + {1'b0, REFILL};
    wire [3:0] refilled = (sum > {1'b0, BURST}) ? BURST : sum[3:0];
   wire       commit   = rf_s4[4];
   wire [3:0] target   = rf_s4[3:0];

    initial begin
        timer      = 3'd0;
        tokens     = 4'd0;
        saw_refill = 1'b0;
        grant_q    = 1'b0;
       rf_s1      = 5'd0;
       rf_s2      = 5'd0;
       rf_s3      = 5'd0;
       rf_s4      = 5'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            timer      <= 3'd0;
            tokens     <= 4'd0;
            saw_refill <= 1'b0;
            grant_q    <= 1'b0;
           rf_s1      <= 5'd0;
           rf_s2      <= 5'd0;
           rf_s3      <= 5'd0;
           rf_s4      <= 5'd0;
        end else if (ce) begin
            timer   <= tick ? 3'd0 : (timer + 3'd1);
            grant_q <= do_grant;

           // stage the refill: capture the clamped target at the tick and
           // walk it down the pipeline, one stage per enabled cycle
           rf_s1 <= {tick, refilled};
           rf_s2 <= rf_s1;
           rf_s3 <= rf_s2;
           rf_s4 <= rf_s3;

            if (tick)
                saw_refill <= 1'b1;

           case ({commit, do_grant})
               2'b10:   tokens <= target;
                2'b01:   tokens <= tokens - 4'd1;
               2'b11:   tokens <= (target == 4'd0) ? 4'd0 : (target - 4'd1);
                default: tokens <= tokens;
            endcase
        end
    end

    // Precedence: a registered grant can only be observed if a refill tick
    // was recorded earlier in the shadow bit.
    always @(posedge clk)
        if (grant_q)
            assert (saw_refill);

endmodule

module dma_burst_engine (
    input  wire       clk,
    input  wire       i_ce,     // idle condition: low freezes all state
    input  wire       start,    // Q: opens the status window
    input  wire [3:0] len,      // requested burst length (beats)
    input  wire       ack,      // R: host acknowledges, closes the window
    output reg        busy,
    output reg  [3:0] beats
);
    // shadow register: records the length that was requested earlier
    reg [3:0] req_len;
    // beats actually pushed out so far in the current burst
    reg [3:0] done_cnt;
    // window register: set by start, cleared by ack
    reg       armed;
   // second request slot: a further transfer queued behind the one in flight,
   // sharing the single beat engine below
   reg [3:0] q_len;
   reg       q_valid;

    initial busy     = 1'b0;
    initial beats    = 4'd0;
    initial req_len  = 4'd0;
    initial done_cnt = 4'd0;
    initial armed    = 1'b0;
   initial q_len    = 4'd0;
   initial q_valid  = 1'b0;

    wire accept = start && !armed && (len != 4'd0);

   // the length shadow is only four bits wide, so an append is refused unless
   // the combined transfer still fits in it
   wire [4:0] q_sum = {1'b0, req_len} + {1'b0, len};
   wire enq = start && !q_valid && (len != 4'd0) && !q_sum[4];

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
                beats    <= len;
                req_len  <= len;      // shadow capture of the earlier event
                done_cnt <= 4'd0;
                busy     <= 1'b1;
                armed    <= 1'b1;
               q_valid  <= 1'b0;   // a fresh burst flushes a stale append
            end else if (busy) begin
                beats    <= beats - 4'd1;
                done_cnt <= done_cnt + 4'd1;
                busy     <= (beats != 4'd1);
               if (enq) begin
                   q_valid <= 1'b1;
                   q_len   <= len;
               end
           end else if (armed && q_valid) begin
               // the queued transfer reuses the engine that just drained and
               // is appended to the still-open window, so the delivered count
               // keeps running and the shadow length grows by the new request
               beats    <= q_len;
               req_len  <= req_len + q_len;
               busy     <= 1'b1;
               q_valid  <= 1'b0;
            end else if (armed && ack) begin
                armed    <= 1'b0;
            end
        end
    end

    // P, part 1: inside the window, while beats remain the burst cannot yet have
    // delivered everything that was requested earlier.
    always @(posedge clk)
        if (armed && busy)
            assert (done_cnt < req_len);

    // P, part 2: inside the window, once the engine is no longer busy the
    // delivered count must exactly match the earlier requested length.
    always @(posedge clk)
        if (armed && !busy)
            assert (done_cnt == req_len);
endmodule

module fetch_credit_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,        // idle condition: when low, nothing moves
    input  wire       fetch,     // issue an instruction into the fetch queue
    input  wire       retire,    // instruction leaves the queue
    output reg  [3:0] used,      // up counter: occupancy of the fetch queue
    output reg  [3:0] credits,   // down counter: remaining free slots
    output wire       can_fetch
);
    // queue depth is 12, but both counters are 4 bits wide (0..15)
    localparam [3:0] DEPTH = 4'd12;

    // a retire frees a queue slot right away, but the credit itself only
    // reaches the free pool a cycle later, through this return stage
    reg        ret_credit;


    initial used    = 4'd0;
    initial credits = DEPTH;
    initial ret_credit = 1'b0;

    assign can_fetch = (credits != 4'd0);

    wire fetch_go  = fetch && !retire && (credits != 4'd0);
    wire retire_go = retire && !fetch && (used != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            used    <= 4'd0;
            credits <= DEPTH;
            ret_credit <= 1'b0;
        end else if (en) begin
            // queue occupancy reacts in the cycle the request is seen
            if (fetch_go)
                used <= used + 4'd1;
            else if (retire_go)
                used <= used - 4'd1;

            // the free pool gives up a slot on fetch, and only gets one
            // back when a returning credit pops out of the return stage
            if (fetch_go && !ret_credit)
                credits <= credits - 4'd1;
            else if (!fetch_go && ret_credit)
                credits <= credits + 4'd1;

            // a retire hands its credit to the return stage
            ret_credit <= retire_go;
            // simultaneous fetch+retire: slot handed straight over
        end
    end

    // P (two assertions, global scope, bounded existence at most 12):
    // neither counter can ever exceed the queue depth, which is strictly
    // smaller than what their 4-bit width admits.
    always @(posedge clk) begin
        assert (used <= DEPTH);
        assert (credits <= DEPTH);
    end
endmodule

module pdk_reqtrack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_arm,     // Q event: arms the tracker (sticky)
    input  wire       i_launch,  // start step: issue a request into the array
    output wire       o_retire,  // finish step: request leaves last stage
    output wire [2:0] o_inflight
);
    parameter STAGES = 4;

    // shift register tracking in-flight requests through the stage array
    reg [STAGES-1:0] pipe;
    // separate count of set bits in that shift register
    reg [2:0]        cnt;
   // issue stage: an accepted launch is parked here for one cycle before it
   // enters stage 0 of the array
   reg              ld_pend;
    // sticky arm register (scope): set the first time i_arm is seen, never cleared
    reg              armed;
    // sticky record that a start actually happened after arming
    reg              started;
    // backpressure: while the array is draining no further launch is accepted
    reg              draining;

    initial pipe    = {STAGES{1'b0}};
    initial cnt     = 3'd0;
   initial ld_pend = 1'b0;
    initial armed   = 1'b0;
    initial started = 1'b0;
    initial draining = 1'b0;

    // a launch is only accepted once the tracker has been armed
    wire launch_ok = i_launch && armed && !draining;
    wire accept = i_ce && launch_ok;
    wire retire = i_ce && pipe[STAGES-1];

    assign o_retire   = retire;
    assign o_inflight = cnt;

    always @(posedge clk) begin
        if (rst) begin
            pipe    <= {STAGES{1'b0}};
            cnt     <= 3'd0;
           ld_pend <= 1'b0;
            armed   <= 1'b0;
            started <= 1'b0;
    draining <= 1'b0;
        end else if (i_ce) begin
           ld_pend <= launch_ok;
           pipe    <= { pipe[STAGES-2:0], ld_pend };
           cnt     <= cnt + (ld_pend          ? 3'd1 : 3'd0)
                          - (pipe[STAGES-1]   ? 3'd1 : 3'd0);
            armed   <= armed || i_arm;
    started <= started || launch_ok;
    // enter drain mode when every stage is occupied, leave it as the
    // last outstanding request retires
           draining <= draining ? !((cnt == 3'd1) && pipe[STAGES-1])
                                : ((cnt == 3'd4) ||
                                   ((cnt == 3'd3) && ld_pend));
        end
    end

    // Chain precedence, after the sticky arm: while armed, the tracker can never
    // report outstanding work unless a start was really accepted first.
    always @(posedge clk)
        if (armed && (cnt != 3'd0))
            assert (started);

    // Backpressure sanity: drain mode is only ever held while a request was
    // really launched and work is still moving through the stage array.
    always @(posedge clk)
        if (draining)
            assert (started && (pipe != {STAGES{1'b0}}));

endmodule

module axi_grant_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire [3:0] req,
    input  wire       done,
    output reg        gnt_valid,
    output reg [1:0]  gnt_idx,
    output reg [2:0]  timer,
    output reg [2:0]  elapsed,
output wire [3:0] o_gnt,
output reg [3:0]  req_hist
);
    // Latency budget granted to an accepted request.
    localparam [2:0] BUDGET = 3'd5;

    // ---------------------------------------------------------------
    // Priority encoder over the request vector: lowest index wins.
    // The encoded index is only meaningful while gnt_valid is set.
    // ---------------------------------------------------------------
    wire       enc_valid = |req;
    wire [1:0] enc_idx   = req[0] ? 2'd0 :
                           req[1] ? 2'd1 :
                           req[2] ? 2'd2 : 2'd3;

    // Retirement of the outstanding grant: either the slave answered,
    // or the budget has been fully consumed.
    wire retire = gnt_valid && (done || ((elapsed == 3'd4) && (timer == 3'd1)));

    assign o_gnt = gnt_valid ? (4'b0001 << gnt_idx) : 4'b0000;

    initial gnt_valid = 1'b0;
    initial gnt_idx   = 2'd0;
    initial timer     = 3'd0;
    initial elapsed   = 3'd0;
initial req_hist  = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            gnt_valid <= 1'b0;
            gnt_idx   <= 2'd0;
            timer     <= 3'd0;
            elapsed   <= 3'd0;
req_hist  <= 4'd0;
        end else if (i_ce) begin
req_hist <= {req_hist[2:0], (|req) & ~done};
            if (!gnt_valid) begin
                if (enc_valid) begin
                    gnt_valid <= 1'b1;
                    gnt_idx   <= enc_idx;
                    timer     <= BUDGET;   // credits left
                    elapsed   <= 3'd0;     // cycles burnt
                end
            end else if (retire) begin
                gnt_valid <= 1'b0;
                timer     <= 3'd0;
                elapsed   <= 3'd0;
            end else begin
                timer   <= timer   - 3'd1;
                elapsed <= elapsed + 3'd1;
            end
        end
    end

    // Bounded response, safety form: the countdown must never reach zero
    // while a grant is still outstanding ...
    always @(posedge clk)
        assert (!gnt_valid || (timer != 3'd0));

    // ... and the elapsed-cycle counter must never run past the budget
    // window while a grant is still outstanding.
    always @(posedge clk)
        assert (!gnt_valid || (elapsed <= 3'd4));
endmodule

module skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,          // idle condition: en low freezes all state
    input  wire       in_valid,
    input  wire [7:0] in_data,
    input  wire       out_ready,
    output wire       in_ready,
    output reg        out_valid,
output reg  [7:0] out_data,
output reg  [3:0] xfer_count
);
    // skid buffer: only meaningful while the stall flag skid_valid is up
    reg        skid_valid;
    reg  [7:0] skid_data;

    // redundant occupancy counter (3 bits wide, but only 0..2 are real)
    reg  [2:0] occ;

    // sticky arm: set the first time a word is actually accepted
    reg        armed;
reg  [7:0] shadow_data;

    initial begin
        out_valid  = 1'b0;
        out_data   = 8'h00;
        skid_valid = 1'b0;
        skid_data  = 8'h00;
        occ        = 3'd0;
        armed      = 1'b0;
xfer_count  = 4'd0;
shadow_data = 8'h00;
    end

    assign in_ready = !skid_valid;

    wire accept = en && in_valid && in_ready;
    wire drain  = en && out_valid && out_ready;

    always @(posedge clk) begin
        if (rst) begin
            out_valid  <= 1'b0;
            out_data   <= 8'h00;
            skid_valid <= 1'b0;
            skid_data  <= 8'h00;
            occ        <= 3'd0;
            armed      <= 1'b0;
xfer_count  <= 4'd0;
shadow_data <= 8'h00;
        end else if (en) begin
            // output register / skid promotion
            if (!out_valid || out_ready) begin
                if (skid_valid) begin
                    out_data   <= skid_data;
                    out_valid  <= 1'b1;
                    skid_valid <= 1'b0;
                end else if (in_valid) begin
                    out_data  <= in_data;
                    out_valid <= 1'b1;
                end else begin
                    out_valid <= 1'b0;
                end
            end else begin
                // downstream stalled: park the incoming word in the skid slot
                if (in_valid && !skid_valid) begin
                    skid_data  <= in_data;
                    skid_valid <= 1'b1;
                end
            end

            // occupancy bookkeeping, tracked independently of the flags
            occ <= occ + (accept ? 3'd1 : 3'd0) - (drain ? 3'd1 : 3'd0);

            if (accept) armed <= 1'b1;
if (accept) shadow_data <= in_data;
if (drain)  xfer_count  <= xfer_count + 4'd1 + {3'b000, shadow_data[7]};
        end
    end

    // P, part 1: once the stage has ever accepted a word, occupancy never
    // exceeds 2 even though the counter is 3 bits wide
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd2);

    // P, part 2: once armed, whenever the skid slot holds a meaningful word the
    // stage is occupancy-saturated at exactly 2
    always @(posedge clk)
        if (armed)
            assert (!skid_valid || occ == 3'd2);
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
output wire [2:0] o_inflight,
output reg  [3:0] o_issue_hist,
output reg  [3:0] o_act_cnt
);
    // fixed-latency (4 cycle) pipeline occupancy shift register
    reg [3:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;
// distractor: history of raw issue requests (not tied to occupancy)
reg [3:0] req_hist;
// distractor: raw retire-pulse accumulator, unrelated to occupancy
reg [3:0] ce_cnt;

    initial pipe     = 4'b0000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;
initial req_hist     = 4'b0000;
initial o_issue_hist = 4'b0000;
initial ce_cnt       = 4'b0000;
initial o_act_cnt    = 4'b0000;

    wire retire = pipe[3];

    always @(posedge clk) begin
        if (rst) begin
            pipe     <= 4'b0000;
            inflight <= 3'd0;
req_hist     <= 4'b0000;
o_issue_hist <= 4'b0000;
ce_cnt       <= 4'b0000;
o_act_cnt    <= 4'b0000;
        end else if (i_ce) begin
            pipe     <= {pipe[2:0], issue};
            inflight <= inflight + {2'b00, issue} - {2'b00, retire};
req_hist     <= {req_hist[2:0], issue};
o_issue_hist <= req_hist ^ {3'b000, issue};
ce_cnt       <= ce_cnt + {3'b000, retire};
o_act_cnt    <= ce_cnt ^ {3'b000, issue};
        end
    end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module sb_window (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_issue,
    input  wire i_retire,
    input  wire i_open,
    input  wire i_close,
    output wire o_full,
    output wire o_empty,
output wire o_mon,
output reg [3:0] o_act
);
    localparam [3:0] WINDOW = 4'd8;

    // transaction scoreboard: issued count, retired count, and a redundant
    // outstanding-transaction register maintained in parallel
    reg [4:0] iss;
    reg [4:0] ret;
    reg [3:0] out_r;

    // registered status flags (one cycle stale, updated only when enabled)
    reg       full_q;
    reg       empty_q;

   // the issue count feeds the status comparator through four retiming
   // registers; the raw counter is too far from the compare logic to make
   // timing in one cycle, so the compare now sees a 4-cycle-old copy
   reg [4:0] iss_d1;
   reg [4:0] iss_d2;
   reg [4:0] iss_d3;
   reg [4:0] iss_d4;

    // monitoring window: opened by i_open, closed by i_close
    reg       mon;

    reg       pv;

    initial iss     = 5'd0;
    initial ret     = 5'd0;
    initial out_r   = 4'd0;
    initial full_q  = 1'b0;
    initial empty_q = 1'b1;
   initial iss_d1  = 5'd0;
   initial iss_d2  = 5'd0;
   initial iss_d3  = 5'd0;
   initial iss_d4  = 5'd0;
    initial mon     = 1'b0;
    initial pv      = 1'b0;
initial o_act   = 4'd0;

    wire acc_iss = i_ce && i_issue  && (out_r <  WINDOW);
    wire acc_ret = i_ce && i_retire && (out_r != 4'd0);

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            iss   <= 5'd0;
            ret   <= 5'd0;
            out_r <= 4'd0;
o_act <= 4'd0;
        end else begin
            if (acc_iss) iss <= iss + 5'd1;
            if (acc_ret) ret <= ret + 5'd1;
            if (acc_iss && !acc_ret)
                out_r <= out_r + 4'd1;
            else if (!acc_iss && acc_ret)
                out_r <= out_r - 4'd1;
if (i_ce && (i_open || i_close))
    o_act <= o_act + 4'd1;
        end

    always @(posedge clk)
        if (i_rst) begin
            full_q  <= 1'b0;
            empty_q <= 1'b1;
           iss_d1  <= 5'd0;
           iss_d2  <= 5'd0;
           iss_d3  <= 5'd0;
           iss_d4  <= 5'd0;
        end else if (i_ce) begin
            full_q  <= (out_r == WINDOW);
           empty_q <= (iss_d4 == ret);
           iss_d1  <= iss;
           iss_d2  <= iss_d1;
           iss_d3  <= iss_d2;
           iss_d4  <= iss_d3;
        end

    always @(posedge clk)
        if (i_rst)
            mon <= 1'b0;
        else if (i_ce) begin
            if (i_close)
                mon <= 1'b0;
            else if (i_open)
                mon <= 1'b1;
        end

    assign o_full  = full_q;
    assign o_empty = empty_q;
    assign o_mon   = mon;

    // P: inside an open monitoring window, when the full flag rises the
    // scoreboard must not simultaneously report empty
    always @(posedge clk)
        if (pv && mon && $rose(full_q))
            assert (!empty_q);
endmodule

module token_bucket_deadline (
    input  wire clk,
    input  wire i_ce,
    input  wire req,
    output wire grant,
    output wire expired
);
    // burst size of the bucket and the response deadline for one request
    localparam [2:0] BURST   = 3'd4;
    localparam [3:0] TIMEOUT = 4'd6;

    reg [2:0] tokens;    // token bucket, capped at BURST
    reg [1:0] tick_cnt;   // refill timer, counts down, tick at zero
    reg       pending;    // window register: set by accepted request, cleared by grant
    reg [3:0] deadline;   // bounded-response countdown for the pending request

   // credit pipeline: a refill tick becomes a credit that walks four stages
   // before it reaches the bucket's refill port
   reg       rfc_s1, rfc_s2, rfc_s3, rfc_s4;

    initial tokens   = BURST;
    initial tick_cnt = 2'd3;
    initial pending  = 1'b0;
    initial deadline = 4'd0;
   initial rfc_s1   = 1'b1;   // reset in phase with the timer: credit just issued
   initial rfc_s2   = 1'b0;
   initial rfc_s3   = 1'b0;
   initial rfc_s4   = 1'b0;

    wire tick     = (tick_cnt == 2'd0);
    wire do_grant = pending && (tokens != 3'd0);
   wire refill   = rfc_s4;   // credit landing at the bucket this cycle

    assign grant   = i_ce && do_grant;
    assign expired = pending && (deadline == 4'd0);

    // refill timer
    always @(posedge clk) if (i_ce)
        tick_cnt <= tick ? 2'd3 : (tick_cnt - 2'd1);

   // one credit per stage, in flight between the timer and the bucket
   always @(posedge clk) if (i_ce) begin
       rfc_s1 <= tick;
       rfc_s2 <= rfc_s1;
       rfc_s3 <= rfc_s2;
       rfc_s4 <= rfc_s3;
   end

    // bucket: drains on a grant, refills on a tick, saturates at BURST
    always @(posedge clk) if (i_ce) begin
       if (do_grant && refill)
            tokens <= tokens;                 // one out, one in
        else if (do_grant)
            tokens <= tokens - 3'd1;
       else if (refill && (tokens < BURST))
            tokens <= tokens + 3'd1;
    end

    // request window and its countdown
    always @(posedge clk) if (i_ce) begin
        if (do_grant)
            pending <= 1'b0;
        else if (pending)
            deadline <= deadline - 4'd1;
        else if (req) begin
            pending  <= 1'b1;
            deadline <= TIMEOUT;
        end
    end

    // P: inside the request window the countdown never expires
    always @(posedge clk)
        if (pending) assert (deadline != 4'd0);
endmodule

module deb_evt_fifo (
    input  wire clk,
    input  wire i_ce,      // sample enable: low freezes all state
    input  wire raw,       // raw (noisy) button level
    input  wire pop,       // consumer request
    output wire empty,
    output wire full,
output reg  o_level,   // last popped debounced level
output reg [3:0] o_pop_tally   // diagnostic: mixed pop tally (non-functional)
);
    // ---- debouncer: saturating stability counter ----
    reg [1:0] stab;
    reg       deb;

    // ---- event FIFO: pointers + occupancy ----
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg [1:0] tail;        // shadow: write pointer snapshot taken at the last push
    reg       mem [0:3];

   // ---- event ledger: free-running push/pop transfer counters ----
   // flag generation is taken from the ledger difference so that empty/full
   // are a direct function of logged transfers rather than of the occupancy
   // accumulator; the counters wrap naturally at their width.
   reg [2:0] n_push, n_pop;
   wire [2:0] occ = n_push - n_pop;   // outstanding entries, mod 8

    // ---- scope register: high until the FIFO has ever been full ----
    reg       never_full;

    // ---- past-valid ----
    reg       pv;

   // ---- diagnostic pop tally (observability only) ----
   reg [3:0] pop_tally;

    initial begin
        stab = 2'd0; deb = 1'b0;
        wptr = 2'd0; rptr = 2'd0; count = 3'd0;
        tail = 2'd0;
       n_push = 3'd0; n_pop = 3'd0;
        never_full = 1'b1;
        pv = 1'b0;
       pop_tally   = 4'd0;
       o_pop_tally = 4'd0;
        o_level = 1'b0;
        mem[0] = 1'b0; mem[1] = 1'b0; mem[2] = 1'b0; mem[3] = 1'b0;
    end

   assign empty = (occ == 3'd0);
   assign full  = (occ == 3'd4);

    // a debounced edge is committed once raw has disagreed with deb for 3 samples
    wire deb_commit = (raw != deb) && (stab == 2'd2);

    wire do_push = i_ce && deb_commit && !full;
    wire do_pop  = i_ce && pop && !empty;

    always @(posedge clk) begin
        if (i_ce) begin
            if (raw != deb) begin
                if (stab == 2'd2) stab <= 2'd0;
                else              stab <= stab + 2'd1;
            end else begin
                stab <= 2'd0;
            end
            if (deb_commit) deb <= raw;

            if (do_push) begin
                mem[wptr] <= raw;
                wptr      <= wptr + 2'd1;
                tail      <= wptr + 2'd1;
            end

            if (do_pop) begin
                o_level <= mem[rptr];
                rptr    <= rptr + 2'd1;
            end

           // log both sides of every completed transfer
           if (do_push) n_push <= n_push + 3'd1;
           if (do_pop)  n_pop  <= n_pop  + 3'd1;

            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase

            if (count == 3'd4) never_full <= 1'b0;
        end
        pv <= 1'b1;
    end

   // diagnostic-only: counts completed pops and publishes a mixed view of it
   always @(posedge clk) begin
       if (i_ce) begin
           if (do_pop) pop_tally <= pop_tally + 4'd1;
           o_pop_tally <= pop_tally ^ {3'b000, raw};
       end
   end

    // Precedence, before-first-full scope, stated about the previous cycle:
    // if the queue has just been drained empty by a pop, the read pointer must
    // have reached the write-pointer snapshot recorded at the earlier push.
    always @(posedge clk)
        if (pv && never_full && (count == 3'd0) && $past(do_pop))
            assert (rptr == $past(tail));
endmodule

module phase_divider_pair (
    input  wire       clk,
    input  wire       ce,       // divider step enable; low = idle, all state held
    input  wire       resync,   // realigns both phase counters, retires the pristine scope
    output reg  [2:0] phase,    // primary phase counter, mod 5
    output reg  [2:0] cnt,      // skewed phase counter, mod 5, built 2 phases ahead
    output reg        en_load,  // divided enable: fires the cycle after phase wraps
    output reg        en_sample,// divided enable: fires the cycle after cnt wraps
    output reg        pristine  // high until the first resync has ever happened
);

    // Load/sample ledger: every load pulse and every sample pulse is logged
    // for the lifetime of the current alignment, so the buffer downstream can
    // account for the two divided enables it sees.
    reg  [3:0] n_load;   // count of load pulses issued
    reg  [3:0] n_samp;   // count of sample pulses issued

    // samples that do not have a matching load behind them yet
    wire [3:0] samp_ahead = n_samp - n_load;
    // a realignment can leave the ping-pong buffer starved; while the sample
    // side is two or more entries ahead, inject make-up load pulses
    wire       makeup     = (samp_ahead >= 4'd2);

   // Load-side stall watchdog: the sink downstream must never be left
   // without a load pulse for long, so the gap since the last one is timed
   // and a make-up pulse is forced once that gap gets too wide.
   reg  [2:0] gap;      // enabled cycles since the last load pulse
   wire       wdog       = (gap >= 3'd6);
   wire       load_pulse = (phase == 3'd4) || makeup || wdog;

    // The skewed counter is constructed 2 phases ahead of the primary phase
    // counter, so the two divided-enable pulses are interleaved by design.
    initial phase     = 3'd0;
    initial cnt       = 3'd2;
    initial en_load   = 1'b0;
    initial en_sample = 1'b0;
    initial pristine  = 1'b1;
    initial n_load    = 4'd0;
    initial n_samp    = 4'd0;
   initial gap       = 3'd0;

    always @(posedge clk) begin
        if (resync) begin
            // hard realignment: both phase counters are slammed to zero, which
            // destroys the constructed skew (and retires the pristine scope)
            phase     <= 3'd0;
            cnt       <= 3'd0;
            en_load   <= 1'b0;
            en_sample <= 1'b0;
            pristine  <= 1'b0;
            n_load    <= 4'd0;
            n_samp    <= 4'd0;
           gap       <= 3'd0;
        end
        else if (ce) begin
            phase     <= (phase == 3'd4) ? 3'd0 : phase + 3'd1;
            cnt       <= (cnt   == 3'd4) ? 3'd0 : cnt   + 3'd1;
            // each divided enable pulses exactly when its phase counter wraps
           en_load   <= load_pulse;
            en_sample <= (cnt   == 3'd4);
            // ledger entries are made as the pulses are issued
           n_load    <= n_load + (load_pulse ? 4'd1 : 4'd0);
            n_samp    <= n_samp + ((cnt == 3'd4) ? 4'd1 : 4'd0);
           gap       <= load_pulse ? 3'd0 : gap + 3'd1;
        end
    end

    // Absence: while the divider has never been resynced, the two divided
    // enables are never asserted in the same cycle.
    always @(posedge clk)
        if (pristine)
            assert (!(en_load && en_sample));

   // Alignment: while the divider has never been resynced, the sample pulse
   // always lands three enabled cycles into the current load window.
   always @(posedge clk)
       if (pristine)
           assert (!en_sample || (gap == 3'd3));

endmodule

module lex_onehot_esc (
    input wire       i_clk,
    input wire       i_reset,
    input wire       i_ce,
    input wire [7:0] i_char,
    output wire      o_in_string,
    output wire [3:0] o_esc_count
);
    // one-hot lexer state: exactly one bit set by construction
    localparam S_IDLE  = 0;
    localparam S_IDENT = 1;
    localparam S_NUM   = 2;
    localparam S_STR   = 3;
    localparam S_ESC   = 4;

    reg [4:0] st;
    reg [3:0] cnt;   // escape sequences counted in the current string literal
   reg [3:0] lim;   // per-literal escape budget; escapes past it are not retired
    reg       arm;   // sticky: set the first time a string literal is being scanned
    reg       pv;

    initial st  = 5'b00001;
    initial cnt = 4'd0;
   initial lim = 4'd8;
    initial arm = 1'b0;
    initial pv  = 1'b0;

    wire is_q   = (i_char == 8'h22);
    wire is_bs  = (i_char == 8'h5C);
    wire is_dig = (i_char >= 8'h30) && (i_char <= 8'h39);
    wire is_alp = ((i_char | 8'h20) >= 8'h61) && ((i_char | 8'h20) <= 8'h7A);

    reg [4:0] nst;
    reg [3:0] ncnt;
   reg [3:0] nlim;

    always @(*) begin
        nst  = st;
        ncnt = cnt;
       nlim = lim;
        if (st[S_IDLE]) begin
            if (is_q) begin
                nst  = 5'b01000;   // open quote: enter string, fresh escape count
                ncnt = 4'd0;
           end else if (is_dig) begin
               nst  = 5'b00100;
               nlim = i_char[3:0];   // leading digit also programs the escape budget
           end
            else if (is_alp)
                nst = 5'b00010;
            else
                nst = 5'b00001;
        end else if (st[S_IDENT]) begin
            nst = (is_alp || is_dig) ? 5'b00010 : 5'b00001;
        end else if (st[S_NUM]) begin
            nst = is_dig ? 5'b00100 : 5'b00001;
        end else if (st[S_STR]) begin
            if (is_q) begin
                nst  = 5'b00001;   // close quote: escape count retired
               ncnt = (cnt > lim) ? (cnt - lim) : 4'd0;   // debit one budget worth
            end else if (is_bs)
                nst = 5'b10000;    // ESC is reachable only from STR
            else
                nst = 5'b01000;
        end else if (st[S_ESC]) begin
            nst  = 5'b01000;       // ESC always returns to STR
           ncnt = (cnt >= lim) ? lim : (cnt + 4'd1);
        end
    end

    always @(posedge i_clk) begin
        if (i_reset) begin
            st  <= 5'b00001;
            cnt <= 4'd0;
           lim <= 4'd8;
        end else if (i_ce) begin
            st  <= nst;
            cnt <= ncnt;
           lim <= nlim;
        end

        if (i_ce && !i_reset && (st[S_STR] || st[S_ESC]))
            arm <= 1'b1;

        pv <= 1'b1;
    end

    assign o_in_string  = st[S_STR] || st[S_ESC];
    assign o_esc_count  = cnt;

    // Universality, in the "after arm" scope, stated about the previous cycle:
    // once a string literal has been seen, the escape counter is always zero
    // whenever the lexer sits in the IDLE state.
    always @(posedge i_clk)
        if (pv && arm)
            assert (!$past(st[S_IDLE]) || ($past(cnt) == 4'd0));
endmodule

module elevator_call_gen (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output reg  [1:0] floor,
    output reg        dir,
    output reg  [3:0] pending,
    output reg  [2:0] dry_cnt,
    output reg  [3:0] lf
);
// Pseudo-random hall-call source.  The shift chain and its feedback XOR
// are split across two flops: the tap is evaluated one cycle ahead into
// lf_fb and shifted in on the next enabled step, which keeps the XOR
// gate out of the shift path.  Taps are chosen so that the combined
// 5-bit generator state {lf, lf_fb} is maximal length (period 31).
reg lf_fb;

initial lf_fb   = 1'b0;
    initial lf      = 4'b0001;
    initial floor   = 2'd0;
    initial dir     = 1'b1;   // 1 = up, 0 = down
    initial pending = 4'b0000;
    initial dry_cnt = 3'd0;

wire       lf_fb_next = lf[3] ^ lf[1];
wire [3:0] lf_next    = {lf[2:0], lf_fb};

// A pseudo-random hall call is issued unless the top three shift
// stages of the generator are all zero.
    wire       new_call   = (lf[3:1] != 3'b000);
    wire [1:0] call_floor = lf[1:0];

    wire at_top = (floor == 2'd3);
    wire at_bot = (floor == 2'd0);

    wire [1:0] floor_next = dir ? (at_top ? floor : floor + 2'd1)
                                : (at_bot ? floor : floor - 2'd1);
    wire       dir_next   = dir ? (at_top ? 1'b0 : 1'b1)
                                : (at_bot ? 1'b1 : 1'b0);

    wire [3:0] set_mask   = new_call ? (4'b0001 << call_floor) : 4'b0000;
    wire [3:0] clr_mask   = (4'b0001 << floor);

    always @(posedge clk) begin
        if (rst) begin
            lf      <= 4'b0001;
lf_fb   <= 1'b0;
            floor   <= 2'd0;
            dir     <= 1'b1;
            pending <= 4'b0000;
            dry_cnt <= 3'd0;
        end else if (step) begin
            lf      <= lf_next;
lf_fb   <= lf_fb_next;
            floor   <= floor_next;
            dir     <= dir_next;
            pending <= (pending | set_mask) & ~clr_mask;
            // consecutive enabled steps during which no new call appeared
            dry_cnt <= new_call ? 3'd0 : (dry_cnt + 3'd1);
        end
    end

    // Bounded existence: the call-starvation streak never exceeds 3,
    // although the counter is 3 bits wide.
    assert property (dry_cnt <= 3'd3);
endmodule

module prio_grant_tracker (
    input  wire       clk,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [3:0] req,
    output reg        vld,     // registered valid: idx meaningful only while set
    output reg  [1:0] idx,     // encoded winner index
    output reg  [3:0] oh,      // registered one-hot grant
    output reg        ack_lo,  // low-half acknowledge, derived from idx
    output reg        ack_hi,  // high-half acknowledge, derived from one-hot
    output reg        armed    // sticky: set the first time a request is taken
);

    // combinational priority encoder (lowest index wins)
    wire       any = |req;
    wire [1:0] enc = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;
    wire [3:0] iso = req & (~req + 4'd1);   // isolate lowest set bit

   // Banked grant position: the half-select bit is registered on its own, so
   // the aging path is an offset toggle plus a bank carry rather than a full
   // 2-bit incrementer feeding the index register.
   reg  bank;                         // 0: grant sits in req[1:0], 1: req[3:2]
   wire nxt_bank = bank ^ idx[0];     // rotation carries out of the current bank


    initial begin
        vld    = 1'b0;
        idx    = 2'd0;
       bank   = 1'b0;
        oh     = 4'b0000;
        ack_lo = 1'b0;
        ack_hi = 1'b0;
        armed  = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            // acknowledge flags are built from the *previous* grant state:
            // one path reads the index, the other reads the one-hot vector
            ack_lo <= vld && (idx < 2'd2);
            ack_hi <= vld && (oh[3] || oh[2]);

            if (any) begin
                // accept a new request: index and one-hot come from the encoder
                vld   <= 1'b1;
                idx   <= enc;
                oh    <= iso;
               bank  <= enc[1];
                armed <= 1'b1;
            end else if (vld) begin
                // no new request: age the standing grant round-robin style
               // advance one slot: the offset toggles, the bank takes the carry
               idx  <= {nxt_bank, ~idx[0]};
               bank <= nxt_bank;
                oh  <= {oh[2:0], oh[3]};
            end
        end
    end

    // P: once the tracker has ever accepted a request, the low-half and
    // high-half acknowledges are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(ack_lo && ack_hi));

endmodule

// DRC check engine: each accepted board-check job walks a saturating
// step counter up to MAXSTEP while a completion countdown runs down.
module drc_engine (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       start,     // new check job requested
    output reg        busy,      // request outstanding
    output reg [3:0]  progress,  // saturating up-counter, clamps at MAXSTEP
    output reg [3:0]  deadline,  // completion countdown
    output reg        armed,     // sticky: a job has been accepted at least once
    output reg        done
);
    localparam [3:0] MAXSTEP = 4'd10;
   localparam [3:0] PASS1   = 4'd6;   // steps budgeted to the first pass

   // second-pass budget, parked out of the live countdown until pass one ends
   reg [3:0] credit;

    initial begin
        busy     = 1'b0;
        progress = 4'd0;
        deadline = 4'd0;
        armed    = 1'b0;
        done     = 1'b0;
       credit   = 4'd0;
    end

    wire accept   = i_ce && start && !busy;
    wire step     = i_ce && busy;
    wire last     = (progress + 4'd1 >= MAXSTEP);
   wire refill   = (deadline <= 4'd1) && (credit != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            busy     <= 1'b0;
            progress <= 4'd0;
            deadline <= 4'd0;
            armed    <= 1'b0;
            done     <= 1'b0;
           credit   <= 4'd0;
        end else if (accept) begin
            busy     <= 1'b1;
            progress <= 4'd0;
           deadline <= PASS1;             // pass one runs on its own budget
           credit   <= MAXSTEP - PASS1;   // remainder held back for pass two
            armed    <= 1'b1;   // sticky once set, never cleared except by rst
            done     <= 1'b0;
        end else if (step) begin
            // saturating up-counter: clamps at MAXSTEP, never reaches 4'd15
            progress <= (progress == MAXSTEP) ? MAXSTEP : progress + 4'd1;
           if (refill) begin
               // pass one spent: hand the reserve to the live countdown
               deadline <= credit;
               credit   <= 4'd0;
           end else begin
               deadline <= (deadline == 4'd0) ? 4'd0 : deadline - 4'd1;
           end
            if (last) begin
                busy <= 1'b0;
                done <= 1'b1;
            end
        end
    end

    // P: while the engine has ever been armed and a check is outstanding,
    // the completion countdown must not have expired.
    always @(*)
        if (armed && busy)
            assert (deadline != 4'd0);
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

    reg [3:0] nxt;

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
            else if (nxt == S_ROUTE)
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);
endmodule

module pcb_pool_top (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] ce,
    input  wire [5:0] start,
    input  wire [5:0] route_ok,
    input  wire [5:0] ack,
    output reg  [3:0] pool,     // free router-engine seats
    output reg  [5:0] hold,     // per-board seat ownership
    output wire [5:0] window    // per-board routing window (tracking)
);
    // Six board flows share a pool of six router/DRC engine seats.
    localparam [3:0] TOTAL = 4'd6;

    wire [3:0] s0, s1, s2, s3, s4, s5;
    wire [7:0] m0, m1, m2, m3, m4, m5;
    wire       t0, t1, t2, t3, t4, t5;

    wire h0 = hold[0];
    wire h1 = hold[1];
    wire h2 = hold[2];
    wire h3 = hold[3];
    wire h4 = hold[4];
    wire h5 = hold[5];

    assign window = {t5, t4, t3, t2, t1, t0};
    // Grants are registered: the seat is booked one cycle after the arbiter
    // picks a winner, so the seat already in flight must be accounted for.
    reg  [5:0] gnt_q;
    wire       q_any = |gnt_q;
// Booking is two-phase: the arbiter parks its winner in gnt_p, and the seat
// is charged to the pool on that board's next enabled cycle. The parking
// station holds one grant, so the arbiter stalls while it is occupied.
reg  [5:0] gnt_p;
wire       p_any = |gnt_p;
wire [5:0] book  = gnt_p & ce;   // parked grant commits on the owner's step

    pcb_flow_fsm u0 (.clk(clk), .rst(rst), .ce(ce[0]), .start(start[0]),
                     .route_ok(route_ok[0]), .ack(ack[0]),
                     .state(s0), .mirror(m0), .tracking(t0));
    pcb_flow_fsm u1 (.clk(clk), .rst(rst), .ce(ce[1]), .start(start[1]),
                     .route_ok(route_ok[1]), .ack(ack[1]),
                     .state(s1), .mirror(m1), .tracking(t1));
    pcb_flow_fsm u2 (.clk(clk), .rst(rst), .ce(ce[2]), .start(start[2]),
                     .route_ok(route_ok[2]), .ack(ack[2]),
                     .state(s2), .mirror(m2), .tracking(t2));
    pcb_flow_fsm u3 (.clk(clk), .rst(rst), .ce(ce[3]), .start(start[3]),
                     .route_ok(route_ok[3]), .ack(ack[3]),
                     .state(s3), .mirror(m3), .tracking(t3));
    pcb_flow_fsm u4 (.clk(clk), .rst(rst), .ce(ce[4]), .start(start[4]),
                     .route_ok(route_ok[4]), .ack(ack[4]),
                     .state(s4), .mirror(m4), .tracking(t4));
    pcb_flow_fsm u5 (.clk(clk), .rst(rst), .ce(ce[5]), .start(start[5]),
                     .route_ok(route_ok[5]), .ack(ack[5]),
                     .state(s5), .mirror(m5), .tracking(t5));

    // A board wants a seat while its window is armed; it gives the seat back
    // on its next enabled cycle after the export has been acknowledged.
wire [5:0] req = window & ~hold & ~gnt_q & ~gnt_p & ce;
    wire [5:0] rel = ~window &  hold & ce;

    // Fixed-priority arbiter: at most one seat handed out per cycle.
wire [3:0] inflight    = {3'b0, p_any} + {3'b0, q_any};
wire       have_credit = (pool > inflight);
    wire [5:0] pri;
    assign pri[0] = req[0];
    assign pri[1] = req[1] & ~req[0];
    assign pri[2] = req[2] & ~(|req[1:0]);
    assign pri[3] = req[3] & ~(|req[2:0]);
    assign pri[4] = req[4] & ~(|req[3:0]);
    assign pri[5] = req[5] & ~(|req[4:0]);

wire [5:0] gnt     = (have_credit && !p_any) ? pri : 6'b0;

    wire [2:0] rel_cnt = {2'b0, rel[0]} + {2'b0, rel[1]} + {2'b0, rel[2]} +
                         {2'b0, rel[3]} + {2'b0, rel[4]} + {2'b0, rel[5]};

    initial begin
        pool = TOTAL;
        hold = 6'd0;
    gnt_q = 6'd0;
gnt_p = 6'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
            hold <= 6'd0;
    gnt_q <= 6'd0;
gnt_p <= 6'd0;
        end else begin
    hold <= (hold | gnt_q) & ~rel;
    pool <= pool - {3'b0, q_any} + {1'b0, rel_cnt};
gnt_q <= book;
gnt_p <= (gnt_p & ~book) | gnt;
        end
    end

    // Pool property: if no seat is free, every board must be holding one.
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 && h1 && h2 && h3 && h4 && h5);
    // Hand-off property: a registered grant is always backed by a seat that
    // was still free when the arbiter committed it, so the pool is never
    // empty while a grant is landing.
    always @(posedge clk)
        if (gnt_q != 6'd0)
            assert (pool != 4'd0);
endmodule

// Packet-capture sensor credit window.
// TOTAL = 8 stream credits.  A burst send spends 3 credits (they become
// "outstanding" bytes in flight); the collector returns exactly one credit
// per enabled cycle while anything is outstanding.  A deadline register is
// reloaded on every accepted burst and counts down otherwise; it must never
// expire while credits are still outstanding.
module credit_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_send,    // producer requests a burst
output wire       o_busy,
output wire [3:0] o_nspend,  // ledger: credits handed to the link (wraps)
output wire [3:0] o_nret,    // ledger: credits taken back (wraps)
output wire       o_phase,   // which link slot the collector is in
output wire       o_rdy,     // collector has a return slot open
output wire [3:0] o_ngrant,  // ledger: return slots opened (wraps)
output wire [3:0] o_nuse     // ledger: return slots consumed (wraps)
);
    reg [3:0] avail;   // credits held by the sensor
    reg [3:0] outst;   // credits outstanding (in flight)
    reg [3:0] timer;   // completion deadline countdown
    reg       armed;   // sticky: set the first time a burst is accepted
reg [3:0] n_spend;  // event ledger: credits spent on bursts
reg [3:0] n_ret;    // event ledger: credits returned by the collector
reg       phase;    // half-rate return link: credits only come back on return slots
reg       rdy;      // a return slot is open and not yet used
reg [3:0] n_grant;  // event ledger: return slots opened by the collector
reg [3:0] n_use;    // event ledger: return slots consumed by a credit

    initial avail = 4'd8;
    initial outst = 4'd0;
    initial timer = 4'd0;
    initial armed = 1'b0;
initial n_spend = 4'd0;
initial n_ret = 4'd0;
initial phase = 1'b0;
initial rdy = 1'b0;
initial n_grant = 4'd0;
initial n_use = 4'd0;

    wire send_ok = i_send && (avail >= 4'd3);
wire grant   = !phase && !rdy;                  // collector opens the next return slot
wire retire  = (outst != 4'd0) && phase && rdy;  // a credit comes back in an open slot

    assign o_busy = (outst != 4'd0);
assign o_nspend = n_spend;
assign o_nret   = n_ret;
assign o_phase  = phase;
assign o_rdy    = rdy;
assign o_ngrant = n_grant;
assign o_nuse   = n_use;

    always @(posedge clk) begin
        if (rst) begin
            avail <= 4'd8;
            outst <= 4'd0;
            timer <= 4'd0;
            armed <= 1'b0;
n_spend <= 4'd0;
n_ret <= 4'd0;
phase <= 1'b0;
rdy <= 1'b0;
n_grant <= 4'd0;
n_use <= 4'd0;
        end else if (i_ce) begin
phase <= ~phase;             // link alternates send / return slots
if (send_ok) n_spend <= n_spend + 4'd3;
if (retire)  n_ret   <= n_ret   + 4'd1;
if (grant) begin
    rdy     <= 1'b1;         // slot opens during the send half-period
    n_grant <= n_grant + 4'd1;
end else if (retire) begin
    rdy   <= 1'b0;           // slot consumed by the returning credit
    n_use <= n_use + 4'd1;
end
            if (send_ok) begin
                // spend three credits, one may come back the same cycle
                avail <= avail - 4'd3 + (retire ? 4'd1 : 4'd0);
                outst <= outst + 4'd3 - (retire ? 4'd1 : 4'd0);
timer <= 4'd15;         // deadline: half-rate return of up to 8 credits
                armed <= 1'b1;          // sticky arm
            end else if (retire) begin
                avail <= avail + 4'd1;
                outst <= outst - 4'd1;
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end else begin
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end
        end
    end

    // Bounded response (safety form), scoped after the first accepted burst:
    // the deadline never expires while credits are still outstanding.
    always @(*)
        assert (!armed || !((timer == 4'd0) && (outst != 4'd0)));
endmodule

module skid_parity_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // stage enable: low => full idle
    input  wire       i_valid,
    input  wire [7:0] i_data,
    input  wire       i_dready,    // downstream ready
    input  wire       i_close,     // closes the observation window
    output wire       o_ready,
    output reg        o_valid,
output reg  [7:0] o_data,
output reg  [3:0] o_beat_count
);

    // ---- skid buffer stage state ----
    reg        stall;      // skid slot occupied
    reg  [7:0] skid;       // buffered word (meaningful only while stall)
    reg        skid_par;   // shadow parity of the buffered word

    reg        o_par;      // shadow parity of the presented word

    // ---- observation window (opened by a skid release, closed by i_close) ----
    reg        win;
    reg  [7:0] acc_data;    // xor of words released inside the window
    reg        acc_par;     // xor of their shadow parities

    initial begin
        stall    = 1'b0;
        skid     = 8'h00;
        skid_par = 1'b0;
        o_valid  = 1'b0;
        o_data   = 8'h00;
        o_par    = 1'b0;
        win      = 1'b0;
        acc_data = 8'h00;
        acc_par  = 1'b0;
o_beat_count = 4'd0;
    end

    assign o_ready = !stall;

    wire do_release = i_ce &&  stall &&  i_dready;
    wire do_direct  = i_ce && !stall &&  i_valid && (i_dready || !o_valid);
    wire do_capture = i_ce && !stall &&  i_valid && o_valid && !i_dready;
    wire do_drop    = i_ce && !stall && !i_valid && i_dready && o_valid;

    always @(posedge clk) begin
        if (rst) begin
            stall    <= 1'b0;
            skid     <= 8'h00;
            skid_par <= 1'b0;
            o_valid  <= 1'b0;
            o_data   <= 8'h00;
            o_par    <= 1'b0;
            win      <= 1'b0;
            acc_data <= 8'h00;
            acc_par  <= 1'b0;
o_beat_count <= 4'd0;
        end else begin
            // datapath
            if (do_release) begin
                o_valid <= 1'b1;
                o_data  <= skid;
                o_par   <= skid_par;
                stall   <= 1'b0;
            end else if (do_direct) begin
                o_valid <= 1'b1;
                o_data  <= i_data;
                o_par   <= ^i_data;
            end else if (do_capture) begin
                stall    <= 1'b1;
                skid     <= i_data;
                skid_par <= ^i_data;
            end else if (do_drop) begin
                o_valid <= 1'b0;
            end

            // window: opened by a release, closed by i_close
            if (i_ce) begin
                if (i_close)         win <= 1'b0;
                else if (do_release) win <= 1'b1;
            end

            // in-window accumulation of released words
            if (do_release) begin
                if (win) begin
                    acc_data <= acc_data ^ skid;
                    acc_par  <= acc_par  ^ skid_par;
                end else begin
                    acc_data <= skid;
                    acc_par  <= skid_par;
                end
            end
if (i_ce) begin
    o_beat_count <= o_beat_count + 4'd1;
end
        end
    end

    // ---- property: inside the window, both shadow parities track their words ----
    always @(posedge clk) begin
        if (win) begin
            assert (o_par   == (^o_data));
            assert (acc_par == (^acc_data));
        end
    end

endmodule

module gray_quantum_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // scheduler quantum tick enable
    output wire [3:0] o_gray,
    output wire [2:0] o_ones
);
    // Ten quantum slots (0..9). The binary shadow does the arithmetic,
    // the gray register is what leaves the clock domain. Terminal count is
    // detected on the gray word, as the CDC-facing logic sees it.
    localparam [3:0] GRAY_LAST = 4'b1101; // gray code of 4'd9

    reg [3:0] bin  = 4'd0;
    reg [3:0] gray = 4'b0000;

   // Lane B is the second scheduler quantum lane. To save area the two
   // lanes time-share one binary shadow and one increment/encode
   // datapath: the owner named by `turn` uses `bin`, the parked lane's
   // shadow waits in `bin_hold`, and the pair swaps on every tick.
   reg [3:0] gray_b   = 4'b0000;
   reg [3:0] bin_hold = 4'd0;
   reg       turn     = 1'b0;   // 0: lane A owns the shared shadow

   wire [3:0] gray_sel = turn ? gray_b : gray;

   wire       wrap    = (gray_sel == GRAY_LAST);
    wire [3:0] bin_nxt = wrap ? 4'd0 : (bin + 4'd1);

    // occupancy of the gray word: how many lanes are asserted this slot
    wire [2:0] ones = {2'b00, gray[0]} + {2'b00, gray[1]} +
                      {2'b00, gray[2]} + {2'b00, gray[3]};
    wire       occ_hi = (ones >= 3'd3);

    assign o_gray = gray;
    assign o_ones = ones;

    always @(posedge clk) begin
        if (rst) begin
            bin  <= 4'd0;
            gray <= 4'b0000;
           gray_b   <= 4'b0000;
           bin_hold <= 4'd0;
           turn     <= 1'b0;
        end else if (i_ce) begin
           // the lane owning the datapath advances its gray word, then
           // the shared shadow is handed over to the other lane
           if (turn) gray_b <= bin_nxt ^ (bin_nxt >> 1);
           else      gray   <= bin_nxt ^ (bin_nxt >> 1);
           bin      <= bin_hold;
           bin_hold <= bin_nxt;
           turn     <= ~turn;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Bounded existence: the gray word never carries four asserted lanes,
    // so whenever the high-occupancy flag rises it rises to exactly three.
    always @(posedge clk)
        if (pv && $rose(occ_hi))
            assert (ones == 3'd3);
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       issue,     // new operation issued this advance
    output wire       o_retire,  // fixed-latency result leaving the unit
    output wire [2:0] o_occ
);
// 3-deep shift register feeding a registered writeback stage:
// bit k = op issued k advances ago
reg [2:0] pipe;
    // occupancy: incremented on issue, decremented when the tail drains
    reg [2:0] occ;
    // sticky arm: set the first time an operation is ever issued
    reg       armed;
// registered result stage: the final latency slot lives here
reg       wb;
// second beat of the narrow result bus; the pipe cannot advance during it
reg       beat;
// credit-based issue throttle: free slots in the 4-stage result path
reg [2:0] credit;

initial pipe  = 3'b000;
    initial occ   = 3'd0;
    initial armed = 1'b0;
initial wb    = 1'b0;
initial beat  = 1'b0;
initial credit = 3'd4;
wire adv = i_ce && !beat;
// an issue is only taken when the unit still has a free slot
wire acc = issue && (credit != 3'd0);

assign o_retire = adv && wb;
    assign o_occ    = occ;

    always @(posedge clk) begin
        if (rst) begin
pipe  <= 3'b000;
            occ   <= 3'd0;
            armed <= 1'b0;
wb    <= 1'b0;
beat  <= 1'b0;
credit <= 3'd4;
end else begin
if (adv) begin
pipe <= {pipe[1:0], acc};
wb   <= pipe[2];
occ    <= occ    + (acc ? 3'd1 : 3'd0) - (wb ? 3'd1 : 3'd0);
credit <= credit - (acc ? 3'd1 : 3'd0) + (wb ? 3'd1 : 3'd0);
if (acc)
                armed <= 1'b1;
end
if (i_ce)
beat <= !beat && wb;
        end
    end

    // P: once the unit has ever issued, at most 4 operations are in flight.
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd4);

   // P2: a result waiting in writeback means the credit pool is not full.
   always @(posedge clk)
       assert (!wb || credit <= 3'd3);
endmodule

module pwm_precedence (
    input  wire       clk,
    input  wire       ce,
    input  wire       load,
    input  wire [3:0] duty_in,
    output wire       o_pwm,
    output wire       o_period_start
);
    // 12-cycle PWM period: counter runs 0..11 and reloads.
    localparam [3:0] PERIOD_M1 = 4'd11;

    reg [3:0] cnt;       // period counter
    reg [3:0] duty_act;  // active duty, latched at period start
    reg [3:0] duty_pend; // pending (requested) duty
    reg [3:0] hi_left;   // shadow: high-cycle budget recorded at last period start
    reg [3:0] duty_stg;  // prefetched duty feeding the compare path

    initial cnt       = 4'd0;
    initial duty_act  = 4'd0;
    initial duty_pend = 4'd0;
    initial hi_left   = 4'd0;
    initial duty_stg  = 4'd0;

    wire wrap = (cnt == PERIOD_M1);
    wire prefetch = (cnt == PERIOD_M1 - 4'd1);
    // the duty pipeline is already latched during the last two cycles of a
    // period, so a request arriving there is deferred to the next period
    wire duty_hold = prefetch || wrap;

    // seeded construct: output high exactly while the counter is below the duty
    assign o_pwm          = (cnt < duty_act);
    assign o_period_start = (cnt == 4'd0);

    always @(posedge clk) begin
        if (ce) begin
            // prefetch one cycle ahead of the boundary so the cnt<duty
            // compare gets a full cycle of setup on the new duty value
            if (prefetch)
                duty_stg <= duty_pend;
            if (wrap) begin
                // new period: both the active duty and the high budget are
                // (re)loaded from the pending duty requested earlier
                cnt      <= 4'd0;
    duty_act <= duty_stg;
                hi_left  <= duty_pend;
            end else begin
                cnt <= cnt + 4'd1;
                if (hi_left != 4'd0)
                    hi_left <= hi_left - 4'd1;
            end
    if (load && !duty_hold)
                duty_pend <= duty_in;
        end
    end

    // past-valid register so cycle zero is not judged
    reg pv = 0;
    always @(posedge clk)
        pv <= 1'b1;

    // Precedence: if the output was driven high last cycle, then a nonzero
    // high-cycle budget (recorded at the earlier period start) must still have
    // been available at that time.
    always @(posedge clk)
        if (pv && $past(o_pwm))
            assert ($past(hi_left) != 4'd0);
endmodule

module elastic_tag_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       start,      // Q: opens the observation window
    input  wire       stop,       // R: closes the observation window
    input  wire       push,
    input  wire       pop,
    input  wire [3:0] din,
    output wire [3:0] head_data,
    output wire       head_valid,
output wire       marked_seen,
output reg [3:0] push_count
);
    // two-entry elastic buffer: one valid flag per slot, head/tail flags,
    // plus an occupancy counter that mirrors the flags
    reg [1:0] cnt;
    reg       hp, tp;      // head flag / tail flag
    reg       v0, v1;      // per-slot occupancy flags
    reg [3:0] mem0, mem1;

    // window + shadow register for the precedence check
    reg       win;
    reg       seen_hi;
reg       pop_toggle;

    initial begin
        cnt     = 2'd0;
        hp      = 1'b0;
        tp      = 1'b0;
        v0      = 1'b0;
        v1      = 1'b0;
        mem0    = 4'd0;
        mem1    = 4'd0;
        win     = 1'b0;
        seen_hi = 1'b0;
push_count = 4'd0;
pop_toggle = 1'b0;
    end

    // a window may only be opened on an empty buffer; it may be reopened
    wire start_acc = start && !win && (cnt == 2'd0);
    wire stop_acc  = stop && win && !start_acc;

    wire do_push = push && !start_acc && (cnt != 2'd2);
    wire do_pop  = pop  && !start_acc && (cnt != 2'd0);

    assign head_valid  = hp ? v1   : v0;
    assign head_data   = hp ? mem1 : mem0;
    assign marked_seen = seen_hi;

    always @(posedge clk) begin
        if (rst) begin
            cnt     <= 2'd0;
            hp      <= 1'b0;
            tp      <= 1'b0;
            v0      <= 1'b0;
            v1      <= 1'b0;
            win     <= 1'b0;
            seen_hi <= 1'b0;
push_count <= 4'd0;
pop_toggle <= 1'b0;
        end else begin
            if (do_push) begin
                if (tp) begin
                    mem1 <= din;
                    v1   <= 1'b1;
                end else begin
                    mem0 <= din;
                    v0   <= 1'b1;
                end
                tp <= ~tp;
            end

            if (do_pop) begin
                if (hp) v1 <= 1'b0;
                else    v0 <= 1'b0;
                hp <= ~hp;
            end

            cnt <= cnt + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);

            if (start_acc) begin
                win     <= 1'b1;
                seen_hi <= 1'b0;
            end else if (stop_acc) begin
                win     <= 1'b0;
            end else if (do_push && win && din[3]) begin
                seen_hi <= 1'b1;
            end
if (do_pop) begin
    pop_toggle <= ~pop_toggle;
end
if (do_push) begin
    push_count <= push_count + 4'd1;
end else if (pop_toggle) begin
    push_count <= push_count ^ 4'd3;
end
        end
    end

    // Precedence, inside the window: a marked item can only be observed at the
    // head if a marked item was pushed earlier in this same window.
    assert property (!win || !head_valid || !head_data[3] || seen_hi);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;
   localparam [2:0] M = 3'd3;  // samples counted by the run counter
   localparam [1:0] G = 2'd2;  // K - M: steps counted by the hold-off stage

    reg       samp     = 1'b0;  // last accepted raw sample
   reg [2:0] cnt      = 3'd0;  // stability run counter, saturates at M
   reg       stable_f = 1'b0;  // decoded "full K-sample count elapsed" flag
   reg [1:0] hold     = 2'd0;  // tail of the count: the K - M steps past cnt's top
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_raw != samp) begin
                // sample changed: restart the stability count
                samp     <= i_raw;
                cnt      <= 3'd0;
               hold     <= 2'd0;
                stable_f <= 1'b0;
cmt_pend <= 1'b0;          // an in-flight commit is aborted
end else begin
   if (cnt != M) begin
       cnt <= cnt + 3'd1;         // the first M identical samples
   end else if (hold != G) begin
       hold <= hold + 2'd1;       // the tail of the count runs here
       if (hold == G - 2'd1) begin
           // stage the commit; the flag and output move one step later
           cmt_pend <= 1'b1;
           cmt_val  <= samp;
       end
   end
    if (cmt_pend) begin
        o_clean  <= cmt_val;   // commit the debounced value
        stable_f <= 1'b1;
        cmt_pend <= 1'b0;
    end
            end
// cnt == M and hold == G with nothing staged: saturated, everything holds

            if (i_disarm)
                armed <= 1'b0;
            else if (i_arm)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

// Credit-managed transfer engine: three credit pools, one per chain step.
// A credit is spent on ARM, handed on at START and returned by the consumer
// at FINISH.  Total credits in the system is fixed at TOTAL by construction.
module credit_chain (
    input  wire clk,
    input  wire i_ce,      // global enable: low => the engine idles
    input  wire i_arm,
    input  wire i_start,
    input  wire i_done,
    input  wire i_flush,
    output wire o_fin_seen,
output wire o_busy,
output reg [3:0] o_evt_cnt
);
    localparam [3:0] TOTAL = 4'd3;

    // ---- credit counter: credits held + credits in each stage == TOTAL ----
    reg [3:0] free_cr;    // credits held by the producer
    reg [3:0] armed_cr;   // credits spent on ARM, awaiting START
    reg [3:0] busy_cr;    // credits outstanding at the consumer

    // ---- chain history (arm -> start -> finish) ----
    reg ever_arm;
    reg ever_start;
    reg ever_fin;

    // ---- peer chain B: second engine drawing on the same credit pool ----
    reg [3:0] armed_b;    // chain B credits spent on ARM, awaiting START
    reg [3:0] busy_b;     // chain B credits outstanding at its consumer

    // ---- before-flush scope register: starts high, cleared by first flush ----
    reg nf;

    // ---- command-port ownership: both chains share one command port; it is
    //      handed to the other chain once the current owner has drained ----
    reg sel;              // 0 => chain A is served, 1 => chain B
// ---- debug-only activity trace: counts presented command strobes ----
reg [3:0] evt_hist;

    initial begin
        armed_b    = 4'd0;
        busy_b     = 4'd0;
        sel        = 1'b0;
        free_cr    = TOTAL;
        armed_cr   = 4'd0;
        busy_cr    = 4'd0;
        ever_arm   = 1'b0;
        ever_start = 1'b0;
        ever_fin   = 1'b0;
        nf         = 1'b1;
evt_hist   = 4'd0;
o_evt_cnt  = 4'd0;
    end

    wire do_flush = i_ce &&  i_flush;
    wire own_idle = sel ? ((armed_b  == 4'd0) && (busy_b  == 4'd0))
                        : ((armed_cr == 4'd0) && (busy_cr == 4'd0));
    wire do_swap  = i_ce && !i_flush && own_idle && !i_arm && !i_start && !i_done;

    // the port owner is the only chain that sees the command strobes
    wire do_arm   = i_ce && !i_flush && !sel && i_arm   && (free_cr  != 4'd0);
    wire do_start = i_ce && !i_flush && !sel && i_start && (armed_cr != 4'd0);
    wire do_fin   = i_ce && !i_flush && !sel && i_done  && (busy_cr  != 4'd0);

    wire do_arm_b   = i_ce && !i_flush && sel && i_arm   && (free_cr != 4'd0);
    wire do_start_b = i_ce && !i_flush && sel && i_start && (armed_b != 4'd0);
    wire do_fin_b   = i_ce && !i_flush && sel && i_done  && (busy_b  != 4'd0);

    always @(posedge clk) begin
        if (do_flush) begin
            // all credits are recalled to the producer; the chain record for
            // this session is dropped, the finish record is kept.
            free_cr    <= TOTAL;
            armed_cr   <= 4'd0;
            busy_cr    <= 4'd0;
            armed_b    <= 4'd0;
            busy_b     <= 4'd0;
            sel        <= 1'b0;
            ever_arm   <= 1'b0;
            ever_start <= 1'b0;
            nf         <= 1'b0;
evt_hist   <= 4'd0;
o_evt_cnt  <= 4'd0;
        end else if (i_ce) begin
            free_cr  <= free_cr  - do_arm - do_arm_b + do_fin + do_fin_b;
            armed_cr <= armed_cr + do_arm   - do_start;
            busy_cr  <= busy_cr  + do_start - do_fin;
            armed_b  <= armed_b  + do_arm_b   - do_start_b;
            busy_b   <= busy_b   + do_start_b - do_fin_b;
            if (do_swap) sel <= ~sel;
            if (do_arm)   ever_arm   <= 1'b1;
            if (do_start) ever_start <= 1'b1;
            if (do_fin)   ever_fin   <= 1'b1;
evt_hist  <= {evt_hist[2:0], (i_arm | i_start | i_done)};
o_evt_cnt <= o_evt_cnt + {3'd0, (evt_hist[3] | i_arm | i_start | i_done)};
        end
    end

    assign o_fin_seen = ever_fin;
    assign o_busy     = (busy_cr != 4'd0) || (busy_b != 4'd0);

    // Chain precedence, in the before-flush scope: a FINISH can never have been
    // observed unless an ARM and a START were observed first.
    always @(*)
        if (nf)
            assert (!ever_fin || (ever_arm && ever_start));
endmodule

module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] req,
    output reg  [3:0] gnt,
    output reg  [1:0] stage
);
    // round-robin arbiter state
    reg [1:0] last_gnt;
    // chain-precedence bookkeeping: arm (line0) -> start (line1) -> finish (line2)
    reg       seen_arm;
    reg       seen_start;
    // sticky scope register: set the first time any grant is issued
    reg       armed;
   // peer chain B: shares the start unit with chain A
   // arm(line2) -> start(line3) -> finish(line1)
   reg [1:0] stage_b;
   // shared start unit is primed and not yet consumed
   reg       start_tok;
  // posted stage-update pipe: a chain A stage advance is handed to the
  // writeback pipe and only lands on the stage register four cycles later.
  // 2'd0 in a slot means "nothing posted here".
  reg [1:0] upd_p0;
  reg [1:0] upd_p1;
  reg [1:0] upd_p2;
  reg [1:0] upd_p3;

    initial begin
        last_gnt   = 2'd3;
        gnt        = 4'b0000;
        stage      = 2'd0;
        seen_arm   = 1'b0;
        seen_start = 1'b0;
        armed      = 1'b0;
       stage_b    = 2'd0;
       start_tok  = 1'b0;
      upd_p0     = 2'd0;
      upd_p1     = 2'd0;
      upd_p2     = 2'd0;
      upd_p3     = 2'd0;
    end

    // combinational round-robin grant: one-hot, never on a non-requesting line
    reg [3:0] gnt_c;
    always @(*) begin
        case (last_gnt)
            2'd0: gnt_c = req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 : 4'b0000;
            2'd1: gnt_c = req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 : 4'b0000;
            2'd2: gnt_c = req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 : 4'b0000;
            default: gnt_c = req[0] ? 4'b0001 :
                             req[1] ? 4'b0010 :
                             req[2] ? 4'b0100 :
                             req[3] ? 4'b1000 : 4'b0000;
        endcase
    end

    wire [1:0] gnt_idx = gnt_c[0] ? 2'd0 :
                         gnt_c[1] ? 2'd1 :
                         gnt_c[2] ? 2'd2 : 2'd3;

    wire fire = i_ce && (gnt_c != 4'b0000);
  // only one stage update may be outstanding in the pipe
  wire upd_busy = (upd_p0 | upd_p1 | upd_p2 | upd_p3) != 2'd0;

    always @(posedge clk) begin
        gnt <= fire ? gnt_c : 4'b0000;
      if (i_ce) begin
          // last slot retires onto the stage register, then the pipe shifts
          if (upd_p3 != 2'd0)
              stage <= upd_p3;
          upd_p3 <= upd_p2;
          upd_p2 <= upd_p1;
          upd_p1 <= upd_p0;
          upd_p0 <= 2'd0;
      end
        if (fire) begin
            last_gnt <= gnt_idx;
            armed    <= 1'b1;
            case (stage)
                2'd0: begin
                   if (gnt_c[0] && !upd_busy) begin
                       upd_p0   <= 2'd1;   // post ARM step
                        seen_arm <= 1'b1;
                    end
                end
                2'd1: begin
                   if (gnt_c[1] && !upd_busy) begin
                       upd_p0     <= 2'd2; // post START step
                        seen_start <= 1'b1;
                  end else if (start_tok && gnt_c[2] && !upd_busy) begin
                      upd_p0     <= 2'd3; // start unit already primed: skip START
                   end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                       start_tok  <= 1'b0; // release shared start unit
                      upd_p0     <= 2'd0; // abort flushes the posted update
                      upd_p1     <= 2'd0;
                      upd_p2     <= 2'd0;
                      upd_p3     <= 2'd0;
                    end
                end
                2'd2: begin
                   if (gnt_c[2] && !upd_busy) begin
                       upd_p0 <= 2'd3;     // post FINISH step
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                       start_tok  <= 1'b0; // release shared start unit
                      upd_p0     <= 2'd0; // abort flushes the posted update
                      upd_p1     <= 2'd0;
                      upd_p2     <= 2'd0;
                      upd_p3     <= 2'd0;
                    end
                end
                default: begin
                    stage      <= 2'd0;     // retire transaction
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                   start_tok  <= 1'b0;     // release shared start unit
                  upd_p0     <= 2'd0;     // nothing left to post
                  upd_p1     <= 2'd0;
                  upd_p2     <= 2'd0;
                  upd_p3     <= 2'd0;
                end
            endcase
           // peer chain B drives the same start unit from the high lines
           case (stage_b)
               2'd0: if (gnt_c[2]) stage_b <= 2'd1;   // ARM step (B)
               2'd1: if (gnt_c[3]) begin
                         stage_b    <= 2'd2;          // START step (B)
                         seen_start <= 1'b1;          // shared unit has run
                         start_tok  <= 1'b1;          // and stays primed
                     end
               2'd2: if (gnt_c[1]) begin
                         stage_b   <= 2'd3;           // FINISH step (B)
                         start_tok <= 1'b0;           // B consumes the unit
                     end
               default: stage_b <= 2'd0;              // retire B
           endcase
        end
    end

    // P: once the arbiter has ever granted (sticky armed), a finished
    // transaction can only be observed if arm and start really happened.
    always @(posedge clk)
        if (armed && stage == 2'd3)
            assert (seen_arm && seen_start);
endmodule

module elastic_profile_buf (
    input wire       i_clk,
    input wire       i_rst,
    input wire       i_push,
    input wire       i_pop,
    input wire [7:0] i_data,
    output wire      o_valid,
    output wire      o_full,
    output wire [7:0] o_data,
output wire [2:0] o_count,
output reg [3:0] o_push_tally
);
    // Two-entry elastic buffer holding profiling samples.
    // Entry 0 is the head, entry 1 is the tail.  v0/v1 are the head/tail
    // occupancy flags; count is a separate occupancy register that is
    // maintained in parallel with the flags.
    reg       v0, v1;
    reg [7:0] d0, d1;
    reg [2:0] count;
   // Skid slot behind the tail.  o_full is raised as soon as the tail fills,
   // but one upstream beat may already be in flight, so it is absorbed here
   // and handed to the tail as soon as a pop frees it.
   reg       s_v;
   reg [7:0] s_d;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;
   initial s_v   = 1'b0;
   initial s_d   = 8'h00;
initial o_push_tally = 4'd0;

    // "full" is decided purely by the tail flag
    wire w_full  = v1;
    wire do_push = i_push && !w_full;
    wire do_pop  = i_pop  && v0;
   // a beat arriving while full is taken by the skid slot, unless a pop is
   // freeing the tail this cycle, in which case it goes straight to the tail
   wire do_skid = i_push && w_full && !s_v && !do_pop;

    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
           s_v   <= 1'b0;
           s_d   <= 8'h00;
o_push_tally <= 4'd0;
        end else if (do_push && do_pop) begin
            // head leaves, new sample becomes the head: occupancy unchanged
            d0    <= i_data;
        end else if (do_push) begin
            if (!v0) begin
                v0 <= 1'b1;
                d0 <= i_data;
            end else begin
                v1 <= 1'b1;
                d1 <= i_data;
            end
            count <= count + 3'd1;
        end else if (do_pop) begin
            // tail slides down into the head slot
           v0 <= v1;
           d0 <= d1;
           if (s_v) begin
               // the parked skid sample takes the freed tail slot
               v1    <= 1'b1;
               d1    <= s_d;
               s_v   <= 1'b0;
               count <= count - 3'd1;
           end else if (i_push) begin
               // we reported full, so this beat lands in the freed tail
               v1 <= 1'b1;
               d1 <= i_data;
           end else begin
               v1    <= 1'b0;
               count <= count - 3'd1;
           end
       end else if (do_skid) begin
           s_v   <= 1'b1;
           s_d   <= i_data;
           count <= count + 3'd1;
       end
        // i_push = i_pop = 0 : the buffer idles, all state held
if (!i_rst && do_push)
    o_push_tally <= o_push_tally + 4'd1;
    end

    assign o_valid = v0;
    assign o_full  = w_full;
    assign o_data  = d0;
    assign o_count = count;

    // P: whenever the buffer is not reporting full, the recorded occupancy
    // is at most one sample (the 3-bit register would allow up to 7).
    always @(posedge i_clk)
        if (!w_full)
            assert (count <= 3'd1);
endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;

   // transaction ledger: one entry per chain run.  Free-running event
   // counters, they simply wrap at four bits; software reads the pair and
   // takes the difference to see whether a run is still outstanding.
   reg [3:0] n_acq;
   initial   n_acq = 4'd0;
   reg [3:0] n_rel;
   initial   n_rel = 4'd0;
   // single-slot occupancy interlock
   reg       busy;
   initial   busy = 1'b0;

    wire [2:0] gray  = bin ^ (bin >> 1);
    wire [2:0] delta = sync1 ^ sync2;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

   // outstanding runs according to the ledger.  The chain has exactly one
   // slot, so two or more outstanding runs means the ledger and the chain
   // have diverged: abort the run just like a corrupt handshake.
   wire [3:0] outst   = n_acq - n_rel;
   wire       lgr_err = (outst > 4'd1);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
           n_acq     <= 4'd0;
           n_rel     <= 4'd0;
           busy      <= 1'b0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;

           if (bad_ev || lgr_err) begin
                stage <= S_FINISH;
            end else begin
                case (stage)
                S_IDLE:
                   if (arm_ev && !busy) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                       busy    <= 1'b1;
                       n_acq   <= n_acq + 4'd1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                    end
                S_STARTED:
                    if (fin_ev)
                        stage <= S_FINISH;
               S_FINISH:
                   // next arm toggle retires the run and recycles the chain
                   if (arm_ev) begin
                       stage     <= S_IDLE;
                       saw_arm   <= 1'b0;
                       saw_start <= 1'b0;
                       busy      <= 1'b0;
                       n_rel     <= n_rel + 4'd1;
                   end
               default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
    assign o_done  = (stage == S_FINISH);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
endmodule

module handshake_deadline (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       start,     // upstream wants a parse burst
    input  wire       done,      // target signals completion early
    output wire       req,
    output wire       ack,
    output wire       busy_o,
    output wire       timeout
);
    // four-phase handshake: IDLE -> REQ (req rises) -> ACK (ack rises)
    //                       -> DROP (req drops) -> IDLE (ack drops)
    localparam [1:0] P_IDLE = 2'd0,
                     P_REQ  = 2'd1,
                     P_ACK  = 2'd2,
                     P_DROP = 2'd3;

    reg [1:0] phase = P_IDLE;   // handshake phase
    reg       busy  = 1'b0;     // mirrors the phase by construction
    reg [2:0] cnt   = 3'd4;     // completion deadline countdown
    reg [2:0] used  = 3'd0;     // enabled cycles this burst has been engaged
    reg       drain = 1'b0;     // extra busy cycle after a full-budget burst

    assign req    = (phase == P_REQ)  || (phase == P_ACK);
    assign ack    = (phase == P_ACK)  || (phase == P_DROP);
    assign busy_o = busy || drain;  // hold busy one cycle longer after a slow burst

    // the deadline has expired while the engine is still engaged
    assign timeout = busy && (cnt == 3'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                P_IDLE: begin
                    drain <= 1'b0;
                    if (start) begin
                        phase <= P_REQ;   // req rises
                        busy  <= 1'b1;
                    end
                end
                P_REQ: begin
                    // req may not drop here; the target must raise ack first.
                    // the deadline forces the ack phase on the last tick,
                    // so the countdown can never run through zero.
                    if (done || cnt <= 3'd1)
                        phase <= P_ACK;   // ack rises
                    else
                        cnt   <= cnt - 3'd1;
                    used  <= used + 3'd1;   // charge the latency counter
                end
                P_ACK: begin
                    phase <= P_DROP;      // req drops, ack still high
                    used  <= used + 3'd1;
                end
                P_DROP: begin
                    phase <= P_IDLE;      // ack drops
                    busy  <= 1'b0;
                    cnt   <= 3'd4;        // rearm the deadline
                    used  <= 3'd0;
                    drain <= (used >= 3'd5); // burst ate the whole budget
                end
            endcase
        end
    end

    // P1: the completion deadline never expires while the engine is engaged
    always @(posedge clk)
        assert (!timeout);

    // P2: while a request is outstanding the deadline is a live value
    always @(posedge clk)
        if (phase == 2'd1)
            assert (cnt >= 3'd1 && cnt <= 3'd4);

    // P3: a burst never stays engaged longer than the budget plus the ack tail
    always @(posedge clk)
        if (busy)
            assert (used <= 3'd5);
endmodule

module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] req,
    output reg  [3:0] gnt,
    output reg  [1:0] stage
);
    // round-robin arbiter state
    reg [1:0] last_gnt;
    // chain-precedence bookkeeping: arm (line0) -> start (line1) -> finish (line2)
    reg       seen_arm;
    reg       seen_start;
    // sticky scope register: set the first time any grant is issued
    reg       armed;

   // peer chain tracker B: walks line2 -> line3 -> line0 and shares the
   // seen_arm / seen_start bookkeeping with tracker A. own_b marks which
   // tracker currently owns that bookkeeping.
   reg [1:0] stage_b;
   reg       own_b;

    initial begin
        last_gnt   = 2'd3;
        gnt        = 4'b0000;
        stage      = 2'd0;
        seen_arm   = 1'b0;
        seen_start = 1'b0;
        armed      = 1'b0;
       stage_b    = 2'd0;
       own_b      = 1'b0;
    end

    // combinational round-robin grant: one-hot, never on a non-requesting line
    reg [3:0] gnt_c;
    always @(*) begin
        case (last_gnt)
            2'd0: gnt_c = req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 : 4'b0000;
            2'd1: gnt_c = req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 : 4'b0000;
            2'd2: gnt_c = req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 : 4'b0000;
            default: gnt_c = req[0] ? 4'b0001 :
                             req[1] ? 4'b0010 :
                             req[2] ? 4'b0100 :
                             req[3] ? 4'b1000 : 4'b0000;
        endcase
    end

    wire [1:0] gnt_idx = gnt_c[0] ? 2'd0 :
                         gnt_c[1] ? 2'd1 :
                         gnt_c[2] ? 2'd2 : 2'd3;

    wire fire = i_ce && (gnt_c != 4'b0000);

    always @(posedge clk) begin
        gnt <= fire ? gnt_c : 4'b0000;
        if (fire) begin
            last_gnt <= gnt_idx;
            armed    <= 1'b1;
           // tracker A is frozen while the peer tracker owns the bookkeeping
           if (!own_b)
            case (stage)
                2'd0: begin
                    if (gnt_c[0]) begin
                        stage    <= 2'd1;   // ARM step
                        seen_arm <= 1'b1;
                    end
                end
                2'd1: begin
                    if (gnt_c[1]) begin
                        stage      <= 2'd2; // START step
                        seen_start <= 1'b1;
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                    end
                end
                2'd2: begin
                    if (gnt_c[2]) begin
                        stage <= 2'd3;      // FINISH step
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                    end
                end
                default: begin
                    stage      <= 2'd0;     // retire transaction
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                end
            endcase
           // peer tracker B: may only take the shared bookkeeping while
           // tracker A is idle; it releases and clears it again on line0
           if (!own_b) begin
               if (stage_b == 2'd0 && stage == 2'd0 && gnt_c[2]) begin
                   own_b    <= 1'b1;
                   stage_b  <= 2'd1;
                   seen_arm <= 1'b1;
               end
           end else begin
               case (stage_b)
                   2'd1: if (gnt_c[3]) begin
                             stage_b    <= 2'd2;
                             seen_start <= 1'b1;
                         end
                   2'd2: if (gnt_c[0]) begin
                             stage_b    <= 2'd0;
                             own_b      <= 1'b0;
                             seen_arm   <= 1'b0;
                             seen_start <= 1'b0;
                         end
                   default: begin
                             stage_b <= 2'd0;
                             own_b   <= 1'b0;
                         end
               endcase
           end
        end
    end

    // P: once the arbiter has ever granted (sticky armed), a finished
    // transaction can only be observed if arm and start really happened.
    always @(posedge clk)
        if (armed && stage == 2'd3)
            assert (seen_arm && seen_start);
endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    // upstream credit: number of empty slots, maintained incrementally so the
    // full indication does not have to decode the valid flags
    reg [1:0] free;
   // peak occupancy telemetry: high-water mark of the occupancy counter since
   // reset, sampled every cycle and read back on the data output while the
   // buffer is empty (the head slot carries no valid word then)
   reg [1:0] hwm;
    reg [7:0] d0, d1;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial free  = 2'd2;
   initial hwm   = 2'd0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
    wire do_push = push && !v1;
    wire do_pop  = pop  &&  v0;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            free  <= 2'd2;
           hwm   <= 2'd0;
            d0    <= 8'h00;
            d1    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                    d0 <= din;
                    v0 <= 1'b1;
                end else begin
                    d1 <= din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
                d0 <= din;
            end

            count <= count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
            free  <= free  - (do_push ? 2'd1 : 2'd0) + (do_pop ? 2'd1 : 2'd0);
           if (count > hwm)
               hwm <= count;
        end
    end

   assign dout    = v0 ? d0 : {6'b0, hwm};
    assign o_empty = !v0;
    assign o_full   = (free == 2'd0);
    assign o_count  = count;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);

    // ---- property: a push accepted last cycle must have gone into a buffer
    // ---- that both occupancy encodings called non-full
    always @(posedge clk)
        if (pv && $past(push) && !$past(v1))
            assert ($past(free) != 2'd0 && $past(count) != 2'd2);

   // ---- property: a cycle in which the upstream credit register reported no
   // ---- free slots must leave the peak occupancy telemetry pegged at two
   always @(posedge clk)
       if (pv && !$past(rst) && $past(free) == 2'd0)
           assert (hwm == 2'd2);
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
   // launch flop on the gray encoder: the crossing wires are driven
   // point to point instead of straight off the encoder cone
   reg [3:0] gq;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;
   // programmable ring bound: the bridge starts at quarter span after reset and
   // opens up one binary step per four completed laps
   reg [3:0] lim;
   reg [1:0] laps;
  // read-side pointer of the same ring: one data word takes two destination
  // beats, so it advances on alternate enables.  it shares the programmable
  // ring bound with the write pointer.
  reg [3:0] cnt2;
  reg [3:0] g2;
  reg       ph;
  // the crossing lane is a single physical 4-bit bundle, so the two pointers
  // take turns on it.  the turn is handed over only at the common origin,
  // where both encoders read zero and the lane sees no step on the bundle.
  reg       own;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
       gq  = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
       lim  = 4'd3;
       laps = 2'd0;
      cnt2 = 4'd0;
      g2   = 4'd0;
      ph   = 1'b0;
      own  = 1'b0;
    end

   wire       wrap     = (cnt >= lim);
   wire [3:0] nxt      = wrap ? 4'd0 : cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);
  wire       wrap2      = (cnt2 >= lim);
  wire [3:0] nxt2       = wrap2 ? 4'd0 : cnt2 + 4'd1;
  wire [3:0] nxt_gray2  = nxt2 ^ (nxt2 >> 1);
  wire       tick2      = ph;
  wire       swap       = (cnt == 4'd0) && (cnt2 == 4'd0);
  wire [3:0] lane       = own ? g2 : g;

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
          gq  <= lane;
           s1  <= gq;
            s2  <= s1;
          ph  <= ~ph;
          if (tick2) begin
              cnt2 <= nxt2;
              g2   <= nxt_gray2;
          end
          if (swap)
              own <= ~own;
           if (wrap) begin
               laps <= laps + 2'd1;
               if (laps == 2'd3)
                   lim <= {lim[2:0], 1'b1};
           end
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
   assign o_settled = (diff == 4'd0) && (gq == s1);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;
   localparam       CH_A = 1'b0;  // commit-stage owner encoding
   localparam       CH_B = 1'b1;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
reg       cmt_ch   = 1'b0;  // which channel owns the commit stage
reg       q_pend   = 1'b0;  // queued commit sitting behind the head slot
reg       q_val    = 1'b0;  // sample value waiting in the queued slot
reg       q_ch     = 1'b0;  // which channel owns the queued slot
reg       wb_pend  = 1'b0;  // writeback slot: entry retired by the head
reg       wb_val   = 1'b0;  // sample value being applied this step
reg       wb_ch    = 1'b0;  // which channel owns the writeback slot
reg       samp_b   = 1'b0;  // last accepted arm-button sample
reg [2:0] cnt_b    = 3'd0;  // arm-button stability counter, saturates at K
reg       arm_clean = 1'b0; // debounced arm-button level
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

// Two commit slots were budgeted (a head that retires and one queued tail);
// the channels arbitrate for a free slot, the raw-sample channel wins a tie.
   wire a_chg   = (i_raw != samp);
   wire b_chg   = (i_arm != samp_b);
   wire a_req   = !a_chg && (cnt   == K - 3'd1);
   wire b_req   = !b_chg && (cnt_b == K - 3'd1);
wire q_full  = cmt_pend && q_pend;
wire grant_a = !q_full && a_req;
wire grant_b = !q_full && b_req && !a_req;
wire grant   = grant_a || grant_b;
wire new_val = grant_a ? samp : samp_b;
wire new_ch  = grant_a ? CH_A : CH_B;
// a queued raw-sample commit is stale the moment the sample moves again
wire keep_q  = q_pend && !(q_ch == CH_A && a_chg);

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
           // ---- channel A: the raw sample ----
           if (a_chg) begin
               // sample changed: restart the stability count
               samp     <= i_raw;
               cnt      <= 3'd0;
               stable_f <= 1'b0;
           end else if (cnt != K) begin
               if (!a_req) begin
                   cnt <= cnt + 3'd1;
               end else if (grant_a) begin
// take a commit slot; the flag and output move one step later
                   cnt      <= cnt + 3'd1;
               end
// both slots busy: hold at K-1 and retry once one frees
           end

           // ---- channel B: the arm button, same filter, same stage ----
           if (b_chg) begin
               samp_b <= i_arm;
               cnt_b  <= 3'd0;
           end else if (cnt_b != K) begin
               if (!b_req) begin
                   cnt_b <= cnt_b + 3'd1;
               end else if (grant_b) begin
                   cnt_b    <= cnt_b + 3'd1;
               end
           end
           // ---- writeback slot: applies the entry retired one step ago ----
           if (wb_pend) begin
               if (wb_ch == CH_A) begin
                   if (!a_chg) begin
                       o_clean  <= wb_val;   // commit the debounced value
                       stable_f <= 1'b1;
                   end
               end else if (!b_chg) begin
                   arm_clean <= wb_val;
               end
           end
           // the head hands its entry to the writeback slot; an entry whose
           // sample moved again in the meantime is dropped instead
           wb_pend <= cmt_pend && !(cmt_ch == CH_A && a_chg)
                               && !(cmt_ch == CH_B && b_chg);
           wb_val  <= cmt_val;
           wb_ch   <= cmt_ch;

           // ---- shared stage: retires one entry per enabled step ----
           if (cmt_pend) begin
// the head always retires: the queued tail shifts up and a fresh
// grant lands in whichever slot is left over
cmt_pend <= keep_q || grant;
cmt_val  <= keep_q ? q_val : new_val;
cmt_ch   <= keep_q ? q_ch  : new_ch;
q_pend   <= keep_q && grant;
q_val    <= new_val;
q_ch     <= new_ch;
           end
else begin
cmt_pend <= grant;
cmt_val  <= new_val;
cmt_ch   <= new_ch;
q_pend   <= 1'b0;
end

            if (i_disarm)
                armed <= 1'b0;
           else if (arm_clean)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

module pdk_reqtrack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_arm,     // Q event: arms the tracker (sticky)
    input  wire       i_launch,  // start step: issue a request into the array
    output wire       o_retire,  // finish step: request leaves last stage
    output wire [2:0] o_inflight
);
    parameter STAGES = 4;

    // shift register tracking in-flight requests through the stage array
    reg [STAGES-1:0] pipe;
    // separate count of set bits in that shift register
    reg [2:0]        cnt;
    // sticky arm register (scope): set the first time i_arm is seen, never cleared
    reg              armed;
    // sticky record that a start actually happened after arming
    reg              started;
   // issue stage: an accepted launch is held here for one cycle (address
   // decode) before it is written into the stage array
   reg              ln_stage;
// express lane: a request issued while the stage array is completely idle
// bypasses the array and completes one cycle later
reg              xpr;

    initial pipe    = {STAGES{1'b0}};
    initial cnt     = 3'd0;
    initial armed   = 1'b0;
    initial started = 1'b0;
   initial ln_stage = 1'b0;
initial xpr      = 1'b0;

    // a launch is only accepted once the tracker has been armed
    wire accept = i_ce && i_launch && armed;
   // the issue stage takes the express lane only when the array is empty
   wire xpr_take = ln_stage && (pipe == {STAGES{1'b0}});
   wire retire = i_ce && (pipe[STAGES-1] || xpr);

    assign o_retire   = retire;
    assign o_inflight = cnt;

    always @(posedge clk) begin
        if (rst) begin
            pipe    <= {STAGES{1'b0}};
            cnt     <= 3'd0;
            armed   <= 1'b0;
            started <= 1'b0;
           ln_stage <= 1'b0;
           xpr      <= 1'b0;
        end else if (i_ce) begin
          pipe    <= { pipe[STAGES-2:0], ln_stage && !xpr_take };
          cnt     <= cnt + (ln_stage ? 3'd1 : 3'd0)
                          - ((pipe[STAGES-1] || xpr) ? 3'd1 : 3'd0);
            armed   <= armed || i_arm;
            started <= started || (i_launch && armed);
           ln_stage <= i_launch && armed;
          xpr     <= xpr_take;
        end
    end

    // Chain precedence, after the sticky arm: while armed, the tracker can never
    // report outstanding work unless a start was really accepted first.
    always @(posedge clk)
        if (armed && (cnt != 3'd0))
            assert (started);

    // Retire/issue provenance: a request can only be observed leaving the last
    // stage, or waiting in the issue stage for address decode, if it entered
    // through an accepted start, which in turn can only happen after arming.
    always @(posedge clk)
        if (o_retire || ln_stage)
            assert (started && armed);

endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

    reg [3:0] nxt;

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
            else if (nxt == S_ROUTE)
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);
endmodule

module pcb_pool_top (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] ce,
    input  wire [5:0] start,
    input  wire [5:0] route_ok,
    input  wire [5:0] ack,
    output reg  [3:0] pool,     // free router-engine seats
    output reg  [5:0] hold,     // per-board seat ownership
    output wire [5:0] window    // per-board routing window (tracking)
);
    // Six board flows share a pool of six router/DRC engine seats.
    localparam [3:0] TOTAL = 4'd6;

    wire [3:0] s0, s1, s2, s3, s4, s5;
    wire [7:0] m0, m1, m2, m3, m4, m5;
    wire       t0, t1, t2, t3, t4, t5;

    wire h0 = hold[0];
    wire h1 = hold[1];
    wire h2 = hold[2];
    wire h3 = hold[3];
    wire h4 = hold[4];
    wire h5 = hold[5];

    assign window = {t5, t4, t3, t2, t1, t0};
    // Grants are registered: the seat is booked one cycle after the arbiter
    // picks a winner, so the seat already in flight must be accounted for.
    reg  [5:0] gnt_q;
    wire       q_any = |gnt_q;
// Booking is two-phase: the arbiter parks its winner in gnt_p, and the seat
// is charged to the pool on that board's next enabled cycle. The parking
// station holds one grant, so the arbiter stalls while it is occupied.
reg  [5:0] gnt_p;
wire       p_any = |gnt_p;
wire [5:0] book  = gnt_p & ce;   // parked grant commits on the owner's step
// Occupancy shadow: seats currently charged out, maintained alongside the
// pool so the arbiter's credit check is one compare against TOTAL.
reg  [3:0] used;

    pcb_flow_fsm u0 (.clk(clk), .rst(rst), .ce(ce[0]), .start(start[0]),
                     .route_ok(route_ok[0]), .ack(ack[0]),
                     .state(s0), .mirror(m0), .tracking(t0));
    pcb_flow_fsm u1 (.clk(clk), .rst(rst), .ce(ce[1]), .start(start[1]),
                     .route_ok(route_ok[1]), .ack(ack[1]),
                     .state(s1), .mirror(m1), .tracking(t1));
    pcb_flow_fsm u2 (.clk(clk), .rst(rst), .ce(ce[2]), .start(start[2]),
                     .route_ok(route_ok[2]), .ack(ack[2]),
                     .state(s2), .mirror(m2), .tracking(t2));
    pcb_flow_fsm u3 (.clk(clk), .rst(rst), .ce(ce[3]), .start(start[3]),
                     .route_ok(route_ok[3]), .ack(ack[3]),
                     .state(s3), .mirror(m3), .tracking(t3));
    pcb_flow_fsm u4 (.clk(clk), .rst(rst), .ce(ce[4]), .start(start[4]),
                     .route_ok(route_ok[4]), .ack(ack[4]),
                     .state(s4), .mirror(m4), .tracking(t4));
    pcb_flow_fsm u5 (.clk(clk), .rst(rst), .ce(ce[5]), .start(start[5]),
                     .route_ok(route_ok[5]), .ack(ack[5]),
                     .state(s5), .mirror(m5), .tracking(t5));

    // A board wants a seat while its window is armed; it gives the seat back
    // on its next enabled cycle after the export has been acknowledged.
wire [5:0] req = window & ~hold & ~gnt_q & ~gnt_p & ce;
    wire [5:0] rel = ~window &  hold & ce;

    // Fixed-priority arbiter: at most one seat handed out per cycle.
wire [3:0] inflight    = {3'b0, p_any} + {3'b0, q_any};
wire [4:0] occ         = {1'b0, used} + {1'b0, inflight};
wire       have_credit = (occ < {1'b0, TOTAL});
    wire [5:0] pri;
    assign pri[0] = req[0];
    assign pri[1] = req[1] & ~req[0];
    assign pri[2] = req[2] & ~(|req[1:0]);
    assign pri[3] = req[3] & ~(|req[2:0]);
    assign pri[4] = req[4] & ~(|req[3:0]);
    assign pri[5] = req[5] & ~(|req[4:0]);

wire [5:0] gnt     = (have_credit && !p_any) ? pri : 6'b0;

    wire [2:0] rel_cnt = {2'b0, rel[0]} + {2'b0, rel[1]} + {2'b0, rel[2]} +
                         {2'b0, rel[3]} + {2'b0, rel[4]} + {2'b0, rel[5]};

    initial begin
        pool = TOTAL;
        hold = 6'd0;
    gnt_q = 6'd0;
gnt_p = 6'd0;
used = 4'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
            hold <= 6'd0;
    gnt_q <= 6'd0;
gnt_p <= 6'd0;
used <= 4'd0;
        end else begin
    hold <= (hold | gnt_q) & ~rel;
    pool <= pool - {3'b0, q_any} + {1'b0, rel_cnt};
gnt_q <= book;
gnt_p <= (gnt_p & ~book) | gnt;
used <= used + {3'b0, q_any} - {1'b0, rel_cnt};
        end
    end

    // Pool property: if no seat is free, every board must be holding one.
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 && h1 && h2 && h3 && h4 && h5);
    // Hand-off property: a registered grant is always backed by a seat that
    // was still free when the arbiter committed it, so the pool is never
    // empty while a grant is landing.
    always @(posedge clk)
        if (gnt_q != 6'd0)
            assert (pool != 4'd0);
    // Occupancy property: with every board seated the pool is fully charged
    // out and the parking station must be empty -- there is no seat left for
    // the arbiter to have booked.
    always @(posedge clk)
        if (hold == 6'b111111)
            assert (used == TOTAL && gnt_p == 6'd0);
endmodule

module seq_detect_1011 (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output wire       match,
    output wire [3:0] hits
);
    // fixed pattern, MSB first: 1 0 1 1
    localparam [3:0] PAT = 4'b1011;

    // match-progress register: number of leading pattern bits matched so far,
    // never exceeds the pattern length (4)
    reg [2:0] prog;
    // shadow register: records that progress 3 (pattern prefix 101) was
    // observed at some earlier cycle
    reg       saw_p3;
    // saturating count of completed pattern matches consumed
    reg [3:0] match_count;
   // commit-stage flag: a detected match is posted here and lands in the
   // counter on the next enabled cycle, keeping the counter adder off the
   // detector's critical path
   reg       cmt_vld;

  // sticky saturation lock: if the counter is already topped out when a
  // match credit retires, the credit is dropped and the reading is frozen,
  // so software can tell "exactly 15" from "15 or more"
  reg       sat_lock;
 // census of match credits that retired into an already-locked counter;
 // firmware uses it to bound how far the frozen reading undercounts
 reg [3:0] drop_cnt;
// credit ledger: posted credits and retired credits are tallied on
// separate free-running counters so firmware can read back, by
// subtraction, how many credits are still in flight in the commit stage
reg [3:0] post_cnt;
reg [3:0] rtr_cnt;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;
   initial cmt_vld     = 1'b0;
  initial sat_lock    = 1'b0;
 initial drop_cnt    = 4'd0;
initial post_cnt    = 4'd0;
initial rtr_cnt     = 4'd0;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
    wire       restart  = (din == PAT[3]) ? 1'b1 : 1'b0;
   // overflow park: once the census tops out the scan is frozen so the
   // count, the census and the detector state stay mutually consistent
   wire       park     = (drop_cnt == 4'd15);
// a credit retires when the commit stage presents it, or when the ledger
// still shows one outstanding after the commit flag was dropped
wire       retire   = cmt_vld || (post_cnt != rtr_cnt);

    assign match = (prog == 3'd4);
    assign hits  = match_count;

    always @(posedge clk) begin
        if (rst) begin
            prog        <= 3'd0;
            saw_p3      <= 1'b0;
            match_count <= 4'd0;
           cmt_vld     <= 1'b0;
          sat_lock    <= 1'b0;
         drop_cnt    <= 4'd0;
post_cnt    <= 4'd0;
rtr_cnt     <= 4'd0;
       end else if (ce && !park) begin
            // shadow bit latches the earlier occurrence of progress 3
            saw_p3 <= saw_p3 | (prog == 3'd3);
           // post a credit for a completed match; retire the credit posted
           // by the previous enabled cycle
           cmt_vld <= (prog == 3'd4);
// ledger sides: log the posting event and the retiring event
post_cnt <= post_cnt + ((prog == 3'd4) ? 4'd1 : 4'd0);
rtr_cnt  <= rtr_cnt  + (retire ? 4'd1 : 4'd0);
if (retire)
              sat_lock <= sat_lock | (match_count == 4'd15);
if (retire && !sat_lock)
               match_count <= (match_count == 4'd15) ? 4'd15 : match_count + 4'd1;
         // tally the credit we just threw away; the park above guarantees
         // this adder cannot wrap
if (retire && sat_lock)
             drop_cnt <= drop_cnt + 4'd1;


            if (prog == 3'd4) begin
                // consume the completed match, then begin a fresh scan
                prog        <= restart ? 3'd1 : 3'd0;
            end else if (din == exp_bit) begin
                prog <= prog + 3'd1;
            end else begin
                prog <= restart ? 3'd1 : 3'd0;
            end
        end
    end

    // Precedence, global: any counted match must have been preceded by the
    // pattern prefix reaching progress 3.
    assert property (match_count == 4'd0 || saw_p3);

   // Saturation lock is a consequence of counted traffic: it can only engage
   // after the counter has been driven to full, so the exported count is
   // nonzero and the pattern prefix must already have been seen.
   always @(posedge clk)
       assert (!sat_lock || (saw_p3 && hits != 4'd0));
  // Credits are only discarded against a full, locked counter, so any
  // nonzero census means the exported reading is pinned at maximum and the
  // pattern prefix was seen long ago.
  always @(posedge clk)
      assert (drop_cnt == 4'd0 || (saw_p3 && hits == 4'd15));
endmodule

module parity_slice_occ (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_data,
    output reg        o_valid,
    output reg  [7:0] o_data,
    output reg        o_retry
);
    // two-deep register slice, each stage protected by a parity bit
    reg [7:0] d0, d1;
    reg       p0, p1;
    reg       v0, v1;

    // occupancy accounting: one 3-bit counter tracking live stages
    reg [2:0] occ;

   // egress check: the word presented on the output register keeps its slice
   // slot for one more cycle while its parity is re-checked, so the credit is
   // returned one cycle after the word leaves
   reg       oq_busy;
   reg       oq_par;

  // sideband echo lane: a control word tagged with bit 6 is parked here and
  // replayed onto the output whenever the data lane's second stage is empty.
  // It draws its slot from the same occupancy pool as the data lane.
  reg [7:0] sb_d;
  reg       sb_p;
  reg       sb_v;

   // programmable slot limit (one or two stages), written by a control word
   reg [2:0] lim;

  // replay bookkeeping: every parity mismatch books one replay slot, and a
  // booked slot is handed back when the egress re-check frees a credit
  reg [2:0] rpy;

    initial begin
        d0 = 8'h00; d1 = 8'h00;
        p0 = 1'b0;  p1 = 1'b0;
        v0 = 1'b0;  v1 = 1'b0;
        occ = 3'd0;
       oq_busy = 1'b0;
       oq_par  = 1'b0;
       sb_d = 8'h00; sb_p = 1'b0; sb_v = 1'b0;
       lim     = 3'd2;
      rpy     = 3'd0;
        o_valid = 1'b0;
        o_data  = 8'h00;
        o_retry = 1'b0;
    end

    // stored parity is checked against stored data every cycle
    wire mism0 = v0 && (p0 != (^d0));
    wire mism1 = v1 && (p1 != (^d1));
wire mismsb = sb_v && (sb_p != (^sb_d));
wire retry  = mism0 || mism1 || mismsb;

   // the slot is only released when the egress parity re-check is clean
   wire oq_bad = oq_busy && (oq_par != (^o_data));
   wire rel    = oq_busy && !oq_bad;

   // control words carry the depth limit instead of payload
   wire cfg  = i_valid && i_data[7];
   wire room = occ < lim;
   wire acc  = i_valid && !cfg && room;
   wire nack = i_valid && !cfg && !room;
  // echo lane arbitration: the parked word only reaches the egress slot when
  // the data lane's second stage is empty, so the lanes never collide
  wire echo    = cfg && i_data[6];
  wire sb_acc  = echo && !sb_v && room;
  wire sb_nack = echo && (sb_v || !room);
  wire sb_go   = sb_v && !v1;

    always @(posedge clk) begin
        if (i_ce) begin
o_retry <= retry || nack || sb_nack || oq_bad || (rpy != 3'd0);
            if (retry) begin
                // corrupted stage: freeze the slice and book a replay slot
                occ <= occ + 3'd1;
               rpy <= rpy + 3'd1;
            end else begin
                // normal shift: stage0 -> stage1 -> output
                d1 <= d0;
                p1 <= p0;
                v1 <= v0;
                d0 <= i_data;
                p0 <= ^i_data;
               v0 <= acc;
oq_busy <= v1 || sb_go;
oq_par  <= v1 ? p1 : sb_p;
sb_v <= sb_acc || (sb_v && !sb_go);
if (sb_acc) begin
    sb_d <= i_data;
    sb_p <= ^i_data;
end
if (cfg && !echo) lim <= i_data[0] ? 3'd2 : 3'd1;
occ <= occ + (acc ? 3'd1 : 3'd0) + (sb_acc ? 3'd1 : 3'd0) - (rel ? 3'd1 : 3'd0);
              if (rel && rpy != 3'd0) rpy <= rpy - 3'd1;
o_valid <= v1 || sb_go;
o_data  <= v1 ? d1 : sb_d;
            end
        end
    end

    // bounded existence: the slice is two deep, so occupancy never exceeds 2
    always @(*) assert (occ <= 3'd2);

   // a replay slot is only booked on a real corruption, so booked slots plus
   // live slice slots never oversubscribe the two-deep slice
   always @(posedge clk)
       assert ({1'b0, occ} + {1'b0, rpy} <= 4'd2);
endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
output wire       g_holdoff,
output reg  [3:0] o_dbg_count
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

// ---- per-slot occupancy accounting, kept in parallel with the valid bits ----
    reg [1:0]  occ;
   reg [1:0]  p_occ;   // priority-class share of the main slot (i_cred[7] set)
reg [1:0]  s_occ;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;
reg  [3:0] dbg_prev;

    initial begin
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
       p_occ   = 2'd0;
s_occ   = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
o_dbg_count = 4'd0;
dbg_prev    = 4'd0;
    end

wire       skid_free  = (s_occ == 2'd0);
wire       load_skid  = i_ce && i_valid && !hold && m_valid && !i_ready && skid_free;
wire       fill_main  = i_ce && i_valid && !m_valid;
wire       drain_main = i_ce && m_valid && i_ready && !hold && !i_valid;
wire       drain_skid = i_ce && hold && i_ready;
// a fresh input record takes the main slot next cycle
wire       main_wr_new  = fill_main || (i_ce && i_valid && m_valid && i_ready && !hold);
// the parked record is promoted out of the skid slot into the main slot
wire       main_wr_skid = i_ce && m_valid && i_ready && hold;
// total records resident in the stage (main slot + skid slot)
wire [1:0] occ_total  = occ + p_occ + s_occ;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
if (i_valid && !hold && skid_free) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

// ---- main-slot occupancy counter ----
   // normal-class records only; the priority-class share lives in p_occ
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
           if (main_wr_new)
               occ <= {1'b0, ~i_cred[7]};
           else if (main_wr_skid)
               occ <= {1'b0, ~s_cred[7]};
           else if (drain_main)
               occ <= 2'd0;
        end
    end

   // ---- main-slot occupancy counter, priority-class share ----
   always @(posedge i_clk) begin
       if (i_reset)
           p_occ <= 2'd0;
       else if (i_ce) begin
           if (main_wr_new)
               p_occ <= {1'b0, i_cred[7]};
           else if (main_wr_skid)
               p_occ <= {1'b0, s_cred[7]};
           else if (drain_main)
               p_occ <= 2'd0;
       end
   end

// ---- skid-slot occupancy counter ----
always @(posedge i_clk) begin
    if (i_reset)
        s_occ <= 2'd0;
    else if (i_ce) begin
        if (load_skid)
            s_occ <= s_occ + 2'd1;
        else if (drain_skid)
            s_occ <= s_occ - 2'd1;
    end
end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
dbg_prev    <= 4'd0;
o_dbg_count <= 4'd0;
        end else if (i_ce) begin
g_fast <= i_valid && (occ_total == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
dbg_prev    <= dbg_prev + {3'b000, (i_valid && i_ready)};
o_dbg_count <= dbg_prev ^ {3'b000, hold};
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
assign o_upstream_ready = !hold && skid_free;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

endmodule

// In-flight tracker for a fixed-latency chart-query render pipeline.
// Each issued query walks a 4-stage valid shift register; occupancy is the
// number of ones currently resident in that shift register.
module query_pipe_tracker (
    input  wire       clk,
    input  wire       ce,        // pipeline advance / idle control
    input  wire       issue,     // a new query is pushed into stage 0
    output wire       retire,    // a rendered result leaves the last stage
    output wire       full,      // tracker says all 4 slots are busy
output reg  [2:0] occ,       // queries in flight
output reg  [3:0] retire_cnt // rolling count of retired queries
);

    reg [3:0] pipe;              // fixed-latency valid shift register
   reg [1:0] apipe;             // 2-stage cached-result render path
    reg       hold;              // input capture slot: query admitted while stalled
    reg       ever_issued;       // shadow: an issue has been observed earlier
    reg       armed;             // scope: still before the pipe was ever full
reg       retire_seen;        // sticky: at least one retirement observed

    initial begin
        pipe        = 4'b0000;
        occ         = 3'd0;
        ever_issued = 1'b0;
        armed       = 1'b1;
        hold        = 1'b0;
       apipe       = 2'b00;
retire_cnt  = 4'd0;
retire_seen = 1'b0;
    end

   assign retire = pipe[3] || apipe[1];
    assign full   = (occ == 3'd4);

    // Admission control: the tracker backpressures at capacity, and a query
    // taken while the pipe is not advancing waits in the capture slot.
    wire room   = (occ != 3'd4);
    wire accept = issue && !hold && room;   // query admitted this cycle
    wire inject = hold || accept;           // entry pushed into stage 0
   // A query offered while the capture slot is still busy is served from the
   // result cache instead: shorter path, same 4-slot occupancy budget.
   wire aux_accept = ce && issue && hold && room;

    always @(posedge clk) begin
        if (ce) begin
            // drain: stage 3 retires, everything shifts, stage 0 takes issue
            pipe <= {pipe[2:0], inject};

            // occupancy bookkeeping: +1 on issue, -1 on retire
           occ  <= occ + {2'b00, accept} + {2'b00, aux_accept}
                       - {2'b00, pipe[3]} - {2'b00, apipe[1]};
           apipe <= {apipe[0], aux_accept};
            hold <= 1'b0;

            // shadow register for the earlier event
           if (accept || aux_accept) ever_issued <= 1'b1;

            // scope closes the first time the unit reports saturation
            if (full)  armed <= 1'b0;
        end else if (accept) begin
            // stalled: park the admitted query and count it as in flight
            hold        <= 1'b1;
            occ         <= occ + 3'd1;
            ever_issued <= 1'b1;
        end
    end

    // Precedence, before the unit was ever full:
    // if work is in flight now, an issue must have happened earlier.
    always @(posedge clk)
        if (armed && occ != 3'd0)
            assert (ever_issued);

// Distractor telemetry: counts retirements, observed by nothing else.
always @(posedge clk) begin
   if (ce && retire) begin
        retire_seen <= 1'b1;
        retire_cnt  <= retire_cnt + (retire_seen ? 4'd2 : 4'd1);
    end
end

endmodule

module fsm_phase_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_start,
    output wire [4:0] o_phase,
    output wire       o_busy
);
    // binary-encoded FSM: only 0..4 are legal encodings, 5..7 are unreachable
    localparam [2:0] S_IDLE   = 3'd0,
                     S_FETCH  = 3'd1,
                     S_DECODE = 3'd2,
                     S_EXEC   = 3'd3,
                     S_WRITE  = 3'd4;

    reg [2:0] state;
    reg [4:0] dec;   // shadow one-hot decode of state
   reg [4:0] dec_s; // decode stage register, one pipeline step ahead of dec
    reg       win;   // window register: opened by a job start, closed at retire
   reg       tail;  // retire stage: carries the window over the write-back phase

    initial state = S_IDLE;
    initial dec   = 5'b00001;
   initial dec_s = 5'b00001;
    initial win   = 1'b0;
   initial tail  = 1'b0;

    reg [2:0] nstate;
    always @(*) begin
        case (state)
            S_IDLE:   nstate = i_start ? S_FETCH : S_IDLE;
            S_FETCH:  nstate = S_DECODE;
            S_DECODE: nstate = S_EXEC;
            S_EXEC:   nstate = S_WRITE;
            S_WRITE:  nstate = S_IDLE;
            default:  nstate = 3'd5;   // illegal-encoding trap, never taken
        endcase
    end

    // one-hot decode of the next state; illegal encodings decode to all-zero
    wire [4:0] ndec = (nstate == S_IDLE)   ? 5'b00001 :
                      (nstate == S_FETCH)  ? 5'b00010 :
                      (nstate == S_DECODE) ? 5'b00100 :
                      (nstate == S_EXEC)   ? 5'b01000 :
                      (nstate == S_WRITE)  ? 5'b10000 : 5'b00000;

    always @(posedge i_clk) begin
        if (i_rst) begin
            state <= S_IDLE;
            dec   <= 5'b00001;
           dec_s <= 5'b00001;
            win   <= 1'b0;
           tail  <= 1'b0;
        end else if (i_ce) begin
            state <= nstate;
           dec_s <= ndec;      // decode is registered here ...
           dec   <= dec_s;     // ... and presented on o_phase one cycle later
            if ((state == S_IDLE) && i_start)
                win <= 1'b1;               // Q: a job is launched
           else if (tail)             // the retire stage owns the window now
                win <= 1'b0;               // R: the job retires

           // hand the window over once DECODE reaches o_phase, so the retire
           // stage covers the final write-back cycle on its own
           if (dec == 5'b00100)
               tail <= 1'b1;
           else if (dec == 5'b10000)
               tail <= 1'b0;
        end
    end

    assign o_phase = dec;
   assign o_busy  = win | tail;   // busy spans the lead half and the retire tail

    // P: inside the job window the phase decode always names some phase
    always @(posedge i_clk)
        assert (!win || (|dec));

   // P2: a busy job showing phase 0 on o_phase is the launch cycle, so the
   // decode stage must already be carrying the FETCH phase behind it
   always @(posedge i_clk)
       assert (!win || (dec != 5'b00001) || (dec_s == 5'b00010));
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
    output wire [2:0] o_inflight
);
// fixed-latency (6 cycle) pipeline occupancy shift register
reg [5:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;
// remaining issue credits: an op is only taken while credits are left
reg [2:0] cred;
// currently programmed outstanding-op limit, retuned at each quiesce point
reg [2:0] lim;
// congestion flag: enable dropped while work was still in flight
reg       thr;
// credit-return path: a retired op's credit takes four more cycles to walk
// back from the pipe tail to the issue-side credit counter
reg       rq0;
reg       rq1;
reg       rq2;
reg       rq3;
// returned credits wait here until the credit counter's write port is free
reg [2:0] rtn;

initial pipe     = 6'b000000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;
initial cred     = 3'd4;
initial lim      = 3'd4;
initial thr      = 1'b0;
initial rq0      = 1'b0;
initial rq1      = 1'b0;
initial rq2      = 1'b0;
initial rq3      = 1'b0;
initial rtn      = 3'd0;

wire retire  = pipe[5];
// credit gate on the issue path
wire accept  = issue && (cred != 3'd0);
// nothing still travelling back down the credit-return path
wire rq_empty = !(rq0 || rq1 || rq2 || rq3);
// at most one parked credit is merged back per cycle, and only on cycles
// where the issue side is not already updating the credit counter
wire drain = (rtn != 3'd0) && !accept;
// true quiesce: pipe drained, returns landed, nothing arriving this cycle
wire quiesce = (pipe == 6'b000000) && rq_empty && !issue;

    always @(posedge clk) begin
        if (rst) begin
pipe     <= 6'b000000;
            inflight <= 3'd0;
        end else if (i_ce) begin
pipe     <= {pipe[4:0], accept};
inflight <= inflight + {2'b00, accept} - {2'b00, retire};
        end
    end
// credit accounting and outstanding-limit retuning
always @(posedge clk) begin
    if (rst) begin
        cred <= 3'd4;
        lim  <= 3'd4;
        thr  <= 1'b0;
        rtn  <= 3'd0;
    end else if (i_ce) begin
        if (quiesce) begin
            lim  <= thr ? 3'd2 : 3'd4;
            cred <= thr ? 3'd2 : 3'd4;
            thr  <= 1'b0;
            rtn  <= 3'd0;
        end else begin
            cred <= cred - {2'b00, accept} + {2'b00, drain};
            rtn  <= rtn + {2'b00, rq3} - {2'b00, drain};
        end
    end else if (pipe != 6'b000000) begin
        thr  <= 1'b1;
    end
end

// credit-return path: retire pulses shift back toward the issue side
always @(posedge clk) begin
    if (rst) begin
        rq0 <= 1'b0;
        rq1 <= 1'b0;
        rq2 <= 1'b0;
        rq3 <= 1'b0;
    end else if (i_ce) begin
        rq0 <= retire;
        rq1 <= rq0;
        rq2 <= rq1;
        rq3 <= rq2;
    end
end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module uart_rx_onehot (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // baud tick / enable: low freezes all state
    input  wire       rx,
    input  wire       take,    // consumer accepts the byte parked in STOP
    output wire [7:0] o_data,
    output wire       o_ferr,
    output wire       o_busy
);
    // one-hot phase FSM:
    //   st[0]      IDLE
    //   st[1]      START bit
    //   st[2..9]   data bits D0..D7 (one state per bit)
    //   st[10]     STOP bit / byte parked
    reg [10:0] st;
    reg [3:0]  nbits;   // frame phase index: 0..10 only, though 4 bits hold 15
   reg [3:0]  dcnt;    // data bits already shifted into sr this frame: 0..8
    reg [7:0]  sr;
    reg        ferr;
    reg        pv;
   reg [3:0]  n_acq;   // ledger: frames acquired off the line (start bit seen)
   reg [3:0]  n_rel;   // ledger: frames released to the consumer (take at STOP)
   reg        active;  // a frame is in flight according to the ledger
  reg        owner;   // baud-tick arbiter: 1 = the idle timer owns this tick
  reg [3:0]  icnt;    // idle ticks seen by the line-idle timer: 0..11

    initial st    = 11'b000_0000_0001;
    initial nbits = 4'd0;
   initial dcnt  = 4'd0;
    initial sr    = 8'h00;
    initial ferr  = 1'b0;
    initial pv    = 1'b0;
   initial n_acq  = 4'd0;
   initial n_rel  = 4'd0;
   initial active = 1'b0;
  initial owner = 1'b0;
  initial icnt  = 4'd0;

    wire idle   = st[0];
    wire startb = st[1];
    wire datab  = |st[9:2];
    wire stopb  = st[10];

    wire start_det = ce && idle   && !rx;   // falling edge of the line
   wire adv       = ce && active && !owner && (startb || datab); // count only the ticks this engine owns
    wire done      = ce && stopb  && take;
   wire in_flight = start_det || (active && !done); // frame engine's claim on the next tick
   wire quiet     = owner && (icnt == 4'd11);       // line idle for a whole frame time

    // next-state decode: every source bit drives exactly one destination bit
    reg [10:0] nxt;
    always @(*) begin
        nxt      = 11'd0;
        nxt[0]   = (st[0] && rx) || (st[10] && take);
        nxt[1]   = st[0] && !rx;
        nxt[2]   = st[1];
        nxt[3]   = st[2];
        nxt[4]   = st[3];
        nxt[5]   = st[4];
        nxt[6]   = st[5];
        nxt[7]   = st[6];
        nxt[8]   = st[7];
        nxt[9]   = st[8];
        nxt[10]  = st[9] || (st[10] && !take);
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            st    <= 11'b000_0000_0001;
            nbits <= 4'd0;
           dcnt  <= 4'd0;
            sr    <= 8'h00;
            ferr  <= 1'b0;
           n_acq  <= 4'd0;
           n_rel  <= 4'd0;
           active <= 1'b0;
           owner <= 1'b0;
           icnt  <= 4'd0;
        end else if (ce) begin
            st <= nxt;
            if (start_det)     nbits <= 4'd1;   // load: start bit is phase 1
            else if (done)     nbits <= 4'd0;
            else if (adv)      nbits <= nbits + 4'd1;
            if (datab)         sr    <= {rx, sr[7:1]};
           if (start_det || done) dcnt <= 4'd0;
           else if (datab)        dcnt <= dcnt + 4'd1;
           if (done)          ferr  <= !rx || (dcnt != 4'd8); // stop bit high and a full byte
          else if (quiet)    ferr  <= 1'b0;                  // stale error retired once the line goes quiet
           // frame ledger: one acquire per start bit, one release per handoff
           if (start_det)     n_acq  <= n_acq + 4'd1;
           if (done)          n_rel  <= n_rel + 4'd1;
           if (start_det)     active <= 1'b1;
           else if (done)     active <= 1'b0;
          // tick arbiter: every tick the frame engine will not use goes to the idle timer
          owner <= !in_flight;
          if (!owner)             icnt <= 4'd0;
          else if (icnt != 4'd11) icnt <= icnt + 4'd1;
        end
    end

   // with no byte parked, the data bus reads back the ledger for diagnostics
   assign o_data = stopb ? sr : {n_acq, n_rel};
    assign o_ferr = ferr;
   assign o_busy = !idle || active;

    // P: the phase counter changes on every phase change, and it never counts
    // past the 10 phases of a frame -- stated as a no-change check.
    always @(posedge clk)
        if (pv && $stable(nbits))
            assert ($stable(st) && nbits <= 4'd10);

   // P2: dcnt lags the phase index by the START phase plus the one-cycle
   // capture lag, so inside a frame it is always nbits-2 bits deep.
   always @(posedge clk)
       if (pv && o_busy && nbits >= 4'd2)
           assert (dcnt == nbits - 4'd2);
endmodule

// Gray-coded write pointer crossing into a destination domain through a
// two-flop synchronizer, with a shadow binary pipeline kept alongside the
// synchronizer stages and a monitor that records the Hamming distance between
// the two most recent samples of the pointer.
module gray_cdc_skew_monitor (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable / idle
    input  wire       i_incr,    // source pointer advance
    output reg        armed,     // sticky: a pointer change has been observed
    output reg  [2:0] last_delta // bits differing between the last two samples
);

    // source-domain binary pointer and its gray encoding
    reg  [3:0] wbin;
    wire [3:0] wgray = wbin ^ (wbin >> 1);

    // two-flop synchronizer carrying the gray pointer
    reg  [3:0] sync1, sync2;

   // second consumer's synchronizer chain onto the same gray pointer
   reg  [3:0] s1b, s2b;

    // shadow binary pipeline, one stage per synchronizer flop
    reg  [3:0] b1, b2;
   reg  [3:0] b1b, b2b;

   // round-robin refresh phase: 0 refreshes chain A, 1 refreshes chain B.
// Advances are no longer pinned to a phase: the issue/retire ledger below
// keeps at most one advance outstanding, which is what bounds either chain
// to a single gray transition between two of its own samples.
   reg        phase;
  // Programmable pointer depth.  The wrap modulus is carried as a mask that
  // is always one less than a power of two; it is widened one bit at a time
  // by i_incr pulses while the destination domain is parked (i_ce low).
  // Moving the wrap point invalidates everything already in flight, so a
  // depth change also drains the pointer and both synchronizer shadows.
  reg  [3:0] wrap_mask;

 // Issue/retire ledger for pointer advances.  n_issue logs advances pushed
 // into the source pointer, n_retire logs advances absorbed by the chain-A
 // shadow stage.  Both are plain free-running event counters that wrap at
 // four bits; only their difference is meaningful.
 reg  [3:0] n_issue;
 reg  [3:0] n_retire;

    initial begin
        wbin       = 4'd0;
        sync1      = 4'd0;
        sync2      = 4'd0;
        b1         = 4'd0;
        b2         = 4'd0;
       s1b        = 4'd0;
       s2b        = 4'd0;
       b1b        = 4'd0;
       b2b        = 4'd0;
       phase      = 1'b0;
      wrap_mask  = 4'd1;
     n_issue    = 4'd0;
     n_retire   = 4'd0;
        armed      = 1'b0;
        last_delta = 3'd0;
    end

    // combinational Hamming distance between the two synchronizer stages
    wire [3:0] xr = sync1 ^ sync2;
    wire [2:0] delta = {2'b00, xr[0]} + {2'b00, xr[1]} +
                       {2'b00, xr[2]} + {2'b00, xr[3]};

   // the same distance measure for the second chain
   wire [3:0] xrb = s1b ^ s2b;
   wire [2:0] delta_b = {2'b00, xrb[0]} + {2'b00, xrb[1]} +
                        {2'b00, xrb[2]} + {2'b00, xrb[3]};

   // one skew monitor is shared by both chains; it reports whichever chain
   // was refreshed on this phase
   wire [2:0] delta_mux = phase ? delta_b : delta;
   wire       skew_mux  = phase ? (s1b != s2b) : (sync1 != sync2);
  // depth reconfiguration is only accepted while the destination domain is
  // idle, and only up to the full four-bit pointer range
  wire       cfg_widen = !i_ce && i_incr && (wrap_mask != 4'd15);
 // credit-style interlock: a fresh advance is only issued once the previous
 // one has been retired by the shadow stage
 wire       ledger_busy = (n_issue != n_retire);
 wire       ptr_adv     = i_ce && i_incr && !ledger_busy;
 wire       shadow_adv  = i_ce && !phase && (b1 != wbin);

    always @(posedge clk) begin
       if (cfg_widen) begin
           // new wrap point: grow the mask and drain the pointer pipeline
           wrap_mask <= (wrap_mask << 1) | 4'd1;
           wbin      <= 4'd0;
           sync1     <= 4'd0;
           sync2     <= 4'd0;
           b1        <= 4'd0;
           b2        <= 4'd0;
           s1b       <= 4'd0;
           s2b       <= 4'd0;
           b1b       <= 4'd0;
           b2b       <= 4'd0;
          n_issue   <= 4'd0;
          n_retire  <= 4'd0;
       end else if (i_ce) begin
            // source pointer
         wbin  <= (wbin + (ptr_adv ? 4'd1 : 4'd0)) & wrap_mask;

           // ledger: log both sides of the advance
         n_issue  <= n_issue  + (ptr_adv    ? 4'd1 : 4'd0);
         n_retire <= n_retire + (shadow_adv ? 4'd1 : 4'd0);

            // synchronizer chain
           if (!phase) begin
               sync1 <= wgray;
               sync2 <= sync1;
           end else begin
               s1b   <= wgray;
               s2b   <= s1b;
           end

            // shadow binary chain, structurally parallel to the chain above
           if (!phase) begin
               b1    <= wbin;
               b2    <= b1;
           end else begin
               b1b   <= wbin;
               b2b   <= b1b;
           end

            // monitor
           last_delta <= delta_mux;
           phase      <= ~phase;

            // Q: first time the two stages disagree, i.e. a pointer update is
            // in flight through the synchronizer.  Sticky, never cleared.
          if (skew_mux || ledger_busy)
                armed <= 1'b1;
        end
    end

    // P: once a pointer change has been seen, every recorded sample-to-sample
    // distance is at most one bit (gray-code single-bit transition).
    assert property (!armed || last_delta <= 3'd1);

endmodule

module gray_deadline_tracker (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       req,       // request pulse
    output wire [3:0] o_gray,
    output wire [3:0] o_bin,
    output wire [3:0] o_timer,
    output wire       o_busy,
    output wire       o_on_time
);
    // ---- gray counter with its binary shadow -------------------------
    reg [3:0] bin;
    reg [3:0] gray;

   // The binary->gray conversion is pipelined: the encoder runs one
// increment ahead of the visible counter; behind it a four-deep
// prefetch chain holds the next four encodings, so the adder and the
// XOR network run six counts ahead and every register in the chain --
// including the output register -- is fed straight out of a register.
reg [2:0] gray_pre;     // in-flight gray code for bin+1, low bits
// Bit 3 of a gray code is just bit 3 of the binary count, so the top
// bit skips the XOR network entirely and lives in its own register.
// It is only reloaded on the two counts where it can change, which
// keeps it from toggling with the rest of the pipeline.
reg       gray_pre_top;
// prefetch chain: pre-encoded gray codes waiting to be shifted into
// the stage-1 registers, oldest (nearest the output) first.
reg [3:0] gray_pre2;    // gray code queued for bin+2
reg [3:0] gray_pre3;    // gray code queued for bin+3
reg [3:0] gray_pre4;    // gray code queued for bin+4
reg [3:0] gray_pre5;    // gray code queued for bin+5

    // ---- bounded-response deadline machinery -------------------------
    reg [3:0] timer;      // countdown for the outstanding request
    reg       busy;       // request outstanding
    reg [3:0] goal_gray;  // gray code the counter should show at completion
    reg       armed;      // sticky: set the first time a request is seen

    reg       pv;         // past valid

    localparam [3:0] K = 4'd8;   // response bound

    initial begin
        bin       = 4'd0;
        gray      = 4'd0;
gray_pre     = 3'd1;   // encoder prefilled with gray(bin+1)[2:0]
gray_pre_top = 1'b0;   // ... and its top bit
gray_pre2    = 4'd3;   // prefetch chain prefilled with gray(bin+2..5)
gray_pre3    = 4'd2;
gray_pre4    = 4'd6;
gray_pre5    = 4'd7;
        timer     = 4'd0;
        busy      = 1'b0;
        goal_gray = 4'd0;
        armed     = 1'b0;
        pv        = 1'b0;
    end

    wire [3:0] bin_nxt  = bin + 4'd1;
   wire [3:0] bin_ahead  = bin_nxt + 4'd1;
// deepest lookahead: the count whose encoding enters the chain now
wire [3:0] bin_la     = bin + 4'd6;
wire [3:0] gray_la    = bin_la ^ (bin_la >> 1);
// the held top bit only needs a new value as the count rolls into 8 or 0
wire       top_load  = (bin_ahead[2:0] == 3'd0);

    wire [3:0] goal_bin = bin + K;

    wire accept = i_ce && armed && req && !busy;
    wire tick   = i_ce && busy;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            // gray counter advances together with its binary shadow
            bin  <= bin_nxt;
gray_pre  <= gray_pre2[2:0];
if (top_load) gray_pre_top <= gray_pre2[3];
gray     <= {gray_pre_top, gray_pre};
// the prefetch chain shifts one encoding per count
gray_pre2 <= gray_pre3;
gray_pre3 <= gray_pre4;
gray_pre4 <= gray_pre5;
gray_pre5 <= gray_la;

            // sticky arm: first request ever seen arms the monitor forever
            if (req) armed <= 1'b1;

            if (accept) begin
                busy      <= 1'b1;
                timer     <= K;
                goal_gray <= goal_bin ^ (goal_bin >> 1);
            end else if (busy) begin
                if (timer == 4'd1) begin
                    // completion lands exactly on the deadline tick
                    busy  <= 1'b0;
                    timer <= 4'd0;
                end else begin
                    timer <= timer - 4'd1;
                end
            end
        end
    end

    assign o_gray    = gray;
    assign o_bin     = bin;
    assign o_timer   = timer;
    assign o_busy    = busy;
    assign o_on_time = busy && (gray == goal_gray);

    // P: after the monitor is armed, while a request is outstanding the
    // deadline countdown may only move when the gray counter moves --
    // it can never silently run down toward expiry.
    always @(posedge clk)
        if (pv && armed && busy && $stable(gray))
            assert ($stable(timer));
endmodule

module wdt_absence (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       arm,       // Q: opens the window
    input  wire       disarm,    // R: closes the window (may never arrive)
    input  wire       kick,      // pet the watchdog
    output reg  [3:0] cnt,
    output reg        expired,
    output reg        safe,
output reg        armed,
output reg [3:0] kick_cnt,
output reg [3:0] disarm_cnt
);
    localparam [3:0] LIMIT = 4'd10;  // timeout value
    localparam [3:0] WARN  = 4'd8;   // below this the timer is in the safe zone
    localparam [1:0] GRACE = LIMIT - WARN;  // warning-zone dwell before timeout
    reg [1:0] grace;                        // ticks elapsed since cnt hit WARN
reg [3:0] evt_shift;

    initial cnt     = 4'd0;
    initial expired = 1'b0;
    initial safe    = 1'b1;
    initial armed   = 1'b0;
    initial grace   = 2'd0;
initial kick_cnt = 4'd0;
initial disarm_cnt = 4'd0;
initial evt_shift = 4'd0;

    always @(posedge clk) begin
        if (i_ce) begin
// bookkeeping only: how many kicks have been seen
if (kick)
kick_cnt <= kick_cnt + 4'd1;
evt_shift <= {evt_shift[2:0], disarm};
if (disarm && !arm)
disarm_cnt <= disarm_cnt + 4'd1 + {3'd0, evt_shift[3]};
            // window register: set by arm, cleared by disarm
            if (arm)
                armed <= 1'b1;
            else if (disarm)
                armed <= 1'b0;

            // the watchdog only runs inside the window
            if (armed) begin
                if (kick) begin
                    cnt     <= 4'd0;
                    grace   <= 2'd0;
                    expired <= 1'b0;
                    safe    <= 1'b1;
                end else if (cnt < WARN) begin
                    // pre-warning part of the interval is held in cnt
                    cnt     <= cnt + 4'd1;
                    safe    <= ((cnt + 4'd1) < WARN);
                end else if (grace < GRACE) begin
                    // once cnt has reached WARN the remaining ticks before the
                    // timeout are accumulated here, so the warning-zone dwell
                    // can be reported on its own
                    grace   <= grace + 2'd1;
                    expired <= ((grace + 2'd1) == GRACE);
                    safe    <= 1'b0;
                end
            end
        end
    end

    // P: once armed (and until disarmed, if ever), the timer can never report
    // both "expired" and "safe" at the same time.
    always @(*)
        if (armed)
            assert (!(expired && safe));
endmodule

// Histogram accumulator: four bin counters, one sample at a time,
// plus a running total-samples register and a shadow register that
// records the bin-0 count observed at the most recent bin-1 sample.
module histo_precedence (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire [1:0] i_bin,     // which bin the incoming sample lands in
    output wire [5:0] o_total,
output wire [3:0] o_snap,
output reg  [3:0] o_act
);
    // bin counters
    reg [3:0] b0, b1, b2, b3;
    // total samples accumulated
    reg [5:0] total;
    // shadow register: value of bin 0 at the time of the last bin-1 sample
    reg [3:0] snap;
   // snapshot delivery pipeline: the bin-0 population read out alongside a
   // bin-1 sample only reaches the shadow register four cycles later, which
   // matches the read latency of the bin storage array.
   reg [3:0] sn1, sn2, sn3, sn4;
   reg       v1, v2, v3, v4;
reg [3:0] ce_hist;
// snapshot defer buffer: a bin-1 sample that arrives while the readout
// pipeline is still busy parks its bin-0 reading here and replays it when
// the pipeline frees up, so back-to-back bin-1 samples are not lost
reg [3:0] hold;
reg       hold_v;
// snapshot ledger: requests issued vs. snapshots delivered to the shadow
reg [3:0] n_iss, n_ret;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;
   initial sn1   = 4'd0;
   initial sn2   = 4'd0;
   initial sn3   = 4'd0;
   initial sn4   = 4'd0;
   initial v1    = 1'b0;
   initial v2    = 1'b0;
   initial v3    = 1'b0;
   initial v4    = 1'b0;
initial ce_hist = 4'd0;
initial o_act   = 4'd0;
initial hold    = 4'd0;
initial hold_v  = 1'b0;
initial n_iss   = 4'd0;
initial n_ret   = 4'd0;

    // value currently held by the selected bin
    wire [3:0] sel_val = (i_bin == 2'd0) ? b0 :
                         (i_bin == 2'd1) ? b1 :
                         (i_bin == 2'd2) ? b2 : b3;

    // a sample is committed only if the selected bin has headroom
wire [3:0] inflight  = n_iss - n_ret;
wire       pipe_free = !(v1 | v2 | v3 | v4);
// the ledger can carry two outstanding snapshots (one in the readout
// pipeline, one in the defer buffer); a bin-1 sample that would overflow it
// is held off at the input until a slot frees up
wire       snap_full = (inflight == 4'd2);
wire incr = i_ce && (sel_val != 4'd15) && !((i_bin == 2'd1) && snap_full);
wire req  = incr && (i_bin == 2'd1);

    always @(posedge clk) begin
        if (incr) begin
            case (i_bin)
                2'd0: b0 <= b0 + 4'd1;
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
            endcase
            total <= total + 6'd1;
        end
    end
   // Snapshot pipeline: the read data shifts on every enabled cycle and the
   // valid bit travels with it, so the shadow register is loaded four cycles
   // after the bin-1 sample that requested the snapshot.
   always @(posedge clk) begin
       if (i_ce) begin
           sn2 <= sn1;
           v2  <= v1;
           sn3 <= sn2;
           v3  <= v2;
           sn4 <= sn3;
           v4  <= v3;
           if (v4)
               snap <= sn4;
          // stage-1 arbitration: a parked request replays ahead of a new
          // one so the shadow register sees bin-1 samples in order
          if (pipe_free && hold_v) begin
              sn1    <= hold;
              v1     <= 1'b1;
              hold_v <= req;
              if (req)
                  hold <= b0;
          end else if (pipe_free && req) begin
              sn1 <= b0;
              v1  <= 1'b1;
          end else begin
              v1 <= 1'b0;
              if (req) begin
                  hold   <= b0;
                  hold_v <= 1'b1;
              end
          end
          // ledger: one tick per request issued, one per snapshot delivered
          n_iss <= n_iss + {3'd0, req};
          n_ret <= n_ret + {3'd0, v4};
       end
   end

  // Activity monitor: a shift register of "sample landed in bin 3" flags,
// plus a status readout multiplexer: the current bin index selects which
// ledger / defer-buffer register is presented on o_act.
  always @(posedge clk) begin
      if (i_ce) begin
          ce_hist <= {ce_hist[2:0], (i_bin == 2'd3)};
          case (i_bin)
              2'd0: o_act <= n_iss;
              2'd1: o_act <= n_ret;
              2'd2: o_act <= hold;
              2'd3: o_act <= {hold_v, ce_hist[2:0]};
          endcase
      end
  end

    assign o_total = total;
    assign o_snap  = snap;

    // Property (precedence): whenever a sample is being committed, the
    // bin-0 population recorded earlier in the shadow register must already
    // have been accounted for in the total-samples register.
    always @(posedge clk)
        if (incr)
            assert (total >= {2'b00, snap});
endmodule

module sb_window (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_issue,
    input  wire i_retire,
    input  wire i_open,
    input  wire i_close,
    output wire o_full,
    output wire o_empty,
output wire o_mon,
output reg [3:0] o_act
);
    localparam [3:0] WINDOW = 4'd8;

    // transaction scoreboard: issued count, retired count, and a redundant
    // outstanding-transaction register maintained in parallel
    reg [4:0] iss;
    reg [4:0] ret;
   // retires are committed to `ret` in groups of four; `ret_p` holds the
   // retires of the group that has not been folded in yet
   reg [1:0] ret_p;
    reg [3:0] out_r;

    // registered status flags (one cycle stale, updated only when enabled)
    reg       full_q;
    reg       empty_q;

   // the issue count feeds the status comparator through four retiming
   // registers; the raw counter is too far from the compare logic to make
   // timing in one cycle, so the compare now sees a 4-cycle-old copy
   reg [4:0] iss_d1;
   reg [4:0] iss_d2;
   reg [4:0] iss_d3;
   reg [4:0] iss_d4;

    // monitoring window: opened by i_open, closed by i_close
    reg       mon;

    reg       pv;

    initial iss     = 5'd0;
    initial ret     = 5'd0;
   initial ret_p   = 2'd0;
    initial out_r   = 4'd0;
    initial full_q  = 1'b0;
    initial empty_q = 1'b1;
   initial iss_d1  = 5'd0;
   initial iss_d2  = 5'd0;
   initial iss_d3  = 5'd0;
   initial iss_d4  = 5'd0;
    initial mon     = 1'b0;
    initial pv      = 1'b0;
initial o_act   = 4'd0;

    wire acc_iss = i_ce && i_issue  && (out_r <  WINDOW);
    wire acc_ret = i_ce && i_retire && (out_r != 4'd0);
   // closing the monitoring window forces a partial group to commit so the
   // retire count is exact at the window boundary
   wire ret_flush = i_ce && i_close;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            iss   <= 5'd0;
            ret   <= 5'd0;
           ret_p <= 2'd0;
            out_r <= 4'd0;
o_act <= 4'd0;
        end else begin
            if (acc_iss) iss <= iss + 5'd1;
           if (ret_flush) begin
               ret   <= ret + {3'b0, ret_p} + (acc_ret ? 5'd1 : 5'd0);
               ret_p <= 2'd0;
           end else if (acc_ret) begin
               if (ret_p == 2'd3) begin
                   ret   <= ret + 5'd4;
                   ret_p <= 2'd0;
               end else begin
                   ret_p <= ret_p + 2'd1;
               end
           end
            if (acc_iss && !acc_ret)
                out_r <= out_r + 4'd1;
            else if (!acc_iss && acc_ret)
                out_r <= out_r - 4'd1;
if (i_ce && (i_open || i_close))
    o_act <= o_act + 4'd1;
        end

    always @(posedge clk)
        if (i_rst) begin
            full_q  <= 1'b0;
            empty_q <= 1'b1;
           iss_d1  <= 5'd0;
           iss_d2  <= 5'd0;
           iss_d3  <= 5'd0;
           iss_d4  <= 5'd0;
        end else if (i_ce) begin
            full_q  <= (out_r == WINDOW);
           empty_q <= (iss_d4 == ret);
           iss_d1  <= iss;
           iss_d2  <= iss_d1;
           iss_d3  <= iss_d2;
           iss_d4  <= iss_d3;
        end

    always @(posedge clk)
        if (i_rst)
            mon <= 1'b0;
        else if (i_ce) begin
            if (i_close)
                mon <= 1'b0;
            else if (i_open)
                mon <= 1'b1;
        end

    assign o_full  = full_q;
    assign o_empty = empty_q;
    assign o_mon   = mon;

    // P: inside an open monitoring window, when the full flag rises the
    // scoreboard must not simultaneously report empty
    always @(posedge clk)
        if (pv && mon && $rose(full_q))
            assert (!empty_q);
endmodule

// Tracks outstanding memory requests issued into a 4-deep load/store pipeline.
// A shift register records which pipeline stages hold a live request; a separate
// counter tracks how many are in flight.
module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,   // pipeline advance / clock-enable
    input  wire       req,    // a new request is issued into stage 0
    output wire       f_idle, // no requests outstanding (from the counter)
    output wire       f_full, // all pipeline slots occupied (from the counter)
    output wire       f_any,  // some stage holds a request (from the shifter)
    output wire       f_slot  // some stage is free (from the shifter)
);

    reg [3:0] inflight;
    reg [2:0] cnt;
reg       issue;                // request launch register (input -> stage 0)
reg [1:0] bcnt;                 // back-half occupancy (stage 3 only)
reg       hand;                 // request in the stage1 -> stage2 handover

    initial inflight = 4'b0000;
    initial cnt      = 3'd0;
initial issue    = 1'b0;
initial bcnt     = 2'd0;
initial hand     = 1'b0;

    // the request leaving the last stage completes this cycle
    wire retire = inflight[3];

    always @(posedge clk) begin
        if (rst) begin
            inflight <= 4'b0000;
            cnt      <= 3'd0;
issue    <= 1'b0;
bcnt     <= 2'd0;
hand     <= 1'b0;
        end else if (step) begin
// the request bus is registered at the pipeline input to cut the
// fan-in on stage 0: an accepted request waits one advance in the
// launch register before it occupies stage 0.  The front count is
// taken on acceptance, so it already covers that waiting request.
issue    <= req;
inflight <= {inflight[2:0], issue};
// each pipeline half maintains its own occupancy count locally.  The
// stage1 -> stage2 crossing is registered to keep the adder chains
// short: the front count drops the request on the advance that moves
// it out of stage 1, the handover latch carries it, and the back
// count picks it up on the following advance.
cnt      <= cnt  + {2'b00, req}           - {2'b00, inflight[1]};
bcnt     <= bcnt + {1'b0,  hand}          - {1'b0,  retire};
hand     <= inflight[1];
        end
    end

assign f_idle = (cnt == 3'd0) && (bcnt == 2'd0) && !hand;
// five holding places now: the launch register plus the four stages
assign f_full = ((cnt + {1'b0, bcnt} + {2'b00, hand}) == 3'd5);
    assign f_any  = |inflight;
    assign f_slot = ~(&inflight);

    // P: the counter-derived flags and the shifter-derived flags may never
    // contradict each other -- idle together with an occupied stage, or
    // full together with a free stage.
    always @(posedge clk) assert (!(f_idle && f_any));
    always @(posedge clk) assert (!(f_full && f_slot));

endmodule

module disasm_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       kick,      // an instruction was successfully decoded
    output reg  [3:0] count,     // cycles since last kick
    output reg        expired,   // decoder hung: limit was reached
    output reg        healthy    // plenty of slack left
);
    localparam [3:0] LIMIT = 4'd10;   // timeout
    localparam [3:0] WARN  = 4'd8;    // slack threshold

   // saved context of the decode channel that is parked while the other
   // one owns the shared pipeline slot
   reg  [3:0] count_sh;
   reg        exp_sh;
  // second parked context: three decode channels rotate through the one
  // pipeline slot, so two of them are always parked at any time
  reg  [3:0] count_sh2;
  reg        exp_sh2;
 // remaining slack of the channel that currently owns the slot; the
 // timeout now fires on a zero-detect of this countdown instead of a
 // magnitude compare, and it is reloaded whenever the slot changes hands
 reg  [3:0] deadline;

    initial begin
        count   = 4'd0;
        expired = 1'b0;
        healthy = 1'b1;
       count_sh = 4'd0;
       exp_sh   = 1'b0;
      count_sh2 = 4'd0;
      exp_sh2   = 1'b0;
     deadline  = LIMIT;
    end

    // next value of the stall counter: kick clears it, otherwise it
    // counts up and saturates at the timeout limit
    wire [3:0] nxt = kick              ? 4'd0  :
                     (count == LIMIT)  ? LIMIT :
                                         count + 4'd1;

   // the slot is handed to the other channel when the active one makes
   // progress, and is preempted once the active one has clearly hung
   wire swap = kick || (count == LIMIT);

  // the channel holding the slot has just run out of slack
  wire hung = !kick && (deadline <= 4'd1);

    always @(posedge clk) begin
        if (rst) begin
            count   <= 4'd0;
           count_sh <= 4'd0;
           exp_sh   <= 1'b0;
           count_sh2 <= 4'd0;
           exp_sh2   <= 1'b0;
          deadline  <= LIMIT;
            expired <= 1'b0;
            healthy <= 1'b1;
        end else if (i_ce) begin
           if (swap) begin
               count    <= count_sh;         // resume the parked channel
              deadline <= LIMIT - count_sh; // slack left for the resumed channel
count_sh  <= count_sh2;        // rotate the parked queue forward
count_sh2 <= nxt;              // park the current stall count
exp_sh    <= exp_sh2;          // its hang flag rotates with it
exp_sh2   <= hung;             // remember if it hung
           end else begin
               count    <= nxt;
              deadline <= (deadline == 4'd0) ? 4'd0 : deadline - 4'd1;
           end
           // sticky per channel: a kick only clears the channel that
           // currently owns the slot
expired <= hung || exp_sh || exp_sh2;
healthy <= (nxt < WARN) && (count_sh < WARN) && (count_sh2 < WARN);
        end
    end

    // P: the timeout flag and the slack flag are never raised together
    always @(posedge clk)
        if (expired)
            assert (!healthy);
endmodule

// Packet-capture sensor credit window.
// TOTAL = 8 stream credits.  A burst send spends 3 credits (they become
// "outstanding" bytes in flight); the collector returns exactly one credit
// per enabled cycle while anything is outstanding.  A deadline register is
// reloaded on every accepted burst and counts down otherwise; it must never
// expire while credits are still outstanding.
module credit_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_send,    // producer requests a burst
output wire       o_busy,
output wire [3:0] o_nspend,  // ledger: credits handed to the link (wraps)
output wire [3:0] o_nret,    // ledger: credits taken back (wraps)
output wire       o_phase,   // which link slot the collector is in
output wire       o_rdy,     // collector has a return slot open
output wire [3:0] o_ngrant,  // ledger: return slots opened (wraps)
output wire [3:0] o_nuse     // ledger: return slots consumed (wraps)
);
    reg [3:0] avail;   // credits held by the sensor
    reg [3:0] outst;   // credits outstanding (in flight)
reg [3:0] stage;   // credits accepted for a burst but not yet on the link
    reg [3:0] timer;   // completion deadline countdown
    reg       armed;   // sticky: set the first time a burst is accepted
reg [3:0] n_spend;  // event ledger: credits spent on bursts
reg [3:0] n_ret;    // event ledger: credits returned by the collector
reg       phase;    // half-rate return link: credits only come back on return slots
reg       rdy;      // a return slot is open and not yet used
reg [3:0] n_grant;  // event ledger: return slots opened by the collector
reg [3:0] n_use;    // event ledger: return slots consumed by a credit

    initial avail = 4'd8;
    initial outst = 4'd0;
initial stage = 4'd0;
    initial timer = 4'd0;
    initial armed = 1'b0;
initial n_spend = 4'd0;
initial n_ret = 4'd0;
initial phase = 1'b0;
initial rdy = 1'b0;
initial n_grant = 4'd0;
initial n_use = 4'd0;

    wire send_ok = i_send && (avail >= 4'd3);
wire grant   = !phase && !rdy;                  // collector opens the next return slot
wire retire  = (outst != 4'd0) && phase && rdy;  // a credit comes back in an open slot
wire push    = !phase && (stage != 4'd0);        // staged credit takes the send slot

assign o_busy = (outst != 4'd0) || (stage != 4'd0);
assign o_nspend = n_spend;
assign o_nret   = n_ret;
assign o_phase  = phase;
assign o_rdy    = rdy;
assign o_ngrant = n_grant;
assign o_nuse   = n_use;

    always @(posedge clk) begin
        if (rst) begin
            avail <= 4'd8;
            outst <= 4'd0;
stage <= 4'd0;
            timer <= 4'd0;
            armed <= 1'b0;
n_spend <= 4'd0;
n_ret <= 4'd0;
phase <= 1'b0;
rdy <= 1'b0;
n_grant <= 4'd0;
n_use <= 4'd0;
        end else if (i_ce) begin
phase <= ~phase;             // link alternates send / return slots
if (send_ok) n_spend <= n_spend + 4'd3;
if (retire)  n_ret   <= n_ret   + 4'd1;
if (grant) begin
    rdy     <= 1'b1;         // slot opens during the send half-period
    n_grant <= n_grant + 4'd1;
end else if (retire) begin
    rdy   <= 1'b0;           // slot consumed by the returning credit
    n_use <= n_use + 4'd1;
end
            if (send_ok) begin
                // spend three credits, one may come back the same cycle
                avail <= avail - 4'd3 + (retire ? 4'd1 : 4'd0);
// one credit goes out on this slot, the other two wait in the stage buffer
outst <= outst + 4'd1 + (push ? 4'd1 : 4'd0) - (retire ? 4'd1 : 4'd0);
stage <= stage + 4'd2 - (push ? 4'd1 : 4'd0);
timer <= 4'd15;         // deadline: half-rate return of up to 8 credits
                armed <= 1'b1;          // sticky arm
            end else if (retire) begin
                avail <= avail + 4'd1;
                outst <= outst - 4'd1;
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end else begin
if (push) begin
    outst <= outst + 4'd1;
    stage <= stage - 4'd1;
end
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end
        end
    end

    // Bounded response (safety form), scoped after the first accepted burst:
    // the deadline never expires while credits are still outstanding.
    always @(*)
        assert (!armed || !((timer == 4'd0) && (outst != 4'd0)));
endmodule

// Credit-managed transfer engine: three credit pools, one per chain step.
// A credit is spent on ARM, handed on at START and returned by the consumer
// at FINISH.  Total credits in the system is fixed at TOTAL by construction.
module credit_chain (
    input  wire clk,
    input  wire i_ce,      // global enable: low => the engine idles
    input  wire i_arm,
    input  wire i_start,
    input  wire i_done,
    input  wire i_flush,
    output wire o_fin_seen,
output wire o_busy,
output reg [3:0] o_evt_cnt
);
    localparam [3:0] TOTAL = 4'd3;
   localparam [3:0] CR_MIN = 4'd1;

    // ---- credit counter: credits held + credits in each stage == TOTAL ----
    reg [3:0] free_cr;    // credits held by the producer
    reg [3:0] armed_cr;   // credits spent on ARM, awaiting START
    reg [3:0] busy_cr;    // credits outstanding at the consumer

   // ---- adaptive credit budget: the pool in circulation is trimmed when a
   //      flush has to tear down live traffic, and healed one credit at a
   //      time while the whole engine is quiescent ----
   reg [3:0] cr_lim;     // credits currently in circulation

    // ---- chain history (arm -> start -> finish) ----
    reg ever_arm;
    reg ever_start;
    reg ever_fin;

    // ---- peer chain B: second engine drawing on the same credit pool ----
    reg [3:0] armed_b;    // chain B credits spent on ARM, awaiting START
    reg [3:0] busy_b;     // chain B credits outstanding at its consumer

    // ---- before-flush scope register: starts high, cleared by first flush ----
    reg nf;

    // ---- command-port ownership: both chains share one command port; it is
    //      handed to the other chain once the current owner has drained ----
    reg sel;              // 0 => chain A is served, 1 => chain B
// ---- debug-only activity trace: counts presented command strobes ----
reg [3:0] evt_hist;

    initial begin
        armed_b    = 4'd0;
        busy_b     = 4'd0;
        sel        = 1'b0;
        free_cr    = TOTAL;
       cr_lim     = TOTAL;
        armed_cr   = 4'd0;
        busy_cr    = 4'd0;
        ever_arm   = 1'b0;
        ever_start = 1'b0;
        ever_fin   = 1'b0;
        nf         = 1'b1;
evt_hist   = 4'd0;
o_evt_cnt  = 4'd0;
    end

    wire do_flush = i_ce &&  i_flush;
    wire own_idle = sel ? ((armed_b  == 4'd0) && (busy_b  == 4'd0))
                        : ((armed_cr == 4'd0) && (busy_cr == 4'd0));
    wire do_swap  = i_ce && !i_flush && own_idle && !i_arm && !i_start && !i_done;

   wire all_idle  = (armed_cr == 4'd0) && (busy_cr == 4'd0) &&
                    (armed_b  == 4'd0) && (busy_b  == 4'd0);
   // a flush over live traffic means the consumers were overrun: shed a credit
   wire cr_shrink = do_flush && !all_idle && (cr_lim != CR_MIN);
   // quiet enabled cycles hand a shed credit back to the producer
   wire cr_grow   = i_ce && !i_flush && all_idle && (cr_lim != TOTAL) &&
                    !i_arm && !i_start && !i_done;

    // the port owner is the only chain that sees the command strobes
    wire do_arm   = i_ce && !i_flush && !sel && i_arm   && (free_cr  != 4'd0);
    wire do_start = i_ce && !i_flush && !sel && i_start && (armed_cr != 4'd0);
    wire do_fin   = i_ce && !i_flush && !sel && i_done  && (busy_cr  != 4'd0);

    wire do_arm_b   = i_ce && !i_flush && sel && i_arm   && (free_cr != 4'd0);
    wire do_start_b = i_ce && !i_flush && sel && i_start && (armed_b != 4'd0);
    wire do_fin_b   = i_ce && !i_flush && sel && i_done  && (busy_b  != 4'd0);

    always @(posedge clk) begin
        if (do_flush) begin
            // all credits are recalled to the producer; the chain record for
            // this session is dropped, the finish record is kept.
           free_cr    <= cr_shrink ? (cr_lim - 4'd1) : cr_lim;
           cr_lim     <= cr_shrink ? (cr_lim - 4'd1) : cr_lim;
            armed_cr   <= 4'd0;
            busy_cr    <= 4'd0;
            armed_b    <= 4'd0;
            busy_b     <= 4'd0;
            sel        <= 1'b0;
            ever_arm   <= 1'b0;
            ever_start <= 1'b0;
            nf         <= 1'b0;
evt_hist   <= 4'd0;
o_evt_cnt  <= 4'd0;
        end else if (i_ce) begin
           free_cr  <= free_cr  - do_arm - do_arm_b + do_fin + do_fin_b + cr_grow;
           if (cr_grow) cr_lim <= cr_lim + 4'd1;
            armed_cr <= armed_cr + do_arm   - do_start;
            busy_cr  <= busy_cr  + do_start - do_fin;
            armed_b  <= armed_b  + do_arm_b   - do_start_b;
            busy_b   <= busy_b   + do_start_b - do_fin_b;
            if (do_swap) sel <= ~sel;
            if (do_arm)   ever_arm   <= 1'b1;
            if (do_start) ever_start <= 1'b1;
            if (do_fin)   ever_fin   <= 1'b1;
evt_hist  <= {evt_hist[2:0], (i_arm | i_start | i_done)};
o_evt_cnt <= o_evt_cnt + {3'd0, (evt_hist[3] | i_arm | i_start | i_done)};
        end
    end

    assign o_fin_seen = ever_fin;
    assign o_busy     = (busy_cr != 4'd0) || (busy_b != 4'd0);

    // Chain precedence, in the before-flush scope: a FINISH can never have been
    // observed unless an ARM and a START were observed first.
    always @(*)
        if (nf)
            assert (!ever_fin || (ever_arm && ever_start));
endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    // upstream credit: number of empty slots, maintained incrementally so the
    // full indication does not have to decode the valid flags
    reg [1:0] free;
   // peak occupancy telemetry: high-water mark of the occupancy counter since
   // reset, sampled every cycle and read back on the data output while the
   // buffer is empty (the head slot carries no valid word then)
   reg [1:0] hwm;
    reg [7:0] d0, d1;

   // spill stage: a second two-entry buffer sitting behind the head buffer so
   // a burst is not backpressured while the head buffer is draining. words
   // leave the spill stage in arrival order and refill the head buffer.
   reg       vb0, vb1;
   reg [1:0] cntb;
   reg [7:0] b0, b1;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial free  = 2'd2;
   initial hwm   = 2'd0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
   initial vb0   = 1'b0;
   initial vb1   = 1'b0;
   initial cntb  = 2'd0;
   initial b0    = 8'h00;
   initial b1    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
   wire push_a  = push && !v1 && !vb0;      // straight in when there is no backlog
   wire push_b  = push && !vb1 && !push_a;  // otherwise the word spills
   wire refill  = vb0 && !v1;               // backlog moves up when a slot frees
   wire do_push = push_a || refill;         // head buffer write enable
    wire do_pop  = pop  &&  v0;
   wire [7:0] a_din  = push_a ? din : b0;
   // a single high-water comparator is shared by both stages: it watches
   // whichever stage the upstream is currently feeding
   wire [1:0] occ_in = vb0 ? cntb : count;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            free  <= 2'd2;
           hwm   <= 2'd0;
            d0    <= 8'h00;
            d1    <= 8'h00;
           vb0   <= 1'b0;
           vb1   <= 1'b0;
           cntb  <= 2'd0;
           b0    <= 8'h00;
           b1    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                   d0 <= a_din;
                    v0 <= 1'b1;
                end else begin
                   d1 <= a_din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
               d0 <= a_din;
            end

            count <= count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
            free  <= free  - (do_push ? 2'd1 : 2'd0) + (do_pop ? 2'd1 : 2'd0);

           // the spill stage preserves arrival order: it only takes a word
           // once the head buffer cannot, and it empties into the head first
           if (push_b && !refill) begin
               if (!vb0) begin
                   b0  <= din;
                   vb0 <= 1'b1;
               end else begin
                   b1  <= din;
                   vb1 <= 1'b1;
               end
           end else if (refill && !push_b) begin
               b0  <= b1;
               vb0 <= vb1;
               vb1 <= 1'b0;
           end else if (push_b && refill) begin
               b0 <= din;
           end
           cntb <= cntb + (push_b ? 2'd1 : 2'd0) - (refill ? 2'd1 : 2'd0);

           if (occ_in > hwm)
               hwm <= occ_in;
        end
    end

   assign dout    = v0 ? d0 : {6'b0, hwm};
    assign o_empty = !v0;
    assign o_full   = (free == 2'd0);
    assign o_count  = count;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);

    // ---- property: a push accepted last cycle must have gone into a buffer
    // ---- that both occupancy encodings called non-full
    always @(posedge clk)
        if (pv && $past(push) && !$past(v1))
            assert ($past(free) != 2'd0 && $past(count) != 2'd2);

   // ---- property: a cycle in which the upstream credit register reported no
   // ---- free slots must leave the peak occupancy telemetry pegged at two
   always @(posedge clk)
       if (pv && !$past(rst) && $past(free) == 2'd0)
           assert (hwm == 2'd2);
endmodule

module elastic_profile_buf (
    input wire       i_clk,
    input wire       i_rst,
    input wire       i_push,
    input wire       i_pop,
    input wire [7:0] i_data,
    output wire      o_valid,
    output wire      o_full,
    output wire [7:0] o_data,
output wire [2:0] o_count,
output reg [3:0] o_push_tally
);
    // Two-entry elastic buffer holding profiling samples.
    // Entry 0 is the head, entry 1 is the tail.  v0/v1 are the head/tail
    // occupancy flags; count is a separate occupancy register that is
    // maintained in parallel with the flags.
    reg       v0, v1;
    reg [7:0] d0, d1;
    reg [2:0] count;
   // Skid slot behind the tail.  o_full is raised as soon as the tail fills,
   // but one upstream beat may already be in flight, so it is absorbed here
   // and handed to the tail as soon as a pop frees it.
   reg       s_v;
   reg [7:0] s_d;
  // occupancy contributed by the skid slot, held apart from the core count
  reg [1:0] skid_occ;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;
   initial s_v   = 1'b0;
   initial s_d   = 8'h00;
  initial skid_occ = 2'd0;
initial o_push_tally = 4'd0;

    // "full" is decided purely by the tail flag
    wire w_full  = v1;
    wire do_push = i_push && !w_full;
    wire do_pop  = i_pop  && v0;
   // a beat arriving while full is taken by the skid slot, unless a pop is
   // freeing the tail this cycle, in which case it goes straight to the tail
   wire do_skid = i_push && w_full && !s_v && !do_pop;

    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
           s_v   <= 1'b0;
           s_d   <= 8'h00;
          skid_occ <= 2'd0;
o_push_tally <= 4'd0;
        end else if (do_push && do_pop) begin
            // head leaves, new sample becomes the head: occupancy unchanged
            d0    <= i_data;
        end else if (do_push) begin
            if (!v0) begin
                v0 <= 1'b1;
                d0 <= i_data;
            end else begin
                v1 <= 1'b1;
                d1 <= i_data;
            end
            count <= count + 3'd1;
        end else if (do_pop) begin
            // tail slides down into the head slot
           v0 <= v1;
           d0 <= d1;
           if (s_v) begin
               // the parked skid sample takes the freed tail slot
               v1    <= 1'b1;
               d1    <= s_d;
               s_v   <= 1'b0;
              // the head leaves and the parked beat joins the core, so its
              // occupancy share moves from the skid counter into count
              count    <= count - 3'd1 + {1'b0, skid_occ};
              skid_occ <= 2'd0;
           end else if (i_push) begin
               // we reported full, so this beat lands in the freed tail
               v1 <= 1'b1;
               d1 <= i_data;
           end else begin
               v1    <= 1'b0;
               count <= count - 3'd1;
           end
       end else if (do_skid) begin
           s_v   <= 1'b1;
           s_d   <= i_data;
          skid_occ <= skid_occ + 2'd1;
       end
        // i_push = i_pop = 0 : the buffer idles, all state held
if (!i_rst && do_push)
    o_push_tally <= o_push_tally + 4'd1;
    end

    assign o_valid = v0;
    assign o_full  = w_full;
    assign o_data  = d0;
   assign o_count = count + {1'b0, skid_occ};

    // P: whenever the buffer is not reporting full, the recorded occupancy
    // is at most one sample (the 3-bit register would allow up to 7).
    always @(posedge i_clk)
        if (!w_full)
            assert (count <= 3'd1);
endmodule

// PWM channel for a wire-logic accelerator block.
// Period counter walks 0..PER-1, duty is double buffered at the period edge,
// and high_cnt accumulates the number of high cycles elapsed in the period.
module pwm_channel (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire       i_load,
    input  wire [3:0] i_duty,
    output wire       pwm_out,
    output reg        armed
);
    localparam [3:0] PER = 4'd12;
   localparam [3:0] HALF = 4'd6;   // the period is walked as two half windows

   reg [3:0] cnt;       // sub-counter inside the current half, 0 .. HALF-1
   reg       half;      // 0 = first half of the period, 1 = second half
    reg [3:0] duty;      // active duty, 0 .. PER
    reg [3:0] high_cnt;  // high cycles elapsed so far this period
   reg       pwm_q;     // registered output stage, resolved one cycle ahead

    initial begin
        cnt      = 4'd0;
       half     = 1'b0;
        duty     = 4'd0;
        high_cnt = 4'd0;
        armed    = 1'b0;
       pwm_q    = 1'b0;
    end

    // the construct: output high exactly while the counter is below the duty
   assign pwm_out = pwm_q;

    wire [3:0] duty_clamped = (i_duty > PER) ? PER : i_duty;
   wire       at_half      = (cnt == HALF - 4'd1);
   wire       at_edge      = half && at_half;
   // full period phase reassembled from the two halves, 0 .. PER-1
   wire [3:0] phase        = half ? (cnt + HALF) : cnt;

   // Next-cycle counter and duty. The output register is loaded from these so
   // the pin keeps the same alignment the combinational comparator had, while
   // the compare itself is off the critical path.
  wire [3:0] cnt_nxt   = at_half ? 4'd0 : cnt + 4'd1;
  wire       half_nxt  = at_half ? ~half : half;
  wire [3:0] phase_nxt = at_edge ? 4'd0 : phase + 4'd1;
   wire [3:0] duty_nxt = (at_edge && i_load) ? duty_clamped : duty;

    always @(posedge clk) begin
        if (rst) begin
            cnt      <= 4'd0;
           half     <= 1'b0;
            duty     <= 4'd0;
            high_cnt <= 4'd0;
            armed    <= 1'b0;
           pwm_q    <= 1'b0;
        end else if (i_ce) begin
          pwm_q <= (phase_nxt < duty_nxt);
            if (at_edge) begin
                // period rolls over: new duty takes effect, accumulator clears
                cnt      <= 4'd0;
               half     <= 1'b0;
                high_cnt <= 4'd0;
                armed    <= 1'b1;            // sticky, never cleared
                if (i_load)
                    duty <= duty_clamped;
            end else begin
               cnt      <= cnt_nxt;
               half     <= half_nxt;
                high_cnt <= high_cnt + (pwm_out ? 4'd1 : 4'd0);
            end
        end
    end

    // Property (universality, after the first completed period):
    // the accumulated high time never exceeds the duty, and the live output
    // agrees with the accumulator's headroom.
    always @(posedge clk)
        if (armed)
            assert (high_cnt <= duty);

    always @(posedge clk)
        if (armed)
            assert (pwm_out == (high_cnt < duty));
endmodule

module dma_burst_dimmer (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // beat enable / idle when low
    input  wire       i_start,
    input  wire [3:0] i_beats,
    input  wire [3:0] i_duty,
    output wire       o_busy,
    output wire       o_beat,
    output wire       o_pwm
);

    // ---- DMA burst engine state ----
    reg [3:0] beats_left;   // beats remaining in the burst
    reg [3:0] done_cnt;     // beats already pushed out
    reg [3:0] total;        // beats requested by the accepted burst
    reg [3:0] duty;         // dimming level latched with the burst
    reg       busy;         // up exactly while beats remain
    reg [3:0] queued;       // beats accepted but not yet issued into the current chunk
   reg [3:0] chunk_pend;   // chunk staged for issue on the next beat

    initial beats_left = 4'd0;
    initial done_cnt   = 4'd0;
    initial total      = 4'd0;
    initial duty       = 4'd0;
    initial busy       = 1'b0;
    initial queued     = 4'd0;
   initial chunk_pend = 4'd0;

    // the fabric only accepts short chunks, so a long burst is issued piecewise
    localparam [3:0] CHUNK_MAX = 4'd4;
    wire [3:0] first_chunk = (i_beats > CHUNK_MAX) ? CHUNK_MAX : i_beats;
    wire [3:0] next_chunk  = (queued  > CHUNK_MAX) ? CHUNK_MAX : queued;

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            done_cnt   <= 4'd0;
            total      <= 4'd0;
            duty       <= 4'd0;
            queued     <= 4'd0;
           chunk_pend <= 4'd0;
            busy       <= 1'b0;
        end else if (i_start && !busy && (i_beats != 4'd0)) begin
            // accept a new burst
            beats_left <= first_chunk;
            queued     <= i_beats - first_chunk;
            total      <= i_beats;
            done_cnt   <= 4'd0;
            duty       <= i_duty;
            busy       <= 1'b1;
        end else if (i_ce) begin
            // retire one beat
            if (beats_left > 4'd1) begin
                beats_left <= beats_left - 4'd1;
            end else if (beats_left == 4'd1) begin
               // current chunk drained: stage the next chunk, the fabric
               // needs a cycle of turnaround before it can be issued
               beats_left <= 4'd0;
               chunk_pend <= next_chunk;
                queued     <= queued - next_chunk;
           end else if (chunk_pend != 4'd0) begin
               // staged chunk lands in the beat counter
               beats_left <= chunk_pend;
               chunk_pend <= 4'd0;
           end
           if ((beats_left <= 4'd1) && (queued == 4'd0) && (chunk_pend == 4'd0))
                busy <= 1'b0;
           if (busy && (beats_left != 4'd0))
                done_cnt <= done_cnt + 4'd1;
        end
    end

    assign o_busy = busy;
   assign o_beat = busy && i_ce && (beats_left != 4'd0);
    assign o_pwm  = busy && (done_cnt < duty);

    // ---- P: whenever the engine is not busy, the whole burst has been pushed ----
    always @(posedge i_clk)
        if (!busy)
            assert (done_cnt == total);

endmodule

// Valid/ready pipeline stage with a skid buffer carrying a three-step
// command chain: ARM -> START -> FINISH -> ARM -> ...
// The buffered word is only meaningful while the stage is stalled.
module chain_skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,       // global enable / idle condition
    input  wire       in_valid,   // producer offers its next chain word
    input  wire       out_ready,  // consumer accepts
    output wire       o_valid,
    output wire [1:0] o_code,
    output wire       o_in_ready
);
    localparam [1:0] ARM    = 2'd1;
    localparam [1:0] START  = 2'd2;
    localparam [1:0] FINISH = 2'd3;

    // producer chain position: next word emitted is src_phase+1
    reg [1:0] src_phase  = 2'd0;
    // consumer chain position: 0 = nothing armed, 1 = armed, 2 = started
    reg [1:0] phase      = 2'd0;

    // output (skid) register pair
    reg       out_valid  = 1'b0;
    reg [1:0] out_code   = ARM;
    reg       skid_valid = 1'b0;
    reg [1:0] skid_code  = ARM;

   // second (tail) skid slot: lets the stage swallow one more word when the
   // consumer stalls for two cycles in a row instead of dropping in_ready
   // immediately behind a single buffered word
   reg       skid2_valid = 1'b0;
   reg [1:0] skid2_code  = ARM;

   // one-cycle inter-chain gap: after a FINISH leaves the stage the
   // producer is held off for a cycle so it can resynchronise on the
   // head of the next chain
   reg       gap        = 1'b0;

    wire [1:0] in_code  = src_phase + 2'd1;
  wire       in_ready = !skid2_valid && !gap;
    wire       out_room = !out_valid || out_ready;
    wire       in_fire  = step && in_valid && in_ready;
    wire       out_fire = step && out_valid && out_ready;

    assign o_valid    = out_valid;
    assign o_code     = out_code;
    assign o_in_ready = in_ready;

    always @(posedge clk) begin
        if (rst) begin
            src_phase  <= 2'd0;
            phase      <= 2'd0;
            out_valid  <= 1'b0;
            out_code   <= ARM;
            skid_valid <= 1'b0;
            skid_code  <= ARM;
           skid2_valid <= 1'b0;
           skid2_code  <= ARM;
           gap        <= 1'b0;
        end else if (step) begin
            // output register: drain skid first, else take the fresh word
            if (out_room) begin
                if (skid_valid) begin
                    out_valid <= 1'b1;
                    out_code  <= skid_code;
               end else if (in_valid && in_ready) begin
                    out_valid <= 1'b1;
                    out_code  <= in_code;
                end else begin
                    out_valid <= 1'b0;
                end
            end

            // skid buffer: only loaded while the stage is stalled
            if (skid_valid) begin
               if (out_room) begin
                   // head drains into the output register; refill it from
                   // the tail slot, or straight from the producer
                   if (skid2_valid) begin
                       skid_valid <= 1'b1;
                       skid_code  <= skid2_code;
                   end else if (in_valid && in_ready) begin
                       skid_valid <= 1'b1;
                       skid_code  <= in_code;
                   end else begin
                       skid_valid <= 1'b0;
                   end
               end
           end else if (in_valid && in_ready && !out_room) begin
                skid_valid <= 1'b1;
                skid_code  <= in_code;
            end

           // tail slot: only fills behind a full head slot while the
           // output register is blocked, and always shifts down on a drain
           if (skid2_valid) begin
               if (out_room)
                   skid2_valid <= 1'b0;
           end else if (in_valid && in_ready && skid_valid && !out_room) begin
               skid2_valid <= 1'b1;
               skid2_code  <= in_code;
           end

            // producer advances on every accepted word
            if (in_valid && in_ready)
                src_phase <= (src_phase == 2'd2) ? 2'd0 : src_phase + 2'd1;

            // consumer chain tracker advances on every delivered word
            if (out_valid && out_ready)
                phase <= (out_code == FINISH) ? 2'd0 : out_code;

           // hold the producer off for one cycle after a completed chain
           gap <= out_valid && out_ready && out_code == FINISH;
        end
    end

    // P (two assertions): a later chain step is never delivered unless the
    // earlier ones already were.
    always @(*)
        assert (!(out_fire && out_code == FINISH) || phase == 2'd2);

    always @(*)
        assert (!(out_fire && out_code == START) || phase == 2'd1);

   // Q: the only word that may leave the stage during the post-FINISH
   // gap cycle is the ARM that opens the next chain.
   always @(posedge clk)
       if (!rst)
           assert (!(gap && out_fire) || out_code == ARM);
endmodule

module wifi_radio_owner_fsm (
    input  wire clk,
    input  wire rst,
    input  wire step,      // idle/enable: low freezes all state
    input  wire rx_start,  // preamble detected by the receiver
    input  wire tx_req,    // MAC wants the air for a frame
    output wire radio_tx,  // transmit chain owns the radio
    output wire radio_rx   // receive chain owns the radio
);
    // one-hot MAC air-interface FSM:
//   bit0 = IDLE, bit1 = RX_FRAME, bit2 = TX_BURST, bit3 = ACK_WAIT
reg [3:0] state;
initial state = 4'b0001;

// transmit burst sequencer: one-hot shift register that walks the PA
// through the preamble and data phases of a granted frame
//   bit0 = PREAMBLE, bit1 = DATA, 2'b00 = burst finished
reg [1:0] txph;
initial txph = 2'b00;

   // periodic beacon engine; shares the radio front end with the MAC FSM
   //   bit0 = B_IDLE, bit1 = B_RAMP, bit2 = B_SEND
   reg [2:0] bstate;
   reg [3:0] btimer;
   initial bstate = 3'b001;
   initial btimer = 4'd15;

wire s_idle = state[0];
wire s_rx   = state[1];
wire s_txb  = state[2];
wire s_ackw = state[3];

wire tx_pre = txph[0];
wire tx_dat = txph[1];
// the MAC hands the air to the burst sequencer on the way out of IDLE
wire tx_start = s_idle & tx_req & ~rx_start;

   wire b_idle = bstate[0];
   wire b_ramp = bstate[1];
   wire b_send = bstate[2];
   wire b_busy = b_ramp | b_send;
   wire b_due  = (btimer == 4'd0);
   // the MAC keeps priority: the beacon only grabs an idle, unrequested radio
   wire b_go   = b_idle & b_due & s_idle & ~rx_start & ~tx_req;

   wire [2:0] bnxt;
   assign bnxt[0] = (b_idle & ~b_go) | b_send;
   assign bnxt[1] = b_go;                             // ramp the beacon PA
   assign bnxt[2] = b_ramp;                           // ramp -> send beacon

    // next-state as a per-bit OR of its legal source states
wire [3:0] nxt;
    assign nxt[0] = (s_idle & ~rx_start & ~tx_req) | s_rx | s_ackw;
    assign nxt[1] = s_idle & rx_start;                 // RX wins the air
assign nxt[2] = tx_start | (s_txb & tx_pre);       // start / stay in burst
assign nxt[3] = s_txb & tx_dat;                    // data done -> ACK wait

    always @(posedge clk) begin
        if (rst)
state <= 4'b0001;
       // the air is single-ported: the MAC FSM stalls while the beacon has it
       else if (step && !b_busy)
            state <= nxt;
    end

  // the sequencer shifts a zero in on every granted cycle, so the burst
  // self-terminates one cycle after the data phase
  always @(posedge clk) begin
      if (rst)
          txph <= 2'b00;
      else if (step && !b_busy) begin
          if (tx_start)
              txph <= 2'b01;
          else
              txph <= {txph[0], 1'b0};
      end
  end

   always @(posedge clk) begin
       if (rst)
           bstate <= 3'b001;
       else if (step)
           bstate <= bnxt;
   end

   // beacon interval: reload on transmission, hold at zero until the air frees
   always @(posedge clk) begin
       if (rst)
           btimer <= 4'd15;
       else if (step) begin
           if (b_send)
               btimer <= 4'd15;
           else if (btimer != 4'd0)
               btimer <= btimer - 4'd1;
       end
   end

    // decoded radio ownership
assign radio_tx = tx_pre | tx_dat | b_ramp | b_send;
    assign radio_rx = s_rx    | s_ackw;

    // P: the transmit and receive chains never own the radio together
    always @(*)
        assert (!(radio_tx && radio_rx));
endmodule

module window_rate_limiter (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_req,
    output wire o_grant
);
    parameter W     = 4;
    parameter LIMIT = 3;

    // sliding window of the last W grant decisions
    reg [W-1:0] win;
    // count of ones that mirrors the window by construction
    reg [2:0]   ones;
   // admit decision in flight toward the accumulator: the count update is
   // retimed through one register stage, so `ones` trails the window by a beat
   reg         adm_q;
    // sticky arm register: set the first time a grant is ever issued
    reg         armed;
   // post-grant cooldown: a grant is followed by two enabled cycles of refusal
   reg [1:0]   gap;
    reg         pv;

    initial win   = 0;
    initial ones  = 0;
   initial adm_q = 0;
    initial armed = 0;
   initial gap   = 0;
    initial pv    = 0;

    // the bit about to leave the window
    wire [2:0] retiring = win[W-1] ? 3'd1 : 3'd0;
    // occupancy of the window once the oldest slot retires
   // plus the admit still in flight, which the accumulator has not absorbed yet
   wire [2:0] eff      = ones - retiring + (adm_q ? 3'd1 : 3'd0);

    // rate decision is taken from the mirrored count, not from the window
   // and is additionally blocked while the post-grant cooldown is running
   wire allow = i_req && (eff < LIMIT) && (gap == 2'd0);

    assign o_grant = i_ce && allow;

    always @(posedge clk) begin
        if (i_rst) begin
            win   <= 0;
            ones  <= 0;
           adm_q <= 0;
            armed <= 0;
           gap   <= 0;
        end else if (i_ce) begin
           win   <= { win[W-2:0], allow };
           ones  <= ones - retiring + (adm_q ? 3'd1 : 3'd0);
           adm_q <= allow;
            if (allow)
                armed <= 1'b1;
           if (allow)
               gap <= 2'd2;
           else if (gap != 2'd0)
               gap <= gap - 2'd1;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    // Precedence, after the limiter has armed: a grant observed one cycle ago
    // must have been preceded by a window that was not already saturated, so
    // the window can never be completely full of grants.
    always @(posedge clk)
        if (pv && armed)
            assert (!($past(i_ce) && $past(allow)) || (win != 4'hF));

   // Cooldown consistency: halfway through a cooldown the grant that started it
   // is still resident in the window, so the mirrored occupancy is not empty.
   always @(posedge clk)
       if (pv)
           assert ((gap != 2'd1) || (ones != 3'd0 || adm_q));
endmodule

// Simple token-lexer FSM: binary-encoded states 0..4, encodings 5..7 unused.
module lex_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [1:0] cls,     // 0=escape/backslash, 1=alpha, 2=digit, 3=quote
    output reg  [2:0] st,
    output reg  [2:0] len
);
    localparam [2:0] S_IDLE  = 3'd0;
    localparam [2:0] S_IDENT = 3'd1;
    localparam [2:0] S_NUM   = 3'd2;
    localparam [2:0] S_STR   = 3'd3;
    localparam [2:0] S_ESC   = 3'd4;
    // An escape can now be taken from top level or from inside an identifier,
    // so S_ESC alone no longer says which token is being built: the state code
    // to resume with is held here while st == S_ESC.
    reg [2:0] esc_ret;
   // Decode and commit are now separate cycles: the next-state decode and the
   // length adder no longer share one combinational path to the outputs. A
   // character is absorbed into the staging pair in one cycle and the pair is
   // driven onto st/len in the next.
   reg [2:0] st_s;
   reg [2:0] len_s;
   reg       s_vld;

    wire [2:0] len_inc = (len == 3'd7) ? 3'd7 : (len + 3'd1);

    initial st  = S_IDLE;
    initial len = 3'd0;
    initial esc_ret = S_IDLE;
   initial st_s  = S_IDLE;
   initial len_s = 3'd0;
   initial s_vld = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            st  <= S_IDLE;
            len <= 3'd0;
            esc_ret <= S_IDLE;
           st_s  <= S_IDLE;
           len_s <= 3'd0;
           s_vld <= 1'b0;
        end else if (ce) begin
           if (s_vld) begin
               st    <= st_s;   // commit cycle: staged pair becomes visible
               len   <= len_s;
               s_vld <= 1'b0;
           end else begin
               s_vld <= 1'b1;   // decode cycle: absorb this character
            case (st)
                S_IDLE: begin
                    if (cls == 2'd1) begin
                       st_s  <= S_IDENT;
                       len_s <= 3'd1;
                    end else if (cls == 2'd2) begin
                       st_s  <= S_NUM;
                       len_s <= 3'd1;
                    end else if (cls == 2'd3) begin
                       st_s  <= S_STR;
                       len_s <= 3'd0;
                    end else begin
                       st_s    <= S_ESC;   // stray backslash: escaped char starts an identifier
                        esc_ret <= S_IDENT;
                       len_s   <= 3'd0;
                    end
                end
                S_IDENT: begin
                    if (cls == 2'd1 || cls == 2'd2) begin
                       st_s  <= S_IDENT;
                       len_s <= len_inc;
                    end else if (cls == 2'd0) begin
                       st_s    <= S_ESC;   // a\b is still a single identifier
                        esc_ret <= S_IDENT;
                       len_s   <= len;
                    end else begin
                       st_s  <= S_IDLE;
                       len_s <= 3'd0;
                    end
                end
                S_NUM: begin
                    if (cls == 2'd2) begin
                       st_s  <= S_NUM;
                       len_s <= len_inc;
                    end else begin
                       st_s  <= S_IDLE;
                       len_s <= 3'd0;
                    end
                end
                S_STR: begin
                    if (cls == 2'd3) begin
                       st_s  <= S_IDLE;   // closing quote ends the token
                       len_s <= 3'd0;
                    end else if (cls == 2'd0) begin
                       st_s  <= S_ESC;    // backslash: next char is literal
                        esc_ret <= S_STR;
                       len_s <= len;
                    end else begin
                       st_s  <= S_STR;
                       len_s <= len_inc;
                    end
                end
                S_ESC: begin
                   st_s  <= esc_ret;     // resume whatever token the escape interrupted
                   len_s <= len_inc;
                end
                default: begin
                    // unreachable encodings 5..7: recover to IDLE
                   st_s  <= S_IDLE;
                end
            endcase
           end
        end
    end

    // P: in the IDLE state the accumulated token length is always zero.
    always @(*)
        if (st == 3'd0)
            assert (len == 3'd0);
endmodule

module credit_deadline (
    input  wire clk,
    input  wire i_ce,      // global enable: low => all state frozen
    input  wire rst,
    input  wire req,       // producer wants to spend a credit
    output wire grant,
    output wire busy
);
    localparam [2:0] TOTAL = 3'd4;   // configured credit pool

    // credits held by the producer, credits outstanding at the consumer
    reg [2:0] credits;
    reg [2:0] outst;
    // consumer needs two enabled cycles to retire one outstanding credit
    reg       svc;
    // bounded-response deadline countdown for the outstanding credits
    reg [3:0] timer;
   // governor watermark: deepest outstanding occupancy seen so far
   reg [2:0] peak;

    initial begin
        credits = 3'd4;
        outst   = 3'd0;
        svc     = 1'b0;
        timer   = 4'd0;
       peak    = 3'd0;
    end

   // once occupancy has ever peaked at the whole pool, hold off new
   // spends until the consumer has drained completely
   wire throttle  = (peak == TOTAL) && (outst != 3'd0);
   wire do_spend  = req && (credits != 3'd0) && !throttle;
    wire do_return = (outst != 3'd0) && (svc == 1'b1);
   wire [2:0] outst_nxt = outst + (do_spend  ? 3'd1 : 3'd0)
                                - (do_return ? 3'd1 : 3'd0);

    assign grant = i_ce && do_spend;
    assign busy  = (outst != 3'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            if (rst) begin
                credits <= TOTAL;
                outst   <= 3'd0;
                svc     <= 1'b0;
                timer   <= 4'd0;
               peak    <= 3'd0;
            end else begin
                // credit conservation: one token moves per event
                credits <= credits - (do_spend  ? 3'd1 : 3'd0)
                                   + (do_return ? 3'd1 : 3'd0);
                outst   <= outst   + (do_spend  ? 3'd1 : 3'd0)
                                   - (do_return ? 3'd1 : 3'd0);

                // two-cycle service phase per outstanding credit
                if (outst == 3'd0)
                    svc <= 1'b0;
                else
                    svc <= ~svc;

               // watermark only ever rises
               if (outst_nxt > peak)
                   peak <= outst_nxt;

                // deadline budget: each spend buys 2 cycles, one cycle burnt
                timer <= timer - ((timer != 4'd0) ? 4'd1 : 4'd0)
                               + (do_spend ? 4'd2 : 4'd0);
            end
        end
    end

    // Bounded response (safety): the countdown must never expire while a
    // credit is still outstanding at the consumer.
    always @(posedge clk)
        if (outst != 3'd0)
            assert (timer != 4'd0);

   // Quiescence (safety): once the whole pool is back at the producer
   // there is nothing left at the consumer, so the service phase must be
   // idle and the deadline budget must be fully spent.
   always @(posedge clk)
       if (credits == TOTAL)
           assert ((timer == 4'd0) && (svc == 1'b0));

   // Governor coherence (safety): the in-flight deadline budget never
   // exceeds two cycles per credit at the recorded peak occupancy.
   always @(posedge clk)
       assert (timer <= {peak, 1'b0});

endmodule

module pwm_prio_duty (
    input  wire       clk,
    input  wire       ce,
    input  wire [7:0] req,
    output reg        out_r,
    output reg        vld_r
);
    // ---------------- PWM state ----------------
    reg [2:0] cnt;        // period counter 0..7
   reg [2:0] per;        // programmed frame length minus one (frame = per+1)
    reg [3:0] duty;       // active duty value 0..8
    reg [3:0] hi_cnt;     // cycles spent high inside the current period
    reg       shadow_nz;  // shadow: the duty programmed for this period was nonzero
    reg       armed;      // scope: high until the first all-zero request load
   reg       duty_ext;   // extra whole cycle granted to this frame by the dither
   reg       dith;       // pending half-step credit carried between frames

    initial begin
        cnt       = 3'd0;
       per       = 3'd7;   // reset frame is the full eight cycles
        duty      = 4'd4;   // reset duty is nonzero
        hi_cnt    = 4'd0;
        shadow_nz = 1'b1;   // matches reset duty
        armed     = 1'b1;
       duty_ext  = 1'b0;
       dith      = 1'b0;
        out_r     = 1'b0;
        vld_r     = 1'b0;
    end

    // ---------------- priority encoder over the request vector ----------------
    reg [2:0] idx;
    reg       vld;
    always @(*) begin
        vld = |req;
        if      (req[7]) idx = 3'd7;
        else if (req[6]) idx = 3'd6;
        else if (req[5]) idx = 3'd5;
        else if (req[4]) idx = 3'd4;
        else if (req[3]) idx = 3'd3;
        else if (req[2]) idx = 3'd2;
        else if (req[1]) idx = 3'd1;
        else             idx = 3'd0;
    end

    // requested duty: highest set index + 1, or 0 when no request
    wire [3:0] duty_req = vld ? ({1'b0, idx} + 4'd1) : 4'd0;

   // ---------------- frame-length programming ----------------
   // req[2:0] double as the frame-length code; a requested duty that does not
   // fit in the programmed frame is truncated to 100% of that frame
   wire [2:0] per_nxt  = req[2:0];
   wire [3:0] per_lim  = {1'b0, per_nxt} + 4'd1;
   wire [3:0] duty_nxt = (duty_req > per_lim) ? per_lim : duty_req;
  // ---------------- half-step dither ----------------
  // when several sources request at once the winner earns an extra half cycle
  // of duty for the aggregate load; two half cycles are cashed in as one whole
  // cycle, and the bump is only applied while the duty is below 100% of the
  // frame so that the extra cycle still fits inside the frame
  wire       multi    = vld && ((req & (req - 8'd1)) != 8'd0);
  wire       ext_nxt  = (dith && multi) && (duty_nxt < per_lim);
  wire [3:0] duty_eff = duty + {3'b000, duty_ext};

    // ---------------- comparator: high exactly while cnt < duty ----------------
wire out  = ({1'b0, cnt} < duty_eff);
   wire wrap = (cnt == per);

    always @(posedge clk) begin
        if (ce) begin
           cnt   <= wrap ? 3'd0 : cnt + 3'd1;   // restarts at each boundary
            out_r <= out;          // registered output stage
            vld_r <= vld;
            if (wrap) begin
               per       <= per_nxt;
                // period boundary: latch the new duty and its shadow flag together
               duty      <= duty_nxt;
               shadow_nz <= (duty_nxt != 4'd0);
              duty_ext  <= ext_nxt;
              dith      <= dith ^ multi;
                hi_cnt    <= 4'd0;
               if (duty_nxt == 4'd0)
                    armed <= 1'b0; // the scope-closing event R
            end else begin
                hi_cnt <= hi_cnt + (out ? 4'd1 : 4'd0);
               // frame monitor: the high time can never outrun the frame it
               // belongs to; if it does, the latched flag no longer describes
               // the pulse being emitted, so drop it
               if (hi_cnt > {1'b0, per})
                   shadow_nz <= 1'b0;
            end
        end
    end

    // Precedence, in the "before the first zero-duty program" scope:
    // if the output has been high at all inside this period, then a nonzero
    // duty must have been recorded in the shadow flag earlier.
    always @(posedge clk)
        if (armed && hi_cnt != 4'd0)
            assert (shadow_nz);
endmodule

module phase_divider_pair (
    input  wire       clk,
    input  wire       ce,       // divider step enable; low = idle, all state held
    input  wire       resync,   // realigns both phase counters, retires the pristine scope
    output reg  [2:0] phase,    // primary phase counter, mod 5
    output reg  [2:0] cnt,      // skewed phase counter, mod 5, built 2 phases ahead
    output reg        en_load,  // divided enable: fires the cycle after phase wraps
    output reg        en_sample,// divided enable: fires the cycle after cnt wraps
    output reg        pristine  // high until the first resync has ever happened
);

    // Load/sample ledger: every load pulse and every sample pulse is logged
    // for the lifetime of the current alignment, so the buffer downstream can
    // account for the two divided enables it sees.
    reg  [3:0] n_load;   // count of load pulses issued
    reg  [3:0] n_samp;   // count of sample pulses issued

    // samples that do not have a matching load behind them yet
    wire [3:0] samp_ahead = n_samp - n_load;
    // a realignment can leave the ping-pong buffer starved; while the sample
    // side is two or more entries ahead, inject make-up load pulses
    wire       makeup     = (samp_ahead >= 4'd2);

   // Skew-buffer ledger: the sample pulse captures one entry into the
   // ping-pong skew buffer and the load pulse releases it to the sink, so
   // both sides are logged as the buffer sees them, on the divided enables.
   reg  [3:0] n_cap;    // entries captured by the sample side
   reg  [3:0] n_rel;    // entries released by the load side
   wire [3:0] level     = n_cap - n_rel;
   // the load side must not release an entry the sample side has not
   // captured yet, so the phase-4 pulse waits for a filled buffer
   wire       bank_full = (level != 4'd0);

   // Load-side stall watchdog: the sink downstream must never be left
   // without a load pulse for long, so the gap since the last one is timed
   // and a make-up pulse is forced once that gap gets too wide.
   reg  [2:0] gap;      // enabled cycles since the last load pulse
   wire       wdog       = (gap >= 3'd6);
wire       load_pulse = ((phase == 3'd4) && bank_full) || makeup || wdog;

    // The skewed counter is constructed 2 phases ahead of the primary phase
    // counter, so the two divided-enable pulses are interleaved by design.
    initial phase     = 3'd0;
    initial cnt       = 3'd2;
    initial en_load   = 1'b0;
    initial en_sample = 1'b0;
    initial pristine  = 1'b1;
    initial n_load    = 4'd0;
    initial n_samp    = 4'd0;
initial n_cap     = 4'd0;
initial n_rel     = 4'd0;
   initial gap       = 3'd0;

    always @(posedge clk) begin
        if (resync) begin
            // hard realignment: both phase counters are slammed to zero, which
            // destroys the constructed skew (and retires the pristine scope)
            phase     <= 3'd0;
            cnt       <= 3'd0;
            en_load   <= 1'b0;
            en_sample <= 1'b0;
            pristine  <= 1'b0;
            n_load    <= 4'd0;
            n_samp    <= 4'd0;
n_cap     <= 4'd0;
n_rel     <= 4'd0;
           gap       <= 3'd0;
        end
        else if (ce) begin
            phase     <= (phase == 3'd4) ? 3'd0 : phase + 3'd1;
            cnt       <= (cnt   == 3'd4) ? 3'd0 : cnt   + 3'd1;
            // each divided enable pulses exactly when its phase counter wraps
           en_load   <= load_pulse;
            en_sample <= (cnt   == 3'd4);
            // ledger entries are made as the pulses are issued
           n_load    <= n_load + (load_pulse ? 4'd1 : 4'd0);
            n_samp    <= n_samp + ((cnt == 3'd4) ? 4'd1 : 4'd0);
n_cap     <= n_cap + (en_sample ? 4'd1 : 4'd0);
n_rel     <= n_rel + (en_load   ? 4'd1 : 4'd0);
           gap       <= load_pulse ? 3'd0 : gap + 3'd1;
        end
    end

    // Absence: while the divider has never been resynced, the two divided
    // enables are never asserted in the same cycle.
    always @(posedge clk)
        if (pristine)
            assert (!(en_load && en_sample));

   // Alignment: while the divider has never been resynced, the sample pulse
   // always lands three enabled cycles into the current load window.
   always @(posedge clk)
       if (pristine)
           assert (!en_sample || (gap == 3'd3));

endmodule

module pingpong_tile_buffer (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire       wr_en,
    input  wire       rd_en,
    input  wire [7:0] wr_data,
    output reg  [7:0] rd_data,
    output wire       o_sel
);
    localparam [1:0] LAST = 2'd3;

    // ping-pong double buffer: one half owned by the rasterizer (writer),
    // the other half owned by the shader fetch port (reader)
    reg       sel;                 // master ping-pong select bit
    reg       wr_half, rd_half;    // half currently addressed by each port
    reg [1:0] wcnt, rcnt;          // offset inside the owned half
    reg       wr_full, rd_empty;   // per-half handshake flags
   // buffer-turnaround commit pipeline: the ownership swap is handed to the
   // memory system and retires four cycles later, so both ports keep their
   // current half assignment until the request has walked all four stages
   reg       swp_v0, swp_v1, swp_v2, swp_v3;   // request valid, per stage
   reg       swp_d0, swp_d1, swp_d2, swp_d3;   // pending select, per stage
  // turnaround ledger for the memory-system interface: every issued swap
  // request is logged on n_iss and every retired one on n_ret. The port
  // allows a single outstanding turnaround, so the two logs must agree
  // again before a new request may be handed over. Free-running, wrapping.
  reg [3:0] n_iss, n_ret;
    reg [7:0] mem [0:7];
    integer   i;

    initial begin
        sel     = 1'b0;
        wr_half = 1'b0;
        rd_half = 1'b1;
        wcnt    = 2'd0;
        rcnt    = 2'd0;
        wr_full = 1'b0;
        rd_empty= 1'b1;
       swp_v0  = 1'b0;
       swp_v1  = 1'b0;
       swp_v2  = 1'b0;
       swp_v3  = 1'b0;
       swp_d0  = 1'b0;
       swp_d1  = 1'b0;
       swp_d2  = 1'b0;
       swp_d3  = 1'b0;
       n_iss   = 4'd0;
       n_ret   = 4'd0;
        rd_data = 8'h00;
        for (i = 0; i < 8; i = i + 1) mem[i] = 8'h00;
    end

    wire [2:0] wr_addr = {wr_half, wcnt};
    wire [2:0] rd_addr = {rd_half, rcnt};

    wire w_step = i_ce && wr_en && !wr_full;
    wire r_step = i_ce && rd_en && !rd_empty;
  wire ld_outst   = (n_iss != n_ret);   // a logged turnaround is unretired
  wire swap       = i_ce && wr_full && rd_empty && !ld_outst;
   wire swp_commit = i_ce && swp_v3;

    assign o_sel = sel;

    always @(posedge clk) begin
        if (rst) begin
            sel      <= 1'b0;
            wr_half  <= 1'b0;
            rd_half  <= 1'b1;
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
            wr_full  <= 1'b0;
            rd_empty <= 1'b1;
           swp_v0   <= 1'b0;
           swp_v1   <= 1'b0;
           swp_v2   <= 1'b0;
           swp_v3   <= 1'b0;
           swp_d0   <= 1'b0;
           swp_d1   <= 1'b0;
           swp_d2   <= 1'b0;
           swp_d3   <= 1'b0;
           n_iss    <= 4'd0;
           n_ret    <= 4'd0;
       end else if (swp_commit) begin
           sel      <= swp_d3;
           wr_half  <= swp_d3; // writer takes the freshly drained half
           rd_half  <=  sel;   // reader takes the freshly filled half
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
            wr_full  <= 1'b0;
            rd_empty <= 1'b0;
        end else begin
            if (w_step) begin
                mem[wr_addr] <= wr_data;
                wcnt <= wcnt + 2'd1;
                if (wcnt == LAST) wr_full <= 1'b1;
            end
            if (r_step) begin
                rd_data <= mem[rd_addr];
                rcnt <= rcnt + 2'd1;
                if (rcnt == LAST) rd_empty <= 1'b1;
            end
        end

       // the turnaround request advances one stage per enabled cycle
       if (!rst && i_ce) begin
           swp_v3 <= swp_v2;   swp_d3 <= swp_d2;
           swp_v2 <= swp_v1;   swp_d2 <= swp_d1;
           swp_v1 <= swp_v0;   swp_d1 <= swp_d0;
           swp_v0 <= swap;     swp_d0 <= ~sel;
          if (swap)       n_iss <= n_iss + 4'd1;
          if (swp_commit) n_ret <= n_ret + 4'd1;
       end
    end

    // P: whenever both ports perform an access in the same cycle they never
    // touch the same buffer location
    always @(posedge clk)
        if (i_ce && wr_en && rd_en && !wr_full && !rd_empty)
            assert (wr_addr != rd_addr);
endmodule

// Debug-probe challenge sequencer: a maximal-length LFSR supplies one tick per
// chain step (arm -> start -> finish). The LFSR is seeded non-zero and can never
// enter the all-zeros lockup state, so every FSM advance is accompanied by a
// genuine change of the challenge shift register.
module probe_chain_seq (
    input  wire       clk,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire       arm,
    input  wire       start,
    input  wire       fin,
    output reg  [1:0] stage,
    output reg        pre_done,
    output reg  [3:0] chal
);
    // stage encoding: 0 = IDLE, 1 = ARMED, 2 = RUNNING, 3 = DONE
    reg [3:0] lfsr;
    reg       pv;
    // channel B: second probe chain sharing the one challenge generator
    reg [1:0] stage_b;
    reg       own;      // 0 = chain A holds the generator, 1 = chain B
    reg       ld;       // generator context restore in flight (owner stalls)
    reg       chal_ok;  // chal holds a valid generator word
   // per-chain generator context: a chain preempted by the arbiter resumes
   // its own point in the challenge stream when it gets the generator back
   reg [3:0] ctx_a;
   reg [3:0] ctx_b;
   reg [2:0] tmr;      // round-robin time slice for the shared generator

    initial lfsr     = 4'b0001;
    initial chal     = 4'b0000;
    initial stage    = 2'd0;
    initial pre_done = 1'b1;   // before-scope: high until the first DONE ever
    initial pv       = 1'b0;
    initial stage_b  = 2'd0;
    initial own      = 1'b0;
    initial ld       = 1'b0;
    initial chal_ok  = 1'b0;
   initial ctx_a    = 4'b0000;
   initial ctx_b    = 4'b0000;
   initial tmr      = 3'd7;

    // x^4 + x^3 + 1 : period 15 over the non-zero states
    wire       fb        = lfsr[3] ^ lfsr[2];
    wire [3:0] lfsr_next = {lfsr[2:0], fb};

   // A chain that has left IDLE owns a parked generator word and resumes from
   // it; a chain that is IDLE starts cold from the last challenge issued on
   // the shared bus, or from the cold seed if none has been issued yet.
   wire       in_a      = (stage   != 2'd0);
   wire       in_b      = (stage_b != 2'd0);
   wire [3:0] cold      = chal_ok ? chal : 4'b0001;
   wire [3:0] lfsr_rest = own ? (in_b ? ctx_b : cold)
                              : (in_a ? ctx_a : cold);

    // the current owner releases the generator once its chain reaches DONE
    wire a_done = (stage   == 2'd3);
    wire b_done = (stage_b == 2'd3);
   // ... or when its arbitration time slice expires, so a chain that stalls
   // mid-run cannot hold the shared generator forever
   wire slice_up = (tmr == 3'd0);
   wire yield    = !ld && (slice_up || (own ? b_done : a_done));

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            lfsr <= ld ? lfsr_rest : lfsr_next;
           if (yield) begin
               own <= ~own;
               if (own) ctx_b <= lfsr_next;   // park the outgoing chain's stream
               else     ctx_a <= lfsr_next;
               tmr <= 3'd7;
           end else if (!ld) begin
               tmr <= tmr - 3'd1;
           end
            ld <= yield;
            if (!ld) begin
            if (!own) begin
            case (stage)
                2'd0: if (arm) begin
                          stage <= 2'd1;
                          chal  <= lfsr;      // latch the challenge word on arm
                      chal_ok <= 1'b1;
                     ctx_a <= lfsr_next;  // resume point for this chain
                      end
                2'd1: if (start) stage <= 2'd2;
                2'd2: if (fin) begin
                          stage    <= 2'd3;   // finish: clears the before-scope
                          pre_done <= 1'b0;
                      end
                default: stage <= 2'd0;
            endcase
            end else begin
                case (stage_b)
                    2'd0: if (arm) begin
                              stage_b <= 2'd1;
                              chal    <= lfsr;   // same challenge bus
                              chal_ok <= 1'b1;
                             ctx_b <= lfsr_next;
                          end
                    2'd1: if (start) stage_b <= 2'd2;
                    2'd2: if (fin)   stage_b <= 2'd3;
                    default: stage_b <= 2'd0;
                endcase
            end
            end
        end
    end

    // P: before the first finish has ever been observed, the chain FSM cannot
    //    move unless the challenge shift register moved with it.
    always @(posedge clk)
        if (pv && pre_done && $stable(lfsr))
            assert ($stable(stage));
endmodule

module prio_grant_tracker (
    input  wire       clk,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [3:0] req,
    output reg        vld,     // registered valid: idx meaningful only while set
    output reg  [1:0] idx,     // encoded winner index
    output reg  [3:0] oh,      // registered one-hot grant
    output reg        ack_lo,  // low-half acknowledge, derived from idx
    output reg        ack_hi,  // high-half acknowledge, derived from one-hot
output reg        armed,   // sticky: set the first time a request is taken
output reg  [3:0] n_take,  // ledger: leases issued  (free-running, wraps)
output reg  [3:0] n_drop,  // ledger: leases retired (free-running, wraps)
output reg        stale    // standing lease has burned one idle cycle
);

    // combinational priority encoder (lowest index wins)
    wire       any = |req;
    wire [1:0] enc = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;
    wire [3:0] iso = req & (~req + 4'd1);   // isolate lowest set bit
   // retirements are booked by half: a low-half holder settles into n_drop,
   // a high-half holder into its own column, so the two halves of the
   // ledger can be read out independently
   reg [3:0] n_drop_hi;

   // the ledger, not vld, is the authority on lease occupancy
  wire [3:0] n_ret       = n_drop + n_drop_hi;
  wire       outstanding = (n_take != n_ret);

    initial begin
        vld    = 1'b0;
        idx    = 2'd0;
        oh     = 4'b0000;
        ack_lo = 1'b0;
        ack_hi = 1'b0;
        armed  = 1'b0;
n_take = 4'd0;
n_drop = 4'd0;
       n_drop_hi = 4'd0;
stale  = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            // acknowledge flags are built from the *previous* grant state:
            // one path reads the index, the other reads the one-hot vector
            ack_lo <= vld && (idx < 2'd2);
            ack_hi <= vld && (oh[3] || oh[2]);

            if (any) begin
                // any request refreshes the lease and re-asserts valid
                vld   <= 1'b1;
                armed <= 1'b1;
                stale <= 1'b0;
                if (!outstanding) begin
                    // ledger is square: issue a fresh lease to the winner
                    idx    <= enc;
                    oh     <= iso;
                    n_take <= n_take + 4'd1;
                end else if (enc < idx) begin
                    // lease already in flight: a higher-priority requester
                    // takes it over in place -- a hand-off, not a new lease,
                    // so the ledger does not move
                    idx <= enc;
                    oh  <= iso;
                end
                // otherwise the current holder keeps the bus
            end else if (outstanding) begin
                if (stale) begin
                    // second idle cycle retires the lease; the one-hot is
                    // left parked as a record of the last holder
                    vld    <= 1'b0;
                    stale  <= 1'b0;
                   if (idx[1]) n_drop_hi <= n_drop_hi + 4'd1;
                   else        n_drop    <= n_drop    + 4'd1;
                end else begin
                    // first idle cycle: age the standing grant round-robin
                    idx   <= idx + 2'd1;
                    oh    <= {oh[2:0], oh[3]};
                    stale <= 1'b1;
                end
            end
        end
    end

    // P: once the tracker has ever accepted a request, the low-half and
    // high-half acknowledges are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(ack_lo && ack_hi));

endmodule

module dma_burst_engine (
    input  wire       clk,
    input  wire       i_ce,     // idle condition: low freezes all state
    input  wire       start,    // Q: opens the status window
    input  wire [3:0] len,      // requested burst length (beats)
    input  wire       ack,      // R: host acknowledges, closes the window
    output reg        busy,
    output reg  [3:0] beats
);
    // shadow register: records the length that was requested earlier
    reg [3:0] req_len;
    // beats actually pushed out so far in the current burst
    reg [3:0] done_cnt;
    // window register: set by start, cleared by ack
    reg       armed;
   // beats deferred past the 8-beat hardware burst limit of the current request
   reg [3:0] resid;
// credit-return coalescing: the fabric returns completion credit in groups of
// four, so beats already pushed may sit here before reaching done_cnt
reg [2:0] pend;

    initial busy     = 1'b0;
    initial beats    = 4'd0;
    initial req_len  = 4'd0;
    initial done_cnt = 4'd0;
    initial armed    = 1'b0;
   initial resid    = 4'd0;
initial pend     = 3'd0;

    wire accept = start && !armed && (len != 4'd0);
   // the fabric accepts at most 8 beats in one burst; the rest is deferred
   wire [3:0] chunk = (len > 4'd8) ? 4'd8 : len;
wire       last_beat = (beats == 4'd1) && (resid == 4'd0);
wire [2:0] pend_nxt  = (pend == 3'd3) ? 3'd0 : pend + 3'd1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
               beats    <= chunk;
                req_len  <= len;      // shadow capture of the earlier event
               resid    <= len - chunk;
                done_cnt <= 4'd0;
pend     <= 3'd0;
                busy     <= 1'b1;
                armed    <= 1'b1;
end else if (busy && beats != 4'd0) begin
               beats    <= (beats == 4'd1 && resid != 4'd0) ? resid : beats - 4'd1;
resid    <= (beats == 4'd1) ? 4'd0 : resid;
// one beat pushed: hold the credit until a full group of four is ready
pend     <= pend_nxt;
done_cnt <= (pend == 3'd3) ? done_cnt + 4'd4 : done_cnt;
busy     <= !last_beat || (pend_nxt != 3'd0);
end else if (busy) begin
// trailing partial credit group flushed before the burst reports done
done_cnt <= done_cnt + {1'b0, pend};
pend     <= 3'd0;
busy     <= 1'b0;
            end else if (armed && ack) begin
                armed    <= 1'b0;
            end
        end
    end

    // P, part 1: inside the window, while beats remain the burst cannot yet have
    // delivered everything that was requested earlier.
    always @(posedge clk)
        if (armed && busy)
            assert (done_cnt < req_len);

    // P, part 2: inside the window, once the engine is no longer busy the
    // delivered count must exactly match the earlier requested length.
    always @(posedge clk)
        if (armed && !busy)
            assert (done_cnt == req_len);

   // P, part 3: inside the window, while a deferred chunk is still queued the
   // beats already pushed plus the beats still held back must leave headroom
   // inside the length that was requested earlier.
   always @(posedge clk)
       if (armed && resid != 4'd0)
           assert (({1'b0,done_cnt} + {1'b0,resid}) < {1'b0,req_len});
endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

   // destination-side retiming pipeline: the event decoder sits far from the
   // synchronizer in the floorplan, so the sampled pointer is retimed four
   // times before it is decoded, and both decode operands are taken from
   // the last two taps of this pipeline so they share the same route delay
   reg [2:0] ret1;
   initial   ret1 = 3'b000;
   reg [2:0] ret2;
   initial   ret2 = 3'b000;
   reg [2:0] ret3;
   initial   ret3 = 3'b000;
   reg [2:0] ret4;
   initial   ret4 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;
   // number of chain transitions actually taken.  A corrupt handshake aborts
   // straight to FINISH, so the transition count is what tells a full walk
   // of the chain apart from an aborted one.
   reg [2:0] steps;
   initial   steps = 3'd0;

    wire [2:0] gray  = bin ^ (bin >> 1);
   wire [2:0] delta = ret3 ^ ret4;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
           ret1      <= 3'b000;
           ret2      <= 3'b000;
           ret3      <= 3'b000;
           ret4      <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
           steps     <= 3'd0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;
           ret1  <= sync2;
           ret2  <= ret1;
           ret3  <= ret2;
           ret4  <= ret3;

            if (bad_ev) begin
                stage <= S_FINISH;
               steps <= steps + 3'd1;
            end else begin
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                       steps   <= steps + 3'd1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                       steps     <= steps + 3'd1;
                    end
                S_STARTED:
                   if (fin_ev) begin
                       stage <= S_FINISH;
                       steps <= steps + 3'd1;
                   end
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
   assign o_done  = (stage == S_FINISH) && (steps == 3'd3);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
   // an abort reaches FINISH without walking the chain, so a FINISH that the
   // done output is allowed to honour must show all three transitions counted
   always @(posedge i_clk)
       if (stage == S_FINISH)
           assert (steps == 3'd3);
endmodule

// Multi-zone thermostat front end with hysteresis and a power budget.
// The active-zone mask is a parity protected register slice; a maintained
// occupancy counter and a remaining-budget counter track it.
module zone_heat_budget (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire [2:0] i_zone,    // zone under consideration this cycle
    input  wire [7:0] i_temp,    // measured temperature of that zone
    output wire       o_fault,   // parity mismatch on the zone slice
    output wire [3:0] o_nact,
output wire [3:0] o_budget,
output reg  [3:0] o_hot_cnt
);
    parameter [7:0] T_LOW  = 8'd40;   // below this, zone asks for heat
    parameter [7:0] T_HIGH = 8'd60;   // above this, zone releases heat
    localparam [3:0] BUDGET = 4'd4;   // at most 4 heaters may run at once

    // ---- parity protected register slice -------------------------------
    reg [7:0] zone;    // one bit per zone heater
    reg       zpar;    // parity bit covering zone
    initial   zone = 8'h00;
    initial   zpar = 1'b0;

    // ---- bookkeeping registers -----------------------------------------
    reg [3:0] nact;    // number of heaters currently on
    reg [3:0] budget;  // remaining power slots
    initial   nact   = 4'd0;
    initial   budget = BUDGET;

   // ---- issue / commit pipeline ---------------------------------------
   // A grant decided this cycle reaches the heater mask on the next cycle;
   // the in-flight grant is held here.  One grant may be in flight.
   reg       p_val;   // a grant is in flight
   reg       p_on;    // 1 = turn the zone on, 0 = turn it off
   reg [2:0] p_zone;  // zone the in-flight grant targets
   initial   p_val  = 1'b0;
   initial   p_on   = 1'b0;
   initial   p_zone = 3'd0;
initial   o_hot_cnt = 4'd0;

    wire fault = (zpar != (^zone));
    assign o_fault  = fault;
    assign o_nact   = nact;
    assign o_budget = budget;

    // hysteresis: nothing happens inside the dead band, so no chattering
    wire req_on  = i_ce && !fault && (i_temp <  T_LOW);
    wire req_off = i_ce && !fault && (i_temp >  T_HIGH);

   // forward the in-flight grant, so a zone is never granted twice while
   // its mask bit has not been updated yet
   wire zbit = (p_val && (p_zone == i_zone)) ? p_on : zone[i_zone];

   wire do_on  = req_on  && !zbit && (budget != 4'd0);
   wire do_off = req_off &&  zbit;

   // a power slot is reserved when the grant is issued and released only
   // when the heater has actually been switched off, one cycle later
   wire bud_dec = do_on;
   wire bud_inc = p_val && !p_on;

    always @(posedge i_clk) begin
        if (i_rst) begin
            zone   <= 8'h00;
            zpar   <= 1'b0;
            nact   <= 4'd0;
            budget <= BUDGET;
           p_val  <= 1'b0;
           p_on   <= 1'b0;
           p_zone <= 3'd0;
o_hot_cnt <= 4'd0;
       end else if (i_ce) begin
           // commit stage: apply the grant issued last cycle
           if (p_val) begin
               zone[p_zone] <= p_on;
               zpar         <= ~zpar;  // one data bit flips, parity flips
               nact         <= p_on ? nact + 4'd1 : nact - 4'd1;
           end
           // issue stage: latch this cycle's decision
           p_val  <= do_on || do_off;
           p_on   <= do_on;
           p_zone <= i_zone;
           budget <= budget - {3'b000, bud_dec} + {3'b000, bud_inc};
o_hot_cnt <= ((i_temp > T_HIGH) && (o_hot_cnt != 4'd15)) ? o_hot_cnt + 4'd1 : o_hot_cnt;
       end
    end

    wire heating = (zone != 8'h00);

    // P: whenever any heater is running, occupancy never exceeds the
    //    power budget of 4 (the counter is 4 bits wide).
    always @(posedge i_clk)
        if (heating)
            assert (nact <= 4'd4);
endmodule

module serial_retire_counter (
    input  wire i_clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_bit,
    output wire o_word_done,
    output wire o_saturated
);
    // Bit-serial datapath: one bit per enabled cycle, 32 bits per word.
    // Every completed 32-bit word retires one operation; the retire counter
    // is a saturating up-counter that clamps at 20, well below the 31 its
    // 5-bit register could hold.
    localparam [4:0] MAX_RETIRE = 5'd20;

    reg [4:0]  sh;       // serial bit index 0..31
    reg [31:0] word;     // serial shift register (datapath flavour)
    reg [4:0]  retired;  // saturating up-counter, clamps at MAX_RETIRE
    reg        done;     // "counter has reached the clamp" flag
   reg [4:0]  pend;    // retire credits posted but not yet counted
  // Credit ledger for occupancy audit: every post and every release is
  // logged.  Free-running, wraps at 5 bits; the queue depth reported to the
  // saturation accounting is the difference of the two logs.
  reg [4:0]  n_post;  // credits posted  (enqueue side of the ledger)
  reg [4:0]  n_rel;   // credits released (dequeue side of the ledger)

    initial sh      = 5'd0;
    initial word    = 32'd0;
    initial retired = 5'd0;
    initial done    = 1'b0;
   initial pend    = 5'd0;
  initial n_post  = 5'd0;
  initial n_rel   = 5'd0;

   // Retirement is credited through a small pending-credit queue: a completed
   // word posts one credit, and the retire counter's write port (shared with
   // word capture) releases one credit on any enabled cycle that is not a
   // word boundary.  Saturation is declared on the total, posted + counted.

    wire word_last = (sh == 5'd31);

  wire [4:0] outstanding  = n_post - n_rel;
  wire [5:0] retire_total = {1'b0, retired} + {1'b0, outstanding};
   wire       credit_enq   = word_last && !done;
   wire       credit_deq   = (pend != 5'd0) && !word_last;

    always @(posedge i_clk) begin
        if (i_rst) begin
            sh      <= 5'd0;
            word    <= 32'd0;
            retired <= 5'd0;
            done    <= 1'b0;
           pend    <= 5'd0;
          n_post  <= 5'd0;
          n_rel   <= 5'd0;
        end else if (i_ce) begin
            sh   <= sh + 5'd1;
            word <= { i_bit, word[31:1] };
           if (credit_enq)
               pend <= pend + 5'd1;
           else if (credit_deq)
               pend <= pend - 5'd1;
           if (credit_deq)
               retired <= retired + 5'd1;
          if (credit_enq)
              n_post <= n_post + 5'd1;
          if (credit_deq)
              n_rel <= n_rel + 5'd1;
           if (credit_enq)
               done <= (retire_total == {1'b0, (MAX_RETIRE - 5'd1)});
        end
    end

    assign o_word_done = word_last;
    assign o_saturated = done;

    // P: the retire count never exceeds 20, although the register admits 31.
    always @(posedge i_clk)
        assert (retired <= MAX_RETIRE);
endmodule

// Triple-modular-redundant power-rail sequencer step counter.
// Three shadow copies of the sequencer step code are advanced independently;
// the exported step code is the bitwise majority vote of the three copies.
// prev_voted is a precedence shadow: it records the voted code as it was at
// the previous advance, so the present code must be the successor of the code
// that was observed earlier.
module tmr_rail_sequencer (
    input  wire       clk,
    input  wire       ce,        // advance / load enable; low => design idles
    input  wire       load,      // reload the sequencer with an external code
    input  wire [2:0] code_in,
    input  wire       q_start,   // opens the monitoring window
    input  wire       r_stop,    // closes the monitoring window
    output wire [2:0] voted
);

    // three shadow registers of the TMR voter
    reg [2:0] shadow_a = 3'd1;
    reg [2:0] shadow_b = 3'd1;
    reg [2:0] shadow_c = 3'd1;
    // Ring bounds of the rail ramp. The last load fixes the origin:
    // base_code is the first code of the ring and top_code the code after
    // which the sequencer wraps back to the origin. at_top is the registered
    // terminal-count flag, kept out of the voter's compare path.
    reg [2:0] base_code = 3'd1;
    reg [2:0] top_code  = 3'd0;
    reg       at_top    = 1'b0;

// Precedence shadow, split for radiation tolerance: the low two bits of the
// recorded code ripple in prev_lo, while its top bit is kept as a dual-rail
// pair whose advance is a swap of the two rails.
reg [1:0] prev_lo   = 2'd0;
reg       prev_hi_t = 1'b0;
reg       prev_hi_f = 1'b1;

    // window register: set by q_start, cleared by r_stop, reopenable
    reg       win = 1'b0;

    // bitwise majority vote
    assign voted = (shadow_a & shadow_b) | (shadow_a & shadow_c) |
                   (shadow_b & shadow_c);

// recomposed precedence code
wire [2:0] prev_voted = {prev_hi_t, prev_lo};
    // code the shadows will hold after the next advance
    wire [2:0] next_code = at_top ? base_code : voted + 3'd1;

    always @(posedge clk) begin
        if (ce) begin
            if (load) begin
                shadow_a   <= code_in;
                shadow_b   <= code_in;
                shadow_c   <= code_in;
prev_lo   <= code_in[1:0] - 2'd1;
prev_hi_t <= code_in[2] ^ (code_in[1:0] == 2'd0);
prev_hi_f <= ~(code_in[2] ^ (code_in[1:0] == 2'd0));
               base_code  <= code_in;
               top_code   <= code_in - 3'd1;
               at_top     <= 1'b0;
            end else begin
               if (at_top) begin
                   shadow_a   <= base_code;
                   shadow_b   <= base_code;
                   shadow_c   <= base_code;
               end else begin
                   shadow_a   <= shadow_a + 3'd1;
                   shadow_b   <= shadow_b + 3'd1;
                   shadow_c   <= shadow_c + 3'd1;
               end
               at_top <= (next_code == top_code);
prev_lo <= voted[1:0];
// the top bit only moves when the low part rolls over
if (prev_lo == 2'd3) begin
    prev_hi_t <= prev_hi_f;
    prev_hi_f <= prev_hi_t;
end
            end
        end
    end

    always @(posedge clk) begin
        if (r_stop)
            win <= 1'b0;
        else if (q_start)
            win <= 1'b1;
    end

    // Property: inside the monitoring window, the voted step code must be the
    // immediate successor of the code recorded earlier in prev_voted.
    always @(posedge clk)
        assert (!win || (voted == prev_voted + 3'd1));

endmodule

module histogram_sampler (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // sample-enable; low => whole histogram idles
    input  wire [1:0] i_sel,     // which bin the incoming sample lands in
    output reg  [3:0] bin0,
    output reg  [3:0] bin1,
    output reg  [3:0] bin2,
    output reg  [3:0] bin3,
    output reg  [3:0] total,
output wire       o_full,
output reg  [3:0] ce_ticks
);
    // sampling window closes after MAXS samples have been binned
    localparam [3:0] MAXS = 4'd12;

   // run-length coalescing: consecutive samples aimed at one bin are counted
   // here and folded into that bin register with a single add
   localparam [1:0] PMAX = 2'd3;

   reg [1:0] pend;      // samples staged but not yet folded into a bin
   reg [1:0] pend_sel;  // bin the staged samples belong to

    initial bin0  = 4'd0;
    initial bin1  = 4'd0;
    initial bin2  = 4'd0;
    initial bin3  = 4'd0;
    initial total = 4'd0;
   initial pend     = 2'd0;
   initial pend_sel = 2'd0;
initial ce_ticks = 4'd0;

    assign o_full = (total == MAXS);

    wire take = i_ce && (total < MAXS);
   wire same  = (i_sel == pend_sel);
   // window already shut: commit whatever is still staged on the next beat
   wire drain = i_ce && !take;
   wire fold  = (pend != 2'd0) && (drain || (take && (!same || pend == PMAX)));
   wire [2:0] fold_amt = (take && same) ? 3'd4 : {1'b0, pend};

    always @(posedge clk) begin
        if (rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 4'd0;
           pend     <= 2'd0;
           pend_sel <= 2'd0;
ce_ticks <= 4'd0;
       end else begin
           if (fold) begin
               case (pend_sel)
                   2'd0: bin0 <= bin0 + {1'b0, fold_amt};
                   2'd1: bin1 <= bin1 + {1'b0, fold_amt};
                   2'd2: bin2 <= bin2 + {1'b0, fold_amt};
                   2'd3: bin3 <= bin3 + {1'b0, fold_amt};
               endcase
           end
           if (take) begin
               pend_sel <= i_sel;
               pend     <= same ? ((pend == PMAX) ? 2'd0 : pend + 2'd1)
                                : 2'd1;
               total    <= total + 4'd1;
           end else if (drain) begin
               pend <= 2'd0;
           end
if (i_ce && ce_ticks != 4'd15)
    ce_ticks <= ce_ticks + 4'd1;
       end
    end

    // P: no single bin's occupancy can ever exceed the sampling-window size,
    // even though the 4-bit bin register could physically hold 15.
    always @(*)
        assert (bin1 <= MAXS);
endmodule

module handshake_deadline (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       start,     // upstream wants a parse burst
    input  wire       done,      // target signals completion early
    output wire       req,
    output wire       ack,
    output wire       busy_o,
    output wire       timeout
);
    // four-phase handshake: IDLE -> REQ (req rises) -> ACK (ack rises)
    //                       -> DROP (req drops) -> IDLE (ack drops)
    localparam [1:0] P_IDLE = 2'd0,
                     P_REQ  = 2'd1,
                     P_ACK  = 2'd2,
                     P_DROP = 2'd3;

    reg [1:0] phase = P_IDLE;   // handshake phase
    reg       busy  = 1'b0;     // mirrors the phase by construction
    reg [2:0] cnt   = 3'd4;     // completion deadline countdown
   reg [2:0] wait_cnt = 3'd0;  // ticks the target made us wait for ack
   reg [2:0] hold  = 3'd0;     // ack hold time still owed in the drop phase

    assign req    = (phase == P_REQ)  || (phase == P_ACK);
    assign ack    = (phase == P_ACK)  || (phase == P_DROP);
    assign busy_o = busy;

    // the deadline has expired while the engine is still engaged
    assign timeout = busy && (cnt == 3'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                P_IDLE: begin
                    if (start) begin
                        phase <= P_REQ;   // req rises
                        busy  <= 1'b1;
                    end
                end
                P_REQ: begin
                    // req may not drop here; the target must raise ack first.
                    // the deadline forces the ack phase on the last tick,
                    // so the countdown can never run through zero.
                    if (done || cnt <= 3'd1)
                        phase <= P_ACK;   // ack rises
                   else begin
                       cnt      <= cnt - 3'd1;
                       wait_cnt <= wait_cnt + 3'd1;  // log the wait
                   end
                end
                P_ACK: begin
                   // fast target: ack came back on the first tick, so there
                   // is nothing left to drain - finish without a drop phase
                   if (wait_cnt == 3'd0) begin
                       phase <= P_IDLE;
                       busy  <= 1'b0;
                       cnt   <= 3'd4;
                   end else begin
                       phase <= P_DROP;  // req drops, ack still high
                      hold  <= wait_cnt;  // hold ack as long as the target stalled us
                   end
                end
                P_DROP: begin
                   if (hold > 3'd1) begin
                       hold <= hold - 3'd1;  // ack stays high a bit longer
                   end else begin
                       phase <= P_IDLE;      // ack drops
                       busy  <= 1'b0;
                       cnt   <= 3'd4;        // rearm the deadline
                       wait_cnt <= 3'd0;     // clear the latency monitor
                       hold  <= 3'd0;
                   end
                end
            endcase
        end
    end

    // P1: the completion deadline never expires while the engine is engaged
    always @(posedge clk)
        assert (!timeout);

    // P2: while a request is outstanding the deadline is a live value
    always @(posedge clk)
        if (phase == 2'd1)
            assert (cnt >= 3'd1 && cnt <= 3'd4);

   // P3: the latency monitor never reports a wait longer than the window
   always @(posedge clk)
       if (busy) assert (wait_cnt <= 3'd3);

  // P4: the ack hold never outlasts the deadline budget
  always @(posedge clk)
      if (phase == 2'd3) assert (cnt + hold <= 3'd4);
endmodule

module chess_clock_seq_alarm (
    input  wire clk,
    input  wire i_ce,      // clock tick enable; low freezes the whole mechanism
    input  wire sym,       // observed press: 1 = white side, 0 = black side
    output reg  alarm
);
    // match-progress register for the fixed press pattern 1,0,1,1
    // (white, black, white, white) -- the blitz alarm trigger
    reg [2:0] prog;
    // shadow register: latches that the half-way progress (2 symbols) occurred
    reg       seen_half;
    // "before R" scope register: high until the alarm pattern first completes
    reg       before_alarm;
   // commit stage: the decoder's next-progress value waits one tick here
   // before it is retired into the matcher, keeping the decode path short
   reg [2:0] stg;
   reg       stg_v;       // a staged progress value is pending commit
  // black-turn tally: how many times the matcher has passed the half-way
  // point since power-up. The blitz time control also ends the game once
  // this tally reaches its limit of seven, so it feeds the alarm too.
  reg [2:0] hcnt;

    initial prog         = 3'd0;
    initial seen_half    = 1'b0;
    initial before_alarm = 1'b1;
    initial alarm        = 1'b0;
   initial stg          = 3'd0;
   initial stg_v        = 1'b0;
  initial hcnt         = 3'd0;

    reg [2:0] nxt;
   // a press is only consumed in the decode phase
   wire match = (prog == 3'd3) && sym && !stg_v;

    always @(*) begin
        case (prog)
            3'd0: nxt = sym ? 3'd1 : 3'd0;
            3'd1: nxt = sym ? 3'd1 : 3'd2;
            3'd2: nxt = sym ? 3'd3 : 3'd0;
            3'd3: nxt = sym ? 3'd0 : 3'd2;  // overlap: "10" survives
            default: nxt = 3'd0;
        endcase
    end

    always @(posedge clk) begin
        if (i_ce) begin
           if (!stg_v) begin
               // decode phase: consume the press, stage the new progress
               stg       <= nxt;
               stg_v     <= 1'b1;
               seen_half <= seen_half | (nxt == 3'd2);
              if ((nxt == 3'd2) && (hcnt != 3'd7))
                  hcnt <= hcnt + 3'd1;
              // the alarm sounds on the pattern match, and also on the press
              // that takes the black-turn tally to its limit
              alarm     <= match | ((nxt == 3'd2) && (hcnt == 3'd6));
               if (match)
                   before_alarm <= 1'b0;
           end else begin
               // commit phase: retire the staged progress into the matcher
               prog      <= stg;
               stg_v     <= 1'b0;
               alarm     <= 1'b0;
               if (stg == 3'd0)
                   seen_half <= 1'b0;   // matcher restarted from scratch
           end
        end
    end

    // Precedence, in the scope before the alarm has ever fired:
    // three-quarter progress can only be observed if half progress happened earlier.
    always @(posedge clk)
        assert (!before_alarm || (prog != 3'd3) || seen_half);

   // Tally accounting, in the scope before the alarm has ever fired:
   // three-quarter progress cannot be on record while the black-turn tally
   // is still empty, because reaching it costs one black press.
   always @(posedge clk)
       assert (!before_alarm || (prog != 3'd3) || (hcnt != 3'd0));
endmodule

// Sliding-window grant rate limiter: an 8-cycle shift register of recent
// grants plus an occupancy counter that mirrors its population count.
// A grant may only be issued if no grant occurred in the last two cycles,
// which spaces grants at least 3 cycles apart and therefore caps the
// occupancy of the 8-deep window at 3, far below the 4-bit counter range.
// Grants now ping-pong between two sinks, each with its own 8-cycle window;
// the spacing rule is held in one cooldown counter shared by both sinks.
// The sink-A occupancy add is retimed to shorten the accumulator path: the +1
// from a fresh grant is staged one cycle in ones_pend, so the accumulator holds
// only the aged part of the window and picks the staged carry up next cycle.
module grant_window_limiter (
    input  wire       clk,
    input  wire       ce,      // idle when low: no state changes
    input  wire       req,
    output wire       grant,
    output reg  [7:0] win,
    output reg  [3:0] ones
);

    reg armed = 1'b0;   // sticky: set the first time a grant is issued
    reg pv    = 1'b0;   // past-valid
    reg [7:0] win_b = 8'b0000_0000;  // sink B's window, same 8-cycle depth
    reg [1:0] cool  = 2'd0;          // shared spacing cooldown, loaded by either sink
    reg       sel   = 1'b0;          // ping-pong pointer: 0 = next grant goes to sink A
    reg       ones_pend = 1'b0;      // staged +1 for the occupancy accumulator

    initial win  = 8'b0000_0000;
    initial ones = 4'd0;

    // spacing rule, now carried by the shared cooldown: a grant to either sink
    // blocks the shared issue path for the following two cycles
    wire allow = (cool == 2'd0);
    wire g     = ce && req && allow;
    wire to_b  = sel;                // this grant is tagged for sink B

    assign grant = g;

    always @(posedge clk) begin
        if (ce) begin
            win   <= {win[6:0], g && !to_b};
            win_b <= {win_b[6:0], g && to_b};
            ones_pend <= g && !to_b;
            ones      <= ones + (ones_pend ? 4'd1 : 4'd0) - (win[7] ? 4'd1 : 4'd0);
            cool  <= g ? 2'd2 : ((cool == 2'd0) ? 2'd0 : cool - 2'd1);
            if (g)
                sel <= ~sel;
        end
        if (g)
            armed <= 1'b1;
        pv <= 1'b1;
    end

    // Bounded existence, at most 3, in the scope after the first grant.
    always @(posedge clk)
        if (pv && armed)
            assert ((ones <= 4'd3) && ($past(ones) <= 4'd3));

endmodule

module skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,          // idle condition: en low freezes all state
    input  wire       in_valid,
    input  wire [7:0] in_data,
    input  wire       out_ready,
    output wire       in_ready,
    output reg        out_valid,
    output reg  [7:0] out_data
);
    // skid buffer: only meaningful while the stall flag skid_valid is up
    reg        skid_valid;
    reg  [7:0] skid_data;

   // input capture register: a word that arrives while the output register
   // is stalled lands here first and reaches the skid slot next cycle
   reg        cap_valid;
   reg  [7:0] cap_data;

    // redundant occupancy counter (3 bits wide, but only 0..2 are real)
    reg  [2:0] occ;

   // in-flight ledger: two free-running event counters, one tick per
   // hand-off on each side of the stage. Their difference is the number of
   // words the stage still owes downstream, and it is the credit budget
   // used to throttle the upstream interface.
   reg  [3:0] n_in;
   reg  [3:0] n_out;

    // sticky arm: set the first time a word is actually accepted
    reg        armed;

    initial begin
        out_valid  = 1'b0;
        out_data   = 8'h00;
        skid_valid = 1'b0;
        skid_data  = 8'h00;
       cap_valid  = 1'b0;
       cap_data   = 8'h00;
        occ        = 3'd0;
       n_in       = 4'd0;
       n_out      = 4'd0;
        armed      = 1'b0;
    end


   // credit accounting: at most two words may be in flight at once
   wire [3:0] level     = n_in - n_out;
   wire       no_credit = (level >= 4'd2);

   assign in_ready = !no_credit && !skid_valid;

    wire accept = en && in_valid && in_ready;
    wire drain  = en && out_valid && out_ready;

    always @(posedge clk) begin
        if (rst) begin
            out_valid  <= 1'b0;
            out_data   <= 8'h00;
            skid_valid <= 1'b0;
            skid_data  <= 8'h00;
           cap_valid  <= 1'b0;
           cap_data   <= 8'h00;
            occ        <= 3'd0;
           n_in       <= 4'd0;
           n_out      <= 4'd0;
            armed      <= 1'b0;
        end else if (en) begin
            // output register / skid promotion
            if (!out_valid || out_ready) begin
                if (skid_valid) begin
                    out_data   <= skid_data;
                    out_valid  <= 1'b1;
                    skid_valid <= 1'b0;
               end else if (cap_valid) begin
                   out_data  <= cap_data;
                   out_valid <= 1'b1;
                   cap_valid <= 1'b0;
               end else if (accept) begin
                    out_data  <= in_data;
                    out_valid <= 1'b1;
                end else begin
                    out_valid <= 1'b0;
                end
            end else begin
               // downstream stalled: promote the capture register into the
               // skid slot, otherwise capture the arriving word
               if (cap_valid && !skid_valid) begin
                   skid_data  <= cap_data;
                    skid_valid <= 1'b1;
                   cap_valid  <= 1'b0;
              end else if (accept) begin
                   cap_data  <= in_data;
                   cap_valid <= 1'b1;
                end
            end

            // occupancy bookkeeping, tracked independently of the flags
            occ <= occ + (accept ? 3'd1 : 3'd0) - (drain ? 3'd1 : 3'd0);

           // ledger ticks: one side per hand-off, wrapping freely
           n_in  <= n_in  + (accept ? 4'd1 : 4'd0);
           n_out <= n_out + (drain  ? 4'd1 : 4'd0);

            if (accept) armed <= 1'b1;
        end
    end

    // P, part 1: once the stage has ever accepted a word, occupancy never
    // exceeds 2 even though the counter is 3 bits wide
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd2);

    // P, part 2: once armed, whenever the skid slot holds a meaningful word the
    // stage is occupancy-saturated at exactly 2
    always @(posedge clk)
        if (armed)
            assert (!skid_valid || occ == 3'd2);
endmodule

module token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle condition: nothing moves when low
    input  wire       req,
    output reg        grant_q,
    output reg [3:0]  tokens
);
    localparam [3:0] BURST  = 4'd12; // bucket cap
    localparam [3:0] REFILL = 4'd3;  // tokens added per timer tick
    localparam [2:0] PERIOD = 3'd4;  // refill timer top
   localparam [3:0] SOFT    = 4'd8; // tokens kept in the live bucket
   localparam [3:0] RESVMAX = 4'd6; // reserve pool cap

    reg [2:0] timer;
    reg       saw_refill;            // shadow: a refill tick has occurred
   // Overflow reserve: refill above SOFT is parked here instead of being
   // thrown away by the clamp, and trickles back one token at a time when
   // the live bucket runs dry.
   reg [3:0] resv;

   // Refill commit pipeline: the bucket adder/clamp is registered, so the
   // token target computed at a timer tick is applied four cycles later.
   // Layout of each stage: {valid, precomputed token target}.
   reg [4:0] rf_s1, rf_s2, rf_s3, rf_s4;

    wire       tick     = (timer == PERIOD);
    wire       do_grant = ce && req && (tokens != 4'd0);
    wire [4:0] sum      = {1'b0, tokens} + {1'b0, REFILL};
    wire [3:0] refilled = (sum > {1'b0, BURST}) ? BURST : sum[3:0];
   wire       commit   = rf_s4[4];
   wire [3:0] target   = rf_s4[3:0];
  wire [3:0] eff_target = (target > SOFT) ? SOFT : target;
  wire [3:0] excess     = (target > SOFT) ? (target - SOFT) : 4'd0;
  wire [4:0] resv_sum   = {1'b0, resv} + {1'b0, excess};
  wire       drain      = !commit && (tokens == 4'd0) && (resv != 4'd0);

    initial begin
        timer      = 3'd0;
        tokens     = 4'd0;
        saw_refill = 1'b0;
       resv       = 4'd0;
        grant_q    = 1'b0;
       rf_s1      = 5'd0;
       rf_s2      = 5'd0;
       rf_s3      = 5'd0;
       rf_s4      = 5'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            timer      <= 3'd0;
            tokens     <= 4'd0;
            saw_refill <= 1'b0;
           resv       <= 4'd0;
            grant_q    <= 1'b0;
           rf_s1      <= 5'd0;
           rf_s2      <= 5'd0;
           rf_s3      <= 5'd0;
           rf_s4      <= 5'd0;
        end else if (ce) begin
            timer   <= tick ? 3'd0 : (timer + 3'd1);
            grant_q <= do_grant;

           // stage the refill: capture the clamped target at the tick and
           // walk it down the pipeline, one stage per enabled cycle
           rf_s1 <= {tick, refilled};
           rf_s2 <= rf_s1;
           rf_s3 <= rf_s2;
           rf_s4 <= rf_s3;

            if (tick)
                saw_refill <= 1'b1;

           case ({commit, do_grant})
              2'b10:   tokens <= eff_target;
                2'b01:   tokens <= tokens - 4'd1;
              2'b11:   tokens <= (eff_target == 4'd0) ? 4'd0 : (eff_target - 4'd1);
               default: tokens <= drain ? 4'd1 : tokens;
            endcase

          // reserve bookkeeping: soak up the clamped surplus, or hand one
          // token back to the live bucket when it has emptied out
          if (commit)
              resv <= (resv_sum > {1'b0, RESVMAX}) ? RESVMAX : resv_sum[3:0];
          else if (drain)
              resv <= resv - 4'd1;
        end
    end

    // Precedence: a registered grant can only be observed if a refill tick
    // was recorded earlier in the shadow bit.
    always @(posedge clk)
        if (grant_q)
            assert (saw_refill);

endmodule

// Transaction scoreboard with a completion deadline countdown.
// issued/retired are wrapping transaction counters; outst is the occupancy
// of the issue window (WINDOW deep). Every outstanding transaction is forced
// to retire before its RELOAD-cycle deadline countdown reaches zero.
module scoreboard_deadline (
    input  wire clk,
    input  wire ce,      // idle condition: ce low freezes the scoreboard
    input  wire issue,
    input  wire retire,
    output wire busy
);
    localparam [2:0] WINDOW = 3'd4;
    localparam [2:0] RELOAD = 3'd5;
    localparam [1:0] QDEPTH = 2'd2;   // staging queue in front of the window

    reg [3:0] issued;
    reg [3:0] retired;
    reg [2:0] outst;    // outstanding transactions = issued - retired
    reg [1:0] queued;   // accepted, still waiting for a free window slot
   reg [1:0] qb;       // class-B staging queue sharing the same window
   reg       rr;       // round-robin pointer for the freed window slot
    reg [2:0] timer;    // deadline countdown for the oldest outstanding item
    reg       armed;    // sticky: set the first time a transaction is accepted
    reg       pv;       // past valid

    initial begin
        issued  = 4'd0;
        retired = 4'd0;
        outst   = 3'd0;
        queued  = 2'd0;
       qb      = 2'd0;
       rr      = 1'b0;
        timer   = 3'd0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

   assign busy = (outst != 3'd0) || (queued != 2'd0) || (qb != 2'd0);

    // deadline flag: the countdown has run out
    wire expired = (timer == 3'd0);

    // the design completes a transaction itself when the deadline is imminent
    wire force_ret = (outst != 3'd0) && (timer == 3'd1);

   wire [3:0] total = {1'b0, outst} + {2'b0, queued} + {2'b0, qb};

   // accept while the window plus both staging queues still have capacity
   wire do_issue  = ce && issue && (total < ({1'b0, WINDOW} + {2'b0, QDEPTH} + {2'b0, QDEPTH}));
    wire do_retire = ce && (outst != 3'd0) && (retire || force_ret);

    // a window slot is free, or is being freed by this cycle's retirement
    wire slot_free = (outst < WINDOW) || do_retire;
   // staged transactions are older than an incoming one, so they go first;
   // the two classes take turns for the slot the window frees up
   wire admit_a = ce && (queued != 2'd0) && slot_free && (!rr || (qb == 2'd0));
   wire admit_b = ce && (qb != 2'd0) && slot_free && !admit_a;
   wire admit   = admit_a || admit_b;
   wire direct  = do_issue && slot_free && !admit;
   wire enq     = do_issue && !direct;
   // a fresh transaction joins the shorter of the two queues
   wire enq_a   = enq && (queued <= qb);
   wire enq_b   = enq && !enq_a;

    wire [2:0] outst_n  = outst + ((admit || direct) ? 3'd1 : 3'd0)
                                - (do_retire ? 3'd1 : 3'd0);
   wire [1:0] queued_n = queued + (enq_a ? 2'd1 : 2'd0)
                                - (admit_a ? 2'd1 : 2'd0);
   wire [1:0] qb_n     = qb + (enq_b ? 2'd1 : 2'd0)
                            - (admit_b ? 2'd1 : 2'd0);

    always @(posedge clk) begin
        pv <= 1'b1;

        if (do_issue) begin
            armed  <= 1'b1;
            issued <= issued + 4'd1;
        end

        if (do_retire)
            retired <= retired + 4'd1;

        outst <= outst_n;
       queued <= queued_n;
       qb     <= qb_n;
       if (admit) rr <= admit_a;

        if (do_issue || do_retire) begin
            // any scoreboard event restarts (or clears) the deadline
           if (outst_n == 3'd0 && queued_n == 2'd0 && qb_n == 2'd0) timer <= 3'd0;
            else                 timer <= RELOAD;
        end else if (ce && (outst != 3'd0)) begin
            timer <= timer - 3'd1;
        end
    end

    // Bounded response, safety form, in no-change style, scoped after arming:
    // once a transaction has been accepted, whenever the outstanding count did
    // not change and work is still outstanding, the deadline flag must not
    // change either (i.e. the countdown cannot expire under an outstanding
    // request).
    always @(posedge clk) begin
        if (pv && armed && (outst != 3'd0) && $stable(outst))
            assert ($stable(expired));
    end
endmodule

module credit_ledger (
    input  wire        clk,
    input  wire        i_ce,
    output wire [4:0]  o_gray,
    output wire        o_drained
);
// up counter and the credit pool stepped by the same enable; the pool is
// split into a reserve tranche and a main balance, and up + pool == 20
    reg [4:0] up;
    reg [4:0] dn;
// reserve tranche of the batch: returning credits are charged here first
reg [3:0] resv;

    // shadow register: records that the up counter has already reached 10
    reg       mark;

    // "before R" scope: starts high, cleared the first time the ledger drains
    reg       before_done;
    // ledger counters: one tick per credit handed out, one per credit back
    reg [4:0] n_iss;
    reg [4:0] n_ret;

    initial up          = 5'd0;
initial dn          = 5'd12;
initial resv        = 4'd8;
    initial mark        = 1'b0;
    initial before_done = 1'b1;
    initial n_iss       = 5'd0;
    initial n_ret       = 5'd0;

    always @(posedge clk) begin
        if (i_ce) begin
            if (dn == 5'd0) begin
                before_done <= 1'b0;   // the drained event has been observed
                up          <= 5'd0;   // recharge with a fresh batch of 20
dn          <= 5'd12;
resv        <= 4'd8;   // fresh batch: reserve tranche refilled
                mark        <= 1'b0;   // new batch: halfway not passed yet
            end else if (n_iss == n_ret) begin
                // nothing outstanding: hand a credit to the consumer
                up    <= up + 5'd1;
                mark  <= mark | (up == 5'd9);
                n_iss <= n_iss + 5'd1;
            end else begin
// the outstanding credit returns: charge the reserve tranche first and
// only fall back on the main balance once the tranche is dry
if (resv != 4'd0)
    resv <= resv - 4'd1;
else
    dn   <= dn - 5'd1;
                n_ret <= n_ret + 5'd1;
            end
        end
    end

    // gray view of the issue pointer (clock-domain-crossing flavour)
    assign o_gray    = n_iss ^ (n_iss >> 1);
assign o_drained = (dn == 5'd0) && (resv == 4'd0) && (n_iss == n_ret);

    // Property: before the ledger has ever drained, seeing fewer than ten
    // credits left means the up counter must already have passed ten.
    always @(*)
        if (before_done && (dn <= 5'd9))
            assert (mark);
endmodule

module fetch_credit_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,        // idle condition: when low, nothing moves
    input  wire       fetch,     // issue an instruction into the fetch queue
    input  wire       retire,    // instruction leaves the queue
    output reg  [3:0] used,      // up counter: occupancy of the fetch queue
    output reg  [3:0] credits,   // down counter: remaining free slots
    output wire       can_fetch
);
    // queue depth is 12, but both counters are 4 bits wide (0..15)
    localparam [3:0] DEPTH = 4'd12;

    // a retire frees a queue slot right away, but the credit itself only
    // reaches the free pool a cycle later, through this return stage
    reg        ret_credit;

   // an accepted fetch is registered in the allocate stage; it shows up
   // in the occupancy counter on the following cycle
   reg        alloc_pend;


    initial used    = 4'd0;
    initial credits = DEPTH;
    initial ret_credit = 1'b0;
   initial alloc_pend = 1'b0;

    assign can_fetch = (credits != 4'd0);

    wire fetch_go  = fetch && !retire && (credits != 4'd0);
    wire retire_go = retire && !fetch && (used != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            used    <= 4'd0;
            credits <= DEPTH;
            ret_credit <= 1'b0;
           alloc_pend <= 1'b0;
        end else if (en) begin
           // occupancy reflects the allocate stage, one cycle behind the grant
           if (alloc_pend && !retire_go)
                used <= used + 4'd1;
           else if (!alloc_pend && retire_go)
                used <= used - 4'd1;

            // the free pool gives up a slot on fetch, and only gets one
            // back when a returning credit pops out of the return stage
            if (fetch_go && !ret_credit)
                credits <= credits - 4'd1;
            else if (!fetch_go && ret_credit)
                credits <= credits + 4'd1;

            // a retire hands its credit to the return stage
            ret_credit <= retire_go;
           // the grant hands its slot to the allocate stage
           alloc_pend <= fetch_go;
            // simultaneous fetch+retire: slot handed straight over
        end
    end

    // P (two assertions, global scope, bounded existence at most 12):
    // neither counter can ever exceed the queue depth, which is strictly
    // smaller than what their 4-bit width admits.
    always @(posedge clk) begin
        assert (used <= DEPTH);
        assert (credits <= DEPTH);
    end
endmodule

module credit_pool (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // step enable: low leaves all state unchanged
    input  wire i_take,    // 1 = take a credit, 0 = give one back
    output wire o_full,
    output wire o_empty,
    output wire [3:0] o_used,
    output wire [3:0] o_avail
);
    localparam [3:0] CAP = 4'd12;

    // up counter: credits handed out
    reg [3:0] used;
    // down counter: credits still on the shelf
    reg [3:0] avail;
   // per-lane outstanding credits: two clients share the one shelf
   reg [3:0] out_a;
   reg [3:0] out_b;
  // lane A parks its first two credits in a private reserve slot so the
  // common case never touches the lane counter
  reg [1:0] rsv_a;
   // round-robin pointer: whose request is charged next
   reg       turn;
   // registered arbiter grant: the shelf port moves one credit per cycle
   reg       gnt_a;
   reg       gnt_b;
   reg       gnt_take;

    initial used  = 4'd0;
    initial avail = CAP;
   initial out_a = 4'd0;
   initial out_b = 4'd0;
  initial rsv_a = 2'd0;
   initial turn  = 1'b0;
   initial gnt_a = 1'b0;
   initial gnt_b = 1'b0;
   initial gnt_take = 1'b0;

  wire       lane_nz  = turn ? (out_b != 4'd0) : (out_a != 4'd0 || rsv_a != 2'd0);
   wire       arb_idle = !gnt_a && !gnt_b;

   // a request is only latched while the shared shelf port is free
   wire accept = i_ce && arb_idle &&
                (i_take ? (used != CAP) : lane_nz);

   // commit of the move the arbiter granted last cycle
   wire take_fire = (gnt_a || gnt_b) &&  gnt_take;
   wire give_fire = (gnt_a || gnt_b) && !gnt_take;

  // lane A fills the reserve before its counter and drains it first
  wire       a_fill  = gnt_a &&  gnt_take && (rsv_a != 2'd2);
  wire       a_drain = gnt_a && !gnt_take && (rsv_a != 2'd0);
  wire [1:0] rsv_a_nxt = a_fill  ? rsv_a + 2'd1 :
                         a_drain ? rsv_a - 2'd1 : rsv_a;
  wire [3:0] out_a_nxt = (gnt_a &&  gnt_take && !a_fill)  ? out_a + 4'd1 :
                         (gnt_a && !gnt_take && !a_drain) ? out_a - 4'd1 : out_a;
   wire [3:0] out_b_nxt = gnt_b ? (gnt_take ? out_b + 4'd1 : out_b - 4'd1) : out_b;

    always @(posedge clk) begin
        if (rst) begin
            used  <= 4'd0;
            avail <= CAP;
           out_a <= 4'd0;
           out_b <= 4'd0;
          rsv_a <= 2'd0;
           turn  <= 1'b0;
           gnt_a <= 1'b0;
           gnt_b <= 1'b0;
           gnt_take <= 1'b0;
       end else if (i_ce) begin
           // stage 1: arbitrate this cycle's request
           gnt_a    <= accept && !turn;
           gnt_b    <= accept &&  turn;
           gnt_take <= i_take;
           if (accept)
               turn <= ~turn;

           // stage 2: retire the move granted last cycle
           out_a <= out_a_nxt;
           out_b <= out_b_nxt;
          rsv_a <= rsv_a_nxt;
          used  <= out_a_nxt + rsv_a_nxt + out_b_nxt;   // running total over both lanes
           if (take_fire)
               avail <= avail - 4'd1;        // stepped down, single shelf port
           else if (give_fire)
               avail <= avail + 4'd1;
       end
    end

    assign o_full  = (avail == 4'd0);
    assign o_empty = (used  == 4'd0);
    assign o_used  = used;
    assign o_avail = avail;

    // P: whenever the shelf is empty, every credit of the pool is out on loan
    always @(posedge clk)
        if (avail == 4'd0)
            assert (used == CAP);
endmodule

module wdog_saturate (
    input wire i_clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_kick,
    input wire i_ack,
    output wire o_reset,
    output wire [3:0] o_elapsed,
    output wire [3:0] o_remain
);
    // Watchdog window: TIMEOUT ticks without a kick latches a system reset.
    localparam [3:0] TIMEOUT = 4'd12;

    // Saturating up-counter of ticks since the last kick.  It clamps at
    // TIMEOUT (12) even though the 4-bit register admits values up to 15.
    reg [3:0] cnt;
    // Mirror: ticks of grace remaining, saturating down at zero.
    reg [3:0] rem;
    // Latched reset request, cleared only by an acknowledge.
    reg       latched;

   // Margin monitor: low-water mark of the grace window since the
   // watchdog was last armed.  Zero means the window has fully closed.
   reg [3:0] slack;

   // Update stage: the tick arithmetic is registered for one cycle before
   // it commits, so an update issued on a ce cycle lands on the cycle
   // after it was issued.
   reg [3:0] cnt_stg;
   reg [3:0] rem_stg;
   reg       stg_vld;

   // Forwarding: a pending stage value is newer than the committed
   // register, so back-to-back ticks are computed from the stage.
   wire [3:0] cnt_eff = stg_vld ? cnt_stg : cnt;
   wire [3:0] rem_eff = stg_vld ? rem_stg : rem;

  // A kick arriving after the window has already closed is ignored: the
  // reset request stands until software acknowledges it.
  wire kick_ok = i_kick && (slack != 4'd0);

    initial cnt     = 4'd0;
    initial rem     = TIMEOUT;
    initial latched = 1'b0;
   initial cnt_stg = 4'd0;
   initial rem_stg = TIMEOUT;
   initial stg_vld = 1'b0;
  initial slack   = TIMEOUT;

    always @(posedge i_clk) begin
        if (i_rst) begin
            cnt     <= 4'd0;
            rem     <= TIMEOUT;
            latched <= 1'b0;
           cnt_stg <= 4'd0;
           rem_stg <= TIMEOUT;
           stg_vld <= 1'b0;
          slack   <= TIMEOUT;
       end else begin
           // Drain the stage: the in-flight update commits one cycle after
           // it was issued, whether or not a new tick arrives.
           if (stg_vld) begin
               cnt <= cnt_stg;
               rem <= rem_stg;
              slack <= (rem_stg == TIMEOUT) ? TIMEOUT :
                       (rem_stg < slack)    ? rem_stg : slack;
           end
           stg_vld <= 1'b0;

           if (i_ce) begin
           stg_vld <= 1'b1;
          if (kick_ok) begin
               cnt_stg <= 4'd0;
               rem_stg <= TIMEOUT;
           end else begin
               cnt_stg <= (cnt_eff < TIMEOUT) ? cnt_eff + 4'd1 : cnt_eff;
               rem_stg <= (rem_eff != 4'd0) ? rem_eff - 4'd1 : rem_eff;
           end

           if (i_ack) begin
               latched <= 1'b0;
               // The acknowledge also re-arms the window, issued through
               // the same stage so the commit stays single-sourced.
               cnt_stg <= 4'd0;
               rem_stg <= TIMEOUT;
           end
          else if (!kick_ok && (rem_eff == 4'd1))
                latched <= 1'b1;
        end
       end
    end

    assign o_reset   = latched;
    assign o_elapsed = cnt;
    assign o_remain  = rem;

    // Universality, global scope: whenever the grace window has run out, the
    // elapsed-tick counter must be sitting on its saturation value.
    always @(posedge i_clk)
        if (rem == 4'd0)
            assert (cnt == TIMEOUT);

   // Margin report consistency: the ticks already burned plus the deepest
   // margin the monitor has recorded cannot exceed the whole window.
   always @(posedge i_clk)
       assert ((cnt + slack) <= 5'd12);
endmodule

module pwm_precedence (
    input  wire       clk,
    input  wire       ce,
    input  wire       load,
    input  wire [3:0] duty_in,
    output wire       o_pwm,
    output wire       o_period_start
);
    // 12-cycle PWM period: counter runs 0..11 and reloads.
    localparam [3:0] PERIOD_M1 = 4'd11;

    reg [3:0] cnt;       // period counter
    reg [3:0] duty_act;  // active duty, latched at period start
    reg [3:0] duty_pend; // pending (requested) duty
    reg [3:0] hi_left;   // shadow: high-cycle budget recorded at last period start
    reg [3:0] duty_stg;  // prefetched duty feeding the compare path
   reg [3:0] req_val;   // duty value captured from the request bus
   reg       req_vld;   // captured request still waiting to be committed

    initial cnt       = 4'd0;
    initial duty_act  = 4'd0;
    initial duty_pend = 4'd0;
    initial hi_left   = 4'd0;
    initial duty_stg  = 4'd0;
   initial req_val   = 4'd0;
   initial req_vld   = 1'b0;

    wire wrap = (cnt == PERIOD_M1);
    wire prefetch = (cnt == PERIOD_M1 - 4'd1);
   wire prefetch2 = (cnt == PERIOD_M1 - 4'd2);
   // a captured request only reaches duty_pend one cycle after it is
   // accepted, so the accept window has to close three cycles before the
   // boundary for the duty pipeline to be stable across the reload
   wire duty_hold = prefetch2 || prefetch || wrap;

    // seeded construct: output high exactly while the counter is below the duty
    assign o_pwm          = (cnt < duty_act);
    assign o_period_start = (cnt == 4'd0);

    always @(posedge clk) begin
        if (ce) begin
            // prefetch one cycle ahead of the boundary so the cnt<duty
            // compare gets a full cycle of setup on the new duty value
            if (prefetch)
                duty_stg <= duty_pend;
            if (wrap) begin
                // new period: both the active duty and the high budget are
                // (re)loaded from the pending duty requested earlier
                cnt      <= 4'd0;
    duty_act <= duty_stg;
                hi_left  <= duty_pend;
            end else begin
                cnt <= cnt + 4'd1;
                if (hi_left != 4'd0)
                    hi_left <= hi_left - 4'd1;
            end
           // request bus is registered: capture on the accepted cycle and
           // commit into the pending duty on the following cycle
           if (load && !duty_hold) begin
               req_val <= duty_in;
               req_vld <= 1'b1;
           end else begin
               req_vld <= 1'b0;
           end
           if (req_vld)
               duty_pend <= req_val;
        end
    end

    // past-valid register so cycle zero is not judged
    reg pv = 0;
    always @(posedge clk)
        pv <= 1'b1;

    // Precedence: if the output was driven high last cycle, then a nonzero
    // high-cycle budget (recorded at the earlier period start) must still have
    // been available at that time.
    always @(posedge clk)
        if (pv && $past(o_pwm))
            assert ($past(hi_left) != 4'd0);
endmodule

module alu_result_fifo (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] a,
    input  wire [7:0] b,
    input  wire [1:0] op,
    output reg  [7:0] o_data,
    output reg        o_zero,
    output reg        o_carry,
    output wire       full,
    output wire       empty,
output reg  [3:0] count,
output reg  [7:0] o_push_tally
);
    // ---- FIFO state: separate write/read pointers plus occupancy counter ----
    reg [2:0] wptr, rptr;
    reg [8:0] mem [0:7];   // {carry, result} slices
   // one-deep input staging register: the ALU result is captured here and
   // written into the array on the following enabled cycle
   reg        stg_v;
   reg  [8:0] stg_d;
    integer i;

    initial begin
        wptr    = 3'd0;
        rptr    = 3'd0;
        count   = 4'd0;
        o_data  = 8'h00;
        o_zero  = 1'b1;
        o_carry = 1'b0;
       stg_v   = 1'b0;
       stg_d   = 9'd0;
o_push_tally = 8'h00;
        for (i = 0; i < 8; i = i + 1) mem[i] = 9'd0;
    end

    // ---- 8-bit ALU slice: add, subtract, and, or (carry out in bit 8) ----
    wire [8:0] w_sum = {1'b0, a} + {1'b0, b};
    wire [8:0] w_dif = {1'b0, a} - {1'b0, b};
    reg  [8:0] alu;
    always @(*) begin
        case (op)
            2'b00:   alu = w_sum;
            2'b01:   alu = w_dif;
            2'b10:   alu = {1'b0, a & b};
            default: alu = {1'b0, a | b};
        endcase
    end

    // ---- full/empty derived from the POINTERS, not from the counter ----
   wire [3:0] w_occ = {1'b0, (wptr - rptr)} + {3'b0, stg_v};
   assign full  = (w_occ == 4'd5);
    assign empty = (wptr == rptr);

    wire do_push = i_ce && push && !full;
    wire do_pop  = i_ce && pop  && !empty;
   // the staging slot retires into the array whenever the array has room
   wire do_drain = i_ce && stg_v && ((wptr - rptr) != 3'd5);

    always @(posedge clk) begin
       if (do_drain) begin
           mem[wptr] <= stg_d;
           wptr      <= wptr + 3'd1;
       end
       if (do_push) begin
           stg_d <= alu;
           stg_v <= 1'b1;
       end else if (do_drain) begin
           stg_v <= 1'b0;
       end
        if (do_pop) begin
            o_data  <= mem[rptr][7:0];
            o_carry <= mem[rptr][8];
            o_zero  <= (mem[rptr][7:0] == 8'h00);
            rptr    <= rptr + 3'd1;
        end
        if (do_push && !do_pop)
            count <= count + 4'd1;
        else if (!do_push && do_pop)
            count <= count - 4'd1;
        else
            count <= count;
if (do_push)
    o_push_tally <= o_push_tally + 8'd1;
else if (do_pop)
    o_push_tally <= {o_push_tally[6:0], o_push_tally[7]};
    end

    // P: occupancy never exceeds the depth of 5, though the register holds 15
    always @(*) assert (count <= 4'd5);
endmodule

module dma_burst_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // engine clock-enable / idle when low
    input  wire       i_start,   // Q: opens the transfer window
    input  wire [3:0] i_len,     // burst length in beats
    input  wire       i_ack,     // R: closes the transfer window
    output wire       o_busy,
output wire       o_drained,
output reg  [3:0] o_ack_cnt
);

    // beats-remaining counter and the two status flags derived from it
    reg [3:0] beats_left;
    reg       busy;
    reg       drained;

    // window register: set by a new burst (Q), cleared by the ack (R)
    reg       win;

    // commit-stage register: the next beat count is held here for one cycle
    // before it is written into the beats-remaining counter
    reg [3:0] stg_beats;
    reg       stg_vld;

   // ack pulse counter (status only, unrelated to the burst window)
   reg       ack_seen;

    // forwarded count: the in-flight value whenever a commit is pending
    wire [3:0] beats_cur = stg_vld ? stg_beats : beats_left;


    initial beats_left = 4'd0;
    initial busy       = 1'b0;
    initial drained    = 1'b1;
    initial win        = 1'b0;
    initial stg_beats  = 4'd0;
    initial stg_vld    = 1'b0;
   initial ack_seen   = 1'b0;
   initial o_ack_cnt  = 4'd0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            busy       <= 1'b0;
            drained    <= 1'b1;
            win        <= 1'b0;
            stg_beats  <= 4'd0;
            stg_vld    <= 1'b0;
           ack_seen   <= 1'b0;
           o_ack_cnt  <= 4'd0;
        end else if (i_ce) begin
            // commit stage: the registered count reaches the counter
            if (stg_vld) begin
                beats_left <= stg_beats;
                stg_vld    <= 1'b0;
            end
            // issue stage: a descriptor load or a beat retire posts the new
            // status flags now and hands the count to the commit stage
            if (i_start && !busy) begin
                // load a new burst descriptor and open the window
                stg_beats  <= i_len;
                stg_vld    <= 1'b1;
                busy       <= (i_len != 4'd0);
                drained    <= (i_len == 4'd0);
                win        <= 1'b1;
            end else if (busy) begin
                // retire one beat off the forwarded count
                stg_beats  <= beats_cur - 4'd1;
                stg_vld    <= 1'b1;
                busy       <= (beats_cur != 4'd1);
                drained    <= (beats_cur <= 4'd1);
                if (i_ack)
                    win <= 1'b0;
            end else if (i_ack) begin
                // close the window between transfers
                win <= 1'b0;
            end
           // count rising edges of the ack input
           ack_seen <= i_ack;
           if (i_ack && !ack_seen)
               o_ack_cnt <= o_ack_cnt + 4'd1;
        end
    end

    assign o_busy    = busy;
    assign o_drained = drained;

    // P: inside an open transfer window the engine is never simultaneously
    // reporting "busy" and "drained".
    always @(posedge i_clk)
        if (win)
            assert (!(busy && drained));

endmodule

module credit_rr_arbiter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire [3:0] req,       // four requesters
    input  wire       ret,       // consumer returns one credit
    output reg  [1:0] rr_ptr,    // rotating priority pointer
    output reg  [3:0] grant,     // one-hot grant
    output reg  [3:0] credits,   // credits held by the producer
    output reg  [3:0] outstanding // credits in flight at the consumer
);
    localparam [3:0] TOTAL = 4'd8;

   // credits parked against the burst currently in flight
   reg [1:0] escrow;

  // a return occupies the return path for one cycle before it lands
  reg       ret_q;
  reg [3:0] ret_amt;

    initial rr_ptr      = 2'd0;
    initial grant       = 4'b0000;
    initial credits     = TOTAL;
    initial outstanding = 4'd0;
   initial escrow      = 2'd0;
  initial ret_q       = 1'b0;
  initial ret_amt     = 4'd0;

    // rotating priority selection: first requester at or after rr_ptr
    wire [1:0] idx = req[rr_ptr]          ? rr_ptr          :
                     req[rr_ptr + 2'd1]   ? rr_ptr + 2'd1   :
                     req[rr_ptr + 2'd2]   ? rr_ptr + 2'd2   :
                                            rr_ptr + 2'd3;

   // at burst start one credit per other waiting requester is parked in
   // escrow, so a burst that has been admitted can always be drained
   wire [3:0] others = req & ~(4'b0001 << idx);
   wire [1:0] resv   = {1'b0, others[0]} + {1'b0, others[1]} +
                       {1'b0, others[2]} + {1'b0, others[3]};
   wire       burst_start = (outstanding == 4'd0);
   wire [3:0] need        = burst_start ? (4'd1 + {2'b00, resv}) : 4'd1;
   wire have_credit = (credits >= need);
    wire any_req     = |req;

    // a grant spends one credit; it becomes outstanding until returned
   // a return is captured one cycle and applied the next
   wire ret_start = i_ce && ret && !ret_q && (outstanding != 4'd0);
   wire ret_done  = i_ce && ret_q;
   // the return path has priority; grants stall while it is busy
   wire do_grant  = i_ce && have_credit && any_req && !ret_q && !ret_start;

    always @(posedge clk) begin
        if (rst) begin
            rr_ptr      <= 2'd0;
            grant       <= 4'b0000;
            credits     <= TOTAL;
            outstanding <= 4'd0;
           escrow      <= 2'd0;
           ret_q       <= 1'b0;
           ret_amt     <= 4'd0;
        end else if (i_ce) begin
            grant <= do_grant ? (4'b0001 << idx) : 4'b0000;
            if (do_grant)
                rr_ptr <= idx + 2'd1;

           if (do_grant) begin
               if (burst_start) begin
                   credits <= credits - 4'd1 - {2'b00, resv};
                   escrow  <= resv;
               end else begin
                   credits <= credits - 4'd1;
               end
                outstanding <= outstanding + 4'd1;
           end else if (ret_start) begin
               ret_q   <= 1'b1;
               ret_amt <= (outstanding == 4'd1) ? (4'd1 + {2'b00, escrow})
                                                : 4'd1;
           end else if (ret_done) begin
               credits <= credits + ret_amt;
               if (outstanding == 4'd1)
                   escrow <= 2'd0;
               outstanding <= outstanding - 4'd1;
               ret_q <= 1'b0;
           end
        end
    end

    // P: whenever nothing is in flight, the producer holds every credit
    always @(posedge clk)
        if (outstanding == 4'd0)
            assert (credits == TOTAL);
endmodule

// DRC check engine: each accepted board-check job walks a saturating
// step counter up to MAXSTEP while a completion countdown runs down.
module drc_engine (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       start,     // new check job requested
    output reg        busy,      // request outstanding
    output reg [3:0]  progress,  // saturating up-counter, clamps at MAXSTEP
    output reg [3:0]  deadline,  // completion countdown
    output reg        armed,     // sticky: a job has been accepted at least once
output reg        done,
output reg [3:0]  step_tally
);
    localparam [3:0] MAXSTEP = 4'd10;
   localparam [3:0] PASS1   = 4'd6;   // steps budgeted to the first pass

   // second-pass budget, parked out of the live countdown until pass one ends
   reg [3:0] credit;

    initial begin
        busy     = 1'b0;
        progress = 4'd0;
        deadline = 4'd0;
        armed    = 1'b0;
        done     = 1'b0;
       credit   = 4'd0;
step_tally = 4'd0;
    end

    wire accept   = i_ce && start && !busy;
    wire step     = i_ce && busy;
    wire last     = (progress + 4'd1 >= MAXSTEP);
   wire refill   = (deadline <= 4'd1) && (credit != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            busy     <= 1'b0;
            progress <= 4'd0;
            deadline <= 4'd0;
            armed    <= 1'b0;
            done     <= 1'b0;
           credit   <= 4'd0;
step_tally <= 4'd0;
        end else if (accept) begin
            busy     <= 1'b1;
            progress <= 4'd0;
           deadline <= PASS1;             // pass one runs on its own budget
           credit   <= MAXSTEP - PASS1;   // remainder held back for pass two
            armed    <= 1'b1;   // sticky once set, never cleared except by rst
            done     <= 1'b0;
        end else if (step) begin
            // saturating up-counter: clamps at MAXSTEP, never reaches 4'd15
            progress <= (progress == MAXSTEP) ? MAXSTEP : progress + 4'd1;
           if (refill) begin
               // pass one spent: hand the reserve to the live countdown
               deadline <= credit;
               credit   <= 4'd0;
           end else begin
               deadline <= (deadline == 4'd0) ? 4'd0 : deadline - 4'd1;
           end
            if (last) begin
                busy <= 1'b0;
                done <= 1'b1;
            end
step_tally <= (step_tally == 4'd15) ? 4'd15 : step_tally + 4'd1;
        end
    end

    // P: while the engine has ever been armed and a check is outstanding,
    // the completion countdown must not have expired.
    always @(*)
        if (armed && busy)
            assert (deadline != 4'd0);
endmodule

module vd_sheet_loader (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_start,
    input  wire       i_last_row,
    output wire       o_loading,
    output wire       o_ready,
output wire [3:0] o_rows,
output reg  [3:0] o_ce_beats
);
    // binary-encoded loader FSM: IDLE/OPEN/HEADER/ROWS/DONE
    // encodings 101, 110, 111 are never entered by construction
    localparam [2:0] S_IDLE   = 3'b000,
                     S_OPEN   = 3'b001,
                     S_HEADER = 3'b010,
                     S_ROWS   = 3'b011,
                     S_DONE   = 3'b100;

    reg [2:0] st;
    reg       loading;
    reg       ready;
   reg       fin_pend;
    reg [3:0] rows;

    initial st      = S_IDLE;
    initial loading = 1'b0;
    initial ready   = 1'b0;
   initial fin_pend = 1'b0;
    initial rows    = 4'd0;
initial o_ce_beats = 4'd0;

    always @(posedge clk) begin
        if (i_reset) begin
            st      <= S_IDLE;
            loading <= 1'b0;
            ready   <= 1'b0;
           fin_pend <= 1'b0;
            rows    <= 4'd0;
o_ce_beats <= 4'd0;
        end else if (i_ce) begin
o_ce_beats <= o_ce_beats + {3'd0, i_start};
           // completion is committed one beat after the FSM posts it
           ready <= fin_pend;
            case (st)
                S_IDLE: begin
                    if (i_start) begin
                        st      <= S_OPEN;
                        loading <= 1'b1;
                    end else begin
                        st      <= S_IDLE;
                        loading <= 1'b0;
                    end
                end
                S_OPEN: begin
                    st      <= S_HEADER;
                    loading <= 1'b1;
                    rows    <= 4'd0;
                end
                S_HEADER: begin
                    st      <= S_ROWS;
                    loading <= 1'b1;
                end
                S_ROWS: begin
                    if (i_last_row) begin
                        st      <= S_DONE;
                        loading <= 1'b0;
                       fin_pend <= 1'b1;
                    end else begin
                        st      <= S_ROWS;
                        loading <= 1'b1;
                        rows    <= rows + 4'd1;
                    end
                end
                S_DONE: begin
                    st      <= S_IDLE;
                    loading <= 1'b0;
                   fin_pend <= 1'b0;
                end
                default: begin
                    // illegal encoding: parked recovery path, asserts both flags
                    st      <= 3'b110;
                    loading <= 1'b1;
                    ready   <= 1'b1;
                   fin_pend <= 1'b1;
                end
            endcase
        end
    end

    assign o_loading = loading;
    assign o_ready   = ready;
    assign o_rows    = rows;

    // P: the loader is never simultaneously loading and ready
    always @(posedge clk)
        assert (!(loading && ready));
endmodule

module axi_grant_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire [3:0] req,
    input  wire       done,
    output reg        gnt_valid,
    output reg [1:0]  gnt_idx,
    output reg [2:0]  timer,
    output reg [2:0]  elapsed,
output wire [3:0] o_gnt,
output reg [3:0]  req_hist
);
    // Latency budget granted to an accepted request.
localparam [2:0] BUDGET_MAX = 3'd5;
localparam [2:0] BUDGET_MIN = 3'd3;

// Adaptive latency allowance. A slave that times out earns one extra
// credit for the next requester; a slave that answers within a cycle
// gives one back. Only rewritten in the gap between grants.
reg [2:0] budget;

    // ---------------------------------------------------------------
    // Priority encoder over the request vector: lowest index wins.
    // The encoded index is only meaningful while gnt_valid is set.
    // ---------------------------------------------------------------
    wire       enc_valid = |req;
    wire [1:0] enc_idx   = req[0] ? 2'd0 :
                           req[1] ? 2'd1 :
                           req[2] ? 2'd2 : 2'd3;

    // Retirement of the outstanding grant: either the slave answered,
    // or the budget has been fully consumed.
wire retire = gnt_valid && (done || ((elapsed == (budget - 3'd1)) && (timer == 3'd1)));

    assign o_gnt = gnt_valid ? (4'b0001 << gnt_idx) : 4'b0000;

    initial gnt_valid = 1'b0;
    initial gnt_idx   = 2'd0;
    initial timer     = 3'd0;
    initial elapsed   = 3'd0;
initial budget    = BUDGET_MAX;
initial req_hist  = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            gnt_valid <= 1'b0;
            gnt_idx   <= 2'd0;
            timer     <= 3'd0;
            elapsed   <= 3'd0;
budget    <= BUDGET_MAX;
req_hist  <= 4'd0;
        end else if (i_ce) begin
req_hist <= {req_hist[2:0], (|req) & ~done};
            if (!gnt_valid) begin
                if (enc_valid) begin
                    gnt_valid <= 1'b1;
                    gnt_idx   <= enc_idx;
timer     <= budget;   // credits left
                    elapsed   <= 3'd0;     // cycles burnt
                end
            end else if (retire) begin
                gnt_valid <= 1'b0;
                timer     <= 3'd0;
                elapsed   <= 3'd0;
if (!done)
    budget <= (budget == BUDGET_MAX) ? BUDGET_MAX : budget + 3'd1;
else if (elapsed <= 3'd1)
    budget <= (budget == BUDGET_MIN) ? BUDGET_MIN : budget - 3'd1;
            end else begin
                timer   <= timer   - 3'd1;
                elapsed <= elapsed + 3'd1;
            end
        end
    end

    // Bounded response, safety form: the countdown must never reach zero
    // while a grant is still outstanding ...
    always @(posedge clk)
        assert (!gnt_valid || (timer != 3'd0));

    // ... and the elapsed-cycle counter must never run past the budget
    // window while a grant is still outstanding.
    always @(posedge clk)
        assert (!gnt_valid || (elapsed <= 3'd4));
endmodule

module gray_quantum_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // scheduler quantum tick enable
    output wire [3:0] o_gray,
    output wire [2:0] o_ones
);
    // Ten quantum slots (0..9). The binary shadow does the arithmetic,
    // the gray register is what leaves the clock domain. Terminal count is
    // detected on the gray word, as the CDC-facing logic sees it.
    localparam [3:0] GRAY_LAST = 4'b1101; // gray code of 4'd9

    reg [3:0] bin  = 4'd0;
    reg [3:0] gray = 4'b0000;

   // Lane B is the second scheduler quantum lane. To save area the two
   // lanes time-share one binary shadow and one increment/encode
   // datapath: the owner named by `turn` uses `bin`, the parked lane's
   // shadow waits in `bin_hold`, and the pair swaps on every tick.
   reg [3:0] gray_b   = 4'b0000;
   reg [3:0] bin_hold = 4'd0;
   reg       turn     = 1'b0;   // 0: lane A owns the shared shadow

   wire [3:0] gray_sel = turn ? gray_b : gray;

   wire       wrap    = (gray_sel == GRAY_LAST);
    wire [3:0] bin_nxt = wrap ? 4'd0 : (bin + 4'd1);

    // occupancy of the gray word: how many lanes are asserted this slot
    wire [2:0] ones = {2'b00, gray[0]} + {2'b00, gray[1]} +
                      {2'b00, gray[2]} + {2'b00, gray[3]};
    wire       occ_hi = (ones >= 3'd3);

    assign o_gray = gray;
    assign o_ones = ones;

    always @(posedge clk) begin
        if (rst) begin
            bin  <= 4'd0;
            gray <= 4'b0000;
           gray_b   <= 4'b0000;
           bin_hold <= 4'd0;
           turn     <= 1'b0;
        end else if (i_ce) begin
           // the lane owning the datapath advances its gray word, then
           // the shared shadow is handed over to the other lane
           if (turn) gray_b <= bin_nxt ^ (bin_nxt >> 1);
           else      gray   <= bin_nxt ^ (bin_nxt >> 1);
           bin      <= bin_hold;
           bin_hold <= bin_nxt;
           turn     <= ~turn;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Bounded existence: the gray word never carries four asserted lanes,
    // so whenever the high-occupancy flag rises it rises to exactly three.
    always @(posedge clk)
        if (pv && $rose(occ_hi))
            assert (ones == 3'd3);

   // Lane coherence: the swap is only half done while lane B holds the
   // shared shadow. Once ownership is back with lane A both lanes have
   // been advanced to the same quantum slot, so the two gray words the
   // CDC side can sample are identical.
   always @(posedge clk)
       if (pv) assert (turn || (gray == gray_b));
endmodule

module skid_parity_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // stage enable: low => full idle
    input  wire       i_valid,
    input  wire [7:0] i_data,
    input  wire       i_dready,    // downstream ready
    input  wire       i_close,     // closes the observation window
    output wire       o_ready,
    output reg        o_valid,
output reg  [7:0] o_data,
output reg  [3:0] o_beat_count
);

    // ---- skid buffer stage state ----
    reg        stall;      // skid slot occupied
    reg  [3:0] skid;       // low nibble of the buffered word
    reg  [3:0] skid_hi;    // upper nibble; flops enabled only for wide words
    reg        skid_wide;  // buffered word has a nonzero upper nibble
    reg        skid_par;   // shadow parity of the buffered word

    reg        o_par;      // shadow parity of the presented word

    // ---- observation window (opened by a skid release, closed by i_close) ----
    reg        win;
    reg  [7:0] acc_data;    // xor of words released inside the window
    reg        acc_par;     // xor of their shadow parities

    initial begin
        stall    = 1'b0;
        skid      = 4'h0;
        skid_hi   = 4'h0;
        skid_wide = 1'b0;
        skid_par = 1'b0;
        o_valid  = 1'b0;
        o_data   = 8'h00;
        o_par    = 1'b0;
        win      = 1'b0;
        acc_data = 8'h00;
        acc_par  = 1'b0;
o_beat_count = 4'd0;
    end

    assign o_ready = !stall;

    // reassembled buffered word: narrow words carry an implicit zero nibble
    wire [7:0] skid_word = {(skid_wide ? skid_hi : 4'h0), skid};

    wire do_release = i_ce &&  stall &&  i_dready;
    wire do_direct  = i_ce && !stall &&  i_valid && (i_dready || !o_valid);
    wire do_capture = i_ce && !stall &&  i_valid && o_valid && !i_dready;
    wire do_drop    = i_ce && !stall && !i_valid && i_dready && o_valid;

    always @(posedge clk) begin
        if (rst) begin
            stall    <= 1'b0;
            skid      <= 4'h0;
            skid_hi   <= 4'h0;
            skid_wide <= 1'b0;
            skid_par <= 1'b0;
            o_valid  <= 1'b0;
            o_data   <= 8'h00;
            o_par    <= 1'b0;
            win      <= 1'b0;
            acc_data <= 8'h00;
            acc_par  <= 1'b0;
o_beat_count <= 4'd0;
        end else begin
            // datapath
            if (do_release) begin
                o_valid <= 1'b1;
                o_data  <= skid_word;
                o_par   <= skid_par;
                stall   <= 1'b0;
            end else if (do_direct) begin
                o_valid <= 1'b1;
                o_data  <= i_data;
                o_par   <= ^i_data;
            end else if (do_capture) begin
                stall    <= 1'b1;
                skid      <= i_data[3:0];
                if (i_data[7:4] != 4'h0) begin
                    skid_hi   <= i_data[7:4];
                    skid_wide <= 1'b1;
                end else begin
                    skid_wide <= 1'b0;
                end
                skid_par <= ^i_data;
            end else if (do_drop) begin
                o_valid <= 1'b0;
            end

            // window: opened by a release, closed by i_close
            if (i_ce) begin
                if (i_close)         win <= 1'b0;
                else if (do_release) win <= 1'b1;
            end

            // in-window accumulation of released words
            if (do_release) begin
                if (win) begin
                    acc_data <= acc_data ^ skid_word;
                    acc_par  <= acc_par  ^ skid_par;
                end else begin
                    acc_data <= skid_word;
                    acc_par  <= skid_par;
                end
            end
if (i_ce) begin
    o_beat_count <= o_beat_count + 4'd1;
end
        end
    end

    // ---- property: inside the window, both shadow parities track their words ----
    always @(posedge clk) begin
        if (win) begin
            assert (o_par   == (^o_data));
            assert (acc_par == (^acc_data));
        end
    end

endmodule

module token_bucket_deadline (
    input  wire clk,
    input  wire i_ce,
    input  wire req,
    output wire grant,
    output wire expired
);
    // burst size of the bucket and the response deadline for one request
    localparam [2:0] BURST   = 3'd4;
    localparam [3:0] TIMEOUT = 4'd6;

    reg [2:0] tokens;    // token bucket, capped at BURST
    reg [1:0] tick_cnt;   // refill timer, counts down, tick at zero
    reg       pending;    // window register: set by accepted request, cleared by grant
    reg [3:0] deadline;   // bounded-response countdown for the pending request
    reg       refill_q;  // staged refill: a tick is captured here and applied to the bucket next cycle
    reg       pending_b;   // second request slot: holds a request that arrived while the head slot was busy
    reg [3:0] deadline_b;  // best-effort countdown for the queued slot
    reg       rr_b;        // arbitration pointer, 1 when the queued slot gets the next token

    initial tokens   = BURST;
    initial tick_cnt = 2'd3;
    initial pending  = 1'b0;
    initial deadline = 4'd0;
    initial refill_q = 1'b0;
    initial pending_b  = 1'b0;
    initial deadline_b = 4'd0;
    initial rr_b       = 1'b0;

    wire tick     = (tick_cnt == 2'd0);
    wire b_ready    = pending_b && (tokens != 3'd0);
    // the queued slot only pre-empts on its own turn, and only while the
    // bucket still holds a spare token for the head slot
    wire do_grant_b = b_ready && (!pending || (rr_b && (tokens >= 3'd2)));
    wire do_grant = pending && (tokens != 3'd0) && !do_grant_b;
    wire do_refill = refill_q && (tokens < BURST);
    wire any_grant = do_grant || do_grant_b;

    assign grant   = i_ce && any_grant;
    assign expired = (pending && (deadline == 4'd0)) || (pending_b && (deadline_b == 4'd0));

    // refill timer
    always @(posedge clk) if (i_ce)
        tick_cnt <= tick ? 2'd3 : (tick_cnt - 2'd1);

    // refill request is registered one cycle before it reaches the bucket
    always @(posedge clk) if (i_ce)
        refill_q <= tick;

    // bucket: drains on a grant, refills on a tick, saturates at BURST
    always @(posedge clk) if (i_ce) begin
        if (any_grant && do_refill)
            tokens <= tokens;                 // one out, one in
        else if (any_grant)
            tokens <= tokens - 3'd1;
        else if (do_refill)
            tokens <= tokens + 3'd1;
    end

    // round-robin pointer: whichever slot was served hands the turn over
    always @(posedge clk) if (i_ce) begin
        if (do_grant_b)
            rr_b <= 1'b0;
        else if (do_grant)
            rr_b <= 1'b1;
    end

    // queued slot: captures the request that arrives while the head slot is busy,
    // counts down best effort and drops the request if it runs out
    always @(posedge clk) if (i_ce) begin
        if (do_grant_b)
            pending_b <= 1'b0;
        else if (pending_b) begin
            if (deadline_b == 4'd0)
                pending_b <= 1'b0;
            else
                deadline_b <= deadline_b - 4'd1;
        end else if (req && pending) begin
            pending_b  <= 1'b1;
            deadline_b <= TIMEOUT;
        end
    end

    // request window and its countdown
    always @(posedge clk) if (i_ce) begin
        if (do_grant)
            pending <= 1'b0;
        else if (pending)
            deadline <= deadline - 4'd1;
        else if (req) begin
            pending  <= 1'b1;
            deadline <= TIMEOUT;
        end
    end

    // P: inside the request window the countdown never expires
    always @(posedge clk)
        if (pending) assert (deadline != 4'd0);
endmodule

// Four-phase req/ack handshake engine with a busy mirror and
// per-client ownership / response routing tags.
//
//   phase 0 : idle            (req=0, ack=0)
//   phase 1 : req asserted    (req=1, ack=0)
//   phase 2 : ack observed    (req=1, ack=1)
//   phase 3 : req withdrawn   (req=0, ack=1)  -> waits for ack to drop
//
// busy is a separate register that mirrors "phase != 0"; the start path is
// gated on !busy only, exactly as a real controller would do.
module fourphase_owner (
    input  wire clk,
    input  wire i_ce,        // idle condition: nothing moves when low
    input  wire i_req,       // a client wants the channel
    input  wire i_sel,       // which client (0 -> A, 1 -> B)
    input  wire i_ack_in,    // ack wire coming back from the target
    output wire o_busy,
    output wire o_req,
    output wire o_ack
);

    reg [1:0] phase;
    reg       busy;
    reg       req;
    reg       ack;
    reg       own_a, own_b;   // who currently owns the channel
    reg       resp_a, resp_b; // where the response will be routed
    reg       virgin;         // high until the first handshake ever completes

   // Credit ledger: one credit exists for the channel. Every acquire is
   // logged in n_acq, every retire in n_rel; both wrap at four bits. The
   // channel may only be taken when all logged acquires have been retired.
   reg [3:0] n_acq;
   reg [3:0] n_rel;

   wire ledger_free = (n_acq == n_rel);

    initial phase  = 2'd0;
    initial busy   = 1'b0;
    initial req    = 1'b0;
    initial ack    = 1'b0;
    initial own_a  = 1'b0;
    initial own_b  = 1'b0;
    initial resp_a = 1'b0;
    initial resp_b = 1'b0;
    initial virgin = 1'b1;
   initial n_acq  = 4'd0;
   initial n_rel  = 4'd0;

    always @(posedge clk) begin
        if (i_ce) begin
           if (ledger_free) begin
                // channel believed free: latch the owner and drive req
                if (i_req) begin
                    phase <= 2'd1;
                    req   <= 1'b1;
                    busy  <= 1'b1;
                   n_acq <= n_acq + 4'd1;
                    if (i_sel)
                        own_b <= 1'b1;
                    else
                        own_a <= 1'b1;
                end
            end else begin
                case (phase)
                    2'd1: if (i_ack_in) begin
                              // ack rose: snapshot the response route
                              phase  <= 2'd2;
                              ack    <= 1'b1;
                              resp_a <= own_a;
                              resp_b <= own_b;
                          end
                    2'd2: begin
                              // req may only drop now that ack is high
                              phase <= 2'd3;
                              req   <= 1'b0;
                          end
                    2'd3: if (!i_ack_in) begin
                              phase  <= 2'd0;
                              ack    <= 1'b0;
                              busy   <= 1'b0;
                             n_rel  <= n_rel + 4'd1;
                              own_a  <= 1'b0;
                              own_b  <= 1'b0;
                              resp_a <= 1'b0;
                              resp_b <= 1'b0;
                              virgin <= 1'b0;   // first completion disarms
                          end
                    default: ;
                endcase
            end
        end
    end

    assign o_busy = busy;
    assign o_req  = req;
    assign o_ack  = ack;

    // Before the first handshake has ever completed, there must never be two
    // owners at once, and never two response routes at once.
    always @(posedge clk)
        if (virgin) assert (!(own_a && own_b));

    always @(posedge clk)
        if (virgin) assert (!(resp_a && resp_b));

endmodule

// Priority arbiter for per-subchannel energy detect flags.
// Stage 0: combinational priority encode of the request vector.
// Stage 1: registered half-occupancy flags + priority-half decision.
// Stage 2: registered valid, registered index (only meaningful while valid),
//          and the two half-band grant flags.
module wifi_pri_grant (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [7:0] i_req,
    output reg        o_vld,
    output reg  [2:0] o_idx,
    output reg        o_grant_lo,
    output reg        o_grant_hi
);
    // ---------------- stage 0: combinational priority encoder ------------
    wire req_lo = |i_req[3:0];
    wire req_hi = |i_req[7:4];

    reg [2:0] enc;
    always @(*) begin
        casez (i_req)
            8'b???????1: enc = 3'd0;
            8'b??????10: enc = 3'd1;
            8'b?????100: enc = 3'd2;
            8'b????1000: enc = 3'd3;
            8'b???10000: enc = 3'd4;
            8'b??100000: enc = 3'd5;
            8'b?1000000: enc = 3'd6;
            8'b10000000: enc = 3'd7;
            default:     enc = 3'd0;
        endcase
    end

    // ---------------- stage 1 registers ---------------------------------
    reg       s1_vld;
    reg       s1_req_lo;
    reg       s1_req_hi;
    reg       s1_pri_hi;   // upper half wins only when lower half is empty
    reg [2:0] s1_idx;

   // ---------------- stage 2 grant accounting --------------------------
   // Per-band grant counters plus a counter of cycles in which any band
   // reported energy.  Firmware samples their low bits on the index bus
   // while the pipe is idle (o_idx carries no index when o_vld is low).
   reg [3:0] cnt_lo;
   reg [3:0] cnt_hi;
   reg [3:0] cnt_tot;

    initial begin
        s1_vld    = 1'b0;
        s1_req_lo = 1'b0;
        s1_req_hi = 1'b0;
        s1_pri_hi = 1'b0;
        s1_idx    = 3'd0;
       cnt_lo     = 4'd0;
       cnt_hi     = 4'd0;
       cnt_tot    = 4'd0;
        o_vld      = 1'b0;
        o_idx      = 3'd0;
        o_grant_lo = 1'b0;
        o_grant_hi = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // stage 1 capture
            s1_vld    <= req_lo | req_hi;
            s1_req_lo <= req_lo;
            s1_req_hi <= req_hi;
            s1_pri_hi <= req_hi && !req_lo;
            s1_idx    <= enc;

            // stage 2 capture
            o_vld      <= s1_vld;
           // idle index bus carries a compact counter status code
           o_idx      <= s1_vld ? s1_idx
                                : {cnt_tot[0], cnt_hi[0], cnt_lo[0]};
            o_grant_lo <= s1_vld && s1_req_lo;
            o_grant_hi <= s1_vld && s1_pri_hi;

           // grant accounting, driven off the same stage-1 decision
           if (s1_vld && s1_req_lo)
               cnt_lo  <= cnt_lo  + 4'd1;
           if (s1_vld && s1_pri_hi)
               cnt_hi  <= cnt_hi  + 4'd1;
           if (s1_vld && (s1_req_lo || s1_req_hi))
               cnt_tot <= cnt_tot + 4'd1;
        end
    end

    // P: while the encoded index is valid, the two half-band grants are
    //    never asserted together.
    always @(posedge clk)
        if (o_vld)
            assert (!(o_grant_lo && o_grant_hi));

   // Q: the per-band grant counters account for exactly the counted
   //    request cycles.
   always @(posedge clk)
       assert (cnt_tot == cnt_lo + cnt_hi);

endmodule

module boot_chunk_loader (
    input  wire i_clk,
    input  wire i_ce,      // idle when low: no state changes at all
    input  wire i_start,   // accept a fresh load request
    output wire o_expired,
    output wire o_done,
    output wire [7:0] o_total
);
    // A chunk loader that accumulates 3 bytes of payload per accepted step.
    // The accumulator is kept in two carry-save halves (acc_a, acc_b) whose
    // sum is the true byte total; `total` is the redundant true running sum.
localparam [3:0] TMAX  = 4'd9;   // countdown granted: 8 steps + 1 commit-stage cycle
    localparam [7:0] LIMIT = 8'd24;  // bytes that constitute completion

    reg [7:0] acc_a;
    reg [7:0] acc_b;
    reg [7:0] total;
    reg [3:0] timer;
reg       st_v;    // a step is sitting in the commit register
reg [3:0] st_lo;   // its low carry-save half-increment
reg [3:0] st_hi;   // its high carry-save half-increment
    reg       pv;

    initial acc_a = 8'd0;
    initial acc_b = 8'd0;
    initial total = 8'd0;
    initial timer = TMAX;
initial st_v  = 1'b0;
initial st_lo = 4'd0;
initial st_hi = 4'd0;
    initial pv    = 1'b0;

    wire [7:0] csum    = acc_a + acc_b;   // halves recombined
    wire       expired = (timer == 4'd0);

    assign o_expired = expired;
    assign o_done    = (csum >= LIMIT);
    assign o_total   = total;

    always @(posedge i_clk)
        pv <= 1'b1;

    always @(posedge i_clk) begin
        if (i_ce) begin
            if (i_start) begin
                acc_a <= 8'd0;
                acc_b <= 8'd0;
                total <= 8'd0;
                timer <= TMAX;
st_v  <= 1'b0;          // flush whatever was in flight
st_lo <= 4'd0;
st_hi <= 4'd0;
end else begin
    // stage 1: issue the next step's half-increments into the commit register
    if (timer != 4'd0) begin
        st_v  <= 1'b1;
        st_lo <= 4'd1;
        st_hi <= 4'd2;
        timer <= timer - 4'd1;
    end else begin
        st_v  <= 1'b0;
        st_lo <= 4'd0;
        st_hi <= 4'd0;
    end
    // stage 2: commit the step issued last cycle
    if (st_v) begin
        acc_a <= acc_a + {4'd0, st_lo};                  // low carry-save half
        acc_b <= acc_b + {4'd0, st_hi};                  // high carry-save half
        total <= total + {4'd0, st_lo} + {4'd0, st_hi};  // true total
    end
            end
        end
    end

    // Bounded response, safety form: the countdown must never expire while the
    // load request is still outstanding.  Edge form: the cycle `expired` rises,
    // the recombined accumulator must already show a completed transfer.
    always @(posedge i_clk)
        if (pv)
            assert (!$rose(expired) || (acc_a + acc_b >= LIMIT));
endmodule

module debounce_hist_arm (
    input  wire i_clk,
    input  wire i_ce,
    input  wire i_raw,
    output wire o_clean,
    output wire o_armed,
    output wire o_settled
);
    // K identical consecutive samples are required before the clean output flips.
    localparam [2:0] KC = 3'd4;
    localparam       HW = 8;

    reg [2:0]      cnt;     // stability counter, saturates at KC
    reg            sample;  // current candidate level being timed
    reg            clean;   // debounced (committed) level
    reg [HW-1:0]   hist;    // raw sample history, hist[0] is the newest sample
    reg            armed;   // sticky: set the first time the filter commits
   reg            stable;  // registered settled flag, drives o_settled

    initial cnt    = 3'd0;
    initial sample = 1'b0;
    initial clean  = 1'b0;
    initial hist   = {HW{1'b0}};
    initial armed  = 1'b0;
   initial stable = 1'b0;

    always @(posedge i_clk) if (i_ce) begin
        hist <= { hist[HW-2:0], i_raw };
        if (i_raw != sample) begin
            // new level seen: retime from scratch
            sample <= i_raw;
            cnt    <= 3'd0;
           stable <= 1'b0;
        end else if (cnt < KC) begin
            cnt <= cnt + 3'd1;
            if (cnt == (KC - 3'd1)) begin
                // KC identical consecutive samples: commit the level
                clean <= sample;
                armed <= 1'b1;
               stable <= 1'b1;
            end
        end
    end

    assign o_clean   = clean;
    assign o_armed   = armed;
   assign o_settled = stable;

    // Universality, after the filter has armed: whenever the stability counter
    // is nonzero the two newest raw samples must agree.
    always @(*)
        if (armed)
            assert ((cnt == 3'd0) || (hist[1] == hist[0]));

   // While the filter reports settled, the committed level must still match the
   // newest raw sample: any disagreement would mean a missed retime.
   always @(posedge i_clk)
       assert (!stable || (clean == hist[0]));
endmodule

module fourphase_occupancy (
    input  wire       clk,
    input  wire       i_ce,          // global enable / idle when low
    input  wire       start,         // master wants a new transaction
    input  wire       dev_ack_ready, // device is ready to raise ack
    output reg        req,
    output reg        ack,
    output reg        busy,
    output reg [2:0]  occ,           // outstanding-transaction occupancy
output reg        armed,
output reg [3:0]  ce_ticks
);
    // four-phase handshake sequencer:
    //   phase 0 : idle        (req=0, ack=0)
    //   phase 1 : req raised  (req=1, ack=0)
    //   phase 2 : ack raised  (req=1, ack=1)
    //   phase 3 : req dropped (req=0, ack=1)   -> ack drops, back to idle
    reg [1:0] phase;
    reg       pv;
reg [3:0] ce_ticks_d;

    initial begin
        phase = 2'd0;
        req   = 1'b0;
        ack   = 1'b0;
        busy  = 1'b0;
        occ   = 3'd0;
        armed = 1'b0;
        pv    = 1'b0;
ce_ticks   = 4'd0;
ce_ticks_d = 4'd0;
    end

    always @(posedge clk)
        pv <= 1'b1;

always @(posedge clk) begin
    if (i_ce) begin
        ce_ticks_d <= ce_ticks;
        ce_ticks   <= ce_ticks + {3'd0, start} + 4'd1;
    end else begin
        ce_ticks   <= ce_ticks_d;
    end
end

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                2'd0: begin
                    // request may only be launched from idle
                    if (start) begin
                        req   <= 1'b1;
                        busy  <= 1'b1;      // busy mirrors the phase
                        occ   <= occ + 3'd1;
                        phase <= 2'd1;
                    end
                end
                2'd1: begin
                    // req is held; it may not drop until ack rises
                    if (dev_ack_ready) begin
                        ack   <= 1'b1;
                        phase <= 2'd2;
                    end
                end
                2'd2: begin
                    // ack seen -> now req is allowed to drop
                    req   <= 1'b0;
                    phase <= 2'd3;
                end
                2'd3: begin
                    // ack drops, transaction retires
                    ack   <= 1'b0;
                    busy  <= 1'b0;
                    occ   <= occ - 3'd1;
                    armed <= 1'b1;   // sticky: first completed handshake arms
                    phase <= 2'd0;
                end
            endcase
        end
    end

    // Property: once at least one handshake has completed (armed), every time the
    // busy flag rises the occupancy must not exceed two.
    always @(posedge clk)
        if (pv && armed && $rose(busy))
            assert (occ <= 3'd2);
endmodule

module dma_copier_chain (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_clear,
    input  wire [3:0] i_len,
    output wire       o_done,
    output wire       o_busy,
    output wire       o_err
);
    // phase slice codes (gray-ish), each with its stored parity bit
    localparam [1:0] PH_IDLE  = 2'b00,   // parity 0
                     PH_ARMED = 2'b01,   // parity 1
                     PH_BUSY  = 2'b11,   // parity 0
                     PH_DONE  = 2'b10;   // parity 1

    // parity-protected register slice holding the engine phase
    reg [1:0] phase   = PH_IDLE;
    reg       par     = 1'b0;

    // descriptor word counter
    reg [3:0] count   = 4'd0;

    // chain history bits: arm happened, start happened
    reg       h_arm   = 1'b0;
    reg       h_start = 1'b0;
    // start handshake stage: the start pulse is captured here for the
    // descriptor-fetch cycle and is only then logged into h_start
    reg       s_pend  = 1'b0;

    // slice checker: stored parity must match stored phase
    wire slice_bad = (par != (^phase));

    always @(posedge clk) begin
        if (i_ce) begin
            if (slice_bad) begin
                // corrupted descriptor slice: abort, report done immediately
                phase <= PH_DONE;
                par   <= 1'b1;
            end else begin
                case (phase)
                PH_IDLE:
                    if (i_arm) begin
                        phase   <= PH_ARMED;
                        par     <= 1'b1;
                        count   <= i_len;
                        h_arm   <= 1'b1;
                    end
                PH_ARMED:
                    if (i_start) begin
                        phase   <= PH_BUSY;
                        par     <= 1'b0;
                        s_pend  <= 1'b1;
                    end
                PH_BUSY:
                    if (s_pend) begin
                        // first burst cycle fetches the descriptor word,
                        // no payload word moves and the length is untouched
                        s_pend  <= 1'b0;
                        h_start <= 1'b1;
                    end else if (count == 4'd0) begin
                        phase <= PH_DONE;
                        par   <= 1'b1;
                    end else begin
                        count <= count - 4'd1;
                    end
                PH_DONE:
                    if (i_clear) begin
                        phase <= PH_IDLE;
                        par   <= 1'b0;
                    end
                endcase
            end
        end
    end

    assign o_done = (phase == PH_DONE);
    assign o_busy = (phase == PH_BUSY);
    assign o_err  = slice_bad;

    // chain precedence, globally: a finish can never be seen unless the
    // arm step and then the start step were actually taken
    always @(posedge clk)
        if (phase == PH_DONE) assert (h_arm);

    always @(posedge clk)
        if (phase == PH_DONE) assert (h_start);
endmodule

module rr_arb_shadow (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [3:0] req,
    input  wire       arm,
    input  wire       clr,
    output reg  [3:0] gnt
);
    // round-robin arbiter state
    reg [1:0] ptr;       // last granted line index
   reg [1:0] hold;      // line the parked grant is sitting on
   reg [3:0] n_iss;     // grants issued  (free-running, wraps)
   reg [3:0] n_ret;     // grants retired (free-running, wraps)
    // precedence shadow of the previous grant decision
    reg [3:0] prev_gnt;
    reg [1:0] prev_ptr;
    reg [3:0] hist;      // lines the pointer has rested on since arming
    reg       armed;     // window register: set by arm, cleared by clr

    initial begin
        gnt      = 4'b0000;
        ptr      = 2'd0;
        prev_gnt = 4'b0000;
        prev_ptr = 2'd0;
        hist     = 4'b0000;
        armed    = 1'b0;
       hold     = 2'd0;
       n_iss    = 4'd0;
       n_ret    = 4'd0;
    end

    // rotating priority: start just past the last grant
    wire [1:0] c0 = ptr + 2'd1;
    wire [1:0] c1 = ptr + 2'd2;
    wire [1:0] c2 = ptr + 2'd3;
    wire [1:0] c3 = ptr;

    reg       sel_val;
    reg [1:0] sel_idx;
    always @(*) begin
        if (req[c0])      begin sel_val = 1'b1; sel_idx = c0;   end
        else if (req[c1]) begin sel_val = 1'b1; sel_idx = c1;   end
        else if (req[c2]) begin sel_val = 1'b1; sel_idx = c2;   end
        else if (req[c3]) begin sel_val = 1'b1; sel_idx = c3;   end
        else              begin sel_val = 1'b0; sel_idx = 2'd0; end
    end

    // one-hot (or all-zero) next grant, never on a non-requesting line
    wire [3:0] nxt = sel_val ? (4'b0001 << sel_idx) : 4'b0000;

   // a grant is parked on its line until that line drops its request; the
   // issue/retire ledger is what tells the arbiter it may re-arbitrate
   wire outstanding = (n_iss != n_ret);
   wire issue       = ce && !outstanding && sel_val;
   wire retire      = ce &&  outstanding && !req[hold];

    always @(posedge clk) begin
        if (rst) begin
            gnt      <= 4'b0000;
            ptr      <= 2'd0;
            prev_gnt <= 4'b0000;
            prev_ptr <= 2'd0;
            hist     <= 4'b0000;
            armed    <= 1'b0;
           hold     <= 2'd0;
           n_iss    <= 4'd0;
           n_ret    <= 4'd0;
        end else begin
            if (ce) begin
               if (outstanding) begin
                   gnt <= req[hold] ? (4'b0001 << hold) : 4'b0000;
               end else begin
                   gnt <= nxt;
                   if (sel_val) begin
                       ptr  <= sel_idx;
                       hold <= sel_idx;
                   end
               end
                prev_gnt <= gnt;
                prev_ptr <= ptr;
               // a line only counts as rested-on while it holds a grant
               if (outstanding) hist <= hist | (4'b0001 << ptr);
            end
           n_iss <= n_iss + {3'd0, issue};
           n_ret <= n_ret + {3'd0, retire};
            // opening the observation window restarts the shadow record
            if (arm && !armed) begin
                armed    <= 1'b1;
                prev_gnt <= 4'b0000;
                prev_ptr <= 2'd0;
                hist     <= 4'b0000;
            end else if (clr) begin
                armed <= 1'b0;
            end
        end
    end

    // after arm, until clr (which may never come): a recorded grant must have
    // been preceded by the pointer standing on that very line
    always @(posedge clk) begin
        if (armed)
            assert (prev_gnt == 4'b0000 || prev_gnt == (4'b0001 << prev_ptr));
        if (armed)
            assert (prev_gnt == 4'b0000 || (hist & prev_gnt) != 4'b0000);
    end
endmodule

module lock_arbiter_occ (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire [3:0] i_req,
    output wire [3:0] o_grant,
    output wire       o_busy
);
    // fixed-priority arbiter with a lock bit that freezes the winner
    reg [3:0] grant;
    reg       lock;
    // shadow occupancy counter: how many grants are currently outstanding
    reg [2:0] occ;
    // lock-hold timer: beats the current owner has held the bus
    reg [2:0] hold_cnt;

    initial grant = 4'b0000;
    initial lock  = 1'b0;
    initial occ   = 3'd0;
    initial hold_cnt = 3'd0;

    wire        busy    = (grant != 4'b0000);
    wire        any_req = (i_req != 4'b0000);

    // fixed priority: channel 0 highest
    wire [3:0] pri_grant = i_req[0] ? 4'b0001 :
                           i_req[1] ? 4'b0010 :
                           i_req[2] ? 4'b0100 :
                           i_req[3] ? 4'b1000 : 4'b0000;
    // anti-starvation: the lock expires after 5 held beats so lower channels can win
    wire lock_expired = (hold_cnt >= 3'd5);

    // while locked, the current winner keeps the bus as long as it still asks
    wire holding = busy && lock && !lock_expired && ((grant & i_req) != 4'b0000);

    always @(posedge i_clk) begin
        if (i_rst) begin
            grant <= 4'b0000;
            lock  <= 1'b0;
            occ   <= 3'd0;
            hold_cnt <= 3'd0;
        end else if (i_ce) begin
            if (busy) begin
                if (!holding) begin
                    // winner released: drop the grant and free the slot
                    grant <= 4'b0000;
                    lock  <= 1'b0;
                    occ   <= occ - 3'd1;
                    hold_cnt <= 3'd0;
                end
                else begin
                    // still holding: age the lock
                    hold_cnt <= hold_cnt + 3'd1;
                end
            end else if (any_req) begin
                // bus free: award it and lock it
                grant <= pri_grant;
                lock  <= 1'b1;
                occ   <= occ + 3'd1;
                hold_cnt <= 3'd0;
            end
        end
    end

    assign o_grant = grant;
    assign o_busy  = busy;

    // at most one grant may be outstanding at any time
    always @(*)
        assert (occ <= 3'd1);

    // the hold timer only ages while a grant is outstanding
    always @(posedge i_clk)
        assert ((hold_cnt == 3'd0) || (occ == 3'd1));
endmodule

module hist_precedence (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_op,     // 0 = add one sample to bin i_sel, 1 = remove one
    input  wire [1:0] i_sel,
    output reg  [5:0] total
);
    // histogram bins
    reg [3:0] bin0, bin1, bin2, bin3;

    // shadow of the earlier event: which bin got the very first sample
    reg [1:0] first_bin;
    reg       saw_sample;

    // scope arming register: high until the first removal aimed at first_bin
    reg       pre_purge;

    // shadow high-water mark of the first-sampled bin's count
    reg [3:0] hi_first;

   // staged high-water update: the shadow compare is registered, so a
   // candidate count lands in hi_first one enabled cycle later
   reg [3:0] hw_pend;
   reg       hw_vld;

    initial begin
        bin0       = 4'd0;
        bin1       = 4'd0;
        bin2       = 4'd0;
        bin3       = 4'd0;
        total      = 6'd0;
        first_bin  = 2'd0;
        saw_sample = 1'b0;
        pre_purge  = 1'b1;
        hi_first   = 4'd0;
       hw_pend    = 4'd0;
       hw_vld     = 1'b0;
    end

    wire [3:0] sel_cnt   = (i_sel == 2'd0) ? bin0 :
                           (i_sel == 2'd1) ? bin1 :
                           (i_sel == 2'd2) ? bin2 : bin3;

    wire [3:0] first_cnt = (first_bin == 2'd0) ? bin0 :
                           (first_bin == 2'd1) ? bin1 :
                           (first_bin == 2'd2) ? bin2 : bin3;

   // acquisition freezes once the first-sampled bin has saturated
   wire frozen = (hi_first == 4'd15);


   wire do_add = i_ce && !i_op && (total != 6'd31) && (sel_cnt != 4'd15) && !frozen;
    wire do_rem = i_ce &&  i_op && (sel_cnt != 4'd0);
    wire purge  = i_ce &&  i_op && saw_sample && (i_sel == first_bin);

    wire armed  = pre_purge && saw_sample;

    // count the first-sampled bin will hold after this cycle
    wire [3:0] first_nxt =
        (do_add && !saw_sample)                          ? (sel_cnt   + 4'd1) :
        (do_add && saw_sample && (i_sel == first_bin))    ? (first_cnt + 4'd1) :
        (do_rem && saw_sample && (i_sel == first_bin))    ? (first_cnt - 4'd1) :
                                                            first_cnt;

    always @(posedge clk) begin
        if (i_ce) begin
            if (do_add) begin
                total <= total + 6'd1;
                case (i_sel)
                    2'd0:    bin0 <= bin0 + 4'd1;
                    2'd1:    bin1 <= bin1 + 4'd1;
                    2'd2:    bin2 <= bin2 + 4'd1;
                    default: bin3 <= bin3 + 4'd1;
                endcase
                if (!saw_sample) begin
                    saw_sample <= 1'b1;
                    first_bin  <= i_sel;
                end
            end else if (do_rem) begin
                total <= total - 6'd1;
                case (i_sel)
                    2'd0:    bin0 <= bin0 - 4'd1;
                    2'd1:    bin1 <= bin1 - 4'd1;
                    2'd2:    bin2 <= bin2 - 4'd1;
                    default: bin3 <= bin3 - 4'd1;
                endcase
            end

            if (purge)
                pre_purge <= 1'b0;

           // commit the candidate captured on the previous enabled cycle
           if (hw_vld && (hw_pend > hi_first))
               hi_first <= hw_pend;


           if (do_add && !saw_sample) begin
               hw_pend <= sel_cnt + 4'd1;
               hw_vld  <= 1'b1;
           end else if (first_nxt > hi_first) begin
               hw_pend <= first_nxt;
               hw_vld  <= 1'b1;
           end else begin
               hw_vld  <= 1'b0;
           end
        end
    end

    // P: before any sample has ever been purged from the first-sampled bin,
    // the earlier arrival recorded in the shadow registers must still be
    // accounted for in the total-samples register.
    always @(posedge clk)
        if (armed) assert (total >= 6'd1);

    always @(posedge clk)
        if (armed) assert (total >= {2'b00, hi_first});
endmodule

// Tile-render pixel pipeline pacing: a /5 phase counter feeding a /4 row
// counter, plus an accumulator of paced cycles within one tile (20 steps)
// and a high-water mark of that accumulator.
module tilepipe_div (
    input  wire i_clk,
    input  wire i_ce,        // pipeline advance / idle when low
    output wire o_tile_en,   // divided-enable pulse: fires when the chain wraps
    output wire [4:0] o_peak
);
    // ---- phase counter (divide by 5) ----
    reg [2:0] phase;
    initial   phase = 3'd0;

    // ---- row counter (divide by 4 of the phase wrap) ----
    reg [1:0] row;
    initial   row = 2'd0;

    // ---- accumulated paced cycles inside the current tile ----
    reg [4:0] total;
    initial   total = 5'd0;

   // ---- paced cycles already retired from the tile's first half ----
   reg [4:0] retired;
   initial   retired = 5'd0;

    // ---- high-water mark of the accumulator (monotone) ----
    reg [4:0] peak;
    initial   peak = 5'd0;

    reg pv;
    initial pv = 1'b0;

    wire ph_wrap  = (phase == 3'd4);
    wire row_wrap = ph_wrap && (row == 2'd3);

   // the tile is flushed in halves: when row 1 finishes, the low
   // accumulator is folded into the retired count and restarted, so the
   // low accumulator only ever spans one half-tile
   wire half_done = ph_wrap && (row == 2'd1);

   // paced cycles in this tile after the current step, across both halves;
   // cleared only by the divided-enable pulse, never by its own value
   wire [4:0] nxt_sum = row_wrap ? 5'd0 : (retired + total + 5'd1);

    always @(posedge i_clk) begin
        pv <= 1'b1;
        if (i_ce) begin
            phase <= ph_wrap ? 3'd0 : (phase + 3'd1);
            if (ph_wrap)
                row <= row_wrap ? 2'd0 : (row + 2'd1);
           if (row_wrap) begin
               total   <= 5'd0;
               retired <= 5'd0;
           end else if (half_done) begin
               total   <= 5'd0;
               retired <= retired + total + 5'd1;
           end else begin
               total   <= total + 5'd1;
           end
           if (nxt_sum > peak)
               peak <= nxt_sum;
        end
    end

    assign o_tile_en = i_ce && row_wrap;
    assign o_peak    = peak;

    // P: the high-water mark of the tile accumulator never climbs past 19,
    // even though the register is 5 bits wide (would allow 31): once it has
    // reached 19 it must never change again.
    always @(posedge i_clk)
        if (pv && ($past(peak) == 5'd19))
            assert ($stable(peak));
endmodule

module hwm_stack_ptr (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_push,
    input  wire       i_pop,
    output wire       o_deep,
    output wire [3:0] o_mark,
    output wire [3:0] o_sp
);
    localparam [3:0] THRESH = 4'd4;

    // stack pointer and its high-water mark
    reg [3:0] sp;
    reg [3:0] hwm;
    reg       mark_deep;   // registered "mark has crossed THRESH" flag
    reg       pv;          // past-valid

   // push/pop event ledger for depth accounting: every accepted push and
   // every accepted pop is logged, and the difference of the two counters
   // is the occupancy the mark logic trusts
   reg [3:0] n_push;
   reg [3:0] n_pop;

    initial sp        = 4'd0;
    initial hwm       = 4'd0;
    initial mark_deep = 1'b0;
    initial pv        = 1'b0;
   initial n_push    = 4'd0;
   initial n_pop     = 4'd0;

    wire do_push = i_ce && i_push && !i_pop && (sp != 4'hF);
    wire do_pop  = i_ce && i_pop  && !i_push && (sp != 4'h0);

    wire [3:0] sp_nx  = do_push ? (sp + 4'd1)
                      : (do_pop ? (sp - 4'd1) : sp);

   wire [3:0] n_push_nx = do_push ? (n_push + 4'd1) : n_push;
   wire [3:0] n_pop_nx  = do_pop  ? (n_pop  + 4'd1) : n_pop;

   // occupancy as seen by the ledger after this cycle's events
   wire [3:0] occ_nx    = n_push_nx - n_pop_nx;

   // the mark must cover both the pointer and the logged occupancy
   wire [3:0] mark_lo   = (sp_nx > occ_nx) ? sp_nx : occ_nx;

    // the mark never falls below the pointer and only ratchets upward
   wire [3:0] hwm_nx = (mark_lo > hwm) ? mark_lo : hwm;

    always @(posedge clk) begin
        if (i_ce) begin
            sp        <= sp_nx;
            hwm       <= hwm_nx;
            mark_deep <= (hwm_nx >= THRESH);
           n_push    <= n_push_nx;
           n_pop     <= n_pop_nx;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign o_deep = mark_deep;
    assign o_mark = hwm;
    assign o_sp   = sp;

    // Precedence: the deep-mark flag can only rise because the pointer itself
    // has just reached that depth, so the depth must be visible right now.
    always @(posedge clk)
        if (pv && $rose(mark_deep))
            assert (sp >= THRESH);

endmodule

module arb_lock_pending (
    input  wire       clk,
    input  wire       ce,      // global enable / idle when low
    input  wire [3:0] req,     // new requests, latched into pend
    input  wire       rel,     // current owner releases the lock
    output wire [3:0] grant,
    output wire [2:0] occupancy
);
    // pending request bitmap and its redundant occupancy counter
    reg [3:0] pend  = 4'b0000;
    reg [2:0] pcnt  = 3'd0;
   reg [2:0] bcnt  = 3'd0;   // bank B (indices 2,3) occupancy
    // fixed-priority arbiter with a lock bit freezing the winner
    reg       lock  = 1'b0;
    reg [1:0] owner = 2'd0;
    reg       pv    = 1'b0;   // past-valid

    // fixed priority: lowest index wins
wire [1:0] pick_a = pend[0] ? 2'd0 : 2'd1;
wire [1:0] pick_b = pend[2] ? 2'd2 : 2'd3;
// drain the fuller bank first; ties break toward bank A
wire       serve_b = (bcnt > pcnt);
wire [1:0] pick    = serve_b ? pick_b : pick_a;
    wire       any  = |pend;

    // service completion: the locked owner releases, its pending bit retires
    wire       do_clr   = ce && lock && rel;
    wire [3:0] clr_mask = do_clr ? (4'b0001 << owner) : 4'b0000;
    // only genuinely new requests are inserted
    wire [3:0] set_mask = ce ? (req & ~pend & ~clr_mask) : 4'b0000;
wire [2:0] nset_a   = set_mask[0] + set_mask[1];
wire [2:0] nset_b   = set_mask[2] + set_mask[3];
wire       dec_a    = do_clr && !owner[1];
wire       dec_b    = do_clr &&  owner[1];

    assign grant     = lock ? (4'b0001 << owner) : 4'b0000;
assign occupancy = pcnt + bcnt;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ce) begin
            pend <= (pend | set_mask) & ~clr_mask;
pcnt <= pcnt + nset_a - (dec_a ? 3'd1 : 3'd0);
bcnt <= bcnt + nset_b - (dec_b ? 3'd1 : 3'd0);
            if (lock) begin
                if (rel)
                    lock <= 1'b0;      // frozen winner until it releases
            end else if (any) begin
                lock  <= 1'b1;
                owner <= pick;
            end
        end
    end

    // P: if the pending bitmap did not change, the occupancy must not have
    // changed either, and the occupancy stays within its real bound of 4.
    always @(posedge clk)
        if (pv && $stable(pend))
            assert ($stable(pcnt) && (pcnt <= 3'd4));
endmodule

module gray_shadow_ctr (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    output wire [3:0] o_gray,
    output wire [3:0] o_bin
);
    // Binary shadow counter and its gray-coded twin.  The gray register is
    // advanced by the classic single-bit-toggle rule, computed from the gray
    // value alone; the binary shadow is a plain increment.
    reg [3:0] bin;
    reg [3:0] gray;
    reg       pv;
   reg [3:0] gray_s;
   reg       s_vld;

    initial bin  = 4'b0000;
    initial gray = 4'b0000;
    initial pv   = 1'b0;
   initial gray_s = 4'b0000;
   initial s_vld  = 1'b0;

    // Next gray value: toggle bit 0 when the parity is even, otherwise toggle
    // the bit just above the lowest set bit (with the top bit handling wrap).
    function [3:0] gnext(input [3:0] g);
        begin
            if (!(^g))     gnext = g ^ 4'b0001;
            else if (g[0]) gnext = g ^ 4'b0010;
            else if (g[1]) gnext = g ^ 4'b0100;
            else           gnext = g ^ 4'b1000;
        end
    endfunction

   // Stage 1: the gray pointer is advanced one cycle ahead of the output
   // registers, so o_gray leaves the block straight off a flop instead of
   // through the toggle-select network.  s_vld marks the staged word as a
   // pending advance that the commit stage still owes the outputs.
   always @(posedge clk) begin
       if (rst) begin
           gray_s <= 4'b0000;
           s_vld  <= 1'b0;
       end else begin
           s_vld <= i_ce;
           if (i_ce) gray_s <= gnext(gray_s);
       end
   end

   // Stage 2: commit the staged pointer and bump the binary shadow in the
   // same cycle, so the two views never disagree at the outputs.

    always @(posedge clk) begin
        if (rst) begin
            bin  <= 4'b0000;
            gray <= 4'b0000;
       end else if (s_vld) begin
            bin  <= bin + 4'b0001;
           gray <= gray_s;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign o_gray = gray;
    assign o_bin  = bin;

    // Top bit of the gray word and top bit of the binary shadow: the most
    // significant gray bit is just the most significant binary bit, so neither
    // may move without the other.
    wire g_msb = gray[3];
    wire b_msb = bin[3];

    // P: whenever the gray MSB did not change, the shadow MSB did not change.
    always @(posedge clk)
        if (pv && $stable(g_msb))
            assert ($stable(b_msb));
endmodule

module csa_accum_parity (
    input  wire       clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_clear,
    input  wire [7:0] i_data,
    output wire [7:0] o_total,
    output wire [7:0] o_ref
);
    // accumulator kept in carry-save form: two halves that always sum to the
    // true running total held in the reference register
    reg [7:0] acc_s = 8'h00;   // sum half
    reg [7:0] acc_c = 8'h00;   // carry half (always even by construction)
    reg [7:0] total = 8'h00;   // plain ripple-carry reference accumulator
    reg        hi_flag = 1'b0; // registered "total has reached the upper half";
                               // precomputed on the adder result so the flush
                               // path next cycle is just a flop-to-mux hop

    wire [7:0] sum_bits   = acc_s ^ acc_c ^ i_data;
    wire [7:0] maj_bits   = (acc_s & acc_c) | (acc_s & i_data) | (acc_c & i_data);
    wire [7:0] carry_bits = {maj_bits[6:0], 1'b0};
    wire [7:0] next_total = total + i_data;

    always @(posedge clk) begin
        if (i_rst) begin
            acc_s <= 8'h00;
            acc_c <= 8'h00;
            total <= 8'h00;
            hi_flag <= 1'b0;
        end else if (i_ce) begin
            if (i_clear || hi_flag) begin
                acc_s <= 8'h00;
                acc_c <= 8'h00;
                total <= 8'h00;
                hi_flag <= 1'b0;
            end else begin
                acc_s <= sum_bits;
                acc_c <= carry_bits;
                total   <= next_total;
                hi_flag <= next_total[7];
            end
        end
    end

    assign o_total = acc_s + acc_c;
    assign o_ref   = total;

    // P: while the unit is actually accumulating, the low bit of the sum half
    // alone already carries the parity of the true total.
    always @(posedge clk)
        if (i_ce && !i_clear)
            assert (acc_s[0] == total[0]);

    // P2: the flush flag was computed from the adder result, so it must still
    // describe the value the carry-save side is currently reporting.
    always @(posedge clk)
        assert (hi_flag == o_total[7]);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
output reg  o_clean,
output reg [3:0] o_evt_cnt
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;
   localparam       CH_A = 1'b0;  // commit-stage owner encoding
   localparam       CH_B = 1'b1;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
reg       cmt_ch   = 1'b0;  // which channel owns the commit stage
reg       q_pend   = 1'b0;  // queued commit sitting behind the head slot
reg       q_val    = 1'b0;  // sample value waiting in the queued slot
reg       q_ch     = 1'b0;  // which channel owns the queued slot
reg       wb_pend  = 1'b0;  // writeback slot: entry retired by the head
reg       wb_val   = 1'b0;  // sample value being applied this step
reg       wb_ch    = 1'b0;  // which channel owns the writeback slot
reg       samp_b   = 1'b0;  // last accepted arm-button sample
reg [2:0] cnt_b    = 3'd0;  // arm-button stability counter, saturates at K
reg       arm_clean = 1'b0; // debounced arm-button level
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid
   reg [3:0] evt_cnt  = 4'd0;  // distractor: counts disagreeing input steps

// Two commit slots were budgeted (a head that retires and one queued tail);
// the channels arbitrate for a free slot, the raw-sample channel wins a tie.
   wire a_chg   = (i_raw != samp);
   wire b_chg   = (i_arm != samp_b);
   wire a_req   = !a_chg && (cnt   == K - 3'd1);
   wire b_req   = !b_chg && (cnt_b == K - 3'd1);
wire q_full  = cmt_pend && q_pend;
wire grant_a = !q_full && a_req;
wire grant_b = !q_full && b_req && !a_req;
wire grant   = grant_a || grant_b;
wire new_val = grant_a ? samp : samp_b;
wire new_ch  = grant_a ? CH_A : CH_B;
// a queued raw-sample commit is stale the moment the sample moves again
wire keep_q  = q_pend && !(q_ch == CH_A && a_chg);

    initial o_clean = 1'b0;
   initial o_evt_cnt = 4'd0;
   initial evt_cnt   = 4'd0;

    always @(posedge clk)
        pv <= 1'b1;

   always @(posedge clk) begin
       if (i_ce) begin
           if (i_raw ^ i_arm)
               evt_cnt <= evt_cnt + 4'd1;
           o_evt_cnt <= evt_cnt ^ {3'b000, i_disarm};
       end
   end

    always @(posedge clk) begin
        if (i_ce) begin
           // ---- channel A: the raw sample ----
           if (a_chg) begin
               // sample changed: restart the stability count
               samp     <= i_raw;
               cnt      <= 3'd0;
               stable_f <= 1'b0;
           end else if (cnt != K) begin
               if (!a_req) begin
                   cnt <= cnt + 3'd1;
               end else if (grant_a) begin
// take a commit slot; the flag and output move one step later
                   cnt      <= cnt + 3'd1;
               end
// both slots busy: hold at K-1 and retry once one frees
           end

           // ---- channel B: the arm button, same filter, same stage ----
           if (b_chg) begin
               samp_b <= i_arm;
               cnt_b  <= 3'd0;
           end else if (cnt_b != K) begin
               if (!b_req) begin
                   cnt_b <= cnt_b + 3'd1;
               end else if (grant_b) begin
                   cnt_b    <= cnt_b + 3'd1;
               end
           end
           // ---- writeback slot: applies the entry retired one step ago ----
           if (wb_pend) begin
               if (wb_ch == CH_A) begin
                   if (!a_chg) begin
                       o_clean  <= wb_val;   // commit the debounced value
                       stable_f <= 1'b1;
                   end
               end else if (!b_chg) begin
                   arm_clean <= wb_val;
               end
           end
           // the head hands its entry to the writeback slot; an entry whose
           // sample moved again in the meantime is dropped instead
           wb_pend <= cmt_pend && !(cmt_ch == CH_A && a_chg)
                               && !(cmt_ch == CH_B && b_chg);
           wb_val  <= cmt_val;
           wb_ch   <= cmt_ch;

           // ---- shared stage: retires one entry per enabled step ----
           if (cmt_pend) begin
// the head always retires: the queued tail shifts up and a fresh
// grant lands in whichever slot is left over
cmt_pend <= keep_q || grant;
cmt_val  <= keep_q ? q_val : new_val;
cmt_ch   <= keep_q ? q_ch  : new_ch;
q_pend   <= keep_q && grant;
q_val    <= new_val;
q_ch     <= new_ch;
           end
else begin
cmt_pend <= grant;
cmt_val  <= new_val;
cmt_ch   <= new_ch;
q_pend   <= 1'b0;
end

            if (i_disarm)
                armed <= 1'b0;
           else if (arm_clean)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

// In-flight tracker for a fixed-latency chart-query render pipeline.
// Each issued query walks a 4-stage valid shift register; occupancy is the
// number of ones currently resident in that shift register.
module query_pipe_tracker (
    input  wire       clk,
    input  wire       ce,        // pipeline advance / idle control
    input  wire       issue,     // a new query is pushed into stage 0
    output wire       retire,    // a rendered result leaves the last stage
    output wire       full,      // tracker says all 4 slots are busy
output reg  [2:0] occ,       // queries in flight
output reg  [3:0] retire_cnt // rolling count of retired queries
);

    reg [3:0] pipe;              // fixed-latency valid shift register
   reg [1:0] apipe;             // 2-stage cached-result render path
reg       stg;               // entry stage: admitted query registered before stage 0
    reg       hold;              // input capture slot: query admitted while stalled
    reg       ever_issued;       // shadow: an issue has been observed earlier
    reg       armed;             // scope: still before the pipe was ever full
reg       retire_seen;        // sticky: at least one retirement observed

    initial begin
        pipe        = 4'b0000;
        occ         = 3'd0;
        ever_issued = 1'b0;
        armed       = 1'b1;
        hold        = 1'b0;
       apipe       = 2'b00;
stg         = 1'b0;
retire_cnt  = 4'd0;
retire_seen = 1'b0;
    end

   assign retire = pipe[3] || apipe[1];
    assign full   = (occ == 3'd4);

    // Admission control: the tracker backpressures at capacity, and a query
    // taken while the pipe is not advancing waits in the capture slot.
    wire room   = (occ != 3'd4);
    wire accept = issue && !hold && room;   // query admitted this cycle
    wire inject = hold || accept;           // entry pushed into stage 0
   // A query offered while the capture slot is still busy is served from the
   // result cache instead: shorter path, same 4-slot occupancy budget.
   wire aux_accept = ce && issue && hold && room;

    always @(posedge clk) begin
        if (ce) begin
            // drain: stage 3 retires, everything shifts, stage 0 takes issue
pipe <= {pipe[2:0], stg};
stg  <= inject;

            // occupancy bookkeeping: +1 on issue, -1 on retire
           occ  <= occ + {2'b00, accept} + {2'b00, aux_accept}
                       - {2'b00, pipe[3]} - {2'b00, apipe[1]};
           apipe <= {apipe[0], aux_accept};
            hold <= 1'b0;

            // shadow register for the earlier event
           if (accept || aux_accept) ever_issued <= 1'b1;

            // scope closes the first time the unit reports saturation
            if (full)  armed <= 1'b0;
        end else if (accept) begin
            // stalled: park the admitted query and count it as in flight
            hold        <= 1'b1;
            occ         <= occ + 3'd1;
            ever_issued <= 1'b1;
        end
    end

    // Precedence, before the unit was ever full:
    // if work is in flight now, an issue must have happened earlier.
    always @(posedge clk)
        if (armed && occ != 3'd0)
            assert (ever_issued);

// Distractor telemetry: counts retirements, observed by nothing else.
always @(posedge clk) begin
   if (ce && retire) begin
        retire_seen <= 1'b1;
        retire_cnt  <= retire_cnt + (retire_seen ? 4'd2 : 4'd1);
    end
end

endmodule

module parity_slice_occ (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_data,
    output reg        o_valid,
    output reg  [7:0] o_data,
    output reg        o_retry
);
    // two-deep register slice, each stage protected by a parity bit
    reg [7:0] d0, d1;
    reg       p0, p1;
   // per-nibble parity: p0/p1 cover bits [3:0] and the h companions bits [7:4],
   // so a reported mismatch localises the fault to one half-word
   reg       p0h, p1h;
    reg       v0, v1;

    // occupancy accounting: one 3-bit counter tracking live stages
    reg [2:0] occ;

   // egress check: the word presented on the output register keeps its slice
   // slot for one more cycle while its parity is re-checked, so the credit is
   // returned one cycle after the word leaves
   reg       oq_busy;
   reg       oq_par;
  reg       oq_parh;

  // sideband echo lane: a control word tagged with bit 6 is parked here and
  // replayed onto the output whenever the data lane's second stage is empty.
  // It draws its slot from the same occupancy pool as the data lane.
  reg [7:0] sb_d;
  reg       sb_p;
 reg       sb_ph;
  reg       sb_v;

   // programmable slot limit (one or two stages), written by a control word
   reg [2:0] lim;

  // replay bookkeeping: every parity mismatch books one replay slot, and a
  // booked slot is handed back when the egress re-check frees a credit
  reg [2:0] rpy;

    initial begin
        d0 = 8'h00; d1 = 8'h00;
        p0 = 1'b0;  p1 = 1'b0;
       p0h = 1'b0; p1h = 1'b0;
        v0 = 1'b0;  v1 = 1'b0;
        occ = 3'd0;
       oq_busy = 1'b0;
       oq_par  = 1'b0;
      oq_parh = 1'b0;
       sb_d = 8'h00; sb_p = 1'b0; sb_v = 1'b0;
      sb_ph = 1'b0;
       lim     = 3'd2;
      rpy     = 3'd0;
        o_valid = 1'b0;
        o_data  = 8'h00;
        o_retry = 1'b0;
    end

    // stored parity is checked against stored data every cycle
   wire mism0 = v0 && ((p0 != (^d0[3:0])) || (p0h != (^d0[7:4])));
   wire mism1 = v1 && ((p1 != (^d1[3:0])) || (p1h != (^d1[7:4])));
wire mismsb = sb_v && ((sb_p != (^sb_d[3:0])) || (sb_ph != (^sb_d[7:4])));
wire retry  = mism0 || mism1 || mismsb;

   // the slot is only released when the egress parity re-check is clean
  wire oq_bad = oq_busy && ((oq_par != (^o_data[3:0])) || (oq_parh != (^o_data[7:4])));
   wire rel    = oq_busy && !oq_bad;

   // control words carry the depth limit instead of payload
   wire cfg  = i_valid && i_data[7];
   wire room = occ < lim;
   wire acc  = i_valid && !cfg && room;
   wire nack = i_valid && !cfg && !room;
  // echo lane arbitration: the parked word only reaches the egress slot when
  // the data lane's second stage is empty, so the lanes never collide
  wire echo    = cfg && i_data[6];
  wire sb_acc  = echo && !sb_v && room;
  wire sb_nack = echo && (sb_v || !room);
  wire sb_go   = sb_v && !v1;

    always @(posedge clk) begin
        if (i_ce) begin
o_retry <= retry || nack || sb_nack || oq_bad || (rpy != 3'd0);
            if (retry) begin
                // corrupted stage: freeze the slice and book a replay slot
                occ <= occ + 3'd1;
               rpy <= rpy + 3'd1;
            end else begin
                // normal shift: stage0 -> stage1 -> output
                d1 <= d0;
                p1 <= p0;
               p1h <= p0h;
                v1 <= v0;
                d0 <= i_data;
               p0  <= ^i_data[3:0];
               p0h <= ^i_data[7:4];
               v0 <= acc;
oq_busy <= v1 || sb_go;
oq_par  <= v1 ? p1 : sb_p;
oq_parh <= v1 ? p1h : sb_ph;
sb_v <= sb_acc || (sb_v && !sb_go);
if (sb_acc) begin
    sb_d <= i_data;
   sb_p  <= ^i_data[3:0];
   sb_ph <= ^i_data[7:4];
end
if (cfg && !echo) lim <= i_data[0] ? 3'd2 : 3'd1;
occ <= occ + (acc ? 3'd1 : 3'd0) + (sb_acc ? 3'd1 : 3'd0) - (rel ? 3'd1 : 3'd0);
              if (rel && rpy != 3'd0) rpy <= rpy - 3'd1;
o_valid <= v1 || sb_go;
o_data  <= v1 ? d1 : sb_d;
            end
        end
    end

    // bounded existence: the slice is two deep, so occupancy never exceeds 2
    always @(*) assert (occ <= 3'd2);

   // a replay slot is only booked on a real corruption, so booked slots plus
   // live slice slots never oversubscribe the two-deep slice
   always @(posedge clk)
       assert ({1'b0, occ} + {1'b0, rpy} <= 4'd2);
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
    output wire [2:0] o_inflight
);
// fixed-latency (6 cycle) pipeline occupancy shift register
reg [5:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;
// remaining issue credits: an op is only taken while credits are left
reg [2:0] cred;
// currently programmed outstanding-op limit, retuned at each quiesce point
reg [2:0] lim;
// congestion flag: enable dropped while work was still in flight
reg       thr;
// credit-return path: a retired op's credit takes four more cycles to walk
// back from the pipe tail to the issue-side credit counter
reg       rq0;
reg       rq1;
reg       rq2;
reg       rq3;
// returned credits wait here until the credit counter's write port is free
reg [2:0] rtn;
// merge stage: a credit leaving the park register spends one cycle in this
// flop before it is written into the issue-side credit counter
reg       mrg;

initial pipe     = 6'b000000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;
initial cred     = 3'd4;
initial lim      = 3'd4;
initial thr      = 1'b0;
initial rq0      = 1'b0;
initial rq1      = 1'b0;
initial rq2      = 1'b0;
initial rq3      = 1'b0;
initial rtn      = 3'd0;
initial mrg      = 1'b0;

wire retire  = pipe[5];
// credit gate on the issue path
wire accept  = issue && (cred != 3'd0);
// nothing still travelling back down the credit-return path
wire rq_empty = !(rq0 || rq1 || rq2 || rq3);
// at most one parked credit is merged back per cycle, and only on cycles
// where the issue side is not already updating the credit counter
wire drain = (rtn != 3'd0) && !accept;
// true quiesce: pipe drained, returns landed, nothing arriving this cycle
wire quiesce = (pipe == 6'b000000) && rq_empty && !issue;

    always @(posedge clk) begin
        if (rst) begin
pipe     <= 6'b000000;
            inflight <= 3'd0;
        end else if (i_ce) begin
pipe     <= {pipe[4:0], accept};
inflight <= inflight + {2'b00, accept} - {2'b00, retire};
        end
    end
// credit accounting and outstanding-limit retuning
always @(posedge clk) begin
    if (rst) begin
        cred <= 3'd4;
        lim  <= 3'd4;
        thr  <= 1'b0;
        rtn  <= 3'd0;
mrg  <= 1'b0;
    end else if (i_ce) begin
        if (quiesce) begin
            lim  <= thr ? 3'd2 : 3'd4;
            cred <= thr ? 3'd2 : 3'd4;
            thr  <= 1'b0;
            rtn  <= 3'd0;
mrg  <= 1'b0;
        end else begin
cred <= cred - {2'b00, accept} + {2'b00, mrg};
            rtn  <= rtn + {2'b00, rq3} - {2'b00, drain};
mrg  <= drain;
        end
    end else if (pipe != 6'b000000) begin
        thr  <= 1'b1;
    end
end

// credit-return path: retire pulses shift back toward the issue side
always @(posedge clk) begin
    if (rst) begin
        rq0 <= 1'b0;
        rq1 <= 1'b0;
        rq2 <= 1'b0;
        rq3 <= 1'b0;
    end else if (i_ce) begin
        rq0 <= retire;
        rq1 <= rq0;
        rq2 <= rq1;
        rq3 <= rq2;
    end
end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

    reg [3:0] nxt;

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
            else if (nxt == S_ROUTE)
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);
endmodule

module pcb_pool_top (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] ce,
    input  wire [5:0] start,
    input  wire [5:0] route_ok,
    input  wire [5:0] ack,
    output reg  [3:0] pool,     // free router-engine seats
    output reg  [5:0] hold,     // per-board seat ownership
    output wire [5:0] window    // per-board routing window (tracking)
);
    // Six board flows share a pool of six router/DRC engine seats.
    localparam [3:0] TOTAL = 4'd6;

    wire [3:0] s0, s1, s2, s3, s4, s5;
    wire [7:0] m0, m1, m2, m3, m4, m5;
    wire       t0, t1, t2, t3, t4, t5;

    wire h0 = hold[0];
    wire h1 = hold[1];
    wire h2 = hold[2];
    wire h3 = hold[3];
    wire h4 = hold[4];
    wire h5 = hold[5];

    assign window = {t5, t4, t3, t2, t1, t0};
    // Grants are registered: the seat is booked one cycle after the arbiter
    // picks a winner, so the seat already in flight must be accounted for.
    reg  [5:0] gnt_q;
    wire       q_any = |gnt_q;
// Booking is two-phase: the arbiter parks its winner in gnt_p, and the seat
// is charged to the pool on that board's next enabled cycle. The parking
// station holds one grant, so the arbiter stalls while it is occupied.
reg  [5:0] gnt_p;
wire       p_any = |gnt_p;
wire [5:0] book  = gnt_p & ce;   // parked grant commits on the owner's step
// Occupancy shadow: seats currently charged out, maintained alongside the
// pool so the arbiter's credit check is one compare against TOTAL.
reg  [3:0] used;
// Returns are retimed by one step: the six-way release popcount is
// registered here and applied to the occupancy shadow on the following
// cycle, which keeps that adder out of the credit comparator's cone. The
// pool is a status count outside the arbiter path and still absorbs
// releases immediately, so the shadow trails it by whatever is parked here.
reg  [2:0] ret;

    pcb_flow_fsm u0 (.clk(clk), .rst(rst), .ce(ce[0]), .start(start[0]),
                     .route_ok(route_ok[0]), .ack(ack[0]),
                     .state(s0), .mirror(m0), .tracking(t0));
    pcb_flow_fsm u1 (.clk(clk), .rst(rst), .ce(ce[1]), .start(start[1]),
                     .route_ok(route_ok[1]), .ack(ack[1]),
                     .state(s1), .mirror(m1), .tracking(t1));
    pcb_flow_fsm u2 (.clk(clk), .rst(rst), .ce(ce[2]), .start(start[2]),
                     .route_ok(route_ok[2]), .ack(ack[2]),
                     .state(s2), .mirror(m2), .tracking(t2));
    pcb_flow_fsm u3 (.clk(clk), .rst(rst), .ce(ce[3]), .start(start[3]),
                     .route_ok(route_ok[3]), .ack(ack[3]),
                     .state(s3), .mirror(m3), .tracking(t3));
    pcb_flow_fsm u4 (.clk(clk), .rst(rst), .ce(ce[4]), .start(start[4]),
                     .route_ok(route_ok[4]), .ack(ack[4]),
                     .state(s4), .mirror(m4), .tracking(t4));
    pcb_flow_fsm u5 (.clk(clk), .rst(rst), .ce(ce[5]), .start(start[5]),
                     .route_ok(route_ok[5]), .ack(ack[5]),
                     .state(s5), .mirror(m5), .tracking(t5));

    // A board wants a seat while its window is armed; it gives the seat back
    // on its next enabled cycle after the export has been acknowledged.
wire [5:0] req = window & ~hold & ~gnt_q & ~gnt_p & ce;
    wire [5:0] rel = ~window &  hold & ce;

    // Fixed-priority arbiter: at most one seat handed out per cycle.
wire [3:0] inflight    = {3'b0, p_any} + {3'b0, q_any};
wire [4:0] occ         = {1'b0, used} + {1'b0, inflight};
wire       have_credit = (occ < {1'b0, TOTAL});
    wire [5:0] pri;
    assign pri[0] = req[0];
    assign pri[1] = req[1] & ~req[0];
    assign pri[2] = req[2] & ~(|req[1:0]);
    assign pri[3] = req[3] & ~(|req[2:0]);
    assign pri[4] = req[4] & ~(|req[3:0]);
    assign pri[5] = req[5] & ~(|req[4:0]);

wire [5:0] gnt     = (have_credit && !p_any) ? pri : 6'b0;

    wire [2:0] rel_cnt = {2'b0, rel[0]} + {2'b0, rel[1]} + {2'b0, rel[2]} +
                         {2'b0, rel[3]} + {2'b0, rel[4]} + {2'b0, rel[5]};

    initial begin
        pool = TOTAL;
        hold = 6'd0;
    gnt_q = 6'd0;
gnt_p = 6'd0;
used = 4'd0;
ret = 3'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
            hold <= 6'd0;
    gnt_q <= 6'd0;
gnt_p <= 6'd0;
used <= 4'd0;
ret <= 3'd0;
        end else begin
    hold <= (hold | gnt_q) & ~rel;
    pool <= pool - {3'b0, q_any} + {1'b0, rel_cnt};
gnt_q <= book;
gnt_p <= (gnt_p & ~book) | gnt;
used <= used + {3'b0, q_any} - {1'b0, ret};
ret  <= rel_cnt;
        end
    end

    // Pool property: if no seat is free, every board must be holding one.
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 && h1 && h2 && h3 && h4 && h5);
    // Hand-off property: a registered grant is always backed by a seat that
    // was still free when the arbiter committed it, so the pool is never
    // empty while a grant is landing.
    always @(posedge clk)
        if (gnt_q != 6'd0)
            assert (pool != 4'd0);
    // Occupancy property: with every board seated the pool is fully charged
    // out and the parking station must be empty -- there is no seat left for
    // the arbiter to have booked.
    always @(posedge clk)
        if (hold == 6'b111111)
            assert (used == TOTAL && gnt_p == 6'd0);
endmodule

module seq_detect_1011 (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output wire       match,
    output wire [3:0] hits
);
    // fixed pattern, MSB first: 1 0 1 1
    localparam [3:0] PAT = 4'b1011;

    // match-progress register: number of leading pattern bits matched so far,
    // never exceeds the pattern length (4)
    reg [2:0] prog;
    // shadow register: records that progress 3 (pattern prefix 101) was
    // observed at some earlier cycle
    reg       saw_p3;
    // saturating count of completed pattern matches consumed
    reg [3:0] match_count;
   // commit-stage flag: a detected match is posted here and lands in the
   // counter on the next enabled cycle, keeping the counter adder off the
   // detector's critical path
   reg       cmt_vld;

  // sticky saturation lock: if the counter is already topped out when a
  // match credit retires, the credit is dropped and the reading is frozen,
  // so software can tell "exactly 15" from "15 or more"
  reg       sat_lock;
 // census of match credits that retired into an already-locked counter;
 // firmware uses it to bound how far the frozen reading undercounts
 reg [3:0] drop_cnt;
// credit ledger: posted credits and retired credits are tallied on
// separate free-running counters so firmware can read back, by
// subtraction, how many credits are still in flight in the commit stage
reg [3:0] post_cnt;
reg [3:0] rtr_cnt;
// match-window ledger: the opening of a detection window (the scan is
// about to reach full pattern length) and its closing are logged on
// separate free-running counters, so firmware can read back by
// subtraction whether a window is currently parked in the scan register;
// the commit stage sources its credits from this ledger, which keeps the
// posting decision independent of the scan register's own decode
reg [3:0] mw_opn;
reg [3:0] mw_cls;
// saturation full-detect, sampled when the credit is posted so the
// 15-compare sits off the lock path; the lock engages when the armed
// credit retires one enabled cycle later
reg       lock_arm;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;
   initial cmt_vld     = 1'b0;
  initial sat_lock    = 1'b0;
 initial drop_cnt    = 4'd0;
initial post_cnt    = 4'd0;
initial rtr_cnt     = 4'd0;
initial mw_opn      = 4'd0;
initial mw_cls      = 4'd0;
initial lock_arm    = 1'b0;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
    wire       restart  = (din == PAT[3]) ? 1'b1 : 1'b0;
   // overflow park: once the census tops out the scan is frozen so the
   // count, the census and the detector state stay mutually consistent
   wire       park     = (drop_cnt == 4'd15);
// a detection window is parked in the scan register right now
wire       win_open = (mw_opn != mw_cls);
// a credit retires when the commit stage presents it, or when the ledger
// still shows one outstanding after the commit flag was dropped
wire       retire   = cmt_vld || (post_cnt != rtr_cnt);

    assign match = (prog == 3'd4);
    assign hits  = match_count;

    always @(posedge clk) begin
        if (rst) begin
            prog        <= 3'd0;
            saw_p3      <= 1'b0;
            match_count <= 4'd0;
           cmt_vld     <= 1'b0;
          sat_lock    <= 1'b0;
         drop_cnt    <= 4'd0;
post_cnt    <= 4'd0;
rtr_cnt     <= 4'd0;
mw_opn      <= 4'd0;
mw_cls      <= 4'd0;
lock_arm    <= 1'b0;
       end else if (ce && !park) begin
            // shadow bit latches the earlier occurrence of progress 3
            saw_p3 <= saw_p3 | (prog == 3'd3);
           // post a credit for a completed match; retire the credit posted
           // by the previous enabled cycle
cmt_vld <= win_open;
// ledger sides: log the posting event and the retiring event
post_cnt <= post_cnt + (win_open ? 4'd1 : 4'd0);
rtr_cnt  <= rtr_cnt  + (retire ? 4'd1 : 4'd0);
// window ledger sides: log the opening and the closing of each window
mw_opn <= mw_opn + (((prog == 3'd3) && (din == exp_bit)) ? 4'd1 : 4'd0);
mw_cls <= mw_cls + ((prog == 3'd4) ? 4'd1 : 4'd0);
// arm the lock together with the credit it belongs to
lock_arm <= win_open && (match_count == 4'd15);
if (retire)
sat_lock <= sat_lock | lock_arm;
if (retire && !sat_lock)
               match_count <= (match_count == 4'd15) ? 4'd15 : match_count + 4'd1;
         // tally the credit we just threw away; the park above guarantees
         // this adder cannot wrap
if (retire && sat_lock)
             drop_cnt <= drop_cnt + 4'd1;


            if (prog == 3'd4) begin
                // consume the completed match, then begin a fresh scan
                prog        <= restart ? 3'd1 : 3'd0;
            end else if (din == exp_bit) begin
                prog <= prog + 3'd1;
            end else begin
                prog <= restart ? 3'd1 : 3'd0;
            end
        end
    end

    // Precedence, global: any counted match must have been preceded by the
    // pattern prefix reaching progress 3.
    assert property (match_count == 4'd0 || saw_p3);

   // Saturation lock is a consequence of counted traffic: it can only engage
   // after the counter has been driven to full, so the exported count is
   // nonzero and the pattern prefix must already have been seen.
   always @(posedge clk)
       assert (!sat_lock || (saw_p3 && hits != 4'd0));
  // Credits are only discarded against a full, locked counter, so any
  // nonzero census means the exported reading is pinned at maximum and the
  // pattern prefix was seen long ago.
  always @(posedge clk)
      assert (drop_cnt == 4'd0 || (saw_p3 && hits == 4'd15));
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
   // launch flop on the gray encoder: the crossing wires are driven
   // point to point instead of straight off the encoder cone
   reg [3:0] gq;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;
   // programmable ring bound: the bridge starts at quarter span after reset and
   // opens up one binary step per four completed laps
   reg [3:0] lim;
   reg [1:0] laps;
  // read-side pointer of the same ring: one data word takes two destination
  // beats, so it advances on alternate enables.  it shares the programmable
  // ring bound with the write pointer.
  reg [3:0] cnt2;
  reg [3:0] g2;
  reg       ph;
 // completion pointer of the same ring: the consumer retires a word on the
 // opposite half beat, so this one steps when the read phase is low.  it uses
 // the same programmable ring bound as the write and read pointers.
 reg [3:0] cnt3;
 reg [3:0] g3;
 // the crossing lane is a single physical 4-bit bundle, so the three pointers
 // take turns on it under a one-hot grant that rotates.  the turn is handed
 // over only at the common origin, where every encoder reads zero and the
 // lane sees no step on the bundle.
 reg [2:0] own;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
       gq  = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
       lim  = 4'd3;
       laps = 2'd0;
      cnt2 = 4'd0;
      g2   = 4'd0;
      ph   = 1'b0;
     cnt3 = 4'd0;
     g3   = 4'd0;
     own  = 3'b001;
    end

   wire       wrap     = (cnt >= lim);
   wire [3:0] nxt      = wrap ? 4'd0 : cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);
  wire       wrap2      = (cnt2 >= lim);
  wire [3:0] nxt2       = wrap2 ? 4'd0 : cnt2 + 4'd1;
  wire [3:0] nxt_gray2  = nxt2 ^ (nxt2 >> 1);
  wire       tick2      = ph;
 wire       wrap3      = (cnt3 >= lim);
 wire [3:0] nxt3       = wrap3 ? 4'd0 : cnt3 + 4'd1;
 wire [3:0] nxt_gray3  = nxt3 ^ (nxt3 >> 1);
 wire       tick3      = ~ph;
 wire       swap       = (cnt == 4'd0) && (cnt2 == 4'd0) && (cnt3 == 4'd0);
 // one-hot grant onto the shared bundle: each encoder is masked by its grant
 // bit and the three masked copies are or-ed onto the lane
 wire [3:0] lane       = (own[0] ? g : 4'd0) | (own[1] ? g2 : 4'd0) | (own[2] ? g3 : 4'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
          gq  <= lane;
           s1  <= gq;
            s2  <= s1;
          ph  <= ~ph;
          if (tick2) begin
              cnt2 <= nxt2;
              g2   <= nxt_gray2;
          end
         if (tick3) begin
             cnt3 <= nxt3;
             g3   <= nxt_gray3;
         end
          if (swap)
             own <= {own[1:0], own[2]};
           if (wrap) begin
               laps <= laps + 2'd1;
               if (laps == 2'd3)
                   lim <= {lim[2:0], 1'b1};
           end
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
   assign o_settled = (diff == 4'd0) && (gq == s1);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module gray_deadline_tracker (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       req,       // request pulse
    output wire [3:0] o_gray,
    output wire [3:0] o_bin,
    output wire [3:0] o_timer,
    output wire       o_busy,
    output wire       o_on_time
);
    // ---- gray counter with its binary shadow -------------------------
    reg [3:0] bin;
    reg [3:0] gray;

   // The binary->gray conversion is pipelined: the encoder runs one
// increment ahead of the visible counter; behind it a four-deep
// prefetch chain holds the next four encodings, so the adder and the
// XOR network run six counts ahead and every register in the chain --
// including the output register -- is fed straight out of a register.
reg [2:0] gray_pre;     // in-flight gray code for bin+1, low bits
// Bit 3 of a gray code is just bit 3 of the binary count, so the top
// bit skips the XOR network entirely and lives in its own register.
// It is only reloaded on the two counts where it can change, which
// keeps it from toggling with the rest of the pipeline.
reg       gray_pre_top;
// prefetch chain: pre-encoded gray codes waiting to be shifted into
// the stage-1 registers, oldest (nearest the output) first.
reg [3:0] gray_pre2;    // gray code queued for bin+2
reg [3:0] gray_pre3;    // gray code queued for bin+3
reg [3:0] gray_pre4;    // gray code queued for bin+4
reg [3:0] gray_pre5;    // gray code queued for bin+5

    // ---- bounded-response deadline machinery -------------------------
    reg [3:0] timer;      // countdown for the outstanding request
    reg       busy;       // request outstanding
    reg [3:0] goal_gray;  // gray code the counter should show at completion
   reg [3:0] goal_pre;   // deadline gray code, encoded K counts ahead
    reg       armed;      // sticky: set the first time a request is seen

    reg       pv;         // past valid

    localparam [3:0] K = 4'd8;   // response bound

    initial begin
        bin       = 4'd0;
        gray      = 4'd0;
gray_pre     = 3'd1;   // encoder prefilled with gray(bin+1)[2:0]
gray_pre_top = 1'b0;   // ... and its top bit
gray_pre2    = 4'd3;   // prefetch chain prefilled with gray(bin+2..5)
gray_pre3    = 4'd2;
gray_pre4    = 4'd6;
gray_pre5    = 4'd7;
        timer     = 4'd0;
        busy      = 1'b0;
        goal_gray = 4'd0;
       goal_pre  = 4'd12;   // gray(0 + K)
        armed     = 1'b0;
        pv        = 1'b0;
    end

    wire [3:0] bin_nxt  = bin + 4'd1;
   wire [3:0] bin_ahead  = bin_nxt + 4'd1;
// deepest lookahead: the count whose encoding enters the chain now
wire [3:0] bin_la     = bin + 4'd6;
wire [3:0] gray_la    = bin_la ^ (bin_la >> 1);
// the held top bit only needs a new value as the count rolls into 8 or 0
wire       top_load  = (bin_ahead[2:0] == 3'd0);

// The deadline encoder runs alongside the counter so the accept path
// does not have to carry an adder and an XOR network in the same
// cycle: goal_pre always holds the code the counter will show K
// counts from now, and accept just latches it.
wire [3:0] goal_bin      = bin_nxt + K;
wire [3:0] goal_gray_nxt = goal_bin ^ (goal_bin >> 1);

    wire accept = i_ce && armed && req && !busy;
    wire tick   = i_ce && busy;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            // gray counter advances together with its binary shadow
            bin  <= bin_nxt;
gray_pre  <= gray_pre2[2:0];
if (top_load) gray_pre_top <= gray_pre2[3];
gray     <= {gray_pre_top, gray_pre};
// the prefetch chain shifts one encoding per count
gray_pre2 <= gray_pre3;
gray_pre3 <= gray_pre4;
gray_pre4 <= gray_pre5;
gray_pre5 <= gray_la;
           // deadline encoder keeps pace with the counter
           goal_pre <= goal_gray_nxt;

            // sticky arm: first request ever seen arms the monitor forever
            if (req) armed <= 1'b1;

            if (accept) begin
                busy      <= 1'b1;
                timer     <= K;
               goal_gray <= goal_pre;
            end else if (busy) begin
                if (timer == 4'd1) begin
                    // completion lands exactly on the deadline tick
                    busy  <= 1'b0;
                    timer <= 4'd0;
                end else begin
                    timer <= timer - 4'd1;
                end
            end
        end
    end

    assign o_gray    = gray;
    assign o_bin     = bin;
    assign o_timer   = timer;
    assign o_busy    = busy;
    assign o_on_time = busy && (gray == goal_gray);

    // P: after the monitor is armed, while a request is outstanding the
    // deadline countdown may only move when the gray counter moves --
    // it can never silently run down toward expiry.
    always @(posedge clk)
        if (pv && armed && busy && $stable(gray))
            assert ($stable(timer));

   // P2: the on-time flag marks the deadline count itself -- the
   // tracked request is due exactly when the counter reaches the
   // latched goal code.
   always @(posedge clk)
       assert (o_on_time == (busy && (timer == 4'd1)));
endmodule

// Tracks outstanding memory requests issued into a 4-deep load/store pipeline.
// A shift register records which pipeline stages hold a live request; a separate
// counter tracks how many are in flight.
module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,   // pipeline advance / clock-enable
    input  wire       req,    // a new request is issued into stage 0
    output wire       f_idle, // no requests outstanding (from the counter)
    output wire       f_full, // all pipeline slots occupied (from the counter)
    output wire       f_any,  // some stage holds a request (from the shifter)
    output wire       f_slot  // some stage is free (from the shifter)
);

    reg [3:0] inflight;
    reg [2:0] cnt;
reg       issue;                // request launch register (input -> stage 0)
reg [1:0] bcnt;                 // back-half occupancy (stage 3 only)
reg       hand;                 // request in the stage1 -> stage2 handover
reg [3:0] n_in;                 // ledger: requests accepted at the input port
reg [3:0] n_out;                // ledger: requests retired out of stage 3

    initial inflight = 4'b0000;
    initial cnt      = 3'd0;
initial issue    = 1'b0;
initial bcnt     = 2'd0;
initial hand     = 1'b0;
initial n_in     = 4'd0;
initial n_out    = 4'd0;

    // the request leaving the last stage completes this cycle
    wire retire = inflight[3];

// outstanding-request ledger.  Rather than carrying a dedicated depth
// register alongside the per-half counts, the input and output events are
// logged by two free-running counters; their difference is the number of
// requests the block still owes a completion for.  The input port refuses a
// new request once every holding place is taken.
wire [3:0] depth  = n_in - n_out;
wire       accept = req && (depth != 4'd5);

    always @(posedge clk) begin
        if (rst) begin
            inflight <= 4'b0000;
            cnt      <= 3'd0;
issue    <= 1'b0;
bcnt     <= 2'd0;
hand     <= 1'b0;
n_in     <= 4'd0;
n_out    <= 4'd0;
        end else if (step) begin
// the request bus is registered at the pipeline input to cut the
// fan-in on stage 0: an accepted request waits one advance in the
// launch register before it occupies stage 0.  The front count is
// taken on acceptance, so it already covers that waiting request.
issue    <= accept;
inflight <= {inflight[2:0], issue};
// each pipeline half maintains its own occupancy count locally.  The
// stage1 -> stage2 crossing is registered to keep the adder chains
// short: the front count drops the request on the advance that moves
// it out of stage 1, the handover latch carries it, and the back
// count picks it up on the following advance.
cnt      <= cnt  + {2'b00, accept}        - {2'b00, inflight[1]};
bcnt     <= bcnt + {1'b0,  hand}          - {1'b0,  retire};
hand     <= inflight[1];
n_in     <= n_in  + {3'b000, accept};
n_out    <= n_out + {3'b000, retire};
        end
    end

assign f_idle = (cnt == 3'd0) && (bcnt == 2'd0) && !hand;
// five holding places: the launch register plus the four stages.  The
// ledger difference is the authoritative outstanding-request count.
assign f_full = (depth == 4'd5);
    assign f_any  = |inflight;
    assign f_slot = ~(&inflight);

    // P: the counter-derived flags and the shifter-derived flags may never
    // contradict each other -- idle together with an occupied stage, or
    // full together with a free stage.
    always @(posedge clk) assert (!(f_idle && f_any));
    always @(posedge clk) assert (!(f_full && f_slot));

endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    // upstream credit: number of empty slots, maintained incrementally so the
    // full indication does not have to decode the valid flags
    reg [1:0] free;
   // peak occupancy telemetry: high-water mark of the occupancy counter since
   // reset, sampled every cycle and read back on the data output while the
   // buffer is empty (the head slot carries no valid word then)
   reg [1:0] hwm;
  // the peak comparator is retimed behind a stage register: the occupancy
  // that will be resident next cycle is captured here and is compared
  // against the high-water mark on the following edge, so the occupancy
  // adders and the comparator no longer share one cycle of timing budget
  reg [1:0] peak_q;
    reg [7:0] d0, d1;

   // spill stage: a second two-entry buffer sitting behind the head buffer so
   // a burst is not backpressured while the head buffer is draining. words
   // leave the spill stage in arrival order and refill the head buffer.
   reg       vb0, vb1;
   reg [1:0] cntb;
   reg [7:0] b0, b1;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial free  = 2'd2;
   initial hwm   = 2'd0;
  initial peak_q = 2'd0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
   initial vb0   = 1'b0;
   initial vb1   = 1'b0;
   initial cntb  = 2'd0;
   initial b0    = 8'h00;
   initial b1    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
   wire push_a  = push && !v1 && !vb0;      // straight in when there is no backlog
   wire push_b  = push && !vb1 && !push_a;  // otherwise the word spills
   wire refill  = vb0 && !v1;               // backlog moves up when a slot frees
   wire do_push = push_a || refill;         // head buffer write enable
    wire do_pop  = pop  &&  v0;
   wire [7:0] a_din  = push_a ? din : b0;
  // next-state occupancy of whichever stage the upstream is feeding; the
  // single shared comparator sees it one cycle later, through peak_q
  wire [1:0] count_nxt = count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
  wire [1:0] cntb_nxt  = cntb  + (push_b  ? 2'd1 : 2'd0) - (refill  ? 2'd1 : 2'd0);
  wire       vb0_nxt   = (push_b && !refill) ? 1'b1 :
                         (refill && !push_b) ? vb1  : vb0;
  wire [1:0] occ_nxt   = vb0_nxt ? cntb_nxt : count_nxt;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            free  <= 2'd2;
           hwm   <= 2'd0;
          peak_q <= 2'd0;
            d0    <= 8'h00;
            d1    <= 8'h00;
           vb0   <= 1'b0;
           vb1   <= 1'b0;
           cntb  <= 2'd0;
           b0    <= 8'h00;
           b1    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                   d0 <= a_din;
                    v0 <= 1'b1;
                end else begin
                   d1 <= a_din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
               d0 <= a_din;
            end

            count <= count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
            free  <= free  - (do_push ? 2'd1 : 2'd0) + (do_pop ? 2'd1 : 2'd0);

           // the spill stage preserves arrival order: it only takes a word
           // once the head buffer cannot, and it empties into the head first
           if (push_b && !refill) begin
               if (!vb0) begin
                   b0  <= din;
                   vb0 <= 1'b1;
               end else begin
                   b1  <= din;
                   vb1 <= 1'b1;
               end
           end else if (refill && !push_b) begin
               b0  <= b1;
               vb0 <= vb1;
               vb1 <= 1'b0;
           end else if (push_b && refill) begin
               b0 <= din;
           end
           cntb <= cntb + (push_b ? 2'd1 : 2'd0) - (refill ? 2'd1 : 2'd0);

          peak_q <= occ_nxt;
          if (peak_q > hwm)
              hwm <= peak_q;
        end
    end

   assign dout    = v0 ? d0 : {6'b0, hwm};
    assign o_empty = !v0;
    assign o_full   = (free == 2'd0);
    assign o_count  = count;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);

    // ---- property: a push accepted last cycle must have gone into a buffer
    // ---- that both occupancy encodings called non-full
    always @(posedge clk)
        if (pv && $past(push) && !$past(v1))
            assert ($past(free) != 2'd0 && $past(count) != 2'd2);

   // ---- property: a cycle in which the upstream credit register reported no
   // ---- free slots must leave the peak occupancy telemetry pegged at two
   always @(posedge clk)
       if (pv && !$past(rst) && $past(free) == 2'd0)
           assert (hwm == 2'd2);
endmodule

// Histogram accumulator: four bin counters, one sample at a time,
// plus a running total-samples register and a shadow register that
// records the bin-0 count observed at the most recent bin-1 sample.
module histo_precedence (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire [1:0] i_bin,     // which bin the incoming sample lands in
    output wire [5:0] o_total,
output wire [3:0] o_snap,
output reg  [3:0] o_act
);
    // bin counters
    reg [3:0] b0, b1, b2, b3;
    // total samples accumulated
    reg [5:0] total;
    // shadow register: value of bin 0 at the time of the last bin-1 sample
    reg [3:0] snap;
   // snapshot delivery pipeline: the bin-0 population read out alongside a
   // bin-1 sample only reaches the shadow register four cycles later, which
   // matches the read latency of the bin storage array.
   reg [3:0] sn1, sn2, sn3, sn4;
   reg       v1, v2, v3, v4;
reg [3:0] ce_hist;
// snapshot defer buffer: a bin-1 sample that arrives while the readout
// pipeline is still busy parks its bin-0 reading here and replays it when
// the pipeline frees up, so back-to-back bin-1 samples are not lost
reg [3:0] hold;
reg       hold_v;
// snapshot ledger: requests issued vs. snapshots delivered to the shadow
reg [3:0] n_iss, n_ret;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;
   initial sn1   = 4'd0;
   initial sn2   = 4'd0;
   initial sn3   = 4'd0;
   initial sn4   = 4'd0;
   initial v1    = 1'b0;
   initial v2    = 1'b0;
   initial v3    = 1'b0;
   initial v4    = 1'b0;
initial ce_hist = 4'd0;
initial o_act   = 4'd0;
initial hold    = 4'd0;
initial hold_v  = 1'b0;
initial n_iss   = 4'd0;
initial n_ret   = 4'd0;

    // value currently held by the selected bin
    wire [3:0] sel_val = (i_bin == 2'd0) ? b0 :
                         (i_bin == 2'd1) ? b1 :
                         (i_bin == 2'd2) ? b2 : b3;

    // a sample is committed only if the selected bin has headroom
wire [3:0] inflight  = n_iss - n_ret;
wire       pipe_free = !(v1 | v2 | v3 | v4);
// the ledger can carry two outstanding snapshots (one in the readout
// pipeline, one in the defer buffer); a bin-1 sample that would overflow it
// is held off at the input until a slot frees up
wire       snap_full = (inflight == 4'd2);
wire incr = i_ce && (sel_val != 4'd15) && !((i_bin == 2'd1) && snap_full);
wire req  = incr && (i_bin == 2'd1);

    always @(posedge clk) begin
        if (incr) begin
            case (i_bin)
                2'd0: b0 <= b0 + 4'd1;
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
            endcase
            total <= total + 6'd1;
        end
    end
   // Snapshot pipeline: the read data shifts on every enabled cycle and the
   // valid bit travels with it, so the shadow register is loaded four cycles
   // after the bin-1 sample that requested the snapshot.
   always @(posedge clk) begin
       if (i_ce) begin
           sn2 <= sn1;
           v2  <= v1;
           sn3 <= sn2;
           v3  <= v2;
           sn4 <= sn3;
           v4  <= v3;
           if (v4)
               snap <= sn4;
          // stage-1 arbitration: a parked request replays ahead of a new
          // one so the shadow register sees bin-1 samples in order
          if (pipe_free && hold_v) begin
              sn1    <= hold;
              v1     <= 1'b1;
              hold_v <= req;
              if (req)
                  hold <= b0;
          end else if (pipe_free && req) begin
              sn1 <= b0;
              v1  <= 1'b1;
          end else begin
              v1 <= 1'b0;
              if (req) begin
                  hold   <= b0;
                  hold_v <= 1'b1;
              end
          end
          // ledger: one tick per request issued, one per snapshot delivered
          n_iss <= n_iss + {3'd0, req};
          n_ret <= n_ret + {3'd0, v4};
       end
   end

  // Activity monitor: a shift register of "sample landed in bin 3" flags,
// plus a status readout multiplexer: the current bin index selects which
// ledger / defer-buffer register is presented on o_act.
  always @(posedge clk) begin
      if (i_ce) begin
          ce_hist <= {ce_hist[2:0], (i_bin == 2'd3)};
          case (i_bin)
              2'd0: o_act <= n_iss;
              2'd1: o_act <= n_ret;
              2'd2: o_act <= hold;
              2'd3: o_act <= {hold_v, ce_hist[2:0]};
          endcase
      end
  end

    assign o_total = total;
    assign o_snap  = snap;

    // Property (precedence): whenever a sample is being committed, the
    // bin-0 population recorded earlier in the shadow register must already
    // have been accounted for in the total-samples register.
    always @(posedge clk)
        if (incr)
            assert (total >= {2'b00, snap});

   // Property (snapshot ledger conservation): every outstanding snapshot
   // request corresponds to a bin-1 sample that has already been counted,
   // and the bin-0 reading parked in the defer buffer was taken from a
   // population already counted, so together they can never exceed the
   // running sample total.
   always @(posedge clk)
       assert (total >= {2'b00, hold} + {2'b00, inflight});
endmodule

// Gray-coded write pointer crossing into a destination domain through a
// two-flop synchronizer, with a shadow binary pipeline kept alongside the
// synchronizer stages and a monitor that records the Hamming distance between
// the two most recent samples of the pointer.
module gray_cdc_skew_monitor (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable / idle
    input  wire       i_incr,    // source pointer advance
    output reg        armed,     // sticky: a pointer change has been observed
output reg  [2:0] last_delta, // bits differing between the last two samples
output reg  [3:0] o_idle_count // distractor: destination-domain activity meter
);

    // source-domain binary pointer and its gray encoding
    reg  [3:0] wbin;
    wire [3:0] wgray = wbin ^ (wbin >> 1);

    // two-flop synchronizer carrying the gray pointer
    reg  [3:0] sync1, sync2;

   // second consumer's synchronizer chain onto the same gray pointer
   reg  [3:0] s1b, s2b;

    // shadow binary pipeline, one stage per synchronizer flop
    reg  [3:0] b1, b2;
   reg  [3:0] b1b, b2b;

   // round-robin refresh phase: 0 refreshes chain A, 1 refreshes chain B.
// Advances are no longer pinned to a phase: the issue/retire ledger below
// keeps at most one advance outstanding, which is what bounds either chain
// to a single gray transition between two of its own samples.
   reg        phase;
  // Programmable pointer depth.  The wrap modulus is carried as a mask that
  // is always one less than a power of two; it is widened one bit at a time
  // by i_incr pulses while the destination domain is parked (i_ce low).
  // Moving the wrap point invalidates everything already in flight, so a
  // depth change also drains the pointer and both synchronizer shadows.
  reg  [3:0] wrap_mask;

 // Issue/retire ledger for pointer advances.  n_issue logs advances pushed
 // into the source pointer, n_retire logs advances absorbed by the chain-A
 // shadow stage.  Both are plain free-running event counters that wrap at
 // four bits; only their difference is meaningful.
 reg  [3:0] n_issue;
 reg  [3:0] n_retire;

// Distractor bookkeeping: counts accepted advance pulses and bleeds down
// while the destination domain is parked.  Purely observational.
reg  [3:0] idle_count;

    initial begin
        wbin       = 4'd0;
        sync1      = 4'd0;
        sync2      = 4'd0;
        b1         = 4'd0;
        b2         = 4'd0;
       s1b        = 4'd0;
       s2b        = 4'd0;
       b1b        = 4'd0;
       b2b        = 4'd0;
       phase      = 1'b0;
      wrap_mask  = 4'd1;
     n_issue    = 4'd0;
     n_retire   = 4'd0;
idle_count = 4'd0;
o_idle_count = 4'd0;
        armed      = 1'b0;
        last_delta = 3'd0;
    end

    // combinational Hamming distance between the two synchronizer stages
    wire [3:0] xr = sync1 ^ sync2;
    wire [2:0] delta = {2'b00, xr[0]} + {2'b00, xr[1]} +
                       {2'b00, xr[2]} + {2'b00, xr[3]};

   // the same distance measure for the second chain
   wire [3:0] xrb = s1b ^ s2b;
   wire [2:0] delta_b = {2'b00, xrb[0]} + {2'b00, xrb[1]} +
                        {2'b00, xrb[2]} + {2'b00, xrb[3]};

   // one skew monitor is shared by both chains; it reports whichever chain
   // was refreshed on this phase
   wire [2:0] delta_mux = phase ? delta_b : delta;
   wire       skew_mux  = phase ? (s1b != s2b) : (sync1 != sync2);
  // depth reconfiguration is only accepted while the destination domain is
  // idle, and only up to the full four-bit pointer range
  wire       cfg_widen = !i_ce && i_incr && (wrap_mask != 4'd15);
 // credit-style interlock: a fresh advance is only issued once the previous
 // one has been retired by the shadow stage
 wire       ledger_busy = (n_issue != n_retire);
 wire       ptr_adv     = i_ce && i_incr && !ledger_busy;
 wire       shadow_adv  = i_ce && !phase && (b1 != wbin);

    always @(posedge clk) begin
       if (cfg_widen) begin
           // new wrap point: grow the mask and drain the pointer pipeline
           wrap_mask <= (wrap_mask << 1) | 4'd1;
           wbin      <= 4'd0;
           sync1     <= 4'd0;
           sync2     <= 4'd0;
           b1        <= 4'd0;
           b2        <= 4'd0;
           s1b       <= 4'd0;
           s2b       <= 4'd0;
           b1b       <= 4'd0;
           b2b       <= 4'd0;
          n_issue   <= 4'd0;
          n_retire  <= 4'd0;
       end else if (i_ce) begin
            // source pointer
         wbin  <= (wbin + (ptr_adv ? 4'd1 : 4'd0)) & wrap_mask;

           // ledger: log both sides of the advance
         n_issue  <= n_issue  + (ptr_adv    ? 4'd1 : 4'd0);
         n_retire <= n_retire + (shadow_adv ? 4'd1 : 4'd0);

            // synchronizer chain
           if (!phase) begin
               sync1 <= wgray;
               sync2 <= sync1;
           end else begin
               s1b   <= wgray;
               s2b   <= s1b;
           end

            // shadow binary chain, structurally parallel to the chain above
           if (!phase) begin
               b1    <= wbin;
               b2    <= b1;
           end else begin
               b1b   <= wbin;
               b2b   <= b1b;
           end

            // monitor
           last_delta <= delta_mux;
           phase      <= ~phase;

            // Q: first time the two stages disagree, i.e. a pointer update is
            // in flight through the synchronizer.  Sticky, never cleared.
          if (skew_mux || ledger_busy)
                armed <= 1'b1;
        end
    end

   // ---- distractor: activity meter, independent of the pointer pipeline ----
   always @(posedge clk) begin
       if (i_ce && i_incr) begin
           if (idle_count != 4'd15)
               idle_count <= idle_count + 4'd1;
       end else if (!i_ce && idle_count != 4'd0) begin
           idle_count <= idle_count - 4'd1;
       end
       o_idle_count <= idle_count;
   end

    // P: once a pointer change has been seen, every recorded sample-to-sample
    // distance is at most one bit (gray-code single-bit transition).
    assert property (!armed || last_delta <= 3'd1);

endmodule

module disasm_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       kick,      // an instruction was successfully decoded
    output reg  [3:0] count,     // cycles since last kick
    output reg        expired,   // decoder hung: limit was reached
    output reg        healthy    // plenty of slack left
);
    localparam [3:0] LIMIT = 4'd10;   // timeout
    localparam [3:0] WARN  = 4'd8;    // slack threshold

   // saved context of the decode channel that is parked while the other
   // one owns the shared pipeline slot
   reg  [3:0] count_sh;
   reg        exp_sh;
  // second parked context: three decode channels rotate through the one
  // pipeline slot, so two of them are always parked at any time
  reg  [3:0] count_sh2;
  reg        exp_sh2;
 // remaining slack of the channel that currently owns the slot; the
 // timeout now fires on a zero-detect of this countdown instead of a
 // magnitude compare, and it is reloaded whenever the slot changes hands
 reg  [3:0] deadline;
// the decode channel hands its shared operand port to the issue stage for
// one pipeline advance on every successful decode; the port comes back on
// the following advance.  both sides of the loan are logged so the loan
// traffic can be watched from the outside, and the level flag is the
// registered "port is out" condition used by the slack report.
reg  [3:0] n_lend;    // hand-overs to the issue stage (wraps)
reg  [3:0] n_back;    // returns from the issue stage (wraps)
reg        port_out;  // the operand port is out on loan right now

    initial begin
        count   = 4'd0;
        expired = 1'b0;
        healthy = 1'b1;
       count_sh = 4'd0;
       exp_sh   = 1'b0;
      count_sh2 = 4'd0;
      exp_sh2   = 1'b0;
     deadline  = LIMIT;
n_lend    = 4'd0;
n_back    = 4'd0;
port_out  = 1'b0;
    end

    // next value of the stall counter: kick clears it, otherwise it
    // counts up and saturates at the timeout limit
    wire [3:0] nxt = kick              ? 4'd0  :
                     (count == LIMIT)  ? LIMIT :
                                         count + 4'd1;

   // the slot is handed to the other channel when the active one makes
   // progress, and is preempted once the active one has clearly hung
   wire swap = kick || (count == LIMIT);

  // the channel holding the slot has just run out of slack
  wire hung = !kick && (deadline <= 4'd1);

// a decode hands the port over unless it is already out; the return
// ledger chases the hand-over ledger, so the port comes back on the next
// advance after it was taken
wire       lend      = !port_out && kick;
wire       back      = (n_lend != n_back);
wire [3:0] n_lend_nx = n_lend + (lend ? 4'd1 : 4'd0);
wire [3:0] n_back_nx = n_back + (back ? 4'd1 : 4'd0);
wire       port_nx   = lend || (port_out && !back);

    always @(posedge clk) begin
        if (rst) begin
            count   <= 4'd0;
           count_sh <= 4'd0;
           exp_sh   <= 1'b0;
           count_sh2 <= 4'd0;
           exp_sh2   <= 1'b0;
          deadline  <= LIMIT;
n_lend    <= 4'd0;
n_back    <= 4'd0;
port_out  <= 1'b0;
            expired <= 1'b0;
            healthy <= 1'b1;
        end else if (i_ce) begin
           if (swap) begin
               count    <= count_sh;         // resume the parked channel
              deadline <= LIMIT - count_sh; // slack left for the resumed channel
count_sh  <= count_sh2;        // rotate the parked queue forward
count_sh2 <= nxt;              // park the current stall count
exp_sh    <= exp_sh2;          // its hang flag rotates with it
exp_sh2   <= hung;             // remember if it hung
           end else begin
               count    <= nxt;
              deadline <= (deadline == 4'd0) ? 4'd0 : deadline - 4'd1;
           end
// the loan ledgers are free running and wrap at four bits; nothing but
// the flag tracks how many loans are outstanding
if (lend) n_lend <= n_lend + 4'd1;
if (back) n_back <= n_back + 4'd1;
port_out <= port_nx;
           // sticky per channel: a kick only clears the channel that
           // currently owns the slot
// the hang detector reads the ledgers directly: a hand-over that is
// still unmatched means the issue stage never took the operands
expired <= hung || exp_sh || exp_sh2 || (n_lend_nx != n_back_nx);
// the slack report is built from the registered port flag
healthy <= (nxt < WARN) && (count_sh < WARN) && (count_sh2 < WARN) && !port_nx;
        end
    end

    // P: the timeout flag and the slack flag are never raised together
    always @(posedge clk)
        if (expired)
            assert (!healthy);
endmodule

module elastic_profile_buf (
    input wire       i_clk,
    input wire       i_rst,
    input wire       i_push,
    input wire       i_pop,
    input wire [7:0] i_data,
    output wire      o_valid,
    output wire      o_full,
    output wire [7:0] o_data,
output wire [2:0] o_count,
output reg [3:0] o_push_tally
);
    // Two-entry elastic buffer holding profiling samples.
    // Entry 0 is the head, entry 1 is the tail.  v0/v1 are the head/tail
    // occupancy flags; count is a separate occupancy register that is
    // maintained in parallel with the flags.
    reg       v0, v1;
    reg [7:0] d0, d1;
    reg [2:0] count;
   // Skid slot behind the tail.  o_full is raised as soon as the tail fills,
   // but one upstream beat may already be in flight, so it is absorbed here
   // and handed to the tail as soon as a pop frees it.
   reg       s_v;
   reg [7:0] s_d;
  // occupancy contributed by the skid slot, held apart from the core count
  reg [1:0] skid_occ;
 // the occupancy adder is retimed off the push path: a beat that has just
 // been written into a core slot has its unit of occupancy parked in
 // inc_pend for one cycle and is folded into count on the next edge
 reg       inc_pend;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;
   initial s_v   = 1'b0;
   initial s_d   = 8'h00;
  initial skid_occ = 2'd0;
 initial inc_pend = 1'b0;
initial o_push_tally = 4'd0;

    // "full" is decided purely by the tail flag
    wire w_full  = v1;
    wire do_push = i_push && !w_full;
    wire do_pop  = i_pop  && v0;
   // a beat arriving while full is taken by the skid slot, unless a pop is
   // freeing the tail this cycle, in which case it goes straight to the tail
   wire do_skid = i_push && w_full && !s_v && !do_pop;
  // a beat takes a core slot this cycle; its increment is deferred one edge
  wire core_join  = do_push || (do_pop && !s_v && i_push);
  // the head always vacates on a pop; that decrement is taken immediately
  wire core_leave = do_pop;
  // when the parked beat is handed to the freed tail, its occupancy share
  // crosses straight from the skid counter into count
  wire [2:0] skid_xfer = (do_pop && s_v) ? {1'b0, skid_occ} : 3'd0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
           s_v   <= 1'b0;
           s_d   <= 8'h00;
          skid_occ <= 2'd0;
         inc_pend <= 1'b0;
o_push_tally <= 4'd0;
        end else if (do_push && do_pop) begin
            // head leaves, new sample becomes the head: occupancy unchanged
            d0    <= i_data;
        end else if (do_push) begin
            if (!v0) begin
                v0 <= 1'b1;
                d0 <= i_data;
            end else begin
                v1 <= 1'b1;
                d1 <= i_data;
            end
        end else if (do_pop) begin
            // tail slides down into the head slot
           v0 <= v1;
           d0 <= d1;
           if (s_v) begin
               // the parked skid sample takes the freed tail slot
               v1    <= 1'b1;
               d1    <= s_d;
               s_v   <= 1'b0;
              // the head leaves and the parked beat joins the core, so its
              // occupancy share moves from the skid counter into count
              skid_occ <= 2'd0;
           end else if (i_push) begin
               // we reported full, so this beat lands in the freed tail
               v1 <= 1'b1;
               d1 <= i_data;
           end else begin
               v1    <= 1'b0;
           end
       end else if (do_skid) begin
           s_v   <= 1'b1;
           s_d   <= i_data;
          skid_occ <= skid_occ + 2'd1;
       end
        // i_push = i_pop = 0 : the buffer idles, all state held
       if (!i_rst) begin
           count    <= count + {2'b00, inc_pend} - {2'b00, core_leave} + skid_xfer;
           inc_pend <= core_join;
       end
if (!i_rst && do_push)
    o_push_tally <= o_push_tally + 4'd1;
    end

    assign o_valid = v0;
    assign o_full  = w_full;
    assign o_data  = d0;
  assign o_count = count + {1'b0, skid_occ} + {2'b00, inc_pend};

    // P: whenever the buffer is not reporting full, the recorded occupancy
    // is at most one sample (the 3-bit register would allow up to 7).
    always @(posedge i_clk)
        if (!w_full)
            assert (count <= 3'd1);
endmodule

module uart_rx_onehot (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // baud tick / enable: low freezes all state
    input  wire       rx,
    input  wire       take,    // consumer accepts the byte parked in STOP
    output wire [7:0] o_data,
    output wire       o_ferr,
    output wire       o_busy
);
    // one-hot phase FSM:
    //   st[0]      IDLE
    //   st[1]      START bit
    //   st[2..9]   data bits D0..D7 (one state per bit)
    //   st[10]     STOP bit / byte parked
    reg [10:0] st;
    reg [3:0]  nbits;   // frame phase index: 0..10 only, though 4 bits hold 15
   reg [3:0]  dcnt;    // data bits already shifted into sr this frame: 0..8
    reg [7:0]  sr;
    reg        ferr;
    reg        pv;
   reg [3:0]  n_acq;   // ledger: frames acquired off the line (start bit seen)
   reg [3:0]  n_rel;   // ledger: frames released to the consumer (take at STOP)
   reg        active;  // a frame is in flight according to the ledger
  reg        owner;   // baud-tick arbiter: 1 = the idle timer owns this tick
  reg [3:0]  icnt;    // idle ticks seen by the line-idle timer: 0..11
 reg        rel_q;   // handoff staged one tick: take now acks on the next tick
 reg [7:0]  obuf;    // output holding register for the byte being handed off

    initial st    = 11'b000_0000_0001;
    initial nbits = 4'd0;
   initial dcnt  = 4'd0;
    initial sr    = 8'h00;
    initial ferr  = 1'b0;
    initial pv    = 1'b0;
   initial n_acq  = 4'd0;
   initial n_rel  = 4'd0;
   initial active = 1'b0;
  initial owner = 1'b0;
  initial icnt  = 4'd0;
 initial rel_q = 1'b0;
 initial obuf  = 8'h00;

    wire idle   = st[0];
    wire startb = st[1];
    wire datab  = |st[9:2];
    wire stopb  = st[10];

    wire start_det = ce && idle   && !rx;   // falling edge of the line
   wire adv       = ce && active && !owner && (startb || datab); // count only the ticks this engine owns
    wire done      = ce && stopb  && take;
   wire in_flight = start_det || (active && !done); // frame engine's claim on the next tick
   wire quiet     = owner && (icnt == 4'd11);       // line idle for a whole frame time

    // next-state decode: every source bit drives exactly one destination bit
    reg [10:0] nxt;
    always @(*) begin
        nxt      = 11'd0;
        nxt[0]   = (st[0] && rx) || (st[10] && take);
        nxt[1]   = st[0] && !rx;
        nxt[2]   = st[1];
        nxt[3]   = st[2];
        nxt[4]   = st[3];
        nxt[5]   = st[4];
        nxt[6]   = st[5];
        nxt[7]   = st[6];
        nxt[8]   = st[7];
        nxt[9]   = st[8];
        nxt[10]  = st[9] || (st[10] && !take);
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            st    <= 11'b000_0000_0001;
            nbits <= 4'd0;
           dcnt  <= 4'd0;
            sr    <= 8'h00;
            ferr  <= 1'b0;
           n_acq  <= 4'd0;
           n_rel  <= 4'd0;
           active <= 1'b0;
           owner <= 1'b0;
           icnt  <= 4'd0;
          rel_q <= 1'b0;
          obuf  <= 8'h00;
        end else if (ce) begin
            st <= nxt;
            if (start_det)     nbits <= 4'd1;   // load: start bit is phase 1
            else if (done)     nbits <= 4'd0;
            else if (adv)      nbits <= nbits + 4'd1;
            if (datab)         sr    <= {rx, sr[7:1]};
           if (start_det || done) dcnt <= 4'd0;
           else if (datab)        dcnt <= dcnt + 4'd1;
           if (done)          ferr  <= !rx || (dcnt != 4'd8); // stop bit high and a full byte
          else if (quiet)    ferr  <= 1'b0;                  // stale error retired once the line goes quiet
           // frame ledger: one acquire per start bit, one release per handoff
           if (start_det)     n_acq  <= n_acq + 4'd1;
if (rel_q)         n_rel  <= n_rel + 4'd1;
           if (start_det)     active <= 1'b1;
else if (rel_q)    active <= 1'b0;
// staged handoff: the byte is parked in obuf on take and the ledger
// release commits on the following tick, when the bus has been read
rel_q <= stopb && take;
if (done)          obuf  <= sr;
          // tick arbiter: every tick the frame engine will not use goes to the idle timer
          owner <= !in_flight;
          if (!owner)             icnt <= 4'd0;
          else if (icnt != 4'd11) icnt <= icnt + 4'd1;
        end
    end

   // with no byte parked, the data bus reads back the ledger for diagnostics
assign o_data = stopb ? sr : (rel_q ? obuf : {n_acq, n_rel});
    assign o_ferr = ferr;
   assign o_busy = !idle || active;

    // P: the phase counter changes on every phase change, and it never counts
    // past the 10 phases of a frame -- stated as a no-change check.
    always @(posedge clk)
        if (pv && $stable(nbits))
            assert ($stable(st) && nbits <= 4'd10);

   // P2: dcnt lags the phase index by the START phase plus the one-cycle
   // capture lag, so inside a frame it is always nbits-2 bits deep.
   always @(posedge clk)
       if (pv && o_busy && nbits >= 4'd2)
           assert (dcnt == nbits - 4'd2);
endmodule

module fsm_phase_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_start,
    output wire [4:0] o_phase,
    output wire       o_busy
);
    // binary-encoded FSM: only 0..4 are legal encodings, 5..7 are unreachable
    localparam [2:0] S_IDLE   = 3'd0,
                     S_FETCH  = 3'd1,
                     S_DECODE = 3'd2,
                     S_EXEC   = 3'd3,
                     S_WRITE  = 3'd4;

    reg [2:0] state;
    reg [4:0] dec;   // shadow one-hot decode of state
   reg [4:0] dec_s; // decode stage register, one pipeline step ahead of dec
    reg       win;   // window register: opened by a job start, closed at retire
   reg       tail;  // retire stage: carries the window over the write-back phase
  reg [2:0] age;   // phase age of the job in flight: 1 at launch, 5 at retire

    initial state = S_IDLE;
    initial dec   = 5'b00001;
   initial dec_s = 5'b00001;
    initial win   = 1'b0;
   initial tail  = 1'b0;
  initial age   = 3'd0;

    reg [2:0] nstate;
    always @(*) begin
        case (state)
            S_IDLE:   nstate = i_start ? S_FETCH : S_IDLE;
            S_FETCH:  nstate = S_DECODE;
            S_DECODE: nstate = S_EXEC;
            S_EXEC:   nstate = S_WRITE;
            S_WRITE:  nstate = S_IDLE;
            default:  nstate = 3'd5;   // illegal-encoding trap, never taken
        endcase
    end

    // one-hot decode of the next state; illegal encodings decode to all-zero
    wire [4:0] ndec = (nstate == S_IDLE)   ? 5'b00001 :
                      (nstate == S_FETCH)  ? 5'b00010 :
                      (nstate == S_DECODE) ? 5'b00100 :
                      (nstate == S_EXEC)   ? 5'b01000 :
                      (nstate == S_WRITE)  ? 5'b10000 : 5'b00000;

    always @(posedge i_clk) begin
        if (i_rst) begin
            state <= S_IDLE;
            dec   <= 5'b00001;
           dec_s <= 5'b00001;
            win   <= 1'b0;
           tail  <= 1'b0;
          age   <= 3'd0;
        end else if (i_ce) begin
            state <= nstate;
           dec_s <= ndec;      // decode is registered here ...
           dec   <= dec_s;     // ... and presented on o_phase one cycle later
            if ((state == S_IDLE) && i_start)
                win <= 1'b1;               // Q: a job is launched
           else if (tail)             // the retire stage owns the window now
                win <= 1'b0;               // R: the job retires

           // hand the window over once DECODE reaches o_phase, so the retire
           // stage covers the final write-back cycle on its own
           if (dec == 5'b00100)
               tail <= 1'b1;
           else if (dec == 5'b10000)
               tail <= 1'b0;

          // age the job one phase per enabled cycle: the launch cycle seeds
          // the counter and the retiring write-back cycle clears it again
          if ((state == S_IDLE) && i_start)
              age <= 3'd1;
          else if (dec == 5'b10000)
              age <= 3'd0;
          else if (win || tail)
              age <= age + 3'd1;
        end
    end

    assign o_phase = dec;
  assign o_busy  = win | tail | (|age);  // busy while a job still has an age

    // P: inside the job window the phase decode always names some phase
    always @(posedge i_clk)
        assert (!win || (|dec));

   // P2: a busy job showing phase 0 on o_phase is the launch cycle, so the
   // decode stage must already be carrying the FETCH phase behind it
   always @(posedge i_clk)
       assert (!win || (dec != 5'b00001) || (dec_s == 5'b00010));

  // P3: the retire stage only ever holds the window at the tail of a job, so
  // that job has aged at least four phases and o_phase has left the idle slot
  always @(posedge i_clk)
      assert (!tail || ((dec != 5'b00001) && (age >= 3'd4)));
endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
output wire       g_holdoff,
output reg  [3:0] o_dbg_count
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

// ---- per-slot occupancy accounting, kept in parallel with the valid bits ----
    reg [1:0]  occ;
   reg [1:0]  p_occ;   // priority-class share of the main slot (i_cred[7] set)
reg [1:0]  s_occ;
// ---- configured stage depth and free-slot accounting ----
reg [1:0]  cap;    // programmed depth: 1 (main only) or 2 (main + skid)
reg [2:0]  free;   // slots still available = cap - records resident

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;
reg  [3:0] dbg_prev;

    initial begin
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
       p_occ   = 2'd0;
s_occ   = 2'd0;
cap     = 2'd2;
free    = 3'd2;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
o_dbg_count = 4'd0;
dbg_prev    = 4'd0;
    end

wire       skid_free  = (free != 3'd0);
wire       load_skid  = i_ce && i_valid && !hold && m_valid && !i_ready && skid_free;
wire       fill_main  = i_ce && i_valid && !m_valid;
wire       drain_main = i_ce && m_valid && i_ready && !hold && !(i_valid && skid_free);
wire       drain_skid = i_ce && hold && i_ready;
// a fresh input record takes the main slot next cycle
wire       main_wr_new  = fill_main || (i_ce && i_valid && m_valid && i_ready && !hold && skid_free);
// the parked record is promoted out of the skid slot into the main slot
wire       main_wr_skid = i_ce && m_valid && i_ready && hold;
// total records resident in the stage (main slot + skid slot)
wire [1:0] occ_total  = occ + p_occ + s_occ;
// quiescent: nothing resident in the stage and nothing arriving this cycle
wire       stage_idle = (occ_total == 2'd0) && !i_valid;
// depth request is sampled off the credential bus while quiescent
wire [1:0] cap_req    = i_cred[0] ? 2'd1 : 2'd2;
// a record is taken from upstream / handed downstream this cycle
wire       in_accept  = i_valid && !hold && skid_free;
wire       out_accept = m_valid && i_ready;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
end else if (i_valid && skid_free) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
if (i_valid && !hold && skid_free) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

// ---- main-slot occupancy counter ----
   // normal-class records only; the priority-class share lives in p_occ
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
           if (main_wr_new)
               occ <= {1'b0, ~i_cred[7]};
           else if (main_wr_skid)
               occ <= {1'b0, ~s_cred[7]};
           else if (drain_main)
               occ <= 2'd0;
        end
    end

   // ---- main-slot occupancy counter, priority-class share ----
   always @(posedge i_clk) begin
       if (i_reset)
           p_occ <= 2'd0;
       else if (i_ce) begin
           if (main_wr_new)
               p_occ <= {1'b0, i_cred[7]};
           else if (main_wr_skid)
               p_occ <= {1'b0, s_cred[7]};
           else if (drain_main)
               p_occ <= 2'd0;
       end
   end

// ---- skid-slot occupancy counter ----
always @(posedge i_clk) begin
    if (i_reset)
        s_occ <= 2'd0;
    else if (i_ce) begin
        if (load_skid)
            s_occ <= s_occ + 2'd1;
        else if (drain_skid)
            s_occ <= s_occ - 2'd1;
    end
end
// ---- programmed stage depth ----
// depth is re-sampled only while the stage is quiescent, so a change can
// never strand a record in a slot that has just been configured away
always @(posedge i_clk) begin
    if (i_reset)
        cap <= 2'd2;
    else if (i_ce && stage_idle)
        cap <= cap_req;
end
// ---- free-slot counter: depth minus the records resident in the stage ----
always @(posedge i_clk) begin
    if (i_reset)
        free <= 3'd2;
    else if (i_ce) begin
        if (stage_idle)
            free <= {1'b0, cap_req};
        else
            free <= free - {2'b00, in_accept} + {2'b00, out_accept};
    end
end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
dbg_prev    <= 4'd0;
o_dbg_count <= 4'd0;
        end else if (i_ce) begin
g_fast <= i_valid && (free == {1'b0, cap});
            g_hld  <= i_valid && m_valid && hold;
dbg_prev    <= dbg_prev + {3'b000, (i_valid && i_ready)};
o_dbg_count <= dbg_prev ^ {3'b000, hold};
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
assign o_upstream_ready = !hold && skid_free;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

endmodule

module wdt_absence (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       arm,       // Q: opens the window
    input  wire       disarm,    // R: closes the window (may never arrive)
    input  wire       kick,      // pet the watchdog
    output reg  [3:0] cnt,
    output reg        expired,
    output reg        safe,
output reg        armed,
output reg [3:0] kick_cnt,
output reg [3:0] disarm_cnt
);
    localparam [3:0] LIMIT = 4'd10;  // timeout value
    localparam [3:0] WARN  = 4'd8;   // below this the timer is in the safe zone
    localparam [1:0] GRACE = LIMIT - WARN;  // warning-zone dwell before timeout
    reg [1:0] grace;                        // ticks elapsed since cnt hit WARN
reg [3:0] evt_shift;
localparam [3:0] B_LIMIT = 4'd3;        // backup trip point, in prescaled units
reg [1:0] b_tick;                       // /4 prescaler of the backup watchdog
reg [3:0] b_cnt;                        // prescaled ticks since the last kick
reg       hard;                         // backup watchdog has tripped

    initial cnt     = 4'd0;
    initial expired = 1'b0;
    initial safe    = 1'b1;
    initial armed   = 1'b0;
    initial grace   = 2'd0;
initial kick_cnt = 4'd0;
initial disarm_cnt = 4'd0;
initial evt_shift = 4'd0;
initial b_tick = 2'd0;
initial b_cnt  = 4'd0;
initial hard   = 1'b0;

    always @(posedge clk) begin
        if (i_ce) begin
// bookkeeping only: how many kicks have been seen
if (kick)
kick_cnt <= kick_cnt + 4'd1;
evt_shift <= {evt_shift[2:0], disarm};
if (disarm && !arm)
disarm_cnt <= disarm_cnt + 4'd1 + {3'd0, evt_shift[3]};
            // window register: set by arm, cleared by disarm
            if (arm)
                armed <= 1'b1;
            else if (disarm)
                armed <= 1'b0;

            // the watchdog only runs inside the window
            if (armed) begin
                if (kick) begin
                    cnt     <= 4'd0;
                    grace   <= 2'd0;
                    expired <= 1'b0;
                    safe    <= 1'b1;
                end else if (cnt < WARN) begin
                    // pre-warning part of the interval is held in cnt
                    cnt     <= cnt + 4'd1;
                    safe    <= ((cnt + 4'd1) < WARN);
                end else if (grace < GRACE) begin
                    // once cnt has reached WARN the remaining ticks before the
                    // timeout are accumulated here, so the warning-zone dwell
                    // can be reported on its own
                    grace   <= grace + 2'd1;
                    expired <= ((grace + 2'd1) == GRACE);
                    safe    <= 1'b0;
                end
            end

           // backup watchdog: same window and same kick, but clocked at a
           // quarter rate so it trips after the primary one; when it trips it
           // latches the expiry flag so the fault cannot be missed
           if (armed) begin
               if (kick) begin
                   b_tick <= 2'd0;
                   b_cnt  <= 4'd0;
                   hard   <= 1'b0;
               end else if (!hard) begin
                   if (b_tick == 2'd3) begin
                       b_tick <= 2'd0;
                       b_cnt  <= b_cnt + 4'd1;
                       if ((b_cnt + 4'd1) == B_LIMIT) begin
                           hard    <= 1'b1;
                           expired <= 1'b1;
                       end
                   end else begin
                       b_tick <= b_tick + 2'd1;
                   end
               end else begin
                   expired <= 1'b1;
               end
           end
        end
    end

    // P: once armed (and until disarmed, if ever), the timer can never report
    // both "expired" and "safe" at the same time.
    always @(*)
        if (armed)
            assert (!(expired && safe));
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       issue,     // new operation issued this advance
    output wire       o_retire,  // fixed-latency result leaving the unit
    output wire [2:0] o_occ
);
// 3-deep shift register feeding a registered writeback stage:
// bit k = op issued k advances ago
reg [2:0] pipe;
    // occupancy: incremented on issue, decremented when the tail drains
    reg [2:0] occ;
    // sticky arm: set the first time an operation is ever issued
    reg       armed;
// registered result stage: the final latency slot lives here
reg       wb;
// second beat of the narrow result bus; the pipe cannot advance during it
reg       beat;
// credit-based issue throttle: free slots in the 4-stage result path
reg [2:0] credit;
// return ledger: every accepted issue and every writeback return is logged
// so credits lost to a dropped return can be recovered at a drain point
reg [2:0] n_iss;
reg [2:0] n_ret;

initial pipe  = 3'b000;
    initial occ   = 3'd0;
    initial armed = 1'b0;
initial wb    = 1'b0;
initial beat  = 1'b0;
initial credit = 3'd4;
initial n_iss = 3'd0;
initial n_ret = 3'd0;
wire adv = i_ce && !beat;
// an issue is only taken when the unit still has a free slot
wire acc = issue && (credit != 3'd0);
// ledger view of the unit: nothing issued is still outstanding
wire drained = (n_iss == n_ret);

assign o_retire = adv && wb;
    assign o_occ    = occ;

    always @(posedge clk) begin
        if (rst) begin
pipe  <= 3'b000;
            occ   <= 3'd0;
            armed <= 1'b0;
wb    <= 1'b0;
beat  <= 1'b0;
credit <= 3'd4;
n_iss <= 3'd0;
n_ret <= 3'd0;
end else begin
if (adv) begin
pipe <= {pipe[1:0], acc};
wb   <= pipe[2];
occ    <= occ    + (acc ? 3'd1 : 3'd0) - (wb ? 3'd1 : 3'd0);
// a drained ledger means the pool owes nothing: re-sync it to full
credit <= drained ? (3'd4 - (acc ? 3'd1 : 3'd0))
                  : (credit - (acc ? 3'd1 : 3'd0) + (wb ? 3'd1 : 3'd0));
n_iss  <= n_iss + (acc ? 3'd1 : 3'd0);
n_ret  <= n_ret + (wb  ? 3'd1 : 3'd0);
if (acc)
                armed <= 1'b1;
end
if (i_ce)
beat <= !beat && wb;
        end
    end

    // P: once the unit has ever issued, at most 4 operations are in flight.
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd4);

   // P2: a result waiting in writeback means the credit pool is not full.
   always @(posedge clk)
       assert (!wb || credit <= 3'd3);
endmodule

module sb_window (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_issue,
    input  wire i_retire,
    input  wire i_open,
    input  wire i_close,
    output wire o_full,
    output wire o_empty,
output wire o_mon,
output reg [3:0] o_act
);
    localparam [3:0] WINDOW = 4'd8;

    // transaction scoreboard: issued count, retired count, and a redundant
    // outstanding-transaction register maintained in parallel
    reg [4:0] iss;
    reg [4:0] ret;
   // retires are committed to `ret` in groups of four; `ret_p` holds the
   // retires of the group that has not been folded in yet
   reg [1:0] ret_p;
    reg [3:0] out_r;

   // speculative class: a second scoreboard of the same shape that shares the
   // WINDOW budget and the issue/retire port with the primary class. Issues
   // are steered round-robin between the two classes; retires drain the
   // speculative class first so primary entries stay ordered behind them.
   reg [4:0] sec_iss;
   reg [4:0] sec_ret;
   reg [3:0] out_s;
   reg       rr;

    // registered status flags (one cycle stale, updated only when enabled)
    reg       full_q;
    reg       empty_q;

   // the issue count feeds the status comparator through four retiming
   // registers; the raw counter is too far from the compare logic to make
   // timing in one cycle, so the compare now sees a 4-cycle-old copy
   reg [4:0] iss_d1;
   reg [4:0] iss_d2;
   reg [4:0] iss_d3;
   reg [4:0] iss_d4;

    // monitoring window: opened by i_open, closed by i_close
    reg       mon;

    reg       pv;

    initial iss     = 5'd0;
    initial ret     = 5'd0;
   initial ret_p   = 2'd0;
    initial out_r   = 4'd0;
   initial sec_iss = 5'd0;
   initial sec_ret = 5'd0;
   initial out_s   = 4'd0;
   initial rr      = 1'b0;
    initial full_q  = 1'b0;
    initial empty_q = 1'b1;
   initial iss_d1  = 5'd0;
   initial iss_d2  = 5'd0;
   initial iss_d3  = 5'd0;
   initial iss_d4  = 5'd0;
    initial mon     = 1'b0;
    initial pv      = 1'b0;
initial o_act   = 4'd0;

   // the window budget is shared by both classes
   wire [4:0] occ  = {1'b0, out_r} + {1'b0, out_s};
   wire       room = (occ < {1'b0, WINDOW});
   wire iss_any   = i_ce && i_issue && room;
   wire acc_iss   = iss_any && !rr;
   wire acc_iss_s = iss_any &&  rr;
   wire acc_ret_s = i_ce && i_retire && (out_s != 4'd0);
   wire acc_ret   = i_ce && i_retire && (out_s == 4'd0) && (out_r != 4'd0);
   // closing the monitoring window forces a partial group to commit so the
   // retire count is exact at the window boundary
   wire ret_flush = i_ce && i_close;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            iss   <= 5'd0;
            ret   <= 5'd0;
           ret_p <= 2'd0;
            out_r <= 4'd0;
           sec_iss <= 5'd0;
           sec_ret <= 5'd0;
           out_s   <= 4'd0;
           rr      <= 1'b0;
o_act <= 4'd0;
        end else begin
            if (acc_iss) iss <= iss + 5'd1;
           if (acc_iss_s) sec_iss <= sec_iss + 5'd1;
           if (acc_ret_s) sec_ret <= sec_ret + 5'd1;
           if (iss_any)   rr <= ~rr;
           if (ret_flush) begin
               ret   <= ret + {3'b0, ret_p} + (acc_ret ? 5'd1 : 5'd0);
               ret_p <= 2'd0;
           end else if (acc_ret) begin
               if (ret_p == 2'd3) begin
                   ret   <= ret + 5'd4;
                   ret_p <= 2'd0;
               end else begin
                   ret_p <= ret_p + 2'd1;
               end
           end
            if (acc_iss && !acc_ret)
                out_r <= out_r + 4'd1;
            else if (!acc_iss && acc_ret)
                out_r <= out_r - 4'd1;
           if (acc_iss_s && !acc_ret_s)
               out_s <= out_s + 4'd1;
           else if (!acc_iss_s && acc_ret_s)
               out_s <= out_s - 4'd1;
if (i_ce && (i_open || i_close))
    o_act <= o_act + 4'd1;
        end

    always @(posedge clk)
        if (i_rst) begin
            full_q  <= 1'b0;
            empty_q <= 1'b1;
           iss_d1  <= 5'd0;
           iss_d2  <= 5'd0;
           iss_d3  <= 5'd0;
           iss_d4  <= 5'd0;
        end else if (i_ce) begin
           full_q  <= (occ == {1'b0, WINDOW});
           empty_q <= (iss_d4 == ret) && (sec_iss == sec_ret);
           iss_d1  <= iss;
           iss_d2  <= iss_d1;
           iss_d3  <= iss_d2;
           iss_d4  <= iss_d3;
        end

    always @(posedge clk)
        if (i_rst)
            mon <= 1'b0;
        else if (i_ce) begin
            if (i_close)
                mon <= 1'b0;
            else if (i_open)
                mon <= 1'b1;
        end

    assign o_full  = full_q;
    assign o_empty = empty_q;
    assign o_mon   = mon;

    // P: inside an open monitoring window, when the full flag rises the
    // scoreboard must not simultaneously report empty
    always @(posedge clk)
        if (pv && mon && $rose(full_q))
            assert (!empty_q);
endmodule

module phase_divider_pair (
    input  wire       clk,
    input  wire       ce,       // divider step enable; low = idle, all state held
    input  wire       resync,   // realigns both phase counters, retires the pristine scope
    output reg  [2:0] phase,    // primary phase counter, mod 5
    output reg  [2:0] cnt,      // skewed phase counter, mod 5, built 2 phases ahead
    output reg        en_load,  // divided enable: fires the cycle after phase wraps
    output reg        en_sample,// divided enable: fires the cycle after cnt wraps
    output reg        pristine  // high until the first resync has ever happened
);

    // Load/sample ledger: every load pulse and every sample pulse is logged
    // for the lifetime of the current alignment, so the buffer downstream can
    // account for the two divided enables it sees.
    reg  [3:0] n_load;   // count of load pulses issued
    reg  [3:0] n_samp;   // count of sample pulses issued

    // samples that do not have a matching load behind them yet
    wire [3:0] samp_ahead = n_samp - n_load;
    // a realignment can leave the ping-pong buffer starved; while the sample
    // side is two or more entries ahead, inject make-up load pulses
    wire       makeup     = (samp_ahead >= 4'd2);

   // Skew-buffer ledger: the sample pulse captures one entry into the
   // ping-pong skew buffer and the load pulse releases it to the sink, so
   // both sides are logged as the buffer sees them, on the divided enables.
   reg  [3:0] n_cap;    // entries captured by the sample side
   reg  [3:0] n_rel;    // entries released by the load side
// the bank has a registered write port: a sample pulse stages its entry and
// the entry only becomes visible to the load side on the next enabled cycle
reg        cap_pend; // entry staged by the sample side, not yet committed
wire [3:0] level     = n_cap + {3'd0, cap_pend} - n_rel;
   // the load side must not release an entry the sample side has not
   // captured yet, so the phase-4 pulse waits for a filled buffer
   wire       bank_full = (level != 4'd0);

   // Load-side stall watchdog: the sink downstream must never be left
   // without a load pulse for long, so the gap since the last one is timed
   // and a make-up pulse is forced once that gap gets too wide.
   reg  [2:0] gap;      // enabled cycles since the last load pulse
   wire       wdog       = (gap >= 3'd6);
wire       load_pulse = ((phase == 3'd4) && bank_full) || makeup || wdog;

    // The skewed counter is constructed 2 phases ahead of the primary phase
    // counter, so the two divided-enable pulses are interleaved by design.
    initial phase     = 3'd0;
    initial cnt       = 3'd2;
    initial en_load   = 1'b0;
    initial en_sample = 1'b0;
    initial pristine  = 1'b1;
    initial n_load    = 4'd0;
    initial n_samp    = 4'd0;
initial n_cap     = 4'd0;
initial n_rel     = 4'd0;
initial cap_pend  = 1'b0;
   initial gap       = 3'd0;

    always @(posedge clk) begin
        if (resync) begin
            // hard realignment: both phase counters are slammed to zero, which
            // destroys the constructed skew (and retires the pristine scope)
            phase     <= 3'd0;
            cnt       <= 3'd0;
            en_load   <= 1'b0;
            en_sample <= 1'b0;
            pristine  <= 1'b0;
            n_load    <= 4'd0;
            n_samp    <= 4'd0;
n_cap     <= 4'd0;
n_rel     <= 4'd0;
cap_pend  <= 1'b0;
           gap       <= 3'd0;
        end
        else if (ce) begin
            phase     <= (phase == 3'd4) ? 3'd0 : phase + 3'd1;
            cnt       <= (cnt   == 3'd4) ? 3'd0 : cnt   + 3'd1;
            // each divided enable pulses exactly when its phase counter wraps
           en_load   <= load_pulse;
            en_sample <= (cnt   == 3'd4);
            // ledger entries are made as the pulses are issued
           n_load    <= n_load + (load_pulse ? 4'd1 : 4'd0);
            n_samp    <= n_samp + ((cnt == 3'd4) ? 4'd1 : 4'd0);
cap_pend  <= en_sample;
n_cap     <= n_cap + (cap_pend ? 4'd1 : 4'd0);
n_rel     <= n_rel + (en_load   ? 4'd1 : 4'd0);
           gap       <= load_pulse ? 3'd0 : gap + 3'd1;
        end
    end

    // Absence: while the divider has never been resynced, the two divided
    // enables are never asserted in the same cycle.
    always @(posedge clk)
        if (pristine)
            assert (!(en_load && en_sample));

   // Alignment: while the divider has never been resynced, the sample pulse
   // always lands three enabled cycles into the current load window.
   always @(posedge clk)
       if (pristine)
           assert (!en_sample || (gap == 3'd3));

endmodule

// Valid/ready pipeline stage with a skid buffer carrying a three-step
// command chain: ARM -> START -> FINISH -> ARM -> ...
// The buffered word is only meaningful while the stage is stalled.
module chain_skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,       // global enable / idle condition
    input  wire       in_valid,   // producer offers its next chain word
    input  wire       out_ready,  // consumer accepts
    output wire       o_valid,
    output wire [1:0] o_code,
output wire       o_in_ready,
output wire [3:0] o_fire_count
);
    localparam [1:0] ARM    = 2'd1;
    localparam [1:0] START  = 2'd2;
    localparam [1:0] FINISH = 2'd3;

    // producer chain position: next word emitted is src_phase+1
    reg [1:0] src_phase  = 2'd0;
    // consumer chain position: 0 = nothing armed, 1 = armed, 2 = started
    reg [1:0] phase      = 2'd0;

    // output (skid) register pair
    reg       out_valid  = 1'b0;
    reg [1:0] out_code   = ARM;
    reg       skid_valid = 1'b0;
    reg [1:0] skid_code  = ARM;

   // second (tail) skid slot: lets the stage swallow one more word when the
   // consumer stalls for two cycles in a row instead of dropping in_ready
   // immediately behind a single buffered word
   reg       skid2_valid = 1'b0;
   reg [1:0] skid2_code  = ARM;

   // one-cycle inter-chain gap: after a FINISH leaves the stage the
   // producer is held off for a cycle so it can resynchronise on the
   // head of the next chain
   reg       gap        = 1'b0;

  // purely observational: count of words handed to the consumer
  reg [3:0] fire_count = 4'd0;

    wire [1:0] in_code  = src_phase + 2'd1;
  wire       in_ready = !skid2_valid && !gap;
    wire       out_room = !out_valid || out_ready;
    wire       in_fire  = step && in_valid && in_ready;
    wire       out_fire = step && out_valid && out_ready;

    assign o_valid    = out_valid;
    assign o_code     = out_code;
    assign o_in_ready = in_ready;
   assign o_fire_count = fire_count;

    always @(posedge clk) begin
        if (rst) begin
            src_phase  <= 2'd0;
            phase      <= 2'd0;
            out_valid  <= 1'b0;
            out_code   <= ARM;
            skid_valid <= 1'b0;
            skid_code  <= ARM;
           skid2_valid <= 1'b0;
           skid2_code  <= ARM;
           gap        <= 1'b0;
          fire_count <= 4'd0;
        end else if (step) begin
            // output register: drain skid first, else take the fresh word
            if (out_room) begin
                if (skid_valid) begin
                    out_valid <= 1'b1;
                    out_code  <= skid_code;
               end else if (in_valid && in_ready) begin
                    out_valid <= 1'b1;
                    out_code  <= in_code;
                end else begin
                    out_valid <= 1'b0;
                end
            end

            // skid buffer: only loaded while the stage is stalled
            if (skid_valid) begin
               if (out_room) begin
                   // head drains into the output register; refill it from
                   // the tail slot, or straight from the producer
                   if (skid2_valid) begin
                       skid_valid <= 1'b1;
                       skid_code  <= skid2_code;
                   end else if (in_valid && in_ready) begin
                       skid_valid <= 1'b1;
                       skid_code  <= in_code;
                   end else begin
                       skid_valid <= 1'b0;
                   end
               end
           end else if (in_valid && in_ready && !out_room) begin
                skid_valid <= 1'b1;
                skid_code  <= in_code;
            end

           // tail slot: only fills behind a full head slot while the
           // output register is blocked, and always shifts down on a drain
           if (skid2_valid) begin
               if (out_room)
                   skid2_valid <= 1'b0;
           end else if (in_valid && in_ready && skid_valid && !out_room) begin
               skid2_valid <= 1'b1;
               skid2_code  <= in_code;
           end

            // producer advances on every accepted word
            if (in_valid && in_ready)
                src_phase <= (src_phase == 2'd2) ? 2'd0 : src_phase + 2'd1;

            // consumer chain tracker advances on every delivered word
            if (out_valid && out_ready)
                phase <= (out_code == FINISH) ? 2'd0 : out_code;

           // hold the producer off for one cycle after a completed chain
           gap <= out_valid && out_ready && out_code == FINISH;

          if (out_valid && out_ready)
              fire_count <= fire_count + 4'd1;
        end
    end

    // P (two assertions): a later chain step is never delivered unless the
    // earlier ones already were.
    always @(*)
        assert (!(out_fire && out_code == FINISH) || phase == 2'd2);

    always @(*)
        assert (!(out_fire && out_code == START) || phase == 2'd1);

   // Q: the only word that may leave the stage during the post-FINISH
   // gap cycle is the ARM that opens the next chain.
   always @(posedge clk)
       if (!rst)
           assert (!(gap && out_fire) || out_code == ARM);
endmodule

module credit_deadline (
    input  wire clk,
    input  wire i_ce,      // global enable: low => all state frozen
    input  wire rst,
    input  wire req,       // producer wants to spend a credit
    output wire grant,
output wire busy,
output reg [3:0] req_hist
);
    localparam [2:0] TOTAL = 3'd4;   // configured credit pool

    // credits held by the producer, credits outstanding at the consumer
    reg [2:0] credits;
    reg [2:0] outst;
    // consumer needs two enabled cycles to retire one outstanding credit
    reg       svc;
    // bounded-response deadline countdown for the outstanding credits
    reg [3:0] timer;
   // governor watermark: deepest outstanding occupancy seen so far
   reg [2:0] peak;
reg last_req;

    initial begin
        credits = 3'd4;
        outst   = 3'd0;
        svc     = 1'b0;
        timer   = 4'd0;
       peak    = 3'd0;
req_hist = 4'd0;
last_req = 1'b0;
    end

   // once occupancy has ever peaked at the whole pool, hold off new
   // spends until the consumer has drained completely
   wire throttle  = (peak == TOTAL) && (outst != 3'd0);
   wire do_spend  = req && (credits != 3'd0) && !throttle;
    wire do_return = (outst != 3'd0) && (svc == 1'b1);
   wire [2:0] outst_nxt = outst + (do_spend  ? 3'd1 : 3'd0)
                                - (do_return ? 3'd1 : 3'd0);

    assign grant = i_ce && do_spend;
    assign busy  = (outst != 3'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            if (rst) begin
                credits <= TOTAL;
                outst   <= 3'd0;
                svc     <= 1'b0;
                timer   <= 4'd0;
               peak    <= 3'd0;
req_hist <= 4'd0;
last_req <= 1'b0;
            end else begin
                // credit conservation: one token moves per event
                credits <= credits - (do_spend  ? 3'd1 : 3'd0)
                                   + (do_return ? 3'd1 : 3'd0);
                outst   <= outst   + (do_spend  ? 3'd1 : 3'd0)
                                   - (do_return ? 3'd1 : 3'd0);

                // two-cycle service phase per outstanding credit
                if (outst == 3'd0)
                    svc <= 1'b0;
                else
                    svc <= ~svc;

               // watermark only ever rises
               if (outst_nxt > peak)
                   peak <= outst_nxt;

                // deadline budget: each spend buys 2 cycles, one cycle burnt
                timer <= timer - ((timer != 4'd0) ? 4'd1 : 4'd0)
                               + (do_spend ? 4'd2 : 4'd0);

// observability only: rolling history of the req input
last_req <= req;
req_hist <= {req_hist[2:0], last_req};
            end
        end
    end

    // Bounded response (safety): the countdown must never expire while a
    // credit is still outstanding at the consumer.
    always @(posedge clk)
        if (outst != 3'd0)
            assert (timer != 4'd0);

   // Quiescence (safety): once the whole pool is back at the producer
   // there is nothing left at the consumer, so the service phase must be
   // idle and the deadline budget must be fully spent.
   always @(posedge clk)
       if (credits == TOTAL)
           assert ((timer == 4'd0) && (svc == 1'b0));

   // Governor coherence (safety): the in-flight deadline budget never
   // exceeds two cycles per credit at the recorded peak occupancy.
   always @(posedge clk)
       assert (timer <= {peak, 1'b0});

endmodule

// Simple token-lexer FSM: binary-encoded states 0..4, encodings 5..7 unused.
module lex_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [1:0] cls,     // 0=escape/backslash, 1=alpha, 2=digit, 3=quote
    output reg  [2:0] st,
    output reg  [2:0] len
);
    localparam [2:0] S_IDLE  = 3'd0;
    localparam [2:0] S_IDENT = 3'd1;
    localparam [2:0] S_NUM   = 3'd2;
    localparam [2:0] S_STR   = 3'd3;
    localparam [2:0] S_ESC   = 3'd4;
    // An escape can now be taken from top level or from inside an identifier,
    // so S_ESC alone no longer says which token is being built: the state code
    // to resume with is held here while st == S_ESC.
    reg [2:0] esc_ret;
   // Second lexer channel. The two character streams are interleaved on cls
   // and take turns owning the single decode/commit datapath below. Channel B
   // measures records rather than tokens, so its length is carried across a
   // token boundary instead of being cleared.
   reg [2:0] st_b;
   reg [2:0] len_b;
   reg [2:0] esc_b;
   reg       own;   // 0 = channel A owns the shared datapath, 1 = channel B
   // Decode and commit are now separate cycles: the next-state decode and the
   // length adder no longer share one combinational path to the outputs. A
   // character is absorbed into the staging pair in one cycle and the pair is
   // driven onto st/len in the next.
   reg [2:0] st_s;
   reg [2:0] len_s;
   reg       s_vld;

   wire [2:0] cur_st  = own ? st_b  : st;
   wire [2:0] cur_len = own ? len_b : len;
   wire [2:0] cur_esc = own ? esc_b : esc_ret;
   wire [2:0] len_inc = (cur_len == 3'd7) ? 3'd7 : (cur_len + 3'd1);

    initial st  = S_IDLE;
    initial len = 3'd0;
    initial esc_ret = S_IDLE;
   initial st_s  = S_IDLE;
   initial len_s = 3'd0;
   initial s_vld = 1'b0;
   initial st_b  = S_IDLE;
   initial len_b = 3'd0;
   initial esc_b = S_IDLE;
   initial own   = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            st  <= S_IDLE;
            len <= 3'd0;
            esc_ret <= S_IDLE;
           st_s  <= S_IDLE;
           len_s <= 3'd0;
           s_vld <= 1'b0;
           st_b  <= S_IDLE;
           len_b <= 3'd0;
           esc_b <= S_IDLE;
           own   <= 1'b0;
        end else if (ce) begin
           if (s_vld) begin
              if (own) begin
                  st_b  <= st_s;   // commit cycle: the staged pair goes back
                  len_b <= len_s;  // to whichever channel was decoded
              end else begin
                  st    <= st_s;
                  len   <= len_s;
              end
               s_vld <= 1'b0;
              own   <= ~own;   // round-robin: the other stream gets the next char
           end else begin
               s_vld <= 1'b1;   // decode cycle: absorb this character
           case (cur_st)
                S_IDLE: begin
                    if (cls == 2'd1) begin
                       st_s  <= S_IDENT;
                       len_s <= 3'd1;
                    end else if (cls == 2'd2) begin
                       st_s  <= S_NUM;
                       len_s <= 3'd1;
                    end else if (cls == 2'd3) begin
                       st_s  <= S_STR;
                       len_s <= 3'd0;
                    end else begin
                      st_s <= S_ESC;   // stray backslash: escaped char starts an identifier
                      if (own) esc_b <= S_IDENT; else esc_ret <= S_IDENT;
                       len_s   <= 3'd0;
                    end
                end
                S_IDENT: begin
                    if (cls == 2'd1 || cls == 2'd2) begin
                       st_s  <= S_IDENT;
                       len_s <= len_inc;
                    end else if (cls == 2'd0) begin
                       st_s    <= S_ESC;   // a\b is still a single identifier
                      if (own) esc_b <= S_IDENT; else esc_ret <= S_IDENT;
                      len_s   <= cur_len;
                    end else begin
                       st_s  <= S_IDLE;
                      len_s <= own ? len_inc : 3'd0;   // B keeps counting the record
                    end
                end
                S_NUM: begin
                    if (cls == 2'd2) begin
                       st_s  <= S_NUM;
                       len_s <= len_inc;
                    end else begin
                       st_s  <= S_IDLE;
                      len_s <= own ? len_inc : 3'd0;
                    end
                end
                S_STR: begin
                    if (cls == 2'd3) begin
                       st_s  <= S_IDLE;   // closing quote ends the token
                      len_s <= own ? len_inc : 3'd0;
                    end else if (cls == 2'd0) begin
                       st_s  <= S_ESC;    // backslash: next char is literal
                      if (own) esc_b <= S_STR; else esc_ret <= S_STR;
                      len_s <= cur_len;
                    end else begin
                       st_s  <= S_STR;
                       len_s <= len_inc;
                    end
                end
                S_ESC: begin
                  st_s  <= cur_esc;     // resume whatever token the escape interrupted
                   len_s <= len_inc;
                end
                default: begin
                    // unreachable encodings 5..7: recover to IDLE
                   st_s  <= S_IDLE;
                end
            endcase
           end
        end
    end

    // P: in the IDLE state the accumulated token length is always zero.
    always @(*)
        if (st == 3'd0)
            assert (len == 3'd0);
endmodule

module pwm_prio_duty (
    input  wire       clk,
    input  wire       ce,
    input  wire [7:0] req,
    output reg        out_r,
    output reg        vld_r
);
    // ---------------- PWM state ----------------
    reg [2:0] cnt;        // period counter 0..7
   reg [2:0] per;        // programmed frame length minus one (frame = per+1)
    reg [3:0] duty;       // active duty value 0..8
    reg [3:0] hi_cnt;     // cycles spent high inside the current period
    reg       shadow_nz;  // shadow: the duty programmed for this period was nonzero
    reg       armed;      // scope: high until the first all-zero request load
   reg       duty_ext;   // extra whole cycle granted to this frame by the dither
   reg       dith;       // pending half-step credit carried between frames

    initial begin
        cnt       = 3'd0;
       per       = 3'd7;   // reset frame is the full eight cycles
        duty      = 4'd4;   // reset duty is nonzero
        hi_cnt    = 4'd0;
        shadow_nz = 1'b1;   // matches reset duty
        armed     = 1'b1;
       duty_ext  = 1'b0;
       dith      = 1'b0;
        out_r     = 1'b0;
        vld_r     = 1'b0;
    end

    // ---------------- priority encoder over the request vector ----------------
    reg [2:0] idx;
    reg       vld;
    always @(*) begin
        vld = |req;
        if      (req[7]) idx = 3'd7;
        else if (req[6]) idx = 3'd6;
        else if (req[5]) idx = 3'd5;
        else if (req[4]) idx = 3'd4;
        else if (req[3]) idx = 3'd3;
        else if (req[2]) idx = 3'd2;
        else if (req[1]) idx = 3'd1;
        else             idx = 3'd0;
    end

    // requested duty: highest set index + 1, or 0 when no request
    wire [3:0] duty_req = vld ? ({1'b0, idx} + 4'd1) : 4'd0;

   // ---------------- frame-length programming ----------------
   // req[2:0] double as the frame-length code; a requested duty that does not
   // fit in the programmed frame is truncated to 100% of that frame
   wire [2:0] per_nxt  = req[2:0];
   wire [3:0] per_lim  = {1'b0, per_nxt} + 4'd1;
   wire [3:0] duty_nxt = (duty_req > per_lim) ? per_lim : duty_req;
  // ---------------- half-step dither ----------------
  // when several sources request at once the winner earns an extra half cycle
  // of duty for the aggregate load; two half cycles are cashed in as one whole
  // cycle, and the bump is only applied while the duty is below 100% of the
  // frame so that the extra cycle still fits inside the frame
  wire       multi    = vld && ((req & (req - 8'd1)) != 8'd0);
  wire       ext_nxt  = (dith && multi) && (duty_nxt < per_lim);
  wire [3:0] duty_eff = duty + {3'b000, duty_ext};

 // ---------------- frame capacity ----------------
 // 100% of the frame being emitted right now (the programmed per, not the
 // one being loaded); the comparator can never ask for more high time than
 // the frame it belongs to is able to hold
 wire [3:0] cap_now = {1'b0, per} + 4'd1;

    // ---------------- comparator: high exactly while cnt < duty ----------------
wire out  = ({1'b0, cnt} < duty_eff);
   wire wrap = (cnt == per);

    always @(posedge clk) begin
        if (ce) begin
           cnt   <= wrap ? 3'd0 : cnt + 3'd1;   // restarts at each boundary
            out_r <= out;          // registered output stage
            vld_r <= vld;
            if (wrap) begin
               per       <= per_nxt;
                // period boundary: latch the new duty and its shadow flag together
               duty      <= duty_nxt;
               shadow_nz <= (duty_nxt != 4'd0);
              duty_ext  <= ext_nxt;
              dith      <= dith ^ multi;
                hi_cnt    <= 4'd0;
               if (duty_nxt == 4'd0)
                    armed <= 1'b0; // the scope-closing event R
            end else begin
                hi_cnt <= hi_cnt + (out ? 4'd1 : 4'd0);
               // frame monitor: the high time can never outrun the frame it
               // belongs to; if it does, the latched flag no longer describes
               // the pulse being emitted, so drop it
               if (hi_cnt > {1'b0, per})
                   shadow_nz <= 1'b0;
            end
        end
    end

    // Precedence, in the "before the first zero-duty program" scope:
    // if the output has been high at all inside this period, then a nonzero
    // duty must have been recorded in the shadow flag earlier.
    always @(posedge clk)
        if (armed && hi_cnt != 4'd0)
            assert (shadow_nz);

   // Frame budget: the high time booked so far in this frame never exceeds
   // the duty being applied to it, and that duty fits inside the frame.
   always @(posedge clk)
       assert (hi_cnt <= duty_eff && duty_eff <= cap_now);
endmodule

module pingpong_tile_buffer (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire       wr_en,
    input  wire       rd_en,
    input  wire [7:0] wr_data,
    output reg  [7:0] rd_data,
output wire       o_sel,
output reg  [7:0] o_wr_tally
);
    localparam [1:0] LAST = 2'd3;

    // ping-pong double buffer: one half owned by the rasterizer (writer),
    // the other half owned by the shader fetch port (reader)
    reg       sel;                 // master ping-pong select bit
    reg       wr_half, rd_half;    // half currently addressed by each port
    reg [1:0] wcnt, rcnt;          // offset inside the owned half
    reg       wr_full, rd_empty;   // per-half handshake flags
   // buffer-turnaround commit pipeline: the ownership swap is handed to the
   // memory system and retires four cycles later, so both ports keep their
   // current half assignment until the request has walked all four stages
   reg       swp_v0, swp_v1, swp_v2, swp_v3;   // request valid, per stage
   reg       swp_d0, swp_d1, swp_d2, swp_d3;   // pending select, per stage
  // turnaround ledger for the memory-system interface: every issued swap
  // request is logged on n_iss and every retired one on n_ret. The port
  // allows a single outstanding turnaround, so the two logs must agree
  // again before a new request may be handed over. Free-running, wrapping.
  reg [3:0] n_iss, n_ret;
reg [7:0] last_byte;
    reg [7:0] mem [0:7];
    integer   i;

    initial begin
        sel     = 1'b0;
        wr_half = 1'b0;
        rd_half = 1'b1;
        wcnt    = 2'd0;
        rcnt    = 2'd0;
        wr_full = 1'b0;
        rd_empty= 1'b1;
       swp_v0  = 1'b0;
       swp_v1  = 1'b0;
       swp_v2  = 1'b0;
       swp_v3  = 1'b0;
       swp_d0  = 1'b0;
       swp_d1  = 1'b0;
       swp_d2  = 1'b0;
       swp_d3  = 1'b0;
       n_iss   = 4'd0;
       n_ret   = 4'd0;
        rd_data = 8'h00;
o_wr_tally = 8'h00;
last_byte  = 8'h00;
        for (i = 0; i < 8; i = i + 1) mem[i] = 8'h00;
    end

    wire [2:0] wr_addr = {wr_half, wcnt};
    wire [2:0] rd_addr = {rd_half, rcnt};

    wire w_step = i_ce && wr_en && !wr_full;
    wire r_step = i_ce && rd_en && !rd_empty;
  wire ld_outst   = (n_iss != n_ret);   // a logged turnaround is unretired
  wire swap       = i_ce && wr_full && rd_empty && !ld_outst;
   wire swp_commit = i_ce && swp_v3;

    assign o_sel = sel;

    always @(posedge clk) begin
        if (rst) begin
            sel      <= 1'b0;
            wr_half  <= 1'b0;
            rd_half  <= 1'b1;
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
            wr_full  <= 1'b0;
            rd_empty <= 1'b1;
           swp_v0   <= 1'b0;
           swp_v1   <= 1'b0;
           swp_v2   <= 1'b0;
           swp_v3   <= 1'b0;
           swp_d0   <= 1'b0;
           swp_d1   <= 1'b0;
           swp_d2   <= 1'b0;
           swp_d3   <= 1'b0;
           n_iss    <= 4'd0;
           n_ret    <= 4'd0;
o_wr_tally <= 8'h00;
last_byte  <= 8'h00;
       end else if (swp_commit) begin
           sel      <= swp_d3;
           wr_half  <= swp_d3; // writer takes the freshly drained half
           rd_half  <=  sel;   // reader takes the freshly filled half
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
            wr_full  <= 1'b0;
            rd_empty <= 1'b0;
        end else begin
            if (w_step) begin
                mem[wr_addr] <= wr_data;
                wcnt <= wcnt + 2'd1;
                if (wcnt == LAST) wr_full <= 1'b1;
            end
            if (r_step) begin
                rd_data <= mem[rd_addr];
                rcnt <= rcnt + 2'd1;
                if (rcnt == LAST) rd_empty <= 1'b1;
            end
        end

       // the turnaround request advances one stage per enabled cycle
       if (!rst && i_ce) begin
           swp_v3 <= swp_v2;   swp_d3 <= swp_d2;
           swp_v2 <= swp_v1;   swp_d2 <= swp_d1;
           swp_v1 <= swp_v0;   swp_d1 <= swp_d0;
           swp_v0 <= swap;     swp_d0 <= ~sel;
          if (swap)       n_iss <= n_iss + 4'd1;
          if (swp_commit) n_ret <= n_ret + 4'd1;
       end
if (!rst && i_ce) begin
    if (w_step) last_byte  <= wr_data;
    if (r_step) o_wr_tally <= o_wr_tally + last_byte;
end
    end

    // P: whenever both ports perform an access in the same cycle they never
    // touch the same buffer location
    always @(posedge clk)
        if (i_ce && wr_en && rd_en && !wr_full && !rd_empty)
            assert (wr_addr != rd_addr);
endmodule

module prio_grant_tracker (
    input  wire       clk,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [3:0] req,
    output reg        vld,     // registered valid: idx meaningful only while set
    output reg  [1:0] idx,     // encoded winner index
    output reg  [3:0] oh,      // registered one-hot grant
    output reg        ack_lo,  // low-half acknowledge, derived from idx
    output reg        ack_hi,  // high-half acknowledge, derived from one-hot
output reg        armed,   // sticky: set the first time a request is taken
output reg  [3:0] n_take,  // ledger: leases issued  (free-running, wraps)
output reg  [3:0] n_drop,  // ledger: leases retired (free-running, wraps)
output reg        stale,   // standing lease has burned one idle cycle
output reg  [3:0] req_seen // sticky union of newly-arriving request bits
);

    // combinational priority encoder (lowest index wins)
    wire       any = |req;
    wire [1:0] enc = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;
    wire [3:0] iso = req & (~req + 4'd1);   // isolate lowest set bit
   // retirements are booked by half: a low-half holder settles into n_drop,
   // a high-half holder into its own column, so the two halves of the
   // ledger can be read out independently
   reg [3:0] n_drop_hi;
// shadow copy of the previous request vector, used for edge detection only
reg [3:0] req_prev;

   // the ledger, not vld, is the authority on lease occupancy
  wire [3:0] n_ret       = n_drop + n_drop_hi;
  wire       outstanding = (n_take != n_ret);

    initial begin
        vld    = 1'b0;
        idx    = 2'd0;
        oh     = 4'b0000;
        ack_lo = 1'b0;
        ack_hi = 1'b0;
        armed  = 1'b0;
n_take = 4'd0;
n_drop = 4'd0;
       n_drop_hi = 4'd0;
stale  = 1'b0;
req_seen  = 4'd0;
req_prev  = 4'd0;
    end

    always @(posedge clk) begin
        if (ce) begin
            // acknowledge flags are built from the *previous* grant state:
            // one path reads the index, the other reads the one-hot vector
// bookkeeping only: remember which request lines have newly arrived
req_prev <= req;
req_seen <= req_seen | (req & ~req_prev);
            ack_lo <= vld && (idx < 2'd2);
            ack_hi <= vld && (oh[3] || oh[2]);

            if (any) begin
                // any request refreshes the lease and re-asserts valid
                vld   <= 1'b1;
                armed <= 1'b1;
                stale <= 1'b0;
                if (!outstanding) begin
                    // ledger is square: issue a fresh lease to the winner
                    idx    <= enc;
                    oh     <= iso;
                    n_take <= n_take + 4'd1;
                end else if (enc < idx) begin
                    // lease already in flight: a higher-priority requester
                    // takes it over in place -- a hand-off, not a new lease,
                    // so the ledger does not move
                    idx <= enc;
                    oh  <= iso;
                end
                // otherwise the current holder keeps the bus
            end else if (outstanding) begin
                if (stale) begin
                    // second idle cycle retires the lease; the one-hot is
                    // left parked as a record of the last holder
                    vld    <= 1'b0;
                    stale  <= 1'b0;
                   if (idx[1]) n_drop_hi <= n_drop_hi + 4'd1;
                   else        n_drop    <= n_drop    + 4'd1;
                end else begin
                    // first idle cycle: age the standing grant round-robin
                    idx   <= idx + 2'd1;
                    oh    <= {oh[2:0], oh[3]};
                    stale <= 1'b1;
                end
            end
        end
    end

    // P: once the tracker has ever accepted a request, the low-half and
    // high-half acknowledges are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(ack_lo && ack_hi));

endmodule

// Packet-capture sensor credit window.
// TOTAL = 8 stream credits.  A burst send spends 3 credits (they become
// "outstanding" bytes in flight); the collector returns exactly one credit
// per enabled cycle while anything is outstanding.  A deadline register is
// reloaded on every accepted burst and counts down otherwise; it must never
// expire while credits are still outstanding.
module credit_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_send,    // producer requests a burst
output wire       o_busy,
output wire [3:0] o_nspend,  // ledger: credits handed to the link (wraps)
output wire [3:0] o_nret,    // ledger: credits taken back (wraps)
output wire       o_phase,   // which link slot the collector is in
output wire       o_rdy,     // collector has a return slot open
output wire [3:0] o_ngrant,  // ledger: return slots opened (wraps)
output wire [3:0] o_nuse     // ledger: return slots consumed (wraps)
);
    reg [3:0] avail;   // credits held by the sensor
    reg [3:0] outst;   // credits outstanding (in flight)
reg [3:0] stage;   // credits accepted for a burst but not yet on the link
    reg [3:0] timer;   // completion deadline countdown
    reg       armed;   // sticky: set the first time a burst is accepted
reg [3:0] n_spend;  // event ledger: credits spent on bursts
reg [3:0] n_ret;    // event ledger: credits returned by the collector
reg       phase;    // half-rate return link: credits only come back on return slots
reg       rdy;      // a return slot is open and not yet used
reg [3:0] n_grant;  // event ledger: return slots opened by the collector
reg [3:0] n_use;    // event ledger: return slots consumed by a credit
reg       sready;   // framer has armed the link's send slot for a staged credit
reg [3:0] n_stg;    // event ledger: credits accepted into the stage buffer
reg [3:0] n_lnch;   // event ledger: staged credits launched onto the link

    initial avail = 4'd8;
    initial outst = 4'd0;
initial stage = 4'd0;
    initial timer = 4'd0;
    initial armed = 1'b0;
initial n_spend = 4'd0;
initial n_ret = 4'd0;
initial phase = 1'b0;
initial rdy = 1'b0;
initial n_grant = 4'd0;
initial n_use = 4'd0;
initial sready = 1'b0;
initial n_stg = 4'd0;
initial n_lnch = 4'd0;

    wire send_ok = i_send && (avail >= 4'd3);
wire grant   = !phase && !rdy;                  // collector opens the next return slot
wire retire  = (outst != 4'd0) && phase && rdy;  // a credit comes back in an open slot
wire sopen   = phase && !sready;                 // framer arms the send slot during the return half
wire push    = !phase && sready && (stage != 4'd0); // staged credit takes the armed send slot

assign o_busy = (outst != 4'd0) || (stage != 4'd0);
assign o_nspend = n_spend;
assign o_nret   = n_ret;
assign o_phase  = phase;
assign o_rdy    = rdy;
assign o_ngrant = n_grant;
assign o_nuse   = n_use;

    always @(posedge clk) begin
        if (rst) begin
            avail <= 4'd8;
            outst <= 4'd0;
stage <= 4'd0;
            timer <= 4'd0;
            armed <= 1'b0;
n_spend <= 4'd0;
n_ret <= 4'd0;
phase <= 1'b0;
rdy <= 1'b0;
n_grant <= 4'd0;
n_use <= 4'd0;
sready <= 1'b0;
n_stg <= 4'd0;
n_lnch <= 4'd0;
        end else if (i_ce) begin
phase <= ~phase;             // link alternates send / return slots
if (send_ok) n_spend <= n_spend + 4'd3;
if (retire)  n_ret   <= n_ret   + 4'd1;
if (grant) begin
    rdy     <= 1'b1;         // slot opens during the send half-period
    n_grant <= n_grant + 4'd1;
end else if (retire) begin
    rdy   <= 1'b0;           // slot consumed by the returning credit
    n_use <= n_use + 4'd1;
end
if (sopen) sready <= 1'b1;        // send slot armed for the next send half-period
else if (push) sready <= 1'b0;    // slot consumed by the launched credit
if (send_ok) n_stg  <= n_stg  + 4'd2;
if (push)    n_lnch <= n_lnch + 4'd1;
            if (send_ok) begin
                // spend three credits, one may come back the same cycle
                avail <= avail - 4'd3 + (retire ? 4'd1 : 4'd0);
// one credit goes out on this slot, the other two wait in the stage buffer
outst <= outst + 4'd1 + (push ? 4'd1 : 4'd0) - (retire ? 4'd1 : 4'd0);
stage <= stage + 4'd2 - (push ? 4'd1 : 4'd0);
timer <= 4'd15;         // deadline: half-rate return of up to 8 credits
                armed <= 1'b1;          // sticky arm
            end else if (retire) begin
                avail <= avail + 4'd1;
                outst <= outst - 4'd1;
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end else begin
if (push) begin
    outst <= outst + 4'd1;
    stage <= stage - 4'd1;
end
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end
        end
    end

    // Bounded response (safety form), scoped after the first accepted burst:
    // the deadline never expires while credits are still outstanding.
    always @(*)
        assert (!armed || !((timer == 4'd0) && (outst != 4'd0)));
endmodule

module window_rate_limiter (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_req,
output wire o_grant,
output wire [2:0] o_n_in,
output wire [2:0] o_n_out
);
    parameter W     = 4;
    parameter LIMIT = 3;

    // sliding window of the last W grant decisions
    reg [W-1:0] win;
    // count of ones that mirrors the window by construction
    reg [2:0]   ones;
   // admit decision in flight toward the accumulator: the count update is
   // retimed through one register stage, so `ones` trails the window by a beat
   reg         adm_q;
    // sticky arm register: set the first time a grant is ever issued
    reg         armed;
   // post-grant cooldown: a grant is followed by two enabled cycles of refusal
   reg [1:0]   gap;
    reg         pv;
// issue/retire ledger: one tick per admit pushed into the window, one per
// slot that falls off the far end. Free running, they wrap at three bits.
reg [2:0]   n_in;
reg [2:0]   n_out;

    initial win   = 0;
    initial ones  = 0;
   initial adm_q = 0;
    initial armed = 0;
   initial gap   = 0;
    initial pv    = 0;
initial n_in  = 0;
initial n_out = 0;

    // the bit about to leave the window
    wire [2:0] retiring = win[W-1] ? 3'd1 : 3'd0;
    // occupancy of the window once the oldest slot retires
   // plus the admit still in flight, which the accumulator has not absorbed yet
   wire [2:0] eff      = ones - retiring + (adm_q ? 3'd1 : 3'd0);
// instantaneous occupancy straight off the ledger; unlike the accumulator
// it does not trail the window by a beat
wire [2:0] occ  = n_in - n_out;
// the same figure once the oldest slot has retired
wire [2:0] live = occ - retiring;

// rate decision is taken from the ledger, which is exact for this cycle,
   // and is additionally blocked while the post-grant cooldown is running
wire allow = i_req && (live < LIMIT) && (gap == 2'd0);
// the retimed accumulator now sizes the cooldown instead: a window already
// carrying two admits earns the long pause, a lightly loaded one a short one
wire [1:0] cool = (eff >= 3'd2) ? 2'd2 : 2'd1;

    assign o_grant = i_ce && allow;
assign o_n_in  = n_in;
assign o_n_out = n_out;

    always @(posedge clk) begin
        if (i_rst) begin
            win   <= 0;
            ones  <= 0;
           adm_q <= 0;
            armed <= 0;
           gap   <= 0;
n_in  <= 0;
n_out <= 0;
        end else if (i_ce) begin
           win   <= { win[W-2:0], allow };
           ones  <= ones - retiring + (adm_q ? 3'd1 : 3'd0);
           adm_q <= allow;
if (allow)
    n_in  <= n_in  + 3'd1;
if (win[W-1])
    n_out <= n_out + 3'd1;
            if (allow)
                armed <= 1'b1;
           if (allow)
gap <= cool;
           else if (gap != 2'd0)
               gap <= gap - 2'd1;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    // Precedence, after the limiter has armed: a grant observed one cycle ago
    // must have been preceded by a window that was not already saturated, so
    // the window can never be completely full of grants.
    always @(posedge clk)
        if (pv && armed)
            assert (!($past(i_ce) && $past(allow)) || (win != 4'hF));

   // Cooldown consistency: halfway through a cooldown the grant that started it
   // is still resident in the window, so the mirrored occupancy is not empty.
   always @(posedge clk)
       if (pv)
           assert ((gap != 2'd1) || (ones != 3'd0 || adm_q));
endmodule

module deb_evt_fifo (
    input  wire clk,
    input  wire i_ce,      // sample enable: low freezes all state
    input  wire raw,       // raw (noisy) button level
    input  wire pop,       // consumer request
    output wire empty,
    output wire full,
    output reg  o_level    // last popped debounced level
);
    // ---- debouncer: saturating stability counter ----
    reg [1:0] stab;
    reg       deb;

    // ---- event FIFO: pointers + occupancy ----
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg [1:0] tail;        // shadow: write pointer snapshot taken at the last push
    reg       mem [0:3];
   reg [1:0] wnext;       // precomputed next write address (shared write-port adder)

   // ---- refresh generator: periodic level-refresh events ----
   // second producer on the shared FIFO write port: every fourth sample it
   // re-posts the current debounced level so a stalled consumer still gets a
   // fresh entry. Edge events own the port; a coincident refresh is held.
   reg [1:0] hb;
   reg       hb_pend;

   // ---- event ledger: free-running push/pop transfer counters ----
// a push is logged when the entry is written, a pop when the consumer's
// request is accepted, so the ledger difference is the number of entries
// not yet spoken for; empty is taken from it and therefore also throttles
// request acceptance. full is taken from the occupancy accumulator: a slot
// whose read is still in flight is not free for rewrite.
   reg [2:0] n_push, n_pop;
   wire [2:0] occ = n_push - n_pop;   // outstanding entries, mod 8

  // ---- read data phase: four-sample memory access latency ----
  // a pop request is acknowledged to the ledger the sample it is accepted,
  // but the entry is only retired -- rptr stepped and o_level updated --
  // when the request walks out of the access pipeline four samples later.
  reg       pop_s0, pop_s1, pop_s2, pop_s3;

    // ---- scope register: high until the FIFO has ever been full ----
    reg       never_full;

    // ---- past-valid ----
    reg       pv;

    initial begin
        stab = 2'd0; deb = 1'b0;
        wptr = 2'd0; rptr = 2'd0; count = 3'd0;
        tail = 2'd0;
       wnext = 2'd1;
       hb = 2'd0; hb_pend = 1'b0;
       n_push = 3'd0; n_pop = 3'd0;
pop_s0 = 1'b0; pop_s1 = 1'b0; pop_s2 = 1'b0; pop_s3 = 1'b0;
        never_full = 1'b1;
        pv = 1'b0;
        o_level = 1'b0;
        mem[0] = 1'b0; mem[1] = 1'b0; mem[2] = 1'b0; mem[3] = 1'b0;
    end

   assign empty = (occ == 3'd0);
assign full  = (count == 3'd4);

    // a debounced edge is committed once raw has disagreed with deb for 3 samples
    wire deb_commit = (raw != deb) && (stab == 2'd2);

   wire hb_req   = (hb == 2'd3) || hb_pend;
   wire push_req = deb_commit || hb_req;
   wire do_push  = i_ce && push_req && !full;
wire pop_ack = i_ce && pop && !empty;   // request accepted this sample
wire do_pop  = i_ce && pop_s3;          // its data phase, four samples on

    always @(posedge clk) begin
        if (i_ce) begin
            if (raw != deb) begin
                if (stab == 2'd2) stab <= 2'd0;
                else              stab <= stab + 2'd1;
            end else begin
                stab <= 2'd0;
            end
            if (deb_commit) deb <= raw;

            if (do_push) begin
               mem[wptr] <= deb_commit ? raw : deb;
               wptr      <= wnext;
               tail      <= wnext;
               wnext     <= wnext + 2'd1;
            end

           // the refresh prescaler runs off the sample clock; a refresh
           // request retires only once it actually wins the write port
           hb <= hb + 2'd1;
           if (hb_req) hb_pend <= deb_commit || full;

           // walk accepted read requests down the access pipeline
           pop_s0 <= pop_ack;
           pop_s1 <= pop_s0;
           pop_s2 <= pop_s1;
           pop_s3 <= pop_s2;

            if (do_pop) begin
                o_level <= mem[rptr];
                rptr    <= rptr + 2'd1;
            end

// log the push at the write and the pop at the accept, so the
// difference excludes reads that are still in flight
           if (do_push) n_push <= n_push + 3'd1;
if (pop_ack) n_pop  <= n_pop  + 3'd1;

            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase

            if (count == 3'd4) never_full <= 1'b0;
        end
        pv <= 1'b1;
    end

    // Precedence, before-first-full scope, stated about the previous cycle:
    // if the queue has just been drained empty by a pop, the read pointer must
    // have reached the write-pointer snapshot recorded at the earlier push.
    always @(posedge clk)
        if (pv && never_full && (count == 3'd0) && $past(do_pop))
            assert (rptr == $past(tail));
endmodule

// Debug-probe challenge sequencer: a maximal-length LFSR supplies one tick per
// chain step (arm -> start -> finish). The LFSR is seeded non-zero and can never
// enter the all-zeros lockup state, so every FSM advance is accompanied by a
// genuine change of the challenge shift register.
module probe_chain_seq (
    input  wire       clk,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire       arm,
    input  wire       start,
    input  wire       fin,
    output reg  [1:0] stage,
    output reg        pre_done,
    output reg  [3:0] chal
);
    // stage encoding: 0 = IDLE, 1 = ARMED, 2 = RUNNING, 3 = DONE
    reg [3:0] lfsr;
    reg       pv;
    // channel B: second probe chain sharing the one challenge generator
    reg [1:0] stage_b;
    reg       own;      // 0 = chain A holds the generator, 1 = chain B
    reg       ld;       // generator context restore in flight (owner stalls)
    reg       chal_ok;  // chal holds a valid generator word
  // the challenge register is written over a 2-bit-wide debug bus, so a new
  // word lands in two beats: the low half is driven immediately and the high
  // half is staged here until the following enabled cycle
  reg [1:0] chal_hi;
  reg       chal_ph;  // high half still owed to the challenge register
   // per-chain generator context: a chain preempted by the arbiter resumes
   // its own point in the challenge stream when it gets the generator back
   reg [3:0] ctx_a;
   reg [3:0] ctx_b;
   reg [2:0] tmr;      // round-robin time slice for the shared generator

    initial lfsr     = 4'b0001;
    initial chal     = 4'b0000;
    initial stage    = 2'd0;
    initial pre_done = 1'b1;   // before-scope: high until the first DONE ever
    initial pv       = 1'b0;
    initial stage_b  = 2'd0;
    initial own      = 1'b0;
    initial ld       = 1'b0;
    initial chal_ok  = 1'b0;
  initial chal_hi  = 2'b00;
  initial chal_ph  = 1'b0;
   initial ctx_a    = 4'b0000;
   initial ctx_b    = 4'b0000;
   initial tmr      = 3'd7;

    // x^4 + x^3 + 1 : period 15 over the non-zero states
    wire       fb        = lfsr[3] ^ lfsr[2];
    wire [3:0] lfsr_next = {lfsr[2:0], fb};

   // A chain that has left IDLE owns a parked generator word and resumes from
   // it; a chain that is IDLE starts cold from the last challenge issued on
   // the shared bus, or from the cold seed if none has been issued yet.
   wire       in_a      = (stage   != 2'd0);
   wire       in_b      = (stage_b != 2'd0);
   wire [3:0] cold      = chal_ok ? chal : 4'b0001;
   wire [3:0] lfsr_rest = own ? (in_b ? ctx_b : cold)
                              : (in_a ? ctx_a : cold);

    // the current owner releases the generator once its chain reaches DONE
    wire a_done = (stage   == 2'd3);
    wire b_done = (stage_b == 2'd3);
   // ... or when its arbitration time slice expires, so a chain that stalls
   // mid-run cannot hold the shared generator forever
   wire slice_up = (tmr == 3'd0);
   wire yield    = !ld && (slice_up || (own ? b_done : a_done));

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            lfsr <= ld ? lfsr_rest : lfsr_next;
           if (yield) begin
               own <= ~own;
               if (own) ctx_b <= lfsr_next;   // park the outgoing chain's stream
               else     ctx_a <= lfsr_next;
               tmr <= 3'd7;
           end else if (!ld) begin
               tmr <= tmr - 3'd1;
           end
            ld <= yield;
          // second beat: the staged high half lands and the challenge word
          // becomes valid for chains that start cold from the shared bus
          if (chal_ph) begin
              chal[3:2] <= chal_hi;
              chal_ok   <= 1'b1;
              chal_ph   <= 1'b0;
          end
            if (!ld) begin
            if (!own) begin
            case (stage)
               2'd0: if (arm && !chal_ph) begin
                          stage <= 2'd1;
                         chal[1:0] <= lfsr[1:0];   // first beat on the bus
                         chal_hi   <= lfsr[3:2];    // high half next cycle
                         chal_ph   <= 1'b1;
                         chal_ok   <= 1'b0;         // incomplete until commit
                     ctx_a <= lfsr_next;  // resume point for this chain
                      end
                2'd1: if (start) stage <= 2'd2;
                2'd2: if (fin) begin
                          stage    <= 2'd3;   // finish: clears the before-scope
                          pre_done <= 1'b0;
                      end
                default: stage <= 2'd0;
            endcase
            end else begin
                case (stage_b)
                   2'd0: if (arm && !chal_ph) begin
                              stage_b <= 2'd1;
                             chal[1:0] <= lfsr[1:0];
                             chal_hi   <= lfsr[3:2];
                             chal_ph   <= 1'b1;
                             chal_ok   <= 1'b0;
                             ctx_b <= lfsr_next;
                          end
                    2'd1: if (start) stage_b <= 2'd2;
                    2'd2: if (fin)   stage_b <= 2'd3;
                    default: stage_b <= 2'd0;
                endcase
            end
            end
        end
    end

    // P: before the first finish has ever been observed, the chain FSM cannot
    //    move unless the challenge shift register moved with it.
    always @(posedge clk)
        if (pv && pre_done && $stable(lfsr))
            assert ($stable(stage));
endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

   // destination-side retiming pipeline: the event decoder sits far from the
   // synchronizer in the floorplan, so the sampled pointer is retimed four
   // times before it is decoded, and both decode operands are taken from
   // the last two taps of this pipeline so they share the same route delay
   reg [2:0] ret1;
   initial   ret1 = 3'b000;
   reg [2:0] ret2;
   initial   ret2 = 3'b000;
   reg [2:0] ret3;
   initial   ret3 = 3'b000;
   reg [2:0] ret4;
   initial   ret4 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;
   // number of chain transitions actually taken.  A corrupt handshake aborts
   // straight to FINISH, so the transition count is what tells a full walk
   // of the chain apart from an aborted one.
   reg [2:0] steps;
   initial   steps = 3'd0;
  // legs of the walk currently in flight.  steps is a status field read by
  // the host, so it is written once per handshake instead of once per leg:
  // the decoder parks intermediate legs here and the terminating leg flushes
  // the whole batch into steps in a single update.
  reg [1:0] credit;
  initial   credit = 2'd0;

    wire [2:0] gray  = bin ^ (bin >> 1);
   wire [2:0] delta = ret3 ^ ret4;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
           ret1      <= 3'b000;
           ret2      <= 3'b000;
           ret3      <= 3'b000;
           ret4      <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
           steps     <= 3'd0;
           credit    <= 2'd0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;
           ret1  <= sync2;
           ret2  <= ret1;
           ret3  <= ret2;
           ret4  <= ret3;

            if (bad_ev) begin
                stage <= S_FINISH;
               steps  <= steps + {1'b0, credit} + 3'd1;
               credit <= 2'd0;
            end else begin
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                       credit  <= credit + 2'd1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                       credit    <= credit + 2'd1;
                    end
                S_STARTED:
                   if (fin_ev) begin
                       stage <= S_FINISH;
                      steps  <= steps + {1'b0, credit} + 3'd1;
                      credit <= 2'd0;
                   end
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
   assign o_done  = (stage == S_FINISH) && (steps == 3'd3);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
   // an abort reaches FINISH without walking the chain, so a FINISH that the
   // done output is allowed to honour must show all three transitions counted
   always @(posedge i_clk)
       if (stage == S_FINISH)
           assert (steps == 3'd3);
endmodule

module dma_burst_engine (
    input  wire       clk,
    input  wire       i_ce,     // idle condition: low freezes all state
    input  wire       start,    // Q: opens the status window
    input  wire [3:0] len,      // requested burst length (beats)
    input  wire       ack,      // R: host acknowledges, closes the window
    output reg        busy,
    output reg  [3:0] beats
);
    // shadow register: records the length that was requested earlier
    reg [3:0] req_len;
    // beats actually pushed out so far in the current burst
    reg [3:0] done_cnt;
    // window register: set by start, cleared by ack
    reg       armed;
   // beats deferred past the 8-beat hardware burst limit of the current request
   reg [3:0] resid;
// credit-return coalescing: the fabric returns completion credit in groups of
// four, so beats already pushed may sit here before reaching done_cnt
reg [2:0] pend;
// fabric issue stage: a beat handed to the fabric in this cycle has left
// beats but its completion credit only arrives on the following cycle
reg        iq;

    initial busy     = 1'b0;
    initial beats    = 4'd0;
    initial req_len  = 4'd0;
    initial done_cnt = 4'd0;
    initial armed    = 1'b0;
   initial resid    = 4'd0;
initial pend     = 3'd0;
initial iq       = 1'b0;

    wire accept = start && !armed && (len != 4'd0);
   // the fabric accepts at most 8 beats in one burst; the rest is deferred
   wire [3:0] chunk = (len > 4'd8) ? 4'd8 : len;
wire [2:0] pend_nxt  = (pend == 3'd3) ? 3'd0 : pend + 3'd1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
               beats    <= chunk;
                req_len  <= len;      // shadow capture of the earlier event
               resid    <= len - chunk;
                done_cnt <= 4'd0;
pend     <= 3'd0;
iq       <= 1'b0;
                busy     <= 1'b1;
                armed    <= 1'b1;
end else if (busy && beats != 4'd0) begin
               beats    <= (beats == 4'd1 && resid != 4'd0) ? resid : beats - 4'd1;
resid    <= (beats == 4'd1) ? 4'd0 : resid;
// one beat is handed to the fabric now; its credit lands next cycle
iq       <= 1'b1;
// the beat issued on the previous cycle returns its credit now, and is
// held here until a full group of four is ready
pend     <= iq ? pend_nxt : pend;
done_cnt <= (iq && pend == 3'd3) ? done_cnt + 4'd4 : done_cnt;
busy     <= 1'b1;
end else if (busy && iq) begin
// every beat has been issued: drain the credit of the last issued beat
iq       <= 1'b0;
pend     <= pend_nxt;
done_cnt <= (pend == 3'd3) ? done_cnt + 4'd4 : done_cnt;
busy     <= (pend_nxt != 3'd0);
end else if (busy) begin
// trailing partial credit group flushed before the burst reports done
done_cnt <= done_cnt + {1'b0, pend};
pend     <= 3'd0;
busy     <= 1'b0;
            end else if (armed && ack) begin
                armed    <= 1'b0;
            end
        end
    end

    // P, part 1: inside the window, while beats remain the burst cannot yet have
    // delivered everything that was requested earlier.
    always @(posedge clk)
        if (armed && busy)
            assert (done_cnt < req_len);

    // P, part 2: inside the window, once the engine is no longer busy the
    // delivered count must exactly match the earlier requested length.
    always @(posedge clk)
        if (armed && !busy)
            assert (done_cnt == req_len);

   // P, part 3: inside the window, while a deferred chunk is still queued the
   // beats already pushed plus the beats still held back must leave headroom
   // inside the length that was requested earlier.
   always @(posedge clk)
       if (armed && resid != 4'd0)
           assert (({1'b0,done_cnt} + {1'b0,resid}) < {1'b0,req_len});
endmodule

module handshake_deadline (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       start,     // upstream wants a parse burst
    input  wire       done,      // target signals completion early
    output wire       req,
    output wire       ack,
    output wire       busy_o,
    output wire       timeout
);
    // four-phase handshake: IDLE -> REQ (req rises) -> ACK (ack rises)
    //                       -> DROP (req drops) -> IDLE (ack drops)
    localparam [1:0] P_IDLE = 2'd0,
                     P_REQ  = 2'd1,
                     P_ACK  = 2'd2,
                     P_DROP = 2'd3;

    reg [1:0] phase = P_IDLE;   // handshake phase
    reg       busy  = 1'b0;     // mirrors the phase by construction
    reg [2:0] cnt   = 3'd4;     // completion deadline countdown
   reg [2:0] wait_cnt = 3'd0;  // ticks the target made us wait for ack
   reg [2:0] hold  = 3'd0;     // ack hold time still owed in the drop phase
reg [2:0] budget = 3'd4;    // completion window currently programmed
reg [2:0] budget_nxt;       // window handed to the next burst

    assign req    = (phase == P_REQ)  || (phase == P_ACK);
    assign ack    = (phase == P_ACK)  || (phase == P_DROP);
    assign busy_o = busy;

    // the deadline has expired while the engine is still engaged
    assign timeout = busy && (cnt == 3'd0);

   // retune the window from the latency the target just showed us
   always @(*) begin
       budget_nxt = budget;
       if (wait_cnt == 3'd0 && budget > 3'd2)
           budget_nxt = budget - 3'd1;                 // instant target: tighten
       else if (wait_cnt != 3'd0 && wait_cnt >= budget - 3'd1 && budget < 3'd4)
           budget_nxt = budget + 3'd1;                 // target ran it out: relax
   end

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                P_IDLE: begin
                    if (start) begin
                        phase <= P_REQ;   // req rises
                        busy  <= 1'b1;
                    end
                end
                P_REQ: begin
                    // req may not drop here; the target must raise ack first.
                    // the deadline forces the ack phase on the last tick,
                    // so the countdown can never run through zero.
                    if (done || cnt <= 3'd1)
                        phase <= P_ACK;   // ack rises
                   else begin
                       cnt      <= cnt - 3'd1;
                       wait_cnt <= wait_cnt + 3'd1;  // log the wait
                   end
                end
                P_ACK: begin
                   // fast target: ack came back on the first tick, so there
                   // is nothing left to drain - finish without a drop phase
                   if (wait_cnt == 3'd0) begin
                       phase <= P_IDLE;
                       busy  <= 1'b0;
cnt    <= budget_nxt;
budget <= budget_nxt;
                   end else begin
                       phase <= P_DROP;  // req drops, ack still high
                      hold  <= wait_cnt;  // hold ack as long as the target stalled us
                   end
                end
                P_DROP: begin
                   if (hold > 3'd1) begin
                       hold <= hold - 3'd1;  // ack stays high a bit longer
                   end else begin
                       phase <= P_IDLE;      // ack drops
                       busy  <= 1'b0;
cnt    <= budget_nxt;   // rearm with the retuned window
budget <= budget_nxt;
                       wait_cnt <= 3'd0;     // clear the latency monitor
                       hold  <= 3'd0;
                   end
                end
            endcase
        end
    end

    // P1: the completion deadline never expires while the engine is engaged
    always @(posedge clk)
        assert (!timeout);

    // P2: while a request is outstanding the deadline is a live value
    always @(posedge clk)
        if (phase == 2'd1)
            assert (cnt >= 3'd1 && cnt <= 3'd4);

   // P3: the latency monitor never reports a wait longer than the window
   always @(posedge clk)
       if (busy) assert (wait_cnt <= 3'd3);

  // P4: the ack hold never outlasts the deadline budget
  always @(posedge clk)
      if (phase == 2'd3) assert (cnt + hold <= 3'd4);
endmodule

module serial_retire_counter (
    input  wire i_clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_bit,
    output wire o_word_done,
    output wire o_saturated
);
    // Bit-serial datapath: one bit per enabled cycle, 32 bits per word.
    // Every completed 32-bit word retires one operation; the retire counter
    // is a saturating up-counter that clamps at 20, well below the 31 its
    // 5-bit register could hold.
    localparam [4:0] MAX_RETIRE = 5'd20;

    reg [4:0]  sh;       // serial bit index 0..31
    reg [31:0] word;     // serial shift register (datapath flavour)
    reg [4:0]  retired;  // saturating up-counter, clamps at MAX_RETIRE
    reg        done;     // "counter has reached the clamp" flag
   reg [4:0]  pend;    // retire credits posted but not yet counted
  reg [4:0]  stg;     // staging slot: this word's credit, before merge
  // Credit ledger for occupancy audit: every post and every release is
  // logged.  Free-running, wraps at 5 bits; the queue depth reported to the
  // saturation accounting is the difference of the two logs.
  reg [4:0]  n_post;  // credits posted  (enqueue side of the ledger)
  reg [4:0]  n_rel;   // credits released (dequeue side of the ledger)

    initial sh      = 5'd0;
    initial word    = 32'd0;
    initial retired = 5'd0;
    initial done    = 1'b0;
   initial pend    = 5'd0;
  initial stg     = 5'd0;
  initial n_post  = 5'd0;
  initial n_rel   = 5'd0;

   // Retirement is credited through a small pending-credit queue: a completed
   // word posts one credit, and the retire counter's write port (shared with
   // word capture) releases one credit on any enabled cycle that is not a
   // word boundary.  Saturation is declared on the total, posted + counted.
  // The credit queue is split across two registers so the post side and the
  // release side never contend for the same write port: a credit posted at a
  // word boundary lands in the staging slot stg, merges into pend on the next
  // enabled non-boundary cycle, and releases are taken from pend only.

    wire word_last = (sh == 5'd31);

  wire [4:0] outstanding  = n_post - n_rel;
  wire [5:0] retire_total = {1'b0, retired} + {1'b0, outstanding};
   wire       credit_enq   = word_last && !done;
   wire       credit_deq   = (pend != 5'd0) && !word_last;
  wire       stg_move    = (stg != 5'd0) && !word_last;

    always @(posedge i_clk) begin
        if (i_rst) begin
            sh      <= 5'd0;
            word    <= 32'd0;
            retired <= 5'd0;
            done    <= 1'b0;
           pend    <= 5'd0;
          stg     <= 5'd0;
          n_post  <= 5'd0;
          n_rel   <= 5'd0;
        end else if (i_ce) begin
            sh   <= sh + 5'd1;
            word <= { i_bit, word[31:1] };
          if (credit_enq)
              stg <= stg + 5'd1;
          else if (stg_move)
              stg <= stg - 5'd1;
          if (stg_move && !credit_deq)
              pend <= pend + 5'd1;
          else if (credit_deq && !stg_move)
              pend <= pend - 5'd1;
           if (credit_deq)
               retired <= retired + 5'd1;
          if (credit_enq)
              n_post <= n_post + 5'd1;
          if (credit_deq)
              n_rel <= n_rel + 5'd1;
           if (credit_enq)
               done <= (retire_total == {1'b0, (MAX_RETIRE - 5'd1)});
        end
    end

    assign o_word_done = word_last;
    assign o_saturated = done;

    // P: the retire count never exceeds 20, although the register admits 31.
    always @(posedge i_clk)
        assert (retired <= MAX_RETIRE);
endmodule

module token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle condition: nothing moves when low
    input  wire       req,
    output reg        grant_q,
    output reg [3:0]  tokens
);
    localparam [3:0] BURST  = 4'd12; // bucket cap
    localparam [3:0] REFILL = 4'd3;  // tokens added per timer tick
    localparam [2:0] PERIOD = 3'd4;  // refill timer top
   localparam [3:0] SOFT    = 4'd8; // tokens kept in the live bucket
   localparam [3:0] RESVMAX = 4'd6; // reserve pool cap

    reg [2:0] timer;
    reg       saw_refill;            // shadow: a refill tick has occurred
   // Overflow reserve: refill above SOFT is parked here instead of being
   // thrown away by the clamp, and trickles back one token at a time when
   // the live bucket runs dry.
   reg [3:0] resv;

   // Refill commit pipeline: the bucket adder/clamp is registered, so the
   // token target computed at a timer tick is applied four cycles later.
   // Layout of each stage: {valid, precomputed token target}.
   reg [4:0] rf_s1, rf_s2, rf_s3, rf_s4;
  // Reserve handoff register: the trickle out of the reserve pool is now
  // registered, so a token leaves resv on one enabled cycle and lands in
  // the live bucket on the next. Only one trickle is in flight at a time.
  reg       hand_v;
  reg [3:0] hand_tok;

    wire       tick     = (timer == PERIOD);
    wire       do_grant = ce && req && (tokens != 4'd0);
    wire [4:0] sum      = {1'b0, tokens} + {1'b0, REFILL};
    wire [3:0] refilled = (sum > {1'b0, BURST}) ? BURST : sum[3:0];
   wire       commit   = rf_s4[4];
   wire [3:0] target   = rf_s4[3:0];
  wire [3:0] eff_target = (target > SOFT) ? SOFT : target;
  wire [3:0] excess     = (target > SOFT) ? (target - SOFT) : 4'd0;
  wire [4:0] resv_sum   = {1'b0, resv} + {1'b0, excess};
 wire [3:0] hand_amt   = (resv >= 4'd2) ? 4'd2 : 4'd1;
 wire       drain      = !commit && (tokens == 4'd0) && (resv != 4'd0) && !hand_v;

    initial begin
        timer      = 3'd0;
        tokens     = 4'd0;
        saw_refill = 1'b0;
       resv       = 4'd0;
        grant_q    = 1'b0;
       rf_s1      = 5'd0;
       rf_s2      = 5'd0;
       rf_s3      = 5'd0;
       rf_s4      = 5'd0;
      hand_v     = 1'b0;
      hand_tok   = 4'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            timer      <= 3'd0;
            tokens     <= 4'd0;
            saw_refill <= 1'b0;
           resv       <= 4'd0;
            grant_q    <= 1'b0;
           rf_s1      <= 5'd0;
           rf_s2      <= 5'd0;
           rf_s3      <= 5'd0;
           rf_s4      <= 5'd0;
          hand_v     <= 1'b0;
          hand_tok   <= 4'd0;
        end else if (ce) begin
            timer   <= tick ? 3'd0 : (timer + 3'd1);
            grant_q <= do_grant;

           // stage the refill: capture the clamped target at the tick and
           // walk it down the pipeline, one stage per enabled cycle
           rf_s1 <= {tick, refilled};
           rf_s2 <= rf_s1;
           rf_s3 <= rf_s2;
           rf_s4 <= rf_s3;

          // post the trickle amount now; it is deposited in the bucket on
          // the next enabled cycle
          hand_v   <= drain;
          hand_tok <= drain ? hand_amt : 4'd0;

            if (tick)
                saw_refill <= 1'b1;

           case ({commit, do_grant})
              2'b10:   tokens <= eff_target;
                2'b01:   tokens <= tokens - 4'd1;
              2'b11:   tokens <= (eff_target == 4'd0) ? 4'd0 : (eff_target - 4'd1);
              default: tokens <= hand_v ? hand_tok : tokens;
            endcase

          // reserve bookkeeping: soak up the clamped surplus, or hand one
          // token back to the live bucket when it has emptied out
          if (commit)
              resv <= (resv_sum > {1'b0, RESVMAX}) ? RESVMAX : resv_sum[3:0];
          else if (drain)
             resv <= resv - hand_amt;
        end
    end

    // Precedence: a registered grant can only be observed if a refill tick
    // was recorded earlier in the shadow bit.
    always @(posedge clk)
        if (grant_q)
            assert (saw_refill);

endmodule

// Triple-modular-redundant power-rail sequencer step counter.
// Three shadow copies of the sequencer step code are advanced independently;
// the exported step code is the bitwise majority vote of the three copies.
// prev_voted is a precedence shadow: it records the voted code as it was at
// the previous advance, so the present code must be the successor of the code
// that was observed earlier.
module tmr_rail_sequencer (
    input  wire       clk,
    input  wire       ce,        // advance / load enable; low => design idles
    input  wire       load,      // reload the sequencer with an external code
    input  wire [2:0] code_in,
    input  wire       q_start,   // opens the monitoring window
    input  wire       r_stop,    // closes the monitoring window
    output wire [2:0] voted
);

    // three shadow registers of the TMR voter
    reg [2:0] shadow_a = 3'd1;
    reg [2:0] shadow_b = 3'd1;
    reg [2:0] shadow_c = 3'd1;
    // Ring bounds of the rail ramp. The last load fixes the origin:
    // base_code is the first code of the ring and top_code the code after
    // which the sequencer wraps back to the origin. at_top is the registered
    // terminal-count flag, kept out of the voter's compare path.
    reg [2:0] base_code = 3'd1;
    reg [2:0] top_code  = 3'd0;
    reg       at_top    = 1'b0;
   // Wrap reseed value: the predecessor of the ring origin, captured when the
   // origin is loaded so that the wrap path carries no decrementer.
   reg [2:0] seed_code = 3'd0;
   // Load phase: alternate loads program the origin, then the wrap point.
   reg       cfg_sel   = 1'b0;

// Precedence shadow, split for radiation tolerance: the low two bits of the
// recorded code ripple in prev_lo, while its top bit is kept as a dual-rail
// pair whose advance is a swap of the two rails.
reg [1:0] prev_lo   = 2'd0;
reg       prev_hi_t = 1'b0;
reg       prev_hi_f = 1'b1;

    // window register: set by q_start, cleared by r_stop, reopenable
    reg       win = 1'b0;

    // bitwise majority vote
    assign voted = (shadow_a & shadow_b) | (shadow_a & shadow_c) |
                   (shadow_b & shadow_c);

// recomposed precedence code
wire [2:0] prev_voted = {prev_hi_t, prev_lo};
    // code the shadows will hold after the next advance
    wire [2:0] next_code = at_top ? base_code : voted + 3'd1;
   // Diverse terminal check for the precedence path: it re-derives the wrap
   // condition from the voted code instead of reusing the voter's flag.
   wire       prev_wrap = (voted == top_code);

    always @(posedge clk) begin
        if (ce) begin
            if (load) begin
               if (!cfg_sel) begin
                shadow_a   <= code_in;
                shadow_b   <= code_in;
                shadow_c   <= code_in;
prev_lo   <= code_in[1:0] - 2'd1;
prev_hi_t <= code_in[2] ^ (code_in[1:0] == 2'd0);
prev_hi_f <= ~(code_in[2] ^ (code_in[1:0] == 2'd0));
               base_code  <= code_in;
               seed_code  <= code_in - 3'd1;
               top_code   <= code_in - 3'd1;
               at_top     <= 1'b0;
               end else begin
                   // a second load moves the wrap point of the ramp
                   top_code <= code_in;
                   at_top   <= (voted == code_in);
               end
               cfg_sel <= ~cfg_sel;
            end else begin
               if (at_top) begin
                   shadow_a   <= base_code;
                   shadow_b   <= base_code;
                   shadow_c   <= base_code;
               end else begin
                   shadow_a   <= shadow_a + 3'd1;
                   shadow_b   <= shadow_b + 3'd1;
                   shadow_c   <= shadow_c + 3'd1;
               end
               at_top <= (next_code == top_code);
              if (prev_wrap) begin
                  // reseed the precedence shadow to the origin's predecessor
                  prev_lo   <= seed_code[1:0];
                  prev_hi_t <= seed_code[2];
                  prev_hi_f <= ~seed_code[2];
              end else begin
                  prev_lo <= voted[1:0];
                  // the top bit only moves when the low part rolls over
                  if (prev_lo == 2'd3) begin
                      prev_hi_t <= prev_hi_f;
                      prev_hi_f <= prev_hi_t;
                  end
              end
            end
        end
    end

    always @(posedge clk) begin
        if (r_stop)
            win <= 1'b0;
        else if (q_start)
            win <= 1'b1;
    end

    // Property: inside the monitoring window, the voted step code must be the
    // immediate successor of the code recorded earlier in prev_voted.
    always @(posedge clk)
        assert (!win || (voted == prev_voted + 3'd1));

endmodule

// Sliding-window grant rate limiter: an 8-cycle shift register of recent
// grants plus an occupancy counter that mirrors its population count.
// A grant may only be issued if no grant occurred in the last two cycles,
// which spaces grants at least 3 cycles apart and therefore caps the
// occupancy of the 8-deep window at 3, far below the 4-bit counter range.
// Grants now ping-pong between two sinks, each with its own 8-cycle window;
// the spacing rule is held in one cooldown counter shared by both sinks.
// The two sinks share one occupancy accumulator: ones reports the total number
// of in-flight grants across both windows. The add is retimed to shorten the
// accumulator path, so each sink stages its own +1 for a cycle (ones_pend,
// ones_pend_b) and the accumulator picks the staged carry up on the next one.
// The retire port is shared as well, since the two windows never age a grant
// out of the tail on the same cycle.
module grant_window_limiter (
    input  wire       clk,
    input  wire       ce,      // idle when low: no state changes
    input  wire       req,
    output wire       grant,
    output reg  [7:0] win,
    output reg  [3:0] ones
);

    reg armed = 1'b0;   // sticky: set the first time a grant is issued
    reg pv    = 1'b0;   // past-valid
    reg [7:0] win_b = 8'b0000_0000;  // sink B's window, same 8-cycle depth
    reg [1:0] cool  = 2'd0;          // shared spacing cooldown, loaded by either sink
    reg       sel   = 1'b0;          // ping-pong pointer: 0 = next grant goes to sink A
reg       ones_pend   = 1'b0;    // staged +1 from a fresh sink-A grant
reg       ones_pend_b = 1'b0;    // staged +1 from a fresh sink-B grant

    initial win  = 8'b0000_0000;
    initial ones = 4'd0;

    // spacing rule, now carried by the shared cooldown: a grant to either sink
    // blocks the shared issue path for the following two cycles
    wire allow = (cool == 2'd0);
    wire g     = ce && req && allow;
    wire to_b  = sel;                // this grant is tagged for sink B
wire retire = win[7] || win_b[7];  // shared retire port into the accumulator

    assign grant = g;

    always @(posedge clk) begin
        if (ce) begin
            win   <= {win[6:0], g && !to_b};
            win_b <= {win_b[6:0], g && to_b};
ones_pend   <= g && !to_b;
ones_pend_b <= g && to_b;
ones        <= ones + (ones_pend ? 4'd1 : 4'd0) + (ones_pend_b ? 4'd1 : 4'd0)
                    - (retire ? 4'd1 : 4'd0);
            cool  <= g ? 2'd2 : ((cool == 2'd0) ? 2'd0 : cool - 2'd1);
            if (g)
                sel <= ~sel;
        end
        if (g)
            armed <= 1'b1;
        pv <= 1'b1;
    end

    // Bounded existence, at most 3, in the scope after the first grant.
    always @(posedge clk)
        if (pv && armed)
            assert ((ones <= 4'd3) && ($past(ones) <= 4'd3));

endmodule

module chess_clock_seq_alarm (
    input  wire clk,
    input  wire i_ce,      // clock tick enable; low freezes the whole mechanism
    input  wire sym,       // observed press: 1 = white side, 0 = black side
    output reg  alarm
);
    // match-progress register for the fixed press pattern 1,0,1,1
    // (white, black, white, white) -- the blitz alarm trigger
    reg [2:0] prog;
    // shadow register: latches that the half-way progress (2 symbols) occurred
    reg       seen_half;
    // "before R" scope register: high until the alarm pattern first completes
    reg       before_alarm;
   // commit stage: the decoder's next-progress value waits one tick here
   // before it is retired into the matcher, keeping the decode path short
   reg [2:0] stg;
   reg       stg_v;       // a staged progress value is pending commit
  // black-turn tally: how many times the matcher has passed the half-way
  // point since power-up. The blitz time control also ends the game once
  // this tally reaches its limit of seven, so it feeds the alarm too.
  reg [2:0] hcnt;
 // black-side peer matcher for the press pattern 0,1,0,0 (black, white,
 // black, black) -- the other side's blitz trigger. It shares the commit
 // stage and the tally's single increment port with the white-side matcher.
 reg [2:0] prog2;
 reg [2:0] stg2;
 // the tally adder accepts one increment per tick; a half-way pass that
 // loses the arbitration is owed and is retired in the commit phase
 reg       hpend;
 reg       harb;   // round-robin pointer for the tally increment port

    initial prog         = 3'd0;
    initial seen_half    = 1'b0;
    initial before_alarm = 1'b1;
    initial alarm        = 1'b0;
   initial stg          = 3'd0;
   initial stg_v        = 1'b0;
  initial hcnt         = 3'd0;
 initial prog2        = 3'd0;
 initial stg2         = 3'd0;
 initial hpend        = 1'b0;
 initial harb         = 1'b0;

    reg [2:0] nxt;
   reg [2:0] nxt2;
   // a press is only consumed in the decode phase
   wire match = (prog == 3'd3) && sym && !stg_v;
  wire match2 = (prog2 == 3'd3) && !sym && !stg_v;
  // tally requests: either matcher asks when it passes its half-way point
  wire req1 = (nxt  == 3'd2);
  wire req2 = (nxt2 == 3'd2);
  wire gnt1 = req1 && (!req2 || !harb);
  wire gnt2 = req2 && (!req1 ||  harb);

    always @(*) begin
        case (prog)
            3'd0: nxt = sym ? 3'd1 : 3'd0;
            3'd1: nxt = sym ? 3'd1 : 3'd2;
            3'd2: nxt = sym ? 3'd3 : 3'd0;
            3'd3: nxt = sym ? 3'd0 : 3'd2;  // overlap: "10" survives
            default: nxt = 3'd0;
        endcase
    end

   always @(*) begin
       case (prog2)
           3'd0: nxt2 = sym ? 3'd0 : 3'd1;
           3'd1: nxt2 = sym ? 3'd2 : 3'd1;
           3'd2: nxt2 = sym ? 3'd0 : 3'd3;
           3'd3: nxt2 = sym ? 3'd2 : 3'd0;  // overlap: "01" survives
           default: nxt2 = 3'd0;
       endcase
   end

    always @(posedge clk) begin
        if (i_ce) begin
           if (!stg_v) begin
               // decode phase: consume the press, stage the new progress
               stg       <= nxt;
              stg2      <= nxt2;
               stg_v     <= 1'b1;
               seen_half <= seen_half | (nxt == 3'd2);
             if ((gnt1 || gnt2) && (hcnt != 3'd7))
                 hcnt <= hcnt + 3'd1;
             // whichever half-way pass lost the port is owed an increment
             hpend     <= (req1 && !gnt1) || (req2 && !gnt2);
             if (req1 && req2)
                 harb <= ~harb;
              // the alarm sounds on the pattern match, and also on the press
              // that takes the black-turn tally to its limit
             alarm     <= match | match2 |
                          ((gnt1 || gnt2) && (hcnt == 3'd6));
               if (match)
                   before_alarm <= 1'b0;
           end else begin
               // commit phase: retire the staged progress into the matcher
               prog      <= stg;
              prog2     <= stg2;
               stg_v     <= 1'b0;
             // the owed increment retires now that the adder is idle
             if (hpend && (hcnt != 3'd7))
                 hcnt <= hcnt + 3'd1;
             hpend     <= 1'b0;
             alarm     <= hpend && (hcnt == 3'd6);
               if (stg == 3'd0)
                   seen_half <= 1'b0;   // matcher restarted from scratch
           end
        end
    end

    // Precedence, in the scope before the alarm has ever fired:
    // three-quarter progress can only be observed if half progress happened earlier.
    always @(posedge clk)
        assert (!before_alarm || (prog != 3'd3) || seen_half);

   // Tally accounting, in the scope before the alarm has ever fired:
   // three-quarter progress cannot be on record while the black-turn tally
   // is still empty, because reaching it costs one black press.
   always @(posedge clk)
       assert (!before_alarm || (prog != 3'd3) || (hcnt != 3'd0));
endmodule

module axi_grant_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire [3:0] req,
    input  wire       done,
    output reg        gnt_valid,
    output reg [1:0]  gnt_idx,
    output reg [2:0]  timer,
    output reg [2:0]  elapsed,
output wire [3:0] o_gnt,
output reg [3:0]  req_hist
);
    // Latency budget granted to an accepted request.
localparam [2:0] BUDGET_MAX = 3'd5;
localparam [2:0] BUDGET_MIN = 3'd3;

// Adaptive latency allowance. A slave that times out earns one extra
// credit for the next requester; a slave that answers within a cycle
// gives one back. Only rewritten in the gap between grants.
reg [2:0] budget;
// Latency of the most recently completed transaction, in cycles. Feeds
// the budget hysteresis below: the window is only narrowed after two
// quick responses in a row, so a single lucky slave cannot starve the
// next requester.
reg [2:0] last_lat;

    // ---------------------------------------------------------------
    // Priority encoder over the request vector: lowest index wins.
    // The encoded index is only meaningful while gnt_valid is set.
    // ---------------------------------------------------------------
    wire       enc_valid = |req;
    wire [1:0] enc_idx   = req[0] ? 2'd0 :
                           req[1] ? 2'd1 :
                           req[2] ? 2'd2 : 2'd3;

    // Retirement of the outstanding grant: either the slave answered,
    // or the budget has been fully consumed.
wire retire = gnt_valid && (done || ((elapsed == (budget - 3'd1)) && (timer == 3'd1)));

    assign o_gnt = gnt_valid ? (4'b0001 << gnt_idx) : 4'b0000;

    initial gnt_valid = 1'b0;
    initial gnt_idx   = 2'd0;
    initial timer     = 3'd0;
    initial elapsed   = 3'd0;
initial budget    = BUDGET_MAX;
initial last_lat  = 3'd0;
initial req_hist  = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            gnt_valid <= 1'b0;
            gnt_idx   <= 2'd0;
            timer     <= 3'd0;
            elapsed   <= 3'd0;
budget    <= BUDGET_MAX;
last_lat  <= 3'd0;
req_hist  <= 4'd0;
        end else if (i_ce) begin
req_hist <= {req_hist[2:0], (|req) & ~done};
            if (!gnt_valid) begin
                if (enc_valid) begin
                    gnt_valid <= 1'b1;
                    gnt_idx   <= enc_idx;
timer     <= budget;   // credits left
                    elapsed   <= 3'd0;     // cycles burnt
                end
            end else if (retire) begin
                gnt_valid <= 1'b0;
                timer     <= 3'd0;
                elapsed   <= 3'd0;
last_lat  <= elapsed;
if (!done)
    budget <= (budget == BUDGET_MAX) ? BUDGET_MAX : budget + 3'd1;
else if ((elapsed <= 3'd1) && (last_lat <= 3'd1))
    budget <= (budget == BUDGET_MIN) ? BUDGET_MIN : budget - 3'd1;
            end else begin
                timer   <= timer   - 3'd1;
                elapsed <= elapsed + 3'd1;
            end
        end
    end

    // Bounded response, safety form: the countdown must never reach zero
    // while a grant is still outstanding ...
    always @(posedge clk)
        assert (!gnt_valid || (timer != 3'd0));

    // ... and the elapsed-cycle counter must never run past the budget
    // window while a grant is still outstanding.
    always @(posedge clk)
        assert (!gnt_valid || (elapsed <= 3'd4));

   // Latency monitor: the recorded latency of the last completed
   // transaction always fits strictly inside the widest window the
   // arbiter can hand out, and an outstanding grant never carries more
   // credits than that window either.
   always @(posedge clk)
       assert ((last_lat < BUDGET_MAX) && (!gnt_valid || (timer <= BUDGET_MAX)));
endmodule

module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] req,
    output reg  [3:0] gnt,
    output reg  [1:0] stage
);
    // round-robin arbiter state
    reg [1:0] last_gnt;
    // chain-precedence bookkeeping: arm (line0) -> start (line1) -> finish (line2)
    reg       seen_arm;
    reg       seen_start;
    // sticky scope register: set the first time any grant is issued
    reg       armed;
   // peer chain B: shares the start unit with chain A
   // arm(line2) -> start(line3) -> finish(line1)
   reg [1:0] stage_b;
   // shared start unit is primed and not yet consumed
   reg       start_tok;
 // shared-start-unit ledger: one entry logged per acquire, one per release
 reg [3:0] tok_acq;
 reg [3:0] tok_rel;
  // posted stage-update pipe: a chain A stage advance is handed to the
  // writeback pipe and only lands on the stage register four cycles later.
  // 2'd0 in a slot means "nothing posted here".
  reg [1:0] upd_p0;
  reg [1:0] upd_p1;
  reg [1:0] upd_p2;
  reg [1:0] upd_p3;

    initial begin
        last_gnt   = 2'd3;
        gnt        = 4'b0000;
        stage      = 2'd0;
        seen_arm   = 1'b0;
        seen_start = 1'b0;
        armed      = 1'b0;
       stage_b    = 2'd0;
       start_tok  = 1'b0;
     tok_acq    = 4'd0;
     tok_rel    = 4'd0;
      upd_p0     = 2'd0;
      upd_p1     = 2'd0;
      upd_p2     = 2'd0;
      upd_p3     = 2'd0;
    end

    // combinational round-robin grant: one-hot, never on a non-requesting line
    reg [3:0] gnt_c;
    always @(*) begin
        case (last_gnt)
            2'd0: gnt_c = req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 : 4'b0000;
            2'd1: gnt_c = req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 : 4'b0000;
            2'd2: gnt_c = req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 : 4'b0000;
            default: gnt_c = req[0] ? 4'b0001 :
                             req[1] ? 4'b0010 :
                             req[2] ? 4'b0100 :
                             req[3] ? 4'b1000 : 4'b0000;
        endcase
    end

    wire [1:0] gnt_idx = gnt_c[0] ? 2'd0 :
                         gnt_c[1] ? 2'd1 :
                         gnt_c[2] ? 2'd2 : 2'd3;

    wire fire = i_ce && (gnt_c != 4'b0000);
  // only one stage update may be outstanding in the pipe
  wire upd_busy = (upd_p0 | upd_p1 | upd_p2 | upd_p3) != 2'd0;
 // ledger view of the shared start unit: a nonzero balance means some
 // acquire has not been returned yet, so the unit is still primed
 wire [3:0] tok_bal  = tok_acq - tok_rel;
 wire       tok_out  = (tok_bal != 4'd0);
 // acquire side: chain B primes the unit on its START step
 wire       tok_grab = fire && (stage_b == 2'd1) && gnt_c[3];
 // return side: B consumes it, or chain A tears it down on abort/retire.
 // a teardown that finds no held unit is not a return, so it is not logged.
 wire       tok_drop = fire && !tok_grab && start_tok &&
                       (((stage_b == 2'd2) && gnt_c[1]) ||
                        (stage == 2'd3) ||
                        (((stage == 2'd1) || (stage == 2'd2)) && gnt_c[3]));

    always @(posedge clk) begin
        gnt <= fire ? gnt_c : 4'b0000;
       // shared-start-unit ledger, free running, wraps at 4 bits
       if (tok_grab) tok_acq <= tok_acq + 4'd1;
       if (tok_drop) tok_rel <= tok_rel + 4'd1;
      if (i_ce) begin
          // last slot retires onto the stage register, then the pipe shifts
          if (upd_p3 != 2'd0)
              stage <= upd_p3;
          upd_p3 <= upd_p2;
          upd_p2 <= upd_p1;
          upd_p1 <= upd_p0;
          upd_p0 <= 2'd0;
      end
        if (fire) begin
            last_gnt <= gnt_idx;
            armed    <= 1'b1;
            case (stage)
                2'd0: begin
                   if (gnt_c[0] && !upd_busy) begin
                       upd_p0   <= 2'd1;   // post ARM step
                        seen_arm <= 1'b1;
                    end
                end
                2'd1: begin
                   if (gnt_c[1] && !upd_busy) begin
                       upd_p0     <= 2'd2; // post START step
                        seen_start <= 1'b1;
end else if (tok_out && gnt_c[2] && !upd_busy) begin
                      upd_p0     <= 2'd3; // start unit already primed: skip START
                   end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                       start_tok  <= 1'b0; // release shared start unit
                      upd_p0     <= 2'd0; // abort flushes the posted update
                      upd_p1     <= 2'd0;
                      upd_p2     <= 2'd0;
                      upd_p3     <= 2'd0;
                    end
                end
                2'd2: begin
                   if (gnt_c[2] && !upd_busy) begin
                       upd_p0 <= 2'd3;     // post FINISH step
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                       start_tok  <= 1'b0; // release shared start unit
                      upd_p0     <= 2'd0; // abort flushes the posted update
                      upd_p1     <= 2'd0;
                      upd_p2     <= 2'd0;
                      upd_p3     <= 2'd0;
                    end
                end
                default: begin
                    stage      <= 2'd0;     // retire transaction
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                   start_tok  <= 1'b0;     // release shared start unit
                  upd_p0     <= 2'd0;     // nothing left to post
                  upd_p1     <= 2'd0;
                  upd_p2     <= 2'd0;
                  upd_p3     <= 2'd0;
                end
            endcase
           // peer chain B drives the same start unit from the high lines
           case (stage_b)
               2'd0: if (gnt_c[2]) stage_b <= 2'd1;   // ARM step (B)
               2'd1: if (gnt_c[3]) begin
                         stage_b    <= 2'd2;          // START step (B)
                         seen_start <= 1'b1;          // shared unit has run
                         start_tok  <= 1'b1;          // and stays primed
                     end
               2'd2: if (gnt_c[1]) begin
                         stage_b   <= 2'd3;           // FINISH step (B)
                         start_tok <= 1'b0;           // B consumes the unit
                     end
               default: stage_b <= 2'd0;              // retire B
           endcase
        end
    end

    // P: once the arbiter has ever granted (sticky armed), a finished
    // transaction can only be observed if arm and start really happened.
    always @(posedge clk)
        if (armed && stage == 2'd3)
            assert (seen_arm && seen_start);
endmodule

module dma_burst_dimmer (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // beat enable / idle when low
    input  wire       i_start,
    input  wire [3:0] i_beats,
    input  wire [3:0] i_duty,
    output wire       o_busy,
    output wire       o_beat,
    output wire       o_pwm
);

    // ---- DMA burst engine state ----
    reg [3:0] beats_left;   // beats remaining in the burst
    reg [3:0] done_cnt;     // beats already pushed out
    reg [3:0] total;        // beats requested by the accepted burst
    reg [3:0] duty;         // dimming level latched with the burst
    reg       busy;         // up exactly while beats remain
    reg [3:0] queued;       // beats accepted but not yet issued into the current chunk
   reg [3:0] chunk_pend;   // chunk staged for issue on the next beat
   // ---- fabric ledger: beats booked out to the fabric vs beats it consumed ----
   reg [3:0] n_iss;        // running count of beats issued to the fabric
   reg [3:0] n_ret;        // running count of beats the fabric has consumed

    initial beats_left = 4'd0;
    initial done_cnt   = 4'd0;
    initial total      = 4'd0;
    initial duty       = 4'd0;
    initial busy       = 1'b0;
    initial queued     = 4'd0;
   initial chunk_pend = 4'd0;
   initial n_iss      = 4'd0;
   initial n_ret      = 4'd0;

    // the fabric only accepts short chunks, so a long burst is issued piecewise
    localparam [3:0] CHUNK_MAX = 4'd4;
    wire [3:0] first_chunk = (i_beats > CHUNK_MAX) ? CHUNK_MAX : i_beats;
    wire [3:0] next_chunk  = (queued  > CHUNK_MAX) ? CHUNK_MAX : queued;
   // a beat is live on the bus exactly while the ledger shows work booked out
   wire outstanding = (n_iss != n_ret);

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            done_cnt   <= 4'd0;
            total      <= 4'd0;
            duty       <= 4'd0;
            queued     <= 4'd0;
           chunk_pend <= 4'd0;
           n_iss      <= 4'd0;
           n_ret      <= 4'd0;
            busy       <= 1'b0;
        end else if (i_start && !busy && (i_beats != 4'd0)) begin
            // accept a new burst
            beats_left <= first_chunk;
           n_iss      <= n_iss + first_chunk;
            queued     <= i_beats - first_chunk;
            total      <= i_beats;
            done_cnt   <= 4'd0;
            duty       <= i_duty;
            busy       <= 1'b1;
        end else if (i_ce) begin
            // retire one beat
            if (beats_left > 4'd1) begin
                beats_left <= beats_left - 4'd1;
            end else if (beats_left == 4'd1) begin
               // current chunk drained: stage the next chunk, the fabric
               // needs a cycle of turnaround before it can be issued
               beats_left <= 4'd0;
               chunk_pend <= next_chunk;
                queued     <= queued - next_chunk;
           end else if (chunk_pend != 4'd0) begin
               // staged chunk lands in the beat counter
               beats_left <= chunk_pend;
               chunk_pend <= 4'd0;
           end
           // ledger bookkeeping: one beat is consumed per enabled cycle, and a
           // staged chunk is booked out to the fabric when it lands
           if (beats_left != 4'd0)
               n_ret <= n_ret + 4'd1;
           else if (chunk_pend != 4'd0)
               n_iss <= n_iss + chunk_pend;
           if ((beats_left <= 4'd1) && (queued == 4'd0) && (chunk_pend == 4'd0))
                busy <= 1'b0;
           if (busy && outstanding)
                done_cnt <= done_cnt + 4'd1;
        end
    end

    assign o_busy = busy;
   assign o_beat = busy && i_ce && outstanding;
    assign o_pwm  = busy && (done_cnt < duty);

    // ---- P: whenever the engine is not busy, the whole burst has been pushed ----
    always @(posedge i_clk)
        if (!busy)
            assert (done_cnt == total);

endmodule

module histogram_sampler (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // sample-enable; low => whole histogram idles
    input  wire [1:0] i_sel,     // which bin the incoming sample lands in
    output reg  [3:0] bin0,
    output reg  [3:0] bin1,
    output reg  [3:0] bin2,
    output reg  [3:0] bin3,
    output reg  [3:0] total,
output wire       o_full,
output reg  [3:0] ce_ticks,
output reg  [3:0] n_in,
output reg  [3:0] n_out
);
    // sampling window closes after MAXS samples have been binned
    localparam [3:0] MAXS = 4'd12;

   // run-length coalescing: consecutive samples aimed at one bin are counted
   // here and folded into that bin register with a single add
   localparam [1:0] PMAX = 2'd3;

   reg [1:0] pend;      // samples staged but not yet folded into a bin
   reg [1:0] pend_sel;  // bin the staged samples belong to

    initial bin0  = 4'd0;
    initial bin1  = 4'd0;
    initial bin2  = 4'd0;
    initial bin3  = 4'd0;
    initial total = 4'd0;
   initial pend     = 2'd0;
   initial pend_sel = 2'd0;
initial ce_ticks = 4'd0;
initial n_in  = 4'd0;
initial n_out = 4'd0;

    assign o_full = (total == MAXS);

    wire take = i_ce && (total < MAXS);
   wire same  = (i_sel == pend_sel);
   // window already shut: commit whatever is still staged on the next beat
   wire drain = i_ce && !take;
   wire fold  = (pend != 2'd0) && (drain || (take && (!same || pend == PMAX)));
// in/out sample ledger: samples presented minus samples retired is the
// number still sitting in the staging accumulator
wire [3:0] staged   = n_in - n_out;
// one add commits the whole staged run, plus the in-flight sample when it
// coalesces into the same bin
wire [3:0] fold_amt = staged + ((take && same) ? 4'd1 : 4'd0);
// samples leaving staging this beat: those folded into a bin, plus the
// sample dropped on the floor once the window has shut
wire [3:0] retire   = (fold ? fold_amt : 4'd0) + (drain ? 4'd1 : 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 4'd0;
           pend     <= 2'd0;
           pend_sel <= 2'd0;
ce_ticks <= 4'd0;
n_in     <= 4'd0;
n_out    <= 4'd0;
       end else begin
           if (fold) begin
               case (pend_sel)
2'd0: bin0 <= bin0 + fold_amt;
2'd1: bin1 <= bin1 + fold_amt;
2'd2: bin2 <= bin2 + fold_amt;
2'd3: bin3 <= bin3 + fold_amt;
               endcase
           end
           if (take) begin
               pend_sel <= i_sel;
               pend     <= same ? ((pend == PMAX) ? 2'd0 : pend + 2'd1)
                                : 2'd1;
               total    <= total + 4'd1;
           end else if (drain) begin
               pend <= 2'd0;
           end
if (i_ce && ce_ticks != 4'd15)
    ce_ticks <= ce_ticks + 4'd1;
// ledger is pure accounting: it wraps, it is never held off
n_in  <= n_in  + (i_ce ? 4'd1 : 4'd0);
n_out <= n_out + retire;
       end
    end

    // P: no single bin's occupancy can ever exceed the sampling-window size,
    // even though the 4-bit bin register could physically hold 15.
    always @(*)
        assert (bin1 <= MAXS);
endmodule

// Multi-zone thermostat front end with hysteresis and a power budget.
// The active-zone mask is a parity protected register slice; a maintained
// occupancy counter and a remaining-budget counter track it.
module zone_heat_budget (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire [2:0] i_zone,    // zone under consideration this cycle
    input  wire [7:0] i_temp,    // measured temperature of that zone
    output wire       o_fault,   // parity mismatch on the zone slice
    output wire [3:0] o_nact,
output wire [3:0] o_budget,
output reg  [3:0] o_hot_cnt
);
    parameter [7:0] T_LOW  = 8'd40;   // below this, zone asks for heat
    parameter [7:0] T_HIGH = 8'd60;   // above this, zone releases heat
    localparam [3:0] BUDGET = 4'd4;   // at most 4 heaters may run at once
   localparam [3:0] BASE   = BUDGET - 4'd1; // slots in the shared base pool
   localparam [7:0] T_CRIT = 8'd20;  // below this a zone may claim the boost slot

    // ---- parity protected register slice -------------------------------
    reg [7:0] zone;    // one bit per zone heater
    reg       zpar;    // parity bit covering zone
    initial   zone = 8'h00;
    initial   zpar = 1'b0;

    // ---- bookkeeping registers -----------------------------------------
    reg [3:0] nact;    // number of heaters currently on
    reg [3:0] budget;  // remaining power slots
    initial   nact   = 4'd0;
   initial   budget = BASE;

   // The fourth slot is a boost slot: it is handed out only to a deeply
   // cold zone when the base pool is dry, and is tracked back to the zone
   // holding it so it can be returned when that heater goes off again.
   reg       b_used;  // boost slot is committed to a zone
   reg [2:0] b_zone;  // zone holding the boost slot
   initial   b_used = 1'b0;
   initial   b_zone = 3'd0;

   // ---- issue / commit pipeline ---------------------------------------
   // A grant decided this cycle reaches the heater mask on the next cycle;
   // the in-flight grant is held here.  One grant may be in flight.
   reg       p_val;   // a grant is in flight
   reg       p_on;    // 1 = turn the zone on, 0 = turn it off
   reg [2:0] p_zone;  // zone the in-flight grant targets
   initial   p_val  = 1'b0;
   initial   p_on   = 1'b0;
   initial   p_zone = 3'd0;
initial   o_hot_cnt = 4'd0;

    wire fault = (zpar != (^zone));
    assign o_fault  = fault;
    assign o_nact   = nact;
   assign o_budget = budget + {3'b000, ~b_used};

    // hysteresis: nothing happens inside the dead band, so no chattering
    wire req_on  = i_ce && !fault && (i_temp <  T_LOW);
    wire req_off = i_ce && !fault && (i_temp >  T_HIGH);

   // forward the in-flight grant, so a zone is never granted twice while
   // its mask bit has not been updated yet
   wire zbit = (p_val && (p_zone == i_zone)) ? p_on : zone[i_zone];

  // a zone deep in the cold may use the boost slot once the base pool is dry
  wire deep_cold = (i_temp < T_CRIT);
  wire slot_free = (budget != 4'd0) || (!b_used && deep_cold);

  wire do_on  = req_on  && !zbit && slot_free;
   wire do_off = req_off &&  zbit;

   // a power slot is reserved when the grant is issued and released only
   // when the heater has actually been switched off, one cycle later
  wire take_base  = do_on && (budget != 4'd0);
  wire take_boost = do_on && (budget == 4'd0);
  wire rel_boost  = p_val && !p_on && b_used && (p_zone == b_zone);
  wire rel_base   = p_val && !p_on && !rel_boost;

    always @(posedge i_clk) begin
        if (i_rst) begin
            zone   <= 8'h00;
            zpar   <= 1'b0;
            nact   <= 4'd0;
           budget <= BASE;
           b_used <= 1'b0;
           b_zone <= 3'd0;
           p_val  <= 1'b0;
           p_on   <= 1'b0;
           p_zone <= 3'd0;
o_hot_cnt <= 4'd0;
       end else if (i_ce) begin
           // commit stage: apply the grant issued last cycle
           if (p_val) begin
               zone[p_zone] <= p_on;
               zpar         <= ~zpar;  // one data bit flips, parity flips
               nact         <= p_on ? nact + 4'd1 : nact - 4'd1;
           end
           // issue stage: latch this cycle's decision
           p_val  <= do_on || do_off;
           p_on   <= do_on;
           p_zone <= i_zone;
          budget <= budget - {3'b000, take_base} + {3'b000, rel_base};
          b_used <= (b_used && !rel_boost) || take_boost;
          if (take_boost)
              b_zone <= i_zone;
o_hot_cnt <= ((i_temp > T_HIGH) && (o_hot_cnt != 4'd15)) ? o_hot_cnt + 4'd1 : o_hot_cnt;
       end
    end

    wire heating = (zone != 8'h00);

    // P: whenever any heater is running, occupancy never exceeds the
    //    power budget of 4 (the counter is 4 bits wide).
    always @(posedge i_clk)
        if (heating)
            assert (nact <= 4'd4);
endmodule

module credit_pool (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // step enable: low leaves all state unchanged
    input  wire i_take,    // 1 = take a credit, 0 = give one back
    output wire o_full,
    output wire o_empty,
    output wire [3:0] o_used,
    output wire [3:0] o_avail
);
    localparam [3:0] CAP = 4'd12;

    // up counter: credits handed out
    reg [3:0] used;
    // down counter: credits still on the shelf
    reg [3:0] avail;
   // per-lane outstanding credits: two clients share the one shelf
   reg [3:0] out_a;
   reg [3:0] out_b;
  // lane A parks its first two credits in a private reserve slot so the
  // common case never touches the lane counter
  reg [1:0] rsv_a;
   // round-robin pointer: whose request is charged next
   reg       turn;
   // registered arbiter grant: the shelf port moves one credit per cycle
   reg       gnt_a;
   reg       gnt_b;
   reg       gnt_take;
   // shelf-port move pipeline: a granted credit needs four more cycles on the
   // shared port before the lane counters and the shelf see it
   reg       p1_a;
   reg       p1_b;
   reg       p1_take;
   reg       p2_a;
   reg       p2_b;
   reg       p2_take;
   reg       p3_a;
   reg       p3_b;
   reg       p3_take;
   reg       p4_a;
   reg       p4_b;
   reg       p4_take;

    initial used  = 4'd0;
    initial avail = CAP;
   initial out_a = 4'd0;
   initial out_b = 4'd0;
  initial rsv_a = 2'd0;
   initial turn  = 1'b0;
   initial gnt_a = 1'b0;
   initial gnt_b = 1'b0;
   initial gnt_take = 1'b0;
   initial p1_a = 1'b0;
   initial p1_b = 1'b0;
   initial p1_take = 1'b0;
   initial p2_a = 1'b0;
   initial p2_b = 1'b0;
   initial p2_take = 1'b0;
   initial p3_a = 1'b0;
   initial p3_b = 1'b0;
   initial p3_take = 1'b0;
   initial p4_a = 1'b0;
   initial p4_b = 1'b0;
   initial p4_take = 1'b0;

  wire       lane_nz  = turn ? (out_b != 4'd0) : (out_a != 4'd0 || rsv_a != 2'd0);
   wire       arb_idle = !gnt_a && !gnt_b && !p1_a && !p1_b &&
                         !p2_a && !p2_b && !p3_a && !p3_b && !p4_a && !p4_b;

   // a request is only latched while the shared shelf port is free
   wire accept = i_ce && arb_idle &&
                (i_take ? (used != CAP) : lane_nz);

   // commit of the move that has finished walking the shelf port
   wire take_fire = (p4_a || p4_b) &&  p4_take;
   wire give_fire = (p4_a || p4_b) && !p4_take;

  // lane A fills the reserve before its counter and drains it first
   wire       a_fill  = p4_a &&  p4_take && (rsv_a != 2'd2);
   wire       a_drain = p4_a && !p4_take && (rsv_a != 2'd0);
  wire [1:0] rsv_a_nxt = a_fill  ? rsv_a + 2'd1 :
                         a_drain ? rsv_a - 2'd1 : rsv_a;
   wire [3:0] out_a_nxt = (p4_a &&  p4_take && !a_fill)  ? out_a + 4'd1 :
                          (p4_a && !p4_take && !a_drain) ? out_a - 4'd1 : out_a;
   wire [3:0] out_b_nxt = p4_b ? (p4_take ? out_b + 4'd1 : out_b - 4'd1) : out_b;

    always @(posedge clk) begin
        if (rst) begin
            used  <= 4'd0;
            avail <= CAP;
           out_a <= 4'd0;
           out_b <= 4'd0;
          rsv_a <= 2'd0;
           turn  <= 1'b0;
           gnt_a <= 1'b0;
           gnt_b <= 1'b0;
           gnt_take <= 1'b0;
           p1_a <= 1'b0;
           p1_b <= 1'b0;
           p1_take <= 1'b0;
           p2_a <= 1'b0;
           p2_b <= 1'b0;
           p2_take <= 1'b0;
           p3_a <= 1'b0;
           p3_b <= 1'b0;
           p3_take <= 1'b0;
           p4_a <= 1'b0;
           p4_b <= 1'b0;
           p4_take <= 1'b0;
       end else if (i_ce) begin
           // stage 1: arbitrate this cycle's request
           gnt_a    <= accept && !turn;
           gnt_b    <= accept &&  turn;
           gnt_take <= i_take;
           if (accept)
               turn <= ~turn;
           // stages 2-5: the credit walks the shared shelf port
           p1_a    <= gnt_a;
           p1_b    <= gnt_b;
           p1_take <= gnt_take;
           p2_a    <= p1_a;
           p2_b    <= p1_b;
           p2_take <= p1_take;
           p3_a    <= p2_a;
           p3_b    <= p2_b;
           p3_take <= p2_take;
           p4_a    <= p3_a;
           p4_b    <= p3_b;
           p4_take <= p3_take;

           // stage 6: retire the move as it leaves the port
           out_a <= out_a_nxt;
           out_b <= out_b_nxt;
          rsv_a <= rsv_a_nxt;
          used  <= out_a_nxt + rsv_a_nxt + out_b_nxt;   // running total over both lanes
           if (take_fire)
               avail <= avail - 4'd1;        // stepped down, single shelf port
           else if (give_fire)
               avail <= avail + 4'd1;
       end
    end

    assign o_full  = (avail == 4'd0);
    assign o_empty = (used  == 4'd0);
    assign o_used  = used;
    assign o_avail = avail;

    // P: whenever the shelf is empty, every credit of the pool is out on loan
    always @(posedge clk)
        if (avail == 4'd0)
            assert (used == CAP);
endmodule

module skid_parity_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // stage enable: low => full idle
    input  wire       i_valid,
    input  wire [7:0] i_data,
    input  wire       i_dready,    // downstream ready
    input  wire       i_close,     // closes the observation window
    output wire       o_ready,
    output reg        o_valid,
output reg  [7:0] o_data,
output reg  [3:0] o_beat_count
);

    // ---- skid buffer stage state ----
    reg        stall;      // skid slot occupied
    reg  [3:0] skid;       // low nibble of the buffered word
    reg  [3:0] skid_hi;    // upper nibble; flops enabled only for wide words
    reg        skid_wide;  // buffered word has a nonzero upper nibble
    reg        skid_par;   // shadow parity of the buffered word

    reg        o_par;      // shadow parity of the presented word

    // ---- observation window (opened by a skid release, closed by i_close) ----
    reg        win;
    reg  [7:0] acc_data;    // xor of words released inside the window
    reg        acc_par;     // xor of their shadow parities

   // ---- pending tracker: window accumulator xor the word still in the skid slot ----
   reg  [7:0] pend_data;
   reg        pend_par;

    initial begin
        stall    = 1'b0;
        skid      = 4'h0;
        skid_hi   = 4'h0;
        skid_wide = 1'b0;
        skid_par = 1'b0;
        o_valid  = 1'b0;
        o_data   = 8'h00;
        o_par    = 1'b0;
        win      = 1'b0;
        acc_data = 8'h00;
        acc_par  = 1'b0;
       pend_data = 8'h00;
       pend_par  = 1'b0;
o_beat_count = 4'd0;
    end

    assign o_ready = !stall;

    // reassembled buffered word: narrow words carry an implicit zero nibble
    wire [7:0] skid_word = {(skid_wide ? skid_hi : 4'h0), skid};

    wire do_release = i_ce &&  stall &&  i_dready;
    wire do_direct  = i_ce && !stall &&  i_valid && (i_dready || !o_valid);
    wire do_capture = i_ce && !stall &&  i_valid && o_valid && !i_dready;
    wire do_drop    = i_ce && !stall && !i_valid && i_dready && o_valid;

    always @(posedge clk) begin
        if (rst) begin
            stall    <= 1'b0;
            skid      <= 4'h0;
            skid_hi   <= 4'h0;
            skid_wide <= 1'b0;
            skid_par <= 1'b0;
            o_valid  <= 1'b0;
            o_data   <= 8'h00;
            o_par    <= 1'b0;
            win      <= 1'b0;
            acc_data <= 8'h00;
            acc_par  <= 1'b0;
           pend_data <= 8'h00;
           pend_par  <= 1'b0;
o_beat_count <= 4'd0;
        end else begin
            // datapath
            if (do_release) begin
                o_valid <= 1'b1;
                o_data  <= skid_word;
                o_par   <= skid_par;
                stall   <= 1'b0;
            end else if (do_direct) begin
                o_valid <= 1'b1;
                o_data  <= i_data;
                o_par   <= ^i_data;
            end else if (do_capture) begin
                stall    <= 1'b1;
                skid      <= i_data[3:0];
                if (i_data[7:4] != 4'h0) begin
                    skid_hi   <= i_data[7:4];
                    skid_wide <= 1'b1;
                end else begin
                    skid_wide <= 1'b0;
                end
                skid_par <= ^i_data;
            end else if (do_drop) begin
                o_valid <= 1'b0;
            end

            // window: opened by a release, closed by i_close
            if (i_ce) begin
                if (i_close)         win <= 1'b0;
                else if (do_release) win <= 1'b1;
            end

            // in-window accumulation of released words
            if (do_release) begin
                if (win) begin
                    acc_data <= acc_data ^ skid_word;
                    acc_par  <= acc_par  ^ skid_par;
                end else begin
                    acc_data <= skid_word;
                    acc_par  <= skid_par;
                end
            end

           // pending tracker: a capture folds straight in, and a window close
           // re-primes it with whatever word is still sitting in the skid slot
           if (i_ce && i_close) begin
               if (do_capture) begin
                   pend_data <= i_data;
                   pend_par  <= ^i_data;
               end else if (stall && !do_release) begin
                   pend_data <= skid_word;
                   pend_par  <= skid_par;
               end else begin
                   pend_data <= 8'h00;
                   pend_par  <= 1'b0;
               end
           end else if (do_capture) begin
               pend_data <= pend_data ^ i_data;
               pend_par  <= pend_par  ^ (^i_data);
           end
if (i_ce) begin
   if (i_close && win)
       o_beat_count <= {3'd0, pend_par};   // close restarts the count, flagging leftover residue
   else
       o_beat_count <= o_beat_count + 4'd1;
end
        end
    end

    // ---- property: inside the window, both shadow parities track their words ----
    always @(posedge clk) begin
        if (win) begin
            assert (o_par   == (^o_data));
            assert (acc_par == (^acc_data));
        end
    end

   // ---- property: inside the window, the residue still owed to the accumulator
   //      (pending tracker xor accumulator) carries a correct shadow parity ----
   always @(posedge clk) begin
       if (win) begin
           assert ((pend_par ^ acc_par) == (^(pend_data ^ acc_data)));
       end
   end

endmodule

module pwm_precedence (
    input  wire       clk,
    input  wire       ce,
    input  wire       load,
    input  wire [3:0] duty_in,
    output wire       o_pwm,
    output wire       o_period_start
);
    // 12-cycle PWM period: counter runs 0..11 and reloads.
    localparam [3:0] PERIOD_M1 = 4'd11;

    reg [3:0] cnt;       // period counter
    reg [3:0] duty_act;  // active duty, latched at period start
    reg [3:0] duty_pend; // pending (requested) duty
    reg [3:0] hi_left;   // shadow: high-cycle budget recorded at last period start
    reg [3:0] duty_stg;  // prefetched duty feeding the compare path
   reg [3:0] req_val;   // duty value captured from the request bus
   reg       req_vld;   // captured request still waiting to be committed
  reg [3:0] n_stage;   // running count of duty_pend -> duty_stg stage loads
  reg [3:0] n_commit;  // running count of duty_stg -> duty_act reloads

    initial cnt       = 4'd0;
    initial duty_act  = 4'd0;
    initial duty_pend = 4'd0;
    initial hi_left   = 4'd0;
    initial duty_stg  = 4'd0;
   initial req_val   = 4'd0;
   initial req_vld   = 1'b0;
  initial n_stage   = 4'd0;
  initial n_commit  = 4'd0;

    wire wrap = (cnt == PERIOD_M1);
    wire prefetch = (cnt == PERIOD_M1 - 4'd1);
   wire prefetch2 = (cnt == PERIOD_M1 - 4'd2);
   // a captured request only reaches duty_pend one cycle after it is
   // accepted, so the accept window has to close three cycles before the
   // boundary for the duty pipeline to be stable across the reload
   wire duty_hold = prefetch2 || prefetch || wrap;

    // seeded construct: output high exactly while the counter is below the duty
    assign o_pwm          = (cnt < duty_act);
    assign o_period_start = (cnt == 4'd0);

    always @(posedge clk) begin
        if (ce) begin
            // prefetch one cycle ahead of the boundary so the cnt<duty
            // compare gets a full cycle of setup on the new duty value
           if (prefetch) begin
               duty_stg <= duty_pend;
               n_stage  <= n_stage + 4'd1;
           end
            if (wrap) begin
                // new period: both the active duty and the high budget are
                // (re)loaded from the pending duty requested earlier
                cnt      <= 4'd0;
               // the staged value is consumed exactly once: the reload only
               // fires when the ledger still shows an un-consumed stage load,
               // otherwise duty_stg already sits in duty_act
               if (n_stage != n_commit) begin
                   duty_act <= duty_stg;
                   n_commit <= n_commit + 4'd1;
               end
                hi_left  <= duty_pend;
            end else begin
                cnt <= cnt + 4'd1;
                if (hi_left != 4'd0)
                    hi_left <= hi_left - 4'd1;
            end
           // request bus is registered: capture on the accepted cycle and
           // commit into the pending duty on the following cycle
           if (load && !duty_hold) begin
               req_val <= duty_in;
               req_vld <= 1'b1;
           end else begin
               req_vld <= 1'b0;
           end
           if (req_vld)
               duty_pend <= req_val;
        end
    end

    // past-valid register so cycle zero is not judged
    reg pv = 0;
    always @(posedge clk)
        pv <= 1'b1;

    // Precedence: if the output was driven high last cycle, then a nonzero
    // high-cycle budget (recorded at the earlier period start) must still have
    // been available at that time.
    always @(posedge clk)
        if (pv && $past(o_pwm))
            assert ($past(hi_left) != 4'd0);
endmodule

module dma_burst_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // engine clock-enable / idle when low
    input  wire       i_start,   // Q: opens the transfer window
    input  wire [3:0] i_len,     // burst length in beats
    input  wire       i_ack,     // R: closes the transfer window
    output wire       o_busy,
output wire       o_drained,
output reg  [3:0] o_ack_cnt
);

    // beats-remaining counter and the two status flags derived from it
    reg [3:0] beats_left;
    reg       busy;
    reg       drained;

    // window register: set by a new burst (Q), cleared by the ack (R)
    reg       win;

    // commit-stage register: the next beat count is held here for one cycle
    // before it is written into the beats-remaining counter
    reg [3:0] stg_beats;
    reg       stg_vld;

   // unpipelined shadow of the beats-remaining count: the issue stage keeps
   // its own copy so downstream flow control does not have to wait a cycle
   // for the commit stage to update beats_left
   reg [3:0] shadow;

   // ack pulse counter (status only, unrelated to the burst window)
   reg       ack_seen;

    // forwarded count: the in-flight value whenever a commit is pending
    wire [3:0] beats_cur = stg_vld ? stg_beats : beats_left;


    initial beats_left = 4'd0;
    initial busy       = 1'b0;
    initial drained    = 1'b1;
    initial win        = 1'b0;
    initial stg_beats  = 4'd0;
    initial stg_vld    = 1'b0;
   initial shadow     = 4'd0;
   initial ack_seen   = 1'b0;
   initial o_ack_cnt  = 4'd0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            busy       <= 1'b0;
            drained    <= 1'b1;
            win        <= 1'b0;
            stg_beats  <= 4'd0;
            stg_vld    <= 1'b0;
           shadow     <= 4'd0;
           ack_seen   <= 1'b0;
           o_ack_cnt  <= 4'd0;
        end else if (i_ce) begin
            // commit stage: the registered count reaches the counter
            if (stg_vld) begin
                beats_left <= stg_beats;
                stg_vld    <= 1'b0;
            end
            // issue stage: a descriptor load or a beat retire posts the new
            // status flags now and hands the count to the commit stage
            if (i_start && !busy) begin
                // load a new burst descriptor and open the window
                stg_beats  <= i_len;
                stg_vld    <= 1'b1;
               shadow     <= i_len;
                busy       <= (i_len != 4'd0);
                drained    <= (i_len == 4'd0);
                win        <= 1'b1;
            end else if (busy) begin
                // retire one beat off the forwarded count
                stg_beats  <= beats_cur - 4'd1;
                stg_vld    <= 1'b1;
               shadow     <= beats_cur - 4'd1;
                busy       <= (beats_cur != 4'd1);
                drained    <= (beats_cur <= 4'd1);
                if (i_ack)
                    win <= 1'b0;
            end else if (i_ack) begin
                // close the window between transfers
                win <= 1'b0;
            end
          // count the acks that close a fully retired burst
           ack_seen <= i_ack;
          if (i_ack && !ack_seen && shadow == 4'd0)
               o_ack_cnt <= o_ack_cnt + 4'd1;
        end
    end

    assign o_busy    = busy;
    assign o_drained = drained;

    // P: inside an open transfer window the engine is never simultaneously
    // reporting "busy" and "drained".
    always @(posedge i_clk)
        if (win)
            assert (!(busy && drained));

   // Q: the engine reports "drained" only once the issue-stage shadow has
   // counted the burst all the way down to zero beats.
   always @(posedge i_clk)
       assert (!drained || (shadow == 4'd0));

endmodule

module credit_ledger (
    input  wire        clk,
    input  wire        i_ce,
    output wire [4:0]  o_gray,
    output wire        o_drained
);
// up counter and the credit pool stepped by the same enable; the pool is
// split into a reserve tranche and a main balance, and up + pool == 20
    reg [4:0] up;
    reg [4:0] dn;
// reserve tranche of the batch: returning credits are charged here first
reg [3:0] resv;

   // the main-balance subtractor is registered: a debit against dn is
   // computed on one enabled cycle and committed on the next
   reg       dn_v;
   reg [4:0] dn_s;

    // shadow register: records that the up counter has already reached 10
    reg       mark;

    // "before R" scope: starts high, cleared the first time the ledger drains
    reg       before_done;
    // ledger counters: one tick per credit handed out, one per credit back
    reg [4:0] n_iss;
    reg [4:0] n_ret;

    initial up          = 5'd0;
initial dn          = 5'd12;
initial resv        = 4'd8;
    initial mark        = 1'b0;
    initial before_done = 1'b1;
    initial n_iss       = 5'd0;
    initial n_ret       = 5'd0;
   initial dn_v        = 1'b0;
   initial dn_s        = 5'd11;

    always @(posedge clk) begin
        if (i_ce) begin
if (dn_v) begin
               // commit the registered debit against the main balance
               dn   <= dn_s;
               dn_v <= 1'b0;
           end else if (dn == 5'd0) begin
                before_done <= 1'b0;   // the drained event has been observed
                up          <= 5'd0;   // recharge with a fresh batch of 20
dn          <= 5'd12;
resv        <= 4'd8;   // fresh batch: reserve tranche refilled
                mark        <= 1'b0;   // new batch: halfway not passed yet
            end else if (n_iss == n_ret) begin
                // nothing outstanding: hand a credit to the consumer
                up    <= up + 5'd1;
                mark  <= mark | (up == 5'd9);
                n_iss <= n_iss + 5'd1;
            end else begin
// the outstanding credit returns: charge the reserve tranche first and
// only fall back on the main balance once the tranche is dry
if (resv != 4'd0) begin
                   resv <= resv - 4'd1;
               end else begin
                   // stage the debit; it lands on dn next enabled cycle
                   dn_s <= dn - 5'd1;
                   dn_v <= 1'b1;
               end
                n_ret <= n_ret + 5'd1;
            end
        end
    end

    // gray view of the issue pointer (clock-domain-crossing flavour)
    assign o_gray    = n_iss ^ (n_iss >> 1);
assign o_drained = (dn == 5'd0) && (resv == 4'd0) && (n_iss == n_ret);

    // Property: before the ledger has ever drained, seeing fewer than ten
    // credits left means the up counter must already have passed ten.
    always @(*)
        if (before_done && (dn <= 5'd9))
            assert (mark);
endmodule

module alu_result_fifo (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] a,
    input  wire [7:0] b,
    input  wire [1:0] op,
    output reg  [7:0] o_data,
    output reg        o_zero,
    output reg        o_carry,
    output wire       full,
    output wire       empty,
output reg  [3:0] count,
output reg  [7:0] o_push_tally,
output reg  [3:0] o_op_shadow
);
    // ---- FIFO state: separate write/read pointers plus occupancy counter ----
    reg [2:0] wptr, rptr;
    reg [8:0] mem [0:7];   // {carry, result} slices
   // one-deep input staging register: the ALU result is captured here and
   // written into the array on the following enabled cycle
   reg        stg_v;
   reg  [8:0] stg_d;
    integer i;

    initial begin
        wptr    = 3'd0;
        rptr    = 3'd0;
        count   = 4'd0;
        o_data  = 8'h00;
        o_zero  = 1'b1;
        o_carry = 1'b0;
       stg_v   = 1'b0;
       stg_d   = 9'd0;
o_push_tally = 8'h00;
o_op_shadow = 4'd0;
        for (i = 0; i < 8; i = i + 1) mem[i] = 9'd0;
    end

    // ---- 8-bit ALU slice: add, subtract, and, or (carry out in bit 8) ----
    wire [8:0] w_sum = {1'b0, a} + {1'b0, b};
    wire [8:0] w_dif = {1'b0, a} - {1'b0, b};
    reg  [8:0] alu;
    always @(*) begin
        case (op)
            2'b00:   alu = w_sum;
            2'b01:   alu = w_dif;
            2'b10:   alu = {1'b0, a & b};
            default: alu = {1'b0, a | b};
        endcase
    end

    // ---- full/empty derived from the POINTERS, not from the counter ----
   wire [3:0] w_occ = {1'b0, (wptr - rptr)} + {3'b0, stg_v};
   assign full  = (w_occ == 4'd5);
    assign empty = (wptr == rptr);

    wire do_push = i_ce && push && !full;
    wire do_pop  = i_ce && pop  && !empty;
   // the staging slot retires into the array whenever the array has room
   wire do_drain = i_ce && stg_v && ((wptr - rptr) != 3'd5);

    always @(posedge clk) begin
       if (do_drain) begin
           mem[wptr] <= stg_d;
           wptr      <= wptr + 3'd1;
       end
       if (do_push) begin
           stg_d <= alu;
           stg_v <= 1'b1;
       end else if (do_drain) begin
           stg_v <= 1'b0;
       end
        if (do_pop) begin
            o_data  <= mem[rptr][7:0];
            o_carry <= mem[rptr][8];
            o_zero  <= (mem[rptr][7:0] == 8'h00);
            rptr    <= rptr + 3'd1;
        end
        if (do_push && !do_pop)
            count <= count + 4'd1;
        else if (!do_push && do_pop)
            count <= count - 4'd1;
        else
            count <= count;
if (do_push)
    o_push_tally <= o_push_tally + 8'd1;
else if (do_pop)
    o_push_tally <= {o_push_tally[6:0], o_push_tally[7]};
if (i_ce)
    o_op_shadow <= {o_op_shadow[2:0], (^op) ^ a[0] ^ b[0]};
    end

    // P: occupancy never exceeds the depth of 5, though the register holds 15
    always @(*) assert (count <= 4'd5);
endmodule

module token_bucket_deadline (
    input  wire clk,
    input  wire i_ce,
    input  wire req,
    output wire grant,
    output wire expired
);
    // burst size of the bucket and the response deadline for one request
    localparam [2:0] BURST   = 3'd4;
    localparam [3:0] TIMEOUT = 4'd6;

    reg [2:0] tokens;    // token bucket, capped at BURST
    reg [1:0] tick_cnt;   // refill timer, counts down, tick at zero
    reg       pending;    // window register: set by accepted request, cleared by grant
    reg [3:0] deadline;   // bounded-response countdown for the pending request
    reg       refill_q;  // staged refill: a tick is captured here and applied to the bucket next cycle
    reg       pending_b;   // second request slot: holds a request that arrived while the head slot was busy
    reg [3:0] deadline_b;  // best-effort countdown for the queued slot
    reg       rr_b;        // arbitration pointer, 1 when the queued slot gets the next token
    reg [2:0] starve;      // consecutive cycles the head slot has waited on a dry bucket

    initial tokens   = BURST;
    initial tick_cnt = 2'd3;
    initial pending  = 1'b0;
    initial deadline = 4'd0;
    initial refill_q = 1'b0;
    initial pending_b  = 1'b0;
    initial deadline_b = 4'd0;
    initial rr_b       = 1'b0;
    initial starve     = 3'd0;

    wire tick     = (tick_cnt == 2'd0);
    wire b_ready    = pending_b && (tokens != 3'd0);
    // the queued slot only pre-empts on its own turn, and only while the
    // bucket still holds a spare token for the head slot
    wire do_grant_b = b_ready && (!pending || (rr_b && (tokens >= 3'd2)));
    wire do_grant = pending && (tokens != 3'd0) && !do_grant_b;
    wire do_refill = refill_q && (tokens < BURST);
    wire any_grant = do_grant || do_grant_b;
    // dry-bucket alarm: the head slot has spent a whole refill interval without a token
    wire dry_alarm = pending && (starve >= 3'd3);

    assign grant   = i_ce && any_grant;
    assign expired = (pending && (deadline == 4'd0)) || (pending_b && (deadline_b == 4'd0)) || dry_alarm;

    // refill timer
    always @(posedge clk) if (i_ce)
        tick_cnt <= tick ? 2'd3 : (tick_cnt - 2'd1);

    // refill request is registered one cycle before it reaches the bucket
    always @(posedge clk) if (i_ce)
        refill_q <= tick;

    // bucket: drains on a grant, refills on a tick, saturates at BURST
    always @(posedge clk) if (i_ce) begin
        if (any_grant && do_refill)
            tokens <= tokens;                 // one out, one in
        else if (any_grant)
            tokens <= tokens - 3'd1;
        else if (do_refill)
            tokens <= tokens + 3'd1;
    end

    // round-robin pointer: whichever slot was served hands the turn over
    always @(posedge clk) if (i_ce) begin
        if (do_grant_b)
            rr_b <= 1'b0;
        else if (do_grant)
            rr_b <= 1'b1;
    end

    // queued slot: captures the request that arrives while the head slot is busy,
    // counts down best effort and drops the request if it runs out
    always @(posedge clk) if (i_ce) begin
        if (do_grant_b)
            pending_b <= 1'b0;
        else if (pending_b) begin
            if (deadline_b == 4'd0)
                pending_b <= 1'b0;
            else
                deadline_b <= deadline_b - 4'd1;
        end else if (req && pending) begin
            pending_b  <= 1'b1;
            deadline_b <= TIMEOUT;
        end
    end

    // request window and its countdown
    always @(posedge clk) if (i_ce) begin
        if (do_grant)
            pending <= 1'b0;
        else if (pending)
            deadline <= deadline - 4'd1;
        else if (req) begin
            pending  <= 1'b1;
            deadline <= TIMEOUT;
        end
    end
    // starvation counter: how many enabled cycles the head request has spent
    // waiting on an empty bucket; cleared as soon as a token is in the bucket
    always @(posedge clk) if (i_ce) begin
        if (!pending || (tokens != 3'd0))
            starve <= 3'd0;
        else
            starve <= starve + 3'd1;
    end

    // P: inside the request window the countdown never expires
    always @(posedge clk)
        if (pending) assert (deadline != 4'd0);
    // P2: the dry-bucket counter cannot outlive the request window
    always @(posedge clk)
        if (pending) assert (starve <= 3'd5);
endmodule

// Kernel task handshake tracker.
// The progress accumulator is kept in two carry-save halves acc_a/acc_b whose
// sum is the true phase count (0=idle, 1=armed, 2=started, 3=finished).
// A tiny FSM (ph_ref) enforces the arm -> start -> finish chain, and sticky
// flags record that each earlier step was really observed.
module cs_chain_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       i_track,   // Q event: arms the observation scope, sticky
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_finish,
    output wire [3:0] o_total,
    output wire       o_done
);
    // carry-save halves of the progress accumulator
    reg [2:0] acc_a, acc_b;
    // redundant direct copy of the phase, used by the sequencer
    reg [2:0] ph_ref;
    // which half receives the next increment
    reg       tog;
    // chain witnesses
    reg       arm_seen, start_seen;
    // sticky scope register (set the first time i_track is seen)
    reg       armed;
   // stage-2 drain chain: reuses the same handshake strobes once stage 1 retired
   reg [2:0] ph_ref2;
   // sticky flag: the drain chain reached its final phase
   reg       b_done;
  // stage-3 writeback chain: reuses the same strobes after the drain retired
  reg [2:0] ph_ref3;
  // sticky flag: the writeback chain reached its final phase
  reg       c_done;

 // retire threshold: how many handshake steps a stage must complete before it
 // releases the shared increment port to the next stage. The host selects the
 // short (arm/start only) protocol by presenting i_finish with the track event.
 reg [2:0] lim;

    initial begin
        acc_a      = 3'd0;
        acc_b      = 3'd0;
        ph_ref     = 3'd0;
        tog        = 1'b0;
        arm_seen   = 1'b0;
        start_seen = 1'b0;
        armed      = 1'b0;
       ph_ref2    = 3'd0;
       b_done     = 1'b0;
      ph_ref3    = 3'd0;
      c_done     = 1'b0;
     lim        = 3'd3;
    end

    // true total recombined from the two halves
    wire [3:0] total = {1'b0, acc_a} + {1'b0, acc_b};
    assign o_total = total;
  assign o_done  = (total == 4'd3) || b_done || c_done;

    // one chain step at a time, in order
    wire adv = i_ce && (((ph_ref == 3'd0) && i_arm)    ||
                        ((ph_ref == 3'd1) && i_start)  ||
                        ((ph_ref == 3'd2) && i_finish));

   // the drain chain may only take the shared accumulator once stage 1 retired
  wire adv2 = i_ce && (ph_ref >= lim) && !adv &&
                       (((ph_ref2 == 3'd0) && i_arm)   ||
                        ((ph_ref2 == 3'd1) && i_start) ||
                        ((ph_ref2 == 3'd2) && i_finish));

  // the writeback chain only takes the shared accumulator once the drain retired
 wire adv3 = i_ce && (ph_ref2 >= lim) && !adv && !adv2 &&
                      (((ph_ref3 == 3'd0) && i_arm)   ||
                       ((ph_ref3 == 3'd1) && i_start) ||
                       ((ph_ref3 == 3'd2) && i_finish));

   // shared increment port into the carry-save halves
  wire inc = adv || adv2 || adv3;

    always @(posedge clk) begin
        if (rst) begin
            acc_a      <= 3'd0;
            acc_b      <= 3'd0;
            ph_ref     <= 3'd0;
            tog        <= 1'b0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            armed      <= 1'b0;
           ph_ref2    <= 3'd0;
           b_done     <= 1'b0;
          ph_ref3    <= 3'd0;
          c_done     <= 1'b0;
         lim        <= 3'd3;
        end else begin
            if (i_ce && i_track)
                armed <= 1'b1;

           // the retire threshold is only re-programmed between runs, while
           // stage 1 is still idle
           if (i_ce && i_track && (ph_ref == 3'd0))
               lim <= i_finish ? 3'd2 : 3'd3;

           if (inc) begin
               // split increment: the halves re-sum to both chain phases together
                if (tog) acc_b <= acc_b + 3'd1;
                else     acc_a <= acc_a + 3'd1;
               tog <= ~tog;
           end

           if (adv) begin
               ph_ref <= ph_ref + 3'd1;

                if (ph_ref == 3'd0) arm_seen   <= 1'b1;
                if (ph_ref == 3'd1) start_seen <= 1'b1;
            end

           if (adv2) begin
               ph_ref2 <= ph_ref2 + 3'd1;
               if (ph_ref2 == 3'd2) b_done <= 1'b1;
           end

          if (adv3) begin
              ph_ref3 <= ph_ref3 + 3'd1;
              if (ph_ref3 == 3'd2) c_done <= 1'b1;
          end
        end
    end

    // Chain precedence, in the sticky "after i_track" scope:
    // a finished accumulation can never be observed unless both the arm and
    // the start steps were witnessed first.
    always @(*)
        if (armed && (total == 4'd3))
            assert (start_seen && arm_seen);
endmodule

// DRC check engine: each accepted board-check job walks a saturating
// step counter up to MAXSTEP while a completion countdown runs down.
module drc_engine (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       start,     // new check job requested
    output reg        busy,      // request outstanding
    output reg [3:0]  progress,  // saturating up-counter, clamps at MAXSTEP
    output reg [3:0]  deadline,  // completion countdown
    output reg        armed,     // sticky: a job has been accepted at least once
output reg        done,
output reg [3:0]  step_tally,
output reg [3:0]  job_count
);
    localparam [3:0] MAXSTEP = 4'd10;
   localparam [3:0] PASS1   = 4'd6;   // steps budgeted to the first pass

   // second-pass budget, parked out of the live countdown until pass one ends
   reg [3:0] credit;

    initial begin
        busy     = 1'b0;
        progress = 4'd0;
        deadline = 4'd0;
        armed    = 1'b0;
        done     = 1'b0;
       credit   = 4'd0;
step_tally = 4'd0;
job_count = 4'd0;
    end

    wire accept   = i_ce && start && !busy;
    wire step     = i_ce && busy;
    wire last     = (progress + 4'd1 >= MAXSTEP);
   wire refill   = (deadline <= 4'd1) && (credit != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            busy     <= 1'b0;
            progress <= 4'd0;
            deadline <= 4'd0;
            armed    <= 1'b0;
            done     <= 1'b0;
           credit   <= 4'd0;
step_tally <= 4'd0;
job_count <= 4'd0;
        end else if (accept) begin
            busy     <= 1'b1;
            progress <= 4'd0;
           deadline <= PASS1;             // pass one runs on its own budget
           credit   <= MAXSTEP - PASS1;   // remainder held back for pass two
            armed    <= 1'b1;   // sticky once set, never cleared except by rst
            done     <= 1'b0;
job_count <= (job_count == 4'd15) ? 4'd15 : job_count + 4'd1;
        end else if (step) begin
            // saturating up-counter: clamps at MAXSTEP, never reaches 4'd15
            progress <= (progress == MAXSTEP) ? MAXSTEP : progress + 4'd1;
           if (refill) begin
               // pass one spent: hand the reserve to the live countdown
               deadline <= credit;
               credit   <= 4'd0;
           end else begin
               deadline <= (deadline == 4'd0) ? 4'd0 : deadline - 4'd1;
           end
            if (last) begin
                busy <= 1'b0;
                done <= 1'b1;
            end
step_tally <= (step_tally == 4'd15) ? 4'd15 : step_tally + 4'd1;
        end
    end

    // P: while the engine has ever been armed and a check is outstanding,
    // the completion countdown must not have expired.
    always @(*)
        if (armed && busy)
            assert (deadline != 4'd0);
endmodule

module wdog_saturate (
    input wire i_clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_kick,
    input wire i_ack,
    output wire o_reset,
    output wire [3:0] o_elapsed,
    output wire [3:0] o_remain
);
    // Watchdog window: TIMEOUT ticks without a kick latches a system reset.
    localparam [3:0] TIMEOUT = 4'd12;
   // The adaptive window never tightens below this floor.
   localparam [3:0] WIN_MIN = 4'd4;

    // Saturating up-counter of ticks since the last kick.  It clamps at
    // TIMEOUT (12) even though the 4-bit register admits values up to 15.
    reg [3:0] cnt;
    // Mirror: ticks of grace remaining, saturating down at zero.
    reg [3:0] rem;
    // Latched reset request, cleared only by an acknowledge.
    reg       latched;

   // Margin monitor: low-water mark of the grace window since the
   // watchdog was last armed.  Zero means the window has fully closed.
   reg [3:0] slack;

  // Adaptive grace window: how many ticks of grace each re-arm hands out.
  // o_elapsed/o_remain are always reported against the full 12-tick frame,
  // so a shortened window simply starts the elapsed count with a head
  // start instead of at zero.
  reg [3:0] win;

   // Update stage: the tick arithmetic is registered for one cycle before
   // it commits, so an update issued on a ce cycle lands on the cycle
   // after it was issued.
   reg [3:0] cnt_stg;
   reg [3:0] rem_stg;
   reg       stg_vld;
  // The stage also carries the window size the update installs, plus a
  // flag marking the entry as a re-arm rather than a plain tick.
  reg [3:0] win_stg;
  reg       ld_stg;

   // Forwarding: a pending stage value is newer than the committed
   // register, so back-to-back ticks are computed from the stage.
   wire [3:0] cnt_eff = stg_vld ? cnt_stg : cnt;
   wire [3:0] rem_eff = stg_vld ? rem_stg : rem;

  // A kick arriving after the window has already closed is ignored: the
  // reset request stands until software acknowledges it.
  wire kick_ok = i_kick && (slack != 4'd0);

 // Each acknowledged timeout tightens the deadline by one tick, each
 // healthy kick relaxes it back one tick toward the full frame.
 wire [3:0] win_up = (win < TIMEOUT) ? win + 4'd1 : win;
 wire [3:0] win_dn = (win > WIN_MIN) ? win - 4'd1 : win;

    initial cnt     = 4'd0;
    initial rem     = TIMEOUT;
    initial latched = 1'b0;
   initial cnt_stg = 4'd0;
   initial rem_stg = TIMEOUT;
   initial stg_vld = 1'b0;
  initial slack   = TIMEOUT;
 initial win     = TIMEOUT;
 initial win_stg = TIMEOUT;
 initial ld_stg  = 1'b0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            cnt     <= 4'd0;
            rem     <= TIMEOUT;
            latched <= 1'b0;
           cnt_stg <= 4'd0;
           rem_stg <= TIMEOUT;
           stg_vld <= 1'b0;
          slack   <= TIMEOUT;
         win     <= TIMEOUT;
         win_stg <= TIMEOUT;
         ld_stg  <= 1'b0;
       end else begin
           // Drain the stage: the in-flight update commits one cycle after
           // it was issued, whether or not a new tick arrives.
           if (stg_vld) begin
               cnt <= cnt_stg;
               rem <= rem_stg;
win <= win_stg;
// The monitor restarts on an explicit re-arm: a shortened window
// never reaches the full frame count, so the old compare against
// TIMEOUT would never fire again.
slack <= ld_stg ? win_stg :
         (rem_stg < slack) ? rem_stg : slack;
           end
           stg_vld <= 1'b0;

           if (i_ce) begin
           stg_vld <= 1'b1;
          if (kick_ok) begin
cnt_stg <= TIMEOUT - win_up;
rem_stg <= win_up;
win_stg <= win_up;
ld_stg  <= 1'b1;
           end else begin
               cnt_stg <= (cnt_eff < TIMEOUT) ? cnt_eff + 4'd1 : cnt_eff;
               rem_stg <= (rem_eff != 4'd0) ? rem_eff - 4'd1 : rem_eff;
win_stg <= win;
ld_stg  <= 1'b0;
           end

           if (i_ack) begin
               latched <= 1'b0;
               // The acknowledge also re-arms the window, issued through
               // the same stage so the commit stays single-sourced.
cnt_stg <= TIMEOUT - win_dn;
rem_stg <= win_dn;
win_stg <= win_dn;
ld_stg  <= 1'b1;
           end
          else if (!kick_ok && (rem_eff == 4'd1))
                latched <= 1'b1;
        end
       end
    end

    assign o_reset   = latched;
    assign o_elapsed = cnt;
    assign o_remain  = rem;

    // Universality, global scope: whenever the grace window has run out, the
    // elapsed-tick counter must be sitting on its saturation value.
    always @(posedge i_clk)
        if (rem == 4'd0)
            assert (cnt == TIMEOUT);

   // Margin report consistency: the ticks already burned plus the deepest
   // margin the monitor has recorded cannot exceed the whole window.
   always @(posedge i_clk)
       assert ((cnt + slack) <= 5'd12);
endmodule

module credit_rr_arbiter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire [3:0] req,       // four requesters
    input  wire       ret,       // consumer returns one credit
    output reg  [1:0] rr_ptr,    // rotating priority pointer
    output reg  [3:0] grant,     // one-hot grant
    output reg  [3:0] credits,   // credits held by the producer
    output reg  [3:0] outstanding // credits in flight at the consumer
);
    localparam [3:0] TOTAL = 4'd8;

   // credits parked against the burst currently in flight
   reg [1:0] escrow;

  // a return occupies the return path for one cycle before it lands
  reg       ret_q;
  reg [3:0] ret_amt;
 // lane B: a peer return lane that picks up the next return on the
 // cycle lane A drains, so returns can arrive back to back
 reg       ret_q2;
 reg [3:0] ret_amt2;

    initial rr_ptr      = 2'd0;
    initial grant       = 4'b0000;
    initial credits     = TOTAL;
    initial outstanding = 4'd0;
   initial escrow      = 2'd0;
  initial ret_q       = 1'b0;
  initial ret_amt     = 4'd0;
 initial ret_q2      = 1'b0;
 initial ret_amt2    = 4'd0;

    // rotating priority selection: first requester at or after rr_ptr
    wire [1:0] idx = req[rr_ptr]          ? rr_ptr          :
                     req[rr_ptr + 2'd1]   ? rr_ptr + 2'd1   :
                     req[rr_ptr + 2'd2]   ? rr_ptr + 2'd2   :
                                            rr_ptr + 2'd3;

   // at burst start one credit per other waiting requester is parked in
   // escrow, so a burst that has been admitted can always be drained
   wire [3:0] others = req & ~(4'b0001 << idx);
   wire [1:0] resv   = {1'b0, others[0]} + {1'b0, others[1]} +
                       {1'b0, others[2]} + {1'b0, others[3]};
   wire       burst_start = (outstanding == 4'd0);
   wire [3:0] need        = burst_start ? (4'd1 + {2'b00, resv}) : 4'd1;
   wire have_credit = (credits >= need);
    wire any_req     = |req;

    // a grant spends one credit; it becomes outstanding until returned
   // a return is captured one cycle and applied the next
  wire ret_start  = i_ce && ret && !ret_q &&
                    (outstanding > {3'd0, ret_q2});
  wire ret_start2 = i_ce && ret && ret_q && !ret_q2 &&
                    (outstanding > 4'd1);
  // the two lanes share one credit write port; lane A drains first
  wire ret_done   = i_ce && ret_q;
  wire ret_done2  = i_ce && ret_q2 && !ret_q;
   // the return path has priority; grants stall while it is busy
  wire do_grant   = i_ce && have_credit && any_req &&
                    !ret_q && !ret_q2 && !ret_start;

    always @(posedge clk) begin
        if (rst) begin
            rr_ptr      <= 2'd0;
            grant       <= 4'b0000;
            credits     <= TOTAL;
            outstanding <= 4'd0;
           escrow      <= 2'd0;
           ret_q       <= 1'b0;
           ret_amt     <= 4'd0;
          ret_q2      <= 1'b0;
          ret_amt2    <= 4'd0;
        end else if (i_ce) begin
            grant <= do_grant ? (4'b0001 << idx) : 4'b0000;
            if (do_grant)
                rr_ptr <= idx + 2'd1;

          // capture side: each lane latches the amount it will hand back
          if (ret_start) begin
              ret_q   <= 1'b1;
              ret_amt <= (outstanding == 4'd1 + {3'd0, ret_q2})
                           ? (4'd1 + {2'b00, escrow}) : 4'd1;
          end
          if (ret_start2) begin
              ret_q2   <= 1'b1;
              ret_amt2 <= (outstanding == 4'd2)
                           ? (4'd1 + {2'b00, escrow}) : 4'd1;
          end

           if (do_grant) begin
               if (burst_start) begin
                   credits <= credits - 4'd1 - {2'b00, resv};
                   escrow  <= resv;
               end else begin
                   credits <= credits - 4'd1;
               end
                outstanding <= outstanding + 4'd1;
           end else if (ret_done) begin
               credits <= credits + ret_amt;
               if (outstanding == 4'd1)
                   escrow <= 2'd0;
               outstanding <= outstanding - 4'd1;
               ret_q <= 1'b0;
          end else if (ret_done2) begin
              credits <= credits + ret_amt2;
              if (outstanding == 4'd1)
                  escrow <= 2'd0;
              outstanding <= outstanding - 4'd1;
              ret_q2 <= 1'b0;
           end
        end
    end

    // P: whenever nothing is in flight, the producer holds every credit
    always @(posedge clk)
        if (outstanding == 4'd0)
            assert (credits == TOTAL);
endmodule

module lex_onehot_esc (
    input wire       i_clk,
    input wire       i_reset,
    input wire       i_ce,
    input wire [7:0] i_char,
    output wire      o_in_string,
    output wire [3:0] o_esc_count
);
    // one-hot lexer state: exactly one bit set by construction
    localparam S_IDLE  = 0;
    localparam S_IDENT = 1;
    localparam S_NUM   = 2;
    localparam S_STR   = 3;
    localparam S_ESC   = 4;

    reg [4:0] st;
    reg [3:0] cnt;   // escape sequences counted in the current string literal
   reg [3:0] lim;   // escape budget for the current string literal (default 8)
   reg [3:0] pend;  // escape count parked between concatenated string segments
    reg       arm;   // sticky: set the first time a string literal is being scanned
    reg       pv;

    initial st  = 5'b00001;
    initial cnt = 4'd0;
   initial lim = 4'd8;
   initial pend = 4'd0;
    initial arm = 1'b0;
    initial pv  = 1'b0;

    wire is_q   = (i_char == 8'h22);
    wire is_bs  = (i_char == 8'h5C);
    wire is_dig = (i_char >= 8'h30) && (i_char <= 8'h39);
    wire is_alp = ((i_char | 8'h20) >= 8'h61) && ((i_char | 8'h20) <= 8'h7A);

   // a numeric prefix before a literal programs the escape budget, clamped to 8
   wire [3:0] dig_lim = (i_char[3:0] > 4'd8) ? 4'd8 : i_char[3:0];

    reg [4:0] nst;
    reg [3:0] ncnt;
   reg [3:0] nlim;
   reg [3:0] npend;

    always @(*) begin
        nst  = st;
        ncnt = cnt;
       nlim = lim;
       npend = pend;
        if (st[S_IDLE]) begin
            if (is_q) begin
               nst   = 5'b01000;  // open quote: resume a continued literal
               ncnt  = pend;      // adjacent segments share one escape count
               npend = 4'd0;
           end else if (is_dig) begin
               nst  = 5'b00100;
               nlim = dig_lim;    // leading digit programs the budget
              npend = 4'd0;      // a numeric prefix ends any concatenation
           end
           else if (is_alp) begin
               nst   = 5'b00010;
               npend = 4'd0;      // an identifier ends any concatenation
           end
            else
                nst = 5'b00001;
        end else if (st[S_IDENT]) begin
            nst = (is_alp || is_dig) ? 5'b00010 : 5'b00001;
        end else if (st[S_NUM]) begin
            nst = is_dig ? 5'b00100 : 5'b00001;
           if (is_dig) nlim = dig_lim;   // later digits override the budget
        end else if (st[S_STR]) begin
            if (is_q) begin
               nst  = 5'b00001;   // close quote: budgeted escapes retire here
               ncnt = (cnt > lim) ? (cnt - lim) : 4'd0;  // surplus carries on
              npend = cnt;       // park the count in case the literal continues
            end else if (is_bs)
                nst = 5'b10000;    // ESC is reachable only from STR
            else
                nst = 5'b01000;
        end else if (st[S_ESC]) begin
            nst  = 5'b01000;       // ESC always returns to STR
           ncnt = (cnt == lim) ? cnt : (cnt + 4'd1);   // saturate at the budget
        end
    end

    always @(posedge i_clk) begin
        if (i_reset) begin
            st  <= 5'b00001;
            cnt <= 4'd0;
           lim <= 4'd8;
           pend <= 4'd0;
        end else if (i_ce) begin
            st  <= nst;
            cnt <= ncnt;
           lim <= nlim;
           pend <= npend;
        end

        if (i_ce && !i_reset && (st[S_STR] || st[S_ESC]))
            arm <= 1'b1;

        pv <= 1'b1;
    end

    assign o_in_string  = st[S_STR] || st[S_ESC];
    assign o_esc_count  = cnt;

    // Universality, in the "after arm" scope, stated about the previous cycle:
    // once a string literal has been seen, the escape counter is always zero
    // whenever the lexer sits in the IDLE state.
    always @(posedge i_clk)
        if (pv && arm)
            assert (!$past(st[S_IDLE]) || ($past(cnt) == 4'd0));
endmodule

module vd_sheet_loader (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_start,
    input  wire       i_last_row,
    output wire       o_loading,
    output wire       o_ready,
output wire [3:0] o_rows,
output reg  [3:0] o_ce_beats
);
    // binary-encoded loader FSM: IDLE/OPEN/HEADER/ROWS/DONE
    // encodings 101, 110, 111 are never entered by construction
    localparam [2:0] S_IDLE   = 3'b000,
                     S_OPEN   = 3'b001,
                     S_HEADER = 3'b010,
                     S_ROWS   = 3'b011,
                     S_DONE   = 3'b100;

    reg [2:0] st;
    reg       loading;
    reg       ready;
   reg       fin_pend;
    reg [3:0] rows;
   reg       abort_pend;
   reg [3:0] row_max;

    initial st      = S_IDLE;
    initial loading = 1'b0;
    initial ready   = 1'b0;
   initial fin_pend = 1'b0;
    initial rows    = 4'd0;
   initial abort_pend = 1'b0;
   initial row_max    = 4'd4;
initial o_ce_beats = 4'd0;

    always @(posedge clk) begin
        if (i_reset) begin
            st      <= S_IDLE;
            loading <= 1'b0;
            ready   <= 1'b0;
           fin_pend <= 1'b0;
            rows    <= 4'd0;
           abort_pend <= 1'b0;
           row_max    <= 4'd4;
o_ce_beats <= 4'd0;
        end else if (i_ce) begin
o_ce_beats <= o_ce_beats + {3'd0, i_start};
           // completion is committed one beat after the FSM posts it
           ready <= fin_pend || abort_pend;
            case (st)
                S_IDLE: begin
                    if (i_start) begin
                        st      <= S_OPEN;
                        loading <= 1'b1;
                    end else begin
                        st      <= S_IDLE;
                        loading <= 1'b0;
                    end
                end
                S_OPEN: begin
                    st      <= S_HEADER;
                    loading <= 1'b1;
                    rows    <= 4'd0;
                end
                S_HEADER: begin
                    st      <= S_ROWS;
                    loading <= 1'b1;
                end
                S_ROWS: begin
                    if (i_last_row) begin
                        st      <= S_DONE;
                        loading <= 1'b0;
                       fin_pend <= 1'b1;
                   end else if (rows == row_max) begin
                       // row budget exhausted: truncate this sheet and close out
                       st         <= S_DONE;
                       loading    <= 1'b0;
                       abort_pend <= 1'b1;
                   end else begin
                        st      <= S_ROWS;
                        loading <= 1'b1;
                        rows    <= rows + 4'd1;
                    end
                end
                S_DONE: begin
                    st      <= S_IDLE;
                    loading <= 1'b0;
                   fin_pend <= 1'b0;
                   abort_pend <= 1'b0;
                   // adapt the burst budget: grow it when the sheet overran,
                   // shrink it back toward the floor when it fit
                   if (abort_pend) begin
                       if (row_max != 4'd12)
                           row_max <= row_max + 4'd1;
                   end else if (row_max != 4'd4) begin
                       row_max <= row_max - 4'd1;
                   end
                end
                default: begin
                    // illegal encoding: parked recovery path, asserts both flags
                    st      <= 3'b110;
                    loading <= 1'b1;
                    ready   <= 1'b1;
                   fin_pend <= 1'b1;
                  abort_pend <= 1'b1;
                end
            endcase
        end
    end

    assign o_loading = loading;
    assign o_ready   = ready;
    assign o_rows    = rows;

    // P: the loader is never simultaneously loading and ready
    always @(posedge clk)
        assert (!(loading && ready));
endmodule

module wdog_scan (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // scanner step enable; low => whole design idles
    input  wire i_kick,    // full substring match: hard kick of the watchdog
    input  wire i_feed,    // partial match: partial credit, no flag clear
    output wire o_timeout,
    output wire [7:0] o_pos
);
    // Watchdog for a character-scan engine: the scanner must report progress
    // before LIMIT idle steps elapse, otherwise the search is declared timed out.
    localparam [3:0] LIMIT = 4'd12;

    reg [3:0] wd;       // cycles since last progress, saturates at LIMIT
    reg       expired;  // sticky timeout flag
    reg [7:0] pos;      // current character position in the haystack
    reg [3:0] slack;    // remaining scan budget exported to the prefetch stride
    // The timeout flag sits on the report bus, four scan steps downstream of
    // the counter, so a saturation event is registered through this pipe
    // before it is visible to the host.
    reg       exp_s0;   // expiry report, stage 0
    reg       exp_s1;   // expiry report, stage 1
    reg       exp_s2;   // expiry report, stage 2
    reg       exp_s3;   // expiry report, stage 3

    initial wd      = 4'd0;
    initial expired = 1'b0;
    initial pos     = 8'd0;
    initial slack   = LIMIT;
    initial exp_s0  = 1'b0;
    initial exp_s1  = 1'b0;
    initial exp_s2  = 1'b0;
    initial exp_s3  = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            wd      <= 4'd0;
            expired <= 1'b0;
            pos     <= 8'd0;
            slack   <= LIMIT;
            exp_s0  <= 1'b0;
            exp_s1  <= 1'b0;
            exp_s2  <= 1'b0;
            exp_s3  <= 1'b0;
        end else if (i_ce) begin
            // plenty of budget left => the scanner may consume two
            // characters in a single step
            pos <= pos + ((slack > 4'd8) ? 8'd2 : 8'd1);
            // walk the report pipe one stage per scan step; nothing new
            // enters unless the counter saturates this step
            exp_s0 <= 1'b0;
            exp_s1 <= exp_s0;
            exp_s2 <= exp_s1;
            exp_s3 <= exp_s2;
            if (exp_s3)
                expired <= 1'b1;
            if (i_kick) begin
                // full match: reload the watchdog and drop the timeout flag
                wd      <= 4'd0;
                expired <= 1'b0;
                slack   <= LIMIT;
                // the reload also flushes any report still in flight
                exp_s0  <= 1'b0;
                exp_s1  <= 1'b0;
                exp_s2  <= 1'b0;
                exp_s3  <= 1'b0;
            end else if (i_feed) begin
                // partial credit: only granted while the counter has not
                // saturated.  Note the gate looks at the COUNTER, not the flag.
                if (wd != LIMIT)
                    wd <= (wd > 4'd4) ? (wd - 4'd4) : 4'd0;
                // partial credit also refunds budget, capped at the reload value
                if (slack != 4'd0)
                    slack <= (slack < 4'd8) ? (slack + 4'd4) : LIMIT;
            end else begin
                // no progress this step: count up and saturate at LIMIT
                if (wd != LIMIT) begin
                    wd <= wd + 4'd1;
                    if ((wd + 4'd1) == LIMIT)
                        exp_s0 <= 1'b1;
                end
                // spend one unit of budget per idle step, floor at zero
                if (slack != 4'd0)
                    slack <= slack - 4'd1;
            end
        end
    end

    assign o_timeout = expired;
    assign o_pos     = pos;

    // P: a reported timeout always comes with a counter in the top half of
    // its range (the watchdog really did run out of slack).
    always @(posedge clk) assert (!expired || wd[3]);

    // Q: a reported timeout means the exported scan budget is exhausted,
    // so downstream stride logic has already dropped back to one char/step.
    always @(posedge clk) assert (!expired || slack == 4'd0);
endmodule

module gfx_frame_fsm (
    input  wire clk,
    input  wire i_reset,
    input  wire i_ce,
    input  wire i_start,
    output wire o_vsync,
    output wire [2:0] o_state
);
    // binary-encoded frame pipeline states; 5,6,7 are unreachable encodings
    localparam [2:0] S_IDLE    = 3'd0;
    localparam [2:0] S_CLEAR   = 3'd1;
    localparam [2:0] S_DRAW    = 3'd2;
    localparam [2:0] S_BLIT    = 3'd3;
    localparam [2:0] S_PRESENT = 3'd4;
   // overlay plane pipeline stages (shares the framebuffer with the frame pipeline)
   localparam [1:0] OV_IDLE = 2'd0;
   localparam [1:0] OV_CLR  = 2'd1;
   localparam [1:0] OV_FILL = 2'd2;
   localparam [1:0] OV_SWAP = 2'd3;
// shared framebuffer write port: an update is staged here for one cycle
localparam [1:0] FB_NOP = 2'd0;
localparam [1:0] FB_CLR = 2'd1;
localparam [1:0] FB_OVL = 2'd2;

    reg [2:0] state;
    reg [1:0] draw_cnt;
    reg       cleared_seen;   // shadow: framebuffer was cleared this frame
   reg [1:0] ov_state;      // overlay plane pipeline
   reg       ov_pend;       // overlay refresh owed after the last frame
reg [1:0] fb_cmd;        // framebuffer update in flight to the shadow

    initial state        = S_IDLE;
    initial draw_cnt     = 2'd0;
    initial cleared_seen = 1'b0;
   initial ov_state     = OV_IDLE;
   initial ov_pend      = 1'b0;
initial fb_cmd       = FB_NOP;

    wire draw_done = (draw_cnt == 2'd3);
   // framebuffer arbitration: the frame pipeline may only start a new frame
   // when no overlay refresh is running or owed
   wire fb_free = (ov_state == OV_IDLE) && !ov_pend;

    always @(posedge clk) begin
        if (i_reset) begin
            state        <= S_IDLE;
            draw_cnt     <= 2'd0;
            cleared_seen <= 1'b0;
           ov_state     <= OV_IDLE;
           ov_pend      <= 1'b0;
fb_cmd       <= FB_NOP;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                   if (i_start && fb_free) begin
                        state    <= S_CLEAR;
                        draw_cnt <= 2'd0;
                    end
                end
                S_CLEAR: begin
// the clear pass hands its update to the framebuffer write port
// rather than touching the shadow directly
fb_cmd       <= FB_CLR;
                    state        <= S_DRAW;
                end
                S_DRAW: begin
                    if (draw_done)
                        state <= S_BLIT;
                    else
                        draw_cnt <= draw_cnt + 2'd1;
                end
                S_BLIT: begin
                    state <= S_PRESENT;
                end
                S_PRESENT: begin
                    state        <= S_IDLE;
                    draw_cnt     <= 2'd0;
                    cleared_seen <= 1'b0;
                   ov_pend      <= 1'b1;   // overlay gets the buffer next
                end
                default: begin
                    // encodings 5/6/7 never occur by construction; the
                    // synthesised decoder folds them onto the present stage
                    state <= S_PRESENT;
                end
            endcase

           // Overlay plane pipeline: same shape as the frame pipeline above,
           // but it borrows the framebuffer and the shared pass counter, so it
           // only runs in the gap between frames.
           case (ov_state)
               OV_IDLE: begin
                   if (ov_pend && state == S_IDLE) begin
                       ov_state <= OV_CLR;
                       ov_pend  <= 1'b0;
                   end
               end
               OV_CLR: begin
                   ov_state <= OV_FILL;
                   draw_cnt <= 2'd0;
               end
               OV_FILL: begin
// overlay writes land on the shared framebuffer, so the recorded
// clear stops describing its contents once this update retires
fb_cmd <= FB_OVL;
                   if (draw_cnt == 2'd1)
                       ov_state <= OV_SWAP;
                   else
                       draw_cnt <= draw_cnt + 2'd1;
               end
               OV_SWAP: begin
                   ov_state <= OV_IDLE;
                   draw_cnt <= 2'd0;
               end
           endcase
// Shared framebuffer write port.  The staged command retires into the
// shadow here, one cycle after the pass that issued it, and the port is
// re-armed in the same cycle.  The frame pipeline wins the port if both
// planes ask for it in the same cycle.
if (fb_cmd == FB_CLR)
    cleared_seen <= 1'b1;
else if (fb_cmd == FB_OVL)
    cleared_seen <= 1'b0;
if (state == S_CLEAR)
    fb_cmd <= FB_CLR;
else if (ov_state == OV_FILL)
    fb_cmd <= FB_OVL;
else
    fb_cmd <= FB_NOP;
        end
    end

    assign o_vsync = (state == S_PRESENT);
    assign o_state = state;

    // Precedence, global: presenting a frame implies the clear pass happened earlier
    always @(posedge clk)
        if (state == S_PRESENT)
            assert (cleared_seen);
endmodule

// Four-phase req/ack handshake engine with a busy mirror and
// per-client ownership / response routing tags.
//
//   phase 0 : idle            (req=0, ack=0)
//   phase 1 : req asserted    (req=1, ack=0)
//   phase 2 : ack observed    (req=1, ack=1)
//   phase 3 : req withdrawn   (req=0, ack=1)  -> waits for ack to drop
//
// busy is a separate register that mirrors "phase != 0"; the start path is
// gated on !busy only, exactly as a real controller would do.
module fourphase_owner (
    input  wire clk,
    input  wire i_ce,        // idle condition: nothing moves when low
    input  wire i_req,       // a client wants the channel
    input  wire i_sel,       // which client (0 -> A, 1 -> B)
    input  wire i_ack_in,    // ack wire coming back from the target
    output wire o_busy,
    output wire o_req,
    output wire o_ack
);

    reg [1:0] phase;
    reg       busy;
    reg       req;
    reg       ack;
    reg       own_a, own_b;   // who currently owns the channel
    reg       resp_a, resp_b; // where the response will be routed
    reg       virgin;         // high until the first handshake ever completes

  // The owner tag is not written straight from the launch path: the launch
  // cycle is already busy driving req and bumping the credit ledger, so the
  // selected client is parked in a one-deep staging latch and copied into
  // the ownership bits on the following enabled cycle. Progress out of
  // phase 1 stalls until the staged tag has been committed.
  reg       tag_v;
  reg       tag_sel;

   // Credit ledger: one credit exists for the channel. Every acquire is
   // logged in n_acq, every retire in n_rel; both wrap at four bits. The
   // channel may only be taken when all logged acquires have been retired.
   reg [3:0] n_acq;
   reg [3:0] n_rel;

   wire ledger_free = (n_acq == n_rel);

    initial phase  = 2'd0;
    initial busy   = 1'b0;
    initial req    = 1'b0;
    initial ack    = 1'b0;
    initial own_a  = 1'b0;
    initial own_b  = 1'b0;
    initial resp_a = 1'b0;
    initial resp_b = 1'b0;
    initial virgin = 1'b1;
  initial tag_v   = 1'b0;
  initial tag_sel = 1'b0;
   initial n_acq  = 4'd0;
   initial n_rel  = 4'd0;

    always @(posedge clk) begin
        if (i_ce) begin
           if (ledger_free) begin
                // channel believed free: latch the owner and drive req
                if (i_req) begin
                    phase <= 2'd1;
                    req   <= 1'b1;
                    busy  <= 1'b1;
                   n_acq <= n_acq + 4'd1;
                   tag_v   <= 1'b1;
                   tag_sel <= i_sel;
                end
            end else begin
                case (phase)
                   2'd1: if (tag_v) begin
                             // drain the staging latch into the tag bits
                             tag_v <= 1'b0;
                             if (tag_sel)
                                 own_b <= 1'b1;
                             else
                                 own_a <= 1'b1;
                         end else if (i_ack_in) begin
                              // ack rose: snapshot the response route
                              phase  <= 2'd2;
                              ack    <= 1'b1;
                              resp_a <= own_a;
                              resp_b <= own_b;
                          end
                    2'd2: begin
                              // req may only drop now that ack is high
                              phase <= 2'd3;
                              req   <= 1'b0;
                          end
                    2'd3: if (!i_ack_in) begin
                              phase  <= 2'd0;
                              ack    <= 1'b0;
                              busy   <= 1'b0;
                             n_rel  <= n_rel + 4'd1;
                              own_a  <= 1'b0;
                              own_b  <= 1'b0;
                              resp_a <= 1'b0;
                              resp_b <= 1'b0;
                              virgin <= 1'b0;   // first completion disarms
                          end
                    default: ;
                endcase
            end
        end
    end

    assign o_busy = busy;
    assign o_req  = req;
    assign o_ack  = ack;

    // Before the first handshake has ever completed, there must never be two
    // owners at once, and never two response routes at once.
    always @(posedge clk)
        if (virgin) assert (!(own_a && own_b));

    always @(posedge clk)
        if (virgin) assert (!(resp_a && resp_b));

endmodule

module lock_arbiter_occ (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire [3:0] i_req,
    output wire [3:0] o_grant,
    output wire       o_busy
);
    // fixed-priority arbiter with a lock bit that freezes the winner
    reg [3:0] grant;
    reg       lock;
    // shadow occupancy counter: how many grants are currently outstanding
    reg [2:0] occ;
    // lock-hold timer: beats the current owner has held the bus
    reg [2:0] hold_cnt;
   // bus turnaround: dead beats after a release before the slot is freed
   reg [1:0] tail_cnt;

    initial grant = 4'b0000;
    initial lock  = 1'b0;
    initial occ   = 3'd0;
    initial hold_cnt = 3'd0;
   initial tail_cnt = 2'd0;

    wire        busy    = (grant != 4'b0000);
    wire        any_req = (i_req != 4'b0000);

    // fixed priority: channel 0 highest
    wire [3:0] pri_grant = i_req[0] ? 4'b0001 :
                           i_req[1] ? 4'b0010 :
                           i_req[2] ? 4'b0100 :
                           i_req[3] ? 4'b1000 : 4'b0000;
    // anti-starvation: the lock expires after 5 held beats so lower channels can win
    wire lock_expired = (hold_cnt >= 3'd5);

    // while locked, the current winner keeps the bus as long as it still asks
    wire holding = busy && lock && !lock_expired && ((grant & i_req) != 4'b0000);

    always @(posedge i_clk) begin
        if (i_rst) begin
            grant <= 4'b0000;
            lock  <= 1'b0;
            occ   <= 3'd0;
            hold_cnt <= 3'd0;
           tail_cnt <= 2'd0;
        end else if (i_ce) begin
            if (busy) begin
                if (!holding) begin
                   // winner released: drop the grant and start the bus turnaround
                    grant <= 4'b0000;
                    lock  <= 1'b0;
                   tail_cnt <= 2'd2;
                    hold_cnt <= 3'd0;
                end
                else begin
                    // still holding: age the lock
                    hold_cnt <= hold_cnt + 3'd1;
                end
           end else if (tail_cnt != 2'd0) begin
               // turnaround: the slot is only freed on the last dead beat
               tail_cnt <= tail_cnt - 2'd1;
               if (tail_cnt == 2'd1)
                   occ <= occ - 3'd1;
           end else if (any_req) begin
                // bus free: award it and lock it
                grant <= pri_grant;
                lock  <= 1'b1;
                occ   <= occ + 3'd1;
                hold_cnt <= 3'd0;
            end
        end
    end

    assign o_grant = grant;
   assign o_busy  = busy || (tail_cnt != 2'd0);

    // at most one grant may be outstanding at any time
    always @(*)
        assert (occ <= 3'd1);

    // the hold timer only ages while a grant is outstanding
    always @(posedge i_clk)
        assert ((hold_cnt == 3'd0) || (occ == 3'd1));
endmodule

module debounce_hist_arm (
    input  wire i_clk,
    input  wire i_ce,
    input  wire i_raw,
    output wire o_clean,
    output wire o_armed,
    output wire o_settled
);
    // K identical consecutive samples are required before the clean output flips.
    localparam [2:0] KC = 3'd4;
    localparam       HW = 8;

    reg [2:0]      cnt;     // stability counter, saturates at KC
    reg            sample;  // current candidate level being timed
    reg            clean;   // debounced (committed) level
    reg [HW-1:0]   hist;    // raw sample history, hist[0] is the newest sample
    reg            armed;   // sticky: set the first time the filter commits
   reg            stable;  // registered settled flag, drives o_settled
reg            pend;    // pending level change: candidate differs from the committed level

    initial cnt    = 3'd0;
    initial sample = 1'b0;
    initial clean  = 1'b0;
    initial hist   = {HW{1'b0}};
    initial armed  = 1'b0;
   initial stable = 1'b0;
initial pend   = 1'b0;

    always @(posedge i_clk) if (i_ce) begin
        hist <= { hist[HW-2:0], i_raw };
        if (i_raw != sample) begin
            // new level seen: retime from scratch
            sample <= i_raw;
            cnt    <= 3'd0;
           stable <= 1'b0;
pend   <= i_raw ^ clean;
        end else if (cnt < KC) begin
            cnt <= cnt + 3'd1;
            if (cnt == (KC - 3'd1)) begin
                // KC identical consecutive samples: commit the level
clean <= clean ^ pend;
pend  <= 1'b0;
                armed <= 1'b1;
               stable <= 1'b1;
            end
        end
    end

    assign o_clean   = clean;
    assign o_armed   = armed;
   assign o_settled = stable;

    // Universality, after the filter has armed: whenever the stability counter
    // is nonzero the two newest raw samples must agree.
    always @(*)
        if (armed)
            assert ((cnt == 3'd0) || (hist[1] == hist[0]));

   // While the filter reports settled, the committed level must still match the
   // newest raw sample: any disagreement would mean a missed retime.
   always @(posedge i_clk)
       assert (!stable || (clean == hist[0]));
endmodule

// Priority arbiter for per-subchannel energy detect flags.
// Stage 0: combinational priority encode of the request vector.
// Stage 1: registered half-occupancy flags + priority-half decision.
// Stage 2: registered valid, registered index (only meaningful while valid),
//          and the two half-band grant flags.
module wifi_pri_grant (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [7:0] i_req,
    output reg        o_vld,
    output reg  [2:0] o_idx,
    output reg        o_grant_lo,
    output reg        o_grant_hi
);
    // ---------------- stage 0: combinational priority encoder ------------
    wire req_lo = |i_req[3:0];
    wire req_hi = |i_req[7:4];

    reg [2:0] enc;
    always @(*) begin
        casez (i_req)
            8'b???????1: enc = 3'd0;
            8'b??????10: enc = 3'd1;
            8'b?????100: enc = 3'd2;
            8'b????1000: enc = 3'd3;
            8'b???10000: enc = 3'd4;
            8'b??100000: enc = 3'd5;
            8'b?1000000: enc = 3'd6;
            8'b10000000: enc = 3'd7;
            default:     enc = 3'd0;
        endcase
    end

    // ---------------- stage 1 registers ---------------------------------
    reg       s1_vld;
    reg       s1_req_lo;
    reg       s1_req_hi;
    reg       s1_pri_hi;   // upper half wins only when lower half is empty
    reg [2:0] s1_idx;

   // ---------------- accounting park slot -------------------------------
   // cnt_hi lives in the slow retention domain and needs a cycle of its own
   // to absorb a write, so an upper-band grant is parked for one cycle
   // together with the energy flag of the cycle it came from.  Stage 1 stops
   // issuing while the slot is in use, so only one upper-band event is ever
   // in flight.
   reg       park_hi;
   reg       park_act;
   wire      acct_busy = (s1_vld && s1_pri_hi) || park_hi;

   // ---------------- stage 2 grant accounting --------------------------
   // Per-band grant counters plus a counter of cycles in which any band
   // reported energy.  Firmware samples their low bits on the index bus
   // while the pipe is idle (o_idx carries no index when o_vld is low).
   reg [3:0] cnt_lo;
   reg [3:0] cnt_hi;
   reg [3:0] cnt_tot;

    initial begin
        s1_vld    = 1'b0;
        s1_req_lo = 1'b0;
        s1_req_hi = 1'b0;
        s1_pri_hi = 1'b0;
        s1_idx    = 3'd0;
       park_hi   = 1'b0;
       park_act  = 1'b0;
       cnt_lo     = 4'd0;
       cnt_hi     = 4'd0;
       cnt_tot    = 4'd0;
        o_vld      = 1'b0;
        o_idx      = 3'd0;
        o_grant_lo = 1'b0;
        o_grant_hi = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // stage 1 capture
s1_vld    <= (req_lo | req_hi) && !acct_busy;
            s1_req_lo <= req_lo;
            s1_req_hi <= req_hi;
            s1_pri_hi <= req_hi && !req_lo;
            s1_idx    <= enc;

            // stage 2 capture
            o_vld      <= s1_vld;
           // idle index bus carries a compact counter status code
           o_idx      <= s1_vld ? s1_idx
                                : {cnt_tot[0], cnt_hi[0], cnt_lo[0]};
            o_grant_lo <= s1_vld && s1_req_lo;
            o_grant_hi <= s1_vld && s1_pri_hi;

           // grant accounting, driven off the same stage-1 decision
           park_hi  <= s1_vld && s1_pri_hi;
           park_act <= (s1_vld && s1_pri_hi) && (s1_req_lo || s1_req_hi);
           if (s1_vld && s1_req_lo)
               cnt_lo  <= cnt_lo  + 4'd1;
if (park_hi)
               cnt_hi  <= cnt_hi  + 4'd1;
if ((s1_vld && !s1_pri_hi && (s1_req_lo || s1_req_hi)) || park_act)
               cnt_tot <= cnt_tot + 4'd1;
        end
    end

    // P: while the encoded index is valid, the two half-band grants are
    //    never asserted together.
    always @(posedge clk)
        if (o_vld)
            assert (!(o_grant_lo && o_grant_hi));

   // Q: the per-band grant counters account for exactly the counted
   //    request cycles.
   always @(posedge clk)
       assert (cnt_tot == cnt_lo + cnt_hi);

endmodule

module elevator_call_gen (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output reg  [1:0] floor,
    output reg        dir,
    output reg  [3:0] pending,
    output reg  [2:0] dry_cnt,
    output reg  [3:0] lf
);
// Pseudo-random hall-call source.  The shift chain and its feedback XOR
// are split across two flops: the tap is evaluated one cycle ahead into
// lf_fb and shifted in on the next enabled step, which keeps the XOR
// gate out of the shift path.  Taps are chosen so that the combined
// 5-bit generator state {lf, lf_fb} is maximal length (period 31).
reg lf_fb;
// Quiet watchdog: reloaded on every hall call and decremented on every
// silent enabled step.  It is the budget of steps the generator may stay
// quiet before the cab is handed a target of its own.
reg [2:0] quiet_wd;

initial lf_fb   = 1'b0;
    initial lf      = 4'b0001;
    initial floor   = 2'd0;
    initial dir     = 1'b1;   // 1 = up, 0 = down
    initial pending = 4'b0000;
    initial dry_cnt = 3'd0;
    initial quiet_wd = 3'd3;

wire       lf_fb_next = lf[3] ^ lf[1];
wire [3:0] lf_next    = {lf[2:0], lf_fb};

// A pseudo-random hall call is issued unless the top three shift
// stages of the generator are all zero.
    wire       new_call   = (lf[3:1] != 3'b000);
    wire [1:0] call_floor = lf[1:0];

    wire at_top = (floor == 2'd3);
    wire at_bot = (floor == 2'd0);

    wire [1:0] floor_next = dir ? (at_top ? floor : floor + 2'd1)
                                : (at_bot ? floor : floor - 2'd1);
    wire       dir_next   = dir ? (at_top ? 1'b0 : 1'b1)
                                : (at_bot ? 1'b1 : 1'b0);

    // On the watchdog's last tick a call at the top floor is synthesized,
    // so a quiet generator cannot leave the cab without work.
    wire       wd_last    = (quiet_wd <= 3'd1);
    wire [3:0] set_mask   = new_call ? (4'b0001 << call_floor)
                                     : (wd_last ? 4'b1000 : 4'b0000);
    wire [3:0] clr_mask   = (4'b0001 << floor);

    always @(posedge clk) begin
        if (rst) begin
            lf      <= 4'b0001;
lf_fb   <= 1'b0;
            floor   <= 2'd0;
            dir     <= 1'b1;
            pending <= 4'b0000;
            dry_cnt <= 3'd0;
            quiet_wd <= 3'd3;
        end else if (step) begin
            lf      <= lf_next;
lf_fb   <= lf_fb_next;
            floor   <= floor_next;
            dir     <= dir_next;
            pending <= (pending | set_mask) & ~clr_mask;
            // consecutive enabled steps during which no new call appeared
            dry_cnt <= new_call ? 3'd0 : (dry_cnt + 3'd1);
            quiet_wd <= new_call ? 3'd3
                                 : (quiet_wd == 3'd0 ? 3'd0 : quiet_wd - 3'd1);
        end
    end

    // Bounded existence: the call-starvation streak never exceeds 3,
    // although the counter is 3 bits wide.
    assert property (dry_cnt <= 3'd3);

    // The watchdog always has budget left over: calls arrive in time.
    always @(posedge clk)
        assert (quiet_wd >= 3'd1);
endmodule

module gray_shadow_ctr (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    output wire [3:0] o_gray,
output wire [3:0] o_bin,
output reg  [3:0] ce_hist
);
    // Binary shadow counter and its gray-coded twin.  The gray register is
    // advanced by the classic single-bit-toggle rule, computed from the gray
    // value alone; the binary shadow is a plain increment.
    reg [3:0] bin;
    reg [3:0] gray;
    reg       pv;
   reg [3:0] gray_s;
   reg       s_vld;
reg       ce_d;

    initial bin  = 4'b0000;
    initial gray = 4'b0000;
    initial pv   = 1'b0;
   initial gray_s = 4'b0000;
   initial s_vld  = 1'b0;
initial ce_d    = 1'b0;
initial ce_hist = 4'b0000;

    // Next gray value: toggle bit 0 when the parity is even, otherwise toggle
    // the bit just above the lowest set bit (with the top bit handling wrap).
    function [3:0] gnext(input [3:0] g);
        begin
            if (!(^g))     gnext = g ^ 4'b0001;
            else if (g[0]) gnext = g ^ 4'b0010;
            else if (g[1]) gnext = g ^ 4'b0100;
            else           gnext = g ^ 4'b1000;
        end
    endfunction

   // Stage 1: the gray pointer is advanced one cycle ahead of the output
   // registers, so o_gray leaves the block straight off a flop instead of
   // through the toggle-select network.  s_vld marks the staged word as a
   // pending advance that the commit stage still owes the outputs.
   always @(posedge clk) begin
       if (rst) begin
           gray_s <= 4'b0000;
           s_vld  <= 1'b0;
ce_d    <= 1'b0;
ce_hist <= 4'b0000;
       end else begin
           s_vld <= i_ce;
ce_d    <= i_ce;
ce_hist <= {ce_hist[2:0], ce_d};
           if (i_ce) gray_s <= gnext(gray_s);
       end
   end

   // Stage 2: commit the staged pointer and bump the binary shadow in the
   // same cycle, so the two views never disagree at the outputs.

    always @(posedge clk) begin
        if (rst) begin
            bin  <= 4'b0000;
            gray <= 4'b0000;
       end else if (s_vld) begin
            bin  <= bin + 4'b0001;
           gray <= gray_s;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign o_gray = gray;
    assign o_bin  = bin;

    // Top bit of the gray word and top bit of the binary shadow: the most
    // significant gray bit is just the most significant binary bit, so neither
    // may move without the other.
    wire g_msb = gray[3];
    wire b_msb = bin[3];

    // P: whenever the gray MSB did not change, the shadow MSB did not change.
    always @(posedge clk)
        if (pv && $stable(g_msb))
            assert ($stable(b_msb));
endmodule

module dma_copier_chain (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_clear,
    input  wire [3:0] i_len,
    output wire       o_done,
    output wire       o_busy,
    output wire       o_err
);
    // phase slice codes (gray-ish), each with its stored parity bit
    localparam [1:0] PH_IDLE  = 2'b00,   // parity 0
                     PH_ARMED = 2'b01,   // parity 1
                     PH_BUSY  = 2'b11,   // parity 0
                     PH_DONE  = 2'b10;   // parity 1

    // parity-protected register slice holding the engine phase
    reg [1:0] phase   = PH_IDLE;
    reg       par     = 1'b0;

    // descriptor word counter
    reg [3:0] count   = 4'd0;

    // chain history bits: arm happened, start happened
    reg       h_arm   = 1'b0;
    reg       h_start = 1'b0;
    // start handshake stage: the start pulse is captured here for the
    // descriptor-fetch cycle and is only then logged into h_start
    reg       s_pend  = 1'b0;

   // descriptor status shadow: while a descriptor is in flight the
   // "start beat seen" record is kept here; it is only folded into the
   // chain log when the descriptor actually retires
   reg       sh_start = 1'b0;

    // slice checker: stored parity must match stored phase
   wire slice_bad = (par != (^phase)) || (phase == PH_IDLE && sh_start);

    always @(posedge clk) begin
        if (i_ce) begin
            if (slice_bad) begin
                // corrupted descriptor slice: abort, report done immediately
                phase <= PH_DONE;
                par   <= 1'b1;
            end else begin
                case (phase)
                PH_IDLE:
                    if (i_arm) begin
                        phase   <= PH_ARMED;
                        par     <= 1'b1;
                        count   <= i_len;
                        h_arm   <= 1'b1;
                    end
                PH_ARMED:
                    if (i_start) begin
                        phase   <= PH_BUSY;
                        par     <= 1'b0;
                        s_pend  <= 1'b1;
                    end
                PH_BUSY:
                    if (s_pend) begin
                        // first burst cycle fetches the descriptor word,
                       // no payload word moves and the length is untouched;
                       // the start beat lands in the status shadow, not yet
                       // in the chain log
                        s_pend  <= 1'b0;
                       sh_start <= 1'b1;
                    end else if (count == 4'd0) begin
                        phase <= PH_DONE;
                        par   <= 1'b1;
                       // retire: commit the in-flight status into the chain
                       // log and release the shadow for the next descriptor
                       h_start  <= sh_start;
                       sh_start <= 1'b0;
                    end else begin
                        count <= count - 4'd1;
                    end
                PH_DONE:
                    if (i_clear) begin
                        phase <= PH_IDLE;
                        par   <= 1'b0;
                    end
                endcase
            end
        end
    end

    assign o_done = (phase == PH_DONE);
    assign o_busy = (phase == PH_BUSY);
    assign o_err  = slice_bad;

    // chain precedence, globally: a finish can never be seen unless the
    // arm step and then the start step were actually taken
    always @(posedge clk)
        if (phase == PH_DONE) assert (h_arm);

    always @(posedge clk)
        if (phase == PH_DONE) assert (h_start);
endmodule

module csa_accum_parity (
    input  wire       clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_clear,
    input  wire [7:0] i_data,
    output wire [7:0] o_total,
    output wire [7:0] o_ref
);
    // accumulator kept in carry-save form: two halves that always sum to the
    // true running total held in the reference register
    reg [7:0] acc_s = 8'h00;   // sum half
    reg [7:0] acc_c = 8'h00;   // carry half (always even by construction)
reg [3:0] total  = 4'h0;   // reference accumulator, low nibble slice
reg [3:0] tot_hi = 4'h0;   // reference accumulator, high nibble slice
    reg        hi_flag = 1'b0; // registered "total has reached the upper half";
                               // precomputed on the adder result so the flush
                               // path next cycle is just a flop-to-mux hop

    wire [7:0] sum_bits   = acc_s ^ acc_c ^ i_data;
    wire [7:0] maj_bits   = (acc_s & acc_c) | (acc_s & i_data) | (acc_c & i_data);
    wire [7:0] carry_bits = {maj_bits[6:0], 1'b0};
// reference adder is built from two nibble slices so neither carry chain
// spans the whole word; the upper slice is only clocked on cycles where it
// can actually change, which keeps it quiet for small operands
wire [4:0] lo_sum     = {1'b0, total} + {1'b0, i_data[3:0]};
wire       lo_cout    = lo_sum[4];
wire [3:0] hi_sum     = tot_hi + i_data[7:4] + {3'b0, lo_cout};
wire       hi_en      = lo_cout || (i_data[7:4] != 4'h0);
wire [7:0] next_total = {hi_sum, lo_sum[3:0]};

    always @(posedge clk) begin
        if (i_rst) begin
            acc_s <= 8'h00;
            acc_c <= 8'h00;
total  <= 4'h0;
tot_hi <= 4'h0;
            hi_flag <= 1'b0;
        end else if (i_ce) begin
            if (i_clear || hi_flag) begin
                acc_s <= 8'h00;
                acc_c <= 8'h00;
total  <= 4'h0;
tot_hi <= 4'h0;
                hi_flag <= 1'b0;
            end else begin
                acc_s <= sum_bits;
                acc_c <= carry_bits;
total   <= next_total[3:0];
if (hi_en)
    tot_hi <= next_total[7:4];
                hi_flag <= next_total[7];
            end
        end
    end

    assign o_total = acc_s + acc_c;
assign o_ref   = {tot_hi, total};

    // P: while the unit is actually accumulating, the low bit of the sum half
    // alone already carries the parity of the true total.
    always @(posedge clk)
        if (i_ce && !i_clear)
            assert (acc_s[0] == total[0]);

    // P2: the flush flag was computed from the adder result, so it must still
    // describe the value the carry-save side is currently reporting.
    always @(posedge clk)
        assert (hi_flag == o_total[7]);
endmodule

module arb_lock_pending (
    input  wire       clk,
    input  wire       ce,      // global enable / idle when low
    input  wire [3:0] req,     // new requests, latched into pend
    input  wire       rel,     // current owner releases the lock
    output wire [3:0] grant,
    output wire [2:0] occupancy
);
    // pending request bitmap and its redundant occupancy counter
    reg [3:0] pend  = 4'b0000;
    reg [2:0] pcnt  = 3'd0;
   reg [2:0] bcnt  = 3'd0;   // bank B (indices 2,3) occupancy
    // fixed-priority arbiter with a lock bit freezing the winner
    reg       lock  = 1'b0;
    reg [1:0] owner = 2'd0;
    reg       pv    = 1'b0;   // past-valid

   // service ledger: every admission and every retirement is logged,
   // both counters free-run and wrap at four bits
   reg [3:0] n_in  = 4'd0;
   reg [3:0] n_out = 4'd0;

    // fixed priority: lowest index wins
wire [1:0] pick_a = pend[0] ? 2'd0 : 2'd1;
wire [1:0] pick_b = pend[2] ? 2'd2 : 2'd3;
// drain the fuller bank first; ties break toward bank A
// work still outstanding per the ledger, and the bank A share of it
wire [3:0] bal     = n_in - n_out;
wire [2:0] a_bal   = bal[2:0] - bcnt;
wire       serve_b = (bcnt > a_bal);
wire [1:0] pick    = serve_b ? pick_b : pick_a;
    wire       any  = |pend;

    // service completion: the locked owner releases, its pending bit retires
    wire       do_clr   = ce && lock && rel;
    wire [3:0] clr_mask = do_clr ? (4'b0001 << owner) : 4'b0000;
    // only genuinely new requests are inserted
// credit limit: admission stops once three entries are outstanding
wire       adm      = (bal < 4'd3);
wire [3:0] set_mask = (ce && adm) ? (req & ~pend & ~clr_mask) : 4'b0000;
wire [2:0] nset_a   = set_mask[0] + set_mask[1];
wire [2:0] nset_b   = set_mask[2] + set_mask[3];
wire       dec_a    = do_clr && !owner[1];
wire       dec_b    = do_clr &&  owner[1];

    assign grant     = lock ? (4'b0001 << owner) : 4'b0000;
assign occupancy = pcnt + bcnt;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ce) begin
            pend <= (pend | set_mask) & ~clr_mask;
pcnt <= pcnt + nset_a - (dec_a ? 3'd1 : 3'd0);
bcnt <= bcnt + nset_b - (dec_b ? 3'd1 : 3'd0);
n_in  <= n_in  + {1'b0, nset_a} + {1'b0, nset_b};
n_out <= n_out + {3'd0, dec_a} + {3'd0, dec_b};
            if (lock) begin
                if (rel)
                    lock <= 1'b0;      // frozen winner until it releases
            end else if (any) begin
                lock  <= 1'b1;
                owner <= pick;
            end
        end
    end

    // P: if the pending bitmap did not change, the occupancy must not have
    // changed either, and the occupancy stays within its real bound of 4.
    always @(posedge clk)
        if (pv && $stable(pend))
            assert ($stable(pcnt) && (pcnt <= 3'd4));
endmodule

module gray_deadline_tracker (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       req,       // request pulse
    output wire [3:0] o_gray,
    output wire [3:0] o_bin,
    output wire [3:0] o_timer,
    output wire       o_busy,
output wire       o_on_time,
output reg  [3:0] o_req_hist
);
    // ---- gray counter with its binary shadow -------------------------
    reg [3:0] bin;
    reg [3:0] gray;

   // The binary->gray conversion is pipelined: the encoder runs one
// increment ahead of the visible counter; behind it a four-deep
// prefetch chain holds the next four encodings, so the adder and the
// XOR network run six counts ahead and every register in the chain --
// including the output register -- is fed straight out of a register.
reg [2:0] gray_pre;     // in-flight gray code for bin+1, low bits
// Bit 3 of a gray code is just bit 3 of the binary count, so the top
// bit skips the XOR network entirely and lives in its own register.
// It is only reloaded on the two counts where it can change, which
// keeps it from toggling with the rest of the pipeline.
reg       gray_pre_top;
// prefetch chain: pre-encoded gray codes waiting to be shifted into
// the stage-1 registers, oldest (nearest the output) first.
reg [3:0] gray_pre2;    // gray code queued for bin+2
reg [3:0] gray_pre3;    // gray code queued for bin+3
reg [3:0] gray_pre4;    // gray code queued for bin+4
reg [3:0] gray_pre5;    // gray code queued for bin+5

    // ---- bounded-response deadline machinery -------------------------
    reg [3:0] timer;      // countdown for the outstanding request
    reg       busy;       // request outstanding
    reg [3:0] goal_gray;  // gray code the counter should show at completion
   reg [3:0] goal_pre;   // deadline gray code, encoded K counts ahead
    reg       armed;      // sticky: set the first time a request is seen

    reg       pv;         // past valid

   // ---- distractor: rolling record of request pulses ---------------
   reg [3:0] req_hist;

    localparam [3:0] K = 4'd8;   // response bound

    initial begin
        bin       = 4'd0;
        gray      = 4'd0;
gray_pre     = 3'd1;   // encoder prefilled with gray(bin+1)[2:0]
gray_pre_top = 1'b0;   // ... and its top bit
gray_pre2    = 4'd3;   // prefetch chain prefilled with gray(bin+2..5)
gray_pre3    = 4'd2;
gray_pre4    = 4'd6;
gray_pre5    = 4'd7;
        timer     = 4'd0;
        busy      = 1'b0;
        goal_gray = 4'd0;
       goal_pre  = 4'd12;   // gray(0 + K)
        armed     = 1'b0;
        pv        = 1'b0;
       req_hist   = 4'd0;
       o_req_hist = 4'd0;
    end

    wire [3:0] bin_nxt  = bin + 4'd1;
   wire [3:0] bin_ahead  = bin_nxt + 4'd1;
// deepest lookahead: the count whose encoding enters the chain now
wire [3:0] bin_la     = bin + 4'd6;
wire [3:0] gray_la    = bin_la ^ (bin_la >> 1);
// the held top bit only needs a new value as the count rolls into 8 or 0
wire       top_load  = (bin_ahead[2:0] == 3'd0);

// The deadline encoder runs alongside the counter so the accept path
// does not have to carry an adder and an XOR network in the same
// cycle: goal_pre always holds the code the counter will show K
// counts from now, and accept just latches it.
wire [3:0] goal_bin      = bin_nxt + K;
wire [3:0] goal_gray_nxt = goal_bin ^ (goal_bin >> 1);

    wire accept = i_ce && armed && req && !busy;
    wire tick   = i_ce && busy;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            // gray counter advances together with its binary shadow
            bin  <= bin_nxt;
gray_pre  <= gray_pre2[2:0];
if (top_load) gray_pre_top <= gray_pre2[3];
gray     <= {gray_pre_top, gray_pre};
// the prefetch chain shifts one encoding per count
gray_pre2 <= gray_pre3;
gray_pre3 <= gray_pre4;
gray_pre4 <= gray_pre5;
gray_pre5 <= gray_la;
           // deadline encoder keeps pace with the counter
           goal_pre <= goal_gray_nxt;

            // sticky arm: first request ever seen arms the monitor forever
            if (req) armed <= 1'b1;
           req_hist   <= {req_hist[2:0], req};
           o_req_hist <= req_hist ^ {1'b0, req_hist[3:1]};

            if (accept) begin
                busy      <= 1'b1;
                timer     <= K;
               goal_gray <= goal_pre;
            end else if (busy) begin
                if (timer == 4'd1) begin
                    // completion lands exactly on the deadline tick
                    busy  <= 1'b0;
                    timer <= 4'd0;
                end else begin
                    timer <= timer - 4'd1;
                end
            end
        end
    end

    assign o_gray    = gray;
    assign o_bin     = bin;
    assign o_timer   = timer;
    assign o_busy    = busy;
    assign o_on_time = busy && (gray == goal_gray);

    // P: after the monitor is armed, while a request is outstanding the
    // deadline countdown may only move when the gray counter moves --
    // it can never silently run down toward expiry.
    always @(posedge clk)
        if (pv && armed && busy && $stable(gray))
            assert ($stable(timer));

   // P2: the on-time flag marks the deadline count itself -- the
   // tracked request is due exactly when the counter reaches the
   // latched goal code.
   always @(posedge clk)
       assert (o_on_time == (busy && (timer == 4'd1)));
endmodule

module parity_slice_occ (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_data,
    output reg        o_valid,
    output reg  [7:0] o_data,
    output reg        o_retry
);
    // two-deep register slice, each stage protected by a parity bit
    reg [7:0] d0, d1;
    reg       p0, p1;
   // per-nibble parity: p0/p1 cover bits [3:0] and the h companions bits [7:4],
   // so a reported mismatch localises the fault to one half-word
   reg       p0h, p1h;
    reg       v0, v1;

    // occupancy accounting: one 3-bit counter tracking live stages
    reg [2:0] occ;

   // egress check: the word presented on the output register keeps its slice
   // slot for one more cycle while its parity is re-checked, so the credit is
   // returned one cycle after the word leaves
   reg       oq_busy;
   reg       oq_par;
  reg       oq_parh;

  // sideband echo lane: a control word tagged with bit 6 is parked here and
  // replayed onto the output whenever the data lane's second stage is empty.
  // It draws its slot from the same occupancy pool as the data lane.
  reg [7:0] sb_d;
  reg       sb_p;
 reg       sb_ph;
  reg       sb_v;
 // the echo lane leases its slot on a dedicated credit counter, so a parked
 // control word does not disturb the data-lane accounting; the credit is
 // migrated into occ at the moment the parked word takes the egress slot
 reg [2:0] sb_occ;

   // programmable slot limit (one or two stages), written by a control word
   reg [2:0] lim;

  // replay bookkeeping: every parity mismatch books one replay slot, and a
  // booked slot is handed back when the egress re-check frees a credit
  reg [2:0] rpy;

    initial begin
        d0 = 8'h00; d1 = 8'h00;
        p0 = 1'b0;  p1 = 1'b0;
       p0h = 1'b0; p1h = 1'b0;
        v0 = 1'b0;  v1 = 1'b0;
        occ = 3'd0;
       oq_busy = 1'b0;
       oq_par  = 1'b0;
      oq_parh = 1'b0;
       sb_d = 8'h00; sb_p = 1'b0; sb_v = 1'b0;
      sb_ph = 1'b0;
     sb_occ  = 3'd0;
       lim     = 3'd2;
      rpy     = 3'd0;
        o_valid = 1'b0;
        o_data  = 8'h00;
        o_retry = 1'b0;
    end

    // stored parity is checked against stored data every cycle
   wire mism0 = v0 && ((p0 != (^d0[3:0])) || (p0h != (^d0[7:4])));
   wire mism1 = v1 && ((p1 != (^d1[3:0])) || (p1h != (^d1[7:4])));
wire mismsb = sb_v && ((sb_p != (^sb_d[3:0])) || (sb_ph != (^sb_d[7:4])));
wire retry  = mism0 || mism1 || mismsb;

   // the slot is only released when the egress parity re-check is clean
  wire oq_bad = oq_busy && ((oq_par != (^o_data[3:0])) || (oq_parh != (^o_data[7:4])));
   wire rel    = oq_busy && !oq_bad;

   // control words carry the depth limit instead of payload
   wire cfg  = i_valid && i_data[7];
  wire [3:0] pool = {1'b0, occ} + {1'b0, sb_occ};
  wire room = pool < {1'b0, lim};
   wire acc  = i_valid && !cfg && room;
   wire nack = i_valid && !cfg && !room;
  // echo lane arbitration: the parked word only reaches the egress slot when
  // the data lane's second stage is empty, so the lanes never collide
  wire echo    = cfg && i_data[6];
  wire sb_acc  = echo && !sb_v && room;
  wire sb_nack = echo && (sb_v || !room);
  wire sb_go   = sb_v && !v1;

    always @(posedge clk) begin
        if (i_ce) begin
o_retry <= retry || nack || sb_nack || oq_bad || (rpy != 3'd0);
            if (retry) begin
                // corrupted stage: freeze the slice and book a replay slot
                occ <= occ + 3'd1;
               rpy <= rpy + 3'd1;
            end else begin
                // normal shift: stage0 -> stage1 -> output
                d1 <= d0;
                p1 <= p0;
               p1h <= p0h;
                v1 <= v0;
                d0 <= i_data;
               p0  <= ^i_data[3:0];
               p0h <= ^i_data[7:4];
               v0 <= acc;
oq_busy <= v1 || sb_go;
oq_par  <= v1 ? p1 : sb_p;
oq_parh <= v1 ? p1h : sb_ph;
sb_v <= sb_acc || (sb_v && !sb_go);
if (sb_acc) begin
    sb_d <= i_data;
   sb_p  <= ^i_data[3:0];
   sb_ph <= ^i_data[7:4];
end
if (cfg && !echo) lim <= i_data[0] ? 3'd2 : 3'd1;
occ    <= occ + (acc ? 3'd1 : 3'd0) + (sb_go ? 3'd1 : 3'd0) - (rel ? 3'd1 : 3'd0);
sb_occ <= sb_occ + (sb_acc ? 3'd1 : 3'd0) - (sb_go ? 3'd1 : 3'd0);
              if (rel && rpy != 3'd0) rpy <= rpy - 3'd1;
o_valid <= v1 || sb_go;
o_data  <= v1 ? d1 : sb_d;
            end
        end
    end

    // bounded existence: the slice is two deep, so occupancy never exceeds 2
    always @(*) assert (occ <= 3'd2);

   // a replay slot is only booked on a real corruption, so booked slots plus
   // live slice slots never oversubscribe the two-deep slice
   always @(posedge clk)
       assert ({1'b0, occ} + {1'b0, rpy} <= 4'd2);
endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    // upstream credit: number of empty slots, maintained incrementally so the
    // full indication does not have to decode the valid flags
    reg [1:0] free;
   // peak occupancy telemetry: high-water mark of the occupancy counter since
   // reset, sampled every cycle and read back on the data output while the
   // buffer is empty (the head slot carries no valid word then)
   reg [1:0] hwm;
  // the peak comparator is retimed behind a stage register: the occupancy
  // that will be resident next cycle is captured here and is compared
  // against the high-water mark on the following edge, so the occupancy
  // adders and the comparator no longer share one cycle of timing budget
  reg [1:0] peak_q;
 // the peak telemetry is filed per stage: hwm is the head buffer's mark and
 // hwm_b the spill stage's, so a deep backlog waiting in the spill stage is
 // not reported as deep head occupancy. peak_sel remembers which mark the
 // staged sample belongs to, since the comparison happens a cycle after the
 // sample is captured.
 reg [1:0] hwm_b;
 reg       peak_sel;
    reg [7:0] d0, d1;

   // spill stage: a second two-entry buffer sitting behind the head buffer so
   // a burst is not backpressured while the head buffer is draining. words
   // leave the spill stage in arrival order and refill the head buffer.
   reg       vb0, vb1;
   reg [1:0] cntb;
   reg [7:0] b0, b1;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial free  = 2'd2;
   initial hwm   = 2'd0;
  initial peak_q = 2'd0;
 initial hwm_b    = 2'd0;
 initial peak_sel = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
   initial vb0   = 1'b0;
   initial vb1   = 1'b0;
   initial cntb  = 2'd0;
   initial b0    = 8'h00;
   initial b1    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
   wire push_a  = push && !v1 && !vb0;      // straight in when there is no backlog
   wire push_b  = push && !vb1 && !push_a;  // otherwise the word spills
   wire refill  = vb0 && !v1;               // backlog moves up when a slot frees
   wire do_push = push_a || refill;         // head buffer write enable
    wire do_pop  = pop  &&  v0;
   wire [7:0] a_din  = push_a ? din : b0;
  // next-state occupancy of whichever stage the upstream is feeding; the
  // single shared comparator sees it one cycle later, through peak_q
  wire [1:0] count_nxt = count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
  wire [1:0] cntb_nxt  = cntb  + (push_b  ? 2'd1 : 2'd0) - (refill  ? 2'd1 : 2'd0);
  wire       vb0_nxt   = (push_b && !refill) ? 1'b1 :
                         (refill && !push_b) ? vb1  : vb0;
  wire [1:0] occ_nxt   = vb0_nxt ? cntb_nxt : count_nxt;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            free  <= 2'd2;
           hwm   <= 2'd0;
          peak_q <= 2'd0;
         hwm_b    <= 2'd0;
         peak_sel <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
           vb0   <= 1'b0;
           vb1   <= 1'b0;
           cntb  <= 2'd0;
           b0    <= 8'h00;
           b1    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                   d0 <= a_din;
                    v0 <= 1'b1;
                end else begin
                   d1 <= a_din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
               d0 <= a_din;
            end

            count <= count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
            free  <= free  - (do_push ? 2'd1 : 2'd0) + (do_pop ? 2'd1 : 2'd0);

           // the spill stage preserves arrival order: it only takes a word
           // once the head buffer cannot, and it empties into the head first
           if (push_b && !refill) begin
               if (!vb0) begin
                   b0  <= din;
                   vb0 <= 1'b1;
               end else begin
                   b1  <= din;
                   vb1 <= 1'b1;
               end
           end else if (refill && !push_b) begin
               b0  <= b1;
               vb0 <= vb1;
               vb1 <= 1'b0;
           end else if (push_b && refill) begin
               b0 <= din;
           end
           cntb <= cntb + (push_b ? 2'd1 : 2'd0) - (refill ? 2'd1 : 2'd0);

          peak_q <= occ_nxt;
         // the channel select tracks the spill stage: it engages when a word
         // spills and releases when the last spilled word is handed up
         if (push_b)
             peak_sel <= 1'b1;
         else if (refill && cntb == 2'd1)
             peak_sel <= 1'b0;
         if (!peak_sel) begin
             if (peak_q > hwm)
                 hwm <= peak_q;
         end else begin
             if (peak_q > hwm_b)
                 hwm_b <= peak_q;
         end
        end
    end

   assign dout    = v0 ? d0 : {6'b0, ((hwm_b > hwm) ? hwm_b : hwm)};
    assign o_empty = !v0;
    assign o_full   = (free == 2'd0);
    assign o_count  = count;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);

    // ---- property: a push accepted last cycle must have gone into a buffer
    // ---- that both occupancy encodings called non-full
    always @(posedge clk)
        if (pv && $past(push) && !$past(v1))
            assert ($past(free) != 2'd0 && $past(count) != 2'd2);

   // ---- property: a cycle in which the upstream credit register reported no
   // ---- free slots must leave the peak occupancy telemetry pegged at two
   always @(posedge clk)
       if (pv && !$past(rst) && $past(free) == 2'd0)
           assert (hwm == 2'd2);
endmodule

// Tracks outstanding memory requests issued into a 4-deep load/store pipeline.
// A shift register records which pipeline stages hold a live request; a separate
// counter tracks how many are in flight.
module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,   // pipeline advance / clock-enable
    input  wire       req,    // a new request is issued into stage 0
    output wire       f_idle, // no requests outstanding (from the counter)
    output wire       f_full, // all pipeline slots occupied (from the counter)
    output wire       f_any,  // some stage holds a request (from the shifter)
    output wire       f_slot  // some stage is free (from the shifter)
);

    reg [3:0] inflight;
    reg [2:0] cnt;
reg       ireq;                // port-side launch register (req -> issue)
reg [1:0] pend;                // requests held in the two launch registers
reg       issue;                // request launch register (input -> stage 0)
reg [1:0] bcnt;                 // back-half occupancy (stage 3 only)
reg       hand;                 // request in the stage1 -> stage2 handover
reg [3:0] n_in;                 // ledger: requests entering the shifter
reg [3:0] n_out;                // ledger: requests retired out of stage 3

    initial inflight = 4'b0000;
    initial cnt      = 3'd0;
initial ireq     = 1'b0;
initial pend     = 2'd0;
initial issue    = 1'b0;
initial bcnt     = 2'd0;
initial hand     = 1'b0;
initial n_in     = 4'd0;
initial n_out    = 4'd0;

    // the request leaving the last stage completes this cycle
    wire retire = inflight[3];

// outstanding-request accounting.  The ledger counters are written when a
// request crosses into the shifter and when it retires, so their difference
// only covers the four pipeline stages; the requests still waiting in the
// launch registers are carried by the port's own credit counter.  The port
// sums the two parts and refuses a new request once every holding place is
// taken.
wire [3:0] depth  = n_in - n_out;
wire [3:0] total  = depth + {2'b00, pend};
wire       accept = req && (total != 4'd6);

    always @(posedge clk) begin
        if (rst) begin
            inflight <= 4'b0000;
            cnt      <= 3'd0;
ireq     <= 1'b0;
pend     <= 2'd0;
issue    <= 1'b0;
bcnt     <= 2'd0;
hand     <= 1'b0;
n_in     <= 4'd0;
n_out    <= 4'd0;
        end else if (step) begin
// the request bus is double-registered at the pipeline input to cut
// the path from req into stage 0: an accepted request waits two
// advances in the launch registers before it occupies stage 0.  The
// front count picks it up on the second of those advances, and the
// port credit counter holds it until then.
ireq     <= accept;
issue    <= ireq;
inflight <= {inflight[2:0], issue};
// each pipeline half maintains its own occupancy count locally.  The
// stage1 -> stage2 crossing is registered to keep the adder chains
// short: the front count drops the request on the advance that moves
// it out of stage 1, the handover latch carries it, and the back
// count picks it up on the following advance.
cnt      <= cnt  + {2'b00, ireq}          - {2'b00, inflight[1]};
pend     <= pend + {1'b0,  accept}        - {1'b0,  issue};
bcnt     <= bcnt + {1'b0,  hand}          - {1'b0,  retire};
hand     <= inflight[1];
n_in     <= n_in  + {3'b000, issue};
n_out    <= n_out + {3'b000, retire};
        end
    end

assign f_idle = (cnt == 3'd0) && (bcnt == 2'd0) && !hand && (pend == 2'd0);
// six holding places: the two launch registers plus the four stages.  The
// ledger difference plus the port credit is the authoritative count.
assign f_full = (total == 4'd6);
    assign f_any  = |inflight;
    assign f_slot = ~(&inflight);

    // P: the counter-derived flags and the shifter-derived flags may never
    // contradict each other -- idle together with an occupied stage, or
    // full together with a free stage.
    always @(posedge clk) assert (!(f_idle && f_any));
    always @(posedge clk) assert (!(f_full && f_slot));

endmodule

module seq_detect_1011 (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output wire       match,
    output wire [3:0] hits
);
    // fixed pattern, MSB first: 1 0 1 1
    localparam [3:0] PAT = 4'b1011;

    // match-progress register: number of leading pattern bits matched so far,
    // never exceeds the pattern length (4)
    reg [2:0] prog;
    // shadow register: records that progress 3 (pattern prefix 101) was
    // observed at some earlier cycle
    reg       saw_p3;
    // saturating count of completed pattern matches consumed
    reg [3:0] match_count;
   // commit-stage flag: a detected match is posted here and lands in the
   // counter on the next enabled cycle, keeping the counter adder off the
   // detector's critical path
   reg       cmt_vld;
  // second commit stage: the credit takes one more pipeline beat before it
  // reaches the counter, so the full-compare and the counter adder land in
  // separate cycles
  reg       cmt_vld2;

  // sticky saturation lock: if the counter is already topped out when a
  // match credit retires, the credit is dropped and the reading is frozen,
  // so software can tell "exactly 15" from "15 or more"
  reg       sat_lock;
 // census of match credits that retired into an already-locked counter;
 // firmware uses it to bound how far the frozen reading undercounts
 reg [3:0] drop_cnt;
// credit ledger: posted credits and retired credits are tallied on
// separate free-running counters so firmware can read back, by
// subtraction, how many credits are still in flight in the commit stage
reg [3:0] post_cnt;
reg [3:0] rtr_cnt;
// match-window ledger: the opening of a detection window (the scan is
// about to reach full pattern length) and its closing are logged on
// separate free-running counters, so firmware can read back by
// subtraction whether a window is currently parked in the scan register;
// the commit stage sources its credits from this ledger, which keeps the
// posting decision independent of the scan register's own decode
reg [3:0] mw_opn;
reg [3:0] mw_cls;
// saturation full-detect, sampled when the credit is posted so the
// 15-compare sits off the lock path; the lock engages when the armed
// credit retires one enabled cycle later
reg       lock_arm;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;
   initial cmt_vld     = 1'b0;
initial cmt_vld2    = 1'b0;
  initial sat_lock    = 1'b0;
 initial drop_cnt    = 4'd0;
initial post_cnt    = 4'd0;
initial rtr_cnt     = 4'd0;
initial mw_opn      = 4'd0;
initial mw_cls      = 4'd0;
initial lock_arm    = 1'b0;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
    wire       restart  = (din == PAT[3]) ? 1'b1 : 1'b0;
   // overflow park: once the census tops out the scan is frozen so the
   // count, the census and the detector state stay mutually consistent
   wire       park     = (drop_cnt == 4'd15);
// a detection window is parked in the scan register right now
wire       win_open = (mw_opn != mw_cls);
// credits currently outstanding in the commit pipeline, per the ledger
wire [3:0] outst    = post_cnt - rtr_cnt;
// a credit retires when the last commit stage presents it, or when the
// ledger shows more outstanding than the pipeline is holding back
wire       retire   = cmt_vld2 || (outst > {3'b000, cmt_vld});

    assign match = (prog == 3'd4);
    assign hits  = match_count;

    always @(posedge clk) begin
        if (rst) begin
            prog        <= 3'd0;
            saw_p3      <= 1'b0;
            match_count <= 4'd0;
           cmt_vld     <= 1'b0;
cmt_vld2    <= 1'b0;
          sat_lock    <= 1'b0;
         drop_cnt    <= 4'd0;
post_cnt    <= 4'd0;
rtr_cnt     <= 4'd0;
mw_opn      <= 4'd0;
mw_cls      <= 4'd0;
lock_arm    <= 1'b0;
       end else if (ce && !park) begin
            // shadow bit latches the earlier occurrence of progress 3
            saw_p3 <= saw_p3 | (prog == 3'd3);
           // post a credit for a completed match; retire the credit posted
           // by the previous enabled cycle
cmt_vld <= win_open;
cmt_vld2 <= cmt_vld;
// ledger sides: log the posting event and the retiring event
post_cnt <= post_cnt + (win_open ? 4'd1 : 4'd0);
rtr_cnt  <= rtr_cnt  + (retire ? 4'd1 : 4'd0);
// window ledger sides: log the opening and the closing of each window
mw_opn <= mw_opn + (((prog == 3'd3) && (din == exp_bit)) ? 4'd1 : 4'd0);
mw_cls <= mw_cls + ((prog == 3'd4) ? 4'd1 : 4'd0);
// arm the lock together with the credit it belongs to
lock_arm <= cmt_vld && (match_count == 4'd15);
if (retire)
sat_lock <= sat_lock | lock_arm;
if (retire && !sat_lock)
               match_count <= (match_count == 4'd15) ? 4'd15 : match_count + 4'd1;
         // tally the credit we just threw away; the park above guarantees
         // this adder cannot wrap
if (retire && sat_lock)
             drop_cnt <= drop_cnt + 4'd1;


            if (prog == 3'd4) begin
                // consume the completed match, then begin a fresh scan
                prog        <= restart ? 3'd1 : 3'd0;
            end else if (din == exp_bit) begin
                prog <= prog + 3'd1;
            end else begin
                prog <= restart ? 3'd1 : 3'd0;
            end
        end
    end

    // Precedence, global: any counted match must have been preceded by the
    // pattern prefix reaching progress 3.
    assert property (match_count == 4'd0 || saw_p3);

   // Saturation lock is a consequence of counted traffic: it can only engage
   // after the counter has been driven to full, so the exported count is
   // nonzero and the pattern prefix must already have been seen.
   always @(posedge clk)
       assert (!sat_lock || (saw_p3 && hits != 4'd0));
  // Credits are only discarded against a full, locked counter, so any
  // nonzero census means the exported reading is pinned at maximum and the
  // pattern prefix was seen long ago.
  always @(posedge clk)
      assert (drop_cnt == 4'd0 || (saw_p3 && hits == 4'd15));
// Ledger traffic never predates the prefix: a credit parked in the commit
// pipeline, or a detection window parked in the scan register, can only
// exist once the pattern prefix 101 has been observed.
always @(posedge clk)
    assert ((post_cnt == rtr_cnt && mw_opn == mw_cls) || saw_p3);
endmodule

// Histogram accumulator: four bin counters, one sample at a time,
// plus a running total-samples register and a shadow register that
// records the bin-0 count observed at the most recent bin-1 sample.
module histo_precedence (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire [1:0] i_bin,     // which bin the incoming sample lands in
    output wire [5:0] o_total,
output wire [3:0] o_snap,
output reg  [3:0] o_act
);
    // bin counters
    reg [3:0] b0, b1, b2, b3;
    // total samples accumulated
    reg [5:0] total;
    // shadow register: value of bin 0 at the time of the last bin-1 sample
    reg [3:0] snap;
   // snapshot delivery pipeline: the bin-0 population read out alongside a
   // bin-1 sample only reaches the shadow register four cycles later, which
   // matches the read latency of the bin storage array.
   reg [3:0] sn1, sn2, sn3, sn4;
   reg       v1, v2, v3, v4;
reg [3:0] ce_hist;
// snapshot defer buffer: a bin-1 sample that arrives while the readout
// pipeline is still busy parks its bin-0 reading here and replays it when
// the pipeline frees up, so back-to-back bin-1 samples are not lost
reg [3:0] hold;
reg       hold_v;
// snapshot ledger: requests issued vs. snapshots delivered to the shadow
reg [3:0] n_iss, n_ret;
// posted-write buffer for bin 0: the bin-0 counter shares its single array
// port with the snapshot readout, so bin-0 samples that are committed while
// the port is busy are parked here and written back on a free cycle
reg [1:0] b0_pend;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;
   initial sn1   = 4'd0;
   initial sn2   = 4'd0;
   initial sn3   = 4'd0;
   initial sn4   = 4'd0;
   initial v1    = 1'b0;
   initial v2    = 1'b0;
   initial v3    = 1'b0;
   initial v4    = 1'b0;
initial ce_hist = 4'd0;
initial o_act   = 4'd0;
initial hold    = 4'd0;
initial hold_v  = 1'b0;
initial n_iss   = 4'd0;
initial n_ret   = 4'd0;
initial b0_pend = 2'd0;

    // value currently held by the selected bin
    wire [3:0] sel_val = (i_bin == 2'd0) ? b0 :
                         (i_bin == 2'd1) ? b1 :
                         (i_bin == 2'd2) ? b2 : b3;

    // a sample is committed only if the selected bin has headroom
wire [3:0] inflight  = n_iss - n_ret;
wire       pipe_free = !(v1 | v2 | v3 | v4);
// the ledger can carry two outstanding snapshots (one in the readout
// pipeline, one in the defer buffer); a bin-1 sample that would overflow it
// is held off at the input until a slot frees up
wire       snap_full = (inflight == 4'd2);
// bin-0 population as seen by the outside world: committed count plus the
// samples still sitting in the posted-write buffer
wire [4:0] b0_pop    = {1'b0, b0} + {3'd0, b0_pend};
wire       bin0_full = (b0_pop == 5'd15) || (b0_pend == 2'd3);
wire incr = i_ce && !((i_bin == 2'd0) ? bin0_full : (sel_val == 4'd15))
                 && !((i_bin == 2'd1) && snap_full);
wire req  = incr && (i_bin == 2'd1);
// the array port is available for a posted bin-0 write-back only on cycles
// where the snapshot logic is not reading the bin-0 population
wire       wb_free = pipe_free && !hold_v && !req;
wire       b0_push = incr && (i_bin == 2'd0);
wire       b0_wb   = i_ce && wb_free && (b0_pend != 2'd0) && (b0 != 4'd15);

    always @(posedge clk) begin
if (b0_wb)
    b0 <= b0 + 4'd1;
if (i_ce)
    b0_pend <= b0_pend + {1'b0, b0_push} - {1'b0, b0_wb};
        if (incr) begin
            case (i_bin)
2'd0: ; // bin-0 sample is posted into b0_pend above
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
            endcase
            total <= total + 6'd1;
        end
    end
   // Snapshot pipeline: the read data shifts on every enabled cycle and the
   // valid bit travels with it, so the shadow register is loaded four cycles
   // after the bin-1 sample that requested the snapshot.
   always @(posedge clk) begin
       if (i_ce) begin
           sn2 <= sn1;
           v2  <= v1;
           sn3 <= sn2;
           v3  <= v2;
           sn4 <= sn3;
           v4  <= v3;
           if (v4)
               snap <= sn4;
          // stage-1 arbitration: a parked request replays ahead of a new
          // one so the shadow register sees bin-1 samples in order
          if (pipe_free && hold_v) begin
              sn1    <= hold;
              v1     <= 1'b1;
              hold_v <= req;
              if (req)
hold <= b0_pop[3:0];
          end else if (pipe_free && req) begin
sn1 <= b0_pop[3:0];
              v1  <= 1'b1;
          end else begin
              v1 <= 1'b0;
              if (req) begin
hold   <= b0_pop[3:0];
                  hold_v <= 1'b1;
              end
          end
          // ledger: one tick per request issued, one per snapshot delivered
          n_iss <= n_iss + {3'd0, req};
          n_ret <= n_ret + {3'd0, v4};
       end
   end

  // Activity monitor: a shift register of "sample landed in bin 3" flags,
// plus a status readout multiplexer: the current bin index selects which
// ledger / defer-buffer register is presented on o_act.
  always @(posedge clk) begin
      if (i_ce) begin
          ce_hist <= {ce_hist[2:0], (i_bin == 2'd3)};
          case (i_bin)
              2'd0: o_act <= n_iss;
              2'd1: o_act <= n_ret;
              2'd2: o_act <= hold;
              2'd3: o_act <= {hold_v, ce_hist[2:0]};
          endcase
      end
  end

    assign o_total = total;
    assign o_snap  = snap;

    // Property (precedence): whenever a sample is being committed, the
    // bin-0 population recorded earlier in the shadow register must already
    // have been accounted for in the total-samples register.
    always @(posedge clk)
        if (incr)
            assert (total >= {2'b00, snap});

   // Property (snapshot ledger conservation): every outstanding snapshot
   // request corresponds to a bin-1 sample that has already been counted,
   // and the bin-0 reading parked in the defer buffer was taken from a
   // population already counted, so together they can never exceed the
   // running sample total.
   always @(posedge clk)
       assert (total >= {2'b00, hold} + {2'b00, inflight});
endmodule

module disasm_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       kick,      // an instruction was successfully decoded
    output reg  [3:0] count,     // cycles since last kick
    output reg        expired,   // decoder hung: limit was reached
    output reg        healthy    // plenty of slack left
);
    localparam [3:0] LIMIT = 4'd10;   // timeout
    localparam [3:0] WARN  = 4'd8;    // slack threshold

   // saved context of the decode channel that is parked while the other
   // one owns the shared pipeline slot
   reg  [3:0] count_sh;
   reg        exp_sh;
  // second parked context: three decode channels rotate through the one
  // pipeline slot, so two of them are always parked at any time
  reg  [3:0] count_sh2;
  reg        exp_sh2;
 // remaining slack of the channel that currently owns the slot; the
 // timeout now fires on a zero-detect of this countdown instead of a
 // magnitude compare, and it is reloaded whenever the slot changes hands
 reg  [3:0] deadline;
// the decode channel hands its shared operand port to the issue stage for
// one pipeline advance on every successful decode; the port comes back on
// the following advance.  both sides of the loan are logged so the loan
// traffic can be watched from the outside, and the level flag is the
// registered "port is out" condition used by the slack report.
reg  [3:0] n_lend;    // hand-overs to the issue stage (wraps)
reg  [3:0] n_back;    // returns from the issue stage (wraps)
reg        port_out;  // the operand port is out on loan right now
// the issue stage hands the operand port back together with the result of
// the decoded instruction; that result is parked in the one-entry commit
// slot until the commit stage accepts it on the following advance.  both
// sides of the parking are logged so commit traffic is visible outside.
reg  [3:0] n_post;   // results parked in the commit slot (wraps)
reg  [3:0] n_pop;    // results accepted by the commit stage (wraps)
reg        rb_full;  // a result is parked in the commit slot right now

    initial begin
        count   = 4'd0;
        expired = 1'b0;
        healthy = 1'b1;
       count_sh = 4'd0;
       exp_sh   = 1'b0;
      count_sh2 = 4'd0;
      exp_sh2   = 1'b0;
     deadline  = LIMIT;
n_lend    = 4'd0;
n_back    = 4'd0;
port_out  = 1'b0;
n_post    = 4'd0;
n_pop     = 4'd0;
rb_full   = 1'b0;
    end

    // next value of the stall counter: kick clears it, otherwise it
    // counts up and saturates at the timeout limit
    wire [3:0] nxt = kick              ? 4'd0  :
                     (count == LIMIT)  ? LIMIT :
                                         count + 4'd1;

   // the slot is handed to the other channel when the active one makes
   // progress, and is preempted once the active one has clearly hung
// a preemption is deferred while a result is still parked for commit,
// because rotating the slot would orphan the parked result
wire swap = kick || (count == LIMIT && !rb_full);

  // the channel holding the slot has just run out of slack
  wire hung = !kick && (deadline <= 4'd1);

// a decode hands the port over unless it is already out; the return
// ledger chases the hand-over ledger, so the port comes back on the next
// advance after it was taken
wire       lend      = !port_out && kick;
wire       back      = (n_lend != n_back);
wire [3:0] n_lend_nx = n_lend + (lend ? 4'd1 : 4'd0);
wire [3:0] n_back_nx = n_back + (back ? 4'd1 : 4'd0);
wire       port_nx   = lend || (port_out && !back);
// the commit slot takes the result on the advance the port comes back and
// the commit stage drains it on the advance after that
wire       rb_take   = back;
wire       rb_free   = (n_post != n_pop);
wire       rb_nx     = rb_take || (rb_full && !rb_free);
wire [3:0] n_post_nx = n_post + (rb_take ? 4'd1 : 4'd0);
wire [3:0] n_pop_nx  = n_pop  + (rb_free ? 4'd1 : 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            count   <= 4'd0;
           count_sh <= 4'd0;
           exp_sh   <= 1'b0;
           count_sh2 <= 4'd0;
           exp_sh2   <= 1'b0;
          deadline  <= LIMIT;
n_lend    <= 4'd0;
n_back    <= 4'd0;
port_out  <= 1'b0;
n_post    <= 4'd0;
n_pop     <= 4'd0;
rb_full   <= 1'b0;
            expired <= 1'b0;
            healthy <= 1'b1;
        end else if (i_ce) begin
           if (swap) begin
               count    <= count_sh;         // resume the parked channel
              deadline <= LIMIT - count_sh; // slack left for the resumed channel
count_sh  <= count_sh2;        // rotate the parked queue forward
count_sh2 <= nxt;              // park the current stall count
exp_sh    <= exp_sh2;          // its hang flag rotates with it
exp_sh2   <= hung;             // remember if it hung
           end else begin
               count    <= nxt;
              deadline <= (deadline == 4'd0) ? 4'd0 : deadline - 4'd1;
           end
// the loan ledgers are free running and wrap at four bits; nothing but
// the flag tracks how many loans are outstanding
if (lend) n_lend <= n_lend + 4'd1;
if (back) n_back <= n_back + 4'd1;
port_out <= port_nx;
// the commit ledgers are free running and wrap at four bits
n_post   <= n_post_nx;
n_pop    <= n_pop_nx;
rb_full  <= rb_nx;
           // sticky per channel: a kick only clears the channel that
           // currently owns the slot
// the hang detector reads the ledgers directly: a hand-over that is
// still unmatched means the issue stage never took the operands
// and a result that is still parked for commit stalls the channel too
expired <= hung || exp_sh || exp_sh2 || (n_lend_nx != n_back_nx) || rb_nx;
// the slack report is built from the registered port flag
healthy <= (nxt < WARN) && (count_sh < WARN) && (count_sh2 < WARN) && !port_nx
           && (n_post_nx == n_pop_nx);
        end
    end

    // P: the timeout flag and the slack flag are never raised together
    always @(posedge clk)
        if (expired)
            assert (!healthy);
endmodule

// Gray-coded write pointer crossing into a destination domain through a
// two-flop synchronizer, with a shadow binary pipeline kept alongside the
// synchronizer stages and a monitor that records the Hamming distance between
// the two most recent samples of the pointer.
module gray_cdc_skew_monitor (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable / idle
    input  wire       i_incr,    // source pointer advance
    output reg        armed,     // sticky: a pointer change has been observed
output reg  [2:0] last_delta, // bits differing between the last two samples
output reg  [3:0] o_idle_count // distractor: destination-domain activity meter
);

    // source-domain binary pointer and its gray encoding
    reg  [3:0] wbin;

   // Four-deep source-domain retiming pipeline.  The pointer counter sits at
   // the far end of the block from the launch flops, so the binary pointer is
   // carried over in four registered hops; the gray encoder is placed at the
   // last hop so both synchronizer chains launch from the same retimed value.
   reg  [3:0] p1, p2, p3, p4;
   wire [3:0] pgray = p4 ^ (p4 >> 1);

    // two-flop synchronizer carrying the gray pointer
    reg  [3:0] sync1, sync2;

   // second consumer's synchronizer chain onto the same gray pointer
   reg  [3:0] s1b, s2b;

    // shadow binary pipeline, one stage per synchronizer flop
    reg  [3:0] b1, b2;
   reg  [3:0] b1b, b2b;

   // round-robin refresh phase: 0 refreshes chain A, 1 refreshes chain B.
// Advances are no longer pinned to a phase: the issue/retire ledger below
// keeps at most one advance outstanding, which is what bounds either chain
// to a single gray transition between two of its own samples.
   reg        phase;
  // Programmable pointer depth.  The wrap modulus is carried as a mask that
  // is always one less than a power of two; it is widened one bit at a time
  // by i_incr pulses while the destination domain is parked (i_ce low).
  // Moving the wrap point invalidates everything already in flight, so a
  // depth change also drains the pointer and both synchronizer shadows.
  reg  [3:0] wrap_mask;

 // Issue/retire ledger for pointer advances.  n_issue logs advances pushed
 // into the source pointer, n_retire logs advances absorbed by the chain-A
 // shadow stage.  Both are plain free-running event counters that wrap at
 // four bits; only their difference is meaningful.
 reg  [3:0] n_issue;
 reg  [3:0] n_retire;

// Distractor bookkeeping: counts accepted advance pulses and bleeds down
// while the destination domain is parked.  Purely observational.
reg  [3:0] idle_count;

    initial begin
        wbin       = 4'd0;
       p1         = 4'd0;
       p2         = 4'd0;
       p3         = 4'd0;
       p4         = 4'd0;
        sync1      = 4'd0;
        sync2      = 4'd0;
        b1         = 4'd0;
        b2         = 4'd0;
       s1b        = 4'd0;
       s2b        = 4'd0;
       b1b        = 4'd0;
       b2b        = 4'd0;
       phase      = 1'b0;
      wrap_mask  = 4'd1;
     n_issue    = 4'd0;
     n_retire   = 4'd0;
idle_count = 4'd0;
o_idle_count = 4'd0;
        armed      = 1'b0;
        last_delta = 3'd0;
    end

    // combinational Hamming distance between the two synchronizer stages
    wire [3:0] xr = sync1 ^ sync2;
    wire [2:0] delta = {2'b00, xr[0]} + {2'b00, xr[1]} +
                       {2'b00, xr[2]} + {2'b00, xr[3]};

   // the same distance measure for the second chain
   wire [3:0] xrb = s1b ^ s2b;
   wire [2:0] delta_b = {2'b00, xrb[0]} + {2'b00, xrb[1]} +
                        {2'b00, xrb[2]} + {2'b00, xrb[3]};

   // one skew monitor is shared by both chains; it reports whichever chain
   // was refreshed on this phase
   wire [2:0] delta_mux = phase ? delta_b : delta;
   wire       skew_mux  = phase ? (s1b != s2b) : (sync1 != sync2);
  // depth reconfiguration is only accepted while the destination domain is
  // idle, and only up to the full four-bit pointer range
  wire       cfg_widen = !i_ce && i_incr && (wrap_mask != 4'd15);
 // credit-style interlock: a fresh advance is only issued once the previous
 // one has been retired by the shadow stage
 wire       ledger_busy = (n_issue != n_retire);
 wire       ptr_adv     = i_ce && i_incr && !ledger_busy;
// an advance retires once it has cleared the last retiming hop and is
// therefore visible to whichever chain refreshes next
wire       shadow_adv  = i_ce && (p3 != p4);

    always @(posedge clk) begin
       if (cfg_widen) begin
           // new wrap point: grow the mask and drain the pointer pipeline
           wrap_mask <= (wrap_mask << 1) | 4'd1;
           wbin      <= 4'd0;
          p1        <= 4'd0;
          p2        <= 4'd0;
          p3        <= 4'd0;
          p4        <= 4'd0;
           sync1     <= 4'd0;
           sync2     <= 4'd0;
           b1        <= 4'd0;
           b2        <= 4'd0;
           s1b       <= 4'd0;
           s2b       <= 4'd0;
           b1b       <= 4'd0;
           b2b       <= 4'd0;
          n_issue   <= 4'd0;
          n_retire  <= 4'd0;
       end else if (i_ce) begin
            // source pointer
         wbin  <= (wbin + (ptr_adv ? 4'd1 : 4'd0)) & wrap_mask;

           // retiming hops toward the launch point
           p1 <= wbin;
           p2 <= p1;
           p3 <= p2;
           p4 <= p3;

           // ledger: log both sides of the advance
         n_issue  <= n_issue  + (ptr_adv    ? 4'd1 : 4'd0);
         n_retire <= n_retire + (shadow_adv ? 4'd1 : 4'd0);

            // synchronizer chain
           if (!phase) begin
              sync1 <= pgray;
               sync2 <= sync1;
           end else begin
              s1b   <= pgray;
               s2b   <= s1b;
           end

            // shadow binary chain, structurally parallel to the chain above
           if (!phase) begin
              b1    <= p4;
               b2    <= b1;
           end else begin
              b1b   <= p4;
               b2b   <= b1b;
           end

            // monitor
           last_delta <= delta_mux;
           phase      <= ~phase;

            // Q: first time the two stages disagree, i.e. a pointer update is
            // in flight through the synchronizer.  Sticky, never cleared.
          if (skew_mux || ledger_busy)
                armed <= 1'b1;
        end
    end

   // ---- distractor: activity meter, independent of the pointer pipeline ----
   always @(posedge clk) begin
       if (i_ce && i_incr) begin
           if (idle_count != 4'd15)
               idle_count <= idle_count + 4'd1;
       end else if (!i_ce && idle_count != 4'd0) begin
           idle_count <= idle_count - 4'd1;
       end
       o_idle_count <= idle_count;
   end

    // P: once a pointer change has been seen, every recorded sample-to-sample
    // distance is at most one bit (gray-code single-bit transition).
    assert property (!armed || last_delta <= 3'd1);

endmodule

module elastic_profile_buf (
    input wire       i_clk,
    input wire       i_rst,
    input wire       i_push,
    input wire       i_pop,
    input wire [7:0] i_data,
    output wire      o_valid,
    output wire      o_full,
    output wire [7:0] o_data,
output wire [2:0] o_count,
output reg [3:0] o_push_tally
);
    // Two-entry elastic buffer holding profiling samples.
    // Entry 0 is the head, entry 1 is the tail.  v0/v1 are the head/tail
    // occupancy flags; count is a separate occupancy register that is
    // maintained in parallel with the flags.
    reg       v0, v1;
    reg [7:0] d0, d1;
    reg [2:0] count;
   // Skid slot behind the tail.  o_full is raised as soon as the tail fills,
   // but one upstream beat may already be in flight, so it is absorbed here
   // and handed to the tail as soon as a pop frees it.
   reg       s_v;
   reg [7:0] s_d;
  // A second skid slot behind the first, so two beats that were already in
  // flight when full was reported can both be absorbed.  Both slots are
  // accounted for by the shared skid occupancy counter below.
  reg       s2_v;
  reg [7:0] s2_d;
  // occupancy contributed by the skid slot, held apart from the core count
  reg [1:0] skid_occ;
 // the occupancy adder is retimed off the push path: a beat that has just
 // been written into a core slot has its unit of occupancy parked in
 // inc_pend for one cycle and is folded into count on the next edge
 reg       inc_pend;
// the skid-to-core hand-off is retimed the same way: the occupancy that
// leaves the skid counter on a drain is parked here for one cycle before it
// is folded into count
reg [1:0] xfer_pend;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;
   initial s_v   = 1'b0;
   initial s_d   = 8'h00;
  initial s2_v  = 1'b0;
  initial s2_d  = 8'h00;
  initial skid_occ = 2'd0;
 initial inc_pend = 1'b0;
initial xfer_pend = 2'd0;
initial o_push_tally = 4'd0;

    // "full" is decided purely by the tail flag
    wire w_full  = v1;
    wire do_push = i_push && !w_full;
    wire do_pop  = i_pop  && v0;
   // a beat arriving while full is taken by the skid slot, unless a pop is
   // freeing the tail this cycle, in which case it goes straight to the tail
   wire do_skid = i_push && w_full && !s_v && !do_pop;
  // with the first slot already parked, the next beat queues behind it
  wire do_skid2 = i_push && w_full && s_v && !s2_v && !do_pop;
  // a beat takes a core slot this cycle; its increment is deferred one edge
  wire core_join  = do_push || (do_pop && !s_v && i_push);
  // the head always vacates on a pop; that decrement is taken immediately
  wire core_leave = do_pop;
// on a drain the skid keeps only the slot that slides forward; the
// difference is the occupancy share migrating towards the core count
wire [1:0] skid_drain = (do_pop && s_v) ? (skid_occ - {1'b0, s2_v}) : 2'd0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
           s_v   <= 1'b0;
           s_d   <= 8'h00;
          s2_v  <= 1'b0;
          s2_d  <= 8'h00;
          skid_occ <= 2'd0;
         inc_pend <= 1'b0;
        xfer_pend <= 2'd0;
o_push_tally <= 4'd0;
        end else if (do_push && do_pop) begin
            // head leaves, new sample becomes the head: occupancy unchanged
            d0    <= i_data;
        end else if (do_push) begin
            if (!v0) begin
                v0 <= 1'b1;
                d0 <= i_data;
            end else begin
                v1 <= 1'b1;
                d1 <= i_data;
            end
        end else if (do_pop) begin
            // tail slides down into the head slot
           v0 <= v1;
           d0 <= d1;
           if (s_v) begin
               // the parked skid sample takes the freed tail slot
               v1    <= 1'b1;
               d1    <= s_d;
              s_v   <= s2_v;
              s_d   <= s2_d;
              s2_v  <= 1'b0;
             // the skid loses one unit of occupancy here; it reaches count
             // one edge later through xfer_pend
             skid_occ <= {1'b0, s2_v};
           end else if (i_push) begin
               // we reported full, so this beat lands in the freed tail
               v1 <= 1'b1;
               d1 <= i_data;
           end else begin
               v1    <= 1'b0;
           end
       end else if (do_skid) begin
           s_v   <= 1'b1;
           s_d   <= i_data;
          skid_occ <= skid_occ + 2'd1;
      end else if (do_skid2) begin
          s2_v  <= 1'b1;
          s2_d  <= i_data;
         skid_occ <= skid_occ + 2'd1;
      end
        // i_push = i_pop = 0 : the buffer idles, all state held
       if (!i_rst) begin
          count     <= count + {2'b00, inc_pend} - {2'b00, core_leave} + {1'b0, xfer_pend};
           inc_pend <= core_join;
          xfer_pend <= skid_drain;
       end
if (!i_rst && do_push)
    o_push_tally <= o_push_tally + 4'd1;
    end

    assign o_valid = v0;
    assign o_full  = w_full;
    assign o_data  = d0;
 assign o_count = count + {1'b0, skid_occ} + {2'b00, inc_pend} + {1'b0, xfer_pend};

    // P: whenever the buffer is not reporting full, the recorded occupancy
    // is at most one sample (the 3-bit register would allow up to 7).
    always @(posedge i_clk)
        if (!w_full)
            assert (count <= 3'd1);
endmodule

module wdt_absence (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       arm,       // Q: opens the window
    input  wire       disarm,    // R: closes the window (may never arrive)
    input  wire       kick,      // pet the watchdog
    output reg  [3:0] cnt,
    output reg        expired,
    output reg        safe,
output reg        armed,
output reg [3:0] kick_cnt,
output reg [3:0] disarm_cnt
);
    localparam [3:0] LIMIT = 4'd10;  // timeout value
    localparam [3:0] WARN  = 4'd8;   // below this the timer is in the safe zone
    localparam [1:0] GRACE = LIMIT - WARN;  // warning-zone dwell before timeout
    reg [1:0] grace;                        // ticks elapsed since cnt hit WARN
reg [3:0] evt_shift;
localparam [3:0] STAGE = 4'd4;          // half of the pre-warning interval
reg [3:0] stage2;                       // pre-warning ticks past the halfway mark
localparam [3:0] B_LIMIT = 4'd3;        // backup trip point, in prescaled units
reg [1:0] b_tick;                       // /4 prescaler of the backup watchdog
reg [3:0] b_cnt;                        // prescaled ticks since the last kick
reg       hard;                         // backup watchdog has tripped

    initial cnt     = 4'd0;
    initial expired = 1'b0;
    initial safe    = 1'b1;
    initial armed   = 1'b0;
    initial grace   = 2'd0;
initial kick_cnt = 4'd0;
initial disarm_cnt = 4'd0;
initial evt_shift = 4'd0;
initial stage2 = 4'd0;
initial b_tick = 2'd0;
initial b_cnt  = 4'd0;
initial hard   = 1'b0;

    always @(posedge clk) begin
        if (i_ce) begin
// bookkeeping only: how many kicks have been seen
if (kick)
kick_cnt <= kick_cnt + 4'd1;
evt_shift <= {evt_shift[2:0], disarm};
if (disarm && !arm)
disarm_cnt <= disarm_cnt + 4'd1 + {3'd0, evt_shift[3]};
            // window register: set by arm, cleared by disarm
            if (arm)
                armed <= 1'b1;
            else if (disarm)
                armed <= 1'b0;

            // the watchdog only runs inside the window
            if (armed) begin
                if (kick) begin
                    cnt     <= 4'd0;
stage2  <= 4'd0;
                    grace   <= 2'd0;
                    expired <= 1'b0;
                    safe    <= 1'b1;
end else if (cnt < STAGE) begin
// first half of the pre-warning interval is held in cnt
                    cnt     <= cnt + 4'd1;
end else if (stage2 < STAGE) begin
// cnt is frozen at the halfway mark and the rest of the
// pre-warning interval accumulates here, so the two halves
// can be reported separately
stage2  <= stage2 + 4'd1;
safe    <= ((stage2 + 4'd1) < STAGE);
                end else if (grace < GRACE) begin
// once both halves are full the remaining ticks before the
                    // timeout are accumulated here, so the warning-zone dwell
                    // can be reported on its own
                    grace   <= grace + 2'd1;
                    expired <= ((grace + 2'd1) == GRACE);
                    safe    <= 1'b0;
                end
            end

           // backup watchdog: same window and same kick, but clocked at a
           // quarter rate so it trips after the primary one; when it trips it
           // latches the expiry flag so the fault cannot be missed
           if (armed) begin
               if (kick) begin
                   b_tick <= 2'd0;
                   b_cnt  <= 4'd0;
                   hard   <= 1'b0;
               end else if (!hard) begin
                   if (b_tick == 2'd3) begin
                       b_tick <= 2'd0;
                       b_cnt  <= b_cnt + 4'd1;
                       if ((b_cnt + 4'd1) == B_LIMIT) begin
                           hard    <= 1'b1;
                           expired <= 1'b1;
                       end
                   end else begin
                       b_tick <= b_tick + 2'd1;
                   end
               end else begin
                   expired <= 1'b1;
               end
           end
        end
    end

    // P: once armed (and until disarmed, if ever), the timer can never report
    // both "expired" and "safe" at the same time.
    always @(*)
        if (armed)
            assert (!(expired && safe));
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
output wire       o_settled, // no sample in flight
output reg  [3:0] o_act      // beat-activity tally, observation only
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
   // launch flop on the gray encoder: the crossing wires are driven
   // point to point instead of straight off the encoder cone
   reg [3:0] gq;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;
   // programmable ring bound: the bridge starts at quarter span after reset and
   // opens up one binary step per four completed laps
   reg [3:0] lim;
   reg [1:0] laps;
  // read-side pointer of the same ring: one data word takes two destination
  // beats, so it advances on alternate enables.  it shares the programmable
  // ring bound with the write pointer.
  reg [3:0] cnt2;
  reg [3:0] g2;
  reg       ph;
 // completion pointer of the same ring: the consumer retires a word on the
 // opposite half beat, so this one steps when the read phase is low.  it uses
 // the same programmable ring bound as the write and read pointers.
 reg [3:0] cnt3;
 reg [3:0] g3;
 // the crossing lane is a single physical 4-bit bundle, so the three pointers
 // take turns on it under a one-hot grant that rotates.  the turn is handed
 // over only at the common origin, where every encoder reads zero and the
 // lane sees no step on the bundle.
 reg [2:0] own;
reg [3:0] act;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
       gq  = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
       lim  = 4'd3;
       laps = 2'd0;
      cnt2 = 4'd0;
      g2   = 4'd0;
      ph   = 1'b0;
     cnt3 = 4'd0;
     g3   = 4'd0;
     own  = 3'b001;
act   = 4'd0;
o_act = 4'd0;
    end

   wire       wrap     = (cnt >= lim);
   wire [3:0] nxt      = wrap ? 4'd0 : cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);
  wire       wrap2      = (cnt2 >= lim);
  wire [3:0] nxt2       = wrap2 ? 4'd0 : cnt2 + 4'd1;
  wire [3:0] nxt_gray2  = nxt2 ^ (nxt2 >> 1);
  wire       tick2      = ph;
 wire       wrap3      = (cnt3 >= lim);
 wire [3:0] nxt3       = wrap3 ? 4'd0 : cnt3 + 4'd1;
 wire [3:0] nxt_gray3  = nxt3 ^ (nxt3 >> 1);
 wire       tick3      = ~ph;
 wire       swap       = (cnt == 4'd0) && (cnt2 == 4'd0) && (cnt3 == 4'd0);
 // one-hot grant onto the shared bundle: each encoder is masked by its grant
 // bit and the three masked copies are or-ed onto the lane
 wire [3:0] lane       = (own[0] ? g : 4'd0) | (own[1] ? g2 : 4'd0) | (own[2] ? g3 : 4'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
          gq  <= lane;
           s1  <= gq;
            s2  <= s1;
          ph  <= ~ph;
          if (tick2) begin
              cnt2 <= nxt2;
              g2   <= nxt_gray2;
          end
         if (tick3) begin
             cnt3 <= nxt3;
             g3   <= nxt_gray3;
         end
          if (swap)
             own <= {own[1:0], own[2]};
           if (wrap) begin
               laps <= laps + 2'd1;
               if (laps == 2'd3)
                   lim <= {lim[2:0], 1'b1};
           end
act   <= act + 4'd1;
o_act <= act ^ {3'b000, ph};
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
   assign o_settled = (diff == 4'd0) && (gq == s1);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module fsm_phase_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_start,
    output wire [4:0] o_phase,
    output wire       o_busy
);
    // binary-encoded FSM: only 0..4 are legal encodings, 5..7 are unreachable
    localparam [2:0] S_IDLE   = 3'd0,
                     S_FETCH  = 3'd1,
                     S_DECODE = 3'd2,
                     S_EXEC   = 3'd3,
                     S_WRITE  = 3'd4;

    reg [2:0] state;
    reg [4:0] dec;   // shadow one-hot decode of state
   reg [4:0] dec_s; // decode stage register, one pipeline step ahead of dec
    reg       win;   // window register: opened by a job start, closed at retire
   reg       tail;  // retire stage: carries the window over the write-back phase
  reg [2:0] age;   // phase age of the job in flight: 1 at launch, 5 at retire
 reg       rjob;   // the job in flight belongs to the refresh channel
 reg [3:0] rtimer; // refresh interval countdown, one tick per enabled cycle

    initial state = S_IDLE;
    initial dec   = 5'b00001;
   initial dec_s = 5'b00001;
    initial win   = 1'b0;
   initial tail  = 1'b0;
  initial age   = 3'd0;
 initial rjob   = 1'b0;
 initial rtimer = 4'd15;

 // the refresh channel asks for the pipe once its interval has expired
 wire rreq = (rtimer == 4'd0);

    reg [2:0] nstate;
    always @(*) begin
        case (state)
           S_IDLE:   nstate = (i_start || rreq) ? S_FETCH : S_IDLE;
            S_FETCH:  nstate = S_DECODE;
            S_DECODE: nstate = S_EXEC;
           S_EXEC:   nstate = rjob ? S_IDLE : S_WRITE;  // refresh has no write-back
            S_WRITE:  nstate = S_IDLE;
            default:  nstate = 3'd5;   // illegal-encoding trap, never taken
        endcase
    end

    // one-hot decode of the next state; illegal encodings decode to all-zero
    wire [4:0] ndec = (nstate == S_IDLE)   ? 5'b00001 :
                      (nstate == S_FETCH)  ? 5'b00010 :
                      (nstate == S_DECODE) ? 5'b00100 :
                      (nstate == S_EXEC)   ? 5'b01000 :
                      (nstate == S_WRITE)  ? 5'b10000 : 5'b00000;

   // phase code shown on o_phase during the last cycle a job owns the pipe:
   // refresh jobs retire out of EXEC, normal jobs out of WRITE
   wire [4:0] retdec = rjob ? 5'b01000 : 5'b10000;

    always @(posedge i_clk) begin
        if (i_rst) begin
            state <= S_IDLE;
            dec   <= 5'b00001;
           dec_s <= 5'b00001;
            win   <= 1'b0;
           tail  <= 1'b0;
          age   <= 3'd0;
           rjob   <= 1'b0;
           rtimer <= 4'd15;
        end else if (i_ce) begin
            state <= nstate;
           dec_s <= ndec;      // decode is registered here ...
           dec   <= dec_s;     // ... and presented on o_phase one cycle later
           if ((state == S_IDLE) && (i_start || rreq))
                win <= 1'b1;               // Q: a job is launched
           else if (tail)             // the retire stage owns the window now
                win <= 1'b0;               // R: the job retires

           // hand the window over once DECODE reaches o_phase, so the retire
           // stage covers the final write-back cycle on its own
           if (dec == 5'b00100)
               tail <= 1'b1;
          else if (dec == retdec)
               tail <= 1'b0;

          // age the job one phase per enabled cycle: the launch cycle seeds
          // the counter and the retiring write-back cycle clears it again
         if ((state == S_IDLE) && (i_start || rreq))
              age <= 3'd1;
         else if (dec == retdec)
              age <= 3'd0;
          else if (win || tail)
              age <= age + 3'd1;

         // the refresh engine is a peer client of the same phase pipeline:
         // an explicit start always wins the idle slot, a due refresh takes
         // whatever idle slot is left over
         if ((state == S_IDLE) && i_start)
             rjob <= 1'b0;
         else if ((state == S_IDLE) && rreq)
             rjob <= 1'b1;
         else if (dec == retdec)
             rjob <= 1'b0;

         // restart the interval only when the refresh channel is granted
         if ((state == S_IDLE) && !i_start && rreq)
             rtimer <= 4'd15;
         else if (rtimer != 4'd0)
             rtimer <= rtimer - 4'd1;
        end
    end

    assign o_phase = dec;
  assign o_busy  = win | tail | (|age);  // busy while a job still has an age

    // P: inside the job window the phase decode always names some phase
    always @(posedge i_clk)
        assert (!win || (|dec));

   // P2: a busy job showing phase 0 on o_phase is the launch cycle, so the
   // decode stage must already be carrying the FETCH phase behind it
   always @(posedge i_clk)
       assert (!win || (dec != 5'b00001) || (dec_s == 5'b00010));

  // P3: the retire stage only ever holds the window at the tail of a job, so
  // that job has aged at least four phases and o_phase has left the idle slot
  always @(posedge i_clk)
      assert (!tail || ((dec != 5'b00001) && (age >= 3'd4)));
endmodule

// In-flight tracker for a fixed-latency chart-query render pipeline.
// Each issued query walks a 4-stage valid shift register; occupancy is the
// number of ones currently resident in that shift register.
module query_pipe_tracker (
    input  wire       clk,
    input  wire       ce,        // pipeline advance / idle control
    input  wire       issue,     // a new query is pushed into stage 0
    output wire       retire,    // a rendered result leaves the last stage
    output wire       full,      // tracker says all 4 slots are busy
output reg  [2:0] occ,       // queries in flight
output reg  [3:0] retire_cnt // rolling count of retired queries
);

    reg [3:0] pipe;              // fixed-latency valid shift register
   reg [1:0] apipe;             // 2-stage cached-result render path
reg       stg;               // entry stage: admitted query registered before stage 0
    reg       hold;              // input capture slot: query admitted while stalled
    reg       ever_issued;       // shadow: an issue has been observed earlier
    reg       armed;             // scope: still before the pipe was ever full
reg       retire_seen;        // sticky: at least one retirement observed

    initial begin
        pipe        = 4'b0000;
        occ         = 3'd0;
        ever_issued = 1'b0;
        armed       = 1'b1;
        hold        = 1'b0;
       apipe       = 2'b00;
stg         = 1'b0;
retire_cnt  = 4'd0;
retire_seen = 1'b0;
    end

   assign retire = pipe[3] || apipe[1];
    assign full   = (occ == 3'd4);

    // Admission control: the tracker backpressures at capacity, and a query
    // taken while the pipe is not advancing waits in the capture slot.
    wire room   = (occ != 3'd4);
    wire accept = issue && !hold && room;   // query admitted this cycle
    wire inject = hold || accept;           // entry pushed into stage 0
   // A query offered while the capture slot is still busy is served from the
   // result cache instead: shorter path, same 4-slot occupancy budget.
   wire aux_accept = ce && issue && hold && room;

    always @(posedge clk) begin
        if (ce) begin
            // drain: stage 3 retires, everything shifts, stage 0 takes issue
pipe <= {pipe[2:0], stg};
stg  <= inject;

            // occupancy bookkeeping: +1 on issue, -1 on retire
           occ  <= occ + {2'b00, accept} + {2'b00, aux_accept}
                       - {2'b00, pipe[3]} - {2'b00, apipe[1]};
           apipe <= {apipe[0], aux_accept};
            hold <= 1'b0;

            // shadow register for the earlier event
           if (accept || aux_accept) ever_issued <= 1'b1;

            // scope closes the first time the unit reports saturation
            if (full)  armed <= 1'b0;
        end else if (accept) begin
            // stalled: park the admitted query and count it as in flight
            hold        <= 1'b1;
            occ         <= occ + 3'd1;
            ever_issued <= 1'b1;
        end
    end

    // Precedence, before the unit was ever full:
    // if work is in flight now, an issue must have happened earlier.
    always @(posedge clk)
        if (armed && occ != 3'd0)
            assert (ever_issued);

// Distractor telemetry: counts retirements, observed by nothing else.
always @(posedge clk) begin
   if (ce && retire) begin
        retire_seen <= 1'b1;
        retire_cnt  <= retire_cnt + (retire_seen ? 4'd2 : 4'd1);
    end
end

   // Telemetry consistency: the retirement counter can only have left zero
   // if something was rendered, and nothing can be rendered before an issue.
   always @(posedge clk)
       assert (retire_cnt == 4'd0 || ever_issued);

endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
    output wire [2:0] o_inflight
);
// fixed-latency (6 cycle) pipeline occupancy shift register
reg [5:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;
// remaining issue credits: an op is only taken while credits are left
reg [2:0] cred;
// currently programmed outstanding-op limit, retuned at each quiesce point
reg [2:0] lim;
// congestion flag: enable dropped while work was still in flight
reg       thr;
// credit-return path: a retired op's credit takes four more cycles to walk
// back from the pipe tail to the issue-side credit counter
reg       rq0;
reg       rq1;
reg       rq2;
reg       rq3;
// returned credits wait here until the credit counter's write port is free
reg [2:0] rtn;
// merge stage: a credit leaving the park register spends one cycle in this
// flop before it is written into the issue-side credit counter
reg       mrg;
// retiming stages: the route from the merge flop back across to the
// issue-side credit counter is long, so a merged credit walks four more
// flops before it is actually added into cred
reg       mg0;
reg       mg1;
reg       mg2;
reg       mg3;

initial pipe     = 6'b000000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;
initial cred     = 3'd4;
initial lim      = 3'd4;
initial thr      = 1'b0;
initial rq0      = 1'b0;
initial rq1      = 1'b0;
initial rq2      = 1'b0;
initial rq3      = 1'b0;
initial rtn      = 3'd0;
initial mrg      = 1'b0;
initial mg0      = 1'b0;
initial mg1      = 1'b0;
initial mg2      = 1'b0;
initial mg3      = 1'b0;

wire retire  = pipe[5];
// credit gate on the issue path
wire accept  = issue && (cred != 3'd0);
// nothing still travelling back down the credit-return path
wire rq_empty = !(rq0 || rq1 || rq2 || rq3);
// at most one parked credit is merged back per cycle, and only on cycles
// where the issue side is not already updating the credit counter
wire drain = (rtn != 3'd0) && !accept;
// true quiesce: pipe drained, returns landed, nothing arriving this cycle
wire quiesce = (pipe == 6'b000000) && rq_empty && !issue;

    always @(posedge clk) begin
        if (rst) begin
pipe     <= 6'b000000;
            inflight <= 3'd0;
        end else if (i_ce) begin
pipe     <= {pipe[4:0], accept};
inflight <= inflight + {2'b00, accept} - {2'b00, retire};
        end
    end
// credit accounting and outstanding-limit retuning
always @(posedge clk) begin
    if (rst) begin
        cred <= 3'd4;
        lim  <= 3'd4;
        thr  <= 1'b0;
        rtn  <= 3'd0;
mrg  <= 1'b0;
mg0  <= 1'b0;
mg1  <= 1'b0;
mg2  <= 1'b0;
mg3  <= 1'b0;
    end else if (i_ce) begin
        if (quiesce) begin
            lim  <= thr ? 3'd2 : 3'd4;
            cred <= thr ? 3'd2 : 3'd4;
            thr  <= 1'b0;
            rtn  <= 3'd0;
mrg  <= 1'b0;
mg0  <= 1'b0;
mg1  <= 1'b0;
mg2  <= 1'b0;
mg3  <= 1'b0;
        end else begin
cred <= cred - {2'b00, accept} + {2'b00, mg3};
            rtn  <= rtn + {2'b00, rq3} - {2'b00, drain};
mrg  <= drain;
mg0  <= mrg;
mg1  <= mg0;
mg2  <= mg1;
mg3  <= mg2;
        end
    end else if (pipe != 6'b000000) begin
        thr  <= 1'b1;
    end
end

// credit-return path: retire pulses shift back toward the issue side
always @(posedge clk) begin
    if (rst) begin
        rq0 <= 1'b0;
        rq1 <= 1'b0;
        rq2 <= 1'b0;
        rq3 <= 1'b0;
    end else if (i_ce) begin
        rq0 <= retire;
        rq1 <= rq0;
        rq2 <= rq1;
        rq3 <= rq2;
    end
end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
output wire       g_holdoff,
output reg  [3:0] o_dbg_count
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;
   // ---- promotion transit register (skid -> main is now a two-cycle path) ----
   reg        pr_v;     // a promoted record is in flight toward the main slot
   reg [7:0]  pr_cred;
   reg [1:0]  t_occ;    // occupancy of the transit register

// ---- per-slot occupancy accounting, kept in parallel with the valid bits ----
    reg [1:0]  occ;
   reg [1:0]  p_occ;   // priority-class share of the main slot (i_cred[7] set)
reg [1:0]  s_occ;
// ---- configured stage depth and free-slot accounting ----
reg [1:0]  cap;    // programmed depth: 1 (main only) or 2 (main + skid)
reg [2:0]  free;   // slots still available = cap - records resident

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;
reg  [3:0] dbg_prev;

    initial begin
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
       pr_v    = 1'b0;
       pr_cred = 8'h00;
       t_occ   = 2'd0;
        occ     = 2'd0;
       p_occ   = 2'd0;
s_occ   = 2'd0;
cap     = 2'd2;
free    = 3'd2;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
o_dbg_count = 4'd0;
dbg_prev    = 4'd0;
    end

wire       skid_free  = (free != 3'd0);
// the parked record leaves the skid slot for the transit register
wire       promote    = i_ce && m_valid && i_ready && hold;
wire       load_skid  = i_ce && i_valid && skid_free && ((m_valid && !i_ready && !hold) || (!m_valid && pr_v));
wire       fill_main  = i_ce && i_valid && !m_valid && !pr_v;
wire       drain_main = i_ce && m_valid && i_ready && !(!hold && i_valid && skid_free);
wire       drain_skid = i_ce && hold && i_ready;
// a fresh input record takes the main slot next cycle
wire       main_wr_new  = fill_main || (i_ce && i_valid && m_valid && i_ready && !hold && skid_free);
// the promoted record leaves the transit register for the main slot
wire       main_wr_pr   = i_ce && !m_valid && pr_v;
// total records resident in the stage (main slot + skid slot + transit)
wire [1:0] occ_total  = occ + p_occ + s_occ + t_occ;
// quiescent: nothing resident in the stage and nothing arriving this cycle
wire       stage_idle = (occ_total == 2'd0) && !i_valid;
// depth request is sampled off the credential bus while quiescent
wire [1:0] cap_req    = i_cred[0] ? 2'd1 : 2'd2;
// a record is taken from upstream / handed downstream this cycle
wire       in_accept  = i_valid && !hold && skid_free;
wire       out_accept = m_valid && i_ready;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                   // the main record goes downstream this cycle; the parked
                   // record steps into the transit register on its way in
                   m_valid <= 1'b0;
                   hold    <= 1'b0;
end else if (i_valid && skid_free) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
               if (pr_v) begin
                   // main slot is reserved for the record already in transit,
                   // so a fresh arrival is parked in the freed skid slot
                   m_valid <= 1'b1;
                   m_cred  <= pr_cred;
                   if (i_valid && skid_free) begin
                       hold   <= 1'b1;
                       s_cred <= i_cred;
                   end
               end else if (i_valid) begin
                   m_valid <= 1'b1;
                   m_cred  <= i_cred;
               end
            end else begin
if (i_valid && !hold && skid_free) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

// ---- main-slot occupancy counter ----
   // normal-class records only; the priority-class share lives in p_occ
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
           if (main_wr_new)
               occ <= {1'b0, ~i_cred[7]};
          else if (main_wr_pr)
              occ <= {1'b0, ~pr_cred[7]};
           else if (drain_main)
               occ <= 2'd0;
        end
    end

   // ---- main-slot occupancy counter, priority-class share ----
   always @(posedge i_clk) begin
       if (i_reset)
           p_occ <= 2'd0;
       else if (i_ce) begin
           if (main_wr_new)
               p_occ <= {1'b0, i_cred[7]};
          else if (main_wr_pr)
              p_occ <= {1'b0, pr_cred[7]};
           else if (drain_main)
               p_occ <= 2'd0;
       end
   end

// ---- skid-slot occupancy counter ----
always @(posedge i_clk) begin
    if (i_reset)
        s_occ <= 2'd0;
    else if (i_ce) begin
        if (load_skid)
            s_occ <= s_occ + 2'd1;
        else if (drain_skid)
            s_occ <= s_occ - 2'd1;
    end
end
// ---- promotion transit register ----
// the parked record now spends a cycle here on its way to the main slot,
// which keeps the skid-to-main mux out of the downstream ready path
always @(posedge i_clk) begin
    if (i_reset) begin
        pr_v    <= 1'b0;
        pr_cred <= 8'h00;
    end else if (i_ce) begin
        if (promote) begin
            pr_v    <= 1'b1;
            pr_cred <= s_cred;
        end else if (main_wr_pr)
            pr_v <= 1'b0;
    end
end
// ---- transit-register occupancy ----
always @(posedge i_clk) begin
    if (i_reset)
        t_occ <= 2'd0;
    else if (i_ce) begin
        if (promote)
            t_occ <= t_occ + 2'd1;
        else if (main_wr_pr)
            t_occ <= t_occ - 2'd1;
    end
end
// ---- programmed stage depth ----
// depth is re-sampled only while the stage is quiescent, so a change can
// never strand a record in a slot that has just been configured away
always @(posedge i_clk) begin
    if (i_reset)
        cap <= 2'd2;
    else if (i_ce && stage_idle)
        cap <= cap_req;
end
// ---- free-slot counter: depth minus the records resident in the stage ----
always @(posedge i_clk) begin
    if (i_reset)
        free <= 3'd2;
    else if (i_ce) begin
        if (stage_idle)
            free <= {1'b0, cap_req};
        else
            free <= free - {2'b00, in_accept} + {2'b00, out_accept};
    end
end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
dbg_prev    <= 4'd0;
o_dbg_count <= 4'd0;
        end else if (i_ce) begin
g_fast <= i_valid && (free == {1'b0, cap});
            g_hld  <= i_valid && m_valid && hold;
dbg_prev    <= dbg_prev + {3'b000, (i_valid && i_ready)};
o_dbg_count <= dbg_prev ^ {3'b000, hold};
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
assign o_upstream_ready = !hold && skid_free;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

endmodule

// Credit-managed transfer engine: three credit pools, one per chain step.
// A credit is spent on ARM, handed on at START and returned by the consumer
// at FINISH.  Total credits in the system is fixed at TOTAL by construction.
module credit_chain (
    input  wire clk,
    input  wire i_ce,      // global enable: low => the engine idles
    input  wire i_arm,
    input  wire i_start,
    input  wire i_done,
    input  wire i_flush,
    output wire o_fin_seen,
output wire o_busy,
output reg [3:0] o_evt_cnt,
output reg [3:0] o_quiet_cnt
);
    localparam [3:0] TOTAL = 4'd3;
   localparam [3:0] CR_MIN = 4'd1;

    // ---- credit counter: credits held + credits in each stage == TOTAL ----
    reg [3:0] free_cr;    // credits held by the producer
    reg [3:0] armed_cr;   // credits spent on ARM, awaiting START
    reg [3:0] busy_cr;    // credits outstanding at the consumer

   // ---- adaptive credit budget: the pool in circulation is trimmed when a
   //      flush has to tear down live traffic, and healed one credit at a
   //      time while the whole engine is quiescent ----
   reg [3:0] cr_lim;     // credits currently in circulation

    // ---- chain history (arm -> start -> finish) ----
    reg ever_arm;
    reg ever_start;
    reg ever_fin;

    // ---- peer chain B: second engine drawing on the same credit pool ----
    reg [3:0] armed_b;    // chain B credits spent on ARM, awaiting START
    reg [3:0] busy_b;     // chain B credits outstanding at its consumer

    // ---- before-flush scope register: starts high, cleared by first flush ----
    reg nf;

    // ---- command-port ownership: both chains share one command port; it is
    //      handed to the other chain once the current owner has drained ----
    reg sel;              // 0 => chain A is served, 1 => chain B
// ---- debug-only activity trace: counts presented command strobes ----
reg [3:0] evt_hist;
// debug-only: saturating count of consecutive command-free enabled cycles
reg [3:0] quiet_run;

    initial begin
        armed_b    = 4'd0;
        busy_b     = 4'd0;
        sel        = 1'b0;
        free_cr    = TOTAL;
       cr_lim     = TOTAL;
        armed_cr   = 4'd0;
        busy_cr    = 4'd0;
        ever_arm   = 1'b0;
        ever_start = 1'b0;
        ever_fin   = 1'b0;
        nf         = 1'b1;
evt_hist   = 4'd0;
o_evt_cnt  = 4'd0;
quiet_run   = 4'd0;
o_quiet_cnt = 4'd0;
    end

    wire do_flush = i_ce &&  i_flush;
    wire own_idle = sel ? ((armed_b  == 4'd0) && (busy_b  == 4'd0))
                        : ((armed_cr == 4'd0) && (busy_cr == 4'd0));
    wire do_swap  = i_ce && !i_flush && own_idle && !i_arm && !i_start && !i_done;

   wire all_idle  = (armed_cr == 4'd0) && (busy_cr == 4'd0) &&
                    (armed_b  == 4'd0) && (busy_b  == 4'd0);
   // a flush over live traffic means the consumers were overrun: shed a credit
   wire cr_shrink = do_flush && !all_idle && (cr_lim != CR_MIN);
   // quiet enabled cycles hand a shed credit back to the producer
   wire cr_grow   = i_ce && !i_flush && all_idle && (cr_lim != TOTAL) &&
                    !i_arm && !i_start && !i_done;

    // the port owner is the only chain that sees the command strobes
    wire do_arm   = i_ce && !i_flush && !sel && i_arm   && (free_cr  != 4'd0);
    wire do_start = i_ce && !i_flush && !sel && i_start && (armed_cr != 4'd0);
    wire do_fin   = i_ce && !i_flush && !sel && i_done  && (busy_cr  != 4'd0);

    wire do_arm_b   = i_ce && !i_flush && sel && i_arm   && (free_cr != 4'd0);
    wire do_start_b = i_ce && !i_flush && sel && i_start && (armed_b != 4'd0);
    wire do_fin_b   = i_ce && !i_flush && sel && i_done  && (busy_b  != 4'd0);

    always @(posedge clk) begin
        if (do_flush) begin
            // all credits are recalled to the producer; the chain record for
            // this session is dropped, the finish record is kept.
           free_cr    <= cr_shrink ? (cr_lim - 4'd1) : cr_lim;
           cr_lim     <= cr_shrink ? (cr_lim - 4'd1) : cr_lim;
            armed_cr   <= 4'd0;
            busy_cr    <= 4'd0;
            armed_b    <= 4'd0;
            busy_b     <= 4'd0;
            sel        <= 1'b0;
            ever_arm   <= 1'b0;
            ever_start <= 1'b0;
            nf         <= 1'b0;
evt_hist   <= 4'd0;
o_evt_cnt  <= 4'd0;
quiet_run   <= 4'd0;
o_quiet_cnt <= 4'd0;
        end else if (i_ce) begin
           free_cr  <= free_cr  - do_arm - do_arm_b + do_fin + do_fin_b + cr_grow;
           if (cr_grow) cr_lim <= cr_lim + 4'd1;
            armed_cr <= armed_cr + do_arm   - do_start;
            busy_cr  <= busy_cr  + do_start - do_fin;
            armed_b  <= armed_b  + do_arm_b   - do_start_b;
            busy_b   <= busy_b   + do_start_b - do_fin_b;
            if (do_swap) sel <= ~sel;
            if (do_arm)   ever_arm   <= 1'b1;
            if (do_start) ever_start <= 1'b1;
            if (do_fin)   ever_fin   <= 1'b1;
evt_hist  <= {evt_hist[2:0], (i_arm | i_start | i_done)};
o_evt_cnt <= o_evt_cnt + {3'd0, (evt_hist[3] | i_arm | i_start | i_done)};
quiet_run   <= (i_arm | i_start | i_done) ? 4'd0
               : ((quiet_run == 4'd15) ? 4'd15 : quiet_run + 4'd1);
o_quiet_cnt <= quiet_run;
        end
    end

    assign o_fin_seen = ever_fin;
    assign o_busy     = (busy_cr != 4'd0) || (busy_b != 4'd0);

    // Chain precedence, in the before-flush scope: a FINISH can never have been
    // observed unless an ARM and a START were observed first.
    always @(*)
        if (nf)
            assert (!ever_fin || (ever_arm && ever_start));
endmodule

module pdk_reqtrack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_arm,     // Q event: arms the tracker (sticky)
    input  wire       i_launch,  // start step: issue a request into the array
    output wire       o_retire,  // finish step: request leaves last stage
    output wire [2:0] o_inflight
);
    parameter STAGES = 4;

    // shift register tracking in-flight requests through the stage array
    reg [STAGES-1:0] pipe;
   // peer short path: a second, two-stage request array. Accepted launches
   // alternate between the long array and this one to balance occupancy.
   reg [1:0]        pipe_b;
    // separate count of set bits in that shift register
    reg [2:0]        cnt;
    // sticky arm register (scope): set the first time i_arm is seen, never cleared
    reg              armed;
    // sticky record that a start actually happened after arming
    reg              started;
   // issue stage: an accepted launch is held here for one cycle (address
   // decode) before it is written into the stage array
   reg              ln_stage;
  // target lane of the request held in the issue stage (0 = long, 1 = short)
  reg              ln_tag;
  // round-robin lane pointer applied to the next accepted launch
  reg              rr;
// express lane: a request issued while the stage array is completely idle
// bypasses the array and completes one cycle later
reg              xpr;

    initial pipe    = {STAGES{1'b0}};
   initial pipe_b  = 2'b00;
    initial cnt     = 3'd0;
    initial armed   = 1'b0;
    initial started = 1'b0;
   initial ln_stage = 1'b0;
  initial ln_tag   = 1'b0;
  initial rr       = 1'b0;
initial xpr      = 1'b0;

    // a launch is only accepted once the tracker has been armed
    wire accept = i_ce && i_launch && armed;
  // the issue stage takes the express lane only when both arrays are empty
  wire xpr_take = ln_stage && (pipe == {STAGES{1'b0}}) && (pipe_b == 2'b00);
  wire retire = i_ce && (pipe[STAGES-1] || pipe_b[1] || xpr);

    assign o_retire   = retire;
    assign o_inflight = cnt;

    always @(posedge clk) begin
        if (rst) begin
            pipe    <= {STAGES{1'b0}};
           pipe_b  <= 2'b00;
            cnt     <= 3'd0;
            armed   <= 1'b0;
            started <= 1'b0;
           ln_stage <= 1'b0;
          ln_tag   <= 1'b0;
          rr       <= 1'b0;
           xpr      <= 1'b0;
        end else if (i_ce) begin
         pipe    <= { pipe[STAGES-2:0], ln_stage && !ln_tag && !xpr_take };
         pipe_b  <= { pipe_b[0],        ln_stage &&  ln_tag && !xpr_take };
         cnt     <= cnt + (ln_stage ? 3'd1 : 3'd0)
                         - (pipe[STAGES-1] ? 3'd1 : 3'd0)
                         - (pipe_b[1] ? 3'd1 : 3'd0)
                         - (xpr ? 3'd1 : 3'd0);
            armed   <= armed || i_arm;
            started <= started || (i_launch && armed);
           ln_stage <= i_launch && armed;
          ln_tag   <= rr;
          rr       <= rr ^ (i_launch && armed);
          xpr     <= xpr_take;
        end
    end

    // Chain precedence, after the sticky arm: while armed, the tracker can never
    // report outstanding work unless a start was really accepted first.
    always @(posedge clk)
        if (armed && (cnt != 3'd0))
            assert (started);

    // Retire/issue provenance: a request can only be observed leaving the last
    // stage, or waiting in the issue stage for address decode, if it entered
    // through an accepted start, which in turn can only happen after arming.
    always @(posedge clk)
        if (o_retire || ln_stage)
            assert (started && armed);

endmodule

module pwm_prio_duty (
    input  wire       clk,
    input  wire       ce,
    input  wire [7:0] req,
    output reg        out_r,
output reg        vld_r,
output reg [3:0] evt_r
);
    // ---------------- PWM state ----------------
    reg [2:0] cnt;        // period counter 0..7
   reg [2:0] per;        // programmed frame length minus one (frame = per+1)
    reg [3:0] duty;       // active duty value 0..8
    reg [3:0] hi_cnt;     // cycles spent high inside the current period
    reg       shadow_nz;  // shadow: the duty programmed for this period was nonzero
    reg       armed;      // scope: high until the first all-zero request load
   reg       duty_ext;   // extra whole cycle granted to this frame by the dither
   reg       dith;       // pending half-step credit carried between frames
reg [3:0] evt_cnt;    // distractor: tally of cycles with an active request

    initial begin
        cnt       = 3'd0;
       per       = 3'd7;   // reset frame is the full eight cycles
        duty      = 4'd4;   // reset duty is nonzero
        hi_cnt    = 4'd0;
        shadow_nz = 1'b1;   // matches reset duty
        armed     = 1'b1;
       duty_ext  = 1'b0;
       dith      = 1'b0;
        out_r     = 1'b0;
        vld_r     = 1'b0;
evt_cnt   = 4'd0;
evt_r     = 4'd0;
    end

    // ---------------- priority encoder over the request vector ----------------
    reg [2:0] idx;
    reg       vld;
    always @(*) begin
        vld = |req;
        if      (req[7]) idx = 3'd7;
        else if (req[6]) idx = 3'd6;
        else if (req[5]) idx = 3'd5;
        else if (req[4]) idx = 3'd4;
        else if (req[3]) idx = 3'd3;
        else if (req[2]) idx = 3'd2;
        else if (req[1]) idx = 3'd1;
        else             idx = 3'd0;
    end

    // requested duty: highest set index + 1, or 0 when no request
    wire [3:0] duty_req = vld ? ({1'b0, idx} + 4'd1) : 4'd0;

   // ---------------- frame-length programming ----------------
   // req[2:0] double as the frame-length code; a requested duty that does not
   // fit in the programmed frame is truncated to 100% of that frame
   wire [2:0] per_nxt  = req[2:0];
   wire [3:0] per_lim  = {1'b0, per_nxt} + 4'd1;
   wire [3:0] duty_nxt = (duty_req > per_lim) ? per_lim : duty_req;
  // ---------------- half-step dither ----------------
  // when several sources request at once the winner earns an extra half cycle
  // of duty for the aggregate load; two half cycles are cashed in as one whole
  // cycle, and the bump is only applied while the duty is below 100% of the
  // frame so that the extra cycle still fits inside the frame
  wire       multi    = vld && ((req & (req - 8'd1)) != 8'd0);
  wire       ext_nxt  = (dith && multi) && (duty_nxt < per_lim);
  wire [3:0] duty_eff = duty + {3'b000, duty_ext};

 // ---------------- frame capacity ----------------
 // 100% of the frame being emitted right now (the programmed per, not the
 // one being loaded); the comparator can never ask for more high time than
 // the frame it belongs to is able to hold
 wire [3:0] cap_now = {1'b0, per} + 4'd1;

    // ---------------- comparator: high exactly while cnt < duty ----------------
wire out  = ({1'b0, cnt} < duty_eff);
   wire wrap = (cnt == per);

    always @(posedge clk) begin
        if (ce) begin
           cnt   <= wrap ? 3'd0 : cnt + 3'd1;   // restarts at each boundary
            out_r <= out;          // registered output stage
            vld_r <= vld;
evt_cnt <= evt_cnt + (vld ? 4'd1 : 4'd0);
evt_r   <= {evt_cnt[2:0], evt_cnt[3]} ^ (wrap ? 4'd1 : 4'd0);
            if (wrap) begin
               per       <= per_nxt;
                // period boundary: latch the new duty and its shadow flag together
               duty      <= duty_nxt;
               shadow_nz <= (duty_nxt != 4'd0);
              duty_ext  <= ext_nxt;
              dith      <= dith ^ multi;
                hi_cnt    <= 4'd0;
               if (duty_nxt == 4'd0)
                    armed <= 1'b0; // the scope-closing event R
            end else begin
                hi_cnt <= hi_cnt + (out ? 4'd1 : 4'd0);
               // frame monitor: the high time can never outrun the frame it
               // belongs to; if it does, the latched flag no longer describes
               // the pulse being emitted, so drop it
               if (hi_cnt > {1'b0, per})
                   shadow_nz <= 1'b0;
            end
        end
    end

    // Precedence, in the "before the first zero-duty program" scope:
    // if the output has been high at all inside this period, then a nonzero
    // duty must have been recorded in the shadow flag earlier.
    always @(posedge clk)
        if (armed && hi_cnt != 4'd0)
            assert (shadow_nz);

   // Frame budget: the high time booked so far in this frame never exceeds
   // the duty being applied to it, and that duty fits inside the frame.
   always @(posedge clk)
       assert (hi_cnt <= duty_eff && duty_eff <= cap_now);
endmodule

// Packet-capture sensor credit window.
// TOTAL = 8 stream credits.  A burst send spends 3 credits (they become
// "outstanding" bytes in flight); the collector returns exactly one credit
// per enabled cycle while anything is outstanding.  A deadline register is
// reloaded on every accepted burst and counts down otherwise; it must never
// expire while credits are still outstanding.
module credit_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_send,    // producer requests a burst
output wire       o_busy,
output wire [3:0] o_nspend,  // ledger: credits handed to the link (wraps)
output wire [3:0] o_nret,    // ledger: credits taken back (wraps)
output wire       o_phase,   // which link slot the collector is in
output wire       o_rdy,     // collector has a return slot open
output wire [3:0] o_ngrant,  // ledger: return slots opened (wraps)
output wire [3:0] o_nuse     // ledger: return slots consumed (wraps)
);
    reg [3:0] avail;   // credits held by the sensor
    reg [3:0] outst;   // credits outstanding (in flight)
reg [3:0] stage;   // credits accepted for a burst but not yet on the link
reg [3:0] stage_b; // lane B stage buffer: second sensor stream, same link
reg       pri_b;   // round-robin owner of the next armed send slot
    reg [3:0] timer;   // completion deadline countdown
    reg       armed;   // sticky: set the first time a burst is accepted
reg [3:0] n_spend;  // event ledger: credits spent on bursts
reg [3:0] n_ret;    // event ledger: credits returned by the collector
reg       phase;    // half-rate return link: credits only come back on return slots
reg       rdy;      // a return slot is open and not yet used
reg [3:0] n_grant;  // event ledger: return slots opened by the collector
reg [3:0] n_use;    // event ledger: return slots consumed by a credit
reg       sready;   // framer has armed the link's send slot for a staged credit
reg [3:0] n_stg;    // event ledger: credits accepted into the stage buffer
reg [3:0] n_lnch;   // event ledger: staged credits launched onto the link

    initial avail = 4'd8;
    initial outst = 4'd0;
initial stage = 4'd0;
    initial timer = 4'd0;
    initial armed = 1'b0;
initial n_spend = 4'd0;
initial n_ret = 4'd0;
initial phase = 1'b0;
initial rdy = 1'b0;
initial n_grant = 4'd0;
initial n_use = 4'd0;
initial sready = 1'b0;
initial n_stg = 4'd0;
initial n_lnch = 4'd0;
initial stage_b = 4'd0;
initial pri_b = 1'b0;

    wire send_ok = i_send && (avail >= 4'd3);
wire grant   = !phase && !rdy;                  // collector opens the next return slot
wire retire  = (outst != 4'd0) && phase && rdy;  // a credit comes back in an open slot
wire sopen   = phase && !sready;                 // framer arms the send slot during the return half
wire slot    = !phase && sready;                    // the armed send slot is live this cycle
wire push_a  = slot && (stage   != 4'd0) && (!pri_b || (stage_b == 4'd0));
wire push_b  = slot && (stage_b != 4'd0) && ( pri_b || (stage   == 4'd0));
wire push    = push_a || push_b;                    // exactly one lane takes the slot

assign o_busy = (outst != 4'd0) || (stage != 4'd0) || (stage_b != 4'd0);
assign o_nspend = n_spend;
assign o_nret   = n_ret;
assign o_phase  = phase;
assign o_rdy    = rdy;
assign o_ngrant = n_grant;
assign o_nuse   = n_use;

    always @(posedge clk) begin
        if (rst) begin
            avail <= 4'd8;
            outst <= 4'd0;
stage <= 4'd0;
stage_b <= 4'd0;
            timer <= 4'd0;
            armed <= 1'b0;
n_spend <= 4'd0;
n_ret <= 4'd0;
phase <= 1'b0;
rdy <= 1'b0;
n_grant <= 4'd0;
n_use <= 4'd0;
sready <= 1'b0;
n_stg <= 4'd0;
n_lnch <= 4'd0;
pri_b <= 1'b0;
        end else if (i_ce) begin
phase <= ~phase;             // link alternates send / return slots
if (send_ok) n_spend <= n_spend + 4'd3;
if (retire)  n_ret   <= n_ret   + 4'd1;
if (grant) begin
    rdy     <= 1'b1;         // slot opens during the send half-period
    n_grant <= n_grant + 4'd1;
end else if (retire) begin
    rdy   <= 1'b0;           // slot consumed by the returning credit
    n_use <= n_use + 4'd1;
end
if (sopen) sready <= 1'b1;        // send slot armed for the next send half-period
else if (push) sready <= 1'b0;    // slot consumed by the launched credit
if (send_ok) n_stg  <= n_stg  + 4'd2;
if (push)    n_lnch <= n_lnch + 4'd1;
if (push)    pri_b  <= ~pri_b;    // hand the next armed slot to the other lane
            if (send_ok) begin
                // spend three credits, one may come back the same cycle
                avail <= avail - 4'd3 + (retire ? 4'd1 : 4'd0);
// one credit goes out on this slot, the other two wait one per lane
outst <= outst + 4'd1 + (push ? 4'd1 : 4'd0) - (retire ? 4'd1 : 4'd0);
stage   <= stage   + 4'd1 - (push_a ? 4'd1 : 4'd0);
stage_b <= stage_b + 4'd1 - (push_b ? 4'd1 : 4'd0);
timer <= 4'd15;         // deadline: half-rate return of up to 8 credits
                armed <= 1'b1;          // sticky arm
            end else if (retire) begin
                avail <= avail + 4'd1;
                outst <= outst - 4'd1;
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end else begin
if (push) begin
    outst <= outst + 4'd1;
if (push_a) stage   <= stage   - 4'd1;
if (push_b) stage_b <= stage_b - 4'd1;
end
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end
        end
    end

    // Bounded response (safety form), scoped after the first accepted burst:
    // the deadline never expires while credits are still outstanding.
    always @(*)
        assert (!armed || !((timer == 4'd0) && (outst != 4'd0)));
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       issue,     // new operation issued this advance
    output wire       o_retire,  // fixed-latency result leaving the unit
    output wire [2:0] o_occ
);
// 3-deep shift register feeding a registered writeback stage:
// bit k = op issued k advances ago
reg [2:0] pipe;
    // occupancy: incremented on issue, decremented when the tail drains
    reg [2:0] occ;
    // sticky arm: set the first time an operation is ever issued
    reg       armed;
// registered result stage: the final latency slot lives here
reg       wb;
// second beat of the narrow result bus; the pipe cannot advance during it
reg       beat;
// credit-based issue throttle: free slots in the 4-stage result path
reg [2:0] credit;
// return ledger: every accepted issue and every writeback return is logged
// so credits lost to a dropped return can be recovered at a drain point
reg [2:0] n_iss;
reg [2:0] n_ret;
// return staging: a slot freed by writeback waits here until the pool's
// single write port is free (an advance that takes no issue) to rejoin credit
reg [2:0] rtn;

initial pipe  = 3'b000;
    initial occ   = 3'd0;
    initial armed = 1'b0;
initial wb    = 1'b0;
initial beat  = 1'b0;
initial credit = 3'd4;
initial n_iss = 3'd0;
initial n_ret = 3'd0;
initial rtn   = 3'd0;
wire adv = i_ce && !beat;
// an issue is only taken when the unit still has a free slot
wire acc = issue && (credit != 3'd0);
// ledger view of the unit: nothing issued is still outstanding
wire drained = (n_iss == n_ret);
// an accepted issue owns the credit write port; returns fold back behind it
wire fold = (rtn != 3'd0) && !acc;

assign o_retire = adv && wb;
    assign o_occ    = occ;

    always @(posedge clk) begin
        if (rst) begin
pipe  <= 3'b000;
            occ   <= 3'd0;
            armed <= 1'b0;
wb    <= 1'b0;
beat  <= 1'b0;
credit <= 3'd4;
n_iss <= 3'd0;
n_ret <= 3'd0;
rtn   <= 3'd0;
end else begin
if (adv) begin
pipe <= {pipe[1:0], acc};
wb   <= pipe[2];
occ    <= occ    + (acc ? 3'd1 : 3'd0) - (wb ? 3'd1 : 3'd0);
// a drained ledger means the pool owes nothing: re-sync it to full
credit <= drained ? (3'd4 - (acc ? 3'd1 : 3'd0))
: (credit - (acc ? 3'd1 : 3'd0) + (fold ? 3'd1 : 3'd0));
rtn    <= drained ? 3'd0
                  : (rtn - (fold ? 3'd1 : 3'd0) + (wb ? 3'd1 : 3'd0));
n_iss  <= n_iss + (acc ? 3'd1 : 3'd0);
n_ret  <= n_ret + (wb  ? 3'd1 : 3'd0);
if (acc)
                armed <= 1'b1;
end
if (i_ce)
beat <= !beat && wb;
        end
    end

    // P: once the unit has ever issued, at most 4 operations are in flight.
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd4);

   // P2: a result waiting in writeback means the credit pool is not full.
   always @(posedge clk)
       assert (!wb || credit <= 3'd3);
endmodule

module phase_divider_pair (
    input  wire       clk,
    input  wire       ce,       // divider step enable; low = idle, all state held
    input  wire       resync,   // realigns both phase counters, retires the pristine scope
    output reg  [2:0] phase,    // primary phase counter, mod 5
    output reg  [2:0] cnt,      // skewed phase counter, mod 5, built 2 phases ahead
    output reg        en_load,  // divided enable: fires the cycle after phase wraps
    output reg        en_sample,// divided enable: fires the cycle after cnt wraps
    output reg        pristine  // high until the first resync has ever happened
);

    // Load/sample ledger: every load pulse and every sample pulse is logged
    // for the lifetime of the current alignment, so the buffer downstream can
    // account for the two divided enables it sees.
    reg  [3:0] n_load;   // count of load pulses issued
    reg  [3:0] n_samp;   // count of sample pulses issued

    // samples that do not have a matching load behind them yet
    wire [3:0] samp_ahead = n_samp - n_load;
    // a realignment can leave the ping-pong buffer starved; while the sample
    // side is two or more entries ahead, inject make-up load pulses
    wire       makeup     = (samp_ahead >= 4'd2);

   // Skew-buffer ledger: the sample pulse captures one entry into the
   // ping-pong skew buffer and the load pulse releases it to the sink, so
   // both sides are logged as the buffer sees them, on the divided enables.
   reg  [3:0] n_cap;    // entries captured by the sample side
   reg  [3:0] n_rel;    // entries released by the load side
// the bank write port is pipelined four deep (stage, format, protect, commit):
// a sample pulse enters the first stage and only lands in the array four
// enabled cycles later, so n_cap advances off the last stage.  The load side
// reads through a forwarding path, so occupancy counts the in-flight entries.
reg        cap_pend; // entry staged by the sample side, not yet committed
reg        cap_s2;   // write pipe stage 2 (format)
reg        cap_s3;   // write pipe stage 3 (protect)
reg        cap_s4;   // write pipe stage 4 (commit into the array)
wire [3:0] level     = n_cap + {3'd0, cap_pend} + {3'd0, cap_s2}
                       + {3'd0, cap_s3} + {3'd0, cap_s4} - n_rel;
   // the load side must not release an entry the sample side has not
   // captured yet, so the phase-4 pulse waits for a filled buffer
   wire       bank_full = (level != 4'd0);

   // Load-side stall watchdog: the sink downstream must never be left
   // without a load pulse for long, so the gap since the last one is timed
   // and a make-up pulse is forced once that gap gets too wide.
   reg  [2:0] gap;      // enabled cycles since the last load pulse
   wire       wdog       = (gap >= 3'd6);
wire       load_pulse = ((phase == 3'd4) && bank_full) || makeup || wdog;

    // The skewed counter is constructed 2 phases ahead of the primary phase
    // counter, so the two divided-enable pulses are interleaved by design.
    initial phase     = 3'd0;
    initial cnt       = 3'd2;
    initial en_load   = 1'b0;
    initial en_sample = 1'b0;
    initial pristine  = 1'b1;
    initial n_load    = 4'd0;
    initial n_samp    = 4'd0;
initial n_cap     = 4'd0;
initial n_rel     = 4'd0;
initial cap_pend  = 1'b0;
initial cap_s2    = 1'b0;
initial cap_s3    = 1'b0;
initial cap_s4    = 1'b0;
   initial gap       = 3'd0;

    always @(posedge clk) begin
        if (resync) begin
            // hard realignment: both phase counters are slammed to zero, which
            // destroys the constructed skew (and retires the pristine scope)
            phase     <= 3'd0;
            cnt       <= 3'd0;
            en_load   <= 1'b0;
            en_sample <= 1'b0;
            pristine  <= 1'b0;
            n_load    <= 4'd0;
            n_samp    <= 4'd0;
n_cap     <= 4'd0;
n_rel     <= 4'd0;
cap_pend  <= 1'b0;
cap_s2    <= 1'b0;
cap_s3    <= 1'b0;
cap_s4    <= 1'b0;
           gap       <= 3'd0;
        end
        else if (ce) begin
            phase     <= (phase == 3'd4) ? 3'd0 : phase + 3'd1;
            cnt       <= (cnt   == 3'd4) ? 3'd0 : cnt   + 3'd1;
            // each divided enable pulses exactly when its phase counter wraps
           en_load   <= load_pulse;
            en_sample <= (cnt   == 3'd4);
            // ledger entries are made as the pulses are issued
           n_load    <= n_load + (load_pulse ? 4'd1 : 4'd0);
            n_samp    <= n_samp + ((cnt == 3'd4) ? 4'd1 : 4'd0);
cap_pend  <= en_sample;
cap_s2    <= cap_pend;
cap_s3    <= cap_s2;
cap_s4    <= cap_s3;
n_cap     <= n_cap + (cap_s4 ? 4'd1 : 4'd0);
n_rel     <= n_rel + (en_load   ? 4'd1 : 4'd0);
           gap       <= load_pulse ? 3'd0 : gap + 3'd1;
        end
    end

    // Absence: while the divider has never been resynced, the two divided
    // enables are never asserted in the same cycle.
    always @(posedge clk)
        if (pristine)
            assert (!(en_load && en_sample));

   // Alignment: while the divider has never been resynced, the sample pulse
   // always lands three enabled cycles into the current load window.
   always @(posedge clk)
       if (pristine)
           assert (!en_sample || (gap == 3'd3));

endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

   // destination-side retiming pipeline: the event decoder sits far from the
   // synchronizer in the floorplan, so the sampled pointer is retimed four
   // times before it is decoded, and both decode operands are taken from
   // the last two taps of this pipeline so they share the same route delay
   reg [2:0] ret1;
   initial   ret1 = 3'b000;
   reg [2:0] ret2;
   initial   ret2 = 3'b000;
   reg [2:0] ret3;
   initial   ret3 = 3'b000;
   reg [2:0] ret4;
   initial   ret4 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;
   // number of chain transitions actually taken.  A corrupt handshake aborts
   // straight to FINISH, so the transition count is what tells a full walk
   // of the chain apart from an aborted one.
   reg [2:0] steps;
   initial   steps = 3'd0;
  // legs of the walk currently in flight.  steps is a status field read by
  // the host, so it is written once per handshake instead of once per leg:
  // the decoder parks intermediate legs here and the terminating leg flushes
  // the whole batch into steps in a single update.
  reg [1:0] credit;
  initial   credit = 2'd0;
// the leg adder is retimed one stage: a freshly decoded leg parks in leg_q
// and merges into credit on the next enabled cycle, so the terminating leg
// has to flush both halves of the pending batch into steps at once
reg       leg_q;
initial   leg_q = 1'b0;

    wire [2:0] gray  = bin ^ (bin >> 1);
   wire [2:0] delta = ret3 ^ ret4;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
           ret1      <= 3'b000;
           ret2      <= 3'b000;
           ret3      <= 3'b000;
           ret4      <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
           steps     <= 3'd0;
           credit    <= 2'd0;
leg_q     <= 1'b0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;
           ret1  <= sync2;
           ret2  <= ret1;
           ret3  <= ret2;
           ret4  <= ret3;

            if (bad_ev) begin
                stage <= S_FINISH;
steps  <= steps + {1'b0, credit} + {2'b0, leg_q} + 3'd1;
               credit <= 2'd0;
leg_q  <= 1'b0;
            end else begin
credit <= credit + {1'b0, leg_q};
leg_q  <= 1'b0;
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
leg_q   <= 1'b1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
leg_q     <= 1'b1;
                    end
                S_STARTED:
                   if (fin_ev) begin
                       stage <= S_FINISH;
steps  <= steps + {1'b0, credit} + {2'b0, leg_q} + 3'd1;
                      credit <= 2'd0;
leg_q  <= 1'b0;
                   end
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
   assign o_done  = (stage == S_FINISH) && (steps == 3'd3);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
   // an abort reaches FINISH without walking the chain, so a FINISH that the
   // done output is allowed to honour must show all three transitions counted
   always @(posedge i_clk)
       if (stage == S_FINISH)
           assert (steps == 3'd3);
endmodule

module prio_grant_tracker (
    input  wire       clk,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [3:0] req,
    output reg        vld,     // registered valid: idx meaningful only while set
    output reg  [1:0] idx,     // encoded winner index
    output reg  [3:0] oh,      // registered one-hot grant
    output reg        ack_lo,  // low-half acknowledge, derived from idx
    output reg        ack_hi,  // high-half acknowledge, derived from one-hot
output reg        armed,   // sticky: set the first time a request is taken
output reg  [3:0] n_take,  // ledger: leases issued  (free-running, wraps)
output reg  [3:0] n_drop,  // ledger: leases retired (free-running, wraps)
output reg        stale,   // standing lease has burned one idle cycle
output reg  [3:0] req_seen // sticky union of newly-arriving request bits
);

    // combinational priority encoder (lowest index wins)
    wire       any = |req;
    wire [1:0] enc = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;
    wire [3:0] iso = req & (~req + 4'd1);   // isolate lowest set bit
   // retirements are booked by half: a low-half holder settles into n_drop,
   // a high-half holder into its own column, so the two halves of the
   // ledger can be read out independently
   reg [3:0] n_drop_hi;
   // channel B: a second lease register set.  Both channels drive the same
   // downstream consumer, so they share the ledger columns and the
   // acknowledge outputs; `turn` alternates which channel is offered the
   // next fresh lease.
   reg        vld_b;
   reg  [1:0] idx_b;
   reg  [3:0] oh_b;
   reg        stale_b;
   reg        turn;
// shadow copy of the previous request vector, used for edge detection only
reg [3:0] req_prev;

   // the ledger, not vld, is the authority on lease occupancy
  wire [3:0] n_ret       = n_drop + n_drop_hi;
  wire       outstanding = (n_take != n_ret);

    initial begin
        vld    = 1'b0;
        idx    = 2'd0;
        oh     = 4'b0000;
        ack_lo = 1'b0;
        ack_hi = 1'b0;
        armed  = 1'b0;
n_take = 4'd0;
n_drop = 4'd0;
       n_drop_hi = 4'd0;
stale  = 1'b0;
req_seen  = 4'd0;
req_prev  = 4'd0;
       vld_b   = 1'b0;
       idx_b   = 2'd0;
       oh_b    = 4'b0000;
       stale_b = 1'b0;
       turn    = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            // acknowledge flags are built from the *previous* grant state:
            // one path reads the index, the other reads the one-hot vector
// bookkeeping only: remember which request lines have newly arrived
req_prev <= req;
req_seen <= req_seen | (req & ~req_prev);
           ack_lo <= (vld   && (idx   < 2'd2)) ||
                     (vld_b && (idx_b < 2'd2));
           ack_hi <= (vld   && (oh[3]   || oh[2])) ||
                     (vld_b && (oh_b[3] || oh_b[2]));

            if (any) begin
               // a request refreshes the standing lease on its own channel
                armed <= 1'b1;
                if (!outstanding) begin
                    // ledger is square: issue a fresh lease to the winner
                   // and hand the bus to whichever channel has the turn
                   turn <= ~turn;
                   if (turn) begin
                       vld_b   <= 1'b1;
                       stale_b <= 1'b0;
                       idx_b   <= enc;
                       oh_b    <= iso;
                   end else begin
                       vld   <= 1'b1;
                       stale <= 1'b0;
                       idx   <= enc;
                       oh    <= iso;
                   end
                   n_take <= n_take + 4'd1;
               end else if (vld_b) begin
                   // channel B is the holder: refreshed in place, and it
                   // yields the bus to a higher-priority requester
                   stale_b <= 1'b0;
                   if (enc < idx_b) begin
                       idx_b <= enc;
                       oh_b  <= iso;
                   end
               end else begin
                   // channel A is the holder
                   vld   <= 1'b1;
                   stale <= 1'b0;
                   if (enc < idx) begin
                    // lease already in flight: a higher-priority requester
                    // takes it over in place -- a hand-off, not a new lease,
                    // so the ledger does not move
                    idx <= enc;
                    oh  <= iso;
                end
               end
                // otherwise the current holder keeps the bus
            end else if (outstanding) begin
               if (vld_b) begin
                   if (stale_b) begin
                       // channel B retires into the shared drop columns
                       vld_b   <= 1'b0;
                       stale_b <= 1'b0;
                       if (idx_b[1]) n_drop_hi <= n_drop_hi + 4'd1;
                       else          n_drop    <= n_drop    + 4'd1;
                   end else begin
                       idx_b   <= idx_b + 2'd1;
                       oh_b    <= {oh_b[2:0], oh_b[3]};
                       stale_b <= 1'b1;
                   end
               end else if (stale) begin
                    // second idle cycle retires the lease; the one-hot is
                    // left parked as a record of the last holder
                    vld    <= 1'b0;
                    stale  <= 1'b0;
                   if (idx[1]) n_drop_hi <= n_drop_hi + 4'd1;
                   else        n_drop    <= n_drop    + 4'd1;
                end else begin
                    // first idle cycle: age the standing grant round-robin
                    idx   <= idx + 2'd1;
                    oh    <= {oh[2:0], oh[3]};
                    stale <= 1'b1;
                end
            end
        end
    end

    // P: once the tracker has ever accepted a request, the low-half and
    // high-half acknowledges are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(ack_lo && ack_hi));

endmodule

// Debug-probe challenge sequencer: a maximal-length LFSR supplies one tick per
// chain step (arm -> start -> finish). The LFSR is seeded non-zero and can never
// enter the all-zeros lockup state, so every FSM advance is accompanied by a
// genuine change of the challenge shift register.
module probe_chain_seq (
    input  wire       clk,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire       arm,
    input  wire       start,
    input  wire       fin,
    output reg  [1:0] stage,
    output reg        pre_done,
    output reg  [3:0] chal
);
    // stage encoding: 0 = IDLE, 1 = ARMED, 2 = RUNNING, 3 = DONE
    reg [3:0] lfsr;
    reg       pv;
    // channel B: second probe chain sharing the one challenge generator
    reg [1:0] stage_b;
    reg       own;      // 0 = chain A holds the generator, 1 = chain B
    reg       ld;       // generator context restore in flight (owner stalls)
    reg       chal_ok;  // chal holds a valid generator word
  // the challenge register is written over a 2-bit-wide debug bus, so a new
  // word lands in two beats: the low half is driven immediately and the high
  // half is staged here until the following enabled cycle
  reg [1:0] chal_hi;
  reg       chal_ph;  // high half still owed to the challenge register
   // per-chain generator context: a chain preempted by the arbiter resumes
   // its own point in the challenge stream when it gets the generator back
   reg [3:0] ctx_a;
   reg [3:0] ctx_b;
  // preemption save buffer: the context file is written over the same 2-bit
  // debug port as the challenge register, so a parked resume word lands low
  // half first and high half on the next free beat
  reg [1:0] ctx_hi;
  reg       ctx_ph;   // high half of a parked context still owed
  reg       ctx_sel;  // 0 = save targets ctx_a, 1 = targets ctx_b
   reg [2:0] tmr;      // round-robin time slice for the shared generator

    initial lfsr     = 4'b0001;
    initial chal     = 4'b0000;
    initial stage    = 2'd0;
    initial pre_done = 1'b1;   // before-scope: high until the first DONE ever
    initial pv       = 1'b0;
    initial stage_b  = 2'd0;
    initial own      = 1'b0;
    initial ld       = 1'b0;
    initial chal_ok  = 1'b0;
  initial chal_hi  = 2'b00;
  initial chal_ph  = 1'b0;
   initial ctx_a    = 4'b0000;
   initial ctx_b    = 4'b0000;
  initial ctx_hi   = 2'b00;
  initial ctx_ph   = 1'b0;
  initial ctx_sel  = 1'b0;
   initial tmr      = 3'd7;

    // x^4 + x^3 + 1 : period 15 over the non-zero states
    wire       fb        = lfsr[3] ^ lfsr[2];
    wire [3:0] lfsr_next = {lfsr[2:0], fb};

   // A chain that has left IDLE owns a parked generator word and resumes from
   // it; a chain that is IDLE starts cold from the last challenge issued on
   // the shared bus, or from the cold seed if none has been issued yet.
   wire       in_a      = (stage   != 2'd0);
   wire       in_b      = (stage_b != 2'd0);
   wire [3:0] cold      = chal_ok ? chal : 4'b0001;
   wire [3:0] lfsr_rest = own ? (in_b ? ctx_b : cold)
                              : (in_a ? ctx_a : cold);

    // the current owner releases the generator once its chain reaches DONE
    wire a_done = (stage   == 2'd3);
    wire b_done = (stage_b == 2'd3);
   // ... or when its arbitration time slice expires, so a chain that stalls
   // mid-run cannot hold the shared generator forever
   wire slice_up = (tmr == 3'd0);
  // a preemption cannot start while the previous context save is still
  // draining, or the parked word would be half of one chain and half of
  // another
  wire yield    = !ld && !ctx_ph && (slice_up || (own ? b_done : a_done));

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            lfsr <= ld ? lfsr_rest : lfsr_next;
           if (yield) begin
               own <= ~own;
              // park the outgoing chain's stream: low half straight away,
              // high half staged for the save buffer
              if (own) ctx_b[1:0] <= lfsr_next[1:0];
              else     ctx_a[1:0] <= lfsr_next[1:0];
              ctx_hi  <= lfsr_next[3:2];
              ctx_sel <= own;
              ctx_ph  <= 1'b1;
               tmr <= 3'd7;
           end else if (!ld) begin
               tmr <= tmr - 3'd1;
           end
            ld <= yield;
          // second beat: the staged high half lands and the challenge word
          // becomes valid for chains that start cold from the shared bus
          if (chal_ph) begin
              chal[3:2] <= chal_hi;
              chal_ok   <= 1'b1;
              chal_ph   <= 1'b0;
          end
         // the save buffer drains on the first beat the debug port is not
         // carrying a challenge half
         if (ctx_ph && !chal_ph) begin
             if (ctx_sel) ctx_b[3:2] <= ctx_hi;
             else         ctx_a[3:2] <= ctx_hi;
             ctx_ph <= 1'b0;
         end
            if (!ld) begin
            if (!own) begin
            case (stage)
               2'd0: if (arm && !chal_ph) begin
                          stage <= 2'd1;
                         chal[1:0] <= lfsr[1:0];   // first beat on the bus
                         chal_hi   <= lfsr[3:2];    // high half next cycle
                         chal_ph   <= 1'b1;
                         chal_ok   <= 1'b0;         // incomplete until commit
                     ctx_a <= lfsr_next;  // resume point for this chain
                      end
                2'd1: if (start) stage <= 2'd2;
                2'd2: if (fin) begin
                          stage    <= 2'd3;   // finish: clears the before-scope
                          pre_done <= 1'b0;
                      end
                default: stage <= 2'd0;
            endcase
            end else begin
                case (stage_b)
                   2'd0: if (arm && !chal_ph) begin
                              stage_b <= 2'd1;
                             chal[1:0] <= lfsr[1:0];
                             chal_hi   <= lfsr[3:2];
                             chal_ph   <= 1'b1;
                             chal_ok   <= 1'b0;
                             ctx_b <= lfsr_next;
                          end
                    2'd1: if (start) stage_b <= 2'd2;
                    2'd2: if (fin)   stage_b <= 2'd3;
                    default: stage_b <= 2'd0;
                endcase
            end
            end
        end
    end

    // P: before the first finish has ever been observed, the chain FSM cannot
    //    move unless the challenge shift register moved with it.
    always @(posedge clk)
        if (pv && pre_done && $stable(lfsr))
            assert ($stable(stage));
endmodule

module serial_retire_counter (
    input  wire i_clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_bit,
    output wire o_word_done,
    output wire o_saturated,
    output reg  o_bit_parity
);
    // Bit-serial datapath: one bit per enabled cycle, 32 bits per word.
    // Every completed 32-bit word retires one operation; the retire counter
    // is a saturating up-counter that clamps at 20, well below the 31 its
    // 5-bit register could hold.
    localparam [4:0] MAX_RETIRE = 5'd20;

    reg [4:0]  sh;       // serial bit index 0..31
    reg [31:0] word;     // serial shift register (datapath flavour)
    reg [4:0]  retired;  // saturating up-counter, clamps at MAX_RETIRE
    reg        done;     // "counter has reached the clamp" flag
   reg [4:0]  pend;    // retire credits posted but not yet counted
  reg [4:0]  stg;     // staging slot: this word's credit, before merge
  // Credit ledger for occupancy audit: every post and every release is
  // logged.  Free-running, wraps at 5 bits; the queue depth reported to the
  // saturation accounting is the difference of the two logs.
  reg [4:0]  n_post;  // credits posted  (enqueue side of the ledger)
  reg [4:0]  n_rel;   // credits released (dequeue side of the ledger)
  reg [3:0]  ones_cnt; // 1-bits observed on the serial input (audit only)

    initial sh      = 5'd0;
    initial word    = 32'd0;
    initial retired = 5'd0;
    initial done    = 1'b0;
   initial pend    = 5'd0;
  initial stg     = 5'd0;
  initial n_post  = 5'd0;
  initial n_rel   = 5'd0;
 initial ones_cnt     = 4'd0;
 initial o_bit_parity = 1'b0;

   // Retirement is credited through a small pending-credit queue: a completed
   // word posts one credit, and the retire counter's write port (shared with
   // word capture) releases one credit on any enabled cycle that is not a
   // word boundary.  Saturation is declared on the total, posted + counted.
  // The credit queue is split across two registers so the post side and the
  // release side never contend for the same write port: a credit posted at a
  // word boundary lands in the staging slot stg, merges into pend on the next
  // enabled non-boundary cycle, and releases are taken from pend only.

    wire word_last = (sh == 5'd31);

  wire [4:0] outstanding  = n_post - n_rel;
  wire [5:0] retire_total = {1'b0, retired} + {1'b0, outstanding};
   wire       credit_enq   = word_last && !done;
   wire       credit_deq   = (pend != 5'd0) && !word_last;
  wire       stg_move    = (stg != 5'd0) && !word_last;

    always @(posedge i_clk) begin
        if (i_rst) begin
            sh      <= 5'd0;
            word    <= 32'd0;
            retired <= 5'd0;
            done    <= 1'b0;
           pend    <= 5'd0;
          stg     <= 5'd0;
          n_post  <= 5'd0;
          n_rel   <= 5'd0;
         ones_cnt     <= 4'd0;
         o_bit_parity <= 1'b0;
        end else if (i_ce) begin
            sh   <= sh + 5'd1;
            word <= { i_bit, word[31:1] };
         ones_cnt     <= ones_cnt + {3'd0, i_bit};
         o_bit_parity <= o_bit_parity ^ i_bit;
          if (credit_enq)
              stg <= stg + 5'd1;
          else if (stg_move)
              stg <= stg - 5'd1;
          if (stg_move && !credit_deq)
              pend <= pend + 5'd1;
          else if (credit_deq && !stg_move)
              pend <= pend - 5'd1;
           if (credit_deq)
               retired <= retired + 5'd1;
          if (credit_enq)
              n_post <= n_post + 5'd1;
          if (credit_deq)
              n_rel <= n_rel + 5'd1;
           if (credit_enq)
               done <= (retire_total == {1'b0, (MAX_RETIRE - 5'd1)});
        end
    end

    assign o_word_done = word_last;
    assign o_saturated = done;

    // P: the retire count never exceeds 20, although the register admits 31.
    always @(posedge i_clk)
        assert (retired <= MAX_RETIRE);
endmodule

module token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle condition: nothing moves when low
    input  wire       req,
    output reg        grant_q,
    output reg [3:0]  tokens
);
    localparam [3:0] BURST  = 4'd12; // bucket cap
    localparam [3:0] REFILL = 4'd3;  // tokens added per timer tick
    localparam [2:0] PERIOD = 3'd4;  // refill timer top
   localparam [3:0] SOFT    = 4'd8; // tokens kept in the live bucket
   localparam [3:0] RESVMAX = 4'd6; // reserve pool cap
  localparam [3:0] LEASEMAX = 4'd2; // tokens leased ahead of the bucket

    reg [2:0] timer;
    reg       saw_refill;            // shadow: a refill tick has occurred
   // Overflow reserve: refill above SOFT is parked here instead of being
   // thrown away by the clamp, and trickles back one token at a time when
   // the live bucket runs dry.
   reg [3:0] resv;

   // Refill commit pipeline: the bucket adder/clamp is registered, so the
   // token target computed at a timer tick is applied four cycles later.
   // Layout of each stage: {valid, precomputed token target}.
   reg [4:0] rf_s1, rf_s2, rf_s3, rf_s4;
  // Reserve handoff register: the trickle out of the reserve pool is now
  // registered, so a token leaves resv on one enabled cycle and lands in
  // the live bucket on the next. Only one trickle is in flight at a time.
  reg       hand_v;
  reg [3:0] hand_tok;
 // Grant lease: every committed refill is split, with the first couple of
 // tokens parked in a tiny lease register that serves requests ahead of the
 // live bucket, so a grant never has to wait behind the bucket adder.
 reg [3:0] lease;

    wire       tick     = (timer == PERIOD);
   wire       do_grant = ce && req && ((tokens != 4'd0) || (lease != 4'd0));
    wire [4:0] sum      = {1'b0, tokens} + {1'b0, REFILL};
    wire [3:0] refilled = (sum > {1'b0, BURST}) ? BURST : sum[3:0];
   wire       commit   = rf_s4[4];
   wire [3:0] target   = rf_s4[3:0];
  wire [3:0] eff_target = (target > SOFT) ? SOFT : target;
  wire [3:0] excess     = (target > SOFT) ? (target - SOFT) : 4'd0;
  wire [4:0] resv_sum   = {1'b0, resv} + {1'b0, excess};
wire [3:0] lease_room = LEASEMAX - lease;
wire [3:0] lease_add  = (eff_target >= lease_room) ? lease_room : eff_target;
wire [3:0] bucket_tgt = eff_target - lease_add;
wire       gl         = do_grant && (lease != 4'd0);
wire       gb         = do_grant && (lease == 4'd0);
 wire [3:0] hand_amt   = (resv >= 4'd2) ? 4'd2 : 4'd1;
wire       drain      = !commit && (tokens == 4'd0) && (lease == 4'd0) && (resv != 4'd0) && !hand_v;

    initial begin
        timer      = 3'd0;
        tokens     = 4'd0;
        saw_refill = 1'b0;
       resv       = 4'd0;
        grant_q    = 1'b0;
       rf_s1      = 5'd0;
       rf_s2      = 5'd0;
       rf_s3      = 5'd0;
       rf_s4      = 5'd0;
      hand_v     = 1'b0;
      hand_tok   = 4'd0;
     lease      = 4'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            timer      <= 3'd0;
            tokens     <= 4'd0;
            saw_refill <= 1'b0;
           resv       <= 4'd0;
            grant_q    <= 1'b0;
           rf_s1      <= 5'd0;
           rf_s2      <= 5'd0;
           rf_s3      <= 5'd0;
           rf_s4      <= 5'd0;
          hand_v     <= 1'b0;
          hand_tok   <= 4'd0;
         lease      <= 4'd0;
        end else if (ce) begin
            timer   <= tick ? 3'd0 : (timer + 3'd1);
            grant_q <= do_grant;

           // stage the refill: capture the clamped target at the tick and
           // walk it down the pipeline, one stage per enabled cycle
           rf_s1 <= {tick, refilled};
           rf_s2 <= rf_s1;
           rf_s3 <= rf_s2;
           rf_s4 <= rf_s3;

          // post the trickle amount now; it is deposited in the bucket on
          // the next enabled cycle
          hand_v   <= drain;
          hand_tok <= drain ? hand_amt : 4'd0;

            if (tick)
                saw_refill <= 1'b1;

           case ({commit, gb})
             2'b10:   tokens <= bucket_tgt;
                2'b01:   tokens <= tokens - 4'd1;
             2'b11:   tokens <= (bucket_tgt == 4'd0) ? 4'd0 : (bucket_tgt - 4'd1);
              default: tokens <= hand_v ? hand_tok : tokens;
            endcase

         // lease bookkeeping: take its slice of the committed refill, and
         // give a token back whenever it is the one serving the grant
         if (commit)
             lease <= gl ? (lease + lease_add - 4'd1) : (lease + lease_add);
         else if (gl)
             lease <= lease - 4'd1;

          // reserve bookkeeping: soak up the clamped surplus, or hand one
          // token back to the live bucket when it has emptied out
          if (commit)
              resv <= (resv_sum > {1'b0, RESVMAX}) ? RESVMAX : resv_sum[3:0];
          else if (drain)
             resv <= resv - hand_amt;
        end
    end

    // Precedence: a registered grant can only be observed if a refill tick
    // was recorded earlier in the shadow bit.
    always @(posedge clk)
        if (grant_q)
            assert (saw_refill);

endmodule

module window_rate_limiter (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_req,
output wire o_grant,
output wire [2:0] o_n_in,
output wire [2:0] o_n_out
);
    parameter W     = 4;
    parameter LIMIT = 3;

    // sliding window of the last W grant decisions
    reg [W-1:0] win;
    // count of ones that mirrors the window by construction
    reg [2:0]   ones;
   // admit decision in flight toward the accumulator: the count update is
   // retimed through one register stage, so `ones` trails the window by a beat
   reg         adm_q;
   // issue pipeline: a granted request spends four cycles travelling from the
   // decision point to the head of the window, one stage per cycle
   reg         s1;
   reg         s2;
   reg         s3;
   reg         s4;
    // sticky arm register: set the first time a grant is ever issued
    reg         armed;
   // post-grant cooldown: a grant is followed by two enabled cycles of refusal
   reg [1:0]   gap;
    reg         pv;
// issue/retire ledger: one tick per admit pushed into the window, one per
// slot that falls off the far end. Free running, they wrap at three bits.
reg [2:0]   n_in;
reg [2:0]   n_out;

    initial win   = 0;
    initial ones  = 0;
   initial adm_q = 0;
   initial s1    = 0;
   initial s2    = 0;
   initial s3    = 0;
   initial s4    = 0;
    initial armed = 0;
   initial gap   = 0;
    initial pv    = 0;
initial n_in  = 0;
initial n_out = 0;

    // the bit about to leave the window
    wire [2:0] retiring = win[W-1] ? 3'd1 : 3'd0;
    // occupancy of the window once the oldest slot retires
   // plus the admit still in flight, which the accumulator has not absorbed yet
   wire [2:0] eff      = ones - retiring + (adm_q ? 3'd1 : 3'd0);
// occupancy straight off the ledger: n_in ticks when an admit is issued into
// the pipeline and n_out when a slot retires, so the difference covers the
// window and everything still in flight behind it
wire [2:0] occ  = n_in - n_out;
// the same figure once the oldest slot has retired
wire [2:0] live = occ - retiring;

// rate decision is taken from the ledger, which is exact for this cycle,
   // and is additionally blocked while the post-grant cooldown is running
wire allow = i_req && (live < LIMIT) && (gap == 2'd0);
// the retimed accumulator now sizes the cooldown instead: a window already
// carrying two admits earns the long pause, a lightly loaded one a short one
wire [1:0] cool = (eff >= 3'd2) ? 2'd2 : 2'd1;

    assign o_grant = i_ce && allow;
assign o_n_in  = n_in;
assign o_n_out = n_out;

    always @(posedge clk) begin
        if (i_rst) begin
            win   <= 0;
            ones  <= 0;
           adm_q <= 0;
           s1    <= 0;
           s2    <= 0;
           s3    <= 0;
           s4    <= 0;
            armed <= 0;
           gap   <= 0;
n_in  <= 0;
n_out <= 0;
        end else if (i_ce) begin
win   <= { win[W-2:0], s4 };
           ones  <= ones - retiring + (adm_q ? 3'd1 : 3'd0);
adm_q <= s4;
s1    <= allow;
s2    <= s1;
s3    <= s2;
s4    <= s3;
if (allow)
    n_in  <= n_in  + 3'd1;
if (win[W-1])
    n_out <= n_out + 3'd1;
            if (allow)
                armed <= 1'b1;
if (s4)
gap <= cool;
           else if (gap != 2'd0)
               gap <= gap - 2'd1;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    // Precedence, after the limiter has armed: a grant observed one cycle ago
    // must have been preceded by a window that was not already saturated, so
    // the window can never be completely full of grants.
    always @(posedge clk)
        if (pv && armed)
            assert (!($past(i_ce) && $past(allow)) || (win != 4'hF));

   // Cooldown consistency: halfway through a cooldown the grant that started it
   // is still resident in the window, so the mirrored occupancy is not empty.
   always @(posedge clk)
       if (pv)
           assert ((gap != 2'd1) || (ones != 3'd0 || adm_q));
endmodule

module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] req,
    output reg  [3:0] gnt,
output reg  [1:0] stage,
output reg  [3:0] act_cnt
);
    // round-robin arbiter state
    reg [1:0] last_gnt;
    // chain-precedence bookkeeping: arm (line0) -> start (line1) -> finish (line2)
    reg       seen_arm;
    reg       seen_start;
    // sticky scope register: set the first time any grant is issued
    reg       armed;
   // peer chain B: shares the start unit with chain A
   // arm(line2) -> start(line3) -> finish(line1)
   reg [1:0] stage_b;
   // shared start unit is primed and not yet consumed
   reg       start_tok;
 // shared-start-unit ledger: one entry logged per acquire, one per release
 reg [3:0] tok_acq;
 reg [3:0] tok_rel;
  // posted stage-update pipe: a chain A stage advance is handed to the
  // writeback pipe and only lands on the stage register four cycles later.
  // 2'd0 in a slot means "nothing posted here".
  reg [1:0] upd_p0;
  reg [1:0] upd_p1;
  reg [1:0] upd_p2;
  reg [1:0] upd_p3;
// distractor: previous request vector, used only for the activity counter
reg [3:0] req_prev;

    initial begin
        last_gnt   = 2'd3;
        gnt        = 4'b0000;
        stage      = 2'd0;
        seen_arm   = 1'b0;
        seen_start = 1'b0;
        armed      = 1'b0;
       stage_b    = 2'd0;
       start_tok  = 1'b0;
     tok_acq    = 4'd0;
     tok_rel    = 4'd0;
      upd_p0     = 2'd0;
      upd_p1     = 2'd0;
      upd_p2     = 2'd0;
      upd_p3     = 2'd0;
req_prev   = 4'b0000;
act_cnt    = 4'd0;
    end

    // combinational round-robin grant: one-hot, never on a non-requesting line
    reg [3:0] gnt_c;
    always @(*) begin
        case (last_gnt)
            2'd0: gnt_c = req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 : 4'b0000;
            2'd1: gnt_c = req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 : 4'b0000;
            2'd2: gnt_c = req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 : 4'b0000;
            default: gnt_c = req[0] ? 4'b0001 :
                             req[1] ? 4'b0010 :
                             req[2] ? 4'b0100 :
                             req[3] ? 4'b1000 : 4'b0000;
        endcase
    end

    wire [1:0] gnt_idx = gnt_c[0] ? 2'd0 :
                         gnt_c[1] ? 2'd1 :
                         gnt_c[2] ? 2'd2 : 2'd3;

    wire fire = i_ce && (gnt_c != 4'b0000);
  // only one stage update may be outstanding in the pipe
  wire upd_busy = (upd_p0 | upd_p1 | upd_p2 | upd_p3) != 2'd0;
 // ledger view of the shared start unit: a nonzero balance means some
 // acquire has not been returned yet, so the unit is still primed
 wire [3:0] tok_bal  = tok_acq - tok_rel;
 wire       tok_out  = (tok_bal != 4'd0);
 // acquire side: chain B primes the unit on its START step
 wire       tok_grab = fire && (stage_b == 2'd1) && gnt_c[3];
 // return side: B consumes it, or chain A tears it down on abort/retire.
 // a teardown that finds no held unit is not a return, so it is not logged.
 wire       tok_drop = fire && !tok_grab && start_tok &&
                       (((stage_b == 2'd2) && gnt_c[1]) ||
                        (stage == 2'd3) ||
                        (((stage == 2'd1) || (stage == 2'd2)) && gnt_c[3]));

    always @(posedge clk) begin
        gnt <= fire ? gnt_c : 4'b0000;
       // shared-start-unit ledger, free running, wraps at 4 bits
       if (tok_grab) tok_acq <= tok_acq + 4'd1;
       if (tok_drop) tok_rel <= tok_rel + 4'd1;
      if (i_ce) begin
          // last slot retires onto the stage register, then the pipe shifts
          if (upd_p3 != 2'd0)
              stage <= upd_p3;
          upd_p3 <= upd_p2;
          upd_p2 <= upd_p1;
          upd_p1 <= upd_p0;
          upd_p0 <= 2'd0;
      end
        if (fire) begin
            last_gnt <= gnt_idx;
            armed    <= 1'b1;
            case (stage)
                2'd0: begin
                   if (gnt_c[0] && !upd_busy) begin
                       upd_p0   <= 2'd1;   // post ARM step
                        seen_arm <= 1'b1;
                    end
                end
                2'd1: begin
                   if (gnt_c[1] && !upd_busy) begin
                       upd_p0     <= 2'd2; // post START step
                        seen_start <= 1'b1;
end else if (tok_out && gnt_c[2] && !upd_busy) begin
                      upd_p0     <= 2'd3; // start unit already primed: skip START
                   end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                       start_tok  <= 1'b0; // release shared start unit
                      upd_p0     <= 2'd0; // abort flushes the posted update
                      upd_p1     <= 2'd0;
                      upd_p2     <= 2'd0;
                      upd_p3     <= 2'd0;
                    end
                end
                2'd2: begin
                   if (gnt_c[2] && !upd_busy) begin
                       upd_p0 <= 2'd3;     // post FINISH step
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                       start_tok  <= 1'b0; // release shared start unit
                      upd_p0     <= 2'd0; // abort flushes the posted update
                      upd_p1     <= 2'd0;
                      upd_p2     <= 2'd0;
                      upd_p3     <= 2'd0;
                    end
                end
                default: begin
                    stage      <= 2'd0;     // retire transaction
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                   start_tok  <= 1'b0;     // release shared start unit
                  upd_p0     <= 2'd0;     // nothing left to post
                  upd_p1     <= 2'd0;
                  upd_p2     <= 2'd0;
                  upd_p3     <= 2'd0;
                end
            endcase
           // peer chain B drives the same start unit from the high lines
           case (stage_b)
               2'd0: if (gnt_c[2]) stage_b <= 2'd1;   // ARM step (B)
               2'd1: if (gnt_c[3]) begin
                         stage_b    <= 2'd2;          // START step (B)
                         seen_start <= 1'b1;          // shared unit has run
                         start_tok  <= 1'b1;          // and stays primed
                     end
               2'd2: if (gnt_c[1]) begin
                         stage_b   <= 2'd3;           // FINISH step (B)
                         start_tok <= 1'b0;           // B consumes the unit
                     end
               default: stage_b <= 2'd0;              // retire B
           endcase
        end
// distractor activity counter: counts request-vector changes while enabled
if (i_ce) begin
req_prev <= req;
if (req != req_prev)
act_cnt <= act_cnt + 4'd1;
end
    end

    // P: once the arbiter has ever granted (sticky armed), a finished
    // transaction can only be observed if arm and start really happened.
    always @(posedge clk)
        if (armed && stage == 2'd3)
            assert (seen_arm && seen_start);
endmodule

module axi_grant_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire [3:0] req,
    input  wire       done,
    output reg        gnt_valid,
    output reg [1:0]  gnt_idx,
    output reg [2:0]  timer,
    output reg [2:0]  elapsed,
output wire [3:0] o_gnt,
output reg [3:0]  req_hist
);
    // Latency budget granted to an accepted request.
localparam [2:0] BUDGET_MAX = 3'd5;
localparam [2:0] BUDGET_MIN = 3'd3;

// Adaptive latency allowance. A slave that times out earns one extra
// credit for the next requester; a slave that answers within a cycle
// gives one back. Only rewritten in the gap between grants.
reg [2:0] budget;
// Latency of the most recently completed transaction, in cycles. Feeds
// the budget hysteresis below: the window is only narrowed after two
// quick responses in a row, so a single lucky slave cannot starve the
// next requester.
reg [2:0] last_lat;
// Contention ceiling. Under sustained backpressure (four consecutive
// cycles with an unserved request) the arbiter advertises a tighter
// maximum window so the request queue can drain; once the history
// clears it relaxes the ceiling again, one credit per idle cycle.
reg [2:0] cap;

    // ---------------------------------------------------------------
    // Priority encoder over the request vector: lowest index wins.
    // The encoded index is only meaningful while gnt_valid is set.
    // ---------------------------------------------------------------
    wire       enc_valid = |req;
    wire [1:0] enc_idx   = req[0] ? 2'd0 :
                           req[1] ? 2'd1 :
                           req[2] ? 2'd2 : 2'd3;

    // Retirement of the outstanding grant: either the slave answered,
    // or the budget has been fully consumed.
wire retire = gnt_valid && (done || ((elapsed == (budget - 3'd1)) && (timer == 3'd1)));

   // Next advertised window, and the allowance actually handed out once
   // the running budget has been clamped into that window.
   wire [2:0] cap_next = (req_hist == 4'b1111) ? ((cap == BUDGET_MIN) ? BUDGET_MIN : cap - 3'd1) :
                         (req_hist == 4'b0000) ? ((cap == BUDGET_MAX) ? BUDGET_MAX : cap + 3'd1) :
                                                 cap;
   wire [2:0] alloc    = (budget > cap_next) ? cap_next : budget;

    assign o_gnt = gnt_valid ? (4'b0001 << gnt_idx) : 4'b0000;

    initial gnt_valid = 1'b0;
    initial gnt_idx   = 2'd0;
    initial timer     = 3'd0;
    initial elapsed   = 3'd0;
initial budget    = BUDGET_MAX;
initial last_lat  = 3'd0;
initial cap       = BUDGET_MAX;
initial req_hist  = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            gnt_valid <= 1'b0;
            gnt_idx   <= 2'd0;
            timer     <= 3'd0;
            elapsed   <= 3'd0;
budget    <= BUDGET_MAX;
last_lat  <= 3'd0;
cap       <= BUDGET_MAX;
req_hist  <= 4'd0;
        end else if (i_ce) begin
req_hist <= {req_hist[2:0], (|req) & ~done};
            if (!gnt_valid) begin
               cap    <= cap_next;
               budget <= alloc;
                if (enc_valid) begin
                    gnt_valid <= 1'b1;
                    gnt_idx   <= enc_idx;
                   timer     <= alloc;    // credits left, clamped to window
                    elapsed   <= 3'd0;     // cycles burnt
                end
            end else if (retire) begin
                gnt_valid <= 1'b0;
                timer     <= 3'd0;
                elapsed   <= 3'd0;
last_lat  <= elapsed;
if (!done)
   budget <= (budget >= cap) ? cap : budget + 3'd1;
else if ((elapsed <= 3'd1) && (last_lat <= 3'd1))
    budget <= (budget == BUDGET_MIN) ? BUDGET_MIN : budget - 3'd1;
            end else begin
                timer   <= timer   - 3'd1;
                elapsed <= elapsed + 3'd1;
            end
        end
    end

    // Bounded response, safety form: the countdown must never reach zero
    // while a grant is still outstanding ...
    always @(posedge clk)
        assert (!gnt_valid || (timer != 3'd0));

    // ... and the elapsed-cycle counter must never run past the budget
    // window while a grant is still outstanding.
    always @(posedge clk)
        assert (!gnt_valid || (elapsed <= 3'd4));

   // Latency monitor: the recorded latency of the last completed
   // transaction always fits strictly inside the widest window the
   // arbiter can hand out, and an outstanding grant never carries more
   // credits than that window either.
   always @(posedge clk)
       assert ((last_lat < BUDGET_MAX) && (!gnt_valid || (timer <= BUDGET_MAX)));
endmodule

module histogram_sampler (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // sample-enable; low => whole histogram idles
    input  wire [1:0] i_sel,     // which bin the incoming sample lands in
    output reg  [3:0] bin0,
    output reg  [3:0] bin1,
    output reg  [3:0] bin2,
    output reg  [3:0] bin3,
    output reg  [3:0] total,
output wire       o_full,
output reg  [3:0] ce_ticks,
output reg  [3:0] n_in,
output reg  [3:0] n_out
);
    // sampling window closes after MAXS samples have been binned
    localparam [3:0] MAXS = 4'd12;

   // run-length coalescing: consecutive samples aimed at one bin are counted
   // here and folded into that bin register with a single add
   localparam [1:0] PMAX = 2'd3;

   reg [1:0] pend;      // samples staged but not yet folded into a bin
   reg [1:0] pend_sel;  // bin the staged samples belong to
  // the bin write port is clock-gated with i_ce: a coalesced run is queued
  // here and lands in its bin on the next enabled beat
  reg [3:0] fq;        // run awaiting write-back (0 => queue empty)
  reg [1:0] fq_sel;    // bin the queued run belongs to

    initial bin0  = 4'd0;
    initial bin1  = 4'd0;
    initial bin2  = 4'd0;
    initial bin3  = 4'd0;
    initial total = 4'd0;
   initial pend     = 2'd0;
   initial pend_sel = 2'd0;
  initial fq     = 4'd0;
  initial fq_sel = 2'd0;
initial ce_ticks = 4'd0;
initial n_in  = 4'd0;
initial n_out = 4'd0;

    assign o_full = (total == MAXS);

    wire take = i_ce && (total < MAXS);
   wire same  = (i_sel == pend_sel);
   // window already shut: commit whatever is still staged on the next beat
   wire drain = i_ce && !take;
   wire fold  = (pend != 2'd0) && (drain || (take && (!same || pend == PMAX)));
// in/out sample ledger: samples presented minus samples retired is the
// number still sitting in the staging accumulator
wire [3:0] staged   = n_in - n_out;
// one add commits the whole staged run, plus the in-flight sample when it
// coalesces into the same bin
wire [3:0] fold_amt = staged + ((take && same) ? 4'd1 : 4'd0);
// samples leaving staging this beat: those folded into a bin, plus the
// sample dropped on the floor once the window has shut
wire [3:0] retire   = (fold ? fold_amt : 4'd0) + (drain ? 4'd1 : 4'd0);
// the queued run is written back only on an enabled beat
wire wb = i_ce && (fq != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 4'd0;
           pend     <= 2'd0;
           pend_sel <= 2'd0;
           fq       <= 4'd0;
           fq_sel   <= 2'd0;
ce_ticks <= 4'd0;
n_in     <= 4'd0;
n_out    <= 4'd0;
       end else begin
          if (wb) begin
              case (fq_sel)
2'd0: bin0 <= bin0 + fq;
2'd1: bin1 <= bin1 + fq;
2'd2: bin2 <= bin2 + fq;
2'd3: bin3 <= bin3 + fq;
               endcase
           end
          if (i_ce) begin
              fq <= fold ? fold_amt : 4'd0;
              if (fold)
                  fq_sel <= pend_sel;
          end
           if (take) begin
               pend_sel <= i_sel;
               pend     <= same ? ((pend == PMAX) ? 2'd0 : pend + 2'd1)
                                : 2'd1;
               total    <= total + 4'd1;
           end else if (drain) begin
               pend <= 2'd0;
           end
if (i_ce && ce_ticks != 4'd15)
    ce_ticks <= ce_ticks + 4'd1;
// ledger is pure accounting: it wraps, it is never held off
n_in  <= n_in  + (i_ce ? 4'd1 : 4'd0);
n_out <= n_out + retire;
       end
    end

    // P: no single bin's occupancy can ever exceed the sampling-window size,
    // even though the 4-bit bin register could physically hold 15.
    always @(*)
        assert (bin1 <= MAXS);
endmodule

module chess_clock_seq_alarm (
    input  wire clk,
    input  wire i_ce,      // clock tick enable; low freezes the whole mechanism
    input  wire sym,       // observed press: 1 = white side, 0 = black side
    output reg  alarm
);
    // match-progress register for the fixed press pattern 1,0,1,1
    // (white, black, white, white) -- the blitz alarm trigger
    reg [2:0] prog;
    // shadow register: latches that the half-way progress (2 symbols) occurred
    reg       seen_half;
    // "before R" scope register: high until the alarm pattern first completes
    reg       before_alarm;
   // commit stage: the decoder's next-progress value waits one tick here
   // before it is retired into the matcher, keeping the decode path short
   reg [2:0] stg;
   reg       stg_v;       // a staged progress value is pending commit
  // black-turn tally: how many times the matcher has passed the half-way
  // point since power-up. The blitz time control also ends the game once
  // this tally reaches its limit of seven, so it feeds the alarm too.
  reg [2:0] hcnt;
 // black-side peer matcher for the press pattern 0,1,0,0 (black, white,
 // black, black) -- the other side's blitz trigger. It shares the commit
 // stage and the tally's single increment port with the white-side matcher.
 reg [2:0] prog2;
 reg [2:0] stg2;
 // the tally adder accepts one increment per tick; a half-way pass that
 // loses the arbitration is owed and is retired in the commit phase
 reg       hpend;
 reg       harb;   // round-robin pointer for the tally increment port
// four-deep retire pipeline: a committed progress pair walks cm1..cm4
// (white) / cn1..cn4 (black) one hop per tick before it lands in the
// matchers, so the retire bus is registered at every hop.  cv1..cv4 mark
// which hop currently carries the press in flight.
reg [2:0] cm1, cm2, cm3, cm4;
reg [2:0] cn1, cn2, cn3, cn4;
reg       cv1, cv2, cv3, cv4;

    initial prog         = 3'd0;
    initial seen_half    = 1'b0;
    initial before_alarm = 1'b1;
    initial alarm        = 1'b0;
   initial stg          = 3'd0;
   initial stg_v        = 1'b0;
  initial hcnt         = 3'd0;
 initial prog2        = 3'd0;
 initial stg2         = 3'd0;
 initial hpend        = 1'b0;
 initial harb         = 1'b0;
initial cm1          = 3'd0;
initial cm2          = 3'd0;
initial cm3          = 3'd0;
initial cm4          = 3'd0;
initial cn1          = 3'd0;
initial cn2          = 3'd0;
initial cn3          = 3'd0;
initial cn4          = 3'd0;
initial cv1          = 1'b0;
initial cv2          = 1'b0;
initial cv3          = 1'b0;
initial cv4          = 1'b0;

    reg [2:0] nxt;
   reg [2:0] nxt2;
  // a new press may only be taken once the retire pipeline has drained
  wire idle = !stg_v && !cv1 && !cv2 && !cv3 && !cv4;
   // a press is only consumed in the decode phase
  wire match = (prog == 3'd3) && sym && idle;
 wire match2 = (prog2 == 3'd3) && !sym && idle;
  // tally requests: either matcher asks when it passes its half-way point
  wire req1 = (nxt  == 3'd2);
  wire req2 = (nxt2 == 3'd2);
  wire gnt1 = req1 && (!req2 || !harb);
  wire gnt2 = req2 && (!req1 ||  harb);

    always @(*) begin
        case (prog)
            3'd0: nxt = sym ? 3'd1 : 3'd0;
            3'd1: nxt = sym ? 3'd1 : 3'd2;
            3'd2: nxt = sym ? 3'd3 : 3'd0;
            3'd3: nxt = sym ? 3'd0 : 3'd2;  // overlap: "10" survives
            default: nxt = 3'd0;
        endcase
    end

   always @(*) begin
       case (prog2)
           3'd0: nxt2 = sym ? 3'd0 : 3'd1;
           3'd1: nxt2 = sym ? 3'd2 : 3'd1;
           3'd2: nxt2 = sym ? 3'd0 : 3'd3;
           3'd3: nxt2 = sym ? 3'd2 : 3'd0;  // overlap: "01" survives
           default: nxt2 = 3'd0;
       endcase
   end

    always @(posedge clk) begin
        if (i_ce) begin
          // the retire pipeline advances one hop on every tick
          cm1 <= stg;   cn1 <= stg2;   cv1 <= stg_v;
          cm2 <= cm1;   cn2 <= cn1;    cv2 <= cv1;
          cm3 <= cm2;   cn3 <= cn2;    cv3 <= cv2;
          cm4 <= cm3;   cn4 <= cn3;    cv4 <= cv3;
          if (cv4) begin
              // retire phase: the value that has walked the whole pipeline
              // lands in the two matchers
              prog      <= cm4;
              prog2     <= cn4;
              if (cm4 == 3'd0)
                  seen_half <= 1'b0;   // white matcher restarted
          end
          if (idle) begin
               // decode phase: consume the press, stage the new progress
               stg       <= nxt;
              stg2      <= nxt2;
               stg_v     <= 1'b1;
               seen_half <= seen_half | (nxt == 3'd2);
             if ((gnt1 || gnt2) && (hcnt != 3'd7))
                 hcnt <= hcnt + 3'd1;
             // whichever half-way pass lost the port is owed an increment
             hpend     <= (req1 && !gnt1) || (req2 && !gnt2);
             if (req1 && req2)
                 harb <= ~harb;
              // the alarm sounds on the pattern match, and also on the press
              // that takes the black-turn tally to its limit
             alarm     <= match | match2 |
                          ((gnt1 || gnt2) && (hcnt == 3'd6));
               if (match)
                   before_alarm <= 1'b0;
          end else if (stg_v) begin
              // commit phase: the staged press is handed to the retire
              // pipeline, so the tally adder is free for the owed increment
               stg_v     <= 1'b0;
             // the owed increment retires now that the adder is idle
             if (hpend && (hcnt != 3'd7))
                 hcnt <= hcnt + 3'd1;
             hpend     <= 1'b0;
             alarm     <= hpend && (hcnt == 3'd6);
           end
          else begin
              // the retire pipeline is still draining: no new alarm source
              alarm     <= 1'b0;
          end
        end
    end

    // Precedence, in the scope before the alarm has ever fired:
    // three-quarter progress can only be observed if half progress happened earlier.
    always @(posedge clk)
        assert (!before_alarm || (prog != 3'd3) || seen_half);

   // Tally accounting, in the scope before the alarm has ever fired:
   // three-quarter progress cannot be on record while the black-turn tally
   // is still empty, because reaching it costs one black press.
   always @(posedge clk)
       assert (!before_alarm || (prog != 3'd3) || (hcnt != 3'd0));
endmodule

module token_bucket_deadline (
    input  wire clk,
    input  wire i_ce,
    input  wire req,
    output wire grant,
output wire expired,
output reg [3:0] grant_tally
);
    // burst size of the bucket and the response deadline for one request
    localparam [2:0] BURST   = 3'd4;
    localparam [3:0] TIMEOUT = 4'd6;

    reg [2:0] tokens;    // token bucket, capped at BURST
    reg [1:0] tick_cnt;   // refill timer, counts down, tick at zero
    reg       pending;    // window register: set by accepted request, cleared by grant
    reg [3:0] deadline;   // bounded-response countdown for the pending request
    reg       refill_q;  // staged refill: a tick is captured here and applied to the bucket next cycle
    reg       pending_b;   // second request slot: holds a request that arrived while the head slot was busy
    reg [3:0] deadline_b;  // best-effort countdown for the queued slot
    reg       rr_b;        // arbitration pointer, 1 when the queued slot gets the next token
    reg [2:0] starve;      // consecutive cycles the head slot has waited on a dry bucket

    initial tokens   = BURST;
    initial tick_cnt = 2'd3;
    initial pending  = 1'b0;
    initial deadline = 4'd0;
    initial refill_q = 1'b0;
    initial pending_b  = 1'b0;
    initial deadline_b = 4'd0;
    initial rr_b       = 1'b0;
    initial starve     = 3'd0;
initial grant_tally = 4'd0;

    wire tick     = (tick_cnt == 2'd0);
    wire b_ready    = pending_b && (tokens != 3'd0);
    // the queued slot only pre-empts on its own turn, and only while the
    // bucket still holds a spare token for the head slot
    wire do_grant_b = b_ready && (!pending || (rr_b && (tokens >= 3'd2)));
    wire do_grant = pending && (tokens != 3'd0) && !do_grant_b;
    wire do_refill = refill_q && (tokens < BURST);
    wire any_grant = do_grant || do_grant_b;
    // dry-bucket alarm: the head slot has spent a whole refill interval without a token
    wire dry_alarm = pending && (starve >= 3'd3);

    assign grant   = i_ce && any_grant;
    assign expired = (pending && (deadline == 4'd0)) || (pending_b && (deadline_b == 4'd0)) || dry_alarm;

    // refill timer
    always @(posedge clk) if (i_ce)
        tick_cnt <= tick ? 2'd3 : (tick_cnt - 2'd1);

    // refill request is registered one cycle before it reaches the bucket
    always @(posedge clk) if (i_ce)
        refill_q <= tick;

    // bucket: drains on a grant, refills on a tick, saturates at BURST
    always @(posedge clk) if (i_ce) begin
        if (any_grant && do_refill)
            tokens <= tokens;                 // one out, one in
        else if (any_grant)
            tokens <= tokens - 3'd1;
        else if (do_refill)
            tokens <= tokens + 3'd1;
    end

    // round-robin pointer: whichever slot was served hands the turn over
    always @(posedge clk) if (i_ce) begin
        if (do_grant_b)
            rr_b <= 1'b0;
        else if (do_grant)
            rr_b <= 1'b1;
    end

    // queued slot: captures the request that arrives while the head slot is busy,
    // counts down best effort and drops the request if it runs out
    always @(posedge clk) if (i_ce) begin
        if (do_grant_b)
            pending_b <= 1'b0;
        else if (pending_b) begin
            if (deadline_b == 4'd0)
                pending_b <= 1'b0;
            else
                deadline_b <= deadline_b - 4'd1;
        end else if (req && pending) begin
            pending_b  <= 1'b1;
            deadline_b <= TIMEOUT;
        end
    end

    // request window and its countdown
    always @(posedge clk) if (i_ce) begin
        if (do_grant)
            pending <= 1'b0;
        else if (pending)
            deadline <= deadline - 4'd1;
        else if (req) begin
            pending  <= 1'b1;
            deadline <= TIMEOUT;
        end
    end
    // starvation counter: how many enabled cycles the head request has spent
    // waiting on an empty bucket; cleared as soon as a token is in the bucket
    always @(posedge clk) if (i_ce) begin
        if (!pending || (tokens != 3'd0))
            starve <= 3'd0;
        else
            starve <= starve + 3'd1;
    end

// observational grant tally: counts served requests, wraps freely
always @(posedge clk) if (i_ce) begin
    if (any_grant)
        grant_tally <= grant_tally + 4'd1;
end

    // P: inside the request window the countdown never expires
    always @(posedge clk)
        if (pending) assert (deadline != 4'd0);
    // P2: the dry-bucket counter cannot outlive the request window
    always @(posedge clk)
        if (pending) assert (starve <= 3'd5);
endmodule

module credit_ledger (
    input  wire        clk,
    input  wire        i_ce,
    output wire [4:0]  o_gray,
    output wire        o_drained
);
// up counter and the credit pool stepped by the same enable; the pool is
// split into a reserve tranche and a main balance, and up + pool == 20
    reg [4:0] up;
   // the issue tally is stored as a quad counter plus an offset: up holds
   // the position inside the current group of four credits, up_q counts the
   // groups of four already handed out
   reg [2:0] up_q;
    reg [4:0] dn;
// reserve tranche of the batch: returning credits are charged here first
reg [3:0] resv;

   // the main-balance subtractor is registered: a debit against dn is
   // computed on one enabled cycle and committed on the next
   reg       dn_v;
   reg [4:0] dn_s;

    // shadow register: records that the up counter has already reached 10
    reg       mark;

    // "before R" scope: starts high, cleared the first time the ledger drains
    reg       before_done;
    // ledger counters: one tick per credit handed out, one per credit back
    reg [4:0] n_iss;
    reg [4:0] n_ret;

    initial up          = 5'd0;
initial up_q        = 3'd0;
initial dn          = 5'd12;
initial resv        = 4'd8;
    initial mark        = 1'b0;
    initial before_done = 1'b1;
    initial n_iss       = 5'd0;
    initial n_ret       = 5'd0;
   initial dn_v        = 1'b0;
   initial dn_s        = 5'd11;

    always @(posedge clk) begin
        if (i_ce) begin
if (dn_v) begin
               // commit the registered debit against the main balance
               dn   <= dn_s;
               dn_v <= 1'b0;
           end else if (dn == 5'd0) begin
                before_done <= 1'b0;   // the drained event has been observed
                up          <= 5'd0;   // recharge with a fresh batch of 20
               up_q        <= 3'd0;   // fresh batch: no group issued yet
dn          <= 5'd12;
resv        <= 4'd8;   // fresh batch: reserve tranche refilled
                mark        <= 1'b0;   // new batch: halfway not passed yet
            end else if (n_iss == n_ret) begin
                // nothing outstanding: hand a credit to the consumer
               if (up == 5'd3) begin
                   up   <= 5'd0;          // group complete
                   up_q <= up_q + 3'd1;   // carry into the group counter
               end else begin
                   up   <= up + 5'd1;
               end
               mark  <= mark | ((up_q == 3'd2) && (up == 5'd1));
                n_iss <= n_iss + 5'd1;
            end else begin
// the outstanding credit returns: charge the reserve tranche first and
// only fall back on the main balance once the tranche is dry
if (resv != 4'd0) begin
                   resv <= resv - 4'd1;
               end else begin
                   // stage the debit; it lands on dn next enabled cycle
                   dn_s <= dn - 5'd1;
                   dn_v <= 1'b1;
               end
                n_ret <= n_ret + 5'd1;
            end
        end
    end

    // gray view of the issue pointer (clock-domain-crossing flavour)
    assign o_gray    = n_iss ^ (n_iss >> 1);
assign o_drained = (dn == 5'd0) && (resv == 4'd0) && (up_q == 3'd5) && (n_iss == n_ret);

    // Property: before the ledger has ever drained, seeing fewer than ten
    // credits left means the up counter must already have passed ten.
    always @(*)
        if (before_done && (dn <= 5'd9))
            assert (mark);
endmodule

// Multi-zone thermostat front end with hysteresis and a power budget.
// The active-zone mask is a parity protected register slice; a maintained
// occupancy counter and a remaining-budget counter track it.
module zone_heat_budget (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire [2:0] i_zone,    // zone under consideration this cycle
    input  wire [7:0] i_temp,    // measured temperature of that zone
    output wire       o_fault,   // parity mismatch on the zone slice
    output wire [3:0] o_nact,
output wire [3:0] o_budget,
output reg  [3:0] o_hot_cnt
);
    parameter [7:0] T_LOW  = 8'd40;   // below this, zone asks for heat
    parameter [7:0] T_HIGH = 8'd60;   // above this, zone releases heat
    localparam [3:0] BUDGET = 4'd4;   // at most 4 heaters may run at once
   localparam [3:0] BASE   = BUDGET - 4'd1; // slots in the shared base pool
   localparam [7:0] T_CRIT = 8'd20;  // below this a zone may claim the boost slot

    // ---- parity protected register slice -------------------------------
    reg [7:0] zone;    // one bit per zone heater
    reg       zpar;    // parity bit covering zone
    initial   zone = 8'h00;
    initial   zpar = 1'b0;

    // ---- bookkeeping registers -----------------------------------------
    reg [3:0] nact;    // number of heaters currently on
    reg [3:0] budget;  // remaining power slots
    initial   nact   = 4'd0;
   initial   budget = BASE;

   // The fourth slot is a boost slot: it is handed out only to a deeply
   // cold zone when the base pool is dry, and is tracked back to the zone
   // holding it so it can be returned when that heater goes off again.
   reg       b_used;  // boost slot is committed to a zone
   reg [2:0] b_zone;  // zone holding the boost slot
   initial   b_used = 1'b0;
   initial   b_zone = 3'd0;

   // ---- issue / commit pipeline ---------------------------------------
   // A grant decided this cycle reaches the heater mask on the next cycle;
   // the in-flight grant is held here.  One grant may be in flight.
   reg       p_val;   // a grant is in flight
   reg       p_on;    // 1 = turn the zone on, 0 = turn it off
   reg [2:0] p_zone;  // zone the in-flight grant targets
   initial   p_val  = 1'b0;
   initial   p_on   = 1'b0;
   initial   p_zone = 3'd0;

  // duct partner channel: zones are ducted in pairs, so a zone that is
  // deeply cold also opens its partner's damper.  The partner grant has
  // its own in-flight register but draws from the same base pool.
  reg       q_val;   // a partner grant is in flight (always a turn-on)
  reg [2:0] q_zone;  // partner zone the in-flight grant targets
  initial   q_val  = 1'b0;
  initial   q_zone = 3'd0;
initial   o_hot_cnt = 4'd0;

    wire fault = (zpar != (^zone));
    assign o_fault  = fault;
    assign o_nact   = nact;
   assign o_budget = budget + {3'b000, ~b_used};

    // hysteresis: nothing happens inside the dead band, so no chattering
    wire req_on  = i_ce && !fault && (i_temp <  T_LOW);
    wire req_off = i_ce && !fault && (i_temp >  T_HIGH);

   // forward the in-flight grant, so a zone is never granted twice while
   // its mask bit has not been updated yet
  wire zbit = (p_val && (p_zone == i_zone)) ? p_on :
              (q_val && (q_zone == i_zone)) ? 1'b1 : zone[i_zone];

  // a zone deep in the cold may use the boost slot once the base pool is dry
  wire deep_cold = (i_temp < T_CRIT);
  wire slot_free = (budget != 4'd0) || (!b_used && deep_cold);

  wire do_on  = req_on  && !zbit && slot_free;
   wire do_off = req_off &&  zbit;

   // a power slot is reserved when the grant is issued and released only
   // when the heater has actually been switched off, one cycle later
  wire take_base  = do_on && (budget != 4'd0);
  wire take_boost = do_on && (budget == 4'd0);
  wire rel_boost  = p_val && !p_on && b_used && (p_zone == b_zone);
  wire rel_base   = p_val && !p_on && !rel_boost;

 // the ducted partner of the zone under consideration
 wire [2:0] pz = i_zone ^ 3'd1;
 wire qbit = (p_val && (p_zone == pz)) ? p_on :
             (q_val && (q_zone == pz)) ? 1'b1 : zone[pz];
 // the partner never uses the boost slot: it may only have what is left
 // of the base pool after the primary grant has taken its slot
 wire [3:0] base_left = budget - {3'b000, take_base};
 wire do_hon = do_on && deep_cold && !qbit && (base_left != 4'd0);

    always @(posedge i_clk) begin
        if (i_rst) begin
            zone   <= 8'h00;
            zpar   <= 1'b0;
            nact   <= 4'd0;
           budget <= BASE;
           b_used <= 1'b0;
           b_zone <= 3'd0;
           p_val  <= 1'b0;
           p_on   <= 1'b0;
           p_zone <= 3'd0;
          q_val  <= 1'b0;
          q_zone <= 3'd0;
o_hot_cnt <= 4'd0;
       end else if (i_ce) begin
           // commit stage: apply the grant issued last cycle
          if (p_val) zone[p_zone] <= p_on;
          if (q_val) zone[q_zone] <= 1'b1;
          // each committed grant flips exactly one data bit
          zpar <= zpar ^ p_val ^ q_val;
          nact <= nact + {3'b000, (p_val && p_on)} + {3'b000, q_val}
                       - {3'b000, (p_val && !p_on)};
           // issue stage: latch this cycle's decision
           p_val  <= do_on || do_off;
           p_on   <= do_on;
           p_zone <= i_zone;
         q_val  <= do_hon;
         q_zone <= pz;
         budget <= budget - {3'b000, take_base} - {3'b000, do_hon}
                          + {3'b000, rel_base};
          b_used <= (b_used && !rel_boost) || take_boost;
          if (take_boost)
              b_zone <= i_zone;
o_hot_cnt <= ((i_temp > T_HIGH) && (o_hot_cnt != 4'd15)) ? o_hot_cnt + 4'd1 : o_hot_cnt;
       end
    end

    wire heating = (zone != 8'h00);

    // P: whenever any heater is running, occupancy never exceeds the
    //    power budget of 4 (the counter is 4 bits wide).
    always @(posedge i_clk)
        if (heating)
            assert (nact <= 4'd4);
endmodule

module skid_parity_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // stage enable: low => full idle
    input  wire       i_valid,
    input  wire [7:0] i_data,
    input  wire       i_dready,    // downstream ready
    input  wire       i_close,     // closes the observation window
    output wire       o_ready,
    output reg        o_valid,
output reg  [7:0] o_data,
output reg  [3:0] o_beat_count
);

    // ---- skid buffer stage state ----
    reg        stall;      // skid slot occupied
    reg  [3:0] skid;       // low nibble of the buffered word
    reg  [3:0] skid_hi;    // upper nibble; flops enabled only for wide words
    reg        skid_wide;  // buffered word has a nonzero upper nibble
    reg        skid_par;   // shadow parity of the buffered word

    reg        o_par;      // shadow parity of the presented word

    // ---- observation window (opened by a skid release, closed by i_close) ----
    reg        win;
    reg  [7:0] acc_data;    // xor of words released inside the window
    reg        acc_par;     // xor of their shadow parities

   // ---- pending tracker: window accumulator xor the word still in the skid slot ----
reg  [3:0] pend_lo;      // low nibble of the pending residue
reg  [3:0] pend_hi;      // upper nibble, only clocked while the residue is wide
reg        pend_wide;    // residue currently carries a nonzero upper nibble
reg        pend_par;     // shadow parity of the whole residue
reg        pend_par_hi;  // shadow parity of the tracked upper nibble

    initial begin
        stall    = 1'b0;
        skid      = 4'h0;
        skid_hi   = 4'h0;
        skid_wide = 1'b0;
        skid_par = 1'b0;
        o_valid  = 1'b0;
        o_data   = 8'h00;
        o_par    = 1'b0;
        win      = 1'b0;
        acc_data = 8'h00;
        acc_par  = 1'b0;
pend_lo     = 4'h0;
pend_hi     = 4'h0;
pend_wide   = 1'b0;
pend_par    = 1'b0;
pend_par_hi = 1'b0;
o_beat_count = 4'd0;
    end

    assign o_ready = !stall;

    // reassembled buffered word: narrow words carry an implicit zero nibble
    wire [7:0] skid_word = {(skid_wide ? skid_hi : 4'h0), skid};

   // pending residue: narrow residues present an implicit zero upper nibble,
   // and the fold datapath is only four bits wide
   wire [3:0] pend_hi_cur = pend_wide ? pend_hi : 4'h0;
   wire       pend_ph_cur = pend_wide & pend_par_hi;
   wire [7:0] pend_data   = {pend_hi_cur, pend_lo};
   wire [3:0] pend_hi_nxt = pend_hi_cur ^ i_data[7:4];

    wire do_release = i_ce &&  stall &&  i_dready;
    wire do_direct  = i_ce && !stall &&  i_valid && (i_dready || !o_valid);
    wire do_capture = i_ce && !stall &&  i_valid && o_valid && !i_dready;
    wire do_drop    = i_ce && !stall && !i_valid && i_dready && o_valid;

    always @(posedge clk) begin
        if (rst) begin
            stall    <= 1'b0;
            skid      <= 4'h0;
            skid_hi   <= 4'h0;
            skid_wide <= 1'b0;
            skid_par <= 1'b0;
            o_valid  <= 1'b0;
            o_data   <= 8'h00;
            o_par    <= 1'b0;
            win      <= 1'b0;
            acc_data <= 8'h00;
            acc_par  <= 1'b0;
pend_lo     <= 4'h0;
pend_hi     <= 4'h0;
pend_wide   <= 1'b0;
pend_par    <= 1'b0;
pend_par_hi <= 1'b0;
o_beat_count <= 4'd0;
        end else begin
            // datapath
            if (do_release) begin
                o_valid <= 1'b1;
                o_data  <= skid_word;
                o_par   <= skid_par;
                stall   <= 1'b0;
            end else if (do_direct) begin
                o_valid <= 1'b1;
                o_data  <= i_data;
                o_par   <= ^i_data;
            end else if (do_capture) begin
                stall    <= 1'b1;
                skid      <= i_data[3:0];
                if (i_data[7:4] != 4'h0) begin
                    skid_hi   <= i_data[7:4];
                    skid_wide <= 1'b1;
                end else begin
                    skid_wide <= 1'b0;
                end
                skid_par <= ^i_data;
            end else if (do_drop) begin
                o_valid <= 1'b0;
            end

            // window: opened by a release, closed by i_close
            if (i_ce) begin
                if (i_close)         win <= 1'b0;
                else if (do_release) win <= 1'b1;
            end

            // in-window accumulation of released words
            if (do_release) begin
                if (win) begin
                    acc_data <= acc_data ^ skid_word;
                    acc_par  <= acc_par  ^ skid_par;
                end else begin
                    acc_data <= skid_word;
                    acc_par  <= skid_par;
                end
            end

          // pending tracker: a capture folds straight in through a four bit
          // datapath, so the upper nibble sits in its own slot and is only
          // clocked while the residue stays wide; a window close re-primes the
          // tracker with whatever word is still sitting in the skid slot
          if (i_ce && i_close) begin
              if (do_capture) begin
                  pend_lo   <= i_data[3:0];
                  pend_par  <= ^i_data;
                  if (i_data[7:4] != 4'h0) begin
                      pend_hi     <= i_data[7:4];
                      pend_par_hi <= ^i_data[7:4];
                      pend_wide   <= 1'b1;
                  end else begin
                      pend_wide   <= 1'b0;
                  end
              end else if (stall && !do_release) begin
                  pend_lo     <= skid;
                  pend_par    <= skid_par;
                  pend_hi     <= skid_hi;
                  pend_par_hi <= ^skid_hi;
                  pend_wide   <= skid_wide;
              end else begin
                  pend_lo   <= 4'h0;
                  pend_par  <= 1'b0;
                  pend_wide <= 1'b0;
              end
          end else if (do_capture) begin
              pend_lo <= pend_lo ^ i_data[3:0];
              if (i_data[7:4] != 4'h0) begin
                  if (pend_hi_nxt != 4'h0) begin
                      pend_hi     <= pend_hi_nxt;
                      pend_par_hi <= pend_ph_cur ^ (^i_data[7:4]);
                      pend_wide   <= 1'b1;
                      pend_par    <= pend_par ^ (^i_data);
                  end else begin
                      // upper nibble cancels out: retract its tracked parity
                      // instead of re-folding the whole byte
                      pend_wide <= 1'b0;
                      pend_par  <= pend_par ^ pend_par_hi ^ (^i_data[3:0]);
                  end
              end else begin
                  pend_par <= pend_par ^ (^i_data[3:0]);
              end
          end
if (i_ce) begin
   if (i_close && win)
       o_beat_count <= {3'd0, pend_par};   // close restarts the count, flagging leftover residue
   else
       o_beat_count <= o_beat_count + 4'd1;
end
        end
    end

    // ---- property: inside the window, both shadow parities track their words ----
    always @(posedge clk) begin
        if (win) begin
            assert (o_par   == (^o_data));
            assert (acc_par == (^acc_data));
        end
    end

   // ---- property: inside the window, the residue still owed to the accumulator
   //      (pending tracker xor accumulator) carries a correct shadow parity ----
   always @(posedge clk) begin
       if (win) begin
           assert ((pend_par ^ acc_par) == (^(pend_data ^ acc_data)));
       end
   end

endmodule

module dma_burst_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // engine clock-enable / idle when low
    input  wire       i_start,   // Q: opens the transfer window
    input  wire [3:0] i_len,     // burst length in beats
    input  wire       i_ack,     // R: closes the transfer window
    output wire       o_busy,
output wire       o_drained,
output reg  [3:0] o_ack_cnt
);

    // beats-remaining counter and the two status flags derived from it
    reg [3:0] beats_left;
    reg       busy;
    reg       drained;

    // window register: set by a new burst (Q), cleared by the ack (R)
    reg       win;

    // commit-stage register: the next beat count is held here for one cycle
    // before it is written into the beats-remaining counter
    reg [3:0] stg_beats;
    reg       stg_vld;

   // unpipelined shadow of the beats-remaining count: the issue stage keeps
   // its own copy so downstream flow control does not have to wait a cycle
   // for the commit stage to update beats_left
   reg [3:0] shadow;

  // registered copy of the ack input (status only)
   reg       ack_seen;

  // window ledger: one counter logs every transfer window that opens, the
  // other logs every window that closes.  The pair is exported as the
  // status word so a host can audit descriptor/ack pairing; both wrap.
  reg [1:0] n_win_opn;
  reg [1:0] n_win_cls;

  // window events, shared by the window register and the ledger
  wire win_set = i_start && !busy;
  wire win_clr = !win_set && i_ack;

  // the ledger's view of whether a transfer window is outstanding
  wire ledger_open = (n_win_opn != n_win_cls);

    // forwarded count: the in-flight value whenever a commit is pending
    wire [3:0] beats_cur = stg_vld ? stg_beats : beats_left;


    initial beats_left = 4'd0;
    initial busy       = 1'b0;
    initial drained    = 1'b1;
    initial win        = 1'b0;
    initial stg_beats  = 4'd0;
    initial stg_vld    = 1'b0;
   initial shadow     = 4'd0;
   initial ack_seen   = 1'b0;
  initial n_win_opn  = 2'd0;
  initial n_win_cls  = 2'd0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            busy       <= 1'b0;
            drained    <= 1'b1;
            win        <= 1'b0;
            stg_beats  <= 4'd0;
            stg_vld    <= 1'b0;
           shadow     <= 4'd0;
           ack_seen   <= 1'b0;
          n_win_opn  <= 2'd0;
          n_win_cls  <= 2'd0;
        end else if (i_ce) begin
            // commit stage: the registered count reaches the counter
            if (stg_vld) begin
                beats_left <= stg_beats;
                stg_vld    <= 1'b0;
            end
            // issue stage: a descriptor load or a beat retire posts the new
            // status flags now and hands the count to the commit stage
            if (i_start && !busy) begin
                // load a new burst descriptor and open the window
                stg_beats  <= i_len;
                stg_vld    <= 1'b1;
               shadow     <= i_len;
                busy       <= (i_len != 4'd0);
                drained    <= (i_len == 4'd0);
                win        <= 1'b1;
            end else if (busy) begin
               // retire one beat off the forwarded count.  A window that
               // has already been closed abandons whatever beats are left:
               // the reported status follows the ledger, the beat counts
               // follow the window register the datapath is wired to.
               stg_beats  <= ledger_open ? (beats_cur - 4'd1) : 4'd0;
               stg_vld    <= 1'b1;
               shadow     <= win ? (beats_cur - 4'd1) : 4'd0;
               busy       <= win && (beats_cur != 4'd1);
               drained    <= !ledger_open || (beats_cur <= 4'd1);
                if (i_ack)
                    win <= 1'b0;
            end else if (i_ack) begin
                // close the window between transfers
                win <= 1'b0;
            end
          // ledger: log the window opens and closes as they happen
          if (win_set && !win)
              n_win_opn <= n_win_opn + 2'd1;
          if (win_clr && win)
              n_win_cls <= n_win_cls + 2'd1;
           ack_seen <= i_ack;
        end
    end

    assign o_busy    = busy;
    assign o_drained = drained;

   // status word: the window ledger, opens in the high half, closes in the low
   always @(*)
       o_ack_cnt = {n_win_opn, n_win_cls};

    // P: inside an open transfer window the engine is never simultaneously
    // reporting "busy" and "drained".
    always @(posedge i_clk)
        if (win)
            assert (!(busy && drained));

   // Q: the engine reports "drained" only once the issue-stage shadow has
   // counted the burst all the way down to zero beats.
   always @(posedge i_clk)
       assert (!drained || (shadow == 4'd0));

endmodule

module deb_evt_fifo (
    input  wire clk,
    input  wire i_ce,      // sample enable: low freezes all state
    input  wire raw,       // raw (noisy) button level
    input  wire pop,       // consumer request
    output wire empty,
    output wire full,
    output reg  o_level    // last popped debounced level
);
    // ---- debouncer: saturating stability counter ----
    reg [1:0] stab;
    reg       deb;

    // ---- event FIFO: pointers + occupancy ----
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg [1:0] tail;        // shadow: write pointer snapshot taken at the last push
    reg       mem [0:3];
   reg [1:0] wnext;       // precomputed next write address (shared write-port adder)

   // ---- refresh generator: periodic level-refresh events ----
   // second producer on the shared FIFO write port: every fourth sample it
   // re-posts the current debounced level so a stalled consumer still gets a
   // fresh entry. Edge events own the port; a coincident refresh is held.
   reg [1:0] hb;
   reg       hb_pend;

   // ---- event ledger: free-running push/pop transfer counters ----
// a push is logged when the entry is written, a pop when the consumer's
// request is accepted, so the ledger difference is the number of entries
// not yet spoken for; empty is taken from it and therefore also throttles
// request acceptance. full is taken from the occupancy accumulator: a slot
// whose read is still in flight is not free for rewrite.
   reg [2:0] n_push, n_pop;
   wire [2:0] occ = n_push - n_pop;   // outstanding entries, mod 8

  // ---- read data phase: four-sample memory access latency ----
  // a pop request is acknowledged to the ledger the sample it is accepted,
  // but the entry is only retired -- rptr stepped and o_level updated --
  // when the request walks out of the access pipeline four samples later.
  reg       pop_s0, pop_s1, pop_s2, pop_s3;

  // ---- registered write port: capture stage in front of the array ----
  // the array has a registered write path: a push captures the slot address
  // and the level on one sample and the array cell is written the next. the
  // write pointer advances at capture so a following event addresses the next
  // slot, but the slot only counts as occupancy once the write has landed,
  // and the capture stage holds one transfer, so a push waits while one is in
  // flight. the entry is announced to the consumer at capture: the read data
  // phase is four samples long, so the write has landed before the read runs.
  reg       wr_pend;
  reg [1:0] wr_addr;
  reg       wr_data;

  // ---- array port ledger: free-running write/read access counters ----
  // the arbiter logs every array access: a write when it lands, a read when
  // its data phase runs. the excess of landed writes over performed reads is
  // the number of slots resident in the array, and a resident slot is not
  // available for rewrite, so the write-side backpressure comes from here.
  reg [2:0] n_wr, n_rd;
  wire [2:0] resident = n_wr - n_rd;

    // ---- scope register: high until the FIFO has ever been full ----
    reg       never_full;

    // ---- past-valid ----
    reg       pv;

    initial begin
        stab = 2'd0; deb = 1'b0;
        wptr = 2'd0; rptr = 2'd0; count = 3'd0;
        tail = 2'd0;
       wnext = 2'd1;
       hb = 2'd0; hb_pend = 1'b0;
       n_push = 3'd0; n_pop = 3'd0;
      wr_pend = 1'b0; wr_addr = 2'd0; wr_data = 1'b0;
      n_wr = 3'd0; n_rd = 3'd0;
pop_s0 = 1'b0; pop_s1 = 1'b0; pop_s2 = 1'b0; pop_s3 = 1'b0;
        never_full = 1'b1;
        pv = 1'b0;
        o_level = 1'b0;
        mem[0] = 1'b0; mem[1] = 1'b0; mem[2] = 1'b0; mem[3] = 1'b0;
    end

   assign empty = (occ == 3'd0);
assign full  = (resident == 3'd4);

    // a debounced edge is committed once raw has disagreed with deb for 3 samples
    wire deb_commit = (raw != deb) && (stab == 2'd2);

   wire hb_req   = (hb == 2'd3) || hb_pend;
   wire push_req = deb_commit || hb_req;
wire do_push  = i_ce && push_req && !full && !wr_pend;  // capture at the write port
wire wr_cmt   = i_ce && wr_pend;                        // captured transfer lands
wire pop_ack = i_ce && pop && !empty;   // request accepted this sample
wire do_pop  = i_ce && pop_s3;          // its data phase, four samples on

    always @(posedge clk) begin
        if (i_ce) begin
            if (raw != deb) begin
                if (stab == 2'd2) stab <= 2'd0;
                else              stab <= stab + 2'd1;
            end else begin
                stab <= 2'd0;
            end
            if (deb_commit) deb <= raw;

           // the captured transfer reaches the array one sample on
           if (wr_cmt) begin
               mem[wr_addr] <= wr_data;
               wr_pend      <= 1'b0;
           end


            if (do_push) begin
              wr_pend   <= 1'b1;
              wr_addr   <= wptr;
              wr_data   <= deb_commit ? raw : deb;
               wptr      <= wnext;
               tail      <= wnext;
               wnext     <= wnext + 2'd1;
            end

           // the refresh prescaler runs off the sample clock; a refresh
           // request retires only once it actually wins the write port
           hb <= hb + 2'd1;
if (hb_req) hb_pend <= deb_commit || full || wr_pend;

           // walk accepted read requests down the access pipeline
           pop_s0 <= pop_ack;
           pop_s1 <= pop_s0;
           pop_s2 <= pop_s1;
           pop_s3 <= pop_s2;

            if (do_pop) begin
                o_level <= mem[rptr];
                rptr    <= rptr + 2'd1;
            end

// log the push at the write and the pop at the accept, so the
// difference excludes reads that are still in flight
           if (do_push) n_push <= n_push + 3'd1;
if (pop_ack) n_pop  <= n_pop  + 3'd1;

          // and log the array accesses themselves
          if (wr_cmt) n_wr <= n_wr + 3'd1;
          if (do_pop) n_rd <= n_rd + 3'd1;

case ({wr_cmt, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase

            if (count == 3'd4) never_full <= 1'b0;
        end
        pv <= 1'b1;
    end

    // Precedence, before-first-full scope, stated about the previous cycle:
    // if the queue has just been drained empty by a pop, the read pointer must
    // have reached the write-pointer snapshot recorded at the earlier push.
    always @(posedge clk)
        if (pv && never_full && (count == 3'd0) && $past(do_pop))
            assert (rptr == $past(tail));
endmodule

// Valid/ready pipeline stage with a skid buffer carrying a three-step
// command chain: ARM -> START -> FINISH -> ARM -> ...
// The buffered word is only meaningful while the stage is stalled.
module chain_skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,       // global enable / idle condition
    input  wire       in_valid,   // producer offers its next chain word
    input  wire       out_ready,  // consumer accepts
    output wire       o_valid,
    output wire [1:0] o_code,
output wire       o_in_ready,
output wire [3:0] o_fire_count
);
    localparam [1:0] ARM    = 2'd1;
    localparam [1:0] START  = 2'd2;
    localparam [1:0] FINISH = 2'd3;

    // producer chain position: next word emitted is src_phase+1
    reg [1:0] src_phase  = 2'd0;
    // consumer chain position: 0 = nothing armed, 1 = armed, 2 = started
    reg [1:0] phase      = 2'd0;

    // output (skid) register pair
    reg       out_valid  = 1'b0;
    reg [1:0] out_code   = ARM;
    reg       skid_valid = 1'b0;
    reg [1:0] skid_code  = ARM;

   // second (tail) skid slot: lets the stage swallow one more word when the
   // consumer stalls for two cycles in a row instead of dropping in_ready
   // immediately behind a single buffered word
   reg       skid2_valid = 1'b0;
   reg [1:0] skid2_code  = ARM;

   // one-cycle inter-chain gap: after a FINISH leaves the stage the
   // producer is held off for a cycle so it can resynchronise on the
   // head of the next chain
   reg       gap        = 1'b0;

// in-flight word ledger: every word taken from the producer and every word
// handed to the consumer is logged. The counters free-run and wrap; their
// difference is how many words the stage is currently holding, and that is
// what the backpressure below is derived from (head + tail + output = 3).
// Both counters are exported packed on the trace port.
reg [1:0] n_in  = 2'd0;
reg [1:0] n_out = 2'd0;

    wire [1:0] in_code  = src_phase + 2'd1;
wire [1:0] led_occ  = n_in - n_out;
wire       in_ready = (led_occ != 2'd3) && !gap;
    wire       out_room = !out_valid || out_ready;
    wire       in_fire  = step && in_valid && in_ready;
    wire       out_fire = step && out_valid && out_ready;

    assign o_valid    = out_valid;
    assign o_code     = out_code;
    assign o_in_ready = in_ready;
assign o_fire_count = {n_in, n_out};

    always @(posedge clk) begin
        if (rst) begin
            src_phase  <= 2'd0;
            phase      <= 2'd0;
            out_valid  <= 1'b0;
            out_code   <= ARM;
            skid_valid <= 1'b0;
            skid_code  <= ARM;
           skid2_valid <= 1'b0;
           skid2_code  <= ARM;
           gap        <= 1'b0;
n_in       <= 2'd0;
n_out      <= 2'd0;
        end else if (step) begin
            // output register: drain skid first, else take the fresh word
            if (out_room) begin
                if (skid_valid) begin
                    out_valid <= 1'b1;
                    out_code  <= skid_code;
               end else if (in_valid && in_ready) begin
                    out_valid <= 1'b1;
                    out_code  <= in_code;
                end else begin
                    out_valid <= 1'b0;
                end
            end

            // skid buffer: only loaded while the stage is stalled
            if (skid_valid) begin
               if (out_room) begin
                   // head drains into the output register; refill it from
                   // the tail slot, or straight from the producer
                   if (skid2_valid) begin
                       skid_valid <= 1'b1;
                       skid_code  <= skid2_code;
                   end else if (in_valid && in_ready) begin
                       skid_valid <= 1'b1;
                       skid_code  <= in_code;
                   end else begin
                       skid_valid <= 1'b0;
                   end
               end
           end else if (in_valid && in_ready && !out_room) begin
                skid_valid <= 1'b1;
                skid_code  <= in_code;
            end

           // tail slot: only fills behind a full head slot while the
           // output register is blocked, and always shifts down on a drain
           if (skid2_valid) begin
               if (out_room)
                   skid2_valid <= 1'b0;
           end else if (in_valid && in_ready && skid_valid && !out_room) begin
               skid2_valid <= 1'b1;
               skid2_code  <= in_code;
           end

            // producer advances on every accepted word
            if (in_valid && in_ready)
                src_phase <= (src_phase == 2'd2) ? 2'd0 : src_phase + 2'd1;

            // consumer chain tracker advances on every delivered word
            if (out_valid && out_ready)
                phase <= (out_code == FINISH) ? 2'd0 : out_code;

           // hold the producer off for one cycle after a completed chain
           gap <= out_valid && out_ready && out_code == FINISH;

if (in_valid && in_ready)
    n_in <= n_in + 2'd1;
if (out_valid && out_ready)
    n_out <= n_out + 2'd1;
        end
    end

    // P (two assertions): a later chain step is never delivered unless the
    // earlier ones already were.
    always @(*)
        assert (!(out_fire && out_code == FINISH) || phase == 2'd2);

    always @(*)
        assert (!(out_fire && out_code == START) || phase == 2'd1);

   // Q: the only word that may leave the stage during the post-FINISH
   // gap cycle is the ARM that opens the next chain.
   always @(posedge clk)
       if (!rst)
           assert (!(gap && out_fire) || out_code == ARM);
endmodule

module pingpong_tile_buffer (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire       wr_en,
    input  wire       rd_en,
    input  wire [7:0] wr_data,
    output reg  [7:0] rd_data,
output wire       o_sel,
output reg  [7:0] o_wr_tally
);
    localparam [1:0] LAST = 2'd3;

    // ping-pong double buffer: one half owned by the rasterizer (writer),
    // the other half owned by the shader fetch port (reader)
    reg       sel;                 // master ping-pong select bit
    reg       wr_half, rd_half;    // half currently addressed by each port
    reg [1:0] wcnt, rcnt;          // offset inside the owned half
   // programmable tile geometry: the two halves are packed back to back in
   // the RAM, so the upper half starts one entry past the last entry of the
   // lower half. tile_len is the index of the last entry of a half and only
   // moves at turnaround; tile_cfg stages the geometry of the next tile and
   // is posted by the rasterizer as a write issued while its half is closed.
   reg [1:0] tile_len, tile_cfg;
    reg       wr_full, rd_empty;   // per-half handshake flags
   // buffer-turnaround commit pipeline: the ownership swap is handed to the
   // memory system and retires four cycles later, so both ports keep their
   // current half assignment until the request has walked all four stages
   reg       swp_v0, swp_v1, swp_v2, swp_v3;   // request valid, per stage
   reg       swp_d0, swp_d1, swp_d2, swp_d3;   // pending select, per stage
  // turnaround ledger for the memory-system interface: every issued swap
  // request is logged on n_iss and every retired one on n_ret. The port
  // allows a single outstanding turnaround, so the two logs must agree
  // again before a new request may be handed over. Free-running, wrapping.
  reg [3:0] n_iss, n_ret;
reg [7:0] last_byte;
    reg [7:0] mem [0:7];
    integer   i;

    initial begin
        sel     = 1'b0;
        wr_half = 1'b0;
        rd_half = 1'b1;
        wcnt    = 2'd0;
        rcnt    = 2'd0;
      tile_len = LAST;
      tile_cfg = LAST;
        wr_full = 1'b0;
        rd_empty= 1'b1;
       swp_v0  = 1'b0;
       swp_v1  = 1'b0;
       swp_v2  = 1'b0;
       swp_v3  = 1'b0;
       swp_d0  = 1'b0;
       swp_d1  = 1'b0;
       swp_d2  = 1'b0;
       swp_d3  = 1'b0;
       n_iss   = 4'd0;
       n_ret   = 4'd0;
        rd_data = 8'h00;
o_wr_tally = 8'h00;
last_byte  = 8'h00;
        for (i = 0; i < 8; i = i + 1) mem[i] = 8'h00;
    end

   wire [2:0] half_base = {1'b0, tile_len} + 3'd1;
   wire [2:0] wr_addr = wr_half ? half_base + {1'b0, wcnt} : {1'b0, wcnt};
   wire [2:0] rd_addr = rd_half ? half_base + {1'b0, rcnt} : {1'b0, rcnt};

    wire w_step = i_ce && wr_en && !wr_full;
    wire r_step = i_ce && rd_en && !rd_empty;
   wire cfg_wr = i_ce && wr_en && wr_full;   // geometry post, not a data beat
  wire ld_outst   = (n_iss != n_ret);   // a logged turnaround is unretired
  wire swap       = i_ce && wr_full && rd_empty && !ld_outst;
   wire swp_commit = i_ce && swp_v3;

    assign o_sel = sel;

    always @(posedge clk) begin
        if (rst) begin
            sel      <= 1'b0;
            wr_half  <= 1'b0;
            rd_half  <= 1'b1;
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
          tile_len <= LAST;
          tile_cfg <= LAST;
            wr_full  <= 1'b0;
            rd_empty <= 1'b1;
           swp_v0   <= 1'b0;
           swp_v1   <= 1'b0;
           swp_v2   <= 1'b0;
           swp_v3   <= 1'b0;
           swp_d0   <= 1'b0;
           swp_d1   <= 1'b0;
           swp_d2   <= 1'b0;
           swp_d3   <= 1'b0;
           n_iss    <= 4'd0;
           n_ret    <= 4'd0;
o_wr_tally <= 8'h00;
last_byte  <= 8'h00;
       end else if (swp_commit) begin
           sel      <= swp_d3;
           wr_half  <= swp_d3; // writer takes the freshly drained half
           rd_half  <=  sel;   // reader takes the freshly filled half
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
            wr_full  <= 1'b0;
            rd_empty <= 1'b0;
          tile_len <= tile_cfg;   // next tile's geometry takes effect here
        end else begin
            if (w_step) begin
                mem[wr_addr] <= wr_data;
               if (wcnt == tile_len) begin
                   wcnt    <= 2'd0;
                   wr_full <= 1'b1;
               end else begin
                   wcnt <= wcnt + 2'd1;
               end
            end
            if (r_step) begin
                rd_data <= mem[rd_addr];
               if (rcnt == tile_len) begin
                   rcnt     <= 2'd0;
                   rd_empty <= 1'b1;
               end else begin
                   rcnt <= rcnt + 2'd1;
               end
            end
        end

       // the turnaround request advances one stage per enabled cycle
       if (!rst && i_ce) begin
           swp_v3 <= swp_v2;   swp_d3 <= swp_d2;
           swp_v2 <= swp_v1;   swp_d2 <= swp_d1;
           swp_v1 <= swp_v0;   swp_d1 <= swp_d0;
           swp_v0 <= swap;     swp_d0 <= ~sel;
          if (swap)       n_iss <= n_iss + 4'd1;
          if (swp_commit) n_ret <= n_ret + 4'd1;
       end
if (!rst && i_ce) begin
    if (w_step) last_byte  <= wr_data;
   if (cfg_wr) tile_cfg <= wr_data[1:0];
    if (r_step) o_wr_tally <= o_wr_tally + last_byte;
end
    end

    // P: whenever both ports perform an access in the same cycle they never
    // touch the same buffer location
    always @(posedge clk)
        if (i_ce && wr_en && rd_en && !wr_full && !rd_empty)
            assert (wr_addr != rd_addr);
endmodule

// Kernel task handshake tracker.
// The progress accumulator is kept in two carry-save halves acc_a/acc_b whose
// sum is the true phase count (0=idle, 1=armed, 2=started, 3=finished).
// A tiny FSM (ph_ref) enforces the arm -> start -> finish chain, and sticky
// flags record that each earlier step was really observed.
module cs_chain_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       i_track,   // Q event: arms the observation scope, sticky
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_finish,
    output wire [3:0] o_total,
    output wire       o_done
);
    // carry-save halves of the progress accumulator
    reg [2:0] acc_a, acc_b;
    // redundant direct copy of the phase, used by the sequencer
    reg [2:0] ph_ref;
// accumulator port credit ledger: each accepted advance issues one
// increment request, the commit stage retires one per enabled cycle.
// Both counters free-run and wrap at four bits.
reg [3:0] n_iss, n_cmt;
// the shared increment port stays busy while a credit is unretired
wire      port_busy = (n_iss != n_cmt);
    // chain witnesses
    reg       arm_seen, start_seen;
    // sticky scope register (set the first time i_track is seen)
    reg       armed;
   // stage-2 drain chain: reuses the same handshake strobes once stage 1 retired
   reg [2:0] ph_ref2;
   // sticky flag: the drain chain reached its final phase
   reg       b_done;
  // stage-3 writeback chain: reuses the same strobes after the drain retired
  reg [2:0] ph_ref3;
  // sticky flag: the writeback chain reached its final phase
  reg       c_done;

 // retire threshold: how many handshake steps a stage must complete before it
 // releases the shared increment port to the next stage. The host selects the
 // short (arm/start only) protocol by presenting i_finish with the track event.
 reg [2:0] lim;

    initial begin
        acc_a      = 3'd0;
        acc_b      = 3'd0;
        ph_ref     = 3'd0;
n_iss      = 4'd0;
n_cmt      = 4'd0;
        arm_seen   = 1'b0;
        start_seen = 1'b0;
        armed      = 1'b0;
       ph_ref2    = 3'd0;
       b_done     = 1'b0;
      ph_ref3    = 3'd0;
      c_done     = 1'b0;
     lim        = 3'd3;
    end

    // true total recombined from the two halves
    wire [3:0] total = {1'b0, acc_a} + {1'b0, acc_b};
// report the committed total plus the credit still in flight
assign o_total = total + {3'd0, port_busy};
  assign o_done  = (total == 4'd3) || b_done || c_done;

    // one chain step at a time, in order
wire adv = i_ce && !port_busy && (((ph_ref == 3'd0) && i_arm)    ||
                        ((ph_ref == 3'd1) && i_start)  ||
                        ((ph_ref == 3'd2) && i_finish));

   // the drain chain may only take the shared accumulator once stage 1 retired
wire adv2 = i_ce && !port_busy && (ph_ref >= lim) && !adv &&
                       (((ph_ref2 == 3'd0) && i_arm)   ||
                        ((ph_ref2 == 3'd1) && i_start) ||
                        ((ph_ref2 == 3'd2) && i_finish));

  // the writeback chain only takes the shared accumulator once the drain retired
wire adv3 = i_ce && !port_busy && (ph_ref2 >= lim) && !adv && !adv2 &&
                      (((ph_ref3 == 3'd0) && i_arm)   ||
                       ((ph_ref3 == 3'd1) && i_start) ||
                       ((ph_ref3 == 3'd2) && i_finish));

   // shared increment port into the carry-save halves
  wire inc = adv || adv2 || adv3;

    always @(posedge clk) begin
        if (rst) begin
            acc_a      <= 3'd0;
            acc_b      <= 3'd0;
            ph_ref     <= 3'd0;
n_iss      <= 4'd0;
n_cmt      <= 4'd0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            armed      <= 1'b0;
           ph_ref2    <= 3'd0;
           b_done     <= 1'b0;
          ph_ref3    <= 3'd0;
          c_done     <= 1'b0;
         lim        <= 3'd3;
        end else begin
            if (i_ce && i_track)
                armed <= 1'b1;

           // the retire threshold is only re-programmed between runs, while
           // stage 1 is still idle
           if (i_ce && i_track && (ph_ref == 3'd0))
               lim <= i_finish ? 3'd2 : 3'd3;

// issue side of the ledger: one credit per accepted advance
if (inc)
    n_iss <= n_iss + 4'd1;

// commit side: the outstanding credit lands in the halves; the parity
// of the commit count picks which half receives it
if (i_ce && port_busy) begin
    if (n_cmt[0]) acc_b <= acc_b + 3'd1;
    else          acc_a <= acc_a + 3'd1;
    n_cmt <= n_cmt + 4'd1;
end

           if (adv) begin
               ph_ref <= ph_ref + 3'd1;

                if (ph_ref == 3'd0) arm_seen   <= 1'b1;
                if (ph_ref == 3'd1) start_seen <= 1'b1;
            end

           if (adv2) begin
               ph_ref2 <= ph_ref2 + 3'd1;
               if (ph_ref2 == 3'd2) b_done <= 1'b1;
           end

          if (adv3) begin
              ph_ref3 <= ph_ref3 + 3'd1;
              if (ph_ref3 == 3'd2) c_done <= 1'b1;
          end
        end
    end

    // Chain precedence, in the sticky "after i_track" scope:
    // a finished accumulation can never be observed unless both the arm and
    // the start steps were witnessed first.
    always @(*)
        if (armed && (total == 4'd3))
            assert (start_seen && arm_seen);
endmodule

module credit_deadline (
    input  wire clk,
    input  wire i_ce,      // global enable: low => all state frozen
    input  wire rst,
    input  wire req,       // producer wants to spend a credit
    output wire grant,
output wire busy,
output reg [3:0] req_hist
);
    localparam [2:0] TOTAL = 3'd4;   // configured credit pool

    // credits held by the producer, credits outstanding at the consumer
    reg [2:0] credits;
    reg [2:0] outst;
    // consumer needs two enabled cycles to retire one outstanding credit
    reg       svc;
    // bounded-response deadline countdown for the outstanding credits
    reg [3:0] timer;
   // deferred deadline budget for the credits queued behind the head
   reg [3:0] bank;
   // governor watermark: deepest outstanding occupancy seen so far
   reg [2:0] peak;
reg last_req;

    initial begin
        credits = 3'd4;
        outst   = 3'd0;
        svc     = 1'b0;
        timer   = 4'd0;
       bank    = 4'd0;
       peak    = 3'd0;
req_hist = 4'd0;
last_req = 1'b0;
    end

   // once occupancy has ever peaked at the whole pool, hold off new
   // spends until the consumer has drained completely
   wire throttle  = (peak == TOTAL) && (outst != 3'd0);
  // admission control: a new spend must be able to park its two cycle
  // budget behind the head credit, so the bank has to have room
  wire bank_room = (bank <= 4'd4);
  wire do_spend  = req && (credits != 3'd0) && !throttle && bank_room;
    wire do_return = (outst != 3'd0) && (svc == 1'b1);
   wire [2:0] outst_nxt = outst + (do_spend  ? 3'd1 : 3'd0)
                                - (do_return ? 3'd1 : 3'd0);

  // a retiring head hands the deadline of the next credit out of the bank
  wire [3:0] bank_in   = bank + ((do_spend && (outst != 3'd0)) ? 4'd2 : 4'd0);
  wire [3:0] bank_take = (bank_in >= 4'd2) ? 4'd2 : bank_in;
  wire       reload    = do_return && (outst_nxt != 3'd0);

    assign grant = i_ce && do_spend;
    assign busy  = (outst != 3'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            if (rst) begin
                credits <= TOTAL;
                outst   <= 3'd0;
                svc     <= 1'b0;
                timer   <= 4'd0;
               bank    <= 4'd0;
               peak    <= 3'd0;
req_hist <= 4'd0;
last_req <= 1'b0;
            end else begin
                // credit conservation: one token moves per event
                credits <= credits - (do_spend  ? 3'd1 : 3'd0)
                                   + (do_return ? 3'd1 : 3'd0);
                outst   <= outst   + (do_spend  ? 3'd1 : 3'd0)
                                   - (do_return ? 3'd1 : 3'd0);

                // two-cycle service phase per outstanding credit
                if (outst == 3'd0)
                    svc <= 1'b0;
                else
                    svc <= ~svc;

               // watermark only ever rises
               if (outst_nxt > peak)
                   peak <= outst_nxt;

               // deadline budget: the head credit owns a two cycle deadline;
               // the budget of the credits queued behind it waits in the bank
               if (reload)
                   timer <= bank_take;
               else if (do_return)
                   timer <= 4'd0;
               else if (do_spend && (outst == 3'd0))
                   timer <= 4'd2;
               else
                   timer <= timer - ((timer != 4'd0) ? 4'd1 : 4'd0);

               bank <= bank_in - (reload ? bank_take : 4'd0);

// observability only: rolling history of the req input
last_req <= req;
req_hist <= {req_hist[2:0], last_req};
            end
        end
    end

    // Bounded response (safety): the countdown must never expire while a
    // credit is still outstanding at the consumer.
    always @(posedge clk)
        if (outst != 3'd0)
            assert (timer != 4'd0);

   // Quiescence (safety): once the whole pool is back at the producer
   // there is nothing left at the consumer, so the service phase must be
   // idle and the deadline budget must be fully spent.
   always @(posedge clk)
       if (credits == TOTAL)
           assert ((timer == 4'd0) && (svc == 1'b0));

   // Governor coherence (safety): the in-flight deadline budget never
   // exceeds two cycles per credit at the recorded peak occupancy.
   always @(posedge clk)
       assert (timer <= {peak, 1'b0});

endmodule

// Sliding-window grant rate limiter: an 8-cycle shift register of recent
// grants plus an occupancy counter that mirrors its population count.
// A grant may only be issued if no grant occurred in the last two cycles,
// which spaces grants at least 3 cycles apart and therefore caps the
// occupancy of the 8-deep window at 3, far below the 4-bit counter range.
// Grants now ping-pong between two sinks, each with its own 8-cycle window;
// the spacing rule is held in one cooldown counter shared by both sinks.
// The two sinks share one occupancy accumulator: ones reports the total number
// of in-flight grants across both windows. The add is retimed to shorten the
// accumulator path, so each sink stages its own +1 for a cycle (ones_pend,
// ones_pend_b) and the accumulator picks the staged carry up on the next one.
// The retire port is shared as well, since the two windows never age a grant
// out of the tail on the same cycle.
module grant_window_limiter (
    input  wire       clk,
    input  wire       ce,      // idle when low: no state changes
    input  wire       req,
    output wire       grant,
    output reg  [7:0] win,
    output reg  [3:0] ones
);

    reg armed = 1'b0;   // sticky: set the first time a grant is issued
    reg pv    = 1'b0;   // past-valid
    reg [7:0] win_b = 8'b0000_0000;  // sink B's window, same 8-cycle depth
    reg [1:0] cool  = 2'd0;          // shared spacing cooldown, loaded by either sink
    reg       sel   = 1'b0;          // ping-pong pointer: 0 = next grant goes to sink A
reg       ones_pend   = 1'b0;    // staged +1 from a fresh sink-A grant
reg       ones_pend_b = 1'b0;    // staged +1 from a fresh sink-B grant

   // The tail age-out detect is tapped four taps early and pipelined four
   // deep, so the accumulator's subtract port sees a registered flag instead
   // of a long combinational reach into the top of both windows.
   reg       rt1 = 1'b0;
   reg       rt2 = 1'b0;
   reg       rt3 = 1'b0;
   reg       rt4 = 1'b0;

    initial win  = 8'b0000_0000;
    initial ones = 4'd0;

    // spacing rule, now carried by the shared cooldown: a grant to either sink
    // blocks the shared issue path for the following two cycles
    wire allow = (cool == 2'd0);
    wire g     = ce && req && allow;
    wire to_b  = sel;                // this grant is tagged for sink B
wire rt_det = win[3] || win_b[3];  // tail-approach detect, four taps early
wire retire = rt4;                 // shared retire port into the accumulator

    assign grant = g;

    always @(posedge clk) begin
        if (ce) begin
            win   <= {win[6:0], g && !to_b};
            win_b <= {win_b[6:0], g && to_b};
ones_pend   <= g && !to_b;
ones_pend_b <= g && to_b;
           rt1 <= rt_det;
           rt2 <= rt1;
           rt3 <= rt2;
           rt4 <= rt3;
ones        <= ones + (ones_pend ? 4'd1 : 4'd0) + (ones_pend_b ? 4'd1 : 4'd0)
                    - (retire ? 4'd1 : 4'd0);
            cool  <= g ? 2'd2 : ((cool == 2'd0) ? 2'd0 : cool - 2'd1);
            if (g)
                sel <= ~sel;
        end
        if (g)
            armed <= 1'b1;
        pv <= 1'b1;
    end

    // Bounded existence, at most 3, in the scope after the first grant.
    always @(posedge clk)
        if (pv && armed)
            assert ((ones <= 4'd3) && ($past(ones) <= 4'd3));

endmodule

module dma_burst_dimmer (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // beat enable / idle when low
    input  wire       i_start,
    input  wire [3:0] i_beats,
    input  wire [3:0] i_duty,
    output wire       o_busy,
    output wire       o_beat,
output wire       o_pwm,
output reg  [3:0] o_ce_count
);

    // ---- DMA burst engine state ----
    reg [3:0] beats_left;   // beats remaining in the burst
    reg [3:0] done_cnt;     // beats already pushed out
    reg [3:0] total;        // beats requested by the accepted burst
    reg [3:0] duty;         // dimming level latched with the burst
    reg       busy;         // up exactly while beats remain
    reg [3:0] queued;       // beats accepted but not yet issued into the current chunk
   reg [3:0] chunk_pend;   // chunk staged for issue on the next beat
   // ---- fabric ledger: beats booked out to the fabric vs beats it consumed ----
   reg [3:0] n_iss;        // running count of beats issued to the fabric
   reg [3:0] n_ret;        // running count of beats the fabric has consumed

    initial beats_left = 4'd0;
    initial done_cnt   = 4'd0;
    initial total      = 4'd0;
    initial duty       = 4'd0;
    initial busy       = 1'b0;
    initial queued     = 4'd0;
   initial chunk_pend = 4'd0;
   initial n_iss      = 4'd0;
   initial n_ret      = 4'd0;
initial o_ce_count = 4'd0;

    // the fabric only accepts short chunks, so a long burst is issued piecewise
    localparam [3:0] CHUNK_MAX = 4'd4;
    wire [3:0] first_chunk = (i_beats > CHUNK_MAX) ? CHUNK_MAX : i_beats;
    wire [3:0] next_chunk  = (queued  > CHUNK_MAX) ? CHUNK_MAX : queued;
   // a beat is live on the bus exactly while the ledger shows work booked out
   wire outstanding = (n_iss != n_ret);

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            done_cnt   <= 4'd0;
            total      <= 4'd0;
            duty       <= 4'd0;
            queued     <= 4'd0;
           chunk_pend <= 4'd0;
           n_iss      <= 4'd0;
           n_ret      <= 4'd0;
o_ce_count <= 4'd0;
            busy       <= 1'b0;
        end else if (i_start && !busy && (i_beats != 4'd0)) begin
            // accept a new burst
            beats_left <= first_chunk;
           n_iss      <= n_iss + first_chunk;
            queued     <= i_beats - first_chunk;
            total      <= i_beats;
            done_cnt   <= 4'd0;
            duty       <= i_duty;
            busy       <= 1'b1;
        end else if (i_ce) begin
            // retire one beat
            if (beats_left > 4'd1) begin
                beats_left <= beats_left - 4'd1;
            end else if (beats_left == 4'd1) begin
               // current chunk drained: stage the next chunk, the fabric
               // needs a cycle of turnaround before it can be issued
               beats_left <= 4'd0;
               chunk_pend <= next_chunk;
                queued     <= queued - next_chunk;
           end else if (chunk_pend != 4'd0) begin
               // staged chunk lands in the beat counter
               beats_left <= chunk_pend;
               chunk_pend <= 4'd0;
           end
           // ledger bookkeeping: one beat is consumed per enabled cycle, and a
           // staged chunk is booked out to the fabric when it lands
           if (beats_left != 4'd0)
               n_ret <= n_ret + 4'd1;
           else if (chunk_pend != 4'd0)
               n_iss <= n_iss + chunk_pend;
           if ((beats_left <= 4'd1) && (queued == 4'd0) && (chunk_pend == 4'd0))
                busy <= 1'b0;
           if (busy && outstanding)
                done_cnt <= done_cnt + 4'd1;
o_ce_count <= o_ce_count + 4'd1;
        end
    end

    assign o_busy = busy;
   assign o_beat = busy && i_ce && outstanding;
    assign o_pwm  = busy && (done_cnt < duty);

    // ---- P: whenever the engine is not busy, the whole burst has been pushed ----
    always @(posedge i_clk)
        if (!busy)
            assert (done_cnt == total);

endmodule

module pwm_precedence (
    input  wire       clk,
    input  wire       ce,
    input  wire       load,
    input  wire [3:0] duty_in,
    output wire       o_pwm,
    output wire       o_period_start
);
    // 12-cycle PWM period: counter runs 0..11 and reloads.
    localparam [3:0] PERIOD_M1 = 4'd11;

    reg [3:0] cnt;       // period counter
    reg [3:0] duty_act;  // active duty, latched at period start
    reg [3:0] duty_pend; // pending (requested) duty
    reg [3:0] hi_left;   // shadow: high-cycle budget recorded at last period start
    reg [3:0] duty_stg;  // prefetched duty feeding the compare path
   reg [3:0] req_val;   // duty value captured from the request bus
   reg       req_vld;   // captured request still waiting to be committed
  reg [3:0] n_stage;   // running count of duty_pend -> duty_stg stage loads
  reg [3:0] n_commit;  // running count of duty_stg -> duty_act reloads
 // two duty slots are played on alternating periods so the average duty
 // lands between them (half-LSB dither); the compare path, the staging
 // register and the request capture are shared between the two slots
 reg [3:0] duty_pend_b; // pending duty for the B slot
 reg       ph;          // slot the period now running was loaded from
 reg       wr_sel;      // next accepted request programs the B slot

    initial cnt       = 4'd0;
    initial duty_act  = 4'd0;
    initial duty_pend = 4'd0;
    initial hi_left   = 4'd0;
    initial duty_stg  = 4'd0;
   initial req_val   = 4'd0;
   initial req_vld   = 1'b0;
  initial n_stage   = 4'd0;
  initial n_commit  = 4'd0;
 initial duty_pend_b = 4'd0;
 initial ph          = 1'b0;
 initial wr_sel      = 1'b0;

    wire wrap = (cnt == PERIOD_M1);
    wire prefetch = (cnt == PERIOD_M1 - 4'd1);
   wire prefetch2 = (cnt == PERIOD_M1 - 4'd2);
   // a captured request only reaches duty_pend one cycle after it is
   // accepted, so the accept window has to close three cycles before the
   // boundary for the duty pipeline to be stable across the reload
   wire duty_hold = prefetch2 || prefetch || wrap;

    // seeded construct: output high exactly while the counter is below the duty
    assign o_pwm          = (cnt < duty_act);
    assign o_period_start = (cnt == 4'd0);

    always @(posedge clk) begin
        if (ce) begin
            // prefetch one cycle ahead of the boundary so the cnt<duty
            // compare gets a full cycle of setup on the new duty value
           if (prefetch) begin
             // the period after this one runs the other slot
             duty_stg <= ph ? duty_pend : duty_pend_b;
               n_stage  <= n_stage + 4'd1;
           end
            if (wrap) begin
                // new period: both the active duty and the high budget are
                // (re)loaded from the pending duty requested earlier
                cnt      <= 4'd0;
               // the staged value is consumed exactly once: the reload only
               // fires when the ledger still shows an un-consumed stage load,
               // otherwise duty_stg already sits in duty_act
               if (n_stage != n_commit) begin
                   duty_act <= duty_stg;
                   n_commit <= n_commit + 4'd1;
               end
              hi_left  <= ph ? duty_pend : duty_pend_b;
              ph       <= ~ph;
            end else begin
                cnt <= cnt + 4'd1;
                if (hi_left != 4'd0)
                    hi_left <= hi_left - 4'd1;
            end
           // request bus is registered: capture on the accepted cycle and
           // commit into the pending duty on the following cycle
           if (load && !duty_hold) begin
               req_val <= duty_in;
               req_vld <= 1'b1;
           end else begin
               req_vld <= 1'b0;
           end
          // consecutive accepted writes program the A slot then the B slot
          if (req_vld) begin
              if (wr_sel) duty_pend_b <= req_val;
              else        duty_pend   <= req_val;
              wr_sel <= ~wr_sel;
          end
        end
    end

    // past-valid register so cycle zero is not judged
    reg pv = 0;
    always @(posedge clk)
        pv <= 1'b1;

    // Precedence: if the output was driven high last cycle, then a nonzero
    // high-cycle budget (recorded at the earlier period start) must still have
    // been available at that time.
    always @(posedge clk)
        if (pv && $past(o_pwm))
            assert ($past(hi_left) != 4'd0);
endmodule

module wifi_radio_owner_fsm (
    input  wire clk,
    input  wire rst,
    input  wire step,      // idle/enable: low freezes all state
    input  wire rx_start,  // preamble detected by the receiver
    input  wire tx_req,    // MAC wants the air for a frame
    output wire radio_tx,  // transmit chain owns the radio
output wire radio_rx,  // receive chain owns the radio
output reg  [3:0] rx_evt_count // count of observed preambles (diagnostic)
);
    // one-hot MAC air-interface FSM:
//   bit0 = IDLE, bit1 = RX_FRAME, bit2 = TX_BURST, bit3 = ACK_WAIT
reg [3:0] state;
initial state = 4'b0001;

// transmit burst sequencer: one-hot shift register that walks the PA
// through the preamble and data phases of a granted frame
//   bit0 = PREAMBLE, bit1 = DATA, 2'b00 = burst finished
reg [1:0] txph;
initial txph = 2'b00;

   // periodic beacon engine; shares the radio front end with the MAC FSM
   //   bit0 = B_IDLE, bit1 = B_RAMP, bit2 = B_SEND
   reg [2:0] bstate;
   reg [3:0] btimer;
   initial bstate = 3'b001;
   initial btimer = 4'd15;
  initial rx_evt_count = 4'd0;

wire s_idle = state[0];
wire s_rx   = state[1];
wire s_txb  = state[2];
wire s_ackw = state[3];

wire tx_pre = txph[0];
wire tx_dat = txph[1];
// the MAC hands the air to the burst sequencer on the way out of IDLE
wire tx_start = s_idle & tx_req & ~rx_start;

   wire b_idle = bstate[0];
   wire b_ramp = bstate[1];
   wire b_send = bstate[2];
   wire b_busy = b_ramp | b_send;
   wire b_due  = (btimer == 4'd0);
   // the MAC keeps priority: the beacon only grabs an idle, unrequested radio
   wire b_go   = b_idle & b_due & s_idle & ~rx_start & ~tx_req;

   wire [2:0] bnxt;
   assign bnxt[0] = (b_idle & ~b_go) | b_send;
   assign bnxt[1] = b_go;                             // ramp the beacon PA
   assign bnxt[2] = b_ramp;                           // ramp -> send beacon

    // next-state as a per-bit OR of its legal source states
wire [3:0] nxt;
    assign nxt[0] = (s_idle & ~rx_start & ~tx_req) | s_rx | s_ackw;
    assign nxt[1] = s_idle & rx_start;                 // RX wins the air
assign nxt[2] = tx_start | (s_txb & tx_pre);       // start / stay in burst
assign nxt[3] = s_txb & tx_dat;                    // data done -> ACK wait

    always @(posedge clk) begin
        if (rst)
state <= 4'b0001;
       // the air is single-ported: the MAC FSM stalls while the beacon has it
       else if (step && !b_busy)
            state <= nxt;
    end

  // the sequencer shifts a zero in on every granted cycle, so the burst
  // self-terminates one cycle after the data phase
  always @(posedge clk) begin
      if (rst)
          txph <= 2'b00;
      else if (step && !b_busy) begin
          if (tx_start)
              txph <= 2'b01;
          else
              txph <= {txph[0], 1'b0};
      end
  end

   always @(posedge clk) begin
       if (rst)
           bstate <= 3'b001;
       else if (step)
           bstate <= bnxt;
   end

   // beacon interval: reload on transmission, hold at zero until the air frees
   always @(posedge clk) begin
       if (rst)
           btimer <= 4'd15;
       else if (step) begin
           if (b_send)
               btimer <= 4'd15;
           else if (btimer != 4'd0)
               btimer <= btimer - 4'd1;
       end
   end

  // diagnostic preamble counter: observes the inputs only, drives nothing else
  always @(posedge clk) begin
      if (rst)
          rx_evt_count <= 4'd0;
      else if (step && rx_start)
          rx_evt_count <= rx_evt_count + 4'd1;
  end

    // decoded radio ownership
assign radio_tx = tx_pre | tx_dat | b_ramp | b_send;
    assign radio_rx = s_rx    | s_ackw;

    // P: the transmit and receive chains never own the radio together
    always @(*)
        assert (!(radio_tx && radio_rx));
endmodule

module alu_result_fifo (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] a,
    input  wire [7:0] b,
    input  wire [1:0] op,
    output reg  [7:0] o_data,
    output reg        o_zero,
    output reg        o_carry,
    output wire       full,
    output wire       empty,
output reg  [3:0] count,
output reg  [7:0] o_push_tally,
output reg  [3:0] o_op_shadow
);
    // ---- FIFO state: separate write/read pointers plus occupancy counter ----
    reg [2:0] wptr, rptr;
    reg [8:0] mem [0:7];   // {carry, result} slices
   // one-deep input staging register: the ALU result is captured here and
   // written into the array on the following enabled cycle
   reg        stg_v;
   reg  [8:0] stg_d;
  // second (skid) input slot: absorbs one more push while the staging slot
  // is still waiting for room in the array
  reg        skid_v;
  reg  [8:0] skid_d;
    integer i;

    initial begin
        wptr    = 3'd0;
        rptr    = 3'd0;
        count   = 4'd0;
        o_data  = 8'h00;
        o_zero  = 1'b1;
        o_carry = 1'b0;
       stg_v   = 1'b0;
       stg_d   = 9'd0;
      skid_v  = 1'b0;
      skid_d  = 9'd0;
o_push_tally = 8'h00;
o_op_shadow = 4'd0;
        for (i = 0; i < 8; i = i + 1) mem[i] = 9'd0;
    end

    // ---- 8-bit ALU slice: add, subtract, and, or (carry out in bit 8) ----
    wire [8:0] w_sum = {1'b0, a} + {1'b0, b};
    wire [8:0] w_dif = {1'b0, a} - {1'b0, b};
    reg  [8:0] alu;
    always @(*) begin
        case (op)
            2'b00:   alu = w_sum;
            2'b01:   alu = w_dif;
            2'b10:   alu = {1'b0, a & b};
            default: alu = {1'b0, a | b};
        endcase
    end

    // ---- full/empty derived from the POINTERS, not from the counter ----
  wire [3:0] w_occ = {1'b0, (wptr - rptr)} + {3'b0, stg_v} + {3'b0, skid_v};
   assign full  = (w_occ == 4'd5);
    assign empty = (wptr == rptr);

    wire do_push = i_ce && push && !full;
    wire do_pop  = i_ce && pop  && !empty;
   // the staging slot retires into the array whenever the array has room
   wire do_drain = i_ce && stg_v && ((wptr - rptr) != 3'd5);
  // the skid slot advances into the staging slot as soon as that slot frees up
  wire do_shift = i_ce && skid_v && (!stg_v || do_drain);

    always @(posedge clk) begin
       if (do_drain) begin
           mem[wptr] <= stg_d;
           wptr      <= wptr + 3'd1;
       end
      if (do_shift) begin
          stg_d <= skid_d;
          stg_v <= 1'b1;
      end else if (do_drain) begin
          stg_v <= 1'b0;
      end
       if (do_push) begin
          skid_d <= alu;
          skid_v <= 1'b1;
      end else if (do_shift) begin
          skid_v <= 1'b0;
       end
        if (do_pop) begin
            o_data  <= mem[rptr][7:0];
            o_carry <= mem[rptr][8];
            o_zero  <= (mem[rptr][7:0] == 8'h00);
            rptr    <= rptr + 3'd1;
        end
        if (do_push && !do_pop)
            count <= count + 4'd1;
        else if (!do_push && do_pop)
            count <= count - 4'd1;
        else
            count <= count;
if (do_push)
    o_push_tally <= o_push_tally + 8'd1;
else if (do_pop)
    o_push_tally <= {o_push_tally[6:0], o_push_tally[7]};
if (i_ce)
    o_op_shadow <= {o_op_shadow[2:0], (^op) ^ a[0] ^ b[0]};
    end

    // P: occupancy never exceeds the depth of 5, though the register holds 15
    always @(*) assert (count <= 4'd5);
endmodule

module credit_rr_arbiter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire [3:0] req,       // four requesters
    input  wire       ret,       // consumer returns one credit
    output reg  [1:0] rr_ptr,    // rotating priority pointer
    output reg  [3:0] grant,     // one-hot grant
    output reg  [3:0] credits,   // credits held by the producer
    output reg  [3:0] outstanding // credits in flight at the consumer
);
    localparam [3:0] TOTAL = 4'd8;

   // credits parked against the burst currently in flight
   reg [1:0] escrow;

  // a return occupies the return path for one cycle before it lands
  reg       ret_q;
  reg [3:0] ret_amt;
 // lane B: a peer return lane that picks up the next return on the
 // cycle lane A drains, so returns can arrive back to back
 reg       ret_q2;
 reg [3:0] ret_amt2;
// grant commit stage: the credit file has a single write port, so a
// winning grant's debit is registered here on the decision cycle and
// charged against the credit file on the next one
reg       gnt_q;
reg [3:0] gnt_amt;
reg [1:0] gnt_resv;

    initial rr_ptr      = 2'd0;
    initial grant       = 4'b0000;
    initial credits     = TOTAL;
    initial outstanding = 4'd0;
   initial escrow      = 2'd0;
  initial ret_q       = 1'b0;
  initial ret_amt     = 4'd0;
 initial ret_q2      = 1'b0;
 initial ret_amt2    = 4'd0;
initial gnt_q       = 1'b0;
initial gnt_amt     = 4'd0;
initial gnt_resv    = 2'd0;

    // rotating priority selection: first requester at or after rr_ptr
    wire [1:0] idx = req[rr_ptr]          ? rr_ptr          :
                     req[rr_ptr + 2'd1]   ? rr_ptr + 2'd1   :
                     req[rr_ptr + 2'd2]   ? rr_ptr + 2'd2   :
                                            rr_ptr + 2'd3;

   // at burst start one credit per other waiting requester is parked in
   // escrow, so a burst that has been admitted can always be drained
   wire [3:0] others = req & ~(4'b0001 << idx);
   wire [1:0] resv   = {1'b0, others[0]} + {1'b0, others[1]} +
                       {1'b0, others[2]} + {1'b0, others[3]};
   wire       burst_start = (outstanding == 4'd0);
   wire [3:0] need        = burst_start ? (4'd1 + {2'b00, resv}) : 4'd1;
   wire have_credit = (credits >= need);
    wire any_req     = |req;

    // a grant spends one credit; it becomes outstanding until returned
   // a return is captured one cycle and applied the next
wire ret_start  = i_ce && ret && !ret_q && !gnt_q &&
                  (outstanding > {3'd0, ret_q2});
wire ret_start2 = i_ce && ret && ret_q && !ret_q2 && !gnt_q &&
                  (outstanding > 4'd1);
  // the two lanes share one credit write port; lane A drains first
  wire ret_done   = i_ce && ret_q;
  wire ret_done2  = i_ce && ret_q2 && !ret_q;
   // the return path has priority; grants stall while it is busy
wire do_grant   = i_ce && have_credit && any_req &&
                  !ret_q && !ret_q2 && !gnt_q && !ret_start;
// the registered debit owns the credit write port when it lands
wire gnt_commit = i_ce && gnt_q;

    always @(posedge clk) begin
        if (rst) begin
            rr_ptr      <= 2'd0;
            grant       <= 4'b0000;
            credits     <= TOTAL;
            outstanding <= 4'd0;
           escrow      <= 2'd0;
           ret_q       <= 1'b0;
           ret_amt     <= 4'd0;
          ret_q2      <= 1'b0;
          ret_amt2    <= 4'd0;
gnt_q       <= 1'b0;
gnt_amt     <= 4'd0;
gnt_resv    <= 2'd0;
        end else if (i_ce) begin
            grant <= do_grant ? (4'b0001 << idx) : 4'b0000;
            if (do_grant)
                rr_ptr <= idx + 2'd1;

          // capture side: each lane latches the amount it will hand back
          if (ret_start) begin
              ret_q   <= 1'b1;
              ret_amt <= (outstanding == 4'd1 + {3'd0, ret_q2})
                           ? (4'd1 + {2'b00, escrow}) : 4'd1;
          end
          if (ret_start2) begin
              ret_q2   <= 1'b1;
              ret_amt2 <= (outstanding == 4'd2)
                           ? (4'd1 + {2'b00, escrow}) : 4'd1;
          end


         // arbitration only records the winner's charge; the credit
         // file itself is written when the stage commits next cycle
         if (do_grant) begin
             gnt_q    <= 1'b1;
             gnt_amt  <= need;
             gnt_resv <= burst_start ? resv : escrow;
         end

         if (gnt_commit) begin
             credits     <= credits - gnt_amt;
             escrow      <= gnt_resv;
             outstanding <= outstanding + 4'd1;
             gnt_q       <= 1'b0;
           end else if (ret_done) begin
               credits <= credits + ret_amt;
               if (outstanding == 4'd1)
                   escrow <= 2'd0;
               outstanding <= outstanding - 4'd1;
               ret_q <= 1'b0;
          end else if (ret_done2) begin
              credits <= credits + ret_amt2;
              if (outstanding == 4'd1)
                  escrow <= 2'd0;
              outstanding <= outstanding - 4'd1;
              ret_q2 <= 1'b0;
           end
        end
    end

    // P: whenever nothing is in flight, the producer holds every credit
    always @(posedge clk)
        if (outstanding == 4'd0)
            assert (credits == TOTAL);
endmodule

// DRC check engine: each accepted board-check job walks a saturating
// step counter up to MAXSTEP while a completion countdown runs down.
module drc_engine (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       start,     // new check job requested
    output reg        busy,      // request outstanding
    output reg [3:0]  progress,  // saturating up-counter, clamps at MAXSTEP
    output reg [3:0]  deadline,  // completion countdown
    output reg        armed,     // sticky: a job has been accepted at least once
output reg        done,
output reg [3:0]  step_tally,
output reg [3:0]  job_count
);
    localparam [3:0] MAXSTEP = 4'd10;
   localparam [3:0] PASS1   = 4'd6;   // steps budgeted to the first pass

   // second-pass budget, parked out of the live countdown until pass one ends
   reg [3:0] credit;
// steps retired by completed passes; progress counts the pass in flight only
reg [3:0] retired;

    initial begin
        busy     = 1'b0;
        progress = 4'd0;
        deadline = 4'd0;
        armed    = 1'b0;
        done     = 1'b0;
       credit   = 4'd0;
retired  = 4'd0;
step_tally = 4'd0;
job_count = 4'd0;
    end

    wire accept   = i_ce && start && !busy;
    wire step     = i_ce && busy;
// a job ends when the retired steps plus the pass in flight reach MAXSTEP
wire last     = (retired + progress + 4'd1 >= MAXSTEP);
   wire refill   = (deadline <= 4'd1) && (credit != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            busy     <= 1'b0;
            progress <= 4'd0;
            deadline <= 4'd0;
            armed    <= 1'b0;
            done     <= 1'b0;
           credit   <= 4'd0;
retired  <= 4'd0;
step_tally <= 4'd0;
job_count <= 4'd0;
        end else if (accept) begin
            busy     <= 1'b1;
            progress <= 4'd0;
           deadline <= PASS1;             // pass one runs on its own budget
           credit   <= MAXSTEP - PASS1;   // remainder held back for pass two
retired  <= 4'd0;
            armed    <= 1'b1;   // sticky once set, never cleared except by rst
            done     <= 1'b0;
job_count <= (job_count == 4'd15) ? 4'd15 : job_count + 4'd1;
        end else if (step) begin
           if (refill) begin
               // pass one spent: hand the reserve to the live countdown
               deadline <= credit;
               credit   <= 4'd0;
retired  <= retired + progress + 4'd1;   // book the finished pass
progress <= 4'd0;                        // in-pass counter restarts
           end else begin
               deadline <= (deadline == 4'd0) ? 4'd0 : deadline - 4'd1;
// saturating in-pass counter: clamps at MAXSTEP, never reaches 4'd15
progress <= (progress == MAXSTEP) ? MAXSTEP : progress + 4'd1;
           end
            if (last) begin
                busy <= 1'b0;
                done <= 1'b1;
            end
step_tally <= (step_tally == 4'd15) ? 4'd15 : step_tally + 4'd1;
        end
    end

    // P: while the engine has ever been armed and a check is outstanding,
    // the completion countdown must not have expired.
    always @(*)
        if (armed && busy)
            assert (deadline != 4'd0);
endmodule

module fetch_credit_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,        // idle condition: when low, nothing moves
    input  wire       fetch,     // issue an instruction into the fetch queue
    input  wire       retire,    // instruction leaves the queue
    output reg  [3:0] used,      // up counter: occupancy of the fetch queue
    output reg  [3:0] credits,   // down counter: remaining free slots
    output wire       can_fetch
);
    // queue depth is 12, but both counters are 4 bits wide (0..15)
    localparam [3:0] DEPTH = 4'd12;

    // a retire frees a queue slot right away, but the credit itself only
    // reaches the free pool a cycle later, through this return stage
    reg        ret_credit;

   // an accepted fetch is registered in the allocate stage; it shows up
   // in the occupancy counter on the following cycle
   reg        alloc_pend;

   // credits withheld from the fetch free pool and parked for the
   // prefetch port while the queue is running hot
   reg  [1:0] resv;


    initial used    = 4'd0;
    initial credits = DEPTH;
    initial ret_credit = 1'b0;
   initial alloc_pend = 1'b0;
   initial resv = 2'd0;

    assign can_fetch = (credits != 4'd0);

    wire fetch_go  = fetch && !retire && (credits != 4'd0);
    wire retire_go = retire && !fetch && (used != 4'd0);

   // the queue is under pressure once occupancy reaches the top third
   wire hi_load     = (used >= 4'd8);
   // under pressure a returning credit is parked in the reserve instead
   wire ret_to_resv = ret_credit && hi_load && (resv != 2'd2);
   // once the pressure is off, reserved credits go back one per cycle
   wire resv_drain  = !ret_credit && !fetch_go && !hi_load && (resv != 2'd0);
   wire cred_inc    = (ret_credit && !ret_to_resv) || resv_drain;
   wire cred_dec    = fetch_go;

    always @(posedge clk) begin
        if (rst) begin
            used    <= 4'd0;
            credits <= DEPTH;
            ret_credit <= 1'b0;
           alloc_pend <= 1'b0;
           resv <= 2'd0;
        end else if (en) begin
           // occupancy reflects the allocate stage, one cycle behind the grant
           if (alloc_pend && !retire_go)
                used <= used + 4'd1;
           else if (!alloc_pend && retire_go)
                used <= used - 4'd1;

            // the free pool gives up a slot on fetch, and only gets one
            // back when a returning credit pops out of the return stage
           if (cred_dec && !cred_inc)
               credits <= credits - 4'd1;
           else if (cred_inc && !cred_dec)
               credits <= credits + 4'd1;

           // the reserve fills from parked returns and drains back later
           if (ret_to_resv)
               resv <= resv + 2'd1;
           else if (resv_drain)
               resv <= resv - 2'd1;

            // a retire hands its credit to the return stage
            ret_credit <= retire_go;
           // the grant hands its slot to the allocate stage
           alloc_pend <= fetch_go;
            // simultaneous fetch+retire: slot handed straight over
        end
    end

    // P (two assertions, global scope, bounded existence at most 12):
    // neither counter can ever exceed the queue depth, which is strictly
    // smaller than what their 4-bit width admits.
    always @(posedge clk) begin
        assert (used <= DEPTH);
        assert (credits <= DEPTH);
    end
endmodule

module gfx_frame_fsm (
    input  wire clk,
    input  wire i_reset,
    input  wire i_ce,
    input  wire i_start,
    output wire o_vsync,
    output wire [2:0] o_state
);
    // binary-encoded frame pipeline states; 5,6,7 are unreachable encodings
    localparam [2:0] S_IDLE    = 3'd0;
    localparam [2:0] S_CLEAR   = 3'd1;
    localparam [2:0] S_DRAW    = 3'd2;
    localparam [2:0] S_BLIT    = 3'd3;
    localparam [2:0] S_PRESENT = 3'd4;
   // overlay plane pipeline stages (shares the framebuffer with the frame pipeline)
   localparam [1:0] OV_IDLE = 2'd0;
   localparam [1:0] OV_CLR  = 2'd1;
   localparam [1:0] OV_FILL = 2'd2;
   localparam [1:0] OV_SWAP = 2'd3;
   // hardware cursor plane: repaints the sprite after the overlay refresh
   localparam [1:0] CU_IDLE  = 2'd0;
   localparam [1:0] CU_FETCH = 2'd1;
   localparam [1:0] CU_PAINT = 2'd2;
   localparam [1:0] CU_DONE  = 2'd3;
// shared framebuffer write port: an update is staged here for one cycle
localparam [2:0] FB_NOP = 3'd0;
localparam [2:0] FB_CLR = 3'd1;
localparam [2:0] FB_OVL = 3'd2;
localparam [2:0] FB_CUR = 3'd3;

    reg [2:0] state;
    reg [1:0] draw_cnt;
    reg       cleared_seen;   // shadow: framebuffer was cleared this frame
   reg [1:0] ov_state;      // overlay plane pipeline
   reg       ov_pend;       // overlay refresh owed after the last frame
reg [2:0] fb_cmd;        // framebuffer update in flight to the shadow
reg [1:0] cur_state;     // hardware cursor plane pipeline
reg       cur_pend;      // cursor repaint owed after the last frame

    initial state        = S_IDLE;
    initial draw_cnt     = 2'd0;
    initial cleared_seen = 1'b0;
   initial ov_state     = OV_IDLE;
   initial ov_pend      = 1'b0;
initial fb_cmd       = FB_NOP;
initial cur_state    = CU_IDLE;
initial cur_pend     = 1'b0;

    wire draw_done = (draw_cnt == 2'd3);
   // framebuffer arbitration: the frame pipeline may only start a new frame
   // when no overlay refresh is running or owed
  wire fb_free = (ov_state == OV_IDLE) && !ov_pend &&
                 (cur_state == CU_IDLE) && !cur_pend;

    always @(posedge clk) begin
        if (i_reset) begin
            state        <= S_IDLE;
            draw_cnt     <= 2'd0;
            cleared_seen <= 1'b0;
           ov_state     <= OV_IDLE;
           ov_pend      <= 1'b0;
fb_cmd       <= FB_NOP;
           cur_state    <= CU_IDLE;
           cur_pend     <= 1'b0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                   if (i_start && fb_free) begin
                        state    <= S_CLEAR;
                        draw_cnt <= 2'd0;
                    end
                end
                S_CLEAR: begin
// the clear pass hands its update to the framebuffer write port
// rather than touching the shadow directly
fb_cmd       <= FB_CLR;
                    state        <= S_DRAW;
                end
                S_DRAW: begin
                    if (draw_done)
                        state <= S_BLIT;
                    else
                        draw_cnt <= draw_cnt + 2'd1;
                end
                S_BLIT: begin
                    state <= S_PRESENT;
                end
                S_PRESENT: begin
                    state        <= S_IDLE;
                    draw_cnt     <= 2'd0;
                    cleared_seen <= 1'b0;
                   ov_pend      <= 1'b1;   // overlay gets the buffer next
                  cur_pend     <= 1'b1;   // cursor repaints after the overlay
                end
                default: begin
                    // encodings 5/6/7 never occur by construction; the
                    // synthesised decoder folds them onto the present stage
                    state <= S_PRESENT;
                end
            endcase

           // Overlay plane pipeline: same shape as the frame pipeline above,
           // but it borrows the framebuffer and the shared pass counter, so it
           // only runs in the gap between frames.
           case (ov_state)
               OV_IDLE: begin
                   if (ov_pend && state == S_IDLE) begin
                       ov_state <= OV_CLR;
                       ov_pend  <= 1'b0;
                   end
               end
               OV_CLR: begin
                   ov_state <= OV_FILL;
                   draw_cnt <= 2'd0;
               end
               OV_FILL: begin
// overlay writes land on the shared framebuffer, so the recorded
// clear stops describing its contents once this update retires
fb_cmd <= FB_OVL;
                   if (draw_cnt == 2'd1)
                       ov_state <= OV_SWAP;
                   else
                       draw_cnt <= draw_cnt + 2'd1;
               end
               OV_SWAP: begin
                   ov_state <= OV_IDLE;
                   draw_cnt <= 2'd0;
               end
           endcase

          // Hardware cursor plane: a third client of the framebuffer write
          // port.  It repaints the sprite once the overlay refresh has
          // retired, and reuses the shared pass counter for its fill loop.
          case (cur_state)
              CU_IDLE: begin
                  if (cur_pend && state == S_IDLE &&
                      ov_state == OV_IDLE && !ov_pend) begin
                      cur_state <= CU_FETCH;
                      cur_pend  <= 1'b0;
                  end
              end
              CU_FETCH: begin
                  cur_state <= CU_PAINT;
                  draw_cnt  <= 2'd0;
              end
              CU_PAINT: begin
                  if (draw_cnt == 2'd2)
                      cur_state <= CU_DONE;
                  else
                      draw_cnt <= draw_cnt + 2'd1;
              end
              CU_DONE: begin
                  cur_state <= CU_IDLE;
                  draw_cnt  <= 2'd0;
              end
          endcase
// Shared framebuffer write port.  The staged command retires into the
// shadow here, one cycle after the pass that issued it, and the port is
// re-armed in the same cycle.  The frame pipeline wins the port if both
// planes ask for it in the same cycle.
if (fb_cmd == FB_CLR)
    cleared_seen <= 1'b1;
else if (fb_cmd == FB_OVL || fb_cmd == FB_CUR)
    cleared_seen <= 1'b0;
if (state == S_CLEAR)
    fb_cmd <= FB_CLR;
else if (ov_state == OV_FILL)
    fb_cmd <= FB_OVL;
else if (cur_state == CU_PAINT)
    fb_cmd <= FB_CUR;
else
    fb_cmd <= FB_NOP;
        end
    end

    assign o_vsync = (state == S_PRESENT);
    assign o_state = state;

    // Precedence, global: presenting a frame implies the clear pass happened earlier
    always @(posedge clk)
        if (state == S_PRESENT)
            assert (cleared_seen);
endmodule

// Four-phase req/ack handshake engine with a busy mirror and
// per-client ownership / response routing tags.
//
//   phase 0 : idle            (req=0, ack=0)
//   phase 1 : req asserted    (req=1, ack=0)
//   phase 2 : ack observed    (req=1, ack=1)
//   phase 3 : req withdrawn   (req=0, ack=1)  -> waits for ack to drop
//
// busy is a separate register that mirrors "phase != 0"; the start path is
// gated on !busy only, exactly as a real controller would do.
module fourphase_owner (
    input  wire clk,
    input  wire i_ce,        // idle condition: nothing moves when low
    input  wire i_req,       // a client wants the channel
    input  wire i_sel,       // which client (0 -> A, 1 -> B)
    input  wire i_ack_in,    // ack wire coming back from the target
    output wire o_busy,
    output wire o_req,
    output wire o_ack
);

    reg [1:0] phase;
    reg       busy;
    reg       req;
    reg       ack;
    reg       own_a, own_b;   // who currently owns the channel
    reg       resp_a, resp_b; // where the response will be routed
    reg       virgin;         // high until the first handshake ever completes

  // The owner tag is not written straight from the launch path: the launch
  // cycle is already busy driving req and bumping the credit ledger, so the
  // selected client is parked in a one-deep staging latch and copied into
  // the ownership bits on the following enabled cycle. Progress out of
  // phase 1 stalls until the staged tag has been committed.
  reg       tag_v;
  reg       tag_sel;

   // Credit ledger: one credit exists for the channel. Every acquire is
   // logged in n_acq, every retire in n_rel; both wrap at four bits. The
   // channel may only be taken when all logged acquires have been retired.
   reg [3:0] n_acq;
   reg [3:0] n_rel;

  // Retires post lazily: the completion cycle is already writing seven
  // registers, so it only raises rel_pend and the n_rel increment is folded
  // into the next acquire. The ledger counts a pending retire as already
  // retired, so a client can take the channel back to back without waiting
  // for the credit to be written down.
  reg       rel_pend;

  wire ledger_free = ((n_acq - n_rel) == {3'b0, rel_pend});

    initial phase  = 2'd0;
    initial busy   = 1'b0;
    initial req    = 1'b0;
    initial ack    = 1'b0;
    initial own_a  = 1'b0;
    initial own_b  = 1'b0;
    initial resp_a = 1'b0;
    initial resp_b = 1'b0;
    initial virgin = 1'b1;
  initial tag_v   = 1'b0;
  initial tag_sel = 1'b0;
   initial n_acq  = 4'd0;
   initial n_rel  = 4'd0;
  initial rel_pend = 1'b0;

    always @(posedge clk) begin
        if (i_ce) begin
           if (ledger_free) begin
                // channel believed free: latch the owner and drive req
                if (i_req) begin
                    phase <= 2'd1;
                    req   <= 1'b1;
                    busy  <= 1'b1;
                   n_acq <= n_acq + 4'd1;
                  n_rel    <= n_rel + {3'b0, rel_pend};
                  rel_pend <= 1'b0;
                   tag_v   <= 1'b1;
                   tag_sel <= i_sel;
                end
            end else begin
                case (phase)
                   2'd1: if (tag_v) begin
                             // drain the staging latch into the tag bits
                             tag_v <= 1'b0;
                             if (tag_sel)
                                 own_b <= 1'b1;
                             else
                                 own_a <= 1'b1;
                         end else if (i_ack_in) begin
                              // ack rose: snapshot the response route
                              phase  <= 2'd2;
                              ack    <= 1'b1;
                              resp_a <= own_a;
                              resp_b <= own_b;
                          end
                    2'd2: begin
                              // req may only drop now that ack is high
                              phase <= 2'd3;
                              req   <= 1'b0;
                          end
                    2'd3: if (!i_ack_in) begin
                              phase  <= 2'd0;
                              ack    <= 1'b0;
                              busy   <= 1'b0;
                            rel_pend <= 1'b1;
                              own_a  <= 1'b0;
                              own_b  <= 1'b0;
                              resp_a <= 1'b0;
                              resp_b <= 1'b0;
                              virgin <= 1'b0;   // first completion disarms
                          end
                    default: ;
                endcase
            end
        end
    end

    assign o_busy = busy;
    assign o_req  = req;
    assign o_ack  = ack;

    // Before the first handshake has ever completed, there must never be two
    // owners at once, and never two response routes at once.
    always @(posedge clk)
        if (virgin) assert (!(own_a && own_b));

    always @(posedge clk)
        if (virgin) assert (!(resp_a && resp_b));

endmodule

module credit_pool (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // step enable: low leaves all state unchanged
    input  wire i_take,    // 1 = take a credit, 0 = give one back
    output wire o_full,
    output wire o_empty,
    output wire [3:0] o_used,
    output wire [3:0] o_avail
);
    localparam [3:0] CAP = 4'd12;

    // up counter: credits handed out
    reg [3:0] used;
    // down counter: credits still on the shelf
    reg [3:0] avail;
   // per-lane outstanding credits: two clients share the one shelf
   reg [3:0] out_a;
   reg [3:0] out_b;
  // lane A parks its first two credits in a private reserve slot so the
  // common case never touches the lane counter
  reg [1:0] rsv_a;
 // lane B gets the same private reserve slot, so both clients behave alike
 reg [1:0] rsv_b;
   // round-robin pointer: whose request is charged next
   reg       turn;
   // registered arbiter grant: the shelf port moves one credit per cycle
   reg       gnt_a;
   reg       gnt_b;
   reg       gnt_take;
   // shelf-port move pipeline: a granted credit needs four more cycles on the
   // shared port before the lane counters and the shelf see it
   reg       p1_a;
   reg       p1_b;
   reg       p1_take;
   reg       p2_a;
   reg       p2_b;
   reg       p2_take;
   reg       p3_a;
   reg       p3_b;
   reg       p3_take;
   reg       p4_a;
   reg       p4_b;
   reg       p4_take;

    initial used  = 4'd0;
    initial avail = CAP;
   initial out_a = 4'd0;
   initial out_b = 4'd0;
  initial rsv_a = 2'd0;
 initial rsv_b = 2'd0;
   initial turn  = 1'b0;
   initial gnt_a = 1'b0;
   initial gnt_b = 1'b0;
   initial gnt_take = 1'b0;
   initial p1_a = 1'b0;
   initial p1_b = 1'b0;
   initial p1_take = 1'b0;
   initial p2_a = 1'b0;
   initial p2_b = 1'b0;
   initial p2_take = 1'b0;
   initial p3_a = 1'b0;
   initial p3_b = 1'b0;
   initial p3_take = 1'b0;
   initial p4_a = 1'b0;
   initial p4_b = 1'b0;
   initial p4_take = 1'b0;

 wire       lane_nz  = turn ? (out_b != 4'd0 || rsv_b != 2'd0)
                            : (out_a != 4'd0 || rsv_a != 2'd0);
   wire       arb_idle = !gnt_a && !gnt_b && !p1_a && !p1_b &&
                         !p2_a && !p2_b && !p3_a && !p3_b && !p4_a && !p4_b;

   // a request is only latched while the shared shelf port is free
   wire accept = i_ce && arb_idle &&
                (i_take ? (used != CAP) : lane_nz);

   // commit of the move that has finished walking the shelf port
   wire take_fire = (p4_a || p4_b) &&  p4_take;
   wire give_fire = (p4_a || p4_b) && !p4_take;

  // lane A fills the reserve before its counter and drains it first
   wire       a_fill  = p4_a &&  p4_take && (rsv_a != 2'd2);
   wire       a_drain = p4_a && !p4_take && (rsv_a != 2'd0);
  wire [1:0] rsv_a_nxt = a_fill  ? rsv_a + 2'd1 :
                         a_drain ? rsv_a - 2'd1 : rsv_a;
   wire [3:0] out_a_nxt = (p4_a &&  p4_take && !a_fill)  ? out_a + 4'd1 :
                          (p4_a && !p4_take && !a_drain) ? out_a - 4'd1 : out_a;
  // lane B fills its reserve before its counter and drains it first
  wire       b_fill  = p4_b &&  p4_take && (rsv_b != 2'd2);
  wire       b_drain = p4_b && !p4_take && (rsv_b != 2'd0);
  wire [1:0] rsv_b_nxt = b_fill  ? rsv_b + 2'd1 :
                         b_drain ? rsv_b - 2'd1 : rsv_b;
  wire [3:0] out_b_nxt = (p4_b &&  p4_take && !b_fill)  ? out_b + 4'd1 :
                         (p4_b && !p4_take && !b_drain) ? out_b - 4'd1 : out_b;

    always @(posedge clk) begin
        if (rst) begin
            used  <= 4'd0;
            avail <= CAP;
           out_a <= 4'd0;
           out_b <= 4'd0;
          rsv_a <= 2'd0;
         rsv_b <= 2'd0;
           turn  <= 1'b0;
           gnt_a <= 1'b0;
           gnt_b <= 1'b0;
           gnt_take <= 1'b0;
           p1_a <= 1'b0;
           p1_b <= 1'b0;
           p1_take <= 1'b0;
           p2_a <= 1'b0;
           p2_b <= 1'b0;
           p2_take <= 1'b0;
           p3_a <= 1'b0;
           p3_b <= 1'b0;
           p3_take <= 1'b0;
           p4_a <= 1'b0;
           p4_b <= 1'b0;
           p4_take <= 1'b0;
       end else if (i_ce) begin
           // stage 1: arbitrate this cycle's request
           gnt_a    <= accept && !turn;
           gnt_b    <= accept &&  turn;
           gnt_take <= i_take;
           if (accept)
               turn <= ~turn;
           // stages 2-5: the credit walks the shared shelf port
           p1_a    <= gnt_a;
           p1_b    <= gnt_b;
           p1_take <= gnt_take;
           p2_a    <= p1_a;
           p2_b    <= p1_b;
           p2_take <= p1_take;
           p3_a    <= p2_a;
           p3_b    <= p2_b;
           p3_take <= p2_take;
           p4_a    <= p3_a;
           p4_b    <= p3_b;
           p4_take <= p3_take;

           // stage 6: retire the move as it leaves the port
           out_a <= out_a_nxt;
           out_b <= out_b_nxt;
          rsv_a <= rsv_a_nxt;
         rsv_b <= rsv_b_nxt;
         used  <= out_a_nxt + rsv_a_nxt + out_b_nxt + rsv_b_nxt;   // running total over both lanes
           if (take_fire)
               avail <= avail - 4'd1;        // stepped down, single shelf port
           else if (give_fire)
               avail <= avail + 4'd1;
       end
    end

    assign o_full  = (avail == 4'd0);
    assign o_empty = (used  == 4'd0);
    assign o_used  = used;
    assign o_avail = avail;

    // P: whenever the shelf is empty, every credit of the pool is out on loan
    always @(posedge clk)
        if (avail == 4'd0)
            assert (used == CAP);

   // Q: while the shelf is full, neither client is holding a credit
   always @(posedge clk)
       if (avail == CAP)
           assert (out_a == 4'd0 && out_b == 4'd0 &&
                   rsv_a == 2'd0 && rsv_b == 2'd0);
endmodule

// Transaction scoreboard with a completion deadline countdown.
// issued/retired are wrapping transaction counters; outst is the occupancy
// of the issue window (WINDOW deep). Every outstanding transaction is forced
// to retire before its RELOAD-cycle deadline countdown reaches zero.
module scoreboard_deadline (
    input  wire clk,
    input  wire ce,      // idle condition: ce low freezes the scoreboard
    input  wire issue,
    input  wire retire,
output wire busy,
output reg [3:0] evt_count
);
    localparam [2:0] WINDOW = 3'd4;
    localparam [2:0] RELOAD = 3'd5;
    localparam [1:0] QDEPTH = 2'd2;   // staging queue in front of the window

    reg [3:0] issued;
    reg [3:0] retired;
    reg [2:0] outst;    // outstanding transactions = issued - retired
    reg [1:0] queued;   // accepted, still waiting for a free window slot
   reg [1:0] qb;       // class-B staging queue sharing the same window
   reg       rr;       // round-robin pointer for the freed window slot
    reg [2:0] timer;    // deadline countdown for the oldest outstanding item
    reg       armed;    // sticky: set the first time a transaction is accepted
    reg       pv;       // past valid
reg [2:0] hist;     // sampled pin activity history (observability only)

    initial begin
        issued  = 4'd0;
        retired = 4'd0;
        outst   = 3'd0;
        queued  = 2'd0;
       qb      = 2'd0;
       rr      = 1'b0;
        timer   = 3'd0;
        armed   = 1'b0;
        pv      = 1'b0;
evt_count = 4'd0;
hist      = 3'd0;
    end

   assign busy = (outst != 3'd0) || (queued != 2'd0) || (qb != 2'd0);

    // deadline flag: the countdown has run out
    wire expired = (timer == 3'd0);

    // the design completes a transaction itself when the deadline is imminent
    wire force_ret = (outst != 3'd0) && (timer == 3'd1);

   wire [3:0] total = {1'b0, outst} + {2'b0, queued} + {2'b0, qb};

   // accept while the window plus both staging queues still have capacity
   wire do_issue  = ce && issue && (total < ({1'b0, WINDOW} + {2'b0, QDEPTH} + {2'b0, QDEPTH}));
    wire do_retire = ce && (outst != 3'd0) && (retire || force_ret);

    // a window slot is free, or is being freed by this cycle's retirement
    wire slot_free = (outst < WINDOW) || do_retire;
   // staged transactions are older than an incoming one, so they go first;
   // the two classes take turns for the slot the window frees up
   wire admit_a = ce && (queued != 2'd0) && slot_free && (!rr || (qb == 2'd0));
   wire admit_b = ce && (qb != 2'd0) && slot_free && !admit_a;
   wire admit   = admit_a || admit_b;
   wire direct  = do_issue && slot_free && !admit;
   wire enq     = do_issue && !direct;
   // a fresh transaction joins the shorter of the two queues
   wire enq_a   = enq && (queued <= qb);
   wire enq_b   = enq && !enq_a;

    wire [2:0] outst_n  = outst + ((admit || direct) ? 3'd1 : 3'd0)
                                - (do_retire ? 3'd1 : 3'd0);
   wire [1:0] queued_n = queued + (enq_a ? 2'd1 : 2'd0)
                                - (admit_a ? 2'd1 : 2'd0);
   wire [1:0] qb_n     = qb + (enq_b ? 2'd1 : 2'd0)
                            - (admit_b ? 2'd1 : 2'd0);

    always @(posedge clk) begin
        pv <= 1'b1;

        if (do_issue) begin
            armed  <= 1'b1;
            issued <= issued + 4'd1;
        end

        if (do_retire)
            retired <= retired + 4'd1;

        outst <= outst_n;
       queued <= queued_n;
       qb     <= qb_n;
       if (admit) rr <= admit_a;

        if (do_issue || do_retire) begin
            // any scoreboard event restarts (or clears) the deadline
           if (outst_n == 3'd0 && queued_n == 2'd0 && qb_n == 2'd0) timer <= 3'd0;
            else                 timer <= RELOAD;
        end else if (ce && (outst != 3'd0)) begin
            timer <= timer - 3'd1;
        end
if (ce) begin
    hist      <= {hist[1:0], issue ^ retire};
    evt_count <= evt_count + {3'd0, (hist[2] ^ retire)};
end
    end

    // Bounded response, safety form, in no-change style, scoped after arming:
    // once a transaction has been accepted, whenever the outstanding count did
    // not change and work is still outstanding, the deadline flag must not
    // change either (i.e. the countdown cannot expire under an outstanding
    // request).
    always @(posedge clk) begin
        if (pv && armed && (outst != 3'd0) && $stable(outst))
            assert ($stable(expired));
    end
endmodule

module dma_burst_engine (
    input  wire       clk,
    input  wire       i_ce,     // idle condition: low freezes all state
    input  wire       start,    // Q: opens the status window
    input  wire [3:0] len,      // requested burst length (beats)
    input  wire       ack,      // R: host acknowledges, closes the window
    output reg        busy,
    output reg  [3:0] beats
);
    // shadow register: records the length that was requested earlier
    reg [3:0] req_len;
    // beats actually pushed out so far in the current burst
    reg [3:0] done_cnt;
    // window register: set by start, cleared by ack
    reg       armed;
   // beats deferred past the 8-beat hardware burst limit of the current request
   reg [3:0] resid;
// credit-return coalescing: the fabric returns completion credit in groups of
// four, so beats already pushed may sit here before reaching done_cnt
reg [2:0] pend;
// fabric issue stage: a beat handed to the fabric in this cycle has left
// beats but its completion credit only arrives on the following cycle
reg        iq;
// secondary scrub channel: the fabric asks for a short refresh burst between
// host bursts. It shares the single issue stage and credit counter with the
// host burst channel, so the credit path belongs to one channel at a time.
reg [3:0] scr_beats;
// credit path owner: 0 = host burst channel, 1 = scrub channel
reg       own;

    initial busy     = 1'b0;
    initial beats    = 4'd0;
    initial req_len  = 4'd0;
    initial done_cnt = 4'd0;
    initial armed    = 1'b0;
   initial resid    = 4'd0;
initial pend     = 3'd0;
initial iq       = 1'b0;
initial scr_beats = 4'd0;
initial own       = 1'b0;

// ownership of the credit path only changes hands while no credit is in flight
wire path_empty = !iq && (pend == 3'd0);

wire accept = start && !armed && (len != 4'd0) && (!own || path_empty);
   // the fabric accepts at most 8 beats in one burst; the rest is deferred
   wire [3:0] chunk = (len > 4'd8) ? 4'd8 : len;
wire [2:0] pend_nxt  = (pend == 3'd3) ? 3'd0 : pend + 3'd1;
// a start the host channel cannot take (its status window is still open) is
// turned into a scrub burst on the secondary channel
wire scr_load = start && armed && (scr_beats == 4'd0);
wire scr_push = (scr_beats != 4'd0) && (own || path_empty);

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
               beats    <= chunk;
                req_len  <= len;      // shadow capture of the earlier event
               resid    <= len - chunk;
                done_cnt <= 4'd0;
pend     <= 3'd0;
iq       <= 1'b0;
                busy     <= 1'b1;
                armed    <= 1'b1;
own      <= 1'b0;   // the host burst channel takes the credit path
end else if (busy && !own && beats != 4'd0) begin
               beats    <= (beats == 4'd1 && resid != 4'd0) ? resid : beats - 4'd1;
resid    <= (beats == 4'd1) ? 4'd0 : resid;
// one beat is handed to the fabric now; its credit lands next cycle
iq       <= 1'b1;
// the beat issued on the previous cycle returns its credit now, and is
// held here until a full group of four is ready
pend     <= iq ? pend_nxt : pend;
done_cnt <= (iq && pend == 3'd3) ? done_cnt + 4'd4 : done_cnt;
busy     <= 1'b1;
end else if (busy && !own && iq) begin
// every beat has been issued: drain the credit of the last issued beat
iq       <= 1'b0;
pend     <= pend_nxt;
done_cnt <= (pend == 3'd3) ? done_cnt + 4'd4 : done_cnt;
busy     <= (pend_nxt != 3'd0);
end else if (busy && !own) begin
// trailing partial credit group flushed before the burst reports done
done_cnt <= done_cnt + {1'b0, pend};
pend     <= 3'd0;
busy     <= 1'b0;
end else if (scr_push) begin
// the scrub channel pushes a beat into the shared issue stage
scr_beats <= scr_beats - 4'd1;
iq        <= 1'b1;
pend      <= iq ? pend_nxt : pend;
own       <= 1'b1;
end else if (own && iq) begin
// credit of the last scrub beat comes back
iq        <= 1'b0;
pend      <= pend_nxt;
end else if (own) begin
// scrub traffic is never reported to the host: drop its partial credit
// group and hand the credit path back
pend      <= 3'd0;
own       <= 1'b0;
end else if (scr_load) begin
scr_beats <= 4'd4;
            end else if (armed && ack) begin
                armed    <= 1'b0;
            end
        end
    end

    // P, part 1: inside the window, while beats remain the burst cannot yet have
    // delivered everything that was requested earlier.
    always @(posedge clk)
        if (armed && busy)
            assert (done_cnt < req_len);

    // P, part 2: inside the window, once the engine is no longer busy the
    // delivered count must exactly match the earlier requested length.
    always @(posedge clk)
        if (armed && !busy)
            assert (done_cnt == req_len);

   // P, part 3: inside the window, while a deferred chunk is still queued the
   // beats already pushed plus the beats still held back must leave headroom
   // inside the length that was requested earlier.
   always @(posedge clk)
       if (armed && resid != 4'd0)
           assert (({1'b0,done_cnt} + {1'b0,resid}) < {1'b0,req_len});
endmodule

module debounce_hist_arm (
    input  wire i_clk,
    input  wire i_ce,
    input  wire i_raw,
    output wire o_clean,
    output wire o_armed,
    output wire o_settled
);
    // K identical consecutive samples are required before the clean output flips.
    localparam [2:0] KC = 3'd4;
    localparam       HW = 8;

    reg [2:0]      cnt;     // stability counter, saturates at KC
    reg            sample;  // current candidate level being timed
    reg            clean;   // debounced (committed) level
    reg [HW-1:0]   hist;    // raw sample history, hist[0] is the newest sample
    reg            armed;   // sticky: set the first time the filter commits
   reg            stable;  // registered settled flag, drives o_settled
reg            pend;    // pending level change: candidate differs from the committed level
   reg            tgt;     // latched target level of the outstanding change request
   reg [3:0]      n_req;   // ledger: change requests logged (free-running, wraps)
   reg [3:0]      n_ret;   // ledger: change requests retired (free-running, wraps)

    initial cnt    = 3'd0;
    initial sample = 1'b0;
    initial clean  = 1'b0;
    initial hist   = {HW{1'b0}};
    initial armed  = 1'b0;
   initial stable = 1'b0;
initial pend   = 1'b0;
   initial tgt    = 1'b0;
   initial n_req  = 4'd0;
   initial n_ret  = 4'd0;

    always @(posedge i_clk) if (i_ce) begin
        hist <= { hist[HW-2:0], i_raw };
        if (i_raw != sample) begin
            // new level seen: retime from scratch
            sample <= i_raw;
            cnt    <= 3'd0;
           stable <= 1'b0;
pend   <= i_raw ^ clean;
           // A retime either opens a new request against the committed level or
           // retires the one already logged; the target level is captured on open.
           if (n_req == n_ret) begin
               tgt   <= i_raw;
               n_req <= n_req + 4'd1;
           end else begin
               n_ret <= n_ret + 4'd1;
           end
        end else if (cnt < KC) begin
            cnt <= cnt + 3'd1;
            if (cnt == (KC - 3'd1)) begin
                // KC identical consecutive samples: commit the level
               if (pend) begin
                   clean <= tgt;
                   n_ret <= n_ret + 4'd1;
               end
pend  <= 1'b0;
                armed <= 1'b1;
               stable <= 1'b1;
            end
        end
    end

    assign o_clean   = clean;
    assign o_armed   = armed;
   assign o_settled = stable;

    // Universality, after the filter has armed: whenever the stability counter
    // is nonzero the two newest raw samples must agree.
    always @(*)
        if (armed)
            assert ((cnt == 3'd0) || (hist[1] == hist[0]));

   // While the filter reports settled, the committed level must still match the
   // newest raw sample: any disagreement would mean a missed retime.
   always @(posedge i_clk)
       assert (!stable || (clean == hist[0]));
endmodule

// PWM channel for a wire-logic accelerator block.
// Period counter walks 0..PER-1, duty is double buffered at the period edge,
// and high_cnt accumulates the number of high cycles elapsed in the period.
module pwm_channel (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire       i_load,
    input  wire [3:0] i_duty,
    output wire       pwm_out,
    output reg        armed
);
    localparam [3:0] PER = 4'd12;
   localparam [3:0] HALF = 4'd6;   // the period is walked as two half windows

   reg [3:0] cnt;       // sub-counter inside the current half, 0 .. HALF-1
   reg       half;      // 0 = first half of the period, 1 = second half
    reg [3:0] duty;      // active duty, 0 .. PER
    reg [3:0] high_cnt;  // high cycles elapsed so far this period
   reg       pwm_q;     // registered output stage, resolved one cycle ahead
  reg [3:0] duty_b;    // nested window duty, kept inside the main window
  reg       pwm_b_q;   // registered output stage of the nested window
  reg       sel;       // owner of the shared duty load port: 0 = main, 1 = nested

    initial begin
        cnt      = 4'd0;
       half     = 1'b0;
        duty     = 4'd0;
        high_cnt = 4'd0;
        armed    = 1'b0;
       pwm_q    = 1'b0;
       duty_b   = 4'd0;
       pwm_b_q  = 1'b0;
       sel      = 1'b0;
    end

    // the construct: output high exactly while the counter is below the duty
  // both windows share one open-drain pad, so the pin is the wire-OR of the
  // two output stages
  assign pwm_out = pwm_q | pwm_b_q;

    wire [3:0] duty_clamped = (i_duty > PER) ? PER : i_duty;
   wire       at_half      = (cnt == HALF - 4'd1);
   wire       at_edge      = half && at_half;
   // full period phase reassembled from the two halves, 0 .. PER-1
   wire [3:0] phase        = half ? (cnt + HALF) : cnt;

   // Next-cycle counter and duty. The output register is loaded from these so
   // the pin keeps the same alignment the combinational comparator had, while
   // the compare itself is off the critical path.
  wire [3:0] cnt_nxt   = at_half ? 4'd0 : cnt + 4'd1;
  wire       half_nxt  = at_half ? ~half : half;
  wire [3:0] phase_nxt = at_edge ? 4'd0 : phase + 4'd1;
 wire [3:0] duty_nxt = (at_edge && i_load && !sel) ? duty_clamped : duty;
 // The nested window is clamped into the main window when it is loaded, and
 // retrimmed whenever the main channel takes a smaller duty.
 wire [3:0] duty_b_req  = (i_duty > duty) ? duty : i_duty;
 wire [3:0] duty_b_trim = (duty_b > duty_clamped) ? duty_clamped : duty_b;
 wire [3:0] duty_b_nxt  = (at_edge && i_load) ? (sel ? duty_b_req : duty_b_trim)
                                              : duty_b;

    always @(posedge clk) begin
        if (rst) begin
            cnt      <= 4'd0;
           half     <= 1'b0;
            duty     <= 4'd0;
            high_cnt <= 4'd0;
            armed    <= 1'b0;
           pwm_q    <= 1'b0;
           duty_b   <= 4'd0;
           pwm_b_q  <= 1'b0;
           sel      <= 1'b0;
        end else if (i_ce) begin
          pwm_q <= (phase_nxt < duty_nxt);
         pwm_b_q <= (phase_nxt < duty_b_nxt);
            if (at_edge) begin
                // period rolls over: new duty takes effect, accumulator clears
                cnt      <= 4'd0;
               half     <= 1'b0;
                high_cnt <= 4'd0;
                armed    <= 1'b1;            // sticky, never cleared
               sel <= ~sel;                 // round-robin the shared load port
               if (i_load) begin
                   if (sel) begin
                       duty_b <= duty_b_req;
                   end else begin
                       duty   <= duty_clamped;
                       duty_b <= duty_b_trim;
                   end
               end
            end else begin
               cnt      <= cnt_nxt;
               half     <= half_nxt;
                high_cnt <= high_cnt + (pwm_out ? 4'd1 : 4'd0);
            end
        end
    end

    // Property (universality, after the first completed period):
    // the accumulated high time never exceeds the duty, and the live output
    // agrees with the accumulator's headroom.
    always @(posedge clk)
        if (armed)
            assert (high_cnt <= duty);

    always @(posedge clk)
        if (armed)
            assert (pwm_out == (high_cnt < duty));
endmodule

module elevator_call_gen (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output reg  [1:0] floor,
    output reg        dir,
    output reg  [3:0] pending,
    output reg  [2:0] dry_cnt,
    output reg  [3:0] lf
);
// Pseudo-random hall-call source.  The shift chain and its feedback XOR
// are split across two flops: the tap is evaluated one cycle ahead into
// lf_fb and shifted in on the next enabled step, which keeps the XOR
// gate out of the shift path.  Taps are chosen so that the combined
// 5-bit generator state {lf, lf_fb} is maximal length (period 31).
reg lf_fb;
// Quiet watchdog: reloaded on every hall call and decremented on every
// silent enabled step.  It is the budget of steps the generator may stay
// quiet before the cab is handed a target of its own.
reg [2:0] quiet_wd;
// Hall calls reach the cab through a one-deep request stage: the
// generator's decision and its floor are captured here and acted on
// the following enabled step, keeping the call decode off the
// pending-mask and watchdog paths.
reg       call_v;
reg [1:0] call_fl;

initial lf_fb   = 1'b0;
    initial lf      = 4'b0001;
    initial floor   = 2'd0;
    initial dir     = 1'b1;   // 1 = up, 0 = down
    initial pending = 4'b0000;
    initial dry_cnt = 3'd0;
    initial quiet_wd = 3'd3;
    initial call_v  = 1'b0;
    initial call_fl = 2'd0;

wire       lf_fb_next = lf[3] ^ lf[1];
wire [3:0] lf_next    = {lf[2:0], lf_fb};

// A pseudo-random hall call is issued unless the top three shift
// stages of the generator are all zero.
    wire       new_call   = (lf[3:1] != 3'b000);
    wire [1:0] call_floor = lf[1:0];

    wire at_top = (floor == 2'd3);
    wire at_bot = (floor == 2'd0);

    wire [1:0] floor_next = dir ? (at_top ? floor : floor + 2'd1)
                                : (at_bot ? floor : floor - 2'd1);
    wire       dir_next   = dir ? (at_top ? 1'b0 : 1'b1)
                                : (at_bot ? 1'b1 : 1'b0);

    // On the watchdog's last tick a call at the top floor is synthesized,
    // so a quiet generator cannot leave the cab without work.
    wire       wd_last    = (quiet_wd <= 3'd1);
    wire [3:0] set_mask   = call_v ? (4'b0001 << call_fl)
                                   : (wd_last ? 4'b1000 : 4'b0000);
    wire [3:0] clr_mask   = (4'b0001 << floor);

    always @(posedge clk) begin
        if (rst) begin
            lf      <= 4'b0001;
lf_fb   <= 1'b0;
            floor   <= 2'd0;
            dir     <= 1'b1;
            pending <= 4'b0000;
            dry_cnt <= 3'd0;
            quiet_wd <= 3'd3;
            call_v  <= 1'b0;
            call_fl <= 2'd0;
        end else if (step) begin
            lf      <= lf_next;
lf_fb   <= lf_fb_next;
            call_v  <= new_call;
            call_fl <= call_floor;
            floor   <= floor_next;
            dir     <= dir_next;
            pending <= (pending | set_mask) & ~clr_mask;
            // consecutive enabled steps during which no new call appeared
            dry_cnt <= call_v ? 3'd0 : (dry_cnt + 3'd1);
            quiet_wd <= call_v ? 3'd3
                               : (quiet_wd == 3'd0 ? 3'd0 : quiet_wd - 3'd1);
        end
    end

    // Bounded existence: the call-starvation streak never exceeds 3,
    // although the counter is 3 bits wide.
    assert property (dry_cnt <= 3'd3);

    // The watchdog always has budget left over: calls arrive in time.
    always @(posedge clk)
        assert (quiet_wd >= 3'd1);
endmodule

module wdog_scan (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // scanner step enable; low => whole design idles
    input  wire i_kick,    // full substring match: hard kick of the watchdog
    input  wire i_feed,    // partial match: partial credit, no flag clear
    output wire o_timeout,
    output wire [7:0] o_pos
);
    // Watchdog for a character-scan engine: the scanner must report progress
    // before LIMIT idle steps elapse, otherwise the search is declared timed out.
    localparam [3:0] LIMIT = 4'd12;

    reg [3:0] wd;       // cycles since last progress, saturates at LIMIT
    reg       expired;  // sticky timeout flag
    reg [7:0] pos;      // current character position in the haystack
    reg [3:0] slack;    // remaining scan budget exported to the prefetch stride
   // The counter maths sits in the scan pipeline's ALU stage: credit, spend and
   // saturate land here first and are committed onto the report bus (the two
   // registers above) on the following scan step.
   reg [3:0] wd_s;     // watchdog count, arithmetic stage
   reg [3:0] slack_s;  // scan budget, arithmetic stage
    // The timeout flag sits on the report bus, four scan steps downstream of
    // the counter, so a saturation event is registered through this pipe
    // before it is visible to the host.
    reg       exp_s0;   // expiry report, stage 0
    reg       exp_s1;   // expiry report, stage 1
    reg       exp_s2;   // expiry report, stage 2
    reg       exp_s3;   // expiry report, stage 3

    initial wd      = 4'd0;
    initial expired = 1'b0;
    initial pos     = 8'd0;
    initial slack   = LIMIT;
   initial wd_s    = 4'd0;
   initial slack_s = LIMIT;
    initial exp_s0  = 1'b0;
    initial exp_s1  = 1'b0;
    initial exp_s2  = 1'b0;
    initial exp_s3  = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            wd      <= 4'd0;
            expired <= 1'b0;
            pos     <= 8'd0;
            slack   <= LIMIT;
           wd_s    <= 4'd0;
           slack_s <= LIMIT;
            exp_s0  <= 1'b0;
            exp_s1  <= 1'b0;
            exp_s2  <= 1'b0;
            exp_s3  <= 1'b0;
        end else if (i_ce) begin
            // plenty of budget left => the scanner may consume two
            // characters in a single step
            pos <= pos + ((slack > 4'd8) ? 8'd2 : 8'd1);
           // commit the previous step's arithmetic onto the report bus
           wd    <= wd_s;
           slack <= slack_s;
            // walk the report pipe one stage per scan step; nothing new
            // enters unless the counter saturates this step
            exp_s0 <= 1'b0;
            exp_s1 <= exp_s0;
            exp_s2 <= exp_s1;
            exp_s3 <= exp_s2;
            if (exp_s3)
                expired <= 1'b1;
            if (i_kick) begin
                // full match: reload the watchdog and drop the timeout flag
                wd      <= 4'd0;
                expired <= 1'b0;
                slack   <= LIMIT;
               wd_s    <= 4'd0;
               slack_s <= LIMIT;
                // the reload also flushes any report still in flight
                exp_s0  <= 1'b0;
                exp_s1  <= 1'b0;
                exp_s2  <= 1'b0;
                exp_s3  <= 1'b0;
            end else if (i_feed) begin
                // partial credit: only granted while the counter has not
                // saturated.  Note the gate looks at the COUNTER, not the flag.
               if (wd_s != LIMIT)
                   wd_s <= (wd_s > 4'd4) ? (wd_s - 4'd4) : 4'd0;
                // partial credit also refunds budget, capped at the reload value
               if (slack_s != 4'd0)
                   slack_s <= (slack_s < 4'd8) ? (slack_s + 4'd4) : LIMIT;
            end else begin
                // no progress this step: count up and saturate at LIMIT
               if (wd_s != LIMIT) begin
                   wd_s <= wd_s + 4'd1;
                   if ((wd_s + 4'd1) == LIMIT)
                        exp_s0 <= 1'b1;
                end
                // spend one unit of budget per idle step, floor at zero
               if (slack_s != 4'd0)
                   slack_s <= slack_s - 4'd1;
            end
        end
    end

    assign o_timeout = expired;
    assign o_pos     = pos;

    // P: a reported timeout always comes with a counter in the top half of
    // its range (the watchdog really did run out of slack).
    always @(posedge clk) assert (!expired || wd[3]);

    // Q: a reported timeout means the exported scan budget is exhausted,
    // so downstream stride logic has already dropped back to one char/step.
    always @(posedge clk) assert (!expired || slack == 4'd0);
endmodule

module dma_copier_chain (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_clear,
    input  wire [3:0] i_len,
    output wire       o_done,
    output wire       o_busy,
    output wire       o_err
);
    // phase slice codes (gray-ish), each with its stored parity bit
    localparam [1:0] PH_IDLE  = 2'b00,   // parity 0
                     PH_ARMED = 2'b01,   // parity 1
                     PH_BUSY  = 2'b11,   // parity 0
                     PH_DONE  = 2'b10;   // parity 1

    // parity-protected register slice holding the engine phase
    reg [1:0] phase   = PH_IDLE;
    reg       par     = 1'b0;

    // descriptor word counter
    reg [3:0] count   = 4'd0;

    // chain history bits: arm happened, start happened
    reg       h_arm   = 1'b0;
    reg       h_start = 1'b0;
    // start handshake stage: the start pulse is captured here for the
    // descriptor-fetch cycle and is only then logged into h_start
    reg       s_pend  = 1'b0;

   // descriptor status shadow: while a descriptor is in flight the
   // "start beat seen" record is kept here; it is only folded into the
   // chain log when the descriptor actually retires
   reg       sh_start = 1'b0;

  // descriptor ledger: one log entry per descriptor issued to the burst
  // engine and one per descriptor retired.  Both counters free-run and
  // wrap; their difference is the number of descriptors still in flight.
  reg [3:0] n_iss = 4'd0;
  reg [3:0] n_ret = 4'd0;

  wire [3:0] outstanding = n_iss - n_ret;
  // the engine is single-descriptor: at most one may be outstanding, and
  // it must agree with the in-flight status bits of the slice
  wire ledger_bad = (outstanding != {3'd0, (s_pend || sh_start)});

    // slice checker: stored parity must match stored phase
wire slice_bad = (par != (^phase)) || (phase == PH_IDLE && sh_start) || ledger_bad;

    always @(posedge clk) begin
        if (i_ce) begin
            if (slice_bad) begin
                // corrupted descriptor slice: abort, report done immediately
                phase <= PH_DONE;
                par   <= 1'b1;
            end else begin
                case (phase)
                PH_IDLE:
                    if (i_arm) begin
                        phase   <= PH_ARMED;
                        par     <= 1'b1;
                        count   <= i_len;
                        h_arm   <= 1'b1;
                    end
                PH_ARMED:
                    if (i_start) begin
                        phase   <= PH_BUSY;
                        par     <= 1'b0;
                        s_pend  <= 1'b1;
n_iss   <= n_iss + 4'd1;
                    end
                PH_BUSY:
                    if (s_pend) begin
                        // first burst cycle fetches the descriptor word,
                       // no payload word moves and the length is untouched;
                       // the start beat lands in the status shadow, not yet
                       // in the chain log
                        s_pend  <= 1'b0;
                       sh_start <= 1'b1;
                    end else if (count == 4'd0) begin
                        phase <= PH_DONE;
                        par   <= 1'b1;
                       // retire: commit the in-flight status into the chain
                       // log and release the shadow for the next descriptor
                       h_start  <= sh_start;
                       sh_start <= 1'b0;
n_ret    <= n_ret + 4'd1;
                    end else begin
                        count <= count - 4'd1;
                    end
                PH_DONE:
                    if (i_clear) begin
                        phase <= PH_IDLE;
                        par   <= 1'b0;
                    end
                endcase
            end
        end
    end

    assign o_done = (phase == PH_DONE);
    assign o_busy = (phase == PH_BUSY);
    assign o_err  = slice_bad;

    // chain precedence, globally: a finish can never be seen unless the
    // arm step and then the start step were actually taken
    always @(posedge clk)
        if (phase == PH_DONE) assert (h_arm);

    always @(posedge clk)
        if (phase == PH_DONE) assert (h_start);
endmodule

module gray_shadow_ctr (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    output wire [3:0] o_gray,
output wire [3:0] o_bin,
output reg  [3:0] ce_hist
);
    // Binary shadow counter and its gray-coded twin.  The gray register is
    // advanced by the classic single-bit-toggle rule, computed from the gray
    // value alone; the binary shadow is a plain increment.
// The shadow count is split: the low three bits take the increment, and the
// top bit is a separate flop toggled by a carry term that is precomputed one
// cycle ahead (lo_max), so the top bit never hangs off the low adder's carry
// chain.  lo_max is only re-evaluated on cycles that actually advance the
// count, so it is static while the counter is stalled.
reg [2:0] bin_lo;
reg       bin_hi;
reg       lo_max;
wire [3:0] bin = {bin_hi, bin_lo};
    reg [3:0] gray;
    reg       pv;
   reg [3:0] gray_s;
   reg       s_vld;
reg       ce_d;

initial bin_lo = 3'b000;
initial bin_hi = 1'b0;
initial lo_max = 1'b0;
    initial gray = 4'b0000;
    initial pv   = 1'b0;
   initial gray_s = 4'b0000;
   initial s_vld  = 1'b0;
initial ce_d    = 1'b0;
initial ce_hist = 4'b0000;

    // Next gray value: toggle bit 0 when the parity is even, otherwise toggle
    // the bit just above the lowest set bit (with the top bit handling wrap).
    function [3:0] gnext(input [3:0] g);
        begin
            if (!(^g))     gnext = g ^ 4'b0001;
            else if (g[0]) gnext = g ^ 4'b0010;
            else if (g[1]) gnext = g ^ 4'b0100;
            else           gnext = g ^ 4'b1000;
        end
    endfunction

   // Stage 1: the gray pointer is advanced one cycle ahead of the output
   // registers, so o_gray leaves the block straight off a flop instead of
   // through the toggle-select network.  s_vld marks the staged word as a
   // pending advance that the commit stage still owes the outputs.
   always @(posedge clk) begin
       if (rst) begin
           gray_s <= 4'b0000;
           s_vld  <= 1'b0;
ce_d    <= 1'b0;
ce_hist <= 4'b0000;
       end else begin
           s_vld <= i_ce;
ce_d    <= i_ce;
ce_hist <= {ce_hist[2:0], ce_d};
           if (i_ce) gray_s <= gnext(gray_s);
       end
   end

   // Stage 2: commit the staged pointer and bump the binary shadow in the
   // same cycle, so the two views never disagree at the outputs.

    always @(posedge clk) begin
        if (rst) begin
bin_lo <= 3'b000;
bin_hi <= 1'b0;
lo_max <= 1'b0;
            gray <= 4'b0000;
       end else if (s_vld) begin
bin_lo <= bin_lo + 3'b001;
bin_hi <= bin_hi ^ lo_max;
lo_max <= (bin_lo == 3'b110);
           gray <= gray_s;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign o_gray = gray;
    assign o_bin  = bin;

    // Top bit of the gray word and top bit of the binary shadow: the most
    // significant gray bit is just the most significant binary bit, so neither
    // may move without the other.
    wire g_msb = gray[3];
    wire b_msb = bin[3];

    // P: whenever the gray MSB did not change, the shadow MSB did not change.
    always @(posedge clk)
        if (pv && $stable(g_msb))
            assert ($stable(b_msb));
endmodule

module lock_arbiter_occ (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire [3:0] i_req,
    output wire [3:0] o_grant,
    output wire       o_busy
);
    // fixed-priority arbiter with a lock bit that freezes the winner
    reg [3:0] grant;
    reg       lock;
    // shadow occupancy counter: how many grants are currently outstanding
    reg [2:0] occ;
    // lock-hold timer: beats the current owner has held the bus
    reg [2:0] hold_cnt;
   // bus turnaround: dead beats after a release before the slot is freed
   reg [1:0] tail_cnt;
   // one-deep drain slot: a released owner keeps its occupancy credit
   // here until the credit-return beat that follows the turnaround
   reg        drn;

    initial grant = 4'b0000;
    initial lock  = 1'b0;
    initial occ   = 3'd0;
    initial hold_cnt = 3'd0;
   initial tail_cnt = 2'd0;
   initial drn = 1'b0;

    wire        busy    = (grant != 4'b0000);
    wire        any_req = (i_req != 4'b0000);

    // fixed priority: channel 0 highest
    wire [3:0] pri_grant = i_req[0] ? 4'b0001 :
                           i_req[1] ? 4'b0010 :
                           i_req[2] ? 4'b0100 :
                           i_req[3] ? 4'b1000 : 4'b0000;
    // anti-starvation: the lock expires after 5 held beats so lower channels can win
    wire lock_expired = (hold_cnt >= 3'd5);

    // while locked, the current winner keeps the bus as long as it still asks
    wire holding = busy && lock && !lock_expired && ((grant & i_req) != 4'b0000);

    always @(posedge i_clk) begin
        if (i_rst) begin
            grant <= 4'b0000;
            lock  <= 1'b0;
            occ   <= 3'd0;
            hold_cnt <= 3'd0;
           tail_cnt <= 2'd0;
           drn <= 1'b0;
        end else if (i_ce) begin
            if (busy) begin
                if (!holding) begin
                   // winner released: drop the grant and start the bus turnaround
                    grant <= 4'b0000;
                    lock  <= 1'b0;
                   tail_cnt <= 2'd2;
                    hold_cnt <= 3'd0;
                   drn <= 1'b1;
                end
                else begin
                    // still holding: age the lock
                    hold_cnt <= hold_cnt + 3'd1;
                end
           end else if (tail_cnt != 2'd0) begin
              // turnaround: dead beats before the drain slot may empty
               tail_cnt <= tail_cnt - 2'd1;
          end else if (drn) begin
              // credit-return beat: the drain slot empties and the pool refills
              drn <= 1'b0;
              occ <= occ - 3'd1;
           end else if (any_req) begin
                // bus free: award it and lock it
                grant <= pri_grant;
                lock  <= 1'b1;
                occ   <= occ + 3'd1;
                hold_cnt <= 3'd0;
            end
        end
    end

    assign o_grant = grant;
  assign o_busy  = busy || (tail_cnt != 2'd0) || drn;

    // at most one grant may be outstanding at any time
    always @(*)
        assert (occ <= 3'd1);

    // the hold timer only ages while a grant is outstanding
    always @(posedge i_clk)
        assert ((hold_cnt == 3'd0) || (occ == 3'd1));
endmodule

module gray_quantum_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // scheduler quantum tick enable
    output wire [3:0] o_gray,
    output wire [2:0] o_ones
);
    // Ten quantum slots (0..9). The binary shadow does the arithmetic,
    // the gray register is what leaves the clock domain. Terminal count is
    // detected on the gray word, as the CDC-facing logic sees it.
    localparam [3:0] GRAY_LAST = 4'b1101; // gray code of 4'd9

    reg [3:0] bin  = 4'd0;
    reg [3:0] gray = 4'b0000;

   // Lane B is the second scheduler quantum lane. To save area the two
   // lanes time-share one binary shadow and one increment/encode
   // datapath: the owner named by `turn` uses `bin`, the parked lane's
   // shadow waits in `bin_hold`, and the pair swaps on every tick.
   reg [3:0] gray_b   = 4'b0000;
   reg [3:0] bin_hold = 4'd0;
   reg       turn     = 1'b0;   // 0: lane A owns the shared shadow

  // Lane C is the third quantum lane (background dispatch class). It
  // joins the same time-share: the shadow of the lane two slots ahead of
  // the owner parks in `bin_hold2`, and `grp` widens the ownership
  // pointer so the trio rotates A -> B -> C -> A, one hand-off per tick.
  reg [3:0] gray_c    = 4'b0000;
  reg [3:0] bin_hold2 = 4'd0;
  reg       grp       = 1'b0;   // {turn,grp}: 00 = A, 1x = B, 01 = C


  wire [3:0] gray_sel = turn ? gray_b : (grp ? gray_c : gray);

   wire       wrap    = (gray_sel == GRAY_LAST);
    wire [3:0] bin_nxt = wrap ? 4'd0 : (bin + 4'd1);

    // occupancy of the gray word: how many lanes are asserted this slot
    wire [2:0] ones = {2'b00, gray[0]} + {2'b00, gray[1]} +
                      {2'b00, gray[2]} + {2'b00, gray[3]};
    wire       occ_hi = (ones >= 3'd3);

    assign o_gray = gray;
    assign o_ones = ones;

    always @(posedge clk) begin
        if (rst) begin
            bin  <= 4'd0;
            gray <= 4'b0000;
           gray_b   <= 4'b0000;
           bin_hold <= 4'd0;
           turn     <= 1'b0;
          gray_c    <= 4'b0000;
          bin_hold2 <= 4'd0;
          grp       <= 1'b0;
        end else if (i_ce) begin
          // the lane owning the datapath advances its gray word, then the
          // shared shadow is handed to the next lane in the rotation
          if (turn)     gray_b <= bin_nxt ^ (bin_nxt >> 1);
          else if (grp) gray_c <= bin_nxt ^ (bin_nxt >> 1);
          else          gray   <= bin_nxt ^ (bin_nxt >> 1);
          bin       <= bin_hold;
          bin_hold  <= bin_hold2;
          bin_hold2 <= bin_nxt;
          turn      <= !turn && !grp;
          grp       <= turn;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Bounded existence: the gray word never carries four asserted lanes,
    // so whenever the high-occupancy flag rises it rises to exactly three.
    always @(posedge clk)
        if (pv && $rose(occ_hi))
            assert (ones == 3'd3);

   // Lane coherence: the swap is only half done while lane B holds the
   // shared shadow. Once ownership is back with lane A both lanes have
   // been advanced to the same quantum slot, so the two gray words the
   // CDC side can sample are identical.
   always @(posedge clk)
       if (pv) assert (turn || (gray == gray_b));
endmodule

module csa_accum_parity (
    input  wire       clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_clear,
    input  wire [7:0] i_data,
    output wire [7:0] o_total,
output wire [7:0] o_ref,
output wire [3:0] o_evt_cnt
);
    // accumulator kept in carry-save form: two halves that always sum to the
    // true running total held in the reference register
    reg [7:0] acc_s = 8'h00;   // sum half
    reg [7:0] acc_c = 8'h00;   // carry half (always even by construction)
reg [3:0] total  = 4'h0;   // reference accumulator, low nibble slice
reg [3:0] tot_hi = 4'h0;   // reference accumulator, high nibble slice
    reg        hi_flag = 1'b0; // registered "total has reached the upper half";
                               // precomputed on the adder result so the flush
                               // path next cycle is just a flop-to-mux hop
reg [3:0] evt_cnt = 4'h0;  // distractor: counts enabled cycles with nonzero input

    wire [7:0] sum_bits   = acc_s ^ acc_c ^ i_data;
    wire [7:0] maj_bits   = (acc_s & acc_c) | (acc_s & i_data) | (acc_c & i_data);
    wire [7:0] carry_bits = {maj_bits[6:0], 1'b0};
// reference adder is built from two nibble slices so neither carry chain
// spans the whole word; the upper slice is only clocked on cycles where it
// can actually change, which keeps it quiet for small operands
wire [4:0] lo_sum     = {1'b0, total} + {1'b0, i_data[3:0]};
wire       lo_cout    = lo_sum[4];
wire [3:0] hi_sum     = tot_hi + i_data[7:4] + {3'b0, lo_cout};
wire       hi_en      = lo_cout || (i_data[7:4] != 4'h0);
wire [7:0] next_total = {hi_sum, lo_sum[3:0]};

    always @(posedge clk) begin
        if (i_rst) begin
            acc_s <= 8'h00;
            acc_c <= 8'h00;
total  <= 4'h0;
tot_hi <= 4'h0;
            hi_flag <= 1'b0;
evt_cnt <= 4'h0;
        end else if (i_ce) begin
evt_cnt <= evt_cnt + {3'b0, (i_data != 8'h00)};
            if (i_clear || hi_flag) begin
                acc_s <= 8'h00;
                acc_c <= 8'h00;
total  <= 4'h0;
tot_hi <= 4'h0;
                hi_flag <= 1'b0;
            end else begin
                acc_s <= sum_bits;
                acc_c <= carry_bits;
total   <= next_total[3:0];
if (hi_en)
    tot_hi <= next_total[7:4];
                hi_flag <= next_total[7];
            end
        end
    end

    assign o_total = acc_s + acc_c;
assign o_ref   = {tot_hi, total};
assign o_evt_cnt = evt_cnt;

    // P: while the unit is actually accumulating, the low bit of the sum half
    // alone already carries the parity of the true total.
    always @(posedge clk)
        if (i_ce && !i_clear)
            assert (acc_s[0] == total[0]);

    // P2: the flush flag was computed from the adder result, so it must still
    // describe the value the carry-save side is currently reporting.
    always @(posedge clk)
        assert (hi_flag == o_total[7]);
endmodule

module hwm_stack_ptr (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_push,
    input  wire       i_pop,
    output wire       o_deep,
    output wire [3:0] o_mark,
    output wire [3:0] o_sp
);
    localparam [3:0] THRESH = 4'd4;

    // stack pointer and its high-water mark
    reg [3:0] sp;
    reg [3:0] hwm;
    reg       mark_deep;   // registered "mark has crossed THRESH" flag
    reg       pv;          // past-valid

   // push/pop event ledger for depth accounting: every accepted push and
   // every accepted pop is logged, and the difference of the two counters
   // is the occupancy the mark logic trusts
   reg [3:0] n_push;
   reg [3:0] n_pop;

  // deep-region episode ledger: one entry logged each time the pointer
  // crosses up into the deep region, one exit each time it drops back out
  reg [3:0] n_ent;
  reg [3:0] n_ext;

    initial sp        = 4'd0;
    initial hwm       = 4'd0;
    initial mark_deep = 1'b0;
    initial pv        = 1'b0;
   initial n_push    = 4'd0;
   initial n_pop     = 4'd0;
  initial n_ent     = 4'd0;
  initial n_ext     = 4'd0;

    wire do_push = i_ce && i_push && !i_pop && (sp != 4'hF);
    wire do_pop  = i_ce && i_pop  && !i_push && (sp != 4'h0);

    wire [3:0] sp_nx  = do_push ? (sp + 4'd1)
                      : (do_pop ? (sp - 4'd1) : sp);

   wire [3:0] n_push_nx = do_push ? (n_push + 4'd1) : n_push;
   wire [3:0] n_pop_nx  = do_pop  ? (n_pop  + 4'd1) : n_pop;

   // occupancy as seen by the ledger after this cycle's events
   wire [3:0] occ_nx    = n_push_nx - n_pop_nx;

  wire ent_evt = do_push && (sp == (THRESH - 4'd1));
  wire ext_evt = do_pop  && (sp == THRESH);

  wire [3:0] n_ent_nx = ent_evt ? (n_ent + 4'd1) : n_ent;
  wire [3:0] n_ext_nx = ext_evt ? (n_ext + 4'd1) : n_ext;

  // an episode is open while the entry and exit logs disagree; for the
  // whole episode the mark reserves one guard slot above the threshold
  wire       deep_open = (n_ent != n_ext);
  wire [3:0] guard     = deep_open ? (THRESH + 4'd1) : 4'd0;

   // the mark must cover both the pointer and the logged occupancy
  wire [3:0] mark_hi   = (sp_nx > occ_nx) ? sp_nx : occ_nx;
  wire [3:0] mark_lo   = (mark_hi > guard) ? mark_hi : guard;

    // the mark never falls below the pointer and only ratchets upward
   wire [3:0] hwm_nx = (mark_lo > hwm) ? mark_lo : hwm;

    always @(posedge clk) begin
        if (i_ce) begin
            sp        <= sp_nx;
            hwm       <= hwm_nx;
            mark_deep <= (hwm_nx >= THRESH);
           n_push    <= n_push_nx;
           n_pop     <= n_pop_nx;
          n_ent     <= n_ent_nx;
          n_ext     <= n_ext_nx;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign o_deep = mark_deep;
    assign o_mark = hwm;
    assign o_sp   = sp;

    // Precedence: the deep-mark flag can only rise because the pointer itself
    // has just reached that depth, so the depth must be visible right now.
    always @(posedge clk)
        if (pv && $rose(mark_deep))
            assert (sp >= THRESH);

endmodule

module hist_precedence (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_op,     // 0 = add one sample to bin i_sel, 1 = remove one
    input  wire [1:0] i_sel,
output reg  [5:0] total,
output reg  [3:0] ce_count
);
    // histogram bins
    reg [3:0] bin0, bin1, bin2, bin3;

    // shadow of the earlier event: which bin got the very first sample
    reg [1:0] first_bin;
    reg       saw_sample;

    // scope arming register: high until the first removal aimed at first_bin
    reg       pre_purge;

    // shadow high-water mark of the first-sampled bin's count
    reg [3:0] hi_first;

   // staged high-water update: the shadow compare is registered, so a
   // candidate count lands in hi_first one enabled cycle later
   reg [3:0] hw_pend;
   reg       hw_vld;
// distractor bookkeeping: history of the op input on enabled cycles
reg [3:0] op_shift;

    initial begin
        bin0       = 4'd0;
        bin1       = 4'd0;
        bin2       = 4'd0;
        bin3       = 4'd0;
        total      = 6'd0;
        first_bin  = 2'd0;
        saw_sample = 1'b0;
        pre_purge  = 1'b1;
        hi_first   = 4'd0;
       hw_pend    = 4'd0;
       hw_vld     = 1'b0;
op_shift   = 4'd0;
ce_count   = 4'd0;
    end

    wire [3:0] sel_cnt   = (i_sel == 2'd0) ? bin0 :
                           (i_sel == 2'd1) ? bin1 :
                           (i_sel == 2'd2) ? bin2 : bin3;

    wire [3:0] first_cnt = (first_bin == 2'd0) ? bin0 :
                           (first_bin == 2'd1) ? bin1 :
                           (first_bin == 2'd2) ? bin2 : bin3;

   // acquisition freezes once the first-sampled bin has saturated
   wire frozen = (hi_first == 4'd15);


   wire do_add = i_ce && !i_op && (total != 6'd31) && (sel_cnt != 4'd15) && !frozen;
    wire do_rem = i_ce &&  i_op && (sel_cnt != 4'd0);
    wire purge  = i_ce &&  i_op && saw_sample && (i_sel == first_bin);

    wire armed  = pre_purge && saw_sample;

    // count the first-sampled bin will hold after this cycle
    wire [3:0] first_nxt =
        (do_add && !saw_sample)                          ? (sel_cnt   + 4'd1) :
        (do_add && saw_sample && (i_sel == first_bin))    ? (first_cnt + 4'd1) :
        (do_rem && saw_sample && (i_sel == first_bin))    ? (first_cnt - 4'd1) :
                                                            first_cnt;

    always @(posedge clk) begin
        if (i_ce) begin
            if (do_add) begin
                total <= total + 6'd1;
                case (i_sel)
                    2'd0:    bin0 <= bin0 + 4'd1;
                    2'd1:    bin1 <= bin1 + 4'd1;
                    2'd2:    bin2 <= bin2 + 4'd1;
                    default: bin3 <= bin3 + 4'd1;
                endcase
                if (!saw_sample) begin
                    saw_sample <= 1'b1;
                    first_bin  <= i_sel;
                end
            end else if (do_rem) begin
                total <= total - 6'd1;
                case (i_sel)
                    2'd0:    bin0 <= bin0 - 4'd1;
                    2'd1:    bin1 <= bin1 - 4'd1;
                    2'd2:    bin2 <= bin2 - 4'd1;
                    default: bin3 <= bin3 - 4'd1;
                endcase
            end

            if (purge)
                pre_purge <= 1'b0;

           // commit the candidate captured on the previous enabled cycle
           if (hw_vld && (hw_pend > hi_first))
               hi_first <= hw_pend;


           if (do_add && !saw_sample) begin
               hw_pend <= sel_cnt + 4'd1;
               hw_vld  <= 1'b1;
           end else if (first_nxt > hi_first) begin
               hw_pend <= first_nxt;
               hw_vld  <= 1'b1;
           end else begin
               hw_vld  <= 1'b0;
           end
        end
    end

    // P: before any sample has ever been purged from the first-sampled bin,
    // the earlier arrival recorded in the shadow registers must still be
    // accounted for in the total-samples register.
    always @(posedge clk)
        if (armed) assert (total >= 6'd1);

    always @(posedge clk)
        if (armed) assert (total >= {2'b00, hi_first});
always @(posedge clk) begin
    if (i_ce) begin
        op_shift <= {op_shift[2:0], i_op};
        ce_count <= ce_count + 4'd1 + {3'd0, op_shift[3]};
    end
end
endmodule

module wdog_gray_mon (
    input  wire i_clk,
    input  wire i_rst,
    input  wire i_ce,      // idle condition: all state frozen when low
    input  wire i_arm,     // Q: opens the monitoring window
    input  wire i_ack,     // R: closes the monitoring window
    output wire o_bite,
    output wire o_grace,
    output wire o_sys_reset
);
    // ---- timer domain: free running gray coded tick pointer -------------
    reg [2:0] cnt;   // binary tick counter
    reg [2:0] g;     // registered gray code of cnt

    // ---- monitor domain: two flop synchronizer on the gray pointer ------
    reg [2:0] s1, s2;

    // monitor side tally of pointer advances observed since reset
    reg [2:0] adv_cnt;

    // ---- window / latched reset ----------------------------------------
    reg armed;
    reg rst_latch;

   // ---- warning marker --------------------------------------------------
   // Decoded pointer position at which the grace flag is raised.  The
   // marker is re-placed relative to the pointer each time the window is
   // closed, so successive windows warn at different phases of the lap.
   reg [2:0] warn;

    initial cnt       = 3'd0;
    initial g         = 3'd0;
    initial s1        = 3'd0;
    initial s2        = 3'd0;
    initial adv_cnt   = 3'd0;
    initial armed     = 1'b0;
    initial rst_latch = 1'b0;
   initial warn      = 3'd2;

    wire [2:0] nxt = cnt + 3'd1;

    always @(posedge i_clk)
        if (i_rst) begin
            cnt <= 3'd0;
            g   <= 3'd0;
        end else if (i_ce) begin
            cnt <= nxt;
            g   <= nxt ^ (nxt >> 1);
        end

    always @(posedge i_clk)
        if (i_rst) begin
            s1 <= 3'd0;
            s2 <= 3'd0;
            adv_cnt <= 3'd0;
        end else if (i_ce) begin
            s1 <= g;    // first flop: freshly captured pointer
            s2 <= s1;   // second flop: stable pointer sample
            // every time the stable sample moves, the monitor has seen
            // one more tick of the timer domain
            if (s1 != s2) adv_cnt <= adv_cnt + 3'd1;
        end

    // gray -> binary decode of both synchronizer stages
    wire [2:0] mon = { s2[2], s2[2]^s2[1], s2[2]^s2[1]^s2[0] };
    wire [2:0] pre = { s1[2], s1[2]^s1[1], s1[2]^s1[1]^s1[0] };

    // terminal count seen on the stable sample -> watchdog bites
    assign o_bite  = (mon == 3'd7);
    // deep inside the grace region on the freshly captured sample
   assign o_grace = (pre == warn);

    assign o_sys_reset = rst_latch;

    // half a lap of observed advances: by now the all zero power up sample
    // has been flushed out of the synchronizer
    wire startup_done = adv_cnt[2];

   // next marker placement: two ticks past where the pointer stands when
   // the window is closed
   wire [2:0] warn_nxt = pre + 3'd2;
   // a marker sitting on the terminal tick or on the wrap tick would put
   // the grace pulse on top of the bite, which is not a usable placement,
   // so an arm request is refused until the marker has been moved
   wire       warn_ok  = (warn != 3'd0) && (warn != 3'd7);

    always @(posedge i_clk)
        if (i_rst) begin
            armed     <= 1'b0;
            rst_latch <= 1'b0;
           warn      <= 3'd2;
        end else if (i_ce) begin
            if (i_ack)      armed <= 1'b0;
           else if (i_arm && warn_ok) armed <= 1'b1;

           // re-place the marker for the next window
           if (i_ack) warn <= warn_nxt;

            if (i_ack)                     rst_latch <= 1'b0;
            else if (armed && o_bite && startup_done)
                                           rst_latch <= 1'b1;
        end

    // P: inside the monitoring window the bite and grace indications are
    // never asserted together.
    always @(posedge i_clk)
        if (armed)
            assert (!(o_bite && o_grace));

    // P2: a bite is only ever reported when the monitor has tallied a full
    // lap of observed pointer advances.
    always @(posedge i_clk)
        assert (!o_bite || adv_cnt == 3'd7);
endmodule

module arb_lock_pending (
    input  wire       clk,
    input  wire       ce,      // global enable / idle when low
    input  wire [3:0] req,     // new requests, latched into pend
    input  wire       rel,     // current owner releases the lock
    output wire [3:0] grant,
    output wire [2:0] occupancy
);
    // pending request bitmap and its redundant occupancy counter
    reg [3:0] pend  = 4'b0000;
    reg [2:0] pcnt  = 3'd0;
reg [2:0] lcnt  = 3'd0;   // bank A entries admitted on the last credit
reg [3:0] late  = 4'b0000; // arrival class of each pending lane
   reg [2:0] bcnt  = 3'd0;   // bank B (indices 2,3) occupancy
    // fixed-priority arbiter with a lock bit freezing the winner
    reg       lock  = 1'b0;
    reg [1:0] owner = 2'd0;
    reg       pv    = 1'b0;   // past-valid

   // service ledger: every admission and every retirement is logged,
   // both counters free-run and wrap at four bits
   reg [3:0] n_in  = 4'd0;
   reg [3:0] n_out = 4'd0;

    // fixed priority: lowest index wins
// within bank A a fresh arrival outranks a late one; index breaks ties
wire [1:0] pick_a = (pend[0] && !late[0]) ? 2'd0 :
                    (pend[1] && !late[1]) ? 2'd1 :
                    pend[0]               ? 2'd0 : 2'd1;
wire [1:0] pick_b = pend[2] ? 2'd2 : 2'd3;
// drain the fuller bank first; ties break toward bank A
// work still outstanding per the ledger, and the bank A share of it
wire [3:0] bal     = n_in - n_out;
wire [2:0] a_bal   = bal[2:0] - bcnt;
wire       serve_b = (bcnt > a_bal);
wire [1:0] pick    = serve_b ? pick_b : pick_a;
    wire       any  = |pend;

    // service completion: the locked owner releases, its pending bit retires
    wire       do_clr   = ce && lock && rel;
    wire [3:0] clr_mask = do_clr ? (4'b0001 << owner) : 4'b0000;
    // only genuinely new requests are inserted
// credit limit: admission stops once three entries are outstanding
wire       adm      = (bal < 4'd3);
wire [3:0] set_mask = (ce && adm) ? (req & ~pend & ~clr_mask) : 4'b0000;
// the last credit is handed to late arrivals, which are booked apart
wire       mark_late = (bal >= 4'd2);
wire [3:0] late_set  = mark_late ? set_mask : 4'b0000;
wire [3:0] late_clr  = (set_mask & ~late_set) | clr_mask;
wire [3:0] fresh_set = set_mask & ~late_set;
wire [2:0] nset_a   = fresh_set[0] + fresh_set[1];
wire [2:0] nset_l   = late_set[0] + late_set[1];
wire [2:0] nset_b   = set_mask[2] + set_mask[3];
wire       dec_a    = do_clr && !owner[1] && !late[owner];
wire       dec_l    = do_clr && !owner[1] &&  late[owner];
wire       dec_b    = do_clr &&  owner[1];

    assign grant     = lock ? (4'b0001 << owner) : 4'b0000;
assign occupancy = pcnt + lcnt + bcnt;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ce) begin
            pend <= (pend | set_mask) & ~clr_mask;
pcnt <= pcnt + nset_a - (dec_a ? 3'd1 : 3'd0);
lcnt <= lcnt + nset_l - (dec_l ? 3'd1 : 3'd0);
late <= (late | late_set) & ~late_clr;
bcnt <= bcnt + nset_b - (dec_b ? 3'd1 : 3'd0);
n_in  <= n_in  + {1'b0, nset_a} + {1'b0, nset_l} + {1'b0, nset_b};
n_out <= n_out + {3'd0, dec_a} + {3'd0, dec_l} + {3'd0, dec_b};
            if (lock) begin
                if (rel)
                    lock <= 1'b0;      // frozen winner until it releases
            end else if (any) begin
                lock  <= 1'b1;
                owner <= pick;
            end
        end
    end

    // P: if the pending bitmap did not change, the occupancy must not have
    // changed either, and the occupancy stays within its real bound of 4.
    always @(posedge clk)
        if (pv && $stable(pend))
            assert ($stable(pcnt) && (pcnt <= 3'd4));
endmodule

// Serial debug-link pattern probe: detects the fixed 4-bit sync pattern 1101
// arriving MSB-first on i_bit, gated by the probe clock-enable i_ce.
// Match progress is tracked twice: as a binary progress counter (prog) and as
// an independently-updated one-hot shadow (hot). A 4-bit capture window (win)
// records the most recent bits seen.
// The window is assembled from a three-bit live shifter (win_lo) and a
// retired-oldest-bit register (win_hi) that is only loaded once the filler
// count (fill) has run out.
// A match is only declared once the capture window has been primed with four
// genuinely received bits: the match target (goal) starts above the reachable
// progress range and is stepped down to the pattern length, one step per
// probed bit, as the post-reset filler is shifted out of win.
module swd_sync_probe (
    input  wire clk,
    input  wire i_ce,      // probe strobe: low => link idle, all state frozen
    input  wire i_bit,     // serial bit from the debug pin
    output reg  detect     // registered pulse: full pattern just completed
);
    localparam [3:0] PATTERN = 4'b1101;

    reg [2:0] prog;        // match progress, 0..4 (4 == pattern length)
    reg [4:0] hot;         // one-hot shadow of the same progress
reg [2:0] win_lo;      // three newest bits: the live capture shifter
reg       win_hi;      // oldest window bit, retired out of the shifter
reg [1:0] fill;        // reset-filler slots still sitting in the window
reg [3:0] win;         // assembled capture window, MSB = oldest
    reg [3:0] goal;        // progress value that completes a match: 4 once the
                           // window is primed, >4 while win still holds filler

// the window is only whole once the oldest bit has been retired into win_hi
always @(*) win = {win_hi, win_lo};

    initial begin
        prog   = 3'd0;
        hot    = 5'b00001;
win_lo = 3'b000;
win_hi = 1'b0;
fill   = 2'd3;
        goal   = 4'd7;
        detect = 1'b0;
    end

    // ---- next progress from the binary counter -------------------------
    reg [2:0] nprog;
    always @(*) begin
        case (prog)
            3'd0:    nprog = i_bit ? 3'd1 : 3'd0;              // want 1
            3'd1:    nprog = i_bit ? 3'd2 : 3'd0;              // want 1
            3'd2:    nprog = i_bit ? 3'd2 : 3'd3;              // want 0
            3'd3:    nprog = i_bit ? 3'd4 : 3'd0;              // want 1
            3'd4:    nprog = i_bit ? 3'd2 : 3'd0;              // overlap "1"
            default: nprog = prog;
        endcase
    end

    // ---- next progress from the one-hot shadow (own state only) --------
    reg [4:0] nhot;
    always @(*) begin
        case (hot)
            5'b00001: nhot = i_bit ? 5'b00010 : 5'b00001;
            5'b00010: nhot = i_bit ? 5'b00100 : 5'b00001;
            5'b00100: nhot = i_bit ? 5'b00100 : 5'b01000;
            5'b01000: nhot = i_bit ? 5'b10000 : 5'b00001;
            5'b10000: nhot = i_bit ? 5'b00100 : 5'b00001;
            default:  nhot = 5'b00001;
        endcase
    end

// ---- window priming: one filler slot retires per probed bit --------
reg [1:0] nfill;
always @(*) nfill = (fill == 2'd0) ? 2'd0 : fill - 2'd1;

    always @(posedge clk) begin
        if (i_ce) begin
            prog   <= nprog;
            hot    <= nhot;
win_lo <= {win_lo[1:0], i_bit};
if (fill == 2'd0)
    win_hi <= win_lo[2];        // window full: retire the oldest live bit
fill   <= nfill;
goal   <= 4'd4 + {2'b00, nfill};
            detect <= (nprog == goal);
        end
    end

    // ---- property: two universal relations, globally --------------------
    always @(posedge clk) begin
        assert (detect == hot[4]);
        if (prog == 3'd4)
            assert (win == PATTERN);
    end
endmodule

module fourphase_occupancy (
    input  wire       clk,
    input  wire       i_ce,          // global enable / idle when low
    input  wire       start,         // master wants a new transaction
    input  wire       dev_ack_ready, // device is ready to raise ack
    output reg        req,
    output reg        ack,
    output reg        busy,
    output reg [2:0]  occ,           // outstanding-transaction occupancy
output reg        armed,
output reg [3:0]  ce_ticks
);
    // four-phase handshake sequencer:
    //   phase 0 : idle        (req=0, ack=0)
    //   phase 1 : req raised  (req=1, ack=0)
    //   phase 2 : ack raised  (req=1, ack=1)
    //   phase 3 : req dropped (req=0, ack=1)   -> ack drops, back to idle
    reg [1:0] phase;
    reg       pv;
reg [2:0] occ_pend;   // issued, not yet acknowledged
reg [3:0] ce_ticks_d;

    initial begin
        phase = 2'd0;
        req   = 1'b0;
        ack   = 1'b0;
        busy  = 1'b0;
        occ   = 3'd0;
        armed = 1'b0;
        pv    = 1'b0;
occ_pend = 3'd0;
ce_ticks   = 4'd0;
ce_ticks_d = 4'd0;
    end

    always @(posedge clk)
        pv <= 1'b1;

always @(posedge clk) begin
    if (i_ce) begin
        ce_ticks_d <= ce_ticks;
        ce_ticks   <= ce_ticks + {3'd0, start} + 4'd1;
    end else begin
        ce_ticks   <= ce_ticks_d;
    end
end

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                2'd0: begin
                    // request may only be launched from idle
                    if (start) begin
                        req   <= 1'b1;
                        busy  <= 1'b1;      // busy mirrors the phase
occ_pend <= occ_pend + 3'd1;   // counted as pending until the device acks
                        phase <= 2'd1;
                    end
                end
                2'd1: begin
                    // req is held; it may not drop until ack rises
                    if (dev_ack_ready) begin
                        ack   <= 1'b1;
occ      <= occ + occ_pend;    // pending transfer is now accepted
occ_pend <= 3'd0;
                        phase <= 2'd2;
                    end
                end
                2'd2: begin
                    // ack seen -> now req is allowed to drop
                    req   <= 1'b0;
                    phase <= 2'd3;
                end
                2'd3: begin
                    // ack drops, transaction retires
                    ack   <= 1'b0;
                    busy  <= 1'b0;
                    occ   <= occ - 3'd1;
                    armed <= 1'b1;   // sticky: first completed handshake arms
                    phase <= 2'd0;
                end
            endcase
        end
    end

    // Property: once at least one handshake has completed (armed), every time the
    // busy flag rises the occupancy must not exceed two.
    always @(posedge clk)
        if (pv && armed && $rose(busy))
            assert (occ <= 3'd2);
endmodule

// Tile-render pixel pipeline pacing: a /5 phase counter feeding a /4 row
// counter, plus an accumulator of paced cycles within one tile (20 steps)
// and a high-water mark of that accumulator.
module tilepipe_div (
    input  wire i_clk,
    input  wire i_ce,        // pipeline advance / idle when low
    output wire o_tile_en,   // divided-enable pulse: fires when the chain wraps
    output wire [4:0] o_peak
);
    // ---- phase counter (divide by 5) ----
    reg [2:0] phase;
    initial   phase = 3'd0;

    // ---- row counter (divide by 4 of the phase wrap) ----
    reg [1:0] row;
    initial   row = 2'd0;

    // ---- accumulated paced cycles inside the current tile ----
    reg [4:0] total;
    initial   total = 5'd0;

   // ---- paced cycles already retired from the tile's first half ----
   reg [4:0] retired;
   initial   retired = 5'd0;

    // ---- high-water mark of the accumulator (monotone) ----
    reg [4:0] peak;
    initial   peak = 5'd0;

  // ---- staged tile-sum ----
  // the accumulator add and the high-water compare no longer fit in one
  // paced cycle, so the sum is registered here and offered to the
  // comparator on the following paced cycle
  reg [4:0] sum_q;
  initial   sum_q = 5'd0;

    reg pv;
    initial pv = 1'b0;

    wire ph_wrap  = (phase == 3'd4);
    wire row_wrap = ph_wrap && (row == 2'd3);

   // the tile is flushed in halves: when row 1 finishes, the low
   // accumulator is folded into the retired count and restarted, so the
   // low accumulator only ever spans one half-tile
   wire half_done = ph_wrap && (row == 2'd1);

   // paced cycles in this tile after the current step, across both halves;
   // cleared only by the divided-enable pulse, never by its own value
   wire [4:0] nxt_sum = row_wrap ? 5'd0 : (retired + total + 5'd1);

    always @(posedge i_clk) begin
        pv <= 1'b1;
        if (i_ce) begin
            phase <= ph_wrap ? 3'd0 : (phase + 3'd1);
            if (ph_wrap)
                row <= row_wrap ? 2'd0 : (row + 2'd1);
           if (row_wrap) begin
               total   <= 5'd0;
               retired <= 5'd0;
           end else if (half_done) begin
               total   <= 5'd0;
               retired <= retired + total + 5'd1;
           end else begin
               total   <= total + 5'd1;
           end
          sum_q <= nxt_sum;
          if (sum_q > peak)
              peak <= sum_q;
        end
    end

    assign o_tile_en = i_ce && row_wrap;
    assign o_peak    = peak;

    // P: the high-water mark of the tile accumulator never climbs past 19,
    // even though the register is 5 bits wide (would allow 31): once it has
    // reached 19 it must never change again.
    always @(posedge i_clk)
        if (pv && ($past(peak) == 5'd19))
            assert ($stable(peak));
endmodule

module boot_chunk_loader (
    input  wire i_clk,
    input  wire i_ce,      // idle when low: no state changes at all
    input  wire i_start,   // accept a fresh load request
    output wire o_expired,
    output wire o_done,
    output wire [7:0] o_total
);
    // A chunk loader that accumulates 3 bytes of payload per accepted step.
    // The accumulator is kept in two carry-save halves (acc_a, acc_b) whose
    // sum is the true byte total; `total` is the redundant true running sum.
localparam [3:0] TMAX  = 4'd9;   // countdown granted: 8 steps + 1 commit-stage cycle
    localparam [7:0] LIMIT = 8'd24;  // bytes that constitute completion
   localparam [3:0] TBMAX = 4'd6;   // channel B: shorter descriptor fetch

    reg [7:0] acc_a;
    reg [7:0] acc_b;
    reg [7:0] total;
    reg [3:0] timer;
   reg [3:0] timer_b;  // channel B countdown
   reg [3:0] aux;      // channel B byte accumulator
   reg       arb;      // round-robin priority for the shared commit register
reg       st_v;    // a step is sitting in the commit register
reg [3:0] st_lo;   // its low carry-save half-increment
reg [3:0] st_hi;   // its high carry-save half-increment
   reg       st_ch;   // which channel owns the in-flight step
    reg       pv;

    initial acc_a = 8'd0;
    initial acc_b = 8'd0;
    initial total = 8'd0;
    initial timer = TMAX;
   initial timer_b = TBMAX;
   initial aux = 4'd0;
   initial arb = 1'b0;
initial st_v  = 1'b0;
initial st_lo = 4'd0;
initial st_hi = 4'd0;
   initial st_ch = 1'b0;
    initial pv    = 1'b0;

    wire [7:0] csum    = acc_a + acc_b;   // halves recombined
    wire       expired = (timer == 4'd0);
   wire       req_a   = (timer   != 4'd0);
   wire       req_b   = (timer_b != 4'd0);
   wire       gnt_b   = req_b && (arb || !req_a);  // B takes the slot on its turn
   wire       gnt_a   = req_a && !gnt_b;

    assign o_expired = expired;
    assign o_done    = (csum >= LIMIT);
   assign o_total   = total + {4'd0, aux};   // bytes from both channels

    always @(posedge i_clk)
        pv <= 1'b1;

    always @(posedge i_clk) begin
        if (i_ce) begin
            if (i_start) begin
                acc_a <= 8'd0;
                acc_b <= 8'd0;
                total <= 8'd0;
                timer <= TMAX;
               timer_b <= TBMAX;
               aux   <= 4'd0;
               arb   <= 1'b0;
st_v  <= 1'b0;          // flush whatever was in flight
st_lo <= 4'd0;
st_hi <= 4'd0;
               st_ch <= 1'b0;
end else begin
   // stage 1: arbitrate the single commit register between the two channels
   if (gnt_a) begin
       st_v  <= 1'b1;
       st_ch <= 1'b0;
       st_lo <= 4'd1;
       st_hi <= 4'd2;
       timer <= timer - 4'd1;
       arb   <= 1'b1;
   end else if (gnt_b) begin
       st_v  <= 1'b1;
       st_ch <= 1'b1;
       st_lo <= 4'd1;
       st_hi <= 4'd0;          // B carries a single byte per step
       timer_b <= timer_b - 4'd1;
       arb   <= 1'b0;
   end else begin
       st_v  <= 1'b0;
       st_ch <= 1'b0;
       st_lo <= 4'd0;
       st_hi <= 4'd0;
   end
   // stage 2: commit the step issued last cycle to its own channel
   if (st_v && !st_ch) begin
       acc_a <= acc_a + {4'd0, st_lo};                  // low carry-save half
       acc_b <= acc_b + {4'd0, st_hi};                  // high carry-save half
       total <= total + {4'd0, st_lo} + {4'd0, st_hi};  // true total
   end else if (st_v && st_ch) begin
       aux   <= aux + st_lo;
   end
            end
        end
    end

    // Bounded response, safety form: the countdown must never expire while the
    // load request is still outstanding.  Edge form: the cycle `expired` rises,
    // the recombined accumulator must already show a completed transfer.
    always @(posedge i_clk)
        if (pv)
            assert (!$rose(expired) || (acc_a + acc_b >= LIMIT));
endmodule

module elastic_two_entry (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_push,
    input  wire       i_pop,
    input  wire [7:0] i_data,
    output wire       o_valid,
    output wire       o_full,
    output wire [7:0] o_data,
    output wire [2:0] o_count
);

    // ---- two-entry elastic buffer -------------------------------------
    // one valid flag per slot, plus head/tail slot selectors.
    reg        v0, v1;      // slot occupancy flags
    reg        head, tail;  // which slot is read / written next
    reg [7:0]  d0, d1;      // slot payloads
    reg [2:0]  count;       // redundant occupancy counter
   reg [2:0]  credits;     // free slots left, advertised upstream

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial head  = 1'b0;
    initial tail  = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;
   initial credits = 3'd2;

// status: valid/data come from the FLAGS, full comes from the credit count
assign o_full  = (credits == 3'd0);
    assign o_valid = v0 || v1;
    assign o_data  = head ? d1 : d0;
    assign o_count = count;

    wire do_push = i_push && !o_full;
    wire do_pop  = i_pop  &&  o_valid;

    // idle condition: i_push == 0 && i_pop == 0 leaves all state alone
    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            head  <= 1'b0;
            tail  <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
credits <= 3'd2;
        end else begin
            if (do_push) begin
                if (tail == 1'b0) begin
                    v0 <= 1'b1;
                    d0 <= i_data;
                end else begin
                    v1 <= 1'b1;
                    d1 <= i_data;
                end
                tail <= ~tail;
            end

            if (do_pop) begin
                if (head == 1'b0)
                    v0 <= 1'b0;
                else
                    v1 <= 1'b0;
                head <= ~head;
            end

            count <= count + (do_push ? 3'd1 : 3'd0)
                            - (do_pop  ? 3'd1 : 3'd0);

           credits <= credits - (do_push ? 3'd1 : 3'd0)
                             + (do_pop  ? 3'd1 : 3'd0);
        end
    end

    // ---- property: while the buffer holds anything, the occupancy
    //      counter never exceeds the two-entry depth (the register is
    //      three bits wide, so 3..7 are representable).
    always @(posedge i_clk)
        if (o_valid)
            assert (count <= 3'd2);

   // ---- property: a lone resident word sits between the two pointers
   //      (head and tail must differ) and leaves exactly one credit.
   always @(posedge i_clk)
       if (count == 3'd1)
           assert ((head != tail) && (credits == 3'd1));

endmodule

module lfsr_token_arbiter (
    input  wire clk,
    input  wire ce,
    output wire o_gnt_a,
    output wire o_gnt_b,
    output wire o_full,
output wire o_empty,
output reg [3:0] o_heartbeat
);
    // maximal-length 4-bit LFSR (x^4 + x^3 + 1): cycles through all 15
    // nonzero states, so the all-zeros lockup state is never entered.
    reg [3:0] lfsr;
    reg       gnt_a, gnt_b;
    reg [2:0] credit, used;
    reg       f_full, f_empty;
    reg       armed;
reg [3:0] beat_acc;

    initial begin
        lfsr    = 4'h1;
        gnt_a   = 1'b0;
        gnt_b   = 1'b0;
        credit  = 3'd4;
        used    = 3'd0;
        f_full  = 1'b0;
        f_empty = 1'b1;
        armed   = 1'b0;
beat_acc    = 4'd0;
o_heartbeat = 4'd0;
    end

    wire       fb   = lfsr[3] ^ lfsr[2];
    wire [3:0] nxt  = {lfsr[2:0], fb};
    wire       lock = (lfsr == 4'd0);

    // token movement between the two credit pools, steered by the LFSR
    wire take_a = lfsr[0]  && (credit != 3'd0);
    wire give_b = !lfsr[0] && (used   != 3'd0);

    wire [2:0] nc = take_a ? (credit - 3'd1) : (give_b ? (credit + 3'd1) : credit);
    wire [2:0] nu = take_a ? (used   + 3'd1) : (give_b ? (used   - 3'd1) : used);

    always @(posedge clk) begin
        if (ce) begin
            lfsr <= nxt;

            // grant decode: in the lockup state the decode degenerates and
            // asserts both grants at once
            gnt_a <= lock ? 1'b1 : nxt[0];
            gnt_b <= lock ? 1'b1 : !nxt[0];

            credit <= nc;
            used   <= nu;

            f_full  <= (nc == 3'd0);
            f_empty <= (nu == 3'd0);

            if (lfsr == 4'hF)
                armed <= 1'b1;
beat_acc    <= beat_acc + {3'd0, lfsr[1]};
o_heartbeat <= beat_acc ^ {gnt_b, credit};
        end
    end

    assign o_gnt_a = gnt_a;
    assign o_gnt_b = gnt_b;
    assign o_full  = f_full;
    assign o_empty = f_empty;

    // P1: two grants are never asserted together, once the arbiter has been armed
    always @(posedge clk)
        if (armed)
            assert (!(gnt_a && gnt_b));

    // P2: the full and empty flags are never asserted together, once armed
    always @(posedge clk)
        if (armed)
            assert (!(f_full && f_empty));
endmodule

module lfsr_grant_arb (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    output reg  [1:0] gnt,
    output wire [4:0] o_state
);
    // Maximal-length 5-bit Galois-style shift register, x^5 + x^3 + 1.
    // Seeded nonzero, so the all-zeros lockup state is unreachable.
   // Power split: the low three bits run at the full rate, the top two bits
   // live in a half-rate register that is reloaded only every second enabled
   // cycle.  carry_q stages the bit that has already left the low segment but
   // has not been written into the top segment yet, and phase says which half
   // of the two-cycle update is in progress, so the tap is picked accordingly.
   reg [2:0] lfsr;
   reg [1:0] lfsr_hi;
   reg       carry_q;
   reg       phase;

   initial lfsr    = 3'h1;
   initial lfsr_hi = 2'b00;
   initial carry_q = 1'b0;
   initial phase   = 1'b0;
    initial gnt  = 2'b01;

   // Reassemble the polynomial word from the two segments.
   wire [1:0] top   = phase ? {lfsr_hi[0], carry_q} : lfsr_hi;
   wire [4:0] state = {top, lfsr};

   wire       fb  = top[1] ^ lfsr[2];
   wire [2:0] nxt = {lfsr[1:0], fb};

    // Pseudo-random round-robin: the low bit of the shift register picks
    // which of the two requesters is granted next cycle.  The all-zeros
    // lockup pattern decodes to the illegal "both owners" encoding.
   wire [1:0] sel = (state == 5'd0) ? 2'b11 :
                     (lfsr[0]      ? 2'b01 : 2'b10);

    always @(posedge clk) begin
        if (rst) begin
           lfsr    <= 3'h1;
           lfsr_hi <= 2'b00;
           carry_q <= 1'b0;
           phase   <= 1'b0;
            gnt  <= 2'b01;
        end else if (i_ce) begin
           lfsr    <= nxt;
           carry_q <= lfsr[2];
           phase   <= ~phase;
           if (phase)
               lfsr_hi <= {carry_q, lfsr[2]};
            gnt  <= sel;
        end
    end

   assign o_state = state;

    // Absence: the two grants are never asserted together.
    always @(*)
        if (gnt[0])
            assert (!gnt[1]);
endmodule

module notebook_cell_arbiter (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire [7:0] i_req,
    output wire [2:0] o_idx,
output wire       o_valid,
output reg  [3:0] o_req_count
);
    // Stage 1: registered priority-encoder result
    reg [2:0] idx;
    reg       valid;
    // Stage 2: exported result (index only meaningful while valid2 is set)
    reg [2:0] idx2;
    reg       valid2;
    // Shadow register: sticky history of every cell that has ever requested
    reg [7:0] hist;
    // Sticky arm: set the first time any cell requests service
    reg       arm;

    initial idx    = 3'd0;
    initial valid  = 1'b0;
    initial idx2   = 3'd0;
    initial valid2 = 1'b0;
    initial hist   = 8'h00;
    initial arm    = 1'b0;
initial o_req_count = 4'd0;

    function [2:0] penc(input [7:0] r);
        begin
            if      (r[0]) penc = 3'd0;
            else if (r[1]) penc = 3'd1;
            else if (r[2]) penc = 3'd2;
            else if (r[3]) penc = 3'd3;
            else if (r[4]) penc = 3'd4;
            else if (r[5]) penc = 3'd5;
            else if (r[6]) penc = 3'd6;
            else if (r[7]) penc = 3'd7;
            else           penc = 3'd0;
        end
    endfunction

    always @(posedge clk) begin
        if (i_reset) begin
            idx    <= 3'd0;
            valid  <= 1'b0;
            idx2   <= 3'd0;
            valid2 <= 1'b0;
            hist   <= 8'h00;
            arm    <= 1'b0;
o_req_count <= 4'd0;
        end else if (i_ce) begin
            // stage 2 takes last cycle's encode
            idx2   <= idx;
            valid2 <= valid;
            // stage 1 encodes the current request vector
            idx    <= penc(i_req);
            valid  <= |i_req;
            // shadow history grows in the same cycle as the encode
            hist   <= hist | i_req;
o_req_count <= o_req_count + {3'd0, (|i_req)};
            if (|i_req)
                arm <= 1'b1;
        end
    end

    assign o_idx   = idx2;
    assign o_valid = valid2;

    // Precedence, after arm: a published index must name a cell that
    // requested service at some earlier time.
    always @(posedge clk)
        if (arm && valid2)
            assert (hist[idx2]);
endmodule

// Four-phase request/acknowledge handshake between a driver and a
// peripheral service unit, with separate idle and busy status flags.
module fourphase_handshake (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,        // global enable / idle condition
    input  wire start,       // driver wants to open a transaction
    input  wire slave_ack,   // peripheral raises acknowledge
    input  wire slave_drop,  // peripheral releases acknowledge
    output wire o_req,
    output wire o_ack,
    output wire o_idle,
    output wire o_busy
);
    // phase encoding:
    //   0 : IDLE      req=0 ack=0
    //   1 : REQ       req=1 ack=0
    //   2 : ACK       req=1 ack=1
    //   3 : DROP      req=0 ack=1   (req may only fall after ack has risen)
    reg [1:0] phase;
    reg       req_r;
    reg       ack_r;
    reg       idle_r;
    reg       busy_r;

   // service ledger: every acquire of the peripheral is logged against
   // its matching release so the unit can tell whether it still holds
   // the peripheral after a handshake closes.
   reg [3:0] n_acq;
   reg [3:0] n_rel;

   wire [3:0] outstanding    = n_acq - n_rel;
   wire       ledger_closing = (outstanding == 4'd1);

    initial begin
        phase  = 2'd0;
        req_r  = 1'b0;
        ack_r  = 1'b0;
        idle_r = 1'b1;
        busy_r = 1'b0;
       n_acq  = 4'd0;
       n_rel  = 4'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase  <= 2'd0;
            req_r  <= 1'b0;
            ack_r  <= 1'b0;
            idle_r <= 1'b1;
            busy_r <= 1'b0;
           n_acq  <= 4'd0;
           n_rel  <= 4'd0;
        end else if (i_ce) begin
            case (phase)
                2'd0: begin
                    // leave idle only by raising req; idle flag drops here
if (start && outstanding == 4'd0) begin
                        phase  <= 2'd1;
                        req_r  <= 1'b1;
                        idle_r <= 1'b0;
                    end
                end
                2'd1: begin
                    // peripheral acknowledges; service becomes busy
                    if (slave_ack) begin
                        phase  <= 2'd2;
                        ack_r  <= 1'b1;
                        busy_r <= 1'b1;
                       n_acq  <= n_acq + 4'd1;
                    end
                end
                2'd2: begin
                    // req is allowed to fall now that ack is high
                    phase <= 2'd3;
                    req_r <= 1'b0;
                end
                default: begin
                    // peripheral releases ack, transaction closes
                    if (slave_drop) begin
                        phase  <= 2'd0;
                        ack_r  <= 1'b0;
                       busy_r <= !ledger_closing;
                       n_rel  <= n_rel + 4'd1;
                        idle_r <= 1'b1;
                    end
                end
            endcase
        end
    end

    assign o_req  = req_r;
    assign o_ack  = ack_r;
    assign o_idle = idle_r;
    assign o_busy = busy_r;

    // P: the service unit is never reported idle and busy at the same time.
    always @(*)
        assert (!(idle_r && busy_r));
endmodule

module pingpong_rotbuf (
    input  wire        clk,
    input  wire        step,      // enable / idle when low
    input  wire [15:0] din,
    input  wire [3:0]  amt,
    output reg  [15:0] dout,
    output wire        wr_half,
    output wire        rd_half
);
    // ------------------------------------------------------------------
    // one-cycle barrel rotator (staged shift-by-1/2/4/8 collapses to this)
    // ------------------------------------------------------------------
    wire [31:0] dbl = {din, din};
    wire [15:0] rot = dbl[15:0] >> amt | dbl[31:16] << (16 - amt);

    // ------------------------------------------------------------------
    // ping-pong double buffer: 2 halves of 4 words.
    // address = {half_select, index}
    // ------------------------------------------------------------------
    reg [2:0] waddr;
    reg [2:0] raddr;
    reg [15:0] mem [0:7];
    reg        pv;

   // registered write path: the rotate result and its destination slot are
   // captured on one enabled cycle and retired into the array on the next.
   reg [15:0] wdat_q;
   reg [2:0]  wadr_q;
   reg        wval_q;

   // per-port bank arbiter grant, raised one index ahead of the wrap so the
   // half-select mux is driven by a register instead of a comparator.
   reg        wsw_q;
   reg        rsw_q;

  // ------------------------------------------------------------------
  // scrub/refill channel: a second write channel that walks the half the
  // reader is draining and rewrites every word byte-swapped, sharing the
  // rotator and the single array write port with the main channel.
  // ------------------------------------------------------------------
  reg [1:0]  aidx;    // scrub word pointer inside its half
  reg        abank;   // half the scrubber is currently refilling
  reg        adone;   // pass complete, raised one slot ahead of the wrap
  reg [15:0] sdat_q;  // registered scrub write path, mirrors wdat_q/wadr_q
  reg [2:0]  sadr_q;
  reg        pgnt;    // scrubber owns the shared array port this slot

    integer i;
    initial begin
        waddr = 3'b000;   // writer starts in half 0
        raddr = 3'b100;   // reader starts in half 1
        dout  = 16'h0000;
        pv    = 1'b0;
       wdat_q = 16'h0000;
       wadr_q = 3'b000;
       wval_q = 1'b0;
       wsw_q  = 1'b0;
       rsw_q  = 1'b0;
      aidx   = 2'b00;
      abank  = 1'b1;
      adone  = 1'b0;
      sdat_q = 16'h0000;
      sadr_q = 3'b100;
      pgnt   = 1'b0;
        for (i = 0; i < 8; i = i + 1) mem[i] = 16'h0000;
    end

    assign wr_half = waddr[2];
    assign rd_half = raddr[2];

    // each side flips its own half when its own index field wraps
   // grant is requested one slot early and consumed on the wrap itself
   wire wgrant = (waddr[1:0] == 2'b10);
   wire rgrant = (raddr[1:0] == 2'b10);

  // the scrubber asks for the shared port on the last slot of its pass
  wire arq = (aidx == 2'b11);

    always @(posedge clk) begin
        pv <= 1'b1;
        if (step) begin
          pgnt <= arq && !pgnt;

          if (pgnt) begin
             // scrubber's slot: its word goes into the array and both main
             // channels pause for one beat
             mem[sadr_q] <= sdat_q;
          end else begin
           // stage 1: capture the rotated word and where it belongs
           wdat_q <= rot;
           wadr_q <= waddr;
           wval_q <= 1'b1;

           // stage 2: retire the word captured on the previous enabled cycle
           if (wval_q) mem[wadr_q] <= wdat_q;

           wsw_q <= wgrant;
           rsw_q <= rgrant;

            dout       <= mem[raddr];

           waddr <= {wsw_q ? ~waddr[2] : waddr[2], waddr[1:0] + 2'b01};
             // the reader may not cross into a half the scrubber has not
             // finished refilling, so its bank flip is qualified by adone
             raddr <= {(rsw_q && adone) ? ~raddr[2] : raddr[2],
                       raddr[1:0] + 2'b01};

             // scrub bookkeeping: stage the next refill word, walk the
             // pointer and follow the reader into the next half
             sdat_q <= {rot[7:0], rot[15:8]};
             sadr_q <= {abank, aidx};
             adone  <= (aidx == 2'b10);
             aidx   <= aidx + 2'b01;
             abank  <= adone ? ~abank : abank;
          end
        end
    end

    // ------------------------------------------------------------------
    // P: whenever the writer migrates up into the high half, the reader
    //     must at that moment be sitting in the low half.
    // ------------------------------------------------------------------
    always @(posedge clk)
        if (pv && $rose(waddr[2]))
            assert (raddr[2] == 1'b0);
endmodule

module npu_psum_lane (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,      // lane enable / idle when low
    input  wire        i_req,     // new accumulation request
    input  wire [7:0]  i_a,
    input  wire [7:0]  i_b,
    output reg  [19:0] o_psum,
    output reg         o_done
);
    // a full psum accumulation takes exactly MAX MAC steps
    localparam [3:0] MAX = 4'd12;

    // saturating up-counter: clamps at 12 although 4 bits admit 15
    reg [3:0] acc_cnt = 4'd0;
    // countdown that guarantees completion of an accepted request
    reg [4:0] ttl     = 5'd0;
    reg       busy    = 1'b0;
   // pipelined multiplier: the product of a MAC step is retimed through
   // four stages before it lands in the psum accumulator
   reg        mac_v1 = 1'b0;
   reg        mac_v2 = 1'b0;
   reg        mac_v3 = 1'b0;
   reg        mac_v4 = 1'b0;
   reg [15:0] mac_p1 = 16'd0;
   reg [15:0] mac_p2 = 16'd0;
   reg [15:0] mac_p3 = 16'd0;
   reg [15:0] mac_p4 = 16'd0;
   // one MAC step is issued per enabled busy cycle until the step count saturates
   wire       mac_issue = busy && (acc_cnt != MAX);

    initial o_psum = 20'd0;
    initial o_done = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            acc_cnt <= 4'd0;
            ttl     <= 5'd0;
            busy    <= 1'b0;
            o_psum  <= 20'd0;
            o_done  <= 1'b0;
           mac_v1  <= 1'b0;
           mac_v2  <= 1'b0;
           mac_v3  <= 1'b0;
           mac_v4  <= 1'b0;
           mac_p1  <= 16'd0;
           mac_p2  <= 16'd0;
           mac_p3  <= 16'd0;
           mac_p4  <= 16'd0;
        end else if (i_ce) begin
            o_done <= 1'b0;
           // MAC pipeline advances on every enabled cycle
           mac_p1 <= i_a * i_b;
           mac_v1 <= mac_issue;
           mac_p2 <= mac_p1;
           mac_v2 <= mac_v1;
           mac_p3 <= mac_p2;
           mac_v3 <= mac_v2;
           mac_p4 <= mac_p3;
           mac_v4 <= mac_v3;
           if (mac_v4) begin
               o_psum <= o_psum + mac_p4;
           end
            if (!busy) begin
                if (i_req) begin
                    busy    <= 1'b1;
                    acc_cnt <= 4'd0;
                   ttl     <= 5'd17;   // MAX + pipe depth + 1 cycles of slack
                    o_psum  <= 20'd0;
                end
            end else begin
                acc_cnt <= (acc_cnt == MAX) ? MAX : acc_cnt + 4'd1;
                ttl     <= ttl - 5'd1;
               // retire only once the last issued step has drained out of the pipe
               if ((acc_cnt == MAX) && !mac_v1 && !mac_v2 && !mac_v3) begin
                    busy   <= 1'b0;
                    o_done <= 1'b1;
                end
            end
        end
    end

    // Bounded response, safety form: the completion countdown must never
    // expire while an accepted accumulation request is still outstanding.
    assert property (!busy || ttl != 5'd0);

endmodule

module rr_arb_shadow (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [3:0] req,
    input  wire       arm,
    input  wire       clr,
    output reg  [3:0] gnt
);
    // round-robin arbiter state
    reg [1:0] ptr;       // last granted line index
   reg [1:0] hold;      // line the parked grant is sitting on
   reg [3:0] n_iss;     // grants issued  (free-running, wraps)
   reg [3:0] n_ret;     // grants retired (free-running, wraps)
    // precedence shadow of the previous grant decision
    reg [3:0] prev_gnt;
    reg [1:0] prev_ptr;
    reg [3:0] hist;      // lines the pointer has rested on since arming
    reg       armed;     // window register: set by arm, cleared by clr
   reg [3:0] n_arm;     // observation windows opened (free-running, wraps)
   reg [3:0] n_clr;     // observation windows closed (free-running, wraps)

    initial begin
        gnt      = 4'b0000;
        ptr      = 2'd0;
        prev_gnt = 4'b0000;
        prev_ptr = 2'd0;
        hist     = 4'b0000;
        armed    = 1'b0;
       hold     = 2'd0;
       n_iss    = 4'd0;
       n_ret    = 4'd0;
      n_arm    = 4'd0;
      n_clr    = 4'd0;
    end

    // rotating priority: start just past the last grant
    wire [1:0] c0 = ptr + 2'd1;
    wire [1:0] c1 = ptr + 2'd2;
    wire [1:0] c2 = ptr + 2'd3;
    wire [1:0] c3 = ptr;

    reg       sel_val;
    reg [1:0] sel_idx;
    always @(*) begin
        if (req[c0])      begin sel_val = 1'b1; sel_idx = c0;   end
        else if (req[c1]) begin sel_val = 1'b1; sel_idx = c1;   end
        else if (req[c2]) begin sel_val = 1'b1; sel_idx = c2;   end
        else if (req[c3]) begin sel_val = 1'b1; sel_idx = c3;   end
        else              begin sel_val = 1'b0; sel_idx = 2'd0; end
    end

    // one-hot (or all-zero) next grant, never on a non-requesting line
    wire [3:0] nxt = sel_val ? (4'b0001 << sel_idx) : 4'b0000;

   // a grant is parked on its line until that line drops its request; the
   // issue/retire ledger is what tells the arbiter it may re-arbitrate
   wire outstanding = (n_iss != n_ret);
   wire issue       = ce && !outstanding && sel_val;
   wire retire      = ce &&  outstanding && !req[hold];

  // the arm/clr handshake is logged the same way, and the window ledger --
  // not the flag -- decides whether a fresh window may be opened or closed
  wire win_open = (n_arm != n_clr);
  wire do_open  = arm && !win_open;
  wire do_close = clr &&  win_open;

    always @(posedge clk) begin
        if (rst) begin
            gnt      <= 4'b0000;
            ptr      <= 2'd0;
            prev_gnt <= 4'b0000;
            prev_ptr <= 2'd0;
            hist     <= 4'b0000;
            armed    <= 1'b0;
           hold     <= 2'd0;
           n_iss    <= 4'd0;
           n_ret    <= 4'd0;
          n_arm    <= 4'd0;
          n_clr    <= 4'd0;
        end else begin
            if (ce) begin
               if (outstanding) begin
                   gnt <= req[hold] ? (4'b0001 << hold) : 4'b0000;
               end else begin
                   gnt <= nxt;
                   if (sel_val) begin
                       ptr  <= sel_idx;
                       hold <= sel_idx;
                   end
               end
                prev_gnt <= gnt;
                prev_ptr <= ptr;
               // a line only counts as rested-on while it holds a grant
              // and only while a window is open to record it
              if (win_open && outstanding) hist <= hist | (4'b0001 << ptr);
            end
           n_iss <= n_iss + {3'd0, issue};
           n_ret <= n_ret + {3'd0, retire};
          n_arm <= n_arm + {3'd0, do_open};
          n_clr <= n_clr + {3'd0, do_close};
            // opening the observation window restarts the shadow record
           if (do_open) begin
                armed    <= 1'b1;
                prev_gnt <= 4'b0000;
                prev_ptr <= 2'd0;
                hist     <= 4'b0000;
           end else if (do_close) begin
                armed <= 1'b0;
            end
        end
    end

    // after arm, until clr (which may never come): a recorded grant must have
    // been preceded by the pointer standing on that very line
    always @(posedge clk) begin
        if (armed)
            assert (prev_gnt == 4'b0000 || prev_gnt == (4'b0001 << prev_ptr));
        if (armed)
            assert (prev_gnt == 4'b0000 || (hist & prev_gnt) != 4'b0000);
    end
endmodule

module parity_slice_occ (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_data,
    output reg        o_valid,
    output reg  [7:0] o_data,
    output reg        o_retry
);
    // two-deep register slice, each stage protected by a parity bit
    reg [7:0] d0, d1;
    reg       p0, p1;
   // per-nibble parity: p0/p1 cover bits [3:0] and the h companions bits [7:4],
   // so a reported mismatch localises the fault to one half-word
   reg       p0h, p1h;
    reg       v0, v1;

    // occupancy accounting: one 3-bit counter tracking live stages
    reg [2:0] occ;

   // egress check: the word presented on the output register keeps its slice
   // slot for one more cycle while its parity is re-checked, so the credit is
   // returned one cycle after the word leaves
   reg       oq_busy;
   reg       oq_par;
  reg       oq_parh;
// egress lane tag: the word parked in the egress re-check slot keeps its
// credit in the counter of the lane that owns it, so the data lane and the
// echo lane are metered independently instead of swapping credits
reg       eg_sb;
reg [2:0] eg_occ;

  // sideband echo lane: a control word tagged with bit 6 is parked here and
  // replayed onto the output whenever the data lane's second stage is empty.
  // It draws its slot from the same occupancy pool as the data lane.
  reg [7:0] sb_d;
  reg       sb_p;
 reg       sb_ph;
  reg       sb_v;
 // the echo lane leases its slot on a dedicated credit counter, so a parked
 // control word does not disturb the data-lane accounting; the credit is
// handed to the egress counter eg_occ when the parked word takes the slot
 reg [2:0] sb_occ;

   // programmable slot limit (one or two stages), written by a control word
   reg [2:0] lim;

  // replay bookkeeping: every parity mismatch books one replay slot, and a
  // booked slot is handed back when the egress re-check frees a credit
  reg [2:0] rpy;

    initial begin
        d0 = 8'h00; d1 = 8'h00;
        p0 = 1'b0;  p1 = 1'b0;
       p0h = 1'b0; p1h = 1'b0;
        v0 = 1'b0;  v1 = 1'b0;
        occ = 3'd0;
       oq_busy = 1'b0;
       oq_par  = 1'b0;
      oq_parh = 1'b0;
      eg_sb   = 1'b0;
      eg_occ  = 3'd0;
       sb_d = 8'h00; sb_p = 1'b0; sb_v = 1'b0;
      sb_ph = 1'b0;
     sb_occ  = 3'd0;
       lim     = 3'd2;
      rpy     = 3'd0;
        o_valid = 1'b0;
        o_data  = 8'h00;
        o_retry = 1'b0;
    end

    // stored parity is checked against stored data every cycle
   wire mism0 = v0 && ((p0 != (^d0[3:0])) || (p0h != (^d0[7:4])));
   wire mism1 = v1 && ((p1 != (^d1[3:0])) || (p1h != (^d1[7:4])));
wire mismsb = sb_v && ((sb_p != (^sb_d[3:0])) || (sb_ph != (^sb_d[7:4])));
wire retry  = mism0 || mism1 || mismsb;

   // the slot is only released when the egress parity re-check is clean
  wire oq_bad = oq_busy && ((oq_par != (^o_data[3:0])) || (oq_parh != (^o_data[7:4])));
   wire rel    = oq_busy && !oq_bad;

   // control words carry the depth limit instead of payload
   wire cfg  = i_valid && i_data[7];
// both lanes draw from the same physical pool, so all three credit counters
// are summed before the depth limit is applied
wire [4:0] pool = {2'b0, occ} + {2'b0, sb_occ} + {2'b0, eg_occ};
wire room = pool < {2'b0, lim};
   wire acc  = i_valid && !cfg && room;
   wire nack = i_valid && !cfg && !room;
  // echo lane arbitration: the parked word only reaches the egress slot when
  // the data lane's second stage is empty, so the lanes never collide
  wire echo    = cfg && i_data[6];
  wire sb_acc  = echo && !sb_v && room;
  wire sb_nack = echo && (sb_v || !room);
  wire sb_go   = sb_v && !v1;

    always @(posedge clk) begin
        if (i_ce) begin
o_retry <= retry || nack || sb_nack || oq_bad || (rpy != 3'd0);
            if (retry) begin
                // corrupted stage: freeze the slice and book a replay slot
                occ <= occ + 3'd1;
               rpy <= rpy + 3'd1;
            end else begin
                // normal shift: stage0 -> stage1 -> output
                d1 <= d0;
                p1 <= p0;
               p1h <= p0h;
                v1 <= v0;
                d0 <= i_data;
               p0  <= ^i_data[3:0];
               p0h <= ^i_data[7:4];
               v0 <= acc;
oq_busy <= v1 || sb_go;
oq_par  <= v1 ? p1 : sb_p;
oq_parh <= v1 ? p1h : sb_ph;
eg_sb   <= !v1 && sb_go;
sb_v <= sb_acc || (sb_v && !sb_go);
if (sb_acc) begin
    sb_d <= i_data;
   sb_p  <= ^i_data[3:0];
   sb_ph <= ^i_data[7:4];
end
if (cfg && !echo) lim <= i_data[0] ? 3'd2 : 3'd1;
occ    <= occ + (acc ? 3'd1 : 3'd0) - ((rel && !eg_sb) ? 3'd1 : 3'd0);
eg_occ <= eg_occ + (sb_go ? 3'd1 : 3'd0) - ((rel && eg_sb) ? 3'd1 : 3'd0);
sb_occ <= sb_occ + (sb_acc ? 3'd1 : 3'd0) - (sb_go ? 3'd1 : 3'd0);
              if (rel && rpy != 3'd0) rpy <= rpy - 3'd1;
o_valid <= v1 || sb_go;
o_data  <= v1 ? d1 : sb_d;
            end
        end
    end

    // bounded existence: the slice is two deep, so occupancy never exceeds 2
    always @(*) assert (occ <= 3'd2);

   // a replay slot is only booked on a real corruption, so booked slots plus
   // live slice slots never oversubscribe the two-deep slice
   always @(posedge clk)
       assert ({1'b0, occ} + {1'b0, rpy} <= 4'd2);
endmodule

module disasm_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       kick,      // an instruction was successfully decoded
    output reg  [3:0] count,     // cycles since last kick
    output reg        expired,   // decoder hung: limit was reached
    output reg        healthy    // plenty of slack left
);
    localparam [3:0] LIMIT = 4'd10;   // timeout
    localparam [3:0] WARN  = 4'd8;    // slack threshold

   // saved context of the decode channel that is parked while the other
   // one owns the shared pipeline slot
   reg  [3:0] count_sh;
   reg        exp_sh;
  // second parked context: three decode channels rotate through the one
  // pipeline slot, so two of them are always parked at any time
  reg  [3:0] count_sh2;
  reg        exp_sh2;
 // remaining slack of the channel that currently owns the slot; the
 // timeout now fires on a zero-detect of this countdown instead of a
 // magnitude compare, and it is reloaded whenever the slot changes hands
 reg  [3:0] deadline;
// the decode channel hands its shared operand port to the issue stage for
// one pipeline advance on every successful decode; the port comes back on
// the following advance.  both sides of the loan are logged so the loan
// traffic can be watched from the outside, and the level flag is the
// registered "port is out" condition used by the slack report.
reg  [3:0] n_lend;    // hand-overs to the issue stage (wraps)
reg  [3:0] n_back;    // returns from the issue stage (wraps)
reg        port_out;  // the operand port is out on loan right now
// the issue stage hands the operand port back together with the result of
// the decoded instruction; that result is parked in the one-entry commit
// slot until the commit stage accepts it on the following advance.  both
// sides of the parking are logged so commit traffic is visible outside.
reg  [3:0] n_post;   // results parked in the commit slot (wraps)
reg  [3:0] n_pop;    // results accepted by the commit stage (wraps)
reg        rb_full;  // a result is parked in the commit slot right now
// the commit stage accepts one result per pipeline advance, so the parked
// result is shifted out of the slot into the commit-stage register and only
// retires into the pop ledger on the following advance
reg        cmt_q;   // a result is in the commit stage register right now

    initial begin
        count   = 4'd0;
        expired = 1'b0;
        healthy = 1'b1;
       count_sh = 4'd0;
       exp_sh   = 1'b0;
      count_sh2 = 4'd0;
      exp_sh2   = 1'b0;
     deadline  = LIMIT;
n_lend    = 4'd0;
n_back    = 4'd0;
port_out  = 1'b0;
n_post    = 4'd0;
n_pop     = 4'd0;
rb_full   = 1'b0;
cmt_q     = 1'b0;
    end

    // next value of the stall counter: kick clears it, otherwise it
    // counts up and saturates at the timeout limit
    wire [3:0] nxt = kick              ? 4'd0  :
                     (count == LIMIT)  ? LIMIT :
                                         count + 4'd1;

   // the slot is handed to the other channel when the active one makes
   // progress, and is preempted once the active one has clearly hung
// a preemption is deferred while a result is still parked for commit,
// because rotating the slot would orphan the parked result
// the same applies while the result is still in the commit stage register
wire swap = kick || (count == LIMIT && !rb_full && !cmt_q);

  // the channel holding the slot has just run out of slack
  wire hung = !kick && (deadline <= 4'd1);

// a decode hands the port over unless it is already out; the return
// ledger chases the hand-over ledger, so the port comes back on the next
// advance after it was taken
wire       lend      = !port_out && kick;
wire       back      = (n_lend != n_back);
wire [3:0] n_lend_nx = n_lend + (lend ? 4'd1 : 4'd0);
wire [3:0] n_back_nx = n_back + (back ? 4'd1 : 4'd0);
wire       port_nx   = lend || (port_out && !back);
// the commit slot takes the result on the advance the port comes back and
// the commit stage drains it on the advance after that
wire       rb_take   = back;
// the slot always unloads into the commit stage register, which always
// retires, so the two stages are a plain shift and a fresh result can land
// behind the one that is leaving
wire       cmt_nx    = rb_full;   // slot -> commit stage register
wire       retire    = cmt_q;     // commit stage register -> pop ledger
wire       rb_nx     = rb_take;
wire [3:0] n_post_nx = n_post + (rb_take ? 4'd1 : 4'd0);
wire [3:0] n_pop_nx  = n_pop  + (retire ? 4'd1 : 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            count   <= 4'd0;
           count_sh <= 4'd0;
           exp_sh   <= 1'b0;
           count_sh2 <= 4'd0;
           exp_sh2   <= 1'b0;
          deadline  <= LIMIT;
n_lend    <= 4'd0;
n_back    <= 4'd0;
port_out  <= 1'b0;
n_post    <= 4'd0;
n_pop     <= 4'd0;
rb_full   <= 1'b0;
cmt_q     <= 1'b0;
            expired <= 1'b0;
            healthy <= 1'b1;
        end else if (i_ce) begin
           if (swap) begin
               count    <= count_sh;         // resume the parked channel
              deadline <= LIMIT - count_sh; // slack left for the resumed channel
count_sh  <= count_sh2;        // rotate the parked queue forward
count_sh2 <= nxt;              // park the current stall count
exp_sh    <= exp_sh2;          // its hang flag rotates with it
exp_sh2   <= hung;             // remember if it hung
           end else begin
               count    <= nxt;
              deadline <= (deadline == 4'd0) ? 4'd0 : deadline - 4'd1;
           end
// the loan ledgers are free running and wrap at four bits; nothing but
// the flag tracks how many loans are outstanding
if (lend) n_lend <= n_lend + 4'd1;
if (back) n_back <= n_back + 4'd1;
port_out <= port_nx;
// the commit ledgers are free running and wrap at four bits
n_post   <= n_post_nx;
n_pop    <= n_pop_nx;
rb_full  <= rb_nx;
cmt_q    <= cmt_nx;
           // sticky per channel: a kick only clears the channel that
           // currently owns the slot
// the hang detector reads the ledgers directly: a hand-over that is
// still unmatched means the issue stage never took the operands
// and a result that is still parked for commit stalls the channel too
expired <= hung || exp_sh || exp_sh2 || (n_lend_nx != n_back_nx) || rb_nx;
// the slack report is built from the registered port flag
healthy <= (nxt < WARN) && (count_sh < WARN) && (count_sh2 < WARN) && !port_nx
           && (n_post_nx == n_pop_nx);
        end
    end

    // P: the timeout flag and the slack flag are never raised together
    always @(posedge clk)
        if (expired)
            assert (!healthy);
endmodule

// Tracks outstanding memory requests issued into a 4-deep load/store pipeline.
// A shift register records which pipeline stages hold a live request; a separate
// counter tracks how many are in flight.
module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,   // pipeline advance / clock-enable
    input  wire       req,    // a new request is issued into stage 0
    output wire       f_idle, // no requests outstanding (from the counter)
    output wire       f_full, // all pipeline slots occupied (from the counter)
    output wire       f_any,  // some stage holds a request (from the shifter)
    output wire       f_slot  // some stage is free (from the shifter)
);

    reg [3:0] inflight;
    reg [2:0] cnt;
reg       ireq;                // port-side launch register (req -> issue)
reg [1:0] pend;                // requests held in the two launch registers
reg       issue;                // request launch register (input -> stage 0)
reg [1:0] bcnt;                 // back-half occupancy (stage 3 only)
reg       hand;                 // request in the stage1 -> stage2 handover
reg [3:0] n_in;                 // ledger: requests entering the shifter
reg [3:0] n_out;                // ledger: requests retired out of stage 3
reg [2:0] credit;                // free holding places left, 6 down to 0

    initial inflight = 4'b0000;
    initial cnt      = 3'd0;
initial ireq     = 1'b0;
initial pend     = 2'd0;
initial issue    = 1'b0;
initial bcnt     = 2'd0;
initial hand     = 1'b0;
initial n_in     = 4'd0;
initial n_out    = 4'd0;
initial credit   = 3'd6;

    // the request leaving the last stage completes this cycle
    wire retire = inflight[3];

// outstanding-request accounting.  The ledger counters are written when a
// request crosses into the shifter and when it retires, so their difference
// only covers the four pipeline stages; the requests still waiting in the
// launch registers are carried by the port's own credit counter.  The port
// sums the two parts and refuses a new request once every holding place is
// taken.
wire [3:0] depth  = n_in - n_out;
wire [3:0] total  = depth + {2'b00, pend};
wire       accept = req && (credit != 3'd0);

    always @(posedge clk) begin
        if (rst) begin
            inflight <= 4'b0000;
            cnt      <= 3'd0;
ireq     <= 1'b0;
pend     <= 2'd0;
issue    <= 1'b0;
bcnt     <= 2'd0;
hand     <= 1'b0;
n_in     <= 4'd0;
n_out    <= 4'd0;
credit   <= 3'd6;
        end else if (step) begin
// the request bus is double-registered at the pipeline input to cut
// the path from req into stage 0: an accepted request waits two
// advances in the launch registers before it occupies stage 0.  The
// front count picks it up on the second of those advances, and the
// port credit counter holds it until then.
ireq     <= accept;
issue    <= ireq;
inflight <= {inflight[2:0], issue};
// each pipeline half maintains its own occupancy count locally.  The
// stage1 -> stage2 crossing is registered to keep the adder chains
// short: the front count drops the request on the advance that moves
// it out of stage 1, the handover latch carries it, and the back
// count picks it up on the following advance.
cnt      <= cnt  + {2'b00, ireq}          - {2'b00, inflight[1]};
pend     <= pend + {1'b0,  accept}        - {1'b0,  issue};
bcnt     <= bcnt + {1'b0,  hand}          - {1'b0,  retire};
hand     <= inflight[1];
n_in     <= n_in  + {3'b000, issue};
n_out    <= n_out + {3'b000, retire};
// the accept path runs off a dedicated free-slot credit counter so the
// request qualifier does not have to wait for the ledger subtraction
// and the pend adder: one credit is spent when a request is taken in
// and returned when a request retires out of stage 3.
credit   <= credit - {2'b00, accept} + {2'b00, retire};
        end
    end

assign f_idle = (cnt == 3'd0) && (bcnt == 2'd0) && !hand && (pend == 2'd0);
// six holding places: the two launch registers plus the four stages.  The
// ledger difference plus the port credit is the authoritative count.
assign f_full = (total == 4'd6);
    assign f_any  = |inflight;
    assign f_slot = ~(&inflight);

    // P: the counter-derived flags and the shifter-derived flags may never
    // contradict each other -- idle together with an occupied stage, or
    // full together with a free stage.
    always @(posedge clk) assert (!(f_idle && f_any));
    always @(posedge clk) assert (!(f_full && f_slot));

   // Q: if the credit counter has handed out every slot, then every slot
   // really is occupied -- both launch registers and all four stages.
   always @(posedge clk)
       assert (!(credit == 3'd0) || (ireq && issue && !f_slot));

endmodule

// Histogram accumulator: four bin counters, one sample at a time,
// plus a running total-samples register and a shadow register that
// records the bin-0 count observed at the most recent bin-1 sample.
module histo_precedence (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire [1:0] i_bin,     // which bin the incoming sample lands in
    output wire [5:0] o_total,
output wire [3:0] o_snap,
output reg  [3:0] o_act
);
    // bin counters
    reg [3:0] b0, b1, b2, b3;
    // total samples accumulated
    reg [5:0] total;
    // shadow register: value of bin 0 at the time of the last bin-1 sample
    reg [3:0] snap;
   // snapshot delivery pipeline: the bin-0 population read out alongside a
   // bin-1 sample only reaches the shadow register four cycles later, which
   // matches the read latency of the bin storage array.
   reg [3:0] sn1, sn2, sn3, sn4;
   reg       v1, v2, v3, v4;
reg [3:0] ce_hist;
// snapshot defer buffer: a bin-1 sample that arrives while the readout
// pipeline is still busy parks its bin-0 reading here and replays it when
// the pipeline frees up, so back-to-back bin-1 samples are not lost
reg [3:0] hold;
reg       hold_v;
// snapshot ledger: requests issued vs. snapshots delivered to the shadow
reg [3:0] n_iss, n_ret;
// posted-write buffer for bin 0: the bin-0 counter shares its single array
// port with the snapshot readout, so bin-0 samples that are committed while
// the port is busy are parked here and written back on a free cycle
reg [1:0] b0_pend;
// bin-0 posted-write ledger: samples pushed into the posted-write buffer
// versus parked writes retired into the bin-0 counter
reg [3:0] n_p0, n_w0;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;
   initial sn1   = 4'd0;
   initial sn2   = 4'd0;
   initial sn3   = 4'd0;
   initial sn4   = 4'd0;
   initial v1    = 1'b0;
   initial v2    = 1'b0;
   initial v3    = 1'b0;
   initial v4    = 1'b0;
initial ce_hist = 4'd0;
initial o_act   = 4'd0;
initial hold    = 4'd0;
initial hold_v  = 1'b0;
initial n_iss   = 4'd0;
initial n_ret   = 4'd0;
initial b0_pend = 2'd0;
initial n_p0    = 4'd0;
initial n_w0    = 4'd0;

    // value currently held by the selected bin
    wire [3:0] sel_val = (i_bin == 2'd0) ? b0 :
                         (i_bin == 2'd1) ? b1 :
                         (i_bin == 2'd2) ? b2 : b3;

    // a sample is committed only if the selected bin has headroom
wire [3:0] inflight  = n_iss - n_ret;
wire       pipe_free = !(v1 | v2 | v3 | v4);
// the ledger can carry two outstanding snapshots (one in the readout
// pipeline, one in the defer buffer); a bin-1 sample that would overflow it
// is held off at the input until a slot frees up
wire       snap_full = (inflight == 4'd2);
// bin-0 population as seen by the outside world: committed count plus the
// samples still sitting in the posted-write buffer
// outstanding posted writes as tracked by the ledger, which is the count
// the array-port controller exports and uses for its readout arithmetic
wire [3:0] p0_out    = n_p0 - n_w0;
wire [4:0] b0_pop    = {1'b0, b0} + {1'b0, p0_out};
wire       bin0_full = (b0_pop == 5'd15) || (b0_pend == 2'd3);
wire incr = i_ce && !((i_bin == 2'd0) ? bin0_full : (sel_val == 4'd15))
                 && !((i_bin == 2'd1) && snap_full);
wire req  = incr && (i_bin == 2'd1);
// the array port is available for a posted bin-0 write-back only on cycles
// where the snapshot logic is not reading the bin-0 population
wire       wb_free = pipe_free && !hold_v && !req;
wire       b0_push = incr && (i_bin == 2'd0);
wire       b0_wb   = i_ce && wb_free && (b0_pend != 2'd0) && (b0 != 4'd15);

    always @(posedge clk) begin
if (b0_wb)
    b0 <= b0 + 4'd1;
if (i_ce)
    b0_pend <= b0_pend + {1'b0, b0_push} - {1'b0, b0_wb};
// ledger ticks: one per posted bin-0 write, one per write-back retired
if (i_ce) begin
    n_p0 <= n_p0 + {3'd0, b0_push};
    n_w0 <= n_w0 + {3'd0, b0_wb};
end
        if (incr) begin
            case (i_bin)
2'd0: ; // bin-0 sample is posted into b0_pend above
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
            endcase
            total <= total + 6'd1;
        end
    end
   // Snapshot pipeline: the read data shifts on every enabled cycle and the
   // valid bit travels with it, so the shadow register is loaded four cycles
   // after the bin-1 sample that requested the snapshot.
   always @(posedge clk) begin
       if (i_ce) begin
           sn2 <= sn1;
           v2  <= v1;
           sn3 <= sn2;
           v3  <= v2;
           sn4 <= sn3;
           v4  <= v3;
           if (v4)
               snap <= sn4;
          // stage-1 arbitration: a parked request replays ahead of a new
          // one so the shadow register sees bin-1 samples in order
          if (pipe_free && hold_v) begin
              sn1    <= hold;
              v1     <= 1'b1;
              hold_v <= req;
              if (req)
hold <= b0_pop[3:0];
          end else if (pipe_free && req) begin
sn1 <= b0_pop[3:0];
              v1  <= 1'b1;
          end else begin
              v1 <= 1'b0;
              if (req) begin
hold   <= b0_pop[3:0];
                  hold_v <= 1'b1;
              end
          end
          // ledger: one tick per request issued, one per snapshot delivered
          n_iss <= n_iss + {3'd0, req};
          n_ret <= n_ret + {3'd0, v4};
       end
   end

  // Activity monitor: a shift register of "sample landed in bin 3" flags,
// plus a status readout multiplexer: the current bin index selects which
// ledger / defer-buffer register is presented on o_act.
  always @(posedge clk) begin
      if (i_ce) begin
          ce_hist <= {ce_hist[2:0], (i_bin == 2'd3)};
// the bin-3 activity history bit pages the readout between the snapshot
// ledger and the bin-0 posted-write ledger
          case (i_bin)
2'd0: o_act <= ce_hist[3] ? n_p0 : n_iss;
2'd1: o_act <= ce_hist[3] ? n_w0 : n_ret;
2'd2: o_act <= ce_hist[3] ? {2'd0, b0_pend} : hold;
              2'd3: o_act <= {hold_v, ce_hist[2:0]};
          endcase
      end
  end

    assign o_total = total;
    assign o_snap  = snap;

    // Property (precedence): whenever a sample is being committed, the
    // bin-0 population recorded earlier in the shadow register must already
    // have been accounted for in the total-samples register.
    always @(posedge clk)
        if (incr)
            assert (total >= {2'b00, snap});

   // Property (snapshot ledger conservation): every outstanding snapshot
   // request corresponds to a bin-1 sample that has already been counted,
   // and the bin-0 reading parked in the defer buffer was taken from a
   // population already counted, so together they can never exceed the
   // running sample total.
   always @(posedge clk)
       assert (total >= {2'b00, hold} + {2'b00, inflight});
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
output reg  o_clean,
output reg [3:0] o_evt_cnt
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;
   localparam       CH_A = 1'b0;  // commit-stage owner encoding
   localparam       CH_B = 1'b1;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
reg       cmt_ch   = 1'b0;  // which channel owns the commit stage
reg       q_pend   = 1'b0;  // queued commit sitting behind the head slot
reg       q_val    = 1'b0;  // sample value waiting in the queued slot
reg       q_ch     = 1'b0;  // which channel owns the queued slot
reg       wb_pend  = 1'b0;  // writeback slot: entry retired by the head
reg       wb_val   = 1'b0;  // sample value being applied this step
reg       wb_ch    = 1'b0;  // which channel owns the writeback slot
reg       s1_pend  = 1'b0;  // retire pipe stage 1: entry just left the head
reg       s1_val   = 1'b0;  // sample value travelling in stage 1
reg       s1_ch    = 1'b0;  // channel owning stage 1
reg       s2_pend  = 1'b0;  // retire pipe stage 2
reg       s2_val   = 1'b0;  // sample value travelling in stage 2
reg       s2_ch    = 1'b0;  // channel owning stage 2
reg       s3_pend  = 1'b0;  // retire pipe stage 3
reg       s3_val   = 1'b0;  // sample value travelling in stage 3
reg       s3_ch    = 1'b0;  // channel owning stage 3
reg       s4_pend  = 1'b0;  // retire pipe stage 4: feeds the writeback slot
reg       s4_val   = 1'b0;  // sample value travelling in stage 4
reg       s4_ch    = 1'b0;  // channel owning stage 4
reg       samp_b   = 1'b0;  // last accepted arm-button sample
reg [2:0] cnt_b    = 3'd0;  // arm-button stability counter, saturates at K
reg       arm_clean = 1'b0; // debounced arm-button level
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid
   reg [3:0] evt_cnt  = 4'd0;  // distractor: counts disagreeing input steps

// Two commit slots were budgeted (a head that retires and one queued tail);
// the channels arbitrate for a free slot, the raw-sample channel wins a tie.
   wire a_chg   = (i_raw != samp);
   wire b_chg   = (i_arm != samp_b);
   wire a_req   = !a_chg && (cnt   == K - 3'd1);
   wire b_req   = !b_chg && (cnt_b == K - 3'd1);
wire q_full  = cmt_pend && q_pend;
wire grant_a = !q_full && a_req;
wire grant_b = !q_full && b_req && !a_req;
wire grant   = grant_a || grant_b;
wire new_val = grant_a ? samp : samp_b;
wire new_ch  = grant_a ? CH_A : CH_B;
// a queued raw-sample commit is stale the moment the sample moves again
wire keep_q  = q_pend && !(q_ch == CH_A && a_chg);

    initial o_clean = 1'b0;
   initial o_evt_cnt = 4'd0;
   initial evt_cnt   = 4'd0;

    always @(posedge clk)
        pv <= 1'b1;

   always @(posedge clk) begin
       if (i_ce) begin
           if (i_raw ^ i_arm)
               evt_cnt <= evt_cnt + 4'd1;
           o_evt_cnt <= evt_cnt ^ {3'b000, i_disarm};
       end
   end

    always @(posedge clk) begin
        if (i_ce) begin
           // ---- channel A: the raw sample ----
           if (a_chg) begin
               // sample changed: restart the stability count
               samp     <= i_raw;
               cnt      <= 3'd0;
               stable_f <= 1'b0;
           end else if (cnt != K) begin
               if (!a_req) begin
                   cnt <= cnt + 3'd1;
               end else if (grant_a) begin
// take a commit slot; the flag and output move one step later
                   cnt      <= cnt + 3'd1;
               end
// both slots busy: hold at K-1 and retry once one frees
           end

           // ---- channel B: the arm button, same filter, same stage ----
           if (b_chg) begin
               samp_b <= i_arm;
               cnt_b  <= 3'd0;
           end else if (cnt_b != K) begin
               if (!b_req) begin
                   cnt_b <= cnt_b + 3'd1;
               end else if (grant_b) begin
                   cnt_b    <= cnt_b + 3'd1;
               end
           end
// ---- writeback slot: applies the entry the retire pipe handed over ----
           if (wb_pend) begin
               if (wb_ch == CH_A) begin
                   if (!a_chg) begin
                       o_clean  <= wb_val;   // commit the debounced value
                       stable_f <= 1'b1;
                   end
               end else if (!b_chg) begin
                   arm_clean <= wb_val;
               end
           end
// the head hands its entry to the retire pipe; the apply path is
// registered four deep to keep the commit fanout off the counter
// logic, and every stage re-checks its own channel so an entry whose
// sample moved again while in flight is dropped where it stands
s1_pend <= cmt_pend && !(cmt_ch == CH_A && a_chg)
                    && !(cmt_ch == CH_B && b_chg);
s1_val  <= cmt_val;
s1_ch   <= cmt_ch;
s2_pend <= s1_pend && !(s1_ch == CH_A && a_chg)
                   && !(s1_ch == CH_B && b_chg);
s2_val  <= s1_val;
s2_ch   <= s1_ch;
s3_pend <= s2_pend && !(s2_ch == CH_A && a_chg)
                   && !(s2_ch == CH_B && b_chg);
s3_val  <= s2_val;
s3_ch   <= s2_ch;
s4_pend <= s3_pend && !(s3_ch == CH_A && a_chg)
                   && !(s3_ch == CH_B && b_chg);
s4_val  <= s3_val;
s4_ch   <= s3_ch;
wb_pend <= s4_pend && !(s4_ch == CH_A && a_chg)
                   && !(s4_ch == CH_B && b_chg);
wb_val  <= s4_val;
wb_ch   <= s4_ch;

           // ---- shared stage: retires one entry per enabled step ----
           if (cmt_pend) begin
// the head always retires: the queued tail shifts up and a fresh
// grant lands in whichever slot is left over
cmt_pend <= keep_q || grant;
cmt_val  <= keep_q ? q_val : new_val;
cmt_ch   <= keep_q ? q_ch  : new_ch;
q_pend   <= keep_q && grant;
q_val    <= new_val;
q_ch     <= new_ch;
           end
else begin
cmt_pend <= grant;
cmt_val  <= new_val;
cmt_ch   <= new_ch;
q_pend   <= 1'b0;
end

            if (i_disarm)
                armed <= 1'b0;
           else if (arm_clean)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

    reg [3:0] nxt;

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
            else if (nxt == S_ROUTE)
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);
endmodule

module pcb_pool_top (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] ce,
    input  wire [5:0] start,
    input  wire [5:0] route_ok,
    input  wire [5:0] ack,
    output reg  [3:0] pool,     // free router-engine seats
    output reg  [5:0] hold,     // per-board seat ownership
    output wire [5:0] window    // per-board routing window (tracking)
);
    // Six board flows share a pool of six router/DRC engine seats.
    localparam [3:0] TOTAL = 4'd6;

    wire [3:0] s0, s1, s2, s3, s4, s5;
    wire [7:0] m0, m1, m2, m3, m4, m5;
    wire       t0, t1, t2, t3, t4, t5;

    wire h0 = hold[0];
    wire h1 = hold[1];
    wire h2 = hold[2];
    wire h3 = hold[3];
    wire h4 = hold[4];
    wire h5 = hold[5];

    assign window = {t5, t4, t3, t2, t1, t0};
    // Grants are registered: the seat is booked one cycle after the arbiter
    // picks a winner, so the seat already in flight must be accounted for.
    reg  [5:0] gnt_q;
    wire       q_any = |gnt_q;
// Booking is two-phase: the arbiter parks its winner in gnt_p, and the seat
// is charged to the pool on that board's next enabled cycle. The parking
// station holds one grant, so the arbiter stalls while it is occupied.
reg  [5:0] gnt_p;
wire       p_any = |gnt_p;
wire [5:0] book  = gnt_p & ce;   // parked grant commits on the owner's step
// Occupancy shadow: seats currently charged out, maintained alongside the
// pool so the completion report has a count that is independent of the pool.
reg  [3:0] used;
// Returns are retimed by one step: the six-way release popcount is
// registered here and applied to the occupancy shadow on the following
// cycle, which keeps that adder out of the credit comparator's cone. The
// pool is a status count outside the arbiter path and still absorbs
// releases immediately, so the shadow trails it by whatever is parked here.
reg  [2:0] ret;
// Seat audit ledger: every booking and every release is logged here. Both
// counters are free-running and wrap at four bits; their difference is the
// live seat occupancy, and the arbiter takes its credit from that instead
// of the shadow above, because the ledger sees a release in the same cycle
// it happens while the shadow only picks it up one step later.
reg  [3:0] n_book;
reg  [3:0] n_free;

    pcb_flow_fsm u0 (.clk(clk), .rst(rst), .ce(ce[0]), .start(start[0]),
                     .route_ok(route_ok[0]), .ack(ack[0]),
                     .state(s0), .mirror(m0), .tracking(t0));
    pcb_flow_fsm u1 (.clk(clk), .rst(rst), .ce(ce[1]), .start(start[1]),
                     .route_ok(route_ok[1]), .ack(ack[1]),
                     .state(s1), .mirror(m1), .tracking(t1));
    pcb_flow_fsm u2 (.clk(clk), .rst(rst), .ce(ce[2]), .start(start[2]),
                     .route_ok(route_ok[2]), .ack(ack[2]),
                     .state(s2), .mirror(m2), .tracking(t2));
    pcb_flow_fsm u3 (.clk(clk), .rst(rst), .ce(ce[3]), .start(start[3]),
                     .route_ok(route_ok[3]), .ack(ack[3]),
                     .state(s3), .mirror(m3), .tracking(t3));
    pcb_flow_fsm u4 (.clk(clk), .rst(rst), .ce(ce[4]), .start(start[4]),
                     .route_ok(route_ok[4]), .ack(ack[4]),
                     .state(s4), .mirror(m4), .tracking(t4));
    pcb_flow_fsm u5 (.clk(clk), .rst(rst), .ce(ce[5]), .start(start[5]),
                     .route_ok(route_ok[5]), .ack(ack[5]),
                     .state(s5), .mirror(m5), .tracking(t5));

    // A board wants a seat while its window is armed; it gives the seat back
    // on its next enabled cycle after the export has been acknowledged.
wire [5:0] req = window & ~hold & ~gnt_q & ~gnt_p & ce;
    wire [5:0] rel = ~window &  hold & ce;

    // Fixed-priority arbiter: at most one seat handed out per cycle.
wire [3:0] inflight    = {3'b0, p_any} + {3'b0, q_any};
wire [3:0] charged     = n_book - n_free;
wire [4:0] occ         = {1'b0, charged} + {1'b0, inflight};
wire       have_credit = (occ < {1'b0, TOTAL});
    wire [5:0] pri;
    assign pri[0] = req[0];
    assign pri[1] = req[1] & ~req[0];
    assign pri[2] = req[2] & ~(|req[1:0]);
    assign pri[3] = req[3] & ~(|req[2:0]);
    assign pri[4] = req[4] & ~(|req[3:0]);
    assign pri[5] = req[5] & ~(|req[4:0]);

wire [5:0] gnt     = (have_credit && !p_any) ? pri : 6'b0;

    wire [2:0] rel_cnt = {2'b0, rel[0]} + {2'b0, rel[1]} + {2'b0, rel[2]} +
                         {2'b0, rel[3]} + {2'b0, rel[4]} + {2'b0, rel[5]};

    initial begin
        pool = TOTAL;
        hold = 6'd0;
    gnt_q = 6'd0;
gnt_p = 6'd0;
used = 4'd0;
ret = 3'd0;
n_book = 4'd0;
n_free = 4'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
            hold <= 6'd0;
    gnt_q <= 6'd0;
gnt_p <= 6'd0;
used <= 4'd0;
ret <= 3'd0;
n_book <= 4'd0;
n_free <= 4'd0;
        end else begin
    hold <= (hold | gnt_q) & ~rel;
    pool <= pool - {3'b0, q_any} + {1'b0, rel_cnt};
gnt_q <= book;
gnt_p <= (gnt_p & ~book) | gnt;
used <= used + {3'b0, q_any} - {1'b0, ret};
ret  <= rel_cnt;
n_book <= n_book + {3'b0, q_any};
n_free <= n_free + {1'b0, rel_cnt};
        end
    end

    // Pool property: if no seat is free, every board must be holding one.
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 && h1 && h2 && h3 && h4 && h5);
    // Hand-off property: a registered grant is always backed by a seat that
    // was still free when the arbiter committed it, so the pool is never
    // empty while a grant is landing.
    always @(posedge clk)
        if (gnt_q != 6'd0)
            assert (pool != 4'd0);
    // Occupancy property: with every board seated the pool is fully charged
    // out and the parking station must be empty -- there is no seat left for
    // the arbiter to have booked.
    always @(posedge clk)
        if (hold == 6'b111111)
            assert (used == TOTAL && gnt_p == 6'd0);
endmodule

module fsm_phase_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_start,
    output wire [4:0] o_phase,
    output wire       o_busy
);
    // binary-encoded FSM: only 0..4 are legal encodings, 5..7 are unreachable
    localparam [2:0] S_IDLE   = 3'd0,
                     S_FETCH  = 3'd1,
                     S_DECODE = 3'd2,
                     S_EXEC   = 3'd3,
                     S_WRITE  = 3'd4;

    reg [2:0] state;
    reg [4:0] dec;   // shadow one-hot decode of state
   reg [4:0] dec_s; // decode stage register, one pipeline step ahead of dec
    reg       win;   // window register: opened by a job start, closed at retire
   reg       tail;  // retire stage: carries the window over the write-back phase
  reg [2:0] age;   // phase age of the job in flight: 1 at launch, 5 at retire
 reg       rjob;   // the job in flight belongs to the refresh channel
 reg [3:0] rtimer; // refresh interval countdown, one tick per enabled cycle
reg       wb;     // write-back phase flag: the one phase state no longer encodes

    initial state = S_IDLE;
    initial dec   = 5'b00001;
   initial dec_s = 5'b00001;
    initial win   = 1'b0;
   initial tail  = 1'b0;
  initial age   = 3'd0;
 initial rjob   = 1'b0;
 initial rtimer = 4'd15;
initial wb     = 1'b0;

 // the refresh channel asks for the pipe once its interval has expired
 wire rreq = (rtimer == 4'd0);

    reg [2:0] nstate;
    always @(*) begin
        case (state)
S_IDLE:   nstate = (!wb && (i_start || rreq)) ? S_FETCH : S_IDLE;
            S_FETCH:  nstate = S_DECODE;
            S_DECODE: nstate = S_EXEC;
S_EXEC:   nstate = S_IDLE;   // the write-back phase is carried by wb, not by state
            default:  nstate = 3'd5;   // illegal-encoding trap, never taken
        endcase
    end
// a normal job leaves EXEC still owing a write-back phase; that phase has no
// FSM encoding of its own, so wb carries it while state sits back in its slot
wire nwb = (state == S_EXEC) && !rjob;

    // one-hot decode of the next state; illegal encodings decode to all-zero
wire [4:0] ndec = nwb                  ? (5'b00001 << S_WRITE) :
                  (nstate == S_IDLE)   ? 5'b00001 :
                      (nstate == S_FETCH)  ? 5'b00010 :
                      (nstate == S_DECODE) ? 5'b00100 :
                  (nstate == S_EXEC)   ? 5'b01000 : 5'b00000;

   // phase code shown on o_phase during the last cycle a job owns the pipe:
   // refresh jobs retire out of EXEC, normal jobs out of WRITE
   wire [4:0] retdec = rjob ? 5'b01000 : 5'b10000;

    always @(posedge i_clk) begin
        if (i_rst) begin
            state <= S_IDLE;
            dec   <= 5'b00001;
           dec_s <= 5'b00001;
            win   <= 1'b0;
           tail  <= 1'b0;
          age   <= 3'd0;
           rjob   <= 1'b0;
           rtimer <= 4'd15;
wb     <= 1'b0;
        end else if (i_ce) begin
            state <= nstate;
           dec_s <= ndec;      // decode is registered here ...
           dec   <= dec_s;     // ... and presented on o_phase one cycle later
wb    <= nwb;       // the write-back flag follows the EXEC hand-off
if ((state == S_IDLE) && !wb && (i_start || rreq))
                win <= 1'b1;               // Q: a job is launched
           else if (tail)             // the retire stage owns the window now
                win <= 1'b0;               // R: the job retires

           // hand the window over once DECODE reaches o_phase, so the retire
           // stage covers the final write-back cycle on its own
           if (dec == 5'b00100)
               tail <= 1'b1;
          else if (dec == retdec)
               tail <= 1'b0;

          // age the job one phase per enabled cycle: the launch cycle seeds
          // the counter and the retiring write-back cycle clears it again
if ((state == S_IDLE) && !wb && (i_start || rreq))
              age <= 3'd1;
         else if (dec == retdec)
              age <= 3'd0;
          else if (win || tail)
              age <= age + 3'd1;

         // the refresh engine is a peer client of the same phase pipeline:
         // an explicit start always wins the idle slot, a due refresh takes
         // whatever idle slot is left over
if ((state == S_IDLE) && !wb && i_start)
             rjob <= 1'b0;
else if ((state == S_IDLE) && !wb && rreq)
             rjob <= 1'b1;
         else if (dec == retdec)
             rjob <= 1'b0;

         // restart the interval only when the refresh channel is granted
if ((state == S_IDLE) && !wb && !i_start && rreq)
             rtimer <= 4'd15;
         else if (rtimer != 4'd0)
             rtimer <= rtimer - 4'd1;
        end
    end

    assign o_phase = dec;
assign o_busy  = win | tail | wb | (|age);  // busy while any stage still owns the job

    // P: inside the job window the phase decode always names some phase
    always @(posedge i_clk)
        assert (!win || (|dec));

   // P2: a busy job showing phase 0 on o_phase is the launch cycle, so the
   // decode stage must already be carrying the FETCH phase behind it
   always @(posedge i_clk)
       assert (!win || (dec != 5'b00001) || (dec_s == 5'b00010));

  // P3: the retire stage only ever holds the window at the tail of a job, so
  // that job has aged at least four phases and o_phase has left the idle slot
  always @(posedge i_clk)
      assert (!tail || ((dec != 5'b00001) && (age >= 3'd4)));
endmodule

module wdt_absence (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       arm,       // Q: opens the window
    input  wire       disarm,    // R: closes the window (may never arrive)
    input  wire       kick,      // pet the watchdog
    output reg  [3:0] cnt,
    output reg        expired,
    output reg        safe,
output reg        armed,
output reg [3:0] kick_cnt,
output reg [3:0] disarm_cnt
);
    localparam [3:0] LIMIT = 4'd10;  // timeout value
    localparam [3:0] WARN  = 4'd8;   // below this the timer is in the safe zone
    localparam [1:0] GRACE = LIMIT - WARN;  // warning-zone dwell before timeout
    reg [1:0] grace;                        // ticks elapsed since cnt hit WARN
reg [3:0] evt_shift;
localparam [3:0] STAGE = 4'd4;          // half of the pre-warning interval
reg [3:0] stage2;                       // pre-warning ticks past the halfway mark
localparam [3:0] QSTAGE = 4'd2;         // quarter of the pre-warning interval
reg [3:0] stage3;                       // pre-warning ticks in the final quarter
localparam [3:0] B_LIMIT = 4'd3;        // backup trip point, in prescaled units
reg [1:0] b_tick;                       // /4 prescaler of the backup watchdog
reg [3:0] b_cnt;                        // prescaled ticks since the last kick
reg       hard;                         // backup watchdog has tripped

    initial cnt     = 4'd0;
    initial expired = 1'b0;
    initial safe    = 1'b1;
    initial armed   = 1'b0;
    initial grace   = 2'd0;
initial kick_cnt = 4'd0;
initial disarm_cnt = 4'd0;
initial evt_shift = 4'd0;
initial stage2 = 4'd0;
initial stage3 = 4'd0;
initial b_tick = 2'd0;
initial b_cnt  = 4'd0;
initial hard   = 1'b0;

    always @(posedge clk) begin
        if (i_ce) begin
// bookkeeping only: how many kicks have been seen
if (kick)
kick_cnt <= kick_cnt + 4'd1;
evt_shift <= {evt_shift[2:0], disarm};
if (disarm && !arm)
disarm_cnt <= disarm_cnt + 4'd1 + {3'd0, evt_shift[3]};
            // window register: set by arm, cleared by disarm
            if (arm)
                armed <= 1'b1;
            else if (disarm)
                armed <= 1'b0;

            // the watchdog only runs inside the window
            if (armed) begin
                if (kick) begin
                    cnt     <= 4'd0;
stage2  <= 4'd0;
stage3  <= 4'd0;
                    grace   <= 2'd0;
                    expired <= 1'b0;
                    safe    <= 1'b1;
end else if (cnt < STAGE) begin
// first half of the pre-warning interval is held in cnt
                    cnt     <= cnt + 4'd1;
end else if (stage2 < QSTAGE) begin
// cnt is frozen at the halfway mark and the third quarter of
// the pre-warning interval accumulates here
stage2  <= stage2 + 4'd1;
end else if (stage3 < QSTAGE) begin
// final quarter before the warning threshold; dropping out of
// it is what takes the timer out of the safe zone
stage3  <= stage3 + 4'd1;
safe    <= ((stage3 + 4'd1) < QSTAGE);
                end else if (grace < GRACE) begin
// once every pre-warning stage is full the remaining ticks before
                    // timeout are accumulated here, so the warning-zone dwell
                    // can be reported on its own
                    grace   <= grace + 2'd1;
                    expired <= ((grace + 2'd1) == GRACE);
                    safe    <= 1'b0;
                end
            end

           // backup watchdog: same window and same kick, but clocked at a
           // quarter rate so it trips after the primary one; when it trips it
           // latches the expiry flag so the fault cannot be missed
           if (armed) begin
               if (kick) begin
                   b_tick <= 2'd0;
                   b_cnt  <= 4'd0;
                   hard   <= 1'b0;
               end else if (!hard) begin
                   if (b_tick == 2'd3) begin
                       b_tick <= 2'd0;
                       b_cnt  <= b_cnt + 4'd1;
                       if ((b_cnt + 4'd1) == B_LIMIT) begin
                           hard    <= 1'b1;
                           expired <= 1'b1;
                       end
                   end else begin
                       b_tick <= b_tick + 2'd1;
                   end
               end else begin
                   expired <= 1'b1;
               end
           end
        end
    end

    // P: once armed (and until disarmed, if ever), the timer can never report
    // both "expired" and "safe" at the same time.
    always @(*)
        if (armed)
            assert (!(expired && safe));
endmodule

// In-flight tracker for a fixed-latency chart-query render pipeline.
// Each issued query walks a 4-stage valid shift register; occupancy is the
// number of ones currently resident in that shift register.
module query_pipe_tracker (
    input  wire       clk,
    input  wire       ce,        // pipeline advance / idle control
    input  wire       issue,     // a new query is pushed into stage 0
    output wire       retire,    // a rendered result leaves the last stage
    output wire       full,      // tracker says all 4 slots are busy
output reg  [2:0] occ,       // queries in flight
output reg  [3:0] retire_cnt // rolling count of retired queries
);

    reg [3:0] pipe;              // fixed-latency valid shift register
   reg [1:0] apipe;             // 2-stage cached-result render path
   reg [1:0] xpipe;             // 2-stage express render path (peer engine)
   reg       xhold;             // express capture slot: query parked while stalled
   reg       rr;                // round-robin turn: 0 = main engine, 1 = express
reg       stg;               // entry stage: admitted query registered before stage 0
    reg       hold;              // input capture slot: query admitted while stalled
    reg       ever_issued;       // shadow: an issue has been observed earlier
    reg       armed;             // scope: still before the pipe was ever full
reg       retire_seen;        // sticky: at least one retirement observed

    initial begin
        pipe        = 4'b0000;
        occ         = 3'd0;
        ever_issued = 1'b0;
        armed       = 1'b1;
        hold        = 1'b0;
       apipe       = 2'b00;
       xpipe       = 2'b00;
       xhold       = 1'b0;
       rr          = 1'b0;
stg         = 1'b0;
retire_cnt  = 4'd0;
retire_seen = 1'b0;
    end

   assign retire = pipe[3] || apipe[1] || xpipe[1];
    assign full   = (occ == 3'd4);

    // Admission control: the tracker backpressures at capacity, and a query
    // taken while the pipe is not advancing waits in the capture slot.
    wire room   = (occ != 3'd4);
    wire accept = issue && !hold && room;   // query admitted this cycle
   // Round-robin hand-off between the two render engines. The express
   // engine only takes its turn when its capture slot is free; otherwise
   // the main engine serves the query.
   wire use_x   = rr && !xhold;
   wire inject  = hold  || (accept && !use_x);  // entry pushed into stage 0
   wire xinject = xhold || (accept &&  use_x);  // entry pushed into express stage 0
   // A query offered while the capture slot is still busy is served from the
   // result cache instead: shorter path, same 4-slot occupancy budget.
   wire aux_accept = ce && issue && hold && room;

    always @(posedge clk) begin
        if (ce) begin
            // drain: stage 3 retires, everything shifts, stage 0 takes issue
pipe <= {pipe[2:0], stg};
stg  <= inject;

            // occupancy bookkeeping: +1 on issue, -1 on retire
           occ  <= occ + {2'b00, accept} + {2'b00, aux_accept}
                      - {2'b00, pipe[3]} - {2'b00, apipe[1]}
                      - {2'b00, xpipe[1]};
           apipe <= {apipe[0], aux_accept};
           xpipe <= {xpipe[0], xinject};
            hold <= 1'b0;
           xhold <= 1'b0;

            // shadow register for the earlier event
           if (accept || aux_accept) ever_issued <= 1'b1;
           if (accept) rr <= ~rr;   // hand the turn to the other engine

            // scope closes the first time the unit reports saturation
            if (full)  armed <= 1'b0;
        end else if (accept) begin
            // stalled: park the admitted query and count it as in flight
           if (use_x) xhold <= 1'b1;
           else       hold  <= 1'b1;
            occ         <= occ + 3'd1;
            ever_issued <= 1'b1;
           rr          <= ~rr;
        end
    end

    // Precedence, before the unit was ever full:
    // if work is in flight now, an issue must have happened earlier.
    always @(posedge clk)
        if (armed && occ != 3'd0)
            assert (ever_issued);

// Distractor telemetry: counts retirements, observed by nothing else.
always @(posedge clk) begin
   if (ce && retire) begin
        retire_seen <= 1'b1;
        retire_cnt  <= retire_cnt + (retire_seen ? 4'd2 : 4'd1);
    end
end

   // Telemetry consistency: the retirement counter can only have left zero
   // if something was rendered, and nothing can be rendered before an issue.
   always @(posedge clk)
       assert (retire_cnt == 4'd0 || ever_issued);

endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
output wire [2:0] o_inflight,
output reg  [3:0] act_cnt
);
// fixed-latency (6 cycle) pipeline occupancy shift register
reg [5:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;
// remaining issue credits: an op is only taken while credits are left
reg [2:0] cred;
// currently programmed outstanding-op limit, retuned at each quiesce point
reg [2:0] lim;
// congestion flag: enable dropped while work was still in flight
reg       thr;
// credit-return path: a retired op's credit takes four more cycles to walk
// back from the pipe tail to the issue-side credit counter
reg       rq0;
reg       rq1;
reg       rq2;
reg       rq3;
// returned credits wait here until the credit counter's write port is free
reg [2:0] rtn;
// merge stage: a credit leaving the park register spends one cycle in this
// flop before it is written into the issue-side credit counter
reg       mrg;
// retiming stages: the route from the merge flop back across to the
// issue-side credit counter is long, so a merged credit walks four more
// flops before it is actually added into cred
reg       mg0;
reg       mg1;
reg       mg2;
reg       mg3;
reg       seen;

initial pipe     = 6'b000000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;
initial cred     = 3'd4;
initial lim      = 3'd4;
initial thr      = 1'b0;
initial rq0      = 1'b0;
initial rq1      = 1'b0;
initial rq2      = 1'b0;
initial rq3      = 1'b0;
initial rtn      = 3'd0;
initial mrg      = 1'b0;
initial mg0      = 1'b0;
initial mg1      = 1'b0;
initial mg2      = 1'b0;
initial mg3      = 1'b0;
initial act_cnt  = 4'd0;
initial seen     = 1'b0;

wire retire  = pipe[5];
// credit gate on the issue path
wire accept  = issue && (cred != 3'd0);
// nothing still travelling back down the credit-return path
wire rq_empty = !(rq0 || rq1 || rq2 || rq3);
// at most one parked credit is merged back per cycle, and only on cycles
// where the issue side is not already updating the credit counter
wire drain = (rtn != 3'd0) && !accept;
// true quiesce: pipe drained, returns landed, nothing arriving this cycle
wire quiesce = (pipe == 6'b000000) && rq_empty && !issue;

    always @(posedge clk) begin
        if (rst) begin
pipe     <= 6'b000000;
            inflight <= 3'd0;
act_cnt <= 4'd0;
seen    <= 1'b0;
        end else if (i_ce) begin
pipe     <= {pipe[4:0], accept};
inflight <= inflight + {2'b00, accept} - {2'b00, retire};
act_cnt <= act_cnt + {3'b000, retire};
seen    <= seen | issue;
        end
    end
// credit accounting and outstanding-limit retuning
always @(posedge clk) begin
    if (rst) begin
        cred <= 3'd4;
        lim  <= 3'd4;
        thr  <= 1'b0;
        rtn  <= 3'd0;
mrg  <= 1'b0;
mg0  <= 1'b0;
mg1  <= 1'b0;
mg2  <= 1'b0;
mg3  <= 1'b0;
    end else if (i_ce) begin
        if (quiesce) begin
            lim  <= thr ? 3'd2 : 3'd4;
            cred <= thr ? 3'd2 : 3'd4;
            thr  <= 1'b0;
            rtn  <= 3'd0;
mrg  <= 1'b0;
mg0  <= 1'b0;
mg1  <= 1'b0;
mg2  <= 1'b0;
mg3  <= 1'b0;
        end else begin
cred <= cred - {2'b00, accept} + {2'b00, mg3};
            rtn  <= rtn + {2'b00, rq3} - {2'b00, drain};
mrg  <= drain;
mg0  <= mrg;
mg1  <= mg0;
mg2  <= mg1;
mg3  <= mg2;
        end
    end else if (pipe != 6'b000000) begin
        thr  <= 1'b1;
    end
end

// credit-return path: retire pulses shift back toward the issue side
always @(posedge clk) begin
    if (rst) begin
        rq0 <= 1'b0;
        rq1 <= 1'b0;
        rq2 <= 1'b0;
        rq3 <= 1'b0;
    end else if (i_ce) begin
        rq0 <= retire;
        rq1 <= rq0;
        rq2 <= rq1;
        rq3 <= rq2;
    end
end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module phase_divider_pair (
    input  wire       clk,
    input  wire       ce,       // divider step enable; low = idle, all state held
    input  wire       resync,   // realigns both phase counters, retires the pristine scope
    output reg  [2:0] phase,    // primary phase counter, mod 5
    output reg  [2:0] cnt,      // skewed phase counter, mod 5, built 2 phases ahead
    output reg        en_load,  // divided enable: fires the cycle after phase wraps
    output reg        en_sample,// divided enable: fires the cycle after cnt wraps
    output reg        pristine  // high until the first resync has ever happened
);

    // Load/sample ledger: every load pulse and every sample pulse is logged
    // for the lifetime of the current alignment, so the buffer downstream can
    // account for the two divided enables it sees.
    reg  [3:0] n_load;   // count of load pulses issued
    reg  [3:0] n_samp;   // count of sample pulses issued

    // samples that do not have a matching load behind them yet
    wire [3:0] samp_ahead = n_samp - n_load;
    // a realignment can leave the ping-pong buffer starved; while the sample
    // side is two or more entries ahead, inject make-up load pulses
    wire       makeup     = (samp_ahead >= 4'd2);

   // Skew-buffer ledger: the sample pulse captures one entry into the
   // ping-pong skew buffer and the load pulse releases it to the sink, so
   // both sides are logged as the buffer sees them, on the divided enables.
   reg  [3:0] n_cap;    // entries captured by the sample side
   reg  [3:0] n_rel;    // entries released by the load side
// the bank write port is pipelined four deep (stage, format, protect, commit):
// a sample pulse enters the first stage and only lands in the array four
// enabled cycles later, so n_cap advances off the last stage.  The load side
// reads through a forwarding path, so occupancy counts the in-flight entries.
reg        cap_pend; // entry staged by the sample side, not yet committed
reg        cap_s2;   // write pipe stage 2 (format)
reg        cap_s3;   // write pipe stage 3 (protect)
reg        cap_s4;   // write pipe stage 4 (commit into the array)
// the load side is a read pipeline of the same depth (address, array read,
// ECC correct, output register): a release only leaves the array four
// enabled cycles after its load pulse.  An in-flight read is already spoken
// for, so it leaves the occupancy the moment the pulse is issued.
reg        rel_s1;   // read pipe stage 1 (address)
reg        rel_s2;   // read pipe stage 2 (array read)
reg        rel_s3;   // read pipe stage 3 (ECC correct)
reg        rel_s4;   // read pipe stage 4 (retire from the array)
wire [3:0] level     = n_cap + {3'd0, cap_pend} + {3'd0, cap_s2}
                       + {3'd0, cap_s3} + {3'd0, cap_s4} - n_rel
                       - {3'd0, rel_s1} - {3'd0, rel_s2}
                       - {3'd0, rel_s3} - {3'd0, rel_s4};
   // the load side must not release an entry the sample side has not
   // captured yet, so the phase-4 pulse waits for a filled buffer
   wire       bank_full = (level != 4'd0);

   // Load-side stall watchdog: the sink downstream must never be left
   // without a load pulse for long, so the gap since the last one is timed
   // and a make-up pulse is forced once that gap gets too wide.
   reg  [2:0] gap;      // enabled cycles since the last load pulse
   wire       wdog       = (gap >= 3'd6);
wire       load_pulse = ((phase == 3'd4) && bank_full) || makeup || wdog;

    // The skewed counter is constructed 2 phases ahead of the primary phase
    // counter, so the two divided-enable pulses are interleaved by design.
    initial phase     = 3'd0;
    initial cnt       = 3'd2;
    initial en_load   = 1'b0;
    initial en_sample = 1'b0;
    initial pristine  = 1'b1;
    initial n_load    = 4'd0;
    initial n_samp    = 4'd0;
initial n_cap     = 4'd0;
initial n_rel     = 4'd0;
initial cap_pend  = 1'b0;
initial cap_s2    = 1'b0;
initial cap_s3    = 1'b0;
initial cap_s4    = 1'b0;
initial rel_s1    = 1'b0;
initial rel_s2    = 1'b0;
initial rel_s3    = 1'b0;
initial rel_s4    = 1'b0;
   initial gap       = 3'd0;

    always @(posedge clk) begin
        if (resync) begin
            // hard realignment: both phase counters are slammed to zero, which
            // destroys the constructed skew (and retires the pristine scope)
            phase     <= 3'd0;
            cnt       <= 3'd0;
            en_load   <= 1'b0;
            en_sample <= 1'b0;
            pristine  <= 1'b0;
            n_load    <= 4'd0;
            n_samp    <= 4'd0;
n_cap     <= 4'd0;
n_rel     <= 4'd0;
cap_pend  <= 1'b0;
cap_s2    <= 1'b0;
cap_s3    <= 1'b0;
cap_s4    <= 1'b0;
rel_s1    <= 1'b0;
rel_s2    <= 1'b0;
rel_s3    <= 1'b0;
rel_s4    <= 1'b0;
           gap       <= 3'd0;
        end
        else if (ce) begin
            phase     <= (phase == 3'd4) ? 3'd0 : phase + 3'd1;
            cnt       <= (cnt   == 3'd4) ? 3'd0 : cnt   + 3'd1;
            // each divided enable pulses exactly when its phase counter wraps
           en_load   <= load_pulse;
            en_sample <= (cnt   == 3'd4);
            // ledger entries are made as the pulses are issued
           n_load    <= n_load + (load_pulse ? 4'd1 : 4'd0);
            n_samp    <= n_samp + ((cnt == 3'd4) ? 4'd1 : 4'd0);
cap_pend  <= en_sample;
cap_s2    <= cap_pend;
cap_s3    <= cap_s2;
cap_s4    <= cap_s3;
n_cap     <= n_cap + (cap_s4 ? 4'd1 : 4'd0);
rel_s1    <= en_load;
rel_s2    <= rel_s1;
rel_s3    <= rel_s2;
rel_s4    <= rel_s3;
n_rel     <= n_rel + (rel_s4 ? 4'd1 : 4'd0);
           gap       <= load_pulse ? 3'd0 : gap + 3'd1;
        end
    end

    // Absence: while the divider has never been resynced, the two divided
    // enables are never asserted in the same cycle.
    always @(posedge clk)
        if (pristine)
            assert (!(en_load && en_sample));

   // Alignment: while the divider has never been resynced, the sample pulse
   // always lands three enabled cycles into the current load window.
   always @(posedge clk)
       if (pristine)
           assert (!en_sample || (gap == 3'd3));

endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
output wire       o_settled, // no sample in flight
output reg  [3:0] o_act,     // beat-activity tally, observation only
output reg  [3:0] o_dbg      // distractor: idle/beat tally, observation only
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
   // launch flop on the gray encoder: the crossing wires are driven
   // point to point instead of straight off the encoder cone
   reg [3:0] gq;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;
   // programmable ring bound: the bridge starts at quarter span after reset and
   // opens up one binary step per four completed laps
   reg [3:0] lim;
   reg [1:0] laps;
  // read-side pointer of the same ring: one data word takes two destination
  // beats, so it advances on alternate enables.  it shares the programmable
  // ring bound with the write pointer.
  reg [3:0] cnt2;
  reg [3:0] g2;
  reg       ph;
 // completion pointer of the same ring: the consumer retires a word on the
 // opposite half beat, so this one steps when the read phase is low.  it uses
 // the same programmable ring bound as the write and read pointers.
 reg [3:0] cnt3;
 reg [3:0] g3;
 // the crossing lane is a single physical 4-bit bundle, so the three pointers
 // take turns on it under a one-hot grant that rotates.  the turn is handed
 // over only at the common origin, where every encoder reads zero and the
 // lane sees no step on the bundle.
 reg [2:0] own;
reg [3:0] act;
// distractor: purely observational beat tally, not part of the crossing path
reg [3:0] idlecnt;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
       gq  = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
       lim  = 4'd3;
       laps = 2'd0;
      cnt2 = 4'd0;
      g2   = 4'd0;
      ph   = 1'b0;
     cnt3 = 4'd0;
     g3   = 4'd0;
     own  = 3'b001;
act   = 4'd0;
o_act = 4'd0;
idlecnt = 4'd0;
o_dbg   = 4'd0;
    end

   wire       wrap     = (cnt >= lim);
   wire [3:0] nxt      = wrap ? 4'd0 : cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);
  wire       wrap2      = (cnt2 >= lim);
  wire [3:0] nxt2       = wrap2 ? 4'd0 : cnt2 + 4'd1;
  wire [3:0] nxt_gray2  = nxt2 ^ (nxt2 >> 1);
  wire       tick2      = ph;
 wire       wrap3      = (cnt3 >= lim);
 wire [3:0] nxt3       = wrap3 ? 4'd0 : cnt3 + 4'd1;
 wire [3:0] nxt_gray3  = nxt3 ^ (nxt3 >> 1);
 wire       tick3      = ~ph;
 wire       swap       = (cnt == 4'd0) && (cnt2 == 4'd0) && (cnt3 == 4'd0);
 // one-hot grant onto the shared bundle: each encoder is masked by its grant
 // bit and the three masked copies are or-ed onto the lane
 wire [3:0] lane       = (own[0] ? g : 4'd0) | (own[1] ? g2 : 4'd0) | (own[2] ? g3 : 4'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
          gq  <= lane;
           s1  <= gq;
            s2  <= s1;
          ph  <= ~ph;
          if (tick2) begin
              cnt2 <= nxt2;
              g2   <= nxt_gray2;
          end
         if (tick3) begin
             cnt3 <= nxt3;
             g3   <= nxt_gray3;
         end
          if (swap)
             own <= {own[1:0], own[2]};
           if (wrap) begin
               laps <= laps + 2'd1;
               if (laps == 2'd3)
                   lim <= {lim[2:0], 1'b1};
           end
act   <= act + 4'd1;
o_act <= act ^ {3'b000, ph};
idlecnt <= idlecnt + 4'd1;
o_dbg   <= idlecnt ^ act;
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
   assign o_settled = (diff == 4'd0) && (gq == s1);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    // upstream credit: number of empty slots, maintained incrementally so the
    // full indication does not have to decode the valid flags
    reg [1:0] free;
   // peak occupancy telemetry: high-water mark of the occupancy counter since
   // reset, sampled every cycle and read back on the data output while the
   // buffer is empty (the head slot carries no valid word then)
   reg [1:0] hwm;
  // the peak comparator is retimed behind a stage register: the occupancy
  // that will be resident next cycle is captured here and is compared
  // against the high-water mark on the following edge, so the occupancy
  // adders and the comparator no longer share one cycle of timing budget
  reg [1:0] peak_q;
 // the peak telemetry is filed per stage: hwm is the head buffer's mark and
 // hwm_b the spill stage's, so a deep backlog waiting in the spill stage is
 // not reported as deep head occupancy. peak_sel remembers which mark the
 // staged sample belongs to, since the comparison happens a cycle after the
 // sample is captured.
 reg [1:0] hwm_b;
 reg       peak_sel;
    reg [7:0] d0, d1;

   // spill stage: a second two-entry buffer sitting behind the head buffer so
   // a burst is not backpressured while the head buffer is draining. words
   // leave the spill stage in arrival order and refill the head buffer.
   reg       vb0, vb1;
   reg [1:0] cntb;
   reg [7:0] b0, b1;
  // landing register on the spill write path: din is electrically far from
  // the spill array, so a word routed to the spill stage is captured here
  // first and written into the array on a later cycle, once it has room
  reg       sv;
  reg [7:0] sd;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial free  = 2'd2;
   initial hwm   = 2'd0;
  initial peak_q = 2'd0;
 initial hwm_b    = 2'd0;
 initial peak_sel = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
   initial vb0   = 1'b0;
   initial vb1   = 1'b0;
   initial cntb  = 2'd0;
   initial b0    = 8'h00;
   initial b1    = 8'h00;
  initial sv    = 1'b0;
  initial sd    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
  wire push_a  = push && !v1 && !vb0 && !sv;      // straight in when nothing is queued
  wire push_b  = push && !sv && !vb1 && !push_a;  // otherwise the word is staged
  wire land    = sv && !vb1;               // staged word enters the spill array
   wire refill  = vb0 && !v1;               // backlog moves up when a slot frees
   wire do_push = push_a || refill;         // head buffer write enable
    wire do_pop  = pop  &&  v0;
   wire [7:0] a_din  = push_a ? din : b0;
  // next-state occupancy of whichever stage the upstream is feeding; the
  // single shared comparator sees it one cycle later, through peak_q
  wire [1:0] count_nxt = count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
 wire [1:0] cntb_nxt  = cntb  + (land ? 2'd1 : 2'd0) - (refill ? 2'd1 : 2'd0);
 wire       vb0_nxt   = (land && !refill) ? 1'b1 :
                        (refill && !land) ? vb1  : vb0;
 wire       sv_nxt    = push_b ? 1'b1 : (land ? 1'b0 : sv);
 // the spill-side telemetry reports the whole spill path: the array plus a
 // word still waiting in the landing register
 wire [1:0] bklg_nxt  = cntb_nxt + (sv_nxt ? 2'd1 : 2'd0);
 wire [1:0] occ_nxt   = (vb0_nxt || sv_nxt) ? bklg_nxt : count_nxt;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            free  <= 2'd2;
           hwm   <= 2'd0;
          peak_q <= 2'd0;
         hwm_b    <= 2'd0;
         peak_sel <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
           vb0   <= 1'b0;
           vb1   <= 1'b0;
           cntb  <= 2'd0;
           b0    <= 8'h00;
           b1    <= 8'h00;
          sv    <= 1'b0;
          sd    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                   d0 <= a_din;
                    v0 <= 1'b1;
                end else begin
                   d1 <= a_din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
               d0 <= a_din;
            end

            count <= count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
            free  <= free  - (do_push ? 2'd1 : 2'd0) + (do_pop ? 2'd1 : 2'd0);

           // the spill stage preserves arrival order: it only takes a word
           // once the head buffer cannot, and it empties into the head first
          if (land && !refill) begin
               if (!vb0) begin
                  b0  <= sd;
                   vb0 <= 1'b1;
               end else begin
                  b1  <= sd;
                   vb1 <= 1'b1;
               end
          end else if (refill && !land) begin
               b0  <= b1;
               vb0 <= vb1;
               vb1 <= 1'b0;
          end else if (land && refill) begin
              b0 <= sd;
           end
          cntb <= cntb + (land ? 2'd1 : 2'd0) - (refill ? 2'd1 : 2'd0);

          // the landing register holds its word until the array can take it
          if (push_b) begin
              sd <= din;
              sv <= 1'b1;
          end else if (land) begin
              sv <= 1'b0;
          end

          peak_q <= occ_nxt;
         // the channel select tracks the spill stage: it engages when a word
         // spills and releases when the last spilled word is handed up
         if (push_b)
             peak_sel <= 1'b1;
        else if (refill && cntb == 2'd1 && !sv)
             peak_sel <= 1'b0;
         if (!peak_sel) begin
             if (peak_q > hwm)
                 hwm <= peak_q;
         end else begin
             if (peak_q > hwm_b)
                 hwm_b <= peak_q;
         end
        end
    end

   assign dout    = v0 ? d0 : {6'b0, ((hwm_b > hwm) ? hwm_b : hwm)};
    assign o_empty = !v0;
    assign o_full   = (free == 2'd0);
    assign o_count  = count;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);

    // ---- property: a push accepted last cycle must have gone into a buffer
    // ---- that both occupancy encodings called non-full
    always @(posedge clk)
        if (pv && $past(push) && !$past(v1))
            assert ($past(free) != 2'd0 && $past(count) != 2'd2);

   // ---- property: a cycle in which the upstream credit register reported no
   // ---- free slots must leave the peak occupancy telemetry pegged at two
   always @(posedge clk)
       if (pv && !$past(rst) && $past(free) == 2'd0)
           assert (hwm == 2'd2);
endmodule

module elastic_profile_buf (
    input wire       i_clk,
    input wire       i_rst,
    input wire       i_push,
    input wire       i_pop,
    input wire [7:0] i_data,
    output wire      o_valid,
    output wire      o_full,
    output wire [7:0] o_data,
output wire [2:0] o_count,
output reg [3:0] o_push_tally
);
    // Two-entry elastic buffer holding profiling samples.
    // Entry 0 is the head, entry 1 is the tail.  v0/v1 are the head/tail
    // occupancy flags; count is a separate occupancy register that is
    // maintained in parallel with the flags.
    reg       v0, v1;
    reg [7:0] d0, d1;
    reg [2:0] count;
   // Skid slot behind the tail.  o_full is raised as soon as the tail fills,
   // but one upstream beat may already be in flight, so it is absorbed here
   // and handed to the tail as soon as a pop frees it.
   reg       s_v;
   reg [7:0] s_d;
  // A second skid slot behind the first, so two beats that were already in
  // flight when full was reported can both be absorbed.  Both slots are
  // accounted for by the shared skid occupancy counter below.
  reg       s2_v;
  reg [7:0] s2_d;
 // A third skid stage, for the deepest case of three beats already in
 // flight when full was reported.  All three stages share the skid
 // occupancy counter and the free-stage credit below.
 reg       s3_v;
 reg [7:0] s3_d;
 // stages still free in the skid.  The accept term sits on the push path,
 // so it reads this counter instead of gathering the three stage flags.
 reg [1:0] sk_credit;
  // occupancy contributed by the skid slot, held apart from the core count
  reg [1:0] skid_occ;
 // the occupancy adder is retimed off the push path: a beat that has just
 // been written into a core slot has its unit of occupancy parked in
 // inc_pend for one cycle and is folded into count on the next edge
 reg       inc_pend;
// the skid-to-core hand-off is retimed the same way: the occupancy that
// leaves the skid counter on a drain is parked here for one cycle before it
// is folded into count
reg [1:0] xfer_pend;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;
   initial s_v   = 1'b0;
   initial s_d   = 8'h00;
  initial s2_v  = 1'b0;
  initial s2_d  = 8'h00;
 initial s3_v  = 1'b0;
 initial s3_d  = 8'h00;
 initial sk_credit = 2'd3;
  initial skid_occ = 2'd0;
 initial inc_pend = 1'b0;
initial xfer_pend = 2'd0;
initial o_push_tally = 4'd0;

    // "full" is decided purely by the tail flag
    wire w_full  = v1;
    wire do_push = i_push && !w_full;
    wire do_pop  = i_pop  && v0;
   // a beat arriving while full is taken by the skid slot, unless a pop is
   // freeing the tail this cycle, in which case it goes straight to the tail
  wire sk_push  = i_push && w_full && !do_pop && (sk_credit != 2'd0);
  wire do_skid  = sk_push && !s_v;
  // with the first slot already parked, the next beat queues behind it
 wire do_skid2 = sk_push && s_v && !s2_v;
 // the last free stage is taken by elimination once the first two are full
 wire do_skid3 = sk_push && s_v && s2_v;
  // a beat takes a core slot this cycle; its increment is deferred one edge
  wire core_join  = do_push || (do_pop && !s_v && i_push);
  // the head always vacates on a pop; that decrement is taken immediately
  wire core_leave = do_pop;
// on a drain the skid keeps only the slot that slides forward; the
// difference is the occupancy share migrating towards the core count
wire [1:0] skid_drain = (do_pop && s_v) ? (skid_occ - {1'b0, s2_v} - {1'b0, s3_v}) : 2'd0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
           s_v   <= 1'b0;
           s_d   <= 8'h00;
          s2_v  <= 1'b0;
          s2_d  <= 8'h00;
         s3_v  <= 1'b0;
         s3_d  <= 8'h00;
         sk_credit <= 2'd3;
          skid_occ <= 2'd0;
         inc_pend <= 1'b0;
        xfer_pend <= 2'd0;
o_push_tally <= 4'd0;
        end else if (do_push && do_pop) begin
            // head leaves, new sample becomes the head: occupancy unchanged
            d0    <= i_data;
        end else if (do_push) begin
            if (!v0) begin
                v0 <= 1'b1;
                d0 <= i_data;
            end else begin
                v1 <= 1'b1;
                d1 <= i_data;
            end
        end else if (do_pop) begin
            // tail slides down into the head slot
           v0 <= v1;
           d0 <= d1;
           if (s_v) begin
               // the parked skid sample takes the freed tail slot
               v1    <= 1'b1;
               d1    <= s_d;
              s_v   <= s2_v;
              s_d   <= s2_d;
             s2_v  <= s3_v;
             s2_d  <= s3_d;
             s3_v  <= 1'b0;
             // the skid loses one unit of occupancy here; it reaches count
             // one edge later through xfer_pend
            skid_occ <= {1'b0, s2_v} + {1'b0, s3_v};
            sk_credit <= sk_credit + 2'd1;
           end else if (i_push) begin
               // we reported full, so this beat lands in the freed tail
               v1 <= 1'b1;
               d1 <= i_data;
           end else begin
               v1    <= 1'b0;
           end
       end else if (do_skid) begin
           s_v   <= 1'b1;
           s_d   <= i_data;
          skid_occ <= skid_occ + 2'd1;
         sk_credit <= sk_credit - 2'd1;
      end else if (do_skid2) begin
          s2_v  <= 1'b1;
          s2_d  <= i_data;
         skid_occ <= skid_occ + 2'd1;
        sk_credit <= sk_credit - 2'd1;
     end else if (do_skid3) begin
         s3_v  <= 1'b1;
         s3_d  <= i_data;
        skid_occ <= skid_occ + 2'd1;
        sk_credit <= sk_credit - 2'd1;
      end
        // i_push = i_pop = 0 : the buffer idles, all state held
       if (!i_rst) begin
          count     <= count + {2'b00, inc_pend} - {2'b00, core_leave} + {1'b0, xfer_pend};
           inc_pend <= core_join;
          xfer_pend <= skid_drain;
       end
if (!i_rst && do_push)
    o_push_tally <= o_push_tally + 4'd1;
    end

    assign o_valid = v0;
    assign o_full  = w_full;
    assign o_data  = d0;
 assign o_count = count + {1'b0, skid_occ} + {2'b00, inc_pend} + {1'b0, xfer_pend};

    // P: whenever the buffer is not reporting full, the recorded occupancy
    // is at most one sample (the 3-bit register would allow up to 7).
    always @(posedge i_clk)
        if (!w_full)
            assert (count <= 3'd1);
endmodule

module token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle condition: nothing moves when low
    input  wire       req,
    output reg        grant_q,
   output reg [3:0]  tokens,
   output reg [3:0]  grant_ctr
);
    localparam [3:0] BURST  = 4'd12; // bucket cap
    localparam [3:0] REFILL = 4'd3;  // tokens added per timer tick
    localparam [2:0] PERIOD = 3'd4;  // refill timer top
   localparam [3:0] SOFT    = 4'd8; // tokens kept in the live bucket
   localparam [3:0] RESVMAX = 4'd6; // reserve pool cap
  localparam [3:0] LEASEMAX = 4'd2; // tokens leased ahead of the bucket

    reg [2:0] timer;
    reg       saw_refill;            // shadow: a refill tick has occurred
   // Overflow reserve: refill above SOFT is parked here instead of being
   // thrown away by the clamp, and trickles back one token at a time when
   // the live bucket runs dry.
   reg [3:0] resv;

   // Refill commit pipeline: the bucket adder/clamp is registered, so the
   // token target computed at a timer tick is applied four cycles later.
   // Layout of each stage: {valid, precomputed token target}.
   reg [4:0] rf_s1, rf_s2, rf_s3, rf_s4;
  // Reserve handoff register: the trickle out of the reserve pool is now
  // registered, so a token leaves resv on one enabled cycle and lands in
  // the live bucket on the next. Only one trickle is in flight at a time.
  reg       hand_v;
  reg [3:0] hand_tok;
 // Grant lease: every committed refill is split, with the first couple of
 // tokens parked in a tiny lease register that serves requests ahead of the
 // live bucket, so a grant never has to wait behind the bucket adder.
 reg [3:0] lease;
// Distractor telemetry: enabled-cycle and grant counters (observability only).
reg [3:0] ce_ctr;

    wire       tick     = (timer == PERIOD);
   wire       do_grant = ce && req && ((tokens != 4'd0) || (lease != 4'd0));
    wire [4:0] sum      = {1'b0, tokens} + {1'b0, REFILL};
    wire [3:0] refilled = (sum > {1'b0, BURST}) ? BURST : sum[3:0];
   wire       commit   = rf_s4[4];
   wire [3:0] target   = rf_s4[3:0];
  wire [3:0] eff_target = (target > SOFT) ? SOFT : target;
  wire [3:0] excess     = (target > SOFT) ? (target - SOFT) : 4'd0;
  wire [4:0] resv_sum   = {1'b0, resv} + {1'b0, excess};
wire [3:0] lease_room = LEASEMAX - lease;
wire [3:0] lease_add  = (eff_target >= lease_room) ? lease_room : eff_target;
wire [3:0] bucket_tgt = eff_target - lease_add;
wire       gl         = do_grant && (lease != 4'd0);
wire       gb         = do_grant && (lease == 4'd0);
 wire [3:0] hand_amt   = (resv >= 4'd2) ? 4'd2 : 4'd1;
wire       drain      = !commit && (tokens == 4'd0) && (lease == 4'd0) && (resv != 4'd0) && !hand_v;

    initial begin
        timer      = 3'd0;
        tokens     = 4'd0;
        saw_refill = 1'b0;
       resv       = 4'd0;
        grant_q    = 1'b0;
       rf_s1      = 5'd0;
       rf_s2      = 5'd0;
       rf_s3      = 5'd0;
       rf_s4      = 5'd0;
      hand_v     = 1'b0;
      hand_tok   = 4'd0;
     lease      = 4'd0;
     ce_ctr     = 4'd0;
     grant_ctr  = 4'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            timer      <= 3'd0;
            tokens     <= 4'd0;
            saw_refill <= 1'b0;
           resv       <= 4'd0;
            grant_q    <= 1'b0;
           rf_s1      <= 5'd0;
           rf_s2      <= 5'd0;
           rf_s3      <= 5'd0;
           rf_s4      <= 5'd0;
          hand_v     <= 1'b0;
          hand_tok   <= 4'd0;
         lease      <= 4'd0;
         ce_ctr     <= 4'd0;
         grant_ctr  <= 4'd0;
        end else if (ce) begin
            timer   <= tick ? 3'd0 : (timer + 3'd1);
            grant_q <= do_grant;

           // stage the refill: capture the clamped target at the tick and
           // walk it down the pipeline, one stage per enabled cycle
           rf_s1 <= {tick, refilled};
           rf_s2 <= rf_s1;
           rf_s3 <= rf_s2;
           rf_s4 <= rf_s3;

          // post the trickle amount now; it is deposited in the bucket on
          // the next enabled cycle
          hand_v   <= drain;
          hand_tok <= drain ? hand_amt : 4'd0;

            if (tick)
                saw_refill <= 1'b1;

           case ({commit, gb})
             2'b10:   tokens <= bucket_tgt;
                2'b01:   tokens <= tokens - 4'd1;
             2'b11:   tokens <= (bucket_tgt == 4'd0) ? 4'd0 : (bucket_tgt - 4'd1);
              default: tokens <= hand_v ? hand_tok : tokens;
            endcase

         // lease bookkeeping: take its slice of the committed refill, and
         // give a token back whenever it is the one serving the grant
         if (commit)
             lease <= gl ? (lease + lease_add - 4'd1) : (lease + lease_add);
         else if (gl)
             lease <= lease - 4'd1;

          // reserve bookkeeping: soak up the clamped surplus, or hand one
          // token back to the live bucket when it has emptied out
          if (commit)
              resv <= (resv_sum > {1'b0, RESVMAX}) ? RESVMAX : resv_sum[3:0];
          else if (drain)
             resv <= resv - hand_amt;

         // telemetry counters: wrap freely, observed only on the new port
         ce_ctr    <= ce_ctr + 4'd1;
         grant_ctr <= do_grant ? (grant_ctr + 4'd1) : grant_ctr;
        end
    end

    // Precedence: a registered grant can only be observed if a refill tick
    // was recorded earlier in the shadow bit.
    always @(posedge clk)
        if (grant_q)
            assert (saw_refill);

endmodule

// Gray-coded write pointer crossing into a destination domain through a
// two-flop synchronizer, with a shadow binary pipeline kept alongside the
// synchronizer stages and a monitor that records the Hamming distance between
// the two most recent samples of the pointer.
module gray_cdc_skew_monitor (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable / idle
    input  wire       i_incr,    // source pointer advance
    output reg        armed,     // sticky: a pointer change has been observed
output reg  [2:0] last_delta, // bits differing between the last two samples
output reg  [3:0] o_idle_count // distractor: destination-domain activity meter
);

    // source-domain binary pointer and its gray encoding
    reg  [3:0] wbin;

   // Four-deep source-domain retiming pipeline.  The pointer counter sits at
   // the far end of the block from the launch flops, so the binary pointer is
   // carried over in four registered hops; the gray encoder is placed at the
   // last hop so both synchronizer chains launch from the same retimed value.
   reg  [3:0] p1, p2, p3, p4;
   wire [3:0] pgray = p4 ^ (p4 >> 1);

    // two-flop synchronizer carrying the gray pointer
    reg  [3:0] sync1, sync2;

   // second consumer's synchronizer chain onto the same gray pointer
   reg  [3:0] s1b, s2b;

    // shadow binary pipeline, one stage per synchronizer flop
    reg  [3:0] b1, b2;
   reg  [3:0] b1b, b2b;

   // round-robin refresh phase: 0 refreshes chain A, 1 refreshes chain B.
// Advances are no longer pinned to a phase: the issue pacer below spaces
// launches apart in time, which is what bounds either chain to a single
// gray transition between two of its own samples.
   reg        phase;
  // Programmable pointer depth.  The wrap modulus is carried as a mask that
  // is always one less than a power of two; it is widened one bit at a time
  // by i_incr pulses while the destination domain is parked (i_ce low).
  // Moving the wrap point invalidates everything already in flight, so a
  // depth change also drains the pointer and both synchronizer shadows.
  reg  [3:0] wrap_mask;

 // Issue/retire ledger for pointer advances.  n_issue logs advances pushed
 // into the source pointer, n_retire logs advances absorbed by the chain-A
 // shadow stage.  Both are plain free-running event counters that wrap at
 // four bits; only their difference is meaningful.
 reg  [3:0] n_issue;
 reg  [3:0] n_retire;

// Issue pacing.  gap_min is the programmed minimum number of destination
// cycles between two pointer advances and space_cnt counts the cycles since
// the last one, saturating once the pointer has been quiet for a while.
// Pacing the launches keeps the retiming chain from carrying two advances
// back to back, which is what the old fixed one-outstanding credit did.
reg  [2:0] gap_min;
reg  [2:0] space_cnt;

// Distractor bookkeeping: counts accepted advance pulses and bleeds down
// while the destination domain is parked.  Purely observational.
reg  [3:0] idle_count;

    initial begin
        wbin       = 4'd0;
       p1         = 4'd0;
       p2         = 4'd0;
       p3         = 4'd0;
       p4         = 4'd0;
        sync1      = 4'd0;
        sync2      = 4'd0;
        b1         = 4'd0;
        b2         = 4'd0;
       s1b        = 4'd0;
       s2b        = 4'd0;
       b1b        = 4'd0;
       b2b        = 4'd0;
       phase      = 1'b0;
      wrap_mask  = 4'd1;
     n_issue    = 4'd0;
     n_retire   = 4'd0;
gap_min    = 3'd1;
space_cnt  = 3'd7;
idle_count = 4'd0;
o_idle_count = 4'd0;
        armed      = 1'b0;
        last_delta = 3'd0;
    end

    // combinational Hamming distance between the two synchronizer stages
    wire [3:0] xr = sync1 ^ sync2;
    wire [2:0] delta = {2'b00, xr[0]} + {2'b00, xr[1]} +
                       {2'b00, xr[2]} + {2'b00, xr[3]};

   // the same distance measure for the second chain
   wire [3:0] xrb = s1b ^ s2b;
   wire [2:0] delta_b = {2'b00, xrb[0]} + {2'b00, xrb[1]} +
                        {2'b00, xrb[2]} + {2'b00, xrb[3]};

   // one skew monitor is shared by both chains; it reports whichever chain
   // was refreshed on this phase
   wire [2:0] delta_mux = phase ? delta_b : delta;
   wire       skew_mux  = phase ? (s1b != s2b) : (sync1 != sync2);
  // depth reconfiguration is only accepted while the destination domain is
  // idle, and only up to the full four-bit pointer range
  wire       cfg_widen = !i_ce && i_incr && (wrap_mask != 4'd15);
 // once the pointer is at full depth the same parked pulses step the
 // issue-interval field instead of the mask; the field wraps back to one
 wire       cfg_pace  = !i_ce && i_incr && (wrap_mask == 4'd15);
// the ledger no longer gates issue; it only reports that an advance is
// somewhere between the pointer and the launch tap
 wire       ledger_busy = (n_issue != n_retire);
// pacing interlock: the previous launch must have had gap_min destination
// cycles to walk clear of the first retiming hop before another is issued
wire       pace_ok     = (space_cnt >= gap_min);
wire       ptr_adv     = i_ce && i_incr && pace_ok;
// an advance retires once it has cleared the last retiming hop and is
// therefore visible to whichever chain refreshes next
wire       shadow_adv  = i_ce && (p3 != p4);

    always @(posedge clk) begin
       if (cfg_widen) begin
           // new wrap point: grow the mask and drain the pointer pipeline
           wrap_mask <= (wrap_mask << 1) | 4'd1;
           wbin      <= 4'd0;
          p1        <= 4'd0;
          p2        <= 4'd0;
          p3        <= 4'd0;
          p4        <= 4'd0;
           sync1     <= 4'd0;
           sync2     <= 4'd0;
           b1        <= 4'd0;
           b2        <= 4'd0;
           s1b       <= 4'd0;
           s2b       <= 4'd0;
           b1b       <= 4'd0;
           b2b       <= 4'd0;
          n_issue   <= 4'd0;
          n_retire  <= 4'd0;
         space_cnt <= 3'd0;
      end else if (cfg_pace) begin
          // interval field steps and wraps back to its minimum of one
          gap_min <= (gap_min == 3'd7) ? 3'd1 : gap_min + 3'd1;
       end else if (i_ce) begin
            // source pointer
         wbin  <= (wbin + (ptr_adv ? 4'd1 : 4'd0)) & wrap_mask;

           // retiming hops toward the launch point
           p1 <= wbin;
           p2 <= p1;
           p3 <= p2;
           p4 <= p3;

           // ledger: log both sides of the advance
         n_issue  <= n_issue  + (ptr_adv    ? 4'd1 : 4'd0);
         n_retire <= n_retire + (shadow_adv ? 4'd1 : 4'd0);

           // issue pacer: restart on a launch, saturate while quiet
        if (ptr_adv)
            space_cnt <= 3'd0;
        else if (space_cnt != 3'd7)
            space_cnt <= space_cnt + 3'd1;

            // synchronizer chain
           if (!phase) begin
              sync1 <= pgray;
               sync2 <= sync1;
           end else begin
              s1b   <= pgray;
               s2b   <= s1b;
           end

            // shadow binary chain, structurally parallel to the chain above
           if (!phase) begin
              b1    <= p4;
               b2    <= b1;
           end else begin
              b1b   <= p4;
               b2b   <= b1b;
           end

            // monitor
           last_delta <= delta_mux;
           phase      <= ~phase;

            // Q: first time the two stages disagree, i.e. a pointer update is
            // in flight through the synchronizer.  Sticky, never cleared.
          if (skew_mux || ledger_busy)
                armed <= 1'b1;
        end
    end

   // ---- distractor: activity meter, independent of the pointer pipeline ----
   always @(posedge clk) begin
       if (i_ce && i_incr) begin
           if (idle_count != 4'd15)
               idle_count <= idle_count + 4'd1;
       end else if (!i_ce && idle_count != 4'd0) begin
           idle_count <= idle_count - 4'd1;
       end
       o_idle_count <= idle_count;
   end

    // P: once a pointer change has been seen, every recorded sample-to-sample
    // distance is at most one bit (gray-code single-bit transition).
    assert property (!armed || last_delta <= 3'd1);

endmodule

module prio_grant_tracker (
    input  wire       clk,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [3:0] req,
    output reg        vld,     // registered valid: idx meaningful only while set
    output reg  [1:0] idx,     // encoded winner index
    output reg  [3:0] oh,      // registered one-hot grant
    output reg        ack_lo,  // low-half acknowledge, derived from idx
    output reg        ack_hi,  // high-half acknowledge, derived from one-hot
output reg        armed,   // sticky: set the first time a request is taken
output reg  [3:0] n_take,  // ledger: leases issued  (free-running, wraps)
output reg  [3:0] n_drop,  // ledger: leases retired (free-running, wraps)
output reg        stale,   // standing lease has burned one idle cycle
output reg  [3:0] req_seen // sticky union of newly-arriving request bits
);

    // combinational priority encoder (lowest index wins)
    wire       any = |req;
    wire [1:0] enc = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;
    wire [3:0] iso = req & (~req + 4'd1);   // isolate lowest set bit
   // retirements are booked by half: a low-half holder settles into n_drop,
   // a high-half holder into its own column, so the two halves of the
   // ledger can be read out independently
   reg [3:0] n_drop_hi;
   // issues are booked the same way: the winner's half decides which
   // take column advances, so each half's lease traffic can be metered
   // straight off the ledger
   reg [3:0] n_take_hi;
   // channel B: a second lease register set.  Both channels drive the same
   // downstream consumer, so they share the ledger columns and the
   // acknowledge outputs; `turn` alternates which channel is offered the
   // next fresh lease.
   reg        vld_b;
   reg  [1:0] idx_b;
   reg  [3:0] oh_b;
   reg        stale_b;
   reg        turn;
// shadow copy of the previous request vector, used for edge detection only
reg [3:0] req_prev;

   // the ledger, not vld, is the authority on lease occupancy
  wire [3:0] n_ret       = n_drop + n_drop_hi;
 wire [3:0] n_iss       = n_take + n_take_hi;
 wire       outstanding = (n_iss != n_ret);

    initial begin
        vld    = 1'b0;
        idx    = 2'd0;
        oh     = 4'b0000;
        ack_lo = 1'b0;
        ack_hi = 1'b0;
        armed  = 1'b0;
n_take = 4'd0;
       n_take_hi = 4'd0;
n_drop = 4'd0;
       n_drop_hi = 4'd0;
stale  = 1'b0;
req_seen  = 4'd0;
req_prev  = 4'd0;
       vld_b   = 1'b0;
       idx_b   = 2'd0;
       oh_b    = 4'b0000;
       stale_b = 1'b0;
       turn    = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            // acknowledge flags are built from the *previous* grant state:
            // one path reads the index, the other reads the one-hot vector
// bookkeeping only: remember which request lines have newly arrived
req_prev <= req;
req_seen <= req_seen | (req & ~req_prev);
           ack_lo <= (vld   && (idx   < 2'd2)) ||
                     (vld_b && (idx_b < 2'd2));
           ack_hi <= (vld   && (oh[3]   || oh[2])) ||
                     (vld_b && (oh_b[3] || oh_b[2]));

            if (any) begin
               // a request refreshes the standing lease on its own channel
                armed <= 1'b1;
                if (!outstanding) begin
                    // ledger is square: issue a fresh lease to the winner
                   // and hand the bus to whichever channel has the turn
                   turn <= ~turn;
                   if (turn) begin
                       vld_b   <= 1'b1;
                       stale_b <= 1'b0;
                       idx_b   <= enc;
                       oh_b    <= iso;
                   end else begin
                       vld   <= 1'b1;
                       stale <= 1'b0;
                       idx   <= enc;
                       oh    <= iso;
                   end
                  if (enc[1]) n_take_hi <= n_take_hi + 4'd1;
                  else        n_take    <= n_take    + 4'd1;
               end else if (vld_b) begin
                   // channel B is the holder: refreshed in place, and it
                   // yields the bus to a higher-priority requester
                   stale_b <= 1'b0;
                   if (enc < idx_b) begin
                       idx_b <= enc;
                       oh_b  <= iso;
                   end
               end else begin
                   // channel A is the holder
                   vld   <= 1'b1;
                   stale <= 1'b0;
                   if (enc < idx) begin
                    // lease already in flight: a higher-priority requester
                    // takes it over in place -- a hand-off, not a new lease,
                    // so the ledger does not move
                    idx <= enc;
                    oh  <= iso;
                end
               end
                // otherwise the current holder keeps the bus
            end else if (outstanding) begin
               if (vld_b) begin
                   if (stale_b) begin
                       // channel B retires into the shared drop columns
                       vld_b   <= 1'b0;
                       stale_b <= 1'b0;
                       if (idx_b[1]) n_drop_hi <= n_drop_hi + 4'd1;
                       else          n_drop    <= n_drop    + 4'd1;
                   end else begin
                       idx_b   <= idx_b + 2'd1;
                       oh_b    <= {oh_b[2:0], oh_b[3]};
                       stale_b <= 1'b1;
                   end
               end else if (stale) begin
                    // second idle cycle retires the lease; the one-hot is
                    // left parked as a record of the last holder
                    vld    <= 1'b0;
                    stale  <= 1'b0;
                   if (idx[1]) n_drop_hi <= n_drop_hi + 4'd1;
                   else        n_drop    <= n_drop    + 4'd1;
                end else begin
                    // first idle cycle: age the standing grant round-robin
                    idx   <= idx + 2'd1;
                    oh    <= {oh[2:0], oh[3]};
                    stale <= 1'b1;
                end
            end
        end
    end

    // P: once the tracker has ever accepted a request, the low-half and
    // high-half acknowledges are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(ack_lo && ack_hi));

endmodule

module histogram_sampler (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // sample-enable; low => whole histogram idles
    input  wire [1:0] i_sel,     // which bin the incoming sample lands in
    output reg  [3:0] bin0,
    output reg  [3:0] bin1,
    output reg  [3:0] bin2,
    output reg  [3:0] bin3,
    output reg  [3:0] total,
output wire       o_full,
output reg  [3:0] ce_ticks,
output reg  [3:0] n_in,
output reg  [3:0] n_out,
output reg  [3:0] sel_trace
);
    // sampling window closes after MAXS samples have been binned
    localparam [3:0] MAXS = 4'd12;

   // run-length coalescing: consecutive samples aimed at one bin are counted
   // here and folded into that bin register with a single add
   localparam [1:0] PMAX = 2'd3;

   reg [1:0] pend;      // samples staged but not yet folded into a bin
   reg [1:0] pend_sel;  // bin the staged samples belong to
  // the bin write port is clock-gated with i_ce: a coalesced run is queued
  // here and lands in its bin on the next enabled beat
  reg [3:0] fq;        // run awaiting write-back (0 => queue empty)
  reg [1:0] fq_sel;    // bin the queued run belongs to
reg [1:0] sel_prev;  // last observed bin selector (diagnostic only)

    initial bin0  = 4'd0;
    initial bin1  = 4'd0;
    initial bin2  = 4'd0;
    initial bin3  = 4'd0;
    initial total = 4'd0;
   initial pend     = 2'd0;
   initial pend_sel = 2'd0;
  initial fq     = 4'd0;
  initial fq_sel = 2'd0;
initial ce_ticks = 4'd0;
initial n_in  = 4'd0;
initial n_out = 4'd0;
initial sel_prev  = 2'd0;
initial sel_trace = 4'd0;

    assign o_full = (total == MAXS);

    wire take = i_ce && (total < MAXS);
   wire same  = (i_sel == pend_sel);
   // window already shut: commit whatever is still staged on the next beat
   wire drain = i_ce && !take;
   wire fold  = (pend != 2'd0) && (drain || (take && (!same || pend == PMAX)));
// in/out sample ledger: samples presented minus samples retired is the
// number still sitting in the staging accumulator
wire [3:0] staged   = n_in - n_out;
// one add commits the whole staged run, plus the in-flight sample when it
// coalesces into the same bin
wire [3:0] fold_amt = staged + ((take && same) ? 4'd1 : 4'd0);
// samples leaving staging this beat: those folded into a bin, plus the
// sample dropped on the floor once the window has shut
wire [3:0] retire   = (fold ? fold_amt : 4'd0) + (drain ? 4'd1 : 4'd0);
// the queued run is written back only on an enabled beat
wire wb = i_ce && (fq != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 4'd0;
           pend     <= 2'd0;
           pend_sel <= 2'd0;
           fq       <= 4'd0;
           fq_sel   <= 2'd0;
ce_ticks <= 4'd0;
n_in     <= 4'd0;
n_out    <= 4'd0;
sel_prev  <= 2'd0;
sel_trace <= 4'd0;
       end else begin
          if (wb) begin
              case (fq_sel)
2'd0: bin0 <= bin0 + fq;
2'd1: bin1 <= bin1 + fq;
2'd2: bin2 <= bin2 + fq;
2'd3: bin3 <= bin3 + fq;
               endcase
           end
          if (i_ce) begin
              fq <= fold ? fold_amt : 4'd0;
              if (fold)
                  fq_sel <= pend_sel;
          end
           if (take) begin
               pend_sel <= i_sel;
               pend     <= same ? ((pend == PMAX) ? 2'd0 : pend + 2'd1)
                                : 2'd1;
               total    <= total + 4'd1;
           end else if (drain) begin
               pend <= 2'd0;
           end
if (i_ce && ce_ticks != 4'd15)
    ce_ticks <= ce_ticks + 4'd1;
// ledger is pure accounting: it wraps, it is never held off
n_in  <= n_in  + (i_ce ? 4'd1 : 4'd0);
n_out <= n_out + retire;
sel_prev <= i_sel;
if (i_ce && (i_sel != sel_prev) && sel_trace != 4'd15)
    sel_trace <= sel_trace + 4'd1;
       end
    end

    // P: no single bin's occupancy can ever exceed the sampling-window size,
    // even though the 4-bit bin register could physically hold 15.
    always @(*)
        assert (bin1 <= MAXS);
endmodule

module axi_grant_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire [3:0] req,
    input  wire       done,
    output reg        gnt_valid,
    output reg [1:0]  gnt_idx,
    output reg [2:0]  timer,
    output reg [2:0]  elapsed,
output wire [3:0] o_gnt,
output reg [3:0]  req_hist,
output reg [3:0]  n_iss,
output reg [3:0]  n_ret
);
    // Latency budget granted to an accepted request.
localparam [2:0] BUDGET_MAX = 3'd5;
localparam [2:0] BUDGET_MIN = 3'd3;

// Adaptive latency allowance. A slave that times out earns one extra
// credit for the next requester; a slave that answers within a cycle
// gives one back. Only rewritten in the gap between grants.
reg [2:0] budget;
// Latency of the most recently completed transaction, in cycles. Feeds
// the budget hysteresis below: the window is only narrowed after two
// quick responses in a row, so a single lucky slave cannot starve the
// next requester.
reg [2:0] last_lat;
// Contention ceiling. Under sustained backpressure (four consecutive
// cycles with an unserved request) the arbiter advertises a tighter
// maximum window so the request queue can drain; once the history
// clears it relaxes the ceiling again, one credit per idle cycle.
reg [2:0] cap;

    // ---------------------------------------------------------------
    // Priority encoder over the request vector: lowest index wins.
    // The encoded index is only meaningful while gnt_valid is set.
    // ---------------------------------------------------------------
    wire       enc_valid = |req;
    wire [1:0] enc_idx   = req[0] ? 2'd0 :
                           req[1] ? 2'd1 :
                           req[2] ? 2'd2 : 2'd3;

    // Retirement of the outstanding grant: either the slave answered,
    // or the budget has been fully consumed.
// Outstanding-transaction ledger: n_iss logs every grant handed to the
// interconnect, n_ret logs every grant given back. Both wrap freely.
// A response is only honoured while the ledger still shows an issued,
// unreturned beat, so a stray done pulse on the response channel is
// dropped instead of retiring a grant that was never logged.
wire ledger_busy = (n_iss != n_ret);
wire retire = gnt_valid && ledger_busy && (done || ((elapsed == (budget - 3'd1)) && (timer == 3'd1)));

   // Next advertised window, and the allowance actually handed out once
   // the running budget has been clamped into that window.
   wire [2:0] cap_next = (req_hist == 4'b1111) ? ((cap == BUDGET_MIN) ? BUDGET_MIN : cap - 3'd1) :
                         (req_hist == 4'b0000) ? ((cap == BUDGET_MAX) ? BUDGET_MAX : cap + 3'd1) :
                                                 cap;
   wire [2:0] alloc    = (budget > cap_next) ? cap_next : budget;

    assign o_gnt = gnt_valid ? (4'b0001 << gnt_idx) : 4'b0000;

    initial gnt_valid = 1'b0;
    initial gnt_idx   = 2'd0;
    initial timer     = 3'd0;
    initial elapsed   = 3'd0;
initial budget    = BUDGET_MAX;
initial last_lat  = 3'd0;
initial cap       = BUDGET_MAX;
initial req_hist  = 4'd0;
initial n_iss     = 4'd0;
initial n_ret     = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            gnt_valid <= 1'b0;
            gnt_idx   <= 2'd0;
            timer     <= 3'd0;
            elapsed   <= 3'd0;
budget    <= BUDGET_MAX;
last_lat  <= 3'd0;
cap       <= BUDGET_MAX;
req_hist  <= 4'd0;
n_iss     <= 4'd0;
n_ret     <= 4'd0;
        end else if (i_ce) begin
req_hist <= {req_hist[2:0], (|req) & ~done};
            if (!gnt_valid) begin
               cap    <= cap_next;
               budget <= alloc;
                if (enc_valid) begin
                    gnt_valid <= 1'b1;
                    gnt_idx   <= enc_idx;
                   timer     <= alloc;    // credits left, clamped to window
                    elapsed   <= 3'd0;     // cycles burnt
n_iss     <= n_iss + 4'd1;
                end
            end else if (retire) begin
                gnt_valid <= 1'b0;
n_ret     <= n_ret + 4'd1;
                timer     <= 3'd0;
                elapsed   <= 3'd0;
last_lat  <= elapsed;
if (!done)
   budget <= (budget >= cap) ? cap : budget + 3'd1;
else if ((elapsed <= 3'd1) && (last_lat <= 3'd1))
    budget <= (budget == BUDGET_MIN) ? BUDGET_MIN : budget - 3'd1;
            end else begin
                timer   <= timer   - 3'd1;
                elapsed <= elapsed + 3'd1;
            end
        end
    end

    // Bounded response, safety form: the countdown must never reach zero
    // while a grant is still outstanding ...
    always @(posedge clk)
        assert (!gnt_valid || (timer != 3'd0));

    // ... and the elapsed-cycle counter must never run past the budget
    // window while a grant is still outstanding.
    always @(posedge clk)
        assert (!gnt_valid || (elapsed <= 3'd4));

   // Latency monitor: the recorded latency of the last completed
   // transaction always fits strictly inside the widest window the
   // arbiter can hand out, and an outstanding grant never carries more
   // credits than that window either.
   always @(posedge clk)
       assert ((last_lat < BUDGET_MAX) && (!gnt_valid || (timer <= BUDGET_MAX)));
endmodule

module pdk_reqtrack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_arm,     // Q event: arms the tracker (sticky)
    input  wire       i_launch,  // start step: issue a request into the array
    output wire       o_retire,  // finish step: request leaves last stage
    output wire [2:0] o_inflight
);
    parameter STAGES = 4;

    // shift register tracking in-flight requests through the stage array
    reg [STAGES-1:0] pipe;
   // peer short path: a second, two-stage request array. Accepted launches
   // alternate between the long array and this one to balance occupancy.
   reg [1:0]        pipe_b;
    // separate count of set bits in that shift register
    reg [2:0]        cnt;
   // issue/retire ledger: n_in logs each request leaving the issue stage,
   // n_out logs each request completing. Both wrap at three bits; the
   // reported in-flight count is simply their balance.
   reg [2:0]        n_in;
   reg [2:0]        n_out;
    // sticky arm register (scope): set the first time i_arm is seen, never cleared
    reg              armed;
    // sticky record that a start actually happened after arming
    reg              started;
   // issue stage: an accepted launch is held here for one cycle (address
   // decode) before it is written into the stage array
   reg              ln_stage;
  // target lane of the request held in the issue stage (0 = long, 1 = short)
  reg              ln_tag;
  // round-robin lane pointer applied to the next accepted launch
  reg              rr;
// express lane: a request issued while the stage array is completely idle
// bypasses the array and completes one cycle later
reg              xpr;

    initial pipe    = {STAGES{1'b0}};
   initial pipe_b  = 2'b00;
    initial cnt     = 3'd0;
   initial n_in    = 3'd0;
   initial n_out   = 3'd0;
    initial armed   = 1'b0;
    initial started = 1'b0;
   initial ln_stage = 1'b0;
  initial ln_tag   = 1'b0;
  initial rr       = 1'b0;
initial xpr      = 1'b0;

    // a launch is only accepted once the tracker has been armed
    wire accept = i_ce && i_launch && armed;
  // the issue stage takes the express lane only when both arrays are empty
  wire xpr_take = ln_stage && (pipe == {STAGES{1'b0}}) && (pipe_b == 2'b00);
 // ledger next values: one issue event per decoded launch, one completion
 // event per request leaving an array exit or the express lane
 wire [2:0] n_in_nxt  = n_in  + (ln_stage ? 3'd1 : 3'd0);
 wire [2:0] n_out_nxt = n_out + (pipe[STAGES-1] ? 3'd1 : 3'd0)
                              + (pipe_b[1] ? 3'd1 : 3'd0)
                              + (xpr ? 3'd1 : 3'd0);
  wire retire = i_ce && (pipe[STAGES-1] || pipe_b[1] || xpr);

    assign o_retire   = retire;
    assign o_inflight = cnt;

    always @(posedge clk) begin
        if (rst) begin
            pipe    <= {STAGES{1'b0}};
           pipe_b  <= 2'b00;
            cnt     <= 3'd0;
           n_in    <= 3'd0;
           n_out   <= 3'd0;
            armed   <= 1'b0;
            started <= 1'b0;
           ln_stage <= 1'b0;
          ln_tag   <= 1'b0;
          rr       <= 1'b0;
           xpr      <= 1'b0;
        end else if (i_ce) begin
         pipe    <= { pipe[STAGES-2:0], ln_stage && !ln_tag && !xpr_take };
         pipe_b  <= { pipe_b[0],        ln_stage &&  ln_tag && !xpr_take };
        n_in    <= n_in_nxt;
        n_out   <= n_out_nxt;
        cnt     <= n_in_nxt - n_out_nxt;
            armed   <= armed || i_arm;
            started <= started || (i_launch && armed);
           ln_stage <= i_launch && armed;
          ln_tag   <= rr;
          rr       <= rr ^ (i_launch && armed);
          xpr     <= xpr_take;
        end
    end

    // Chain precedence, after the sticky arm: while armed, the tracker can never
    // report outstanding work unless a start was really accepted first.
    always @(posedge clk)
        if (armed && (cnt != 3'd0))
            assert (started);

    // Retire/issue provenance: a request can only be observed leaving the last
    // stage, or waiting in the issue stage for address decode, if it entered
    // through an accepted start, which in turn can only happen after arming.
    always @(posedge clk)
        if (o_retire || ln_stage)
            assert (started && armed);

endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       issue,     // new operation issued this advance
    output wire       o_retire,  // fixed-latency result leaving the unit
    output wire [2:0] o_occ
);
// 3-deep shift register feeding a registered writeback stage:
// bit k = op issued k advances ago
reg [2:0] pipe;
    // occupancy: incremented on issue, decremented when the tail drains
    reg [2:0] occ;
    // sticky arm: set the first time an operation is ever issued
    reg       armed;
// registered result stage: the final latency slot lives here
reg       wb;
// second beat of the narrow result bus; the pipe cannot advance during it
reg       beat;
// credit-based issue throttle: free slots in the 4-stage result path
reg [2:0] credit;
// return ledger: every accepted issue and every writeback return is logged
// so credits lost to a dropped return can be recovered at a drain point
reg [2:0] n_iss;
reg [2:0] n_ret;
// return staging: a slot freed by writeback waits here until the pool's
// single write port is free (an advance that takes no issue) to rejoin credit
reg [2:0] rtn;
// reserve bank: the return path is two-stage. Staging hands a freed slot to
// the bank, and the bank releases it into the pool on a later advance. The
// bank is single-ported, so it cannot be read on a cycle it is written.
reg [2:0] resv;

initial pipe  = 3'b000;
    initial occ   = 3'd0;
    initial armed = 1'b0;
initial wb    = 1'b0;
initial beat  = 1'b0;
initial credit = 3'd4;
initial n_iss = 3'd0;
initial n_ret = 3'd0;
initial rtn   = 3'd0;
initial resv  = 3'd0;
wire adv = i_ce && !beat;
// an issue is only taken when the unit still has a free slot
wire acc = issue && (credit != 3'd0);
// ledger view of the unit: nothing issued is still outstanding
wire drained = (n_iss == n_ret);
// an accepted issue owns the credit write port; returns fold back behind it
wire fold = (rtn != 3'd0) && !acc;
// the bank may release a credit only when it is not taking a hand-off
wire lend = (resv != 3'd0) && !acc && !fold;

assign o_retire = adv && wb;
    assign o_occ    = occ;

    always @(posedge clk) begin
        if (rst) begin
pipe  <= 3'b000;
            occ   <= 3'd0;
            armed <= 1'b0;
wb    <= 1'b0;
beat  <= 1'b0;
credit <= 3'd4;
n_iss <= 3'd0;
n_ret <= 3'd0;
rtn   <= 3'd0;
resv  <= 3'd0;
end else begin
if (adv) begin
pipe <= {pipe[1:0], acc};
wb   <= pipe[2];
occ    <= occ    + (acc ? 3'd1 : 3'd0) - (wb ? 3'd1 : 3'd0);
// a drained ledger means the pool owes nothing: re-sync it to full
credit <= drained ? (3'd4 - (acc ? 3'd1 : 3'd0))
: (credit - (acc ? 3'd1 : 3'd0) + (lend ? 3'd1 : 3'd0));
rtn    <= drained ? 3'd0
                  : (rtn - (fold ? 3'd1 : 3'd0) + (wb ? 3'd1 : 3'd0));
resv   <= drained ? 3'd0
                 : (resv + (fold ? 3'd1 : 3'd0) - (lend ? 3'd1 : 3'd0));
n_iss  <= n_iss + (acc ? 3'd1 : 3'd0);
n_ret  <= n_ret + (wb  ? 3'd1 : 3'd0);
if (acc)
                armed <= 1'b1;
end
if (i_ce)
beat <= !beat && wb;
        end
    end

    // P: once the unit has ever issued, at most 4 operations are in flight.
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd4);

   // P2: a result waiting in writeback means the credit pool is not full.
   always @(posedge clk)
       assert (!wb || credit <= 3'd3);
endmodule

module dma_burst_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // engine clock-enable / idle when low
    input  wire       i_start,   // Q: opens the transfer window
    input  wire [3:0] i_len,     // burst length in beats
    input  wire       i_ack,     // R: closes the transfer window
    output wire       o_busy,
output wire       o_drained,
output reg  [3:0] o_ack_cnt,
output reg  [3:0] o_dbg_tick
);

    // beats-remaining counter and the two status flags derived from it
    reg [3:0] beats_left;
    reg       busy;
    reg       drained;

    // window register: set by a new burst (Q), cleared by the ack (R)
    reg       win;

    // commit-stage register: the next beat count is held here for one cycle
    // before it is written into the beats-remaining counter
    reg [3:0] stg_beats;
    reg       stg_vld;

   // unpipelined shadow of the beats-remaining count: the issue stage keeps
   // its own copy so downstream flow control does not have to wait a cycle
   // for the commit stage to update beats_left
   reg [3:0] shadow;

  // registered copy of the ack input (status only)
   reg       ack_seen;

  // window ledger: one counter logs every transfer window that opens, the
  // other logs every window that closes.  The pair is exported as the
  // status word so a host can audit descriptor/ack pairing; both wrap.
  reg [1:0] n_win_opn;
  reg [1:0] n_win_cls;
// debug telemetry: free-running tick counter, status only
reg [3:0] ce_ticks;

  // window events, shared by the window register and the ledger
  wire win_set = i_start && !busy;
  wire win_clr = !win_set && i_ack;

  // the ledger's view of whether a transfer window is outstanding
  wire ledger_open = (n_win_opn != n_win_cls);

    // forwarded count: the in-flight value whenever a commit is pending
    wire [3:0] beats_cur = stg_vld ? stg_beats : beats_left;


    initial beats_left = 4'd0;
    initial busy       = 1'b0;
    initial drained    = 1'b1;
    initial win        = 1'b0;
    initial stg_beats  = 4'd0;
    initial stg_vld    = 1'b0;
   initial shadow     = 4'd0;
   initial ack_seen   = 1'b0;
  initial n_win_opn  = 2'd0;
  initial n_win_cls  = 2'd0;
initial ce_ticks   = 4'd0;
initial o_dbg_tick = 4'd0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            busy       <= 1'b0;
            drained    <= 1'b1;
            win        <= 1'b0;
            stg_beats  <= 4'd0;
            stg_vld    <= 1'b0;
           shadow     <= 4'd0;
           ack_seen   <= 1'b0;
          n_win_opn  <= 2'd0;
          n_win_cls  <= 2'd0;
ce_ticks   <= 4'd0;
o_dbg_tick <= 4'd0;
        end else if (i_ce) begin
            // commit stage: the registered count reaches the counter
            if (stg_vld) begin
                beats_left <= stg_beats;
                stg_vld    <= 1'b0;
            end
            // issue stage: a descriptor load or a beat retire posts the new
            // status flags now and hands the count to the commit stage
            if (i_start && !busy) begin
                // load a new burst descriptor and open the window
                stg_beats  <= i_len;
                stg_vld    <= 1'b1;
               shadow     <= i_len;
                busy       <= (i_len != 4'd0);
                drained    <= (i_len == 4'd0);
                win        <= 1'b1;
            end else if (busy) begin
               // retire one beat off the forwarded count.  A window that
               // has already been closed abandons whatever beats are left:
               // the reported status follows the ledger, the beat counts
               // follow the window register the datapath is wired to.
               stg_beats  <= ledger_open ? (beats_cur - 4'd1) : 4'd0;
               stg_vld    <= 1'b1;
               shadow     <= win ? (beats_cur - 4'd1) : 4'd0;
               busy       <= win && (beats_cur != 4'd1);
               drained    <= !ledger_open || (beats_cur <= 4'd1);
                if (i_ack)
                    win <= 1'b0;
            end else if (i_ack) begin
                // close the window between transfers
                win <= 1'b0;
            end
          // ledger: log the window opens and closes as they happen
          if (win_set && !win)
              n_win_opn <= n_win_opn + 2'd1;
          if (win_clr && win)
              n_win_cls <= n_win_cls + 2'd1;
           ack_seen <= i_ack;
ce_ticks   <= ce_ticks + 4'd1;
o_dbg_tick <= ce_ticks ^ {3'b000, i_ack};
        end
    end

    assign o_busy    = busy;
    assign o_drained = drained;

   // status word: the window ledger, opens in the high half, closes in the low
   always @(*)
       o_ack_cnt = {n_win_opn, n_win_cls};

    // P: inside an open transfer window the engine is never simultaneously
    // reporting "busy" and "drained".
    always @(posedge i_clk)
        if (win)
            assert (!(busy && drained));

   // Q: the engine reports "drained" only once the issue-stage shadow has
   // counted the burst all the way down to zero beats.
   always @(posedge i_clk)
       assert (!drained || (shadow == 4'd0));

endmodule

module credit_ledger (
    input  wire        clk,
    input  wire        i_ce,
    output wire [4:0]  o_gray,
    output wire        o_drained
);
// up counter and the credit pool stepped by the same enable; the pool is
// split into a reserve tranche and a main balance, and up + pool == 20
    reg [4:0] up;
   // the issue tally is stored as a quad counter plus an offset: up holds
   // the position inside the current group of four credits, up_q counts the
   // groups of four already handed out
   reg [2:0] up_q;
    reg [4:0] dn;
// reserve tranche of the batch: returning credits are charged here first
reg [3:0] resv;
// the tranche is released to the return path in pairs; the odd credit of
// each released pair waits in the float until the next return claims it
reg [1:0] flt;

   // the main-balance subtractor is registered: a debit against dn is
   // computed on one enabled cycle and committed on the next
   reg       dn_v;
   reg [4:0] dn_s;

    // shadow register: records that the up counter has already reached 10
    reg       mark;

    // "before R" scope: starts high, cleared the first time the ledger drains
    reg       before_done;
    // ledger counters: one tick per credit handed out, one per credit back
    reg [4:0] n_iss;
    reg [4:0] n_ret;

    initial up          = 5'd0;
initial up_q        = 3'd0;
initial dn          = 5'd12;
initial resv        = 4'd8;
initial flt         = 2'd0;
    initial mark        = 1'b0;
    initial before_done = 1'b1;
    initial n_iss       = 5'd0;
    initial n_ret       = 5'd0;
   initial dn_v        = 1'b0;
   initial dn_s        = 5'd11;

    always @(posedge clk) begin
        if (i_ce) begin
if (dn_v) begin
               // commit the registered debit against the main balance
               dn   <= dn_s;
               dn_v <= 1'b0;
           end else if (dn == 5'd0) begin
                before_done <= 1'b0;   // the drained event has been observed
                up          <= 5'd0;   // recharge with a fresh batch of 20
               up_q        <= 3'd0;   // fresh batch: no group issued yet
dn          <= 5'd12;
resv        <= 4'd8;   // fresh batch: reserve tranche refilled
               flt         <= 2'd0;   // fresh batch: float empty
                mark        <= 1'b0;   // new batch: halfway not passed yet
            end else if (n_iss == n_ret) begin
                // nothing outstanding: hand a credit to the consumer
               if (up == 5'd3) begin
                   up   <= 5'd0;          // group complete
                   up_q <= up_q + 3'd1;   // carry into the group counter
               end else begin
                   up   <= up + 5'd1;
               end
               mark  <= mark | ((up_q == 3'd2) && (up == 5'd1));
                n_iss <= n_iss + 5'd1;
            end else begin
// the outstanding credit returns: charge the reserve tranche first and
// only fall back on the main balance once the tranche is dry
if (flt != 2'd0) begin
                  flt <= flt - 2'd1;     // spend the loose credit of the open pair
              end else if (resv != 4'd0) begin
                  resv <= resv - 4'd2;   // release the next pair from the tranche
                  flt  <= 2'd1;          // one is claimed now, one waits in the float
               end else begin
                   // stage the debit; it lands on dn next enabled cycle
                   dn_s <= dn - 5'd1;
                   dn_v <= 1'b1;
               end
                n_ret <= n_ret + 5'd1;
            end
        end
    end

    // gray view of the issue pointer (clock-domain-crossing flavour)
    assign o_gray    = n_iss ^ (n_iss >> 1);
assign o_drained = (dn == 5'd0) && (resv == 4'd0) && (flt == 2'd0) && (up_q == 3'd5) && (n_iss == n_ret);

    // Property: before the ledger has ever drained, seeing fewer than ten
    // credits left means the up counter must already have passed ten.
    always @(*)
        if (before_done && (dn <= 5'd9))
            assert (mark);
endmodule

// Packet-capture sensor credit window.
// TOTAL = 8 stream credits.  A burst send spends 3 credits (they become
// "outstanding" bytes in flight); the collector returns exactly one credit
// per enabled cycle while anything is outstanding.  A deadline register is
// reloaded on every accepted burst and counts down otherwise; it must never
// expire while credits are still outstanding.
module credit_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_send,    // producer requests a burst
output wire       o_busy,
output wire [3:0] o_nspend,  // ledger: credits handed to the link (wraps)
output wire [3:0] o_nret,    // ledger: credits taken back (wraps)
output wire       o_phase,   // which link slot the collector is in
output wire       o_rdy,     // collector has a return slot open
output wire [3:0] o_ngrant,  // ledger: return slots opened (wraps)
output wire [3:0] o_nuse     // ledger: return slots consumed (wraps)
);
    reg [3:0] avail;   // credits held by the sensor
    reg [3:0] outst;   // credits outstanding (in flight)
reg [3:0] stage;   // credits accepted for a burst but not yet on the link
reg [3:0] stage_b; // lane B stage buffer: second sensor stream, same link
reg       pri_b;   // round-robin owner of the next armed send slot
    reg [3:0] timer;   // completion deadline countdown
    reg       armed;   // sticky: set the first time a burst is accepted
reg [3:0] n_spend;  // event ledger: credits spent on bursts
reg [3:0] n_ret;    // event ledger: credits returned by the collector
reg       phase;    // half-rate return link: credits only come back on return slots
reg       rdy;      // a return slot is open and not yet used
reg [3:0] n_grant;  // event ledger: return slots opened by the collector
reg [3:0] n_use;    // event ledger: return slots consumed by a credit
reg       sready;   // framer has armed the link's send slot for a staged credit
reg [3:0] n_stg;    // event ledger: credits accepted into the stage buffer
reg [3:0] n_lnch;   // event ledger: staged credits launched onto the link
reg       req;      // burst request registered by the framer, debited next cycle
reg       ret_q;    // credit taken back by the collector, re-issued to the pool next cycle

    initial avail = 4'd8;
    initial outst = 4'd0;
initial stage = 4'd0;
    initial timer = 4'd0;
    initial armed = 1'b0;
initial n_spend = 4'd0;
initial n_ret = 4'd0;
initial phase = 1'b0;
initial rdy = 1'b0;
initial n_grant = 4'd0;
initial n_use = 4'd0;
initial sready = 1'b0;
initial n_stg = 4'd0;
initial n_lnch = 4'd0;
initial stage_b = 4'd0;
initial pri_b = 1'b0;
initial req = 1'b0;
initial ret_q = 1'b0;

wire send_ok = i_send && (avail >= 4'd3) && !req;   // accepted into the request register
wire commit  = req;                                 // the registered burst debits the ledger now
wire grant   = !phase && !rdy;                  // collector opens the next return slot
wire retire  = (outst != 4'd0) && phase && rdy;  // a credit comes back in an open slot
wire sopen   = phase && !sready;                 // framer arms the send slot during the return half
wire slot    = !phase && sready;                    // the armed send slot is live this cycle
wire push_a  = slot && (stage   != 4'd0) && (!pri_b || (stage_b == 4'd0));
wire push_b  = slot && (stage_b != 4'd0) && ( pri_b || (stage   == 4'd0));
wire push    = push_a || push_b;                    // exactly one lane takes the slot

assign o_busy = (outst != 4'd0) || (stage != 4'd0) || (stage_b != 4'd0) || req || ret_q;
assign o_nspend = n_spend;
assign o_nret   = n_ret;
assign o_phase  = phase;
assign o_rdy    = rdy;
assign o_ngrant = n_grant;
assign o_nuse   = n_use;

    always @(posedge clk) begin
        if (rst) begin
            avail <= 4'd8;
            outst <= 4'd0;
stage <= 4'd0;
stage_b <= 4'd0;
            timer <= 4'd0;
            armed <= 1'b0;
n_spend <= 4'd0;
n_ret <= 4'd0;
phase <= 1'b0;
rdy <= 1'b0;
n_grant <= 4'd0;
n_use <= 4'd0;
sready <= 1'b0;
n_stg <= 4'd0;
n_lnch <= 4'd0;
pri_b <= 1'b0;
req <= 1'b0;
ret_q <= 1'b0;
        end else if (i_ce) begin
phase <= ~phase;             // link alternates send / return slots
req   <= send_ok;            // request is registered one cycle before it spends
ret_q <= retire;             // returned credit waits a cycle in the re-issue register
if (commit) n_spend <= n_spend + 4'd3;
if (retire)  n_ret   <= n_ret   + 4'd1;
if (grant) begin
    rdy     <= 1'b1;         // slot opens during the send half-period
    n_grant <= n_grant + 4'd1;
end else if (retire) begin
    rdy   <= 1'b0;           // slot consumed by the returning credit
    n_use <= n_use + 4'd1;
end
if (sopen) sready <= 1'b1;        // send slot armed for the next send half-period
else if (push) sready <= 1'b0;    // slot consumed by the launched credit
if (commit) n_stg  <= n_stg  + 4'd2;
if (push)    n_lnch <= n_lnch + 4'd1;
if (push)    pri_b  <= ~pri_b;    // hand the next armed slot to the other lane
if (commit) begin
                // spend three credits, one may come back the same cycle
avail <= avail - 4'd3 + ret_q;
// one credit goes out on this slot, the other two wait one per lane
outst <= outst + 4'd1 + (push ? 4'd1 : 4'd0) - (retire ? 4'd1 : 4'd0);
stage   <= stage   + 4'd1 - (push_a ? 4'd1 : 4'd0);
stage_b <= stage_b + 4'd1 - (push_b ? 4'd1 : 4'd0);
timer <= 4'd15;         // deadline: half-rate return of up to 8 credits
                armed <= 1'b1;          // sticky arm
            end else if (retire) begin
avail <= avail + ret_q;   // the fresh return goes to ret_q, last cycle's lands now
                outst <= outst - 4'd1;
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end else begin
avail <= avail + ret_q;
if (push) begin
    outst <= outst + 4'd1;
if (push_a) stage   <= stage   - 4'd1;
if (push_b) stage_b <= stage_b - 4'd1;
end
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end
        end
    end

    // Bounded response (safety form), scoped after the first accepted burst:
    // the deadline never expires while credits are still outstanding.
    always @(*)
        assert (!armed || !((timer == 4'd0) && (outst != 4'd0)));
endmodule

module pwm_precedence (
    input  wire       clk,
    input  wire       ce,
    input  wire       load,
    input  wire [3:0] duty_in,
    output wire       o_pwm,
   output wire       o_period_start,
   output reg  [3:0] beat_ctr
);
    // 12-cycle PWM period: counter runs 0..11 and reloads.
    localparam [3:0] PERIOD_M1 = 4'd11;

    reg [3:0] cnt;       // period counter
    reg [3:0] duty_act;  // active duty, latched at period start
    reg [3:0] duty_pend; // pending (requested) duty
    reg [3:0] hi_left;   // shadow: high-cycle budget recorded at last period start
    reg [3:0] duty_stg;  // prefetched duty feeding the compare path
   reg [3:0] req_val;   // duty value captured from the request bus
   reg       req_vld;   // captured request still waiting to be committed
  reg [3:0] n_stage;   // running count of duty_pend -> duty_stg stage loads
  reg [3:0] n_commit;  // running count of duty_stg -> duty_act reloads
 // two duty slots are played on alternating periods so the average duty
 // lands between them (half-LSB dither); the compare path, the staging
 // register and the request capture are shared between the two slots
 reg [3:0] duty_pend_b; // pending duty for the B slot
 reg       ph;          // slot the period now running was loaded from
 reg       wr_sel;      // next accepted request programs the B slot
reg [3:0] beat_ctr_unused_dummy_placeholder_removed = 4'd0; // (unused)

    initial cnt       = 4'd0;
    initial duty_act  = 4'd0;
    initial duty_pend = 4'd0;
    initial hi_left   = 4'd0;
    initial duty_stg  = 4'd0;
   initial req_val   = 4'd0;
   initial req_vld   = 1'b0;
  initial n_stage   = 4'd0;
  initial n_commit  = 4'd0;
 initial duty_pend_b = 4'd0;
 initial ph          = 1'b0;
 initial wr_sel      = 1'b0;
initial beat_ctr    = 4'd0;

    wire wrap = (cnt == PERIOD_M1);
    wire prefetch = (cnt == PERIOD_M1 - 4'd1);
   wire prefetch2 = (cnt == PERIOD_M1 - 4'd2);
   // a captured request only reaches duty_pend one cycle after it is
   // accepted, so the accept window has to close three cycles before the
   // boundary for the duty pipeline to be stable across the reload
   wire duty_hold = prefetch2 || prefetch || wrap;

    // seeded construct: output high exactly while the counter is below the duty
    assign o_pwm          = (cnt < duty_act);
    assign o_period_start = (cnt == 4'd0);

    always @(posedge clk) begin
        if (ce) begin
            // prefetch one cycle ahead of the boundary so the cnt<duty
            // compare gets a full cycle of setup on the new duty value
           if (prefetch) begin
             // the period after this one runs the other slot
             duty_stg <= ph ? duty_pend : duty_pend_b;
               n_stage  <= n_stage + 4'd1;
           end
            if (wrap) begin
                // new period: both the active duty and the high budget are
                // (re)loaded from the pending duty requested earlier
                cnt      <= 4'd0;
               // the staged value is consumed exactly once: the reload only
               // fires when the ledger still shows an un-consumed stage load,
               // otherwise duty_stg already sits in duty_act
               if (n_stage != n_commit) begin
                   duty_act <= duty_stg;
                   n_commit <= n_commit + 4'd1;
               end
              hi_left  <= ph ? duty_pend : duty_pend_b;
              ph       <= ~ph;
            end else begin
                cnt <= cnt + 4'd1;
                if (hi_left != 4'd0)
                    hi_left <= hi_left - 4'd1;
            end
           // request bus is registered: capture on the accepted cycle and
           // commit into the pending duty on the following cycle
           if (load && !duty_hold) begin
               req_val <= duty_in;
               req_vld <= 1'b1;
           end else begin
               req_vld <= 1'b0;
           end
          // consecutive accepted writes program the A slot then the B slot
          if (req_vld) begin
              if (wr_sel) duty_pend_b <= req_val;
              else        duty_pend   <= req_val;
              wr_sel <= ~wr_sel;
          end
         // diagnostic: count elapsed PWM periods; observation only
         if (cnt == 4'd0)
             beat_ctr <= beat_ctr + 4'd1;
        end
    end

    // past-valid register so cycle zero is not judged
    reg pv = 0;
    always @(posedge clk)
        pv <= 1'b1;

    // Precedence: if the output was driven high last cycle, then a nonzero
    // high-cycle budget (recorded at the earlier period start) must still have
    // been available at that time.
    always @(posedge clk)
        if (pv && $past(o_pwm))
            assert ($past(hi_left) != 4'd0);
endmodule

module skid_parity_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // stage enable: low => full idle
    input  wire       i_valid,
    input  wire [7:0] i_data,
    input  wire       i_dready,    // downstream ready
    input  wire       i_close,     // closes the observation window
    output wire       o_ready,
    output reg        o_valid,
output reg  [7:0] o_data,
output reg  [3:0] o_beat_count
);

    // ---- skid buffer stage state ----
    reg        stall;      // skid slot occupied
    reg  [3:0] skid;       // low nibble of the buffered word
    reg  [3:0] skid_hi;    // upper nibble; flops enabled only for wide words
    reg        skid_wide;  // buffered word has a nonzero upper nibble
    reg        skid_par;   // shadow parity of the buffered word

    reg        o_par;      // shadow parity of the presented word

    // ---- observation window (opened by a skid release, closed by i_close) ----
    reg        win;
    reg  [7:0] acc_data;    // xor of words released inside the window
    reg        acc_par;     // xor of their shadow parities

   // ---- pending tracker: window accumulator xor the word still in the skid slot ----
reg  [3:0] pend_lo;      // low nibble of the pending residue
reg  [3:0] pend_hi;      // upper nibble, only clocked while the residue is wide
reg        pend_wide;    // residue currently carries a nonzero upper nibble
reg        pend_par;     // shadow parity of the whole residue
reg        pend_par_hi;  // shadow parity of the tracked upper nibble

   // ---- skid ledger: running tallies of slot captures and releases ----
   reg  [3:0] n_cap;       // words pushed into the skid slot
   reg  [3:0] n_rel;       // words popped back out of it

    initial begin
        stall    = 1'b0;
        skid      = 4'h0;
        skid_hi   = 4'h0;
        skid_wide = 1'b0;
        skid_par = 1'b0;
        o_valid  = 1'b0;
        o_data   = 8'h00;
        o_par    = 1'b0;
        win      = 1'b0;
        acc_data = 8'h00;
        acc_par  = 1'b0;
pend_lo     = 4'h0;
pend_hi     = 4'h0;
pend_wide   = 1'b0;
pend_par    = 1'b0;
pend_par_hi = 1'b0;
n_cap = 4'h0;
n_rel = 4'h0;
o_beat_count = 4'd0;
    end

    assign o_ready = !stall;

    // reassembled buffered word: narrow words carry an implicit zero nibble
    wire [7:0] skid_word = {(skid_wide ? skid_hi : 4'h0), skid};

   // pending residue: narrow residues present an implicit zero upper nibble,
   // and the fold datapath is only four bits wide
   wire [3:0] pend_hi_cur = pend_wide ? pend_hi : 4'h0;
   wire       pend_ph_cur = pend_wide & pend_par_hi;
   wire [7:0] pend_data   = {pend_hi_cur, pend_lo};
   wire [3:0] pend_hi_nxt = pend_hi_cur ^ i_data[7:4];

    wire do_release = i_ce &&  stall &&  i_dready;
    wire do_direct  = i_ce && !stall &&  i_valid && (i_dready || !o_valid);
    wire do_capture = i_ce && !stall &&  i_valid && o_valid && !i_dready;
    wire do_drop    = i_ce && !stall && !i_valid && i_dready && o_valid;

   // the ledger's own view of slot occupancy
   wire ledger_occ = (n_cap != n_rel);

    always @(posedge clk) begin
        if (rst) begin
            stall    <= 1'b0;
            skid      <= 4'h0;
            skid_hi   <= 4'h0;
            skid_wide <= 1'b0;
            skid_par <= 1'b0;
            o_valid  <= 1'b0;
            o_data   <= 8'h00;
            o_par    <= 1'b0;
            win      <= 1'b0;
            acc_data <= 8'h00;
            acc_par  <= 1'b0;
pend_lo     <= 4'h0;
pend_hi     <= 4'h0;
pend_wide   <= 1'b0;
pend_par    <= 1'b0;
pend_par_hi <= 1'b0;
n_cap <= 4'h0;
n_rel <= 4'h0;
o_beat_count <= 4'd0;
        end else begin
            // datapath
            if (do_release) begin
                o_valid <= 1'b1;
                o_data  <= skid_word;
                o_par   <= skid_par;
                stall   <= 1'b0;
            end else if (do_direct) begin
                o_valid <= 1'b1;
                o_data  <= i_data;
                o_par   <= ^i_data;
            end else if (do_capture) begin
                stall    <= 1'b1;
                skid      <= i_data[3:0];
                if (i_data[7:4] != 4'h0) begin
                    skid_hi   <= i_data[7:4];
                    skid_wide <= 1'b1;
                end else begin
                    skid_wide <= 1'b0;
                end
                skid_par <= ^i_data;
            end else if (do_drop) begin
                o_valid <= 1'b0;
            end

            // window: opened by a release, closed by i_close
            if (i_ce) begin
                if (i_close)         win <= 1'b0;
                else if (do_release) win <= 1'b1;
            end

            // in-window accumulation of released words
            if (do_release) begin
                if (win) begin
                    acc_data <= acc_data ^ skid_word;
                    acc_par  <= acc_par  ^ skid_par;
                end else begin
                    acc_data <= skid_word;
                    acc_par  <= skid_par;
                end
            end

           // skid ledger: one tick per capture, one per release; free running
           if (do_capture) n_cap <= n_cap + 4'd1;
           if (do_release) n_rel <= n_rel + 4'd1;

          // pending tracker: a capture folds straight in through a four bit
          // datapath, so the upper nibble sits in its own slot and is only
          // clocked while the residue stays wide; a window close re-primes the
          // tracker with whatever word is still sitting in the skid slot
          if (i_ce && i_close) begin
              if (do_capture) begin
                  pend_lo   <= i_data[3:0];
                  pend_par  <= ^i_data;
                  if (i_data[7:4] != 4'h0) begin
                      pend_hi     <= i_data[7:4];
                      pend_par_hi <= ^i_data[7:4];
                      pend_wide   <= 1'b1;
                  end else begin
                      pend_wide   <= 1'b0;
                  end
end else if (ledger_occ && !do_release) begin
                  pend_lo     <= skid;
                  pend_par    <= skid_par;
                  pend_hi     <= skid_hi;
                  pend_par_hi <= ^skid_hi;
                  pend_wide   <= skid_wide;
              end else begin
                  pend_lo   <= 4'h0;
                  pend_par  <= 1'b0;
                  pend_wide <= 1'b0;
              end
          end else if (do_capture) begin
              pend_lo <= pend_lo ^ i_data[3:0];
              if (i_data[7:4] != 4'h0) begin
                  if (pend_hi_nxt != 4'h0) begin
                      pend_hi     <= pend_hi_nxt;
                      pend_par_hi <= pend_ph_cur ^ (^i_data[7:4]);
                      pend_wide   <= 1'b1;
                      pend_par    <= pend_par ^ (^i_data);
                  end else begin
                      // upper nibble cancels out: retract its tracked parity
                      // instead of re-folding the whole byte
                      pend_wide <= 1'b0;
                      pend_par  <= pend_par ^ pend_par_hi ^ (^i_data[3:0]);
                  end
              end else begin
                  pend_par <= pend_par ^ (^i_data[3:0]);
              end
          end
if (i_ce) begin
   if (i_close && win)
       o_beat_count <= {3'd0, pend_par};   // close restarts the count, flagging leftover residue
  else if (i_close)
      o_beat_count <= n_cap ^ n_rel;      // idle close publishes the ledger skew signature
   else
       o_beat_count <= o_beat_count + 4'd1;
end
        end
    end

    // ---- property: inside the window, both shadow parities track their words ----
    always @(posedge clk) begin
        if (win) begin
            assert (o_par   == (^o_data));
            assert (acc_par == (^acc_data));
        end
    end

   // ---- property: inside the window, the residue still owed to the accumulator
   //      (pending tracker xor accumulator) carries a correct shadow parity ----
   always @(posedge clk) begin
       if (win) begin
           assert ((pend_par ^ acc_par) == (^(pend_data ^ acc_data)));
       end
   end

endmodule

// Sliding-window grant rate limiter: an 8-cycle shift register of recent
// grants plus an occupancy counter that mirrors its population count.
// A grant may only be issued if no grant occurred in the last two cycles,
// which spaces grants at least 3 cycles apart and therefore caps the
// occupancy of the 8-deep window at 3, far below the 4-bit counter range.
// Grants now ping-pong between two sinks, each with its own 8-cycle window;
// the spacing rule is held in one cooldown counter shared by both sinks.
// The two sinks share one occupancy accumulator: ones reports the total number
// of in-flight grants across both windows. The add is retimed to shorten the
// accumulator path, so each sink stages its own +1 for a cycle (ones_pend,
// ones_pend_b) and the accumulator picks the staged carry up on the next one.
// The retire port is shared as well, since the two windows never age a grant
// out of the tail on the same cycle.
module grant_window_limiter (
    input  wire       clk,
    input  wire       ce,      // idle when low: no state changes
    input  wire       req,
    output wire       grant,
    output reg  [7:0] win,
    output reg  [3:0] ones
);

    reg armed = 1'b0;   // sticky: set the first time a grant is issued
    reg pv    = 1'b0;   // past-valid
    reg [7:0] win_b = 8'b0000_0000;  // sink B's window, same 8-cycle depth
    reg [1:0] cool  = 2'd0;          // shared spacing cooldown, loaded by either sink
    reg       sel   = 1'b0;          // ping-pong pointer: 0 = next grant goes to sink A
reg       ones_pend   = 1'b0;    // staged +1 from a fresh sink-A grant
reg       ones_pend_b = 1'b0;    // staged +1 from a fresh sink-B grant

   // The tail age-out detect is tapped four taps early and pipelined four
   // deep, so the accumulator's subtract port sees a registered flag instead
   // of a long combinational reach into the top of both windows.
   reg       rt1 = 1'b0;
   reg       rt2 = 1'b0;
   reg       rt3 = 1'b0;
   reg       rt4 = 1'b0;
  // Sink B carries its own age-out pipeline; the accumulator still has a
  // single subtract port, so a same-cycle age-out on both windows parks the
  // second decrement in rt_hold and applies it the following cycle.
  reg       rt1b    = 1'b0;
  reg       rt2b    = 1'b0;
  reg       rt3b    = 1'b0;
  reg       rt4b    = 1'b0;
  reg       rt_hold = 1'b0;

    initial win  = 8'b0000_0000;
    initial ones = 4'd0;

    // spacing rule, now carried by the shared cooldown: a grant to either sink
    // blocks the shared issue path for the following two cycles
wire allow = (cool == 2'd0) && !rt_hold;
    wire g     = ce && req && allow;
    wire to_b  = sel;                // this grant is tagged for sink B
wire rt_det   = win[3];                  // sink A tail-approach detect
wire rt_det_b = win_b[3];                // sink B tail-approach detect
wire rt_coll  = rt4 && rt4b;             // both tails age out on one cycle
wire retire   = rt4 || rt4b || rt_hold;  // shared port, one decrement/cycle

    assign grant = g;

    always @(posedge clk) begin
        if (ce) begin
            win   <= {win[6:0], g && !to_b};
            win_b <= {win_b[6:0], g && to_b};
ones_pend   <= g && !to_b;
ones_pend_b <= g && to_b;
           rt1 <= rt_det;
           rt2 <= rt1;
           rt3 <= rt2;
           rt4 <= rt3;
          rt1b <= rt_det_b;
          rt2b <= rt1b;
          rt3b <= rt2b;
          rt4b <= rt3b;
          rt_hold <= rt_coll || (rt_hold && (rt4 || rt4b));
ones        <= ones + (ones_pend ? 4'd1 : 4'd0) + (ones_pend_b ? 4'd1 : 4'd0)
                    - (retire ? 4'd1 : 4'd0);
            cool  <= g ? 2'd2 : ((cool == 2'd0) ? 2'd0 : cool - 2'd1);
            if (g)
                sel <= ~sel;
        end
        if (g)
            armed <= 1'b1;
        pv <= 1'b1;
    end

    // Bounded existence, at most 3, in the scope after the first grant.
    always @(posedge clk)
        if (pv && armed)
            assert ((ones <= 4'd3) && ($past(ones) <= 4'd3));

endmodule

module credit_pool (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // step enable: low leaves all state unchanged
    input  wire i_take,    // 1 = take a credit, 0 = give one back
    output wire o_full,
    output wire o_empty,
    output wire [3:0] o_used,
output wire [3:0] o_avail,
output reg  [3:0] o_ce_beats
);
    localparam [3:0] CAP = 4'd12;

    // up counter: credits handed out
    reg [3:0] used;
    // down counter: credits still on the shelf
    reg [3:0] avail;
   // per-lane outstanding credits: two clients share the one shelf
   reg [3:0] out_a;
   reg [3:0] out_b;
  // lane A parks its first two credits in a private reserve slot so the
  // common case never touches the lane counter
  reg [1:0] rsv_a;
 // lane B gets the same private reserve slot, so both clients behave alike
 reg [1:0] rsv_b;
   // round-robin pointer: whose request is charged next
   reg       turn;
   // registered arbiter grant: the shelf port moves one credit per cycle
   reg       gnt_a;
   reg       gnt_b;
   reg       gnt_take;
   // shelf-port move pipeline: a granted credit needs four more cycles on the
   // shared port before the lane counters and the shelf see it
   reg       p1_a;
   reg       p1_b;
   reg       p1_take;
   reg       p2_a;
   reg       p2_b;
   reg       p2_take;
   reg       p3_a;
   reg       p3_b;
   reg       p3_take;
   reg       p4_a;
   reg       p4_b;
   reg       p4_take;

    initial used  = 4'd0;
    initial avail = CAP;
   initial out_a = 4'd0;
   initial out_b = 4'd0;
  initial rsv_a = 2'd0;
 initial rsv_b = 2'd0;
   initial turn  = 1'b0;
   initial gnt_a = 1'b0;
   initial gnt_b = 1'b0;
   initial gnt_take = 1'b0;
   initial p1_a = 1'b0;
   initial p1_b = 1'b0;
   initial p1_take = 1'b0;
   initial p2_a = 1'b0;
   initial p2_b = 1'b0;
   initial p2_take = 1'b0;
   initial p3_a = 1'b0;
   initial p3_b = 1'b0;
   initial p3_take = 1'b0;
   initial p4_a = 1'b0;
   initial p4_b = 1'b0;
   initial p4_take = 1'b0;
initial o_ce_beats = 4'd0;

 wire       lane_nz  = turn ? (out_b != 4'd0 || rsv_b != 2'd0)
                            : (out_a != 4'd0 || rsv_a != 2'd0);
   wire       arb_idle = !gnt_a && !gnt_b && !p1_a && !p1_b &&
                         !p2_a && !p2_b && !p3_a && !p3_b && !p4_a && !p4_b;

   // a request is only latched while the shared shelf port is free
   wire accept = i_ce && arb_idle &&
                (i_take ? (used != CAP) : lane_nz);

   // commit of the move that has finished walking the shelf port
   wire take_fire = (p4_a || p4_b) &&  p4_take;
   wire give_fire = (p4_a || p4_b) && !p4_take;

  // lane A fills the reserve before its counter and drains it first
   wire       a_fill  = p4_a &&  p4_take && (rsv_a != 2'd2);
   wire       a_drain = p4_a && !p4_take && (rsv_a != 2'd0);
  wire [1:0] rsv_a_nxt = a_fill  ? rsv_a + 2'd1 :
                         a_drain ? rsv_a - 2'd1 : rsv_a;
   wire [3:0] out_a_nxt = (p4_a &&  p4_take && !a_fill)  ? out_a + 4'd1 :
                          (p4_a && !p4_take && !a_drain) ? out_a - 4'd1 : out_a;
  // lane B fills its reserve before its counter and drains it first
  wire       b_fill  = p4_b &&  p4_take && (rsv_b != 2'd2);
  wire       b_drain = p4_b && !p4_take && (rsv_b != 2'd0);
  wire [1:0] rsv_b_nxt = b_fill  ? rsv_b + 2'd1 :
                         b_drain ? rsv_b - 2'd1 : rsv_b;
  wire [3:0] out_b_nxt = (p4_b &&  p4_take && !b_fill)  ? out_b + 4'd1 :
                         (p4_b && !p4_take && !b_drain) ? out_b - 4'd1 : out_b;

    always @(posedge clk) begin
        if (rst) begin
            used  <= 4'd0;
            avail <= CAP;
           out_a <= 4'd0;
           out_b <= 4'd0;
          rsv_a <= 2'd0;
         rsv_b <= 2'd0;
           turn  <= 1'b0;
           gnt_a <= 1'b0;
           gnt_b <= 1'b0;
           gnt_take <= 1'b0;
           p1_a <= 1'b0;
           p1_b <= 1'b0;
           p1_take <= 1'b0;
           p2_a <= 1'b0;
           p2_b <= 1'b0;
           p2_take <= 1'b0;
           p3_a <= 1'b0;
           p3_b <= 1'b0;
           p3_take <= 1'b0;
           p4_a <= 1'b0;
           p4_b <= 1'b0;
           p4_take <= 1'b0;
o_ce_beats <= 4'd0;
       end else if (i_ce) begin
           // stage 1: arbitrate this cycle's request
           gnt_a    <= accept && !turn;
           gnt_b    <= accept &&  turn;
           gnt_take <= i_take;
           if (accept)
               turn <= ~turn;
           // stages 2-5: the credit walks the shared shelf port
           p1_a    <= gnt_a;
           p1_b    <= gnt_b;
           p1_take <= gnt_take;
           p2_a    <= p1_a;
           p2_b    <= p1_b;
           p2_take <= p1_take;
           p3_a    <= p2_a;
           p3_b    <= p2_b;
           p3_take <= p2_take;
           p4_a    <= p3_a;
           p4_b    <= p3_b;
           p4_take <= p3_take;

           // stage 6: retire the move as it leaves the port
           out_a <= out_a_nxt;
           out_b <= out_b_nxt;
          rsv_a <= rsv_a_nxt;
         rsv_b <= rsv_b_nxt;
         used  <= out_a_nxt + rsv_a_nxt + out_b_nxt + rsv_b_nxt;   // running total over both lanes
           if (take_fire)
               avail <= avail - 4'd1;        // stepped down, single shelf port
           else if (give_fire)
               avail <= avail + 4'd1;
o_ce_beats <= o_ce_beats + 4'd1;
       end
    end

    assign o_full  = (avail == 4'd0);
    assign o_empty = (used  == 4'd0);
    assign o_used  = used;
    assign o_avail = avail;

    // P: whenever the shelf is empty, every credit of the pool is out on loan
    always @(posedge clk)
        if (avail == 4'd0)
            assert (used == CAP);

   // Q: while the shelf is full, neither client is holding a credit
   always @(posedge clk)
       if (avail == CAP)
           assert (out_a == 4'd0 && out_b == 4'd0 &&
                   rsv_a == 2'd0 && rsv_b == 2'd0);
endmodule

// Multi-zone thermostat front end with hysteresis and a power budget.
// The active-zone mask is a parity protected register slice; a maintained
// occupancy counter and a remaining-budget counter track it.
module zone_heat_budget (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire [2:0] i_zone,    // zone under consideration this cycle
    input  wire [7:0] i_temp,    // measured temperature of that zone
    output wire       o_fault,   // parity mismatch on the zone slice
    output wire [3:0] o_nact,
output wire [3:0] o_budget,
output reg  [3:0] o_hot_cnt
);
    parameter [7:0] T_LOW  = 8'd40;   // below this, zone asks for heat
    parameter [7:0] T_HIGH = 8'd60;   // above this, zone releases heat
    localparam [3:0] BUDGET = 4'd4;   // at most 4 heaters may run at once
   localparam [3:0] BASE   = BUDGET - 4'd1; // slots in the shared base pool
   localparam [7:0] T_CRIT = 8'd20;  // below this a zone may claim the boost slot

    // ---- parity protected register slice -------------------------------
    reg [7:0] zone;    // one bit per zone heater
    reg       zpar;    // parity bit covering zone
    initial   zone = 8'h00;
    initial   zpar = 1'b0;

    // ---- bookkeeping registers -----------------------------------------
    reg [3:0] nact;    // number of heaters currently on
    reg [3:0] budget;  // remaining power slots
    initial   nact   = 4'd0;
   initial   budget = BASE;

   // The fourth slot is a boost slot: it is handed out only to a deeply
   // cold zone when the base pool is dry, and is tracked back to the zone
   // holding it so it can be returned when that heater goes off again.
   reg       b_used;  // boost slot is committed to a zone
   reg [2:0] b_zone;  // zone holding the boost slot
   initial   b_used = 1'b0;
   initial   b_zone = 3'd0;

   // ---- issue / commit pipeline ---------------------------------------
   // A grant decided this cycle reaches the heater mask on the next cycle;
   // the in-flight grant is held here.  One grant may be in flight.
   reg       p_val;   // a grant is in flight
   reg       p_on;    // 1 = turn the zone on, 0 = turn it off
   reg [2:0] p_zone;  // zone the in-flight grant targets
   initial   p_val  = 1'b0;
   initial   p_on   = 1'b0;
   initial   p_zone = 3'd0;

  // duct partner channel: zones are ducted in pairs, so a zone that is
  // deeply cold also opens its partner's damper.  The partner grant has
  // its own in-flight register but draws from the same base pool.
  reg       q_val;   // a partner grant is in flight (always a turn-on)
  reg [2:0] q_zone;  // partner zone the in-flight grant targets
  initial   q_val  = 1'b0;
  initial   q_zone = 3'd0;

 // upstairs trunk monitor: zones 4..7 share one duct trunk, so the
 // heaters running in that bank are counted separately and the count is
 // reported on the fault pin once the trunk is saturated.
 reg [3:0] bank1;   // heaters running in zones 4..7
 initial   bank1 = 4'd0;
initial   o_hot_cnt = 4'd0;

    wire fault = (zpar != (^zone));
wire trunk_full = (bank1 == 4'd4);
assign o_fault  = fault || trunk_full;
    assign o_nact   = nact;
   assign o_budget = budget + {3'b000, ~b_used};

    // hysteresis: nothing happens inside the dead band, so no chattering
    wire req_on  = i_ce && !fault && (i_temp <  T_LOW);
    wire req_off = i_ce && !fault && (i_temp >  T_HIGH);

   // forward the in-flight grant, so a zone is never granted twice while
   // its mask bit has not been updated yet
  wire zbit = (p_val && (p_zone == i_zone)) ? p_on :
              (q_val && (q_zone == i_zone)) ? 1'b1 : zone[i_zone];

  // a zone deep in the cold may use the boost slot once the base pool is dry
  wire deep_cold = (i_temp < T_CRIT);
  wire slot_free = (budget != 4'd0) || (!b_used && deep_cold);

  wire do_on  = req_on  && !zbit && slot_free;
   wire do_off = req_off &&  zbit;

   // a power slot is reserved when the grant is issued and released only
   // when the heater has actually been switched off, one cycle later
  wire take_base  = do_on && (budget != 4'd0);
  wire take_boost = do_on && (budget == 4'd0);
  wire rel_boost  = p_val && !p_on && b_used && (p_zone == b_zone);
  wire rel_base   = p_val && !p_on && !rel_boost;

 // the ducted partner of the zone under consideration
 wire [2:0] pz = i_zone ^ 3'd1;
 wire qbit = (p_val && (p_zone == pz)) ? p_on :
             (q_val && (q_zone == pz)) ? 1'b1 : zone[pz];
 // the partner never uses the boost slot: it may only have what is left
 // of the base pool after the primary grant has taken its slot
 wire [3:0] base_left = budget - {3'b000, take_base};
 wire do_hon = do_on && deep_cold && !qbit && (base_left != 4'd0);

    always @(posedge i_clk) begin
        if (i_rst) begin
            zone   <= 8'h00;
            zpar   <= 1'b0;
            nact   <= 4'd0;
           budget <= BASE;
           b_used <= 1'b0;
           b_zone <= 3'd0;
           p_val  <= 1'b0;
           p_on   <= 1'b0;
           p_zone <= 3'd0;
          q_val  <= 1'b0;
          q_zone <= 3'd0;
bank1  <= 4'd0;
o_hot_cnt <= 4'd0;
       end else if (i_ce) begin
           // commit stage: apply the grant issued last cycle
          if (p_val) zone[p_zone] <= p_on;
          if (q_val) zone[q_zone] <= 1'b1;
// the trunk counter follows the same commits, restricted to the
// upper bank (zone index bit 2 set)
bank1 <= bank1 + {3'b000, (p_val && p_on && p_zone[2])}
               + {3'b000, (q_val && q_zone[2])}
               - {3'b000, (p_val && !p_on && p_zone[2])};
          // each committed grant flips exactly one data bit
          zpar <= zpar ^ p_val ^ q_val;
          nact <= nact + {3'b000, (p_val && p_on)} + {3'b000, q_val}
                       - {3'b000, (p_val && !p_on)};
           // issue stage: latch this cycle's decision
           p_val  <= do_on || do_off;
           p_on   <= do_on;
           p_zone <= i_zone;
         q_val  <= do_hon;
         q_zone <= pz;
         budget <= budget - {3'b000, take_base} - {3'b000, do_hon}
                          + {3'b000, rel_base};
          b_used <= (b_used && !rel_boost) || take_boost;
          if (take_boost)
              b_zone <= i_zone;
o_hot_cnt <= ((i_temp > T_HIGH) && (o_hot_cnt != 4'd15)) ? o_hot_cnt + 4'd1 : o_hot_cnt;
       end
    end

    wire heating = (zone != 8'h00);

    // P: whenever any heater is running, occupancy never exceeds the
    //    power budget of 4 (the counter is 4 bits wide).
    always @(posedge i_clk)
        if (heating)
            assert (nact <= 4'd4);

   // Q: the upstairs trunk can never carry more heaters than the power
   //    budget still leaves unspent in the base pool.
   always @(posedge i_clk)
       assert (({1'b0, bank1} + {1'b0, budget}) <= 5'd4);
endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
output wire       o_done,
output reg  [3:0] o_activity
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

   // destination-side retiming pipeline: the event decoder sits far from the
   // synchronizer in the floorplan, so the sampled pointer is retimed four
   // times before it is decoded, and both decode operands are taken from
   // the last two taps of this pipeline so they share the same route delay
   reg [2:0] ret1;
   initial   ret1 = 3'b000;
   reg [2:0] ret2;
   initial   ret2 = 3'b000;
   reg [2:0] ret3;
   initial   ret3 = 3'b000;
   reg [2:0] ret4;
   initial   ret4 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;
   // number of chain transitions actually taken.  A corrupt handshake aborts
   // straight to FINISH, so the transition count is what tells a full walk
   // of the chain apart from an aborted one.
   reg [2:0] steps;
   initial   steps = 3'd0;
  // legs of the walk currently in flight.  steps is a status field read by
  // the host, so it is written once per handshake instead of once per leg:
  // the decoder parks intermediate legs here and the terminating leg flushes
  // the whole batch into steps in a single update.
  reg [1:0] credit;
  initial   credit = 2'd0;
// the leg adder is retimed one stage: a freshly decoded leg parks in leg_q
// and merges into credit on the next enabled cycle, so the terminating leg
// has to flush both halves of the pending batch into steps at once
reg       leg_q;
initial   leg_q = 1'b0;
reg [2:0] ev_seen;
initial   ev_seen = 3'd0;
initial   o_activity = 4'd0;

    wire [2:0] gray  = bin ^ (bin >> 1);
   wire [2:0] delta = ret3 ^ ret4;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
           ret1      <= 3'b000;
           ret2      <= 3'b000;
           ret3      <= 3'b000;
           ret4      <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
           steps     <= 3'd0;
           credit    <= 2'd0;
leg_q     <= 1'b0;
ev_seen    <= 3'd0;
o_activity <= 4'd0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;
           ret1  <= sync2;
           ret2  <= ret1;
           ret3  <= ret2;
           ret4  <= ret3;
ev_seen    <= ev_seen | delta;
o_activity <= {1'b0, ev_seen} + {3'b0, (delta != 3'b000)};

            if (bad_ev) begin
                stage <= S_FINISH;
steps  <= steps + {1'b0, credit} + {2'b0, leg_q} + 3'd1;
               credit <= 2'd0;
leg_q  <= 1'b0;
            end else begin
credit <= credit + {1'b0, leg_q};
leg_q  <= 1'b0;
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
leg_q   <= 1'b1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
leg_q     <= 1'b1;
                    end
                S_STARTED:
                   if (fin_ev) begin
                       stage <= S_FINISH;
steps  <= steps + {1'b0, credit} + {2'b0, leg_q} + 3'd1;
                      credit <= 2'd0;
leg_q  <= 1'b0;
                   end
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
   assign o_done  = (stage == S_FINISH) && (steps == 3'd3);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
   // an abort reaches FINISH without walking the chain, so a FINISH that the
   // done output is allowed to honour must show all three transitions counted
   always @(posedge i_clk)
       if (stage == S_FINISH)
           assert (steps == 3'd3);
endmodule

module dma_burst_engine (
    input  wire       clk,
    input  wire       i_ce,     // idle condition: low freezes all state
    input  wire       start,    // Q: opens the status window
    input  wire [3:0] len,      // requested burst length (beats)
    input  wire       ack,      // R: host acknowledges, closes the window
    output reg        busy,
    output reg  [3:0] beats
);
    // shadow register: records the length that was requested earlier
    reg [3:0] req_len;
    // beats actually pushed out so far in the current burst
    reg [3:0] done_cnt;
    // window register: set by start, cleared by ack
    reg       armed;
   // beats deferred past the 8-beat hardware burst limit of the current request
   reg [3:0] resid;
// credit-return coalescing: the fabric returns completion credit in groups of
// four, so beats already pushed may sit here before reaching done_cnt
reg [2:0] pend;
// fabric issue stage: a beat handed to the fabric in this cycle has left
// beats but its completion credit only arrives on the following cycle
reg        iq;
// the fabric completion path is four cycles deep: a beat handed over now
// walks three further stages before its credit can be counted
reg        iq2;
reg        iq3;
reg        iq4;
// secondary scrub channel: the fabric asks for a short refresh burst between
// host bursts. It shares the single issue stage and credit counter with the
// host burst channel, so the credit path belongs to one channel at a time.
reg [3:0] scr_beats;
// credit path owner: 0 = host burst channel, 1 = scrub channel
reg       own;

    initial busy     = 1'b0;
    initial beats    = 4'd0;
    initial req_len  = 4'd0;
    initial done_cnt = 4'd0;
    initial armed    = 1'b0;
   initial resid    = 4'd0;
initial pend     = 3'd0;
initial iq       = 1'b0;
initial iq2      = 1'b0;
initial iq3      = 1'b0;
initial iq4      = 1'b0;
initial scr_beats = 4'd0;
initial own       = 1'b0;

// ownership of the credit path only changes hands while no credit is in flight
wire pipe_occ   = iq || iq2 || iq3 || iq4;
wire path_empty = !pipe_occ && (pend == 3'd0);

wire accept = start && !armed && (len != 4'd0) && (!own || path_empty);
   // the fabric accepts at most 8 beats in one burst; the rest is deferred
   wire [3:0] chunk = (len > 4'd8) ? 4'd8 : len;
wire [2:0] pend_nxt  = (pend == 3'd3) ? 3'd0 : pend + 3'd1;
// a start the host channel cannot take (its status window is still open) is
// turned into a scrub burst on the secondary channel
wire scr_load = start && armed && (scr_beats == 4'd0);
wire scr_push = (scr_beats != 4'd0) && (own || path_empty);

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
               beats    <= chunk;
                req_len  <= len;      // shadow capture of the earlier event
               resid    <= len - chunk;
                done_cnt <= 4'd0;
pend     <= 3'd0;
iq       <= 1'b0;
iq2      <= 1'b0;
iq3      <= 1'b0;
iq4      <= 1'b0;
                busy     <= 1'b1;
                armed    <= 1'b1;
own      <= 1'b0;   // the host burst channel takes the credit path
end else if (busy && !own && beats != 4'd0) begin
               beats    <= (beats == 4'd1 && resid != 4'd0) ? resid : beats - 4'd1;
resid    <= (beats == 4'd1) ? 4'd0 : resid;
// one beat is handed to the fabric now; it must cross all four
// completion stages before its credit lands
iq       <= 1'b1;
iq2      <= iq;
iq3      <= iq2;
iq4      <= iq3;
// the beat issued four cycles ago returns its credit now, and is held
// here until a full group of four is ready
pend     <= iq4 ? pend_nxt : pend;
done_cnt <= (iq4 && pend == 3'd3) ? done_cnt + 4'd4 : done_cnt;
busy     <= 1'b1;
end else if (busy && !own && pipe_occ) begin
// every beat has been issued: walk what is still in flight down the
// completion stages until they and the credit counter are both empty
iq       <= 1'b0;
iq2      <= iq;
iq3      <= iq2;
iq4      <= iq3;
pend     <= iq4 ? pend_nxt : pend;
done_cnt <= (iq4 && pend == 3'd3) ? done_cnt + 4'd4 : done_cnt;
busy     <= (iq || iq2 || iq3) || ((iq4 ? pend_nxt : pend) != 3'd0);
end else if (busy && !own) begin
// trailing partial credit group flushed before the burst reports done
done_cnt <= done_cnt + {1'b0, pend};
pend     <= 3'd0;
busy     <= 1'b0;
end else if (scr_push) begin
// the scrub channel pushes a beat into the shared issue stage
scr_beats <= scr_beats - 4'd1;
iq        <= 1'b1;
iq2       <= iq;
iq3       <= iq2;
iq4       <= iq3;
pend      <= iq4 ? pend_nxt : pend;
own       <= 1'b1;
end else if (own && pipe_occ) begin
// scrub beats cross the same four completion stages
iq        <= 1'b0;
iq2       <= iq;
iq3       <= iq2;
iq4       <= iq3;
pend      <= iq4 ? pend_nxt : pend;
end else if (own) begin
// scrub traffic is never reported to the host: drop its partial credit
// group and hand the credit path back
pend      <= 3'd0;
own       <= 1'b0;
end else if (scr_load) begin
scr_beats <= 4'd4;
            end else if (armed && ack) begin
                armed    <= 1'b0;
            end
        end
    end

    // P, part 1: inside the window, while beats remain the burst cannot yet have
    // delivered everything that was requested earlier.
    always @(posedge clk)
        if (armed && busy)
            assert (done_cnt < req_len);

    // P, part 2: inside the window, once the engine is no longer busy the
    // delivered count must exactly match the earlier requested length.
    always @(posedge clk)
        if (armed && !busy)
            assert (done_cnt == req_len);

   // P, part 3: inside the window, while a deferred chunk is still queued the
   // beats already pushed plus the beats still held back must leave headroom
   // inside the length that was requested earlier.
   always @(posedge clk)
       if (armed && resid != 4'd0)
           assert (({1'b0,done_cnt} + {1'b0,resid}) < {1'b0,req_len});
endmodule

// Debug-probe challenge sequencer: a maximal-length LFSR supplies one tick per
// chain step (arm -> start -> finish). The LFSR is seeded non-zero and can never
// enter the all-zeros lockup state, so every FSM advance is accompanied by a
// genuine change of the challenge shift register.
module probe_chain_seq (
    input  wire       clk,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire       arm,
    input  wire       start,
    input  wire       fin,
    output reg  [1:0] stage,
    output reg        pre_done,
    output reg  [3:0] chal
);
    // stage encoding: 0 = IDLE, 1 = ARMED, 2 = RUNNING, 3 = DONE
    reg [3:0] lfsr;
    reg       pv;
    // channel B: second probe chain sharing the one challenge generator
    reg [1:0] stage_b;
    reg       own;      // 0 = chain A holds the generator, 1 = chain B
    reg       ld;       // generator context restore in flight (owner stalls)
    reg       chal_ok;  // chal holds a valid generator word
  // the challenge register is written over a 2-bit-wide debug bus, so a new
  // word lands in two beats: the low half is driven immediately and the high
  // half is staged here until the following enabled cycle
  reg [1:0] chal_hi;
  reg       chal_ph;  // high half still owed to the challenge register
   // per-chain generator context: a chain preempted by the arbiter resumes
   // its own point in the challenge stream when it gets the generator back
   reg [3:0] ctx_a;
   reg [3:0] ctx_b;
  // preemption save buffer: the context file is written over the same 2-bit
  // debug port as the challenge register, so a parked resume word lands low
  // half first and high half on the next free beat
  reg [1:0] ctx_hi;
  reg       ctx_ph;   // high half of a parked context still owed
  reg       ctx_sel;  // 0 = save targets ctx_a, 1 = targets ctx_b
   reg [2:0] tmr;      // round-robin time slice for the shared generator

    initial lfsr     = 4'b0001;
    initial chal     = 4'b0000;
    initial stage    = 2'd0;
    initial pre_done = 1'b1;   // before-scope: high until the first DONE ever
    initial pv       = 1'b0;
    initial stage_b  = 2'd0;
    initial own      = 1'b0;
    initial ld       = 1'b0;
    initial chal_ok  = 1'b0;
  initial chal_hi  = 2'b00;
  initial chal_ph  = 1'b0;
   initial ctx_a    = 4'b0000;
   initial ctx_b    = 4'b0000;
  initial ctx_hi   = 2'b00;
  initial ctx_ph   = 1'b0;
  initial ctx_sel  = 1'b0;
   initial tmr      = 3'd7;

    // x^4 + x^3 + 1 : period 15 over the non-zero states
    wire       fb        = lfsr[3] ^ lfsr[2];
    wire [3:0] lfsr_next = {lfsr[2:0], fb};

   // A chain that has left IDLE owns a parked generator word and resumes from
   // it; a chain that is IDLE starts cold from the last challenge issued on
   // the shared bus, or from the cold seed if none has been issued yet.
   wire       in_a      = (stage   != 2'd0);
   wire       in_b      = (stage_b != 2'd0);
   wire [3:0] cold      = chal_ok ? chal : 4'b0001;
   wire [3:0] lfsr_rest = own ? (in_b ? ctx_b : cold)
                              : (in_a ? ctx_a : cold);

    // the current owner releases the generator once its chain reaches DONE
    wire a_done = (stage   == 2'd3);
    wire b_done = (stage_b == 2'd3);
   // ... or when its arbitration time slice expires, so a chain that stalls
   // mid-run cannot hold the shared generator forever
   wire slice_up = (tmr == 3'd0);
  // a preemption cannot start while the previous context save is still
  // draining, or the parked word would be half of one chain and half of
  // another
  wire yield    = !ld && !ctx_ph && (slice_up || (own ? b_done : a_done));

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            lfsr <= ld ? lfsr_rest : lfsr_next;
           if (yield) begin
               own <= ~own;
              // park the outgoing chain's stream: low half straight away,
              // high half staged for the save buffer
              if (own) ctx_b[1:0] <= lfsr_next[1:0];
              else     ctx_a[1:0] <= lfsr_next[1:0];
              ctx_hi  <= lfsr_next[3:2];
              ctx_sel <= own;
              ctx_ph  <= 1'b1;
               tmr <= 3'd7;
           end else if (!ld) begin
               tmr <= tmr - 3'd1;
           end
            ld <= yield;
          // second beat: the staged high half lands and the challenge word
          // becomes valid for chains that start cold from the shared bus
          if (chal_ph) begin
              chal[3:2] <= chal_hi;
              chal_ok   <= 1'b1;
              chal_ph   <= 1'b0;
          end
         // the save buffer drains on the first beat the debug port is not
         // carrying a challenge half
         if (ctx_ph && !chal_ph) begin
             if (ctx_sel) ctx_b[3:2] <= ctx_hi;
             else         ctx_a[3:2] <= ctx_hi;
             ctx_ph <= 1'b0;
         end
            if (!ld) begin
            if (!own) begin
            case (stage)
               2'd0: if (arm && !chal_ph) begin
                          stage <= 2'd1;
                         chal[1:0] <= lfsr[1:0];   // first beat on the bus
                         chal_hi   <= lfsr[3:2];    // high half next cycle
                         chal_ph   <= 1'b1;
                         chal_ok   <= 1'b0;         // incomplete until commit
                     ctx_a <= lfsr_next;  // resume point for this chain
                      end
                2'd1: if (start) stage <= 2'd2;
                2'd2: if (fin) begin
                          stage    <= 2'd3;   // finish: clears the before-scope
                          pre_done <= 1'b0;
                      end
                default: stage <= 2'd0;
            endcase
            end else begin
                case (stage_b)
                   2'd0: if (arm && !chal_ph) begin
                              stage_b <= 2'd1;
                             chal[1:0] <= lfsr[1:0];
                             chal_hi   <= lfsr[3:2];
                             chal_ph   <= 1'b1;
                             chal_ok   <= 1'b0;
                             ctx_b <= lfsr_next;
                          end
                    2'd1: if (start) stage_b <= 2'd2;
                    2'd2: if (fin)   stage_b <= 2'd3;
                    default: stage_b <= 2'd0;
                endcase
            end
            end
        end
    end

    // P: before the first finish has ever been observed, the chain FSM cannot
    //    move unless the challenge shift register moved with it.
    always @(posedge clk)
        if (pv && pre_done && $stable(lfsr))
            assert ($stable(stage));

   // Q: a chain that has been armed has a live challenge on the bus, so once
   //    chain A is running the challenge register reads back non-zero -- the
   //    only exception is the single beat where the high half is still owed.
   always @(posedge clk)
       if (pv && stage == 2'd2)
           assert (chal != 4'd0 || chal_ph);
endmodule

module deb_evt_fifo (
    input  wire clk,
    input  wire i_ce,      // sample enable: low freezes all state
    input  wire raw,       // raw (noisy) button level
    input  wire pop,       // consumer request
    output wire empty,
    output wire full,
    output reg  o_level    // last popped debounced level
);
    // ---- debouncer: saturating stability counter ----
    reg [1:0] stab;
    reg       deb;

    // ---- event FIFO: pointers + occupancy ----
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg [1:0] tail;        // shadow: write pointer snapshot taken at the last push
    reg       mem [0:3];
   reg [1:0] wnext;       // precomputed next write address (shared write-port adder)

   // ---- refresh generator: periodic level-refresh events ----
   // second producer on the shared FIFO write port: every fourth sample it
   // re-posts the current debounced level so a stalled consumer still gets a
   // fresh entry. Edge events own the port; a coincident refresh is held.
   reg [1:0] hb;
   reg       hb_pend;

   // ---- event ledger: free-running push/pop transfer counters ----
// a push is logged when the entry is written, a pop when the consumer's
// request is accepted, so the ledger difference is the number of entries
// not yet spoken for; empty is taken from it and therefore also throttles
// request acceptance. full is taken from the occupancy accumulator: a slot
// whose read is still in flight is not free for rewrite.
   reg [2:0] n_push, n_pop;
   wire [2:0] occ = n_push - n_pop;   // outstanding entries, mod 8

  // ---- read data phase: four-sample memory access latency ----
  // a pop request is acknowledged to the ledger the sample it is accepted,
  // but the entry is only retired -- rptr stepped and o_level updated --
  // when the request walks out of the access pipeline four samples later.
  reg       pop_s0, pop_s1, pop_s2, pop_s3;

  // ---- registered write port: capture stage in front of the array ----
  // the array has a registered write path: a push captures the slot address
  // and the level on one sample and the array cell is written the next. the
  // write pointer advances at capture so a following event addresses the next
  // slot, but the slot only counts as occupancy once the write has landed,
  // and the capture stage holds one transfer, so a push waits while one is in
  // flight. the entry is announced to the consumer at capture: the read data
  // phase is four samples long, so the write has landed before the read runs.
  reg       wr_pend;
  reg [1:0] wr_addr;
  reg       wr_data;

  // ---- array port ledger: free-running write/read access counters ----
  // the arbiter logs every array access: a write when it lands, a read when
  // its data phase runs. the excess of landed writes over performed reads is
  // the number of slots resident in the array, and a resident slot is not
  // available for rewrite, so the write-side backpressure comes from here.
  reg [2:0] n_wr, n_rd;
  wire [2:0] resident = n_wr - n_rd;

   // ---- free-slot counter: write-side backpressure ----
   // the write port books a slot when a transfer is captured and releases
   // it when that entry's read data phase runs, so a slot reserved for a
   // capture still in flight is never offered to a second producer.
   reg [2:0] space;


    // ---- scope register: high until the FIFO has ever been full ----
    reg       never_full;

    // ---- past-valid ----
    reg       pv;

    initial begin
        stab = 2'd0; deb = 1'b0;
        wptr = 2'd0; rptr = 2'd0; count = 3'd0;
        tail = 2'd0;
       wnext = 2'd1;
       hb = 2'd0; hb_pend = 1'b0;
       n_push = 3'd0; n_pop = 3'd0;
      wr_pend = 1'b0; wr_addr = 2'd0; wr_data = 1'b0;
      n_wr = 3'd0; n_rd = 3'd0;
     space = 3'd4;
pop_s0 = 1'b0; pop_s1 = 1'b0; pop_s2 = 1'b0; pop_s3 = 1'b0;
        never_full = 1'b1;
        pv = 1'b0;
        o_level = 1'b0;
        mem[0] = 1'b0; mem[1] = 1'b0; mem[2] = 1'b0; mem[3] = 1'b0;
    end

   assign empty = (occ == 3'd0);
assign full  = (resident == 3'd4) || (space == 3'd0);

    // a debounced edge is committed once raw has disagreed with deb for 3 samples
    wire deb_commit = (raw != deb) && (stab == 2'd2);

   wire hb_req   = (hb == 2'd3) || hb_pend;
   wire push_req = deb_commit || hb_req;
wire do_push  = i_ce && push_req && !full && !wr_pend;  // capture at the write port
wire wr_cmt   = i_ce && wr_pend;                        // captured transfer lands
wire pop_ack = i_ce && pop && !empty;   // request accepted this sample
wire do_pop  = i_ce && pop_s3;          // its data phase, four samples on

    always @(posedge clk) begin
        if (i_ce) begin
            if (raw != deb) begin
                if (stab == 2'd2) stab <= 2'd0;
                else              stab <= stab + 2'd1;
            end else begin
                stab <= 2'd0;
            end
            if (deb_commit) deb <= raw;

           // the captured transfer reaches the array one sample on
           if (wr_cmt) begin
               mem[wr_addr] <= wr_data;
               wr_pend      <= 1'b0;
           end


            if (do_push) begin
              wr_pend   <= 1'b1;
              wr_addr   <= wptr;
              wr_data   <= deb_commit ? raw : deb;
               wptr      <= wnext;
               tail      <= wnext;
               wnext     <= wnext + 2'd1;
            end

           // the refresh prescaler runs off the sample clock; a refresh
           // request retires only once it actually wins the write port
           hb <= hb + 2'd1;
if (hb_req) hb_pend <= deb_commit || full || wr_pend;

           // walk accepted read requests down the access pipeline
           pop_s0 <= pop_ack;
           pop_s1 <= pop_s0;
           pop_s2 <= pop_s1;
           pop_s3 <= pop_s2;

            if (do_pop) begin
                o_level <= mem[rptr];
                rptr    <= rptr + 2'd1;
            end

// log the push at the write and the pop at the accept, so the
// difference excludes reads that are still in flight
           if (do_push) n_push <= n_push + 3'd1;
if (pop_ack) n_pop  <= n_pop  + 3'd1;

          // and log the array accesses themselves
          if (wr_cmt) n_wr <= n_wr + 3'd1;
          if (do_pop) n_rd <= n_rd + 3'd1;

case ({wr_cmt, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase

           // free-slot accounting: booked at capture, released at read
           case ({do_push, do_pop})
               2'b10:   space <= space - 3'd1;
               2'b01:   space <= space + 3'd1;
               default: space <= space;
           endcase

            if (count == 3'd4) never_full <= 1'b0;
        end
        pv <= 1'b1;
    end

    // Precedence, before-first-full scope, stated about the previous cycle:
    // if the queue has just been drained empty by a pop, the read pointer must
    // have reached the write-pointer snapshot recorded at the earlier push.
    always @(posedge clk)
        if (pv && never_full && (count == 3'd0) && $past(do_pop))
            assert (rptr == $past(tail));

   // A full queue is a wrapped queue: with no free slot left the write
   // pointer has caught up with the read pointer.
   always @(posedge clk)
       assert (!full || (wptr == rptr));
endmodule

module window_rate_limiter (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_req,
output wire o_grant,
output wire [2:0] o_n_in,
output wire [2:0] o_n_out
);
    parameter W     = 4;
    parameter LIMIT = 3;

    // sliding window of the last W grant decisions
    reg [W-1:0] win;
    // count of ones that mirrors the window by construction
    reg [2:0]   ones;
   // admit decision in flight toward the accumulator: the count update is
   // retimed through one register stage, so `ones` trails the window by a beat
   reg         adm_q;
   // issue pipeline: a granted request spends four cycles travelling from the
   // decision point to the head of the window, one stage per cycle
   reg         s1;
   reg         s2;
   reg         s3;
   reg         s4;
  // credit-return pipeline: a slot that falls off the far end of the window
  // walks four stages of the accounting block before its credit is handed
  // back to the retire ledger, one stage per enabled cycle
  reg         d1;
  reg         d2;
  reg         d3;
  reg         d4;
    // sticky arm register: set the first time a grant is ever issued
    reg         armed;
   // post-grant cooldown: a grant is followed by two enabled cycles of refusal
   reg [1:0]   gap;
    reg         pv;
// issue/retire ledger: one tick per admit pushed into the window, one per
// slot that falls off the far end. Free running, they wrap at three bits.
reg [2:0]   n_in;
reg [2:0]   n_out;

    initial win   = 0;
    initial ones  = 0;
   initial adm_q = 0;
   initial s1    = 0;
   initial s2    = 0;
   initial s3    = 0;
   initial s4    = 0;
  initial d1    = 0;
  initial d2    = 0;
  initial d3    = 0;
  initial d4    = 0;
    initial armed = 0;
   initial gap   = 0;
    initial pv    = 0;
initial n_in  = 0;
initial n_out = 0;

    // the bit about to leave the window
    wire [2:0] retiring = win[W-1] ? 3'd1 : 3'd0;
    // occupancy of the window once the oldest slot retires
   // plus the admit still in flight, which the accumulator has not absorbed yet
   wire [2:0] eff      = ones - retiring + (adm_q ? 3'd1 : 3'd0);
// occupancy straight off the ledger: n_in ticks when an admit is issued into
// the pipeline and n_out when a slot retires, so the difference covers the
// window and everything still in flight behind it
wire [2:0] occ  = n_in - n_out;
// the same figure once the oldest slot has retired
wire [2:0] live = occ - retiring;

// rate decision is taken from the ledger, which is exact for this cycle,
   // and is additionally blocked while the post-grant cooldown is running
wire allow = i_req && (live < LIMIT) && (gap == 2'd0);
// the retimed accumulator now sizes the cooldown instead: a window already
// carrying two admits earns the long pause, a lightly loaded one a short one
wire [1:0] cool = (eff >= 3'd2) ? 2'd2 : 2'd1;

    assign o_grant = i_ce && allow;
assign o_n_in  = n_in;
assign o_n_out = n_out;

    always @(posedge clk) begin
        if (i_rst) begin
            win   <= 0;
            ones  <= 0;
           adm_q <= 0;
           s1    <= 0;
           s2    <= 0;
           s3    <= 0;
           s4    <= 0;
          d1    <= 0;
          d2    <= 0;
          d3    <= 0;
          d4    <= 0;
            armed <= 0;
           gap   <= 0;
n_in  <= 0;
n_out <= 0;
        end else if (i_ce) begin
win   <= { win[W-2:0], s4 };
           ones  <= ones - retiring + (adm_q ? 3'd1 : 3'd0);
adm_q <= s4;
s1    <= allow;
s2    <= s1;
s3    <= s2;
s4    <= s3;
if (allow)
    n_in  <= n_in  + 3'd1;
d1    <= win[W-1];
d2    <= d1;
d3    <= d2;
d4    <= d3;
if (d4)
    n_out <= n_out + 3'd1;
            if (allow)
                armed <= 1'b1;
if (s4)
gap <= cool;
           else if (gap != 2'd0)
               gap <= gap - 2'd1;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    // Precedence, after the limiter has armed: a grant observed one cycle ago
    // must have been preceded by a window that was not already saturated, so
    // the window can never be completely full of grants.
    always @(posedge clk)
        if (pv && armed)
            assert (!($past(i_ce) && $past(allow)) || (win != 4'hF));

   // Cooldown consistency: halfway through a cooldown the grant that started it
   // is still resident in the window, so the mirrored occupancy is not empty.
   always @(posedge clk)
       if (pv)
           assert ((gap != 2'd1) || (ones != 3'd0 || adm_q));
endmodule

module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] req,
    output reg  [3:0] gnt,
output reg  [1:0] stage,
output reg  [3:0] act_cnt
);
    // round-robin arbiter state
    reg [1:0] last_gnt;
    // chain-precedence bookkeeping: arm (line0) -> start (line1) -> finish (line2)
    reg       seen_arm;
    reg       seen_start;
    // sticky scope register: set the first time any grant is issued
    reg       armed;
   // peer chain B: shares the start unit with chain A
   // arm(line2) -> start(line3) -> finish(line1)
   reg [1:0] stage_b;
   // shared start unit is primed and not yet consumed
   reg       start_tok;
  // peer chain C: second port on the same shared start unit
  // arm(line1) -> start(line2) -> finish(line0)
  reg [1:0] stage_c;
  // port C's primed-and-unconsumed flag
  reg       start_tok_c;
 // shared-start-unit ledger: one entry logged per acquire, one per release
 reg [3:0] tok_acq;
 reg [3:0] tok_rel;
  // posted stage-update pipe: a chain A stage advance is handed to the
  // writeback pipe and only lands on the stage register four cycles later.
  // 2'd0 in a slot means "nothing posted here".
  reg [1:0] upd_p0;
  reg [1:0] upd_p1;
  reg [1:0] upd_p2;
  reg [1:0] upd_p3;
// distractor: previous request vector, used only for the activity counter
reg [3:0] req_prev;

    initial begin
        last_gnt   = 2'd3;
        gnt        = 4'b0000;
        stage      = 2'd0;
        seen_arm   = 1'b0;
        seen_start = 1'b0;
        armed      = 1'b0;
       stage_b    = 2'd0;
       start_tok  = 1'b0;
      stage_c     = 2'd0;
      start_tok_c = 1'b0;
     tok_acq    = 4'd0;
     tok_rel    = 4'd0;
      upd_p0     = 2'd0;
      upd_p1     = 2'd0;
      upd_p2     = 2'd0;
      upd_p3     = 2'd0;
req_prev   = 4'b0000;
act_cnt    = 4'd0;
    end

    // combinational round-robin grant: one-hot, never on a non-requesting line
    reg [3:0] gnt_c;
    always @(*) begin
        case (last_gnt)
            2'd0: gnt_c = req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 : 4'b0000;
            2'd1: gnt_c = req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 : 4'b0000;
            2'd2: gnt_c = req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 : 4'b0000;
            default: gnt_c = req[0] ? 4'b0001 :
                             req[1] ? 4'b0010 :
                             req[2] ? 4'b0100 :
                             req[3] ? 4'b1000 : 4'b0000;
        endcase
    end

    wire [1:0] gnt_idx = gnt_c[0] ? 2'd0 :
                         gnt_c[1] ? 2'd1 :
                         gnt_c[2] ? 2'd2 : 2'd3;

    wire fire = i_ce && (gnt_c != 4'b0000);
  // only one stage update may be outstanding in the pipe
  wire upd_busy = (upd_p0 | upd_p1 | upd_p2 | upd_p3) != 2'd0;
 // ledger view of the shared start unit: a nonzero balance means some
 // acquire has not been returned yet, so the unit is still primed
 wire [3:0] tok_bal  = tok_acq - tok_rel;
 wire       tok_out  = (tok_bal != 4'd0);
 // acquire side: chain B primes the unit on its START step
 wire       tok_grab = fire && (stage_b == 2'd1) && gnt_c[3];
 // return side: B consumes it, or chain A tears it down on abort/retire.
 // a teardown that finds no held unit is not a return, so it is not logged.
 wire       tok_drop = fire && !tok_grab && start_tok &&
                       (((stage_b == 2'd2) && gnt_c[1]) ||
                        (stage == 2'd3) ||
                        (((stage == 2'd1) || (stage == 2'd2)) && gnt_c[3]));
// port C acquires on its START step and returns it on its FINISH step;
// a chain A teardown tears the peer port down as well
wire       tok_grab_c = fire && (stage_c == 2'd1) && gnt_c[2];
wire       tok_drop_c = fire && !tok_grab_c && start_tok_c &&
                       (((stage_c == 2'd2) && gnt_c[0]) ||
                        (stage == 2'd3) ||
                        (((stage == 2'd1) || (stage == 2'd2)) && gnt_c[3]));

    always @(posedge clk) begin
        gnt <= fire ? gnt_c : 4'b0000;
// shared-start-unit ledger, free running, wraps at 4 bits;
// both ports log through the same pair of counters
tok_acq <= tok_acq + {3'd0, tok_grab} + {3'd0, tok_grab_c};
tok_rel <= tok_rel + {3'd0, tok_drop} + {3'd0, tok_drop_c};
      if (i_ce) begin
          // last slot retires onto the stage register, then the pipe shifts
          if (upd_p3 != 2'd0)
              stage <= upd_p3;
          upd_p3 <= upd_p2;
          upd_p2 <= upd_p1;
          upd_p1 <= upd_p0;
          upd_p0 <= 2'd0;
      end
        if (fire) begin
            last_gnt <= gnt_idx;
            armed    <= 1'b1;
            case (stage)
                2'd0: begin
                   if (gnt_c[0] && !upd_busy) begin
                       upd_p0   <= 2'd1;   // post ARM step
                        seen_arm <= 1'b1;
                    end
                end
                2'd1: begin
                   if (gnt_c[1] && !upd_busy) begin
                       upd_p0     <= 2'd2; // post START step
                        seen_start <= 1'b1;
end else if (tok_out && gnt_c[2] && !upd_busy) begin
                      upd_p0     <= 2'd3; // start unit already primed: skip START
                   end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                       start_tok  <= 1'b0; // release shared start unit
start_tok_c <= 1'b0; // tear down the peer port as well
                      upd_p0     <= 2'd0; // abort flushes the posted update
                      upd_p1     <= 2'd0;
                      upd_p2     <= 2'd0;
                      upd_p3     <= 2'd0;
                    end
                end
                2'd2: begin
                   if (gnt_c[2] && !upd_busy) begin
                       upd_p0 <= 2'd3;     // post FINISH step
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                       start_tok  <= 1'b0; // release shared start unit
start_tok_c <= 1'b0; // tear down the peer port as well
                      upd_p0     <= 2'd0; // abort flushes the posted update
                      upd_p1     <= 2'd0;
                      upd_p2     <= 2'd0;
                      upd_p3     <= 2'd0;
                    end
                end
                default: begin
                    stage      <= 2'd0;     // retire transaction
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                   start_tok  <= 1'b0;     // release shared start unit
start_tok_c <= 1'b0;     // tear down the peer port as well
                  upd_p0     <= 2'd0;     // nothing left to post
                  upd_p1     <= 2'd0;
                  upd_p2     <= 2'd0;
                  upd_p3     <= 2'd0;
                end
            endcase
           // peer chain B drives the same start unit from the high lines
           case (stage_b)
               2'd0: if (gnt_c[2]) stage_b <= 2'd1;   // ARM step (B)
               2'd1: if (gnt_c[3]) begin
                         stage_b    <= 2'd2;          // START step (B)
                         seen_start <= 1'b1;          // shared unit has run
                         start_tok  <= 1'b1;          // and stays primed
                     end
               2'd2: if (gnt_c[1]) begin
                         stage_b   <= 2'd3;           // FINISH step (B)
                         start_tok <= 1'b0;           // B consumes the unit
                     end
               default: stage_b <= 2'd0;              // retire B
           endcase
          // peer chain C drives the second port of the same start unit
          case (stage_c)
              2'd0: if (gnt_c[1]) stage_c <= 2'd1;   // ARM step (C)
              2'd1: if (gnt_c[2]) begin
                        stage_c     <= 2'd2;         // START step (C)
                        seen_start  <= 1'b1;         // shared unit has run
                        start_tok_c <= 1'b1;         // and stays primed
                    end
              2'd2: if (gnt_c[0]) begin
                        stage_c     <= 2'd3;         // FINISH step (C)
                        start_tok_c <= 1'b0;         // C consumes the unit
                    end
              default: stage_c <= 2'd0;              // retire C
          endcase
        end
// distractor activity counter: counts request-vector changes while enabled
if (i_ce) begin
req_prev <= req;
if (req != req_prev)
act_cnt <= act_cnt + 4'd1;
end
    end

    // P: once the arbiter has ever granted (sticky armed), a finished
    // transaction can only be observed if arm and start really happened.
    always @(posedge clk)
        if (armed && stage == 2'd3)
            assert (seen_arm && seen_start);
endmodule

module chess_clock_seq_alarm (
    input  wire clk,
    input  wire i_ce,      // clock tick enable; low freezes the whole mechanism
    input  wire sym,       // observed press: 1 = white side, 0 = black side
    output reg  alarm
);
    // match-progress register for the fixed press pattern 1,0,1,1
    // (white, black, white, white) -- the blitz alarm trigger
    reg [2:0] prog;
    // shadow register: latches that the half-way progress (2 symbols) occurred
    reg       seen_half;
    // "before R" scope register: high until the alarm pattern first completes
    reg       before_alarm;
   // commit stage: the decoder's next-progress value waits one tick here
   // before it is retired into the matcher, keeping the decode path short
   reg [2:0] stg;
   reg       stg_v;       // a staged progress value is pending commit
  // black-turn tally: how many times the matcher has passed the half-way
  // point since power-up. The blitz time control also ends the game once
  // this tally reaches its limit of seven, so it feeds the alarm too.
  reg [2:0] hcnt;
 // black-side peer matcher for the press pattern 0,1,0,0 (black, white,
 // black, black) -- the other side's blitz trigger. It shares the commit
 // stage and the tally's single increment port with the white-side matcher.
 reg [2:0] prog2;
 reg [2:0] stg2;
 // the tally adder accepts one increment per tick; a half-way pass that
 // loses the arbitration is owed and is retired in the commit phase
 reg       hpend;
 reg       harb;   // round-robin pointer for the tally increment port
// black-side half-way shadow, the peer of seen_half.  Both shadows are
// written through one shared notice slot: a matcher that crosses its
// half-way point posts a notice here and the slot retires it into the
// selected shadow on the following tick.
reg       seen_half2;
reg       nq_v;   // a half-way notice is waiting in the slot
reg       nq_s;   // 0 = white shadow, 1 = black shadow
// four-deep retire pipeline: a committed progress pair walks cm1..cm4
// (white) / cn1..cn4 (black) one hop per tick before it lands in the
// matchers, so the retire bus is registered at every hop.  cv1..cv4 mark
// which hop currently carries the press in flight.
reg [2:0] cm1, cm2, cm3, cm4;
reg [2:0] cn1, cn2, cn3, cn4;
reg       cv1, cv2, cv3, cv4;

    initial prog         = 3'd0;
    initial seen_half    = 1'b0;
    initial before_alarm = 1'b1;
    initial alarm        = 1'b0;
   initial stg          = 3'd0;
   initial stg_v        = 1'b0;
  initial hcnt         = 3'd0;
 initial prog2        = 3'd0;
 initial stg2         = 3'd0;
 initial hpend        = 1'b0;
 initial harb         = 1'b0;
initial seen_half2   = 1'b0;
initial nq_v         = 1'b0;
initial nq_s         = 1'b0;
initial cm1          = 3'd0;
initial cm2          = 3'd0;
initial cm3          = 3'd0;
initial cm4          = 3'd0;
initial cn1          = 3'd0;
initial cn2          = 3'd0;
initial cn3          = 3'd0;
initial cn4          = 3'd0;
initial cv1          = 1'b0;
initial cv2          = 1'b0;
initial cv3          = 1'b0;
initial cv4          = 1'b0;

    reg [2:0] nxt;
   reg [2:0] nxt2;
  // a new press may only be taken once the retire pipeline has drained
  wire idle = !stg_v && !cv1 && !cv2 && !cv3 && !cv4;
   // a press is only consumed in the decode phase
  wire match = (prog == 3'd3) && sym && idle;
 wire match2 = (prog2 == 3'd3) && !sym && idle;
  // tally requests: either matcher asks when it passes its half-way point
  wire req1 = (nxt  == 3'd2);
  wire req2 = (nxt2 == 3'd2);
  wire gnt1 = req1 && (!req2 || !harb);
  wire gnt2 = req2 && (!req1 ||  harb);

    always @(*) begin
        case (prog)
            3'd0: nxt = sym ? 3'd1 : 3'd0;
            3'd1: nxt = sym ? 3'd1 : 3'd2;
            3'd2: nxt = sym ? 3'd3 : 3'd0;
            3'd3: nxt = sym ? 3'd0 : 3'd2;  // overlap: "10" survives
            default: nxt = 3'd0;
        endcase
    end

   always @(*) begin
       case (prog2)
           3'd0: nxt2 = sym ? 3'd0 : 3'd1;
           3'd1: nxt2 = sym ? 3'd2 : 3'd1;
           3'd2: nxt2 = sym ? 3'd0 : 3'd3;
           3'd3: nxt2 = sym ? 3'd2 : 3'd0;  // overlap: "01" survives
           default: nxt2 = 3'd0;
       endcase
   end

    always @(posedge clk) begin
        if (i_ce) begin
          // the retire pipeline advances one hop on every tick
          cm1 <= stg;   cn1 <= stg2;   cv1 <= stg_v;
          cm2 <= cm1;   cn2 <= cn1;    cv2 <= cv1;
          cm3 <= cm2;   cn3 <= cn2;    cv3 <= cv2;
          cm4 <= cm3;   cn4 <= cn3;    cv4 <= cv3;
          if (cv4) begin
              // retire phase: the value that has walked the whole pipeline
              // lands in the two matchers
              prog      <= cm4;
              prog2     <= cn4;
              if (cm4 == 3'd0)
                  seen_half <= 1'b0;   // white matcher restarted
if (cn4 == 3'd0)
    seen_half2 <= 1'b0;  // black matcher restarted
          end
          if (idle) begin
               // decode phase: consume the press, stage the new progress
               stg       <= nxt;
              stg2      <= nxt2;
               stg_v     <= 1'b1;
// post the half-way crossing into the shared shadow notice slot
nq_v      <= req1 | req2;
nq_s      <= !req1;
             if ((gnt1 || gnt2) && (hcnt != 3'd7))
                 hcnt <= hcnt + 3'd1;
             // whichever half-way pass lost the port is owed an increment
             hpend     <= (req1 && !gnt1) || (req2 && !gnt2);
             if (req1 && req2)
                 harb <= ~harb;
              // the alarm sounds on the pattern match, and also on the press
              // that takes the black-turn tally to its limit
             alarm     <= match | match2 |
                          ((gnt1 || gnt2) && (hcnt == 3'd6));
               if (match)
                   before_alarm <= 1'b0;
          end else if (stg_v) begin
              // commit phase: the staged press is handed to the retire
              // pipeline, so the tally adder is free for the owed increment
               stg_v     <= 1'b0;
             // the owed increment retires now that the adder is idle
             if (hpend && (hcnt != 3'd7))
                 hcnt <= hcnt + 3'd1;
             hpend     <= 1'b0;
             alarm     <= hpend && (hcnt == 3'd6);
           end
          else begin
              // the retire pipeline is still draining: no new alarm source
              alarm     <= 1'b0;
          end
// shadow retire: the notice posted last tick lands in its shadow
if (nq_v) begin
    nq_v <= 1'b0;
    if (!nq_s)
        seen_half  <= 1'b1;
    else
        seen_half2 <= 1'b1;
    // warning chime: this crossing puts both sides past half-way
    if (nq_s ? seen_half : seen_half2)
        alarm <= 1'b1;
end
        end
    end

    // Precedence, in the scope before the alarm has ever fired:
    // three-quarter progress can only be observed if half progress happened earlier.
    always @(posedge clk)
        assert (!before_alarm || (prog != 3'd3) || seen_half);

   // Tally accounting, in the scope before the alarm has ever fired:
   // three-quarter progress cannot be on record while the black-turn tally
   // is still empty, because reaching it costs one black press.
   always @(posedge clk)
       assert (!before_alarm || (prog != 3'd3) || (hcnt != 3'd0));
endmodule

// Valid/ready pipeline stage with a skid buffer carrying a three-step
// command chain: ARM -> START -> FINISH -> ARM -> ...
// The buffered word is only meaningful while the stage is stalled.
module chain_skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,       // global enable / idle condition
    input  wire       in_valid,   // producer offers its next chain word
    input  wire       out_ready,  // consumer accepts
    output wire       o_valid,
    output wire [1:0] o_code,
output wire       o_in_ready,
output wire [3:0] o_fire_count
);
    localparam [1:0] ARM    = 2'd1;
    localparam [1:0] START  = 2'd2;
    localparam [1:0] FINISH = 2'd3;

    // producer chain position: next word emitted is src_phase+1
    reg [1:0] src_phase  = 2'd0;
    // consumer chain position: 0 = nothing armed, 1 = armed, 2 = started
    reg [1:0] phase      = 2'd0;

    // output (skid) register pair
    reg       out_valid  = 1'b0;
    reg [1:0] out_code   = ARM;
    reg       skid_valid = 1'b0;
    reg [1:0] skid_code  = ARM;

   // second (tail) skid slot: lets the stage swallow one more word when the
   // consumer stalls for two cycles in a row instead of dropping in_ready
   // immediately behind a single buffered word
   reg       skid2_valid = 1'b0;
   reg [1:0] skid2_code  = ARM;

   // one-cycle inter-chain gap: after a FINISH leaves the stage the
   // producer is held off for a cycle so it can resynchronise on the
   // head of the next chain
   reg       gap        = 1'b0;

// in-flight word ledger: every word taken from the producer and every word
// handed to the consumer is logged. The counters free-run and wrap; their
// difference is how many words the stage is currently holding, and that is
// what the backpressure below is derived from. The ledger only covers the
// main path (output register + head slot); see tail_cnt below.
// Both counters are exported packed on the trace port.
reg [1:0] n_in  = 2'd0;
reg [1:0] n_out = 2'd0;

// the tail slot was bolted on after the ledger existed, and rather than
// re-timing the ledger it keeps its own occupancy count; the backpressure
// below sums the two
reg [1:0] tail_cnt = 2'd0;

    wire [1:0] in_code  = src_phase + 2'd1;
wire [1:0] led_occ  = n_in - n_out;
wire [2:0] occ_all  = {1'b0, led_occ} + {1'b0, tail_cnt};
wire       in_ready = (occ_all != 3'd3) && !gap;
    wire       out_room = !out_valid || out_ready;
    wire       in_fire  = step && in_valid && in_ready;
    wire       out_fire = step && out_valid && out_ready;

// where an accepted word lands, and when the tail slot shifts into the head
wire       take_tail = in_valid && in_ready && skid_valid && !out_room;
wire       take_main = in_valid && in_ready && !(skid_valid && !out_room);
wire       tail_pop  = skid2_valid && out_room;

    assign o_valid    = out_valid;
    assign o_code     = out_code;
    assign o_in_ready = in_ready;
assign o_fire_count = {n_in, n_out};

    always @(posedge clk) begin
        if (rst) begin
            src_phase  <= 2'd0;
            phase      <= 2'd0;
            out_valid  <= 1'b0;
            out_code   <= ARM;
            skid_valid <= 1'b0;
            skid_code  <= ARM;
           skid2_valid <= 1'b0;
           skid2_code  <= ARM;
           gap        <= 1'b0;
n_in       <= 2'd0;
n_out      <= 2'd0;
tail_cnt   <= 2'd0;
        end else if (step) begin
            // output register: drain skid first, else take the fresh word
            if (out_room) begin
                if (skid_valid) begin
                    out_valid <= 1'b1;
                    out_code  <= skid_code;
               end else if (in_valid && in_ready) begin
                    out_valid <= 1'b1;
                    out_code  <= in_code;
                end else begin
                    out_valid <= 1'b0;
                end
            end

            // skid buffer: only loaded while the stage is stalled
            if (skid_valid) begin
               if (out_room) begin
                   // head drains into the output register; refill it from
                   // the tail slot, or straight from the producer
                   if (skid2_valid) begin
                       skid_valid <= 1'b1;
                       skid_code  <= skid2_code;
                   end else if (in_valid && in_ready) begin
                       skid_valid <= 1'b1;
                       skid_code  <= in_code;
                   end else begin
                       skid_valid <= 1'b0;
                   end
               end
           end else if (in_valid && in_ready && !out_room) begin
                skid_valid <= 1'b1;
                skid_code  <= in_code;
            end

           // tail slot: only fills behind a full head slot while the
           // output register is blocked, and always shifts down on a drain
           if (skid2_valid) begin
               if (out_room)
                   skid2_valid <= 1'b0;
           end else if (in_valid && in_ready && skid_valid && !out_room) begin
               skid2_valid <= 1'b1;
               skid2_code  <= in_code;
           end

            // producer advances on every accepted word
            if (in_valid && in_ready)
                src_phase <= (src_phase == 2'd2) ? 2'd0 : src_phase + 2'd1;

            // consumer chain tracker advances on every delivered word
            if (out_valid && out_ready)
                phase <= (out_code == FINISH) ? 2'd0 : out_code;

           // hold the producer off for one cycle after a completed chain
           gap <= out_valid && out_ready && out_code == FINISH;

n_in <= n_in + {1'b0, take_main} + {1'b0, tail_pop};
if (out_valid && out_ready)
    n_out <= n_out + 2'd1;
tail_cnt <= tail_cnt + {1'b0, take_tail} - {1'b0, tail_pop};
        end
    end

    // P (two assertions): a later chain step is never delivered unless the
    // earlier ones already were.
    always @(*)
        assert (!(out_fire && out_code == FINISH) || phase == 2'd2);

    always @(*)
        assert (!(out_fire && out_code == START) || phase == 2'd1);

   // Q: the only word that may leave the stage during the post-FINISH
   // gap cycle is the ARM that opens the next chain.
   always @(posedge clk)
       if (!rst)
           assert (!(gap && out_fire) || out_code == ARM);
endmodule

module token_bucket_deadline (
    input  wire clk,
    input  wire i_ce,
    input  wire req,
    output wire grant,
output wire expired,
output reg [3:0] grant_tally
);
    // burst size of the bucket and the response deadline for one request
    localparam [2:0] BURST   = 3'd4;
    localparam [3:0] TIMEOUT = 4'd6;

    reg [2:0] tokens;    // token bucket, capped at BURST
    reg [1:0] tick_cnt;   // refill timer, counts down, tick at zero
    reg       pending;    // window register: set by accepted request, cleared by grant
    reg [3:0] deadline;   // bounded-response countdown for the pending request
reg       refill_q;   // refill pipeline stage 1: a tick is captured here
reg       refill_go;  // refill pipeline stage 2: the credit presented to the bucket, held while the bucket is full
    reg       pending_b;   // second request slot: holds a request that arrived while the head slot was busy
    reg [3:0] deadline_b;  // best-effort countdown for the queued slot
    reg       rr_b;        // arbitration pointer, 1 when the queued slot gets the next token
    reg [2:0] starve;      // consecutive cycles the head slot has waited on a dry bucket

    initial tokens   = BURST;
    initial tick_cnt = 2'd3;
    initial pending  = 1'b0;
    initial deadline = 4'd0;
    initial refill_q = 1'b0;
initial refill_go = 1'b0;
    initial pending_b  = 1'b0;
    initial deadline_b = 4'd0;
    initial rr_b       = 1'b0;
    initial starve     = 3'd0;
initial grant_tally = 4'd0;

    wire tick     = (tick_cnt == 2'd0);
    wire b_ready    = pending_b && (tokens != 3'd0);
    // the queued slot only pre-empts on its own turn, and only while the
    // bucket still holds a spare token for the head slot
    wire do_grant_b = b_ready && (!pending || (rr_b && (tokens >= 3'd2)));
    wire do_grant = pending && (tokens != 3'd0) && !do_grant_b;
wire do_refill = refill_go && (tokens < BURST);
    wire any_grant = do_grant || do_grant_b;
    // dry-bucket alarm: the head slot has spent a whole refill interval without a token
    wire dry_alarm = pending && (starve >= 3'd3);

    assign grant   = i_ce && any_grant;
    assign expired = (pending && (deadline == 4'd0)) || (pending_b && (deadline_b == 4'd0)) || dry_alarm;

    // refill timer
    always @(posedge clk) if (i_ce)
        tick_cnt <= tick ? 2'd3 : (tick_cnt - 2'd1);

    // refill request is registered one cycle before it reaches the bucket
    always @(posedge clk) if (i_ce)
        refill_q <= tick;
// second refill stage: the credit reaches the bucket a cycle later, and waits
// here instead of being thrown away when the bucket has no room for it
always @(posedge clk) if (i_ce)
    refill_go <= refill_q || (refill_go && !do_refill);

    // bucket: drains on a grant, refills on a tick, saturates at BURST
    always @(posedge clk) if (i_ce) begin
        if (any_grant && do_refill)
            tokens <= tokens;                 // one out, one in
        else if (any_grant)
            tokens <= tokens - 3'd1;
        else if (do_refill)
            tokens <= tokens + 3'd1;
    end

    // round-robin pointer: whichever slot was served hands the turn over
    always @(posedge clk) if (i_ce) begin
        if (do_grant_b)
            rr_b <= 1'b0;
        else if (do_grant)
            rr_b <= 1'b1;
    end

    // queued slot: captures the request that arrives while the head slot is busy,
    // counts down best effort and drops the request if it runs out
    always @(posedge clk) if (i_ce) begin
        if (do_grant_b)
            pending_b <= 1'b0;
        else if (pending_b) begin
            if (deadline_b == 4'd0)
                pending_b <= 1'b0;
            else
                deadline_b <= deadline_b - 4'd1;
        end else if (req && pending) begin
            pending_b  <= 1'b1;
            deadline_b <= TIMEOUT;
        end
    end

    // request window and its countdown
    always @(posedge clk) if (i_ce) begin
        if (do_grant)
            pending <= 1'b0;
        else if (pending)
            deadline <= deadline - 4'd1;
        else if (req) begin
            pending  <= 1'b1;
            deadline <= TIMEOUT;
        end
    end
    // starvation counter: how many enabled cycles the head request has spent
    // waiting on an empty bucket; cleared as soon as a token is in the bucket
    always @(posedge clk) if (i_ce) begin
        if (!pending || (tokens != 3'd0))
            starve <= 3'd0;
        else
            starve <= starve + 3'd1;
    end

// observational grant tally: counts served requests, wraps freely
always @(posedge clk) if (i_ce) begin
    if (any_grant)
        grant_tally <= grant_tally + 4'd1;
end

    // P: inside the request window the countdown never expires
    always @(posedge clk)
        if (pending) assert (deadline != 4'd0);
    // P2: the dry-bucket counter cannot outlive the request window
    always @(posedge clk)
        if (pending) assert (starve <= 3'd5);
endmodule

module alu_result_fifo (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] a,
    input  wire [7:0] b,
    input  wire [1:0] op,
    output reg  [7:0] o_data,
    output reg        o_zero,
    output reg        o_carry,
    output wire       full,
    output wire       empty,
output reg  [3:0] count,
output wire [7:0] o_push_tally,
output reg  [3:0] o_op_shadow
);
    // ---- FIFO state: separate write/read pointers plus occupancy counter ----
    reg [2:0] wptr, rptr;
    reg [8:0] mem [0:7];   // {carry, result} slices
   // one-deep input staging register: the ALU result is captured here and
   // written into the array on the following enabled cycle
   reg        stg_v;
   reg  [8:0] stg_d;
  // second (skid) input slot: absorbs one more push while the staging slot
  // is still waiting for room in the array
  reg        skid_v;
  reg  [8:0] skid_d;
  // ---- push/pop transaction ledger ----
  // every accepted push logs one entry and every accepted pop logs one
  // retirement; both counts wrap freely at four bits.  The number of
  // entries the FIFO currently owns is the difference of the two logs,
  // which lets one 4-bit compare cover the array and both input slots.
  reg  [3:0] n_push, n_pop;
  assign o_push_tally = {n_pop, n_push};
    integer i;

    initial begin
        wptr    = 3'd0;
        rptr    = 3'd0;
        count   = 4'd0;
        o_data  = 8'h00;
        o_zero  = 1'b1;
        o_carry = 1'b0;
       stg_v   = 1'b0;
       stg_d   = 9'd0;
      skid_v  = 1'b0;
      skid_d  = 9'd0;
      n_push  = 4'd0;
      n_pop   = 4'd0;
o_op_shadow = 4'd0;
        for (i = 0; i < 8; i = i + 1) mem[i] = 9'd0;
    end

    // ---- 8-bit ALU slice: add, subtract, and, or (carry out in bit 8) ----
    wire [8:0] w_sum = {1'b0, a} + {1'b0, b};
    wire [8:0] w_dif = {1'b0, a} - {1'b0, b};
    reg  [8:0] alu;
    always @(*) begin
        case (op)
            2'b00:   alu = w_sum;
            2'b01:   alu = w_dif;
            2'b10:   alu = {1'b0, a & b};
            default: alu = {1'b0, a | b};
        endcase
    end

    // ---- full from the push/pop ledger, empty from the pointers ----
    wire [3:0] w_ledger = n_push - n_pop;
    assign full  = (w_ledger == 4'd5);
    assign empty = (wptr == rptr);

    wire do_push = i_ce && push && !full;
    wire do_pop  = i_ce && pop  && !empty;
   // the staging slot retires into the array whenever the array has room
   wire do_drain = i_ce && stg_v && ((wptr - rptr) != 3'd5);
  // the skid slot advances into the staging slot as soon as that slot frees up
  wire do_shift = i_ce && skid_v && (!stg_v || do_drain);

    always @(posedge clk) begin
       if (do_drain) begin
           mem[wptr] <= stg_d;
           wptr      <= wptr + 3'd1;
       end
      if (do_shift) begin
          stg_d <= skid_d;
          stg_v <= 1'b1;
      end else if (do_drain) begin
          stg_v <= 1'b0;
      end
       if (do_push) begin
          skid_d <= alu;
          skid_v <= 1'b1;
      end else if (do_shift) begin
          skid_v <= 1'b0;
       end
        if (do_pop) begin
            o_data  <= mem[rptr][7:0];
            o_carry <= mem[rptr][8];
            o_zero  <= (mem[rptr][7:0] == 8'h00);
            rptr    <= rptr + 3'd1;
        end
        if (do_push && !do_pop)
            count <= count + 4'd1;
        else if (!do_push && do_pop)
            count <= count - 4'd1;
        else
            count <= count;
        if (do_push)
            n_push <= n_push + 4'd1;
        if (do_pop)
            n_pop  <= n_pop  + 4'd1;
if (i_ce)
    o_op_shadow <= {o_op_shadow[2:0], (^op) ^ a[0] ^ b[0]};
    end

    // P: occupancy never exceeds the depth of 5, though the register holds 15
    always @(*) assert (count <= 4'd5);
endmodule

module pwm_prio_duty (
    input  wire       clk,
    input  wire       ce,
    input  wire [7:0] req,
    output reg        out_r,
output reg        vld_r,
output reg [3:0] evt_r
);
    // ---------------- PWM state ----------------
    reg [2:0] cnt;        // period counter 0..7
   reg [2:0] per;        // programmed frame length minus one (frame = per+1)
    reg [3:0] duty;       // active duty value 0..8
    reg [3:0] hi_cnt;     // cycles spent high inside the current period
   reg       hi_pend;    // high cycle staged in the pad register, not booked yet
    reg       shadow_nz;  // shadow: the duty programmed for this period was nonzero
    reg       armed;      // scope: high until the first all-zero request load
   reg       duty_ext;   // extra whole cycle granted to this frame by the dither
   reg       dith;       // pending half-step credit carried between frames
reg [3:0] evt_cnt;    // distractor: tally of cycles with an active request

    initial begin
        cnt       = 3'd0;
       per       = 3'd7;   // reset frame is the full eight cycles
        duty      = 4'd4;   // reset duty is nonzero
        hi_cnt    = 4'd0;
       hi_pend   = 1'b0;
        shadow_nz = 1'b1;   // matches reset duty
        armed     = 1'b1;
       duty_ext  = 1'b0;
       dith      = 1'b0;
        out_r     = 1'b0;
        vld_r     = 1'b0;
evt_cnt   = 4'd0;
evt_r     = 4'd0;
    end

    // ---------------- priority encoder over the request vector ----------------
    reg [2:0] idx;
    reg       vld;
    always @(*) begin
        vld = |req;
        if      (req[7]) idx = 3'd7;
        else if (req[6]) idx = 3'd6;
        else if (req[5]) idx = 3'd5;
        else if (req[4]) idx = 3'd4;
        else if (req[3]) idx = 3'd3;
        else if (req[2]) idx = 3'd2;
        else if (req[1]) idx = 3'd1;
        else             idx = 3'd0;
    end

    // requested duty: highest set index + 1, or 0 when no request
    wire [3:0] duty_req = vld ? ({1'b0, idx} + 4'd1) : 4'd0;

   // ---------------- frame-length programming ----------------
   // req[2:0] double as the frame-length code; a requested duty that does not
   // fit in the programmed frame is truncated to 100% of that frame
   wire [2:0] per_nxt  = req[2:0];
   wire [3:0] per_lim  = {1'b0, per_nxt} + 4'd1;
   wire [3:0] duty_nxt = (duty_req > per_lim) ? per_lim : duty_req;
  // ---------------- half-step dither ----------------
  // when several sources request at once the winner earns an extra half cycle
  // of duty for the aggregate load; two half cycles are cashed in as one whole
  // cycle, and the bump is only applied while the duty is below 100% of the
  // frame so that the extra cycle still fits inside the frame
  wire       multi    = vld && ((req & (req - 8'd1)) != 8'd0);
  wire       ext_nxt  = (dith && multi) && (duty_nxt < per_lim);
  wire [3:0] duty_eff = duty + {3'b000, duty_ext};

 // ---------------- frame capacity ----------------
 // 100% of the frame being emitted right now (the programmed per, not the
 // one being loaded); the comparator can never ask for more high time than
 // the frame it belongs to is able to hold
 wire [3:0] cap_now = {1'b0, per} + 4'd1;

    // ---------------- comparator: high exactly while cnt < duty ----------------
wire out  = ({1'b0, cnt} < duty_eff);
   wire wrap = (cnt == per);

    always @(posedge clk) begin
        if (ce) begin
           cnt   <= wrap ? 3'd0 : cnt + 3'd1;   // restarts at each boundary
           out_r   <= hi_pend;    // pad stage emits the cycle staged last tick
           // the boundary cycle is reserved for the reload, so whatever the
           // comparator produces there is flushed instead of staged
           hi_pend <= wrap ? 1'b0 : out;
            vld_r <= vld;
evt_cnt <= evt_cnt + (vld ? 4'd1 : 4'd0);
evt_r   <= {evt_cnt[2:0], evt_cnt[3]} ^ (wrap ? 4'd1 : 4'd0);
            if (wrap) begin
               per       <= per_nxt;
                // period boundary: latch the new duty and its shadow flag together
               duty      <= duty_nxt;
               shadow_nz <= (duty_nxt != 4'd0);
              duty_ext  <= ext_nxt;
              dith      <= dith ^ multi;
                hi_cnt    <= 4'd0;
               if (duty_nxt == 4'd0)
                    armed <= 1'b0; // the scope-closing event R
            end else begin
               // only cycles that have actually reached the pad are booked
               hi_cnt <= hi_cnt + {3'b000, hi_pend};
               // frame monitor: the high time can never outrun the frame it
               // belongs to; if it does, the latched flag no longer describes
               // the pulse being emitted, so drop it
               if (hi_cnt > {1'b0, per})
                   shadow_nz <= 1'b0;
            end
        end
    end

    // Precedence, in the "before the first zero-duty program" scope:
    // if the output has been high at all inside this period, then a nonzero
    // duty must have been recorded in the shadow flag earlier.
    always @(posedge clk)
        if (armed && hi_cnt != 4'd0)
            assert (shadow_nz);

   // Frame budget: the high time booked so far in this frame never exceeds
   // the duty being applied to it, and that duty fits inside the frame.
   always @(posedge clk)
       assert (hi_cnt <= duty_eff && duty_eff <= cap_now);
endmodule

// DRC check engine: each accepted board-check job walks a saturating
// step counter up to MAXSTEP while a completion countdown runs down.
module drc_engine (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       start,     // new check job requested
    output reg        busy,      // request outstanding
    output reg [3:0]  progress,  // saturating up-counter, clamps at MAXSTEP
    output reg [3:0]  deadline,  // completion countdown
    output reg        armed,     // sticky: a job has been accepted at least once
output reg        done,
output reg [3:0]  step_tally,
output reg [3:0]  job_count,
output reg [3:0]  n_open,    // ledger: jobs opened (free-running, wraps)
output reg [3:0]  n_close,   // ledger: jobs closed (free-running, wraps)
output reg        pass2      // reserve budget already handed to the countdown
);
    localparam [3:0] MAXSTEP = 4'd10;
   localparam [3:0] PASS1   = 4'd6;   // steps budgeted to the first pass

   // second-pass budget, parked out of the live countdown until pass one ends
   reg [3:0] credit;
// steps retired by completed passes; progress counts the pass in flight only
reg [3:0] retired;

    initial begin
        busy     = 1'b0;
        progress = 4'd0;
        deadline = 4'd0;
        armed    = 1'b0;
        done     = 1'b0;
       credit   = 4'd0;
retired  = 4'd0;
step_tally = 4'd0;
job_count = 4'd0;
n_open   = 4'd0;
n_close  = 4'd0;
pass2    = 1'b0;
    end

    wire accept   = i_ce && start && !busy;
    wire step     = i_ce && busy;
// a job ends when the retired steps plus the pass in flight reach MAXSTEP
wire last     = (retired + progress + 4'd1 >= MAXSTEP);
// the reserve is handed over exactly once per job; pass2 remembers that
wire refill   = (deadline <= 4'd1) && !pass2;

    always @(posedge clk) begin
        if (rst) begin
            busy     <= 1'b0;
            progress <= 4'd0;
            deadline <= 4'd0;
            armed    <= 1'b0;
            done     <= 1'b0;
           credit   <= 4'd0;
retired  <= 4'd0;
step_tally <= 4'd0;
job_count <= 4'd0;
n_open   <= 4'd0;
n_close  <= 4'd0;
pass2    <= 1'b0;
        end else if (accept) begin
            busy     <= 1'b1;
            progress <= 4'd0;
           deadline <= PASS1;             // pass one runs on its own budget
           credit   <= MAXSTEP - PASS1;   // remainder held back for pass two
retired  <= 4'd0;
            armed    <= 1'b1;   // sticky once set, never cleared except by rst
            done     <= 1'b0;
job_count <= (job_count == 4'd15) ? 4'd15 : job_count + 4'd1;
n_open   <= n_open + 4'd1;   // ledger: one more job opened
pass2    <= 1'b0;            // fresh job starts on the pass-one budget
        end else if (step) begin
           if (refill) begin
               // pass one spent: hand the reserve to the live countdown
               deadline <= credit;
pass2    <= 1'b1;            // reserve now spent for this job
               credit   <= 4'd0;
retired  <= retired + progress + 4'd1;   // book the finished pass
progress <= 4'd0;                        // in-pass counter restarts
           end else begin
               deadline <= (deadline == 4'd0) ? 4'd0 : deadline - 4'd1;
// saturating in-pass counter: clamps at MAXSTEP, never reaches 4'd15
progress <= (progress == MAXSTEP) ? MAXSTEP : progress + 4'd1;
           end
            if (last) begin
                busy <= 1'b0;
                done <= 1'b1;
n_close <= n_close + 4'd1;   // ledger: job retired
            end
step_tally <= (step_tally == 4'd15) ? 4'd15 : step_tally + 4'd1;
        end
    end

    // P: while the engine has ever been armed and a check is outstanding,
    // the completion countdown must not have expired.
    always @(*)
        if (armed && busy)
            assert (deadline != 4'd0);
endmodule

module uart_rx_onehot (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // baud tick / enable: low freezes all state
    input  wire       rx,
    input  wire       take,    // consumer accepts the byte parked in STOP
    output wire [7:0] o_data,
    output wire       o_ferr,
    output wire       o_busy
);
    // one-hot phase FSM:
    //   st[0]      IDLE
    //   st[1]      START bit
    //   st[2..9]   data bits D0..D7 (one state per bit)
    //   st[10]     STOP bit / byte parked
    reg [10:0] st;
    reg [3:0]  nbits;   // frame phase index: 0..10 only, though 4 bits hold 15
   reg [3:0]  dcnt;    // data bits already shifted into sr this frame: 0..8
    reg [7:0]  sr;
    reg        ferr;
    reg        pv;
   reg [3:0]  n_acq;   // ledger: frames acquired off the line (start bit seen)
   reg [3:0]  n_rel;   // ledger: frames released to the consumer (take at STOP)
   reg        active;  // a frame is in flight according to the ledger
  reg        owner;   // baud-tick arbiter: 1 = the idle timer owns this tick
  reg [3:0]  icnt;    // idle ticks seen by the line-idle timer: 0..11
 reg        rel_q;   // handoff staged one tick: take now acks on the next tick
 reg [7:0]  obuf;    // output holding register for the byte being handed off
reg        park;   // hand-off stage: owns the frame from the last data bit until the ack

    initial st    = 11'b000_0000_0001;
    initial nbits = 4'd0;
   initial dcnt  = 4'd0;
    initial sr    = 8'h00;
    initial ferr  = 1'b0;
    initial pv    = 1'b0;
   initial n_acq  = 4'd0;
   initial n_rel  = 4'd0;
   initial active = 1'b0;
  initial owner = 1'b0;
  initial icnt  = 4'd0;
 initial rel_q = 1'b0;
 initial obuf  = 8'h00;
initial park = 1'b0;

    wire idle   = st[0];
    wire startb = st[1];
    wire datab  = |st[9:2];
    wire stopb  = st[10];

    wire start_det = ce && idle   && !rx;   // falling edge of the line
   wire adv       = ce && active && !owner && (startb || datab); // count only the ticks this engine owns
wire done      = ce && stopb  && park && take;  // release only when the park stage holds the frame
wire in_flight = start_det || ((active || park) && !done); // receive engine or park stage claims the next tick
   wire quiet     = owner && (icnt == 4'd11);       // line idle for a whole frame time

    // next-state decode: every source bit drives exactly one destination bit
    reg [10:0] nxt;
    always @(*) begin
        nxt      = 11'd0;
        nxt[0]   = (st[0] && rx) || (st[10] && take);
        nxt[1]   = st[0] && !rx;
        nxt[2]   = st[1];
        nxt[3]   = st[2];
        nxt[4]   = st[3];
        nxt[5]   = st[4];
        nxt[6]   = st[5];
        nxt[7]   = st[6];
        nxt[8]   = st[7];
        nxt[9]   = st[8];
        nxt[10]  = st[9] || (st[10] && !take);
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            st    <= 11'b000_0000_0001;
            nbits <= 4'd0;
           dcnt  <= 4'd0;
            sr    <= 8'h00;
            ferr  <= 1'b0;
           n_acq  <= 4'd0;
           n_rel  <= 4'd0;
           active <= 1'b0;
           owner <= 1'b0;
           icnt  <= 4'd0;
          rel_q <= 1'b0;
          obuf  <= 8'h00;
park  <= 1'b0;
        end else if (ce) begin
            st <= nxt;
            if (start_det)     nbits <= 4'd1;   // load: start bit is phase 1
            else if (done)     nbits <= 4'd0;
            else if (adv)      nbits <= nbits + 4'd1;
            if (datab)         sr    <= {rx, sr[7:1]};
           if (start_det || done) dcnt <= 4'd0;
           else if (datab)        dcnt <= dcnt + 4'd1;
           if (done)          ferr  <= !rx || (dcnt != 4'd8); // stop bit high and a full byte
          else if (quiet)    ferr  <= 1'b0;                  // stale error retired once the line goes quiet
           // frame ledger: one acquire per start bit, one release per handoff
           if (start_det)     n_acq  <= n_acq + 4'd1;
if (rel_q)         n_rel  <= n_rel + 4'd1;
           if (start_det)     active <= 1'b1;
else if (st[9])    active <= 1'b0;   // last data bit: ownership passes to the park stage
if (st[9])         park   <= 1'b1;   // park stage takes the frame for the stop bit
else if (rel_q)    park   <= 1'b0;   // ... and lets go once the release has committed
// staged handoff: the byte is parked in obuf on take and the ledger
// release commits on the following tick, when the bus has been read
rel_q <= stopb && take;
if (done)          obuf  <= sr;
          // tick arbiter: every tick the frame engine will not use goes to the idle timer
          owner <= !in_flight;
          if (!owner)             icnt <= 4'd0;
          else if (icnt != 4'd11) icnt <= icnt + 4'd1;
        end
    end

   // with no byte parked, the data bus reads back the ledger for diagnostics
assign o_data = stopb ? sr : (park ? obuf : {n_acq, n_rel});
    assign o_ferr = ferr;
assign o_busy = !idle || active || park;

    // P: the phase counter changes on every phase change, and it never counts
    // past the 10 phases of a frame -- stated as a no-change check.
    always @(posedge clk)
        if (pv && $stable(nbits))
            assert ($stable(st) && nbits <= 4'd10);

   // P2: dcnt lags the phase index by the START phase plus the one-cycle
   // capture lag, so inside a frame it is always nbits-2 bits deep.
   always @(posedge clk)
       if (pv && o_busy && nbits >= 4'd2)
           assert (dcnt == nbits - 4'd2);
endmodule

module dma_burst_dimmer (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // beat enable / idle when low
    input  wire       i_start,
    input  wire [3:0] i_beats,
    input  wire [3:0] i_duty,
    output wire       o_busy,
    output wire       o_beat,
output wire       o_pwm,
output reg  [3:0] o_ce_count
);

    // ---- DMA burst engine state ----
    reg [3:0] beats_left;   // beats remaining in the burst
    reg [3:0] done_cnt;     // beats already pushed out
    reg [3:0] total;        // beats requested by the accepted burst
    reg [3:0] duty;         // dimming level latched with the burst
    reg       busy;         // up exactly while beats remain
    reg [3:0] queued;       // beats accepted but not yet issued into the current chunk
   reg [3:0] chunk_pend;   // chunk staged for issue on the next beat
   // ---- fabric ledger: beats booked out to the fabric vs beats it consumed ----
   reg [3:0] n_iss;        // running count of beats issued to the fabric
   reg [3:0] n_ret;        // running count of beats the fabric has consumed
  reg       ret_pend;     // one retirement in flight to the completion counter

    initial beats_left = 4'd0;
    initial done_cnt   = 4'd0;
    initial total      = 4'd0;
    initial duty       = 4'd0;
    initial busy       = 1'b0;
    initial queued     = 4'd0;
   initial chunk_pend = 4'd0;
   initial n_iss      = 4'd0;
   initial n_ret      = 4'd0;
  initial ret_pend   = 1'b0;
initial o_ce_count = 4'd0;

    // the fabric only accepts short chunks, so a long burst is issued piecewise
    localparam [3:0] CHUNK_MAX = 4'd4;
    wire [3:0] first_chunk = (i_beats > CHUNK_MAX) ? CHUNK_MAX : i_beats;
    wire [3:0] next_chunk  = (queued  > CHUNK_MAX) ? CHUNK_MAX : queued;
   // a beat is live on the bus exactly while the ledger shows work booked out
   wire outstanding = (n_iss != n_ret);

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            done_cnt   <= 4'd0;
            total      <= 4'd0;
            duty       <= 4'd0;
            queued     <= 4'd0;
           chunk_pend <= 4'd0;
           n_iss      <= 4'd0;
           n_ret      <= 4'd0;
          ret_pend   <= 1'b0;
o_ce_count <= 4'd0;
            busy       <= 1'b0;
        end else if (i_start && !busy && (i_beats != 4'd0)) begin
            // accept a new burst
            beats_left <= first_chunk;
           n_iss      <= n_iss + first_chunk;
            queued     <= i_beats - first_chunk;
            total      <= i_beats;
            done_cnt   <= 4'd0;
            duty       <= i_duty;
            busy       <= 1'b1;
        end else if (i_ce) begin
            // retire one beat
            if (beats_left > 4'd1) begin
                beats_left <= beats_left - 4'd1;
            end else if (beats_left == 4'd1) begin
               // current chunk drained: stage the next chunk, the fabric
               // needs a cycle of turnaround before it can be issued
               beats_left <= 4'd0;
               chunk_pend <= next_chunk;
                queued     <= queued - next_chunk;
           end else if (chunk_pend != 4'd0) begin
               // staged chunk lands in the beat counter
               beats_left <= chunk_pend;
               chunk_pend <= 4'd0;
           end
           // ledger bookkeeping: one beat is consumed per enabled cycle, and a
           // staged chunk is booked out to the fabric when it lands
           if (beats_left != 4'd0)
               n_ret <= n_ret + 4'd1;
           else if (chunk_pend != 4'd0)
               n_iss <= n_iss + chunk_pend;
          // completion counting is pipelined: the retirement observed on this
          // beat is registered, then folded into done_cnt on the next beat
          ret_pend <= busy && outstanding;
          if (ret_pend)
               done_cnt <= done_cnt + 4'd1;
          if ((beats_left == 4'd0) && (queued == 4'd0) && (chunk_pend == 4'd0))
                busy <= 1'b0;
o_ce_count <= o_ce_count + 4'd1;
        end
    end

    assign o_busy = busy;
   assign o_beat = busy && i_ce && outstanding;
    assign o_pwm  = busy && (done_cnt < duty);

    // ---- P: whenever the engine is not busy, the whole burst has been pushed ----
    always @(posedge i_clk)
        if (!busy)
            assert (done_cnt == total);

endmodule

// Simple token-lexer FSM: binary-encoded states 0..4, encodings 5..7 unused.
module lex_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [1:0] cls,     // 0=escape/backslash, 1=alpha, 2=digit, 3=quote
    output reg  [2:0] st,
output reg  [2:0] len,
output reg  [3:0] qcnt
);
    localparam [2:0] S_IDLE  = 3'd0;
    localparam [2:0] S_IDENT = 3'd1;
    localparam [2:0] S_NUM   = 3'd2;
    localparam [2:0] S_STR   = 3'd3;
    localparam [2:0] S_ESC   = 3'd4;
    // An escape can now be taken from top level or from inside an identifier,
    // so S_ESC alone no longer says which token is being built: the state code
    // to resume with is held here while st == S_ESC.
    reg [2:0] esc_ret;
   // Second lexer channel. The two character streams are interleaved on cls
   // and take turns owning the single decode/commit datapath below. Channel B
   // measures records rather than tokens, so its length is carried across a
   // token boundary instead of being cleared.
   reg [2:0] st_b;
   reg [2:0] len_b;
   reg [2:0] esc_b;
   reg       own;   // 0 = channel A owns the shared datapath, 1 = channel B
   // Decode and commit are now separate cycles: the next-state decode and the
   // length adder no longer share one combinational path to the outputs. A
   // character is absorbed into the staging pair in one cycle and the pair is
   // driven onto st/len in the next.
   reg [2:0] st_s;
   reg [2:0] len_s;
   reg       s_vld;
reg       last_q;

   wire [2:0] cur_st  = own ? st_b  : st;
   wire [2:0] cur_len = own ? len_b : len;
   wire [2:0] cur_esc = own ? esc_b : esc_ret;
   wire [2:0] len_inc = (cur_len == 3'd7) ? 3'd7 : (cur_len + 3'd1);

    initial st  = S_IDLE;
    initial len = 3'd0;
    initial esc_ret = S_IDLE;
   initial st_s  = S_IDLE;
   initial len_s = 3'd0;
   initial s_vld = 1'b0;
   initial st_b  = S_IDLE;
   initial len_b = 3'd0;
   initial esc_b = S_IDLE;
   initial own   = 1'b0;
initial qcnt   = 4'd0;
initial last_q = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            st  <= S_IDLE;
            len <= 3'd0;
            esc_ret <= S_IDLE;
           st_s  <= S_IDLE;
           len_s <= 3'd0;
           s_vld <= 1'b0;
           st_b  <= S_IDLE;
           len_b <= 3'd0;
           esc_b <= S_IDLE;
           own   <= 1'b0;
qcnt   <= 4'd0;
last_q <= 1'b0;
        end else if (ce) begin
           if (s_vld) begin
              if (own) begin
                  st_b  <= st_s;   // commit cycle: the staged pair goes back
                  len_b <= len_s;  // to whichever channel was decoded
              end else begin
                  st    <= st_s;
                  len   <= len_s;
              end
               s_vld <= 1'b0;
              own   <= ~own;   // round-robin: the other stream gets the next char
           end else begin
               s_vld <= 1'b1;   // decode cycle: absorb this character
           case (cur_st)
                S_IDLE: begin
                    if (cls == 2'd1) begin
                       st_s  <= S_IDENT;
                       len_s <= 3'd1;
                    end else if (cls == 2'd2) begin
                       st_s  <= S_NUM;
                       len_s <= 3'd1;
                    end else if (cls == 2'd3) begin
                       st_s  <= S_STR;
                       len_s <= 3'd0;
                    end else begin
                      st_s <= S_ESC;   // stray backslash: escaped char starts an identifier
                      if (own) esc_b <= S_IDENT; else esc_ret <= S_IDENT;
                       len_s   <= 3'd0;
                    end
                end
                S_IDENT: begin
                    if (cls == 2'd1 || cls == 2'd2) begin
                       st_s  <= S_IDENT;
                       len_s <= len_inc;
                    end else if (cls == 2'd0) begin
                       st_s    <= S_ESC;   // a\b is still a single identifier
                      if (own) esc_b <= S_IDENT; else esc_ret <= S_IDENT;
                      len_s   <= cur_len;
                    end else begin
                       st_s  <= S_IDLE;
                      len_s <= own ? len_inc : 3'd0;   // B keeps counting the record
                    end
                end
                S_NUM: begin
                    if (cls == 2'd2) begin
                       st_s  <= S_NUM;
                       len_s <= len_inc;
                    end else begin
                       st_s  <= S_IDLE;
                      len_s <= own ? len_inc : 3'd0;
                    end
                end
                S_STR: begin
                    if (cls == 2'd3) begin
                       st_s  <= S_IDLE;   // closing quote ends the token
                      len_s <= own ? len_inc : 3'd0;
                    end else if (cls == 2'd0) begin
                       st_s  <= S_ESC;    // backslash: next char is literal
                      if (own) esc_b <= S_STR; else esc_ret <= S_STR;
                      len_s <= cur_len;
                    end else begin
                       st_s  <= S_STR;
                       len_s <= len_inc;
                    end
                end
                S_ESC: begin
                  st_s  <= cur_esc;     // resume whatever token the escape interrupted
                   len_s <= len_inc;
                end
                default: begin
                    // unreachable encodings 5..7: recover to IDLE
                   st_s  <= S_IDLE;
                end
            endcase
           end
if (cls == 2'd3) last_q <= 1'b1; else last_q <= 1'b0;
if (last_q && cls == 2'd1) qcnt <= qcnt + 4'd1;
        end
    end

    // P: in the IDLE state the accumulated token length is always zero.
    always @(*)
        if (st == 3'd0)
            assert (len == 3'd0);
endmodule

module credit_rr_arbiter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire [3:0] req,       // four requesters
    input  wire       ret,       // consumer returns one credit
    output reg  [1:0] rr_ptr,    // rotating priority pointer
    output reg  [3:0] grant,     // one-hot grant
    output reg  [3:0] credits,   // credits held by the producer
    output reg  [3:0] outstanding // credits in flight at the consumer
);
    localparam [3:0] TOTAL = 4'd8;

   // credits parked against the burst currently in flight
   reg [1:0] escrow;

  // a return occupies the return path for one cycle before it lands
  reg       ret_q;
  reg [3:0] ret_amt;
 // lane B: a peer return lane that picks up the next return on the
 // cycle lane A drains, so returns can arrive back to back
 reg       ret_q2;
 reg [3:0] ret_amt2;
// grant commit stage: the credit file has a single write port, so a
// winning grant's debit is registered here on the decision cycle and
// charged against the credit file on the next one
reg       gnt_q;
reg [3:0] gnt_amt;
reg [1:0] gnt_resv;
// the credit file's write port sits four stages downstream of the
// arbiter, so a winning charge walks the pipe before it lands
reg       gnt_q2;
reg [3:0] gnt_amt2;
reg [1:0] gnt_resv2;
reg       gnt_q3;
reg [3:0] gnt_amt3;
reg [1:0] gnt_resv3;
reg       gnt_q4;
reg [3:0] gnt_amt4;
reg [1:0] gnt_resv4;
reg       gnt_q5;
reg [3:0] gnt_amt5;
reg [1:0] gnt_resv5;

    initial rr_ptr      = 2'd0;
    initial grant       = 4'b0000;
    initial credits     = TOTAL;
    initial outstanding = 4'd0;
   initial escrow      = 2'd0;
  initial ret_q       = 1'b0;
  initial ret_amt     = 4'd0;
 initial ret_q2      = 1'b0;
 initial ret_amt2    = 4'd0;
initial gnt_q       = 1'b0;
initial gnt_amt     = 4'd0;
initial gnt_resv    = 2'd0;
initial gnt_q2      = 1'b0;
initial gnt_amt2    = 4'd0;
initial gnt_resv2   = 2'd0;
initial gnt_q3      = 1'b0;
initial gnt_amt3    = 4'd0;
initial gnt_resv3   = 2'd0;
initial gnt_q4      = 1'b0;
initial gnt_amt4    = 4'd0;
initial gnt_resv4   = 2'd0;
initial gnt_q5      = 1'b0;
initial gnt_amt5    = 4'd0;
initial gnt_resv5   = 2'd0;

    // rotating priority selection: first requester at or after rr_ptr
    wire [1:0] idx = req[rr_ptr]          ? rr_ptr          :
                     req[rr_ptr + 2'd1]   ? rr_ptr + 2'd1   :
                     req[rr_ptr + 2'd2]   ? rr_ptr + 2'd2   :
                                            rr_ptr + 2'd3;

   // at burst start one credit per other waiting requester is parked in
   // escrow, so a burst that has been admitted can always be drained
   wire [3:0] others = req & ~(4'b0001 << idx);
   wire [1:0] resv   = {1'b0, others[0]} + {1'b0, others[1]} +
                       {1'b0, others[2]} + {1'b0, others[3]};
   wire       burst_start = (outstanding == 4'd0);
   wire [3:0] need        = burst_start ? (4'd1 + {2'b00, resv}) : 4'd1;
   wire have_credit = (credits >= need);
    wire any_req     = |req;

    // a grant spends one credit; it becomes outstanding until returned
   // a return is captured one cycle and applied the next
// the charge pipe owns the credit write port from the decision
// cycle until the charge reaches the far end
wire gnt_busy = gnt_q || gnt_q2 || gnt_q3 || gnt_q4 || gnt_q5;
wire ret_start  = i_ce && ret && !ret_q && !gnt_busy &&
                  (outstanding > {3'd0, ret_q2});
wire ret_start2 = i_ce && ret && ret_q && !ret_q2 && !gnt_busy &&
                  (outstanding > 4'd1);
  // the two lanes share one credit write port; lane A drains first
  wire ret_done   = i_ce && ret_q;
  wire ret_done2  = i_ce && ret_q2 && !ret_q;
   // the return path has priority; grants stall while it is busy
wire do_grant   = i_ce && have_credit && any_req &&
!ret_q && !ret_q2 && !gnt_busy && !ret_start;
// the registered debit owns the credit write port when it lands
wire gnt_commit = i_ce && gnt_q5;

    always @(posedge clk) begin
        if (rst) begin
            rr_ptr      <= 2'd0;
            grant       <= 4'b0000;
            credits     <= TOTAL;
            outstanding <= 4'd0;
           escrow      <= 2'd0;
           ret_q       <= 1'b0;
           ret_amt     <= 4'd0;
          ret_q2      <= 1'b0;
          ret_amt2    <= 4'd0;
gnt_q       <= 1'b0;
gnt_amt     <= 4'd0;
gnt_resv    <= 2'd0;
gnt_q2      <= 1'b0;
gnt_amt2    <= 4'd0;
gnt_resv2   <= 2'd0;
gnt_q3      <= 1'b0;
gnt_amt3    <= 4'd0;
gnt_resv3   <= 2'd0;
gnt_q4      <= 1'b0;
gnt_amt4    <= 4'd0;
gnt_resv4   <= 2'd0;
gnt_q5      <= 1'b0;
gnt_amt5    <= 4'd0;
gnt_resv5   <= 2'd0;
        end else if (i_ce) begin
            grant <= do_grant ? (4'b0001 << idx) : 4'b0000;
            if (do_grant)
                rr_ptr <= idx + 2'd1;

          // capture side: each lane latches the amount it will hand back
          if (ret_start) begin
              ret_q   <= 1'b1;
              ret_amt <= (outstanding == 4'd1 + {3'd0, ret_q2})
                           ? (4'd1 + {2'b00, escrow}) : 4'd1;
          end
          if (ret_start2) begin
              ret_q2   <= 1'b1;
              ret_amt2 <= (outstanding == 4'd2)
                           ? (4'd1 + {2'b00, escrow}) : 4'd1;
          end


         // arbitration only records the winner's charge; the credit
// file itself is written when the charge reaches the last stage
gnt_q2    <= gnt_q;
gnt_amt2  <= gnt_amt;
gnt_resv2 <= gnt_resv;
gnt_q3    <= gnt_q2;
gnt_amt3  <= gnt_amt2;
gnt_resv3 <= gnt_resv2;
gnt_q4    <= gnt_q3;
gnt_amt4  <= gnt_amt3;
gnt_resv4 <= gnt_resv3;
gnt_q5    <= gnt_q4;
gnt_amt5  <= gnt_amt4;
gnt_resv5 <= gnt_resv4;
gnt_q     <= 1'b0;
         if (do_grant) begin
             gnt_q    <= 1'b1;
             gnt_amt  <= need;
             gnt_resv <= burst_start ? resv : escrow;
         end

         if (gnt_commit) begin
credits     <= credits - gnt_amt5;
escrow      <= gnt_resv5;
             outstanding <= outstanding + 4'd1;
           end else if (ret_done) begin
               credits <= credits + ret_amt;
               if (outstanding == 4'd1)
                   escrow <= 2'd0;
               outstanding <= outstanding - 4'd1;
               ret_q <= 1'b0;
          end else if (ret_done2) begin
              credits <= credits + ret_amt2;
              if (outstanding == 4'd1)
                  escrow <= 2'd0;
              outstanding <= outstanding - 4'd1;
              ret_q2 <= 1'b0;
           end
        end
    end

    // P: whenever nothing is in flight, the producer holds every credit
    always @(posedge clk)
        if (outstanding == 4'd0)
            assert (credits == TOTAL);
endmodule

module credit_deadline (
    input  wire clk,
    input  wire i_ce,      // global enable: low => all state frozen
    input  wire rst,
    input  wire req,       // producer wants to spend a credit
    output wire grant,
output wire busy,
output reg [3:0] req_hist
);
    localparam [2:0] TOTAL = 3'd4;   // configured credit pool

    // credits held by the producer, credits outstanding at the consumer
    reg [2:0] credits;
    reg [2:0] outst;
   // registered handoff: a spent credit occupies the launch slot for one
   // enabled cycle before the consumer counts it as outstanding
   reg       snd;
    // consumer needs two enabled cycles to retire one outstanding credit
    reg       svc;
    // bounded-response deadline countdown for the outstanding credits
    reg [3:0] timer;
   // deferred deadline budget for the credits queued behind the head
   reg [3:0] bank;
   // governor watermark: deepest outstanding occupancy seen so far
   reg [2:0] peak;
reg last_req;

    initial begin
        credits = 3'd4;
        outst   = 3'd0;
       snd     = 1'b0;
        svc     = 1'b0;
        timer   = 4'd0;
       bank    = 4'd0;
       peak    = 3'd0;
req_hist = 4'd0;
last_req = 1'b0;
    end

   // once occupancy has ever peaked at the whole pool, hold off new
   // spends until the consumer has drained completely
  wire throttle  = (peak == TOTAL) && ((outst != 3'd0) || snd);
  // admission control: a new spend must be able to park its two cycle
  // budget behind the head credit, so the bank has to have room
  wire bank_room = (bank <= 4'd4);
 wire do_spend  = req && (credits != 3'd0) && !throttle && bank_room && !snd;
 // the launch slot drains into the outstanding set on the next enabled cycle
 wire do_launch = snd;
    wire do_return = (outst != 3'd0) && (svc == 1'b1);
  wire [2:0] outst_nxt = outst + (do_launch ? 3'd1 : 3'd0)
                                - (do_return ? 3'd1 : 3'd0);

  // a retiring head hands the deadline of the next credit out of the bank
 wire [3:0] bank_in   = bank + ((do_launch && (outst != 3'd0)) ? 4'd2 : 4'd0);
  wire [3:0] bank_take = (bank_in >= 4'd2) ? 4'd2 : bank_in;
  wire       reload    = do_return && (outst_nxt != 3'd0);

    assign grant = i_ce && do_spend;
   assign busy  = (outst != 3'd0) || snd;

    always @(posedge clk) begin
        if (i_ce) begin
            if (rst) begin
                credits <= TOTAL;
                outst   <= 3'd0;
               snd     <= 1'b0;
                svc     <= 1'b0;
                timer   <= 4'd0;
               bank    <= 4'd0;
               peak    <= 3'd0;
req_hist <= 4'd0;
last_req <= 1'b0;
            end else begin
                // credit conservation: one token moves per event
                credits <= credits - (do_spend  ? 3'd1 : 3'd0)
                                   + (do_return ? 3'd1 : 3'd0);
               outst   <= outst   + (do_launch ? 3'd1 : 3'd0)
                                   - (do_return ? 3'd1 : 3'd0);

               // the launch slot is one deep, so a new spend is only
               // accepted once the previous one has entered the pool
               snd     <= do_spend;

                // two-cycle service phase per outstanding credit
                if (outst == 3'd0)
                    svc <= 1'b0;
                else
                    svc <= ~svc;

               // watermark only ever rises
               if (outst_nxt > peak)
                   peak <= outst_nxt;

               // deadline budget: the head credit owns a two cycle deadline;
               // the budget of the credits queued behind it waits in the bank
               if (reload)
                   timer <= bank_take;
               else if (do_return)
                   timer <= 4'd0;
              else if (do_launch && (outst == 3'd0))
                   timer <= 4'd2;
               else
                   timer <= timer - ((timer != 4'd0) ? 4'd1 : 4'd0);

               bank <= bank_in - (reload ? bank_take : 4'd0);

// observability only: rolling history of the req input
last_req <= req;
req_hist <= {req_hist[2:0], last_req};
            end
        end
    end

    // Bounded response (safety): the countdown must never expire while a
    // credit is still outstanding at the consumer.
    always @(posedge clk)
        if (outst != 3'd0)
            assert (timer != 4'd0);

   // Quiescence (safety): once the whole pool is back at the producer
   // there is nothing left at the consumer, so the service phase must be
   // idle and the deadline budget must be fully spent.
   always @(posedge clk)
       if (credits == TOTAL)
           assert ((timer == 4'd0) && (svc == 1'b0));

   // Governor coherence (safety): the in-flight deadline budget never
   // exceeds two cycles per credit at the recorded peak occupancy.
   always @(posedge clk)
       assert (timer <= {peak, 1'b0});

endmodule

module wdog_saturate (
    input wire i_clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_kick,
    input wire i_ack,
    output wire o_reset,
    output wire [3:0] o_elapsed,
output wire [3:0] o_remain,
output reg [3:0] o_kick_cnt
);
    // Watchdog window: TIMEOUT ticks without a kick latches a system reset.
    localparam [3:0] TIMEOUT = 4'd12;
   // The adaptive window never tightens below this floor.
   localparam [3:0] WIN_MIN = 4'd4;

    // Saturating up-counter of ticks since the last kick.  It clamps at
    // TIMEOUT (12) even though the 4-bit register admits values up to 15.
    reg [3:0] cnt;
    // Mirror: ticks of grace remaining, saturating down at zero.
    reg [3:0] rem;
    // Latched reset request, cleared only by an acknowledge.
    reg       latched;

   // Margin monitor: low-water mark of the grace window since the
   // watchdog was last armed.  Zero means the window has fully closed.
   reg [3:0] slack;

  // Adaptive grace window: how many ticks of grace each re-arm hands out.
  // o_elapsed/o_remain are always reported against the full 12-tick frame,
  // so a shortened window simply starts the elapsed count with a head
  // start instead of at zero.
  reg [3:0] win;
// Diagnostic only: counts rising edges of i_kick seen on ce cycles.
reg kick_dly;

   // Update stage: the tick arithmetic is registered for one cycle before
   // it commits, so an update issued on a ce cycle lands on the cycle
   // after it was issued.
   reg [3:0] cnt_stg;
   reg [3:0] rem_stg;
   reg       stg_vld;
  // The stage also carries the window size the update installs, plus a
  // flag marking the entry as a re-arm rather than a plain tick.
  reg [3:0] win_stg;
  reg       ld_stg;

   // Forwarding: a pending stage value is newer than the committed
   // register, so back-to-back ticks are computed from the stage.
   wire [3:0] cnt_eff = stg_vld ? cnt_stg : cnt;
   wire [3:0] rem_eff = stg_vld ? rem_stg : rem;

  // A kick arriving after the window has already closed is ignored: the
  // reset request stands until software acknowledges it.
  wire kick_ok = i_kick && (slack != 4'd0);

 // Each acknowledged timeout tightens the deadline by one tick, each
 // healthy kick relaxes it back one tick toward the full frame.
 wire [3:0] win_up = (win < TIMEOUT) ? win + 4'd1 : win;
 wire [3:0] win_dn = (win > WIN_MIN) ? win - 4'd1 : win;

    initial cnt     = 4'd0;
    initial rem     = TIMEOUT;
    initial latched = 1'b0;
   initial cnt_stg = 4'd0;
   initial rem_stg = TIMEOUT;
   initial stg_vld = 1'b0;
  initial slack   = TIMEOUT;
 initial win     = TIMEOUT;
 initial win_stg = TIMEOUT;
 initial ld_stg  = 1'b0;
initial kick_dly   = 1'b0;
initial o_kick_cnt = 4'd0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            cnt     <= 4'd0;
            rem     <= TIMEOUT;
            latched <= 1'b0;
           cnt_stg <= 4'd0;
           rem_stg <= TIMEOUT;
           stg_vld <= 1'b0;
          slack   <= TIMEOUT;
         win     <= TIMEOUT;
         win_stg <= TIMEOUT;
         ld_stg  <= 1'b0;
kick_dly   <= 1'b0;
o_kick_cnt <= 4'd0;
       end else begin
           // Drain the stage: the in-flight update commits one cycle after
           // it was issued, whether or not a new tick arrives.
           if (stg_vld) begin
               cnt <= cnt_stg;
               rem <= rem_stg;
win <= win_stg;
// The monitor restarts on an explicit re-arm: a shortened window
// never reaches the full frame count, so the old compare against
// TIMEOUT would never fire again.
slack <= ld_stg ? win_stg :
         (rem_stg < slack) ? rem_stg : slack;
           end
           stg_vld <= 1'b0;
if (i_ce) begin
    kick_dly <= i_kick;
    if (i_kick && !kick_dly && (o_kick_cnt != 4'd15))
        o_kick_cnt <= o_kick_cnt + 4'd1;
end

           if (i_ce) begin
           stg_vld <= 1'b1;
          if (kick_ok) begin
cnt_stg <= TIMEOUT - win_up;
rem_stg <= win_up;
win_stg <= win_up;
ld_stg  <= 1'b1;
           end else begin
               cnt_stg <= (cnt_eff < TIMEOUT) ? cnt_eff + 4'd1 : cnt_eff;
               rem_stg <= (rem_eff != 4'd0) ? rem_eff - 4'd1 : rem_eff;
win_stg <= win;
ld_stg  <= 1'b0;
           end

           if (i_ack) begin
               latched <= 1'b0;
               // The acknowledge also re-arms the window, issued through
               // the same stage so the commit stays single-sourced.
cnt_stg <= TIMEOUT - win_dn;
rem_stg <= win_dn;
win_stg <= win_dn;
ld_stg  <= 1'b1;
           end
          else if (!kick_ok && (rem_eff == 4'd1))
                latched <= 1'b1;
        end
       end
    end

    assign o_reset   = latched;
    assign o_elapsed = cnt;
    assign o_remain  = rem;

    // Universality, global scope: whenever the grace window has run out, the
    // elapsed-tick counter must be sitting on its saturation value.
    always @(posedge i_clk)
        if (rem == 4'd0)
            assert (cnt == TIMEOUT);

   // Margin report consistency: the ticks already burned plus the deepest
   // margin the monitor has recorded cannot exceed the whole window.
   always @(posedge i_clk)
       assert ((cnt + slack) <= 5'd12);
endmodule

module fetch_credit_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,        // idle condition: when low, nothing moves
    input  wire       fetch,     // issue an instruction into the fetch queue
    input  wire       retire,    // instruction leaves the queue
    output reg  [3:0] used,      // up counter: occupancy of the fetch queue
    output reg  [3:0] credits,   // down counter: remaining free slots
output wire       can_fetch,
output reg  [3:0] fetch_events
);
    // queue depth is 12, but both counters are 4 bits wide (0..15)
    localparam [3:0] DEPTH = 4'd12;

    // a retire frees a queue slot right away, but the credit itself only
    // reaches the free pool a cycle later, through this return stage
    reg        ret_credit;

   // an accepted fetch is registered in the allocate stage; it shows up
   // in the occupancy counter on the following cycle
   reg        alloc_pend;

   // credits withheld from the fetch free pool and parked for the
   // prefetch port while the queue is running hot
   reg  [1:0] resv;

   // purely observational statistics: saturating count of granted fetches
   reg        activity_seen;


    initial used    = 4'd0;
    initial credits = DEPTH;
    initial ret_credit = 1'b0;
   initial alloc_pend = 1'b0;
   initial resv = 2'd0;
   initial fetch_events = 4'd0;
   initial activity_seen = 1'b0;

    assign can_fetch = (credits != 4'd0);

    wire fetch_go  = fetch && !retire && (credits != 4'd0);
    wire retire_go = retire && !fetch && (used != 4'd0);

   // the queue is under pressure once occupancy reaches the top third
   wire hi_load     = (used >= 4'd8);
   // under pressure a returning credit is parked in the reserve instead
   wire ret_to_resv = ret_credit && hi_load && (resv != 2'd2);
   // once the pressure is off, reserved credits go back one per cycle
   wire resv_drain  = !ret_credit && !fetch_go && !hi_load && (resv != 2'd0);
   wire cred_inc    = (ret_credit && !ret_to_resv) || resv_drain;
   wire cred_dec    = fetch_go;

    always @(posedge clk) begin
        if (rst) begin
            used    <= 4'd0;
            credits <= DEPTH;
            ret_credit <= 1'b0;
           alloc_pend <= 1'b0;
           resv <= 2'd0;
           fetch_events <= 4'd0;
           activity_seen <= 1'b0;
        end else if (en) begin
           // occupancy reflects the allocate stage, one cycle behind the grant
           if (alloc_pend && !retire_go)
                used <= used + 4'd1;
           else if (!alloc_pend && retire_go)
                used <= used - 4'd1;

            // the free pool gives up a slot on fetch, and only gets one
            // back when a returning credit pops out of the return stage
           if (cred_dec && !cred_inc)
               credits <= credits - 4'd1;
           else if (cred_inc && !cred_dec)
               credits <= credits + 4'd1;

           // the reserve fills from parked returns and drains back later
           if (ret_to_resv)
               resv <= resv + 2'd1;
           else if (resv_drain)
               resv <= resv - 2'd1;

            // a retire hands its credit to the return stage
            ret_credit <= retire_go;
           // the grant hands its slot to the allocate stage
           alloc_pend <= fetch_go;
          // statistics only; not read by anything else
          activity_seen <= fetch || retire;
          if (fetch_go && (fetch_events != 4'd15))
              fetch_events <= fetch_events + 4'd1;
            // simultaneous fetch+retire: slot handed straight over
        end
    end

    // P (two assertions, global scope, bounded existence at most 12):
    // neither counter can ever exceed the queue depth, which is strictly
    // smaller than what their 4-bit width admits.
    always @(posedge clk) begin
        assert (used <= DEPTH);
        assert (credits <= DEPTH);
    end
endmodule

module gfx_frame_fsm (
    input  wire clk,
    input  wire i_reset,
    input  wire i_ce,
    input  wire i_start,
    output wire o_vsync,
output wire [2:0] o_state,
output reg [3:0] o_frame_tag
);
    // binary-encoded frame pipeline states; 5,6,7 are unreachable encodings
    localparam [2:0] S_IDLE    = 3'd0;
    localparam [2:0] S_CLEAR   = 3'd1;
    localparam [2:0] S_DRAW    = 3'd2;
    localparam [2:0] S_BLIT    = 3'd3;
    localparam [2:0] S_PRESENT = 3'd4;
   // overlay plane pipeline stages (shares the framebuffer with the frame pipeline)
   localparam [1:0] OV_IDLE = 2'd0;
   localparam [1:0] OV_CLR  = 2'd1;
   localparam [1:0] OV_FILL = 2'd2;
   localparam [1:0] OV_SWAP = 2'd3;
   // hardware cursor plane: repaints the sprite after the overlay refresh
   localparam [1:0] CU_IDLE  = 2'd0;
   localparam [1:0] CU_FETCH = 2'd1;
   localparam [1:0] CU_PAINT = 2'd2;
   localparam [1:0] CU_DONE  = 2'd3;
// shared framebuffer write port: an update is staged here for one cycle
localparam [2:0] FB_NOP = 3'd0;
localparam [2:0] FB_CLR = 3'd1;
localparam [2:0] FB_OVL = 3'd2;
localparam [2:0] FB_CUR = 3'd3;

    reg [2:0] state;
    reg [1:0] draw_cnt;
    reg       cleared_seen;   // shadow: framebuffer was cleared this frame
   reg [1:0] ov_state;      // overlay plane pipeline
   reg       ov_pend;       // overlay refresh owed after the last frame
reg [2:0] fb_cmd;        // framebuffer update in flight to the shadow
reg [1:0] cur_state;     // hardware cursor plane pipeline
reg       cur_pend;      // cursor repaint owed after the last frame
reg [3:0] vs_count;      // decorative tally of presented frames

    initial state        = S_IDLE;
    initial draw_cnt     = 2'd0;
    initial cleared_seen = 1'b0;
   initial ov_state     = OV_IDLE;
   initial ov_pend      = 1'b0;
initial fb_cmd       = FB_NOP;
initial cur_state    = CU_IDLE;
initial cur_pend     = 1'b0;
initial vs_count     = 4'd0;
initial o_frame_tag  = 4'd0;

    wire draw_done = (draw_cnt == 2'd3);
   // framebuffer arbitration: the frame pipeline may only start a new frame
   // when no overlay refresh is running or owed
  wire fb_free = (ov_state == OV_IDLE) && !ov_pend &&
                 (cur_state == CU_IDLE) && !cur_pend;

    always @(posedge clk) begin
        if (i_reset) begin
            state        <= S_IDLE;
            draw_cnt     <= 2'd0;
            cleared_seen <= 1'b0;
           ov_state     <= OV_IDLE;
           ov_pend      <= 1'b0;
fb_cmd       <= FB_NOP;
           cur_state    <= CU_IDLE;
           cur_pend     <= 1'b0;
vs_count     <= 4'd0;
o_frame_tag  <= 4'd0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                   if (i_start && fb_free) begin
                        state    <= S_CLEAR;
                        draw_cnt <= 2'd0;
                    end
                end
                S_CLEAR: begin
// the clear pass hands its update to the framebuffer write port
// rather than touching the shadow directly
fb_cmd       <= FB_CLR;
                    state        <= S_DRAW;
                end
                S_DRAW: begin
                    if (draw_done)
                        state <= S_BLIT;
                    else
                        draw_cnt <= draw_cnt + 2'd1;
                end
                S_BLIT: begin
                    state <= S_PRESENT;
                end
                S_PRESENT: begin
                    state        <= S_IDLE;
                    draw_cnt     <= 2'd0;
                    cleared_seen <= 1'b0;
                   ov_pend      <= 1'b1;   // overlay gets the buffer next
                  cur_pend     <= 1'b1;   // cursor repaints after the overlay
                end
                default: begin
                    // encodings 5/6/7 never occur by construction; the
                    // synthesised decoder folds them onto the present stage
                    state <= S_PRESENT;
                end
            endcase

           // Overlay plane pipeline: same shape as the frame pipeline above,
           // but it borrows the framebuffer and the shared pass counter, so it
           // only runs in the gap between frames.
           case (ov_state)
               OV_IDLE: begin
                   if (ov_pend && state == S_IDLE) begin
                       ov_state <= OV_CLR;
                       ov_pend  <= 1'b0;
                   end
               end
               OV_CLR: begin
                   ov_state <= OV_FILL;
                   draw_cnt <= 2'd0;
               end
               OV_FILL: begin
// overlay writes land on the shared framebuffer, so the recorded
// clear stops describing its contents once this update retires
fb_cmd <= FB_OVL;
                   if (draw_cnt == 2'd1)
                       ov_state <= OV_SWAP;
                   else
                       draw_cnt <= draw_cnt + 2'd1;
               end
               OV_SWAP: begin
                   ov_state <= OV_IDLE;
                   draw_cnt <= 2'd0;
               end
           endcase

          // Hardware cursor plane: a third client of the framebuffer write
          // port.  It repaints the sprite once the overlay refresh has
          // retired, and reuses the shared pass counter for its fill loop.
          case (cur_state)
              CU_IDLE: begin
                  if (cur_pend && state == S_IDLE &&
                      ov_state == OV_IDLE && !ov_pend) begin
                      cur_state <= CU_FETCH;
                      cur_pend  <= 1'b0;
                  end
              end
              CU_FETCH: begin
                  cur_state <= CU_PAINT;
                  draw_cnt  <= 2'd0;
              end
              CU_PAINT: begin
                  if (draw_cnt == 2'd2)
                      cur_state <= CU_DONE;
                  else
                      draw_cnt <= draw_cnt + 2'd1;
              end
              CU_DONE: begin
                  cur_state <= CU_IDLE;
                  draw_cnt  <= 2'd0;
              end
          endcase
// Shared framebuffer write port.  The staged command retires into the
// shadow here, one cycle after the pass that issued it, and the port is
// re-armed in the same cycle.  The frame pipeline wins the port if both
// planes ask for it in the same cycle.
if (fb_cmd == FB_CLR)
    cleared_seen <= 1'b1;
else if (fb_cmd == FB_OVL || fb_cmd == FB_CUR)
    cleared_seen <= 1'b0;
if (state == S_CLEAR)
    fb_cmd <= FB_CLR;
else if (ov_state == OV_FILL)
    fb_cmd <= FB_OVL;
else if (cur_state == CU_PAINT)
    fb_cmd <= FB_CUR;
else
    fb_cmd <= FB_NOP;
if (state == S_PRESENT)
    vs_count <= vs_count + 4'd1;
o_frame_tag <= vs_count ^ {2'b00, cur_state};
        end
    end

    assign o_vsync = (state == S_PRESENT);
    assign o_state = state;

    // Precedence, global: presenting a frame implies the clear pass happened earlier
    always @(posedge clk)
        if (state == S_PRESENT)
            assert (cleared_seen);
endmodule

// PWM channel for a wire-logic accelerator block.
// Period counter walks 0..PER-1, duty is double buffered at the period edge,
// and high_cnt accumulates the number of high cycles elapsed in the period.
module pwm_channel (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire       i_load,
    input  wire [3:0] i_duty,
    output wire       pwm_out,
output reg        armed,
output reg [3:0]  dbg_load_cnt
);
    localparam [3:0] PER = 4'd12;
   localparam [3:0] HALF = 4'd6;   // the period is walked as two half windows

   reg [3:0] cnt;       // sub-counter inside the current half, 0 .. HALF-1
   reg       half;      // 0 = first half of the period, 1 = second half
    reg [3:0] duty;      // active duty, 0 .. PER
    reg [3:0] high_cnt;  // high cycles elapsed so far this period
   reg       pwm_q;     // registered output stage, resolved one cycle ahead
  reg [3:0] duty_b;    // nested window duty, kept inside the main window
  reg       pwm_b_q;   // registered output stage of the nested window
  reg       sel;       // owner of the shared duty load port: 0 = main, 1 = nested
reg [1:0] load_hist;  // recent i_load request history (debug only)

    initial begin
        cnt      = 4'd0;
       half     = 1'b0;
        duty     = 4'd0;
        high_cnt = 4'd0;
        armed    = 1'b0;
       pwm_q    = 1'b0;
       duty_b   = 4'd0;
       pwm_b_q  = 1'b0;
       sel      = 1'b0;
load_hist    = 2'd0;
dbg_load_cnt = 4'd0;
    end

    // the construct: output high exactly while the counter is below the duty
  // both windows share one open-drain pad, so the pin is the wire-OR of the
  // two output stages
  assign pwm_out = pwm_q | pwm_b_q;

    wire [3:0] duty_clamped = (i_duty > PER) ? PER : i_duty;
   wire       at_half      = (cnt == HALF - 4'd1);
   wire       at_edge      = half && at_half;
   // full period phase reassembled from the two halves, 0 .. PER-1
   wire [3:0] phase        = half ? (cnt + HALF) : cnt;

   // Next-cycle counter and duty. The output register is loaded from these so
   // the pin keeps the same alignment the combinational comparator had, while
   // the compare itself is off the critical path.
  wire [3:0] cnt_nxt   = at_half ? 4'd0 : cnt + 4'd1;
  wire       half_nxt  = at_half ? ~half : half;
  wire [3:0] phase_nxt = at_edge ? 4'd0 : phase + 4'd1;
 wire [3:0] duty_nxt = (at_edge && i_load && !sel) ? duty_clamped : duty;
 // The nested window is clamped into the main window when it is loaded, and
 // retrimmed whenever the main channel takes a smaller duty.
 wire [3:0] duty_b_req  = (i_duty > duty) ? duty : i_duty;
 wire [3:0] duty_b_trim = (duty_b > duty_clamped) ? duty_clamped : duty_b;
 wire [3:0] duty_b_nxt  = (at_edge && i_load) ? (sel ? duty_b_req : duty_b_trim)
                                              : duty_b;

    always @(posedge clk) begin
        if (rst) begin
            cnt      <= 4'd0;
           half     <= 1'b0;
            duty     <= 4'd0;
            high_cnt <= 4'd0;
            armed    <= 1'b0;
           pwm_q    <= 1'b0;
           duty_b   <= 4'd0;
           pwm_b_q  <= 1'b0;
           sel      <= 1'b0;
load_hist    <= 2'd0;
dbg_load_cnt <= 4'd0;
        end else if (i_ce) begin
          pwm_q <= (phase_nxt < duty_nxt);
         pwm_b_q <= (phase_nxt < duty_b_nxt);
load_hist <= {load_hist[0], i_load};
if (i_load && !load_hist[0]) begin
    dbg_load_cnt <= dbg_load_cnt + 4'd1;
end
            if (at_edge) begin
                // period rolls over: new duty takes effect, accumulator clears
                cnt      <= 4'd0;
               half     <= 1'b0;
                high_cnt <= 4'd0;
                armed    <= 1'b1;            // sticky, never cleared
               sel <= ~sel;                 // round-robin the shared load port
               if (i_load) begin
                   if (sel) begin
                       duty_b <= duty_b_req;
                   end else begin
                       duty   <= duty_clamped;
                       duty_b <= duty_b_trim;
                   end
               end
            end else begin
               cnt      <= cnt_nxt;
               half     <= half_nxt;
                high_cnt <= high_cnt + (pwm_out ? 4'd1 : 4'd0);
            end
        end
    end

    // Property (universality, after the first completed period):
    // the accumulated high time never exceeds the duty, and the live output
    // agrees with the accumulator's headroom.
    always @(posedge clk)
        if (armed)
            assert (high_cnt <= duty);

    always @(posedge clk)
        if (armed)
            assert (pwm_out == (high_cnt < duty));
endmodule

// Four-phase req/ack handshake engine with a busy mirror and
// per-client ownership / response routing tags.
//
//   phase 0 : idle            (req=0, ack=0)
//   phase 1 : req asserted    (req=1, ack=0)
//   phase 2 : ack observed    (req=1, ack=1)
//   phase 3 : req withdrawn   (req=0, ack=1)  -> waits for ack to drop
//
// busy is a separate register that mirrors "phase != 0"; the start path is
// gated on !busy only, exactly as a real controller would do.
module fourphase_owner (
    input  wire clk,
    input  wire i_ce,        // idle condition: nothing moves when low
    input  wire i_req,       // a client wants the channel
    input  wire i_sel,       // which client (0 -> A, 1 -> B)
    input  wire i_ack_in,    // ack wire coming back from the target
    output wire o_busy,
    output wire o_req,
    output wire o_ack
);

    reg [1:0] phase;
    reg       busy;
    reg       req;
    reg       ack;
    reg       own_a, own_b;   // who currently owns the channel
    reg       resp_a, resp_b; // where the response will be routed
    reg       virgin;         // high until the first handshake ever completes

  // The owner tag is not written straight from the launch path: the launch
  // cycle is already busy driving req and bumping the credit ledger, so the
  // selected client is parked in a one-deep staging latch and copied into
  // the ownership bits on the following enabled cycle. Progress out of
  // phase 1 stalls until the staged tag has been committed.
  reg       tag_v;
  reg       tag_sel;

 // The response route is staged the same way: the cycle that observes ack is
 // already raising ack and beginning the req teardown, so the route is
 // captured into a one-deep latch and written into the resp bits on the
 // following enabled cycle. req is not allowed to drop until that write has
 // landed, so phase 2 holds until the latch is empty.
 reg       rt_v;
 reg       rt_sel;

   // Credit ledger: one credit exists for the channel. Every acquire is
   // logged in n_acq, every retire in n_rel; both wrap at four bits. The
   // channel may only be taken when all logged acquires have been retired.
   reg [3:0] n_acq;
   reg [3:0] n_rel;

  // Retires post lazily: the completion cycle is already writing seven
  // registers, so it only raises rel_pend and the n_rel increment is folded
  // into the next acquire. The ledger counts a pending retire as already
  // retired, so a client can take the channel back to back without waiting
  // for the credit to be written down.
  reg       rel_pend;

  wire ledger_free = ((n_acq - n_rel) == {3'b0, rel_pend});

    initial phase  = 2'd0;
    initial busy   = 1'b0;
    initial req    = 1'b0;
    initial ack    = 1'b0;
    initial own_a  = 1'b0;
    initial own_b  = 1'b0;
    initial resp_a = 1'b0;
    initial resp_b = 1'b0;
    initial virgin = 1'b1;
  initial tag_v   = 1'b0;
  initial tag_sel = 1'b0;
 initial rt_v    = 1'b0;
 initial rt_sel  = 1'b0;
   initial n_acq  = 4'd0;
   initial n_rel  = 4'd0;
  initial rel_pend = 1'b0;

    always @(posedge clk) begin
        if (i_ce) begin
           if (ledger_free) begin
                // channel believed free: latch the owner and drive req
                if (i_req) begin
                    phase <= 2'd1;
                    req   <= 1'b1;
                    busy  <= 1'b1;
                   n_acq <= n_acq + 4'd1;
                  n_rel    <= n_rel + {3'b0, rel_pend};
                  rel_pend <= 1'b0;
                   tag_v   <= 1'b1;
                   tag_sel <= i_sel;
                end
            end else begin
                case (phase)
                   2'd1: if (tag_v) begin
                             // drain the staging latch into the tag bits
                             tag_v <= 1'b0;
                             if (tag_sel)
                                 own_b <= 1'b1;
                             else
                                 own_a <= 1'b1;
                         end else if (i_ack_in) begin
// ack rose: stage the response route for the next cycle
                              phase  <= 2'd2;
                              ack    <= 1'b1;
rt_v   <= 1'b1;
rt_sel <= own_b;
                          end
2'd2: if (rt_v) begin
          // drain the route latch into the resp tag bits
          rt_v <= 1'b0;
          if (rt_sel)
              resp_b <= 1'b1;
          else
              resp_a <= 1'b1;
      end else begin
                              // req may only drop now that ack is high
                              phase <= 2'd3;
                              req   <= 1'b0;
                          end
                    2'd3: if (!i_ack_in) begin
                              phase  <= 2'd0;
                              ack    <= 1'b0;
                              busy   <= 1'b0;
                            rel_pend <= 1'b1;
                              own_a  <= 1'b0;
                              own_b  <= 1'b0;
                              resp_a <= 1'b0;
                              resp_b <= 1'b0;
                           rt_v   <= 1'b0;
                              virgin <= 1'b0;   // first completion disarms
                          end
                    default: ;
                endcase
            end
        end
    end

    assign o_busy = busy;
    assign o_req  = req;
    assign o_ack  = ack;

    // Before the first handshake has ever completed, there must never be two
    // owners at once, and never two response routes at once.
    always @(posedge clk)
        if (virgin) assert (!(own_a && own_b));

    always @(posedge clk)
        if (virgin) assert (!(resp_a && resp_b));

endmodule

module wifi_radio_owner_fsm (
    input  wire clk,
    input  wire rst,
    input  wire step,      // idle/enable: low freezes all state
    input  wire rx_start,  // preamble detected by the receiver
    input  wire tx_req,    // MAC wants the air for a frame
    output wire radio_tx,  // transmit chain owns the radio
output wire radio_rx,  // receive chain owns the radio
output reg  [3:0] rx_evt_count // count of observed preambles (diagnostic)
);
    // one-hot MAC air-interface FSM:
//   bit0 = IDLE, bit1 = RX_FRAME, bit2 = TX_BURST, bit3 = ACK_WAIT
reg [3:0] state;
initial state = 4'b0001;

// transmit burst sequencer: one-hot shift register that walks the PA
// through the preamble and data phases of a granted frame
//   bit0 = PREAMBLE, bit1 = DATA, 2'b00 = burst finished
reg [1:0] txph;
initial txph = 2'b00;

   // periodic beacon engine; shares the radio front end with the MAC FSM
   //   bit0 = B_IDLE, bit1 = B_RAMP, bit2 = B_SEND
   reg [2:0] bstate;
   reg [3:0] btimer;
  // PA bias-settling pipeline: the beacon power amp needs four cycles of
  // bias settling between the interval expiring and the ramp keying the
  // front end, so the arm decision walks these stages before it is applied
  reg pa_arm0, pa_arm1, pa_arm2, pa_arm3;
   initial bstate = 3'b001;
   initial btimer = 4'd15;
  initial pa_arm0 = 1'b0;
  initial pa_arm1 = 1'b0;
  initial pa_arm2 = 1'b0;
  initial pa_arm3 = 1'b0;
  initial rx_evt_count = 4'd0;

wire s_idle = state[0];
wire s_rx   = state[1];
wire s_txb  = state[2];
wire s_ackw = state[3];

wire tx_pre = txph[0];
wire tx_dat = txph[1];
// the MAC hands the air to the burst sequencer on the way out of IDLE
wire tx_start = s_idle & tx_req & ~rx_start;

   wire b_idle = bstate[0];
   wire b_ramp = bstate[1];
   wire b_send = bstate[2];
  wire pa_busy = pa_arm0 | pa_arm1 | pa_arm2 | pa_arm3;
  // a beacon whose PA is arming already owns the air as far as the MAC
  // is concerned, so the front end stays reserved for the whole settle
  wire b_busy = b_ramp | b_send | pa_busy;
   wire b_due  = (btimer == 4'd0);
   // the MAC keeps priority: the beacon only grabs an idle, unrequested radio
  wire b_arm  = b_idle & b_due & s_idle & ~rx_start & ~tx_req & ~pa_busy;
  // the ramp only starts once the bias pipeline has drained through
  wire b_go   = pa_arm3;

   wire [2:0] bnxt;
   assign bnxt[0] = (b_idle & ~b_go) | b_send;
   assign bnxt[1] = b_go;                             // ramp the beacon PA
   assign bnxt[2] = b_ramp;                           // ramp -> send beacon

    // next-state as a per-bit OR of its legal source states
wire [3:0] nxt;
    assign nxt[0] = (s_idle & ~rx_start & ~tx_req) | s_rx | s_ackw;
    assign nxt[1] = s_idle & rx_start;                 // RX wins the air
assign nxt[2] = tx_start | (s_txb & tx_pre);       // start / stay in burst
assign nxt[3] = s_txb & tx_dat;                    // data done -> ACK wait

    always @(posedge clk) begin
        if (rst)
state <= 4'b0001;
       // the air is single-ported: the MAC FSM stalls while the beacon has it
       else if (step && !b_busy)
            state <= nxt;
    end

  // the sequencer shifts a zero in on every granted cycle, so the burst
  // self-terminates one cycle after the data phase
  always @(posedge clk) begin
      if (rst)
          txph <= 2'b00;
      else if (step && !b_busy) begin
          if (tx_start)
              txph <= 2'b01;
          else
              txph <= {txph[0], 1'b0};
      end
  end

   always @(posedge clk) begin
      if (rst) begin
          bstate <= 3'b001;
          pa_arm0 <= 1'b0;
          pa_arm1 <= 1'b0;
          pa_arm2 <= 1'b0;
          pa_arm3 <= 1'b0;
      end
       else if (step)
      begin
          bstate <= bnxt;
          // bias settle: one stage per cycle, a single token in flight
          pa_arm0 <= b_arm;
          pa_arm1 <= pa_arm0;
          pa_arm2 <= pa_arm1;
          pa_arm3 <= pa_arm2;
      end
   end

   // beacon interval: reload on transmission, hold at zero until the air frees
   always @(posedge clk) begin
       if (rst)
           btimer <= 4'd15;
       else if (step) begin
           if (b_send)
               btimer <= 4'd15;
           else if (btimer != 4'd0)
               btimer <= btimer - 4'd1;
       end
   end

  // diagnostic preamble counter: observes the inputs only, drives nothing else
  always @(posedge clk) begin
      if (rst)
          rx_evt_count <= 4'd0;
      else if (step && rx_start)
          rx_evt_count <= rx_evt_count + 4'd1;
  end

    // decoded radio ownership
assign radio_tx = tx_pre | tx_dat | b_ramp | b_send;
    assign radio_rx = s_rx    | s_ackw;

    // P: the transmit and receive chains never own the radio together
    always @(*)
        assert (!(radio_tx && radio_rx));
endmodule

module vd_sheet_loader (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_start,
    input  wire       i_last_row,
    output wire       o_loading,
    output wire       o_ready,
output wire [3:0] o_rows,
output reg  [3:0] o_ce_beats
);
    // binary-encoded loader FSM: IDLE/OPEN/HEADER/ROWS/DONE
    // encodings 101, 110, 111 are never entered by construction
    localparam [2:0] S_IDLE   = 3'b000,
                     S_OPEN   = 3'b001,
                     S_HEADER = 3'b010,
                     S_ROWS   = 3'b011,
                     S_DONE   = 3'b100;

   // index-block fetch engine: shares the loader handshake and row counter
   localparam [1:0] X_IDLE  = 2'b00,
                    X_FETCH = 2'b01,
                    X_TAIL  = 2'b10,
                    X_DONE  = 2'b11;

    reg [2:0] st;
    reg       loading;
    reg       ready;
   reg       fin_pend;
    reg [3:0] rows;
   reg       abort_pend;
   reg [3:0] row_max;
  reg [1:0] ix_st;
  reg       ix_req;

    initial st      = S_IDLE;
    initial loading = 1'b0;
    initial ready   = 1'b0;
   initial fin_pend = 1'b0;
    initial rows    = 4'd0;
   initial abort_pend = 1'b0;
   initial row_max    = 4'd4;
  initial ix_st  = X_IDLE;
  initial ix_req = 1'b0;
initial o_ce_beats = 4'd0;

    always @(posedge clk) begin
        if (i_reset) begin
            st      <= S_IDLE;
            loading <= 1'b0;
            ready   <= 1'b0;
           fin_pend <= 1'b0;
            rows    <= 4'd0;
           abort_pend <= 1'b0;
           row_max    <= 4'd4;
          ix_st      <= X_IDLE;
          ix_req     <= 1'b0;
o_ce_beats <= 4'd0;
        end else if (i_ce) begin
o_ce_beats <= o_ce_beats + {3'd0, i_start};
           // completion is committed one beat after the FSM posts it
           ready <= fin_pend || abort_pend;
            case (st)
                S_IDLE: begin
                   if (i_start && ix_st == X_IDLE) begin
                        st      <= S_OPEN;
                        loading <= 1'b1;
                    end else begin
                        st      <= S_IDLE;
                        loading <= 1'b0;
                    end
                end
                S_OPEN: begin
                    st      <= S_HEADER;
                    loading <= 1'b1;
                    rows    <= 4'd0;
                end
                S_HEADER: begin
                    st      <= S_ROWS;
                    loading <= 1'b1;
                end
                S_ROWS: begin
                    if (i_last_row) begin
                        st      <= S_DONE;
                        loading <= 1'b0;
                       fin_pend <= 1'b1;
                   end else if (rows == row_max) begin
                       // row budget exhausted: truncate this sheet and close out
                       st         <= S_DONE;
                       loading    <= 1'b0;
                       abort_pend <= 1'b1;
                   end else begin
                        st      <= S_ROWS;
                        loading <= 1'b1;
                        rows    <= rows + 4'd1;
                    end
                end
                S_DONE: begin
                    st      <= S_IDLE;
                    loading <= 1'b0;
                   fin_pend <= 1'b0;
                   abort_pend <= 1'b0;
                   // adapt the burst budget: grow it when the sheet overran,
                   // shrink it back toward the floor when it fit
                   if (abort_pend) begin
                      // truncated sheet leaves the directory stale
                      ix_req <= 1'b1;
                       if (row_max != 4'd12)
                           row_max <= row_max + 4'd1;
                   end else if (row_max != 4'd4) begin
                       row_max <= row_max - 4'd1;
                   end
                end
                default: begin
                    // illegal encoding: parked recovery path, asserts both flags
                    st      <= 3'b110;
                    loading <= 1'b1;
                    ready   <= 1'b1;
                   fin_pend <= 1'b1;
                  abort_pend <= 1'b1;
                end
            endcase
          // index-block fetch: reuses the loader's busy/ready handshake and
          // the row counter, so it only runs while the sheet FSM is parked
          case (ix_st)
              X_IDLE: begin
                  if (ix_req && st == S_IDLE && !i_start) begin
                      ix_st   <= X_FETCH;
                      rows    <= 4'd0;
                      loading <= 1'b1;
                  end
              end
              X_FETCH: begin
                  loading <= 1'b1;
                  if (rows == 4'd3)
                      ix_st <= X_TAIL;
                  else
                      rows  <= rows + 4'd1;
              end
              X_TAIL: begin
                  // trailing checksum word, bus still held
                  ix_st   <= X_DONE;
                  loading <= 1'b1;
              end
              X_DONE: begin
                  ix_st   <= X_IDLE;
                  ix_req  <= 1'b0;
                  loading <= 1'b0;
                  ready   <= 1'b1;
              end
          endcase
        end
    end

    assign o_loading = loading;
    assign o_ready   = ready;
    assign o_rows    = rows;

    // P: the loader is never simultaneously loading and ready
    always @(posedge clk)
        assert (!(loading && ready));
endmodule

module gray_shadow_ctr (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    output wire [3:0] o_gray,
output wire [3:0] o_bin,
output reg  [3:0] ce_hist,
output reg  [3:0] o_act_cnt
);
    // Binary shadow counter and its gray-coded twin.  The gray register is
    // advanced by the classic single-bit-toggle rule, computed from the gray
    // value alone; the binary shadow is a plain increment.
// The shadow count is split: the low three bits take the increment, and the
// top bit is a separate flop toggled by a carry term that is precomputed one
// cycle ahead (lo_max), so the top bit never hangs off the low adder's carry
// chain.  lo_max is only re-evaluated on cycles that actually advance the
// count, so it is static while the counter is stalled.
reg [2:0] bin_lo;
reg       bin_hi;
reg       lo_max;
wire [3:0] bin = {bin_hi, bin_lo};
    reg [3:0] gray;
    reg       pv;
   reg [3:0] gray_s;
   reg       s_vld;
reg       ce_d;
reg       act_seen;

initial bin_lo = 3'b000;
initial bin_hi = 1'b0;
initial lo_max = 1'b0;
    initial gray = 4'b0000;
    initial pv   = 1'b0;
   initial gray_s = 4'b0000;
   initial s_vld  = 1'b0;
initial ce_d    = 1'b0;
initial ce_hist = 4'b0000;
initial act_seen  = 1'b0;
initial o_act_cnt = 4'b0000;

    // Next gray value: toggle bit 0 when the parity is even, otherwise toggle
    // the bit just above the lowest set bit (with the top bit handling wrap).
    function [3:0] gnext(input [3:0] g);
        begin
            if (!(^g))     gnext = g ^ 4'b0001;
            else if (g[0]) gnext = g ^ 4'b0010;
            else if (g[1]) gnext = g ^ 4'b0100;
            else           gnext = g ^ 4'b1000;
        end
    endfunction

   // Stage 1: the gray pointer is advanced one cycle ahead of the output
   // registers, so o_gray leaves the block straight off a flop instead of
   // through the toggle-select network.  s_vld marks the staged word as a
   // pending advance that the commit stage still owes the outputs.
   always @(posedge clk) begin
       if (rst) begin
           gray_s <= 4'b0000;
           s_vld  <= 1'b0;
ce_d    <= 1'b0;
ce_hist <= 4'b0000;
act_seen  <= 1'b0;
o_act_cnt <= 4'b0000;
       end else begin
           s_vld <= i_ce;
ce_d    <= i_ce;
ce_hist <= {ce_hist[2:0], ce_d};
           if (i_ce) gray_s <= gnext(gray_s);
act_seen  <= i_ce | ce_d;
o_act_cnt <= o_act_cnt + {3'b000, (i_ce & ~act_seen)};
       end
   end

   // Stage 2: commit the staged pointer and bump the binary shadow in the
   // same cycle, so the two views never disagree at the outputs.

    always @(posedge clk) begin
        if (rst) begin
bin_lo <= 3'b000;
bin_hi <= 1'b0;
lo_max <= 1'b0;
            gray <= 4'b0000;
       end else if (s_vld) begin
bin_lo <= bin_lo + 3'b001;
bin_hi <= bin_hi ^ lo_max;
lo_max <= (bin_lo == 3'b110);
           gray <= gray_s;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign o_gray = gray;
    assign o_bin  = bin;

    // Top bit of the gray word and top bit of the binary shadow: the most
    // significant gray bit is just the most significant binary bit, so neither
    // may move without the other.
    wire g_msb = gray[3];
    wire b_msb = bin[3];

    // P: whenever the gray MSB did not change, the shadow MSB did not change.
    always @(posedge clk)
        if (pv && $stable(g_msb))
            assert ($stable(b_msb));
endmodule

module wdog_scan (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // scanner step enable; low => whole design idles
    input  wire i_kick,    // full substring match: hard kick of the watchdog
    input  wire i_feed,    // partial match: partial credit, no flag clear
    output wire o_timeout,
    output wire [7:0] o_pos
);
    // Watchdog for a character-scan engine: the scanner must report progress
    // before LIMIT idle steps elapse, otherwise the search is declared timed out.
    localparam [3:0] LIMIT = 4'd12;

    reg [3:0] wd;       // cycles since last progress, saturates at LIMIT
    reg       expired;  // sticky timeout flag
    reg [7:0] pos;      // current character position in the haystack
    reg [3:0] slack;    // remaining scan budget exported to the prefetch stride
   // The counter maths sits in the scan pipeline's ALU stage: credit, spend and
   // saturate land here first and are committed onto the report bus (the two
   // registers above) on the following scan step.
   reg [3:0] wd_s;     // watchdog count, arithmetic stage
   reg [3:0] slack_s;  // scan budget, arithmetic stage
   reg [3:0] slack_q;  // scan budget, report-bus retime stage
    // The timeout flag sits on the report bus, four scan steps downstream of
    // the counter, so a saturation event is registered through this pipe
    // before it is visible to the host.
    reg       exp_s0;   // expiry report, stage 0
    reg       exp_s1;   // expiry report, stage 1
    reg       exp_s2;   // expiry report, stage 2
    reg       exp_s3;   // expiry report, stage 3

    initial wd      = 4'd0;
    initial expired = 1'b0;
    initial pos     = 8'd0;
    initial slack   = LIMIT;
   initial wd_s    = 4'd0;
   initial slack_s = LIMIT;
  initial slack_q = LIMIT;
    initial exp_s0  = 1'b0;
    initial exp_s1  = 1'b0;
    initial exp_s2  = 1'b0;
    initial exp_s3  = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            wd      <= 4'd0;
            expired <= 1'b0;
            pos     <= 8'd0;
            slack   <= LIMIT;
           wd_s    <= 4'd0;
           slack_s <= LIMIT;
           slack_q <= LIMIT;
            exp_s0  <= 1'b0;
            exp_s1  <= 1'b0;
            exp_s2  <= 1'b0;
            exp_s3  <= 1'b0;
        end else if (i_ce) begin
            // plenty of budget left => the scanner may consume two
            // characters in a single step
            pos <= pos + ((slack > 4'd8) ? 8'd2 : 8'd1);
           // commit the previous step's arithmetic onto the report bus
           wd    <= wd_s;
           // the budget export is retimed once more: the stride comparator
           // downstream sits on a long path, so it reads a registered copy
           slack   <= slack_q;
           slack_q <= slack_s;
            // walk the report pipe one stage per scan step; nothing new
            // enters unless the counter saturates this step
            exp_s0 <= 1'b0;
            exp_s1 <= exp_s0;
            exp_s2 <= exp_s1;
            exp_s3 <= exp_s2;
            if (exp_s3)
                expired <= 1'b1;
            if (i_kick) begin
                // full match: reload the watchdog and drop the timeout flag
                wd      <= 4'd0;
                expired <= 1'b0;
                slack   <= LIMIT;
               wd_s    <= 4'd0;
               slack_s <= LIMIT;
               slack_q <= LIMIT;
                // the reload also flushes any report still in flight
                exp_s0  <= 1'b0;
                exp_s1  <= 1'b0;
                exp_s2  <= 1'b0;
                exp_s3  <= 1'b0;
            end else if (i_feed) begin
                // partial credit: only granted while the counter has not
                // saturated.  Note the gate looks at the COUNTER, not the flag.
               if (wd_s != LIMIT)
                   wd_s <= (wd_s > 4'd4) ? (wd_s - 4'd4) : 4'd0;
                // partial credit also refunds budget, capped at the reload value
               if (slack_s != 4'd0)
                   slack_s <= (slack_s < 4'd8) ? (slack_s + 4'd4) : LIMIT;
            end else begin
                // no progress this step: count up and saturate at LIMIT
               if (wd_s != LIMIT) begin
                   wd_s <= wd_s + 4'd1;
                   if ((wd_s + 4'd1) == LIMIT)
                        exp_s0 <= 1'b1;
                end
                // spend one unit of budget per idle step, floor at zero
               if (slack_s != 4'd0)
                   slack_s <= slack_s - 4'd1;
            end
        end
    end

    assign o_timeout = expired;
    assign o_pos     = pos;

    // P: a reported timeout always comes with a counter in the top half of
    // its range (the watchdog really did run out of slack).
    always @(posedge clk) assert (!expired || wd[3]);

    // Q: a reported timeout means the exported scan budget is exhausted,
    // so downstream stride logic has already dropped back to one char/step.
    always @(posedge clk) assert (!expired || slack == 4'd0);
endmodule

module dma_copier_chain (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_clear,
    input  wire [3:0] i_len,
    output wire       o_done,
    output wire       o_busy,
    output wire       o_err
);
    // phase slice codes (gray-ish), each with its stored parity bit
    localparam [1:0] PH_IDLE  = 2'b00,   // parity 0
                     PH_ARMED = 2'b01,   // parity 1
                     PH_BUSY  = 2'b11,   // parity 0
                     PH_DONE  = 2'b10;   // parity 1

    // parity-protected register slice holding the engine phase
    reg [1:0] phase   = PH_IDLE;
    reg       par     = 1'b0;

    // descriptor word counter
    reg [3:0] count   = 4'd0;

    // chain history bits: arm happened, start happened
    reg       h_arm   = 1'b0;
    reg       h_start = 1'b0;
    // start handshake stage: the start pulse is captured here for the
    // descriptor-fetch cycle and is only then logged into h_start
    reg       s_pend  = 1'b0;

   // descriptor status shadow: while a descriptor is in flight the
   // "start beat seen" record is kept here; it is only folded into the
   // chain log when the descriptor actually retires
   reg       sh_start = 1'b0;

  // descriptor ledger: one log entry per descriptor issued to the burst
  // engine and one per descriptor retired.  Both counters free-run and
  // wrap; their difference is the number of descriptors still in flight.
  reg [3:0] n_iss = 4'd0;
  reg [3:0] n_ret = 4'd0;

  wire [3:0] outstanding = n_iss - n_ret;
  // the engine is single-descriptor: at most one may be outstanding, and
  // it must agree with the in-flight status bits of the slice
  wire ledger_bad = (outstanding != {3'd0, (s_pend || sh_start)});

 // channel ledger: the copy channel is acquired when a descriptor is
 // armed and released when the completion is cleared.  Both counters
 // free-run and wrap; their difference is the channel occupancy.
 reg [3:0] n_acq = 4'd0;
 reg [3:0] n_rel = 4'd0;
 // owner bit carried alongside the phase slice
 reg       ch_own = 1'b0;

 wire [3:0] chan_held = n_acq - n_rel;
 // the channel is single-owner: the owner bit, the phase slice and the
 // acquire/release ledger must all agree
 wire chan_bad = (chan_held != {3'd0, ch_own}) ||
                 (ch_own != (phase != PH_IDLE));

    // slice checker: stored parity must match stored phase
wire slice_bad = (par != (^phase)) || (phase == PH_IDLE && sh_start) || ledger_bad || chan_bad;

    always @(posedge clk) begin
        if (i_ce) begin
            if (slice_bad) begin
                // corrupted descriptor slice: abort, report done immediately
                phase <= PH_DONE;
                par   <= 1'b1;
            end else begin
                case (phase)
                PH_IDLE:
if (i_arm && !ch_own) begin
                        phase   <= PH_ARMED;
                        par     <= 1'b1;
                        count   <= i_len;
                        h_arm   <= 1'b1;
ch_own  <= 1'b1;
n_acq   <= n_acq + 4'd1;
                    end
                PH_ARMED:
                    if (i_start) begin
                        phase   <= PH_BUSY;
                        par     <= 1'b0;
                        s_pend  <= 1'b1;
n_iss   <= n_iss + 4'd1;
                    end
                PH_BUSY:
                    if (s_pend) begin
                        // first burst cycle fetches the descriptor word,
                       // no payload word moves and the length is untouched;
                       // the start beat lands in the status shadow, not yet
                       // in the chain log
                        s_pend  <= 1'b0;
                       sh_start <= 1'b1;
                    end else if (count == 4'd0) begin
                        phase <= PH_DONE;
                        par   <= 1'b1;
                       // retire: commit the in-flight status into the chain
                       // log and release the shadow for the next descriptor
                       h_start  <= sh_start;
                       sh_start <= 1'b0;
n_ret    <= n_ret + 4'd1;
                    end else begin
                        count <= count - 4'd1;
                    end
                PH_DONE:
                    if (i_clear) begin
                        phase <= PH_IDLE;
                        par   <= 1'b0;
ch_own <= 1'b0;
n_rel  <= n_rel + 4'd1;
                    end
                endcase
            end
        end
    end

    assign o_done = (phase == PH_DONE);
    assign o_busy = (phase == PH_BUSY);
    assign o_err  = slice_bad;

    // chain precedence, globally: a finish can never be seen unless the
    // arm step and then the start step were actually taken
    always @(posedge clk)
        if (phase == PH_DONE) assert (h_arm);

    always @(posedge clk)
        if (phase == PH_DONE) assert (h_start);
endmodule

module arb_lock_pending (
    input  wire       clk,
    input  wire       ce,      // global enable / idle when low
    input  wire [3:0] req,     // new requests, latched into pend
    input  wire       rel,     // current owner releases the lock
    output wire [3:0] grant,
output wire [2:0] occupancy,
output wire [3:0] evt_count
);
    // pending request bitmap and its redundant occupancy counter
    reg [3:0] pend  = 4'b0000;
    reg [2:0] pcnt  = 3'd0;
reg [2:0] lcnt  = 3'd0;   // bank A entries admitted on the last credit
reg [3:0] late  = 4'b0000; // arrival class of each pending lane
   reg [2:0] bcnt  = 3'd0;   // bank B (indices 2,3) occupancy
    // fixed-priority arbiter with a lock bit freezing the winner
    reg       lock  = 1'b0;
    reg [1:0] owner = 2'd0;
    reg       pv    = 1'b0;   // past-valid

   // service ledger: every admission and every retirement is logged,
   // both counters free-run and wrap at four bits
   reg [3:0] n_in  = 4'd0;
   reg [3:0] n_out = 4'd0;
// activity monitor: counts completed release handshakes (observation only)
reg [3:0] rel_cnt = 4'd0;

    // fixed priority: lowest index wins
// within bank A a fresh arrival outranks a late one; index breaks ties
wire [1:0] pick_a = (pend[0] && !late[0]) ? 2'd0 :
                    (pend[1] && !late[1]) ? 2'd1 :
                    pend[0]               ? 2'd0 : 2'd1;
wire [1:0] pick_b = pend[2] ? 2'd2 : 2'd3;
// drain the fuller bank first; ties break toward bank A
// work still outstanding per the ledger, and the bank A share of it
wire [3:0] bal     = n_in - n_out;
wire [2:0] a_bal   = bal[2:0] - bcnt;
wire       serve_b = (bcnt > a_bal);
wire [1:0] pick    = serve_b ? pick_b : pick_a;
    wire       any  = |pend;

    // service completion: the locked owner releases, its pending bit retires
    wire       do_clr   = ce && lock && rel;
    wire [3:0] clr_mask = do_clr ? (4'b0001 << owner) : 4'b0000;
    // only genuinely new requests are inserted
// credit limit: admission stops once three entries are outstanding
wire       adm      = (bal < 4'd3);
wire [3:0] set_mask = (ce && adm) ? (req & ~pend & ~clr_mask) : 4'b0000;
// the last credit is handed to late arrivals, which are booked apart
wire       mark_late = (bal >= 4'd2);
wire [3:0] late_set  = mark_late ? set_mask : 4'b0000;
wire [3:0] late_clr  = (set_mask & ~late_set) | clr_mask;
wire [3:0] fresh_set = set_mask & ~late_set;
wire [2:0] nset_a   = fresh_set[0] + fresh_set[1];
wire [2:0] nset_l   = late_set[0] + late_set[1];
wire [2:0] nset_b   = set_mask[2] + set_mask[3];
wire       dec_a    = do_clr && !owner[1] && !late[owner];
wire       dec_l    = do_clr && !owner[1] &&  late[owner];
wire       dec_b    = do_clr &&  owner[1];

    assign grant     = lock ? (4'b0001 << owner) : 4'b0000;
assign occupancy = pcnt + lcnt + bcnt;
assign evt_count = rel_cnt;

always @(posedge clk) begin
    if (ce && rel)
        rel_cnt <= rel_cnt + 4'd1;
end

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ce) begin
            pend <= (pend | set_mask) & ~clr_mask;
pcnt <= pcnt + nset_a - (dec_a ? 3'd1 : 3'd0);
lcnt <= lcnt + nset_l - (dec_l ? 3'd1 : 3'd0);
late <= (late | late_set) & ~late_clr;
bcnt <= bcnt + nset_b - (dec_b ? 3'd1 : 3'd0);
n_in  <= n_in  + {1'b0, nset_a} + {1'b0, nset_l} + {1'b0, nset_b};
n_out <= n_out + {3'd0, dec_a} + {3'd0, dec_l} + {3'd0, dec_b};
            if (lock) begin
                if (rel)
                    lock <= 1'b0;      // frozen winner until it releases
            end else if (any) begin
                lock  <= 1'b1;
                owner <= pick;
            end
        end
    end

    // P: if the pending bitmap did not change, the occupancy must not have
    // changed either, and the occupancy stays within its real bound of 4.
    always @(posedge clk)
        if (pv && $stable(pend))
            assert ($stable(pcnt) && (pcnt <= 3'd4));
endmodule

module gray_quantum_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // scheduler quantum tick enable
    output wire [3:0] o_gray,
    output wire [2:0] o_ones
);
    // Ten quantum slots (0..9). The binary shadow does the arithmetic,
    // the gray register is what leaves the clock domain. Terminal count is
    // detected on the gray word, as the CDC-facing logic sees it.
    localparam [3:0] GRAY_LAST = 4'b1101; // gray code of 4'd9

    reg [3:0] bin  = 4'd0;
    reg [3:0] gray = 4'b0000;

   // Lane B is the second scheduler quantum lane. To save area the two
   // lanes time-share one binary shadow and one increment/encode
   // datapath: the owner named by `turn` uses `bin`, the parked lane's
   // shadow waits in `bin_hold`, and the pair swaps on every tick.
   reg [3:0] gray_b   = 4'b0000;
   reg [3:0] bin_hold = 4'd0;
   reg       turn     = 1'b0;   // 0: lane A owns the shared shadow

  // Lane C is the third quantum lane (background dispatch class). It
  // joins the same time-share: the shadow of the lane two slots ahead of
  // the owner parks in `bin_hold2`, and `grp` widens the ownership
  // pointer so the trio rotates A -> B -> C -> A, one hand-off per tick.
  reg [3:0] gray_c    = 4'b0000;
  reg [3:0] bin_hold2 = 4'd0;
 reg       grp       = 1'b0;   // {turn,grp,ext}: 000=A, 100=B, 010=C, 001=D

 // Lane D is the realtime dispatch class and the last member of the
 // time-share. Its shadow parks one stage deeper, in `bin_hold3`, and
 // `ext` extends the ownership pointer so the hand-off rotates
 // A -> B -> C -> D -> A, one lane per tick.
 reg [3:0] gray_d    = 4'b0000;
 reg [3:0] bin_hold3 = 4'd0;
 reg       ext       = 1'b0;   // 1: lane D owns the shared shadow


 wire [3:0] gray_sel = ext ? gray_d
                           : (turn ? gray_b : (grp ? gray_c : gray));

   wire       wrap    = (gray_sel == GRAY_LAST);
    wire [3:0] bin_nxt = wrap ? 4'd0 : (bin + 4'd1);

    // occupancy of the gray word: how many lanes are asserted this slot
    wire [2:0] ones = {2'b00, gray[0]} + {2'b00, gray[1]} +
                      {2'b00, gray[2]} + {2'b00, gray[3]};
    wire       occ_hi = (ones >= 3'd3);

    assign o_gray = gray;
    assign o_ones = ones;

    always @(posedge clk) begin
        if (rst) begin
            bin  <= 4'd0;
            gray <= 4'b0000;
           gray_b   <= 4'b0000;
           bin_hold <= 4'd0;
           turn     <= 1'b0;
          gray_c    <= 4'b0000;
          bin_hold2 <= 4'd0;
          grp       <= 1'b0;
         gray_d    <= 4'b0000;
         bin_hold3 <= 4'd0;
         ext       <= 1'b0;
        end else if (i_ce) begin
          // the lane owning the datapath advances its gray word, then the
          // shared shadow is handed to the next lane in the rotation
         if (ext)       gray_d <= bin_nxt ^ (bin_nxt >> 1);
         else if (turn) gray_b <= bin_nxt ^ (bin_nxt >> 1);
          else if (grp) gray_c <= bin_nxt ^ (bin_nxt >> 1);
          else          gray   <= bin_nxt ^ (bin_nxt >> 1);
          bin       <= bin_hold;
          bin_hold  <= bin_hold2;
         bin_hold2 <= bin_hold3;
         bin_hold3 <= bin_nxt;
         turn      <= !turn && !grp && !ext;
          grp       <= turn;
         ext       <= !turn && grp;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Bounded existence: the gray word never carries four asserted lanes,
    // so whenever the high-occupancy flag rises it rises to exactly three.
    always @(posedge clk)
        if (pv && $rose(occ_hi))
            assert (ones == 3'd3);

   // Lane coherence: the swap is only half done while lane B holds the
   // shared shadow. Once ownership is back with lane A both lanes have
   // been advanced to the same quantum slot, so the two gray words the
   // CDC side can sample are identical.
   always @(posedge clk)
       if (pv) assert (turn || (gray == gray_b));
endmodule

module elevator_call_gen (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output reg  [1:0] floor,
    output reg        dir,
    output reg  [3:0] pending,
    output reg  [2:0] dry_cnt,
    output reg  [3:0] lf
);
// Pseudo-random hall-call source.  The shift chain and its feedback XOR
// are split across two flops: the tap is evaluated one cycle ahead into
// lf_fb and shifted in on the next enabled step, which keeps the XOR
// gate out of the shift path.  Taps are chosen so that the combined
// 5-bit generator state {lf, lf_fb} is maximal length (period 31).
reg lf_fb;
// Quiet watchdog: reloaded on every hall call and decremented on every
// silent enabled step.  It is the budget of steps the generator may stay
// quiet before the cab is handed a target of its own.
reg [2:0] quiet_wd;
// Reload accounting is split across two flops: on a hall call the counter
// is handed two ticks at once and the third rides in wd_carry, which is
// folded back into the counter on the following quiet step.  That keeps
// the counter's load path a constant, and the budget still outstanding is
// quiet_wd + wd_carry.
reg [1:0] wd_carry;
// Hall calls reach the cab through a one-deep request stage: the
// generator's decision and its floor are captured here and acted on
// the following enabled step, keeping the call decode off the
// pending-mask and watchdog paths.
reg       call_v;
reg [1:0] call_fl;

initial lf_fb   = 1'b0;
    initial lf      = 4'b0001;
    initial floor   = 2'd0;
    initial dir     = 1'b1;   // 1 = up, 0 = down
    initial pending = 4'b0000;
    initial dry_cnt = 3'd0;
    initial quiet_wd = 3'd3;
    initial call_v  = 1'b0;
    initial call_fl = 2'd0;
    initial wd_carry = 2'd0;

wire       lf_fb_next = lf[3] ^ lf[1];
wire [3:0] lf_next    = {lf[2:0], lf_fb};

// A pseudo-random hall call is issued unless the top three shift
// stages of the generator are all zero.
    wire       new_call   = (lf[3:1] != 3'b000);
    wire [1:0] call_floor = lf[1:0];

    wire at_top = (floor == 2'd3);
    wire at_bot = (floor == 2'd0);

    wire [1:0] floor_next = dir ? (at_top ? floor : floor + 2'd1)
                                : (at_bot ? floor : floor - 2'd1);
    wire       dir_next   = dir ? (at_top ? 1'b0 : 1'b1)
                                : (at_bot ? 1'b1 : 1'b0);

    // On the watchdog's last tick a call at the top floor is synthesized,
    // so a quiet generator cannot leave the cab without work.
wire [2:0] wd_left    = quiet_wd + {1'b0, wd_carry};
wire       wd_last    = (wd_left <= 3'd1);
    wire [3:0] set_mask   = call_v ? (4'b0001 << call_fl)
                                   : (wd_last ? 4'b1000 : 4'b0000);
    wire [3:0] clr_mask   = (4'b0001 << floor);

    always @(posedge clk) begin
        if (rst) begin
            lf      <= 4'b0001;
lf_fb   <= 1'b0;
            floor   <= 2'd0;
            dir     <= 1'b1;
            pending <= 4'b0000;
            dry_cnt <= 3'd0;
            quiet_wd <= 3'd3;
            call_v  <= 1'b0;
            call_fl <= 2'd0;
            wd_carry <= 2'd0;
        end else if (step) begin
            lf      <= lf_next;
lf_fb   <= lf_fb_next;
            call_v  <= new_call;
            call_fl <= call_floor;
            floor   <= floor_next;
            dir     <= dir_next;
            pending <= (pending | set_mask) & ~clr_mask;
            // consecutive enabled steps during which no new call appeared
            dry_cnt <= call_v ? 3'd0 : (dry_cnt + 3'd1);
            quiet_wd <= call_v ? 3'd2
                               : (quiet_wd == 3'd0 ? 3'd0 : quiet_wd - 3'd1)
                                 + (wd_carry != 2'd0 ? 3'd1 : 3'd0);
            // the deferred tick of the reload, merged one step later
            wd_carry <= call_v ? 2'd1
                               : (wd_carry == 2'd0 ? 2'd0 : wd_carry - 2'd1);
        end
    end

    // Bounded existence: the call-starvation streak never exceeds 3,
    // although the counter is 3 bits wide.
    assert property (dry_cnt <= 3'd3);

    // The watchdog always has budget left over: calls arrive in time.
    always @(posedge clk)
        assert (quiet_wd >= 3'd1);
endmodule

// Triple-modular-redundant power-rail sequencer step counter.
// Three shadow copies of the sequencer step code are advanced independently;
// the exported step code is the bitwise majority vote of the three copies.
// prev_voted is a precedence shadow: it records the voted code as it was at
// the previous advance, so the present code must be the successor of the code
// that was observed earlier.
module tmr_rail_sequencer (
    input  wire       clk,
    input  wire       ce,        // advance / load enable; low => design idles
    input  wire       load,      // reload the sequencer with an external code
    input  wire [2:0] code_in,
    input  wire       q_start,   // opens the monitoring window
    input  wire       r_stop,    // closes the monitoring window
    output wire [2:0] voted
);

    // three shadow registers of the TMR voter
    reg [2:0] shadow_a = 3'd1;
    reg [2:0] shadow_b = 3'd1;
    reg [2:0] shadow_c = 3'd1;
    // Ring bounds of the rail ramp. The last load fixes the origin:
    // base_code is the first code of the ring and top_code the code after
    // which the sequencer wraps back to the origin. at_top is the registered
    // terminal-count flag, kept out of the voter's compare path.
    reg [2:0] base_code = 3'd1;
    reg [2:0] top_code  = 3'd0;
    reg       at_top    = 1'b0;
   // Wrap reseed value: the predecessor of the ring origin, captured when the
   // origin is loaded so that the wrap path carries no decrementer.
   reg [2:0] seed_code = 3'd0;
   // Load phase: alternate loads program the origin, then the wrap point.
   reg       cfg_sel   = 1'b0;
  // Ramp length: index of the last step of the ring, counted from the origin.
  // A fresh origin load opens the ring to its full length; a wrap-point load
  // narrows it. pos is the index of the code held in the precedence shadow,
  // so that path can time the wrap without carrying a code comparator.
  reg [2:0] ring_len = 3'd7;
  reg [2:0] pos      = 3'd0;

// Precedence shadow, split for radiation tolerance: the low two bits of the
// recorded code ripple in prev_lo, while its top bit is kept as a dual-rail
// pair whose advance is a swap of the two rails.
reg [1:0] prev_lo   = 2'd0;
reg       prev_hi_t = 1'b0;
reg       prev_hi_f = 1'b1;

    // window register: set by q_start, cleared by r_stop, reopenable
    reg       win = 1'b0;

    // bitwise majority vote
    assign voted = (shadow_a & shadow_b) | (shadow_a & shadow_c) |
                   (shadow_b & shadow_c);

// recomposed precedence code
wire [2:0] prev_voted = {prev_hi_t, prev_lo};
    // code the shadows will hold after the next advance
    wire [2:0] next_code = at_top ? base_code : voted + 3'd1;
  // Diverse terminal check for the precedence path: it re-derives the wrap
  // condition from the step index and the configured ramp length instead of
  // reusing the voter's flag or its code compare.
  wire       prev_wrap = (pos == ring_len);
  // Ramp length carried by a wrap-point load word.
  wire [2:0] len_in    = code_in - base_code;

    always @(posedge clk) begin
        if (ce) begin
            if (load) begin
               if (!cfg_sel) begin
                shadow_a   <= code_in;
                shadow_b   <= code_in;
                shadow_c   <= code_in;
prev_lo   <= code_in[1:0] - 2'd1;
prev_hi_t <= code_in[2] ^ (code_in[1:0] == 2'd0);
prev_hi_f <= ~(code_in[2] ^ (code_in[1:0] == 2'd0));
               base_code  <= code_in;
               seed_code  <= code_in - 3'd1;
               top_code   <= code_in - 3'd1;
               at_top     <= 1'b0;
              // a fresh origin opens the ring out to its full length
              ring_len   <= 3'd7;
              pos        <= 3'd0;
               end else begin
                   // a second load moves the wrap point of the ramp
                   top_code <= code_in;
                  ring_len <= len_in;
                  at_top   <= (pos == len_in);
               end
               cfg_sel <= ~cfg_sel;
            end else begin
               if (at_top) begin
                   shadow_a   <= base_code;
                   shadow_b   <= base_code;
                   shadow_c   <= base_code;
               end else begin
                   shadow_a   <= shadow_a + 3'd1;
                   shadow_b   <= shadow_b + 3'd1;
                   shadow_c   <= shadow_c + 3'd1;
               end
               at_top <= (next_code == top_code);
             // the precedence index rolls with the code it records
             pos <= prev_wrap ? 3'd0 : pos + 3'd1;
              if (prev_wrap) begin
                  // reseed the precedence shadow to the origin's predecessor
                  prev_lo   <= seed_code[1:0];
                  prev_hi_t <= seed_code[2];
                  prev_hi_f <= ~seed_code[2];
              end else begin
                  prev_lo <= voted[1:0];
                  // the top bit only moves when the low part rolls over
                  if (prev_lo == 2'd3) begin
                      prev_hi_t <= prev_hi_f;
                      prev_hi_f <= prev_hi_t;
                  end
              end
            end
        end
    end

    always @(posedge clk) begin
        if (r_stop)
            win <= 1'b0;
        else if (q_start)
            win <= 1'b1;
    end

    // Property: inside the monitoring window, the voted step code must be the
    // immediate successor of the code recorded earlier in prev_voted.
    always @(posedge clk)
        assert (!win || (voted == prev_voted + 3'd1));

endmodule

module lock_arbiter_occ (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire [3:0] i_req,
    output wire [3:0] o_grant,
    output wire       o_busy
);
    // fixed-priority arbiter with a lock bit that freezes the winner
    reg [3:0] grant;
    reg       lock;
    // shadow occupancy counter: how many grants are currently outstanding
    reg [2:0] occ;
    // lock-hold timer: beats the current owner has held the bus
    reg [2:0] hold_cnt;
   // bus turnaround: dead beats after a release before the slot is freed
   reg [1:0] tail_cnt;
   // one-deep drain slot: a released owner keeps its occupancy credit
   // here until the credit-return beat that follows the turnaround
   reg        drn;
   // handoff park slot: on the last turnaround beat the occupancy credit
   // leaves the counter and waits here, either for a channel that is
   // already asking to take it, or for the pool refill
   reg        park;

    initial grant = 4'b0000;
    initial lock  = 1'b0;
    initial occ   = 3'd0;
    initial hold_cnt = 3'd0;
   initial tail_cnt = 2'd0;
   initial drn = 1'b0;
   initial park = 1'b0;

    wire        busy    = (grant != 4'b0000);
    wire        any_req = (i_req != 4'b0000);

    // fixed priority: channel 0 highest
    wire [3:0] pri_grant = i_req[0] ? 4'b0001 :
                           i_req[1] ? 4'b0010 :
                           i_req[2] ? 4'b0100 :
                           i_req[3] ? 4'b1000 : 4'b0000;
    // anti-starvation: the lock expires after 5 held beats so lower channels can win
    wire lock_expired = (hold_cnt >= 3'd5);

    // while locked, the current winner keeps the bus as long as it still asks
    wire holding = busy && lock && !lock_expired && ((grant & i_req) != 4'b0000);

    always @(posedge i_clk) begin
        if (i_rst) begin
            grant <= 4'b0000;
            lock  <= 1'b0;
            occ   <= 3'd0;
            hold_cnt <= 3'd0;
           tail_cnt <= 2'd0;
           drn <= 1'b0;
           park <= 1'b0;
        end else if (i_ce) begin
            if (busy) begin
                if (!holding) begin
                   // winner released: drop the grant and start the bus turnaround
                    grant <= 4'b0000;
                    lock  <= 1'b0;
                   tail_cnt <= 2'd2;
                    hold_cnt <= 3'd0;
                   drn <= 1'b1;
                end
                else begin
                    // still holding: age the lock
                    hold_cnt <= hold_cnt + 3'd1;
                end
           end else if (tail_cnt != 2'd0) begin
              // turnaround: dead beats before the drain slot may empty
               tail_cnt <= tail_cnt - 2'd1;
              if (tail_cnt == 2'd1) begin
                  // last dead beat: the credit moves into the park slot
                  occ  <= occ - 3'd1;
                  park <= 1'b1;
              end
          end else if (drn) begin
              if (park && any_req) begin
                  // express handoff: a channel that is already waiting takes
                  // the parked credit instead of cycling it through the pool
                  grant <= pri_grant;
                  lock  <= 1'b1;
                  hold_cnt <= 3'd0;
                  occ  <= occ + 3'd1;
                  park <= 1'b0;
                  drn  <= 1'b0;
              end else begin
                  // credit-return beat: the parked credit goes back to the pool
                  drn  <= 1'b0;
                  park <= 1'b0;
              end
           end else if (any_req) begin
                // bus free: award it and lock it
                grant <= pri_grant;
                lock  <= 1'b1;
                occ   <= occ + 3'd1;
                hold_cnt <= 3'd0;
            end
        end
    end

    assign o_grant = grant;
   assign o_busy  = busy || (tail_cnt != 2'd0) || drn || park;

    // at most one grant may be outstanding at any time
    always @(*)
        assert (occ <= 3'd1);

    // the hold timer only ages while a grant is outstanding
    always @(posedge i_clk)
        assert ((hold_cnt == 3'd0) || (occ == 3'd1));
endmodule

module lex_onehot_esc (
    input wire       i_clk,
    input wire       i_reset,
    input wire       i_ce,
    input wire [7:0] i_char,
    output wire      o_in_string,
    output wire [3:0] o_esc_count
);
    // one-hot lexer state: exactly one bit set by construction
    localparam S_IDLE  = 0;
    localparam S_IDENT = 1;
    localparam S_NUM   = 2;
    localparam S_STR   = 3;
    localparam S_ESC   = 4;

    reg [4:0] st;
    reg [3:0] cnt;   // escape sequences counted in the current string literal
   reg [3:0] lim;   // escape budget for the current string literal (default 8)
   reg [3:0] pend;  // escape count parked between concatenated string segments
    reg       arm;   // sticky: set the first time a string literal is being scanned
    reg       pv;
   reg [3:0] n_op;  // ledger: backslashes logged while scanning a literal
   reg [3:0] n_rt;  // ledger: ESC cycles handed back to STR

    initial st  = 5'b00001;
    initial cnt = 4'd0;
   initial lim = 4'd8;
   initial pend = 4'd0;
    initial arm = 1'b0;
    initial pv  = 1'b0;
   initial n_op = 4'd0;
   initial n_rt = 4'd0;

    wire is_q   = (i_char == 8'h22);
    wire is_bs  = (i_char == 8'h5C);
    wire is_dig = (i_char >= 8'h30) && (i_char <= 8'h39);
    wire is_alp = ((i_char | 8'h20) >= 8'h61) && ((i_char | 8'h20) <= 8'h7A);

   // a numeric prefix before a literal programs the escape budget, clamped to 8
   wire [3:0] dig_lim = (i_char[3:0] > 4'd8) ? 4'd8 : i_char[3:0];

   // escape opens that have been logged but not yet retired by the ESC state
   wire [3:0] out_esc = n_op - n_rt;

    reg [4:0] nst;
    reg [3:0] ncnt;
   reg [3:0] nlim;
   reg [3:0] npend;

    always @(*) begin
        nst  = st;
        ncnt = cnt;
       nlim = lim;
       npend = pend;
        if (st[S_IDLE]) begin
            if (is_q) begin
               nst   = 5'b01000;  // open quote: resume a continued literal
               ncnt  = pend;      // adjacent segments share one escape count
               npend = 4'd0;
           end else if (is_dig) begin
               nst  = 5'b00100;
               nlim = dig_lim;    // leading digit programs the budget
              npend = 4'd0;      // a numeric prefix ends any concatenation
           end
           else if (is_alp) begin
               nst   = 5'b00010;
               npend = 4'd0;      // an identifier ends any concatenation
           end
            else
                nst = 5'b00001;
        end else if (st[S_IDENT]) begin
            nst = (is_alp || is_dig) ? 5'b00010 : 5'b00001;
        end else if (st[S_NUM]) begin
            nst = is_dig ? 5'b00100 : 5'b00001;
           if (is_dig) nlim = dig_lim;   // later digits override the budget
        end else if (st[S_STR]) begin
            if (is_q) begin
               nst  = 5'b00001;   // close quote: budgeted escapes retire here
               ncnt = (cnt > lim) ? (cnt - lim) : 4'd0;  // surplus carries on
              npend = cnt;       // park the count in case the literal continues
            end else if (is_bs)
                nst = 5'b10000;    // ESC is reachable only from STR
            else
                nst = 5'b01000;
        end else if (st[S_ESC]) begin
            nst  = 5'b01000;       // ESC always returns to STR
           // charge the budget for every outstanding logged escape open
           ncnt = (cnt >= lim) ? cnt : (cnt + out_esc);   // saturate at the budget
        end
    end

    always @(posedge i_clk) begin
        if (i_reset) begin
            st  <= 5'b00001;
            cnt <= 4'd0;
           lim <= 4'd8;
           pend <= 4'd0;
           n_op <= 4'd0;
           n_rt <= 4'd0;
        end else if (i_ce) begin
            st  <= nst;
            cnt <= ncnt;
           lim <= nlim;
           pend <= npend;
           n_op <= n_op + {3'b0, (st[S_STR] && is_bs)};
           n_rt <= n_rt + {3'b0, st[S_ESC]};
        end

        if (i_ce && !i_reset && (st[S_STR] || st[S_ESC]))
            arm <= 1'b1;

        pv <= 1'b1;
    end

    assign o_in_string  = st[S_STR] || st[S_ESC];
    assign o_esc_count  = cnt;

    // Universality, in the "after arm" scope, stated about the previous cycle:
    // once a string literal has been seen, the escape counter is always zero
    // whenever the lexer sits in the IDLE state.
    always @(posedge i_clk)
        if (pv && arm)
            assert (!$past(st[S_IDLE]) || ($past(cnt) == 4'd0));
endmodule

module debounce_hist_arm (
    input  wire i_clk,
    input  wire i_ce,
    input  wire i_raw,
    output wire o_clean,
    output wire o_armed,
    output wire o_settled
);
    // K identical consecutive samples are required before the clean output flips.
    localparam [2:0] KC = 3'd4;
   localparam [2:0] KS = 3'd6;   // validated filter: longer confirm window
    localparam       HW = 8;

    reg [2:0]      cnt;     // stability counter, saturates at KC
    reg            sample;  // current candidate level being timed
    reg            clean;   // debounced (committed) level
    reg [HW-1:0]   hist;    // raw sample history, hist[0] is the newest sample
    reg            armed;   // sticky: set the first time the filter commits
   reg            stable;  // registered settled flag, drives o_settled
reg            pend;    // pending level change: candidate differs from the committed level
   reg            tgt;     // latched target level of the outstanding change request
   reg [3:0]      n_req;   // ledger: change requests logged (free-running, wraps)
   reg [3:0]      n_ret;   // ledger: change requests retired (free-running, wraps)
  reg            clean_s; // validated level published by the slow filter
  reg            pend_s;  // validated change pending against clean_s
  reg            armed_s; // sticky: the slow filter has committed once

    initial cnt    = 3'd0;
    initial sample = 1'b0;
    initial clean  = 1'b0;
    initial hist   = {HW{1'b0}};
    initial armed  = 1'b0;
   initial stable = 1'b0;
initial pend   = 1'b0;
   initial tgt    = 1'b0;
   initial n_req  = 4'd0;
   initial n_ret  = 4'd0;
  initial clean_s = 1'b0;
  initial pend_s  = 1'b0;
  initial armed_s = 1'b0;

  // Level the validated filter will publish at its next commit.
  wire s_lvl = clean_s ^ pend_s;

    always @(posedge i_clk) if (i_ce) begin
        hist <= { hist[HW-2:0], i_raw };
        if (i_raw != sample) begin
            // new level seen: retime from scratch
            sample <= i_raw;
            cnt    <= 3'd0;
           stable <= 1'b0;
pend   <= i_raw ^ clean;
          pend_s <= i_raw ^ clean_s;
           // A retime either opens a new request against the committed level or
           // retires the one already logged; the target level is captured on open.
           if (n_req == n_ret) begin
               tgt   <= i_raw;
               n_req <= n_req + 4'd1;
           end else begin
               n_ret <= n_ret + 4'd1;
           end
       end else if (cnt < KS) begin
            cnt <= cnt + 3'd1;
            if (cnt == (KC - 3'd1)) begin
                // KC identical consecutive samples: commit the level
               if (pend) begin
                   clean <= tgt;
                   n_ret <= n_ret + 4'd1;
               end
pend  <= 1'b0;
                armed <= 1'b1;
               stable <= 1'b1;
            end
           if (cnt == (KS - 3'd1)) begin
               // KS identical samples: the validated filter commits.  It is the
               // authority on the level, so a fast output that has drifted away
               // is resynced here and its outstanding request retired.
               clean_s <= s_lvl;
               pend_s  <= 1'b0;
               armed_s <= 1'b1;
               if (s_lvl != clean) begin
                   clean <= s_lvl;
                   if (pend) n_ret <= n_ret + 4'd1;
                   pend  <= 1'b0;
               end
           end
        end
    end

    assign o_clean   = clean;
   assign o_armed   = armed && armed_s;
   assign o_settled = stable;

    // Universality, after the filter has armed: whenever the stability counter
    // is nonzero the two newest raw samples must agree.
    always @(*)
        if (armed)
            assert ((cnt == 3'd0) || (hist[1] == hist[0]));

   // While the filter reports settled, the committed level must still match the
   // newest raw sample: any disagreement would mean a missed retime.
   always @(posedge i_clk)
       assert (!stable || (clean == hist[0]));
endmodule

module wdog_gray_mon (
    input  wire i_clk,
    input  wire i_rst,
    input  wire i_ce,      // idle condition: all state frozen when low
    input  wire i_arm,     // Q: opens the monitoring window
    input  wire i_ack,     // R: closes the monitoring window
    output wire o_bite,
    output wire o_grace,
output wire o_sys_reset,
output reg [3:0] o_dbg_ce_cnt
);
    // ---- timer domain: free running gray coded tick pointer -------------
    reg [2:0] cnt;   // binary tick counter
    reg [2:0] g;     // registered gray code of cnt

    // ---- monitor domain: two flop synchronizer on the gray pointer ------
    reg [2:0] s1, s2;

    // monitor side tally of pointer advances observed since reset
    reg [2:0] adv_cnt;

    // ---- window / latched reset ----------------------------------------
    reg armed;
    reg rst_latch;

   // ---- warning marker --------------------------------------------------
   // Decoded pointer position at which the grace flag is raised.  The
   // marker is re-placed relative to the pointer each time the window is
   // closed, so successive windows warn at different phases of the lap.
   reg [2:0] warn;
reg dbg_tog;

    initial cnt       = 3'd0;
    initial g         = 3'd0;
    initial s1        = 3'd0;
    initial s2        = 3'd0;
    initial adv_cnt   = 3'd0;
    initial armed     = 1'b0;
    initial rst_latch = 1'b0;
   initial warn      = 3'd2;
initial o_dbg_ce_cnt = 4'd0;
initial dbg_tog      = 1'b0;

    wire [2:0] nxt = cnt + 3'd1;

    always @(posedge i_clk)
        if (i_rst) begin
            cnt <= 3'd0;
            g   <= 3'd0;
        end else if (i_ce) begin
            cnt <= nxt;
            g   <= nxt ^ (nxt >> 1);
        end

    always @(posedge i_clk)
        if (i_rst) begin
            s1 <= 3'd0;
            s2 <= 3'd0;
            adv_cnt <= 3'd0;
        end else if (i_ce) begin
            s1 <= g;    // first flop: freshly captured pointer
            s2 <= s1;   // second flop: stable pointer sample
            // every time the stable sample moves, the monitor has seen
            // one more tick of the timer domain
            if (s1 != s2) adv_cnt <= adv_cnt + 3'd1;
        end

    // gray -> binary decode of both synchronizer stages
    wire [2:0] mon = { s2[2], s2[2]^s2[1], s2[2]^s2[1]^s2[0] };
    wire [2:0] pre = { s1[2], s1[2]^s1[1], s1[2]^s1[1]^s1[0] };

    // terminal count seen on the stable sample -> watchdog bites
    assign o_bite  = (mon == 3'd7);
    // deep inside the grace region on the freshly captured sample
   assign o_grace = (pre == warn);

    assign o_sys_reset = rst_latch;

    // half a lap of observed advances: by now the all zero power up sample
    // has been flushed out of the synchronizer
    wire startup_done = adv_cnt[2];

   // next marker placement: two ticks past where the pointer stands when
   // the window is closed
   wire [2:0] warn_nxt = pre + 3'd2;
   // a marker sitting on the terminal tick or on the wrap tick would put
   // the grace pulse on top of the bite, which is not a usable placement,
   // so an arm request is refused until the marker has been moved
   wire       warn_ok  = (warn != 3'd0) && (warn != 3'd7);

    always @(posedge i_clk)
        if (i_rst) begin
            armed     <= 1'b0;
            rst_latch <= 1'b0;
           warn      <= 3'd2;
o_dbg_ce_cnt <= 4'd0;
dbg_tog      <= 1'b0;
        end else if (i_ce) begin
            if (i_ack)      armed <= 1'b0;
           else if (i_arm && warn_ok) armed <= 1'b1;

           // re-place the marker for the next window
           if (i_ack) warn <= warn_nxt;

            if (i_ack)                     rst_latch <= 1'b0;
            else if (armed && o_bite && startup_done)
                                           rst_latch <= 1'b1;
dbg_tog <= ~dbg_tog;
if (dbg_tog && i_arm) o_dbg_ce_cnt <= o_dbg_ce_cnt + 4'd1;
        end

    // P: inside the monitoring window the bite and grace indications are
    // never asserted together.
    always @(posedge i_clk)
        if (armed)
            assert (!(o_bite && o_grace));

    // P2: a bite is only ever reported when the monitor has tallied a full
    // lap of observed pointer advances.
    always @(posedge i_clk)
        assert (!o_bite || adv_cnt == 3'd7);
endmodule

// Priority arbiter for per-subchannel energy detect flags.
// Stage 0: combinational priority encode of the request vector.
// Stage 1: registered half-occupancy flags + priority-half decision.
// Stage 1b: the decision is retimed through a second register so the grant
//          flags and the accounting write leave stage 1 on the same path.
// Stage 2: registered valid, registered index (only meaningful while valid),
//          and the two half-band grant flags.
module wifi_pri_grant (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [7:0] i_req,
    output reg        o_vld,
    output reg  [2:0] o_idx,
    output reg        o_grant_lo,
    output reg        o_grant_hi
);
    // ---------------- stage 0: combinational priority encoder ------------
    wire req_lo = |i_req[3:0];
    wire req_hi = |i_req[7:4];

    reg [2:0] enc;
    always @(*) begin
        casez (i_req)
            8'b???????1: enc = 3'd0;
            8'b??????10: enc = 3'd1;
            8'b?????100: enc = 3'd2;
            8'b????1000: enc = 3'd3;
            8'b???10000: enc = 3'd4;
            8'b??100000: enc = 3'd5;
            8'b?1000000: enc = 3'd6;
            8'b10000000: enc = 3'd7;
            default:     enc = 3'd0;
        endcase
    end

    // ---------------- stage 1 registers ---------------------------------
    reg       s1_vld;
    reg       s1_req_lo;
    reg       s1_req_hi;
    reg       s1_pri_hi;   // upper half wins only when lower half is empty
    reg [2:0] s1_idx;

  // ---------------- stage 1b: retimed decision -------------------------
  // The output pins and the retention-domain counters sit far apart, so the
  // stage-1 decision is carried one more register before it is used.
  reg       s1b_vld;
  reg       s1b_req_lo;
  reg       s1b_req_hi;
  reg       s1b_pri_hi;
  reg [2:0] s1b_idx;

   // ---------------- accounting park slot -------------------------------
   // cnt_hi lives in the slow retention domain and needs a cycle of its own
   // to absorb a write, so an upper-band grant is parked for one cycle
   // together with the energy flag of the cycle it came from.  Stage 1 stops
   // issuing while the slot is in use, so only one upper-band event is ever
   // in flight.
   reg       park_hi;
   reg       park_act;
  wire      acct_busy = (s1_vld && s1_pri_hi) || (s1b_vld && s1b_pri_hi) ||
                        park_hi;

   // ---------------- stage 2 grant accounting --------------------------
   // Per-band grant counters plus a counter of cycles in which any band
   // reported energy.  Firmware samples their low bits on the index bus
   // while the pipe is idle (o_idx carries no index when o_vld is low).
   reg [3:0] cnt_lo;
   reg [3:0] cnt_hi;
   reg [3:0] cnt_tot;

    initial begin
        s1_vld    = 1'b0;
        s1_req_lo = 1'b0;
        s1_req_hi = 1'b0;
        s1_pri_hi = 1'b0;
        s1_idx    = 3'd0;
      s1b_vld    = 1'b0;
      s1b_req_lo = 1'b0;
      s1b_req_hi = 1'b0;
      s1b_pri_hi = 1'b0;
      s1b_idx    = 3'd0;
       park_hi   = 1'b0;
       park_act  = 1'b0;
       cnt_lo     = 4'd0;
       cnt_hi     = 4'd0;
       cnt_tot    = 4'd0;
        o_vld      = 1'b0;
        o_idx      = 3'd0;
        o_grant_lo = 1'b0;
        o_grant_hi = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // stage 1 capture
s1_vld    <= (req_lo | req_hi) && !acct_busy;
            s1_req_lo <= req_lo;
            s1_req_hi <= req_hi;
            s1_pri_hi <= req_hi && !req_lo;
            s1_idx    <= enc;

           // stage 1b capture
           s1b_vld    <= s1_vld;
           s1b_req_lo <= s1_req_lo;
           s1b_req_hi <= s1_req_hi;
           s1b_pri_hi <= s1_pri_hi;
           s1b_idx    <= s1_idx;

            // stage 2 capture
           o_vld      <= s1b_vld;
           // idle index bus carries a compact counter status code
          o_idx      <= s1b_vld ? s1b_idx
                                : {cnt_tot[0], cnt_hi[0], cnt_lo[0]};
           o_grant_lo <= s1b_vld && s1b_req_lo;
           o_grant_hi <= s1b_vld && s1b_pri_hi;

          // grant accounting, driven off the retimed stage-1b decision
          park_hi  <= s1b_vld && s1b_pri_hi;
          park_act <= (s1b_vld && s1b_pri_hi) && (s1b_req_lo || s1b_req_hi);
          if (s1b_vld && s1b_req_lo)
               cnt_lo  <= cnt_lo  + 4'd1;
if (park_hi)
               cnt_hi  <= cnt_hi  + 4'd1;
if ((s1b_vld && !s1b_pri_hi && (s1b_req_lo || s1b_req_hi)) || park_act)
               cnt_tot <= cnt_tot + 4'd1;
        end
    end

    // P: while the encoded index is valid, the two half-band grants are
    //    never asserted together.
    always @(posedge clk)
        if (o_vld)
            assert (!(o_grant_lo && o_grant_hi));

   // Q: the per-band grant counters account for exactly the counted
   //    request cycles.
   always @(posedge clk)
       assert (cnt_tot == cnt_lo + cnt_hi);

endmodule

// Transaction scoreboard with a completion deadline countdown.
// issued/retired are wrapping transaction counters; outst is the occupancy
// of the issue window (WINDOW deep). Every outstanding transaction is forced
// to retire before its RELOAD-cycle deadline countdown reaches zero.
module scoreboard_deadline (
    input  wire clk,
    input  wire ce,      // idle condition: ce low freezes the scoreboard
    input  wire issue,
    input  wire retire,
output wire busy,
output reg [3:0] evt_count
);
    localparam [2:0] WINDOW = 3'd4;
    localparam [2:0] RELOAD = 3'd5;
    localparam [1:0] QDEPTH = 2'd2;   // staging queue in front of the window
   localparam [1:0] CDEPTH = 2'd2;   // completion buffer inside the window

    reg [3:0] issued;
    reg [3:0] retired;
    reg [2:0] outst;    // outstanding transactions = issued - retired
    reg [1:0] queued;   // accepted, still waiting for a free window slot
   reg [1:0] qb;       // class-B staging queue sharing the same window
   reg [1:0] cdone;    // response landed, retirement handshake still pending
   reg       rr;       // round-robin pointer for the freed window slot
    reg [2:0] timer;    // deadline countdown for the oldest outstanding item
    reg       armed;    // sticky: set the first time a transaction is accepted
    reg       pv;       // past valid
reg [2:0] hist;     // sampled pin activity history (observability only)

    initial begin
        issued  = 4'd0;
        retired = 4'd0;
        outst   = 3'd0;
        queued  = 2'd0;
       qb      = 2'd0;
       cdone   = 2'd0;
       rr      = 1'b0;
        timer   = 3'd0;
        armed   = 1'b0;
        pv      = 1'b0;
evt_count = 4'd0;
hist      = 3'd0;
    end

   assign busy = (outst != 3'd0) || (queued != 2'd0) || (qb != 2'd0) || (cdone != 2'd0);

    // deadline flag: the countdown has run out
    wire expired = (timer == 3'd0);

    // the design completes a transaction itself when the deadline is imminent
    wire force_ret = (outst != 3'd0) && (timer == 3'd1);
   // window occupancy: response-pending entries plus entries whose response
   // has landed and that are waiting for the retirement handshake
   wire [2:0] occ = outst + {1'b0, cdone};
   wire cdone_room = (cdone < CDEPTH);

   wire [3:0] total = {1'b0, occ} + {2'b0, queued} + {2'b0, qb};

   // accept while the window plus both staging queues still have capacity
   wire do_issue  = ce && issue && (total < ({1'b0, WINDOW} + {2'b0, QDEPTH} + {2'b0, QDEPTH}));
   // a response moves the transaction out of the pipeline into the buffer
   wire do_resp   = ce && (outst != 3'd0) && (retire || force_ret) && cdone_room;
   // the buffer gives one entry back per enabled cycle; that handshake is
   // what advances the retire counter and releases the window slot
   wire do_retire = ce && (cdone != 2'd0);

    // a window slot is free, or is being freed by this cycle's retirement
   wire slot_free = (occ < WINDOW) || do_retire;
   // staged transactions are older than an incoming one, so they go first;
   // the two classes take turns for the slot the window frees up
   wire admit_a = ce && (queued != 2'd0) && slot_free && (!rr || (qb == 2'd0));
   wire admit_b = ce && (qb != 2'd0) && slot_free && !admit_a;
   wire admit   = admit_a || admit_b;
   wire direct  = do_issue && slot_free && !admit;
   wire enq     = do_issue && !direct;
   // a fresh transaction joins the shorter of the two queues
   wire enq_a   = enq && (queued <= qb);
   wire enq_b   = enq && !enq_a;

    wire [2:0] outst_n  = outst + ((admit || direct) ? 3'd1 : 3'd0)
                               - (do_resp ? 3'd1 : 3'd0);
   wire [1:0] queued_n = queued + (enq_a ? 2'd1 : 2'd0)
                                - (admit_a ? 2'd1 : 2'd0);
   wire [1:0] qb_n     = qb + (enq_b ? 2'd1 : 2'd0)
                            - (admit_b ? 2'd1 : 2'd0);
   wire [1:0] cdone_n  = cdone + (do_resp ? 2'd1 : 2'd0)
                               - (do_retire ? 2'd1 : 2'd0);

    always @(posedge clk) begin
        pv <= 1'b1;

        if (do_issue) begin
            armed  <= 1'b1;
            issued <= issued + 4'd1;
        end

        if (do_retire)
            retired <= retired + 4'd1;

        outst <= outst_n;
       queued <= queued_n;
       qb     <= qb_n;
       cdone  <= cdone_n;
       if (admit) rr <= admit_a;

       if (do_issue || do_resp) begin
            // any scoreboard event restarts (or clears) the deadline
           if (outst_n == 3'd0 && queued_n == 2'd0 && qb_n == 2'd0) timer <= 3'd0;
            else                 timer <= RELOAD;
        end else if (ce && (outst != 3'd0)) begin
            timer <= timer - 3'd1;
        end
if (ce) begin
    hist      <= {hist[1:0], issue ^ retire};
    evt_count <= evt_count + {3'd0, (hist[2] ^ retire)};
end
    end

    // Bounded response, safety form, in no-change style, scoped after arming:
    // once a transaction has been accepted, whenever the outstanding count did
    // not change and work is still outstanding, the deadline flag must not
    // change either (i.e. the countdown cannot expire under an outstanding
    // request).
    always @(posedge clk) begin
        if (pv && armed && (outst != 3'd0) && $stable(outst))
            assert ($stable(expired));
    end
endmodule

module hwm_stack_ptr (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_push,
    input  wire       i_pop,
    output wire       o_deep,
    output wire [3:0] o_mark,
    output wire [3:0] o_sp
);
    localparam [3:0] THRESH = 4'd4;

    // stack pointer and its high-water mark
    reg [3:0] sp;
    reg [3:0] hwm;
    reg       mark_deep;   // registered "mark has crossed THRESH" flag
    reg       pv;          // past-valid

   // push/pop event ledger for depth accounting: every accepted push and
   // every accepted pop is logged, and the difference of the two counters
   // is the occupancy the mark logic trusts
   reg [3:0] n_push;
   reg [3:0] n_pop;

  // deep-region episode ledger: one entry logged each time the pointer
  // crosses up into the deep region, one exit each time it drops back out
  reg [3:0] n_ent;
  reg [3:0] n_ext;
 // deep-excursion ledger: one entry per slot taken above the threshold
 // line, one exit per slot given back, used to size the reserved band
 reg [3:0] n_dp_in;
 reg [3:0] n_dp_out;

    initial sp        = 4'd0;
    initial hwm       = 4'd0;
    initial mark_deep = 1'b0;
    initial pv        = 1'b0;
   initial n_push    = 4'd0;
   initial n_pop     = 4'd0;
  initial n_ent     = 4'd0;
  initial n_ext     = 4'd0;
 initial n_dp_in   = 4'd0;
 initial n_dp_out  = 4'd0;

    wire do_push = i_ce && i_push && !i_pop && (sp != 4'hF);
    wire do_pop  = i_ce && i_pop  && !i_push && (sp != 4'h0);

    wire [3:0] sp_nx  = do_push ? (sp + 4'd1)
                      : (do_pop ? (sp - 4'd1) : sp);

   wire [3:0] n_push_nx = do_push ? (n_push + 4'd1) : n_push;
   wire [3:0] n_pop_nx  = do_pop  ? (n_pop  + 4'd1) : n_pop;

   // occupancy as seen by the ledger after this cycle's events
   wire [3:0] occ_nx    = n_push_nx - n_pop_nx;

  wire ent_evt = do_push && (sp == (THRESH - 4'd1));
  wire ext_evt = do_pop  && (sp == THRESH);

  wire [3:0] n_ent_nx = ent_evt ? (n_ent + 4'd1) : n_ent;
  wire [3:0] n_ext_nx = ext_evt ? (n_ext + 4'd1) : n_ext;
 wire dp_in_evt  = do_push && (sp >= THRESH);
 wire dp_out_evt = do_pop  && (sp >  THRESH);
 wire [3:0] n_dp_in_nx  = dp_in_evt  ? (n_dp_in  + 4'd1) : n_dp_in;
 wire [3:0] n_dp_out_nx = dp_out_evt ? (n_dp_out + 4'd1) : n_dp_out;
 // slots the excursion ledger says are consumed above the threshold
 wire [3:0] excess_nx   = n_dp_in_nx - n_dp_out_nx;
 // while the ledger shows an outstanding excursion the mark covers the
 // whole reserved band: the threshold plus every logged slot above it
 wire [3:0] reserve     = (excess_nx != 4'd0) ? (THRESH + excess_nx) : 4'd0;

  // an episode is open while the entry and exit logs disagree; for the
  // whole episode the mark reserves one guard slot above the threshold
  wire       deep_open = (n_ent != n_ext);
  wire [3:0] guard     = deep_open ? (THRESH + 4'd1) : 4'd0;

   // the mark must cover both the pointer and the logged occupancy
  wire [3:0] mark_hi   = (sp_nx > occ_nx) ? sp_nx : occ_nx;
 wire [3:0] mark_g    = (mark_hi > guard) ? mark_hi : guard;
 wire [3:0] mark_lo   = (mark_g > reserve) ? mark_g : reserve;

    // the mark never falls below the pointer and only ratchets upward
   wire [3:0] hwm_nx = (mark_lo > hwm) ? mark_lo : hwm;

    always @(posedge clk) begin
        if (i_ce) begin
            sp        <= sp_nx;
            hwm       <= hwm_nx;
            mark_deep <= (hwm_nx >= THRESH);
           n_push    <= n_push_nx;
           n_pop     <= n_pop_nx;
          n_ent     <= n_ent_nx;
          n_ext     <= n_ext_nx;
         n_dp_in   <= n_dp_in_nx;
         n_dp_out  <= n_dp_out_nx;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign o_deep = mark_deep;
    assign o_mark = hwm;
    assign o_sp   = sp;

    // Precedence: the deep-mark flag can only rise because the pointer itself
    // has just reached that depth, so the depth must be visible right now.
    always @(posedge clk)
        if (pv && $rose(mark_deep))
            assert (sp >= THRESH);

endmodule

module pingpong_rotbuf (
    input  wire        clk,
    input  wire        step,      // enable / idle when low
    input  wire [15:0] din,
    input  wire [3:0]  amt,
    output reg  [15:0] dout,
    output wire        wr_half,
    output wire        rd_half
);
    // ------------------------------------------------------------------
    // one-cycle barrel rotator (staged shift-by-1/2/4/8 collapses to this)
    // ------------------------------------------------------------------
    wire [31:0] dbl = {din, din};
    wire [15:0] rot = dbl[15:0] >> amt | dbl[31:16] << (16 - amt);

    // ------------------------------------------------------------------
    // ping-pong double buffer: 2 halves of 4 words.
    // address = {half_select, index}
    // ------------------------------------------------------------------
    reg [2:0] waddr;
    reg [2:0] raddr;
    reg [15:0] mem [0:7];
    reg        pv;

   // registered write path: the rotate result and its destination slot are
   // captured on one enabled cycle and retired into the array on the next.
   reg [15:0] wdat_q;
   reg [2:0]  wadr_q;
   reg        wval_q;

   // per-port bank arbiter grant, raised one index ahead of the wrap so the
   // half-select mux is driven by a register instead of a comparator.
   reg        wsw_q;
   reg        rsw_q;

  // ------------------------------------------------------------------
  // scrub/refill channel: a second write channel that walks the half the
  // reader is draining and rewrites every word byte-swapped, sharing the
  // rotator and the single array write port with the main channel.
  // ------------------------------------------------------------------
  reg [1:0]  aidx;    // scrub word pointer inside its half
  reg        abank;   // half the scrubber is currently refilling
  reg        adone;   // pass complete, raised one slot ahead of the wrap
  reg [15:0] sdat_q;  // registered scrub write path, mirrors wdat_q/wadr_q
  reg [2:0]  sadr_q;
  reg        pgnt;    // scrubber owns the shared array port this slot

 // ------------------------------------------------------------------
 // half-handoff ledger: telemetry counters logging the two sides of the
 // bank handoff - one tick when the write channel releases a full half,
 // one tick when the read channel claims it.  Free running, wrap at four
 // bits; they are read back on the data port whenever the scrubber owns
 // the array, and the outstanding-credit term interlocks the reader so it
 // cannot claim a half the writer has not released.
 // ------------------------------------------------------------------
 reg [3:0]  n_rel;
 reg [3:0]  n_acq;

    integer i;
    initial begin
        waddr = 3'b000;   // writer starts in half 0
        raddr = 3'b100;   // reader starts in half 1
        dout  = 16'h0000;
        pv    = 1'b0;
       wdat_q = 16'h0000;
       wadr_q = 3'b000;
       wval_q = 1'b0;
       wsw_q  = 1'b0;
       rsw_q  = 1'b0;
      aidx   = 2'b00;
      abank  = 1'b1;
      adone  = 1'b0;
      sdat_q = 16'h0000;
      sadr_q = 3'b100;
      pgnt   = 1'b0;
     n_rel  = 4'd0;
     n_acq  = 4'd0;
        for (i = 0; i < 8; i = i + 1) mem[i] = 16'h0000;
    end

    assign wr_half = waddr[2];
    assign rd_half = raddr[2];

    // each side flips its own half when its own index field wraps
   // grant is requested one slot early and consumed on the wrap itself
   wire wgrant = (waddr[1:0] == 2'b10);
   wire rgrant = (raddr[1:0] == 2'b10);

  // the scrubber asks for the shared port on the last slot of its pass
  wire arq = (aidx == 2'b11);

 // a released half is sitting in the ledger waiting to be claimed
 wire hs_rdy = (n_rel != n_acq);

    always @(posedge clk) begin
        pv <= 1'b1;
        if (step) begin
          pgnt <= arq && !pgnt;

          if (pgnt) begin
             // scrubber's slot: its word goes into the array and both main
             // channels pause for one beat
             mem[sadr_q] <= sdat_q;
            // the data port is idle this beat: drive the ledger readback
            dout <= {4'h0, n_rel, 4'h0, n_acq};
          end else begin
           // stage 1: capture the rotated word and where it belongs
           wdat_q <= rot;
           wadr_q <= waddr;
           wval_q <= 1'b1;

           // stage 2: retire the word captured on the previous enabled cycle
           if (wval_q) mem[wadr_q] <= wdat_q;

           wsw_q <= wgrant;
           rsw_q <= rgrant;

            dout       <= mem[raddr];

           waddr <= {wsw_q ? ~waddr[2] : waddr[2], waddr[1:0] + 2'b01};
             // the reader may not cross into a half the scrubber has not
            // finished refilling, so its bank flip is qualified by adone
            // and by an outstanding released-half credit in the ledger
            raddr <= {(rsw_q && adone && hs_rdy) ? ~raddr[2] : raddr[2],
                      raddr[1:0] + 2'b01};

             // scrub bookkeeping: stage the next refill word, walk the
             // pointer and follow the reader into the next half
             sdat_q <= {rot[7:0], rot[15:8]};
             sadr_q <= {abank, aidx};
             adone  <= (aidx == 2'b10);
             aidx   <= aidx + 2'b01;
             abank  <= adone ? ~abank : abank;

            // ledger ticks: release is logged one slot ahead of the wrap,
            // the claim is logged on the beat the reader actually crosses
            n_rel <= n_rel + {3'b000, wgrant};
            n_acq <= n_acq + {3'b000, (rsw_q && adone && hs_rdy)};
          end
        end
    end

    // ------------------------------------------------------------------
    // P: whenever the writer migrates up into the high half, the reader
    //     must at that moment be sitting in the low half.
    // ------------------------------------------------------------------
    always @(posedge clk)
        if (pv && $rose(waddr[2]))
            assert (raddr[2] == 1'b0);
endmodule

module csa_accum_parity (
    input  wire       clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_clear,
    input  wire [7:0] i_data,
    output wire [7:0] o_total,
output wire [7:0] o_ref,
output wire [3:0] o_evt_cnt
);
    // accumulator kept in carry-save form: two halves that always sum to the
    // true running total held in the reference register
    reg [7:0] acc_s = 8'h00;   // sum half
    reg [7:0] acc_c = 8'h00;   // carry half (always even by construction)
reg [3:0] total  = 4'h0;   // reference accumulator, low nibble slice
reg [3:0] tot_hi = 4'h0;   // reference accumulator, high nibble slice
    reg        hi_flag = 1'b0; // registered "total has reached the upper half";
                               // precomputed on the adder result so the flush
                               // path next cycle is just a flop-to-mux hop
reg [3:0] evt_cnt = 4'h0;  // distractor: counts enabled cycles with nonzero input
reg [1:0] fill = 2'b00;    // coarse fill level of the open window: bits 6:5 of
                           // the running total, published in the status nibble
                           // so the consumer can pace its reads

    wire [7:0] sum_bits   = acc_s ^ acc_c ^ i_data;
    wire [7:0] maj_bits   = (acc_s & acc_c) | (acc_s & i_data) | (acc_c & i_data);
    wire [7:0] carry_bits = {maj_bits[6:0], 1'b0};
// reference adder is built from two nibble slices so neither carry chain
// spans the whole word; the upper slice is only clocked on cycles where it
// can actually change, which keeps it quiet for small operands
wire [4:0] lo_sum     = {1'b0, total} + {1'b0, i_data[3:0]};
wire       lo_cout    = lo_sum[4];
wire [3:0] hi_sum     = tot_hi + i_data[7:4] + {3'b0, lo_cout};
wire       hi_en      = lo_cout || (i_data[7:4] != 4'h0);
wire [7:0] next_total = {hi_sum, lo_sum[3:0]};

    always @(posedge clk) begin
        if (i_rst) begin
            acc_s <= 8'h00;
            acc_c <= 8'h00;
total  <= 4'h0;
tot_hi <= 4'h0;
            hi_flag <= 1'b0;
evt_cnt <= 4'h0;
fill <= 2'b00;
        end else if (i_ce) begin
evt_cnt <= evt_cnt + {3'b0, (i_data != 8'h00)};
            if (i_clear || hi_flag) begin
                acc_s <= 8'h00;
                acc_c <= 8'h00;
total  <= 4'h0;
tot_hi <= 4'h0;
                hi_flag <= 1'b0;
fill <= 2'b00;
            end else begin
                acc_s <= sum_bits;
                acc_c <= carry_bits;
total   <= next_total[3:0];
if (hi_en)
    tot_hi <= next_total[7:4];
                hi_flag <= next_total[7];
fill <= next_total[6:5];
            end
        end
    end

    assign o_total = acc_s + acc_c;
assign o_ref   = {tot_hi, total};
// status nibble: coarse fill level in the top two bits, low two bits of the
// event count packed underneath it
assign o_evt_cnt = {fill, evt_cnt[1:0]};

    // P: while the unit is actually accumulating, the low bit of the sum half
    // alone already carries the parity of the true total.
    always @(posedge clk)
        if (i_ce && !i_clear)
            assert (acc_s[0] == total[0]);

    // P2: the flush flag was computed from the adder result, so it must still
    // describe the value the carry-save side is currently reporting.
    always @(posedge clk)
        assert (hi_flag == o_total[7]);

    // P3: the fill field is latched off the reference adder result, so it must
    // still match the coarse magnitude the carry-save side is reporting.
    always @(posedge clk)
        assert (fill == o_total[6:5]);
endmodule

module fourphase_occupancy (
    input  wire       clk,
    input  wire       i_ce,          // global enable / idle when low
    input  wire       start,         // master wants a new transaction
    input  wire       dev_ack_ready, // device is ready to raise ack
    output reg        req,
    output reg        ack,
    output reg        busy,
    output reg [2:0]  occ,           // outstanding-transaction occupancy
output reg        armed,
output reg [3:0]  ce_ticks,
output reg [3:0]  start_hist
);
    // four-phase handshake sequencer:
    //   phase 0 : idle        (req=0, ack=0)
    //   phase 1 : req raised  (req=1, ack=0)
    //   phase 2 : ack raised  (req=1, ack=1)
    //   phase 3 : req dropped (req=0, ack=1)   -> ack drops, back to idle
    reg [1:0] phase;
    reg       pv;
reg [2:0] occ_pend;   // issued, not yet acknowledged
reg [3:0] ce_ticks_d;
reg [3:0] start_hist_d;

    initial begin
        phase = 2'd0;
        req   = 1'b0;
        ack   = 1'b0;
        busy  = 1'b0;
        occ   = 3'd0;
        armed = 1'b0;
        pv    = 1'b0;
occ_pend = 3'd0;
ce_ticks   = 4'd0;
ce_ticks_d = 4'd0;
start_hist   = 4'd0;
start_hist_d = 4'd0;
    end

    always @(posedge clk)
        pv <= 1'b1;

always @(posedge clk) begin
    if (i_ce) begin
        ce_ticks_d <= ce_ticks;
        ce_ticks   <= ce_ticks + {3'd0, start} + 4'd1;
    end else begin
        ce_ticks   <= ce_ticks_d;
    end
end

always @(posedge clk) begin
    if (i_ce) begin
        start_hist_d <= start_hist;
        start_hist   <= {start_hist[2:0], start ^ dev_ack_ready};
    end else begin
        start_hist   <= start_hist_d;
    end
end

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                2'd0: begin
                    // request may only be launched from idle
                    if (start) begin
                        req   <= 1'b1;
                        busy  <= 1'b1;      // busy mirrors the phase
occ_pend <= occ_pend + 3'd1;   // counted as pending until the device acks
                        phase <= 2'd1;
                    end
                end
                2'd1: begin
                    // req is held; it may not drop until ack rises
                    if (dev_ack_ready) begin
                        ack   <= 1'b1;
occ      <= occ + occ_pend;    // pending transfer is now accepted
occ_pend <= 3'd0;
                        phase <= 2'd2;
                    end
                end
                2'd2: begin
                    // ack seen -> now req is allowed to drop
                    req   <= 1'b0;
                    phase <= 2'd3;
                end
                2'd3: begin
                    // ack drops, transaction retires
                    ack   <= 1'b0;
                    busy  <= 1'b0;
                    occ   <= occ - 3'd1;
                    armed <= 1'b1;   // sticky: first completed handshake arms
                    phase <= 2'd0;
                end
            endcase
        end
    end

    // Property: once at least one handshake has completed (armed), every time the
    // busy flag rises the occupancy must not exceed two.
    always @(posedge clk)
        if (pv && armed && $rose(busy))
            assert (occ <= 3'd2);
endmodule

module issue_token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire [1:0] i_req,     // dual-issue: 0, 1 or 2 slots want to issue
    output wire [1:0] o_grant,   // slots actually granted this cycle
output reg  [3:0] tokens,    // credits left in the bucket
output reg  [5:0] o_grant_acc // saturating count of issued slots (observability only)
);
    localparam [3:0] BURST  = 4'd8;   // bucket capacity
    localparam [2:0] PERIOD = 3'd5;   // refill timer period

    // thermometer-coded shadow of the bucket occupancy
    reg [7:0] bucket;
    // refill timer
    reg [2:0] tick_cnt;
   // peak-rate peer bucket: second credit counter metering the same traffic
   reg [3:0] tokens_b;
   // shared refill-credit bus: one credit per tick, one destination
   reg       cred_val;
   reg       cred_dst;   // 0 = mean bucket, 1 = peak bucket
// distractor: pipelined record of the last grant width
reg [1:0] last_grant;

    initial begin
        tokens   = 4'd0;
       tokens_b = 4'd0;
        bucket   = 8'h00;
        tick_cnt = 3'd0;
       cred_val = 1'b0;
       cred_dst = 1'b0;
last_grant  = 2'd0;
o_grant_acc = 6'd0;
    end

    wire       tick    = (tick_cnt == PERIOD);
    wire [1:0] req_c   = (i_req == 2'd3) ? 2'd2 : i_req;

    // grants are limited by available credits
   // a slot must be covered by BOTH buckets, so the burst is the tighter one
   wire [1:0] cap_a   = (tokens   >= {2'b00, req_c}) ? req_c : tokens[1:0];
   wire [1:0] cap_b   = (tokens_b >= {2'b00, req_c}) ? req_c : tokens_b[1:0];
   wire [1:0] n_drain = (cap_a < cap_b) ? cap_a : cap_b;

   // One refill credit per timer tick, shared by both buckets.  The capacity
   // check is done here in the arbiter, so the credit that comes back off the
   // bus one cycle later is applied straight to the counter.
   wire       a_full   = (tokens   == BURST);
   wire       b_full   = (tokens_b == BURST);
   wire       cred_new = tick && !(a_full && b_full);
   // round robin between the buckets, skipping one that has no room
   wire       sel_b    = b_full ? 1'b0 : (a_full ? 1'b1 : ~cred_dst);
   wire       do_ref   = cred_val && !cred_dst;
   wire       do_ref_b = cred_val &&  cred_dst;

    wire [7:0] b_ref   = do_ref ? {bucket[6:0], 1'b1} : bucket;
    wire [7:0] b_nxt   = b_ref >> n_drain;
    wire [3:0] t_nxt   = tokens + (do_ref ? 4'd1 : 4'd0) - {2'b00, n_drain};
   wire [3:0] t_b_nxt = tokens_b + (do_ref_b ? 4'd1 : 4'd0) - {2'b00, n_drain};

    assign o_grant = i_ce ? n_drain : 2'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens   <= 4'd0;
           tokens_b <= 4'd0;
            bucket   <= 8'h00;
            tick_cnt <= 3'd0;
           cred_val <= 1'b0;
           cred_dst <= 1'b0;
last_grant  <= 2'd0;
o_grant_acc <= 6'd0;
        end else if (i_ce) begin
            tokens   <= t_nxt;
           tokens_b <= t_b_nxt;
            bucket   <= b_nxt;
            tick_cnt <= tick ? 3'd0 : (tick_cnt + 3'd1);
           cred_val <= cred_new;
           if (cred_new)
               cred_dst <= sel_b;
last_grant  <= n_drain;
o_grant_acc <= (o_grant_acc >= 6'd60) ? 6'd63 : (o_grant_acc + {4'b00, last_grant});
        end
    end

    // P: whenever the credit counter reads empty, the thermometer shadow
    //    of the bucket must be empty as well.
    always @(posedge clk)
        if (tokens == 4'd0)
            assert (bucket == 8'h00);

endmodule

// Serial debug-link pattern probe: detects the fixed 4-bit sync pattern 1101
// arriving MSB-first on i_bit, gated by the probe clock-enable i_ce.
// Match progress is tracked twice: as a binary progress counter (prog) and as
// an independently-updated one-hot shadow (hot). A 4-bit capture window (win)
// records the most recent bits seen.
// The window is assembled from a three-bit live shifter (win_lo) and a
// retired-oldest-bit register (win_hi) that is only loaded once the filler
// count (fill) has run out.
// A match is only declared once the capture window has been primed with four
// genuinely received bits: the match target (goal) starts above the reachable
// progress range and is stepped down to the pattern length, one step per
// probed bit, as the post-reset filler is shifted out of win.
module swd_sync_probe (
    input  wire clk,
    input  wire i_ce,      // probe strobe: low => link idle, all state frozen
    input  wire i_bit,     // serial bit from the debug pin
    output reg  detect     // registered pulse: full pattern just completed
);
    localparam [3:0] PATTERN = 4'b1101;

    reg [2:0] prog;        // match progress, 0..4 (4 == pattern length)
    reg [4:0] hot;         // one-hot shadow of the same progress
reg [2:0] win_lo;      // three newest bits: the live capture shifter
reg       win_hi;      // oldest window bit, retired out of the shifter
reg [1:0] fill;        // reset-filler slots still sitting in the window
reg [3:0] win;         // assembled capture window, MSB = oldest
    reg [3:0] goal;        // progress value that completes a match: 4 once the
                           // window is primed, >4 while win still holds filler

   // ---- match-target retiming -----------------------------------------
   // The filler count is handed to the goal register through four registers
   // so the countdown subtractor and the nprog compare no longer share one
   // path; the target therefore lands four probed bits late.
   reg [1:0] fs1, fs2, fs3, fs4;  // filler count in flight toward goal
   reg       match_en;            // target settled: matcher may consume bits

// the window is only whole once the oldest bit has been retired into win_hi
always @(*) win = {win_hi, win_lo};

    initial begin
        prog   = 3'd0;
        hot    = 5'b00001;
win_lo = 3'b000;
win_hi = 1'b0;
fill   = 2'd3;
       fs1    = 2'd3;
       fs2    = 2'd3;
       fs3    = 2'd3;
       fs4    = 2'd3;
        goal   = 4'd7;
        detect = 1'b0;
    end

    // ---- next progress from the binary counter -------------------------
    reg [2:0] nprog;
    always @(*) begin
        case (prog)
            3'd0:    nprog = i_bit ? 3'd1 : 3'd0;              // want 1
            3'd1:    nprog = i_bit ? 3'd2 : 3'd0;              // want 1
            3'd2:    nprog = i_bit ? 3'd2 : 3'd3;              // want 0
            3'd3:    nprog = i_bit ? 3'd4 : 3'd0;              // want 1
            3'd4:    nprog = i_bit ? 3'd2 : 3'd0;              // overlap "1"
            default: nprog = prog;
        endcase
    end

    // ---- next progress from the one-hot shadow (own state only) --------
    reg [4:0] nhot;
    always @(*) begin
        case (hot)
            5'b00001: nhot = i_bit ? 5'b00010 : 5'b00001;
            5'b00010: nhot = i_bit ? 5'b00100 : 5'b00001;
            5'b00100: nhot = i_bit ? 5'b00100 : 5'b01000;
            5'b01000: nhot = i_bit ? 5'b10000 : 5'b00001;
            5'b10000: nhot = i_bit ? 5'b00100 : 5'b00001;
            default:  nhot = 5'b00001;
        endcase
    end

// ---- window priming: one filler slot retires per probed bit --------
reg [1:0] nfill;
always @(*) nfill = (fill == 2'd0) ? 2'd0 : fill - 2'd1;

   // the matcher stays idle until the retimed target has reached goal
   always @(*) match_en = (goal == 4'd4);

    always @(posedge clk) begin
        if (i_ce) begin
           if (match_en) begin
               prog <= nprog;
               hot  <= nhot;
           end
win_lo <= {win_lo[1:0], i_bit};
if (fill == 2'd0)
    win_hi <= win_lo[2];        // window full: retire the oldest live bit
fill   <= nfill;
           fs1    <= nfill;
           fs2    <= fs1;
           fs3    <= fs2;
           fs4    <= fs3;
           goal   <= 4'd4 + {2'b00, fs4};
            detect <= (nprog == goal);
        end
    end

    // ---- property: two universal relations, globally --------------------
    always @(posedge clk) begin
        assert (detect == hot[4]);
        if (prog == 3'd4)
            assert (win == PATTERN);
    end
endmodule

// Tile-render pixel pipeline pacing: a /5 phase counter feeding a /4 row
// counter, plus an accumulator of paced cycles within one tile (20 steps)
// and a high-water mark of that accumulator.
module tilepipe_div (
    input  wire i_clk,
    input  wire i_ce,        // pipeline advance / idle when low
    output wire o_tile_en,   // divided-enable pulse: fires when the chain wraps
    output wire [4:0] o_peak
);
    // ---- phase counter (divide by 5) ----
    reg [2:0] phase;
    initial   phase = 3'd0;

    // ---- row counter (divide by 4 of the phase wrap) ----
    reg [1:0] row;
    initial   row = 2'd0;

    // ---- accumulated paced cycles inside the current tile ----
    reg [4:0] total;
    initial   total = 5'd0;

   // ---- paced cycles already retired from the tile's first half ----
   reg [4:0] retired;
   initial   retired = 5'd0;

  // ---- staged half-tile fold ----
  // folding the low accumulator into the retired count no longer fits in
  // the paced cycle that closes row 1: the partial sum is parked here and
  // written back to the retired count on the next paced step
  reg [4:0] fold_q;
  initial   fold_q = 5'd0;
  reg       fold_pend;
  initial   fold_pend = 1'b0;

    // ---- high-water mark of the accumulator (monotone) ----
    reg [4:0] peak;
    initial   peak = 5'd0;

  // ---- staged tile-sum ----
  // the accumulator add and the high-water compare no longer fit in one
  // paced cycle, so the sum is registered here and offered to the
  // comparator on the following paced cycle
  reg [4:0] sum_q;
  initial   sum_q = 5'd0;

    reg pv;
    initial pv = 1'b0;

    wire ph_wrap  = (phase == 3'd4);
    wire row_wrap = ph_wrap && (row == 2'd3);

   // the tile is flushed in halves: when row 1 finishes, the low
   // accumulator is folded into the retired count and restarted, so the
   // low accumulator only ever spans one half-tile
   wire half_done = ph_wrap && (row == 2'd1);

  // a fold that is still in flight is already retired as far as the tile
  // sum is concerned, so the accumulator reads it in place of the register
  wire [4:0] eff_retired = fold_pend ? fold_q : retired;

   // paced cycles in this tile after the current step, across both halves;
   // cleared only by the divided-enable pulse, never by its own value
  wire [4:0] nxt_sum = row_wrap ? 5'd0 : (eff_retired + total + 5'd1);

    always @(posedge i_clk) begin
        pv <= 1'b1;
        if (i_ce) begin
            phase <= ph_wrap ? 3'd0 : (phase + 3'd1);
            if (ph_wrap)
                row <= row_wrap ? 2'd0 : (row + 2'd1);
           if (row_wrap) begin
               total   <= 5'd0;
              retired   <= 5'd0;
              fold_q    <= 5'd0;
              fold_pend <= 1'b0;
           end else if (half_done) begin
               total   <= 5'd0;
              fold_q    <= retired + total + 5'd1;
              fold_pend <= 1'b1;
           end else begin
               total   <= total + 5'd1;
              if (fold_pend) begin
                  retired   <= fold_q;
                  fold_pend <= 1'b0;
              end
           end
          sum_q <= nxt_sum;
          if (sum_q > peak)
              peak <= sum_q;
        end
    end

    assign o_tile_en = i_ce && row_wrap;
    assign o_peak    = peak;

    // P: the high-water mark of the tile accumulator never climbs past 19,
    // even though the register is 5 bits wide (would allow 31): once it has
    // reached 19 it must never change again.
    always @(posedge i_clk)
        if (pv && ($past(peak) == 5'd19))
            assert ($stable(peak));
endmodule

module elastic_two_entry (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_push,
    input  wire       i_pop,
    input  wire [7:0] i_data,
    output wire       o_valid,
    output wire       o_full,
    output wire [7:0] o_data,
    output wire [2:0] o_count
);

    // ---- two-entry elastic buffer -------------------------------------
    // one valid flag per slot, plus head/tail slot selectors.
    reg        v0, v1;      // slot occupancy flags
    reg        head, tail;  // which slot is read / written next
    reg [7:0]  d0, d1;      // slot payloads
    reg [2:0]  count;       // redundant occupancy counter
   reg [2:0]  credits;     // free slots left, advertised upstream
   reg [2:0]  limit;       // programmable depth limit: 1 or 2 entries
   reg        full_r;      // registered flow-control flag toward upstream

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial head  = 1'b0;
    initial tail  = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;
   initial credits = 3'd2;
   initial limit  = 3'd2;
   initial full_r = 1'b0;

// status: valid/data come from the FLAGS, full comes from the credit count
   // full is registered so the upstream ready path is not combinational;
   // it compares the occupancy against the programmed depth limit.
   assign o_full  = full_r;
    assign o_valid = v0 || v1;
    assign o_data  = head ? d1 : d0;
    assign o_count = count;

    wire do_push = i_push && !o_full;
    wire do_pop  = i_pop  &&  o_valid;

   // a pop strobe on an empty buffer moves no data, so upstream reuses it
   // as the depth-limit write: i_data[0] picks a one or two entry buffer.
   wire       lim_we   = i_pop && !o_valid;
   wire [2:0] limit_n  = lim_we ? (i_data[0] ? 3'd2 : 3'd1) : limit;

   // occupancy after this cycle, used to pre-compute the registered full flag
   wire [2:0] count_n  = count + (do_push ? 3'd1 : 3'd0)
                               - (do_pop  ? 3'd1 : 3'd0);

    // idle condition: i_push == 0 && i_pop == 0 leaves all state alone
    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            head  <= 1'b0;
            tail  <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
credits <= 3'd2;
           limit  <= 3'd2;
           full_r <= 1'b0;
        end else begin
            if (do_push) begin
                if (tail == 1'b0) begin
                    v0 <= 1'b1;
                    d0 <= i_data;
                end else begin
                    v1 <= 1'b1;
                    d1 <= i_data;
                end
                tail <= ~tail;
            end

            if (do_pop) begin
                if (head == 1'b0)
                    v0 <= 1'b0;
                else
                    v1 <= 1'b0;
                head <= ~head;
            end

            count <= count + (do_push ? 3'd1 : 3'd0)
                            - (do_pop  ? 3'd1 : 3'd0);

           credits <= credits - (do_push ? 3'd1 : 3'd0)
                             + (do_pop  ? 3'd1 : 3'd0);

           limit  <= limit_n;
           full_r <= (count_n >= limit_n);
        end
    end

    // ---- property: while the buffer holds anything, the occupancy
    //      counter never exceeds the two-entry depth (the register is
    //      three bits wide, so 3..7 are representable).
    always @(posedge i_clk)
        if (o_valid)
            assert (count <= 3'd2);

   // ---- property: a lone resident word sits between the two pointers
   //      (head and tail must differ) and leaves exactly one credit.
   always @(posedge i_clk)
       if (count == 3'd1)
           assert ((head != tail) && (credits == 3'd1));

endmodule

module boot_chunk_loader (
    input  wire i_clk,
    input  wire i_ce,      // idle when low: no state changes at all
    input  wire i_start,   // accept a fresh load request
    output wire o_expired,
    output wire o_done,
    output wire [7:0] o_total
);
    // A chunk loader that accumulates 3 bytes of payload per accepted step.
    // The accumulator is kept in two carry-save halves (acc_a, acc_b) whose
    // sum is the true byte total; `total` is the redundant true running sum.
localparam [3:0] TMAX  = 4'd9;   // countdown granted: 8 steps + 1 commit-stage cycle
    localparam [7:0] LIMIT = 8'd24;  // bytes that constitute completion
   localparam [3:0] TBMAX = 4'd6;   // channel B: shorter descriptor fetch
   localparam [3:0] TCMAX = 4'd5;   // channel C: streamed payload bytes

    reg [7:0] acc_a;
    reg [7:0] acc_b;
    reg [7:0] total;
    reg [3:0] timer;
   reg [3:0] timer_b;  // channel B countdown
   reg [3:0] aux;      // channel B byte accumulator
   reg       arb;      // round-robin priority for the shared commit register
reg       st_v;    // a step is sitting in the commit register
reg [3:0] st_lo;   // its low carry-save half-increment
reg [3:0] st_hi;   // its high carry-save half-increment
   reg       st_ch;   // which channel owns the in-flight step
   reg [3:0] timer_c;  // channel C countdown
   reg       ct_v;     // channel C step waiting for the shared accumulator adder
   reg [3:0] ct_lo;    // its byte increment
   reg       parb;     // accumulator-port fairness: C was denied last cycle
    reg       pv;

    initial acc_a = 8'd0;
    initial acc_b = 8'd0;
    initial total = 8'd0;
    initial timer = TMAX;
   initial timer_b = TBMAX;
   initial aux = 4'd0;
   initial arb = 1'b0;
initial st_v  = 1'b0;
initial st_lo = 4'd0;
initial st_hi = 4'd0;
   initial st_ch = 1'b0;
   initial timer_c = TCMAX;
   initial ct_v    = 1'b0;
   initial ct_lo   = 4'd0;
   initial parb    = 1'b0;
    initial pv    = 1'b0;

    wire [7:0] csum    = acc_a + acc_b;   // halves recombined
    wire       expired = (timer == 4'd0);
   wire       req_a   = (timer   != 4'd0);
   wire       req_b   = (timer_b != 4'd0);
   wire       acc_req_a = st_v && !st_ch;                // A's step needs the accumulator adder
   wire       acc_gnt_c = ct_v && (!acc_req_a || parb);  // C pre-empts only after a denial
   wire       acc_gnt_a = acc_req_a && !acc_gnt_c;
   wire       slot_busy = acc_req_a && !acc_gnt_a;       // A's step stays in the commit register
   wire       gnt_b   = req_b && !slot_busy && (arb || !req_a);  // B takes the slot on its turn
   wire       gnt_a   = req_a && !slot_busy && !gnt_b;

    assign o_expired = expired;
    assign o_done    = (csum >= LIMIT);
   assign o_total   = total + {4'd0, aux};   // bytes from both channels

    always @(posedge i_clk)
        pv <= 1'b1;

    always @(posedge i_clk) begin
        if (i_ce) begin
            if (i_start) begin
                acc_a <= 8'd0;
                acc_b <= 8'd0;
                total <= 8'd0;
                timer <= TMAX;
               timer_b <= TBMAX;
               aux   <= 4'd0;
               arb   <= 1'b0;
               timer_c <= TCMAX;
               ct_v    <= 1'b0;
               ct_lo   <= 4'd0;
               parb    <= 1'b0;
st_v  <= 1'b0;          // flush whatever was in flight
st_lo <= 4'd0;
st_hi <= 4'd0;
               st_ch <= 1'b0;
end else begin
   // stage 1: arbitrate the single commit register between the two channels
   if (slot_busy) begin
       st_v  <= st_v;          // C took the adder this cycle; the step has to wait
       st_ch <= st_ch;
       st_lo <= st_lo;
       st_hi <= st_hi;
   end else if (gnt_a) begin
       st_v  <= 1'b1;
       st_ch <= 1'b0;
       st_lo <= 4'd1;
       st_hi <= 4'd2;
       timer <= timer - 4'd1;
       arb   <= 1'b1;
   end else if (gnt_b) begin
       st_v  <= 1'b1;
       st_ch <= 1'b1;
       st_lo <= 4'd1;
       st_hi <= 4'd0;          // B carries a single byte per step
       timer_b <= timer_b - 4'd1;
       arb   <= 1'b0;
   end else begin
       st_v  <= 1'b0;
       st_ch <= 1'b0;
       st_lo <= 4'd0;
       st_hi <= 4'd0;
   end
   // stage 2: the shared accumulator adder commits whichever channel won it
   if (acc_gnt_a) begin
       acc_a <= acc_a + {4'd0, st_lo};                  // low carry-save half
       acc_b <= acc_b + {4'd0, st_hi};                  // high carry-save half
       total <= total + {4'd0, st_lo} + {4'd0, st_hi};  // true total
   end else if (acc_gnt_c) begin
       acc_a <= acc_a + {4'd0, ct_lo};                  // C's byte joins the low half
       total <= total + {4'd0, ct_lo};
   end
   if (st_v && st_ch) begin
       aux   <= aux + st_lo;
   end
   // channel C: one streamed byte outstanding at a time
   if (ct_v) begin
       if (acc_gnt_c) begin
           ct_v  <= 1'b0;
           ct_lo <= 4'd0;
       end
   end else if (timer_c != 4'd0) begin
       ct_v    <= 1'b1;
       ct_lo   <= 4'd1;
       timer_c <= timer_c - 4'd1;
   end
   parb <= ct_v && acc_req_a && !parb;   // remember a denied C request
            end
        end
    end

    // Bounded response, safety form: the countdown must never expire while the
    // load request is still outstanding.  Edge form: the cycle `expired` rises,
    // the recombined accumulator must already show a completed transfer.
    always @(posedge i_clk)
        if (pv)
            assert (!$rose(expired) || (acc_a + acc_b >= LIMIT));
endmodule

module sorted_pair (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire ins,
    input wire rem,
    input wire [7:0] val,
    output reg [1:0] count
);
    reg [7:0] e0, e1, max_shadow;
    initial begin count = 2'd0; e0 = 8'd0; e1 = 8'd0; max_shadow = 8'd0; end

    wire do_ins = i_ce && ins && !rem && (count != 2'd2);
    wire do_rem = i_ce && rem && !ins && (count != 2'd0);

    always @(posedge clk) begin
        if (rst) begin
            count <= 2'd0; e0 <= 8'd0; e1 <= 8'd0; max_shadow <= 8'd0;
        end else if (do_ins) begin
            count <= count + 2'd1;
            if (count == 2'd0) begin
                e0 <= val;  max_shadow <= val;
            end else if (val >= e0) begin
                e1 <= val;  max_shadow <= val;
            end else begin
                e0 <= val;  e1 <= e0;  max_shadow <= e0;
            end
        end else if (do_rem) begin
            count <= count - 2'd1;
            if (count == 2'd2) e0 <= e1;
        end
    end

    always @(posedge clk)
        if (count == 2'd1)
            assert (max_shadow == e0);
endmodule

module gcd_ctrl (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire       ack,
    input  wire [3:0] x,
    input  wire [3:0] y,
    output reg  [3:0] a,
    output reg  [3:0] b,
    output reg        idle,
    output reg        calc,
    output reg        done
);
    initial begin a = 4'd0; b = 4'd0; idle = 1'b1; calc = 1'b0; done = 1'b0; end

    wire finish = (b == 4'd0);

    always @(posedge clk) begin
        if (ce) begin
            idle <= (idle && !start) || (done && ack);
            calc <= (idle && start)  || (calc && !finish);
            done <= (calc && finish) || (done && !ack);

            if (idle && start) begin
                a <= x;
                b <= y;
            end else if (calc && !finish) begin
                if (a >= b) begin
                    a <= a - b;
                end else begin
                    a <= b;
                    b <= a;
                end
            end
        end
    end

    always @(posedge clk)
        if (done)
            assert (!calc);
endmodule

module char_occurrence_scan (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire ch_match,
    output reg [3:0] nchars,
    output reg [3:0] nmatch,
    output wire done
);
    initial nchars = 4'd0;
    initial nmatch = 4'd0;

    // scan a fixed 8-character string, counting occurrences of the target char
    assign done = (nchars == 4'd8);

    always @(posedge clk) begin
        if (rst) begin
            nchars <= 4'd0;
            nmatch <= 4'd0;
        end else if (ce && !done) begin
            nchars <= nchars + 4'd1;
            if (ch_match)
                nmatch <= nmatch + 4'd1;
        end
    end

    // P: if every character matched, the whole string must have been consumed
    always @(posedge clk)
        if (nmatch == 4'd8)
            assert (nchars == 4'd8);
endmodule

module ringq (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] dout,
    output wire full,
    output wire empty
);
    reg [1:0] wptr = 2'd0;
    reg [1:0] rptr = 2'd0;
    reg [2:0] count = 3'd0;
    reg [7:0] mem [0:3];

    assign full  = (count == 3'd4);
    assign empty = (count == 3'd0);

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
        end else begin
            if (do_push) begin
                mem[wptr] <= din;
                wptr <= wptr + 2'd1;
            end
            if (do_pop)
                rptr <= rptr + 2'd1;
            if (do_push && !do_pop)
                count <= count + 3'd1;
            else if (do_pop && !do_push)
                count <= count - 3'd1;
        end
    end

    assign dout = mem[rptr];

    always @(posedge clk)
        if (count == 3'd0) assert (wptr == rptr);
endmodule

module stack_xor (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [3:0] data,
    output reg [2:0] sp,
    output reg [3:0] xor_acc
);
    reg [3:0] m0, m1, m2, m3;
    initial begin sp = 0; xor_acc = 0; m0 = 0; m1 = 0; m2 = 0; m3 = 0; end

    wire do_push = push && !pop && (sp != 3'd4);
    wire do_pop  = pop  && !push && (sp != 3'd0);
    wire [3:0] top = (sp == 3'd1) ? m0 : (sp == 3'd2) ? m1 : (sp == 3'd3) ? m2 : m3;

    always @(posedge clk) begin
        if (rst) begin
            sp <= 3'd0;
            xor_acc <= 4'd0;
        end else if (do_push) begin
            case (sp)
                3'd0:    m0 <= data;
                3'd1:    m1 <= data;
                3'd2:    m2 <= data;
                default: m3 <= data;
            endcase
            sp <= sp + 3'd1;
            xor_acc <= xor_acc ^ data;
        end else if (do_pop) begin
            sp <= sp - 3'd1;
            xor_acc <= xor_acc ^ top;
        end
    end

    always @(posedge clk)
        if (sp == 3'd0)
            assert (xor_acc == 4'd0);
endmodule

module ringq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire push,
    input wire pop
);
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg       empty_r, full_r;
    initial begin wptr = 2'd0; rptr = 2'd0; count = 3'd0; empty_r = 1'b1; full_r = 1'b0; end

    wire do_push = i_ce && push && !full_r;
    wire do_pop  = i_ce && pop  && !empty_r;
    wire [1:0] nw = wptr + do_push;
    wire [1:0] nr = rptr + do_pop;

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 2'd0; rptr <= 2'd0; count <= 3'd0;
            empty_r <= 1'b1; full_r <= 1'b0;
        end else begin
            wptr <= nw;
            rptr <= nr;
            empty_r <= (nw == nr) && (do_pop  || (empty_r && !do_push));
            full_r  <= (nw == nr) && (do_push || (full_r  && !do_pop));
            count <= count + do_push - do_pop;
        end
    end

    always @(posedge clk)
        if (empty_r)
            assert (!full_r);
endmodule

module char_tally (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire [7:0] i_char,
    input wire [7:0] i_target,
    output wire o_all_hits,
    output wire o_all_misses
);
    reg [3:0] total, hits, misses;
    initial total  = 4'd0;
    initial hits   = 4'd0;
    initial misses = 4'd0;

    wire match = (i_char == i_target);

    always @(posedge clk)
        if (rst) begin
            total  <= 4'd0;
            hits   <= 4'd0;
            misses <= 4'd0;
        end else if (i_ce && (total != 4'hf)) begin
            total <= total + 4'd1;
            if (match) hits   <= hits   + 4'd1;
            else       misses <= misses + 4'd1;
        end

    assign o_all_hits   = (total != 4'd0) && (hits   == total);
    assign o_all_misses = (total != 4'd0) && (misses == total);

    always @(*)
        if (o_all_hits) assert (!o_all_misses);
endmodule

module stack_ptr_guard (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] dout,
    output reg [2:0] sp,
    output reg empty,
    output reg full
);
    reg [7:0] mem [0:3];

    initial sp    = 3'd0;
    initial empty = 1'b1;
    initial full  = 1'b0;

    assign dout = empty ? 8'h00 : mem[sp - 3'd1];

    always @(posedge clk) begin
        if (rst) begin
            sp    <= 3'd0;
            empty <= 1'b1;
            full  <= 1'b0;
        end else if (push && !pop && !full) begin
            mem[sp] <= din;
            sp      <= sp + 3'd1;
            empty   <= 1'b0;
            full    <= (sp == 3'd3);
        end else if (pop && !push && !empty) begin
            sp    <= sp - 3'd1;
            full  <= 1'b0;
            empty <= (sp == 3'd1);
        end
    end

    always @(posedge clk)
        if (!full) assert (sp <= 3'd4);
endmodule

module qring (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_push,
    input  wire       i_pop,
    output wire       o_full,
    output wire       o_empty
);
    reg [1:0] wptr;
    reg [1:0] rptr;
    reg [2:0] count;

    initial wptr  = 2'd0;
    initial rptr  = 2'd0;
    initial count = 3'd0;

    assign o_full  = (count == 3'd4);
    assign o_empty = (count == 3'd0);

    wire do_push = i_push && !o_full;
    wire do_pop  = i_pop  && !o_empty;

    always @(posedge clk)
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
        end else begin
            if (do_push) wptr <= wptr + 2'd1;
            if (do_pop)  rptr <= rptr + 2'd1;
            if (do_push && !do_pop) count <= count + 3'd1;
            else if (do_pop && !do_push) count <= count - 3'd1;
        end

    always @(*)
        if (count == 3'd0)
            assert (wptr == rptr);
endmodule

module strcount_pipe (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire flush,
    input wire [7:0] ch,
    output wire [5:0] o_cnt
);
    parameter [7:0] TARGET = 8'h61;

    reg [5:0] total = 6'd0;   // characters accepted
    reg [5:0] cnt   = 6'd0;   // committed occurrences of TARGET
    reg       st_valid = 1'b0; // staged character present
    reg       st_match = 1'b0; // staged character equals TARGET

    wire full   = (total == 6'd63);
    wire accept = ce && !full;

    always @(posedge clk)
        if (rst) begin
            total    <= 6'd0;
            cnt      <= 6'd0;
            st_valid <= 1'b0;
            st_match <= 1'b0;
        end else if (accept) begin
            total    <= total + 6'd1;
            st_valid <= 1'b1;
            st_match <= (ch == TARGET);
            if (st_valid && st_match)
                cnt <= cnt + 6'd1;
        end else if (flush && st_valid) begin
            st_valid <= 1'b0;
            if (st_match)
                cnt <= cnt + 6'd1;
        end

    assign o_cnt = cnt;

    always @(*)
        if (!st_valid)
            assert (cnt <= total);
endmodule

module stack_occupancy (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    output reg [2:0] sp,
    output reg [2:0] items,
    output reg top_valid
);
    initial sp = 3'd0;
    initial items = 3'd0;
    initial top_valid = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            sp        <= 3'd0;
            items     <= 3'd0;
            top_valid <= 1'b0;
        end else if (push && sp != 3'd4) begin
            sp        <= sp + 3'd1;
            items     <= items + 3'd1;
            top_valid <= 1'b1;
        end else if (pop && sp != 3'd0) begin
            sp        <= sp - 3'd1;
            items     <= items - 3'd1;
            top_valid <= (sp != 3'd1);
        end
    end

    // P: an empty stack (per the occupancy counter) must not advertise a valid top
    always @(posedge clk)
        if (items == 3'd0)
            assert (top_valid == 1'b0);
endmodule

module uart_tx (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire start,
    input wire [7:0] data,
    output reg tx
);
    localparam IDLE = 2'd0, ST = 2'd1, DAT = 2'd2, STP = 2'd3;
    reg [1:0] phase;
    reg [2:0] bit_cnt;
    reg [7:0] sh;
    initial begin phase = IDLE; bit_cnt = 3'd0; sh = 8'h00; tx = 1'b1; end

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE; bit_cnt <= 3'd0; sh <= 8'h00; tx <= 1'b1;
        end else if (ce) begin
            case (phase)
                IDLE: if (start) begin
                          phase <= ST; sh <= data; tx <= 1'b0; bit_cnt <= 3'd0;
                      end
                ST:   begin
                          phase <= DAT; tx <= sh[0]; sh <= {1'b0, sh[7:1]};
                          bit_cnt <= 3'd0;
                      end
                DAT:  if (bit_cnt == 3'd7) begin
                          phase <= STP; tx <= 1'b1; bit_cnt <= 3'd0;
                      end else begin
                          bit_cnt <= bit_cnt + 3'd1; tx <= sh[0];
                          sh <= {1'b0, sh[7:1]};
                      end
                STP:  begin phase <= IDLE; tx <= 1'b1; end
            endcase
        end
    end

    always @(posedge clk)
        if (phase == IDLE)
            assert (bit_cnt == 3'd0);
endmodule

module stack_occupancy (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [7:0] data,
    output wire [7:0] o_top,
    output wire empty,
    output wire full
);
    parameter DEPTH = 8;
    reg [3:0] sp   = 4'd0;   // occupancy / stack pointer
    reg [3:0] free = 4'd8;   // mirrored free-slot count
    reg [7:0] mem [0:7];
    integer i;
    initial for (i = 0; i < 8; i = i + 1) mem[i] = 8'h00;

    assign empty = (sp == 4'd0);
    assign full  = (sp == DEPTH[3:0]);

    wire do_push = push && !pop && !full;
    wire do_pop  = pop  && !push && !empty;

    always @(posedge clk)
        if (rst) begin
            sp   <= 4'd0;
            free <= 4'd8;
        end else if (do_push) begin
            sp   <= sp + 4'd1;
            free <= free - 4'd1;
        end else if (do_pop) begin
            sp   <= sp - 4'd1;
            free <= free + 4'd1;
        end

    always @(posedge clk)
        if (!rst && do_push) mem[sp[2:0]] <= data;

    assign o_top = empty ? 8'h00 : mem[sp[2:0] - 3'd1];

    always @(*)
        if (!empty) assert (free <= 4'd7);
endmodule

module intersection_phase_pair (
    input wire clk,
    input wire rst,
    input wire ce,
    output reg [2:0] a_ph,
    output reg [2:0] b_ph,
    output reg [2:0] timer
);
    // phase 0 = GREEN, 1 = YELLOW, 2 = ALL_RED, 3..5 = red while the other road runs
    localparam [2:0] LAST = 3'd5;
    localparam [2:0] DUR  = 3'd4;

    initial a_ph  = 3'd0;
    initial b_ph  = 3'd3;
    initial timer = DUR;

    always @(posedge clk) begin
        if (rst) begin
            a_ph  <= 3'd0;
            b_ph  <= 3'd3;
            timer <= DUR;
        end else if (ce) begin
            if (timer == 3'd0) begin
                a_ph  <= (a_ph == LAST) ? 3'd0 : a_ph + 3'd1;
                b_ph  <= (b_ph == LAST) ? 3'd0 : b_ph + 3'd1;
                timer <= DUR;
            end else begin
                timer <= timer - 3'd1;
            end
        end
    end

    // P: when road A holds its green phase, road B must not also be in its green phase
    always @(posedge clk)
        if (a_ph == 3'd0) assert (b_ph != 3'd0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module wdog_kick (
    input wire clk,
    input wire i_ce,
    input wire kick,
    input wire ack,
    output wire o_reset
);
    reg [3:0] cnt;
    reg zf, armed, fault;
    initial cnt   = 4'd0;
    initial zf    = 1'b1;
    initial armed = 1'b0;
    initial fault = 1'b0;

    always @(posedge clk) if (i_ce) begin
        if (ack) begin
            fault <= 1'b0;
            armed <= 1'b0;
            cnt   <= 4'd0;
            zf    <= 1'b1;
        end else if (kick && !fault) begin
            armed <= 1'b1;
            cnt   <= 4'd8;
            zf    <= 1'b0;
        end else if (armed) begin
            if (zf) fault <= 1'b1;            // expiry seen through the flag
            if (cnt == 4'd0) armed <= 1'b0;   // disarm seen through the count
            else begin
                cnt <= cnt - 4'd1;
                zf  <= (cnt == 4'd1);
            end
        end
    end

    assign o_reset = fault;

    always @(*)
        if (fault) assert (!armed);
endmodule

module thermo_window (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire warmer,
    output reg heat
);
    localparam [3:0] T_LOW  = 4'd4;
    localparam [3:0] T_HIGH = 4'd12;

    reg [3:0] temp;
    reg [1:0] win, heat_cycles, cool_cycles;

    initial begin
        temp = 4'd8; heat = 1'b0;
        win = 2'd0; heat_cycles = 2'd0; cool_cycles = 2'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            temp <= 4'd8; heat <= 1'b0;
            win <= 2'd0; heat_cycles <= 2'd0; cool_cycles <= 2'd0;
        end else if (ce) begin
            win <= win + 2'd1;
            if (heat) heat_cycles <= heat_cycles + 2'd1;
            else      cool_cycles <= cool_cycles + 2'd1;
            temp <= warmer ? ((temp == 4'd15) ? temp : temp + 4'd1)
                           : ((temp == 4'd0)  ? temp : temp - 4'd1);
            if      (temp <= T_LOW)  heat <= 1'b1;
            else if (temp >= T_HIGH) heat <= 1'b0;
        end
    end

    always @(posedge clk)
        if (cool_cycles == 2'd0)
            assert (heat_cycles == win);
endmodule

module strscan (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] ch,
    input wire [7:0] target,
    output wire done,
    output wire [3:0] hits
);
    parameter LEN = 8;

    reg [3:0] remaining;
    reg [3:0] consumed;
    reg [3:0] match_count;

    initial remaining   = LEN;
    initial consumed    = 0;
    initial match_count = 0;

    always @(posedge clk)
        if (rst) begin
            remaining   <= LEN;
            consumed    <= 0;
            match_count <= 0;
        end else if (ce && (remaining != 4'd0)) begin
            remaining <= remaining - 4'd1;
            consumed  <= consumed  + 4'd1;
            if (ch == target)
                match_count <= match_count + 4'd1;
        end

    assign done = (remaining == 4'd0);
    assign hits = match_count;

    // P: once the whole string has been scanned, every character was consumed
    always @(*)
        if (remaining == 4'd0)
            assert (consumed == LEN);
endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] rd_data,
    output reg  [3:0] wr_addr,
    output reg  [3:0] remaining,
    output reg  [7:0] wr_data,
    output wire       done
);
    localparam [3:0] TOTAL = 4'd8;

    initial wr_addr   = 4'd0;
    initial remaining = TOTAL;
    initial wr_data   = 8'h00;

    assign done = (remaining == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            wr_addr   <= 4'd0;
            remaining <= TOTAL;
            wr_data   <= 8'h00;
        end else if (ce && remaining != 4'd0) begin
            wr_addr   <= wr_addr + 4'd1;
            remaining <= remaining - 4'd1;
            wr_data   <= rd_data;
        end
    end

    // P: while the block copy is still in flight, the write pointer must stay
    // inside the destination block (0..7).
    always @(posedge clk)
        if (!done)
            assert (wr_addr <= 4'd7);
endmodule

module ring_occ (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    output reg  [2:0] count,
    output reg  [3:0] occ
);
    reg [1:0] wptr, rptr;
    initial begin wptr = 2'd0; rptr = 2'd0; count = 3'd0; occ = 4'b0000; end

    wire do_push = push && (count != 3'd4);
    wire do_pop  = pop  && (count != 3'd0);

    wire [3:0] set_bit = do_push ? (4'b0001 << wptr) : 4'b0000;
    wire [3:0] clr_bit = do_pop  ? (4'b0001 << rptr) : 4'b0000;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
            occ   <= 4'b0000;
        end else begin
            if (do_push) wptr <= wptr + 2'd1;
            if (do_pop)  rptr <= rptr + 2'd1;
            occ <= (occ | set_bit) & ~clr_bit;
            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase
        end
    end

    always @(posedge clk)
        if (count == 3'd1)
            assert (occ == 4'b0001 || occ == 4'b0010 ||
                    occ == 4'b0100 || occ == 4'b1000);
endmodule

module rot_shadow (
    input wire clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_load,
    input wire [15:0] i_data,
    output wire [15:0] o_word,
    output wire [15:0] o_shadow
);
    reg [15:0] word   = 16'h0000;
    reg [15:0] shadow = 16'h0000;
    reg [3:0]  amt    = 4'd0;

    always @(posedge clk)
        if (i_rst) begin
            word   <= 16'h0000;
            shadow <= 16'h0000;
            amt    <= 4'd0;
        end else if (i_ce) begin
            if (i_load) begin
                word   <= i_data;
                shadow <= i_data;
                amt    <= 4'd0;
            end else begin
                shadow <= { shadow[14:0], shadow[15] };
                amt    <= amt + 4'd1;
            end
        end

    assign o_word   = word;
    assign o_shadow = shadow;

    always @(*)
        if (amt == 4'd0)
            assert (shadow == word);
endmodule

module lfsr_capture (
    input wire clk,
    input wire rst,
    input wire ce,
    output reg [7:0] out,
    output reg valid
);
    reg [7:0] s = 8'h01;
    wire fb = s[7] ^ s[5] ^ s[4] ^ s[3];

    initial out   = 8'h00;
    initial valid = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            s     <= 8'h01;
            out   <= 8'h00;
            valid <= 1'b0;
        end else if (ce) begin
            s     <= {s[6:0], fb};
            out   <= s;
            valid <= 1'b1;
        end
    end

    always @(posedge clk)
        if (valid) assert (out != 8'h00);
endmodule

module elevator_ctrl (
    input wire clk,
    input wire rst,
    input wire step,
    output reg [1:0] floor,
    output reg dir
);
    // one-hot shadow of the cab position, shifted in lockstep with floor
    reg [3:0] pos;
    initial begin floor = 2'd0; dir = 1'b1; pos = 4'b0001; end

    wire go_up   = step &&  dir && (floor != 2'd3);
    wire go_down = step && !dir && (floor != 2'd0);

    always @(posedge clk) begin
        if (rst) begin
            floor <= 2'd0;
            dir   <= 1'b1;
            pos   <= 4'b0001;
        end else begin
            if (go_up) begin
                floor <= floor + 2'd1;
                pos   <= pos << 1;
            end else if (go_down) begin
                floor <= floor - 2'd1;
                pos   <= pos >> 1;
            end
            if (step) begin
                if (dir && (floor == 2'd3))       dir <= 1'b0;
                else if (!dir && (floor == 2'd0)) dir <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (floor == 2'd0)
            assert (pos == 4'b0001);
endmodule

module debounce_stability (
    input wire clk,
    input wire rst,
    input wire sample,
    input wire raw,
    output reg out
);
    reg [2:0] cnt;   // consecutive samples disagreeing with out
    reg [2:0] rem;   // samples still required before out may flip

    initial out = 1'b0;
    initial cnt = 3'd0;
    initial rem = 3'd4;

    always @(posedge clk) begin
        if (rst) begin
            out <= 1'b0;
            cnt <= 3'd0;
            rem <= 3'd4;
        end else if (sample) begin
            if (raw == out) begin
                cnt <= 3'd0;
                rem <= 3'd4;
            end else if (cnt == 3'd4) begin
                out <= raw;
                cnt <= 3'd0;
                rem <= 3'd4;
            end else begin
                cnt <= cnt + 3'd1;
                rem <= rem - 3'd1;
            end
        end
    end

    always @(posedge clk)
        if (cnt == 3'd4) assert (rem != 3'd4);
endmodule

module pwm_antiphase (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire load,
    input wire [3:0] i_duty,
    output wire pwm_a,
    output wire pwm_b
);
    // ramp counter and its anti-phase mirror (kept complementary by construction)
    reg [3:0] cnt  = 4'd0;
    reg [3:0] cntb = 4'd15;
    // duty for each channel, split so the pair always sums to full scale
    reg [3:0] duty_a = 4'd8;
    reg [3:0] duty_b = 4'd7;

    always @(posedge clk)
        if (rst) begin
            cnt  <= 4'd0;
            cntb <= 4'd15;
        end else if (ce) begin
            cnt  <= cnt  + 4'd1;
            cntb <= cntb - 4'd1;
        end

    always @(posedge clk)
        if (rst) begin
            duty_a <= 4'd8;
            duty_b <= 4'd7;
        end else if (load) begin
            duty_a <= i_duty;
            duty_b <= 4'd15 - i_duty;
        end

    assign pwm_a = (cnt  < duty_a);
    assign pwm_b = (cntb < duty_b);

    // the two half-bridge drives must never be asserted together
    always @(*)
        if (pwm_a) assert (!pwm_b);
endmodule

module prio_pipe (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] req,
    output reg b_valid,
    output reg [2:0] b_idx
);
    reg [7:0] a_vec;
    reg       a_valid;
    reg [7:0] b_vec;

    initial begin
        a_vec = 8'h00; a_valid = 1'b0;
        b_vec = 8'h00; b_idx = 3'd0; b_valid = 1'b0;
    end

    // combinational priority encode of the stage-1 vector (default index 0)
    wire [2:0] a_idx = a_vec[7] ? 3'd7 :
                       a_vec[6] ? 3'd6 :
                       a_vec[5] ? 3'd5 :
                       a_vec[4] ? 3'd4 :
                       a_vec[3] ? 3'd3 :
                       a_vec[2] ? 3'd2 :
                       a_vec[1] ? 3'd1 : 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            a_vec <= 8'h00; a_valid <= 1'b0;
            b_vec <= 8'h00; b_idx <= 3'd0; b_valid <= 1'b0;
        end else if (ce) begin
            a_vec   <= req;
            a_valid <= (req != 8'h00);
            b_vec   <= a_vec;
            b_idx   <= a_idx;
            b_valid <= a_valid;
        end
    end

    always @(posedge clk)
        if (b_valid)
            assert (b_vec[b_idx]);
endmodule

module isqrt_ladder (
    input wire clk,
    input wire rst,
    input wire step,
    output reg [2:0] k,
    output reg [5:0] sq,
    output reg [4:0] odd
);
    initial k   = 3'd0;
    initial sq  = 6'd0;
    initial odd = 5'd1;

    always @(posedge clk) begin
        if (rst) begin
            k   <= 3'd0;
            sq  <= 6'd0;
            odd <= 5'd1;
        end else if (step && k != 3'd7) begin
            k   <= k + 3'd1;
            sq  <= sq + {1'b0, odd};
            odd <= odd + 5'd2;
        end
    end

    // P: when the ladder index reaches 3, the accumulated square must be 9
    always @(posedge clk)
        if (k == 3'd3)
            assert (sq == 6'd9);
endmodule

module gray_cdc_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output reg  [2:0] bin,
    output reg  [2:0] gray,
    output reg  [2:0] prev_gray,
    output reg        past_ce
);
    initial bin       = 3'd0;
    initial gray      = 3'b000;
    initial prev_gray = 3'b000;
    initial past_ce   = 1'b0;

    wire [2:0] bin_nxt  = bin + 3'd1;
    wire [2:0] gray_nxt = bin_nxt ^ (bin_nxt >> 1);
    wire [2:0] delta    = gray ^ prev_gray;

    always @(posedge clk) begin
        if (rst) begin
            bin       <= 3'd0;
            gray      <= 3'b000;
            prev_gray <= 3'b000;
        end else if (ce) begin
            bin       <= bin_nxt;
            gray      <= gray_nxt;
            prev_gray <= gray;
        end
        past_ce <= ce && !rst;
    end

    // P: after an enabled step, the gray output changed in exactly one bit
    always @(posedge clk)
        if (past_ce)
            assert (delta == 3'b001 || delta == 3'b010 || delta == 3'b100);
endmodule

module vend_credit (
    input  wire clk,
    input  wire i_rst,
    input  wire i_nickel,
    input  wire i_dime,
    output wire o_dispense
);
    // credit counted in 5-cent units toward a 25c (5 unit) item
    reg [2:0] units;
    reg [4:0] credit_1h;   // one-hot shadow of the credit level
    initial units     = 3'd0;
    initial credit_1h = 5'b00001;

    wire       step   = i_nickel | i_dime;
    wire [2:0] amount = i_dime ? 3'd2 : 3'd1;
    wire [3:0] sum    = units + amount;

    assign o_dispense = step && (sum >= 4'd5);

    always @(posedge clk)
        if (i_rst) begin
            units     <= 3'd0;
            credit_1h <= 5'b00001;
        end else if (step) begin
            if (sum >= 4'd5) begin
                units     <= 3'd0;          // vend and clear credit
                credit_1h <= 5'b00001;
            end else begin
                units     <= sum[2:0];
                credit_1h <= i_dime ? (credit_1h << 2) : (credit_1h << 1);
            end
        end

    // P: outside reset the credit shadow is always exactly one-hot
    always @(*)
        if (!i_rst)
            assert ((credit_1h != 5'b00000) &&
                    ((credit_1h & (credit_1h - 5'b00001)) == 5'b00000));
endmodule

module crc8_check (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output reg  [7:0] crc,
    output reg        any_one
);
    // bit-serial CRC-8 reduction, polynomial 0x07
    initial begin
        crc     = 8'h00;
        any_one = 1'b0;
    end

    wire fb = crc[7] ^ din;

    always @(posedge clk) begin
        if (rst) begin
            crc     <= 8'h00;
            any_one <= 1'b0;
        end else if (ce) begin
            crc     <= {crc[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);
            any_one <= any_one | din;
        end
    end

    // an all-zero stream can never push weight into the high nibble
    always @(posedge clk)
        if (any_one == 1'b0)
            assert (crc[7:4] == 4'h0);
endmodule

module chess_clock (
    input wire clk,
    input wire rst,
    input wire tick,
    input wire press,
    output reg run_w,
    output reg run_b,
    output reg active,
    output reg [2:0] t_w,
    output reg [2:0] t_b
);
    initial run_w  = 1'b1;
    initial run_b  = 1'b0;
    initial active = 1'b1;
    initial t_w    = 3'd5;
    initial t_b    = 3'd5;

    always @(posedge clk) begin
        if (rst) begin
            run_w <= 1'b1; run_b <= 1'b0; active <= 1'b1;
            t_w <= 3'd5;   t_b <= 3'd5;
        end else if (tick && active) begin
            if (press) begin
                run_w <= ~run_w;
                run_b <= ~run_b;
            end
            if (run_w && t_w != 3'd0) t_w <= t_w - 3'd1;
            if (run_b && t_b != 3'd0) t_b <= t_b - 3'd1;
            if ((run_w && t_w == 3'd1) || (run_b && t_b == 3'd1)) begin
                active <= 1'b0;
                run_w  <= 1'b0;
                run_b  <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (active) assert (!(run_w && run_b));
endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    output wire       o_done,
    output wire [4:0] o_src_off
);
    parameter [4:0] TOTAL = 5'd20;

    reg [4:0] remaining;
    reg [4:0] sent;
    initial remaining = TOTAL;
    initial sent      = 5'd0;

    always @(posedge clk)
        if (rst) begin
            remaining <= TOTAL;
            sent      <= 5'd0;
        end else if (i_ce && (remaining != 5'd0)) begin
            remaining <= remaining - 5'd1;
            sent      <= sent + 5'd1;
        end

    assign o_done    = (remaining == 5'd0);
    assign o_src_off = sent;

    always @(*)
        if (o_done)
            assert (sent == TOTAL);
endmodule

module lfsr_budget (
    input wire clk,
    input wire rst,
    input wire en,
    output reg [7:0] lfsr,
    output reg [2:0] draws,
    output reg [3:0] bits_used
);
    initial lfsr      = 8'h01;
    initial draws     = 3'd0;
    initial bits_used = 4'd0;

    wire fb = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];

    always @(posedge clk) begin
        if (rst) begin
            lfsr      <= 8'h01;
            draws     <= 3'd0;
            bits_used <= 4'd0;
        end else if (en) begin
            if (draws != 3'd7) begin
                lfsr      <= {lfsr[6:0], fb};
                draws     <= draws + 3'd1;
                bits_used <= bits_used + 4'd2;
            end
        end
    end

    always @(posedge clk)
        if (draws != 3'd7)
            assert (bits_used <= 4'd12);
endmodule

module chess_clock (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire press,
    output wire o_frozen
);
    reg [3:0] tA;
    reg [3:0] tB;
    reg [4:0] sum;   // shadow of the combined remaining time
    reg       turn;
    initial tA  = 4'd15;
    initial tB  = 4'd15;
    initial sum = 5'd30;
    initial turn = 1'b0;

    wire frz = (tA == 4'd0) || (tB == 4'd0);
    assign o_frozen = frz;

    always @(posedge clk) begin
        if (rst) begin
            tA   <= 4'd15;
            tB   <= 4'd15;
            sum  <= 5'd30;
            turn <= 1'b0;
        end else if (ce) begin
            if (press)
                turn <= ~turn;
            else if (!frz) begin
                if (turn) tB <= tB - 4'd1;
                else      tA <= tA - 4'd1;
                sum <= sum - 5'd1;
            end
        end
    end

    always @(*)
        if (tA == 4'd0)
            assert (sum == {1'b0, tB});
endmodule

module rr_prio_encoder (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] req,
    output reg [2:0] ptr,
    output reg vld,
    output reg [2:0] gnt_idx
);
    reg [7:0] mask;
    initial begin ptr = 3'd0; mask = 8'h01; vld = 1'b0; gnt_idx = 3'd0; end

    // the rotating priority slot currently under consideration
    wire hit = |(req & mask);

    always @(posedge clk) begin
        if (rst) begin
            ptr     <= 3'd0;
            mask    <= 8'h01;
            vld     <= 1'b0;
            gnt_idx <= 3'd0;
        end else if (ce) begin
            ptr  <= ptr + 3'd1;
            mask <= {mask[6:0], mask[7]};
            vld  <= hit;
            if (hit) gnt_idx <= ptr;
        end
    end

    always @(posedge clk)
        if (ptr == 3'd0)
            assert (mask == 8'h01);
endmodule

module pwm_dimmer (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] duty_in,
    output wire pwm_out
);
    reg [7:0] cnt      = 8'd0;   // free-running ramp
    reg [7:0] duty_reg = 8'd0;   // duty latched at period start
    reg [7:0] high_cnt = 8'd0;   // high-time accumulated this period

    always @(posedge clk)
        if (rst) begin
            cnt      <= 8'd0;
            duty_reg <= 8'd0;
            high_cnt <= 8'd0;
        end else if (ce) begin
            if (cnt == 8'd0) begin
                duty_reg <= duty_in;
                high_cnt <= (duty_in != 8'd0) ? 8'd1 : 8'd0;
                cnt      <= 8'd1;
            end else if (cnt == 8'hFF) begin
                cnt      <= 8'd0;
                high_cnt <= 8'd0;
            end else begin
                cnt      <= cnt + 8'd1;
                high_cnt <= high_cnt + ((cnt < duty_reg) ? 8'd1 : 8'd0);
            end
        end

    assign pwm_out = (cnt < duty_reg);

    always @(posedge clk)
        if (pwm_out)
            assert (high_cnt < duty_reg);
endmodule

module watchdog (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire kick,
    input wire ack,
    output reg fault
);
    reg [3:0] timer;
    reg [3:0] elapsed;
    initial begin timer = 4'd8; elapsed = 4'd0; fault = 1'b0; end

    always @(posedge clk) begin
        if (rst) begin
            timer   <= 4'd8;
            elapsed <= 4'd0;
            fault   <= 1'b0;
        end else if (i_ce) begin
            if (ack) begin
                timer   <= 4'd8;
                elapsed <= 4'd0;
                fault   <= 1'b0;
            end else if (kick && !fault) begin
                timer   <= 4'd8;
                elapsed <= 4'd0;
            end else begin
                if (timer != 4'd0)   timer   <= timer - 4'd1;
                if (elapsed != 4'd8) elapsed <= elapsed + 4'd1;
                if (timer == 4'd1)   fault   <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (elapsed == 4'd8)
            assert (fault);
endmodule

module alu_accum_slice (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire       i_sub,
    output reg  [7:0] o_result,
    output wire       o_zero
);
    reg [6:0] half;

    initial o_result = 8'd0;
    initial half     = 7'd0;

    assign o_zero = (o_result == 8'd0);

    always @(posedge clk) begin
        if (rst) begin
            o_result <= 8'd0;
            half     <= 7'd0;
        end else if (i_ce) begin
            o_result <= i_sub ? (o_result - 8'd2) : (o_result + 8'd2);
            half     <= i_sub ? (half     - 7'd1) : (half     + 7'd1);
        end
    end

    // P: whenever the half-step tracker is at zero, the registered ALU result is zero
    always @(posedge clk)
        if (half == 7'd0)
            assert (o_result == 8'd0);
endmodule

module crc8_bitpos (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire din,
    output reg [7:0] crc,
    output wire byte_done
);
    reg [7:0] active;
    reg [2:0] bitcnt;
    reg [7:0] crc_last;

    initial begin
        crc      = 8'hFF;
        active   = 8'h01;
        bitcnt   = 3'd0;
        crc_last = 8'h00;
    end

    wire       fb      = crc[7] ^ din;
    wire [7:0] crc_nxt = {crc[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);

    assign byte_done = ce && active[7];

    always @(posedge clk) begin
        if (rst) begin
            crc      <= 8'hFF;
            active   <= 8'h01;
            bitcnt   <= 3'd0;
            crc_last <= 8'h00;
        end else if (ce) begin
            crc    <= crc_nxt;
            active <= {active[6:0], active[7]};
            bitcnt <= bitcnt + 3'd1;
            if (active[7]) crc_last <= crc_nxt;
        end
    end

    always @(posedge clk)
        if (bitcnt == 3'd7)
            assert (active == 8'h80);
endmodule

module sqacc (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output wire [5:0] o_sq,
    output wire [2:0] o_cnt
);
    // accumulates successive odd numbers, so sq tracks cnt*cnt (mod 64)
    reg [2:0] cnt;
    reg [5:0] sq;
    reg [3:0] odd;

    initial cnt = 3'd0;
    initial sq  = 6'd0;
    initial odd = 4'd1;

    always @(posedge clk)
        if (rst) begin
            cnt <= 3'd0;
            sq  <= 6'd0;
            odd <= 4'd1;
        end else if (step) begin
            cnt <= cnt + 3'd1;
            sq  <= sq + {2'b00, odd};
            odd <= odd + 4'd2;
        end

    assign o_sq  = sq;
    assign o_cnt = cnt;

    // P: at the third index the accumulated value must be the perfect square 9
    always @(*)
        if (cnt == 3'd3)
            assert (sq == 6'd9);
endmodule

module rotstage (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire i_valid,
    input wire [3:0] i_amt,
    input wire [15:0] i_data,
    output wire o_valid,
    output wire [15:0] o_data
);
    reg v0, v1, v2, v3;
    reg [2:0] pend;
    reg [15:0] d0, d1, d2, d3;
    reg [3:0] a0, a1, a2;

    initial begin
        v0 = 0; v1 = 0; v2 = 0; v3 = 0; pend = 0;
        d0 = 0; d1 = 0; d2 = 0; d3 = 0;
        a0 = 0; a1 = 0; a2 = 0;
    end

    always @(posedge clk) begin
        if (rst) begin
            v0 <= 0; v1 <= 0; v2 <= 0; v3 <= 0; pend <= 0;
        end else if (ce) begin
            v0 <= i_valid;
            v1 <= v0;
            v2 <= v1;
            v3 <= v2;
            pend <= pend + (i_valid ? 3'd1 : 3'd0) - (v3 ? 3'd1 : 3'd0);
            d0 <= i_amt[0] ? {i_data[14:0], i_data[15]} : i_data;
            a0 <= i_amt;
            d1 <= a0[1] ? {d0[13:0], d0[15:14]} : d0;
            a1 <= a0;
            d2 <= a1[2] ? {d1[11:0], d1[15:12]} : d1;
            a2 <= a1;
            d3 <= a2[3] ? {d2[7:0], d2[15:8]} : d2;
        end
    end

    assign o_valid = v3;
    assign o_data  = d3;

    always @(posedge clk)
        if (pend == 3'd0) assert (!v3);
endmodule

module sorted_pair (
    input wire clk,
    input wire rst,
    input wire ins,
    input wire pop,
    input wire [3:0] val,
    output reg [4:0] sum
);
    reg [3:0] k0, k1;
    reg [1:0] count;
    initial begin k0 = 0; k1 = 0; count = 0; sum = 0; end

    wire do_ins = ins && !pop && (count != 2'd2);
    wire do_pop = pop && !ins && (count != 2'd0);

    always @(posedge clk) begin
        if (rst) begin
            k0 <= 4'd0; k1 <= 4'd0; count <= 2'd0; sum <= 5'd0;
        end else if (do_ins) begin
            if (count == 2'd0) begin
                k0 <= val;
            end else if (val < k0) begin
                k0 <= val; k1 <= k0;
            end else begin
                k1 <= val;
            end
            count <= count + 2'd1;
            sum   <= sum + {1'b0, val};
        end else if (do_pop) begin
            k0    <= k1;
            k1    <= 4'd0;
            count <= count - 2'd1;
            sum   <= sum - {1'b0, k0};
        end
    end

    always @(posedge clk)
        if (count == 2'd0)
            assert (sum == 5'd0);
endmodule

module token_bucket (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire req,
    input  wire drip,
    output wire grant
);
    reg [3:0] tokens = 4'd8;   // tokens currently in the bucket
    reg [3:0] free   = 4'd0;   // room left in the bucket (shadow accounting)

    wire spend   = ce && req  && (tokens != 4'd0);
    wire refill  = ce && drip && (free   != 4'd0);

    assign grant = spend;

    always @(posedge clk) begin
        if (rst) begin
            tokens <= 4'd8;
            free   <= 4'd0;
        end else begin
            tokens <= tokens - spend + refill;
            free   <= free   + spend - refill;
        end
    end

    // P: if the bucket is not completely full, at least one slot's worth of
    // tokens is missing, so occupancy cannot exceed CAP-1.
    always @(posedge clk)
        if (free != 4'd0)
            assert (tokens <= 4'd7);
endmodule

module stack_hwm (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] top
);
    reg [3:0] sp;
    reg [3:0] hwm;
    reg [7:0] mem [0:15];
    initial begin sp = 4'd0; hwm = 4'd0; end

    wire do_push = ce && push && (sp != 4'd8);
    wire do_pop  = ce && pop  && (sp != 4'd0);
    wire [3:0] nxt = sp + 4'd1;

    assign top = (sp == 4'd0) ? 8'h00 : mem[sp - 4'd1];

    always @(posedge clk) begin
        if (rst) begin
            sp  <= 4'd0;
            hwm <= 4'd0;
        end else begin
            case ({do_push, do_pop})
                2'b10: begin
                    mem[sp] <= din;
                    sp <= nxt;
                    if (nxt > hwm) hwm <= nxt;
                end
                2'b01: sp <= sp - 4'd1;
                default: ;
            endcase
        end
    end

    always @(posedge clk)
        if (sp == 4'd8)
            assert (hwm == 4'd8);
endmodule

module vend_credit (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_dime,
    output wire o_dispense,
    output wire [5:0] o_change
);
    reg [3:0] units = 0;      // credit in 5-cent units
    reg [5:0] cents = 0;      // credit in cents
    reg       dispense = 0;
    reg [5:0] change = 0;

    wire [3:0] inc_u = i_dime ? 4'd2  : 4'd1;
    wire [5:0] inc_c = i_dime ? 6'd10 : 6'd5;
    wire [3:0] nu = units + inc_u;
    wire [5:0] nc = cents + inc_c;

    always @(posedge clk)
        if (i_reset) begin
            units    <= 4'd0;
            cents    <= 6'd0;
            dispense <= 1'b0;
            change   <= 6'd0;
        end else if (i_ce) begin
            if (nu >= 4'd5) begin
                units    <= nu - 4'd5;
                cents    <= nc - 6'd25;
                change   <= nc - 6'd25;
                dispense <= 1'b1;
            end else begin
                units    <= nu;
                cents    <= nc;
                dispense <= 1'b0;
            end
        end

    assign o_dispense = dispense;
    assign o_change   = change;

    always @(posedge clk)
        if (dispense) assert (change <= 6'd5);
endmodule

module substr_search (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] in_char,
    output reg [1:0] idx,
    output reg found
);
    localparam [7:0] TGT = 8'h61; // 'a'

    initial idx   = 2'd0;
    initial found = 1'b0;

    // matches the 3-character run "aaa"; freezes once idx saturates at 3
    always @(posedge clk) begin
        if (rst) begin
            idx   <= 2'd0;
            found <= 1'b0;
        end else if (ce && idx != 2'd3) begin
            if (in_char == TGT) begin
                idx <= idx + 2'd1;
                if (idx == 2'd2)
                    found <= 1'b1;
            end else begin
                idx <= 2'd0;
            end
        end
    end

    // P: the found flag implies a non-empty partial match is held
    always @(posedge clk)
        if (found) assert (idx != 2'd0);
endmodule

module rr_arbiter_pri (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire [3:0] req,
    output wire [3:0] gnt,
    output reg  [3:0] pri,
    output reg  [1:0] idx
);
    initial pri = 4'b0001;
    initial idx = 2'd0;

    // only the requester currently pointed at by the rotating priority wins
    assign gnt = req & pri;

    wire low_pri = pri[0] | pri[1];   // priority pointer sits in lower half
    wire idx_hi  = idx[1];            // binary index says upper half

    always @(posedge clk) begin
        if (rst) begin
            pri <= 4'b0001;
            idx <= 2'd0;
        end else if (step) begin
            pri <= {pri[2:0], pri[3]};
            idx <= idx + 2'd1;
        end
    end

    always @(posedge clk)
        if (|gnt)
            assert (!(low_pri && idx_hi));
endmodule

module alu_budget (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire [7:0] i_step,
    output wire [7:0] o_acc,
    output wire o_zero,
    output wire o_full
);
    localparam [7:0] LIMIT = 8'd200;

    reg [7:0] acc;   // accumulated result
    reg [7:0] rem;   // headroom credited to the accumulator
    initial acc = 8'd0;
    initial rem = LIMIT;

    wire grant = i_ce && (rem >= i_step);

    always @(posedge clk)
        if (rst) begin
            acc <= 8'd0;
            rem <= LIMIT;
        end else if (grant) begin
            acc <= acc + i_step;
            rem <= rem - i_step;
        end

    assign o_acc  = acc;
    assign o_zero = (acc == 8'd0);
    assign o_full = (rem == 8'd0);

    // P: a nonzero accumulation never exceeds its saturation bound
    always @(*)
        if (!o_zero) assert (acc <= LIMIT);
endmodule

module chess_clock (
    input  wire clk,
    input  wire ce,
    input  wire rst,
    input  wire press,
    output reg  frozen
);
    // Each side starts with 5 units of time.
    reg [2:0] time_a, time_b;   // remaining time per side
    reg [2:0] spent_a, spent_b; // ticks consumed per side
    reg       turn;             // 0 = side A running, 1 = side B running

    initial begin
        time_a  = 3'd5;
        time_b  = 3'd5;
        spent_a = 3'd0;
        spent_b = 3'd0;
        turn    = 1'b0;
        frozen  = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            if (rst) begin
                time_a  <= 3'd5;
                time_b  <= 3'd5;
                spent_a <= 3'd0;
                spent_b <= 3'd0;
                turn    <= 1'b0;
                frozen  <= 1'b0;
            end else if (!frozen) begin
                if (press) begin
                    // hand over the move: exactly one side runs at a time
                    turn <= ~turn;
                end else if (turn == 1'b0) begin
                    time_a  <= time_a  - 1'b1;
                    spent_a <= spent_a + 1'b1;
                    if (time_a == 3'd1)
                        frozen <= 1'b1;
                end else begin
                    time_b  <= time_b  - 1'b1;
                    spent_b <= spent_b + 1'b1;
                    if (time_b == 3'd1)
                        frozen <= 1'b1;
                end
            end
        end
    end

    // P: the clock only freezes once some side has burned its full allowance.
    always @(posedge clk)
        if (frozen)
            assert (spent_a == 3'd5 || spent_b == 3'd5);
endmodule

module ring_valid_onehot (
    input wire        clk,
    input wire        rst,
    input wire        push,
    input wire        pop,
    input wire [7:0]  din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full
);
    // 4-deep ring buffer with a per-slot valid bit vector
    reg [1:0] wptr;
    reg [1:0] rptr;
    reg [2:0] count;
    reg [3:0] valid;
    reg [7:0] mem [0:3];

    integer k;
    initial begin
        wptr  = 2'd0;
        rptr  = 2'd0;
        count = 3'd0;
        valid = 4'b0000;
        for (k = 0; k < 4; k = k + 1)
            mem[k] = 8'h00;
    end

    wire do_push = push && (count != 3'd4);
    wire do_pop  = pop  && (count != 3'd0);

    assign o_empty = (count == 3'd0);
    assign o_full  = (count == 3'd4);
    assign dout    = mem[rptr];

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
            valid <= 4'b0000;
        end else begin
            if (do_push) begin
                mem[wptr]   <= din;
                valid[wptr] <= 1'b1;
                wptr        <= wptr + 2'd1;
            end
            if (do_pop) begin
                valid[rptr] <= 1'b0;
                rptr        <= rptr + 2'd1;
            end
            if (do_push && !do_pop)
                count <= count + 3'd1;
            else if (!do_push && do_pop)
                count <= count - 3'd1;
        end
    end

    // occupancy window implied by (rptr, count): slot i is occupied iff
    // ((i - rptr) mod 4) < count
    wire [1:0] d0 = 2'd0 - rptr;
    wire [1:0] d1 = 2'd1 - rptr;
    wire [1:0] d2 = 2'd2 - rptr;
    wire [1:0] d3 = 2'd3 - rptr;
    wire [3:0] occ;
    assign occ[0] = ({1'b0, d0} < count);
    assign occ[1] = ({1'b0, d1} < count);
    assign occ[2] = ({1'b0, d2} < count);
    assign occ[3] = ({1'b0, d3} < count);

    // P: a single-entry queue has exactly one valid slot
    always @(*)
        if (count == 3'd1)
            assert ((valid == 4'b0001) || (valid == 4'b0010) ||
                    (valid == 4'b0100) || (valid == 4'b1000));
endmodule

module debounce_shadow (
    input  wire clk,
    input  wire rst,
    input  wire ce,      // sample enable: low => design idles, no state changes
    input  wire raw,     // raw (noisy) button input
    output reg  out      // debounced output
);
    // stability counter (binary) and its one-hot phase shadow
    reg [1:0] cnt;
    reg [3:0] oh;

    reg       sync;        // last sampled level
    reg       out_shadow;  // shadow copy of out, driven off the one-hot path
    reg       out_valid;   // set once a debounced decision has been taken

    initial begin
        cnt        = 2'd0;
        oh         = 4'b0001;
        sync       = 1'b0;
        out        = 1'b0;
        out_shadow = 1'b0;
        out_valid  = 1'b0;
    end

    wire match = (raw == sync);

    always @(posedge clk) begin
        if (rst) begin
            cnt        <= 2'd0;
            oh         <= 4'b0001;
            sync       <= raw;
            out        <= 1'b0;
            out_shadow <= 1'b0;
            out_valid  <= 1'b0;
        end else if (ce) begin
            if (!match) begin
                // input changed: restart the stability measurement
                sync <= raw;
                cnt  <= 2'd0;
                oh   <= 4'b0001;
            end else begin
                // advance binary counter (saturating)
                if (cnt != 2'd3)
                    cnt <= cnt + 2'd1;
                // advance one-hot phase (saturating in the top position)
                if (!oh[3])
                    oh <= oh << 1;
                // decision taken from the BINARY path
                if (cnt == 2'd3) begin
                    out       <= sync;
                    out_valid <= 1'b1;
                end
                // decision taken from the ONE-HOT path
                if (oh[3])
                    out_shadow <= sync;
            end
        end
    end

    // P: once a debounced decision exists, the shadow must agree with the output
    always @(posedge clk)
        if (out_valid)
            assert (out == out_shadow);
endmodule

module vend_credit (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_coin_valid,   // idle when low: all state frozen
    input  wire       i_coin_dime,    // 1 = 10c, 0 = 5c
    output reg        o_dispense,
    output reg  [5:0] o_change
);
    // credit in cents, always a multiple of 5, capped by the 25c price
    reg [5:0] credit;
    // redundant "nickel units" accumulator: credit / 5
    reg [2:0] units;

    initial credit     = 6'd0;
    initial units      = 3'd0;
    initial o_dispense = 1'b0;
    initial o_change   = 6'd0;

    // coin value, in units and in cents
    wire [2:0] coin_u = i_coin_valid ? (i_coin_dime ? 3'd2 : 3'd1) : 3'd0;
    wire [5:0] coin_c = i_coin_valid ? (i_coin_dime ? 6'd10 : 6'd5) : 6'd0;

    wire [3:0] usum = {1'b0, units}  + {1'b0, coin_u};
    wire [6:0] csum = {1'b0, credit} + {1'b0, coin_c};

    // the dispense decision is taken on the units accumulator
    wire       pay   = (usum >= 4'd5);

    always @(posedge clk) begin
        if (rst) begin
            credit     <= 6'd0;
            units      <= 3'd0;
            o_dispense <= 1'b0;
            o_change   <= 6'd0;
        end else if (i_coin_valid) begin
            if (pay) begin
                units      <= usum[2:0] - 3'd5;
                credit     <= csum[5:0] - 6'd25;
                o_dispense <= 1'b1;
                o_change   <= csum[5:0] - 6'd25;
            end else begin
                units      <= usum[2:0];
                credit     <= csum[5:0];
                o_dispense <= 1'b0;
            end
        end else begin
            o_dispense <= 1'b0;
        end
    end

    // P: when the units accumulator sits one nickel short of the price,
    //    the cent accumulator must read exactly 20 cents.
    always @(*)
        if (units == 3'd4)
            assert (credit == 6'd20);
endmodule

module token_bucket_ledger (
    input  wire       clk,
    input  wire       rst,
    input  wire       drip_en,
    input  wire       grant_req,
    output wire       grant,
    output wire       dry
);
    localparam [3:0] CAP = 4'd8;

    // bucket level
    reg [3:0] tokens = 4'd0;
    // free-running mod-16 ledgers of every accepted drip and every issued grant
    reg [3:0] drips  = 4'd0;
    reg [3:0] grants = 4'd0;

    wire do_drip  = drip_en   && (tokens < CAP);
    wire do_grant = grant_req && (tokens != 4'd0);

    assign grant = do_grant;
    assign dry   = (tokens == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            tokens <= 4'd0;
            drips  <= 4'd0;
            grants <= 4'd0;
        end else begin
            if (do_drip && !do_grant)
                tokens <= tokens + 4'd1;
            else if (!do_drip && do_grant)
                tokens <= tokens - 4'd1;

            if (do_drip)
                drips <= drips + 4'd1;
            if (do_grant)
                grants <= grants + 4'd1;
        end
    end

    // P: whenever the two ledgers agree, the bucket must be empty
    always @(posedge clk)
        if (drips == grants)
            assert (tokens == 4'd0);
endmodule

module uart_tx_budget (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // baud tick / enable: low means idle
    input  wire       i_start,
    input  wire [7:0] i_data,
    output reg        tx,
    output reg        busy
);
    // bit accounting for one 8-bit payload
    reg [3:0] sent;   // data bits already shifted out
    reg [3:0] left;    // data bits still to shift out
    reg [7:0] sh;      // shift register

    initial tx   = 1'b1;
    initial busy = 1'b0;
    initial sent = 4'd0;
    initial left = 4'd8;
    initial sh   = 8'h00;

    always @(posedge clk) begin
        if (rst) begin
            tx   <= 1'b1;
            busy <= 1'b0;
            sent <= 4'd0;
            left <= 4'd8;
            sh   <= 8'h00;
        end else if (i_ce) begin
            if (!busy) begin
                if (i_start) begin
                    busy <= 1'b1;
                    sh   <= i_data;
                    sent <= 4'd0;
                    left <= 4'd8;
                    tx   <= 1'b0;      // start bit
                end else begin
                    tx   <= 1'b1;      // line idle high
                end
            end else if (left != 4'd0) begin
                tx   <= sh[0];         // data bit
                sh   <= {1'b0, sh[7:1]};
                sent <= sent + 4'd1;
                left <= left - 4'd1;
            end else begin
                tx   <= 1'b1;          // stop bit, frame complete
                busy <= 1'b0;
            end
        end
    end

    // Property: whenever the transmitter reports no data bits remaining while a
    // frame is still active, exactly eight payload bits must have been shifted.
    always @(posedge clk)
        if (busy && left == 4'd0)
            assert (sent == 4'd8);
endmodule

module crc8_bitpos_check (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       bit_in,
    output wire [7:0] o_crc,
    output wire [7:0] o_byte,
    output wire       o_byte_done
);
    parameter [7:0] POLY = 8'h07;

    // streaming CRC-8 remainder, one bit per cycle
    reg [7:0] crc;
    // one-hot pointer marking which bit slot of the byte is being filled
    reg [7:0] mask;
    // bit index within the current byte
    reg [2:0] cnt;
    // byte under assembly
    reg [7:0] byte_sr;

    initial crc     = 8'h00;
    initial mask    = 8'h01;
    initial cnt     = 3'd0;
    initial byte_sr = 8'h00;

    wire fb = crc[7] ^ bit_in;

    always @(posedge clk) begin
        if (rst) begin
            crc     <= 8'h00;
            mask    <= 8'h01;
            cnt     <= 3'd0;
            byte_sr <= 8'h00;
        end else if (ce) begin
            crc     <= { crc[6:0], 1'b0 } ^ (fb ? POLY : 8'h00);
            mask    <= { mask[6:0], mask[7] };
            cnt     <= cnt + 3'd1;
            byte_sr <= (byte_sr & ~mask) | (bit_in ? mask : 8'h00);
        end
    end

    assign o_crc       = crc;
    assign o_byte      = byte_sr;
    assign o_byte_done = ce && (cnt == 3'd7);

    // P: at a byte boundary the fill pointer must point at bit 0
    always @(posedge clk)
        if (cnt == 3'd0)
            assert (mask == 8'h01);
endmodule

module rr_arb (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,       // enable: low means the arbiter idles
    input  wire [3:0] req,
    output reg  [3:0] grant,
    output reg        gnt_valid
);
    reg [1:0] ptr;      // round-robin priority pointer
    reg [1:0] gnt_id;   // id of the currently granted requester

    initial begin
        grant     = 4'b0000;
        gnt_valid = 1'b0;
        ptr       = 2'd0;
        gnt_id    = 2'd0;
    end

    // rotate the request vector by the priority pointer
    wire [3:0] rreq;
    assign rreq[0] = req[ptr];
    assign rreq[1] = req[ptr + 2'd1];
    assign rreq[2] = req[ptr + 2'd2];
    assign rreq[3] = req[ptr + 2'd3];

    wire [1:0] roff = rreq[0] ? 2'd0 :
                      rreq[1] ? 2'd1 :
                      rreq[2] ? 2'd2 : 2'd3;

    wire       win_valid = |req;
    wire [1:0] win_id    = ptr + roff;

    // one-hot masks derived from the recorded ids
    wire [3:0] old_mask = 4'b0001 << gnt_id;
    wire [3:0] new_mask = 4'b0001 << win_id;

    always @(posedge clk) begin
        if (rst) begin
            grant     <= 4'b0000;
            gnt_valid <= 1'b0;
            ptr       <= 2'd0;
            gnt_id    <= 2'd0;
        end else if (step) begin
            if (win_valid) begin
                // release the previously granted line, assert the new one
                grant     <= (grant & ~old_mask) | new_mask;
                gnt_id    <= win_id;
                gnt_valid <= 1'b1;
                ptr       <= win_id + 2'd1;
            end else begin
                grant     <= grant & ~old_mask;
                gnt_valid <= 1'b0;
            end
        end
    end

    // P: while a grant is outstanding, no two grant lines are high together
    always @(posedge clk)
        if (gnt_valid)
            assert (grant == 4'b0001 || grant == 4'b0010 ||
                    grant == 4'b0100 || grant == 4'b1000);
endmodule

module stack_mask (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       empty,
    output wire       full,
    output reg  [3:0] sp
);
    // occupancy mask: bit i is set iff slot i currently holds data.
    // maintained purely by shifting, never recomputed from sp.
    reg [7:0] occ;
    reg [7:0] mem0, mem1, mem2, mem3, mem4, mem5, mem6, mem7;

    initial begin
        sp   = 4'd0;
        occ  = 8'h00;
        mem0 = 8'h00; mem1 = 8'h00; mem2 = 8'h00; mem3 = 8'h00;
        mem4 = 8'h00; mem5 = 8'h00; mem6 = 8'h00; mem7 = 8'h00;
    end

    assign empty = (sp == 4'd0);
    assign full  = (sp == 4'd8);

    wire do_push = en && push && !pop && !full;
    wire do_pop  = en && pop  && !push && !empty;

    wire [2:0] top = sp[2:0] - 3'd1;

    assign dout = empty ? 8'h00 :
                  (top == 3'd0) ? mem0 :
                  (top == 3'd1) ? mem1 :
                  (top == 3'd2) ? mem2 :
                  (top == 3'd3) ? mem3 :
                  (top == 3'd4) ? mem4 :
                  (top == 3'd5) ? mem5 :
                  (top == 3'd6) ? mem6 : mem7;

    always @(posedge clk) begin
        if (rst) begin
            sp  <= 4'd0;
            occ <= 8'h00;
        end else if (do_push) begin
            sp  <= sp + 4'd1;
            occ <= {occ[6:0], 1'b1};
        end else if (do_pop) begin
            sp  <= sp - 4'd1;
            occ <= {1'b0, occ[7:1]};
        end
    end

    always @(posedge clk) begin
        if (!rst && do_push) begin
            case (sp[2:0])
                3'd0: mem0 <= din;
                3'd1: mem1 <= din;
                3'd2: mem2 <= din;
                3'd3: mem3 <= din;
                3'd4: mem4 <= din;
                3'd5: mem5 <= din;
                3'd6: mem6 <= din;
                3'd7: mem7 <= din;
            endcase
        end
    end

    // P: an empty stack must own no slots.
    always @(posedge clk)
        if (sp == 4'd0)
            assert (occ == 8'h00);
endmodule

module elevator_cab (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,        // idle condition: low freezes all state
    input  wire       req_valid,
    input  wire [1:0] req_floor,
    output reg  [1:0] floor,
    output reg  [1:0] target,
    output reg  [1:0] dist,        // remaining floors of travel
    output reg        dir,         // 1 = up, 0 = down
    output reg        busy         // cab is in transit
);
    initial floor  = 2'd0;
    initial target = 2'd0;
    initial dist   = 2'd0;
    initial dir    = 1'b0;
    initial busy   = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            floor  <= 2'd0;
            target <= 2'd0;
            dist   <= 2'd0;
            dir    <= 1'b0;
            busy   <= 1'b0;
        end else if (step) begin
            if (busy) begin
                // one floor of travel per step
                if (dir)
                    floor <= floor + 2'd1;
                else
                    floor <= floor - 2'd1;
                dist <= dist - 2'd1;
                if (dist == 2'd1)
                    busy <= 1'b0;
            end else if (req_valid && (req_floor != floor)) begin
                target <= req_floor;
                dir    <= (req_floor > floor);
                dist   <= (req_floor > floor) ? (req_floor - floor)
                                              : (floor - req_floor);
                busy   <= 1'b1;
            end
        end
    end

    // P: whenever the cab is not in transit, it is parked at its target floor
    always @(posedge clk)
        if (!busy)
            assert (floor == target);
endmodule

module queue_ring_onehot (
    input  wire clk,
    input  wire rst,
    input  wire push,
    input  wire pop,
    input  wire [7:0] wdata,
    output wire [7:0] rdata,
    output wire full,
    output wire empty
);
    // 4-entry ring buffer.  The write and read positions are kept as one-hot
    // slot selects that rotate; the occupancy is kept as a separate counter.
    reg [2:0] count;
    reg [3:0] wsel;
    reg [3:0] rsel;
    reg [7:0] mem0, mem1, mem2, mem3;

    initial count = 3'd0;
    initial wsel  = 4'b0001;
    initial rsel  = 4'b0001;
    initial mem0  = 8'h00;
    initial mem1  = 8'h00;
    initial mem2  = 8'h00;
    initial mem3  = 8'h00;

    assign full  = (count == 3'd4);
    assign empty = (count == 3'd0);

    wire do_push = push && (count != 3'd4);
    wire do_pop  = pop  && (count != 3'd0);

    assign rdata = rsel[0] ? mem0 :
                   rsel[1] ? mem1 :
                   rsel[2] ? mem2 : mem3;

    always @(posedge clk) begin
        if (rst) begin
            count <= 3'd0;
            wsel  <= 4'b0001;
            rsel  <= 4'b0001;
        end else begin
            if (do_push && !do_pop)
                count <= count + 3'd1;
            else if (do_pop && !do_push)
                count <= count - 3'd1;

            if (do_push)
                wsel <= { wsel[2:0], wsel[3] };

            if (do_pop)
                rsel <= { rsel[2:0], rsel[3] };
        end
    end

    always @(posedge clk) begin
        if (!rst && do_push) begin
            if (wsel[0]) mem0 <= wdata;
            if (wsel[1]) mem1 <= wdata;
            if (wsel[2]) mem2 <= wdata;
            if (wsel[3]) mem3 <= wdata;
        end
    end

    // P: an empty ring must have its write slot select aligned with its read
    // slot select.
    always @(*)
        if (count == 3'd0)
            assert (wsel == rsel);
endmodule

module lfsr_shadow_capture (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_cap,
    output wire [7:0] o_rand,
    output wire [7:0] o_shadow,
    output wire       o_shadow_valid
);
    // maximal-length 8-bit LFSR, taps at 8,6,5,4 (x^8 + x^6 + x^5 + x^4 + 1)
    reg [7:0] lfsr;
    reg [7:0] shadow;
    reg       shadow_valid;

    initial lfsr         = 8'h01;
    initial shadow       = 8'h00;
    initial shadow_valid = 1'b0;

    wire fb = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];

    always @(posedge i_clk) begin
        if (i_rst) begin
            lfsr <= 8'h01;
        end else if (i_ce) begin
            lfsr <= { lfsr[6:0], fb };
        end
    end

    // shadow register: snapshots the generator output on request
    always @(posedge i_clk) begin
        if (i_rst) begin
            shadow       <= 8'h00;
            shadow_valid <= 1'b0;
        end else if (i_ce && i_cap) begin
            shadow       <= lfsr;
            shadow_valid <= 1'b1;
        end
    end

    assign o_rand         = lfsr;
    assign o_shadow       = shadow;
    assign o_shadow_valid = shadow_valid;

    // P: once a sample has been latched, it can never be the lockup word
    always @(*)
        if (shadow_valid)
            assert (shadow != 8'h00);
endmodule

module gray_cdc_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output reg  [3:0] gray
);
    // shadow binary counter
    reg [3:0] bin;
    // previous emitted gray value, and a sticky flag saying one step happened
    reg [3:0] gray_prev;
    reg       changed;

    initial bin       = 4'd0;
    initial gray      = 4'b0000;
    initial gray_prev = 4'b0000;
    initial changed   = 1'b0;

    wire [3:0] bin_nxt  = bin + 4'd1;
    wire [3:0] gray_nxt = bin_nxt ^ (bin_nxt >> 1);

    always @(posedge clk) begin
        if (rst) begin
            bin       <= 4'd0;
            gray      <= 4'b0000;
            gray_prev <= 4'b0000;
            changed   <= 1'b0;
        end else if (step) begin
            bin       <= bin_nxt;
            gray      <= gray_nxt;
            gray_prev <= gray;
            changed   <= 1'b1;
        end
    end

    // P: once a step has been taken, the current and previous gray words
    //    differ in exactly one bit (safe for clock-domain crossing).
    wire [3:0] diff = gray ^ gray_prev;

    always @(posedge clk) begin
        if (changed)
            assert ((diff != 4'b0000) && ((diff & (diff - 4'd1)) == 4'b0000));
    end
endmodule

module thermo_hyst (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output reg        heat_on,
    output reg [2:0]  on_events,
    output reg [2:0]  off_events
);
    localparam [5:0] T_LOW  = 6'd20;
    localparam [5:0] T_HIGH = 6'd40;

    reg [5:0] temp;

    initial begin
        temp       = 6'd30;
        heat_on    = 1'b0;
        on_events  = 3'd0;
        off_events = 3'd0;
    end

    // hysteresis decisions
    wire turn_on  = ce && !heat_on && (temp <= T_LOW);
    wire turn_off = ce &&  heat_on && (temp >= T_HIGH);

    always @(posedge clk) begin
        if (rst) begin
            temp       <= 6'd30;
            heat_on    <= 1'b0;
            on_events  <= 3'd0;
            off_events <= 3'd0;
        end else if (ce) begin
            if (turn_on) begin
                heat_on   <= 1'b1;
                on_events <= on_events + 3'd1;
            end else if (turn_off) begin
                heat_on    <= 1'b0;
                off_events <= off_events + 3'd1;
            end

            // plant: heater warms, ambient cools
            if (heat_on) begin
                if (temp != 6'd63) temp <= temp + 6'd1;
            end else begin
                if (temp != 6'd0)  temp <= temp - 6'd1;
            end
        end
    end

    // P: whenever the heater is commanded on, strictly more on-events than
    // off-events have been logged, so the two event counters cannot agree.
    always @(posedge clk)
        if (heat_on)
            assert (on_events != off_events);

endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output reg  [3:0] remaining,
    output reg  [3:0] sent,
    output reg        busy,
    output reg        done
);
    // block length is fixed at 8 words
    initial remaining = 4'd8;
    initial sent      = 4'd0;
    initial busy      = 1'b1;
    initial done      = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            remaining <= 4'd8;
            sent      <= 4'd0;
            busy      <= 1'b1;
            done      <= 1'b0;
        end else if (ce) begin
            if (remaining != 4'd0) begin
                remaining <= remaining - 4'd1;
                sent      <= sent + 4'd1;
                if (remaining == 4'd1)
                    busy <= 1'b0;
            end
            // done is raised the cycle after the last word retires
            done <= (remaining == 4'd0);
        end
    end

    // P: the engine must never report completion while still claiming to copy
    always @(posedge clk)
        if (done)
            assert (!busy);
endmodule

module prio_pipe (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire [7:0] req,
    output reg        y_valid,
    output reg  [2:0] y_index,
    output reg        y_bit
);
    // combinational priority encode of the incoming request vector
    wire       c_valid = |req;
    wire [2:0] c_index = req[7] ? 3'd7 :
                         req[6] ? 3'd6 :
                         req[5] ? 3'd5 :
                         req[4] ? 3'd4 :
                         req[3] ? 3'd3 :
                         req[2] ? 3'd2 :
                         req[1] ? 3'd1 : 3'd0;

    // stage 1: captured request vector plus its encoding
    reg [7:0] q_req;
    reg       q_valid;
    reg [2:0] q_index;

    initial begin
        q_req   = 8'h00;
        q_valid = 1'b0;
        q_index = 3'd0;
        y_valid = 1'b0;
        y_index = 3'd0;
        y_bit   = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            q_req   <= 8'h00;
            q_valid <= 1'b0;
            q_index <= 3'd0;
        end else if (i_ce) begin
            q_req   <= req;
            q_valid <= c_valid;
            q_index <= c_index;
        end
    end

    // stage 2: registered output stage, samples the selected bit out of the
    // captured vector using the captured index
    always @(posedge clk) begin
        if (rst) begin
            y_valid <= 1'b0;
            y_index <= 3'd0;
            y_bit   <= 1'b0;
        end else if (i_ce) begin
            y_valid <= q_valid;
            y_index <= q_index;
            y_bit   <= q_req[q_index];
        end
    end

    // property: a granted output must point at a bit that was actually set
    always @(posedge clk)
        if (y_valid)
            assert (y_bit == 1'b1);
endmodule

// Two-road intersection controller.
// Light codes: 0 = RED, 1 = GREEN, 2 = YELLOW
// Phases: 0 NS-green, 1 NS-yellow, 2 all-red, 3 EW-green, 4 EW-yellow, 5 all-red
// Each phase handover advances the affected road's light one step around the
// RED -> GREEN -> YELLOW -> RED ring.
module intersection_ctrl (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output wire       o_ns_green,
    output wire       o_ew_green,
    output wire [2:0] o_phase
);
    localparam [1:0] RED    = 2'd0;
    localparam [1:0] GREEN  = 2'd1;
    localparam [1:0] YELLOW = 2'd2;

    localparam [2:0] PHASE_LEN = 3'd4;

    reg [2:0] phase;
    reg [2:0] timer;
    reg [1:0] ns_state;
    reg [1:0] ew_state;

    initial phase    = 3'd0;
    initial timer    = PHASE_LEN;
    initial ns_state = GREEN;
    initial ew_state = RED;

    // one step around the three-colour ring
    function [1:0] nextcolor;
        input [1:0] c;
        begin
            if (c == YELLOW)
                nextcolor = RED;
            else
                nextcolor = c + 2'd1;
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            phase    <= 3'd0;
            timer    <= PHASE_LEN;
            ns_state <= GREEN;
            ew_state <= RED;
        end else if (ce) begin
            if (timer != 3'd0) begin
                timer <= timer - 3'd1;
            end else begin
                timer <= PHASE_LEN;
                case (phase)
                3'd0: begin // NS green expires -> NS yellow
                    phase    <= 3'd1;
                    ns_state <= nextcolor(ns_state);
                end
                3'd1: begin // NS yellow expires -> all red
                    phase    <= 3'd2;
                    ns_state <= nextcolor(ns_state);
                end
                3'd2: begin // all red -> EW green
                    phase    <= 3'd3;
                    ew_state <= nextcolor(ew_state);
                end
                3'd3: begin // EW green expires -> EW yellow
                    phase    <= 3'd4;
                    ew_state <= nextcolor(ew_state);
                end
                3'd4: begin // EW yellow expires -> all red
                    phase    <= 3'd5;
                    ew_state <= nextcolor(ew_state);
                end
                3'd5: begin // all red -> NS green
                    phase    <= 3'd0;
                    ns_state <= nextcolor(ns_state);
                end
                default: begin
                    phase <= phase;
                end
                endcase
            end
        end
    end

    assign o_ns_green = (ns_state == GREEN);
    assign o_ew_green = (ew_state == GREEN);
    assign o_phase    = phase;

    // P: the two roads are never green at the same time
    always @(*)
        if (ns_state == GREEN)
            assert (ew_state != GREEN);
endmodule

module pwm_dimmer_seq (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] duty_in,
    output wire       pwm
);
    // free-running PWM phase counter
    reg [3:0] phase       = 4'd0;
    // rotating one-hot channel selector, advanced once per PWM period
    reg [3:0] chan_sel    = 4'b0001;
    // binary mirror of the selector position
    reg [1:0] idx         = 2'd0;
    // duty latched at the period boundary
    reg [7:0] duty_shadow = 8'd0;

    assign pwm = (phase < duty_shadow[7:4]);

    wire period_end = ce && (phase == 4'd15);

    always @(posedge clk) begin
        if (rst) begin
            phase       <= 4'd0;
            chan_sel    <= 4'b0001;
            idx         <= 2'd0;
            duty_shadow <= 8'd0;
        end else if (ce) begin
            phase <= phase + 4'd1;
            if (phase == 4'd15) begin
                chan_sel    <= {chan_sel[2:0], chan_sel[3]};
                idx         <= idx + 2'd1;
                duty_shadow <= duty_in;
            end
        end
    end

    // P: when the mirror index points at position 0, the one-hot selector
    //    must be sitting on channel 0.
    always @(posedge clk)
        if (idx == 2'd0)
            assert (chan_sel == 4'b0001);
endmodule

module minmax_abs_track (
    input wire i_clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_push,
    input wire signed [7:0] i_val,
    output wire [7:0] o_min,
    output wire [7:0] o_max,
    output wire [3:0] o_count,
    output wire o_bad
);
    // Tracks the running min and max of the magnitudes (absolute values) of a
    // stream of signed samples, plus a saturating sample counter and a latched
    // order-violation flag.

    reg [7:0] mn;
    reg [7:0] mx;
    reg       valid;
    reg [3:0] count;
    reg       bad;

    initial mn    = 8'hff;
    initial mx    = 8'h00;
    initial valid = 1'b0;
    initial count = 4'd0;
    initial bad   = 1'b0;

    // unsigned magnitude of the signed input (|-128| == 8'h80 fits unsigned)
    wire [7:0] mag = i_val[7] ? (~i_val + 8'd1) : i_val;

    always @(posedge i_clk) begin
        if (i_rst) begin
            mn    <= 8'hff;
            mx    <= 8'h00;
            valid <= 1'b0;
            count <= 4'd0;
            bad   <= 1'b0;
        end else if (i_ce) begin
            // order checker: samples the registered extremes, gated by the
            // *counter* rather than by the valid flag
            bad <= (count != 4'd0) && (mn > mx);

            if (i_push) begin
                if (!valid) begin
                    mn <= mag;
                    mx <= mag;
                end else begin
                    if (mag < mn)
                        mn <= mag;
                    if (mag > mx)
                        mx <= mag;
                end
                valid <= 1'b1;
                count <= (count == 4'd15) ? 4'd15 : (count + 4'd1);
            end
        end
    end

    assign o_min   = mn;
    assign o_max   = mx;
    assign o_count = count;
    assign o_bad   = bad;

    // Property: once at least one sample has been absorbed, the order checker
    // must never have fired.
    always @(posedge i_clk)
        if (valid)
            assert (!bad);

endmodule

module chess_clock (
    input  wire       clk,
    input  wire       rst,
    input  wire       tick,   // enable: when low, all state is held
    input  wire       press,  // toggles which side is running
    output reg  [5:0] w_time,
    output reg  [5:0] b_time,
    output reg  [5:0] elapsed,
    output reg        turn
);
    localparam [5:0] BUDGET = 6'd16;

    // clock is frozen once either side has run out
    wire frozen = (w_time == 6'd0) || (b_time == 6'd0);

    initial w_time  = BUDGET;
    initial b_time  = BUDGET;
    initial elapsed = 6'd0;
    initial turn    = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            w_time  <= BUDGET;
            b_time  <= BUDGET;
            elapsed <= 6'd0;
            turn    <= 1'b0;
        end else if (tick && !frozen) begin
            if (turn == 1'b0)
                w_time <= w_time - 6'd1;
            else
                b_time <= b_time - 6'd1;

            elapsed <= elapsed + 6'd1;

            if (press)
                turn <= ~turn;
        end
    end

    // P: while the clock is still running, at most BUDGET*2-2 ticks can have elapsed
    always @(posedge clk)
        if (!frozen)
            assert (elapsed <= 6'd30);
endmodule

module nano_alu_flags (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [1:0] op,      // 00=ADD 01=SUB 10=AND 11=PASS/refresh
    input wire [7:0] b,
    output reg [7:0] acc,
    output reg zf,            // zero flag
    output reg nf,            // negative (sign) flag
    output reg cf             // carry flag
);

    initial begin
        acc = 8'h00;
        zf  = 1'b1;           // acc == 0 at start
        nf  = 1'b0;
        cf  = 1'b0;
    end

    wire [8:0] add_res = {1'b0, acc} + {1'b0, b};
    wire [8:0] sub_res = {1'b0, acc} - {1'b0, b};
    wire [7:0] and_res = acc & b;

    reg [7:0] res;
    reg        carry;

    always @(*) begin
        case (op)
            2'b00: begin res = add_res[7:0]; carry = add_res[8]; end
            2'b01: begin res = sub_res[7:0]; carry = sub_res[8]; end
            2'b10: begin res = and_res;      carry = 1'b0;       end
            default: begin res = acc;        carry = cf;         end // PASS
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            acc <= 8'h00;
            zf  <= 1'b1;
            nf  <= 1'b0;
            cf  <= 1'b0;
        end else if (ce) begin
            acc <= res;
            zf  <= (res == 8'h00);
            cf  <= carry;
            // sign flag is only rewritten by ops that actually change acc
            if (op != 2'b11)
                nf <= res[7];
        end
    end

    // P: the zero flag and the negative flag are never both asserted
    always @(posedge clk)
        if (zf)
            assert (!nf);

endmodule

module str_reverse_stack (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [7:0] in_char,
    output reg [7:0] out_char
);
    // Character stack used to reverse a string: chars are pushed in order and
    // popped out back-to-front.  n_pushed / n_popped are free-running mod-16
    // bookkeeping counters of how many characters entered and left the stack.
    reg [3:0] sp       = 4'd0;
    reg [3:0] n_pushed = 4'd0;
    reg [3:0] n_popped = 4'd0;
    reg [7:0] mem [0:7];

    integer i;
    initial begin
        out_char = 8'h00;
        for (i = 0; i < 8; i = i + 1) mem[i] = 8'h00;
    end

    wire full    = (sp >= 4'd8);
    wire empty   = (sp == 4'd0);
    wire do_push = push && !full;
    wire do_pop  = !do_push && pop && !empty;

    always @(posedge clk) begin
        if (rst) begin
            sp       <= 4'd0;
            n_pushed <= 4'd0;
            n_popped <= 4'd0;
            out_char <= 8'h00;
        end else if (do_push) begin
            mem[sp[2:0]] <= in_char;
            sp           <= sp + 4'd1;
            n_pushed     <= n_pushed + 4'd1;
        end else if (do_pop) begin
            out_char <= mem[sp[2:0] - 3'd1];
            sp       <= sp - 4'd1;
            n_popped <= n_popped + 4'd1;
        end
    end

    // P: whenever the character stack is empty, exactly as many characters have
    // left it as entered it.
    always @(posedge clk)
        if (sp == 4'd0)
            assert (n_pushed == n_popped);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
output reg tokens_hi,
output reg [3:0] spent_total
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;
    initial spent_total = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
            spent_total <= 4'd0;
        end else begin
            if (dec) spent_total <= spent_total + 4'd1;
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
output reg tokens_hi,
output reg [3:0] drip_count
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;
initial drip_count = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
drip_count <= 4'd0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
if (drip_en && drip_count != 4'd15) drip_count <= drip_count + 4'd1;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    reg deep;  // registered level>=3 flag, re-evaluated when the level moves
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    // burst drain: while the bucket is deep a spend sheds two tokens at once
    wire bulk = dec && deep;
    wire lite = dec && !deep;
    wire [2:0] nxt = inc  ? tokens + 3'd1 :
                     bulk ? tokens - 3'd2 :
                     lite ? tokens - 3'd1 : tokens;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;
    initial deep = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
            deep      <= 1'b0;
        end else begin
            tokens <= nxt;
            if (inc || dec) deep <= (nxt >= 3'd3);

            if (inc && tokens == 3'd1)       tokens_hi <= 1'b1;
            else if (lite && tokens == 3'd2) tokens_hi <= 1'b0;
            else if (bulk && tokens == 3'd3) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    reg pace;   // refill divider: only every other drip request is honoured
    wire drip_ok  = drip && !pace;
    wire drip_en  = drip_ok && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;
    initial pace      = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
            pace      <= 1'b0;
        end else begin
            if (drip) pace <= !pace;

            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);

    always @(posedge clk)
        if (tokens == 3'd4) assert (tokens_hi);
endmodule

module watchdog (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire kick,
    input wire ack,
    output reg fault
);
    reg [3:0] timer;
    reg [3:0] elapsed;
reg [3:0] period;
wire [3:0] period_tight = (period == 4'd4) ? 4'd4 : period - 4'd1;
wire [3:0] period_relax = (period == 4'd8) ? 4'd8 : period + 4'd1;
initial begin timer = 4'd8; elapsed = 4'd0; fault = 1'b0; period = 4'd8; end

    always @(posedge clk) begin
        if (rst) begin
            timer   <= 4'd8;
            elapsed <= 4'd0;
            fault   <= 1'b0;
period  <= 4'd8;
        end else if (i_ce) begin
            if (ack) begin
timer   <= period_tight;
period  <= period_tight;
                elapsed <= 4'd0;
                fault   <= 1'b0;
            end else if (kick && !fault) begin
timer   <= period_relax;
period  <= period_relax;
                elapsed <= 4'd0;
            end else begin
                if (timer != 4'd0)   timer   <= timer - 4'd1;
if (elapsed != period) elapsed <= elapsed + 4'd1;
                if (timer == 4'd1)   fault   <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (elapsed == 4'd8)
            assert (fault);
endmodule

module stack_hwm (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] top
);
    reg [3:0] sp;
    reg [3:0] hwm;
    reg [7:0] mem [0:15];
    reg        wb_v;
    reg [7:0]  wb_d;
    initial begin sp = 4'd0; hwm = 4'd0; wb_v = 1'b0; wb_d = 8'h00; end

    wire [3:0] occ = sp + {3'b000, wb_v};
    wire do_push = ce && push && (occ != 4'd8);
    wire do_pop  = ce && pop  && (occ != 4'd0);
    wire [3:0] nxt = occ + 4'd1;

    assign top = wb_v ? wb_d : ((sp == 4'd0) ? 8'h00 : mem[sp - 4'd1]);

    always @(posedge clk) begin
        if (rst) begin
            sp  <= 4'd0;
            hwm <= 4'd0;
            wb_v <= 1'b0;
            wb_d <= 8'h00;
        end else begin
            case ({do_push, do_pop})
                2'b10: begin
                    if (wb_v) begin
                        mem[sp] <= wb_d;
                        sp <= sp + 4'd1;
                    end
                    wb_v <= 1'b1;
                    wb_d <= din;
                    if (nxt > hwm) hwm <= nxt;
                end
                2'b01: begin
                    if (wb_v) wb_v <= 1'b0;
                    else      sp   <= sp - 4'd1;
                end
                default: if (ce && wb_v) begin
                    mem[sp] <= wb_d;
                    sp      <= sp + 4'd1;
                    wb_v    <= 1'b0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (sp == 4'd8)
            assert (hwm == 4'd8);
endmodule

module stack_hwm (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] top
);
    reg [3:0] sp;
    reg [3:0] hwm;
reg [3:0] hdrm;
    reg [7:0] mem [0:15];
initial begin sp = 4'd0; hwm = 4'd0; hdrm = 4'd8; end

    wire do_push = ce && push && (sp != 4'd8);
    wire do_pop  = ce && pop  && (sp != 4'd0);
    wire [3:0] nxt = sp + 4'd1;

// an empty stack reads back the depth status: {high-water mark, headroom}
wire [7:0] status = {hwm, hdrm};


assign top = (sp == 4'd0) ? status : mem[sp - 4'd1];

    always @(posedge clk) begin
        if (rst) begin
            sp  <= 4'd0;
            hwm <= 4'd0;
hdrm <= 4'd8;
        end else begin
            case ({do_push, do_pop})
                2'b10: begin
                    mem[sp] <= din;
                    sp <= nxt;
if (nxt > hwm) begin
    hwm <= nxt;
    // headroom shrinks with every new peak and saturates at the limit
    if (hdrm != 4'd0) hdrm <= hdrm - 4'd1;
end
                end
                2'b01: sp <= sp - 4'd1;
                default: ;
            endcase
        end
    end

    always @(posedge clk)
        if (sp == 4'd8)
            assert (hwm == 4'd8);

always @(posedge clk)
    assert ({1'b0, hwm} + {1'b0, hdrm} == 5'd8);
endmodule

module rr_arbiter_pri (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire [3:0] req,
    output wire [3:0] gnt,
    output reg  [3:0] pri,
    output reg  [1:0] idx
);
    initial pri = 4'b0001;
    initial idx = 2'd0;

   // second request port; both ports share the one grant bus via a token
   reg  [3:0] pri_b;   // port B's rotating priority pointer
   reg  [1:0] off;     // slots B's pointer sits ahead of the shared index
   reg        own;     // 0: port A drives gnt, 1: port B drives gnt
   initial pri_b = 4'b0001;
   initial off   = 2'd0;
   initial own   = 1'b0;

    // only the requester currently pointed at by the rotating priority wins
   wire [3:0] cur_pri = own ? pri_b : pri;
   assign gnt = req & cur_pri;

    wire low_pri = pri[0] | pri[1];   // priority pointer sits in lower half
    wire idx_hi  = idx[1];            // binary index says upper half

   // an owner that cannot place a grant this cycle releases the shared bus
   wire pass = ~|gnt;

    always @(posedge clk) begin
        if (rst) begin
            pri <= 4'b0001;
            idx <= 2'd0;
           pri_b <= 4'b0001;
           off   <= 2'd0;
           own   <= 1'b0;
        end else if (step) begin
           if (pass) begin
               own <= ~own;
               if (own) begin
                   // B releases: A resumes the scan where B stopped
                   pri <= pri_b;
                   idx <= idx + off;
                   off <= 2'd0;
               end else begin
                   // A releases: B picks the scan up at A's pointer
                   pri_b <= pri;
                   off   <= 2'd0;
               end
           end else if (own) begin
               // B holds the bus: only B's pointer walks, it pulls ahead
               pri_b <= {pri_b[2:0], pri_b[3]};
               off   <= off + 2'd1;
           end else begin
               // A holds the bus: A walks, closing on B's parked pointer
               pri <= {pri[2:0], pri[3]};
               idx <= idx + 2'd1;
               off <= off - 2'd1;
           end
        end
    end

    always @(posedge clk)
        if (|gnt)
            assert (!(low_pri && idx_hi));
endmodule

module rr_arbiter_pri (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire [3:0] req,
    output wire [3:0] gnt,
    output reg  [3:0] pri,
    output reg  [1:0] idx
);
    initial pri = 4'b0001;
    initial idx = 2'd0;

   reg [1:0] hold_cnt;   // cycles left in the current grant burst
   initial hold_cnt = 2'd0;

    // only the requester currently pointed at by the rotating priority wins
    assign gnt = req & pri;

    wire low_pri = pri[0] | pri[1];   // priority pointer sits in lower half
    wire idx_hi  = idx[1];            // binary index says upper half

   wire hold_active  = (hold_cnt != 2'd0);
   // a fresh grant opens a burst; the pointer moves on the last burst cycle,
   // or right away when the requester it points at has nothing pending
   wire burst_start  = (|gnt) && !hold_active;
   wire rotate       = step && ((hold_cnt == 2'd1) || (!hold_active && !(|gnt)));

    always @(posedge clk) begin
        if (rst) begin
            pri <= 4'b0001;
            idx <= 2'd0;
           hold_cnt <= 2'd0;
       end else begin
           if (rotate) begin
               pri <= {pri[2:0], pri[3]};
               idx <= idx + 2'd1;
           end
           if (burst_start)
               hold_cnt <= 2'd3;
           else if (step && hold_active)
               hold_cnt <= hold_cnt - 2'd1;
       end
    end

    always @(posedge clk)
        if (|gnt)
            assert (!(low_pri && idx_hi));

   // the binary index must always name the requester that is being granted
   always @(posedge clk)
       if (|gnt)
           assert (gnt[idx]);
endmodule

module pwm_dimmer (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] duty_in,
    output wire pwm_out
);
    reg [7:0] cnt      = 8'd0;   // free-running ramp
    reg [7:0] duty_reg = 8'd0;   // duty latched at period start
    reg [7:0] high_cnt = 8'd0;   // high-time accumulated this period
    reg       hi_q     = 1'b0;   // compare result, registered ahead of the accumulator
    reg [7:0] duty_cap = 8'd0;   // duty request captured at ramp end, after foldback clamp

    localparam [7:0] HI_LIMIT = 8'd192; // high cycles per period allowed by thermal budget

    always @(posedge clk)
        if (rst) begin
            cnt      <= 8'd0;
            duty_reg <= 8'd0;
            high_cnt <= 8'd0;
            hi_q     <= 1'b0;
            duty_cap <= 8'd0;
        end else if (ce) begin
            if (cnt == 8'd0) begin
                duty_reg <= duty_cap;
                high_cnt <= 8'd0;
                hi_q     <= (duty_cap != 8'd0);
                cnt      <= 8'd1;
            end else if (cnt == 8'hFF) begin
                duty_cap <= (high_cnt >= HI_LIMIT) ? HI_LIMIT : duty_in;
                cnt      <= 8'd0;
                high_cnt <= 8'd0;
                hi_q     <= 1'b0;
            end else begin
                cnt      <= cnt + 8'd1;
                high_cnt <= high_cnt + {7'd0, hi_q};
                hi_q     <= (cnt < duty_reg);
            end
        end

    assign pwm_out = (cnt < duty_reg);

    always @(posedge clk)
        if (pwm_out)
            assert (high_cnt < duty_reg);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module token_bucket_pool (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] drip_req,
    input  wire [5:0] spend_req,
    output reg  [3:0] pool,
    output wire [5:0] hi_flags,
    output reg        starved
);
    localparam [3:0] TOTAL = 4'd8;

    // per-instance observable state
    wire [2:0] t0, t1, t2, t3, t4, t5;
    wire       h0, h1, h2, h3, h4, h5;

    // a bucket wants a credit only if the drip would really land:
    // not already full, and not cancelled by a concurrent accepted spend
    wire [5:0] want;
    assign want[0] = drip_req[0] && (t0 != 3'd4) && !(spend_req[0] && (t0 != 3'd0));
    assign want[1] = drip_req[1] && (t1 != 3'd4) && !(spend_req[1] && (t1 != 3'd0));
    assign want[2] = drip_req[2] && (t2 != 3'd4) && !(spend_req[2] && (t2 != 3'd0));
    assign want[3] = drip_req[3] && (t3 != 3'd4) && !(spend_req[3] && (t3 != 3'd0));
    assign want[4] = drip_req[4] && (t4 != 3'd4) && !(spend_req[4] && (t4 != 3'd0));
    assign want[5] = drip_req[5] && (t5 != 3'd4) && !(spend_req[5] && (t5 != 3'd0));

    wire credit_avail = (pool != 4'd0);

    // one credit per cycle, fixed priority
    wire [5:0] grant;
    assign grant[0] = credit_avail && want[0];
    assign grant[1] = credit_avail && want[1] && !want[0];
    assign grant[2] = credit_avail && want[2] && !want[0] && !want[1];
    assign grant[3] = credit_avail && want[3] && !want[0] && !want[1] && !want[2];
    assign grant[4] = credit_avail && want[4] && !want[0] && !want[1] && !want[2] && !want[3];
    assign grant[5] = credit_avail && want[5] && !want[0] && !want[1] && !want[2] && !want[3] && !want[4];
    wire grant_any = grant[0] || grant[1] || grant[2] || grant[3] || grant[4] || grant[5];

    // a released token returns its credit
    wire [5:0] rel;
    assign rel[0] = spend_req[0] && (t0 != 3'd0) && !(grant[0] && (t0 != 3'd4));
    assign rel[1] = spend_req[1] && (t1 != 3'd0) && !(grant[1] && (t1 != 3'd4));
    assign rel[2] = spend_req[2] && (t2 != 3'd0) && !(grant[2] && (t2 != 3'd4));
    assign rel[3] = spend_req[3] && (t3 != 3'd0) && !(grant[3] && (t3 != 3'd4));
    assign rel[4] = spend_req[4] && (t4 != 3'd0) && !(grant[4] && (t4 != 3'd4));
    assign rel[5] = spend_req[5] && (t5 != 3'd0) && !(grant[5] && (t5 != 3'd4));

    wire [3:0] rel_cnt = {3'd0, rel[0]} + {3'd0, rel[1]} + {3'd0, rel[2]} +
                         {3'd0, rel[3]} + {3'd0, rel[4]} + {3'd0, rel[5]};

    token_bucket u0 (.clk(clk), .rst(rst), .drip(grant[0]), .spend(spend_req[0]), .tokens(t0), .tokens_hi(h0));
    token_bucket u1 (.clk(clk), .rst(rst), .drip(grant[1]), .spend(spend_req[1]), .tokens(t1), .tokens_hi(h1));
    token_bucket u2 (.clk(clk), .rst(rst), .drip(grant[2]), .spend(spend_req[2]), .tokens(t2), .tokens_hi(h2));
    token_bucket u3 (.clk(clk), .rst(rst), .drip(grant[3]), .spend(spend_req[3]), .tokens(t3), .tokens_hi(h3));
    token_bucket u4 (.clk(clk), .rst(rst), .drip(grant[4]), .spend(spend_req[4]), .tokens(t4), .tokens_hi(h4));
    token_bucket u5 (.clk(clk), .rst(rst), .drip(grant[5]), .spend(spend_req[5]), .tokens(t5), .tokens_hi(h5));

    assign hi_flags = {h5, h4, h3, h2, h1, h0};

    initial pool    = TOTAL;
    initial starved = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            pool    <= TOTAL;
            starved <= 1'b0;
        end else begin
            pool <= pool + rel_cnt - {3'd0, grant_any};
            if (pool == 4'd0) starved <= 1'b1;
        end
    end

    // when the pool is exhausted all credits sit in the buckets, so at least
    // one bucket must be above its high-water mark
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 || h1 || h2 || h3 || h4 || h5);
endmodule

module pwm_dimmer (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] duty_in,
    output wire pwm_out
);
    reg [7:0] cnt      = 8'd0;   // free-running ramp
    reg [7:0] duty_reg = 8'd0;   // duty latched at period start
    reg [7:0] high_cnt = 8'd0;   // high-time accumulated this period

   // compare -> accumulate path registered four deep to meet timing at the
   // top clock rate; each stage carries one pending high-time increment and
   // the last stage is the PWM output itself, so output and accumulator stay
   // aligned by construction.
   reg inc_s0 = 1'b0;
   reg inc_s1 = 1'b0;
   reg inc_s2 = 1'b0;
   reg inc_s3 = 1'b0;

    always @(posedge clk)
        if (rst) begin
            cnt      <= 8'd0;
            duty_reg <= 8'd0;
            high_cnt <= 8'd0;
           inc_s0   <= 1'b0;
           inc_s1   <= 1'b0;
           inc_s2   <= 1'b0;
           inc_s3   <= 1'b0;
        end else if (ce) begin
            if (cnt == 8'd0) begin
                duty_reg <= duty_in;
               high_cnt <= 8'd0;
               inc_s0   <= (duty_in != 8'd0);
               inc_s1   <= inc_s0;
               inc_s2   <= inc_s1;
               inc_s3   <= inc_s2;
                cnt      <= 8'd1;
            end else if (cnt == 8'hFF) begin
                cnt      <= 8'd0;
                high_cnt <= 8'd0;
               inc_s0   <= 1'b0;
               inc_s1   <= 1'b0;
               inc_s2   <= 1'b0;
               inc_s3   <= 1'b0;
            end else begin
                cnt      <= cnt + 8'd1;
               high_cnt <= high_cnt + (inc_s3 ? 8'd1 : 8'd0);
               inc_s0   <= (cnt < duty_reg);
               inc_s1   <= inc_s0;
               inc_s2   <= inc_s1;
               inc_s3   <= inc_s2;
            end
        end

   assign pwm_out = inc_s3;

    always @(posedge clk)
        if (pwm_out)
            assert (high_cnt < duty_reg);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] rd_data,
    output reg  [3:0] wr_addr,
    output reg  [3:0] remaining,
    output reg  [7:0] wr_data,
    output wire       done
);
    localparam [3:0] TOTAL = 4'd8;

    initial wr_addr   = 4'd0;
    initial remaining = TOTAL;
    initial wr_data   = 8'h00;

    assign done = (remaining == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            wr_addr   <= 4'd0;
            remaining <= TOTAL;
            wr_data   <= 8'h00;
        end else if (ce && remaining != 4'd0) begin
            wr_addr   <= wr_addr + 4'd1;
            remaining <= remaining - 4'd1;
            wr_data   <= rd_data;
        end
    end

    // P: while the block copy is still in flight, the write pointer must stay
    // inside the destination block (0..7).
    always @(posedge clk)
        if (!done)
            assert (wr_addr <= 4'd7);
endmodule

// Top level: a token-bucket rate limiter feeds a burst queue which drives the
// DMA copier one beat at a time.  The queue holds a whole burst's worth of
// beats plus the source word latched when the burst was granted.
module bucket_dma_top (
    input  wire       clk,
    input  wire       rst,
    input  wire       drip,
    input  wire       run,
    input  wire [7:0] src_data,
    output wire [2:0] tokens,
    output wire       tokens_hi,
    output wire [3:0] wr_addr,
    output wire [3:0] remaining,
    output wire [7:0] wr_data,
    output wire       done,
    output reg  [2:0] pending
);
    reg [7:0] hold;

    initial pending = 3'd0;
    initial hold    = 8'h00;

    // One beat leaves the queue per enabled cycle; each beat also spends a
    // token out of the bucket.
    wire beat = run && (pending != 3'd0) && (remaining != 4'd0);

    // A fresh burst is granted only when the bucket is above its low-water
    // mark, the queue has drained, and the block copy is still in flight.
    wire load = tokens_hi && (pending == 3'd0) && (remaining != 4'd0);

    // Grant no more beats than either the bucket or the destination block can
    // support.
    wire [2:0] grant = (remaining < {1'b0, tokens}) ? remaining[2:0] : tokens;

    always @(posedge clk) begin
        if (rst) begin
            pending <= 3'd0;
            hold    <= 8'h00;
        end else if (load) begin
            pending <= grant;
            hold    <= src_data;
        end else if (beat) begin
            pending <= pending - 3'd1;
        end
    end

    token_bucket u_bucket (
        .clk       (clk),
        .rst       (rst),
        .drip      (drip),
        .spend     (beat),
        .tokens    (tokens),
        .tokens_hi (tokens_hi)
    );

    dma_copier u_dma (
        .clk       (clk),
        .rst       (rst),
        .ce        (beat),
        .rd_data   (hold),
        .wr_addr   (wr_addr),
        .remaining (remaining),
        .wr_data   (wr_data),
        .done      (done)
    );

    // Composed property: any beat still sitting in the burst queue must have
    // somewhere left to land in the destination block.
    always @(posedge clk)
        if (pending != 3'd0)
            assert (remaining != 4'd0);
endmodule

module thermo_hyst (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output reg        heat_on,
    output reg [2:0]  on_events,
    output reg [2:0]  off_events
);
    localparam [5:0] T_LOW  = 6'd20;
    localparam [5:0] T_HIGH = 6'd40;

    reg [5:0] temp;

    initial begin
        temp       = 6'd30;
        heat_on    = 1'b0;
        on_events  = 3'd0;
        off_events = 3'd0;
    end

    // hysteresis decisions
    wire turn_on  = ce && !heat_on && (temp <= T_LOW);
    wire turn_off = ce &&  heat_on && (temp >= T_HIGH);

    always @(posedge clk) begin
        if (rst) begin
            temp       <= 6'd30;
            heat_on    <= 1'b0;
            on_events  <= 3'd0;
            off_events <= 3'd0;
        end else if (ce) begin
            if (turn_on) begin
                heat_on   <= 1'b1;
                on_events <= on_events + 3'd1;
            end else if (turn_off) begin
                heat_on    <= 1'b0;
                off_events <= off_events + 3'd1;
            end

            // plant: heater warms, ambient cools
            if (heat_on) begin
                if (temp != 6'd63) temp <= temp + 6'd1;
            end else begin
                if (temp != 6'd0)  temp <= temp - 6'd1;
            end
        end
    end

    // P: whenever the heater is commanded on, strictly more on-events than
    // off-events have been logged, so the two event counters cannot agree.
    always @(posedge clk)
        if (heat_on)
            assert (on_events != off_events);

endmodule

module thermo_farm (
    input  wire       clk,
    input  wire       rst,
    input  wire [3:0] ce_req,
    output reg  [3:0] pool,
    output wire [3:0] heat_on_o,
    output wire [3:0] held_o
);
    localparam [3:0] TOTAL = 4'd4;

    // per-instance observable signals
    wire       h0, h1, h2, h3;
    wire [2:0] on0, on1, on2, on3;
    wire [2:0] off0, off1, off2, off3;

    wire [3:0] heat_v = {h3, h2, h1, h0};

    // registered mirror of which instances currently hold a credit
    reg [3:0] held;

    wire t0 = held[0];
    wire t1 = held[1];
    wire t2 = held[2];
    wire t3 = held[3];

    initial begin
        pool = TOTAL;
        held = 4'd0;
    end

    // credit accounting: a rising heater takes a credit, a falling one returns it
    wire [3:0] acq = heat_v & ~held;
    wire [3:0] rel = ~heat_v & held;

    wire [2:0] n_acq = {2'b00, acq[0]} + {2'b00, acq[1]} +
                       {2'b00, acq[2]} + {2'b00, acq[3]};
    wire [2:0] n_rel = {2'b00, rel[0]} + {2'b00, rel[1]} +
                       {2'b00, rel[2]} + {2'b00, rel[3]};

    wire [3:0] pool_nxt = pool + {1'b0, n_rel} - {1'b0, n_acq};

    // only an idle heater needs a credit; one-hot priority grant
    wire [3:0] want = ce_req & ~heat_v;
    wire [3:0] gnt;
    assign gnt[0] = want[0];
    assign gnt[1] = want[1] & ~want[0];
    assign gnt[2] = want[2] & ~want[1] & ~want[0];
    assign gnt[3] = want[3] & ~want[2] & ~want[1] & ~want[0];

    wire avail = (pool_nxt != 4'd0);

    // running heaters keep their enable so they can release; idle ones need a grant
    wire [3:0] ce_gated = (ce_req & heat_v) | (gnt & {4{avail}});

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
            held <= 4'd0;
        end else begin
            pool <= pool_nxt;
            held <= heat_v;
        end
    end

    thermo_hyst u0 (
        .clk(clk), .rst(rst), .ce(ce_gated[0]),
        .heat_on(h0), .on_events(on0), .off_events(off0)
    );
    thermo_hyst u1 (
        .clk(clk), .rst(rst), .ce(ce_gated[1]),
        .heat_on(h1), .on_events(on1), .off_events(off1)
    );
    thermo_hyst u2 (
        .clk(clk), .rst(rst), .ce(ce_gated[2]),
        .heat_on(h2), .on_events(on2), .off_events(off2)
    );
    thermo_hyst u3 (
        .clk(clk), .rst(rst), .ce(ce_gated[3]),
        .heat_on(h3), .on_events(on3), .off_events(off3)
    );

    assign heat_on_o = heat_v;
    assign held_o    = held;

    // Pool property: a completely free budget means nobody is recorded as holding.
    always @(posedge clk)
        if (pool == 4'd4)
            assert (!t0 && !t1 && !t2 && !t3);

endmodule

module alu_budget (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire [7:0] i_step,
    output wire [7:0] o_acc,
    output wire o_zero,
    output wire o_full
);
    localparam [7:0] LIMIT = 8'd200;

    reg [7:0] acc;   // accumulated result
    reg [7:0] rem;   // headroom credited to the accumulator
    reg [7:0] acc_b; // secondary channel accumulation
    reg       turn;  // round-robin owner of the shared credit pool
    initial acc = 8'd0;
    initial rem = LIMIT;
    initial acc_b = 8'd0;
    initial turn = 1'b0;

    wire grant = i_ce && (rem >= i_step);

    always @(posedge clk)
        if (rst) begin
            acc <= 8'd0;
            rem <= LIMIT;
            acc_b <= 8'd0;
            turn <= 1'b0;
        end else if (grant) begin
            rem  <= rem - i_step;
            turn <= ~turn;
            if (turn) acc_b <= acc_b + i_step;
            else      acc   <= acc   + i_step;
        end

    assign o_acc  = acc;
    assign o_zero = (acc == 8'd0) && (acc_b == 8'd0);
    assign o_full = (rem == 8'd0);

    // P: a nonzero accumulation never exceeds its saturation bound
    always @(*)
        if (!o_zero) assert (acc <= LIMIT);
endmodule

// Two-road intersection controller.
// Light codes: 0 = RED, 1 = GREEN, 2 = YELLOW
// Phases: 0 NS-green, 1 NS-yellow, 2 all-red, 3 EW-green, 4 EW-yellow, 5 all-red
// Each phase handover advances the affected road's light one step around the
// RED -> GREEN -> YELLOW -> RED ring.
module intersection_ctrl (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output wire       o_ns_green,
    output wire       o_ew_green,
    output wire [2:0] o_phase
);
    localparam [1:0] RED    = 2'd0;
    localparam [1:0] GREEN  = 2'd1;
    localparam [1:0] YELLOW = 2'd2;

    localparam [2:0] PHASE_LEN = 3'd4;
   // clearance (all-red) intervals are held longer than the coloured phases
   localparam [2:0] CLEAR_LEN = 3'd6;

    reg [2:0] phase;
    reg [2:0] timer;
    reg [1:0] ns_state;
    reg [1:0] ew_state;

    initial phase    = 3'd0;
    initial timer    = PHASE_LEN;
    initial ns_state = GREEN;
    initial ew_state = RED;

    // one step around the three-colour ring
    function [1:0] nextcolor;
        input [1:0] c;
        begin
            if (c == YELLOW)
                nextcolor = RED;
            else
                nextcolor = c + 2'd1;
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            phase    <= 3'd0;
            timer    <= PHASE_LEN;
            ns_state <= GREEN;
            ew_state <= RED;
        end else if (ce) begin
            if (timer != 3'd0) begin
                timer <= timer - 3'd1;
            end else begin
               // a handover into an all-red clearance phase gets the long interval
               timer <= ((phase == 3'd1) || (phase == 3'd4)) ? CLEAR_LEN : PHASE_LEN;
                case (phase)
                3'd0: begin // NS green expires -> NS yellow
                    phase    <= 3'd1;
                    ns_state <= nextcolor(ns_state);
                end
                3'd1: begin // NS yellow expires -> all red
                    phase    <= 3'd2;
                    ns_state <= nextcolor(ns_state);
                end
                3'd2: begin // all red -> EW green
                    phase    <= 3'd3;
                    ew_state <= nextcolor(ew_state);
                end
                3'd3: begin // EW green expires -> EW yellow
                    phase    <= 3'd4;
                    ew_state <= nextcolor(ew_state);
                end
                3'd4: begin // EW yellow expires -> all red
                    phase    <= 3'd5;
                    ew_state <= nextcolor(ew_state);
                end
                3'd5: begin // all red -> NS green
                    phase    <= 3'd0;
                    ns_state <= nextcolor(ns_state);
                end
                default: begin
                    phase <= phase;
                end
                endcase
            end
        end
    end

    assign o_ns_green = (ns_state == GREEN);
    assign o_ew_green = (ew_state == GREEN);
    assign o_phase    = phase;

    // P: the two roads are never green at the same time
    always @(*)
        if (ns_state == GREEN)
            assert (ew_state != GREEN);

   // Q: during the all-red clearance phases neither road may show green
   always @(posedge clk)
       if (phase == 3'd2 || phase == 3'd5)
           assert ((ns_state != GREEN) && (ew_state != GREEN));
endmodule

module rot_shadow (
    input wire clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_load,
    input wire [15:0] i_data,
    output wire [15:0] o_word,
    output wire [15:0] o_shadow
);
    reg [15:0] word   = 16'h0000;
    reg [15:0] shadow = 16'h0000;
    reg [3:0]  amt    = 4'd0;

   // rotate lookahead pipeline: stage k holds the shadow value that is due
   // k+1 rotations from now, so o_shadow is driven straight off a register
   // and the rot-by-1 producer sits four stages upstream of the consumer
   reg [15:0] rot_p0 = 16'h0000;
   reg [15:0] rot_p1 = 16'h0000;
   reg [15:0] rot_p2 = 16'h0000;
   reg [15:0] rot_p3 = 16'h0000;

    always @(posedge clk)
        if (i_rst) begin
            word   <= 16'h0000;
            shadow <= 16'h0000;
            amt    <= 4'd0;
           rot_p0 <= 16'h0000;
           rot_p1 <= 16'h0000;
           rot_p2 <= 16'h0000;
           rot_p3 <= 16'h0000;
        end else if (i_ce) begin
            if (i_load) begin
                word   <= i_data;
                shadow <= i_data;
                amt    <= 4'd0;
               rot_p0 <= { i_data[14:0], i_data[15]   };
               rot_p1 <= { i_data[13:0], i_data[15:14] };
               rot_p2 <= { i_data[12:0], i_data[15:13] };
               rot_p3 <= { i_data[11:0], i_data[15:12] };
            end else begin
               shadow <= rot_p0;
               rot_p0 <= rot_p1;
               rot_p1 <= rot_p2;
               rot_p2 <= rot_p3;
               rot_p3 <= { rot_p3[14:0], rot_p3[15] };
                amt    <= amt + 4'd1;
            end
        end

    assign o_word   = word;
    assign o_shadow = shadow;

    always @(*)
        if (amt == 4'd0)
            assert (shadow == word);
endmodule

module alu_accum_slice (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire       i_sub,
    output reg  [7:0] o_result,
    output wire       o_zero
);
    reg [6:0] half;
reg [7:0] stg_res;   // ALU result in flight, written back next cycle
reg       stg_sub;   // direction latched alongside the in-flight result
reg       stg_vld;   // a writeback is pending


    initial o_result = 8'd0;
    initial half     = 7'd0;
initial stg_res  = 8'd0;
initial stg_sub  = 1'b0;
initial stg_vld  = 1'b0;

    assign o_zero = (o_result == 8'd0);

// back-to-back requests must accumulate on top of the in-flight result
wire [7:0] acc_src = stg_vld ? stg_res : o_result;

    always @(posedge clk) begin
        if (rst) begin
            o_result <= 8'd0;
            half     <= 7'd0;
stg_res  <= 8'd0;
stg_sub  <= 1'b0;
stg_vld  <= 1'b0;
end else begin
stg_vld <= i_ce;
if (i_ce) begin
stg_res <= i_sub ? (acc_src - 8'd2) : (acc_src + 8'd2);
stg_sub <= i_sub;
end
if (stg_vld) begin
o_result <= stg_res;
half     <= stg_sub ? (half - 7'd1) : (half + 7'd1);
end
        end
    end

    // P: whenever the half-step tracker is at zero, the registered ALU result is zero
    always @(posedge clk)
        if (half == 7'd0)
            assert (o_result == 8'd0);
endmodule

module lfsr_shadow_capture (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_cap,
    output wire [7:0] o_rand,
    output wire [7:0] o_shadow,
    output wire       o_shadow_valid
);
    // maximal-length 8-bit LFSR, taps at 8,6,5,4 (x^8 + x^6 + x^5 + x^4 + 1)
    reg [7:0] lfsr;
   reg [7:0] lfsr_b;
    reg [7:0] shadow;
    reg       shadow_valid;
   reg [1:0] ch_en;   // capture mixer channel enables: bit0 = gen A, bit1 = gen B

    initial lfsr         = 8'h01;
   initial lfsr_b       = 8'hA5;
    initial shadow       = 8'h00;
    initial shadow_valid = 1'b0;
   initial ch_en        = 2'b01;

    wire fb = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];
   wire fb_b = lfsr_b[7] ^ lfsr_b[5] ^ lfsr_b[4] ^ lfsr_b[3];
   // shared capture port: XOR of whichever generator channels are enabled
   wire [7:0] sample = (ch_en[0] ? lfsr : 8'h00) ^ (ch_en[1] ? lfsr_b : 8'h00);

    always @(posedge i_clk) begin
        if (i_rst) begin
            lfsr <= 8'h01;
           lfsr_b <= 8'hA5;
        end else if (i_ce) begin
            lfsr <= { lfsr[6:0], fb };
           lfsr_b <= { lfsr_b[6:0], fb_b };
        end
    end

    // shadow register: snapshots the generator output on request
    always @(posedge i_clk) begin
        if (i_rst) begin
            shadow       <= 8'h00;
            shadow_valid <= 1'b0;
           ch_en        <= 2'b01;
        end else if (i_ce && i_cap) begin
           shadow       <= sample;
            shadow_valid <= 1'b1;
           // round-robin the shared port: gen A, gen B, then both mixed
           ch_en        <= (ch_en == 2'b01) ? 2'b10 :
                           (ch_en == 2'b10) ? 2'b11 : 2'b01;
        end
    end

    assign o_rand         = lfsr;
    assign o_shadow       = shadow;
    assign o_shadow_valid = shadow_valid;

    // P: once a sample has been latched, it can never be the lockup word
    always @(*)
        if (shadow_valid)
            assert (shadow != 8'h00);
endmodule

module stack_xor (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [3:0] data,
    output reg [2:0] sp,
    output reg [3:0] xor_acc
);
    reg [3:0] m0, m1, m2, m3;
    reg [2:0] sp_b;
    initial begin sp = 0; xor_acc = 0; m0 = 0; m1 = 0; m2 = 0; m3 = 0; sp_b = 0; end

    wire [3:0] used = {1'b0, sp} + {1'b0, sp_b};
    wire do_push = push && !pop && (used != 4'd4);
    wire do_pop  = pop  && !push && (sp != 3'd0);
    wire do_a2b  = push && pop && (sp != 3'd0);
    wire do_b2a  = push && pop && (sp == 3'd0) && (sp_b != 3'd0);
    wire [3:0] top = (sp == 3'd1) ? m0 : (sp == 3'd2) ? m1 : (sp == 3'd3) ? m2 : m3;
    wire [3:0] b_top = (sp_b == 3'd1) ? m3 : (sp_b == 3'd2) ? m2 : (sp_b == 3'd3) ? m1 : m0;

    always @(posedge clk) begin
        if (rst) begin
            sp <= 3'd0;
            sp_b <= 3'd0;
            xor_acc <= 4'd0;
        end else if (do_push) begin
            case (sp)
                3'd0:    m0 <= data;
                3'd1:    m1 <= data;
                3'd2:    m2 <= data;
                default: m3 <= data;
            endcase
            sp <= sp + 3'd1;
            xor_acc <= xor_acc ^ data;
        end else if (do_pop) begin
            sp <= sp - 3'd1;
            xor_acc <= xor_acc ^ top;
        end else if (do_a2b) begin
            case (sp_b)
                3'd0:    m3 <= top;
                3'd1:    m2 <= top;
                3'd2:    m1 <= top;
                default: m0 <= top;
            endcase
            sp   <= sp - 3'd1;
            sp_b <= sp_b + 3'd1;
            xor_acc <= xor_acc ^ top;
        end else if (do_b2a) begin
            m0 <= b_top;
            sp <= 3'd1;
            sp_b <= sp_b - 3'd1;
            xor_acc <= xor_acc ^ b_top;
        end
    end

    always @(posedge clk)
        if (sp == 3'd0)
            assert (xor_acc == 4'd0);
endmodule

module prio_pipe (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] req,
    output reg b_valid,
    output reg [2:0] b_idx
);
    reg [7:0] a_vec;
    reg       a_valid;
    reg [7:0] b_vec;
   reg [2:0] s_idx;    // runner-up index into the vector held at the grant port
   reg       s_valid;  // a runner-up grant is pending for that vector

    initial begin
        a_vec = 8'h00; a_valid = 1'b0;
        b_vec = 8'h00; b_idx = 3'd0; b_valid = 1'b0;
       s_idx = 3'd0; s_valid = 1'b0;
    end

    // combinational priority encode of the stage-1 vector (default index 0)
    wire [2:0] a_idx = a_vec[7] ? 3'd7 :
                       a_vec[6] ? 3'd6 :
                       a_vec[5] ? 3'd5 :
                       a_vec[4] ? 3'd4 :
                       a_vec[3] ? 3'd3 :
                       a_vec[2] ? 3'd2 :
                       a_vec[1] ? 3'd1 : 3'd0;

   // second-pass encode: strip the winning bit, encode the next-highest request
   wire [7:0] a_rem  = a_vec & ~(8'h01 << a_idx);
   wire [2:0] a2_idx = a_rem[7] ? 3'd7 :
                       a_rem[6] ? 3'd6 :
                       a_rem[5] ? 3'd5 :
                       a_rem[4] ? 3'd4 :
                       a_rem[3] ? 3'd3 :
                       a_rem[2] ? 3'd2 :
                       a_rem[1] ? 3'd1 : 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            a_vec <= 8'h00; a_valid <= 1'b0;
            b_vec <= 8'h00; b_idx <= 3'd0; b_valid <= 1'b0;
           s_idx <= 3'd0; s_valid <= 1'b0;
        end else if (ce) begin
            a_vec   <= req;
            a_valid <= (req != 8'h00);
           if (a_valid) begin
               // stage-1 winner owns the grant port; queue its runner-up
               b_vec   <= a_vec;
               b_idx   <= a_idx;
               b_valid <= 1'b1;
               s_idx   <= a2_idx;
               s_valid <= (a_rem != 8'h00);
           end else if (s_valid) begin
               // grant port would idle: reissue held vector with runner-up index
               b_idx   <= s_idx;
               b_valid <= 1'b1;
               s_idx   <= 3'd0;
               s_valid <= 1'b0;
           end else begin
               b_vec   <= 8'h00;
               b_idx   <= 3'd0;
               b_valid <= 1'b0;
           end
        end
    end

    always @(posedge clk)
        if (b_valid)
            assert (b_vec[b_idx]);
endmodule

module ring_occ (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    output reg  [2:0] count,
    output reg  [3:0] occ
);
    reg [1:0] wptr, rptr;
   reg [1:0] bwptr, brptr;
   reg [2:0] bcount;
   reg [3:0] bocc;
   reg [2:0] credit;
   reg       sel, psel;
    initial begin wptr = 2'd0; rptr = 2'd0; count = 3'd0; occ = 4'b0000; end
   initial begin bwptr = 2'd0; brptr = 2'd0; bcount = 3'd0; bocc = 4'b0000; credit = 3'd4; sel = 1'b0; psel = 1'b0; end

   wire push_ok = push && (credit != 3'd0);
   wire do_push = push_ok && !sel;
   wire push_b  = push_ok &&  sel;
   wire pop_b   = pop && bocc[brptr] && (psel || (count == 3'd0));
   wire do_pop  = pop && (count != 3'd0) && !pop_b;

    wire [3:0] set_bit = do_push ? (4'b0001 << wptr) : 4'b0000;
    wire [3:0] clr_bit = do_pop  ? (4'b0001 << rptr) : 4'b0000;
   wire [3:0] bset_bit = push_b ? (4'b0001 << bwptr) : 4'b0000;
   wire [3:0] bclr_bit = pop_b  ? (4'b0001 << brptr) : 4'b0000;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
            occ   <= 4'b0000;
           bwptr  <= 2'd0;
           brptr  <= 2'd0;
           bcount <= 3'd0;
           bocc   <= 4'b0000;
           credit <= 3'd4;
           sel    <= 1'b0;
           psel   <= 1'b0;
        end else begin
            if (do_push) wptr <= wptr + 2'd1;
            if (do_pop)  rptr <= rptr + 2'd1;
            occ <= (occ | set_bit) & ~clr_bit;
            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase
           if (push_b) bwptr <= bwptr + 2'd1;
           if (pop_b)  brptr <= brptr + 2'd1;
           bocc <= (bocc | bset_bit) & ~bclr_bit;
           case ({push_b, pop_b})
               2'b10:   bcount <= bcount + 3'd1;
               2'b01:   bcount <= bcount - 3'd1;
               default: bcount <= bcount;
           endcase
           case ({push_ok, do_pop || pop_b})
               2'b10:   credit <= credit - 3'd1;
               2'b01:   credit <= credit + 3'd1;
               default: credit <= credit;
           endcase
           if (push_ok) sel <= ~sel;
           if (do_pop)     psel <= 1'b1;
           else if (pop_b) psel <= 1'b0;
        end
    end

    always @(posedge clk)
        if (count == 3'd1)
            assert (occ == 4'b0001 || occ == 4'b0010 ||
                    occ == 4'b0100 || occ == 4'b1000);
endmodule

module vend_credit (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_dime,
    output wire o_dispense,
    output wire [5:0] o_change
);
    reg [3:0] units = 0;      // credit in 5-cent units
reg [3:0] cred_tens = 0;  // credit in cents, tens BCD digit (display)
reg [3:0] cred_ones = 0;  // credit in cents, ones BCD digit (display)
    reg       dispense = 0;
    reg [5:0] change = 0;

    wire [3:0] inc_u = i_dime ? 4'd2  : 4'd1;
    wire [5:0] inc_c = i_dime ? 6'd10 : 6'd5;
    wire [3:0] nu = units + inc_u;
wire [7:0] cred_c    = cred_tens * 8'd10 + cred_ones;
wire [7:0] nc        = cred_c + inc_c;
// BCD carry propagation when the coin is just added to the credit
wire [4:0] ones_sum  = cred_ones + (i_dime ? 4'd0 : 4'd5);
wire       ones_cy   = (ones_sum >= 5'd10);
wire [3:0] ones_next = ones_cy ? (ones_sum - 5'd10) : ones_sum[3:0];
wire [3:0] tens_next = cred_tens + (i_dime ? 4'd1 : 4'd0) + ones_cy;
// leftover credit after a 25c vend, renormalised back into BCD
wire [7:0] rem       = nc - 8'd25;
wire       rem_cy    = (rem >= 8'd10);
wire [3:0] rem_tens  = rem_cy ? 4'd1 : 4'd0;
wire [3:0] rem_ones  = rem_cy ? (rem[3:0] - 4'd10) : rem[3:0];

    always @(posedge clk)
        if (i_reset) begin
            units    <= 4'd0;
cred_tens <= 4'd0;
cred_ones <= 4'd0;
            dispense <= 1'b0;
            change   <= 6'd0;
        end else if (i_ce) begin
            if (nu >= 4'd5) begin
                units    <= nu - 4'd5;
cred_tens <= rem_tens;
cred_ones <= rem_ones;
change    <= rem[5:0];
                dispense <= 1'b1;
            end else begin
                units    <= nu;
cred_tens <= tens_next;
cred_ones <= ones_next;
                dispense <= 1'b0;
            end
        end

    assign o_dispense = dispense;
    assign o_change   = change;

    always @(posedge clk)
        if (dispense) assert (change <= 6'd5);
endmodule

module token_bucket (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire req,
    input  wire drip,
    output wire grant
);
    reg [3:0] tokens = 4'd8;   // tokens currently in the bucket
    reg [3:0] free   = 4'd0;   // room left in the bucket (shadow accounting)
    reg [3:0] cap    = 4'd8;   // current burst allowance (adaptive capacity)

    wire spend   = ce && req  && (tokens != 4'd0);
    wire refill  = ce && drip && (free   != 4'd0);
    // starved: a request found the bucket empty, so hand a retired slot back
    wire restore = ce && req && (tokens == 4'd0) && (cap != 4'd8);
    // fully idle with room going unused: retire one slot of allowance
    wire reclaim = ce && !req && !drip && (free != 4'd0) && (cap != 4'd4);

    assign grant = spend;

    always @(posedge clk) begin
        if (rst) begin
            tokens <= 4'd8;
            free   <= 4'd0;
            cap    <= 4'd8;
        end else begin
            tokens <= tokens - spend + refill;
            free   <= free   + spend - refill + restore - reclaim;
            cap    <= cap    + restore - reclaim;
        end
    end

    // P: if the bucket is not completely full, at least one slot's worth of
    // tokens is missing, so occupancy cannot exceed CAP-1.
    always @(posedge clk)
        if (free != 4'd0)
            assert (tokens <= 4'd7);
endmodule

module sorted_pair (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire ins,
    input wire rem,
    input wire [7:0] val,
    output reg [1:0] count
);
    reg [7:0] e0, e1, max_shadow;
reg [7:0] sh;
reg sh_v;
initial begin count = 2'd0; e0 = 8'd0; e1 = 8'd0; max_shadow = 8'd0; sh = 8'd0; sh_v = 1'b0; end

wire do_fin = i_ce && sh_v;
wire do_ins = i_ce && ins && !rem && !sh_v && (count != 2'd2);
wire do_rem = i_ce && rem && !ins && !sh_v && (count != 2'd0);

    always @(posedge clk) begin
        if (rst) begin
            count <= 2'd0; e0 <= 8'd0; e1 <= 8'd0; max_shadow <= 8'd0;
sh <= 8'd0; sh_v <= 1'b0;
end else if (do_fin) begin
count <= count + 2'd1;
e1 <= sh;  max_shadow <= sh;  sh_v <= 1'b0;
end else if (do_ins) begin
            if (count == 2'd0) begin
count <= count + 2'd1;
                e0 <= val;  max_shadow <= val;
            end else if (val >= e0) begin
count <= count + 2'd1;
                e1 <= val;  max_shadow <= val;
            end else begin
e0 <= val;  max_shadow <= val;  sh <= e0;  sh_v <= 1'b1;
            end
        end else if (do_rem) begin
            count <= count - 2'd1;
            if (count == 2'd2) e0 <= e1;
        end
    end

    always @(posedge clk)
        if (count == 2'd1)
            assert (max_shadow == e0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] rd_data,
    output reg  [3:0] wr_addr,
    output reg  [3:0] remaining,
    output reg  [7:0] wr_data,
    output wire       done
);
    localparam [3:0] TOTAL = 4'd8;

    initial wr_addr   = 4'd0;
    initial remaining = TOTAL;
    initial wr_data   = 8'h00;

    assign done = (remaining == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            wr_addr   <= 4'd0;
            remaining <= TOTAL;
            wr_data   <= 8'h00;
        end else if (ce && remaining != 4'd0) begin
            wr_addr   <= wr_addr + 4'd1;
            remaining <= remaining - 4'd1;
            wr_data   <= rd_data;
        end
    end

    // P: while the block copy is still in flight, the write pointer must stay
    // inside the destination block (0..7).
    always @(posedge clk)
        if (!done)
            assert (wr_addr <= 4'd7);
endmodule

// Top level: a token-bucket rate limiter feeds a burst queue which drives the
// DMA copier one beat at a time.  The queue holds a whole burst's worth of
// beats plus the source word latched when the burst was granted.
module bucket_dma_top (
    input  wire       clk,
    input  wire       rst,
    input  wire       drip,
    input  wire       run,
    input  wire [7:0] src_data,
    output wire [2:0] tokens,
    output wire       tokens_hi,
    output wire [3:0] wr_addr,
    output wire [3:0] remaining,
    output wire [7:0] wr_data,
    output wire       done,
    output reg  [2:0] pending
);
    reg [7:0] hold;
   reg [7:0] wbeat_d;
   reg       wbeat_v;

    initial pending = 3'd0;
    initial hold    = 8'h00;
   initial wbeat_v = 1'b0;
   initial wbeat_d = 8'h00;

    // One beat leaves the queue per enabled cycle; each beat also spends a
   // token out of the bucket.  A beat is first captured in the write-beat
   // stage and is retired into the copier on the following enabled cycle,
   // so the stage must be free before the queue may issue again.
   wire beat   = run && (pending != 3'd0) && (remaining != 4'd0) && !wbeat_v;
   wire commit = run && wbeat_v;

    // A fresh burst is granted only when the bucket is above its low-water
    // mark, the queue has drained, and the block copy is still in flight.
   wire load = tokens_hi && (pending == 3'd0) && !wbeat_v && (remaining != 4'd0);

    // Grant no more beats than either the bucket or the destination block can
    // support.
    wire [2:0] grant = (remaining < {1'b0, tokens}) ? remaining[2:0] : tokens;

    always @(posedge clk) begin
        if (rst) begin
            pending <= 3'd0;
            hold    <= 8'h00;
           wbeat_v <= 1'b0;
           wbeat_d <= 8'h00;
       end else begin
           if (load) begin
            pending <= grant;
            hold    <= src_data;
           end else if (beat) begin
            pending <= pending - 3'd1;
           end
           // Write-beat pipeline stage: holds the in-flight beat until the
           // copier is enabled again.
           wbeat_v <= beat || (wbeat_v && !commit);
           if (beat) wbeat_d <= hold;
       end
    end

    token_bucket u_bucket (
        .clk       (clk),
        .rst       (rst),
        .drip      (drip),
       .spend     (commit),
        .tokens    (tokens),
        .tokens_hi (tokens_hi)
    );

    dma_copier u_dma (
        .clk       (clk),
        .rst       (rst),
       .ce        (commit),
       .rd_data   (wbeat_d),
        .wr_addr   (wr_addr),
        .remaining (remaining),
        .wr_data   (wr_data),
        .done      (done)
    );

    // Composed property: any beat still sitting in the burst queue must have
    // somewhere left to land in the destination block.
    always @(posedge clk)
        if (pending != 3'd0)
            assert (remaining != 4'd0);
endmodule

module gray_cdc_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output reg  [3:0] gray
);
    // shadow binary counter
    reg [3:0] bin;
    // previous emitted gray value, and a sticky flag saying one step happened
    reg [3:0] gray_prev;
    reg       changed;
    // running parity of the emitted gray word, kept incrementally
    reg       par;

    initial bin       = 4'd0;
    initial gray      = 4'b0000;
    initial gray_prev = 4'b0000;
    initial changed   = 1'b0;
    initial par       = 1'b0;

    wire [3:0] bin_nxt  = bin + 4'd1;
    // Gray increment performed on the gray word itself: with an even number
    // of ones toggle bit 0, otherwise toggle the bit left of the rightmost
    // one (wrapping onto the MSB at the end of the sequence). par supplies
    // the ones-parity so it never has to be recomputed from gray.
    wire [3:0] gray_lsb1 = gray & (~gray + 4'd1);
    wire [3:0] gray_shl  = {gray_lsb1[2:0], 1'b0};
    wire [3:0] gray_tog  = par ? ((gray_shl == 4'b0000) ? 4'b1000 : gray_shl)
                               : 4'b0001;
    wire [3:0] gray_nxt  = gray ^ gray_tog;

    always @(posedge clk) begin
        if (rst) begin
            bin       <= 4'd0;
            gray      <= 4'b0000;
            gray_prev <= 4'b0000;
            changed   <= 1'b0;
            par       <= 1'b0;
        end else if (step) begin
            bin       <= bin_nxt;
            gray      <= gray_nxt;
            gray_prev <= gray;
            changed   <= 1'b1;
            par       <= ~par;
        end
    end

    // P: once a step has been taken, the current and previous gray words
    //    differ in exactly one bit (safe for clock-domain crossing).
    wire [3:0] diff = gray ^ gray_prev;

    always @(posedge clk) begin
        if (changed)
            assert ((diff != 4'b0000) && ((diff & (diff - 4'd1)) == 4'b0000));
    end

    // Q: the top gray bit tracks the top binary bit, so it can be used as a
    //    half-full flag without decoding the gray word.
    always @(posedge clk)
        assert (gray[3] == bin[3]);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    reg deep;  // registered level>=3 flag, re-evaluated when the level moves
   // reserve slot: drips that arrive while the bucket is already deep park here
   reg [1:0] resv;
   wire [2:0] level = tokens + {1'b0, resv};
   wire drip_en  = drip  && (level != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

   // a deep bucket diverts fresh drips into the reserve instead of raising the level
   wire park = inc && deep && (resv != 2'd2);
   wire fill = inc && !park;
   // burst drain: while the bucket is deep a spend sheds two tokens at once; the
   // second one is taken from the reserve whenever the reserve is holding something
   wire bulk  = dec && deep && (resv == 2'd0);
   wire drain = dec && deep && (resv != 2'd0);
   wire lite  = dec && !bulk;
   // the reserve folds back into the bucket once the level is no longer deep
   wire refill = !inc && !dec && !deep && (resv != 2'd0);
   wire [2:0] nxt = fill   ? tokens + 3'd1 :
                    bulk   ? tokens - 3'd2 :
                    lite   ? tokens - 3'd1 :
                    refill ? tokens + 3'd1 : tokens;
   wire [1:0] nxt_resv = park               ? resv + 2'd1 :
                         (drain || refill)  ? resv - 2'd1 : resv;
   wire [2:0] nxt_level = nxt + {1'b0, nxt_resv};

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;
    initial deep = 1'b0;
   initial resv = 2'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
            deep      <= 1'b0;
           resv      <= 2'd0;
        end else begin
            tokens <= nxt;
           resv   <= nxt_resv;
           if (inc || dec) deep <= (nxt_level >= 3'd3);

           if (fill && tokens == 3'd1)        tokens_hi <= 1'b1;
           else if (refill && tokens == 3'd1) tokens_hi <= 1'b1;
            else if (lite && tokens == 3'd2) tokens_hi <= 1'b0;
            else if (bulk && tokens == 3'd3) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output reg  [3:0] remaining,
    output reg  [3:0] sent,
    output reg        busy,
    output reg        done
);
    // the bus grants at most five words per burst, so an 8-word block is
    // issued as a 5-word burst plus a deferred 3-word tail
    reg  [3:0] pending;
    // block length is fixed at 8 words
    initial remaining = 4'd5;
    initial pending   = 4'd3;
    initial sent      = 4'd0;
    initial busy      = 1'b1;
    initial done      = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            remaining <= 4'd5;
            pending   <= 4'd3;
            sent      <= 4'd0;
            busy      <= 1'b1;
            done      <= 1'b0;
        end else if (ce) begin
            if (remaining != 4'd0) begin
                remaining <= remaining - 4'd1;
                sent      <= sent + 4'd1;
                if (remaining == 4'd1 && pending == 4'd0)
                    busy <= 1'b0;
            end
            else if (pending != 4'd0) begin
                // burst boundary: re-arm the engine for the deferred tail
                remaining <= pending;
                pending   <= 4'd0;
                busy      <= 1'b1;
            end
            // done is raised the cycle after the last word retires
            done <= (remaining == 4'd0 && pending == 4'd0);
        end
    end

    // P: the engine must never report completion while still claiming to copy
    always @(posedge clk)
        if (done)
            assert (!busy);
endmodule

module lfsr_shadow_capture (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_cap,
    output wire [7:0] o_rand,
    output wire [7:0] o_shadow,
    output wire       o_shadow_valid
);
    // maximal-length 8-bit LFSR, taps at 8,6,5,4 (x^8 + x^6 + x^5 + x^4 + 1)
    reg [7:0] lfsr;
   reg [7:0] lfsr_b;
    reg [7:0] shadow;
    reg       shadow_valid;
   reg [1:0] ch_en;   // capture mixer channel enables: bit0 = gen A, bit1 = gen B
  reg [7:0] cap_data;  // capture pipeline stage: sampled word awaiting commit
  reg       cap_pend;  // stage holds a word not yet written to the shadow

    initial lfsr         = 8'h01;
   initial lfsr_b       = 8'hA5;
    initial shadow       = 8'h00;
    initial shadow_valid = 1'b0;
   initial ch_en        = 2'b01;
  initial cap_data     = 8'h00;
  initial cap_pend     = 1'b0;

    wire fb = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];
   wire fb_b = lfsr_b[7] ^ lfsr_b[5] ^ lfsr_b[4] ^ lfsr_b[3];
   // shared capture port: XOR of whichever generator channels are enabled
   wire [7:0] sample = (ch_en[0] ? lfsr : 8'h00) ^ (ch_en[1] ? lfsr_b : 8'h00);
  // two-cycle capture: register the shared port, then commit it into the shadow
  wire cap_start  = i_ce && i_cap && !cap_pend;   // stall a request while one is in flight
  wire cap_commit = i_ce && cap_pend;
  // generators hold on the sample cycle so the staged word matches the reported channel
  wire gen_adv    = i_ce && !cap_start;

    always @(posedge i_clk) begin
        if (i_rst) begin
            lfsr <= 8'h01;
           lfsr_b <= 8'hA5;
       end else if (gen_adv) begin
            lfsr <= { lfsr[6:0], fb };
           lfsr_b <= { lfsr_b[6:0], fb_b };
        end
    end

   // capture stage: the shared port is registered before it reaches the shadow
   always @(posedge i_clk) begin
       if (i_rst) begin
           cap_data <= 8'h00;
           cap_pend <= 1'b0;
       end else if (cap_start) begin
           cap_data <= sample;
           cap_pend <= 1'b1;
       end else if (cap_commit) begin
           cap_pend <= 1'b0;
       end
   end

    // shadow register: snapshots the generator output on request
    always @(posedge i_clk) begin
        if (i_rst) begin
            shadow       <= 8'h00;
            shadow_valid <= 1'b0;
           ch_en        <= 2'b01;
       end else if (cap_commit) begin
          shadow       <= cap_data;
            shadow_valid <= 1'b1;
           // round-robin the shared port: gen A, gen B, then both mixed
           ch_en        <= (ch_en == 2'b01) ? 2'b10 :
                           (ch_en == 2'b10) ? 2'b11 : 2'b01;
        end
    end

    assign o_rand         = lfsr;
    assign o_shadow       = shadow;
    assign o_shadow_valid = shadow_valid;

    // P: once a sample has been latched, it can never be the lockup word
    always @(*)
        if (shadow_valid)
            assert (shadow != 8'h00);
endmodule

module char_occurrence_scan (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire ch_match,
    output reg [3:0] nchars,
    output reg [3:0] nmatch,
    output wire done
);
    initial nchars = 4'd0;
    initial nmatch = 4'd0;

   // match accounting is pipelined one cycle behind the character counter
   reg m_stage;
   initial m_stage = 1'b0;

    // scan a fixed 8-character string, counting occurrences of the target char
    assign done = (nchars == 4'd8);

    always @(posedge clk) begin
        if (rst) begin
            nchars <= 4'd0;
            nmatch <= 4'd0;
           m_stage <= 1'b0;
       end else begin
           // retire the match flag captured for the previous character
           if (m_stage)
               nmatch <= nmatch + 4'd1;
           m_stage <= 1'b0;
           if (ce && !done) begin
               nchars <= nchars + 4'd1;
               m_stage <= ch_match;
           end
       end
    end

    // P: if every character matched, the whole string must have been consumed
    always @(posedge clk)
        if (nmatch == 4'd8)
            assert (nchars == 4'd8);
endmodule

module char_tally (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire [7:0] i_char,
    input wire [7:0] i_target,
    output wire o_all_hits,
    output wire o_all_misses
);
    reg [3:0] total, hits, misses;
reg       pend_v;
reg       pend_m;
    initial total  = 4'd0;
    initial hits   = 4'd0;
    initial misses = 4'd0;
initial pend_v = 1'b0;
initial pend_m = 1'b0;

    wire match = (i_char == i_target);

    always @(posedge clk)
        if (rst) begin
            total  <= 4'd0;
            hits   <= 4'd0;
            misses <= 4'd0;
pend_v <= 1'b0;
pend_m <= 1'b0;
end else if (i_ce) begin
    if (pend_v) begin
        if (pend_m) hits   <= hits   + 4'd1;
        else        misses <= misses + 4'd1;
    end
    pend_v <= (total != 4'hf);
    if (total != 4'hf) begin
        total  <= total + 4'd1;
        pend_m <= match;
    end
        end

    assign o_all_hits   = (total != 4'd0) && (hits   == total);
    assign o_all_misses = (total != 4'd0) && (misses == total);

    always @(*)
        if (o_all_hits) assert (!o_all_misses);
endmodule

module thermo_window (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire warmer,
    output reg heat
);
    localparam [3:0] T_LOW  = 4'd4;
    localparam [3:0] T_HIGH = 4'd12;

    reg [3:0] temp;
    reg [1:0] win, heat_cycles, cool_cycles;
    reg cool;                    // second valve position (two-position loop)
    reg cmd_heat, cmd_cool;      // staged window comparator result

    initial begin
        temp = 4'd8; heat = 1'b0;
        win = 2'd0; heat_cycles = 2'd0; cool_cycles = 2'd0;
        cool = 1'b1; cmd_heat = 1'b0; cmd_cool = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            temp <= 4'd8; heat <= 1'b0;
            win <= 2'd0; heat_cycles <= 2'd0; cool_cycles <= 2'd0;
            cool <= 1'b1; cmd_heat <= 1'b0; cmd_cool <= 1'b0;
        end else if (ce) begin
            win <= win + 2'd1;
            if (heat) heat_cycles <= heat_cycles + 2'd1;
            if (cool) cool_cycles <= cool_cycles + 2'd1;
            temp <= warmer ? ((temp == 4'd15) ? temp : temp + 4'd1)
                           : ((temp == 4'd0)  ? temp : temp - 4'd1);
            // apply the command staged on the previous enabled cycle
            if      (cmd_heat) begin heat <= 1'b1; cool <= 1'b0; end
            else if (cmd_cool) begin heat <= 1'b0; cool <= 1'b1; end
            // stage the next command; only the resting position requests a move
            cmd_heat <= cool && (temp <= T_LOW);
            cmd_cool <= heat && (temp >= T_HIGH);
        end
    end

    always @(posedge clk)
        if (cool_cycles == 2'd0)
            assert (heat_cycles == win);
endmodule

module ring_occ (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    output reg  [2:0] count,
    output reg  [3:0] occ
);
    reg [1:0] wptr, rptr;
   reg [2:0] alloc_cnt;
   reg [3:0] upd_set, upd_clr;
   initial begin wptr = 2'd0; rptr = 2'd0; count = 3'd0; occ = 4'b0000;
                 alloc_cnt = 3'd0; upd_set = 4'b0000; upd_clr = 4'b0000; end

   wire do_push = push && (alloc_cnt != 3'd4);
   wire do_pop  = pop  && (alloc_cnt != 3'd0);

    wire [3:0] set_bit = do_push ? (4'b0001 << wptr) : 4'b0000;
    wire [3:0] clr_bit = do_pop  ? (4'b0001 << rptr) : 4'b0000;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
            occ   <= 4'b0000;
           alloc_cnt <= 3'd0;
           upd_set   <= 4'b0000;
           upd_clr   <= 4'b0000;
        end else begin
            if (do_push) wptr <= wptr + 2'd1;
            if (do_pop)  rptr <= rptr + 2'd1;
           upd_set <= set_bit;
           upd_clr <= clr_bit;
           occ   <= (occ | upd_set) & ~upd_clr;
           count <= alloc_cnt;
            case ({do_push, do_pop})
               2'b10:   alloc_cnt <= alloc_cnt + 3'd1;
               2'b01:   alloc_cnt <= alloc_cnt - 3'd1;
               default: alloc_cnt <= alloc_cnt;
            endcase
        end
    end

    always @(posedge clk)
        if (count == 3'd1)
            assert (occ == 4'b0001 || occ == 4'b0010 ||
                    occ == 4'b0100 || occ == 4'b1000);
endmodule

module intersection_phase_pair (
    input wire clk,
    input wire rst,
    input wire ce,
    output reg [2:0] a_ph,
    output reg [2:0] b_ph,
    output reg [2:0] timer
);
    // phase 0 = GREEN, 1 = YELLOW, 2 = ALL_RED, 3..5 = red while the other road runs
    localparam [2:0] LAST = 3'd5;
    localparam [2:0] DUR  = 3'd4;
    localparam [2:0] DUR_Y = 3'd2;   // yellow change interval
    localparam [2:0] DUR_R = 3'd1;   // all-red clearance interval

    // dual timing plan: alternate cycles run the greens one tick shorter
    reg       alt;
    reg [2:0] a_nxt;
    reg [2:0] b_nxt;
    reg [2:0] dur_nxt;

    initial a_ph  = 3'd0;
    initial b_ph  = 3'd3;
    initial timer = DUR;
    initial alt   = 1'b1;

    always @(*) begin
        a_nxt = (a_ph == LAST) ? 3'd0 : a_ph + 3'd1;
        b_nxt = (b_ph == LAST) ? 3'd0 : b_ph + 3'd1;
        case (a_nxt)
            3'd0, 3'd3: dur_nxt = alt ? DUR : DUR - 3'd1;
            3'd1, 3'd4: dur_nxt = DUR_Y;
            default:    dur_nxt = DUR_R;
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            a_ph  <= 3'd0;
            b_ph  <= 3'd3;
            timer <= DUR;
            alt   <= 1'b1;
        end else if (ce) begin
            if (timer == 3'd0) begin
                a_ph  <= a_nxt;
                b_ph  <= b_nxt;
                timer <= dur_nxt;
                if (a_nxt == 3'd0) alt <= ~alt;
            end else begin
                timer <= timer - 3'd1;
            end
        end
    end

    // P: when road A holds its green phase, road B must not also be in its green phase
    always @(posedge clk)
        if (a_ph == 3'd0) assert (b_ph != 3'd0);

    // P2: the rings stay half a cycle apart, so they never display the same phase
    always @(posedge clk)
        assert (a_ph != b_ph);
endmodule

module pwm_antiphase (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire load,
    input wire [3:0] i_duty,
    output wire pwm_a,
    output wire pwm_b
);
    // ramp counter and its anti-phase mirror (kept complementary by construction)
    reg [3:0] cnt  = 4'd0;
    reg [3:0] cntb = 4'd15;
    // duty for each channel, split so the pair always sums to full scale
    reg [3:0] duty_a = 4'd8;
    reg [3:0] duty_b = 4'd7;
   // the B-side complement is computed in its own stage to shorten the load path,
   // so it lands in duty_b one cycle after duty_a takes the new value
   reg [3:0] duty_b_stg = 4'd7;
   reg       upd_pend   = 1'b0;

    always @(posedge clk)
        if (rst) begin
            cnt  <= 4'd0;
            cntb <= 4'd15;
        end else if (ce) begin
            cnt  <= cnt  + 4'd1;
            cntb <= cntb - 4'd1;
        end

    always @(posedge clk)
        if (rst) begin
            duty_a <= 4'd8;
            duty_b <= 4'd7;
           duty_b_stg <= 4'd7;
           upd_pend   <= 1'b0;
        end else if (load) begin
            duty_a <= i_duty;
           duty_b_stg <= 4'd15 - i_duty;
           upd_pend   <= 1'b1;
       end else if (upd_pend) begin
           duty_b     <= duty_b_stg;
           upd_pend   <= 1'b0;
        end
   // while the B complement is still in the stage the two comparators would be
   // working from a mismatched duty pair, so the A-side drive is held off

   assign pwm_a = (cnt  < duty_a) && !upd_pend;
    assign pwm_b = (cntb < duty_b);

    // the two half-bridge drives must never be asserted together
    always @(*)
        if (pwm_a) assert (!pwm_b);
endmodule

module ring_valid_onehot (
    input wire        clk,
    input wire        rst,
    input wire        push,
    input wire        pop,
    input wire [7:0]  din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full
);
    // 4-deep ring buffer with a per-slot valid bit vector
    reg [1:0] wptr;
    reg [1:0] rptr;
    reg [2:0] count;
    reg [3:0] valid;
   // one-hot slot selects: decoder-free access to the valid vector and mem
   reg [3:0] wsel;
   reg [3:0] rsel;
    reg [7:0] mem [0:3];

    integer k;
    initial begin
        wptr  = 2'd0;
        rptr  = 2'd0;
        count = 3'd0;
        valid = 4'b0000;
       wsel  = 4'b0001;
       rsel  = 4'b0001;
        for (k = 0; k < 4; k = k + 1)
            mem[k] = 8'h00;
    end

wire do_push = push && !o_full;
wire do_pop  = pop  && !o_empty;

// flags come straight off the valid bits at the two access points:
// empty = the slot we would read is not valid, full = the slot we
// would write is still valid
assign o_empty = ~|(valid & rsel);
assign o_full  = |(valid & wsel);
assign dout    = (rsel[0] ? mem[0] : 8'h00) |
                 (rsel[1] ? mem[1] : 8'h00) |
                 (rsel[2] ? mem[2] : 8'h00) |
                 (rsel[3] ? mem[3] : 8'h00);

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
            valid <= 4'b0000;
           wsel  <= 4'b0001;
           rsel  <= 4'b0001;
        end else begin
            if (do_push) begin
                mem[wptr]   <= din;
wsel        <= {wsel[2:0], wsel[3]};
                wptr        <= wptr + 2'd1;
            end
            if (do_pop) begin
rsel        <= {rsel[2:0], rsel[3]};
                rptr        <= rptr + 2'd1;
            end
           // shared read-modify-write of the valid vector: the write
           // side sets its slot, the read side clears its slot
           valid <= (valid | (do_push ? wsel : 4'b0000)) &
                    ~(do_pop ? rsel : 4'b0000);
            if (do_push && !do_pop)
                count <= count + 3'd1;
            else if (!do_push && do_pop)
                count <= count - 3'd1;
        end
    end

    // occupancy window implied by (rptr, count): slot i is occupied iff
    // ((i - rptr) mod 4) < count
    wire [1:0] d0 = 2'd0 - rptr;
    wire [1:0] d1 = 2'd1 - rptr;
    wire [1:0] d2 = 2'd2 - rptr;
    wire [1:0] d3 = 2'd3 - rptr;
    wire [3:0] occ;
    assign occ[0] = ({1'b0, d0} < count);
    assign occ[1] = ({1'b0, d1} < count);
    assign occ[2] = ({1'b0, d2} < count);
    assign occ[3] = ({1'b0, d3} < count);

    // P: a single-entry queue has exactly one valid slot
    always @(*)
        if (count == 3'd1)
            assert ((valid == 4'b0001) || (valid == 4'b0010) ||
                    (valid == 4'b0100) || (valid == 4'b1000));
endmodule

module stack_occupancy (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [7:0] data,
    output wire [7:0] o_top,
    output wire empty,
    output wire full
);
    parameter DEPTH = 8;
    reg [3:0] sp   = 4'd0;   // occupancy / stack pointer
    reg [3:0] free = 4'd8;   // mirrored free-slot count
reg [3:0] sp_n   = 4'd0;   // issue-stage pointer (ops accepted)
reg [3:0] free_n = 4'd8;   // issue-stage free-slot count
reg       stg_v    = 1'b0; // operation staged for commit
reg       stg_push = 1'b0; // staged direction: 1 = push, 0 = pop
reg [2:0] stg_addr = 3'd0; // staged write slot
reg [7:0] stg_data = 8'h00;
    reg [7:0] mem [0:7];
    integer i;
    initial for (i = 0; i < 8; i = i + 1) mem[i] = 8'h00;

    assign empty = (sp == 4'd0);
    assign full  = (sp == DEPTH[3:0]);

wire empty_n = (sp_n == 4'd0);
wire full_n  = (sp_n == DEPTH[3:0]);

wire do_push = push && !pop && !full_n;
wire do_pop  = pop  && !push && !empty_n;

    always @(posedge clk)
        if (rst) begin
            sp   <= 4'd0;
            free <= 4'd8;
end else if (stg_v && stg_push) begin
            sp   <= sp + 4'd1;
            free <= free - 4'd1;
end else if (stg_v && !stg_push) begin
            sp   <= sp - 4'd1;
            free <= free + 4'd1;
        end

   always @(posedge clk)
       if (rst) begin
           sp_n     <= 4'd0;
           free_n   <= 4'd8;
           stg_v    <= 1'b0;
           stg_push <= 1'b0;
           stg_addr <= 3'd0;
           stg_data <= 8'h00;
       end else begin
           stg_v    <= do_push || do_pop;
           stg_push <= do_push;
           stg_addr <= sp_n[2:0];
           stg_data <= data;
           if (do_push) begin
               sp_n   <= sp_n + 4'd1;
               free_n <= free_n - 4'd1;
           end else if (do_pop) begin
               sp_n   <= sp_n - 4'd1;
               free_n <= free_n + 4'd1;
           end
       end

    always @(posedge clk)
if (!rst && stg_v && stg_push) mem[stg_addr] <= stg_data;

    assign o_top = empty ? 8'h00 : mem[sp[2:0] - 3'd1];

    always @(*)
        if (!empty) assert (free <= 4'd7);
endmodule

module watchdog (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire kick,
    input wire ack,
    output reg fault
);
    reg [3:0] timer;
    reg [3:0] elapsed;
reg [3:0] resv;
reg [3:0] period;
wire [3:0] period_tight = (period == 4'd4) ? 4'd4 : period - 4'd1;
wire [3:0] period_relax = (period == 4'd8) ? 4'd8 : period + 4'd1;
localparam [3:0] GRACE = 4'd2;
initial begin timer = 4'd8; elapsed = 4'd0; fault = 1'b0; period = 4'd8; resv = 4'd0; end

    always @(posedge clk) begin
        if (rst) begin
            timer   <= 4'd8;
            elapsed <= 4'd0;
            fault   <= 1'b0;
period  <= 4'd8;
            resv    <= 4'd0;
        end else if (i_ce) begin
            if (ack) begin
timer   <= period_tight - GRACE;
resv    <= GRACE;
period  <= period_tight;
                elapsed <= 4'd0;
                fault   <= 1'b0;
            end else if (kick && !fault) begin
timer   <= period_relax - GRACE;
resv    <= GRACE;
period  <= period_relax;
                elapsed <= 4'd0;
            end else begin
                if (timer == 4'd1 && resv != 4'd0) begin
                    timer <= resv;
                    resv  <= 4'd0;
                end else if (timer != 4'd0) timer <= timer - 4'd1;
if (elapsed != period) elapsed <= elapsed + 4'd1;
                if (timer == 4'd1 && resv == 4'd0) fault <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (elapsed == 4'd8)
            assert (fault);
endmodule

module queue_ring_onehot (
    input  wire clk,
    input  wire rst,
    input  wire push,
    input  wire pop,
    input  wire [7:0] wdata,
    output wire [7:0] rdata,
    output wire full,
    output wire empty
);
    // 4-entry ring buffer.  The write and read positions are kept as one-hot
    // slot selects that rotate; the occupancy is kept as a separate counter.
    reg [2:0] count;
    reg [3:0] wsel;
    reg [3:0] rsel;
   // One-entry write staging register: an accepted push lands here and is
   // committed into the ring array on the following cycle, which keeps the
   // array write path off the push datapath.
   reg [7:0] stg;
   reg       stg_v;
    reg [7:0] mem0, mem1, mem2, mem3;

    initial count = 3'd0;
    initial wsel  = 4'b0001;
    initial rsel  = 4'b0001;
   initial stg   = 8'h00;
   initial stg_v = 1'b0;
    initial mem0  = 8'h00;
    initial mem1  = 8'h00;
    initial mem2  = 8'h00;
    initial mem3  = 8'h00;

    assign full  = (count == 3'd4);
    assign empty = (count == 3'd0);

    wire do_push = push && (count != 3'd4);
    wire do_pop  = pop  && (count != 3'd0);

   wire commit = stg_v;

   // While the array part of the ring is empty the head of the queue is still
   // sitting in the staging register, so forward it to the read port.
   wire fwd = stg_v && (rsel == wsel);


   assign rdata = fwd     ? stg  :
                  rsel[0] ? mem0 :
                  rsel[1] ? mem1 :
                  rsel[2] ? mem2 : mem3;

    always @(posedge clk) begin
        if (rst) begin
            count <= 3'd0;
            wsel  <= 4'b0001;
            rsel  <= 4'b0001;
           stg   <= 8'h00;
           stg_v <= 1'b0;
        end else begin
            if (do_push && !do_pop)
                count <= count + 3'd1;
            else if (do_pop && !do_push)
                count <= count - 3'd1;

           stg_v <= do_push;
           if (do_push)
               stg <= wdata;


           if (commit)
               wsel <= { wsel[2:0], wsel[3] };

            if (do_pop)
                rsel <= { rsel[2:0], rsel[3] };
        end
    end

    always @(posedge clk) begin
       if (!rst && commit) begin
           if (wsel[0]) mem0 <= stg;
           if (wsel[1]) mem1 <= stg;
           if (wsel[2]) mem2 <= stg;
           if (wsel[3]) mem3 <= stg;
        end
    end

    // P: an empty ring must have its write slot select aligned with its read
    // slot select.
    always @(*)
        if (count == 3'd0)
            assert (wsel == rsel);
endmodule

module ringq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire push,
    input wire pop
);
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg       empty_r, full_r;
reg [1:0] wptr2, rptr2;
reg [2:0] count2;
reg       empty2_r, full2_r;
reg       wsel, rsel;
reg [2:0] free_pool;
    initial begin wptr = 2'd0; rptr = 2'd0; count = 3'd0; empty_r = 1'b1; full_r = 1'b0; end
initial begin wptr2 = 2'd0; rptr2 = 2'd0; count2 = 3'd0; empty2_r = 1'b1; full2_r = 1'b0; end
initial begin wsel = 1'b0; rsel = 1'b0; free_pool = 3'd6; end

wire do_push  = i_ce && push && !wsel && !full_r;
wire do_push2 = i_ce && push &&  wsel && !full2_r;
wire do_pop   = i_ce && pop  && !rsel && !empty_r;
wire do_pop2  = i_ce && pop  &&  rsel && !empty2_r;
    wire [1:0] nw = wptr + do_push;
    wire [1:0] nr = rptr + do_pop;
wire [1:0] nw2 = wptr2 + do_push2;
wire [1:0] nr2 = rptr2 + do_pop2;
wire push_any = do_push || do_push2;
wire pop_any  = do_pop  || do_pop2;
wire [2:0] free_nxt = free_pool - push_any + pop_any;

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 2'd0; rptr <= 2'd0; count <= 3'd0;
            empty_r <= 1'b1; full_r <= 1'b0;
wptr2 <= 2'd0; rptr2 <= 2'd0; count2 <= 3'd0;
empty2_r <= 1'b1; full2_r <= 1'b0;
wsel <= 1'b0; rsel <= 1'b0; free_pool <= 3'd6;
        end else begin
            wptr <= nw;
            rptr <= nr;
            empty_r <= (nw == nr) && (do_pop  || (empty_r && !do_push));
full_r  <= ((nw == nr) && (do_push || (full_r  && !do_pop))) || (free_nxt == 3'd0);
            count <= count + do_push - do_pop;
wptr2 <= nw2;
rptr2 <= nr2;
empty2_r <= (nw2 == nr2) && (do_pop2  || (empty2_r && !do_push2));
full2_r  <= ((nw2 == nr2) && (do_push2 || (full2_r  && !do_pop2))) || (free_nxt == 3'd0);
count2 <= count2 + do_push2 - do_pop2;
wsel <= wsel ^ push_any;
rsel <= rsel ^ pop_any;
free_pool <= free_nxt;
        end
    end

    always @(posedge clk)
        if (empty_r)
            assert (!full_r);
endmodule

module sorted_pair (
    input wire clk,
    input wire rst,
    input wire ins,
    input wire pop,
    input wire [3:0] val,
    output reg [4:0] sum
);
    reg [3:0] k0, k1;
    reg [1:0] count;
   reg [3:0] stg;
   reg        stg_v;
initial begin k0 = 0; k1 = 0; count = 0; sum = 0; stg = 0; stg_v = 0; end

wire do_ins = ins && !pop && !stg_v && (count != 2'd2);
wire do_pop = pop && !ins && !stg_v && (count != 2'd0);

   // an accepted value waits in the staging slot; the merge into the sorted
   // pair is deferred until the next access, which is stalled for that cycle
   wire do_mrg = stg_v && (ins || pop);

    always @(posedge clk) begin
        if (rst) begin
            k0 <= 4'd0; k1 <= 4'd0; count <= 2'd0; sum <= 5'd0;
            stg <= 4'd0; stg_v <= 1'b0;
end else if (do_mrg) begin
            if (count == 2'd0) begin
                k0 <= stg;
            end else if (stg < k0) begin
                k0 <= stg; k1 <= k0;
            end else begin
                k1 <= stg;
            end
            count <= count + 2'd1;
            sum   <= sum + {1'b0, stg};
            stg_v <= 1'b0;
        end else if (do_ins) begin
            stg   <= val;
            stg_v <= 1'b1;
        end else if (do_pop) begin
            k0    <= k1;
            k1    <= 4'd0;
            count <= count - 2'd1;
            sum   <= sum - {1'b0, k0};
        end
    end

    always @(posedge clk)
        if (count == 2'd0)
            assert (sum == 5'd0);
endmodule

module token_bucket (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire req,
    input  wire drip,
    output wire grant
);
    reg [3:0] tokens = 4'd8;   // tokens currently in the bucket
    reg [3:0] free   = 4'd0;   // room left in the bucket (shadow accounting)
    reg [3:0] cap    = 4'd8;   // current burst allowance (adaptive capacity)
   // secondary lane: overflow bucket drawing on the same allowance pool
   reg [3:0] tokens_b = 4'd4;
   reg [3:0] free_b   = 4'd0;
   reg [3:0] cap_b    = 4'd4;

    wire spend   = ce && req  && (tokens != 4'd0);
    wire refill  = ce && drip && (free   != 4'd0);
   // the secondary lane serves a request only when the primary bucket is
   // dry, and absorbs a drip only when the primary bucket has no room left
   wire spend_b  = ce && req  && (tokens == 4'd0) && (tokens_b != 4'd0);
   wire refill_b = ce && drip && (free   == 4'd0) && (free_b   != 4'd0);
   // starved: a request found the bucket empty, so pull one slot of
   // allowance across from the secondary lane; that lane may only give a
   // slot up above its own reserve, and only out of room it is not using
   wire restore = ce && req && (tokens == 4'd0) && (cap_b != 4'd4) && (free_b != 4'd0);
    // fully idle with room going unused: retire one slot of allowance
    wire reclaim = ce && !req && !drip && (free != 4'd0) && (cap != 4'd4);

   assign grant = spend || spend_b;

    always @(posedge clk) begin
        if (rst) begin
            tokens <= 4'd8;
            free   <= 4'd0;
            cap    <= 4'd8;
           tokens_b <= 4'd4;
           free_b   <= 4'd0;
           cap_b    <= 4'd4;
        end else begin
            tokens <= tokens - spend + refill;
            free   <= free   + spend - refill + restore - reclaim;
            cap    <= cap    + restore - reclaim;
           tokens_b <= tokens_b - spend_b + refill_b;
           free_b   <= free_b   + spend_b - refill_b - restore + reclaim;
           cap_b    <= cap_b    - restore + reclaim;
        end
    end

    // P: if the bucket is not completely full, at least one slot's worth of
    // tokens is missing, so occupancy cannot exceed CAP-1.
    always @(posedge clk)
        if (free != 4'd0)
            assert (tokens <= 4'd7);
endmodule

module substr_search (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] in_char,
    output reg [1:0] idx,
    output reg found
);
    localparam [7:0] TGT = 8'h61; // 'a'
    localparam [7:0] DELIM = 8'h20; // ' '

    // engine B: delimited-word matcher for "aa", sharing engine A's counter
    reg wpend; // engine B result awaiting commit onto the shared found flag
    reg hold;  // shared index frozen while a match position is being reported


    initial idx   = 2'd0;
    initial found = 1'b0;
    initial wpend = 1'b0;
    initial hold  = 1'b0;

    // matches the 3-character run "aaa"; freezes once idx saturates at 3
    always @(posedge clk) begin
        if (rst) begin
            idx   <= 2'd0;
            found <= 1'b0;
            wpend <= 1'b0;
            hold  <= 1'b0;
        end else if (ce) begin
            // commit stage: engine B publishes onto the shared found flag
            if (wpend) begin
                wpend <= 1'b0;
                found <= 1'b1;
            end
            if (!hold && idx != 2'd3) begin
            if (in_char == TGT) begin
                idx <= idx + 2'd1;
                if (idx == 2'd2)
                    found <= 1'b1;
            end else if (in_char == DELIM && idx == 2'd2) begin
                // "aa" closed by a delimiter: freeze the shared index at the
                // match length and hand the result to the commit stage
                wpend <= 1'b1;
                hold  <= 1'b1;
            end else begin
                idx <= 2'd0;
            end
            end
        end
    end

    // P: the found flag implies a non-empty partial match is held
    always @(posedge clk)
        if (found) assert (idx != 2'd0);
endmodule

module alu_budget (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire [7:0] i_step,
    output wire [7:0] o_acc,
    output wire o_zero,
    output wire o_full
);
    localparam [7:0] LIMIT = 8'd200;
   localparam [7:0] CHUNK = 8'd8; // credit shifted into the reservation per refill

    reg [7:0] acc;   // accumulated result
    reg [7:0] rem;   // headroom credited to the accumulator
    reg [7:0] acc_b; // secondary channel accumulation
   reg [7:0] resv;  // credit reserved so channel B cannot be starved
    reg       turn;  // round-robin owner of the shared credit pool
    initial acc = 8'd0;
    initial rem = LIMIT;
    initial acc_b = 8'd0;
   initial resv = 8'd0;
    initial turn = 1'b0;

   wire [7:0] pool   = turn ? resv : rem;
   wire       grant  = i_ce && (pool >= i_step);
   wire       refill = !grant && (resv < CHUNK) && (rem >= CHUNK);

    always @(posedge clk)
        if (rst) begin
            acc <= 8'd0;
            rem <= LIMIT;
            acc_b <= 8'd0;
           resv <= 8'd0;
            turn <= 1'b0;
        end else if (grant) begin
            turn <= ~turn;
           if (turn) begin
               resv  <= resv  - i_step;
               acc_b <= acc_b + i_step;
           end else begin
               rem <= rem - i_step;
               acc <= acc + i_step;
           end
       end else if (refill) begin
           rem  <= rem  - CHUNK;
           resv <= resv + CHUNK;
        end

    assign o_acc  = acc;
    assign o_zero = (acc == 8'd0) && (acc_b == 8'd0);
    assign o_full = (rem == 8'd0);

    // P: a nonzero accumulation never exceeds its saturation bound
    always @(*)
        if (!o_zero) assert (acc <= LIMIT);
endmodule

module uart_tx_budget (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // baud tick / enable: low means idle
    input  wire       i_start,
    input  wire [7:0] i_data,
    output reg        tx,
    output reg        busy
);
    // bit accounting for one 8-bit payload
    reg [3:0] sent;   // data bits already shifted out
    reg [3:0] left;    // data bits still to shift out
    reg [7:0] sh;      // shift register
   reg [3:0] sh_cnt;  // payload bits still sitting inside the shift register
   reg       obuf;    // output stage: line level registered one tick ahead
   reg       obuf_v;  // output stage currently holds a payload bit

    initial tx   = 1'b1;
    initial busy = 1'b0;
    initial sent = 4'd0;
    initial left = 4'd8;
    initial sh   = 8'h00;
   initial sh_cnt = 4'd0;
   initial obuf   = 1'b1;
   initial obuf_v = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tx   <= 1'b1;
            busy <= 1'b0;
            sent <= 4'd0;
            left <= 4'd8;
            sh   <= 8'h00;
           sh_cnt <= 4'd0;
           obuf   <= 1'b1;
           obuf_v <= 1'b0;
        end else if (i_ce) begin
            if (!busy) begin
                if (i_start) begin
                    busy <= 1'b1;
                   sh     <= {1'b0, i_data[7:1]};
                   obuf   <= i_data[0];   // prefetch bit 0 during the start bit
                   obuf_v <= 1'b1;
                   sh_cnt <= 4'd7;
                    sent <= 4'd0;
                    left <= 4'd8;
                    tx   <= 1'b0;      // start bit
                end else begin
                    tx   <= 1'b1;      // line idle high
                end
            end else if (left != 4'd0) begin
               tx   <= obuf;          // data bit out of the output stage
               sent <= sent + {3'b000, obuf_v};
                left <= left - 4'd1;
               if (sh_cnt != 4'd0) begin
                   obuf   <= sh[0];
                   sh     <= {1'b0, sh[7:1]};
                   sh_cnt <= sh_cnt - 4'd1;
                   obuf_v <= 1'b1;
               end else begin
                   obuf_v <= 1'b0;    // shifter drained, last bit is on the line
               end
            end else begin
                tx   <= 1'b1;          // stop bit, frame complete
                busy <= 1'b0;
            end
        end
    end

    // Property: whenever the transmitter reports no data bits remaining while a
    // frame is still active, exactly eight payload bits must have been shifted.
    always @(posedge clk)
        if (busy && left == 4'd0)
            assert (sent == 4'd8);
endmodule

module vend_credit (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_coin_valid,   // idle when low: all state frozen
    input  wire       i_coin_dime,    // 1 = 10c, 0 = 5c
    output reg        o_dispense,
    output reg  [5:0] o_change
);
    // credit in cents, always a multiple of 5, capped by the 25c price
    reg [5:0] credit;
    // redundant "nickel units" accumulator: credit / 5
    reg [2:0] units;
   // the units path has only a +1 incrementer, so a dime's second nickel
   // unit waits here and is folded in on the next coin event
   reg [2:0] pend;

    initial credit     = 6'd0;
    initial units      = 3'd0;
   initial pend       = 3'd0;
    initial o_dispense = 1'b0;
    initial o_change   = 6'd0;

    // coin value, in units and in cents
    wire [2:0] coin_u = i_coin_valid ? (i_coin_dime ? 3'd2 : 3'd1) : 3'd0;
    wire [5:0] coin_c = i_coin_valid ? (i_coin_dime ? 6'd10 : 6'd5) : 6'd0;

   // nickel units waiting to be counted, including the coin arriving now
   wire [3:0] uq    = {1'b0, pend}   + {1'b0, coin_u};
   wire [4:0] utot  = {2'b00, units} + {1'b0, uq};
    wire [6:0] csum = {1'b0, credit} + {1'b0, coin_c};

    // the dispense decision is taken on the units accumulator
   wire       pay    = (utot >= 5'd5);
   wire [4:0] uafter = utot - 5'd5;

    always @(posedge clk) begin
        if (rst) begin
            credit     <= 6'd0;
            units      <= 3'd0;
           pend       <= 3'd0;
            o_dispense <= 1'b0;
            o_change   <= 6'd0;
        end else if (i_coin_valid) begin
            if (pay) begin
               units      <= uafter[2:0];
               pend       <= 3'd0;
                credit     <= csum[5:0] - 6'd25;
                o_dispense <= 1'b1;
                o_change   <= csum[5:0] - 6'd25;
            end else begin
               units      <= units + 3'd1;
               pend       <= uq[2:0] - 3'd1;
                credit     <= csum[5:0];
                o_dispense <= 1'b0;
            end
        end else begin
            o_dispense <= 1'b0;
        end
    end

    // P: when the units accumulator sits one nickel short of the price,
    //    the cent accumulator must read exactly 20 cents.
    always @(*)
        if (units == 3'd4)
            assert (credit == 6'd20);
endmodule

module alu_accum_slice (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire       i_sub,
    output reg  [7:0] o_result,
    output wire       o_zero
);
    reg [6:0] half;
reg [3:0] stg_lo;    // low nibble of the result in flight
reg       stg_cy;    // carry/borrow leaving the low nibble
reg       stg_sub;   // direction latched alongside the in-flight result
reg       stg_vld;   // a writeback is pending


    initial o_result = 8'd0;
    initial half     = 7'd0;
initial stg_lo   = 4'd0;
initial stg_cy   = 1'b0;
initial stg_sub  = 1'b0;
initial stg_vld  = 1'b0;

    assign o_zero = (o_result == 8'd0);

// only the low nibble is staged; the upper nibble is fixed up at drain time
// from the committed accumulator plus the latched carry/borrow
wire [3:0] hi_adj   = stg_cy ? (stg_sub ? 4'hF : 4'h1) : 4'h0;
wire [7:0] stg_full = {o_result[7:4] + hi_adj, stg_lo};

// the single 4-bit adder handles one nibble per pass
wire [4:0] lo_inc = {1'b0, o_result[3:0]} + 5'd2;
wire [4:0] lo_dec = {1'b0, o_result[3:0]} - 5'd2;

    always @(posedge clk) begin
        if (rst) begin
            o_result <= 8'd0;
            half     <= 7'd0;
stg_lo   <= 4'd0;
stg_cy   <= 1'b0;
stg_sub  <= 1'b0;
stg_vld  <= 1'b0;
end else begin
// a staged nibble cannot be chained onto, so a new request is refused
// while one is in flight; the drain reuses the same adder port, so it
// only runs on a cycle that is not accepting a request
if (i_ce && !stg_vld) begin
stg_lo  <= i_sub ? lo_dec[3:0] : lo_inc[3:0];
stg_cy  <= i_sub ? lo_dec[4]   : lo_inc[4];
stg_sub <= i_sub;
stg_vld <= 1'b1;
end else if (!i_ce && stg_vld) begin
o_result <= stg_full;
half     <= stg_sub ? (half - 7'd1) : (half + 7'd1);
stg_vld  <= 1'b0;
end
        end
    end

    // P: whenever the half-step tracker is at zero, the registered ALU result is zero
    always @(posedge clk)
        if (half == 7'd0)
            assert (o_result == 8'd0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    // in-flight bucket level; tokens is the registered (pipelined) copy
    reg [2:0] tok_stage;

wire drip_en  = drip  && (tok_stage != 3'd4);
wire spend_en = spend && (tok_stage != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
initial tok_stage = 3'd0;
    initial tokens_hi = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
tok_stage <= 3'd0;
            tokens_hi <= 1'b0;
        end else begin
if (inc)      tok_stage <= tok_stage + 3'd1;
else if (dec) tok_stage <= tok_stage - 3'd1;

tokens <= tok_stage;

if (inc && tok_stage == 3'd1)      tokens_hi <= 1'b1;
else if (dec && tok_stage == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module token_bucket (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire req,
    input  wire drip,
    output wire grant
);
    reg [3:0] tokens = 4'd8;   // tokens currently in the bucket
    reg [3:0] free   = 4'd0;   // room left in the bucket (shadow accounting)
   // A drip credit is charged against the bucket's room the moment it is
   // taken, but the token itself only shows up in the bucket on a later
   // enabled cycle, so credits queue up in the staging counter (depth 2).
   reg [1:0] stage  = 2'd0;   // accepted drips not yet added to tokens

    wire spend   = ce && req  && (tokens != 4'd0);
   wire accept  = ce && drip && (free != 4'd0) && (stage != 2'd2);
   wire commit  = ce && (stage != 2'd0);

    assign grant = spend;

    always @(posedge clk) begin
        if (rst) begin
            tokens <= 4'd8;
            free   <= 4'd0;
           stage  <= 2'd0;
        end else begin
           tokens <= tokens - spend + commit;
           free   <= free   + spend - accept;
           stage  <= stage  + accept - commit;
        end
    end

    // P: if the bucket is not completely full, at least one slot's worth of
    // tokens is missing, so occupancy cannot exceed CAP-1.
    always @(posedge clk)
        if (free != 4'd0)
            assert (tokens <= 4'd7);
endmodule

module minmax_abs_track (
    input wire i_clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_push,
    input wire signed [7:0] i_val,
    output wire [7:0] o_min,
    output wire [7:0] o_max,
    output wire [3:0] o_count,
    output wire o_bad
);
    // Tracks the running min and max of the magnitudes (absolute values) of a
    // stream of signed samples, plus a saturating sample counter and a latched
    // order-violation flag.

    reg [7:0] mn;
    reg [7:0] mx;
    reg       valid;
    reg [3:0] count;
    reg       bad;
    // programmable squelch floor (noise gate threshold)
    reg [7:0] flr;

    initial mn    = 8'hff;
    initial mx    = 8'h00;
    initial valid = 1'b0;
    initial count = 4'd0;
    initial bad   = 1'b0;
    initial flr   = 8'h00;

    // unsigned magnitude of the signed input (|-128| == 8'h80 fits unsigned)
    wire [7:0] mag = i_val[7] ? (~i_val + 8'd1) : i_val;

    // floor code shares the data bus with the samples
    wire [7:0] fcode = i_val;
    // squelch: a sample quieter than the floor is reported as the floor
    wire [7:0] gated = (mag < flr) ? flr : mag;

    always @(posedge i_clk) begin
        if (i_rst) begin
            mn    <= 8'hff;
            mx    <= 8'h00;
            valid <= 1'b0;
            count <= 4'd0;
            bad   <= 1'b0;
            flr   <= 8'h00;
        end else if (i_ce) begin
            // order checker: samples the registered extremes, gated by the
            // *counter* rather than by the valid flag
            bad <= (count != 4'd0) && (mn > mx);

            // floor programming: an enabled cycle without a push carries a
            // new floor code.  A code above the recorded peak would strand
            // that peak underneath the floor, so it is refused while a
            // window is open.
            if (!i_push && (!valid || (fcode <= mx)))
                flr <= fcode;

            // the recorded minimum saturates at the floor: a minimum taken
            // before the floor was raised is no longer a legal reading
            if (mn < flr)
                mn <= flr;

            if (i_push) begin
                if (!valid) begin
                    mn <= gated;
                    mx <= gated;
                end else begin
                    if (gated < mn)
                        mn <= gated;
                    if (gated > mx)
                        mx <= gated;
                end
                valid <= 1'b1;
                count <= (count == 4'd15) ? 4'd15 : (count + 4'd1);
            end
        end
    end

    assign o_min   = mn;
    assign o_max   = mx;
    assign o_count = count;
    assign o_bad   = bad;

    // Property: once at least one sample has been absorbed, the order checker
    // must never have fired.
    always @(posedge i_clk)
        if (valid)
            assert (!bad);

endmodule

module vend_credit (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_dime,
    output wire o_dispense,
    output wire [5:0] o_change
);
    reg [3:0] units = 0;      // credit in 5-cent units
    reg [5:0] cents = 0;      // credit in cents
    reg       dispense = 0;
    reg [5:0] change = 0;
    reg [5:0] chg_stage = 0;   // vend total waiting on the change subtractor
    reg       vend_stage = 0;  // a vend was deducted from credit last cycle

    wire [3:0] inc_u = i_dime ? 4'd2  : 4'd1;
    wire [5:0] inc_c = i_dime ? 6'd10 : 6'd5;
    wire [3:0] nu = units + inc_u;
    wire [5:0] nc = cents + inc_c;

    always @(posedge clk)
        if (i_reset) begin
            units    <= 4'd0;
            cents    <= 6'd0;
            dispense <= 1'b0;
            change   <= 6'd0;
            chg_stage  <= 6'd0;
            vend_stage <= 1'b0;
        end else if (i_ce) begin
            // stage 2: finish the change subtraction started last cycle
            dispense <= vend_stage;
            if (vend_stage) change <= chg_stage - 6'd25;
            // stage 1: take the coin and deduct a full vend's worth of credit
            if (nu >= 4'd5) begin
                units    <= nu - 4'd5;
                cents    <= nc - 6'd25;
                chg_stage  <= nc;
                vend_stage <= 1'b1;
            end else begin
                units    <= nu;
                cents    <= nc;
                vend_stage <= 1'b0;
            end
        end

    assign o_dispense = dispense;
    assign o_change   = change;

    always @(posedge clk)
        if (dispense) assert (change <= 6'd5);
endmodule

module crc8_bitpos (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire din,
    output reg [7:0] crc,
    output wire byte_done
);
    reg [7:0] active;
    reg [2:0] bitcnt;
    reg [7:0] crc_last;
    reg [7:0] crc_p;
    reg [7:0] act_pre;
    reg       ph;

    initial begin
        crc      = 8'hFF;
        active   = 8'h01;
        bitcnt   = 3'd0;
        crc_last = 8'h00;
        crc_p    = 8'hFF;
        act_pre  = 8'h01;
        ph       = 1'b0;
    end

    wire       fb      = crc[7] ^ din;
    wire [7:0] crc_nxt = {crc[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);

    assign byte_done = ce && ph && active[7];

    always @(posedge clk) begin
        if (rst) begin
            crc      <= 8'hFF;
            active   <= 8'h01;
            bitcnt   <= 3'd0;
            crc_last <= 8'h00;
            crc_p    <= 8'hFF;
            act_pre  <= 8'h01;
            ph       <= 1'b0;
        end else if (ce) begin
            ph <= ~ph;
            if (!ph) begin
                crc_p   <= crc_nxt;
                act_pre <= {active[6:0], active[7]};
            end else begin
                crc     <= crc_p;
                active  <= act_pre;
                bitcnt  <= bitcnt + 3'd1;
                if (active[7]) crc_last <= crc_p;
            end
        end
    end

    always @(posedge clk)
        if (bitcnt == 3'd7)
            assert (active == 8'h80);
endmodule

module watchdog (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire kick,
    input wire ack,
    output reg fault
);
    reg [3:0] timer;
    reg [3:0] elapsed;
    initial begin timer = 4'd8; elapsed = 4'd0; fault = 1'b0; end

    always @(posedge clk) begin
        if (rst) begin
            timer   <= 4'd8;
            elapsed <= 4'd0;
            fault   <= 1'b0;
        end else if (i_ce) begin
            if (ack) begin
                timer   <= 4'd8;
                elapsed <= 4'd0;
                fault   <= 1'b0;
            end else if (kick && !fault) begin
                timer   <= 4'd8;
                elapsed <= 4'd0;
            end else begin
                if (timer != 4'd0)   timer   <= timer - 4'd1;
                if (elapsed != 4'd8) elapsed <= elapsed + 4'd1;
                if (timer == 4'd1)   fault   <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (elapsed == 4'd8)
            assert (fault);
    always @(posedge clk)
        if (fault)
            assert (elapsed == 4'd8);
endmodule

module strscan (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] ch,
    input wire [7:0] target,
    output wire done,
    output wire [3:0] hits
);
    parameter LEN = 8;
    parameter MAXMISS = 4;


    reg [3:0] remaining;
    reg [3:0] consumed;
    reg [3:0] match_count;
    reg [3:0] miss_count;

    // abandon the scan early once too many characters have failed to match
    wire reject = (miss_count >= MAXMISS);

    initial remaining   = LEN;
    initial consumed    = 0;
    initial match_count = 0;
    initial miss_count  = 0;

    always @(posedge clk)
        if (rst) begin
            remaining   <= LEN;
            consumed    <= 0;
            match_count <= 0;
            miss_count  <= 0;
        end else if (ce && (remaining != 4'd0) && !reject) begin
            remaining <= remaining - 4'd1;
            consumed  <= consumed  + 4'd1;
            if (ch == target)
                match_count <= match_count + 4'd1;
            else
                miss_count <= miss_count + 4'd1;
        end

    assign done = (remaining == 4'd0) || reject;
    assign hits = match_count;

    // P: once the whole string has been scanned, every character was consumed
    always @(*)
        if (remaining == 4'd0)
            assert (consumed == LEN);

    // P2: a completed scan classified every character as a hit or a miss
    always @(posedge clk)
        if (remaining == 4'd0)
            assert (match_count + miss_count == LEN);
endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    output wire       o_done,
    output wire [4:0] o_src_off
);
    parameter [4:0] TOTAL = 5'd20;

    reg [4:0] remaining;
    reg [4:0] sent;
reg [2:0] pending;
    initial remaining = TOTAL;
    initial sent      = 5'd0;
initial pending   = 3'd0;

    always @(posedge clk)
        if (rst) begin
            remaining <= TOTAL;
            sent      <= 5'd0;
pending   <= 3'd0;
        end else if (i_ce && (remaining != 5'd0)) begin
            remaining <= remaining - 5'd1;
if ((pending == 3'd3) || (remaining == 5'd1)) begin
    sent    <= sent + {2'b00, pending} + 5'd1;
    pending <= 3'd0;
end else begin
    pending <= pending + 3'd1;
end
        end

    assign o_done    = (remaining == 5'd0);
    assign o_src_off = sent;

    always @(*)
        if (o_done)
            assert (sent == TOTAL);
endmodule

module wdog_kick (
    input wire clk,
    input wire i_ce,
    input wire kick,
    input wire ack,
    output wire o_reset
);
    reg [3:0] cnt;
    reg zf, armed, fault;
    reg [1:0] hold;
    initial cnt   = 4'd0;
    initial zf    = 1'b1;
    initial armed = 1'b0;
    initial fault = 1'b0;
    initial hold  = 2'd0;

    always @(posedge clk) if (i_ce) begin
        if (ack) begin
            fault <= 1'b0;
            armed <= 1'b0;
            cnt   <= 4'd0;
            zf    <= 1'b1;
        end else if (kick && !fault) begin
            armed <= 1'b1;
            cnt   <= 4'd8;
            zf    <= 1'b0;
        end else if (armed) begin
            if (zf) fault <= 1'b1;            // expiry seen through the flag
            if (cnt == 4'd0) armed <= 1'b0;   // disarm seen through the count
            else begin
                cnt <= cnt - 4'd1;
                zf  <= (cnt == 4'd1);
            end
        end
    end

    // minimum reset assertion width: downstream blocks need o_reset wide, so
    // the fault latch is stretched by a shadow timer for a few ce ticks after
    // the host acknowledges it
    always @(posedge clk) if (i_ce) begin
        if (fault)             hold <= 2'd3;
        else if (hold != 2'd0) hold <= hold - 2'd1;
    end

    assign o_reset = fault || (hold != 2'd0);

    always @(*)
        if (fault) assert (!armed);

    // a pending fault means the service window timer is parked at zero
    always @(posedge clk)
        if (fault) assert (cnt == 4'd0);
endmodule

module nano_alu_flags (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [1:0] op,      // 00=ADD 01=SUB 10=AND 11=PASS/refresh
    input wire [7:0] b,
    output reg [7:0] acc,
    output reg zf,            // zero flag
    output reg nf,            // negative (sign) flag
    output reg cf             // carry flag
);

   // accumulator writeback is pipelined one enabled cycle: the ALU result
   // waits in the writeback stage before it is retired into acc
   reg [7:0] stage;
   reg       stage_v;

    initial begin
        acc = 8'h00;
        zf  = 1'b1;           // acc == 0 at start
        nf  = 1'b0;
        cf  = 1'b0;
       stage   = 8'h00;
       stage_v = 1'b0;
    end

   // bypass the pending writeback so ops never read a stale acc
   wire [7:0] a_cur = stage_v ? stage : acc;

   wire [8:0] add_res = {1'b0, a_cur} + {1'b0, b};
   wire [8:0] sub_res = {1'b0, a_cur} - {1'b0, b};
   wire [7:0] and_res = a_cur & b;

    reg [7:0] res;
    reg        carry;

    always @(*) begin
        case (op)
            2'b00: begin res = add_res[7:0]; carry = add_res[8]; end
            2'b01: begin res = sub_res[7:0]; carry = sub_res[8]; end
            2'b10: begin res = and_res;      carry = 1'b0;       end
           default: begin res = a_cur;      carry = cf;         end // PASS
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            acc <= 8'h00;
            zf  <= 1'b1;
            nf  <= 1'b0;
            cf  <= 1'b0;
           stage   <= 8'h00;
           stage_v <= 1'b0;
        end else if (ce) begin
           if (stage_v)
               acc <= stage;              // retire the pending writeback
           stage   <= res;
           stage_v <= (op != 2'b11);      // PASS refresh adds no new write
            zf  <= (res == 8'h00);
            cf  <= carry;
            // sign flag is only rewritten by ops that actually change acc
            if (op != 2'b11)
                nf <= res[7];
        end
    end

    // P: the zero flag and the negative flag are never both asserted
    always @(posedge clk)
        if (zf)
            assert (!nf);

endmodule

module prio_pipe (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire [7:0] req,
    output reg        y_valid,
    output reg  [2:0] y_index,
    output reg        y_bit
);
    // combinational priority encode of the incoming request vector
    wire       c_valid = |req;
    wire [2:0] c_index = req[7] ? 3'd7 :
                         req[6] ? 3'd6 :
                         req[5] ? 3'd5 :
                         req[4] ? 3'd4 :
                         req[3] ? 3'd3 :
                         req[2] ? 3'd2 :
                         req[1] ? 3'd1 : 3'd0;

   // secondary grant: the highest priority request strictly below the primary
   // one, so one capture can produce two grants
   wire [7:0] req2     = req & ~(8'h01 << c_index);
   wire       c2_valid = |req2;
   wire [2:0] c2_index = req2[7] ? 3'd7 :
                         req2[6] ? 3'd6 :
                         req2[5] ? 3'd5 :
                         req2[4] ? 3'd4 :
                         req2[3] ? 3'd3 :
                         req2[2] ? 3'd2 :
                         req2[1] ? 3'd1 : 3'd0;

    // stage 1: captured request vector plus its encoding
    reg [7:0] q_req;
    reg       q_valid;
    reg [2:0] q_index;
   reg       q2_valid;
   reg [2:0] q2_index;
   // the output stage is a single shared port: alternate which grant slot
   // drains through it each beat
   reg       sel;

    initial begin
        q_req   = 8'h00;
        q_valid = 1'b0;
        q_index = 3'd0;
       q2_valid = 1'b0;
       q2_index = 3'd0;
       sel      = 1'b0;
        y_valid = 1'b0;
        y_index = 3'd0;
        y_bit   = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            q_req   <= 8'h00;
            q_valid <= 1'b0;
            q_index <= 3'd0;
           q2_valid <= 1'b0;
           q2_index <= 3'd0;
           sel      <= 1'b0;
        end else if (i_ce) begin
            q_req   <= req;
            q_valid <= c_valid;
            q_index <= c_index;
           q2_valid <= c2_valid;
           q2_index <= c2_index;
           sel      <= ~sel;
        end
    end

    // stage 2: registered output stage, samples the selected bit out of the
    // captured vector using the captured index
    always @(posedge clk) begin
        if (rst) begin
            y_valid <= 1'b0;
            y_index <= 3'd0;
            y_bit   <= 1'b0;
        end else if (i_ce) begin
           y_valid <= sel ? q2_valid : q_valid;
           y_index <= sel ? q2_index : q_index;
           y_bit   <= q_req[sel ? q2_index : q_index];
        end
    end

    // property: a granted output must point at a bit that was actually set
    always @(posedge clk)
        if (y_valid)
            assert (y_bit == 1'b1);
endmodule

module prio_pipe (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] req,
    output reg b_valid,
    output reg [2:0] b_idx
);
    reg [7:0] a_vec;
    reg       a_valid;
reg [7:0] m_vec;
reg       m_valid;
reg       m_hi;
reg [3:0] m_nib;
    reg [7:0] b_vec;

    initial begin
        a_vec = 8'h00; a_valid = 1'b0;
m_vec = 8'h00; m_valid = 1'b0; m_hi = 1'b0; m_nib = 4'h0;
        b_vec = 8'h00; b_idx = 3'd0; b_valid = 1'b0;
    end

    // stage 1 -> stage M: pick which nibble owns the highest-priority bit
    wire       a_hi  = (a_vec[7:4] != 4'h0);
    wire [3:0] a_nib = a_hi ? a_vec[7:4] : a_vec[3:0];

    // stage M -> stage B: resolve the position inside the captured nibble
    wire [1:0] m_sub = m_nib[3] ? 2'd3 :
                       m_nib[2] ? 2'd2 :
                       m_nib[1] ? 2'd1 : 2'd0;

    always @(posedge clk) begin
        if (rst) begin
            a_vec <= 8'h00; a_valid <= 1'b0;
m_vec <= 8'h00; m_valid <= 1'b0; m_hi <= 1'b0; m_nib <= 4'h0;
            b_vec <= 8'h00; b_idx <= 3'd0; b_valid <= 1'b0;
        end else if (ce) begin
            a_vec   <= req;
            a_valid <= (req != 8'h00);
            m_vec   <= a_vec;
            m_valid <= a_valid;
            m_hi    <= a_hi;
            m_nib   <= a_nib;
            b_vec   <= m_vec;
            b_idx   <= {m_hi, m_sub};
            b_valid <= m_valid;
        end
    end

    always @(posedge clk)
        if (b_valid)
            assert (b_vec[b_idx]);
endmodule

module ring_occ (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    output reg  [2:0] count,
    output reg  [3:0] occ
);
    reg [1:0] wptr, rptr;
   reg [1:0] bwptr, brptr;
   reg [2:0] bcount;
   reg [3:0] bocc;
   reg [2:0] credit;
   reg       sel, psel;
  reg       stg_v;
  reg [1:0] stg_ptr;
    initial begin wptr = 2'd0; rptr = 2'd0; count = 3'd0; occ = 4'b0000; end
   initial begin bwptr = 2'd0; brptr = 2'd0; bcount = 3'd0; bocc = 4'b0000; credit = 3'd4; sel = 1'b0; psel = 1'b0; end
  initial begin stg_v = 1'b0; stg_ptr = 2'd0; end

  wire ring_full = ((wptr - rptr) == 2'd0) && (stg_v || count != 3'd0);
  wire push_ok = push && (credit != 3'd0) && !(ring_full && !sel);
   wire do_push = push_ok && !sel;
   wire push_b  = push_ok &&  sel;
   wire pop_b   = pop && bocc[brptr] && (psel || (count == 3'd0));
   wire do_pop  = pop && (count != 3'd0) && !pop_b;

   wire [3:0] set_bit = stg_v ? (4'b0001 << stg_ptr) : 4'b0000;
    wire [3:0] clr_bit = do_pop  ? (4'b0001 << rptr) : 4'b0000;
   wire [3:0] bset_bit = push_b ? (4'b0001 << bwptr) : 4'b0000;
   wire [3:0] bclr_bit = pop_b  ? (4'b0001 << brptr) : 4'b0000;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
            occ   <= 4'b0000;
           bwptr  <= 2'd0;
           brptr  <= 2'd0;
           bcount <= 3'd0;
           bocc   <= 4'b0000;
           credit <= 3'd4;
           sel    <= 1'b0;
           psel   <= 1'b0;
          stg_v   <= 1'b0;
          stg_ptr <= 2'd0;
        end else begin
            if (do_push) wptr <= wptr + 2'd1;
            if (do_pop)  rptr <= rptr + 2'd1;
           stg_v <= do_push;
           if (stg_v) stg_ptr <= stg_ptr + 2'd1;
            occ <= (occ | set_bit) & ~clr_bit;
           case ({stg_v, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase
           if (push_b) bwptr <= bwptr + 2'd1;
           if (pop_b)  brptr <= brptr + 2'd1;
           bocc <= (bocc | bset_bit) & ~bclr_bit;
           case ({push_b, pop_b})
               2'b10:   bcount <= bcount + 3'd1;
               2'b01:   bcount <= bcount - 3'd1;
               default: bcount <= bcount;
           endcase
           case ({push_ok, do_pop || pop_b})
               2'b10:   credit <= credit - 3'd1;
               2'b01:   credit <= credit + 3'd1;
               default: credit <= credit;
           endcase
           if (push_ok) sel <= ~sel;
           if (do_pop)     psel <= 1'b1;
           else if (pop_b) psel <= 1'b0;
        end
    end

    always @(posedge clk)
        if (count == 3'd1)
            assert (occ == 4'b0001 || occ == 4'b0010 ||
                    occ == 4'b0100 || occ == 4'b1000);
endmodule

module pwm_dimmer (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] duty_in,
    output wire pwm_out
);
    reg [7:0] cnt      = 8'd0;   // free-running ramp
    reg [7:0] duty_reg = 8'd0;   // duty latched at period start
    reg [7:0] high_cnt = 8'd0;   // high-time accumulated this period
    reg [3:0] hi_pend  = 4'd0;   // high cycles waiting to be folded into the accumulator
    reg       hi_q     = 1'b0;   // compare result, registered ahead of the accumulator
    reg [7:0] duty_cap = 8'd0;   // duty request captured at ramp end, after foldback clamp

    localparam [7:0] HI_LIMIT = 8'd192; // high cycles per period allowed by thermal budget

    always @(posedge clk)
        if (rst) begin
            cnt      <= 8'd0;
            duty_reg <= 8'd0;
            high_cnt <= 8'd0;
            hi_pend  <= 4'd0;
            hi_q     <= 1'b0;
            duty_cap <= 8'd0;
        end else if (ce) begin
            if (cnt == 8'd0) begin
                duty_reg <= duty_cap;
                high_cnt <= 8'd0;
                hi_pend  <= 4'd0;
                hi_q     <= (duty_cap != 8'd0);
                cnt      <= 8'd1;
            end else if (cnt == 8'hFF) begin
                duty_cap <= ((high_cnt + {4'd0, hi_pend}) >= HI_LIMIT) ? HI_LIMIT : duty_in;
                cnt      <= 8'd0;
                high_cnt <= 8'd0;
                hi_pend  <= 4'd0;
                hi_q     <= 1'b0;
            end else begin
                cnt      <= cnt + 8'd1;
                if (cnt[2:0] == 3'b111) begin
                    high_cnt <= high_cnt + {4'd0, hi_pend} + {7'd0, hi_q};
                    hi_pend  <= 4'd0;
                end else begin
                    hi_pend  <= hi_pend + {3'd0, hi_q};
                end
                hi_q     <= (cnt < duty_reg);
            end
        end

    assign pwm_out = (cnt < duty_reg);

    always @(posedge clk)
        if (pwm_out)
            assert (high_cnt < duty_reg);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
output reg tokens_hi,
output reg [3:0] drip_count
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;
initial drip_count = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
drip_count <= 4'd0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
if (drip_en && drip_count != 4'd15) drip_count <= drip_count + 4'd1;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module credit_pool_top (
    input wire clk,
    input wire rst,
    input wire [3:0] req,
    input wire [3:0] rel,
    output reg [3:0] pool,
    output wire [4:0] total_tokens,
    output wire [3:0] hi_flags
);
    localparam [3:0] TOTAL = 4'd8;

    wire [2:0] t0, t1, t2, t3;
    wire       h0, h1, h2, h3;
    wire [3:0] dc0, dc1, dc2, dc3;

    reg [1:0] rr_ptr;

    wire want0 = req[0] && (t0 != 3'd4) && !(rel[0] && (t0 != 3'd0));
    wire want1 = req[1] && (t1 != 3'd4) && !(rel[1] && (t1 != 3'd0));
    wire want2 = req[2] && (t2 != 3'd4) && !(rel[2] && (t2 != 3'd0));
    wire want3 = req[3] && (t3 != 3'd4) && !(rel[3] && (t3 != 3'd0));
    wire [3:0] want = {want3, want2, want1, want0};

    wire [1:0] p0 = rr_ptr;
    wire [1:0] p1 = rr_ptr + 2'd1;
    wire [1:0] p2 = rr_ptr + 2'd2;
    wire [1:0] p3 = rr_ptr + 2'd3;

    wire [1:0] sel_idx = want[p0] ? p0 :
                         want[p1] ? p1 :
                         want[p2] ? p2 : p3;

    wire grant_any = (want != 4'd0) && (pool != 4'd0);
    wire grant0 = grant_any && (sel_idx == 2'd0);
    wire grant1 = grant_any && (sel_idx == 2'd1);
    wire grant2 = grant_any && (sel_idx == 2'd2);
    wire grant3 = grant_any && (sel_idx == 2'd3);

    token_bucket u0 (.clk(clk), .rst(rst), .drip(grant0), .spend(rel[0]),
                     .tokens(t0), .tokens_hi(h0), .drip_count(dc0));
    token_bucket u1 (.clk(clk), .rst(rst), .drip(grant1), .spend(rel[1]),
                     .tokens(t1), .tokens_hi(h1), .drip_count(dc1));
    token_bucket u2 (.clk(clk), .rst(rst), .drip(grant2), .spend(rel[2]),
                     .tokens(t2), .tokens_hi(h2), .drip_count(dc2));
    token_bucket u3 (.clk(clk), .rst(rst), .drip(grant3), .spend(rel[3]),
                     .tokens(t3), .tokens_hi(h3), .drip_count(dc3));

    wire dec0 = rel[0] && (t0 != 3'd0) && !grant0;
    wire dec1 = rel[1] && (t1 != 3'd0) && !grant1;
    wire dec2 = rel[2] && (t2 != 3'd0) && !grant2;
    wire dec3 = rel[3] && (t3 != 3'd0) && !grant3;

    wire [2:0] ret = {2'b00, dec0} + {2'b00, dec1} +
                     {2'b00, dec2} + {2'b00, dec3};

    assign total_tokens = {2'b00, t0} + {2'b00, t1} +
                          {2'b00, t2} + {2'b00, t3};
    assign hi_flags = {h3, h2, h1, h0};

    initial pool   = TOTAL;
    initial rr_ptr = 2'd0;

    always @(posedge clk) begin
        if (rst) begin
            pool   <= TOTAL;
            rr_ptr <= 2'd0;
        end else begin
            pool <= pool - {3'b000, grant_any} + {1'b0, ret};
            if (grant_any) rr_ptr <= sel_idx + 2'd1;
        end
    end

    always @(posedge clk)
        if (pool == 4'd0) assert (h0 || h1 || h2 || h3);
endmodule

module rr_arbiter_pri (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire [3:0] req,
    output wire [3:0] gnt,
    output reg  [3:0] pri,
    output reg  [1:0] idx
);
    initial pri = 4'b0001;
    initial idx = 2'd0;

   reg [1:0] hold_cnt;   // cycles left in the current grant burst
   initial hold_cnt = 2'd0;

  reg        parked;     // arbiter folded to quiescent outputs while idle
  reg  [1:0] park_idx;   // rotating pointer position retained while parked
  initial parked = 1'b0;
  initial park_idx = 2'd0;

    // only the requester currently pointed at by the rotating priority wins
    assign gnt = req & pri;

    wire low_pri = pri[0] | pri[1];   // priority pointer sits in lower half
    wire idx_hi  = idx[1];            // binary index says upper half

   wire hold_active  = (hold_cnt != 2'd0);
   // a fresh grant opens a burst; the pointer moves on the last burst cycle,
   // or right away when the requester it points at has nothing pending
   wire burst_start  = (|gnt) && !hold_active;
   wire rotate       = step && ((hold_cnt == 2'd1) || (!hold_active && !(|gnt)));

  // nothing to serve: fold the pointer away into park_idx and drive the
  // outputs quiet; wake and reload the pointer when a request shows up
  wire idle    = (req == 4'b0000) && !hold_active;
  wire go_park = step && !parked && idle;
  wire wake    = step && parked && (req != 4'b0000);

    always @(posedge clk) begin
        if (rst) begin
            pri <= 4'b0001;
            idx <= 2'd0;
           hold_cnt <= 2'd0;
          parked   <= 1'b0;
          park_idx <= 2'd0;
       end else begin
          if (go_park) begin
              parked   <= 1'b1;
              park_idx <= idx;
              pri      <= 4'b0000;
              idx      <= 2'd0;
          end else if (wake) begin
              parked <= 1'b0;
              pri    <= (4'b0001 << park_idx);
              idx    <= park_idx;
          end else if (rotate && !parked) begin
              pri <= {pri[2:0], pri[3]};
              idx <= idx + 2'd1;
          end
           if (burst_start)
               hold_cnt <= 2'd3;
           else if (step && hold_active)
               hold_cnt <= hold_cnt - 2'd1;
       end
    end

    always @(posedge clk)
        if (|gnt)
            assert (!(low_pri && idx_hi));

   // the binary index must always name the requester that is being granted
   always @(posedge clk)
       if (|gnt)
           assert (gnt[idx]);
endmodule

module alu_accum_slice (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire       i_sub,
    output reg  [7:0] o_result,
    output wire       o_zero
);
    reg [6:0] half;
   // every eighth enabled operation the slice takes a double step, so the
   // accumulator keeps up with the externally scaled sample rate
   reg [2:0] phase;
   wire      dbl = (phase == 3'd7);


    initial o_result = 8'd0;
    initial half     = 7'd0;
   initial phase    = 3'd0;

    assign o_zero = (o_result == 8'd0);

    always @(posedge clk) begin
        if (rst) begin
            o_result <= 8'd0;
            half     <= 7'd0;
           phase    <= 3'd0;
        end else if (i_ce) begin
           o_result <= i_sub ? (o_result - (dbl ? 8'd4 : 8'd2))
                             : (o_result + (dbl ? 8'd4 : 8'd2));
           half     <= i_sub ? (half     - (dbl ? 7'd2 : 7'd1))
                             : (half     + (dbl ? 7'd2 : 7'd1));
           phase    <= phase + 3'd1;
        end
    end

    // P: whenever the half-step tracker is at zero, the registered ALU result is zero
    always @(posedge clk)
        if (half == 7'd0)
            assert (o_result == 8'd0);

   // Q: the accumulator can only read zero while the half-step tracker is at zero
   always @(posedge clk)
       if (o_zero)
           assert (half == 7'd0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module token_bucket_pool (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] drip_req,
    input  wire [5:0] spend_req,
    output reg  [3:0] pool,
    output wire [5:0] hi_flags,
    output reg        starved
);
    localparam [3:0] TOTAL = 4'd8;

    // per-instance observable state
    wire [2:0] t0, t1, t2, t3, t4, t5;
    wire       h0, h1, h2, h3, h4, h5;

    // a bucket wants a credit only if the drip would really land:
    // not already full, and not cancelled by a concurrent accepted spend
    wire [5:0] want;
    assign want[0] = drip_req[0] && (t0 != 3'd4) && !(spend_req[0] && (t0 != 3'd0));
    assign want[1] = drip_req[1] && (t1 != 3'd4) && !(spend_req[1] && (t1 != 3'd0));
    assign want[2] = drip_req[2] && (t2 != 3'd4) && !(spend_req[2] && (t2 != 3'd0));
    assign want[3] = drip_req[3] && (t3 != 3'd4) && !(spend_req[3] && (t3 != 3'd0));
    assign want[4] = drip_req[4] && (t4 != 3'd4) && !(spend_req[4] && (t4 != 3'd0));
    assign want[5] = drip_req[5] && (t5 != 3'd4) && !(spend_req[5] && (t5 != 3'd0));

    wire credit_avail = (pool != 4'd0);

    // one credit per cycle, fixed priority
    wire [5:0] grant;
    assign grant[0] = credit_avail && want[0];
    assign grant[1] = credit_avail && want[1] && !want[0];
    assign grant[2] = credit_avail && want[2] && !want[0] && !want[1];
    assign grant[3] = credit_avail && want[3] && !want[0] && !want[1] && !want[2];
    assign grant[4] = credit_avail && want[4] && !want[0] && !want[1] && !want[2] && !want[3];
    assign grant[5] = credit_avail && want[5] && !want[0] && !want[1] && !want[2] && !want[3] && !want[4];
    wire grant_any = grant[0] || grant[1] || grant[2] || grant[3] || grant[4] || grant[5];

   // the arbitration result is registered before it reaches the buckets: the
   // credit leaves the pool in the grant cycle, the drip lands the cycle after
   reg  [5:0] grant_q;
   wire       inflight = (grant_q != 6'd0);

   // a bucket may have filled up, or be spending, by the time the staged drip
   // arrives; a drip that cannot land refunds its credit to the pool
   wire [5:0] landed;
   assign landed[0] = grant_q[0] && (t0 != 3'd4) && !(spend_req[0] && (t0 != 3'd0));
   assign landed[1] = grant_q[1] && (t1 != 3'd4) && !(spend_req[1] && (t1 != 3'd0));
   assign landed[2] = grant_q[2] && (t2 != 3'd4) && !(spend_req[2] && (t2 != 3'd0));
   assign landed[3] = grant_q[3] && (t3 != 3'd4) && !(spend_req[3] && (t3 != 3'd0));
   assign landed[4] = grant_q[4] && (t4 != 3'd4) && !(spend_req[4] && (t4 != 3'd0));
   assign landed[5] = grant_q[5] && (t5 != 3'd4) && !(spend_req[5] && (t5 != 3'd0));
   wire landed_any = landed[0] || landed[1] || landed[2] || landed[3] || landed[4] || landed[5];
   wire refund = inflight && !landed_any;

    // a released token returns its credit
    wire [5:0] rel;
   assign rel[0] = spend_req[0] && (t0 != 3'd0) && !(grant_q[0] && (t0 != 3'd4));
   assign rel[1] = spend_req[1] && (t1 != 3'd0) && !(grant_q[1] && (t1 != 3'd4));
   assign rel[2] = spend_req[2] && (t2 != 3'd0) && !(grant_q[2] && (t2 != 3'd4));
   assign rel[3] = spend_req[3] && (t3 != 3'd0) && !(grant_q[3] && (t3 != 3'd4));
   assign rel[4] = spend_req[4] && (t4 != 3'd0) && !(grant_q[4] && (t4 != 3'd4));
   assign rel[5] = spend_req[5] && (t5 != 3'd0) && !(grant_q[5] && (t5 != 3'd4));

    wire [3:0] rel_cnt = {3'd0, rel[0]} + {3'd0, rel[1]} + {3'd0, rel[2]} +
                         {3'd0, rel[3]} + {3'd0, rel[4]} + {3'd0, rel[5]};

   token_bucket u0 (.clk(clk), .rst(rst), .drip(grant_q[0]), .spend(spend_req[0]), .tokens(t0), .tokens_hi(h0));
   token_bucket u1 (.clk(clk), .rst(rst), .drip(grant_q[1]), .spend(spend_req[1]), .tokens(t1), .tokens_hi(h1));
   token_bucket u2 (.clk(clk), .rst(rst), .drip(grant_q[2]), .spend(spend_req[2]), .tokens(t2), .tokens_hi(h2));
   token_bucket u3 (.clk(clk), .rst(rst), .drip(grant_q[3]), .spend(spend_req[3]), .tokens(t3), .tokens_hi(h3));
   token_bucket u4 (.clk(clk), .rst(rst), .drip(grant_q[4]), .spend(spend_req[4]), .tokens(t4), .tokens_hi(h4));
   token_bucket u5 (.clk(clk), .rst(rst), .drip(grant_q[5]), .spend(spend_req[5]), .tokens(t5), .tokens_hi(h5));

    assign hi_flags = {h5, h4, h3, h2, h1, h0};

   initial grant_q = 6'd0;

    initial pool    = TOTAL;
    initial starved = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            pool    <= TOTAL;
           grant_q <= 6'd0;
            starved <= 1'b0;
        end else begin
           grant_q <= grant;
           pool <= pool + rel_cnt + {3'd0, refund} - {3'd0, grant_any};
            if (pool == 4'd0) starved <= 1'b1;
        end
    end

    // when the pool is exhausted all credits sit in the buckets, so at least
    // one bucket must be above its high-water mark
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 || h1 || h2 || h3 || h4 || h5);
endmodule

module strcount_pipe (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire flush,
    input wire [7:0] ch,
    output wire [5:0] o_cnt
);
    parameter [7:0] TARGET = 8'h61;

    reg [5:0] total = 6'd0;   // characters accepted
    reg [5:0] cnt   = 6'd0;   // committed occurrences of TARGET
    reg       st_valid = 1'b0; // staged character present
    reg       st_match = 1'b0; // staged character equals TARGET
    reg [2:0] pend = 3'd0;    // occurrences held locally, not yet merged into cnt

    wire full   = (total == 6'd63);
    wire accept = ce && !full;
    wire retire = st_valid && st_match;   // staged match leaves the stage this cycle
    wire dump   = (pend == 3'd3);         // local accumulator full: merge a block of 4

    always @(posedge clk)
        if (rst) begin
            total    <= 6'd0;
            cnt      <= 6'd0;
            st_valid <= 1'b0;
            st_match <= 1'b0;
            pend     <= 3'd0;
        end else if (accept) begin
            total    <= total + 6'd1;
            st_valid <= 1'b1;
            st_match <= (ch == TARGET);
            if (retire) begin
                if (dump) begin
                    cnt  <= cnt + 6'd4;
                    pend <= 3'd0;
                end else
                    pend <= pend + 3'd1;
            end
        end else if (flush && st_valid) begin
            st_valid <= 1'b0;
            if (st_match) begin
                if (dump) begin
                    cnt  <= cnt + 6'd4;
                    pend <= 3'd0;
                end else
                    pend <= pend + 3'd1;
            end
        end

    assign o_cnt = cnt + {3'd0, pend};

    always @(*)
        if (!st_valid)
            assert (cnt <= total);
endmodule

module token_bucket_ledger (
    input  wire       clk,
    input  wire       rst,
    input  wire       drip_en,
    input  wire       grant_req,
    output wire       grant,
    output wire       dry
);
    localparam [3:0] CAP = 4'd8;

    // bucket level
    reg [3:0] tokens = 4'd0;
    // free-running mod-16 ledgers of every accepted drip and every issued grant
    reg [3:0] drips  = 4'd0;
    reg [3:0] grants = 4'd0;

   // accepted drips are shaped: a credit spends four cycles in flight before it
   // actually lands in the bucket, at most one credit per stage
   reg        drip_s1 = 1'b0;
   reg        drip_s2 = 1'b0;
   reg        drip_s3 = 1'b0;
   reg        drip_s4 = 1'b0;

   wire [3:0] in_flight = {3'd0, drip_s1} + {3'd0, drip_s2}
                        + {3'd0, drip_s3} + {3'd0, drip_s4};


   // credits already promised to the bucket count against the cap at accept time
   wire do_drip  = drip_en   && ((tokens + in_flight) < CAP);
    wire do_grant = grant_req && (tokens != 4'd0);
   wire land     = drip_s4;

    assign grant = do_grant;
    assign dry   = (tokens == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            tokens <= 4'd0;
            drips  <= 4'd0;
            grants <= 4'd0;
           drip_s1 <= 1'b0;
           drip_s2 <= 1'b0;
           drip_s3 <= 1'b0;
           drip_s4 <= 1'b0;
        end else begin
           if (land && !do_grant)
                tokens <= tokens + 4'd1;
           else if (!land && do_grant)
                tokens <= tokens - 4'd1;

           drip_s1 <= do_drip;
           drip_s2 <= drip_s1;
           drip_s3 <= drip_s2;
           drip_s4 <= drip_s3;

            if (do_drip)
                drips <= drips + 4'd1;
            if (do_grant)
                grants <= grants + 4'd1;
        end
    end

    // P: whenever the two ledgers agree, the bucket must be empty
    always @(posedge clk)
        if (drips == grants)
            assert (tokens == 4'd0);
endmodule

module stack_occupancy (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    output reg [2:0] sp,
    output reg [2:0] items,
output reg top_valid,
output reg [2:0] push_cnt,
output reg [2:0] pop_cnt
);
reg full;
reg empty;
reg full_nxt;
reg empty_nxt;
    initial sp = 3'd0;
    initial items = 3'd0;
    initial top_valid = 1'b0;
initial full = 1'b0;
initial empty = 1'b1;
initial push_cnt = 3'd0;
initial pop_cnt = 3'd0;

// registered level flags: the push/pop acceptance gates are flopped so the
// datapath does not have to compare the pointer in the same cycle
wire do_push = push && !full;
wire do_pop  = pop && !empty;

always @(*) begin
    full_nxt  = full;
    empty_nxt = empty;
    if (do_push) begin
        full_nxt  = (sp == 3'd3);
        empty_nxt = 1'b0;
    end else if (do_pop) begin
        full_nxt  = 1'b0;
        empty_nxt = (sp == 3'd1);
    end
end


    always @(posedge clk) begin
        if (rst) begin
            sp        <= 3'd0;
            items     <= 3'd0;
            top_valid <= 1'b0;
full      <= 1'b0;
empty     <= 1'b1;
push_cnt  <= 3'd0;
pop_cnt   <= 3'd0;
end else begin
    if (do_push) begin
        sp       <= sp + 3'd1;
        items    <= items + 3'd1;
        push_cnt <= push_cnt + 3'd1;
    end else if (do_pop) begin
        sp       <= sp - 3'd1;
        items    <= items - 3'd1;
        pop_cnt  <= pop_cnt + 3'd1;
    end
    // traffic ledger for the debug interface: wraps freely, never cleared
    full      <= full_nxt;
    empty     <= empty_nxt;
    top_valid <= !empty_nxt;
end
    end

    // P: an empty stack (per the occupancy counter) must not advertise a valid top
    always @(posedge clk)
        if (items == 3'd0)
            assert (top_valid == 1'b0);
endmodule

module stack_occupancy (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    output reg [2:0] sp,
    output reg [2:0] items,
output reg top_valid,
output reg [2:0] n_push,
output reg [2:0] n_pop
);
    initial sp = 3'd0;
    initial items = 3'd0;
    initial top_valid = 1'b0;
initial n_push = 3'd0;
initial n_pop = 3'd0;

// occupancy as reported by the push/pop transaction ledger
wire [2:0] net_depth = n_push - n_pop;

    always @(posedge clk) begin
        if (rst) begin
            sp        <= 3'd0;
            items     <= 3'd0;
            top_valid <= 1'b0;
n_push    <= 3'd0;
n_pop     <= 3'd0;
        end else if (push && sp != 3'd4) begin
            sp        <= sp + 3'd1;
            items     <= items + 3'd1;
            top_valid <= 1'b1;
n_push    <= n_push + 3'd1;
        end else if (pop && sp != 3'd0) begin
            sp        <= sp - 3'd1;
            items     <= items - 3'd1;
top_valid <= (net_depth != 3'd1);
n_pop     <= n_pop + 3'd1;
        end
    end

    // P: an empty stack (per the occupancy counter) must not advertise a valid top
    always @(posedge clk)
        if (items == 3'd0)
            assert (top_valid == 1'b0);
endmodule

module stack_occupancy (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    output reg [2:0] sp,
    output reg [2:0] items,
output reg top_valid,
output reg [3:0] n_push,
output reg [3:0] n_pop,
output reg full
);
    initial sp = 3'd0;
    initial items = 3'd0;
    initial top_valid = 1'b0;
initial n_push = 4'd0;
initial n_pop  = 4'd0;
initial full   = 1'b0;

// Transaction ledger: every accepted push and pop is logged.  The fill-level
// flag that back-pressures the push port is recomputed from the logged depth,
// so the pointer itself is never compared against the stack size.
wire [3:0] depth_now = n_push - n_pop;

    always @(posedge clk) begin
        if (rst) begin
            sp        <= 3'd0;
            items     <= 3'd0;
            top_valid <= 1'b0;
n_push    <= 4'd0;
n_pop     <= 4'd0;
full      <= 1'b0;
end else if (push && !full) begin
            sp        <= sp + 3'd1;
            items     <= items + 3'd1;
            top_valid <= 1'b1;
n_push    <= n_push + 4'd1;
full      <= ((depth_now + 4'd1) == 4'd4);
        end else if (pop && sp != 3'd0) begin
            sp        <= sp - 3'd1;
            items     <= items - 3'd1;
            top_valid <= (sp != 3'd1);
n_pop     <= n_pop + 4'd1;
full      <= ((depth_now - 4'd1) == 4'd4);
        end
    end

    // P: an empty stack (per the occupancy counter) must not advertise a valid top
    always @(posedge clk)
        if (items == 3'd0)
            assert (top_valid == 1'b0);
endmodule

module stack_occupancy (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    output reg [2:0] sp,
    output reg [2:0] items,
output reg top_valid,
output reg [2:0] n_push,
output reg [2:0] n_pop
);
    initial sp = 3'd0;
    initial items = 3'd0;
    initial top_valid = 1'b0;
initial n_push = 3'd0;
initial n_pop = 3'd0;

// occupancy as reported by the push/pop transaction ledger
wire [2:0] net_depth = n_push - n_pop;

    always @(posedge clk) begin
        if (rst) begin
            sp        <= 3'd0;
            items     <= 3'd0;
            top_valid <= 1'b0;
n_push    <= 3'd0;
n_pop     <= 3'd0;
        end else if (push && sp != 3'd4) begin
            sp        <= sp + 3'd1;
            items     <= items + 3'd1;
            top_valid <= 1'b1;
n_push    <= n_push + 3'd1;
        end else if (pop && sp != 3'd0) begin
            sp        <= sp - 3'd1;
            items     <= items - 3'd1;
top_valid <= (net_depth != 3'd1);
n_pop     <= n_pop + 3'd1;
        end
    end

    // P: an empty stack (per the occupancy counter) must not advertise a valid top
    always @(posedge clk)
        if (items == 3'd0)
            assert (top_valid == 1'b0);
endmodule

module credit_pooled_stacks (
    input wire clk,
    input wire rst,
    input wire [3:0] push_req,
    input wire [3:0] pop_req,
    output reg [3:0] pool,
    output wire [3:0] occ_mask,
    output wire [3:0] grant_o
);
    // shared buffer pool: 8 entries handed out to four stacks
    initial pool = 4'd8;

    // round-robin starting index for the push arbiter
    reg [1:0] ptr;
    initial ptr = 2'd0;

    // per-instance observable state
    wire [2:0] t0, t1, t2, t3;      // stack pointers
    wire [2:0] it0, it1, it2, it3;  // occupancy counters
    wire h0, h1, h2, h3;            // top_valid flags
    wire [2:0] np0, np1, np2, np3;  // push ledger
    wire [2:0] nq0, nq1, nq2, nq3;  // pop ledger

    wire [3:0] full_mask  = {t3 == 3'd4, t2 == 3'd4, t1 == 3'd4, t0 == 3'd4};
    wire [3:0] nonempty   = {t3 != 3'd0, t2 != 3'd0, t1 != 3'd0, t0 != 3'd0};
    wire       pool_has   = (pool != 4'd0);

    // a push is eligible only if a credit is free and the stack has room
    wire [3:0] elig = push_req & ~full_mask & {4{pool_has}};

    reg [3:0] grant;
    always @(*) begin
        grant = 4'b0000;
        case (ptr)
            2'd0: begin
                if (elig[0])      grant = 4'b0001;
                else if (elig[1]) grant = 4'b0010;
                else if (elig[2]) grant = 4'b0100;
                else if (elig[3]) grant = 4'b1000;
            end
            2'd1: begin
                if (elig[1])      grant = 4'b0010;
                else if (elig[2]) grant = 4'b0100;
                else if (elig[3]) grant = 4'b1000;
                else if (elig[0]) grant = 4'b0001;
            end
            2'd2: begin
                if (elig[2])      grant = 4'b0100;
                else if (elig[3]) grant = 4'b1000;
                else if (elig[0]) grant = 4'b0001;
                else if (elig[1]) grant = 4'b0010;
            end
            default: begin
                if (elig[3])      grant = 4'b1000;
                else if (elig[0]) grant = 4'b0001;
                else if (elig[1]) grant = 4'b0010;
                else if (elig[2]) grant = 4'b0100;
            end
        endcase
    end

    wire [1:0] gidx = grant[0] ? 2'd0 : grant[1] ? 2'd1 : grant[2] ? 2'd2 : 2'd3;

    // pops that actually retire an entry (push wins the port on that stack)
    wire [3:0] pop_go = pop_req & ~grant & nonempty;

    wire [2:0] pops = {2'd0, pop_go[0]} + {2'd0, pop_go[1]} +
                      {2'd0, pop_go[2]} + {2'd0, pop_go[3]};

    assign occ_mask = {h3, h2, h1, h0};
    assign grant_o  = grant;

    stack_occupancy u0 (
        .clk(clk), .rst(rst), .push(grant[0]), .pop(pop_go[0]),
        .sp(t0), .items(it0), .top_valid(h0), .n_push(np0), .n_pop(nq0)
    );
    stack_occupancy u1 (
        .clk(clk), .rst(rst), .push(grant[1]), .pop(pop_go[1]),
        .sp(t1), .items(it1), .top_valid(h1), .n_push(np1), .n_pop(nq1)
    );
    stack_occupancy u2 (
        .clk(clk), .rst(rst), .push(grant[2]), .pop(pop_go[2]),
        .sp(t2), .items(it2), .top_valid(h2), .n_push(np2), .n_pop(nq2)
    );
    stack_occupancy u3 (
        .clk(clk), .rst(rst), .push(grant[3]), .pop(pop_go[3]),
        .sp(t3), .items(it3), .top_valid(h3), .n_push(np3), .n_pop(nq3)
    );

    always @(posedge clk) begin
        if (rst) begin
            pool <= 4'd8;
            ptr  <= 2'd0;
        end else begin
            pool <= pool - {3'd0, (|grant)} + {1'b0, pops};
            ptr  <= (|grant) ? (gidx + 2'd1) : ptr;
        end
    end

    // Q: when the pool reports every entry free, no stack may advertise data
    always @(posedge clk)
        if (pool == 4'd8)
            assert (occ_mask == 4'b0000);
endmodule

module stack_occupancy (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    output reg [2:0] sp,
    output reg [2:0] items,
output reg top_valid,
output reg [3:0] n_push,
output reg [3:0] n_pop,
output reg full
);
    initial sp = 3'd0;
    initial items = 3'd0;
    initial top_valid = 1'b0;
initial n_push = 4'd0;
initial n_pop  = 4'd0;
initial full   = 1'b0;

// Transaction ledger: every accepted push and pop is logged.  The fill-level
// flag that back-pressures the push port is recomputed from the logged depth,
// so the pointer itself is never compared against the stack size.
wire [3:0] depth_now = n_push - n_pop;

    always @(posedge clk) begin
        if (rst) begin
            sp        <= 3'd0;
            items     <= 3'd0;
            top_valid <= 1'b0;
n_push    <= 4'd0;
n_pop     <= 4'd0;
full      <= 1'b0;
end else if (push && !full) begin
            sp        <= sp + 3'd1;
            items     <= items + 3'd1;
            top_valid <= 1'b1;
n_push    <= n_push + 4'd1;
full      <= ((depth_now + 4'd1) == 4'd4);
        end else if (pop && sp != 3'd0) begin
            sp        <= sp - 3'd1;
            items     <= items - 3'd1;
            top_valid <= (sp != 3'd1);
n_pop     <= n_pop + 4'd1;
full      <= ((depth_now - 4'd1) == 4'd4);
        end
    end

    // P: an empty stack (per the occupancy counter) must not advertise a valid top
    always @(posedge clk)
        if (items == 3'd0)
            assert (top_valid == 1'b0);
endmodule

module stack_pool (
    input  wire       clk,
    input  wire       rst,
    input  wire [3:0] push_req,
    input  wire [3:0] pop_req,
    output reg  [3:0] pool,
    output wire [3:0] grant,
    output wire [3:0] pop_ack,
    output wire [3:0] valid_top,
    output wire [3:0] busy
);
    // Shared depth budget for the four stacks.  A stack may only take a new
    // entry when the pool still has a free credit; the credit comes back when
    // the entry is popped again.
    localparam [3:0] TOTAL = 4'd8;

    initial pool = TOTAL;

    wire [2:0] sp0, sp1, sp2, sp3;
    wire [2:0] items0, items1, items2, items3;
    wire       t0, t1, t2, t3;
    wire       h0, h1, h2, h3;
    wire [3:0] np0, np1, np2, np3;
    wire [3:0] nq0, nq1, nq2, nq3;

    wire have_credit = (pool != 4'd0);

    // A stack that is already at its own limit does not ask for a credit.
    wire want0 = push_req[0] && !h0;
    wire want1 = push_req[1] && !h1;
    wire want2 = push_req[2] && !h2;
    wire want3 = push_req[3] && !h3;

    // Static priority arbiter: one credit is handed out per cycle at most.
    wire g0 = have_credit && want0;
    wire g1 = have_credit && want1 && !want0;
    wire g2 = have_credit && want2 && !want1 && !want0;
    wire g3 = have_credit && want3 && !want2 && !want1 && !want0;
    wire g_any = g0 || g1 || g2 || g3;

    // The stack core gives its push port priority over its pop port, so a
    // granted cycle never retires an entry.
    wire p0 = !g0 && pop_req[0] && (sp0 != 3'd0);
    wire p1 = !g1 && pop_req[1] && (sp1 != 3'd0);
    wire p2 = !g2 && pop_req[2] && (sp2 != 3'd0);
    wire p3 = !g3 && pop_req[3] && (sp3 != 3'd0);

    wire [2:0] returned = {2'b00, p0} + {2'b00, p1} + {2'b00, p2} + {2'b00, p3};

    always @(posedge clk) begin
        if (rst)
            pool <= TOTAL;
        else
            pool <= pool + {1'b0, returned} - {3'b000, g_any};
    end

    stack_occupancy u0 (
        .clk(clk), .rst(rst), .push(g0), .pop(pop_req[0]),
        .sp(sp0), .items(items0), .top_valid(t0),
        .n_push(np0), .n_pop(nq0), .full(h0)
    );

    stack_occupancy u1 (
        .clk(clk), .rst(rst), .push(g1), .pop(pop_req[1]),
        .sp(sp1), .items(items1), .top_valid(t1),
        .n_push(np1), .n_pop(nq1), .full(h1)
    );

    stack_occupancy u2 (
        .clk(clk), .rst(rst), .push(g2), .pop(pop_req[2]),
        .sp(sp2), .items(items2), .top_valid(t2),
        .n_push(np2), .n_pop(nq2), .full(h2)
    );

    stack_occupancy u3 (
        .clk(clk), .rst(rst), .push(g3), .pop(pop_req[3]),
        .sp(sp3), .items(items3), .top_valid(t3),
        .n_push(np3), .n_pop(nq3), .full(h3)
    );

    assign grant     = {g3, g2, g1, g0};
    assign pop_ack   = {p3, p2, p1, p0};
    assign valid_top = {t3, t2, t1, t0};
    assign busy      = {h3, h2, h1, h0};

    // Pool property: if every credit is back in the pool, no stack can still
    // be advertising a valid top entry.
    always @(posedge clk)
        if (pool == TOTAL)
            assert (!(t0 || t1 || t2 || t3));
endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    output wire       o_done,
    output wire [4:0] o_src_off
);
    parameter [4:0] TOTAL = 5'd20;

    reg [4:0] remaining;
    reg [4:0] sent;
    reg       wr_pend;   // beat issued to the read port, write commits next cycle
    initial remaining = TOTAL;
    initial sent      = 5'd0;
    initial wr_pend   = 1'b0;

    always @(posedge clk)
        if (rst) begin
            remaining <= TOTAL;
            sent      <= 5'd0;
            wr_pend   <= 1'b0;
        end else begin
            if (i_ce && (remaining != 5'd0)) begin
                remaining <= remaining - 5'd1;
                wr_pend   <= 1'b1;
            end else begin
                wr_pend   <= 1'b0;
            end
            if (wr_pend)
                sent <= sent + 5'd1;
        end

    assign o_done    = (remaining == 5'd0) && !wr_pend;
    assign o_src_off = sent;

    always @(*)
        if (o_done)
            assert (sent == TOTAL);
endmodule

module sorted_pair (
    input wire clk,
    input wire rst,
    input wire ins,
    input wire pop,
    input wire [3:0] val,
    output reg [4:0] sum
);
    reg [3:0] k0, k1;
    reg [1:0] count;
    reg [2:0] n_in, n_out;
    initial begin k0 = 0; k1 = 0; count = 0; sum = 0; end
    initial begin n_in = 0; n_out = 0; end

    // occupancy is tracked by the insert/pop event ledger; the difference of
    // the two wrapping counters is the live depth used for flow control
    wire [2:0] net_occ  = n_in - n_out;
    wire occ_full  = (net_occ == 3'd2);
    wire occ_empty = (net_occ == 3'd0);
    wire do_ins = ins && !pop && !occ_full;
    wire do_pop = pop && !ins && !occ_empty;

    always @(posedge clk) begin
        if (rst) begin
            k0 <= 4'd0; k1 <= 4'd0; count <= 2'd0; sum <= 5'd0;
            n_in <= 3'd0; n_out <= 3'd0;
        end else if (do_ins) begin
            if (count == 2'd0) begin
                k0 <= val;
            end else if (val < k0) begin
                k0 <= val; k1 <= k0;
            end else begin
                k1 <= val;
            end
            count <= count + 2'd1;
            sum   <= sum + {1'b0, val};
            n_in  <= n_in + 3'd1;
        end else if (do_pop) begin
            k0    <= k1;
            k1    <= 4'd0;
            count <= count - 2'd1;
            sum   <= sum - {1'b0, k0};
            n_out <= n_out + 3'd1;
        end
    end

    always @(posedge clk)
        if (count == 2'd0)
            assert (sum == 5'd0);
endmodule

module pwm_dimmer_seq (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] duty_in,
    output wire       pwm
);
    // free-running PWM phase counter
    reg [3:0] phase       = 4'd0;
    // rotating one-hot channel selector, advanced once per PWM period
    reg [3:0] chan_sel    = 4'b0001;
    // binary mirror of the selector position
    reg [1:0] idx         = 2'd0;
    // duty latched at the period boundary
    reg [7:0] duty_shadow = 8'd0;

   // channel B: auxiliary dimming engine, staggered two ring slots ahead of
   // channel A so the two banks are never driven in the same slot
   reg [3:0] sel_b       = 4'b0100;
   reg [3:0] duty_b      = 4'd0;

   // only one rotator is instantiated (in channel B); channel A taps the
   // same ring two slots behind it
   wire [3:0] sel_b_next = {sel_b[2:0], sel_b[3]};

   assign pwm = (phase < duty_shadow[7:4]) | (sel_b[0] & (phase < duty_b));

    wire period_end = ce && (phase == 4'd15);

    always @(posedge clk) begin
        if (rst) begin
            phase       <= 4'd0;
            chan_sel    <= 4'b0001;
            idx         <= 2'd0;
            duty_shadow <= 8'd0;
           sel_b       <= 4'b0100;
           duty_b      <= 4'd0;
        end else if (ce) begin
            phase <= phase + 4'd1;
            if (phase == 4'd15) begin
               sel_b       <= sel_b_next;
               chan_sel    <= {sel_b_next[1:0], sel_b_next[3:2]};
                idx         <= idx + 2'd1;
                duty_shadow <= duty_in;
               duty_b      <= duty_in[3:0];
            end
        end
    end

    // P: when the mirror index points at position 0, the one-hot selector
    //    must be sitting on channel 0.
    always @(posedge clk)
        if (idx == 2'd0)
            assert (chan_sel == 4'b0001);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
output reg tokens_hi,
output reg [3:0] drip_count
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;
initial drip_count = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
drip_count <= 4'd0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
if (drip_en && drip_count != 4'd15) drip_count <= drip_count + 4'd1;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module credit_pool_top (
    input wire clk,
    input wire rst,
    input wire [3:0] req,
    input wire [3:0] rel,
    output reg [3:0] pool,
    output wire [4:0] total_tokens,
output wire [3:0] hi_flags,
output reg [3:0] grant_hist
);
    localparam [3:0] TOTAL = 4'd8;

    wire [2:0] t0, t1, t2, t3;
    wire       h0, h1, h2, h3;
    wire [3:0] dc0, dc1, dc2, dc3;

    reg [1:0] rr_ptr;

    wire want0 = req[0] && (t0 != 3'd4) && !(rel[0] && (t0 != 3'd0));
    wire want1 = req[1] && (t1 != 3'd4) && !(rel[1] && (t1 != 3'd0));
    wire want2 = req[2] && (t2 != 3'd4) && !(rel[2] && (t2 != 3'd0));
    wire want3 = req[3] && (t3 != 3'd4) && !(rel[3] && (t3 != 3'd0));
    wire [3:0] want = {want3, want2, want1, want0};

    wire [1:0] p0 = rr_ptr;
    wire [1:0] p1 = rr_ptr + 2'd1;
    wire [1:0] p2 = rr_ptr + 2'd2;
    wire [1:0] p3 = rr_ptr + 2'd3;

    wire [1:0] sel_idx = want[p0] ? p0 :
                         want[p1] ? p1 :
                         want[p2] ? p2 : p3;

    wire grant_any = (want != 4'd0) && (pool != 4'd0);
    wire grant0 = grant_any && (sel_idx == 2'd0);
    wire grant1 = grant_any && (sel_idx == 2'd1);
    wire grant2 = grant_any && (sel_idx == 2'd2);
    wire grant3 = grant_any && (sel_idx == 2'd3);

    token_bucket u0 (.clk(clk), .rst(rst), .drip(grant0), .spend(rel[0]),
                     .tokens(t0), .tokens_hi(h0), .drip_count(dc0));
    token_bucket u1 (.clk(clk), .rst(rst), .drip(grant1), .spend(rel[1]),
                     .tokens(t1), .tokens_hi(h1), .drip_count(dc1));
    token_bucket u2 (.clk(clk), .rst(rst), .drip(grant2), .spend(rel[2]),
                     .tokens(t2), .tokens_hi(h2), .drip_count(dc2));
    token_bucket u3 (.clk(clk), .rst(rst), .drip(grant3), .spend(rel[3]),
                     .tokens(t3), .tokens_hi(h3), .drip_count(dc3));

    wire dec0 = rel[0] && (t0 != 3'd0) && !grant0;
    wire dec1 = rel[1] && (t1 != 3'd0) && !grant1;
    wire dec2 = rel[2] && (t2 != 3'd0) && !grant2;
    wire dec3 = rel[3] && (t3 != 3'd0) && !grant3;

    wire [2:0] ret = {2'b00, dec0} + {2'b00, dec1} +
                     {2'b00, dec2} + {2'b00, dec3};

    assign total_tokens = {2'b00, t0} + {2'b00, t1} +
                          {2'b00, t2} + {2'b00, t3};
    assign hi_flags = {h3, h2, h1, h0};

    initial pool   = TOTAL;
    initial rr_ptr = 2'd0;
initial grant_hist = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            pool   <= TOTAL;
            rr_ptr <= 2'd0;
grant_hist <= 4'd0;
        end else begin
            pool <= pool - {3'b000, grant_any} + {1'b0, ret};
            if (grant_any) rr_ptr <= sel_idx + 2'd1;
grant_hist <= {grant_hist[2:0], grant_any};
        end
    end

    always @(posedge clk)
        if (pool == 4'd0) assert (h0 || h1 || h2 || h3);
endmodule

module char_tally (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire [7:0] i_char,
    input wire [7:0] i_target,
    output wire o_all_hits,
    output wire o_all_misses
);
    reg [3:0] total, hits, misses;
    initial total  = 4'd0;
    initial hits   = 4'd0;
    initial misses = 4'd0;
    reg q_valid, q_match;
    initial q_valid = 1'b0;
    initial q_match = 1'b0;

    wire match = (i_char == i_target);

    always @(posedge clk)
        if (rst) begin
            total  <= 4'd0;
            hits   <= 4'd0;
            misses <= 4'd0;
            q_valid <= 1'b0;
            q_match <= 1'b0;
        end else begin
            // stage 1: accept the sample, register the compare result
            q_valid <= i_ce && (total != 4'hf);
            if (i_ce && (total != 4'hf)) begin
                total   <= total + 4'd1;
                q_match <= match;
            end
            // stage 2: commit the classification one cycle later
            if (q_valid) begin
                if (q_match) hits   <= hits   + 4'd1;
                else         misses <= misses + 4'd1;
            end
        end

    assign o_all_hits   = (total != 4'd0) && (hits   == total);
    assign o_all_misses = (total != 4'd0) && (misses == total);

    always @(*)
        if (o_all_hits) assert (!o_all_misses);
endmodule

module debounce_shadow (
    input  wire clk,
    input  wire rst,
    input  wire ce,      // sample enable: low => design idles, no state changes
    input  wire raw,     // raw (noisy) button input
    output reg  out      // debounced output
);
    // stability counter (binary) and its one-hot phase shadow
    reg [1:0] cnt;
    reg [3:0] oh;

    reg       sync;        // last sampled level
    reg       out_shadow;  // shadow copy of out, driven off the one-hot path
    reg       out_valid;   // set once a debounced decision has been taken
    reg [1:0] hold;        // minimum output hold: ce cycles left before out may move again

    initial begin
        cnt        = 2'd0;
        oh         = 4'b0001;
        sync       = 1'b0;
        out        = 1'b0;
        out_shadow = 1'b0;
        out_valid  = 1'b0;
        hold       = 2'd0;
    end

    wire match = (raw == sync);
    // a level accepted by the one-hot phase path, honouring the hold window
    wire accept = match && oh[3] && (hold == 2'd0);

    always @(posedge clk) begin
        if (rst) begin
            cnt        <= 2'd0;
            oh         <= 4'b0001;
            sync       <= raw;
            out        <= 1'b0;
            out_shadow <= 1'b0;
            out_valid  <= 1'b0;
            hold       <= 2'd0;
        end else if (ce) begin
            if (!match) begin
                // input changed: restart the stability measurement
                sync <= raw;
                cnt  <= 2'd0;
                oh   <= 4'b0001;
            end else begin
                // advance binary counter (saturating)
                if (cnt != 2'd3)
                    cnt <= cnt + 2'd1;
                // advance one-hot phase (saturating in the top position)
                if (!oh[3])
                    oh <= oh << 1;
                // decision taken from the BINARY path
                if (cnt == 2'd3 && hold == 2'd0) begin
                    out       <= sync;
                    out_valid <= 1'b1;
                end
                // decision taken from the ONE-HOT path
                if (accept)
                    out_shadow <= sync;
                // minimum output pulse width: reload on a real change, else run down
                if (accept && (sync != out_shadow))
                    hold <= 2'd3;
                else if (hold != 2'd0)
                    hold <= hold - 2'd1;
            end
        end
    end

    // P: once a debounced decision exists, the shadow must agree with the output
    always @(posedge clk)
        if (out_valid)
            assert (out == out_shadow);

    // P2: before the first debounced decision the shadow path and the hold timer are quiescent
    always @(posedge clk)
        if (!out_valid)
            assert (!out_shadow && hold == 2'd0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    reg deep;  // registered level>=3 flag, re-evaluated when the level moves
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    // burst drain: while the bucket is deep a spend sheds two tokens at once
    wire bulk = dec && deep;
    wire lite = dec && !deep;
    wire [2:0] nxt = inc  ? tokens + 3'd1 :
                     bulk ? tokens - 3'd2 :
                     lite ? tokens - 3'd1 : tokens;

   // halfway-mark crossings are staged one cycle before they reach the flag
   wire hi_cross = (inc  && tokens == 3'd1) ||
                   (lite && tokens == 3'd2) ||
                   (bulk && tokens == 3'd3);
   reg hi_vld;   // a flag update is in flight
   reg hi_dat;   // the flag value it carries

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;
    initial deep = 1'b0;
   initial hi_vld = 1'b0;
   initial hi_dat = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
            deep      <= 1'b0;
           hi_vld    <= 1'b0;
           hi_dat    <= 1'b0;
        end else begin
            tokens <= nxt;
            if (inc || dec) deep <= (nxt >= 3'd3);

           // the flag no longer turns around in the same cycle as the level:
           // a crossing is captured here and driven out on the next cycle
           hi_vld <= hi_cross;
           if (hi_cross) hi_dat <= (nxt >= 3'd2);
           if (hi_vld)   tokens_hi <= hi_dat;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    // in-flight bucket level; tokens is the registered (pipelined) copy
    reg [2:0] tok_stage;
   // adaptive burst allowance: how full the bucket is currently allowed to get
   reg [2:0] cap;

wire drip_en  = drip  && (tok_stage != cap);
wire spend_en = spend && (tok_stage != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

   // widen the allowance when drips keep arriving at an already-full bucket,
   // tighten it when a request finds the bucket dry
   wire cap_up = drip  && (tok_stage == cap)  && (cap != 3'd4);
   wire cap_dn = spend && !drip && (tok_stage == 3'd0) && (cap != 3'd0);

    initial tokens   = 3'd0;
initial tok_stage = 3'd0;
initial cap = 3'd2;
    initial tokens_hi = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
tok_stage <= 3'd0;
           cap       <= 3'd2;
            tokens_hi <= 1'b0;
        end else begin
if (inc)      tok_stage <= tok_stage + 3'd1;
else if (dec) tok_stage <= tok_stage - 3'd1;

tokens <= tok_stage;

if (cap_up)      cap <= cap + 3'd1;
else if (cap_dn) cap <= cap - 3'd1;

if (inc && tok_stage == 3'd1)      tokens_hi <= 1'b1;
else if (dec && tok_stage == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module vend_credit (
    input  wire clk,
    input  wire i_rst,
    input  wire i_nickel,
    input  wire i_dime,
    output wire o_dispense
);
    // credit counted in 5-cent units toward a 25c (5 unit) item
    reg [2:0] units;
    reg [4:0] credit_1h;   // one-hot shadow of the credit level
   reg [2:0] nkl;         // nickels held in the escrow, available as change
    initial units     = 3'd0;
    initial credit_1h = 5'b00001;
   initial nkl       = 3'd0;

   wire       coin    = i_nickel | i_dime;
    wire [2:0] amount = i_dime ? 3'd2 : 3'd1;
    wire [3:0] sum    = units + amount;

   // 30c tendered for a 25c item owes a nickel back, so the mech only takes
   // that coin when the escrow still holds a nickel it can return
   wire       overpay = coin && (sum == 4'd6);
   wire       refuse  = overpay && (nkl == 3'd0);
   wire       step    = coin && !refuse;

    assign o_dispense = step && (sum >= 4'd5);

    always @(posedge clk)
        if (i_rst) begin
            units     <= 3'd0;
            credit_1h <= 5'b00001;
           nkl       <= 3'd0;
        end else if (step) begin
            if (sum >= 4'd5) begin
                units     <= 3'd0;          // vend and clear credit
                credit_1h <= 5'b00001;
               nkl       <= 3'd0;          // escrow dumped, change paid out
            end else begin
                units     <= sum[2:0];
                credit_1h <= i_dime ? (credit_1h << 2) : (credit_1h << 1);
               nkl       <= i_dime ? nkl : (nkl + 3'd1);
            end
        end

    // P: outside reset the credit shadow is always exactly one-hot
    always @(*)
        if (!i_rst)
            assert ((credit_1h != 5'b00000) &&
                    ((credit_1h & (credit_1h - 5'b00001)) == 5'b00000));

   // P2: the escrow can never hold more nickels than the credit level it
   // helped build, so the shadow bit always survives a shift down by nkl
   always @(posedge clk)
       if (!i_rst)
           assert ((credit_1h >> nkl) != 5'b00000);
endmodule

module ring_occ (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    output reg  [2:0] count,
    output reg  [3:0] occ
);
    reg [1:0] wptr, rptr;
   reg [2:0] alloc_cnt;
   reg [3:0] upd_set, upd_clr;
   // occ bitmap update is staged 4 deep to close timing on the wide occ
   // fabric; the exported count is delayed the same depth so that the
   // count view and the bitmap view always describe the same instant
   reg [3:0] upd_set_s2, upd_clr_s2;
   reg [3:0] upd_set_s3, upd_clr_s3;
   reg [3:0] upd_set_s4, upd_clr_s4;
   reg [2:0] cnt_q1, cnt_q2, cnt_q3;
   initial begin wptr = 2'd0; rptr = 2'd0; count = 3'd0; occ = 4'b0000;
                alloc_cnt = 3'd0; upd_set = 4'b0000; upd_clr = 4'b0000;
                upd_set_s2 = 4'b0000; upd_clr_s2 = 4'b0000;
                upd_set_s3 = 4'b0000; upd_clr_s3 = 4'b0000;
                upd_set_s4 = 4'b0000; upd_clr_s4 = 4'b0000;
                cnt_q1 = 3'd0; cnt_q2 = 3'd0; cnt_q3 = 3'd0; end

   wire do_push = push && (alloc_cnt != 3'd4);
   wire do_pop  = pop  && (alloc_cnt != 3'd0);

    wire [3:0] set_bit = do_push ? (4'b0001 << wptr) : 4'b0000;
    wire [3:0] clr_bit = do_pop  ? (4'b0001 << rptr) : 4'b0000;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
            occ   <= 4'b0000;
           alloc_cnt <= 3'd0;
           upd_set   <= 4'b0000;
           upd_clr   <= 4'b0000;
           upd_set_s2 <= 4'b0000;
           upd_clr_s2 <= 4'b0000;
           upd_set_s3 <= 4'b0000;
           upd_clr_s3 <= 4'b0000;
           upd_set_s4 <= 4'b0000;
           upd_clr_s4 <= 4'b0000;
           cnt_q1 <= 3'd0;
           cnt_q2 <= 3'd0;
           cnt_q3 <= 3'd0;
        end else begin
            if (do_push) wptr <= wptr + 2'd1;
            if (do_pop)  rptr <= rptr + 2'd1;
           upd_set <= set_bit;
           upd_clr <= clr_bit;
           upd_set_s2 <= upd_set;
           upd_clr_s2 <= upd_clr;
           upd_set_s3 <= upd_set_s2;
           upd_clr_s3 <= upd_clr_s2;
           upd_set_s4 <= upd_set_s3;
           upd_clr_s4 <= upd_clr_s3;
           occ   <= (occ | upd_set_s4) & ~upd_clr_s4;
           cnt_q1 <= alloc_cnt;
           cnt_q2 <= cnt_q1;
           cnt_q3 <= cnt_q2;
           count <= cnt_q3;
            case ({do_push, do_pop})
               2'b10:   alloc_cnt <= alloc_cnt + 3'd1;
               2'b01:   alloc_cnt <= alloc_cnt - 3'd1;
               default: alloc_cnt <= alloc_cnt;
            endcase
        end
    end

    always @(posedge clk)
        if (count == 3'd1)
            assert (occ == 4'b0001 || occ == 4'b0010 ||
                    occ == 4'b0100 || occ == 4'b1000);
endmodule

module lfsr_shadow_capture (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_cap,
    output wire [7:0] o_rand,
    output wire [7:0] o_shadow,
    output wire       o_shadow_valid
);
    // maximal-length 8-bit LFSR, taps at 8,6,5,4 (x^8 + x^6 + x^5 + x^4 + 1)
    reg [7:0] lfsr;
    reg [7:0] shadow;
    reg       shadow_valid;
   reg [7:0] stage;
   reg       stage_full;
   reg [3:0] n_ld;
   reg [3:0] n_mv;

    initial lfsr         = 8'h01;
    initial shadow       = 8'h00;
    initial shadow_valid = 1'b0;
   initial stage      = 8'h00;
   initial stage_full = 1'b0;
   initial n_ld       = 4'd0;
   initial n_mv       = 4'd0;

    wire fb = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];

   // capture pipeline: a request stages one sample, the stage then drains
   // into the shadow register on the following enabled cycle
   wire ld_en = i_ce && i_cap && !stage_full;
   wire mv_en = i_ce && (n_ld != n_mv);

    always @(posedge i_clk) begin
        if (i_rst) begin
            lfsr <= 8'h01;
        end else if (i_ce) begin
            lfsr <= { lfsr[6:0], fb };
        end
    end

    // shadow register: snapshots the generator output on request
    always @(posedge i_clk) begin
        if (i_rst) begin
            shadow       <= 8'h00;
            shadow_valid <= 1'b0;
end else if (mv_en) begin
shadow       <= stage;
            shadow_valid <= 1'b1;
        end
    end

   // staging buffer for the capture pipeline
   always @(posedge i_clk) begin
       if (i_rst) begin
           stage      <= 8'h00;
           stage_full <= 1'b0;
       end else if (ld_en) begin
           stage      <= lfsr;
           stage_full <= 1'b1;
       end else if (mv_en) begin
           stage_full <= 1'b0;
       end
   end

   // pipeline ledger: loads into and moves out of the staging buffer
   always @(posedge i_clk) begin
       if (i_rst) begin
           n_ld <= 4'd0;
           n_mv <= 4'd0;
       end else begin
           if (ld_en) n_ld <= n_ld + 4'd1;
           if (mv_en) n_mv <= n_mv + 4'd1;
       end
   end

    assign o_rand         = lfsr;
    assign o_shadow       = shadow;
    assign o_shadow_valid = shadow_valid;

    // P: once a sample has been latched, it can never be the lockup word
    always @(*)
        if (shadow_valid)
            assert (shadow != 8'h00);
endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output reg  [3:0] remaining,
    output reg  [3:0] sent,
    output reg        busy,
    output reg        done
);
    // the bus grants at most five words per burst, so an 8-word block is
    // issued as a 5-word burst plus a deferred 3-word tail
    reg  [3:0] pending;
   // the write port is half-width, so a staged word retires on alternate
   // cycles; a 2-entry buffer absorbs the fetch/retire rate difference
   reg  [3:0] inflight;
   reg        wr_phase;
   wire drain = wr_phase && (inflight != 4'd0);
   wire fetch = (remaining != 4'd0) && ((inflight != 4'd2) || drain);
    // block length is fixed at 8 words
    initial remaining = 4'd5;
    initial pending   = 4'd3;
    initial sent      = 4'd0;
    initial busy      = 1'b1;
    initial done      = 1'b0;
   initial inflight  = 4'd0;
   initial wr_phase  = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            remaining <= 4'd5;
            pending   <= 4'd3;
            sent      <= 4'd0;
            busy      <= 1'b1;
            done      <= 1'b0;
           inflight  <= 4'd0;
           wr_phase  <= 1'b0;
        end else if (ce) begin
           wr_phase <= ~wr_phase;
           if (drain)
               sent <= sent + 4'd1;
           inflight <= inflight + (fetch ? 4'd1 : 4'd0) - (drain ? 4'd1 : 4'd0);
           if (fetch) begin
                remaining <= remaining - 4'd1;
            end
           else if (remaining == 4'd0 && pending != 4'd0) begin
                // burst boundary: re-arm the engine for the deferred tail
                remaining <= pending;
                pending   <= 4'd0;
                busy      <= 1'b1;
            end
           // the engine stays busy until the staging buffer has drained
           else if (drain && inflight == 4'd1)
               busy <= 1'b0;
            // done is raised the cycle after the last word retires
           done <= (remaining == 4'd0 && pending == 4'd0 && inflight == 4'd0);
        end
    end

    // P: the engine must never report completion while still claiming to copy
    always @(posedge clk)
        if (done)
            assert (!busy);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
output reg tokens_hi,
output reg [3:0] spent_total
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;
   // staged level status: the threshold compare is registered one cycle
   // ahead of the reported flag so the status output path stays short
   reg hi_stage;

    initial tokens   = 3'd0;
   initial hi_stage = 1'b0;
    initial tokens_hi = 1'b0;
    initial spent_total = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
           hi_stage  <= 1'b0;
            tokens_hi <= 1'b0;
            spent_total <= 4'd0;
        end else begin
            if (dec) spent_total <= spent_total + 4'd1;
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

           if (inc && tokens == 3'd1)      hi_stage <= 1'b1;
           else if (dec && tokens == 3'd2) hi_stage <= 1'b0;
           tokens_hi <= hi_stage;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module lfsr_shadow_capture (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_cap,
    output wire [7:0] o_rand,
    output wire [7:0] o_shadow,
    output wire       o_shadow_valid
);
    // maximal-length 8-bit LFSR, taps at 8,6,5,4 (x^8 + x^6 + x^5 + x^4 + 1)
    reg [7:0] lfsr;
   reg [7:0] lfsr_b;
    reg [7:0] shadow;
    reg       shadow_valid;
   reg [1:0] ch_en;   // capture mixer channel enables: bit0 = gen A, bit1 = gen B
reg [3:0] n_on;    // grant ledger: times channel B was switched on
reg [3:0] n_off;   // grant ledger: times channel B was switched off

    initial lfsr         = 8'h01;
   initial lfsr_b       = 8'hA5;
    initial shadow       = 8'h00;
    initial shadow_valid = 1'b0;
   initial ch_en        = 2'b01;
initial n_on         = 4'd0;
initial n_off        = 4'd0;

    wire fb = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];
   wire fb_b = lfsr_b[7] ^ lfsr_b[5] ^ lfsr_b[4] ^ lfsr_b[3];
   // shared capture port: XOR of whichever generator channels are enabled
   wire [7:0] sample = (ch_en[0] ? lfsr : 8'h00) ^ (ch_en[1] ? lfsr_b : 8'h00);
// gen B holds the shared port for as long as its grant ledger is unbalanced
wire b_gnt = (n_on != n_off);
// B hands the port back once the mixed phase (A alongside B) has been sampled
wire b_rel = b_gnt & ch_en[0];
wire b_nxt = ~b_rel;        // channel-B enable for the next sample
wire a_nxt = ch_en[1];      // channel A trails B by one phase

    always @(posedge i_clk) begin
        if (i_rst) begin
            lfsr <= 8'h01;
           lfsr_b <= 8'hA5;
        end else if (i_ce) begin
            lfsr <= { lfsr[6:0], fb };
           lfsr_b <= { lfsr_b[6:0], fb_b };
        end
    end

    // shadow register: snapshots the generator output on request
    always @(posedge i_clk) begin
        if (i_rst) begin
            shadow       <= 8'h00;
            shadow_valid <= 1'b0;
           ch_en        <= 2'b01;
n_on         <= 4'd0;
n_off         <= 4'd0;
        end else if (i_ce && i_cap) begin
           shadow       <= sample;
            shadow_valid <= 1'b1;
           // round-robin the shared port: gen A, gen B, then both mixed
ch_en        <= { b_nxt, a_nxt };
// log both sides of the channel-B grant handshake
if (!ch_en[1] &&  b_nxt) n_on  <= n_on  + 4'd1;
if ( ch_en[1] && !b_nxt) n_off <= n_off + 4'd1;
        end
    end

// o_rand doubles as a status read-back: while a capture is requested the bus
// returns the channel-B grant ledger so the host can tag the sample
assign o_rand         = i_cap ? { n_on, n_off } : lfsr;
    assign o_shadow       = shadow;
    assign o_shadow_valid = shadow_valid;

    // P: once a sample has been latched, it can never be the lockup word
    always @(*)
        if (shadow_valid)
            assert (shadow != 8'h00);
endmodule

module ringq (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] dout,
    output wire full,
    output wire empty
);
reg [2:0] wptr = 3'd0;
reg [2:0] rptr = 3'd0;
    reg [2:0] count = 3'd0;
    reg [2:0] depth = 3'd4;
    reg [7:0] mem [0:3];

    assign full  = (count == depth);
    assign empty = (count == 3'd0);
    // push+pop issued together on an empty queue is a resize command,
    // not data: din carries the new usable depth (clamped to 1..4).
    wire cfg_we = push && pop && empty;
    wire [2:0] cfg_depth = (din[2:0] == 3'd0) ? 3'd1 :
                           (din[2:0] >  3'd4) ? 3'd4 : din[2:0];

    wire do_push = push && !full && !cfg_we;
    wire do_pop  = pop  && !empty;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 3'd0;
            rptr  <= 3'd0;
            count <= 3'd0;
            depth <= 3'd4;
        end else if (cfg_we) begin
            depth <= cfg_depth;
            wptr  <= 3'd0;
            rptr  <= 3'd0;
        end else begin
            if (do_push) begin
                mem[wptr[1:0]] <= din;
                wptr <= (wptr + 3'd1 == depth) ? 3'd0 : wptr + 3'd1;
            end
            if (do_pop)
                rptr <= (rptr + 3'd1 == depth) ? 3'd0 : rptr + 3'd1;
            if (do_push && !do_pop)
                count <= count + 3'd1;
            else if (do_pop && !do_push)
                count <= count - 3'd1;
        end
    end

    assign dout = mem[rptr[1:0]];

    always @(posedge clk)
        if (count == 3'd0) assert (wptr == rptr);
endmodule

module alu_accum_slice (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire       i_sub,
    output reg  [7:0] o_result,
    output reg  [6:0] o_n_iss,
    output reg  [6:0] o_n_ret,
    output wire       o_zero
);
    reg [6:0] half;

    // Ledger: one counter per side of the transition.  Every issue and every
    // return is logged; the counters are free running and wrap at 7 bits.
    // The outstanding count is the difference, recomputed where needed.
    wire [6:0] outstanding = o_n_iss - o_n_ret;

    // The return that empties the ledger clears the tracker outright rather
    // than decrementing it, so a mis-counted step cannot leave the tracker
    // hanging off zero after the slice has fully drained.
    wire       ret_drains  = i_sub && (outstanding == 7'd1);

    initial o_result = 8'd0;
    initial o_n_iss  = 7'd0;
    initial o_n_ret  = 7'd0;
    initial half     = 7'd0;

    assign o_zero = (o_result == 8'd0);

    always @(posedge clk) begin
        if (rst) begin
            o_result <= 8'd0;
            half     <= 7'd0;
            o_n_iss  <= 7'd0;
            o_n_ret  <= 7'd0;
        end else if (i_ce) begin
            o_result <= i_sub ? (o_result - 8'd2) : (o_result + 8'd2);
            if (ret_drains)
                half <= 7'd0;
            else
                half <= i_sub ? (half - 7'd1) : (half + 7'd1);
            o_n_iss  <= i_sub ? o_n_iss : (o_n_iss + 7'd1);
            o_n_ret  <= i_sub ? (o_n_ret + 7'd1) : o_n_ret;
        end
    end

    // P: whenever the half-step tracker is at zero, the registered ALU result is zero
    always @(posedge clk)
        if (half == 7'd0)
            assert (o_result == 8'd0);
endmodule

module uart_tx_budget (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // baud tick / enable: low means idle
    input  wire       i_start,
    input  wire [7:0] i_data,
    output reg        tx,
    output reg        busy
);
    // bit accounting for one 8-bit payload
    reg [3:0] sent;   // data bits already shifted out
    reg [3:0] left;    // data bits still to shift out
    reg [7:0] sh;      // shift register
   reg [3:0] sh_cnt;  // payload bits still sitting inside the shift register
   reg       obuf;    // output stage: line level registered one tick ahead
   reg       obuf_v;  // output stage currently holds a payload bit
  reg       obuf2;   // second output stage: bit queued behind obuf
  reg       obuf2_v; // second output stage currently holds a payload bit

    initial tx   = 1'b1;
    initial busy = 1'b0;
    initial sent = 4'd0;
    initial left = 4'd8;
    initial sh   = 8'h00;
   initial sh_cnt = 4'd0;
   initial obuf   = 1'b1;
   initial obuf_v = 1'b0;
  initial obuf2   = 1'b1;
  initial obuf2_v = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tx   <= 1'b1;
            busy <= 1'b0;
            sent <= 4'd0;
            left <= 4'd8;
            sh   <= 8'h00;
           sh_cnt <= 4'd0;
           obuf   <= 1'b1;
           obuf_v <= 1'b0;
          obuf2   <= 1'b1;
          obuf2_v <= 1'b0;
        end else if (i_ce) begin
            if (!busy) begin
                if (i_start) begin
                    busy <= 1'b1;
                  sh     <= {2'b00, i_data[7:2]};
                   obuf   <= i_data[0];   // prefetch bit 0 during the start bit
                  obuf2  <= i_data[1];   // and bit 1 queued behind it
                   obuf_v <= 1'b1;
                  obuf2_v <= 1'b1;
                  sh_cnt <= 4'd6;
                    sent <= 4'd0;
                    left <= 4'd8;
                    tx   <= 1'b0;      // start bit
                end else begin
                    tx   <= 1'b1;      // line idle high
                end
            end else if (left != 4'd0) begin
               tx   <= obuf;          // data bit out of the output stage
               sent <= sent + {3'b000, obuf_v};
                left <= left - 4'd1;
               if (sh_cnt != 4'd0) begin
                  obuf   <= obuf2;
                  obuf2  <= sh[0];
                   sh     <= {1'b0, sh[7:1]};
                   sh_cnt <= sh_cnt - 4'd1;
                  obuf_v  <= obuf2_v;
                  obuf2_v <= 1'b1;
               end else begin
                  obuf    <= obuf2;
                  obuf_v  <= obuf2_v;  // last queued bit moves up a stage
                  obuf2_v <= 1'b0;     // shifter drained
               end
            end else begin
                tx   <= 1'b1;          // stop bit, frame complete
                busy <= 1'b0;
            end
        end
    end

    // Property: whenever the transmitter reports no data bits remaining while a
    // frame is still active, exactly eight payload bits must have been shifted.
    always @(posedge clk)
        if (busy && left == 4'd0)
            assert (sent == 4'd8);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module token_bucket_pool (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] drip_req,
    input  wire [5:0] spend_req,
    output reg  [3:0] pool,
    output wire [5:0] hi_flags,
    output reg        starved
);
    localparam [3:0] TOTAL = 4'd8;

    // per-instance observable state
    wire [2:0] t0, t1, t2, t3, t4, t5;
    wire       h0, h1, h2, h3, h4, h5;

   // a granted credit is registered before it reaches its bucket: the
   // arbiter no longer drives the bucket update path directly, so a drip
   // lands one cycle after it is granted
   reg  [5:0] drip_q;

   // a bucket with a credit in flight holds off its spend request for that
   // one cycle, so the landing drip can never be cancelled by a release
   wire [5:0] spend_eff;
   assign spend_eff[0] = spend_req[0] && !drip_q[0];
   assign spend_eff[1] = spend_req[1] && !drip_q[1];
   assign spend_eff[2] = spend_req[2] && !drip_q[2];
   assign spend_eff[3] = spend_req[3] && !drip_q[3];
   assign spend_eff[4] = spend_req[4] && !drip_q[4];
   assign spend_eff[5] = spend_req[5] && !drip_q[5];

   // occupancy counts the credit already on its way to the bucket
   wire [2:0] occ0 = t0 + {2'd0, drip_q[0]};
   wire [2:0] occ1 = t1 + {2'd0, drip_q[1]};
   wire [2:0] occ2 = t2 + {2'd0, drip_q[2]};
   wire [2:0] occ3 = t3 + {2'd0, drip_q[3]};
   wire [2:0] occ4 = t4 + {2'd0, drip_q[4]};
   wire [2:0] occ5 = t5 + {2'd0, drip_q[5]};


    // a bucket wants a credit only if the drip would really land:
   // its occupancy, counting any credit already in flight, must leave room
    wire [5:0] want;
   assign want[0] = drip_req[0] && (occ0 <= 3'd3);
   assign want[1] = drip_req[1] && (occ1 <= 3'd3);
   assign want[2] = drip_req[2] && (occ2 <= 3'd3);
   assign want[3] = drip_req[3] && (occ3 <= 3'd3);
   assign want[4] = drip_req[4] && (occ4 <= 3'd3);
   assign want[5] = drip_req[5] && (occ5 <= 3'd3);

    wire credit_avail = (pool != 4'd0);

    // one credit per cycle, fixed priority
    wire [5:0] grant;
    assign grant[0] = credit_avail && want[0];
    assign grant[1] = credit_avail && want[1] && !want[0];
    assign grant[2] = credit_avail && want[2] && !want[0] && !want[1];
    assign grant[3] = credit_avail && want[3] && !want[0] && !want[1] && !want[2];
    assign grant[4] = credit_avail && want[4] && !want[0] && !want[1] && !want[2] && !want[3];
    assign grant[5] = credit_avail && want[5] && !want[0] && !want[1] && !want[2] && !want[3] && !want[4];
    wire grant_any = grant[0] || grant[1] || grant[2] || grant[3] || grant[4] || grant[5];

    // a released token returns its credit
    wire [5:0] rel;
   assign rel[0] = spend_eff[0] && (t0 != 3'd0);
   assign rel[1] = spend_eff[1] && (t1 != 3'd0);
   assign rel[2] = spend_eff[2] && (t2 != 3'd0);
   assign rel[3] = spend_eff[3] && (t3 != 3'd0);
   assign rel[4] = spend_eff[4] && (t4 != 3'd0);
   assign rel[5] = spend_eff[5] && (t5 != 3'd0);

    wire [3:0] rel_cnt = {3'd0, rel[0]} + {3'd0, rel[1]} + {3'd0, rel[2]} +
                         {3'd0, rel[3]} + {3'd0, rel[4]} + {3'd0, rel[5]};

   token_bucket u0 (.clk(clk), .rst(rst), .drip(drip_q[0]), .spend(spend_eff[0]), .tokens(t0), .tokens_hi(h0));
   token_bucket u1 (.clk(clk), .rst(rst), .drip(drip_q[1]), .spend(spend_eff[1]), .tokens(t1), .tokens_hi(h1));
   token_bucket u2 (.clk(clk), .rst(rst), .drip(drip_q[2]), .spend(spend_eff[2]), .tokens(t2), .tokens_hi(h2));
   token_bucket u3 (.clk(clk), .rst(rst), .drip(drip_q[3]), .spend(spend_eff[3]), .tokens(t3), .tokens_hi(h3));
   token_bucket u4 (.clk(clk), .rst(rst), .drip(drip_q[4]), .spend(spend_eff[4]), .tokens(t4), .tokens_hi(h4));
   token_bucket u5 (.clk(clk), .rst(rst), .drip(drip_q[5]), .spend(spend_eff[5]), .tokens(t5), .tokens_hi(h5));

    assign hi_flags = {h5, h4, h3, h2, h1, h0};

    initial pool    = TOTAL;
    initial starved = 1'b0;
   initial drip_q  = 6'd0;

    always @(posedge clk) begin
        if (rst) begin
            pool    <= TOTAL;
            starved <= 1'b0;
           drip_q  <= 6'd0;
        end else begin
           drip_q <= grant;
            pool <= pool + rel_cnt - {3'd0, grant_any};
            if (pool == 4'd0) starved <= 1'b1;
        end
    end

    // when the pool is exhausted all credits sit in the buckets, so at least
    // one bucket must be above its high-water mark
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 || h1 || h2 || h3 || h4 || h5);
endmodule

module pwm_antiphase (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire load,
    input wire [3:0] i_duty,
    output wire pwm_a,
    output wire pwm_b
);
    // ramp counter and its anti-phase mirror (kept complementary by construction)
    reg [3:0] cnt  = 4'd0;
    reg [3:0] cntb = 4'd15;
    // duty for each channel, split so the pair always sums to full scale
    reg [3:0] duty_a = 4'd8;
    reg [3:0] duty_b = 4'd7;
   // the B-side complement is computed in its own stage to shorten the load path,
   // so it lands in duty_b one cycle after duty_a takes the new value
   reg [3:0] duty_b_stg = 4'd7;
   reg       upd_pend   = 1'b0;

    always @(posedge clk)
        if (rst) begin
            cnt  <= 4'd0;
            cntb <= 4'd15;
        end else if (ce) begin
            cnt  <= cnt  + 4'd1;
            cntb <= cntb - 4'd1;
        end

    always @(posedge clk)
        if (rst) begin
            duty_a <= 4'd8;
            duty_b <= 4'd7;
           duty_b_stg <= 4'd7;
           upd_pend   <= 1'b0;
        end else if (load) begin
            duty_a <= i_duty;
           duty_b_stg <= 4'd15 - i_duty;
           upd_pend   <= 1'b1;
       end else if (upd_pend) begin
           duty_b     <= duty_b_stg;
           upd_pend   <= 1'b0;
        end
   // while the B complement is still in the stage the two comparators would be
   // working from a mismatched duty pair, so the A-side drive is held off

   assign pwm_a = (cnt  < duty_a) && !upd_pend;
    assign pwm_b = (cntb < duty_b);

    // the two half-bridge drives must never be asserted together
    always @(*)
        if (pwm_a) assert (!pwm_b);

   // the staged complement must already describe a non-overlapping pair, so the
   // B channel cannot begin conducting on the cycle the queued update lands
   always @(posedge clk)
       if (cnt < duty_a) assert (!(cntb < duty_b_stg));
endmodule

module watchdog (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire kick,
    input wire ack,
    output reg fault
);
    reg [3:0] timer;
    reg [3:0] elapsed;
reg [3:0] period;
localparam [3:0] GRACE_TICKS = 4'd2;
reg [3:0] grace;
wire [3:0] period_tight = (period == 4'd4) ? 4'd4 : period - 4'd1;
wire [3:0] period_relax = (period == 4'd8) ? 4'd8 : period + 4'd1;
wire [3:0] remain       = timer + grace;
wire [3:0] reload_tight = period_tight - GRACE_TICKS;
wire [3:0] reload_relax = period_relax - GRACE_TICKS;
wire [3:0] reload_hold  = period - GRACE_TICKS;
initial begin timer = 4'd6; grace = GRACE_TICKS; elapsed = 4'd0; fault = 1'b0; period = 4'd8; end

    always @(posedge clk) begin
        if (rst) begin
timer   <= 4'd6;
grace   <= GRACE_TICKS;
            elapsed <= 4'd0;
            fault   <= 1'b0;
period  <= 4'd8;
        end else if (i_ce) begin
            if (ack) begin
timer   <= reload_tight;
grace   <= GRACE_TICKS;
period  <= period_tight;
                elapsed <= 4'd0;
                fault   <= 1'b0;
            end else if (kick && !fault) begin
if (timer == 4'd0) begin
timer  <= reload_hold;
grace  <= GRACE_TICKS;
end else begin
timer  <= reload_relax;
grace  <= GRACE_TICKS;
period <= period_relax;
end
                elapsed <= 4'd0;
            end else begin
                if (timer != 4'd0)   timer   <= timer - 4'd1;
else if (grace != 4'd0) grace <= grace - 4'd1;
if (elapsed != period) elapsed <= elapsed + 4'd1;
if (remain == 4'd1)   fault   <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (elapsed == 4'd8)
            assert (fault);
endmodule

module rr_arbiter_pri (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire [3:0] req,
    output wire [3:0] gnt,
    output reg  [3:0] pri,
    output reg  [1:0] idx
);
    initial pri = 4'b0001;
    initial idx = 2'd0;

   // Requesters are grouped in pairs, {req[1:0]} and {req[3:2]}.  The pointer
   // walks both members of the selected pair before handing the turn over to
   // the other pair, so the rotation is held as a pair select plus a slot
   // inside that pair; idx is just the flattened pointer published outside.
   reg pair_sel;
   reg slot;
   initial pair_sel = 1'b0;
   initial slot = 1'b0;

   wire pair_wrap = slot;                  // slot 1 is the last member of a pair
   wire pair_nxt  = pair_sel ^ pair_wrap;
   wire slot_nxt  = ~slot;

    // only the requester currently pointed at by the rotating priority wins
    assign gnt = req & pri;

    wire low_pri = pri[0] | pri[1];   // priority pointer sits in lower half
    wire idx_hi  = idx[1];            // binary index says upper half

    always @(posedge clk) begin
        if (rst) begin
            pri <= 4'b0001;
            idx <= 2'd0;
           pair_sel <= 1'b0;
           slot <= 1'b0;
        end else if (step) begin
            pri <= {pri[2:0], pri[3]};
           pair_sel <= pair_nxt;
           slot <= slot_nxt;
           idx <= {pair_nxt, slot_nxt};
        end
    end

    always @(posedge clk)
        if (|gnt)
            assert (!(low_pri && idx_hi));
endmodule

module stack_occupancy (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [7:0] data,
    output wire [7:0] o_top,
    output wire empty,
output wire full,
output reg [7:0] ev_count
);
    parameter DEPTH = 8;
    reg [3:0] sp   = 4'd0;   // occupancy / stack pointer
    reg [3:0] free = 4'd8;   // mirrored free-slot count
reg [3:0] sp_n   = 4'd0;   // issue-stage pointer (ops accepted)
reg [3:0] free_n = 4'd8;   // issue-stage free-slot count
reg       stg_v    = 1'b0; // operation staged for commit
reg       stg_push = 1'b0; // staged direction: 1 = push, 0 = pop
reg [2:0] stg_addr = 3'd0; // staged write slot
reg [7:0] stg_data = 8'h00;
    reg [7:0] mem [0:7];
    integer i;
    initial for (i = 0; i < 8; i = i + 1) mem[i] = 8'h00;
initial ev_count = 8'h00;

    assign empty = (sp == 4'd0);
    assign full  = (sp == DEPTH[3:0]);

wire empty_n = (sp_n == 4'd0);
wire full_n  = (sp_n == DEPTH[3:0]);

wire do_push = push && !pop && !full_n;
wire do_pop  = pop  && !push && !empty_n;

    always @(posedge clk)
        if (rst) begin
            sp   <= 4'd0;
            free <= 4'd8;
end else if (stg_v && stg_push) begin
            sp   <= sp + 4'd1;
            free <= free - 4'd1;
end else if (stg_v && !stg_push) begin
            sp   <= sp - 4'd1;
            free <= free + 4'd1;
        end

   always @(posedge clk)
       if (rst) begin
           sp_n     <= 4'd0;
           free_n   <= 4'd8;
           stg_v    <= 1'b0;
           stg_push <= 1'b0;
           stg_addr <= 3'd0;
           stg_data <= 8'h00;
ev_count <= 8'h00;
       end else begin
if (do_push || do_pop) ev_count <= ev_count + 8'h01;
           stg_v    <= do_push || do_pop;
           stg_push <= do_push;
           stg_addr <= sp_n[2:0];
           stg_data <= data;
           if (do_push) begin
               sp_n   <= sp_n + 4'd1;
               free_n <= free_n - 4'd1;
           end else if (do_pop) begin
               sp_n   <= sp_n - 4'd1;
               free_n <= free_n + 4'd1;
           end
       end

    always @(posedge clk)
if (!rst && stg_v && stg_push) mem[stg_addr] <= stg_data;

    assign o_top = empty ? 8'h00 : mem[sp[2:0] - 3'd1];

    always @(*)
        if (!empty) assert (free <= 4'd7);
endmodule

module wdog_kick (
    input wire clk,
    input wire i_ce,
    input wire kick,
    input wire ack,
    output wire o_reset
);
    reg [3:0] cnt;
    reg zf, armed, fault;
    reg [1:0] hold;
   reg [1:0] frac;                 // sub-tick prescaler of the service window
    initial cnt   = 4'd0;
    initial zf    = 1'b1;
    initial armed = 1'b0;
    initial fault = 1'b0;
    initial hold  = 2'd0;
   initial frac  = 2'd0;

    always @(posedge clk) if (i_ce) begin
        if (ack) begin
            fault <= 1'b0;
            armed <= 1'b0;
            cnt   <= 4'd0;
            zf    <= 1'b1;
           frac  <= 2'd0;
        end else if (kick && !fault) begin
            armed <= 1'b1;
            cnt   <= 4'd8;
            zf    <= 1'b0;
           frac  <= 2'd3;          // 8 coarse ticks of 4 ce pulses each
        end else if (armed) begin
            if (zf) fault <= 1'b1;            // expiry seen through the flag
           if (cnt == 4'd0 && frac == 2'd0) armed <= 1'b0; // whole window elapsed
           else if (frac != 2'd0) begin
               frac <= frac - 2'd1;
               zf   <= (cnt == 4'd0) && (frac == 2'd1);
           end else begin
                cnt <= cnt - 4'd1;
               frac <= 2'd3;
               zf   <= 1'b0;
            end
        end
    end

    // minimum reset assertion width: downstream blocks need o_reset wide, so
    // the fault latch is stretched by a shadow timer for a few ce ticks after
    // the host acknowledges it
    always @(posedge clk) if (i_ce) begin
        if (fault)             hold <= 2'd3;
        else if (hold != 2'd0) hold <= hold - 2'd1;
    end

    assign o_reset = fault || (hold != 2'd0);

    always @(*)
        if (fault) assert (!armed);

    // a pending fault means the service window timer is parked at zero
    always @(posedge clk)
        if (fault) assert (cnt == 4'd0);
endmodule

module debounce_stability (
    input wire clk,
    input wire rst,
    input wire sample,
    input wire raw,
    output reg out
);
    reg [2:0] cnt;   // consecutive samples disagreeing with out
    reg [2:0] rem;   // samples still required before out may flip
    reg [2:0] cred;  // progress banked across brief re-agreements

    initial out = 1'b0;
    initial cnt = 3'd0;
    initial rem = 3'd4;
    initial cred = 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            out <= 1'b0;
            cnt <= 3'd0;
            rem <= 3'd4;
            cred <= 3'd0;
        end else if (sample) begin
            if (raw == out) begin
                // brief re-agreement: bank what the streak achieved,
                // leaking one sample so stale progress decays away
                cnt <= 3'd0;
                if (cnt + cred == 3'd0) begin
                    cred <= 3'd0;
                    rem  <= 3'd4;
                end else begin
                    cred <= cnt + cred - 3'd1;
                    rem  <= rem + 3'd1;
                end
            end else if (cnt + cred == 3'd4) begin
                out <= raw;
                cnt <= 3'd0;
                cred <= 3'd0;
                rem <= 3'd4;
            end else begin
                cnt <= cnt + 3'd1;
                rem <= rem - 3'd1;
            end
        end
    end

    always @(posedge clk)
        if (cnt == 3'd4) assert (rem != 3'd4);
endmodule

module alu_budget (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire [7:0] i_step,
    output wire [7:0] o_acc,
    output wire o_zero,
    output wire o_full,
    output wire [7:0] o_resv,
    output wire [3:0] o_take,
    output wire [3:0] o_give
);
    localparam [7:0] LIMIT = 8'd200;

    reg [7:0] acc;   // accumulated result
    reg [7:0] rem;   // headroom credited to the accumulator
    reg [7:0] resv;   // operand held between the headroom debit and the accumulate
    reg [3:0] n_take; // reservations debited out of the headroom
    reg [3:0] n_give; // reservations folded into the accumulator
    initial acc = 8'd0;
    initial rem = LIMIT;
    initial resv = 8'd0;
    initial n_take = 4'd0;
    initial n_give = 4'd0;

    wire pending = (n_take != n_give);
    wire grant = i_ce && !pending && (i_step != 8'd0) && (rem >= i_step);
    wire fold = i_ce && pending;

    always @(posedge clk)
        if (rst) begin
            acc <= 8'd0;
            rem <= LIMIT;
            resv <= 8'd0;
            n_take <= 4'd0;
            n_give <= 4'd0;
        end else begin
            if (grant) begin
                rem <= rem - i_step;
                resv <= i_step;
                n_take <= n_take + 4'd1;
            end
            if (fold) begin
                acc <= acc + resv;
                resv <= 8'd0;
                n_give <= n_give + 4'd1;
            end
        end

    assign o_acc  = acc;
    assign o_zero = (acc == 8'd0);
    assign o_full = (rem == 8'd0);
    assign o_resv = resv;
    assign o_take = n_take;
    assign o_give = n_give;

    // P: a nonzero accumulation never exceeds its saturation bound
    always @(*)
        if (!o_zero) assert (acc <= LIMIT);
endmodule

module vend_credit (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_dime,
    output wire o_dispense,
    output wire [5:0] o_change
);
    reg [3:0] units = 0;      // credit in 5-cent units
    reg [5:0] cents = 0;      // credit in cents
    reg       dispense = 0;
    reg [5:0] change = 0;
    reg [5:0] chg_stage = 0;   // vend total waiting on the change subtractor
    reg       vend_stage = 0;  // a vend was deducted from credit last cycle
   reg [2:0] n_units_in  = 0; // coin ledger: nickel-equivalents taken in
   reg [2:0] n_units_out = 0; // coin ledger: nickel-equivalents paid out by vends

    wire [3:0] inc_u = i_dime ? 4'd2  : 4'd1;
    wire [5:0] inc_c = i_dime ? 6'd10 : 6'd5;
    wire [3:0] nu = units + inc_u;
    wire [5:0] nc = cents + inc_c;
   wire [2:0] inc_n = i_dime ? 3'd2 : 3'd1;
   // credit the ledger says we hold once this coin has been counted
   wire [2:0] nl = (n_units_in - n_units_out) + inc_n;
   // the change subtractor is fed from the audited ledger, converted to cents
   wire [5:0] vend_total = {nl, 2'b00} + {3'b000, nl};

    always @(posedge clk)
        if (i_reset) begin
            units    <= 4'd0;
            cents    <= 6'd0;
            dispense <= 1'b0;
            change   <= 6'd0;
            chg_stage  <= 6'd0;
            vend_stage <= 1'b0;
           n_units_in  <= 3'd0;
           n_units_out <= 3'd0;
        end else if (i_ce) begin
            // stage 2: finish the change subtraction started last cycle
            dispense <= vend_stage;
            if (vend_stage) change <= chg_stage - 6'd25;
            // stage 1: take the coin and deduct a full vend's worth of credit
           n_units_in <= n_units_in + inc_n;
            if (nu >= 4'd5) begin
               n_units_out <= n_units_out + 3'd5;
                units    <= nu - 4'd5;
                cents    <= nc - 6'd25;
               chg_stage  <= vend_total;
                vend_stage <= 1'b1;
            end else begin
                units    <= nu;
                cents    <= nc;
                vend_stage <= 1'b0;
            end
        end

    assign o_dispense = dispense;
   // between dispenses the change bus reports the coin ledger for the audit port
   assign o_change   = dispense ? change : {n_units_in, n_units_out};

    always @(posedge clk)
        if (dispense) assert (change <= 6'd5);
endmodule

module watchdog (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire kick,
    input wire ack,
    output reg fault
);
    reg [3:0] timer;
    reg [3:0] elapsed;
reg [3:0] resv;
reg [3:0] wresv;
reg [3:0] period;
wire [3:0] period_tight = (period == 4'd4) ? 4'd4 : period - 4'd1;
wire [3:0] period_relax = (period == 4'd8) ? 4'd8 : period + 4'd1;
localparam [3:0] GRACE = 4'd2;
localparam [3:0] WARN = 4'd1;
initial begin timer = 4'd8; elapsed = 4'd0; fault = 1'b0; period = 4'd8; resv = 4'd0; wresv = 4'd0; end

    always @(posedge clk) begin
        if (rst) begin
            timer   <= 4'd8;
            elapsed <= 4'd0;
            fault   <= 1'b0;
period  <= 4'd8;
            resv    <= 4'd0;
            wresv   <= 4'd0;
        end else if (i_ce) begin
            if (ack) begin
timer   <= period_tight - GRACE;
resv    <= GRACE - WARN;
wresv   <= WARN;
period  <= period_tight;
                elapsed <= 4'd0;
                fault   <= 1'b0;
            end else if (kick && !fault) begin
timer   <= period_relax - GRACE;
resv    <= GRACE - WARN;
wresv   <= WARN;
period  <= period_relax;
                elapsed <= 4'd0;
            end else begin
                if (timer == 4'd1 && resv != 4'd0) begin
                    timer <= resv;
                    resv  <= 4'd0;
               end else if (timer == 4'd1 && wresv != 4'd0) begin
                   timer <= wresv;
                   wresv <= 4'd0;
               end else if (timer != 4'd0) timer <= timer - 4'd1;
if (elapsed != period) elapsed <= elapsed + 4'd1;
               if (timer == 4'd1 && resv == 4'd0 && wresv == 4'd0) fault <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (elapsed == 4'd8)
            assert (fault);
endmodule

module token_bucket (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire req,
    input  wire drip,
    output wire grant
);
    reg [3:0] tokens = 4'd8;   // tokens currently in the bucket
    reg [3:0] free   = 4'd0;   // room left in the bucket (shadow accounting)

   reg [3:0] n_out  = 4'd0;   // ledger: tokens handed out (free-running, wraps)
   reg [3:0] n_in   = 4'd0;   // ledger: tokens dripped in (free-running, wraps)

    wire spend   = ce && req  && (tokens != 4'd0);
    wire refill  = ce && drip && (free   != 4'd0);

   // Idle maintenance cycle: enabled but nothing requested and nothing
   // dripping.  The shadow room count is re-derived from the event ledger
   // so that it cannot drift away from the traffic actually seen.
   wire audit = ce && !req && !drip;

    assign grant = spend;

    always @(posedge clk) begin
        if (rst) begin
            tokens <= 4'd8;
            free   <= 4'd0;
           n_out  <= 4'd0;
           n_in   <= 4'd0;
        end else begin
            tokens <= tokens - spend + refill;
           if (audit)
               free <= n_out - n_in;
           else
               free <= free + spend - refill;
           n_out <= n_out + spend;
           n_in  <= n_in  + refill;
        end
    end

    // P: if the bucket is not completely full, at least one slot's worth of
    // tokens is missing, so occupancy cannot exceed CAP-1.
    always @(posedge clk)
        if (free != 4'd0)
            assert (tokens <= 4'd7);
endmodule

// Two-road intersection controller.
// Light codes: 0 = RED, 1 = GREEN, 2 = YELLOW
// Phases: 0 NS-green, 1 NS-yellow, 2 all-red, 3 EW-green, 4 EW-yellow, 5 all-red
// Each phase handover advances the affected road's light one step around the
// RED -> GREEN -> YELLOW -> RED ring.
module intersection_ctrl (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output wire       o_ns_green,
    output wire       o_ew_green,
    output wire [2:0] o_phase
);
    localparam [1:0] RED    = 2'd0;
    localparam [1:0] GREEN  = 2'd1;
    localparam [1:0] YELLOW = 2'd2;

    localparam [2:0] PHASE_LEN = 3'd4;
   // clearance (all-red) intervals are held longer than the coloured phases
   localparam [2:0] CLEAR_LEN = 3'd6;

    reg [2:0] phase;
    reg [2:0] timer;
    reg [1:0] ns_state;
    reg [1:0] ew_state;
    // lamp driver pipeline: {ns_color, ew_color} on its way out to the signal
    // heads.  A commanded change needs four enabled cycles to reach the lamps.
    reg [3:0] lamp_s1;
    reg [3:0] lamp_s2;
    reg [3:0] lamp_s3;
    reg [3:0] lamp_s4;

    initial phase    = 3'd0;
    initial timer    = PHASE_LEN;
    // the heads come up all-red and the pipeline primes them from phase 0
    initial ns_state = RED;
    initial ew_state = RED;
    initial lamp_s1  = {GREEN, RED};
    initial lamp_s2  = {RED, RED};
    initial lamp_s3  = {RED, RED};
    initial lamp_s4  = {RED, RED};

    // one step around the three-colour ring
    function [1:0] nextcolor;
        input [1:0] c;
        begin
            if (c == YELLOW)
                nextcolor = RED;
            else
                nextcolor = c + 2'd1;
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            phase    <= 3'd0;
            timer    <= PHASE_LEN;
            ns_state <= RED;
            ew_state <= RED;
            lamp_s1  <= {GREEN, RED};
            lamp_s2  <= {RED, RED};
            lamp_s3  <= {RED, RED};
            lamp_s4  <= {RED, RED};
        end else if (ce) begin
            // the driver pipeline advances one stage every enabled cycle
            lamp_s2  <= lamp_s1;
            lamp_s3  <= lamp_s2;
            lamp_s4  <= lamp_s3;
            ns_state <= lamp_s4[3:2];
            ew_state <= lamp_s4[1:0];
            if (timer != 3'd0) begin
                timer <= timer - 3'd1;
            end else begin
               // a handover into an all-red clearance phase gets the long interval
               timer <= ((phase == 3'd1) || (phase == 3'd4)) ? CLEAR_LEN : PHASE_LEN;
                case (phase)
                3'd0: begin // NS green expires -> NS yellow
                    phase    <= 3'd1;
                    lamp_s1  <= {nextcolor(lamp_s1[3:2]), lamp_s1[1:0]};
                end
                3'd1: begin // NS yellow expires -> all red
                    phase    <= 3'd2;
                    lamp_s1  <= {nextcolor(lamp_s1[3:2]), lamp_s1[1:0]};
                end
                3'd2: begin // all red -> EW green
                    phase    <= 3'd3;
                    lamp_s1  <= {lamp_s1[3:2], nextcolor(lamp_s1[1:0])};
                end
                3'd3: begin // EW green expires -> EW yellow
                    phase    <= 3'd4;
                    lamp_s1  <= {lamp_s1[3:2], nextcolor(lamp_s1[1:0])};
                end
                3'd4: begin // EW yellow expires -> all red
                    phase    <= 3'd5;
                    lamp_s1  <= {lamp_s1[3:2], nextcolor(lamp_s1[1:0])};
                end
                3'd5: begin // all red -> NS green
                    phase    <= 3'd0;
                    lamp_s1  <= {nextcolor(lamp_s1[3:2]), lamp_s1[1:0]};
                end
                default: begin
                    phase <= phase;
                end
                endcase
            end
        end
    end

    assign o_ns_green = (ns_state == GREEN);
    assign o_ew_green = (ew_state == GREEN);
    assign o_phase    = phase;

    // P: the two roads are never green at the same time
    always @(*)
        if (ns_state == GREEN)
            assert (ew_state != GREEN);

   // Q: during the all-red clearance phases neither road may show green
   always @(posedge clk)
       if (phase == 3'd2 || phase == 3'd5)
           assert ((ns_state != GREEN) && (ew_state != GREEN));
endmodule

module ringq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire push,
    input wire pop
);
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg       empty_r, full_r;
reg       stage_v;
initial begin wptr = 2'd0; rptr = 2'd0; count = 3'd0; empty_r = 1'b1; full_r = 1'b0; stage_v = 1'b0; end

// registered write path: a push lands in the staging slot first and is
// committed into the ring array on the next enabled cycle
wire do_stage = i_ce && push && !full_r;
wire do_push  = i_ce && stage_v;
    wire do_pop  = i_ce && pop  && !empty_r;
    wire [1:0] nw = wptr + do_push;
    wire [1:0] nr = rptr + do_pop;
wire       nstage = do_stage || (stage_v && !do_push);
wire [2:0] ncount = count + do_push - do_pop;
// entries the queue owns: ring body plus whatever is still staged
wire [2:0] nlevel = ncount + {2'b0, nstage};

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 2'd0; rptr <= 2'd0; count <= 3'd0;
            empty_r <= 1'b1; full_r <= 1'b0;
stage_v <= 1'b0;
        end else begin
            wptr <= nw;
            rptr <= nr;
            empty_r <= (nw == nr) && (do_pop  || (empty_r && !do_push));
full_r  <= (nlevel == 3'd4);
count   <= ncount;
stage_v <= nstage;
        end
    end

    always @(posedge clk)
        if (empty_r)
            assert (!full_r);
endmodule

module smbus_pec_mon (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire scl_low,
    input wire wvalid,
    input wire [127:0] wdata
);
    localparam [5:0] TMAX = 6'd50;

    reg [5:0]   low_cnt      = 6'd0;
    reg         timeout_flag = 1'b0;
    reg         before_to    = 1'b1;
    reg [127:0] wbuf         = 128'd0;
    reg         pend         = 1'b0;
    reg         pend_cnt     = 1'b0;
    reg [7:0]   pec_acc      = 8'h00;
    reg [6:0]   wcnt         = 7'd0;
    reg [7:0]   pec_snap     = 8'h00;
    reg         pv           = 1'b0;

    function [7:0] crc8_128;
        input [7:0] c;
        input [127:0] d;
        integer i;
        reg [7:0] r;
        reg fb;
        begin
            r = c;
            for (i = 127; i >= 0; i = i - 1) begin
                fb = r[7] ^ d[i];
                r = {r[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);
            end
            crc8_128 = r;
        end
    endfunction

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (!rst_n) begin
            low_cnt      <= 6'd0;
            timeout_flag <= 1'b0;
            before_to    <= 1'b1;
            wbuf         <= 128'd0;
            pend         <= 1'b0;
            pend_cnt     <= 1'b0;
            pec_acc      <= 8'h00;
            wcnt         <= 7'd0;
            pec_snap     <= 8'h00;
        end else if (en) begin
            if (!scl_low)
                low_cnt <= 6'd0;
            else if (low_cnt < TMAX)
                low_cnt <= low_cnt + 6'd1;

            if (low_cnt == TMAX - 6'd1 && scl_low) begin
                timeout_flag <= 1'b1;
                before_to    <= 1'b0;
            end

            if (wvalid)
                wbuf <= wdata;

            if (wvalid)
                pend <= 1'b1;
            else if (pend)
                pend <= 1'b0;

            if (wvalid)
                pend_cnt <= 1'b1;
            else if (pend_cnt)
                pend_cnt <= 1'b0;

            if (pend)
                pec_acc <= crc8_128(pec_acc, wbuf);

            if (pend_cnt) begin
                wcnt     <= wcnt + 7'd1;
                pec_snap <= crc8_128(pec_acc, wbuf);
            end
        end
    end

    always @(posedge clk)
        if (pv && $past(rst_n) && before_to && $past(before_to) && $stable(wcnt))
            assert ($stable(pec_acc));
endmodule

module ec_jdbl_seq (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        arm,
    input  wire        start,
    input  wire        clr,
    input  wire        sel_add,
    input  wire        wr_en,
    input  wire [3:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire        o_done,
    output wire [31:0] o_acc,
    output wire [31:0] o_x3
);
    localparam [31:0] PRIME = 32'hFFFFFFFB;
    localparam [31:0] LAST  = 32'd11;
    localparam [1:0]  OP_MUL = 2'd0;
    localparam [1:0]  OP_ADD = 2'd1;
    localparam [1:0]  OP_SUB = 2'd2;

    reg        armed;
    reg        started;
    reg        done;
    reg        pre_clr;
    reg        mode;
    reg [31:0] step;
    reg [31:0] acc;
    reg [31:0] rf [0:15];

    integer i;
    initial begin
        armed   = 1'b0;
        started = 1'b0;
        done    = 1'b0;
        pre_clr = 1'b1;
        mode    = 1'b0;
        step    = 32'd0;
        acc     = 32'd0;
        for (i = 0; i < 16; i = i + 1)
            rf[i] = 32'd0;
    end

    function [31:0] fadd;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            s = {1'b0, a} + {1'b0, b};
            if (s >= {1'b0, PRIME})
                s = s - {1'b0, PRIME};
            fadd = s[31:0];
        end
    endfunction

    function [31:0] fsub;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            if (a >= b)
                s = {1'b0, a} - {1'b0, b};
            else
                s = {1'b0, a} + {1'b0, PRIME} - {1'b0, b};
            fsub = s[31:0];
        end
    endfunction

    function [31:0] fmul;
        input [31:0] a;
        input [31:0] b;
        reg [63:0] p;
        reg [35:0] t;
        reg [35:0] u;
        begin
            p = {32'd0, a} * {32'd0, b};
            t = {4'd0, p[31:0]} + {4'd0, p[63:32]} * 36'd5;
            u = {4'd0, t[31:0]} + {32'd0, t[35:32]} * 36'd5;
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            fmul = u[31:0];
        end
    endfunction

    reg [3:0] ra, rb, rd;
    reg [1:0] opc;
    always @(*) begin
        ra  = 4'd0;
        rb  = 4'd0;
        rd  = 4'd6;
        opc = OP_MUL;
        case (step)
            32'd1:  begin ra = 4'd1;  rb = mode ? 4'd4 : 4'd1; rd = 4'd6;  opc = OP_MUL; end
            32'd2:  begin ra = 4'd0;  rb = 4'd6;  rd = 4'd7;  opc = OP_MUL; end
            32'd3:  begin ra = 4'd0;  rb = mode ? 4'd3 : 4'd0; rd = 4'd8;  opc = OP_MUL; end
            32'd4:  begin ra = 4'd8;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd5:  begin ra = 4'd9;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd6:  begin ra = 4'd9;  rb = 4'd9;  rd = 4'd10; opc = OP_MUL; end
            32'd7:  begin ra = 4'd7;  rb = 4'd7;  rd = 4'd11; opc = OP_ADD; end
            32'd8:  begin ra = 4'd10; rb = 4'd11; rd = 4'd12; opc = OP_SUB; end
            32'd9:  begin ra = mode ? 4'd2 : 4'd1; rb = mode ? 4'd5 : 4'd2; rd = 4'd13; opc = OP_MUL; end
            32'd10: begin ra = 4'd6;  rb = 4'd6;  rd = 4'd15; opc = OP_MUL; end
            default: begin ra = 4'd0; rb = 4'd0; rd = 4'd6; opc = OP_MUL; end
        endcase
    end

    wire [31:0] opa = rf[ra];
    wire [31:0] opb = rf[rb];
    reg  [31:0] res;
    always @(*) begin
        case (opc)
            OP_MUL:  res = fmul(opa, opb);
            OP_ADD:  res = fadd(opa, opb);
            OP_SUB:  res = fsub(opa, opb);
            default: res = opa;
        endcase
    end

    wire [31:0] y3 = fsub(fmul(rf[9], fsub(rf[7], rf[12])), rf[15]);
    wire [31:0] z3 = fadd(rf[13], rf[13]);

    always @(posedge clk) begin
        if (rst) begin
            armed   <= 1'b0;
            started <= 1'b0;
            done    <= 1'b0;
            pre_clr <= 1'b1;
            mode    <= 1'b0;
            step    <= 32'd0;
            acc     <= 32'd0;
        end else if (en) begin
            if (clr) begin
                armed   <= 1'b0;
                started <= 1'b0;
                done    <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (arm)
                    armed <= 1'b1;
                if (start && armed && step == 32'd0)
                    started <= 1'b1;
                if (step == LAST)
                    done <= 1'b1;
            end
            if (step == 32'd0) begin
                if (start && armed && !clr) begin
                    step <= 32'd1;
                    mode <= sel_add;
                end
            end else if (step == LAST) begin
                step <= 32'd0;
                acc  <= y3;
            end else begin
                step <= step + 32'd1;
                acc  <= res;
            end
        end
    end

    always @(posedge clk) begin
        if (!rst && en) begin
            if (step == 32'd0) begin
                if (wr_en)
                    rf[wr_addr] <= wr_data;
            end else if (step == LAST) begin
                rf[0] <= rf[12];
                rf[1] <= y3;
                rf[2] <= z3;
            end else begin
                rf[rd] <= res;
            end
        end
    end

    assign o_done = done;
    assign o_acc  = acc;
    assign o_x3   = rf[0];

    always @(*)
        if (pre_clr && done)
            assert (started && armed);
endmodule

module cdc_line_edge_fifo (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [127:0] din,
    input  wire         rd_en,
    input  wire         cfg_set,
    output wire [127:0] dout,
    output reg          full,
    output reg          empty
);
    reg [127:0] prev;
    reg [127:0] mem [0:15];
    reg [3:0]   wr_ptr;
    reg [3:0]   rd_ptr;
    reg [4:0]   count;
    reg         armed;
    reg         pv;
    integer i;

    initial begin
        prev   = 128'd0;
        wr_ptr = 4'd0;
        rd_ptr = 4'd0;
        count  = 5'd0;
        full   = 1'b0;
        empty  = 1'b1;
        armed  = 1'b0;
        pv     = 1'b0;
        for (i = 0; i < 16; i = i + 1) mem[i] = 128'd0;
    end

    wire edge_seen = en && (din != prev);
    wire push = edge_seen && !full;
    wire pop  = en && rd_en && !empty;
    wire [4:0] count_next = count + {4'd0, push} - {4'd0, pop};

    assign dout = mem[rd_ptr];

    always @(posedge clk) begin
        if (!rst_n) begin
            prev   <= 128'd0;
            wr_ptr <= 4'd0;
            rd_ptr <= 4'd0;
            count  <= 5'd0;
            full   <= 1'b0;
            empty  <= 1'b1;
            armed  <= 1'b0;
        end else if (en) begin
            prev <= din;
            if (push) begin
                mem[wr_ptr] <= din;
                wr_ptr <= wr_ptr + 4'd1;
            end
            if (pop)
                rd_ptr <= rd_ptr + 4'd1;
            count <= count_next;
            full  <= (count_next == 5'd16);
            empty <= (count_next == 5'd0);
            armed <= armed | cfg_set;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && rst_n && armed && $rose(edge_seen))
            assert (!(full && empty));
endmodule

module lssd_scan_dump (
    input  wire        clk,
    input  wire        en,
    input  wire        scan_req,
    input  wire        tdi,
    input  wire        cap,
    input  wire [63:0] sys_d0,
    input  wire [63:0] sys_d1,
    output wire        tdo,
    output wire        busy_o
);
    reg [63:0] l1_0 = 64'd0;
    reg [63:0] l1_1 = 64'd0;
    reg [63:0] l2_0 = 64'd0;
    reg [63:0] l2_1 = 64'd0;
    reg        busy = 1'b0;
    reg        ph   = 1'b0;
    reg [6:0]  sc   = 7'd0;
    reg [7:0]  cd   = 8'd0;

    assign tdo    = l2_1[63];
    assign busy_o = busy;

    always @(posedge clk) begin
        if (en) begin
            if (!busy) begin
                if (scan_req) begin
                    busy <= 1'b1;
                    cd   <= 8'd128;
                    sc   <= 7'd0;
                    ph   <= 1'b0;
                end else begin
                    if (cap) begin
                        l1_0 <= sys_d0;
                        l1_1 <= sys_d1;
                    end
                    l2_0 <= l1_0;
                    l2_1 <= l1_1;
                end
            end else begin
                cd <= cd - 8'd1;
                if (!ph) begin
                    l1_0 <= {l2_0[62:0], tdi};
                    l1_1 <= {l2_1[62:0], l2_0[63]};
                    ph   <= 1'b1;
                end else begin
                    l2_0 <= l1_0;
                    l2_1 <= l1_1;
                    ph   <= 1'b0;
                    if (sc == 7'd63) begin
                        busy <= 1'b0;
                        sc   <= 7'd0;
                    end else begin
                        sc   <= sc + 7'd1;
                    end
                end
            end
        end
    end

    always @(*) begin
        if (busy)
            assert (cd != 8'd0);
        else
            assert (cd == 8'd0);
    end
endmodule

module mips_wb_scoreboard (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [15:0] req_vec,
    input wire q_open,
    input wire r_close,
    output wire wb_valid,
    output reg [3:0] wb_idx
);
    reg [15:0] pend = 16'd0;
    reg busy = 1'b0;
    reg [7:0] cnt = 8'd0;
    reg win = 1'b0;

    wire [15:0] low = pend & (~pend + 16'd1);
    wire [15:0] pend_next = pend & ~low;

    reg [4:0] pc;
    integer i;
    always @(*) begin
        wb_idx = 4'd0;
        for (i = 15; i >= 0; i = i - 1)
            if (pend[i]) wb_idx = i[3:0];
    end

    integer j;
    always @(*) begin
        pc = 5'd0;
        for (j = 0; j < 16; j = j + 1)
            pc = pc + {4'd0, pend[j]};
    end

    assign wb_valid = en && busy;

    always @(posedge clk) begin
        if (en) begin
            if (rst) begin
                pend <= 16'd0;
                busy <= 1'b0;
                cnt <= 8'd0;
                win <= 1'b0;
            end else begin
                if (q_open)
                    win <= 1'b1;
                else if (r_close)
                    win <= 1'b0;
                if (!busy && req && req_vec != 16'd0) begin
                    pend <= req_vec;
                    busy <= 1'b1;
                    cnt <= 8'd16;
                end else if (busy) begin
                    pend <= pend_next;
                    cnt <= cnt - 8'd1;
                    if (pend_next == 16'd0)
                        busy <= 1'b0;
                end
            end
        end
    end

    always @(*) assert (!(win && busy) || cnt != 8'd0);
endmodule

module relo_belt (
    input wire clk,
    input wire rst,
    input wire en,
    input wire drop,
    input wire [63:0] din,
    input wire [4:0] rd_pos,
    input wire ckpt_open,
    input wire ckpt_close,
    output wire [63:0] dout
);
    reg [63:0] slot [0:31];
    reg [4:0] head;
    reg [63:0] drops;
    reg [63:0] win_cnt;
    reg win;
    integer i;

    initial begin
        for (i = 0; i < 32; i = i + 1)
            slot[i] = 64'd0;
        head = 5'd0;
        drops = 64'd0;
        win_cnt = 64'd0;
        win = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < 32; i = i + 1)
                slot[i] <= 64'd0;
            head <= 5'd0;
            drops <= 64'd0;
            win_cnt <= 64'd0;
            win <= 1'b0;
        end else if (en) begin
            if (drop) begin
                slot[head] <= din;
                head <= head + 5'd1;
                drops <= drops + 64'd1;
                if (win)
                    win_cnt <= win_cnt + 64'd1;
            end
            if (ckpt_close) begin
                win <= 1'b0;
            end else if (ckpt_open) begin
                win <= 1'b1;
                win_cnt <= 64'd0;
            end
        end
    end

    assign dout = slot[head - 5'd1 - rd_pos];

    always @(posedge clk)
        if (win && !rst)
            assert (head == drops[4:0]);
endmodule

module rdf_lockstep_wl (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [63:0] wl_in,
    input wire close_in,
    input wire eco_in
);
    reg [63:0] acc_a = 64'd0;
    reg [63:0] acc_b = 64'd0;
    reg [63:0] step_cnt = 64'd0;
    reg mism_q = 1'b0;
    reg err_q = 1'b0;
    reg ok_q = 1'b0;
    reg pre_eco = 1'b1;

    wire [63:0] nxt_a = acc_a + wl_in;
    wire [63:0] nxt_b = acc_b + wl_in;

    always @(posedge clk) begin
        if (rst) begin
            acc_a <= 64'd0;
            acc_b <= 64'd0;
            step_cnt <= 64'd0;
            mism_q <= 1'b0;
            err_q <= 1'b0;
            ok_q <= 1'b0;
            pre_eco <= 1'b1;
        end else if (en) begin
            acc_a <= nxt_a;
            acc_b <= nxt_b;
            step_cnt <= step_cnt + 64'd1;
            mism_q <= (nxt_a != nxt_b);
            err_q <= err_q | mism_q;
            ok_q <= ok_q | close_in;
            pre_eco <= pre_eco & ~eco_in;
        end
    end

    always @(posedge clk) assert (!pre_eco || !(mism_q && ok_q));
endmodule

module hdmi_agc (
    input wire clk,
    input wire rst,
    input wire en,
    input wire vsync_rise,
    input wire frame_end,
    input wire pix_valid,
    input wire [31:0] luma,
    output wire [31:0] o_pix,
    output wire [31:0] o_gain
);
    localparam [1:0] IDLE  = 2'd0;
    localparam [1:0] ARMED = 2'd1;
    localparam [1:0] ADAPT = 2'd2;
    localparam [1:0] DONE  = 2'd3;
    localparam [31:0] ARM_TH     = 32'd1000;
    localparam [31:0] TARGET     = 32'd50000;
    localparam [31:0] GSTEP      = 32'd16;
    localparam [31:0] ADAPT_LAST = 32'd63;

    reg [31:0] amp_est;
    reg [31:0] gain;
    reg [31:0] hist [0:63];
    reg [5:0]  wr_ptr;
    reg [31:0] adapt_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done_flag;
    reg        win;

    integer i;
    initial begin
        amp_est    = 32'd0;
        gain       = 32'h00010000;
        wr_ptr     = 6'd0;
        adapt_cnt  = 32'd0;
        phase      = IDLE;
        arm_seen   = 1'b0;
        start_seen = 1'b0;
        done_flag  = 1'b0;
        win        = 1'b0;
        for (i = 0; i < 64; i = i + 1)
            hist[i] = 32'd0;
    end

    wire [31:0] abs_luma = luma[31] ? (~luma + 32'd1) : luma;
    wire [31:0] scaled   = luma * {16'd0, gain[31:16]};
    wire [31:0] amp_next = (abs_luma > amp_est) ? abs_luma : (amp_est - (amp_est >> 4));

    always @(posedge clk) begin
        if (rst) begin
            amp_est    <= 32'd0;
            gain       <= 32'h00010000;
            wr_ptr     <= 6'd0;
            adapt_cnt  <= 32'd0;
            phase      <= IDLE;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            done_flag  <= 1'b0;
            win        <= 1'b0;
        end else if (en) begin
            if (vsync_rise) begin
                win        <= 1'b1;
                phase      <= IDLE;
                arm_seen   <= 1'b0;
                start_seen <= 1'b0;
                done_flag  <= 1'b0;
                adapt_cnt  <= 32'd0;
            end else if (frame_end) begin
                win <= 1'b0;
            end else if (win && pix_valid) begin
                hist[wr_ptr] <= scaled;
                wr_ptr       <= wr_ptr + 6'd1;
                amp_est      <= amp_next;
                case (phase)
                    IDLE: begin
                        if (amp_est > ARM_TH) begin
                            phase    <= ARMED;
                            arm_seen <= 1'b1;
                        end
                    end
                    ARMED: begin
                        if (wr_ptr == 6'd63) begin
                            phase      <= ADAPT;
                            start_seen <= 1'b1;
                        end
                    end
                    ADAPT: begin
                        if (amp_est < TARGET)
                            gain <= gain + GSTEP;
                        else if ((amp_est > TARGET) && (gain > GSTEP))
                            gain <= gain - GSTEP;
                        if (adapt_cnt == ADAPT_LAST) begin
                            phase     <= DONE;
                            done_flag <= 1'b1;
                        end else begin
                            adapt_cnt <= adapt_cnt + 32'd1;
                        end
                    end
                    default: ;
                endcase
            end
        end
    end

    assign o_pix  = hist[wr_ptr];
    assign o_gain = gain;

    always @(*) assert (!(win && done_flag) || start_seen);
    always @(*) assert (!(win && start_seen) || arm_seen);
endmodule

module benes_lane_shuffler (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         in_valid,
    input  wire [511:0] in_data,
    input  wire [7:0]   in_sel,
    input  wire         cfg_we,
    input  wire [7:0]   cfg_addr,
    input  wire [19:0]  cfg_bits,
    output wire         out_valid,
    output wire [511:0] out_data,
    output wire [63:0]  o_beats_done
);
    reg [19:0]  cfg_tab   [0:255];
    reg [3:0]   stage_cfg [0:4];
    reg [19:0]  cfg_pipe  [0:3];
    reg [511:0] data_pipe [0:4];
    reg [4:0]   valid_pipe;
    reg [63:0]  inflight;
    reg [63:0]  beats_done;
    reg         armed;

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) cfg_tab[i] = 20'd0;
        for (i = 0; i < 5; i = i + 1) begin
            stage_cfg[i] = 4'd0;
            data_pipe[i] = 512'd0;
        end
        for (i = 0; i < 4; i = i + 1) cfg_pipe[i] = 20'd0;
        valid_pipe = 5'd0;
        inflight   = 64'd0;
        beats_done = 64'd0;
        armed      = 1'b0;
    end

    // butterfly stage, pair distance 4
    function [511:0] sw4;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw4[0*64 +: 64] = c[0] ? d[4*64 +: 64] : d[0*64 +: 64];
            sw4[4*64 +: 64] = c[0] ? d[0*64 +: 64] : d[4*64 +: 64];
            sw4[1*64 +: 64] = c[1] ? d[5*64 +: 64] : d[1*64 +: 64];
            sw4[5*64 +: 64] = c[1] ? d[1*64 +: 64] : d[5*64 +: 64];
            sw4[2*64 +: 64] = c[2] ? d[6*64 +: 64] : d[2*64 +: 64];
            sw4[6*64 +: 64] = c[2] ? d[2*64 +: 64] : d[6*64 +: 64];
            sw4[3*64 +: 64] = c[3] ? d[7*64 +: 64] : d[3*64 +: 64];
            sw4[7*64 +: 64] = c[3] ? d[3*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 2
    function [511:0] sw2;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw2[0*64 +: 64] = c[0] ? d[2*64 +: 64] : d[0*64 +: 64];
            sw2[2*64 +: 64] = c[0] ? d[0*64 +: 64] : d[2*64 +: 64];
            sw2[1*64 +: 64] = c[1] ? d[3*64 +: 64] : d[1*64 +: 64];
            sw2[3*64 +: 64] = c[1] ? d[1*64 +: 64] : d[3*64 +: 64];
            sw2[4*64 +: 64] = c[2] ? d[6*64 +: 64] : d[4*64 +: 64];
            sw2[6*64 +: 64] = c[2] ? d[4*64 +: 64] : d[6*64 +: 64];
            sw2[5*64 +: 64] = c[3] ? d[7*64 +: 64] : d[5*64 +: 64];
            sw2[7*64 +: 64] = c[3] ? d[5*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 1 (middle stage)
    function [511:0] sw1;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw1[0*64 +: 64] = c[0] ? d[1*64 +: 64] : d[0*64 +: 64];
            sw1[1*64 +: 64] = c[0] ? d[0*64 +: 64] : d[1*64 +: 64];
            sw1[2*64 +: 64] = c[1] ? d[3*64 +: 64] : d[2*64 +: 64];
            sw1[3*64 +: 64] = c[1] ? d[2*64 +: 64] : d[3*64 +: 64];
            sw1[4*64 +: 64] = c[2] ? d[5*64 +: 64] : d[4*64 +: 64];
            sw1[5*64 +: 64] = c[2] ? d[4*64 +: 64] : d[5*64 +: 64];
            sw1[6*64 +: 64] = c[3] ? d[7*64 +: 64] : d[6*64 +: 64];
            sw1[7*64 +: 64] = c[3] ? d[6*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    wire [19:0] cfg0 = cfg_tab[in_sel];

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < 256; i = i + 1) cfg_tab[i] <= 20'd0;
            for (i = 0; i < 5; i = i + 1) begin
                stage_cfg[i] <= 4'd0;
                data_pipe[i] <= 512'd0;
            end
            for (i = 0; i < 4; i = i + 1) cfg_pipe[i] <= 20'd0;
            valid_pipe <= 5'd0;
            inflight   <= 64'd0;
            beats_done <= 64'd0;
            armed      <= 1'b0;
        end else if (en) begin
            if (cfg_we) begin
                cfg_tab[cfg_addr] <= cfg_bits;
                armed <= 1'b1;
            end
            data_pipe[0] <= sw4(in_data, cfg0[3:0]);
            stage_cfg[0] <= cfg0[3:0];
            cfg_pipe[0]  <= cfg0;
            data_pipe[1] <= sw2(data_pipe[0], cfg_pipe[0][7:4]);
            stage_cfg[1] <= cfg_pipe[0][7:4];
            cfg_pipe[1]  <= cfg_pipe[0];
            data_pipe[2] <= sw1(data_pipe[1], cfg_pipe[1][11:8]);
            stage_cfg[2] <= cfg_pipe[1][11:8];
            cfg_pipe[2]  <= cfg_pipe[1];
            data_pipe[3] <= sw2(data_pipe[2], cfg_pipe[2][15:12]);
            stage_cfg[3] <= cfg_pipe[2][15:12];
            cfg_pipe[3]  <= cfg_pipe[2];
            data_pipe[4] <= sw4(data_pipe[3], cfg_pipe[3][19:16]);
            stage_cfg[4] <= cfg_pipe[3][19:16];
            valid_pipe <= {valid_pipe[3:0], in_valid};
            inflight   <= inflight + {63'd0, in_valid} - {63'd0, valid_pipe[4]};
            if (valid_pipe[4])
                beats_done <= beats_done + 64'd1;
        end
    end

    assign out_valid    = valid_pipe[4];
    assign out_data     = data_pipe[4];
    assign o_beats_done = beats_done;

    always @(posedge clk)
        if (armed)
            assert (inflight <= 64'd5);
endmodule

module wrapped_quad_dec (
    input  wire        clk,
    input  wire        rst,
    input  wire        proj_en,
    input  wire        enc_a,
    input  wire        enc_b,
    input  wire        wbs_stb_i,
    input  wire        wbs_cyc_i,
    input  wire        wbs_we_i,
    input  wire [3:0]  wbs_adr_i,
    output wire [31:0] wbs_dat_o,
    output wire        wbs_ack_o
);
    reg        a_q = 1'b0;
    reg        b_q = 1'b0;
    reg [15:0] pos = 16'd0;
    reg [15:0] err_cnt = 16'd0;
    reg        seen_step = 1'b0;
    reg        armed = 1'b0;
    reg        ack_q = 1'b0;

    wire da   = enc_a ^ a_q;
    wire db   = enc_b ^ b_q;
    wire step = da ^ db;
    wire dbl  = da & db;
    wire up   = a_q ^ enc_b;
    wire rd0  = proj_en && wbs_stb_i && wbs_cyc_i && !wbs_we_i && (wbs_adr_i == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            a_q       <= 1'b0;
            b_q       <= 1'b0;
            pos       <= 16'd0;
            err_cnt   <= 16'd0;
            seen_step <= 1'b0;
            armed     <= 1'b0;
            ack_q     <= 1'b0;
        end else if (proj_en) begin
            a_q <= enc_a;
            b_q <= enc_b;
            if (step) begin
                seen_step <= 1'b1;
                if (up)
                    pos <= pos + 16'd1;
                else
                    pos <= pos - 16'd1;
            end else if (dbl) begin
                err_cnt <= err_cnt + 16'd1;
            end
            if (rd0)
                armed <= 1'b1;
            ack_q <= wbs_stb_i && wbs_cyc_i && !ack_q;
        end
    end

    assign wbs_ack_o = ack_q;
    assign wbs_dat_o = (wbs_adr_i == 4'd0) ? {{16{pos[15]}}, pos} : {16'd0, err_cnt};

    assert property (!(armed && (pos != 16'd0)) || seen_step);
endmodule

module tcu_useq (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [2:0]  op,
    input  wire        cond,
    input  wire [1:0]  sel,
    input  wire        tw_en,
    input  wire [1:0]  tw_idx,
    input  wire [15:0] tw_data,
    output wire [15:0] upc_o,
    output wire        ret_valid_o
);
    localparam [2:0] OP_INC  = 3'd0;
    localparam [2:0] OP_JMP  = 3'd1;
    localparam [2:0] OP_BR   = 3'd2;
    localparam [2:0] OP_CALL = 3'd3;
    localparam [2:0] OP_RET  = 3'd4;

    reg [15:0] upc;
    reg [15:0] jt0, jt1, jt2, jt3;
    reg [15:0] ret_reg;
    reg        ret_valid;
    reg [15:0] shadow_ret;
    reg        pv;

    initial upc = 16'h0000;
    initial jt0 = 16'h0000;
    initial jt1 = 16'h0000;
    initial jt2 = 16'h0000;
    initial jt3 = 16'h0000;
    initial ret_reg = 16'h0000;
    initial ret_valid = 1'b0;
    initial shadow_ret = 16'h0000;
    initial pv = 1'b0;

    reg [15:0] tgt;
    always @(*) begin
        case (sel)
            2'd0: tgt = jt0;
            2'd1: tgt = jt1;
            2'd2: tgt = jt2;
            default: tgt = jt3;
        endcase
    end

    wire [15:0] upc_inc = upc + 16'h0001;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            upc        <= 16'h0000;
            jt0        <= 16'h0000;
            jt1        <= 16'h0000;
            jt2        <= 16'h0000;
            jt3        <= 16'h0000;
            ret_reg    <= 16'h0000;
            ret_valid  <= 1'b0;
            shadow_ret <= 16'h0000;
        end else if (en) begin
            if (tw_en) begin
                case (tw_idx)
                    2'd0: jt0 <= tw_data;
                    2'd1: jt1 <= tw_data;
                    2'd2: jt2 <= tw_data;
                    default: jt3 <= tw_data;
                endcase
            end
            case (op)
                OP_INC:  upc <= upc_inc;
                OP_JMP:  upc <= tgt;
                OP_BR:   upc <= cond ? tgt : upc_inc;
                OP_CALL: begin
                    ret_reg    <= upc_inc;
                    shadow_ret <= upc_inc;
                    ret_valid  <= 1'b1;
                    upc        <= tgt;
                end
                OP_RET: begin
                    if (ret_valid) begin
                        upc       <= ret_reg;
                        ret_valid <= 1'b0;
                    end else begin
                        upc <= upc_inc;
                    end
                end
                default: upc <= upc_inc;
            endcase
        end
    end

    assign upc_o = upc;
    assign ret_valid_o = ret_valid;

    always @(posedge clk)
        if (pv && $past(en) && !$past(rst) && ($past(op) == 3'd4) && $past(ret_valid))
            assert (upc == $past(shadow_ret));
endmodule

module nfc_rst_escalator (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire rx_fault,
    output wire sub_rst,
    output wire chip_rst
);
    localparam [63:0] T1 = 64'd4;
    localparam [63:0] T2 = 64'd8;
    localparam [63:0] DECAY = 64'd1000;
    localparam [63:0] CNT_MAX = 64'hFFFF_FFFF_FFFF_FFFF;

    reg [63:0] fault_cnt = 64'd0;
    reg [63:0] decay_tmr = 64'd0;
    reg sub_rst_q = 1'b0;
    reg chip_rst_q = 1'b0;
    reg armed = 1'b0;

    wire [63:0] inc = fault_cnt + 64'd1;
    wire [63:0] dec = fault_cnt - 64'd1;

    always @(posedge clk) begin
        if (!rst_n) begin
            fault_cnt <= 64'd0;
            decay_tmr <= 64'd0;
            sub_rst_q <= 1'b0;
            chip_rst_q <= 1'b0;
            armed <= 1'b0;
        end else if (en) begin
            armed <= armed | sub_rst_q;
            if (rx_fault) begin
                if (fault_cnt != CNT_MAX) begin
                    fault_cnt <= inc;
                    if (inc == T1)
                        sub_rst_q <= 1'b1;
                    if (inc == T2) begin
                        chip_rst_q <= 1'b1;
                        sub_rst_q <= 1'b0;
                    end
                end
            end else begin
                if (decay_tmr == DECAY) begin
                    decay_tmr <= 64'd0;
                    if (fault_cnt != 64'd0) begin
                        fault_cnt <= dec;
                        if (dec == T2 - 64'd1) begin
                            chip_rst_q <= 1'b0;
                            sub_rst_q <= 1'b1;
                        end
                        if (dec == T1 - 64'd1)
                            sub_rst_q <= 1'b0;
                    end
                end else begin
                    decay_tmr <= decay_tmr + 64'd1;
                end
            end
        end
    end

    assign sub_rst = sub_rst_q;
    assign chip_rst = chip_rst_q;

    always @(*)
        if (armed)
            assert (!(sub_rst_q && chip_rst_q));
endmodule

module pix_palette_bimap (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire [1:0] op,
    input wire [7:0] din_a,
    input wire [7:0] din_b,
    output wire hit,
    output wire [5:0] addr,
    output wire [7:0] partner
);
    // 48 entries x 8 bits, flattened: entry i lives at [i*8 +: 8]
    reg [383:0] key_mem = 384'd0;
    reg [383:0] val_mem = 384'd0;
    reg [47:0]  valid = 48'd0;
    reg [5:0]   wr_ptr = 6'd0;
    reg         hit_q = 1'b0;
    reg [5:0]   addr_q = 6'd0;
    reg [7:0]   partner_q = 8'd0;
    reg         ever_ins = 1'b0;
    reg         pre_flush = 1'b1;

    assign hit = hit_q;
    assign addr = addr_q;
    assign partner = partner_q;

    // parallel search, lowest matching index wins
    reg       m_hit;
    reg [5:0] m_addr;
    reg [7:0] m_partner;
    reg [7:0] sel;
    integer i;
    always @(*) begin
        m_hit = 1'b0;
        m_addr = 6'd0;
        m_partner = 8'd0;
        sel = 8'd0;
        for (i = 47; i >= 0; i = i - 1) begin
            sel = (op == 2'b01) ? val_mem[i*8 +: 8] : key_mem[i*8 +: 8];
            if (valid[i] && (sel == din_a)) begin
                m_hit = 1'b1;
                m_addr = i;
                m_partner = (op == 2'b01) ? key_mem[i*8 +: 8] : val_mem[i*8 +: 8];
            end
        end
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            valid <= 48'd0;
            hit_q <= 1'b0;
            addr_q <= 6'd0;
            partner_q <= 8'd0;
            ever_ins <= 1'b0;
            pre_flush <= 1'b1;
            wr_ptr <= 6'd0;
        end else if (en) begin
            case (op)
                2'b00, 2'b01: begin
                    hit_q <= m_hit;
                    addr_q <= m_addr;
                    partner_q <= m_partner;
                end
                2'b10: begin
                    key_mem[wr_ptr*8 +: 8] <= din_a;
                    val_mem[wr_ptr*8 +: 8] <= din_b;
                    valid[wr_ptr] <= 1'b1;
                    ever_ins <= 1'b1;
                    wr_ptr <= (wr_ptr == 6'd47) ? 6'd0 : wr_ptr + 6'd1;
                end
                default: begin
                    valid <= 48'd0;
                    hit_q <= 1'b0;
                    ever_ins <= 1'b0;
                    pre_flush <= 1'b0;
                end
            endcase
        end
    end

    // Precedence: before the first flush, a registered hit requires a prior insert
    always @(posedge clk)
        assert (!(pre_flush && hit_q) || ever_ins);
endmodule

module cam_key_scan (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [7:0]  col_in,
    output reg  [31:0] row_n,
    output wire [7:0]  key_map_out
);
    localparam [7:0] DWELL = 8'd200;

    reg [7:0] row_idx;
    reg [7:0] scan_tmr;
    reg [7:0] key_map [0:31];
    integer i;

    initial begin
        row_idx  = 8'd0;
        scan_tmr = 8'd0;
        row_n    = 32'hFFFF_FFFE;
        for (i = 0; i < 32; i = i + 1) key_map[i] = 8'd0;
    end

    wire [7:0] nxt = (row_idx == 8'd31) ? 8'd0 : (row_idx + 8'd1);

    always @(posedge clk) begin
        if (rst) begin
            row_idx  <= 8'd0;
            scan_tmr <= 8'd0;
            row_n    <= 32'hFFFF_FFFE;
        end else if (en) begin
            if (scan_tmr == DWELL - 8'd1) begin
                scan_tmr <= 8'd0;
                key_map[row_idx[4:0]] <= ~col_in;
                row_idx  <= nxt;
                row_n    <= ~(32'b1 << nxt);
            end else begin
                scan_tmr <= scan_tmr + 8'd1;
            end
        end
    end

    assign key_map_out = key_map[row_idx[4:0]];

    reg pv = 1'b0;
    reg rst_q = 1'b1;
    always @(posedge clk) begin
        pv    <= 1'b1;
        rst_q <= rst;
    end

    always @(posedge clk)
        if (pv && !rst_q)
            assert (row_n == $past(row_n) || row_n == {$past(row_n[30:0]), $past(row_n[31])});
endmodule

module qpsk_mw_cfg (
    input wire clk,
    input wire rst,
    input wire en,
    input wire cs,
    input wire di,
    output wire dout,
    output reg do_oe
);
    localparam [2:0] IDLE = 3'd0, START = 3'd1, OPCODE = 3'd2, ADDR = 3'd3, DATA = 3'd4;

    reg [2:0]  phase;
    reg [63:0] cnt;
    reg [7:0]  oa_sr;
    reg [63:0] dat_sr;
    reg [63:0] mem [0:63];
    reg [63:0] wr_cnt;
    reg        pre_commit;
    integer i;

    initial begin
        phase = IDLE; cnt = 64'd0; oa_sr = 8'd0; dat_sr = 64'd0;
        do_oe = 1'b0; wr_cnt = 64'd0; pre_commit = 1'b1;
        for (i = 0; i < 64; i = i + 1) mem[i] = 64'd0;
    end

    wire [7:0]  oa_next  = {oa_sr[6:0], di};
    wire        is_read  = (oa_sr[7:6] == 2'b10);
    wire [63:0] dat_next = {dat_sr[62:0], di};

    assign dout = do_oe & dat_sr[63];

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE; cnt <= 64'd0; oa_sr <= 8'd0; dat_sr <= 64'd0;
            do_oe <= 1'b0; wr_cnt <= 64'd0; pre_commit <= 1'b1;
        end else if (en) begin
            if (!cs) begin
                phase <= IDLE;
                do_oe <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (di) phase <= START;
                    end
                    START: begin
                        phase <= OPCODE;
                        cnt <= 64'd2;
                    end
                    OPCODE: begin
                        oa_sr <= oa_next;
                        if (cnt == 64'd1) begin
                            phase <= ADDR;
                            cnt <= 64'd6;
                        end else begin
                            cnt <= cnt - 64'd1;
                        end
                    end
                    ADDR: begin
                        oa_sr <= oa_next;
                        if (cnt == 64'd1) begin
                            phase <= DATA;
                            cnt <= 64'd64;
                            do_oe <= (oa_next[7:6] == 2'b10);
                            if (oa_next[7:6] == 2'b10)
                                dat_sr <= mem[oa_next[5:0]];
                        end else begin
                            cnt <= cnt - 64'd1;
                        end
                    end
                    DATA: begin
                        if (is_read)
                            dat_sr <= {dat_sr[62:0], 1'b0};
                        else
                            dat_sr <= dat_next;
                        if (cnt == 64'd1) begin
                            if (!is_read) begin
                                mem[oa_sr[5:0]] <= dat_next;
                                wr_cnt <= wr_cnt + 64'd1;
                                pre_commit <= 1'b0;
                            end
                            phase <= IDLE;
                            do_oe <= 1'b0;
                        end else begin
                            cnt <= cnt - 64'd1;
                        end
                    end
                    default: begin
                        phase <= IDLE;
                    end
                endcase
            end
        end
    end

    always @(*)
        if (pre_commit)
            assert (!(phase == 3'd3 && do_oe));
endmodule

module vcd_mac_learn (
    input wire clk,
    input wire rst,
    input wire en,
    input wire learn_v,
    input wire [31:0] src_mac,
    input wire [3:0] src_port,
    input wire look_v,
    input wire [31:0] dst_mac,
    input wire age_tick,
    input wire win_open,
    input wire win_close,
    output wire o_hit,
    output wire [3:0] o_port,
    output wire o_win
);
    reg [383:0] key_flat;
    reg [47:0]  port_flat;
    reg [11:0]  valid;
    reg [11:0]  age;
    reg [3:0]   rr_ptr;
    reg [31:0]  learn_cnt;
    reg         hit_q;
    reg [3:0]   out_port;
    reg         win;

    initial key_flat = 384'd0;
    initial port_flat = 48'd0;
    initial valid = 12'd0;
    initial age = 12'd0;
    initial rr_ptr = 4'd0;
    initial learn_cnt = 32'd0;
    initial hit_q = 1'b0;
    initial out_port = 4'd0;
    initial win = 1'b0;

    assign o_hit = hit_q;
    assign o_port = out_port;
    assign o_win = win;

    integer i;
    reg match_any;
    reg [3:0] match_idx;
    reg free_any;
    reg [3:0] free_idx;
    reg look_hit;
    reg [3:0] look_idx;
    always @(*) begin
        match_any = 1'b0; match_idx = 4'd0;
        free_any = 1'b0;  free_idx = 4'd0;
        look_hit = 1'b0;  look_idx = 4'd0;
        for (i = 11; i >= 0; i = i - 1) begin
            if (valid[i] && (key_flat[i*32 +: 32] == src_mac)) begin
                match_any = 1'b1; match_idx = i;
            end
            if (!valid[i]) begin
                free_any = 1'b1; free_idx = i;
            end
            if (valid[i] && (key_flat[i*32 +: 32] == dst_mac)) begin
                look_hit = 1'b1; look_idx = i;
            end
        end
    end

    wire [3:0] tgt = match_any ? match_idx : (free_any ? free_idx : rr_ptr);

    reg [11:0] valid_n;
    reg [11:0] age_n;
    always @(*) begin
        valid_n = valid;
        age_n = age;
        if (age_tick) begin
            valid_n = valid & age;
            age_n = 12'd0;
        end
        if (look_v && look_hit)
            age_n[look_idx] = 1'b1;
        if (learn_v) begin
            valid_n[tgt] = 1'b1;
            age_n[tgt] = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            key_flat <= 384'd0;
            port_flat <= 48'd0;
            valid <= 12'd0;
            age <= 12'd0;
            rr_ptr <= 4'd0;
            learn_cnt <= 32'd0;
            hit_q <= 1'b0;
            out_port <= 4'd0;
            win <= 1'b0;
        end else if (en) begin
            valid <= valid_n;
            age <= age_n;
            hit_q <= look_v & look_hit;
            if (look_v && look_hit)
                out_port <= port_flat[look_idx*4 +: 4];
            if (learn_v) begin
                key_flat[tgt*32 +: 32] <= src_mac;
                port_flat[tgt*4 +: 4] <= src_port;
                if (!match_any)
                    rr_ptr <= (rr_ptr >= 4'd11) ? 4'd0 : rr_ptr + 4'd1;
                if (learn_cnt != 32'hFFFFFFFF)
                    learn_cnt <= learn_cnt + 32'd1;
            end
            if (win_close)
                win <= 1'b0;
            else if (win_open)
                win <= 1'b1;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && win && $rose(hit_q))
            assert (learn_cnt != 32'd0);
endmodule

module wal_quad_probe (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [63:0] x_in,
    input  wire        cap_req,
    input  wire        stop,
    output reg         done,
    output wire [63:0] i_out,
    output wire [63:0] q
);
    reg [63:0] d0, d1, d2, d3;
    reg [63:0] i_dly;
    reg [63:0] q_out;
    reg [63:0] cnt;
    reg [2:0]  fill;
    reg        pending;
    reg        win;

    initial begin
        d0 = 64'd0; d1 = 64'd0; d2 = 64'd0; d3 = 64'd0;
        i_dly = 64'd0; q_out = 64'd0; cnt = 64'd0;
        fill = 3'd0; pending = 1'b0; win = 1'b0; done = 1'b0;
    end

    assign i_out = i_dly;
    assign q = q_out;

    always @(posedge clk) begin
        if (rst) begin
            d0 <= 64'd0; d1 <= 64'd0; d2 <= 64'd0; d3 <= 64'd0;
            i_dly <= 64'd0; q_out <= 64'd0; cnt <= 64'd0;
            fill <= 3'd0; pending <= 1'b0; win <= 1'b0; done <= 1'b0;
        end else if (en) begin
            d0 <= x_in;
            d1 <= d0;
            d2 <= d1;
            d3 <= d2;
            i_dly <= d1;
            q_out <= (d0 - d3) + 64'd3 * (d1 - d2);
            done <= 1'b0;
            if (cap_req && !pending) begin
                pending <= 1'b1;
                fill    <= 3'd0;
                cnt     <= 64'd5;
                win     <= 1'b1;
            end else begin
                if (stop)
                    win <= 1'b0;
                if (pending) begin
                    if (fill + 3'd1 == 3'd4) begin
                        pending <= 1'b0;
                        cnt     <= 64'd0;
                        fill    <= 3'd4;
                        done    <= 1'b1;
                    end else begin
                        fill <= fill + 3'd1;
                        cnt  <= cnt - 64'd1;
                    end
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && (cnt == 64'd0) && !$past(cnt == 64'd0))
            assert (!pending);
endmodule

module femto_trace_ser (
    input wire clk,
    input wire rst,
    input wire en,
    input wire arm,
    input wire start,
    input wire ack,
    input wire flush,
    input wire [31:0] data_in,
    output wire sout
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, SHIFT = 2'd2, DONE = 2'd3;

    reg [1:0]  phase;
    reg [31:0] load_reg;
    reg [31:0] shift_reg;
    reg [31:0] bit_cnt;
    reg armed_f, started_f, finished_f;
    reg win;

    initial begin
        phase = IDLE;
        load_reg = 32'd0;
        shift_reg = 32'd0;
        bit_cnt = 32'd0;
        armed_f = 1'b0;
        started_f = 1'b0;
        finished_f = 1'b0;
        win = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            load_reg <= 32'd0;
            shift_reg <= 32'd0;
            bit_cnt <= 32'd0;
            armed_f <= 1'b0;
            started_f <= 1'b0;
            finished_f <= 1'b0;
            win <= 1'b0;
        end else if (en) begin
            if (flush) begin
                win <= 1'b0;
                armed_f <= 1'b0;
                started_f <= 1'b0;
                finished_f <= 1'b0;
                phase <= IDLE;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm) begin
                            load_reg <= data_in;
                            armed_f <= 1'b1;
                            phase <= ARMED;
                            win <= 1'b1;
                        end
                    end
                    ARMED: begin
                        if (start) begin
                            shift_reg <= load_reg;
                            bit_cnt <= 32'd0;
                            started_f <= 1'b1;
                            phase <= SHIFT;
                        end
                    end
                    SHIFT: begin
                        shift_reg <= {shift_reg[30:0], 1'b0};
                        bit_cnt <= bit_cnt + 32'd1;
                        if (bit_cnt == 32'd31) begin
                            finished_f <= 1'b1;
                            phase <= DONE;
                        end
                    end
                    DONE: begin
                        if (ack) begin
                            armed_f <= 1'b0;
                            started_f <= 1'b0;
                            finished_f <= 1'b0;
                            phase <= IDLE;
                        end
                    end
                endcase
            end
        end
    end

    assign sout = shift_reg[31];

    always @(posedge clk)
        if (win && finished_f)
            assert (started_f);

    always @(posedge clk)
        if (win && started_f)
            assert (armed_f);
endmodule

module GF8MulCore (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [7:0] a_in,
    input wire [7:0] b_in,
    input wire [7:0] poly_in,
    input wire poly_we,
    output reg done,
    output wire [7:0] result
);
    reg [7:0] acc;
    reg [7:0] a_reg;
    reg [7:0] b_reg;
    reg [7:0] poly;
    reg [7:0] bitcnt;
    reg [7:0] deadline;
    reg busy;
    reg armed;

    initial begin
        acc = 8'd0;
        a_reg = 8'd0;
        b_reg = 8'd0;
        poly = 8'd0;
        bitcnt = 8'd0;
        deadline = 8'd0;
        busy = 1'b0;
        armed = 1'b0;
        done = 1'b0;
    end

    assign result = acc;

    wire [7:0] a_shl = {a_reg[6:0], 1'b0};
    wire [7:0] xtime = a_reg[7] ? (a_shl ^ poly) : a_shl;

    always @(posedge clk) begin
        if (rst) begin
            acc <= 8'd0;
            a_reg <= 8'd0;
            b_reg <= 8'd0;
            poly <= 8'd0;
            bitcnt <= 8'd0;
            deadline <= 8'd0;
            busy <= 1'b0;
            armed <= 1'b0;
            done <= 1'b0;
        end else if (en) begin
            done <= 1'b0;
            if (poly_we && !busy)
                poly <= poly_in;
            if (!busy) begin
                if (req) begin
                    busy <= 1'b1;
                    armed <= 1'b1;
                    acc <= 8'd0;
                    a_reg <= a_in;
                    b_reg <= b_in;
                    bitcnt <= 8'd8;
                    deadline <= 8'd9;
                end
            end else if (bitcnt != 8'd0) begin
                if (b_reg[0])
                    acc <= acc ^ a_reg;
                a_reg <= xtime;
                b_reg <= {1'b0, b_reg[7:1]};
                bitcnt <= bitcnt - 8'd1;
                deadline <= deadline - 8'd1;
            end else begin
                busy <= 1'b0;
                deadline <= 8'd0;
                done <= 1'b1;
            end
        end
    end

    assert property (!(armed && busy) || (deadline != 8'd0));
endmodule

module atalanta_ca_retry (
    input wire clk,
    input wire rst,
    input wire en,
    input wire cmd_valid,
    input wire [63:0] cmd_addr,
    input wire alert_n,
    output reg [63:0] ca_out,
    output reg ca_par
);
    reg [63:0] hist [0:31];
    reg hist_par [0:31];
    reg [4:0] wr_ptr;
    reg [4:0] replay_ptr;
    reg replaying;
    reg [63:0] issue_cnt;
    reg [63:0] log_cnt;
    reg [63:0] err_status;
    reg no_alert_yet;

    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1) begin
            hist[i] = 64'd0;
            hist_par[i] = 1'b0;
        end
        wr_ptr = 5'd0;
        replay_ptr = 5'd0;
        replaying = 1'b0;
        issue_cnt = 64'd0;
        log_cnt = 64'd0;
        err_status = 64'd0;
        no_alert_yet = 1'b1;
        ca_out = 64'd0;
        ca_par = 1'b0;
    end

    wire alert = !alert_n;
    wire do_issue = cmd_valid && !replaying;
    wire [4:0] replay_next = replay_ptr + 5'd1;

    wire [63:0] err_next;
    assign err_next[0] = err_status[0] | (issue_cnt != log_cnt);
    assign err_next[1] = err_status[1] | alert;
    assign err_next[31:2] = err_status[31:2];
    assign err_next[63:32] = replaying ? (err_status[63:32] + 32'd1) : err_status[63:32];

    always @(posedge clk) begin
        if (rst) begin
            wr_ptr <= 5'd0;
            replay_ptr <= 5'd0;
            replaying <= 1'b0;
            issue_cnt <= 64'd0;
            log_cnt <= 64'd0;
            err_status <= 64'd0;
            no_alert_yet <= 1'b1;
            ca_out <= 64'd0;
            ca_par <= 1'b0;
        end else if (en) begin
            err_status <= err_next;
            if (do_issue) begin
                ca_out <= cmd_addr;
                ca_par <= ^cmd_addr;
                hist[wr_ptr] <= cmd_addr;
                hist_par[wr_ptr] <= ^cmd_addr;
                wr_ptr <= wr_ptr + 5'd1;
                issue_cnt <= issue_cnt + 64'd1;
                log_cnt <= log_cnt + 64'd1;
            end
            if (replaying) begin
                ca_out <= hist[replay_ptr];
                ca_par <= hist_par[replay_ptr];
                replay_ptr <= replay_next;
                if (replay_next == wr_ptr)
                    replaying <= 1'b0;
            end
            if (alert) begin
                replaying <= 1'b1;
                replay_ptr <= wr_ptr - 5'd1;
                no_alert_yet <= 1'b0;
            end
        end
    end

    always @(*) assert (!no_alert_yet || err_status == 64'd0);
endmodule

module sc_park_alu (
    input wire clk,
    input wire rst,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire uni_bit,
    input wire util_bit,
    input wire vis_bit,
    input wire win_bit,
    output wire [1:0] o_phase,
    output wire [15:0] o_ones,
    output wire [15:0] o_log0
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3;

    reg [1:0] phase;
    reg arm_seen, start_seen, done_seen;
    reg [15:0] len_cnt;
    reg [15:0] ones_cnt;
    reg [15:0] log_q [0:7];
    reg [2:0] log_ptr;
    integer i;

    initial begin
        phase = IDLE;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        done_seen = 1'b0;
        len_cnt = 16'd0;
        ones_cnt = 16'd0;
        log_ptr = 3'd0;
        for (i = 0; i < 8; i = i + 1) log_q[i] = 16'd0;
    end

    wire m = uni_bit & util_bit;
    wire s = win_bit ? vis_bit : m;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done_seen <= 1'b0;
            len_cnt <= 16'd0;
            ones_cnt <= 16'd0;
            log_ptr <= 3'd0;
            for (i = 0; i < 8; i = i + 1) log_q[i] <= 16'd0;
        end else if (en) begin
            case (phase)
                IDLE: begin
                    if (arm_req) begin
                        phase <= ARMED;
                        arm_seen <= 1'b1;
                    end
                end
                ARMED: begin
                    if (start_req) begin
                        phase <= RUN;
                        start_seen <= 1'b1;
                        len_cnt <= 16'd0;
                        ones_cnt <= 16'd0;
                    end
                end
                RUN: begin
                    len_cnt <= len_cnt + 16'd1;
                    ones_cnt <= ones_cnt + {15'd0, s};
                    if (len_cnt == 16'd699) begin
                        phase <= DONE;
                        done_seen <= 1'b1;
                        log_q[log_ptr] <= ones_cnt;
                        log_ptr <= log_ptr + 3'd1;
                    end
                end
                DONE: begin
                    if (arm_req) phase <= ARMED;
                end
            endcase
        end
    end

    assign o_phase = phase;
    assign o_ones = ones_cnt;
    assign o_log0 = log_q[0];

    always @(posedge clk)
        assert ((!done_seen || start_seen) && (!start_seen || arm_seen));
endmodule

module metron_trace_latch (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [5:0] s,
    input wire [5:0] r,
    input wire trace_on,
    input wire trace_off,
    output wire [5:0] q_out,
    output wire [31:0] cnt_out
);
    reg [5:0] q;
    reg [31:0] live_cnt;
    reg win;
    initial q = 6'b000000;
    initial live_cnt = 32'd0;
    initial win = 1'b0;

    function [31:0] pc6;
        input [5:0] v;
        begin
            pc6 = {31'd0, v[0]} + {31'd0, v[1]} + {31'd0, v[2]}
                + {31'd0, v[3]} + {31'd0, v[4]} + {31'd0, v[5]};
        end
    endfunction

    wire [5:0] q_n = s | (~r & q);
    wire [5:0] rises = q_n & ~q;
    wire [5:0] falls = q & ~q_n;

    always @(posedge clk) begin
        if (rst) begin
            q <= 6'b000000;
            live_cnt <= 32'd0;
            win <= 1'b0;
        end else if (en) begin
            q <= q_n;
            live_cnt <= live_cnt + pc6(rises) - pc6(falls);
            win <= trace_on ? 1'b1 : (trace_off ? 1'b0 : win);
        end
    end

    assign q_out = q;
    assign cnt_out = live_cnt;

    assert property (!win || live_cnt <= 32'd6);
endmodule

module mips_i2c_deglitch (
    input wire clk,
    input wire rst,
    input wire en,
    input wire scl_in,
    input wire sda_in,
    input wire cfg_we,
    input wire [7:0] cfg_din,
    output wire scl_o,
    output wire sda_o
);
    reg [3:0] sh_scl = 4'b1111;
    reg [3:0] sh_sda = 4'b1111;
    reg st_scl = 1'b1;
    reg st_sda = 1'b1;
    reg [7:0] cnt_scl = 8'd0;
    reg [7:0] cnt_sda = 8'd0;
    reg [7:0] flen = 8'd3;
    reg armed = 1'b0;
    reg pv = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            sh_scl <= 4'b1111;
            sh_sda <= 4'b1111;
            st_scl <= 1'b1;
            st_sda <= 1'b1;
            cnt_scl <= 8'd0;
            cnt_sda <= 8'd0;
            flen <= 8'd3;
            armed <= 1'b0;
        end else if (en) begin
            sh_scl <= {sh_scl[2:0], scl_in};
            sh_sda <= {sh_sda[2:0], sda_in};
            if (cfg_we) begin
                flen <= (cfg_din > 8'd12) ? 8'd12 : cfg_din;
                cnt_scl <= 8'd0;
                cnt_sda <= 8'd0;
            end else begin
                if (sh_scl[3] != st_scl) begin
                    if (cnt_scl >= flen) begin
                        st_scl <= sh_scl[3];
                        cnt_scl <= 8'd0;
                        if (st_scl && !sh_scl[3])
                            armed <= 1'b1;
                    end else begin
                        cnt_scl <= cnt_scl + 8'd1;
                    end
                end else begin
                    cnt_scl <= 8'd0;
                end
                if (sh_sda[3] != st_sda) begin
                    if (cnt_sda >= flen) begin
                        st_sda <= sh_sda[3];
                        cnt_sda <= 8'd0;
                    end else begin
                        cnt_sda <= cnt_sda + 8'd1;
                    end
                end else begin
                    cnt_sda <= 8'd0;
                end
            end
        end
    end

    assign scl_o = st_scl;
    assign sda_o = st_sda;

    always @(posedge clk)
        if (pv && $past(armed))
            assert ($past(cnt_scl) <= 8'd12 && $past(cnt_sda) <= 8'd12);
endmodule

module LispDebugBridge (
    input wire clk,
    input wire en,
    input wire start,
    input wire wr_in,
    input wire [3:0] addr_in,
    input wire [63:0] wdata_in,
    output wire busy_o,
    output wire [63:0] rdata_o,
    output wire [63:0] txn_o
);
    // host side
    reg busy = 1'b0;
    reg req_tgl = 1'b0;
    reg ack_s1 = 1'b0;
    reg ack_s2 = 1'b0;
    reg [3:0] addr_q = 4'd0;
    reg wr_q = 1'b0;
    reg [63:0] wdata_q = 64'd0;
    reg [63:0] rdata_q = 64'd0;
    reg [63:0] txn_cnt = 64'd0;
    // core side
    reg req_s1 = 1'b0;
    reg req_s2 = 1'b0;
    reg tgt_seen = 1'b0;
    reg ack_tgl = 1'b0;
    reg [63:0] regs [0:15];
    // verification shadow
    reg [3:0] shadow_addr = 4'd0;
    reg [63:0] shadow_wdata = 64'd0;
    reg win = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1)
            regs[i] = 64'd0;
    end

    wire tgt_fire = (req_s2 != tgt_seen);
    wire launch = start && !busy;

    // host side: launch and completion
    always @(posedge clk) begin
        if (en) begin
            ack_s1 <= ack_tgl;
            ack_s2 <= ack_s1;
            if (launch) begin
                addr_q       <= addr_in;
                wr_q         <= wr_in;
                wdata_q      <= wdata_in;
                req_tgl      <= ~req_tgl;
                busy         <= 1'b1;
                shadow_addr  <= addr_in;
                shadow_wdata <= wdata_in;
                win          <= 1'b1;
            end else if (busy && (ack_s2 == req_tgl)) begin
                busy    <= 1'b0;
                win     <= 1'b0;
                txn_cnt <= txn_cnt + 64'd1;
            end
        end
    end

    // core side: synchronizer and target access
    always @(posedge clk) begin
        if (en) begin
            req_s1 <= req_tgl;
            req_s2 <= req_s1;
            if (tgt_fire) begin
                if (wr_q)
                    regs[addr_q] <= wdata_q;
                else
                    rdata_q <= regs[addr_q];
                tgt_seen <= req_s2;
                ack_tgl  <= ~ack_tgl;
            end
        end
    end

    assign busy_o  = busy;
    assign rdata_o = rdata_q;
    assign txn_o   = txn_cnt;

    // A1: core acts only on the address the host launched
    always @(*) assert (!(win && tgt_fire) || (addr_q == shadow_addr));
    // A2: core writes only the data the host launched
    always @(*) assert (!(win && tgt_fire && wr_q) || (wdata_q == shadow_wdata));
endmodule

module fletcher_seg_offload (
    input wire clk,
    input wire rst,
    input wire en,
    input wire arm,
    input wire in_valid,
    input wire in_last,
    input wire [127:0] in_data,
    output wire chk_valid,
    output wire [31:0] checksum
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3;

    reg [1:0]  phase = IDLE;
    reg        armed_seen = 1'b0;
    reg        started_seen = 1'b0;
    reg        fin_q = 1'b0;
    reg [4:0]  cnt = 5'd0;
    reg [15:0] sumA = 16'd0;
    reg [15:0] sumB = 16'd0;

    assign chk_valid = fin_q;
    assign checksum = {sumB, sumA};

    function [31:0] fold;
        input [15:0] a;
        input [15:0] b;
        input [127:0] d;
        reg [16:0] ta;
        reg [16:0] tb;
        integer i;
        begin
            ta = {1'b0, a};
            tb = {1'b0, b};
            for (i = 0; i < 8; i = i + 1) begin
                ta = ta + {1'b0, d[i*16 +: 16]};
                if (ta >= 17'd65535) ta = ta - 17'd65535;
                tb = tb + ta;
                if (tb >= 17'd65535) tb = tb - 17'd65535;
            end
            fold = {tb[15:0], ta[15:0]};
        end
    endfunction

    wire [31:0] fold_run   = fold(sumA, sumB, in_data);
    wire [31:0] fold_first = fold(16'd0, 16'd0, in_data);

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            fin_q <= 1'b0;
            cnt <= 5'd0;
            sumA <= 16'd0;
            sumB <= 16'd0;
        end else if (en) begin
            case (phase)
                IDLE: begin
                    if (arm) begin
                        phase <= ARMED;
                        armed_seen <= 1'b1;
                    end
                end
                ARMED: begin
                    if (in_valid) begin
                        phase <= RUN;
                        started_seen <= 1'b1;
                        cnt <= 5'd1;
                        sumA <= fold_first[15:0];
                        sumB <= fold_first[31:16];
                    end
                end
                RUN: begin
                    if (in_valid) begin
                        sumA <= fold_run[15:0];
                        sumB <= fold_run[31:16];
                        cnt <= cnt + 5'd1;
                        if (in_last || cnt == 5'd23) begin
                            phase <= DONE;
                            fin_q <= 1'b1;
                        end
                    end
                end
                DONE: begin
                    phase <= IDLE;
                    armed_seen <= 1'b0;
                    started_seen <= 1'b0;
                    fin_q <= 1'b0;
                    cnt <= 5'd0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (fin_q) assert (armed_seen && started_seen);
endmodule

module ol_flow_perfmon (
    input  wire        clk,
    input  wire        en,
    input  wire [7:0]  ev,
    input  wire        cfg_we,
    input  wire [1:0]  cfg_idx,
    input  wire [2:0]  cfg_sel,
    input  wire        rd_en,
    input  wire        clr_all,
    output wire [15:0] rd_data,
    output wire        empty,
    output wire        full
);
    reg [15:0] ctr0, ctr1, ctr2, ctr3;
    reg [2:0]  sel0, sel1, sel2, sel3;
    reg [13:0] stamp;
    reg [15:0] mem [0:63];
    reg [6:0]  wr_ptr, rd_ptr, occ;
    reg        pre_clr;
    reg        pv;

    integer i;
    initial begin
        ctr0 = 16'd0; ctr1 = 16'd0; ctr2 = 16'd0; ctr3 = 16'd0;
        sel0 = 3'd0; sel1 = 3'd1; sel2 = 3'd2; sel3 = 3'd3;
        stamp = 14'd0;
        wr_ptr = 7'd0; rd_ptr = 7'd0; occ = 7'd0;
        pre_clr = 1'b1;
        pv = 1'b0;
        for (i = 0; i < 64; i = i + 1) mem[i] = 16'd0;
    end

    assign empty = (occ == 7'd0);
    wire [6:0] ptr_diff = wr_ptr - rd_ptr;
    assign full  = (ptr_diff == 7'd64);
    assign rd_data = mem[rd_ptr[5:0]];

    wire inc0 = ev[sel0];
    wire inc1 = ev[sel1];
    wire inc2 = ev[sel2];
    wire inc3 = ev[sel3];
    wire wrap0 = inc0 && (ctr0 == 16'hFFFF);
    wire wrap1 = inc1 && (ctr1 == 16'hFFFF);
    wire wrap2 = inc2 && (ctr2 == 16'hFFFF);
    wire wrap3 = inc3 && (ctr3 == 16'hFFFF);
    wire any_wrap = wrap0 | wrap1 | wrap2 | wrap3;
    wire [1:0] wid = wrap0 ? 2'd0 : (wrap1 ? 2'd1 : (wrap2 ? 2'd2 : 2'd3));

    wire do_push = en && !clr_all && any_wrap && !full;
    wire do_pop  = en && !clr_all && rd_en && !empty;

    integer j;
    always @(posedge clk) begin
        pv <= 1'b1;
        if (en) begin
            stamp <= stamp + 14'd1;
            if (cfg_we) begin
                case (cfg_idx)
                    2'd0: sel0 <= cfg_sel;
                    2'd1: sel1 <= cfg_sel;
                    2'd2: sel2 <= cfg_sel;
                    default: sel3 <= cfg_sel;
                endcase
            end
            if (clr_all) begin
                ctr0 <= 16'd0; ctr1 <= 16'd0; ctr2 <= 16'd0; ctr3 <= 16'd0;
                wr_ptr <= 7'd0; rd_ptr <= 7'd0; occ <= 7'd0;
                pre_clr <= 1'b0;
                for (j = 0; j < 64; j = j + 1) mem[j] <= 16'd0;
            end else begin
                if (inc0) ctr0 <= ctr0 + 16'd1;
                if (inc1) ctr1 <= ctr1 + 16'd1;
                if (inc2) ctr2 <= ctr2 + 16'd1;
                if (inc3) ctr3 <= ctr3 + 16'd1;
                if (do_push) begin
                    mem[wr_ptr[5:0]] <= {wid, stamp};
                    wr_ptr <= wr_ptr + 7'd1;
                end
                if (do_pop) rd_ptr <= rd_ptr + 7'd1;
                case ({do_push, do_pop})
                    2'b10:   occ <= occ + 7'd1;
                    2'b01:   occ <= occ - 7'd1;
                    default: occ <= occ;
                endcase
            end
        end
    end

    always @(posedge clk)
        if (pv && $past(pre_clr))
            assert (!($past(full) && $past(empty)));
endmodule

module lfsr_gpio (
    input wire clk,
    input wire rst,
    input wire en,
    input wire wr_out,
    input wire wr_dir,
    input wire wr_lock,
    input wire wr_unlock,
    input wire [31:0] wdata,
    input wire [31:0] pins_in,
    input wire sample,
    output reg [31:0] pin_drive,
    output reg [33:0] box_sum
);
    reg [31:0] out_data;
    reg [31:0] dir;
    reg [31:0] cap0;
    reg [31:0] cap1;
    reg [31:0] cap2;
    reg        lock_win;
    reg        pv;

    initial out_data  = 32'h0000_0000;
    initial dir       = 32'h0000_0000;
    initial pin_drive = 32'h0000_0000;
    initial cap0      = 32'h0000_0000;
    initial cap1      = 32'h0000_0000;
    initial cap2      = 32'h0000_0000;
    initial box_sum   = 34'h0_0000_0000;
    initial lock_win  = 1'b0;
    initial pv        = 1'b0;

    wire [31:0] nxt_out = wr_out ? wdata : out_data;
    wire [31:0] nxt_dir = wr_dir ? wdata : dir;
    wire [31:0] new_cap = pins_in & ~dir;

    always @(posedge clk) begin
        if (rst) begin
            out_data  <= 32'h0000_0000;
            dir       <= 32'h0000_0000;
            pin_drive <= 32'h0000_0000;
            cap0      <= 32'h0000_0000;
            cap1      <= 32'h0000_0000;
            cap2      <= 32'h0000_0000;
            box_sum   <= 34'h0_0000_0000;
            lock_win  <= 1'b0;
        end else if (en) begin
            out_data  <= nxt_out;
            dir       <= nxt_dir;
            pin_drive <= nxt_out & nxt_dir;
            if (sample) begin
                cap0    <= new_cap;
                cap1    <= cap0;
                cap2    <= cap1;
                box_sum <= box_sum + {2'b00, new_cap} - {2'b00, cap2};
            end
            if (wr_unlock)
                lock_win <= 1'b0;
            else if (wr_lock)
                lock_win <= 1'b1;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && lock_win && $past(lock_win) && $stable(out_data) && $stable(dir))
            assert ($stable(pin_drive));
endmodule

module hls_pixclk_swallow (
    input wire clk,
    input wire rst,
    input wire en,
    input wire load,
    input wire [7:0] N,
    input wire [7:0] S,
    output wire strobe
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, STARTED = 2'd2, DONE = 2'd3;

    reg [3:0] pre_cnt = 4'd0;
    reg [7:0] p_cnt = 8'd0;
    reg [7:0] s_cnt = 8'd0;
    reg [7:0] n_reg = 8'd0;
    reg [7:0] s_reg = 8'd0;
    reg [1:0] phase = 2'd0;
    reg armed_seen = 1'b0;
    reg started_seen = 1'b0;
    reg q_seen = 1'b0;

    wire tc = (s_cnt != 8'd0) ? (pre_cnt == 4'd8) : (pre_cnt == 4'd7);
    wire hit = tc && (p_cnt <= 8'd1);
    assign strobe = en && !load && hit;

    always @(posedge clk) begin
        if (rst) begin
            pre_cnt <= 4'd0;
            p_cnt <= 8'd0;
            s_cnt <= 8'd0;
            n_reg <= 8'd0;
            s_reg <= 8'd0;
            phase <= IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            q_seen <= 1'b0;
        end else if (en) begin
            if (load) begin
                n_reg <= N;
                s_reg <= S;
                p_cnt <= N;
                s_cnt <= S;
                pre_cnt <= 4'd0;
                phase <= ARMED;
                armed_seen <= 1'b1;
                started_seen <= 1'b0;
                q_seen <= 1'b1;
            end else begin
                if (tc) begin
                    pre_cnt <= 4'd0;
                    if (p_cnt <= 8'd1) begin
                        p_cnt <= n_reg;
                        s_cnt <= s_reg;
                    end else begin
                        p_cnt <= p_cnt - 8'd1;
                        if (s_cnt != 8'd0)
                            s_cnt <= s_cnt - 8'd1;
                    end
                    case (phase)
                        ARMED: begin
                            phase <= STARTED;
                            started_seen <= 1'b1;
                        end
                        STARTED: begin
                            if (p_cnt <= 8'd1)
                                phase <= DONE;
                        end
                        default: phase <= phase;
                    endcase
                end else begin
                    pre_cnt <= pre_cnt + 4'd1;
                end
            end
        end
    end

    always @(*) assert (!(q_seen && phase == 2'd3) || (started_seen && armed_seen));
endmodule

module dnn_wfuse_ctrl (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire prog_req,
    input wire [2:0] prog_addr,
    input wire [31:0] prog_data,
    input wire lock_req,
    input wire sense_req,
    output wire [31:0] o_rd_data,
    output wire o_locked
);
    localparam [1:0] S_IDLE = 2'd0, S_BURN = 2'd1, S_SENSE = 2'd2;

    reg [31:0] fuse_shadow [0:7];
    reg [7:0]  prog_done;
    reg [31:0] prog_cnt;
    reg [1:0]  fsm;
    reg        pre_lock;
    reg [2:0]  burn_addr;
    reg [31:0] burn_data;
    reg [31:0] rd_data;

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) fuse_shadow[i] = 32'd0;
        prog_done = 8'd0;
        prog_cnt  = 32'd0;
        fsm       = S_IDLE;
        pre_lock  = 1'b1;
        burn_addr = 3'd0;
        burn_data = 32'd0;
        rd_data   = 32'd0;
    end

    wire [3:0] done_pop = prog_done[0] + prog_done[1] + prog_done[2] + prog_done[3]
                        + prog_done[4] + prog_done[5] + prog_done[6] + prog_done[7];

    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 8; i = i + 1) fuse_shadow[i] <= 32'd0;
            prog_done <= 8'd0;
            prog_cnt  <= 32'd0;
            fsm       <= S_IDLE;
            pre_lock  <= 1'b1;
            burn_addr <= 3'd0;
            burn_data <= 32'd0;
            rd_data   <= 32'd0;
        end else if (en) begin
            if (lock_req)
                pre_lock <= 1'b0;
            case (fsm)
                S_IDLE: begin
                    if (pre_lock && prog_req && !prog_done[prog_addr]) begin
                        burn_addr <= prog_addr;
                        burn_data <= prog_data;
                        fsm       <= S_BURN;
                    end else if (!pre_lock && sense_req) begin
                        burn_addr <= prog_addr;
                        fsm       <= S_SENSE;
                    end
                end
                S_BURN: begin
                    fuse_shadow[burn_addr] <= burn_data;
                    prog_done[burn_addr]   <= 1'b1;
                    prog_cnt               <= prog_cnt + 32'd1;
                    fsm                    <= S_IDLE;
                end
                S_SENSE: begin
                    rd_data  <= fuse_shadow[burn_addr];
                    prog_cnt <= prog_cnt + 32'd1;
                    fsm      <= S_IDLE;
                end
                default: fsm <= S_IDLE;
            endcase
        end
    end

    assign o_rd_data = rd_data;
    assign o_locked  = !pre_lock;

    always @(posedge clk)
        assert (!pre_lock || prog_cnt <= 32'd8);
endmodule

module issie_dbi_lane (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        wr,
    input  wire [63:0] wdata,
    input  wire        q_start,
    input  wire        r_stop,
    output wire [63:0] rdata,
    output wire [63:0] beat_count
);
    reg [63:0] bus_q;
    reg [7:0]  dbi_q;
    reg [63:0] plain_q;
    reg [63:0] beat_cnt;
    reg        win;
    reg        pv;
    initial begin
        bus_q = 64'd0; dbi_q = 8'd0; plain_q = 64'd0;
        beat_cnt = 64'd0; win = 1'b0; pv = 1'b0;
    end

    function [3:0] pop8;
        input [7:0] b;
        integer k;
        begin
            pop8 = 4'd0;
            for (k = 0; k < 8; k = k + 1)
                pop8 = pop8 + {3'd0, b[k]};
        end
    endfunction

    wire [7:0]  f;
    wire [63:0] enc;
    wire [63:0] xdbi;

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : g_lane
            assign f[i] = ((4'd8 - pop8(wdata[8*i +: 8])) > 4'd4);
            assign enc[8*i +: 8]  = wdata[8*i +: 8] ^ {8{f[i]}};
            assign xdbi[8*i +: 8] = {8{dbi_q[i]}};
        end
    endgenerate

    assign rdata = bus_q ^ xdbi;
    assign beat_count = beat_cnt;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            bus_q <= 64'd0;
            dbi_q <= 8'd0;
            plain_q <= 64'd0;
            beat_cnt <= 64'd0;
            win <= 1'b0;
        end else if (en) begin
            if (wr) begin
                bus_q <= enc;
                dbi_q <= f;
                plain_q <= wdata;
                beat_cnt <= beat_cnt + 64'd1;
            end
            if (q_start)
                win <= 1'b1;
            else if (r_stop)
                win <= 1'b0;
        end
    end

    always @(posedge clk)
        if (pv && !rst && win && $past(win) && $stable(bus_q) && $stable(dbi_q))
            assert ($stable(plain_q));
endmodule

module zkr_seed_unit (
    input wire clk,
    input wire rst,
    input wire en,
    input wire raw,
    input wire q_open,
    input wire r_close,
    output wire [7:0] o_seed,
    output wire o_win
);
    reg half = 1'b0;
    reg first_bit = 1'b0;
    reg out_valid = 1'b0;
    reg out_bit = 1'b0;
    reg [7:0] pair_cnt = 8'd0;
    reg [7:0] emit_cnt = 8'd0;
    reg [63:0] pool = 64'd0;
    reg [5:0] wr_ptr = 6'd0;
    reg win = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            half <= 1'b0;
            first_bit <= 1'b0;
            out_valid <= 1'b0;
            out_bit <= 1'b0;
            pair_cnt <= 8'd0;
            emit_cnt <= 8'd0;
            pool <= 64'd0;
            wr_ptr <= 6'd0;
            win <= 1'b0;
        end else if (en) begin
            if (!half) begin
                first_bit <= raw;
                half <= 1'b1;
                pair_cnt <= pair_cnt + 8'd1;
                if (out_valid) begin
                    pool[wr_ptr] <= out_bit;
                    wr_ptr <= wr_ptr + 6'd1;
                    out_valid <= 1'b0;
                end
            end else begin
                half <= 1'b0;
                if (raw != first_bit) begin
                    out_bit <= first_bit;
                    out_valid <= 1'b1;
                end
            end
            if (out_valid)
                emit_cnt <= emit_cnt + 8'd1;
            if (q_open)
                win <= 1'b1;
            else if (r_close)
                win <= 1'b0;
        end
    end

    assign o_seed = pool[7:0];
    assign o_win = win;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $stable(pair_cnt))
            assert ($stable(emit_cnt));
endmodule

module lane_deskew4 (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [255:0] din,
    input  wire [3:0]   mk,
    output wire [255:0] dout,
    output wire         aligned_o,
    output wire         timeout_o
);
    reg [63:0] fifo [0:31];
    reg [11:0] wptr;
    reg [11:0] rptr;
    reg [3:0]  seen;
    reg        aligned;
    reg        win;
    reg [63:0] cd;
    reg        timeout;

    integer k;
    initial begin
        for (k = 0; k < 32; k = k + 1) fifo[k] = 64'd0;
        wptr = 12'd0; rptr = 12'd0; seen = 4'd0;
        aligned = 1'b0; win = 1'b0; cd = 64'd0; timeout = 1'b0;
    end

    wire       q        = !win && !aligned && (|mk);
    wire       force_mk = win && !aligned && (cd == 64'd1);
    wire [3:0] seen_n   = force_mk ? 4'hF : (seen | mk);

    integer i;
    always @(posedge clk) begin
        if (!rst_n) begin
            wptr <= 12'd0; rptr <= 12'd0; seen <= 4'd0;
            aligned <= 1'b0; win <= 1'b0; cd <= 64'd0; timeout <= 1'b0;
        end else if (en) begin
            for (i = 0; i < 4; i = i + 1) begin
                fifo[i*8 + wptr[i*3 +: 3]] <= din[i*64 +: 64];
                wptr[i*3 +: 3] <= wptr[i*3 +: 3] + 3'd1;
                if (aligned) rptr[i*3 +: 3] <= rptr[i*3 +: 3] + 3'd1;
            end
            seen    <= seen_n;
            timeout <= timeout | (win && !aligned && (cd == 64'd0));
            if (seen_n == 4'hF) begin
                aligned <= 1'b1;
                win     <= 1'b0;
                cd      <= 64'd0;
            end else if (q) begin
                win <= 1'b1;
                cd  <= 64'd8;
            end else if (win && !aligned) begin
                cd <= cd - 64'd1;
            end
        end
    end

    genvar g;
    generate
        for (g = 0; g < 4; g = g + 1) begin : g_out
            assign dout[g*64 +: 64] = fifo[g*8 + rptr[g*3 +: 3]];
        end
    endgenerate

    assign aligned_o = aligned;
    assign timeout_o = timeout;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && rst_n && win && !aligned && $stable(aligned))
            assert ($stable(timeout));
endmodule

module tia_pll_seq (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire band_ok,
    input wire lock_in,
    output wire pll_pwr,
    output wire cal_active,
    output wire loop_closed,
    output wire clk_release,
    output reg [3:0] band
);
    localparam [2:0] S_OFF      = 3'd0;
    localparam [2:0] S_PWRUP    = 3'd1;
    localparam [2:0] S_BANDCAL  = 3'd2;
    localparam [2:0] S_CLOSE    = 3'd3;
    localparam [2:0] S_LOCKWAIT = 3'd4;
    localparam [2:0] S_RUN      = 3'd5;

    reg [2:0]  state;
    reg [15:0] cnt;

    initial state = S_OFF;
    initial cnt   = 16'd0;
    initial band  = 4'd0;

    assign pll_pwr     = (state != S_OFF);
    assign cal_active  = (state == S_BANDCAL);
    assign loop_closed = (state == S_CLOSE) || (state == S_LOCKWAIT) || (state == S_RUN);
    assign clk_release = (state == S_RUN);

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= S_OFF;
            cnt   <= 16'd0;
            band  <= 4'd0;
        end else if (en) begin
            case (state)
                S_OFF: begin
                    state <= S_PWRUP;
                    cnt   <= 16'd0;
                end
                S_PWRUP: begin
                    if (cnt >= 16'd511) begin
                        state <= S_BANDCAL;
                        cnt   <= 16'd0;
                    end else begin
                        cnt <= cnt + 16'd1;
                    end
                end
                S_BANDCAL: begin
                    cnt <= 16'd0;
                    if (band_ok) begin
                        state <= S_CLOSE;
                    end else begin
                        band <= band + 4'd1;
                    end
                end
                S_CLOSE: begin
                    cnt <= cnt + 16'd1;
                    if (cnt >= 16'd200)
                        state <= S_LOCKWAIT;
                end
                S_LOCKWAIT: begin
                    if (!lock_in) begin
                        state <= S_BANDCAL;
                        cnt   <= 16'd0;
                    end else if (cnt >= 16'd1200) begin
                        state <= S_RUN;
                        cnt   <= 16'd0;
                    end else begin
                        cnt <= cnt + 16'd1;
                    end
                end
                S_RUN: begin
                    cnt <= 16'd0;
                    if (!lock_in)
                        state <= S_BANDCAL;
                end
                default: begin
                    state <= S_OFF;
                    cnt   <= 16'd0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (state == 3'd4) assert (cnt <= 16'd1200);
endmodule

module pico_wakeup (
    input wire        clk,
    input wire        rst_n,
    input wire        en,
    input wire        alloc,
    input wire [31:0] alloc_deps,
    input wire        issue,
    input wire [4:0]  issue_idx
);
    reg [31:0]   valid    = 32'd0;
    reg [1023:0] dep_flat = 1024'd0;
    reg [31:0]   pend     = 32'd0;
    reg [63:0]   occ      = 64'd0;
    reg [63:0]   wake_cnt = 64'd0;

    initial valid    = 32'd0;
    initial dep_flat = 1024'd0;
    initial pend     = 32'd0;
    initial occ      = 64'd0;
    initial wake_cnt = 64'd0;

    wire full = &valid;

    // lowest free index
    reg [4:0] free_idx;
    integer a;
    always @(*) begin
        free_idx = 5'd0;
        for (a = 31; a >= 0; a = a - 1)
            if (!valid[a]) free_idx = a[4:0];
    end

    // popcount of valid (status helper)
    reg [63:0] valid_cnt;
    integer b;
    always @(*) begin
        valid_cnt = 64'd0;
        for (b = 0; b < 32; b = b + 1)
            valid_cnt = valid_cnt + {63'd0, valid[b]};
    end

    // per-row OR of dependency matrix (status helper)
    reg [31:0] dep_or;
    integer c;
    always @(*) begin
        for (c = 0; c < 32; c = c + 1)
            dep_or[c] = |dep_flat[c*32 +: 32];
    end

    wire alloc_fire = alloc && !full;
    wire issue_fire = issue && valid[issue_idx] && !pend[issue_idx];
    wire [31:0] clr_mask   = issue_fire ? (32'd1 << issue_idx) : 32'd0;
    wire [31:0] alloc_mask = alloc_fire ? (32'd1 << free_idx)  : 32'd0;
    wire [31:0] new_deps   = alloc_deps & valid & ~clr_mask;

    reg [1023:0] dep_nxt;
    reg [31:0]   pend_nxt;
    reg [63:0]   woke;
    integer k;
    always @(*) begin
        woke = 64'd0;
        dep_nxt = dep_flat;
        pend_nxt = pend;
        for (k = 0; k < 32; k = k + 1) begin
            if (alloc_mask[k]) begin
                dep_nxt[k*32 +: 32] = new_deps;
                pend_nxt[k] = |new_deps;
            end else if (clr_mask[k]) begin
                dep_nxt[k*32 +: 32] = 32'd0;
                pend_nxt[k] = 1'b0;
            end else begin
                dep_nxt[k*32 +: 32] = dep_flat[k*32 +: 32] & ~clr_mask;
                pend_nxt[k] = pend[k] && (|(dep_flat[k*32 +: 32] & ~clr_mask));
                if (pend[k] && !pend_nxt[k])
                    woke = woke + 64'd1;
            end
        end
    end

    wire [31:0] valid_nxt = (valid | alloc_mask) & ~clr_mask;

    always @(posedge clk) begin
        if (!rst_n) begin
            valid    <= 32'd0;
            dep_flat <= 1024'd0;
            pend     <= 32'd0;
            occ      <= 64'd0;
            wake_cnt <= 64'd0;
        end else if (en) begin
            valid    <= valid_nxt;
            dep_flat <= dep_nxt;
            pend     <= pend_nxt;
            wake_cnt <= wake_cnt + woke;
            if (alloc_fire && !issue_fire)
                occ <= occ + 64'd1;
            else if (issue_fire && !alloc_fire)
                occ <= occ - 64'd1;
        end
    end

    always @(posedge clk)
        if (|valid) assert (occ <= 64'd32);
endmodule

module arrow_bound_cmp (
    input wire clk,
    input wire rst,
    input wire en,
    input wire load,
    input wire mode_in,
    input wire [7:0] cnt_in,
    input wire [7:0] len_in,
    output wire o_lt,
    output wire o_eq,
    output wire o_gt
);
    reg mode_r;
    reg [7:0] cnt_r;
    reg [7:0] len_r;
    reg lt_r, eq_r, gt_r;
    reg gt_q;
    initial mode_r = 1'b0;
    initial cnt_r = 8'd0;
    initial len_r = 8'd0;
    initial lt_r = 1'b0;
    initial eq_r = 1'b1;
    initial gt_r = 1'b0;
    initial gt_q = 1'b0;

    wire in_lt = mode_in ? ($signed(cnt_in) < $signed(len_in)) : (cnt_in < len_in);
    wire in_eq = (cnt_in == len_in);
    wire in_gt = !in_lt && !in_eq;

    wire cur_lt = mode_r ? ($signed(cnt_r) < $signed(len_r)) : (cnt_r < len_r);
    wire cur_eq = (cnt_r == len_r);

    wire [7:0] cnt_nx = cnt_r + 8'd1;

    always @(posedge clk) begin
        if (rst) begin
            mode_r <= 1'b0;
            cnt_r <= 8'd0;
            len_r <= 8'd0;
            lt_r <= 1'b0;
            eq_r <= 1'b1;
            gt_r <= 1'b0;
            gt_q <= 1'b0;
        end else if (en) begin
            gt_q <= gt_r;
            if (load) begin
                cnt_r <= cnt_in;
                len_r <= len_in;
                mode_r <= mode_in;
                lt_r <= in_lt;
                eq_r <= in_eq;
                gt_r <= in_gt;
            end else if (eq_r) begin
                eq_r <= 1'b0;
                gt_r <= 1'b1;
            end else if (lt_r) begin
                cnt_r <= cnt_nx;
                if (cnt_nx == len_r) begin
                    lt_r <= 1'b0;
                    eq_r <= 1'b1;
                end
            end
        end
    end

    assign o_lt = lt_r;
    assign o_eq = eq_r;
    assign o_gt = gt_r;

    always @(posedge clk)
        if (gt_r && !gt_q)
            assert (!lt_r && !eq_r);
endmodule

module rvx_dma2d (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        start,
    input  wire [63:0] cfg_row_len,
    input  wire [63:0] cfg_row_cnt,
    input  wire [63:0] cfg_src_base,
    input  wire [63:0] cfg_dst_base,
    input  wire [63:0] cfg_src_stride,
    input  wire [63:0] cfg_dst_stride,
    input  wire [63:0] rd_data,
    input  wire        dst_ready,
    output wire [63:0] rd_addr,
    output wire        rd_req,
    output wire [63:0] wr_addr,
    output wire [63:0] wr_data,
    output wire        wr_valid,
    output wire        busy
);
    reg [63:0] row_len, row_cnt, src_stride, dst_stride;
    reg [63:0] rcol, rrow, src_addr;
    reg [63:0] wcol, wrow, dst_addr;
    reg        active;
    reg [63:0] fifo_mem [0:7];
    reg [2:0]  wr_ptr, rd_ptr;
    reg        wr_lap, rd_lap;
    reg [3:0]  fifo_count;
    reg        pre_done;
    integer i;

    initial begin
        row_len = 64'd0; row_cnt = 64'd0; src_stride = 64'd0; dst_stride = 64'd0;
        rcol = 64'd0; rrow = 64'd0; src_addr = 64'd0;
        wcol = 64'd0; wrow = 64'd0; dst_addr = 64'd0;
        active = 1'b0;
        wr_ptr = 3'd0; rd_ptr = 3'd0; wr_lap = 1'b0; rd_lap = 1'b0;
        fifo_count = 4'd0;
        pre_done = 1'b1;
        for (i = 0; i < 8; i = i + 1) fifo_mem[i] = 64'd0;
    end

    wire fifo_full  = (fifo_count == 4'd8);
    wire fifo_empty = (wr_ptr == rd_ptr) && (wr_lap == rd_lap);

    wire rows_left = (rrow < row_cnt);
    wire do_push   = active && rows_left && (fifo_count < 4'd8);
    wire do_pop    = !fifo_empty && dst_ready;
    wire rd_row_end = (rcol == row_len - 64'd1);
    wire wr_row_end = (wcol == row_len - 64'd1);
    wire last_pop  = do_pop && wr_row_end && (wrow == row_cnt - 64'd1);

    assign rd_addr  = src_addr;
    assign rd_req   = do_push;
    assign wr_addr  = dst_addr;
    assign wr_data  = fifo_mem[rd_ptr];
    assign wr_valid = !fifo_empty;
    assign busy     = active;

    always @(posedge clk) begin
        if (rst) begin
            active <= 1'b0;
            rcol <= 64'd0; rrow <= 64'd0; src_addr <= 64'd0;
            wcol <= 64'd0; wrow <= 64'd0; dst_addr <= 64'd0;
            wr_ptr <= 3'd0; rd_ptr <= 3'd0; wr_lap <= 1'b0; rd_lap <= 1'b0;
            fifo_count <= 4'd0;
            pre_done <= 1'b1;
        end else if (en) begin
            if (do_push) begin
                fifo_mem[wr_ptr] <= rd_data;
                {wr_lap, wr_ptr} <= {wr_lap, wr_ptr} + 4'd1;
                if (rd_row_end) begin
                    rcol     <= 64'd0;
                    rrow     <= rrow + 64'd1;
                    src_addr <= src_addr + 64'd8 + src_stride;
                end else begin
                    rcol     <= rcol + 64'd1;
                    src_addr <= src_addr + 64'd8;
                end
            end
            if (do_pop) begin
                {rd_lap, rd_ptr} <= {rd_lap, rd_ptr} + 4'd1;
                if (wr_row_end) begin
                    wcol     <= 64'd0;
                    wrow     <= wrow + 64'd1;
                    dst_addr <= dst_addr + 64'd8 + dst_stride;
                end else begin
                    wcol     <= wcol + 64'd1;
                    dst_addr <= dst_addr + 64'd8;
                end
            end
            case ({do_push, do_pop})
                2'b10:   fifo_count <= fifo_count + 4'd1;
                2'b01:   fifo_count <= fifo_count - 4'd1;
                default: fifo_count <= fifo_count;
            endcase
            if (last_pop) begin
                active   <= 1'b0;
                pre_done <= 1'b0;
            end
            if (start && !active) begin
                row_len    <= cfg_row_len;
                row_cnt    <= cfg_row_cnt;
                src_stride <= cfg_src_stride;
                dst_stride <= cfg_dst_stride;
                src_addr   <= cfg_src_base;
                dst_addr   <= cfg_dst_base;
                rcol <= 64'd0; rrow <= 64'd0;
                wcol <= 64'd0; wrow <= 64'd0;
                active <= 1'b1;
            end
        end
    end

    always @(*) assert (!pre_done || !(fifo_full && fifo_empty));
endmodule

module ras_walker (
    input wire clk,
    input wire rst,
    input wire en,
    input wire call,
    input wire ret,
    input wire [63:0] call_addr,
    output reg [63:0] ret_addr,
    output reg ret_valid
);
    reg [63:0] ras0, ras1;
    reg [1:0]  tos;
    reg        pend;
    reg [63:0] stg;
    reg [63:0] cnt;
    reg        win;
    reg        pv;

    initial ras0 = 64'd0;
    initial ras1 = 64'd0;
    initial tos = 2'd0;
    initial pend = 1'b0;
    initial stg = 64'd0;
    initial cnt = 64'd0;
    initial win = 1'b0;
    initial ret_addr = 64'd0;
    initial ret_valid = 1'b0;
    initial pv = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            ras0 <= 64'd0;
            ras1 <= 64'd0;
            tos <= 2'd0;
            pend <= 1'b0;
            stg <= 64'd0;
            cnt <= 64'd0;
            win <= 1'b0;
            ret_addr <= 64'd0;
            ret_valid <= 1'b0;
        end else if (en) begin
            ret_valid <= 1'b0;
            if (pend) begin
                if (stg == 64'd3) begin
                    ret_addr <= tos[0] ? ras1 : ras0;
                    ret_valid <= 1'b1;
                    pend <= 1'b0;
                    win <= 1'b0;
                    stg <= 64'd0;
                end else begin
                    stg <= stg + 64'd1;
                    cnt <= cnt - 64'd1;
                end
            end else if (ret && tos != 2'd0) begin
                tos <= tos - 2'd1;
                pend <= 1'b1;
                stg <= 64'd0;
                cnt <= 64'd4;
                win <= 1'b1;
            end else if (call && tos < 2'd2) begin
                if (tos == 2'd0) ras0 <= call_addr;
                else ras1 <= call_addr;
                tos <= tos + 2'd1;
            end
        end
    end

    always @(posedge clk)
        if (pv && $past(en) && $past(win) && $past(pend))
            assert ($past(cnt) != 64'd0);
endmodule

module vcd_tstamp (
    input wire clk,
    input wire rst,
    input wire en,
    input wire snap_req,
    input wire rd_hi,
    output wire [31:0] rdata
);
    reg [31:0] cnt_lo, cnt_hi, snap_lo, snap_hi;
    reg        busy;
    reg [3:0]  cd;
    reg        win;
    reg        latched;

    initial begin
        cnt_lo = 32'd0; cnt_hi = 32'd0;
        snap_lo = 32'd0; snap_hi = 32'd0;
        busy = 1'b0; cd = 4'd0; win = 1'b0; latched = 1'b0;
    end

    wire accept = snap_req && (cd == 4'd0);

    assign rdata = rd_hi ? snap_hi : snap_lo;

    always @(posedge clk) begin
        if (rst) begin
            cnt_lo <= 32'd0; cnt_hi <= 32'd0;
            snap_lo <= 32'd0; snap_hi <= 32'd0;
            busy <= 1'b0; cd <= 4'd0; win <= 1'b0; latched <= 1'b0;
        end else if (en) begin
            cnt_lo <= cnt_lo + 32'd1;
            if (cnt_lo == 32'hFFFFFFFF)
                cnt_hi <= cnt_hi + 32'd1;

            if (accept) begin
                busy    <= 1'b1;
                cd      <= 4'd8;
                latched <= 1'b0;
            end else begin
                if (cd != 4'd0)
                    cd <= cd - 4'd1;
                if (busy && cd == 4'd5) begin
                    snap_lo <= cnt_lo;
                    snap_hi <= cnt_hi;
                    latched <= 1'b1;
                end
                if (busy && cd == 4'd1 && latched) begin
                    busy    <= 1'b0;
                    latched <= 1'b0;
                end
            end

            if (accept)
                win <= 1'b1;
            else if (rd_hi)
                win <= 1'b0;
        end
    end

    always @(posedge clk)
        if (win && busy)
            assert (cd != 4'd0);

    always @(posedge clk)
        if (win && busy)
            assert (cd <= 4'd8);
endmodule

module awesome_frame_sync (
    input wire clk,
    input wire rst,
    input wire en,
    input wire hdr_ok,
    input wire win_clr,
    output reg [1:0] state
);
    localparam [1:0] HUNT = 2'd0, PRESYNC = 2'd1, SYNC = 2'd2;
    reg [31:0] good_cnt;
    reg [31:0] bad_cnt;
    reg [3:0]  bad_hist;
    reg        win;
    initial begin
        state = HUNT; good_cnt = 32'd0; bad_cnt = 32'd0; bad_hist = 4'd0; win = 1'b0;
    end

    wire q_evt = en && (state == PRESYNC) && hdr_ok && (good_cnt == 32'd2);

    always @(posedge clk) begin
        if (rst) begin
            state <= HUNT; good_cnt <= 32'd0; bad_cnt <= 32'd0; bad_hist <= 4'd0; win <= 1'b0;
        end else if (en) begin
            if (win_clr) win <= 1'b0;
            else if (q_evt) win <= 1'b1;
            case (state)
                HUNT: begin
                    if (hdr_ok) begin
                        state <= PRESYNC;
                        good_cnt <= 32'd1;
                    end
                end
                PRESYNC: begin
                    if (hdr_ok) begin
                        if (good_cnt == 32'd2) begin
                            state <= SYNC;
                            good_cnt <= 32'd0;
                            bad_cnt <= 32'd0;
                            bad_hist <= 4'd0;
                        end else begin
                            good_cnt <= good_cnt + 32'd1;
                        end
                    end else begin
                        state <= HUNT;
                        good_cnt <= 32'd0;
                        bad_cnt <= 32'd0;
                        bad_hist <= 4'd0;
                    end
                end
                SYNC: begin
                    if (hdr_ok) begin
                        bad_cnt <= 32'd0;
                        bad_hist <= {bad_hist[2:0], 1'b0};
                    end else if (bad_hist[2:0] == 3'b111) begin
                        state <= HUNT;
                        bad_cnt <= 32'd0;
                        bad_hist <= 4'd0;
                    end else begin
                        bad_cnt <= bad_cnt + 32'd1;
                        bad_hist <= {bad_hist[2:0], 1'b1};
                    end
                end
                default: begin
                    state <= HUNT;
                    good_cnt <= 32'd0;
                    bad_cnt <= 32'd0;
                    bad_hist <= 4'd0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (win && state == 2'd2)
            assert (bad_cnt <= 32'd3);
endmodule

module farrow_apb_bridge (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire hwr,
    input wire [31:0] hwdata,
    input wire hmu_wr,
    input wire [31:0] hmu,
    input wire pread,
    output wire [31:0] prdata
);
    reg [31:0] x0, x1, x2, x3;
    reg [31:0] c0, c1, c2, c3;
    reg [31:0] mu;
    reg [31:0] fill_cnt;
    reg out_valid;
    reg [31:0] y;
    reg hist_wr;

    initial begin
        x0 = 32'd0; x1 = 32'd0; x2 = 32'd0; x3 = 32'd0;
        c0 = 32'd0; c1 = 32'd0; c2 = 32'd0; c3 = 32'd0;
        mu = 32'd0; fill_cnt = 32'd0; out_valid = 1'b0;
        y = 32'd0; hist_wr = 1'b0;
    end

    // cubic Lagrange sub-filter taps (truncated arithmetic)
    wire [31:0] d02  = x0 - x2;
    wire [31:0] t1   = $signed(d02) >>> 1;
    wire [31:0] x1m5 = x1 * 32'd5;
    wire [31:0] t2   = x2 - ($signed(x1m5) >>> 1) + (x0 << 1);
    wire [31:0] s3   = (x3 - x0) + ((x1 - x2) * 32'd3);
    wire [31:0] t3   = $signed(s3) >>> 1;

    // Horner evaluation in Q0.32 mu
    wire [63:0] p3 = {32'd0, c3} * {32'd0, mu};
    wire [31:0] h3 = p3[63:32] + c2;
    wire [63:0] p2 = {32'd0, h3} * {32'd0, mu};
    wire [31:0] h2 = p2[63:32] + c1;
    wire [63:0] p1 = {32'd0, h2} * {32'd0, mu};
    wire [31:0] y_next = p1[63:32] + c0;

    wire rd_done = pread && (fill_cnt == 32'd4);

    always @(posedge clk) begin
        if (!rst_n) begin
            x0 <= 32'd0; x1 <= 32'd0; x2 <= 32'd0; x3 <= 32'd0;
            c0 <= 32'd0; c1 <= 32'd0; c2 <= 32'd0; c3 <= 32'd0;
            mu <= 32'd0; fill_cnt <= 32'd0; out_valid <= 1'b0;
            y <= 32'd0; hist_wr <= 1'b0;
        end else if (en) begin
            if (hwr) begin
                x3 <= x2;
                x2 <= x1;
                x1 <= x0;
                x0 <= hwdata;
                fill_cnt <= (fill_cnt >= 32'd4) ? 32'd4 : fill_cnt + 32'd1;
                hist_wr <= 1'b1;
            end
            c0 <= x1;
            c1 <= t1;
            c2 <= t2;
            c3 <= t3;
            if (hmu_wr)
                mu <= hmu;
            out_valid <= rd_done;
            if (rd_done)
                y <= y_next;
        end
    end

    assign prdata = y;

    always @(posedge clk)
        if (out_valid)
            assert (hist_wr);
endmodule

module bayer_tile_demosaic (
    input wire clk,
    input wire rst,
    input wire en,
    input wire start,
    input wire [63:0] pix_in,
    output reg [63:0] rgb_r,
    output reg [63:0] rgb_g,
    output reg [63:0] rgb_b,
    output reg done
);
    reg [63:0] tile [0:15];
    reg [63:0] idx;
    reg [63:0] cd;
    reg busy;
    reg [1:0] phase;
    reg win;
    reg pv;
    integer k;

    initial begin
        for (k = 0; k < 16; k = k + 1) tile[k] = 64'd0;
        idx = 64'd0;
        cd = 64'd0;
        busy = 1'b0;
        phase = 2'b00;
        win = 1'b0;
        pv = 1'b0;
        rgb_r = 64'd0;
        rgb_g = 64'd0;
        rgb_b = 64'd0;
        done = 1'b0;
    end

    wire [3:0] i0 = idx[3:0];
    wire [3:0] im = i0 - 4'd1;
    wire [3:0] ip = i0 + 4'd1;
    wire [63:0] c_px = tile[i0];
    wire [63:0] l_px = tile[im];
    wire [63:0] r_px = tile[ip];
    wire [63:0] avg = (l_px >> 1) + (r_px >> 1);
    wire [63:0] diag = (l_px >> 2) + (r_px >> 2) + (c_px >> 1);

    reg [63:0] nr, ng, nb;
    always @(*) begin
        case (phase)
            2'b00: begin nr = c_px; ng = avg;  nb = diag; end
            2'b01: begin nr = avg;  ng = c_px; nb = diag; end
            2'b10: begin nr = diag; ng = c_px; nb = avg;  end
            default: begin nr = diag; ng = avg; nb = c_px; end
        endcase
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            for (k = 0; k < 16; k = k + 1) tile[k] <= 64'd0;
            idx <= 64'd0;
            cd <= 64'd0;
            busy <= 1'b0;
            phase <= 2'b00;
            win <= 1'b0;
            rgb_r <= 64'd0;
            rgb_g <= 64'd0;
            rgb_b <= 64'd0;
            done <= 1'b0;
        end else if (en) begin
            if (start && !busy) begin
                busy <= 1'b1;
                win <= 1'b1;
                idx <= 64'd0;
                cd <= 64'd16;
                phase <= 2'b00;
                done <= 1'b0;
            end else if (busy) begin
                tile[i0] <= pix_in;
                rgb_r <= nr;
                rgb_g <= ng;
                rgb_b <= nb;
                idx <= idx + 64'd1;
                cd <= cd - 64'd1;
                phase[0] <= ~phase[0];
                if (i0[1:0] == 2'b11) phase[1] <= ~phase[1];
                if (idx == 64'd15) begin
                    busy <= 1'b0;
                    win <= 1'b0;
                    done <= 1'b1;
                end else begin
                    done <= 1'b0;
                end
            end else begin
                done <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (pv && $past(win) && $past(busy))
            assert ($past(cd) != 64'd0);
endmodule

module round_disp (
    input wire clk,
    input wire rst,
    input wire en,
    input wire load,
    input wire [34:0] din,
    input wire [1:0] mode_in,
    output reg [6:0] seg
);
    reg [31:0] trunc = 32'd0;
    reg [2:0]  grs = 3'b000;
    reg [1:0]  mode = 2'd0;
    reg [31:0] rounded = 32'd0;
    reg        armed = 1'b0;
    reg        pv = 1'b0;

    function inc_f;
        input [1:0] m;
        input [2:0] g;
        input lsb;
        begin
            case (m)
                2'd0: inc_f = g[2] & (g[1] | g[0] | lsb);
                2'd1: inc_f = 1'b0;
                2'd2: inc_f = g[2] | g[1] | g[0];
                default: inc_f = g[2];
            endcase
        end
    endfunction

    wire ld_inc = inc_f(mode_in, din[2:0], din[3]);
    wire rf_inc = inc_f(mode, grs, trunc[0]);

    always @(posedge clk) begin
        if (rst) begin
            trunc   <= 32'd0;
            grs     <= 3'b000;
            mode    <= 2'd0;
            rounded <= 32'd0;
            armed   <= 1'b0;
        end else if (en) begin
            if (load) begin
                trunc   <= din[34:3];
                grs     <= din[2:0];
                mode    <= mode_in;
                rounded <= din[34:3] + {31'd0, ld_inc};
                armed   <= 1'b1;
            end else begin
                rounded <= trunc + {31'd0, rf_inc};
            end
        end
    end

    always @(*) begin
        case (rounded[3:0])
            4'h0: seg = 7'b1111110;
            4'h1: seg = 7'b0110000;
            4'h2: seg = 7'b1101101;
            4'h3: seg = 7'b1111001;
            4'h4: seg = 7'b0110011;
            4'h5: seg = 7'b1011011;
            4'h6: seg = 7'b1011111;
            4'h7: seg = 7'b1110000;
            4'h8: seg = 7'b1111111;
            4'h9: seg = 7'b1111011;
            4'hA: seg = 7'b1110111;
            4'hB: seg = 7'b0011111;
            4'hC: seg = 7'b1001110;
            4'hD: seg = 7'b0111101;
            4'hE: seg = 7'b1001111;
            default: seg = 7'b1000111;
        endcase
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && !$past(rst) && armed && $stable(trunc) && $stable(grs) && $stable(mode))
            assert ($stable(rounded));
endmodule

module sd_host_blk (
    input wire clk,
    input wire rst,
    input wire en,
    input wire cmd_start,
    input wire [63:0] cmd_arg,
    input wire resp_valid,
    input wire [63:0] resp_in,
    input wire data_valid,
    input wire [63:0] data_in,
    input wire [1:0] rd_idx,
    output wire o_busy,
    output wire [63:0] o_resp,
    output wire [63:0] o_arg,
    output wire [63:0] o_data,
    output wire [63:0] o_words_done
);
    localparam [63:0] BLK_WORDS = 64'd8;

    reg [63:0] arg_reg;
    reg [63:0] resp_reg;
    reg        busy;
    reg [63:0] words_done;
    reg [63:0] words_left;
    reg [63:0] fifo [0:3];
    reg        armed;
    reg        pv;

    initial begin
        arg_reg = 64'd0;
        resp_reg = 64'd0;
        busy = 1'b0;
        words_done = 64'd0;
        words_left = BLK_WORDS;
        fifo[0] = 64'd0;
        fifo[1] = 64'd0;
        fifo[2] = 64'd0;
        fifo[3] = 64'd0;
        armed = 1'b0;
        pv = 1'b0;
    end

    always @(posedge clk) begin
        if (en) begin
            pv <= 1'b1;
            if (rst) begin
                words_done <= 64'd0;
                words_left <= BLK_WORDS;
                busy <= 1'b0;
                armed <= 1'b0;
            end else begin
                if (resp_valid) begin
                    resp_reg <= resp_in;
                    armed <= 1'b1;
                end
                if (cmd_start && !busy) begin
                    arg_reg <= cmd_arg;
                    words_done <= 64'd0;
                    words_left <= BLK_WORDS;
                    busy <= 1'b1;
                end else if (busy) begin
                    if (data_valid && words_left != 64'd0) begin
                        fifo[words_done[1:0]] <= data_in;
                        words_done <= words_done + 64'd1;
                        words_left <= words_left - 64'd1;
                    end
                    if (words_left == 64'd0)
                        busy <= 1'b0;
                end
            end
        end
    end

    assign o_busy = busy;
    assign o_resp = resp_reg;
    assign o_arg = arg_reg;
    assign o_data = fifo[rd_idx];
    assign o_words_done = words_done;

    always @(posedge clk)
        if (pv && $past(armed))
            assert ($past(words_done) <= 64'd8);
endmodule

module udp_hamming_tx (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         req,
    input  wire [127:0] data_i,
    input  wire         link_down,
    output wire [136:0] code_o,
    output wire         valid_o
);
    reg [127:0] data_q;
    reg [8:0]   chk_q;
    reg [1:0]   step;
    reg [2:0]   cd;
    reg         busy;
    reg [136:0] code_q;
    reg         valid_q;
    reg         pre_r;

    initial begin
        data_q  = 128'd0;
        chk_q   = 9'd0;
        step    = 2'd0;
        cd      = 3'd0;
        busy    = 1'b0;
        code_q  = 137'd0;
        valid_q = 1'b0;
        pre_r   = 1'b1;
    end

    assign code_o  = code_q;
    assign valid_o = valid_q;

    // current 32-bit beat
    wire [31:0] beat = data_q[{step, 5'b00000} +: 32];

    // Hamming contribution of this beat: data bit idx sits at position 129+idx
    reg [8:0] beat_chk;
    reg [5:0] j;
    always @(*) begin
        beat_chk = 9'd0;
        for (j = 6'd0; j < 6'd32; j = j + 6'd1) begin
            if (beat[j[4:0]]) begin
                beat_chk[7:0] = beat_chk[7:0] ^ (8'd129 + {1'b0, step, j[4:0]});
                beat_chk[8]   = ~beat_chk[8];
            end
        end
    end

    wire [8:0] chk_next  = chk_q ^ beat_chk;
    wire       par_final = chk_next[8] ^ (^chk_next[7:0]);

    always @(posedge clk) begin
        if (!rst_n) begin
            data_q  <= 128'd0;
            chk_q   <= 9'd0;
            step    <= 2'd0;
            cd      <= 3'd0;
            busy    <= 1'b0;
            code_q  <= 137'd0;
            valid_q <= 1'b0;
        end else if (en) begin
            if (busy) begin
                chk_q <= chk_next;
                step  <= step + 2'd1;
                cd    <= cd - 3'd1;
                if (step == 2'd3) begin
                    code_q  <= {par_final, chk_next[7:0], data_q};
                    valid_q <= 1'b1;
                    busy    <= 1'b0;
                end
            end else if (req) begin
                data_q  <= data_i;
                chk_q   <= 9'd0;
                step    <= 2'd0;
                cd      <= 3'd4;
                busy    <= 1'b1;
                valid_q <= 1'b0;
            end
        end
    end

    // scope register: ignores en
    always @(posedge clk) begin
        if (!rst_n)
            pre_r <= 1'b1;
        else if (link_down)
            pre_r <= 1'b0;
    end

    always @(posedge clk)
        if (pre_r) assert (!(busy && cd == 3'd0));
endmodule

module pin_bist (
    input wire clk,
    input wire rst,
    input wire en,
    input wire start,
    output wire busy,
    output reg fail
);
    localparam [127:0] PAT = "PIN_UART_A15____";

    reg [127:0] mem [0:15];
    reg [3:0] addr = 4'd0;
    reg [1:0] phase = 2'd0;
    reg [6:0] countdown = 7'd0;
    reg win = 1'b0;
    initial fail = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1)
            mem[i] = 128'd0;
    end

    assign busy = win;

    wire [5:0] pa = {phase, addr};
    wire [127:0] rd = mem[addr];
    wire [127:0] exp_rd = (phase == 2'd2) ? ~PAT : PAT;
    wire [127:0] wr = (phase == 2'd1) ? ~PAT : PAT;
    wire do_read = (phase != 2'd0);
    wire do_write = (phase != 2'd3);

    always @(posedge clk) begin
        if (!rst && en && win && do_write)
            mem[addr] <= wr;
    end

    always @(posedge clk) begin
        if (rst) begin
            win <= 1'b0;
            countdown <= 7'd0;
            addr <= 4'd0;
            phase <= 2'd0;
            fail <= 1'b0;
        end else if (en) begin
            if (!win) begin
                if (start) begin
                    win <= 1'b1;
                    countdown <= 7'd64;
                    addr <= 4'd0;
                    phase <= 2'd0;
                    fail <= 1'b0;
                end
            end else begin
                if (do_read && (rd != exp_rd))
                    fail <= 1'b1;
                {phase, addr} <= pa + 6'd1;
                if (pa == 6'd63) begin
                    win <= 1'b0;
                    countdown <= 7'd0;
                end else begin
                    countdown <= countdown - 7'd1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    wire cd_zero = (countdown == 7'd0);

    always @(posedge clk) begin
        if (pv && !rst && win && $stable(win))
            assert ($stable(cd_zero));
    end
endmodule

module axi_goertzel_bin (
    input wire clk,
    input wire rst,
    input wire en,
    input wire arm,
    input wire start,
    input wire b_ready,
    input wire clr,
    input wire [15:0] sample,
    input wire [15:0] coef_in,
    output reg done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUNNING = 2'd2, DONE = 2'd3;

    reg [1:0] phase = 2'd0;
    reg signed [15:0] s1 = 16'sd0;
    reg signed [15:0] s2 = 16'sd0;
    reg [15:0] cnt = 16'd0;
    reg [15:0] coef = 16'd0;
    reg armed_seen = 1'b0;
    reg started_seen = 1'b0;
    reg before_clr = 1'b1;
    initial done = 1'b0;

    wire signed [31:0] prod = $signed(coef) * s1;
    wire signed [31:0] fb = prod >>> 14;
    wire signed [15:0] s1_next = $signed(sample) + fb[15:0] - s2;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            s1 <= 16'sd0;
            s2 <= 16'sd0;
            cnt <= 16'd0;
            coef <= 16'd0;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            before_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            case (phase)
                IDLE: begin
                    if (arm) begin
                        phase <= ARMED;
                        coef <= coef_in;
                        armed_seen <= 1'b1;
                    end
                end
                ARMED: begin
                    if (start) begin
                        phase <= RUNNING;
                        started_seen <= 1'b1;
                        cnt <= 16'd0;
                        s1 <= 16'sd0;
                        s2 <= 16'sd0;
                    end
                end
                RUNNING: begin
                    s1 <= s1_next;
                    s2 <= s1;
                    if (cnt == 16'd23) begin
                        phase <= DONE;
                        done <= 1'b1;
                    end else begin
                        cnt <= cnt + 16'd1;
                    end
                end
                DONE: begin
                    if (b_ready) begin
                        phase <= IDLE;
                        done <= 1'b0;
                    end
                end
            endcase
            if (clr) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                before_clr <= 1'b0;
            end
        end
    end

    always @(*) assert (!before_clr || !done || (started_seen && armed_seen));
endmodule

module kaze_gust_meter (
    input wire clk,
    input wire rst,
    input wire en,
    input wire inc,
    input wire q_open,
    input wire r_close,
    output wire calm,
    output wire storm
);
    reg [63:0] b;
    reg [63:0] g;
    reg        win;
    initial b = 64'd0;
    initial g = 64'd0;
    initial win = 1'b0;

    wire [63:0] b_nxt = b + 64'd1;

    always @(posedge clk) begin
        if (rst) begin
            b   <= 64'd0;
            g   <= 64'd0;
            win <= 1'b0;
        end else if (en) begin
            if (inc) begin
                b <= b_nxt;
                g <= b_nxt ^ (b_nxt >> 1);
            end
            win <= q_open ? 1'b1 : (r_close ? 1'b0 : win);
        end
    end

    // stateless prefix-XOR Gray-to-binary network, MSB down
    wire [63:0] conv;
    assign conv[63] = g[63];
    genvar i;
    generate
        for (i = 62; i >= 0; i = i - 1) begin : g2b
            assign conv[i] = conv[i+1] ^ g[i];
        end
    endgenerate

    assign calm  = (b == 64'd0);
    assign storm = (conv == 64'hFFFF_FFFF_FFFF_FFFF);

    always @(posedge clk)
        if (win) assert (!((b == 64'd0) && (conv == 64'hFFFF_FFFF_FFFF_FFFF)));
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
    output reg          out_v
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                    cnt    <= cnt + 4'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
    wire match1 = beat_valid && (((beat_data ^ wval1) & wmask1) == 128'h0);

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
            S_ARMED: if (match0)  fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
                if (fsm == S_ARMED && match0) started_seen <= 1'b1;
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
endmodule

module camsi_line_energy_acc (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire sol,
    input wire [31:0] px,
    output wire [31:0] o_energy,
    output wire o_sat
);
    localparam [31:0] LIMIT = 32'h00FF_FFFF;

    reg [31:0] acc;
    reg [31:0] headroom;
    reg        sat_flag;
    initial acc = 32'd0;
    initial headroom = LIMIT;
    initial sat_flag = 1'b0;

    always @(posedge clk) begin
        if (!rst_n) begin
            acc      <= 32'd0;
            headroom <= LIMIT;
            sat_flag <= 1'b0;
        end else if (en) begin
            if (sol) begin
                acc      <= 32'd0;
                headroom <= LIMIT;
                sat_flag <= 1'b0;
            end else if (px > headroom) begin
                acc      <= LIMIT;
                headroom <= 32'd0;
                sat_flag <= 1'b1;
            end else begin
                acc      <= acc + px;
                headroom <= headroom - px;
            end
        end
    end

    assign o_energy = acc;
    assign o_sat = sat_flag;

    always @(posedge clk)
        if (!sat_flag) assert (acc <= LIMIT);
endmodule

module tpu_dct_xpose (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [15:0] sample_in,
    output wire [15:0] acc_out
);
    reg phase = 1'b0;
    reg [15:0] wr_cnt = 16'd0;
    reg [15:0] rd_cnt = 16'd0;
    reg [15:0] wr_seen = 16'd0;
    reg [15:0] acc = 16'd0;
    reg [15:0] coef_idx = 16'd0;
    reg [15:0] mem [0:23];
    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) mem[i] = 16'd0;
    end

    assign acc_out = acc;

    function [15:0] cosv;
        input [2:0] idx;
        begin
            case (idx)
                3'd0: cosv = 16'd23170;
                3'd1: cosv = 16'd32138;
                3'd2: cosv = 16'd30274;
                3'd3: cosv = 16'd27246;
                3'd4: cosv = 16'd23170;
                3'd5: cosv = 16'd18205;
                3'd6: cosv = 16'd12540;
                default: cosv = 16'd6393;
            endcase
        end
    endfunction

    wire [31:0] row_prod = sample_in * cosv(coef_idx[2:0]);
    wire [15:0] rd_word = (rd_cnt < 16'd24) ? mem[rd_cnt[4:0]] : 16'd0;
    wire [31:0] col_prod = rd_word * cosv(coef_idx[2:0]);

    always @(posedge clk) begin
        if (rst) begin
            phase <= 1'b0;
            wr_cnt <= 16'd0;
            rd_cnt <= 16'd0;
            wr_seen <= 16'd0;
            acc <= 16'd0;
            coef_idx <= 16'd0;
        end else if (en) begin
            if (!phase) begin
                if (wr_cnt == 16'd24) begin
                    phase <= 1'b1;
                    rd_cnt <= 16'd0;
                end else begin
                    if (wr_cnt < 16'd24) mem[wr_cnt[4:0]] <= row_prod[15:0];
                    wr_cnt <= wr_cnt + 16'd1;
                    wr_seen <= wr_cnt + 16'd1;
                    coef_idx <= coef_idx + 16'd1;
                end
            end else begin
                if (rd_cnt < 16'd24) begin
                    acc <= acc + col_prod[15:0];
                    rd_cnt <= rd_cnt + 16'd1;
                    coef_idx <= coef_idx + 16'd1;
                end else begin
                    phase <= 1'b0;
                    wr_cnt <= 16'd0;
                    wr_seen <= 16'd0;
                    rd_cnt <= 16'd0;
                    acc <= 16'd0;
                end
            end
        end
    end

    assert property (!phase || (rd_cnt <= wr_seen));
endmodule

module tta_loop_fu (
    input wire clk,
    input wire rst,
    input wire en,
    input wire load,
    input wire [31:0] bus,
    input wire tick,
    output reg [31:0] cnt,
    output reg [31:0] rem
);
    localparam [31:0] LIMIT = 32'd1000;

    initial cnt = 32'd0;
    initial rem = LIMIT;

    wire [31:0] v = (bus > LIMIT) ? LIMIT : bus;

    always @(posedge clk) begin
        if (en) begin
            if (rst) begin
                cnt <= 32'd0;
                rem <= LIMIT;
            end else if (load) begin
                cnt <= v;
                rem <= LIMIT - v;
            end else if (tick && rem != 32'd0) begin
                cnt <= cnt + 32'd1;
                rem <= rem - 32'd1;
            end
        end
    end

    always @(*) assert (cnt <= 32'd1000);
endmodule

module pmod_simd_div (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire       req,
    input  wire       req_mode,
    input  wire [7:0] dividend,
    input  wire [7:0] divisor,
    input  wire       cfg_wr,
    output reg        resp_valid,
    output wire [7:0] quotient,
    output wire [7:0] remainder,
    output wire       busy_o
);
    reg       busy = 1'b0;
    reg       mode = 1'b0;
    reg [7:0] prem = 8'd0;
    reg [7:0] dvs  = 8'd0;
    reg [7:0] quo  = 8'd0;
    reg [7:0] cnt  = 8'd0;
    reg [7:0] dl   = 8'd0;
    reg       pre  = 1'b1;
    initial resp_valid = 1'b0;

    assign quotient  = quo;
    assign remainder = prem;
    assign busy_o    = busy;

    wire [7:0] w_cur = mode     ? 8'd4 : 8'd8;
    wire [7:0] w_req = req_mode ? 8'd4 : 8'd8;
    wire       last  = (cnt == (w_cur - 8'd1));

    // 8-bit lane
    wire [8:0] r8  = {prem, quo[7]};
    wire       ge8 = (r8 >= {1'b0, dvs});
    wire [8:0] s8  = r8 - {1'b0, dvs};

    // two 4-bit lanes
    wire [4:0] rlo  = {prem[3:0], quo[3]};
    wire       gelo = (rlo >= {1'b0, dvs[3:0]});
    wire [4:0] slo  = rlo - {1'b0, dvs[3:0]};
    wire [4:0] rhi  = {prem[7:4], quo[7]};
    wire       gehi = (rhi >= {1'b0, dvs[7:4]});
    wire [4:0] shi  = rhi - {1'b0, dvs[7:4]};

    wire [7:0] prem_n = mode ? {(gehi ? shi[3:0] : rhi[3:0]), (gelo ? slo[3:0] : rlo[3:0])}
                             : (ge8 ? s8[7:0] : r8[7:0]);
    wire [7:0] quo_n  = mode ? {quo[6:4], gehi, quo[2:0], gelo}
                             : {quo[6:0], ge8};

    always @(posedge clk) begin
        if (en) begin
            if (rst) begin
                busy <= 1'b0;
                cnt  <= 8'd0;
                dl   <= 8'd0;
                mode <= 1'b0;
                pre  <= 1'b1;
                resp_valid <= 1'b0;
            end else begin
                resp_valid <= 1'b0;
                if (!busy) begin
                    if (cfg_wr)
                        pre <= 1'b0;
                    if (req) begin
                        prem <= 8'd0;
                        quo  <= dividend;
                        dvs  <= divisor;
                        mode <= req_mode;
                        cnt  <= 8'd0;
                        dl   <= w_req;
                        busy <= 1'b1;
                    end
                end else begin
                    prem <= prem_n;
                    quo  <= quo_n;
                    cnt  <= cnt + 8'd1;
                    dl   <= dl - 8'd1;
                    if (last) begin
                        busy <= 1'b0;
                        resp_valid <= 1'b1;
                    end
                end
            end
        end
    end

    // A1: countdown never expires while an operation is outstanding
    always @(*)
        if (pre && busy)
            assert (dl != 8'd0);

    // A2: deadline and completion coincide
    always @(*)
        if (pre && busy && dl == 8'd1)
            assert (cnt == (mode ? 8'd3 : 8'd7));
endmodule

module acc_normalizer (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        load,
    input  wire        shift,
    input  wire [63:0] din,
    output wire [63:0] norm_out,
    output wire [6:0]  exp_adj,
    output wire        done
);
    function [6:0] lzc_tree;
        input [63:0] x;
        reg [31:0] y32;
        reg [15:0] y16;
        reg [7:0]  y8;
        reg [3:0]  y4;
        reg [1:0]  y2;
        reg b5, b4, b3, b2, b1, b0;
        begin
            b5  = ~|x[63:32];
            y32 = b5 ? x[31:0] : x[63:32];
            b4  = ~|y32[31:16];
            y16 = b4 ? y32[15:0] : y32[31:16];
            b3  = ~|y16[15:8];
            y8  = b3 ? y16[7:0] : y16[15:8];
            b2  = ~|y8[7:4];
            y4  = b2 ? y8[3:0] : y8[7:4];
            b1  = ~|y4[3:2];
            y2  = b1 ? y4[1:0] : y4[3:2];
            b0  = ~y2[1];
            if (x == 64'd0)
                lzc_tree = 7'd64;
            else
                lzc_tree = {1'b0, b5, b4, b3, b2, b1, b0};
        end
    endfunction

    reg [63:0] data_r;
    reg [6:0]  lz_r;
    reg        armed_r;
    initial data_r  = 64'd0;
    initial lz_r    = 7'd64;
    initial armed_r = 1'b0;

    wire [6:0] lzc_din = lzc_tree(din);
    wire [6:0] lzc_cur = lzc_tree(data_r);

    always @(posedge clk) begin
        if (rst) begin
            data_r  <= 64'd0;
            lz_r    <= 7'd64;
            armed_r <= 1'b0;
        end else if (en) begin
            if (load) begin
                data_r  <= din;
                lz_r    <= lzc_din;
                armed_r <= 1'b1;
            end else if (shift && lz_r != 7'd0 && lz_r != 7'd64) begin
                data_r <= {data_r[62:0], 1'b0};
                lz_r   <= lz_r - 7'd1;
            end
        end
    end

    assign norm_out = data_r;
    assign exp_adj  = lz_r;
    assign done     = (lz_r == 7'd0);

    always @(*) if (armed_r) assert (!(done && !data_r[63]));
    always @(*) if (armed_r) assert (!(data_r[63] && lz_r != 7'd0));
endmodule

module kv_vault (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        wr_en,
    input  wire [2:0]  wr_slot,
    input  wire [63:0] wr_key,
    input  wire        perm_set,
    input  wire [2:0]  perm_slot,
    input  wire        lock_req,
    input  wire [2:0]  lock_slot,
    input  wire        use_req,
    input  wire [2:0]  use_slot,
    output reg  [63:0] cipher_key,
    output reg         use_gnt
);
    reg [511:0] key;
    reg [7:0]   perm;
    reg [7:0]   lock;
    reg [63:0]  use_cnt;
    reg         armed;

    initial key        = 512'd0;
    initial perm       = 8'd0;
    initial lock       = 8'd0;
    initial use_cnt    = 64'd0;
    initial armed      = 1'b0;
    initial cipher_key = 64'd0;
    initial use_gnt    = 1'b0;

    wire grant = use_req && perm[use_slot] && lock[use_slot];

    always @(posedge clk) begin
        if (!rst_n) begin
            key        <= 512'd0;
            perm       <= 8'd0;
            lock       <= 8'd0;
            use_cnt    <= 64'd0;
            armed      <= 1'b0;
            cipher_key <= 64'd0;
            use_gnt    <= 1'b0;
        end else if (en) begin
            if (wr_en && !lock[wr_slot])
                key[{wr_slot, 6'd0} +: 64] <= wr_key;
            if (perm_set && !lock[perm_slot])
                perm[perm_slot] <= 1'b1;
            if (lock_req) begin
                lock[lock_slot] <= 1'b1;
                if (lock_slot == 3'd0)
                    armed <= 1'b1;
            end
            use_gnt <= grant;
            if (grant) begin
                cipher_key <= key[{use_slot, 6'd0} +: 64];
                use_cnt    <= use_cnt + 64'd1;
            end else begin
                cipher_key <= 64'd0;
            end
        end
    end

    wire [63:0] key0 = key[63:0];

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $past(armed) && $stable(use_cnt))
            assert ($stable(key0));
endmodule

module darki2s_tx (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [63:0] smp_l,
    input wire [63:0] smp_r,
    input wire start,
    input wire stop,
    output wire sd,
    output wire o_ws
);
    localparam [63:0] SLOT_END = 64'd63;
    reg [63:0] sh_l, sh_r, bit_cnt;
    reg ws, own_l, own_r, win;
    initial begin
        sh_l = 64'd0; sh_r = 64'd0; bit_cnt = 64'd0;
        ws = 1'b0; own_l = 1'b1; own_r = 1'b0; win = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            sh_l <= 64'd0;
            sh_r <= 64'd0;
            bit_cnt <= 64'd0;
            ws <= 1'b0;
            own_l <= 1'b1;
            own_r <= 1'b0;
            win <= 1'b0;
        end else if (en) begin
            win <= start ? 1'b1 : (stop ? 1'b0 : win);
            if (bit_cnt == SLOT_END) begin
                bit_cnt <= 64'd0;
                ws <= ~ws;
                own_l <= own_r;
                own_r <= ~ws;
                if (~ws) begin
                    sh_r <= smp_r;
                    if (own_l) sh_l <= {sh_l[62:0], 1'b0};
                end else begin
                    sh_l <= smp_l;
                    if (own_r) sh_r <= {sh_r[62:0], 1'b0};
                end
            end else begin
                bit_cnt <= bit_cnt + 64'd1;
                if (own_l) sh_l <= {sh_l[62:0], 1'b0};
                if (own_r) sh_r <= {sh_r[62:0], 1'b0};
            end
        end
    end

    assign sd = ws ? sh_r[63] : sh_l[63];
    assign o_ws = ws;

    always @(posedge clk)
        if (win)
            assert (!(own_l && own_r));
endmodule

module lim_mod_fold (
    input wire clk,
    input wire rst,
    input wire en,
    input wire start,
    input wire vld,
    input wire [63:0] chunk,
    output wire [15:0] res,
    output wire done
);
    localparam [63:0] M = 64'd65521;

    function [63:0] two64;
        input [31:0] dummy;
        integer i;
        reg [63:0] r;
        begin
            r = 64'd1;
            for (i = 0; i < 64; i = i + 1)
                r = (r * 64'd2) % M;
            two64 = r;
        end
    endfunction

    localparam [63:0] K = two64(0);

    function [63:0] kpow;
        input [31:0] n;
        integer i;
        reg [63:0] r;
        begin
            r = 64'd1;
            for (i = 0; i < n; i = i + 1)
                r = (r * K) % M;
            kpow = r;
        end
    endfunction

    localparam [63:0] C = kpow(256);

    reg [63:0] acc;
    reg [63:0] wreg;
    reg [8:0]  idx;
    reg        armed;
    initial acc = 64'd0;
    initial wreg = 64'd1;
    initial idx = 9'd0;
    initial armed = 1'b0;

    wire [64*257-1:0] wflat;
    genvar g;
    generate
        for (g = 0; g < 257; g = g + 1) begin : G_ROM
            localparam [63:0] WV = kpow(g);
            assign wflat[g*64 +: 64] = WV;
        end
    endgenerate

    wire [63:0] wexp = wflat[idx*64 +: 64];

    always @(posedge clk) begin
        if (rst) begin
            acc   <= 64'd0;
            wreg  <= 64'd1;
            idx   <= 9'd0;
            armed <= 1'b0;
        end else if (en) begin
            if (start) begin
                acc   <= 64'd0;
                wreg  <= 64'd1;
                idx   <= 9'd0;
                armed <= 1'b1;
            end else if (vld && (idx < 9'd256)) begin
                acc  <= (acc + (chunk % M) * wreg) % M;
                wreg <= (wreg * K) % M;
                idx  <= idx + 9'd1;
            end
        end
    end

    assign res  = acc[15:0];
    assign done = (idx == 9'd256);

    always @(posedge clk)
        if (armed && idx == 9'd256)
            assert (wreg == C);
endmodule

module docker_cfg_shadow (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire wr,
    input wire [5:0] waddr,
    input wire [7:0] wdata,
    input wire commit,
    input wire [5:0] raddr,
    output wire [7:0] rdata
);
    reg [7:0] shadow [0:63];
    reg [7:0] active [0:63];
    reg [7:0] wr_cnt;
    reg [7:0] act_gen;
    reg armed;
    reg pre_commit;
    integer i;

    initial begin
        wr_cnt = 8'h00;
        act_gen = 8'h00;
        armed = 1'b0;
        pre_commit = 1'b1;
        for (i = 0; i < 64; i = i + 1) begin
            shadow[i] = 8'h00;
            active[i] = 8'h00;
        end
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            wr_cnt <= 8'h00;
            act_gen <= 8'h00;
            armed <= 1'b0;
            pre_commit <= 1'b1;
            for (i = 0; i < 64; i = i + 1) begin
                shadow[i] <= 8'h00;
                active[i] <= 8'h00;
            end
        end else if (en) begin
            if (wr) begin
                shadow[waddr] <= wdata;
                wr_cnt <= wr_cnt + 8'h01;
            end
            if (armed) begin
                for (i = 0; i < 64; i = i + 1)
                    active[i] <= shadow[i];
                act_gen <= act_gen + 8'h01;
            end
            armed <= commit;
            if (commit)
                pre_commit <= 1'b0;
        end
    end

    assign rdata = active[raddr];

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && rst_n && $past(rst_n) && pre_commit && $stable(wr_cnt))
            assert ($stable(act_gen));
endmodule

module polar_sc_result_dec (
    input wire clk,
    input wire rst,
    input wire en,
    input wire arm,
    input wire start,
    input wire abort,
    input wire wr,
    input wire [2:0] wr_addr,
    input wire [127:0] llr_in,
    output wire [7:0] o_result,
    output wire o_done
);
    localparam [7:0] FROZEN = 8'b0001_0111;
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, DECODE = 2'd2, DONE = 2'd3;

    reg [127:0] llr_mem [0:7];
    reg [7:0] ps;
    reg [7:0] dec;
    reg [2:0] leaf_idx;
    reg [1:0] phase;
    reg armed_seen;
    reg started_seen;
    reg pre_abort;

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) llr_mem[i] = 128'd0;
        ps = 8'd0;
        dec = 8'd0;
        leaf_idx = 3'd0;
        phase = IDLE;
        armed_seen = 1'b0;
        started_seen = 1'b0;
        pre_abort = 1'b1;
    end

    wire [127:0] cur_word = llr_mem[leaf_idx];
    wire [7:0] la = cur_word[7:0];
    wire [7:0] lb = cur_word[15:8];
    wire [6:0] min_mag = (la[6:0] < lb[6:0]) ? la[6:0] : lb[6:0];
    wire [7:0] f_llr = {la[7] ^ lb[7], min_mag};
    wire [2:0] prev_idx = leaf_idx - 3'd1;
    wire u_prev = ps[prev_idx];
    wire [7:0] g_llr = u_prev ? (lb - la) : (lb + la);
    wire [7:0] leaf_llr = leaf_idx[0] ? g_llr : f_llr;
    wire bit_hat = FROZEN[leaf_idx] ? 1'b0 : leaf_llr[7];

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_abort <= 1'b1;
            leaf_idx <= 3'd0;
            ps <= 8'd0;
            dec <= 8'd0;
        end else if (en) begin
            if (wr && phase != DECODE)
                llr_mem[wr_addr] <= llr_in;
            if (abort) begin
                phase <= IDLE;
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm) begin
                            phase <= ARMED;
                            armed_seen <= 1'b1;
                        end
                    end
                    ARMED: begin
                        if (start) begin
                            phase <= DECODE;
                            started_seen <= 1'b1;
                            leaf_idx <= 3'd0;
                            ps <= 8'd0;
                        end
                    end
                    DECODE: begin
                        dec[leaf_idx] <= bit_hat;
                        ps[leaf_idx] <= bit_hat;
                        llr_mem[leaf_idx] <= {cur_word[127:16], f_llr, g_llr};
                        leaf_idx <= leaf_idx + 3'd1;
                        if (leaf_idx == 3'd7)
                            phase <= DONE;
                    end
                    DONE: begin
                        if (arm) begin
                            phase <= ARMED;
                            started_seen <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    assign o_result = dec;
    assign o_done = (phase == DONE);

    always @(posedge clk)
        if (pre_abort && phase == 2'd3)
            assert (started_seen && armed_seen);
endmodule

module jls_remap_lut (
    input wire clk,
    input wire rst,
    input wire en,
    input wire wr_v,
    input wire [63:0] wdata,
    input wire new_frame,
    input wire pix_v,
    input wire [4:0] pix_idx,
    output reg [63:0] out_q
);
    localparam [63:0] DEPTH = 64'd24;
    localparam [63:0] LAST  = 64'd23;

    reg [63:0] mem [0:23];
    reg [63:0] wp;
    reg full_q, empty_q, load_own, map_own, armed;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) mem[i] = 64'd0;
        wp = 64'd0;
        full_q = 1'b0;
        empty_q = 1'b1;
        load_own = 1'b1;
        map_own = 1'b0;
        armed = 1'b0;
        out_q = 64'd0;
    end

    wire [4:0] sidx = (pix_idx > 5'd23) ? 5'd23 : pix_idx;
    wire do_wr = wr_v && load_own && (wp < DEPTH);

    always @(posedge clk) begin
        if (rst) begin
            wp <= 64'd0;
            full_q <= 1'b0;
            empty_q <= 1'b1;
            load_own <= 1'b1;
            map_own <= 1'b0;
            armed <= 1'b0;
            out_q <= 64'd0;
        end else if (en) begin
            if (new_frame) begin
                wp <= 64'd0;
                empty_q <= 1'b1;
                full_q <= 1'b0;
                load_own <= 1'b1;
                map_own <= 1'b0;
            end else if (do_wr) begin
                mem[wp[4:0]] <= wdata;
                wp <= wp + 64'd1;
                empty_q <= empty_q && (wp != 64'd0);
                full_q <= full_q || (wp == LAST);
                load_own <= load_own && (wp != LAST);
                map_own <= map_own || (wp == LAST);
                if (wp == LAST) armed <= 1'b1;
            end
            if (pix_v && map_own)
                out_q <= mem[sidx];
        end
    end

    always @(posedge clk)
        if (armed)
            assert (!(full_q && empty_q));

    always @(posedge clk)
        if (armed)
            assert (!(load_own && map_own));
endmodule

module croc_wm_fifo (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        push,
    input  wire        pop,
    input  wire [63:0] wdata,
    input  wire        cfg_we,
    input  wire [63:0] cfg_af,
    input  wire [63:0] cfg_ae,
    input  wire        arm,
    input  wire        disarm,
    output wire [63:0] rdata,
    output wire        full,
    output wire        empty,
    output wire        afull,
    output wire        aempty
);
    reg [63:0] mem [0:15];
    reg [3:0]  wptr = 4'd0;
    reg [3:0]  rptr = 4'd0;
    reg [63:0] count = 64'd0;
    reg [63:0] af_thr = 64'd14;
    reg [63:0] ae_thr = 64'd2;
    reg        full_q = 1'b0;
    reg        empty_q = 1'b1;
    reg        afull_q = 1'b0;
    reg        aempty_q = 1'b1;
    reg        win_q = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1)
            mem[i] = 64'd0;
    end

    wire do_push = push && !full_q;
    wire do_pop  = pop  && !empty_q;

    assign rdata  = mem[rptr];
    assign full   = full_q;
    assign empty  = empty_q;
    assign afull  = afull_q;
    assign aempty = aempty_q;

    always @(posedge clk) begin
        if (!rst_n) begin
            wptr     <= 4'd0;
            rptr     <= 4'd0;
            count    <= 64'd0;
            af_thr   <= 64'd14;
            ae_thr   <= 64'd2;
            full_q   <= 1'b0;
            empty_q  <= 1'b1;
            afull_q  <= 1'b0;
            aempty_q <= 1'b1;
            win_q    <= 1'b0;
        end else if (en) begin
            if (cfg_we) begin
                af_thr <= cfg_af;
                ae_thr <= cfg_ae;
            end
            if (disarm)
                win_q <= 1'b0;
            else if (arm)
                win_q <= 1'b1;
            if (do_push) begin
                mem[wptr] <= wdata;
                wptr <= wptr + 4'd1;
            end
            if (do_pop)
                rptr <= rptr + 4'd1;
            if (do_push && !do_pop) begin
                count   <= count + 64'd1;
                empty_q <= 1'b0;
                if (count == 64'd15)
                    full_q <= 1'b1;
                if (count + 64'd1 == af_thr)
                    afull_q <= 1'b1;
                if (count == ae_thr)
                    aempty_q <= 1'b0;
            end else if (do_pop && !do_push) begin
                count <= count - 64'd1;
                if (count == 64'd1)
                    empty_q <= 1'b1;
                if (count == 64'd16)
                    full_q <= 1'b0;
                if (count == af_thr)
                    afull_q <= 1'b0;
                if (count - 64'd1 == ae_thr)
                    aempty_q <= 1'b1;
            end
        end
    end

    assert property (!(win_q && full_q && empty_q));
endmodule

module udp_keccak_tagger (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        in_valid,
    input  wire        in_last,
    input  wire [15:0] in_data,
    input  wire        go,
    input  wire        ack,
    output wire [15:0] tag,
    output reg         done,
    output wire        busy
);
    localparam [1:0] P_IDLE = 2'd0, P_ARMED = 2'd1, P_RUN = 2'd2, P_DONE = 2'd3;

    reg [255:0] st;
    reg [3:0]   absorb_ptr;
    reg [4:0]   rnd;
    reg [1:0]   phase;
    reg         armed_flg;
    reg         started_flg;
    reg         seen_q;
    reg         done_q;

    initial begin
        st = 256'd0;
        absorb_ptr = 4'd0;
        rnd = 5'd0;
        phase = P_IDLE;
        armed_flg = 1'b0;
        started_flg = 1'b0;
        seen_q = 1'b0;
        done = 1'b0;
        done_q = 1'b0;
    end

    function [15:0] rotl;
        input [15:0] a;
        input [3:0]  r;
        begin
            rotl = (a << r) | (a >> (5'd16 - {1'b0, r}));
        end
    endfunction

    wire [15:0] rc = (16'h1 << rnd[3:0]) ^ {11'd0, rnd} ^ 16'h8081;

    reg [63:0]  C, D;
    reg [255:0] A1, B, nxt;
    integer x, y, i;

    always @(*) begin
        C = 64'd0;
        for (x = 0; x < 4; x = x + 1)
            for (y = 0; y < 4; y = y + 1)
                C[16*x +: 16] = C[16*x +: 16] ^ st[16*(x+4*y) +: 16];
        for (x = 0; x < 4; x = x + 1)
            D[16*x +: 16] = C[16*((x+3)%4) +: 16] ^ rotl(C[16*((x+1)%4) +: 16], 4'd1);
        for (x = 0; x < 4; x = x + 1)
            for (y = 0; y < 4; y = y + 1)
                A1[16*(x+4*y) +: 16] = st[16*(x+4*y) +: 16] ^ D[16*x +: 16];
        B = 256'd0;
        for (x = 0; x < 4; x = x + 1)
            for (y = 0; y < 4; y = y + 1)
                B[16*(y+4*((x+3*y)%4)) +: 16] = rotl(A1[16*(x+4*y) +: 16], (((x+4*y)*(x+4*y+1))/2) % 16);
        for (x = 0; x < 4; x = x + 1)
            for (y = 0; y < 4; y = y + 1)
                nxt[16*(x+4*y) +: 16] = B[16*(x+4*y) +: 16] ^ ((~B[16*(((x+1)%4)+4*y) +: 16]) & B[16*(((x+2)%4)+4*y) +: 16]);
        nxt[15:0] = nxt[15:0] ^ rc;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            st <= 256'd0;
            absorb_ptr <= 4'd0;
            rnd <= 5'd0;
            phase <= P_IDLE;
            armed_flg <= 1'b0;
            started_flg <= 1'b0;
            seen_q <= 1'b0;
            done <= 1'b0;
        end else if (en) begin
            case (phase)
                P_IDLE: begin
                    if (in_valid) begin
                        for (i = 0; i < 16; i = i + 1)
                            if (i == absorb_ptr)
                                st[16*i +: 16] <= st[16*i +: 16] ^ in_data;
                        if (in_last) begin
                            phase <= P_ARMED;
                            armed_flg <= 1'b1;
                            seen_q <= 1'b1;
                            absorb_ptr <= 4'd0;
                        end else begin
                            absorb_ptr <= absorb_ptr + 4'd1;
                        end
                    end
                end
                P_ARMED: begin
                    if (go) begin
                        phase <= P_RUN;
                        rnd <= 5'd0;
                        started_flg <= 1'b1;
                    end
                end
                P_RUN: begin
                    st <= nxt;
                    if (rnd == 5'd23) begin
                        phase <= P_DONE;
                        done <= 1'b1;
                    end else begin
                        rnd <= rnd + 5'd1;
                    end
                end
                P_DONE: begin
                    if (ack) begin
                        phase <= P_IDLE;
                        done <= 1'b0;
                        armed_flg <= 1'b0;
                        started_flg <= 1'b0;
                        st <= 256'd0;
                    end
                end
            endcase
        end
    end

    always @(posedge clk) done_q <= done;

    assign tag  = st[15:0];
    assign busy = (phase == P_RUN);

    reg pv;
    initial pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && seen_q && done && !done_q)
            assert (armed_flg && started_flg);
endmodule

module tlb32_ice40 (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [51:0] lookup_vpn,
    input wire [7:0] lookup_asid,
    input wire fill,
    input wire [51:0] fill_vpn,
    input wire [7:0] fill_asid,
    input wire [51:0] fill_ppn,
    input wire [2:0] fill_perm,
    input wire flush_all,
    input wire flush_asid,
    input wire [7:0] asid_sel,
    output reg hit,
    output reg [51:0] ppn_out,
    output reg [2:0] perm_out
);
    reg [31:0] valid = 32'd0;
    reg [63:0] occ = 64'd0;
    reg [63:0] hits = 64'd0;
    reg [4:0] victim = 5'd0;

    reg [51:0] tag_vpn [0:31];
    reg [7:0] tag_asid [0:31];
    reg [51:0] data_ppn [0:31];
    reg [2:0] data_perm [0:31];

    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1) begin
            tag_vpn[i] = 52'd0;
            tag_asid[i] = 8'd0;
            data_ppn[i] = 52'd0;
            data_perm[i] = 3'd0;
        end
    end

    function [6:0] popcount32;
        input [31:0] v;
        integer k;
        begin
            popcount32 = 7'd0;
            for (k = 0; k < 32; k = k + 1)
                popcount32 = popcount32 + {6'd0, v[k]};
        end
    endfunction

    reg [31:0] asid_match;
    reg [4:0] free_idx;
    reg has_free;
    integer j;

    always @(*) begin
        asid_match = 32'd0;
        hit = 1'b0;
        ppn_out = 52'd0;
        perm_out = 3'd0;
        has_free = 1'b0;
        free_idx = 5'd0;
        for (j = 31; j >= 0; j = j - 1) begin
            if (!valid[j]) begin
                has_free = 1'b1;
                free_idx = j;
            end
        end
        for (j = 0; j < 32; j = j + 1) begin
            if (valid[j] && (tag_asid[j] == asid_sel))
                asid_match[j] = 1'b1;
            if (valid[j] && !hit && (tag_vpn[j] == lookup_vpn) && (tag_asid[j] == lookup_asid)) begin
                hit = 1'b1;
                ppn_out = data_ppn[j];
                perm_out = data_perm[j];
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            valid <= 32'd0;
            occ <= 64'd0;
            hits <= 64'd0;
            victim <= 5'd0;
        end else if (en) begin
            if (flush_all) begin
                valid <= 32'd0;
                occ <= 64'd0;
            end else if (flush_asid) begin
                valid <= valid & ~asid_match;
                occ <= occ - {57'd0, popcount32(asid_match)};
            end else if (fill) begin
                if (has_free) begin
                    tag_vpn[free_idx] <= fill_vpn;
                    tag_asid[free_idx] <= fill_asid;
                    data_ppn[free_idx] <= fill_ppn;
                    data_perm[free_idx] <= fill_perm;
                    valid <= valid | (32'd1 << free_idx);
                    occ <= occ + 64'd1;
                end else begin
                    tag_vpn[victim] <= fill_vpn;
                    tag_asid[victim] <= fill_asid;
                    data_ppn[victim] <= fill_ppn;
                    data_perm[victim] <= fill_perm;
                    victim <= victim + 5'd1;
                end
            end
            if (hit)
                hits <= hits + 64'd1;
        end
    end

    assert property (occ <= 64'd32);
endmodule

module spi_snoop_filter (
    input wire clk,
    input wire en,
    input wire sclk_rise,
    input wire mosi,
    output wire [4:0] o_occ
);
    reg [15:0] sr;
    reg [3:0]  bitcnt;
    reg [15:0] pvec [0:15];
    reg [4:0]  occ_cnt;
    reg        armed;

    integer k;
    initial begin
        sr = 16'd0;
        bitcnt = 4'd0;
        occ_cnt = 5'd0;
        armed = 1'b0;
        for (k = 0; k < 16; k = k + 1)
            pvec[k] = 16'd0;
    end

    wire [15:0] w   = {sr[14:0], mosi};
    wire [1:0]  op  = w[15:14];
    wire [3:0]  idx = w[13:10];
    wire [3:0]  cid = w[9:6];
    wire [15:0] cur = pvec[idx];
    wire [15:0] cmask = 16'd1 << cid;
    wire [15:0] set_v = cur | cmask;
    wire [15:0] clr_v = cur & ~cmask;

    always @(posedge clk) begin
        if (en && sclk_rise) begin
            sr <= w;
            bitcnt <= bitcnt + 4'd1;
            if (bitcnt == 4'd15) begin
                case (op)
                    2'b01: begin
                        pvec[idx] <= set_v;
                        if (cur == 16'd0)
                            occ_cnt <= occ_cnt + 5'd1;
                    end
                    2'b10: begin
                        pvec[idx] <= clr_v;
                        if (cur != 16'd0 && clr_v == 16'd0)
                            occ_cnt <= occ_cnt - 5'd1;
                    end
                    2'b11: begin
                        pvec[idx] <= 16'd0;
                        if (cur != 16'd0) begin
                            occ_cnt <= occ_cnt - 5'd1;
                            armed <= 1'b1;
                        end
                    end
                    default: ;
                endcase
            end
        end
    end

    assign o_occ = occ_cnt;

    always @(posedge clk)
        if (armed)
            assert (occ_cnt <= 5'd16);
endmodule

module stepper_seq (
    input wire clk,
    input wire i_ce,
    input wire i_open,
    input wire i_close,
    input wire i_arm,
    input wire i_start,
    input wire [7:0] i_rate,
    input wire i_wr,
    input wire [2:0] i_waddr,
    input wire [127:0] i_wdata,
    output wire [127:0] o_coil,
    output wire o_done
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [1:0] fsm = S_IDLE;
    reg win = 1'b0;
    reg arm_seen = 1'b0;
    reg start_seen = 1'b0;
    reg [2:0] phase = 3'd0;
    reg [7:0] div = 8'd0;
    reg [7:0] rate = 8'd0;

    reg [127:0] pat [0:7];
    integer k;
    initial for (k = 0; k < 8; k = k + 1) pat[k] = 128'd1 << (k * 16);

    always @(posedge clk)
        if (i_ce && i_wr && !win)
            pat[i_waddr] <= i_wdata;

    always @(posedge clk) begin
        if (i_ce) begin
            if (!win) begin
                if (i_open) begin
                    win <= 1'b1;
                    fsm <= S_IDLE;
                    arm_seen <= 1'b0;
                    start_seen <= 1'b0;
                    phase <= 3'd0;
                    div <= 8'd0;
                end
            end else if (i_close) begin
                win <= 1'b0;
            end else begin
                case (fsm)
                    S_IDLE: if (i_arm) begin
                        fsm <= S_ARMED;
                        arm_seen <= 1'b1;
                        rate <= i_rate;
                    end
                    S_ARMED: if (i_start) begin
                        fsm <= S_RUN;
                        start_seen <= 1'b1;
                        div <= 8'd0;
                    end
                    S_RUN: begin
                        if (div == rate) begin
                            div <= 8'd0;
                            phase <= phase + 3'd1;
                            if (phase == 3'd7)
                                fsm <= S_DONE;
                        end else begin
                            div <= div + 8'd1;
                        end
                    end
                    default: if (i_arm) begin
                        fsm <= S_ARMED;
                        start_seen <= 1'b0;
                        rate <= i_rate;
                    end
                endcase
            end
        end
    end

    assign o_coil = pat[phase];
    assign o_done = (fsm == S_DONE);

    always @(*) if (win && fsm == S_DONE) assert (start_seen);
    always @(*) if (win && start_seen) assert (arm_seen);
endmodule

module range_mask_insert (
    input  wire        clk,
    input  wire        req,
    input  wire        ce,
    input  wire [4:0]  i_start,
    input  wire [4:0]  i_end,
    input  wire [31:0] i_src,
    output wire [31:0] mask,
    output reg  [31:0] dst,
    output reg         busy
);
    reg [4:0]  start_idx = 5'd0;
    reg [4:0]  end_idx   = 5'd0;
    reg [4:0]  cur       = 5'd0;
    reg [31:0] timer     = 32'd0;
    reg [31:0] src       = 32'd0;
    reg        arm       = 1'b0;
    initial busy = 1'b0;
    initial dst  = 32'd0;

    // contiguous range mask decoder: bits start_idx..end_idx asserted
    assign mask = (32'hFFFFFFFF << start_idx) & (32'hFFFFFFFF >> (5'd31 - end_idx));

    wire [4:0] off = cur - start_idx;

    always @(posedge clk) begin
        if (!busy) begin
            if (req && (i_start <= i_end)) begin
                start_idx <= i_start;
                end_idx   <= i_end;
                cur       <= i_start;
                src       <= i_src;
                busy      <= 1'b1;
                timer     <= 32'd32;
                arm       <= 1'b1;
            end
        end else if (ce) begin
            dst[cur] <= src[off];
            timer    <= timer - 32'd1;
            if (cur == end_idx)
                busy <= 1'b0;
            else
                cur <= cur + 5'd1;
        end
    end

    always @(*) assert (!arm || !busy || (timer != 32'd0));
endmodule

module nan_canon_log (
    input wire clk,
    input wire i_ce,
    input wire [15:0] i_a,
    input wire [15:0] i_b,
    input wire i_canon,
    input wire i_pop,
    output wire [15:0] o_result,
    output wire o_invalid,
    output wire [15:0] o_log_head,
    output wire [15:0] o_occ
);
    localparam [15:0] QNAN_CANON = 16'h7E00;
    localparam [15:0] QUIET_BIT  = 16'h0200;

    // half-precision NaN classification
    wire a_nan  = (i_a[14:10] == 5'h1f) && (i_a[9:0] != 10'd0);
    wire b_nan  = (i_b[14:10] == 5'h1f) && (i_b[9:0] != 10'd0);
    wire a_snan = a_nan && !i_a[9];
    wire b_snan = b_nan && !i_b[9];
    wire any_nan = a_nan | b_nan;

    // NaN selection / quieting / canonicalization
    reg [15:0] sel;
    always @(*) begin
        if (i_canon)     sel = QNAN_CANON;
        else if (a_snan) sel = i_a | QUIET_BIT;
        else if (b_snan) sel = i_b | QUIET_BIT;
        else if (a_nan)  sel = i_a;
        else             sel = i_b;
    end
    wire [15:0] nxt = any_nan ? sel : i_a;

    reg [15:0] r_result = 16'd0;
    reg        r_invalid = 1'b0;
    reg [3:0]  wptr = 4'd0;
    reg [3:0]  rptr = 4'd0;
    reg [15:0] occ  = 16'd0;
    reg [15:0] log_mem [0:7];
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) log_mem[i] = 16'd0;
    end

    wire [3:0] fill  = wptr - rptr;
    wire full  = (fill == 4'd8);
    wire empty = (fill == 4'd0);
    wire push_ok = i_ce && any_nan && !full;
    wire pop_ok  = i_pop && !empty;

    always @(posedge clk) begin
        if (i_ce) begin
            r_result  <= nxt;
            r_invalid <= a_snan | b_snan;
        end
        if (push_ok) begin
            log_mem[wptr[2:0]] <= sel;
            wptr <= wptr + 4'd1;
        end
        if (pop_ok)
            rptr <= rptr + 4'd1;
        case ({push_ok, pop_ok})
            2'b10: occ <= occ + 16'd1;
            2'b01: occ <= occ - 16'd1;
            default: ;
        endcase
    end

    assign o_result   = r_result;
    assign o_invalid  = r_invalid;
    assign o_log_head = log_mem[rptr[2:0]];
    assign o_occ      = occ;

    always @(posedge clk) assert (occ <= 16'd8);
endmodule

module trivium_core (
    input  wire        clk,
    input  wire        ce,
    input  wire        load,
    input  wire        zeroize,
    input  wire [79:0] key,
    input  wire [79:0] iv,
    output wire        ks_bit,
    output wire        ks_valid,
    output reg         ready
);
    reg [287:0] s = 288'd0;
    reg [63:0]  wcnt = 64'd0;
    reg         busy = 1'b0;
    reg         seen_load = 1'b0;
    reg         armed = 1'b1;
    reg         pv = 1'b0;
    initial ready = 1'b0;

    wire t1a = s[65]  ^ s[92];
    wire t2a = s[161] ^ s[176];
    wire t3a = s[242] ^ s[287];
    wire z   = t1a ^ t2a ^ t3a;
    wire t1  = t1a ^ (s[90]  & s[91])  ^ s[170];
    wire t2  = t2a ^ (s[174] & s[175]) ^ s[263];
    wire t3  = t3a ^ (s[285] & s[286]) ^ s[68];

    wire [287:0] nxt  = {s[286:177], t2, s[175:93], t1, s[91:0], t3};
    wire [287:0] init = {3'b111, 108'd0, 4'd0, iv, 13'd0, key};

    assign ks_bit   = z;
    assign ks_valid = ready && ce && !load && !zeroize;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (zeroize) begin
            s         <= 288'd0;
            wcnt      <= 64'd0;
            busy      <= 1'b0;
            ready     <= 1'b0;
            seen_load <= 1'b0;
            armed     <= 1'b0;
        end else if (ce) begin
            if (load) begin
                s         <= init;
                wcnt      <= 64'd0;
                busy      <= 1'b1;
                ready     <= 1'b0;
                seen_load <= 1'b1;
            end else if (busy) begin
                s <= nxt;
                if (wcnt == 64'd1151) begin
                    busy  <= 1'b0;
                    ready <= 1'b1;
                    wcnt  <= 64'd0;
                end else begin
                    wcnt <= wcnt + 64'd1;
                end
            end else if (ready) begin
                s <= nxt;
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && $rose(ready))
            assert (seen_load);
endmodule

module mutex_arb (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire req_a,
    input wire req_b,
    input wire rel,
    input wire w_open,
    input wire w_close,
    output wire o_own_a,
    output wire o_own_b,
    output wire [31:0] o_grants
);
    localparam [1:0] IDLE = 2'd0, ARM = 2'd1, START = 2'd2, FIN = 2'd3;

    reg [1:0] phase;
    reg latch_a, latch_b;
    reg sync_a, sync_b;
    reg own_a, own_b;
    reg win;
    reg [31:0] n_grants;

    initial phase = IDLE;
    initial latch_a = 1'b0;
    initial latch_b = 1'b0;
    initial sync_a = 1'b0;
    initial sync_b = 1'b0;
    initial own_a = 1'b0;
    initial own_b = 1'b0;
    initial win = 1'b0;
    initial n_grants = 32'd0;

    // cross-coupled set terms: each side inhibited by the other, A wins ties
    wire set_a = req_a & ~latch_b;
    wire set_b = req_b & ~latch_a & ~set_a;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            latch_a <= 1'b0;
            latch_b <= 1'b0;
            sync_a <= 1'b0;
            sync_b <= 1'b0;
            own_a <= 1'b0;
            own_b <= 1'b0;
            win <= 1'b0;
            n_grants <= 32'd0;
        end else if (i_ce) begin
            if (w_open)
                win <= 1'b1;
            else if (w_close)
                win <= 1'b0;
            case (phase)
                IDLE: begin
                    if (set_a | set_b) begin
                        latch_a <= latch_a | set_a;
                        latch_b <= latch_b | set_b;
                        phase <= ARM;
                    end
                end
                ARM: begin
                    sync_a <= latch_a;
                    sync_b <= latch_b;
                    phase <= START;
                end
                START: begin
                    own_a <= sync_a;
                    own_b <= sync_b;
                    n_grants <= n_grants + 32'd1;
                    phase <= FIN;
                end
                FIN: begin
                    if (rel) begin
                        latch_a <= 1'b0;
                        latch_b <= 1'b0;
                        sync_a <= 1'b0;
                        sync_b <= 1'b0;
                        own_a <= 1'b0;
                        own_b <= 1'b0;
                        phase <= IDLE;
                    end
                end
            endcase
        end
    end

    assign o_own_a = own_a;
    assign o_own_b = own_b;
    assign o_grants = n_grants;

    // Chain precedence inside the window: ownership (finish) only with filter (start) and latch (arm)
    assert property (!win || ((!own_a || (sync_a && latch_a)) && (!own_b || (sync_b && latch_b))));
endmodule

module ifu_align_buf (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_rvalid,
    input  wire [127:0] i_rdata,
    input  wire         i_pop,
    output wire         o_req,
    output wire [31:0]  o_fetch_addr,
    output wire         o_valid,
    output wire [127:0] o_line,
    output wire [31:0]  o_pc
);
    reg [127:0] abuf [0:7];
    reg [3:0]  wptr = 4'd0;
    reg [3:0]  rptr = 4'd0;
    reg [3:0]  count = 4'd0;
    reg [31:0] fetch_ptr = 32'd0;
    reg [31:0] head_pc = 32'd0;
    reg        armed = 1'b0;
    reg        pv = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            abuf[i] = 128'd0;
    end

    wire [3:0] occ   = wptr - rptr;
    wire       full  = (occ == 4'd8);
    wire       empty = (occ == 4'd0);
    wire push_ok = i_ce && i_rvalid && !full;
    wire pop_ok  = i_ce && i_pop && !empty;

    always @(posedge clk) begin
        if (push_ok) begin
            abuf[wptr[2:0]] <= i_rdata;
            wptr            <= wptr + 4'd1;
            fetch_ptr       <= fetch_ptr + 32'd16;
        end
        if (pop_ok) begin
            rptr    <= rptr + 4'd1;
            head_pc <= head_pc + 32'd16;
        end
        case ({push_ok, pop_ok})
            2'b10:   count <= count + 4'd1;
            2'b01:   count <= count - 4'd1;
            default: count <= count;
        endcase
    end

    always @(posedge clk)
        if (push_ok)
            armed <= 1'b1;

    always @(posedge clk)
        pv <= 1'b1;

    assign o_req        = !full;
    assign o_fetch_addr = fetch_ptr;
    assign o_valid      = !empty;
    assign o_line       = abuf[rptr[2:0]];
    assign o_pc         = head_pc;

    always @(posedge clk)
        if (armed && pv && $stable(rptr))
            assert ($stable(head_pc) && (count <= 4'd8));
endmodule

module doorbell_sweep (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        ring,
    input  wire [5:0]  ring_ch,
    input  wire        ext,
    output reg         busy,
    output reg  [7:0]  svc_cnt,
    output reg  [47:0] pending
);
    reg [5:0] idx;
    reg [7:0] deadline;
    reg       armed;
    reg       pv;
    initial begin
        pending  = 48'd0;
        busy     = 1'b0;
        idx      = 6'd0;
        deadline = 8'd0;
        armed    = 1'b1;
        svc_cnt  = 8'd0;
        pv       = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (ext) armed <= 1'b0;
            if (busy) begin
                if (pending[idx]) svc_cnt <= svc_cnt + 8'd1;
                pending[idx] <= 1'b0;
                deadline <= deadline - 8'd1 + (ext ? 8'd16 : 8'd0);
                if (idx == 6'd47) begin
                    busy <= 1'b0;
                    idx  <= 6'd0;
                end else begin
                    idx <= idx + 6'd1;
                end
            end else if (pending != 48'd0) begin
                busy     <= 1'b1;
                idx      <= 6'd0;
                deadline <= 8'd48;
            end
            if (ring && (ring_ch < 6'd48)) pending[ring_ch] <= 1'b1;
        end
    end

    always @(posedge clk)
        if (armed && busy)
            assert (deadline != 8'd0);

    always @(posedge clk)
        if (pv && armed && $past(i_ce) && $past(busy) && !busy)
            assert ($past(deadline) == 8'd1);
endmodule

module backoff_ctrl (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire req,
    input wire col,
    input wire [63:0] rnd,
    output wire tx_active,
    output wire busy,
    output wire [63:0] o_attempts
);
    localparam [1:0] S_IDLE = 2'd0;
    localparam [1:0] S_WAIT = 2'd1;
    localparam [1:0] S_TX   = 2'd2;
    localparam [63:0] MAXA    = 64'd3;
    localparam [63:0] BUDGET0 = 64'd18;

    reg [1:0]  state;
    reg        pending;
    reg [63:0] attempts;
    reg [63:0] slot;
    reg [63:0] budget;

    initial begin
        state = S_IDLE;
        pending = 1'b0;
        attempts = 64'd0;
        slot = 64'd0;
        budget = 64'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE;
            pending <= 1'b0;
            attempts <= 64'd0;
            slot <= 64'd0;
            budget <= 64'd0;
        end else if (ce) begin
            case (state)
                S_IDLE: begin
                    if (req) begin
                        state <= S_TX;
                        pending <= 1'b1;
                        attempts <= 64'd0;
                        slot <= 64'd0;
                        budget <= BUDGET0;
                    end
                end
                S_WAIT: begin
                    budget <= budget - 64'd1;
                    if (slot == 64'd0)
                        state <= S_TX;
                    else
                        slot <= slot - 64'd1;
                end
                S_TX: begin
                    budget <= budget - 64'd1;
                    if (!col) begin
                        state <= S_IDLE;
                        pending <= 1'b0;
                        attempts <= 64'd0;
                    end else if (attempts >= MAXA) begin
                        state <= S_IDLE;
                        pending <= 1'b0;
                        attempts <= 64'd0;
                    end else begin
                        attempts <= attempts + 64'd1;
                        slot <= rnd & ((64'd1 << (attempts + 64'd1)) - 64'd1);
                        state <= S_WAIT;
                    end
                end
                default: begin
                    state <= S_IDLE;
                    pending <= 1'b0;
                end
            endcase
        end
    end

    assign tx_active = (state == S_TX);
    assign busy = pending;
    assign o_attempts = attempts;

    always @(posedge clk)
        if (pending)
            assert (budget != 64'd0);
endmodule

module dirty_track_ram (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_we,
    input  wire [1:0]   i_addr,
    input  wire [127:0] i_wdata,
    input  wire         i_clr,
    input  wire         i_clr_blk,
    input  wire         i_clr_all,
    output wire [127:0] o_rdata,
    output wire [1:0]   o_dirty,
    output wire [1:0]   o_dirty_cnt,
    output wire         o_any_dirty
);
    // 4 x 128-bit data array, organised as 2 blocks of 2 words
    reg [127:0] mem [0:3];
    reg [1:0]   dirty     = 2'b00;
    reg [1:0]   dirty_cnt = 2'd0;
    reg         any_dirty = 1'b0;

    initial begin
        mem[0] = 128'd0;
        mem[1] = 128'd0;
        mem[2] = 128'd0;
        mem[3] = 128'd0;
    end

    wire wblk = i_addr[1];

    reg [1:0] dirty_nx;
    reg [1:0] cnt_nx;
    always @(*) begin
        dirty_nx = dirty;
        cnt_nx   = dirty_cnt;
        if (i_we) begin
            dirty_nx[wblk] = 1'b1;
            if (!dirty[wblk])
                cnt_nx = dirty_cnt + 2'd1;
        end else if (i_clr_all) begin
            dirty_nx = 2'b00;
            cnt_nx   = 2'd0;
        end else if (i_clr) begin
            dirty_nx[i_clr_blk] = 1'b0;
            if (dirty[i_clr_blk])
                cnt_nx = dirty_cnt - 2'd1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_we)
                mem[i_addr] <= i_wdata;
            dirty     <= dirty_nx;
            dirty_cnt <= cnt_nx;
            any_dirty <= |dirty_nx;
        end
    end

    assign o_rdata     = mem[i_addr];
    assign o_dirty     = dirty;
    assign o_dirty_cnt = dirty_cnt;
    assign o_any_dirty = any_dirty;

    always @(*)
        assert (any_dirty == (dirty_cnt != 2'd0));
endmodule

module lz77_match_finder (
    input wire clk,
    input wire i_push,
    input wire [63:0] i_data,
    input wire i_start,
    input wire [63:0] i_look0,
    input wire [63:0] i_look1,
    input wire i_ce,
    input wire i_ack,
    input wire i_flush,
    output wire o_searching,
    output wire o_match_valid,
    output wire [63:0] o_best_len,
    output wire [63:0] o_best_pos,
    output wire [63:0] o_match_len
);
    localparam [63:0] WIN  = 64'd256;
    localparam [63:0] LAST = 64'd255;

    reg [63:0] hist [0:255];
    reg [63:0] wr_ptr    = 64'd0;
    reg [63:0] look0     = 64'd0;
    reg [63:0] look1     = 64'd0;
    reg [63:0] scan_idx  = 64'd0;
    reg [63:0] scan_left = 64'd0;
    reg [63:0] cand_pos  = 64'd0;
    reg [63:0] match_len = 64'd0;
    reg [63:0] best_len  = 64'd0;
    reg [63:0] best_pos  = 64'd0;
    reg searching   = 1'b0;
    reg match_valid = 1'b0;
    reg armed       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) hist[i] = 64'd0;
    end

    wire [7:0] c0 = cand_pos[7:0];
    wire [7:0] c1 = c0 + 8'd1;
    wire [63:0] cand_len = (hist[c0] == look0) ? ((hist[c1] == look1) ? 64'd2 : 64'd1) : 64'd0;

    always @(posedge clk) begin
        if (i_push && !searching) begin
            hist[wr_ptr[7:0]] <= i_data;
            wr_ptr <= wr_ptr + 64'd1;
        end
        if (!searching && i_start) begin
            searching   <= 1'b1;
            match_valid <= 1'b0;
            scan_idx    <= 64'd0;
            scan_left   <= WIN;
            cand_pos    <= wr_ptr;
            look0       <= i_look0;
            look1       <= i_look1;
            best_len    <= 64'd0;
            best_pos    <= 64'd0;
            match_len   <= 64'd0;
        end else if (searching && i_ce) begin
            match_len <= cand_len;
            if (cand_len > best_len) begin
                best_len <= cand_len;
                best_pos <= cand_pos;
            end
            cand_pos  <= cand_pos + 64'd1;
            scan_idx  <= scan_idx + 64'd1;
            scan_left <= scan_left - 64'd1;
            if (scan_left == 64'd1) searching <= 1'b0;
            if (scan_idx == LAST) match_valid <= 1'b1;
        end else if (!searching && i_ack) begin
            match_valid <= 1'b0;
        end
    end

    // scope window: opened by the first accepted search, closed by flush
    always @(posedge clk) begin
        if (i_flush) armed <= 1'b0;
        else if (!searching && i_start) armed <= 1'b1;
    end

    assign o_searching   = searching;
    assign o_match_valid = match_valid;
    assign o_best_len    = best_len;
    assign o_best_pos    = best_pos;
    assign o_match_len   = match_len;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(armed))
            assert (!($past(searching) && $past(match_valid)));
endmodule

module async_mem_bus_ctrl (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         req,
    input  wire         req_wr,
    input  wire [4:0]   req_cs,
    input  wire [63:0]  req_addr,
    input  wire [63:0]  req_wdata,
    input  wire [63:0]  i_rdata,
    input  wire         cfg_we,
    input  wire [4:0]   cfg_cs,
    input  wire [63:0]  cfg_setup,
    input  wire [63:0]  cfg_access,
    input  wire [63:0]  cfg_hold,
    output wire [31:0]  cs_n,
    output wire         oe_n,
    output wire         we_n,
    output wire [63:0]  addr,
    output wire [63:0]  wdata,
    output wire [63:0]  rdata,
    output wire         busy
);
    localparam [1:0] P_IDLE = 2'd0, P_SETUP = 2'd1, P_ACCESS = 2'd2, P_HOLD = 2'd3;

    reg [1:0]    phase     = P_IDLE;
    reg [63:0]   cnt       = 64'd0;
    reg          wr_lat    = 1'b0;
    reg [4:0]    cs_lat    = 5'd0;
    reg [63:0]   addr_lat  = 64'd0;
    reg [63:0]   wdata_lat = 64'd0;
    reg [63:0]   rdata_lat = 64'd0;
    reg          oe        = 1'b0;
    reg          we        = 1'b0;
    reg          armed     = 1'b0;

    // per-chip-select timing registers: 32 entries x 64 bits each
    reg [2047:0] tsetup_flat  = {32{64'd1}};
    reg [2047:0] taccess_flat = {32{64'd2}};
    reg [2047:0] thold_flat   = {32{64'd1}};

    wire [63:0] t_setup  = tsetup_flat[cs_lat*64 +: 64];
    wire [63:0] t_access = taccess_flat[cs_lat*64 +: 64];
    wire [63:0] t_hold   = thold_flat[cs_lat*64 +: 64];

    always @(posedge clk) begin
        if (rst) begin
            phase  <= P_IDLE;
            cnt    <= 64'd0;
            wr_lat <= 1'b0;
            oe     <= 1'b0;
            we     <= 1'b0;
        end else if (i_ce) begin
            if (cfg_we) begin
                tsetup_flat[cfg_cs*64 +: 64]  <= cfg_setup;
                taccess_flat[cfg_cs*64 +: 64] <= cfg_access;
                thold_flat[cfg_cs*64 +: 64]   <= cfg_hold;
            end
            case (phase)
                P_IDLE: begin
                    if (req) begin
                        phase     <= P_SETUP;
                        cnt       <= 64'd0;
                        wr_lat    <= req_wr;
                        cs_lat    <= req_cs;
                        addr_lat  <= req_addr;
                        wdata_lat <= req_wdata;
                        armed     <= 1'b1;
                    end
                end
                P_SETUP: begin
                    if (cnt >= t_setup) begin
                        phase <= P_ACCESS;
                        cnt   <= 64'd0;
                        if (wr_lat) we <= 1'b1;
                        else        oe <= 1'b1;
                    end else begin
                        cnt <= cnt + 64'd1;
                    end
                end
                P_ACCESS: begin
                    if (cnt >= t_access) begin
                        phase <= P_HOLD;
                        cnt   <= 64'd0;
                        if (!wr_lat) rdata_lat <= i_rdata;
                        oe    <= 1'b0;
                        we    <= 1'b0;
                    end else begin
                        cnt <= cnt + 64'd1;
                    end
                end
                P_HOLD: begin
                    if (cnt >= t_hold) begin
                        phase <= P_IDLE;
                        cnt   <= 64'd0;
                    end else begin
                        cnt <= cnt + 64'd1;
                    end
                end
            endcase
        end
    end

    assign cs_n  = (phase == P_IDLE) ? 32'hFFFFFFFF : ~(32'd1 << cs_lat);
    assign oe_n  = ~oe;
    assign we_n  = ~we;
    assign addr  = addr_lat;
    assign wdata = wdata_lat;
    assign rdata = rdata_lat;
    assign busy  = (phase != P_IDLE);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Absence after first accepted transaction: OE and WE strobes never both active
    always @(posedge clk)
        if (pv && armed)
            assert (!($past(oe) && $past(we)));
endmodule

module stream_buffer (
    input wire clk,
    input wire ce,
    input wire flush,
    input wire [31:0] miss_addr,
    input wire fill,
    input wire [31:0] fill_data,
    input wire req,
    input wire [31:0] req_addr,
    output wire hit,
    output wire [31:0] hit_data,
    output wire [31:0] hit_tag
);
    reg [31:0] head = 32'd0;
    reg [31:0] tail = 32'd0;
    reg [6:0]  count = 7'd0;
    reg [5:0]  wptr = 6'd0;
    reg [5:0]  rptr = 6'd0;
    reg [63:0] valid = 64'd0;
    reg [31:0] tag_mem  [0:63];
    reg [31:0] data_mem [0:63];
    reg [31:0] fills = 32'd0;
    reg [31:0] hits  = 32'd0;
    reg armed = 1'b1;
    reg pv = 1'b0;
    integer i;
    initial begin
        for (i = 0; i < 64; i = i + 1) begin
            tag_mem[i]  = 32'd0;
            data_mem[i] = 32'd0;
        end
    end

    wire do_fill = ce && !flush && fill && (count != 7'd64);
    wire do_hit  = ce && !flush && req && (count != 7'd0) && (req_addr == head);

    assign hit      = do_hit;
    assign hit_data = data_mem[rptr];
    assign hit_tag  = tag_mem[rptr];

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (flush) begin
                head  <= miss_addr + 32'd1;
                tail  <= miss_addr + 32'd1;
                count <= 7'd0;
                wptr  <= 6'd0;
                rptr  <= 6'd0;
                valid <= 64'd0;
                armed <= 1'b0;
            end else begin
                if (do_fill) begin
                    tag_mem[wptr]  <= tail;
                    data_mem[wptr] <= fill_data;
                    tail  <= tail + 32'd1;
                    wptr  <= wptr + 6'd1;
                    fills <= fills + 32'd1;
                end
                if (do_hit) begin
                    rptr <= rptr + 6'd1;
                    head <= head + 32'd1;
                    hits <= hits + 32'd1;
                end
                valid <= (valid | (do_fill ? (64'd1 << wptr) : 64'd0))
                         & ~(do_hit ? (64'd1 << rptr) : 64'd0);
                case ({do_fill, do_hit})
                    2'b10:   count <= count + 7'd1;
                    2'b01:   count <= count - 7'd1;
                    default: count <= count;
                endcase
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && $stable(fills) && $past(fills == hits))
            assert ($stable(hits));
endmodule

module welch_spectral_avg (
    input  wire        clk,
    input  wire        in_valid,
    input  wire [7:0]  mag,
    input  wire        dump,
    input  wire [6:0]  rd_addr,
    output wire [23:0] rd_data,
    output wire        avg_done
);
    // per-bin accumulation RAM for squared magnitudes
    reg [23:0] acc [0:127];
    reg [7:0]  bin_idx      = 8'd0;
    reg [7:0]  frame_cnt    = 8'd0;
    reg [10:0] samples_left = 11'd1024;
    reg        armed        = 1'b1;   // high until the first dump event

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1)
            acc[i] = 24'd0;
    end

    wire [15:0] sq     = mag * mag;
    wire        accept = in_valid && (!armed || samples_left != 11'd0);

    always @(posedge clk) begin
        if (dump) begin
            armed        <= 1'b0;
            bin_idx      <= 8'd0;
            frame_cnt    <= 8'd0;
            samples_left <= 11'd0;
        end else if (accept) begin
            acc[bin_idx[6:0]] <= ((frame_cnt == 8'd0) ? 24'd0 : acc[bin_idx[6:0]]) + {8'd0, sq};
            if (bin_idx == 8'd127) begin
                bin_idx   <= 8'd0;
                frame_cnt <= frame_cnt + 8'd1;
            end else begin
                bin_idx <= bin_idx + 8'd1;
            end
            if (armed)
                samples_left <= samples_left - 11'd1;
        end
    end

    // 8-frame Welch average: divide accumulated power by 8
    assign rd_data  = acc[rd_addr] >> 3;
    assign avg_done = armed && (samples_left == 11'd0);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Before the first dump, the frame count never exceeded 8
    always @(posedge clk)
        if (pv && armed)
            assert ($past(frame_cnt) <= 8'd8);
endmodule

module ptw_walker (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_start,
    input  wire [15:0] i_va,
    input  wire [15:0] i_root,
    input  wire        i_mem_valid,
    input  wire [15:0] i_mem_data,
    input  wire        i_ack,
    output wire        o_mem_req,
    output wire [15:0] o_mem_addr,
    output wire        o_done,
    output wire        o_fault,
    output wire [15:0] o_pa
);
    localparam [1:0]  S_IDLE = 2'd0;
    localparam [1:0]  S_WALK = 2'd1;
    localparam [1:0]  S_DONE = 2'd2;
    localparam [15:0] LAST_LVL = 16'd3;

    reg [1:0]  state   = S_IDLE;
    reg [15:0] lvl     = 16'd0;
    reg [15:0] reads   = 16'd0;
    reg [15:0] desc    = 16'd0;
    reg [15:0] va      = 16'd0;
    reg [15:0] walk_id = 16'd0;
    reg        fault   = 1'b0;
    reg        armed   = 1'b0;
    reg        pv      = 1'b0;

    wire [3:0] idx = (lvl == 16'd0) ? va[15:12] :
                     (lvl == 16'd1) ? va[11:8]  :
                     (lvl == 16'd2) ? va[7:4]   : va[3:0];

    assign o_mem_req  = (state == S_WALK);
    assign o_mem_addr = {desc[15:4], idx};
    assign o_done     = (state == S_DONE);
    assign o_fault    = fault;
    assign o_pa       = {desc[15:4], va[3:0]};

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE;
            fault <= 1'b0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_start) begin
                        state   <= S_WALK;
                        lvl     <= 16'd0;
                        reads   <= 16'd0;
                        desc    <= i_root;
                        va      <= i_va;
                        walk_id <= walk_id + 16'd1;
                        fault   <= 1'b0;
                        armed   <= 1'b1;
                    end
                end
                S_WALK: begin
                    if (i_mem_valid) begin
                        reads <= reads + 16'd1;
                        desc  <= i_mem_data;
                        if (!i_mem_data[0] || (!i_mem_data[1] && lvl == LAST_LVL)) begin
                            fault <= 1'b1;
                            state <= S_DONE;
                        end else if (i_mem_data[1]) begin
                            state <= S_DONE;
                        end else begin
                            lvl <= lvl + 16'd1;
                        end
                    end
                end
                S_DONE: begin
                    if (i_ack) state <= S_IDLE;
                end
                default: state <= S_IDLE;
            endcase
        end
    end

    always @(posedge clk)
        if (armed && pv && $stable(walk_id) && $past(reads) >= 16'd4)
            assert ($stable(reads));
endmodule

module lza_normalizer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_ld,
    input  wire [31:0] i_a,
    input  wire [31:0] i_b,
    output reg  [31:0] o_sum,
    output wire        o_done
);
    function [31:0] clz32;
        input [31:0] v;
        integer i;
        reg found;
        begin
            clz32 = 32'd32;
            found = 1'b0;
            for (i = 31; i >= 0; i = i - 1) begin
                if (!found && v[i]) begin
                    clz32 = 31 - i;
                    found = 1'b1;
                end
            end
        end
    endfunction

    reg [31:0] ind = 32'd0;
    reg [31:0] rem = 32'd32;
    initial o_sum = 32'd0;

    wire [31:0] t_str = i_a ^ i_b;
    wire [31:0] g_str = i_a & i_b;
    wire [31:0] f_new = t_str | g_str;

    wire [31:0] lz_of_ind = clz32(ind);
    wire busy = (rem != 32'd0) && (rem != 32'd32);

    assign o_done = (rem == 32'd0);

    always @(posedge clk) begin
        if (rst) begin
            ind   <= 32'd0;
            rem   <= 32'd32;
            o_sum <= 32'd0;
        end else if (i_ce) begin
            if (i_ld) begin
                ind   <= f_new;
                rem   <= clz32(f_new);
                o_sum <= i_a + i_b;
            end else if (busy) begin
                ind   <= ind << 1;
                rem   <= rem - 32'd1;
                o_sum <= o_sum << 1;
            end
        end
    end

    always @(posedge clk)
        if (o_done) assert (ind[31]);
endmodule

module bfi_chain (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_load,
    input wire i_abort,
    input wire [63:0] i_dest,
    input wire [63:0] i_field,
    input wire [5:0] i_off,
    input wire [6:0] i_len,
    output wire [63:0] o_result,
    output wire o_done
);
    reg [1:0] phase = 2'd0;
    reg [63:0] dest = 64'd0;
    reg [63:0] field = 64'd0;
    reg [63:0] shifted = 64'd0;
    reg [63:0] mask = 64'd0;
    reg [63:0] result = 64'd0;
    reg [5:0] off = 6'd0;
    reg [6:0] len = 7'd0;
    reg armed_seen = 1'b0;
    reg start_seen = 1'b0;
    reg done_seen = 1'b0;
    reg pre_r = 1'b1;

    wire [63:0] lowmask = (len >= 7'd64) ? {64{1'b1}} : ((64'd1 << len) - 64'd1);

    always @(posedge clk) begin
        if (i_reset) begin
            phase <= 2'd0;
            armed_seen <= 1'b0;
            start_seen <= 1'b0;
            done_seen <= 1'b0;
        end else if (i_ce) begin
            if (i_abort && (phase != 2'd0)) begin
                phase <= 2'd0;
                pre_r <= 1'b0;
            end else begin
                case (phase)
                    2'd0: if (i_load) begin
                        dest <= i_dest;
                        field <= i_field;
                        off <= i_off;
                        len <= (i_len > 7'd64) ? 7'd64 : i_len;
                        phase <= 2'd1;
                        armed_seen <= 1'b1;
                    end
                    2'd1: begin
                        shifted <= field << off;
                        mask <= lowmask << off;
                        phase <= 2'd2;
                        start_seen <= 1'b1;
                    end
                    2'd2: begin
                        result <= (dest & ~mask) | (shifted & mask);
                        phase <= 2'd3;
                        done_seen <= 1'b1;
                    end
                    default: phase <= 2'd0;
                endcase
            end
        end
    end

    assign o_result = result;
    assign o_done = (phase == 2'd3);

    always @(posedge clk)
        if (pre_r) assert (!done_seen || (start_seen && armed_seen));
endmodule

module block_parity_tally (
    input  wire        clk,
    input  wire        ce,
    input  wire        start,
    input  wire        stop,
    input  wire [15:0] din,
    output reg         par_q,
    output reg  [15:0] word_cnt,
    output reg  [15:0] odd_cnt,
    output reg         win
);
    // XOR parity tree: 16 -> 8 -> 4 -> 2 -> 1
    wire [7:0] l1;
    wire [3:0] l2;
    wire [1:0] l3;
    wire       par;
    assign l1[0] = din[0]  ^ din[1];
    assign l1[1] = din[2]  ^ din[3];
    assign l1[2] = din[4]  ^ din[5];
    assign l1[3] = din[6]  ^ din[7];
    assign l1[4] = din[8]  ^ din[9];
    assign l1[5] = din[10] ^ din[11];
    assign l1[6] = din[12] ^ din[13];
    assign l1[7] = din[14] ^ din[15];
    assign l2[0] = l1[0] ^ l1[1];
    assign l2[1] = l1[2] ^ l1[3];
    assign l2[2] = l1[4] ^ l1[5];
    assign l2[3] = l1[6] ^ l1[7];
    assign l3[0] = l2[0] ^ l2[1];
    assign l3[1] = l2[2] ^ l2[3];
    assign par   = l3[0] ^ l3[1];

    // 8-entry block buffer with per-word parity
    reg [15:0] mem  [0:7];
    reg        mpar [0:7];
    integer i;
    initial begin
        par_q    = 1'b0;
        word_cnt = 16'd0;
        odd_cnt  = 16'd0;
        win      = 1'b0;
        for (i = 0; i < 8; i = i + 1) begin
            mem[i]  = 16'd0;
            mpar[i] = 1'b0;
        end
    end

    always @(posedge clk) begin
        if (ce) begin
            par_q <= par;  // optional output register of the tree
            if (start) begin
                win      <= 1'b1;
                word_cnt <= 16'd0;
                odd_cnt  <= 16'd0;
            end else if (win) begin
                if (stop) begin
                    win <= 1'b0;
                end else if (word_cnt < 16'd8) begin
                    mem[word_cnt[2:0]]  <= din;
                    mpar[word_cnt[2:0]] <= par;
                    word_cnt <= word_cnt + 16'd1;
                    if (par) odd_cnt <= odd_cnt + 16'd1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // after start until stop: at most 8 odd-parity words are tallied
    always @(posedge clk)
        if (pv && $past(win))
            assert ($past(odd_cnt) <= 16'd8);
endmodule

module stream_demux16 (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        in_valid,
    input  wire [3:0]  in_sel,
    input  wire [31:0] in_data,
    output wire        in_ready,
    output wire [15:0] out_valid,
    input  wire [15:0] out_ready,
    output wire [31:0] out_data
);
    reg [3:0]  sel_q   = 4'd0;
    reg [15:0] vld_q   = 16'd0;
    reg [31:0] data_q  = 32'd0;
    reg [31:0] acc_cnt = 32'd0;
    reg [31:0] dlv_cnt = 32'd0;
    reg        armed   = 1'b0;

    wire deliver = i_ce && vld_q[sel_q] && out_ready[sel_q];
    assign in_ready = (vld_q == 16'd0) || (vld_q[sel_q] && out_ready[sel_q]);
    wire accept  = i_ce && in_valid && in_ready;

    always @(posedge clk) begin
        if (rst) begin
            sel_q   <= 4'd0;
            vld_q   <= 16'd0;
            data_q  <= 32'd0;
            acc_cnt <= 32'd0;
            dlv_cnt <= 32'd0;
        end else if (i_ce) begin
            if (deliver) begin
                vld_q   <= 16'd0;
                dlv_cnt <= dlv_cnt + 32'd1;
            end
            if (accept) begin
                sel_q   <= in_sel;
                data_q  <= in_data;
                vld_q   <= (16'd1 << in_sel);
                acc_cnt <= acc_cnt + 32'd1;
                armed   <= 1'b1;
            end
        end
    end

    assign out_valid = vld_q;
    assign out_data  = data_q;

    assert property (!armed || ((acc_cnt - dlv_cnt) <= 32'd1));
endmodule

module jk_bounded_resp (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    output reg         busy,
    output reg  [63:0] work,
    output reg  [63:0] timer
);
    localparam [63:0] LEN = 64'd12;

    initial busy  = 1'b0;
    initial work  = 64'd0;
    initial timer = 64'd0;

    // JK latch inputs: J accepts a request, K signals completion
    wire j = start && !busy;
    wire k = busy && (work == 64'd0);

    always @(posedge clk) begin
        if (rst) begin
            busy  <= 1'b0;
            work  <= 64'd0;
            timer <= 64'd0;
        end else if (ce) begin
            // gated JK latch: set / reset / invert while enabled, hold otherwise
            case ({j, k})
                2'b10:   busy <= 1'b1;
                2'b01:   busy <= 1'b0;
                2'b11:   busy <= ~busy;
                default: busy <= busy;
            endcase
            if (j) begin
                work  <= LEN;
                timer <= LEN + 64'd1;
            end else if (busy) begin
                if (work != 64'd0)
                    work <= work - 64'd1;
                timer <= timer - 64'd1;
            end
        end
    end

    // bounded response: countdown never expires while request outstanding
    always @(posedge clk)
        assert (!(busy && timer == 64'd0));
endmodule

module chipkill_decoder (
    input wire clk,
    input wire i_ce,
    input wire i_scrub,
    input wire [31:0] i_data,
    input wire [31:0] i_chk,
    output wire [31:0] o_data,
    output wire o_uncorr,
    output wire o_fail_valid,
    output wire [1:0] o_fail_id
);
    reg [31:0] syn;
    reg [31:0] dat;
    reg [3:0] fail_oh;
    reg [1:0] fail_id;
    reg fail_valid;
    reg uncorr;
    reg armed;
    initial begin
        syn = 32'h0; dat = 32'h0; fail_oh = 4'd0; fail_id = 2'd0;
        fail_valid = 1'b0; uncorr = 1'b0; armed = 1'b0;
    end

    wire [31:0] s = i_data ^ i_chk;
    wire e0 = |s[7:0];
    wire e1 = |s[15:8];
    wire e2 = |s[23:16];
    wire e3 = |s[31:24];
    wire [2:0] nerr = {2'b00, e0} + {2'b00, e1} + {2'b00, e2} + {2'b00, e3};
    wire [1:0] c = e3 ? 2'd3 : (e2 ? 2'd2 : (e1 ? 2'd1 : 2'd0));
    wire any_err = (nerr != 3'd0);
    wire mark = !fail_valid && (nerr == 3'd1);
    wire bad = (nerr > 3'd1) || (fail_valid && (nerr == 3'd1) && (c != fail_id));

    always @(posedge clk) begin
        if (i_scrub) begin
            syn <= 32'h0;
            fail_oh <= 4'd0;
            fail_id <= 2'd0;
            fail_valid <= 1'b0;
            uncorr <= 1'b0;
        end else if (i_ce) begin
            syn <= s;
            dat <= i_data;
            if (any_err) armed <= 1'b1;
            if (mark) begin
                fail_valid <= 1'b1;
                fail_id <= c;
                fail_oh <= fail_oh | (4'd1 << c);
            end
            if (bad) uncorr <= 1'b1;
        end
    end

    wire [31:0] chip_mask = fail_valid ? (32'h000000FF << {fail_id, 3'b000}) : 32'h0;
    assign o_data = dat ^ (syn & chip_mask);
    assign o_uncorr = uncorr;
    assign o_fail_valid = fail_valid;
    assign o_fail_id = fail_id;

    always @(posedge clk)
        if (armed)
            assert ((fail_oh & (fail_oh - 4'd1)) == 4'd0);
endmodule

module conv_interleaver (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_resync,
    input  wire [7:0] i_sym,
    output reg  [7:0] o_sym,
    output wire       o_fin
);
    // commutator branch counter and revolution counter
    reg [7:0] br  = 8'd0;
    reg [7:0] rev = 8'd0;
    // chain FSM: 0 IDLE, 1 ARMED (first symbol), 2 STARTED (first wrap), 3 FINISHED (second wrap)
    reg [1:0] phase = 2'd0;
    // scope latch: high until the first resync event
    reg before_r = 1'b1;
    reg pv = 1'b0;
    // per-branch delay memories: branch k delays by k symbols
    reg [7:0] d1_0 = 8'd0;
    reg [7:0] d2_0 = 8'd0, d2_1 = 8'd0;
    reg [7:0] d3_0 = 8'd0, d3_1 = 8'd0, d3_2 = 8'd0;
    initial o_sym = 8'd0;

    wire wrap = (br == 8'd3);
    wire fin  = (phase == 2'd3);
    assign o_fin = fin;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_resync) begin
            br       <= 8'd0;
            rev      <= 8'd0;
            phase    <= 2'd0;
            before_r <= 1'b0;
        end else if (i_ce) begin
            br <= wrap ? 8'd0 : br + 8'd1;
            if (wrap && rev != 8'd3) rev <= rev + 8'd1;
            case (phase)
                2'd0:    phase <= 2'd1;
                2'd1:    if (wrap) phase <= 2'd2;
                2'd2:    if (wrap) phase <= 2'd3;
                default: phase <= 2'd3;
            endcase
            case (br)
                8'd0: o_sym <= i_sym;
                8'd1: begin o_sym <= d1_0; d1_0 <= i_sym; end
                8'd2: begin o_sym <= d2_1; d2_1 <= d2_0; d2_0 <= i_sym; end
                default: begin o_sym <= d3_2; d3_2 <= d3_1; d3_1 <= d3_0; d3_0 <= i_sym; end
            endcase
        end
    end

    // finish may only be observed after arm and start: exactly two revolutions done
    always @(posedge clk)
        if (pv && before_r && $rose(fin))
            assert (rev == 8'd2);
endmodule

module misr_lockstep (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire        stop,
    input  wire [63:0] din,
    output wire [63:0] signature,
    output wire        armed_o
);
    localparam [63:0] POLY = 64'h000000000000001B;
    localparam [63:0] SEED = 64'h0123456789ABCDEF;

    // Lane A holds the signature in true form, lane B in complemented form
    reg [63:0] sig_a;
    reg [63:0] sig_b;
    reg        armed;

    initial sig_a = SEED;
    initial sig_b = ~SEED;
    initial armed = 1'b0;

    function [63:0] misr_step;
        input [63:0] s;
        input [63:0] d;
        begin
            misr_step = {s[62:0], 1'b0} ^ (s[63] ? POLY : 64'd0) ^ d;
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            sig_a <= SEED;
            sig_b <= ~SEED;
            armed <= 1'b0;
        end else if (start) begin
            sig_a <= SEED;
            sig_b <= ~SEED;
            armed <= 1'b1;
        end else begin
            if (stop)
                armed <= 1'b0;
            if (ce) begin
                sig_a <= misr_step(sig_a, din);
                sig_b <= ~misr_step(~sig_b, din);
            end
        end
    end

    assign signature = sig_a;
    assign armed_o   = armed;

    // After a capture starts, until it is stopped, the lockstep lanes agree on the low byte
    always @(*) assert (!armed || (sig_a[7:0] == ~sig_b[7:0]));
endmodule

module mcycle_epoch (
    input  wire        clk,
    input  wire        i_ce,
    output wire [63:0] o_cycle,
    output wire [63:0] o_epoch
);
    // 64-bit synchronous binary up counter (cycle CSR style) with a
    // pipelined lookahead carry out of the low 32-bit half that drives
    // an epoch counter tracking high-half advances.
    reg [63:0] cnt;
    reg        carry_q;
    reg [63:0] epoch;
    reg        armed;
    reg        pv;
    initial cnt     = 64'd0;
    initial carry_q = 1'b0;
    initial epoch   = 64'd0;
    initial armed   = 1'b0;
    initial pv      = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            cnt     <= cnt + 64'd1;
            carry_q <= (cnt[31:0] == 32'hFFFFFFFE);
            if (carry_q)
                epoch <= epoch + 64'd1;
            armed   <= 1'b1;
        end
    end

    assign o_cycle = cnt;
    assign o_epoch = epoch;

    // after the first enabled cycle: if the high half of the counter did
    // not change, the epoch counter must not have changed either
    always @(posedge clk)
        if (pv && armed && $stable(cnt[63:32]))
            assert ($stable(epoch));
endmodule

module snoop_dup_tag_cache (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_fill,
    input  wire [31:0]  i_fill_addr,
    input  wire [127:0] i_fill_data,
    input  wire         i_snoop,
    input  wire [31:0]  i_snp_addr,
    input  wire         i_flush,
    input  wire [31:0]  i_cpu_addr,
    output reg          o_snp_valid,
    output reg  [127:0] o_snp_data,
    output wire         o_snp_hit,
    output wire         o_cpu_hit
);
    localparam TW = 24;

    reg [15:0]       valid     = 16'h0000;
    reg [16*TW-1:0]  tags      = {(16*TW){1'b0}};
    reg [2047:0]     data      = {2048{1'b0}};
    reg [15:0]       dup_valid = 16'h0000;
    reg [16*TW-1:0]  dup_tags  = {(16*TW){1'b0}};
    reg              snp_pend  = 1'b0;
    reg [3:0]        snp_idx   = 4'd0;
    reg              ever_filled = 1'b0;
    reg              armed     = 1'b1;
    initial o_snp_valid = 1'b0;
    initial o_snp_data  = 128'd0;

    wire [3:0]    f_idx = i_fill_addr[7:4];
    wire [TW-1:0] f_tag = i_fill_addr[31:8];
    wire [3:0]    s_idx = i_snp_addr[7:4];
    wire [TW-1:0] s_tag = i_snp_addr[31:8];
    wire [3:0]    c_idx = i_cpu_addr[7:4];
    wire [TW-1:0] c_tag = i_cpu_addr[31:8];

    wire dup_hit = dup_valid[s_idx] && (dup_tags[s_idx*TW +: TW] == s_tag);
    assign o_snp_hit = i_ce && !snp_pend && !i_fill && !i_flush && i_snoop && dup_hit;
    assign o_cpu_hit = valid[c_idx] && (tags[c_idx*TW +: TW] == c_tag);

    always @(posedge clk) begin
        if (i_ce) begin
            o_snp_valid <= 1'b0;
            if (snp_pend) begin
                valid[snp_idx]     <= 1'b0;
                dup_valid[snp_idx] <= 1'b0;
                o_snp_data  <= data[snp_idx*128 +: 128];
                o_snp_valid <= 1'b1;
                snp_pend    <= 1'b0;
            end else if (i_fill) begin
                valid[f_idx]     <= 1'b1;
                dup_valid[f_idx] <= 1'b1;
                tags[f_idx*TW +: TW]     <= f_tag;
                dup_tags[f_idx*TW +: TW] <= f_tag;
                data[f_idx*128 +: 128]   <= i_fill_data;
                ever_filled <= 1'b1;
            end else if (i_flush) begin
                valid     <= 16'h0000;
                dup_valid <= 16'h0000;
                armed     <= 1'b0;
            end else if (o_snp_hit) begin
                snp_pend <= 1'b1;
                snp_idx  <= s_idx;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed)
            assert (!$past(o_snp_hit) || $past(ever_filled));
endmodule

module vcpu_minmax_seq (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        open,
    input  wire        close,
    input  wire        arm,
    input  wire [15:0] a,
    input  wire [15:0] b,
    output reg  [15:0] min_out,
    output reg  [15:0] max_out,
    output reg         rdy
);
    localparam [1:0] S_IDLE     = 2'd0;
    localparam [1:0] S_ARMED    = 2'd1;
    localparam [1:0] S_STARTED  = 2'd2;
    localparam [1:0] S_FINISHED = 2'd3;

    reg [1:0]  st;
    reg        win, f_arm, f_start, f_done;
    reg [15:0] a_q, b_q, lo_q, hi_q;

    initial begin
        st = S_IDLE; win = 1'b0; f_arm = 1'b0; f_start = 1'b0; f_done = 1'b0;
        a_q = 16'd0; b_q = 16'd0; lo_q = 16'd0; hi_q = 16'd0;
        min_out = 16'd0; max_out = 16'd0; rdy = 1'b0;
    end

    // single magnitude decision drives both selections
    wire a_lt_b = (a_q < b_q);

    always @(posedge clk) begin
        if (rst) begin
            st <= S_IDLE; win <= 1'b0; f_arm <= 1'b0; f_start <= 1'b0; f_done <= 1'b0;
            a_q <= 16'd0; b_q <= 16'd0; lo_q <= 16'd0; hi_q <= 16'd0;
            min_out <= 16'd0; max_out <= 16'd0; rdy <= 1'b0;
        end else if (ce) begin
            rdy <= 1'b0;
            if (open && !win && st == S_IDLE) begin
                win     <= 1'b1;
                f_arm   <= 1'b0;
                f_start <= 1'b0;
                f_done  <= 1'b0;
            end else if (close) begin
                win <= 1'b0;
            end
            case (st)
                S_IDLE: if (arm) begin
                    a_q   <= a;
                    b_q   <= b;
                    f_arm <= 1'b1;
                    st    <= S_ARMED;
                end
                S_ARMED: begin
                    lo_q    <= a_lt_b ? a_q : b_q;
                    hi_q    <= a_lt_b ? b_q : a_q;
                    f_start <= 1'b1;
                    st      <= S_STARTED;
                end
                S_STARTED: begin
                    min_out <= lo_q;
                    max_out <= hi_q;
                    rdy     <= 1'b1;
                    f_done  <= 1'b1;
                    st      <= S_FINISHED;
                end
                default: st <= S_IDLE;
            endcase
        end
    end

    // after open until close: a finish is never seen without start and arm before it
    always @(*) assert (!(win && f_done) || (f_start && f_arm));
endmodule

module meta_sync_burst (
    input  wire        clk,
    input  wire        ce,
    input  wire [31:0] async_main,
    input  wire [31:0] async_shadow,
    input  wire        win_open,
    input  wire        win_close,
    output wire [31:0] sync_q,
    output wire        meta_err
);
    reg [31:0] main_q   = 32'd0;
    reg [31:0] shadow_q = 32'd0;
    reg        err_flag = 1'b0;
    reg        win      = 1'b0;
    reg [31:0] burst    = 32'd0;
    reg [31:0] budget   = 32'd16;

    assign sync_q   = main_q;
    assign meta_err = err_flag;

    always @(posedge clk) begin
        if (ce) begin
            main_q   <= async_main;
            shadow_q <= async_shadow;
            err_flag <= (main_q != shadow_q);
        end
    end

    always @(posedge clk) begin
        if (ce) begin
            if (win_open) begin
                win    <= 1'b1;
                burst  <= 32'd0;
                budget <= 32'd16;
            end else if (win_close) begin
                win <= 1'b0;
            end else if (win && err_flag && (budget != 32'd0)) begin
                burst  <= burst + 32'd1;
                budget <= budget - 32'd1;
            end
        end
    end

    always @(posedge clk)
        assert (!win || burst <= 32'd16);
endmodule

module tb_drv_demux (
    input  wire         clk,
    input  wire         i_reset,
    input  wire         i_ce,
    input  wire         i_req,
    input  wire [3:0]   i_sel,
    input  wire [15:0]  i_data,
    output wire [255:0] o_bus,
    output wire         o_busy
);
    localparam [15:0] K = 16'd8;

    reg [3:0]   sel_r;
    reg [15:0]  data_r;
    reg [255:0] out_q;
    reg         pending;
    reg [15:0]  cnt;
    reg [15:0]  ph;

    initial sel_r   = 4'd0;
    initial data_r  = 16'd0;
    initial out_q   = 256'd0;
    initial pending = 1'b0;
    initial cnt     = 16'd0;
    initial ph      = 16'd0;

    always @(posedge clk) begin
        if (i_reset) begin
            sel_r   <= 4'd0;
            data_r  <= 16'd0;
            out_q   <= 256'd0;
            pending <= 1'b0;
            cnt     <= 16'd0;
            ph      <= 16'd0;
        end else if (i_ce) begin
            if (!pending) begin
                if (i_req) begin
                    pending <= 1'b1;
                    sel_r   <= i_sel;
                    data_r  <= i_data;
                    cnt     <= K;
                    ph      <= 16'd0;
                end
            end else begin
                if (ph == K - 16'd1) begin
                    out_q[sel_r*16 +: 16] <= data_r;
                    pending <= 1'b0;
                    cnt     <= 16'd0;
                    ph      <= 16'd0;
                end else begin
                    ph  <= ph + 16'd1;
                    cnt <= cnt - 16'd1;
                end
            end
        end
    end

    assign o_bus  = out_q;
    assign o_busy = pending;

    assert property (!pending || cnt != 16'd0);
endmodule

module vend_ctrl (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       coin_valid,
    input  wire [7:0] coin_val,
    input  wire       select,
    input  wire       cancel,
    output wire       vend,
    output wire       change_ret,
    output wire [7:0] change_out
);
    localparam [1:0] S_IDLE    = 2'd0;
    localparam [1:0] S_COLLECT = 2'd1;
    localparam [1:0] S_VEND    = 2'd2;
    localparam [1:0] S_CHANGE  = 2'd3;
    localparam [7:0] PRICE     = 8'd75;

    reg [1:0] state;
    reg [7:0] credit;
    reg [7:0] change_amt;
    reg       vend_r;
    reg       chg_r;
    reg       pv;
    initial begin
        state = S_IDLE; credit = 8'd0; change_amt = 8'd0;
        vend_r = 1'b0; chg_r = 1'b0; pv = 1'b0;
    end

    wire [8:0] sum     = {1'b0, credit} + {1'b0, coin_val};
    wire [7:0] sat_sum = sum[8] ? 8'd255 : sum[7:0];

    assign vend       = vend_r;
    assign change_ret = chg_r;
    assign change_out = change_amt;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; credit <= 8'd0; change_amt <= 8'd0;
            vend_r <= 1'b0; chg_r <= 1'b0;
        end else if (ce) begin
            case (state)
                S_IDLE: begin
                    if (coin_valid) begin
                        credit <= sat_sum;
                        state  <= S_COLLECT;
                    end
                end
                S_COLLECT: begin
                    if (select && credit >= PRICE) begin
                        credit <= credit - PRICE;
                        state  <= S_VEND;
                        vend_r <= 1'b1;
                    end else if (cancel) begin
                        change_amt <= credit;
                        credit     <= 8'd0;
                        state      <= S_CHANGE;
                        chg_r      <= 1'b1;
                    end else if (coin_valid) begin
                        credit <= sat_sum;
                    end
                end
                S_VEND: begin
                    vend_r <= 1'b0;
                    if (credit != 8'd0) begin
                        change_amt <= credit;
                        credit     <= 8'd0;
                        state      <= S_CHANGE;
                        chg_r      <= 1'b1;
                    end else begin
                        state <= S_IDLE;
                    end
                end
                S_CHANGE: begin
                    chg_r      <= 1'b0;
                    change_amt <= 8'd0;
                    state      <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (pv && $rose(vend_r))
            assert (!chg_r);
endmodule

module polyphase_resampler (
    input  wire         clk,
    input  wire         ce,
    input  wire         in_valid,
    input  wire [127:0] in_data,
    output reg  [127:0] out_data,
    output reg          out_valid
);
    localparam [1:0] S_IDLE   = 2'd0;
    localparam [1:0] S_PRIMED = 2'd1;
    localparam [1:0] S_RUN    = 2'd2;
    localparam [1:0] S_DONE   = 2'd3;

    reg [127:0] hist [0:23];
    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) hist[i] = 128'd0;
    end

    reg [4:0] fill        = 5'd0;
    reg [4:0] phase       = 5'd0;
    reg [3:0] out_cnt     = 4'd0;
    reg [1:0] st          = S_IDLE;
    reg       q_seen      = 1'b0;
    reg       armed_seen  = 1'b0;
    reg       start_seen  = 1'b0;
    reg       finish_seen = 1'b0;
    initial out_data  = 128'd0;
    initial out_valid = 1'b0;

    wire [5:0] phase_sum = {1'b0, phase} + 6'd7;
    wire       wrap      = (phase_sum >= 6'd24);
    wire [4:0] phase_nxt = wrap ? (phase_sum[4:0] - 5'd24) : phase_sum[4:0];
    wire [4:0] tap       = 5'd23 - phase;

    always @(posedge clk) begin
        if (ce) begin
            if (in_valid) begin
                for (i = 23; i > 0; i = i - 1) hist[i] <= hist[i-1];
                hist[0] <= in_data;
                if (fill != 5'd24) fill <= fill + 5'd1;
                q_seen <= 1'b1;
            end
            phase     <= phase_nxt;
            out_valid <= 1'b0;
            case (st)
                S_IDLE: begin
                    if (fill == 5'd24) begin
                        st         <= S_PRIMED;
                        armed_seen <= 1'b1;
                    end
                end
                S_PRIMED: begin
                    if (wrap) begin
                        st         <= S_RUN;
                        start_seen <= 1'b1;
                        out_cnt    <= 4'd0;
                    end
                end
                S_RUN: begin
                    out_data  <= hist[phase] + hist[tap];
                    out_valid <= 1'b1;
                    if (out_cnt == 4'd11) begin
                        st          <= S_DONE;
                        finish_seen <= 1'b1;
                        out_cnt     <= 4'd0;
                    end else begin
                        out_cnt <= out_cnt + 4'd1;
                    end
                end
                S_DONE: begin
                    if (wrap) st <= S_RUN;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (q_seen && finish_seen)
            assert (start_seen && armed_seen);
endmodule

module prbs_win_checker (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_bit,
    input  wire        i_arm,
    input  wire        i_disarm,
    output wire        o_sync,
    output wire [63:0] o_errs
);
    localparam [63:0] SYNC_LEN = 64'd8;
    localparam [63:0] LOSS_LEN = 64'd4;
    localparam [63:0] MAXV     = 64'hFFFFFFFFFFFFFFFF;

    reg [63:0] ref_sr;
    reg        sync;
    reg [63:0] match_run;
    reg [63:0] bad_run;
    reg [63:0] err_cnt;
    reg        win;
    reg [63:0] err_snap;
    reg [63:0] win_errs;

    initial ref_sr    = 64'h1;
    initial sync      = 1'b0;
    initial match_run = 64'd0;
    initial bad_run   = 64'd0;
    initial err_cnt   = 64'd0;
    initial win       = 1'b0;
    initial err_snap  = 64'd0;
    initial win_errs  = 64'd0;

    // PRBS x^64 + x^63 + x^61 + x^60 + 1 prediction
    wire        pred    = ref_sr[63] ^ ref_sr[62] ^ ref_sr[60] ^ ref_sr[59];
    wire        mism    = sync && (i_bit != pred);
    wire        cnt_inc = mism && (err_cnt != MAXV);
    wire [63:0] err_nxt = cnt_inc ? (err_cnt + 64'd1) : err_cnt;
    wire        lose    = mism && ((bad_run + 64'd1) >= LOSS_LEN);
    wire        open_w  = i_arm && sync && !lose && !i_disarm;
    wire        close_w = i_disarm || lose;

    always @(posedge clk) begin
        if (i_reset) begin
            ref_sr    <= 64'h1;
            sync      <= 1'b0;
            match_run <= 64'd0;
            bad_run   <= 64'd0;
            err_cnt   <= 64'd0;
            win       <= 1'b0;
            err_snap  <= 64'd0;
            win_errs  <= 64'd0;
        end else if (i_ce) begin
            err_cnt <= err_nxt;
            if (!sync) begin
                // self-synchronising: load incoming stream into reference
                ref_sr  <= {ref_sr[62:0], i_bit};
                bad_run <= 64'd0;
                if (i_bit == pred) begin
                    if ((match_run + 64'd1) >= SYNC_LEN) begin
                        sync      <= 1'b1;
                        match_run <= 64'd0;
                    end else begin
                        match_run <= match_run + 64'd1;
                    end
                end else begin
                    match_run <= 64'd0;
                end
            end else begin
                // locked: free-run the local reference
                ref_sr    <= {ref_sr[62:0], pred};
                match_run <= 64'd0;
                if (mism) begin
                    if (lose) begin
                        sync    <= 1'b0;
                        bad_run <= 64'd0;
                    end else begin
                        bad_run <= bad_run + 64'd1;
                    end
                end else begin
                    bad_run <= 64'd0;
                end
            end
            // measurement window: opened by arm while locked, closed by disarm or sync loss
            if (win) begin
                if (close_w) win <= 1'b0;
                if (cnt_inc) win_errs <= win_errs + 64'd1;
            end else if (open_w) begin
                win      <= 1'b1;
                err_snap <= err_nxt;
                win_errs <= 64'd0;
            end
        end
    end

    assign o_sync = sync;
    assign o_errs = err_cnt;

    // Precedence inside the window: a nonzero window tally requires the global
    // counter to have advanced past the snapshot recorded when the window opened.
    always @(*)
        if (win && (win_errs != 64'd0))
            assert (err_cnt != err_snap);

    // With no window errors, the global counter must still equal the snapshot.
    always @(*)
        if (win && (win_errs == 64'd0))
            assert (err_cnt == err_snap);
endmodule

module fft_tdm_bus (
    input  wire        clk,
    input  wire        step,
    input  wire        wr_en,
    input  wire [2:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire [31:0] bus
);
    // 8-entry butterfly result store, time-shared onto one tri-state bus
    reg [31:0] mem [0:7];
    reg [31:0] phase = 32'd0;   // time-share slot counter
    reg [7:0]  oe    = 8'h01;   // one-hot slot output enable
    reg        armed = 1'b0;    // sticky: first bus drive by slot 0 has happened
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            mem[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (wr_en)
            mem[wr_addr] <= wr_data;
        if (step) begin
            oe <= {oe[6:0], oe[7]};
            if (oe[7])
                phase <= 32'd0;
            else
                phase <= phase + 32'd1;
            if (oe[0])
                armed <= 1'b1;
        end
    end

    // tri-state buffer: drive the selected butterfly word only while stepping
    assign bus = step ? mem[phase[2:0]] : 32'bz;

    always @(posedge clk)
        if (armed) assert (phase <= 32'd7);
endmodule

module rms_power_meter (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_start,
    input wire [2:0] i_shift,
    input wire [31:0] i_sample,
    output wire o_busy,
    output wire o_valid,
    output wire [63:0] o_mean_sq
);
    reg busy;
    reg valid;
    reg [2:0] shift_r;
    reg [63:0] win_len, win_cnt, countdown, acc, result;
    reg pv;
    initial begin
        busy = 1'b0; valid = 1'b0; shift_r = 3'd0;
        win_len = 64'd1; win_cnt = 64'd0; countdown = 64'd0;
        acc = 64'd0; result = 64'd0; pv = 1'b0;
    end

    wire [63:0] sq = {32'd0, i_sample} * {32'd0, i_sample};
    wire [63:0] acc_nxt = acc + sq;
    wire last = (win_cnt + 64'd1 == win_len);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0; valid <= 1'b0; shift_r <= 3'd0;
            win_len <= 64'd1; win_cnt <= 64'd0; countdown <= 64'd0;
            acc <= 64'd0; result <= 64'd0;
        end else if (i_ce) begin
            valid <= 1'b0;
            if (!busy) begin
                if (i_start) begin
                    busy <= 1'b1;
                    shift_r <= i_shift;
                    win_len <= 64'd1 << i_shift;
                    countdown <= 64'd1 << i_shift;
                    win_cnt <= 64'd0;
                    acc <= 64'd0;
                end
            end else begin
                acc <= acc_nxt;
                win_cnt <= win_cnt + 64'd1;
                countdown <= countdown - 64'd1;
                if (last) begin
                    busy <= 1'b0;
                    result <= acc_nxt >> shift_r;
                    valid <= 1'b1;
                end
            end
        end
    end

    assign o_busy = busy;
    assign o_valid = valid;
    assign o_mean_sq = result;

    // after a measurement request is accepted (busy set) until the window completes:
    // the deadline countdown never expires while the request is outstanding
    always @(posedge clk)
        if (busy)
            assert (countdown != 64'd0);

    // and the window completes exactly when the countdown reaches zero
    always @(posedge clk)
        if (pv && $fell(busy))
            assert (countdown == 64'd0);
endmodule

module forth_rng_word (
    input  wire       clk,
    input  wire       ce,
    input  wire       go,
    output wire [7:0] rnd,
    output reg        busy
);
    reg [7:0] prng;
    reg [7:0] cd;
    reg [7:0] steps;
    initial begin prng = 8'h5A; cd = 8'd0; steps = 8'd0; busy = 1'b0; end

    // 8-bit xorshift (7,5,3)
    wire [7:0] x1 = prng ^ (prng << 7);
    wire [7:0] x2 = x1 ^ (x1 >> 5);
    wire [7:0] x3 = x2 ^ (x2 << 3);

    assign rnd = prng;

    always @(posedge clk) begin
        if (ce) begin
            if (!busy) begin
                if (go) begin
                    busy  <= 1'b1;
                    steps <= 8'd0;
                    cd    <= 8'd8;
                end
            end else begin
                prng <= x3;
                cd   <= cd - 8'd1;
                if (steps == 8'd7)
                    busy <= 1'b0;
                else
                    steps <= steps + 8'd1;
            end
        end
    end

    // countdown never expires while the request is outstanding
    always @(posedge clk)
        if (busy)
            assert (cd != 8'd0);

    // on the final shift round, exactly one tick of budget remains
    always @(posedge clk)
        if (busy && steps == 8'd7)
            assert (cd == 8'd1);
endmodule

module eth_sticky_align (
    input wire clk,
    input wire load,
    input wire shift,
    input wire [31:0] din,
    output wire [31:0] o_mant,
    output wire o_sticky,
    output wire [31:0] o_shamt
);
    localparam [31:0] PREAMBLE = 32'hD5555555;
    localparam [31:0] MAXSH = 32'd32;

    reg [31:0] mant;
    reg sticky;
    reg [31:0] shamt;
    reg [31:0] orig;
    reg armed;
    reg pv;

    initial begin
        mant = PREAMBLE;
        sticky = 1'b0;
        shamt = 32'd0;
        orig = PREAMBLE;
        armed = 1'b1;
        pv = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load) begin
            mant <= din;
            orig <= din;
            sticky <= 1'b0;
            shamt <= 32'd0;
            armed <= 1'b0;
        end else if (shift) begin
            mant <= mant >> 1;
            sticky <= sticky | mant[0];
            if (shamt != MAXSH)
                shamt <= shamt + 32'd1;
        end
    end

    assign o_mant = mant;
    assign o_sticky = sticky;
    assign o_shamt = shamt;

    always @(posedge clk)
        if (pv && armed && $stable(shamt))
            assert ($stable(mant));
endmodule

module usb_route_lookup (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_pkt_valid,
    input wire [31:0] i_dest,
    input wire cfg_we,
    input wire [4:0] cfg_addr,
    input wire [31:0] cfg_data,
    output wire o_done,
    output wire [31:0] o_port
);
    localparam [1:0] P_IDLE = 2'd0, P_ARM = 2'd1, P_START = 2'd2, P_FIN = 2'd3;

    reg [1:0]  phase    = 2'd0;
    reg [31:0] step_cnt = 32'd0;
    reg        fin_q    = 1'b0;
    reg [31:0] dest_q   = 32'd0;
    reg [31:0] port_q   = 32'd0;

    reg [31:0] rt_mem [0:31];
    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1)
            rt_mem[i] = 32'd0;
    end

    // routing table configuration write port
    always @(posedge clk)
        if (!i_reset && i_ce && cfg_we)
            rt_mem[cfg_addr] <= cfg_data;

    // lookup sequencer: arm (capture dest) -> start (table read) -> finish (port valid)
    always @(posedge clk) begin
        if (i_reset) begin
            phase    <= P_IDLE;
            step_cnt <= 32'd0;
            fin_q    <= 1'b0;
            dest_q   <= 32'd0;
            port_q   <= 32'd0;
        end else if (i_ce) begin
            fin_q <= (step_cnt == 32'd2);
            case (phase)
                P_IDLE:  if (i_pkt_valid) begin
                             phase  <= P_ARM;
                             dest_q <= i_dest;
                         end
                P_ARM:   phase <= P_START;
                P_START: begin
                             phase  <= P_FIN;
                             port_q <= rt_mem[dest_q[4:0]];
                         end
                default: phase <= P_IDLE;
            endcase
            case (step_cnt)
                32'd0:   if (i_pkt_valid) step_cnt <= 32'd1;
                32'd3:   step_cnt <= 32'd0;
                default: step_cnt <= step_cnt + 32'd1;
            endcase
        end
    end

    assign o_done = fin_q;
    assign o_port = port_q;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && fin_q)
            assert (($past(phase) == P_START) || ($past(phase) == P_FIN));
endmodule

module mem_stream_reader (
    input  wire        clk,
    input  wire        rst,
    input  wire        start,
    input  wire [31:0] i_len,
    input  wire [31:0] i_psize,
    input  wire        ce,
    input  wire        wr_en,
    input  wire [4:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire        o_valid,
    output wire [31:0] o_data,
    output wire        o_start,
    output wire        o_last
);
    reg [31:0] mem [0:31];
    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1) mem[i] = 32'd0;
    end
    always @(posedge clk)
        if (wr_en) mem[wr_addr] <= wr_data;

    reg [31:0] rd_ptr    = 32'd0;
    reg [31:0] remaining = 32'd0;
    reg [31:0] pkt_size  = 32'd8;
    reg [31:0] beat      = 32'd0;
    reg        busy      = 1'b0;
    reg        in_pkt    = 1'b0;

    wire fire = busy && ce;
    assign o_valid = busy;
    assign o_data  = mem[rd_ptr[4:0]];
    assign o_start = busy && (beat == 32'd0);
    assign o_last  = busy && ((beat == pkt_size - 32'd1) || (remaining == 32'd1));

    wire [31:0] len_c = (i_len > 32'd32) ? 32'd32 : i_len;
    wire [31:0] psz_c = ((i_psize == 32'd0) || (i_psize > 32'd8)) ? 32'd8 : i_psize;

    always @(posedge clk) begin
        if (rst) begin
            rd_ptr    <= 32'd0;
            remaining <= 32'd0;
            pkt_size  <= 32'd8;
            beat      <= 32'd0;
            busy      <= 1'b0;
            in_pkt    <= 1'b0;
        end else if (start && !busy) begin
            rd_ptr    <= 32'd0;
            remaining <= len_c;
            pkt_size  <= psz_c;
            beat      <= 32'd0;
            busy      <= (len_c != 32'd0);
            in_pkt    <= 1'b0;
        end else if (fire) begin
            rd_ptr    <= rd_ptr + 32'd1;
            remaining <= remaining - 32'd1;
            busy      <= (remaining != 32'd1);
            beat      <= o_last ? 32'd0 : beat + 32'd1;
            if (o_last)
                in_pkt <= 1'b0;
            else if (o_start)
                in_pkt <= 1'b1;
        end
    end

    always @(posedge clk)
        if (in_pkt) assert (beat <= 32'd7);
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
    output reg         fault
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
            fault  <= miss_q;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
endmodule

module vrf_lanes (
    input  wire        clk,
    input  wire        ce,
    input  wire        lock,
    input  wire        unlock,
    input  wire        we,
    input  wire [6:0]  waddr,
    input  wire        wsel_alu,
    input  wire [63:0] wdata0,
    input  wire [63:0] wdata1,
    input  wire [6:0]  ra0,
    input  wire [6:0]  rb0,
    input  wire [6:0]  ra1,
    input  wire [6:0]  rb1,
    input  wire        cfg_we,
    input  wire [6:0]  cfg_addr,
    input  wire [1:0]  cfg_ew,
    output wire [63:0] out0,
    output wire [63:0] out1,
    output wire [63:0] o_wr_count
);
    reg [63:0] lane0_mem [0:127];
    reg [63:0] lane1_mem [0:127];
    reg [1:0]  ew_cfg    [0:127];
    reg [63:0] lane0_elems;
    reg [63:0] lane1_elems;
    reg [63:0] wr_count;
    reg        armed;
    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            lane0_mem[i] = 64'd0;
            lane1_mem[i] = 64'd0;
            ew_cfg[i]    = 2'd0;
        end
        lane0_elems = 64'd0;
        lane1_elems = 64'd0;
        wr_count    = 64'd0;
        armed       = 1'b0;
    end

    wire [63:0] alu0 = lane0_mem[ra0] + lane0_mem[rb0];
    wire [63:0] alu1 = lane1_mem[ra1] + lane1_mem[rb1];
    wire [63:0] elems = 64'd1 << ew_cfg[waddr];

    always @(posedge clk) begin
        if (ce) begin
            if (we) begin
                lane0_mem[waddr] <= wsel_alu ? alu0 : wdata0;
                lane1_mem[waddr] <= wsel_alu ? alu1 : wdata1;
                lane0_elems <= lane0_elems + elems;
                lane1_elems <= lane1_elems + elems;
                wr_count    <= wr_count + 64'd1;
            end
            if (cfg_we)
                ew_cfg[cfg_addr] <= cfg_ew;
            if (lock)
                armed <= 1'b1;
            else if (unlock)
                armed <= 1'b0;
        end
    end

    assign out0 = alu0;
    assign out1 = alu1;
    assign o_wr_count = wr_count;

    always @(*) assert (!armed || (lane0_elems == lane1_elems));
endmodule

module brmask_alloc (
    input  wire        clk,
    input  wire        rst,
    input  wire        alloc_req,
    input  wire        clr_req,
    input  wire        kill_req,
    input  wire        disp_valid,
    input  wire [5:0]  res_tag,
    input  wire [7:0]  disp_slot,
    input  wire [7:0]  rd_slot,
    output wire [63:0] o_free_vec,
    output wire [63:0] o_alloc_onehot,
    output wire [63:0] o_rd_mask,
    output wire [63:0] o_live,
    output wire        o_full
);
    reg [63:0] free_vec = ~64'd0;
    reg [63:0] live     = 64'd0;
    reg [63:0] n_free   = 64'd64;
    reg        no_kill  = 1'b1;

    wire [63:0] alloc_oh = free_vec & (~free_vec + 64'd1);
    wire [63:0] res_bit  = 64'd1 << res_tag;

    wire do_alloc = alloc_req && (n_free != 64'd0);
    wire do_clr   = !alloc_req && clr_req && (live != 64'd0) && ((free_vec & res_bit) == 64'd0);
    wire do_kill  = !alloc_req && !clr_req && kill_req && (live != 64'd0) && ((free_vec & res_bit) == 64'd0);
    wire do_disp  = !alloc_req && !clr_req && !kill_req && disp_valid;

    always @(posedge clk) begin
        if (rst) begin
            free_vec <= ~64'd0;
            live     <= 64'd0;
            n_free   <= 64'd64;
        end else if (do_alloc) begin
            free_vec <= free_vec & ~alloc_oh;
            live     <= live + 64'd1;
            n_free   <= n_free - 64'd1;
        end else if (do_clr) begin
            free_vec <= free_vec | res_bit;
            live     <= live - 64'd1;
            n_free   <= n_free + 64'd1;
        end else if (do_kill) begin
            free_vec <= free_vec | res_bit;
            live     <= live - 64'd1;
            n_free   <= n_free + 64'd1;
            no_kill  <= 1'b0;
        end
    end

    wire [256*64-1:0] mask_flat;
    genvar g;
    generate
        for (g = 0; g < 256; g = g + 1) begin : slot
            reg [63:0] m = 64'd0;
            always @(posedge clk) begin
                if (rst)
                    m <= 64'd0;
                else if (do_clr)
                    m <= m & ~res_bit;
                else if (do_kill && ((m & res_bit) != 64'd0))
                    m <= 64'd0;
                else if (do_disp && (disp_slot == g))
                    m <= ~free_vec;
            end
            assign mask_flat[g*64 +: 64] = m;
        end
    endgenerate

    assign o_free_vec     = free_vec;
    assign o_alloc_onehot = alloc_oh;
    assign o_rd_mask      = mask_flat[rd_slot*64 +: 64];
    assign o_live         = live;
    assign o_full         = (n_free == 64'd0);

    assert property (!no_kill || (live <= 64'd64));
endmodule

module dfe_ss_lms (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_mu_wr,
    input  wire [63:0] i_mu,
    input  wire        i_dec,
    input  wire        i_err_sgn,
    output wire [63:0] o_tap0,
    output wire [63:0] o_tap1,
    output wire        o_done
);
    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_ARMED = 2'd1;
    localparam [1:0] P_ADAPT = 2'd2;
    localparam [1:0] P_DONE  = 2'd3;
    localparam [63:0] N_UPD  = 64'd4;

    reg [63:0] coef0 = 64'd0;
    reg [63:0] coef1 = 64'd0;
    reg [63:0] mu = 64'd1;
    reg [63:0] upd_cnt = 64'd0;
    reg [1:0]  hist = 2'b00;
    reg [1:0]  hist_cnt = 2'd0;
    reg [1:0]  phase = P_IDLE;
    reg        arm_seen = 1'b0;
    reg        start_seen = 1'b0;
    reg        q_seen = 1'b0;

    // sign-sign LMS step: +mu when error sign matches decided bit sign, else -mu
    wire [63:0] d0 = (i_err_sgn ^ hist[0]) ? (~mu + 64'd1) : mu;
    wire [63:0] d1 = (i_err_sgn ^ hist[1]) ? (~mu + 64'd1) : mu;

    always @(posedge clk) begin
        if (rst) begin
            coef0 <= 64'd0;
            coef1 <= 64'd0;
            hist <= 2'b00;
            hist_cnt <= 2'd0;
            upd_cnt <= 64'd0;
            phase <= P_IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
        end else if (i_ce) begin
            if (i_mu_wr) begin
                mu <= i_mu;
                q_seen <= 1'b1;
            end
            hist <= {hist[0], i_dec};
            if (hist_cnt != 2'd2)
                hist_cnt <= hist_cnt + 2'd1;
            case (phase)
                P_IDLE: begin
                    if (hist_cnt == 2'd2) begin
                        phase <= P_ARMED;
                        arm_seen <= 1'b1;
                    end
                end
                P_ARMED: begin
                    coef0 <= coef0 + d0;
                    coef1 <= coef1 + d1;
                    upd_cnt <= 64'd1;
                    phase <= P_ADAPT;
                    start_seen <= 1'b1;
                end
                P_ADAPT: begin
                    coef0 <= coef0 + d0;
                    coef1 <= coef1 + d1;
                    upd_cnt <= upd_cnt + 64'd1;
                    if (upd_cnt == N_UPD - 64'd1)
                        phase <= P_DONE;
                end
                default: ;
            endcase
        end
    end

    assign o_tap0 = coef0;
    assign o_tap1 = coef1;
    assign o_done = (phase == P_DONE);

    always @(posedge clk)
        if (q_seen && phase == P_DONE)
            assert (arm_seen && start_seen);
endmodule

module fb_scanout (
    input  wire        clk,
    input  wire        start,
    input  wire        ce,
    input  wire [31:0] base_in,
    output wire [31:0] o_addr,
    output wire        o_rd,
    output wire        o_eol,
    output wire        o_eof
);
    // 32 pixels per line, 32 lines per frame, raster-order scanout
    reg        armed    = 1'b0;
    reg [31:0] base     = 32'd0;
    reg [31:0] cur_addr = 32'd0;
    reg [31:0] line     = 32'd0;
    reg [31:0] px       = 32'd0;

    wire adv = armed && ce;
    wire eol = (px == 32'd31);
    wire eof = eol && (line == 32'd31);

    assign o_addr = cur_addr;
    assign o_rd   = adv;
    assign o_eol  = adv && eol;
    assign o_eof  = adv && eof;

    always @(posedge clk) begin
        if (start)
            armed <= 1'b1;
        if (adv) begin
            if (eof) begin
                base     <= base_in;
                cur_addr <= base_in;
                line     <= 32'd0;
                px       <= 32'd0;
            end else if (eol) begin
                px       <= 32'd0;
                line     <= line + 32'd1;
                cur_addr <= cur_addr + 32'd1;
            end else begin
                px       <= px + 32'd1;
                cur_addr <= cur_addr + 32'd1;
            end
        end
    end

    // after scanout has been started, the fetch address stays inside the frame
    always @(posedge clk)
        if (armed)
            assert (cur_addr - base <= 32'd1023);
endmodule

module axis_scan_lockup (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_sof,
    input  wire        i_eof,
    input  wire        i_vld,
    input  wire [63:0] i_data,
    output wire        o_vld,
    output wire [63:0] o_data
);
    // Scan segment A (MAC-side domain): 4 beats of 64-bit stream data
    reg [3:0]   a_v;
    reg [255:0] a_d;
    // Lockup latch between segments: holds A's tail beat for a half cycle
    reg         lk_v;
    reg [63:0]  lk_d;
    // Scan segment B (UDP-side domain): 4 beats
    reg [3:0]   b_v;
    reg [255:0] b_d;
    // Occupancy of valid beats across the whole chain (8 entries + lockup)
    reg [63:0]  occ;
    // Packet window: opened by start-of-frame, closed by end-of-frame
    reg         armed;

    initial a_v   = 4'b0000;
    initial a_d   = 256'd0;
    initial lk_v  = 1'b0;
    initial lk_d  = 64'd0;
    initial b_v   = 4'b0000;
    initial b_d   = 256'd0;
    initial occ   = 64'd0;
    initial armed = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            a_v   <= 4'b0000;
            a_d   <= 256'd0;
            lk_v  <= 1'b0;
            lk_d  <= 64'd0;
            b_v   <= 4'b0000;
            b_d   <= 256'd0;
            occ   <= 64'd0;
            armed <= 1'b0;
        end else if (i_ce) begin
            a_v   <= {a_v[2:0], i_vld};
            a_d   <= {a_d[191:0], i_data};
            lk_v  <= a_v[3];
            lk_d  <= a_d[255:192];
            b_v   <= {b_v[2:0], lk_v};
            b_d   <= {b_d[191:0], lk_d};
            occ   <= occ + {63'd0, i_vld} - {63'd0, b_v[3]};
            armed <= (armed | i_sof) & ~i_eof;
        end
    end

    assign o_vld  = b_v[3];
    assign o_data = b_d[255:192];

    always @(*)
        assert (!armed || occ <= 64'd9);
endmodule

module spi_master_face (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire start,
    input wire cfg_wr,
    input wire [1:0] cfg_mode,
    input wire [7:0] tx_data,
    input wire miso,
    output reg cs_n,
    output reg sclk,
    output wire mosi,
    output reg [7:0] rx_data,
    output reg done
);
    reg busy;
    reg [7:0] shreg;
    reg [7:0] bitcnt;
    reg cpol;
    reg cpha;
    reg phase;
    reg samp;
    reg win;
    reg [1:0] mode_sh;
    reg pv;

    initial begin
        cs_n = 1'b1; sclk = 1'b0; rx_data = 8'd0; done = 1'b0;
        busy = 1'b0; shreg = 8'd0; bitcnt = 8'd0; cpol = 1'b0; cpha = 1'b0;
        phase = 1'b0; samp = 1'b0; win = 1'b0; mode_sh = 2'b00; pv = 1'b0;
    end

    assign mosi = shreg[7];

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            cs_n <= 1'b1; sclk <= 1'b0; done <= 1'b0; busy <= 1'b0;
            bitcnt <= 8'd0; cpol <= 1'b0; cpha <= 1'b0; phase <= 1'b0;
            win <= 1'b0; mode_sh <= 2'b00;
        end else if (ce) begin
            done <= 1'b0;
            if (!busy) begin
                if (cfg_wr) begin
                    cpol <= cfg_mode[1];
                    cpha <= cfg_mode[0];
                    sclk <= cfg_mode[1];
                end else if (start) begin
                    busy <= 1'b1;
                    cs_n <= 1'b0;
                    shreg <= tx_data;
                    bitcnt <= 8'd0;
                    phase <= 1'b0;
                    win <= 1'b1;
                    mode_sh <= {cpol, cpha};
                end
            end else begin
                sclk <= ~sclk;
                phase <= ~phase;
                if (!phase) begin
                    samp <= miso;
                end else begin
                    shreg <= {shreg[6:0], (cpha ? miso : samp)};
                    if (bitcnt == 8'd7) begin
                        bitcnt <= 8'd0;
                        busy <= 1'b0;
                        cs_n <= 1'b1;
                        win <= 1'b0;
                        done <= 1'b1;
                        rx_data <= {shreg[6:0], (cpha ? miso : samp)};
                    end else begin
                        bitcnt <= bitcnt + 8'd1;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        if (pv && win && $stable(cs_n))
            assert ($stable({cpol, cpha}) && ({cpol, cpha} == mode_sh));
endmodule

module simd_serial_alu (
    input wire clk,
    input wire ce,
    input wire req,
    input wire [1:0] op,
    input wire [1:0] lsz,
    input wire [63:0] a_in,
    input wire [63:0] b_in,
    output wire busy_o,
    output wire [63:0] result,
    output wire [7:0] lane_flags
);
    localparam [63:0] K = 64'd8;
    reg busy = 1'b0;
    reg [63:0] cd = 64'd0;
    reg [63:0] pos = 64'd0;
    reg [63:0] a_r = 64'd0;
    reg [63:0] b_r = 64'd0;
    reg [63:0] res = 64'd0;
    reg [7:0] flg = 8'd0;
    reg [1:0] op_r = 2'd0;
    reg [1:0] lsz_r = 2'd0;
    reg carry = 1'b0;

    wire [2:0] p = pos[2:0];
    wire lane_lo = (lsz_r == 2'd0) | ((lsz_r == 2'd1) & ~p[0]) | ((lsz_r == 2'd2) & (p[1:0] == 2'b00)) | (p == 3'd0);
    wire lane_hi = (lsz_r == 2'd0) | ((lsz_r == 2'd1) & p[0]) | ((lsz_r == 2'd2) & (p[1:0] == 2'b11)) | (p == 3'd7);
    wire [7:0] ab = a_r[{p, 3'b000} +: 8];
    wire [7:0] bb = b_r[{p, 3'b000} +: 8];
    wire sub = (op_r == 2'd1);
    wire arith = ~op_r[1];
    wire cin = lane_lo ? sub : carry;
    wire [8:0] sum = {1'b0, ab} + {1'b0, bb ^ {8{sub}}} + {8'd0, cin};
    reg [7:0] r8;
    always @(*) begin
        case (op_r)
            2'd0, 2'd1: r8 = sum[7:0];
            2'd2: r8 = ab & bb;
            default: r8 = ab ^ bb;
        endcase
    end

    always @(posedge clk) begin
        if (ce) begin
            if (busy) begin
                res[{p, 3'b000} +: 8] <= r8;
                flg[p] <= lane_hi & arith & sum[8];
                carry <= sum[8];
                cd <= cd - 64'd1;
                if (pos == 64'd7) begin
                    busy <= 1'b0;
                    pos <= 64'd0;
                end else begin
                    pos <= pos + 64'd1;
                end
            end else if (req) begin
                busy <= 1'b1;
                pos <= 64'd0;
                cd <= K;
                a_r <= a_in;
                b_r <= b_in;
                op_r <= op;
                lsz_r <= lsz;
                carry <= 1'b0;
            end
        end
    end

    assign busy_o = busy;
    assign result = res;
    assign lane_flags = flg;

    always @(*) if (busy) assert (cd != 64'd0);
    always @(*) if (!busy) assert (cd == 64'd0);
endmodule

module lin_master_tx (
    input wire clk,
    input wire rst,
    input wire i_tick,
    input wire i_start,
    input wire i_abort,
    input wire i_enhanced,
    input wire [5:0] i_id,
    input wire [3:0] i_len,
    input wire i_wr_en,
    input wire [3:0] i_wr_addr,
    input wire [31:0] i_wr_data,
    output wire o_busy,
    output wire o_bus_low,
    output wire [31:0] o_tx_byte
);
    // one-hot frame phase: 0 IDLE, 1 BREAK, 2 SYNC, 3 PID, 4 DATA, 5 CSUM
    reg [5:0] phase;
    initial phase = 6'b000001;
    reg [31:0] brk_cnt = 32'd0;
    reg [31:0] byte_idx = 32'd0;
    reg [31:0] bytes_left = 32'd0;
    reg [31:0] frame_len = 32'd1;
    reg [31:0] csum = 32'd0;
    reg [31:0] tx_byte = 32'd0;
    reg [7:0] pid_reg = 8'd0;
    reg [31:0] data_buf [0:15];
    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) data_buf[i] = 32'd0;
    end
    reg armed = 1'b1;
    reg pv = 1'b0;

    wire [7:0] cur_byte = data_buf[byte_idx[3:0]][7:0];
    wire [8:0] csum_sum = {1'b0, csum[7:0]} + {1'b0, cur_byte};
    wire [7:0] csum_next = csum_sum[8] ? (csum_sum[7:0] + 8'd1) : csum_sum[7:0];
    wire p0 = i_id[0] ^ i_id[1] ^ i_id[2] ^ i_id[4];
    wire p1 = ~(i_id[1] ^ i_id[3] ^ i_id[4] ^ i_id[5]);
    wire [7:0] pid_calc = {p1, p0, i_id};

    always @(posedge clk) begin
        pv <= 1'b1;
        if (i_abort) armed <= 1'b0;
    end

    always @(posedge clk) begin
        if (i_wr_en) data_buf[i_wr_addr] <= i_wr_data;
    end

    always @(posedge clk) begin
        if (rst || i_abort) begin
            phase <= 6'b000001;
            brk_cnt <= 32'd0;
            byte_idx <= 32'd0;
            bytes_left <= 32'd0;
        end else if (i_tick) begin
            if (phase[0] && i_start) begin
                phase[0] <= 1'b0;
                phase[1] <= 1'b1;
                brk_cnt <= 32'd0;
                frame_len <= {28'd0, i_len} + 32'd1;
                pid_reg <= pid_calc;
                csum <= i_enhanced ? {24'd0, pid_calc} : 32'd0;
            end
            if (phase[1]) begin
                if (brk_cnt == 32'd12) begin
                    phase[1] <= 1'b0;
                    phase[2] <= 1'b1;
                end
                brk_cnt <= brk_cnt + 32'd1;
            end
            if (phase[2]) begin
                tx_byte <= 32'h00000055;
                phase[2] <= 1'b0;
                phase[3] <= 1'b1;
            end
            if (phase[3]) begin
                tx_byte <= {24'd0, pid_reg};
                byte_idx <= 32'd0;
                bytes_left <= frame_len;
                phase[3] <= 1'b0;
                phase[4] <= 1'b1;
            end
            if (phase[4]) begin
                tx_byte <= {24'd0, cur_byte};
                csum <= {24'd0, csum_next};
                byte_idx <= byte_idx + 32'd1;
                bytes_left <= bytes_left - 32'd1;
                if (byte_idx == frame_len - 32'd1) phase[4] <= 1'b0;
                if (bytes_left == 32'd1) phase[5] <= 1'b1;
            end
            if (phase[5]) begin
                tx_byte <= {24'd0, ~csum[7:0]};
                phase[5] <= 1'b0;
                phase[0] <= 1'b1;
            end
        end
    end

    assign o_busy = !phase[0];
    assign o_bus_low = phase[1];
    assign o_tx_byte = tx_byte;

    // Absence, before first abort: checksum phase never begins while data phase is still active
    always @(posedge clk)
        if (pv && armed && $rose(phase[5]))
            assert (!phase[4]);
endmodule

module iq_imbalance_corr (
    input  wire         clk,
    input  wire         rst,
    input  wire         ce,
    input  wire         in_valid,
    input  wire [127:0] i_in,
    input  wire [127:0] q_in,
    input  wire         coef_we,
    input  wire [7:0]   gain_in,
    input  wire [7:0]   phase_in,
    input  wire         cal_start,
    input  wire         cal_stop,
    output wire         out_valid,
    output wire [127:0] i_out,
    output wire [127:0] q_out,
    output wire [2:0]   inflight_o
);
    // programmable correction coefficients (Q1.7 fixed point)
    reg [7:0] gain;
    reg [7:0] phase;
    // pipeline valid bits
    reg v0, v1, v2, v3;
    // pipeline data
    reg [127:0] i0, q0, i1, i2, i3, q3;
    reg [135:0] p_i, p_q;
    reg [136:0] s2;
    // occupancy of the correction pipeline
    reg [2:0] inflight;
    // calibration observation window
    reg win;

    initial begin
        gain = 8'd128; phase = 8'd0;
        v0 = 1'b0; v1 = 1'b0; v2 = 1'b0; v3 = 1'b0;
        i0 = 128'd0; q0 = 128'd0; i1 = 128'd0; i2 = 128'd0; i3 = 128'd0; q3 = 128'd0;
        p_i = 136'd0; p_q = 136'd0; s2 = 137'd0;
        inflight = 3'd0;
        win = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            gain <= 8'd128; phase <= 8'd0;
            v0 <= 1'b0; v1 <= 1'b0; v2 <= 1'b0; v3 <= 1'b0;
            inflight <= 3'd0;
            win <= 1'b0;
        end else if (ce) begin
            if (coef_we) begin
                gain  <= gain_in;
                phase <= phase_in;
            end
            // stage 0: capture complex sample
            v0 <= in_valid;
            i0 <= i_in;
            q0 <= q_in;
            // stage 1: correction matrix products
            v1  <= v0;
            i1  <= i0;
            p_q <= q0 * gain;
            p_i <= i0 * phase;
            // stage 2: cross-branch sum
            v2 <= v1;
            i2 <= i1;
            s2 <= p_q + p_i;
            // stage 3: corrected output
            v3 <= v2;
            i3 <= i2;
            q3 <= s2[134:7];
            // occupancy bookkeeping
            inflight <= inflight + {2'b00, in_valid} - {2'b00, v3};
            // calibration window: opened by cal_start, closed by cal_stop
            if (cal_start)
                win <= 1'b1;
            else if (cal_stop)
                win <= 1'b0;
        end
    end

    assign out_valid  = v3;
    assign i_out      = i3;
    assign q_out      = q3;
    assign inflight_o = inflight;

    // within a calibration window, at most 4 samples are in flight
    always @(posedge clk)
        if (win)
            assert (inflight <= 3'd4);

    // within a calibration window, an empty pipeline presents no output
    always @(posedge clk)
        if (win && inflight == 3'd0)
            assert (!v3);
endmodule

module ro_entropy_harvester (
    input  wire        clk,
    input  wire        sample_en,
    input  wire [2:0]  ro_phase,
    output reg  [31:0] o_word,
    output reg         o_valid
);
    // collection shift register and sample counter
    reg [31:0] shreg      = 32'd0;
    reg [31:0] sample_cnt = 32'd0;
    // scope register: high until the first full word is harvested
    reg        armed      = 1'b1;
    initial o_word  = 32'd0;
    initial o_valid = 1'b0;

    // raw entropy bit: XOR of free-running oscillator phases
    wire raw_bit = ^ro_phase;

    always @(posedge clk) begin
        if (sample_en) begin
            shreg <= {shreg[30:0], raw_bit};
            if (sample_cnt == 32'd31) begin
                sample_cnt <= 32'd0;
                o_word     <= {shreg[30:0], raw_bit};
                o_valid    <= 1'b1;
                armed      <= 1'b0;
            end else begin
                sample_cnt <= sample_cnt + 32'd1;
                o_valid    <= 1'b0;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // before the first harvest, the top collection bit never changes
    always @(posedge clk)
        if (pv && armed) assert (shreg[31] == $past(shreg[31]));
endmodule

module fm_link_8b10b_framer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [7:0]  i_data,
    output reg  [9:0]  o_sym,
    output reg         o_rd,
    output reg  [31:0] o_sym_cnt,
    output reg  [31:0] o_pkt_cnt
);
    localparam [1:0] K_COMMA = 2'd1, K_SOF = 2'd2, K_EOF = 2'd3;
    localparam [1:0] PH_IDLE = 2'd0, PH_ALIGN = 2'd1, PH_PKT = 2'd2;

    reg [1:0] phase;
    reg seen_comma, seen_start, seen_end;

    initial begin
        phase = PH_IDLE; seen_comma = 1'b0; seen_start = 1'b0; seen_end = 1'b0;
        o_sym = 10'd0; o_rd = 1'b0; o_sym_cnt = 32'd0; o_pkt_cnt = 32'd0;
    end

    function [5:0] enc6;
        input [4:0] x;
        begin
            case (x)
                5'd0:  enc6 = 6'b100111;
                5'd1:  enc6 = 6'b011101;
                5'd2:  enc6 = 6'b101101;
                5'd3:  enc6 = 6'b110001;
                5'd4:  enc6 = 6'b110101;
                5'd5:  enc6 = 6'b101001;
                5'd6:  enc6 = 6'b011001;
                5'd7:  enc6 = 6'b111000;
                5'd8:  enc6 = 6'b111001;
                5'd9:  enc6 = 6'b100101;
                5'd10: enc6 = 6'b010101;
                5'd11: enc6 = 6'b110100;
                5'd12: enc6 = 6'b001101;
                5'd13: enc6 = 6'b101100;
                5'd14: enc6 = 6'b011100;
                5'd15: enc6 = 6'b010111;
                5'd16: enc6 = 6'b011011;
                5'd17: enc6 = 6'b100011;
                5'd18: enc6 = 6'b010011;
                5'd19: enc6 = 6'b110010;
                5'd20: enc6 = 6'b001011;
                5'd21: enc6 = 6'b101010;
                5'd22: enc6 = 6'b011010;
                5'd23: enc6 = 6'b111010;
                5'd24: enc6 = 6'b110011;
                5'd25: enc6 = 6'b100110;
                5'd26: enc6 = 6'b010110;
                5'd27: enc6 = 6'b110110;
                5'd28: enc6 = 6'b001110;
                5'd29: enc6 = 6'b101110;
                5'd30: enc6 = 6'b011110;
                default: enc6 = 6'b101011;
            endcase
        end
    endfunction

    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
                3'd5: enc4 = 4'b1010;
                3'd6: enc4 = 4'b0110;
                default: enc4 = 4'b1110;
            endcase
        end
    endfunction

    function [2:0] ones6;
        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
    wire do_comma = i_ce && i_k && (i_kcode == K_COMMA);
    wire do_sof   = i_ce && i_k && (i_kcode == K_SOF) && (phase == PH_ALIGN);
    wire do_eof   = i_ce && i_k && (i_kcode == K_EOF) && (phase == PH_PKT);
    wire do_data  = i_ce && !i_k;

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
        end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));
endmodule

module dvfs_ctrl (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire [31:0] i_load,
    input  wire        i_vr_ack,
    input  wire        i_win_close,
    output reg  [31:0] o_volt_mv,
    output reg  [31:0] o_freq_khz,
    output wire        o_pending,
    output wire [31:0] o_req_count
);
    localparam [31:0] HI_TH = 32'd800;
    localparam [31:0] LO_TH = 32'd200;

    reg [2:0]  cur_pt    = 3'd0;
    reg [2:0]  req_pt    = 3'd0;
    reg [2:0]  last_req  = 3'd0;
    reg        pending   = 1'b0;
    reg        win       = 1'b0;
    reg [31:0] req_count = 32'd0;

    wire       up    = (i_load > HI_TH) && (cur_pt != 3'd7);
    wire       dn    = (i_load < LO_TH) && (cur_pt != 3'd0);
    wire       issue = i_ce && !pending && (up || dn);
    wire [2:0] nxt   = up ? (cur_pt + 3'd1) : (cur_pt - 3'd1);
    wire       grant = i_ce && pending && i_vr_ack;

    always @(posedge clk) begin
        if (i_reset) begin
            cur_pt    <= 3'd0;
            req_pt    <= 3'd0;
            last_req  <= 3'd0;
            pending   <= 1'b0;
            win       <= 1'b0;
            req_count <= 32'd0;
        end else begin
            if (issue) begin
                req_pt    <= nxt;
                last_req  <= nxt;
                pending   <= 1'b1;
                req_count <= req_count + 32'd1;
            end else if (grant) begin
                cur_pt  <= req_pt;
                pending <= 1'b0;
            end
            if (issue)
                win <= 1'b1;
            else if (i_ce && i_win_close)
                win <= 1'b0;
        end
    end

    always @(*) begin
        case (cur_pt)
            3'd0: begin o_volt_mv = 32'd700;  o_freq_khz = 32'd100000;  end
            3'd1: begin o_volt_mv = 32'd750;  o_freq_khz = 32'd200000;  end
            3'd2: begin o_volt_mv = 32'd800;  o_freq_khz = 32'd400000;  end
            3'd3: begin o_volt_mv = 32'd850;  o_freq_khz = 32'd600000;  end
            3'd4: begin o_volt_mv = 32'd900;  o_freq_khz = 32'd800000;  end
            3'd5: begin o_volt_mv = 32'd950;  o_freq_khz = 32'd1000000; end
            3'd6: begin o_volt_mv = 32'd1000; o_freq_khz = 32'd1200000; end
            default: begin o_volt_mv = 32'd1100; o_freq_khz = 32'd1500000; end
        endcase
    end

    assign o_pending   = pending;
    assign o_req_count = req_count;

    always @(posedge clk)
        assert (!(win && !pending) || (cur_pt == last_req));
endmodule

module trace_buffer (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_trig,
    input  wire        i_flush,
    input  wire [63:0] i_sample,
    input  wire [5:0]  i_raddr,
    output wire [63:0] o_rdata,
    output wire        o_done,
    output wire [5:0]  o_trig_pos
);
    localparam [63:0] POST     = 64'd12;
    localparam [5:0]  DEPTH_M1 = 6'd47;

    reg [63:0] mem [0:47];
    reg [5:0]  wptr       = 6'd0;
    reg [5:0]  trig_pos   = 6'd0;
    reg        triggered  = 1'b0;
    reg        done       = 1'b0;
    reg [63:0] remaining  = 64'd0;
    reg [63:0] post_count = 64'd0;
    reg        no_abort   = 1'b1;
    reg        pv         = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 48; i = i + 1) mem[i] = 64'd0;
    end

    wire [5:0] wptr_nxt = (wptr == DEPTH_M1) ? 6'd0 : wptr + 6'd1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_flush) begin
                triggered  <= 1'b0;
                done       <= 1'b0;
                remaining  <= 64'd0;
                post_count <= 64'd0;
                no_abort   <= 1'b0;
            end else if (!done) begin
                mem[wptr] <= i_sample;
                wptr      <= wptr_nxt;
                if (!triggered) begin
                    if (i_trig) begin
                        triggered  <= 1'b1;
                        trig_pos   <= wptr;
                        remaining  <= POST;
                        post_count <= 64'd0;
                    end
                end else begin
                    remaining  <= remaining - 64'd1;
                    post_count <= post_count + 64'd1;
                    if (post_count == POST - 64'd1)
                        done <= 1'b1;
                end
            end
        end
    end

    assign o_rdata    = (i_raddr <= DEPTH_M1) ? mem[i_raddr] : 64'd0;
    assign o_done     = done;
    assign o_trig_pos = trig_pos;

    wire expired = (remaining == 64'd0);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && no_abort && $rose(expired))
            assert (done);
endmodule

module act_gate_counter (
    input wire clk,
    input wire ce,
    input wire gate,
    input wire evt,
    output reg [7:0] result
);
    reg       gate_q = 1'b0;
    reg       evt_q  = 1'b0;
    reg [7:0] cnt    = 8'd0;
    reg       win    = 1'b0;
    reg       seen   = 1'b0;
    initial result = 8'd0;

    wire edge_det = evt && !evt_q;

    always @(posedge clk) begin
        if (ce) begin
            gate_q <= gate;
            evt_q  <= evt;
            if (gate && !gate_q) begin
                win  <= 1'b1;
                seen <= 1'b0;
            end else if (gate && gate_q) begin
                if (edge_det) begin
                    seen <= 1'b1;
                    if (cnt != 8'hFF)
                        cnt <= cnt + 8'd1;
                end
            end else if (!gate && gate_q) begin
                result <= cnt;
                cnt    <= 8'd0;
                win    <= 1'b0;
            end
        end
    end

    assert property (!win || seen || cnt == 8'd0);
endmodule

module cplx_mixer (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        lock,
    input  wire        unlock,
    input  wire [63:0] s_i,
    input  wire [63:0] s_q,
    input  wire [63:0] lo_i,
    input  wire [63:0] lo_q,
    output reg  [63:0] y_i,
    output reg  [63:0] y_q
);
    // stage 1: four partial products of (s_i + j s_q) * (lo_i + j lo_q)
    reg [63:0] pp_ii, pp_qq, pp_iq, pp_qi;
    // shadow: the partial products that were summed into the current output
    reg [63:0] sp_ii, sp_qq, sp_iq, sp_qi;
    // observation window: opened by LO lock, closed by unlock (may never close)
    reg win;
    reg pv;

    initial begin
        pp_ii = 64'd0; pp_qq = 64'd0; pp_iq = 64'd0; pp_qi = 64'd0;
        sp_ii = 64'd0; sp_qq = 64'd0; sp_iq = 64'd0; sp_qi = 64'd0;
        y_i = 64'd0; y_q = 64'd0;
        win = 1'b0;
        pv = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            pp_ii <= 64'd0; pp_qq <= 64'd0; pp_iq <= 64'd0; pp_qi <= 64'd0;
            sp_ii <= 64'd0; sp_qq <= 64'd0; sp_iq <= 64'd0; sp_qi <= 64'd0;
            y_i <= 64'd0; y_q <= 64'd0;
        end else if (ce) begin
            pp_ii <= s_i * lo_i;
            pp_qq <= s_q * lo_q;
            pp_iq <= s_i * lo_q;
            pp_qi <= s_q * lo_i;
            sp_ii <= pp_ii;
            sp_qq <= pp_qq;
            sp_iq <= pp_iq;
            sp_qi <= pp_qi;
            y_i   <= pp_ii - pp_qq;
            y_q   <= pp_iq + pp_qi;
        end
    end

    always @(posedge clk) begin
        if (rst)         win <= 1'b0;
        else if (lock)   win <= 1'b1;
        else if (unlock) win <= 1'b0;
    end

    // precedence: within the lock window, an output change must be preceded by
    // a change in the partial products that feed the summer
    always @(posedge clk)
        if (pv && win && $stable(sp_ii) && $stable(sp_qq) && $stable(sp_iq) && $stable(sp_qi))
            assert ($stable(y_i) && $stable(y_q));
endmodule

module zz_reorder (
    input  wire        i_clk,
    input  wire        i_reset,
    input  wire        i_in_valid,
    input  wire [31:0] i_coef,
    input  wire        i_out_ready,
    output reg         o_valid,
    output reg  [31:0] o_coef,
    output wire        o_full,
    output wire        o_empty
);
    // two 64-entry banks = 128-entry block memory (ping-pong)
    reg [31:0] mem [0:127];
    reg [1:0]  bank_valid = 2'b00;
    reg        w_bank = 1'b0;
    reg        r_bank = 1'b0;
    reg [31:0] w_idx = 32'd0;
    reg [31:0] r_idx = 32'd0;
    reg [31:0] nfull = 32'd0;
    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) mem[i] = 32'd0;
        o_valid = 1'b0;
        o_coef  = 32'd0;
    end

    // zigzag index-sequence ROM: zigzag position -> raster position
    function [5:0] zz;
        input [5:0] k;
        case (k)
            6'd0: zz=6'd0;   6'd1: zz=6'd1;   6'd2: zz=6'd8;   6'd3: zz=6'd16;
            6'd4: zz=6'd9;   6'd5: zz=6'd2;   6'd6: zz=6'd3;   6'd7: zz=6'd10;
            6'd8: zz=6'd17;  6'd9: zz=6'd24;  6'd10: zz=6'd32; 6'd11: zz=6'd25;
            6'd12: zz=6'd18; 6'd13: zz=6'd11; 6'd14: zz=6'd4;  6'd15: zz=6'd5;
            6'd16: zz=6'd12; 6'd17: zz=6'd19; 6'd18: zz=6'd26; 6'd19: zz=6'd33;
            6'd20: zz=6'd40; 6'd21: zz=6'd48; 6'd22: zz=6'd41; 6'd23: zz=6'd34;
            6'd24: zz=6'd27; 6'd25: zz=6'd20; 6'd26: zz=6'd13; 6'd27: zz=6'd6;
            6'd28: zz=6'd7;  6'd29: zz=6'd14; 6'd30: zz=6'd21; 6'd31: zz=6'd28;
            6'd32: zz=6'd35; 6'd33: zz=6'd42; 6'd34: zz=6'd49; 6'd35: zz=6'd56;
            6'd36: zz=6'd57; 6'd37: zz=6'd50; 6'd38: zz=6'd43; 6'd39: zz=6'd36;
            6'd40: zz=6'd29; 6'd41: zz=6'd22; 6'd42: zz=6'd15; 6'd43: zz=6'd23;
            6'd44: zz=6'd30; 6'd45: zz=6'd37; 6'd46: zz=6'd44; 6'd47: zz=6'd51;
            6'd48: zz=6'd58; 6'd49: zz=6'd59; 6'd50: zz=6'd52; 6'd51: zz=6'd45;
            6'd52: zz=6'd38; 6'd53: zz=6'd31; 6'd54: zz=6'd39; 6'd55: zz=6'd46;
            6'd56: zz=6'd53; 6'd57: zz=6'd60; 6'd58: zz=6'd61; 6'd59: zz=6'd54;
            6'd60: zz=6'd47; 6'd61: zz=6'd55; 6'd62: zz=6'd62; default: zz=6'd63;
        endcase
    endfunction

    wire wr_go   = i_in_valid && !bank_valid[w_bank];
    wire rd_go   = i_out_ready && bank_valid[r_bank];
    wire wr_done = wr_go && (w_idx == 32'd63);
    wire rd_done = rd_go && (r_idx == 32'd63);

    assign o_full  = (nfull == 32'd2);
    assign o_empty = !bank_valid[r_bank];

    // raster-order write into the current write bank
    always @(posedge i_clk)
        if (!i_reset && wr_go)
            mem[{w_bank, w_idx[5:0]}] <= i_coef;

    always @(posedge i_clk) begin
        if (i_reset) begin
            bank_valid <= 2'b00;
            w_bank     <= 1'b0;
            r_bank     <= 1'b0;
            w_idx      <= 32'd0;
            r_idx      <= 32'd0;
            nfull      <= 32'd0;
            o_valid    <= 1'b0;
        end else begin
            if (wr_go)   w_idx  <= wr_done ? 32'd0 : w_idx + 32'd1;
            if (wr_done) w_bank <= ~w_bank;
            if (rd_go)   r_idx  <= rd_done ? 32'd0 : r_idx + 32'd1;
            if (rd_done) r_bank <= ~r_bank;
            if (wr_done) bank_valid[w_bank] <= 1'b1;
            if (rd_done) bank_valid[r_bank] <= 1'b0;
            case ({wr_done, rd_done})
                2'b10:   nfull <= nfull + 32'd1;
                2'b01:   nfull <= nfull - 32'd1;
                default: nfull <= nfull;
            endcase
            // zigzag-order read from the current read bank
            if (i_out_ready) begin
                o_valid <= bank_valid[r_bank];
                if (rd_go)
                    o_coef <= mem[{r_bank, zz(r_idx[5:0])}];
            end
        end
    end

    // absence: the buffer is never full and empty at the same time
    always @(posedge i_clk)
        if (o_full)
            assert (!o_empty);
endmodule

module usb_ep_buf (
    input  wire        clk,
    input  wire        ce,
    input  wire        cfg_set,
    input  wire        out_valid,
    input  wire [31:0] out_data,
    input  wire        in_ready,
    output wire [31:0] in_data,
    output wire        in_toggle,
    output wire        out_toggle,
    output wire [31:0] level_o
);
    reg [31:0] mem [0:15];
    reg [31:0] wptr     = 32'd0;
    reg [31:0] rptr     = 32'd0;
    reg [31:0] count    = 32'd0;
    reg        tog_out  = 1'b0;
    reg        tog_in   = 1'b0;
    reg        ep_cfg   = 1'b0;
    reg        armed    = 1'b0;
    reg        pkt_done = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) mem[i] = 32'd0;
    end

    wire [31:0] level   = wptr - rptr;
    wire        do_push = ce && ep_cfg && out_valid && (level != 32'd16);
    wire        do_pop  = ce && in_ready && (level != 32'd0);

    assign in_data    = mem[rptr[3:0]];
    assign in_toggle  = tog_in;
    assign out_toggle = tog_out;
    assign level_o    = count;

    always @(posedge clk) begin
        if (ce) begin
            if (cfg_set) ep_cfg <= 1'b1;
            pkt_done <= do_push;
        end
        if (do_push) begin
            mem[wptr[3:0]] <= out_data;
            wptr    <= wptr + 32'd1;
            tog_out <= ~tog_out;
            armed   <= 1'b1;
        end
        if (do_pop) begin
            rptr   <= rptr + 32'd1;
            tog_in <= ~tog_in;
        end
        case ({do_push, do_pop})
            2'b10:   count <= count + 32'd1;
            2'b01:   count <= count - 32'd1;
            default: count <= count;
        endcase
    end

    always @(posedge clk)
        if (armed && $rose(pkt_done))
            assert (count <= 32'd16);
endmodule

module flow_hash_steer (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        pkt_valid,
    input  wire [7:0]  src,
    input  wire [7:0]  dst,
    input  wire [7:0]  port,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_addr,
    input  wire [7:0]  cfg_data,
    output reg  [7:0]  hash_q,
    output reg  [7:0]  q_sel,
    output reg         out_valid
);
    // 32-entry indirection table, 8-bit words, entry i at bits [8i+7:8i]
    reg [255:0] tbl_flat;
    initial tbl_flat = {8{8'd3, 8'd2, 8'd1, 8'd0}};
    initial hash_q = 8'd0;
    initial q_sel = 8'd0;
    initial out_valid = 1'b0;

    // header hash
    wire [7:0] h = src ^ {dst[3:0], dst[7:4]} ^ {port[6:0], port[7]};
    wire [4:0] hidx = h[4:0];
    wire [255:0] sh = tbl_flat >> {hidx, 3'b000};
    wire [7:0] entry = sh[7:0];

    integer i;
    always @(posedge clk) begin
        if (rst) begin
            tbl_flat  <= {8{8'd3, 8'd2, 8'd1, 8'd0}};
            hash_q    <= 8'd0;
            q_sel     <= 8'd0;
            out_valid <= 1'b0;
        end else if (en) begin
            for (i = 0; i < 32; i = i + 1)
                if (cfg_we && cfg_addr == i[4:0])
                    tbl_flat[i*8 +: 8] <= {6'd0, cfg_data[1:0]};
            out_valid <= pkt_valid;
            if (pkt_valid) begin
                hash_q <= h;
                q_sel  <= entry;
            end
        end
    end

    always @(posedge clk)
        if (out_valid) assert (q_sel < 8'd4);
endmodule

module fracn_mash_ctrl (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        arm,
    input  wire        start,
    input  wire        clear,
    input  wire [31:0] int_in,
    input  wire [31:0] frac_in,
    input  wire [31:0] len_in,
    output reg  [31:0] div_ratio,
    output wire        busy
);
    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_ARMED = 2'd1;
    localparam [1:0] P_RUN   = 2'd2;
    localparam [1:0] P_DONE  = 2'd3;

    reg [1:0]  phase;
    reg        win;
    reg        seen_arm;
    reg        seen_start;
    reg [31:0] int_set;
    reg [31:0] frac_set;
    reg [31:0] len_set;
    reg [31:0] remaining;
    reg [31:0] acc1;
    reg [31:0] acc2;
    reg        c2_d;

    initial phase      = P_IDLE;
    initial win        = 1'b0;
    initial seen_arm   = 1'b0;
    initial seen_start = 1'b0;
    initial int_set    = 32'd0;
    initial frac_set   = 32'd0;
    initial len_set    = 32'd0;
    initial remaining  = 32'd0;
    initial acc1       = 32'd0;
    initial acc2       = 32'd0;
    initial c2_d       = 1'b0;
    initial div_ratio  = 32'd0;

    // two-stage MASH 1-1 sigma-delta modulator
    wire [32:0] sum1 = {1'b0, acc1} + {1'b0, frac_set};
    wire [32:0] sum2 = {1'b0, acc2} + {1'b0, sum1[31:0]};
    wire        c1   = sum1[32];
    wire        c2   = sum2[32];

    always @(posedge clk) begin
        if (rst) begin
            phase      <= P_IDLE;
            win        <= 1'b0;
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            int_set    <= 32'd0;
            frac_set   <= 32'd0;
            len_set    <= 32'd0;
            remaining  <= 32'd0;
            acc1       <= 32'd0;
            acc2       <= 32'd0;
            c2_d       <= 1'b0;
            div_ratio  <= 32'd0;
        end else if (ce) begin
            case (phase)
                P_IDLE: if (arm) begin
                    int_set    <= int_in;
                    frac_set   <= frac_in;
                    len_set    <= len_in;
                    acc1       <= 32'd0;
                    acc2       <= 32'd0;
                    c2_d       <= 1'b0;
                    phase      <= P_ARMED;
                    win        <= 1'b1;
                    seen_arm   <= 1'b1;
                    seen_start <= 1'b0;
                end
                P_ARMED: if (start) begin
                    remaining  <= len_set;
                    phase      <= P_RUN;
                    seen_start <= 1'b1;
                end
                P_RUN: begin
                    acc1      <= sum1[31:0];
                    acc2      <= sum2[31:0];
                    c2_d      <= c2;
                    div_ratio <= int_set + {31'd0, c1} + {31'd0, c2} - {31'd0, c2_d};
                    if (remaining == 32'd0)
                        phase <= P_DONE;
                    else
                        remaining <= remaining - 32'd1;
                end
                P_DONE: if (clear) begin
                    phase      <= P_IDLE;
                    win        <= 1'b0;
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                end
            endcase
        end
    end

    assign busy = (phase == P_RUN);

    // chain precedence inside the arm..clear window: finish implies start and arm happened
    always @(posedge clk)
        if (win && phase == P_DONE)
            assert (seen_arm && seen_start);
endmodule

module autobaud_detect (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_rx,
    input  wire        i_arm,
    input  wire        i_clr,
    output wire [31:0] o_divisor,
    output wire        o_locked
);
    localparam [1:0] S_IDLE  = 2'd0;
    localparam [1:0] S_ARMED = 2'd1;
    localparam [1:0] S_MEAS  = 2'd2;
    localparam [1:0] S_DONE  = 2'd3;

    reg [1:0]  stage     = S_IDLE;
    reg        measuring = 1'b0;
    reg [31:0] timer     = 32'd0;
    reg [31:0] divisor   = 32'd0;
    reg        rx_q      = 1'b1;
    reg        win       = 1'b0;
    reg        pv        = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            rx_q <= i_rx;
            if (i_clr) begin
                stage     <= S_IDLE;
                measuring <= 1'b0;
                timer     <= 32'd0;
                win       <= 1'b0;
            end else begin
                if (i_arm) win <= 1'b1;
                // edge-capture timer: count start-bit width
                if (measuring) begin
                    if (i_rx) begin
                        divisor   <= timer + 32'd1;
                        measuring <= 1'b0;
                    end else begin
                        timer <= timer + 32'd1;
                    end
                end
                // measurement-state register: arm -> start -> finish
                case (stage)
                    S_IDLE:  if (i_arm) stage <= S_ARMED;
                    S_ARMED: if (rx_q && !i_rx) begin
                                 stage     <= S_MEAS;
                                 measuring <= 1'b1;
                                 timer     <= 32'd0;
                             end
                    S_MEAS:  if (i_rx) stage <= S_DONE;
                    default: ;
                endcase
            end
        end
    end

    assign o_divisor = divisor;
    assign o_locked  = (stage == S_DONE);

    always @(posedge clk)
        if (pv && win && $stable(stage))
            assert ($stable(divisor));
endmodule

module axi_addr_decoder (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire        cfg_sel,
    input  wire [63:0] cfg_base,
    input  wire [63:0] cfg_limit,
    input  wire        req_valid,
    input  wire [63:0] req_addr,
    input  wire        resp_valid,
    input  wire        resp_port,
    output wire        req_ready,
    output wire [1:0]  route,
    output wire        dec_err
);
    localparam [63:0] MAX_OUT = 64'd32;

    reg [63:0] base0  = 64'h0000000000000000;
    reg [63:0] limit0 = 64'h0000000000000FFF;
    reg [63:0] base1  = 64'h0000000000001000;
    reg [63:0] limit1 = 64'h0000000000001FFF;
    reg [63:0] cnt0   = 64'd0;
    reg [63:0] cnt1   = 64'd0;
    reg [63:0] total  = 64'd0;
    reg        armed  = 1'b0;

    wire hit0 = (req_addr >= base0) && (req_addr <= limit0);
    wire hit1 = !hit0 && (req_addr >= base1) && (req_addr <= limit1);

    assign route     = {hit1, hit0};
    assign dec_err   = req_valid && !hit0 && !hit1;
    assign req_ready = (total < MAX_OUT);

    wire do_resp  = resp_valid && (resp_port ? (cnt1 != 64'd0) : (cnt0 != 64'd0));
    wire do_issue = !do_resp && req_valid && (hit0 || hit1) && req_ready;

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we) begin
                if (cfg_sel) begin
                    base1  <= cfg_base;
                    limit1 <= cfg_limit;
                end else begin
                    base0  <= cfg_base;
                    limit0 <= cfg_limit;
                end
            end
            if (do_resp) begin
                if (resp_port)
                    cnt1 <= cnt1 - 64'd1;
                else
                    cnt0 <= cnt0 - 64'd1;
                total <= total - 64'd1;
            end else if (do_issue) begin
                if (hit0)
                    cnt0 <= cnt0 + 64'd1;
                else
                    cnt1 <= cnt1 + 64'd1;
                total <= total + 64'd1;
                armed <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (armed) assert (cnt0 <= MAX_OUT);

    always @(posedge clk)
        if (armed) assert (cnt1 <= MAX_OUT);
endmodule

module swd_target_port (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        swdio_in,
    output wire        swdio_oe,
    output wire        swdio_out,
    output wire [31:0] o_wdata,
    output wire        o_busy
);
    localparam [2:0] PH_IDLE = 3'd0;
    localparam [2:0] PH_REQ  = 3'd1;
    localparam [2:0] PH_TRN1 = 3'd2;
    localparam [2:0] PH_ACK  = 3'd3;
    localparam [2:0] PH_DATA = 3'd4;
    localparam [2:0] PH_TRN2 = 3'd5;
    localparam [31:0] K = 32'd38;

    reg [2:0]  phase;
    reg [7:0]  req_sr;
    reg [31:0] bitcnt;
    reg [31:0] data_sr;
    reg        par_acc;
    reg        rnw_q;
    reg        outstanding;
    reg [31:0] countdown;
    reg        no_err;
    reg [31:0] wdata;

    initial begin
        phase = PH_IDLE;
        req_sr = 8'd0;
        bitcnt = 32'd0;
        data_sr = 32'd0;
        par_acc = 1'b0;
        rnw_q = 1'b0;
        outstanding = 1'b0;
        countdown = 32'd0;
        no_err = 1'b1;
        wdata = 32'd0;
    end

    wire [7:0] req_full = {swdio_in, req_sr[7:1]};
    wire req_ok = req_full[0] && !req_full[6] && req_full[7] &&
                  (req_full[5] == ^req_full[4:1]);

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE;
            req_sr <= 8'd0;
            bitcnt <= 32'd0;
            data_sr <= 32'd0;
            par_acc <= 1'b0;
            rnw_q <= 1'b0;
            outstanding <= 1'b0;
            countdown <= 32'd0;
            no_err <= 1'b1;
            wdata <= 32'd0;
        end else if (ce) begin
            case (phase)
                PH_IDLE: begin
                    if (swdio_in) begin
                        req_sr <= req_full;
                        bitcnt <= 32'd1;
                        phase <= PH_REQ;
                    end
                end
                PH_REQ: begin
                    req_sr <= req_full;
                    if (bitcnt == 32'd7) begin
                        bitcnt <= 32'd0;
                        if (req_ok) begin
                            phase <= PH_TRN1;
                            outstanding <= 1'b1;
                            countdown <= K;
                            rnw_q <= req_full[2];
                        end else begin
                            phase <= PH_IDLE;
                            no_err <= 1'b0;
                        end
                    end else begin
                        bitcnt <= bitcnt + 32'd1;
                    end
                end
                PH_TRN1: begin
                    phase <= PH_ACK;
                    bitcnt <= 32'd0;
                    countdown <= countdown - 32'd1;
                    par_acc <= 1'b0;
                    if (rnw_q) data_sr <= wdata;
                    else data_sr <= 32'd0;
                end
                PH_ACK: begin
                    countdown <= countdown - 32'd1;
                    if (bitcnt == 32'd2) begin
                        phase <= PH_DATA;
                        bitcnt <= 32'd0;
                    end else begin
                        bitcnt <= bitcnt + 32'd1;
                    end
                end
                PH_DATA: begin
                    countdown <= countdown - 32'd1;
                    if (bitcnt == 32'd32) begin
                        phase <= PH_TRN2;
                        bitcnt <= 32'd0;
                        if (!rnw_q) begin
                            if (par_acc != swdio_in) no_err <= 1'b0;
                            else wdata <= data_sr;
                        end
                    end else begin
                        bitcnt <= bitcnt + 32'd1;
                        if (rnw_q) begin
                            par_acc <= par_acc ^ data_sr[0];
                            data_sr <= {1'b0, data_sr[31:1]};
                        end else begin
                            par_acc <= par_acc ^ swdio_in;
                            data_sr <= {swdio_in, data_sr[31:1]};
                        end
                    end
                end
                PH_TRN2: begin
                    phase <= PH_IDLE;
                    outstanding <= 1'b0;
                    countdown <= 32'd0;
                end
                default: begin
                    phase <= PH_IDLE;
                end
            endcase
        end
    end

    assign swdio_oe  = (phase == PH_ACK) || (phase == PH_DATA && rnw_q);
    assign swdio_out = (phase == PH_ACK) ? (bitcnt == 32'd0) :
                       ((bitcnt == 32'd32) ? par_acc : data_sr[0]);
    assign o_wdata = wdata;
    assign o_busy  = outstanding;

    assert property (!no_err || !outstanding || countdown != 32'd0);
endmodule

module rns_alu (
    input wire clk,
    input wire en,
    input wire [1:0] op,
    input wire [7:0] op_a,
    output wire [7:0] result,
    output wire rns_zero
);
    localparam OP_LOAD = 2'd0;
    localparam OP_ADD  = 2'd1;
    localparam OP_SUB  = 2'd2;
    localparam OP_MUL  = 2'd3;

    // residue registers, one per modulus channel (moduli 5 and 7)
    reg [2:0] r5;
    reg [2:0] r7;
    // binary mirror accumulator modulo 35 (= 5*7)
    reg [7:0] acc;
    // sticky scope register: set at the first LOAD
    reg armed;

    initial begin
        r5 = 3'd0;
        r7 = 3'd0;
        acc = 8'd0;
        armed = 1'b0;
    end

    // operand residues
    wire [15:0] opw = {8'd0, op_a};
    wire [15:0] a5  = opw % 16'd5;
    wire [15:0] a7  = opw % 16'd7;
    wire [15:0] a35 = opw % 16'd35;

    wire [15:0] r5w  = {13'd0, r5};
    wire [15:0] r7w  = {13'd0, r7};
    wire [15:0] accw = {8'd0, acc};

    // channel 5
    wire [15:0] n5_add = (r5w + a5) % 16'd5;
    wire [15:0] n5_sub = (r5w + 16'd5 - a5) % 16'd5;
    wire [15:0] n5_mul = (r5w * a5) % 16'd5;
    // channel 7
    wire [15:0] n7_add = (r7w + a7) % 16'd7;
    wire [15:0] n7_sub = (r7w + 16'd7 - a7) % 16'd7;
    wire [15:0] n7_mul = (r7w * a7) % 16'd7;
    // binary mirror mod 35
    wire [15:0] nb_add = (accw + a35) % 16'd35;
    wire [15:0] nb_sub = (accw + 16'd35 - a35) % 16'd35;
    wire [15:0] nb_mul = (accw * a35) % 16'd35;

    always @(posedge clk) begin
        if (en) begin
            case (op)
                OP_LOAD: begin
                    r5 <= a5[2:0];
                    r7 <= a7[2:0];
                    acc <= a35[7:0];
                    armed <= 1'b1;
                end
                OP_ADD: begin
                    r5 <= n5_add[2:0];
                    r7 <= n7_add[2:0];
                    acc <= nb_add[7:0];
                end
                OP_SUB: begin
                    r5 <= n5_sub[2:0];
                    r7 <= n7_sub[2:0];
                    acc <= nb_sub[7:0];
                end
                default: begin
                    r5 <= n5_mul[2:0];
                    r7 <= n7_mul[2:0];
                    acc <= nb_mul[7:0];
                end
            endcase
        end
    end

    assign result = acc;
    assign rns_zero = (r5 == 3'd0) && (r7 == 3'd0);

    // Absence after first LOAD: RNS zero flag and nonzero binary mirror never together
    assert property (!armed || !((r5 == 3'd0) && (r7 == 3'd0) && (acc != 8'd0)));
endmodule

module delay_pulse_gen (
    input  wire        clk,
    input  wire        ce,
    input  wire        trig,
    input  wire        wr_cfg,
    input  wire [31:0] cfg_delay,
    input  wire [31:0] cfg_width,
    output wire        pulse,
    output wire        busy
);
    localparam [1:0] IDLE = 2'd0, DLY = 2'd1, WID = 2'd2;

    reg [31:0] delay_reg;
    reg [31:0] width_reg;
    reg [31:0] snap_delay;
    reg [31:0] snap_width;
    reg [31:0] cnt;
    reg [1:0]  phase;
    reg [33:0] since_trig;

    initial begin
        delay_reg  = 32'd0;
        width_reg  = 32'd0;
        snap_delay = 32'd0;
        snap_width = 32'd0;
        cnt        = 32'd0;
        phase      = IDLE;
        since_trig = 34'd0;
    end

    always @(posedge clk) begin
        if (ce) begin
            if (wr_cfg) begin
                delay_reg <= cfg_delay;
                width_reg <= cfg_width;
            end
            case (phase)
                IDLE: begin
                    if (trig) begin
                        phase      <= DLY;
                        cnt        <= 32'd0;
                        snap_delay <= delay_reg;
                        snap_width <= width_reg;
                        since_trig <= 34'd0;
                    end
                end
                DLY: begin
                    since_trig <= since_trig + 34'd1;
                    if (cnt == snap_delay) begin
                        phase <= WID;
                        cnt   <= 32'd0;
                    end else begin
                        cnt <= cnt + 32'd1;
                    end
                end
                WID: begin
                    since_trig <= since_trig + 34'd1;
                    if (cnt == snap_width) begin
                        phase <= IDLE;
                        cnt   <= 32'd0;
                    end else begin
                        cnt <= cnt + 32'd1;
                    end
                end
                default: begin
                    phase <= IDLE;
                    cnt   <= 32'd0;
                end
            endcase
        end
    end

    assign pulse = (phase == WID);
    assign busy  = (phase != IDLE);

    // Precedence: a pulse now implies the trigger came more than 'delay' cycles earlier
    always @(posedge clk)
        if (phase == WID)
            assert (since_trig > {2'b00, snap_delay});

    // Precedence: a pulse now implies the trigger came no more than delay+width+1 cycles earlier
    always @(posedge clk)
        if (phase == WID)
            assert (since_trig <= {2'b00, snap_delay} + {2'b00, snap_width} + 34'd1);
endmodule

module raw_hazard_wq (
    input  wire        clk,
    input  wire        rst,
    input  wire        push,
    input  wire [63:0] wr_addr,
    input  wire [7:0]  wr_mask,
    input  wire        pop,
    input  wire        rd_valid,
    input  wire [63:0] rd_addr,
    input  wire [7:0]  rd_mask,
    output wire [31:0] o_match,
    output wire        o_fwd,
    output wire        o_stall,
    output wire        o_full,
    output wire        o_empty
);
    reg [63:0] q_addr [0:31];
    reg [7:0]  q_mask [0:31];
    reg [63:0] wptr, rptr, count;
    reg [31:0] match_vec;
    reg        fwd_r, stall_r;
    integer i;
    initial begin
        wptr = 64'd0; rptr = 64'd0; count = 64'd0;
        match_vec = 32'd0; fwd_r = 1'b0; stall_r = 1'b0;
        for (i = 0; i < 32; i = i + 1) begin
            q_addr[i] = 64'd0;
            q_mask[i] = 8'd0;
        end
    end

    wire full  = ((wptr - rptr) == 64'd32);
    wire empty = (count == 64'd0);
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;

    wire [31:0] hit;
    wire [31:0] cov_ok;
    genvar g;
    generate
        for (g = 0; g < 32; g = g + 1) begin : cmp
            localparam [4:0] IDX = g;
            wire [4:0] off = IDX - rptr[4:0];
            wire pend = ({59'd0, off} < count);
            assign hit[g]    = pend && (q_addr[g] == rd_addr) && ((q_mask[g] & rd_mask) != 8'd0);
            assign cov_ok[g] = ((q_mask[g] & rd_mask) == rd_mask);
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 64'd0;
            rptr <= 64'd0;
            count <= 64'd0;
            match_vec <= 32'd0;
            fwd_r <= 1'b0;
            stall_r <= 1'b0;
        end else begin
            if (do_push) begin
                q_addr[wptr[4:0]] <= wr_addr;
                q_mask[wptr[4:0]] <= wr_mask;
                wptr <= wptr + 64'd1;
            end
            if (do_pop)
                rptr <= rptr + 64'd1;
            case ({do_push, do_pop})
                2'b10: count <= count + 64'd1;
                2'b01: count <= count - 64'd1;
                default: count <= count;
            endcase
            if (rd_valid) begin
                match_vec <= hit;
                fwd_r   <= (hit != 32'd0) && ((hit & cov_ok) == hit);
                stall_r <= (hit != 32'd0) && ((hit & cov_ok) != hit);
            end
        end
    end

    assign o_match = match_vec;
    assign o_fwd   = fwd_r;
    assign o_stall = stall_r;
    assign o_full  = full;
    assign o_empty = empty;

    assert property (!(full && empty));
endmodule

module ivt_dispatch (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        irq_valid,
    input  wire [3:0]  irq_id,
    input  wire        eoi,
    input  wire        tbl_we,
    input  wire [3:0]  tbl_idx,
    input  wire [31:0] tbl_wdata,
    output reg         active,
    output reg  [31:0] vec_addr,
    output reg  [3:0]  cur_id
);
    reg [31:0] vt [0:11];
    reg        nxt_valid;
    reg [3:0]  nxt_id;
    reg [31:0] nxt_addr;
    integer i;

    initial begin
        active    = 1'b0;
        vec_addr  = 32'd0;
        cur_id    = 4'd0;
        nxt_valid = 1'b0;
        nxt_id    = 4'd0;
        nxt_addr  = 32'd0;
        for (i = 0; i < 12; i = i + 1) vt[i] = 32'd0;
    end

    reg [31:0] cur_entry, nxt_entry, irq_entry;

    always @(*) begin
        case (cur_id)
            4'd0: cur_entry = vt[0];   4'd1: cur_entry = vt[1];
            4'd2: cur_entry = vt[2];   4'd3: cur_entry = vt[3];
            4'd4: cur_entry = vt[4];   4'd5: cur_entry = vt[5];
            4'd6: cur_entry = vt[6];   4'd7: cur_entry = vt[7];
            4'd8: cur_entry = vt[8];   4'd9: cur_entry = vt[9];
            4'd10: cur_entry = vt[10]; 4'd11: cur_entry = vt[11];
            default: cur_entry = 32'd0;
        endcase
    end

    always @(*) begin
        case (nxt_id)
            4'd0: nxt_entry = vt[0];   4'd1: nxt_entry = vt[1];
            4'd2: nxt_entry = vt[2];   4'd3: nxt_entry = vt[3];
            4'd4: nxt_entry = vt[4];   4'd5: nxt_entry = vt[5];
            4'd6: nxt_entry = vt[6];   4'd7: nxt_entry = vt[7];
            4'd8: nxt_entry = vt[8];   4'd9: nxt_entry = vt[9];
            4'd10: nxt_entry = vt[10]; 4'd11: nxt_entry = vt[11];
            default: nxt_entry = 32'd0;
        endcase
    end

    always @(*) begin
        case (irq_id)
            4'd0: irq_entry = vt[0];   4'd1: irq_entry = vt[1];
            4'd2: irq_entry = vt[2];   4'd3: irq_entry = vt[3];
            4'd4: irq_entry = vt[4];   4'd5: irq_entry = vt[5];
            4'd6: irq_entry = vt[6];   4'd7: irq_entry = vt[7];
            4'd8: irq_entry = vt[8];   4'd9: irq_entry = vt[9];
            4'd10: irq_entry = vt[10]; 4'd11: irq_entry = vt[11];
            default: irq_entry = 32'd0;
        endcase
    end

    wire        do_wr  = tbl_we && (tbl_idx < 4'd12);
    wire        do_irq = irq_valid && (irq_id < 4'd12);
    wire [31:0] wval   = {tbl_wdata[31:2], 2'b00};

    always @(posedge clk) begin
        if (rst) begin
            active    <= 1'b0;
            nxt_valid <= 1'b0;
        end else if (ce) begin
            if (do_wr) begin
                vt[tbl_idx] <= wval;
                if (active && tbl_idx == cur_id)
                    vec_addr <= wval;
                if (nxt_valid && tbl_idx == nxt_id)
                    nxt_addr <= wval;
            end else if (eoi) begin
                if (active) begin
                    if (nxt_valid) begin
                        cur_id    <= nxt_id;
                        vec_addr  <= nxt_addr;
                        nxt_valid <= 1'b0;
                    end else begin
                        active <= 1'b0;
                    end
                end
            end else if (do_irq) begin
                if (!active) begin
                    active   <= 1'b1;
                    cur_id   <= irq_id;
                    vec_addr <= irq_entry;
                end else if (!nxt_valid) begin
                    nxt_valid <= 1'b1;
                    nxt_id    <= irq_id;
                    nxt_addr  <= irq_entry;
                end
            end
        end
    end

    always @(posedge clk)
        assert (!active || vec_addr == cur_entry);
endmodule

module csa_token_checksum (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_close,
    input  wire [7:0] i_byte,
    output wire       o_csa_zero,
    output wire       o_ref_busy
);
    // carry-save accumulator of a token byte stream
    reg [7:0] sum_r   = 8'd0;
    reg [7:0] carry_r = 8'd0;
    // binary reference accumulator (shadow checksum)
    reg [7:0] acc     = 8'd0;
    // scope register: high until the first record-close event
    reg       armed   = 1'b1;

    // 3:2 reduction of (sum, carry<<1, incoming byte)
    wire [7:0] csa_a = sum_r;
    wire [7:0] csa_b = {carry_r[6:0], 1'b0};
    wire [7:0] csa_c = i_byte;
    wire [7:0] sum_n   = csa_a ^ csa_b ^ csa_c;
    wire [7:0] carry_n = (csa_a & csa_b) | (csa_a & csa_c) | (csa_b & csa_c);

    wire [7:0] csa_val = sum_r + {carry_r[6:0], 1'b0};

    assign o_csa_zero = (csa_val == 8'd0);
    assign o_ref_busy = (acc != 8'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            sum_r   <= sum_n;
            carry_r <= carry_n;
            acc     <= acc + i_byte;
            if (i_close)
                armed <= 1'b0;
        end
    end

    // Absence, before first close: CSA-zero and reference-busy never together
    assert property (!armed || !(o_csa_zero && o_ref_busy));
endmodule

module ws2812_encoder (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire [23:0] color,
    output reg         dout,
    output wire        busy_o,
    output wire        ready
);
    localparam [31:0] T_BIT   = 32'd4;
    localparam [31:0] T_HI0   = 32'd1;
    localparam [31:0] T_HI1   = 32'd3;
    localparam [31:0] T_RESET = 32'd8;
    localparam [31:0] N_BITS  = 32'd24;
    localparam [31:0] K       = 32'd104;

    reg        busy        = 1'b0;
    reg        in_reset    = 1'b0;
    reg [31:0] shift       = 32'd0;
    reg [31:0] bit_cnt     = 32'd0;
    reg [31:0] pulse_timer = 32'd0;
    reg [31:0] gap_cnt     = 32'd0;
    reg [31:0] deadline    = 32'd0;

    assign busy_o = busy;
    assign ready  = !busy;

    always @(*) begin
        dout = busy && !in_reset && (pulse_timer < (shift[23] ? T_HI1 : T_HI0));
    end

    always @(posedge clk) begin
        if (rst) begin
            busy        <= 1'b0;
            in_reset    <= 1'b0;
            shift       <= 32'd0;
            bit_cnt     <= 32'd0;
            pulse_timer <= 32'd0;
            gap_cnt     <= 32'd0;
            deadline    <= 32'd0;
        end else if (ce) begin
            if (!busy) begin
                if (start) begin
                    busy        <= 1'b1;
                    in_reset    <= 1'b0;
                    shift       <= {8'd0, color};
                    bit_cnt     <= N_BITS;
                    pulse_timer <= 32'd0;
                    gap_cnt     <= 32'd0;
                    deadline    <= K;
                end
            end else begin
                deadline <= deadline - 32'd1;
                if (!in_reset) begin
                    if (pulse_timer == T_BIT - 32'd1) begin
                        pulse_timer <= 32'd0;
                        shift       <= shift << 1;
                        if (bit_cnt == 32'd1) begin
                            bit_cnt  <= 32'd0;
                            in_reset <= 1'b1;
                            gap_cnt  <= T_RESET;
                        end else begin
                            bit_cnt <= bit_cnt - 32'd1;
                        end
                    end else begin
                        pulse_timer <= pulse_timer + 32'd1;
                    end
                end else begin
                    if (gap_cnt == 32'd1) begin
                        gap_cnt  <= 32'd0;
                        in_reset <= 1'b0;
                        busy     <= 1'b0;
                    end else begin
                        gap_cnt <= gap_cnt - 32'd1;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        if (busy)
            assert (deadline != 32'd0);
endmodule

module tapeout_i2f (
    input wire clk,
    input wire en,
    input wire arm,
    input wire start,
    input wire [7:0] din,
    input wire q_sess,
    input wire r_sess,
    output reg [7:0] fout,
    output reg fin
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, NORM = 2'd2, DONE = 2'd3;

    reg [1:0] phase;
    reg arm_f, start_f;
    reg [7:0] mant;
    reg [3:0] exp;
    reg win;

    initial begin
        phase = IDLE; arm_f = 1'b0; start_f = 1'b0;
        mant = 8'd0; exp = 4'd0; fout = 8'd0; fin = 1'b0; win = 1'b0;
    end

    wire guard_b = mant[3];
    wire sticky_b = |mant[2:0];
    wire rup = guard_b && (sticky_b || mant[4]);
    wire [2:0] mfrac = mant[6:4];
    wire [2:0] mr = (rup && mfrac != 3'b111) ? (mfrac + 3'd1) : mfrac;
    wire [7:0] rounded = (mant == 8'd0) ? 8'd0 : {1'b0, exp, mr};

    always @(posedge clk) begin
        if (en) begin
            if (q_sess) begin
                win <= 1'b1;
                arm_f <= 1'b0;
                start_f <= 1'b0;
                phase <= IDLE;
                fin <= 1'b0;
            end else begin
                if (r_sess) win <= 1'b0;
                fin <= 1'b0;
                case (phase)
                    IDLE: if (arm) begin
                        mant <= din; exp <= 4'd7; arm_f <= 1'b1; phase <= ARMED;
                    end
                    ARMED: if (start) begin
                        start_f <= 1'b1; phase <= NORM;
                    end
                    NORM: begin
                        if (mant != 8'd0 && !mant[7]) begin
                            mant <= mant << 1;
                            exp <= exp - 4'd1;
                        end else begin
                            phase <= DONE;
                            fin <= 1'b1;
                            fout <= rounded;
                        end
                    end
                    DONE: if (arm) begin
                        mant <= din; exp <= 4'd7; arm_f <= 1'b1; phase <= ARMED;
                    end
                endcase
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $past(win) && fin)
            assert ($past(arm_f) && $past(start_f));
endmodule

module wl_map_scan (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [4:0] lblk,
    output reg busy,
    output reg done
);
    reg [4:0]  map_mem   [0:31];
    reg [15:0] erase_cnt [0:31];
    reg [5:0]  scan_idx;
    reg [5:0]  countdown;
    reg [4:0]  best_idx;
    reg [15:0] best_cnt;
    reg [4:0]  tgt;
    integer i;

    initial busy = 1'b0;
    initial done = 1'b0;
    initial scan_idx = 6'd0;
    initial countdown = 6'd0;
    initial best_idx = 5'd0;
    initial best_cnt = 16'hFFFF;
    initial tgt = 5'd0;
    initial begin
        for (i = 0; i < 32; i = i + 1) begin
            map_mem[i] = i;
            erase_cnt[i] = 16'd0;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            done <= 1'b0;
            scan_idx <= 6'd0;
            countdown <= 6'd0;
            best_idx <= 5'd0;
            best_cnt <= 16'hFFFF;
            tgt <= 5'd0;
            for (i = 0; i < 32; i = i + 1) begin
                map_mem[i] <= i;
                erase_cnt[i] <= 16'd0;
            end
        end else if (en) begin
            done <= 1'b0;
            if (!busy) begin
                if (req) begin
                    busy <= 1'b1;
                    tgt <= lblk;
                    scan_idx <= 6'd0;
                    countdown <= 6'd33;
                    best_cnt <= 16'hFFFF;
                end
            end else if (scan_idx < 6'd32) begin
                if (erase_cnt[scan_idx[4:0]] < best_cnt) begin
                    best_idx <= scan_idx[4:0];
                    best_cnt <= erase_cnt[scan_idx[4:0]];
                end
                scan_idx <= scan_idx + 6'd1;
                countdown <= countdown - 6'd1;
            end else if (scan_idx == 6'd32) begin
                map_mem[tgt] <= best_idx;
                if (erase_cnt[best_idx] != 16'hFFFF)
                    erase_cnt[best_idx] <= erase_cnt[best_idx] + 16'd1;
                busy <= 1'b0;
                countdown <= countdown - 6'd1;
                done <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (busy) assert (countdown != 6'd0);
endmodule

module mempool_bank_rdata_mux (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req_valid,
    input wire [3:0] req_bank,
    input wire [255:0] bank_rdata,
    output reg [15:0] rdata,
    output wire rvalid,
    output wire [15:0] o_rsp_cnt
);
    reg v_q0, v_q1, v_q2;
    reg [3:0] idx_q0, idx_q1, idx_q2;
    reg [15:0] sel_q0, sel_q1, sel_q2;
    reg [15:0] rsp_cnt;

    initial begin
        v_q0 = 1'b0; v_q1 = 1'b0; v_q2 = 1'b0;
        idx_q0 = 4'd0; idx_q1 = 4'd0; idx_q2 = 4'd0;
        sel_q0 = 16'h0000; sel_q1 = 16'h0000; sel_q2 = 16'h0000;
        rsp_cnt = 16'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            v_q0 <= 1'b0; v_q1 <= 1'b0; v_q2 <= 1'b0;
            idx_q0 <= 4'd0; idx_q1 <= 4'd0; idx_q2 <= 4'd0;
            sel_q0 <= 16'h0000; sel_q1 <= 16'h0000; sel_q2 <= 16'h0000;
            rsp_cnt <= 16'd0;
        end else if (en) begin
            v_q0 <= req_valid;
            idx_q0 <= req_bank;
            sel_q0 <= req_valid ? (16'h0001 << req_bank) : 16'h0000;
            v_q1 <= v_q0;
            idx_q1 <= idx_q0;
            sel_q1 <= sel_q0;
            v_q2 <= v_q1;
            idx_q2 <= idx_q1;
            sel_q2 <= sel_q1;
            if (v_q2)
                rsp_cnt <= rsp_cnt + 16'd1;
        end
    end

    integer b;
    always @(*) begin
        rdata = 16'h0000;
        for (b = 0; b < 16; b = b + 1)
            if (sel_q2[b])
                rdata = rdata | bank_rdata[b*16 +: 16];
    end

    assign rvalid = v_q2;
    assign o_rsp_cnt = rsp_cnt;

    always @(posedge clk)
        assert ((sel_q2 & (sel_q2 - 16'h0001)) == 16'h0000);
endmodule

module anl_dsp_simd_mul (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [1:0]  cfg_mode,
    input  wire        ld,
    input  wire [31:0] a_in,
    input  wire [31:0] b_in,
    input  wire        push,
    input  wire        pop,
    input  wire        start,
    input  wire        stop,
    output wire [63:0] o_head,
    output wire [31:0] o_occ,
    output wire        o_full,
    output wire        o_win
);
    reg [1:0]  mode_q;
    reg [31:0] a_q, b_q;
    reg [63:0] res_q;
    reg [63:0] buf_q0, buf_q1, buf_q2, buf_q3;
    reg [3:0]  valid_q;
    reg [31:0] occ_q;
    reg        win_q;

    initial begin
        mode_q  = 2'd0;
        a_q     = 32'd0;
        b_q     = 32'd0;
        res_q   = 64'd0;
        buf_q0  = 64'd0;
        buf_q1  = 64'd0;
        buf_q2  = 64'd0;
        buf_q3  = 64'd0;
        valid_q = 4'b0000;
        occ_q   = 32'd0;
        win_q   = 1'b0;
    end

    // lane-cut SIMD multiplier
    wire [63:0] p32   = {32'd0, a_q} * {32'd0, b_q};
    wire [31:0] p16_0 = {16'd0, a_q[15:0]}  * {16'd0, b_q[15:0]};
    wire [31:0] p16_1 = {16'd0, a_q[31:16]} * {16'd0, b_q[31:16]};
    wire [15:0] p8_0  = {8'd0, a_q[7:0]}   * {8'd0, b_q[7:0]};
    wire [15:0] p8_1  = {8'd0, a_q[15:8]}  * {8'd0, b_q[15:8]};
    wire [15:0] p8_2  = {8'd0, a_q[23:16]} * {8'd0, b_q[23:16]};
    wire [15:0] p8_3  = {8'd0, a_q[31:24]} * {8'd0, b_q[31:24]};

    reg [63:0] prod;
    always @(*) begin
        case (mode_q)
            2'd1:    prod = {p16_1, p16_0};
            2'd2:    prod = {p8_3, p8_2, p8_1, p8_0};
            default: prod = p32;
        endcase
    end

    // buffer slot selection
    reg [3:0] push_mask;
    always @(*) begin
        if (!valid_q[0])      push_mask = 4'b0001;
        else if (!valid_q[1]) push_mask = 4'b0010;
        else if (!valid_q[2]) push_mask = 4'b0100;
        else if (!valid_q[3]) push_mask = 4'b1000;
        else                  push_mask = 4'b0000;
    end
    wire [3:0] pop_mask = valid_q & (~valid_q + 4'd1);

    wire push_acc = push && !(&valid_q);
    wire pop_acc  = pop && (|valid_q);

    always @(posedge clk) begin
        if (rst) begin
            mode_q  <= 2'd0;
            a_q     <= 32'd0;
            b_q     <= 32'd0;
            res_q   <= 64'd0;
            buf_q0  <= 64'd0;
            buf_q1  <= 64'd0;
            buf_q2  <= 64'd0;
            buf_q3  <= 64'd0;
            valid_q <= 4'b0000;
            occ_q   <= 32'd0;
            win_q   <= 1'b0;
        end else if (en) begin
            if (ld) begin
                mode_q <= cfg_mode;
                a_q    <= a_in;
                b_q    <= b_in;
            end
            res_q <= prod;
            if (push_acc && push_mask[0]) buf_q0 <= res_q;
            if (push_acc && push_mask[1]) buf_q1 <= res_q;
            if (push_acc && push_mask[2]) buf_q2 <= res_q;
            if (push_acc && push_mask[3]) buf_q3 <= res_q;
            valid_q <= (valid_q | (push_acc ? push_mask : 4'b0000))
                       & ~(pop_acc ? pop_mask : 4'b0000);
            if (push_acc && !pop_acc)
                occ_q <= occ_q + 32'd1;
            else if (pop_acc && !push_acc)
                occ_q <= occ_q - 32'd1;
            if (start)
                win_q <= 1'b1;
            else if (stop)
                win_q <= 1'b0;
        end
    end

    assign o_head = valid_q[0] ? buf_q0 :
                    valid_q[1] ? buf_q1 :
                    valid_q[2] ? buf_q2 :
                    valid_q[3] ? buf_q3 : 64'd0;
    assign o_occ  = occ_q;
    assign o_full = &valid_q;
    assign o_win  = win_q;

    // Bounded existence: at most 4 results inside the observation window
    always @(*) assert (!win_q || occ_q <= 32'd4);
endmodule

module axis_luma_compressor (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        s_tvalid,
    input  wire        s_tuser,
    input  wire        s_tlast,
    input  wire [63:0] s_luma,
    input  wire [63:0] thr,
    input  wire [5:0]  ratio_sh,
    input  wire        eof,
    output wire        s_tready,
    output wire        m_tvalid,
    output wire        m_tuser,
    output wire        m_tlast,
    output wire [63:0] m_luma,
    output wire [63:0] o_gain,
    output wire [63:0] o_hist0,
    output wire        o_win
);
    localparam [63:0] UNITY = 64'h0000_0001_0000_0000;
    localparam [63:0] SLEW_LEN = 64'd8;

    reg [63:0] env;
    reg [63:0] gain;
    reg [63:0] tgt;
    reg        pend;
    reg [63:0] cd;
    reg [63:0] step;
    reg [63:0] hist [0:7];
    reg        win;

    integer i;
    initial begin
        env  = 64'd0;
        gain = UNITY;
        tgt  = UNITY;
        pend = 1'b0;
        cd   = 64'd0;
        step = 64'd0;
        win  = 1'b0;
        for (i = 0; i < 8; i = i + 1) hist[i] = UNITY;
    end

    assign s_tready = en;
    wire acc = en && s_tvalid;

    wire [63:0] reduction = (env > thr) ? ((env - thr) >> ratio_sh) : 64'd0;
    wire [63:0] new_tgt   = (reduction >= gain) ? 64'd0 : (gain - reduction);
    wire [63:0] gain_next = (tgt < gain) ? (gain - ((gain - tgt) >> 3))
                                         : (gain + ((tgt - gain) >> 3));
    wire [63:0] env_next  = (s_luma > env) ? (env + ((s_luma - env) >> 2))
                                           : (env - ((env - s_luma) >> 5));

    always @(posedge clk) begin
        if (rst) begin
            env  <= 64'd0;
            gain <= UNITY;
            tgt  <= UNITY;
            pend <= 1'b0;
            cd   <= 64'd0;
            step <= 64'd0;
            win  <= 1'b0;
            for (i = 0; i < 8; i = i + 1) hist[i] <= UNITY;
        end else if (en) begin
            if (acc)
                env <= env_next;
            if (!pend) begin
                if (acc && (env > thr)) begin
                    tgt  <= new_tgt;
                    pend <= 1'b1;
                    cd   <= SLEW_LEN;
                    step <= 64'd0;
                end
            end else begin
                gain <= gain_next;
                hist[step[2:0]] <= gain;
                cd   <= cd - 64'd1;
                step <= step + 64'd1;
                if (step == 64'd7)
                    pend <= 1'b0;
            end
            if (acc && s_tuser)
                win <= 1'b1;
            else if (eof)
                win <= 1'b0;
        end
    end

    wire [127:0] prod = s_luma * gain;
    assign m_luma   = prod[95:32];
    assign m_tvalid = s_tvalid;
    assign m_tuser  = s_tuser;
    assign m_tlast  = s_tlast;
    assign o_gain   = gain;
    assign o_hist0  = hist[0];
    assign o_win    = win;

    always @(*) assert (!(win && pend) || cd != 64'd0);
endmodule

module tf2_wrle (
    input wire clk,
    input wire rst,
    input wire en,
    input wire in_valid,
    input wire [15:0] in_data,
    input wire drain,
    output reg out_valid,
    output reg [15:0] out_val,
    output reg [15:0] out_cnt
);
    localparam [15:0] MAX = 16'd24;

    reg [15:0] cur;
    reg [15:0] cnt;
    reg [15:0] dl;
    reg busy;
    reg pre_drain;
    reg pv;

    initial begin
        cur = 16'd0;
        cnt = 16'd0;
        dl = 16'd0;
        busy = 1'b0;
        pre_drain = 1'b1;
        pv = 1'b0;
        out_valid = 1'b0;
        out_val = 16'd0;
        out_cnt = 16'd0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            cur <= 16'd0;
            cnt <= 16'd0;
            dl <= 16'd0;
            busy <= 1'b0;
            pre_drain <= 1'b1;
            out_valid <= 1'b0;
            out_val <= 16'd0;
            out_cnt <= 16'd0;
        end else if (en) begin
            out_valid <= 1'b0;
            if (drain) begin
                pre_drain <= 1'b0;
                if (busy) begin
                    out_valid <= 1'b1;
                    out_val <= cur;
                    out_cnt <= cnt;
                    busy <= 1'b0;
                    cnt <= 16'd0;
                    dl <= 16'd0;
                end
            end else if (in_valid) begin
                if (!busy) begin
                    cur <= in_data;
                    cnt <= 16'd1;
                    dl <= MAX;
                    busy <= 1'b1;
                end else if (in_data == cur && cnt < MAX) begin
                    cnt <= cnt + 16'd1;
                    dl <= dl - 16'd1;
                end else begin
                    out_valid <= 1'b1;
                    out_val <= cur;
                    out_cnt <= cnt;
                    cur <= in_data;
                    cnt <= 16'd1;
                    dl <= MAX;
                end
            end
        end
    end

    always @(posedge clk)
        if (pv && $past(pre_drain) && $past(busy))
            assert ($past(dl) != 16'd0);
endmodule

module hbpf_breathe (
    input  wire clk,
    input  wire en,
    output wire led
);
    localparam [63:0] STEP      = 64'h0000000100000000;
    localparam [63:0] NSTEPS    = 64'h0000000080000000;
    localparam [63:0] MAX       = 64'h8000000000000000;
    localparam [63:0] PRESC_MAX = 64'd999;

    reg [63:0] pwm_cnt  = 64'd0;
    reg [63:0] presc    = 64'd0;
    reg [63:0] pos      = 64'd0;
    reg [63:0] duty     = 64'd0;
    reg [63:0] headroom = 64'h8000000000000000;
    reg        dir        = 1'b1;
    reg        first_rise = 1'b1;

    assign led = (pwm_cnt < duty);

    wire tick = en && (presc == PRESC_MAX);

    always @(posedge clk) begin
        if (en) begin
            pwm_cnt <= pwm_cnt + 64'd1;
            if (presc == PRESC_MAX)
                presc <= 64'd0;
            else
                presc <= presc + 64'd1;
        end
        if (tick) begin
            if (dir) begin
                if (pos < NSTEPS) begin
                    pos      <= pos + 64'd1;
                    duty     <= duty + STEP;
                    headroom <= headroom - STEP;
                end else begin
                    dir        <= 1'b0;
                    first_rise <= 1'b0;
                end
            end else begin
                if (pos > 64'd0) begin
                    pos      <= pos - 64'd1;
                    duty     <= duty - STEP;
                    headroom <= headroom + STEP;
                end else begin
                    dir <= 1'b1;
                end
            end
        end
    end

    always @(posedge clk)
        if (first_rise)
            assert (duty <= MAX);

    always @(posedge clk)
        if (first_rise)
            assert (headroom <= MAX);
endmodule

module degate_trng_health (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [127:0] sample
);
    reg [127:0] last_smp = 128'd0;
    reg [127:0] ref_smp  = 128'd0;
    reg [127:0] hist [0:7];
    reg [2:0]   rep_cnt  = 3'd0;
    reg [2:0]   win_cnt  = 3'd0;
    reg [3:0]   apt_cnt  = 4'd0;
    reg         alarm    = 1'b0;
    reg         armed    = 1'b0;
    reg         pv       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            hist[i] = 128'd0;
    end

    wire       rep_match = (sample == last_smp);
    wire [2:0] rep_nxt   = rep_match ? ((rep_cnt == 3'd7) ? 3'd7 : rep_cnt + 3'd1) : 3'd0;

    reg [3:0] apt_nxt;
    reg [2:0] win_nxt;
    always @(*) begin
        if (win_cnt == 3'd0) begin
            apt_nxt = 4'd1;
            win_nxt = 3'd1;
        end else if (win_cnt == 3'd7) begin
            apt_nxt = 4'd0;
            win_nxt = 3'd0;
        end else begin
            apt_nxt = apt_cnt + ((sample == ref_smp) ? 4'd1 : 4'd0);
            win_nxt = win_cnt + 3'd1;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            last_smp <= 128'd0;
            ref_smp  <= 128'd0;
            rep_cnt  <= 3'd0;
            win_cnt  <= 3'd0;
            apt_cnt  <= 4'd0;
            alarm    <= 1'b0;
            armed    <= 1'b0;
        end else if (en) begin
            hist[win_cnt] <= sample;
            last_smp <= sample;
            rep_cnt  <= rep_nxt;
            if (win_cnt == 3'd0)
                ref_smp <= sample;
            apt_cnt  <= apt_nxt;
            win_cnt  <= win_nxt;
            if (rep_nxt >= 3'd5 || apt_nxt >= 4'd6)
                alarm <= 1'b1;
            if (win_cnt == 3'd7)
                armed <= 1'b1;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (pv && !rst && armed && $stable(alarm))
            assert (!(apt_cnt[3] && win_cnt != 3'd0));
    end
endmodule

module lvds_port_perfmon (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         valid,
    input  wire         ready,
    input  wire [127:0] data,
    input  wire         win_start,
    output wire [31:0]  o_txn_cnt,
    output wire [35:0]  o_byte_cnt,
    output wire [31:0]  o_stall_cnt,
    output wire [47:0]  o_lat_cum,
    output wire [15:0]  o_win_cnt
);
    wire hs    = en & valid & ready;
    wire stall = en & valid & ~ready;

    reg [31:0] txn_cnt   = 32'd0;
    reg        hs_d      = 1'b0;
    reg [35:0] byte_cnt  = 36'd0;
    reg [31:0] stall_cnt = 32'd0;
    reg [15:0] lat_cur   = 16'd0;
    reg [47:0] lat_cum   = 48'd0;
    reg [15:0] win_cnt   = 16'd0;
    reg        armed     = 1'b0;
    reg        seen_txn  = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            txn_cnt   <= 32'd0;
            hs_d      <= 1'b0;
            byte_cnt  <= 36'd0;
            stall_cnt <= 32'd0;
            lat_cur   <= 16'd0;
            lat_cum   <= 48'd0;
            win_cnt   <= 16'd0;
            armed     <= 1'b0;
            seen_txn  <= 1'b0;
        end else if (en) begin
            hs_d <= hs;
            if (hs) begin
                txn_cnt  <= txn_cnt + 32'd1;
                seen_txn <= 1'b1;
                lat_cum  <= lat_cum + {32'd0, lat_cur};
                lat_cur  <= 16'd0;
            end else if (valid) begin
                lat_cur  <= lat_cur + 16'd1;
            end
            if (hs_d)
                byte_cnt <= byte_cnt + 36'd16;
            if (stall)
                stall_cnt <= stall_cnt + 32'd1;
            if (win_start) begin
                win_cnt <= 16'd0;
                armed   <= 1'b1;
            end else begin
                win_cnt <= win_cnt + 16'd1;
            end
        end
    end

    assign o_txn_cnt   = txn_cnt;
    assign o_byte_cnt  = byte_cnt;
    assign o_stall_cnt = stall_cnt;
    assign o_lat_cum   = lat_cum;
    assign o_win_cnt   = win_cnt;

    always @(posedge clk)
        if (armed && byte_cnt != 36'd0)
            assert (seen_txn);
endmodule

module stream_trap (
    input wire clk,
    input wire rst,
    input wire en,
    input wire fault_valid,
    input wire [63:0] fault_cause,
    input wire [63:0] frame_addr,
    input wire mret,
    input wire resume,
    input wire host_arm,
    input wire host_disarm,
    output reg in_trap,
    output reg stream_active
);
    localparam [63:0] DEPTH_MAX = 64'hFFFF_FFFF_FFFF_FFFF;

    reg [63:0] cause;
    reg [63:0] epc;
    reg [63:0] status;
    reg [63:0] trap_depth;
    reg [63:0] log_mem [0:31];
    reg [4:0]  log_ptr;
    reg        win;
    reg        pv;
    integer i;

    initial begin
        cause = 64'd0;
        epc = 64'd0;
        status = 64'd0;
        trap_depth = 64'd0;
        in_trap = 1'b0;
        stream_active = 1'b0;
        log_ptr = 5'd0;
        win = 1'b0;
        pv = 1'b0;
        for (i = 0; i < 32; i = i + 1) log_mem[i] = 64'd0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            cause <= 64'd0;
            epc <= 64'd0;
            status <= 64'd0;
            trap_depth <= 64'd0;
            in_trap <= 1'b0;
            stream_active <= 1'b0;
            log_ptr <= 5'd0;
            win <= 1'b0;
            for (i = 0; i < 32; i = i + 1) log_mem[i] <= 64'd0;
        end else if (en) begin
            if (host_disarm) win <= 1'b0;
            else if (host_arm) win <= 1'b1;

            if (fault_valid) begin
                cause <= fault_cause;
                epc <= frame_addr;
                status <= {status[63:1], stream_active};
                log_mem[log_ptr] <= fault_cause;
                log_ptr <= log_ptr + 5'd1;
                if (trap_depth != DEPTH_MAX) trap_depth <= trap_depth + 64'd1;
                in_trap <= 1'b1;
                stream_active <= 1'b0;
            end else if (mret && trap_depth != 64'd0) begin
                trap_depth <= trap_depth - 64'd1;
                if (trap_depth == 64'd1) begin
                    in_trap <= 1'b0;
                    stream_active <= status[0];
                end
            end else if (resume && trap_depth == 64'd0) begin
                stream_active <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (pv && !rst && win && stream_active && !$past(stream_active))
            assert (!in_trap);
endmodule

module yat_phase_ring (
    input  wire        clk,
    input  wire        rst,
    input  wire        advance,
    output wire [31:0] fetch_phase,
    output wire [31:0] exec_phase
);
    reg [31:0] fetch_ring;
    reg [31:0] exec_ring;

    initial fetch_ring = 32'h00000000;
    initial exec_ring  = 32'h00000000;

    // Fetch-side Johnson phase token
    always @(posedge clk) begin
        if (rst)
            fetch_ring <= 32'h00000000;
        else if (advance)
            fetch_ring <= {fetch_ring[30:0], ~fetch_ring[31]};
    end

    // Execute-side shadow ring checked by the hazard unit
    always @(posedge clk) begin
        if (rst)
            exec_ring <= 32'h00000000;
        else if (advance)
            exec_ring <= {exec_ring[30:0], ~exec_ring[31]};
    end

    assign fetch_phase = fetch_ring;
    assign exec_phase  = exec_ring;

    assert property (fetch_ring[31] == exec_ring[31]);
endmodule

module tx_pace_tq (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         wr,
    input  wire         wr_idx,
    input  wire [127:0] wr_data,
    input  wire         ack,
    input  wire         clr,
    output reg          fire,
    output reg          done
);
    reg [127:0] now;
    reg [127:0] dl0, dl1;
    reg [1:0]   vld;
    reg         eidx;
    reg [1:0]   phase;
    reg         started, finished, win;

    initial begin
        now = 128'd0; dl0 = 128'd0; dl1 = 128'd0; vld = 2'b00; eidx = 1'b0;
        phase = 2'd0; started = 1'b0; finished = 1'b0; win = 1'b0;
        fire = 1'b0; done = 1'b0;
    end

    wire [127:0] dl_e     = eidx ? dl1 : dl0;
    wire         start_ok = (phase == 2'd1) && vld[eidx] && (now >= dl_e);
    wire         fin_ok   = (phase == 2'd2) && ack;
    wire [1:0]   vld_clr  = (fin_ok && !clr) ? (vld & ~(2'b01 << eidx)) : vld;
    wire [1:0]   vld_n    = wr ? (vld_clr | (2'b01 << wr_idx)) : vld_clr;
    wire         eidx_n   = (vld == 2'b10) ? 1'b1 :
                            (vld == 2'b11) ? (dl1 < dl0) : 1'b0;

    always @(posedge clk) begin
        if (en) begin
            if (rst) begin
                now <= 128'd0; vld <= 2'b00; eidx <= 1'b0;
                phase <= 2'd0; started <= 1'b0; finished <= 1'b0; win <= 1'b0;
                fire <= 1'b0; done <= 1'b0;
            end else begin
                now  <= now + 128'd1;
                fire <= 1'b0;
                done <= 1'b0;
                eidx <= eidx_n;
                vld  <= vld_n;
                if (wr) begin
                    if (wr_idx) dl1 <= wr_data;
                    else        dl0 <= wr_data;
                end
                if (clr) begin
                    phase <= 2'd0; started <= 1'b0; finished <= 1'b0; win <= 1'b0;
                end else begin
                    case (phase)
                        2'd0: if (wr) begin phase <= 2'd1; win <= 1'b1; end
                        2'd1: if (start_ok) begin phase <= 2'd2; started <= 1'b1; fire <= 1'b1; end
                        2'd2: if (fin_ok) begin phase <= 2'd3; finished <= 1'b1; done <= 1'b1; end
                        default: ;
                    endcase
                end
            end
        end
    end

    always @(posedge clk)
        if (win && finished)
            assert (started);
endmodule

module hadesv_mie_jk (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire j,
    input wire k,
    input wire trap_enter,
    input wire mret,
    output reg q,
    output reg [31:0] tcnt,
    output reg in_trap
);
    initial q = 1'b0;
    initial tcnt = 32'h00000000;
    initial in_trap = 1'b0;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    wire q_next = (j & ~k) ? 1'b1 :
                  (~j & k) ? 1'b0 :
                  (j & k)  ? ~q   : q;

    always @(posedge clk) begin
        if (!rst_n) begin
            q <= 1'b0;
            tcnt <= 32'h00000000;
            in_trap <= 1'b0;
        end else if (en) begin
            q <= q_next;
            if (q_next != q)
                tcnt <= tcnt + 32'h00000001;
            if (mret)
                in_trap <= 1'b0;
            else if (trap_enter)
                in_trap <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (pv && rst_n && in_trap && $rose(q))
            assert (tcnt[0] == 1'b1);
    end
endmodule

module rgmii_relay_fifo (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [3:0]  rxd_rise,
    input  wire [3:0]  rxd_fall,
    input  wire        ctl_rise,
    input  wire        ctl_fall,
    input  wire        rd_en,
    output wire [31:0] dout,
    output wire        empty,
    output wire [31:0] o_occ
);
    reg [4:0]  cap_rise;
    reg [4:0]  cap_fall;
    reg [1:0]  byte_ph;
    reg [23:0] shift;
    reg [31:0] mem [0:3];
    reg [31:0] wr_cnt;
    reg [31:0] rd_cnt;
    reg [31:0] occ;
    reg        armed;

    initial begin
        cap_rise = 5'd0;
        cap_fall = 5'd0;
        byte_ph  = 2'd0;
        shift    = 24'd0;
        mem[0]   = 32'd0;
        mem[1]   = 32'd0;
        mem[2]   = 32'd0;
        mem[3]   = 32'd0;
        wr_cnt   = 32'd0;
        rd_cnt   = 32'd0;
        occ      = 32'd0;
        armed    = 1'b0;
    end

    wire       rx_dv   = cap_rise[4];
    wire [7:0] rx_byte = {cap_fall[3:0], cap_rise[3:0]};
    wire [31:0] diff   = wr_cnt - rd_cnt;
    wire       full    = (diff == 32'd4);
    wire       push    = en && rx_dv && (byte_ph == 2'd3) && !full;
    wire       pop     = en && rd_en && (wr_cnt != rd_cnt);

    always @(posedge clk) begin
        if (rst) begin
            cap_rise <= 5'd0;
            cap_fall <= 5'd0;
            byte_ph  <= 2'd0;
            shift    <= 24'd0;
            mem[0]   <= 32'd0;
            mem[1]   <= 32'd0;
            mem[2]   <= 32'd0;
            mem[3]   <= 32'd0;
            wr_cnt   <= 32'd0;
            rd_cnt   <= 32'd0;
            occ      <= 32'd0;
            armed    <= 1'b0;
        end else if (en) begin
            cap_rise <= {ctl_rise, rxd_rise};
            cap_fall <= {ctl_fall, rxd_fall};
            armed    <= armed | rx_dv;
            if (rx_dv) begin
                byte_ph <= byte_ph + 2'd1;
                case (byte_ph)
                    2'd0: shift[7:0]   <= rx_byte;
                    2'd1: shift[15:8]  <= rx_byte;
                    2'd2: shift[23:16] <= rx_byte;
                    default: ;
                endcase
            end
            if (push) begin
                mem[wr_cnt[1:0]] <= {rx_byte, shift};
                wr_cnt <= wr_cnt + 32'd1;
            end
            if (pop)
                rd_cnt <= rd_cnt + 32'd1;
            occ <= occ + (push ? 32'd1 : 32'd0) - (pop ? 32'd1 : 32'd0);
        end
    end

    assign dout  = mem[rd_cnt[1:0]];
    assign empty = (wr_cnt == rd_cnt);
    assign o_occ = occ;

    always @(posedge clk)
        if (armed)
            assert (occ <= 32'd4);
endmodule

module gf180_tapline_cal (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire [63:0] din,
    input  wire        cal_start,
    input  wire        cal_done,
    output wire [63:0] dout,
    output wire [7:0]  tok_o,
    output wire [63:0] cal_cnt_o,
    output wire        win_o
);
    reg [63:0] tap  [0:7];
    reg [63:0] samp [0:7];
    reg [7:0]  tok;
    reg        win;
    reg [63:0] cal_cnt;
    integer i;

    initial begin
        for (i = 0; i < 8; i = i + 1) begin
            tap[i]  = 64'd0;
            samp[i] = 64'd0;
        end
        tok     = 8'd0;
        win     = 1'b0;
        cal_cnt = 64'd0;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 8; i = i + 1) begin
                tap[i]  <= 64'd0;
                samp[i] <= 64'd0;
            end
            tok     <= 8'd0;
            win     <= 1'b0;
            cal_cnt <= 64'd0;
        end else if (en) begin
            tap[0] <= din;
            for (i = 1; i < 8; i = i + 1)
                tap[i] <= tap[i-1];
            for (i = 0; i < 8; i = i + 1)
                samp[i] <= tap[i];
            if (cal_start) begin
                win     <= 1'b1;
                tok     <= 8'b0000_0001;
                cal_cnt <= 64'd0;
            end else if (cal_done) begin
                win <= 1'b0;
                tok <= 8'd0;
            end else if (win) begin
                tok <= tok << 1;
                if (cal_cnt != 64'hFFFF_FFFF_FFFF_FFFF)
                    cal_cnt <= cal_cnt + 64'd1;
            end else begin
                tok <= 8'd0;
            end
        end
    end

    assign dout      = samp[7];
    assign tok_o     = tok;
    assign cal_cnt_o = cal_cnt;
    assign win_o     = win;

    always @(*)
        if (win)
            assert (!(tok[6] && tok[7]));
endmodule

module tc_trace_cache (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [1:0]   op,
    input  wire [3:0]   idx,
    input  wire [31:0]  fill_start,
    input  wire [3:0]   fill_flags,
    input  wire [127:0] fill_instr,
    input  wire [31:0]  fill_next,
    input  wire         trace_begin,
    input  wire         trace_end,
    input  wire [31:0]  fetch_pc,
    output reg          hit,
    output reg  [3:0]   hit_idx,
    output reg  [3:0]   hit_flags,
    output reg  [127:0] hit_instr,
    output reg  [31:0]  hit_next
);
    reg [15:0] valid = 16'h0000;
    reg [31:0] occ   = 32'd0;
    reg        win   = 1'b0;

    reg [31:0] start_addr [0:15];
    reg [3:0]  br_flags   [0:15];
    reg [31:0] slot       [0:63];
    reg [31:0] next_fa    [0:15];

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) begin
            start_addr[i] = 32'd0;
            br_flags[i]   = 4'd0;
            next_fa[i]    = 32'd0;
        end
        for (i = 0; i < 64; i = i + 1)
            slot[i] = 32'd0;
    end

    // control state: valid, occupancy, window
    always @(posedge clk) begin
        if (!rst_n) begin
            valid <= 16'h0000;
            occ   <= 32'd0;
            win   <= 1'b0;
        end else if (en) begin
            case (op)
                2'd1: begin
                    valid[idx] <= 1'b1;
                    if (!valid[idx]) occ <= occ + 32'd1;
                end
                2'd2: begin
                    valid[idx] <= 1'b0;
                    if (valid[idx]) occ <= occ - 32'd1;
                end
                2'd3: begin
                    valid <= 16'h0000;
                    occ   <= 32'd0;
                end
                default: ;
            endcase
            if (trace_begin)
                win <= 1'b1;
            else if (trace_end || op == 2'd3)
                win <= 1'b0;
        end
    end

    // data storage
    always @(posedge clk) begin
        if (rst_n && en && op == 2'd1) begin
            start_addr[idx]        <= fill_start;
            br_flags[idx]          <= fill_flags;
            next_fa[idx]           <= fill_next;
            slot[{idx, 2'd0}]      <= fill_instr[31:0];
            slot[{idx, 2'd1}]      <= fill_instr[63:32];
            slot[{idx, 2'd2}]      <= fill_instr[95:64];
            slot[{idx, 2'd3}]      <= fill_instr[127:96];
        end
    end

    // combinational lookup
    integer j;
    always @(*) begin
        hit     = 1'b0;
        hit_idx = 4'd0;
        for (j = 15; j >= 0; j = j - 1) begin
            if (valid[j] && start_addr[j] == fetch_pc) begin
                hit     = 1'b1;
                hit_idx = j[3:0];
            end
        end
        hit_flags = br_flags[hit_idx];
        hit_next  = next_fa[hit_idx];
        hit_instr = {slot[{hit_idx, 2'd3}], slot[{hit_idx, 2'd2}],
                     slot[{hit_idx, 2'd1}], slot[{hit_idx, 2'd0}]};
    end

    // properties
    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $stable(valid))
            assert ($stable(occ));

    always @(posedge clk)
        if (win)
            assert (occ <= 32'd16);
endmodule

module zynq_pwr_dom (
    input  wire       clk,
    input  wire       en,
    input  wire       req_on,
    input  wire       req_off,
    input  wire [6:0] idx,
    output wire       root_ready,
    output wire       busy
);
    reg [127:0] dom_on;
    reg [7:0]   refcnt;
    reg         root_on;
    reg         pend;
    reg [7:0]   prog;
    reg [7:0]   cd;
    reg         first_n;
    reg         pv;

    initial dom_on  = 128'd0;
    initial refcnt  = 8'd0;
    initial root_on = 1'b0;
    initial pend    = 1'b0;
    initial prog    = 8'd0;
    initial cd      = 8'd0;
    initial first_n = 1'b1;
    initial pv      = 1'b0;

    wire do_on  = req_on && !req_off;
    wire do_off = req_off && !req_on && !pend;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (en) begin
            if (pend) begin
                prog <= prog + 8'd1;
                cd   <= cd - 8'd1;
                if (prog == 8'd19) begin
                    pend    <= 1'b0;
                    root_on <= 1'b1;
                end
            end
            if (do_on && !dom_on[idx]) begin
                dom_on[idx] <= 1'b1;
                refcnt      <= refcnt + 8'd1;
                if (refcnt == 8'd0 && !root_on && !pend) begin
                    pend <= 1'b1;
                    prog <= 8'd0;
                    cd   <= 8'd24;
                end
            end else if (do_off && dom_on[idx]) begin
                dom_on[idx] <= 1'b0;
                refcnt      <= refcnt - 8'd1;
                if (refcnt == 8'd1 && root_on) begin
                    root_on <= 1'b0;
                    first_n <= 1'b0;
                end
            end
        end
    end

    assign root_ready = root_on;
    assign busy       = pend;

    always @(posedge clk)
        if (pv && first_n && pend && $stable(pend))
            assert ($stable(cd == 8'd0) && cd != 8'd0);
endmodule

module mmio_router_tmo (
    input wire clk,
    input wire en,
    input wire cfg_we,
    input wire [5:0] cfg_idx,
    input wire [63:0] cfg_base,
    input wire [63:0] cfg_limit,
    input wire req,
    input wire [63:0] req_addr,
    input wire win_clr,
    output wire o_busy,
    output wire o_win,
    output wire [5:0] o_sel
);
    localparam [63:0] K = 64'd16;

    reg [63:0] base  [0:63];
    reg [63:0] limit [0:63];
    reg        busy;
    reg        win;
    reg [5:0]  sel;
    reg [63:0] cnt;
    reg [63:0] age;

    integer i;
    initial begin
        busy = 1'b0;
        win  = 1'b0;
        sel  = 6'd0;
        cnt  = 64'd0;
        age  = 64'd0;
        for (i = 0; i < 64; i = i + 1) begin
            base[i]  = 64'd0;
            limit[i] = 64'd0;
        end
    end

    reg       hit;
    reg [5:0] hidx;
    integer j;
    always @(*) begin
        hit  = 1'b0;
        hidx = 6'd0;
        for (j = 63; j >= 0; j = j - 1) begin
            if ((base[j] <= req_addr) && (req_addr <= limit[j])) begin
                hit  = 1'b1;
                hidx = j[5:0];
            end
        end
    end

    wire accept = req && hit && !busy;

    always @(posedge clk) begin
        if (en) begin
            if (cfg_we) begin
                base[cfg_idx]  <= cfg_base;
                limit[cfg_idx] <= cfg_limit;
            end
            if (win_clr)
                win <= 1'b0;
            else if (accept)
                win <= 1'b1;
            if (busy) begin
                if (age == K - 64'd1) begin
                    busy <= 1'b0;
                    cnt  <= 64'd0;
                    age  <= 64'd0;
                end else begin
                    cnt <= cnt - 64'd1;
                    age <= age + 64'd1;
                end
            end else if (accept) begin
                busy <= 1'b1;
                sel  <= hidx;
                cnt  <= K;
                age  <= 64'd0;
            end
        end
    end

    assign o_busy = busy;
    assign o_win  = win;
    assign o_sel  = sel;

    always @(posedge clk)
        if (win && busy)
            assert (cnt != 64'd0);

    always @(posedge clk)
        if (win && busy)
            assert (cnt <= K);
endmodule

module hft_feed_switch (
    input  wire         clk,
    input  wire         en,
    input  wire [3:0]   s_tvalid,
    input  wire [511:0] s_tdata,
    input  wire [7:0]   s_tdest,
    input  wire [3:0]   s_tlast,
    output wire [3:0]   s_tready,
    output wire [3:0]   m_tvalid,
    output wire [511:0] m_tdata,
    output wire [3:0]   m_tlast,
    input  wire [3:0]   m_tready
);
    reg [7:0] sel_o  = 8'd0;
    reg [3:0] lock_o = 4'd0;
    reg [3:0] busy_i = 4'd0;
    reg [7:0] dst_i  = 8'd0;
    reg       win    = 1'b0;

    genvar g;
    generate
        for (g = 0; g < 4; g = g + 1) begin : g_out
            wire [1:0] s = sel_o[2*g +: 2];
            assign m_tvalid[g] = lock_o[g] && s_tvalid[s];
            assign m_tdata[128*g +: 128] = s_tdata[{s, 7'd0} +: 128];
            assign m_tlast[g] = s_tlast[s];
        end
        for (g = 0; g < 4; g = g + 1) begin : g_in
            wire [1:0] d = dst_i[2*g +: 2];
            assign s_tready[g] = en && busy_i[g] && m_tready[d];
        end
    endgenerate

    wire [3:0] rel = {4{en}} & lock_o & m_tvalid & m_tready & m_tlast;

    reg [3:0] gnt_v;
    reg [7:0] gnt_i;
    integer i, j;
    always @(*) begin
        gnt_v = 4'd0;
        gnt_i = 8'd0;
        for (j = 0; j < 4; j = j + 1) begin
            if (!lock_o[j]) begin
                for (i = 3; i >= 0; i = i - 1) begin
                    if (s_tvalid[i] && s_tdest[2*i +: 2] == j && !busy_i[i]) begin
                        gnt_v[j] = 1'b1;
                        gnt_i[2*j +: 2] = i;
                    end
                end
            end
        end
    end

    reg [3:0] lock_n, busy_n;
    reg [7:0] sel_n, dst_n;
    reg       win_n;
    always @(*) begin
        lock_n = lock_o;
        busy_n = busy_i;
        sel_n  = sel_o;
        dst_n  = dst_i;
        win_n  = win;
        for (j = 0; j < 4; j = j + 1) begin
            if (rel[j]) begin
                lock_n[j] = 1'b0;
                for (i = 0; i < 4; i = i + 1)
                    if (sel_o[2*j +: 2] == i) busy_n[i] = 1'b0;
            end
        end
        for (j = 0; j < 4; j = j + 1) begin
            if (gnt_v[j]) begin
                lock_n[j] = 1'b1;
                sel_n[2*j +: 2] = gnt_i[2*j +: 2];
                for (i = 0; i < 4; i = i + 1) begin
                    if (gnt_i[2*j +: 2] == i) begin
                        busy_n[i] = 1'b1;
                        dst_n[2*i +: 2] = j;
                    end
                end
            end
        end
        if (gnt_v[0]) win_n = 1'b1;
        else if (rel[0]) win_n = 1'b0;
    end

    always @(posedge clk) begin
        if (en) begin
            lock_o <= lock_n;
            busy_i <= busy_n;
            sel_o  <= sel_n;
            dst_i  <= dst_n;
            win    <= win_n;
        end
    end

    assert property (!(win && lock_o[0]) || ((!lock_o[1] || sel_o[3:2] != sel_o[1:0]) && (!lock_o[2] || sel_o[5:4] != sel_o[1:0]) && (!lock_o[3] || sel_o[7:6] != sel_o[1:0])));
endmodule

module tile_rf_led (
    input wire clk,
    input wire rst,
    input wire en,
    input wire ld,
    input wire [63:0] ld_data,
    input wire consume,
    input wire reshape,
    input wire [4:0] new_rows,
    output wire o_full,
    output wire [63:0] o_row0,
    output wire [63:0] o_fill
);
    localparam [4:0] DEF_ROWS = 5'd12;
    localparam [4:0] MAX_ROWS = 5'd16;

    reg [63:0] mem [0:15];
    reg [4:0] wptr;
    reg [63:0] fill_cnt;
    reg [4:0] shape_rows;
    reg pristine;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) mem[i] = 64'd0;
        wptr = 5'd0;
        fill_cnt = 64'd0;
        shape_rows = DEF_ROWS;
        pristine = 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 5'd0;
            fill_cnt <= 64'd0;
            shape_rows <= DEF_ROWS;
            pristine <= 1'b1;
        end else if (en) begin
            if (consume) begin
                wptr <= 5'd0;
                fill_cnt <= 64'd0;
            end else if (ld && (wptr != shape_rows)) begin
                mem[wptr[3:0]] <= ld_data;
                wptr <= wptr + 5'd1;
                fill_cnt <= fill_cnt + 64'd1;
            end else if (reshape && (wptr == 5'd0)) begin
                shape_rows <= (new_rows > MAX_ROWS) ? MAX_ROWS : new_rows;
                pristine <= 1'b0;
            end
        end
    end

    assign o_full = (wptr == shape_rows);
    assign o_row0 = mem[0];
    assign o_fill = fill_cnt;

    always @(posedge clk)
        if (pristine)
            assert (fill_cnt <= 64'd12);
endmodule

module da_fir4 (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        start,
    input  wire [31:0] d0,
    input  wire [31:0] d1,
    input  wire [31:0] d2,
    input  wire [31:0] d3,
    output wire [63:0] y,
    output wire        done
);
    // fixed coefficients C0..C3 = 3, 5, 7, 11
    function [31:0] rom;
        input [3:0] a;
        begin
            case (a)
                4'd0:  rom = 32'd0;
                4'd1:  rom = 32'd3;
                4'd2:  rom = 32'd5;
                4'd3:  rom = 32'd8;
                4'd4:  rom = 32'd7;
                4'd5:  rom = 32'd10;
                4'd6:  rom = 32'd12;
                4'd7:  rom = 32'd15;
                4'd8:  rom = 32'd11;
                4'd9:  rom = 32'd14;
                4'd10: rom = 32'd16;
                4'd11: rom = 32'd19;
                4'd12: rom = 32'd18;
                4'd13: rom = 32'd21;
                4'd14: rom = 32'd23;
                default: rom = 32'd26;
            endcase
        end
    endfunction

    reg [31:0] x0, x1, x2, x3;
    reg [63:0] acc;
    reg [31:0] cnt;
    reg [31:0] rem;
    reg        busy;
    reg        win;

    initial x0 = 32'd0;
    initial x1 = 32'd0;
    initial x2 = 32'd0;
    initial x3 = 32'd0;
    initial acc = 64'd0;
    initial cnt = 32'd0;
    initial rem = 32'd32;
    initial busy = 1'b0;
    initial win = 1'b0;

    wire [3:0]  addr  = {x3[0], x2[0], x1[0], x0[0]};
    wire [63:0] slice = {32'd0, rom(addr)} << cnt;

    always @(posedge clk) begin
        if (rst) begin
            x0   <= 32'd0;
            x1   <= 32'd0;
            x2   <= 32'd0;
            x3   <= 32'd0;
            acc  <= 64'd0;
            cnt  <= 32'd0;
            rem  <= 32'd32;
            busy <= 1'b0;
            win  <= 1'b0;
        end else if (en) begin
            if (!busy) begin
                if (start) begin
                    x0   <= d0;
                    x1   <= d1;
                    x2   <= d2;
                    x3   <= d3;
                    acc  <= 64'd0;
                    cnt  <= 32'd0;
                    rem  <= 32'd32;
                    busy <= 1'b1;
                    win  <= 1'b1;
                end
            end else begin
                acc <= acc + slice;
                x0  <= {1'b0, x0[31:1]};
                x1  <= {1'b0, x1[31:1]};
                x2  <= {1'b0, x2[31:1]};
                x3  <= {1'b0, x3[31:1]};
                cnt <= cnt + 32'd1;
                rem <= rem - 32'd1;
                if (cnt == 32'd31) begin
                    busy <= 1'b0;
                    win  <= 1'b0;
                end
            end
        end
    end

    assign y    = acc;
    assign done = busy && en && (cnt == 32'd31);

    // A1 / A2: bounded counts inside the window
    always @(*) if (win) assert (cnt <= 32'd32);
    always @(*) if (win) assert (rem <= 32'd32);
endmodule

module therm_totalizer (
    input  wire        clk,
    input  wire        en,
    input  wire [63:0] therm,
    output wire [63:0] out
);
    // popcount encoder
    reg [6:0] cnt;
    integer k;
    always @(*) begin
        cnt = 7'd0;
        for (k = 0; k < 64; k = k + 1)
            cnt = cnt + {6'd0, therm[k]};
    end

    wire [63:0] addend = {57'd0, cnt};

    reg [63:0] rca_sum;
    reg [63:0] cla_sum;
    reg        armed;
    reg        pv;
    initial rca_sum = 64'd0;
    initial cla_sum = 64'd0;
    initial armed   = 1'b0;
    initial pv      = 1'b0;

    // ripple-carry adder
    wire [64:0] rc;
    wire [63:0] rca_next;
    assign rc[0] = 1'b0;
    genvar i;
    generate
        for (i = 0; i < 64; i = i + 1) begin : g_rca
            assign rca_next[i] = rca_sum[i] ^ addend[i] ^ rc[i];
            assign rc[i+1] = (rca_sum[i] & addend[i]) | (rc[i] & (rca_sum[i] ^ addend[i]));
        end
    endgenerate

    // carry-lookahead adder, 4-bit groups
    wire [63:0] cg = cla_sum & addend;
    wire [63:0] cp = cla_sum ^ addend;
    wire [63:0] cc;
    wire [16:0] gcarry;
    wire [63:0] cla_next;
    assign gcarry[0] = 1'b0;
    genvar j;
    generate
        for (j = 0; j < 16; j = j + 1) begin : g_cla
            wire g0 = cg[4*j];   wire p0 = cp[4*j];
            wire g1 = cg[4*j+1]; wire p1 = cp[4*j+1];
            wire g2 = cg[4*j+2]; wire p2 = cp[4*j+2];
            wire g3 = cg[4*j+3]; wire p3 = cp[4*j+3];
            wire c0 = gcarry[j];
            assign cc[4*j]   = c0;
            assign cc[4*j+1] = g0 | (p0 & c0);
            assign cc[4*j+2] = g1 | (p1 & g0) | (p1 & p0 & c0);
            assign cc[4*j+3] = g2 | (p2 & g1) | (p2 & p1 & g0) | (p2 & p1 & p0 & c0);
            wire GG = g3 | (p3 & g2) | (p3 & p2 & g1) | (p3 & p2 & p1 & g0);
            wire PP = p3 & p2 & p1 & p0;
            assign gcarry[j+1] = GG | (PP & c0);
        end
    endgenerate
    assign cla_next = cp ^ cc;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (en) begin
            rca_sum <= rca_next;
            cla_sum <= cla_next;
            armed   <= armed | therm[63];
        end
    end

    assign out = rca_sum;

    always @(posedge clk)
        if (pv && armed && $past(en))
            assert (rca_sum == $past(cla_sum) + {57'd0, $past(cnt)});
endmodule

module dbg_failover_mux (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       en,
    input  wire [7:0] pri_data,
    input  wire [7:0] bak_data,
    input  wire       pri_fault,
    input  wire       pri_ok,
    output wire [7:0] out_data
);
    reg [7:0] health     = 8'd0;
    reg       arm_f      = 1'b0;
    reg       start_f    = 1'b0;
    reg       fin_f      = 1'b0;
    reg       active_src = 1'b0;
    reg       pv         = 1'b0;

    assign out_data = active_src ? bak_data : pri_data;

    always @(posedge clk) begin
        if (!rst_n) begin
            health     <= 8'd0;
            arm_f      <= 1'b0;
            start_f    <= 1'b0;
            fin_f      <= 1'b0;
            active_src <= 1'b0;
        end else if (en) begin
            if (pri_ok && fin_f && active_src) begin
                health     <= 8'd0;
                arm_f      <= 1'b0;
                start_f    <= 1'b0;
                fin_f      <= 1'b0;
                active_src <= 1'b0;
            end else begin
                if (pri_fault && health != 8'hFF)
                    health <= health + 8'd1;
                if (health >= 8'd3 && !arm_f)
                    arm_f <= 1'b1;
                if (arm_f && pri_fault && !start_f)
                    start_f <= 1'b1;
                if (start_f && !fin_f)
                    fin_f <= 1'b1;
                if (start_f && arm_f && !active_src)
                    active_src <= 1'b1;
            end
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $stable(fin_f))
            assert ($stable(active_src));
endmodule

module orbit_mrs_unit (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        req_valid,
    input  wire [2:0]  req_idx,
    input  wire [15:0] req_data,
    input  wire        cfg_lock,
    output wire        busy,
    output reg         mrs_cmd_valid,
    output reg  [18:0] mrs_cmd
);
    reg [15:0] shadow [0:7];
    reg [7:0]  pend;
    reg [2:0]  cur_idx;
    reg [15:0] cur_data;
    reg [15:0] cnt;
    reg        win;
    integer i;

    initial begin
        for (i = 0; i < 8; i = i + 1) shadow[i] = 16'd0;
        pend = 8'd0;
        cur_idx = 3'd0;
        cur_data = 16'd0;
        cnt = 16'd0;
        win = 1'b0;
        mrs_cmd_valid = 1'b0;
        mrs_cmd = 19'd0;
    end

    assign busy = |pend;

    wire accept   = req_valid && !busy;
    wire countdn  = busy && (cnt > 16'd1);
    wire complete = busy && (cnt == 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 8; i = i + 1) shadow[i] <= 16'd0;
            pend <= 8'd0;
            cur_idx <= 3'd0;
            cur_data <= 16'd0;
            cnt <= 16'd0;
            win <= 1'b0;
            mrs_cmd_valid <= 1'b0;
            mrs_cmd <= 19'd0;
        end else if (en) begin
            mrs_cmd_valid <= 1'b0;
            if (accept) begin
                pend[req_idx] <= 1'b1;
                cur_idx <= req_idx;
                cur_data <= req_data;
                cnt <= 16'd8;
                mrs_cmd_valid <= 1'b1;
                mrs_cmd <= {req_idx, req_data};
            end else if (countdn) begin
                cnt <= cnt - 16'd1;
            end else if (complete) begin
                for (i = 0; i < 8; i = i + 1)
                    if (cur_idx == i[2:0]) shadow[i] <= cur_data;
                pend[cur_idx] <= 1'b0;
                cnt <= 16'd0;
            end
            if (accept)
                win <= 1'b1;
            else if (cfg_lock)
                win <= 1'b0;
        end
    end

    always @(posedge clk)
        if (win && busy) assert (cnt != 16'd0);
endmodule

module dram_ret_est (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire [3:0] x,
    output wire [7:0] est
);
    reg [7:0] tiv0, tiv1, tiv2, tiv3;
    reg [7:0] to0, to1, to2, to3;
    reg [3:0] idx1, idx2;
    reg [7:0] tiv_r, to_r, sum_q;
    reg       arm;

    initial begin
        tiv0 = 8'd200; tiv1 = 8'd150; tiv2 = 8'd100; tiv3 = 8'd60;
        to0  = 8'd0;   to1  = 8'd12;  to2  = 8'd24;  to3  = 8'd36;
        idx1 = 4'd0; tiv_r = 8'd200; to_r = 8'd0;
        idx2 = 4'd0; sum_q = 8'd200; arm = 1'b0;
    end

    wire [7:0] tiv_sel = (x[3:2] == 2'd0) ? tiv0 :
                         (x[3:2] == 2'd1) ? tiv1 :
                         (x[3:2] == 2'd2) ? tiv2 : tiv3;
    wire [7:0] to_sel  = (x[1:0] == 2'd0) ? to0 :
                         (x[1:0] == 2'd1) ? to1 :
                         (x[1:0] == 2'd2) ? to2 : to3;

    always @(posedge clk) begin
        if (rst) begin
            tiv0 <= 8'd200; tiv1 <= 8'd150; tiv2 <= 8'd100; tiv3 <= 8'd60;
            to0  <= 8'd0;   to1  <= 8'd12;  to2  <= 8'd24;  to3  <= 8'd36;
            idx1 <= 4'd0; tiv_r <= 8'd200; to_r <= 8'd0;
            idx2 <= 4'd0; sum_q <= 8'd200; arm <= 1'b0;
        end else if (en) begin
            idx1  <= x;
            tiv_r <= tiv_sel;
            to_r  <= to_sel;
            idx2  <= idx1;
            sum_q <= tiv_r + to_r;
            arm   <= 1'b1;
        end
    end

    assign est = sum_q;

    wire [7:0] exp_tiv2 = (idx2[3:2] == 2'd0) ? 8'd200 :
                          (idx2[3:2] == 2'd1) ? 8'd150 :
                          (idx2[3:2] == 2'd2) ? 8'd100 : 8'd60;
    wire [7:0] exp_to2  = (idx2[1:0] == 2'd0) ? 8'd0 :
                          (idx2[1:0] == 2'd1) ? 8'd12 :
                          (idx2[1:0] == 2'd2) ? 8'd24 : 8'd36;
    wire [7:0] exp_sum2 = exp_tiv2 + exp_to2;

    always @(posedge clk)
        if (arm)
            assert (sum_q == exp_sum2);
endmodule

module sd_line_fill_uart #(
    parameter [15:0] CLKS_PER_BIT = 16'd16
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        rx,
    input  wire        flush,
    output wire [15:0] o_occ,
    output wire        o_full,
    output wire        o_ferr,
    output wire [15:0] o_word0
);
    localparam [1:0] S_IDLE  = 2'd0;
    localparam [1:0] S_START = 2'd1;
    localparam [1:0] S_DATA  = 2'd2;
    localparam [1:0] S_STOP  = 2'd3;

    reg [1:0]  st;
    reg [15:0] baud_cnt;
    reg [15:0] bit_cnt;
    reg [15:0] shreg;
    reg [15:0] line [0:7];
    reg [2:0]  wr_ptr;
    reg [15:0] occ;
    reg        line_full;
    reg        frame_err;
    reg        armed;
    reg        rx_prev;

    integer i;
    initial begin
        st = S_IDLE;
        baud_cnt = 16'd0;
        bit_cnt = 16'd0;
        shreg = 16'd0;
        wr_ptr = 3'd0;
        occ = 16'd0;
        line_full = 1'b0;
        frame_err = 1'b0;
        armed = 1'b0;
        rx_prev = 1'b1;
        for (i = 0; i < 8; i = i + 1) line[i] = 16'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            st <= S_IDLE;
            baud_cnt <= 16'd0;
            bit_cnt <= 16'd0;
            shreg <= 16'd0;
            wr_ptr <= 3'd0;
            occ <= 16'd0;
            line_full <= 1'b0;
            frame_err <= 1'b0;
            armed <= 1'b0;
            rx_prev <= 1'b1;
        end else if (en) begin
            rx_prev <= rx;
            case (st)
                S_IDLE: begin
                    baud_cnt <= 16'd0;
                    bit_cnt <= 16'd0;
                    if (rx_prev && !rx) st <= S_START;
                end
                S_START: begin
                    if (baud_cnt == (CLKS_PER_BIT >> 1) - 16'd1) begin
                        baud_cnt <= 16'd0;
                        if (!rx) st <= S_DATA;
                        else st <= S_IDLE;
                    end else begin
                        baud_cnt <= baud_cnt + 16'd1;
                    end
                end
                S_DATA: begin
                    if (baud_cnt == CLKS_PER_BIT - 16'd1) begin
                        baud_cnt <= 16'd0;
                        shreg <= {rx, shreg[15:1]};
                        if (bit_cnt == 16'd15) begin
                            bit_cnt <= 16'd0;
                            st <= S_STOP;
                        end else begin
                            bit_cnt <= bit_cnt + 16'd1;
                        end
                    end else begin
                        baud_cnt <= baud_cnt + 16'd1;
                    end
                end
                S_STOP: begin
                    if (baud_cnt == CLKS_PER_BIT - 16'd1) begin
                        baud_cnt <= 16'd0;
                        st <= S_IDLE;
                        if (!rx) begin
                            frame_err <= 1'b1;
                        end else if (!line_full) begin
                            line[wr_ptr] <= shreg;
                            wr_ptr <= wr_ptr + 3'd1;
                            occ <= occ + 16'd1;
                            line_full <= ((occ + 16'd1) == 16'd8);
                            armed <= 1'b1;
                        end
                    end else begin
                        baud_cnt <= baud_cnt + 16'd1;
                    end
                end
            endcase
            if (flush) begin
                occ <= 16'd0;
                wr_ptr <= 3'd0;
                line_full <= 1'b0;
                frame_err <= 1'b0;
            end
        end
    end

    assign o_occ = occ;
    assign o_full = line_full;
    assign o_ferr = frame_err;
    assign o_word0 = line[0];

    always @(posedge clk)
        if (armed)
            assert (occ <= 16'd8);
endmodule

module perfect_id_rom (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    output wire [31:0] rdata,
    output wire        last
);
    localparam [31:0] ROM_VENDOR    = 32'h49424D00;
    localparam [31:0] ROM_PART      = 32'h50455246;
    localparam [31:0] ROM_REVISION  = 32'h00000003;
    localparam [31:0] ROM_FEAT0     = 32'h0000C3A5;
    localparam [31:0] ROM_FEAT1     = 32'h00000011;
    localparam [31:0] ROM_SIGNATURE = 32'h43484933;
    localparam [31:0] LAST_IDX      = 32'd5;

    reg [31:0] ptr;
    reg [31:0] remaining;
    reg [31:0] rdata_q;
    initial begin
        ptr       = 32'd0;
        remaining = LAST_IDX;
        rdata_q   = 32'd0;
    end

    reg [31:0] rom_word;
    always @(*) begin
        case (ptr)
            32'd0:   rom_word = ROM_VENDOR;
            32'd1:   rom_word = ROM_PART;
            32'd2:   rom_word = ROM_REVISION;
            32'd3:   rom_word = ROM_FEAT0;
            32'd4:   rom_word = ROM_FEAT1;
            32'd5:   rom_word = ROM_SIGNATURE;
            default: rom_word = 32'd0;
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            ptr       <= 32'd0;
            remaining <= LAST_IDX;
            rdata_q   <= 32'd0;
        end else if (en) begin
            rdata_q   <= rom_word;
            ptr       <= (remaining == 32'd0) ? 32'd0 : ptr + 32'd1;
            remaining <= (ptr == LAST_IDX) ? LAST_IDX : remaining - 32'd1;
        end
    end

    assign rdata = rdata_q;
    assign last  = (remaining == 32'd0);

    assert property (ptr <= 32'd5);
    assert property (remaining <= 32'd5);
endmodule

module json_key_fuzzy_match (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [7:0] key_in,
    input wire [7:0] query,
    input wire ld_tol,
    input wire [3:0] tol_in,
    input wire q_open,
    input wire q_close,
    output reg near,
    output reg far,
    output reg win
);
    reg [3:0] tol;
    reg pv;
    initial tol = 4'd0;
    initial near = 1'b0;
    initial far = 1'b1;
    initial win = 1'b0;
    initial pv = 1'b0;

    wire [7:0] diff = key_in ^ query;
    wire [3:0] dist = {3'd0, diff[0]} + {3'd0, diff[1]} + {3'd0, diff[2]} + {3'd0, diff[3]}
                    + {3'd0, diff[4]} + {3'd0, diff[5]} + {3'd0, diff[6]} + {3'd0, diff[7]};
    wire near_nxt = (dist <= tol);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            tol  <= 4'd0;
            near <= 1'b0;
            far  <= 1'b1;
            win  <= 1'b0;
        end else if (en) begin
            if (ld_tol) tol <= tol_in;
            near <= near_nxt;
            far  <= far ^ (near ^ near_nxt);
            win  <= q_open ? 1'b1 : (q_close ? 1'b0 : win);
        end
    end

    always @(posedge clk)
        if (pv && $past(win))
            assert (!($past(near) && $past(far)));
endmodule

module monocle_bscan (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        capture,
    input  wire        update,
    input  wire        shift,
    input  wire        tdi,
    input  wire [23:0] pins_in,
    output wire        tdo,
    output wire [23:0] pins_out
);
    reg [23:0] shift_reg   = 24'd0;
    reg [23:0] update_reg  = 24'd0;
    reg [15:0] shifted_cnt = 16'd0;
    reg [15:0] remain_cnt  = 16'd24;
    reg        armed       = 1'b0;

    assign tdo      = shift_reg[0];
    assign pins_out = update_reg;

    wire frame_full  = (remain_cnt == 16'd0);
    wire frame_empty = (shifted_cnt == 16'd0);

    always @(posedge clk) begin
        if (!rst_n) begin
            shift_reg   <= 24'd0;
            update_reg  <= 24'd0;
            shifted_cnt <= 16'd0;
            remain_cnt  <= 16'd24;
            armed       <= 1'b0;
        end else if (en) begin
            if (capture) begin
                shift_reg   <= pins_in;
                shifted_cnt <= 16'd0;
                remain_cnt  <= 16'd24;
                armed       <= 1'b1;
            end else if (update) begin
                update_reg  <= shift_reg;
                shifted_cnt <= 16'd0;
                remain_cnt  <= 16'd24;
            end else if (shift && (remain_cnt != 16'd0)) begin
                shift_reg   <= {tdi, shift_reg[23:1]};
                shifted_cnt <= shifted_cnt + 16'd1;
                remain_cnt  <= remain_cnt - 16'd1;
            end
        end
    end

    always @(*)
        if (armed)
            assert (!(frame_full && frame_empty));
endmodule

module friscv_hart_rst_sync (
    input wire clk,
    input wire arst_n,
    input wire en,
    input wire soft_req,
    output wire hart_rst_n
);
    reg [3:0]  sync = 4'b0000;
    reg [63:0] cnt  = 64'd0;
    reg        pend = 1'b0;
    reg        win  = 1'b0;

    always @(posedge clk or negedge arst_n) begin
        if (!arst_n) begin
            sync <= 4'b0000;
            cnt  <= 64'd0;
            pend <= 1'b0;
            win  <= 1'b0;
        end else if (en) begin
            if (soft_req && !pend) begin
                sync <= 4'b0000;
                cnt  <= 64'd6;
                pend <= 1'b1;
                win  <= 1'b1;
            end else if (pend && sync != 4'b1111) begin
                sync <= {sync[2:0], 1'b1};
                cnt  <= cnt - 64'd1;
            end else if (pend) begin
                pend <= 1'b0;
                win  <= 1'b0;
            end
        end
    end

    assign hart_rst_n = sync[3];

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $rose(sync[3]))
            assert (cnt != 64'd0);
endmodule

module hack_rowfix (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [63:0] row_addr,
    input wire fuse_load,
    input wire [3:0] fuse_idx,
    input wire [63:0] fuse_val,
    input wire fuse_reload,
    output reg [4:0] spare_sel,
    output reg [63:0] row_out
);
    reg [63:0] fuse_addr [0:15];
    reg [15:0] fuse_en;
    reg [63:0] lat_addr;
    reg busy;
    reg [4:0] idx;
    reg [63:0] cnt;
    reg hit;
    reg [3:0] hit_slot;
    reg pre_ev;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) fuse_addr[i] = 64'd0;
    end
    initial fuse_en = 16'd0;
    initial lat_addr = 64'd0;
    initial busy = 1'b0;
    initial idx = 5'd0;
    initial cnt = 64'd0;
    initial hit = 1'b0;
    initial hit_slot = 4'd0;
    initial pre_ev = 1'b1;
    initial spare_sel = 5'd0;
    initial row_out = 64'd0;

    // combinational compare of the current 4-entry window
    reg win_hit;
    reg [3:0] win_slot;
    reg [3:0] s;
    integer k;
    always @(*) begin
        win_hit = 1'b0;
        win_slot = 4'd0;
        s = 4'd0;
        for (k = 3; k >= 0; k = k - 1) begin
            s = idx[3:0] + k;
            if (fuse_en[s] && (fuse_addr[s] == lat_addr)) begin
                win_hit = 1'b1;
                win_slot = s;
            end
        end
    end

    wire fin_hit = hit | win_hit;
    wire [3:0] fin_slot = hit ? hit_slot : win_slot;

    always @(posedge clk) begin
        if (rst) begin
            fuse_en <= 16'd0;
            lat_addr <= 64'd0;
            busy <= 1'b0;
            idx <= 5'd0;
            cnt <= 64'd0;
            hit <= 1'b0;
            hit_slot <= 4'd0;
            pre_ev <= 1'b1;
            spare_sel <= 5'd0;
            row_out <= 64'd0;
        end else if (en) begin
            if (fuse_load) begin
                fuse_addr[fuse_idx] <= fuse_val;
                fuse_en[fuse_idx] <= 1'b1;
            end
            if (fuse_reload) begin
                idx <= 5'd0;
                pre_ev <= 1'b0;
            end else if (busy) begin
                if (win_hit && !hit) begin
                    hit <= 1'b1;
                    hit_slot <= win_slot;
                end
                if (idx == 5'd12) begin
                    busy <= 1'b0;
                    if (fin_hit) begin
                        spare_sel <= {1'b1, fin_slot};
                        row_out <= 64'hFFFF_FFFF_FFFF_FFF0 | {60'd0, fin_slot};
                    end else begin
                        spare_sel <= 5'd0;
                        row_out <= lat_addr;
                    end
                end else begin
                    idx <= idx + 5'd4;
                    cnt <= cnt - 64'd1;
                end
            end else if (req) begin
                lat_addr <= row_addr;
                busy <= 1'b1;
                idx <= 5'd0;
                cnt <= 64'd4;
                hit <= 1'b0;
            end
        end
    end

    always @(*)
        if (pre_ev && busy)
            assert ((cnt != 64'd0) && (idx < 5'd16));
endmodule

module golay_scrub (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        wr,
    input  wire [3:0]  wr_addr,
    input  wire [11:0] wr_data,
    input  wire        inj,
    input  wire [3:0]  inj_addr,
    input  wire [23:0] inj_mask,
    input  wire        scrub_start,
    input  wire        scrub_done,
    output wire [31:0] o_corr_cnt,
    output wire [31:0] o_inj_cnt,
    output wire [11:0] o_syn,
    output wire        o_win
);
    function [11:0] brow;
        input [3:0] idx;
        begin
            case (idx)
                4'd0:  brow = 12'hDC5;
                4'd1:  brow = 12'hB8B;
                4'd2:  brow = 12'h717;
                4'd3:  brow = 12'hE2D;
                4'd4:  brow = 12'hC5B;
                4'd5:  brow = 12'h8B7;
                4'd6:  brow = 12'h16F;
                4'd7:  brow = 12'h2DD;
                4'd8:  brow = 12'h5B9;
                4'd9:  brow = 12'hB71;
                4'd10: brow = 12'h6E3;
                default: brow = 12'hFFE;
            endcase
        end
    endfunction

    function [11:0] mulB;
        input [11:0] v;
        integer j;
        begin
            mulB = 12'h000;
            for (j = 0; j < 12; j = j + 1)
                if (v[j]) mulB = mulB ^ brow(j);
        end
    endfunction

    function [3:0] wt12;
        input [11:0] v;
        integer j;
        begin
            wt12 = 4'd0;
            for (j = 0; j < 12; j = j + 1)
                wt12 = wt12 + {3'b000, v[j]};
        end
    endfunction

    function [23:0] encode;
        input [11:0] d;
        begin
            encode = {d, mulB(d)};
        end
    endfunction

    function [11:0] syndrome;
        input [23:0] r;
        begin
            syndrome = mulB(r[23:12]) ^ r[11:0];
        end
    endfunction

    function [23:0] golay_err;
        input [11:0] s;
        reg [11:0] s2;
        reg found;
        integer j;
        begin
            golay_err = 24'h000000;
            found = 1'b0;
            if (wt12(s) <= 4'd3) begin
                golay_err = {12'h000, s};
                found = 1'b1;
            end
            for (j = 0; j < 12; j = j + 1)
                if (!found && (wt12(s ^ brow(j)) <= 4'd2)) begin
                    golay_err = {(12'h001 << j), (s ^ brow(j))};
                    found = 1'b1;
                end
            s2 = mulB(s);
            if (!found && (wt12(s2) <= 4'd3)) begin
                golay_err = {s2, 12'h000};
                found = 1'b1;
            end
            for (j = 0; j < 12; j = j + 1)
                if (!found && (wt12(s2 ^ brow(j)) <= 4'd2)) begin
                    golay_err = {(s2 ^ brow(j)), (12'h001 << j)};
                    found = 1'b1;
                end
        end
    endfunction

    reg [23:0] mem [0:15];
    reg [15:0] err_flag;
    reg [11:0] syn_reg;
    reg [3:0]  scan_ptr;
    reg [31:0] inj_cnt;
    reg [31:0] corr_cnt;
    reg        inj_seen;
    reg        win;
    integer k;

    initial begin
        for (k = 0; k < 16; k = k + 1)
            mem[k] = 24'h000000;
        err_flag = 16'h0000;
        syn_reg  = 12'h000;
        scan_ptr = 4'd0;
        inj_cnt  = 32'd0;
        corr_cnt = 32'd0;
        inj_seen = 1'b0;
        win      = 1'b0;
    end

    wire [23:0] cur     = mem[scan_ptr];
    wire [11:0] cur_syn = syndrome(cur);
    wire [23:0] cur_err = golay_err(cur_syn);

    always @(posedge clk) begin
        if (rst) begin
            for (k = 0; k < 16; k = k + 1)
                mem[k] <= 24'h000000;
            err_flag <= 16'h0000;
            syn_reg  <= 12'h000;
            scan_ptr <= 4'd0;
            inj_cnt  <= 32'd0;
            corr_cnt <= 32'd0;
            inj_seen <= 1'b0;
            win      <= 1'b0;
        end else if (en) begin
            if (scrub_start)
                win <= 1'b1;
            else if (scrub_done)
                win <= 1'b0;
            if (win) begin
                syn_reg <= cur_syn;
                if (err_flag[scan_ptr]) begin
                    mem[scan_ptr]      <= cur ^ cur_err;
                    err_flag[scan_ptr] <= 1'b0;
                    corr_cnt           <= corr_cnt + 32'd1;
                end
                scan_ptr <= scan_ptr + 4'd1;
            end
            if (inj) begin
                mem[inj_addr]      <= mem[inj_addr] ^ inj_mask;
                err_flag[inj_addr] <= 1'b1;
                inj_cnt            <= inj_cnt + 32'd1;
                inj_seen           <= 1'b1;
            end
            if (wr) begin
                mem[wr_addr]      <= encode(wr_data);
                err_flag[wr_addr] <= 1'b0;
            end
        end
    end

    assign o_corr_cnt = corr_cnt;
    assign o_inj_cnt  = inj_cnt;
    assign o_syn      = syn_reg;
    assign o_win      = win;

    assert property (!(win && corr_cnt != 32'd0) || inj_seen);
endmodule

module hdmi_line_window (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        line_start,
    input  wire        line_stop,
    input  wire [31:0] sample_in,
    output reg  [31:0] y
);
    reg [31:0] win_rom [0:255];
    reg [31:0] idx;
    reg [31:0] dn;
    reg        win;

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) begin
            if (i < 128)
                win_rom[i] = i * i * 4;
            else
                win_rom[i] = (255 - i) * (255 - i) * 4;
        end
    end

    initial begin
        idx = 32'd0;
        dn  = 32'd255;
        win = 1'b0;
        y   = 32'd0;
    end

    wire [32:0] coef_sum = {1'b0, win_rom[idx[7:0]]} + {1'b0, win_rom[dn[7:0]]};
    wire [31:0] coef     = coef_sum[32:1];
    wire [63:0] prod     = sample_in * coef;

    always @(posedge clk) begin
        if (rst) begin
            idx <= 32'd0;
            dn  <= 32'd255;
            win <= 1'b0;
            y   <= 32'd0;
        end else if (en) begin
            if (dn == 32'd0) begin
                idx <= 32'd0;
                dn  <= 32'd255;
            end else begin
                idx <= idx + 32'd1;
                dn  <= dn - 32'd1;
            end
            win <= line_start ? 1'b1 : (line_stop ? 1'b0 : win);
            y   <= prod[31:0];
        end
    end

    assert property (!win || idx <= 32'd255);
endmodule

module jls_pausible_clkctl (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire areq,
    input wire mutex_gnt,
    input wire [31:0] din,
    input wire sof,
    input wire eof,
    input wire [7:0] raddr,
    output wire [31:0] dout,
    output wire ring_clk_en
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, STARTED = 2'd2;

    reg [1:0] phase = 2'd0;
    reg hs_latch = 1'b0;
    reg clk_en = 1'b1;
    reg [31:0] arm_cnt = 32'd0;
    reg [31:0] start_cnt = 32'd0;
    reg [31:0] fin_cnt = 32'd0;
    reg [7:0] wptr = 8'd0;
    reg win = 1'b0;
    reg [31:0] linebuf [0:255];

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1)
            linebuf[i] = 32'd0;
    end

    assign dout = linebuf[raddr];
    assign ring_clk_en = clk_en;

    always @(posedge clk) begin
        if (!rst_n) begin
            phase <= IDLE;
            hs_latch <= 1'b0;
            clk_en <= 1'b1;
            arm_cnt <= 32'd0;
            start_cnt <= 32'd0;
            fin_cnt <= 32'd0;
            wptr <= 8'd0;
            win <= 1'b0;
        end else if (en) begin
            if (eof)
                win <= 1'b0;
            else if (sof)
                win <= 1'b1;
            case (phase)
                IDLE: begin
                    if (areq) begin
                        hs_latch <= 1'b1;
                        phase <= ARMED;
                        arm_cnt <= arm_cnt + 32'd1;
                    end
                end
                ARMED: begin
                    if (mutex_gnt) begin
                        clk_en <= 1'b0;
                        phase <= STARTED;
                        start_cnt <= start_cnt + 32'd1;
                    end
                end
                STARTED: begin
                    wptr <= wptr + 8'd1;
                    hs_latch <= 1'b0;
                    clk_en <= 1'b1;
                    phase <= IDLE;
                    fin_cnt <= fin_cnt + 32'd1;
                end
                default: begin
                    phase <= IDLE;
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst_n && en && phase == STARTED)
            linebuf[wptr] <= din;
    end

    always @(posedge clk)
        if (win && phase == 2'd2)
            assert (arm_cnt == start_cnt && start_cnt == fin_cnt + 32'd1 && !clk_en);
endmodule

module neo_ringstop (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        ring_in_vld,
    input  wire [63:0] ring_in_data,
    input  wire [3:0]  ring_in_dst,
    input  wire        push,
    input  wire [63:0] push_data,
    input  wire [3:0]  my_id,
    output wire        ring_hold,
    output wire        eject_vld,
    output wire [63:0] eject_data,
    output wire        out_vld,
    output wire [63:0] out_data,
    output wire [3:0]  out_dst
);
    reg        slot_vld = 1'b0;
    reg [63:0] slot_data = 64'd0;
    reg [3:0]  slot_dst = 4'd0;
    reg [63:0] fifo [0:15];
    reg [4:0]  q_head = 5'd0;
    reg [4:0]  q_tail = 5'd0;
    reg [4:0]  q_count = 5'd0;
    reg [63:0] starve_cnt = 64'd0;
    reg        rsv = 1'b0;
    reg [63:0] inj_total = 64'd0;
    reg        pre_rsv = 1'b1;
    reg        pv = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) fifo[i] = 64'd0;
    end

    wire through   = ring_in_vld && (ring_in_dst != my_id);
    wire nonempty  = (q_head != q_tail);
    wire free_slot = (!through) || rsv;
    wire pop       = nonempty && free_slot;
    wire push_ok   = push && (q_count < 5'd16);
    wire dec       = pop && (q_count != 5'd0);

    assign ring_hold  = rsv && through;
    assign eject_vld  = ring_in_vld && (ring_in_dst == my_id);
    assign eject_data = ring_in_data;
    assign out_vld    = slot_vld;
    assign out_data   = slot_data;
    assign out_dst    = slot_dst;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            slot_vld   <= 1'b0;
            slot_data  <= 64'd0;
            slot_dst   <= 4'd0;
            q_head     <= 5'd0;
            q_tail     <= 5'd0;
            q_count    <= 5'd0;
            starve_cnt <= 64'd0;
            rsv        <= 1'b0;
            inj_total  <= 64'd0;
            pre_rsv    <= 1'b1;
        end else if (en) begin
            if (pop) begin
                slot_vld  <= 1'b1;
                slot_data <= fifo[q_head[3:0]];
                slot_dst  <= fifo[q_head[3:0]][3:0];
                q_head    <= q_head + 5'd1;
                inj_total <= inj_total + 64'd1;
            end else if (through) begin
                slot_vld  <= 1'b1;
                slot_data <= ring_in_data;
                slot_dst  <= ring_in_dst;
            end else begin
                slot_vld  <= 1'b0;
            end

            if (push_ok) begin
                fifo[q_tail[3:0]] <= push_data;
                q_tail <= q_tail + 5'd1;
            end

            q_count <= q_count + {4'd0, push_ok} - {4'd0, dec};

            if (pop)
                starve_cnt <= 64'd0;
            else if (nonempty)
                starve_cnt <= starve_cnt + 64'd1;

            if (pop)
                rsv <= 1'b0;
            else if (starve_cnt == 64'd1000) begin
                rsv     <= 1'b1;
                pre_rsv <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (pv && !$past(rst) && pre_rsv && $stable(q_tail) && $stable(q_count))
            assert ($stable(q_head));
endmodule

module hfrisc_ctx_save_mux (
    input  wire          clk,
    input  wire          rst,
    input  wire          en,
    input  wire [1023:0] rf_flat,
    output reg  [31:0]   dout
);
    reg [31:0] sel;
    reg [4:0]  idx;
    initial begin
        sel = 32'h00000001;
        idx = 5'd0;
    end

    wire [4:0] idx_n = idx + 5'd1;

    always @(posedge clk) begin
        if (rst) begin
            sel <= 32'h00000001;
            idx <= 5'd0;
        end else if (en) begin
            sel <= sel ^ (32'h00000001 << idx) ^ (32'h00000001 << idx_n);
            idx <= idx_n;
        end
    end

    integer i;
    always @(*) begin
        dout = 32'h00000000;
        for (i = 0; i < 32; i = i + 1)
            dout = dout | (rf_flat[i*32 +: 32] & {32{sel[i]}});
    end

    always @(*) assert ((sel != 32'h00000000) && ((sel & (sel - 32'h00000001)) == 32'h00000000));
endmodule

module babysoc_padmux (
    input wire clk,
    input wire rst,
    input wire en,
    input wire wr,
    input wire [2:0] wr_idx,
    input wire [2:0] wr_func,
    input wire lock_req,
    input wire [7:0] gpio_out,
    input wire pll_clk,
    input wire dac_bit,
    input wire uart_tx,
    output wire [7:0] pad_out,
    output wire o_err,
    output wire o_locked
);
    reg [23:0] func_sel;
    reg [31:0] wr_cnt;
    reg [31:0] cm_cnt;
    reg err;
    reg locked;
    reg pre_lock;
    integer k;

    initial begin
        func_sel = 24'd0;
        wr_cnt = 32'd0;
        cm_cnt = 32'd0;
        err = 1'b0;
        locked = 1'b0;
        pre_lock = 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            func_sel <= 24'd0;
            wr_cnt <= 32'd0;
            cm_cnt <= 32'd0;
            err <= 1'b0;
            locked <= 1'b0;
            pre_lock <= 1'b1;
        end else if (en) begin
            if (wr && !locked) begin
                for (k = 0; k < 8; k = k + 1)
                    if (wr_idx == k) func_sel[k*3 +: 3] <= wr_func;
                wr_cnt <= wr_cnt + 32'd1;
                cm_cnt <= cm_cnt + 32'd1;
            end
            err <= err | (wr_cnt != cm_cnt);
            if (lock_req) begin
                locked <= 1'b1;
                pre_lock <= 1'b0;
            end
        end
    end

    genvar g;
    generate
        for (g = 0; g < 8; g = g + 1) begin : pads
            wire [2:0] fs = func_sel[g*3 +: 3];
            assign pad_out[g] = (fs == 3'd0) ? gpio_out[g] :
                                (fs == 3'd1) ? pll_clk :
                                (fs == 3'd2) ? dac_bit :
                                (fs == 3'd3) ? uart_tx : 1'b0;
        end
    endgenerate

    assign o_err = err;
    assign o_locked = locked;

    always @(posedge clk)
        if (pre_lock)
            assert (!err);
endmodule

module hdlbits_cam (
    input wire clk,
    input wire rst,
    input wire en,
    input wire lookup,
    input wire [63:0] lookup_key,
    input wire wr_en,
    input wire wr_idx,
    input wire [63:0] wr_key,
    output wire hit,
    output wire [1:0] hit_vec
);
    reg [63:0] key_mem [0:1];
    reg [1:0] valid;
    reg s1_vld;
    reg [31:0] s1_key_hi;
    reg [1:0] s1_pm;
    reg s2_vld;
    reg [1:0] s2_match;
    reg [63:0] inflight;
    reg armed;

    initial key_mem[0] = 64'd0;
    initial key_mem[1] = 64'd0;
    initial valid = 2'b00;
    initial s1_vld = 1'b0;
    initial s1_key_hi = 32'd0;
    initial s1_pm = 2'b00;
    initial s2_vld = 1'b0;
    initial s2_match = 2'b00;
    initial inflight = 64'd0;
    initial armed = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            key_mem[0] <= 64'd0;
            key_mem[1] <= 64'd0;
            valid <= 2'b00;
            s1_vld <= 1'b0;
            s1_key_hi <= 32'd0;
            s1_pm <= 2'b00;
            s2_vld <= 1'b0;
            s2_match <= 2'b00;
            inflight <= 64'd0;
            armed <= 1'b0;
        end else if (en) begin
            if (wr_en) begin
                key_mem[wr_idx] <= wr_key;
                valid[wr_idx] <= 1'b1;
            end
            s1_vld <= lookup;
            s1_key_hi <= lookup_key[63:32];
            s1_pm[0] <= valid[0] & (key_mem[0][31:0] == lookup_key[31:0]);
            s1_pm[1] <= valid[1] & (key_mem[1][31:0] == lookup_key[31:0]);
            s2_vld <= s1_vld;
            s2_match[0] <= s1_pm[0] & (key_mem[0][63:32] == s1_key_hi);
            s2_match[1] <= s1_pm[1] & (key_mem[1][63:32] == s1_key_hi);
            inflight <= inflight + {63'd0, lookup} - {63'd0, s2_vld};
            armed <= armed | lookup;
        end
    end

    assign hit_vec = s2_vld ? s2_match : 2'b00;
    assign hit = |hit_vec;

    always @(*) assert (!armed || inflight <= 64'd2);
endmodule

module doomsday_cdr (
    input wire clk,
    input wire rst,
    input wire en,
    input wire rx,
    output reg finished
);
    reg [3:0]  samp;
    reg [1:0]  phase_sel;
    reg [2:0]  vote;
    reg [1:0]  os_cnt;
    reg [15:0] bit_cnt;
    reg        armed;
    reg        started;
    reg        no_slip;
    reg        prev_bit;

    initial begin
        samp = 4'b1111; phase_sel = 2'd0; vote = 3'b111; os_cnt = 2'd0;
        bit_cnt = 16'd0; armed = 1'b0; started = 1'b0; finished = 1'b0;
        no_slip = 1'b1; prev_bit = 1'b1;
    end

    wire [1:0] ph_m     = phase_sel - 2'd1;
    wire [1:0] ph_p     = phase_sel + 2'd1;
    wire [1:0] exp_edge = phase_sel + 2'd2;
    wire [1:0] dist     = os_cnt - exp_edge;
    wire edge_det  = samp[0] ^ rx;
    wire slip      = edge_det && (os_cnt != exp_edge);
    wire bit_valid = (os_cnt == 2'd3);
    wire rec_bit   = (vote[0] & vote[1]) | (vote[0] & vote[2]) | (vote[1] & vote[2]);
    wire idle_edge = (samp == 4'b1111) && !rx;

    always @(posedge clk) begin
        if (rst) begin
            samp <= 4'b1111; phase_sel <= 2'd0; vote <= 3'b111; os_cnt <= 2'd0;
            bit_cnt <= 16'd0; armed <= 1'b0; started <= 1'b0; finished <= 1'b0;
            no_slip <= 1'b1; prev_bit <= 1'b1;
        end else if (en) begin
            samp   <= {samp[2:0], rx};
            os_cnt <= os_cnt + 2'd1;
            vote   <= {samp[ph_p], samp[phase_sel], samp[ph_m]};
            if (slip) begin
                no_slip <= 1'b0;
                if (dist[1] == 1'b0) phase_sel <= phase_sel + 2'd1;
                else                 phase_sel <= phase_sel - 2'd1;
            end
            if (bit_valid) prev_bit <= rec_bit;
            if (idle_edge) armed <= 1'b1;
            if (armed && bit_valid && prev_bit && !rec_bit) started <= 1'b1;
            if (started && !finished && bit_valid && bit_cnt != 16'd383)
                bit_cnt <= bit_cnt + 16'd1;
            if (started && bit_cnt == 16'd383) finished <= 1'b1;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && no_slip)
            assert (!finished || $past(armed));
endmodule

module metro_led_scan (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        wr_en,
    input  wire [5:0]  wr_addr,
    input  wire [63:0] wr_data,
    output wire [63:0] row_drv,
    output wire [63:0] col_drv
);
    reg [63:0] frame_mem_r [0:63];
    reg [63:0] row_idx_r = 64'd0;
    reg [63:0] row_sel_r = 64'h0000_0000_0000_0001;
    reg [63:0] col_r     = 64'd0;
    reg        armed_r   = 1'b0;
    reg        pv_r      = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 64; i = i + 1)
            frame_mem_r[i] = 64'd0;
    end

    assign row_drv = row_sel_r;
    assign col_drv = col_r;

    always_ff @(posedge clk) begin
        if (wr_en)
            frame_mem_r[wr_addr] <= wr_data;
    end

    always_ff @(posedge clk) begin
        if (rst)
            row_idx_r <= 64'd0;
        else if (en)
            row_idx_r <= (row_idx_r == 64'd63) ? 64'd0 : (row_idx_r + 64'd1);
    end

    always_ff @(posedge clk) begin
        if (rst)
            row_sel_r <= 64'h0000_0000_0000_0001;
        else if (en)
            row_sel_r <= {row_sel_r[62:0], row_sel_r[63]};
    end

    always_ff @(posedge clk) begin
        if (rst)
            col_r <= 64'd0;
        else if (en)
            col_r <= frame_mem_r[row_idx_r[5:0]];
    end

    always_ff @(posedge clk) begin
        if (rst)
            armed_r <= 1'b0;
        else if (en && (row_idx_r == 64'd63))
            armed_r <= 1'b1;
    end

    always_ff @(posedge clk) begin
        pv_r <= 1'b1;
    end

    always @(posedge clk) begin
        if (pv_r && $past(armed_r))
            assert (!($past(row_sel_r[0]) && $past(row_sel_r[63])));
    end
endmodule

module isp_fb_sema (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire [31:0] req_id,
    input wire [5:0] cell_sel,
    input wire arm_req,
    input wire start_req,
    input wire fin_req,
    output wire [1:0] o_phase,
    output wire [47:0] o_locked,
    output wire [31:0] o_cur_owner
);
    reg [47:0] locked = 48'd0;
    reg [31:0] owner [0:47];
    reg [5:0] cur_cell = 6'd0;
    reg [1:0] phase = 2'd0;
    reg [31:0] arm_cnt = 32'd0;
    reg [31:0] start_cnt = 32'd0;
    reg [31:0] fin_cnt = 32'd0;
    integer i;
    initial begin
        for (i = 0; i < 48; i = i + 1) owner[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            locked <= 48'd0;
            cur_cell <= 6'd0;
            phase <= 2'd0;
            arm_cnt <= 32'd0;
            start_cnt <= 32'd0;
            fin_cnt <= 32'd0;
        end else if (en) begin
            case (phase)
                2'd0: begin
                    if (arm_req && (cell_sel < 6'd48) && !locked[cell_sel]) begin
                        locked[cell_sel] <= 1'b1;
                        owner[cell_sel] <= req_id;
                        cur_cell <= cell_sel;
                        phase <= 2'd1;
                        arm_cnt <= arm_cnt + 32'd1;
                    end
                end
                2'd1: begin
                    if (start_req) begin
                        phase <= 2'd2;
                        start_cnt <= start_cnt + 32'd1;
                    end
                end
                2'd2: begin
                    if (fin_req) begin
                        locked[cur_cell] <= 1'b0;
                        phase <= 2'd0;
                        fin_cnt <= fin_cnt + 32'd1;
                    end
                end
                default: begin
                end
            endcase
        end
    end

    assign o_phase = phase;
    assign o_locked = locked;
    assign o_cur_owner = owner[cur_cell];

    always @(*) assert (((arm_cnt - start_cnt) <= 32'd1) && ((start_cnt - fin_cnt) <= 32'd1));
endmodule

module vid_gearbox_128b130b (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         sof,
    input  wire         eof,
    input  wire         in_v,
    input  wire [127:0] in_data,
    input  wire         in_ctl,
    output reg          out_v,
    output reg  [127:0] out_word
);
    reg [255:0] gbuf     = 256'd0;
    reg [7:0]   occ      = 8'd0;
    reg [6:0]   ph       = 7'd0;
    reg         win      = 1'b0;
    reg         acc_seen = 1'b0;

    initial out_v    = 1'b0;
    initial out_word = 128'd0;

    wire [1:0]   hdr  = in_ctl ? 2'b10 : 2'b01;
    wire [255:0] ins  = {126'd0, hdr, in_data} << occ;
    wire [255:0] mix  = gbuf | ins;
    wire         stall = (ph == 7'd64);

    always @(posedge clk) begin
        if (rst) begin
            gbuf     <= 256'd0;
            occ      <= 8'd0;
            ph       <= 7'd0;
            win      <= 1'b0;
            acc_seen <= 1'b0;
            out_v    <= 1'b0;
            out_word <= 128'd0;
        end else if (en) begin
            if (sof) begin
                gbuf     <= 256'd0;
                occ      <= 8'd0;
                ph       <= 7'd0;
                win      <= 1'b1;
                acc_seen <= 1'b0;
                out_v    <= 1'b0;
            end else begin
                if (eof)
                    win <= 1'b0;
                if (stall) begin
                    out_v    <= 1'b1;
                    out_word <= gbuf[127:0];
                    gbuf     <= {128'd0, gbuf[255:128]};
                    occ      <= occ - 8'd128;
                    ph       <= 7'd0;
                end else if (in_v) begin
                    out_v    <= 1'b1;
                    out_word <= mix[127:0];
                    gbuf     <= {128'd0, mix[255:128]};
                    occ      <= occ + 8'd2;
                    ph       <= ph + 7'd1;
                    acc_seen <= 1'b1;
                end else begin
                    out_v    <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (win && !acc_seen)
            assert (occ == 8'd0);
        if (win && acc_seen && ph != 7'd0)
            assert (occ != 8'd0);
    end
endmodule

module manch_h16_rx (
    input  wire        clk,
    input  wire        en,
    input  wire        sof,
    input  wire        abort,
    input  wire        rx,
    output wire        done,
    output wire [15:0] word,
    output wire        err_o,
    output wire        mid_strobe
);
    reg [31:0] phase;
    reg        last_lvl;
    reg [31:0] shreg;
    reg [31:0] bits_left;
    reg [31:0] deadline;
    reg        busy;
    reg        err;
    reg        win;
    reg        pv;

    initial begin
        phase = 32'd0;
        last_lvl = 1'b0;
        shreg = 32'd0;
        bits_left = 32'd0;
        deadline = 32'd0;
        busy = 1'b0;
        err = 1'b0;
        win = 1'b0;
        pv = 1'b0;
    end

    assign mid_strobe = busy && (phase == 32'd8);
    assign done  = en && busy && !abort && (phase == 32'd15) && (bits_left == 32'd1);
    assign word  = shreg[15:0];
    assign err_o = err;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (en) begin
            if (abort) begin
                busy <= 1'b0;
                win  <= 1'b0;
            end else if (sof && !busy) begin
                busy      <= 1'b1;
                win       <= 1'b1;
                bits_left <= 32'd16;
                phase     <= 32'd0;
                deadline  <= 32'd256;
                err       <= 1'b0;
            end else if (busy) begin
                deadline <= (deadline != 32'd0) ? (deadline - 32'd1) : 32'd0;
                if (phase == 32'd15) begin
                    phase     <= 32'd0;
                    bits_left <= bits_left - 32'd1;
                    if (bits_left == 32'd1) begin
                        busy <= 1'b0;
                        win  <= 1'b0;
                    end
                end else begin
                    phase <= phase + 32'd1;
                end
                if (phase == 32'd4)
                    last_lvl <= rx;
                if (phase == 32'd12) begin
                    if (last_lvl != rx)
                        shreg <= {shreg[30:0], last_lvl};
                    else begin
                        shreg <= {shreg[30:0], 1'b0};
                        err   <= 1'b1;
                    end
                    last_lvl <= rx;
                end
            end
        end
    end

    always @(posedge clk)
        if (pv && win && $rose(mid_strobe))
            assert (deadline != 32'd0);
endmodule

module toast_spi_cs_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         push,
    input  wire [4:0]   push_slv,
    input  wire [127:0] push_data,
    input  wire [7:0]   cfg_setup,
    input  wire [7:0]   cfg_hold,
    input  wire [7:0]   cfg_gap,
    output wire [23:0]  cs_n,
    output wire         mosi,
    output wire         busy,
    output wire         full
);
    localparam [2:0] ST_IDLE  = 3'd0;
    localparam [2:0] ST_SETUP = 3'd1;
    localparam [2:0] ST_XFER  = 3'd2;
    localparam [2:0] ST_HOLD  = 3'd3;
    localparam [2:0] ST_GAP   = 3'd4;

    reg [2:0]   st     = ST_IDLE;
    reg [4:0]   sel    = 5'd0;
    reg [7:0]   dly    = 8'd0;
    reg [6:0]   bitcnt = 7'd0;
    reg [23:0]  cs_vec = 24'd0;
    reg [127:0] shreg  = 128'd0;

    reg [4:0]   q_slv [0:23];
    reg [127:0] q_dat [0:23];
    reg [4:0]   wptr  = 5'd0;
    reg [4:0]   rptr  = 5'd0;
    reg [4:0]   count = 5'd0;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) begin
            q_slv[i] = 5'd0;
            q_dat[i] = 128'd0;
        end
    end

    wire [4:0]   head_raw = q_slv[rptr];
    wire [4:0]   head_slv = (head_raw < 5'd24) ? head_raw : 5'd0;
    wire [127:0] head_dat = q_dat[rptr];

    wire can_pop = (count != 5'd0) &&
                   ((st == ST_IDLE) || ((st == ST_GAP) && (dly == 8'd0)));
    wire do_push = push && (count < 5'd24);

    wire [4:0] wptr_nx = (wptr == 5'd23) ? 5'd0 : wptr + 5'd1;
    wire [4:0] rptr_nx = (rptr == 5'd23) ? 5'd0 : rptr + 5'd1;

    assign cs_n = ~cs_vec;
    assign mosi = shreg[127];
    assign busy = (st != ST_IDLE);
    assign full = (count == 5'd24);

    always @(posedge clk) begin
        if (rst) begin
            st     <= ST_IDLE;
            sel    <= 5'd0;
            dly    <= 8'd0;
            bitcnt <= 7'd0;
            cs_vec <= 24'd0;
            shreg  <= 128'd0;
            wptr   <= 5'd0;
            rptr   <= 5'd0;
            count  <= 5'd0;
        end else if (en) begin
            if (do_push) begin
                q_slv[wptr] <= (push_slv < 5'd24) ? push_slv : 5'd0;
                q_dat[wptr] <= push_data;
                wptr <= wptr_nx;
            end
            if (can_pop)
                rptr <= rptr_nx;
            if (do_push && !can_pop)
                count <= count + 5'd1;
            else if (!do_push && can_pop)
                count <= count - 5'd1;

            case (st)
                ST_IDLE: begin
                    if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                    end
                end
                ST_SETUP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        bitcnt <= 7'd127;
                        st     <= ST_XFER;
                    end
                end
                ST_XFER: begin
                    shreg <= {shreg[126:0], 1'b0};
                    if (bitcnt != 7'd0)
                        bitcnt <= bitcnt - 7'd1;
                    else begin
                        dly <= cfg_hold;
                        st  <= ST_HOLD;
                    end
                end
                ST_HOLD: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        cs_vec <= cs_vec & ~(24'd1 << sel);
                        dly    <= cfg_gap;
                        st     <= ST_GAP;
                    end
                end
                ST_GAP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                    end else
                        st <= ST_IDLE;
                end
                default: st <= ST_IDLE;
            endcase
        end
    end

    // No two slave selects asserted at once while the sequencer is active
    always @(posedge clk)
        if (st != ST_IDLE)
            assert ((cs_vec & (cs_vec - 24'd1)) == 24'd0);
endmodule

module coyote_vfpga_bod (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire cmp_low,
    input wire clr,
    input wire sel_wr,
    input wire [1:0] sel_in,
    output wire slot_reset
);
    reg [15:0] deb_cnt = 16'd0;
    reg [1:0]  thr_sel = 2'd0;
    reg        bo_flag = 1'b0;
    reg [15:0] streak  = 16'd0;
    reg        pv      = 1'b0;

    reg [15:0] thr;
    always @(*) begin
        case (thr_sel)
            2'd0: thr = 16'd4;
            2'd1: thr = 16'd16;
            2'd2: thr = 16'd256;
            default: thr = 16'd4096;
        endcase
    end

    wire [16:0] deb_inc    = {1'b0, deb_cnt} + 17'd1;
    wire [15:0] streak_inc = (streak == 16'hFFFF) ? 16'hFFFF : (streak + 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            deb_cnt <= 16'd0;
            thr_sel <= 2'd0;
            bo_flag <= 1'b0;
            streak  <= 16'd0;
        end else if (en) begin
            if (!cmp_low) begin
                deb_cnt <= 16'd0;
                streak  <= 16'd0;
            end else begin
                streak <= streak_inc;
                if (!bo_flag) begin
                    deb_cnt <= deb_inc[15:0];
                    if (deb_inc >= {1'b0, thr})
                        bo_flag <= 1'b1;
                end
            end
            if (clr) begin
                bo_flag <= 1'b0;
                deb_cnt <= 16'd0;
            end
            if (sel_wr && (deb_cnt == 16'd0))
                thr_sel <= sel_in;
        end
    end

    assign slot_reset = bo_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(bo_flag))
            assert (streak >= thr);
endmodule

module wl_decim48 (
    input wire clk,
    input wire rst,
    input wire en,
    input wire flush,
    input wire [63:0] din,
    output wire [63:0] o_dout,
    output wire o_tick
);
    localparam [5:0]  LAST = 6'd47;
    localparam [63:0] WIN  = 64'd48;

    reg [5:0]  phase;
    reg [63:0] acc;
    reg [63:0] dout;
    reg [63:0] in_cnt;
    reg [63:0] out_cnt;
    reg        tick;
    reg        pre_flush;
    reg        pv;

    initial begin
        phase = 6'd0;
        acc = 64'd0;
        dout = 64'd0;
        in_cnt = 64'd0;
        out_cnt = 64'd0;
        tick = 1'b0;
        pre_flush = 1'b1;
        pv = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            phase <= 6'd0;
            acc <= 64'd0;
            dout <= 64'd0;
            in_cnt <= 64'd0;
            out_cnt <= 64'd0;
            tick <= 1'b0;
            pre_flush <= 1'b1;
        end else if (en) begin
            if (flush) begin
                phase <= 6'd0;
                acc <= 64'd0;
                tick <= 1'b0;
                pre_flush <= 1'b0;
            end else begin
                in_cnt <= in_cnt + 64'd1;
                if (phase == LAST) begin
                    phase <= 6'd0;
                    dout <= acc + din;
                    acc <= 64'd0;
                    out_cnt <= out_cnt + 64'd1;
                    tick <= 1'b1;
                end else begin
                    phase <= phase + 6'd1;
                    acc <= acc + din;
                    tick <= 1'b0;
                end
            end
        end
    end

    assign o_dout = dout;
    assign o_tick = tick;

    always @(posedge clk)
        if (pv && !rst && pre_flush && $rose(tick))
            assert (in_cnt == WIN * out_cnt);
endmodule

module SsiFir8 (
    input  wire        clk,
    input  wire        en,
    input  wire        load_req,
    input  wire [31:0] coef_in,
    input  wire        s_valid,
    input  wire [31:0] s_data,
    input  wire        frame_end,
    output wire [31:0] y,
    output wire        y_valid
);
    reg [31:0] tap  [0:7];
    reg [31:0] coef [0:7];
    reg [31:0] fill_cnt = 32'd0;
    reg        primed   = 1'b0;
    reg        loading  = 1'b0;
    reg [31:0] load_ptr = 32'd0;
    reg        win      = 1'b0;
    reg        pv       = 1'b0;
    integer i;

    initial begin
        for (i = 0; i < 8; i = i + 1) begin
            tap[i]  = 32'd0;
            coef[i] = 32'd0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (en) begin
            if (load_req) begin
                loading  <= 1'b1;
                load_ptr <= 32'd0;
                fill_cnt <= 32'd0;
                primed   <= 1'b0;
            end else begin
                primed <= (fill_cnt >= 32'd8);
                if (loading) begin
                    coef[load_ptr[2:0]] <= coef_in;
                    if (load_ptr == 32'd7) begin
                        loading  <= 1'b0;
                        load_ptr <= 32'd0;
                    end else begin
                        load_ptr <= load_ptr + 32'd1;
                    end
                end else if (s_valid) begin
                    for (i = 7; i > 0; i = i - 1)
                        tap[i] <= tap[i-1];
                    tap[0]   <= s_data;
                    fill_cnt <= (fill_cnt < 32'd8) ? (fill_cnt + 32'd1) : 32'd8;
                end
            end
            if (load_req)
                win <= 1'b1;
            else if (frame_end)
                win <= 1'b0;
        end
    end

    assign y = tap[0]*coef[0] + tap[1]*coef[1] + tap[2]*coef[2] + tap[3]*coef[3]
             + tap[4]*coef[4] + tap[5]*coef[5] + tap[6]*coef[6] + tap[7]*coef[7];
    assign y_valid = primed;

    always @(posedge clk)
        if (pv && $past(win))
            assert (!($past(primed) && $past(loading)));
endmodule

module ecc_err_logger (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire sw_arm,
    input wire err_valid,
    input wire err_ue,
    input wire [31:0] err_syn,
    input wire [31:0] err_addr,
    input wire sw_ack
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, CAPT = 2'd2, DONE = 2'd3;

    reg [1:0]  phase;
    reg [31:0] syn_q, addr_q;
    reg        type_q;
    reg [31:0] ce_cnt, ue_cnt;
    reg [31:0] log_mem [0:127];
    reg [6:0]  wp;
    reg        arm_seen, start_seen, fin_seen;

    integer i;
    initial begin
        phase = IDLE;
        syn_q = 32'd0;
        addr_q = 32'd0;
        type_q = 1'b0;
        ce_cnt = 32'd0;
        ue_cnt = 32'd0;
        wp = 7'd0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        fin_seen = 1'b0;
        for (i = 0; i < 128; i = i + 1) log_mem[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            phase <= IDLE;
            syn_q <= 32'd0;
            addr_q <= 32'd0;
            type_q <= 1'b0;
            ce_cnt <= 32'd0;
            ue_cnt <= 32'd0;
            wp <= 7'd0;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            fin_seen <= 1'b0;
        end else if (en) begin
            case (phase)
                IDLE, DONE: begin
                    if (sw_arm) begin
                        phase <= ARMED;
                        arm_seen <= 1'b1;
                    end
                end
                ARMED: begin
                    if (err_valid) begin
                        phase <= CAPT;
                        start_seen <= 1'b1;
                        syn_q <= err_syn;
                        addr_q <= err_addr;
                        type_q <= err_ue;
                        if (err_ue) begin
                            if (ue_cnt != 32'hFFFFFFFF) ue_cnt <= ue_cnt + 32'd1;
                        end else begin
                            if (ce_cnt != 32'hFFFFFFFF) ce_cnt <= ce_cnt + 32'd1;
                        end
                        log_mem[wp] <= err_addr;
                        wp <= wp + 7'd1;
                    end
                end
                CAPT: begin
                    if (sw_ack) begin
                        phase <= DONE;
                        fin_seen <= 1'b1;
                    end
                end
                default: phase <= phase;
            endcase
        end
    end

    assert property (!fin_seen || (start_seen && arm_seen));
endmodule

module norm32 (
    input wire clk,
    input wire en,
    input wire arm,
    input wire load,
    input wire start,
    input wire ack,
    input wire [31:0] din,
    input wire [31:0] ein,
    output wire done,
    output wire [31:0] mant_o,
    output wire [31:0] exp_o
);
    reg [1:0] phase = 2'd0;
    reg [31:0] mant = 32'd0;
    reg [31:0] exp_r = 32'd0;
    reg [5:0] shamt = 6'd0;
    reg armed_f = 1'b0;
    reg started_f = 1'b0;
    reg q_seen = 1'b0;
    reg pv = 1'b0;

    assign done = (phase == 2'd3);
    assign mant_o = mant;
    assign exp_o = exp_r;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (en) begin
            q_seen <= q_seen | load;
            case (phase)
                2'd0: begin
                    if (arm) begin
                        mant <= din;
                        exp_r <= ein;
                        shamt <= 6'd0;
                        armed_f <= 1'b1;
                        phase <= 2'd1;
                    end
                end
                2'd1: begin
                    if (start) begin
                        started_f <= 1'b1;
                        phase <= 2'd2;
                    end
                end
                2'd2: begin
                    if (mant[31] || (mant == 32'd0) || (shamt >= 6'd32)) begin
                        exp_r <= exp_r - {26'd0, shamt};
                        phase <= 2'd3;
                    end else begin
                        mant <= {mant[30:0], 1'b0};
                        shamt <= shamt + 6'd1;
                    end
                end
                2'd3: begin
                    if (ack) begin
                        armed_f <= 1'b0;
                        started_f <= 1'b0;
                        phase <= 2'd0;
                    end
                end
            endcase
        end
    end

    always @(posedge clk)
        if (pv && q_seen && $past(q_seen) && $past(phase) == 2'd3)
            assert ($past(armed_f) && $past(started_f));
endmodule

module dfx_quiesce (
    input wire clk,
    input wire rst,
    input wire en,
    input wire issue,
    input wire ret,
    output wire bus_quiet
);
    reg [15:0] out_cnt;
    reg [15:0] iss_cnt;
    reg [15:0] ret_cnt;
    reg        armed;
    initial out_cnt = 16'd0;
    initial iss_cnt = 16'd0;
    initial ret_cnt = 16'd0;
    initial armed   = 1'b0;

    wire iss_ok = issue && (out_cnt != 16'hFFFF);
    wire ret_ok = ret && (out_cnt != 16'd0);

    always @(posedge clk) begin
        if (rst) begin
            out_cnt <= 16'd0;
            iss_cnt <= 16'd0;
            ret_cnt <= 16'd0;
            armed   <= 1'b0;
        end else if (en) begin
            out_cnt <= out_cnt + {15'd0, iss_ok} - {15'd0, ret_ok};
            iss_cnt <= iss_cnt + {15'd0, iss_ok};
            ret_cnt <= ret_cnt + {15'd0, ret_ok};
            armed   <= armed | iss_ok;
        end
    end

    assign bus_quiet = ~(out_cnt[0] | out_cnt[1] | out_cnt[2] | out_cnt[3] |
                         out_cnt[4] | out_cnt[5] | out_cnt[6] | out_cnt[7] |
                         out_cnt[8] | out_cnt[9] | out_cnt[10] | out_cnt[11] |
                         out_cnt[12] | out_cnt[13] | out_cnt[14] | out_cnt[15]);

    always @(posedge clk)
        if (armed && bus_quiet)
            assert (ret_cnt == iss_cnt);
endmodule

module ppu_clkfail_ctl (
    input  wire clk,
    input  wire rst_n,
    input  wire en,
    input  wire prim_fail,
    output wire use_backup,
    output wire busy,
    output wire fail_flag
);
    localparam [7:0] SETTLE = 8'd200;

    reg       sel_src     = 1'b0;
    reg       switching   = 1'b0;
    reg [7:0] settle_cnt  = 8'd0;
    reg       sticky_fail = 1'b0;
    reg [7:0] fail_cnt    = 8'd0;
    reg       fail_seen   = 1'b0;

    always @(posedge clk) begin
        if (!rst_n) begin
            sel_src     <= 1'b0;
            switching   <= 1'b0;
            settle_cnt  <= 8'd0;
            sticky_fail <= 1'b0;
            fail_cnt    <= 8'd0;
            fail_seen   <= 1'b0;
        end else if (en) begin
            if (prim_fail) begin
                fail_seen   <= 1'b1;
                sticky_fail <= 1'b1;
                if (fail_cnt != 8'd255)
                    fail_cnt <= fail_cnt + 8'd1;
            end
            if (prim_fail && !sel_src && !switching) begin
                switching  <= 1'b1;
                settle_cnt <= SETTLE;
            end else if (switching) begin
                settle_cnt <= settle_cnt - 8'd1;
                if (settle_cnt == 8'd1) begin
                    sel_src   <= 1'b1;
                    switching <= 1'b0;
                end
            end
        end
    end

    assign use_backup = sel_src;
    assign busy       = switching;
    assign fail_flag  = sticky_fail;

    always @(posedge clk)
        if (sel_src)
            assert (fail_seen);
endmodule

module caribou_cuckoo_barrett (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        req,
    input  wire [31:0] a,
    input  wire [31:0] b,
    input  wire        rehash,
    input  wire [31:0] new_mod,
    output reg  [32:0] res_r,
    output reg         done,
    output reg         busy,
    output reg         expired
);
    reg [31:0] mod_r;
    reg [32:0] mu_r;
    reg [63:0] prod_r;
    reg [31:0] q_r;
    reg [2:0]  stage;
    reg [31:0] cnt;
    reg        pre_rehash;

    initial begin
        mod_r      = 32'hFFFF_FFFF;
        mu_r       = 33'h1_0000_0001;
        prod_r     = 64'd0;
        q_r        = 32'd0;
        res_r      = 33'd0;
        stage      = 3'd0;
        cnt        = 32'd0;
        busy       = 1'b0;
        done       = 1'b0;
        expired    = 1'b0;
        pre_rehash = 1'b1;
    end

    wire [64:0] two64   = {1'b1, 64'd0};
    wire [64:0] mu_full = (new_mod == 32'd0) ? 65'd0 : (two64 / {33'd0, new_mod});
    wire [96:0] pm      = prod_r * mu_r;
    wire [63:0] qm      = q_r * mod_r;
    wire [63:0] diff    = prod_r - qm;
    wire [32:0] mod_ext = {1'b0, mod_r};

    always @(posedge clk) begin
        if (rst) begin
            mod_r      <= 32'hFFFF_FFFF;
            mu_r       <= 33'h1_0000_0001;
            prod_r     <= 64'd0;
            q_r        <= 32'd0;
            res_r      <= 33'd0;
            stage      <= 3'd0;
            cnt        <= 32'd0;
            busy       <= 1'b0;
            done       <= 1'b0;
            expired    <= 1'b0;
            pre_rehash <= 1'b1;
        end else if (en) begin
            if (rehash) pre_rehash <= 1'b0;
            if (!busy) begin
                if (req) begin
                    prod_r <= a * b;
                    busy   <= 1'b1;
                    stage  <= 3'd0;
                    cnt    <= 32'd5;
                    done   <= 1'b0;
                end else if (rehash) begin
                    mod_r <= new_mod;
                    mu_r  <= mu_full[32:0];
                    done  <= 1'b0;
                end
            end else begin
                cnt     <= cnt - 32'd1;
                expired <= expired | ((cnt == 32'd1) && (stage != 3'd4));
                case (stage)
                    3'd0: begin
                        q_r   <= pm[95:64];
                        stage <= 3'd1;
                    end
                    3'd1: begin
                        res_r <= diff[32:0];
                        stage <= 3'd2;
                    end
                    3'd2: begin
                        if (res_r >= mod_ext) res_r <= res_r - mod_ext;
                        stage <= 3'd3;
                    end
                    3'd3: begin
                        if (res_r >= mod_ext) res_r <= res_r - mod_ext;
                        stage <= 3'd4;
                    end
                    3'd4: begin
                        done <= 1'b1;
                        busy <= 1'b0;
                    end
                    default: begin
                        stage <= stage;
                    end
                endcase
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) begin
        pv <= 1'b1;
        if (pv && pre_rehash && en && $stable(done))
            assert ($stable(expired));
    end
endmodule

module gardner_ted_lxp (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [7:0] sample_in,
    output wire [15:0] o_err,
    output wire o_strobe
);
    reg phase;
    reg [7:0] prev_sym, mid, cur_sym;
    reg [7:0] sym_cnt;
    reg [7:0] half_cnt;
    reg [15:0] err_out;
    reg [15:0] err_mem [0:31];
    integer i;

    initial begin
        phase = 1'b0;
        prev_sym = 8'd0;
        mid = 8'd0;
        cur_sym = 8'd0;
        sym_cnt = 8'd0;
        half_cnt = 8'd0;
        err_out = 16'd0;
        for (i = 0; i < 32; i = i + 1) err_mem[i] = 16'd0;
    end

    wire signed [8:0] diff = $signed({sample_in[7], sample_in}) - $signed({cur_sym[7], cur_sym});
    wire signed [16:0] prod = diff * $signed({mid[7], mid});
    wire [15:0] err = prod[15:0];

    always @(posedge clk) begin
        if (rst) begin
            phase <= 1'b0;
            prev_sym <= 8'd0;
            mid <= 8'd0;
            cur_sym <= 8'd0;
            sym_cnt <= 8'd0;
            half_cnt <= 8'd0;
            err_out <= 16'd0;
            for (i = 0; i < 32; i = i + 1) err_mem[i] <= 16'd0;
        end else if (en) begin
            phase <= ~phase;
            if (!phase) begin
                mid <= sample_in;
            end else begin
                prev_sym <= cur_sym;
                cur_sym <= sample_in;
                err_out <= err;
                err_mem[sym_cnt[4:0]] <= err;
            end
            if (half_cnt == 8'd63) begin
                half_cnt <= 8'd0;
                sym_cnt <= 8'd0;
            end else begin
                half_cnt <= half_cnt + 8'd1;
                if (phase)
                    sym_cnt <= sym_cnt + 8'd1;
            end
        end
    end

    assign o_err = err_out;
    assign o_strobe = phase;

    always @(*) assert (sym_cnt <= 8'd31);
endmodule

module ft60x_axi_default_slave (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       en,
    input  wire       arvalid,
    input  wire [7:0] arid,
    input  wire [7:0] arlen,
    input  wire       rready,
    input  wire       awvalid,
    input  wire [7:0] awid,
    input  wire       wvalid,
    input  wire       wlast,
    input  wire       bready,
    output wire       arready,
    output wire       rvalid,
    output wire [1:0] rresp,
    output wire       rlast,
    output wire [7:0] rid,
    output wire       awready,
    output wire       wready,
    output wire       bvalid,
    output wire [1:0] bresp,
    output wire [7:0] bid
);
    reg [7:0] rid_q   = 8'd0;
    reg [7:0] len_q   = 8'd0;
    reg [7:0] sent_q  = 8'd0;
    reg       busy    = 1'b0;
    reg       rbeat_q = 1'b0;
    reg       win     = 1'b0;
    reg [7:0] bid_q   = 8'd0;
    reg       wact    = 1'b0;
    reg       bpend   = 1'b0;

    assign arready = en & ~busy;
    assign rvalid  = en & busy;
    assign rresp   = 2'b11;
    assign rlast   = ((sent_q + 8'd1) == len_q);
    assign rid     = rid_q;
    assign awready = en & ~bpend & ~wact;
    assign wready  = en & wact;
    assign bvalid  = en & bpend;
    assign bresp   = 2'b11;
    assign bid     = bid_q;

    wire ar_hs = arvalid & arready;
    wire r_hs  = rvalid & rready;
    wire aw_hs = awvalid & awready;
    wire w_hs  = wvalid & wready;
    wire b_hs  = bvalid & bready;

    always @(posedge clk) begin
        if (!rst_n) begin
            rid_q   <= 8'd0;
            len_q   <= 8'd0;
            sent_q  <= 8'd0;
            busy    <= 1'b0;
            rbeat_q <= 1'b0;
            win     <= 1'b0;
            bid_q   <= 8'd0;
            wact    <= 1'b0;
            bpend   <= 1'b0;
        end else if (en) begin
            rbeat_q <= r_hs;
            if (ar_hs) begin
                rid_q  <= arid;
                len_q  <= ((arlen > 8'd15) ? 8'd15 : arlen) + 8'd1;
                sent_q <= 8'd0;
                busy   <= 1'b1;
                win    <= 1'b1;
            end else if (r_hs) begin
                if (rlast) begin
                    busy   <= 1'b0;
                    sent_q <= 8'd0;
                    win    <= 1'b0;
                end else begin
                    sent_q <= sent_q + 8'd1;
                end
            end
            if (aw_hs) begin
                bid_q <= awid;
                wact  <= 1'b1;
            end
            if (w_hs && wlast) begin
                wact  <= 1'b0;
                bpend <= 1'b1;
            end
            if (b_hs)
                bpend <= 1'b0;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && rst_n && win && $rose(rbeat_q))
            assert (sent_q <= 8'd16);
endmodule

module nyuzi_scan_demux (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         ir_load,
    input  wire [7:0]   ir_data,
    input  wire         shift,
    input  wire         scan_in,
    output wire [255:0] chain_si,
    output reg          frame_done
);
    reg [7:0]  chain_sel;
    reg [15:0] shift_cnt;
    reg [15:0] remaining;
    reg        armed;

    initial chain_sel  = 8'd0;
    initial shift_cnt  = 16'd0;
    initial remaining  = 16'd999;
    initial armed      = 1'b0;
    initial frame_done = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            chain_sel  <= 8'd0;
            shift_cnt  <= 16'd0;
            remaining  <= 16'd999;
            armed      <= 1'b0;
            frame_done <= 1'b0;
        end else if (en) begin
            frame_done <= 1'b0;
            if (ir_load) begin
                chain_sel <= ir_data;
                shift_cnt <= 16'd0;
                remaining <= 16'd999;
                armed     <= 1'b1;
            end else if (shift) begin
                if (remaining == 16'd0) begin
                    shift_cnt  <= 16'd0;
                    remaining  <= 16'd999;
                    frame_done <= 1'b1;
                end else begin
                    shift_cnt <= shift_cnt + 16'd1;
                    remaining <= remaining - 16'd1;
                end
            end
        end
    end

    wire si_bit = scan_in & shift & en;
    assign chain_si = {255'd0, si_bit} << chain_sel;

    always @(posedge clk)
        if (armed) assert (shift_cnt <= 16'd999);
endmodule

module sv2v_hdr_parser (
    input wire clk,
    input wire rst,
    input wire en,
    input wire sop,
    input wire eop,
    input wire [15:0] din,
    output reg [15:0] kind,
    output reg [15:0] len,
    output reg [15:0] csum
);
    reg [15:0] off;
    reg [15:0] hdr_mem [0:31];
    reg hdr_done;
    reg win;
    integer i;

    initial begin
        off = 16'd0;
        kind = 16'd0;
        len = 16'd0;
        csum = 16'd0;
        hdr_done = 1'b0;
        win = 1'b0;
        for (i = 0; i < 32; i = i + 1) hdr_mem[i] = 16'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            off <= 16'd0;
            kind <= 16'd0;
            len <= 16'd0;
            csum <= 16'd0;
            hdr_done <= 1'b0;
            win <= 1'b0;
            for (i = 0; i < 32; i = i + 1) hdr_mem[i] <= 16'd0;
        end else if (en) begin
            if (sop) begin
                off <= 16'd1;
                kind <= din;
                hdr_mem[0] <= din;
                hdr_done <= 1'b0;
                win <= 1'b1;
            end else if (win) begin
                if (off < 16'd32) hdr_mem[off[4:0]] <= din;
                if (off == 16'd1) len <= din;
                if (off == 16'd2) begin
                    csum <= din;
                    hdr_done <= 1'b1;
                end
                if (off != 16'hFFFF) off <= off + 16'd1;
                if (eop) win <= 1'b0;
            end
        end
    end

    assert property (!(win && (off > 16'd3)) || hdr_done);
endmodule

module fp8_reduce_minmax (
    input wire clk,
    input wire rst,
    input wire en,
    input wire valid,
    input wire op,
    input wire [7:0] x,
    output reg [7:0] mx,
    output reg [7:0] mn,
    output reg [7:0] res,
    output reg inv,
    output reg armed
);
    initial mx = 8'hFC;
    initial mn = 8'h7C;
    initial res = 8'h00;
    initial inv = 1'b0;
    initial armed = 1'b0;

    function isnan;
        input [7:0] a;
        isnan = (a[6:2] == 5'h1F) && (a[1:0] != 2'b00);
    endfunction

    function [7:0] key;
        input [7:0] a;
        key = a[7] ? ~a : (a | 8'h80);
    endfunction

    function [7:0] fmax;
        input [7:0] a;
        input [7:0] b;
        begin
            if (isnan(a) && isnan(b)) fmax = 8'h7E;
            else if (isnan(a)) fmax = b;
            else if (isnan(b)) fmax = a;
            else if (key(a) >= key(b)) fmax = a;
            else fmax = b;
        end
    endfunction

    function [7:0] fmin;
        input [7:0] a;
        input [7:0] b;
        begin
            if (isnan(a) && isnan(b)) fmin = 8'h7E;
            else if (isnan(a)) fmin = b;
            else if (isnan(b)) fmin = a;
            else if (key(a) <= key(b)) fmin = a;
            else fmin = b;
        end
    endfunction

    function fle;
        input [7:0] a;
        input [7:0] b;
        fle = !isnan(a) && !isnan(b) && (key(a) <= key(b));
    endfunction

    wire [7:0] nmax = fmax(mx, x);
    wire [7:0] nmin = fmin(mn, x);

    always @(posedge clk) begin
        if (rst) begin
            mx <= 8'hFC;
            mn <= 8'h7C;
            res <= 8'h00;
            inv <= 1'b0;
            armed <= 1'b0;
        end else if (en && valid) begin
            mx <= nmax;
            mn <= nmin;
            res <= op ? nmin : nmax;
            inv <= isnan(x) && !x[1];
            armed <= 1'b1;
        end
    end

    always @(posedge clk)
        if (armed)
            assert (!isnan(mx) && !isnan(mn) && (fle(mn, mx) || (mx == 8'hFC && mn == 8'h7C)));
endmodule

module tbdr_tile_dir (
    input  wire         clk,
    input  wire         en,
    input  wire         rd_req,
    input  wire         wr_req,
    input  wire [3:0]   req_line,
    input  wire [2:0]   req_id,
    input  wire [127:0] wdata,
    input  wire         inv_ack,
    input  wire         tile_begin,
    input  wire         tile_end,
    output reg          gnt_s,
    output reg          gnt_x,
    output reg          win,
    output reg          busy,
    output reg  [3:0]   ack_cnt
);
    reg [31:0]   st_f;
    reg [127:0]  shr_f;
    reg [47:0]   own_f;
    reg [2047:0] data_f;
    reg [3:0]    tline;
    reg [2:0]    treq;
    reg [127:0]  tdata;

    initial begin
        st_f    = 32'd0;
        shr_f   = 128'd0;
        own_f   = 48'd0;
        data_f  = 2048'd0;
        tline   = 4'd0;
        treq    = 3'd0;
        tdata   = 128'd0;
        busy    = 1'b0;
        ack_cnt = 4'd0;
        gnt_s   = 1'b0;
        gnt_x   = 1'b0;
        win     = 1'b0;
    end

    wire [7:0] shr_cur  = shr_f[req_line*8 +: 8];
    wire [7:0] id_mask  = 8'd1 << req_id;
    wire [7:0] others   = shr_cur & ~id_mask;
    wire [3:0] pop      = {3'd0, others[0]} + {3'd0, others[1]} + {3'd0, others[2]} + {3'd0, others[3]}
                        + {3'd0, others[4]} + {3'd0, others[5]} + {3'd0, others[6]} + {3'd0, others[7]};
    wire       no_other = (others == 8'd0);
    wire       wr_go    = wr_req && !busy;
    wire       rd_go    = rd_req && !wr_req && !busy;
    wire       ack_go   = inv_ack && (ack_cnt != 4'd0);
    wire       ack_last = ack_go && (ack_cnt == 4'd1);

    always @(posedge clk) begin
        if (en) begin
            gnt_s <= rd_go;
            gnt_x <= (wr_go && no_other) || ack_last;
            win   <= tile_begin ? 1'b1 : (tile_end ? 1'b0 : win);

            if (wr_go) begin
                if (!no_other) begin
                    busy    <= 1'b1;
                    ack_cnt <= pop;
                    tline   <= req_line;
                    treq    <= req_id;
                    tdata   <= wdata;
                    st_f[req_line*2 +: 2] <= 2'd3;
                end else begin
                    data_f[req_line*128 +: 128] <= wdata;
                    st_f[req_line*2 +: 2]       <= 2'd2;
                    own_f[req_line*3 +: 3]      <= req_id;
                    shr_f[req_line*8 +: 8]      <= 8'd0;
                end
            end else if (rd_go) begin
                shr_f[req_line*8 + req_id] <= 1'b1;
                st_f[req_line*2 +: 2]      <= 2'd1;
            end

            if (ack_go) begin
                ack_cnt <= ack_cnt - 4'd1;
                if (ack_cnt == 4'd1) begin
                    busy <= 1'b0;
                    st_f[tline*2 +: 2]       <= 2'd2;
                    own_f[tline*3 +: 3]      <= treq;
                    shr_f[tline*8 +: 8]      <= 8'd0;
                    data_f[tline*128 +: 128] <= tdata;
                end
            end
        end
    end

    always @(*) if (win) assert (!(gnt_s && gnt_x));
endmodule

module chacha_qr_lockstep (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire load,
    input wire [3:0] ld_idx,
    input wire [31:0] ld_word,
    input wire start,
    input wire abort,
    output wire o_mismatch,
    output wire [31:0] o_word0,
    output wire [31:0] o_rnd
);
    // 16 x 32-bit state words, flattened: word i at bits [i*32 +: 32]
    reg [511:0] st_a;
    reg [511:0] st_b;
    reg [31:0]  rnd;
    reg         win;

    initial begin
        st_a = 512'd0;
        st_b = 512'd0;
        rnd  = 32'd0;
        win  = 1'b0;
    end

    function [511:0] qr_step;
        input [511:0] s;
        input [2:0] sel;
        reg [3:0] ia, ib, ic, id;
        reg [31:0] a, b, c, d;
        reg [511:0] r;
        begin
            case (sel)
                3'd0: begin ia = 4'd0; ib = 4'd4; ic = 4'd8;  id = 4'd12; end
                3'd1: begin ia = 4'd1; ib = 4'd5; ic = 4'd9;  id = 4'd13; end
                3'd2: begin ia = 4'd2; ib = 4'd6; ic = 4'd10; id = 4'd14; end
                3'd3: begin ia = 4'd3; ib = 4'd7; ic = 4'd11; id = 4'd15; end
                3'd4: begin ia = 4'd0; ib = 4'd5; ic = 4'd10; id = 4'd15; end
                3'd5: begin ia = 4'd1; ib = 4'd6; ic = 4'd11; id = 4'd12; end
                3'd6: begin ia = 4'd2; ib = 4'd7; ic = 4'd8;  id = 4'd13; end
                default: begin ia = 4'd3; ib = 4'd4; ic = 4'd9; id = 4'd14; end
            endcase
            a = s[{ia, 5'b0} +: 32];
            b = s[{ib, 5'b0} +: 32];
            c = s[{ic, 5'b0} +: 32];
            d = s[{id, 5'b0} +: 32];
            a = a + b; d = d ^ a; d = {d[15:0], d[31:16]};
            c = c + d; b = b ^ c; b = {b[19:0], b[31:20]};
            a = a + b; d = d ^ a; d = {d[23:0], d[31:24]};
            c = c + d; b = b ^ c; b = {b[24:0], b[31:25]};
            r = s;
            r[{ia, 5'b0} +: 32] = a;
            r[{ib, 5'b0} +: 32] = b;
            r[{ic, 5'b0} +: 32] = c;
            r[{id, 5'b0} +: 32] = d;
            qr_step = r;
        end
    endfunction

    wire [511:0] nxt_a = qr_step(st_a, rnd[2:0]);
    wire [511:0] nxt_b = qr_step(st_b, rnd[2:0]);

    always @(posedge clk) begin
        if (!rst_n) begin
            st_a <= 512'd0;
            st_b <= 512'd0;
            rnd  <= 32'd0;
            win  <= 1'b0;
        end else if (en) begin
            if (load) begin
                st_a[{ld_idx, 5'b0} +: 32] <= ld_word;
                st_b[{ld_idx, 5'b0} +: 32] <= ld_word;
                rnd <= 32'd0;
            end else begin
                st_a <= nxt_a;
                st_b <= nxt_b;
                rnd  <= rnd + 32'd1;
            end
            if (abort)
                win <= 1'b0;
            else if (start)
                win <= 1'b1;
        end
    end

    assign o_mismatch = (st_a != st_b);
    assign o_word0    = st_a[31:0];
    assign o_rnd      = rnd;

    always @(*) assert (!win || (st_a[31:0] == st_b[31:0]));
endmodule

module lego_slot_alloc (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire alloc_req,
    input wire free_req,
    input wire [0:0] free_idx,
    input wire sess_open,
    input wire sess_close,
    output wire full,
    output wire empty,
    output wire grant_valid,
    output wire [0:0] grant_idx
);
    reg [1:0] bitmap;
    reg [15:0] used_cnt;
    reg [15:0] free_cnt;
    reg win;
    initial begin
        bitmap = 2'b00;
        used_cnt = 16'd0;
        free_cnt = 16'd2;
        win = 1'b0;
    end

    assign grant_valid = alloc_req && (bitmap != 2'b11);
    assign grant_idx = bitmap[0] ? 1'b1 : 1'b0;
    wire do_free = !grant_valid && free_req && bitmap[free_idx];

    always @(posedge clk) begin
        if (!rst_n) begin
            bitmap <= 2'b00;
            used_cnt <= 16'd0;
            free_cnt <= 16'd2;
            win <= 1'b0;
        end else if (en) begin
            if (grant_valid) begin
                bitmap[grant_idx] <= 1'b1;
                used_cnt <= used_cnt + 16'd1;
                free_cnt <= free_cnt - 16'd1;
            end else if (do_free) begin
                bitmap[free_idx] <= 1'b0;
                used_cnt <= used_cnt - 16'd1;
                free_cnt <= free_cnt + 16'd1;
            end
            win <= sess_open ? 1'b1 : (sess_close ? 1'b0 : win);
        end
    end

    assign full = (free_cnt == 16'd0);
    assign empty = (used_cnt == 16'd0);

    always @(*) if (win) assert (!(free_cnt == 16'd0 && used_cnt == 16'd0));
endmodule

module tile_polarity_lock (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         retrain,
    input  wire [127:0] rx_data,
    output wire [127:0] data_out,
    output reg          locked
);
    localparam [7:0] TS     = 8'hBC;
    localparam [7:0] TS_INV = 8'h43;

    reg [15:0] inv_flag;
    reg [15:0] det_mask;
    reg [4:0]  det_cnt;
    reg        pre_rt;
    reg        pv;

    initial inv_flag = 16'd0;
    initial det_mask = 16'd0;
    initial det_cnt  = 5'd0;
    initial locked   = 1'b0;
    initial pre_rt   = 1'b1;
    initial pv       = 1'b0;

    reg [15:0] new_mask;
    reg [15:0] nxt_inv;
    reg [4:0]  new_cnt;
    integer i;

    always @(*) begin
        new_mask = 16'd0;
        nxt_inv  = inv_flag;
        new_cnt  = 5'd0;
        for (i = 0; i < 16; i = i + 1) begin
            if (!det_mask[i]) begin
                if (rx_data[8*i +: 8] == TS) begin
                    new_mask[i] = 1'b1;
                    nxt_inv[i]  = 1'b0;
                end else if (rx_data[8*i +: 8] == TS_INV) begin
                    new_mask[i] = 1'b1;
                    nxt_inv[i]  = 1'b1;
                end
            end
            new_cnt = new_cnt + {4'd0, new_mask[i]};
        end
    end

    wire [4:0] sum_cnt = det_cnt + new_cnt;

    genvar g;
    generate
        for (g = 0; g < 16; g = g + 1) begin : g_lane
            assign data_out[8*g +: 8] = rx_data[8*g +: 8] ^ {8{inv_flag[g]}};
        end
    endgenerate

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            inv_flag <= 16'd0;
            det_mask <= 16'd0;
            det_cnt  <= 5'd0;
            locked   <= 1'b0;
            pre_rt   <= 1'b1;
        end else if (en) begin
            if (retrain) begin
                inv_flag <= 16'd0;
                det_mask <= 16'd0;
                det_cnt  <= 5'd0;
                locked   <= 1'b0;
                pre_rt   <= 1'b0;
            end else begin
                inv_flag <= nxt_inv;
                det_mask <= det_mask | new_mask;
                det_cnt  <= sum_cnt;
                locked   <= locked | (sum_cnt == 5'd16);
            end
        end
    end

    always @(posedge clk)
        if (pv && !rst && pre_rt && $rose(locked))
            assert (&det_mask);
endmodule

module uart_nco (
    input wire i_clk,
    input wire i_rst,
    input wire i_en,
    input wire [7:0] i_fword,
    input wire i_start,
    input wire i_stop,
    output wire [7:0] o_sin,
    output wire [7:0] o_ticks,
    output wire o_win
);
    localparam [63:0] SIN_TAB = {8'd37, 8'd1, 8'd37, 8'd128, 8'd218, 8'd255, 8'd218, 8'd128};

    reg [7:0] phase = 8'd0;
    reg [7:0] tick_cnt = 8'd0;
    reg [2:0] last_idx = 3'd0;
    reg [7:0] sin_q = 8'd128;
    reg       win = 1'b0;

    wire [8:0] sum = {1'b0, phase} + {1'b0, i_fword};
    wire [7:0] nphase = sum[7:0];
    wire       carry = sum[8];
    wire [2:0] nidx = nphase[7:5];
    wire [5:0] nbase = {nidx, 3'b000};
    wire [7:0] n_sin = SIN_TAB[nbase +: 8];
    wire [5:0] lbase = {last_idx, 3'b000};
    wire [7:0] sin_of_last = SIN_TAB[lbase +: 8];

    always @(posedge i_clk) begin
        if (i_rst) begin
            phase <= 8'd0;
            tick_cnt <= 8'd0;
            last_idx <= 3'd0;
            sin_q <= 8'd128;
            win <= 1'b0;
        end else if (i_en) begin
            phase <= nphase;
            if (carry)
                tick_cnt <= tick_cnt + 8'd1;
            last_idx <= nidx;
            sin_q <= n_sin;
            if (i_start)
                win <= 1'b1;
            else if (i_stop)
                win <= 1'b0;
        end
    end

    assign o_sin = sin_q;
    assign o_ticks = tick_cnt;
    assign o_win = win;

    reg pv = 1'b0;
    always @(posedge i_clk) pv <= 1'b1;

    always @(posedge i_clk)
        if (pv && !$past(i_rst) && win && $stable(phase))
            assert ($stable(sin_q));
endmodule

module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
    output wire o_done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                        if (start_req) begin
                            phase <= RUN;
                            start_seen <= 1'b1;
                            col_cnt <= 64'd0;
                            row_cnt <= 64'd0;
                        end
                    end
                    RUN: begin
                        pix_row <= font_row(cur_char, row_cnt[2:0]);
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                done <= 1'b1;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                    end
                    FIN: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

module bank_steer_demux (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        req,
    input  wire        resp,
    input  wire [15:0] addr,
    output reg  [3:0]  pending,
    output reg  [1:0]  phase,
    output reg  [15:0] done_cnt
);
    // phase: 0 = IDLE, 1 = ARMED (bank decoded), 2 = STARTED (bank pending), 3 = FINISHED
    reg [1:0]  bank_idx;
    reg [15:0] addr_q;

    initial phase    = 2'd0;
    initial pending  = 4'd0;
    initial bank_idx = 2'd0;
    initial addr_q   = 16'd0;
    initial done_cnt = 16'd0;

    always @(posedge clk) begin
        if (rst) begin
            phase    <= 2'd0;
            pending  <= 4'd0;
            bank_idx <= 2'd0;
            addr_q   <= 16'd0;
            done_cnt <= 16'd0;
        end else if (ce) begin
            case (phase)
                2'd0: if (req) begin
                    addr_q   <= addr;
                    bank_idx <= addr[1:0];
                    phase    <= 2'd1;
                end
                2'd1: begin
                    pending <= pending | (4'd1 << bank_idx);
                    phase   <= 2'd2;
                end
                2'd2: if (resp) begin
                    pending  <= pending & ~(4'd1 << bank_idx);
                    phase    <= 2'd3;
                    done_cnt <= done_cnt + 16'd1;
                end
                default: phase <= 2'd0;
            endcase
        end
    end

    // A finish can only be observed once the started bank request has been retired
    always @(*) assert (phase != 2'd3 || pending == 4'd0);
endmodule

module wwdg_window (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire       stop,
    input  wire       kick,
    input  wire [7:0] cfg_reload,
    input  wire [7:0] cfg_win,
    output wire [1:0] o_fault,
    output wire       o_armed,
    output wire [7:0] o_cnt
);
    reg       pv       = 1'b0;
    reg       armed    = 1'b0;
    reg [7:0] cnt      = 8'd64;
    reg [7:0] reload   = 8'd64;
    reg [7:0] win_thr  = 8'd0;
    reg [1:0] fault    = 2'b00;
    reg       win_open = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (start) begin
            armed    <= 1'b1;
            reload   <= cfg_reload | 8'h40;
            win_thr  <= cfg_win & 8'h3F;
            cnt      <= cfg_reload | 8'h40;
            fault    <= 2'b00;
            win_open <= 1'b0;
        end else if (stop) begin
            armed <= 1'b0;
        end else if (armed && ce && fault == 2'b00) begin
            if (kick) begin
                if (cnt > win_thr)
                    fault[0] <= 1'b1;
                else begin
                    cnt      <= reload;
                    win_open <= 1'b0;
                end
            end else if (cnt == 8'd0) begin
                fault[1] <= 1'b1;
            end else begin
                cnt      <= cnt - 8'd1;
                win_open <= ((cnt - 8'd1) <= win_thr);
            end
        end
    end

    assign o_fault = fault;
    assign o_armed = armed;
    assign o_cnt   = cnt;

    always @(posedge clk)
        if (pv && armed && $rose(fault[1]))
            assert (win_open);
endmodule

module huff_decoder64 (
    input wire clk,
    input wire rst,
    input wire start,
    input wire step,
    input wire wr_en,
    input wire wr_idx,
    input wire [63:0] bits_in,
    input wire [63:0] wr_code,
    input wire [63:0] wr_len,
    output wire busy,
    output wire [63:0] o_sym,
    output wire [63:0] o_nsym
);
    localparam [63:0] MAXLEN = 64'd8;

    // decode window / request outstanding
    reg win = 1'b0;
    // bit accumulator, consumed-code shift register, bit position, completion countdown
    reg [63:0] acc = 64'd0;
    reg [63:0] code_acc = 64'd0;
    reg [63:0] bitpos = 64'd0;
    reg [63:0] cnt = 64'd0;
    reg [63:0] sym = 64'd0;
    reg [63:0] nsym = 64'd0;
    // two-entry code table (code word + length)
    reg [63:0] code0 = 64'd0;
    reg [63:0] len0 = 64'd1;
    reg [63:0] code1 = 64'd2;
    reg [63:0] len1 = 64'd2;

    wire [63:0] nbits = bitpos + 64'd1;
    wire [63:0] ncode = {code_acc[62:0], acc[63]};
    wire hit0 = (nbits == len0) && (ncode == code0);
    wire hit1 = (nbits == len1) && (ncode == code1);
    wire esc  = (nbits == MAXLEN);

    always @(posedge clk) begin
        if (rst) begin
            win <= 1'b0;
            acc <= 64'd0;
            code_acc <= 64'd0;
            bitpos <= 64'd0;
            cnt <= 64'd0;
            nsym <= 64'd0;
        end else begin
            if (wr_en) begin
                if (wr_idx) begin
                    code1 <= wr_code;
                    len1 <= wr_len;
                end else begin
                    code0 <= wr_code;
                    len0 <= wr_len;
                end
            end
            if (win) begin
                if (step) begin
                    acc <= acc << 1;
                    code_acc <= ncode;
                    bitpos <= nbits;
                    cnt <= cnt - 64'd1;
                    if (hit0 || hit1 || esc) begin
                        win <= 1'b0;
                        nsym <= nsym + 64'd1;
                        sym <= hit0 ? 64'd0 : (hit1 ? 64'd1 : 64'd2);
                    end
                end
            end else if (start) begin
                win <= 1'b1;
                acc <= bits_in;
                code_acc <= 64'd0;
                bitpos <= 64'd0;
                cnt <= MAXLEN;
            end
        end
    end

    assign busy = win;
    assign o_sym = sym;
    assign o_nsym = nsym;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(win))
            assert ($past(cnt) != 64'd0);
endmodule

module bfx_unit (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire [2:0] i_op,
    input  wire       i_lock,
    input  wire       i_unlock,
    input  wire [7:0] i_src,
    input  wire [7:0] i_dst,
    output wire [7:0] o_res
);
    // field control: start position, width, and remaining headroom above the field
    reg [7:0] pos;
    reg [7:0] wid;
    reg [7:0] rem;
    reg [7:0] res;
    reg       win;
    initial pos = 8'd0;
    initial wid = 8'd0;
    initial rem = 8'd8;
    initial res = 8'd0;
    initial win = 1'b0;

    localparam OP_GROW = 3'd0, OP_SHRINK = 3'd1, OP_ADV = 3'd2, OP_RET = 3'd3,
               OP_EXTZ = 3'd4, OP_EXTS = 3'd5, OP_INS = 3'd6, OP_NOP = 3'd7;

    wire [7:0] mask = (wid >= 8'd8) ? 8'hFF : ((8'd1 << wid) - 8'd1);
    wire [7:0] ext  = (i_src >> pos) & mask;
    wire       sbit = ((wid != 8'd0) && (wid < 8'd8)) ? ext[wid[2:0] - 3'd1] : 1'b0;
    wire [7:0] exts = sbit ? (ext | ~mask) : ext;
    wire [7:0] ins  = (i_dst & ~(mask << pos)) | ((i_src & mask) << pos);

    always @(posedge clk) begin
        if (i_reset) begin
            pos <= 8'd0;
            wid <= 8'd0;
            rem <= 8'd8;
            res <= 8'd0;
            win <= 1'b0;
        end else if (i_ce) begin
            if (i_unlock)
                win <= 1'b0;
            else if (i_lock)
                win <= 1'b1;
            case (i_op)
                OP_GROW:   if (rem != 8'd0) begin wid <= wid + 8'd1; rem <= rem - 8'd1; end
                OP_SHRINK: if (wid != 8'd0) begin wid <= wid - 8'd1; rem <= rem + 8'd1; end
                OP_ADV:    if (rem != 8'd0) begin pos <= pos + 8'd1; rem <= rem - 8'd1; end
                OP_RET:    if (pos != 8'd0) begin pos <= pos - 8'd1; rem <= rem + 8'd1; end
                OP_EXTZ:   res <= ext;
                OP_EXTS:   res <= exts;
                OP_INS:    res <= ins;
                default:   ;
            endcase
        end
    end

    assign o_res = res;

    // between lock and unlock: field width never exceeds the word size
    always @(posedge clk)
        if (win) assert (wid <= 8'd8);
endmodule

module wb_port_arbiter (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire       issue,
    input  wire [7:0] lat,
    input  wire       oreq,
    input  wire [7:0] olat,
    output wire       acc,
    output wire       oacc,
    output wire       wb_fire,
    output wire       wb_trk
);
    // result-bus reservation shift register: bit i = write port booked i steps ahead
    reg [47:0] resv = 48'd0;
    // slot booked by the tracked (watched) functional unit request
    reg [47:0] trk  = 48'd0;
    // window register: set when tracked request accepted, cleared on its writeback
    reg        pend = 1'b0;
    // bounded-response countdown
    reg [7:0]  cnt  = 8'd0;

    wire [47:0] rsh = resv >> 1;
    wire lat_ok  = (lat  < 8'd48) && ((rsh & (48'd1 << lat))  == 48'd0);
    wire olat_ok = (olat < 8'd48) && ((rsh & (48'd1 << olat)) == 48'd0);

    assign acc  = step && issue && !pend && lat_ok;
    assign oacc = step && oreq && olat_ok && !(acc && (olat == lat));
    assign wb_fire = step && resv[0];
    assign wb_trk  = step && pend && trk[0];

    always @(posedge clk) begin
        if (rst) begin
            resv <= 48'd0;
            trk  <= 48'd0;
            pend <= 1'b0;
            cnt  <= 8'd0;
        end else if (step) begin
            resv <= rsh | (acc ? (48'd1 << lat) : 48'd0) | (oacc ? (48'd1 << olat) : 48'd0);
            trk  <= (trk >> 1) | (acc ? (48'd1 << lat) : 48'd0);
            if (pend) begin
                if (trk[0]) begin
                    pend <= 1'b0;
                    cnt  <= 8'd0;
                end else begin
                    cnt  <= cnt - 8'd1;
                end
            end else if (acc) begin
                pend <= 1'b1;
                cnt  <= lat + 8'd1;
            end
        end
    end

    // after accept (pend set) until writeback (pend cleared): countdown never expires
    assert property (!pend || cnt != 8'd0);
endmodule

module lpm_engine (
    input  wire        clk,
    input  wire        insert,
    input  wire        flush,
    input  wire [63:0] ins_prefix,
    input  wire [6:0]  ins_len,
    input  wire [63:0] key,
    output reg         hit,
    output reg  [4:0]  match_addr,
    output reg  [6:0]  match_len,
    output wire [63:0] o_count
);
    reg [63:0] prefix_mem [0:31];
    reg [6:0]  len_mem    [0:31];
    reg [31:0] valid;
    reg [5:0]  wr_ptr;
    reg [63:0] count;
    reg        armed;

    integer k;
    initial begin
        valid  = 32'd0;
        wr_ptr = 6'd0;
        count  = 64'd0;
        armed  = 1'b1;
        for (k = 0; k < 32; k = k + 1) begin
            prefix_mem[k] = 64'd0;
            len_mem[k]    = 7'd0;
        end
    end

    function [63:0] pmask;
        input [6:0] l;
        begin
            if (l >= 7'd64) pmask = ~64'd0;
            else            pmask = ~(~64'd0 >> l);
        end
    endfunction

    wire [6:0] ins_len_sat = (ins_len > 7'd64) ? 7'd64 : ins_len;

    always @(posedge clk) begin
        if (flush) begin
            valid  <= 32'd0;
            wr_ptr <= 6'd0;
            armed  <= 1'b0;
        end else if (insert && wr_ptr < 6'd32) begin
            prefix_mem[wr_ptr[4:0]] <= ins_prefix & pmask(ins_len_sat);
            len_mem[wr_ptr[4:0]]    <= ins_len_sat;
            valid[wr_ptr[4:0]]      <= 1'b1;
            wr_ptr <= wr_ptr + 6'd1;
            count  <= count + 64'd1;
        end
    end

    integer i;
    always @(*) begin
        hit        = 1'b0;
        match_addr = 5'd0;
        match_len  = 7'd0;
        for (i = 0; i < 32; i = i + 1) begin
            if (valid[i] && (((key ^ prefix_mem[i]) & pmask(len_mem[i])) == 64'd0)
                && (!hit || len_mem[i] > match_len)) begin
                hit        = 1'b1;
                match_addr = i[4:0];
                match_len  = len_mem[i];
            end
        end
    end

    assign o_count = count;

    always @(*)
        if (armed)
            assert (count <= 64'd32);
endmodule

module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
    output reg rest_ack
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;

    reg [7:0] ramp_cnt;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
                    end
                end
                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
                        ramp_ack <= 1'b1;
                        state <= S_REST;
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
endmodule

module eink_cic_decim (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire [127:0] din,
    output wire [127:0] o_pix,
    output wire         o_valid
);
    // 2-stage CIC decimator (R=4) smoothing grayscale waveform drive levels
    reg [127:0] integ1, integ2;
    reg [127:0] comb1_dly, comb2_dly;
    reg [127:0] dout;
    reg [1:0]   phase;
    reg         seen_nz;   // shadow: a nonzero sample has been accepted
    reg         vld;
    initial integ1 = 128'd0;
    initial integ2 = 128'd0;
    initial comb1_dly = 128'd0;
    initial comb2_dly = 128'd0;
    initial dout = 128'd0;
    initial phase = 2'd0;
    initial seen_nz = 1'b0;
    initial vld = 1'b0;

    wire [127:0] c1 = integ2 - comb1_dly;
    wire [127:0] c2 = c1 - comb2_dly;

    always @(posedge clk) begin
        if (rst) begin
            integ1 <= 128'd0;
            integ2 <= 128'd0;
            comb1_dly <= 128'd0;
            comb2_dly <= 128'd0;
            dout <= 128'd0;
            phase <= 2'd0;
            seen_nz <= 1'b0;
            vld <= 1'b0;
        end else if (i_ce) begin
            integ1 <= integ1 + din;
            integ2 <= integ2 + integ1;
            phase <= phase + 2'd1;
            if (din != 128'd0)
                seen_nz <= 1'b1;
            if (phase == 2'd3) begin
                comb1_dly <= integ2;
                comb2_dly <= c1;
                dout <= c2;
                vld <= 1'b1;
            end else begin
                vld <= 1'b0;
            end
        end
    end

    assign o_pix = dout;
    assign o_valid = vld;

    // Precedence: a nonzero output requires a nonzero input accepted earlier
    always @(posedge clk)
        if (dout != 128'd0) assert (seen_nz);
endmodule

module mcast_demux (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_arm,
    input  wire [7:0] i_mask,
    input  wire [7:0] i_data,
    input  wire [7:0] i_ready,
    output wire [7:0] o_valid,
    output wire [7:0] o_data,
    output wire       o_done,
    output wire       o_busy
);
    localparam IDLE  = 2'd0;
    localparam ARMED = 2'd1;
    localparam SEND  = 2'd2;
    localparam FIN   = 2'd3;

    reg [1:0] phase;
    reg [7:0] mask;
    reg [7:0] delivered;
    reg [7:0] data;
    initial phase = IDLE;
    initial mask = 8'd0;
    initial delivered = 8'd0;
    initial data = 8'd0;

    assign o_valid = (phase == SEND) ? (mask & ~delivered) : 8'd0;
    assign o_data  = data;
    assign o_done  = (phase == FIN);
    assign o_busy  = (phase != IDLE);

    wire [7:0] accepted = o_valid & i_ready;
    wire [7:0] next_del = delivered | accepted;

    always @(posedge clk) begin
        if (i_reset) begin
            phase     <= IDLE;
            mask      <= 8'd0;
            delivered <= 8'd0;
            data      <= 8'd0;
        end else if (i_ce) begin
            case (phase)
                IDLE: begin
                    if (i_arm && (i_mask != 8'd0)) begin
                        mask      <= i_mask;
                        data      <= i_data;
                        delivered <= 8'd0;
                        phase     <= ARMED;
                    end
                end
                ARMED: begin
                    phase <= SEND;
                end
                SEND: begin
                    delivered <= next_del;
                    if (next_del == mask)
                        phase <= FIN;
                end
                FIN: begin
                    phase     <= IDLE;
                    mask      <= 8'd0;
                    delivered <= 8'd0;
                end
            endcase
        end
    end

    // finish implies a copy was started (at least one delivery)
    always @(*)
        if (phase == FIN) assert (delivered != 8'd0);

    // finish implies an arm with a non-empty destination mask happened
    always @(*)
        if (phase == FIN) assert (mask != 8'd0);
endmodule

module remap_unit (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_seq_go,
    input  wire        i_unlock,
    input  wire        i_cfg_we,
    input  wire        i_cfg_sel,
    input  wire        i_cfg_en,
    input  wire [63:0] i_cfg_src,
    input  wire [63:0] i_cfg_size,
    input  wire [63:0] i_cfg_tgt,
    input  wire [63:0] i_addr,
    output wire [63:0] o_addr,
    output wire        o_hit
);
    localparam [63:0] ROM_BASE  = 64'h0000_0000_2000_0000;
    localparam [63:0] ROM_SIZE  = 64'h0000_0000_0001_0000;
    localparam [63:0] DRAM_BASE = 64'h0000_0000_8000_0000;
    localparam [63:0] DRAM_SIZE = 64'h0000_0000_4000_0000;

    // scope register: high until software unlocks the remap table
    reg        boot_phase = 1'b1;
    // boot handoff sequencer: 0 alias, 1 copy, 2 drain, 3 ram at zero
    reg [63:0] seq        = 64'd0;
    // window 0: boot ROM aliased to address zero
    reg        alias_en   = 1'b1;
    reg [63:0] src0       = 64'd0;
    reg [63:0] size0      = ROM_SIZE;
    reg [63:0] tgt0       = ROM_BASE;
    // window 1: DRAM mapped at address zero
    reg        ram_en     = 1'b0;
    reg [63:0] src1       = 64'd0;
    reg [63:0] size1      = DRAM_SIZE;
    reg [63:0] tgt1       = DRAM_BASE;

    always @(posedge clk) begin
        if (i_reset) begin
            boot_phase <= 1'b1;
            seq        <= 64'd0;
            alias_en   <= 1'b1;
            src0       <= 64'd0;
            size0      <= ROM_SIZE;
            tgt0       <= ROM_BASE;
            ram_en     <= 1'b0;
            src1       <= 64'd0;
            size1      <= DRAM_SIZE;
            tgt1       <= DRAM_BASE;
        end else if (i_ce) begin
            if (i_unlock)
                boot_phase <= 1'b0;
            if (i_seq_go && (seq != 64'd3))
                seq <= seq + 64'd1;
            if (i_seq_go && (seq == 64'd1))
                alias_en <= 1'b0;
            if (i_seq_go && (seq == 64'd2))
                ram_en <= 1'b1;
            if (i_cfg_we && !boot_phase) begin
                if (i_cfg_sel) begin
                    src1   <= i_cfg_src;
                    size1  <= i_cfg_size;
                    tgt1   <= i_cfg_tgt;
                    ram_en <= i_cfg_en;
                end else begin
                    src0     <= i_cfg_src;
                    size0    <= i_cfg_size;
                    tgt0     <= i_cfg_tgt;
                    alias_en <= i_cfg_en;
                end
            end
        end
    end

    wire [63:0] off0 = i_addr - src0;
    wire [63:0] off1 = i_addr - src1;
    wire hit0 = alias_en && (i_addr >= src0) && (off0 < size0);
    wire hit1 = ram_en   && (i_addr >= src1) && (off1 < size1);

    assign o_hit  = hit0 || hit1;
    assign o_addr = hit0 ? (tgt0 + off0) : (hit1 ? (tgt1 + off1) : i_addr);

    // Absence, before unlock: address zero never has two owners
    always @(posedge clk)
        if (boot_phase)
            assert (!(alias_en && ram_en));
endmodule

module dram_init_seq (
    input wire clk,
    input wire rst,
    input wire step,
    input wire rel,
    output reg [2:0] cmd,
    output reg cke,
    output reg init_done
);
    reg [3:0]  cmd_idx  = 4'd0;
    reg [63:0] wait_cnt = 64'd0;
    reg        zq_done  = 1'b0;
    reg        armed    = 1'b0;

    initial cmd = 3'd0;
    initial cke = 1'b0;
    initial init_done = 1'b0;

    function [63:0] cmd_delay;
        input [3:0] idx;
        begin
            case (idx)
                4'd0:    cmd_delay = 64'd4;
                4'd1:    cmd_delay = 64'd3;
                4'd14:   cmd_delay = 64'd4;
                default: cmd_delay = 64'd1;
            endcase
        end
    endfunction

    function [2:0] cmd_code;
        input [3:0] idx;
        begin
            if (idx == 4'd0)       cmd_code = 3'd1;
            else if (idx == 4'd1)  cmd_code = 3'd2;
            else if (idx == 4'd14) cmd_code = 3'd4;
            else if (idx == 4'd15) cmd_code = 3'd0;
            else                   cmd_code = 3'd3;
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            cmd_idx   <= 4'd0;
            wait_cnt  <= 64'd0;
            zq_done   <= 1'b0;
            armed     <= 1'b0;
            init_done <= 1'b0;
            cmd       <= 3'd0;
            cke       <= 1'b0;
        end else if (step) begin
            cmd <= 3'd0;
            if (rel) armed <= 1'b0;
            if (wait_cnt != 64'd0) begin
                wait_cnt <= wait_cnt - 64'd1;
            end else if (cmd_idx != 4'd15) begin
                cmd      <= cmd_code(cmd_idx);
                wait_cnt <= cmd_delay(cmd_idx);
                cmd_idx  <= cmd_idx + 4'd1;
                if (cmd_idx == 4'd1) begin
                    cke <= 1'b1;
                    if (!rel) armed <= 1'b1;
                end
                if (cmd_idx == 4'd14) zq_done <= 1'b1;
            end else begin
                init_done <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (armed && init_done)
            assert (zq_done);
endmodule

module const_slicer (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       req,
    input  wire       cfg_we,
    input  wire [1:0] cfg_order,
    input  wire [7:0] in_i,
    input  wire [7:0] in_q,
    output reg  [3:0] dec_bits,
    output reg  [7:0] err_i,
    output reg  [7:0] err_q,
    output reg        done,
    output wire       busy_o
);
    reg [1:0] mod_order;
    reg [7:0] sym_i, sym_q;
    reg       busy;
    reg [7:0] cd;
    reg [7:0] phase;
    reg       pre_cfg;
    reg       pv;

    initial begin
        mod_order = 2'd1; sym_i = 8'd0; sym_q = 8'd0;
        busy = 1'b0; cd = 8'd0; phase = 8'd0;
        dec_bits = 4'd0; err_i = 8'd0; err_q = 8'd0; done = 1'b0;
        pre_cfg = 1'b1; pv = 1'b0;
    end

    assign busy_o = busy;

    wire si = sym_i[7];
    wire sq = sym_q[7];
    wire mi = sym_i[7] ^ sym_i[6];
    wire mq = sym_q[7] ^ sym_q[6];
    wire qam = mod_order[1];

    wire [7:0] qam_pt_i = si ? (mi ? 8'hA0 : 8'hE0) : (mi ? 8'h60 : 8'h20);
    wire [7:0] qam_pt_q = sq ? (mq ? 8'hA0 : 8'hE0) : (mq ? 8'h60 : 8'h20);
    wire [7:0] psk_pt_i = si ? 8'hC0 : 8'h40;
    wire [7:0] psk_pt_q = sq ? 8'hC0 : 8'h40;

    wire [7:0] pt_i = qam ? qam_pt_i : psk_pt_i;
    wire [7:0] pt_q = qam ? qam_pt_q : ((mod_order == 2'd0) ? 8'h00 : psk_pt_q);
    wire [3:0] bits = qam ? {mq, sq, mi, si}
                    : ((mod_order == 2'd0) ? {3'b000, si} : {2'b00, sq, si});

    always @(posedge clk) begin
        if (rst) begin
            busy  <= 1'b0;
            cd    <= 8'd0;
            phase <= 8'd0;
            done  <= 1'b0;
        end else if (ce) begin
            done <= 1'b0;
            if (cfg_we && !busy)
                mod_order <= cfg_order;
            if (!busy) begin
                if (req) begin
                    sym_i <= in_i;
                    sym_q <= in_q;
                    busy  <= 1'b1;
                    cd    <= 8'd4;
                    phase <= 8'd0;
                end
            end else begin
                cd <= cd - 8'd1;
                if (phase == 8'd3) begin
                    busy     <= 1'b0;
                    phase    <= 8'd0;
                    dec_bits <= bits;
                    err_i    <= sym_i - pt_i;
                    err_q    <= sym_q - pt_q;
                    done     <= 1'b1;
                end else begin
                    phase <= phase + 8'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (!rst && ce && cfg_we && !busy)
            pre_cfg <= 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_cfg && $past(busy))
            assert ($past(cd) != 8'd0);
endmodule

module r2sdf_stage (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [63:0] x_in,
    output reg  [63:0] y_out,
    output reg         y_valid
);
    // single-delay-feedback memory: N/2 = 64 entries
    reg [63:0] dly [0:63];
    reg [63:0] ptr;       // stage control counter (0..63)
    reg        phase;     // 0 = fill, 1 = compute (butterfly)
    reg [63:0] bfly_cnt;  // butterflies issued
    reg        armed;     // high until the first frame's compute pass completes
    integer i;

    initial begin
        ptr = 64'd0; phase = 1'b0; bfly_cnt = 64'd0; armed = 1'b1;
        y_out = 64'd0; y_valid = 1'b0;
        for (i = 0; i < 64; i = i + 1) dly[i] = 64'd0;
    end

    wire [5:0]  idx    = ptr[5:0];
    wire [63:0] fb     = dly[idx];
    wire [63:0] bf_sum = fb + x_in;
    wire [63:0] bf_dif = fb - x_in;
    wire        last   = (ptr == 64'd63);

    always @(posedge clk) begin
        if (rst) begin
            ptr <= 64'd0; phase <= 1'b0; bfly_cnt <= 64'd0; armed <= 1'b1;
            y_out <= 64'd0; y_valid <= 1'b0;
        end else if (en) begin
            if (phase) begin
                // compute: butterfly between delayed sample and new sample
                dly[idx] <= bf_dif;
                y_out    <= bf_sum;
                bfly_cnt <= bfly_cnt + 64'd1;
                if (last) armed <= 1'b0;
            end else begin
                // fill: push new sample into delay line, drain previous differences
                dly[idx] <= x_in;
                y_out    <= fb;
            end
            y_valid <= 1'b1;
            if (last) begin
                ptr   <= 64'd0;
                phase <= ~phase;
            end else begin
                ptr <= ptr + 64'd1;
            end
        end
    end

    // before the first frame completes, at most 63 butterflies have been issued
    always @(posedge clk) if (armed) assert (bfly_cnt <= 64'd63);
endmodule

module mtile_od_loader (
    input  wire         clk,
    input  wire         step,
    input  wire         req,
    input  wire         ext_hold,
    input  wire [127:0] din,
    input  wire [3:0]   raddr,
    output wire [127:0] rdata,
    output wire         bus_line,
    output wire         busy_o
);
    // tile register: 16 rows of 128-bit data
    reg [127:0] tile [0:15];
    reg         busy;
    reg [4:0]   cnt;    // completion countdown
    reg [3:0]   beats;  // rows loaded so far
    reg         armed;  // sticky: set at first accepted request
    reg         pv;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) tile[i] = 128'd0;
        busy  = 1'b0;
        cnt   = 5'd0;
        beats = 4'd0;
        armed = 1'b0;
        pv    = 1'b0;
    end

    // open-drain drivers on a wired-AND ready line with external pull-up:
    // each driver pulls the line low while its input is asserted, otherwise releases it
    wire [1:0] od_pull = {ext_hold, busy};
    wire [1:0] od_rel  = ~od_pull;
    assign bus_line = &od_rel;

    always @(posedge clk) begin
        if (step) begin
            if (busy) begin
                tile[beats] <= din;
                if (beats == 4'd15) begin
                    busy  <= 1'b0;
                    cnt   <= 5'd0;
                    beats <= 4'd0;
                end else begin
                    beats <= beats + 4'd1;
                    cnt   <= cnt - 5'd1;
                end
            end else if (req && bus_line) begin
                busy  <= 1'b1;
                cnt   <= 5'd16;
                beats <= 4'd0;
                armed <= 1'b1;
            end
        end
    end

    assign rdata  = tile[raddr];
    assign busy_o = busy;

    always @(posedge clk) pv <= 1'b1;

    // bounded response: countdown never expired while the load was still outstanding
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(busy) || $past(cnt) != 5'd0);
endmodule

module razor_shadow_stage (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire [63:0] d_main,
    input  wire [63:0] d_late,
    output reg  [63:0] main_q,
    output reg  [63:0] shadow_q,
    output reg  [63:0] err_cnt,
    output reg         razor_err
);
    localparam [1:0] IDLE    = 2'd0;
    localparam [1:0] ARMED   = 2'd1;
    localparam [1:0] STARTED = 2'd2;
    localparam [1:0] DONE    = 2'd3;

    reg [1:0] phase = IDLE;
    reg armed = 1'b0;
    reg started = 1'b0;
    reg finished = 1'b0;

    initial begin
        main_q    = 64'd0;
        shadow_q  = 64'd0;
        err_cnt   = 64'd0;
        razor_err = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase     <= IDLE;
            armed     <= 1'b0;
            started   <= 1'b0;
            finished  <= 1'b0;
            main_q    <= 64'd0;
            shadow_q  <= 64'd0;
            err_cnt   <= 64'd0;
            razor_err <= 1'b0;
        end else if (ce) begin
            case (phase)
                IDLE: begin
                    main_q   <= d_main;
                    armed    <= 1'b1;
                    started  <= 1'b0;
                    finished <= 1'b0;
                    phase    <= ARMED;
                end
                ARMED: begin
                    shadow_q <= d_late;
                    started  <= 1'b1;
                    phase    <= STARTED;
                end
                STARTED: begin
                    razor_err <= (main_q != shadow_q);
                    if (main_q != shadow_q) begin
                        main_q  <= shadow_q;
                        err_cnt <= err_cnt + 64'd1;
                    end
                    finished <= 1'b1;
                    phase    <= DONE;
                end
                default: begin
                    armed    <= 1'b0;
                    started  <= 1'b0;
                    finished <= 1'b0;
                    phase    <= IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (finished) assert (started && armed);
endmodule

module crc_residue_chk (
    input  wire clk,
    input  wire ce,
    input  wire start,
    input  wire din,
    output reg  done,
    output reg  err
);
    // bit-serial CRC-8 (poly x^8+x^2+x+1) residue checker:
    // 8 data bits followed by 8 appended CRC bits; residue must be zero
    reg [7:0] crc    = 8'h00;
    reg [7:0] bitcnt = 8'd0;   // bits consumed in current frame
    reg [7:0] timer  = 8'd0;   // completion watchdog countdown
    reg       busy   = 1'b0;   // frame outstanding
    reg       armed  = 1'b1;   // scope: no CRC error has ever been flagged
    initial done = 1'b0;
    initial err  = 1'b0;

    wire       fb       = crc[7] ^ din;
    wire [7:0] crc_next = {crc[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);
    wire       last     = busy && ce && (bitcnt == 8'd15);

    always @(posedge clk) begin
        if (!busy) begin
            if (start) begin
                busy   <= 1'b1;
                bitcnt <= 8'd0;
                timer  <= 8'd16;
                crc    <= 8'h00;
                done   <= 1'b0;
                err    <= 1'b0;
            end
        end else if (ce) begin
            crc    <= crc_next;
            bitcnt <= bitcnt + 8'd1;
            timer  <= timer - 8'd1;
            if (bitcnt == 8'd15) begin
                busy <= 1'b0;
                done <= 1'b1;
                err  <= (crc_next != 8'h00);
            end
        end
        if (last && (crc_next != 8'h00))
            armed <= 1'b0;
    end

    // before the first CRC error: the watchdog never expires while a frame is outstanding
    always @(*)
        assert (!armed || !busy || timer != 8'd0);
endmodule

module irq_pulse_stretch (
    input  wire clk,
    input  wire ce,
    input  wire irq_pulse,
    input  wire win_open,
    input  wire win_close,
    output reg  irq_out
);
    localparam [63:0] LEN = 64'd12;

    reg [63:0] remain = 64'd0;
    reg [63:0] held   = 64'd0;
    reg        win    = 1'b0;
    initial irq_out = 1'b0;

    always @(posedge clk) begin
        if (ce) begin
            if (win_close)     win <= 1'b0;
            else if (win_open) win <= 1'b1;

            if (!irq_out) begin
                if (irq_pulse) begin
                    irq_out <= 1'b1;
                    remain  <= LEN - 64'd1;
                    held    <= 64'd1;
                end
            end else if (remain == 64'd0) begin
                irq_out <= 1'b0;
            end else begin
                remain <= remain - 64'd1;
                held   <= held + 64'd1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $fell(irq_out))
            assert (held <= LEN);
endmodule

module conv_enc_win (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire din,
    input wire start,
    input wire stop,
    output reg c0,
    output reg c1,
    output reg win,
    output reg [15:0] nbits
);
    // constraint-length-4 shift register of past input bits (4 entries)
    reg [3:0] sr;
    initial sr = 4'b0000;
    initial c0 = 1'b0;
    initial c1 = 1'b0;
    initial win = 1'b0;
    initial nbits = 16'd0;

    wire [3:0] sr_n = {sr[2:0], din};

    // G0 = 1111 computed incrementally as a sliding-window parity,
    // G1 = 1011 computed directly from the next shift-register contents
    always @(posedge clk) begin
        if (rst) begin
            sr    <= 4'b0000;
            c0    <= 1'b0;
            c1    <= 1'b0;
            nbits <= 16'd0;
        end else if (ce) begin
            sr    <= sr_n;
            c0    <= c0 ^ din ^ sr[3];
            c1    <= sr_n[3] ^ sr_n[1] ^ sr_n[0];
            nbits <= nbits + 16'd1;
        end
    end

    // observation window: opened by start, closed by stop
    always @(posedge clk) begin
        if (rst)
            win <= 1'b0;
        else if (start)
            win <= 1'b1;
        else if (stop)
            win <= 1'b0;
    end

    reg pv = 0;
    always @(posedge clk) pv <= 1;

    // inside the window, the XOR of the two code bits equals the input bit
    // that sat in tap position 1 before the shift
    always @(posedge clk)
        if (pv && win && $past(ce) && !$past(rst))
            assert ((c0 ^ c1) == $past(sr[1]));
endmodule

module cordic_rot64 (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire        ack,
    input  wire [63:0] x_in,
    input  wire [63:0] y_in,
    input  wire [63:0] z_in,
    output wire [63:0] x_out,
    output wire [63:0] y_out,
    output wire [63:0] z_out,
    output wire        busy_o,
    output wire        done_o
);
    localparam [63:0] N_ITER = 64'd32;

    reg signed [63:0] x, y, z;
    reg [63:0] iter, remaining;
    reg busy, done, armed;

    initial begin
        x = 64'd0; y = 64'd0; z = 64'd0;
        iter = 64'd0; remaining = N_ITER;
        busy = 1'b0; done = 1'b0; armed = 1'b0;
    end

    // 32-entry arctangent ROM, angle in Q32 radians held in 64 bits
    function [63:0] atan_lut;
        input [4:0] i;
        begin
            case (i)
                5'd0: atan_lut = 64'h00000000C90FDAA2;
                5'd1: atan_lut = 64'h0000000076B19C16;
                5'd2: atan_lut = 64'h000000003EB6EBF2;
                5'd3: atan_lut = 64'h000000001FD5BA9B;
                5'd4: atan_lut = 64'h000000000FFAADDC;
                5'd5: atan_lut = 64'h0000000007FF556F;
                5'd6: atan_lut = 64'h0000000003FFEAAB;
                5'd7: atan_lut = 64'h0000000001FFFD55;
                default: atan_lut = 64'd1 << (6'd32 - {1'b0, i});
            endcase
        end
    endfunction

    wire [4:0] sh = iter[4:0];

    always @(posedge clk) begin
        if (rst) begin
            x <= 64'd0; y <= 64'd0; z <= 64'd0;
            iter <= 64'd0; remaining <= N_ITER;
            busy <= 1'b0; done <= 1'b0; armed <= 1'b0;
        end else if (ce) begin
            if (start && !busy) begin
                x <= x_in; y <= y_in; z <= z_in;
                iter <= 64'd0;
                remaining <= N_ITER;
                busy <= 1'b1;
                done <= 1'b0;
                armed <= 1'b1;
            end else begin
                if (ack) armed <= 1'b0;
                if (busy) begin
                    if (z[63] == 1'b0) begin
                        x <= x - (y >>> sh);
                        y <= y + (x >>> sh);
                        z <= z - atan_lut(sh);
                    end else begin
                        x <= x + (y >>> sh);
                        y <= y - (x >>> sh);
                        z <= z + atan_lut(sh);
                    end
                    iter <= iter + 64'd1;
                    remaining <= remaining - 64'd1;
                    if (iter == N_ITER - 64'd1) begin
                        busy <= 1'b0;
                        done <= 1'b1;
                    end
                end
            end
        end
    end

    assign x_out = x;
    assign y_out = y;
    assign z_out = z;
    assign busy_o = busy;
    assign done_o = done;

    // After a start (armed) until ack: never busy with the iteration budget exhausted
    always @(posedge clk)
        if (armed)
            assert (!(busy && remaining == 64'd0));
endmodule

module gray_tally (
    input  wire        clk,
    input  wire        start,
    input  wire        stop,
    input  wire        step,
    output reg  [63:0] bin,
    output reg  [63:0] gray,
    output reg         armed
);
    initial bin   = 64'd0;
    initial gray  = 64'd0;
    initial armed = 1'b0;

    // next binary count and the bits that change on increment
    wire [63:0] bin_nx = bin + 64'd1;
    wire [63:0] diff   = bin ^ bin_nx;
    // binary-to-Gray conversion of the change mask: XOR each bit with its upper neighbour
    wire [63:0] flip   = diff ^ (diff >> 1);

    // tally counters: binary count plus an incrementally maintained Gray image
    always @(posedge clk) begin
        if (start) begin
            bin  <= 64'd0;
            gray <= 64'd0;
        end else if (step) begin
            bin  <= bin_nx;
            gray <= gray ^ flip;
        end
    end

    // observation window: opened by start, closed by stop (stop may never come)
    always @(posedge clk) begin
        if (start)
            armed <= 1'b1;
        else if (stop)
            armed <= 1'b0;
    end

    // inside the window the Gray image is zero exactly when the binary count is zero
    assert property (!armed || ((gray == 64'd0) == (bin == 64'd0)));
endmodule

module bitslip_align (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_slip,
    input  wire        i_lock,
    input  wire [31:0] i_word,
    output wire [31:0] o_word,
    output wire        o_armed
);
    // two-word window of the incoming serial stream
    reg [63:0] window  = 64'd0;
    // slip offset (up counter) and its redundant remaining-slips counter (down counter)
    reg [31:0] slip    = 32'd0;
    reg [31:0] slip_dn = 32'd31;
    // sticky: set the first time word lock is reported
    reg        armed   = 1'b0;

    always @(posedge clk) begin
        if (i_ce) begin
            window <= {window[31:0], i_word};
            if (i_lock)
                armed <= 1'b1;
            if (i_slip) begin
                // up counter wraps when the down counter is exhausted
                slip    <= (slip_dn == 32'd0)  ? 32'd0  : slip + 32'd1;
                // down counter reloads when the up counter hits the last offset
                slip_dn <= (slip == 32'd31)    ? 32'd31 : slip_dn - 32'd1;
            end
        end
    end

    wire [63:0] shifted = window << slip[4:0];
    assign o_word  = shifted[63:32];
    assign o_armed = armed;

    // after lock: the slip offset never exceeds one word width minus one
    always @(posedge clk)
        if (armed)
            assert (slip <= 32'd31);

    // after lock: the remaining-slip counter never exceeds one word width minus one
    always @(posedge clk)
        if (armed)
            assert (slip_dn <= 32'd31);
endmodule

module mdio_master64 (
    input  wire        clk,
    input  wire        ce,
    input  wire        start,
    input  wire        op_rd,
    input  wire [4:0]  phy_ad,
    input  wire [4:0]  reg_ad,
    input  wire [15:0] wr_data,
    input  wire        mdio_i,
    output wire        mdio_o,
    output wire        mdio_oe,
    output wire        busy,
    output wire [63:0] o_rd_data
);
    localparam [2:0] IDLE = 3'd0, PRE = 3'd1, CMD = 3'd2, TA = 3'd3, DATA = 3'd4;

    reg [2:0]  phase      = IDLE;
    reg [63:0] pre_cnt    = 64'd0;
    reg [31:0] frame_sr   = 32'd0;
    reg [63:0] bit_cnt    = 64'd0;
    reg        ta         = 1'b0;
    reg        op_read    = 1'b0;
    reg [15:0] rx_sh      = 16'd0;
    reg [63:0] rd_data    = 64'd0;
    reg        ta_pending = 1'b0;

    always @(posedge clk) begin
        if (ce) begin
            case (phase)
                IDLE: begin
                    if (start) begin
                        op_read  <= op_rd;
                        frame_sr <= {2'b01, (op_rd ? 2'b10 : 2'b01), phy_ad, reg_ad, 2'b10, wr_data};
                        pre_cnt  <= 64'd0;
                        bit_cnt  <= 64'd0;
                        phase    <= PRE;
                    end
                end
                PRE: begin
                    if (pre_cnt == 64'd31) begin
                        pre_cnt <= 64'd0;
                        bit_cnt <= 64'd0;
                        phase   <= CMD;
                    end else begin
                        pre_cnt <= pre_cnt + 64'd1;
                    end
                end
                CMD: begin
                    frame_sr <= {frame_sr[30:0], 1'b0};
                    if (bit_cnt == 64'd13) begin
                        bit_cnt <= 64'd0;
                        ta      <= 1'b1;
                        phase   <= TA;
                    end else begin
                        bit_cnt <= bit_cnt + 64'd1;
                    end
                end
                TA: begin
                    frame_sr <= {frame_sr[30:0], 1'b0};
                    if (bit_cnt == 64'd1) begin
                        bit_cnt <= 64'd0;
                        ta      <= 1'b0;
                        phase   <= DATA;
                        if (op_read) ta_pending <= 1'b1;
                    end else begin
                        bit_cnt <= bit_cnt + 64'd1;
                    end
                end
                DATA: begin
                    frame_sr <= {frame_sr[30:0], 1'b0};
                    if (op_read) rx_sh <= {rx_sh[14:0], mdio_i};
                    if (bit_cnt == 64'd15) begin
                        bit_cnt <= 64'd0;
                        phase   <= IDLE;
                        if (op_read) begin
                            rd_data    <= {48'd0, rx_sh[14:0], mdio_i};
                            ta_pending <= 1'b0;
                        end
                    end else begin
                        bit_cnt <= bit_cnt + 64'd1;
                    end
                end
                default: begin
                    phase <= IDLE;
                    ta    <= 1'b0;
                end
            endcase
        end
    end

    assign mdio_oe   = (phase == PRE) || (phase == CMD) || ((phase == TA || phase == DATA) && !op_read);
    assign mdio_o    = (phase == PRE) ? 1'b1 : frame_sr[31];
    assign busy      = (phase != IDLE);
    assign o_rd_data = rd_data;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $stable(ta_pending))
            assert ($stable(rd_data));
endmodule

module phase_clkgen (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        cfg_we,
    input  wire [2:0]  cfg_sel,
    input  wire [15:0] cfg_div,
    input  wire [15:0] cfg_off,
    input  wire        win_open,
    input  wire        win_close,
    output wire [7:0]  clk_out,
    output wire [7:0]  align_pulse
);
    localparam [15:0] LAP = 16'd240;

    reg [15:0]  cyc        = 16'd0;
    reg [15:0]  lap        = 16'd0;
    reg [127:0] div_sh     = {8{16'd2}};
    reg [127:0] off_sh     = 128'd0;
    reg [127:0] div_act    = {8{16'd2}};
    reg [127:0] off_act    = 128'd0;
    reg [127:0] ph         = 128'd0;
    reg [15:0]  align_cnt0 = 16'd0;
    reg         win        = 1'b0;
    reg         pv         = 1'b0;

    wire        wrap = (cyc == LAP - 16'd1);
    wire [15:0] off0 = off_act[15:0];

    genvar g;
    generate
        for (g = 0; g < 8; g = g + 1) begin : outs
            assign clk_out[g]     = ph[g*16 +: 16] < (div_act[g*16 +: 16] >> 1);
            assign align_pulse[g] = ce && (cyc == off_act[g*16 +: 16]);
        end
    endgenerate

    integer i;
    always @(posedge clk) begin
        if (rst) begin
            cyc        <= 16'd0;
            lap        <= 16'd0;
            align_cnt0 <= 16'd0;
            win        <= 1'b0;
            ph         <= 128'd0;
            div_act    <= {8{16'd2}};
            off_act    <= 128'd0;
            div_sh     <= {8{16'd2}};
            off_sh     <= 128'd0;
        end else begin
            if (win_close)     win <= 1'b0;
            else if (win_open) win <= 1'b1;
            if (cfg_we) begin
                div_sh[cfg_sel*16 +: 16] <= cfg_div;
                off_sh[cfg_sel*16 +: 16] <= cfg_off;
            end
            if (ce) begin
                if (wrap) begin
                    cyc        <= 16'd0;
                    lap        <= lap + 16'd1;
                    align_cnt0 <= 16'd0;
                end else begin
                    cyc <= cyc + 16'd1;
                    if (cyc == off0) align_cnt0 <= align_cnt0 + 16'd1;
                end
                for (i = 0; i < 8; i = i + 1) begin
                    if (wrap) begin
                        div_act[i*16 +: 16] <= (div_sh[i*16 +: 16] < 16'd2) ? 16'd2 : div_sh[i*16 +: 16];
                        off_act[i*16 +: 16] <= (off_sh[i*16 +: 16] >= LAP) ? (LAP - 16'd1) : off_sh[i*16 +: 16];
                    end
                    if (cyc == off_act[i*16 +: 16])
                        ph[i*16 +: 16] <= 16'd0;
                    else if (ph[i*16 +: 16] >= div_act[i*16 +: 16] - 16'd1)
                        ph[i*16 +: 16] <= 16'd0;
                    else
                        ph[i*16 +: 16] <= ph[i*16 +: 16] + 16'd1;
                end
            end
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $stable(lap) && $past(align_cnt0) >= 16'd1)
            assert ($stable(align_cnt0));
endmodule

module bitserial_alu (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       arm,
    input  wire       start,
    input  wire       ack,
    input  wire [1:0] op,
    input  wire [7:0] a_in,
    input  wire [7:0] b_in,
    output wire [7:0] result,
    output wire       done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3;

    reg [1:0] phase      = 2'd0;
    reg [7:0] cnt        = 8'd0;
    reg       seen_arm   = 1'b0;
    reg       seen_start = 1'b0;
    reg [1:0] op_r       = 2'd0;
    reg [7:0] opa        = 8'd0;
    reg [7:0] opb        = 8'd0;
    reg [7:0] res        = 8'd0;
    reg       carry      = 1'b0;

    wire abit = opa[0];
    wire bbit = (op_r == 2'd1) ? ~opb[0] : opb[0];
    wire sbit = abit ^ bbit ^ carry;
    wire cout = (abit & bbit) | (abit & carry) | (bbit & carry);
    wire fbit = (op_r == 2'd2) ? (abit & opb[0]) :
                (op_r == 2'd3) ? (abit ^ opb[0]) : sbit;

    assign result = res;
    assign done   = (phase == DONE);

    always @(posedge clk) begin
        if (rst) begin
            phase      <= IDLE;
            cnt        <= 8'd0;
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            carry      <= 1'b0;
        end else if (ce) begin
            case (phase)
                IDLE: begin
                    if (arm) begin
                        phase      <= ARMED;
                        seen_arm   <= 1'b1;
                        seen_start <= 1'b0;
                        op_r       <= op;
                    end
                end
                ARMED: begin
                    if (start) begin
                        phase      <= RUN;
                        seen_start <= 1'b1;
                        cnt        <= 8'd0;
                        opa        <= a_in;
                        opb        <= b_in;
                        res        <= 8'd0;
                        carry      <= (op_r == 2'd1);
                    end
                end
                RUN: begin
                    res   <= {fbit, res[7:1]};
                    opa   <= {1'b0, opa[7:1]};
                    opb   <= {1'b0, opb[7:1]};
                    carry <= (op_r[1] == 1'b0) ? cout : 1'b0;
                    if (cnt == 8'd7) begin
                        phase <= DONE;
                        cnt   <= 8'd8;
                    end else begin
                        cnt <= cnt + 8'd1;
                    end
                end
                DONE: begin
                    if (ack) begin
                        phase      <= IDLE;
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                    end
                end
            endcase
        end
    end

    assert property (phase != 2'd3 || (seen_arm && seen_start));
endmodule

module wfq_sched16 (
    input  wire        clk,
    input  wire        step,
    input  wire        enq_valid,
    input  wire [3:0]  enq_q,
    input  wire        cfg_we,
    input  wire [3:0]  cfg_q,
    input  wire [15:0] cfg_weight,
    output wire        enq_ready,
    output wire        backlogged,
    output wire [3:0]  grant_q,
    output wire        sched_idle
);
    // scheduling state array: 16 queues x 16-bit virtual time / weight / backlog
    reg [255:0] vtime;
    reg [255:0] weight;
    reg [255:0] backlog;
    reg [15:0]  active;
    reg [4:0]   active_cnt;
    reg [15:0]  gvt;
    reg         armed;

    initial begin
        vtime      = 256'd0;
        weight     = {16{16'd1}};
        backlog    = 256'd0;
        active     = 16'd0;
        active_cnt = 5'd0;
        gvt        = 16'd0;
        armed      = 1'b0;
    end

    // weighted fair selection: active queue with smallest virtual time
    reg [3:0]  sel;
    reg [15:0] best_vt;
    reg        found;
    integer j;
    always @(*) begin
        found = 1'b0;
        sel = 4'd0;
        best_vt = 16'd0;
        for (j = 0; j < 16; j = j + 1)
            if (active[j] && (!found || vtime[j*16 +: 16] < best_vt)) begin
                found = 1'b1;
                sel = j[3:0];
                best_vt = vtime[j*16 +: 16];
            end
    end

    wire [15:0] sel_backlog = backlog[sel*16 +: 16];
    wire [15:0] sel_weight  = weight[sel*16 +: 16];
    wire [15:0] enq_backlog = backlog[enq_q*16 +: 16];
    wire [15:0] enq_vt      = vtime[enq_q*16 +: 16];

    wire dispatch = step && (active != 16'd0);
    wire do_enq   = enq_valid && !step && (enq_backlog != 16'hFFFF);

    always @(posedge clk) begin
        if (cfg_we)
            weight[cfg_q*16 +: 16] <= cfg_weight;
        if (dispatch) begin
            armed <= 1'b1;
            gvt <= best_vt;
            vtime[sel*16 +: 16] <= best_vt + sel_weight;
            backlog[sel*16 +: 16] <= sel_backlog - 16'd1;
            if (sel_backlog == 16'd1) begin
                active[sel] <= 1'b0;
                active_cnt <= active_cnt - 5'd1;
            end
        end else if (do_enq) begin
            backlog[enq_q*16 +: 16] <= enq_backlog + 16'd1;
            if (!active[enq_q]) begin
                active[enq_q] <= 1'b1;
                active_cnt <= active_cnt + 5'd1;
                if (enq_vt < gvt)
                    vtime[enq_q*16 +: 16] <= gvt;
            end
        end
    end

    assign enq_ready  = !step;
    assign grant_q    = sel;
    assign sched_idle = (active_cnt == 5'd0);
    assign backlogged = (active != 16'd0);

    // after the first dispatch: idle flag and backlogged flag never both set
    always @(*) if (armed) assert (!(sched_idle && backlogged));
endmodule

module axi_burst_to_lite (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         i_awvalid,
    input  wire [3:0]   i_awid,
    input  wire [31:0]  i_awaddr,
    input  wire [2:0]   i_awlen,
    input  wire         i_wr_en,
    input  wire [2:0]   i_wr_idx,
    input  wire [127:0] i_wr_data,
    input  wire [1:0]   i_lite_bresp,
    input  wire         i_bready,
    output wire         o_awready,
    output wire         o_lite_valid,
    output wire [31:0]  o_lite_awaddr,
    output wire [127:0] o_lite_wdata,
    output wire         o_bvalid,
    output wire [3:0]   o_bid,
    output wire [1:0]   o_bresp
);
    reg         busy = 1'b0;
    reg         bvalid = 1'b0;
    reg         win = 1'b0;
    reg [3:0]   beats_left = 4'd0;
    reg [3:0]   deadline = 4'd0;
    reg [31:0]  addr = 32'd0;
    reg [3:0]   id = 4'd0;
    reg [1:0]   resp_acc = 2'd0;
    reg [2:0]   bidx = 3'd0;
    reg [127:0] wbuf [0:7];
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            wbuf[i] = 128'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            bvalid <= 1'b0;
            win <= 1'b0;
            beats_left <= 4'd0;
            deadline <= 4'd0;
            addr <= 32'd0;
            id <= 4'd0;
            resp_acc <= 2'd0;
            bidx <= 3'd0;
        end else if (i_ce) begin
            if (!busy && !bvalid && i_awvalid) begin
                busy <= 1'b1;
                win <= 1'b1;
                id <= i_awid;
                addr <= i_awaddr;
                beats_left <= {1'b0, i_awlen} + 4'd1;
                deadline <= {1'b0, i_awlen} + 4'd1;
                resp_acc <= 2'd0;
                bidx <= 3'd0;
            end else if (busy) begin
                beats_left <= beats_left - 4'd1;
                deadline <= deadline - 4'd1;
                addr <= addr + 32'd16;
                bidx <= bidx + 3'd1;
                if (i_lite_bresp > resp_acc)
                    resp_acc <= i_lite_bresp;
                if (beats_left == 4'd1) begin
                    busy <= 1'b0;
                    bvalid <= 1'b1;
                end
            end else if (bvalid && i_bready) begin
                bvalid <= 1'b0;
                win <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (!rst && i_ce && i_wr_en)
            wbuf[i_wr_idx] <= i_wr_data;

    assign o_awready     = !busy && !bvalid;
    assign o_lite_valid  = busy;
    assign o_lite_awaddr = addr;
    assign o_lite_wdata  = wbuf[bidx];
    assign o_bvalid      = bvalid;
    assign o_bid         = id;
    assign o_bresp       = resp_acc;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(win))
            assert ($past(beats_left) == 4'd0 || $past(deadline) != 4'd0);
endmodule

module qspi_xip_ctrl (
    input  wire        clk,
    input  wire        ce,
    input  wire        req,
    input  wire [23:0] addr,
    input  wire        cfg_we,
    input  wire [7:0]  cfg_wdata,
    input  wire [3:0]  io_in,
    output wire [3:0]  io_out,
    output wire        cs_n,
    output reg         busy,
    output reg         pf_valid,
    output reg  [31:0] pf_data
);
    reg        cs_active  = 1'b0;
    reg [31:0] cnt        = 32'd0;
    reg [31:0] nib        = 32'd0;
    reg [31:0] sh_out     = 32'd0;
    reg [7:0]  cfg_opcode = 8'hEB;
    reg        armed      = 1'b0;

    initial busy     = 1'b0;
    initial pf_valid = 1'b0;
    initial pf_data  = 32'd0;

    assign cs_n   = !cs_active;
    assign io_out = sh_out[31:28];

    always @(posedge clk) begin
        if (ce) begin
            if (!busy) begin
                if (cfg_we)
                    cfg_opcode <= cfg_wdata;
                if (req) begin
                    armed     <= 1'b1;
                    busy      <= 1'b1;
                    cs_active <= 1'b1;
                    cnt       <= 32'd20;
                    nib       <= 32'd0;
                    pf_valid  <= 1'b0;
                    sh_out    <= {cfg_opcode, addr};
                end
            end else begin
                cnt    <= cnt - 32'd1;
                sh_out <= {sh_out[27:0], 4'h0};
                if (cnt <= 32'd8) begin
                    pf_data <= {pf_data[27:0], io_in};
                    if (nib == 32'd7) begin
                        pf_valid  <= 1'b1;
                        cs_active <= 1'b0;
                        nib       <= 32'd0;
                    end else begin
                        nib <= nib + 32'd1;
                    end
                end
                if (cnt == 32'd1)
                    busy <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (armed) assert (!(busy && pf_valid));

    always @(posedge clk)
        if (armed) assert (!(cs_active && !busy));
endmodule

module pretrig_capture (
    input  wire        clk,
    input  wire        ce,
    input  wire        rearm,
    input  wire        trig,
    input  wire [63:0] sample,
    input  wire [5:0]  rd_idx,
    output wire [63:0] rd_data,
    output wire        is_frozen,
    output wire [63:0] captured
);
    localparam [63:0] DEPTH = 64'd48;
    reg [63:0] chain [0:47];
    reg [47:0] valid;
    reg [63:0] count;
    reg        frozen;
    reg        pv;
    integer i;

    initial begin
        for (i = 0; i < 48; i = i + 1) chain[i] = 64'd0;
        valid  = 48'd0;
        count  = 64'd0;
        frozen = 1'b0;
        pv     = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rearm) begin
            frozen <= 1'b0;
            count  <= 64'd0;
            valid  <= 48'd0;
        end else if (ce && !frozen) begin
            if (trig && count == DEPTH) begin
                frozen <= 1'b1;
            end else begin
                chain[0] <= sample;
                for (i = 1; i < 48; i = i + 1) chain[i] <= chain[i-1];
                valid <= {valid[46:0], 1'b1};
                if (count != DEPTH) count <= count + 64'd1;
            end
        end
    end

    assign rd_data   = (rd_idx < 6'd48) ? chain[rd_idx] : 64'd0;
    assign is_frozen = frozen;
    assign captured  = count;

    always @(posedge clk)
        if (pv && $rose(frozen))
            assert (valid == 48'hFFFFFFFFFFFF);
endmodule

module wormhole_route_unit #(
    parameter [63:0] MY_X = 64'd4,
    parameter [63:0] MY_Y = 64'd2
) (
    input  wire        clk,
    input  wire        in_valid,
    input  wire [1:0]  flit_type,
    input  wire [3:0]  in_ch,
    input  wire [63:0] dest_x,
    input  wire [63:0] dest_y,
    output reg  [2:0]  out_port,
    output wire        out_fire
);
    localparam [1:0] FT_BODY = 2'b00;
    localparam [1:0] FT_HEAD = 2'b01;
    localparam [1:0] FT_TAIL = 2'b10;

    localparam [2:0] P_LOCAL = 3'd0;
    localparam [2:0] P_EAST  = 3'd1;
    localparam [2:0] P_WEST  = 3'd2;
    localparam [2:0] P_NORTH = 3'd3;
    localparam [2:0] P_SOUTH = 3'd4;

    reg [15:0] route_valid;
    reg [47:0] route_port;
    reg [63:0] head_cnt;
    reg [63:0] body_cnt;
    reg        head_seen;
    reg        armed;

    initial begin
        route_valid = 16'd0;
        route_port  = 48'd0;
        head_cnt    = 64'd0;
        body_cnt    = 64'd0;
        head_seen   = 1'b0;
        armed       = 1'b1;
        out_port    = 3'd0;
    end

    wire ch_busy = route_valid[in_ch];
    wire do_head = in_valid && (flit_type == FT_HEAD) && !ch_busy;
    wire do_body = in_valid && (flit_type == FT_BODY) && ch_busy;
    wire do_tail = in_valid && (flit_type == FT_TAIL) && ch_busy;

    assign out_fire = do_head || do_body || do_tail;

    reg [2:0] calc_port;
    always @(*) begin
        if (dest_x > MY_X)      calc_port = P_EAST;
        else if (dest_x < MY_X) calc_port = P_WEST;
        else if (dest_y > MY_Y) calc_port = P_NORTH;
        else if (dest_y < MY_Y) calc_port = P_SOUTH;
        else                    calc_port = P_LOCAL;
    end

    wire [2:0] stored_port = route_port[in_ch*3 +: 3];

    always @(posedge clk) begin
        if (do_head) begin
            route_valid[in_ch]         <= 1'b1;
            route_port[in_ch*3 +: 3]   <= calc_port;
            head_cnt                   <= head_cnt + 64'd1;
            head_seen                  <= 1'b1;
            out_port                   <= calc_port;
        end
        if (do_body) begin
            body_cnt <= body_cnt + 64'd1;
            out_port <= stored_port;
        end
        if (do_tail) begin
            route_valid[in_ch] <= 1'b0;
            armed              <= 1'b0;
            out_port           <= stored_port;
        end
    end

    always @(*) assert (!armed || (body_cnt == 64'd0) || head_seen);
endmodule

module pwm_fault_trip (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       fault_in,
    input  wire       cfg_we,
    input  wire [3:0] cfg_hi,
    input  wire [3:0] cfg_lo,
    input  wire       clr_req,
    input  wire       duty_we,
    input  wire [7:0] duty_in,
    output reg  [3:0] out_hi,
    output reg  [3:0] out_lo
);
    reg [7:0] cnt;
    reg [7:0] duty;
    reg       fault_lat;
    reg [3:0] safe_hi;
    reg [3:0] safe_lo;
    reg       clr_arm;
    reg       no_clear_yet;

    initial cnt = 8'd0;
    initial duty = 8'd128;
    initial fault_lat = 1'b0;
    initial safe_hi = 4'b0000;
    initial safe_lo = 4'b1111;
    initial clr_arm = 1'b0;
    initial no_clear_yet = 1'b1;
    initial out_hi = 4'b0000;
    initial out_lo = 4'b1111;

    wire pwm_on = (cnt < duty);

    always @(posedge clk) begin
        if (rst) begin
            cnt       <= 8'd0;
            duty      <= 8'd128;
            fault_lat <= 1'b0;
            safe_hi   <= 4'b0000;
            safe_lo   <= 4'b1111;
            clr_arm   <= 1'b0;
            out_hi    <= 4'b0000;
            out_lo    <= 4'b1111;
        end else if (ce) begin
            cnt <= cnt + 8'd1;
            if (duty_we)
                duty <= duty_in;
            if (cfg_we) begin
                safe_hi <= cfg_hi;
                safe_lo <= cfg_lo & ~cfg_hi;
            end
            if (clr_req)
                clr_arm <= 1'b1;
            if (fault_in)
                fault_lat <= 1'b1;
            else if (clr_arm && fault_lat) begin
                fault_lat    <= 1'b0;
                clr_arm      <= 1'b0;
                no_clear_yet <= 1'b0;
            end
            if (fault_in || fault_lat) begin
                out_hi <= safe_hi;
                out_lo <= safe_lo;
            end else begin
                out_hi <= {4{pwm_on}};
                out_lo <= {4{~pwm_on}};
            end
        end
    end

    always @(posedge clk)
        if (no_clear_yet)
            assert ((out_hi & out_lo) == 4'd0);
endmodule

module tag_array_precedence (
    input wire clk,
    input wire ce,
    input wire fill,
    input wire [6:0] fill_set,
    input wire [7:0] fill_tag,
    input wire flush,
    input wire lookup,
    input wire [6:0] lookup_set,
    input wire [7:0] lookup_tag,
    output wire hit
);
    localparam [6:0] NSETS = 7'd96;

    reg [7:0] tag_mem [0:95];
    reg [95:0] valid;
    reg filled_any;
    reg [7:0] fill_cnt;
    reg hit_q;
    reg armed;

    integer i;
    initial begin
        for (i = 0; i < 96; i = i + 1) tag_mem[i] = 8'd0;
        valid = 96'd0;
        filled_any = 1'b0;
        fill_cnt = 8'd0;
        hit_q = 1'b0;
        armed = 1'b0;
    end

    wire fill_ok = fill && (fill_set < NSETS);
    wire look_ok = lookup && (lookup_set < NSETS);
    wire raw_hit = look_ok && valid[lookup_set] && (tag_mem[lookup_set] == lookup_tag);

    always @(posedge clk) begin
        if (ce && !flush && fill_ok)
            tag_mem[fill_set] <= fill_tag;
    end

    always @(posedge clk) begin
        if (ce) begin
            hit_q <= !flush && raw_hit;
            if (flush) begin
                valid <= 96'd0;
                filled_any <= 1'b0;
                fill_cnt <= 8'd0;
            end else if (fill_ok) begin
                valid[fill_set] <= 1'b1;
                filled_any <= 1'b1;
                if (fill_cnt != 8'hFF) fill_cnt <= fill_cnt + 8'd1;
                armed <= 1'b1;
            end
        end
    end

    assign hit = hit_q;

    always @(posedge clk)
        if (armed && hit_q)
            assert (filled_any);

    always @(posedge clk)
        if (armed && hit_q)
            assert (fill_cnt != 8'd0);
endmodule

module ecc_dbg_mem (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        cmd_valid,
    input  wire        cmd_wr,
    input  wire [5:0]  cmd_addr,
    input  wire [31:0] cmd_wdata,
    input  wire [38:0] cmd_inject,
    input  wire        rsp_ack,
    output wire        rsp_valid,
    output reg  [31:0] rsp_rdata,
    output reg  [6:0]  rsp_syndrome,
    output reg         rsp_sbe,
    output reg         rsp_dbe
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, START = 2'd2, DONE = 2'd3;

    function [38:0] secded_enc(input [31:0] d);
        integer i, j, p, k;
        reg [38:0] c;
        reg par;
        begin
            c = 39'd0;
            j = 0;
            for (i = 1; i < 39; i = i + 1) begin
                if ((i & (i - 1)) != 0) begin
                    c[i] = d[j];
                    j = j + 1;
                end
            end
            for (p = 0; p < 6; p = p + 1) begin
                par = 1'b0;
                for (k = 1; k < 39; k = k + 1)
                    if (((k >> p) & 1) == 1) par = par ^ c[k];
                c[1 << p] = par;
            end
            c[0] = ^c[38:1];
            secded_enc = c;
        end
    endfunction

    function [5:0] secded_syn(input [38:0] c);
        integer p, k;
        reg [5:0] s;
        begin
            s = 6'd0;
            for (p = 0; p < 6; p = p + 1)
                for (k = 1; k < 39; k = k + 1)
                    if (((k >> p) & 1) == 1) s[p] = s[p] ^ c[k];
            secded_syn = s;
        end
    endfunction

    function [31:0] secded_data(input [38:0] c);
        integer i, j;
        reg [31:0] d;
        begin
            d = 32'd0;
            j = 0;
            for (i = 1; i < 39; i = i + 1) begin
                if ((i & (i - 1)) != 0) begin
                    d[j] = c[i];
                    j = j + 1;
                end
            end
            secded_data = d;
        end
    endfunction

    reg [1:0]  phase      = IDLE;
    reg        arm_seen   = 1'b0;
    reg        start_seen = 1'b0;
    reg        q_seen     = 1'b0;
    reg        wr_q       = 1'b0;
    reg [5:0]  addr_q     = 6'd0;
    reg [31:0] wdata_q    = 32'd0;
    reg [38:0] inj_q      = 39'd0;
    reg [38:0] rd_cw_q    = 39'd0;
    reg [38:0] mem [0:63];

    integer n;
    initial begin
        for (n = 0; n < 64; n = n + 1) mem[n] = 39'd0;
        rsp_rdata    = 32'd0;
        rsp_syndrome = 7'd0;
        rsp_sbe      = 1'b0;
        rsp_dbe      = 1'b0;
    end

    wire [38:0] wr_cw = secded_enc(wdata_q) ^ inj_q;
    wire [5:0]  syn   = secded_syn(rd_cw_q);
    wire        ovp   = ^rd_cw_q;
    wire        sbe   = ovp;
    wire        dbe   = !ovp && (syn != 6'd0);
    wire [38:0] fixed = sbe ? (rd_cw_q ^ (39'd1 << syn)) : rd_cw_q;

    assign rsp_valid = (phase == DONE);

    always @(posedge clk) begin
        if (rst) begin
            phase      <= IDLE;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
        end else if (ce) begin
            case (phase)
                IDLE: if (cmd_valid) begin
                    phase      <= ARMED;
                    arm_seen   <= 1'b1;
                    start_seen <= 1'b0;
                    wr_q       <= cmd_wr;
                    addr_q     <= cmd_addr;
                    wdata_q    <= cmd_wdata;
                    inj_q      <= cmd_inject;
                    if (cmd_wr) q_seen <= 1'b1;
                end
                ARMED: begin
                    if (wr_q) mem[addr_q] <= wr_cw;
                    rd_cw_q    <= wr_q ? wr_cw : mem[addr_q];
                    start_seen <= 1'b1;
                    phase      <= START;
                end
                START: begin
                    rsp_rdata    <= secded_data(fixed);
                    rsp_syndrome <= {ovp, syn};
                    rsp_sbe      <= sbe;
                    rsp_dbe      <= dbe;
                    phase        <= DONE;
                end
                DONE: if (rsp_ack) begin
                    phase      <= IDLE;
                    arm_seen   <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
        end
    end

    assert property (!q_seen || !rsp_valid || (arm_seen && start_seen));
endmodule

module mpop_fifo (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire push,
    input wire [31:0] din,
    input wire [2:0] npop_req,
    input wire open,
    input wire close,
    output reg [31:0] dout0,
    output reg [31:0] dout1,
    output reg [31:0] dout2,
    output reg [31:0] dout3,
    output wire [2:0] npop_o,
    output wire [31:0] count_o
);
    reg [31:0] bank0 [0:3];
    reg [31:0] bank1 [0:3];
    reg [31:0] bank2 [0:3];
    reg [31:0] bank3 [0:3];
    integer k;
    initial begin
        for (k = 0; k < 4; k = k + 1) begin
            bank0[k] = 32'd0; bank1[k] = 32'd0; bank2[k] = 32'd0; bank3[k] = 32'd0;
        end
    end

    reg [4:0] wptr = 5'd0;
    reg [4:0] rptr = 5'd0;
    reg [31:0] count = 32'd0;
    reg win = 1'b0;
    reg push_ack = 1'b0;

    wire [4:0] occ = wptr - rptr;
    wire full = (occ >= 5'd16);
    wire do_push = push && !full;
    wire [2:0] req = (npop_req > 3'd4) ? 3'd4 : npop_req;
    wire [2:0] npop = ({2'b00, req} > occ) ? occ[2:0] : req;
    assign npop_o = npop;
    assign count_o = count;

    wire [3:0] i0 = rptr[3:0];
    wire [3:0] i1 = rptr[3:0] + 4'd1;
    wire [3:0] i2 = rptr[3:0] + 4'd2;
    wire [3:0] i3 = rptr[3:0] + 4'd3;

    always @(*) begin
        case (i0[1:0])
            2'd0: dout0 = bank0[i0[3:2]];
            2'd1: dout0 = bank1[i0[3:2]];
            2'd2: dout0 = bank2[i0[3:2]];
            default: dout0 = bank3[i0[3:2]];
        endcase
        case (i1[1:0])
            2'd0: dout1 = bank0[i1[3:2]];
            2'd1: dout1 = bank1[i1[3:2]];
            2'd2: dout1 = bank2[i1[3:2]];
            default: dout1 = bank3[i1[3:2]];
        endcase
        case (i2[1:0])
            2'd0: dout2 = bank0[i2[3:2]];
            2'd1: dout2 = bank1[i2[3:2]];
            2'd2: dout2 = bank2[i2[3:2]];
            default: dout2 = bank3[i2[3:2]];
        endcase
        case (i3[1:0])
            2'd0: dout3 = bank0[i3[3:2]];
            2'd1: dout3 = bank1[i3[3:2]];
            2'd2: dout3 = bank2[i3[3:2]];
            default: dout3 = bank3[i3[3:2]];
        endcase
    end

    always @(posedge clk) begin
        if (ce && do_push) begin
            case (wptr[1:0])
                2'd0: bank0[wptr[3:2]] <= din;
                2'd1: bank1[wptr[3:2]] <= din;
                2'd2: bank2[wptr[3:2]] <= din;
                default: bank3[wptr[3:2]] <= din;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 5'd0;
            rptr <= 5'd0;
            count <= 32'd0;
            win <= 1'b0;
            push_ack <= 1'b0;
        end else if (ce) begin
            wptr <= wptr + {4'd0, do_push};
            rptr <= rptr + {2'd0, npop};
            count <= count + {31'd0, do_push} - {29'd0, npop};
            push_ack <= do_push;
            if (open) win <= 1'b1;
            else if (close) win <= 1'b0;
        end
    end

    always @(posedge clk)
        if (win && $rose(push_ack))
            assert (count <= 32'd16);
endmodule

module gshare_streak (
    input  wire        clk,
    input  wire        upd,
    input  wire        taken,
    input  wire [63:0] upd_pc,
    input  wire [63:0] fetch_pc,
    input  wire        restore,
    input  wire [63:0] restore_ghr,
    output wire        pred_taken
);
    reg [63:0] ghr      = 64'd0;
    reg [63:0] streak_t = 64'd0;
    reg [63:0] streak_n = 64'd0;
    reg        armed    = 1'b1;
    reg [1:0]  pht [0:255];
    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1)
            pht[i] = 2'b01;
    end

    wire [7:0] fidx = fetch_pc[9:2] ^ ghr[7:0];
    wire [7:0] uidx = upd_pc[9:2] ^ ghr[7:0];
    assign pred_taken = pht[fidx][1];

    wire [63:0] t_inc = (streak_t == 64'hFFFF_FFFF_FFFF_FFFF) ? streak_t : streak_t + 64'd1;
    wire [63:0] n_inc = (streak_n == 64'hFFFF_FFFF_FFFF_FFFF) ? streak_n : streak_n + 64'd1;

    always @(posedge clk) begin
        if (restore) begin
            ghr   <= restore_ghr;
            armed <= 1'b0;
        end else if (upd) begin
            ghr <= {ghr[62:0], taken};
            if (taken) begin
                pht[uidx] <= (pht[uidx] == 2'b11) ? 2'b11 : pht[uidx] + 2'b01;
                if (!ghr[0]) begin
                    streak_t <= 64'd1;
                    streak_n <= 64'd0;
                end else begin
                    streak_t <= t_inc;
                end
            end else begin
                pht[uidx] <= (pht[uidx] == 2'b00) ? 2'b00 : pht[uidx] - 2'b01;
                if (ghr[0]) begin
                    streak_n <= 64'd1;
                    streak_t <= 64'd0;
                end else begin
                    streak_n <= n_inc;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed)
            assert (!($past(streak_t) != 64'd0 && $past(streak_n) != 64'd0));
endmodule

module rst_seq24 (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_cfg_we,
    input  wire [127:0] i_cfg_order,
    input  wire [127:0] i_cfg_delay,
    input  wire         i_start,
    output wire [23:0]  o_dom_rst,
    output wire         o_busy
);
    localparam [4:0] LAST   = 5'd23;
    localparam [9:0] BUDGET = 10'd768;

    // programmed release order (24 x 5-bit domain ids) and per-step delays (24 x 5-bit)
    reg [127:0] cfg_order = 128'd0;
    reg [127:0] cfg_delay = 128'd0;
    reg [4:0]   step_idx  = 5'd0;
    reg [4:0]   dly_cnt   = 5'd0;
    reg [23:0]  dom_rst   = 24'hFFFFFF;
    reg         busy      = 1'b0;
    reg [9:0]   budget    = 10'd0;

    wire [4:0] cur_dom = cfg_order[step_idx*5 +: 5];
    wire [4:0] nxt_dly = cfg_delay[(step_idx + 5'd1)*5 +: 5];

    always @(posedge clk) begin
        if (i_ce) begin
            if (!busy) begin
                if (i_cfg_we) begin
                    cfg_order <= i_cfg_order;
                    cfg_delay <= i_cfg_delay;
                end else if (i_start) begin
                    busy     <= 1'b1;
                    step_idx <= 5'd0;
                    dly_cnt  <= cfg_delay[4:0];
                    budget   <= BUDGET;
                    dom_rst  <= 24'hFFFFFF;
                end
            end else begin
                budget <= budget - 10'd1;
                if (dly_cnt != 5'd0) begin
                    dly_cnt <= dly_cnt - 5'd1;
                end else begin
                    if (cur_dom < 5'd24)
                        dom_rst[cur_dom] <= 1'b0;
                    if (step_idx == LAST) begin
                        busy     <= 1'b0;
                        step_idx <= 5'd0;
                    end else begin
                        step_idx <= step_idx + 5'd1;
                        dly_cnt  <= nxt_dly;
                    end
                end
            end
        end
    end

    assign o_dom_rst = dom_rst;
    assign o_busy    = busy;

    // after start accepted until sequence done: watchdog countdown never expires
    always @(*)
        assert (!busy || budget != 10'd0);
endmodule

module bus_timeout_mon (
    input  wire        clk,
    input  wire        i_clr,
    input  wire        i_ce,
    input  wire        i_arm,
    input  wire [31:0] i_thresh,
    input  wire        i_req,
    input  wire        i_resp,
    output wire        o_err_resp,
    output wire        o_timeout,
    output wire [31:0] o_txn_count
);
    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_ARMED = 2'd1;
    localparam [1:0] P_BUSY  = 2'd2;

    reg [1:0]  phase;
    reg [31:0] thresh;
    reg [31:0] wait_cnt;
    reg [31:0] txn_count;
    reg        to_err;
    reg        seen_arm;
    reg        seen_start;

    initial begin
        phase = P_IDLE;
        thresh = 32'd0;
        wait_cnt = 32'd0;
        txn_count = 32'd0;
        to_err = 1'b0;
        seen_arm = 1'b0;
        seen_start = 1'b0;
    end

    always @(posedge clk) begin
        if (i_clr) begin
            phase <= P_IDLE;
            thresh <= 32'd0;
            wait_cnt <= 32'd0;
            txn_count <= 32'd0;
            to_err <= 1'b0;
            seen_arm <= 1'b0;
            seen_start <= 1'b0;
        end else if (i_ce) begin
            case (phase)
                P_IDLE: begin
                    if (i_arm) begin
                        thresh <= i_thresh;
                        seen_arm <= 1'b1;
                        phase <= P_ARMED;
                    end
                end
                P_ARMED: begin
                    if (i_req) begin
                        seen_start <= 1'b1;
                        wait_cnt <= 32'd0;
                        txn_count <= txn_count + 32'd1;
                        phase <= P_BUSY;
                    end
                end
                P_BUSY: begin
                    if (i_resp) begin
                        wait_cnt <= 32'd0;
                        phase <= P_ARMED;
                    end else if (wait_cnt >= thresh) begin
                        to_err <= 1'b1;
                        wait_cnt <= 32'd0;
                        phase <= P_ARMED;
                    end else begin
                        wait_cnt <= wait_cnt + 32'd1;
                    end
                end
                default: begin
                end
            endcase
        end
    end

    assign o_err_resp  = (phase == P_BUSY) && !i_resp && (wait_cnt >= thresh);
    assign o_timeout   = to_err;
    assign o_txn_count = txn_count;

    assert property (!to_err || (seen_arm && seen_start));
endmodule

module pdm_cic_precedence (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_pdm,
    output wire [31:0] o_pcm
);
    localparam [31:0] DEC = 32'd64;

    reg [31:0] integ1;
    reg [31:0] integ2;
    reg [31:0] dly1;
    reg [31:0] dly2;
    reg [31:0] pcm;
    reg [31:0] phase;
    reg        seen_one;
    reg        armed;

    initial integ1   = 32'd0;
    initial integ2   = 32'd0;
    initial dly1     = 32'd0;
    initial dly2     = 32'd0;
    initial pcm      = 32'd0;
    initial phase    = 32'd0;
    initial seen_one = 1'b0;
    initial armed    = 1'b0;

    wire [31:0] integ1_n = integ1 + {31'd0, i_pdm};
    wire [31:0] integ2_n = integ2 + integ1;
    wire [31:0] comb1    = integ2 - dly1;
    wire [31:0] comb2    = comb1 - dly2;
    wire        tick     = (phase == DEC - 32'd1);

    always @(posedge clk) begin
        if (i_ce) begin
            integ1 <= integ1_n;
            integ2 <= integ2_n;
            if (i_pdm)
                seen_one <= 1'b1;
            if (tick) begin
                phase <= 32'd0;
                dly1  <= integ2;
                dly2  <= comb1;
                pcm   <= comb2;
                armed <= 1'b1;
            end else begin
                phase <= phase + 32'd1;
            end
        end
    end

    assign o_pcm = pcm;

    always @(posedge clk) assert (!armed || pcm == 32'd0 || seen_one);
endmodule

module scan_unload_chain (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        req,
    input  wire [31:0] scan_in,
    input  wire [31:0] func_d,
    output wire [31:0] scan_out,
    output wire        busy_o
);
    // 32-entry scan chain of 32-bit scan flip-flops
    reg [31:0] chain [0:31];
    reg        busy     = 1'b0;
    reg [31:0] shifted  = 32'd0;
    reg [31:0] deadline = 32'd0;
    integer i;
    integer k;
    initial begin
        for (k = 0; k < 32; k = k + 1) chain[k] = 32'd0;
    end

    assign scan_out = chain[31];
    assign busy_o   = busy;

    always @(posedge clk) begin
        if (rst) begin
            busy     <= 1'b0;
            shifted  <= 32'd0;
            deadline <= 32'd0;
        end else if (ce) begin
            if (busy) begin
                // test mode: scan mux selects the previous flop
                for (i = 31; i > 0; i = i - 1)
                    chain[i] <= chain[i-1];
                chain[0] <= scan_in;
                shifted  <= shifted + 32'd1;
                deadline <= deadline - 32'd1;
                if (shifted == 32'd31)
                    busy <= 1'b0;
            end else if (req) begin
                // accept unload request: countdown guarantees completion in 32 shifts
                busy     <= 1'b1;
                shifted  <= 32'd0;
                deadline <= 32'd32;
            end else begin
                // functional mode: scan mux selects functional data
                for (i = 0; i < 32; i = i + 1)
                    chain[i] <= chain[i] ^ func_d;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(busy))
            assert ($past(deadline) != 32'd0);
endmodule

module median_tick_filter (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        in_valid,
    input  wire [15:0] in_px,
    input  wire        sess_open,
    input  wire        sess_close,
    output wire [15:0] med_px,
    output wire        med_valid,
    output wire [15:0] fill_out
);
    // 8-entry sliding window of 16-bit price samples (packed)
    reg [127:0] win   = 128'd0;
    // thermometer occupancy mask: one bit per filled slot
    reg [7:0]   mask  = 8'h00;
    // occupancy counter, saturates at 8
    reg [15:0]  fill  = 16'd0;
    // trading-session window register (scope: open .. close)
    reg         armed = 1'b0;

    // odd-even transposition sorting network over 8 entries
    function [127:0] sort8;
        input [127:0] v;
        integer st, j;
        reg [127:0] t;
        reg [15:0] a, b;
        begin
            t = v;
            for (st = 0; st < 8; st = st + 1) begin
                for (j = (st % 2); j < 7; j = j + 2) begin
                    a = t[16*j +: 16];
                    b = t[16*(j+1) +: 16];
                    if (a > b) begin
                        t[16*j +: 16]     = b;
                        t[16*(j+1) +: 16] = a;
                    end
                end
            end
            sort8 = t;
        end
    endfunction

    wire [127:0] sorted = sort8(win);
    assign med_px    = sorted[16*3 +: 16];
    assign med_valid = mask[7];
    assign fill_out  = fill;

    always @(posedge clk) begin
        if (rst) begin
            win   <= 128'd0;
            mask  <= 8'h00;
            fill  <= 16'd0;
            armed <= 1'b0;
        end else if (ce) begin
            if (sess_close) begin
                armed <= 1'b0;
                mask  <= 8'h00;
                fill  <= 16'd0;
            end else begin
                if (sess_open)
                    armed <= 1'b1;
                if (in_valid) begin
                    win  <= {win[111:0], in_px};
                    mask <= {mask[6:0], 1'b1};
                    if (!mask[7])
                        fill <= fill + 16'd1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // inside a session, whenever the clock-enable burst ends, occupancy is at most 8
    always @(posedge clk)
        if (pv && armed && $fell(ce))
            assert (fill <= 16'd8);
endmodule

module aes_round_seq64 (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire arm,
    input wire start,
    input wire ack,
    input wire [63:0] pt,
    input wire [63:0] key_in,
    output wire done,
    output wire [63:0] ct
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3;
    localparam [63:0] NR = 64'd10;

    reg [1:0] phase;
    reg arm_seen, start_seen;
    reg [63:0] rnd;
    reg [63:0] st;
    reg [63:0] rk;
    initial begin
        phase = IDLE; arm_seen = 1'b0; start_seen = 1'b0;
        rnd = 64'd0; st = 64'd0; rk = 64'd0;
    end

    function [3:0] sbox4(input [3:0] x);
        case (x)
            4'h0: sbox4 = 4'hC; 4'h1: sbox4 = 4'h5; 4'h2: sbox4 = 4'h6; 4'h3: sbox4 = 4'hB;
            4'h4: sbox4 = 4'h9; 4'h5: sbox4 = 4'h0; 4'h6: sbox4 = 4'hA; 4'h7: sbox4 = 4'hD;
            4'h8: sbox4 = 4'h3; 4'h9: sbox4 = 4'hE; 4'hA: sbox4 = 4'hF; 4'hB: sbox4 = 4'h8;
            4'hC: sbox4 = 4'h4; 4'hD: sbox4 = 4'h7; 4'hE: sbox4 = 4'h1; default: sbox4 = 4'h2;
        endcase
    endfunction

    function [63:0] sub64(input [63:0] x);
        integer i;
        begin
            sub64 = 64'd0;
            for (i = 0; i < 16; i = i + 1)
                sub64[i*4 +: 4] = sbox4(x[i*4 +: 4]);
        end
    endfunction

    function [63:0] shift64(input [63:0] x);
        integer r, c;
        begin
            shift64 = 64'd0;
            for (c = 0; c < 4; c = c + 1)
                for (r = 0; r < 4; r = r + 1)
                    shift64[(4*c+r)*4 +: 4] = x[(4*((c+r)%4)+r)*4 +: 4];
        end
    endfunction

    function [63:0] mix64(input [63:0] x);
        integer c;
        reg [15:0] col;
        begin
            mix64 = 64'd0;
            for (c = 0; c < 4; c = c + 1) begin
                col = x[c*16 +: 16];
                mix64[c*16 +: 16] = col ^ {col[11:0], col[15:12]} ^ {col[7:0], col[15:8]};
            end
        end
    endfunction

    wire last_round = (rnd == NR - 64'd1);
    wire [63:0] after_shift = shift64(sub64(st));
    wire [63:0] round_out = (last_round ? after_shift : mix64(after_shift)) ^ rk;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE; arm_seen <= 1'b0; start_seen <= 1'b0;
            rnd <= 64'd0; st <= 64'd0; rk <= 64'd0;
        end else if (ce) begin
            case (phase)
                IDLE: if (arm) begin
                    phase <= ARMED; arm_seen <= 1'b1; start_seen <= 1'b0;
                    st <= pt ^ key_in; rk <= key_in;
                end
                ARMED: if (start) begin
                    phase <= RUN; start_seen <= 1'b1; rnd <= 64'd0;
                end
                RUN: begin
                    st <= round_out;
                    rk <= {rk[62:0], rk[63]} ^ rnd;
                    rnd <= rnd + 64'd1;
                    if (last_round) phase <= DONE;
                end
                default: if (ack) begin
                    phase <= IDLE; arm_seen <= 1'b0; start_seen <= 1'b0;
                end
            endcase
        end
    end

    assign done = (phase == DONE);
    assign ct = st;

    always @(posedge clk)
        if (phase == DONE)
            assert (arm_seen && start_seen);
endmodule

module stream_realigner (
    input wire clk,
    input wire rst,
    input wire in_valid,
    input wire sop,
    input wire eop,
    input wire [2:0] sop_off,
    input wire [63:0] in_data,
    output reg [63:0] out_data,
    output reg [63:0] out_tail,
    output reg out_valid,
    output reg tail_valid
);
    reg [2:0]  off;
    reg [63:0] residue;
    reg        win;
    reg [63:0] in_cnt;
    reg [63:0] out_cnt;

    initial begin
        off = 3'd0; residue = 64'd0; win = 1'b0;
        in_cnt = 64'd0; out_cnt = 64'd0;
        out_data = 64'd0; out_tail = 64'd0;
        out_valid = 1'b0; tail_valid = 1'b0;
    end

    wire [5:0]  sh     = {off, 3'b000};
    wire [5:0]  sop_sh = {sop_off, 3'b000};
    wire [6:0]  lsh    = 7'd64 - {1'b0, sh};
    wire [63:0] merged = residue | (in_data << lsh);

    always @(posedge clk) begin
        if (rst) begin
            off <= 3'd0; residue <= 64'd0; win <= 1'b0;
            in_cnt <= 64'd0; out_cnt <= 64'd0;
            out_data <= 64'd0; out_tail <= 64'd0;
            out_valid <= 1'b0; tail_valid <= 1'b0;
        end else if (in_valid) begin
            out_valid  <= 1'b0;
            tail_valid <= 1'b0;
            if (!win) begin
                if (sop) begin
                    off     <= sop_off;
                    residue <= in_data >> sop_sh;
                    win     <= 1'b1;
                    in_cnt  <= in_cnt + 64'd1;
                end
            end else begin
                out_data  <= merged;
                out_valid <= 1'b1;
                in_cnt    <= in_cnt + 64'd1;
                if (eop) begin
                    out_tail   <= in_data >> sh;
                    tail_valid <= 1'b1;
                    out_cnt    <= out_cnt + 64'd2;
                    residue    <= 64'd0;
                    win        <= 1'b0;
                end else begin
                    residue <= in_data >> sh;
                    out_cnt <= out_cnt + 64'd1;
                end
            end
        end
    end

    assert property (!win || (in_cnt != out_cnt));
endmodule

module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
    output reg  [6:0]  rsp_rule
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
    wire last = (idx == 7'd127);

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
                if (req) begin
                    busy  <= 1'b1;
                    idx   <= 7'd0;
                    timer <= 8'd128;
                    q_key <= req_key;
                    q_len <= {48'd0, req_len};
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
endmodule

module fp_align_shifter (
    input  wire        clk,
    input  wire        rst,
    input  wire        load,
    input  wire        i_ce,
    input  wire [63:0] a_exp,
    input  wire [63:0] a_sig,
    input  wire [63:0] b_exp,
    input  wire [63:0] b_sig,
    output reg  [63:0] sig,
    output reg  [63:0] exp_out,
    output reg  [63:0] cnt,
    output reg         g,
    output reg         r,
    output reg         s,
    output wire        busy
);
    // shadow: some nonzero bit has been shifted out of the significand
    reg lost  = 1'b0;
    // sticky scope register: set at the first accepted alignment request
    reg armed = 1'b0;

    initial sig     = 64'd0;
    initial exp_out = 64'd0;
    initial cnt     = 64'd0;
    initial g       = 1'b0;
    initial r       = 1'b0;
    initial s       = 1'b0;

    assign busy = (cnt != 64'd0);

    always @(posedge clk) begin
        if (rst) begin
            sig     <= 64'd0;
            exp_out <= 64'd0;
            cnt     <= 64'd0;
            g       <= 1'b0;
            r       <= 1'b0;
            s       <= 1'b0;
            lost    <= 1'b0;
        end else if (load) begin
            armed <= 1'b1;
            if (a_exp >= b_exp) begin
                exp_out <= a_exp;
                sig     <= b_sig;
                cnt     <= a_exp - b_exp;
            end else begin
                exp_out <= b_exp;
                sig     <= a_sig;
                cnt     <= b_exp - a_exp;
            end
            g    <= 1'b0;
            r    <= 1'b0;
            s    <= 1'b0;
            lost <= 1'b0;
        end else if (i_ce && cnt != 64'd0) begin
            sig  <= {1'b0, sig[63:1]};
            g    <= sig[0];
            r    <= g;
            s    <= s | r;
            lost <= lost | sig[0];
            cnt  <= cnt - 64'd1;
        end
    end

    // precedence, after first load: sticky set now => a nonzero bit was shifted out earlier
    always @(*) assert (!armed || !s || lost);
endmodule

module dadda4x4 (
    input  wire [3:0] a,
    input  wire [3:0] b,
    output wire [7:0] p
);
    // partial products pij = a[i] & b[j], weight i+j
    wire p00 = a[0] & b[0];
    wire p01 = a[0] & b[1];
    wire p02 = a[0] & b[2];
    wire p03 = a[0] & b[3];
    wire p10 = a[1] & b[0];
    wire p11 = a[1] & b[1];
    wire p12 = a[1] & b[2];
    wire p13 = a[1] & b[3];
    wire p20 = a[2] & b[0];
    wire p21 = a[2] & b[1];
    wire p22 = a[2] & b[2];
    wire p23 = a[2] & b[3];
    wire p30 = a[3] & b[0];
    wire p31 = a[3] & b[1];
    wire p32 = a[3] & b[2];
    wire p33 = a[3] & b[3];
    // Dadda stage 1: reduce max column height 4 -> 3 (two half adders)
    wire s1 = p03 ^ p12;
    wire c1 = p03 & p12;
    wire s2 = p13 ^ p22;
    wire c2 = p13 & p22;
    // Dadda stage 2: reduce height 3 -> 2 (one half adder, three full adders)
    wire s3 = p02 ^ p11;
    wire c3 = p02 & p11;
    wire s4 = s1 ^ p21 ^ p30;
    wire c4 = (s1 & p21) | (s1 & p30) | (p21 & p30);
    wire s5 = s2 ^ p31 ^ c1;
    wire c5 = (s2 & p31) | (s2 & c1) | (p31 & c1);
    wire s6 = p23 ^ p32 ^ c2;
    wire c6 = (p23 & p32) | (p23 & c2) | (p32 & c2);
    // final carry-propagate adder over columns 1..6
    wire [5:0] row_x = {p33, s6, s5, s4, s3, p01};
    wire [5:0] row_y = {c6, c5, c4, c3, p20, p10};
    wire [6:0] cpa = {1'b0, row_x} + {1'b0, row_y};
    assign p = {cpa, p00};
endmodule

module dadda_simd_mul (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_load,
    input  wire         i_flush,
    input  wire [127:0] i_data,
    output wire [127:0] o_prod
);
    reg [127:0] op_r;
    reg [127:0] prod_r;
    reg         v1;
    reg [1:0]   op_gen;
    reg [1:0]   p_gen;
    reg         armed;
    reg         pv;
    initial op_r   = 128'h0;
    initial prod_r = 128'h0;
    initial v1     = 1'b0;
    initial op_gen = 2'd0;
    initial p_gen  = 2'd0;
    initial armed  = 1'b0;
    initial pv     = 1'b0;

    // 16 lanes, each lane packs {a[3:0], b[3:0]} in 8 bits of the operand word
    wire [127:0] tree_p;
    genvar k;
    generate
        for (k = 0; k < 16; k = k + 1) begin : lane
            dadda4x4 u_mul (
                .a(op_r[8*k+7:8*k+4]),
                .b(op_r[8*k+3:8*k]),
                .p(tree_p[8*k+7:8*k])
            );
        end
    endgenerate

    always @(posedge clk) begin
        if (i_ce) begin
            if (v1) begin
                prod_r <= tree_p;
                p_gen  <= op_gen;
            end
            if (i_load) begin
                op_r   <= i_data;
                op_gen <= op_gen + 2'd1;
                v1     <= 1'b1;
            end else if (v1) begin
                v1 <= 1'b0;
            end
            if (i_flush)
                armed <= 1'b0;
            else if (i_load)
                armed <= 1'b1;
        end
    end

    assign o_prod = prod_r;

    always @(posedge clk) pv <= 1'b1;

    // after first load until flush: never (product tag unchanged AND product changed)
    always @(posedge clk)
        if (pv && armed && $stable(p_gen))
            assert ($stable(prod_r));
endmodule

module tap_delay_chain (
    input  wire        clk,
    input  wire        ce,
    input  wire        arm,
    input  wire        start,
    input  wire [31:0] cfg_tap,
    input  wire [31:0] din,
    output wire [31:0] dout,
    output wire        done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3;

    // 12-stage x 32-bit data chain plus a parallel marker chain
    reg [383:0] chain;
    reg [11:0]  mark;
    reg [31:0]  tap;
    reg [1:0]   phase;
    reg         started;
    reg         q_seen;

    initial chain   = 384'd0;
    initial mark    = 12'h000;
    initial tap     = 32'd0;
    initial phase   = IDLE;
    initial started = 1'b0;
    initial q_seen  = 1'b0;

    wire tap_ok   = (tap < 32'd12);
    wire tap_mark = tap_ok ? mark[tap[3:0]] : 1'b0;
    assign dout   = tap_ok ? chain[{tap[3:0], 5'b00000} +: 32] : 32'd0;
    assign done   = (phase == DONE);

    wire go_arm    = ce && (phase == IDLE) && arm;
    wire go_finish = ce && ((phase == ARMED) || (phase == RUN)) && tap_mark;
    wire go_start  = ce && (phase == ARMED) && start && !tap_mark;

    always @(posedge clk) begin
        if (ce) begin
            chain <= {chain[351:0], din};
            mark  <= {mark[10:0], go_start};
        end
        if (go_arm) begin
            phase  <= ARMED;
            q_seen <= 1'b1;
            tap    <= (cfg_tap < 32'd12) ? cfg_tap : 32'd11;
        end else if (go_finish) begin
            phase <= DONE;
        end else if (go_start) begin
            phase   <= RUN;
            started <= 1'b1;
        end
    end

    // after the first arm: finish is never observed unless start happened
    always @(posedge clk)
        if (q_seen) assert (phase != DONE || started);
endmodule

module mesi_pair (
    input wire clk,
    input wire rst,
    input wire step,
    input wire who,
    input wire wr,
    output reg [1:0] st_a,
    output reg [1:0] st_b,
    output reg bus_req,
    output reg [31:0] bus_cnt,
    output reg [31:0] wb_cnt
);
    localparam [1:0] ST_I = 2'b00;
    localparam [1:0] ST_S = 2'b01;
    localparam [1:0] ST_E = 2'b10;
    localparam [1:0] ST_M = 2'b11;

    initial st_a = ST_I;
    initial st_b = ST_I;
    initial bus_req = 1'b0;
    initial bus_cnt = 32'd0;
    initial wb_cnt = 32'd0;

    always @(posedge clk) begin
        if (rst) begin
            st_a <= ST_I;
            st_b <= ST_I;
            bus_req <= 1'b0;
            bus_cnt <= 32'd0;
            wb_cnt <= 32'd0;
        end else if (step) begin
            bus_req <= 1'b0;
            if (!who) begin
                if (wr) begin
                    if (st_a == ST_E) begin
                        st_a <= ST_M;
                    end else if (st_a != ST_M) begin
                        st_a <= ST_M;
                        if (st_b == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_b <= ST_I;
                        bus_req <= 1'b1;
                        bus_cnt <= bus_cnt + 32'd1;
                    end
                end else if (st_a == ST_I) begin
                    bus_req <= 1'b1;
                    bus_cnt <= bus_cnt + 32'd1;
                    if (st_b == ST_I) begin
                        st_a <= ST_E;
                    end else begin
                        st_a <= ST_S;
                        if (st_b == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_b <= ST_S;
                    end
                end
            end else begin
                if (wr) begin
                    if (st_b == ST_E) begin
                        st_b <= ST_M;
                    end else if (st_b != ST_M) begin
                        st_b <= ST_M;
                        if (st_a == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_a <= ST_I;
                        bus_req <= 1'b1;
                        bus_cnt <= bus_cnt + 32'd1;
                    end
                end else if (st_b == ST_I) begin
                    bus_req <= 1'b1;
                    bus_cnt <= bus_cnt + 32'd1;
                    if (st_a == ST_I) begin
                        st_b <= ST_E;
                    end else begin
                        st_b <= ST_S;
                        if (st_a == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_a <= ST_S;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        assert (!(st_a == ST_M && st_b == ST_M));
endmodule

module therm_dac_seg (
    input wire clk,
    input wire i_ce,
    input wire i_mute,
    input wire i_load,
    input wire [3:0] i_val,
    input wire i_up,
    input wire i_down,
    output wire [15:0] o_seg
);
    reg [3:0]  val;
    reg [15:0] therm;
    reg        pre_mute;
    initial val = 4'd0;
    initial therm = 16'h0001;
    initial pre_mute = 1'b1;

    // binary-to-thermometer decoder: lines 0..i_val asserted
    wire [15:0] dec_in = (16'd2 << i_val) - 16'd1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (!pre_mute) begin
                // muted: segments frozen off
            end else if (i_mute) begin
                pre_mute <= 1'b0;
                val      <= 4'd0;
                therm    <= 16'd0;
            end else if (i_load) begin
                val   <= i_val;
                therm <= dec_in;
            end else if (i_up && !i_down) begin
                if (val != 4'd15) begin
                    val   <= val + 4'd1;
                    therm <= {therm[14:0], 1'b1};
                end
            end else if (i_down && !i_up) begin
                if (val != 4'd0) begin
                    val   <= val - 4'd1;
                    therm <= {1'b0, therm[15:1]};
                end
            end
        end
    end

    // registered thermometer output driving unary DAC segments
    assign o_seg = therm;

    // before mute: output is always a valid, non-empty thermometer code
    always @(*)
        assert (!pre_mute || (therm[0] && ((therm & (therm + 16'd1)) == 16'd0)));
endmodule

module traffic_ctrl (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire       preempt,
    output wire       ns_green,
    output wire       ew_green,
    output wire [2:0] phase_o
);
    // phases: 0 NS_GREEN, 1 NS_YELLOW, 2 ALL_RED_A, 3 EW_GREEN, 4 EW_YELLOW, 5 ALL_RED_B
    reg [2:0]  phase     = 3'd0;
    reg [15:0] timer     = 16'd39;
    reg [15:0] green_cnt = 16'd0;
    reg        armed     = 1'b1;
    reg        pv        = 1'b0;

    assign ns_green = (phase == 3'd0);
    assign ew_green = (phase == 3'd3);
    assign phase_o  = phase;

    function [15:0] dur;
        input [2:0] p;
        begin
            case (p)
                3'd0:    dur = 16'd39;
                3'd1:    dur = 16'd4;
                3'd2:    dur = 16'd1;
                3'd3:    dur = 16'd29;
                3'd4:    dur = 16'd4;
                default: dur = 16'd1;
            endcase
        end
    endfunction

    wire [2:0] nxt = (phase >= 3'd5) ? 3'd0 : phase + 3'd1;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (rst) begin
            phase     <= 3'd0;
            timer     <= 16'd39;
            green_cnt <= 16'd0;
            armed     <= 1'b1;
        end else if (step) begin
            if (phase == 3'd0)
                green_cnt <= green_cnt + 16'd1;
            if (phase == 3'd0 && preempt) begin
                timer <= 16'd200;
                armed <= 1'b0;
            end else if (timer == 16'd0) begin
                phase <= nxt;
                timer <= dur(nxt);
                if (nxt == 3'd0)
                    green_cnt <= 16'd0;
            end else begin
                timer <= timer - 16'd1;
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && $fell(ns_green))
            assert (green_cnt <= 16'd40);
endmodule

module vtg_frame_sync #(
    parameter [31:0] H_ACTIVE = 32'd4,
    parameter [31:0] H_FP     = 32'd1,
    parameter [31:0] H_SYNC   = 32'd2,
    parameter [31:0] H_BP     = 32'd1,
    parameter [31:0] V_ACTIVE = 32'd2,
    parameter [31:0] V_FP     = 32'd1,
    parameter [31:0] V_SYNC   = 32'd2,
    parameter [31:0] V_BP     = 32'd1
) (
    input  wire        clk,
    input  wire        ce,
    input  wire        arm,
    output wire        hsync,
    output wire        vsync,
    output wire        hblank,
    output wire        vblank,
    output wire        active,
    output wire [31:0] o_x,
    output wire [31:0] o_y,
    output wire        o_win
);
    localparam [31:0] H_TOTAL    = H_ACTIVE + H_FP + H_SYNC + H_BP;
    localparam [31:0] HS_START   = H_ACTIVE + H_FP;
    localparam [31:0] HS_END     = H_ACTIVE + H_FP + H_SYNC;
    localparam [31:0] V_TOTAL    = V_ACTIVE + V_FP + V_SYNC + V_BP;
    localparam [31:0] VS_START   = V_ACTIVE + V_FP;
    localparam [31:0] VS_END     = V_ACTIVE + V_FP + V_SYNC;

    reg [31:0] h_cnt;
    reg [31:0] v_cnt;
    reg [31:0] lines_done;
    reg        win;
    reg        pv;
    initial begin
        h_cnt = 32'd0;
        v_cnt = 32'd0;
        lines_done = 32'd0;
        win = 1'b0;
        pv = 1'b0;
    end

    wire line_end = (h_cnt == H_TOTAL - 32'd1);
    wire last_line = (v_cnt == V_TOTAL - 32'd1);
    wire vs_close = line_end && (v_cnt == VS_END - 32'd1);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (line_end) begin
                h_cnt <= 32'd0;
                if (last_line) begin
                    v_cnt <= 32'd0;
                    lines_done <= 32'd0;
                end else begin
                    v_cnt <= v_cnt + 32'd1;
                    lines_done <= lines_done + 32'd1;
                end
            end else begin
                h_cnt <= h_cnt + 32'd1;
            end
            if (vs_close)
                win <= 1'b0;
            else if (arm)
                win <= 1'b1;
        end
    end

    assign hsync  = (h_cnt >= HS_START) && (h_cnt < HS_END);
    assign vsync  = (v_cnt >= VS_START) && (v_cnt < VS_END);
    assign hblank = (h_cnt >= H_ACTIVE);
    assign vblank = (v_cnt >= V_ACTIVE);
    assign active = !hblank && !vblank;
    assign o_x = h_cnt;
    assign o_y = v_cnt;
    assign o_win = win;

    always @(posedge clk)
        if (pv && win && $rose(vsync))
            assert (lines_done == VS_START);
endmodule

module xs3_cell_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         step,
    input  wire         arm,
    input  wire         go,
    input  wire         clr,
    input  wire [127:0] a_in,
    input  wire [127:0] b_in,
    output reg  [127:0] result,
    output reg          carry_out
);
    reg [127:0] opa;
    reg [127:0] opb;
    reg [1:0]   phase;
    reg         armed_seen;
    reg         start_seen;
    reg         done;

    initial begin
        opa = 128'd0; opb = 128'd0; result = 128'd0; carry_out = 1'b0;
        phase = 2'd0; armed_seen = 1'b0; start_seen = 1'b0; done = 1'b0;
    end

    // Combinational excess-3 adder: 32 digits, binary add then +3/-3 correction
    wire [32:0]  c;
    wire [127:0] xs3_sum;
    assign c[0] = 1'b0;
    genvar i;
    generate
        for (i = 0; i < 32; i = i + 1) begin : g_dig
            wire [4:0] raw = {1'b0, opa[4*i +: 4]} + {1'b0, opb[4*i +: 4]} + {4'd0, c[i]};
            assign c[i+1] = raw[4];
            assign xs3_sum[4*i +: 4] = raw[4] ? (raw[3:0] + 4'd3) : (raw[3:0] - 4'd3);
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            phase <= 2'd0; armed_seen <= 1'b0; start_seen <= 1'b0; done <= 1'b0;
        end else if (step) begin
            case (phase)
                2'd0: if (arm) begin
                    opa <= a_in;
                    armed_seen <= 1'b1;
                    phase <= 2'd1;
                end
                2'd1: if (go) begin
                    opb <= b_in;
                    start_seen <= 1'b1;
                    phase <= 2'd2;
                end
                2'd2: begin
                    result <= xs3_sum;
                    carry_out <= c[32];
                    done <= 1'b1;
                    phase <= 2'd3;
                end
                default: if (clr) begin
                    armed_seen <= 1'b0;
                    start_seen <= 1'b0;
                    done <= 1'b0;
                    phase <= 2'd0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (done)
            assert (start_seen && armed_seen);
endmodule

module irq_prio_budget (
    input wire clk,
    input wire rst,
    input wire step,
    input wire [3:0] req,
    input wire [7:0] d0,
    input wire [7:0] d1,
    input wire [7:0] d2,
    input wire [7:0] d3,
    input wire dbg_wr,
    input wire [7:0] dbg_val,
    output reg [7:0] sel_data,
    output reg [1:0] sel_idx,
    output reg sel_vld,
    output reg [7:0] cnt
);
    reg armed;
    initial sel_data = 8'd0;
    initial sel_idx = 2'd0;
    initial sel_vld = 1'b0;
    initial cnt = 8'd0;
    initial armed = 1'b1;

    wire [7:0] c0 = (d0 > 8'd8)  ? 8'd8  : d0;
    wire [7:0] c1 = (d1 > 8'd12) ? 8'd12 : d1;
    wire [7:0] c2 = (d2 > 8'd16) ? 8'd16 : d2;
    wire [7:0] c3 = (d3 > 8'd20) ? 8'd20 : d3;

    reg [7:0] nxt_data;
    reg [1:0] nxt_idx;
    reg nxt_vld;
    always @(*) begin
        if (req[0]) begin
            nxt_data = c0; nxt_idx = 2'd0; nxt_vld = 1'b1;
        end else if (req[1]) begin
            nxt_data = c1; nxt_idx = 2'd1; nxt_vld = 1'b1;
        end else if (req[2]) begin
            nxt_data = c2; nxt_idx = 2'd2; nxt_vld = 1'b1;
        end else if (req[3]) begin
            nxt_data = c3; nxt_idx = 2'd3; nxt_vld = 1'b1;
        end else begin
            nxt_data = 8'd0; nxt_idx = 2'd0; nxt_vld = 1'b0;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            cnt <= 8'd0;
            sel_data <= 8'd0;
            sel_idx <= 2'd0;
            sel_vld <= 1'b0;
        end else if (dbg_wr) begin
            cnt <= dbg_val;
            armed <= 1'b0;
        end else if (step) begin
            if (cnt == sel_data) begin
                cnt <= 8'd0;
                sel_data <= nxt_data;
                sel_idx <= nxt_idx;
                sel_vld <= nxt_vld;
            end else begin
                cnt <= cnt + 8'd1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;
    always @(posedge clk)
        if (pv && $past(armed)) assert ($past(cnt) <= 8'd20);
endmodule

module frame_scrambler32 (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire [31:0] i_data,
    output wire [31:0] o_scr,
    output wire [31:0] o_desc
);
    localparam [31:0] SEED = 32'h1D2C3B4A;
    localparam [31:0] POLY = 32'hEDB88320;
    localparam [31:0] LAST = 32'd11;

    reg [31:0] lfsr_tx, lfsr_rx;
    reg [31:0] tx_cnt, rx_cnt;
    reg        armed;
    initial begin
        lfsr_tx = SEED; lfsr_rx = SEED;
        tx_cnt = 32'd0; rx_cnt = 32'd0;
        armed = 1'b0;
    end

    function [31:0] lfsr_step;
        input [31:0] s;
        begin
            lfsr_step = s[0] ? ((s >> 1) ^ POLY) : (s >> 1);
        end
    endfunction

    // scrambler (tx) and descrambler (rx) run in lockstep, reseeding every 12 words
    always @(posedge clk) begin
        if (rst) begin
            lfsr_tx <= SEED; lfsr_rx <= SEED;
            tx_cnt <= 32'd0; rx_cnt <= 32'd0;
        end else if (i_ce) begin
            if (tx_cnt == LAST) begin
                tx_cnt  <= 32'd0;
                lfsr_tx <= SEED;
            end else begin
                tx_cnt  <= tx_cnt + 32'd1;
                lfsr_tx <= lfsr_step(lfsr_tx);
            end
            if (rx_cnt == LAST) begin
                rx_cnt  <= 32'd0;
                lfsr_rx <= SEED;
            end else begin
                rx_cnt  <= rx_cnt + 32'd1;
                lfsr_rx <= lfsr_step(lfsr_rx);
            end
        end
    end

    // sticky scope register: set at the first scrambled word, never cleared
    always @(posedge clk)
        if (i_ce) armed <= 1'b1;

    assign o_scr  = i_data ^ lfsr_tx;
    assign o_desc = o_scr ^ lfsr_rx;

    wire tx_sof = (tx_cnt == 32'd0);
    wire tx_eof = (tx_cnt == LAST);
    wire rx_sof = (rx_cnt == 32'd0);
    wire rx_eof = (rx_cnt == LAST);

    always @(posedge clk) begin
        if (armed) begin
            assert (!(tx_sof && rx_eof));
            assert (!(tx_eof && rx_sof));
        end
    end
endmodule

module wstrobe_demux_bank (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_we,
    input  wire [4:0]  i_addr,
    input  wire [63:0] i_data,
    input  wire        i_ce,
    output wire [31:0] o_strobe,
    output wire        o_busy,
    output wire [63:0] o_num_valid
);
    reg        pending;
    reg [4:0]  addr_q;
    reg [63:0] data_q;
    reg [31:0] valid;
    reg [63:0] num_valid;
    reg        armed;
    reg [63:0] bank [0:31];
    integer i;
    initial begin
        pending = 1'b0;
        addr_q = 5'd0;
        data_q = 64'd0;
        valid = 32'd0;
        num_valid = 64'd0;
        armed = 1'b0;
        for (i = 0; i < 32; i = i + 1) bank[i] = 64'd0;
    end

    wire fire = pending && i_ce;
    wire [31:0] strobe = fire ? (32'd1 << addr_q) : 32'd0;
    wire newly_valid = |(strobe & ~valid);

    reg [63:0] valid_pop;
    integer k;
    always @(*) begin
        valid_pop = 64'd0;
        for (k = 0; k < 32; k = k + 1)
            valid_pop = valid_pop + {63'd0, valid[k]};
    end

    always @(posedge clk) begin
        if (rst) begin
            pending <= 1'b0;
            valid <= 32'd0;
            num_valid <= 64'd0;
        end else begin
            if (fire) begin
                pending <= 1'b0;
                valid <= valid | strobe;
                if (newly_valid)
                    num_valid <= num_valid + 64'd1;
                armed <= 1'b1;
            end else if (i_we && !pending) begin
                pending <= 1'b1;
                addr_q <= i_addr;
                data_q <= i_data;
            end
        end
    end

    always @(posedge clk) begin
        for (i = 0; i < 32; i = i + 1)
            if (!rst && strobe[i]) bank[i] <= data_q;
    end

    assign o_strobe = strobe;
    assign o_busy = pending;
    assign o_num_valid = num_valid;

    assert property (!armed || (num_valid <= 64'd32));
endmodule

module ctr_drbg_engine (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [1:0] cmd,
    input wire [31:0] entropy,
    output reg busy,
    output reg [31:0] out_data,
    output reg [31:0] reseed_ctr
);
    // cmd: 2'b01 instantiate, 2'b10 reseed, 2'b11 generate
    reg [31:0] key = 32'd0;
    reg [31:0] v = 32'd0;
    reg [31:0] timer = 32'd0;
    reg [31:0] rnd = 32'd0;
    reg [1:0] op = 2'b00;
    initial busy = 1'b0;
    initial out_data = 32'd0;
    initial reseed_ctr = 32'd0;

    always @(posedge clk) begin
        if (rst) begin
            key <= 32'd0;
            v <= 32'd0;
            timer <= 32'd0;
            rnd <= 32'd0;
            op <= 2'b00;
            busy <= 1'b0;
            out_data <= 32'd0;
            reseed_ctr <= 32'd0;
        end else if (ce) begin
            if (!busy) begin
                if (cmd != 2'b00) begin
                    busy <= 1'b1;
                    op <= cmd;
                    rnd <= 32'd0;
                    timer <= 32'd8;
                end
            end else begin
                v <= v + 32'd1;
                key <= {key[26:0], key[31:27]} ^ (v + 32'h9E3779B9) ^ ((op != 2'b11) ? entropy : 32'd0);
                rnd <= rnd + 32'd1;
                timer <= timer - 32'd1;
                if (rnd == 32'd5) begin
                    busy <= 1'b0;
                    timer <= 32'd0;
                    rnd <= 32'd0;
                    case (op)
                        2'b01: reseed_ctr <= 32'd1;
                        2'b10: reseed_ctr <= 32'd1;
                        2'b11: begin
                            reseed_ctr <= reseed_ctr + 32'd1;
                            out_data <= v ^ key;
                        end
                        default: reseed_ctr <= reseed_ctr;
                    endcase
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(busy)) assert ($past(timer) != 32'd0);
endmodule

module sevenseg_scan_mux (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_wr,
    input  wire [4:0]  i_waddr,
    input  wire [31:0] i_wdata,
    output reg  [6:0]  o_seg,
    output wire [31:0] o_anode
);
    // digit-index counter and one-hot digit drive (anode) register
    reg [31:0] dig_idx = 32'd0;
    reg [31:0] anode   = 32'h00000001;
    // shadow: digit 16 has been driven during this (first) frame
    reg        visited_hi = 1'b0;
    // scope register: high until the scan first wraps from digit 31 to 0
    reg        armed = 1'b1;
    // per-digit value registers
    reg [31:0] digit_val [0:31];
    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1)
            digit_val[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (i_reset) begin
            dig_idx    <= 32'd0;
            anode      <= 32'h00000001;
            visited_hi <= 1'b0;
            armed      <= 1'b1;
        end else if (i_ce) begin
            if (dig_idx == 32'd31) begin
                dig_idx <= 32'd0;
                armed   <= 1'b0;
            end else begin
                dig_idx <= dig_idx + 32'd1;
            end
            anode <= {anode[30:0], anode[31]};
            if (anode[16])
                visited_hi <= 1'b1;
        end
    end

    always @(posedge clk)
        if (i_wr)
            digit_val[i_waddr] <= i_wdata;

    wire [31:0] cur_val = digit_val[dig_idx[4:0]];
    wire [3:0]  nib     = cur_val[3:0];

    always @(*) begin
        case (nib)
            4'h0: o_seg = 7'b1000000;
            4'h1: o_seg = 7'b1111001;
            4'h2: o_seg = 7'b0100100;
            4'h3: o_seg = 7'b0110000;
            4'h4: o_seg = 7'b0011001;
            4'h5: o_seg = 7'b0010010;
            4'h6: o_seg = 7'b0000010;
            4'h7: o_seg = 7'b1111000;
            4'h8: o_seg = 7'b0000000;
            4'h9: o_seg = 7'b0010000;
            4'hA: o_seg = 7'b0001000;
            4'hB: o_seg = 7'b0000011;
            4'hC: o_seg = 7'b1000110;
            4'hD: o_seg = 7'b0100001;
            4'hE: o_seg = 7'b0000110;
            default: o_seg = 7'b0001110;
        endcase
    end

    assign o_anode = ~anode;

    // Precedence, before first wrap: driving the last digit requires digit 16 to have been driven earlier
    always @(*)
        assert (!(armed && anode[31]) || visited_hi);
endmodule

module palette_lut (
    input wire clk,
    input wire rst,
    input wire wr_en,
    input wire [1:0] wr_idx,
    input wire [31:0] wr_data,
    input wire pix_valid,
    input wire [1:0] pix_idx,
    input wire lock_cmd,
    input wire unlock_cmd,
    output reg [31:0] color_q,
    output reg [1:0] idx_q,
    output reg locked,
    output reg [31:0] lookups
);
    reg [31:0] pal0, pal1, pal2, pal3;
    initial begin
        pal0 = 32'd0; pal1 = 32'd0; pal2 = 32'd0; pal3 = 32'd0;
        color_q = 32'd0; idx_q = 2'd0; locked = 1'b0; lookups = 32'd0;
    end

    wire do_wr = wr_en && !locked;
    wire [31:0] pal_rd = (pix_idx == 2'd0) ? pal0 : (pix_idx == 2'd1) ? pal1 : (pix_idx == 2'd2) ? pal2 : pal3;
    wire [31:0] new_rd = (do_wr && (wr_idx == pix_idx)) ? wr_data : pal_rd;
    wire [31:0] cur_entry = (idx_q == 2'd0) ? pal0 : (idx_q == 2'd1) ? pal1 : (idx_q == 2'd2) ? pal2 : pal3;

    always @(posedge clk) begin
        if (rst) begin
            pal0 <= 32'd0; pal1 <= 32'd0; pal2 <= 32'd0; pal3 <= 32'd0;
            color_q <= 32'd0; idx_q <= 2'd0; locked <= 1'b0; lookups <= 32'd0;
        end else begin
            if (do_wr) begin
                case (wr_idx)
                    2'd0: pal0 <= wr_data;
                    2'd1: pal1 <= wr_data;
                    2'd2: pal2 <= wr_data;
                    default: pal3 <= wr_data;
                endcase
            end
            if (pix_valid) begin
                idx_q <= pix_idx;
                color_q <= new_rd;
                lookups <= lookups + 32'd1;
            end else if (do_wr && (wr_idx == idx_q)) begin
                color_q <= wr_data;
            end
            if (lock_cmd) locked <= 1'b1;
            else if (unlock_cmd) locked <= 1'b0;
        end
    end

    always @(posedge clk)
        if (locked)
            assert (color_q == cur_entry);
endmodule

module bypass_xact_reg (
    input  wire        clk,
    input  wire        ce,
    input  wire        arm,
    input  wire        start,
    input  wire        finish,
    input  wire        open_w,
    input  wire        close_w,
    input  wire [31:0] din,
    output wire [31:0] dout,
    output wire        bypass_en
);
    // phase: 0 idle, 1 armed (word captured), 2 started (bypass engaged), 3 finished
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        win;
    reg [31:0] stored;
    reg [31:0] xact_cnt;
    reg        pv;

    initial begin
        phase = 2'd0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        win = 1'b0;
        stored = 32'd0;
        xact_cnt = 32'd0;
        pv = 1'b0;
    end

    // bypass multiplexer: steer input straight through while started,
    // the stored copy is left untouched
    assign bypass_en = (phase == 2'd2);
    assign dout = bypass_en ? din : stored;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (open_w)       win <= 1'b1;
            else if (close_w) win <= 1'b0;

            case (phase)
                2'd0: if (arm) begin
                    phase    <= 2'd1;
                    arm_seen <= 1'b1;
                    stored   <= din;
                end
                2'd1: if (start) begin
                    phase      <= 2'd2;
                    start_seen <= 1'b1;
                end
                2'd2: if (finish) begin
                    phase    <= 2'd3;
                    xact_cnt <= xact_cnt + 32'd1;
                end
                default: begin
                    phase      <= 2'd0;
                    arm_seen   <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
        end
    end

    // chain precedence inside the window: a finish is only observed if
    // arm and start had both happened in the previous cycle's record
    always @(posedge clk)
        if (pv && win && phase == 2'd3)
            assert ($past(start_seen) && $past(arm_seen));
endmodule

module pipe_ao22_track (
    input  wire        clk,
    input  wire        rst,
    input  wire        step,
    input  wire        in_valid,
    input  wire [31:0] din,
    input  wire        open_win,
    input  wire        close_win,
    output wire [31:0] dout,
    output wire        dout_valid
);
    reg        v1;
    reg [31:0] s1;
    reg        v2;
    reg [31:0] s2;
    reg        seen_in;
    reg [31:0] in_cnt;
    reg        armed;

    initial v1 = 1'b0;
    initial s1 = 32'd0;
    initial v2 = 1'b0;
    initial s2 = 32'd0;
    initial seen_in = 1'b0;
    initial in_cnt = 32'd0;
    initial armed = 1'b0;

    wire [31:0] s1_next;
    wire [31:0] s2_next;

    ao22 #(.W(32)) u_s1 (
        .a({32{in_valid}}), .b(din),
        .c({32{~in_valid}}), .d(s1),
        .y(s1_next)
    );

    ao22 #(.W(32)) u_s2 (
        .a({32{v1}}), .b(s1),
        .c({32{~v1}}), .d(s2),
        .y(s2_next)
    );

    assign dout = s2;
    assign dout_valid = v2;

    always @(posedge clk) begin
        if (rst) begin
            v1 <= 1'b0;
            s1 <= 32'd0;
            v2 <= 1'b0;
            s2 <= 32'd0;
            seen_in <= 1'b0;
            in_cnt <= 32'd0;
            armed <= 1'b0;
        end else if (step) begin
            v1 <= in_valid;
            s1 <= s1_next;
            v2 <= v1;
            s2 <= s2_next;
            seen_in <= seen_in | in_valid;
            if (in_valid && (in_cnt != 32'hFFFFFFFF))
                in_cnt <= in_cnt + 32'd1;
            if (open_win)
                armed <= 1'b1;
            else if (close_win)
                armed <= 1'b0;
        end
    end

    always @(posedge clk)
        if (armed && v2) assert (seen_in);

    always @(posedge clk)
        if (armed && v2) assert (in_cnt != 32'd0);
endmodule

module ao22 #(parameter W = 32) (
    input  wire [W-1:0] a,
    input  wire [W-1:0] b,
    input  wire [W-1:0] c,
    input  wire [W-1:0] d,
    output wire [W-1:0] y
);
    assign y = (a & b) | (c & d);
endmodule

module age_matrix_iq (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_alloc,
    input  wire        i_alloc_ready,
    input  wire [31:0] i_alloc_tag,
    input  wire        i_issue,
    input  wire [3:0]  i_wake,
    output reg  [31:0] o_issue_tag,
    output wire        o_issue_valid,
    output wire [31:0] o_issue_cnt
);
    // age[i*4+j] == 1 means entry i is older than entry j
    reg [3:0]   valid = 4'b0000;
    reg [3:0]   ready = 4'b0000;
    reg [15:0]  age = 16'h0000;
    reg [127:0] tags = 128'd0;
    reg [31:0]  issue_cnt = 32'd0;
    reg         armed = 1'b0;
    reg         pv = 1'b0;

    reg [3:0] grant;
    reg [3:0] free_sel;
    integer i, j, k;

    wire [3:0] rv = valid & ready;
    wire issue_fire = i_ce & i_issue & (|rv);
    wire alloc_fire = i_ce & i_alloc & ~(&valid);

    // oldest-ready select: an entry wins if no other ready entry is older
    always @(*) begin
        for (i = 0; i < 4; i = i + 1) begin
            grant[i] = rv[i];
            for (j = 0; j < 4; j = j + 1)
                if (j != i && rv[j] && age[j*4+i]) grant[i] = 1'b0;
        end
        if (!valid[0])      free_sel = 4'b0001;
        else if (!valid[1]) free_sel = 4'b0010;
        else if (!valid[2]) free_sel = 4'b0100;
        else if (!valid[3]) free_sel = 4'b1000;
        else                free_sel = 4'b0000;
        o_issue_tag = 32'd0;
        for (k = 0; k < 4; k = k + 1)
            if (grant[k]) o_issue_tag = o_issue_tag | tags[k*32 +: 32];
    end

    assign o_issue_valid = issue_fire;
    assign o_issue_cnt = issue_cnt;

    always @(posedge clk) begin
        if (issue_fire) begin
            issue_cnt <= issue_cnt + 32'd1;
            armed <= 1'b1;
        end
        for (i = 0; i < 4; i = i + 1) begin
            if (alloc_fire && free_sel[i]) begin
                valid[i] <= 1'b1;
                ready[i] <= i_alloc_ready;
                tags[i*32 +: 32] <= i_alloc_tag;
                for (j = 0; j < 4; j = j + 1)
                    if (j != i) begin
                        age[i*4+j] <= 1'b0;
                        age[j*4+i] <= valid[j];
                    end
            end else begin
                if (issue_fire && grant[i]) valid[i] <= 1'b0;
                if (i_ce && valid[i] && i_wake[i]) ready[i] <= 1'b1;
            end
        end
    end

    always @(posedge clk) pv <= 1'b1;

    // after the first issue: if the valid set did not change, no issue was counted
    always @(posedge clk)
        if (pv && armed && $stable(valid))
            assert ($stable(issue_cnt));
endmodule

module sd_dac_lockstep (
    input wire clk,
    input wire ce,
    input wire mute,
    input wire [15:0] din,
    output reg dout,
    output reg dchk
);
    // main first-order sigma-delta error accumulator
    reg [15:0] acc = 16'h0000;
    // lockstep reference accumulator (does not see mute)
    reg [15:0] acc_chk = 16'h0000;
    // scope register: high until the first mute event
    reg before_mute = 1'b1;
    reg pv = 1'b0;

    initial dout = 1'b0;
    initial dchk = 1'b0;

    wire [16:0] sum     = {1'b0, acc}     + {1'b0, din};
    wire [16:0] sum_chk = {1'b0, acc_chk} + {1'b0, din};

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (mute) begin
            acc  <= 16'h0000;
            dout <= 1'b0;
        end else if (ce) begin
            acc  <= sum[15:0];
            dout <= sum[16];
        end
    end

    always @(posedge clk) begin
        if (ce) begin
            acc_chk <= sum_chk[15:0];
            dchk    <= sum_chk[16];
        end
    end

    always @(posedge clk) begin
        if (mute)
            before_mute <= 1'b0;
    end

    // Absence, before first mute: never (reference bit held) and (main bit toggled)
    always @(posedge clk)
        if (pv && before_mute)
            assert (!($stable(dchk) && !$stable(dout)));
endmodule

module its_xlate #(
    parameter DEV_ENTRIES = 16,
    parameter CQ_DEPTH = 16,
    parameter DW = 64,
    parameter DEVW = 4,
    parameter AW = 4
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            cmd_valid,
    output wire            cmd_ready,
    input  wire [1:0]      cmd_op,
    input  wire [DEVW-1:0] cmd_dev,
    input  wire [DW-1:0]   cmd_base,
    input  wire [DW-1:0]   cmd_coll,
    input  wire            exec_en,
    input  wire            req_valid,
    output wire            req_ready,
    input  wire [DEVW-1:0] req_dev,
    input  wire [DW-1:0]   req_event,
    output reg             out_valid,
    input  wire            out_ready,
    output reg  [DW-1:0]   out_intid,
    output reg  [DW-1:0]   out_coll,
    output reg  [DW-1:0]   xlat_count,
    output reg  [DW-1:0]   miss_count
);
    localparam [1:0] OP_MAPD = 2'd1;
    localparam [1:0] OP_UNMAPD = 2'd2;

    reg [1:0]      cq_op   [0:CQ_DEPTH-1];
    reg [DEVW-1:0] cq_dev  [0:CQ_DEPTH-1];
    reg [DW-1:0]   cq_base [0:CQ_DEPTH-1];
    reg [DW-1:0]   cq_coll [0:CQ_DEPTH-1];
    reg [AW:0]     wptr;
    reg [AW:0]     rptr;

    reg [DEV_ENTRIES-1:0] dev_valid;
    reg [DW-1:0]   dt_base [0:DEV_ENTRIES-1];
    reg [DW-1:0]   dt_coll [0:DEV_ENTRIES-1];

    reg seen_map;

    wire [AW:0] cq_count = wptr - rptr;
    assign cmd_ready = (cq_count != CQ_DEPTH);
    assign req_ready = !out_valid || out_ready;

    wire [1:0]      ex_op   = cq_op[rptr[AW-1:0]];
    wire [DEVW-1:0] ex_dev  = cq_dev[rptr[AW-1:0]];
    wire [DW-1:0]   ex_base = cq_base[rptr[AW-1:0]];
    wire [DW-1:0]   ex_coll = cq_coll[rptr[AW-1:0]];

    integer i;
    initial begin
        wptr = 0;
        rptr = 0;
        dev_valid = 0;
        seen_map = 1'b0;
        out_valid = 1'b0;
        out_intid = 0;
        out_coll = 0;
        xlat_count = 0;
        miss_count = 0;
        for (i = 0; i < CQ_DEPTH; i = i + 1) begin
            cq_op[i] = 0;
            cq_dev[i] = 0;
            cq_base[i] = 0;
            cq_coll[i] = 0;
        end
        for (i = 0; i < DEV_ENTRIES; i = i + 1) begin
            dt_base[i] = 0;
            dt_coll[i] = 0;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr <= 0;
            rptr <= 0;
            dev_valid <= 0;
            seen_map <= 1'b0;
            out_valid <= 1'b0;
            out_intid <= 0;
            out_coll <= 0;
            xlat_count <= 0;
            miss_count <= 0;
            for (i = 0; i < CQ_DEPTH; i = i + 1) begin
                cq_op[i] <= 0;
                cq_dev[i] <= 0;
                cq_base[i] <= 0;
                cq_coll[i] <= 0;
            end
            for (i = 0; i < DEV_ENTRIES; i = i + 1) begin
                dt_base[i] <= 0;
                dt_coll[i] <= 0;
            end
        end else begin
            if (cmd_valid && cmd_ready) begin
                cq_op[wptr[AW-1:0]]   <= cmd_op;
                cq_dev[wptr[AW-1:0]]  <= cmd_dev;
                cq_base[wptr[AW-1:0]] <= cmd_base;
                cq_coll[wptr[AW-1:0]] <= cmd_coll;
                wptr <= wptr + 1'b1;
            end
            if (exec_en && (cq_count != 0)) begin
                if (ex_op == OP_MAPD) begin
                    dev_valid[ex_dev] <= 1'b1;
                    dt_base[ex_dev] <= ex_base;
                    dt_coll[ex_dev] <= ex_coll;
                    seen_map <= 1'b1;
                end else if (ex_op == OP_UNMAPD) begin
                    dev_valid[ex_dev] <= 1'b0;
                end
                rptr <= rptr + 1'b1;
            end
            if (out_valid && out_ready)
                out_valid <= 1'b0;
            if (req_valid && req_ready) begin
                if (dev_valid[req_dev]) begin
                    out_valid <= 1'b1;
                    out_intid <= dt_base[req_dev] + req_event;
                    out_coll <= dt_coll[req_dev];
                    xlat_count <= xlat_count + 1'b1;
                end else begin
                    miss_count <= miss_count + 1'b1;
                end
            end
        end
    end

    always @(posedge clk)
        if (xlat_count != {DW{1'b0}}) assert (seen_map);
endmodule

module sw_reset_ctrl #(
    parameter NPERIPH = 4,
    parameter IDXW = 2,
    parameter [31:0] PULSE_LEN = 32'd8
) (
    input  wire               clk,
    input  wire               rst,
    input  wire               cmd_valid,
    output wire               cmd_ready,
    input  wire [1:0]         cmd_op,
    input  wire [IDXW-1:0]    cmd_idx,
    input  wire               tick,
    output wire [NPERIPH-1:0] periph_rst,
    output wire               pulse_busy
);
    typedef enum logic [1:0] {IDLE = 2'd0, PULSE = 2'd1} state_t;

    localparam [1:0] OP_SET   = 2'd0;
    localparam [1:0] OP_CLR   = 2'd1;
    localparam [1:0] OP_PULSE = 2'd2;

    state_t            state     = IDLE;
    reg [NPERIPH-1:0]  rst_ctrl  = {NPERIPH{1'b0}};
    reg [31:0]         n_held    = 32'd0;
    reg [31:0]         pulse_cnt = 32'd0;
    reg [31:0]         remain    = 32'd0;
    reg [IDXW-1:0]     pulse_idx = {IDXW{1'b0}};
    reg                win       = 1'b0;

    assign cmd_ready = (state == IDLE) || (cmd_op != OP_PULSE);
    wire fire     = cmd_valid && cmd_ready;
    wire do_set   = fire && (cmd_op == OP_SET) && !rst_ctrl[cmd_idx];
    wire do_clr   = fire && (cmd_op == OP_CLR) &&  rst_ctrl[cmd_idx];
    wire do_pulse = fire && (cmd_op == OP_PULSE);

    assign pulse_busy = (state == PULSE);
    assign periph_rst = rst_ctrl | ((state == PULSE) ? ({{(NPERIPH-1){1'b0}}, 1'b1} << pulse_idx) : {NPERIPH{1'b0}});

    always @(posedge clk) begin
        if (rst) begin
            state     <= IDLE;
            rst_ctrl  <= {NPERIPH{1'b0}};
            n_held    <= 32'd0;
            pulse_cnt <= 32'd0;
            remain    <= 32'd0;
            pulse_idx <= {IDXW{1'b0}};
            win       <= 1'b0;
        end else begin
            if (do_set) begin
                rst_ctrl[cmd_idx] <= 1'b1;
                n_held <= n_held + 32'd1;
            end else if (do_clr) begin
                rst_ctrl[cmd_idx] <= 1'b0;
                n_held <= n_held - 32'd1;
            end
            case (state)
                IDLE: begin
                    if (do_pulse) begin
                        state     <= PULSE;
                        win       <= 1'b1;
                        pulse_cnt <= 32'd0;
                        remain    <= PULSE_LEN - 32'd1;
                        pulse_idx <= cmd_idx;
                    end
                end
                PULSE: begin
                    if (tick) begin
                        if (remain == 32'd0) begin
                            state <= IDLE;
                            win   <= 1'b0;
                        end else begin
                            pulse_cnt <= pulse_cnt + 32'd1;
                            remain    <= remain - 32'd1;
                        end
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    always @(posedge clk) if (win) assert (pulse_cnt < PULSE_LEN);
    always @(posedge clk) if (win) assert (n_held <= NPERIPH);
endmodule

module lockable_cfg #(
    parameter WIDTH = 32
) (
    input  wire             clk,
    input  wire             i_reset,
    input  wire             in_valid,
    output wire             in_ready,
    input  wire [1:0]       in_cmd,
    input  wire [WIDTH-1:0] in_data,
    output wire [WIDTH-1:0] cfg_out,
    output wire             cfg_locked
);
    localparam [1:0] CMD_ARM   = 2'd1;
    localparam [1:0] CMD_WRITE = 2'd2;
    localparam [1:0] CMD_LOCK  = 2'd3;
    localparam [WIDTH-1:0] CFG_DEFAULT = {WIDTH{1'b0}};

    typedef enum logic [1:0] {S_OPEN, S_ARMED, S_WRITTEN, S_LOCKED} state_t;

    state_t state;
    initial state = S_OPEN;

    reg [WIDTH-1:0] cfg_word = CFG_DEFAULT;
    reg locked     = 1'b0;
    reg arm_seen   = 1'b0;
    reg start_seen = 1'b0;
    reg before_r   = 1'b1;
    reg pv         = 1'b0;

    assign in_ready   = (state != S_LOCKED);
    assign cfg_out    = cfg_word;
    assign cfg_locked = locked;

    wire xfer       = in_valid && in_ready;
    wire fire_arm   = xfer && (state == S_OPEN) && (in_cmd == CMD_ARM);
    wire fire_write = xfer && ((state == S_ARMED) || (state == S_WRITTEN)) && (in_cmd == CMD_WRITE);
    wire fire_lock  = xfer && (state == S_WRITTEN) && (in_cmd == CMD_LOCK);

    always @(posedge clk) begin
        if (i_reset) begin
            state      <= S_OPEN;
            cfg_word   <= CFG_DEFAULT;
            locked     <= 1'b0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
        end else begin
            if (fire_arm) begin
                state    <= S_ARMED;
                arm_seen <= 1'b1;
            end
            if (fire_write) begin
                cfg_word   <= in_data;
                start_seen <= 1'b1;
                if (state == S_ARMED)
                    state <= S_WRITTEN;
            end
            if (fire_lock) begin
                locked <= 1'b1;
                state  <= S_LOCKED;
            end
        end
    end

    always @(posedge clk)
        if (i_reset)
            before_r <= 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && before_r && $past(fire_lock))
            assert ($past(arm_seen) && $past(start_seen));
endmodule

module dualrail_asr #(
    parameter WIDTH = 32,
    parameter [WIDTH-1:0] INIT = 32'h8000_0000
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             en,
    input  wire             dir,
    input  wire             load,
    input  wire [WIDTH-1:0] din,
    output reg  [WIDTH-1:0] data,
    output reg  [WIDTH-1:0] nd,
    output reg              armed
);
    initial data  = INIT;
    initial nd    = ~INIT;
    initial armed = 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            data  <= INIT;
            nd    <= ~INIT;
            armed <= 1'b1;
        end else if (en) begin
            if (load) begin
                data <= din;
                nd   <= ~din;
            end else if (dir) begin
                data  <= {data[WIDTH-2:0], 1'b0};
                nd    <= {nd[WIDTH-2:0], 1'b0};
                armed <= 1'b0;
            end else begin
                data <= {data[WIDTH-1], data[WIDTH-1:1]};
                nd   <= {nd[WIDTH-1], nd[WIDTH-1:1]};
            end
        end
    end

    always @(posedge clk)
        assert (!armed || (data[0] != nd[0]));
endmodule

module bar_req_queue #(
    parameter DEPTH = 8,
    parameter AW = 3
) (
    input  wire       clk,
    input  wire       rst,
    input  wire       in_valid,
    output wire       in_ready,
    input  wire [7:0] in_addr,
    output wire       out_valid,
    input  wire       out_ready,
    output wire [7:0] out_addr,
    input  wire       irq_on_done,
    input  wire       host_wr,
    input  wire       host_wdata,
    output wire       irq
);
    localparam [7:0] CAP = DEPTH;

    reg [7:0] mem [0:DEPTH-1];
    reg [AW-1:0] wptr = 0;
    reg [AW-1:0] rptr = 0;
    reg [7:0] count = 8'd0;
    reg [7:0] credits = CAP;
    reg irq_pend = 1'b0;
    reg armed = 1'b0;
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = 8'd0;
    end

    assign in_ready  = (credits != 8'd0);
    assign out_valid = (count != 8'd0);
    assign out_addr  = mem[rptr];
    assign irq       = irq_pend;

    wire in_fire  = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    // request storage and credit accounting
    always @(posedge clk) begin
        if (rst) begin
            wptr <= 0;
            rptr <= 0;
            count <= 8'd0;
            credits <= CAP;
        end else begin
            if (in_fire) begin
                mem[wptr] <= in_addr;
                wptr <= wptr + 1'b1;
            end
            if (out_fire) rptr <= rptr + 1'b1;
            case ({in_fire, out_fire})
                2'b10: begin count <= count + 8'd1; credits <= credits - 8'd1; end
                2'b01: begin count <= count - 8'd1; credits <= credits + 8'd1; end
                default: begin count <= count; credits <= credits; end
            endcase
        end
    end

    // dual-port latch: completion port and host port both write the shared pending bit
    wire en_a = out_fire;
    wire d_a  = irq_on_done;
    wire en_b = host_wr;
    wire d_b  = host_wdata;
    always @(posedge clk) begin
        if (rst)       irq_pend <= 1'b0;
        else if (en_a) irq_pend <= d_a;
        else if (en_b) irq_pend <= d_b;
        else           irq_pend <= irq_pend;
    end

    // after-Q scope: armed by the first accepted request, never cleared
    always @(posedge clk) begin
        if (in_fire) armed <= 1'b1;
    end

    always @(posedge clk) if (armed) assert (count <= CAP);
    always @(posedge clk) if (armed) assert (credits <= CAP);
endmodule

module aes_keyexp64 #(
    parameter [63:0] NR = 64'd10
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         s_valid,
    output wire         s_ready,
    input  wire [255:0] s_key,
    input  wire         step,
    output reg          m_valid,
    input  wire         m_ready,
    output wire [255:0] m_key,
    output wire [63:0]  m_round
);
    reg [63:0] kw0, kw1, kw2, kw3;
    reg [63:0] round;
    reg [63:0] countdown;
    reg        busy;
    reg        armed;

    initial begin
        kw0 = 64'd0; kw1 = 64'd0; kw2 = 64'd0; kw3 = 64'd0;
        round = 64'd0;
        countdown = 64'd0;
        busy = 1'b0;
        armed = 1'b0;
        m_valid = 1'b0;
    end

    assign s_ready = !busy;
    wire accept = s_valid && s_ready;
    wire adv    = busy && armed && step;

    wire [63:0] rcon = 64'h1 << round[5:0];
    wire [63:0] g    = {kw3[55:0], kw3[63:56]} ^ rcon;
    wire [63:0] n0   = kw0 ^ g;
    wire [63:0] n1   = kw1 ^ n0;
    wire [63:0] n2   = kw2 ^ n1;
    wire [63:0] n3   = kw3 ^ n2;

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            armed     <= 1'b0;
            m_valid   <= 1'b0;
            round     <= 64'd0;
            countdown <= 64'd0;
        end else if (accept) begin
            busy      <= 1'b1;
            armed     <= 1'b1;
            m_valid   <= 1'b0;
            round     <= 64'd0;
            countdown <= NR;
            kw0 <= s_key[63:0];
            kw1 <= s_key[127:64];
            kw2 <= s_key[191:128];
            kw3 <= s_key[255:192];
        end else if (adv) begin
            round     <= round + 64'd1;
            countdown <= countdown - 64'd1;
            kw0 <= n0;
            kw1 <= n1;
            kw2 <= n2;
            kw3 <= n3;
            if (round + 64'd1 == NR) begin
                armed   <= 1'b0;
                m_valid <= 1'b1;
            end
        end else if (m_valid && m_ready) begin
            m_valid <= 1'b0;
            busy    <= 1'b0;
        end
    end

    assign m_key   = {kw3, kw2, kw1, kw0};
    assign m_round = round;

    assert property (!armed || countdown != 64'd0);
endmodule

module xdom_pulse_demux #(
    parameter N = 64,
    parameter SELW = 6
) (
    input  wire            clk,
    input  wire            rst,
    input  wire            in_valid,
    output wire            in_ready,
    input  wire [SELW-1:0] in_sel,
    input  wire            dst_ce,
    output wire [N-1:0]    out_pulse,
    output wire            busy_o
);
    localparam [63:0] LAT = 64'd3;

    reg [N-1:0] src_tog = {N{1'b0}};
    reg [N-1:0] s1 = {N{1'b0}};
    reg [N-1:0] s2 = {N{1'b0}};
    reg [N-1:0] s3 = {N{1'b0}};
    reg         busy = 1'b0;
    reg [63:0]  countdown = 64'd0;

    assign in_ready  = !busy;
    wire   accept    = in_valid && in_ready;
    assign out_pulse = s2 ^ s3;
    assign busy_o    = busy;

    always @(posedge clk) begin
        if (rst) begin
            src_tog   <= {N{1'b0}};
            s1        <= {N{1'b0}};
            s2        <= {N{1'b0}};
            s3        <= {N{1'b0}};
            busy      <= 1'b0;
            countdown <= 64'd0;
        end else begin
            if (accept)
                src_tog <= src_tog ^ ({{(N-1){1'b0}}, 1'b1} << in_sel);
            if (dst_ce) begin
                s1 <= src_tog;
                s2 <= s1;
                s3 <= s2;
            end
            if (accept) begin
                busy      <= 1'b1;
                countdown <= LAT;
            end else if (busy && dst_ce) begin
                if (|out_pulse) begin
                    busy      <= 1'b0;
                    countdown <= 64'd0;
                end else begin
                    countdown <= countdown - 64'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (busy) assert (countdown != 64'd0);
endmodule

module uart_tx_word #(
    parameter DATA_W = 32
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire              baud_tick,
    input  wire              s_valid,
    output wire              s_ready,
    input  wire [DATA_W-1:0] s_data,
    output wire              txd,
    output wire              o_busy
);
    localparam integer FRAME_W = DATA_W + 3;
    localparam [31:0] LAST = FRAME_W - 1;
    localparam [FRAME_W-1:0] ONE = 1;

    reg [FRAME_W-1:0] shreg = {FRAME_W{1'b0}};
    reg [31:0] bitcnt = 32'd0;
    reg busy = 1'b0;
    reg in_frame = 1'b0;

    assign s_ready = !busy;
    assign txd = busy ? shreg[0] : 1'b1;
    assign o_busy = busy;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shreg <= {FRAME_W{1'b0}};
            bitcnt <= 32'd0;
            busy <= 1'b0;
            in_frame <= 1'b0;
        end else if (s_valid && s_ready) begin
            shreg <= {1'b1, ^s_data, s_data, 1'b0};
            bitcnt <= 32'd0;
            busy <= 1'b1;
            in_frame <= 1'b1;
        end else if (baud_tick && busy) begin
            bitcnt <= bitcnt + 32'd1;
            if (shreg == ONE) begin
                shreg <= {FRAME_W{1'b0}};
                busy <= 1'b0;
                in_frame <= 1'b0;
            end else begin
                shreg <= shreg >> 1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && in_frame && $rose(txd))
            assert (bitcnt <= LAST);
endmodule

module assoc_bitserial #(
    parameter N  = 8,
    parameter W  = 32,
    parameter CW = 6,
    parameter TW = 4
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire          in_op,
    input  wire [2:0]    in_addr,
    input  wire [W-1:0]  in_data,
    input  wire [W-1:0]  in_mask,
    input  wire          i_step,
    output reg           res_valid,
    input  wire          res_ready,
    output wire [N-1:0]  res_tag,
    output wire          res_any
);
    reg [N*W-1:0] words;
    reg [W-1:0]   comparand;
    reg [W-1:0]   mask;
    reg [N-1:0]   tag;
    reg [TW-1:0]  hit_cnt;
    reg [CW-1:0]  col;
    reg           busy;

    initial begin
        words = {N*W{1'b0}};
        comparand = {W{1'b0}};
        mask = {W{1'b0}};
        tag = {N{1'b0}};
        hit_cnt = {TW{1'b0}};
        col = {CW{1'b0}};
        busy = 1'b0;
        res_valid = 1'b0;
    end

    assign in_ready = !busy && !res_valid;
    assign res_tag  = tag;
    assign res_any  = (hit_cnt != {TW{1'b0}});

    wire [4:0] bit_idx = col[4:0];
    wire cmp_bit = comparand[bit_idx];
    wire msk_bit = mask[bit_idx];

    wire [N-1:0] keep;
    genvar g;
    generate
        for (g = 0; g < N; g = g + 1) begin : g_col
            assign keep[g] = !msk_bit || (words[g*W + bit_idx] == cmp_bit);
        end
    endgenerate

    wire [N-1:0] cleared = tag & ~keep;
    reg [TW-1:0] drop;
    integer k;
    always @(*) begin
        drop = {TW{1'b0}};
        for (k = 0; k < N; k = k + 1)
            drop = drop + {{(TW-1){1'b0}}, cleared[k]};
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            words <= {N*W{1'b0}};
            comparand <= {W{1'b0}};
            mask <= {W{1'b0}};
            tag <= {N{1'b0}};
            hit_cnt <= {TW{1'b0}};
            col <= {CW{1'b0}};
            busy <= 1'b0;
            res_valid <= 1'b0;
        end else begin
            if (res_valid && res_ready)
                res_valid <= 1'b0;
            if (in_valid && in_ready) begin
                if (in_op) begin
                    comparand <= in_data;
                    mask <= in_mask;
                    tag <= {N{1'b1}};
                    hit_cnt <= N[TW-1:0];
                    col <= {CW{1'b0}};
                    busy <= 1'b1;
                end else begin
                    words[in_addr*W +: W] <= in_data;
                end
            end else if (busy && i_step) begin
                tag <= tag & keep;
                hit_cnt <= hit_cnt - drop;
                if (col == W-1) begin
                    col <= W[CW-1:0];
                    busy <= 1'b0;
                    res_valid <= 1'b1;
                end else begin
                    col <= col + 1'b1;
                end
            end
        end
    end

    always @(posedge clk)
        if (busy)
            assert ((hit_cnt != {TW{1'b0}}) == (tag != {N{1'b0}}));
endmodule

module shader_alu_seq #(
    parameter W = 32
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         i_ce,
    input  wire         i_frame,
    input  wire         i_arm,
    input  wire         i_go,
    input  wire [2:0]   i_op,
    input  wire [W-1:0] i_operand,
    output wire [W-1:0] o_acc,
    output wire [3:0]   o_flags
);
    localparam [1:0] PH_IDLE    = 2'd0;
    localparam [1:0] PH_ARMED   = 2'd1;
    localparam [1:0] PH_STARTED = 2'd2;

    localparam [2:0] OP_ADD = 3'd0;
    localparam [2:0] OP_SUB = 3'd1;
    localparam [2:0] OP_AND = 3'd2;
    localparam [2:0] OP_OR  = 3'd3;
    localparam [2:0] OP_XOR = 3'd4;

    reg [1:0]   phase     = PH_IDLE;
    reg         armed_f   = 1'b0;
    reg         started_f = 1'b0;
    reg         q_seen    = 1'b0;
    reg [W-1:0] acc       = {W{1'b0}};
    reg [W-1:0] opnd      = {W{1'b0}};
    reg [2:0]   opsel     = 3'd0;
    reg [W-1:0] res       = {W{1'b0}};
    reg         c_r       = 1'b0;
    reg         v_r       = 1'b0;
    reg [3:0]   flags     = 4'd0; // {C, Z, N, V}

    wire arm_evt   = i_ce && (phase == PH_IDLE)    && i_arm;
    wire start_evt = i_ce && (phase == PH_ARMED)   && i_go;
    wire fin_evt   = i_ce && (phase == PH_STARTED);

    wire [W:0] sum  = {1'b0, acc} + {1'b0, opnd};
    wire [W:0] diff = {1'b0, acc} - {1'b0, opnd};

    reg [W-1:0] alu_res;
    reg         alu_c;
    reg         alu_v;
    always @(*) begin
        alu_c = 1'b0;
        alu_v = 1'b0;
        case (opsel)
            OP_ADD: begin
                alu_res = sum[W-1:0];
                alu_c   = sum[W];
                alu_v   = (acc[W-1] == opnd[W-1]) && (sum[W-1] != acc[W-1]);
            end
            OP_SUB: begin
                alu_res = diff[W-1:0];
                alu_c   = diff[W];
                alu_v   = (acc[W-1] != opnd[W-1]) && (diff[W-1] != acc[W-1]);
            end
            OP_AND:  alu_res = acc & opnd;
            OP_OR:   alu_res = acc | opnd;
            OP_XOR:  alu_res = acc ^ opnd;
            default: alu_res = opnd;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase     <= PH_IDLE;
            armed_f   <= 1'b0;
            started_f <= 1'b0;
            q_seen    <= 1'b0;
            acc       <= {W{1'b0}};
            opnd      <= {W{1'b0}};
            opsel     <= 3'd0;
            res       <= {W{1'b0}};
            c_r       <= 1'b0;
            v_r       <= 1'b0;
            flags     <= 4'd0;
        end else begin
            if (i_ce && i_frame)
                q_seen <= 1'b1;
            if (arm_evt) begin
                phase   <= PH_ARMED;
                armed_f <= 1'b1;
                opnd    <= i_operand;
                opsel   <= i_op;
            end else if (start_evt) begin
                phase     <= PH_STARTED;
                armed_f   <= 1'b0;
                started_f <= 1'b1;
                res       <= alu_res;
                c_r       <= alu_c;
                v_r       <= alu_v;
            end else if (fin_evt) begin
                phase     <= PH_IDLE;
                started_f <= 1'b0;
                acc       <= res;
                flags     <= {c_r, (res == {W{1'b0}}), res[W-1], v_r};
            end
        end
    end

    assign o_acc   = acc;
    assign o_flags = flags;

    reg pv = 1'b0;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && q_seen)
            assert ((!$past(fin_evt) || $past(started_f)) &&
                    (!$past(start_evt) || $past(armed_f)));
endmodule

module comma_align_search #(
    parameter W = 16,
    parameter NOFF = 16,
    parameter [15:0] COMMA = 16'hFA0C
) (
    input  wire clk,
    input  wire rst_n,
    input  wire ce,
    input  wire start,
    input  wire [W-1:0] din,
    output reg  [$clog2(NOFF)-1:0] align_off,
    output reg  locked,
    output reg  searching
);
    localparam OW = $clog2(NOFF);

    reg [W-1:0]  prev_word = {W{1'b0}};
    reg [15:0]   timer     = 16'd0;
    reg [OW-1:0] scan_off  = {OW{1'b0}};
    initial align_off = {OW{1'b0}};
    initial locked    = 1'b0;
    initial searching = 1'b0;

    wire [2*W-1:0] win  = {prev_word, din};
    wire [2*W-1:0] shft = win >> scan_off;
    wire [W-1:0]   cand = shft[W-1:0];
    wire           match = (cand == COMMA);
    wire           expired = (timer == 16'd0);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            prev_word <= {W{1'b0}};
            timer     <= 16'd0;
            scan_off  <= {OW{1'b0}};
            align_off <= {OW{1'b0}};
            locked    <= 1'b0;
            searching <= 1'b0;
        end else if (ce) begin
            prev_word <= din;
            if (!searching) begin
                if (start) begin
                    searching <= 1'b1;
                    locked    <= 1'b0;
                    timer     <= NOFF;
                    scan_off  <= {OW{1'b0}};
                end
            end else begin
                if (match) begin
                    align_off <= scan_off;
                    locked    <= 1'b1;
                    searching <= 1'b0;
                    timer     <= 16'd0;
                    scan_off  <= {OW{1'b0}};
                end else if (scan_off == NOFF - 1) begin
                    searching <= 1'b0;
                    timer     <= 16'd0;
                    scan_off  <= {OW{1'b0}};
                end else begin
                    timer     <= timer - 16'd1;
                    scan_off  <= scan_off + 1'b1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(expired)) assert (!searching);
endmodule

module rtc_calendar #(
    parameter W = 16,
    parameter [W-1:0] SEC_LAST   = 16'd59,
    parameter [W-1:0] MIN_LAST   = 16'd59,
    parameter [W-1:0] HOUR_LAST  = 16'd23,
    parameter [W-1:0] DAY_LAST   = 16'd30,
    parameter [W-1:0] MONTH_LAST = 16'd12
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         ce,
    input  wire         tick,
    input  wire         alarm_arm,
    input  wire         alarm_clear,
    output wire [W-1:0] o_sec,
    output wire [W-1:0] o_min,
    output wire [W-1:0] o_hour,
    output wire [W-1:0] o_day,
    output wire [W-1:0] o_month,
    output wire         o_minute_strobe,
    output wire         o_window
);
    reg [W-1:0] sec, sec_left, minute, hour, day, month;
    reg         in_window;

    initial begin
        sec       = {W{1'b0}};
        sec_left  = SEC_LAST;
        minute    = {W{1'b0}};
        hour      = {W{1'b0}};
        day       = 16'd1;
        month     = 16'd1;
        in_window = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            sec       <= {W{1'b0}};
            sec_left  <= SEC_LAST;
            minute    <= {W{1'b0}};
            hour      <= {W{1'b0}};
            day       <= 16'd1;
            month     <= 16'd1;
            in_window <= 1'b0;
        end else if (ce) begin
            if (alarm_clear)
                in_window <= 1'b0;
            else if (alarm_arm)
                in_window <= 1'b1;

            if (tick) begin
                if (sec_left == {W{1'b0}})
                    sec_left <= SEC_LAST;
                else
                    sec_left <= sec_left - 16'd1;

                if (sec == SEC_LAST) begin
                    sec <= {W{1'b0}};
                    if (minute == MIN_LAST) begin
                        minute <= {W{1'b0}};
                        if (hour == HOUR_LAST) begin
                            hour <= {W{1'b0}};
                            if (day == DAY_LAST) begin
                                day <= 16'd1;
                                if (month == MONTH_LAST)
                                    month <= 16'd1;
                                else
                                    month <= month + 16'd1;
                            end else begin
                                day <= day + 16'd1;
                            end
                        end else begin
                            hour <= hour + 16'd1;
                        end
                    end else begin
                        minute <= minute + 16'd1;
                    end
                end else begin
                    sec <= sec + 16'd1;
                end
            end
        end
    end

    assign o_sec           = sec;
    assign o_min           = minute;
    assign o_hour          = hour;
    assign o_day           = day;
    assign o_month         = month;
    assign o_minute_strobe = (sec_left == {W{1'b0}});
    assign o_window        = in_window;

    // Absence, between arm and clear: start-of-minute and end-of-minute
    // are never flagged at the same time while the alarm window is open.
    always @(posedge clk)
        if (in_window)
            assert (!(sec == {W{1'b0}} && sec_left == {W{1'b0}}));
endmodule

module rename_table #(
    parameter NARCH = 4,
    parameter NPHYS = 8,
    parameter AW = $clog2(NARCH),
    parameter TW = $clog2(NPHYS),
    parameter CW = 16
) (
    input  wire          clk,
    input  wire          i_ce,
    input  wire          i_req,
    input  wire [AW-1:0] i_dst,
    output wire [TW-1:0] o_tag,
    output wire [CW-1:0] o_cnt
);
    typedef enum logic [1:0] {S_IDLE, S_ARM, S_START, S_FINISH} state_t;

    state_t state = S_IDLE;

    // rename map: architectural register -> physical tag
    reg [NARCH-1:0][TW-1:0] map_q;
    // free-tag list as a bit vector (1 = tag free)
    reg [NPHYS-1:0] free_vec = {NPHYS{1'b1}} << NARCH;
    reg [AW-1:0]    dst       = {AW{1'b0}};
    reg [TW-1:0]    alloc_tag = {TW{1'b0}};
    reg [CW-1:0]    rename_cnt = {CW{1'b0}};
    reg             seen_q    = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < NARCH; i = i + 1)
            map_q[i] = i;
    end

    // lowest free physical tag
    reg [TW-1:0] pick;
    integer k;
    always @(*) begin
        pick = {TW{1'b0}};
        for (k = NPHYS-1; k >= 0; k = k - 1)
            if (free_vec[k]) pick = k;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        dst    <= i_dst;
                        seen_q <= 1'b1;
                        state  <= S_ARM;
                    end
                end
                S_ARM: begin
                    if (free_vec != {NPHYS{1'b0}}) begin
                        alloc_tag      <= pick;
                        free_vec[pick] <= 1'b0;
                        state          <= S_START;
                    end
                end
                S_START: begin
                    map_q[dst]           <= alloc_tag;
                    free_vec[map_q[dst]] <= 1'b1;
                    state                <= S_FINISH;
                end
                S_FINISH: begin
                    rename_cnt <= rename_cnt + 1'b1;
                    state      <= S_IDLE;
                end
            endcase
        end
    end

    assign o_tag = alloc_tag;
    assign o_cnt = rename_cnt;

    // after the first accepted rename request: a finished rename must have
    // passed through allocation (tag taken off the free list)
    always @(posedge clk)
        if (seen_q && state == S_FINISH)
            assert (!free_vec[alloc_tag]);
endmodule

module thr_cross_det #(
    parameter W = 32,
    parameter [W-1:0] THR_INIT = 32'h8000_0000
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         i_load,
    input  wire [W-1:0] i_thr,
    input  wire [W-1:0] i_sample,
    output reg          o_xflag,
    output reg          o_xdir,
    output reg  [W-1:0] o_xcnt
);
    reg [W-1:0] thr;
    reg [W-1:0] prev;
    reg         have_prev;
    reg         seen_below;

    initial begin
        thr        = THR_INIT;
        prev       = {W{1'b0}};
        have_prev  = 1'b0;
        seen_below = 1'b0;
        o_xflag    = 1'b0;
        o_xdir     = 1'b0;
        o_xcnt     = {W{1'b0}};
    end

    wire s_below = (i_sample < thr);
    wire p_below = (prev < thr);
    wire cross   = have_prev && (s_below != p_below);

    always @(posedge clk) begin
        if (rst) begin
            thr        <= THR_INIT;
            prev       <= {W{1'b0}};
            have_prev  <= 1'b0;
            seen_below <= 1'b0;
            o_xflag    <= 1'b0;
            o_xdir     <= 1'b0;
            o_xcnt     <= {W{1'b0}};
        end else if (i_load) begin
            thr        <= i_thr;
            have_prev  <= 1'b0;
            seen_below <= 1'b0;
            o_xflag    <= 1'b0;
        end else if (i_ce) begin
            prev      <= i_sample;
            have_prev <= 1'b1;
            if (s_below)
                seen_below <= 1'b1;
            o_xflag <= cross;
            if (cross) begin
                o_xdir <= p_below;
                o_xcnt <= o_xcnt + 1'b1;
            end
        end
    end

    always @(*) assert (!(o_xflag && o_xdir) || seen_below);
endmodule

module mn_clken_gen #(
    parameter W = 64,
    parameter [W-1:0] M_DEF = 64'd3,
    parameter [W-1:0] N_DEF = 64'd8
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         step,
    input  wire         req,
    input  wire         cfg_load,
    input  wire [W-1:0] cfg_m,
    input  wire [W-1:0] cfg_n,
    output wire         ce_out,
    output wire         busy
);
    reg [W-1:0] m_r = M_DEF;
    reg [W-1:0] n_r = N_DEF;
    reg [W-1:0] err = {W{1'b0}};
    reg [W-1:0] cd  = {W{1'b0}};
    reg         armed = 1'b0;
    reg         timeout = 1'b0;

    wire [W:0]   sum  = {1'b0, err} + {1'b0, m_r};
    wire         hit  = (sum >= {1'b0, n_r});
    wire [W:0]   diff = sum - {1'b0, n_r};
    wire [W-1:0] err_nxt = step ? (hit ? diff[W-1:0] : sum[W-1:0]) : err;
    wire         cfg_ok = (cfg_n != {W{1'b0}}) && (cfg_m != {W{1'b0}}) && (cfg_m <= cfg_n);

    assign ce_out = step && hit;
    assign busy   = armed;

    always @(posedge clk) begin
        if (rst) begin
            m_r     <= M_DEF;
            n_r     <= N_DEF;
            err     <= {W{1'b0}};
            cd      <= {W{1'b0}};
            armed   <= 1'b0;
            timeout <= 1'b0;
        end else if (cfg_load && cfg_ok) begin
            m_r     <= cfg_m;
            n_r     <= cfg_n;
            err     <= {W{1'b0}};
            cd      <= {W{1'b0}};
            armed   <= 1'b0;
            timeout <= 1'b0;
        end else begin
            err <= err_nxt;
            if (!armed) begin
                if (req) begin
                    armed <= 1'b1;
                    cd    <= n_r - err_nxt;
                end
            end else if (step) begin
                if (hit)
                    armed <= 1'b0;
                else if (cd <= m_r)
                    timeout <= 1'b1;
                else
                    cd <= cd - m_r;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $stable(armed))
            assert ($stable(timeout));
endmodule

module oc_csum_acc #(
    parameter W = 32
) (
    input  wire         clk,
    input  wire         i_reset,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_data,
    input  wire         i_ce,
    output wire [W-1:0] o_csum
);
    reg [W-1:0] acc;
    reg [W-1:0] hold_data;
    reg         hold_valid;
    reg         seen_nz;
    reg         armed;
    initial acc = {W{1'b0}};
    initial hold_data = {W{1'b0}};
    initial hold_valid = 1'b0;
    initial seen_nz = 1'b0;
    initial armed = 1'b1;

    wire drain = i_ce && hold_valid;
    assign in_ready = !hold_valid || drain;
    wire accept = in_valid && in_ready;

    // end-around-carry (one's-complement) adder, purely combinational
    wire [W:0]   raw     = {1'b0, acc} + {1'b0, hold_data};
    wire         eac     = raw[W];
    wire [W-1:0] eac_sum = raw[W-1:0] + {{(W-1){1'b0}}, eac};

    always @(posedge clk) begin
        if (i_reset) begin
            acc        <= {W{1'b0}};
            hold_data  <= {W{1'b0}};
            hold_valid <= 1'b0;
            seen_nz    <= 1'b0;
            armed      <= 1'b1;
        end else begin
            if (drain) begin
                acc <= eac_sum;
                if (eac)
                    armed <= 1'b0;
            end
            if (accept) begin
                hold_data  <= in_data;
                hold_valid <= 1'b1;
                if (in_data != {W{1'b0}})
                    seen_nz <= 1'b1;
            end else if (drain) begin
                hold_valid <= 1'b0;
            end
        end
    end

    assign o_csum = ~acc;

    always @(*)
        assert (!armed || seen_nz || acc == {W{1'b0}});
endmodule

module burst_hold_arb #(
    parameter NREQ = 4,
    parameter LW   = 16,
    parameter OW   = 2
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            ce,
    input  wire [NREQ-1:0] req,
    input  wire [LW-1:0]   req_len,
    output wire [NREQ-1:0] gnt,
    output wire            busy,
    output wire            last_beat
);
    localparam [1:0] S_IDLE = 2'd0;
    localparam [1:0] S_ARM  = 2'd1;
    localparam [1:0] S_XFER = 2'd2;

    reg [1:0]    phase      = S_IDLE;
    reg [OW-1:0] owner      = {OW{1'b0}};
    reg [LW-1:0] beats      = {LW{1'b0}};
    reg          seen_grant = 1'b0;
    reg          pv         = 1'b0;

    reg [OW-1:0] winner;
    integer i;
    always @(*) begin
        winner = {OW{1'b0}};
        for (i = NREQ-1; i >= 0; i = i - 1)
            if (req[i]) winner = i;
    end

    wire [LW-1:0] eff_len = (req_len == {LW{1'b0}}) ? {{(LW-1){1'b0}}, 1'b1} : req_len;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase      <= S_IDLE;
            owner      <= {OW{1'b0}};
            beats      <= {LW{1'b0}};
            seen_grant <= 1'b0;
        end else if (ce) begin
            case (phase)
                S_IDLE: begin
                    if (|req) begin
                        owner      <= winner;
                        beats      <= eff_len;
                        phase      <= S_ARM;
                        seen_grant <= 1'b1;
                    end
                end
                S_ARM: begin
                    phase <= S_XFER;
                end
                S_XFER: begin
                    beats <= beats - {{(LW-1){1'b0}}, 1'b1};
                    if (beats == {{(LW-1){1'b0}}, 1'b1})
                        phase <= S_IDLE;
                end
                default: begin
                    phase <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    assign gnt       = (phase == S_XFER) ? ({{(NREQ-1){1'b0}}, 1'b1} << owner) : {NREQ{1'b0}};
    assign busy      = (phase != S_IDLE);
    assign last_beat = (phase == S_XFER) && (beats == {{(LW-1){1'b0}}, 1'b1});

    always @(posedge clk)
        if (pv && seen_grant && $stable(beats))
            assert ($stable(owner));
endmodule

module morse_decoder #(
    parameter SRW = 8,
    parameter [7:0] MAXSYM = 8'd7,
    parameter [7:0] DOT_MAX = 8'd3,
    parameter [7:0] CHAR_GAP = 8'd5
) (
    input wire clk,
    input wire rst,
    input wire step,
    input wire key,
    output reg [SRW-1:0] char_code,
    output reg [7:0] char_len,
    output reg char_valid
);
    typedef enum logic [1:0] {IDLE = 2'd0, MARK = 2'd1, SPACE = 2'd2} state_t;
    state_t state;
    reg [7:0] dur;
    reg [SRW-1:0] sym_sr;
    reg [7:0] sym_cnt;
    reg armed;

    initial begin
        state = IDLE;
        dur = 8'd0;
        sym_sr = {{(SRW-1){1'b0}}, 1'b1};
        sym_cnt = 8'd0;
        armed = 1'b0;
        char_code = {SRW{1'b0}};
        char_len = 8'd0;
        char_valid = 1'b0;
    end

    wire is_dash = (dur > DOT_MAX);
    wire [7:0] dur_inc = (dur == 8'hFF) ? dur : (dur + 8'd1);

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            dur <= 8'd0;
            sym_sr <= {{(SRW-1){1'b0}}, 1'b1};
            sym_cnt <= 8'd0;
            armed <= 1'b0;
            char_code <= {SRW{1'b0}};
            char_len <= 8'd0;
            char_valid <= 1'b0;
        end else if (step) begin
            char_valid <= 1'b0;
            case (state)
                IDLE: begin
                    if (key) begin
                        state <= MARK;
                        dur <= 8'd1;
                    end
                end
                MARK: begin
                    if (key) begin
                        dur <= dur_inc;
                    end else begin
                        if (sym_cnt < MAXSYM) begin
                            sym_sr <= {sym_sr[SRW-2:0], is_dash};
                            sym_cnt <= sym_cnt + 8'd1;
                        end
                        armed <= 1'b1;
                        state <= SPACE;
                        dur <= 8'd1;
                    end
                end
                SPACE: begin
                    if (key) begin
                        state <= MARK;
                        dur <= 8'd1;
                    end else if (dur_inc >= CHAR_GAP) begin
                        char_code <= sym_sr;
                        char_len <= sym_cnt;
                        char_valid <= 1'b1;
                        sym_sr <= {{(SRW-1){1'b0}}, 1'b1};
                        sym_cnt <= 8'd0;
                        armed <= 1'b0;
                        state <= IDLE;
                        dur <= 8'd0;
                    end else begin
                        dur <= dur_inc;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    // Scope: after a symbol is accepted (armed set) until the character is emitted (armed cleared)
    always @(posedge clk)
        if (armed)
            assert (sym_sr != {{(SRW-1){1'b0}}, 1'b1});

    always @(posedge clk)
        if (armed && sym_cnt < MAXSYM)
            assert (sym_sr[SRW-1] == 1'b0);
endmodule

module sqrt_restoring #(
    parameter W  = 128,
    parameter SW = 7
) (
    input  wire           clk,
    input  wire           rst,
    input  wire           ce,
    input  wire           start,
    input  wire [W-1:0]   radicand,
    output wire [W/2-1:0] root,
    output wire           busy,
    output wire           done
);
    typedef enum logic [1:0] {IDLE = 2'd0, BUSY = 2'd1, DONE = 2'd2} state_t;

    localparam [W-1:0]  TOP   = {2'b01, {(W-2){1'b0}}};
    localparam [SW-1:0] STEPS = W / 2;

    state_t        state;
    reg [W-1:0]    rem;
    reg [W-1:0]    res;
    reg [W-1:0]    bit_r;
    reg [SW-1:0]   step;

    initial begin
        state = IDLE;
        rem   = {W{1'b0}};
        res   = {W{1'b0}};
        bit_r = TOP;
        step  = {SW{1'b0}};
    end

    wire [W-1:0] trial = res + bit_r;
    wire         fits  = (rem >= trial);

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            rem   <= {W{1'b0}};
            res   <= {W{1'b0}};
            bit_r <= TOP;
            step  <= {SW{1'b0}};
        end else if (ce) begin
            case (state)
                IDLE, DONE: begin
                    if (start) begin
                        state <= BUSY;
                        rem   <= radicand;
                        res   <= {W{1'b0}};
                        bit_r <= TOP;
                        step  <= {SW{1'b0}};
                    end
                end
                BUSY: begin
                    if (bit_r == {W{1'b0}}) begin
                        state <= DONE;
                    end else begin
                        if (fits) begin
                            rem <= rem - trial;
                            res <= (res >> 1) + bit_r;
                        end else begin
                            res <= res >> 1;
                        end
                        bit_r <= bit_r >> 2;
                        step  <= step + 1'b1;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    assign root = res[W/2-1:0];
    assign busy = (state == BUSY);
    assign done = (state == DONE);

    always @(*) assert (step <= STEPS);
endmodule

module atpg_pattern_buf #(
    parameter W = 128,
    parameter DEPTH = 24
) (
    input  wire                           clk,
    input  wire                           rst,
    input  wire                           in_valid,
    output wire                           in_ready,
    input  wire [W-1:0]                   in_data,
    output wire                           out_valid,
    input  wire                           out_ready,
    output wire [W-1:0]                   out_data,
    input  wire                           load_limit,
    input  wire [$clog2(DEPTH+1)-1:0]     limit_in
);
    localparam CW = $clog2(DEPTH+1);
    localparam PW = $clog2(DEPTH);

    // occupancy held in a DICE-style quadruple of interlocked storage nodes
    reg [CW-1:0] n0, n1, n2, n3;
    reg [CW-1:0] limit;
    reg [PW-1:0] wptr, rptr;
    reg          armed;
    reg [W-1:0]  mem [0:DEPTH-1];

    integer i;
    initial begin
        n0 = 0; n1 = 0; n2 = 0; n3 = 0;
        limit = DEPTH;
        wptr = 0; rptr = 0;
        armed = 1'b0;
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = {W{1'b0}};
    end

    // interlock restoration: a node is overridden when its two neighbours agree
    wire [CW-1:0] b0 = (n1 == n3) ? n1 : n0;
    wire [CW-1:0] b1 = (n2 == n0) ? n2 : n1;
    wire [CW-1:0] b2 = (n3 == n1) ? n3 : n2;
    wire [CW-1:0] b3 = (n0 == n2) ? n0 : n3;

    wire [CW-1:0] cap = (limit > DEPTH) ? DEPTH[CW-1:0] : limit;

    assign in_ready  = (n0 < cap);
    assign out_valid = (n0 != {CW{1'b0}});
    assign out_data  = mem[rptr];

    wire do_push = in_valid && in_ready;
    wire do_pop  = out_valid && out_ready;

    wire [PW-1:0] wptr_nx = (wptr == DEPTH-1) ? {PW{1'b0}} : wptr + 1'b1;
    wire [PW-1:0] rptr_nx = (rptr == DEPTH-1) ? {PW{1'b0}} : rptr + 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            n0 <= 0; n1 <= 0; n2 <= 0; n3 <= 0;
            wptr <= 0; rptr <= 0;
            limit <= limit_in;
        end else begin
            if (load_limit) limit <= limit_in;
            if (do_push) begin
                mem[wptr] <= in_data;
                wptr <= wptr_nx;
            end
            if (do_pop) rptr <= rptr_nx;
            if (do_push != do_pop) begin
                n0 <= do_push ? b0 + 1'b1 : b0 - 1'b1;
                n1 <= do_push ? b1 + 1'b1 : b1 - 1'b1;
                n2 <= do_push ? b2 + 1'b1 : b2 - 1'b1;
                n3 <= do_push ? b3 + 1'b1 : b3 - 1'b1;
            end
        end
    end

    // sticky scope: armed by the first accepted pattern, never cleared
    always @(posedge clk)
        if (do_push) armed <= 1'b1;

    assert property (!armed || n0 <= DEPTH);
endmodule

module usb_stream_writer (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire start,
    input wire ack,
    input wire s_valid,
    input wire s_last,
    input wire [31:0] s_data,
    input wire trig_arm,
    input wire trig_disarm,
    output wire busy,
    output wire full,
    output wire [31:0] o_pkt_len,
    output wire o_eop
);
    parameter DEPTH = 16;
    parameter AW = 4;
    parameter DW = 32;

    typedef enum logic [1:0] {IDLE = 2'd0, CAPTURE = 2'd1, DONE = 2'd2} state_t;

    state_t state = IDLE;
    reg [AW-1:0] wr_ptr = {AW{1'b0}};
    reg [DW-1:0] byte_cnt = {DW{1'b0}};
    reg [DW-1:0] pkt_len = {DW{1'b0}};
    reg eop = 1'b0;
    reg win = 1'b0;
    reg [DW-1:0] mem [0:DEPTH-1];
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = {DW{1'b0}};
    end

    assign busy = (state == CAPTURE);
    assign full = (byte_cnt == DEPTH);
    assign o_pkt_len = pkt_len;
    assign o_eop = eop;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            wr_ptr <= {AW{1'b0}};
            byte_cnt <= {DW{1'b0}};
            pkt_len <= {DW{1'b0}};
            eop <= 1'b0;
            win <= 1'b0;
        end else if (ce) begin
            if (trig_arm)
                win <= 1'b1;
            else if (trig_disarm)
                win <= 1'b0;
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= CAPTURE;
                        wr_ptr <= {AW{1'b0}};
                        byte_cnt <= {DW{1'b0}};
                        eop <= 1'b0;
                    end
                end
                CAPTURE: begin
                    if (s_valid) begin
                        mem[wr_ptr] <= s_data;
                        wr_ptr <= wr_ptr + 1'b1;
                        byte_cnt <= byte_cnt + 1;
                        if (s_last || (wr_ptr == DEPTH-1)) begin
                            state <= DONE;
                            pkt_len <= byte_cnt + 1;
                            eop <= s_last;
                        end
                    end
                end
                DONE: begin
                    if (ack)
                        state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

    always @(*)
        if (win) assert (!(busy && full));
endmodule

module karatsuba_mul_hs #(
    parameter WIDTH = 16
) (
    input  wire               clk,
    input  wire               rst_n,
    input  wire               in_valid,
    output wire               in_ready,
    input  wire [WIDTH-1:0]   in_a,
    input  wire [WIDTH-1:0]   in_b,
    output wire               out_valid,
    input  wire               out_ready,
    output wire [2*WIDTH-1:0] out_prod
);
    localparam HALF = WIDTH / 2;
    localparam [15:0] LAT = 16'd4;

    reg               busy = 1'b0;
    reg [15:0]        cnt  = 16'd0;
    reg [3:0]         done = 4'b0000;
    reg [WIDTH-1:0]   a_q  = {WIDTH{1'b0}};
    reg [WIDTH-1:0]   b_q  = {WIDTH{1'b0}};
    reg [WIDTH-1:0]   z0   = {WIDTH{1'b0}};
    reg [WIDTH-1:0]   z2   = {WIDTH{1'b0}};
    reg [WIDTH+1:0]   z1   = {(WIDTH+2){1'b0}};
    reg [2*WIDTH-1:0] prod = {(2*WIDTH){1'b0}};

    wire [HALF-1:0] a_lo = a_q[HALF-1:0];
    wire [HALF-1:0] a_hi = a_q[WIDTH-1:HALF];
    wire [HALF-1:0] b_lo = b_q[HALF-1:0];
    wire [HALF-1:0] b_hi = b_q[WIDTH-1:HALF];
    wire [HALF:0]   a_sum = {1'b0, a_lo} + {1'b0, a_hi};
    wire [HALF:0]   b_sum = {1'b0, b_lo} + {1'b0, b_hi};

    wire [2*WIDTH-1:0] z0_w  = {{WIDTH{1'b0}}, z0};
    wire [2*WIDTH-1:0] z2_w  = {{WIDTH{1'b0}}, z2};
    wire [2*WIDTH-1:0] z1_w  = {{(WIDTH-2){1'b0}}, z1};
    wire [2*WIDTH-1:0] mid_w = z1_w - z2_w - z0_w;

    assign in_ready  = !busy;
    assign out_valid = done[3];
    assign out_prod  = prod;

    wire adv = busy && !done[3] && out_ready;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy <= 1'b0;
            cnt  <= 16'd0;
            done <= 4'b0000;
            a_q  <= {WIDTH{1'b0}};
            b_q  <= {WIDTH{1'b0}};
            z0   <= {WIDTH{1'b0}};
            z2   <= {WIDTH{1'b0}};
            z1   <= {(WIDTH+2){1'b0}};
            prod <= {(2*WIDTH){1'b0}};
        end else if (in_valid && in_ready) begin
            a_q  <= in_a;
            b_q  <= in_b;
            busy <= 1'b1;
            cnt  <= LAT;
            done <= 4'b0000;
        end else if (adv) begin
            cnt  <= cnt - 16'd1;
            done <= {done[2:0], 1'b1};
            if (!done[0])
                z0 <= a_lo * b_lo;
            else if (!done[1])
                z2 <= a_hi * b_hi;
            else if (!done[2])
                z1 <= a_sum * b_sum;
            else
                prod <= (z2_w << WIDTH) + (mid_w << HALF) + z0_w;
        end else if (out_valid && out_ready) begin
            busy <= 1'b0;
            cnt  <= 16'd0;
            done <= 4'b0000;
        end
    end

    // Bounded response: the countdown never expires while the request is outstanding
    always @(posedge clk)
        if (busy && cnt == 16'd0)
            assert (out_valid);

    // Completion only when the countdown has fully run out
    always @(posedge clk)
        if (busy && out_valid)
            assert (cnt == 16'd0);
endmodule

module ps2_frame_rx #(
    parameter W = 128
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         in_valid,
    input  wire         in_bit,
    output wire         in_ready,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] code
);
    localparam CW = $clog2(W);

    reg [W-1:0]  shreg;
    reg [CW-1:0] bitcnt;
    reg          armed;

    initial shreg     = {W{1'b0}};
    initial bitcnt    = {CW{1'b0}};
    initial code      = {W{1'b0}};
    initial out_valid = 1'b0;
    initial armed     = 1'b1;

    assign in_ready = !out_valid;

    wire take = in_valid && in_ready;

    always @(posedge clk) begin
        if (rst) begin
            shreg     <= {W{1'b0}};
            bitcnt    <= {CW{1'b0}};
            code      <= {W{1'b0}};
            out_valid <= 1'b0;
        end else begin
            if (out_valid && out_ready)
                out_valid <= 1'b0;
            if (take) begin
                if (bitcnt == W-1) begin
                    code      <= {in_bit, shreg[W-1:1]};
                    out_valid <= 1'b1;
                    shreg     <= {W{1'b0}};
                    bitcnt    <= {CW{1'b0}};
                end else begin
                    shreg  <= {in_bit, shreg[W-1:1]};
                    bitcnt <= bitcnt + 1'b1;
                end
            end
            if (take && in_bit)
                armed <= 1'b0;
        end
    end

    always @(posedge clk)
        if (armed) assert (code == {W{1'b0}});
endmodule

module btb_vec #(
    parameter NUM_ENTRIES = 12,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         upd_taken,
    input  wire         upd_nottaken,
    input  wire [W-1:0] upd_pc,
    input  wire [W-1:0] upd_target,
    input  wire [W-1:0] lookup_pc,
    output wire         hit,
    output wire [W-1:0] pred_target,
    output wire         full
);
    localparam [3:0] NE4 = NUM_ENTRIES;

    reg [NUM_ENTRIES-1:0]   valid;
    reg [NUM_ENTRIES*W-1:0] tag_flat;
    reg [NUM_ENTRIES*W-1:0] tgt_flat;
    reg [31:0]              n_valid;

    initial begin
        valid    = {NUM_ENTRIES{1'b0}};
        tag_flat = {(NUM_ENTRIES*W){1'b0}};
        tgt_flat = {(NUM_ENTRIES*W){1'b0}};
        n_valid  = 32'd0;
    end

    wire [3:0] u_raw = upd_pc[5:2];
    wire [3:0] uidx  = (u_raw >= NE4) ? (u_raw - NE4) : u_raw;
    wire [3:0] l_raw = lookup_pc[5:2];
    wire [3:0] lidx  = (l_raw >= NE4) ? (l_raw - NE4) : l_raw;

    wire [W-1:0] u_tag = tag_flat[uidx*W +: W];
    wire [W-1:0] l_tag = tag_flat[lidx*W +: W];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid    <= {NUM_ENTRIES{1'b0}};
            tag_flat <= {(NUM_ENTRIES*W){1'b0}};
            tgt_flat <= {(NUM_ENTRIES*W){1'b0}};
            n_valid  <= 32'd0;
        end else if (upd_taken) begin
            tag_flat[uidx*W +: W] <= upd_pc;
            tgt_flat[uidx*W +: W] <= upd_target;
            valid[uidx] <= 1'b1;
            if (!valid[uidx])
                n_valid <= n_valid + 32'd1;
        end else if (upd_nottaken) begin
            if (valid[uidx] && (u_tag == upd_pc)) begin
                valid[uidx] <= 1'b0;
                n_valid <= n_valid - 32'd1;
            end
        end
    end

    assign hit         = valid[lidx] && (l_tag == lookup_pc);
    assign pred_target = tgt_flat[lidx*W +: W];
    assign full        = (n_valid == NUM_ENTRIES);

    always @(posedge clk)
        if ($rose(full))
            assert (&valid);
endmodule

module i2c_arb_monitor #(
    parameter FRAME_BITS = 8
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire        stop,
    input  wire        drv_bit,
    input  wire        sda_in,
    output reg         lost,
    output reg  [31:0] lost_pos,
    output reg         last_drv
);
    localparam [31:0] FRAME = FRAME_BITS;

    reg        busy    = 1'b0;
    reg [31:0] bit_cnt = 32'd0;
    reg        win     = 1'b0;
    reg [31:0] sh_cnt  = 32'd0;

    initial begin
        lost     = 1'b0;
        lost_pos = 32'd0;
        last_drv = 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            busy     <= 1'b0;
            bit_cnt  <= 32'd0;
            lost     <= 1'b0;
            lost_pos <= 32'd0;
            last_drv <= 1'b1;
            win      <= 1'b0;
            sh_cnt   <= 32'd0;
        end else if (ce) begin
            if (stop) begin
                busy <= 1'b0;
                win  <= 1'b0;
            end else if (start && !busy) begin
                busy     <= 1'b1;
                bit_cnt  <= 32'd0;
                lost     <= 1'b0;
                lost_pos <= 32'd0;
                last_drv <= 1'b1;
                win      <= 1'b0;
                sh_cnt   <= 32'd0;
            end else if (busy) begin
                last_drv <= lost ? 1'b1 : drv_bit;
                if (!lost && drv_bit && !sda_in) begin
                    lost     <= 1'b1;
                    lost_pos <= bit_cnt;
                    win      <= 1'b1;
                    sh_cnt   <= 32'd0;
                end else if (win) begin
                    sh_cnt <= sh_cnt + 32'd1;
                end
                bit_cnt <= bit_cnt + 32'd1;
                if (bit_cnt == FRAME - 32'd1)
                    busy <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (win) assert (lost_pos < bit_cnt);

    always @(posedge clk)
        if (win) assert (sh_cnt < bit_cnt);
endmodule

module desc_own_table #(
    parameter DEPTH = 8,
    parameter AW = 3,
    parameter DW = 32
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          ce,
    input  wire          we,
    input  wire [AW-1:0] waddr,
    input  wire [DW-1:0] wdata,
    input  wire          dma_take,
    input  wire          adv,
    input  wire          start,
    input  wire          stop,
    output wire [DW-1:0] rdata,
    output wire          cpu_own,
    output wire          dma_own
);
    // asynchronous-read distributed descriptor RAM
    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] ptr = {AW{1'b0}};
    reg armed = 1'b0;
    integer i;

    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = {DW{1'b0}};
    end

    // combinational read of the word addressed by the DMA fetch pointer
    assign rdata   = mem[ptr];
    assign cpu_own = rdata[0];
    assign dma_own = rdata[1];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < DEPTH; i = i + 1)
                mem[i] <= {DW{1'b0}};
            ptr   <= {AW{1'b0}};
            armed <= 1'b0;
        end else if (ce) begin
            if (we)
                // CPU write: CPU ownership bit wins, DMA bit is cleared if CPU claims
                mem[waddr] <= {wdata[DW-1:2], wdata[1] & ~wdata[0], wdata[0]};
            else if (dma_take && !rdata[0])
                // DMA claims the fetched descriptor only if CPU does not own it
                mem[ptr] <= {rdata[DW-1:2], 2'b10};
            if (adv)
                ptr <= ptr + 1'b1;
            if (start)
                armed <= 1'b1;
            else if (stop)
                armed <= 1'b0;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pv <= 1'b0;
        else
            pv <= 1'b1;
    end

    // after start until stop: the fetched descriptor never has two owners
    always @(posedge clk)
        if (pv && $past(armed))
            assert (!($past(cpu_own) && $past(dma_own)));
endmodule

module axi_w_upsizer #(
    parameter NW    = 16,
    parameter LANES = 16,
    parameter LW    = 4,
    parameter SW    = 2*LANES
) (
    input  wire              clk,
    input  wire              rst,
    input  wire              i_awvalid,
    output wire              o_awready,
    input  wire [15:0]       i_awlen,
    input  wire [2:0]        i_awsize,
    input  wire              i_wvalid,
    output wire              o_wready,
    input  wire [NW-1:0]     i_wdata,
    output wire              o_wvalid,
    input  wire              i_wready,
    output wire [NW*LANES-1:0] o_wdata,
    output wire [SW-1:0]     o_wstrb,
    output wire              o_wlast,
    output wire [2:0]        o_cap_size,
    output wire [15:0]       o_beats_left
);
    localparam [1:0] P_IDLE = 2'd0, P_ARMED = 2'd1, P_PACK = 2'd2, P_OUT = 2'd3;

    reg [1:0]          phase      = P_IDLE;
    reg                aw_seen    = 1'b0;
    reg [LW-1:0]       lane       = {LW{1'b0}};
    reg [SW-1:0]       strb       = {SW{1'b0}};
    reg [NW*LANES-1:0] pbuf       = {(NW*LANES){1'b0}};
    reg [15:0]         beats_left = 16'd0;
    reg [2:0]          cap_size   = 3'd0;
    reg                last_q     = 1'b0;

    assign o_awready    = (phase == P_IDLE);
    assign o_wready     = (phase == P_ARMED) || (phase == P_PACK);
    assign o_wvalid     = (phase == P_OUT);
    assign o_wdata      = pbuf;
    assign o_wstrb      = strb;
    assign o_wlast      = last_q;
    assign o_cap_size   = cap_size;
    assign o_beats_left = beats_left;

    wire aw_hs  = i_awvalid && o_awready;
    wire w_hs   = i_wvalid  && o_wready;
    wire out_hs = o_wvalid  && i_wready;

    wire          end_wide  = (lane == LANES-1) || (beats_left == 16'd0);
    wire [SW-1:0] lane_strb = {{(SW-2){1'b0}}, 2'b11} << {lane, 1'b0};

    always @(posedge clk) begin
        if (rst) begin
            phase      <= P_IDLE;
            aw_seen    <= 1'b0;
            lane       <= {LW{1'b0}};
            strb       <= {SW{1'b0}};
            pbuf       <= {(NW*LANES){1'b0}};
            beats_left <= 16'd0;
            cap_size   <= 3'd0;
            last_q     <= 1'b0;
        end else begin
            if (aw_hs) begin
                phase      <= P_ARMED;
                aw_seen    <= 1'b1;
                beats_left <= i_awlen;
                cap_size   <= i_awsize;
                lane       <= {LW{1'b0}};
                strb       <= {SW{1'b0}};
            end
            if (w_hs) begin
                pbuf[lane*NW +: NW] <= i_wdata;
                strb <= strb | lane_strb;
                if (end_wide) begin
                    phase  <= P_OUT;
                    last_q <= (beats_left == 16'd0);
                end else begin
                    phase <= P_PACK;
                    lane  <= lane + 1'b1;
                end
                if (beats_left != 16'd0)
                    beats_left <= beats_left - 16'd1;
            end
            if (out_hs) begin
                strb <= {SW{1'b0}};
                lane <= {LW{1'b0}};
                pbuf <= {(NW*LANES){1'b0}};
                if (last_q) begin
                    phase   <= P_IDLE;
                    aw_seen <= 1'b0;
                    last_q  <= 1'b0;
                end else begin
                    phase <= P_PACK;
                end
            end
        end
    end

    // chain precedence: a wide beat (finish) is never offered unless the
    // address was captured (arm) and the first lane was packed (start)
    assert property (!o_wvalid || (aw_seen && strb[1:0] == 2'b11));
endmodule

module adc_scan_mux #(
    parameter N_CH = 16,
    parameter [63:0] SETTLE_CYC = 64'd6
) (
    input  wire                     clk,
    input  wire                     rst,
    input  wire                     cfg_we,
    input  wire [$clog2(N_CH)-1:0]  cfg_addr,
    input  wire [63:0]              cfg_data,
    input  wire                     start_valid,
    output wire                     start_ready,
    input  wire [$clog2(N_CH)-1:0]  start_last,
    input  wire                     tick,
    output wire                     out_valid,
    input  wire                     out_ready,
    output wire [63:0]              out_chan,
    output wire [$clog2(N_CH)-1:0]  out_idx
);
    localparam IDXW = $clog2(N_CH);

    typedef enum logic [1:0] {S_IDLE = 2'd0, S_SETTLE = 2'd1, S_OUT = 2'd2} state_t;

    state_t state;
    reg [63:0] chan_mem [0:N_CH-1];
    reg [IDXW-1:0] idx;
    reg [IDXW-1:0] last_idx;
    reg [63:0] settle;
    reg [63:0] deadline;
    reg win;

    integer i;
    initial begin
        state = S_IDLE;
        idx = {IDXW{1'b0}};
        last_idx = {IDXW{1'b0}};
        settle = SETTLE_CYC;
        deadline = SETTLE_CYC + 64'd1;
        win = 1'b0;
        for (i = 0; i < N_CH; i = i + 1) chan_mem[i] = i;
    end

    assign start_ready = (state == S_IDLE);
    assign out_valid   = (state == S_OUT);
    assign out_chan    = chan_mem[idx];
    assign out_idx     = idx;

    // channel-list memory: CSR-style programming only while idle
    always @(posedge clk) begin
        if (!rst && cfg_we && state == S_IDLE)
            chan_mem[cfg_addr] <= cfg_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            idx      <= {IDXW{1'b0}};
            last_idx <= {IDXW{1'b0}};
            settle   <= SETTLE_CYC;
            deadline <= SETTLE_CYC + 64'd1;
            win      <= 1'b0;
        end else begin
            case (state)
                S_IDLE: begin
                    if (start_valid) begin
                        last_idx <= start_last;
                        idx      <= {IDXW{1'b0}};
                        settle   <= SETTLE_CYC;
                        deadline <= SETTLE_CYC + 64'd1;
                        state    <= S_SETTLE;
                        win      <= 1'b1;
                    end
                end
                S_SETTLE: begin
                    if (tick) begin
                        if (settle == 64'd0) begin
                            state <= S_OUT;
                        end else begin
                            settle   <= settle - 64'd1;
                            deadline <= deadline - 64'd1;
                        end
                    end
                end
                S_OUT: begin
                    if (out_ready) begin
                        if (idx == last_idx) begin
                            state <= S_IDLE;
                            win   <= 1'b0;
                        end else begin
                            idx      <= idx + 1'b1;
                            settle   <= SETTLE_CYC;
                            deadline <= SETTLE_CYC + 64'd1;
                            state    <= S_SETTLE;
                        end
                    end
                end
                default: state <= S_IDLE;
            endcase
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // bounded response: a settle step taken inside the scan window never expires the deadline
    always @(posedge clk)
        if (pv && $past(win) && $past(state) == S_SETTLE && $past(tick))
            assert (deadline != 64'd0);
endmodule

module pkt_framer #(
    parameter W = 16,
    parameter DEPTH = 16
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         i_start,
    input  wire [W-1:0] i_len,
    input  wire [W-1:0] i_data,
    output reg  [W-1:0] o_word,
    output reg          o_sof,
    output reg          o_eof
);
    localparam [W-1:0] MAX_LEN    = DEPTH;
    localparam [W-1:0] START_DELIM = 16'hA5A5;
    localparam [W-1:0] END_DELIM   = 16'h5A5A;
    localparam [1:0] S_IDLE = 2'd0, S_HDR = 2'd1, S_PAY = 2'd2, S_TRL = 2'd3;

    reg [1:0]   frame_state = S_IDLE;
    reg [W-1:0] byte_cnt    = {W{1'b0}};
    reg [W-1:0] len_reg     = {{(W-1){1'b0}}, 1'b1};
    reg         armed       = 1'b0;
    reg         pv          = 1'b0;
    initial o_word = {W{1'b0}};
    initial o_sof  = 1'b0;
    initial o_eof  = 1'b0;

    wire [W-1:0] len_clamped = (i_len == {W{1'b0}}) ? {{(W-1){1'b0}}, 1'b1} :
                               ((i_len > MAX_LEN) ? MAX_LEN : i_len);
    wire over_lim = (byte_cnt > MAX_LEN);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            frame_state <= S_IDLE;
            byte_cnt    <= {W{1'b0}};
            len_reg     <= {{(W-1){1'b0}}, 1'b1};
            o_word      <= {W{1'b0}};
            o_sof       <= 1'b0;
            o_eof       <= 1'b0;
        end else if (i_ce) begin
            case (frame_state)
                S_IDLE: begin
                    o_sof <= 1'b0;
                    o_eof <= 1'b0;
                    if (i_start) begin
                        len_reg     <= len_clamped;
                        o_word      <= START_DELIM;
                        o_sof       <= 1'b1;
                        armed       <= 1'b1;
                        frame_state <= S_HDR;
                    end
                end
                S_HDR: begin
                    o_sof       <= 1'b0;
                    o_word      <= len_reg;
                    byte_cnt    <= {W{1'b0}};
                    frame_state <= S_PAY;
                end
                S_PAY: begin
                    o_word <= i_data;
                    if (byte_cnt == len_reg - 1'b1) begin
                        byte_cnt    <= {W{1'b0}};
                        frame_state <= S_TRL;
                    end else begin
                        byte_cnt <= byte_cnt + 1'b1;
                    end
                end
                S_TRL: begin
                    o_word      <= END_DELIM;
                    o_eof       <= 1'b1;
                    frame_state <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (pv && armed && $stable(frame_state))
            assert ($stable(over_lim));
endmodule

module search_fifo #(
    parameter DEPTH = 32,
    parameter DW = 16,
    parameter AW = $clog2(DEPTH)
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            in_valid,
    output wire            in_ready,
    input  wire [DW-1:0]   in_data,
    output wire            out_valid,
    input  wire            out_ready,
    output wire [DW-1:0]   out_data,
    input  wire            srch_valid,
    output wire            srch_ready,
    input  wire [DW-1:0]   srch_key,
    output wire            srch_present,
    output wire [DEPTH-1:0] srch_vec,
    output wire            res_valid,
    input  wire            res_ready,
    output wire [AW-1:0]   res_pos,
    output wire            res_hit,
    output wire            res_last,
    input  wire            cfg_we,
    input  wire [15:0]     cfg_timeout
);
    localparam [15:0] DEPTH16 = DEPTH;

    reg [DEPTH*DW-1:0] mem;
    reg [DEPTH-1:0]    vld;
    reg [AW-1:0]       head, tail;
    reg [15:0]         count;
    reg                busy;
    reg [DW-1:0]       key_q;
    reg [AW-1:0]       scan_idx;
    reg [15:0]         scan_left;
    reg [15:0]         timer;
    reg [15:0]         timeout_q;
    reg                armed;

    initial begin
        mem = {(DEPTH*DW){1'b0}};
        vld = {DEPTH{1'b0}};
        head = {AW{1'b0}};
        tail = {AW{1'b0}};
        count = 16'd0;
        busy = 1'b0;
        key_q = {DW{1'b0}};
        scan_idx = {AW{1'b0}};
        scan_left = 16'd0;
        timer = 16'd0;
        timeout_q = DEPTH16;
        armed = 1'b1;
    end

    assign in_ready   = (count != DEPTH16) && !busy;
    assign out_valid  = (count != 16'd0);
    assign out_data   = mem[head*DW +: DW];
    assign srch_ready = !busy;
    assign res_valid  = busy;
    assign res_pos    = scan_idx;
    assign res_hit    = vld[scan_idx] && (mem[scan_idx*DW +: DW] == key_q);
    assign res_last   = (scan_left == 16'd1);

    genvar gi;
    generate
        for (gi = 0; gi < DEPTH; gi = gi + 1) begin : g_cmp
            assign srch_vec[gi] = vld[gi] && (mem[gi*DW +: DW] == srch_key);
        end
    endgenerate
    assign srch_present = |srch_vec;

    wire push_fire = in_valid && in_ready;
    wire pop_fire  = out_valid && out_ready;
    wire srch_fire = srch_valid && srch_ready;
    wire res_fire  = res_valid && res_ready;
    wire cfg_fire  = cfg_we && !busy;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mem <= {(DEPTH*DW){1'b0}};
            vld <= {DEPTH{1'b0}};
            head <= {AW{1'b0}};
            tail <= {AW{1'b0}};
            count <= 16'd0;
            busy <= 1'b0;
            key_q <= {DW{1'b0}};
            scan_idx <= {AW{1'b0}};
            scan_left <= 16'd0;
            timer <= 16'd0;
            timeout_q <= DEPTH16;
            armed <= 1'b1;
        end else begin
            if (push_fire) begin
                mem[tail*DW +: DW] <= in_data;
                vld[tail] <= 1'b1;
                tail <= tail + 1'b1;
            end
            if (pop_fire) begin
                vld[head] <= 1'b0;
                head <= head + 1'b1;
            end
            case ({push_fire, pop_fire})
                2'b10: count <= count + 16'd1;
                2'b01: count <= count - 16'd1;
                default: ;
            endcase

            if (srch_fire) begin
                key_q     <= srch_key;
                scan_idx  <= head;
                scan_left <= count;
                timer     <= timeout_q;
                busy      <= (count != 16'd0);
            end else if (res_fire) begin
                scan_idx  <= scan_idx + 1'b1;
                scan_left <= scan_left - 16'd1;
                if (timer != 16'd0)
                    timer <= timer - 16'd1;
                if (scan_left == 16'd1)
                    busy <= 1'b0;
            end

            if (cfg_fire) begin
                timeout_q <= cfg_timeout;
                armed     <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (armed && busy)
            assert (timer != 16'd0);
endmodule

module agu_burst #(
    parameter AW     = 32,
    parameter BURST  = 8,
    parameter STRIDE = 4
) (
    input  wire          clk,
    input  wire          rst,
    input  wire          ce,
    input  wire          start,
    input  wire          pre_inc,
    input  wire [AW-1:0] base_in,
    input  wire [AW-1:0] index_in,
    input  wire [AW-1:0] disp_in,
    input  wire [1:0]    scale_in,
    output wire [AW-1:0] ea,
    output wire          fault
);
    typedef enum logic [1:0] {IDLE = 2'd0, RUN = 2'd1, DONE = 2'd2} state_t;

    state_t state = IDLE;
    reg [AW-1:0] base_r = {AW{1'b0}};
    reg [AW-1:0] end_r  = {AW{1'b0}};
    reg [AW-1:0] ea_r   = {AW{1'b0}};
    reg [AW-1:0] beats  = {AW{1'b0}};
    reg          fault_r = 1'b0;
    reg          armed   = 1'b1;

    wire [AW-1:0] step_base = base_r + STRIDE;
    wire [AW-1:0] scaled_ix = index_in << scale_in;
    wire [AW-1:0] ea_next   = (pre_inc ? step_base : base_r) + scaled_ix + disp_in;
    wire          misaligned = |ea_next[1:0];

    always @(posedge clk) begin
        if (rst) begin
            state   <= IDLE;
            base_r  <= {AW{1'b0}};
            end_r   <= {AW{1'b0}};
            ea_r    <= {AW{1'b0}};
            beats   <= {AW{1'b0}};
            fault_r <= 1'b0;
        end else if (ce) begin
            case (state)
                IDLE: if (start) begin
                    base_r  <= base_in;
                    end_r   <= base_in + BURST * STRIDE;
                    beats   <= {AW{1'b0}};
                    fault_r <= 1'b0;
                    state   <= RUN;
                end
                RUN: begin
                    ea_r    <= ea_next;
                    fault_r <= misaligned;
                    base_r  <= step_base;
                    beats   <= beats + 1'b1;
                    if (step_base == end_r)
                        state <= DONE;
                end
                DONE: state <= IDLE;
                default: state <= IDLE;
            endcase
        end
    end

    always @(posedge clk)
        if (!rst && ce && state == RUN && misaligned)
            armed <= 1'b0;

    assign ea    = ea_r;
    assign fault = fault_r;

    assert property (!armed || beats <= BURST);
endmodule

module seg_rot_shifter #(
    parameter W = 32,
    parameter SEGS = 4
) (
    input  wire              clk,
    input  wire              rst,
    input  wire              in_valid,
    output wire              in_ready,
    input  wire [W-1:0]      in_data,
    input  wire [31:0]       in_amt,
    input  wire              step,
    output reg               out_valid,
    input  wire              out_ready,
    output wire [SEGS*W-1:0] out_data
);
    reg [SEGS*W-1:0] segs;
    reg [SEGS-1:0]   spill;
    reg              par;
    reg              busy;
    reg [31:0]       cnt;

    initial segs = {SEGS*W{1'b0}};
    initial spill = {SEGS{1'b0}};
    initial par = 1'b0;
    initial busy = 1'b0;
    initial cnt = 32'd0;
    initial out_valid = 1'b0;

    assign in_ready = !busy && !out_valid;
    assign out_data = segs;

    reg [SEGS*W-1:0] seg_nxt;
    reg [SEGS-1:0]   sp_nxt;
    integer i;
    always @(*) begin
        for (i = 0; i < SEGS; i = i + 1) begin
            seg_nxt[i*W +: W] = {segs[i*W +: (W-1)], spill[(i+SEGS-1)%SEGS]};
            sp_nxt[i] = segs[i*W + W - 2];
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            segs <= {SEGS*W{1'b0}};
            spill <= {SEGS{1'b0}};
            par <= 1'b0;
            busy <= 1'b0;
            cnt <= 32'd0;
            out_valid <= 1'b0;
        end else begin
            if (in_valid && in_ready) begin
                segs <= {{((SEGS-1)*W){1'b0}}, in_data};
                spill <= {{(SEGS-1){1'b0}}, in_data[W-1]};
                par <= ^in_data;
                cnt <= in_amt;
                busy <= 1'b1;
            end else if (busy && step) begin
                if (cnt == 32'd0) begin
                    busy <= 1'b0;
                    out_valid <= 1'b1;
                end else begin
                    segs <= seg_nxt;
                    spill <= sp_nxt;
                    cnt <= cnt - 32'd1;
                end
            end
            if (out_valid && out_ready)
                out_valid <= 1'b0;
        end
    end

    always @(posedge clk)
        if (busy) assert ((^segs) == par);
endmodule

module pkt_stream_mux #(
    parameter NSRC = 4,
    parameter DW   = 128,
    parameter CNTW = 3,
    parameter SRCW = $clog2(NSRC)
) (
    input  wire                 clk,
    input  wire                 rst_n,
    input  wire [NSRC-1:0]      s_valid,
    input  wire [NSRC*DW-1:0]   s_data,
    input  wire [NSRC-1:0]      s_last,
    output wire [NSRC-1:0]      s_ready,
    output reg                  o_valid,
    output reg  [DW-1:0]        o_data,
    output reg                  o_last,
    output reg  [SRCW-1:0]      o_src,
    input  wire                 o_ready
);
    reg [SRCW-1:0] cur_src  = {SRCW{1'b0}};
    reg            locked   = 1'b0;
    reg [CNTW-1:0] beat_cnt = {CNTW{1'b0}};
    initial begin
        o_valid = 1'b0;
        o_data  = {DW{1'b0}};
        o_last  = 1'b0;
        o_src   = {SRCW{1'b0}};
    end

    wire            can_load = !o_valid || o_ready;
    wire            take     = can_load && s_valid[cur_src];
    wire [DW-1:0]   sel_data = s_data[cur_src*DW +: DW];
    wire            sel_last = s_last[cur_src];
    wire [SRCW-1:0] next_src = (cur_src == NSRC-1) ? {SRCW{1'b0}} : cur_src + {{(SRCW-1){1'b0}},1'b1};

    assign s_ready = can_load ? ({{(NSRC-1){1'b0}},1'b1} << cur_src) : {NSRC{1'b0}};

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cur_src  <= {SRCW{1'b0}};
            locked   <= 1'b0;
            beat_cnt <= {CNTW{1'b0}};
            o_valid  <= 1'b0;
            o_data   <= {DW{1'b0}};
            o_last   <= 1'b0;
            o_src    <= {SRCW{1'b0}};
        end else begin
            if (take) begin
                o_valid <= 1'b1;
                o_data  <= sel_data;
                o_last  <= sel_last;
                o_src   <= cur_src;
                if (sel_last) begin
                    locked   <= 1'b0;
                    beat_cnt <= {CNTW{1'b0}};
                    cur_src  <= next_src;
                end else begin
                    locked   <= 1'b1;
                    beat_cnt <= (beat_cnt == {CNTW{1'b1}}) ? beat_cnt : beat_cnt + {{(CNTW-1){1'b0}},1'b1};
                end
            end else begin
                if (o_valid && o_ready)
                    o_valid <= 1'b0;
                if (!locked && !s_valid[cur_src] && (|s_valid))
                    cur_src <= next_src;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && $rose(locked))
            assert (beat_cnt == {{(CNTW-1){1'b0}},1'b1});
endmodule

module frac_xmul_cmp #(
    parameter W = 16,
    parameter [15:0] LAT = 16'd3
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         ce,
    input  wire         req,
    input  wire [W-1:0] a_num,
    input  wire [W-1:0] a_den,
    input  wire [W-1:0] c_num,
    input  wire [W-1:0] c_den,
    output wire         busy_o,
    output wire         done_o,
    output wire         lt_o,
    output wire         eq_o
);
    reg           busy    = 1'b0;
    reg  [1:0]    stage   = 2'd0;
    reg  [15:0]   cnt     = 16'd0;
    reg           armed   = 1'b0;
    reg  [W-1:0]  ra      = {W{1'b0}};
    reg  [W-1:0]  rb      = {W{1'b0}};
    reg  [W-1:0]  rc      = {W{1'b0}};
    reg  [W-1:0]  rd      = {W{1'b0}};
    reg  [2*W-1:0] prod_ad = {2*W{1'b0}};
    reg  [2*W-1:0] prod_cb = {2*W{1'b0}};
    reg           lt_r    = 1'b0;
    reg           eq_r    = 1'b0;
    reg           done_r  = 1'b0;

    assign busy_o = busy;
    assign done_o = done_r;
    assign lt_o   = lt_r;
    assign eq_o   = eq_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy    <= 1'b0;
            stage   <= 2'd0;
            cnt     <= 16'd0;
            armed   <= 1'b0;
            ra      <= {W{1'b0}};
            rb      <= {W{1'b0}};
            rc      <= {W{1'b0}};
            rd      <= {W{1'b0}};
            prod_ad <= {2*W{1'b0}};
            prod_cb <= {2*W{1'b0}};
            lt_r    <= 1'b0;
            eq_r    <= 1'b0;
            done_r  <= 1'b0;
        end else if (ce) begin
            done_r <= 1'b0;
            if (!busy) begin
                if (req) begin
                    busy  <= 1'b1;
                    armed <= 1'b1;
                    stage <= 2'd0;
                    cnt   <= LAT;
                    ra    <= a_num;
                    rb    <= a_den;
                    rc    <= c_num;
                    rd    <= c_den;
                end
            end else begin
                cnt <= cnt - 16'd1;
                case (stage)
                    2'd0: begin
                        prod_ad <= ra * rd;
                        prod_cb <= rc * rb;
                        stage   <= 2'd1;
                    end
                    2'd1: begin
                        lt_r  <= (prod_ad < prod_cb);
                        eq_r  <= (prod_ad == prod_cb);
                        stage <= 2'd2;
                    end
                    default: begin
                        busy   <= 1'b0;
                        done_r <= 1'b1;
                        stage  <= 2'd0;
                    end
                endcase
            end
        end
    end

    assert property (!armed || !busy || cnt != 16'd0);
endmodule

module uart_break_detect #(
    parameter [31:0] FRAME = 32'd10
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    input  wire s_line,
    output wire s_ready,
    output reg  m_valid,
    input  wire m_ready,
    output reg  brk_sticky
);
    reg [31:0] low_cnt = 32'd0;
    reg        in_brk  = 1'b0;
    reg        win     = 1'b0;
    initial m_valid    = 1'b0;
    initial brk_sticky = 1'b0;

    assign s_ready = !m_valid;
    wire acc = s_valid && s_ready;

    always @(posedge clk) begin
        if (rst) begin
            low_cnt    <= 32'd0;
            in_brk     <= 1'b0;
            win        <= 1'b0;
            m_valid    <= 1'b0;
            brk_sticky <= 1'b0;
        end else begin
            if (m_valid && m_ready)
                m_valid <= 1'b0;
            if (acc) begin
                if (!s_line) begin
                    win <= 1'b1;
                    if (!in_brk) begin
                        if (low_cnt == FRAME - 32'd1) begin
                            low_cnt    <= FRAME;
                            in_brk     <= 1'b1;
                            brk_sticky <= 1'b1;
                            m_valid    <= 1'b1;
                        end else begin
                            low_cnt <= low_cnt + 32'd1;
                        end
                    end
                end else begin
                    low_cnt <= 32'd0;
                    in_brk  <= 1'b0;
                    win     <= 1'b0;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win)
            assert (low_cnt <= FRAME && $past(low_cnt) <= FRAME);
endmodule

module warm_reset_quiesce #(
    parameter NPORTS = 64,
    parameter [31:0] TIMEOUT = 32'd16
) (
    input  wire              clk,
    input  wire              ce,
    input  wire              req_valid,
    output wire              req_ready,
    input  wire [NPORTS-1:0] port_idle,
    output wire              quiesce_req,
    output wire              block_new,
    output reg               warm_rst,
    output reg               timed_out
);
    reg              quiesce;
    reg [31:0]       timer;
    reg [31:0]       elapsed;
    reg [NPORTS-1:0] ack;
    reg              before_rst;

    initial begin
        quiesce    = 1'b0;
        timer      = 32'd0;
        elapsed    = 32'd0;
        ack        = {NPORTS{1'b0}};
        warm_rst   = 1'b0;
        timed_out  = 1'b0;
        before_rst = 1'b1;
    end

    assign req_ready   = ce && !quiesce;
    assign quiesce_req = quiesce;
    assign block_new   = quiesce;

    wire accept   = req_valid && req_ready;
    wire all_idle = &(ack | port_idle);
    wire expire   = (elapsed == TIMEOUT - 32'd1);

    always @(posedge clk) begin
        if (ce) begin
            warm_rst <= 1'b0;
            if (!quiesce) begin
                if (accept) begin
                    quiesce <= 1'b1;
                    timer   <= TIMEOUT;
                    elapsed <= 32'd0;
                    ack     <= {NPORTS{1'b0}};
                end
            end else begin
                ack <= ack | port_idle;
                if (all_idle || expire) begin
                    quiesce    <= 1'b0;
                    warm_rst   <= 1'b1;
                    timed_out  <= !all_idle;
                    before_rst <= 1'b0;
                end else begin
                    timer   <= timer - 32'd1;
                    elapsed <= elapsed + 32'd1;
                end
            end
        end
    end

    always @(*) assert (!(before_rst && quiesce) || timer != 32'd0);
endmodule

module csc_pipe #(
    parameter DW    = 64,
    parameter NCOEF = 8,
    parameter AW    = 3
) (
    input  wire          clk,
    input  wire          i_reset,
    // coefficient configuration port
    input  wire          cfg_valid,
    output wire          cfg_ready,
    input  wire [AW-1:0] cfg_addr,
    input  wire [DW-1:0] cfg_data,
    input  wire          cfg_last,
    // pixel input stream (R,G,B)
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_r,
    input  wire [DW-1:0] in_g,
    input  wire [DW-1:0] in_b,
    // pixel output stream (Cb,Cr)
    output reg           o_valid,
    input  wire          out_ready,
    output reg  [DW-1:0] o_cb,
    output reg  [DW-1:0] o_cr
);
    // coefficient bank: 0..2 Cb row, 3..5 Cr row, 6 Cb offset, 7 Cr offset
    reg [NCOEF*DW-1:0] coef;
    initial coef = {(NCOEF*DW){1'b0}};

    reg armed;    // window: coefficients committed (arm)
    reg started;  // a pixel has been accepted (start)
    reg s1_valid; // multiply stage holds a pixel
    initial armed    = 1'b0;
    initial started  = 1'b0;
    initial s1_valid = 1'b0;
    initial o_valid  = 1'b0;

    reg [DW-1:0] p0, p1, p2, p3, p4, p5;
    initial begin
        p0 = {DW{1'b0}}; p1 = {DW{1'b0}}; p2 = {DW{1'b0}};
        p3 = {DW{1'b0}}; p4 = {DW{1'b0}}; p5 = {DW{1'b0}};
        o_cb = {DW{1'b0}}; o_cr = {DW{1'b0}};
    end

    // whole pipeline stalls when downstream is not ready
    wire advance = out_ready;
    assign cfg_ready = !s1_valid && !o_valid;
    wire cfg_fire = cfg_valid && cfg_ready;
    assign in_ready  = armed && out_ready && !cfg_valid;
    wire in_fire  = in_valid && in_ready;

    always @(posedge clk) begin
        if (i_reset) begin
            armed    <= 1'b0;
            started  <= 1'b0;
            s1_valid <= 1'b0;
            o_valid  <= 1'b0;
        end else begin
            if (cfg_fire) begin
                coef[cfg_addr*DW +: DW] <= cfg_data;
                if (cfg_last)
                    armed <= 1'b1;
            end
            if (in_fire)
                started <= 1'b1;
            if (advance) begin
                s1_valid <= in_fire;
                o_valid  <= s1_valid;
            end
        end
    end

    // datapath: matrix multiply stage then sum/offset output register
    always @(posedge clk) begin
        if (advance) begin
            p0 <= in_r * coef[0*DW +: DW];
            p1 <= in_g * coef[1*DW +: DW];
            p2 <= in_b * coef[2*DW +: DW];
            p3 <= in_r * coef[3*DW +: DW];
            p4 <= in_g * coef[4*DW +: DW];
            p5 <= in_b * coef[5*DW +: DW];
            o_cb <= p0 + p1 + p2 + coef[6*DW +: DW];
            o_cr <= p3 + p4 + p5 + coef[7*DW +: DW];
        end
    end

    // chain precedence after commit: a delivered pixel implies a pixel was started
    always @(posedge clk)
        assert (!(armed && o_valid) || started);
endmodule

module axi_w_cdc_bridge #(
    parameter DW    = 16,
    parameter AW    = 8,
    parameter DEPTH = 256
) (
    input  wire          clk,
    input  wire          rst_n,
    // slave side (write domain): AXI W channel beats enter here
    input  wire          s_valid,
    output wire          s_ready,
    input  wire [DW-1:0] s_data,
    input  wire          s_last,
    // master side (read domain): beats leave here
    output wire          m_valid,
    input  wire          m_ready,
    output wire [DW-1:0] m_data,
    output wire          m_last
);
    // dual-clock payload storage (data + last flag)
    reg [DW:0] mem [0:DEPTH-1];
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = {(DW+1){1'b0}};
    end

    // write-side pointers and synchronized copy of the read pointer
    reg [AW:0]   wptr_bin  = {(AW+1){1'b0}};
    reg [AW:0]   wptr_gray = {(AW+1){1'b0}};
    reg [AW:0]   rq1       = {(AW+1){1'b0}};
    reg [AW:0]   rq2       = {(AW+1){1'b0}};
    reg          win       = 1'b0;
    reg [15:0]   beat_cnt  = 16'd0;

    // read-side pointers and synchronized copy of the write pointer
    reg [AW:0]   rptr_bin  = {(AW+1){1'b0}};
    reg [AW:0]   rptr_gray = {(AW+1){1'b0}};
    reg [AW:0]   wq1       = {(AW+1){1'b0}};
    reg [AW:0]   wq2       = {(AW+1){1'b0}};

    wire [AW:0] wbin_nxt  = wptr_bin + 1'b1;
    wire [AW:0] wgray_nxt = wbin_nxt ^ (wbin_nxt >> 1);
    wire [AW:0] rbin_nxt  = rptr_bin + 1'b1;
    wire [AW:0] rgray_nxt = rbin_nxt ^ (rbin_nxt >> 1);

    wire full  = (wptr_gray == {~rq2[AW:AW-1], rq2[AW-2:0]});
    wire empty = (rptr_gray == wq2);

    assign s_ready = !full;
    assign m_valid = !empty;

    wire do_push = s_valid && s_ready;
    wire do_pop  = m_valid && m_ready;

    assign {m_last, m_data} = mem[rptr_bin[AW-1:0]];

    always @(posedge clk)
        if (do_push) mem[wptr_bin[AW-1:0]] <= {s_last, s_data};

    // write domain
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr_bin  <= {(AW+1){1'b0}};
            wptr_gray <= {(AW+1){1'b0}};
            rq1       <= {(AW+1){1'b0}};
            rq2       <= {(AW+1){1'b0}};
            win       <= 1'b0;
            beat_cnt  <= 16'd0;
        end else begin
            if (do_push) begin
                wptr_bin  <= wbin_nxt;
                wptr_gray <= wgray_nxt;
                if (s_last) begin
                    win      <= 1'b0;
                    beat_cnt <= 16'd0;
                end else begin
                    win      <= 1'b1;
                    beat_cnt <= beat_cnt + 16'd1;
                end
            end
            if (s_valid) begin
                rq1 <= rptr_gray;
                rq2 <= rq1;
            end
        end
    end

    // read domain
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rptr_bin  <= {(AW+1){1'b0}};
            rptr_gray <= {(AW+1){1'b0}};
            wq1       <= {(AW+1){1'b0}};
            wq2       <= {(AW+1){1'b0}};
        end else begin
            if (do_pop) begin
                rptr_bin  <= rbin_nxt;
                rptr_gray <= rgray_nxt;
            end
            if (m_ready) begin
                wq1 <= wptr_gray;
                wq2 <= wq1;
            end
        end
    end

    // past-valid, cleared by reset
    reg pv = 1'b0;
    always @(posedge clk or negedge rst_n)
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;

    // inside a burst window: the gray write pointer never holds still while
    // the binary write pointer moves
    always @(posedge clk)
        if (pv && win && $stable(wptr_gray))
            assert ($stable(wptr_bin));
endmodule

module lane_tile_transpose #(
    parameter N = 4,
    parameter W = 64
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_data,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_data
);
    localparam IW = $clog2(N);
    localparam ENTRIES = N * N;

    typedef enum logic [0:0] {FILL = 1'b0, DRAIN = 1'b1} state_t;
    state_t state;
    initial state = FILL;

    // lane-sensor tile: rows = approach lanes, columns = signal phases
    reg [W-1:0] mem [0:ENTRIES-1];
    integer k;
    initial begin
        for (k = 0; k < ENTRIES; k = k + 1)
            mem[k] = {W{1'b0}};
    end

    reg [IW-1:0] wrow, wcol, rrow, rcol;
    initial wrow = 0;
    initial wcol = 0;
    initial rrow = 0;
    initial rcol = 0;

    // shadow history registers
    reg [63:0] wr_total, rd_total;
    initial wr_total = 64'd0;
    initial rd_total = 64'd0;

    // scope register: high until the first tile has been fully drained
    reg armed;
    initial armed = 1'b1;

    assign in_ready  = (state == FILL);
    assign out_valid = (state == DRAIN);
    assign out_data  = mem[{rrow, rcol}];

    wire wr_fire = in_valid && in_ready;
    wire rd_fire = out_valid && out_ready;
    wire wr_last = (wrow == N-1) && (wcol == N-1);
    wire rd_last = (rrow == N-1) && (rcol == N-1);

    always @(posedge clk) begin
        if (wr_fire) begin
            mem[{wrow, wcol}] <= in_data;
            wr_total <= wr_total + 64'd1;
            if (wcol == N-1) begin
                wcol <= 0;
                wrow <= wrow + 1'b1;
            end else begin
                wcol <= wcol + 1'b1;
            end
            if (wr_last)
                state <= DRAIN;
        end
        if (rd_fire) begin
            rd_total <= rd_total + 64'd1;
            if (rrow == N-1) begin
                rrow <= 0;
                rcol <= rcol + 1'b1;
            end else begin
                rrow <= rrow + 1'b1;
            end
            if (rd_last) begin
                state <= FILL;
                armed <= 1'b0;
            end
        end
    end

    // Precedence, before first drain completes: a phase column is offered only after the whole tile was written
    always @(posedge clk)
        if (armed && out_valid)
            assert (wr_total == ENTRIES);

    // Precedence, before first drain completes: every item read was written earlier
    always @(posedge clk)
        if (armed)
            assert (rd_total <= wr_total);
endmodule

module islip_alloc #(
    parameter N = 4
) (
    input  wire           clk,
    input  wire           rst_n,
    input  wire           en,
    input  wire [N*N-1:0] req,
    input  wire [N-1:0]   release_i,
    output wire [N-1:0]   o_in_busy,
    output wire [31:0]    o_active
);
    localparam PW = (N <= 2) ? 1 : $clog2(N);

    reg [N-1:0]    in_busy    = {N{1'b0}};
    reg [N-1:0]    out_busy   = {N{1'b0}};
    reg [N*PW-1:0] g_ptr      = {(N*PW){1'b0}};
    reg [N*PW-1:0] a_ptr      = {(N*PW){1'b0}};
    reg [N*PW-1:0] conn       = {(N*PW){1'b0}};
    reg [31:0]     active_cnt = 32'd0;
    reg            armed      = 1'b0;

    reg [N*N-1:0]  ereq, gnt, acc;
    reg [N-1:0]    new_in, new_out, rel_in, rel_out;
    reg [N*PW-1:0] acc_out, acc_in;
    reg [31:0]     new_cnt, rel_cnt;
    integer i, j, k, idx;
    reg found;

    always @(*) begin
        ereq = {(N*N){1'b0}};
        for (i = 0; i < N; i = i + 1)
            for (j = 0; j < N; j = j + 1)
                ereq[i*N+j] = req[i*N+j] & ~in_busy[i] & ~out_busy[j];
        gnt = {(N*N){1'b0}};
        for (j = 0; j < N; j = j + 1) begin
            found = 1'b0;
            for (k = 0; k < N; k = k + 1) begin
                idx = (g_ptr[j*PW +: PW] + k) % N;
                for (i = 0; i < N; i = i + 1)
                    if (!found && (i == idx) && ereq[i*N+j]) begin
                        gnt[j*N+i] = 1'b1;
                        found = 1'b1;
                    end
            end
        end
        acc = {(N*N){1'b0}};
        acc_out = {(N*PW){1'b0}};
        acc_in = {(N*PW){1'b0}};
        new_in = {N{1'b0}};
        new_out = {N{1'b0}};
        for (i = 0; i < N; i = i + 1) begin
            found = 1'b0;
            for (k = 0; k < N; k = k + 1) begin
                idx = (a_ptr[i*PW +: PW] + k) % N;
                for (j = 0; j < N; j = j + 1)
                    if (!found && (j == idx) && gnt[j*N+i]) begin
                        acc[i*N+j] = 1'b1;
                        acc_out[i*PW +: PW] = j;
                        acc_in[j*PW +: PW] = i;
                        new_in[i] = 1'b1;
                        new_out[j] = 1'b1;
                        found = 1'b1;
                    end
            end
        end
        rel_in = release_i & in_busy;
        rel_out = {N{1'b0}};
        for (i = 0; i < N; i = i + 1)
            for (j = 0; j < N; j = j + 1)
                if (rel_in[i] && (conn[i*PW +: PW] == j))
                    rel_out[j] = 1'b1;
        new_cnt = 32'd0;
        rel_cnt = 32'd0;
        for (i = 0; i < N; i = i + 1) begin
            new_cnt = new_cnt + new_in[i];
            rel_cnt = rel_cnt + rel_in[i];
        end
    end

    integer p;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            in_busy    <= {N{1'b0}};
            out_busy   <= {N{1'b0}};
            g_ptr      <= {(N*PW){1'b0}};
            a_ptr      <= {(N*PW){1'b0}};
            conn       <= {(N*PW){1'b0}};
            active_cnt <= 32'd0;
            armed      <= 1'b0;
        end else if (en) begin
            in_busy  <= (in_busy & ~rel_in) | new_in;
            out_busy <= (out_busy & ~rel_out) | new_out;
            for (p = 0; p < N; p = p + 1) begin
                if (new_in[p]) begin
                    conn[p*PW +: PW]  <= acc_out[p*PW +: PW];
                    a_ptr[p*PW +: PW] <= (acc_out[p*PW +: PW] == N-1) ? {PW{1'b0}} : acc_out[p*PW +: PW] + 1'b1;
                end
                if (new_out[p])
                    g_ptr[p*PW +: PW] <= (acc_in[p*PW +: PW] == N-1) ? {PW{1'b0}} : acc_in[p*PW +: PW] + 1'b1;
            end
            active_cnt <= active_cnt + new_cnt - rel_cnt;
            if (new_cnt != 32'd0)
                armed <= 1'b1;
        end
    end

    assign o_in_busy = in_busy;
    assign o_active  = active_cnt;

    always @(posedge clk)
        if (armed)
            assert (active_cnt <= N);
endmodule

module pam4_gray_mapper #(
    parameter CW = 32
) (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       slip,
    input  wire       precode_en,
    input  wire       din,
    output reg  [1:0] sym_out,
    output reg        sym_valid,
    output wire       pair_pending
);
    // bit-pair staging register
    reg          stage_bit;
    reg          half;
    // precoder previous-symbol register
    reg  [1:0]   prev_sym;
    // statistics
    reg  [CW-1:0] bit_cnt;
    reg  [CW-1:0] sym_cnt;
    reg  [CW-1:0] drop_cnt;
    // scope register: high until the first bit slip
    reg          armed;

    initial begin
        stage_bit = 1'b0;
        half      = 1'b0;
        prev_sym  = 2'd0;
        bit_cnt   = {CW{1'b0}};
        sym_cnt   = {CW{1'b0}};
        drop_cnt  = {CW{1'b0}};
        armed     = 1'b1;
        sym_out   = 2'd0;
        sym_valid = 1'b0;
    end

    wire [1:0] pair  = {stage_bit, din};
    // Gray map: 00->0, 01->1, 11->2, 10->3
    wire [1:0] level = {pair[1], pair[1] ^ pair[0]};
    wire [1:0] coded = precode_en ? (level - prev_sym) : level;

    always @(posedge clk) begin
        if (rst) begin
            stage_bit <= 1'b0;
            half      <= 1'b0;
            prev_sym  <= 2'd0;
            bit_cnt   <= {CW{1'b0}};
            sym_cnt   <= {CW{1'b0}};
            drop_cnt  <= {CW{1'b0}};
            armed     <= 1'b1;
            sym_out   <= 2'd0;
            sym_valid <= 1'b0;
        end else if (ce) begin
            if (slip) begin
                armed     <= 1'b0;
                sym_valid <= 1'b0;
                if (half) begin
                    half     <= 1'b0;
                    drop_cnt <= drop_cnt + {{(CW-1){1'b0}}, 1'b1};
                end
            end else begin
                bit_cnt <= bit_cnt + {{(CW-1){1'b0}}, 1'b1};
                if (!half) begin
                    stage_bit <= din;
                    half      <= 1'b1;
                    sym_valid <= 1'b0;
                end else begin
                    half      <= 1'b0;
                    sym_cnt   <= sym_cnt + {{(CW-1){1'b0}}, 1'b1};
                    sym_out   <= coded;
                    prev_sym  <= coded;
                    sym_valid <= 1'b1;
                end
            end
        end
    end

    assign pair_pending = half;

    // Absence, before the first slip: the staging register is never occupied
    // while the bit count sits on a pair boundary.
    always @(posedge clk)
        if (armed)
            assert (!(half && (bit_cnt[0] == 1'b0)));
endmodule

module preload_timer #(
    parameter W = 16
) (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_period,
    input  wire [W-1:0] in_cmp,
    output wire [W-1:0] o_cnt,
    output wire         o_match,
    output wire         o_wrap
);
    reg [W-1:0] cnt        = {W{1'b0}};
    reg [W-1:0] period_act = 16'd9;
    reg [W-1:0] period_sh  = 16'd9;
    reg [W-1:0] cmp_act    = 16'd4;
    reg [W-1:0] cmp_sh     = 16'd4;
    reg         pend       = 1'b0;
    reg         armed      = 1'b0;
    reg         pv         = 1'b0;

    assign in_ready = !pend;
    wire accept = in_valid && in_ready;
    wire wrap   = i_ce && (cnt >= period_act);

    assign o_cnt   = cnt;
    assign o_match = (cnt == cmp_act);
    assign o_wrap  = wrap;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (cnt >= period_act) begin
                cnt        <= {W{1'b0}};
                period_act <= period_sh;
                cmp_act    <= cmp_sh;
            end else begin
                cnt <= cnt + 1'b1;
            end
        end
        if (accept) begin
            period_sh <= in_period;
            cmp_sh    <= in_cmp;
            pend      <= 1'b1;
        end else if (wrap) begin
            pend      <= 1'b0;
        end
        if (accept)
            armed <= 1'b1;
    end

    always @(posedge clk)
        if (pv && armed && $stable(pend))
            assert ($stable(period_act));
endmodule

module idle_autopd #(
    parameter DATA_W = 128,
    parameter CNT_W  = 4,
    parameter [CNT_W-1:0] DEF_THR = 4'd6
) (
    input  wire              clk,
    input  wire              rst,
    input  wire              in_valid,
    output wire              in_ready,
    input  wire [DATA_W-1:0] in_data,
    input  wire              tick,
    input  wire              cfg_thr_we,
    input  wire [CNT_W-1:0]  cfg_thr,
    input  wire              cfg_en,
    input  wire              cfg_dis,
    output wire              pwr_down_req,
    output reg  [DATA_W-1:0] blk_data
);
    reg [CNT_W-1:0] idle_cnt = {CNT_W{1'b0}};
    reg [CNT_W-1:0] thresh   = DEF_THR;
    reg             pd_req   = 1'b0;
    reg             apd_en   = 1'b0;
    initial blk_data = {DATA_W{1'b0}};

    assign in_ready     = !pd_req;
    assign pwr_down_req = pd_req && apd_en;

    wire accept = in_valid && in_ready;

    always @(posedge clk) begin
        if (rst) begin
            idle_cnt <= {CNT_W{1'b0}};
            thresh   <= DEF_THR;
            pd_req   <= 1'b0;
        end else if (cfg_thr_we) begin
            thresh   <= (cfg_thr == {CNT_W{1'b0}}) ? {{(CNT_W-1){1'b0}}, 1'b1} : cfg_thr;
            idle_cnt <= {CNT_W{1'b0}};
            pd_req   <= 1'b0;
        end else if (in_valid) begin
            idle_cnt <= {CNT_W{1'b0}};
            pd_req   <= 1'b0;
        end else if (tick && !pd_req) begin
            idle_cnt <= idle_cnt + 1'b1;
            if (idle_cnt + 1'b1 == thresh)
                pd_req <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (!rst && accept)
            blk_data <= in_data;
    end

    always @(posedge clk) begin
        if (rst)
            apd_en <= 1'b0;
        else if (cfg_dis)
            apd_en <= 1'b0;
        else if (cfg_en)
            apd_en <= 1'b1;
    end

    always @(*) assert (!apd_en || idle_cnt <= thresh);
endmodule

module exp_scale_unit #(
    parameter W = 32,
    parameter signed EMAX = 127,
    parameter signed EMIN = -126
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [W-1:0] i_exp,
    input  wire [W-1:0] i_scale,
    input  wire [W-1:0] i_sig,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [W-1:0] o_exp,
    output reg  [W-1:0] o_sig,
    output reg          o_ovf,
    output reg          o_uf,
    output reg  [W-1:0] ovf_in_cnt,
    output reg  [W-1:0] ovf_out_cnt
);
    initial begin
        o_valid = 1'b0; o_exp = {W{1'b0}}; o_sig = {W{1'b0}};
        o_ovf = 1'b0; o_uf = 1'b0;
        ovf_in_cnt = {W{1'b0}}; ovf_out_cnt = {W{1'b0}};
    end

    assign i_ready = !o_valid || o_ready;
    wire accept = i_valid && i_ready;
    wire fire   = o_valid && o_ready;

    // scaleB: exponent + signed scale, computed wide to avoid wrap
    wire signed [W+1:0] sum = $signed({{2{i_exp[W-1]}}, i_exp}) + $signed({{2{i_scale[W-1]}}, i_scale});
    wire ovf_now = (sum > EMAX);
    wire uf_now  = (sum < EMIN);
    wire signed [W+1:0] ushift = EMIN - sum;
    wire flush = uf_now && (ushift >= W);
    wire [W-1:0] den_sig = flush ? {W{1'b0}} : (i_sig >> ushift[$clog2(W):0]);
    wire [W-1:0] emax_p1 = EMAX + 1;
    wire [W-1:0] emin_m1 = EMIN - 1;
    wire [W-1:0] res_exp = ovf_now ? emax_p1 : (uf_now ? emin_m1 : sum[W-1:0]);
    wire [W-1:0] res_sig = ovf_now ? {W{1'b0}} : (uf_now ? den_sig : i_sig);

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0; o_exp <= {W{1'b0}}; o_sig <= {W{1'b0}};
            o_ovf <= 1'b0; o_uf <= 1'b0;
            ovf_in_cnt <= {W{1'b0}}; ovf_out_cnt <= {W{1'b0}};
        end else begin
            if (accept) begin
                o_valid <= 1'b1;
                o_exp   <= res_exp;
                o_sig   <= res_sig;
                o_ovf   <= ovf_now;
                o_uf    <= uf_now;
            end else if (fire) begin
                o_valid <= 1'b0;
            end
            if (accept && ovf_now) ovf_in_cnt  <= ovf_in_cnt + 1'b1;
            if (fire && o_ovf)     ovf_out_cnt <= ovf_out_cnt + 1'b1;
        end
    end

    // Precedence: an overflow result delivered now must have been preceded by
    // an accepted overflowing input that has not yet been delivered.
    always @(posedge clk)
        if (o_valid && o_ready && o_ovf)
            assert (ovf_in_cnt != ovf_out_cnt);
endmodule

module bcd_divider #(
    parameter DIGITS = 16
) (
    input  wire                  clk,
    input  wire                  i_clr,
    input  wire                  i_ce,
    input  wire                  i_go,
    input  wire [4*DIGITS-1:0]   i_dividend,
    input  wire [4*DIGITS-1:0]   i_divisor,
    output wire [4*DIGITS-1:0]   o_quotient,
    output wire [4*DIGITS+3:0]   o_remainder,
    output wire                  o_done
);
    localparam W  = 4*DIGITS;
    localparam RW = W + 4;
    localparam PW = $clog2(DIGITS);

    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_TABLE = 2'd1;
    localparam [1:0] P_DIV   = 2'd2;
    localparam [1:0] P_DONE  = 2'd3;

    function [RW-1:0] bcd_add;
        input [RW-1:0] a;
        input [RW-1:0] b;
        integer i;
        reg [4:0] s;
        reg c;
        begin
            c = 1'b0;
            bcd_add = {RW{1'b0}};
            for (i = 0; i < RW/4; i = i + 1) begin
                s = {1'b0, a[4*i +: 4]} + {1'b0, b[4*i +: 4]} + {4'd0, c};
                if (s > 5'd9) begin s = s + 5'd6; c = 1'b1; end
                else c = 1'b0;
                bcd_add[4*i +: 4] = s[3:0];
            end
        end
    endfunction

    function [RW-1:0] bcd_sub;
        input [RW-1:0] a;
        input [RW-1:0] b;
        integer i;
        reg [4:0] d;
        reg br;
        begin
            br = 1'b0;
            bcd_sub = {RW{1'b0}};
            for (i = 0; i < RW/4; i = i + 1) begin
                d = {1'b0, a[4*i +: 4]} - {1'b0, b[4*i +: 4]} - {4'd0, br};
                if (d[4]) begin d = d + 5'd10; br = 1'b1; end
                else br = 1'b0;
                bcd_sub[4*i +: 4] = d[3:0];
            end
        end
    endfunction

    reg [1:0]    phase      = P_IDLE;
    reg [3:0]    tbl_idx    = 4'd0;
    reg [PW-1:0] pos        = {PW{1'b0}};
    reg [W-1:0]  dvd        = {W{1'b0}};
    reg [W-1:0]  quo        = {W{1'b0}};
    reg [RW-1:0] rem        = {RW{1'b0}};
    reg [RW-1:0] acc        = {RW{1'b0}};
    reg [RW-1:0] mult [0:9];
    reg          seen_arm   = 1'b0;
    reg          seen_start = 1'b0;
    reg          done       = 1'b0;
    reg          win        = 1'b0;

    integer k;
    initial begin
        for (k = 0; k < 10; k = k + 1) mult[k] = {RW{1'b0}};
    end

    wire [RW-1:0] shifted = {rem[RW-5:0], dvd[pos*4 +: 4]};
    wire [RW-1:0] acc_sum = bcd_add(acc, mult[1]);

    reg [3:0]    qdig;
    reg [RW-1:0] qmul;
    integer j;
    always @(*) begin
        qdig = 4'd0;
        qmul = {RW{1'b0}};
        for (j = 1; j < 10; j = j + 1)
            if (shifted >= mult[j]) begin
                qdig = j;
                qmul = mult[j];
            end
    end

    wire [RW-1:0] rem_next = bcd_sub(shifted, qmul);

    always @(posedge clk) begin
        if (i_clr) begin
            phase      <= P_IDLE;
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            done       <= 1'b0;
            win        <= 1'b0;
        end else if (i_ce) begin
            case (phase)
                P_IDLE, P_DONE: begin
                    if (i_go) begin
                        dvd        <= i_dividend;
                        quo        <= {W{1'b0}};
                        rem        <= {RW{1'b0}};
                        mult[0]    <= {RW{1'b0}};
                        mult[1]    <= {4'd0, i_divisor};
                        acc        <= {4'd0, i_divisor};
                        tbl_idx    <= 4'd2;
                        phase      <= P_TABLE;
                        seen_arm   <= 1'b1;
                        seen_start <= 1'b0;
                        done       <= 1'b0;
                        win        <= 1'b1;
                    end
                end
                P_TABLE: begin
                    for (k = 2; k < 10; k = k + 1)
                        if (tbl_idx == k) mult[k] <= acc_sum;
                    acc <= acc_sum;
                    if (tbl_idx == 4'd9) begin
                        phase      <= P_DIV;
                        seen_start <= 1'b1;
                        pos        <= DIGITS - 1;
                    end else begin
                        tbl_idx <= tbl_idx + 4'd1;
                    end
                end
                P_DIV: begin
                    rem <= rem_next;
                    quo <= {quo[W-5:0], qdig};
                    if (pos == {PW{1'b0}}) begin
                        phase <= P_DONE;
                        done  <= 1'b1;
                    end else begin
                        pos <= pos - 1'b1;
                    end
                end
                default: phase <= P_IDLE;
            endcase
        end
    end

    assign o_quotient  = quo;
    assign o_remainder = rem;
    assign o_done      = done;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $rose(done))
            assert (seen_arm && seen_start);
endmodule

module ola_block_conv #(
    parameter W = 32,
    parameter BLK = 64,
    parameter TAPS = 4,
    parameter [TAPS*W-1:0] COEF = {32'd1, 32'd3, 32'd3, 32'd1}
)(
    input  wire         clk,
    input  wire         i_reset,
    input  wire         i_ce,
    input  wire [W-1:0] i_sample,
    output reg  [W-1:0] o_y,
    output reg          o_valid,
    output wire         o_busy,
    output wire [31:0]  o_blocks
);
    localparam [31:0] LAST  = BLK + TAPS - 2;
    localparam [31:0] TLAST = TAPS - 2;

    reg [W-1:0] in_buf [0:BLK-1];
    reg [W-1:0] tail   [0:TAPS-2];
    reg [31:0] wr_idx   = 32'd0;
    reg [31:0] out_idx  = 32'd0;
    reg [31:0] tail_idx = 32'd0;
    reg [31:0] blk_cnt  = 32'd0;
    reg        phase    = 1'b0;

    integer i;
    initial begin
        o_y = 0;
        o_valid = 1'b0;
        for (i = 0; i < BLK; i = i + 1) in_buf[i] = 0;
        for (i = 0; i < TAPS-1; i = i + 1) tail[i] = 0;
    end

    assign o_busy   = phase;
    assign o_blocks = blk_cnt;

    reg [W-1:0] acc;
    reg [31:0]  src;
    integer j;
    always @(*) begin
        acc = 0;
        src = 0;
        for (j = 0; j < TAPS; j = j + 1) begin
            src = out_idx - j;
            if (out_idx >= j && src < BLK)
                acc = acc + COEF[j*W +: W] * in_buf[src];
        end
        if (out_idx < TAPS-1)
            acc = acc + tail[out_idx];
    end

    always @(posedge clk) begin
        if (i_reset) begin
            wr_idx   <= 32'd0;
            out_idx  <= 32'd0;
            tail_idx <= 32'd0;
            blk_cnt  <= 32'd0;
            phase    <= 1'b0;
            o_valid  <= 1'b0;
            o_y      <= 0;
        end else if (i_ce) begin
            o_valid <= 1'b0;
            if (!phase) begin
                in_buf[wr_idx] <= i_sample;
                if (wr_idx == BLK-1) begin
                    wr_idx   <= 32'd0;
                    phase    <= 1'b1;
                    out_idx  <= 32'd0;
                    tail_idx <= 32'd0;
                end else begin
                    wr_idx <= wr_idx + 32'd1;
                end
            end else begin
                if (out_idx >= BLK) begin
                    tail[tail_idx] <= acc;
                    if (tail_idx == TLAST) begin
                        phase    <= 1'b0;
                        out_idx  <= 32'd0;
                        tail_idx <= 32'd0;
                        blk_cnt  <= blk_cnt + 32'd1;
                    end else begin
                        tail_idx <= tail_idx + 32'd1;
                        out_idx  <= out_idx + 32'd1;
                    end
                end else begin
                    o_y     <= acc;
                    o_valid <= 1'b1;
                    out_idx <= out_idx + 32'd1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv) assert (!$past(i_ce) || out_idx <= LAST);
endmodule

module arduboy_tone_ripple #(
    parameter W = 8
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         in_valid,
    output wire         in_ready,
    output reg          out_valid,
    input  wire         out_ready,
    output wire         pin_a,
    output wire         pin_b,
    output wire [W-1:0] o_count
);
    localparam [W-1:0] HALF = {1'b1, {(W-1){1'b0}}};

    // a tone tick is accepted only when valid and ready are both high
    assign in_ready = !out_valid;
    wire accept = in_valid && in_ready;

    // ripple chain of toggle flip-flops: each stage toggles when the
    // previous stage falls (synchronous model of the ripple carry)
    wire [W:0]   t;
    wire [W-1:0] q;
    assign t[0] = accept;

    genvar i;
    generate
        for (i = 0; i < W; i = i + 1) begin : stage
            reg tff = 1'b0;
            always @(posedge clk or negedge rst_n) begin
                if (!rst_n)
                    tff <= 1'b0;
                else if (t[i])
                    tff <= ~tff;
            end
            assign q[i]   = tff;
            assign t[i+1] = t[i] & tff;
        end
    endgenerate

    // shadow record of every tick accepted earlier
    reg [W-1:0] shadow = {W{1'b0}};
    initial out_valid = 1'b0;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shadow    <= {W{1'b0}};
            out_valid <= 1'b0;
        end else begin
            if (accept)
                shadow <= shadow + 1'b1;
            if (t[W])
                out_valid <= 1'b1;          // full buzzer period completed
            else if (out_valid && out_ready)
                out_valid <= 1'b0;
        end
    end

    // piezo wired between two pins, driven in antiphase
    assign pin_a   = q[W-1];
    assign pin_b   = ~q[W-1];
    assign o_count = q;

    // precedence: buzzer phase high now => half a period of ticks accepted earlier
    always @(*) assert (!q[W-1] || shadow >= HALF);
    // precedence: period-done offered now => the accepted-tick record has wrapped
    always @(*) assert (!out_valid || shadow == {W{1'b0}});
endmodule

module apb_reg_ctrl #(
    parameter NREGS = 16,
    parameter AW    = 4,
    parameter DW    = 32
) (
    input  wire          clk,
    input  wire          psel,
    input  wire          penable,
    input  wire          pwrite,
    input  wire [AW-1:0] paddr,
    input  wire [DW-1:0] pwdata,
    input  wire          dev_ready,
    output wire          pready,
    output reg  [DW-1:0] prdata
);
    typedef enum logic [1:0] {IDLE = 2'd0, SETUP = 2'd1, ACCESS = 2'd2} state_t;

    state_t        state    = IDLE;
    reg            phase    = 1'b0;
    reg [AW-1:0]   sel_idx  = {AW{1'b0}};
    reg            wr_q     = 1'b0;
    reg [DW-1:0]   wdata_q  = {DW{1'b0}};
    reg            in_xfer  = 1'b0;
    reg [DW-1:0]   xfer_cnt = {DW{1'b0}};
    reg [DW-1:0]   done_cnt = {DW{1'b0}};
    reg [DW-1:0]   regs [0:NREGS-1];

    integer i;
    initial begin
        prdata = {DW{1'b0}};
        for (i = 0; i < NREGS; i = i + 1) regs[i] = {DW{1'b0}};
    end

    assign pready = (state == ACCESS) && dev_ready;

    wire start        = (state == IDLE)   && psel && !penable;
    wire enter_access = (state == SETUP)  && psel && penable;
    wire xfer_done    = (state == ACCESS) && psel && penable && pready;

    always @(posedge clk) begin
        case (state)
            IDLE: if (start) begin
                state    <= SETUP;
                phase    <= 1'b0;
                sel_idx  <= paddr;
                wr_q     <= pwrite;
                wdata_q  <= pwdata;
                in_xfer  <= 1'b1;
                xfer_cnt <= xfer_cnt + 32'd1;
            end
            SETUP: if (enter_access) begin
                state <= ACCESS;
                phase <= 1'b1;
            end
            ACCESS: if (xfer_done) begin
                state    <= IDLE;
                phase    <= 1'b0;
                in_xfer  <= 1'b0;
                done_cnt <= done_cnt + 32'd1;
                if (wr_q) regs[sel_idx] <= wdata_q;
                else      prdata        <= regs[sel_idx];
            end
            default: state <= state;
        endcase
    end

    assert property (!in_xfer || (xfer_cnt == done_cnt + 32'd1));
endmodule

module irq_claim_gateway #(
    parameter NSRC = 4,
    parameter IDW  = 2,
    parameter W    = 64
) (
    input  wire            clk,
    input  wire            i_reset,
    input  wire            i_ce,
    input  wire [NSRC-1:0] irq_in,
    input  wire            claim_rd,
    input  wire            cmpl_wr,
    input  wire [IDW-1:0]  cmpl_id,
    output wire [W-1:0]    o_claim_id,
    output wire            o_cmpl_ack
);
    reg [NSRC-1:0] pending  = {NSRC{1'b0}};
    reg [NSRC-1:0] inflight = {NSRC{1'b0}};
    reg [W-1:0]    last_id   = {W{1'b0}};
    reg [W-1:0]    ack_id    = {W{1'b0}};
    reg [W-1:0]    claim_cnt = {W{1'b0}};
    reg [W-1:0]    cmpl_cnt  = {W{1'b0}};
    reg            cmpl_ack  = 1'b0;
    reg            seen_q    = 1'b0;
    reg            pv        = 1'b0;

    reg [IDW-1:0] sel_id;
    reg           any_pend;
    integer i;
    always @(*) begin
        sel_id   = {IDW{1'b0}};
        any_pend = 1'b0;
        for (i = 0; i < NSRC; i = i + 1)
            if (pending[i]) begin
                sel_id   = i;
                any_pend = 1'b1;
            end
    end

    wire do_claim = i_ce && claim_rd && any_pend && (inflight == {NSRC{1'b0}});
    wire do_cmpl  = i_ce && cmpl_wr && inflight[cmpl_id];

    wire [NSRC-1:0] one_hot1   = {{(NSRC-1){1'b0}}, 1'b1};
    wire [NSRC-1:0] claim_mask = do_claim ? (one_hot1 << sel_id)  : {NSRC{1'b0}};
    wire [NSRC-1:0] cmpl_mask  = do_cmpl  ? (one_hot1 << cmpl_id) : {NSRC{1'b0}};

    always @(posedge clk) begin
        if (i_reset) begin
            pending   <= {NSRC{1'b0}};
            inflight  <= {NSRC{1'b0}};
            last_id   <= {W{1'b0}};
            ack_id    <= {W{1'b0}};
            claim_cnt <= {W{1'b0}};
            cmpl_cnt  <= {W{1'b0}};
            cmpl_ack  <= 1'b0;
        end else if (i_ce) begin
            pending  <= (pending | (irq_in & ~inflight)) & ~claim_mask;
            inflight <= (inflight | claim_mask) & ~cmpl_mask;
            if (do_claim) begin
                last_id   <= {{(W-IDW){1'b0}}, sel_id};
                claim_cnt <= claim_cnt + {{(W-1){1'b0}}, 1'b1};
                seen_q    <= 1'b1;
            end
            cmpl_ack <= do_cmpl;
            if (do_cmpl) begin
                ack_id   <= {{(W-IDW){1'b0}}, cmpl_id};
                cmpl_cnt <= cmpl_cnt + {{(W-1){1'b0}}, 1'b1};
            end
        end
    end

    always @(posedge clk) pv <= 1'b1;

    assign o_claim_id = last_id;
    assign o_cmpl_ack = cmpl_ack;

    always @(posedge clk)
        if (pv && seen_q && $rose(cmpl_ack))
            assert (ack_id == last_id);
endmodule

module freq_meter #(
    parameter DATA_W = 128,
    parameter GATE_W = 4,
    parameter [GATE_W-1:0] DEFAULT_GATE = 4'd8
) (
    input  wire              clk,
    input  wire              ce,
    input  wire              load,
    input  wire [GATE_W-1:0] gate_len_in,
    input  wire              arm_cmd,
    input  wire              start_cmd,
    input  wire              fx,
    output reg  [DATA_W-1:0] res0,
    output reg  [DATA_W-1:0] res1,
    output reg               res_valid
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_GATE = 2'd2, S_DONE = 2'd3;

    reg [1:0]        phase    = S_IDLE;
    reg              after_q  = 1'b0;
    reg              st_seen  = 1'b0;
    reg [GATE_W-1:0] gate_len = DEFAULT_GATE;
    reg [GATE_W-1:0] gate_cnt = {GATE_W{1'b0}};
    reg [DATA_W-1:0] ev_cnt   = {DATA_W{1'b0}};
    reg              fx_q     = 1'b0;

    initial res0 = {DATA_W{1'b0}};
    initial res1 = {DATA_W{1'b0}};
    initial res_valid = 1'b0;

    wire edge_det = fx & ~fx_q;

    always @(posedge clk) begin
        if (ce) begin
            fx_q <= fx;
            if (load)
                gate_len <= gate_len_in;
            case (phase)
                S_IDLE: begin
                    if (arm_cmd) begin
                        phase     <= S_ARMED;
                        after_q   <= 1'b1;
                        st_seen   <= 1'b0;
                        res_valid <= 1'b0;
                    end
                end
                S_ARMED: begin
                    if (start_cmd) begin
                        phase    <= S_GATE;
                        st_seen  <= 1'b1;
                        gate_cnt <= {GATE_W{1'b0}};
                        ev_cnt   <= {DATA_W{1'b0}};
                    end
                end
                S_GATE: begin
                    gate_cnt <= gate_cnt + 1'b1;
                    if (edge_det)
                        ev_cnt <= ev_cnt + {{(DATA_W-1){1'b0}}, 1'b1};
                    if (gate_cnt >= gate_len) begin
                        phase     <= S_DONE;
                        res_valid <= 1'b1;
                        res1      <= res0;
                        res0      <= ev_cnt;
                    end
                end
                S_DONE: begin
                    if (arm_cmd) begin
                        phase     <= S_ARMED;
                        st_seen   <= 1'b0;
                        res_valid <= 1'b0;
                    end
                end
            endcase
        end
    end

    // Chain precedence after the first arm: finish is never seen without start
    always @(posedge clk)
        if (after_q && phase == S_DONE) assert (st_seen);

    always @(posedge clk)
        if (after_q && res_valid) assert (st_seen);
endmodule

module sha2_sched_expander #(
    parameter WIDTH  = 8,
    parameter NW     = 16,
    parameter ROUNDS = 48
) (
    input  wire                  clk,
    input  wire                  ce,
    input  wire                  start,
    input  wire [WIDTH*NW-1:0]   blk,
    output wire [WIDTH-1:0]      o_word,
    output wire                  o_busy,
    output wire                  o_done
);
    localparam [7:0] NR = ROUNDS;

    typedef enum logic [1:0] {IDLE = 2'd0, EXPAND = 2'd1, DONE = 2'd2} state_t;
    state_t state;

    reg [WIDTH*NW-1:0] sched;
    reg [7:0] rnd;
    reg [7:0] tmr;
    reg       win;

    initial begin
        state = IDLE;
        sched = {(WIDTH*NW){1'b0}};
        rnd   = 8'd0;
        tmr   = 8'd0;
        win   = 1'b0;
    end

    function [WIDTH-1:0] rotr(input [WIDTH-1:0] x, input integer n);
        rotr = (x >> n) | (x << (WIDTH - n));
    endfunction

    function [WIDTH-1:0] sig0(input [WIDTH-1:0] x);
        sig0 = rotr(x, 1) ^ rotr(x, 4) ^ (x >> 2);
    endfunction

    function [WIDTH-1:0] sig1(input [WIDTH-1:0] x);
        sig1 = rotr(x, 3) ^ rotr(x, 5) ^ (x >> 1);
    endfunction

    wire [WIDTH-1:0] w0  = sched[0*WIDTH  +: WIDTH];
    wire [WIDTH-1:0] w1  = sched[1*WIDTH  +: WIDTH];
    wire [WIDTH-1:0] w9  = sched[9*WIDTH  +: WIDTH];
    wire [WIDTH-1:0] w14 = sched[14*WIDTH +: WIDTH];
    wire [WIDTH-1:0] w_new = sig1(w14) + w9 + sig0(w1) + w0;

    always @(posedge clk) begin
        if (ce) begin
            case (state)
                IDLE: begin
                    if (start) begin
                        sched <= blk;
                        rnd   <= 8'd0;
                        tmr   <= NR;
                        state <= EXPAND;
                        win   <= 1'b1;
                    end
                end
                EXPAND: begin
                    sched <= {w_new, sched[WIDTH*NW-1:WIDTH]};
                    rnd   <= rnd + 8'd1;
                    tmr   <= tmr - 8'd1;
                    if (rnd == NR - 8'd1) begin
                        state <= DONE;
                        win   <= 1'b0;
                    end
                end
                DONE: state <= IDLE;
                default: state <= IDLE;
            endcase
        end
    end

    assign o_word = sched[WIDTH*NW-1 -: WIDTH];
    assign o_busy = win;
    assign o_done = (state == DONE);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $past(win))
            assert (tmr != 8'd0 && (!$stable(rnd) || $stable(tmr)));
endmodule

module psg_minority_tally #(
    parameter [31:0] FRAME = 32'd64
) (
    input  wire clk,
    input  wire step,
    input  wire start,
    input  wire stop,
    input  wire ch_a,
    input  wire ch_b,
    input  wire ch_c,
    output wire minority,
    output wire busy
);
    typedef enum logic [1:0] {S_IDLE = 2'd0, S_RUN = 2'd1, S_DONE = 2'd2} state_t;

    // Minority gate: complement of the majority of the three channel bits
    wire majority = (ch_a & ch_b) | (ch_a & ch_c) | (ch_b & ch_c);
    assign minority = ~majority;

    state_t state;
    reg [31:0] pos;
    reg [31:0] cnt;
    reg armed;

    initial state = S_IDLE;
    initial pos = 32'd0;
    initial cnt = 32'd0;
    initial armed = 1'b0;

    assign busy = (state == S_RUN);

    always @(posedge clk) begin
        if (step) begin
            case (state)
                S_IDLE: begin
                    if (start) begin
                        state <= S_RUN;
                        pos <= 32'd0;
                        cnt <= 32'd0;
                    end
                end
                S_RUN: begin
                    pos <= pos + 32'd1;
                    cnt <= cnt + {31'd0, minority};
                    if (pos == FRAME - 32'd1)
                        state <= S_DONE;
                end
                S_DONE: begin
                    if (start) begin
                        state <= S_RUN;
                        pos <= 32'd0;
                        cnt <= 32'd0;
                    end
                end
                default: state <= S_IDLE;
            endcase
        end
    end

    // Window register: opened by a frame start, closed by stop (which may never come)
    always @(posedge clk) begin
        if (step) begin
            if (start)
                armed <= 1'b1;
            else if (stop)
                armed <= 1'b0;
        end
    end

    assert property (!armed || cnt <= FRAME);
endmodule

module branch_resolve_unit #(
    parameter integer XLEN = 64,
    parameter [63:0] INSN_BYTES = 64'd4
) (
    input  wire            clk,
    input  wire            ce,
    input  wire            br_valid,
    input  wire [XLEN-1:0] br_pc,
    input  wire [XLEN-1:0] br_offset,
    input  wire            br_cond,
    input  wire [XLEN-1:0] br_pred_tgt,
    input  wire [XLEN-1:0] br_pred_meta,
    output wire            o_redirect,
    output wire            o_flush,
    output wire [XLEN-1:0] o_redirect_addr,
    output wire            o_busy
);
    typedef enum logic [1:0] {S_IDLE, S_RESOLVE, S_REDIRECT, S_FLUSH} state_t;

    state_t state = S_IDLE;
    reg            win = 1'b0;
    reg [XLEN-1:0] pc_q = {XLEN{1'b0}};
    reg [XLEN-1:0] off_q = {XLEN{1'b0}};
    reg            cond_q = 1'b0;
    reg [XLEN-1:0] pred_target = {XLEN{1'b0}};
    reg [XLEN-1:0] pred_meta = {XLEN{1'b0}};
    reg [XLEN-1:0] redirect_addr = {XLEN{1'b0}};
    reg [XLEN-1:0] mispred_cnt = {XLEN{1'b0}};

    wire [XLEN-1:0] actual_tgt = cond_q ? (pc_q + off_q) : (pc_q + INSN_BYTES);
    wire            mispredict = (actual_tgt != pred_target);

    always @(posedge clk) begin
        if (ce) begin
            case (state)
                S_IDLE: begin
                    if (br_valid) begin
                        pc_q        <= br_pc;
                        off_q       <= br_offset;
                        cond_q      <= br_cond;
                        pred_target <= br_pred_tgt;
                        pred_meta   <= br_pred_meta;
                        state       <= S_RESOLVE;
                    end
                end
                S_RESOLVE: begin
                    if (mispredict) begin
                        redirect_addr <= actual_tgt;
                        mispred_cnt   <= mispred_cnt + 64'd1;
                        win           <= 1'b1;
                        state         <= S_REDIRECT;
                    end else begin
                        state <= S_IDLE;
                    end
                end
                S_REDIRECT: begin
                    state <= S_FLUSH;
                end
                S_FLUSH: begin
                    win   <= 1'b0;
                    state <= S_IDLE;
                end
                default: state <= S_IDLE;
            endcase
        end
    end

    assign o_redirect      = (state == S_REDIRECT);
    assign o_flush         = (state == S_FLUSH);
    assign o_redirect_addr = redirect_addr;
    assign o_busy          = (state != S_IDLE);

    always @(posedge clk)
        if (win)
            assert (redirect_addr != pred_target);
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;

    assign in_ready  = (state == S_ACCUM);
    assign out_valid = (state == S_DONE);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready;

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
            if (in_mag < min1) begin
                min2    <= min1;
                min1    <= in_mag;
                min_idx <= count;
            end else if (in_mag < min2) begin
                min2 <= in_mag;
            end
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = min1;
    assign out_min2 = min2;
    assign out_idx  = min_idx;
    assign out_sign = sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
endmodule

module ckpt_regfile #(
    parameter W = 32,
    parameter NREG = 4,
    parameter NCKPT = 4,
    parameter [31:0] TIMEOUT = 32'd6,
    parameter SW = $clog2(NCKPT),
    parameter RW = $clog2(NREG)
) (
    input wire clk,
    input wire rst,
    input wire step,
    input wire branch,
    input wire resolve,
    input wire mispredict,
    input wire [SW-1:0] rsv_id,
    input wire wr_en,
    input wire [RW-1:0] wr_addr,
    input wire [W-1:0] wr_data,
    output wire [NCKPT-1:0] o_mask,
    output wire [W-1:0] o_acc0,
    output wire o_busy
);
    // active accumulator register file and checkpoint shadow copies
    reg [NREG*W-1:0] regs_q;
    reg [NCKPT*NREG*W-1:0] shadow_q;
    reg [NCKPT-1:0] ckpt_mask;
    reg [31:0] n_live;
    reg [31:0] wd;
    reg armed;

    initial begin
        regs_q = {NREG*W{1'b0}};
        shadow_q = {NCKPT*NREG*W{1'b0}};
        ckpt_mask = {NCKPT{1'b0}};
        n_live = 32'd0;
        wd = 32'd0;
        armed = 1'b1;
    end

    // lowest free checkpoint slot
    reg [SW-1:0] free_slot;
    integer k;
    always @(*) begin
        free_slot = {SW{1'b0}};
        for (k = NCKPT-1; k >= 0; k = k - 1)
            if (!ckpt_mask[k]) free_slot = k;
    end

    wire live        = (n_live != 32'd0);
    wire timeout     = live && (wd == 32'd1);
    wire do_rollback = mispredict && ckpt_mask[rsv_id];
    wire do_free     = resolve && ckpt_mask[rsv_id];
    wire do_alloc    = branch && (n_live != NCKPT);

    reg [NCKPT-1:0] mask_nxt;
    reg [31:0] live_nxt;
    always @(*) begin
        mask_nxt = ckpt_mask;
        live_nxt = n_live;
        if (do_free) begin
            mask_nxt[rsv_id] = 1'b0;
            live_nxt = live_nxt - 32'd1;
        end
        if (do_alloc) begin
            mask_nxt[free_slot] = 1'b1;
            live_nxt = live_nxt + 32'd1;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            regs_q <= {NREG*W{1'b0}};
            ckpt_mask <= {NCKPT{1'b0}};
            n_live <= 32'd0;
            wd <= 32'd0;
        end else if (step) begin
            if (timeout) begin
                // deadline reached: force-commit all outstanding checkpoints
                ckpt_mask <= {NCKPT{1'b0}};
                n_live <= 32'd0;
                wd <= 32'd0;
            end else if (do_rollback) begin
                regs_q <= shadow_q[rsv_id*NREG*W +: NREG*W];
                ckpt_mask <= {NCKPT{1'b0}};
                n_live <= 32'd0;
                wd <= 32'd0;
                armed <= 1'b0;
            end else begin
                if (do_alloc)
                    shadow_q[free_slot*NREG*W +: NREG*W] <= regs_q;
                if (wr_en)
                    regs_q[wr_addr*W +: W] <= wr_data;
                ckpt_mask <= mask_nxt;
                n_live <= live_nxt;
                if (live_nxt == 32'd0)
                    wd <= 32'd0;
                else if (!live)
                    wd <= TIMEOUT;
                else
                    wd <= wd - 32'd1;
            end
        end
    end

    assign o_mask = ckpt_mask;
    assign o_acc0 = regs_q[W-1:0];
    assign o_busy = live;

    // before the first rollback: an outstanding checkpoint never sees an expired deadline
    always @(*) assert (!armed || ckpt_mask == {NCKPT{1'b0}} || wd != 32'd0);
endmodule

module twiddle_rom_seq #(
    parameter N   = 256,
    parameter LGN = 8,
    parameter DW  = 64
) (
    input  wire          clk,
    input  wire          i_reset,
    input  wire          i_ce,
    output reg  [DW-1:0] o_re,
    output reg  [DW-1:0] o_im,
    output reg           o_unity,
    output reg           o_negj,
    output reg           o_win
);
    localparam HALF = N / 2;
    localparam QW   = N / 4;
    localparam SH   = DW - 2 - 2*(LGN-2);
    localparam [DW-1:0] ONE = {2'b01, {(DW-2){1'b0}}};

    // quarter-wave magnitude table: cos(pi*x/(N/2)) approximated as 1-(x/QW)^2
    function [DW-1:0] cmag;
        input [LGN-2:0] x;
        reg [2*(LGN-1)-1:0] sq;
        begin
            sq   = x * x;
            cmag = ONE - ({{(DW-2*(LGN-1)){1'b0}}, sq} << SH);
        end
    endfunction

    // real coefficient table: cos(2*pi*k/N), quadrant folded
    function [DW-1:0] re_rom;
        input [LGN-1:0] k;
        reg [LGN-2:0] r;
        begin
            r = {1'b0, k[LGN-3:0]};
            case (k[LGN-1:LGN-2])
                2'd0:    re_rom =  cmag(r);
                2'd1:    re_rom = -cmag(QW - r);
                2'd2:    re_rom = -cmag(r);
                default: re_rom =  cmag(QW - r);
            endcase
        end
    endfunction

    // imaginary coefficient table: -sin(2*pi*k/N), quadrant folded
    function [DW-1:0] im_rom;
        input [LGN-1:0] k;
        reg [LGN-2:0] r;
        begin
            r = {1'b0, k[LGN-3:0]};
            case (k[LGN-1:LGN-2])
                2'd0:    im_rom = -cmag(QW - r);
                2'd1:    im_rom = -cmag(r);
                2'd2:    im_rom =  cmag(QW - r);
                default: im_rom =  cmag(r);
            endcase
        end
    endfunction

    reg [DW-1:0]  pos;
    reg [DW-1:0]  stage;
    reg [LGN-1:0] re_addr;
    reg [LGN-1:0] im_addr;

    initial pos     = 0;
    initial stage   = 0;
    initial re_addr = 0;
    initial im_addr = 0;
    initial o_re    = 0;
    initial o_im    = 0;
    initial o_unity = 1'b0;
    initial o_negj  = 1'b0;
    initial o_win   = 1'b0;

    // twiddle index for butterfly position pos in stage: (pos << stage) mod N
    wire [LGN-1:0] tw_k = pos[LGN-1:0] << stage[2:0];

    always @(posedge clk) begin
        if (i_reset) begin
            pos     <= 0;
            stage   <= 0;
            re_addr <= 0;
            im_addr <= 0;
            o_re    <= 0;
            o_im    <= 0;
            o_unity <= 1'b0;
            o_negj  <= 1'b0;
            o_win   <= 1'b0;
        end else if (i_ce) begin
            // separate address registers for the real and imaginary ROM ports
            re_addr <= tw_k;
            im_addr <= tw_k;
            // registered coefficient output pair
            o_re    <= re_rom(re_addr);
            o_im    <= im_rom(im_addr);
            o_unity <= (re_addr == 0);
            o_negj  <= (im_addr == QW);
            if (pos == HALF-1) begin
                pos   <= 0;
                stage <= (stage == LGN-1) ? 0 : stage + 1;
            end else begin
                pos   <= pos + 1;
            end
            // stage window: opens at first butterfly, closes at last
            if (pos == 0)
                o_win <= 1'b1;
            else if (pos == HALF-1)
                o_win <= 1'b0;
        end
    end

    // within a stage window, the unity and -j coefficient markers never coincide
    assert property (!o_win || !(o_unity && o_negj));
endmodule

module irq_first_arrival #(
    parameter NCH  = 8,
    parameter IDXW = 3,
    parameter TW   = 64
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            ce,
    input  wire            clr,
    input  wire [NCH-1:0]  irq,
    output reg             captured,
    output reg [IDXW-1:0]  win_idx,
    output reg [NCH-1:0]   win_mask,
    output reg [TW-1:0]    cap_time
);
    localparam [NCH-1:0] ONE = 1;

    reg [TW-1:0] tick;

    initial begin
        captured = 1'b0;
        win_idx  = {IDXW{1'b0}};
        win_mask = {NCH{1'b0}};
        cap_time = {TW{1'b0}};
        tick     = {TW{1'b0}};
    end

    function [IDXW-1:0] first_idx;
        input [NCH-1:0] v;
        integer i;
        begin
            first_idx = {IDXW{1'b0}};
            for (i = NCH-1; i >= 0; i = i - 1)
                if (v[i]) first_idx = i;
        end
    endfunction

    wire [IDXW-1:0] enc = first_idx(irq);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            captured <= 1'b0;
            win_idx  <= {IDXW{1'b0}};
            win_mask <= {NCH{1'b0}};
            cap_time <= {TW{1'b0}};
            tick     <= {TW{1'b0}};
        end else if (ce) begin
            tick <= tick + {{(TW-1){1'b0}}, 1'b1};
            if (!captured && (|irq)) begin
                captured <= 1'b1;
                win_idx  <= enc;
                win_mask <= ONE << enc;
                cap_time <= tick;
            end else if (captured && clr) begin
                captured <= 1'b0;
                win_mask <= win_mask & ~(ONE << win_idx);
            end
        end
    end

    always @(*) assert (captured || win_mask == {NCH{1'b0}});
endmodule

module eye_scan_monitor #(
    parameter [63:0] NSAMP = 64'd16,
    parameter [63:0] H_PTS = 64'd4,
    parameter [63:0] V_PTS = 64'd4
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        start,
    input  wire        abort,
    input  wire        data_bit,
    input  wire        offset_bit,
    output wire        busy,
    output wire [63:0] o_mismatch,
    output wire [63:0] o_h_off,
    output wire [63:0] o_v_off
);
    typedef enum logic [1:0] {S_IDLE, S_SAMPLE, S_STEP, S_DONE} state_t;

    state_t     state;
    reg [63:0]  h_off;
    reg [63:0]  v_off;
    reg [63:0]  sample_cnt;
    reg [63:0]  mismatch_cnt;
    reg         window;

    initial begin
        state        = S_IDLE;
        h_off        = 64'd0;
        v_off        = 64'd0;
        sample_cnt   = 64'd0;
        mismatch_cnt = 64'd0;
        window       = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state        <= S_IDLE;
            h_off        <= 64'd0;
            v_off        <= 64'd0;
            sample_cnt   <= 64'd0;
            mismatch_cnt <= 64'd0;
            window       <= 1'b0;
        end else if (en) begin
            case (state)
                S_IDLE: begin
                    if (start) begin
                        state        <= S_SAMPLE;
                        h_off        <= 64'd0;
                        v_off        <= 64'd0;
                        sample_cnt   <= 64'd0;
                        mismatch_cnt <= 64'd0;
                        window       <= 1'b1;
                    end
                end
                S_SAMPLE: begin
                    if (abort) begin
                        state  <= S_IDLE;
                        window <= 1'b0;
                    end else begin
                        sample_cnt <= sample_cnt + 64'd1;
                        if (data_bit != offset_bit)
                            mismatch_cnt <= mismatch_cnt + 64'd1;
                        if (sample_cnt == NSAMP - 64'd1)
                            state <= S_STEP;
                    end
                end
                S_STEP: begin
                    sample_cnt   <= 64'd0;
                    mismatch_cnt <= 64'd0;
                    if (h_off == H_PTS - 64'd1) begin
                        h_off <= 64'd0;
                        if (v_off == V_PTS - 64'd1) begin
                            v_off <= 64'd0;
                            state <= S_DONE;
                        end else begin
                            v_off <= v_off + 64'd1;
                            state <= S_SAMPLE;
                        end
                    end else begin
                        h_off <= h_off + 64'd1;
                        state <= S_SAMPLE;
                    end
                end
                S_DONE: begin
                    window <= 1'b0;
                    state  <= S_IDLE;
                end
                default: state <= S_IDLE;
            endcase
        end
    end

    assign busy       = (state != S_IDLE);
    assign o_mismatch = mismatch_cnt;
    assign o_h_off    = h_off;
    assign o_v_off    = v_off;

    always @(posedge clk)
        if (window)
            assert (mismatch_cnt <= NSAMP);
endmodule

module requant_unit #(
    parameter W  = 64,
    parameter SW = 6
) (
    input  wire          clk,
    input  wire          rst,
    input  wire          ce,
    input  wire          arm,
    input  wire          start,
    input  wire          ack,
    input  wire          clr,
    input  wire [W-1:0]  cfg_mult,
    input  wire [SW-1:0] cfg_shift,
    input  wire [W-1:0]  acc_in,
    output reg  [W-1:0]  out_q,
    output reg  [1:0]    phase
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, BUSY = 2'd2, DONE = 2'd3;

    reg [W-1:0]  mult_cfg  = {W{1'b0}};
    reg [SW-1:0] shift_cfg = {SW{1'b0}};
    reg [W-1:0]  work      = {W{1'b0}};
    reg [SW-1:0] cnt       = {SW{1'b0}};
    reg          run       = 1'b0;
    reg          win       = 1'b0;
    initial out_q = {W{1'b0}};
    initial phase = IDLE;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            run   <= 1'b0;
            cnt   <= {SW{1'b0}};
            work  <= {W{1'b0}};
            win   <= 1'b0;
        end else if (ce) begin
            if (clr)
                win <= 1'b0;
            if (phase == IDLE && arm) begin
                mult_cfg  <= cfg_mult;
                shift_cfg <= cfg_shift;
                phase     <= ARMED;
                win       <= 1'b1;
            end
            if (phase == ARMED && start) begin
                work  <= acc_in * mult_cfg;
                cnt   <= shift_cfg;
                run   <= 1'b1;
                phase <= BUSY;
            end
            if (phase == DONE && ack)
                phase <= IDLE;
            if (run) begin
                if (cnt == {SW{1'b0}}) begin
                    out_q <= work;
                    run   <= 1'b0;
                    phase <= DONE;
                end else begin
                    work <= work >> 1;
                    cnt  <= cnt - 1'b1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $stable(phase))
            assert ($stable(out_q));
endmodule

module tage_predictor #(
    parameter ENTRIES = 32,
    parameter IDXW    = 5,
    parameter TAGW    = 4,
    parameter CTRW    = 3,
    parameter BCTRW   = 2,
    parameter HISTW   = 16,
    parameter CW      = 16,
    parameter [15:0] TICK_MAX = 16'd15
)(
    input  wire          clk,
    input  wire          rst_n,
    input  wire          i_ce,
    input  wire [15:0]   i_pc,
    input  wire          i_taken,
    input  wire          i_arm,
    output wire          o_pred,
    output wire [CW-1:0] o_ucnt
);
    // base bimodal table and two tagged tables (history lengths 4 and 8)
    reg [ENTRIES*BCTRW-1:0] base_ctr;
    reg [ENTRIES*TAGW-1:0]  t1_tag;
    reg [ENTRIES*CTRW-1:0]  t1_ctr;
    reg [ENTRIES-1:0]       t1_u;
    reg [ENTRIES*TAGW-1:0]  t2_tag;
    reg [ENTRIES*CTRW-1:0]  t2_ctr;
    reg [ENTRIES-1:0]       t2_u;
    reg [HISTW-1:0]         ghist;
    reg [CW-1:0]            t1_ucnt;
    reg [CW-1:0]            tick;
    reg                     armed;

    initial begin
        base_ctr = 0; t1_tag = 0; t1_ctr = 0; t1_u = 0;
        t2_tag = 0; t2_ctr = 0; t2_u = 0; ghist = 0;
        t1_ucnt = 0; tick = 0; armed = 0;
    end

    // folded global history, geometric lengths 4 (T1) and 8 (T2)
    wire [IDXW-1:0] fold1 = {1'b0, ghist[3:0]};
    wire [IDXW-1:0] fold2 = ghist[4:0] ^ {2'b00, ghist[7:5]};
    wire [IDXW-1:0] idx0  = i_pc[IDXW-1:0];
    wire [IDXW-1:0] idx1  = i_pc[IDXW-1:0] ^ fold1;
    wire [IDXW-1:0] idx2  = i_pc[IDXW-1:0] ^ fold2;
    wire [TAGW-1:0] tag1  = i_pc[8:5] ^ ghist[3:0];
    wire [TAGW-1:0] tag2  = i_pc[8:5] ^ ghist[7:4] ^ {ghist[2:0], ghist[3]};

    wire [BCTRW-1:0] b_c   = base_ctr[idx0*BCTRW +: BCTRW];
    wire [TAGW-1:0]  t1_t  = t1_tag[idx1*TAGW +: TAGW];
    wire [CTRW-1:0]  t1_c  = t1_ctr[idx1*CTRW +: CTRW];
    wire             t1_uo = t1_u[idx1];
    wire [TAGW-1:0]  t2_t  = t2_tag[idx2*TAGW +: TAGW];
    wire [CTRW-1:0]  t2_c  = t2_ctr[idx2*CTRW +: CTRW];
    wire             t2_uo = t2_u[idx2];

    wire hit1 = (t1_t == tag1);
    wire hit2 = (t2_t == tag2);
    wire base_pred = b_c[BCTRW-1];
    wire t1_pred   = t1_c[CTRW-1];
    wire t2_pred   = t2_c[CTRW-1];
    wire prov_t2 = hit2;
    wire prov_t1 = !hit2 && hit1;
    wire prov_b  = !hit2 && !hit1;
    wire alt_pred = prov_t2 ? (hit1 ? t1_pred : base_pred) : base_pred;
    wire pred     = prov_t2 ? t2_pred : (prov_t1 ? t1_pred : base_pred);
    wire mispred  = (pred != i_taken);
    assign o_pred = pred;
    assign o_ucnt = t1_ucnt;

    // saturating counter next values
    wire [BCTRW-1:0] b_nxt  = i_taken ? ((b_c  == 2'd3) ? b_c  : b_c  + 2'd1) : ((b_c  == 2'd0) ? b_c  : b_c  - 2'd1);
    wire [CTRW-1:0]  t1_nxt = i_taken ? ((t1_c == 3'd7) ? t1_c : t1_c + 3'd1) : ((t1_c == 3'd0) ? t1_c : t1_c - 3'd1);
    wire [CTRW-1:0]  t2_nxt = i_taken ? ((t2_c == 3'd7) ? t2_c : t2_c + 3'd1) : ((t2_c == 3'd0) ? t2_c : t2_c - 3'd1);
    wire [CTRW-1:0]  weak   = i_taken ? 3'd4 : 3'd3;

    // usefulness and allocation
    wire u1_set      = prov_t1 && !mispred && (alt_pred != t1_pred);
    wire u1_dec      = prov_t1 &&  mispred && (alt_pred != t1_pred);
    wire alloc1_try  = prov_b && mispred;
    wire alloc1_ok   = alloc1_try && !t1_uo;
    wire alloc1_fail = alloc1_try &&  t1_uo;
    wire alloc2_try  = prov_t1 && mispred;
    wire alloc2_ok   = alloc2_try && !t2_uo;
    wire alloc2_fail = alloc2_try &&  t2_uo;
    wire u1_clr      = u1_dec || alloc1_fail;
    wire u2_set      = prov_t2 && !mispred && (alt_pred != t2_pred);
    wire u2_clr      = (prov_t2 && mispred && (alt_pred != t2_pred)) || alloc2_fail;
    wire any_fail    = alloc1_fail || alloc2_fail;
    wire u_reset     = any_fail && (tick == TICK_MAX);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            base_ctr <= 0; t1_tag <= 0; t1_ctr <= 0; t1_u <= 0;
            t2_tag <= 0; t2_ctr <= 0; t2_u <= 0; ghist <= 0;
            t1_ucnt <= 0; tick <= 0; armed <= 0;
        end else if (i_ce) begin
            ghist <= {ghist[HISTW-2:0], i_taken};
            if (prov_b)  base_ctr[idx0*BCTRW +: BCTRW] <= b_nxt;
            if (prov_t1) t1_ctr[idx1*CTRW +: CTRW] <= t1_nxt;
            if (alloc1_ok) begin
                t1_tag[idx1*TAGW +: TAGW] <= tag1;
                t1_ctr[idx1*CTRW +: CTRW] <= weak;
            end
            if (prov_t2) t2_ctr[idx2*CTRW +: CTRW] <= t2_nxt;
            if (alloc2_ok) begin
                t2_tag[idx2*TAGW +: TAGW] <= tag2;
                t2_ctr[idx2*CTRW +: CTRW] <= weak;
            end
            if (u_reset) begin
                t1_u <= 0; t2_u <= 0; t1_ucnt <= 0; tick <= 0;
            end else begin
                if (any_fail) tick <= tick + 16'd1;
                if (u1_set && !t1_uo) begin
                    t1_u[idx1] <= 1'b1;
                    t1_ucnt <= t1_ucnt + 16'd1;
                end else if (u1_clr && t1_uo) begin
                    t1_u[idx1] <= 1'b0;
                    t1_ucnt <= t1_ucnt - 16'd1;
                end
                if (u2_set) t2_u[idx2] <= 1'b1;
                else if (u2_clr) t2_u[idx2] <= 1'b0;
            end
            // scope window: opened by i_arm, closed by the periodic usefulness reset
            if (u_reset) armed <= 1'b0;
            else if (i_arm) armed <= 1'b1;
        end
    end

    // absence: the useful-entry count never reads zero while some T1 entry is marked useful
    always @(posedge clk)
        if (armed)
            assert (!((t1_ucnt == 16'd0) && (t1_u != 32'd0)));
endmodule

module ddr3_cmd_queue #(
    parameter DEPTH = 12,
    parameter DW = 32
) (
    input  wire          clk,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data,
    input  wire          cfg_load,
    input  wire [31:0]   cfg_wm,
    output wire          almost_full,
    output wire [31:0]   occupancy
);
    localparam AW = $clog2(DEPTH);
    localparam [AW-1:0] LAST = DEPTH - 1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] wptr = {AW{1'b0}};
    reg [AW-1:0] rptr = {AW{1'b0}};
    reg          wr_lap = 1'b0;
    reg          rd_lap = 1'b0;
    reg [31:0]   count = 32'd0;
    reg [31:0]   wm = 32'd8;
    reg          armed = 1'b1;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = {DW{1'b0}};
    end

    wire full  = (wptr == rptr) && (wr_lap != rd_lap);
    wire empty = (wptr == rptr) && (wr_lap == rd_lap);
    assign in_ready  = !full;
    assign out_valid = !empty;
    assign out_data  = mem[rptr];

    wire push = in_valid && in_ready;
    wire pop  = out_valid && out_ready;

    // T inputs of the two lap toggle flip-flops
    wire wr_t = push && (wptr == LAST);
    wire rd_t = pop  && (rptr == LAST);

    always @(posedge clk) begin
        if (push) begin
            mem[wptr] <= in_data;
            wptr <= (wptr == LAST) ? {AW{1'b0}} : wptr + 1'b1;
        end
        if (pop)
            rptr <= (rptr == LAST) ? {AW{1'b0}} : rptr + 1'b1;
        if (wr_t) wr_lap <= ~wr_lap;
        if (rd_t) rd_lap <= ~rd_lap;
        case ({push, pop})
            2'b10:   count <= count + 32'd1;
            2'b01:   count <= count - 32'd1;
            default: count <= count;
        endcase
        if (cfg_load) begin
            wm    <= cfg_wm;
            armed <= 1'b0;
        end
    end

    assign almost_full = (count >= wm);
    assign occupancy   = count;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $rose(wr_lap))
            assert (count <= DEPTH);
endmodule

module xbar_cfg #(
    parameter N_IN  = 16,
    parameter N_OUT = 16,
    parameter DW    = 8,
    parameter SW    = $clog2(N_IN),
    parameter PW    = $clog2(N_OUT)
) (
    input  wire                 clk,
    input  wire                 rst,
    input  wire                 cfg_valid,
    output wire                 cfg_ready,
    input  wire [PW-1:0]        cfg_port,
    input  wire [SW-1:0]        cfg_sel,
    input  wire                 commit,
    input  wire                 lock,
    input  wire [N_IN*DW-1:0]   in_data,
    output wire [N_OUT*DW-1:0]  out_data
);
    typedef enum logic [1:0] {IDLE = 2'd0, PEND = 2'd1, LOCKED = 2'd2} state_t;

    state_t state = IDLE;
    reg [SW-1:0] sel [0:N_OUT-1];
    reg [PW-1:0] pend_port = '0;
    reg [SW-1:0] pend_sel  = '0;
    reg          cfg_seen  = 1'b0;
    reg          armed     = 1'b1;

    integer i;
    initial begin
        for (i = 0; i < N_OUT; i = i + 1) sel[i] = '0;
    end

    assign cfg_ready = (state == IDLE);

    always @(posedge clk) begin
        if (rst) begin
            state     <= IDLE;
            for (i = 0; i < N_OUT; i = i + 1) sel[i] <= '0;
            pend_port <= '0;
            pend_sel  <= '0;
            cfg_seen  <= 1'b0;
            armed     <= 1'b1;
        end else begin
            case (state)
                IDLE: begin
                    if (cfg_valid && cfg_ready) begin
                        pend_port <= cfg_port;
                        pend_sel  <= cfg_sel;
                        cfg_seen  <= 1'b1;
                        state     <= PEND;
                    end else if (lock) begin
                        armed <= 1'b0;
                        state <= LOCKED;
                    end
                end
                PEND: begin
                    if (commit) begin
                        sel[pend_port] <= pend_sel;
                        state          <= IDLE;
                    end
                end
                LOCKED: begin
                end
                default: state <= IDLE;
            endcase
        end
    end

    genvar o;
    generate
        for (o = 0; o < N_OUT; o = o + 1) begin : g_out
            assign out_data[o*DW +: DW] = in_data[sel[o]*DW +: DW];
        end
    endgenerate

    reg any_sel;
    integer j;
    always @(*) begin
        any_sel = 1'b0;
        for (j = 0; j < N_OUT; j = j + 1)
            any_sel = any_sel | (sel[j] != '0);
    end

    always @(posedge clk) assert (!armed || cfg_seen || !any_sel);
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b
);
    localparam NBF = NCOEF / 2;

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end

    assign in_ready = !busy && !out_valid;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);

    wire [31:0] prod = w_r * b_r;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load_cfg) lat_cfg <= cfg_lat;
        if (accept) begin
            a_r   <= in_a;
            b_r   <= in_b;
            w_r   <= in_w;
            lat_q <= lat_eff;
            cd    <= lat_eff;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
        end else if (busy && ce) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - 16'd1;
                phase <= phase + 16'd1;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

module zi_mux_chain #(
    parameter N  = 16,
    parameter W  = 64,
    parameter SW = 4
) (
    input  wire          clk,
    input  wire          i_reset,
    input  wire          i_ce,
    input  wire          i_arm,
    input  wire [SW-1:0] i_sel,
    input  wire          i_start,
    input  wire [SW-1:0] i_idx,
    input  wire [W-1:0]  i_data,
    output wire [W-1:0]  o_data,
    output wire          o_vld
);
    // arm: latch the mux select; start: load an entry and mark it valid;
    // finish: the zero-insertion mux forwards a valid entry.
    reg            armed   = 1'b0;
    reg            started = 1'b0;
    reg [SW-1:0]   sel     = {SW{1'b0}};
    reg [N-1:0]    vmask   = {N{1'b0}};
    reg [N*W-1:0]  store   = {(N*W){1'b0}};
    reg [W-1:0]    odata   = {W{1'b0}};
    reg            ovld    = 1'b0;

    always @(posedge clk) begin
        if (i_reset) begin
            armed   <= 1'b0;
            started <= 1'b0;
            sel     <= {SW{1'b0}};
            vmask   <= {N{1'b0}};
            store   <= {(N*W){1'b0}};
            odata   <= {W{1'b0}};
            ovld    <= 1'b0;
        end else if (i_ce) begin
            if (i_arm) begin
                armed <= 1'b1;
                sel   <= i_sel;
            end
            if (i_start && armed) begin
                started              <= 1'b1;
                vmask[i_idx]         <= 1'b1;
                store[i_idx*W +: W]  <= i_data;
            end
            ovld  <= vmask[sel];
            odata <= vmask[sel] ? store[sel*W +: W] : {W{1'b0}};
        end
    end

    assign o_data = odata;
    assign o_vld  = ovld;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Chain precedence: a forwarded (finished) word is never observed unless
    // the start and arm steps had already happened by the previous cycle.
    always @(posedge clk)
        if (pv && ovld)
            assert ($past(started) && $past(armed));
endmodule

module fll_cnt_cmp #(
    parameter W = 64,
    parameter [W-1:0] WINDOW = 64'd8
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         ce,
    input  wire         osc_tick,
    input  wire         tgt_load,
    input  wire [W-1:0] tgt_in,
    output reg  [W-1:0] osc_code,
    output reg          locked
);
    typedef enum logic [1:0] {S_IDLE = 2'd0, S_COUNT = 2'd1, S_CMP = 2'd2, S_ADJ = 2'd3} state_t;

    state_t state = S_IDLE;
    reg [W-1:0] cyc_cnt = {W{1'b0}};
    reg [W-1:0] win_tmr = {W{1'b0}};
    reg [W-1:0] target  = {W{1'b0}};
    reg up_req = 1'b0;
    reg dn_req = 1'b0;
    reg armed  = 1'b0;

    initial osc_code = {W{1'b0}};
    initial locked   = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            state   <= S_IDLE;
            cyc_cnt <= {W{1'b0}};
            win_tmr <= {W{1'b0}};
            up_req  <= 1'b0;
            dn_req  <= 1'b0;
            locked  <= 1'b0;
        end else if (ce) begin
            case (state)
                S_IDLE: begin
                    if (tgt_load) target <= tgt_in;
                    cyc_cnt <= {W{1'b0}};
                    win_tmr <= WINDOW;
                    armed   <= 1'b1;
                    state   <= S_COUNT;
                end
                S_COUNT: begin
                    if (osc_tick) cyc_cnt <= cyc_cnt + 1'b1;
                    win_tmr <= win_tmr - 1'b1;
                    if (win_tmr == 1) state <= S_CMP;
                end
                S_CMP: begin
                    up_req <= (cyc_cnt < target);
                    dn_req <= (cyc_cnt > target);
                    state  <= S_ADJ;
                end
                S_ADJ: begin
                    if (up_req)      osc_code <= osc_code + 1'b1;
                    else if (dn_req) osc_code <= osc_code - 1'b1;
                    locked <= !up_req && !dn_req;
                    up_req <= 1'b0;
                    dn_req <= 1'b0;
                    state  <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        assert (!armed || !(state == S_CMP && cyc_cnt > WINDOW));
endmodule

module wc_buffer #(
    parameter LINE_BYTES = 8
) (
    input  wire                      clk,
    input  wire                      in_valid,
    output wire                      in_ready,
    input  wire [63:0]               in_addr,
    input  wire [8*LINE_BYTES-1:0]   in_data,
    input  wire [LINE_BYTES-1:0]     in_be,
    input  wire                      i_flush,
    output wire                      out_valid,
    input  wire                      out_ready,
    output wire [63:0]               out_addr,
    output wire [8*LINE_BYTES-1:0]   out_data,
    output wire [LINE_BYTES-1:0]     out_mask,
    output wire [63:0]               o_bursts
);
    localparam W = 8*LINE_BYTES;
    localparam [LINE_BYTES-1:0] FULL = {LINE_BYTES{1'b1}};

    reg                  buf_valid      = 1'b0;
    reg [63:0]           buf_addr       = 64'd0;
    reg [W-1:0]          buf_data       = {W{1'b0}};
    reg [LINE_BYTES-1:0] buf_mask       = {LINE_BYTES{1'b0}};
    reg [63:0]           buf_cnt        = 64'd0;
    reg                  draining       = 1'b0;
    reg [63:0]           acc_stores     = 64'd0;
    reg [63:0]           flushed_stores = 64'd0;
    reg [63:0]           bursts         = 64'd0;

    wire [W-1:0] be_bits;
    genvar i;
    generate
        for (i = 0; i < LINE_BYTES; i = i + 1) begin : g_be
            assign be_bits[8*i +: 8] = {8{in_be[i]}};
        end
    endgenerate

    wire same_line = buf_valid && (in_addr == buf_addr);
    assign in_ready  = !draining && (!buf_valid || same_line);
    wire in_fire     = in_valid && in_ready;
    assign out_valid = draining;
    wire out_fire    = out_valid && out_ready;

    wire [W-1:0]          base     = buf_valid ? buf_data : {W{1'b0}};
    wire [W-1:0]          merged   = (base & ~be_bits) | (in_data & be_bits);
    wire [LINE_BYTES-1:0] new_mask = (buf_valid ? buf_mask : {LINE_BYTES{1'b0}}) | in_be;

    always @(posedge clk) begin
        if (out_fire) begin
            buf_valid      <= 1'b0;
            buf_mask       <= {LINE_BYTES{1'b0}};
            buf_cnt        <= 64'd0;
            draining       <= 1'b0;
            flushed_stores <= flushed_stores + buf_cnt;
            bursts         <= bursts + 64'd1;
        end else if (in_fire && (in_be != {LINE_BYTES{1'b0}})) begin
            buf_valid  <= 1'b1;
            if (!buf_valid) buf_addr <= in_addr;
            buf_data   <= merged;
            buf_mask   <= new_mask;
            buf_cnt    <= buf_cnt + 64'd1;
            acc_stores <= acc_stores + 64'd1;
            if (new_mask == FULL) draining <= 1'b1;
        end else if (buf_valid && !draining && ((in_valid && !same_line) || i_flush)) begin
            draining <= 1'b1;
        end
    end

    assign out_addr = buf_addr;
    assign out_data = buf_data;
    assign out_mask = buf_mask;
    assign o_bursts = bursts;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(out_valid && out_ready))
            assert (acc_stores == flushed_stores);
endmodule

module an_arbiter #(
    parameter W = 64,
    parameter NPAGES = 2,
    parameter [63:0] LINK_TIME = 64'd6,
    parameter [63:0] LOCAL_ABIL = 64'h0000_0000_0000_01E0
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          page_valid,
    input  wire [W-1:0]  page_data,
    output wire          page_ready,
    input  wire          tick,
    input  wire          restart,
    output wire          link_up,
    output reg  [W-1:0]  resolved_mode
);
    localparam [1:0] ST_BASE = 2'd0;
    localparam [1:0] ST_NEXT = 2'd1;
    localparam [1:0] ST_WAIT = 2'd2;
    localparam [1:0] ST_DONE = 2'd3;

    reg [1:0]          neg_state  = ST_BASE;
    reg [W-1:0]        link_timer = {W{1'b0}};
    reg [NPAGES*W-1:0] rx_abil    = {(NPAGES*W){1'b0}};
    reg                win        = 1'b0;
    reg                pv         = 1'b0;
    initial resolved_mode = {W{1'b0}};

    assign page_ready = (neg_state == ST_BASE) || (neg_state == ST_NEXT);
    wire accept = page_valid && page_ready;
    assign link_up = (neg_state == ST_DONE);
    wire tmr_expired = (link_timer == {W{1'b0}});
    wire tmr_last    = (link_timer == {{(W-1){1'b0}}, 1'b1});

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            neg_state     <= ST_BASE;
            link_timer    <= {W{1'b0}};
            rx_abil       <= {(NPAGES*W){1'b0}};
            win           <= 1'b0;
            resolved_mode <= {W{1'b0}};
        end else begin
            if (tick && !tmr_expired)
                link_timer <= link_timer - {{(W-1){1'b0}}, 1'b1};
            case (neg_state)
                ST_BASE: if (accept) begin
                    rx_abil[W-1:0] <= page_data;
                    neg_state      <= ST_NEXT;
                end
                ST_NEXT: if (accept) begin
                    rx_abil[2*W-1:W] <= page_data;
                    neg_state        <= ST_WAIT;
                    link_timer       <= LINK_TIME;
                    win              <= 1'b1;
                end
                ST_WAIT: if (tick && tmr_last) begin
                    neg_state     <= ST_DONE;
                    win           <= 1'b0;
                    resolved_mode <= (rx_abil[W-1:0] | rx_abil[2*W-1:W]) & LOCAL_ABIL;
                end
                ST_DONE: if (restart) begin
                    neg_state <= ST_BASE;
                end
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && win) assert (!$rose(tmr_expired));
endmodule

module wallace_pipe_mul #(
    parameter W = 16
) (
    input  wire           clk,
    input  wire           rst_n,
    input  wire           ce,
    input  wire           in_valid,
    input  wire           clr_window,
    input  wire [W-1:0]   in_a,
    input  wire [W-1:0]   in_b,
    output wire [2*W-1:0] o_product,
    output wire           o_valid,
    output wire [31:0]    o_inflight
);
    localparam P = 2*W;
    localparam [31:0] STAGES = 32'd3;

    function integer rows_at;
        input integer lvl;
        integer k, r;
        begin
            r = W;
            for (k = 0; k < lvl; k = k + 1)
                if (r > 2) r = 2*(r/3) + (r%3);
            rows_at = r;
        end
    endfunction

    function integer num_levels;
        input integer dummy;
        integer k, r, n;
        begin
            r = W; n = 0;
            for (k = 0; k < 64; k = k + 1)
                if (r > 2) begin
                    r = 2*(r/3) + (r%3);
                    n = n + 1;
                end
            num_levels = n;
        end
    endfunction

    localparam integer NLEV = num_levels(0);

    reg [W-1:0] s1_a = {W{1'b0}};
    reg [W-1:0] s1_b = {W{1'b0}};
    reg         v1 = 1'b0;
    reg [P-1:0] s2_sum = {P{1'b0}};
    reg [P-1:0] s2_carry = {P{1'b0}};
    reg         v2 = 1'b0;
    reg [P-1:0] s3_prod = {P{1'b0}};
    reg         v3 = 1'b0;
    reg [31:0]  inflight = 32'd0;
    reg         armed = 1'b0;

    wire [(NLEV+1)*W*P-1:0] tree;

    genvar j, L, i;
    generate
        for (j = 0; j < W; j = j + 1) begin : pp
            assign tree[j*P +: P] = s1_b[j] ? ({{W{1'b0}}, s1_a} << j) : {P{1'b0}};
        end
        for (L = 0; L < NLEV; L = L + 1) begin : lev
            localparam integer NR = rows_at(L);
            localparam integer NG = NR / 3;
            localparam integer NP = NR - 3*NG;
            for (i = 0; i < NG; i = i + 1) begin : csa
                wire [P-1:0] xa = tree[(L*W + 3*i)*P +: P];
                wire [P-1:0] xb = tree[(L*W + 3*i + 1)*P +: P];
                wire [P-1:0] xc = tree[(L*W + 3*i + 2)*P +: P];
                assign tree[((L+1)*W + 2*i)*P +: P]     = xa ^ xb ^ xc;
                assign tree[((L+1)*W + 2*i + 1)*P +: P] = ((xa & xb) | (xa & xc) | (xb & xc)) << 1;
            end
            for (i = 0; i < NP; i = i + 1) begin : pass
                assign tree[((L+1)*W + 2*NG + i)*P +: P] = tree[(L*W + 3*NG + i)*P +: P];
            end
            for (i = 2*NG + NP; i < W; i = i + 1) begin : unused
                assign tree[((L+1)*W + i)*P +: P] = {P{1'b0}};
            end
        end
    endgenerate

    wire [P-1:0] cs_sum   = tree[(NLEV*W)*P +: P];
    wire [P-1:0] cs_carry = tree[(NLEV*W + 1)*P +: P];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            s1_a     <= {W{1'b0}};
            s1_b     <= {W{1'b0}};
            v1       <= 1'b0;
            s2_sum   <= {P{1'b0}};
            s2_carry <= {P{1'b0}};
            v2       <= 1'b0;
            s3_prod  <= {P{1'b0}};
            v3       <= 1'b0;
            inflight <= 32'd0;
            armed    <= 1'b0;
        end else if (ce) begin
            s1_a     <= in_a;
            s1_b     <= in_b;
            v1       <= in_valid;
            s2_sum   <= cs_sum;
            s2_carry <= cs_carry;
            v2       <= v1;
            s3_prod  <= s2_sum + s2_carry;
            v3       <= v2;
            inflight <= inflight + {31'd0, in_valid} - {31'd0, v3};
            if (clr_window)
                armed <= 1'b0;
            else if (in_valid)
                armed <= 1'b1;
        end
    end

    assign o_product  = s3_prod;
    assign o_valid    = v3;
    assign o_inflight = inflight;

    assert property (!armed || (inflight <= STAGES));
endmodule

module ecc_scrubber #(
    parameter LINES = 16,
    parameter AW = 4,
    parameter DW = 128,
    parameter SW = 7,
    parameter TW = 4,
    parameter [TW-1:0] INTERVAL = 4'd9,
    parameter CW = 8
)(
    input  wire          clk,
    input  wire          tick,
    input  wire          rd_valid,
    output wire          rd_ready,
    input  wire [DW-1:0] rd_data,
    input  wire          rd_err,
    input  wire [SW-1:0] rd_syn,
    output wire [AW-1:0] rd_addr,
    output wire          wb_valid,
    input  wire          wb_ready,
    output reg  [AW-1:0] wb_addr,
    output reg  [DW-1:0] wb_data,
    output reg  [CW-1:0] err_count,
    output reg  [AW-1:0] scrub_addr,
    output reg  [LINES-1:0] err_map
);
    localparam [1:0] S_WAIT = 2'd0;
    localparam [1:0] S_READ = 2'd1;
    localparam [1:0] S_WB   = 2'd2;

    reg [1:0]    phase;
    reg [TW-1:0] timer;
    reg          first_pass;

    initial begin
        phase      = S_WAIT;
        timer      = INTERVAL;
        wb_addr    = {AW{1'b0}};
        wb_data    = {DW{1'b0}};
        err_count  = {CW{1'b0}};
        scrub_addr = {AW{1'b0}};
        err_map    = {LINES{1'b0}};
        first_pass = 1'b1;
    end

    assign rd_ready = (phase == S_READ);
    assign wb_valid = (phase == S_WB);
    assign rd_addr  = scrub_addr;

    wire rd_fire    = rd_valid && rd_ready;
    wire done_clean = rd_fire && !rd_err;
    wire done_wb    = wb_valid && wb_ready;
    wire wrap_event = (done_clean && scrub_addr == LINES-1) ||
                      (done_wb && wb_addr == LINES-1);

    wire [DW-1:0] flip_mask = {{(DW-1){1'b0}}, 1'b1} << rd_syn;

    always @(posedge clk) begin
        case (phase)
            S_WAIT: begin
                if (tick) begin
                    if (timer == {TW{1'b0}}) begin
                        phase <= S_READ;
                        timer <= INTERVAL;
                    end else begin
                        timer <= timer - 1'b1;
                    end
                end
            end
            S_READ: begin
                if (rd_fire) begin
                    if (rd_err) begin
                        wb_data <= rd_data ^ flip_mask;
                        wb_addr <= scrub_addr;
                        phase   <= S_WB;
                    end else begin
                        scrub_addr <= scrub_addr + 1'b1;
                        phase      <= S_WAIT;
                    end
                end
            end
            S_WB: begin
                if (wb_ready) begin
                    scrub_addr       <= wb_addr + 1'b1;
                    err_map[wb_addr] <= 1'b1;
                    if (err_count != {CW{1'b1}})
                        err_count <= err_count + 1'b1;
                    phase <= S_WAIT;
                end
            end
            default: phase <= S_WAIT;
        endcase
        if (wrap_event)
            first_pass <= 1'b0;
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && first_pass && $stable(scrub_addr))
            assert ($stable(err_count));
endmodule

module heap_pq #(
    parameter DEPTH = 4,
    parameter KW    = 8,
    parameter IW    = 2,
    parameter SW    = 3,
    parameter LVL   = 2
) (
    input  wire          clk,
    input  wire          i_ce,
    input  wire          in_valid,
    input  wire          in_op,
    input  wire [KW-1:0] in_key,
    output wire          in_ready,
    output reg  [KW-1:0] o_key,
    output wire [SW-1:0] o_size,
    output wire          o_busy
);
    reg [DEPTH*KW-1:0] heap = {(DEPTH*KW){1'b0}};
    reg [SW-1:0] size  = {SW{1'b0}};
    reg          busy  = 1'b0;
    reg          dir   = 1'b0;
    reg [IW-1:0] idx   = {IW{1'b0}};
    reg [1:0]    timer = 2'd0;
    reg          armed = 1'b0;
    initial o_key = {KW{1'b0}};

    assign in_ready = i_ce && !busy && (in_op ? (size != {SW{1'b0}}) : (size != DEPTH));
    wire accept = in_valid && in_ready;
    assign o_size = size;
    assign o_busy = busy;

    wire [IW-1:0] last   = size - 1'b1;
    wire [KW-1:0] k_root = heap[KW-1:0];
    wire [KW-1:0] k_last = heap[last*KW +: KW];
    wire [KW-1:0] k_idx  = heap[idx*KW +: KW];

    // sift-up
    wire [IW-1:0] up_par  = (idx - 1'b1) >> 1;
    wire [KW-1:0] k_par   = heap[up_par*KW +: KW];
    wire          up_swap = (idx != {IW{1'b0}}) && (k_idx < k_par);

    // sift-down
    wire [SW:0]   lc    = {idx, 1'b1};
    wire [SW:0]   rc    = lc + 1'b1;
    wire [IW-1:0] lci   = lc[IW-1:0];
    wire [IW-1:0] rci   = rc[IW-1:0];
    wire [KW-1:0] k_lc  = heap[lci*KW +: KW];
    wire [KW-1:0] k_rc  = heap[rci*KW +: KW];
    wire          lc_ok = lc < {1'b0, size};
    wire          rc_ok = rc < {1'b0, size};
    wire          l_lt  = lc_ok && (k_lc < k_idx);
    wire [IW-1:0] sm1   = l_lt ? lci : idx;
    wire [KW-1:0] k_sm1 = l_lt ? k_lc : k_idx;
    wire          r_lt  = rc_ok && (k_rc < k_sm1);
    wire [IW-1:0] sm    = r_lt ? rci : sm1;
    wire [KW-1:0] k_sm  = r_lt ? k_rc : k_sm1;
    wire          dn_swap = (sm != idx);
    wire [SW:0]   sm_lc = {sm, 1'b1};
    wire          dn_more = sm_lc < {1'b0, size};

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
                armed <= 1'b1;
                timer <= LVL;
                if (!in_op) begin
                    heap[size[IW-1:0]*KW +: KW] <= in_key;
                    idx  <= size[IW-1:0];
                    size <= size + 1'b1;
                    busy <= (size != {SW{1'b0}});
                    dir  <= 1'b0;
                end else begin
                    o_key <= k_root;
                    heap[KW-1:0] <= k_last;
                    size  <= size - 1'b1;
                    idx   <= {IW{1'b0}};
                    busy  <= (size > 3'd2);
                    dir   <= 1'b1;
                end
            end else if (busy) begin
                if (!dir) begin
                    if (up_swap) begin
                        heap[idx*KW +: KW]    <= k_par;
                        heap[up_par*KW +: KW] <= k_idx;
                        idx   <= up_par;
                        timer <= timer - 1'b1;
                        busy  <= (up_par != {IW{1'b0}});
                        if (up_par == {IW{1'b0}}) armed <= 1'b0;
                    end else begin
                        busy  <= 1'b0;
                        armed <= 1'b0;
                    end
                end else begin
                    if (dn_swap) begin
                        heap[idx*KW +: KW] <= k_sm;
                        heap[sm*KW +: KW]  <= k_idx;
                        idx   <= sm;
                        timer <= timer - 1'b1;
                        busy  <= dn_more;
                        if (!dn_more) armed <= 1'b0;
                    end else begin
                        busy  <= 1'b0;
                        armed <= 1'b0;
                    end
                end
            end else begin
                armed <= 1'b0;
            end
        end
    end

    // bounded response: while the accepted request is still sifting, its budget never runs out
    always @(posedge clk)
        if (armed) assert (!busy || timer != 2'd0);
endmodule

module div3_serial_checker (
    input  wire clk,
    input  wire i_ce,
    input  wire i_arm,
    input  wire i_start,
    input  wire i_bit,
    output wire o_verdict,
    output wire o_done
);
    parameter WIDTH = 32;

    typedef enum logic [1:0] {IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3} ctl_t;
    typedef enum logic [1:0] {R0 = 2'd0, R1 = 2'd1, R2 = 2'd2} rem_t;

    ctl_t ctl = IDLE;
    rem_t rem = R0;
    reg [WIDTH-1:0] value = {WIDTH{1'b0}};
    reg [WIDTH-1:0] nbits = {WIDTH{1'b0}};
    reg armed = 1'b0;
    reg started = 1'b0;

    rem_t rem_next;
    always @(*) begin
        case (rem)
            R0: rem_next = i_bit ? R1 : R0;
            R1: rem_next = i_bit ? R0 : R2;
            R2: rem_next = i_bit ? R2 : R1;
            default: rem_next = R0;
        endcase
    end

    always @(posedge clk) begin
        if (i_ce) begin
            case (ctl)
                IDLE: begin
                    if (i_arm) begin
                        ctl   <= ARMED;
                        armed <= 1'b1;
                    end
                end
                ARMED: begin
                    if (i_start) begin
                        ctl     <= RUN;
                        started <= 1'b1;
                        value   <= {WIDTH{1'b0}};
                        nbits   <= {WIDTH{1'b0}};
                        rem     <= R0;
                    end
                end
                RUN: begin
                    value <= {value[WIDTH-2:0], i_bit};
                    nbits <= nbits + 1'b1;
                    rem   <= rem_next;
                    if (nbits == WIDTH-1)
                        ctl <= DONE;
                end
                DONE: begin
                    if (i_arm)
                        ctl <= ARMED;
                end
                default: ctl <= IDLE;
            endcase
        end
    end

    assign o_done    = (ctl == DONE);
    assign o_verdict = (ctl == DONE) && (rem == R0);

    always @(*)
        assert (!(armed && ctl == DONE && rem == R0) || (started && (value % 32'd3) == 32'd0));
endmodule

module desc_prefetch_cache #(
    parameter DEPTH = 32,
    parameter AW = $clog2(DEPTH)
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        step,
    input  wire        fetch_req,
    input  wire        consume_req,
    input  wire        flush,
    input  wire [63:0] desc_in,
    input  wire [63:0] lookup_addr,
    output reg         out_valid,
    output reg  [63:0] out_tag,
    output reg  [63:0] out_desc,
    output reg         lookup_hit
);
    localparam [63:0] DEPTH64 = DEPTH;

    reg [DEPTH-1:0] valid;
    reg [63:0] tag_mem  [0:DEPTH-1];
    reg [63:0] data_mem [0:DEPTH-1];
    reg [AW-1:0] wr_ptr;
    reg [AW-1:0] rd_ptr;
    reg [AW:0]   count;
    reg [63:0] next_fetch;
    reg [63:0] head_addr;
    reg [63:0] fetch_seen;
    reg [63:0] consume_seen;
    reg        before_flush;

    integer i;
    initial begin
        valid = {DEPTH{1'b0}};
        for (i = 0; i < DEPTH; i = i + 1) begin
            tag_mem[i]  = 64'd0;
            data_mem[i] = 64'd0;
        end
        wr_ptr = {AW{1'b0}};
        rd_ptr = {AW{1'b0}};
        count = {(AW+1){1'b0}};
        next_fetch = 64'd0;
        head_addr = 64'd0;
        fetch_seen = 64'd0;
        consume_seen = 64'd0;
        before_flush = 1'b1;
        out_valid = 1'b0;
        out_tag = 64'd0;
        out_desc = 64'd0;
    end

    wire do_fetch   = step && !flush && fetch_req && (count < DEPTH);
    wire do_consume = step && !flush && consume_req && (count != 0);

    integer j;
    always @(*) begin
        lookup_hit = 1'b0;
        for (j = 0; j < DEPTH; j = j + 1)
            if (valid[j] && tag_mem[j] == lookup_addr)
                lookup_hit = 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            valid <= {DEPTH{1'b0}};
            wr_ptr <= {AW{1'b0}};
            rd_ptr <= {AW{1'b0}};
            count <= {(AW+1){1'b0}};
            next_fetch <= 64'd0;
            head_addr <= 64'd0;
            fetch_seen <= 64'd0;
            consume_seen <= 64'd0;
            before_flush <= 1'b1;
            out_valid <= 1'b0;
            out_tag <= 64'd0;
            out_desc <= 64'd0;
        end else if (step) begin
            if (flush) begin
                valid <= {DEPTH{1'b0}};
                count <= {(AW+1){1'b0}};
                rd_ptr <= wr_ptr;
                head_addr <= next_fetch;
                out_valid <= 1'b0;
                before_flush <= 1'b0;
            end else begin
                out_valid <= do_consume;
                if (do_fetch) begin
                    tag_mem[wr_ptr]  <= next_fetch;
                    data_mem[wr_ptr] <= desc_in;
                    valid[wr_ptr] <= 1'b1;
                    wr_ptr <= wr_ptr + 1'b1;
                    next_fetch <= next_fetch + 64'd1;
                    fetch_seen <= fetch_seen + 64'd1;
                end
                if (do_consume) begin
                    valid[rd_ptr] <= 1'b0;
                    rd_ptr <= rd_ptr + 1'b1;
                    head_addr <= head_addr + 64'd1;
                    consume_seen <= consume_seen + 64'd1;
                    out_tag <= head_addr;
                    out_desc <= data_mem[rd_ptr];
                end
                case ({do_fetch, do_consume})
                    2'b10:   count <= count + 1'b1;
                    2'b01:   count <= count - 1'b1;
                    default: count <= count;
                endcase
            end
        end
    end

    // Precedence, before flush: a delivered descriptor must have been fetched earlier
    always @(posedge clk)
        if (before_flush && out_valid)
            assert ((fetch_seen - out_tag - 64'd1) <= DEPTH64);

    // Precedence, before flush: every consume was preceded by a fetch
    always @(posedge clk)
        if (before_flush)
            assert ((fetch_seen - consume_seen) <= DEPTH64);
endmodule

module wallace_pipe_mul (
    input  wire          i_clk,
    input  wire          i_reset,
    input  wire          i_ce,
    input  wire          i_valid,
    input  wire [15:0]   i_a,
    input  wire [15:0]   i_b,
    input  wire          i_open,
    input  wire          i_close,
    output wire [31:0]   o_prod,
    output wire          o_valid,
    output wire          o_empty
);
    parameter W = 16;
    localparam PW = 2*W;

    function [PW-1:0] csa_s;
        input [PW-1:0] x, y, z;
        csa_s = x ^ y ^ z;
    endfunction

    function [PW-1:0] csa_c;
        input [PW-1:0] x, y, z;
        csa_c = ((x & y) | (x & z) | (y & z)) << 1;
    endfunction

    // partial products
    wire [PW-1:0] pp [0:W-1];
    genvar g;
    generate
        for (g = 0; g < W; g = g + 1) begin : g_pp
            assign pp[g] = i_a[g] ? ({{W{1'b0}}, i_b} << g) : {PW{1'b0}};
        end
    endgenerate

    // Wallace level 1: 16 -> 11
    wire [PW-1:0] l1 [0:10];
    generate
        for (g = 0; g < 5; g = g + 1) begin : g_l1
            assign l1[2*g]   = csa_s(pp[3*g], pp[3*g+1], pp[3*g+2]);
            assign l1[2*g+1] = csa_c(pp[3*g], pp[3*g+1], pp[3*g+2]);
        end
    endgenerate
    assign l1[10] = pp[15];

    // level 2: 11 -> 8
    wire [PW-1:0] l2 [0:7];
    generate
        for (g = 0; g < 3; g = g + 1) begin : g_l2
            assign l2[2*g]   = csa_s(l1[3*g], l1[3*g+1], l1[3*g+2]);
            assign l2[2*g+1] = csa_c(l1[3*g], l1[3*g+1], l1[3*g+2]);
        end
    endgenerate
    assign l2[6] = l1[9];
    assign l2[7] = l1[10];

    // level 3: 8 -> 6
    wire [PW-1:0] l3 [0:5];
    generate
        for (g = 0; g < 2; g = g + 1) begin : g_l3
            assign l3[2*g]   = csa_s(l2[3*g], l2[3*g+1], l2[3*g+2]);
            assign l3[2*g+1] = csa_c(l2[3*g], l2[3*g+1], l2[3*g+2]);
        end
    endgenerate
    assign l3[4] = l2[6];
    assign l3[5] = l2[7];

    // level 4: 6 -> 4
    wire [PW-1:0] l4 [0:3];
    generate
        for (g = 0; g < 2; g = g + 1) begin : g_l4
            assign l4[2*g]   = csa_s(l3[3*g], l3[3*g+1], l3[3*g+2]);
            assign l4[2*g+1] = csa_c(l3[3*g], l3[3*g+1], l3[3*g+2]);
        end
    endgenerate

    // stage 1 pipeline registers (4 rows)
    reg [PW-1:0] r1_0, r1_1, r1_2, r1_3;
    reg          v1;
    initial begin r1_0 = 0; r1_1 = 0; r1_2 = 0; r1_3 = 0; v1 = 1'b0; end

    // level 5: 4 -> 3, level 6: 3 -> 2
    wire [PW-1:0] s5 = csa_s(r1_0, r1_1, r1_2);
    wire [PW-1:0] c5 = csa_c(r1_0, r1_1, r1_2);
    wire [PW-1:0] s6 = csa_s(s5, c5, r1_3);
    wire [PW-1:0] c6 = csa_c(s5, c5, r1_3);

    // stage 2 pipeline registers (carry-save pair)
    reg [PW-1:0] s2, c2;
    reg          v2;
    initial begin s2 = 0; c2 = 0; v2 = 1'b0; end

    // stage 3: final carry-propagate adder
    reg [PW-1:0] prod;
    reg          v3;
    initial begin prod = 0; v3 = 1'b0; end

    // occupancy counter and observation window
    reg [W-1:0] inflight;
    reg         win;
    initial begin inflight = {W{1'b0}}; win = 1'b0; end

    always @(posedge i_clk) begin
        if (i_reset) begin
            r1_0 <= 0; r1_1 <= 0; r1_2 <= 0; r1_3 <= 0;
            s2 <= 0; c2 <= 0; prod <= 0;
            v1 <= 1'b0; v2 <= 1'b0; v3 <= 1'b0;
            inflight <= {W{1'b0}};
            win <= 1'b0;
        end else if (i_ce) begin
            r1_0 <= l4[0]; r1_1 <= l4[1]; r1_2 <= l4[2]; r1_3 <= l4[3];
            s2   <= s6;    c2   <= c6;
            prod <= s2 + c2;
            v1 <= i_valid;
            v2 <= v1;
            v3 <= v2;
            inflight <= inflight + {{(W-1){1'b0}}, i_valid} - {{(W-1){1'b0}}, v3};
            if (i_open)
                win <= 1'b1;
            else if (i_close)
                win <= 1'b0;
        end
    end

    wire empty = (inflight == {W{1'b0}});

    assign o_prod  = prod;
    assign o_valid = v3;
    assign o_empty = empty;

    // Absence, between open and close: empty flag and output-valid never together
    always @(*)
        assert (!win || !(empty && v3));
endmodule

module ldpc_cnp #(
    parameter DEG = 32,
    parameter W   = 16
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_data,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_data
);
    localparam IW = $clog2(DEG);

    reg [W-1:0]   cnt       = {W{1'b0}};
    reg [W-1:0]   oidx      = {W{1'b0}};
    reg           out_phase = 1'b0;
    reg [W-2:0]   min1      = {(W-1){1'b1}};
    reg [W-2:0]   min2      = {(W-1){1'b1}};
    reg [W-1:0]   min_idx   = {W{1'b0}};
    reg           sign_prod = 1'b0;
    reg [DEG-1:0] sign_mem  = {DEG{1'b0}};
    reg           armed     = 1'b0;

    assign in_ready  = !out_phase;
    assign out_valid = out_phase;

    wire          accept = in_valid && in_ready;
    wire          emit   = out_valid && out_ready;
    wire          in_sgn = in_data[W-1];
    wire [W-2:0]  in_mag = in_data[W-2:0];

    assign out_data = { sign_prod ^ sign_mem[oidx[IW-1:0]],
                        (oidx == min_idx) ? min2 : min1 };

    always @(posedge clk) begin
        if (accept) armed <= 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            cnt       <= {W{1'b0}};
            oidx      <= {W{1'b0}};
            out_phase <= 1'b0;
            min1      <= {(W-1){1'b1}};
            min2      <= {(W-1){1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
        end else if (accept) begin
            sign_mem[cnt[IW-1:0]] <= in_sgn;
            sign_prod <= sign_prod ^ in_sgn;
            if (in_mag < min1) begin
                min2    <= min1;
                min1    <= in_mag;
                min_idx <= cnt;
            end else if (in_mag < min2) begin
                min2 <= in_mag;
            end
            cnt <= cnt + 1'b1;
            if (cnt == DEG - 1)
                out_phase <= 1'b1;
        end else if (emit) begin
            if (oidx == DEG - 1) begin
                oidx      <= {W{1'b0}};
                cnt       <= {W{1'b0}};
                out_phase <= 1'b0;
                min1      <= {(W-1){1'b1}};
                min2      <= {(W-1){1'b1}};
                min_idx   <= {W{1'b0}};
                sign_prod <= 1'b0;
            end else begin
                oidx <= oidx + 1'b1;
            end
        end
    end

    assert property (!armed || cnt <= DEG);
endmodule

module frame_beat_ripple #(
    parameter W = 32,
    parameter MAX_BEATS = 12
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         s_valid,
    input  wire         s_last,
    output wire         s_ready,
    output wire         m_valid,
    input  wire         m_ready,
    output wire [W-1:0] m_count
);
    typedef enum logic [1:0] {IDLE = 2'd0, COUNTING = 2'd1, DONE = 2'd2} state_t;

    localparam [W-1:0] LIMIT    = MAX_BEATS;
    localparam [W-1:0] LAST_IDX = MAX_BEATS - 1;

    state_t state;
    reg in_frame;
    reg [W-1:0] q;
    integer i;

    initial begin
        state    = IDLE;
        in_frame = 1'b0;
        q        = {W{1'b0}};
    end

    assign s_ready = (state != DONE);
    assign m_valid = (state == DONE);
    assign m_count = q;

    wire accept = s_valid && s_ready;
    wire drain  = m_valid && m_ready;

    // Ripple chain of toggle flip-flops: stage 0 toggles on each accepted
    // beat; stage g toggles when stage g-1 falls from 1 to 0 (its 'clock').
    wire [W-1:0] t;
    assign t[0] = accept;
    genvar g;
    generate
        for (g = 1; g < W; g = g + 1) begin : rip
            assign t[g] = t[g-1] & q[g-1];
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            state    <= IDLE;
            in_frame <= 1'b0;
            q        <= {W{1'b0}};
        end else begin
            if (drain)
                q <= {W{1'b0}};
            else
                for (i = 0; i < W; i = i + 1)
                    if (t[i]) q[i] <= ~q[i];

            case (state)
                IDLE: begin
                    if (accept) begin
                        in_frame <= 1'b1;
                        state    <= (s_last || q == LAST_IDX) ? DONE : COUNTING;
                    end
                end
                COUNTING: begin
                    if (accept && (s_last || q == LAST_IDX))
                        state <= DONE;
                end
                DONE: begin
                    if (drain) begin
                        state    <= IDLE;
                        in_frame <= 1'b0;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    always @(posedge clk)
        if (in_frame) assert (q <= LIMIT);
endmodule

module ntt_butterfly #(
    parameter N = 64,
    parameter LOGN = 6,
    parameter [31:0] Q = 32'd3329
)(
    input  wire        clk,
    // twiddle factor channel (arm)
    input  wire        tw_valid,
    output wire        tw_ready,
    input  wire [31:0] tw_in,
    // coefficient operand channel (start)
    input  wire        in_valid,
    output wire        in_ready,
    input  wire [31:0] in_a,
    input  wire [31:0] in_b,
    // butterfly result channel (finish)
    output wire        out_valid,
    input  wire        out_ready,
    output wire [31:0] out_a,
    output wire [31:0] out_b,
    output wire [31:0] o_stage,
    output wire [31:0] o_idx
);
    localparam [31:0] HALF = N / 2;
    localparam [23:0] Q24  = Q;
    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_ARMED = 2'd1;
    localparam [1:0] P_DONE  = 2'd2;

    reg [1:0]  phase   = P_IDLE;
    reg [31:0] tw      = 32'd0;
    reg [31:0] res_a   = 32'd0;
    reg [31:0] res_b   = 32'd0;
    reg [31:0] stage   = 32'd0;
    reg [31:0] idx     = 32'd0;
    reg [31:0] grp_cnt = 32'd0;
    reg        arm_seen   = 1'b0;
    reg        start_seen = 1'b0;
    reg        before_r   = 1'b1;

    assign tw_ready  = (phase == P_IDLE);
    assign in_ready  = (phase == P_ARMED);
    assign out_valid = (phase == P_DONE);
    assign out_a     = res_a;
    assign out_b     = res_b;
    assign o_stage   = stage;
    assign o_idx     = idx;

    wire tw_fire  = tw_valid && tw_ready;
    wire in_fire  = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    wire [31:0] glen          = HALF >> stage;
    wire        last_in_stage = (idx == HALF - 32'd1);
    wire        last_stage    = (stage == LOGN - 1);
    wire        last_in_group = (grp_cnt + 32'd1 == glen);

    // Cooley-Tukey butterfly: (a + w*b, a - w*b) mod Q
    wire [23:0] prod = tw[11:0] * in_b[11:0];
    wire [23:0] t24  = prod % Q24;
    wire [31:0] t    = {8'd0, t24};
    wire [31:0] sum  = in_a + t;
    wire [31:0] bf_a = (sum >= Q) ? (sum - Q) : sum;
    wire [31:0] dif  = in_a + Q - t;
    wire [31:0] bf_b = (dif >= Q) ? (dif - Q) : dif;

    always @(posedge clk) begin
        if (tw_fire) begin
            tw       <= tw_in;
            phase    <= P_ARMED;
            arm_seen <= 1'b1;
        end
        if (in_fire) begin
            res_a      <= bf_a;
            res_b      <= bf_b;
            phase      <= P_DONE;
            start_seen <= 1'b1;
        end
        if (out_fire) begin
            if (last_in_stage) begin
                idx     <= 32'd0;
                grp_cnt <= 32'd0;
                phase   <= P_IDLE;
                if (last_stage) begin
                    stage    <= 32'd0;
                    before_r <= 1'b0;
                end else begin
                    stage <= stage + 32'd1;
                end
            end else begin
                idx <= idx + 32'd1;
                if (last_in_group) begin
                    grp_cnt <= 32'd0;
                    phase   <= P_IDLE;
                end else begin
                    grp_cnt <= grp_cnt + 32'd1;
                    phase   <= P_ARMED;
                end
            end
        end
    end

    // Chain precedence, before the first transform completes:
    // a result can only be offered after a twiddle was armed and operands started.
    always @(posedge clk) assert (!(before_r && out_valid) || (arm_seen && start_seen));
endmodule

module preload_timer #(
    parameter W = 64,
    parameter [W-1:0] INIT_PERIOD = 64'd7
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         tick,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_period,
    input  wire [W-1:0] in_cmp,
    output wire         match,
    output wire         reload_evt
);
    reg [W-1:0] cnt           = INIT_PERIOD;
    reg [W-1:0] period        = INIT_PERIOD;
    reg [W-1:0] cmp_active    = {W{1'b0}};
    reg [W-1:0] shadow_period = INIT_PERIOD;
    reg [W-1:0] shadow_cmp    = {W{1'b0}};
    reg [W-1:0] deadline      = {W{1'b0}};
    reg         pending       = 1'b0;
    reg         armed         = 1'b0;
    reg         pv            = 1'b0;

    assign in_ready   = !pending;
    wire   accept     = in_valid && in_ready;
    wire   due        = (deadline == {W{1'b0}});
    assign reload_evt = tick && (cnt == {W{1'b0}});
    assign match      = (cnt == cmp_active);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            cnt           <= INIT_PERIOD;
            period        <= INIT_PERIOD;
            cmp_active    <= {W{1'b0}};
            shadow_period <= INIT_PERIOD;
            shadow_cmp    <= {W{1'b0}};
            pending       <= 1'b0;
            deadline      <= {W{1'b0}};
        end else begin
            if (tick) begin
                if (cnt == {W{1'b0}}) begin
                    if (pending) begin
                        cnt        <= shadow_period;
                        period     <= shadow_period;
                        cmp_active <= shadow_cmp;
                        pending    <= 1'b0;
                    end else begin
                        cnt <= period;
                    end
                end else begin
                    cnt <= cnt - 1'b1;
                end
                if (pending && (cnt != {W{1'b0}}) && !due)
                    deadline <= deadline - 1'b1;
            end
            if (accept) begin
                shadow_period <= in_period;
                shadow_cmp    <= in_cmp;
                pending       <= 1'b1;
                armed         <= 1'b1;
                deadline      <= tick ? ((cnt == {W{1'b0}}) ? period : (cnt - 1'b1)) : cnt;
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && pending && $rose(due))
            assert (cnt == {W{1'b0}});
endmodule

module desc_prefetch_cache #(
    parameter DEPTH = 32,
    parameter DW = 16
)(
    input  wire          clk,
    input  wire          flush,
    input  wire [DW-1:0] flush_addr,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_desc,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_desc,
    output wire [DW-1:0] out_tag,
    output wire [DW-1:0] fetch_req_addr,
    input  wire [DW-1:0] lk_addr,
    output wire          lk_hit
);
    localparam AW = $clog2(DEPTH);

    reg [DW-1:0] desc_mem [0:DEPTH-1];
    reg [DW-1:0] tag_mem  [0:DEPTH-1];
    reg [DEPTH-1:0] valid = {DEPTH{1'b0}};
    reg [AW-1:0] wr_ptr = {AW{1'b0}};
    reg [AW-1:0] rd_ptr = {AW{1'b0}};
    reg [DW-1:0] count = {DW{1'b0}};
    reg [DW-1:0] fetch_addr = {DW{1'b0}};
    reg armed = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) begin
            desc_mem[i] = {DW{1'b0}};
            tag_mem[i]  = {DW{1'b0}};
        end
    end

    assign in_ready = !flush && (count != DEPTH);
    wire in_fire = in_valid && in_ready;
    wire push = in_fire && !valid[wr_ptr];
    assign out_valid = !flush && valid[rd_ptr];
    wire pop = out_valid && out_ready;

    assign out_desc = desc_mem[rd_ptr];
    assign out_tag = tag_mem[rd_ptr];
    assign fetch_req_addr = fetch_addr;

    wire [DEPTH-1:0] set_mask = push ? ({{(DEPTH-1){1'b0}}, 1'b1} << wr_ptr) : {DEPTH{1'b0}};
    wire [DEPTH-1:0] clr_mask = pop  ? ({{(DEPTH-1){1'b0}}, 1'b1} << rd_ptr) : {DEPTH{1'b0}};

    wire [DEPTH-1:0] exp_valid;
    wire [DEPTH-1:0] hit_vec;
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : g_slot
            wire [AW-1:0] off = g - rd_ptr;
            assign exp_valid[g] = ({{(DW-AW){1'b0}}, off} < count);
            assign hit_vec[g] = valid[g] && (tag_mem[g] == lk_addr);
        end
    endgenerate
    assign lk_hit = |hit_vec;

    always @(posedge clk) begin
        if (flush) begin
            valid <= {DEPTH{1'b0}};
            count <= {DW{1'b0}};
            rd_ptr <= wr_ptr;
            fetch_addr <= flush_addr;
            armed <= 1'b0;
        end else begin
            if (push) begin
                desc_mem[wr_ptr] <= in_desc;
                tag_mem[wr_ptr] <= fetch_addr;
                wr_ptr <= wr_ptr + 1'b1;
                armed <= 1'b1;
            end
            if (in_fire)
                fetch_addr <= fetch_addr + {{(DW-1){1'b0}}, 1'b1};
            if (pop)
                rd_ptr <= rd_ptr + 1'b1;
            valid <= (valid | set_mask) & ~clr_mask;
            count <= count + {{(DW-1){1'b0}}, push} - {{(DW-1){1'b0}}, pop};
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $stable(wr_ptr))
            assert ($stable(fetch_addr));
endmodule

module mem_autopd #(
    parameter W = 64,
    parameter [W-1:0] DEF_THRESH = 64'd4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         activity,
    input  wire         thr_we,
    input  wire [W-1:0] thr_din,
    output reg          pd_req,
    output reg  [W-1:0] idle_cnt
);
    typedef enum logic [1:0] {ACTIVE = 2'd0, COUNTING = 2'd1, POWERDN = 2'd2} state_t;

    state_t state;
    reg [W-1:0] threshold;
    reg pv;

    initial begin
        state     = ACTIVE;
        threshold = DEF_THRESH;
        pd_req    = 1'b0;
        idle_cnt  = {W{1'b0}};
        pv        = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (thr_we && state == ACTIVE)
                threshold <= thr_din;
            if (activity) begin
                state    <= ACTIVE;
                idle_cnt <= {W{1'b0}};
                pd_req   <= 1'b0;
            end else begin
                case (state)
                    ACTIVE: begin
                        state    <= COUNTING;
                        idle_cnt <= {{(W-1){1'b0}}, 1'b1};
                    end
                    COUNTING: begin
                        if (idle_cnt >= threshold) begin
                            state  <= POWERDN;
                            pd_req <= 1'b1;
                        end else begin
                            idle_cnt <= idle_cnt + {{(W-1){1'b0}}, 1'b1};
                        end
                    end
                    POWERDN: begin
                        state <= POWERDN;
                    end
                    default: begin
                        state    <= ACTIVE;
                        idle_cnt <= {W{1'b0}};
                        pd_req   <= 1'b0;
                    end
                endcase
            end
        end
    end

    always @(posedge clk)
        if (pv && pd_req && $stable(pd_req))
            assert ($stable(idle_cnt));
endmodule

module fll_cmp #(
    parameter [31:0] WINDOW      = 32'd32,
    parameter [31:0] TARGET_INIT = 32'd20
) (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_osc_tick,
    input  wire        i_set_target,
    input  wire [31:0] i_target,
    output wire [31:0] o_code,
    output wire        o_searching
);
    reg [31:0] cyc_cnt  = 32'd0;
    reg [31:0] win_tmr  = 32'd0;
    reg [31:0] target   = TARGET_INIT;
    reg [31:0] osc_code = 32'h80000000;
    reg        searching = 1'b1;

    wire        win_end   = (win_tmr == WINDOW - 32'd1);
    wire [31:0] final_cnt = cyc_cnt + {31'd0, i_osc_tick};

    always @(posedge clk) begin
        if (i_reset) begin
            cyc_cnt  <= 32'd0;
            win_tmr  <= 32'd0;
            target   <= TARGET_INIT;
            osc_code <= 32'h80000000;
        end else if (i_ce) begin
            if (i_set_target)
                target <= i_target;
            if (win_end) begin
                cyc_cnt <= 32'd0;
                win_tmr <= 32'd0;
                if (final_cnt < target) begin
                    if (osc_code != 32'hFFFFFFFF)
                        osc_code <= osc_code + 32'd1;
                end else if (final_cnt > target) begin
                    if (osc_code != 32'd0)
                        osc_code <= osc_code - 32'd1;
                end else begin
                    searching <= 1'b0;
                end
            end else begin
                win_tmr <= win_tmr + 32'd1;
                cyc_cnt <= final_cnt;
            end
        end
    end

    assign o_code      = osc_code;
    assign o_searching = searching;

    assert property (!searching || (cyc_cnt < WINDOW));
endmodule

module requant_unit #(
    parameter DATA_W  = 32,
    parameter OUT_W   = 8,
    parameter SHIFT_W = 6
) (
    input  wire               clk,
    input  wire               rst,
    input  wire               ce,
    input  wire               cfg_we,
    input  wire [DATA_W-1:0]  cfg_mult,
    input  wire [SHIFT_W-1:0] cfg_shift,
    input  wire               in_valid,
    input  wire [DATA_W-1:0]  acc_in,
    output wire [OUT_W-1:0]   q_out,
    output wire               q_valid
);
    localparam [DATA_W-1:0] CNT_MAX = {DATA_W{1'b1}};
    localparam signed [2*DATA_W-1:0] QMAX = {{(2*DATA_W-OUT_W+1){1'b0}}, {(OUT_W-1){1'b1}}};
    localparam signed [2*DATA_W-1:0] QMIN = {{(2*DATA_W-OUT_W+1){1'b1}}, {(OUT_W-1){1'b0}}};

    // configuration registers
    reg [DATA_W-1:0]  mult_r  = {DATA_W{1'b0}};
    reg [SHIFT_W-1:0] shift_r = {SHIFT_W{1'b0}};
    reg               armed   = 1'b0;            // sticky: first config write seen
    reg [DATA_W-1:0]  cfg_cnt = {DATA_W{1'b0}};  // config epoch (saturating)

    // output stage
    reg               out_valid = 1'b0;
    reg [OUT_W-1:0]   out_q     = {OUT_W{1'b0}};
    reg [DATA_W-1:0]  out_tag   = {DATA_W{1'b0}}; // shadow: epoch used by current output
    reg [DATA_W-1:0]  out_cnt   = {DATA_W{1'b0}}; // outputs produced (saturating)
    reg [DATA_W-1:0]  first_tag = {DATA_W{1'b0}}; // shadow: epoch used by first output

    wire fire = in_valid && armed;

    // requantization datapath: (acc * mult + round) >>> shift, saturated
    wire signed [2*DATA_W-1:0] prod   = $signed(acc_in) * $signed(mult_r);
    wire        [2*DATA_W-1:0] rnd_u  = (shift_r == {SHIFT_W{1'b0}}) ? {2*DATA_W{1'b0}} :
                                        ({{(2*DATA_W-1){1'b0}}, 1'b1} << (shift_r - 1'b1));
    wire signed [2*DATA_W-1:0] summed = prod + $signed(rnd_u);
    wire signed [2*DATA_W-1:0] scaled = summed >>> shift_r;
    wire        [OUT_W-1:0]    sat    = (scaled > QMAX) ? QMAX[OUT_W-1:0] :
                                        (scaled < QMIN) ? QMIN[OUT_W-1:0] :
                                        scaled[OUT_W-1:0];

    always @(posedge clk) begin
        if (rst) begin
            out_valid <= 1'b0;
            out_q     <= {OUT_W{1'b0}};
        end else if (ce) begin
            if (cfg_we) begin
                mult_r  <= cfg_mult;
                shift_r <= cfg_shift;
                armed   <= 1'b1;
                if (cfg_cnt != CNT_MAX)
                    cfg_cnt <= cfg_cnt + 1'b1;
            end
            out_valid <= fire;
            if (fire) begin
                out_q   <= sat;
                out_tag <= cfg_cnt;
                if (out_cnt == {DATA_W{1'b0}})
                    first_tag <= cfg_cnt;
                if (out_cnt != CNT_MAX)
                    out_cnt <= out_cnt + 1'b1;
            end
        end
    end

    assign q_out   = out_q;
    assign q_valid = out_valid;

    // Precedence, after first config write: an emitted sample must have been
    // produced under a configuration that was written earlier.
    always @(posedge clk)
        if (armed && out_valid)
            assert (out_tag != 32'd0);

    always @(posedge clk)
        if (armed && out_cnt != 32'd0)
            assert (first_tag != 32'd0);
endmodule

module heap_pq #(
    parameter DEPTH = 4,
    parameter W = 8
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         step,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_key,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_key
);
    localparam AW = $clog2(DEPTH);
    localparam [1:0] IDLE = 2'd0, LOAD = 2'd1, SIFT_UP = 2'd2, SIFT_DN = 2'd3;

    reg [1:0] state = IDLE;
    reg [DEPTH*W-1:0] heap = {(DEPTH*W){1'b0}};

    reg [31:0]  size      = 32'd0;
    reg [31:0]  idx       = 32'd0;
    reg [31:0]  armed_cnt = 32'd0;
    reg [31:0]  start_cnt = 32'd0;
    reg [31:0]  done_cnt  = 32'd0;
    reg [W-1:0] stage_key = {W{1'b0}};
    reg         win       = 1'b0;

    wire [31:0] szm1   = size - 32'd1;
    wire [31:0] parent = (idx - 32'd1) >> 1;
    wire [31:0] lc     = {idx[30:0], 1'b0} + 32'd1;
    wire [31:0] rc     = lc + 32'd1;

    wire [AW-1:0] a_idx = idx[AW-1:0];
    wire [AW-1:0] a_par = parent[AW-1:0];
    wire [AW-1:0] a_lc  = lc[AW-1:0];
    wire [AW-1:0] a_rc  = rc[AW-1:0];
    wire [AW-1:0] a_szm = szm1[AW-1:0];
    wire [AW-1:0] a_sz  = size[AW-1:0];

    wire [W-1:0] k_idx = heap[a_idx*W +: W];
    wire [W-1:0] k_par = heap[a_par*W +: W];
    wire [W-1:0] k_lc  = heap[a_lc*W +: W];
    wire [W-1:0] k_rc  = heap[a_rc*W +: W];
    wire [W-1:0] k_szm = heap[a_szm*W +: W];

    assign out_valid = (state == IDLE) && (size != 32'd0);
    assign out_key   = heap[W-1:0];
    wire pop  = step && out_valid && out_ready;
    assign in_ready  = step && (state == IDLE) && (size < DEPTH) && !pop;
    wire push = in_valid && in_ready;

    reg [31:0]  sm;
    reg [W-1:0] sm_key;
    always @(*) begin
        sm = idx;
        sm_key = k_idx;
        if (lc < size && k_lc < sm_key) begin sm = lc; sm_key = k_lc; end
        if (rc < size && k_rc < sm_key) begin sm = rc; sm_key = k_rc; end
    end
    wire [AW-1:0] a_sm = sm[AW-1:0];

    always @(posedge clk) begin
        if (rst) begin
            state     <= IDLE;
            size      <= 32'd0;
            idx       <= 32'd0;
            armed_cnt <= 32'd0;
            start_cnt <= 32'd0;
            done_cnt  <= 32'd0;
            stage_key <= {W{1'b0}};
            win       <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (pop) begin
                        heap[W-1:0] <= k_szm;
                        size   <= szm1;
                        idx    <= 32'd0;
                        state  <= SIFT_DN;
                        if (size == 32'd1) win <= 1'b0;
                    end else if (push) begin
                        stage_key <= in_key;
                        armed_cnt <= armed_cnt + 32'd1;
                        state     <= LOAD;
                        win       <= 1'b1;
                    end
                end
                LOAD: begin
                    if (step) begin
                        heap[a_sz*W +: W] <= stage_key;
                        idx       <= size;
                        size      <= size + 32'd1;
                        start_cnt <= start_cnt + 32'd1;
                        state     <= SIFT_UP;
                    end
                end
                SIFT_UP: begin
                    if (step) begin
                        if (idx == 32'd0 || k_par <= k_idx) begin
                            done_cnt <= done_cnt + 32'd1;
                            state    <= IDLE;
                        end else begin
                            heap[a_par*W +: W] <= k_idx;
                            heap[a_idx*W +: W] <= k_par;
                            idx <= parent;
                        end
                    end
                end
                SIFT_DN: begin
                    if (step) begin
                        if (sm == idx) begin
                            state <= IDLE;
                        end else begin
                            heap[a_idx*W +: W] <= sm_key;
                            heap[a_sm*W +: W]  <= k_idx;
                            idx <= sm;
                        end
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $past(state) == SIFT_UP && state == IDLE)
            assert ($past(start_cnt) == $past(done_cnt) + 32'd1 && $past(armed_cnt) == $past(start_cnt));
endmodule

module eye_scan_mon #(
    parameter W  = 128,
    parameter NS = 8,
    parameter NH = 8,
    parameter NV = 4,
    parameter CW = $clog2(NS),
    parameter HW = $clog2(NH),
    parameter VW = $clog2(NV),
    parameter EW = $clog2(NS) + 1
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          s_valid,
    output wire          s_ready,
    input  wire [W-1:0]  s_data,
    input  wire [W-1:0]  s_off,
    output reg           m_valid,
    input  wire          m_ready,
    output reg  [HW-1:0] m_hoff,
    output reg  [VW-1:0] m_voff,
    output reg  [EW-1:0] m_errs
);
    reg [HW-1:0]    hoff       = {HW{1'b0}};
    reg [VW-1:0]    voff       = {VW{1'b0}};
    reg [CW-1:0]    sample_cnt = {CW{1'b0}};
    reg [EW-1:0]    err_cnt    = {EW{1'b0}};
    reg [NH*EW-1:0] emap       = {(NH*EW){1'b0}};
    reg             armed      = 1'b1;

    initial m_valid = 1'b0;
    initial m_hoff  = {HW{1'b0}};
    initial m_voff  = {VW{1'b0}};
    initial m_errs  = {EW{1'b0}};

    assign s_ready = !m_valid;

    wire          s_fire    = s_valid && s_ready;
    wire          mis       = |(s_data ^ s_off);
    wire [EW-1:0] err_next  = err_cnt + {{(EW-1){1'b0}}, mis};
    wire          last      = (sample_cnt == NS-1);
    wire          scan_done = s_fire && last && (hoff == NH-1) && (voff == NV-1);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            hoff       <= {HW{1'b0}};
            voff       <= {VW{1'b0}};
            sample_cnt <= {CW{1'b0}};
            err_cnt    <= {EW{1'b0}};
            emap       <= {(NH*EW){1'b0}};
            armed      <= 1'b1;
            m_valid    <= 1'b0;
            m_hoff     <= {HW{1'b0}};
            m_voff     <= {VW{1'b0}};
            m_errs     <= {EW{1'b0}};
        end else begin
            if (m_valid && m_ready)
                m_valid <= 1'b0;
            if (s_fire) begin
                if (last) begin
                    sample_cnt <= {CW{1'b0}};
                    err_cnt    <= {EW{1'b0}};
                    m_valid    <= 1'b1;
                    m_errs     <= err_next;
                    m_hoff     <= hoff;
                    m_voff     <= voff;
                    emap[hoff*EW +: EW] <= err_next;
                    if (hoff == NH-1) begin
                        hoff <= {HW{1'b0}};
                        voff <= voff + 1'b1;
                    end else begin
                        hoff <= hoff + 1'b1;
                    end
                end else begin
                    sample_cnt <= sample_cnt + 1'b1;
                    err_cnt    <= err_next;
                end
            end
            if (scan_done)
                armed <= 1'b0;
        end
    end

    always @(posedge clk)
        if (armed) assert (err_cnt < NS);
endmodule

module warm_rst_quiesce #(
    parameter NPORTS = 4,
    parameter DW = 128,
    parameter TMO_CYCLES = 10,
    parameter TW = $clog2(TMO_CYCLES + 1)
) (
    input  wire              clk,
    // warm reset request stream (valid/ready), carries a 128-bit reset context word
    input  wire              wr_valid,
    output wire              wr_ready,
    input  wire [DW-1:0]     wr_ctx,
    // per-port drain/idle acknowledgments
    input  wire [NPORTS-1:0] ack_valid,
    output wire [NPORTS-1:0] ack_ready,
    // timeout timebase strobe
    input  wire              tick,
    // outgoing warm reset command (valid/ready)
    output wire              rst_valid,
    input  wire              rst_ready,
    output wire [DW-1:0]     rst_ctx,
    output wire              rst_forced,
    // block new bus transactions while quiescing / resetting
    output wire              blk_new
);
    localparam [TW-1:0] TMO_MAX = TMO_CYCLES;

    reg              qreq      = 1'b0;
    reg [NPORTS-1:0] ack       = {NPORTS{1'b0}};
    reg [TW-1:0]     tmo       = {TW{1'b0}};
    reg              rst_v     = 1'b0;
    reg              forced    = 1'b0;
    reg [DW-1:0]     ctx       = {DW{1'b0}};
    reg              qreq_seen = 1'b0;

    wire all_ack = &ack;

    assign wr_ready   = !qreq && !rst_v;
    assign ack_ready  = {NPORTS{qreq}};
    assign rst_valid  = rst_v;
    assign rst_ctx    = ctx;
    assign rst_forced = forced;
    assign blk_new    = qreq || rst_v;

    always @(posedge clk) begin
        if (wr_valid && wr_ready) begin
            qreq      <= 1'b1;
            ack       <= {NPORTS{1'b0}};
            tmo       <= {TW{1'b0}};
            ctx       <= wr_ctx;
            qreq_seen <= 1'b1;
        end else if (qreq) begin
            if (tick && (all_ack || tmo == TMO_MAX)) begin
                qreq   <= 1'b0;
                rst_v  <= 1'b1;
                forced <= !all_ack;
            end else begin
                ack <= ack | ack_valid;
                if (tick)
                    tmo <= tmo + 1'b1;
            end
        end else if (rst_v && rst_ready) begin
            rst_v     <= 1'b0;
            forced    <= 1'b0;
            qreq_seen <= 1'b0;
        end
    end

    // Precedence: a warm reset command is only presented after a quiesce request was accepted
    always @(posedge clk)
        if (rst_v)
            assert (qreq_seen);
endmodule

module fft_twiddle_rom #(
    parameter ENTRIES = 16,
    parameter AW = 4,
    parameter W = 16,
    parameter CW = 6
) (
    input wire clk,
    input wire rst,
    input wire ce,
    output reg [W-1:0] re_q,
    output reg [W-1:0] im_q,
    output reg [AW-1:0] idx_q
);
    // butterfly sequencing counter: position and stage fields
    reg [CW-1:0] cnt;
    wire [1:0]    stage = cnt[5:4];
    wire [AW-1:0] pos   = cnt[AW-1:0];
    wire [AW-1:0] k     = pos << stage;

    // ROM contents: cos(pi*k/16) and -sin(pi*k/16) in Q15
    wire [W-1:0] cos_k =
        (k == 4'd0)  ? 16'h7FFF :
        (k == 4'd1)  ? 16'h7D89 :
        (k == 4'd2)  ? 16'h7641 :
        (k == 4'd3)  ? 16'h6A6D :
        (k == 4'd4)  ? 16'h5A82 :
        (k == 4'd5)  ? 16'h471D :
        (k == 4'd6)  ? 16'h30FC :
        (k == 4'd7)  ? 16'h18F9 :
        (k == 4'd8)  ? 16'h0000 :
        (k == 4'd9)  ? 16'hE707 :
        (k == 4'd10) ? 16'hCF04 :
        (k == 4'd11) ? 16'hB8E3 :
        (k == 4'd12) ? 16'hA57E :
        (k == 4'd13) ? 16'h9593 :
        (k == 4'd14) ? 16'h89BF :
                       16'h8277;
    wire [W-1:0] msin_k =
        (k == 4'd0)  ? 16'h0000 :
        (k == 4'd1)  ? 16'hE707 :
        (k == 4'd2)  ? 16'hCF04 :
        (k == 4'd3)  ? 16'hB8E3 :
        (k == 4'd4)  ? 16'hA57E :
        (k == 4'd5)  ? 16'h9593 :
        (k == 4'd6)  ? 16'h89BF :
        (k == 4'd7)  ? 16'h8277 :
        (k == 4'd8)  ? 16'h8001 :
        (k == 4'd9)  ? 16'h8277 :
        (k == 4'd10) ? 16'h89BF :
        (k == 4'd11) ? 16'h9593 :
        (k == 4'd12) ? 16'hA57E :
        (k == 4'd13) ? 16'hB8E3 :
        (k == 4'd14) ? 16'hCF04 :
                       16'hE707;

    // registered ROM read stage
    reg [W-1:0]  re_d;
    reg [W-1:0]  im_d;
    reg [AW-1:0] idx_d;

    initial cnt = {CW{1'b0}};
    initial re_d = 16'h7FFF;
    initial im_d = 16'h0000;
    initial idx_d = {AW{1'b0}};
    initial re_q = 16'h7FFF;
    initial im_q = 16'h0000;
    initial idx_q = {AW{1'b0}};

    always @(posedge clk) begin
        if (rst) begin
            cnt   <= {CW{1'b0}};
            re_d  <= 16'h7FFF;
            im_d  <= 16'h0000;
            idx_d <= {AW{1'b0}};
            re_q  <= 16'h7FFF;
            im_q  <= 16'h0000;
            idx_q <= {AW{1'b0}};
        end else if (ce) begin
            cnt   <= cnt + 1'b1;
            idx_d <= k;
            re_d  <= cos_k;
            im_d  <= msin_k;
            idx_q <= idx_d;
            re_q  <= re_d;
            im_q  <= im_d;
        end
    end

    // unity twiddle W^0 = 1
    always @(*) assert (idx_q != 4'd0 || (re_q == 16'h7FFF && im_q == 16'h0000));
    // quarter twiddle W^8 = -j
    always @(*) assert (idx_q != 4'd8 || (re_q == 16'h0000 && im_q == 16'h8001));
endmodule

module ola_convolver #(
    parameter DW    = 128,
    parameter BLOCK = 24,
    parameter TAPS  = 4
) (
    input  wire          clk,
    input  wire          rst,
    input  wire          ce,
    input  wire          in_valid,
    input  wire [DW-1:0] in_data,
    output reg  [DW-1:0] y_out,
    output reg           y_valid,
    output reg  [7:0]    blk_cnt,
    output wire          busy
);
    localparam TOTAL = BLOCK + TAPS - 1;
    localparam IW = $clog2(TOTAL);
    localparam CW = $clog2(TOTAL + 1);
    localparam FW = $clog2(BLOCK);
    localparam [CW-1:0] TOTAL_C = TOTAL;
    localparam [IW-1:0] LAST_C  = TOTAL - 1;
    localparam [FW-1:0] BLAST_C = BLOCK - 1;

    typedef enum logic [0:0] {FILL, CONV} state_t;
    state_t state;
    initial state = FILL;

    reg [DW-1:0] xbuf [0:BLOCK-1];
    reg [DW-1:0] tail [0:TAPS-2];
    reg [FW-1:0] fill_idx = 0;
    reg [IW-1:0] out_idx  = 0;
    reg [CW-1:0] cd       = 0;
    reg          win      = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < BLOCK; i = i + 1) xbuf[i] = {DW{1'b0}};
        for (i = 0; i < TAPS-1; i = i + 1) tail[i] = {DW{1'b0}};
        y_out   = {DW{1'b0}};
        y_valid = 1'b0;
        blk_cnt = 8'd0;
    end

    assign busy = (state == CONV);

    // one output sample of the block convolution, plus overlap tail
    reg [DW-1:0] acc;
    integer k, j;
    always @(*) begin
        acc = {DW{1'b0}};
        for (k = 0; k < TAPS; k = k + 1) begin
            j = out_idx - k;
            if (j >= 0 && j < BLOCK) begin
                if (k == 1 || k == 2)
                    acc = acc + (xbuf[j] << 1);
                else
                    acc = acc + xbuf[j];
            end
        end
        if (out_idx < TAPS-1)
            acc = acc + tail[out_idx];
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= FILL;
            fill_idx <= 0;
            out_idx  <= 0;
            cd       <= 0;
            win      <= 1'b0;
            y_valid  <= 1'b0;
            blk_cnt  <= 8'd0;
        end else if (ce) begin
            case (state)
                FILL: begin
                    y_valid <= 1'b0;
                    if (in_valid) begin
                        xbuf[fill_idx] <= in_data;
                        if (fill_idx == BLAST_C) begin
                            fill_idx <= 0;
                            state    <= CONV;
                            win      <= 1'b1;
                            cd       <= TOTAL_C;
                            out_idx  <= 0;
                        end else begin
                            fill_idx <= fill_idx + 1'b1;
                        end
                    end
                end
                CONV: begin
                    if (out_idx < BLOCK) begin
                        y_out   <= acc;
                        y_valid <= 1'b1;
                    end else begin
                        tail[out_idx - BLOCK] <= acc;
                        y_valid <= 1'b0;
                    end
                    if (out_idx == LAST_C) begin
                        state   <= FILL;
                        win     <= 1'b0;
                        cd      <= 0;
                        out_idx <= 0;
                        blk_cnt <= blk_cnt + 8'd1;
                    end else begin
                        cd      <= cd - 1'b1;
                        out_idx <= out_idx + 1'b1;
                    end
                end
                default: state <= FILL;
            endcase
        end
    end

    // bounded response: while a accepted block is outstanding, its countdown never expires
    always @(posedge clk)
        assert (!win || cd != {CW{1'b0}});
endmodule

module sha256_msg_sched #(
    parameter WIDTH = 32,
    parameter NWIN  = 16,
    parameter NEXP  = 48
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             in_valid,
    output wire             in_ready,
    input  wire [WIDTH-1:0] in_data,
    output wire             out_valid,
    input  wire             out_ready,
    output wire [WIDTH-1:0] out_data,
    output wire             out_last
);
    typedef enum logic [1:0] {IDLE = 2'd0, LOAD = 2'd1, EXPAND = 2'd2} state_t;

    state_t state;
    initial state = IDLE;
    reg [31:0] cnt;
    initial cnt = 32'd0;
    reg armed;
    initial armed = 1'b1;
    reg [NWIN*WIDTH-1:0] win;
    initial win = {(NWIN*WIDTH){1'b0}};

    function [31:0] ssig0(input [31:0] x);
        ssig0 = {x[6:0], x[31:7]} ^ {x[17:0], x[31:18]} ^ (x >> 3);
    endfunction
    function [31:0] ssig1(input [31:0] x);
        ssig1 = {x[16:0], x[31:17]} ^ {x[18:0], x[31:19]} ^ (x >> 10);
    endfunction

    wire [WIDTH-1:0] w0  = win[0*WIDTH +: WIDTH];
    wire [WIDTH-1:0] w1  = win[1*WIDTH +: WIDTH];
    wire [WIDTH-1:0] w9  = win[9*WIDTH +: WIDTH];
    wire [WIDTH-1:0] w14 = win[14*WIDTH +: WIDTH];

    assign out_data  = ssig1(w14) + w9 + ssig0(w1) + w0;
    assign in_ready  = (state == IDLE) || (state == LOAD);
    assign out_valid = (state == EXPAND);
    assign out_last  = out_valid && (cnt == NEXP - 1);

    wire in_fire  = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            cnt   <= 32'd0;
        end else begin
            case (state)
                IDLE: begin
                    if (in_fire) begin
                        win   <= {in_data, win[NWIN*WIDTH-1:WIDTH]};
                        cnt   <= 32'd1;
                        state <= LOAD;
                    end
                end
                LOAD: begin
                    if (in_fire) begin
                        win <= {in_data, win[NWIN*WIDTH-1:WIDTH]};
                        if (cnt == NWIN - 1) begin
                            cnt   <= 32'd0;
                            state <= EXPAND;
                        end else begin
                            cnt <= cnt + 32'd1;
                        end
                    end
                end
                EXPAND: begin
                    if (out_fire) begin
                        win <= {out_data, win[NWIN*WIDTH-1:WIDTH]};
                        if (cnt == NEXP - 1) begin
                            cnt   <= 32'd0;
                            state <= IDLE;
                            armed <= 1'b0;
                        end else begin
                            cnt <= cnt + 32'd1;
                        end
                    end
                end
                default: begin
                    state <= IDLE;
                    cnt   <= 32'd0;
                end
            endcase
        end
    end

    assert property (!armed || cnt <= NEXP);
endmodule

module pam4_gray_mapper #(
    parameter W = 64
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         ce,
    input  wire         load,
    input  wire         precode,
    input  wire [W-1:0] data,
    output reg  [1:0]   sym_out,
    output reg          sym_valid
);
    localparam [63:0] NSYM = W / 2;

    reg [W-1:0] stage;
    reg [63:0]  sym_left;
    reg [63:0]  deadline;
    reg [1:0]   prev_sym;
    reg         armed;

    initial begin
        stage     = {W{1'b0}};
        sym_left  = 64'd0;
        deadline  = 64'd0;
        prev_sym  = 2'd0;
        sym_out   = 2'd0;
        sym_valid = 1'b0;
        armed     = 1'b0;
    end

    wire [1:0] pair  = stage[1:0];
    wire [1:0] gray  = {pair[1], pair[1] ^ pair[0]};
    wire [1:0] sum4  = gray + prev_sym;
    wire [1:0] coded = precode ? sum4 : gray;

    always @(posedge clk) begin
        if (rst) begin
            stage     <= {W{1'b0}};
            sym_left  <= 64'd0;
            deadline  <= 64'd0;
            prev_sym  <= 2'd0;
            sym_out   <= 2'd0;
            sym_valid <= 1'b0;
        end else if (ce) begin
            sym_valid <= 1'b0;
            if (sym_left == 64'd0) begin
                if (load) begin
                    stage    <= data;
                    sym_left <= NSYM;
                    deadline <= NSYM;
                    armed    <= 1'b1;
                end
            end else begin
                sym_out   <= coded;
                sym_valid <= 1'b1;
                prev_sym  <= coded;
                stage     <= stage >> 2;
                sym_left  <= sym_left - 64'd1;
                deadline  <= deadline - 64'd1;
            end
        end
    end

    always @(posedge clk)
        if (armed && sym_left != 64'd0)
            assert (deadline != 64'd0);

    always @(posedge clk)
        if (armed && sym_left == 64'd0)
            assert (deadline == 64'd0);
endmodule

module ecc_scrubber #(
    parameter ENTRIES  = 64,
    parameter AW       = 6,
    parameter DW       = 64,
    parameter CW       = 7,
    parameter [63:0] INTERVAL = 64'd16,
    parameter [63:0] BUDGET   = 64'd5
) (
    input  wire          clk,
    input  wire          rst,
    input  wire          ce,
    input  wire          fill_en,
    input  wire [AW-1:0] fill_addr,
    input  wire [DW-1:0] fill_data,
    input  wire [CW-1:0] fill_chk,
    output reg  [63:0]   corr_count,
    output reg  [63:0]   uncorr_count,
    output reg  [AW-1:0] scrub_addr
);
    typedef enum logic [2:0] {IDLE = 3'd0, READ = 3'd1, CHECK = 3'd2, WRITE = 3'd3, LOG = 3'd4} state_t;

    state_t state = IDLE;
    reg [63:0]   deadline   = 64'd0;
    reg [63:0]   timer      = INTERVAL;
    reg [DW-1:0] line_data  = {DW{1'b0}};
    reg [CW-1:0] line_chk   = {CW{1'b0}};

    reg [DW-1:0] mem_data [0:ENTRIES-1];
    reg [CW-1:0] mem_chk  [0:ENTRIES-1];

    integer k;
    initial begin
        corr_count   = 64'd0;
        uncorr_count = 64'd0;
        scrub_addr   = {AW{1'b0}};
        for (k = 0; k < ENTRIES; k = k + 1) begin
            mem_data[k] = {DW{1'b0}};
            mem_chk[k]  = {CW{1'b0}};
        end
    end

    function [CW-1:0] hcode;
        input [DW-1:0] d;
        integer i;
        begin
            hcode = {CW{1'b0}};
            for (i = 0; i < DW; i = i + 1)
                if (d[i]) hcode = hcode ^ (i + 1);
        end
    endfunction

    wire [CW-1:0] syndrome = line_chk ^ hcode(line_data);

    always @(posedge clk) begin
        if (!rst && ce) begin
            if (state == WRITE) begin
                mem_data[scrub_addr] <= line_data;
                mem_chk[scrub_addr]  <= hcode(line_data);
            end else if (fill_en) begin
                mem_data[fill_addr] <= fill_data;
                mem_chk[fill_addr]  <= fill_chk;
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            state        <= IDLE;
            deadline     <= 64'd0;
            timer        <= INTERVAL;
            scrub_addr   <= {AW{1'b0}};
            corr_count   <= 64'd0;
            uncorr_count <= 64'd0;
            line_data    <= {DW{1'b0}};
            line_chk     <= {CW{1'b0}};
        end else if (ce) begin
            case (state)
                IDLE: begin
                    if (timer == 64'd0) begin
                        state    <= READ;
                        deadline <= BUDGET;
                        timer    <= INTERVAL;
                    end else begin
                        timer <= timer - 64'd1;
                    end
                end
                READ: begin
                    line_data <= mem_data[scrub_addr];
                    line_chk  <= mem_chk[scrub_addr];
                    deadline  <= deadline - 64'd1;
                    state     <= CHECK;
                end
                CHECK: begin
                    deadline <= deadline - 64'd1;
                    if (syndrome == {CW{1'b0}}) begin
                        state <= LOG;
                    end else if (syndrome <= DW) begin
                        line_data <= line_data ^ ({{(DW-1){1'b0}}, 1'b1} << (syndrome - 7'd1));
                        state     <= WRITE;
                    end else begin
                        uncorr_count <= uncorr_count + 64'd1;
                        state        <= LOG;
                    end
                end
                WRITE: begin
                    deadline   <= deadline - 64'd1;
                    corr_count <= corr_count + 64'd1;
                    state      <= LOG;
                end
                LOG: begin
                    deadline   <= 64'd0;
                    scrub_addr <= scrub_addr + 1'b1;
                    state      <= IDLE;
                end
                default: begin
                    deadline <= 64'd0;
                    state    <= IDLE;
                end
            endcase
        end
    end

    wire expired = (deadline == 64'd0);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(expired))
            assert (state == IDLE);
endmodule

module pkt_boundary_mux #(
    parameter NSRC = 4,
    parameter DW   = 64,
    parameter CW   = 64
) (
    input  wire               clk,
    input  wire               rst,
    input  wire               step,
    input  wire [NSRC-1:0]    valid,
    input  wire [NSRC-1:0]    eop,
    input  wire [NSRC*DW-1:0] in_data,
    output wire               out_valid,
    output wire               out_eop,
    output wire [DW-1:0]      out_data,
    output wire [$clog2(NSRC)-1:0] out_src
);
    localparam SW = $clog2(NSRC);

    reg [SW-1:0] cur_src;
    reg          locked;
    reg          win;
    reg          started;
    reg [CW-1:0] arm_cnt;
    reg [CW-1:0] start_cnt;
    reg [CW-1:0] fin_cnt;
    reg [CW-1:0] tot_beats;

    initial begin
        cur_src   = {SW{1'b0}};
        locked    = 1'b0;
        win       = 1'b0;
        started   = 1'b0;
        arm_cnt   = {CW{1'b0}};
        start_cnt = {CW{1'b0}};
        fin_cnt   = {CW{1'b0}};
        tot_beats = {CW{1'b0}};
    end

    reg [SW-1:0] pick;
    reg          any_valid;
    integer i;
    always @(*) begin
        any_valid = 1'b0;
        pick = {SW{1'b0}};
        for (i = NSRC-1; i >= 0; i = i - 1)
            if (valid[i]) begin
                any_valid = 1'b1;
                pick = i;
            end
    end

    wire sel_valid = valid[cur_src];
    wire sel_eop   = eop[cur_src];
    wire beat      = locked && sel_valid;

    assign out_valid = step && beat;
    assign out_eop   = step && beat && sel_eop;
    assign out_data  = in_data[cur_src*DW +: DW];
    assign out_src   = cur_src;

    always @(posedge clk) begin
        if (rst) begin
            cur_src   <= {SW{1'b0}};
            locked    <= 1'b0;
            win       <= 1'b0;
            started   <= 1'b0;
            arm_cnt   <= {CW{1'b0}};
            start_cnt <= {CW{1'b0}};
            fin_cnt   <= {CW{1'b0}};
            tot_beats <= {CW{1'b0}};
        end else if (step) begin
            if (!locked) begin
                if (any_valid) begin
                    cur_src <= pick;
                    locked  <= 1'b1;
                    win     <= 1'b1;
                    arm_cnt <= arm_cnt + 1'b1;
                end
            end else if (sel_valid) begin
                tot_beats <= tot_beats + 1'b1;
                if (!started)
                    start_cnt <= start_cnt + 1'b1;
                if (sel_eop) begin
                    fin_cnt <= fin_cnt + 1'b1;
                    locked  <= 1'b0;
                    win     <= 1'b0;
                    started <= 1'b0;
                end else begin
                    started <= 1'b1;
                end
            end
        end
    end

    always @(*)
        assert (!win || (((arm_cnt - start_cnt) <= 64'd1) && ((start_cnt - fin_cnt) <= 64'd1)));
endmodule

module transpose_buf #(
    parameter ROWS  = 4,
    parameter COLS  = 8,
    parameter DEPTH = ROWS * COLS,
    parameter DW    = 32
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data
);
    localparam AW = $clog2(DEPTH);
    localparam [1:0] C_IDLE  = 2'd0;
    localparam [1:0] C_ARM   = 2'd1;
    localparam [1:0] C_START = 2'd2;
    localparam PH_FILL  = 1'b0;
    localparam PH_DRAIN = 1'b1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg        phase    = 1'b0;
    reg [31:0] wr_row   = 32'd0;
    reg [31:0] wr_col   = 32'd0;
    reg [31:0] rd_row   = 32'd0;
    reg [31:0] rd_col   = 32'd0;
    reg [1:0]  chain    = 2'd0;
    reg        before_r = 1'b1;
    reg        pv       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = {DW{1'b0}};
    end

    assign in_ready  = (phase == PH_FILL);
    assign out_valid = (phase == PH_DRAIN);

    wire wr_fire = in_valid && in_ready;
    wire rd_fire = out_valid && out_ready;
    wire wr_last = (wr_row == ROWS - 1) && (wr_col == COLS - 1);
    wire rd_last = (rd_row == ROWS - 1) && (rd_col == COLS - 1);

    wire [31:0] wr_addr = wr_row * COLS + wr_col;
    wire [31:0] rd_addr = rd_row * COLS + rd_col;

    assign out_data = mem[rd_addr[AW-1:0]];

    // row-order write into the tile
    always @(posedge clk) begin
        if (wr_fire)
            mem[wr_addr[AW-1:0]] <= in_data;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase    <= PH_FILL;
            wr_row   <= 32'd0;
            wr_col   <= 32'd0;
            rd_row   <= 32'd0;
            rd_col   <= 32'd0;
            chain    <= C_IDLE;
            before_r <= 1'b1;
        end else begin
            if (wr_fire) begin
                if (wr_col == COLS - 1) begin
                    wr_col <= 32'd0;
                    if (wr_row == ROWS - 1) wr_row <= 32'd0;
                    else                    wr_row <= wr_row + 32'd1;
                end else begin
                    wr_col <= wr_col + 32'd1;
                end
                if (wr_last) begin
                    phase <= PH_DRAIN;
                    chain <= C_START;
                end else if (chain == C_IDLE) begin
                    chain <= C_ARM;
                end
            end
            // column-order read out of the tile
            if (rd_fire) begin
                if (rd_row == ROWS - 1) begin
                    rd_row <= 32'd0;
                    if (rd_col == COLS - 1) rd_col <= 32'd0;
                    else                    rd_col <= rd_col + 32'd1;
                end else begin
                    rd_row <= rd_row + 32'd1;
                end
                if (rd_last) begin
                    phase    <= PH_FILL;
                    chain    <= C_IDLE;
                    before_r <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    // Chain precedence (arm -> start -> finish), before first tile completes:
    // while the chain FSM sits unchanged short of START, no column-order read may advance.
    always @(posedge clk) begin
        if (pv && before_r && $stable(chain) && chain != C_START)
            assert ($stable(rd_row) && $stable(rd_col));
    end
endmodule

module spi_sclk_tff #(
    parameter W = 8
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         step,
    input  wire         miso,
    output wire         spi_clk_o,
    output wire [W-1:0] o_edges,
    output wire [W-1:0] o_rx
);
    localparam [W-1:0] MAXC = {W{1'b1}};

    // T flip-flop generating the SPI serial clock (mode 0)
    reg         sclk      = 1'b0;
    // number of rising SPI clock edges (saturating)
    reg [W-1:0] edges     = {W{1'b0}};
    // shadow register: a falling SPI clock edge has happened earlier
    reg         fell_seen = 1'b0;
    // MISO capture shift register, sampled on rising edges
    reg [W-1:0] rx        = {W{1'b0}};

    wire t    = step;
    wire rise = t && !sclk;
    wire fall = t &&  sclk;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sclk      <= 1'b0;
            edges     <= {W{1'b0}};
            fell_seen <= 1'b0;
            rx        <= {W{1'b0}};
        end else begin
            if (t)
                sclk <= ~sclk;
            if (rise && edges != MAXC)
                edges <= edges + 1'b1;
            if (rise)
                rx <= {rx[W-2:0], miso};
            if (fall)
                fell_seen <= 1'b1;
        end
    end

    assign spi_clk_o = sclk;
    assign o_edges   = edges;
    assign o_rx      = rx;

    // Precedence: a second rising SPI clock edge requires an earlier falling edge
    always @(*) assert ((edges <= 8'd1) || fell_seen);
endmodule

module branch_resolve_unit #(
    parameter XLEN = 64,
    parameter INST_BYTES = 4
) (
    input  wire            clk,
    input  wire            rst_n,
    // resolved branch packet from execute (valid/ready)
    input  wire            br_valid,
    output wire            br_ready,
    input  wire [XLEN-1:0] br_pc,
    input  wire            br_pred_taken,
    input  wire [XLEN-1:0] br_pred_target,
    input  wire            br_taken,
    input  wire [XLEN-1:0] br_target,
    // redirect / flush request to fetch (valid/ready)
    output reg             redir_valid,
    input  wire            redir_ready,
    output reg  [XLEN-1:0] redir_addr,
    output wire            flush,
    // monitor window control
    input  wire            mon_open,
    input  wire            mon_close
);
    localparam [XLEN-1:0] ONE  = 1;
    localparam [XLEN-1:0] STEP = INST_BYTES;

    reg [XLEN-1:0] pred_target_q = 0;
    reg            pred_taken_q  = 1'b0;
    reg            act_taken_q   = 1'b0;
    reg [XLEN-1:0] mispred_cnt   = 0;
    reg [XLEN-1:0] correct_cnt   = 0;
    reg [XLEN-1:0] redir_cnt     = 0;
    reg            win           = 1'b0;
    reg            pv            = 1'b0;
    initial begin redir_valid = 1'b0; redir_addr = 0; end

    assign br_ready = !redir_valid;
    wire accept   = br_valid && br_ready;
    wire send     = redir_valid && redir_ready;
    assign flush  = send;

    wire mispredict = (br_pred_taken != br_taken) ||
                      (br_taken && (br_pred_target != br_target));
    wire [XLEN-1:0] fix_addr = br_taken ? br_target : (br_pc + STEP);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pred_target_q <= 0;
            pred_taken_q  <= 1'b0;
            act_taken_q   <= 1'b0;
            mispred_cnt   <= 0;
            correct_cnt   <= 0;
            redir_cnt     <= 0;
            redir_valid   <= 1'b0;
            redir_addr    <= 0;
        end else begin
            if (accept) begin
                pred_target_q <= br_pred_target;
                pred_taken_q  <= br_pred_taken;
                act_taken_q   <= br_taken;
                if (mispredict) begin
                    mispred_cnt <= mispred_cnt + ONE;
                    redir_valid <= 1'b1;
                    redir_addr  <= fix_addr;
                end else begin
                    correct_cnt <= correct_cnt + ONE;
                end
            end else if (send) begin
                redir_valid <= 1'b0;
                redir_cnt   <= redir_cnt + ONE;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            win <= 1'b0;
        end else begin
            if (mon_open)       win <= 1'b1;
            else if (mon_close) win <= 1'b0;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && win && $rose(redir_valid))
            assert (mispred_cnt == redir_cnt + ONE);
endmodule

module axi_cdc_bridge #(
    parameter DEPTH = 24,
    parameter PW = 5
) (
    input  wire        clk,
    input  wire        s_ce,
    input  wire        m_ce,
    input  wire        i_load,
    input  wire [15:0] i_lim,
    input  wire        s_aw_valid,
    input  wire [15:0] s_aw_addr,
    output wire        s_aw_ready,
    output wire        m_aw_valid,
    output wire [15:0] m_aw_addr,
    input  wire        m_aw_ready,
    input  wire        s_w_valid,
    input  wire [15:0] s_w_data,
    output wire        s_w_ready,
    output wire        m_w_valid,
    output wire [15:0] m_w_data,
    input  wire        m_w_ready,
    input  wire        m_b_valid,
    input  wire [15:0] m_b_resp,
    output wire        m_b_ready,
    output wire        s_b_valid,
    output wire [15:0] s_b_resp,
    input  wire        s_b_ready,
    input  wire        s_ar_valid,
    input  wire [15:0] s_ar_addr,
    output wire        s_ar_ready,
    output wire        m_ar_valid,
    output wire [15:0] m_ar_addr,
    input  wire        m_ar_ready,
    input  wire        m_r_valid,
    input  wire [15:0] m_r_data,
    output wire        m_r_ready,
    output wire        s_r_valid,
    output wire [15:0] s_r_data,
    input  wire        s_r_ready
);
    localparam [15:0]   DEPTH16 = DEPTH;
    localparam [PW-1:0] LAST    = DEPTH - 1;

    reg [15:0] lim = DEPTH16;

    reg [15:0] mem_aw [0:DEPTH-1];
    reg [15:0] mem_w  [0:DEPTH-1];
    reg [15:0] mem_b  [0:DEPTH-1];
    reg [15:0] mem_ar [0:DEPTH-1];
    reg [15:0] mem_r  [0:DEPTH-1];
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) begin
            mem_aw[i] = 16'd0;
            mem_w[i]  = 16'd0;
            mem_b[i]  = 16'd0;
            mem_ar[i] = 16'd0;
            mem_r[i]  = 16'd0;
        end
    end

    reg [PW-1:0] wp_aw = 0, rp_aw = 0, wp_w = 0, rp_w = 0, wp_b = 0, rp_b = 0;
    reg [PW-1:0] wp_ar = 0, rp_ar = 0, wp_r = 0, rp_r = 0;
    reg [15:0] wc_aw = 0, rc_aw = 0, occ_aw = 0;
    reg [15:0] wc_w  = 0, rc_w  = 0, occ_w  = 0;
    reg [15:0] wc_b  = 0, rc_b  = 0, occ_b  = 0;
    reg [15:0] wc_ar = 0, rc_ar = 0, occ_ar = 0;
    reg [15:0] wc_r  = 0, rc_r  = 0, occ_r  = 0;

    wire full_aw  = (occ_aw >= lim);
    wire empty_aw = (wc_aw == rc_aw);
    wire full_w   = (occ_w >= lim);
    wire empty_w  = (wc_w == rc_w);
    wire full_b   = (occ_b >= lim);
    wire empty_b  = (wc_b == rc_b);
    wire full_ar  = (occ_ar >= lim);
    wire empty_ar = (wc_ar == rc_ar);
    wire full_r   = (occ_r >= lim);
    wire empty_r  = (wc_r == rc_r);

    wire push_aw = s_ce && s_aw_valid && !full_aw;
    wire pop_aw  = m_ce && m_aw_ready && !empty_aw;
    wire push_w  = s_ce && s_w_valid  && !full_w;
    wire pop_w   = m_ce && m_w_ready  && !empty_w;
    wire push_b  = m_ce && m_b_valid  && !full_b;
    wire pop_b   = s_ce && s_b_ready  && !empty_b;
    wire push_ar = s_ce && s_ar_valid && !full_ar;
    wire pop_ar  = m_ce && m_ar_ready && !empty_ar;
    wire push_r  = m_ce && m_r_valid  && !full_r;
    wire pop_r   = s_ce && s_r_ready  && !empty_r;

    assign s_aw_ready = !full_aw;
    assign m_aw_valid = !empty_aw;
    assign m_aw_addr  = mem_aw[rp_aw];
    assign s_w_ready  = !full_w;
    assign m_w_valid  = !empty_w;
    assign m_w_data   = mem_w[rp_w];
    assign m_b_ready  = !full_b;
    assign s_b_valid  = !empty_b;
    assign s_b_resp   = mem_b[rp_b];
    assign s_ar_ready = !full_ar;
    assign m_ar_valid = !empty_ar;
    assign m_ar_addr  = mem_ar[rp_ar];
    assign m_r_ready  = !full_r;
    assign s_r_valid  = !empty_r;
    assign s_r_data   = mem_r[rp_r];

    wire quiet = (occ_aw == 16'd0) && (occ_w == 16'd0) && (occ_b == 16'd0) && (occ_ar == 16'd0) && (occ_r == 16'd0);

    always @(posedge clk)
        if (i_load && quiet)
            lim <= ((i_lim == 16'd0) || (i_lim > DEPTH16)) ? DEPTH16 : i_lim;

    always @(posedge clk) begin
        if (push_aw) begin
            mem_aw[wp_aw] <= s_aw_addr;
            wp_aw <= (wp_aw == LAST) ? {PW{1'b0}} : wp_aw + 1'b1;
            wc_aw <= wc_aw + 16'd1;
        end
        if (pop_aw) begin
            rp_aw <= (rp_aw == LAST) ? {PW{1'b0}} : rp_aw + 1'b1;
            rc_aw <= rc_aw + 16'd1;
        end
        occ_aw <= occ_aw + {15'd0, push_aw} - {15'd0, pop_aw};
    end

    always @(posedge clk) begin
        if (push_w) begin
            mem_w[wp_w] <= s_w_data;
            wp_w <= (wp_w == LAST) ? {PW{1'b0}} : wp_w + 1'b1;
            wc_w <= wc_w + 16'd1;
        end
        if (pop_w) begin
            rp_w <= (rp_w == LAST) ? {PW{1'b0}} : rp_w + 1'b1;
            rc_w <= rc_w + 16'd1;
        end
        occ_w <= occ_w + {15'd0, push_w} - {15'd0, pop_w};
    end

    always @(posedge clk) begin
        if (push_b) begin
            mem_b[wp_b] <= m_b_resp;
            wp_b <= (wp_b == LAST) ? {PW{1'b0}} : wp_b + 1'b1;
            wc_b <= wc_b + 16'd1;
        end
        if (pop_b) begin
            rp_b <= (rp_b == LAST) ? {PW{1'b0}} : rp_b + 1'b1;
            rc_b <= rc_b + 16'd1;
        end
        occ_b <= occ_b + {15'd0, push_b} - {15'd0, pop_b};
    end

    always @(posedge clk) begin
        if (push_ar) begin
            mem_ar[wp_ar] <= s_ar_addr;
            wp_ar <= (wp_ar == LAST) ? {PW{1'b0}} : wp_ar + 1'b1;
            wc_ar <= wc_ar + 16'd1;
        end
        if (pop_ar) begin
            rp_ar <= (rp_ar == LAST) ? {PW{1'b0}} : rp_ar + 1'b1;
            rc_ar <= rc_ar + 16'd1;
        end
        occ_ar <= occ_ar + {15'd0, push_ar} - {15'd0, pop_ar};
    end

    always @(posedge clk) begin
        if (push_r) begin
            mem_r[wp_r] <= m_r_data;
            wp_r <= (wp_r == LAST) ? {PW{1'b0}} : wp_r + 1'b1;
            wc_r <= wc_r + 16'd1;
        end
        if (pop_r) begin
            rp_r <= (rp_r == LAST) ? {PW{1'b0}} : rp_r + 1'b1;
            rc_r <= rc_r + 16'd1;
        end
        occ_r <= occ_r + {15'd0, push_r} - {15'd0, pop_r};
    end

    reg armed = 1'b0;
    always @(posedge clk)
        if (push_w)
            armed <= 1'b1;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed)
            assert (!($past(full_w) && $past(empty_w)));
endmodule

module uart_break_det #(
    parameter FRAME_BITS = 10,
    parameter BREAK_LEN  = FRAME_BITS + 1
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        tick,
    input  wire        rx,
    input  wire        clr_status,
    output reg  [31:0] low_cnt,
    output reg         in_break,
    output reg         break_rcvd
);
    localparam [31:0] BRK = BREAK_LEN;

    initial low_cnt    = 32'd0;
    initial in_break   = 1'b0;
    initial break_rcvd = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            low_cnt    <= 32'd0;
            in_break   <= 1'b0;
            break_rcvd <= 1'b0;
        end else begin
            if (clr_status)
                break_rcvd <= 1'b0;
            if (tick) begin
                if (rx) begin
                    low_cnt  <= 32'd0;
                    in_break <= 1'b0;
                end else if (!in_break) begin
                    low_cnt <= low_cnt + 32'd1;
                    if (low_cnt == BRK - 32'd1) begin
                        in_break   <= 1'b1;
                        break_rcvd <= 1'b1;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        assert (low_cnt <= BRK);
endmodule

module dds_tmr_minority #(
    parameter W = 8
) (
    input  wire         clk,
    input  wire         i_reset,
    input  wire         i_ce,
    input  wire [W-1:0] i_tw,
    input  wire         i_sweep_start,
    input  wire         i_sweep_stop,
    output wire         o_sq,
    output wire         o_min
);
    // Triple-redundant phase accumulators of a DDS core
    reg [W-1:0] acc_a;
    reg [W-1:0] acc_b;
    reg [W-1:0] acc_c;
    reg         sweep_win;
    initial acc_a = {W{1'b0}};
    initial acc_b = {W{1'b0}};
    initial acc_c = {W{1'b0}};
    initial sweep_win = 1'b0;

    always @(posedge clk) begin
        if (i_reset) begin
            acc_a     <= {W{1'b0}};
            acc_b     <= {W{1'b0}};
            acc_c     <= {W{1'b0}};
            sweep_win <= 1'b0;
        end else if (i_ce) begin
            acc_a <= acc_a + i_tw;
            acc_b <= acc_b + i_tw;
            acc_c <= acc_c + i_tw;
            if (i_sweep_start)
                sweep_win <= 1'b1;
            else if (i_sweep_stop)
                sweep_win <= 1'b0;
        end
    end

    // Square-wave output taken from replica A's MSB
    assign o_sq = acc_a[W-1];

    // Minority gate over the three replica MSBs: complement of the majority
    wire ma = acc_a[W-1];
    wire mb = acc_b[W-1];
    wire mc = acc_c[W-1];
    assign o_min = ~((ma & mb) | (mb & mc) | (ma & mc));

    // Absence, after sweep start until sweep stop:
    // square output and minority output are never high together
    assert property (!sweep_win || !(o_sq && o_min));
endmodule

module claim_gateway #(
    parameter NSRC = 24,
    parameter IDW  = 16
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire [NSRC-1:0] irq,
    input  wire            claim,
    input  wire            complete,
    input  wire [IDW-1:0]  complete_id,
    output wire [IDW-1:0]  claim_rdata,
    output reg  [IDW-1:0]  last_id,
    output reg  [15:0]     inflight_cnt
);
    reg [NSRC-1:0] pending;
    reg [NSRC-1:0] inflight;
    reg            armed;
    reg            pv;

    initial begin
        pending      = {NSRC{1'b0}};
        inflight     = {NSRC{1'b0}};
        last_id      = {IDW{1'b0}};
        inflight_cnt = 16'd0;
        armed        = 1'b0;
        pv           = 1'b0;
    end

    wire [NSRC-1:0] elig = pending & ~inflight;

    reg [IDW-1:0]  sel_id;
    reg [NSRC-1:0] sel_oh;
    reg [NSRC-1:0] comp_oh;
    integer i;
    always @(*) begin
        sel_id  = {IDW{1'b0}};
        sel_oh  = {NSRC{1'b0}};
        comp_oh = {NSRC{1'b0}};
        for (i = 0; i < NSRC; i = i + 1) begin
            if (elig[i]) begin
                sel_id    = i + 1;
                sel_oh    = {NSRC{1'b0}};
                sel_oh[i] = 1'b1;
            end
            if (complete_id == i + 1)
                comp_oh[i] = 1'b1;
        end
    end

    wire claim_ok = claim && (sel_id != {IDW{1'b0}});
    wire comp_hit = complete && !claim && (|(comp_oh & inflight));
    wire do_dec   = comp_hit && (inflight_cnt != 16'd0);

    assign claim_rdata = claim_ok ? sel_id : {IDW{1'b0}};

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pending      <= {NSRC{1'b0}};
            inflight     <= {NSRC{1'b0}};
            last_id      <= {IDW{1'b0}};
            inflight_cnt <= 16'd0;
            armed        <= 1'b0;
        end else begin
            pending  <= (pending | (irq & ~inflight)) & ~(claim_ok ? sel_oh : {NSRC{1'b0}});
            inflight <= (inflight | (claim_ok ? sel_oh : {NSRC{1'b0}}))
                        & ~(comp_hit ? comp_oh : {NSRC{1'b0}});
            if (claim_ok)
                last_id <= sel_id;
            if (claim_ok)
                inflight_cnt <= inflight_cnt + 16'd1;
            else if (do_dec)
                inflight_cnt <= inflight_cnt - 16'd1;
            if (claim_ok)
                armed <= 1'b1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && armed)
            assert (!$stable(inflight_cnt) || $stable(inflight));
endmodule

module bcd_div_resp #(
    parameter DIGITS = 8,
    parameter PHASES = 5
) (
    input  wire        clk,
    input  wire        ce,
    input  wire        flush,
    input  wire        in_valid,
    output wire        in_ready,
    input  wire [31:0] in_dividend,
    input  wire [31:0] in_divisor,
    output wire        out_valid,
    input  wire        out_ready,
    output wire [31:0] out_quotient,
    output wire [31:0] out_remainder
);
    localparam [31:0] LAT     = DIGITS * PHASES;
    localparam [31:0] LASTPOS = DIGITS - 1;
    localparam [2:0]  LASTPH  = PHASES - 1;

    function [35:0] bcd_add36;
        input [35:0] a;
        input [35:0] b;
        integer i;
        reg [4:0] s;
        reg c;
        begin
            c = 1'b0;
            bcd_add36 = 36'd0;
            for (i = 0; i < 9; i = i + 1) begin
                s = {1'b0, a[i*4 +: 4]} + {1'b0, b[i*4 +: 4]} + {4'd0, c};
                if (s > 5'd9) begin s = s + 5'd6; c = 1'b1; end
                else c = 1'b0;
                bcd_add36[i*4 +: 4] = s[3:0];
            end
        end
    endfunction

    function [35:0] bcd_sub36;
        input [35:0] a;
        input [35:0] b;
        integer i;
        reg [4:0] s;
        reg br;
        begin
            br = 1'b0;
            bcd_sub36 = 36'd0;
            for (i = 0; i < 9; i = i + 1) begin
                s = {1'b0, a[i*4 +: 4]} - {1'b0, b[i*4 +: 4]} - {4'd0, br};
                if (s[4]) begin s = s + 5'd10; br = 1'b1; end
                else br = 1'b0;
                bcd_sub36[i*4 +: 4] = s[3:0];
            end
        end
    endfunction

    reg        busy;
    reg        ovalid;
    reg        before_flush;
    reg [31:0] cd;
    reg [31:0] pos;
    reg [2:0]  phase;
    reg [31:0] dvd;
    reg [31:0] quo;
    reg [35:0] rem;
    reg [35:0] mult1x;
    reg [35:0] mult2x;
    reg [35:0] mult4x;
    reg [3:0]  qdig;

    initial begin
        busy = 1'b0; ovalid = 1'b0; before_flush = 1'b1;
        cd = 32'd0; pos = 32'd0; phase = 3'd0;
        dvd = 32'd0; quo = 32'd0; rem = 36'd0;
        mult1x = 36'd0; mult2x = 36'd0; mult4x = 36'd0;
        qdig = 4'd0;
    end

    wire [35:0] d1 = {4'd0, in_divisor};
    wire [35:0] d2 = bcd_add36(d1, d1);
    wire [35:0] d4 = bcd_add36(d2, d2);

    wire [35:0] msel = (phase == 3'd3) ? mult2x : (phase == 3'd4) ? mult1x : mult4x;
    wire [3:0]  minc = (phase == 3'd3) ? 4'd2 : (phase == 3'd4) ? 4'd1 : 4'd4;
    wire        take = (rem >= msel);
    wire [35:0] rem_sub = bcd_sub36(rem, msel);
    wire [3:0]  qnext = qdig + (take ? minc : 4'd0);

    assign in_ready = ce && !busy && !ovalid;
    wire accept = in_valid && in_ready;

    assign out_valid     = ovalid;
    assign out_quotient  = quo;
    assign out_remainder = rem[31:0];

    always @(posedge clk) begin
        if (flush) begin
            busy <= 1'b0;
            ovalid <= 1'b0;
            cd <= 32'd0;
            pos <= 32'd0;
            phase <= 3'd0;
            before_flush <= 1'b0;
        end else begin
            if (ovalid && out_ready)
                ovalid <= 1'b0;
            if (accept) begin
                busy <= 1'b1;
                cd <= LAT;
                pos <= 32'd0;
                phase <= 3'd0;
                dvd <= in_dividend;
                mult1x <= d1;
                mult2x <= d2;
                mult4x <= d4;
                rem <= 36'd0;
                qdig <= 4'd0;
                quo <= 32'd0;
            end else if (ce && busy) begin
                cd <= cd - 32'd1;
                if (phase == 3'd0) begin
                    rem <= {rem[31:0], dvd[31:28]};
                    dvd <= {dvd[27:0], 4'd0};
                    qdig <= 4'd0;
                    phase <= 3'd1;
                end else begin
                    if (take)
                        rem <= rem_sub;
                    qdig <= qnext;
                    if (phase == LASTPH) begin
                        quo <= {quo[27:0], qnext};
                        phase <= 3'd0;
                        if (pos == LASTPOS) begin
                            busy <= 1'b0;
                            ovalid <= 1'b1;
                            pos <= 32'd0;
                        end else begin
                            pos <= pos + 32'd1;
                        end
                    end else begin
                        phase <= phase + 3'd1;
                    end
                end
            end
        end
    end

    always @(*)
        if (before_flush && busy)
            assert (cd != 32'd0);
endmodule

module div3_serial #(
    parameter W = 16,
    parameter MAXBITS = 16
) (
    input  wire         clk,
    input  wire         arm,
    input  wire         clr,
    input  wire         load,
    input  wire [W-1:0] load_len,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire         in_bit,
    output wire         done,
    output wire         div3,
    output wire [1:0]   o_rem
);
    localparam [1:0] S_IDLE = 2'd0, S_ARM = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [1:0]   phase   = S_IDLE;
    reg [1:0]   rem     = 2'd0;
    reg [W-1:0] val     = {W{1'b0}};
    reg [W-1:0] cnt     = {W{1'b0}};
    reg [W-1:0] limit   = 16'd8;
    reg         started = 1'b0;
    reg         win     = 1'b0;

    assign in_ready = (phase == S_ARM) || (phase == S_RUN);
    wire acc = in_valid && in_ready;

    function [1:0] rnext;
        input [1:0] r;
        input       b;
        begin
            case ({r, b})
                3'b000: rnext = 2'd0;
                3'b001: rnext = 2'd1;
                3'b010: rnext = 2'd2;
                3'b011: rnext = 2'd0;
                3'b100: rnext = 2'd1;
                3'b101: rnext = 2'd2;
                default: rnext = 2'd0;
            endcase
        end
    endfunction

    wire [W-1:0] load_clamped = (load_len == 16'd0) ? 16'd1 :
                                (load_len > MAXBITS) ? MAXBITS : load_len;

    always @(posedge clk) begin
        if (phase == S_IDLE) begin
            if (load) limit <= load_clamped;
            if (arm) begin
                phase   <= S_ARM;
                rem     <= 2'd0;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b1;
            end
        end else if (phase == S_DONE) begin
            if (clr) begin
                phase   <= S_IDLE;
                rem     <= 2'd0;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b0;
            end
        end else if (acc) begin
            rem     <= rnext(rem, in_bit);
            val     <= {val[W-2:0], in_bit};
            cnt     <= cnt + 16'd1;
            started <= 1'b1;
            if (cnt + 16'd1 == limit) phase <= S_DONE;
            else                      phase <= S_RUN;
        end
    end

    assign done  = (phase == S_DONE);
    assign div3  = (rem == 2'd0);
    assign o_rem = rem;

    always @(posedge clk)
        if (win && $rose(done))
            assert (started && (div3 == ((val % 16'd3) == 16'd0)));
endmodule

module first_ready_latch #(
    parameter NCH  = 4,
    parameter IDXW = 2,
    parameter CW   = 64
) (
    input  wire            clk,
    input  wire            rst,
    input  wire            ce,
    input  wire            arm,
    input  wire            clr,
    input  wire [NCH-1:0]  ch_rdy,
    output reg  [IDXW-1:0] winner,
    output reg             captured,
    output reg             armed,
    output reg  [CW-1:0]   cap_cnt
);
    initial begin
        winner   = {IDXW{1'b0}};
        captured = 1'b0;
        armed    = 1'b0;
        cap_cnt  = {CW{1'b0}};
    end

    reg [IDXW-1:0] first_idx;
    integer i;
    always @(*) begin
        first_idx = {IDXW{1'b0}};
        for (i = NCH-1; i >= 0; i = i - 1)
            if (ch_rdy[i]) first_idx = i[IDXW-1:0];
    end

    wire any_rdy = |ch_rdy;

    always @(posedge clk) begin
        if (rst) begin
            winner   <= {IDXW{1'b0}};
            captured <= 1'b0;
            armed    <= 1'b0;
            cap_cnt  <= {CW{1'b0}};
        end else if (ce) begin
            if (clr) begin
                armed    <= 1'b0;
                captured <= 1'b0;
                cap_cnt  <= {CW{1'b0}};
            end else if (arm) begin
                armed    <= 1'b1;
                captured <= 1'b0;
                cap_cnt  <= {CW{1'b0}};
            end else if (armed && !captured && any_rdy) begin
                captured <= 1'b1;
                winner   <= first_idx;
                cap_cnt  <= cap_cnt + {{(CW-1){1'b0}}, 1'b1};
            end
        end
    end

    always @(*) assert (!armed || cap_cnt <= 64'd1);
endmodule

module noc_freq_meter #(
    parameter GATE = 8
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        in_valid,
    output wire        in_ready,
    input  wire        in_edge,
    output reg         out_valid,
    input  wire        out_ready,
    output reg  [31:0] result
);
    reg [31:0] gate_cnt;
    reg [31:0] ev_cnt;
    reg [31:0] gate_snap;
    reg        armed;

    initial begin
        gate_cnt  = 32'd0;
        ev_cnt    = 32'd0;
        gate_snap = 32'd0;
        result    = 32'd0;
        out_valid = 1'b0;
        armed     = 1'b0;
    end

    assign in_ready = !out_valid;
    wire in_fire    = in_valid && in_ready;
    wire out_fire   = out_valid && out_ready;
    wire gate_close = in_fire && (gate_cnt == GATE - 1);

    always @(posedge clk) begin
        if (rst) begin
            gate_cnt  <= 32'd0;
            ev_cnt    <= 32'd0;
            gate_snap <= 32'd0;
            result    <= 32'd0;
            out_valid <= 1'b0;
            armed     <= 1'b0;
        end else begin
            if (in_fire)
                armed <= 1'b1;
            if (in_fire) begin
                if (gate_close) begin
                    gate_cnt  <= 32'd0;
                    ev_cnt    <= 32'd0;
                    result    <= ev_cnt + {31'd0, in_edge};
                    gate_snap <= gate_cnt + 32'd1;
                    out_valid <= 1'b1;
                end else begin
                    gate_cnt <= gate_cnt + 32'd1;
                    ev_cnt   <= ev_cnt + {31'd0, in_edge};
                end
            end else if (out_fire) begin
                out_valid <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (armed && out_valid)
            assert (result <= gate_snap);
endmodule

module wc_buffer #(
    parameter WORDS = 4,
    parameter [31:0] TIMEOUT = 32'd8
)(
    input wire clk,
    input wire rst,
    input wire ce,
    input wire st_valid,
    input wire [31:0] st_line,
    input wire [$clog2(WORDS)-1:0] st_word,
    input wire [31:0] st_data,
    input wire [3:0] st_be,
    output reg wr_burst,
    output reg [31:0] wr_line,
    output reg [WORDS*32-1:0] wr_data,
    output reg [WORDS*4-1:0] wr_mask
);
    localparam MW = WORDS*4;
    localparam DW = WORDS*32;

    reg v = 1'b0;
    reg [31:0] line_addr = 32'd0;
    reg [DW-1:0] line_data = {DW{1'b0}};
    reg [MW-1:0] mask = {MW{1'b0}};
    reg [31:0] timer = 32'd0;
    reg [31:0] age = 32'd0;
    reg armed = 1'b0;
    reg pv = 1'b0;

    initial begin
        wr_burst = 1'b0;
        wr_line = 32'd0;
        wr_data = {DW{1'b0}};
        wr_mask = {MW{1'b0}};
    end

    wire hit = v && st_valid && (st_line == line_addr);
    wire miss = st_valid && !hit;

    reg [DW-1:0] in_data;
    reg [DW-1:0] in_bits;
    reg [MW-1:0] in_mask;
    integer b;
    always @(*) begin
        in_data = {DW{1'b0}};
        in_bits = {DW{1'b0}};
        in_mask = {MW{1'b0}};
        for (b = 0; b < 4; b = b + 1) begin
            in_data[st_word*32 + b*8 +: 8] = st_data[b*8 +: 8];
            in_bits[st_word*32 + b*8 +: 8] = {8{st_be[b]}};
            in_mask[st_word*4 + b] = st_be[b];
        end
    end

    wire [DW-1:0] n_data = hit ? ((line_data & ~in_bits) | (in_data & in_bits)) : line_data;
    wire [MW-1:0] n_mask = hit ? (mask | in_mask) : mask;
    wire timeout = (age == TIMEOUT - 32'd1);
    wire full = (n_mask == {MW{1'b1}});
    wire flush = v && (miss || timeout || full);
    wire expired = (timer == 32'd0);

    always @(posedge clk) begin
        pv <= 1'b1;
        if (rst) begin
            v <= 1'b0;
            line_addr <= 32'd0;
            line_data <= {DW{1'b0}};
            mask <= {MW{1'b0}};
            timer <= 32'd0;
            age <= 32'd0;
            wr_burst <= 1'b0;
            wr_line <= 32'd0;
            wr_data <= {DW{1'b0}};
            wr_mask <= {MW{1'b0}};
        end else if (ce) begin
            if (st_valid) armed <= 1'b1;
            wr_burst <= flush;
            if (flush) begin
                wr_line <= line_addr;
                wr_data <= n_data;
                wr_mask <= n_mask;
            end
            if (miss) begin
                v <= 1'b1;
                line_addr <= st_line;
                line_data <= in_data & in_bits;
                mask <= in_mask;
                timer <= TIMEOUT;
                age <= 32'd0;
            end else if (flush) begin
                v <= 1'b0;
                line_data <= {DW{1'b0}};
                mask <= {MW{1'b0}};
                timer <= 32'd0;
                age <= 32'd0;
            end else if (v) begin
                line_data <= n_data;
                mask <= n_mask;
                timer <= timer - 32'd1;
                age <= age + 32'd1;
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && $rose(expired))
            assert (!v);
endmodule

module qp_zins_mux #(
    parameter DEPTH = 16,
    parameter DW = 32,
    parameter SW = $clog2(DEPTH)
) (
    input  wire          clk,
    input  wire          i_reset,
    input  wire          i_load,
    input  wire [31:0]   i_limit,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [SW-1:0] in_qp,
    input  wire [DW-1:0] in_data,
    input  wire          i_drain,
    output wire [DW-1:0] o_data,
    output wire          o_valid
);
    reg [DEPTH*DW-1:0] data_flat;
    reg [DEPTH-1:0]    mask;
    reg [SW-1:0]       sel;
    reg [31:0]         cnt;
    reg [31:0]         limit;
    reg                win;

    initial data_flat = {(DEPTH*DW){1'b0}};
    initial mask = {DEPTH{1'b0}};
    initial sel = {SW{1'b0}};
    initial cnt = 32'd0;
    initial limit = DEPTH;
    initial win = 1'b0;

    wire hit = mask[sel];
    assign in_ready = !mask[in_qp] && (cnt < limit);
    wire in_fire = in_valid && in_ready;
    wire drn_hit = i_drain && hit;

    wire [DEPTH-1:0] one_m = {{(DEPTH-1){1'b0}}, 1'b1};
    wire [DEPTH-1:0] set_m = in_fire ? (one_m << in_qp) : {DEPTH{1'b0}};
    wire [DEPTH-1:0] clr_m = drn_hit ? (one_m << sel) : {DEPTH{1'b0}};

    // zero-insertion multiplexer: selected slot if valid, else constant zero
    assign o_valid = hit;
    assign o_data  = hit ? data_flat[sel*DW +: DW] : {DW{1'b0}};

    always @(posedge clk) begin
        if (i_reset) begin
            mask  <= {DEPTH{1'b0}};
            sel   <= {SW{1'b0}};
            cnt   <= 32'd0;
            win   <= 1'b0;
            limit <= i_limit;
        end else begin
            if (i_load)
                limit <= i_limit;
            if (in_fire)
                data_flat[in_qp*DW +: DW] <= in_data;
            mask <= (mask & ~clr_m) | set_m;
            cnt  <= cnt + (in_fire ? 32'd1 : 32'd0) - (drn_hit ? 32'd1 : 32'd0);
            if (i_drain)
                sel <= (sel == DEPTH-1) ? {SW{1'b0}} : sel + 1'b1;
            if (i_load)
                win <= 1'b0;
            else if (in_fire)
                win <= 1'b1;
        end
    end

    always @(posedge clk)
        if (win) assert (cnt <= DEPTH);

    always @(posedge clk)
        if (win) assert (cnt != 32'd0 || o_data == {DW{1'b0}});
endmodule

module autoneg_arb #(
    parameter [63:0] LINK_TIME  = 64'd12,
    parameter [63:0] LOCAL_ABIL = 64'h0000_0000_0000_01E0
) (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_start,
    input  wire        i_rx_valid,
    input  wire [63:0] i_rx_page,
    input  wire        i_link_fail,
    output wire        o_link_up,
    output wire [63:0] o_mode
);
    typedef enum logic [2:0] {AN_IDLE, AN_ABILITY, AN_ACK, AN_COMPLETE, AN_LINK_OK} an_state_t;

    an_state_t state;
    reg [63:0] link_tmr;
    reg [63:0] remain;
    reg [63:0] rx_abil;
    reg [63:0] mode;
    reg        win;

    initial state    = AN_IDLE;
    initial link_tmr = 64'd0;
    initial remain   = LINK_TIME;
    initial rx_abil  = 64'd0;
    initial mode     = 64'd0;
    initial win      = 1'b0;

    always @(posedge clk) begin
        if (i_reset) begin
            state    <= AN_IDLE;
            link_tmr <= 64'd0;
            remain   <= LINK_TIME;
            rx_abil  <= 64'd0;
            mode     <= 64'd0;
            win      <= 1'b0;
        end else if (i_ce) begin
            case (state)
                AN_IDLE: begin
                    if (i_start) begin
                        state    <= AN_ABILITY;
                        link_tmr <= 64'd0;
                        remain   <= LINK_TIME;
                        win      <= 1'b1;
                    end
                end
                AN_ABILITY: begin
                    if (i_rx_valid) begin
                        rx_abil  <= i_rx_page;
                        link_tmr <= 64'd0;
                        remain   <= LINK_TIME;
                        state    <= AN_ACK;
                    end else if (remain == 64'd0) begin
                        state <= AN_IDLE;
                    end else begin
                        link_tmr <= link_tmr + 64'd1;
                        remain   <= remain - 64'd1;
                    end
                end
                AN_ACK: begin
                    if (remain == 64'd0) begin
                        mode  <= rx_abil & LOCAL_ABIL;
                        state <= AN_COMPLETE;
                    end else begin
                        link_tmr <= link_tmr + 64'd1;
                        remain   <= remain - 64'd1;
                    end
                end
                AN_COMPLETE: begin
                    state <= AN_LINK_OK;
                    win   <= 1'b0;
                end
                AN_LINK_OK: begin
                    if (i_link_fail)
                        state <= AN_IDLE;
                end
                default: state <= AN_IDLE;
            endcase
        end
    end

    assign o_link_up = (state == AN_LINK_OK);
    assign o_mode    = mode;

    always @(posedge clk)
        if (win)
            assert (link_tmr <= LINK_TIME);
endmodule

module apb_periph_ctrl #(
    parameter NREG = 12,
    parameter [31:0] WAIT = 32'd3,
    parameter [31:0] K = WAIT + 32'd2
)(
    input  wire        clk,
    input  wire        i_ce,
    input  wire        req_valid,
    output wire        req_ready,
    input  wire        req_write,
    input  wire [3:0]  req_addr,
    input  wire [31:0] req_wdata,
    output reg  [31:0] rdata,
    output reg         pslverr_o,
    output wire        psel,
    output reg         penable
);
    typedef enum logic [1:0] {IDLE = 2'd0, SETUP = 2'd1, ACCESS = 2'd2} state_t;

    state_t     state;
    reg [31:0]  timer;
    reg [31:0]  wait_cnt;
    reg [3:0]   sel;
    reg         wr;
    reg [31:0]  wdata;
    reg         err;
    reg         armed;
    reg [31:0]  regs [0:NREG-1];

    integer i;
    initial begin
        state     = IDLE;
        timer     = 32'd0;
        wait_cnt  = 32'd0;
        sel       = 4'd0;
        wr        = 1'b0;
        wdata     = 32'd0;
        err       = 1'b0;
        armed     = 1'b1;
        rdata     = 32'd0;
        pslverr_o = 1'b0;
        penable   = 1'b0;
        for (i = 0; i < NREG; i = i + 1) regs[i] = 32'd0;
    end

    assign req_ready = i_ce && (state == IDLE);
    assign psel      = (state != IDLE);

    always @(posedge clk) begin
        if (i_ce) begin
            case (state)
                IDLE: begin
                    if (req_valid) begin
                        state <= SETUP;
                        timer <= K;
                        wr    <= req_write;
                        wdata <= req_wdata;
                        if (req_addr < NREG) begin
                            sel <= req_addr;
                            err <= 1'b0;
                        end else begin
                            sel <= 4'd0;
                            err <= 1'b1;
                        end
                    end
                end
                SETUP: begin
                    state    <= ACCESS;
                    penable  <= 1'b1;
                    timer    <= timer - 32'd1;
                    wait_cnt <= WAIT;
                end
                ACCESS: begin
                    if (wait_cnt == 32'd0) begin
                        state     <= IDLE;
                        penable   <= 1'b0;
                        timer     <= 32'd0;
                        pslverr_o <= err;
                        if (err)
                            armed <= 1'b0;
                        else if (wr)
                            regs[sel] <= wdata;
                        else
                            rdata <= regs[sel];
                    end else begin
                        wait_cnt <= wait_cnt - 32'd1;
                        timer    <= timer - 32'd1;
                    end
                end
                default: begin
                    state   <= IDLE;
                    penable <= 1'b0;
                    timer   <= 32'd0;
                end
            endcase
        end
    end

    // Bounded response, before the first slave error:
    // the completion countdown never expires while a transfer is outstanding
    always @(posedge clk)
        if (armed && state != IDLE) assert (timer != 32'd0);

    // during the access phase the countdown always outlasts the remaining wait states
    always @(posedge clk)
        if (armed && penable) assert (timer > wait_cnt);
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, i_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, i_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, i_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    assign i_ready = !o_valid || o_ready;
    wire in_fire  = i_valid && i_ready;
    wire out_fire = o_valid && o_ready;

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= i_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && i_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
endmodule

module ckpt_regfile #(
    parameter NREG = 256,
    parameter NCK  = 4,
    parameter DW   = 32,
    parameter AW   = 8,
    parameter TW   = 2
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          cmd_valid,
    output wire          cmd_ready,
    input  wire [1:0]    cmd_op,
    input  wire [AW-1:0] cmd_addr,
    input  wire [DW-1:0] cmd_data,
    input  wire [TW-1:0] cmd_tag,
    input  wire [AW-1:0] rd_addr,
    output reg  [DW-1:0] rd_data,
    output reg  [TW-1:0] alloc_tag,
    output reg           alloc_found,
    output wire [NCK-1:0] ckpt_mask_o,
    output wire [31:0]   ckpt_count_o
);
    localparam [1:0] OP_WRITE   = 2'd0;
    localparam [1:0] OP_BRANCH  = 2'd1;
    localparam [1:0] OP_RESOLVE = 2'd2;
    localparam [1:0] OP_MISPRED = 2'd3;
    localparam W = NREG * DW;

    reg [W-1:0]     rf       = {W{1'b0}};
    reg [NCK*W-1:0] ck       = {(NCK*W){1'b0}};
    reg [NCK-1:0]   ck_mask  = {NCK{1'b0}};
    reg [31:0]      ck_count = 32'd0;

    assign ckpt_mask_o  = ck_mask;
    assign ckpt_count_o = ck_count;

    assign cmd_ready = !(cmd_op == OP_BRANCH && ck_count >= NCK);
    wire fire    = cmd_valid && cmd_ready;
    wire br_fire = fire && (cmd_op == OP_BRANCH);

    integer i;
    always @(*) begin
        alloc_found = 1'b0;
        alloc_tag   = {TW{1'b0}};
        for (i = 0; i < NCK; i = i + 1)
            if (!alloc_found && !ck_mask[i]) begin
                alloc_found = 1'b1;
                alloc_tag   = i;
            end
    end

    integer j;
    always @(*) begin
        rd_data = {DW{1'b0}};
        for (j = 0; j < NREG; j = j + 1)
            if (rd_addr == j) rd_data = rf[j*DW +: DW];
    end

    integer k;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rf       <= {W{1'b0}};
            ck       <= {(NCK*W){1'b0}};
            ck_mask  <= {NCK{1'b0}};
            ck_count <= 32'd0;
        end else if (fire) begin
            case (cmd_op)
                OP_WRITE: begin
                    for (k = 0; k < NREG; k = k + 1)
                        if (cmd_addr == k) rf[k*DW +: DW] <= cmd_data;
                end
                OP_BRANCH: begin
                    if (alloc_found) begin
                        for (k = 0; k < NCK; k = k + 1)
                            if (alloc_tag == k) ck[k*W +: W] <= rf;
                        ck_mask[alloc_tag] <= 1'b1;
                    end
                    ck_count <= ck_count + 32'd1;
                end
                OP_RESOLVE: begin
                    if (ck_mask[cmd_tag]) begin
                        ck_mask[cmd_tag] <= 1'b0;
                        ck_count <= ck_count - 32'd1;
                    end
                end
                OP_MISPRED: begin
                    if (ck_mask[cmd_tag]) begin
                        for (k = 0; k < NCK; k = k + 1)
                            if (cmd_tag == k) rf <= ck[k*W +: W];
                        ck_mask  <= {NCK{1'b0}};
                        ck_count <= 32'd0;
                    end
                end
            endcase
        end
    end

    reg pv = 1'b0;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && $past(br_fire))
            assert (ck_mask != $past(ck_mask));
endmodule

module exp_scale_unit #(
    parameter EW = 8,
    parameter SW = 8,
    parameter MAXSH = 9
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          ce,
    input  wire          arm,
    input  wire          start,
    input  wire [EW-1:0] exp_in,
    input  wire [SW-1:0] sig_in,
    input  wire [7:0]    scale_in,
    output wire [EW-1:0] o_exp,
    output wire [SW-1:0] o_sig,
    output wire          o_ovf,
    output wire          o_uf,
    output wire          o_done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, STARTED = 2'd2, FINISHED = 2'd3;
    localparam [EW-1:0] EXP_INF = {EW{1'b1}};
    localparam [3:0] MAXSH4 = MAXSH;

    reg [1:0]    phase    = IDLE;
    reg          busy     = 1'b0;
    reg [3:0]    sh_cnt   = 4'd0;
    reg [EW-1:0] op_exp   = {EW{1'b0}};
    reg [SW-1:0] op_sig   = {SW{1'b0}};
    reg [7:0]    op_scale = 8'd0;
    reg [EW-1:0] work_exp = {EW{1'b0}};
    reg [SW-1:0] work_sig = {SW{1'b0}};
    reg          work_ovf = 1'b0;
    reg          work_uf  = 1'b0;
    reg          sticky   = 1'b0;
    reg [EW-1:0] res_exp  = {EW{1'b0}};
    reg [SW-1:0] res_sig  = {SW{1'b0}};
    reg          res_ovf  = 1'b0;
    reg          res_uf   = 1'b0;
    reg          no_ovf   = 1'b1;
    reg          pv       = 1'b0;

    wire [EW+1:0] sum   = {2'b00, op_exp} + {{2{op_scale[7]}}, op_scale};
    wire [EW+1:0] under = {{(EW+1){1'b0}}, 1'b1} - sum;
    wire          sum_neg = sum[EW+1];
    wire          sum_ovf = !sum_neg && (sum[EW:0] >= {1'b0, EXP_INF});
    wire          sum_unf = sum_neg || (sum == {(EW+2){1'b0}});
    wire [3:0]    sh_amt  = (under > MAXSH) ? MAXSH4 : under[3:0];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase    <= IDLE;
            busy     <= 1'b0;
            sh_cnt   <= 4'd0;
            op_exp   <= {EW{1'b0}};
            op_sig   <= {SW{1'b0}};
            op_scale <= 8'd0;
            work_exp <= {EW{1'b0}};
            work_sig <= {SW{1'b0}};
            work_ovf <= 1'b0;
            work_uf  <= 1'b0;
            sticky   <= 1'b0;
            res_exp  <= {EW{1'b0}};
            res_sig  <= {SW{1'b0}};
            res_ovf  <= 1'b0;
            res_uf   <= 1'b0;
            no_ovf   <= 1'b1;
        end else if (ce) begin
            case (phase)
                IDLE: if (arm) begin
                    op_exp   <= exp_in;
                    op_sig   <= sig_in;
                    op_scale <= scale_in;
                    phase    <= ARMED;
                end
                ARMED: if (start) begin
                    busy   <= 1'b1;
                    sticky <= 1'b0;
                    phase  <= STARTED;
                    if (sum_ovf) begin
                        work_exp <= EXP_INF;
                        work_sig <= {SW{1'b0}};
                        work_ovf <= 1'b1;
                        work_uf  <= 1'b0;
                        sh_cnt   <= 4'd0;
                    end else if (sum_unf) begin
                        work_exp <= {EW{1'b0}};
                        work_sig <= op_sig;
                        work_ovf <= 1'b0;
                        work_uf  <= 1'b1;
                        sh_cnt   <= sh_amt;
                    end else begin
                        work_exp <= sum[EW-1:0];
                        work_sig <= op_sig;
                        work_ovf <= 1'b0;
                        work_uf  <= 1'b0;
                        sh_cnt   <= 4'd0;
                    end
                end
                STARTED: if (sh_cnt == 4'd0) phase <= FINISHED;
                FINISHED: phase <= IDLE;
            endcase
            if (busy) begin
                if (sh_cnt != 4'd0) begin
                    work_sig <= work_sig >> 1;
                    sticky   <= sticky | work_sig[0];
                    sh_cnt   <= sh_cnt - 4'd1;
                end else begin
                    res_exp <= work_exp;
                    res_sig <= work_sig;
                    res_ovf <= work_ovf;
                    res_uf  <= work_uf & (sticky | (work_sig == {SW{1'b0}}));
                    busy    <= 1'b0;
                    if (work_ovf) no_ovf <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    assign o_exp  = res_exp;
    assign o_sig  = res_sig;
    assign o_ovf  = res_ovf;
    assign o_uf   = res_uf;
    assign o_done = (phase == FINISHED);

    always @(posedge clk)
        if (pv && no_ovf && $stable(phase))
            assert ($stable(res_exp) && $stable(res_sig));
endmodule

module islip_alloc #(
    parameter N  = 4,
    parameter W  = 2,
    parameter CW = 64
) (
    input  wire           clk,
    input  wire           rst,
    input  wire           step,
    input  wire [N*N-1:0] req,
    input  wire [N-1:0]   rel,
    output reg  [N-1:0]   in_busy,
    output reg  [N*W-1:0] in_dst,
    output reg  [N-1:0]   out_busy,
    output reg  [N*W-1:0] out_src,
    output reg  [CW-1:0]  match_count,
    output reg            armed
);
    reg [N*W-1:0] g_ptr;
    reg [N*W-1:0] a_ptr;

    initial begin
        in_busy     = {N{1'b0}};
        in_dst      = {(N*W){1'b0}};
        out_busy    = {N{1'b0}};
        out_src     = {(N*W){1'b0}};
        g_ptr       = {(N*W){1'b0}};
        a_ptr       = {(N*W){1'b0}};
        match_count = {CW{1'b0}};
        armed       = 1'b0;
    end

    // grant phase: each free output picks a free requesting input, round robin from g_ptr
    integer gi, go, gk;
    reg [W-1:0]   tmp_g;
    reg [N-1:0]   gnt_v;
    reg [N*W-1:0] gnt_in;
    always @(*) begin
        gnt_v  = {N{1'b0}};
        gnt_in = {(N*W){1'b0}};
        tmp_g  = {W{1'b0}};
        for (go = 0; go < N; go = go + 1)
            for (gk = N-1; gk >= 0; gk = gk - 1) begin
                tmp_g = g_ptr[go*W +: W] + gk;
                for (gi = 0; gi < N; gi = gi + 1)
                    if (tmp_g == gi && !out_busy[go] && !in_busy[gi] && req[gi*N+go]) begin
                        gnt_v[go] = 1'b1;
                        gnt_in[go*W +: W] = gi;
                    end
            end
    end

    // accept phase: each free input accepts one granting output, round robin from a_ptr
    integer ai, ao, ak;
    reg [W-1:0]   tmp_a;
    reg [N-1:0]   acc_v;
    reg [N*W-1:0] acc_out;
    always @(*) begin
        acc_v   = {N{1'b0}};
        acc_out = {(N*W){1'b0}};
        tmp_a   = {W{1'b0}};
        for (ai = 0; ai < N; ai = ai + 1)
            for (ak = N-1; ak >= 0; ak = ak - 1) begin
                tmp_a = a_ptr[ai*W +: W] + ak;
                for (ao = 0; ao < N; ao = ao + 1)
                    if (tmp_a == ao && !in_busy[ai] && gnt_v[ao] && gnt_in[ao*W +: W] == ai) begin
                        acc_v[ai] = 1'b1;
                        acc_out[ai*W +: W] = ao;
                    end
            end
    end

    // next-state: releases tear down, accepted matches connect, pointers advance only on accept
    integer ni, no;
    reg [N-1:0]   in_busy_n;
    reg [N*W-1:0] in_dst_n;
    reg [N-1:0]   out_busy_n;
    reg [N*W-1:0] out_src_n;
    reg [N*W-1:0] g_ptr_n;
    reg [N*W-1:0] a_ptr_n;
    reg [W:0]     n_acc;
    always @(*) begin
        in_busy_n  = in_busy;
        in_dst_n   = in_dst;
        out_busy_n = out_busy;
        out_src_n  = out_src;
        g_ptr_n    = g_ptr;
        a_ptr_n    = a_ptr;
        n_acc      = {(W+1){1'b0}};
        for (ni = 0; ni < N; ni = ni + 1) begin
            if (rel[ni] && in_busy[ni])
                in_busy_n[ni] = 1'b0;
            if (acc_v[ni]) begin
                in_busy_n[ni]        = 1'b1;
                in_dst_n[ni*W +: W]  = acc_out[ni*W +: W];
                a_ptr_n[ni*W +: W]   = acc_out[ni*W +: W] + 1'b1;
                n_acc                = n_acc + 1'b1;
            end
            for (no = 0; no < N; no = no + 1) begin
                if (rel[ni] && in_busy[ni] && in_dst[ni*W +: W] == no)
                    out_busy_n[no] = 1'b0;
                if (acc_v[ni] && acc_out[ni*W +: W] == no) begin
                    out_busy_n[no]       = 1'b1;
                    out_src_n[no*W +: W] = ni;
                    g_ptr_n[no*W +: W]   = ni + 1;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            in_busy     <= {N{1'b0}};
            in_dst      <= {(N*W){1'b0}};
            out_busy    <= {N{1'b0}};
            out_src     <= {(N*W){1'b0}};
            g_ptr       <= {(N*W){1'b0}};
            a_ptr       <= {(N*W){1'b0}};
            match_count <= {CW{1'b0}};
        end else if (step) begin
            in_busy     <= in_busy_n;
            in_dst      <= in_dst_n;
            out_busy    <= out_busy_n;
            out_src     <= out_src_n;
            g_ptr       <= g_ptr_n;
            a_ptr       <= a_ptr_n;
            match_count <= match_count + n_acc;
            if (|acc_v)
                armed <= 1'b1;
        end
    end

    // absence: two inputs never own the same output (after the first match)
    integer pi, pj;
    reg dup;
    always @(*) begin
        dup = 1'b0;
        for (pi = 0; pi < N; pi = pi + 1)
            for (pj = pi + 1; pj < N; pj = pj + 1)
                if (in_busy[pi] && in_busy[pj] && in_dst[pi*W +: W] == in_dst[pj*W +: W])
                    dup = 1'b1;
    end

    assert property (!armed || !dup);
endmodule

module frac_xmul_cmp #(
    parameter W = 32
) (
    input  wire           clk,
    input  wire           rst,
    // input channel: op=0 loads two fractions a/b and c/d, op=1 takes the reciprocal of both held fractions
    input  wire           in_valid,
    output wire           in_ready,
    input  wire           in_op,
    input  wire [W-1:0]   in_a,
    input  wire [W-1:0]   in_b,
    input  wire [W-1:0]   in_c,
    input  wire [W-1:0]   in_d,
    // output channel: registered cross products and relation result
    output reg            out_valid,
    input  wire           out_ready,
    output reg [2*W-1:0]  p_ad,
    output reg [2*W-1:0]  p_cb,
    output reg            lt_q,
    output reg            gt_q,
    output wire           eq_q
);
    initial begin
        out_valid = 1'b0;
        p_ad      = {2*W{1'b0}};
        p_cb      = {2*W{1'b0}};
        lt_q      = 1'b0;
        gt_q      = 1'b0;
    end

    // cross multiply: a/b vs c/d  <=>  a*d vs c*b (no division)
    wire [2*W-1:0] m_ad = in_a * in_d;
    wire [2*W-1:0] m_cb = in_c * in_b;

    assign in_ready = !out_valid || out_ready;
    wire in_fire  = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    assign eq_q = !lt_q && !gt_q;

    always @(posedge clk) begin
        if (rst) begin
            out_valid <= 1'b0;
            p_ad      <= {2*W{1'b0}};
            p_cb      <= {2*W{1'b0}};
            lt_q      <= 1'b0;
            gt_q      <= 1'b0;
        end else if (in_fire) begin
            out_valid <= 1'b1;
            if (in_op) begin
                // reciprocal of both fractions: b/a vs d/c -> b*c vs d*a, products and relation swap
                p_ad <= p_cb;
                p_cb <= p_ad;
                lt_q <= gt_q;
                gt_q <= lt_q;
            end else begin
                p_ad <= m_ad;
                p_cb <= m_cb;
                lt_q <= (m_ad < m_cb);
                gt_q <= (m_ad > m_cb);
            end
        end else if (out_fire) begin
            out_valid <= 1'b0;
        end
    end

    // Absence: the 'greater' result flag and products that are not greater never coexist
    wire prod_le = (p_ad <= p_cb);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv)
            assert (!($past(gt_q) && $past(prod_le)));
endmodule

module gardner_ted_lxp (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [7:0] sample_in,
    output wire [15:0] o_err,
    output wire o_strobe
);
    reg phase;
    reg [7:0] prev_sym, mid, cur_sym;
    reg [7:0] sym_cnt;
    reg [7:0] half_cnt;
    reg [15:0] err_out;
reg [15:0] wb_err;
reg [4:0] wb_addr;
reg wb_vld;
    reg [15:0] err_mem [0:31];
    integer i;

    initial begin
        phase = 1'b0;
        prev_sym = 8'd0;
        mid = 8'd0;
        cur_sym = 8'd0;
        sym_cnt = 8'd0;
        half_cnt = 8'd0;
        err_out = 16'd0;
wb_err = 16'd0;
wb_addr = 5'd0;
wb_vld = 1'b0;
        for (i = 0; i < 32; i = i + 1) err_mem[i] = 16'd0;
    end

    wire signed [8:0] diff = $signed({sample_in[7], sample_in}) - $signed({cur_sym[7], cur_sym});
    wire signed [16:0] prod = diff * $signed({mid[7], mid});
    wire [15:0] err = prod[15:0];

    always @(posedge clk) begin
        if (rst) begin
            phase <= 1'b0;
            prev_sym <= 8'd0;
            mid <= 8'd0;
            cur_sym <= 8'd0;
            sym_cnt <= 8'd0;
            half_cnt <= 8'd0;
            err_out <= 16'd0;
wb_err <= 16'd0;
wb_addr <= 5'd0;
wb_vld <= 1'b0;
            for (i = 0; i < 32; i = i + 1) err_mem[i] <= 16'd0;
        end else if (en) begin
            phase <= ~phase;
wb_vld <= 1'b0;
if (wb_vld) begin
err_out <= wb_err;
err_mem[wb_addr] <= wb_err;
if (wb_addr == 5'd31)
sym_cnt <= 8'd0;
else
sym_cnt <= sym_cnt + 8'd1;
end
            if (!phase) begin
                mid <= sample_in;
            end else begin
                prev_sym <= cur_sym;
                cur_sym <= sample_in;
wb_err <= err;
wb_addr <= sym_cnt[4:0];
wb_vld <= 1'b1;
            end
            if (half_cnt == 8'd63) begin
                half_cnt <= 8'd0;
            end else begin
                half_cnt <= half_cnt + 8'd1;
            end
        end
    end

    assign o_err = err_out;
    assign o_strobe = phase;

    always @(*) assert (sym_cnt <= 8'd31);
endmodule

module crc_residue_chk (
    input  wire clk,
    input  wire ce,
    input  wire start,
    input  wire din,
    output reg  done,
    output reg  err
);
    // bit-serial CRC-8 (poly x^8+x^2+x+1) residue checker:
    // 8 data bits followed by 8 appended CRC bits; residue must be zero
    reg [7:0] crc    = 8'h00;
reg [7:0] bitcnt = 8'd0;   // data bits consumed in current frame (saturates at 8)
reg [7:0] chkcnt = 8'd0;   // appended CRC bits consumed in current frame
    reg [7:0] timer  = 8'd0;   // completion watchdog countdown
    reg       busy   = 1'b0;   // frame outstanding
    reg       armed  = 1'b1;   // scope: no CRC error has ever been flagged
    initial done = 1'b0;
    initial err  = 1'b0;

    wire       fb       = crc[7] ^ din;
    wire [7:0] crc_next = {crc[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);
wire       in_chk   = (bitcnt == 8'd8);   // data phase complete, consuming CRC bits
wire       last     = busy && ce && in_chk && (chkcnt == 8'd7);

    always @(posedge clk) begin
        if (!busy) begin
            if (start) begin
                busy   <= 1'b1;
                bitcnt <= 8'd0;
chkcnt <= 8'd0;
                timer  <= 8'd16;
                crc    <= 8'h00;
                done   <= 1'b0;
                err    <= 1'b0;
            end
        end else if (ce) begin
            crc    <= crc_next;
if (in_chk) chkcnt <= chkcnt + 8'd1;
else        bitcnt <= bitcnt + 8'd1;
            timer  <= timer - 8'd1;
if (in_chk && (chkcnt == 8'd7)) begin
                busy <= 1'b0;
                done <= 1'b1;
                err  <= (crc_next != 8'h00);
            end
        end
        if (last && (crc_next != 8'h00))
            armed <= 1'b0;
    end

    // before the first CRC error: the watchdog never expires while a frame is outstanding
    always @(*)
        assert (!armed || !busy || timer != 8'd0);
endmodule

module vcd_mac_learn (
    input wire clk,
    input wire rst,
    input wire en,
    input wire learn_v,
    input wire [31:0] src_mac,
    input wire [3:0] src_port,
    input wire look_v,
    input wire [31:0] dst_mac,
    input wire age_tick,
    input wire win_open,
    input wire win_close,
    output wire o_hit,
    output wire [3:0] o_port,
output wire o_win,
output reg [3:0] tick_cnt
);
    reg [383:0] key_flat;
    reg [47:0]  port_flat;
    reg [11:0]  valid;
    reg [11:0]  age;
    reg [3:0]   rr_ptr;
    reg [31:0]  learn_cnt;
    reg         hit_q;
    reg [3:0]   out_port;
    reg         win;

    initial key_flat = 384'd0;
    initial port_flat = 48'd0;
    initial valid = 12'd0;
    initial age = 12'd0;
    initial rr_ptr = 4'd0;
    initial learn_cnt = 32'd0;
    initial hit_q = 1'b0;
    initial out_port = 4'd0;
    initial win = 1'b0;
initial tick_cnt = 4'd0;

    assign o_hit = hit_q;
    assign o_port = out_port;
    assign o_win = win;

    integer i;
    reg match_any;
    reg [3:0] match_idx;
    reg free_any;
    reg [3:0] free_idx;
    reg look_hit;
    reg [3:0] look_idx;
    always @(*) begin
        match_any = 1'b0; match_idx = 4'd0;
        free_any = 1'b0;  free_idx = 4'd0;
        look_hit = 1'b0;  look_idx = 4'd0;
        for (i = 11; i >= 0; i = i - 1) begin
            if (valid[i] && (key_flat[i*32 +: 32] == src_mac)) begin
                match_any = 1'b1; match_idx = i;
            end
            if (!valid[i]) begin
                free_any = 1'b1; free_idx = i;
            end
            if (valid[i] && (key_flat[i*32 +: 32] == dst_mac)) begin
                look_hit = 1'b1; look_idx = i;
            end
        end
    end

    wire [3:0] tgt = match_any ? match_idx : (free_any ? free_idx : rr_ptr);

    reg [11:0] valid_n;
    reg [11:0] age_n;
    always @(*) begin
        valid_n = valid;
        age_n = age;
        if (age_tick) begin
            valid_n = valid & age;
            age_n = 12'd0;
        end
        if (look_v && look_hit)
            age_n[look_idx] = 1'b1;
        if (learn_v) begin
            valid_n[tgt] = 1'b1;
            age_n[tgt] = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            key_flat <= 384'd0;
            port_flat <= 48'd0;
            valid <= 12'd0;
            age <= 12'd0;
            rr_ptr <= 4'd0;
            learn_cnt <= 32'd0;
            hit_q <= 1'b0;
            out_port <= 4'd0;
            win <= 1'b0;
tick_cnt <= 4'd0;
        end else if (en) begin
            valid <= valid_n;
            age <= age_n;
            hit_q <= look_v & look_hit;
            if (look_v && look_hit)
                out_port <= port_flat[look_idx*4 +: 4];
            if (learn_v) begin
                key_flat[tgt*32 +: 32] <= src_mac;
                port_flat[tgt*4 +: 4] <= src_port;
                if (!match_any)
                    rr_ptr <= (rr_ptr >= 4'd11) ? 4'd0 : rr_ptr + 4'd1;
                if (learn_cnt != 32'hFFFFFFFF)
                    learn_cnt <= learn_cnt + 32'd1;
            end
            if (win_close)
                win <= 1'b0;
            else if (win_open)
                win <= 1'b1;
if (age_tick)
tick_cnt <= tick_cnt + 4'd1;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && win && $rose(hit_q))
            assert (learn_cnt != 32'd0);
endmodule

module flow_hash_steer (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        pkt_valid,
    input  wire [7:0]  src,
    input  wire [7:0]  dst,
    input  wire [7:0]  port,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_addr,
    input  wire [7:0]  cfg_data,
    output reg  [7:0]  hash_q,
    output reg  [7:0]  q_sel,
    output reg         out_valid
);
    // 32-entry indirection table, 8-bit words, entry i at bits [8i+7:8i]
    reg [255:0] tbl_flat;
   // staged config write: captured this cycle, committed to the table next cycle
   reg        cfg_pv;
   reg [4:0]  cfg_pa;
   reg [7:0]  cfg_pd;
    initial tbl_flat = {8{8'd3, 8'd2, 8'd1, 8'd0}};
    initial hash_q = 8'd0;
    initial q_sel = 8'd0;
    initial out_valid = 1'b0;
   initial cfg_pv = 1'b0;
   initial cfg_pa = 5'd0;
   initial cfg_pd = 8'd0;

    // header hash
    wire [7:0] h = src ^ {dst[3:0], dst[7:4]} ^ {port[6:0], port[7]};
    wire [4:0] hidx = h[4:0];
    wire [255:0] sh = tbl_flat >> {hidx, 3'b000};
   // forward the pending (uncommitted) write so lookups see it immediately
   wire       fwd_hit = cfg_pv && (cfg_pa == hidx);
   wire [7:0] entry = fwd_hit ? cfg_pd : sh[7:0];

    integer i;
    always @(posedge clk) begin
        if (rst) begin
            tbl_flat  <= {8{8'd3, 8'd2, 8'd1, 8'd0}};
            hash_q    <= 8'd0;
            q_sel     <= 8'd0;
            out_valid <= 1'b0;
           cfg_pv    <= 1'b0;
           cfg_pa    <= 5'd0;
           cfg_pd    <= 8'd0;
        end else if (en) begin
            for (i = 0; i < 32; i = i + 1)
               if (cfg_pv && cfg_pa == i[4:0])
                   tbl_flat[i*8 +: 8] <= cfg_pd;
           cfg_pv <= cfg_we;
           if (cfg_we) begin
               cfg_pa <= cfg_addr;
               cfg_pd <= {6'd0, cfg_data[1:0]};
           end
            out_valid <= pkt_valid;
            if (pkt_valid) begin
                hash_q <= h;
                q_sel  <= entry;
            end
        end
    end

    always @(posedge clk)
        if (out_valid) assert (q_sel < 8'd4);
endmodule

module toast_spi_cs_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         push,
    input  wire [4:0]   push_slv,
    input  wire [127:0] push_data,
    input  wire [7:0]   cfg_setup,
    input  wire [7:0]   cfg_hold,
    input  wire [7:0]   cfg_gap,
    output wire [23:0]  cs_n,
    output wire         mosi,
    output wire         busy,
    output wire         full
);
    localparam [2:0] ST_IDLE  = 3'd0;
    localparam [2:0] ST_SETUP = 3'd1;
    localparam [2:0] ST_XFER  = 3'd2;
    localparam [2:0] ST_HOLD  = 3'd3;
    localparam [2:0] ST_GAP   = 3'd4;

    reg [2:0]   st     = ST_IDLE;
    reg [4:0]   sel    = 5'd0;
    reg [7:0]   dly    = 8'd0;
    reg [6:0]   bitcnt = 7'd0;
    reg [23:0]  cs_vec = 24'd0;
    reg [127:0] shreg  = 128'd0;

    reg [4:0]   q_slv [0:23];
    reg [127:0] q_dat [0:23];
    reg [4:0]   wptr  = 5'd0;
    reg [4:0]   rptr  = 5'd0;
    reg [4:0]   count = 5'd0;
   reg [4:0]   cs_on_cnt  = 5'd0;
   reg [4:0]   cs_off_cnt = 5'd0;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) begin
            q_slv[i] = 5'd0;
            q_dat[i] = 128'd0;
        end
    end

    wire [4:0]   head_raw = q_slv[rptr];
    wire [4:0]   head_slv = (head_raw < 5'd24) ? head_raw : 5'd0;
    wire [127:0] head_dat = q_dat[rptr];

    wire can_pop = (count != 5'd0) &&
                   ((st == ST_IDLE) || ((st == ST_GAP) && (dly == 8'd0)));
    wire do_push = push && (count < 5'd24);

    wire [4:0] wptr_nx = (wptr == 5'd23) ? 5'd0 : wptr + 5'd1;
    wire [4:0] rptr_nx = (rptr == 5'd23) ? 5'd0 : rptr + 5'd1;

    assign cs_n = ~cs_vec;
    assign mosi = shreg[127];
    assign busy = (st != ST_IDLE);
    assign full = (count == 5'd24);

    always @(posedge clk) begin
        if (rst) begin
            st     <= ST_IDLE;
            sel    <= 5'd0;
            dly    <= 8'd0;
            bitcnt <= 7'd0;
            cs_vec <= 24'd0;
            shreg  <= 128'd0;
            wptr   <= 5'd0;
            rptr   <= 5'd0;
            count  <= 5'd0;
           cs_on_cnt  <= 5'd0;
           cs_off_cnt <= 5'd0;
        end else if (en) begin
            if (do_push) begin
                q_slv[wptr] <= (push_slv < 5'd24) ? push_slv : 5'd0;
                q_dat[wptr] <= push_data;
                wptr <= wptr_nx;
            end
            if (can_pop)
                rptr <= rptr_nx;
            if (do_push && !can_pop)
                count <= count + 5'd1;
            else if (!do_push && can_pop)
                count <= count - 5'd1;

            case (st)
                ST_IDLE: begin
                    if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                       cs_on_cnt <= cs_on_cnt + 5'd1;
                    end
                end
                ST_SETUP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        bitcnt <= 7'd127;
                        st     <= ST_XFER;
                    end
                end
                ST_XFER: begin
                    shreg <= {shreg[126:0], 1'b0};
                    if (bitcnt != 7'd0)
                        bitcnt <= bitcnt - 7'd1;
                    else begin
                        dly <= cfg_hold;
                        st  <= ST_HOLD;
                    end
                end
                ST_HOLD: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                       if (cs_on_cnt != cs_off_cnt)
                           cs_vec <= cs_vec & ~(24'd1 << sel);
                       cs_off_cnt <= cs_off_cnt + 5'd1;
                        dly    <= cfg_gap;
                        st     <= ST_GAP;
                    end
                end
                ST_GAP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                       cs_on_cnt <= cs_on_cnt + 5'd1;
                    end else
                        st <= ST_IDLE;
                end
                default: st <= ST_IDLE;
            endcase
        end
    end

    // No two slave selects asserted at once while the sequencer is active
    always @(posedge clk)
        if (st != ST_IDLE)
            assert ((cs_vec & (cs_vec - 24'd1)) == 24'd0);
endmodule

module median_tick_filter (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        in_valid,
    input  wire [15:0] in_px,
    input  wire        sess_open,
    input  wire        sess_close,
    output wire [15:0] med_px,
    output wire        med_valid,
    output wire [15:0] fill_out
);
    // 8-entry sliding window of 16-bit price samples (packed)
    reg [127:0] win   = 128'd0;
    // thermometer occupancy mask: one bit per filled slot
    reg [7:0]   mask  = 8'h00;
    // occupancy counter, saturates at 8
    reg [15:0]  fill  = 16'd0;
    // trading-session window register (scope: open .. close)
    reg         armed = 1'b0;
   // standby book: second window/occupancy mask, sharing the sorter and the fill counter
   reg [127:0] win_b  = 128'd0;
   reg [7:0]   mask_b = 8'h00;
   // occupancy of whichever book is currently parked
   reg [15:0]  park   = 16'd0;
   // active book select: 0 = primary window, 1 = standby window
   reg         bank   = 1'b0;

    // odd-even transposition sorting network over 8 entries
    function [127:0] sort8;
        input [127:0] v;
        integer st, j;
        reg [127:0] t;
        reg [15:0] a, b;
        begin
            t = v;
            for (st = 0; st < 8; st = st + 1) begin
                for (j = (st % 2); j < 7; j = j + 2) begin
                    a = t[16*j +: 16];
                    b = t[16*(j+1) +: 16];
                    if (a > b) begin
                        t[16*j +: 16]     = b;
                        t[16*(j+1) +: 16] = a;
                    end
                end
            end
            sort8 = t;
        end
    endfunction

   wire [127:0] sorted   = sort8(bank ? win_b : win);
   wire         act_full = bank ? mask_b[7] : mask[7];
    assign med_px    = sorted[16*3 +: 16];
   assign med_valid = act_full;
    assign fill_out  = fill;

    always @(posedge clk) begin
        if (rst) begin
            win   <= 128'd0;
            mask  <= 8'h00;
            fill  <= 16'd0;
            armed <= 1'b0;
           win_b  <= 128'd0;
           mask_b <= 8'h00;
           park   <= 16'd0;
           bank   <= 1'b0;
        end else if (ce) begin
            if (sess_close) begin
                armed <= 1'b0;
                mask  <= 8'h00;
                fill  <= 16'd0;
               mask_b <= 8'h00;
               park   <= 16'd0;
               bank   <= 1'b0;
            end else begin
                if (sess_open)
                    armed <= 1'b1;
               if (sess_open && armed) begin
                   // re-open inside a live session rolls to the other book;
                   // the shared occupancy counter trades places with the parked count
                   // (a sample coincident with the roll is discarded)
                   bank <= ~bank;
                   fill <= park;
                   park <= fill;
               end else if (in_valid) begin
                   if (bank) begin
                       win_b  <= {win_b[111:0], in_px};
                       mask_b <= {mask_b[6:0], 1'b1};
                   end else begin
                       win  <= {win[111:0], in_px};
                       mask <= {mask[6:0], 1'b1};
                   end
                   if (!act_full)
                       fill <= fill + 16'd1;
               end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // inside a session, whenever the clock-enable burst ends, occupancy is at most 8
    always @(posedge clk)
        if (pv && armed && $fell(ce))
            assert (fill <= 16'd8);
endmodule

module nan_canon_log (
    input wire clk,
    input wire i_ce,
    input wire [15:0] i_a,
    input wire [15:0] i_b,
    input wire i_canon,
    input wire i_pop,
    output wire [15:0] o_result,
    output wire o_invalid,
    output wire [15:0] o_log_head,
    output wire [15:0] o_occ
);
    localparam [15:0] QNAN_CANON = 16'h7E00;
    localparam [15:0] QUIET_BIT  = 16'h0200;

    // half-precision NaN classification
    wire a_nan  = (i_a[14:10] == 5'h1f) && (i_a[9:0] != 10'd0);
    wire b_nan  = (i_b[14:10] == 5'h1f) && (i_b[9:0] != 10'd0);
    wire a_snan = a_nan && !i_a[9];
    wire b_snan = b_nan && !i_b[9];
    wire any_nan = a_nan | b_nan;

    // NaN selection / quieting / canonicalization
    reg [15:0] sel;
    always @(*) begin
        if (i_canon)     sel = QNAN_CANON;
        else if (a_snan) sel = i_a | QUIET_BIT;
        else if (b_snan) sel = i_b | QUIET_BIT;
        else if (a_nan)  sel = i_a;
        else             sel = i_b;
    end
    wire [15:0] nxt = any_nan ? sel : i_a;

    reg [15:0] r_result = 16'd0;
    reg        r_invalid = 1'b0;
    reg [3:0]  wptr = 4'd0;
    reg [3:0]  rptr = 4'd0;
    reg [15:0] occ  = 16'd0;
// occupancy accounting is retimed through a 4-deep event pipe so o_occ
// lines up with the downstream credit-return latency
reg [1:0]  occ_ev_s1 = 2'b00;
reg [1:0]  occ_ev_s2 = 2'b00;
reg [1:0]  occ_ev_s3 = 2'b00;
reg [1:0]  occ_ev_s4 = 2'b00;
    reg [15:0] log_mem [0:7];
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) log_mem[i] = 16'd0;
    end

    wire [3:0] fill  = wptr - rptr;
    wire full  = (fill == 4'd8);
    wire empty = (fill == 4'd0);
    wire push_ok = i_ce && any_nan && !full;
    wire pop_ok  = i_pop && !empty;

    always @(posedge clk) begin
        if (i_ce) begin
            r_result  <= nxt;
            r_invalid <= a_snan | b_snan;
        end
        if (push_ok) begin
            log_mem[wptr[2:0]] <= sel;
            wptr <= wptr + 4'd1;
        end
        if (pop_ok)
            rptr <= rptr + 4'd1;
occ_ev_s1 <= {push_ok, pop_ok};
occ_ev_s2 <= occ_ev_s1;
occ_ev_s3 <= occ_ev_s2;
occ_ev_s4 <= occ_ev_s3;
case (occ_ev_s4)
            2'b10: occ <= occ + 16'd1;
            2'b01: occ <= occ - 16'd1;
            default: ;
        endcase
    end

    assign o_result   = r_result;
    assign o_invalid  = r_invalid;
    assign o_log_head = log_mem[rptr[2:0]];
    assign o_occ      = occ;

    always @(posedge clk) assert (occ <= 16'd8);
endmodule

module qspi_xip_ctrl (
    input  wire        clk,
    input  wire        ce,
    input  wire        req,
    input  wire [23:0] addr,
    input  wire        cfg_we,
    input  wire [7:0]  cfg_wdata,
    input  wire [3:0]  io_in,
    output wire [3:0]  io_out,
    output wire        cs_n,
    output reg         busy,
    output reg         pf_valid,
    output reg  [31:0] pf_data
);
    reg        cs_active  = 1'b0;
    reg [31:0] cnt        = 32'd0;
    reg [31:0] nib        = 32'd0;
    reg [31:0] sh_out     = 32'd0;
    reg [7:0]  cfg_opcode = 8'hEB;
    reg        armed      = 1'b0;
   reg [31:0] rd_nibs    = 32'd8;

    initial busy     = 1'b0;
    initial pf_valid = 1'b0;
    initial pf_data  = 32'd0;

    assign cs_n   = !cs_active;
    assign io_out = sh_out[31:28];

    always @(posedge clk) begin
        if (ce) begin
            if (!busy) begin
                if (cfg_we)
                    cfg_opcode <= cfg_wdata;
                if (req) begin
                    armed     <= 1'b1;
                    busy      <= 1'b1;
                    cs_active <= 1'b1;
                   cnt       <= addr[1] ? 32'd16 : 32'd20;
                   rd_nibs   <= addr[1] ? 32'd4 : 32'd8;
                    nib       <= 32'd0;
                    pf_valid  <= 1'b0;
                    sh_out    <= {cfg_opcode, addr};
                end
            end else begin
                cnt    <= cnt - 32'd1;
                sh_out <= {sh_out[27:0], 4'h0};
               if (cnt <= rd_nibs) begin
                    pf_data <= {pf_data[27:0], io_in};
                   if (nib == rd_nibs - 32'd1) begin
                        pf_valid  <= 1'b1;
                        cs_active <= 1'b0;
                        nib       <= 32'd0;
                    end else begin
                        nib <= nib + 32'd1;
                    end
                end
                if (cnt == 32'd1)
                    busy <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (armed) assert (!(busy && pf_valid));

    always @(posedge clk)
        if (armed) assert (!(cs_active && !busy));
endmodule

module femto_trace_ser (
    input wire clk,
    input wire rst,
    input wire en,
    input wire arm,
    input wire start,
    input wire ack,
    input wire flush,
    input wire [31:0] data_in,
    output wire sout
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, SHIFT = 2'd2, DONE = 2'd3;

    reg [1:0]  phase;
    reg [31:0] load_reg;
    reg [31:0] shift_reg;
    reg [31:0] bit_cnt;
    reg armed_f, started_f, finished_f;
    reg win;
reg xfer_pend;
reg [31:0] xfer_data;

    initial begin
        phase = IDLE;
        load_reg = 32'd0;
        shift_reg = 32'd0;
        bit_cnt = 32'd0;
        armed_f = 1'b0;
        started_f = 1'b0;
        finished_f = 1'b0;
        win = 1'b0;
xfer_pend = 1'b0;
xfer_data = 32'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            load_reg <= 32'd0;
            shift_reg <= 32'd0;
            bit_cnt <= 32'd0;
            armed_f <= 1'b0;
            started_f <= 1'b0;
            finished_f <= 1'b0;
            win <= 1'b0;
xfer_pend <= 1'b0;
xfer_data <= 32'd0;
        end else if (en) begin
            if (flush) begin
                win <= 1'b0;
xfer_pend <= 1'b0;
                armed_f <= 1'b0;
                started_f <= 1'b0;
                finished_f <= 1'b0;
                phase <= IDLE;
end else if (xfer_pend) begin
shift_reg <= xfer_data;
bit_cnt <= 32'd0;
started_f <= 1'b1;
phase <= SHIFT;
xfer_pend <= 1'b0;
end else begin
                case (phase)
                    IDLE: begin
                        if (arm) begin
                            load_reg <= data_in;
                            armed_f <= 1'b1;
                            phase <= ARMED;
                            win <= 1'b1;
                        end
                    end
                    ARMED: begin
                        if (start) begin
xfer_data <= load_reg;
xfer_pend <= 1'b1;
                        end
                    end
                    SHIFT: begin
                        shift_reg <= {shift_reg[30:0], 1'b0};
                        bit_cnt <= bit_cnt + 32'd1;
                        if (bit_cnt == 32'd31) begin
                            finished_f <= 1'b1;
                            phase <= DONE;
                        end
                    end
                    DONE: begin
                        if (ack) begin
                            armed_f <= 1'b0;
                            started_f <= 1'b0;
                            finished_f <= 1'b0;
                            phase <= IDLE;
                        end
                    end
                endcase
            end
        end
    end

    assign sout = shift_reg[31];

    always @(posedge clk)
        if (win && finished_f)
            assert (started_f);

    always @(posedge clk)
        if (win && started_f)
            assert (armed_f);
endmodule

module irq_pulse_stretch (
    input  wire clk,
    input  wire ce,
    input  wire irq_pulse,
    input  wire win_open,
    input  wire win_close,
    output reg  irq_out
);
    localparam [63:0] LEN = 64'd12;
localparam [63:0] TAIL = 64'd4;

    reg [63:0] remain = 64'd0;
    reg [63:0] held   = 64'd0;
reg [63:0] tail   = 64'd0;
    reg        win    = 1'b0;
    initial irq_out = 1'b0;

    always @(posedge clk) begin
        if (ce) begin
            if (win_close)     win <= 1'b0;
            else if (win_open) win <= 1'b1;

            if (!irq_out) begin
                if (irq_pulse) begin
                    irq_out <= 1'b1;
remain  <= LEN - TAIL - 64'd1;
tail    <= TAIL;
                    held    <= 64'd1;
                end
end else if (remain == 64'd0 && tail != 64'd0) begin
remain <= tail - 64'd1;
tail   <= 64'd0;
held   <= held + 64'd1;
end else if (remain == 64'd0) begin
                irq_out <= 1'b0;
            end else begin
                remain <= remain - 64'd1;
                held   <= held + 64'd1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $fell(irq_out))
            assert (held <= LEN);
endmodule

module ras_walker (
    input wire clk,
    input wire rst,
    input wire en,
    input wire call,
    input wire ret,
    input wire [63:0] call_addr,
    output reg [63:0] ret_addr,
    output reg ret_valid
);
    reg [63:0] ras0, ras1;
    reg [1:0]  tos;
    reg        pend;
    reg [63:0] stg;
    reg [63:0] cnt;
    reg        win;
    reg        pv;

    initial ras0 = 64'd0;
    initial ras1 = 64'd0;
    initial tos = 2'd0;
    initial pend = 1'b0;
    initial stg = 64'd0;
    initial cnt = 64'd0;
    initial win = 1'b0;
    initial ret_addr = 64'd0;
    initial ret_valid = 1'b0;
    initial pv = 1'b0;
   reg [63:0] pq0, pq1, pq2, pq3;
   wire pq_busy = (pq0 != 64'd0) || (pq1 != 64'd0) || (pq2 != 64'd0) || (pq3 != 64'd0);
   initial pq0 = 64'd0;
   initial pq1 = 64'd0;
   initial pq2 = 64'd0;
   initial pq3 = 64'd0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            ras0 <= 64'd0;
            ras1 <= 64'd0;
            tos <= 2'd0;
            pend <= 1'b0;
            stg <= 64'd0;
            cnt <= 64'd0;
            win <= 1'b0;
            ret_addr <= 64'd0;
            ret_valid <= 1'b0;
           pq0 <= 64'd0;
           pq1 <= 64'd0;
           pq2 <= 64'd0;
           pq3 <= 64'd0;
        end else if (en) begin
            ret_valid <= 1'b0;
           pq0 <= 64'd0;
           pq1 <= pq0;
           pq2 <= pq1;
           pq3 <= pq2;
            if (pend) begin
                if (stg == 64'd3) begin
                    ret_addr <= tos[0] ? ras1 : ras0;
                    ret_valid <= 1'b1;
                    pend <= 1'b0;
                    win <= 1'b0;
                    stg <= 64'd0;
                end else begin
                    stg <= stg + 64'd1;
                    cnt <= cnt - 64'd1;
                end
           end else if (pq3 != 64'd0) begin
               pend <= 1'b1;
               cnt <= pq3;
               win <= 1'b1;
           end else if (ret && tos != 2'd0 && !pq_busy) begin
                tos <= tos - 2'd1;
                stg <= 64'd0;
               pq0 <= 64'd4;
           end else if (call && tos < 2'd2 && !pq_busy) begin
                if (tos == 2'd0) ras0 <= call_addr;
                else ras1 <= call_addr;
                tos <= tos + 2'd1;
            end
        end
    end

    always @(posedge clk)
        if (pv && $past(en) && $past(win) && $past(pend))
            assert ($past(cnt) != 64'd0);
endmodule

module uart_nco (
    input wire i_clk,
    input wire i_rst,
    input wire i_en,
    input wire [7:0] i_fword,
    input wire i_start,
    input wire i_stop,
    output wire [7:0] o_sin,
    output wire [7:0] o_ticks,
    output wire o_win
);
    localparam [63:0] SIN_TAB = {8'd37, 8'd1, 8'd37, 8'd128, 8'd218, 8'd255, 8'd218, 8'd128};

    reg [7:0] phase = 8'd0;
    reg [7:0] tick_cnt = 8'd0;
    reg [2:0] last_idx = 3'd0;
    reg [7:0] sin_q = 8'd128;
   reg [7:0] phase_nx = 8'd0;
   reg       cmt_pend = 1'b0;
    reg       win = 1'b0;

    wire [8:0] sum = {1'b0, phase} + {1'b0, i_fword};
    wire [7:0] nphase = sum[7:0];
    wire       carry = sum[8];
    wire [2:0] nidx = nphase[7:5];
    wire [5:0] nbase = {nidx, 3'b000};
    wire [7:0] n_sin = SIN_TAB[nbase +: 8];
    wire [5:0] lbase = {last_idx, 3'b000};
    wire [7:0] sin_of_last = SIN_TAB[lbase +: 8];
   wire [2:0] s_idx = phase_nx[7:5];
   wire [5:0] sbase = {s_idx, 3'b000};
   wire [7:0] s_sin = SIN_TAB[sbase +: 8];

    always @(posedge i_clk) begin
        if (i_rst) begin
            phase <= 8'd0;
            tick_cnt <= 8'd0;
            last_idx <= 3'd0;
            sin_q <= 8'd128;
            win <= 1'b0;
           phase_nx <= 8'd0;
           cmt_pend <= 1'b0;
        end else if (i_en) begin
           sin_q <= s_sin;
           if (cmt_pend) begin
               phase <= phase_nx;
               last_idx <= s_idx;
               cmt_pend <= 1'b0;
           end else begin
               phase_nx <= nphase;
               if (carry)
                   tick_cnt <= tick_cnt + 8'd1;
               cmt_pend <= 1'b1;
           end
            if (i_start)
                win <= 1'b1;
            else if (i_stop)
                win <= 1'b0;
        end
    end

    assign o_sin = sin_q;
    assign o_ticks = tick_cnt;
    assign o_win = win;

    reg pv = 1'b0;
    always @(posedge i_clk) pv <= 1'b1;

    always @(posedge i_clk)
        if (pv && !$past(i_rst) && win && $stable(phase))
            assert ($stable(sin_q));
endmodule

module GF8MulCore (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [7:0] a_in,
    input wire [7:0] b_in,
    input wire [7:0] poly_in,
    input wire poly_we,
    output reg done,
    output wire [7:0] result
);
    reg [7:0] acc;
    reg [7:0] a_reg;
    reg [7:0] b_reg;
    reg [7:0] poly;
    reg [7:0] bitcnt;
    reg [7:0] deadline;
    reg busy;
    reg armed;
   reg [7:0] acc2;
   reg [7:0] a2_reg;
   reg [7:0] b2_reg;
   reg [7:0] bitcnt2;
   reg busy2;
   reg res_sel;

    initial begin
        acc = 8'd0;
        a_reg = 8'd0;
        b_reg = 8'd0;
        poly = 8'd0;
        bitcnt = 8'd0;
        deadline = 8'd0;
        busy = 1'b0;
        armed = 1'b0;
        done = 1'b0;
       acc2 = 8'd0;
       a2_reg = 8'd0;
       b2_reg = 8'd0;
       bitcnt2 = 8'd0;
       busy2 = 1'b0;
       res_sel = 1'b0;
    end

   assign result = res_sel ? acc2 : acc;

   // single shared xtime unit; the overflow lane has priority on it
   wire [7:0] xt_src = busy2 ? a2_reg : a_reg;

   wire [7:0] a_shl = {xt_src[6:0], 1'b0};
   wire [7:0] xtime = xt_src[7] ? (a_shl ^ poly) : a_shl;

    always @(posedge clk) begin
        if (rst) begin
            acc <= 8'd0;
            a_reg <= 8'd0;
            b_reg <= 8'd0;
            poly <= 8'd0;
            bitcnt <= 8'd0;
            deadline <= 8'd0;
            busy <= 1'b0;
            armed <= 1'b0;
            done <= 1'b0;
           acc2 <= 8'd0;
           a2_reg <= 8'd0;
           b2_reg <= 8'd0;
           bitcnt2 <= 8'd0;
           busy2 <= 1'b0;
           res_sel <= 1'b0;
        end else if (en) begin
            done <= 1'b0;
            if (poly_we && !busy)
                poly <= poly_in;
            if (!busy) begin
                if (req) begin
                    busy <= 1'b1;
                    armed <= 1'b1;
                    acc <= 8'd0;
                    a_reg <= a_in;
                    b_reg <= b_in;
                    bitcnt <= 8'd8;
                    deadline <= 8'd9;
                end
           end else if (busy2) begin
               // lane A holds while lane B owns the shifter; ETA still counts down
               deadline <= deadline - 8'd1;
               if (bitcnt2 != 8'd0) begin
                   if (b2_reg[0])
                       acc2 <= acc2 ^ a2_reg;
                   a2_reg <= xtime;
                   b2_reg <= {1'b0, b2_reg[7:1]};
                   bitcnt2 <= bitcnt2 - 8'd1;
               end else begin
                   busy2 <= 1'b0;
                   res_sel <= 1'b1;
                   done <= 1'b1;
               end
           end else if (bitcnt != 8'd0) begin
                if (b_reg[0])
                    acc <= acc ^ a_reg;
                a_reg <= xtime;
                b_reg <= {1'b0, b_reg[7:1]};
                bitcnt <= bitcnt - 8'd1;
               if (req) begin
                   // overflow lane accepts the request and pushes lane A's ETA out
                   busy2 <= 1'b1;
                   acc2 <= 8'd0;
                   a2_reg <= a_in;
                   b2_reg <= b_in;
                   bitcnt2 <= 8'd8;
                   deadline <= deadline + 8'd8;
               end else begin
                   deadline <= deadline - 8'd1;
               end
            end else begin
                busy <= 1'b0;
                deadline <= 8'd0;
                done <= 1'b1;
               res_sel <= 1'b0;
            end
        end
    end

    assert property (!(armed && busy) || (deadline != 8'd0));
endmodule

module vrf_lanes (
    input  wire        clk,
    input  wire        ce,
    input  wire        lock,
    input  wire        unlock,
    input  wire        we,
    input  wire [6:0]  waddr,
    input  wire        wsel_alu,
    input  wire [63:0] wdata0,
    input  wire [63:0] wdata1,
    input  wire [6:0]  ra0,
    input  wire [6:0]  rb0,
    input  wire [6:0]  ra1,
    input  wire [6:0]  rb1,
    input  wire        cfg_we,
    input  wire [6:0]  cfg_addr,
    input  wire [1:0]  cfg_ew,
    output wire [63:0] out0,
    output wire [63:0] out1,
output wire [63:0] o_wr_count,
output reg [3:0] cfg_cnt
);
    reg [63:0] lane0_mem [0:127];
    reg [63:0] lane1_mem [0:127];
    reg [1:0]  ew_cfg    [0:127];
    reg [63:0] lane0_elems;
    reg [63:0] lane1_elems;
    reg [63:0] wr_count;
    reg        armed;
    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            lane0_mem[i] = 64'd0;
            lane1_mem[i] = 64'd0;
            ew_cfg[i]    = 2'd0;
        end
        lane0_elems = 64'd0;
        lane1_elems = 64'd0;
        wr_count    = 64'd0;
        armed       = 1'b0;
cfg_cnt = 4'd0;
    end

    wire [63:0] alu0 = lane0_mem[ra0] + lane0_mem[rb0];
    wire [63:0] alu1 = lane1_mem[ra1] + lane1_mem[rb1];
    wire [63:0] elems = 64'd1 << ew_cfg[waddr];

    always @(posedge clk) begin
        if (ce) begin
            if (we) begin
                lane0_mem[waddr] <= wsel_alu ? alu0 : wdata0;
                lane1_mem[waddr] <= wsel_alu ? alu1 : wdata1;
                lane0_elems <= lane0_elems + elems;
                lane1_elems <= lane1_elems + elems;
                wr_count    <= wr_count + 64'd1;
            end
            if (cfg_we)
                ew_cfg[cfg_addr] <= cfg_ew;
if (cfg_we)
cfg_cnt <= cfg_cnt + 4'd1;
            if (lock)
                armed <= 1'b1;
            else if (unlock)
                armed <= 1'b0;
        end
    end

    assign out0 = alu0;
    assign out1 = alu1;
    assign o_wr_count = wr_count;

    always @(*) assert (!armed || (lane0_elems == lane1_elems));
endmodule

module zz_reorder (
    input  wire        i_clk,
    input  wire        i_reset,
    input  wire        i_in_valid,
    input  wire [31:0] i_coef,
    input  wire        i_out_ready,
    output reg         o_valid,
    output reg  [31:0] o_coef,
    output wire        o_full,
    output wire        o_empty
);
    // two 64-entry banks = 128-entry block memory (ping-pong)
    reg [31:0] mem [0:127];
    reg [1:0]  bank_valid = 2'b00;
    reg        w_bank = 1'b0;
    reg        r_bank = 1'b0;
    reg [31:0] w_idx = 32'd0;
    reg [31:0] r_idx = 32'd0;
    reg [31:0] nfull = 32'd0;
   // block-completion mailbox: writer posts a finished bank, output stage absorbs it
   reg        cm_pend = 1'b0;
   reg        cm_bank = 1'b0;
    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) mem[i] = 32'd0;
        o_valid = 1'b0;
        o_coef  = 32'd0;
    end

    // zigzag index-sequence ROM: zigzag position -> raster position
    function [5:0] zz;
        input [5:0] k;
        case (k)
            6'd0: zz=6'd0;   6'd1: zz=6'd1;   6'd2: zz=6'd8;   6'd3: zz=6'd16;
            6'd4: zz=6'd9;   6'd5: zz=6'd2;   6'd6: zz=6'd3;   6'd7: zz=6'd10;
            6'd8: zz=6'd17;  6'd9: zz=6'd24;  6'd10: zz=6'd32; 6'd11: zz=6'd25;
            6'd12: zz=6'd18; 6'd13: zz=6'd11; 6'd14: zz=6'd4;  6'd15: zz=6'd5;
            6'd16: zz=6'd12; 6'd17: zz=6'd19; 6'd18: zz=6'd26; 6'd19: zz=6'd33;
            6'd20: zz=6'd40; 6'd21: zz=6'd48; 6'd22: zz=6'd41; 6'd23: zz=6'd34;
            6'd24: zz=6'd27; 6'd25: zz=6'd20; 6'd26: zz=6'd13; 6'd27: zz=6'd6;
            6'd28: zz=6'd7;  6'd29: zz=6'd14; 6'd30: zz=6'd21; 6'd31: zz=6'd28;
            6'd32: zz=6'd35; 6'd33: zz=6'd42; 6'd34: zz=6'd49; 6'd35: zz=6'd56;
            6'd36: zz=6'd57; 6'd37: zz=6'd50; 6'd38: zz=6'd43; 6'd39: zz=6'd36;
            6'd40: zz=6'd29; 6'd41: zz=6'd22; 6'd42: zz=6'd15; 6'd43: zz=6'd23;
            6'd44: zz=6'd30; 6'd45: zz=6'd37; 6'd46: zz=6'd44; 6'd47: zz=6'd51;
            6'd48: zz=6'd58; 6'd49: zz=6'd59; 6'd50: zz=6'd52; 6'd51: zz=6'd45;
            6'd52: zz=6'd38; 6'd53: zz=6'd31; 6'd54: zz=6'd39; 6'd55: zz=6'd46;
            6'd56: zz=6'd53; 6'd57: zz=6'd60; 6'd58: zz=6'd61; 6'd59: zz=6'd54;
            6'd60: zz=6'd47; 6'd61: zz=6'd55; 6'd62: zz=6'd62; default: zz=6'd63;
        endcase
    endfunction

   wire wr_go   = i_in_valid && !bank_valid[w_bank] && !(cm_pend && (w_idx == 32'd63));
    wire rd_go   = i_out_ready && bank_valid[r_bank];
    wire wr_done = wr_go && (w_idx == 32'd63);
    wire rd_done = rd_go && (r_idx == 32'd63);
   // the output stage (enabled by i_out_ready) picks up a posted bank completion
   wire cm_ret  = cm_pend && i_out_ready;

    assign o_full  = (nfull == 32'd2);
    assign o_empty = !bank_valid[r_bank];

    // raster-order write into the current write bank
    always @(posedge i_clk)
        if (!i_reset && wr_go)
            mem[{w_bank, w_idx[5:0]}] <= i_coef;

    always @(posedge i_clk) begin
        if (i_reset) begin
            bank_valid <= 2'b00;
           cm_pend    <= 1'b0;
           cm_bank    <= 1'b0;
            w_bank     <= 1'b0;
            r_bank     <= 1'b0;
            w_idx      <= 32'd0;
            r_idx      <= 32'd0;
            nfull      <= 32'd0;
            o_valid    <= 1'b0;
        end else begin
            if (wr_go)   w_idx  <= wr_done ? 32'd0 : w_idx + 32'd1;
            if (wr_done) w_bank <= ~w_bank;
            if (rd_go)   r_idx  <= rd_done ? 32'd0 : r_idx + 32'd1;
            if (rd_done) r_bank <= ~r_bank;
           // output stage owns bank_valid; it publishes the posted bank on its next enabled cycle
           if (wr_done) begin
               cm_pend <= 1'b1;
               cm_bank <= w_bank;
           end else if (cm_ret) begin
               cm_pend <= 1'b0;
           end
           if (cm_ret)  bank_valid[cm_bank] <= 1'b1;
            if (rd_done) bank_valid[r_bank] <= 1'b0;
            case ({wr_done, rd_done})
                2'b10:   nfull <= nfull + 32'd1;
                2'b01:   nfull <= nfull - 32'd1;
                default: nfull <= nfull;
            endcase
            // zigzag-order read from the current read bank
            if (i_out_ready) begin
                o_valid <= bank_valid[r_bank];
                if (rd_go)
                    o_coef <= mem[{r_bank, zz(r_idx[5:0])}];
            end
        end
    end

    // absence: the buffer is never full and empty at the same time
    always @(posedge i_clk)
        if (o_full)
            assert (!o_empty);
endmodule

module atalanta_ca_retry (
    input wire clk,
    input wire rst,
    input wire en,
    input wire cmd_valid,
    input wire [63:0] cmd_addr,
    input wire alert_n,
    output reg [63:0] ca_out,
    output reg ca_par
);
    reg [63:0] hist [0:31];
    reg hist_par [0:31];
    reg [4:0] wr_ptr;
    reg [4:0] replay_ptr;
    reg replaying;
    reg [63:0] issue_cnt;
    reg [63:0] log_cnt;
    reg [63:0] err_status;
    reg no_alert_yet;
reg lg_v1;
reg lg_v2;
reg lg_v3;
reg lg_v4;
reg [63:0] lg_addr1;
reg [63:0] lg_addr2;
reg [63:0] lg_addr3;
reg [63:0] lg_addr4;
reg lg_par1;
reg lg_par2;
reg lg_par3;
reg lg_par4;

    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1) begin
            hist[i] = 64'd0;
            hist_par[i] = 1'b0;
        end
        wr_ptr = 5'd0;
        replay_ptr = 5'd0;
        replaying = 1'b0;
        issue_cnt = 64'd0;
        log_cnt = 64'd0;
        err_status = 64'd0;
        no_alert_yet = 1'b1;
lg_v1 = 1'b0;
lg_v2 = 1'b0;
lg_v3 = 1'b0;
lg_v4 = 1'b0;
lg_addr1 = 64'd0;
lg_addr2 = 64'd0;
lg_addr3 = 64'd0;
lg_addr4 = 64'd0;
lg_par1 = 1'b0;
lg_par2 = 1'b0;
lg_par3 = 1'b0;
lg_par4 = 1'b0;
        ca_out = 64'd0;
        ca_par = 1'b0;
    end

    wire alert = !alert_n;
    wire do_issue = cmd_valid && !replaying;
    wire [4:0] replay_next = replay_ptr + 5'd1;
wire [63:0] log_pend = {63'd0, lg_v1} + {63'd0, lg_v2} + {63'd0, lg_v3} + {63'd0, lg_v4};

    wire [63:0] err_next;
assign err_next[0] = err_status[0] | (issue_cnt != log_cnt + log_pend);
    assign err_next[1] = err_status[1] | alert;
assign err_next[2] = err_status[2] | (lg_v4 && (lg_par4 != ^lg_addr4));
assign err_next[31:3] = err_status[31:3];
    assign err_next[63:32] = replaying ? (err_status[63:32] + 32'd1) : err_status[63:32];

    always @(posedge clk) begin
        if (rst) begin
            wr_ptr <= 5'd0;
            replay_ptr <= 5'd0;
            replaying <= 1'b0;
            issue_cnt <= 64'd0;
            log_cnt <= 64'd0;
            err_status <= 64'd0;
            no_alert_yet <= 1'b1;
lg_v1 <= 1'b0;
lg_v2 <= 1'b0;
lg_v3 <= 1'b0;
lg_v4 <= 1'b0;
lg_addr1 <= 64'd0;
lg_addr2 <= 64'd0;
lg_addr3 <= 64'd0;
lg_addr4 <= 64'd0;
lg_par1 <= 1'b0;
lg_par2 <= 1'b0;
lg_par3 <= 1'b0;
lg_par4 <= 1'b0;
            ca_out <= 64'd0;
            ca_par <= 1'b0;
        end else if (en) begin
            err_status <= err_next;
lg_v1 <= do_issue;
lg_v2 <= lg_v1;
lg_addr2 <= lg_addr1;
lg_par2 <= lg_par1;
lg_v3 <= lg_v2;
lg_addr3 <= lg_addr2;
lg_par3 <= lg_par2;
lg_v4 <= lg_v3;
lg_addr4 <= lg_addr3;
lg_par4 <= lg_par3;
            if (do_issue) begin
lg_addr1 <= cmd_addr;
lg_par1 <= ^cmd_addr;
                ca_out <= cmd_addr;
                ca_par <= ^cmd_addr;
                issue_cnt <= issue_cnt + 64'd1;
            end
if (lg_v4) begin
hist[wr_ptr] <= lg_addr4;
hist_par[wr_ptr] <= lg_par4;
wr_ptr <= wr_ptr + 5'd1;
log_cnt <= log_cnt + 64'd1;
end
            if (replaying) begin
                ca_out <= hist[replay_ptr];
                ca_par <= hist_par[replay_ptr];
                replay_ptr <= replay_next;
                if (replay_next == wr_ptr)
                    replaying <= 1'b0;
            end
            if (alert) begin
                replaying <= 1'b1;
                replay_ptr <= wr_ptr - 5'd1;
                no_alert_yet <= 1'b0;
            end
        end
    end

    always @(*) assert (!no_alert_yet || err_status == 64'd0);
endmodule

module rns_alu (
    input wire clk,
    input wire en,
    input wire [1:0] op,
    input wire [7:0] op_a,
    output wire [7:0] result,
    output wire rns_zero
);
    localparam OP_LOAD = 2'd0;
    localparam OP_ADD  = 2'd1;
    localparam OP_SUB  = 2'd2;
    localparam OP_MUL  = 2'd3;

    // residue registers, one per modulus channel (moduli 5 and 7)
    reg [2:0] r5;
    reg [2:0] r7;
    // binary mirror accumulator modulo 35 (= 5*7)
    reg [7:0] acc;
    // sticky scope register: set at the first LOAD
    reg armed;
   // registered zero flag: precomputed from the binary mirror next-state so
   // the rns_zero output comes straight from a flop
   reg zero_q;

    initial begin
        r5 = 3'd0;
        r7 = 3'd0;
        acc = 8'd0;
        armed = 1'b0;
       zero_q = 1'b1;
    end

    // operand residues
    wire [15:0] opw = {8'd0, op_a};
    wire [15:0] a5  = opw % 16'd5;
    wire [15:0] a7  = opw % 16'd7;
    wire [15:0] a35 = opw % 16'd35;

    wire [15:0] r5w  = {13'd0, r5};
    wire [15:0] r7w  = {13'd0, r7};
    wire [15:0] accw = {8'd0, acc};

    // channel 5
    wire [15:0] n5_add = (r5w + a5) % 16'd5;
    wire [15:0] n5_sub = (r5w + 16'd5 - a5) % 16'd5;
    wire [15:0] n5_mul = (r5w * a5) % 16'd5;
    // channel 7
    wire [15:0] n7_add = (r7w + a7) % 16'd7;
    wire [15:0] n7_sub = (r7w + 16'd7 - a7) % 16'd7;
    wire [15:0] n7_mul = (r7w * a7) % 16'd7;
    // binary mirror mod 35
    wire [15:0] nb_add = (accw + a35) % 16'd35;
    wire [15:0] nb_sub = (accw + 16'd35 - a35) % 16'd35;
    wire [15:0] nb_mul = (accw * a35) % 16'd35;

    always @(posedge clk) begin
        if (en) begin
            case (op)
                OP_LOAD: begin
                    r5 <= a5[2:0];
                    r7 <= a7[2:0];
                    acc <= a35[7:0];
                    armed <= 1'b1;
                   zero_q <= (a35 == 16'd0);
                end
                OP_ADD: begin
                    r5 <= n5_add[2:0];
                    r7 <= n7_add[2:0];
                    acc <= nb_add[7:0];
                   zero_q <= (nb_add == 16'd0);
                end
                OP_SUB: begin
                    r5 <= n5_sub[2:0];
                    r7 <= n7_sub[2:0];
                    acc <= nb_sub[7:0];
                   zero_q <= (nb_sub == 16'd0);
                end
                default: begin
                    r5 <= n5_mul[2:0];
                    r7 <= n7_mul[2:0];
                    acc <= nb_mul[7:0];
                   zero_q <= (nb_mul == 16'd0);
                end
            endcase
        end
    end

    assign result = acc;
   assign rns_zero = zero_q;

    // Absence after first LOAD: RNS zero flag and nonzero binary mirror never together
    assert property (!armed || !((r5 == 3'd0) && (r7 == 3'd0) && (acc != 8'd0)));

   // Registered zero flag agrees with the residue channels
   always @(posedge clk)
       assert (zero_q == ((r5 == 3'd0) && (r7 == 3'd0)));
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
    output reg          out_v
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                    cnt    <= cnt + 4'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);

   always @(posedge clk)
       if (win && en && cnt != 4'd0)
           assert (out_q[63:48] == {12'h0, cnt - 4'd1});
endmodule

module wormhole_route_unit #(
    parameter [63:0] MY_X = 64'd4,
    parameter [63:0] MY_Y = 64'd2
) (
    input  wire        clk,
    input  wire        in_valid,
    input  wire [1:0]  flit_type,
    input  wire [3:0]  in_ch,
    input  wire [63:0] dest_x,
    input  wire [63:0] dest_y,
    output reg  [2:0]  out_port,
    output wire        out_fire
);
    localparam [1:0] FT_BODY = 2'b00;
    localparam [1:0] FT_HEAD = 2'b01;
    localparam [1:0] FT_TAIL = 2'b10;
localparam [1:0] FT_CFG  = 2'b11;
localparam [63:0] DRAIN_DEFAULT = 64'd2;

    localparam [2:0] P_LOCAL = 3'd0;
    localparam [2:0] P_EAST  = 3'd1;
    localparam [2:0] P_WEST  = 3'd2;
    localparam [2:0] P_NORTH = 3'd3;
    localparam [2:0] P_SOUTH = 3'd4;

    reg [15:0] route_valid;
    reg [47:0] route_port;
    reg [63:0] head_cnt;
    reg [63:0] body_cnt;
reg [63:0] drain_lim;
reg [63:0] drain_left;
reg [3:0]  drain_ch;
    reg        head_seen;
    reg        armed;

    initial begin
drain_lim   = DRAIN_DEFAULT;
drain_left  = 64'd0;
drain_ch    = 4'd0;
        route_valid = 16'd0;
        route_port  = 48'd0;
        head_cnt    = 64'd0;
        body_cnt    = 64'd0;
        head_seen   = 1'b0;
        armed       = 1'b1;
        out_port    = 3'd0;
    end

    wire ch_busy = route_valid[in_ch];
    wire do_head = in_valid && (flit_type == FT_HEAD) && !ch_busy;
wire drain_hit = (in_ch == drain_ch) && (drain_left != 64'd0);
wire do_body = in_valid && (flit_type == FT_BODY) && (ch_busy || drain_hit);
    wire do_tail = in_valid && (flit_type == FT_TAIL) && ch_busy;

    assign out_fire = do_head || do_body || do_tail;

    reg [2:0] calc_port;
    always @(*) begin
        if (dest_x > MY_X)      calc_port = P_EAST;
        else if (dest_x < MY_X) calc_port = P_WEST;
        else if (dest_y > MY_Y) calc_port = P_NORTH;
        else if (dest_y < MY_Y) calc_port = P_SOUTH;
        else                    calc_port = P_LOCAL;
    end

    wire [2:0] stored_port = route_port[in_ch*3 +: 3];

    always @(posedge clk) begin
if (in_valid && (flit_type == FT_CFG))
    drain_lim <= dest_x;
        if (do_head) begin
if (in_ch == drain_ch)
    drain_left <= 64'd0;
            route_valid[in_ch]         <= 1'b1;
            route_port[in_ch*3 +: 3]   <= calc_port;
            head_cnt                   <= head_cnt + 64'd1;
            head_seen                  <= 1'b1;
            out_port                   <= calc_port;
        end
        if (do_body) begin
if (!ch_busy)
    drain_left <= drain_left - 64'd1;
            body_cnt <= body_cnt + 64'd1;
            out_port <= stored_port;
        end
        if (do_tail) begin
drain_ch   <= in_ch;
drain_left <= drain_lim;
            route_valid[in_ch] <= 1'b0;
            armed              <= 1'b0;
            out_port           <= stored_port;
        end
    end

    always @(*) assert (!armed || (body_cnt == 64'd0) || head_seen);
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
    output reg         fault
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

   // Quarantine controller: a denied access closes the checker for lk_len
   // cycles (fault held, every access denied); denials beyond esc_thr in the
   // fault bucket escalate to a permanent lockout. Grants drain the bucket.
   reg [3:0] lk_len  = 4'd4;
   reg [2:0] esc_thr = 3'd7;
   reg [3:0] lk_cnt  = 4'd0;
   reg [2:0] flt_cnt = 3'd0;
   reg       esc     = 1'b0;
   reg [3:0] lk_nxt;
   reg       esc_nxt;
   reg       blk;
   reg       blk_nxt;
   always @(*) begin
       if (miss_q)
           lk_nxt = lk_len;
       else if (lk_cnt != 4'd0)
           lk_nxt = lk_cnt - 4'd1;
       else
           lk_nxt = 4'd0;
       esc_nxt = esc || (miss_q && (flt_cnt == esc_thr));
       blk     = esc || (lk_cnt != 4'd0);
       blk_nxt = esc_nxt || (lk_nxt != 4'd0);
   end

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
           if (cfg_we && pre_lock && (cfg_idx == 5'd24)) begin
               lk_len  <= cfg_base[3:0];
               esc_thr <= cfg_limit[2:0];
           end
           lk_cnt <= lk_nxt;
           esc    <= esc_nxt;
           if (miss_q)
               flt_cnt <= flt_cnt + 3'd1;
           else if (hit_q && (flt_cnt != 3'd0))
               flt_cnt <= flt_cnt - 3'd1;
           hit_q  <= acc_valid && hit && !blk_nxt;
           miss_q <= acc_valid && (!hit || blk_nxt);
            grant  <= hit_q;
           fault  <= miss_q || blk;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
endmodule

module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
    output reg rest_ack
,
    output wire [7:0] ramp_cnt_o
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;

    reg [7:0] ramp_cnt;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
                    end
                end
                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
                        ramp_ack <= 1'b1;
                        state <= S_REST;
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
    assign ramp_cnt_o = ramp_cnt;
endmodule

module pg_pool (
    input wire clk,
    input wire rst,
    input wire [5:0] ce,
    input wire [5:0] req,
    output wire [7:0] pool_o,
    output wire [5:0] win_o,
    output wire [5:0] done_o
);
    localparam [7:0] TOTAL = 8'd3;

    reg [7:0] pool;
    initial pool = TOTAL;

    wire w0, w1, w2, w3, w4, w5;
    wire [2:0] st0, st1, st2, st3, st4, st5;
    wire sa0, sa1, sa2, sa3, sa4, sa5;
    wire ra0, ra1, ra2, ra3, ra4, ra5;
    wire rs0, rs1, rs2, rs3, rs4, rs5;
    wire [7:0] rc0, rc1, rc2, rc3, rc4, rc5;

    // idle instances asking to open a power-down window
    wire c0, c1, c2, c3, c4, c5;
    assign c0 = ce[0] && req[0] && (st0 == 3'd0);
    assign c1 = ce[1] && req[1] && (st1 == 3'd0);
    assign c2 = ce[2] && req[2] && (st2 == 3'd0);
    assign c3 = ce[3] && req[3] && (st3 == 3'd0);
    assign c4 = ce[4] && req[4] && (st4 == 3'd0);
    assign c5 = ce[5] && req[5] && (st5 == 3'd0);

    // fixed-priority arbiter, one grant per cycle while a credit is free
    wire avail;
    assign avail = (pool != 8'd0);
    wire g0, g1, g2, g3, g4, g5;
    assign g0 = avail && c0;
    assign g1 = avail && c1 && !c0;
    assign g2 = avail && c2 && !c0 && !c1;
    assign g3 = avail && c3 && !c0 && !c1 && !c2;
    assign g4 = avail && c4 && !c0 && !c1 && !c2 && !c3;
    assign g5 = avail && c5 && !c0 && !c1 && !c2 && !c3 && !c4;
    wire acq;
    assign acq = g0 | g1 | g2 | g3 | g4 | g5;

    // windows closing this cycle return their credit
    wire r0, r1, r2, r3, r4, r5;
    assign r0 = ce[0] && (st0 == 3'd4);
    assign r1 = ce[1] && (st1 == 3'd4);
    assign r2 = ce[2] && (st2 == 3'd4);
    assign r3 = ce[3] && (st3 == 3'd4);
    assign r4 = ce[4] && (st4 == 3'd4);
    assign r5 = ce[5] && (st5 == 3'd4);
    wire [7:0] rel_cnt;
    assign rel_cnt = {7'd0, r0} + {7'd0, r1} + {7'd0, r2} + {7'd0, r3} + {7'd0, r4} + {7'd0, r5};

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
        end else begin
            pool <= pool - {7'd0, acq} + rel_cnt;
        end
    end

    pg_seq u0 (.clk(clk), .rst(rst), .i_ce(ce[0]), .i_req(g0), .win(w0), .state(st0), .save_ack(sa0), .ramp_ack(ra0), .rest_ack(rs0), .ramp_cnt_o(rc0));
    pg_seq u1 (.clk(clk), .rst(rst), .i_ce(ce[1]), .i_req(g1), .win(w1), .state(st1), .save_ack(sa1), .ramp_ack(ra1), .rest_ack(rs1), .ramp_cnt_o(rc1));
    pg_seq u2 (.clk(clk), .rst(rst), .i_ce(ce[2]), .i_req(g2), .win(w2), .state(st2), .save_ack(sa2), .ramp_ack(ra2), .rest_ack(rs2), .ramp_cnt_o(rc2));
    pg_seq u3 (.clk(clk), .rst(rst), .i_ce(ce[3]), .i_req(g3), .win(w3), .state(st3), .save_ack(sa3), .ramp_ack(ra3), .rest_ack(rs3), .ramp_cnt_o(rc3));
    pg_seq u4 (.clk(clk), .rst(rst), .i_ce(ce[4]), .i_req(g4), .win(w4), .state(st4), .save_ack(sa4), .ramp_ack(ra4), .rest_ack(rs4), .ramp_cnt_o(rc4));
    pg_seq u5 (.clk(clk), .rst(rst), .i_ce(ce[5]), .i_req(g5), .win(w5), .state(st5), .save_ack(sa5), .ramp_ack(ra5), .rest_ack(rs5), .ramp_cnt_o(rc5));

    // the pool never holds more credits than it was provisioned with
    always @(posedge clk)
        assert (pool <= TOTAL);

    assign pool_o = pool;
    assign win_o = {w5, w4, w3, w2, w1, w0};
    assign done_o = {rs5, rs4, rs3, rs2, rs1, rs0};
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
,
    output wire armed_seen_o,
    output wire [1:0] fsm_o,
    output wire started_seen_o
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
    wire match1 = beat_valid && (((beat_data ^ wval1) & wmask1) == 128'h0);

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
            S_ARMED: if (match0)  fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
                if (fsm == S_ARMED && match0) started_seen <= 1'b1;
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
    assign armed_seen_o = armed_seen;
    assign fsm_o = fsm;
    assign started_seen_o = started_seen;
endmodule

module coyote_vfpga_bod (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire cmp_low,
    input wire clr,
    input wire sel_wr,
    input wire [1:0] sel_in,
    output wire slot_reset
,
    output wire bo_flag_o,
    output wire [15:0] deb_cnt_o,
    output wire [15:0] streak_o,
    output wire [15:0] thr_o
);
    reg [15:0] deb_cnt = 16'd0;
    reg [1:0]  thr_sel = 2'd0;
    reg        bo_flag = 1'b0;
    reg [15:0] streak  = 16'd0;
    reg        pv      = 1'b0;

    reg [15:0] thr;
    always @(*) begin
        case (thr_sel)
            2'd0: thr = 16'd4;
            2'd1: thr = 16'd16;
            2'd2: thr = 16'd256;
            default: thr = 16'd4096;
        endcase
    end

    wire [16:0] deb_inc    = {1'b0, deb_cnt} + 17'd1;
    wire [15:0] streak_inc = (streak == 16'hFFFF) ? 16'hFFFF : (streak + 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            deb_cnt <= 16'd0;
            thr_sel <= 2'd0;
            bo_flag <= 1'b0;
            streak  <= 16'd0;
        end else if (en) begin
            if (!cmp_low) begin
                deb_cnt <= 16'd0;
                streak  <= 16'd0;
            end else begin
                streak <= streak_inc;
                if (!bo_flag) begin
                    deb_cnt <= deb_inc[15:0];
                    if (deb_inc >= {1'b0, thr})
                        bo_flag <= 1'b1;
                end
            end
            if (clr) begin
                bo_flag <= 1'b0;
                deb_cnt <= 16'd0;
            end
            if (sel_wr && (deb_cnt == 16'd0))
                thr_sel <= sel_in;
        end
    end

    assign slot_reset = bo_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(bo_flag))
            assert (streak >= thr);
    assign bo_flag_o = bo_flag;
    assign deb_cnt_o = deb_cnt;
    assign streak_o = streak;
    assign thr_o = thr;
endmodule

module vbrk_bod_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en_a,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    input  wire         cap_en,
    input  wire         en_b,
    input  wire         bod_clr,
    input  wire         sel_wr,
    input  wire [1:0]   sel_in,
    output wire         done,
    output wire         slot_reset,
    output wire         brk_o,
    output wire [15:0]  qual_cnt_o
);
    wire        done_a;
    wire        armed_seen_a;
    wire        started_seen_a;
    wire [1:0]  fsm_a;
    wire        bo_flag_b;
    wire [15:0] deb_cnt_b;
    wire [15:0] streak_b;
    wire [15:0] thr_b;
    wire        slot_reset_b;

    reg        brk_q    = 1'b0;
    reg        q_ok     = 1'b0;
    reg [15:0] qual_cnt = 16'd0;

    vbrk_cmp u_cmp (
        .clk(clk),
        .rst(rst),
        .en(en_a),
        .beat_valid(beat_valid),
        .beat_data(beat_data),
        .wr_en(wr_en),
        .wr_sel(wr_sel),
        .wr_val(wr_val),
        .wr_mask(wr_mask),
        .arm_cmd(arm_cmd),
        .clr_cmd(clr_cmd),
        .done(done_a),
        .armed_seen_o(armed_seen_a),
        .fsm_o(fsm_a),
        .started_seen_o(started_seen_a)
    );

    coyote_vfpga_bod u_bod (
        .clk(clk),
        .rst_n(!rst),
        .en(en_b),
        .cmp_low(brk_q),
        .clr(bod_clr),
        .sel_wr(sel_wr),
        .sel_in(sel_in),
        .slot_reset(slot_reset_b),
        .bo_flag_o(bo_flag_b),
        .deb_cnt_o(deb_cnt_b),
        .streak_o(streak_b),
        .thr_o(thr_b)
    );

    wire brk_qualified = brk_q && q_ok;

    always @(posedge clk) begin
        if (rst) begin
            brk_q    <= 1'b0;
            q_ok     <= 1'b0;
            qual_cnt <= 16'd0;
        end else begin
            if (cap_en) begin
                brk_q <= done_a;
                q_ok  <= armed_seen_a && started_seen_a;
            end
            if (en_b) begin
                if (brk_qualified)
                    qual_cnt <= (qual_cnt == 16'hFFFF) ? 16'hFFFF : (qual_cnt + 16'd1);
                else
                    qual_cnt <= 16'd0;
            end
        end
    end

    always @(posedge clk)
        assert (qual_cnt >= deb_cnt_b);

    assign done       = done_a;
    assign slot_reset = slot_reset_b;
    assign brk_o      = brk_q;
    assign qual_cnt_o = qual_cnt;
endmodule

module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
    output reg rest_ack
,
    output wire [7:0] ramp_cnt_o
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;

    reg [7:0] ramp_cnt;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
                    end
                end
                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
                        ramp_ack <= 1'b1;
                        state <= S_REST;
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
    assign ramp_cnt_o = ramp_cnt;
endmodule

module pg_pool (
    input wire clk,
    input wire rst,
    input wire [5:0] ce,
    input wire [5:0] req,
    output wire [7:0] pool_o,
    output wire [5:0] win_o,
    output wire [5:0] done_o
,
    output wire [7:0] pool_obs,
    output wire ra0_o,
    output wire ra1_o,
    output wire ra2_o,
    output wire ra3_o,
    output wire ra4_o,
    output wire ra5_o,
    output wire [7:0] rc0_o,
    output wire [7:0] rc1_o,
    output wire [7:0] rc2_o,
    output wire [7:0] rc3_o,
    output wire [7:0] rc4_o,
    output wire [7:0] rc5_o,
    output wire rs0_o,
    output wire rs1_o,
    output wire rs2_o,
    output wire rs3_o,
    output wire rs4_o,
    output wire rs5_o,
    output wire sa0_o,
    output wire sa1_o,
    output wire sa2_o,
    output wire sa3_o,
    output wire sa4_o,
    output wire sa5_o,
    output wire [2:0] st0_o,
    output wire [2:0] st1_o,
    output wire [2:0] st2_o,
    output wire [2:0] st3_o,
    output wire [2:0] st4_o,
    output wire [2:0] st5_o,
    output wire w0_o,
    output wire w1_o,
    output wire w2_o,
    output wire w3_o,
    output wire w4_o,
    output wire w5_o
);
    localparam [7:0] TOTAL = 8'd3;

    reg [7:0] pool;
    initial pool = TOTAL;

    wire w0, w1, w2, w3, w4, w5;
    wire [2:0] st0, st1, st2, st3, st4, st5;
    wire sa0, sa1, sa2, sa3, sa4, sa5;
    wire ra0, ra1, ra2, ra3, ra4, ra5;
    wire rs0, rs1, rs2, rs3, rs4, rs5;
    wire [7:0] rc0, rc1, rc2, rc3, rc4, rc5;

    // idle instances asking to open a power-down window
    wire c0, c1, c2, c3, c4, c5;
    assign c0 = ce[0] && req[0] && (st0 == 3'd0);
    assign c1 = ce[1] && req[1] && (st1 == 3'd0);
    assign c2 = ce[2] && req[2] && (st2 == 3'd0);
    assign c3 = ce[3] && req[3] && (st3 == 3'd0);
    assign c4 = ce[4] && req[4] && (st4 == 3'd0);
    assign c5 = ce[5] && req[5] && (st5 == 3'd0);

    // fixed-priority arbiter, one grant per cycle while a credit is free
    wire avail;
    assign avail = (pool != 8'd0);
    wire g0, g1, g2, g3, g4, g5;
    assign g0 = avail && c0;
    assign g1 = avail && c1 && !c0;
    assign g2 = avail && c2 && !c0 && !c1;
    assign g3 = avail && c3 && !c0 && !c1 && !c2;
    assign g4 = avail && c4 && !c0 && !c1 && !c2 && !c3;
    assign g5 = avail && c5 && !c0 && !c1 && !c2 && !c3 && !c4;
    wire acq;
    assign acq = g0 | g1 | g2 | g3 | g4 | g5;

    // windows closing this cycle return their credit
    wire r0, r1, r2, r3, r4, r5;
    assign r0 = ce[0] && (st0 == 3'd4);
    assign r1 = ce[1] && (st1 == 3'd4);
    assign r2 = ce[2] && (st2 == 3'd4);
    assign r3 = ce[3] && (st3 == 3'd4);
    assign r4 = ce[4] && (st4 == 3'd4);
    assign r5 = ce[5] && (st5 == 3'd4);
    wire [7:0] rel_cnt;
    assign rel_cnt = {7'd0, r0} + {7'd0, r1} + {7'd0, r2} + {7'd0, r3} + {7'd0, r4} + {7'd0, r5};

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
        end else begin
            pool <= pool - {7'd0, acq} + rel_cnt;
        end
    end

    pg_seq u0 (.clk(clk), .rst(rst), .i_ce(ce[0]), .i_req(g0), .win(w0), .state(st0), .save_ack(sa0), .ramp_ack(ra0), .rest_ack(rs0), .ramp_cnt_o(rc0));
    pg_seq u1 (.clk(clk), .rst(rst), .i_ce(ce[1]), .i_req(g1), .win(w1), .state(st1), .save_ack(sa1), .ramp_ack(ra1), .rest_ack(rs1), .ramp_cnt_o(rc1));
    pg_seq u2 (.clk(clk), .rst(rst), .i_ce(ce[2]), .i_req(g2), .win(w2), .state(st2), .save_ack(sa2), .ramp_ack(ra2), .rest_ack(rs2), .ramp_cnt_o(rc2));
    pg_seq u3 (.clk(clk), .rst(rst), .i_ce(ce[3]), .i_req(g3), .win(w3), .state(st3), .save_ack(sa3), .ramp_ack(ra3), .rest_ack(rs3), .ramp_cnt_o(rc3));
    pg_seq u4 (.clk(clk), .rst(rst), .i_ce(ce[4]), .i_req(g4), .win(w4), .state(st4), .save_ack(sa4), .ramp_ack(ra4), .rest_ack(rs4), .ramp_cnt_o(rc4));
    pg_seq u5 (.clk(clk), .rst(rst), .i_ce(ce[5]), .i_req(g5), .win(w5), .state(st5), .save_ack(sa5), .ramp_ack(ra5), .rest_ack(rs5), .ramp_cnt_o(rc5));

    // the pool never holds more credits than it was provisioned with
    always @(posedge clk)
        assert (pool <= TOTAL);

    assign pool_o = pool;
    assign win_o = {w5, w4, w3, w2, w1, w0};
    assign done_o = {rs5, rs4, rs3, rs2, rs1, rs0};
    assign pool_obs = pool;
    assign ra0_o = ra0;
    assign ra1_o = ra1;
    assign ra2_o = ra2;
    assign ra3_o = ra3;
    assign ra4_o = ra4;
    assign ra5_o = ra5;
    assign rc0_o = rc0;
    assign rc1_o = rc1;
    assign rc2_o = rc2;
    assign rc3_o = rc3;
    assign rc4_o = rc4;
    assign rc5_o = rc5;
    assign rs0_o = rs0;
    assign rs1_o = rs1;
    assign rs2_o = rs2;
    assign rs3_o = rs3;
    assign rs4_o = rs4;
    assign rs5_o = rs5;
    assign sa0_o = sa0;
    assign sa1_o = sa1;
    assign sa2_o = sa2;
    assign sa3_o = sa3;
    assign sa4_o = sa4;
    assign sa5_o = sa5;
    assign st0_o = st0;
    assign st1_o = st1;
    assign st2_o = st2;
    assign st3_o = st3;
    assign st4_o = st4;
    assign st5_o = st5;
    assign w0_o = w0;
    assign w1_o = w1;
    assign w2_o = w2;
    assign w3_o = w3;
    assign w4_o = w4;
    assign w5_o = w5;
endmodule

module crc_residue_chk (
    input  wire clk,
    input  wire ce,
    input  wire start,
    input  wire din,
    output reg  done,
    output reg  err
,
    output wire [7:0] bitcnt_o,
    output wire busy_o,
    output wire [7:0] timer_o
);
    // bit-serial CRC-8 (poly x^8+x^2+x+1) residue checker:
    // 8 data bits followed by 8 appended CRC bits; residue must be zero
    reg [7:0] crc    = 8'h00;
    reg [7:0] bitcnt = 8'd0;   // bits consumed in current frame
    reg [7:0] timer  = 8'd0;   // completion watchdog countdown
    reg       busy   = 1'b0;   // frame outstanding
    reg       armed  = 1'b1;   // scope: no CRC error has ever been flagged
    initial done = 1'b0;
    initial err  = 1'b0;

    wire       fb       = crc[7] ^ din;
    wire [7:0] crc_next = {crc[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);
    wire       last     = busy && ce && (bitcnt == 8'd15);

    always @(posedge clk) begin
        if (!busy) begin
            if (start) begin
                busy   <= 1'b1;
                bitcnt <= 8'd0;
                timer  <= 8'd16;
                crc    <= 8'h00;
                done   <= 1'b0;
                err    <= 1'b0;
            end
        end else if (ce) begin
            crc    <= crc_next;
            bitcnt <= bitcnt + 8'd1;
            timer  <= timer - 8'd1;
            if (bitcnt == 8'd15) begin
                busy <= 1'b0;
                done <= 1'b1;
                err  <= (crc_next != 8'h00);
            end
        end
        if (last && (crc_next != 8'h00))
            armed <= 1'b0;
    end

    // before the first CRC error: the watchdog never expires while a frame is outstanding
    always @(*)
        assert (!armed || !busy || timer != 8'd0);
    assign bitcnt_o = bitcnt;
    assign busy_o = busy;
    assign timer_o = timer;
endmodule

module pg_crc_top (
    input  wire clk,
    input  wire rst,
    input  wire [5:0] ce,
    input  wire [5:0] req,
    input  wire b_ce,
    output wire [7:0] pool_o,
    output wire [5:0] win_o,
    output wire [5:0] done_o,
    output wire crc_done,
    output wire crc_err,
    output wire rpt_pend_o,
    output wire [7:0] rpt_mask_o,
    output wire [7:0] rpt_shift_o
);
    wire [7:0] pool;
    wire w0, w1, w2, w3, w4, w5;
    wire [2:0] st0, st1, st2, st3, st4, st5;
    wire sa0, sa1, sa2, sa3, sa4, sa5;
    wire ra0, ra1, ra2, ra3, ra4, ra5;
    wire rs0, rs1, rs2, rs3, rs4, rs5;
    wire [7:0] rc0, rc1, rc2, rc3, rc4, rc5;
    wire [7:0] bitcnt;
    wire [7:0] timer;
    wire busy;

    pg_pool u_pool (
        .clk(clk), .rst(rst), .ce(ce), .req(req),
        .pool_o(pool_o), .win_o(win_o), .done_o(done_o), .pool_obs(pool),
        .ra0_o(ra0), .ra1_o(ra1), .ra2_o(ra2), .ra3_o(ra3), .ra4_o(ra4), .ra5_o(ra5),
        .rc0_o(rc0), .rc1_o(rc1), .rc2_o(rc2), .rc3_o(rc3), .rc4_o(rc4), .rc5_o(rc5),
        .rs0_o(rs0), .rs1_o(rs1), .rs2_o(rs2), .rs3_o(rs3), .rs4_o(rs4), .rs5_o(rs5),
        .sa0_o(sa0), .sa1_o(sa1), .sa2_o(sa2), .sa3_o(sa3), .sa4_o(sa4), .sa5_o(sa5),
        .st0_o(st0), .st1_o(st1), .st2_o(st2), .st3_o(st3), .st4_o(st4), .st5_o(st5),
        .w0_o(w0), .w1_o(w1), .w2_o(w2), .w3_o(w3), .w4_o(w4), .w5_o(w5)
    );

    // power-down windows retiring this cycle
    wire [5:0] closing;
    assign closing = {ce[5] && (st5 == 3'd4), ce[4] && (st4 == 3'd4), ce[3] && (st3 == 3'd4),
                      ce[2] && (st2 == 3'd4), ce[1] && (st1 == 3'd4), ce[0] && (st0 == 3'd4)};

    // completion report buffer and serializer toward the CRC checker
    reg       pend;
    reg [7:0] snap;
    reg [7:0] frame;
    initial begin
        pend = 1'b0; snap = 8'd0; frame = 8'd0;
    end

    wire launch;
    assign launch = pend && !busy && !rst;
    wire shift_en;
    assign shift_en = busy && b_ce;

    always @(posedge clk) begin
        if (rst) begin
            pend  <= 1'b0;
            snap  <= 8'd0;
            frame <= 8'd0;
        end else begin
            if (launch) begin
                frame <= snap;
                pend  <= 1'b0;
            end else if (shift_en) begin
                frame <= {frame[6:0], 1'b0};
            end
            if (!pend && (closing != 6'd0)) begin
                pend <= 1'b1;
                snap <= {2'b00, closing};
            end
        end
    end

    wire din_b;
    assign din_b = frame[7];

    crc_residue_chk u_crc (
        .clk(clk), .ce(b_ce), .start(launch), .din(din_b),
        .done(crc_done), .err(crc_err),
        .bitcnt_o(bitcnt), .busy_o(busy), .timer_o(timer)
    );

    // the check-bit half of every report frame is all zeros on the wire
    always @(*)
        if (busy && bitcnt >= 8'd8)
            assert (!din_b);

    assign rpt_pend_o  = pend;
    assign rpt_mask_o  = snap;
    assign rpt_shift_o = frame;
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
,
    output wire armed_seen_o,
    output wire [1:0] fsm_o,
    output wire started_seen_o
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
    wire match1 = beat_valid && (((beat_data ^ wval1) & wmask1) == 128'h0);

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
            S_ARMED: if (match0)  fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
                if (fsm == S_ARMED && match0) started_seen <= 1'b1;
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
    assign armed_seen_o = armed_seen;
    assign fsm_o = fsm;
    assign started_seen_o = started_seen;
endmodule

module coyote_vfpga_bod (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire cmp_low,
    input wire clr,
    input wire sel_wr,
    input wire [1:0] sel_in,
    output wire slot_reset
,
    output wire bo_flag_o,
    output wire [15:0] deb_cnt_o,
    output wire [15:0] streak_o,
    output wire [15:0] thr_o
);
    reg [15:0] deb_cnt = 16'd0;
    reg [1:0]  thr_sel = 2'd0;
    reg        bo_flag = 1'b0;
    reg [15:0] streak  = 16'd0;
    reg        pv      = 1'b0;

    reg [15:0] thr;
    always @(*) begin
        case (thr_sel)
            2'd0: thr = 16'd4;
            2'd1: thr = 16'd16;
            2'd2: thr = 16'd256;
            default: thr = 16'd4096;
        endcase
    end

    wire [16:0] deb_inc    = {1'b0, deb_cnt} + 17'd1;
    wire [15:0] streak_inc = (streak == 16'hFFFF) ? 16'hFFFF : (streak + 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            deb_cnt <= 16'd0;
            thr_sel <= 2'd0;
            bo_flag <= 1'b0;
            streak  <= 16'd0;
        end else if (en) begin
            if (!cmp_low) begin
                deb_cnt <= 16'd0;
                streak  <= 16'd0;
            end else begin
                streak <= streak_inc;
                if (!bo_flag) begin
                    deb_cnt <= deb_inc[15:0];
                    if (deb_inc >= {1'b0, thr})
                        bo_flag <= 1'b1;
                end
            end
            if (clr) begin
                bo_flag <= 1'b0;
                deb_cnt <= 16'd0;
            end
            if (sel_wr && (deb_cnt == 16'd0))
                thr_sel <= sel_in;
        end
    end

    assign slot_reset = bo_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(bo_flag))
            assert (streak >= thr);
    assign bo_flag_o = bo_flag;
    assign deb_cnt_o = deb_cnt;
    assign streak_o = streak;
    assign thr_o = thr;
endmodule

module vbrk_bod_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en_a,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    input  wire         cap_en,
    input  wire         en_b,
    input  wire         bod_clr,
    input  wire         sel_wr,
    input  wire [1:0]   sel_in,
    output wire         done,
    output wire         slot_reset,
    output wire         brk_o,
    output wire [15:0]  qual_cnt_o
,
    output wire armed_seen_a_o,
    output wire bo_flag_b_o,
    output wire brk_q_o,
    output wire [15:0] deb_cnt_b_o,
    output wire done_a_o,
    output wire [1:0] fsm_a_o,
    output wire q_ok_o,
    output wire [15:0] qual_cnt_obs,
    output wire started_seen_a_o,
    output wire [15:0] streak_b_o,
    output wire [15:0] thr_b_o
);
    wire        done_a;
    wire        armed_seen_a;
    wire        started_seen_a;
    wire [1:0]  fsm_a;
    wire        bo_flag_b;
    wire [15:0] deb_cnt_b;
    wire [15:0] streak_b;
    wire [15:0] thr_b;
    wire        slot_reset_b;

    reg        brk_q    = 1'b0;
    reg        q_ok     = 1'b0;
    reg [15:0] qual_cnt = 16'd0;

    vbrk_cmp u_cmp (
        .clk(clk),
        .rst(rst),
        .en(en_a),
        .beat_valid(beat_valid),
        .beat_data(beat_data),
        .wr_en(wr_en),
        .wr_sel(wr_sel),
        .wr_val(wr_val),
        .wr_mask(wr_mask),
        .arm_cmd(arm_cmd),
        .clr_cmd(clr_cmd),
        .done(done_a),
        .armed_seen_o(armed_seen_a),
        .fsm_o(fsm_a),
        .started_seen_o(started_seen_a)
    );

    coyote_vfpga_bod u_bod (
        .clk(clk),
        .rst_n(!rst),
        .en(en_b),
        .cmp_low(brk_q),
        .clr(bod_clr),
        .sel_wr(sel_wr),
        .sel_in(sel_in),
        .slot_reset(slot_reset_b),
        .bo_flag_o(bo_flag_b),
        .deb_cnt_o(deb_cnt_b),
        .streak_o(streak_b),
        .thr_o(thr_b)
    );

    wire brk_qualified = brk_q && q_ok;

    always @(posedge clk) begin
        if (rst) begin
            brk_q    <= 1'b0;
            q_ok     <= 1'b0;
            qual_cnt <= 16'd0;
        end else begin
            if (cap_en) begin
                brk_q <= done_a;
                q_ok  <= armed_seen_a && started_seen_a;
            end
            if (en_b) begin
                if (brk_qualified)
                    qual_cnt <= (qual_cnt == 16'hFFFF) ? 16'hFFFF : (qual_cnt + 16'd1);
                else
                    qual_cnt <= 16'd0;
            end
        end
    end

    always @(posedge clk)
        assert (qual_cnt >= deb_cnt_b);

    assign done       = done_a;
    assign slot_reset = slot_reset_b;
    assign brk_o      = brk_q;
    assign qual_cnt_o = qual_cnt;
    assign armed_seen_a_o = armed_seen_a;
    assign bo_flag_b_o = bo_flag_b;
    assign brk_q_o = brk_q;
    assign deb_cnt_b_o = deb_cnt_b;
    assign done_a_o = done_a;
    assign fsm_a_o = fsm_a;
    assign q_ok_o = q_ok;
    assign qual_cnt_obs = qual_cnt;
    assign started_seen_a_o = started_seen_a;
    assign streak_b_o = streak_b;
    assign thr_b_o = thr_b;
endmodule

module GF8MulCore (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [7:0] a_in,
    input wire [7:0] b_in,
    input wire [7:0] poly_in,
    input wire poly_we,
    output reg done,
    output wire [7:0] result
,
    output wire [7:0] bitcnt_o,
    output wire busy_o,
    output wire [7:0] deadline_o
);
    reg [7:0] acc;
    reg [7:0] a_reg;
    reg [7:0] b_reg;
    reg [7:0] poly;
    reg [7:0] bitcnt;
    reg [7:0] deadline;
    reg busy;
    reg armed;

    initial begin
        acc = 8'd0;
        a_reg = 8'd0;
        b_reg = 8'd0;
        poly = 8'd0;
        bitcnt = 8'd0;
        deadline = 8'd0;
        busy = 1'b0;
        armed = 1'b0;
        done = 1'b0;
    end

    assign result = acc;

    wire [7:0] a_shl = {a_reg[6:0], 1'b0};
    wire [7:0] xtime = a_reg[7] ? (a_shl ^ poly) : a_shl;

    always @(posedge clk) begin
        if (rst) begin
            acc <= 8'd0;
            a_reg <= 8'd0;
            b_reg <= 8'd0;
            poly <= 8'd0;
            bitcnt <= 8'd0;
            deadline <= 8'd0;
            busy <= 1'b0;
            armed <= 1'b0;
            done <= 1'b0;
        end else if (en) begin
            done <= 1'b0;
            if (poly_we && !busy)
                poly <= poly_in;
            if (!busy) begin
                if (req) begin
                    busy <= 1'b1;
                    armed <= 1'b1;
                    acc <= 8'd0;
                    a_reg <= a_in;
                    b_reg <= b_in;
                    bitcnt <= 8'd8;
                    deadline <= 8'd9;
                end
            end else if (bitcnt != 8'd0) begin
                if (b_reg[0])
                    acc <= acc ^ a_reg;
                a_reg <= xtime;
                b_reg <= {1'b0, b_reg[7:1]};
                bitcnt <= bitcnt - 8'd1;
                deadline <= deadline - 8'd1;
            end else begin
                busy <= 1'b0;
                deadline <= 8'd0;
                done <= 1'b1;
            end
        end
    end

    assert property (!(armed && busy) || (deadline != 8'd0));
    assign bitcnt_o = bitcnt;
    assign busy_o = busy;
    assign deadline_o = deadline;
endmodule

module vbrk_gf8_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en_a,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    input  wire         cap_en,
    input  wire         en_b,
    input  wire         bod_clr,
    input  wire         sel_wr,
    input  wire [1:0]   sel_in,
    input  wire         job_cap,
    input  wire         en_m,
    input  wire [7:0]   poly_in,
    input  wire         poly_we,
    output wire         done,
    output wire         slot_reset,
    output wire         brk_o,
    output wire [15:0]  qual_cnt_o,
    output wire         gf_done,
    output wire [7:0]   gf_result,
    output wire         job_pend_o,
    output wire         job_inflight_o,
    output wire [7:0]   job_wd_o,
    output wire         gf_busy_o,
    output wire [7:0]   gf_deadline_o
);
    wire        a_done;
    wire        a_slot_reset;
    wire        a_brk;
    wire [15:0] a_qual_cnt_out;
    wire        a_armed_seen;
    wire        a_bo_flag;
    wire        a_brk_q;
    wire [15:0] a_deb_cnt;
    wire        a_done_mirror;
    wire [1:0]  a_fsm;
    wire        a_q_ok;
    wire [15:0] a_qual_cnt;
    wire        a_started_seen;
    wire [15:0] a_streak;
    wire [15:0] a_thr;

    wire        m_done;
    wire [7:0]  m_result;
    wire [7:0]  m_bitcnt;
    wire        m_busy;
    wire [7:0]  m_deadline;

    reg        job_pend     = 1'b0;
    reg [7:0]  job_a        = 8'd0;
    reg [7:0]  job_b        = 8'd0;
    reg        job_inflight = 1'b0;
    reg [7:0]  job_wd       = 8'd0;

    vbrk_bod_top u_a (
        .clk(clk),
        .rst(rst),
        .en_a(en_a),
        .beat_valid(beat_valid),
        .beat_data(beat_data),
        .wr_en(wr_en),
        .wr_sel(wr_sel),
        .wr_val(wr_val),
        .wr_mask(wr_mask),
        .arm_cmd(arm_cmd),
        .clr_cmd(clr_cmd),
        .cap_en(cap_en),
        .en_b(en_b),
        .bod_clr(bod_clr),
        .sel_wr(sel_wr),
        .sel_in(sel_in),
        .done(a_done),
        .slot_reset(a_slot_reset),
        .brk_o(a_brk),
        .qual_cnt_o(a_qual_cnt_out),
        .armed_seen_a_o(a_armed_seen),
        .bo_flag_b_o(a_bo_flag),
        .brk_q_o(a_brk_q),
        .deb_cnt_b_o(a_deb_cnt),
        .done_a_o(a_done_mirror),
        .fsm_a_o(a_fsm),
        .q_ok_o(a_q_ok),
        .qual_cnt_obs(a_qual_cnt),
        .started_seen_a_o(a_started_seen),
        .streak_b_o(a_streak),
        .thr_b_o(a_thr)
    );

    GF8MulCore u_m (
        .clk(clk),
        .rst(rst),
        .en(en_m),
        .req(job_pend),
        .a_in(job_a),
        .b_in(job_b),
        .poly_in(poly_in),
        .poly_we(poly_we),
        .done(m_done),
        .result(m_result),
        .bitcnt_o(m_bitcnt),
        .busy_o(m_busy),
        .deadline_o(m_deadline)
    );

    wire job_issue = en_m && job_pend && !m_busy;

    always @(posedge clk) begin
        if (rst) begin
            job_pend     <= 1'b0;
            job_a        <= 8'd0;
            job_b        <= 8'd0;
            job_inflight <= 1'b0;
            job_wd       <= 8'd0;
        end else begin
            if (!job_pend) begin
                if (job_cap && a_brk_q) begin
                    job_pend <= 1'b1;
                    job_a    <= a_qual_cnt[7:0];
                    job_b    <= a_deb_cnt[7:0];
                end
            end else if (job_issue) begin
                job_pend <= 1'b0;
            end
            if (en_m) begin
                if (job_issue) begin
                    job_inflight <= 1'b1;
                    job_wd       <= 8'd9;
                end else if (job_inflight) begin
                    if (m_bitcnt == 8'd0) begin
                        job_inflight <= 1'b0;
                        job_wd       <= 8'd0;
                    end else begin
                        job_wd <= job_wd - 8'd1;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        if (job_inflight)
            assert (job_wd != 8'd0);

    assign done           = a_done;
    assign slot_reset     = a_slot_reset;
    assign brk_o          = a_brk;
    assign qual_cnt_o     = a_qual_cnt_out;
    assign gf_done        = m_done;
    assign gf_result      = m_result;
    assign job_pend_o     = job_pend;
    assign job_inflight_o = job_inflight;
    assign job_wd_o       = job_wd;
    assign gf_busy_o      = m_busy;
    assign gf_deadline_o  = m_deadline;
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
    output reg          out_v
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
localparam [1:0] ROM_LAT  = 2'd3;
localparam [3:0] MAX_PASS = 4'd15;
reg [127:0] pf_word;
reg         pf_vld;
reg [1:0]   pf_wait;
reg [3:0]   pass_cnt;
reg         sweep_done;
wire [127:0] issue_word = {pf_word[127:80], 12'h0, pass_cnt, pf_word[63:0]};

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
pf_word    = 128'h0;
pf_vld     = 1'b0;
pf_wait    = 2'd0;
pass_cnt   = 4'd0;
sweep_done = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
pf_word    <= 128'h0;
pf_vld     <= 1'b0;
pf_wait    <= 2'd0;
pass_cnt   <= 4'd0;
sweep_done <= 1'b0;
        end else if (en) begin
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
pf_vld     <= 1'b0;
pf_wait    <= 2'd0;
pass_cnt   <= 4'd0;
sweep_done <= 1'b0;
            end else if (stop) begin
                win <= 1'b0;
end else if (win && pf_vld) begin
out_q  <= issue_word;
                out_v <= 1'b1;
pf_vld <= 1'b0;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
if (pass_cnt == MAX_PASS) begin
win        <= 1'b0;
pass_cnt   <= 4'd0;
sweep_done <= 1'b1;
end else begin
pass_cnt <= pass_cnt + 4'd1;
end
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                    cnt    <= cnt + 4'd1;
                end
end else if (win) begin
if (pf_wait == ROM_LAT) begin
pf_word <= rom_word;
pf_vld  <= 1'b1;
pf_wait <= 2'd0;
end else begin
pf_wait <= pf_wait + 2'd1;
end
end else if (sweep_done) begin
out_v <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);

   always @(posedge clk)
       if (win && en && cnt != 4'd0)
           assert (out_q[63:48] == {12'h0, cnt - 4'd1});
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
    output reg         fault
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

   // Quarantine controller: a denied access closes the checker for lk_len
   // cycles (fault held, every access denied); denials beyond esc_thr in the
   // fault bucket escalate to a permanent lockout. Grants drain the bucket.
   reg [3:0] lk_len  = 4'd4;
   reg [2:0] esc_thr = 3'd7;
   reg [3:0] lk_cnt  = 4'd0;
   reg [2:0] flt_cnt = 3'd0;
   reg       esc     = 1'b0;
   reg [3:0] lk_nxt;
   reg       esc_nxt;
   reg       blk;
   reg       blk_nxt;
  // Write-protect quarantine: a denied write additionally closes the
  // checker for wlk_len cycles (the maximum window is used once write
  // denials arrive in a burst). Its countdown shares the decrementer with
  // the read quarantine and only advances once the read quarantine has
  // drained. Write denials fill their own bucket; overflow raises the same
  // permanent lockout as the read side.
  reg [3:0] wlk_len   = 4'd2;
  reg [2:0] wesc_thr  = 3'd3;
  reg [3:0] wlk_cnt   = 4'd0;
  reg [2:0] wflt_cnt  = 3'd0;
  reg [1:0] wburst    = 2'd0;
  reg       miss_wr_q = 1'b0;
  reg       hit_wr_q  = 1'b0;
  reg [3:0] wlk_nxt;
  reg       rd_miss;
  reg       rd_hit;
  reg       resc_hit;
  reg       wesc_hit;
   always @(*) begin
      rd_miss  = miss_q && !miss_wr_q;
      rd_hit   = hit_q && !hit_wr_q;
      if (rd_miss)
           lk_nxt = lk_len;
       else if (lk_cnt != 4'd0)
           lk_nxt = lk_cnt - 4'd1;
       else
           lk_nxt = 4'd0;
      if (miss_wr_q) begin
          if (wburst == 2'd3)
              wlk_nxt = 4'hF;
          else
              wlk_nxt = wlk_len;
      end else if ((wlk_cnt != 4'd0) && (lk_cnt == 4'd0))
          wlk_nxt = wlk_cnt - 4'd1;
      else
          wlk_nxt = wlk_cnt;
      resc_hit = rd_miss && (flt_cnt == esc_thr);
      wesc_hit = miss_wr_q && (wflt_cnt == wesc_thr);
      esc_nxt = esc || resc_hit || wesc_hit;
      blk     = esc || (lk_cnt != 4'd0) || (wlk_cnt != 4'd0);
      blk_nxt = esc_nxt || (lk_nxt != 4'd0) || (wlk_nxt != 4'd0);
   end

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
           if (cfg_we && pre_lock && (cfg_idx == 5'd24)) begin
               lk_len  <= cfg_base[3:0];
               esc_thr <= cfg_limit[2:0];
           end
          if (cfg_we && pre_lock && (cfg_idx == 5'd25)) begin
              wlk_len  <= cfg_base[3:0];
              wesc_thr <= cfg_limit[2:0];
          end
           lk_cnt <= lk_nxt;
          wlk_cnt <= wlk_nxt;
           esc    <= esc_nxt;
          if (rd_miss)
               flt_cnt <= flt_cnt + 3'd1;
          else if (rd_hit && (flt_cnt != 3'd0))
               flt_cnt <= flt_cnt - 3'd1;
          if (miss_wr_q)
              wflt_cnt <= wflt_cnt + 3'd1;
          else if (hit_wr_q && (wflt_cnt != 3'd0))
              wflt_cnt <= wflt_cnt - 3'd1;
          if (miss_wr_q) begin
              if (wburst != 2'd3)
                  wburst <= wburst + 2'd1;
          end else if (hit_q) begin
              wburst <= 2'd0;
          end
           hit_q  <= acc_valid && hit && !blk_nxt;
           miss_q <= acc_valid && (!hit || blk_nxt);
          hit_wr_q  <= acc_valid && acc_write && hit && !blk_nxt;
          miss_wr_q <= acc_valid && acc_write && (!hit || blk_nxt);
            grant  <= hit_q;
           fault  <= miss_q || blk;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
,
    output wire armed_seen_o,
    output wire [1:0] fsm_o,
    output wire started_seen_o
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
    wire match1 = beat_valid && (((beat_data ^ wval1) & wmask1) == 128'h0);

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
            S_ARMED: if (match0)  fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
                if (fsm == S_ARMED && match0) started_seen <= 1'b1;
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
    assign armed_seen_o = armed_seen;
    assign fsm_o = fsm;
    assign started_seen_o = started_seen;
endmodule

module coyote_vfpga_bod (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire cmp_low,
    input wire clr,
    input wire sel_wr,
    input wire [1:0] sel_in,
    output wire slot_reset
,
    output wire bo_flag_o,
    output wire [15:0] deb_cnt_o,
    output wire [15:0] streak_o,
    output wire [15:0] thr_o
);
    reg [15:0] deb_cnt = 16'd0;
    reg [1:0]  thr_sel = 2'd0;
    reg        bo_flag = 1'b0;
    reg [15:0] streak  = 16'd0;
    reg        pv      = 1'b0;

    reg [15:0] thr;
    always @(*) begin
        case (thr_sel)
            2'd0: thr = 16'd4;
            2'd1: thr = 16'd16;
            2'd2: thr = 16'd256;
            default: thr = 16'd4096;
        endcase
    end

    wire [16:0] deb_inc    = {1'b0, deb_cnt} + 17'd1;
    wire [15:0] streak_inc = (streak == 16'hFFFF) ? 16'hFFFF : (streak + 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            deb_cnt <= 16'd0;
            thr_sel <= 2'd0;
            bo_flag <= 1'b0;
            streak  <= 16'd0;
        end else if (en) begin
            if (!cmp_low) begin
                deb_cnt <= 16'd0;
                streak  <= 16'd0;
            end else begin
                streak <= streak_inc;
                if (!bo_flag) begin
                    deb_cnt <= deb_inc[15:0];
                    if (deb_inc >= {1'b0, thr})
                        bo_flag <= 1'b1;
                end
            end
            if (clr) begin
                bo_flag <= 1'b0;
                deb_cnt <= 16'd0;
            end
            if (sel_wr && (deb_cnt == 16'd0))
                thr_sel <= sel_in;
        end
    end

    assign slot_reset = bo_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(bo_flag))
            assert (streak >= thr);
    assign bo_flag_o = bo_flag;
    assign deb_cnt_o = deb_cnt;
    assign streak_o = streak;
    assign thr_o = thr;
endmodule

module vbrk_bod_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en_a,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    input  wire         cap_en,
    input  wire         en_b,
    input  wire         bod_clr,
    input  wire         sel_wr,
    input  wire [1:0]   sel_in,
    output wire         done,
    output wire         slot_reset,
    output wire         brk_o,
    output wire [15:0]  qual_cnt_o
,
    output wire armed_seen_a_o,
    output wire bo_flag_b_o,
    output wire brk_q_o,
    output wire [15:0] deb_cnt_b_o,
    output wire done_a_o,
    output wire [1:0] fsm_a_o,
    output wire q_ok_o,
    output wire [15:0] qual_cnt_obs,
    output wire started_seen_a_o,
    output wire [15:0] streak_b_o,
    output wire [15:0] thr_b_o
);
    wire        done_a;
    wire        armed_seen_a;
    wire        started_seen_a;
    wire [1:0]  fsm_a;
    wire        bo_flag_b;
    wire [15:0] deb_cnt_b;
    wire [15:0] streak_b;
    wire [15:0] thr_b;
    wire        slot_reset_b;

    reg        brk_q    = 1'b0;
    reg        q_ok     = 1'b0;
    reg [15:0] qual_cnt = 16'd0;

    vbrk_cmp u_cmp (
        .clk(clk),
        .rst(rst),
        .en(en_a),
        .beat_valid(beat_valid),
        .beat_data(beat_data),
        .wr_en(wr_en),
        .wr_sel(wr_sel),
        .wr_val(wr_val),
        .wr_mask(wr_mask),
        .arm_cmd(arm_cmd),
        .clr_cmd(clr_cmd),
        .done(done_a),
        .armed_seen_o(armed_seen_a),
        .fsm_o(fsm_a),
        .started_seen_o(started_seen_a)
    );

    coyote_vfpga_bod u_bod (
        .clk(clk),
        .rst_n(!rst),
        .en(en_b),
        .cmp_low(brk_q),
        .clr(bod_clr),
        .sel_wr(sel_wr),
        .sel_in(sel_in),
        .slot_reset(slot_reset_b),
        .bo_flag_o(bo_flag_b),
        .deb_cnt_o(deb_cnt_b),
        .streak_o(streak_b),
        .thr_o(thr_b)
    );

    wire brk_qualified = brk_q && q_ok;

    always @(posedge clk) begin
        if (rst) begin
            brk_q    <= 1'b0;
            q_ok     <= 1'b0;
            qual_cnt <= 16'd0;
        end else begin
            if (cap_en) begin
                brk_q <= done_a;
                q_ok  <= armed_seen_a && started_seen_a;
            end
            if (en_b) begin
                if (brk_qualified)
                    qual_cnt <= (qual_cnt == 16'hFFFF) ? 16'hFFFF : (qual_cnt + 16'd1);
                else
                    qual_cnt <= 16'd0;
            end
        end
    end

    always @(posedge clk)
        assert (qual_cnt >= deb_cnt_b);

    assign done       = done_a;
    assign slot_reset = slot_reset_b;
    assign brk_o      = brk_q;
    assign qual_cnt_o = qual_cnt;
    assign armed_seen_a_o = armed_seen_a;
    assign bo_flag_b_o = bo_flag_b;
    assign brk_q_o = brk_q;
    assign deb_cnt_b_o = deb_cnt_b;
    assign done_a_o = done_a;
    assign fsm_a_o = fsm_a;
    assign q_ok_o = q_ok;
    assign qual_cnt_obs = qual_cnt;
    assign started_seen_a_o = started_seen_a;
    assign streak_b_o = streak_b;
    assign thr_b_o = thr_b;
