module GF8MulCore (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [7:0] a_in,
    input wire [7:0] b_in,
    input wire [7:0] poly_in,
    input wire poly_we,
    output reg done,
    output wire [7:0] result
,
    output wire [7:0] bitcnt_o,
    output wire busy_o,
    output wire [7:0] deadline_o
);
    reg [7:0] acc;
    reg [7:0] a_reg;
    reg [7:0] b_reg;
    reg [7:0] poly;
    reg [7:0] bitcnt;
    reg [7:0] deadline;
    reg busy;
    reg armed;

    initial begin
        acc = 8'd0;
        a_reg = 8'd0;
        b_reg = 8'd0;
        poly = 8'd0;
        bitcnt = 8'd0;
        deadline = 8'd0;
        busy = 1'b0;
        armed = 1'b0;
        done = 1'b0;
    end

    assign result = acc;

    wire [7:0] a_shl = {a_reg[6:0], 1'b0};
    wire [7:0] xtime = a_reg[7] ? (a_shl ^ poly) : a_shl;

    always @(posedge clk) begin
        if (rst) begin
            acc <= 8'd0;
            a_reg <= 8'd0;
            b_reg <= 8'd0;
            poly <= 8'd0;
            bitcnt <= 8'd0;
            deadline <= 8'd0;
            busy <= 1'b0;
            armed <= 1'b0;
            done <= 1'b0;
        end else if (en) begin
            done <= 1'b0;
            if (poly_we && !busy)
                poly <= poly_in;
            if (!busy) begin
                if (req) begin
                    busy <= 1'b1;
                    armed <= 1'b1;
                    acc <= 8'd0;
                    a_reg <= a_in;
                    b_reg <= b_in;
                    bitcnt <= 8'd8;
                    deadline <= 8'd9;
                end
            end else if (bitcnt != 8'd0) begin
                if (b_reg[0])
                    acc <= acc ^ a_reg;
                a_reg <= xtime;
                b_reg <= {1'b0, b_reg[7:1]};
                bitcnt <= bitcnt - 8'd1;
                deadline <= deadline - 8'd1;
            end else begin
                busy <= 1'b0;
                deadline <= 8'd0;
                done <= 1'b1;
            end
        end
    end

    assert property (!(armed && busy) || (deadline != 8'd0));
    assign bitcnt_o = bitcnt;
    assign busy_o = busy;
    assign deadline_o = deadline;
endmodule

module vbrk_gf8_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en_a,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    input  wire         cap_en,
    input  wire         en_b,
    input  wire         bod_clr,
    input  wire         sel_wr,
    input  wire [1:0]   sel_in,
    input  wire         job_cap,
    input  wire         en_m,
    input  wire [7:0]   poly_in,
    input  wire         poly_we,
    output wire         done,
    output wire         slot_reset,
    output wire         brk_o,
    output wire [15:0]  qual_cnt_o,
    output wire         gf_done,
    output wire [7:0]   gf_result,
    output wire         job_pend_o,
    output wire         job_inflight_o,
    output wire [7:0]   job_wd_o,
    output wire         gf_busy_o,
output wire [7:0]   gf_deadline_o,
output wire [7:0]   job_iss_cnt_o,
output wire [7:0]   job_ret_cnt_o
);
    wire        a_done;
    wire        a_slot_reset;
    wire        a_brk;
    wire [15:0] a_qual_cnt_out;
    wire        a_armed_seen;
    wire        a_bo_flag;
    wire        a_brk_q;
    wire [15:0] a_deb_cnt;
    wire        a_done_mirror;
    wire [1:0]  a_fsm;
    wire        a_q_ok;
    wire [15:0] a_qual_cnt;
    wire        a_started_seen;
    wire [15:0] a_streak;
    wire [15:0] a_thr;

    wire        m_done;
    wire [7:0]  m_result;
    wire [7:0]  m_bitcnt;
    wire        m_busy;
    wire [7:0]  m_deadline;

    reg        job_pend     = 1'b0;
    reg [7:0]  job_a        = 8'd0;
    reg [7:0]  job_b        = 8'd0;
    reg        job_inflight = 1'b0;
    reg [7:0]  job_wd       = 8'd0;
reg [7:0]  job_iss_cnt  = 8'd0;
reg [7:0]  job_ret_cnt  = 8'd0;

    vbrk_bod_top u_a (
        .clk(clk),
        .rst(rst),
        .en_a(en_a),
        .beat_valid(beat_valid),
        .beat_data(beat_data),
        .wr_en(wr_en),
        .wr_sel(wr_sel),
        .wr_val(wr_val),
        .wr_mask(wr_mask),
        .arm_cmd(arm_cmd),
        .clr_cmd(clr_cmd),
        .cap_en(cap_en),
        .en_b(en_b),
        .bod_clr(bod_clr),
        .sel_wr(sel_wr),
        .sel_in(sel_in),
        .done(a_done),
        .slot_reset(a_slot_reset),
        .brk_o(a_brk),
        .qual_cnt_o(a_qual_cnt_out),
        .armed_seen_a_o(a_armed_seen),
        .bo_flag_b_o(a_bo_flag),
        .brk_q_o(a_brk_q),
        .deb_cnt_b_o(a_deb_cnt),
        .done_a_o(a_done_mirror),
        .fsm_a_o(a_fsm),
        .q_ok_o(a_q_ok),
        .qual_cnt_obs(a_qual_cnt),
        .started_seen_a_o(a_started_seen),
        .streak_b_o(a_streak),
        .thr_b_o(a_thr)
    );

    GF8MulCore u_m (
        .clk(clk),
        .rst(rst),
        .en(en_m),
        .req(job_pend),
        .a_in(job_a),
        .b_in(job_b),
        .poly_in(poly_in),
        .poly_we(poly_we),
        .done(m_done),
        .result(m_result),
        .bitcnt_o(m_bitcnt),
        .busy_o(m_busy),
        .deadline_o(m_deadline)
    );

    wire job_issue = en_m && job_pend && !m_busy;
wire job_drain  = (m_bitcnt == 8'd0) && (job_iss_cnt != job_ret_cnt);
wire job_retire = en_m && !job_issue && job_inflight && job_drain;

    always @(posedge clk) begin
        if (rst) begin
            job_pend     <= 1'b0;
            job_a        <= 8'd0;
            job_b        <= 8'd0;
            job_inflight <= 1'b0;
            job_wd       <= 8'd0;
job_iss_cnt  <= 8'd0;
job_ret_cnt  <= 8'd0;
        end else begin
            if (!job_pend) begin
                if (job_cap && a_brk_q) begin
                    job_pend <= 1'b1;
                    job_a    <= a_qual_cnt[7:0];
                    job_b    <= a_deb_cnt[7:0];
                end
            end else if (job_issue) begin
                job_pend <= 1'b0;
            end
            if (en_m) begin
if (job_issue)
job_iss_cnt <= job_iss_cnt + 8'd1;
if (job_retire)
job_ret_cnt <= job_ret_cnt + 8'd1;
                if (job_issue) begin
                    job_inflight <= 1'b1;
                    job_wd       <= 8'd9;
                end else if (job_inflight) begin
if (job_drain) begin
                        job_inflight <= 1'b0;
                        job_wd       <= 8'd0;
                    end else begin
                        job_wd <= job_wd - 8'd1;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        if (job_inflight)
            assert (job_wd != 8'd0);

    assign done           = a_done;
    assign slot_reset     = a_slot_reset;
    assign brk_o          = a_brk;
    assign qual_cnt_o     = a_qual_cnt_out;
    assign gf_done        = m_done;
    assign gf_result      = m_result;
    assign job_pend_o     = job_pend;
    assign job_inflight_o = job_inflight;
    assign job_wd_o       = job_wd;
    assign gf_busy_o      = m_busy;
    assign gf_deadline_o  = m_deadline;
assign job_iss_cnt_o  = job_iss_cnt;
assign job_ret_cnt_o  = job_ret_cnt;
endmodule

