module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
    output reg         fault
,
    output wire esc_o,
    output wire hit_q_o,
    output wire [3:0] lk_cnt_o,
    output wire miss_q_o,
    output wire [3:0] wlk_cnt_o
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

   // Quarantine controller: a denied access closes the checker for lk_len
   // cycles (fault held, every access denied); denials beyond esc_thr in the
   // fault bucket escalate to a permanent lockout. Grants drain the bucket.
   reg [3:0] lk_len  = 4'd4;
   reg [2:0] esc_thr = 3'd7;
   reg [3:0] lk_cnt  = 4'd0;
   reg [2:0] flt_cnt = 3'd0;
   reg       esc     = 1'b0;
   reg [3:0] lk_nxt;
   reg       esc_nxt;
   reg       blk;
   reg       blk_nxt;
  // Write-protect quarantine: a denied write additionally closes the
  // checker for wlk_len cycles (the maximum window is used once write
  // denials arrive in a burst). Its countdown shares the decrementer with
  // the read quarantine and only advances once the read quarantine has
  // drained. Write denials fill their own bucket; overflow raises the same
  // permanent lockout as the read side.
  reg [3:0] wlk_len   = 4'd2;
  reg [2:0] wesc_thr  = 3'd3;
  reg [3:0] wlk_cnt   = 4'd0;
  reg [2:0] wflt_cnt  = 3'd0;
  reg [1:0] wburst    = 2'd0;
  reg       miss_wr_q = 1'b0;
  reg       hit_wr_q  = 1'b0;
  reg [3:0] wlk_nxt;
  reg       rd_miss;
  reg       rd_hit;
  reg       resc_hit;
  reg       wesc_hit;
   always @(*) begin
      rd_miss  = miss_q && !miss_wr_q;
      rd_hit   = hit_q && !hit_wr_q;
      if (rd_miss)
           lk_nxt = lk_len;
       else if (lk_cnt != 4'd0)
           lk_nxt = lk_cnt - 4'd1;
       else
           lk_nxt = 4'd0;
      if (miss_wr_q) begin
          if (wburst == 2'd3)
              wlk_nxt = 4'hF;
          else
              wlk_nxt = wlk_len;
      end else if ((wlk_cnt != 4'd0) && (lk_cnt == 4'd0))
          wlk_nxt = wlk_cnt - 4'd1;
      else
          wlk_nxt = wlk_cnt;
      resc_hit = rd_miss && (flt_cnt == esc_thr);
      wesc_hit = miss_wr_q && (wflt_cnt == wesc_thr);
      esc_nxt = esc || resc_hit || wesc_hit;
      blk     = esc || (lk_cnt != 4'd0) || (wlk_cnt != 4'd0);
      blk_nxt = esc_nxt || (lk_nxt != 4'd0) || (wlk_nxt != 4'd0);
   end

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
           if (cfg_we && pre_lock && (cfg_idx == 5'd24)) begin
               lk_len  <= cfg_base[3:0];
               esc_thr <= cfg_limit[2:0];
           end
          if (cfg_we && pre_lock && (cfg_idx == 5'd25)) begin
              wlk_len  <= cfg_base[3:0];
              wesc_thr <= cfg_limit[2:0];
          end
           lk_cnt <= lk_nxt;
          wlk_cnt <= wlk_nxt;
           esc    <= esc_nxt;
          if (rd_miss)
               flt_cnt <= flt_cnt + 3'd1;
          else if (rd_hit && (flt_cnt != 3'd0))
               flt_cnt <= flt_cnt - 3'd1;
          if (miss_wr_q)
              wflt_cnt <= wflt_cnt + 3'd1;
          else if (hit_wr_q && (wflt_cnt != 3'd0))
              wflt_cnt <= wflt_cnt - 3'd1;
          if (miss_wr_q) begin
              if (wburst != 2'd3)
                  wburst <= wburst + 2'd1;
          end else if (hit_q) begin
              wburst <= 2'd0;
          end
           hit_q  <= acc_valid && hit && !blk_nxt;
           miss_q <= acc_valid && (!hit || blk_nxt);
          hit_wr_q  <= acc_valid && acc_write && hit && !blk_nxt;
          miss_wr_q <= acc_valid && acc_write && (!hit || blk_nxt);
            grant  <= hit_q;
           fault  <= miss_q || blk;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
    assign esc_o = esc;
    assign hit_q_o = hit_q;
    assign lk_cnt_o = lk_cnt;
    assign miss_q_o = miss_q;
    assign wlk_cnt_o = wlk_cnt;
endmodule

module mpu_credit_pool (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire [5:0]  acc_valid,
    input  wire [5:0]  acc_write,
    input  wire [15:0] acc_addr,
    output wire [5:0]  grant_o,
    output wire [5:0]  fault_o,
    output wire [3:0]  pool_o,
    output wire [5:0]  busy_o
);
    localparam [3:0] TOTAL = 4'd8;
    localparam [3:0] CAP   = 4'd4;

    reg [3:0] pool = 4'd8;
    reg [3:0] t0 = 4'd0;
    reg [3:0] t1 = 4'd0;
    reg [3:0] t2 = 4'd0;
    reg [3:0] t3 = 4'd0;
    reg [3:0] t4 = 4'd0;
    reg [3:0] t5 = 4'd0;

    wire gr0, gr1, gr2, gr3, gr4, gr5;
    wire fl0, fl1, fl2, fl3, fl4, fl5;
    wire es0, es1, es2, es3, es4, es5;
    wire hq0, hq1, hq2, hq3, hq4, hq5;
    wire mq0, mq1, mq2, mq3, mq4, mq5;
    wire [3:0] lk0, lk1, lk2, lk3, lk4, lk5;
    wire [3:0] wl0, wl1, wl2, wl3, wl4, wl5;

    mpu_region_checker u0 (.clk(clk), .i_ce(i_ce), .cfg_we(cfg_we), .cfg_idx(cfg_idx), .cfg_base(cfg_base), .cfg_limit(cfg_limit), .cfg_perm(cfg_perm), .lock_req(lock_req), .acc_valid(acc_valid[0]), .acc_write(acc_write[0]), .acc_addr(acc_addr), .grant(gr0), .fault(fl0), .esc_o(es0), .hit_q_o(hq0), .lk_cnt_o(lk0), .miss_q_o(mq0), .wlk_cnt_o(wl0));
    mpu_region_checker u1 (.clk(clk), .i_ce(i_ce), .cfg_we(cfg_we), .cfg_idx(cfg_idx), .cfg_base(cfg_base), .cfg_limit(cfg_limit), .cfg_perm(cfg_perm), .lock_req(lock_req), .acc_valid(acc_valid[1]), .acc_write(acc_write[1]), .acc_addr(acc_addr), .grant(gr1), .fault(fl1), .esc_o(es1), .hit_q_o(hq1), .lk_cnt_o(lk1), .miss_q_o(mq1), .wlk_cnt_o(wl1));
    mpu_region_checker u2 (.clk(clk), .i_ce(i_ce), .cfg_we(cfg_we), .cfg_idx(cfg_idx), .cfg_base(cfg_base), .cfg_limit(cfg_limit), .cfg_perm(cfg_perm), .lock_req(lock_req), .acc_valid(acc_valid[2]), .acc_write(acc_write[2]), .acc_addr(acc_addr), .grant(gr2), .fault(fl2), .esc_o(es2), .hit_q_o(hq2), .lk_cnt_o(lk2), .miss_q_o(mq2), .wlk_cnt_o(wl2));
    mpu_region_checker u3 (.clk(clk), .i_ce(i_ce), .cfg_we(cfg_we), .cfg_idx(cfg_idx), .cfg_base(cfg_base), .cfg_limit(cfg_limit), .cfg_perm(cfg_perm), .lock_req(lock_req), .acc_valid(acc_valid[3]), .acc_write(acc_write[3]), .acc_addr(acc_addr), .grant(gr3), .fault(fl3), .esc_o(es3), .hit_q_o(hq3), .lk_cnt_o(lk3), .miss_q_o(mq3), .wlk_cnt_o(wl3));
    mpu_region_checker u4 (.clk(clk), .i_ce(i_ce), .cfg_we(cfg_we), .cfg_idx(cfg_idx), .cfg_base(cfg_base), .cfg_limit(cfg_limit), .cfg_perm(cfg_perm), .lock_req(lock_req), .acc_valid(acc_valid[4]), .acc_write(acc_write[4]), .acc_addr(acc_addr), .grant(gr4), .fault(fl4), .esc_o(es4), .hit_q_o(hq4), .lk_cnt_o(lk4), .miss_q_o(mq4), .wlk_cnt_o(wl4));
    mpu_region_checker u5 (.clk(clk), .i_ce(i_ce), .cfg_we(cfg_we), .cfg_idx(cfg_idx), .cfg_base(cfg_base), .cfg_limit(cfg_limit), .cfg_perm(cfg_perm), .lock_req(lock_req), .acc_valid(acc_valid[5]), .acc_write(acc_write[5]), .acc_addr(acc_addr), .grant(gr5), .fault(fl5), .esc_o(es5), .hit_q_o(hq5), .lk_cnt_o(lk5), .miss_q_o(mq5), .wlk_cnt_o(wl5));

    // A checker with a freshly qualified hit asks for a credit (up to CAP held)
    wire rq0 = hq0 && (t0 < CAP);
    wire rq1 = hq1 && (t1 < CAP);
    wire rq2 = hq2 && (t2 < CAP);
    wire rq3 = hq3 && (t3 < CAP);
    wire rq4 = hq4 && (t4 < CAP);
    wire rq5 = hq5 && (t5 < CAP);

    // Fixed-priority single acquisition per cycle
    wire avail = (pool != 4'd0);
    wire a0 = avail && rq0;
    wire a1 = avail && rq1 && !rq0;
    wire a2 = avail && rq2 && !rq0 && !rq1;
    wire a3 = avail && rq3 && !rq0 && !rq1 && !rq2;
    wire a4 = avail && rq4 && !rq0 && !rq1 && !rq2 && !rq3;
    wire a5 = avail && rq5 && !rq0 && !rq1 && !rq2 && !rq3 && !rq4;
    wire acq_any = a0 || a1 || a2 || a3 || a4 || a5;

    // A denied access returns one held credit
    wire r0 = mq0 && (t0 != 4'd0);
    wire r1 = mq1 && (t1 != 4'd0);
    wire r2 = mq2 && (t2 != 4'd0);
    wire r3 = mq3 && (t3 != 4'd0);
    wire r4 = mq4 && (t4 != 4'd0);
    wire r5 = mq5 && (t5 != 4'd0);
    wire [3:0] rel_n = {3'b000, r0} + {3'b000, r1} + {3'b000, r2}
                     + {3'b000, r3} + {3'b000, r4} + {3'b000, r5};

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
            t0 <= 4'd0;
            t1 <= 4'd0;
            t2 <= 4'd0;
            t3 <= 4'd0;
            t4 <= 4'd0;
            t5 <= 4'd0;
        end else if (i_ce) begin
            pool <= pool + rel_n - {3'b000, acq_any};
            t0 <= t0 + {3'b000, a0} - {3'b000, r0};
            t1 <= t1 + {3'b000, a1} - {3'b000, r1};
            t2 <= t2 + {3'b000, a2} - {3'b000, r2};
            t3 <= t3 + {3'b000, a3} - {3'b000, r3};
            t4 <= t4 + {3'b000, a4} - {3'b000, r4};
            t5 <= t5 + {3'b000, a5} - {3'b000, r5};
        end
    end

    always @(posedge clk)
        assert (pool <= TOTAL);

    assign grant_o = {gr5, gr4, gr3, gr2, gr1, gr0};
    assign fault_o = {fl5, fl4, fl3, fl2, fl1, fl0};
    assign pool_o  = pool;
    assign busy_o  = {(t5 != 4'd0), (t4 != 4'd0), (t3 != 4'd0), (t2 != 4'd0), (t1 != 4'd0), (t0 != 4'd0)};
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
