        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
n_start   = 8'd0;
n_stop    = 8'd0;
n_words   = 16'd0;
en_cyc    = 16'd0;
win_len   = 8'd0;
max_win   = 8'd0;
