    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
n_start   <= 8'd0;
n_stop    <= 8'd0;
n_words   <= 16'd0;
en_cyc    <= 16'd0;
win_len   <= 8'd0;
max_win   <= 8'd0;
wrap_seen <= 1'b0;
half_beat <= 1'b0;
dbg_stat  <= 32'h0;
        end else if (en) begin
en_cyc <= en_cyc + 16'd1;
if (start && n_start != 8'hFF) n_start <= n_start + 8'd1;
if (stop && !start && n_stop != 8'hFF) n_stop <= n_stop + 8'd1;
if (!start && !stop && win) begin
    n_words <= n_words + 16'd1;
    if (rd_ptr == 3'd7) wrap_seen <= 1'b1;
    if (win_len != 8'hFF) win_len <= win_len + 8'd1;
end
if (start) win_len <= 8'd0;
if (win_len > max_win) max_win <= win_len;
dbg_stat <= {n_start[3:0], n_stop[3:0], max_win, n_words[11:0], wrap_seen, half_beat, en_cyc[1:0]};
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
half_beat <= 1'b0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
half_beat <= 1'b0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
if (half_beat) cnt <= cnt + 4'd2;
half_beat <= !half_beat;
                end
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
    assign cnt_o = cnt;
    assign half_beat_o = half_beat;
    assign rd_ptr_o = rd_ptr;
endmodule

module prbs_win_checker (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_bit,
    input  wire        i_arm,
    input  wire        i_disarm,
    output wire        o_sync,
    output wire [63:0] o_errs
,
    output wire [63:0] err_cnt_o,
    output wire [63:0] err_snap_o,
    output wire win_o,
    output wire [63:0] win_errs_o
);
    localparam [63:0] SYNC_LEN = 64'd8;
    localparam [63:0] LOSS_LEN = 64'd4;
    localparam [63:0] MAXV     = 64'hFFFFFFFFFFFFFFFF;

    reg [63:0] ref_sr;
    reg        sync;
    reg [63:0] match_run;
    reg [63:0] bad_run;
    reg [63:0] err_cnt;
    reg        win;
    reg [63:0] err_snap;
    reg [63:0] win_errs;

    initial ref_sr    = 64'h1;
    initial sync      = 1'b0;
    initial match_run = 64'd0;
    initial bad_run   = 64'd0;
    initial err_cnt   = 64'd0;
    initial win       = 1'b0;
    initial err_snap  = 64'd0;
    initial win_errs  = 64'd0;

    // PRBS x^64 + x^63 + x^61 + x^60 + 1 prediction
    wire        pred    = ref_sr[63] ^ ref_sr[62] ^ ref_sr[60] ^ ref_sr[59];
    wire        mism    = sync && (i_bit != pred);
    wire        cnt_inc = mism && (err_cnt != MAXV);
    wire [63:0] err_nxt = cnt_inc ? (err_cnt + 64'd1) : err_cnt;
    wire        lose    = mism && ((bad_run + 64'd1) >= LOSS_LEN);
    wire        open_w  = i_arm && sync && !lose && !i_disarm;
    wire        close_w = i_disarm || lose;

    always @(posedge clk) begin
        if (i_reset) begin
            ref_sr    <= 64'h1;
            sync      <= 1'b0;
            match_run <= 64'd0;
            bad_run   <= 64'd0;
            err_cnt   <= 64'd0;
            win       <= 1'b0;
            err_snap  <= 64'd0;
            win_errs  <= 64'd0;
        end else if (i_ce) begin
            err_cnt <= err_nxt;
            if (!sync) begin
                // self-synchronising: load incoming stream into reference
                ref_sr  <= {ref_sr[62:0], i_bit};
                bad_run <= 64'd0;
                if (i_bit == pred) begin
                    if ((match_run + 64'd1) >= SYNC_LEN) begin
                        sync      <= 1'b1;
                        match_run <= 64'd0;
                    end else begin
                        match_run <= match_run + 64'd1;
                    end
                end else begin
                    match_run <= 64'd0;
                end
            end else begin
                // locked: free-run the local reference
                ref_sr    <= {ref_sr[62:0], pred};
                match_run <= 64'd0;
                if (mism) begin
                    if (lose) begin
                        sync    <= 1'b0;
                        bad_run <= 64'd0;
                    end else begin
                        bad_run <= bad_run + 64'd1;
                    end
                end else begin
                    bad_run <= 64'd0;
                end
            end
            // measurement window: opened by arm while locked, closed by disarm or sync loss
            if (win) begin
                if (close_w) win <= 1'b0;
                if (cnt_inc) win_errs <= win_errs + 64'd1;
            end else if (open_w) begin
                win      <= 1'b1;
                err_snap <= err_nxt;
                win_errs <= 64'd0;
            end
        end
    end

    assign o_sync = sync;
    assign o_errs = err_cnt;

    // Precedence inside the window: a nonzero window tally requires the global
    // counter to have advanced past the snapshot recorded when the window opened.
    always @(*)
        if (win && (win_errs != 64'd0))
            assert (err_cnt != err_snap);

    // With no window errors, the global counter must still equal the snapshot.
    always @(*)
        if (win && (win_errs == 64'd0))
            assert (err_cnt == err_snap);
    assign err_cnt_o = err_cnt;
    assign err_snap_o = err_snap;
    assign win_o = win;
    assign win_errs_o = win_errs;
endmodule

module route_prbs_top (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    input  wire         ld,
    input  wire         step,
    input  wire         arm,
    input  wire         disarm,
    output wire [127:0] out_q,
    output wire         out_v,
    output wire [31:0]  dbg_stat,
    output wire         o_sync,
    output wire [63:0]  o_errs,
    output wire         win_o,
    output wire [8:0]   stg_o
);
    wire [3:0]  a_cnt;
    wire        a_half_beat;
    wire [2:0]  a_rd_ptr;
    wire [63:0] b_err_cnt;
    wire [63:0] b_err_snap;
    wire        b_win;
    wire [63:0] b_win_errs;

    xbar_route_rom u_a (
        .clk(clk), .rst_n(rst_n), .en(en), .start(start), .stop(stop),
        .out_q(out_q), .out_v(out_v), .dbg_stat(dbg_stat),
        .cnt_o(a_cnt), .half_beat_o(a_half_beat), .rd_ptr_o(a_rd_ptr)
    );

    // beat staging register: latches the route cursor, then sequences it locally
    reg       g_v;
    reg [2:0] g_ptr;
    reg [3:0] g_cnt;
    reg       g_hb;

    initial begin
        g_v   = 1'b0;
        g_ptr = 3'd0;
        g_cnt = 4'd0;
        g_hb  = 1'b0;
    end

    wire g_load = ld && out_v;
    wire g_adv  = step && g_v && !g_load;

    always @(posedge clk) begin
        if (!rst_n) begin
            g_v   <= 1'b0;
            g_ptr <= 3'd0;
            g_cnt <= 4'd0;
            g_hb  <= 1'b0;
        end else if (g_load) begin
            g_v   <= 1'b1;
            g_ptr <= a_rd_ptr;
            g_cnt <= a_cnt;
            g_hb  <= a_half_beat;
        end else if (g_adv) begin
            if (g_ptr == 3'd7) begin
                g_ptr <= 3'd0;
                g_cnt <= 4'd0;
                g_hb  <= 1'b0;
            end else begin
                g_ptr <= g_ptr + 3'd1;
                if (g_hb) g_cnt <= g_cnt + 4'd2;
                g_hb  <= !g_hb;
            end
        end
    end

    wire stg_bit = g_ptr[0] ^ g_ptr[1] ^ g_ptr[2] ^ g_cnt[1] ^ g_cnt[2] ^ g_hb;
    wire b_ce    = g_adv;
    wire b_rst   = !rst_n;

    prbs_win_checker u_b (
        .clk(clk), .i_reset(b_rst), .i_ce(b_ce), .i_bit(stg_bit),
        .i_arm(arm), .i_disarm(disarm),
        .o_sync(o_sync), .o_errs(o_errs),
        .err_cnt_o(b_err_cnt), .err_snap_o(b_err_snap),
        .win_o(b_win), .win_errs_o(b_win_errs)
    );

    assign win_o = b_win;
    assign stg_o = {g_v, g_ptr, g_cnt, g_hb};

    // a staged cursor must always name a beat within the eight-entry route table
    always @(*)
        if (g_v)
            assert (g_cnt <= 4'd7);
endmodule

module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
    output reg rest_ack
,
    output wire [7:0] ramp_cnt_o
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;

    reg [7:0] ramp_cnt;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
                    end
                end
                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
                        ramp_ack <= 1'b1;
                        state <= S_REST;
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
    assign ramp_cnt_o = ramp_cnt;
endmodule

module pg_pool (
    input wire clk,
    input wire rst,
    input wire [5:0] ce,
    input wire [5:0] req,
    output wire [7:0] pool_o,
    output wire [5:0] win_o,
    output wire [5:0] done_o
,
    output wire [7:0] pool_obs,
    output wire ra0_o,
    output wire ra1_o,
    output wire ra2_o,
    output wire ra3_o,
    output wire ra4_o,
    output wire ra5_o,
    output wire [7:0] rc0_o,
    output wire [7:0] rc1_o,
    output wire [7:0] rc2_o,
    output wire [7:0] rc3_o,
    output wire [7:0] rc4_o,
    output wire [7:0] rc5_o,
    output wire rs0_o,
    output wire rs1_o,
    output wire rs2_o,
    output wire rs3_o,
    output wire rs4_o,
    output wire rs5_o,
    output wire sa0_o,
    output wire sa1_o,
    output wire sa2_o,
    output wire sa3_o,
    output wire sa4_o,
    output wire sa5_o,
    output wire [2:0] st0_o,
    output wire [2:0] st1_o,
    output wire [2:0] st2_o,
    output wire [2:0] st3_o,
    output wire [2:0] st4_o,
    output wire [2:0] st5_o,
    output wire w0_o,
    output wire w1_o,
    output wire w2_o,
    output wire w3_o,
    output wire w4_o,
    output wire w5_o
);
    localparam [7:0] TOTAL = 8'd3;

    reg [7:0] pool;
    initial pool = TOTAL;

    wire w0, w1, w2, w3, w4, w5;
    wire [2:0] st0, st1, st2, st3, st4, st5;
    wire sa0, sa1, sa2, sa3, sa4, sa5;
    wire ra0, ra1, ra2, ra3, ra4, ra5;
    wire rs0, rs1, rs2, rs3, rs4, rs5;
    wire [7:0] rc0, rc1, rc2, rc3, rc4, rc5;

    // idle instances asking to open a power-down window
    wire c0, c1, c2, c3, c4, c5;
    assign c0 = ce[0] && req[0] && (st0 == 3'd0);
    assign c1 = ce[1] && req[1] && (st1 == 3'd0);
    assign c2 = ce[2] && req[2] && (st2 == 3'd0);
    assign c3 = ce[3] && req[3] && (st3 == 3'd0);
    assign c4 = ce[4] && req[4] && (st4 == 3'd0);
    assign c5 = ce[5] && req[5] && (st5 == 3'd0);

    // fixed-priority arbiter, one grant per cycle while a credit is free
    wire avail;
    assign avail = (pool != 8'd0);
    wire g0, g1, g2, g3, g4, g5;
    assign g0 = avail && c0;
    assign g1 = avail && c1 && !c0;
    assign g2 = avail && c2 && !c0 && !c1;
    assign g3 = avail && c3 && !c0 && !c1 && !c2;
    assign g4 = avail && c4 && !c0 && !c1 && !c2 && !c3;
    assign g5 = avail && c5 && !c0 && !c1 && !c2 && !c3 && !c4;
    wire acq;
    assign acq = g0 | g1 | g2 | g3 | g4 | g5;

    // windows closing this cycle return their credit
    wire r0, r1, r2, r3, r4, r5;
    assign r0 = ce[0] && (st0 == 3'd4);
    assign r1 = ce[1] && (st1 == 3'd4);
    assign r2 = ce[2] && (st2 == 3'd4);
    assign r3 = ce[3] && (st3 == 3'd4);
    assign r4 = ce[4] && (st4 == 3'd4);
    assign r5 = ce[5] && (st5 == 3'd4);
    wire [7:0] rel_cnt;
    assign rel_cnt = {7'd0, r0} + {7'd0, r1} + {7'd0, r2} + {7'd0, r3} + {7'd0, r4} + {7'd0, r5};

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
        end else begin
            pool <= pool - {7'd0, acq} + rel_cnt;
        end
    end

    pg_seq u0 (.clk(clk), .rst(rst), .i_ce(ce[0]), .i_req(g0), .win(w0), .state(st0), .save_ack(sa0), .ramp_ack(ra0), .rest_ack(rs0), .ramp_cnt_o(rc0));
    pg_seq u1 (.clk(clk), .rst(rst), .i_ce(ce[1]), .i_req(g1), .win(w1), .state(st1), .save_ack(sa1), .ramp_ack(ra1), .rest_ack(rs1), .ramp_cnt_o(rc1));
    pg_seq u2 (.clk(clk), .rst(rst), .i_ce(ce[2]), .i_req(g2), .win(w2), .state(st2), .save_ack(sa2), .ramp_ack(ra2), .rest_ack(rs2), .ramp_cnt_o(rc2));
    pg_seq u3 (.clk(clk), .rst(rst), .i_ce(ce[3]), .i_req(g3), .win(w3), .state(st3), .save_ack(sa3), .ramp_ack(ra3), .rest_ack(rs3), .ramp_cnt_o(rc3));
    pg_seq u4 (.clk(clk), .rst(rst), .i_ce(ce[4]), .i_req(g4), .win(w4), .state(st4), .save_ack(sa4), .ramp_ack(ra4), .rest_ack(rs4), .ramp_cnt_o(rc4));
    pg_seq u5 (.clk(clk), .rst(rst), .i_ce(ce[5]), .i_req(g5), .win(w5), .state(st5), .save_ack(sa5), .ramp_ack(ra5), .rest_ack(rs5), .ramp_cnt_o(rc5));

    // the pool never holds more credits than it was provisioned with
    always @(posedge clk)
        assert (pool <= TOTAL);

    assign pool_o = pool;
    assign win_o = {w5, w4, w3, w2, w1, w0};
    assign done_o = {rs5, rs4, rs3, rs2, rs1, rs0};
    assign pool_obs = pool;
    assign ra0_o = ra0;
    assign ra1_o = ra1;
    assign ra2_o = ra2;
    assign ra3_o = ra3;
    assign ra4_o = ra4;
    assign ra5_o = ra5;
    assign rc0_o = rc0;
    assign rc1_o = rc1;
    assign rc2_o = rc2;
    assign rc3_o = rc3;
    assign rc4_o = rc4;
    assign rc5_o = rc5;
    assign rs0_o = rs0;
    assign rs1_o = rs1;
    assign rs2_o = rs2;
    assign rs3_o = rs3;
    assign rs4_o = rs4;
    assign rs5_o = rs5;
    assign sa0_o = sa0;
    assign sa1_o = sa1;
    assign sa2_o = sa2;
    assign sa3_o = sa3;
    assign sa4_o = sa4;
    assign sa5_o = sa5;
    assign st0_o = st0;
    assign st1_o = st1;
    assign st2_o = st2;
    assign st3_o = st3;
    assign st4_o = st4;
    assign st5_o = st5;
    assign w0_o = w0;
    assign w1_o = w1;
    assign w2_o = w2;
    assign w3_o = w3;
    assign w4_o = w4;
    assign w5_o = w5;
endmodule

module crc_residue_chk (
    input  wire clk,
    input  wire ce,
    input  wire start,
    input  wire din,
    output reg  done,
    output reg  err
,
    output wire [7:0] bitcnt_o,
    output wire busy_o,
    output wire [7:0] timer_o
);
    // bit-serial CRC-8 (poly x^8+x^2+x+1) residue checker:
    // 8 data bits followed by 8 appended CRC bits; residue must be zero
    reg [7:0] crc    = 8'h00;
    reg [7:0] bitcnt = 8'd0;   // bits consumed in current frame
    reg [7:0] timer  = 8'd0;   // completion watchdog countdown
    reg       busy   = 1'b0;   // frame outstanding
    reg       armed  = 1'b1;   // scope: no CRC error has ever been flagged
    initial done = 1'b0;
    initial err  = 1'b0;

    wire       fb       = crc[7] ^ din;
    wire [7:0] crc_next = {crc[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);
    wire       last     = busy && ce && (bitcnt == 8'd15);

    always @(posedge clk) begin
        if (!busy) begin
            if (start) begin
                busy   <= 1'b1;
                bitcnt <= 8'd0;
                timer  <= 8'd16;
                crc    <= 8'h00;
                done   <= 1'b0;
                err    <= 1'b0;
            end
        end else if (ce) begin
            crc    <= crc_next;
            bitcnt <= bitcnt + 8'd1;
            timer  <= timer - 8'd1;
            if (bitcnt == 8'd15) begin
                busy <= 1'b0;
                done <= 1'b1;
                err  <= (crc_next != 8'h00);
            end
        end
        if (last && (crc_next != 8'h00))
            armed <= 1'b0;
    end

    // before the first CRC error: the watchdog never expires while a frame is outstanding
    always @(*)
        assert (!armed || !busy || timer != 8'd0);
    assign bitcnt_o = bitcnt;
    assign busy_o = busy;
    assign timer_o = timer;
endmodule

module pg_crc_top (
    input  wire clk,
    input  wire rst,
    input  wire [5:0] ce,
    input  wire [5:0] req,
    input  wire b_ce,
    output wire [7:0] pool_o,
    output wire [5:0] win_o,
    output wire [5:0] done_o,
    output wire crc_done,
    output wire crc_err,
    output wire rpt_pend_o,
    output wire [7:0] rpt_mask_o,
    output wire [7:0] rpt_shift_o
,
    output wire [7:0] bitcnt_obs,
    output wire busy_obs,
    output wire [7:0] frame_o,
    output wire [7:0] pool_obs2,
    output wire ra0_obs,
    output wire ra1_obs,
    output wire ra2_obs,
    output wire ra3_obs,
    output wire ra4_obs,
    output wire ra5_obs,
    output wire [7:0] rc0_obs,
    output wire [7:0] rc1_obs,
    output wire [7:0] rc2_obs,
    output wire [7:0] rc3_obs,
    output wire [7:0] rc4_obs,
    output wire [7:0] rc5_obs,
    output wire rs0_obs,
    output wire rs1_obs,
    output wire rs2_obs,
    output wire rs3_obs,
    output wire rs4_obs,
    output wire rs5_obs,
    output wire sa0_obs,
    output wire sa1_obs,
    output wire sa2_obs,
    output wire sa3_obs,
    output wire sa4_obs,
    output wire sa5_obs,
    output wire [7:0] snap_o,
    output wire [2:0] st0_obs,
    output wire [2:0] st1_obs,
    output wire [2:0] st2_obs,
    output wire [2:0] st3_obs,
    output wire [2:0] st4_obs,
    output wire [2:0] st5_obs,
    output wire [7:0] timer_obs,
    output wire w0_obs,
    output wire w1_obs,
    output wire w2_obs,
    output wire w3_obs,
    output wire w4_obs,
    output wire w5_obs
);
    wire [7:0] pool;
    wire w0, w1, w2, w3, w4, w5;
    wire [2:0] st0, st1, st2, st3, st4, st5;
    wire sa0, sa1, sa2, sa3, sa4, sa5;
    wire ra0, ra1, ra2, ra3, ra4, ra5;
    wire rs0, rs1, rs2, rs3, rs4, rs5;
    wire [7:0] rc0, rc1, rc2, rc3, rc4, rc5;
    wire [7:0] bitcnt;
    wire [7:0] timer;
    wire busy;

    pg_pool u_pool (
        .clk(clk), .rst(rst), .ce(ce), .req(req),
        .pool_o(pool_o), .win_o(win_o), .done_o(done_o), .pool_obs(pool),
        .ra0_o(ra0), .ra1_o(ra1), .ra2_o(ra2), .ra3_o(ra3), .ra4_o(ra4), .ra5_o(ra5),
        .rc0_o(rc0), .rc1_o(rc1), .rc2_o(rc2), .rc3_o(rc3), .rc4_o(rc4), .rc5_o(rc5),
        .rs0_o(rs0), .rs1_o(rs1), .rs2_o(rs2), .rs3_o(rs3), .rs4_o(rs4), .rs5_o(rs5),
        .sa0_o(sa0), .sa1_o(sa1), .sa2_o(sa2), .sa3_o(sa3), .sa4_o(sa4), .sa5_o(sa5),
        .st0_o(st0), .st1_o(st1), .st2_o(st2), .st3_o(st3), .st4_o(st4), .st5_o(st5),
        .w0_o(w0), .w1_o(w1), .w2_o(w2), .w3_o(w3), .w4_o(w4), .w5_o(w5)
    );

    // power-down windows retiring this cycle
    wire [5:0] closing;
    assign closing = {ce[5] && (st5 == 3'd4), ce[4] && (st4 == 3'd4), ce[3] && (st3 == 3'd4),
                      ce[2] && (st2 == 3'd4), ce[1] && (st1 == 3'd4), ce[0] && (st0 == 3'd4)};

    // completion report buffer and serializer toward the CRC checker
    reg       pend;
    reg [7:0] snap;
    reg [7:0] frame;
    initial begin
        pend = 1'b0; snap = 8'd0; frame = 8'd0;
    end

    wire launch;
    assign launch = pend && !busy && !rst;
    wire shift_en;
    assign shift_en = busy && b_ce;

    always @(posedge clk) begin
        if (rst) begin
            pend  <= 1'b0;
            snap  <= 8'd0;
            frame <= 8'd0;
        end else begin
            if (launch) begin
                frame <= snap;
                pend  <= 1'b0;
            end else if (shift_en) begin
                frame <= {frame[6:0], 1'b0};
            end
            if (!pend && (closing != 6'd0)) begin
                pend <= 1'b1;
                snap <= {2'b00, closing};
            end
        end
    end

    wire din_b;
    assign din_b = frame[7];

    crc_residue_chk u_crc (
        .clk(clk), .ce(b_ce), .start(launch), .din(din_b),
        .done(crc_done), .err(crc_err),
        .bitcnt_o(bitcnt), .busy_o(busy), .timer_o(timer)
    );

    // the check-bit half of every report frame is all zeros on the wire
    always @(*)
        if (busy && bitcnt >= 8'd8)
            assert (!din_b);

    assign rpt_pend_o  = pend;
    assign rpt_mask_o  = snap;
    assign rpt_shift_o = frame;
    assign bitcnt_obs = bitcnt;
    assign busy_obs = busy;
    assign frame_o = frame;
    assign pool_obs2 = pool;
    assign ra0_obs = ra0;
    assign ra1_obs = ra1;
    assign ra2_obs = ra2;
    assign ra3_obs = ra3;
    assign ra4_obs = ra4;
    assign ra5_obs = ra5;
    assign rc0_obs = rc0;
    assign rc1_obs = rc1;
    assign rc2_obs = rc2;
    assign rc3_obs = rc3;
    assign rc4_obs = rc4;
    assign rc5_obs = rc5;
    assign rs0_obs = rs0;
    assign rs1_obs = rs1;
    assign rs2_obs = rs2;
    assign rs3_obs = rs3;
    assign rs4_obs = rs4;
    assign rs5_obs = rs5;
    assign sa0_obs = sa0;
    assign sa1_obs = sa1;
    assign sa2_obs = sa2;
    assign sa3_obs = sa3;
    assign sa4_obs = sa4;
    assign sa5_obs = sa5;
    assign snap_o = snap;
    assign st0_obs = st0;
    assign st1_obs = st1;
    assign st2_obs = st2;
    assign st3_obs = st3;
    assign st4_obs = st4;
    assign st5_obs = st5;
    assign timer_obs = timer;
    assign w0_obs = w0;
    assign w1_obs = w1;
    assign w2_obs = w2;
    assign w3_obs = w3;
    assign w4_obs = w4;
    assign w5_obs = w5;
endmodule

module pg_crc_quad (
    input  wire clk,
    input  wire rst,
    input  wire [23:0] ce,
    input  wire [23:0] req,
    input  wire [3:0] b_ce,
    output wire [7:0] credit_o,
    output wire [3:0] grant_o,
    output wire [23:0] win_o,
    output wire [3:0] crc_done_o,
    output wire [3:0] crc_err_o
);
    localparam [7:0] OTOTAL = 8'd4;

    reg [7:0] credit;
    initial credit = OTOTAL;

    wire [5:0] ce_i0, ce_i1, ce_i2, ce_i3;
    wire [5:0] rq_i0, rq_i1, rq_i2, rq_i3;
    assign ce_i0 = ce[5:0];
    assign ce_i1 = ce[11:6];
    assign ce_i2 = ce[17:12];
    assign ce_i3 = ce[23:18];
    assign rq_i0 = req[5:0];
    assign rq_i1 = req[11:6];
    assign rq_i2 = req[17:12];
    assign rq_i3 = req[23:18];

    wire [7:0] pool_i0, pool_i1, pool_i2, pool_i3;
    wire [7:0] bitcnt_i0, bitcnt_i1, bitcnt_i2, bitcnt_i3;
    wire [7:0] timer_i0, timer_i1, timer_i2, timer_i3;
    wire [7:0] frame_i0, frame_i1, frame_i2, frame_i3;
    wire [7:0] snap_i0, snap_i1, snap_i2, snap_i3;
    wire busy_i0, busy_i1, busy_i2, busy_i3;

    wire w0_i0, w1_i0, w2_i0, w3_i0, w4_i0, w5_i0;
    wire [2:0] st0_i0, st1_i0, st2_i0, st3_i0, st4_i0, st5_i0;
    wire sa0_i0, sa1_i0, sa2_i0, sa3_i0, sa4_i0, sa5_i0;
    wire ra0_i0, ra1_i0, ra2_i0, ra3_i0, ra4_i0, ra5_i0;
    wire rs0_i0, rs1_i0, rs2_i0, rs3_i0, rs4_i0, rs5_i0;
    wire [7:0] rc0_i0, rc1_i0, rc2_i0, rc3_i0, rc4_i0, rc5_i0;

    wire w0_i1, w1_i1, w2_i1, w3_i1, w4_i1, w5_i1;
    wire [2:0] st0_i1, st1_i1, st2_i1, st3_i1, st4_i1, st5_i1;
    wire sa0_i1, sa1_i1, sa2_i1, sa3_i1, sa4_i1, sa5_i1;
    wire ra0_i1, ra1_i1, ra2_i1, ra3_i1, ra4_i1, ra5_i1;
    wire rs0_i1, rs1_i1, rs2_i1, rs3_i1, rs4_i1, rs5_i1;
    wire [7:0] rc0_i1, rc1_i1, rc2_i1, rc3_i1, rc4_i1, rc5_i1;

    wire w0_i2, w1_i2, w2_i2, w3_i2, w4_i2, w5_i2;
    wire [2:0] st0_i2, st1_i2, st2_i2, st3_i2, st4_i2, st5_i2;
    wire sa0_i2, sa1_i2, sa2_i2, sa3_i2, sa4_i2, sa5_i2;
    wire ra0_i2, ra1_i2, ra2_i2, ra3_i2, ra4_i2, ra5_i2;
    wire rs0_i2, rs1_i2, rs2_i2, rs3_i2, rs4_i2, rs5_i2;
    wire [7:0] rc0_i2, rc1_i2, rc2_i2, rc3_i2, rc4_i2, rc5_i2;

    wire w0_i3, w1_i3, w2_i3, w3_i3, w4_i3, w5_i3;
    wire [2:0] st0_i3, st1_i3, st2_i3, st3_i3, st4_i3, st5_i3;
    wire sa0_i3, sa1_i3, sa2_i3, sa3_i3, sa4_i3, sa5_i3;
    wire ra0_i3, ra1_i3, ra2_i3, ra3_i3, ra4_i3, ra5_i3;
    wire rs0_i3, rs1_i3, rs2_i3, rs3_i3, rs4_i3, rs5_i3;
    wire [7:0] rc0_i3, rc1_i3, rc2_i3, rc3_i3, rc4_i3, rc5_i3;

    // sequencers sitting idle, and windows retiring this cycle, per instance
    wire [5:0] idle_i0, idle_i1, idle_i2, idle_i3;
    wire [5:0] fin_i0, fin_i1, fin_i2, fin_i3;
    assign idle_i0 = {st5_i0 == 3'd0, st4_i0 == 3'd0, st3_i0 == 3'd0, st2_i0 == 3'd0, st1_i0 == 3'd0, st0_i0 == 3'd0};
    assign idle_i1 = {st5_i1 == 3'd0, st4_i1 == 3'd0, st3_i1 == 3'd0, st2_i1 == 3'd0, st1_i1 == 3'd0, st0_i1 == 3'd0};
    assign idle_i2 = {st5_i2 == 3'd0, st4_i2 == 3'd0, st3_i2 == 3'd0, st2_i2 == 3'd0, st1_i2 == 3'd0, st0_i2 == 3'd0};
    assign idle_i3 = {st5_i3 == 3'd0, st4_i3 == 3'd0, st3_i3 == 3'd0, st2_i3 == 3'd0, st1_i3 == 3'd0, st0_i3 == 3'd0};
    assign fin_i0 = ce_i0 & {st5_i0 == 3'd4, st4_i0 == 3'd4, st3_i0 == 3'd4, st2_i0 == 3'd4, st1_i0 == 3'd4, st0_i0 == 3'd4};
    assign fin_i1 = ce_i1 & {st5_i1 == 3'd4, st4_i1 == 3'd4, st3_i1 == 3'd4, st2_i1 == 3'd4, st1_i1 == 3'd4, st0_i1 == 3'd4};
    assign fin_i2 = ce_i2 & {st5_i2 == 3'd4, st4_i2 == 3'd4, st3_i2 == 3'd4, st2_i2 == 3'd4, st1_i2 == 3'd4, st0_i2 == 3'd4};
    assign fin_i3 = ce_i3 & {st5_i3 == 3'd4, st4_i3 == 3'd4, st3_i3 == 3'd4, st2_i3 == 3'd4, st1_i3 == 3'd4, st0_i3 == 3'd4};

    // an instance can open a window this cycle only if its local pool has room
    wire want_i0, want_i1, want_i2, want_i3;
    assign want_i0 = (pool_i0 != 8'd0) && ((ce_i0 & rq_i0 & idle_i0) != 6'd0);
    assign want_i1 = (pool_i1 != 8'd0) && ((ce_i1 & rq_i1 & idle_i1) != 6'd0);
    assign want_i2 = (pool_i2 != 8'd0) && ((ce_i2 & rq_i2 & idle_i2) != 6'd0);
    assign want_i3 = (pool_i3 != 8'd0) && ((ce_i3 & rq_i3 & idle_i3) != 6'd0);

    // global budget arbiter: one new window per cycle chip-wide
    wire avail;
    assign avail = (credit != 8'd0);
    wire gnt0, gnt1, gnt2, gnt3;
    assign gnt0 = avail && want_i0;
    assign gnt1 = avail && want_i1 && !want_i0;
    assign gnt2 = avail && want_i2 && !want_i0 && !want_i1;
    assign gnt3 = avail && want_i3 && !want_i0 && !want_i1 && !want_i2;
    wire acq;
    assign acq = gnt0 | gnt1 | gnt2 | gnt3;

    wire [5:0] qrq_i0, qrq_i1, qrq_i2, qrq_i3;
    assign qrq_i0 = rq_i0 & {6{gnt0}};
    assign qrq_i1 = rq_i1 & {6{gnt1}};
    assign qrq_i2 = rq_i2 & {6{gnt2}};
    assign qrq_i3 = rq_i3 & {6{gnt3}};

    wire [7:0] rel_i0, rel_i1, rel_i2, rel_i3, rel_cnt;
    assign rel_i0 = {7'd0, fin_i0[0]} + {7'd0, fin_i0[1]} + {7'd0, fin_i0[2]} + {7'd0, fin_i0[3]} + {7'd0, fin_i0[4]} + {7'd0, fin_i0[5]};
    assign rel_i1 = {7'd0, fin_i1[0]} + {7'd0, fin_i1[1]} + {7'd0, fin_i1[2]} + {7'd0, fin_i1[3]} + {7'd0, fin_i1[4]} + {7'd0, fin_i1[5]};
    assign rel_i2 = {7'd0, fin_i2[0]} + {7'd0, fin_i2[1]} + {7'd0, fin_i2[2]} + {7'd0, fin_i2[3]} + {7'd0, fin_i2[4]} + {7'd0, fin_i2[5]};
    assign rel_i3 = {7'd0, fin_i3[0]} + {7'd0, fin_i3[1]} + {7'd0, fin_i3[2]} + {7'd0, fin_i3[3]} + {7'd0, fin_i3[4]} + {7'd0, fin_i3[5]};
    assign rel_cnt = rel_i0 + rel_i1 + rel_i2 + rel_i3;

    always @(posedge clk) begin
        if (rst) begin
            credit <= OTOTAL;
        end else begin
            credit <= credit - {7'd0, acq} + rel_cnt;
        end
    end

    pg_crc_top u0 (
        .clk(clk), .rst(rst), .ce(ce_i0), .req(qrq_i0), .b_ce(b_ce[0]),
        .pool_o(), .win_o(win_o[5:0]), .done_o(), .crc_done(crc_done_o[0]), .crc_err(crc_err_o[0]),
        .rpt_pend_o(), .rpt_mask_o(), .rpt_shift_o(),
        .bitcnt_obs(bitcnt_i0), .busy_obs(busy_i0), .frame_o(frame_i0), .pool_obs2(pool_i0),
        .ra0_obs(ra0_i0), .ra1_obs(ra1_i0), .ra2_obs(ra2_i0), .ra3_obs(ra3_i0), .ra4_obs(ra4_i0), .ra5_obs(ra5_i0),
        .rc0_obs(rc0_i0), .rc1_obs(rc1_i0), .rc2_obs(rc2_i0), .rc3_obs(rc3_i0), .rc4_obs(rc4_i0), .rc5_obs(rc5_i0),
        .rs0_obs(rs0_i0), .rs1_obs(rs1_i0), .rs2_obs(rs2_i0), .rs3_obs(rs3_i0), .rs4_obs(rs4_i0), .rs5_obs(rs5_i0),
        .sa0_obs(sa0_i0), .sa1_obs(sa1_i0), .sa2_obs(sa2_i0), .sa3_obs(sa3_i0), .sa4_obs(sa4_i0), .sa5_obs(sa5_i0),
        .snap_o(snap_i0),
        .st0_obs(st0_i0), .st1_obs(st1_i0), .st2_obs(st2_i0), .st3_obs(st3_i0), .st4_obs(st4_i0), .st5_obs(st5_i0),
        .timer_obs(timer_i0),
        .w0_obs(w0_i0), .w1_obs(w1_i0), .w2_obs(w2_i0), .w3_obs(w3_i0), .w4_obs(w4_i0), .w5_obs(w5_i0)
    );

    pg_crc_top u1 (
        .clk(clk), .rst(rst), .ce(ce_i1), .req(qrq_i1), .b_ce(b_ce[1]),
        .pool_o(), .win_o(win_o[11:6]), .done_o(), .crc_done(crc_done_o[1]), .crc_err(crc_err_o[1]),
        .rpt_pend_o(), .rpt_mask_o(), .rpt_shift_o(),
        .bitcnt_obs(bitcnt_i1), .busy_obs(busy_i1), .frame_o(frame_i1), .pool_obs2(pool_i1),
        .ra0_obs(ra0_i1), .ra1_obs(ra1_i1), .ra2_obs(ra2_i1), .ra3_obs(ra3_i1), .ra4_obs(ra4_i1), .ra5_obs(ra5_i1),
        .rc0_obs(rc0_i1), .rc1_obs(rc1_i1), .rc2_obs(rc2_i1), .rc3_obs(rc3_i1), .rc4_obs(rc4_i1), .rc5_obs(rc5_i1),
        .rs0_obs(rs0_i1), .rs1_obs(rs1_i1), .rs2_obs(rs2_i1), .rs3_obs(rs3_i1), .rs4_obs(rs4_i1), .rs5_obs(rs5_i1),
        .sa0_obs(sa0_i1), .sa1_obs(sa1_i1), .sa2_obs(sa2_i1), .sa3_obs(sa3_i1), .sa4_obs(sa4_i1), .sa5_obs(sa5_i1),
        .snap_o(snap_i1),
        .st0_obs(st0_i1), .st1_obs(st1_i1), .st2_obs(st2_i1), .st3_obs(st3_i1), .st4_obs(st4_i1), .st5_obs(st5_i1),
        .timer_obs(timer_i1),
        .w0_obs(w0_i1), .w1_obs(w1_i1), .w2_obs(w2_i1), .w3_obs(w3_i1), .w4_obs(w4_i1), .w5_obs(w5_i1)
    );

    pg_crc_top u2 (
        .clk(clk), .rst(rst), .ce(ce_i2), .req(qrq_i2), .b_ce(b_ce[2]),
        .pool_o(), .win_o(win_o[17:12]), .done_o(), .crc_done(crc_done_o[2]), .crc_err(crc_err_o[2]),
        .rpt_pend_o(), .rpt_mask_o(), .rpt_shift_o(),
        .bitcnt_obs(bitcnt_i2), .busy_obs(busy_i2), .frame_o(frame_i2), .pool_obs2(pool_i2),
        .ra0_obs(ra0_i2), .ra1_obs(ra1_i2), .ra2_obs(ra2_i2), .ra3_obs(ra3_i2), .ra4_obs(ra4_i2), .ra5_obs(ra5_i2),
        .rc0_obs(rc0_i2), .rc1_obs(rc1_i2), .rc2_obs(rc2_i2), .rc3_obs(rc3_i2), .rc4_obs(rc4_i2), .rc5_obs(rc5_i2),
        .rs0_obs(rs0_i2), .rs1_obs(rs1_i2), .rs2_obs(rs2_i2), .rs3_obs(rs3_i2), .rs4_obs(rs4_i2), .rs5_obs(rs5_i2),
        .sa0_obs(sa0_i2), .sa1_obs(sa1_i2), .sa2_obs(sa2_i2), .sa3_obs(sa3_i2), .sa4_obs(sa4_i2), .sa5_obs(sa5_i2),
        .snap_o(snap_i2),
        .st0_obs(st0_i2), .st1_obs(st1_i2), .st2_obs(st2_i2), .st3_obs(st3_i2), .st4_obs(st4_i2), .st5_obs(st5_i2),
        .timer_obs(timer_i2),
        .w0_obs(w0_i2), .w1_obs(w1_i2), .w2_obs(w2_i2), .w3_obs(w3_i2), .w4_obs(w4_i2), .w5_obs(w5_i2)
    );

    pg_crc_top u3 (
        .clk(clk), .rst(rst), .ce(ce_i3), .req(qrq_i3), .b_ce(b_ce[3]),
        .pool_o(), .win_o(win_o[23:18]), .done_o(), .crc_done(crc_done_o[3]), .crc_err(crc_err_o[3]),
        .rpt_pend_o(), .rpt_mask_o(), .rpt_shift_o(),
        .bitcnt_obs(bitcnt_i3), .busy_obs(busy_i3), .frame_o(frame_i3), .pool_obs2(pool_i3),
        .ra0_obs(ra0_i3), .ra1_obs(ra1_i3), .ra2_obs(ra2_i3), .ra3_obs(ra3_i3), .ra4_obs(ra4_i3), .ra5_obs(ra5_i3),
        .rc0_obs(rc0_i3), .rc1_obs(rc1_i3), .rc2_obs(rc2_i3), .rc3_obs(rc3_i3), .rc4_obs(rc4_i3), .rc5_obs(rc5_i3),
        .rs0_obs(rs0_i3), .rs1_obs(rs1_i3), .rs2_obs(rs2_i3), .rs3_obs(rs3_i3), .rs4_obs(rs4_i3), .rs5_obs(rs5_i3),
        .sa0_obs(sa0_i3), .sa1_obs(sa1_i3), .sa2_obs(sa2_i3), .sa3_obs(sa3_i3), .sa4_obs(sa4_i3), .sa5_obs(sa5_i3),
        .snap_o(snap_i3),
        .st0_obs(st0_i3), .st1_obs(st1_i3), .st2_obs(st2_i3), .st3_obs(st3_i3), .st4_obs(st4_i3), .st5_obs(st5_i3),
        .timer_obs(timer_i3),
        .w0_obs(w0_i3), .w1_obs(w1_i3), .w2_obs(w2_i3), .w3_obs(w3_i3), .w4_obs(w4_i3), .w5_obs(w5_i3)
    );

    // the chip-wide budget never exceeds what was provisioned
    always @(posedge clk)
        assert (credit <= OTOTAL);

    assign credit_o = credit;
    assign grant_o = {gnt3, gnt2, gnt1, gnt0};
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
    output reg         fault
,
    output wire hit_q_o,
    output wire miss_q_o
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
            fault  <= miss_q;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
    assign hit_q_o = hit_q;
    assign miss_q_o = miss_q;
endmodule

module awesome_frame_sync (
    input wire clk,
    input wire rst,
    input wire en,
    input wire hdr_ok,
    input wire win_clr,
    output reg [1:0] state
,
    output wire [31:0] bad_cnt_o,
    output wire [3:0] bad_hist_o,
    output wire [31:0] good_cnt_o
);
    localparam [1:0] HUNT = 2'd0, PRESYNC = 2'd1, SYNC = 2'd2;
    reg [31:0] good_cnt;
    reg [31:0] bad_cnt;
    reg [3:0]  bad_hist;
    reg        win;
    initial begin
        state = HUNT; good_cnt = 32'd0; bad_cnt = 32'd0; bad_hist = 4'd0; win = 1'b0;
    end

    wire q_evt = en && (state == PRESYNC) && hdr_ok && (good_cnt == 32'd2);

    always @(posedge clk) begin
        if (rst) begin
            state <= HUNT; good_cnt <= 32'd0; bad_cnt <= 32'd0; bad_hist <= 4'd0; win <= 1'b0;
        end else if (en) begin
            if (win_clr) win <= 1'b0;
            else if (q_evt) win <= 1'b1;
            case (state)
                HUNT: begin
                    if (hdr_ok) begin
                        state <= PRESYNC;
                        good_cnt <= 32'd1;
                    end
                end
                PRESYNC: begin
                    if (hdr_ok) begin
                        if (good_cnt == 32'd2) begin
                            state <= SYNC;
                            good_cnt <= 32'd0;
                            bad_cnt <= 32'd0;
                            bad_hist <= 4'd0;
                        end else begin
                            good_cnt <= good_cnt + 32'd1;
                        end
                    end else begin
                        state <= HUNT;
                        good_cnt <= 32'd0;
                        bad_cnt <= 32'd0;
                        bad_hist <= 4'd0;
                    end
                end
                SYNC: begin
                    if (hdr_ok) begin
                        bad_cnt <= 32'd0;
                        bad_hist <= {bad_hist[2:0], 1'b0};
                    end else if (bad_hist[2:0] == 3'b111) begin
                        state <= HUNT;
                        bad_cnt <= 32'd0;
                        bad_hist <= 4'd0;
                    end else begin
                        bad_cnt <= bad_cnt + 32'd1;
                        bad_hist <= {bad_hist[2:0], 1'b1};
                    end
                end
                default: begin
                    state <= HUNT;
                    good_cnt <= 32'd0;
                    bad_cnt <= 32'd0;
                    bad_hist <= 4'd0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (win && state == 2'd2)
            assert (bad_cnt <= 32'd3);
    assign bad_cnt_o = bad_cnt;
    assign bad_hist_o = bad_hist;
    assign good_cnt_o = good_cnt;
endmodule

module mpu_frame_monitor (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    input  wire        fs_en,
    input  wire        win_clr,
    output wire        grant,
    output wire        fault,
    output wire [1:0]  sync_state,
    output wire [1:0]  occ_o,
    output wire        slot_vld_o,
    output wire [31:0] bad_cnt_out
);
    wire        a_grant;
    wire        a_fault;
    wire        hit_q_w;
    wire        miss_q_w;
    wire [1:0]  fs_state;
    wire [31:0] b_bad_cnt;
    wire [3:0]  b_bad_hist;
    wire [31:0] b_good_cnt;

    // one-entry verdict slot between checker and frame sync
    reg       slot_vld = 1'b0;
    reg       slot_ok  = 1'b0;
    // accesses accepted by the checker and not yet consumed downstream
    reg [1:0] occ      = 2'd0;

    wire b_take = fs_en && slot_vld;
    wire a_ce   = ce && !rst && (!slot_vld || fs_en);
    wire a_ret  = a_grant || a_fault;
    wire a_push = a_ce && acc_valid;

    mpu_region_checker u_mpu (
        .clk(clk), .i_ce(a_ce), .cfg_we(cfg_we), .cfg_idx(cfg_idx),
        .cfg_base(cfg_base), .cfg_limit(cfg_limit), .cfg_perm(cfg_perm),
        .lock_req(lock_req), .acc_valid(acc_valid), .acc_write(acc_write),
        .acc_addr(acc_addr), .grant(a_grant), .fault(a_fault),
        .hit_q_o(hit_q_w), .miss_q_o(miss_q_w)
    );

    awesome_frame_sync u_fs (
        .clk(clk), .rst(rst), .en(b_take), .hdr_ok(slot_ok), .win_clr(win_clr),
        .state(fs_state), .bad_cnt_o(b_bad_cnt), .bad_hist_o(b_bad_hist),
        .good_cnt_o(b_good_cnt)
    );

    always @(posedge clk) begin
        if (rst) begin
            slot_vld <= 1'b0;
            slot_ok  <= 1'b0;
            // checker has no reset: resync occupancy from its pipeline
            occ <= {1'b0, hit_q_w || miss_q_w} + {1'b0, a_ret};
        end else begin
            if (a_ce && a_ret) begin
                slot_vld <= 1'b1;
                slot_ok  <= a_grant;
            end else if (b_take) begin
                slot_vld <= 1'b0;
            end
            occ <= occ + {1'b0, a_push} - {1'b0, b_take};
        end
    end

    always @(posedge clk)
        if (slot_vld)
            assert (occ != 2'd0);

    assign grant       = a_grant;
    assign fault       = a_fault;
    assign sync_state  = fs_state;
    assign occ_o       = occ;
    assign slot_vld_o  = slot_vld;
    assign bad_cnt_out = b_bad_cnt;
endmodule

module wormhole_route_unit #(
    parameter [63:0] MY_X = 64'd4,
    parameter [63:0] MY_Y = 64'd2
) (
    input  wire        clk,
    input  wire        in_valid,
    input  wire [1:0]  flit_type,
    input  wire [3:0]  in_ch,
    input  wire [63:0] dest_x,
    input  wire [63:0] dest_y,
    output reg  [2:0]  out_port,
    output wire        out_fire
,
    output wire [63:0] body_cnt_o,
    output wire head_seen_o,
    output wire [15:0] route_valid_o
);
    localparam [1:0] FT_BODY = 2'b00;
    localparam [1:0] FT_HEAD = 2'b01;
    localparam [1:0] FT_TAIL = 2'b10;

    localparam [2:0] P_LOCAL = 3'd0;
    localparam [2:0] P_EAST  = 3'd1;
    localparam [2:0] P_WEST  = 3'd2;
    localparam [2:0] P_NORTH = 3'd3;
    localparam [2:0] P_SOUTH = 3'd4;

    reg [15:0] route_valid;
    reg [47:0] route_port;
    reg [63:0] head_cnt;
    reg [63:0] body_cnt;
    reg        head_seen;
    reg        armed;

    initial begin
        route_valid = 16'd0;
        route_port  = 48'd0;
        head_cnt    = 64'd0;
        body_cnt    = 64'd0;
        head_seen   = 1'b0;
        armed       = 1'b1;
        out_port    = 3'd0;
    end

    wire ch_busy = route_valid[in_ch];
    wire do_head = in_valid && (flit_type == FT_HEAD) && !ch_busy;
    wire do_body = in_valid && (flit_type == FT_BODY) && ch_busy;
    wire do_tail = in_valid && (flit_type == FT_TAIL) && ch_busy;

    assign out_fire = do_head || do_body || do_tail;

    reg [2:0] calc_port;
    always @(*) begin
        if (dest_x > MY_X)      calc_port = P_EAST;
        else if (dest_x < MY_X) calc_port = P_WEST;
        else if (dest_y > MY_Y) calc_port = P_NORTH;
        else if (dest_y < MY_Y) calc_port = P_SOUTH;
        else                    calc_port = P_LOCAL;
    end

    wire [2:0] stored_port = route_port[in_ch*3 +: 3];

    always @(posedge clk) begin
        if (do_head) begin
            route_valid[in_ch]         <= 1'b1;
            route_port[in_ch*3 +: 3]   <= calc_port;
            head_cnt                   <= head_cnt + 64'd1;
            head_seen                  <= 1'b1;
            out_port                   <= calc_port;
        end
        if (do_body) begin
            body_cnt <= body_cnt + 64'd1;
            out_port <= stored_port;
        end
        if (do_tail) begin
            route_valid[in_ch] <= 1'b0;
            armed              <= 1'b0;
            out_port           <= stored_port;
        end
    end

    always @(*) assert (!armed || (body_cnt == 64'd0) || head_seen);
    assign body_cnt_o = body_cnt;
    assign head_seen_o = head_seen;
    assign route_valid_o = route_valid;
endmodule

module wormhole_credit_pool (
    input  wire        clk,
    input  wire        rst,
    input  wire [3:0]  in_valid,
    input  wire [7:0]  flit_type,
    input  wire [15:0] in_ch,
    input  wire [63:0] dest_x,
    input  wire [63:0] dest_y,
    output wire [11:0] out_port,
    output wire [3:0]  out_fire,
    output wire [63:0] credits_free
);
    localparam [63:0] TOTAL   = 64'd6;
    localparam [1:0]  FT_HEAD = 2'b01;
    localparam [1:0]  FT_TAIL = 2'b10;

    reg [63:0] pool;
    initial pool = TOTAL;

    function [63:0] popcnt16;
        input [15:0] v;
        integer k;
        begin
            popcnt16 = 64'd0;
            for (k = 0; k < 16; k = k + 1)
                popcnt16 = popcnt16 + {63'd0, v[k]};
        end
    endfunction

    wire [1:0] ft0 = flit_type[1:0];
    wire [1:0] ft1 = flit_type[3:2];
    wire [1:0] ft2 = flit_type[5:4];
    wire [1:0] ft3 = flit_type[7:6];

    wire hr0 = in_valid[0] && (ft0 == FT_HEAD);
    wire hr1 = in_valid[1] && (ft1 == FT_HEAD);
    wire hr2 = in_valid[2] && (ft2 == FT_HEAD);
    wire hr3 = in_valid[3] && (ft3 == FT_HEAD);

    wire pool_avail = (pool != 64'd0);
    wire g0 = pool_avail && hr0;
    wire g1 = pool_avail && hr1 && !hr0;
    wire g2 = pool_avail && hr2 && !hr0 && !hr1;
    wire g3 = pool_avail && hr3 && !hr0 && !hr1 && !hr2;

    wire v0 = !rst && in_valid[0] && ((ft0 != FT_HEAD) || g0);
    wire v1 = !rst && in_valid[1] && ((ft1 != FT_HEAD) || g1);
    wire v2 = !rst && in_valid[2] && ((ft2 != FT_HEAD) || g2);
    wire v3 = !rst && in_valid[3] && ((ft3 != FT_HEAD) || g3);

    wire f0, f1, f2, f3;
    wire h0, h1, h2, h3;
    wire [63:0] b0, b1, b2, b3;
    wire [15:0] rv0, rv1, rv2, rv3;

    wormhole_route_unit u0 (.clk(clk), .in_valid(v0), .flit_type(ft0), .in_ch(in_ch[3:0]),
        .dest_x(dest_x), .dest_y(dest_y), .out_port(out_port[2:0]), .out_fire(f0),
        .body_cnt_o(b0), .head_seen_o(h0), .route_valid_o(rv0));
    wormhole_route_unit u1 (.clk(clk), .in_valid(v1), .flit_type(ft1), .in_ch(in_ch[7:4]),
        .dest_x(dest_x), .dest_y(dest_y), .out_port(out_port[5:3]), .out_fire(f1),
        .body_cnt_o(b1), .head_seen_o(h1), .route_valid_o(rv1));
    wormhole_route_unit u2 (.clk(clk), .in_valid(v2), .flit_type(ft2), .in_ch(in_ch[11:8]),
        .dest_x(dest_x), .dest_y(dest_y), .out_port(out_port[8:6]), .out_fire(f2),
        .body_cnt_o(b2), .head_seen_o(h2), .route_valid_o(rv2));
    wormhole_route_unit u3 (.clk(clk), .in_valid(v3), .flit_type(ft3), .in_ch(in_ch[15:12]),
        .dest_x(dest_x), .dest_y(dest_y), .out_port(out_port[11:9]), .out_fire(f3),
        .body_cnt_o(b3), .head_seen_o(h3), .route_valid_o(rv3));

    assign out_fire = {f3, f2, f1, f0};

    wire [63:0] t0 = popcnt16(rv0);
    wire [63:0] t1 = popcnt16(rv1);
    wire [63:0] t2 = popcnt16(rv2);
    wire [63:0] t3 = popcnt16(rv3);
    wire [63:0] held = t0 + t1 + t2 + t3;

    wire acq0 = f0 && (ft0 == FT_HEAD);
    wire acq1 = f1 && (ft1 == FT_HEAD);
    wire acq2 = f2 && (ft2 == FT_HEAD);
    wire acq3 = f3 && (ft3 == FT_HEAD);
    wire acq_any = acq0 || acq1 || acq2 || acq3;

    wire rel0 = f0 && (ft0 == FT_TAIL);
    wire rel1 = f1 && (ft1 == FT_TAIL);
    wire rel2 = f2 && (ft2 == FT_TAIL);
    wire rel3 = f3 && (ft3 == FT_TAIL);
    wire [63:0] rel_cnt = {63'd0, rel0} + {63'd0, rel1} + {63'd0, rel2} + {63'd0, rel3};

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL - held;
        end else begin
            pool <= pool - {63'd0, acq_any} + rel_cnt;
        end
    end

    assign credits_free = pool;

    always @(*) assert (pool <= TOTAL);
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  dbg_stat
,
    output wire [3:0] cnt_o,
    output wire half_beat_o,
    output wire [2:0] rd_ptr_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg [7:0]  n_start;
reg [7:0]  n_stop;
reg [15:0] n_words;
reg [15:0] en_cyc;
reg [7:0]  win_len;
reg [7:0]  max_win;
reg        wrap_seen;
reg        half_beat;

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
n_start   = 8'd0;
n_stop    = 8'd0;
n_words   = 16'd0;
en_cyc    = 16'd0;
win_len   = 8'd0;
max_win   = 8'd0;
wrap_seen = 1'b0;
half_beat = 1'b0;
dbg_stat  = 32'h0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
n_start   <= 8'd0;
n_stop    <= 8'd0;
n_words   <= 16'd0;
en_cyc    <= 16'd0;
win_len   <= 8'd0;
max_win   <= 8'd0;
wrap_seen <= 1'b0;
half_beat <= 1'b0;
dbg_stat  <= 32'h0;
        end else if (en) begin
en_cyc <= en_cyc + 16'd1;
if (start && n_start != 8'hFF) n_start <= n_start + 8'd1;
if (stop && !start && n_stop != 8'hFF) n_stop <= n_stop + 8'd1;
if (!start && !stop && win) begin
    n_words <= n_words + 16'd1;
    if (rd_ptr == 3'd7) wrap_seen <= 1'b1;
    if (win_len != 8'hFF) win_len <= win_len + 8'd1;
end
if (start) win_len <= 8'd0;
if (win_len > max_win) max_win <= win_len;
dbg_stat <= {n_start[3:0], n_stop[3:0], max_win, n_words[11:0], wrap_seen, half_beat, en_cyc[1:0]};
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
half_beat <= 1'b0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
half_beat <= 1'b0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
if (half_beat) cnt <= cnt + 4'd2;
half_beat <= !half_beat;
                end
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
    assign cnt_o = cnt;
    assign half_beat_o = half_beat;
    assign rd_ptr_o = rd_ptr;
endmodule

module prbs_win_checker (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_bit,
    input  wire        i_arm,
    input  wire        i_disarm,
    output wire        o_sync,
    output wire [63:0] o_errs
,
    output wire [63:0] err_cnt_o,
    output wire [63:0] err_snap_o,
    output wire win_o,
    output wire [63:0] win_errs_o
);
    localparam [63:0] SYNC_LEN = 64'd8;
    localparam [63:0] LOSS_LEN = 64'd4;
    localparam [63:0] MAXV     = 64'hFFFFFFFFFFFFFFFF;

    reg [63:0] ref_sr;
    reg        sync;
    reg [63:0] match_run;
    reg [63:0] bad_run;
    reg [63:0] err_cnt;
    reg        win;
    reg [63:0] err_snap;
    reg [63:0] win_errs;

    initial ref_sr    = 64'h1;
    initial sync      = 1'b0;
    initial match_run = 64'd0;
    initial bad_run   = 64'd0;
    initial err_cnt   = 64'd0;
    initial win       = 1'b0;
    initial err_snap  = 64'd0;
    initial win_errs  = 64'd0;

    // PRBS x^64 + x^63 + x^61 + x^60 + 1 prediction
    wire        pred    = ref_sr[63] ^ ref_sr[62] ^ ref_sr[60] ^ ref_sr[59];
    wire        mism    = sync && (i_bit != pred);
    wire        cnt_inc = mism && (err_cnt != MAXV);
    wire [63:0] err_nxt = cnt_inc ? (err_cnt + 64'd1) : err_cnt;
    wire        lose    = mism && ((bad_run + 64'd1) >= LOSS_LEN);
    wire        open_w  = i_arm && sync && !lose && !i_disarm;
    wire        close_w = i_disarm || lose;

    always @(posedge clk) begin
        if (i_reset) begin
            ref_sr    <= 64'h1;
            sync      <= 1'b0;
            match_run <= 64'd0;
            bad_run   <= 64'd0;
            err_cnt   <= 64'd0;
            win       <= 1'b0;
            err_snap  <= 64'd0;
            win_errs  <= 64'd0;
        end else if (i_ce) begin
            err_cnt <= err_nxt;
            if (!sync) begin
                // self-synchronising: load incoming stream into reference
                ref_sr  <= {ref_sr[62:0], i_bit};
                bad_run <= 64'd0;
                if (i_bit == pred) begin
                    if ((match_run + 64'd1) >= SYNC_LEN) begin
                        sync      <= 1'b1;
                        match_run <= 64'd0;
                    end else begin
                        match_run <= match_run + 64'd1;
                    end
                end else begin
                    match_run <= 64'd0;
                end
            end else begin
                // locked: free-run the local reference
                ref_sr    <= {ref_sr[62:0], pred};
                match_run <= 64'd0;
                if (mism) begin
                    if (lose) begin
                        sync    <= 1'b0;
                        bad_run <= 64'd0;
                    end else begin
                        bad_run <= bad_run + 64'd1;
                    end
                end else begin
                    bad_run <= 64'd0;
                end
            end
            // measurement window: opened by arm while locked, closed by disarm or sync loss
            if (win) begin
                if (close_w) win <= 1'b0;
                if (cnt_inc) win_errs <= win_errs + 64'd1;
            end else if (open_w) begin
                win      <= 1'b1;
                err_snap <= err_nxt;
                win_errs <= 64'd0;
            end
        end
    end

    assign o_sync = sync;
    assign o_errs = err_cnt;

    // Precedence inside the window: a nonzero window tally requires the global
    // counter to have advanced past the snapshot recorded when the window opened.
    always @(*)
        if (win && (win_errs != 64'd0))
            assert (err_cnt != err_snap);

    // With no window errors, the global counter must still equal the snapshot.
    always @(*)
        if (win && (win_errs == 64'd0))
            assert (err_cnt == err_snap);
    assign err_cnt_o = err_cnt;
    assign err_snap_o = err_snap;
    assign win_o = win;
    assign win_errs_o = win_errs;
endmodule

module route_prbs_top (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    input  wire         ld,
    input  wire         step,
    input  wire         arm,
    input  wire         disarm,
    output wire [127:0] out_q,
    output wire         out_v,
    output wire [31:0]  dbg_stat,
    output wire         o_sync,
    output wire [63:0]  o_errs,
    output wire         win_o,
    output wire [8:0]   stg_o
);
    wire [3:0]  a_cnt;
    wire        a_half_beat;
    wire [2:0]  a_rd_ptr;
    wire [63:0] b_err_cnt;
    wire [63:0] b_err_snap;
    wire        b_win;
    wire [63:0] b_win_errs;

    xbar_route_rom u_a (
        .clk(clk), .rst_n(rst_n), .en(en), .start(start), .stop(stop),
        .out_q(out_q), .out_v(out_v), .dbg_stat(dbg_stat),
        .cnt_o(a_cnt), .half_beat_o(a_half_beat), .rd_ptr_o(a_rd_ptr)
    );

    // beat staging register: latches the route cursor, then sequences it locally
    reg       g_v;
    reg [2:0] g_ptr;
    reg [3:0] g_cnt;
    reg       g_hb;
   // half-beat carry: registered on the odd beat, folded into g_cnt on the next advance
   reg       g_pend;

    initial begin
        g_v   = 1'b0;
        g_ptr = 3'd0;
        g_cnt = 4'd0;
        g_hb  = 1'b0;
       g_pend = 1'b0;
    end

    wire g_load = ld && out_v;
    wire g_adv  = step && g_v && !g_load;

    always @(posedge clk) begin
        if (!rst_n) begin
            g_v   <= 1'b0;
            g_ptr <= 3'd0;
            g_cnt <= 4'd0;
            g_hb  <= 1'b0;
           g_pend <= 1'b0;
        end else if (g_load) begin
            g_v   <= 1'b1;
            g_ptr <= a_rd_ptr;
            g_cnt <= a_cnt;
            g_hb  <= a_half_beat;
           g_pend <= 1'b0;
        end else if (g_adv) begin
            if (g_ptr == 3'd7) begin
                g_ptr <= 3'd0;
                g_cnt <= 4'd0;
                g_hb  <= 1'b0;
               g_pend <= 1'b0;
            end else begin
                g_ptr <= g_ptr + 3'd1;
               if (g_pend) g_cnt <= g_cnt + 4'd2;
                g_hb  <= !g_hb;
               g_pend <= g_hb;
            end
        end
    end

    wire stg_bit = g_ptr[0] ^ g_ptr[1] ^ g_ptr[2] ^ g_cnt[1] ^ g_cnt[2] ^ g_hb;
    wire b_ce    = g_adv;
    wire b_rst   = !rst_n;

    prbs_win_checker u_b (
        .clk(clk), .i_reset(b_rst), .i_ce(b_ce), .i_bit(stg_bit),
        .i_arm(arm), .i_disarm(disarm),
        .o_sync(o_sync), .o_errs(o_errs),
        .err_cnt_o(b_err_cnt), .err_snap_o(b_err_snap),
        .win_o(b_win), .win_errs_o(b_win_errs)
    );

    assign win_o = b_win;
    assign stg_o = {g_v, g_ptr, g_cnt, g_hb};

    // a staged cursor must always name a beat within the eight-entry route table
    always @(*)
        if (g_v)
            assert (g_cnt <= 4'd7);
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
    output reg          out_v
,
    output wire [3:0] cnt_o,
    output wire pf_vld_o,
    output wire [127:0] pf_word_o,
    output wire [2:0] rd_ptr_o,
    output wire win_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
localparam [1:0] ROM_LAT  = 2'd3;
localparam [3:0] MAX_PASS = 4'd15;
reg [127:0] pf_word;
reg         pf_vld;
reg [1:0]   pf_wait;
reg [3:0]   pass_cnt;
reg         sweep_done;
wire [127:0] issue_word = {pf_word[127:80], 12'h0, pass_cnt, pf_word[63:0]};

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
pf_word    = 128'h0;
pf_vld     = 1'b0;
pf_wait    = 2'd0;
pass_cnt   = 4'd0;
sweep_done = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
pf_word    <= 128'h0;
pf_vld     <= 1'b0;
pf_wait    <= 2'd0;
pass_cnt   <= 4'd0;
sweep_done <= 1'b0;
        end else if (en) begin
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
pf_vld     <= 1'b0;
pf_wait    <= 2'd0;
pass_cnt   <= 4'd0;
sweep_done <= 1'b0;
            end else if (stop) begin
                win <= 1'b0;
end else if (win && pf_vld) begin
out_q  <= issue_word;
                out_v <= 1'b1;
pf_vld <= 1'b0;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
if (pass_cnt == MAX_PASS) begin
win        <= 1'b0;
pass_cnt   <= 4'd0;
sweep_done <= 1'b1;
end else begin
pass_cnt <= pass_cnt + 4'd1;
end
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                    cnt    <= cnt + 4'd1;
                end
end else if (win) begin
if (pf_wait == ROM_LAT) begin
pf_word <= rom_word;
pf_vld  <= 1'b1;
pf_wait <= 2'd0;
end else begin
pf_wait <= pf_wait + 2'd1;
end
end else if (sweep_done) begin
out_v <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);

   always @(posedge clk)
       if (win && en && cnt != 4'd0)
           assert (out_q[63:48] == {12'h0, cnt - 4'd1});
    assign cnt_o = cnt;
    assign pf_vld_o = pf_vld;
    assign pf_word_o = pf_word;
    assign rd_ptr_o = rd_ptr;
    assign win_o = win;
endmodule

module xbar_route_pool (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       en,
    input  wire [5:0] req,
    input  wire [5:0] rel,
    output wire [3:0] pool_o,
    output wire [5:0] held_o,
    output wire [5:0] win_vec_o,
    output wire [5:0] vld_vec_o
,
    output wire [3:0] cnt0_o,
    output wire [3:0] cnt1_o,
    output wire [3:0] cnt2_o,
    output wire [3:0] cnt3_o,
    output wire [3:0] cnt4_o,
    output wire [3:0] cnt5_o,
    output wire h0_o,
    output wire h1_o,
    output wire h2_o,
    output wire h3_o,
    output wire h4_o,
    output wire h5_o,
    output wire [127:0] oq0_o,
    output wire [127:0] oq1_o,
    output wire [127:0] oq2_o,
    output wire [127:0] oq3_o,
    output wire [127:0] oq4_o,
    output wire [127:0] oq5_o,
    output wire pfv0_o,
    output wire pfv1_o,
    output wire pfv2_o,
    output wire pfv3_o,
    output wire pfv4_o,
    output wire pfv5_o,
    output wire [127:0] pfw0_o,
    output wire [127:0] pfw1_o,
    output wire [127:0] pfw2_o,
    output wire [127:0] pfw3_o,
    output wire [127:0] pfw4_o,
    output wire [127:0] pfw5_o,
    output wire [3:0] pool_obs,
    output wire [2:0] rdp0_o,
    output wire [2:0] rdp1_o,
    output wire [2:0] rdp2_o,
    output wire [2:0] rdp3_o,
    output wire [2:0] rdp4_o,
    output wire [2:0] rdp5_o,
    output wire win0_o,
    output wire win1_o,
    output wire win2_o,
    output wire win3_o,
    output wire win4_o,
    output wire win5_o
);
    localparam [3:0] TOTAL = 4'd4;

    reg [3:0] pool;
    reg h0, h1, h2, h3, h4, h5;

    initial begin
        pool = TOTAL;
        h0 = 1'b0; h1 = 1'b0; h2 = 1'b0;
        h3 = 1'b0; h4 = 1'b0; h5 = 1'b0;
    end

    wire can_gnt = en && (pool != 4'd0);
    wire w0 = req[0] && !h0;
    wire w1 = req[1] && !h1;
    wire w2 = req[2] && !h2;
    wire w3 = req[3] && !h3;
    wire w4 = req[4] && !h4;
    wire w5 = req[5] && !h5;
    wire g0 = can_gnt && w0;
    wire g1 = can_gnt && w1 && !w0;
    wire g2 = can_gnt && w2 && !w0 && !w1;
    wire g3 = can_gnt && w3 && !w0 && !w1 && !w2;
    wire g4 = can_gnt && w4 && !w0 && !w1 && !w2 && !w3;
    wire g5 = can_gnt && w5 && !w0 && !w1 && !w2 && !w3 && !w4;
    wire any_g = g0 | g1 | g2 | g3 | g4 | g5;

    wire c0 = rel[0] && h0;
    wire c1 = rel[1] && h1;
    wire c2 = rel[2] && h2;
    wire c3 = rel[3] && h3;
    wire c4 = rel[4] && h4;
    wire c5 = rel[5] && h5;
    wire r0 = en && c0;
    wire r1 = en && c1 && !c0;
    wire r2 = en && c2 && !c0 && !c1;
    wire r3 = en && c3 && !c0 && !c1 && !c2;
    wire r4 = en && c4 && !c0 && !c1 && !c2 && !c3;
    wire r5 = en && c5 && !c0 && !c1 && !c2 && !c3 && !c4;
    wire any_r = r0 | r1 | r2 | r3 | r4 | r5;

    wire [127:0] oq0, oq1, oq2, oq3, oq4, oq5;
    wire ov0, ov1, ov2, ov3, ov4, ov5;
    wire [3:0] cnt0, cnt1, cnt2, cnt3, cnt4, cnt5;
    wire pfv0, pfv1, pfv2, pfv3, pfv4, pfv5;
    wire [127:0] pfw0, pfw1, pfw2, pfw3, pfw4, pfw5;
    wire [2:0] rdp0, rdp1, rdp2, rdp3, rdp4, rdp5;
    wire win0, win1, win2, win3, win4, win5;

    xbar_route_rom u0 (.clk(clk), .rst_n(rst_n), .en(en), .start(g0), .stop(r0), .out_q(oq0), .out_v(ov0), .cnt_o(cnt0), .pf_vld_o(pfv0), .pf_word_o(pfw0), .rd_ptr_o(rdp0), .win_o(win0));
    xbar_route_rom u1 (.clk(clk), .rst_n(rst_n), .en(en), .start(g1), .stop(r1), .out_q(oq1), .out_v(ov1), .cnt_o(cnt1), .pf_vld_o(pfv1), .pf_word_o(pfw1), .rd_ptr_o(rdp1), .win_o(win1));
    xbar_route_rom u2 (.clk(clk), .rst_n(rst_n), .en(en), .start(g2), .stop(r2), .out_q(oq2), .out_v(ov2), .cnt_o(cnt2), .pf_vld_o(pfv2), .pf_word_o(pfw2), .rd_ptr_o(rdp2), .win_o(win2));
    xbar_route_rom u3 (.clk(clk), .rst_n(rst_n), .en(en), .start(g3), .stop(r3), .out_q(oq3), .out_v(ov3), .cnt_o(cnt3), .pf_vld_o(pfv3), .pf_word_o(pfw3), .rd_ptr_o(rdp3), .win_o(win3));
    xbar_route_rom u4 (.clk(clk), .rst_n(rst_n), .en(en), .start(g4), .stop(r4), .out_q(oq4), .out_v(ov4), .cnt_o(cnt4), .pf_vld_o(pfv4), .pf_word_o(pfw4), .rd_ptr_o(rdp4), .win_o(win4));
    xbar_route_rom u5 (.clk(clk), .rst_n(rst_n), .en(en), .start(g5), .stop(r5), .out_q(oq5), .out_v(ov5), .cnt_o(cnt5), .pf_vld_o(pfv5), .pf_word_o(pfw5), .rd_ptr_o(rdp5), .win_o(win5));

    always @(posedge clk) begin
        if (!rst_n) begin
            pool <= TOTAL;
            h0 <= 1'b0; h1 <= 1'b0; h2 <= 1'b0;
            h3 <= 1'b0; h4 <= 1'b0; h5 <= 1'b0;
        end else begin
            if (g0) h0 <= 1'b1; else if (r0) h0 <= 1'b0;
            if (g1) h1 <= 1'b1; else if (r1) h1 <= 1'b0;
            if (g2) h2 <= 1'b1; else if (r2) h2 <= 1'b0;
            if (g3) h3 <= 1'b1; else if (r3) h3 <= 1'b0;
            if (g4) h4 <= 1'b1; else if (r4) h4 <= 1'b0;
            if (g5) h5 <= 1'b1; else if (r5) h5 <= 1'b0;
            pool <= pool - {3'b0, any_g} + {3'b0, any_r};
        end
    end

    always @(posedge clk)
        assert (pool <= TOTAL);

    assign pool_o    = pool;
    assign held_o    = {h5, h4, h3, h2, h1, h0};
    assign win_vec_o = {win5, win4, win3, win2, win1, win0};
    assign vld_vec_o = {ov5, ov4, ov3, ov2, ov1, ov0};
    assign cnt0_o = cnt0;
    assign cnt1_o = cnt1;
    assign cnt2_o = cnt2;
    assign cnt3_o = cnt3;
    assign cnt4_o = cnt4;
    assign cnt5_o = cnt5;
    assign h0_o = h0;
    assign h1_o = h1;
    assign h2_o = h2;
    assign h3_o = h3;
    assign h4_o = h4;
    assign h5_o = h5;
    assign oq0_o = oq0;
    assign oq1_o = oq1;
    assign oq2_o = oq2;
    assign oq3_o = oq3;
    assign oq4_o = oq4;
    assign oq5_o = oq5;
    assign pfv0_o = pfv0;
    assign pfv1_o = pfv1;
    assign pfv2_o = pfv2;
    assign pfv3_o = pfv3;
    assign pfv4_o = pfv4;
    assign pfv5_o = pfv5;
    assign pfw0_o = pfw0;
    assign pfw1_o = pfw1;
    assign pfw2_o = pfw2;
    assign pfw3_o = pfw3;
    assign pfw4_o = pfw4;
    assign pfw5_o = pfw5;
    assign pool_obs = pool;
    assign rdp0_o = rdp0;
    assign rdp1_o = rdp1;
    assign rdp2_o = rdp2;
    assign rdp3_o = rdp3;
    assign rdp4_o = rdp4;
    assign rdp5_o = rdp5;
    assign win0_o = win0;
    assign win1_o = win1;
    assign win2_o = win2;
    assign win3_o = win3;
    assign win4_o = win4;
    assign win5_o = win5;
endmodule

module xbar_route_credit4 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [3:0]  en,
    input  wire [23:0] req,
    input  wire [23:0] rel,
    output wire [3:0]  spool_o,
    output wire [15:0] ipool_o,
    output wire [3:0]  busy_o
);
    localparam [3:0] TOTAL = 4'd8;

    reg [3:0] spool;
    initial spool = TOTAL;

    wire [3:0] i0_pool, i1_pool, i2_pool, i3_pool;
    wire [5:0] i0_held, i1_held, i2_held, i3_held;
    wire i0_h0, i0_h1, i0_h2, i0_h3, i0_h4, i0_h5;
    wire i1_h0, i1_h1, i1_h2, i1_h3, i1_h4, i1_h5;
    wire i2_h0, i2_h1, i2_h2, i2_h3, i2_h4, i2_h5;
