    wire [3:0] i2_cnt0, i2_cnt1, i2_cnt2, i2_cnt3, i2_cnt4, i2_cnt5;
    wire [3:0] i3_cnt0, i3_cnt1, i3_cnt2, i3_cnt3, i3_cnt4, i3_cnt5;
    wire [2:0] i0_rdp0, i0_rdp1, i0_rdp2, i0_rdp3, i0_rdp4, i0_rdp5;
    wire [2:0] i1_rdp0, i1_rdp1, i1_rdp2, i1_rdp3, i1_rdp4, i1_rdp5;
    wire [2:0] i2_rdp0, i2_rdp1, i2_rdp2, i2_rdp3, i2_rdp4, i2_rdp5;
    wire [2:0] i3_rdp0, i3_rdp1, i3_rdp2, i3_rdp3, i3_rdp4, i3_rdp5;
    wire i0_win0, i0_win1, i0_win2, i0_win3, i0_win4, i0_win5;
    wire i1_win0, i1_win1, i1_win2, i1_win3, i1_win4, i1_win5;
    wire i2_win0, i2_win1, i2_win2, i2_win3, i2_win4, i2_win5;
    wire i3_win0, i3_win1, i3_win2, i3_win3, i3_win4, i3_win5;
    wire [127:0] i0_oq0, i0_oq1, i0_oq2, i0_oq3, i0_oq4, i0_oq5;
    wire [127:0] i1_oq0, i1_oq1, i1_oq2, i1_oq3, i1_oq4, i1_oq5;
    wire [127:0] i2_oq0, i2_oq1, i2_oq2, i2_oq3, i2_oq4, i2_oq5;
    wire [127:0] i3_oq0, i3_oq1, i3_oq2, i3_oq3, i3_oq4, i3_oq5;
    wire i0_pfv0, i0_pfv1, i0_pfv2, i0_pfv3, i0_pfv4, i0_pfv5;
