    wire give2 = en[2] && ((rel[17:12] & i2_held) != 6'd0);
    wire give3 = en[3] && ((rel[23:18] & i3_held) != 6'd0);
    wire [2:0] n_give = {2'b0, give0} + {2'b0, give1} + {2'b0, give2} + {2'b0, give3};

    wire [2:0] t0 = {2'b0, i0_h0} + {2'b0, i0_h1} + {2'b0, i0_h2} + {2'b0, i0_h3} + {2'b0, i0_h4} + {2'b0, i0_h5};
    wire [2:0] t1 = {2'b0, i1_h0} + {2'b0, i1_h1} + {2'b0, i1_h2} + {2'b0, i1_h3} + {2'b0, i1_h4} + {2'b0, i1_h5};
    wire [2:0] t2 = {2'b0, i2_h0} + {2'b0, i2_h1} + {2'b0, i2_h2} + {2'b0, i2_h3} + {2'b0, i2_h4} + {2'b0, i2_h5};
    wire [2:0] t3 = {2'b0, i3_h0} + {2'b0, i3_h1} + {2'b0, i3_h2} + {2'b0, i3_h3} + {2'b0, i3_h4} + {2'b0, i3_h5};

    xbar_route_pool p0 (.clk(clk), .rst_n(rst_n), .en(en[0]), .req(q0), .rel(rel[5:0]),
        .pool_o(i0_pool), .held_o(i0_held), .win_vec_o(), .vld_vec_o(),
        .cnt0_o(i0_cnt0), .cnt1_o(i0_cnt1), .cnt2_o(i0_cnt2), .cnt3_o(i0_cnt3), .cnt4_o(i0_cnt4), .cnt5_o(i0_cnt5),
        .h0_o(i0_h0), .h1_o(i0_h1), .h2_o(i0_h2), .h3_o(i0_h3), .h4_o(i0_h4), .h5_o(i0_h5),
        .oq0_o(i0_oq0), .oq1_o(i0_oq1), .oq2_o(i0_oq2), .oq3_o(i0_oq3), .oq4_o(i0_oq4), .oq5_o(i0_oq5),
        .pfv0_o(i0_pfv0), .pfv1_o(i0_pfv1), .pfv2_o(i0_pfv2), .pfv3_o(i0_pfv3), .pfv4_o(i0_pfv4), .pfv5_o(i0_pfv5),
        .pfw0_o(i0_pfw0), .pfw1_o(i0_pfw1), .pfw2_o(i0_pfw2), .pfw3_o(i0_pfw3), .pfw4_o(i0_pfw4), .pfw5_o(i0_pfw5),
        .pool_obs(),
        .rdp0_o(i0_rdp0), .rdp1_o(i0_rdp1), .rdp2_o(i0_rdp2), .rdp3_o(i0_rdp3), .rdp4_o(i0_rdp4), .rdp5_o(i0_rdp5),
        .win0_o(i0_win0), .win1_o(i0_win1), .win2_o(i0_win2), .win3_o(i0_win3), .win4_o(i0_win4), .win5_o(i0_win5));

    xbar_route_pool p1 (.clk(clk), .rst_n(rst_n), .en(en[1]), .req(q1), .rel(rel[11:6]),
        .pool_o(i1_pool), .held_o(i1_held), .win_vec_o(), .vld_vec_o(),
        .cnt0_o(i1_cnt0), .cnt1_o(i1_cnt1), .cnt2_o(i1_cnt2), .cnt3_o(i1_cnt3), .cnt4_o(i1_cnt4), .cnt5_o(i1_cnt5),
        .h0_o(i1_h0), .h1_o(i1_h1), .h2_o(i1_h2), .h3_o(i1_h3), .h4_o(i1_h4), .h5_o(i1_h5),
        .oq0_o(i1_oq0), .oq1_o(i1_oq1), .oq2_o(i1_oq2), .oq3_o(i1_oq3), .oq4_o(i1_oq4), .oq5_o(i1_oq5),
        .pfv0_o(i1_pfv0), .pfv1_o(i1_pfv1), .pfv2_o(i1_pfv2), .pfv3_o(i1_pfv3), .pfv4_o(i1_pfv4), .pfv5_o(i1_pfv5),
        .pfw0_o(i1_pfw0), .pfw1_o(i1_pfw1), .pfw2_o(i1_pfw2), .pfw3_o(i1_pfw3), .pfw4_o(i1_pfw4), .pfw5_o(i1_pfw5),
        .pool_obs(),
        .rdp0_o(i1_rdp0), .rdp1_o(i1_rdp1), .rdp2_o(i1_rdp2), .rdp3_o(i1_rdp3), .rdp4_o(i1_rdp4), .rdp5_o(i1_rdp5),
        .win0_o(i1_win0), .win1_o(i1_win1), .win2_o(i1_win2), .win3_o(i1_win3), .win4_o(i1_win4), .win5_o(i1_win5));

    xbar_route_pool p2 (.clk(clk), .rst_n(rst_n), .en(en[2]), .req(q2), .rel(rel[17:12]),
        .pool_o(i2_pool), .held_o(i2_held), .win_vec_o(), .vld_vec_o(),
        .cnt0_o(i2_cnt0), .cnt1_o(i2_cnt1), .cnt2_o(i2_cnt2), .cnt3_o(i2_cnt3), .cnt4_o(i2_cnt4), .cnt5_o(i2_cnt5),
        .h0_o(i2_h0), .h1_o(i2_h1), .h2_o(i2_h2), .h3_o(i2_h3), .h4_o(i2_h4), .h5_o(i2_h5),
        .oq0_o(i2_oq0), .oq1_o(i2_oq1), .oq2_o(i2_oq2), .oq3_o(i2_oq3), .oq4_o(i2_oq4), .oq5_o(i2_oq5),
        .pfv0_o(i2_pfv0), .pfv1_o(i2_pfv1), .pfv2_o(i2_pfv2), .pfv3_o(i2_pfv3), .pfv4_o(i2_pfv4), .pfv5_o(i2_pfv5),
        .pfw0_o(i2_pfw0), .pfw1_o(i2_pfw1), .pfw2_o(i2_pfw2), .pfw3_o(i2_pfw3), .pfw4_o(i2_pfw4), .pfw5_o(i2_pfw5),
        .pool_obs(),
        .rdp0_o(i2_rdp0), .rdp1_o(i2_rdp1), .rdp2_o(i2_rdp2), .rdp3_o(i2_rdp3), .rdp4_o(i2_rdp4), .rdp5_o(i2_rdp5),
        .win0_o(i2_win0), .win1_o(i2_win1), .win2_o(i2_win2), .win3_o(i2_win3), .win4_o(i2_win4), .win5_o(i2_win5));

    xbar_route_pool p3 (.clk(clk), .rst_n(rst_n), .en(en[3]), .req(q3), .rel(rel[23:18]),
        .pool_o(i3_pool), .held_o(i3_held), .win_vec_o(), .vld_vec_o(),
        .cnt0_o(i3_cnt0), .cnt1_o(i3_cnt1), .cnt2_o(i3_cnt2), .cnt3_o(i3_cnt3), .cnt4_o(i3_cnt4), .cnt5_o(i3_cnt5),
        .h0_o(i3_h0), .h1_o(i3_h1), .h2_o(i3_h2), .h3_o(i3_h3), .h4_o(i3_h4), .h5_o(i3_h5),
        .oq0_o(i3_oq0), .oq1_o(i3_oq1), .oq2_o(i3_oq2), .oq3_o(i3_oq3), .oq4_o(i3_oq4), .oq5_o(i3_oq5),
        .pfv0_o(i3_pfv0), .pfv1_o(i3_pfv1), .pfv2_o(i3_pfv2), .pfv3_o(i3_pfv3), .pfv4_o(i3_pfv4), .pfv5_o(i3_pfv5),
        .pfw0_o(i3_pfw0), .pfw1_o(i3_pfw1), .pfw2_o(i3_pfw2), .pfw3_o(i3_pfw3), .pfw4_o(i3_pfw4), .pfw5_o(i3_pfw5),
        .pool_obs(),
        .rdp0_o(i3_rdp0), .rdp1_o(i3_rdp1), .rdp2_o(i3_rdp2), .rdp3_o(i3_rdp3), .rdp4_o(i3_rdp4), .rdp5_o(i3_rdp5),
        .win0_o(i3_win0), .win1_o(i3_win1), .win2_o(i3_win2), .win3_o(i3_win3), .win4_o(i3_win4), .win5_o(i3_win5));

    always @(posedge clk) begin
        if (!rst_n) begin
            spool <= TOTAL;
        end else begin
            spool <= spool - {3'b0, any_take} + {1'b0, n_give};
        end
    end

    always @(posedge clk)
        assert (spool <= TOTAL);

    assign spool_o = spool;
    assign ipool_o = {i3_pool, i2_pool, i1_pool, i0_pool};
    assign busy_o  = {(i3_held != 6'd0), (i2_held != 6'd0), (i1_held != 6'd0), (i0_held != 6'd0)};
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  dbg_stat
,
    output wire [3:0] cnt_o,
    output wire half_beat_o,
    output wire [2:0] rd_ptr_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg [7:0]  n_start;
reg [7:0]  n_stop;
reg [15:0] n_words;
reg [15:0] en_cyc;
reg [7:0]  win_len;
reg [7:0]  max_win;
reg        wrap_seen;
reg        half_beat;

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
n_start   = 8'd0;
n_stop    = 8'd0;
n_words   = 16'd0;
en_cyc    = 16'd0;
win_len   = 8'd0;
max_win   = 8'd0;
wrap_seen = 1'b0;
half_beat = 1'b0;
dbg_stat  = 32'h0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
n_start   <= 8'd0;
n_stop    <= 8'd0;
n_words   <= 16'd0;
en_cyc    <= 16'd0;
win_len   <= 8'd0;
max_win   <= 8'd0;
wrap_seen <= 1'b0;
half_beat <= 1'b0;
dbg_stat  <= 32'h0;
        end else if (en) begin
en_cyc <= en_cyc + 16'd1;
if (start && n_start != 8'hFF) n_start <= n_start + 8'd1;
if (stop && !start && n_stop != 8'hFF) n_stop <= n_stop + 8'd1;
if (!start && !stop && win) begin
    n_words <= n_words + 16'd1;
    if (rd_ptr == 3'd7) wrap_seen <= 1'b1;
    if (win_len != 8'hFF) win_len <= win_len + 8'd1;
end
if (start) win_len <= 8'd0;
if (win_len > max_win) max_win <= win_len;
dbg_stat <= {n_start[3:0], n_stop[3:0], max_win, n_words[11:0], wrap_seen, half_beat, en_cyc[1:0]};
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
half_beat <= 1'b0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
half_beat <= 1'b0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
if (half_beat) cnt <= cnt + 4'd2;
half_beat <= !half_beat;
                end
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
    assign cnt_o = cnt;
    assign half_beat_o = half_beat;
    assign rd_ptr_o = rd_ptr;
endmodule

module prbs_win_checker (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_bit,
    input  wire        i_arm,
    input  wire        i_disarm,
    output wire        o_sync,
    output wire [63:0] o_errs
,
    output wire [63:0] err_cnt_o,
    output wire [63:0] err_snap_o,
    output wire win_o,
    output wire [63:0] win_errs_o
);
    localparam [63:0] SYNC_LEN = 64'd8;
    localparam [63:0] LOSS_LEN = 64'd4;
    localparam [63:0] MAXV     = 64'hFFFFFFFFFFFFFFFF;

    reg [63:0] ref_sr;
    reg        sync;
    reg [63:0] match_run;
    reg [63:0] bad_run;
    reg [63:0] err_cnt;
    reg        win;
    reg [63:0] err_snap;
    reg [63:0] win_errs;

    initial ref_sr    = 64'h1;
    initial sync      = 1'b0;
    initial match_run = 64'd0;
    initial bad_run   = 64'd0;
    initial err_cnt   = 64'd0;
    initial win       = 1'b0;
    initial err_snap  = 64'd0;
    initial win_errs  = 64'd0;

    // PRBS x^64 + x^63 + x^61 + x^60 + 1 prediction
    wire        pred    = ref_sr[63] ^ ref_sr[62] ^ ref_sr[60] ^ ref_sr[59];
    wire        mism    = sync && (i_bit != pred);
    wire        cnt_inc = mism && (err_cnt != MAXV);
    wire [63:0] err_nxt = cnt_inc ? (err_cnt + 64'd1) : err_cnt;
    wire        lose    = mism && ((bad_run + 64'd1) >= LOSS_LEN);
    wire        open_w  = i_arm && sync && !lose && !i_disarm;
    wire        close_w = i_disarm || lose;

    always @(posedge clk) begin
        if (i_reset) begin
            ref_sr    <= 64'h1;
            sync      <= 1'b0;
            match_run <= 64'd0;
            bad_run   <= 64'd0;
            err_cnt   <= 64'd0;
            win       <= 1'b0;
            err_snap  <= 64'd0;
            win_errs  <= 64'd0;
        end else if (i_ce) begin
            err_cnt <= err_nxt;
            if (!sync) begin
                // self-synchronising: load incoming stream into reference
                ref_sr  <= {ref_sr[62:0], i_bit};
                bad_run <= 64'd0;
                if (i_bit == pred) begin
                    if ((match_run + 64'd1) >= SYNC_LEN) begin
                        sync      <= 1'b1;
                        match_run <= 64'd0;
                    end else begin
                        match_run <= match_run + 64'd1;
                    end
                end else begin
                    match_run <= 64'd0;
                end
            end else begin
                // locked: free-run the local reference
                ref_sr    <= {ref_sr[62:0], pred};
                match_run <= 64'd0;
                if (mism) begin
                    if (lose) begin
                        sync    <= 1'b0;
                        bad_run <= 64'd0;
                    end else begin
                        bad_run <= bad_run + 64'd1;
                    end
                end else begin
                    bad_run <= 64'd0;
                end
            end
            // measurement window: opened by arm while locked, closed by disarm or sync loss
            if (win) begin
                if (close_w) win <= 1'b0;
                if (cnt_inc) win_errs <= win_errs + 64'd1;
            end else if (open_w) begin
                win      <= 1'b1;
                err_snap <= err_nxt;
                win_errs <= 64'd0;
            end
        end
    end

    assign o_sync = sync;
    assign o_errs = err_cnt;

    // Precedence inside the window: a nonzero window tally requires the global
    // counter to have advanced past the snapshot recorded when the window opened.
    always @(*)
        if (win && (win_errs != 64'd0))
            assert (err_cnt != err_snap);

    // With no window errors, the global counter must still equal the snapshot.
    always @(*)
        if (win && (win_errs == 64'd0))
            assert (err_cnt == err_snap);
    assign err_cnt_o = err_cnt;
    assign err_snap_o = err_snap;
    assign win_o = win;
    assign win_errs_o = win_errs;
endmodule

module route_prbs_top (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    input  wire         ld,
    input  wire         step,
    input  wire         arm,
    input  wire         disarm,
    output wire [127:0] out_q,
    output wire         out_v,
    output wire [31:0]  dbg_stat,
    output wire         o_sync,
    output wire [63:0]  o_errs,
    output wire         win_o,
    output wire [8:0]   stg_o
,
    output wire [3:0] a_cnt_o,
    output wire a_half_beat_o,
    output wire [2:0] a_rd_ptr_o,
    output wire [63:0] b_err_cnt_o,
    output wire [63:0] b_err_snap_o,
    output wire b_win_o,
    output wire [63:0] b_win_errs_o,
    output wire [3:0] g_cnt_o,
    output wire g_hb_o,
    output wire g_pend_o,
    output wire [2:0] g_ptr_o
);
    wire [3:0]  a_cnt;
    wire        a_half_beat;
    wire [2:0]  a_rd_ptr;
    wire [63:0] b_err_cnt;
    wire [63:0] b_err_snap;
    wire        b_win;
    wire [63:0] b_win_errs;

    xbar_route_rom u_a (
        .clk(clk), .rst_n(rst_n), .en(en), .start(start), .stop(stop),
        .out_q(out_q), .out_v(out_v), .dbg_stat(dbg_stat),
        .cnt_o(a_cnt), .half_beat_o(a_half_beat), .rd_ptr_o(a_rd_ptr)
    );

    // beat staging register: latches the route cursor, then sequences it locally
    reg       g_v;
    reg [2:0] g_ptr;
    reg [3:0] g_cnt;
    reg       g_hb;
   // half-beat carry: registered on the odd beat, folded into g_cnt on the next advance
   reg       g_pend;

    initial begin
        g_v   = 1'b0;
        g_ptr = 3'd0;
        g_cnt = 4'd0;
        g_hb  = 1'b0;
       g_pend = 1'b0;
    end

    wire g_load = ld && out_v;
    wire g_adv  = step && g_v && !g_load;

    always @(posedge clk) begin
        if (!rst_n) begin
            g_v   <= 1'b0;
            g_ptr <= 3'd0;
            g_cnt <= 4'd0;
            g_hb  <= 1'b0;
           g_pend <= 1'b0;
        end else if (g_load) begin
            g_v   <= 1'b1;
            g_ptr <= a_rd_ptr;
            g_cnt <= a_cnt;
            g_hb  <= a_half_beat;
           g_pend <= 1'b0;
        end else if (g_adv) begin
            if (g_ptr == 3'd7) begin
                g_ptr <= 3'd0;
                g_cnt <= 4'd0;
                g_hb  <= 1'b0;
               g_pend <= 1'b0;
            end else begin
                g_ptr <= g_ptr + 3'd1;
               if (g_pend) g_cnt <= g_cnt + 4'd2;
                g_hb  <= !g_hb;
               g_pend <= g_hb;
            end
        end
    end

    wire stg_bit = g_ptr[0] ^ g_ptr[1] ^ g_ptr[2] ^ g_cnt[1] ^ g_cnt[2] ^ g_hb;
    wire b_ce    = g_adv;
    wire b_rst   = !rst_n;

    prbs_win_checker u_b (
        .clk(clk), .i_reset(b_rst), .i_ce(b_ce), .i_bit(stg_bit),
        .i_arm(arm), .i_disarm(disarm),
        .o_sync(o_sync), .o_errs(o_errs),
        .err_cnt_o(b_err_cnt), .err_snap_o(b_err_snap),
        .win_o(b_win), .win_errs_o(b_win_errs)
    );

    assign win_o = b_win;
    assign stg_o = {g_v, g_ptr, g_cnt, g_hb};

    // a staged cursor must always name a beat within the eight-entry route table
    always @(*)
        if (g_v)
            assert (g_cnt <= 4'd7);
    assign a_cnt_o = a_cnt;
    assign a_half_beat_o = a_half_beat;
    assign a_rd_ptr_o = a_rd_ptr;
    assign b_err_cnt_o = b_err_cnt;
    assign b_err_snap_o = b_err_snap;
    assign b_win_o = b_win;
    assign b_win_errs_o = b_win_errs;
    assign g_cnt_o = g_cnt;
    assign g_hb_o = g_hb;
    assign g_pend_o = g_pend;
    assign g_ptr_o = g_ptr;
endmodule

module route_prbs_pool (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [5:0]   en,
    input  wire [5:0]   start,
    input  wire [5:0]   stop,
    input  wire [5:0]   ld,
    input  wire [5:0]   step,
    input  wire [5:0]   arm,
    input  wire [5:0]   disarm,
    input  wire [5:0]   acq,
    input  wire [5:0]   rel,
    output wire [127:0] q_mix_o,
    output wire [63:0]  errs_mix_o,
    output wire [5:0]   out_v_o,
    output wire [5:0]   sync_o,
    output wire [5:0]   win_vec_o,
    output wire [53:0]  stg_vec_o,
    output wire [3:0]   pool_o,
    output wire [23:0]  held_o
);
    localparam [3:0] TOTAL = 4'd8;

    // shared lane-credit pool and per-lane holdings
    reg [3:0] pool;
    reg [3:0] h0, h1, h2, h3, h4, h5;

    initial begin
        pool = TOTAL;
        h0 = 4'd0; h1 = 4'd0; h2 = 4'd0;
        h3 = 4'd0; h4 = 4'd0; h5 = 4'd0;
    end

    wire [5:0] live    = {h5 != 4'd0, h4 != 4'd0, h3 != 4'd0, h2 != 4'd0, h1 != 4'd0, h0 != 4'd0};
    wire [5:0] run     = en & live;
    wire [5:0] acq_req = acq & {6{pool != 4'd0}};
    wire [5:0] ag      = acq_req & (~acq_req + 6'd1);
    wire [5:0] rel_ok  = rel & live;
    wire [5:0] rg      = rel_ok & (~rel_ok + 6'd1);
    wire       any_a   = |ag;
    wire       any_r   = |rg;

    always @(posedge clk) begin
        if (!rst_n) begin
            pool <= TOTAL;
            h0 <= 4'd0; h1 <= 4'd0; h2 <= 4'd0;
            h3 <= 4'd0; h4 <= 4'd0; h5 <= 4'd0;
        end else begin
            case ({any_a, any_r})
                2'b10:   pool <= pool - 4'd1;
                2'b01:   pool <= pool + 4'd1;
                default: pool <= pool;
            endcase
            h0 <= h0 + {3'b000, ag[0]} - {3'b000, rg[0]};
            h1 <= h1 + {3'b000, ag[1]} - {3'b000, rg[1]};
            h2 <= h2 + {3'b000, ag[2]} - {3'b000, rg[2]};
            h3 <= h3 + {3'b000, ag[3]} - {3'b000, rg[3]};
            h4 <= h4 + {3'b000, ag[4]} - {3'b000, rg[4]};
            h5 <= h5 + {3'b000, ag[5]} - {3'b000, rg[5]};
        end
    end

    // lane 0
    wire [127:0] q0; wire v0; wire s0; wire [63:0] e0; wire w0; wire [8:0] g0;
    wire [3:0] t0_a_cnt; wire t0_a_hb; wire [2:0] t0_a_rd_ptr;
    wire [63:0] t0_b_err_cnt; wire [63:0] t0_b_err_snap; wire [63:0] t0_b_win_errs; wire t0_b_win;
    wire [3:0] t0_g_cnt; wire t0_g_hb; wire t0_g_pend; wire [2:0] t0_g_ptr;
    route_prbs_top u0 (
        .clk(clk), .rst_n(rst_n), .en(run[0]), .start(start[0]), .stop(stop[0]),
        .ld(ld[0]), .step(step[0]), .arm(arm[0]), .disarm(disarm[0]),
        .out_q(q0), .out_v(v0), .dbg_stat(), .o_sync(s0), .o_errs(e0), .win_o(w0), .stg_o(g0),
        .a_cnt_o(t0_a_cnt), .a_half_beat_o(t0_a_hb), .a_rd_ptr_o(t0_a_rd_ptr),
        .b_err_cnt_o(t0_b_err_cnt), .b_err_snap_o(t0_b_err_snap), .b_win_o(t0_b_win), .b_win_errs_o(t0_b_win_errs),
        .g_cnt_o(t0_g_cnt), .g_hb_o(t0_g_hb), .g_pend_o(t0_g_pend), .g_ptr_o(t0_g_ptr)
    );

    // lane 1
    wire [127:0] q1; wire v1; wire s1; wire [63:0] e1; wire w1; wire [8:0] g1;
    wire [3:0] t1_a_cnt; wire t1_a_hb; wire [2:0] t1_a_rd_ptr;
    wire [63:0] t1_b_err_cnt; wire [63:0] t1_b_err_snap; wire [63:0] t1_b_win_errs; wire t1_b_win;
    wire [3:0] t1_g_cnt; wire t1_g_hb; wire t1_g_pend; wire [2:0] t1_g_ptr;
    route_prbs_top u1 (
        .clk(clk), .rst_n(rst_n), .en(run[1]), .start(start[1]), .stop(stop[1]),
        .ld(ld[1]), .step(step[1]), .arm(arm[1]), .disarm(disarm[1]),
