        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
S_ARMED: if (head_start) fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
bq_d0 <= 128'h0;
bq_d1 <= 128'h0;
bq_d2 <= 128'h0;
bq_d3 <= 128'h0;
bq_tag <= 4'h0;
bq_wp <= 2'd0;
bq_rp <= 2'd0;
bq_cnt <= 3'd0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
bq_tag <= 4'h0;
bq_wp <= 2'd0;
bq_rp <= 2'd0;
bq_cnt <= 3'd0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
if (bq_push && push_tag) started_seen <= 1'b1;
if (bq_pop) begin
bq_tag[bq_rp] <= 1'b0;
bq_rp <= bq_rp + 2'd1;
end
if (bq_push) begin
case (bq_wp)
2'd0: bq_d0 <= beat_data;
2'd1: bq_d1 <= beat_data;
2'd2: bq_d2 <= beat_data;
default: bq_d3 <= beat_data;
endcase
bq_tag[bq_wp] <= push_tag;
bq_wp <= bq_wp + 2'd1;
end
case ({bq_push, bq_pop})
2'b10: bq_cnt <= bq_cnt + 3'd1;
2'b01: bq_cnt <= bq_cnt - 3'd1;
default: bq_cnt <= bq_cnt;
endcase
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);

   always @(posedge clk)
       if (!rst) assert (!(fsm == S_ARMED && started_seen) || (bq_cnt != 3'd0));
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
,
    output wire armed_seen_o,
    output wire [1:0] fsm_o,
    output wire started_seen_o
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
    wire match1 = beat_valid && (((beat_data ^ wval1) & wmask1) == 128'h0);

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
            S_ARMED: if (match0)  fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
                if (fsm == S_ARMED && match0) started_seen <= 1'b1;
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
    assign armed_seen_o = armed_seen;
    assign fsm_o = fsm;
    assign started_seen_o = started_seen;
endmodule

module coyote_vfpga_bod (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire cmp_low,
    input wire clr,
    input wire sel_wr,
    input wire [1:0] sel_in,
    output wire slot_reset
,
    output wire bo_flag_o,
    output wire [15:0] deb_cnt_o,
    output wire [15:0] streak_o,
    output wire [15:0] thr_o
);
    reg [15:0] deb_cnt = 16'd0;
    reg [1:0]  thr_sel = 2'd0;
    reg        bo_flag = 1'b0;
    reg [15:0] streak  = 16'd0;
    reg        pv      = 1'b0;

    reg [15:0] thr;
    always @(*) begin
        case (thr_sel)
            2'd0: thr = 16'd4;
            2'd1: thr = 16'd16;
            2'd2: thr = 16'd256;
            default: thr = 16'd4096;
        endcase
    end

    wire [16:0] deb_inc    = {1'b0, deb_cnt} + 17'd1;
    wire [15:0] streak_inc = (streak == 16'hFFFF) ? 16'hFFFF : (streak + 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            deb_cnt <= 16'd0;
            thr_sel <= 2'd0;
            bo_flag <= 1'b0;
            streak  <= 16'd0;
        end else if (en) begin
            if (!cmp_low) begin
                deb_cnt <= 16'd0;
                streak  <= 16'd0;
            end else begin
                streak <= streak_inc;
                if (!bo_flag) begin
                    deb_cnt <= deb_inc[15:0];
                    if (deb_inc >= {1'b0, thr})
                        bo_flag <= 1'b1;
                end
            end
            if (clr) begin
                bo_flag <= 1'b0;
                deb_cnt <= 16'd0;
            end
            if (sel_wr && (deb_cnt == 16'd0))
                thr_sel <= sel_in;
        end
    end

    assign slot_reset = bo_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(bo_flag))
            assert (streak >= thr);
    assign bo_flag_o = bo_flag;
    assign deb_cnt_o = deb_cnt;
    assign streak_o = streak;
    assign thr_o = thr;
endmodule

module vbrk_bod_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en_a,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    input  wire         cap_en,
    input  wire         en_b,
    input  wire         bod_clr,
    input  wire         sel_wr,
    input  wire [1:0]   sel_in,
    output wire         done,
    output wire         slot_reset,
    output wire         brk_o,
output wire [15:0]  qual_cnt_o,
output reg  [31:0]  dbg_o,
output wire         wdt_o
);
    wire        done_a;
    wire        armed_seen_a;
    wire        started_seen_a;
    wire [1:0]  fsm_a;
    wire        bo_flag_b;
    wire [15:0] deb_cnt_b;
    wire [15:0] streak_b;
    wire [15:0] thr_b;
    wire        slot_reset_b;

    reg        brk_q    = 1'b0;
    reg        q_ok     = 1'b0;
    reg [15:0] qual_cnt = 16'd0;

   localparam [19:0] WDT_LIMIT = 20'd65535;

   reg [31:0] cyc_cnt;
   reg [31:0] beat_cnt;
   reg [15:0] wr0_cnt;
   reg [15:0] wr1_cnt;
   reg [15:0] arm_cnt;
   reg [15:0] clr_cnt;
   reg [15:0] hit_cnt;
   reg [15:0] sr_cnt;
   reg        done_d;
   reg        sr_d;
   reg [1:0]  fsm_d;
   reg [19:0] wdt_cnt;
   reg        wdt_to;
   reg [3:0]  err_bits;
   reg [2:0]  err_code;
   reg [31:0] err_ts;
   reg        err_valid;

   initial cyc_cnt   = 32'd0;
   initial beat_cnt  = 32'd0;
   initial wr0_cnt   = 16'd0;
   initial wr1_cnt   = 16'd0;
   initial arm_cnt   = 16'd0;
   initial clr_cnt   = 16'd0;
   initial hit_cnt   = 16'd0;
   initial sr_cnt    = 16'd0;
   initial done_d    = 1'b0;
   initial sr_d      = 1'b0;
   initial fsm_d     = 2'd0;
   initial wdt_cnt   = 20'd0;
   initial wdt_to    = 1'b0;
   initial err_bits  = 4'd0;
   initial err_code  = 3'd0;
   initial err_ts    = 32'd0;
   initial err_valid = 1'b0;
   initial dbg_o     = 32'd0;

   wire       dbg_fsm_busy  = (fsm_a == 2'd1) || (fsm_a == 2'd2);
   wire       dbg_fsm_move  = (fsm_a != fsm_d);
   wire       dbg_clr_a     = en_a && clr_cmd;
   wire       err_arm_busy  = en_a && arm_cmd && !clr_cmd && (fsm_a != 2'd0);
   wire       err_wr_busy   = en_a && wr_en && dbg_fsm_busy;
   wire       err_wdt       = dbg_fsm_busy && (wdt_cnt == WDT_LIMIT);
   wire       err_bod       = bod_clr && !en_b;
   wire [3:0] err_now       = {err_bod, err_wdt, err_wr_busy, err_arm_busy};
   wire [2:0] err_enc       = err_now[0] ? 3'd1 :
                              err_now[1] ? 3'd2 :
                              err_now[2] ? 3'd3 :
                              err_now[3] ? 3'd4 : 3'd0;
   wire       done_rise     = done_a && !done_d;
   wire       sr_rise       = slot_reset_b && !sr_d;

   reg [31:0] dbg_mux;
   always @(*) begin
       case ({wr_sel, sel_in})
           3'd0: dbg_mux = cyc_cnt;
           3'd1: dbg_mux = beat_cnt;
           3'd2: dbg_mux = {wr1_cnt, wr0_cnt};
           3'd3: dbg_mux = {arm_cnt, clr_cnt};
           3'd4: dbg_mux = {hit_cnt, sr_cnt};
           3'd5: dbg_mux = {err_valid, 3'd0, err_code, 1'b0, err_bits, wdt_to, wdt_cnt[18:0]};
           3'd6: dbg_mux = err_ts;
           default: dbg_mux = {thr_b, streak_b};
       endcase
   end

    vbrk_cmp u_cmp (
        .clk(clk),
        .rst(rst),
        .en(en_a),
        .beat_valid(beat_valid),
        .beat_data(beat_data),
        .wr_en(wr_en),
        .wr_sel(wr_sel),
        .wr_val(wr_val),
        .wr_mask(wr_mask),
        .arm_cmd(arm_cmd),
        .clr_cmd(clr_cmd),
        .done(done_a),
        .armed_seen_o(armed_seen_a),
        .fsm_o(fsm_a),
        .started_seen_o(started_seen_a)
    );

    coyote_vfpga_bod u_bod (
        .clk(clk),
        .rst_n(!rst),
        .en(en_b),
        .cmp_low(brk_q),
        .clr(bod_clr),
        .sel_wr(sel_wr),
        .sel_in(sel_in),
        .slot_reset(slot_reset_b),
        .bo_flag_o(bo_flag_b),
        .deb_cnt_o(deb_cnt_b),
        .streak_o(streak_b),
        .thr_o(thr_b)
    );

    wire brk_qualified = brk_q && q_ok;

    always @(posedge clk) begin
        if (rst) begin
            brk_q    <= 1'b0;
            q_ok     <= 1'b0;
            qual_cnt <= 16'd0;
           cyc_cnt   <= 32'd0;
           beat_cnt  <= 32'd0;
           wr0_cnt   <= 16'd0;
           wr1_cnt   <= 16'd0;
           arm_cnt   <= 16'd0;
           clr_cnt   <= 16'd0;
           hit_cnt   <= 16'd0;
           sr_cnt    <= 16'd0;
           done_d    <= 1'b0;
           sr_d      <= 1'b0;
           fsm_d     <= 2'd0;
           wdt_cnt   <= 20'd0;
           wdt_to    <= 1'b0;
           err_bits  <= 4'd0;
           err_code  <= 3'd0;
           err_ts    <= 32'd0;
           err_valid <= 1'b0;
           dbg_o     <= 32'd0;
        end else begin
            if (cap_en) begin
                brk_q <= done_a;
                q_ok  <= armed_seen_a && started_seen_a;
            end
            if (en_b) begin
                if (brk_qualified)
                    qual_cnt <= (qual_cnt == 16'hFFFF) ? 16'hFFFF : (qual_cnt + 16'd1);
                else
                    qual_cnt <= 16'd0;
            end
           cyc_cnt <= cyc_cnt + 32'd1;
           if (beat_valid && (beat_cnt != 32'hFFFFFFFF))
               beat_cnt <= beat_cnt + 32'd1;
           if (en_a && wr_en && !wr_sel && (wr0_cnt != 16'hFFFF))
               wr0_cnt <= wr0_cnt + 16'd1;
           if (en_a && wr_en && wr_sel && (wr1_cnt != 16'hFFFF))
               wr1_cnt <= wr1_cnt + 16'd1;
           if (en_a && arm_cmd && (arm_cnt != 16'hFFFF))
               arm_cnt <= arm_cnt + 16'd1;
           if (dbg_clr_a && (clr_cnt != 16'hFFFF))
               clr_cnt <= clr_cnt + 16'd1;
           done_d <= done_a;
           sr_d   <= slot_reset_b;
           fsm_d  <= fsm_a;
           if (done_rise && (hit_cnt != 16'hFFFF))
               hit_cnt <= hit_cnt + 16'd1;
           if (sr_rise && (sr_cnt != 16'hFFFF))
               sr_cnt <= sr_cnt + 16'd1;
           if (!dbg_fsm_busy || dbg_fsm_move || dbg_clr_a)
               wdt_cnt <= 20'd0;
           else if (wdt_cnt != WDT_LIMIT)
               wdt_cnt <= wdt_cnt + 20'd1;
           if (dbg_clr_a)
               wdt_to <= 1'b0;
           else if (err_wdt)
               wdt_to <= 1'b1;
           if (bod_clr && en_b) begin
               err_bits  <= 4'd0;
               err_code  <= 3'd0;
               err_ts    <= 32'd0;
               err_valid <= 1'b0;
           end else begin
               err_bits <= err_bits | err_now;
               if (!err_valid && (err_now != 4'd0)) begin
                   err_valid <= 1'b1;
                   err_code  <= err_enc;
                   err_ts    <= cyc_cnt;
               end
           end
           dbg_o <= dbg_mux;
        end
    end

    always @(posedge clk)
        assert (qual_cnt >= deb_cnt_b);

    assign done       = done_a;
    assign slot_reset = slot_reset_b;
    assign brk_o      = brk_q;
    assign qual_cnt_o = qual_cnt;
   assign wdt_o      = wdt_to;
endmodule

module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
    output reg rest_ack
,
    output wire [7:0] ramp_cnt_o
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;

    reg [7:0] ramp_cnt;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
                    end
                end
                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
                        ramp_ack <= 1'b1;
                        state <= S_REST;
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
    assign ramp_cnt_o = ramp_cnt;
endmodule

module tpu_dct_xpose (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [15:0] sample_in,
    output wire [15:0] acc_out
,
    output wire phase_o,
    output wire [15:0] rd_cnt_o,
    output wire [15:0] wr_cnt_o,
    output wire [15:0] wr_seen_o
);
    reg phase = 1'b0;
    reg [15:0] wr_cnt = 16'd0;
    reg [15:0] rd_cnt = 16'd0;
    reg [15:0] wr_seen = 16'd0;
    reg [15:0] acc = 16'd0;
    reg [15:0] coef_idx = 16'd0;
    reg [15:0] mem [0:23];
    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) mem[i] = 16'd0;
    end

    assign acc_out = acc;

    function [15:0] cosv;
        input [2:0] idx;
        begin
            case (idx)
                3'd0: cosv = 16'd23170;
                3'd1: cosv = 16'd32138;
                3'd2: cosv = 16'd30274;
                3'd3: cosv = 16'd27246;
                3'd4: cosv = 16'd23170;
                3'd5: cosv = 16'd18205;
                3'd6: cosv = 16'd12540;
                default: cosv = 16'd6393;
            endcase
        end
    endfunction

    wire [31:0] row_prod = sample_in * cosv(coef_idx[2:0]);
    wire [15:0] rd_word = (rd_cnt < 16'd24) ? mem[rd_cnt[4:0]] : 16'd0;
    wire [31:0] col_prod = rd_word * cosv(coef_idx[2:0]);

    always @(posedge clk) begin
        if (rst) begin
            phase <= 1'b0;
            wr_cnt <= 16'd0;
            rd_cnt <= 16'd0;
            wr_seen <= 16'd0;
            acc <= 16'd0;
            coef_idx <= 16'd0;
        end else if (en) begin
            if (!phase) begin
                if (wr_cnt == 16'd24) begin
                    phase <= 1'b1;
                    rd_cnt <= 16'd0;
                end else begin
                    if (wr_cnt < 16'd24) mem[wr_cnt[4:0]] <= row_prod[15:0];
                    wr_cnt <= wr_cnt + 16'd1;
                    wr_seen <= wr_cnt + 16'd1;
                    coef_idx <= coef_idx + 16'd1;
                end
            end else begin
                if (rd_cnt < 16'd24) begin
                    acc <= acc + col_prod[15:0];
                    rd_cnt <= rd_cnt + 16'd1;
                    coef_idx <= coef_idx + 16'd1;
                end else begin
                    phase <= 1'b0;
                    wr_cnt <= 16'd0;
                    wr_seen <= 16'd0;
                    rd_cnt <= 16'd0;
                    acc <= 16'd0;
                end
            end
        end
    end

    assert property (!phase || (rd_cnt <= wr_seen));
    assign phase_o = phase;
    assign rd_cnt_o = rd_cnt;
    assign wr_cnt_o = wr_cnt;
    assign wr_seen_o = wr_seen;
endmodule

module pg_dct_top (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    input wire dn_rdy,
    output wire [15:0] acc_out,
    output wire busy,
    output wire [15:0] xfer_o,
    output wire smp_pend
,
    output wire a_ramp_ack_o,
    output wire [7:0] a_ramp_cnt_o,
    output wire a_rest_ack_o,
    output wire a_save_ack_o,
    output wire [2:0] a_state_o,
    output wire a_win_o,
    output wire b_phase_o,
    output wire [15:0] b_rd_cnt_o,
    output wire [15:0] b_wr_cnt_o,
    output wire [15:0] b_wr_seen_o,
    output wire [15:0] smp_q_o,
    output wire [15:0] xfer_cnt_o
);
    wire a_win;
    wire [2:0] a_state;
    wire a_save_ack;
    wire a_ramp_ack;
    wire a_rest_ack;
    wire [7:0] a_ramp_cnt;

    wire b_phase;
    wire [15:0] b_rd_cnt;
    wire [15:0] b_wr_cnt;
    wire [15:0] b_wr_seen;
    wire [15:0] b_acc;

    reg [15:0] smp_q = 16'd0;
    reg smp_vld = 1'b0;
    reg [15:0] xfer_cnt = 16'd0;

    // A ramp step produces a new sample; B's write phase drains it when downstream is ready
    wire a_step = i_ce && (a_state == 3'd2);
    wire consume = smp_vld && dn_rdy && !b_phase && (b_wr_cnt != 16'd24);
    wire b_wrap = b_phase && (b_rd_cnt >= 16'd24);
    wire b_en = (smp_vld && dn_rdy) || b_phase || (b_wr_cnt == 16'd24);

    pg_seq u_seq (
        .clk(clk),
        .rst(rst),
        .i_ce(i_ce),
        .i_req(i_req),
        .win(a_win),
        .state(a_state),
        .save_ack(a_save_ack),
        .ramp_ack(a_ramp_ack),
        .rest_ack(a_rest_ack),
        .ramp_cnt_o(a_ramp_cnt)
    );

    tpu_dct_xpose u_dct (
        .clk(clk),
        .rst(rst),
        .en(b_en),
        .sample_in(smp_q),
        .acc_out(b_acc),
        .phase_o(b_phase),
        .rd_cnt_o(b_rd_cnt),
        .wr_cnt_o(b_wr_cnt),
        .wr_seen_o(b_wr_seen)
    );

    always @(posedge clk) begin
        if (rst) begin
            smp_q <= 16'd0;
            smp_vld <= 1'b0;
            xfer_cnt <= 16'd0;
        end else begin
            if (a_step) begin
                smp_q <= {8'd0, a_ramp_cnt};
                smp_vld <= 1'b1;
            end else if (consume) begin
                smp_vld <= 1'b0;
            end
            if (consume)
                xfer_cnt <= xfer_cnt + 16'd1;
            else if (b_wrap)
                xfer_cnt <= 16'd0;
        end
    end

    // A transpose read sweep only starts after a full block of ramp samples was delivered
    always @(posedge clk)
        if (b_phase)
            assert (xfer_cnt == 16'd24);

    assign acc_out = b_acc;
    assign busy = a_win || b_phase;
    assign xfer_o = xfer_cnt;
    assign smp_pend = smp_vld;
    assign a_ramp_ack_o = a_ramp_ack;
    assign a_ramp_cnt_o = a_ramp_cnt;
    assign a_rest_ack_o = a_rest_ack;
    assign a_save_ack_o = a_save_ack;
    assign a_state_o = a_state;
    assign a_win_o = a_win;
    assign b_phase_o = b_phase;
    assign b_rd_cnt_o = b_rd_cnt;
    assign b_wr_cnt_o = b_wr_cnt;
    assign b_wr_seen_o = b_wr_seen;
    assign smp_q_o = smp_q;
    assign xfer_cnt_o = xfer_cnt;
endmodule

module pg_pool_top (
    input wire clk,
    input wire rst,
    input wire [5:0] i_ce,
    input wire [5:0] i_req,
    input wire [5:0] dn_rdy,
    output wire [2:0] pool_o,
    output wire [5:0] hold_o,
    output wire [5:0] busy_o,
    output wire [15:0] acc_mix
);
    localparam [2:0] TOTAL = 3'd4;

    reg [2:0] pool = 3'd4;

    wire [2:0] st0, st1, st2, st3, st4, st5;
    wire win0, win1, win2, win3, win4, win5;
    wire sva0, sva1, sva2, sva3, sva4, sva5;
    wire rpa0, rpa1, rpa2, rpa3, rpa4, rpa5;
    wire rsa0, rsa1, rsa2, rsa3, rsa4, rsa5;
    wire [7:0] rc0, rc1, rc2, rc3, rc4, rc5;
    wire ph0, ph1, ph2, ph3, ph4, ph5;
    wire [15:0] rd0, rd1, rd2, rd3, rd4, rd5;
    wire [15:0] wc0, wc1, wc2, wc3, wc4, wc5;
    wire [15:0] ws0, ws1, ws2, ws3, ws4, ws5;
    wire [15:0] sq0, sq1, sq2, sq3, sq4, sq5;
    wire [15:0] xc0, xc1, xc2, xc3, xc4, xc5;
    wire [15:0] acc0, acc1, acc2, acc3, acc4, acc5;
    wire bz0, bz1, bz2, bz3, bz4, bz5;

    // an idle sequencer asking to enter a power-down window
    wire want0 = i_ce[0] && i_req[0] && (st0 == 3'd0);
    wire want1 = i_ce[1] && i_req[1] && (st1 == 3'd0);
    wire want2 = i_ce[2] && i_req[2] && (st2 == 3'd0);
    wire want3 = i_ce[3] && i_req[3] && (st3 == 3'd0);
    wire want4 = i_ce[4] && i_req[4] && (st4 == 3'd0);
    wire want5 = i_ce[5] && i_req[5] && (st5 == 3'd0);

    // fixed-priority grant, at most one new window per cycle, only while credits remain
    wire pool_ok = (pool != 3'd0);
    wire gnt0 = pool_ok && want0;
    wire gnt1 = pool_ok && want1 && !want0;
    wire gnt2 = pool_ok && want2 && !want0 && !want1;
    wire gnt3 = pool_ok && want3 && !want0 && !want1 && !want2;
    wire gnt4 = pool_ok && want4 && !want0 && !want1 && !want2 && !want3;
    wire gnt5 = pool_ok && want5 && !want0 && !want1 && !want2 && !want3 && !want4;
    wire acq_any = gnt0 || gnt1 || gnt2 || gnt3 || gnt4 || gnt5;

    // a window closes when the sequencer leaves DONE
    wire rel0 = i_ce[0] && (st0 == 3'd4);
    wire rel1 = i_ce[1] && (st1 == 3'd4);
    wire rel2 = i_ce[2] && (st2 == 3'd4);
    wire rel3 = i_ce[3] && (st3 == 3'd4);
    wire rel4 = i_ce[4] && (st4 == 3'd4);
    wire rel5 = i_ce[5] && (st5 == 3'd4);
    wire [2:0] rel_sum = {2'b0, rel0} + {2'b0, rel1} + {2'b0, rel2} + {2'b0, rel3} + {2'b0, rel4} + {2'b0, rel5};

    pg_dct_top u0 (.clk(clk), .rst(rst), .i_ce(i_ce[0]), .i_req(gnt0), .dn_rdy(dn_rdy[0]), .acc_out(acc0), .busy(bz0), .xfer_o(), .smp_pend(),
        .a_ramp_ack_o(rpa0), .a_ramp_cnt_o(rc0), .a_rest_ack_o(rsa0), .a_save_ack_o(sva0), .a_state_o(st0), .a_win_o(win0),
        .b_phase_o(ph0), .b_rd_cnt_o(rd0), .b_wr_cnt_o(wc0), .b_wr_seen_o(ws0), .smp_q_o(sq0), .xfer_cnt_o(xc0));
    pg_dct_top u1 (.clk(clk), .rst(rst), .i_ce(i_ce[1]), .i_req(gnt1), .dn_rdy(dn_rdy[1]), .acc_out(acc1), .busy(bz1), .xfer_o(), .smp_pend(),
        .a_ramp_ack_o(rpa1), .a_ramp_cnt_o(rc1), .a_rest_ack_o(rsa1), .a_save_ack_o(sva1), .a_state_o(st1), .a_win_o(win1),
        .b_phase_o(ph1), .b_rd_cnt_o(rd1), .b_wr_cnt_o(wc1), .b_wr_seen_o(ws1), .smp_q_o(sq1), .xfer_cnt_o(xc1));
    pg_dct_top u2 (.clk(clk), .rst(rst), .i_ce(i_ce[2]), .i_req(gnt2), .dn_rdy(dn_rdy[2]), .acc_out(acc2), .busy(bz2), .xfer_o(), .smp_pend(),
        .a_ramp_ack_o(rpa2), .a_ramp_cnt_o(rc2), .a_rest_ack_o(rsa2), .a_save_ack_o(sva2), .a_state_o(st2), .a_win_o(win2),
        .b_phase_o(ph2), .b_rd_cnt_o(rd2), .b_wr_cnt_o(wc2), .b_wr_seen_o(ws2), .smp_q_o(sq2), .xfer_cnt_o(xc2));
    pg_dct_top u3 (.clk(clk), .rst(rst), .i_ce(i_ce[3]), .i_req(gnt3), .dn_rdy(dn_rdy[3]), .acc_out(acc3), .busy(bz3), .xfer_o(), .smp_pend(),
        .a_ramp_ack_o(rpa3), .a_ramp_cnt_o(rc3), .a_rest_ack_o(rsa3), .a_save_ack_o(sva3), .a_state_o(st3), .a_win_o(win3),
        .b_phase_o(ph3), .b_rd_cnt_o(rd3), .b_wr_cnt_o(wc3), .b_wr_seen_o(ws3), .smp_q_o(sq3), .xfer_cnt_o(xc3));
    pg_dct_top u4 (.clk(clk), .rst(rst), .i_ce(i_ce[4]), .i_req(gnt4), .dn_rdy(dn_rdy[4]), .acc_out(acc4), .busy(bz4), .xfer_o(), .smp_pend(),
        .a_ramp_ack_o(rpa4), .a_ramp_cnt_o(rc4), .a_rest_ack_o(rsa4), .a_save_ack_o(sva4), .a_state_o(st4), .a_win_o(win4),
        .b_phase_o(ph4), .b_rd_cnt_o(rd4), .b_wr_cnt_o(wc4), .b_wr_seen_o(ws4), .smp_q_o(sq4), .xfer_cnt_o(xc4));
    pg_dct_top u5 (.clk(clk), .rst(rst), .i_ce(i_ce[5]), .i_req(gnt5), .dn_rdy(dn_rdy[5]), .acc_out(acc5), .busy(bz5), .xfer_o(), .smp_pend(),
        .a_ramp_ack_o(rpa5), .a_ramp_cnt_o(rc5), .a_rest_ack_o(rsa5), .a_save_ack_o(sva5), .a_state_o(st5), .a_win_o(win5),
        .b_phase_o(ph5), .b_rd_cnt_o(rd5), .b_wr_cnt_o(wc5), .b_wr_seen_o(ws5), .smp_q_o(sq5), .xfer_cnt_o(xc5));

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
        end else begin
            pool <= pool - {2'b0, acq_any} + rel_sum;
        end
    end

    // A fully returned budget means no power-down window is still open
    always @(posedge clk)
        if (pool == TOTAL)
            assert (!(win0 || win1 || win2 || win3 || win4 || win5));

    assign pool_o = pool;
    assign hold_o = {win5, win4, win3, win2, win1, win0};
    assign busy_o = {bz5, bz4, bz3, bz2, bz1, bz0};
    assign acc_mix = acc0 ^ acc1 ^ acc2 ^ acc3 ^ acc4 ^ acc5;
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;
localparam [1:0] OV_DEPTH = 2'd2;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;
reg [127:0] bq_d0, bq_d1, bq_d2, bq_d3;
reg [127:0] bq_head;
reg [3:0] bq_tag;
reg [1:0] bq_wp, bq_rp;
reg [2:0] bq_cnt;
reg [127:0] ov_d0, ov_d1;
reg [127:0] ov_head;
reg [1:0] ov_tag;
reg ov_wp, ov_rp;
reg [1:0] ov_cnt;
reg [127:0] bq_in_data;
reg bq_in_tag;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;
initial bq_d0 = 128'h0;
initial bq_d1 = 128'h0;
initial bq_d2 = 128'h0;
initial bq_d3 = 128'h0;
initial bq_tag = 4'h0;
initial bq_wp = 2'd0;
initial bq_rp = 2'd0;
initial bq_cnt = 3'd0;
initial ov_d0 = 128'h0;
initial ov_d1 = 128'h0;
initial ov_tag = 2'h0;
initial ov_wp = 1'b0;
initial ov_rp = 1'b0;
initial ov_cnt = 2'd0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
wire bq_empty = (bq_cnt == 3'd0);
wire bq_full = (bq_cnt >= 3'd4);
wire bq_pop = en && !clr_cmd && !bq_empty && (fsm != S_DONE);
wire bq_space = !bq_full || bq_pop;
wire ov_empty = (ov_cnt == 2'd0);
wire ov_full = (ov_cnt >= OV_DEPTH);
wire ov_drain = en && !clr_cmd && !ov_empty && bq_space;
wire beat_direct = en && !clr_cmd && beat_valid && ov_empty && bq_space;
wire ov_fill = en && !clr_cmd && beat_valid && !beat_direct && (!ov_full || ov_drain);
wire beat_accept = beat_direct || ov_fill;
wire bq_push = ov_drain || beat_direct;
wire push_tag = (fsm == S_ARMED) && match0;
wire start_drop = en && !clr_cmd && push_tag && !beat_accept;
wire head_start = bq_pop && bq_tag[bq_rp];
wire match1 = bq_pop && (((bq_head ^ wval1) & wmask1) == 128'h0);

always @(*) begin
case (bq_rp)
2'd0: bq_head = bq_d0;
2'd1: bq_head = bq_d1;
2'd2: bq_head = bq_d2;
default: bq_head = bq_d3;
endcase
end
always @(*) begin
case (ov_rp)
1'b0: ov_head = ov_d0;
default: ov_head = ov_d1;
endcase
end
always @(*) begin
if (ov_empty) begin
bq_in_data = beat_data;
bq_in_tag = push_tag;
end else begin
bq_in_data = ov_head;
bq_in_tag = ov_tag[ov_rp];
end
end

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
S_ARMED: if (start_drop && !started_seen) fsm_nxt = S_IDLE;
else if (head_start) fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
bq_d0 <= 128'h0;
bq_d1 <= 128'h0;
bq_d2 <= 128'h0;
bq_d3 <= 128'h0;
bq_tag <= 4'h0;
bq_wp <= 2'd0;
bq_rp <= 2'd0;
bq_cnt <= 3'd0;
ov_d0 <= 128'h0;
ov_d1 <= 128'h0;
ov_tag <= 2'h0;
ov_wp <= 1'b0;
ov_rp <= 1'b0;
ov_cnt <= 2'd0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
bq_tag <= 4'h0;
bq_wp <= 2'd0;
bq_rp <= 2'd0;
bq_cnt <= 3'd0;
ov_tag <= 2'h0;
ov_wp <= 1'b0;
ov_rp <= 1'b0;
ov_cnt <= 2'd0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
if (beat_accept && push_tag) started_seen <= 1'b1;
if (bq_pop) begin
bq_tag[bq_rp] <= 1'b0;
bq_rp <= bq_rp + 2'd1;
end
if (bq_push) begin
case (bq_wp)
2'd0: bq_d0 <= bq_in_data;
2'd1: bq_d1 <= bq_in_data;
2'd2: bq_d2 <= bq_in_data;
default: bq_d3 <= bq_in_data;
endcase
bq_tag[bq_wp] <= bq_in_tag;
bq_wp <= bq_wp + 2'd1;
end
if (ov_drain) begin
ov_tag[ov_rp] <= 1'b0;
ov_rp <= ov_rp + 1'b1;
end
if (ov_fill) begin
case (ov_wp)
1'b0: ov_d0 <= beat_data;
default: ov_d1 <= beat_data;
endcase
ov_tag[ov_wp] <= push_tag;
ov_wp <= ov_wp + 1'b1;
end
case ({ov_fill, ov_drain})
2'b10: ov_cnt <= ov_cnt + 2'd1;
2'b01: ov_cnt <= ov_cnt - 2'd1;
default: ov_cnt <= ov_cnt;
endcase
case ({bq_push, bq_pop})
2'b10: bq_cnt <= bq_cnt + 3'd1;
2'b01: bq_cnt <= bq_cnt - 3'd1;
default: bq_cnt <= bq_cnt;
endcase
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);

   always @(posedge clk)
       if (!rst) assert (!(fsm == S_ARMED && started_seen) || (bq_cnt != 3'd0));
endmodule

module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
    output reg rest_ack
,
    output wire [7:0] ramp_cnt_o
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;

    reg [7:0] ramp_cnt;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
                    end
                end
                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
                        ramp_ack <= 1'b1;
                        state <= S_REST;
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
    assign ramp_cnt_o = ramp_cnt;
endmodule

module pg_pool (
    input wire clk,
    input wire rst,
    input wire [5:0] ce,
    input wire [5:0] req,
    output wire [7:0] pool_o,
    output wire [5:0] win_o,
    output wire [5:0] done_o
,
    output wire [7:0] pool_obs,
    output wire ra0_o,
    output wire ra1_o,
    output wire ra2_o,
    output wire ra3_o,
    output wire ra4_o,
    output wire ra5_o,
    output wire [7:0] rc0_o,
    output wire [7:0] rc1_o,
    output wire [7:0] rc2_o,
    output wire [7:0] rc3_o,
    output wire [7:0] rc4_o,
    output wire [7:0] rc5_o,
    output wire rs0_o,
    output wire rs1_o,
    output wire rs2_o,
    output wire rs3_o,
    output wire rs4_o,
    output wire rs5_o,
    output wire sa0_o,
    output wire sa1_o,
    output wire sa2_o,
    output wire sa3_o,
    output wire sa4_o,
    output wire sa5_o,
    output wire [2:0] st0_o,
    output wire [2:0] st1_o,
    output wire [2:0] st2_o,
    output wire [2:0] st3_o,
    output wire [2:0] st4_o,
    output wire [2:0] st5_o,
    output wire w0_o,
    output wire w1_o,
    output wire w2_o,
    output wire w3_o,
    output wire w4_o,
    output wire w5_o
);
    localparam [7:0] TOTAL = 8'd3;

    reg [7:0] pool;
    initial pool = TOTAL;

    wire w0, w1, w2, w3, w4, w5;
    wire [2:0] st0, st1, st2, st3, st4, st5;
    wire sa0, sa1, sa2, sa3, sa4, sa5;
    wire ra0, ra1, ra2, ra3, ra4, ra5;
    wire rs0, rs1, rs2, rs3, rs4, rs5;
    wire [7:0] rc0, rc1, rc2, rc3, rc4, rc5;

    // idle instances asking to open a power-down window
    wire c0, c1, c2, c3, c4, c5;
    assign c0 = ce[0] && req[0] && (st0 == 3'd0);
    assign c1 = ce[1] && req[1] && (st1 == 3'd0);
    assign c2 = ce[2] && req[2] && (st2 == 3'd0);
    assign c3 = ce[3] && req[3] && (st3 == 3'd0);
    assign c4 = ce[4] && req[4] && (st4 == 3'd0);
    assign c5 = ce[5] && req[5] && (st5 == 3'd0);

    // fixed-priority arbiter, one grant per cycle while a credit is free
    wire avail;
    assign avail = (pool != 8'd0);
    wire g0, g1, g2, g3, g4, g5;
    assign g0 = avail && c0;
    assign g1 = avail && c1 && !c0;
    assign g2 = avail && c2 && !c0 && !c1;
    assign g3 = avail && c3 && !c0 && !c1 && !c2;
    assign g4 = avail && c4 && !c0 && !c1 && !c2 && !c3;
    assign g5 = avail && c5 && !c0 && !c1 && !c2 && !c3 && !c4;
    wire acq;
    assign acq = g0 | g1 | g2 | g3 | g4 | g5;

    // windows closing this cycle return their credit
    wire r0, r1, r2, r3, r4, r5;
    assign r0 = ce[0] && (st0 == 3'd4);
    assign r1 = ce[1] && (st1 == 3'd4);
    assign r2 = ce[2] && (st2 == 3'd4);
    assign r3 = ce[3] && (st3 == 3'd4);
    assign r4 = ce[4] && (st4 == 3'd4);
    assign r5 = ce[5] && (st5 == 3'd4);
    wire [7:0] rel_cnt;
    assign rel_cnt = {7'd0, r0} + {7'd0, r1} + {7'd0, r2} + {7'd0, r3} + {7'd0, r4} + {7'd0, r5};

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
        end else begin
            pool <= pool - {7'd0, acq} + rel_cnt;
        end
    end

    pg_seq u0 (.clk(clk), .rst(rst), .i_ce(ce[0]), .i_req(g0), .win(w0), .state(st0), .save_ack(sa0), .ramp_ack(ra0), .rest_ack(rs0), .ramp_cnt_o(rc0));
    pg_seq u1 (.clk(clk), .rst(rst), .i_ce(ce[1]), .i_req(g1), .win(w1), .state(st1), .save_ack(sa1), .ramp_ack(ra1), .rest_ack(rs1), .ramp_cnt_o(rc1));
    pg_seq u2 (.clk(clk), .rst(rst), .i_ce(ce[2]), .i_req(g2), .win(w2), .state(st2), .save_ack(sa2), .ramp_ack(ra2), .rest_ack(rs2), .ramp_cnt_o(rc2));
    pg_seq u3 (.clk(clk), .rst(rst), .i_ce(ce[3]), .i_req(g3), .win(w3), .state(st3), .save_ack(sa3), .ramp_ack(ra3), .rest_ack(rs3), .ramp_cnt_o(rc3));
    pg_seq u4 (.clk(clk), .rst(rst), .i_ce(ce[4]), .i_req(g4), .win(w4), .state(st4), .save_ack(sa4), .ramp_ack(ra4), .rest_ack(rs4), .ramp_cnt_o(rc4));
    pg_seq u5 (.clk(clk), .rst(rst), .i_ce(ce[5]), .i_req(g5), .win(w5), .state(st5), .save_ack(sa5), .ramp_ack(ra5), .rest_ack(rs5), .ramp_cnt_o(rc5));

    // the pool never holds more credits than it was provisioned with
    always @(posedge clk)
        assert (pool <= TOTAL);

    assign pool_o = pool;
    assign win_o = {w5, w4, w3, w2, w1, w0};
    assign done_o = {rs5, rs4, rs3, rs2, rs1, rs0};
    assign pool_obs = pool;
    assign ra0_o = ra0;
    assign ra1_o = ra1;
    assign ra2_o = ra2;
    assign ra3_o = ra3;
    assign ra4_o = ra4;
    assign ra5_o = ra5;
    assign rc0_o = rc0;
    assign rc1_o = rc1;
    assign rc2_o = rc2;
    assign rc3_o = rc3;
    assign rc4_o = rc4;
    assign rc5_o = rc5;
    assign rs0_o = rs0;
    assign rs1_o = rs1;
    assign rs2_o = rs2;
    assign rs3_o = rs3;
    assign rs4_o = rs4;
    assign rs5_o = rs5;
    assign sa0_o = sa0;
    assign sa1_o = sa1;
    assign sa2_o = sa2;
    assign sa3_o = sa3;
    assign sa4_o = sa4;
    assign sa5_o = sa5;
    assign st0_o = st0;
    assign st1_o = st1;
    assign st2_o = st2;
    assign st3_o = st3;
    assign st4_o = st4;
    assign st5_o = st5;
    assign w0_o = w0;
    assign w1_o = w1;
    assign w2_o = w2;
    assign w3_o = w3;
    assign w4_o = w4;
    assign w5_o = w5;
endmodule

module ctr_drbg_engine (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [1:0] cmd,
    input wire [31:0] entropy,
    output reg busy,
    output reg [31:0] out_data,
    output reg [31:0] reseed_ctr
,
    output wire [31:0] rnd_o,
    output wire [31:0] timer_o
);
    // cmd: 2'b01 instantiate, 2'b10 reseed, 2'b11 generate
    reg [31:0] key = 32'd0;
    reg [31:0] v = 32'd0;
    reg [31:0] timer = 32'd0;
    reg [31:0] rnd = 32'd0;
    reg [1:0] op = 2'b00;
    initial busy = 1'b0;
    initial out_data = 32'd0;
    initial reseed_ctr = 32'd0;

    always @(posedge clk) begin
        if (rst) begin
            key <= 32'd0;
            v <= 32'd0;
            timer <= 32'd0;
            rnd <= 32'd0;
            op <= 2'b00;
            busy <= 1'b0;
            out_data <= 32'd0;
            reseed_ctr <= 32'd0;
        end else if (ce) begin
            if (!busy) begin
                if (cmd != 2'b00) begin
                    busy <= 1'b1;
                    op <= cmd;
                    rnd <= 32'd0;
                    timer <= 32'd8;
                end
            end else begin
                v <= v + 32'd1;
                key <= {key[26:0], key[31:27]} ^ (v + 32'h9E3779B9) ^ ((op != 2'b11) ? entropy : 32'd0);
                rnd <= rnd + 32'd1;
                timer <= timer - 32'd1;
                if (rnd == 32'd5) begin
                    busy <= 1'b0;
                    timer <= 32'd0;
                    rnd <= 32'd0;
                    case (op)
                        2'b01: reseed_ctr <= 32'd1;
                        2'b10: reseed_ctr <= 32'd1;
                        2'b11: begin
                            reseed_ctr <= reseed_ctr + 32'd1;
                            out_data <= v ^ key;
                        end
                        default: reseed_ctr <= reseed_ctr;
                    endcase
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(busy)) assert ($past(timer) != 32'd0);
    assign rnd_o = rnd;
    assign timer_o = timer;
endmodule

module pg_drbg_top (
    input wire clk,
    input wire rst,
    input wire [5:0] ce,
    input wire [5:0] req,
    input wire d_ce,
    output wire [7:0] pool_o,
    output wire [5:0] win_o,
    output wire [5:0] done_o,
    output wire d_busy_o,
    output wire [31:0] d_out_o,
    output wire [31:0] d_reseed_o,
    output wire mb_valid_o,
    output wire [31:0] ent_o
);
    wire [7:0] pool;
    wire [7:0] pool_obs;
    wire [5:0] win_v;
    wire [5:0] done_v;
    wire w0, w1, w2, w3, w4, w5;
    wire [2:0] st0, st1, st2, st3, st4, st5;
    wire sa0, sa1, sa2, sa3, sa4, sa5;
    wire ra0, ra1, ra2, ra3, ra4, ra5;
    wire rs0, rs1, rs2, rs3, rs4, rs5;
    wire [7:0] rc0, rc1, rc2, rc3, rc4, rc5;

    pg_pool u_pool (
        .clk(clk), .rst(rst), .ce(ce), .req(req),
        .pool_o(pool), .win_o(win_v), .done_o(done_v), .pool_obs(pool_obs),
        .ra0_o(ra0), .ra1_o(ra1), .ra2_o(ra2), .ra3_o(ra3), .ra4_o(ra4), .ra5_o(ra5),
        .rc0_o(rc0), .rc1_o(rc1), .rc2_o(rc2), .rc3_o(rc3), .rc4_o(rc4), .rc5_o(rc5),
        .rs0_o(rs0), .rs1_o(rs1), .rs2_o(rs2), .rs3_o(rs3), .rs4_o(rs4), .rs5_o(rs5),
        .sa0_o(sa0), .sa1_o(sa1), .sa2_o(sa2), .sa3_o(sa3), .sa4_o(sa4), .sa5_o(sa5),
        .st0_o(st0), .st1_o(st1), .st2_o(st2), .st3_o(st3), .st4_o(st4), .st5_o(st5),
        .w0_o(w0), .w1_o(w1), .w2_o(w2), .w3_o(w3), .w4_o(w4), .w5_o(w5)
    );

    // power domains finishing their window this cycle
    wire [5:0] close_vec;
    assign close_vec = {ce[5] && (st5 == 3'd4), ce[4] && (st4 == 3'd4), ce[3] && (st3 == 3'd4),
                        ce[2] && (st2 == 3'd4), ce[1] && (st1 == 3'd4), ce[0] && (st0 == 3'd4)};
    wire close;
    assign close = |close_vec;

    // status mailbox toward the DRBG and the entropy word it is reseeding with
    reg mb_valid;
    reg [31:0] mb_data;
    reg [31:0] ent_q;
    initial begin
        mb_valid = 1'b0;
        mb_data = 32'd0;
        ent_q = 32'd0;
    end

    wire d_busy;
    wire [31:0] d_out;
    wire [31:0] d_reseed;
    wire [31:0] d_rnd;
    wire [31:0] d_timer;

    wire issue;
    assign issue = d_ce && !d_busy && mb_valid;
    wire [1:0] d_cmd;
    assign d_cmd = mb_valid ? 2'b10 : 2'b00;

    always @(posedge clk) begin
        if (rst) begin
            mb_valid <= 1'b0;
            mb_data <= 32'd0;
            ent_q <= 32'd0;
        end else begin
            if (issue) begin
                ent_q <= mb_data;
                mb_valid <= 1'b0;
            end else if (close && !mb_valid) begin
                mb_valid <= 1'b1;
                mb_data <= {8'h5A, 2'b00, close_vec, 8'd0, pool};
            end
        end
    end

    ctr_drbg_engine u_drbg (
        .clk(clk), .rst(rst), .ce(d_ce), .cmd(d_cmd), .entropy(ent_q),
        .busy(d_busy), .out_data(d_out), .reseed_ctr(d_reseed),
        .rnd_o(d_rnd), .timer_o(d_timer)
    );

    // while reseeding, the pool-level field of the entropy word is a legal credit count
    always @(posedge clk)
        if (d_busy)
            assert (ent_q[7:0] <= 8'd3);

    assign pool_o = pool;
    assign win_o = win_v;
    assign done_o = done_v;
    assign d_busy_o = d_busy;
    assign d_out_o = d_out;
    assign d_reseed_o = d_reseed;
    assign mb_valid_o = mb_valid;
    assign ent_o = ent_q;
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  stat_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg [15:0] start_cnt;
reg [15:0] stop_cnt;
reg [15:0] beat_cnt;
reg [7:0]  wrap_cnt;
reg [15:0] idle_cnt;
reg        err_sticky;
reg [1:0]  stat_sel;

    initial begin
start_cnt  = 16'd0;
stop_cnt   = 16'd0;
beat_cnt   = 16'd0;
wrap_cnt   = 8'd0;
idle_cnt   = 16'd0;
err_sticky = 1'b0;
stat_sel   = 2'd0;
stat_o     = 32'h0;
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
start_cnt  <= 16'd0;
stop_cnt   <= 16'd0;
beat_cnt   <= 16'd0;
wrap_cnt   <= 8'd0;
idle_cnt   <= 16'd0;
err_sticky <= 1'b0;
stat_sel   <= 2'd0;
stat_o     <= 32'h0;
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
if (start)
    start_cnt <= start_cnt + 16'd1;
if (stop)
    stop_cnt <= stop_cnt + 16'd1;
if (start && stop)
    err_sticky <= 1'b1;
if (win && !start && !stop) begin
    beat_cnt <= beat_cnt + 16'd1;
    if (rd_ptr == 3'd7)
        wrap_cnt <= wrap_cnt + 8'd1;
end
if (!win)
    idle_cnt <= idle_cnt + 16'd1;
stat_sel <= stat_sel + 2'd1;
case (stat_sel)
    2'd0: stat_o <= {start_cnt, stop_cnt};
    2'd1: stat_o <= {beat_cnt, idle_cnt};
    2'd2: stat_o <= {8'h0, wrap_cnt, 15'h0, err_sticky};
    default: stat_o <= {err_sticky, 7'h0, wrap_cnt, beat_cnt};
endcase
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                    cnt    <= cnt + 4'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
output reg rest_ack,
output reg vfy_busy,
output reg [2:0] vfy_cnt,
output reg [1:0] retry_cnt,
output reg [1:0] last_retry,
output reg retry_exh
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;
localparam [2:0] VFY_LAST = 3'd5;
localparam [1:0] RETRY_MAX = 2'd3;

    reg [7:0] ramp_cnt;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
vfy_busy = 1'b0; vfy_cnt = 3'd0;
retry_cnt = 2'd0; last_retry = 2'd0; retry_exh = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
vfy_busy <= 1'b0; vfy_cnt <= 3'd0;
retry_cnt <= 2'd0; last_retry <= 2'd0; retry_exh <= 1'b0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
retry_cnt <= 2'd0;
retry_exh <= 1'b0;
                    end
                end
                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
if (!vfy_busy) begin
vfy_busy <= 1'b1;
vfy_cnt <= 3'd0;
end
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
last_retry <= retry_cnt;
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
// Post-ramp rail verification. The rail must settle for VFY_LAST+1
// enabled cycles before the ramp is acknowledged. A request seen while
// settling means the saved context is stale: drop the save and redo it,
// up to RETRY_MAX times, after which the ramp is accepted and flagged.
if (vfy_busy) begin
if (i_req && retry_cnt != RETRY_MAX) begin
vfy_busy <= 1'b0;
retry_cnt <= retry_cnt + 2'd1;
save_ack <= 1'b0;
state <= S_SAVE;
end else begin
if (i_req)
retry_exh <= 1'b1;
if (vfy_cnt == VFY_LAST) begin
vfy_busy <= 1'b0;
ramp_ack <= 1'b1;
state <= S_REST;
end else begin
vfy_cnt <= vfy_cnt + 3'd1;
end
end
end
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
endmodule

module wormhole_route_unit #(
    parameter [63:0] MY_X = 64'd4,
    parameter [63:0] MY_Y = 64'd2
) (
    input  wire        clk,
    input  wire        in_valid,
    input  wire [1:0]  flit_type,
    input  wire [3:0]  in_ch,
    input  wire [63:0] dest_x,
    input  wire [63:0] dest_y,
    output reg  [2:0]  out_port,
output wire        out_fire,
output reg  [23:0] diag_status
);
    localparam [1:0] FT_BODY = 2'b00;
    localparam [1:0] FT_HEAD = 2'b01;
    localparam [1:0] FT_TAIL = 2'b10;

    localparam [2:0] P_LOCAL = 3'd0;
    localparam [2:0] P_EAST  = 3'd1;
    localparam [2:0] P_WEST  = 3'd2;
    localparam [2:0] P_NORTH = 3'd3;
    localparam [2:0] P_SOUTH = 3'd4;

    reg [15:0] route_valid;
    reg [47:0] route_port;
    reg [63:0] head_cnt;
    reg [63:0] body_cnt;
    reg        head_seen;
    reg        armed;

    initial begin
        route_valid = 16'd0;
        route_port  = 48'd0;
        head_cnt    = 64'd0;
        body_cnt    = 64'd0;
        head_seen   = 1'b0;
        armed       = 1'b1;
        out_port    = 3'd0;
    end

    wire ch_busy = route_valid[in_ch];
    wire do_head = in_valid && (flit_type == FT_HEAD) && !ch_busy;
    wire do_body = in_valid && (flit_type == FT_BODY) && ch_busy;
    wire do_tail = in_valid && (flit_type == FT_TAIL) && ch_busy;

    assign out_fire = do_head || do_body || do_tail;

    reg [2:0] calc_port;
    always @(*) begin
        if (dest_x > MY_X)      calc_port = P_EAST;
        else if (dest_x < MY_X) calc_port = P_WEST;
        else if (dest_y > MY_Y) calc_port = P_NORTH;
        else if (dest_y < MY_Y) calc_port = P_SOUTH;
        else                    calc_port = P_LOCAL;
    end

    wire [2:0] stored_port = route_port[in_ch*3 +: 3];
localparam [15:0] WDOG_LIMIT = 16'd1000;
reg [15:0] tail_cnt;
reg [15:0] err_cnt;
reg [3:0]  last_err_ch;
reg [1:0]  last_err_type;
reg [15:0] idle_cnt;
reg        wdog_trip;
reg [4:0]  port_hit;
initial begin
tail_cnt      = 16'd0;
err_cnt       = 16'd0;
last_err_ch   = 4'd0;
last_err_type = 2'd0;
idle_cnt      = 16'd0;
wdog_trip     = 1'b0;
port_hit      = 5'd0;
diag_status   = 24'd0;
end
wire err_head_busy = in_valid && (flit_type == FT_HEAD) && ch_busy;
wire err_orphan    = in_valid && ((flit_type == FT_BODY) || (flit_type == FT_TAIL)) && !ch_busy;
wire err_badtype   = in_valid && (flit_type == 2'b11);
wire any_err       = err_head_busy || err_orphan || err_badtype;
always @(posedge clk) begin
if (do_tail)
tail_cnt <= tail_cnt + 16'd1;
if (any_err) begin
if (err_cnt != 16'hFFFF)
err_cnt <= err_cnt + 16'd1;
last_err_ch   <= in_ch;
last_err_type <= flit_type;
end
if (out_fire)
idle_cnt <= 16'd0;
else if (idle_cnt != 16'hFFFF)
idle_cnt <= idle_cnt + 16'd1;
if (idle_cnt == WDOG_LIMIT)
wdog_trip <= 1'b1;
else if (out_fire)
wdog_trip <= 1'b0;
if (do_head)
port_hit <= port_hit | (5'd1 << calc_port);
diag_status <= {wdog_trip, port_hit, last_err_type, last_err_ch,
err_cnt[5:0], tail_cnt[5:0]};
end

    always @(posedge clk) begin
        if (do_head) begin
            route_valid[in_ch]         <= 1'b1;
            route_port[in_ch*3 +: 3]   <= calc_port;
            head_cnt                   <= head_cnt + 64'd1;
            head_seen                  <= 1'b1;
            out_port                   <= calc_port;
        end
        if (do_body) begin
            body_cnt <= body_cnt + 64'd1;
            out_port <= stored_port;
        end
        if (do_tail) begin
            route_valid[in_ch] <= 1'b0;
            armed              <= 1'b0;
            out_port           <= stored_port;
        end
    end

    always @(*) assert (!armed || (body_cnt == 64'd0) || head_seen);
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
output reg         fault,
output reg  [3:0]  n_acc_in,   // accesses accepted into the lookup stage
output reg  [3:0]  n_acc_out   // accesses retired from the lookup stage
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;
initial n_acc_in  = 4'd0;
initial n_acc_out = 4'd0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
// a hit retiring while the ledger shows nothing outstanding is a spurious response
fault  <= miss_q || (hit_q && (n_acc_in == n_acc_out));
if (acc_valid)
    n_acc_in <= n_acc_in + 4'd1;
if (hit_q || miss_q)
    n_acc_out <= n_acc_out + 4'd1;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
   output reg          done,
   output reg  [127:0] trig_data,
   output wire         bq_full
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;
   reg [127:0] bq_d0, bq_d1, bq_d2, bq_d3;
   reg [3:0] bq_vld, bq_t0, bq_t1;
   reg [1:0] bq_wp, bq_rp;
   reg [127:0] bq_head;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;
   initial trig_data = 128'h0;
   initial bq_d0 = 128'h0;
   initial bq_d1 = 128'h0;
   initial bq_d2 = 128'h0;
   initial bq_d3 = 128'h0;
   initial bq_vld = 4'h0;
   initial bq_t0 = 4'h0;
   initial bq_t1 = 4'h0;
   initial bq_wp = 2'd0;
   initial bq_rp = 2'd0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
    wire match1 = beat_valid && (((beat_data ^ wval1) & wmask1) == 128'h0);
   wire bq_live  = (fsm == S_ARMED) || (fsm == S_RUN);
   wire bq_push  = bq_live && (match0 || match1) && !bq_vld[bq_wp];
   wire bq_pop   = bq_vld[bq_rp];
   wire bq_hd_t0 = bq_t0[bq_rp];
   wire bq_hd_t1 = bq_t1[bq_rp];
   assign bq_full = &bq_vld;
   always @(*)
       case (bq_rp)
           2'd0: bq_head = bq_d0;
           2'd1: bq_head = bq_d1;
           2'd2: bq_head = bq_d2;
           default: bq_head = bq_d3;
       endcase

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
           S_ARMED: if (bq_pop && bq_hd_t0) fsm_nxt = S_RUN;
           S_RUN:   if (bq_pop && bq_hd_t1) fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
           trig_data <= 128'h0;
           bq_d0 <= 128'h0;
           bq_d1 <= 128'h0;
           bq_d2 <= 128'h0;
           bq_d3 <= 128'h0;
           bq_vld <= 4'h0;
           bq_t0 <= 4'h0;
           bq_t1 <= 4'h0;
           bq_wp <= 2'd0;
           bq_rp <= 2'd0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
               bq_vld <= 4'h0;
               bq_wp <= 2'd0;
               bq_rp <= 2'd0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
               if (fsm == S_ARMED && bq_push && match0) started_seen <= 1'b1;
               if (bq_pop) begin
                   bq_vld[bq_rp] <= 1'b0;
                   bq_rp <= bq_rp + 2'd1;
                   if (fsm == S_RUN && bq_hd_t1) trig_data <= bq_head;
               end
               if (bq_push) begin
                   bq_vld[bq_wp] <= 1'b1;
                   bq_t0[bq_wp] <= match0;
                   bq_t1[bq_wp] <= match1;
                   bq_wp <= bq_wp + 2'd1;
                   case (bq_wp)
                       2'd0: bq_d0 <= beat_data;
                       2'd1: bq_d1 <= beat_data;
                       2'd2: bq_d2 <= beat_data;
                       default: bq_d3 <= beat_data;
                   endcase
               end
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
output reg         fault,
output reg  [3:0]  n_acc_in,   // accesses accepted into the lookup stage
output reg  [3:0]  n_acc_out,  // accesses retired from the lookup stage (committed in pairs)
output reg         ret_pend    // one retirement banked, not yet committed to n_acc_out
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;
initial n_acc_in  = 4'd0;
initial n_acc_out = 4'd0;
initial ret_pend  = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
// a hit retiring while the ledger shows nothing outstanding is a spurious response
fault  <= miss_q || (hit_q && (n_acc_in == (n_acc_out + {3'd0, ret_pend})));
if (acc_valid)
    n_acc_in <= n_acc_in + 4'd1;
// retirements are banked in a half-slot and committed to the ledger in pairs;
// an idle cycle flushes a lone banked retirement
if (hit_q || miss_q) begin
    if (ret_pend) begin
        n_acc_out <= n_acc_out + 4'd2;
        ret_pend  <= 1'b0;
    end else
        ret_pend  <= 1'b1;
end else if (ret_pend) begin
    n_acc_out <= n_acc_out + 4'd1;
    ret_pend  <= 1'b0;
end
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  stat_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg [15:0] start_cnt;
reg [15:0] stop_cnt;
reg [15:0] beat_cnt;
reg [7:0]  wrap_cnt;
reg [15:0] idle_cnt;
reg        err_sticky;
reg [1:0]  stat_sel;
reg [127:0] pf_data [0:3];
reg [3:0]   pf_tag  [0:3];
reg [1:0]   pf_wp;
reg [1:0]   pf_rp;
reg [2:0]   pf_used;

    initial begin
start_cnt  = 16'd0;
stop_cnt   = 16'd0;
beat_cnt   = 16'd0;
wrap_cnt   = 8'd0;
idle_cnt   = 16'd0;
err_sticky = 1'b0;
stat_sel   = 2'd0;
stat_o     = 32'h0;
pf_data[0] = 128'h0;
pf_data[1] = 128'h0;
pf_data[2] = 128'h0;
pf_data[3] = 128'h0;
pf_tag[0]  = 4'd0;
pf_tag[1]  = 4'd0;
pf_tag[2]  = 4'd0;
pf_tag[3]  = 4'd0;
pf_wp      = 2'd0;
pf_rp      = 2'd0;
pf_used    = 3'd0;
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end
   // shared crossbar lane: this source owns the even arbitration slots
   wire       slot_gnt    = ~stat_sel[0];
   wire       pf_full     = (pf_used == 3'd4);
   wire       pf_empty    = (pf_used == 3'd0);
   wire       pf_push     = win && !pf_full;
   wire       pf_pop      = win && !pf_empty && slot_gnt;
   wire [3:0] pf_head_tag = pf_tag[pf_rp];
   wire       pf_last     = (pf_head_tag == 4'd7);

    always @(posedge clk) begin
        if (!rst_n) begin
start_cnt  <= 16'd0;
stop_cnt   <= 16'd0;
beat_cnt   <= 16'd0;
wrap_cnt   <= 8'd0;
idle_cnt   <= 16'd0;
err_sticky <= 1'b0;
stat_sel   <= 2'd0;
stat_o     <= 32'h0;
pf_data[0] <= 128'h0;
pf_data[1] <= 128'h0;
pf_data[2] <= 128'h0;
pf_data[3] <= 128'h0;
pf_tag[0]  <= 4'd0;
pf_tag[1]  <= 4'd0;
pf_tag[2]  <= 4'd0;
pf_tag[3]  <= 4'd0;
pf_wp      <= 2'd0;
pf_rp      <= 2'd0;
pf_used    <= 3'd0;
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
if (start)
    start_cnt <= start_cnt + 16'd1;
if (stop)
    stop_cnt <= stop_cnt + 16'd1;
if (start && stop)
    err_sticky <= 1'b1;
if (win && !start && !stop) begin
    beat_cnt <= beat_cnt + 16'd1;
   if (pf_pop && pf_last)
        wrap_cnt <= wrap_cnt + 8'd1;
end
if (!win)
    idle_cnt <= idle_cnt + 16'd1;
stat_sel <= stat_sel + 2'd1;
case (stat_sel)
    2'd0: stat_o <= {start_cnt, stop_cnt};
    2'd1: stat_o <= {beat_cnt, idle_cnt};
   2'd2: stat_o <= {5'h0, pf_used, wrap_cnt, 15'h0, err_sticky};
    default: stat_o <= {err_sticky, 7'h0, wrap_cnt, beat_cnt};
endcase
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
               pf_wp   <= 2'd0;
               pf_rp   <= 2'd0;
               pf_used <= 3'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
               if (pf_push) begin
                   pf_data[pf_wp] <= rom_word;
                   pf_tag[pf_wp]  <= {1'b0, rd_ptr};
                   pf_wp          <= pf_wp + 2'd1;
                   rd_ptr         <= rd_ptr + 3'd1;
               end
               if (pf_pop) begin
                   out_q <= pf_data[pf_rp];
                   out_v <= 1'b1;
                   pf_rp <= pf_rp + 2'd1;
                   if (pf_last)
                       cnt <= 4'd0;
                   else
                       cnt <= cnt + 4'd1;
               end
               case ({pf_push, pf_pop})
                   2'b10:   pf_used <= pf_used + 3'd1;
                   2'b01:   pf_used <= pf_used - 3'd1;
                   default: pf_used <= pf_used;
               endcase
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
output reg rest_ack,
output reg vfy_busy,
output reg [2:0] vfy_cnt,
output reg [1:0] retry_cnt,
output reg [1:0] last_retry,
output reg retry_exh
,
    output wire [7:0] ramp_cnt_o
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;
localparam [2:0] VFY_LAST = 3'd5;
localparam [1:0] RETRY_MAX = 2'd3;

    reg [7:0] ramp_cnt;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
vfy_busy = 1'b0; vfy_cnt = 3'd0;
retry_cnt = 2'd0; last_retry = 2'd0; retry_exh = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
vfy_busy <= 1'b0; vfy_cnt <= 3'd0;
retry_cnt <= 2'd0; last_retry <= 2'd0; retry_exh <= 1'b0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
retry_cnt <= 2'd0;
retry_exh <= 1'b0;
                    end
                end
                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
if (!vfy_busy) begin
vfy_busy <= 1'b1;
vfy_cnt <= 3'd0;
end
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
last_retry <= retry_cnt;
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
// Post-ramp rail verification. The rail must settle for VFY_LAST+1
// enabled cycles before the ramp is acknowledged. A request seen while
// settling means the saved context is stale: drop the save and redo it,
// up to RETRY_MAX times, after which the ramp is accepted and flagged.
if (vfy_busy) begin
if (i_req && retry_cnt != RETRY_MAX) begin
vfy_busy <= 1'b0;
retry_cnt <= retry_cnt + 2'd1;
save_ack <= 1'b0;
state <= S_SAVE;
end else begin
if (i_req)
retry_exh <= 1'b1;
if (vfy_cnt == VFY_LAST) begin
vfy_busy <= 1'b0;
ramp_ack <= 1'b1;
state <= S_REST;
end else begin
vfy_cnt <= vfy_cnt + 3'd1;
end
end
end
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
    assign ramp_cnt_o = ramp_cnt;
endmodule

module pg_seq_pool (
    input wire clk,
    input wire rst,
    input wire [5:0] i_ce,
    input wire [5:0] i_req,
    output wire [2:0] pool_o,
    output wire [5:0] gnt_o,
    output wire [5:0] win_o,
    output wire [17:0] state_o,
    output wire [5:0] save_ack_o,
    output wire [5:0] ramp_ack_o,
    output wire [5:0] rest_ack_o,
    output wire [5:0] vfy_busy_o,
    output wire [17:0] vfy_cnt_o,
    output wire [11:0] retry_cnt_o,
    output wire [11:0] last_retry_o,
    output wire [5:0] retry_exh_o,
    output wire [47:0] ramp_cnt_o
);
    // Shared power-down budget: at most TOTAL rails may be in a window at once.
    localparam [2:0] TOTAL = 3'd4;

    reg [2:0] pool;
    initial pool = TOTAL;

    wire win_t0, win_t1, win_t2, win_t3, win_t4, win_t5;
    wire [2:0] state_t0, state_t1, state_t2, state_t3, state_t4, state_t5;
    wire save_t0, save_t1, save_t2, save_t3, save_t4, save_t5;
    wire ramp_t0, ramp_t1, ramp_t2, ramp_t3, ramp_t4, ramp_t5;
    wire rest_t0, rest_t1, rest_t2, rest_t3, rest_t4, rest_t5;
    wire vbusy_t0, vbusy_t1, vbusy_t2, vbusy_t3, vbusy_t4, vbusy_t5;
    wire [2:0] vcnt_t0, vcnt_t1, vcnt_t2, vcnt_t3, vcnt_t4, vcnt_t5;
    wire [1:0] rcnt_t0, rcnt_t1, rcnt_t2, rcnt_t3, rcnt_t4, rcnt_t5;
    wire [1:0] lretry_t0, lretry_t1, lretry_t2, lretry_t3, lretry_t4, lretry_t5;
    wire rexh_t0, rexh_t1, rexh_t2, rexh_t3, rexh_t4, rexh_t5;
    wire [7:0] rampc_t0, rampc_t1, rampc_t2, rampc_t3, rampc_t4, rampc_t5;

    wire [5:0] w = {win_t5, win_t4, win_t3, win_t2, win_t1, win_t0};
    wire [5:0] done = {(state_t5 == 3'd4), (state_t4 == 3'd4), (state_t3 == 3'd4),
                       (state_t2 == 3'd4), (state_t1 == 3'd4), (state_t0 == 3'd4)};

    // Idle sequencers asking to enter a window; lowest index wins a free credit.
    wire [5:0] cand = ~w & i_req & i_ce;
    wire [5:0] gnt = (pool != 3'd0) ? (cand & (~cand + 6'd1)) : 6'd0;
    // A sequencer leaving S_DONE hands its credit back.
    wire [5:0] rel = w & done & i_ce;
    // Requests inside a window are retry requests and always pass through.
    wire [5:0] req_g = i_req & (w | gnt);

    wire [3:0] pool_n = {1'b0, pool}
                      + {3'b000, rel[0]} + {3'b000, rel[1]} + {3'b000, rel[2]}
                      + {3'b000, rel[3]} + {3'b000, rel[4]} + {3'b000, rel[5]}
                      - {3'b000, (|gnt)};

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
        end else begin
            pool <= pool_n[2:0];
        end
    end

    // A full pool means no rail is inside a power-down window.
    always @(posedge clk)
        if (pool == 3'd4)
            assert (w == 6'd0);

