pf_data[1] = 128'h0;
pf_data[2] = 128'h0;
pf_data[3] = 128'h0;
pf_tag[0]  = 4'd0;
pf_tag[1]  = 4'd0;
pf_tag[2]  = 4'd0;
pf_tag[3]  = 4'd0;
pf_wp      = 2'd0;
pf_rp      = 2'd0;
pf_used    = 3'd0;
eq_data[0] = 128'h0;
eq_data[1] = 128'h0;
eq_tag[0]  = 4'd0;
eq_tag[1]  = 4'd0;
eq_wp      = 1'b0;
eq_rp      = 1'b0;
eq_used    = 2'd0;
stall_cnt  = 16'd0;
out_tag    = 3'd0;
out_last   = 1'b0;
out_par    = 1'b0;
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
