                win <= 1'b0;
            end else if (win) begin
               if (pf_push) begin
                   pf_data[pf_wp] <= rom_word;
                   pf_tag[pf_wp]  <= {1'b0, rd_ptr};
                   pf_wp          <= pf_wp + 2'd1;
                   rd_ptr         <= rd_ptr + 3'd1;
               end
               if (pf_pop) begin
