            pool <= TOTAL;
           cr_issued <= 4'd0;
           cr_returned <= 4'd0;
        end else begin
            pool <= pool_n[2:0];
           cr_issued <= cr_issued + {3'b000, (|gnt)};
           cr_returned <= cr_returned + {1'b0, rel_cnt};
