                    rd_ptr <= 3'd0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                end
            end
        end
if (rst_n) begin
if (en) begin
if (start)
start_cnt <= start_cnt + 8'd1;
if (stop)
stop_cnt <= stop_cnt + 8'd1;
if (start && stop)
err_flag <= 1'b1;
if (start || win)
idle_wdog <= 12'd0;
else if (idle_wdog != 12'hFFF)
idle_wdog <= idle_wdog + 12'd1;
if (idle_wdog == 12'hFFE)
wdog_flag <= 1'b1;
if (start)
last_tag <= 3'd7;
if (win && !start && !stop && st3_v) begin
beat_cnt <= beat_cnt + 16'd1;
csum     <= {csum[14:0], csum[15]} ^ st3_q[15:0] ^ st3_q[127:112];
last_tag <= st3_idx;
if (st3_idx != last_tag + 3'd1)
seq_err <= 1'b1;
end
end
dbg_stat <= {wdog_flag, err_flag, seq_err, idle_wdog[4:0], start_cnt ^ stop_cnt, beat_cnt ^ csum};
end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
output reg rest_ack,
output reg [15:0] dbg_status,
output reg [2:0] state_b,
output reg save_ack_b,
output reg ramp_ack_b,
output reg rest_ack_b,
output reg [7:0] rail_stall_cnt
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;
localparam [7:0] WDOG_LIMIT = 8'd24;

    reg [7:0] ramp_cnt;
reg [7:0] req_total;
reg [7:0] busy_cycles;
reg [7:0] wdog_cnt;
reg wdog_trip;
reg overlap_err;
reg [3:0] overlap_cnt;
reg [3:0] done_cnt;
reg [3:0] ramp_seen;
reg rail_busy;
reg rail_owner;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
req_total = 8'd0; busy_cycles = 8'd0;
wdog_cnt = 8'd0; wdog_trip = 1'b0;
overlap_err = 1'b0; overlap_cnt = 4'd0;
done_cnt = 4'd0; ramp_seen = 4'd0;
dbg_status = 16'd0;
state_b = S_IDLE;
save_ack_b = 1'b0; ramp_ack_b = 1'b0; rest_ack_b = 1'b0;
rail_busy = 1'b0; rail_owner = 1'b0;
rail_stall_cnt = 8'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
req_total <= 8'd0; busy_cycles <= 8'd0;
wdog_cnt <= 8'd0; wdog_trip <= 1'b0;
overlap_err <= 1'b0; overlap_cnt <= 4'd0;
done_cnt <= 4'd0; ramp_seen <= 4'd0;
dbg_status <= 16'd0;
state_b <= S_IDLE;
save_ack_b <= 1'b0; ramp_ack_b <= 1'b0; rest_ack_b <= 1'b0;
rail_busy <= 1'b0; rail_owner <= 1'b0;
rail_stall_cnt <= 8'd0;
        end else if (i_ce) begin
if ((state == S_IDLE) && i_req && (req_total != 8'hFF))
req_total <= req_total + 8'd1;
if (win && (busy_cycles != 8'hFF))
busy_cycles <= busy_cycles + 8'd1;
if ((state != S_IDLE) && (state_b != S_IDLE) && i_req) begin
overlap_err <= 1'b1;
if (overlap_cnt != 4'hF)
overlap_cnt <= overlap_cnt + 4'd1;
end
if (state == S_IDLE) begin
wdog_cnt <= 8'd0;
end else if (wdog_cnt == WDOG_LIMIT) begin
wdog_trip <= 1'b1;
end else begin
wdog_cnt <= wdog_cnt + 8'd1;
end
if (state == S_DONE)
done_cnt <= done_cnt + 4'd1;
if ((state == S_RAMP) && (ramp_cnt == RAMP_LAST))
ramp_seen <= ramp_seen + 4'd1;
dbg_status <= {wdog_trip, overlap_err, done_cnt[1:0] ^ ramp_seen[1:0],
req_total[3:0] ^ overlap_cnt, busy_cycles ^ wdog_cnt};
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
                    end
                end
                S_SAVE: begin
                    if (!rail_busy) begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                        rail_busy <= 1'b1;
                        rail_owner <= 1'b0;
                    state <= S_RAMP;
                    end else if (rail_stall_cnt != 8'hFF) begin
                        rail_stall_cnt <= rail_stall_cnt + 8'd1;
                    end
                end
                S_RAMP: begin
                    if (ramp_ack)
                        state <= S_REST;
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
            // Second power domain: takes requests that arrive while domain A is busy
            case (state_b)
                S_IDLE: begin
                    if (i_req && (state != S_IDLE)) begin
                        state_b <= S_SAVE;
                        save_ack_b <= 1'b0;
                        ramp_ack_b <= 1'b0;
                        rest_ack_b <= 1'b0;
                    end
                end
                S_SAVE: begin
                    if (!rail_busy && (state != S_SAVE)) begin
                        save_ack_b <= 1'b1;
                        ramp_cnt <= 8'd0;
                        rail_busy <= 1'b1;
                        rail_owner <= 1'b1;
                        state_b <= S_RAMP;
                    end else if (rail_stall_cnt != 8'hFF) begin
                        rail_stall_cnt <= rail_stall_cnt + 8'd1;
                    end
                end
                S_RAMP: begin
                    if (ramp_ack_b)
                        state_b <= S_REST;
                end
                S_REST: begin
                    rest_ack_b <= 1'b1;
                    state_b <= S_DONE;
                end
                S_DONE: begin
                    state_b <= S_IDLE;
                end
                default: begin
                    state_b <= S_IDLE;
                end
            endcase
            // Shared ramp regulator: one ramp at a time, completion reported to the grant holder
            if (rail_busy) begin
                if (ramp_cnt == RAMP_LAST) begin
                    rail_busy <= 1'b0;
                    if (rail_owner)
                        ramp_ack_b <= 1'b1;
                    else
                        ramp_ack <= 1'b1;
                end else begin
                    ramp_cnt <= ramp_cnt + 8'd1;
                end
            end
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  stat_o,
output reg  [2:0]   out_tag,
output reg          out_last,
output reg          out_par,
output wire [1:0]   eq_lvl_o,
output wire [15:0]  eq_stall_o,
output wire         ln_busy_o,
output wire [2:0]   ra_lvl_o,
output reg  [2:0]   ra_hwm_o,
output reg  [7:0]   ra_lat_o,
output reg  [15:0]  ra_perr_o,
output reg  [15:0]  ra_blk_o,
output reg  [15:0]  ra_byp_o,
output reg  [15:0]  ra_fetch_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg [15:0] start_cnt;
reg [15:0] stop_cnt;
reg [15:0] beat_cnt;
reg [7:0]  wrap_cnt;
reg [15:0] idle_cnt;
reg        err_sticky;
reg [1:0]  stat_sel;
reg [127:0] pf_data [0:3];
reg [3:0]   pf_tag  [0:3];
reg [1:0]   pf_wp;
reg [1:0]   pf_rp;
reg [2:0]   pf_used;
// egress retiming queue: decouples prefetch from the shared lane grant
reg [127:0] eq_data [0:1];
reg [3:0]   eq_tag  [0:1];
reg         eq_wp;
reg         eq_rp;
reg [1:0]   eq_used;
reg [15:0]  stall_cnt;
// lane output register: one beat parked until this source's grant slot
reg [127:0] ln_data;
reg [3:0]   ln_tag;
reg         ln_v;
// ROM read-ahead register file: fetches run ahead of prefetch acceptance;
// every slot keeps its own valid bit, write-time parity and fetch stamp
reg [127:0] ra_data [0:3];
reg [3:0]   ra_tag  [0:3];
reg [7:0]   ra_ts   [0:3];
reg [3:0]   ra_par;
reg [3:0]   ra_v;
reg [1:0]   ra_wp;
reg [1:0]   ra_rp;

    initial begin
start_cnt  = 16'd0;
stop_cnt   = 16'd0;
beat_cnt   = 16'd0;
wrap_cnt   = 8'd0;
idle_cnt   = 16'd0;
err_sticky = 1'b0;
stat_sel   = 2'd0;
stat_o     = 32'h0;
pf_data[0] = 128'h0;
pf_data[1] = 128'h0;
pf_data[2] = 128'h0;
pf_data[3] = 128'h0;
pf_tag[0]  = 4'd0;
pf_tag[1]  = 4'd0;
pf_tag[2]  = 4'd0;
pf_tag[3]  = 4'd0;
pf_wp      = 2'd0;
pf_rp      = 2'd0;
pf_used    = 3'd0;
eq_data[0] = 128'h0;
eq_data[1] = 128'h0;
eq_tag[0]  = 4'd0;
eq_tag[1]  = 4'd0;
eq_wp      = 1'b0;
eq_rp      = 1'b0;
eq_used    = 2'd0;
stall_cnt  = 16'd0;
ln_data    = 128'h0;
ln_tag     = 4'd0;
ln_v       = 1'b0;
ra_data[0] = 128'h0;
ra_data[1] = 128'h0;
ra_data[2] = 128'h0;
ra_data[3] = 128'h0;
ra_tag[0]  = 4'd0;
ra_tag[1]  = 4'd0;
ra_tag[2]  = 4'd0;
ra_tag[3]  = 4'd0;
ra_ts[0]   = 8'd0;
ra_ts[1]   = 8'd0;
ra_ts[2]   = 8'd0;
ra_ts[3]   = 8'd0;
ra_par     = 4'd0;
ra_v       = 4'd0;
ra_wp      = 2'd0;
ra_rp      = 2'd0;
ra_hwm_o   = 3'd0;
ra_lat_o   = 8'd0;
ra_perr_o  = 16'd0;
ra_blk_o   = 16'd0;
ra_byp_o   = 16'd0;
ra_fetch_o = 16'd0;
out_tag    = 3'd0;
out_last   = 1'b0;
out_par    = 1'b0;
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end
   // shared crossbar lane: this source owns the even arbitration slots
   wire       slot_gnt    = ~stat_sel[0];
   wire       pf_full     = (pf_used == 3'd4);
   wire       pf_empty    = (pf_used == 3'd0);
   wire       eq_full     = (eq_used == 2'd2);
   wire       eq_empty    = (eq_used == 2'd0);
wire       ln_pop      = win && ln_v && slot_gnt;
wire       ln_last     = (ln_tag == 4'd7);
wire       eq_pop      = win && !eq_empty && (!ln_v || ln_pop);
   wire       pf_pop      = win && !pf_empty && (!eq_full || eq_pop);
   wire       eq_push     = pf_pop;
// read-ahead control: slots are filled in order at ra_wp, drained at ra_rp
wire [2:0]   ra_lvl       = {2'b0, ra_v[0]} + {2'b0, ra_v[1]} + {2'b0, ra_v[2]} + {2'b0, ra_v[3]};
wire         ra_head_v    = ra_v[ra_rp];
wire         ra_slot_v    = ra_v[ra_wp];
wire         pf_room      = !pf_full || pf_pop;
wire         ra_pop       = win && ra_head_v && pf_room;
// empty buffer: the ROM word goes straight into prefetch, saving a cycle
wire         ra_byp       = win && (ra_lvl == 3'd0) && pf_room;
wire         ra_push      = win && !ra_byp && (!ra_slot_v || (ra_pop && (ra_wp == ra_rp)));
wire         rom_take     = ra_push || ra_byp;
wire         pf_push      = ra_pop || ra_byp;
wire [3:0]   ra_set       = ra_push ? (4'b0001 << ra_wp) : 4'b0000;
wire [3:0]   ra_clr       = ra_pop  ? (4'b0001 << ra_rp) : 4'b0000;
wire [3:0]   ra_v_nxt     = (ra_v & ~ra_clr) | ra_set;
wire [127:0] ra_head_data = ra_data[ra_rp];
wire [3:0]   ra_head_tag  = ra_tag[ra_rp];
wire [7:0]   ra_res       = beat_cnt[7:0] - ra_ts[ra_rp];
wire         ra_par_bad   = ra_par[ra_rp] ^ (^ra_head_data);
wire         rom_par      = ^rom_word;
wire [127:0] pf_in_data   = ra_byp ? rom_word : ra_head_data;
wire [3:0]   pf_in_tag    = ra_byp ? {1'b0, rd_ptr} : ra_head_tag;
wire         ra_blk       = win && ra_slot_v && !rom_take;
assign ra_lvl_o = ra_lvl;
   wire [3:0] pf_head_tag = pf_tag[pf_rp];
   wire [3:0] eq_head_tag = eq_tag[eq_rp];
   wire       eq_last     = (eq_head_tag == 4'd7);
   wire       pf_stall    = win && !pf_empty && !pf_pop;
   assign eq_lvl_o   = eq_used;
   assign eq_stall_o = stall_cnt;
assign ln_busy_o  = ln_v;

    always @(posedge clk) begin
        if (!rst_n) begin
start_cnt  <= 16'd0;
stop_cnt   <= 16'd0;
beat_cnt   <= 16'd0;
wrap_cnt   <= 8'd0;
idle_cnt   <= 16'd0;
err_sticky <= 1'b0;
stat_sel   <= 2'd0;
stat_o     <= 32'h0;
pf_data[0] <= 128'h0;
pf_data[1] <= 128'h0;
pf_data[2] <= 128'h0;
pf_data[3] <= 128'h0;
pf_tag[0]  <= 4'd0;
pf_tag[1]  <= 4'd0;
pf_tag[2]  <= 4'd0;
pf_tag[3]  <= 4'd0;
pf_wp      <= 2'd0;
pf_rp      <= 2'd0;
pf_used    <= 3'd0;
eq_data[0] <= 128'h0;
eq_data[1] <= 128'h0;
eq_tag[0]  <= 4'd0;
eq_tag[1]  <= 4'd0;
eq_wp      <= 1'b0;
eq_rp      <= 1'b0;
eq_used    <= 2'd0;
stall_cnt  <= 16'd0;
ln_data    <= 128'h0;
ln_tag     <= 4'd0;
ln_v       <= 1'b0;
ra_data[0] <= 128'h0;
ra_data[1] <= 128'h0;
ra_data[2] <= 128'h0;
ra_data[3] <= 128'h0;
ra_tag[0]  <= 4'd0;
ra_tag[1]  <= 4'd0;
ra_tag[2]  <= 4'd0;
ra_tag[3]  <= 4'd0;
ra_ts[0]   <= 8'd0;
ra_ts[1]   <= 8'd0;
ra_ts[2]   <= 8'd0;
ra_ts[3]   <= 8'd0;
ra_par     <= 4'd0;
ra_v       <= 4'd0;
ra_wp      <= 2'd0;
ra_rp      <= 2'd0;
ra_hwm_o   <= 3'd0;
ra_lat_o   <= 8'd0;
ra_perr_o  <= 16'd0;
ra_blk_o   <= 16'd0;
ra_byp_o   <= 16'd0;
ra_fetch_o <= 16'd0;
out_tag    <= 3'd0;
out_last   <= 1'b0;
out_par    <= 1'b0;
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
if (start)
    start_cnt <= start_cnt + 16'd1;
if (stop)
    stop_cnt <= stop_cnt + 16'd1;
if (start && stop)
    err_sticky <= 1'b1;
if (win && !start && !stop) begin
    beat_cnt <= beat_cnt + 16'd1;
if (ln_pop && ln_last)
        wrap_cnt <= wrap_cnt + 8'd1;
end
if (!win)
    idle_cnt <= idle_cnt + 16'd1;
if (pf_stall && !start && !stop)
    stall_cnt <= stall_cnt + 16'd1;
if (ra_blk && !start && !stop)
    ra_blk_o <= ra_blk_o + 16'd1;
if (ra_lvl > ra_hwm_o)
    ra_hwm_o <= ra_lvl;
stat_sel <= stat_sel + 2'd1;
case (stat_sel)
    2'd0: stat_o <= {start_cnt, stop_cnt};
    2'd1: stat_o <= {beat_cnt, idle_cnt};
2'd2: stat_o <= {3'h0, eq_used, pf_used, wrap_cnt, 12'h0, ra_lvl, err_sticky};
    default: stat_o <= {err_sticky, 7'h0, wrap_cnt, beat_cnt};
endcase
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
               pf_wp   <= 2'd0;
               pf_rp   <= 2'd0;
               pf_used <= 3'd0;
               eq_wp   <= 1'b0;
               eq_rp   <= 1'b0;
               eq_used <= 2'd0;
ln_v    <= 1'b0;
ra_v    <= 4'd0;
ra_wp   <= 2'd0;
ra_rp   <= 2'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
               if (rom_take) begin
                   rd_ptr     <= rd_ptr + 3'd1;
                   ra_fetch_o <= ra_fetch_o + 16'd1;
               end
               if (ra_byp)
                   ra_byp_o <= ra_byp_o + 16'd1;
               if (ra_push) begin
                   ra_data[ra_wp] <= rom_word;
                   ra_tag[ra_wp]  <= {1'b0, rd_ptr};
                   ra_ts[ra_wp]   <= beat_cnt[7:0];
                   ra_par[ra_wp]  <= rom_par;
                   ra_wp          <= ra_wp + 2'd1;
               end
               if (ra_pop) begin
                   ra_rp <= ra_rp + 2'd1;
                   if (ra_res > ra_lat_o)
                       ra_lat_o <= ra_res;
                   if (ra_par_bad)
                       ra_perr_o <= ra_perr_o + 16'd1;
               end
               ra_v <= ra_v_nxt;
               if (pf_push) begin
                   pf_data[pf_wp] <= pf_in_data;
                   pf_tag[pf_wp]  <= pf_in_tag;
                   pf_wp          <= pf_wp + 2'd1;
               end
               if (pf_pop) begin
                  eq_data[eq_wp] <= pf_data[pf_rp];
                  eq_tag[eq_wp]  <= pf_head_tag;
                  eq_wp          <= eq_wp + 1'b1;
                  pf_rp          <= pf_rp + 2'd1;
              end
if (ln_pop) begin
    out_q    <= ln_data;
    out_tag  <= ln_tag[2:0];
    out_last <= ln_last;
    out_par  <= ^ln_data;
    out_v    <= 1'b1;
    if (ln_last)
        cnt <= 4'd0;
    else
        cnt <= cnt + 4'd1;
end
if (eq_pop) begin
    ln_data <= eq_data[eq_rp];
    ln_tag  <= eq_head_tag;
    eq_rp   <= eq_rp + 1'b1;
end
if (eq_pop)
    ln_v <= 1'b1;
else if (ln_pop)
    ln_v <= 1'b0;
              case ({eq_push, eq_pop})
                  2'b10:   eq_used <= eq_used + 2'd1;
                  2'b01:   eq_used <= eq_used - 2'd1;
                  default: eq_used <= eq_used;
              endcase
               case ({pf_push, pf_pop})
                   2'b10:   pf_used <= pf_used + 3'd1;
                   2'b01:   pf_used <= pf_used - 3'd1;
                   default: pf_used <= pf_used;
               endcase
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module wormhole_route_unit #(
    parameter [63:0] MY_X = 64'd4,
    parameter [63:0] MY_Y = 64'd2
) (
    input  wire        clk,
    input  wire        in_valid,
    input  wire [1:0]  flit_type,
    input  wire [3:0]  in_ch,
    input  wire [63:0] dest_x,
    input  wire [63:0] dest_y,
    output reg  [2:0]  out_port,
output wire        out_fire,
output wire [2:0]  hq_level,
output wire        head_stall,
output reg  [3:0]  last_commit_ch
);
    localparam [1:0] FT_BODY = 2'b00;
    localparam [1:0] FT_HEAD = 2'b01;
    localparam [1:0] FT_TAIL = 2'b10;

    localparam [2:0] P_LOCAL = 3'd0;
    localparam [2:0] P_EAST  = 3'd1;
    localparam [2:0] P_WEST  = 3'd2;
    localparam [2:0] P_NORTH = 3'd3;
    localparam [2:0] P_SOUTH = 3'd4;

    reg [15:0] route_valid;
    reg [47:0] route_port;
    reg [63:0] head_cnt;
    reg [63:0] body_cnt;
    reg        head_seen;
    reg        armed;
reg [3:0]  hq_ch   [0:3];
reg [2:0]  hq_port [0:3];
reg [1:0]  hq_wr;
reg [1:0]  hq_rd;
reg [2:0]  hq_count;
reg [15:0] hq_pend;

    initial begin
        route_valid = 16'd0;
        route_port  = 48'd0;
        head_cnt    = 64'd0;
        body_cnt    = 64'd0;
        head_seen   = 1'b0;
        armed       = 1'b1;
hq_ch[0]    = 4'd0;
hq_ch[1]    = 4'd0;
hq_ch[2]    = 4'd0;
hq_ch[3]    = 4'd0;
hq_port[0]  = 3'd0;
hq_port[1]  = 3'd0;
hq_port[2]  = 3'd0;
hq_port[3]  = 3'd0;
hq_wr       = 2'd0;
hq_rd       = 2'd0;
hq_count    = 3'd0;
hq_pend     = 16'd0;
last_commit_ch = 4'd0;
        out_port    = 3'd0;
    end

    wire ch_busy = route_valid[in_ch];
wire       hq_full      = (hq_count == 3'd4);
wire       hq_empty     = (hq_count == 3'd0);
wire       hq_pop       = !hq_empty && !in_valid;
wire [3:0] hq_head_ch   = hq_ch[hq_rd];
wire [2:0] hq_head_port = hq_port[hq_rd];
assign hq_level   = hq_count;
assign head_stall = in_valid && (flit_type == FT_HEAD) && !ch_busy && (hq_full || hq_pend[in_ch]);
wire do_head = in_valid && (flit_type == FT_HEAD) && !ch_busy && !hq_pend[in_ch] && !hq_full;
    wire do_body = in_valid && (flit_type == FT_BODY) && ch_busy;
    wire do_tail = in_valid && (flit_type == FT_TAIL) && ch_busy;

    assign out_fire = do_head || do_body || do_tail;

    reg [2:0] calc_port;
    always @(*) begin
        if (dest_x > MY_X)      calc_port = P_EAST;
        else if (dest_x < MY_X) calc_port = P_WEST;
        else if (dest_y > MY_Y) calc_port = P_NORTH;
        else if (dest_y < MY_Y) calc_port = P_SOUTH;
        else                    calc_port = P_LOCAL;
    end

    wire [2:0] stored_port = route_port[in_ch*3 +: 3];

    always @(posedge clk) begin
        if (do_head) begin
hq_ch[hq_wr]               <= in_ch;
hq_port[hq_wr]             <= calc_port;
hq_wr                      <= hq_wr + 2'd1;
hq_count                   <= hq_count + 3'd1;
hq_pend[in_ch]             <= 1'b1;
            head_cnt                   <= head_cnt + 64'd1;
            head_seen                  <= 1'b1;
            out_port                   <= calc_port;
        end
        if (do_body) begin
            body_cnt <= body_cnt + 64'd1;
            out_port <= stored_port;
        end
        if (do_tail) begin
            route_valid[in_ch] <= 1'b0;
            armed              <= 1'b0;
            out_port           <= stored_port;
        end
if (hq_pop) begin
route_valid[hq_head_ch]       <= 1'b1;
route_port[hq_head_ch*3 +: 3] <= hq_head_port;
hq_pend[hq_head_ch]           <= 1'b0;
hq_rd                         <= hq_rd + 2'd1;
hq_count                      <= hq_count - 3'd1;
last_commit_ch                <= hq_head_ch;
end
    end

    always @(*) assert (!armed || (body_cnt == 64'd0) || head_seen);
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
output reg         fault,
output reg  [1:0]  outstanding
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;
// accesses accepted but not yet answered (drain status for reconfiguration)
initial outstanding = 2'd0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
            fault  <= miss_q;
outstanding <= outstanding + {1'b0, acc_valid} - {1'b0, grant} - {1'b0, fault};
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);

always @(posedge clk)
if (grant || fault) assert (outstanding != 2'd0);
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  stat_o,
output reg  [2:0]   out_tag,
output reg          out_last,
output reg          out_par,
output wire [1:0]   eq_lvl_o,
output wire [15:0]  eq_stall_o,
output wire         ln_busy_o,
output wire [2:0]   ra_lvl_o,
output reg  [2:0]   ra_hwm_o,
output reg  [7:0]   ra_lat_o,
output reg  [15:0]  ra_perr_o,
output reg  [15:0]  ra_blk_o,
output reg  [15:0]  ra_byp_o,
output reg  [15:0]  ra_fetch_o,
output wire [2:0]   rb_lvl_o,
output wire [3:0]   ra_tot_o,
output reg  [2:0]   rb_hwm_o,
output reg  [7:0]   rb_lat_o,
output reg  [15:0]  rb_perr_o,
output reg  [15:0]  rb_blk_o,
output reg  [15:0]  rb_fetch_o,
output reg  [15:0]  bk_coll_o,
output reg  [15:0]  ra_pop_o,
output reg  [15:0]  rb_pop_o,
output reg  [15:0]  ra_occ_o,
output reg  [15:0]  rb_occ_o,
output reg  [15:0]  ra_old_o,
output reg  [15:0]  rb_old_o,
output reg  [3:0]   bk_ferr_o,
output reg          bk_ferr_v_o,
output reg  [31:0]  bk_stat_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg [15:0] start_cnt;
reg [15:0] stop_cnt;
reg [15:0] beat_cnt;
reg [7:0]  wrap_cnt;
reg [15:0] idle_cnt;
reg        err_sticky;
reg [1:0]  stat_sel;
reg [127:0] pf_data [0:3];
reg [3:0]   pf_tag  [0:3];
reg [1:0]   pf_wp;
reg [1:0]   pf_rp;
reg [2:0]   pf_used;
// egress retiming queue: decouples prefetch from the shared lane grant
reg [127:0] eq_data [0:1];
reg [3:0]   eq_tag  [0:1];
reg         eq_wp;
reg         eq_rp;
reg [1:0]   eq_used;
reg [15:0]  stall_cnt;
// lane output register: one beat parked until this source's grant slot
reg [127:0] ln_data;
reg [3:0]   ln_tag;
reg         ln_v;
// ROM read-ahead register file: fetches run ahead of prefetch acceptance;
// every slot keeps its own valid bit, write-time parity and fetch stamp
reg [127:0] ra_data [0:3];
reg [3:0]   ra_tag  [0:3];
reg [7:0]   ra_ts   [0:3];
reg [3:0]   ra_par;
reg [3:0]   ra_v;
reg [1:0]   ra_wp;
reg [1:0]   ra_rp;
// second read-ahead bank: the ROM port alternates between the two banks by
// word address (even words to ra, odd words to rb); both banks drain through
// the single prefetch write port, oldest word first
reg [127:0] rb_data [0:3];
reg [3:0]   rb_tag  [0:3];
reg [7:0]   rb_ts   [0:3];
reg [3:0]   rb_par;
reg [3:0]   rb_v;
reg [1:0]   rb_wp;
reg [1:0]   rb_rp;

    initial begin
start_cnt  = 16'd0;
stop_cnt   = 16'd0;
beat_cnt   = 16'd0;
wrap_cnt   = 8'd0;
idle_cnt   = 16'd0;
err_sticky = 1'b0;
stat_sel   = 2'd0;
stat_o     = 32'h0;
pf_data[0] = 128'h0;
pf_data[1] = 128'h0;
pf_data[2] = 128'h0;
pf_data[3] = 128'h0;
pf_tag[0]  = 4'd0;
pf_tag[1]  = 4'd0;
pf_tag[2]  = 4'd0;
pf_tag[3]  = 4'd0;
pf_wp      = 2'd0;
pf_rp      = 2'd0;
pf_used    = 3'd0;
eq_data[0] = 128'h0;
eq_data[1] = 128'h0;
eq_tag[0]  = 4'd0;
eq_tag[1]  = 4'd0;
eq_wp      = 1'b0;
eq_rp      = 1'b0;
eq_used    = 2'd0;
stall_cnt  = 16'd0;
ln_data    = 128'h0;
ln_tag     = 4'd0;
ln_v       = 1'b0;
ra_data[0] = 128'h0;
ra_data[1] = 128'h0;
ra_data[2] = 128'h0;
ra_data[3] = 128'h0;
ra_tag[0]  = 4'd0;
ra_tag[1]  = 4'd0;
ra_tag[2]  = 4'd0;
ra_tag[3]  = 4'd0;
ra_ts[0]   = 8'd0;
ra_ts[1]   = 8'd0;
ra_ts[2]   = 8'd0;
ra_ts[3]   = 8'd0;
ra_par     = 4'd0;
ra_v       = 4'd0;
ra_wp      = 2'd0;
ra_rp      = 2'd0;
ra_hwm_o   = 3'd0;
ra_lat_o   = 8'd0;
ra_perr_o  = 16'd0;
ra_blk_o   = 16'd0;
ra_byp_o   = 16'd0;
ra_fetch_o = 16'd0;
rb_data[0] = 128'h0;
rb_data[1] = 128'h0;
rb_data[2] = 128'h0;
rb_data[3] = 128'h0;
rb_tag[0]  = 4'd0;
rb_tag[1]  = 4'd0;
rb_tag[2]  = 4'd0;
rb_tag[3]  = 4'd0;
rb_ts[0]   = 8'd0;
rb_ts[1]   = 8'd0;
rb_ts[2]   = 8'd0;
rb_ts[3]   = 8'd0;
rb_par     = 4'd0;
rb_v       = 4'd0;
rb_wp      = 2'd0;
rb_rp      = 2'd0;
rb_hwm_o   = 3'd0;
rb_lat_o   = 8'd0;
rb_perr_o  = 16'd0;
rb_blk_o   = 16'd0;
rb_fetch_o = 16'd0;
bk_coll_o  = 16'd0;
ra_pop_o   = 16'd0;
rb_pop_o   = 16'd0;
ra_occ_o   = 16'd0;
rb_occ_o   = 16'd0;
ra_old_o   = 16'd0;
rb_old_o   = 16'd0;
bk_ferr_o  = 4'd0;
bk_ferr_v_o = 1'b0;
bk_stat_o  = 32'h0;
out_tag    = 3'd0;
out_last   = 1'b0;
out_par    = 1'b0;
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end
   // shared crossbar lane: this source owns the even arbitration slots
   wire       slot_gnt    = ~stat_sel[0];
   wire       pf_full     = (pf_used == 3'd4);
   wire       pf_empty    = (pf_used == 3'd0);
   wire       eq_full     = (eq_used == 2'd2);
   wire       eq_empty    = (eq_used == 2'd0);
wire       ln_pop      = win && ln_v && slot_gnt;
wire       ln_last     = (ln_tag == 4'd7);
wire       eq_pop      = win && !eq_empty && (!ln_v || ln_pop);
   wire       pf_pop      = win && !pf_empty && (!eq_full || eq_pop);
   wire       eq_push     = pf_pop;
// read-ahead control: slots are filled in order at ra_wp, drained at ra_rp
wire [2:0]   ra_lvl       = {2'b0, ra_v[0]} + {2'b0, ra_v[1]} + {2'b0, ra_v[2]} + {2'b0, ra_v[3]};
wire         ra_head_v    = ra_v[ra_rp];
wire         ra_slot_v    = ra_v[ra_wp];
wire [2:0]   rb_lvl       = {2'b0, rb_v[0]} + {2'b0, rb_v[1]} + {2'b0, rb_v[2]} + {2'b0, rb_v[3]};
wire [3:0]   ra_tot       = {1'b0, ra_lvl} + {1'b0, rb_lvl};
// even ROM words fill bank a, odd words fill bank b; the oldest buffered
// word was fetched ra_tot fetches back, so its address parity names the head bank
wire         ra_fsel      = rd_ptr[0];
wire         ra_hsel      = rd_ptr[0] ^ ra_tot[0];
wire         rb_head_v    = rb_v[rb_rp];
wire         rb_slot_v    = rb_v[rb_wp];
wire         bk_head_v    = ra_hsel ? rb_head_v : ra_head_v;
wire         pf_room      = !pf_full || pf_pop;
wire         bk_pop       = win && bk_head_v && pf_room;
wire         ra_pop       = bk_pop && !ra_hsel;
wire         rb_pop       = bk_pop && ra_hsel;
// empty buffer: the ROM word goes straight into prefetch, saving a cycle
wire         ra_byp       = win && (ra_tot == 4'd0) && pf_room;
// a bank may accept the fetch if its fill slot is free or is being drained now
wire         ra_fill_ok   = !ra_slot_v || (ra_pop && (ra_wp == ra_rp));
wire         rb_fill_ok   = !rb_slot_v || (rb_pop && (rb_wp == rb_rp));
wire         bk_push      = win && !ra_byp && (ra_fsel ? rb_fill_ok : ra_fill_ok);
wire         ra_push      = bk_push && !ra_fsel;
wire         rb_push      = bk_push && ra_fsel;
wire         rom_take     = bk_push || ra_byp;
wire         pf_push      = bk_pop || ra_byp;
wire [3:0]   ra_set       = ra_push ? (4'b0001 << ra_wp) : 4'b0000;
wire [3:0]   ra_clr       = ra_pop  ? (4'b0001 << ra_rp) : 4'b0000;
wire [3:0]   ra_v_nxt     = (ra_v & ~ra_clr) | ra_set;
wire [3:0]   rb_set       = rb_push ? (4'b0001 << rb_wp) : 4'b0000;
wire [3:0]   rb_clr       = rb_pop  ? (4'b0001 << rb_rp) : 4'b0000;
wire [3:0]   rb_v_nxt     = (rb_v & ~rb_clr) | rb_set;
wire [127:0] ra_head_data = ra_data[ra_rp];
wire [3:0]   ra_head_tag  = ra_tag[ra_rp];
wire [7:0]   ra_res       = beat_cnt[7:0] - ra_ts[ra_rp];
wire         ra_par_bad   = ra_par[ra_rp] ^ (^ra_head_data);
wire [127:0] rb_head_data = rb_data[rb_rp];
wire [3:0]   rb_head_tag  = rb_tag[rb_rp];
wire [7:0]   rb_res       = beat_cnt[7:0] - rb_ts[rb_rp];
wire         rb_par_bad   = rb_par[rb_rp] ^ (^rb_head_data);
// a head word that has waited too long points at a starved prefetch port
wire         ra_stale     = ra_head_v && (ra_res > 8'd48);
wire         rb_stale     = rb_head_v && (rb_res > 8'd48);
wire         rom_par      = ^rom_word;
wire [127:0] bk_head_data = ra_hsel ? rb_head_data : ra_head_data;
wire [3:0]   bk_head_tag  = ra_hsel ? rb_head_tag  : ra_head_tag;
wire [127:0] pf_in_data   = ra_byp ? rom_word : bk_head_data;
wire [3:0]   pf_in_tag    = ra_byp ? {1'b0, rd_ptr} : bk_head_tag;
wire         ra_blk       = win && !ra_fsel && ra_slot_v && !rom_take;
wire         rb_blk       = win && ra_fsel && rb_slot_v && !rom_take;
// same bank written and read in one cycle: needs the bypassing write port
wire         bk_coll      = bk_push && bk_pop && (ra_fsel == ra_hsel);
assign ra_lvl_o = ra_lvl;
assign rb_lvl_o = rb_lvl;
assign ra_tot_o = ra_tot;
   wire [3:0] pf_head_tag = pf_tag[pf_rp];
   wire [3:0] eq_head_tag = eq_tag[eq_rp];
   wire       eq_last     = (eq_head_tag == 4'd7);
   wire       pf_stall    = win && !pf_empty && !pf_pop;
   assign eq_lvl_o   = eq_used;
   assign eq_stall_o = stall_cnt;
assign ln_busy_o  = ln_v;

    always @(posedge clk) begin
        if (!rst_n) begin
start_cnt  <= 16'd0;
stop_cnt   <= 16'd0;
beat_cnt   <= 16'd0;
wrap_cnt   <= 8'd0;
idle_cnt   <= 16'd0;
err_sticky <= 1'b0;
stat_sel   <= 2'd0;
stat_o     <= 32'h0;
pf_data[0] <= 128'h0;
pf_data[1] <= 128'h0;
pf_data[2] <= 128'h0;
pf_data[3] <= 128'h0;
pf_tag[0]  <= 4'd0;
pf_tag[1]  <= 4'd0;
pf_tag[2]  <= 4'd0;
pf_tag[3]  <= 4'd0;
pf_wp      <= 2'd0;
pf_rp      <= 2'd0;
pf_used    <= 3'd0;
eq_data[0] <= 128'h0;
eq_data[1] <= 128'h0;
eq_tag[0]  <= 4'd0;
eq_tag[1]  <= 4'd0;
eq_wp      <= 1'b0;
eq_rp      <= 1'b0;
eq_used    <= 2'd0;
stall_cnt  <= 16'd0;
ln_data    <= 128'h0;
ln_tag     <= 4'd0;
ln_v       <= 1'b0;
ra_data[0] <= 128'h0;
ra_data[1] <= 128'h0;
ra_data[2] <= 128'h0;
ra_data[3] <= 128'h0;
ra_tag[0]  <= 4'd0;
ra_tag[1]  <= 4'd0;
ra_tag[2]  <= 4'd0;
ra_tag[3]  <= 4'd0;
ra_ts[0]   <= 8'd0;
ra_ts[1]   <= 8'd0;
ra_ts[2]   <= 8'd0;
ra_ts[3]   <= 8'd0;
ra_par     <= 4'd0;
ra_v       <= 4'd0;
ra_wp      <= 2'd0;
ra_rp      <= 2'd0;
ra_hwm_o   <= 3'd0;
ra_lat_o   <= 8'd0;
ra_perr_o  <= 16'd0;
ra_blk_o   <= 16'd0;
ra_byp_o   <= 16'd0;
ra_fetch_o <= 16'd0;
rb_data[0] <= 128'h0;
rb_data[1] <= 128'h0;
rb_data[2] <= 128'h0;
rb_data[3] <= 128'h0;
rb_tag[0]  <= 4'd0;
rb_tag[1]  <= 4'd0;
rb_tag[2]  <= 4'd0;
rb_tag[3]  <= 4'd0;
rb_ts[0]   <= 8'd0;
rb_ts[1]   <= 8'd0;
rb_ts[2]   <= 8'd0;
rb_ts[3]   <= 8'd0;
rb_par     <= 4'd0;
rb_v       <= 4'd0;
rb_wp      <= 2'd0;
rb_rp      <= 2'd0;
rb_hwm_o   <= 3'd0;
rb_lat_o   <= 8'd0;
rb_perr_o  <= 16'd0;
rb_blk_o   <= 16'd0;
rb_fetch_o <= 16'd0;
bk_coll_o  <= 16'd0;
ra_pop_o   <= 16'd0;
rb_pop_o   <= 16'd0;
ra_occ_o   <= 16'd0;
rb_occ_o   <= 16'd0;
ra_old_o   <= 16'd0;
rb_old_o   <= 16'd0;
bk_ferr_o  <= 4'd0;
bk_ferr_v_o <= 1'b0;
bk_stat_o  <= 32'h0;
out_tag    <= 3'd0;
out_last   <= 1'b0;
out_par    <= 1'b0;
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
if (start)
    start_cnt <= start_cnt + 16'd1;
if (stop)
    stop_cnt <= stop_cnt + 16'd1;
if (start && stop)
    err_sticky <= 1'b1;
if (win && !start && !stop) begin
    beat_cnt <= beat_cnt + 16'd1;
if (ln_pop && ln_last)
        wrap_cnt <= wrap_cnt + 8'd1;
end
if (!win)
    idle_cnt <= idle_cnt + 16'd1;
if (pf_stall && !start && !stop)
    stall_cnt <= stall_cnt + 16'd1;
if (ra_blk && !start && !stop)
    ra_blk_o <= ra_blk_o + 16'd1;
if (ra_lvl > ra_hwm_o)
    ra_hwm_o <= ra_lvl;
if (rb_lvl > rb_hwm_o)
    rb_hwm_o <= rb_lvl;
if (rb_blk && !start && !stop)
    rb_blk_o <= rb_blk_o + 16'd1;
if (win && !start && !stop) begin
    ra_occ_o <= ra_occ_o + {13'h0, ra_lvl};
    rb_occ_o <= rb_occ_o + {13'h0, rb_lvl};
    if (ra_stale)
        ra_old_o <= ra_old_o + 16'd1;
    if (rb_stale)
        rb_old_o <= rb_old_o + 16'd1;
end
stat_sel <= stat_sel + 2'd1;
case (stat_sel)
    2'd0: stat_o <= {start_cnt, stop_cnt};
    2'd1: stat_o <= {beat_cnt, idle_cnt};
2'd2: stat_o <= {3'h0, eq_used, pf_used, wrap_cnt, 9'h0, rb_lvl, ra_lvl, err_sticky};
    default: stat_o <= {err_sticky, 7'h0, wrap_cnt, beat_cnt};
endcase
case (stat_sel)
    2'd0: bk_stat_o <= {ra_pop_o, rb_pop_o};
    2'd1: bk_stat_o <= {ra_occ_o, rb_occ_o};
    2'd2: bk_stat_o <= {ra_old_o, rb_old_o};
    default: bk_stat_o <= {bk_ferr_v_o, 3'h0, bk_ferr_o, 8'h0, rb_lat_o, ra_lat_o};
endcase
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
               pf_wp   <= 2'd0;
               pf_rp   <= 2'd0;
               pf_used <= 3'd0;
               eq_wp   <= 1'b0;
               eq_rp   <= 1'b0;
               eq_used <= 2'd0;
ln_v    <= 1'b0;
ra_v    <= 4'd0;
ra_wp   <= 2'd0;
ra_rp   <= 2'd0;
rb_v    <= 4'd0;
rb_wp   <= 2'd0;
rb_rp   <= 2'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
               if (rom_take) begin
                   rd_ptr     <= rd_ptr + 3'd1;
                   ra_fetch_o <= ra_fetch_o + 16'd1;
               end
               if (ra_byp)
                   ra_byp_o <= ra_byp_o + 16'd1;
if (rb_push)
    rb_fetch_o <= rb_fetch_o + 16'd1;
if (bk_coll)
    bk_coll_o <= bk_coll_o + 16'd1;
if (rb_push) begin
    rb_data[rb_wp] <= rom_word;
    rb_tag[rb_wp]  <= {1'b0, rd_ptr};
    rb_ts[rb_wp]   <= beat_cnt[7:0];
    rb_par[rb_wp]  <= rom_par;
    rb_wp          <= rb_wp + 2'd1;
end
               if (ra_push) begin
                   ra_data[ra_wp] <= rom_word;
                   ra_tag[ra_wp]  <= {1'b0, rd_ptr};
                   ra_ts[ra_wp]   <= beat_cnt[7:0];
                   ra_par[ra_wp]  <= rom_par;
                   ra_wp          <= ra_wp + 2'd1;
               end
               if (ra_pop) begin
                   ra_rp <= ra_rp + 2'd1;
                   if (ra_res > ra_lat_o)
                       ra_lat_o <= ra_res;
                   if (ra_par_bad)
                       ra_perr_o <= ra_perr_o + 16'd1;
ra_pop_o <= ra_pop_o + 16'd1;
if (ra_par_bad && !bk_ferr_v_o) begin
    bk_ferr_o   <= {1'b0, ra_head_tag[2:0]};
    bk_ferr_v_o <= 1'b1;
end
               end
if (rb_pop) begin
    rb_rp    <= rb_rp + 2'd1;
    rb_pop_o <= rb_pop_o + 16'd1;
    if (rb_res > rb_lat_o)
        rb_lat_o <= rb_res;
    if (rb_par_bad)
        rb_perr_o <= rb_perr_o + 16'd1;
    if (rb_par_bad && !bk_ferr_v_o) begin
        bk_ferr_o   <= {1'b1, rb_head_tag[2:0]};
        bk_ferr_v_o <= 1'b1;
    end
end
               ra_v <= ra_v_nxt;
rb_v <= rb_v_nxt;
               if (pf_push) begin
                   pf_data[pf_wp] <= pf_in_data;
                   pf_tag[pf_wp]  <= pf_in_tag;
                   pf_wp          <= pf_wp + 2'd1;
               end
               if (pf_pop) begin
                  eq_data[eq_wp] <= pf_data[pf_rp];
                  eq_tag[eq_wp]  <= pf_head_tag;
                  eq_wp          <= eq_wp + 1'b1;
                  pf_rp          <= pf_rp + 2'd1;
              end
if (ln_pop) begin
    out_q    <= ln_data;
    out_tag  <= ln_tag[2:0];
    out_last <= ln_last;
    out_par  <= ^ln_data;
    out_v    <= 1'b1;
    if (ln_last)
        cnt <= 4'd0;
    else
        cnt <= cnt + 4'd1;
end
if (eq_pop) begin
    ln_data <= eq_data[eq_rp];
    ln_tag  <= eq_head_tag;
    eq_rp   <= eq_rp + 1'b1;
end
if (eq_pop)
    ln_v <= 1'b1;
else if (ln_pop)
    ln_v <= 1'b0;
              case ({eq_push, eq_pop})
                  2'b10:   eq_used <= eq_used + 2'd1;
                  2'b01:   eq_used <= eq_used - 2'd1;
                  default: eq_used <= eq_used;
              endcase
               case ({pf_push, pf_pop})
                   2'b10:   pf_used <= pf_used + 3'd1;
                   2'b01:   pf_used <= pf_used - 3'd1;
                   default: pf_used <= pf_used;
               endcase
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output wire [3:0]   pipe_vld,
output wire [2:0]   out_tag,
output reg  [31:0]  dbg_stat
,
    output wire [3:0] cnt_o,
    output wire [2:0] rd_ptr_o,
    output wire [2:0] st0_idx_o,
    output wire st0_v_o,
    output wire [2:0] st1_idx_o,
    output wire st1_v_o,
    output wire [2:0] st2_idx_o,
    output wire st2_v_o,
    output wire [2:0] st3_idx_o,
    output wire st3_v_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg [127:0] st0_q, st1_q, st2_q, st3_q;
reg [2:0]   st0_idx, st1_idx, st2_idx, st3_idx;
reg         st0_v, st1_v, st2_v, st3_v;
assign pipe_vld = {st3_v, st2_v, st1_v, st0_v};
assign out_tag  = st3_idx;
reg [7:0]  start_cnt;
reg [7:0]  stop_cnt;
reg [15:0] beat_cnt;
reg [15:0] csum;
reg [11:0] idle_wdog;
reg        wdog_flag;
reg        err_flag;
reg        seq_err;
reg [2:0]  last_tag;

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
st0_q = 128'h0; st1_q = 128'h0; st2_q = 128'h0; st3_q = 128'h0;
st0_idx = 3'd0; st1_idx = 3'd0; st2_idx = 3'd0; st3_idx = 3'd0;
st0_v = 1'b0; st1_v = 1'b0; st2_v = 1'b0; st3_v = 1'b0;
start_cnt = 8'd0;
stop_cnt  = 8'd0;
beat_cnt  = 16'd0;
csum      = 16'd0;
idle_wdog = 12'd0;
wdog_flag = 1'b0;
err_flag  = 1'b0;
seq_err   = 1'b0;
last_tag  = 3'd7;
dbg_stat  = 32'd0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
st0_q <= 128'h0; st1_q <= 128'h0; st2_q <= 128'h0; st3_q <= 128'h0;
st0_idx <= 3'd0; st1_idx <= 3'd0; st2_idx <= 3'd0; st3_idx <= 3'd0;
st0_v <= 1'b0; st1_v <= 1'b0; st2_v <= 1'b0; st3_v <= 1'b0;
start_cnt <= 8'd0;
stop_cnt  <= 8'd0;
beat_cnt  <= 16'd0;
csum      <= 16'd0;
idle_wdog <= 12'd0;
wdog_flag <= 1'b0;
err_flag  <= 1'b0;
seq_err   <= 1'b0;
last_tag  <= 3'd7;
dbg_stat  <= 32'd0;
        end else if (en) begin
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
st0_v  <= 1'b0;
st1_v  <= 1'b0;
st2_v  <= 1'b0;
st3_v  <= 1'b0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
st0_q   <= rom_word;
st0_idx <= rd_ptr;
st0_v   <= 1'b1;
st1_q   <= st0_q;
st1_idx <= st0_idx;
st1_v   <= st0_v;
st2_q   <= st1_q;
st2_idx <= st1_idx;
st2_v   <= st1_v;
st3_q   <= st2_q;
st3_idx <= st2_idx;
st3_v   <= st2_v;
if (st3_v) begin
out_q <= st3_q;
out_v <= 1'b1;
if (st3_idx == 3'd7)
cnt <= 4'd0;
else
cnt <= cnt + 4'd1;
end
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                end
            end
        end
if (rst_n) begin
if (en) begin
if (start)
start_cnt <= start_cnt + 8'd1;
if (stop)
stop_cnt <= stop_cnt + 8'd1;
if (start && stop)
err_flag <= 1'b1;
if (start || win)
idle_wdog <= 12'd0;
else if (idle_wdog != 12'hFFF)
idle_wdog <= idle_wdog + 12'd1;
if (idle_wdog == 12'hFFE)
wdog_flag <= 1'b1;
if (start)
last_tag <= 3'd7;
if (win && !start && !stop && st3_v) begin
beat_cnt <= beat_cnt + 16'd1;
csum     <= {csum[14:0], csum[15]} ^ st3_q[15:0] ^ st3_q[127:112];
last_tag <= st3_idx;
if (st3_idx != last_tag + 3'd1)
seq_err <= 1'b1;
end
end
dbg_stat <= {wdog_flag, err_flag, seq_err, idle_wdog[4:0], start_cnt ^ stop_cnt, beat_cnt ^ csum};
end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
    assign cnt_o = cnt;
    assign rd_ptr_o = rd_ptr;
    assign st0_idx_o = st0_idx;
    assign st0_v_o = st0_v;
    assign st1_idx_o = st1_idx;
    assign st1_v_o = st1_v;
    assign st2_idx_o = st2_idx;
    assign st2_v_o = st2_v;
    assign st3_idx_o = st3_idx;
    assign st3_v_o = st3_v;
endmodule

module xbar_route_pool (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [3:0]   req,
    input  wire [3:0]   start,
    input  wire [3:0]   stop,
    output reg  [127:0] out_q,
    output reg          out_v,
    output reg  [1:0]   out_src,
    output wire [3:0]   frame_v,
    output wire [11:0]  out_tag_all,
    output wire [15:0]  pipe_vld_all,
    output wire [127:0] dbg_all,
    output wire [1:0]   pool_o,
    output wire [3:0]   hold_o
);
    reg [1:0] pool;
    reg       h0, h1, h2, h3;

    initial begin
        pool = 2'd2;
        h0 = 1'b0; h1 = 1'b0; h2 = 1'b0; h3 = 1'b0;
    end

    wire [127:0] t0_out_q, t1_out_q, t2_out_q, t3_out_q;
    wire         t0_out_v, t1_out_v, t2_out_v, t3_out_v;
    wire [3:0]   t0_pipe_vld, t1_pipe_vld, t2_pipe_vld, t3_pipe_vld;
    wire [2:0]   t0_out_tag, t1_out_tag, t2_out_tag, t3_out_tag;
    wire [31:0]  t0_dbg, t1_dbg, t2_dbg, t3_dbg;
    wire [3:0]   t0_cnt, t1_cnt, t2_cnt, t3_cnt;
    wire [2:0]   t0_rd_ptr, t1_rd_ptr, t2_rd_ptr, t3_rd_ptr;
    wire [2:0]   t0_st0_idx, t0_st1_idx, t0_st2_idx, t0_st3_idx;
    wire [2:0]   t1_st0_idx, t1_st1_idx, t1_st2_idx, t1_st3_idx;
    wire [2:0]   t2_st0_idx, t2_st1_idx, t2_st2_idx, t2_st3_idx;
    wire [2:0]   t3_st0_idx, t3_st1_idx, t3_st2_idx, t3_st3_idx;
    wire         t0_st0_v, t0_st1_v, t0_st2_v, t0_st3_v;
    wire         t1_st0_v, t1_st1_v, t1_st2_v, t1_st3_v;
    wire         t2_st0_v, t2_st1_v, t2_st2_v, t2_st3_v;
    wire         t3_st0_v, t3_st1_v, t3_st2_v, t3_st3_v;

    wire t0_en = en && h0;
    wire t1_en = en && h1;
    wire t2_en = en && h2;
    wire t3_en = en && h3;

    xbar_route_rom u0 (.clk(clk), .rst_n(rst_n), .en(t0_en), .start(start[0]), .stop(stop[0]),
        .out_q(t0_out_q), .out_v(t0_out_v), .pipe_vld(t0_pipe_vld), .out_tag(t0_out_tag), .dbg_stat(t0_dbg),
        .cnt_o(t0_cnt), .rd_ptr_o(t0_rd_ptr),
        .st0_idx_o(t0_st0_idx), .st0_v_o(t0_st0_v), .st1_idx_o(t0_st1_idx), .st1_v_o(t0_st1_v),
        .st2_idx_o(t0_st2_idx), .st2_v_o(t0_st2_v), .st3_idx_o(t0_st3_idx), .st3_v_o(t0_st3_v));

    xbar_route_rom u1 (.clk(clk), .rst_n(rst_n), .en(t1_en), .start(start[1]), .stop(stop[1]),
        .out_q(t1_out_q), .out_v(t1_out_v), .pipe_vld(t1_pipe_vld), .out_tag(t1_out_tag), .dbg_stat(t1_dbg),
        .cnt_o(t1_cnt), .rd_ptr_o(t1_rd_ptr),
        .st0_idx_o(t1_st0_idx), .st0_v_o(t1_st0_v), .st1_idx_o(t1_st1_idx), .st1_v_o(t1_st1_v),
        .st2_idx_o(t1_st2_idx), .st2_v_o(t1_st2_v), .st3_idx_o(t1_st3_idx), .st3_v_o(t1_st3_v));

    xbar_route_rom u2 (.clk(clk), .rst_n(rst_n), .en(t2_en), .start(start[2]), .stop(stop[2]),
        .out_q(t2_out_q), .out_v(t2_out_v), .pipe_vld(t2_pipe_vld), .out_tag(t2_out_tag), .dbg_stat(t2_dbg),
        .cnt_o(t2_cnt), .rd_ptr_o(t2_rd_ptr),
        .st0_idx_o(t2_st0_idx), .st0_v_o(t2_st0_v), .st1_idx_o(t2_st1_idx), .st1_v_o(t2_st1_v),
        .st2_idx_o(t2_st2_idx), .st2_v_o(t2_st2_v), .st3_idx_o(t2_st3_idx), .st3_v_o(t2_st3_v));

    xbar_route_rom u3 (.clk(clk), .rst_n(rst_n), .en(t3_en), .start(start[3]), .stop(stop[3]),
        .out_q(t3_out_q), .out_v(t3_out_v), .pipe_vld(t3_pipe_vld), .out_tag(t3_out_tag), .dbg_stat(t3_dbg),
        .cnt_o(t3_cnt), .rd_ptr_o(t3_rd_ptr),
        .st0_idx_o(t3_st0_idx), .st0_v_o(t3_st0_v), .st1_idx_o(t3_st1_idx), .st1_v_o(t3_st1_v),
        .st2_idx_o(t3_st2_idx), .st2_v_o(t3_st2_v), .st3_idx_o(t3_st3_idx), .st3_v_o(t3_st3_v));

    // credit return: frame end (last ROM index leaving stage 3) or lane stopped
    wire r0 = h0 && en && (stop[0] || (!start[0] && t0_st3_v && t0_st3_idx == 3'd7));
    wire r1 = h1 && en && (stop[1] || (!start[1] && t1_st3_v && t1_st3_idx == 3'd7));
    wire r2 = h2 && en && (stop[2] || (!start[2] && t2_st3_v && t2_st3_idx == 3'd7));
    wire r3 = h3 && en && (stop[3] || (!start[3] && t3_st3_v && t3_st3_idx == 3'd7));

    // one grant per cycle, fixed priority, only from a non-empty pool
    wire credit_ok = en && (pool != 2'd0);
    wire g0 = credit_ok && req[0] && !h0;
    wire g1 = credit_ok && req[1] && !h1 && !g0;
    wire g2 = credit_ok && req[2] && !h2 && !g0 && !g1;
    wire g3 = credit_ok && req[3] && !h3 && !g0 && !g1 && !g2;
    wire g_any = g0 || g1 || g2 || g3;

    wire [2:0] rel_cnt = {2'b00, r0} + {2'b00, r1} + {2'b00, r2} + {2'b00, r3};
    wire [2:0] pool_nx = {1'b0, pool} + rel_cnt - {2'b00, g_any};

    always @(posedge clk) begin
        if (!rst_n) begin
            pool <= 2'd2;
            h0 <= 1'b0; h1 <= 1'b0; h2 <= 1'b0; h3 <= 1'b0;
        end else begin
            pool <= pool_nx[1:0];
            h0 <= g0 || (h0 && !r0);
            h1 <= g1 || (h1 && !r1);
            h2 <= g2 || (h2 && !r2);
            h3 <= g3 || (h3 && !r3);
        end
    end

    // output port: lowest credited lane with valid data drives the shared bus
    always @(*) begin
        out_q   = 128'h0;
        out_v   = 1'b0;
        out_src = 2'd0;
        if (h0 && t0_out_v) begin
            out_q = t0_out_q; out_v = 1'b1; out_src = 2'd0;
        end else if (h1 && t1_out_v) begin
            out_q = t1_out_q; out_v = 1'b1; out_src = 2'd1;
        end else if (h2 && t2_out_v) begin
            out_q = t2_out_q; out_v = 1'b1; out_src = 2'd2;
        end else if (h3 && t3_out_v) begin
            out_q = t3_out_q; out_v = 1'b1; out_src = 2'd3;
        end
    end

    assign frame_v      = {t3_out_v, t2_out_v, t1_out_v, t0_out_v};
    assign out_tag_all  = {t3_out_tag, t2_out_tag, t1_out_tag, t0_out_tag};
    assign pipe_vld_all = {t3_pipe_vld, t2_pipe_vld, t1_pipe_vld, t0_pipe_vld};
    assign dbg_all      = {t3_dbg, t2_dbg, t1_dbg, t0_dbg};
    assign pool_o       = pool;
    assign hold_o       = {h3, h2, h1, h0};

    always @(posedge clk)
        assert (pool <= 2'd2);
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
   output reg          done,
   output wire         beat_ready,
   output wire [1:0]   q_level,
   output wire [127:0] q_head
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;

   // two-entry beat staging queue; the start comparator is evaluated on
   // entry so a later watchpoint rewrite cannot retroactively change it
   reg [127:0] q_data0, q_data1;
   reg q_st0, q_st1;
   reg q_rd, q_wr;
   reg [1:0] q_cnt;
   initial q_data0 = 128'h0;
   initial q_data1 = 128'h0;
   initial q_st0 = 1'b0;
   initial q_st1 = 1'b0;
   initial q_rd = 1'b0;
   initial q_wr = 1'b0;
   initial q_cnt = 2'd0;

   wire q_full = (q_cnt == 2'd2);
   wire q_hv   = (q_cnt != 2'd0);
   wire q_hst  = q_rd ? q_st1 : q_st0;
   assign q_head     = q_rd ? q_data1 : q_data0;
   assign q_level    = q_cnt;
   assign beat_ready = !q_full;
   // pops stall while the watchpoint port is being written
   wire q_pop  = en && !clr_cmd && q_hv && !wr_en;
   wire q_push = en && !clr_cmd && beat_valid && (!q_full || q_pop);

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
   wire match1 = q_hv && (((q_head ^ wval1) & wmask1) == 128'h0);
   wire start_hit = (fsm == S_ARMED) && match0;

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
           S_ARMED: if (q_pop && q_hst)  fsm_nxt = S_RUN;
           S_RUN:   if (q_pop && match1) fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
           q_data0 <= 128'h0;
           q_data1 <= 128'h0;
           q_st0 <= 1'b0;
           q_st1 <= 1'b0;
           q_rd <= 1'b0;
           q_wr <= 1'b0;
           q_cnt <= 2'd0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
               q_cnt <= 2'd0;
               q_rd <= 1'b0;
               q_wr <= 1'b0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
               if (start_hit && q_push) started_seen <= 1'b1;
               if (q_push) begin
                   if (q_wr) begin
                       q_data1 <= beat_data;
                       q_st1   <= start_hit;
                   end else begin
                       q_data0 <= beat_data;
                       q_st0   <= start_hit;
                   end
                   q_wr <= !q_wr;
               end
               if (q_pop) q_rd <= !q_rd;
               if (q_push && !q_pop) q_cnt <= q_cnt + 2'd1;
               else if (q_pop && !q_push) q_cnt <= q_cnt - 2'd1;
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
output reg         fault,
output reg  [3:0]  n_acc_in,   // accesses accepted into the lookup stage
output reg  [3:0]  n_acc_out,  // accesses retired from the lookup stage
output reg  [15:0] dbg_status   // rotating debug/statistics readout
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;
initial n_acc_in  = 4'd0;
initial n_acc_out = 4'd0;
   // ---- debug / statistics bank (observability only) ----
   reg [7:0]  dbg_grant_cnt   = 8'd0;
   reg [7:0]  dbg_fault_cnt   = 8'd0;
   reg [5:0]  dbg_cfg_wr_cnt  = 6'd0;
   reg [5:0]  dbg_cfg_rej_cnt = 6'd0;
   reg [7:0]  dbg_idle_cnt    = 8'd0;
   reg        dbg_wdog_trip   = 1'b0;
   reg [15:0] dbg_addr_d1     = 16'd0;
   reg [15:0] dbg_fault_addr  = 16'd0;
   reg [1:0]  dbg_sel         = 2'd0;
   initial dbg_status = 16'd0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
// a hit retiring while the ledger shows nothing outstanding is a spurious response
fault  <= miss_q || (hit_q && (n_acc_in == n_acc_out));
if (acc_valid)
    n_acc_in <= n_acc_in + 4'd1;
if (hit_q || miss_q)
    n_acc_out <= n_acc_out + 4'd1;
        end
    end

    always @(posedge clk) pv <= 1'b1;

   always @(posedge clk) begin
       if (i_ce) begin
           dbg_addr_d1 <= acc_addr;
           if (grant && (dbg_grant_cnt != 8'hFF))
               dbg_grant_cnt <= dbg_grant_cnt + 8'd1;
           if (fault && (dbg_fault_cnt != 8'hFF))
               dbg_fault_cnt <= dbg_fault_cnt + 8'd1;
           if (miss_q)
               dbg_fault_addr <= dbg_addr_d1;
           if (cfg_we) begin
               if (pre_lock && (cfg_idx < 5'd24))
                   dbg_cfg_wr_cnt <= dbg_cfg_wr_cnt + 6'd1;
               else
                   dbg_cfg_rej_cnt <= dbg_cfg_rej_cnt + 6'd1;
           end
           if (acc_valid) begin
               dbg_idle_cnt  <= 8'd0;
               dbg_wdog_trip <= 1'b0;
           end else if (dbg_idle_cnt == 8'hFF)
               dbg_wdog_trip <= 1'b1;
           else
               dbg_idle_cnt <= dbg_idle_cnt + 8'd1;
           dbg_sel <= dbg_sel + 2'd1;
           case (dbg_sel)
               2'd0:    dbg_status <= {dbg_grant_cnt, dbg_fault_cnt};
               2'd1:    dbg_status <= {dbg_cfg_wr_cnt, dbg_cfg_rej_cnt, pre_lock, dbg_wdog_trip, 2'b00};
               2'd2:    dbg_status <= dbg_fault_addr;
               default: dbg_status <= {dbg_idle_cnt, 4'd0, n_acc_in - n_acc_out};
           endcase
       end
   end

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  stat_o,
output reg  [2:0]   out_tag,
output reg          out_last,
output reg          out_par,
output wire [1:0]   eq_lvl_o,
output wire [15:0]  eq_stall_o,
output wire         ln_busy_o,
output wire [2:0]   ra_lvl_o,
output reg  [2:0]   ra_hwm_o,
output reg  [7:0]   ra_lat_o,
output reg  [15:0]  ra_perr_o,
output reg  [15:0]  ra_blk_o,
output reg  [15:0]  ra_byp_o,
output reg  [15:0]  ra_fetch_o,
output wire [2:0]   rb_lvl_o,
output wire [3:0]   ra_tot_o,
output reg  [2:0]   rb_hwm_o,
output reg  [7:0]   rb_lat_o,
output reg  [15:0]  rb_perr_o,
output reg  [15:0]  rb_blk_o,
output reg  [15:0]  rb_fetch_o,
output reg  [15:0]  bk_coll_o,
output reg  [15:0]  ra_pop_o,
output reg  [15:0]  rb_pop_o,
output reg  [15:0]  ra_occ_o,
output reg  [15:0]  rb_occ_o,
output reg  [15:0]  ra_old_o,
output reg  [15:0]  rb_old_o,
output reg  [3:0]   bk_ferr_o,
output reg          bk_ferr_v_o,
output reg  [31:0]  bk_stat_o,
output wire         beat_post_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
// posted beat retirement: a delivered beat is committed into cnt on the
// following window cycle, keeping the counter adder off the lane grant path
reg       cnt_pnd;
reg [15:0] start_cnt;
reg [15:0] stop_cnt;
reg [15:0] beat_cnt;
reg [7:0]  wrap_cnt;
reg [15:0] idle_cnt;
reg        err_sticky;
reg [1:0]  stat_sel;
reg [127:0] pf_data [0:3];
reg [3:0]   pf_tag  [0:3];
reg [1:0]   pf_wp;
reg [1:0]   pf_rp;
reg [2:0]   pf_used;
// egress retiming queue: decouples prefetch from the shared lane grant
reg [127:0] eq_data [0:1];
reg [3:0]   eq_tag  [0:1];
reg         eq_wp;
reg         eq_rp;
reg [1:0]   eq_used;
reg [15:0]  stall_cnt;
// lane output register: one beat parked until this source's grant slot
reg [127:0] ln_data;
reg [3:0]   ln_tag;
reg         ln_v;
// ROM read-ahead register file: fetches run ahead of prefetch acceptance;
// every slot keeps its own valid bit, write-time parity and fetch stamp
reg [127:0] ra_data [0:3];
reg [3:0]   ra_tag  [0:3];
reg [7:0]   ra_ts   [0:3];
reg [3:0]   ra_par;
reg [3:0]   ra_v;
reg [1:0]   ra_wp;
reg [1:0]   ra_rp;
// second read-ahead bank: the ROM port alternates between the two banks by
// word address (even words to ra, odd words to rb); both banks drain through
// the single prefetch write port, oldest word first
reg [127:0] rb_data [0:3];
reg [3:0]   rb_tag  [0:3];
reg [7:0]   rb_ts   [0:3];
reg [3:0]   rb_par;
reg [3:0]   rb_v;
reg [1:0]   rb_wp;
reg [1:0]   rb_rp;

    initial begin
start_cnt  = 16'd0;
stop_cnt   = 16'd0;
beat_cnt   = 16'd0;
wrap_cnt   = 8'd0;
idle_cnt   = 16'd0;
err_sticky = 1'b0;
stat_sel   = 2'd0;
stat_o     = 32'h0;
pf_data[0] = 128'h0;
pf_data[1] = 128'h0;
pf_data[2] = 128'h0;
pf_data[3] = 128'h0;
pf_tag[0]  = 4'd0;
pf_tag[1]  = 4'd0;
pf_tag[2]  = 4'd0;
pf_tag[3]  = 4'd0;
pf_wp      = 2'd0;
pf_rp      = 2'd0;
pf_used    = 3'd0;
eq_data[0] = 128'h0;
eq_data[1] = 128'h0;
eq_tag[0]  = 4'd0;
eq_tag[1]  = 4'd0;
eq_wp      = 1'b0;
eq_rp      = 1'b0;
eq_used    = 2'd0;
stall_cnt  = 16'd0;
ln_data    = 128'h0;
ln_tag     = 4'd0;
ln_v       = 1'b0;
ra_data[0] = 128'h0;
ra_data[1] = 128'h0;
ra_data[2] = 128'h0;
ra_data[3] = 128'h0;
ra_tag[0]  = 4'd0;
ra_tag[1]  = 4'd0;
ra_tag[2]  = 4'd0;
ra_tag[3]  = 4'd0;
ra_ts[0]   = 8'd0;
ra_ts[1]   = 8'd0;
ra_ts[2]   = 8'd0;
ra_ts[3]   = 8'd0;
ra_par     = 4'd0;
ra_v       = 4'd0;
ra_wp      = 2'd0;
ra_rp      = 2'd0;
ra_hwm_o   = 3'd0;
ra_lat_o   = 8'd0;
ra_perr_o  = 16'd0;
ra_blk_o   = 16'd0;
ra_byp_o   = 16'd0;
ra_fetch_o = 16'd0;
rb_data[0] = 128'h0;
rb_data[1] = 128'h0;
rb_data[2] = 128'h0;
rb_data[3] = 128'h0;
rb_tag[0]  = 4'd0;
rb_tag[1]  = 4'd0;
rb_tag[2]  = 4'd0;
rb_tag[3]  = 4'd0;
rb_ts[0]   = 8'd0;
rb_ts[1]   = 8'd0;
rb_ts[2]   = 8'd0;
rb_ts[3]   = 8'd0;
rb_par     = 4'd0;
rb_v       = 4'd0;
rb_wp      = 2'd0;
rb_rp      = 2'd0;
rb_hwm_o   = 3'd0;
rb_lat_o   = 8'd0;
rb_perr_o  = 16'd0;
rb_blk_o   = 16'd0;
rb_fetch_o = 16'd0;
bk_coll_o  = 16'd0;
ra_pop_o   = 16'd0;
rb_pop_o   = 16'd0;
ra_occ_o   = 16'd0;
rb_occ_o   = 16'd0;
ra_old_o   = 16'd0;
rb_old_o   = 16'd0;
bk_ferr_o  = 4'd0;
bk_ferr_v_o = 1'b0;
bk_stat_o  = 32'h0;
out_tag    = 3'd0;
out_last   = 1'b0;
out_par    = 1'b0;
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
cnt_pnd = 1'b0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end
   // shared crossbar lane: this source owns the even arbitration slots
   wire       slot_gnt    = ~stat_sel[0];
   wire       pf_full     = (pf_used == 3'd4);
   wire       pf_empty    = (pf_used == 3'd0);
   wire       eq_full     = (eq_used == 2'd2);
   wire       eq_empty    = (eq_used == 2'd0);
// the lane holds while a retired beat is still posted to the counter
wire       ln_pop      = win && ln_v && slot_gnt && !cnt_pnd;
wire       ln_last     = (ln_tag == 4'd7);
wire       eq_pop      = win && !eq_empty && (!ln_v || ln_pop);
   wire       pf_pop      = win && !pf_empty && (!eq_full || eq_pop);
   wire       eq_push     = pf_pop;
// read-ahead control: slots are filled in order at ra_wp, drained at ra_rp
wire [2:0]   ra_lvl       = {2'b0, ra_v[0]} + {2'b0, ra_v[1]} + {2'b0, ra_v[2]} + {2'b0, ra_v[3]};
wire         ra_head_v    = ra_v[ra_rp];
wire         ra_slot_v    = ra_v[ra_wp];
wire [2:0]   rb_lvl       = {2'b0, rb_v[0]} + {2'b0, rb_v[1]} + {2'b0, rb_v[2]} + {2'b0, rb_v[3]};
wire [3:0]   ra_tot       = {1'b0, ra_lvl} + {1'b0, rb_lvl};
// even ROM words fill bank a, odd words fill bank b; the oldest buffered
// word was fetched ra_tot fetches back, so its address parity names the head bank
wire         ra_fsel      = rd_ptr[0];
wire         ra_hsel      = rd_ptr[0] ^ ra_tot[0];
wire         rb_head_v    = rb_v[rb_rp];
wire         rb_slot_v    = rb_v[rb_wp];
wire         bk_head_v    = ra_hsel ? rb_head_v : ra_head_v;
wire         pf_room      = !pf_full || pf_pop;
wire         bk_pop       = win && bk_head_v && pf_room;
wire         ra_pop       = bk_pop && !ra_hsel;
wire         rb_pop       = bk_pop && ra_hsel;
// empty buffer: the ROM word goes straight into prefetch, saving a cycle
wire         ra_byp       = win && (ra_tot == 4'd0) && pf_room;
// a bank may accept the fetch if its fill slot is free or is being drained now
wire         ra_fill_ok   = !ra_slot_v || (ra_pop && (ra_wp == ra_rp));
wire         rb_fill_ok   = !rb_slot_v || (rb_pop && (rb_wp == rb_rp));
wire         bk_push      = win && !ra_byp && (ra_fsel ? rb_fill_ok : ra_fill_ok);
wire         ra_push      = bk_push && !ra_fsel;
wire         rb_push      = bk_push && ra_fsel;
wire         rom_take     = bk_push || ra_byp;
wire         pf_push      = bk_pop || ra_byp;
wire [3:0]   ra_set       = ra_push ? (4'b0001 << ra_wp) : 4'b0000;
wire [3:0]   ra_clr       = ra_pop  ? (4'b0001 << ra_rp) : 4'b0000;
wire [3:0]   ra_v_nxt     = (ra_v & ~ra_clr) | ra_set;
wire [3:0]   rb_set       = rb_push ? (4'b0001 << rb_wp) : 4'b0000;
wire [3:0]   rb_clr       = rb_pop  ? (4'b0001 << rb_rp) : 4'b0000;
wire [3:0]   rb_v_nxt     = (rb_v & ~rb_clr) | rb_set;
wire [127:0] ra_head_data = ra_data[ra_rp];
wire [3:0]   ra_head_tag  = ra_tag[ra_rp];
wire [7:0]   ra_res       = beat_cnt[7:0] - ra_ts[ra_rp];
wire         ra_par_bad   = ra_par[ra_rp] ^ (^ra_head_data);
wire [127:0] rb_head_data = rb_data[rb_rp];
wire [3:0]   rb_head_tag  = rb_tag[rb_rp];
wire [7:0]   rb_res       = beat_cnt[7:0] - rb_ts[rb_rp];
wire         rb_par_bad   = rb_par[rb_rp] ^ (^rb_head_data);
// a head word that has waited too long points at a starved prefetch port
wire         ra_stale     = ra_head_v && (ra_res > 8'd48);
wire         rb_stale     = rb_head_v && (rb_res > 8'd48);
wire         rom_par      = ^rom_word;
wire [127:0] bk_head_data = ra_hsel ? rb_head_data : ra_head_data;
wire [3:0]   bk_head_tag  = ra_hsel ? rb_head_tag  : ra_head_tag;
wire [127:0] pf_in_data   = ra_byp ? rom_word : bk_head_data;
wire [3:0]   pf_in_tag    = ra_byp ? {1'b0, rd_ptr} : bk_head_tag;
wire         ra_blk       = win && !ra_fsel && ra_slot_v && !rom_take;
wire         rb_blk       = win && ra_fsel && rb_slot_v && !rom_take;
// same bank written and read in one cycle: needs the bypassing write port
wire         bk_coll      = bk_push && bk_pop && (ra_fsel == ra_hsel);
assign ra_lvl_o = ra_lvl;
assign rb_lvl_o = rb_lvl;
assign ra_tot_o = ra_tot;
   wire [3:0] pf_head_tag = pf_tag[pf_rp];
   wire [3:0] eq_head_tag = eq_tag[eq_rp];
   wire       eq_last     = (eq_head_tag == 4'd7);
   wire       pf_stall    = win && !pf_empty && !pf_pop;
   assign eq_lvl_o   = eq_used;
   assign eq_stall_o = stall_cnt;
assign ln_busy_o  = ln_v;
assign beat_post_o = cnt_pnd;

    always @(posedge clk) begin
        if (!rst_n) begin
start_cnt  <= 16'd0;
stop_cnt   <= 16'd0;
beat_cnt   <= 16'd0;
wrap_cnt   <= 8'd0;
idle_cnt   <= 16'd0;
err_sticky <= 1'b0;
stat_sel   <= 2'd0;
stat_o     <= 32'h0;
pf_data[0] <= 128'h0;
pf_data[1] <= 128'h0;
pf_data[2] <= 128'h0;
pf_data[3] <= 128'h0;
pf_tag[0]  <= 4'd0;
pf_tag[1]  <= 4'd0;
pf_tag[2]  <= 4'd0;
pf_tag[3]  <= 4'd0;
pf_wp      <= 2'd0;
pf_rp      <= 2'd0;
pf_used    <= 3'd0;
eq_data[0] <= 128'h0;
eq_data[1] <= 128'h0;
eq_tag[0]  <= 4'd0;
eq_tag[1]  <= 4'd0;
eq_wp      <= 1'b0;
eq_rp      <= 1'b0;
eq_used    <= 2'd0;
stall_cnt  <= 16'd0;
ln_data    <= 128'h0;
ln_tag     <= 4'd0;
ln_v       <= 1'b0;
ra_data[0] <= 128'h0;
ra_data[1] <= 128'h0;
ra_data[2] <= 128'h0;
ra_data[3] <= 128'h0;
ra_tag[0]  <= 4'd0;
ra_tag[1]  <= 4'd0;
ra_tag[2]  <= 4'd0;
ra_tag[3]  <= 4'd0;
ra_ts[0]   <= 8'd0;
ra_ts[1]   <= 8'd0;
ra_ts[2]   <= 8'd0;
ra_ts[3]   <= 8'd0;
ra_par     <= 4'd0;
ra_v       <= 4'd0;
ra_wp      <= 2'd0;
ra_rp      <= 2'd0;
ra_hwm_o   <= 3'd0;
ra_lat_o   <= 8'd0;
ra_perr_o  <= 16'd0;
ra_blk_o   <= 16'd0;
ra_byp_o   <= 16'd0;
ra_fetch_o <= 16'd0;
rb_data[0] <= 128'h0;
rb_data[1] <= 128'h0;
rb_data[2] <= 128'h0;
rb_data[3] <= 128'h0;
rb_tag[0]  <= 4'd0;
rb_tag[1]  <= 4'd0;
rb_tag[2]  <= 4'd0;
rb_tag[3]  <= 4'd0;
rb_ts[0]   <= 8'd0;
rb_ts[1]   <= 8'd0;
rb_ts[2]   <= 8'd0;
rb_ts[3]   <= 8'd0;
rb_par     <= 4'd0;
rb_v       <= 4'd0;
rb_wp      <= 2'd0;
rb_rp      <= 2'd0;
rb_hwm_o   <= 3'd0;
rb_lat_o   <= 8'd0;
rb_perr_o  <= 16'd0;
rb_blk_o   <= 16'd0;
rb_fetch_o <= 16'd0;
bk_coll_o  <= 16'd0;
ra_pop_o   <= 16'd0;
rb_pop_o   <= 16'd0;
ra_occ_o   <= 16'd0;
rb_occ_o   <= 16'd0;
ra_old_o   <= 16'd0;
rb_old_o   <= 16'd0;
bk_ferr_o  <= 4'd0;
bk_ferr_v_o <= 1'b0;
bk_stat_o  <= 32'h0;
out_tag    <= 3'd0;
out_last   <= 1'b0;
out_par    <= 1'b0;
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
cnt_pnd <= 1'b0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
if (start)
    start_cnt <= start_cnt + 16'd1;
if (stop)
    stop_cnt <= stop_cnt + 16'd1;
if (start && stop)
    err_sticky <= 1'b1;
if (win && !start && !stop) begin
    beat_cnt <= beat_cnt + 16'd1;
if (ln_pop && ln_last)
        wrap_cnt <= wrap_cnt + 8'd1;
end
if (!win)
    idle_cnt <= idle_cnt + 16'd1;
if (pf_stall && !start && !stop)
    stall_cnt <= stall_cnt + 16'd1;
if (ra_blk && !start && !stop)
    ra_blk_o <= ra_blk_o + 16'd1;
if (ra_lvl > ra_hwm_o)
    ra_hwm_o <= ra_lvl;
if (rb_lvl > rb_hwm_o)
    rb_hwm_o <= rb_lvl;
if (rb_blk && !start && !stop)
    rb_blk_o <= rb_blk_o + 16'd1;
if (win && !start && !stop) begin
    ra_occ_o <= ra_occ_o + {13'h0, ra_lvl};
    rb_occ_o <= rb_occ_o + {13'h0, rb_lvl};
    if (ra_stale)
        ra_old_o <= ra_old_o + 16'd1;
    if (rb_stale)
        rb_old_o <= rb_old_o + 16'd1;
end
stat_sel <= stat_sel + 2'd1;
case (stat_sel)
    2'd0: stat_o <= {start_cnt, stop_cnt};
    2'd1: stat_o <= {beat_cnt, idle_cnt};
2'd2: stat_o <= {3'h0, eq_used, pf_used, wrap_cnt, 9'h0, rb_lvl, ra_lvl, err_sticky};
    default: stat_o <= {err_sticky, 7'h0, wrap_cnt, beat_cnt};
endcase
case (stat_sel)
    2'd0: bk_stat_o <= {ra_pop_o, rb_pop_o};
    2'd1: bk_stat_o <= {ra_occ_o, rb_occ_o};
    2'd2: bk_stat_o <= {ra_old_o, rb_old_o};
    default: bk_stat_o <= {bk_ferr_v_o, 3'h0, bk_ferr_o, 8'h0, rb_lat_o, ra_lat_o};
endcase
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
cnt_pnd <= 1'b0;
               pf_wp   <= 2'd0;
               pf_rp   <= 2'd0;
               pf_used <= 3'd0;
               eq_wp   <= 1'b0;
               eq_rp   <= 1'b0;
               eq_used <= 2'd0;
ln_v    <= 1'b0;
ra_v    <= 4'd0;
ra_wp   <= 2'd0;
ra_rp   <= 2'd0;
rb_v    <= 4'd0;
rb_wp   <= 2'd0;
rb_rp   <= 2'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
               if (rom_take) begin
                   rd_ptr     <= rd_ptr + 3'd1;
                   ra_fetch_o <= ra_fetch_o + 16'd1;
               end
               if (ra_byp)
                   ra_byp_o <= ra_byp_o + 16'd1;
if (rb_push)
    rb_fetch_o <= rb_fetch_o + 16'd1;
if (bk_coll)
    bk_coll_o <= bk_coll_o + 16'd1;
if (rb_push) begin
    rb_data[rb_wp] <= rom_word;
    rb_tag[rb_wp]  <= {1'b0, rd_ptr};
    rb_ts[rb_wp]   <= beat_cnt[7:0];
    rb_par[rb_wp]  <= rom_par;
    rb_wp          <= rb_wp + 2'd1;
end
               if (ra_push) begin
                   ra_data[ra_wp] <= rom_word;
                   ra_tag[ra_wp]  <= {1'b0, rd_ptr};
                   ra_ts[ra_wp]   <= beat_cnt[7:0];
                   ra_par[ra_wp]  <= rom_par;
                   ra_wp          <= ra_wp + 2'd1;
               end
               if (ra_pop) begin
                   ra_rp <= ra_rp + 2'd1;
                   if (ra_res > ra_lat_o)
                       ra_lat_o <= ra_res;
                   if (ra_par_bad)
                       ra_perr_o <= ra_perr_o + 16'd1;
ra_pop_o <= ra_pop_o + 16'd1;
if (ra_par_bad && !bk_ferr_v_o) begin
    bk_ferr_o   <= {1'b0, ra_head_tag[2:0]};
    bk_ferr_v_o <= 1'b1;
end
               end
if (rb_pop) begin
    rb_rp    <= rb_rp + 2'd1;
    rb_pop_o <= rb_pop_o + 16'd1;
    if (rb_res > rb_lat_o)
        rb_lat_o <= rb_res;
    if (rb_par_bad)
        rb_perr_o <= rb_perr_o + 16'd1;
    if (rb_par_bad && !bk_ferr_v_o) begin
        bk_ferr_o   <= {1'b1, rb_head_tag[2:0]};
        bk_ferr_v_o <= 1'b1;
    end
end
               ra_v <= ra_v_nxt;
rb_v <= rb_v_nxt;
               if (pf_push) begin
                   pf_data[pf_wp] <= pf_in_data;
                   pf_tag[pf_wp]  <= pf_in_tag;
                   pf_wp          <= pf_wp + 2'd1;
               end
               if (pf_pop) begin
                  eq_data[eq_wp] <= pf_data[pf_rp];
                  eq_tag[eq_wp]  <= pf_head_tag;
                  eq_wp          <= eq_wp + 1'b1;
                  pf_rp          <= pf_rp + 2'd1;
              end
if (ln_pop) begin
    out_q    <= ln_data;
    out_tag  <= ln_tag[2:0];
    out_last <= ln_last;
    out_par  <= ^ln_data;
    out_v    <= 1'b1;
    if (ln_last)
        cnt <= 4'd0;
    else
cnt_pnd <= 1'b1;
end else if (cnt_pnd) begin
cnt     <= cnt + 4'd1;
cnt_pnd <= 1'b0;
end
if (eq_pop) begin
    ln_data <= eq_data[eq_rp];
    ln_tag  <= eq_head_tag;
    eq_rp   <= eq_rp + 1'b1;
end
if (eq_pop)
    ln_v <= 1'b1;
else if (ln_pop)
    ln_v <= 1'b0;
              case ({eq_push, eq_pop})
                  2'b10:   eq_used <= eq_used + 2'd1;
                  2'b01:   eq_used <= eq_used - 2'd1;
                  default: eq_used <= eq_used;
              endcase
               case ({pf_push, pf_pop})
                   2'b10:   pf_used <= pf_used + 3'd1;
                   2'b01:   pf_used <= pf_used - 3'd1;
                   default: pf_used <= pf_used;
               endcase
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  stat_o,
output reg  [2:0]   out_tag,
output reg          out_last,
output reg          out_par,
output wire [1:0]   eq_lvl_o,
output wire [15:0]  eq_stall_o,
