output reg  [15:0]  rb_fetch_o,
output reg  [15:0]  bk_coll_o,
output reg  [15:0]  ra_pop_o,
output reg  [15:0]  rb_pop_o,
output reg  [15:0]  ra_occ_o,
output reg  [15:0]  rb_occ_o,
output reg  [15:0]  ra_old_o,
output reg  [15:0]  rb_old_o,
output reg  [3:0]   bk_ferr_o,
output reg          bk_ferr_v_o,
