rb_hwm_o   = 3'd0;
rb_lat_o   = 8'd0;
rb_perr_o  = 16'd0;
rb_blk_o   = 16'd0;
rb_fetch_o = 16'd0;
bk_coll_o  = 16'd0;
ra_pop_o   = 16'd0;
rb_pop_o   = 16'd0;
ra_occ_o   = 16'd0;
rb_occ_o   = 16'd0;
