bk_ferr_v_o = 1'b0;
bk_stat_o  = 32'h0;
pf_ins_o   = 16'd0;
pf_ret_o   = 16'd0;
out_tag    = 3'd0;
out_last   = 1'b0;
out_par    = 1'b0;
        win    = 1'b0;
        rd_ptr = 3'd0;
