ra_rp      <= 2'd0;
ra_hwm_o   <= 3'd0;
ra_lat_o   <= 8'd0;
ra_perr_o  <= 16'd0;
ra_blk_o   <= 16'd0;
ra_byp_o   <= 16'd0;
ra_fetch_o <= 16'd0;
rb_data[0] <= 128'h0;
rb_data[1] <= 128'h0;
