rb_data[3] <= 128'h0;
rb_tag[0]  <= 4'd0;
rb_tag[1]  <= 4'd0;
rb_tag[2]  <= 4'd0;
rb_tag[3]  <= 4'd0;
rb_ts[0]   <= 8'd0;
rb_ts[1]   <= 8'd0;
rb_ts[2]   <= 8'd0;
rb_ts[3]   <= 8'd0;
rb_par     <= 4'd0;
rb_v       <= 4'd0;
rb_wp      <= 2'd0;
rb_rp      <= 2'd0;
rb_hwm_o   <= 3'd0;
rb_lat_o   <= 8'd0;
rb_perr_o  <= 16'd0;
rb_blk_o   <= 16'd0;
rb_fetch_o <= 16'd0;
bk_coll_o  <= 16'd0;
ra_pop_o   <= 16'd0;
rb_pop_o   <= 16'd0;
ra_occ_o   <= 16'd0;
rb_occ_o   <= 16'd0;
ra_old_o   <= 16'd0;
rb_old_o   <= 16'd0;
bk_ferr_o  <= 4'd0;
bk_ferr_v_o <= 1'b0;
bk_stat_o  <= 32'h0;
pf_ins_o   <= 16'd0;
pf_ret_o   <= 16'd0;
out_tag    <= 3'd0;
out_last   <= 1'b0;
out_par    <= 1'b0;
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
cnt_pnd <= 1'b0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
if (start)
    start_cnt <= start_cnt + 16'd1;
if (stop)
    stop_cnt <= stop_cnt + 16'd1;
if (start && stop)
    err_sticky <= 1'b1;
if (win && !start && !stop) begin
    beat_cnt <= beat_cnt + 16'd1;
if (ln_pop && ln_last)
        wrap_cnt <= wrap_cnt + 8'd1;
end
if (!win)
    idle_cnt <= idle_cnt + 16'd1;
if (pf_stall && !start && !stop)
    stall_cnt <= stall_cnt + 16'd1;
if (ra_blk && !start && !stop)
    ra_blk_o <= ra_blk_o + 16'd1;
if (ra_lvl > ra_hwm_o)
    ra_hwm_o <= ra_lvl;
if (rb_lvl > rb_hwm_o)
    rb_hwm_o <= rb_lvl;
if (rb_blk && !start && !stop)
    rb_blk_o <= rb_blk_o + 16'd1;
if (win && !start && !stop) begin
    ra_occ_o <= ra_occ_o + {13'h0, ra_lvl};
    rb_occ_o <= rb_occ_o + {13'h0, rb_lvl};
    if (ra_stale)
        ra_old_o <= ra_old_o + 16'd1;
    if (rb_stale)
        rb_old_o <= rb_old_o + 16'd1;
end
stat_sel <= stat_sel + 2'd1;
case (stat_sel)
    2'd0: stat_o <= {start_cnt, stop_cnt};
    2'd1: stat_o <= {beat_cnt, idle_cnt};
2'd2: stat_o <= {3'h0, eq_used, pf_used, wrap_cnt, 9'h0, rb_lvl, ra_lvl, err_sticky};
    default: stat_o <= {err_sticky, 7'h0, wrap_cnt, beat_cnt};
endcase
case (stat_sel)
    2'd0: bk_stat_o <= {ra_pop_o, rb_pop_o};
    2'd1: bk_stat_o <= {ra_occ_o, rb_occ_o};
    2'd2: bk_stat_o <= {ra_old_o, rb_old_o};
    default: bk_stat_o <= {bk_ferr_v_o, 3'h0, bk_ferr_o, 8'h0, rb_lat_o, ra_lat_o};
endcase
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
cnt_pnd <= 1'b0;
               pf_wp   <= 2'd0;
               pf_rp   <= 2'd0;
               pf_used <= 3'd0;
pf_ret_o <= pf_ret_o + {13'h0, pf_used};
               eq_wp   <= 1'b0;
               eq_rp   <= 1'b0;
               eq_used <= 2'd0;
ln_v    <= 1'b0;
ra_v    <= 4'd0;
ra_wp   <= 2'd0;
ra_rp   <= 2'd0;
rb_v    <= 4'd0;
rb_wp   <= 2'd0;
rb_rp   <= 2'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
               if (rom_take) begin
                   rd_ptr     <= rd_ptr + 3'd1;
                   ra_fetch_o <= ra_fetch_o + 16'd1;
               end
               if (ra_byp)
                   ra_byp_o <= ra_byp_o + 16'd1;
if (rb_push)
    rb_fetch_o <= rb_fetch_o + 16'd1;
if (bk_coll)
    bk_coll_o <= bk_coll_o + 16'd1;
if (rb_push) begin
    rb_data[rb_wp] <= rom_word;
    rb_tag[rb_wp]  <= {1'b0, rd_ptr};
    rb_ts[rb_wp]   <= beat_cnt[7:0];
    rb_par[rb_wp]  <= rom_par;
    rb_wp          <= rb_wp + 2'd1;
end
               if (ra_push) begin
                   ra_data[ra_wp] <= rom_word;
                   ra_tag[ra_wp]  <= {1'b0, rd_ptr};
                   ra_ts[ra_wp]   <= beat_cnt[7:0];
                   ra_par[ra_wp]  <= rom_par;
                   ra_wp          <= ra_wp + 2'd1;
               end
               if (ra_pop) begin
                   ra_rp <= ra_rp + 2'd1;
                   if (ra_res > ra_lat_o)
                       ra_lat_o <= ra_res;
                   if (ra_par_bad)
                       ra_perr_o <= ra_perr_o + 16'd1;
ra_pop_o <= ra_pop_o + 16'd1;
if (ra_par_bad && !bk_ferr_v_o) begin
    bk_ferr_o   <= {1'b0, ra_head_tag[2:0]};
    bk_ferr_v_o <= 1'b1;
end
               end
if (rb_pop) begin
    rb_rp    <= rb_rp + 2'd1;
    rb_pop_o <= rb_pop_o + 16'd1;
    if (rb_res > rb_lat_o)
        rb_lat_o <= rb_res;
    if (rb_par_bad)
        rb_perr_o <= rb_perr_o + 16'd1;
    if (rb_par_bad && !bk_ferr_v_o) begin
        bk_ferr_o   <= {1'b1, rb_head_tag[2:0]};
        bk_ferr_v_o <= 1'b1;
    end
end
               ra_v <= ra_v_nxt;
rb_v <= rb_v_nxt;
               if (pf_push) begin
                   pf_data[pf_wp] <= pf_in_data;
                   pf_tag[pf_wp]  <= pf_in_tag;
                   pf_wp          <= pf_wp + 2'd1;
pf_ins_o       <= pf_ins_o + 16'd1;
               end
               if (pf_pop) begin
                  eq_data[eq_wp] <= pf_data[pf_rp];
                  eq_tag[eq_wp]  <= pf_head_tag;
                  eq_wp          <= eq_wp + 1'b1;
                  pf_rp          <= pf_rp + 2'd1;
pf_ret_o       <= pf_ret_o + 16'd1;
              end
if (ln_pop) begin
    out_q    <= ln_data;
    out_tag  <= ln_tag[2:0];
    out_last <= ln_last;
    out_par  <= ^ln_data;
    out_v    <= 1'b1;
    if (ln_last)
        cnt <= 4'd0;
    else
cnt_pnd <= 1'b1;
end else if (cnt_pnd) begin
cnt     <= cnt + 4'd1;
cnt_pnd <= 1'b0;
end
if (eq_pop) begin
    ln_data <= eq_data[eq_rp];
    ln_tag  <= eq_head_tag;
    eq_rp   <= eq_rp + 1'b1;
end
if (eq_pop)
    ln_v <= 1'b1;
else if (ln_pop)
    ln_v <= 1'b0;
              case ({eq_push, eq_pop})
                  2'b10:   eq_used <= eq_used + 2'd1;
                  2'b01:   eq_used <= eq_used - 2'd1;
                  default: eq_used <= eq_used;
              endcase
               case ({pf_push, pf_pop})
                   2'b10:   pf_used <= pf_used + 3'd1;
                   2'b01:   pf_used <= pf_used - 3'd1;
                   default: pf_used <= pf_used;
               endcase
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  stat_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg       cnt_pend;
reg [15:0] start_cnt;
reg [15:0] stop_cnt;
reg [15:0] beat_cnt;
reg [7:0]  wrap_cnt;
reg [15:0] idle_cnt;
reg        err_sticky;
reg [1:0]  stat_sel;

    initial begin
start_cnt  = 16'd0;
stop_cnt   = 16'd0;
beat_cnt   = 16'd0;
wrap_cnt   = 8'd0;
idle_cnt   = 16'd0;
err_sticky = 1'b0;
stat_sel   = 2'd0;
stat_o     = 32'h0;
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        cnt_pend = 1'b0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
start_cnt  <= 16'd0;
stop_cnt   <= 16'd0;
beat_cnt   <= 16'd0;
wrap_cnt   <= 8'd0;
idle_cnt   <= 16'd0;
err_sticky <= 1'b0;
stat_sel   <= 2'd0;
stat_o     <= 32'h0;
            cnt_pend   <= 1'b0;
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
if (start)
    start_cnt <= start_cnt + 16'd1;
if (stop)
    stop_cnt <= stop_cnt + 16'd1;
if (start && stop)
    err_sticky <= 1'b1;
if (win && !start && !stop) begin
    beat_cnt <= beat_cnt + 16'd1;
    if (rd_ptr == 3'd7)
        wrap_cnt <= wrap_cnt + 8'd1;
end
if (!win)
    idle_cnt <= idle_cnt + 16'd1;
stat_sel <= stat_sel + 2'd1;
case (stat_sel)
    2'd0: stat_o <= {start_cnt, stop_cnt};
    2'd1: stat_o <= {beat_cnt, idle_cnt};
    2'd2: stat_o <= {8'h0, wrap_cnt, 14'h0, cnt_pend, err_sticky};
    default: stat_o <= {err_sticky, 7'h0, wrap_cnt, beat_cnt};
endcase
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
                cnt_pend <= 1'b0;
            end else if (stop) begin
                win <= 1'b0;
                cnt      <= cnt + {3'b000, cnt_pend};
                cnt_pend <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
                    cnt_pend <= 1'b0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                    cnt      <= cnt + {3'b000, cnt_pend};
                    cnt_pend <= 1'b1;
                end
            end else begin
                cnt      <= cnt + {3'b000, cnt_pend};
                cnt_pend <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module xbar_route_rom (
    input  wire         clk,
