reg         st0_v, st1_v, st2_v, st3_v;
assign pipe_vld = {st3_v, st2_v, st1_v, st0_v};
assign out_tag  = st3_idx;
reg [7:0]  start_cnt;
reg [7:0]  stop_cnt;
reg [15:0] beat_cnt;
reg [15:0] csum;
reg [11:0] idle_wdog;
reg        wdog_flag;
reg        err_flag;
reg        seq_err;
reg [2:0]  last_tag;

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
st0_q = 128'h0; st1_q = 128'h0; st2_q = 128'h0; st3_q = 128'h0;
st0_idx = 3'd0; st1_idx = 3'd0; st2_idx = 3'd0; st3_idx = 3'd0;
st0_v = 1'b0; st1_v = 1'b0; st2_v = 1'b0; st3_v = 1'b0;
start_cnt = 8'd0;
stop_cnt  = 8'd0;
beat_cnt  = 16'd0;
csum      = 16'd0;
idle_wdog = 12'd0;
wdog_flag = 1'b0;
err_flag  = 1'b0;
seq_err   = 1'b0;
last_tag  = 3'd7;
dbg_stat  = 32'd0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
st0_q <= 128'h0; st1_q <= 128'h0; st2_q <= 128'h0; st3_q <= 128'h0;
st0_idx <= 3'd0; st1_idx <= 3'd0; st2_idx <= 3'd0; st3_idx <= 3'd0;
st0_v <= 1'b0; st1_v <= 1'b0; st2_v <= 1'b0; st3_v <= 1'b0;
start_cnt <= 8'd0;
stop_cnt  <= 8'd0;
beat_cnt  <= 16'd0;
csum      <= 16'd0;
idle_wdog <= 12'd0;
wdog_flag <= 1'b0;
err_flag  <= 1'b0;
seq_err   <= 1'b0;
last_tag  <= 3'd7;
dbg_stat  <= 32'd0;
        end else if (en) begin
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
st0_v  <= 1'b0;
st1_v  <= 1'b0;
st2_v  <= 1'b0;
st3_v  <= 1'b0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
st0_q   <= rom_word;
st0_idx <= rd_ptr;
st0_v   <= 1'b1;
st1_q   <= st0_q;
st1_idx <= st0_idx;
st1_v   <= st0_v;
st2_q   <= st1_q;
st2_idx <= st1_idx;
st2_v   <= st1_v;
st3_q   <= st2_q;
st3_idx <= st2_idx;
st3_v   <= st2_v;
if (st3_v) begin
out_q <= st3_q;
out_v <= 1'b1;
if (st3_idx == 3'd7)
cnt <= 4'd0;
else
cnt <= cnt + 4'd1;
end
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                end
            end
        end
if (rst_n) begin
if (en) begin
if (start)
start_cnt <= start_cnt + 8'd1;
if (stop)
stop_cnt <= stop_cnt + 8'd1;
if (start && stop)
err_flag <= 1'b1;
if (start || win)
idle_wdog <= 12'd0;
else if (idle_wdog != 12'hFFF)
idle_wdog <= idle_wdog + 12'd1;
if (idle_wdog == 12'hFFE)
wdog_flag <= 1'b1;
if (start)
last_tag <= 3'd7;
if (win && !start && !stop && st3_v) begin
beat_cnt <= beat_cnt + 16'd1;
