        .out_q(t2_out_q), .out_v(t2_out_v), .pipe_vld(t2_pipe_vld), .out_tag(t2_out_tag), .dbg_stat(t2_dbg),
        .cnt_o(t2_cnt), .rd_ptr_o(t2_rd_ptr),
        .st0_idx_o(t2_st0_idx), .st0_v_o(t2_st0_v), .st1_idx_o(t2_st1_idx), .st1_v_o(t2_st1_v),
        .st2_idx_o(t2_st2_idx), .st2_v_o(t2_st2_v), .st3_idx_o(t2_st3_idx), .st3_v_o(t2_st3_v));

    xbar_route_rom u3 (.clk(clk), .rst_n(rst_n), .en(t3_en), .start(start[3]), .stop(stop[3]),
        .out_q(t3_out_q), .out_v(t3_out_v), .pipe_vld(t3_pipe_vld), .out_tag(t3_out_tag), .dbg_stat(t3_dbg),
        .cnt_o(t3_cnt), .rd_ptr_o(t3_rd_ptr),
        .st0_idx_o(t3_st0_idx), .st0_v_o(t3_st0_v), .st1_idx_o(t3_st1_idx), .st1_v_o(t3_st1_v),
        .st2_idx_o(t3_st2_idx), .st2_v_o(t3_st2_v), .st3_idx_o(t3_st3_idx), .st3_v_o(t3_st3_v));

    // credit return: frame end (last ROM index leaving stage 3) or lane stopped
    wire r0 = h0 && en && (stop[0] || (!start[0] && t0_st3_v && t0_st3_idx == 3'd7));
    wire r1 = h1 && en && (stop[1] || (!start[1] && t1_st3_v && t1_st3_idx == 3'd7));
    wire r2 = h2 && en && (stop[2] || (!start[2] && t2_st3_v && t2_st3_idx == 3'd7));
    wire r3 = h3 && en && (stop[3] || (!start[3] && t3_st3_v && t3_st3_idx == 3'd7));

   // lease timer: a lane that holds a credit but never launches a frame
   // (no start and nothing entering its pipeline) hands the credit back
   wire p0 = start[0] || t0_st0_v;
   wire p1 = start[1] || t1_st0_v;
   wire p2 = start[2] || t2_st0_v;
   wire p3 = start[3] || t3_st0_v;
   wire lx0 = (lease0 == 4'hF);
   wire lx1 = (lease1 == 4'hF);
   wire lx2 = (lease2 == 4'hF);
   wire lx3 = (lease3 == 4'hF);
   wire rv0 = h0 && en && !r0 && !start[0] && lx0;
   wire rv1 = h1 && en && !r1 && !start[1] && lx1;
   wire rv2 = h2 && en && !r2 && !start[2] && lx2;
   wire rv3 = h3 && en && !r3 && !start[3] && lx3;
   wire [3:0] rv_vec = {rv3, rv2, rv1, rv0};
   wire [2:0] rv_cnt = {2'b00, rv0} + {2'b00, rv1} + {2'b00, rv2} + {2'b00, rv3};

   // starvation guard: a requester passed over for seven enabled cycles
   wire s0 = req[0] && !h0 && (age0 == 3'd7);
   wire s1 = req[1] && !h1 && (age1 == 3'd7);
   wire s2 = req[2] && !h2 && (age2 == 3'd7);
   wire s3 = req[3] && !h3 && (age3 == 3'd7);
   reg       stv_any;
   reg [1:0] stv_sel;
   always @(*) begin
       stv_any = s0 || s1 || s2 || s3;
       stv_sel = 2'd0;
       case (boost_ptr)
           2'd0: begin
               if (s0)      stv_sel = 2'd0;
               else if (s1) stv_sel = 2'd1;
               else if (s2) stv_sel = 2'd2;
               else         stv_sel = 2'd3;
           end
           2'd1: begin
               if (s1)      stv_sel = 2'd1;
               else if (s2) stv_sel = 2'd2;
               else if (s3) stv_sel = 2'd3;
               else         stv_sel = 2'd0;
           end
           2'd2: begin
               if (s2)      stv_sel = 2'd2;
               else if (s3) stv_sel = 2'd3;
               else if (s0) stv_sel = 2'd0;
               else         stv_sel = 2'd1;
           end
           default: begin
               if (s3)      stv_sel = 2'd3;
               else if (s0) stv_sel = 2'd0;
               else if (s1) stv_sel = 2'd1;
               else         stv_sel = 2'd2;
           end
       endcase
   end

   // reservation slot: one credit parked for the chosen starved lane,
   // handed over on the next enabled cycle, or returned if the lane
   // has withdrawn its request; the parked lane is idle by construction
   wire park_take = en && !park_v && (pool != 2'd0) && stv_any;
   wire park_fire = en && park_v && req[park_lane];
   wire park_ret  = en && park_v && !req[park_lane];
   wire pf0 = park_fire && (park_lane == 2'd0);
   wire pf1 = park_fire && (park_lane == 2'd1);
   wire pf2 = park_fire && (park_lane == 2'd2);
   wire pf3 = park_fire && (park_lane == 2'd3);
   wire pb0 = park_v && (park_lane == 2'd0);
   wire pb1 = park_v && (park_lane == 2'd1);
   wire pb2 = park_v && (park_lane == 2'd2);
   wire pb3 = park_v && (park_lane == 2'd3);

    // one grant per cycle, fixed priority, only from a non-empty pool
   // a reservation take preempts the normal arbiter for that cycle
   wire credit_ok = en && (pool != 2'd0) && !park_take;
   wire g0 = credit_ok && req[0] && !h0 && !pb0;
   wire g1 = credit_ok && req[1] && !h1 && !pb1 && !g0;
   wire g2 = credit_ok && req[2] && !h2 && !pb2 && !g0 && !g1;
   wire g3 = credit_ok && req[3] && !h3 && !pb3 && !g0 && !g1 && !g2;
    wire g_any = g0 || g1 || g2 || g3;

    wire [2:0] rel_cnt = {2'b00, r0} + {2'b00, r1} + {2'b00, r2} + {2'b00, r3};
   wire [2:0] pool_nx = {1'b0, pool} + rel_cnt + rv_cnt + {2'b00, park_ret}
                        - {2'b00, g_any} - {2'b00, park_take};

    always @(posedge clk) begin
        if (!rst_n) begin
            pool <= 2'd2;
            h0 <= 1'b0; h1 <= 1'b0; h2 <= 1'b0; h3 <= 1'b0;
           age0 <= 3'd0; age1 <= 3'd0; age2 <= 3'd0; age3 <= 3'd0;
           lease0 <= 4'd0; lease1 <= 4'd0; lease2 <= 4'd0; lease3 <= 4'd0;
           park_v     <= 1'b0;
           park_lane  <= 2'd0;
           boost_ptr  <= 2'd0;
           park_cnt   <= 8'd0;
           ret_cnt    <= 8'd0;
           revoke_cnt <= 8'd0;
           last_rv    <= 4'd0;
        end else begin
            pool <= pool_nx[1:0];
           h0 <= g0 || pf0 || (h0 && !r0 && !rv0);
           h1 <= g1 || pf1 || (h1 && !r1 && !rv1);
           h2 <= g2 || pf2 || (h2 && !r2 && !rv2);
           h3 <= g3 || pf3 || (h3 && !r3 && !rv3);
           if (en) begin
               // request aging
               if (!req[0] || h0 || g0 || pf0)
                   age0 <= 3'd0;
               else if (age0 != 3'd7)
                   age0 <= age0 + 3'd1;
               if (!req[1] || h1 || g1 || pf1)
                   age1 <= 3'd0;
               else if (age1 != 3'd7)
                   age1 <= age1 + 3'd1;
               if (!req[2] || h2 || g2 || pf2)
                   age2 <= 3'd0;
               else if (age2 != 3'd7)
                   age2 <= age2 + 3'd1;
               if (!req[3] || h3 || g3 || pf3)
                   age3 <= 3'd0;
               else if (age3 != 3'd7)
                   age3 <= age3 + 3'd1;
               // lease timers
               if (!h0 || p0 || r0 || rv0)
                   lease0 <= 4'd0;
               else if (!lx0)
                   lease0 <= lease0 + 4'd1;
               if (!h1 || p1 || r1 || rv1)
                   lease1 <= 4'd0;
               else if (!lx1)
                   lease1 <= lease1 + 4'd1;
               if (!h2 || p2 || r2 || rv2)
                   lease2 <= 4'd0;
               else if (!lx2)
                   lease2 <= lease2 + 4'd1;
               if (!h3 || p3 || r3 || rv3)
                   lease3 <= 4'd0;
               else if (!lx3)
                   lease3 <= lease3 + 4'd1;
               // reservation slot
               if (park_take) begin
                   park_v    <= 1'b1;
                   park_lane <= stv_sel;
                   boost_ptr <= stv_sel + 2'd1;
                   park_cnt  <= park_cnt + 8'd1;
               end else if (park_fire || park_ret) begin
                   park_v    <= 1'b0;
               end
               if (park_ret)
                   ret_cnt <= ret_cnt + 8'd1;
               if (rv_vec != 4'd0) begin
                   revoke_cnt <= revoke_cnt + {5'd0, rv_cnt};
                   last_rv    <= rv_vec;
               end
           end
        end
    end

    // output port: lowest credited lane with valid data drives the shared bus
    always @(*) begin
        out_q   = 128'h0;
        out_v   = 1'b0;
        out_src = 2'd0;
        if (h0 && t0_out_v) begin
            out_q = t0_out_q; out_v = 1'b1; out_src = 2'd0;
        end else if (h1 && t1_out_v) begin
            out_q = t1_out_q; out_v = 1'b1; out_src = 2'd1;
        end else if (h2 && t2_out_v) begin
            out_q = t2_out_q; out_v = 1'b1; out_src = 2'd2;
        end else if (h3 && t3_out_v) begin
            out_q = t3_out_q; out_v = 1'b1; out_src = 2'd3;
        end
    end

    assign frame_v      = {t3_out_v, t2_out_v, t1_out_v, t0_out_v};
    assign out_tag_all  = {t3_out_tag, t2_out_tag, t1_out_tag, t0_out_tag};
    assign pipe_vld_all = {t3_pipe_vld, t2_pipe_vld, t1_pipe_vld, t0_pipe_vld};
    assign dbg_all      = {t3_dbg, t2_dbg, t1_dbg, t0_dbg};
    assign pool_o       = pool;
    assign hold_o       = {h3, h2, h1, h0};
   assign park_o       = park_v;
   assign park_lane_o  = park_lane;
   assign boost_o      = boost_ptr;
   assign age_all_o    = {age3, age2, age1, age0};
   assign lease_all_o  = {lease3, lease2, lease1, lease0};
   assign arb_stat_o   = {last_rv, park_v, park_lane, stv_any, revoke_cnt, ret_cnt, park_cnt};

    always @(posedge clk)
        assert (pool <= 2'd2);
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
output reg         fault,
output reg  [3:0]  n_acc_in,   // accesses accepted into the lookup stage
output reg  [3:0]  n_acc_out,  // accesses retired from the lookup stage
output reg  [15:0] dbg_status   // rotating debug/statistics readout
,
    output wire hit_q_o,
    output wire miss_q_o
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;
initial n_acc_in  = 4'd0;
initial n_acc_out = 4'd0;
   // ---- debug / statistics bank (observability only) ----
   reg [7:0]  dbg_grant_cnt   = 8'd0;
   reg [7:0]  dbg_fault_cnt   = 8'd0;
   reg [5:0]  dbg_cfg_wr_cnt  = 6'd0;
   reg [5:0]  dbg_cfg_rej_cnt = 6'd0;
   reg [7:0]  dbg_idle_cnt    = 8'd0;
   reg        dbg_wdog_trip   = 1'b0;
   reg [15:0] dbg_addr_d1     = 16'd0;
   reg [15:0] dbg_fault_addr  = 16'd0;
   reg [1:0]  dbg_sel         = 2'd0;
   initial dbg_status = 16'd0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
// a hit retiring while the ledger shows nothing outstanding is a spurious response
fault  <= miss_q || (hit_q && (n_acc_in == n_acc_out));
if (acc_valid)
    n_acc_in <= n_acc_in + 4'd1;
if (hit_q || miss_q)
    n_acc_out <= n_acc_out + 4'd1;
        end
    end

    always @(posedge clk) pv <= 1'b1;

   always @(posedge clk) begin
       if (i_ce) begin
           dbg_addr_d1 <= acc_addr;
           if (grant && (dbg_grant_cnt != 8'hFF))
               dbg_grant_cnt <= dbg_grant_cnt + 8'd1;
           if (fault && (dbg_fault_cnt != 8'hFF))
               dbg_fault_cnt <= dbg_fault_cnt + 8'd1;
           if (miss_q)
               dbg_fault_addr <= dbg_addr_d1;
           if (cfg_we) begin
               if (pre_lock && (cfg_idx < 5'd24))
                   dbg_cfg_wr_cnt <= dbg_cfg_wr_cnt + 6'd1;
               else
                   dbg_cfg_rej_cnt <= dbg_cfg_rej_cnt + 6'd1;
           end
           if (acc_valid) begin
               dbg_idle_cnt  <= 8'd0;
               dbg_wdog_trip <= 1'b0;
           end else if (dbg_idle_cnt == 8'hFF)
               dbg_wdog_trip <= 1'b1;
           else
               dbg_idle_cnt <= dbg_idle_cnt + 8'd1;
           dbg_sel <= dbg_sel + 2'd1;
           case (dbg_sel)
               2'd0:    dbg_status <= {dbg_grant_cnt, dbg_fault_cnt};
               2'd1:    dbg_status <= {dbg_cfg_wr_cnt, dbg_cfg_rej_cnt, pre_lock, dbg_wdog_trip, 2'b00};
               2'd2:    dbg_status <= dbg_fault_addr;
               default: dbg_status <= {dbg_idle_cnt, 4'd0, n_acc_in - n_acc_out};
           endcase
       end
   end

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
    assign hit_q_o = hit_q;
    assign miss_q_o = miss_q;
endmodule

module rgmii_relay_fifo (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [3:0]  rxd_rise,
    input  wire [3:0]  rxd_fall,
    input  wire        ctl_rise,
    input  wire        ctl_fall,
    input  wire        rd_en,
    output wire [31:0] dout,
    output wire        empty,
    output wire [31:0] o_occ
,
    output wire [31:0] occ_o,
    output wire [31:0] rd_cnt_o,
    output wire [31:0] wr_cnt_o
);
    reg [4:0]  cap_rise;
    reg [4:0]  cap_fall;
    reg [1:0]  byte_ph;
    reg [23:0] shift;
    reg [31:0] mem [0:3];
    reg [31:0] wr_cnt;
    reg [31:0] rd_cnt;
    reg [31:0] occ;
    reg        armed;

    initial begin
        cap_rise = 5'd0;
        cap_fall = 5'd0;
        byte_ph  = 2'd0;
        shift    = 24'd0;
        mem[0]   = 32'd0;
        mem[1]   = 32'd0;
        mem[2]   = 32'd0;
        mem[3]   = 32'd0;
        wr_cnt   = 32'd0;
        rd_cnt   = 32'd0;
        occ      = 32'd0;
        armed    = 1'b0;
    end

    wire       rx_dv   = cap_rise[4];
    wire [7:0] rx_byte = {cap_fall[3:0], cap_rise[3:0]};
    wire [31:0] diff   = wr_cnt - rd_cnt;
    wire       full    = (diff == 32'd4);
    wire       push    = en && rx_dv && (byte_ph == 2'd3) && !full;
    wire       pop     = en && rd_en && (wr_cnt != rd_cnt);

    always @(posedge clk) begin
        if (rst) begin
            cap_rise <= 5'd0;
            cap_fall <= 5'd0;
            byte_ph  <= 2'd0;
            shift    <= 24'd0;
            mem[0]   <= 32'd0;
            mem[1]   <= 32'd0;
            mem[2]   <= 32'd0;
            mem[3]   <= 32'd0;
            wr_cnt   <= 32'd0;
            rd_cnt   <= 32'd0;
            occ      <= 32'd0;
            armed    <= 1'b0;
        end else if (en) begin
            cap_rise <= {ctl_rise, rxd_rise};
            cap_fall <= {ctl_fall, rxd_fall};
            armed    <= armed | rx_dv;
            if (rx_dv) begin
                byte_ph <= byte_ph + 2'd1;
                case (byte_ph)
                    2'd0: shift[7:0]   <= rx_byte;
                    2'd1: shift[15:8]  <= rx_byte;
                    2'd2: shift[23:16] <= rx_byte;
                    default: ;
                endcase
            end
            if (push) begin
                mem[wr_cnt[1:0]] <= {rx_byte, shift};
                wr_cnt <= wr_cnt + 32'd1;
            end
            if (pop)
                rd_cnt <= rd_cnt + 32'd1;
            occ <= occ + (push ? 32'd1 : 32'd0) - (pop ? 32'd1 : 32'd0);
        end
    end

    assign dout  = mem[rd_cnt[1:0]];
    assign empty = (wr_cnt == rd_cnt);
    assign o_occ = occ;

    always @(posedge clk)
        if (armed)
            assert (occ <= 32'd4);
    assign occ_o = occ;
    assign rd_cnt_o = rd_cnt;
    assign wr_cnt_o = wr_cnt;
endmodule

module mpu_verdict_relay (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    input  wire        relay_en,
    input  wire        rd_en,
    output wire        grant,
    output wire        fault,
    output wire [15:0] dbg_status,
    output wire [31:0] dout,
    output wire        empty,
    output wire [31:0] o_occ,
    output reg         pend_vld,
    output reg  [7:0]  pend_byte,
    output reg         tx_vld,
    output reg  [7:0]  tx_byte,
    output reg  [3:0]  vseq,
    output reg  [7:0]  drop_cnt
);
    wire        a_grant;
    wire        a_fault;
    wire [3:0]  a_n_in;
    wire [3:0]  a_n_out;
    wire [15:0] a_dbg;
    wire        a_hit_q;
    wire        a_miss_q;

    wire [31:0] b_dout;
    wire        b_empty;
    wire [31:0] b_o_occ;
    wire [31:0] b_occ;
    wire [31:0] b_rd_cnt;
    wire [31:0] b_wr_cnt;

    initial pend_vld  = 1'b0;
    initial pend_byte = 8'd0;
    initial tx_vld    = 1'b0;
    initial tx_byte   = 8'd0;
    initial vseq      = 4'd0;
    initial drop_cnt  = 8'd0;

    mpu_region_checker u_mpu (
        .clk(clk),
        .i_ce(i_ce),
        .cfg_we(cfg_we),
        .cfg_idx(cfg_idx),
        .cfg_base(cfg_base),
        .cfg_limit(cfg_limit),
        .cfg_perm(cfg_perm),
        .lock_req(lock_req),
        .acc_valid(acc_valid),
        .acc_write(acc_write),
        .acc_addr(acc_addr),
        .grant(a_grant),
        .fault(a_fault),
        .n_acc_in(a_n_in),
        .n_acc_out(a_n_out),
        .dbg_status(a_dbg),
        .hit_q_o(a_hit_q),
        .miss_q_o(a_miss_q)
    );

    // a lookup retiring from the MPU lookup stage produces one verdict record
    wire       verdict_ev   = i_ce && (a_hit_q || a_miss_q);
    wire [7:0] verdict_byte = {2'b01, a_miss_q, a_hit_q, vseq};
    wire       pend_free    = !pend_vld || relay_en;

    always @(posedge clk) begin
        if (rst) begin
            pend_vld  <= 1'b0;
            pend_byte <= 8'd0;
            tx_vld    <= 1'b0;
            tx_byte   <= 8'd0;
            vseq      <= 4'd0;
            drop_cnt  <= 8'd0;
        end else begin
            if (relay_en) begin
                tx_vld <= pend_vld;
                if (pend_vld)
                    tx_byte <= pend_byte;
            end
            if (verdict_ev && pend_free) begin
                pend_vld  <= 1'b1;
                pend_byte <= verdict_byte;
                vseq      <= vseq + 4'd1;
            end else if (relay_en) begin
                pend_vld <= 1'b0;
            end
            if (verdict_ev && !pend_free && (drop_cnt != 8'hFF))
                drop_cnt <= drop_cnt + 8'd1;
        end
    end

    rgmii_relay_fifo u_fifo (
        .clk(clk),
        .rst(rst),
        .en(relay_en),
        .rxd_rise(tx_byte[3:0]),
        .rxd_fall(tx_byte[7:4]),
        .ctl_rise(tx_vld),
        .ctl_fall(tx_vld),
        .rd_en(rd_en),
        .dout(b_dout),
        .empty(b_empty),
        .o_occ(b_o_occ),
        .occ_o(b_occ),
        .rd_cnt_o(b_rd_cnt),
        .wr_cnt_o(b_wr_cnt)
    );

    assign grant      = a_grant;
    assign fault      = a_fault;
    assign dbg_status = a_dbg;
    assign dout       = b_dout;
    assign empty      = b_empty;
    assign o_occ      = b_o_occ;

    // every record on the relay link is a well-formed verdict: type tag 01, exactly one of miss/hit
    always @(posedge clk)
        if (tx_vld)
            assert ((tx_byte[7:6] == 2'b01) && (tx_byte[5] != tx_byte[4]));
endmodule

module ec_jdbl_seq (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        arm,
    input  wire        start,
    input  wire        clr,
    input  wire        sel_add,
    input  wire        wr_en,
    input  wire [3:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire        o_done,
    output wire [31:0] o_acc,
   output wire [31:0] o_x3,
   output wire [2:0]  o_jq_cnt,
   output wire [2:0]  o_jq_hwm,
   output wire        o_jq_full,
   output wire        o_jq_ovf,
   output wire [7:0]  o_jq_drop,
   output wire        o_jq_hmode,
   output wire [31:0] o_jq_hseed,
   output wire        o_jq_tmode,
   output wire [31:0] o_jq_tseed,
   output wire        o_busy,
   output wire [2:0]  o_hist_cnt,
   output wire        o_hist_hit,
   output wire [31:0] o_hist_x,
   output wire [31:0] o_hist_y,
   output wire [31:0] o_hist_z,
   output wire        o_hist_md,
   output wire        o_hist_src,
   output wire [7:0]  o_hist_tag,
   output wire [7:0]  o_hist_lag,
   output wire [31:0] o_hist_sum,
   output wire [7:0]  o_job_seq,
   output wire [7:0]  o_n_qlaunch,
   output wire [7:0]  o_n_dbl,
   output wire [7:0]  o_n_add
);
    localparam [31:0] PRIME = 32'hFFFFFFFB;
    localparam [31:0] LAST  = 32'd11;
    localparam [1:0]  OP_MUL = 2'd0;
    localparam [1:0]  OP_ADD = 2'd1;
    localparam [1:0]  OP_SUB = 2'd2;

    reg        armed;
    reg        started;
    reg        done;
    reg        pre_clr;
    reg        mode;
    reg [31:0] step;
    reg [31:0] acc;
    reg [31:0] rf [0:15];
   localparam [2:0]  JQ_DEPTH = 3'd4;
   reg        jq_mode [0:3];
   reg        jq_ld   [0:3];
   reg [31:0] jq_seed [0:3];
   reg [1:0]  jq_wp;
   reg [1:0]  jq_rp;
   reg [2:0]  jq_cnt;
   reg [2:0]  jq_hwm;
   reg        jq_ovf;
   reg [7:0]  jq_drop;
   reg [7:0]  n_qlaunch;
   reg [31:0] hist_x   [0:3];
   reg [31:0] hist_y   [0:3];
   reg [31:0] hist_z   [0:3];
   reg        hist_md  [0:3];
   reg        hist_src [0:3];
   reg [7:0]  hist_tag [0:3];
   reg [1:0]  hist_wp;
   reg        hist_wrap;
   reg [31:0] hist_sum;
   reg [7:0]  job_seq;
   reg        job_src;
   reg [7:0]  n_dbl;
   reg [7:0]  n_add;

    integer i;
   integer k;
    initial begin
        armed   = 1'b0;
        started = 1'b0;
        done    = 1'b0;
        pre_clr = 1'b1;
        mode    = 1'b0;
        step    = 32'd0;
        acc     = 32'd0;
        for (i = 0; i < 16; i = i + 1)
            rf[i] = 32'd0;
       jq_wp     = 2'd0;
       jq_rp     = 2'd0;
       jq_cnt    = 3'd0;
       jq_hwm    = 3'd0;
       jq_ovf    = 1'b0;
       jq_drop   = 8'd0;
       n_qlaunch = 8'd0;
       hist_wp   = 2'd0;
       hist_wrap = 1'b0;
       hist_sum  = 32'd0;
       job_seq   = 8'd0;
       job_src   = 1'b0;
       n_dbl     = 8'd0;
       n_add     = 8'd0;
       for (i = 0; i < 4; i = i + 1) begin
           jq_mode[i]  = 1'b0;
           jq_ld[i]    = 1'b0;
           jq_seed[i]  = 32'd0;
           hist_x[i]   = 32'd0;
           hist_y[i]   = 32'd0;
           hist_z[i]   = 32'd0;
           hist_md[i]  = 1'b0;
           hist_src[i] = 1'b0;
           hist_tag[i] = 8'd0;
       end
    end

    function [31:0] fadd;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            s = {1'b0, a} + {1'b0, b};
            if (s >= {1'b0, PRIME})
                s = s - {1'b0, PRIME};
            fadd = s[31:0];
        end
    endfunction

    function [31:0] fsub;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            if (a >= b)
                s = {1'b0, a} - {1'b0, b};
            else
                s = {1'b0, a} + {1'b0, PRIME} - {1'b0, b};
            fsub = s[31:0];
        end
    endfunction

    function [31:0] fmul;
        input [31:0] a;
        input [31:0] b;
        reg [63:0] p;
        reg [35:0] t;
        reg [35:0] u;
        begin
            p = {32'd0, a} * {32'd0, b};
            t = {4'd0, p[31:0]} + {4'd0, p[63:32]} * 36'd5;
            u = {4'd0, t[31:0]} + {32'd0, t[35:32]} * 36'd5;
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            fmul = u[31:0];
        end
    endfunction

    reg [3:0] ra, rb, rd;
    reg [1:0] opc;
    always @(*) begin
        ra  = 4'd0;
        rb  = 4'd0;
        rd  = 4'd6;
        opc = OP_MUL;
        case (step)
            32'd1:  begin ra = 4'd1;  rb = mode ? 4'd4 : 4'd1; rd = 4'd6;  opc = OP_MUL; end
            32'd2:  begin ra = 4'd0;  rb = 4'd6;  rd = 4'd7;  opc = OP_MUL; end
            32'd3:  begin ra = 4'd0;  rb = mode ? 4'd3 : 4'd0; rd = 4'd8;  opc = OP_MUL; end
            32'd4:  begin ra = 4'd8;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd5:  begin ra = 4'd9;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd6:  begin ra = 4'd9;  rb = 4'd9;  rd = 4'd10; opc = OP_MUL; end
            32'd7:  begin ra = 4'd7;  rb = 4'd7;  rd = 4'd11; opc = OP_ADD; end
            32'd8:  begin ra = 4'd10; rb = 4'd11; rd = 4'd12; opc = OP_SUB; end
            32'd9:  begin ra = mode ? 4'd2 : 4'd1; rb = mode ? 4'd5 : 4'd2; rd = 4'd13; opc = OP_MUL; end
            32'd10: begin ra = 4'd6;  rb = 4'd6;  rd = 4'd15; opc = OP_MUL; end
            default: begin ra = 4'd0; rb = 4'd0; rd = 4'd6; opc = OP_MUL; end
        endcase
    end

    wire [31:0] opa = rf[ra];
    wire [31:0] opb = rf[rb];
    reg  [31:0] res;
    always @(*) begin
        case (opc)
            OP_MUL:  res = fmul(opa, opb);
            OP_ADD:  res = fadd(opa, opb);
            OP_SUB:  res = fsub(opa, opb);
            default: res = opa;
        endcase
    end

    wire [31:0] y3 = fsub(fmul(rf[9], fsub(rf[7], rf[12])), rf[15]);
    wire [31:0] z3 = fadd(rf[13], rf[13]);
   wire        idle       = (step == 32'd0);
   wire        jq_empty   = (jq_cnt == 3'd0);
   wire        jq_full    = (jq_cnt == JQ_DEPTH);
   wire        req_ok     = start && armed && !clr;
   wire        q_launch   = en && idle && !clr && !jq_empty;
   wire        d_launch   = en && idle && req_ok && jq_empty;
   wire        job_launch = q_launch || d_launch;
   wire        req_queue  = en && req_ok && (!idle || !jq_empty);
   wire        jq_pop     = q_launch;
   wire        jq_push    = req_queue && (!jq_full || jq_pop);
   wire        jq_reject  = req_queue && jq_full && !jq_pop;
   wire [2:0]  jq_nxt_cnt = jq_cnt + {2'd0, jq_push} - {2'd0, jq_pop};
   wire [1:0]  jq_tail    = jq_wp - 2'd1;
   wire        hd_mode    = jq_mode[jq_rp];
   wire        hd_ld      = jq_ld[jq_rp];
   wire [31:0] hd_seed    = jq_seed[jq_rp];
   wire        nxt_mode   = q_launch ? hd_mode : sel_add;
   wire        job_end    = en && (step == LAST);
   wire [31:0] hist_nsum  = fadd(hist_sum, y3);
   wire [1:0]  hist_ra    = hist_wp - 2'd1 - wr_addr[1:0];
   wire [2:0]  hist_cnt   = hist_wrap ? 3'd4 : {1'b0, hist_wp};
   wire        hist_hit   = ({1'b0, wr_addr[1:0]} < hist_cnt);

    always @(posedge clk) begin
        if (rst) begin
            armed   <= 1'b0;
            started <= 1'b0;
            done    <= 1'b0;
            pre_clr <= 1'b1;
            mode    <= 1'b0;
            step    <= 32'd0;
            acc     <= 32'd0;
           jq_wp     <= 2'd0;
           jq_rp     <= 2'd0;
           jq_cnt    <= 3'd0;
           jq_hwm    <= 3'd0;
           jq_ovf    <= 1'b0;
           jq_drop   <= 8'd0;
           n_qlaunch <= 8'd0;
           hist_wp   <= 2'd0;
           hist_wrap <= 1'b0;
           hist_sum  <= 32'd0;
           job_seq   <= 8'd0;
           job_src   <= 1'b0;
           n_dbl     <= 8'd0;
           n_add     <= 8'd0;
           for (k = 0; k < 4; k = k + 1) begin
               jq_mode[k]  <= 1'b0;
               jq_ld[k]    <= 1'b0;
               jq_seed[k]  <= 32'd0;
               hist_x[k]   <= 32'd0;
               hist_y[k]   <= 32'd0;
               hist_z[k]   <= 32'd0;
               hist_md[k]  <= 1'b0;
               hist_src[k] <= 1'b0;
               hist_tag[k] <= 8'd0;
           end
        end else if (en) begin
            if (clr) begin
                armed   <= 1'b0;
                started <= 1'b0;
                done    <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (arm)
                    armed <= 1'b1;
               if (job_launch)
                    started <= 1'b1;
                if (step == LAST)
                    done <= 1'b1;
            end
            if (step == 32'd0) begin
               if (job_launch) begin
                    step <= 32'd1;
                   mode    <= nxt_mode;
                   job_seq <= job_seq + 8'd1;
                   job_src <= q_launch;
                end
            end else if (step == LAST) begin
                step <= 32'd0;
                acc  <= y3;
            end else begin
                step <= step + 32'd1;
                acc  <= res;
            end
           if (clr) begin
               jq_wp  <= 2'd0;
               jq_rp  <= 2'd0;
               jq_cnt <= 3'd0;
               jq_ovf <= 1'b0;
           end else begin
               if (jq_push) begin
                   jq_mode[jq_wp] <= sel_add;
                   jq_ld[jq_wp]   <= wr_en;
                   jq_seed[jq_wp] <= wr_data;
                   jq_wp          <= jq_wp + 2'd1;
               end
               if (jq_pop) begin
                   jq_rp     <= jq_rp + 2'd1;
                   n_qlaunch <= n_qlaunch + 8'd1;
               end
               jq_cnt <= jq_nxt_cnt;
               if (jq_reject) begin
                   jq_ovf <= 1'b1;
                   if (jq_drop != 8'hFF)
                       jq_drop <= jq_drop + 8'd1;
               end
           end
           if (jq_cnt > jq_hwm)
               jq_hwm <= jq_cnt;
           if (job_end) begin
               hist_x[hist_wp]   <= rf[12];
               hist_y[hist_wp]   <= y3;
               hist_z[hist_wp]   <= z3;
               hist_md[hist_wp]  <= mode;
               hist_src[hist_wp] <= job_src;
               hist_tag[hist_wp] <= job_seq;
               hist_wp           <= hist_wp + 2'd1;
               if (hist_wp == 2'd3)
                   hist_wrap <= 1'b1;
               hist_sum <= hist_nsum;
               if (mode)
                   n_add <= n_add + 8'd1;
               else
                   n_dbl <= n_dbl + 8'd1;
           end
        end
    end

    always @(posedge clk) begin
        if (!rst && en) begin
            if (step == 32'd0) begin
                if (wr_en)
                    rf[wr_addr] <= wr_data;
               if (q_launch && hd_ld)
                   rf[0] <= hd_seed;
            end else if (step == LAST) begin
                rf[0] <= rf[12];
                rf[1] <= y3;
                rf[2] <= z3;
            end else begin
                rf[rd] <= res;
            end
        end
    end

    assign o_done = done;
    assign o_acc  = acc;
    assign o_x3   = rf[0];
   assign o_jq_cnt    = jq_cnt;
   assign o_jq_hwm    = jq_hwm;
   assign o_jq_full   = jq_full;
   assign o_jq_ovf    = jq_ovf;
   assign o_jq_drop   = jq_drop;
   assign o_jq_hmode  = jq_empty ? 1'b0 : hd_mode;
   assign o_jq_hseed  = (jq_empty || !hd_ld) ? 32'd0 : hd_seed;
   assign o_jq_tmode  = jq_empty ? 1'b0 : jq_mode[jq_tail];
   assign o_jq_tseed  = (jq_empty || !jq_ld[jq_tail]) ? 32'd0 : jq_seed[jq_tail];
   assign o_busy      = !idle || !jq_empty;
   assign o_hist_cnt  = hist_cnt;
   assign o_hist_hit  = hist_hit;
   assign o_hist_x    = hist_hit ? hist_x[hist_ra]   : 32'd0;
   assign o_hist_y    = hist_hit ? hist_y[hist_ra]   : 32'd0;
   assign o_hist_z    = hist_hit ? hist_z[hist_ra]   : 32'd0;
   assign o_hist_md   = hist_hit ? hist_md[hist_ra]  : 1'b0;
   assign o_hist_src  = hist_hit ? hist_src[hist_ra] : 1'b0;
   assign o_hist_tag  = hist_hit ? hist_tag[hist_ra] : 8'd0;
   assign o_hist_lag  = hist_hit ? (job_seq - hist_tag[hist_ra]) : 8'd0;
   assign o_hist_sum  = hist_sum;
   assign o_job_seq   = job_seq;
   assign o_n_qlaunch = n_qlaunch;
   assign o_n_dbl     = n_dbl;
   assign o_n_add     = n_add;

    always @(*)
        if (pre_clr && done)
            assert (started && armed);
endmodule

module benes_lane_shuffler (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         in_valid,
    input  wire [511:0] in_data,
    input  wire [7:0]   in_sel,
    input  wire         cfg_we,
    input  wire [7:0]   cfg_addr,
    input  wire [19:0]  cfg_bits,
    output wire         out_valid,
    output wire [511:0] out_data,
output wire [63:0]  o_beats_done,
output wire         out_inv_valid,
output wire [511:0] out_inv_data,
output wire [63:0]  o_inv_beats_done,
output wire         o_any_valid,
output wire [511:0] o_merged_data,
output wire [63:0]  o_dir_switches
);
    reg [19:0]  cfg_tab   [0:255];
    reg [3:0]   stage_cfg [0:4];
    reg [19:0]  cfg_pipe  [0:3];
    reg [511:0] data_pipe [0:4];
    reg [4:0]   valid_pipe;
    reg [63:0]  inflight;
    reg [63:0]  beats_done;
    reg         armed;
reg [19:0]  inv_cfg_pipe  [0:3];
reg [3:0]   inv_stage_cfg [0:4];
reg [511:0] inv_data_pipe [0:4];
reg [4:0]   inv_valid_pipe;
reg [63:0]  inv_beats_done;
reg         last_dir;
reg [63:0]  dir_switches;

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) cfg_tab[i] = 20'd0;
        for (i = 0; i < 5; i = i + 1) begin
            stage_cfg[i] = 4'd0;
            data_pipe[i] = 512'd0;
        end
        for (i = 0; i < 4; i = i + 1) cfg_pipe[i] = 20'd0;
        valid_pipe = 5'd0;
        inflight   = 64'd0;
        beats_done = 64'd0;
        armed      = 1'b0;
for (i = 0; i < 5; i = i + 1) begin
inv_stage_cfg[i] = 4'd0;
inv_data_pipe[i] = 512'd0;
end
for (i = 0; i < 4; i = i + 1) inv_cfg_pipe[i] = 20'd0;
inv_valid_pipe = 5'd0;
inv_beats_done = 64'd0;
last_dir       = 1'b0;
dir_switches   = 64'd0;
    end

    // butterfly stage, pair distance 4
    function [511:0] sw4;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw4[0*64 +: 64] = c[0] ? d[4*64 +: 64] : d[0*64 +: 64];
            sw4[4*64 +: 64] = c[0] ? d[0*64 +: 64] : d[4*64 +: 64];
            sw4[1*64 +: 64] = c[1] ? d[5*64 +: 64] : d[1*64 +: 64];
            sw4[5*64 +: 64] = c[1] ? d[1*64 +: 64] : d[5*64 +: 64];
            sw4[2*64 +: 64] = c[2] ? d[6*64 +: 64] : d[2*64 +: 64];
            sw4[6*64 +: 64] = c[2] ? d[2*64 +: 64] : d[6*64 +: 64];
            sw4[3*64 +: 64] = c[3] ? d[7*64 +: 64] : d[3*64 +: 64];
            sw4[7*64 +: 64] = c[3] ? d[3*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 2
    function [511:0] sw2;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw2[0*64 +: 64] = c[0] ? d[2*64 +: 64] : d[0*64 +: 64];
            sw2[2*64 +: 64] = c[0] ? d[0*64 +: 64] : d[2*64 +: 64];
            sw2[1*64 +: 64] = c[1] ? d[3*64 +: 64] : d[1*64 +: 64];
            sw2[3*64 +: 64] = c[1] ? d[1*64 +: 64] : d[3*64 +: 64];
            sw2[4*64 +: 64] = c[2] ? d[6*64 +: 64] : d[4*64 +: 64];
            sw2[6*64 +: 64] = c[2] ? d[4*64 +: 64] : d[6*64 +: 64];
            sw2[5*64 +: 64] = c[3] ? d[7*64 +: 64] : d[5*64 +: 64];
            sw2[7*64 +: 64] = c[3] ? d[5*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 1 (middle stage)
    function [511:0] sw1;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw1[0*64 +: 64] = c[0] ? d[1*64 +: 64] : d[0*64 +: 64];
            sw1[1*64 +: 64] = c[0] ? d[0*64 +: 64] : d[1*64 +: 64];
            sw1[2*64 +: 64] = c[1] ? d[3*64 +: 64] : d[2*64 +: 64];
            sw1[3*64 +: 64] = c[1] ? d[2*64 +: 64] : d[3*64 +: 64];
            sw1[4*64 +: 64] = c[2] ? d[5*64 +: 64] : d[4*64 +: 64];
            sw1[5*64 +: 64] = c[2] ? d[4*64 +: 64] : d[5*64 +: 64];
            sw1[6*64 +: 64] = c[3] ? d[7*64 +: 64] : d[6*64 +: 64];
            sw1[7*64 +: 64] = c[3] ? d[6*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    wire [19:0] cfg0 = cfg_tab[in_sel];
// in_sel[7] routes the beat through the inverse (unshuffle) lane; both
// lanes share the single input port, the config table and the credit count
wire        go_inv     = in_valid & in_sel[7];
wire        go_fwd     = in_valid & ~in_sel[7];
wire        retire_fwd = valid_pipe[4];
wire        retire_inv = inv_valid_pipe[4];

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < 256; i = i + 1) cfg_tab[i] <= 20'd0;
            for (i = 0; i < 5; i = i + 1) begin
                stage_cfg[i] <= 4'd0;
                data_pipe[i] <= 512'd0;
            end
            for (i = 0; i < 4; i = i + 1) cfg_pipe[i] <= 20'd0;
            valid_pipe <= 5'd0;
            inflight   <= 64'd0;
            beats_done <= 64'd0;
            armed      <= 1'b0;
for (i = 0; i < 5; i = i + 1) begin
inv_stage_cfg[i] <= 4'd0;
inv_data_pipe[i] <= 512'd0;
end
for (i = 0; i < 4; i = i + 1) inv_cfg_pipe[i] <= 20'd0;
inv_valid_pipe <= 5'd0;
inv_beats_done <= 64'd0;
last_dir       <= 1'b0;
dir_switches   <= 64'd0;
        end else if (en) begin
            if (cfg_we) begin
                cfg_tab[cfg_addr] <= cfg_bits;
                armed <= 1'b1;
            end
            data_pipe[0] <= sw4(in_data, cfg0[3:0]);
            stage_cfg[0] <= cfg0[3:0];
            cfg_pipe[0]  <= cfg0;
            data_pipe[1] <= sw2(data_pipe[0], cfg_pipe[0][7:4]);
            stage_cfg[1] <= cfg_pipe[0][7:4];
            cfg_pipe[1]  <= cfg_pipe[0];
            data_pipe[2] <= sw1(data_pipe[1], cfg_pipe[1][11:8]);
            stage_cfg[2] <= cfg_pipe[1][11:8];
            cfg_pipe[2]  <= cfg_pipe[1];
            data_pipe[3] <= sw2(data_pipe[2], cfg_pipe[2][15:12]);
            stage_cfg[3] <= cfg_pipe[2][15:12];
            cfg_pipe[3]  <= cfg_pipe[2];
            data_pipe[4] <= sw4(data_pipe[3], cfg_pipe[3][19:16]);
            stage_cfg[4] <= cfg_pipe[3][19:16];
valid_pipe <= {valid_pipe[3:0], go_fwd};
inflight   <= inflight + {63'd0, in_valid} - {63'd0, retire_fwd} - {63'd0, retire_inv};
            if (valid_pipe[4])
                beats_done <= beats_done + 64'd1;
// inverse lane: same switch stages, control fields applied in reverse
inv_data_pipe[0] <= sw4(in_data, cfg0[19:16]);
inv_stage_cfg[0] <= cfg0[19:16];
inv_cfg_pipe[0]  <= cfg0;
inv_data_pipe[1] <= sw2(inv_data_pipe[0], inv_cfg_pipe[0][15:12]);
inv_stage_cfg[1] <= inv_cfg_pipe[0][15:12];
inv_cfg_pipe[1]  <= inv_cfg_pipe[0];
inv_data_pipe[2] <= sw1(inv_data_pipe[1], inv_cfg_pipe[1][11:8]);
inv_stage_cfg[2] <= inv_cfg_pipe[1][11:8];
inv_cfg_pipe[2]  <= inv_cfg_pipe[1];
inv_data_pipe[3] <= sw2(inv_data_pipe[2], inv_cfg_pipe[2][7:4]);
inv_stage_cfg[3] <= inv_cfg_pipe[2][7:4];
inv_cfg_pipe[3]  <= inv_cfg_pipe[2];
inv_data_pipe[4] <= sw4(inv_data_pipe[3], inv_cfg_pipe[3][3:0]);
inv_stage_cfg[4] <= inv_cfg_pipe[3][3:0];
inv_valid_pipe <= {inv_valid_pipe[3:0], go_inv};
if (retire_inv)
inv_beats_done <= inv_beats_done + 64'd1;
// turnaround statistics: count lane direction changes on the input port
if (in_valid) begin
last_dir <= in_sel[7];
if (in_sel[7] != last_dir)
dir_switches <= dir_switches + 64'd1;
end
        end
    end

    assign out_valid    = valid_pipe[4];
    assign out_data     = data_pipe[4];
    assign o_beats_done = beats_done;
assign out_inv_valid    = inv_valid_pipe[4];
assign out_inv_data     = inv_data_pipe[4];
assign o_inv_beats_done = inv_beats_done;
assign o_any_valid      = retire_fwd | retire_inv;
assign o_merged_data    = retire_inv ? inv_data_pipe[4] : data_pipe[4];
assign o_dir_switches   = dir_switches;

    always @(posedge clk)
        if (armed)
            assert (inflight <= 64'd5);
endmodule

module fm_frame_guard (
   input  wire       clk,
   input  wire       rst,
   input  wire       i_open,
   input  wire       i_close,
   input  wire       i_byte,
   input  wire [7:0] i_data,
   output reg        o_open,
   output reg        o_abort,
   output reg  [5:0] o_len,
   output reg  [7:0] o_csum,
   output reg  [7:0] o_last_csum,
   output reg  [5:0] o_last_len,
   output reg  [5:0] o_max_len,
   output reg  [7:0] o_runt_cnt,
   output reg  [7:0] o_abort_cnt,
   output reg  [7:0] o_good_cnt,
   output reg  [1:0] o_status
);
   // frames longer than LEN_FULL payload bytes are cut off with an abort,
   // frames shorter than LEN_MIN bytes are counted as runts
   localparam [5:0] LEN_FULL = 6'd63;
   localparam [5:0] LEN_MIN  = 6'd4;
   localparam [1:0] ST_NONE = 2'd0, ST_GOOD = 2'd1, ST_RUNT = 2'd2, ST_ABORT = 2'd3;

   wire       byte_ok   = i_byte && o_open && !o_abort;
   wire       overrun   = byte_ok && (o_len == LEN_FULL);
   wire       close_frm = i_close && o_open;
   wire       is_runt   = (o_len < LEN_MIN);
   wire [7:0] csum_nxt  = {o_csum[6:0], o_csum[7]} ^ i_data;
   wire       runt_sat  = (o_runt_cnt == 8'hFF);
   wire       abort_sat = (o_abort_cnt == 8'hFF);
   wire       good_sat  = (o_good_cnt == 8'hFF);

   initial begin
       o_open = 1'b0; o_abort = 1'b0; o_len = 6'd0; o_csum = 8'd0;
       o_last_csum = 8'd0; o_last_len = 6'd0; o_max_len = 6'd0;
       o_runt_cnt = 8'd0; o_abort_cnt = 8'd0; o_good_cnt = 8'd0;
       o_status = ST_NONE;
   end

   // frame window and overrun abort request
   always @(posedge clk) begin
       if (rst) begin
           o_open  <= 1'b0;
           o_abort <= 1'b0;
       end else if (close_frm) begin
           o_open  <= 1'b0;
           o_abort <= 1'b0;
       end else if (i_open) begin
           o_open  <= 1'b1;
           o_abort <= 1'b0;
       end else if (overrun) begin
           o_abort <= 1'b1;
       end
   end

   // payload length and rotating checksum of the open frame
   always @(posedge clk) begin
       if (rst) begin
           o_len  <= 6'd0;
           o_csum <= 8'd0;
       end else if (i_open && !o_open) begin
           o_len  <= 6'd0;
           o_csum <= 8'd0;
       end else if (byte_ok && !overrun) begin
           o_len  <= o_len + 6'd1;
           o_csum <= csum_nxt;
       end
   end

   // record of the most recently closed frame
   always @(posedge clk) begin
       if (rst) begin
           o_last_csum <= 8'd0;
           o_last_len  <= 6'd0;
           o_status    <= ST_NONE;
       end else if (close_frm) begin
           o_last_csum <= o_csum;
           o_last_len  <= o_len;
           if (o_abort)
               o_status <= ST_ABORT;
           else if (is_runt)
               o_status <= ST_RUNT;
           else
               o_status <= ST_GOOD;
       end
   end

   // link statistics, saturating
   always @(posedge clk) begin
       if (rst) begin
           o_max_len   <= 6'd0;
           o_runt_cnt  <= 8'd0;
           o_abort_cnt <= 8'd0;
           o_good_cnt  <= 8'd0;
       end else if (close_frm) begin
           if (o_abort) begin
               if (!abort_sat) o_abort_cnt <= o_abort_cnt + 8'd1;
           end else begin
               if (o_len > o_max_len) o_max_len <= o_len;
               if (is_runt && !runt_sat) o_runt_cnt <= o_runt_cnt + 8'd1;
               if (!is_runt && !good_sat) o_good_cnt <= o_good_cnt + 8'd1;
           end
       end
   end
endmodule

module fm_link_8b10b_framer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [7:0]  i_data,
    output reg  [9:0]  o_sym,
    output reg         o_rd,
    output reg  [31:0] o_sym_cnt,
   output reg  [31:0] o_pkt_cnt,
   output wire        o_frm_open,
   output wire        o_frm_abort,
   output wire [5:0]  o_frm_len,
   output wire [7:0]  o_frm_csum,
   output wire [7:0]  o_last_csum,
   output wire [5:0]  o_last_len,
   output wire [5:0]  o_max_len,
   output wire [7:0]  o_runt_cnt,
   output wire [7:0]  o_abort_cnt,
   output wire [7:0]  o_good_cnt,
   output wire [1:0]  o_frm_status
);
    localparam [1:0] K_COMMA = 2'd1, K_SOF = 2'd2, K_EOF = 2'd3;
    localparam [1:0] PH_IDLE = 2'd0, PH_ALIGN = 2'd1, PH_PKT = 2'd2;

    reg [1:0] phase;
    reg seen_comma, seen_start, seen_end;

    initial begin
        phase = PH_IDLE; seen_comma = 1'b0; seen_start = 1'b0; seen_end = 1'b0;
        o_sym = 10'd0; o_rd = 1'b0; o_sym_cnt = 32'd0; o_pkt_cnt = 32'd0;
    end

    function [5:0] enc6;
        input [4:0] x;
        begin
            case (x)
                5'd0:  enc6 = 6'b100111;
                5'd1:  enc6 = 6'b011101;
                5'd2:  enc6 = 6'b101101;
                5'd3:  enc6 = 6'b110001;
                5'd4:  enc6 = 6'b110101;
                5'd5:  enc6 = 6'b101001;
                5'd6:  enc6 = 6'b011001;
                5'd7:  enc6 = 6'b111000;
                5'd8:  enc6 = 6'b111001;
                5'd9:  enc6 = 6'b100101;
                5'd10: enc6 = 6'b010101;
                5'd11: enc6 = 6'b110100;
                5'd12: enc6 = 6'b001101;
                5'd13: enc6 = 6'b101100;
                5'd14: enc6 = 6'b011100;
                5'd15: enc6 = 6'b010111;
                5'd16: enc6 = 6'b011011;
                5'd17: enc6 = 6'b100011;
                5'd18: enc6 = 6'b010011;
                5'd19: enc6 = 6'b110010;
                5'd20: enc6 = 6'b001011;
                5'd21: enc6 = 6'b101010;
                5'd22: enc6 = 6'b011010;
                5'd23: enc6 = 6'b111010;
                5'd24: enc6 = 6'b110011;
                5'd25: enc6 = 6'b100110;
                5'd26: enc6 = 6'b010110;
                5'd27: enc6 = 6'b110110;
                5'd28: enc6 = 6'b001110;
                5'd29: enc6 = 6'b101110;
                5'd30: enc6 = 6'b011110;
                default: enc6 = 6'b101011;
            endcase
        end
    endfunction

    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
                3'd5: enc4 = 4'b1010;
                3'd6: enc4 = 4'b0110;
                default: enc4 = 4'b1110;
            endcase
        end
    endfunction

    function [2:0] ones6;
        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
    wire do_comma = i_ce && i_k && (i_kcode == K_COMMA);
    wire do_sof   = i_ce && i_k && (i_kcode == K_SOF) && (phase == PH_ALIGN);
    wire do_eof   = i_ce && i_k && (i_kcode == K_EOF) && (phase == PH_PKT);
    wire do_data  = i_ce && !i_k;

   // frame length guard: a frame that overruns the payload limit is closed
   // early with a K30.7 abort symbol in place of the next offered symbol
   wire       frm_open, frm_abort;
   wire       do_abort = i_ce && frm_abort;

   fm_frame_guard u_guard (
       .clk        (clk),
       .rst        (rst),
       .i_open     (do_sof && !do_abort),
       .i_close    (do_abort || do_eof),
       .i_byte     (do_data && !do_abort),
       .i_data     (i_data),
       .o_open     (frm_open),
       .o_abort    (frm_abort),
       .o_len      (o_frm_len),
       .o_csum     (o_frm_csum),
       .o_last_csum(o_last_csum),
       .o_last_len (o_last_len),
       .o_max_len  (o_max_len),
       .o_runt_cnt (o_runt_cnt),
       .o_abort_cnt(o_abort_cnt),
       .o_good_cnt (o_good_cnt),
       .o_status   (o_frm_status)
   );

   assign o_frm_open  = frm_open;
   assign o_frm_abort = frm_abort;

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
       end else if (do_abort) begin
           o_sym      <= o_rd ? 10'b1000010111 : 10'b0111101000;
           seen_end   <= 1'b1;
           phase      <= PH_ALIGN;
           o_sym_cnt  <= o_sym_cnt + 32'd1;
       end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));
endmodule

module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire [63:0] o_hist_stamp,
   output wire [15:0] o_hist_sig,
   output wire [1:0] o_hist_state,
   output wire [2:0] o_hist_level,
   output wire o_hist_open,
   output wire [15:0] o_last_sig,
   output wire [7:0] o_hist_drops,
   output wire [7:0] o_abort_cnt,
   output wire [63:0] o_ret_stamp,
   output wire [15:0] o_ret_sig,
   output wire [1:0] o_ret_state,
   output wire o_ret_valid
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;
   localparam [1:0] ST_FREE = 2'd0, ST_OPEN = 2'd1, ST_DONE = 2'd2, ST_ABRT = 2'd3;
   localparam [4:0] HIST_CLR = 5'd30, HIST_ACK = 5'd31;
   localparam [2:0] HIST_DEPTH = 3'd4;
   // frame history: one record per launched frame, oldest at hist_rd_ptr
   reg [63:0] hist_mem [0:3];
   reg [15:0] hist_sum [0:3];
   reg [1:0]  hist_st  [0:3];
   reg [1:0]  hist_wr_ptr;
   reg [1:0]  hist_rd_ptr;
   reg [2:0]  hist_cnt;
   reg [7:0]  hist_drop;
   reg [7:0]  abort_cnt;
   reg [15:0] frame_sig;
   // last record retired through HIST_ACK
   reg [63:0] ret_stamp;
   reg [15:0] ret_sum;
   reg [1:0]  ret_st;
   reg        ret_vld;
   integer j;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;
   initial begin
       for (j = 0; j < 4; j = j + 1) begin
           hist_mem[j] = 64'd0;
           hist_sum[j] = 16'd0;
           hist_st[j] = ST_FREE;
       end
   end
   initial hist_wr_ptr = 2'd0;
   initial hist_rd_ptr = 2'd0;
   initial hist_cnt = 3'd0;
   initial hist_drop = 8'd0;
   initial abort_cnt = 8'd0;
   initial frame_sig = 16'd0;
   initial ret_stamp = 64'd0;
   initial ret_sum = 16'd0;
   initial ret_st = ST_FREE;
   initial ret_vld = 1'b0;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire [1:0]  hist_last  = hist_wr_ptr - 2'd1;
   wire        hist_empty = (hist_cnt == 3'd0);
   wire        hist_full  = (hist_cnt == HIST_DEPTH);
   // a new record is opened whenever a frame is launched
   wire        hist_push  = !abort_req && (phase == ARMED) && start_req;
   // the record of the frame on screen (running or just finished) may not be acked away
   wire        hist_pin   = (hist_cnt == 3'd1) && ((phase == RUN) || done);
   wire        hist_ack   = wr_en && (wr_addr == HIST_ACK) && !hist_empty && !hist_push && !hist_pin;
   wire        hist_clr   = wr_en && (wr_addr == HIST_CLR) && (phase != RUN) && !done && !hist_push;
   wire        frame_end  = !abort_req && (phase == RUN) && last_col && last_row;
   wire        frame_kill = abort_req && (phase == RUN);
   wire [7:0]  next_pix   = font_row(cur_char, row_cnt[2:0]);
   wire [15:0] next_sig   = {frame_sig[14:0], frame_sig[15] ^ frame_sig[12]} ^ {frame_sig[3:0], 4'h0, next_pix};

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
           for (j = 0; j < 4; j = j + 1) begin
               hist_mem[j] <= 64'd0;
               hist_sum[j] <= 16'd0;
               hist_st[j] <= ST_FREE;
           end
           hist_wr_ptr <= 2'd0;
           hist_rd_ptr <= 2'd0;
           hist_cnt <= 3'd0;
           hist_drop <= 8'd0;
           abort_cnt <= 8'd0;
           frame_sig <= 16'd0;
           ret_stamp <= 64'd0;
           ret_sum <= 16'd0;
           ret_st <= ST_FREE;
           ret_vld <= 1'b0;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                        if (start_req) begin
                            phase <= RUN;
                            start_seen <= 1'b1;
                            col_cnt <= 64'd0;
                            row_cnt <= 64'd0;
                        end
                    end
                    RUN: begin
                        pix_row <= font_row(cur_char, row_cnt[2:0]);
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                done <= 1'b1;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                    end
                    FIN: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
            end
           // ---- frame history ----
           if (hist_push)
               frame_sig <= 16'd0;
           else if (!abort_req && (phase == RUN))
               frame_sig <= next_sig;
           if (hist_push) begin
               hist_mem[hist_wr_ptr] <= frame_cnt + 64'd1;
               hist_sum[hist_wr_ptr] <= 16'd0;
               hist_st[hist_wr_ptr] <= ST_OPEN;
               hist_wr_ptr <= hist_wr_ptr + 2'd1;
               if (hist_full) begin
                   // overwrite the oldest record and account for the loss
                   hist_rd_ptr <= hist_rd_ptr + 2'd1;
                   if (hist_drop != 8'hFF)
                       hist_drop <= hist_drop + 8'd1;
               end else begin
                   hist_cnt <= hist_cnt + 3'd1;
               end
           end else if (hist_ack) begin
               ret_stamp <= hist_mem[hist_rd_ptr];
               ret_sum <= hist_sum[hist_rd_ptr];
               ret_st <= hist_st[hist_rd_ptr];
               ret_vld <= 1'b1;
               hist_st[hist_rd_ptr] <= ST_FREE;
               hist_rd_ptr <= hist_rd_ptr + 2'd1;
               hist_cnt <= hist_cnt - 3'd1;
           end else if (hist_clr) begin
               for (j = 0; j < 4; j = j + 1)
                   hist_st[j] <= ST_FREE;
               hist_rd_ptr <= hist_wr_ptr;
               hist_cnt <= 3'd0;
               ret_vld <= 1'b0;
           end
           if (frame_kill) begin
               hist_st[hist_last] <= ST_ABRT;
               hist_sum[hist_last] <= frame_sig;
               if (abort_cnt != 8'hFF)
                   abort_cnt <= abort_cnt + 8'd1;
           end
           if (frame_end) begin
               hist_st[hist_last] <= ST_DONE;
               hist_sum[hist_last] <= next_sig;
           end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_hist_stamp = hist_empty ? 64'd0 : hist_mem[hist_rd_ptr];
   assign o_hist_sig = hist_empty ? 16'd0 : hist_sum[hist_rd_ptr];
   assign o_hist_state = hist_empty ? ST_FREE : hist_st[hist_rd_ptr];
   assign o_hist_level = hist_cnt;
   assign o_hist_open = !hist_empty && (hist_st[hist_last] == ST_OPEN);
   assign o_last_sig = hist_empty ? 16'd0 : hist_sum[hist_last];
   assign o_hist_drops = hist_drop;
   assign o_abort_cnt = abort_cnt;
   assign o_ret_stamp = ret_stamp;
   assign o_ret_sig = ret_sum;
   assign o_ret_state = ret_st;
   assign o_ret_valid = ret_vld;

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);

   always @(posedge clk)
       if (done)
           assert (hist_cnt != 3'd0 && hist_st[hist_last] == ST_DONE && hist_mem[hist_last] == frame_cnt);
endmodule

module fm_frame_guard (
   input  wire       clk,
   input  wire       rst,
   input  wire       i_open,
   input  wire       i_close,
   input  wire       i_byte,
   input  wire [7:0] i_data,
   output reg        o_open,
   output reg        o_abort,
   output reg  [5:0] o_len,
   output reg  [7:0] o_csum,
   output reg  [7:0] o_last_csum,
   output reg  [5:0] o_last_len,
   output reg  [5:0] o_max_len,
   output reg  [7:0] o_runt_cnt,
   output reg  [7:0] o_abort_cnt,
   output reg  [7:0] o_good_cnt,
   output reg  [1:0] o_status
);
   // frames longer than LEN_FULL payload bytes are cut off with an abort,
   // frames shorter than LEN_MIN bytes are counted as runts
   localparam [5:0] LEN_FULL = 6'd63;
   localparam [5:0] LEN_MIN  = 6'd4;
   localparam [1:0] ST_NONE = 2'd0, ST_GOOD = 2'd1, ST_RUNT = 2'd2, ST_ABORT = 2'd3;

   wire       byte_ok   = i_byte && o_open && !o_abort;
   wire       overrun   = byte_ok && (o_len == LEN_FULL);
   wire       close_frm = i_close && o_open;
   wire       is_runt   = (o_len < LEN_MIN);
   wire [7:0] csum_nxt  = {o_csum[6:0], o_csum[7]} ^ i_data;
   wire       runt_sat  = (o_runt_cnt == 8'hFF);
   wire       abort_sat = (o_abort_cnt == 8'hFF);
   wire       good_sat  = (o_good_cnt == 8'hFF);

   initial begin
       o_open = 1'b0; o_abort = 1'b0; o_len = 6'd0; o_csum = 8'd0;
       o_last_csum = 8'd0; o_last_len = 6'd0; o_max_len = 6'd0;
       o_runt_cnt = 8'd0; o_abort_cnt = 8'd0; o_good_cnt = 8'd0;
       o_status = ST_NONE;
   end

   // frame window and overrun abort request
   always @(posedge clk) begin
       if (rst) begin
           o_open  <= 1'b0;
           o_abort <= 1'b0;
       end else if (close_frm) begin
           o_open  <= 1'b0;
           o_abort <= 1'b0;
       end else if (i_open) begin
           o_open  <= 1'b1;
           o_abort <= 1'b0;
       end else if (overrun) begin
           o_abort <= 1'b1;
       end
   end

   // payload length and rotating checksum of the open frame
   always @(posedge clk) begin
       if (rst) begin
           o_len  <= 6'd0;
           o_csum <= 8'd0;
       end else if (i_open && !o_open) begin
           o_len  <= 6'd0;
           o_csum <= 8'd0;
       end else if (byte_ok && !overrun) begin
           o_len  <= o_len + 6'd1;
           o_csum <= csum_nxt;
       end
   end

   // record of the most recently closed frame
   always @(posedge clk) begin
       if (rst) begin
           o_last_csum <= 8'd0;
           o_last_len  <= 6'd0;
           o_status    <= ST_NONE;
       end else if (close_frm) begin
           o_last_csum <= o_csum;
           o_last_len  <= o_len;
           if (o_abort)
               o_status <= ST_ABORT;
           else if (is_runt)
               o_status <= ST_RUNT;
           else
               o_status <= ST_GOOD;
       end
   end

   // link statistics, saturating
   always @(posedge clk) begin
       if (rst) begin
           o_max_len   <= 6'd0;
           o_runt_cnt  <= 8'd0;
           o_abort_cnt <= 8'd0;
           o_good_cnt  <= 8'd0;
       end else if (close_frm) begin
           if (o_abort) begin
               if (!abort_sat) o_abort_cnt <= o_abort_cnt + 8'd1;
           end else begin
               if (o_len > o_max_len) o_max_len <= o_len;
               if (is_runt && !runt_sat) o_runt_cnt <= o_runt_cnt + 8'd1;
               if (!is_runt && !good_sat) o_good_cnt <= o_good_cnt + 8'd1;
           end
       end
   end
endmodule

module fm_link_8b10b_framer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [7:0]  i_data,
    output reg  [9:0]  o_sym,
    output reg         o_rd,
    output reg  [31:0] o_sym_cnt,
   output reg  [31:0] o_pkt_cnt,
   output wire        o_frm_open,
   output wire        o_frm_abort,
   output wire [5:0]  o_frm_len,
   output wire [7:0]  o_frm_csum,
   output wire [7:0]  o_last_csum,
   output wire [5:0]  o_last_len,
   output wire [5:0]  o_max_len,
   output wire [7:0]  o_runt_cnt,
   output wire [7:0]  o_abort_cnt,
   output wire [7:0]  o_good_cnt,
output wire [1:0]  o_frm_status,
output reg         o_desc_valid,
output reg  [5:0]  o_desc_len,
output reg  [7:0]  o_desc_csum,
output reg  [1:0]  o_desc_stat,
output reg  [3:0]  o_desc_seq,
output reg         o_desc_perr,
output wire [3:0]  o_q_level,
output wire        o_q_full,
output reg  [7:0]  o_sof_refused
);
    localparam [1:0] K_COMMA = 2'd1, K_SOF = 2'd2, K_EOF = 2'd3;
    localparam [1:0] PH_IDLE = 2'd0, PH_ALIGN = 2'd1, PH_PKT = 2'd2;

    reg [1:0] phase;
    reg seen_comma, seen_start, seen_end;
   // frame descriptor queue: each accepted SOF reserves the youngest slot,
   // the slot is completed with length, checksum and status when the frame
   // closes (EOF or abort), and completed slots are handed to the host port
   // in order on idle (clock-enable low) cycles, one every DRAIN_GAP+1 cycles
   localparam [3:0] Q_DEPTH   = 4'd8;
   localparam [1:0] DRAIN_GAP = 2'd3;
   localparam [5:0] RUNT_LEN  = 6'd4;
   localparam [1:0] ST_NONE = 2'd0, ST_GOOD = 2'd1, ST_RUNT = 2'd2, ST_ABORT = 2'd3;
   reg  [2:0] q_wr, q_rd;
   reg  [3:0] q_cnt;
   reg  [7:0] q_done;
   reg  [1:0] q_hold;
   reg  [3:0] q_seq;
   reg  [5:0] q0_len, q1_len, q2_len, q3_len, q4_len, q5_len, q6_len, q7_len;
   reg  [7:0] q0_csum, q1_csum, q2_csum, q3_csum, q4_csum, q5_csum, q6_csum, q7_csum;
   reg  [1:0] q0_stat, q1_stat, q2_stat, q3_stat, q4_stat, q5_stat, q6_stat, q7_stat;
   reg  [3:0] q0_seq, q1_seq, q2_seq, q3_seq, q4_seq, q5_seq, q6_seq, q7_seq;
   reg        q0_par, q1_par, q2_par, q3_par, q4_par, q5_par, q6_par, q7_par;
   wire       q_room = (q_cnt != Q_DEPTH);
   wire [2:0] q_tail = q_wr - 3'd1;
   initial begin
       q_wr = 3'd0; q_rd = 3'd0; q_cnt = 4'd0; q_done = 8'd0; q_hold = 2'd0; q_seq = 4'd0;
       q0_len = 6'd0; q0_csum = 8'd0; q0_stat = ST_NONE; q0_seq = 4'd0; q0_par = 1'b0;
       q1_len = 6'd0; q1_csum = 8'd0; q1_stat = ST_NONE; q1_seq = 4'd0; q1_par = 1'b0;
       q2_len = 6'd0; q2_csum = 8'd0; q2_stat = ST_NONE; q2_seq = 4'd0; q2_par = 1'b0;
       q3_len = 6'd0; q3_csum = 8'd0; q3_stat = ST_NONE; q3_seq = 4'd0; q3_par = 1'b0;
       q4_len = 6'd0; q4_csum = 8'd0; q4_stat = ST_NONE; q4_seq = 4'd0; q4_par = 1'b0;
       q5_len = 6'd0; q5_csum = 8'd0; q5_stat = ST_NONE; q5_seq = 4'd0; q5_par = 1'b0;
       q6_len = 6'd0; q6_csum = 8'd0; q6_stat = ST_NONE; q6_seq = 4'd0; q6_par = 1'b0;
       q7_len = 6'd0; q7_csum = 8'd0; q7_stat = ST_NONE; q7_seq = 4'd0; q7_par = 1'b0;
       o_desc_valid = 1'b0; o_desc_len = 6'd0; o_desc_csum = 8'd0; o_desc_stat = ST_NONE;
       o_desc_seq = 4'd0; o_desc_perr = 1'b0; o_sof_refused = 8'd0;
   end

    initial begin
        phase = PH_IDLE; seen_comma = 1'b0; seen_start = 1'b0; seen_end = 1'b0;
        o_sym = 10'd0; o_rd = 1'b0; o_sym_cnt = 32'd0; o_pkt_cnt = 32'd0;
    end

    function [5:0] enc6;
        input [4:0] x;
        begin
            case (x)
                5'd0:  enc6 = 6'b100111;
                5'd1:  enc6 = 6'b011101;
                5'd2:  enc6 = 6'b101101;
                5'd3:  enc6 = 6'b110001;
                5'd4:  enc6 = 6'b110101;
                5'd5:  enc6 = 6'b101001;
                5'd6:  enc6 = 6'b011001;
                5'd7:  enc6 = 6'b111000;
                5'd8:  enc6 = 6'b111001;
                5'd9:  enc6 = 6'b100101;
                5'd10: enc6 = 6'b010101;
                5'd11: enc6 = 6'b110100;
                5'd12: enc6 = 6'b001101;
                5'd13: enc6 = 6'b101100;
                5'd14: enc6 = 6'b011100;
                5'd15: enc6 = 6'b010111;
                5'd16: enc6 = 6'b011011;
                5'd17: enc6 = 6'b100011;
                5'd18: enc6 = 6'b010011;
                5'd19: enc6 = 6'b110010;
                5'd20: enc6 = 6'b001011;
                5'd21: enc6 = 6'b101010;
                5'd22: enc6 = 6'b011010;
                5'd23: enc6 = 6'b111010;
                5'd24: enc6 = 6'b110011;
                5'd25: enc6 = 6'b100110;
                5'd26: enc6 = 6'b010110;
                5'd27: enc6 = 6'b110110;
                5'd28: enc6 = 6'b001110;
                5'd29: enc6 = 6'b101110;
                5'd30: enc6 = 6'b011110;
                default: enc6 = 6'b101011;
            endcase
        end
    endfunction

    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
                3'd5: enc4 = 4'b1010;
                3'd6: enc4 = 4'b0110;
                default: enc4 = 4'b1110;
            endcase
        end
    endfunction

    function [2:0] ones6;
        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
    wire do_comma = i_ce && i_k && (i_kcode == K_COMMA);
   wire do_sof   = i_ce && i_k && (i_kcode == K_SOF) && (phase == PH_ALIGN) && q_room;
   wire sof_refused = i_ce && i_k && (i_kcode == K_SOF) && (phase == PH_ALIGN) && !q_room;
    wire do_eof   = i_ce && i_k && (i_kcode == K_EOF) && (phase == PH_PKT);
    wire do_data  = i_ce && !i_k;

   // frame length guard: a frame that overruns the payload limit is closed
   // early with a K30.7 abort symbol in place of the next offered symbol
   wire       frm_open, frm_abort;
   wire       do_abort = i_ce && frm_abort;

   fm_frame_guard u_guard (
       .clk        (clk),
       .rst        (rst),
       .i_open     (do_sof && !do_abort),
       .i_close    (do_abort || do_eof),
       .i_byte     (do_data && !do_abort),
       .i_data     (i_data),
       .o_open     (frm_open),
       .o_abort    (frm_abort),
       .o_len      (o_frm_len),
       .o_csum     (o_frm_csum),
       .o_last_csum(o_last_csum),
       .o_last_len (o_last_len),
       .o_max_len  (o_max_len),
       .o_runt_cnt (o_runt_cnt),
       .o_abort_cnt(o_abort_cnt),
       .o_good_cnt (o_good_cnt),
       .o_status   (o_frm_status)
   );

   assign o_frm_open  = frm_open;
   assign o_frm_abort = frm_abort;
  // descriptor queue: reserve on SOF, complete on close, drain on idle
  wire        q_rsv      = do_sof && !do_abort;
  wire        q_fill     = (do_abort || do_eof) && frm_open;
  wire        q_pop      = !i_ce && (q_cnt != 4'd0) && q_done[q_rd] && (q_hold == 2'd0);
  wire [7:0]  q_rsv_sel  = q_rsv  ? (8'd1 << q_wr)   : 8'd0;
  wire [7:0]  q_fill_sel = q_fill ? (8'd1 << q_tail) : 8'd0;
  wire [7:0]  q_pop_sel  = q_pop  ? (8'd1 << q_rd)   : 8'd0;
  wire [1:0]  fill_stat  = frm_abort ? ST_ABORT : ((o_frm_len < RUNT_LEN) ? ST_RUNT : ST_GOOD);
  wire        fill_par   = ^{fill_stat, o_frm_len, o_frm_csum};
  // packed slot words {parity, seq, status, length, checksum}
  wire [20:0] q0_word = {q0_par, q0_seq, q0_stat, q0_len, q0_csum};
  wire [20:0] q1_word = {q1_par, q1_seq, q1_stat, q1_len, q1_csum};
  wire [20:0] q2_word = {q2_par, q2_seq, q2_stat, q2_len, q2_csum};
  wire [20:0] q3_word = {q3_par, q3_seq, q3_stat, q3_len, q3_csum};
  wire [20:0] q4_word = {q4_par, q4_seq, q4_stat, q4_len, q4_csum};
  wire [20:0] q5_word = {q5_par, q5_seq, q5_stat, q5_len, q5_csum};
  wire [20:0] q6_word = {q6_par, q6_seq, q6_stat, q6_len, q6_csum};
  wire [20:0] q7_word = {q7_par, q7_seq, q7_stat, q7_len, q7_csum};
  function [20:0] q_pick;
      input [2:0]  s;
      input [20:0] w0, w1, w2, w3, w4, w5, w6, w7;
      begin
          case (s)
              3'd0: q_pick = w0;
              3'd1: q_pick = w1;
              3'd2: q_pick = w2;
              3'd3: q_pick = w3;
              3'd4: q_pick = w4;
              3'd5: q_pick = w5;
              3'd6: q_pick = w6;
              default: q_pick = w7;
          endcase
      end
  endfunction
  wire [20:0] rd_word = q_pick(q_rd, q0_word, q1_word, q2_word, q3_word, q4_word, q5_word, q6_word, q7_word);
  wire [7:0]  rd_csum = rd_word[7:0];
  wire [5:0]  rd_len  = rd_word[13:8];
  wire [1:0]  rd_stat = rd_word[15:14];
  wire [3:0]  rd_seq  = rd_word[19:16];
  wire        rd_perr = ^rd_word;
  assign o_q_level = q_cnt;
  assign o_q_full  = !q_room;
  // queue pointers, occupancy and completion flags
  always @(posedge clk) begin
      if (rst) begin
          q_wr   <= 3'd0;
          q_rd   <= 3'd0;
          q_cnt  <= 4'd0;
          q_done <= 8'd0;
          q_seq  <= 4'd0;
      end else begin
          q_done <= (q_done & ~(q_rsv_sel | q_pop_sel)) | q_fill_sel;
          if (q_rsv) begin
              q_wr  <= q_wr + 3'd1;
              q_seq <= q_seq + 4'd1;
          end
          if (q_pop)
              q_rd <= q_rd + 3'd1;
          if (q_rsv && !q_pop)
              q_cnt <= q_cnt + 4'd1;
          else if (q_pop && !q_rsv)
              q_cnt <= q_cnt - 4'd1;
      end
  end
  // host port pacing: after a hand-off the port is busy for DRAIN_GAP cycles
  always @(posedge clk) begin
      if (rst)
          q_hold <= 2'd0;
      else if (q_pop)
          q_hold <= DRAIN_GAP;
      else if (q_hold != 2'd0)
          q_hold <= q_hold - 2'd1;
  end
  always @(posedge clk) begin
      if (rst) begin
          q0_len  <= 6'd0;
          q0_csum <= 8'd0;
          q0_stat <= ST_NONE;
          q0_seq  <= 4'd0;
          q0_par  <= 1'b0;
      end else if (q_rsv_sel[0]) begin
          q0_len  <= 6'd0;
          q0_csum <= 8'd0;
          q0_stat <= ST_NONE;
          q0_seq  <= q_seq;
          q0_par  <= ^q_seq;
      end else if (q_fill_sel[0]) begin
          q0_len  <= o_frm_len;
          q0_csum <= o_frm_csum;
          q0_stat <= fill_stat;
          q0_par  <= fill_par ^ (^q0_seq);
      end
  end
  always @(posedge clk) begin
      if (rst) begin
          q1_len  <= 6'd0;
          q1_csum <= 8'd0;
          q1_stat <= ST_NONE;
          q1_seq  <= 4'd0;
          q1_par  <= 1'b0;
      end else if (q_rsv_sel[1]) begin
          q1_len  <= 6'd0;
          q1_csum <= 8'd0;
          q1_stat <= ST_NONE;
          q1_seq  <= q_seq;
          q1_par  <= ^q_seq;
      end else if (q_fill_sel[1]) begin
          q1_len  <= o_frm_len;
          q1_csum <= o_frm_csum;
          q1_stat <= fill_stat;
          q1_par  <= fill_par ^ (^q1_seq);
      end
  end
  always @(posedge clk) begin
      if (rst) begin
          q2_len  <= 6'd0;
          q2_csum <= 8'd0;
          q2_stat <= ST_NONE;
          q2_seq  <= 4'd0;
          q2_par  <= 1'b0;
      end else if (q_rsv_sel[2]) begin
          q2_len  <= 6'd0;
          q2_csum <= 8'd0;
          q2_stat <= ST_NONE;
          q2_seq  <= q_seq;
          q2_par  <= ^q_seq;
      end else if (q_fill_sel[2]) begin
          q2_len  <= o_frm_len;
          q2_csum <= o_frm_csum;
          q2_stat <= fill_stat;
          q2_par  <= fill_par ^ (^q2_seq);
      end
  end
  always @(posedge clk) begin
      if (rst) begin
          q3_len  <= 6'd0;
          q3_csum <= 8'd0;
          q3_stat <= ST_NONE;
          q3_seq  <= 4'd0;
          q3_par  <= 1'b0;
      end else if (q_rsv_sel[3]) begin
          q3_len  <= 6'd0;
          q3_csum <= 8'd0;
          q3_stat <= ST_NONE;
          q3_seq  <= q_seq;
          q3_par  <= ^q_seq;
      end else if (q_fill_sel[3]) begin
          q3_len  <= o_frm_len;
          q3_csum <= o_frm_csum;
          q3_stat <= fill_stat;
          q3_par  <= fill_par ^ (^q3_seq);
      end
  end
  always @(posedge clk) begin
      if (rst) begin
          q4_len  <= 6'd0;
          q4_csum <= 8'd0;
          q4_stat <= ST_NONE;
          q4_seq  <= 4'd0;
          q4_par  <= 1'b0;
      end else if (q_rsv_sel[4]) begin
          q4_len  <= 6'd0;
          q4_csum <= 8'd0;
          q4_stat <= ST_NONE;
          q4_seq  <= q_seq;
          q4_par  <= ^q_seq;
      end else if (q_fill_sel[4]) begin
          q4_len  <= o_frm_len;
          q4_csum <= o_frm_csum;
          q4_stat <= fill_stat;
          q4_par  <= fill_par ^ (^q4_seq);
      end
  end
  always @(posedge clk) begin
      if (rst) begin
          q5_len  <= 6'd0;
          q5_csum <= 8'd0;
          q5_stat <= ST_NONE;
          q5_seq  <= 4'd0;
          q5_par  <= 1'b0;
      end else if (q_rsv_sel[5]) begin
          q5_len  <= 6'd0;
          q5_csum <= 8'd0;
          q5_stat <= ST_NONE;
          q5_seq  <= q_seq;
          q5_par  <= ^q_seq;
      end else if (q_fill_sel[5]) begin
          q5_len  <= o_frm_len;
          q5_csum <= o_frm_csum;
          q5_stat <= fill_stat;
          q5_par  <= fill_par ^ (^q5_seq);
      end
  end
  always @(posedge clk) begin
      if (rst) begin
          q6_len  <= 6'd0;
          q6_csum <= 8'd0;
          q6_stat <= ST_NONE;
          q6_seq  <= 4'd0;
          q6_par  <= 1'b0;
      end else if (q_rsv_sel[6]) begin
          q6_len  <= 6'd0;
          q6_csum <= 8'd0;
          q6_stat <= ST_NONE;
          q6_seq  <= q_seq;
          q6_par  <= ^q_seq;
      end else if (q_fill_sel[6]) begin
          q6_len  <= o_frm_len;
          q6_csum <= o_frm_csum;
          q6_stat <= fill_stat;
          q6_par  <= fill_par ^ (^q6_seq);
      end
  end
  always @(posedge clk) begin
      if (rst) begin
          q7_len  <= 6'd0;
          q7_csum <= 8'd0;
          q7_stat <= ST_NONE;
          q7_seq  <= 4'd0;
          q7_par  <= 1'b0;
      end else if (q_rsv_sel[7]) begin
          q7_len  <= 6'd0;
          q7_csum <= 8'd0;
          q7_stat <= ST_NONE;
          q7_seq  <= q_seq;
          q7_par  <= ^q_seq;
      end else if (q_fill_sel[7]) begin
          q7_len  <= o_frm_len;
          q7_csum <= o_frm_csum;
          q7_stat <= fill_stat;
          q7_par  <= fill_par ^ (^q7_seq);
      end
  end
  // descriptor hand-off to the host, with storage parity check
  always @(posedge clk) begin
      if (rst) begin
          o_desc_valid <= 1'b0;
          o_desc_len   <= 6'd0;
          o_desc_csum  <= 8'd0;
          o_desc_stat  <= ST_NONE;
          o_desc_seq   <= 4'd0;
          o_desc_perr  <= 1'b0;
      end else begin
          o_desc_valid <= q_pop;
          if (q_pop) begin
              o_desc_len  <= rd_len;
              o_desc_csum <= rd_csum;
              o_desc_stat <= rd_stat;
              o_desc_seq  <= rd_seq;
              o_desc_perr <= rd_perr;
          end
      end
  end
  // start-of-frame requests turned away because no descriptor slot was free
  always @(posedge clk) begin
      if (rst)
          o_sof_refused <= 8'd0;
      else if (sof_refused && (o_sof_refused != 8'hFF))
          o_sof_refused <= o_sof_refused + 8'd1;
  end

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
       end else if (do_abort) begin
           o_sym      <= o_rd ? 10'b1000010111 : 10'b0111101000;
           seen_end   <= 1'b1;
           phase      <= PH_ALIGN;
           o_sym_cnt  <= o_sym_cnt + 32'd1;
       end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));
   always @(*) assert ((phase != PH_PKT) || (q_cnt != 4'd0));
endmodule

module fm_pkt_guard #(
   parameter [5:0] MAX_LEN = 6'd48,
   parameter [5:0] MIN_LEN = 6'd4,
   parameter [1:0] IFG     = 2'd3
) (
   input  wire        clk,
   input  wire        rst,
   input  wire        i_sym,
   input  wire        i_in_pkt,
   input  wire        i_sof,
   input  wire        i_eof,
   input  wire        i_trunc,
   input  wire        i_beat,
   input  wire        i_comma,
   input  wire [7:0]  i_data,
   output wire [5:0]  o_len,
   output wire [1:0]  o_holdoff,
   output wire        o_trunc_req,
   output wire        o_sof_ok,
   output reg  [7:0]  o_trunc_cnt,
   output reg  [7:0]  o_drop_cnt,
   output reg  [7:0]  o_runt_cnt,
   output reg  [7:0]  o_kin_cnt,
   output reg  [31:0] o_byte_cnt,
   output reg  [7:0]  o_pkt_sum,
   output reg         o_last_trunc,
   output reg         o_last_runt
);
   reg [5:0] len;
   reg [1:0] holdoff;
   reg [7:0] run_sum;

   initial begin
       len = 6'd0; holdoff = 2'd0; run_sum = 8'd0;
       o_trunc_cnt = 8'd0; o_drop_cnt = 8'd0; o_runt_cnt = 8'd0; o_kin_cnt = 8'd0;
       o_byte_cnt = 32'd0; o_pkt_sum = 8'd0;
       o_last_trunc = 1'b0; o_last_runt = 1'b0;
   end

   // a packet is closed either by a real EOF or by the length limit
   wire at_limit  = (len == MAX_LEN);
   wire close_pkt = i_eof || i_trunc;
   wire take_beat = i_beat && i_in_pkt && !at_limit;
   wire runt      = i_eof && (len < MIN_LEN);
   wire dropped   = i_trunc && i_beat;
   wire in_band_k = i_comma && i_in_pkt;

   assign o_len       = len;
   assign o_holdoff   = holdoff;
   assign o_trunc_req = at_limit;
   assign o_sof_ok    = (holdoff == 2'd0);

   // payload length of the open packet
   always @(posedge clk) begin
       if (rst) begin
           len <= 6'd0;
       end else if (i_sof || close_pkt) begin
           len <= 6'd0;
       end else if (take_beat) begin
           len <= len + 6'd1;
       end
   end

   // minimum inter-frame gap after each packet
   always @(posedge clk) begin
       if (rst) begin
           holdoff <= 2'd0;
       end else if (close_pkt) begin
           holdoff <= IFG;
       end else if (i_sym && (holdoff != 2'd0)) begin
           holdoff <= holdoff - 2'd1;
       end
   end

   // running payload sum, published when the packet closes
   always @(posedge clk) begin
       if (rst) begin
           run_sum   <= 8'd0;
           o_pkt_sum <= 8'd0;
       end else if (i_sof) begin
           run_sum   <= 8'd0;
       end else if (close_pkt) begin
           o_pkt_sum <= run_sum;
           run_sum   <= 8'd0;
       end else if (take_beat) begin
           run_sum   <= run_sum + i_data;
       end
   end

   // saturating event counters
   always @(posedge clk) begin
       if (rst) begin
           o_trunc_cnt <= 8'd0;
           o_drop_cnt  <= 8'd0;
           o_runt_cnt  <= 8'd0;
           o_kin_cnt   <= 8'd0;
       end else begin
           if (i_trunc && (o_trunc_cnt != 8'hFF))
               o_trunc_cnt <= o_trunc_cnt + 8'd1;
           if (dropped && (o_drop_cnt != 8'hFF))
               o_drop_cnt <= o_drop_cnt + 8'd1;
           if (runt && (o_runt_cnt != 8'hFF))
               o_runt_cnt <= o_runt_cnt + 8'd1;
           if (in_band_k && (o_kin_cnt != 8'hFF))
               o_kin_cnt <= o_kin_cnt + 8'd1;
       end
   end

   // payload byte counter and per-packet close status
   always @(posedge clk) begin
       if (rst) begin
           o_byte_cnt   <= 32'd0;
           o_last_trunc <= 1'b0;
           o_last_runt  <= 1'b0;
       end else begin
           if (take_beat)
               o_byte_cnt <= o_byte_cnt + 32'd1;
           if (close_pkt) begin
               o_last_trunc <= i_trunc;
               o_last_runt  <= runt;
           end
       end
   end
endmodule

module fm_link_8b10b_framer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [7:0]  i_data,
    output reg  [9:0]  o_sym,
    output reg         o_rd,
    output reg  [31:0] o_sym_cnt,
   output reg  [31:0] o_pkt_cnt,
   output wire [5:0]  o_pg_len,
   output wire [1:0]  o_pg_holdoff,
   output wire [7:0]  o_trunc_cnt,
   output wire [7:0]  o_drop_cnt,
   output wire [7:0]  o_runt_cnt,
   output wire [7:0]  o_kin_cnt,
   output wire [31:0] o_byte_cnt,
   output wire [7:0]  o_pkt_sum,
   output wire [3:0]  o_pg_status
);
    localparam [1:0] K_COMMA = 2'd1, K_SOF = 2'd2, K_EOF = 2'd3;
    localparam [1:0] PH_IDLE = 2'd0, PH_ALIGN = 2'd1, PH_PKT = 2'd2;

    reg [1:0] phase;
    reg seen_comma, seen_start, seen_end;

    initial begin
        phase = PH_IDLE; seen_comma = 1'b0; seen_start = 1'b0; seen_end = 1'b0;
        o_sym = 10'd0; o_rd = 1'b0; o_sym_cnt = 32'd0; o_pkt_cnt = 32'd0;
    end

    function [5:0] enc6;
        input [4:0] x;
        begin
            case (x)
                5'd0:  enc6 = 6'b100111;
                5'd1:  enc6 = 6'b011101;
                5'd2:  enc6 = 6'b101101;
                5'd3:  enc6 = 6'b110001;
                5'd4:  enc6 = 6'b110101;
                5'd5:  enc6 = 6'b101001;
                5'd6:  enc6 = 6'b011001;
                5'd7:  enc6 = 6'b111000;
                5'd8:  enc6 = 6'b111001;
                5'd9:  enc6 = 6'b100101;
                5'd10: enc6 = 6'b010101;
                5'd11: enc6 = 6'b110100;
                5'd12: enc6 = 6'b001101;
                5'd13: enc6 = 6'b101100;
                5'd14: enc6 = 6'b011100;
                5'd15: enc6 = 6'b010111;
                5'd16: enc6 = 6'b011011;
                5'd17: enc6 = 6'b100011;
                5'd18: enc6 = 6'b010011;
                5'd19: enc6 = 6'b110010;
                5'd20: enc6 = 6'b001011;
                5'd21: enc6 = 6'b101010;
                5'd22: enc6 = 6'b011010;
                5'd23: enc6 = 6'b111010;
                5'd24: enc6 = 6'b110011;
                5'd25: enc6 = 6'b100110;
                5'd26: enc6 = 6'b010110;
                5'd27: enc6 = 6'b110110;
                5'd28: enc6 = 6'b001110;
                5'd29: enc6 = 6'b101110;
                5'd30: enc6 = 6'b011110;
                default: enc6 = 6'b101011;
            endcase
        end
    endfunction

    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
                3'd5: enc4 = 4'b1010;
                3'd6: enc4 = 4'b0110;
                default: enc4 = 4'b1110;
            endcase
        end
    endfunction

    function [2:0] ones6;
        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

   // packet guard status
   wire [5:0] pg_len;
   wire [1:0] pg_holdoff;
   wire       pg_trunc_req;
   wire       pg_sof_ok;
   wire       pg_last_trunc;
   wire       pg_last_runt;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
    wire do_comma = i_ce && i_k && (i_kcode == K_COMMA);
   wire do_sof   = i_ce && i_k && (i_kcode == K_SOF) && (phase == PH_ALIGN) && pg_sof_ok;
    wire do_eof   = i_ce && i_k && (i_kcode == K_EOF) && (phase == PH_PKT);
    wire do_data  = i_ce && !i_k;
   // oversize packet: close it with an EOF in place of the next symbol
   wire do_trunc   = i_ce && pg_trunc_req;
   wire trunc_take = do_trunc && !do_comma && !do_sof && !do_eof;

   fm_pkt_guard #(
       .MAX_LEN(6'd48),
       .MIN_LEN(6'd4),
       .IFG(2'd3)
   ) u_guard (
       .clk(clk),
       .rst(rst),
       .i_sym(i_ce),
       .i_in_pkt(phase == PH_PKT),
       .i_sof(do_sof),
       .i_eof(do_eof),
       .i_trunc(trunc_take),
       .i_beat(do_data),
       .i_comma(do_comma),
       .i_data(i_data),
       .o_len(pg_len),
       .o_holdoff(pg_holdoff),
       .o_trunc_req(pg_trunc_req),
       .o_sof_ok(pg_sof_ok),
       .o_trunc_cnt(o_trunc_cnt),
       .o_drop_cnt(o_drop_cnt),
       .o_runt_cnt(o_runt_cnt),
       .o_kin_cnt(o_kin_cnt),
       .o_byte_cnt(o_byte_cnt),
       .o_pkt_sum(o_pkt_sum),
       .o_last_trunc(pg_last_trunc),
       .o_last_runt(pg_last_runt)
   );

   assign o_pg_len     = pg_len;
   assign o_pg_holdoff = pg_holdoff;
   assign o_pg_status  = {pg_last_trunc, pg_last_runt, pg_trunc_req, pg_sof_ok};

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
        end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
       end else if (do_trunc) begin
           o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
           seen_end   <= 1'b1;
           phase      <= PH_ALIGN;
           o_pkt_cnt  <= o_pkt_cnt + 32'd1;
           o_sym_cnt  <= o_sym_cnt + 32'd1;
       end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));
endmodule

module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire [7:0] o_scan_pix,
   output wire o_scan_valid,
   output wire o_scan_eol,
   output wire o_scan_eof,
   output wire [7:0] o_scan_pos,
   output wire [3:0] o_pixq_level,
   output wire [3:0] o_pixq_peak,
   output wire [7:0] o_underrun,
   output wire [63:0] o_scan_frames
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

   localparam [4:0] SCAN_CFG_ADDR = 5'd24;
   localparam [3:0] PIXQ_DEPTH = 4'd8;

   reg [7:0]  pixq_data [0:7];
   reg [7:0]  pixq_eof;
   reg [2:0]  pixq_wr_ptr;
   reg [2:0]  pixq_rd_ptr;
   reg [3:0]  pixq_count;
   reg [3:0]  pixq_peak;
   reg [3:0]  scan_div;
   reg [3:0]  scan_tmr;
   reg [4:0]  scan_col;
   reg [2:0]  scan_row;
   reg [7:0]  scan_pix;
   reg        scan_valid;
   reg        scan_eol;
   reg        scan_eof;
   reg [7:0]  underrun_cnt;
   reg [63:0] scan_frames;
   integer k;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;
   initial begin
       for (i = 0; i < 8; i = i + 1)
           pixq_data[i] = 8'h00;
   end
   initial pixq_eof = 8'h00;
   initial pixq_wr_ptr = 3'd0;
   initial pixq_rd_ptr = 3'd0;
   initial pixq_count = 4'd0;
   initial pixq_peak = 4'd0;
   initial scan_div = 4'd1;
   initial scan_tmr = 4'd0;
   initial scan_col = 5'd0;
   initial scan_row = 3'd0;
   initial scan_pix = 8'h00;
   initial scan_valid = 1'b0;
   initial scan_eol = 1'b0;
   initial scan_eof = 1'b0;
   initial underrun_cnt = 8'd0;
   initial scan_frames = 64'd0;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire last_px = last_col && last_row;
   wire [7:0] gen_pix = font_row(cur_char, row_cnt[2:0]);
   wire pixq_full = (pixq_count >= PIXQ_DEPTH);
   wire pixq_empty = (pixq_count == 4'd0);
   wire gen_push = (phase == RUN) && !pixq_full;
   wire scan_tick = (scan_tmr == 4'd0);
   wire scan_pop = scan_tick && !pixq_empty;
   wire head_eof = pixq_eof[pixq_rd_ptr];
   wire [7:0] head_pix = pixq_data[pixq_rd_ptr];
   wire scan_line_end = (scan_col >= 5'd23);
   wire scan_starved = scan_tick && pixq_empty && (phase == RUN);

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
           for (k = 0; k < 8; k = k + 1)
               pixq_data[k] <= 8'h00;
           pixq_eof <= 8'h00;
           pixq_wr_ptr <= 3'd0;
           pixq_rd_ptr <= 3'd0;
           pixq_count <= 4'd0;
           pixq_peak <= 4'd0;
           scan_div <= 4'd1;
           scan_tmr <= 4'd0;
           scan_col <= 5'd0;
           scan_row <= 3'd0;
           scan_pix <= 8'h00;
           scan_valid <= 1'b0;
           scan_eol <= 1'b0;
           scan_eof <= 1'b0;
           underrun_cnt <= 8'd0;
           scan_frames <= 64'd0;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
           if (wr_en && (wr_addr == SCAN_CFG_ADDR))
               scan_div <= wr_data[3:0];
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
               pixq_eof <= 8'h00;
               pixq_wr_ptr <= 3'd0;
               pixq_rd_ptr <= 3'd0;
               pixq_count <= 4'd0;
               scan_tmr <= scan_div;
               scan_col <= 5'd0;
               scan_row <= 3'd0;
               scan_valid <= 1'b0;
               scan_eol <= 1'b0;
               scan_eof <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                        if (start_req) begin
                            phase <= RUN;
                            start_seen <= 1'b1;
                            col_cnt <= 64'd0;
                            row_cnt <= 64'd0;
                        end
                    end
                    RUN: begin
                       if (gen_push) begin
                           pix_row <= gen_pix;
                           pixq_data[pixq_wr_ptr] <= gen_pix;
                           pixq_eof[pixq_wr_ptr] <= last_px;
                           pixq_wr_ptr <= pixq_wr_ptr + 3'd1;
                           if (last_col) begin
                               col_cnt <= 64'd0;
                               if (last_row) begin
                                   row_cnt <= 64'd0;
                                   phase <= FIN;
                                   frame_cnt <= frame_cnt + 64'd1;
                               end else begin
                                   row_cnt <= row_cnt + 64'd1;
                               end
                           end else begin
                               col_cnt <= col_cnt + 64'd1;
                           end
                       end
                    end
                    FIN: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
               if (scan_pop) begin
                   scan_pix <= head_pix;
                   scan_eof <= head_eof;
                   scan_eol <= scan_line_end || head_eof;
                   pixq_rd_ptr <= pixq_rd_ptr + 3'd1;
                   if (head_eof) begin
                       scan_col <= 5'd0;
                       scan_row <= 3'd0;
                       scan_frames <= scan_frames + 64'd1;
                       done <= 1'b1;
                   end else if (scan_line_end) begin
                       scan_col <= 5'd0;
                       scan_row <= scan_row + 3'd1;
                   end else begin
                       scan_col <= scan_col + 5'd1;
                   end
               end
               scan_valid <= scan_pop;
               if (gen_push && !scan_pop)
                   pixq_count <= pixq_count + 4'd1;
               else if (scan_pop && !gen_push)
                   pixq_count <= pixq_count - 4'd1;
               if (pixq_count > pixq_peak)
                   pixq_peak <= pixq_count;
               if (scan_tick)
                   scan_tmr <= scan_div;
               else
                   scan_tmr <= scan_tmr - 4'd1;
               if (scan_starved && (underrun_cnt != 8'hFF))
                   underrun_cnt <= underrun_cnt + 8'd1;
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_scan_pix = scan_pix;
   assign o_scan_valid = scan_valid;
   assign o_scan_eol = scan_eol;
   assign o_scan_eof = scan_eof;
   assign o_scan_pos = {scan_row, scan_col};
   assign o_pixq_level = pixq_count;
   assign o_pixq_peak = pixq_peak;
   assign o_underrun = underrun_cnt;
   assign o_scan_frames = scan_frames;

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

module fm_frame_guard (
   input  wire       clk,
   input  wire       rst,
   input  wire       i_open,
   input  wire       i_close,
   input  wire       i_byte,
   input  wire [7:0] i_data,
   output reg        o_open,
   output reg        o_abort,
   output reg  [5:0] o_len,
   output reg  [7:0] o_csum,
   output reg  [7:0] o_last_csum,
   output reg  [5:0] o_last_len,
   output reg  [5:0] o_max_len,
   output reg  [7:0] o_runt_cnt,
   output reg  [7:0] o_abort_cnt,
   output reg  [7:0] o_good_cnt,
   output reg  [1:0] o_status
);
   // frames longer than LEN_FULL payload bytes are cut off with an abort,
   // frames shorter than LEN_MIN bytes are counted as runts
   localparam [5:0] LEN_FULL = 6'd63;
   localparam [5:0] LEN_MIN  = 6'd4;
   localparam [1:0] ST_NONE = 2'd0, ST_GOOD = 2'd1, ST_RUNT = 2'd2, ST_ABORT = 2'd3;

   wire       byte_ok   = i_byte && o_open && !o_abort;
   wire       overrun   = byte_ok && (o_len == LEN_FULL);
   wire       close_frm = i_close && o_open;
   wire       is_runt   = (o_len < LEN_MIN);
   wire [7:0] csum_nxt  = {o_csum[6:0], o_csum[7]} ^ i_data;
   wire       runt_sat  = (o_runt_cnt == 8'hFF);
   wire       abort_sat = (o_abort_cnt == 8'hFF);
   wire       good_sat  = (o_good_cnt == 8'hFF);

   initial begin
       o_open = 1'b0; o_abort = 1'b0; o_len = 6'd0; o_csum = 8'd0;
       o_last_csum = 8'd0; o_last_len = 6'd0; o_max_len = 6'd0;
       o_runt_cnt = 8'd0; o_abort_cnt = 8'd0; o_good_cnt = 8'd0;
       o_status = ST_NONE;
   end

   // frame window and overrun abort request
   always @(posedge clk) begin
       if (rst) begin
           o_open  <= 1'b0;
           o_abort <= 1'b0;
       end else if (close_frm) begin
           o_open  <= 1'b0;
           o_abort <= 1'b0;
       end else if (i_open) begin
           o_open  <= 1'b1;
           o_abort <= 1'b0;
       end else if (overrun) begin
           o_abort <= 1'b1;
       end
   end

   // payload length and rotating checksum of the open frame
   always @(posedge clk) begin
       if (rst) begin
           o_len  <= 6'd0;
           o_csum <= 8'd0;
       end else if (i_open && !o_open) begin
           o_len  <= 6'd0;
           o_csum <= 8'd0;
       end else if (byte_ok && !overrun) begin
           o_len  <= o_len + 6'd1;
           o_csum <= csum_nxt;
       end
   end

   // record of the most recently closed frame
   always @(posedge clk) begin
       if (rst) begin
           o_last_csum <= 8'd0;
           o_last_len  <= 6'd0;
           o_status    <= ST_NONE;
       end else if (close_frm) begin
           o_last_csum <= o_csum;
           o_last_len  <= o_len;
           if (o_abort)
               o_status <= ST_ABORT;
           else if (is_runt)
               o_status <= ST_RUNT;
           else
               o_status <= ST_GOOD;
       end
   end

   // link statistics, saturating
   always @(posedge clk) begin
       if (rst) begin
           o_max_len   <= 6'd0;
           o_runt_cnt  <= 8'd0;
           o_abort_cnt <= 8'd0;
           o_good_cnt  <= 8'd0;
       end else if (close_frm) begin
           if (o_abort) begin
               if (!abort_sat) o_abort_cnt <= o_abort_cnt + 8'd1;
           end else begin
               if (o_len > o_max_len) o_max_len <= o_len;
               if (is_runt && !runt_sat) o_runt_cnt <= o_runt_cnt + 8'd1;
               if (!is_runt && !good_sat) o_good_cnt <= o_good_cnt + 8'd1;
           end
       end
   end
endmodule

module fm_link_8b10b_framer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [7:0]  i_data,
    output reg  [9:0]  o_sym,
