);
    localparam [1:0] K_COMMA = 2'd1, K_SOF = 2'd2, K_EOF = 2'd3;
    localparam [1:0] PH_IDLE = 2'd0, PH_ALIGN = 2'd1, PH_PKT = 2'd2;

    reg [1:0] phase;
    reg seen_comma, seen_start, seen_end;
   // frame descriptor queue: each accepted SOF reserves the youngest slot,
   // the slot is completed with length, checksum and status when the frame
   // closes (EOF or abort), and completed slots are handed to the host port
   // in order on idle (clock-enable low) cycles, one every DRAIN_GAP+1 cycles
   localparam [3:0] Q_DEPTH   = 4'd8;
   localparam [1:0] DRAIN_GAP = 2'd3;
   localparam [5:0] RUNT_LEN  = 6'd4;
   localparam [1:0] ST_NONE = 2'd0, ST_GOOD = 2'd1, ST_RUNT = 2'd2, ST_ABORT = 2'd3;
   reg  [2:0] q_wr, q_rd;
   reg  [3:0] q_cnt;
   reg  [7:0] q_done;
   reg  [1:0] q_hold;
   reg  [3:0] q_seq;
   reg  [5:0] q0_len, q1_len, q2_len, q3_len, q4_len, q5_len, q6_len, q7_len;
   reg  [7:0] q0_csum, q1_csum, q2_csum, q3_csum, q4_csum, q5_csum, q6_csum, q7_csum;
   reg  [1:0] q0_stat, q1_stat, q2_stat, q3_stat, q4_stat, q5_stat, q6_stat, q7_stat;
   reg  [3:0] q0_seq, q1_seq, q2_seq, q3_seq, q4_seq, q5_seq, q6_seq, q7_seq;
   reg        q0_par, q1_par, q2_par, q3_par, q4_par, q5_par, q6_par, q7_par;
   wire       q_room = (q_cnt != Q_DEPTH);
   wire [2:0] q_tail = q_wr - 3'd1;
  // header capture store: the first HDR_LEN payload bytes of every frame
  // (destination and source station address) are kept in the frame's
  // descriptor slot together with a running XOR of the captured bytes, so a
  // corrupted header can be flagged when it is handed to the host
  localparam [3:0] HDR_LEN = 4'd12;
  reg  [3:0] q0_hcnt, q1_hcnt, q2_hcnt, q3_hcnt, q4_hcnt, q5_hcnt, q6_hcnt, q7_hcnt;
  reg  [7:0] q0_hsum, q1_hsum, q2_hsum, q3_hsum, q4_hsum, q5_hsum, q6_hsum, q7_hsum;
  reg  [7:0] q0_h0, q0_h1, q0_h2, q0_h3, q0_h4, q0_h5, q0_h6, q0_h7, q0_h8, q0_h9, q0_h10, q0_h11;
  reg  [7:0] q1_h0, q1_h1, q1_h2, q1_h3, q1_h4, q1_h5, q1_h6, q1_h7, q1_h8, q1_h9, q1_h10, q1_h11;
  reg  [7:0] q2_h0, q2_h1, q2_h2, q2_h3, q2_h4, q2_h5, q2_h6, q2_h7, q2_h8, q2_h9, q2_h10, q2_h11;
  reg  [7:0] q3_h0, q3_h1, q3_h2, q3_h3, q3_h4, q3_h5, q3_h6, q3_h7, q3_h8, q3_h9, q3_h10, q3_h11;
  reg  [7:0] q4_h0, q4_h1, q4_h2, q4_h3, q4_h4, q4_h5, q4_h6, q4_h7, q4_h8, q4_h9, q4_h10, q4_h11;
  reg  [7:0] q5_h0, q5_h1, q5_h2, q5_h3, q5_h4, q5_h5, q5_h6, q5_h7, q5_h8, q5_h9, q5_h10, q5_h11;
  reg  [7:0] q6_h0, q6_h1, q6_h2, q6_h3, q6_h4, q6_h5, q6_h6, q6_h7, q6_h8, q6_h9, q6_h10, q6_h11;
  reg  [7:0] q7_h0, q7_h1, q7_h2, q7_h3, q7_h4, q7_h5, q7_h6, q7_h7, q7_h8, q7_h9, q7_h10, q7_h11;
  // host header lane: the captured header follows its descriptor out on a
  // byte-wide lane, one byte per cycle, from a staging copy so the slot can
  // be reused while the header is still being sent
  reg  [3:0] hs_left;
  reg  [7:0] hs_b0, hs_b1, hs_b2, hs_b3, hs_b4, hs_b5, hs_b6, hs_b7, hs_b8, hs_b9, hs_b10, hs_b11;
  wire       hs_busy = (hs_left != 4'd0);
  initial begin
      q0_hcnt = 4'd0; q0_hsum = 8'd0;
      q0_h0 = 8'd0; q0_h1 = 8'd0; q0_h2 = 8'd0; q0_h3 = 8'd0; q0_h4 = 8'd0; q0_h5 = 8'd0;
      q0_h6 = 8'd0; q0_h7 = 8'd0; q0_h8 = 8'd0; q0_h9 = 8'd0; q0_h10 = 8'd0; q0_h11 = 8'd0;
      q1_hcnt = 4'd0; q1_hsum = 8'd0;
      q1_h0 = 8'd0; q1_h1 = 8'd0; q1_h2 = 8'd0; q1_h3 = 8'd0; q1_h4 = 8'd0; q1_h5 = 8'd0;
      q1_h6 = 8'd0; q1_h7 = 8'd0; q1_h8 = 8'd0; q1_h9 = 8'd0; q1_h10 = 8'd0; q1_h11 = 8'd0;
      q2_hcnt = 4'd0; q2_hsum = 8'd0;
      q2_h0 = 8'd0; q2_h1 = 8'd0; q2_h2 = 8'd0; q2_h3 = 8'd0; q2_h4 = 8'd0; q2_h5 = 8'd0;
      q2_h6 = 8'd0; q2_h7 = 8'd0; q2_h8 = 8'd0; q2_h9 = 8'd0; q2_h10 = 8'd0; q2_h11 = 8'd0;
      q3_hcnt = 4'd0; q3_hsum = 8'd0;
      q3_h0 = 8'd0; q3_h1 = 8'd0; q3_h2 = 8'd0; q3_h3 = 8'd0; q3_h4 = 8'd0; q3_h5 = 8'd0;
      q3_h6 = 8'd0; q3_h7 = 8'd0; q3_h8 = 8'd0; q3_h9 = 8'd0; q3_h10 = 8'd0; q3_h11 = 8'd0;
      q4_hcnt = 4'd0; q4_hsum = 8'd0;
      q4_h0 = 8'd0; q4_h1 = 8'd0; q4_h2 = 8'd0; q4_h3 = 8'd0; q4_h4 = 8'd0; q4_h5 = 8'd0;
      q4_h6 = 8'd0; q4_h7 = 8'd0; q4_h8 = 8'd0; q4_h9 = 8'd0; q4_h10 = 8'd0; q4_h11 = 8'd0;
      q5_hcnt = 4'd0; q5_hsum = 8'd0;
      q5_h0 = 8'd0; q5_h1 = 8'd0; q5_h2 = 8'd0; q5_h3 = 8'd0; q5_h4 = 8'd0; q5_h5 = 8'd0;
      q5_h6 = 8'd0; q5_h7 = 8'd0; q5_h8 = 8'd0; q5_h9 = 8'd0; q5_h10 = 8'd0; q5_h11 = 8'd0;
      q6_hcnt = 4'd0; q6_hsum = 8'd0;
      q6_h0 = 8'd0; q6_h1 = 8'd0; q6_h2 = 8'd0; q6_h3 = 8'd0; q6_h4 = 8'd0; q6_h5 = 8'd0;
      q6_h6 = 8'd0; q6_h7 = 8'd0; q6_h8 = 8'd0; q6_h9 = 8'd0; q6_h10 = 8'd0; q6_h11 = 8'd0;
      q7_hcnt = 4'd0; q7_hsum = 8'd0;
      q7_h0 = 8'd0; q7_h1 = 8'd0; q7_h2 = 8'd0; q7_h3 = 8'd0; q7_h4 = 8'd0; q7_h5 = 8'd0;
      q7_h6 = 8'd0; q7_h7 = 8'd0; q7_h8 = 8'd0; q7_h9 = 8'd0; q7_h10 = 8'd0; q7_h11 = 8'd0;
      hs_left = 4'd0;
      hs_b0 = 8'd0; hs_b1 = 8'd0; hs_b2 = 8'd0; hs_b3 = 8'd0; hs_b4 = 8'd0; hs_b5 = 8'd0;
      hs_b6 = 8'd0; hs_b7 = 8'd0; hs_b8 = 8'd0; hs_b9 = 8'd0; hs_b10 = 8'd0; hs_b11 = 8'd0;
      o_desc_hcnt = 4'd0; o_desc_hsum = 8'd0; o_desc_herr = 1'b0;
      o_hdr_byte = 8'd0; o_hdr_vld = 1'b0; o_hdr_last = 1'b0;
  end
   initial begin
       q_wr = 3'd0; q_rd = 3'd0; q_cnt = 4'd0; q_done = 8'd0; q_hold = 2'd0; q_seq = 4'd0;
       q0_len = 6'd0; q0_csum = 8'd0; q0_stat = ST_NONE; q0_seq = 4'd0; q0_par = 1'b0;
       q1_len = 6'd0; q1_csum = 8'd0; q1_stat = ST_NONE; q1_seq = 4'd0; q1_par = 1'b0;
       q2_len = 6'd0; q2_csum = 8'd0; q2_stat = ST_NONE; q2_seq = 4'd0; q2_par = 1'b0;
       q3_len = 6'd0; q3_csum = 8'd0; q3_stat = ST_NONE; q3_seq = 4'd0; q3_par = 1'b0;
       q4_len = 6'd0; q4_csum = 8'd0; q4_stat = ST_NONE; q4_seq = 4'd0; q4_par = 1'b0;
       q5_len = 6'd0; q5_csum = 8'd0; q5_stat = ST_NONE; q5_seq = 4'd0; q5_par = 1'b0;
       q6_len = 6'd0; q6_csum = 8'd0; q6_stat = ST_NONE; q6_seq = 4'd0; q6_par = 1'b0;
       q7_len = 6'd0; q7_csum = 8'd0; q7_stat = ST_NONE; q7_seq = 4'd0; q7_par = 1'b0;
       o_desc_valid = 1'b0; o_desc_len = 6'd0; o_desc_csum = 8'd0; o_desc_stat = ST_NONE;
       o_desc_seq = 4'd0; o_desc_perr = 1'b0; o_sof_refused = 8'd0;
   end

    initial begin
        phase = PH_IDLE; seen_comma = 1'b0; seen_start = 1'b0; seen_end = 1'b0;
        o_sym = 10'd0; o_rd = 1'b0; o_sym_cnt = 32'd0; o_pkt_cnt = 32'd0;
    end

    function [5:0] enc6;
        input [4:0] x;
        begin
            case (x)
                5'd0:  enc6 = 6'b100111;
                5'd1:  enc6 = 6'b011101;
                5'd2:  enc6 = 6'b101101;
                5'd3:  enc6 = 6'b110001;
                5'd4:  enc6 = 6'b110101;
                5'd5:  enc6 = 6'b101001;
                5'd6:  enc6 = 6'b011001;
                5'd7:  enc6 = 6'b111000;
                5'd8:  enc6 = 6'b111001;
                5'd9:  enc6 = 6'b100101;
                5'd10: enc6 = 6'b010101;
                5'd11: enc6 = 6'b110100;
                5'd12: enc6 = 6'b001101;
                5'd13: enc6 = 6'b101100;
                5'd14: enc6 = 6'b011100;
                5'd15: enc6 = 6'b010111;
                5'd16: enc6 = 6'b011011;
                5'd17: enc6 = 6'b100011;
                5'd18: enc6 = 6'b010011;
                5'd19: enc6 = 6'b110010;
                5'd20: enc6 = 6'b001011;
                5'd21: enc6 = 6'b101010;
                5'd22: enc6 = 6'b011010;
                5'd23: enc6 = 6'b111010;
                5'd24: enc6 = 6'b110011;
                5'd25: enc6 = 6'b100110;
                5'd26: enc6 = 6'b010110;
                5'd27: enc6 = 6'b110110;
                5'd28: enc6 = 6'b001110;
                5'd29: enc6 = 6'b101110;
                5'd30: enc6 = 6'b011110;
                default: enc6 = 6'b101011;
            endcase
        end
    endfunction

    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
                3'd5: enc4 = 4'b1010;
                3'd6: enc4 = 4'b0110;
                default: enc4 = 4'b1110;
            endcase
        end
    endfunction

    function [2:0] ones6;
        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
