        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
    wire do_comma = i_ce && i_k && (i_kcode == K_COMMA);
   wire sof_req  = i_ce && i_k && (i_kcode == K_SOF);
   wire do_sof   = sof_req && o_sof_ok;
    wire do_eof   = i_ce && i_k && (i_kcode == K_EOF) && (phase == PH_PKT);
    wire do_data  = i_ce && !i_k;
   // link alignment and frame admission controller
   fm_link_lock_ctl u_lock (
       .clk         (clk),
       .rst         (rst),
       .i_comma     (do_comma),
       .i_sof_req   (sof_req),
       .i_eof       (do_eof),
       .i_dsym      (do_data),
       .i_in_pkt    (phase == PH_PKT),
       .i_byte      (i_data),
       .o_sof_ok    (o_sof_ok),
       .o_locked    (o_locked),
       .o_comma_run (o_comma_run),
       .o_idle_run  (o_idle_run),
       .o_pkt_len   (o_pkt_len),
       .o_len_err   (o_len_err),
       .o_pkt_sum   (o_pkt_sum),
       .o_last_sum  (o_last_sum),
       .o_sof_rej   (o_sof_rej),
       .o_lock_loss (o_lock_loss),
       .o_status    (o_link_status)
   );

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
        end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));
endmodule

module ec_jdbl_seq (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        arm,
    input  wire        start,
    input  wire        clr,
    input  wire        sel_add,
    input  wire        wr_en,
    input  wire [3:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire        o_done,
    output wire [31:0] o_acc,
   output wire [31:0] o_x3,
   output wire [2:0]  o_jq_cnt,
   output wire [2:0]  o_jq_hwm,
   output wire        o_jq_full,
   output wire        o_jq_ovf,
   output wire [7:0]  o_jq_drop,
   output wire        o_jq_hmode,
   output wire [31:0] o_jq_hseed,
   output wire        o_jq_tmode,
   output wire [31:0] o_jq_tseed,
   output wire        o_busy,
   output wire [2:0]  o_hist_cnt,
   output wire        o_hist_hit,
   output wire [31:0] o_hist_x,
   output wire [31:0] o_hist_y,
   output wire [31:0] o_hist_z,
   output wire        o_hist_md,
   output wire        o_hist_src,
   output wire [7:0]  o_hist_tag,
   output wire [7:0]  o_hist_lag,
   output wire [31:0] o_hist_sum,
   output wire [7:0]  o_job_seq,
   output wire [7:0]  o_n_qlaunch,
   output wire [7:0]  o_n_dbl,
output wire [7:0]  o_n_add,
output wire        o_wd_trip,
output wire [15:0] o_wd_cnt,
output wire [15:0] o_wd_max,
output wire [15:0] o_q_age,
output wire [15:0] o_q_age_max,
output wire [3:0]  o_err_code,
output wire [3:0]  o_err_first,
output wire [7:0]  o_err_cnt,
output wire [7:0]  o_err_tag,
output wire [31:0] o_err_acc,
output wire [31:0] o_cyc,
output wire [31:0] o_busy_cyc,
output wire [31:0] o_idle_cyc,
output wire [15:0] o_n_wr,
output wire [15:0] o_n_mul,
output wire [15:0] o_n_aop,
output wire [15:0] o_n_sop,
output wire [7:0]  o_ign_start,
output wire [7:0]  o_n_clr,
output wire [31:0] o_sig,
output wire [31:0] o_dbg_rd,
output wire [7:0]  o_dbg_wcnt,
output wire [31:0] o_acc_min,
output wire [31:0] o_acc_max
);
    localparam [31:0] PRIME = 32'hFFFFFFFB;
    localparam [31:0] LAST  = 32'd11;
    localparam [1:0]  OP_MUL = 2'd0;
    localparam [1:0]  OP_ADD = 2'd1;
    localparam [1:0]  OP_SUB = 2'd2;

    reg        armed;
    reg        started;
    reg        done;
    reg        pre_clr;
    reg        mode;
    reg [31:0] step;
    reg [31:0] acc;
    reg [31:0] rf [0:15];
   localparam [2:0]  JQ_DEPTH = 3'd4;
   reg        jq_mode [0:3];
   reg        jq_ld   [0:3];
   reg [31:0] jq_seed [0:3];
   reg [1:0]  jq_wp;
   reg [1:0]  jq_rp;
   reg [2:0]  jq_cnt;
   reg [2:0]  jq_hwm;
   reg        jq_ovf;
   reg [7:0]  jq_drop;
   reg [7:0]  n_qlaunch;
   reg [31:0] hist_x   [0:3];
   reg [31:0] hist_y   [0:3];
   reg [31:0] hist_z   [0:3];
   reg        hist_md  [0:3];
   reg        hist_src [0:3];
   reg [7:0]  hist_tag [0:3];
   reg [1:0]  hist_wp;
   reg        hist_wrap;
   reg [31:0] hist_sum;
   reg [7:0]  job_seq;
   reg        job_src;
   reg [7:0]  n_dbl;
   reg [7:0]  n_add;
  localparam [15:0] WD_LIMIT = 16'd12;
  localparam [15:0] QA_LIMIT = 16'd48;
  localparam [31:0] SIG_POLY = 32'h04C11DB7;
  reg [15:0] wd_cnt;
  reg [15:0] wd_max;
  reg        wd_trip;
  reg [15:0] q_age;
  reg [15:0] q_age_max;
  reg [3:0]  err_code;
  reg [3:0]  err_first;
  reg        err_seen;
  reg [7:0]  err_cnt;
  reg [7:0]  err_tag;
  reg [31:0] err_acc;
  reg [31:0] cyc;
  reg [31:0] busy_cyc;
  reg [31:0] idle_cyc;
  reg [15:0] n_wr;
  reg [15:0] n_mul;
  reg [15:0] n_aop;
  reg [15:0] n_sop;
  reg [7:0]  ign_start;
  reg [7:0]  n_clr;
  reg [31:0] sig;
  reg [31:0] dbg_bank [0:3];
  reg [7:0]  dbg_wcnt;
  reg [31:0] acc_min;
  reg [31:0] acc_max;
  reg        acc_seen;

    integer i;
   integer k;
    initial begin
        armed   = 1'b0;
        started = 1'b0;
        done    = 1'b0;
        pre_clr = 1'b1;
        mode    = 1'b0;
        step    = 32'd0;
        acc     = 32'd0;
        for (i = 0; i < 16; i = i + 1)
            rf[i] = 32'd0;
       jq_wp     = 2'd0;
       jq_rp     = 2'd0;
       jq_cnt    = 3'd0;
       jq_hwm    = 3'd0;
       jq_ovf    = 1'b0;
       jq_drop   = 8'd0;
       n_qlaunch = 8'd0;
       hist_wp   = 2'd0;
       hist_wrap = 1'b0;
       hist_sum  = 32'd0;
       job_seq   = 8'd0;
       job_src   = 1'b0;
       n_dbl     = 8'd0;
       n_add     = 8'd0;
      wd_cnt    = 16'd0;
      wd_max    = 16'd0;
      wd_trip   = 1'b0;
      q_age     = 16'd0;
      q_age_max = 16'd0;
      err_code  = 4'd0;
      err_first = 4'd0;
      err_seen  = 1'b0;
      err_cnt   = 8'd0;
      err_tag   = 8'd0;
      err_acc   = 32'd0;
      cyc       = 32'd0;
      busy_cyc  = 32'd0;
      idle_cyc  = 32'd0;
      n_wr      = 16'd0;
      n_mul     = 16'd0;
      n_aop     = 16'd0;
      n_sop     = 16'd0;
      ign_start = 8'd0;
      n_clr     = 8'd0;
      sig       = 32'hFFFFFFFF;
      dbg_wcnt  = 8'd0;
      acc_min   = 32'd0;
      acc_max   = 32'd0;
      acc_seen  = 1'b0;
      for (i = 0; i < 4; i = i + 1)
          dbg_bank[i] = 32'd0;
       for (i = 0; i < 4; i = i + 1) begin
           jq_mode[i]  = 1'b0;
           jq_ld[i]    = 1'b0;
           jq_seed[i]  = 32'd0;
           hist_x[i]   = 32'd0;
           hist_y[i]   = 32'd0;
           hist_z[i]   = 32'd0;
           hist_md[i]  = 1'b0;
           hist_src[i] = 1'b0;
           hist_tag[i] = 8'd0;
       end
    end

    function [31:0] fadd;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            s = {1'b0, a} + {1'b0, b};
            if (s >= {1'b0, PRIME})
                s = s - {1'b0, PRIME};
            fadd = s[31:0];
        end
    endfunction

    function [31:0] fsub;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            if (a >= b)
                s = {1'b0, a} - {1'b0, b};
            else
                s = {1'b0, a} + {1'b0, PRIME} - {1'b0, b};
            fsub = s[31:0];
        end
    endfunction

    function [31:0] fmul;
        input [31:0] a;
        input [31:0] b;
        reg [63:0] p;
        reg [35:0] t;
        reg [35:0] u;
        begin
            p = {32'd0, a} * {32'd0, b};
            t = {4'd0, p[31:0]} + {4'd0, p[63:32]} * 36'd5;
            u = {4'd0, t[31:0]} + {32'd0, t[35:32]} * 36'd5;
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            fmul = u[31:0];
        end
    endfunction

    reg [3:0] ra, rb, rd;
    reg [1:0] opc;
    always @(*) begin
        ra  = 4'd0;
        rb  = 4'd0;
        rd  = 4'd6;
        opc = OP_MUL;
        case (step)
            32'd1:  begin ra = 4'd1;  rb = mode ? 4'd4 : 4'd1; rd = 4'd6;  opc = OP_MUL; end
            32'd2:  begin ra = 4'd0;  rb = 4'd6;  rd = 4'd7;  opc = OP_MUL; end
            32'd3:  begin ra = 4'd0;  rb = mode ? 4'd3 : 4'd0; rd = 4'd8;  opc = OP_MUL; end
            32'd4:  begin ra = 4'd8;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd5:  begin ra = 4'd9;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd6:  begin ra = 4'd9;  rb = 4'd9;  rd = 4'd10; opc = OP_MUL; end
            32'd7:  begin ra = 4'd7;  rb = 4'd7;  rd = 4'd11; opc = OP_ADD; end
            32'd8:  begin ra = 4'd10; rb = 4'd11; rd = 4'd12; opc = OP_SUB; end
            32'd9:  begin ra = mode ? 4'd2 : 4'd1; rb = mode ? 4'd5 : 4'd2; rd = 4'd13; opc = OP_MUL; end
            32'd10: begin ra = 4'd6;  rb = 4'd6;  rd = 4'd15; opc = OP_MUL; end
            default: begin ra = 4'd0; rb = 4'd0; rd = 4'd6; opc = OP_MUL; end
        endcase
    end

    wire [31:0] opa = rf[ra];
    wire [31:0] opb = rf[rb];
    reg  [31:0] res;
    always @(*) begin
        case (opc)
            OP_MUL:  res = fmul(opa, opb);
            OP_ADD:  res = fadd(opa, opb);
            OP_SUB:  res = fsub(opa, opb);
            default: res = opa;
        endcase
    end

    wire [31:0] y3 = fsub(fmul(rf[9], fsub(rf[7], rf[12])), rf[15]);
    wire [31:0] z3 = fadd(rf[13], rf[13]);
   wire        idle       = (step == 32'd0);
   wire        jq_empty   = (jq_cnt == 3'd0);
   wire        jq_full    = (jq_cnt == JQ_DEPTH);
   wire        req_ok     = start && armed && !clr;
   wire        q_launch   = en && idle && !clr && !jq_empty;
   wire        d_launch   = en && idle && req_ok && jq_empty;
   wire        job_launch = q_launch || d_launch;
   wire        req_queue  = en && req_ok && (!idle || !jq_empty);
   wire        jq_pop     = q_launch;
   wire        jq_push    = req_queue && (!jq_full || jq_pop);
   wire        jq_reject  = req_queue && jq_full && !jq_pop;
   wire [2:0]  jq_nxt_cnt = jq_cnt + {2'd0, jq_push} - {2'd0, jq_pop};
   wire [1:0]  jq_tail    = jq_wp - 2'd1;
   wire        hd_mode    = jq_mode[jq_rp];
   wire        hd_ld      = jq_ld[jq_rp];
   wire [31:0] hd_seed    = jq_seed[jq_rp];
   wire        nxt_mode   = q_launch ? hd_mode : sel_add;
   wire        job_end    = en && (step == LAST);
   wire [31:0] hist_nsum  = fadd(hist_sum, y3);
   wire [1:0]  hist_ra    = hist_wp - 2'd1 - wr_addr[1:0];
   wire [2:0]  hist_cnt   = hist_wrap ? 3'd4 : {1'b0, hist_wp};
   wire        hist_hit   = ({1'b0, wr_addr[1:0]} < hist_cnt);
  wire        dbg_wr     = en && wr_en && !idle;
  wire [1:0]  dbg_wa     = wr_addr[1:0];
  wire [1:0]  dbg_ra     = wr_addr[3:2];
  wire        wd_active  = !idle;
  wire        wd_over    = (wd_cnt >= WD_LIMIT);
  wire        ev_reject  = jq_reject;
  wire        ev_ign     = en && start && !clr && !armed;
  wire        ev_clrbusy = en && clr && (!idle || !jq_empty);
  wire        ev_rearm   = en && arm && armed && !clr;
  wire        ev_wd      = en && wd_over && !wd_trip;
  wire        ev_qa      = en && (q_age == QA_LIMIT);
  wire        ev_any     = ev_reject || ev_ign || ev_clrbusy ||
                           ev_rearm || ev_wd || ev_qa;
  wire [3:0]  ev_code    = ev_wd      ? 4'd5 :
                           ev_qa      ? 4'd6 :
                           ev_reject  ? 4'd1 :
                           ev_clrbusy ? 4'd2 :
                           ev_ign     ? 4'd3 :
                           ev_rearm   ? 4'd4 : 4'd0;
  wire [31:0] sig_sh     = {sig[30:0], 1'b0} ^ (sig[31] ? SIG_POLY : 32'd0);
  wire [31:0] sig_nxt    = sig_sh ^ y3 ^ {24'd0, job_seq};
  wire        op_live    = !idle && (step != LAST);
  wire        new_min    = !acc_seen || (y3 < acc_min);
  wire        new_max    = !acc_seen || (y3 > acc_max);

    always @(posedge clk) begin
        if (rst) begin
            armed   <= 1'b0;
            started <= 1'b0;
            done    <= 1'b0;
            pre_clr <= 1'b1;
            mode    <= 1'b0;
            step    <= 32'd0;
            acc     <= 32'd0;
           jq_wp     <= 2'd0;
           jq_rp     <= 2'd0;
           jq_cnt    <= 3'd0;
           jq_hwm    <= 3'd0;
           jq_ovf    <= 1'b0;
           jq_drop   <= 8'd0;
           n_qlaunch <= 8'd0;
           hist_wp   <= 2'd0;
           hist_wrap <= 1'b0;
           hist_sum  <= 32'd0;
           job_seq   <= 8'd0;
           job_src   <= 1'b0;
           n_dbl     <= 8'd0;
           n_add     <= 8'd0;
          wd_cnt    <= 16'd0;
          wd_max    <= 16'd0;
          wd_trip   <= 1'b0;
          q_age     <= 16'd0;
          q_age_max <= 16'd0;
          err_code  <= 4'd0;
          err_first <= 4'd0;
          err_seen  <= 1'b0;
          err_cnt   <= 8'd0;
          err_tag   <= 8'd0;
          err_acc   <= 32'd0;
          cyc       <= 32'd0;
          busy_cyc  <= 32'd0;
          idle_cyc  <= 32'd0;
          n_wr      <= 16'd0;
          n_mul     <= 16'd0;
          n_aop     <= 16'd0;
          n_sop     <= 16'd0;
          ign_start <= 8'd0;
          n_clr     <= 8'd0;
          sig       <= 32'hFFFFFFFF;
          dbg_wcnt  <= 8'd0;
          acc_min   <= 32'd0;
          acc_max   <= 32'd0;
          acc_seen  <= 1'b0;
          for (k = 0; k < 4; k = k + 1)
              dbg_bank[k] <= 32'd0;
           for (k = 0; k < 4; k = k + 1) begin
               jq_mode[k]  <= 1'b0;
               jq_ld[k]    <= 1'b0;
               jq_seed[k]  <= 32'd0;
               hist_x[k]   <= 32'd0;
               hist_y[k]   <= 32'd0;
               hist_z[k]   <= 32'd0;
               hist_md[k]  <= 1'b0;
               hist_src[k] <= 1'b0;
               hist_tag[k] <= 8'd0;
           end
        end else if (en) begin
            if (clr) begin
                armed   <= 1'b0;
                started <= 1'b0;
                done    <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (arm)
                    armed <= 1'b1;
               if (job_launch)
                    started <= 1'b1;
                if (step == LAST)
                    done <= 1'b1;
            end
            if (step == 32'd0) begin
               if (job_launch) begin
                    step <= 32'd1;
                   mode    <= nxt_mode;
                   job_seq <= job_seq + 8'd1;
                   job_src <= q_launch;
                end
            end else if (step == LAST) begin
                step <= 32'd0;
                acc  <= y3;
            end else begin
                step <= step + 32'd1;
                acc  <= res;
            end
           if (clr) begin
               jq_wp  <= 2'd0;
               jq_rp  <= 2'd0;
               jq_cnt <= 3'd0;
               jq_ovf <= 1'b0;
           end else begin
               if (jq_push) begin
                   jq_mode[jq_wp] <= sel_add;
                   jq_ld[jq_wp]   <= wr_en;
                   jq_seed[jq_wp] <= wr_data;
                   jq_wp          <= jq_wp + 2'd1;
               end
               if (jq_pop) begin
                   jq_rp     <= jq_rp + 2'd1;
                   n_qlaunch <= n_qlaunch + 8'd1;
               end
               jq_cnt <= jq_nxt_cnt;
               if (jq_reject) begin
                   jq_ovf <= 1'b1;
                   if (jq_drop != 8'hFF)
                       jq_drop <= jq_drop + 8'd1;
               end
           end
           if (jq_cnt > jq_hwm)
               jq_hwm <= jq_cnt;
           if (job_end) begin
               hist_x[hist_wp]   <= rf[12];
               hist_y[hist_wp]   <= y3;
               hist_z[hist_wp]   <= z3;
               hist_md[hist_wp]  <= mode;
               hist_src[hist_wp] <= job_src;
               hist_tag[hist_wp] <= job_seq;
               hist_wp           <= hist_wp + 2'd1;
               if (hist_wp == 2'd3)
                   hist_wrap <= 1'b1;
               hist_sum <= hist_nsum;
               if (mode)
                   n_add <= n_add + 8'd1;
               else
                   n_dbl <= n_dbl + 8'd1;
           end
          cyc <= cyc + 32'd1;
          if (idle && jq_empty)
              idle_cyc <= idle_cyc + 32'd1;
          else
              busy_cyc <= busy_cyc + 32'd1;
          if (wd_active && !job_end) begin
              if (wd_cnt != 16'hFFFF)
                  wd_cnt <= wd_cnt + 16'd1;
          end else begin
              wd_cnt <= 16'd0;
          end
          if (wd_cnt > wd_max)
              wd_max <= wd_cnt;
          if (wd_over)
              wd_trip <= 1'b1;
          if (jq_empty || jq_pop || clr)
              q_age <= 16'd0;
          else if (q_age != 16'hFFFF)
              q_age <= q_age + 16'd1;
          if (q_age > q_age_max)
              q_age_max <= q_age;
          if (ev_any) begin
              err_code <= ev_code;
              err_tag  <= job_seq;
              err_acc  <= acc;
              if (!err_seen) begin
                  err_seen  <= 1'b1;
                  err_first <= ev_code;
              end
              if (err_cnt != 8'hFF)
                  err_cnt <= err_cnt + 8'd1;
          end
          if (op_live) begin
              case (opc)
                  OP_MUL: n_mul <= n_mul + 16'd1;
                  OP_ADD: n_aop <= n_aop + 16'd1;
                  OP_SUB: n_sop <= n_sop + 16'd1;
                  default: begin end
              endcase
          end
          if (wr_en && idle)
              n_wr <= n_wr + 16'd1;
          if (ev_ign && (ign_start != 8'hFF))
              ign_start <= ign_start + 8'd1;
          if (clr && (n_clr != 8'hFF))
              n_clr <= n_clr + 8'd1;
          if (job_end) begin
              sig      <= sig_nxt;
              acc_seen <= 1'b1;
              if (new_min)
                  acc_min <= y3;
              if (new_max)
                  acc_max <= y3;
          end
          if (dbg_wr) begin
              dbg_bank[dbg_wa] <= wr_data;
              dbg_wcnt         <= dbg_wcnt + 8'd1;
          end
        end
    end

    always @(posedge clk) begin
        if (!rst && en) begin
            if (step == 32'd0) begin
                if (wr_en)
                    rf[wr_addr] <= wr_data;
               if (q_launch && hd_ld)
                   rf[0] <= hd_seed;
            end else if (step == LAST) begin
                rf[0] <= rf[12];
                rf[1] <= y3;
                rf[2] <= z3;
            end else begin
                rf[rd] <= res;
            end
        end
    end

    assign o_done = done;
    assign o_acc  = acc;
    assign o_x3   = rf[0];
   assign o_jq_cnt    = jq_cnt;
   assign o_jq_hwm    = jq_hwm;
   assign o_jq_full   = jq_full;
   assign o_jq_ovf    = jq_ovf;
   assign o_jq_drop   = jq_drop;
   assign o_jq_hmode  = jq_empty ? 1'b0 : hd_mode;
   assign o_jq_hseed  = (jq_empty || !hd_ld) ? 32'd0 : hd_seed;
   assign o_jq_tmode  = jq_empty ? 1'b0 : jq_mode[jq_tail];
   assign o_jq_tseed  = (jq_empty || !jq_ld[jq_tail]) ? 32'd0 : jq_seed[jq_tail];
   assign o_busy      = !idle || !jq_empty;
   assign o_hist_cnt  = hist_cnt;
   assign o_hist_hit  = hist_hit;
   assign o_hist_x    = hist_hit ? hist_x[hist_ra]   : 32'd0;
   assign o_hist_y    = hist_hit ? hist_y[hist_ra]   : 32'd0;
   assign o_hist_z    = hist_hit ? hist_z[hist_ra]   : 32'd0;
   assign o_hist_md   = hist_hit ? hist_md[hist_ra]  : 1'b0;
   assign o_hist_src  = hist_hit ? hist_src[hist_ra] : 1'b0;
   assign o_hist_tag  = hist_hit ? hist_tag[hist_ra] : 8'd0;
   assign o_hist_lag  = hist_hit ? (job_seq - hist_tag[hist_ra]) : 8'd0;
   assign o_hist_sum  = hist_sum;
   assign o_job_seq   = job_seq;
   assign o_n_qlaunch = n_qlaunch;
   assign o_n_dbl     = n_dbl;
   assign o_n_add     = n_add;
  assign o_wd_trip   = wd_trip;
  assign o_wd_cnt    = wd_cnt;
  assign o_wd_max    = wd_max;
  assign o_q_age     = q_age;
  assign o_q_age_max = q_age_max;
  assign o_err_code  = err_code;
  assign o_err_first = err_first;
  assign o_err_cnt   = err_cnt;
  assign o_err_tag   = err_tag;
  assign o_err_acc   = err_acc;
  assign o_cyc       = cyc;
  assign o_busy_cyc  = busy_cyc;
  assign o_idle_cyc  = idle_cyc;
  assign o_n_wr      = n_wr;
  assign o_n_mul     = n_mul;
  assign o_n_aop     = n_aop;
  assign o_n_sop     = n_sop;
  assign o_ign_start = ign_start;
  assign o_n_clr     = n_clr;
  assign o_sig       = sig;
  assign o_dbg_rd    = dbg_bank[dbg_ra];
  assign o_dbg_wcnt  = dbg_wcnt;
  assign o_acc_min   = acc_min;
  assign o_acc_max   = acc_max;

    always @(*)
        if (pre_clr && done)
            assert (started && armed);
endmodule

module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire [63:0] o_hist_stamp,
   output wire [15:0] o_hist_sig,
   output wire [1:0] o_hist_state,
   output wire [2:0] o_hist_level,
   output wire o_hist_open,
   output wire [15:0] o_last_sig,
   output wire [7:0] o_hist_drops,
   output wire [7:0] o_abort_cnt,
   output wire [63:0] o_ret_stamp,
   output wire [15:0] o_ret_sig,
   output wire [1:0] o_ret_state,
  output wire o_ret_valid,
  output wire [15:0] o_cap_sig,
  output wire [7:0] o_cap_ink,
  output wire [63:0] o_cap_tag,
  output wire o_cap_hit,
  output wire [3:0] o_cap_fill,
  output wire o_cap_cut,
  output wire [2:0] o_cap_cut_row,
  output wire [7:0] o_cap_chg,
  output wire [7:0] o_cap_chg_prev,
  output wire [3:0] o_cap_nchg,
  output wire o_cap_static,
  output wire [15:0] o_ref_sig,
  output wire o_ref_valid,
  output wire [2:0] o_cap_ctl,
  output wire [7:0] o_cap_wait,
  output wire o_cap_stb,
  output wire [2:0] o_cap_row,
  output wire [15:0] o_line_sig,
  output wire [7:0] o_line_ink,
  output wire [7:0] o_frame_ink,
  output wire [23:0] o_col_ink,
  output wire [4:0] o_ink_left,
  output wire [4:0] o_ink_right,
  output wire [2:0] o_ext_top,
  output wire [2:0] o_ext_bot,
  output wire o_ext_valid
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;
   localparam [1:0] ST_FREE = 2'd0, ST_OPEN = 2'd1, ST_DONE = 2'd2, ST_ABRT = 2'd3;
   localparam [4:0] HIST_CLR = 5'd30, HIST_ACK = 5'd31;
   localparam [2:0] HIST_DEPTH = 3'd4;
   // frame history: one record per launched frame, oldest at hist_rd_ptr
   reg [63:0] hist_mem [0:3];
   reg [15:0] hist_sum [0:3];
   reg [1:0]  hist_st  [0:3];
   reg [1:0]  hist_wr_ptr;
   reg [1:0]  hist_rd_ptr;
   reg [2:0]  hist_cnt;
   reg [7:0]  hist_drop;
   reg [7:0]  abort_cnt;
   reg [15:0] frame_sig;
   // last record retired through HIST_ACK
   reg [63:0] ret_stamp;
   reg [15:0] ret_sum;
   reg [1:0]  ret_st;
   reg        ret_vld;
   integer j;
  // ---- scanline capture ----
  // Every scanline of a launched frame leaves a record in the row table:
  // its signature, the OR of its pixel bytes and the stamp of the frame it
  // belongs to. The host reads records back through CAP_SEL and can hold
  // off the next launch with the capture lock until it has read them.
  localparam [4:0] CAP_SEL = 5'd24, CAP_CTL = 5'd25;
  localparam [3:0] CAP_ROWS = 4'd8;
  reg [15:0] row_sig [0:7];
  reg [7:0]  row_ink [0:7];
  reg [63:0] row_tag [0:7];
  // reference signatures (last completed frame, or a held golden frame)
  reg [15:0] ref_sig [0:7];
  reg        ref_vld;
  reg        ref_hold;
  reg [7:0]  row_chg;
  reg [7:0]  chg_prev;
  reg [3:0]  row_fill;
  reg [15:0] line_sig;
  reg [7:0]  line_ink;
  reg        cap_cut;
  reg [2:0]  cap_cut_row;
  reg [2:0]  cap_sel;
  reg        cap_lock;
  reg        cap_auto;
  reg [7:0]  cap_wait;
  reg        cap_stb;
  reg [2:0]  cap_row_idx;
  // ink extent of the frame being drawn
  reg [23:0] col_ink;
  reg [2:0]  ext_top;
  reg [2:0]  ext_bot;
  reg        ext_vld;
  integer k;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;
   initial begin
       for (j = 0; j < 4; j = j + 1) begin
           hist_mem[j] = 64'd0;
           hist_sum[j] = 16'd0;
           hist_st[j] = ST_FREE;
       end
   end
   initial hist_wr_ptr = 2'd0;
   initial hist_rd_ptr = 2'd0;
   initial hist_cnt = 3'd0;
   initial hist_drop = 8'd0;
   initial abort_cnt = 8'd0;
   initial frame_sig = 16'd0;
   initial ret_stamp = 64'd0;
   initial ret_sum = 16'd0;
   initial ret_st = ST_FREE;
   initial ret_vld = 1'b0;
  initial begin
      for (k = 0; k < 8; k = k + 1) begin
          row_sig[k] = 16'd0;
          row_ink[k] = 8'h00;
          row_tag[k] = 64'd0;
          ref_sig[k] = 16'd0;
      end
  end
  initial ref_vld = 1'b0;
  initial ref_hold = 1'b0;
  initial row_chg = 8'h00;
  initial chg_prev = 8'h00;
  initial row_fill = 4'd0;
  initial line_sig = 16'd0;
  initial line_ink = 8'h00;
  initial cap_cut = 1'b0;
  initial cap_cut_row = 3'd0;
  initial cap_sel = 3'd0;
  initial cap_lock = 1'b0;
  initial cap_auto = 1'b0;
  initial cap_wait = 8'd0;
  initial cap_stb = 1'b0;
  initial cap_row_idx = 3'd0;
  initial col_ink = 24'd0;
  initial ext_top = 3'd0;
  initial ext_bot = 3'd0;
  initial ext_vld = 1'b0;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire [1:0]  hist_last  = hist_wr_ptr - 2'd1;
   wire        hist_empty = (hist_cnt == 3'd0);
   wire        hist_full  = (hist_cnt == HIST_DEPTH);
   // a new record is opened whenever a frame is launched
  // (a launch waits while the host holds the capture table locked)
  wire        hist_push  = !abort_req && (phase == ARMED) && start_req && !cap_lock;
   // the record of the frame on screen (running or just finished) may not be acked away
   wire        hist_pin   = (hist_cnt == 3'd1) && ((phase == RUN) || done);
   wire        hist_ack   = wr_en && (wr_addr == HIST_ACK) && !hist_empty && !hist_push && !hist_pin;
   wire        hist_clr   = wr_en && (wr_addr == HIST_CLR) && (phase != RUN) && !done && !hist_push;
   wire        frame_end  = !abort_req && (phase == RUN) && last_col && last_row;
   wire        frame_kill = abort_req && (phase == RUN);
   wire [7:0]  next_pix   = font_row(cur_char, row_cnt[2:0]);
   wire [15:0] next_sig   = {frame_sig[14:0], frame_sig[15] ^ frame_sig[12]} ^ {frame_sig[3:0], 4'h0, next_pix};
  // ---- scanline capture ----
  function [4:0] lead_col;
      input [23:0] m;
      integer n;
      begin
          lead_col = 5'd31;
          for (n = 23; n >= 0; n = n - 1)
              if (m[n])
                  lead_col = n;
      end
  endfunction
  function [4:0] trail_col;
      input [23:0] m;
      integer n;
      begin
          trail_col = 5'd31;
          for (n = 0; n < 24; n = n + 1)
              if (m[n])
                  trail_col = n;
      end
  endfunction
  wire        cap_wr_sel  = wr_en && (wr_addr == CAP_SEL);
  wire        cap_wr_ctl  = wr_en && (wr_addr == CAP_CTL);
  // a pixel of a running frame is being drawn this cycle
  wire        cap_pixel   = !abort_req && (phase == RUN);
  // a scanline is complete on the last column of every row
  wire        cap_line    = cap_pixel && last_col;
  // a launch request that the capture lock is holding back
  wire        cap_held    = !abort_req && (phase == ARMED) && start_req && cap_lock;
  wire [2:0]  cap_row     = row_cnt[2:0];
  wire [7:0]  cap_bit     = 8'd1 << cap_row;
  wire [23:0] col_bit     = (next_pix != 8'h00) ? (24'd1 << col_cnt[4:0]) : 24'd0;
  wire [15:0] line_sig_nx = {line_sig[14:0], line_sig[15] ^ line_sig[13]} ^ {8'h00, next_pix};
  wire [7:0]  line_ink_nx = line_ink | next_pix;
  wire        line_blank  = (line_ink_nx == 8'h00);
  // a scanline that differs from the reference (everything differs without one)
  wire        line_diff   = !ref_vld || (line_sig_nx != ref_sig[cap_row]);
  wire [7:0]  chg_line    = line_diff ? (row_chg | cap_bit) : row_chg;
  wire        ref_take    = frame_end && (!ref_hold || !ref_vld);
  wire        cap_hit     = ({1'b0, cap_sel} < row_fill) || (cap_cut && (cap_sel == cap_cut_row));
  wire [3:0]  nchg        = {3'd0, chg_prev[0]} + {3'd0, chg_prev[1]}
                          + {3'd0, chg_prev[2]} + {3'd0, chg_prev[3]}
                          + {3'd0, chg_prev[4]} + {3'd0, chg_prev[5]}
                          + {3'd0, chg_prev[6]} + {3'd0, chg_prev[7]};
  wire [7:0]  frame_ink   = ((row_fill > 4'd0) ? row_ink[0] : 8'h00)
                          | ((row_fill > 4'd1) ? row_ink[1] : 8'h00)
                          | ((row_fill > 4'd2) ? row_ink[2] : 8'h00)
                          | ((row_fill > 4'd3) ? row_ink[3] : 8'h00)
                          | ((row_fill > 4'd4) ? row_ink[4] : 8'h00)
                          | ((row_fill > 4'd5) ? row_ink[5] : 8'h00)
                          | ((row_fill > 4'd6) ? row_ink[6] : 8'h00)
                          | ((row_fill > 4'd7) ? row_ink[7] : 8'h00);
  wire [4:0]  ink_left    = lead_col(col_ink);
  wire [4:0]  ink_right   = trail_col(col_ink);

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
           for (j = 0; j < 4; j = j + 1) begin
               hist_mem[j] <= 64'd0;
               hist_sum[j] <= 16'd0;
               hist_st[j] <= ST_FREE;
           end
           hist_wr_ptr <= 2'd0;
           hist_rd_ptr <= 2'd0;
           hist_cnt <= 3'd0;
           hist_drop <= 8'd0;
           abort_cnt <= 8'd0;
           frame_sig <= 16'd0;
           ret_stamp <= 64'd0;
           ret_sum <= 16'd0;
           ret_st <= ST_FREE;
           ret_vld <= 1'b0;
          for (k = 0; k < 8; k = k + 1) begin
              row_sig[k] <= 16'd0;
              row_ink[k] <= 8'h00;
              row_tag[k] <= 64'd0;
              ref_sig[k] <= 16'd0;
          end
          ref_vld <= 1'b0;
          ref_hold <= 1'b0;
          row_chg <= 8'h00;
          chg_prev <= 8'h00;
          row_fill <= 4'd0;
          line_sig <= 16'd0;
          line_ink <= 8'h00;
          cap_cut <= 1'b0;
          cap_cut_row <= 3'd0;
          cap_sel <= 3'd0;
          cap_lock <= 1'b0;
          cap_auto <= 1'b0;
          cap_wait <= 8'd0;
          cap_stb <= 1'b0;
          cap_row_idx <= 3'd0;
          col_ink <= 24'd0;
          ext_top <= 3'd0;
          ext_bot <= 3'd0;
          ext_vld <= 1'b0;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                       if (start_req && !cap_lock) begin
                            phase <= RUN;
                            start_seen <= 1'b1;
                            col_cnt <= 64'd0;
                            row_cnt <= 64'd0;
                        end
                    end
                    RUN: begin
                        pix_row <= font_row(cur_char, row_cnt[2:0]);
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                done <= 1'b1;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                    end
                    FIN: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
            end
           // ---- frame history ----
           if (hist_push)
               frame_sig <= 16'd0;
           else if (!abort_req && (phase == RUN))
               frame_sig <= next_sig;
           if (hist_push) begin
               hist_mem[hist_wr_ptr] <= frame_cnt + 64'd1;
               hist_sum[hist_wr_ptr] <= 16'd0;
               hist_st[hist_wr_ptr] <= ST_OPEN;
               hist_wr_ptr <= hist_wr_ptr + 2'd1;
               if (hist_full) begin
                   // overwrite the oldest record and account for the loss
                   hist_rd_ptr <= hist_rd_ptr + 2'd1;
                   if (hist_drop != 8'hFF)
                       hist_drop <= hist_drop + 8'd1;
               end else begin
                   hist_cnt <= hist_cnt + 3'd1;
               end
           end else if (hist_ack) begin
               ret_stamp <= hist_mem[hist_rd_ptr];
               ret_sum <= hist_sum[hist_rd_ptr];
               ret_st <= hist_st[hist_rd_ptr];
               ret_vld <= 1'b1;
               hist_st[hist_rd_ptr] <= ST_FREE;
               hist_rd_ptr <= hist_rd_ptr + 2'd1;
               hist_cnt <= hist_cnt - 3'd1;
           end else if (hist_clr) begin
               for (j = 0; j < 4; j = j + 1)
                   hist_st[j] <= ST_FREE;
               hist_rd_ptr <= hist_wr_ptr;
               hist_cnt <= 3'd0;
               ret_vld <= 1'b0;
           end
           if (frame_kill) begin
               hist_st[hist_last] <= ST_ABRT;
               hist_sum[hist_last] <= frame_sig;
               if (abort_cnt != 8'hFF)
                   abort_cnt <= abort_cnt + 8'd1;
           end
           if (frame_end) begin
               hist_st[hist_last] <= ST_DONE;
               hist_sum[hist_last] <= next_sig;
           end
          // ---- scanline capture ----
          if (cap_wr_sel) begin
              if (wr_data[3])
                  cap_sel <= cap_sel + 3'd1;
              else
                  cap_sel <= wr_data[2:0];
          end
          if (cap_wr_ctl) begin
              cap_auto <= wr_data[1];
              ref_hold <= wr_data[3];
          end
          // auto mode locks the table as soon as a frame completes
          if (frame_end && cap_auto)
              cap_lock <= 1'b1;
          else if (cap_wr_ctl)
              cap_lock <= wr_data[0];
          if (cap_wr_ctl && wr_data[4])
              cap_wait <= 8'd0;
          else if (cap_held && (cap_wait != 8'hFF))
              cap_wait <= cap_wait + 8'd1;
          cap_stb <= cap_line || frame_kill;
          if (hist_push) begin
              row_fill <= 4'd0;
              row_chg <= 8'h00;
              line_sig <= 16'd0;
              line_ink <= 8'h00;
              cap_cut <= 1'b0;
              col_ink <= 24'd0;
              ext_vld <= 1'b0;
          end else if (cap_line) begin
              row_sig[cap_row] <= line_sig_nx;
              row_ink[cap_row] <= line_ink_nx;
              row_tag[cap_row] <= frame_cnt + 64'd1;
              row_fill <= row_fill + 4'd1;
              row_chg <= chg_line;
              cap_row_idx <= cap_row;
              col_ink <= col_ink | col_bit;
              line_sig <= 16'd0;
              line_ink <= 8'h00;
              if (!line_blank) begin
                  if (!ext_vld)
                      ext_top <= cap_row;
                  ext_bot <= cap_row;
                  ext_vld <= 1'b1;
              end
          end else if (cap_pixel) begin
              line_sig <= line_sig_nx;
              line_ink <= line_ink_nx;
              col_ink <= col_ink | col_bit;
          end else if (frame_kill) begin
              // keep the partial scanline so the host sees where the frame stopped
              row_sig[cap_row] <= line_sig;
              row_ink[cap_row] <= line_ink;
              row_tag[cap_row] <= frame_cnt + 64'd1;
              cap_cut <= 1'b1;
              cap_cut_row <= cap_row;
              cap_row_idx <= cap_row;
          end
          // the completed frame becomes the reference unless a golden one is held
          if (frame_end) begin
              chg_prev <= chg_line;
              ref_vld <= 1'b1;
          end else if (cap_wr_ctl && wr_data[2]) begin
              ref_vld <= 1'b0;
          end
          if (ref_take) begin
              for (k = 0; k < 7; k = k + 1)
                  ref_sig[k] <= row_sig[k];
              ref_sig[7] <= line_sig_nx;
          end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_hist_stamp = hist_empty ? 64'd0 : hist_mem[hist_rd_ptr];
   assign o_hist_sig = hist_empty ? 16'd0 : hist_sum[hist_rd_ptr];
   assign o_hist_state = hist_empty ? ST_FREE : hist_st[hist_rd_ptr];
   assign o_hist_level = hist_cnt;
   assign o_hist_open = !hist_empty && (hist_st[hist_last] == ST_OPEN);
   assign o_last_sig = hist_empty ? 16'd0 : hist_sum[hist_last];
   assign o_hist_drops = hist_drop;
   assign o_abort_cnt = abort_cnt;
   assign o_ret_stamp = ret_stamp;
   assign o_ret_sig = ret_sum;
   assign o_ret_state = ret_st;
   assign o_ret_valid = ret_vld;
  assign o_cap_sig = row_sig[cap_sel];
  assign o_cap_ink = row_ink[cap_sel];
  assign o_cap_tag = row_tag[cap_sel];
  assign o_cap_hit = cap_hit;
  assign o_cap_fill = row_fill;
  assign o_cap_cut = cap_cut;
  assign o_cap_cut_row = cap_cut_row;
  assign o_cap_chg = row_chg;
  assign o_cap_chg_prev = chg_prev;
  assign o_cap_nchg = nchg;
  assign o_cap_static = ref_vld && (chg_prev == 8'h00) && !cap_cut;
  assign o_ref_sig = ref_sig[cap_sel];
  assign o_ref_valid = ref_vld;
  assign o_cap_ctl = {ref_hold, cap_auto, cap_lock};
  assign o_cap_wait = cap_wait;
  assign o_cap_stb = cap_stb;
  assign o_cap_row = cap_row_idx;
  assign o_line_sig = line_sig;
  assign o_line_ink = line_ink;
  assign o_frame_ink = frame_ink;
  assign o_col_ink = col_ink;
  assign o_ink_left = ink_left;
  assign o_ink_right = ink_right;
  assign o_ext_top = ext_top;
  assign o_ext_bot = ext_bot;
  assign o_ext_valid = ext_vld;

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);

   always @(posedge clk)
       if (done)
           assert (hist_cnt != 3'd0 && hist_st[hist_last] == ST_DONE && hist_mem[hist_last] == frame_cnt);

  // a finished frame leaves a complete, uncut row table stamped with its frame number
  always @(posedge clk)
      if (done)
          assert (row_fill == CAP_ROWS && !cap_cut && row_tag[0] == frame_cnt && row_tag[7] == frame_cnt);
endmodule

module fm_pkt_guard #(
   parameter [5:0] MAX_LEN = 6'd48,
   parameter [5:0] MIN_LEN = 6'd4,
   parameter [1:0] IFG     = 2'd3
) (
   input  wire        clk,
   input  wire        rst,
   input  wire        i_sym,
   input  wire        i_in_pkt,
   input  wire        i_sof,
   input  wire        i_eof,
   input  wire        i_trunc,
   input  wire        i_beat,
   input  wire        i_comma,
   input  wire [7:0]  i_data,
   output wire [5:0]  o_len,
   output wire [1:0]  o_holdoff,
   output wire        o_trunc_req,
   output wire        o_sof_ok,
   output reg  [7:0]  o_trunc_cnt,
   output reg  [7:0]  o_drop_cnt,
   output reg  [7:0]  o_runt_cnt,
   output reg  [7:0]  o_kin_cnt,
   output reg  [31:0] o_byte_cnt,
   output reg  [7:0]  o_pkt_sum,
   output reg         o_last_trunc,
   output reg         o_last_runt
);
   reg [5:0] len;
   reg [1:0] holdoff;
   reg [7:0] run_sum;

   initial begin
       len = 6'd0; holdoff = 2'd0; run_sum = 8'd0;
       o_trunc_cnt = 8'd0; o_drop_cnt = 8'd0; o_runt_cnt = 8'd0; o_kin_cnt = 8'd0;
       o_byte_cnt = 32'd0; o_pkt_sum = 8'd0;
       o_last_trunc = 1'b0; o_last_runt = 1'b0;
   end

   // a packet is closed either by a real EOF or by the length limit
   wire at_limit  = (len == MAX_LEN);
   wire close_pkt = i_eof || i_trunc;
   wire take_beat = i_beat && i_in_pkt && !at_limit;
   wire runt      = i_eof && (len < MIN_LEN);
   wire dropped   = i_trunc && i_beat;
   wire in_band_k = i_comma && i_in_pkt;

   assign o_len       = len;
   assign o_holdoff   = holdoff;
   assign o_trunc_req = at_limit;
   assign o_sof_ok    = (holdoff == 2'd0);

   // payload length of the open packet
   always @(posedge clk) begin
       if (rst) begin
           len <= 6'd0;
       end else if (i_sof || close_pkt) begin
           len <= 6'd0;
       end else if (take_beat) begin
           len <= len + 6'd1;
       end
   end

   // minimum inter-frame gap after each packet
   always @(posedge clk) begin
       if (rst) begin
           holdoff <= 2'd0;
       end else if (close_pkt) begin
           holdoff <= IFG;
       end else if (i_sym && (holdoff != 2'd0)) begin
           holdoff <= holdoff - 2'd1;
       end
   end

   // running payload sum, published when the packet closes
   always @(posedge clk) begin
       if (rst) begin
           run_sum   <= 8'd0;
           o_pkt_sum <= 8'd0;
       end else if (i_sof) begin
           run_sum   <= 8'd0;
       end else if (close_pkt) begin
           o_pkt_sum <= run_sum;
           run_sum   <= 8'd0;
       end else if (take_beat) begin
           run_sum   <= run_sum + i_data;
       end
   end

   // saturating event counters
   always @(posedge clk) begin
       if (rst) begin
           o_trunc_cnt <= 8'd0;
           o_drop_cnt  <= 8'd0;
           o_runt_cnt  <= 8'd0;
           o_kin_cnt   <= 8'd0;
       end else begin
           if (i_trunc && (o_trunc_cnt != 8'hFF))
               o_trunc_cnt <= o_trunc_cnt + 8'd1;
           if (dropped && (o_drop_cnt != 8'hFF))
               o_drop_cnt <= o_drop_cnt + 8'd1;
           if (runt && (o_runt_cnt != 8'hFF))
               o_runt_cnt <= o_runt_cnt + 8'd1;
           if (in_band_k && (o_kin_cnt != 8'hFF))
               o_kin_cnt <= o_kin_cnt + 8'd1;
       end
   end

   // payload byte counter and per-packet close status
   always @(posedge clk) begin
       if (rst) begin
           o_byte_cnt   <= 32'd0;
           o_last_trunc <= 1'b0;
           o_last_runt  <= 1'b0;
       end else begin
           if (take_beat)
               o_byte_cnt <= o_byte_cnt + 32'd1;
           if (close_pkt) begin
               o_last_trunc <= i_trunc;
               o_last_runt  <= runt;
           end
       end
   end
endmodule

module fm_link_8b10b_framer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [7:0]  i_data,
    output reg  [9:0]  o_sym,
    output reg         o_rd,
    output reg  [31:0] o_sym_cnt,
   output reg  [31:0] o_pkt_cnt,
   output wire [5:0]  o_pg_len,
   output wire [1:0]  o_pg_holdoff,
   output wire [7:0]  o_trunc_cnt,
   output wire [7:0]  o_drop_cnt,
   output wire [7:0]  o_runt_cnt,
   output wire [7:0]  o_kin_cnt,
   output wire [31:0] o_byte_cnt,
   output wire [7:0]  o_pkt_sum,
  output wire [3:0]  o_pg_status,
  output wire [6:0]  o_vc_status,
  output reg  [31:0] o_vc1_pkt_cnt,
  output reg  [31:0] o_vc1_byte_cnt,
  output reg  [7:0]  o_vc0_pkt_sum,
  output reg  [7:0]  o_vc1_pkt_sum,
  output reg  [7:0]  o_vc0_err_cnt,
  output reg  [7:0]  o_vc1_err_cnt,
  output reg  [7:0]  o_sel_cnt,
  output reg  [7:0]  o_sel_rej_cnt,
  output reg  [7:0]  o_ifg_defer_cnt,
  output reg  [7:0]  o_vc1_realign_cnt
);
    localparam [1:0] K_COMMA = 2'd1, K_SOF = 2'd2, K_EOF = 2'd3;
    localparam [1:0] PH_IDLE = 2'd0, PH_ALIGN = 2'd1, PH_PKT = 2'd2;
   // K_SEL (kcode 0) switches the virtual channel; i_data[0] carries the channel id
   localparam [1:0] K_SEL = 2'd0;
   // channel 1 must see a fresh comma at least every VC1_REALIGN+1 frames
   localparam [1:0] VC1_REALIGN = 2'd3;
   localparam [5:0] VC1_MIN_LEN = 6'd4;

    reg [1:0] phase;
    reg seen_comma, seen_start, seen_end;
   reg       vc_sel;
   reg [1:0] ph1;
   reg [1:0] vc1_since_comma;
   reg       vc1_last_trunc, vc1_last_runt;
   reg       sum_pend, sum_vc;

    initial begin
        phase = PH_IDLE; seen_comma = 1'b0; seen_start = 1'b0; seen_end = 1'b0;
        o_sym = 10'd0; o_rd = 1'b0; o_sym_cnt = 32'd0; o_pkt_cnt = 32'd0;
       vc_sel = 1'b0; ph1 = PH_IDLE; vc1_since_comma = 2'd0;
       vc1_last_trunc = 1'b0; vc1_last_runt = 1'b0;
       sum_pend = 1'b0; sum_vc = 1'b0;
       o_vc1_pkt_cnt = 32'd0; o_vc1_byte_cnt = 32'd0;
       o_vc0_pkt_sum = 8'd0; o_vc1_pkt_sum = 8'd0;
       o_vc0_err_cnt = 8'd0; o_vc1_err_cnt = 8'd0;
       o_sel_cnt = 8'd0; o_sel_rej_cnt = 8'd0;
       o_ifg_defer_cnt = 8'd0; o_vc1_realign_cnt = 8'd0;
    end

    function [5:0] enc6;
        input [4:0] x;
        begin
            case (x)
                5'd0:  enc6 = 6'b100111;
                5'd1:  enc6 = 6'b011101;
                5'd2:  enc6 = 6'b101101;
                5'd3:  enc6 = 6'b110001;
                5'd4:  enc6 = 6'b110101;
                5'd5:  enc6 = 6'b101001;
                5'd6:  enc6 = 6'b011001;
                5'd7:  enc6 = 6'b111000;
                5'd8:  enc6 = 6'b111001;
                5'd9:  enc6 = 6'b100101;
                5'd10: enc6 = 6'b010101;
                5'd11: enc6 = 6'b110100;
                5'd12: enc6 = 6'b001101;
                5'd13: enc6 = 6'b101100;
                5'd14: enc6 = 6'b011100;
                5'd15: enc6 = 6'b010111;
                5'd16: enc6 = 6'b011011;
                5'd17: enc6 = 6'b100011;
                5'd18: enc6 = 6'b010011;
                5'd19: enc6 = 6'b110010;
                5'd20: enc6 = 6'b001011;
                5'd21: enc6 = 6'b101010;
                5'd22: enc6 = 6'b011010;
                5'd23: enc6 = 6'b111010;
                5'd24: enc6 = 6'b110011;
                5'd25: enc6 = 6'b100110;
                5'd26: enc6 = 6'b010110;
                5'd27: enc6 = 6'b110110;
                5'd28: enc6 = 6'b001110;
                5'd29: enc6 = 6'b101110;
                5'd30: enc6 = 6'b011110;
                default: enc6 = 6'b101011;
            endcase
        end
    endfunction

    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
                3'd5: enc4 = 4'b1010;
                3'd6: enc4 = 4'b0110;
                default: enc4 = 4'b1110;
            endcase
        end
    endfunction

    function [2:0] ones6;
        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

   // packet guard status
   wire [5:0] pg_len;
   wire [1:0] pg_holdoff;
   wire       pg_trunc_req;
   wire       pg_sof_ok;
   wire       pg_last_trunc;
   wire       pg_last_runt;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
   // control symbols are steered to the currently selected virtual channel;
   // both channels share the guard, so only the active one can hold a frame
   wire k_any      = i_ce && i_k;
   wire act_in_pkt = vc_sel ? (ph1 == PH_PKT) : (phase == PH_PKT);
   wire sof_req0   = k_any && (i_kcode == K_SOF) && !vc_sel;
   wire eof_req0   = k_any && (i_kcode == K_EOF) && !vc_sel;
   wire sof_req1   = k_any && (i_kcode == K_SOF) && vc_sel;
   wire eof_req1   = k_any && (i_kcode == K_EOF) && vc_sel;
   wire do_comma   = k_any && (i_kcode == K_COMMA) && !vc_sel;
   wire do_sof     = sof_req0 && (phase == PH_ALIGN) && pg_sof_ok;
   wire do_eof     = eof_req0 && (phase == PH_PKT);
   wire do_comma1  = k_any && (i_kcode == K_COMMA) && vc_sel;
   wire do_sof1    = sof_req1 && (ph1 == PH_ALIGN) && pg_sof_ok;
   wire do_eof1    = eof_req1 && (ph1 == PH_PKT);
   // channel switch is honoured only between frames of the active channel
   wire sel_req    = k_any && (i_kcode == K_SEL);
   wire do_sel     = sel_req && !act_in_pkt;
   wire sel_rej    = sel_req && act_in_pkt;
   wire sel_switch = do_sel && (i_data[0] != vc_sel);
    wire do_data  = i_ce && !i_k;
   // oversize packet: close it with an EOF in place of the next symbol
   wire do_trunc   = i_ce && pg_trunc_req;
  wire trunc_take = do_trunc && !do_comma && !do_sof && !do_eof &&
                    !do_comma1 && !do_sof1 && !do_eof1 && !do_sel;
  // the truncating EOF is charged to the channel that owns the guard
  wire trunc0     = trunc_take && !vc_sel;
  wire trunc1     = trunc_take && vc_sel;
  wire vc1_close  = do_eof1 || trunc1;
  wire vc1_beat   = do_data && vc_sel && act_in_pkt && !pg_trunc_req;
  // out-of-sequence framing symbols, per channel
  wire err0       = (sof_req0 && (phase != PH_ALIGN)) || (eof_req0 && (phase != PH_PKT));
  wire err1       = (sof_req1 && (ph1 != PH_ALIGN)) || (eof_req1 && (ph1 != PH_PKT));
  // aligned SOF refused because the shared inter-frame gap is still running
  wire ifg_defer  = ((sof_req0 && (phase == PH_ALIGN)) ||
                     (sof_req1 && (ph1 == PH_ALIGN))) && !pg_sof_ok;

   fm_pkt_guard #(
       .MAX_LEN(6'd48),
       .MIN_LEN(6'd4),
       .IFG(2'd3)
   ) u_guard (
       .clk(clk),
       .rst(rst),
       .i_sym(i_ce),
      .i_in_pkt(act_in_pkt),
      .i_sof(do_sof || do_sof1),
      .i_eof(do_eof || do_eof1),
       .i_trunc(trunc_take),
       .i_beat(do_data),
      .i_comma(do_comma || do_comma1),
       .i_data(i_data),
       .o_len(pg_len),
       .o_holdoff(pg_holdoff),
       .o_trunc_req(pg_trunc_req),
       .o_sof_ok(pg_sof_ok),
       .o_trunc_cnt(o_trunc_cnt),
       .o_drop_cnt(o_drop_cnt),
       .o_runt_cnt(o_runt_cnt),
       .o_kin_cnt(o_kin_cnt),
       .o_byte_cnt(o_byte_cnt),
       .o_pkt_sum(o_pkt_sum),
       .o_last_trunc(pg_last_trunc),
       .o_last_runt(pg_last_runt)
   );

   assign o_pg_len     = pg_len;
   assign o_pg_holdoff = pg_holdoff;
   assign o_pg_status  = {pg_last_trunc, pg_last_runt, pg_trunc_req, pg_sof_ok};
  assign o_vc_status  = {vc_sel, ph1, vc1_since_comma, vc1_last_trunc, vc1_last_runt};

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
        end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
      end else if (do_sel) begin
          // K28.0 selects channel 0, K28.4 selects channel 1 (both neutral)
          o_sym      <= i_data[0] ? (o_rd ? 10'b1100001101 : 10'b0011110010)
                                  : (o_rd ? 10'b1100001011 : 10'b0011110100);
          o_sym_cnt  <= o_sym_cnt + 32'd1;
      end else if (do_comma1) begin
          o_sym      <= o_rd ? 10'b1100000110 : 10'b0011111001;
          o_rd       <= ~o_rd;
          o_sym_cnt  <= o_sym_cnt + 32'd1;
      end else if (do_sof1) begin
          o_sym      <= o_rd ? 10'b1100001010 : 10'b0011110101;
          o_rd       <= ~o_rd;
          o_sym_cnt  <= o_sym_cnt + 32'd1;
      end else if (do_eof1) begin
          o_sym      <= o_rd ? 10'b1000010111 : 10'b0111101000;
          o_sym_cnt  <= o_sym_cnt + 32'd1;
      end else if (trunc0) begin
           o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
           seen_end   <= 1'b1;
           phase      <= PH_ALIGN;
           o_pkt_cnt  <= o_pkt_cnt + 32'd1;
           o_sym_cnt  <= o_sym_cnt + 32'd1;
      end else if (trunc1) begin
          o_sym      <= o_rd ? 10'b1000010111 : 10'b0111101000;
          o_sym_cnt  <= o_sym_cnt + 32'd1;
       end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));

   // channel 1 framing state: shares the length/IFG guard with channel 0 and
   // drops back to IDLE after VC1_REALIGN+1 frames without a fresh comma
   always @(posedge clk) begin
       if (rst) begin
           ph1               <= PH_IDLE;
           vc1_since_comma   <= 2'd0;
           vc1_last_trunc    <= 1'b0;
           vc1_last_runt     <= 1'b0;
           o_vc1_pkt_cnt     <= 32'd0;
           o_vc1_realign_cnt <= 8'd0;
       end else if (do_comma1) begin
           if (ph1 == PH_IDLE) ph1 <= PH_ALIGN;
           vc1_since_comma   <= 2'd0;
       end else if (do_sof1) begin
           ph1               <= PH_PKT;
       end else if (vc1_close) begin
           o_vc1_pkt_cnt     <= o_vc1_pkt_cnt + 32'd1;
           vc1_last_trunc    <= trunc1;
           vc1_last_runt     <= do_eof1 && (pg_len < VC1_MIN_LEN);
           if (vc1_since_comma == VC1_REALIGN) begin
               ph1             <= PH_IDLE;
               vc1_since_comma <= 2'd0;
               if (o_vc1_realign_cnt != 8'hFF)
                   o_vc1_realign_cnt <= o_vc1_realign_cnt + 8'd1;
           end else begin
               ph1             <= PH_ALIGN;
               vc1_since_comma <= vc1_since_comma + 2'd1;
           end
       end
   end

   // channel 1 payload beats accepted by the shared guard
   always @(posedge clk) begin
       if (rst) begin
           o_vc1_byte_cnt <= 32'd0;
       end else if (vc1_beat) begin
           o_vc1_byte_cnt <= o_vc1_byte_cnt + 32'd1;
       end
   end

   // per-channel copy of the frame sum; the guard publishes o_pkt_sum one
   // cycle after the close, so remember which channel the close belonged to
   wire any_close = do_eof || do_eof1 || trunc_take;
   always @(posedge clk) begin
       if (rst) begin
           sum_pend      <= 1'b0;
           sum_vc        <= 1'b0;
           o_vc0_pkt_sum <= 8'd0;
           o_vc1_pkt_sum <= 8'd0;
       end else begin
           sum_pend <= any_close;
           if (any_close) sum_vc <= vc_sel;
           if (sum_pend) begin
               if (sum_vc) o_vc1_pkt_sum <= o_pkt_sum;
               else        o_vc0_pkt_sum <= o_pkt_sum;
           end
       end
   end

   // channel select register and link-level framing error counters
   always @(posedge clk) begin
       if (rst) begin
           vc_sel          <= 1'b0;
           o_sel_cnt       <= 8'd0;
           o_sel_rej_cnt   <= 8'd0;
           o_vc0_err_cnt   <= 8'd0;
           o_vc1_err_cnt   <= 8'd0;
           o_ifg_defer_cnt <= 8'd0;
       end else begin
           if (do_sel) vc_sel <= i_data[0];
           if (sel_switch && (o_sel_cnt != 8'hFF))
               o_sel_cnt <= o_sel_cnt + 8'd1;
           if (sel_rej && (o_sel_rej_cnt != 8'hFF))
               o_sel_rej_cnt <= o_sel_rej_cnt + 8'd1;
           if (err0 && (o_vc0_err_cnt != 8'hFF))
               o_vc0_err_cnt <= o_vc0_err_cnt + 8'd1;
           if (err1 && (o_vc1_err_cnt != 8'hFF))
               o_vc1_err_cnt <= o_vc1_err_cnt + 8'd1;
           if (ifg_defer && (o_ifg_defer_cnt != 8'hFF))
               o_ifg_defer_cnt <= o_ifg_defer_cnt + 8'd1;
       end
   end
endmodule

module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire [7:0] o_scan_pix,
   output wire o_scan_valid,
   output wire o_scan_eol,
   output wire o_scan_eof,
   output wire [7:0] o_scan_pos,
   output wire [3:0] o_pixq_level,
   output wire [3:0] o_pixq_peak,
   output wire [7:0] o_underrun,
   output wire [63:0] o_scan_frames
,
    output wire arm_seen_o,
    output wire done_o,
    output wire [1:0] phase_o,
    output wire [3:0] pixq_count_o,
    output wire [3:0] pixq_peak_o,
    output wire [4:0] scan_col_o,
    output wire start_seen_o
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

   localparam [4:0] SCAN_CFG_ADDR = 5'd24;
   localparam [3:0] PIXQ_DEPTH = 4'd8;

   reg [7:0]  pixq_data [0:7];
   reg [7:0]  pixq_eof;
   reg [2:0]  pixq_wr_ptr;
   reg [2:0]  pixq_rd_ptr;
   reg [3:0]  pixq_count;
   reg [3:0]  pixq_peak;
   reg [3:0]  scan_div;
   reg [3:0]  scan_tmr;
   reg [4:0]  scan_col;
   reg [2:0]  scan_row;
   reg [7:0]  scan_pix;
   reg        scan_valid;
   reg        scan_eol;
   reg        scan_eof;
   reg [7:0]  underrun_cnt;
   reg [63:0] scan_frames;
   integer k;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;
   initial begin
       for (i = 0; i < 8; i = i + 1)
           pixq_data[i] = 8'h00;
   end
   initial pixq_eof = 8'h00;
   initial pixq_wr_ptr = 3'd0;
   initial pixq_rd_ptr = 3'd0;
   initial pixq_count = 4'd0;
   initial pixq_peak = 4'd0;
   initial scan_div = 4'd1;
   initial scan_tmr = 4'd0;
   initial scan_col = 5'd0;
   initial scan_row = 3'd0;
   initial scan_pix = 8'h00;
   initial scan_valid = 1'b0;
   initial scan_eol = 1'b0;
   initial scan_eof = 1'b0;
   initial underrun_cnt = 8'd0;
   initial scan_frames = 64'd0;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire last_px = last_col && last_row;
   wire [7:0] gen_pix = font_row(cur_char, row_cnt[2:0]);
   wire pixq_full = (pixq_count >= PIXQ_DEPTH);
   wire pixq_empty = (pixq_count == 4'd0);
   wire gen_push = (phase == RUN) && !pixq_full;
   wire scan_tick = (scan_tmr == 4'd0);
   wire scan_pop = scan_tick && !pixq_empty;
   wire head_eof = pixq_eof[pixq_rd_ptr];
   wire [7:0] head_pix = pixq_data[pixq_rd_ptr];
   wire scan_line_end = (scan_col >= 5'd23);
   wire scan_starved = scan_tick && pixq_empty && (phase == RUN);

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
           for (k = 0; k < 8; k = k + 1)
               pixq_data[k] <= 8'h00;
           pixq_eof <= 8'h00;
           pixq_wr_ptr <= 3'd0;
           pixq_rd_ptr <= 3'd0;
           pixq_count <= 4'd0;
           pixq_peak <= 4'd0;
           scan_div <= 4'd1;
           scan_tmr <= 4'd0;
           scan_col <= 5'd0;
           scan_row <= 3'd0;
           scan_pix <= 8'h00;
           scan_valid <= 1'b0;
           scan_eol <= 1'b0;
           scan_eof <= 1'b0;
           underrun_cnt <= 8'd0;
           scan_frames <= 64'd0;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
           if (wr_en && (wr_addr == SCAN_CFG_ADDR))
               scan_div <= wr_data[3:0];
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
               pixq_eof <= 8'h00;
               pixq_wr_ptr <= 3'd0;
               pixq_rd_ptr <= 3'd0;
               pixq_count <= 4'd0;
               scan_tmr <= scan_div;
               scan_col <= 5'd0;
               scan_row <= 3'd0;
               scan_valid <= 1'b0;
               scan_eol <= 1'b0;
               scan_eof <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                        if (start_req) begin
                            phase <= RUN;
                            start_seen <= 1'b1;
                            col_cnt <= 64'd0;
                            row_cnt <= 64'd0;
                        end
                    end
                    RUN: begin
                       if (gen_push) begin
                           pix_row <= gen_pix;
                           pixq_data[pixq_wr_ptr] <= gen_pix;
                           pixq_eof[pixq_wr_ptr] <= last_px;
                           pixq_wr_ptr <= pixq_wr_ptr + 3'd1;
                           if (last_col) begin
                               col_cnt <= 64'd0;
                               if (last_row) begin
                                   row_cnt <= 64'd0;
                                   phase <= FIN;
                                   frame_cnt <= frame_cnt + 64'd1;
                               end else begin
                                   row_cnt <= row_cnt + 64'd1;
                               end
                           end else begin
                               col_cnt <= col_cnt + 64'd1;
                           end
                       end
                    end
                    FIN: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
               if (scan_pop) begin
                   scan_pix <= head_pix;
                   scan_eof <= head_eof;
                   scan_eol <= scan_line_end || head_eof;
                   pixq_rd_ptr <= pixq_rd_ptr + 3'd1;
                   if (head_eof) begin
                       scan_col <= 5'd0;
                       scan_row <= 3'd0;
                       scan_frames <= scan_frames + 64'd1;
                       done <= 1'b1;
                   end else if (scan_line_end) begin
                       scan_col <= 5'd0;
                       scan_row <= scan_row + 3'd1;
                   end else begin
                       scan_col <= scan_col + 5'd1;
                   end
               end
               scan_valid <= scan_pop;
               if (gen_push && !scan_pop)
                   pixq_count <= pixq_count + 4'd1;
               else if (scan_pop && !gen_push)
                   pixq_count <= pixq_count - 4'd1;
               if (pixq_count > pixq_peak)
                   pixq_peak <= pixq_count;
               if (scan_tick)
                   scan_tmr <= scan_div;
               else
                   scan_tmr <= scan_tmr - 4'd1;
               if (scan_starved && (underrun_cnt != 8'hFF))
                   underrun_cnt <= underrun_cnt + 8'd1;
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_scan_pix = scan_pix;
   assign o_scan_valid = scan_valid;
   assign o_scan_eol = scan_eol;
   assign o_scan_eof = scan_eof;
   assign o_scan_pos = {scan_row, scan_col};
   assign o_pixq_level = pixq_count;
   assign o_pixq_peak = pixq_peak;
   assign o_underrun = underrun_cnt;
   assign o_scan_frames = scan_frames;

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
    assign arm_seen_o = arm_seen;
    assign done_o = done;
    assign phase_o = phase;
    assign pixq_count_o = pixq_count;
    assign pixq_peak_o = pixq_peak;
    assign scan_col_o = scan_col;
    assign start_seen_o = start_seen;
endmodule

module dirty_track_ram (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_we,
    input  wire [1:0]   i_addr,
    input  wire [127:0] i_wdata,
    input  wire         i_clr,
    input  wire         i_clr_blk,
    input  wire         i_clr_all,
    output wire [127:0] o_rdata,
    output wire [1:0]   o_dirty,
    output wire [1:0]   o_dirty_cnt,
    output wire         o_any_dirty
,
    output wire any_dirty_o,
    output wire [1:0] dirty_o,
    output wire [1:0] dirty_cnt_o
);
    // 4 x 128-bit data array, organised as 2 blocks of 2 words
    reg [127:0] mem [0:3];
    reg [1:0]   dirty     = 2'b00;
    reg [1:0]   dirty_cnt = 2'd0;
    reg         any_dirty = 1'b0;

    initial begin
        mem[0] = 128'd0;
        mem[1] = 128'd0;
        mem[2] = 128'd0;
        mem[3] = 128'd0;
    end

    wire wblk = i_addr[1];

    reg [1:0] dirty_nx;
    reg [1:0] cnt_nx;
    always @(*) begin
        dirty_nx = dirty;
        cnt_nx   = dirty_cnt;
        if (i_we) begin
            dirty_nx[wblk] = 1'b1;
            if (!dirty[wblk])
                cnt_nx = dirty_cnt + 2'd1;
        end else if (i_clr_all) begin
            dirty_nx = 2'b00;
            cnt_nx   = 2'd0;
        end else if (i_clr) begin
            dirty_nx[i_clr_blk] = 1'b0;
            if (dirty[i_clr_blk])
                cnt_nx = dirty_cnt - 2'd1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_we)
                mem[i_addr] <= i_wdata;
            dirty     <= dirty_nx;
            dirty_cnt <= cnt_nx;
            any_dirty <= |dirty_nx;
        end
    end

    assign o_rdata     = mem[i_addr];
    assign o_dirty     = dirty;
    assign o_dirty_cnt = dirty_cnt;
    assign o_any_dirty = any_dirty;

    always @(*)
        assert (any_dirty == (dirty_cnt != 2'd0));
    assign any_dirty_o = any_dirty;
    assign dirty_o = dirty;
    assign dirty_cnt_o = dirty_cnt;
endmodule

module banner_capture_top (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    input wire ram_ce,
    input wire [1:0] rd_addr,
    input wire clr,
    input wire clr_blk,
    input wire clr_all,
    output wire [127:0] o_rdata,
    output wire [1:0] o_dirty,
    output wire [1:0] o_dirty_cnt,
    output wire o_any_dirty,
    output wire o_done,
    output wire [63:0] o_scan_frames,
    output wire [7:0] o_underrun,
    output wire o_wq_valid,
    output wire [1:0] o_wq_addr,
    output wire [4:0] o_wq_len,
    output wire [4:0] o_pk_cnt,
    output wire [1:0] o_seg_addr,
    output wire [7:0] o_drop_cnt
);
    wire [7:0] a_pix;
    wire a_done_p;
    wire [7:0] a_scan_pix;
    wire a_scan_valid;
    wire a_scan_eol;
    wire a_scan_eof;
    wire [7:0] a_scan_pos;
    wire [3:0] a_pixq_level;
    wire [3:0] a_pixq_peak_p;
    wire [7:0] a_underrun;
    wire [63:0] a_scan_frames;
    wire a_arm_seen;
    wire a_done;
    wire [1:0] a_phase;
    wire [3:0] a_pixq_count;
    wire [3:0] a_pixq_peak;
    wire [4:0] a_scan_col;
    wire a_start_seen;

    wire [127:0] b_rdata;
    wire [1:0] b_dirty_p;
    wire [1:0] b_dirty_cnt_p;
    wire b_any_dirty_p;
    wire b_any_dirty;
    wire [1:0] b_dirty;
    wire [1:0] b_dirty_cnt;

    reg [127:0] pk_data;
    reg [4:0] pk_cnt;
    reg wq_valid;
    reg [127:0] wq_data;
    reg [1:0] wq_addr;
    reg [4:0] wq_len;
    reg [1:0] seg_addr;
    reg [7:0] drop_cnt;

    initial pk_data = 128'd0;
    initial pk_cnt = 5'd0;
    initial wq_valid = 1'b0;
    initial wq_data = 128'd0;
    initial wq_addr = 2'd0;
    initial wq_len = 5'd0;
    initial seg_addr = 2'd0;
    initial drop_cnt = 8'd0;

    tplan_banner_gen u_gen (
        .clk(clk),
        .rst_n(rst_n),
        .en(en),
        .arm_req(arm_req),
        .start_req(start_req),
        .abort_req(abort_req),
        .wr_en(wr_en),
        .wr_addr(wr_addr),
        .wr_data(wr_data),
        .o_pix(a_pix),
        .o_done(a_done_p),
        .o_scan_pix(a_scan_pix),
        .o_scan_valid(a_scan_valid),
        .o_scan_eol(a_scan_eol),
        .o_scan_eof(a_scan_eof),
        .o_scan_pos(a_scan_pos),
        .o_pixq_level(a_pixq_level),
        .o_pixq_peak(a_pixq_peak_p),
        .o_underrun(a_underrun),
        .o_scan_frames(a_scan_frames),
        .arm_seen_o(a_arm_seen),
        .done_o(a_done),
        .phase_o(a_phase),
        .pixq_count_o(a_pixq_count),
        .pixq_peak_o(a_pixq_peak),
        .scan_col_o(a_scan_col),
        .start_seen_o(a_start_seen)
    );

    wire take = en && a_scan_valid;
    wire seg_end = (pk_cnt >= 5'd15) || a_scan_eol;
    wire wq_free = !wq_valid || ram_ce;
    wire [127:0] pk_word = {pk_data[119:0], a_scan_pix};

    dirty_track_ram u_ram (
        .clk(clk),
        .i_ce(ram_ce),
        .i_we(wq_valid),
        .i_addr(wq_valid ? wq_addr : rd_addr),
        .i_wdata(wq_data),
        .i_clr(clr),
        .i_clr_blk(clr_blk),
        .i_clr_all(clr_all),
        .o_rdata(b_rdata),
        .o_dirty(b_dirty_p),
        .o_dirty_cnt(b_dirty_cnt_p),
        .o_any_dirty(b_any_dirty_p),
        .any_dirty_o(b_any_dirty),
        .dirty_o(b_dirty),
        .dirty_cnt_o(b_dirty_cnt)
    );

    always @(posedge clk) begin
        if (!rst_n) begin
            pk_data <= 128'd0;
            pk_cnt <= 5'd0;
            wq_valid <= 1'b0;
            wq_data <= 128'd0;
            wq_addr <= 2'd0;
            wq_len <= 5'd0;
            seg_addr <= 2'd0;
            drop_cnt <= 8'd0;
        end else begin
            if (wq_valid && ram_ce)
                wq_valid <= 1'b0;
            if (en && abort_req) begin
                pk_data <= 128'd0;
                pk_cnt <= 5'd0;
                seg_addr <= 2'd0;
            end else if (take) begin
                if (seg_end) begin
                    pk_data <= 128'd0;
                    pk_cnt <= 5'd0;
                    if (wq_free) begin
                        wq_valid <= 1'b1;
                        wq_data <= pk_word;
                        wq_addr <= seg_addr;
                        wq_len <= pk_cnt + 5'd1;
                    end else if (drop_cnt != 8'hFF) begin
                        drop_cnt <= drop_cnt + 8'd1;
                    end
                    seg_addr <= a_scan_eof ? 2'd0 : (seg_addr + 2'd1);
                end else begin
                    pk_data <= pk_word;
                    pk_cnt <= pk_cnt + 5'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (wq_valid)
            assert ((wq_len != 5'd0) && (wq_len <= 5'd16));

    assign o_rdata = b_rdata;
    assign o_dirty = b_dirty_p;
    assign o_dirty_cnt = b_dirty_cnt_p;
    assign o_any_dirty = b_any_dirty_p;
    assign o_done = a_done_p;
    assign o_scan_frames = a_scan_frames;
    assign o_underrun = a_underrun;
    assign o_wq_valid = wq_valid;
    assign o_wq_addr = wq_addr;
    assign o_wq_len = wq_len;
    assign o_pk_cnt = pk_cnt;
    assign o_seg_addr = seg_addr;
    assign o_drop_cnt = drop_cnt;
endmodule

module tplan_seq_ctrl (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire [1:0] phase_i,
   input wire start_req,
   input wire abort_req,
   input wire frame_end,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire start_ack,
   output wire fire,
   output wire rearm,
   output wire busy,
   output wire pend_o,
   output wire loop_pend_o,
   output wire ovr_o,
   output wire [3:0] delay_o,
   output wire [3:0] loops_o
);
   reg [3:0] cfg_preroll;
   reg [3:0] cfg_loops;
   reg       cfg_auto;
   reg       pend;
   reg [3:0] delay_cnt;
   reg       loop_pend;
   reg [3:0] loops_left;
   reg       ovr;
   initial cfg_preroll = 4'd0;
   initial cfg_loops = 4'd0;
   initial cfg_auto = 1'b0;
   initial pend = 1'b0;
   initial delay_cnt = 4'd0;
   initial loop_pend = 1'b0;
   initial loops_left = 4'd0;
   initial ovr = 1'b0;
   wire armed = (phase_i == 2'd1);
   wire fin = (phase_i == 2'd3);
   assign start_ack = armed && !pend && !abort_req && (start_req || loop_pend);
   assign fire = pend && (delay_cnt == 4'd0) && !abort_req;
   assign rearm = fin && loop_pend && !abort_req;
   assign busy = pend || loop_pend;
   assign pend_o = pend;
   assign loop_pend_o = loop_pend;
   assign ovr_o = ovr;
   assign delay_o = delay_cnt;
   assign loops_o = loops_left;
   always @(posedge clk) begin
       if (!rst_n) begin
           cfg_preroll <= 4'd0;
           cfg_loops <= 4'd0;
           cfg_auto <= 1'b0;
           pend <= 1'b0;
           delay_cnt <= 4'd0;
           loop_pend <= 1'b0;
           loops_left <= 4'd0;
           ovr <= 1'b0;
       end else if (en) begin
           if (csr_we) begin
               case (csr_addr)
                   3'd0: cfg_preroll <= csr_wdata[3:0];
                   3'd1: cfg_loops <= csr_wdata[3:0];
                   3'd2: cfg_auto <= csr_wdata[0];
                   3'd3: ovr <= 1'b0;
               endcase
           end
           if (start_req && pend && !abort_req)
               ovr <= 1'b1;
           if (abort_req) begin
               pend <= 1'b0;
               delay_cnt <= 4'd0;
               loop_pend <= 1'b0;
               loops_left <= 4'd0;
           end else begin
               if (start_ack) begin
                   pend <= 1'b1;
                   delay_cnt <= cfg_preroll;
                   if (loop_pend) begin
                       loop_pend <= 1'b0;
                       loops_left <= loops_left - 4'd1;
                   end else begin
                       loops_left <= cfg_loops;
                   end
               end else if (pend) begin
                   if (delay_cnt == 4'd0)
                       pend <= 1'b0;
                   else
                       delay_cnt <= delay_cnt - 4'd1;
               end
               if (frame_end && cfg_auto && (loops_left != 4'd0))
                   loop_pend <= 1'b1;
           end
       end
   end
endmodule
module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire o_seq_busy,
   output wire [10:0] o_seq_stat
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire seq_start_ack, seq_fire, seq_rearm, seq_busy;
   wire seq_pend, seq_loop_pend, seq_ovr;
   wire [3:0] seq_delay;
   wire [3:0] seq_loops;
   wire frame_end = (phase == RUN) && last_col && last_row && !abort_req;
   wire csr_we = wr_en && (wr_addr[4:3] == 2'b11);
   tplan_seq_ctrl u_seq (
       .clk(clk),
       .rst_n(rst_n),
       .en(en),
       .phase_i(phase),
       .start_req(start_req),
       .abort_req(abort_req),
       .frame_end(frame_end),
       .csr_we(csr_we),
       .csr_addr(wr_addr[2:0]),
       .csr_wdata(wr_data[7:0]),
       .start_ack(seq_start_ack),
       .fire(seq_fire),
       .rearm(seq_rearm),
       .busy(seq_busy),
       .pend_o(seq_pend),
       .loop_pend_o(seq_loop_pend),
       .ovr_o(seq_ovr),
       .delay_o(seq_delay),
       .loops_o(seq_loops)
   );

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                       if (seq_start_ack) begin
                           start_seen <= 1'b1;
                           col_cnt <= 64'd0;
                           row_cnt <= 64'd0;
                       end
                       if (seq_fire)
                           phase <= RUN;
                    end
                    RUN: begin
                        pix_row <= font_row(cur_char, row_cnt[2:0]);
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                done <= 1'b1;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                    end
                    FIN: begin
                       if (arm_req || seq_rearm) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_seq_busy = seq_busy;
   assign o_seq_stat = {seq_pend, seq_loop_pend, seq_ovr, seq_loops, seq_delay};

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

module toast_spi_cs_keeper (
   input  wire        clk,
   input  wire        rst,
   input  wire        en,
   input  wire        hold_done,
   input  wire        gap_end,
   input  wire        launch,
   input  wire        q_empty,
   input  wire [4:0]  head_slv,
   input  wire [4:0]  sel,
   output wire        keep,
   output wire        merge,
   output wire [23:0] rel_mask,
   output wire        held_o,
   output wire [2:0]  burst_o,
   output wire [2:0]  peak_o,
   output wire [7:0]  merge_cnt_o,
   output wire [7:0]  brk_cnt_o,
   output wire [23:0] merged_mask_o
);
   localparam [2:0] MAX_BURST = 3'd4;

   reg        held        = 1'b0;
   reg [2:0]  burst       = 3'd0;
   reg [2:0]  peak        = 3'd0;
   reg [7:0]  merge_cnt   = 8'd0;
   reg [7:0]  brk_cnt     = 8'd0;
   reg [23:0] merged_mask = 24'd0;

   // CS is carried into the gap when the burst has room and the next frame
   // targets the same slave, or the queue is empty (linger for a follow-up).
   wire       same_slv = (head_slv == sel);
   wire       room     = (burst < MAX_BURST);
   wire       cont     = held && launch && same_slv;
   wire       broken   = held && gap_end && !cont;
   wire [2:0] burst_nx = cont ? burst + 3'd1 : 3'd0;

   assign keep          = hold_done && room && (q_empty || same_slv);
   assign merge         = held && same_slv;
   assign rel_mask      = held ? (24'd1 << sel) : 24'd0;
   assign held_o        = held;
   assign burst_o       = burst;
   assign peak_o        = peak;
   assign merge_cnt_o   = merge_cnt;
   assign brk_cnt_o     = brk_cnt;
   assign merged_mask_o = merged_mask;

   always @(posedge clk) begin
       if (rst) begin
           held        <= 1'b0;
           burst       <= 3'd0;
           peak        <= 3'd0;
           merge_cnt   <= 8'd0;
           brk_cnt     <= 8'd0;
           merged_mask <= 24'd0;
       end else if (en) begin
           if (hold_done)
               held <= keep;
           else if (gap_end)
               held <= 1'b0;

           if (launch) begin
               burst <= burst_nx;
               if (burst_nx > peak)
                   peak <= burst_nx;
           end

           if (cont) begin
               if (merge_cnt != 8'hFF)
                   merge_cnt <= merge_cnt + 8'd1;
               merged_mask <= merged_mask | (24'd1 << sel);
           end

           if (broken && brk_cnt != 8'hFF)
               brk_cnt <= brk_cnt + 8'd1;
       end
   end
endmodule

module toast_spi_cs_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         push,
    input  wire [4:0]   push_slv,
    input  wire [127:0] push_data,
    input  wire [7:0]   cfg_setup,
    input  wire [7:0]   cfg_hold,
    input  wire [7:0]   cfg_gap,
    output wire [23:0]  cs_n,
    output wire         mosi,
    output wire         busy,
   output wire         full,
   output wire         cs_held,
   output wire [2:0]   cs_burst,
   output wire [2:0]   cs_peak_burst,
   output wire [7:0]   cs_merge_count,
   output wire [7:0]   cs_break_count,
   output wire [23:0]  cs_merged_slaves
);
    localparam [2:0] ST_IDLE  = 3'd0;
    localparam [2:0] ST_SETUP = 3'd1;
    localparam [2:0] ST_XFER  = 3'd2;
    localparam [2:0] ST_HOLD  = 3'd3;
    localparam [2:0] ST_GAP   = 3'd4;

    reg [2:0]   st     = ST_IDLE;
    reg [4:0]   sel    = 5'd0;
    reg [7:0]   dly    = 8'd0;
    reg [6:0]   bitcnt = 7'd0;
    reg [23:0]  cs_vec = 24'd0;
    reg [127:0] shreg  = 128'd0;

    reg [4:0]   q_slv [0:23];
    reg [127:0] q_dat [0:23];
    reg [4:0]   wptr  = 5'd0;
    reg [4:0]   rptr  = 5'd0;
    reg [4:0]   count = 5'd0;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) begin
            q_slv[i] = 5'd0;
            q_dat[i] = 128'd0;
        end
    end

    wire [4:0]   head_raw = q_slv[rptr];
    wire [4:0]   head_slv = (head_raw < 5'd24) ? head_raw : 5'd0;
    wire [127:0] head_dat = q_dat[rptr];

    wire can_pop = (count != 5'd0) &&
                   ((st == ST_IDLE) || ((st == ST_GAP) && (dly == 8'd0)));
    wire do_push = push && (count < 5'd24);

    wire [4:0] wptr_nx = (wptr == 5'd23) ? 5'd0 : wptr + 5'd1;
    wire [4:0] rptr_nx = (rptr == 5'd23) ? 5'd0 : rptr + 5'd1;

   wire        hold_done = (st == ST_HOLD) && (dly == 8'd0);
   wire        gap_end   = (st == ST_GAP) && (dly == 8'd0);
   wire        cs_keep;
   wire        cs_merge;
   wire [23:0] cs_rel;
   wire        kp_held;
   wire [2:0]  kp_burst;
   wire [2:0]  kp_peak;

   toast_spi_cs_keeper u_keeper (
       .clk           (clk),
       .rst           (rst),
       .en            (en),
       .hold_done     (hold_done),
       .gap_end       (gap_end),
       .launch        (can_pop),
       .q_empty       (count == 5'd0),
       .head_slv      (head_slv),
       .sel           (sel),
       .keep          (cs_keep),
       .merge         (cs_merge),
       .rel_mask      (cs_rel),
       .held_o        (kp_held),
       .burst_o       (kp_burst),
       .peak_o        (kp_peak),
       .merge_cnt_o   (cs_merge_count),
       .brk_cnt_o     (cs_break_count),
       .merged_mask_o (cs_merged_slaves)
   );

   assign cs_held       = kp_held;
   assign cs_burst      = kp_burst;
   assign cs_peak_burst = kp_peak;

    assign cs_n = ~cs_vec;
    assign mosi = shreg[127];
    assign busy = (st != ST_IDLE);
    assign full = (count == 5'd24);

    always @(posedge clk) begin
        if (rst) begin
            st     <= ST_IDLE;
            sel    <= 5'd0;
            dly    <= 8'd0;
            bitcnt <= 7'd0;
            cs_vec <= 24'd0;
            shreg  <= 128'd0;
            wptr   <= 5'd0;
            rptr   <= 5'd0;
            count  <= 5'd0;
        end else if (en) begin
            if (do_push) begin
                q_slv[wptr] <= (push_slv < 5'd24) ? push_slv : 5'd0;
                q_dat[wptr] <= push_data;
                wptr <= wptr_nx;
            end
            if (can_pop)
                rptr <= rptr_nx;
            if (do_push && !can_pop)
                count <= count + 5'd1;
            else if (!do_push && can_pop)
                count <= count - 5'd1;

            case (st)
                ST_IDLE: begin
                    if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                    end
                end
                ST_SETUP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        bitcnt <= 7'd127;
                        st     <= ST_XFER;
                    end
                end
                ST_XFER: begin
                    shreg <= {shreg[126:0], 1'b0};
                    if (bitcnt != 7'd0)
                        bitcnt <= bitcnt - 7'd1;
                    else begin
                        dly <= cfg_hold;
                        st  <= ST_HOLD;
                    end
                end
                ST_HOLD: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                       if (!cs_keep)
                           cs_vec <= cs_vec & ~(24'd1 << sel);
                        dly    <= cfg_gap;
                        st     <= ST_GAP;
                    end
                end
                ST_GAP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else if (can_pop) begin
                        sel    <= head_slv;
                       cs_vec <= (cs_vec & ~cs_rel) | (24'd1 << head_slv);
                        shreg  <= head_dat;
                       dly    <= cs_merge ? 8'd0 : cfg_setup;
                        st     <= ST_SETUP;
                   end else begin
                       cs_vec <= cs_vec & ~cs_rel;
                       st     <= ST_IDLE;
                   end
                end
                default: st <= ST_IDLE;
            endcase
        end
    end

    // No two slave selects asserted at once while the sequencer is active
    always @(posedge clk)
        if (st != ST_IDLE)
            assert ((cs_vec & (cs_vec - 24'd1)) == 24'd0);
endmodule

module ec_jdbl_seq (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        arm,
    input  wire        start,
    input  wire        clr,
    input  wire        sel_add,
    input  wire        wr_en,
    input  wire [3:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire        o_done,
    output wire [31:0] o_acc,
output wire [31:0] o_x3,
output wire        o_cmd_ready,
output wire [3:0]  o_cmd_level,
output wire        o_cmd_ovf,
output wire [3:0]  o_pend_go,
output wire        o_busy,
output wire [7:0]  o_seq_cnt,
output wire [7:0]  o_stall_cnt,
output wire [15:0] o_dirty
);
    localparam [31:0] PRIME = 32'hFFFFFFFB;
    localparam [31:0] LAST  = 32'd11;
    localparam [1:0]  OP_MUL = 2'd0;
    localparam [1:0]  OP_ADD = 2'd1;
    localparam [1:0]  OP_SUB = 2'd2;

    reg        armed;
    reg        started;
    reg        done;
    reg        pre_clr;
    reg        mode;
    reg [31:0] step;
    reg [31:0] acc;
    reg [31:0] rf [0:15];
reg        cq_we   [0:7];
reg [3:0]  cq_addr [0:7];
reg [31:0] cq_data [0:7];
reg        cq_go   [0:7];
reg        cq_mode [0:7];
reg [3:0]  cq_wptr;
reg [3:0]  cq_rptr;
reg        cs_v;
reg        cs_we;
reg [3:0]  cs_addr;
reg [31:0] cs_data;
reg        cs_go;
reg        cs_mode;
reg        cq_ovf;
reg [7:0]  seq_cnt;
reg [7:0]  stall_cnt;
reg [15:0] rf_dirty;

    integer i;
    initial begin
        armed   = 1'b0;
        started = 1'b0;
        done    = 1'b0;
        pre_clr = 1'b1;
        mode    = 1'b0;
        step    = 32'd0;
        acc     = 32'd0;
        for (i = 0; i < 16; i = i + 1)
            rf[i] = 32'd0;
cq_wptr   = 4'd0;
cq_rptr   = 4'd0;
cs_v      = 1'b0;
cs_we     = 1'b0;
cs_addr   = 4'd0;
cs_data   = 32'd0;
cs_go     = 1'b0;
cs_mode   = 1'b0;
cq_ovf    = 1'b0;
seq_cnt   = 8'd0;
stall_cnt = 8'd0;
rf_dirty  = 16'd0;
for (i = 0; i < 8; i = i + 1) begin
cq_we[i]   = 1'b0;
cq_addr[i] = 4'd0;
cq_data[i] = 32'd0;
cq_go[i]   = 1'b0;
cq_mode[i] = 1'b0;
end
    end

    function [31:0] fadd;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            s = {1'b0, a} + {1'b0, b};
            if (s >= {1'b0, PRIME})
                s = s - {1'b0, PRIME};
            fadd = s[31:0];
        end
    endfunction

    function [31:0] fsub;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            if (a >= b)
                s = {1'b0, a} - {1'b0, b};
            else
                s = {1'b0, a} + {1'b0, PRIME} - {1'b0, b};
            fsub = s[31:0];
        end
    endfunction

    function [31:0] fmul;
        input [31:0] a;
        input [31:0] b;
        reg [63:0] p;
        reg [35:0] t;
        reg [35:0] u;
        begin
            p = {32'd0, a} * {32'd0, b};
            t = {4'd0, p[31:0]} + {4'd0, p[63:32]} * 36'd5;
            u = {4'd0, t[31:0]} + {32'd0, t[35:32]} * 36'd5;
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            fmul = u[31:0];
        end
    endfunction

    reg [3:0] ra, rb, rd;
    reg [1:0] opc;
    always @(*) begin
        ra  = 4'd0;
        rb  = 4'd0;
        rd  = 4'd6;
        opc = OP_MUL;
        case (step)
            32'd1:  begin ra = 4'd1;  rb = mode ? 4'd4 : 4'd1; rd = 4'd6;  opc = OP_MUL; end
            32'd2:  begin ra = 4'd0;  rb = 4'd6;  rd = 4'd7;  opc = OP_MUL; end
            32'd3:  begin ra = 4'd0;  rb = mode ? 4'd3 : 4'd0; rd = 4'd8;  opc = OP_MUL; end
            32'd4:  begin ra = 4'd8;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd5:  begin ra = 4'd9;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd6:  begin ra = 4'd9;  rb = 4'd9;  rd = 4'd10; opc = OP_MUL; end
            32'd7:  begin ra = 4'd7;  rb = 4'd7;  rd = 4'd11; opc = OP_ADD; end
            32'd8:  begin ra = 4'd10; rb = 4'd11; rd = 4'd12; opc = OP_SUB; end
            32'd9:  begin ra = mode ? 4'd2 : 4'd1; rb = mode ? 4'd5 : 4'd2; rd = 4'd13; opc = OP_MUL; end
            32'd10: begin ra = 4'd6;  rb = 4'd6;  rd = 4'd15; opc = OP_MUL; end
            default: begin ra = 4'd0; rb = 4'd0; rd = 4'd6; opc = OP_MUL; end
        endcase
    end

    wire [31:0] opa = rf[ra];
    wire [31:0] opb = rf[rb];
    reg  [31:0] res;
    always @(*) begin
        case (opc)
            OP_MUL:  res = fmul(opa, opb);
            OP_ADD:  res = fadd(opa, opb);
            OP_SUB:  res = fsub(opa, opb);
            default: res = opa;
        endcase
    end

    wire [31:0] y3 = fsub(fmul(rf[9], fsub(rf[7], rf[12])), rf[15]);
    wire [31:0] z3 = fadd(rf[13], rf[13]);
wire        cq_empty  = (cq_wptr == cq_rptr);
wire        cq_full   = (cq_wptr[3] != cq_rptr[3]) && (cq_wptr[2:0] == cq_rptr[2:0]);
wire [3:0]  cq_level  = cq_wptr - cq_rptr;
wire [2:0]  cq_widx   = cq_wptr[2:0];
wire [2:0]  cq_ridx   = cq_rptr[2:0];
wire        cq_flush  = en && clr;
wire        cmd_go    = start && armed && !cq_flush;
wire        cmd_req   = wr_en || cmd_go;
wire        cq_push   = cmd_req && !cq_full;
wire        cs_fire   = en && !clr && cs_v && (step == 32'd0);
wire        cs_launch = cs_fire && cs_go;
wire        cq_pop    = en && !clr && !cq_empty && (!cs_v || cs_fire);
reg [3:0] cq_pend_go;
reg [2:0] cq_off;
integer   j;
always @(*) begin
cq_pend_go = 4'd0;
for (j = 0; j < 8; j = j + 1) begin
cq_off = j - cq_ridx;
if (cq_go[j] && ({1'b0, cq_off} < cq_level))
cq_pend_go = cq_pend_go + 4'd1;
end
end

    always @(posedge clk) begin
        if (rst) begin
            armed   <= 1'b0;
            started <= 1'b0;
            done    <= 1'b0;
            pre_clr <= 1'b1;
            mode    <= 1'b0;
            step    <= 32'd0;
            acc     <= 32'd0;
cq_wptr   <= 4'd0;
cq_rptr   <= 4'd0;
cs_v      <= 1'b0;
cs_we     <= 1'b0;
cs_addr   <= 4'd0;
cs_data   <= 32'd0;
cs_go     <= 1'b0;
cs_mode   <= 1'b0;
cq_ovf    <= 1'b0;
seq_cnt   <= 8'd0;
stall_cnt <= 8'd0;
rf_dirty  <= 16'd0;
for (i = 0; i < 8; i = i + 1) begin
cq_we[i]   <= 1'b0;
cq_addr[i] <= 4'd0;
cq_data[i] <= 32'd0;
cq_go[i]   <= 1'b0;
cq_mode[i] <= 1'b0;
end
end else begin
if (en) begin
            if (clr) begin
                armed   <= 1'b0;
                started <= 1'b0;
                done    <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (arm)
                    armed <= 1'b1;
if (cs_launch)
                    started <= 1'b1;
                if (step == LAST)
                    done <= 1'b1;
            end
            if (step == 32'd0) begin
if (cs_launch) begin
                    step <= 32'd1;
mode <= cs_mode;
                end
            end else if (step == LAST) begin
                step <= 32'd0;
                acc  <= y3;
            end else begin
                step <= step + 32'd1;
                acc  <= res;
            end
        end
if (cq_push) begin
cq_we[cq_widx]   <= wr_en;
cq_addr[cq_widx] <= wr_addr;
cq_data[cq_widx] <= wr_data;
cq_go[cq_widx]   <= cmd_go;
cq_mode[cq_widx] <= sel_add;
cq_wptr          <= cq_wptr + 4'd1;
end
if (cq_flush) begin
cq_rptr   <= cq_wptr;
cs_v      <= 1'b0;
cq_ovf    <= 1'b0;
stall_cnt <= 8'd0;
end else begin
if (cq_pop) begin
cs_v    <= 1'b1;
cs_we   <= cq_we[cq_ridx];
cs_addr <= cq_addr[cq_ridx];
cs_data <= cq_data[cq_ridx];
cs_go   <= cq_go[cq_ridx];
cs_mode <= cq_mode[cq_ridx];
cq_rptr <= cq_rptr + 4'd1;
end else if (cs_fire) begin
cs_v <= 1'b0;
end
if (cs_fire) begin
if (cs_go)
rf_dirty <= 16'd0;
else if (cs_we)
rf_dirty[cs_addr] <= 1'b1;
end
if (cs_launch)
seq_cnt <= seq_cnt + 8'd1;
if (cs_v && !cs_fire && stall_cnt != 8'hFF)
stall_cnt <= stall_cnt + 8'd1;
end
if (cmd_req && cq_full)
cq_ovf <= 1'b1;
end
    end

    always @(posedge clk) begin
        if (!rst && en) begin
            if (step == 32'd0) begin
if (cs_fire && cs_we)
rf[cs_addr] <= cs_data;
            end else if (step == LAST) begin
                rf[0] <= rf[12];
                rf[1] <= y3;
                rf[2] <= z3;
            end else begin
                rf[rd] <= res;
            end
        end
    end

    assign o_done = done;
    assign o_acc  = acc;
    assign o_x3   = rf[0];
assign o_cmd_ready = !cq_full;
assign o_cmd_level = cq_level;
assign o_cmd_ovf   = cq_ovf;
assign o_pend_go   = cq_pend_go + {3'd0, cs_v && cs_go};
assign o_busy      = (step != 32'd0) || cs_v || !cq_empty;
assign o_seq_cnt   = seq_cnt;
assign o_stall_cnt = stall_cnt;
assign o_dirty     = rf_dirty;

    always @(*)
        if (pre_clr && done)
            assert (started && armed);
endmodule

module benes_lane_shuffler (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         in_valid,
    input  wire [511:0] in_data,
    input  wire [7:0]   in_sel,
    input  wire         cfg_we,
    input  wire [7:0]   cfg_addr,
    input  wire [19:0]  cfg_bits,
    output wire         out_valid,
    output wire [511:0] out_data,
    output wire [63:0]  o_beats_done
,
    output wire [63:0] inflight_o,
    output wire [4:0] valid_pipe_o
);
    reg [19:0]  cfg_tab   [0:255];
    reg [3:0]   stage_cfg [0:4];
    reg [19:0]  cfg_pipe  [0:3];
    reg [511:0] data_pipe [0:4];
    reg [4:0]   valid_pipe;
    reg [63:0]  inflight;
    reg [63:0]  beats_done;
    reg         armed;

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) cfg_tab[i] = 20'd0;
        for (i = 0; i < 5; i = i + 1) begin
            stage_cfg[i] = 4'd0;
            data_pipe[i] = 512'd0;
        end
        for (i = 0; i < 4; i = i + 1) cfg_pipe[i] = 20'd0;
        valid_pipe = 5'd0;
        inflight   = 64'd0;
        beats_done = 64'd0;
        armed      = 1'b0;
    end

    // butterfly stage, pair distance 4
    function [511:0] sw4;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw4[0*64 +: 64] = c[0] ? d[4*64 +: 64] : d[0*64 +: 64];
            sw4[4*64 +: 64] = c[0] ? d[0*64 +: 64] : d[4*64 +: 64];
            sw4[1*64 +: 64] = c[1] ? d[5*64 +: 64] : d[1*64 +: 64];
            sw4[5*64 +: 64] = c[1] ? d[1*64 +: 64] : d[5*64 +: 64];
            sw4[2*64 +: 64] = c[2] ? d[6*64 +: 64] : d[2*64 +: 64];
            sw4[6*64 +: 64] = c[2] ? d[2*64 +: 64] : d[6*64 +: 64];
            sw4[3*64 +: 64] = c[3] ? d[7*64 +: 64] : d[3*64 +: 64];
            sw4[7*64 +: 64] = c[3] ? d[3*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 2
    function [511:0] sw2;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw2[0*64 +: 64] = c[0] ? d[2*64 +: 64] : d[0*64 +: 64];
            sw2[2*64 +: 64] = c[0] ? d[0*64 +: 64] : d[2*64 +: 64];
            sw2[1*64 +: 64] = c[1] ? d[3*64 +: 64] : d[1*64 +: 64];
            sw2[3*64 +: 64] = c[1] ? d[1*64 +: 64] : d[3*64 +: 64];
            sw2[4*64 +: 64] = c[2] ? d[6*64 +: 64] : d[4*64 +: 64];
            sw2[6*64 +: 64] = c[2] ? d[4*64 +: 64] : d[6*64 +: 64];
            sw2[5*64 +: 64] = c[3] ? d[7*64 +: 64] : d[5*64 +: 64];
            sw2[7*64 +: 64] = c[3] ? d[5*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 1 (middle stage)
    function [511:0] sw1;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw1[0*64 +: 64] = c[0] ? d[1*64 +: 64] : d[0*64 +: 64];
            sw1[1*64 +: 64] = c[0] ? d[0*64 +: 64] : d[1*64 +: 64];
            sw1[2*64 +: 64] = c[1] ? d[3*64 +: 64] : d[2*64 +: 64];
            sw1[3*64 +: 64] = c[1] ? d[2*64 +: 64] : d[3*64 +: 64];
            sw1[4*64 +: 64] = c[2] ? d[5*64 +: 64] : d[4*64 +: 64];
            sw1[5*64 +: 64] = c[2] ? d[4*64 +: 64] : d[5*64 +: 64];
            sw1[6*64 +: 64] = c[3] ? d[7*64 +: 64] : d[6*64 +: 64];
            sw1[7*64 +: 64] = c[3] ? d[6*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    wire [19:0] cfg0 = cfg_tab[in_sel];

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < 256; i = i + 1) cfg_tab[i] <= 20'd0;
            for (i = 0; i < 5; i = i + 1) begin
                stage_cfg[i] <= 4'd0;
                data_pipe[i] <= 512'd0;
            end
            for (i = 0; i < 4; i = i + 1) cfg_pipe[i] <= 20'd0;
            valid_pipe <= 5'd0;
            inflight   <= 64'd0;
            beats_done <= 64'd0;
            armed      <= 1'b0;
        end else if (en) begin
            if (cfg_we) begin
                cfg_tab[cfg_addr] <= cfg_bits;
                armed <= 1'b1;
            end
            data_pipe[0] <= sw4(in_data, cfg0[3:0]);
            stage_cfg[0] <= cfg0[3:0];
            cfg_pipe[0]  <= cfg0;
            data_pipe[1] <= sw2(data_pipe[0], cfg_pipe[0][7:4]);
            stage_cfg[1] <= cfg_pipe[0][7:4];
            cfg_pipe[1]  <= cfg_pipe[0];
            data_pipe[2] <= sw1(data_pipe[1], cfg_pipe[1][11:8]);
            stage_cfg[2] <= cfg_pipe[1][11:8];
            cfg_pipe[2]  <= cfg_pipe[1];
            data_pipe[3] <= sw2(data_pipe[2], cfg_pipe[2][15:12]);
            stage_cfg[3] <= cfg_pipe[2][15:12];
            cfg_pipe[3]  <= cfg_pipe[2];
            data_pipe[4] <= sw4(data_pipe[3], cfg_pipe[3][19:16]);
            stage_cfg[4] <= cfg_pipe[3][19:16];
            valid_pipe <= {valid_pipe[3:0], in_valid};
            inflight   <= inflight + {63'd0, in_valid} - {63'd0, valid_pipe[4]};
            if (valid_pipe[4])
                beats_done <= beats_done + 64'd1;
        end
    end

    assign out_valid    = valid_pipe[4];
    assign out_data     = data_pipe[4];
    assign o_beats_done = beats_done;

    always @(posedge clk)
        if (armed)
            assert (inflight <= 64'd5);
    assign inflight_o = inflight;
    assign valid_pipe_o = valid_pipe;
endmodule

module lvds_port_perfmon (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         valid,
    input  wire         ready,
    input  wire [127:0] data,
    input  wire         win_start,
    output wire [31:0]  o_txn_cnt,
    output wire [35:0]  o_byte_cnt,
    output wire [31:0]  o_stall_cnt,
    output wire [47:0]  o_lat_cum,
    output wire [15:0]  o_win_cnt
,
    output wire [35:0] byte_cnt_o,
    output wire hs_d_o,
    output wire seen_txn_o,
    output wire [31:0] txn_cnt_o
);
    wire hs    = en & valid & ready;
    wire stall = en & valid & ~ready;

    reg [31:0] txn_cnt   = 32'd0;
    reg        hs_d      = 1'b0;
    reg [35:0] byte_cnt  = 36'd0;
    reg [31:0] stall_cnt = 32'd0;
    reg [15:0] lat_cur   = 16'd0;
    reg [47:0] lat_cum   = 48'd0;
    reg [15:0] win_cnt   = 16'd0;
    reg        armed     = 1'b0;
    reg        seen_txn  = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            txn_cnt   <= 32'd0;
            hs_d      <= 1'b0;
            byte_cnt  <= 36'd0;
            stall_cnt <= 32'd0;
            lat_cur   <= 16'd0;
            lat_cum   <= 48'd0;
            win_cnt   <= 16'd0;
            armed     <= 1'b0;
            seen_txn  <= 1'b0;
        end else if (en) begin
            hs_d <= hs;
            if (hs) begin
                txn_cnt  <= txn_cnt + 32'd1;
                seen_txn <= 1'b1;
                lat_cum  <= lat_cum + {32'd0, lat_cur};
                lat_cur  <= 16'd0;
            end else if (valid) begin
                lat_cur  <= lat_cur + 16'd1;
            end
            if (hs_d)
                byte_cnt <= byte_cnt + 36'd16;
            if (stall)
                stall_cnt <= stall_cnt + 32'd1;
            if (win_start) begin
                win_cnt <= 16'd0;
                armed   <= 1'b1;
            end else begin
                win_cnt <= win_cnt + 16'd1;
            end
        end
    end

    assign o_txn_cnt   = txn_cnt;
    assign o_byte_cnt  = byte_cnt;
    assign o_stall_cnt = stall_cnt;
    assign o_lat_cum   = lat_cum;
    assign o_win_cnt   = win_cnt;

    always @(posedge clk)
        if (armed && byte_cnt != 36'd0)
            assert (seen_txn);
    assign byte_cnt_o = byte_cnt;
    assign hs_d_o = hs_d;
    assign seen_txn_o = seen_txn;
    assign txn_cnt_o = txn_cnt;
endmodule

module benes_perfmon_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         in_valid,
    input  wire [511:0] in_data,
    input  wire [7:0]   in_sel,
    input  wire         cfg_we,
    input  wire [7:0]   cfg_addr,
    input  wire [19:0]  cfg_bits,
    input  wire         ready,
    input  wire         win_start,
    output wire [63:0]  o_beats_done,
    output wire         o_port_valid,
    output wire [127:0] o_port_data,
    output wire [31:0]  o_cap_cnt,
    output wire [31:0]  o_drop_cnt,
    output wire [31:0]  o_txn_cnt,
    output wire [35:0]  o_byte_cnt,
    output wire [31:0]  o_stall_cnt,
    output wire [47:0]  o_lat_cum,
    output wire [15:0]  o_win_cnt
);
    wire         a_out_valid;
    wire [511:0] a_out_data;
    wire [63:0]  a_inflight;
    wire [4:0]   a_valid_pipe;

    wire [35:0]  b_byte_cnt;
    wire         b_hs_d;
    wire         b_seen_txn;
    wire [31:0]  b_txn_cnt;

    reg          g_valid  = 1'b0;
    reg  [127:0] g_data   = 128'd0;
    reg  [31:0]  cap_cnt  = 32'd0;
    reg  [31:0]  drop_cnt = 32'd0;

    benes_lane_shuffler u_shuf (
        .clk(clk),
        .rst(rst),
        .en(en),
        .in_valid(in_valid),
        .in_data(in_data),
        .in_sel(in_sel),
        .cfg_we(cfg_we),
        .cfg_addr(cfg_addr),
        .cfg_bits(cfg_bits),
        .out_valid(a_out_valid),
        .out_data(a_out_data),
        .o_beats_done(o_beats_done),
        .inflight_o(a_inflight),
        .valid_pipe_o(a_valid_pipe)
    );

    wire slot_free = !g_valid || ready;

    always @(posedge clk) begin
        if (rst) begin
            g_valid  <= 1'b0;
            g_data   <= 128'd0;
            cap_cnt  <= 32'd0;
            drop_cnt <= 32'd0;
        end else if (en) begin
            if (slot_free) begin
                g_valid <= a_out_valid;
                if (a_out_valid) begin
                    g_data  <= a_out_data[127:0];
                    cap_cnt <= cap_cnt + 32'd1;
                end
            end else if (a_out_valid) begin
                drop_cnt <= drop_cnt + 32'd1;
            end
        end
    end

    lvds_port_perfmon u_mon (
        .clk(clk),
        .rst(rst),
        .en(en),
        .valid(g_valid),
        .ready(ready),
        .data(g_data),
        .win_start(win_start),
        .o_txn_cnt(o_txn_cnt),
        .o_byte_cnt(o_byte_cnt),
        .o_stall_cnt(o_stall_cnt),
        .o_lat_cum(o_lat_cum),
        .o_win_cnt(o_win_cnt),
        .byte_cnt_o(b_byte_cnt),
        .hs_d_o(b_hs_d),
        .seen_txn_o(b_seen_txn),
        .txn_cnt_o(b_txn_cnt)
    );

    assign o_port_valid = g_valid;
    assign o_port_data  = g_data;
    assign o_cap_cnt    = cap_cnt;
    assign o_drop_cnt   = drop_cnt;

    always @(posedge clk)
        if (!g_valid)
            assert (cap_cnt == b_txn_cnt);
endmodule

