                txn_cnt  <= txn_cnt + 32'd1;
                seen_txn <= 1'b1;
                lat_cum  <= lat_cum + {32'd0, lat_cur};
                lat_cur  <= 16'd0;
            end else if (valid) begin
                lat_cur  <= lat_cur + 16'd1;
            end
            if (hs_d)
                byte_cnt <= byte_cnt + 36'd16;
            if (stall)
                stall_cnt <= stall_cnt + 32'd1;
            if (win_start) begin
                win_cnt <= 16'd0;
                armed   <= 1'b1;
            end else begin
                win_cnt <= win_cnt + 16'd1;
            end
        end
    end

    assign o_txn_cnt   = txn_cnt;
    assign o_byte_cnt  = byte_cnt;
    assign o_stall_cnt = stall_cnt;
    assign o_lat_cum   = lat_cum;
    assign o_win_cnt   = win_cnt;

    always @(posedge clk)
        if (armed && byte_cnt != 36'd0)
            assert (seen_txn);
    assign byte_cnt_o = byte_cnt;
    assign hs_d_o = hs_d;
    assign seen_txn_o = seen_txn;
    assign txn_cnt_o = txn_cnt;
endmodule

module benes_perfmon_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         in_valid,
    input  wire [511:0] in_data,
    input  wire [7:0]   in_sel,
    input  wire         cfg_we,
    input  wire [7:0]   cfg_addr,
    input  wire [19:0]  cfg_bits,
    input  wire         ready,
    input  wire         win_start,
    output wire [63:0]  o_beats_done,
    output wire         o_port_valid,
    output wire [127:0] o_port_data,
    output wire [31:0]  o_cap_cnt,
    output wire [31:0]  o_drop_cnt,
    output wire [31:0]  o_txn_cnt,
    output wire [35:0]  o_byte_cnt,
    output wire [31:0]  o_stall_cnt,
    output wire [47:0]  o_lat_cum,
   output wire [15:0]  o_win_cnt,
   output wire [31:0]  o_dbg_word,
   output wire [7:0]   o_dbg_flags
);
    wire         a_out_valid;
    wire [511:0] a_out_data;
    wire [63:0]  a_inflight;
    wire [4:0]   a_valid_pipe;

    wire [35:0]  b_byte_cnt;
    wire         b_hs_d;
    wire         b_seen_txn;
    wire [31:0]  b_txn_cnt;

    reg          g_valid  = 1'b0;
    reg  [127:0] g_data   = 128'd0;
    reg  [31:0]  cap_cnt  = 32'd0;
    reg  [31:0]  drop_cnt = 32'd0;

   // debug / status register bank
   reg  [31:0]  dbg_cycle;
   reg  [23:0]  dbg_wdog;
   reg  [23:0]  dbg_wdog_lim;
   reg          dbg_wdog_trip;
   reg  [15:0]  dbg_stall_run;
   reg  [15:0]  dbg_stall_max;
   reg  [15:0]  dbg_cfg_wr;
   reg  [15:0]  dbg_drop_ev;
   reg  [31:0]  dbg_sig;
   reg  [3:0]   dbg_err_code;
   reg  [31:0]  dbg_err_time;
   reg          dbg_err_valid;
   reg  [7:0]   dbg_err_cnt;
   reg  [7:0]   dbg_err_flags;
   reg  [7:0]   dbg_sel_q0;
   reg  [7:0]   dbg_sel_q1;
   reg  [7:0]   dbg_sel_q2;
   reg  [7:0]   dbg_sel_q3;
   reg  [2:0]   dbg_ptr;
   reg  [31:0]  dbg_word;

   initial begin
       dbg_cycle     = 32'd0;
       dbg_wdog      = 24'd0;
       dbg_wdog_lim  = 24'd4096;
       dbg_wdog_trip = 1'b0;
       dbg_stall_run = 16'd0;
       dbg_stall_max = 16'd0;
       dbg_cfg_wr    = 16'd0;
       dbg_drop_ev   = 16'd0;
       dbg_sig       = 32'd0;
       dbg_err_code  = 4'd0;
       dbg_err_time  = 32'd0;
       dbg_err_valid = 1'b0;
       dbg_err_cnt   = 8'd0;
       dbg_err_flags = 8'd0;
       dbg_sel_q0    = 8'd0;
       dbg_sel_q1    = 8'd0;
       dbg_sel_q2    = 8'd0;
       dbg_sel_q3    = 8'd0;
       dbg_ptr       = 3'd0;
       dbg_word      = 32'd0;
   end

    benes_lane_shuffler u_shuf (
        .clk(clk),
        .rst(rst),
        .en(en),
        .in_valid(in_valid),
        .in_data(in_data),
        .in_sel(in_sel),
        .cfg_we(cfg_we),
        .cfg_addr(cfg_addr),
        .cfg_bits(cfg_bits),
        .out_valid(a_out_valid),
        .out_data(a_out_data),
        .o_beats_done(o_beats_done),
        .inflight_o(a_inflight),
        .valid_pipe_o(a_valid_pipe)
    );

    wire slot_free = !g_valid || ready;

   wire        dbg_hs      = g_valid & ready;
   wire        dbg_stall   = g_valid & ~ready;
   wire        dbg_drop    = ~slot_free & a_out_valid;
   wire        dbg_wd_hit  = (dbg_wdog == dbg_wdog_lim);
   wire        dbg_wd_ev   = dbg_stall & dbg_wd_hit & ~dbg_wdog_trip;
   wire        dbg_collide = cfg_we & in_valid & (cfg_addr == in_sel);
   wire        dbg_any_err = dbg_drop | dbg_wd_ev | dbg_collide;
   wire        dbg_clr     = cfg_we & (cfg_addr == 8'hfe);
   wire [31:0] dbg_fold    = g_data[31:0] ^ g_data[63:32] ^ g_data[95:64] ^ g_data[127:96];
   wire        dbg_fb      = dbg_sig[31] ^ dbg_sig[21] ^ dbg_sig[1] ^ dbg_sig[0];

    always @(posedge clk) begin
        if (rst) begin
            g_valid  <= 1'b0;
            g_data   <= 128'd0;
            cap_cnt  <= 32'd0;
            drop_cnt <= 32'd0;
           dbg_cycle     <= 32'd0;
           dbg_wdog      <= 24'd0;
           dbg_wdog_lim  <= 24'd4096;
           dbg_wdog_trip <= 1'b0;
           dbg_stall_run <= 16'd0;
           dbg_stall_max <= 16'd0;
           dbg_cfg_wr    <= 16'd0;
           dbg_drop_ev   <= 16'd0;
           dbg_sig       <= 32'd0;
           dbg_err_code  <= 4'd0;
           dbg_err_time  <= 32'd0;
           dbg_err_valid <= 1'b0;
           dbg_err_cnt   <= 8'd0;
           dbg_err_flags <= 8'd0;
           dbg_sel_q0    <= 8'd0;
           dbg_sel_q1    <= 8'd0;
           dbg_sel_q2    <= 8'd0;
           dbg_sel_q3    <= 8'd0;
           dbg_ptr       <= 3'd0;
           dbg_word      <= 32'd0;
        end else if (en) begin
            if (slot_free) begin
                g_valid <= a_out_valid;
                if (a_out_valid) begin
                    g_data  <= a_out_data[127:0];
                    cap_cnt <= cap_cnt + 32'd1;
                end
            end else if (a_out_valid) begin
                drop_cnt <= drop_cnt + 32'd1;
            end
           dbg_cycle <= dbg_cycle + 32'd1;
           if (dbg_hs || !g_valid)
               dbg_wdog <= 24'd0;
           else if (!dbg_wd_hit)
               dbg_wdog <= dbg_wdog + 24'd1;
           if (cfg_we && cfg_addr == 8'hff)
               dbg_wdog_lim <= {4'd0, cfg_bits};
           if (dbg_wd_ev)
               dbg_wdog_trip <= 1'b1;
           else if (dbg_clr)
               dbg_wdog_trip <= 1'b0;
           if (dbg_stall) begin
               if (dbg_stall_run != 16'hffff)
                   dbg_stall_run <= dbg_stall_run + 16'd1;
           end else begin
               dbg_stall_run <= 16'd0;
           end
           if (dbg_stall_run > dbg_stall_max)
               dbg_stall_max <= dbg_stall_run;
           if (cfg_we && dbg_cfg_wr != 16'hffff)
               dbg_cfg_wr <= dbg_cfg_wr + 16'd1;
           if (dbg_drop && dbg_drop_ev != 16'hffff)
               dbg_drop_ev <= dbg_drop_ev + 16'd1;
           if (dbg_hs)
               dbg_sig <= {dbg_sig[30:0], dbg_fb} ^ dbg_fold;
           if (in_valid) begin
               case (in_sel[7:6])
                   2'd0: dbg_sel_q0 <= dbg_sel_q0 + 8'd1;
                   2'd1: dbg_sel_q1 <= dbg_sel_q1 + 8'd1;
                   2'd2: dbg_sel_q2 <= dbg_sel_q2 + 8'd1;
                   default: dbg_sel_q3 <= dbg_sel_q3 + 8'd1;
               endcase
           end
           if (dbg_clr) begin
               dbg_err_valid <= 1'b0;
               dbg_err_code  <= 4'd0;
               dbg_err_cnt   <= 8'd0;
               dbg_err_flags <= 8'd0;
           end else if (dbg_any_err) begin
               if (dbg_err_cnt != 8'hff)
                   dbg_err_cnt <= dbg_err_cnt + 8'd1;
               dbg_err_flags <= dbg_err_flags | {5'd0, dbg_collide, dbg_wd_ev, dbg_drop};
               if (!dbg_err_valid) begin
                   dbg_err_valid <= 1'b1;
                   dbg_err_time  <= dbg_cycle;
                   dbg_err_code  <= dbg_drop ? 4'd1 : (dbg_wd_ev ? 4'd2 : 4'd3);
               end
           end
           if (win_start)
               dbg_ptr <= dbg_ptr + 3'd1;
           case (dbg_ptr)
               3'd0: dbg_word <= dbg_cycle;
               3'd1: dbg_word <= {dbg_stall_max, dbg_cfg_wr};
               3'd2: dbg_word <= dbg_sig;
               3'd3: dbg_word <= {dbg_err_valid, dbg_err_code[2:0], 4'd0, dbg_err_cnt, dbg_drop_ev};
               3'd4: dbg_word <= dbg_err_time;
               3'd5: dbg_word <= {dbg_sel_q3, dbg_sel_q2, dbg_sel_q1, dbg_sel_q0};
               3'd6: dbg_word <= {7'd0, dbg_wdog_trip, dbg_wdog};
               default: dbg_word <= {dbg_err_flags, dbg_wdog_lim};
           endcase
        end
    end

    lvds_port_perfmon u_mon (
        .clk(clk),
        .rst(rst),
        .en(en),
        .valid(g_valid),
        .ready(ready),
        .data(g_data),
        .win_start(win_start),
        .o_txn_cnt(o_txn_cnt),
        .o_byte_cnt(o_byte_cnt),
        .o_stall_cnt(o_stall_cnt),
        .o_lat_cum(o_lat_cum),
        .o_win_cnt(o_win_cnt),
        .byte_cnt_o(b_byte_cnt),
        .hs_d_o(b_hs_d),
        .seen_txn_o(b_seen_txn),
        .txn_cnt_o(b_txn_cnt)
    );

    assign o_port_valid = g_valid;
    assign o_port_data  = g_data;
    assign o_cap_cnt    = cap_cnt;
    assign o_drop_cnt   = drop_cnt;
   assign o_dbg_word   = dbg_word;
   assign o_dbg_flags  = dbg_err_flags;

    always @(posedge clk)
        if (!g_valid)
            assert (cap_cnt == b_txn_cnt);
endmodule

module tplan_launch_sched (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire [1:0] phase_i,
   input wire fire_i,
   input wire restart_i,
   input wire abort_req,
   input wire frame_end_i,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire launch_o,
   output wire hold_o,
   output wire tok_o,
   output wire late_o,
   output wire [2:0] slot_o,
   output wire [2:0] last_slot_o,
   output wire [3:0] wait_max_o,
   output wire [3:0] skip_o,
   output wire [3:0] gap_o,
   output wire [6:0] hist_o,
   output wire [3:0] hist_vld_o
);
   reg [3:0] cfg_div;
   reg       cfg_align;
   reg       cfg_gap_en;
   reg       cfg_force;
   reg [3:0] cfg_dl;
   reg [3:0] cfg_gap;
   reg [1:0] cfg_hsel;
   reg [7:0] cfg_mask;
   reg [3:0] div_cnt;
   reg [2:0] slot_idx;
   reg       tok;
   reg [3:0] wait_cnt;
   reg [3:0] wait_max;
   reg       late;
   reg [3:0] skip_cnt;
   reg [3:0] gap_cnt;
   reg [2:0] last_slot;
   reg [6:0] hist [0:3];
   reg [3:0] hist_vld;
   integer g;
   integer h;
   initial begin
       for (g = 0; g < 4; g = g + 1)
           hist[g] = 7'd0;
   end
   initial cfg_div = 4'd0;
   initial cfg_align = 1'b0;
   initial cfg_gap_en = 1'b0;
   initial cfg_force = 1'b0;
   initial cfg_dl = 4'd0;
   initial cfg_gap = 4'd0;
   initial cfg_hsel = 2'd0;
   initial cfg_mask = 8'd0;
   initial div_cnt = 4'd0;
   initial slot_idx = 3'd0;
   initial tok = 1'b0;
   initial wait_cnt = 4'd0;
   initial wait_max = 4'd0;
   initial late = 1'b0;
   initial skip_cnt = 4'd0;
   initial gap_cnt = 4'd0;
   initial last_slot = 3'd0;
   initial hist_vld = 4'd0;
   // slot timebase: one slot every cfg_div+1 cycles, eight slots per window
   wire armed = (phase_i == 2'd1);
   wire slot_tick = (div_cnt >= cfg_div);
   wire slot_ok = (cfg_mask == 8'd0) || cfg_mask[slot_idx];
   wire aligned = !cfg_align || (slot_tick && slot_ok);
   wire dl_hit = (cfg_dl != 4'd0) && (wait_cnt >= cfg_dl);
   wire forced = cfg_force && tok && dl_hit;
   wire want = tok || fire_i;
   assign launch_o = armed && want && !abort_req && !restart_i && (aligned || forced);
   wire skipped = tok && cfg_align && slot_tick && !slot_ok && !launch_o;
   wire stat_clr = csr_we && (csr_addr == 3'd5) && csr_wdata[2];
   assign hold_o = cfg_gap_en && (gap_cnt != 4'd0);
   assign tok_o = tok;
   assign late_o = late;
   assign slot_o = slot_idx;
   assign last_slot_o = last_slot;
   assign wait_max_o = wait_max;
   assign skip_o = skip_cnt;
   assign gap_o = gap_cnt;
   assign hist_o = hist[cfg_hsel];
   assign hist_vld_o = hist_vld;
   always @(posedge clk) begin
       if (!rst_n) begin
           cfg_div <= 4'd0;
           cfg_align <= 1'b0;
           cfg_gap_en <= 1'b0;
           cfg_force <= 1'b0;
           cfg_dl <= 4'd0;
           cfg_gap <= 4'd0;
           cfg_hsel <= 2'd0;
           cfg_mask <= 8'd0;
           div_cnt <= 4'd0;
           slot_idx <= 3'd0;
           tok <= 1'b0;
           wait_cnt <= 4'd0;
           wait_max <= 4'd0;
           late <= 1'b0;
           skip_cnt <= 4'd0;
           gap_cnt <= 4'd0;
           last_slot <= 3'd0;
           hist_vld <= 4'd0;
           for (h = 0; h < 4; h = h + 1)
               hist[h] <= 7'd0;
       end else if (en) begin
           if (csr_we) begin
               case (csr_addr)
                   3'd4: cfg_div <= csr_wdata[3:0];
                   3'd5: begin
                       cfg_align <= csr_wdata[0];
                       cfg_gap_en <= csr_wdata[1];
                       cfg_force <= csr_wdata[3];
                       cfg_dl <= csr_wdata[7:4];
                   end
                   3'd6: begin
                       cfg_gap <= csr_wdata[3:0];
                       cfg_hsel <= csr_wdata[5:4];
                   end
                   3'd7: cfg_mask <= csr_wdata;
               endcase
           end
           if (stat_clr) begin
               wait_max <= 4'd0;
               late <= 1'b0;
               skip_cnt <= 4'd0;
               hist_vld <= 4'd0;
           end
           if (slot_tick) begin
               div_cnt <= 4'd0;
               slot_idx <= slot_idx + 3'd1;
           end else begin
               div_cnt <= div_cnt + 4'd1;
           end
           if (abort_req) begin
               tok <= 1'b0;
               wait_cnt <= 4'd0;
               gap_cnt <= 4'd0;
           end else begin
               if (restart_i || !armed) begin
                   tok <= 1'b0;
                   wait_cnt <= 4'd0;
               end else if (launch_o) begin
                   tok <= 1'b0;
                   wait_cnt <= 4'd0;
                   last_slot <= slot_idx;
                   if (wait_cnt > wait_max)
                       wait_max <= wait_cnt;
                   hist[0] <= {slot_idx, wait_cnt};
                   for (h = 1; h < 4; h = h + 1)
                       hist[h] <= hist[h - 1];
                   hist_vld <= {hist_vld[2:0], 1'b1};
               end else if (fire_i) begin
                   tok <= 1'b1;
                   if (!tok)
                       wait_cnt <= 4'd0;
               end else if (tok) begin
                   if (wait_cnt != 4'hF)
                       wait_cnt <= wait_cnt + 4'd1;
               end
               if (tok && dl_hit)
                   late <= 1'b1;
               if (skipped && (skip_cnt != 4'hF))
                   skip_cnt <= skip_cnt + 4'd1;
               if (frame_end_i)
                   gap_cnt <= cfg_gap_en ? cfg_gap : 4'd0;
               else if (slot_tick && (gap_cnt != 4'd0))
                   gap_cnt <= gap_cnt - 4'd1;
           end
       end
   end
endmodule
module tplan_seq_ctrl (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire [1:0] phase_i,
   input wire start_req,
   input wire abort_req,
   input wire frame_end,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire start_ack,
   output wire fire,
   output wire rearm,
   output wire busy,
   output wire pend_o,
   output wire loop_pend_o,
   output wire ovr_o,
   output wire [3:0] delay_o,
   output wire [3:0] loops_o
);
   reg [3:0] cfg_preroll;
   reg [3:0] cfg_loops;
   reg       cfg_auto;
   reg       pend;
   reg [3:0] delay_cnt;
   reg       loop_pend;
   reg [3:0] loops_left;
   reg       ovr;
   initial cfg_preroll = 4'd0;
   initial cfg_loops = 4'd0;
   initial cfg_auto = 1'b0;
   initial pend = 1'b0;
   initial delay_cnt = 4'd0;
   initial loop_pend = 1'b0;
   initial loops_left = 4'd0;
   initial ovr = 1'b0;
   wire armed = (phase_i == 2'd1);
   wire fin = (phase_i == 2'd3);
   assign start_ack = armed && !pend && !abort_req && (start_req || loop_pend);
   assign fire = pend && (delay_cnt == 4'd0) && !abort_req;
   assign rearm = fin && loop_pend && !abort_req;
   assign busy = pend || loop_pend;
   assign pend_o = pend;
   assign loop_pend_o = loop_pend;
   assign ovr_o = ovr;
   assign delay_o = delay_cnt;
   assign loops_o = loops_left;
   always @(posedge clk) begin
       if (!rst_n) begin
           cfg_preroll <= 4'd0;
           cfg_loops <= 4'd0;
           cfg_auto <= 1'b0;
           pend <= 1'b0;
           delay_cnt <= 4'd0;
           loop_pend <= 1'b0;
           loops_left <= 4'd0;
           ovr <= 1'b0;
       end else if (en) begin
           if (csr_we) begin
               case (csr_addr)
                   3'd0: cfg_preroll <= csr_wdata[3:0];
                   3'd1: cfg_loops <= csr_wdata[3:0];
                   3'd2: cfg_auto <= csr_wdata[0];
                   3'd3: ovr <= 1'b0;
               endcase
           end
           if (start_req && pend && !abort_req)
               ovr <= 1'b1;
           if (abort_req) begin
               pend <= 1'b0;
               delay_cnt <= 4'd0;
               loop_pend <= 1'b0;
               loops_left <= 4'd0;
           end else begin
               if (start_ack) begin
                   pend <= 1'b1;
                   delay_cnt <= cfg_preroll;
                   if (loop_pend) begin
                       loop_pend <= 1'b0;
                       loops_left <= loops_left - 4'd1;
                   end else begin
                       loops_left <= cfg_loops;
                   end
               end else if (pend) begin
                   if (delay_cnt == 4'd0)
                       pend <= 1'b0;
                   else
                       delay_cnt <= delay_cnt - 4'd1;
               end
               if (frame_end && cfg_auto && (loops_left != 4'd0))
                   loop_pend <= 1'b1;
           end
       end
   end
endmodule
module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire o_seq_busy,
  output wire [10:0] o_seq_stat,
  output wire o_arm_rdy,
  output wire [20:0] o_lnch_stat,
  output wire [10:0] o_lnch_hist
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire seq_start_ack, seq_fire, seq_rearm, seq_busy;
   wire seq_pend, seq_loop_pend, seq_ovr;
   wire [3:0] seq_delay;
   wire [3:0] seq_loops;
   wire frame_end = (phase == RUN) && last_col && last_row && !abort_req;
   wire csr_we = wr_en && (wr_addr[4:3] == 2'b11);
   tplan_seq_ctrl u_seq (
       .clk(clk),
       .rst_n(rst_n),
       .en(en),
       .phase_i(phase),
       .start_req(start_req),
       .abort_req(abort_req),
       .frame_end(frame_end),
       .csr_we(csr_we),
       .csr_addr(wr_addr[2:0]),
       .csr_wdata(wr_data[7:0]),
       .start_ack(seq_start_ack),
       .fire(seq_fire),
       .rearm(seq_rearm),
       .busy(seq_busy),
       .pend_o(seq_pend),
       .loop_pend_o(seq_loop_pend),
       .ovr_o(seq_ovr),
       .delay_o(seq_delay),
       .loops_o(seq_loops)
   );
  wire lnch_go, lnch_hold, lnch_tok, lnch_late;
  wire [2:0] lnch_slot, lnch_last;
  wire [3:0] lnch_wait_max, lnch_skip, lnch_gap;
  wire [6:0] lnch_hist;
  wire [3:0] lnch_hist_vld;
  tplan_launch_sched u_lnch (
      .clk(clk),
      .rst_n(rst_n),
      .en(en),
      .phase_i(phase),
      .fire_i(seq_fire),
      .restart_i(seq_start_ack),
      .abort_req(abort_req),
      .frame_end_i(frame_end),
      .csr_we(csr_we),
      .csr_addr(wr_addr[2:0]),
      .csr_wdata(wr_data[7:0]),
      .launch_o(lnch_go),
      .hold_o(lnch_hold),
      .tok_o(lnch_tok),
      .late_o(lnch_late),
      .slot_o(lnch_slot),
      .last_slot_o(lnch_last),
      .wait_max_o(lnch_wait_max),
      .skip_o(lnch_skip),
      .gap_o(lnch_gap),
      .hist_o(lnch_hist),
      .hist_vld_o(lnch_hist_vld)
  );

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                       if (seq_start_ack) begin
                           start_seen <= 1'b1;
                           col_cnt <= 64'd0;
                           row_cnt <= 64'd0;
                       end
                      if (lnch_go)
                           phase <= RUN;
                    end
                    RUN: begin
                        pix_row <= font_row(cur_char, row_cnt[2:0]);
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                done <= 1'b1;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                    end
                    FIN: begin
                      if ((arm_req || seq_rearm) && !lnch_hold) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_seq_busy = seq_busy;
   assign o_seq_stat = {seq_pend, seq_loop_pend, seq_ovr, seq_loops, seq_delay};
  assign o_arm_rdy = !lnch_hold;
  assign o_lnch_stat = {lnch_tok, lnch_late, lnch_hold, lnch_slot, lnch_last, lnch_wait_max, lnch_skip, lnch_gap};
  assign o_lnch_hist = {lnch_hist_vld, lnch_hist};

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

// In-band control/status bank for the CS sequencer. Frames pushed with the
// reserved slave index 31 are decoded here instead of entering the queue.
module toast_spi_cs_csr (
  input  wire         clk,
  input  wire         rst,
  input  wire         en,
  input  wire         wr,
  input  wire [127:0] wdata,
  input  wire         idle,
  input  wire         launch,
  input  wire         head_vld,
  input  wire [4:0]   head_slv,
  input  wire [4:0]   sel,
  input  wire [7:0]   dflt_setup,
  output wire         head_ok,
  output wire         merge_ok,
  output wire [7:0]   setup_dly,
  output wire         man_on_o,
  output wire [4:0]   man_slv_o,
  output wire [23:0]  man_mask,
  output wire         man_upd,
  output wire [23:0]  man_nx,
  output wire         pend_o,
  output wire [4:0]   pend_slv_o,
  output wire         blocked,
  output wire [23:0]  en_mask_o,
  output wire [23:0]  mrg_mask_o,
  output wire [23:0]  ovr_vld_o,
  output wire [7:0]   man_tmr_o,
  output wire [7:0]   cmd_cnt_o,
  output wire [7:0]   blk_cnt_o,
  output wire [1:0]   err_o
);
  localparam [7:0] OP_EN_WR  = 8'h01;
  localparam [7:0] OP_EN_SET = 8'h02;
  localparam [7:0] OP_EN_CLR = 8'h03;
  localparam [7:0] OP_MRG_WR = 8'h04;
  localparam [7:0] OP_MAN_CS = 8'h05;
  localparam [7:0] OP_SETUP  = 8'h06;
  localparam [7:0] OP_CLR_ST = 8'h07;

  reg [23:0] en_mask  = 24'hFFFFFF;
  reg [23:0] mrg_mask = 24'hFFFFFF;
  reg [23:0] ovr_vld  = 24'd0;
  reg [7:0]  ovr_dly [0:23];
  reg        man_on   = 1'b0;
  reg [4:0]  man_slv  = 5'd0;
  reg        man_lim  = 1'b0;
  reg [7:0]  man_tmr  = 8'd0;
  reg        pend     = 1'b0;
  reg        pend_on  = 1'b0;
  reg [4:0]  pend_slv = 5'd0;
  reg [7:0]  pend_tmo = 8'd0;
  reg [7:0]  cmd_cnt  = 8'd0;
  reg [7:0]  blk_cnt  = 8'd0;
  reg [1:0]  err      = 2'd0;

  integer k;
  initial begin
     for (k = 0; k < 24; k = k + 1)
        ovr_dly[k] = 8'd0;
  end

  // control word: [127:120] opcode, [24] flag, [23:16] timeout,
  // [15:8] delay, [4:0] slave index; mask opcodes use [23:0]
  wire [7:0]  op       = wdata[127:120];
  wire [4:0]  arg_slv  = wdata[4:0];
  wire [7:0]  arg_dly  = wdata[15:8];
  wire [7:0]  arg_tmo  = wdata[23:16];
  wire        arg_flag = wdata[24];
  wire [23:0] arg_mask = wdata[23:0];
  wire [23:0] arg_bit  = 24'd1 << arg_slv;
  wire        slv_op   = (op == OP_MAN_CS) || (op == OP_SETUP);
  wire        op_known = (op >= OP_EN_WR) && (op <= OP_CLR_ST);
  wire        bad_idx  = slv_op && (arg_slv >= 5'd24);
  wire        bad_op   = wr && !op_known;
  wire        bad_slv  = wr && op_known && bad_idx;
  wire        good     = wr && op_known && !bad_idx;

  wire       apply   = pend && idle && !launch;
  wire       expire  = man_on && man_lim && (man_tmr == 8'd0) &&
                       idle && !launch && !pend;
  wire [7:0] ovr_sel = ovr_dly[head_slv];

  assign head_ok    = en_mask[head_slv];
  assign blocked    = head_vld && !head_ok;
  assign merge_ok   = mrg_mask[sel];
  assign setup_dly  = ovr_vld[head_slv] ? ovr_sel : dflt_setup;
  assign man_mask   = man_on ? (24'd1 << man_slv) : 24'd0;
  assign man_upd    = apply || expire;
  assign man_nx     = (apply && pend_on) ? (24'd1 << pend_slv) : 24'd0;
  assign man_on_o   = man_on;
  assign man_slv_o  = man_slv;
  assign pend_o     = pend;
  assign pend_slv_o = pend_slv;
  assign en_mask_o  = en_mask;
  assign mrg_mask_o = mrg_mask;
  assign ovr_vld_o  = ovr_vld;
  assign man_tmr_o  = man_tmr;
  assign cmd_cnt_o  = cmd_cnt;
  assign blk_cnt_o  = blk_cnt;
  assign err_o      = err;

  always @(posedge clk) begin
     if (rst) begin
        en_mask  <= 24'hFFFFFF;
        mrg_mask <= 24'hFFFFFF;
        ovr_vld  <= 24'd0;
        man_on   <= 1'b0;
        man_slv  <= 5'd0;
        man_lim  <= 1'b0;
        man_tmr  <= 8'd0;
        pend     <= 1'b0;
        pend_on  <= 1'b0;
        pend_slv <= 5'd0;
        pend_tmo <= 8'd0;
        cmd_cnt  <= 8'd0;
        blk_cnt  <= 8'd0;
        err      <= 2'd0;
        for (k = 0; k < 24; k = k + 1)
           ovr_dly[k] <= 8'd0;
     end else if (en) begin
        if (good) begin
           case (op)
              OP_EN_WR:  en_mask  <= arg_mask;
              OP_EN_SET: en_mask  <= en_mask | arg_mask;
              OP_EN_CLR: en_mask  <= en_mask & ~arg_mask;
              OP_MRG_WR: mrg_mask <= arg_mask;
              OP_SETUP: begin
                 ovr_dly[arg_slv] <= arg_dly;
                 if (arg_flag)
                    ovr_vld <= ovr_vld | arg_bit;
                 else
                    ovr_vld <= ovr_vld & ~arg_bit;
              end
              default: ;
           endcase
        end

        // a manual select request waits until the sequencer is idle
        if (good && (op == OP_MAN_CS)) begin
           pend     <= 1'b1;
           pend_on  <= arg_flag;
           pend_slv <= arg_slv;
           pend_tmo <= arg_tmo;
        end else if (apply)
           pend <= 1'b0;

        // a queued frame always takes the select lines back
        if (launch) begin
           man_on  <= 1'b0;
           man_lim <= 1'b0;
           man_tmr <= 8'd0;
        end else if (apply) begin
           man_on  <= pend_on;
           man_slv <= pend_slv;
           man_lim <= pend_on && (pend_tmo != 8'd0);
           man_tmr <= pend_tmo;
        end else if (expire) begin
           man_on  <= 1'b0;
           man_lim <= 1'b0;
        end else if (man_on && man_lim && (man_tmr != 8'd0))
           man_tmr <= man_tmr - 8'd1;

        if (good && (op == OP_CLR_ST)) begin
           cmd_cnt <= 8'd0;
           blk_cnt <= 8'd0;
           err     <= 2'd0;
        end else begin
           if (good && (cmd_cnt != 8'hFF))
              cmd_cnt <= cmd_cnt + 8'd1;
           if (blocked && (blk_cnt != 8'hFF))
              blk_cnt <= blk_cnt + 8'd1;
           err <= err | {bad_slv, bad_op};
        end
     end
  end
endmodule

module toast_spi_cs_keeper (
   input  wire        clk,
   input  wire        rst,
   input  wire        en,
   input  wire        hold_done,
   input  wire        gap_end,
   input  wire        launch,
   input  wire        q_empty,
   input  wire [4:0]  head_slv,
   input  wire [4:0]  sel,
   output wire        keep,
   output wire        merge,
   output wire [23:0] rel_mask,
   output wire        held_o,
   output wire [2:0]  burst_o,
   output wire [2:0]  peak_o,
   output wire [7:0]  merge_cnt_o,
   output wire [7:0]  brk_cnt_o,
   output wire [23:0] merged_mask_o
);
   localparam [2:0] MAX_BURST = 3'd4;

   reg        held        = 1'b0;
   reg [2:0]  burst       = 3'd0;
   reg [2:0]  peak        = 3'd0;
   reg [7:0]  merge_cnt   = 8'd0;
   reg [7:0]  brk_cnt     = 8'd0;
   reg [23:0] merged_mask = 24'd0;

   // CS is carried into the gap when the burst has room and the next frame
   // targets the same slave, or the queue is empty (linger for a follow-up).
   wire       same_slv = (head_slv == sel);
   wire       room     = (burst < MAX_BURST);
   wire       cont     = held && launch && same_slv;
   wire       broken   = held && gap_end && !cont;
   wire [2:0] burst_nx = cont ? burst + 3'd1 : 3'd0;

   assign keep          = hold_done && room && (q_empty || same_slv);
   assign merge         = held && same_slv;
   assign rel_mask      = held ? (24'd1 << sel) : 24'd0;
   assign held_o        = held;
   assign burst_o       = burst;
   assign peak_o        = peak;
   assign merge_cnt_o   = merge_cnt;
   assign brk_cnt_o     = brk_cnt;
   assign merged_mask_o = merged_mask;

   always @(posedge clk) begin
       if (rst) begin
           held        <= 1'b0;
           burst       <= 3'd0;
           peak        <= 3'd0;
           merge_cnt   <= 8'd0;
           brk_cnt     <= 8'd0;
           merged_mask <= 24'd0;
       end else if (en) begin
           if (hold_done)
               held <= keep;
           else if (gap_end)
               held <= 1'b0;

           if (launch) begin
               burst <= burst_nx;
               if (burst_nx > peak)
                   peak <= burst_nx;
           end

           if (cont) begin
               if (merge_cnt != 8'hFF)
                   merge_cnt <= merge_cnt + 8'd1;
               merged_mask <= merged_mask | (24'd1 << sel);
           end

           if (broken && brk_cnt != 8'hFF)
               brk_cnt <= brk_cnt + 8'd1;
       end
   end
endmodule

module toast_spi_cs_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         push,
    input  wire [4:0]   push_slv,
    input  wire [127:0] push_data,
    input  wire [7:0]   cfg_setup,
    input  wire [7:0]   cfg_hold,
    input  wire [7:0]   cfg_gap,
    output wire [23:0]  cs_n,
    output wire         mosi,
    output wire         busy,
   output wire         full,
   output wire         cs_held,
   output wire [2:0]   cs_burst,
   output wire [2:0]   cs_peak_burst,
   output wire [7:0]   cs_merge_count,
   output wire [7:0]   cs_break_count,
  output wire [23:0]  cs_merged_slaves,
  output wire         cs_head_blocked,
  output wire         cs_manual,
  output wire         cs_cmd_pend,
  output wire [23:0]  cs_en_mask,
  output wire [23:0]  cs_merge_mask,
  output wire [23:0]  cs_setup_ovr,
  output wire [7:0]   cs_man_timer,
  output wire [7:0]   cs_cmd_count,
  output wire [7:0]   cs_blk_count,
  output wire [1:0]   cs_cmd_err
);
    localparam [2:0] ST_IDLE  = 3'd0;
    localparam [2:0] ST_SETUP = 3'd1;
    localparam [2:0] ST_XFER  = 3'd2;
    localparam [2:0] ST_HOLD  = 3'd3;
    localparam [2:0] ST_GAP   = 3'd4;

    reg [2:0]   st     = ST_IDLE;
    reg [4:0]   sel    = 5'd0;
    reg [7:0]   dly    = 8'd0;
    reg [6:0]   bitcnt = 7'd0;
    reg [23:0]  cs_vec = 24'd0;
    reg [127:0] shreg  = 128'd0;

    reg [4:0]   q_slv [0:23];
    reg [127:0] q_dat [0:23];
    reg [4:0]   wptr  = 5'd0;
    reg [4:0]   rptr  = 5'd0;
    reg [4:0]   count = 5'd0;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) begin
            q_slv[i] = 5'd0;
            q_dat[i] = 128'd0;
        end
    end

    wire [4:0]   head_raw = q_slv[rptr];
    wire [4:0]   head_slv = (head_raw < 5'd24) ? head_raw : 5'd0;
    wire [127:0] head_dat = q_dat[rptr];

   // Frames pushed to the reserved index 31 are control words for the
   // CSR bank; a frame to a disabled slave waits at the queue head.
   wire        is_cmd = push && (push_slv == 5'd31);
   wire        csr_head_ok;
   wire        csr_merge_ok;
   wire [7:0]  csr_setup;
   wire        csr_man_on;
   wire [4:0]  csr_man_slv;
   wire [23:0] csr_man_mask;
   wire        csr_man_upd;
   wire [23:0] csr_man_nx;
   wire        csr_pend;
   wire [4:0]  csr_pend_slv;

   wire can_pop = (count != 5'd0) && csr_head_ok &&
                   ((st == ST_IDLE) || ((st == ST_GAP) && (dly == 8'd0)));
   wire do_push = push && !is_cmd && (count < 5'd24);

    wire [4:0] wptr_nx = (wptr == 5'd23) ? 5'd0 : wptr + 5'd1;
    wire [4:0] rptr_nx = (rptr == 5'd23) ? 5'd0 : rptr + 5'd1;

   wire        hold_done = (st == ST_HOLD) && (dly == 8'd0);
   wire        gap_end   = (st == ST_GAP) && (dly == 8'd0);
   wire        cs_keep;
   wire        cs_merge;
   wire [23:0] cs_rel;
   wire        kp_held;
   wire [2:0]  kp_burst;
   wire [2:0]  kp_peak;

   toast_spi_cs_keeper u_keeper (
       .clk           (clk),
       .rst           (rst),
       .en            (en),
      .hold_done     (hold_done && csr_merge_ok),
       .gap_end       (gap_end),
       .launch        (can_pop),
       .q_empty       (count == 5'd0),
       .head_slv      (head_slv),
       .sel           (sel),
       .keep          (cs_keep),
       .merge         (cs_merge),
       .rel_mask      (cs_rel),
       .held_o        (kp_held),
       .burst_o       (kp_burst),
       .peak_o        (kp_peak),
       .merge_cnt_o   (cs_merge_count),
       .brk_cnt_o     (cs_break_count),
       .merged_mask_o (cs_merged_slaves)
   );

   assign cs_held       = kp_held;
   assign cs_burst      = kp_burst;
   assign cs_peak_burst = kp_peak;

  toast_spi_cs_csr u_csr (
      .clk        (clk),
      .rst        (rst),
      .en         (en),
      .wr         (is_cmd),
      .wdata      (push_data),
      .idle       (st == ST_IDLE),
      .launch     (can_pop),
      .head_vld   (count != 5'd0),
      .head_slv   (head_slv),
      .sel        (sel),
      .dflt_setup (cfg_setup),
      .head_ok    (csr_head_ok),
      .merge_ok   (csr_merge_ok),
      .setup_dly  (csr_setup),
      .man_on_o   (csr_man_on),
      .man_slv_o  (csr_man_slv),
      .man_mask   (csr_man_mask),
      .man_upd    (csr_man_upd),
      .man_nx     (csr_man_nx),
      .pend_o     (csr_pend),
      .pend_slv_o (csr_pend_slv),
      .blocked    (cs_head_blocked),
      .en_mask_o  (cs_en_mask),
      .mrg_mask_o (cs_merge_mask),
      .ovr_vld_o  (cs_setup_ovr),
      .man_tmr_o  (cs_man_timer),
      .cmd_cnt_o  (cs_cmd_count),
      .blk_cnt_o  (cs_blk_count),
      .err_o      (cs_cmd_err)
  );

  assign cs_manual   = csr_man_on;
  assign cs_cmd_pend = csr_pend;

    assign cs_n = ~cs_vec;
    assign mosi = shreg[127];
    assign busy = (st != ST_IDLE);
    assign full = (count == 5'd24);

    always @(posedge clk) begin
        if (rst) begin
            st     <= ST_IDLE;
            sel    <= 5'd0;
            dly    <= 8'd0;
            bitcnt <= 7'd0;
            cs_vec <= 24'd0;
            shreg  <= 128'd0;
            wptr   <= 5'd0;
            rptr   <= 5'd0;
            count  <= 5'd0;
        end else if (en) begin
            if (do_push) begin
                q_slv[wptr] <= (push_slv < 5'd24) ? push_slv : 5'd0;
                q_dat[wptr] <= push_data;
                wptr <= wptr_nx;
            end
            if (can_pop)
                rptr <= rptr_nx;
            if (do_push && !can_pop)
                count <= count + 5'd1;
            else if (!do_push && can_pop)
                count <= count - 5'd1;

            case (st)
                ST_IDLE: begin
                    if (can_pop) begin
                        sel    <= head_slv;
                       cs_vec <= (cs_vec & ~csr_man_mask) | (24'd1 << head_slv);
                        shreg  <= head_dat;
                       dly    <= csr_setup;
                        st     <= ST_SETUP;
                   end else if (csr_man_upd) begin
                       cs_vec <= csr_man_nx;
                   end
                end
                ST_SETUP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        bitcnt <= 7'd127;
                        st     <= ST_XFER;
                    end
                end
                ST_XFER: begin
                    shreg <= {shreg[126:0], 1'b0};
                    if (bitcnt != 7'd0)
                        bitcnt <= bitcnt - 7'd1;
                    else begin
                        dly <= cfg_hold;
                        st  <= ST_HOLD;
                    end
                end
                ST_HOLD: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                       if (!cs_keep)
                           cs_vec <= cs_vec & ~(24'd1 << sel);
                        dly    <= cfg_gap;
                        st     <= ST_GAP;
                    end
                end
                ST_GAP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else if (can_pop) begin
                        sel    <= head_slv;
                       cs_vec <= (cs_vec & ~cs_rel) | (24'd1 << head_slv);
                        shreg  <= head_dat;
                      dly    <= cs_merge ? 8'd0 : csr_setup;
                        st     <= ST_SETUP;
                   end else begin
                       cs_vec <= cs_vec & ~cs_rel;
                       st     <= ST_IDLE;
                   end
                end
                default: st <= ST_IDLE;
            endcase
        end
    end

    // No two slave selects asserted at once while the sequencer is active
    always @(posedge clk)
        if (st != ST_IDLE)
            assert ((cs_vec & (cs_vec - 24'd1)) == 24'd0);
endmodule

module toast_spi_rec_guard #(
    parameter [7:0] MIN_REC = 8'd16
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        rel,
    input  wire [4:0]  rel_slv,
    input  wire [7:0]  cfg_rec,
    input  wire        req,
    input  wire [4:0]  req_slv,
    output wire        hit,
    output wire        stall,
    output wire [23:0] mask,
    output wire [15:0] hist_tmr,
    output wire [9:0]  hist_slv,
    output wire [15:0] stall_cyc,
    output wire [7:0]  defer_cnt
);
    // Two slots cover the worst case: a recovery window is at most 255
    // cycles and consecutive CS releases are at least 131 cycles apart.
    localparam integer DEPTH = 2;

    reg [7:0]  tmr [0:DEPTH-1];
    reg [4:0]  slv [0:DEPTH-1];
    reg        stall_q = 1'b0;
    reg [7:0]  defers  = 8'd0;
    reg [15:0] stalls  = 16'd0;

    integer k;
    initial begin
        for (k = 0; k < DEPTH; k = k + 1) begin
            tmr[k] = 8'd0;
            slv[k] = 5'd0;
        end
    end

    reg [23:0] mask_c;
    integer j;
    always @(*) begin
        mask_c = 24'd0;
        for (j = 0; j < DEPTH; j = j + 1)
            if (tmr[j] != 8'd0)
                mask_c = mask_c | (24'd1 << slv[j]);
    end

    wire [7:0] rec_len = (cfg_rec < MIN_REC) ? MIN_REC : cfg_rec;

    assign mask      = mask_c;
    assign hit       = (mask_c & (24'd1 << req_slv)) != 24'd0;
    assign stall     = req && hit;
    assign stall_cyc = stalls;
    assign defer_cnt = defers;

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : g_hist
            assign hist_tmr[8*g +: 8] = tmr[g];
            assign hist_slv[5*g +: 5] = slv[g];
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            for (k = 0; k < DEPTH; k = k + 1) begin
                tmr[k] <= 8'd0;
                slv[k] <= 5'd0;
            end
            stall_q <= 1'b0;
            defers  <= 8'd0;
            stalls  <= 16'd0;
        end else if (en) begin
            for (k = 0; k < DEPTH; k = k + 1)
                if (tmr[k] != 8'd0)
                    tmr[k] <= tmr[k] - 8'd1;
            if (rel) begin
                tmr[0] <= rec_len;
                slv[0] <= rel_slv;
                for (k = 1; k < DEPTH; k = k + 1) begin
                    tmr[k] <= (tmr[k-1] != 8'd0) ? tmr[k-1] - 8'd1 : 8'd0;
                    slv[k] <= slv[k-1];
                end
            end
            stall_q <= stall;
            if (stall && (stalls != 16'hFFFF))
                stalls <= stalls + 16'd1;
            if (stall && !stall_q && (defers != 8'hFF))
                defers <= defers + 8'd1;
        end
    end
endmodule

module toast_spi_cs_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         push,
    input  wire [4:0]   push_slv,
    input  wire [127:0] push_data,
    input  wire [7:0]   cfg_setup,
    input  wire [7:0]   cfg_hold,
    input  wire [7:0]   cfg_gap,
    output wire [23:0]  cs_n,
    output wire [23:0]  rec_mask,
    output wire         rec_stall,
    output wire [15:0]  rec_stall_cyc,
    output wire [7:0]   rec_defer,
    output wire         mosi,
    output wire         busy,
    output wire         full
);
    localparam [2:0] ST_IDLE  = 3'd0;
    localparam [2:0] ST_SETUP = 3'd1;
    localparam [2:0] ST_XFER  = 3'd2;
    localparam [2:0] ST_HOLD  = 3'd3;
    localparam [2:0] ST_GAP   = 3'd4;

    reg [2:0]   st     = ST_IDLE;
    reg [4:0]   sel    = 5'd0;
    reg [7:0]   dly    = 8'd0;
    reg [6:0]   bitcnt = 7'd0;
    reg [23:0]  cs_vec = 24'd0;
    reg [127:0] shreg  = 128'd0;

    reg [4:0]   q_slv [0:23];
    reg [127:0] q_dat [0:23];
    reg [4:0]   wptr  = 5'd0;
    reg [4:0]   rptr  = 5'd0;
    reg [4:0]   count = 5'd0;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) begin
            q_slv[i] = 5'd0;
            q_dat[i] = 128'd0;
        end
    end

    wire [4:0]   head_raw = q_slv[rptr];
    wire [4:0]   head_slv = (head_raw < 5'd24) ? head_raw : 5'd0;
    wire [127:0] head_dat = q_dat[rptr];

    // Same-slave chip-select recovery guard
    wire        rg_hit;
    wire [15:0] rg_tmr;
    wire [9:0]  rg_slv;
    wire [7:0]  rec_tmr_new = rg_tmr[7:0];
    wire [7:0]  rec_tmr_old = rg_tmr[15:8];
    wire [4:0]  rec_slv_new = rg_slv[4:0];
    wire [4:0]  rec_slv_old = rg_slv[9:5];
    wire        cs_release  = (st == ST_HOLD) && (dly == 8'd0);

    wire pop_ready = (count != 5'd0) &&
                     ((st == ST_IDLE) || ((st == ST_GAP) && (dly == 8'd0)));
    wire can_pop   = pop_ready && !rg_hit;
    wire do_push = push && (count < 5'd24);

    wire [4:0] wptr_nx = (wptr == 5'd23) ? 5'd0 : wptr + 5'd1;
    wire [4:0] rptr_nx = (rptr == 5'd23) ? 5'd0 : rptr + 5'd1;

    assign cs_n = ~cs_vec;
    assign mosi = shreg[127];
    assign busy = (st != ST_IDLE);
    assign full = (count == 5'd24);

    toast_spi_rec_guard u_recg (
        .clk       (clk),
        .rst       (rst),
        .en        (en),
        .rel       (cs_release),
        .rel_slv   (sel),
        .cfg_rec   (cfg_hold),
        .req       (pop_ready),
        .req_slv   (head_slv),
        .hit       (rg_hit),
        .stall     (rec_stall),
        .mask      (rec_mask),
        .hist_tmr  (rg_tmr),
        .hist_slv  (rg_slv),
        .stall_cyc (rec_stall_cyc),
        .defer_cnt (rec_defer)
    );

    always @(posedge clk) begin
        if (rst) begin
            st     <= ST_IDLE;
            sel    <= 5'd0;
            dly    <= 8'd0;
            bitcnt <= 7'd0;
            cs_vec <= 24'd0;
            shreg  <= 128'd0;
            wptr   <= 5'd0;
            rptr   <= 5'd0;
            count  <= 5'd0;
        end else if (en) begin
            if (do_push) begin
                q_slv[wptr] <= (push_slv < 5'd24) ? push_slv : 5'd0;
                q_dat[wptr] <= push_data;
                wptr <= wptr_nx;
            end
            if (can_pop)
                rptr <= rptr_nx;
            if (do_push && !can_pop)
                count <= count + 5'd1;
            else if (!do_push && can_pop)
                count <= count - 5'd1;

            case (st)
                ST_IDLE: begin
                    if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                    end
                end
                ST_SETUP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        bitcnt <= 7'd127;
                        st     <= ST_XFER;
                    end
                end
                ST_XFER: begin
                    shreg <= {shreg[126:0], 1'b0};
                    if (bitcnt != 7'd0)
                        bitcnt <= bitcnt - 7'd1;
                    else begin
                        dly <= cfg_hold;
                        st  <= ST_HOLD;
                    end
                end
                ST_HOLD: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        cs_vec <= cs_vec & ~(24'd1 << sel);
                        dly    <= cfg_gap;
                        st     <= ST_GAP;
                    end
                end
                ST_GAP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                    end else
                        st <= ST_IDLE;
                end
                default: st <= ST_IDLE;
            endcase
        end
    end

    // No two slave selects asserted at once while the sequencer is active
    always @(posedge clk)
        if (st != ST_IDLE)
            assert ((cs_vec & (cs_vec - 24'd1)) == 24'd0);

    // A recovery history slot is only recycled once its window has expired
    always @(posedge clk)
        if (cs_release)
            assert (rec_tmr_old == 8'd0);
endmodule

module shuf_admit_ctrl (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        req_valid,
    input  wire [7:0]  req_sel,
    input  wire        cfg_we,
    input  wire [7:0]  cfg_addr,
    input  wire [19:0] cfg_bits,
    input  wire        beat_out,
    input  wire        port_valid,
    input  wire        port_ready,
    output wire        grant,
    output wire        req_ready,
    output wire [6:0]  hold_why_o,
    output wire [7:0]  port_sel_o,
    output wire [2:0]  credit_o,
    output wire [2:0]  budget_o,
    output wire [2:0]  tag_wp_o,
    output wire [2:0]  tag_rp_o,
    output wire        drained_o,
    output wire        backoff_o,
    output wire [31:0] stat_o
);
    // control registers share the top of the shuffler table address space
    localparam [7:0] A_CLASS  = 8'hf7;
    localparam [7:0] A_DRAIN  = 8'hf8;
    localparam [7:0] A_STSEL  = 8'hf9;
    localparam [7:0] A_STARVE = 8'hfa;
    localparam [7:0] A_BOFF   = 8'hfb;
    localparam [7:0] A_RATE   = 8'hfc;
    localparam [7:0] A_BUDGET = 8'hfd;
    localparam [2:0] RST_BUDGET = 3'd4;

    // credit pool: one credit per beat inside the shuffler or the port register
    reg [2:0]  credit;
    reg [2:0]  budget;
    reg [2:0]  pend_budget;
    reg        pend;
    reg [2:0]  lwm;
    reg        drain_req;
    reg        drained;
    reg [3:0]  cls_mask;
    // selector tag ring, in shuffler order
    reg [7:0]  tag_mem [0:7];
    reg [2:0]  tag_wp;
    reg [2:0]  tag_rp;
    reg [7:0]  psel;
    reg [7:0]  drop_sel;
    reg        drop_seen;
    // token bucket rate limiter
    reg [7:0]  rate_period;
    reg [2:0]  rate_burst;
    reg [7:0]  rate_timer;
    reg [2:0]  tokens;
    // congestion backoff
    reg [7:0]  bo_thresh;
    reg [7:0]  bo_base;
    reg [7:0]  bo_run;
    reg [2:0]  bo_level;
    reg [15:0] bo_timer;
    reg        bo_active;
    reg [15:0] bo_quiet;
    // starvation guard
    reg [15:0] starve_lim;
    reg [15:0] wait_cur;
    reg [15:0] wait_max;
    // hold statistics and status readback
    reg [15:0] hold_cnt [0:6];
    reg [3:0]  st_sel;
    reg [31:0] stat;

    integer k;
    initial begin
        credit      = RST_BUDGET;
        budget      = RST_BUDGET;
        pend_budget = RST_BUDGET;
        pend        = 1'b0;
        lwm         = RST_BUDGET;
        drain_req   = 1'b0;
        drained     = 1'b0;
        cls_mask    = 4'd0;
        for (k = 0; k < 8; k = k + 1) tag_mem[k] = 8'd0;
        tag_wp      = 3'd0;
        tag_rp      = 3'd0;
        psel        = 8'd0;
        drop_sel    = 8'd0;
        drop_seen   = 1'b0;
        rate_period = 8'd0;
        rate_burst  = 3'd7;
        rate_timer  = 8'd0;
        tokens      = 3'd7;
        bo_thresh   = 8'd0;
        bo_base     = 8'd1;
        bo_run      = 8'd0;
        bo_level    = 3'd0;
        bo_timer    = 16'd0;
        bo_active   = 1'b0;
        bo_quiet    = 16'd0;
        starve_lim  = 16'd0;
        wait_cur    = 16'd0;
        wait_max    = 16'd0;
        for (k = 0; k < 7; k = k + 1) hold_cnt[k] = 16'd0;
        st_sel      = 4'd0;
        stat        = 32'd0;
    end

    wire        stall_now  = port_valid & ~port_ready;
    wire        drop_now   = beat_out & stall_now;
    wire        ret        = (port_valid & port_ready) | drop_now;
    wire        slot_take  = beat_out & (~port_valid | port_ready);
    wire        hazard     = cfg_we & (cfg_addr == req_sel);
    wire        cls_block  = cls_mask[req_sel[7:6]];
    wire        rate_on    = (rate_period != 8'd0);
    wire        starving   = (starve_lim != 16'd0) & (wait_cur >= starve_lim);
    wire        tok_ok     = ~rate_on | (tokens != 3'd0) | starving;
    wire [6:0]  hold_why   = {cls_block, drain_req, bo_active, pend, hazard, ~tok_ok, credit == 3'd0};

    assign req_ready = (hold_why == 7'd0);
    assign grant     = req_valid & req_ready;

    wire        tok_use    = grant & rate_on & (tokens != 3'd0);
    wire        rate_wrap  = (rate_timer >= rate_period);
    wire        tok_fill   = rate_wrap & (tokens < rate_burst);
    wire        grow       = (pend_budget >= budget);
    wire        can_apply  = pend & (grow | (credit >= budget - pend_budget));
    wire [2:0]  cred_apply = credit + {2'd0, ret} + pend_budget - budget;
    wire [2:0]  cred_next  = credit + {2'd0, ret} - {2'd0, grant};
    wire [15:0] bo_window  = {bo_base, 8'hff} >> (3'd7 - bo_level);
    wire [15:0] bo_qlim    = {bo_base, 8'hff};
    wire        bo_trip    = stall_now & ~bo_active & (bo_thresh != 8'd0) & (bo_run >= bo_thresh);
    wire        wr_stsel   = cfg_we & (cfg_addr == A_STSEL);

    always @(posedge clk) begin
        if (rst) begin
            credit      <= RST_BUDGET;
            budget      <= RST_BUDGET;
            pend_budget <= RST_BUDGET;
            pend        <= 1'b0;
            lwm         <= RST_BUDGET;
            drain_req   <= 1'b0;
            drained     <= 1'b0;
            cls_mask    <= 4'd0;
            for (k = 0; k < 8; k = k + 1) tag_mem[k] <= 8'd0;
            tag_wp      <= 3'd0;
            tag_rp      <= 3'd0;
            psel        <= 8'd0;
            drop_sel    <= 8'd0;
            drop_seen   <= 1'b0;
            rate_period <= 8'd0;
            rate_burst  <= 3'd7;
            rate_timer  <= 8'd0;
            tokens      <= 3'd7;
            bo_thresh   <= 8'd0;
            bo_base     <= 8'd1;
            bo_run      <= 8'd0;
            bo_level    <= 3'd0;
            bo_timer    <= 16'd0;
            bo_active   <= 1'b0;
            bo_quiet    <= 16'd0;
            starve_lim  <= 16'd0;
            wait_cur    <= 16'd0;
            wait_max    <= 16'd0;
            for (k = 0; k < 7; k = k + 1) hold_cnt[k] <= 16'd0;
            st_sel      <= 4'd0;
            stat        <= 32'd0;
        end else if (en) begin
            // credit pool; a new budget is folded in once the pool can absorb it
            if (can_apply) begin
                budget <= pend_budget;
                credit <= cred_apply;
                lwm    <= cred_apply;
                pend   <= 1'b0;
            end else begin
                credit <= cred_next;
                if (cred_next < lwm)
                    lwm <= cred_next;
            end
            if (cfg_we && cfg_addr == A_BUDGET) begin
                pend_budget <= cfg_bits[2:0];
                pend        <= 1'b1;
            end
            if (cfg_we && cfg_addr == A_DRAIN)
                drain_req <= cfg_bits[0];
            if (cfg_we && cfg_addr == A_CLASS)
                cls_mask <= cfg_bits[3:0];
            drained <= drain_req & ~pend & (credit == budget);

            // tag ring follows beats through the shuffler
            if (grant) begin
                tag_mem[tag_wp] <= req_sel;
                tag_wp          <= tag_wp + 3'd1;
            end
            if (beat_out)
                tag_rp <= tag_rp + 3'd1;
            if (slot_take)
                psel <= tag_mem[tag_rp];

            // token bucket
            if (cfg_we && cfg_addr == A_RATE) begin
                rate_period <= cfg_bits[7:0];
                rate_burst  <= cfg_bits[10:8];
            end
            if (!rate_on) begin
                rate_timer <= 8'd0;
                tokens     <= rate_burst;
            end else begin
                rate_timer <= rate_wrap ? 8'd0 : rate_timer + 8'd1;
                if (tokens > rate_burst)
                    tokens <= rate_burst;
                else
                    tokens <= tokens + {2'd0, tok_fill} - {2'd0, tok_use};
            end

            // exponential backoff on sustained port stalls
            if (stall_now) begin
                if (bo_run != 8'hff)
                    bo_run <= bo_run + 8'd1;
            end else begin
                bo_run <= 8'd0;
            end
            if (bo_active) begin
                if (bo_timer == 16'd0)
                    bo_active <= 1'b0;
                else
                    bo_timer <= bo_timer - 16'd1;
            end else if (bo_trip) begin
                bo_active <= 1'b1;
                bo_timer  <= bo_window;
                bo_run    <= 8'd0;
                if (bo_level != 3'd7)
                    bo_level <= bo_level + 3'd1;
            end
            if (stall_now || bo_active) begin
                bo_quiet <= 16'd0;
            end else if (bo_quiet >= bo_qlim) begin
                bo_quiet <= 16'd0;
                if (bo_level != 3'd0)
                    bo_level <= bo_level - 3'd1;
            end else begin
                bo_quiet <= bo_quiet + 16'd1;
            end
            if (cfg_we && cfg_addr == A_BOFF) begin
                bo_thresh <= cfg_bits[7:0];
                bo_base   <= cfg_bits[15:8];
                if (cfg_bits[16]) begin
                    bo_active <= 1'b0;
                    bo_level  <= 3'd0;
                    bo_timer  <= 16'd0;
                end
            end

            // starvation guard
            if (cfg_we && cfg_addr == A_STARVE)
                starve_lim <= cfg_bits[15:0];
            if (!req_valid || grant)
                wait_cur <= 16'd0;
            else if (wait_cur != 16'hffff)
                wait_cur <= wait_cur + 16'd1;
            if (wait_cur > wait_max)
                wait_max <= wait_cur;

            // hold statistics
            for (k = 0; k < 7; k = k + 1)
                if (req_valid && hold_why[k] && hold_cnt[k] != 16'hffff)
                    hold_cnt[k] <= hold_cnt[k] + 16'd1;
            if (wr_stsel) begin
                st_sel <= cfg_bits[3:0];
                if (cfg_bits[8]) begin
                    for (k = 0; k < 7; k = k + 1) hold_cnt[k] <= 16'd0;
                    wait_max  <= 16'd0;
                    drop_seen <= 1'b0;
                end
            end
            if (drop_now) begin
                drop_sel  <= tag_mem[tag_rp];
                drop_seen <= 1'b1;
            end
            case (st_sel)
                4'd0: stat <= {10'd0, drained, drain_req, bo_active, pend, lwm, pend_budget, budget, credit, tag_wp, tag_rp};
                4'd1: stat <= {5'd0, tokens, rate_burst, 5'd0, rate_timer, rate_period};
                4'd2: stat <= {bo_thresh, bo_base, bo_run, 5'd0, bo_level};
                4'd3: stat <= {bo_timer, bo_quiet};
                4'd4: stat <= {hold_cnt[1], hold_cnt[0]};
                4'd5: stat <= {hold_cnt[3], hold_cnt[2]};
                4'd6: stat <= {hold_cnt[5], hold_cnt[4]};
                4'd7: stat <= {hold_cnt[6], cls_mask, 3'd0, drop_seen, drop_sel};
                4'd8: stat <= {wait_max, starve_lim};
                4'd9: stat <= {psel, tag_mem[tag_rp], wait_cur};
                default: stat <= 32'd0;
            endcase
        end
    end

    assign hold_why_o = hold_why;
    assign port_sel_o = psel;
    assign credit_o   = credit;
    assign budget_o   = budget;
    assign tag_wp_o   = tag_wp;
    assign tag_rp_o   = tag_rp;
    assign drained_o  = drained;
    assign backoff_o  = bo_active;
    assign stat_o     = stat;
endmodule

module benes_lane_shuffler (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         in_valid,
    input  wire [511:0] in_data,
    input  wire [7:0]   in_sel,
    input  wire         cfg_we,
    input  wire [7:0]   cfg_addr,
    input  wire [19:0]  cfg_bits,
    output wire         out_valid,
    output wire [511:0] out_data,
    output wire [63:0]  o_beats_done
,
    output wire [63:0] inflight_o,
    output wire [4:0] valid_pipe_o
);
    reg [19:0]  cfg_tab   [0:255];
    reg [3:0]   stage_cfg [0:4];
    reg [19:0]  cfg_pipe  [0:3];
    reg [511:0] data_pipe [0:4];
    reg [4:0]   valid_pipe;
    reg [63:0]  inflight;
    reg [63:0]  beats_done;
    reg         armed;

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) cfg_tab[i] = 20'd0;
        for (i = 0; i < 5; i = i + 1) begin
            stage_cfg[i] = 4'd0;
            data_pipe[i] = 512'd0;
        end
        for (i = 0; i < 4; i = i + 1) cfg_pipe[i] = 20'd0;
        valid_pipe = 5'd0;
        inflight   = 64'd0;
        beats_done = 64'd0;
        armed      = 1'b0;
    end

    // butterfly stage, pair distance 4
    function [511:0] sw4;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw4[0*64 +: 64] = c[0] ? d[4*64 +: 64] : d[0*64 +: 64];
            sw4[4*64 +: 64] = c[0] ? d[0*64 +: 64] : d[4*64 +: 64];
            sw4[1*64 +: 64] = c[1] ? d[5*64 +: 64] : d[1*64 +: 64];
            sw4[5*64 +: 64] = c[1] ? d[1*64 +: 64] : d[5*64 +: 64];
            sw4[2*64 +: 64] = c[2] ? d[6*64 +: 64] : d[2*64 +: 64];
            sw4[6*64 +: 64] = c[2] ? d[2*64 +: 64] : d[6*64 +: 64];
            sw4[3*64 +: 64] = c[3] ? d[7*64 +: 64] : d[3*64 +: 64];
            sw4[7*64 +: 64] = c[3] ? d[3*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 2
    function [511:0] sw2;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw2[0*64 +: 64] = c[0] ? d[2*64 +: 64] : d[0*64 +: 64];
            sw2[2*64 +: 64] = c[0] ? d[0*64 +: 64] : d[2*64 +: 64];
            sw2[1*64 +: 64] = c[1] ? d[3*64 +: 64] : d[1*64 +: 64];
            sw2[3*64 +: 64] = c[1] ? d[1*64 +: 64] : d[3*64 +: 64];
            sw2[4*64 +: 64] = c[2] ? d[6*64 +: 64] : d[4*64 +: 64];
            sw2[6*64 +: 64] = c[2] ? d[4*64 +: 64] : d[6*64 +: 64];
            sw2[5*64 +: 64] = c[3] ? d[7*64 +: 64] : d[5*64 +: 64];
            sw2[7*64 +: 64] = c[3] ? d[5*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 1 (middle stage)
    function [511:0] sw1;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw1[0*64 +: 64] = c[0] ? d[1*64 +: 64] : d[0*64 +: 64];
            sw1[1*64 +: 64] = c[0] ? d[0*64 +: 64] : d[1*64 +: 64];
            sw1[2*64 +: 64] = c[1] ? d[3*64 +: 64] : d[2*64 +: 64];
            sw1[3*64 +: 64] = c[1] ? d[2*64 +: 64] : d[3*64 +: 64];
            sw1[4*64 +: 64] = c[2] ? d[5*64 +: 64] : d[4*64 +: 64];
            sw1[5*64 +: 64] = c[2] ? d[4*64 +: 64] : d[5*64 +: 64];
            sw1[6*64 +: 64] = c[3] ? d[7*64 +: 64] : d[6*64 +: 64];
            sw1[7*64 +: 64] = c[3] ? d[6*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    wire [19:0] cfg0 = cfg_tab[in_sel];

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < 256; i = i + 1) cfg_tab[i] <= 20'd0;
            for (i = 0; i < 5; i = i + 1) begin
                stage_cfg[i] <= 4'd0;
                data_pipe[i] <= 512'd0;
            end
            for (i = 0; i < 4; i = i + 1) cfg_pipe[i] <= 20'd0;
            valid_pipe <= 5'd0;
            inflight   <= 64'd0;
            beats_done <= 64'd0;
            armed      <= 1'b0;
        end else if (en) begin
            if (cfg_we) begin
                cfg_tab[cfg_addr] <= cfg_bits;
                armed <= 1'b1;
            end
            data_pipe[0] <= sw4(in_data, cfg0[3:0]);
            stage_cfg[0] <= cfg0[3:0];
            cfg_pipe[0]  <= cfg0;
            data_pipe[1] <= sw2(data_pipe[0], cfg_pipe[0][7:4]);
            stage_cfg[1] <= cfg_pipe[0][7:4];
            cfg_pipe[1]  <= cfg_pipe[0];
            data_pipe[2] <= sw1(data_pipe[1], cfg_pipe[1][11:8]);
            stage_cfg[2] <= cfg_pipe[1][11:8];
            cfg_pipe[2]  <= cfg_pipe[1];
            data_pipe[3] <= sw2(data_pipe[2], cfg_pipe[2][15:12]);
            stage_cfg[3] <= cfg_pipe[2][15:12];
            cfg_pipe[3]  <= cfg_pipe[2];
            data_pipe[4] <= sw4(data_pipe[3], cfg_pipe[3][19:16]);
            stage_cfg[4] <= cfg_pipe[3][19:16];
            valid_pipe <= {valid_pipe[3:0], in_valid};
            inflight   <= inflight + {63'd0, in_valid} - {63'd0, valid_pipe[4]};
            if (valid_pipe[4])
                beats_done <= beats_done + 64'd1;
        end
    end

    assign out_valid    = valid_pipe[4];
    assign out_data     = data_pipe[4];
    assign o_beats_done = beats_done;

    always @(posedge clk)
        if (armed)
            assert (inflight <= 64'd5);
    assign inflight_o = inflight;
    assign valid_pipe_o = valid_pipe;
endmodule

module lvds_port_perfmon (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         valid,
    input  wire         ready,
    input  wire [127:0] data,
    input  wire         win_start,
    output wire [31:0]  o_txn_cnt,
    output wire [35:0]  o_byte_cnt,
    output wire [31:0]  o_stall_cnt,
    output wire [47:0]  o_lat_cum,
    output wire [15:0]  o_win_cnt
,
    output wire [35:0] byte_cnt_o,
    output wire hs_d_o,
    output wire seen_txn_o,
    output wire [31:0] txn_cnt_o
);
    wire hs    = en & valid & ready;
    wire stall = en & valid & ~ready;

    reg [31:0] txn_cnt   = 32'd0;
    reg        hs_d      = 1'b0;
    reg [35:0] byte_cnt  = 36'd0;
    reg [31:0] stall_cnt = 32'd0;
    reg [15:0] lat_cur   = 16'd0;
    reg [47:0] lat_cum   = 48'd0;
    reg [15:0] win_cnt   = 16'd0;
    reg        armed     = 1'b0;
    reg        seen_txn  = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            txn_cnt   <= 32'd0;
            hs_d      <= 1'b0;
            byte_cnt  <= 36'd0;
            stall_cnt <= 32'd0;
            lat_cur   <= 16'd0;
            lat_cum   <= 48'd0;
            win_cnt   <= 16'd0;
            armed     <= 1'b0;
            seen_txn  <= 1'b0;
        end else if (en) begin
            hs_d <= hs;
            if (hs) begin
                txn_cnt  <= txn_cnt + 32'd1;
                seen_txn <= 1'b1;
                lat_cum  <= lat_cum + {32'd0, lat_cur};
                lat_cur  <= 16'd0;
            end else if (valid) begin
                lat_cur  <= lat_cur + 16'd1;
            end
            if (hs_d)
                byte_cnt <= byte_cnt + 36'd16;
            if (stall)
                stall_cnt <= stall_cnt + 32'd1;
            if (win_start) begin
                win_cnt <= 16'd0;
                armed   <= 1'b1;
            end else begin
                win_cnt <= win_cnt + 16'd1;
            end
        end
    end

    assign o_txn_cnt   = txn_cnt;
    assign o_byte_cnt  = byte_cnt;
    assign o_stall_cnt = stall_cnt;
    assign o_lat_cum   = lat_cum;
    assign o_win_cnt   = win_cnt;

    always @(posedge clk)
        if (armed && byte_cnt != 36'd0)
            assert (seen_txn);
    assign byte_cnt_o = byte_cnt;
    assign hs_d_o = hs_d;
    assign seen_txn_o = seen_txn;
    assign txn_cnt_o = txn_cnt;
endmodule

module benes_perfmon_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         in_valid,
    input  wire [511:0] in_data,
    input  wire [7:0]   in_sel,
    input  wire         cfg_we,
    input  wire [7:0]   cfg_addr,
    input  wire [19:0]  cfg_bits,
    input  wire         ready,
    input  wire         win_start,
    output wire [63:0]  o_beats_done,
    output wire         o_port_valid,
    output wire [127:0] o_port_data,
    output wire [31:0]  o_cap_cnt,
    output wire [31:0]  o_drop_cnt,
    output wire [31:0]  o_txn_cnt,
    output wire [35:0]  o_byte_cnt,
    output wire [31:0]  o_stall_cnt,
    output wire [47:0]  o_lat_cum,
   output wire [15:0]  o_win_cnt,
   output wire [31:0]  o_dbg_word,
   output wire [7:0]   o_dbg_flags,
   output wire         o_in_ready,
   output wire [6:0]   o_adm_hold,
   output wire [7:0]   o_port_sel,
   output wire         o_adm_drained,
   output wire         o_adm_backoff,
   output wire [31:0]  o_adm_stat
);
    wire         a_out_valid;
    wire [511:0] a_out_data;
    wire [63:0]  a_inflight;
    wire [4:0]   a_valid_pipe;

    wire [35:0]  b_byte_cnt;
    wire         b_hs_d;
    wire         b_seen_txn;
    wire [31:0]  b_txn_cnt;

    wire         adm_grant;
    wire         adm_req_ready;
    wire [6:0]   adm_hold;
    wire [7:0]   adm_port_sel;
    wire [2:0]   adm_credit;
    wire [2:0]   adm_budget;
    wire [2:0]   adm_tag_wp;
    wire [2:0]   adm_tag_rp;
    wire         adm_drained;
    wire         adm_backoff;
    wire [31:0]  adm_stat;

    reg          g_valid  = 1'b0;
    reg  [127:0] g_data   = 128'd0;
    reg  [31:0]  cap_cnt  = 32'd0;
    reg  [31:0]  drop_cnt = 32'd0;

   // debug / status register bank
   reg  [31:0]  dbg_cycle;
   reg  [23:0]  dbg_wdog;
   reg  [23:0]  dbg_wdog_lim;
   reg          dbg_wdog_trip;
   reg  [15:0]  dbg_stall_run;
   reg  [15:0]  dbg_stall_max;
   reg  [15:0]  dbg_cfg_wr;
   reg  [15:0]  dbg_drop_ev;
   reg  [31:0]  dbg_sig;
   reg  [3:0]   dbg_err_code;
   reg  [31:0]  dbg_err_time;
   reg          dbg_err_valid;
   reg  [7:0]   dbg_err_cnt;
   reg  [7:0]   dbg_err_flags;
   reg  [7:0]   dbg_sel_q0;
   reg  [7:0]   dbg_sel_q1;
   reg  [7:0]   dbg_sel_q2;
   reg  [7:0]   dbg_sel_q3;
   reg  [2:0]   dbg_ptr;
   reg  [31:0]  dbg_word;

   initial begin
       dbg_cycle     = 32'd0;
       dbg_wdog      = 24'd0;
       dbg_wdog_lim  = 24'd4096;
       dbg_wdog_trip = 1'b0;
       dbg_stall_run = 16'd0;
       dbg_stall_max = 16'd0;
       dbg_cfg_wr    = 16'd0;
       dbg_drop_ev   = 16'd0;
       dbg_sig       = 32'd0;
       dbg_err_code  = 4'd0;
       dbg_err_time  = 32'd0;
       dbg_err_valid = 1'b0;
       dbg_err_cnt   = 8'd0;
       dbg_err_flags = 8'd0;
       dbg_sel_q0    = 8'd0;
       dbg_sel_q1    = 8'd0;
       dbg_sel_q2    = 8'd0;
       dbg_sel_q3    = 8'd0;
       dbg_ptr       = 3'd0;
       dbg_word      = 32'd0;
   end

    benes_lane_shuffler u_shuf (
        .clk(clk),
        .rst(rst),
        .en(en),
        .in_valid(adm_grant),
        .in_data(in_data),
        .in_sel(in_sel),
        .cfg_we(cfg_we),
        .cfg_addr(cfg_addr),
        .cfg_bits(cfg_bits),
        .out_valid(a_out_valid),
        .out_data(a_out_data),
        .o_beats_done(o_beats_done),
        .inflight_o(a_inflight),
        .valid_pipe_o(a_valid_pipe)
    );

    wire slot_free = !g_valid || ready;

    shuf_admit_ctrl u_adm (
        .clk(clk),
        .rst(rst),
        .en(en),
        .req_valid(in_valid),
        .req_sel(in_sel),
        .cfg_we(cfg_we),
        .cfg_addr(cfg_addr),
        .cfg_bits(cfg_bits),
        .beat_out(a_out_valid),
        .port_valid(g_valid),
        .port_ready(ready),
        .grant(adm_grant),
        .req_ready(adm_req_ready),
        .hold_why_o(adm_hold),
        .port_sel_o(adm_port_sel),
        .credit_o(adm_credit),
        .budget_o(adm_budget),
        .tag_wp_o(adm_tag_wp),
        .tag_rp_o(adm_tag_rp),
        .drained_o(adm_drained),
        .backoff_o(adm_backoff),
        .stat_o(adm_stat)
    );

   wire        dbg_hs      = g_valid & ready;
   wire        dbg_stall   = g_valid & ~ready;
   wire        dbg_drop    = ~slot_free & a_out_valid;
   wire        dbg_wd_hit  = (dbg_wdog == dbg_wdog_lim);
   wire        dbg_wd_ev   = dbg_stall & dbg_wd_hit & ~dbg_wdog_trip;
   wire        dbg_collide = cfg_we & in_valid & (cfg_addr == in_sel);
   wire        dbg_any_err = dbg_drop | dbg_wd_ev | dbg_collide;
   wire        dbg_clr     = cfg_we & (cfg_addr == 8'hfe);
   wire [31:0] dbg_fold    = g_data[31:0] ^ g_data[63:32] ^ g_data[95:64] ^ g_data[127:96];
   wire        dbg_fb      = dbg_sig[31] ^ dbg_sig[21] ^ dbg_sig[1] ^ dbg_sig[0];

    always @(posedge clk) begin
        if (rst) begin
            g_valid  <= 1'b0;
            g_data   <= 128'd0;
            cap_cnt  <= 32'd0;
            drop_cnt <= 32'd0;
           dbg_cycle     <= 32'd0;
           dbg_wdog      <= 24'd0;
           dbg_wdog_lim  <= 24'd4096;
           dbg_wdog_trip <= 1'b0;
           dbg_stall_run <= 16'd0;
           dbg_stall_max <= 16'd0;
           dbg_cfg_wr    <= 16'd0;
           dbg_drop_ev   <= 16'd0;
           dbg_sig       <= 32'd0;
           dbg_err_code  <= 4'd0;
           dbg_err_time  <= 32'd0;
           dbg_err_valid <= 1'b0;
           dbg_err_cnt   <= 8'd0;
           dbg_err_flags <= 8'd0;
           dbg_sel_q0    <= 8'd0;
           dbg_sel_q1    <= 8'd0;
           dbg_sel_q2    <= 8'd0;
           dbg_sel_q3    <= 8'd0;
           dbg_ptr       <= 3'd0;
           dbg_word      <= 32'd0;
        end else if (en) begin
            if (slot_free) begin
                g_valid <= a_out_valid;
                if (a_out_valid) begin
                    g_data  <= a_out_data[127:0];
                    cap_cnt <= cap_cnt + 32'd1;
                end
            end else if (a_out_valid) begin
                drop_cnt <= drop_cnt + 32'd1;
            end
           dbg_cycle <= dbg_cycle + 32'd1;
           if (dbg_hs || !g_valid)
               dbg_wdog <= 24'd0;
           else if (!dbg_wd_hit)
               dbg_wdog <= dbg_wdog + 24'd1;
           if (cfg_we && cfg_addr == 8'hff)
               dbg_wdog_lim <= {4'd0, cfg_bits};
           if (dbg_wd_ev)
               dbg_wdog_trip <= 1'b1;
           else if (dbg_clr)
               dbg_wdog_trip <= 1'b0;
           if (dbg_stall) begin
               if (dbg_stall_run != 16'hffff)
                   dbg_stall_run <= dbg_stall_run + 16'd1;
           end else begin
               dbg_stall_run <= 16'd0;
           end
           if (dbg_stall_run > dbg_stall_max)
               dbg_stall_max <= dbg_stall_run;
           if (cfg_we && dbg_cfg_wr != 16'hffff)
               dbg_cfg_wr <= dbg_cfg_wr + 16'd1;
           if (dbg_drop && dbg_drop_ev != 16'hffff)
               dbg_drop_ev <= dbg_drop_ev + 16'd1;
           if (dbg_hs)
               dbg_sig <= {dbg_sig[30:0], dbg_fb} ^ dbg_fold;
           if (adm_grant) begin
               case (in_sel[7:6])
                   2'd0: dbg_sel_q0 <= dbg_sel_q0 + 8'd1;
                   2'd1: dbg_sel_q1 <= dbg_sel_q1 + 8'd1;
                   2'd2: dbg_sel_q2 <= dbg_sel_q2 + 8'd1;
                   default: dbg_sel_q3 <= dbg_sel_q3 + 8'd1;
               endcase
           end
           if (dbg_clr) begin
               dbg_err_valid <= 1'b0;
               dbg_err_code  <= 4'd0;
               dbg_err_cnt   <= 8'd0;
               dbg_err_flags <= 8'd0;
           end else if (dbg_any_err) begin
               if (dbg_err_cnt != 8'hff)
                   dbg_err_cnt <= dbg_err_cnt + 8'd1;
               dbg_err_flags <= dbg_err_flags | {5'd0, dbg_collide, dbg_wd_ev, dbg_drop};
               if (!dbg_err_valid) begin
                   dbg_err_valid <= 1'b1;
                   dbg_err_time  <= dbg_cycle;
                   dbg_err_code  <= dbg_drop ? 4'd1 : (dbg_wd_ev ? 4'd2 : 4'd3);
               end
           end
           if (win_start)
               dbg_ptr <= dbg_ptr + 3'd1;
           case (dbg_ptr)
               3'd0: dbg_word <= dbg_cycle;
               3'd1: dbg_word <= {dbg_stall_max, dbg_cfg_wr};
               3'd2: dbg_word <= dbg_sig;
               3'd3: dbg_word <= {dbg_err_valid, dbg_err_code[2:0], 4'd0, dbg_err_cnt, dbg_drop_ev};
               3'd4: dbg_word <= dbg_err_time;
               3'd5: dbg_word <= {dbg_sel_q3, dbg_sel_q2, dbg_sel_q1, dbg_sel_q0};
               3'd6: dbg_word <= {7'd0, dbg_wdog_trip, dbg_wdog};
               default: dbg_word <= {dbg_err_flags, dbg_wdog_lim};
           endcase
        end
    end

    lvds_port_perfmon u_mon (
        .clk(clk),
        .rst(rst),
        .en(en),
        .valid(g_valid),
        .ready(ready),
        .data(g_data),
        .win_start(win_start),
        .o_txn_cnt(o_txn_cnt),
        .o_byte_cnt(o_byte_cnt),
        .o_stall_cnt(o_stall_cnt),
        .o_lat_cum(o_lat_cum),
        .o_win_cnt(o_win_cnt),
        .byte_cnt_o(b_byte_cnt),
        .hs_d_o(b_hs_d),
        .seen_txn_o(b_seen_txn),
        .txn_cnt_o(b_txn_cnt)
    );

    assign o_port_valid = g_valid;
    assign o_port_data  = g_data;
    assign o_cap_cnt    = cap_cnt;
    assign o_drop_cnt   = drop_cnt;
   assign o_dbg_word   = dbg_word;
   assign o_dbg_flags  = dbg_err_flags;
   assign o_in_ready    = adm_req_ready;
   assign o_adm_hold    = adm_hold;
   assign o_port_sel    = adm_port_sel;
   assign o_adm_drained = adm_drained;
   assign o_adm_backoff = adm_backoff;
   assign o_adm_stat    = adm_stat;

    always @(posedge clk)
        if (!g_valid)
            assert (cap_cnt == b_txn_cnt);

    always @(posedge clk)
        assert ({1'b0, adm_credit} + {1'b0, adm_tag_wp - adm_tag_rp} <= {1'b0, adm_budget});
endmodule

module fm_link_8b10b_framer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [7:0]  i_data,
    output reg  [9:0]  o_sym,
    output reg         o_rd,
    output reg  [31:0] o_sym_cnt,
output reg  [31:0] o_pkt_cnt,
output reg  [15:0] o_err_cnt,
output reg  [15:0] o_max_len,
output reg         o_wdog,
output reg  [7:0]  o_mon_status
);
    localparam [1:0] K_COMMA = 2'd1, K_SOF = 2'd2, K_EOF = 2'd3;
    localparam [1:0] PH_IDLE = 2'd0, PH_ALIGN = 2'd1, PH_PKT = 2'd2;

    reg [1:0] phase;
    reg seen_comma, seen_start, seen_end;
// link monitor / statistics (debug visibility only)
localparam [11:0] WDOG_LIMIT = 12'd2047;
reg [15:0] idle_cnt;
reg [11:0] wdog_cnt;
reg [15:0] cur_len;
reg [7:0]  rd_hist;
reg [1:0]  last_kcode;
reg        bad_k_seen;

    initial begin
        phase = PH_IDLE; seen_comma = 1'b0; seen_start = 1'b0; seen_end = 1'b0;
        o_sym = 10'd0; o_rd = 1'b0; o_sym_cnt = 32'd0; o_pkt_cnt = 32'd0;
idle_cnt = 16'd0; wdog_cnt = 12'd0; cur_len = 16'd0; rd_hist = 8'd0;
last_kcode = 2'd0; bad_k_seen = 1'b0;
o_err_cnt = 16'd0; o_max_len = 16'd0; o_wdog = 1'b0; o_mon_status = 8'd0;
    end

    function [5:0] enc6;
        input [4:0] x;
        begin
            case (x)
                5'd0:  enc6 = 6'b100111;
                5'd1:  enc6 = 6'b011101;
                5'd2:  enc6 = 6'b101101;
                5'd3:  enc6 = 6'b110001;
                5'd4:  enc6 = 6'b110101;
                5'd5:  enc6 = 6'b101001;
                5'd6:  enc6 = 6'b011001;
                5'd7:  enc6 = 6'b111000;
                5'd8:  enc6 = 6'b111001;
                5'd9:  enc6 = 6'b100101;
                5'd10: enc6 = 6'b010101;
                5'd11: enc6 = 6'b110100;
                5'd12: enc6 = 6'b001101;
                5'd13: enc6 = 6'b101100;
                5'd14: enc6 = 6'b011100;
                5'd15: enc6 = 6'b010111;
                5'd16: enc6 = 6'b011011;
                5'd17: enc6 = 6'b100011;
                5'd18: enc6 = 6'b010011;
                5'd19: enc6 = 6'b110010;
                5'd20: enc6 = 6'b001011;
                5'd21: enc6 = 6'b101010;
                5'd22: enc6 = 6'b011010;
                5'd23: enc6 = 6'b111010;
                5'd24: enc6 = 6'b110011;
                5'd25: enc6 = 6'b100110;
                5'd26: enc6 = 6'b010110;
                5'd27: enc6 = 6'b110110;
                5'd28: enc6 = 6'b001110;
                5'd29: enc6 = 6'b101110;
                5'd30: enc6 = 6'b011110;
                default: enc6 = 6'b101011;
            endcase
        end
    endfunction

    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
                3'd5: enc4 = 4'b1010;
                3'd6: enc4 = 4'b0110;
                default: enc4 = 4'b1110;
            endcase
        end
    endfunction

    function [2:0] ones6;
        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
    wire do_comma = i_ce && i_k && (i_kcode == K_COMMA);
    wire do_sof   = i_ce && i_k && (i_kcode == K_SOF) && (phase == PH_ALIGN);
    wire do_eof   = i_ce && i_k && (i_kcode == K_EOF) && (phase == PH_PKT);
    wire do_data  = i_ce && !i_k;
// monitor-side decodes
wire bad_k        = i_ce && i_k && !do_comma && !do_sof && !do_eof;
wire mon_pkt_data = do_data && (phase == PH_PKT);
wire [15:0] len_nxt = cur_len + 16'd1;

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
idle_cnt <= 16'd0; wdog_cnt <= 12'd0; cur_len <= 16'd0; rd_hist <= 8'd0;
last_kcode <= 2'd0; bad_k_seen <= 1'b0;
o_err_cnt <= 16'd0; o_max_len <= 16'd0; o_wdog <= 1'b0; o_mon_status <= 8'd0;
        end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
if (!rst) begin
// idle cycle counter (saturating)
if (!i_ce && (idle_cnt != 16'hFFFF)) idle_cnt <= idle_cnt + 16'd1;
// illegal / out-of-sequence control symbol logger
if (bad_k) begin
bad_k_seen <= 1'b1;
if (o_err_cnt != 16'hFFFF) o_err_cnt <= o_err_cnt + 16'd1;
end
if (i_ce && i_k) last_kcode <= i_kcode;
// comma watchdog
if (do_comma) begin
wdog_cnt <= 12'd0;
o_wdog   <= 1'b0;
end else if (wdog_cnt != WDOG_LIMIT) begin
wdog_cnt <= wdog_cnt + 12'd1;
end else begin
o_wdog   <= 1'b1;
end
// packet payload length tracker
if (do_sof) begin
cur_len <= 16'd0;
end else if (mon_pkt_data && (cur_len != 16'hFFFF)) begin
cur_len <= len_nxt;
if (len_nxt > o_max_len) o_max_len <= len_nxt;
end
// running disparity history
if (i_ce) rd_hist <= {rd_hist[6:0], o_rd};
o_mon_status <= {bad_k_seen, (idle_cnt[15:12] != 4'd0), last_kcode, rd_hist[3:0]};
end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));
endmodule

module beat_admit_q (
   input  wire         clk,
   input  wire         rst,
   input  wire         en,
   input  wire         in_valid,
   input  wire [511:0] in_data,
   input  wire [7:0]   in_sel,
   input  wire         cfg_we,
   input  wire [7:0]   cfg_addr,
   input  wire         ret,
   output wire         in_ready,
   output wire         take,
   output wire         issue,
   output wire [511:0] head_data,
   output wire [7:0]   head_sel,
   output wire [2:0]   o_count,
   output wire [2:0]   o_credits,
   output wire         o_ret_pend,
   output wire [15:0]  o_stalls
);
   reg [511:0] q_data [0:3];
   reg [7:0]   q_sel  [0:3];
   reg [1:0]   wr_ptr;
   reg [1:0]   rd_ptr;
   reg [2:0]   count;
   reg [2:0]   credits;
   reg         ret_pend;
   reg [15:0]  stalls;

   integer j;
   initial begin
       for (j = 0; j < 4; j = j + 1) begin
           q_data[j] = 512'd0;
           q_sel[j]  = 8'd0;
       end
       wr_ptr   = 2'd0;
       rd_ptr   = 2'd0;
       count    = 3'd0;
       credits  = 3'd5;
       ret_pend = 1'b0;
       stalls   = 16'd0;
   end

   // a head beat must not read a mapping row that is being rewritten
   assign head_data = q_data[rd_ptr];
   assign head_sel  = q_sel[rd_ptr];
   wire   nonempty  = (count != 3'd0);
   wire   hazard    = cfg_we && (cfg_addr == head_sel);
   assign in_ready  = (credits != 3'd0) && (count != 3'd4);
   assign take      = en && in_valid && in_ready;
   assign issue     = en && nonempty && !hazard;
   assign o_count    = count;
   assign o_credits  = credits;
   assign o_ret_pend = ret_pend;
   assign o_stalls   = stalls;

   always @(posedge clk) begin
       if (rst) begin
           for (j = 0; j < 4; j = j + 1) begin
               q_data[j] <= 512'd0;
               q_sel[j]  <= 8'd0;
           end
           wr_ptr   <= 2'd0;
           rd_ptr   <= 2'd0;
           count    <= 3'd0;
           credits  <= 3'd5;
           ret_pend <= 1'b0;
           stalls   <= 16'd0;
       end else if (en) begin
           if (take) begin
               q_data[wr_ptr] <= in_data;
               q_sel[wr_ptr]  <= in_sel;
               wr_ptr <= wr_ptr + 2'd1;
           end
           if (issue)
               rd_ptr <= rd_ptr + 2'd1;
           count    <= count + {2'd0, take} - {2'd0, issue};
           // credit comes back one cycle after the beat leaves the pipe
           ret_pend <= ret;
           credits  <= credits - {2'd0, take} + {2'd0, ret_pend};
           if (nonempty && hazard)
               stalls <= stalls + 16'd1;
       end
   end
endmodule

module benes_lane_shuffler (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         in_valid,
    input  wire [511:0] in_data,
    input  wire [7:0]   in_sel,
    input  wire         cfg_we,
    input  wire [7:0]   cfg_addr,
    input  wire [19:0]  cfg_bits,
    output wire         out_valid,
    output wire [511:0] out_data,
   output wire [63:0]  o_beats_done,
   output wire         in_ready,
   output wire [2:0]   o_q_level,
   output wire [2:0]   o_credits,
   output wire [15:0]  o_hazard_stalls
);
    reg [19:0]  cfg_tab   [0:255];
    reg [3:0]   stage_cfg [0:4];
    reg [19:0]  cfg_pipe  [0:3];
    reg [511:0] data_pipe [0:4];
    reg [4:0]   valid_pipe;
    reg [63:0]  inflight;
    reg [63:0]  beats_done;
    reg         armed;

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) cfg_tab[i] = 20'd0;
        for (i = 0; i < 5; i = i + 1) begin
            stage_cfg[i] = 4'd0;
            data_pipe[i] = 512'd0;
        end
        for (i = 0; i < 4; i = i + 1) cfg_pipe[i] = 20'd0;
        valid_pipe = 5'd0;
        inflight   = 64'd0;
        beats_done = 64'd0;
        armed      = 1'b0;
    end

    // butterfly stage, pair distance 4
    function [511:0] sw4;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw4[0*64 +: 64] = c[0] ? d[4*64 +: 64] : d[0*64 +: 64];
            sw4[4*64 +: 64] = c[0] ? d[0*64 +: 64] : d[4*64 +: 64];
            sw4[1*64 +: 64] = c[1] ? d[5*64 +: 64] : d[1*64 +: 64];
            sw4[5*64 +: 64] = c[1] ? d[1*64 +: 64] : d[5*64 +: 64];
            sw4[2*64 +: 64] = c[2] ? d[6*64 +: 64] : d[2*64 +: 64];
            sw4[6*64 +: 64] = c[2] ? d[2*64 +: 64] : d[6*64 +: 64];
            sw4[3*64 +: 64] = c[3] ? d[7*64 +: 64] : d[3*64 +: 64];
            sw4[7*64 +: 64] = c[3] ? d[3*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 2
    function [511:0] sw2;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw2[0*64 +: 64] = c[0] ? d[2*64 +: 64] : d[0*64 +: 64];
            sw2[2*64 +: 64] = c[0] ? d[0*64 +: 64] : d[2*64 +: 64];
            sw2[1*64 +: 64] = c[1] ? d[3*64 +: 64] : d[1*64 +: 64];
            sw2[3*64 +: 64] = c[1] ? d[1*64 +: 64] : d[3*64 +: 64];
            sw2[4*64 +: 64] = c[2] ? d[6*64 +: 64] : d[4*64 +: 64];
            sw2[6*64 +: 64] = c[2] ? d[4*64 +: 64] : d[6*64 +: 64];
            sw2[5*64 +: 64] = c[3] ? d[7*64 +: 64] : d[5*64 +: 64];
            sw2[7*64 +: 64] = c[3] ? d[5*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 1 (middle stage)
    function [511:0] sw1;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw1[0*64 +: 64] = c[0] ? d[1*64 +: 64] : d[0*64 +: 64];
            sw1[1*64 +: 64] = c[0] ? d[0*64 +: 64] : d[1*64 +: 64];
            sw1[2*64 +: 64] = c[1] ? d[3*64 +: 64] : d[2*64 +: 64];
            sw1[3*64 +: 64] = c[1] ? d[2*64 +: 64] : d[3*64 +: 64];
            sw1[4*64 +: 64] = c[2] ? d[5*64 +: 64] : d[4*64 +: 64];
            sw1[5*64 +: 64] = c[2] ? d[4*64 +: 64] : d[5*64 +: 64];
            sw1[6*64 +: 64] = c[3] ? d[7*64 +: 64] : d[6*64 +: 64];
            sw1[7*64 +: 64] = c[3] ? d[6*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

   wire         adm_ready;
   wire         adm_take;
   wire         adm_issue;
   wire [511:0] q_head_data;
   wire [7:0]   q_head_sel;
   wire [2:0]   adm_level;
   wire [2:0]   adm_credits;
   wire         adm_ret_pend;
   wire [15:0]  adm_stalls;

   beat_admit_q u_admit (
       .clk        (clk),
       .rst        (rst),
       .en         (en),
       .in_valid   (in_valid),
       .in_data    (in_data),
       .in_sel     (in_sel),
       .cfg_we     (cfg_we),
       .cfg_addr   (cfg_addr),
       .ret        (valid_pipe[4]),
       .in_ready   (adm_ready),
       .take       (adm_take),
       .issue      (adm_issue),
       .head_data  (q_head_data),
       .head_sel   (q_head_sel),
       .o_count    (adm_level),
       .o_credits  (adm_credits),
       .o_ret_pend (adm_ret_pend),
       .o_stalls   (adm_stalls)
   );

   wire [19:0] cfg0 = cfg_tab[q_head_sel];

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < 256; i = i + 1) cfg_tab[i] <= 20'd0;
            for (i = 0; i < 5; i = i + 1) begin
                stage_cfg[i] <= 4'd0;
                data_pipe[i] <= 512'd0;
            end
            for (i = 0; i < 4; i = i + 1) cfg_pipe[i] <= 20'd0;
            valid_pipe <= 5'd0;
            inflight   <= 64'd0;
            beats_done <= 64'd0;
            armed      <= 1'b0;
        end else if (en) begin
            if (cfg_we) begin
                cfg_tab[cfg_addr] <= cfg_bits;
                armed <= 1'b1;
            end
           data_pipe[0] <= sw4(q_head_data, cfg0[3:0]);
            stage_cfg[0] <= cfg0[3:0];
            cfg_pipe[0]  <= cfg0;
            data_pipe[1] <= sw2(data_pipe[0], cfg_pipe[0][7:4]);
            stage_cfg[1] <= cfg_pipe[0][7:4];
            cfg_pipe[1]  <= cfg_pipe[0];
            data_pipe[2] <= sw1(data_pipe[1], cfg_pipe[1][11:8]);
            stage_cfg[2] <= cfg_pipe[1][11:8];
            cfg_pipe[2]  <= cfg_pipe[1];
            data_pipe[3] <= sw2(data_pipe[2], cfg_pipe[2][15:12]);
            stage_cfg[3] <= cfg_pipe[2][15:12];
            cfg_pipe[3]  <= cfg_pipe[2];
            data_pipe[4] <= sw4(data_pipe[3], cfg_pipe[3][19:16]);
            stage_cfg[4] <= cfg_pipe[3][19:16];
           valid_pipe <= {valid_pipe[3:0], adm_issue};
           inflight   <= inflight + {63'd0, adm_take} - {63'd0, valid_pipe[4]};
            if (valid_pipe[4])
                beats_done <= beats_done + 64'd1;
        end
    end

    assign out_valid    = valid_pipe[4];
    assign out_data     = data_pipe[4];
    assign o_beats_done = beats_done;
   assign in_ready        = adm_ready;
   assign o_q_level       = adm_level;
   assign o_credits       = adm_credits;
   assign o_hazard_stalls = adm_stalls;

    always @(posedge clk)
        if (armed)
            assert (inflight <= 64'd5);
endmodule

module benes_lane_shuffler (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         in_valid,
    input  wire [511:0] in_data,
    input  wire [7:0]   in_sel,
    input  wire         cfg_we,
    input  wire [7:0]   cfg_addr,
    input  wire [19:0]  cfg_bits,
    output wire         out_valid,
    output wire [511:0] out_data,
    output wire [63:0]  o_beats_done
,
    output wire [63:0] inflight_o,
    output wire [4:0] valid_pipe_o
);
    reg [19:0]  cfg_tab   [0:255];
    reg [3:0]   stage_cfg [0:4];
    reg [19:0]  cfg_pipe  [0:3];
    reg [511:0] data_pipe [0:4];
    reg [4:0]   valid_pipe;
    reg [63:0]  inflight;
    reg [63:0]  beats_done;
    reg         armed;

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) cfg_tab[i] = 20'd0;
        for (i = 0; i < 5; i = i + 1) begin
            stage_cfg[i] = 4'd0;
            data_pipe[i] = 512'd0;
        end
        for (i = 0; i < 4; i = i + 1) cfg_pipe[i] = 20'd0;
        valid_pipe = 5'd0;
        inflight   = 64'd0;
        beats_done = 64'd0;
        armed      = 1'b0;
    end

    // butterfly stage, pair distance 4
    function [511:0] sw4;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw4[0*64 +: 64] = c[0] ? d[4*64 +: 64] : d[0*64 +: 64];
            sw4[4*64 +: 64] = c[0] ? d[0*64 +: 64] : d[4*64 +: 64];
            sw4[1*64 +: 64] = c[1] ? d[5*64 +: 64] : d[1*64 +: 64];
            sw4[5*64 +: 64] = c[1] ? d[1*64 +: 64] : d[5*64 +: 64];
            sw4[2*64 +: 64] = c[2] ? d[6*64 +: 64] : d[2*64 +: 64];
            sw4[6*64 +: 64] = c[2] ? d[2*64 +: 64] : d[6*64 +: 64];
            sw4[3*64 +: 64] = c[3] ? d[7*64 +: 64] : d[3*64 +: 64];
            sw4[7*64 +: 64] = c[3] ? d[3*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 2
    function [511:0] sw2;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw2[0*64 +: 64] = c[0] ? d[2*64 +: 64] : d[0*64 +: 64];
            sw2[2*64 +: 64] = c[0] ? d[0*64 +: 64] : d[2*64 +: 64];
            sw2[1*64 +: 64] = c[1] ? d[3*64 +: 64] : d[1*64 +: 64];
            sw2[3*64 +: 64] = c[1] ? d[1*64 +: 64] : d[3*64 +: 64];
            sw2[4*64 +: 64] = c[2] ? d[6*64 +: 64] : d[4*64 +: 64];
            sw2[6*64 +: 64] = c[2] ? d[4*64 +: 64] : d[6*64 +: 64];
            sw2[5*64 +: 64] = c[3] ? d[7*64 +: 64] : d[5*64 +: 64];
            sw2[7*64 +: 64] = c[3] ? d[5*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 1 (middle stage)
    function [511:0] sw1;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw1[0*64 +: 64] = c[0] ? d[1*64 +: 64] : d[0*64 +: 64];
            sw1[1*64 +: 64] = c[0] ? d[0*64 +: 64] : d[1*64 +: 64];
            sw1[2*64 +: 64] = c[1] ? d[3*64 +: 64] : d[2*64 +: 64];
            sw1[3*64 +: 64] = c[1] ? d[2*64 +: 64] : d[3*64 +: 64];
            sw1[4*64 +: 64] = c[2] ? d[5*64 +: 64] : d[4*64 +: 64];
            sw1[5*64 +: 64] = c[2] ? d[4*64 +: 64] : d[5*64 +: 64];
            sw1[6*64 +: 64] = c[3] ? d[7*64 +: 64] : d[6*64 +: 64];
            sw1[7*64 +: 64] = c[3] ? d[6*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    wire [19:0] cfg0 = cfg_tab[in_sel];

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < 256; i = i + 1) cfg_tab[i] <= 20'd0;
            for (i = 0; i < 5; i = i + 1) begin
                stage_cfg[i] <= 4'd0;
                data_pipe[i] <= 512'd0;
            end
            for (i = 0; i < 4; i = i + 1) cfg_pipe[i] <= 20'd0;
            valid_pipe <= 5'd0;
            inflight   <= 64'd0;
            beats_done <= 64'd0;
            armed      <= 1'b0;
        end else if (en) begin
            if (cfg_we) begin
                cfg_tab[cfg_addr] <= cfg_bits;
                armed <= 1'b1;
            end
            data_pipe[0] <= sw4(in_data, cfg0[3:0]);
            stage_cfg[0] <= cfg0[3:0];
            cfg_pipe[0]  <= cfg0;
            data_pipe[1] <= sw2(data_pipe[0], cfg_pipe[0][7:4]);
            stage_cfg[1] <= cfg_pipe[0][7:4];
            cfg_pipe[1]  <= cfg_pipe[0];
            data_pipe[2] <= sw1(data_pipe[1], cfg_pipe[1][11:8]);
            stage_cfg[2] <= cfg_pipe[1][11:8];
            cfg_pipe[2]  <= cfg_pipe[1];
            data_pipe[3] <= sw2(data_pipe[2], cfg_pipe[2][15:12]);
            stage_cfg[3] <= cfg_pipe[2][15:12];
            cfg_pipe[3]  <= cfg_pipe[2];
            data_pipe[4] <= sw4(data_pipe[3], cfg_pipe[3][19:16]);
            stage_cfg[4] <= cfg_pipe[3][19:16];
            valid_pipe <= {valid_pipe[3:0], in_valid};
            inflight   <= inflight + {63'd0, in_valid} - {63'd0, valid_pipe[4]};
            if (valid_pipe[4])
                beats_done <= beats_done + 64'd1;
        end
    end

    assign out_valid    = valid_pipe[4];
    assign out_data     = data_pipe[4];
    assign o_beats_done = beats_done;

    always @(posedge clk)
        if (armed)
            assert (inflight <= 64'd5);
    assign inflight_o = inflight;
    assign valid_pipe_o = valid_pipe;
endmodule

module lvds_port_perfmon (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         valid,
    input  wire         ready,
    input  wire [127:0] data,
    input  wire         win_start,
    output wire [31:0]  o_txn_cnt,
    output wire [35:0]  o_byte_cnt,
    output wire [31:0]  o_stall_cnt,
    output wire [47:0]  o_lat_cum,
    output wire [15:0]  o_win_cnt
,
    output wire [35:0] byte_cnt_o,
    output wire hs_d_o,
    output wire seen_txn_o,
    output wire [31:0] txn_cnt_o
);
    wire hs    = en & valid & ready;
    wire stall = en & valid & ~ready;

    reg [31:0] txn_cnt   = 32'd0;
    reg        hs_d      = 1'b0;
    reg [35:0] byte_cnt  = 36'd0;
    reg [31:0] stall_cnt = 32'd0;
    reg [15:0] lat_cur   = 16'd0;
    reg [47:0] lat_cum   = 48'd0;
    reg [15:0] win_cnt   = 16'd0;
    reg        armed     = 1'b0;
    reg        seen_txn  = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            txn_cnt   <= 32'd0;
            hs_d      <= 1'b0;
            byte_cnt  <= 36'd0;
            stall_cnt <= 32'd0;
            lat_cur   <= 16'd0;
            lat_cum   <= 48'd0;
            win_cnt   <= 16'd0;
            armed     <= 1'b0;
            seen_txn  <= 1'b0;
        end else if (en) begin
            hs_d <= hs;
            if (hs) begin
                txn_cnt  <= txn_cnt + 32'd1;
                seen_txn <= 1'b1;
                lat_cum  <= lat_cum + {32'd0, lat_cur};
                lat_cur  <= 16'd0;
            end else if (valid) begin
                lat_cur  <= lat_cur + 16'd1;
            end
            if (hs_d)
                byte_cnt <= byte_cnt + 36'd16;
            if (stall)
                stall_cnt <= stall_cnt + 32'd1;
            if (win_start) begin
                win_cnt <= 16'd0;
                armed   <= 1'b1;
            end else begin
                win_cnt <= win_cnt + 16'd1;
            end
        end
    end

    assign o_txn_cnt   = txn_cnt;
    assign o_byte_cnt  = byte_cnt;
    assign o_stall_cnt = stall_cnt;
    assign o_lat_cum   = lat_cum;
    assign o_win_cnt   = win_cnt;

    always @(posedge clk)
        if (armed && byte_cnt != 36'd0)
            assert (seen_txn);
    assign byte_cnt_o = byte_cnt;
    assign hs_d_o = hs_d;
    assign seen_txn_o = seen_txn;
    assign txn_cnt_o = txn_cnt;
endmodule

module benes_perfmon_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         in_valid,
    input  wire [511:0] in_data,
    input  wire [7:0]   in_sel,
    input  wire         cfg_we,
    input  wire [7:0]   cfg_addr,
    input  wire [19:0]  cfg_bits,
    input  wire         ready,
    input  wire         win_start,
    output wire [63:0]  o_beats_done,
    output wire         o_port_valid,
    output wire [127:0] o_port_data,
    output wire [31:0]  o_cap_cnt,
    output wire [31:0]  o_drop_cnt,
    output wire [31:0]  o_txn_cnt,
    output wire [35:0]  o_byte_cnt,
    output wire [31:0]  o_stall_cnt,
    output wire [47:0]  o_lat_cum,
   output wire [15:0]  o_win_cnt,
   output wire [31:0]  o_dbg_rdata,
   output wire [31:0]  o_dbg_status,
   output wire [31:0]  o_dbg_sig
);
    wire         a_out_valid;
    wire [511:0] a_out_data;
    wire [63:0]  a_inflight;
    wire [4:0]   a_valid_pipe;

    wire [35:0]  b_byte_cnt;
    wire         b_hs_d;
    wire         b_seen_txn;
    wire [31:0]  b_txn_cnt;

    reg          g_valid  = 1'b0;
    reg  [127:0] g_data   = 128'd0;
    reg  [31:0]  cap_cnt  = 32'd0;
    reg  [31:0]  drop_cnt = 32'd0;

    benes_lane_shuffler u_shuf (
        .clk(clk),
        .rst(rst),
        .en(en),
        .in_valid(in_valid),
        .in_data(in_data),
        .in_sel(in_sel),
        .cfg_we(cfg_we),
        .cfg_addr(cfg_addr),
        .cfg_bits(cfg_bits),
        .out_valid(a_out_valid),
        .out_data(a_out_data),
        .o_beats_done(o_beats_done),
        .inflight_o(a_inflight),
        .valid_pipe_o(a_valid_pipe)
    );

    wire slot_free = !g_valid || ready;

   // ---------------- debug / statistics bank ----------------
   localparam [15:0] DBG_WDOG_LIMIT = 16'd1024;

   reg  [31:0]  dbg_cyc_cnt;
   reg  [31:0]  dbg_in_cnt;
   reg  [15:0]  dbg_cfg_wr;
   reg  [7:0]   dbg_last_addr;
   reg  [19:0]  dbg_last_bits;
   reg  [15:0]  dbg_idle_run;
   reg          dbg_wdog_trip;
   reg  [15:0]  dbg_stall_run;
   reg  [15:0]  dbg_stall_max;
   reg  [31:0]  dbg_sig;
   reg  [7:0]   dbg_err_log [0:3];
   reg  [1:0]   dbg_err_wp;
   reg  [2:0]   dbg_err_cnt;
   reg  [7:0]   dbg_err_flags;
   reg  [15:0]  dbg_win_seen;
   reg  [31:0]  dbg_beats_snap;
   reg  [31:0]  dbg_rdata;

   integer k;
   initial begin
       for (k = 0; k < 4; k = k + 1) dbg_err_log[k] = 8'd0;
       dbg_cyc_cnt    = 32'd0;
       dbg_in_cnt     = 32'd0;
       dbg_cfg_wr     = 16'd0;
       dbg_last_addr  = 8'd0;
       dbg_last_bits  = 20'd0;
       dbg_idle_run   = 16'd0;
       dbg_wdog_trip  = 1'b0;
       dbg_stall_run  = 16'd0;
       dbg_stall_max  = 16'd0;
       dbg_sig        = 32'd0;
       dbg_err_wp     = 2'd0;
       dbg_err_cnt    = 3'd0;
       dbg_err_flags  = 8'd0;
       dbg_win_seen   = 16'd0;
       dbg_beats_snap = 32'd0;
       dbg_rdata      = 32'd0;
   end

   wire [31:0] dbg_fold     = a_out_data[31:0] ^ a_out_data[63:32] ^
                              a_out_data[95:64] ^ a_out_data[127:96];
   wire        dbg_stall    = g_valid & ~ready;
   wire        dbg_hazard   = cfg_we & in_valid & (cfg_addr == in_sel);
   wire        dbg_drop_ev  = ~slot_free & a_out_valid;
   wire        dbg_wdog_ev  = (dbg_idle_run == DBG_WDOG_LIMIT);
   wire        dbg_any_err  = dbg_hazard | dbg_drop_ev | dbg_wdog_ev;
   wire [7:0]  dbg_err_code = {dbg_err_cnt, 2'b00, dbg_wdog_ev, dbg_drop_ev, dbg_hazard};
   wire [15:0] dbg_stall_nx = (dbg_stall_run == 16'hFFFF) ? dbg_stall_run
                                                           : dbg_stall_run + 16'd1;
   wire [1:0]  dbg_err_rp   = dbg_err_wp - 2'd1;
   wire [31:0] dbg_sig_nx   = {dbg_sig[30:0],
                               dbg_sig[31] ^ dbg_sig[21] ^ dbg_sig[1] ^ dbg_sig[0]} ^ dbg_fold;

    always @(posedge clk) begin
        if (rst) begin
            g_valid  <= 1'b0;
            g_data   <= 128'd0;
            cap_cnt  <= 32'd0;
            drop_cnt <= 32'd0;
           for (k = 0; k < 4; k = k + 1) dbg_err_log[k] <= 8'd0;
           dbg_cyc_cnt    <= 32'd0;
           dbg_in_cnt     <= 32'd0;
           dbg_cfg_wr     <= 16'd0;
           dbg_last_addr  <= 8'd0;
           dbg_last_bits  <= 20'd0;
           dbg_idle_run   <= 16'd0;
           dbg_wdog_trip  <= 1'b0;
           dbg_stall_run  <= 16'd0;
           dbg_stall_max  <= 16'd0;
           dbg_sig        <= 32'd0;
           dbg_err_wp     <= 2'd0;
           dbg_err_cnt    <= 3'd0;
           dbg_err_flags  <= 8'd0;
           dbg_win_seen   <= 16'd0;
           dbg_beats_snap <= 32'd0;
           dbg_rdata      <= 32'd0;
        end else if (en) begin
            if (slot_free) begin
                g_valid <= a_out_valid;
                if (a_out_valid) begin
                    g_data  <= a_out_data[127:0];
                    cap_cnt <= cap_cnt + 32'd1;
                end
            end else if (a_out_valid) begin
                drop_cnt <= drop_cnt + 32'd1;
            end
           // debug / statistics bank update
           dbg_cyc_cnt <= dbg_cyc_cnt + 32'd1;
           if (in_valid)
               dbg_in_cnt <= dbg_in_cnt + 32'd1;
           if (cfg_we) begin
               dbg_cfg_wr    <= dbg_cfg_wr + 16'd1;
               dbg_last_addr <= cfg_addr;
               dbg_last_bits <= cfg_bits;
           end
           if (a_out_valid)
               dbg_idle_run <= 16'd0;
           else if (dbg_idle_run != 16'hFFFF)
               dbg_idle_run <= dbg_idle_run + 16'd1;
           if (dbg_wdog_ev)
               dbg_wdog_trip <= 1'b1;
           if (dbg_stall) begin
               dbg_stall_run <= dbg_stall_nx;
               if (dbg_stall_nx > dbg_stall_max)
                   dbg_stall_max <= dbg_stall_nx;
           end else begin
               dbg_stall_run <= 16'd0;
           end
           if (a_out_valid)
               dbg_sig <= dbg_sig_nx;
           if (dbg_any_err) begin
               dbg_err_log[dbg_err_wp] <= dbg_err_code;
               dbg_err_wp    <= dbg_err_wp + 2'd1;
               if (dbg_err_cnt != 3'd4)
                   dbg_err_cnt <= dbg_err_cnt + 3'd1;
               dbg_err_flags <= dbg_err_flags | {5'd0, dbg_wdog_ev, dbg_drop_ev, dbg_hazard};
           end
           if (win_start) begin
               dbg_win_seen   <= dbg_win_seen + 16'd1;
               dbg_beats_snap <= o_beats_done[31:0];
           end
           case (cfg_addr[2:0])
               3'd0: dbg_rdata <= dbg_cyc_cnt;
               3'd1: dbg_rdata <= dbg_in_cnt;
               3'd2: dbg_rdata <= {dbg_cfg_wr, 8'd0, dbg_last_addr};
               3'd3: dbg_rdata <= {12'd0, dbg_last_bits};
               3'd4: dbg_rdata <= {dbg_stall_max, dbg_idle_run};
               3'd5: dbg_rdata <= {dbg_win_seen, dbg_stall_run};
               3'd6: dbg_rdata <= {dbg_err_log[3], dbg_err_log[2], dbg_err_log[1], dbg_err_log[0]};
               default: dbg_rdata <= dbg_beats_snap;
           endcase
        end
    end

    lvds_port_perfmon u_mon (
        .clk(clk),
        .rst(rst),
        .en(en),
        .valid(g_valid),
        .ready(ready),
        .data(g_data),
        .win_start(win_start),
        .o_txn_cnt(o_txn_cnt),
        .o_byte_cnt(o_byte_cnt),
        .o_stall_cnt(o_stall_cnt),
        .o_lat_cum(o_lat_cum),
        .o_win_cnt(o_win_cnt),
        .byte_cnt_o(b_byte_cnt),
        .hs_d_o(b_hs_d),
        .seen_txn_o(b_seen_txn),
        .txn_cnt_o(b_txn_cnt)
    );

    assign o_port_valid = g_valid;
    assign o_port_data  = g_data;
    assign o_cap_cnt    = cap_cnt;
    assign o_drop_cnt   = drop_cnt;
   assign o_dbg_rdata  = dbg_rdata;
   assign o_dbg_status = {dbg_wdog_trip, dbg_err_cnt, dbg_err_flags[3:0], dbg_stall_max[7:0],
                          dbg_err_log[dbg_err_rp], dbg_last_addr};
   assign o_dbg_sig    = dbg_sig;

    always @(posedge clk)
        if (!g_valid)
            assert (cap_cnt == b_txn_cnt);
endmodule

module ec_jdbl_seq (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        arm,
    input  wire        start,
    input  wire        clr,
    input  wire        sel_add,
    input  wire        wr_en,
    input  wire [3:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire        o_done,
    output wire [31:0] o_acc,
    output wire [31:0] o_x3
,
    output wire armed_o,
    output wire done_o,
    output wire pre_clr_o,
    output wire started_o,
    output wire [31:0] step_o
);
    localparam [31:0] PRIME = 32'hFFFFFFFB;
    localparam [31:0] LAST  = 32'd11;
    localparam [1:0]  OP_MUL = 2'd0;
    localparam [1:0]  OP_ADD = 2'd1;
    localparam [1:0]  OP_SUB = 2'd2;

    reg        armed;
    reg        started;
    reg        done;
    reg        pre_clr;
    reg        mode;
    reg [31:0] step;
    reg [31:0] acc;
    reg [31:0] rf [0:15];

    integer i;
    initial begin
        armed   = 1'b0;
        started = 1'b0;
        done    = 1'b0;
        pre_clr = 1'b1;
        mode    = 1'b0;
        step    = 32'd0;
        acc     = 32'd0;
        for (i = 0; i < 16; i = i + 1)
            rf[i] = 32'd0;
    end

    function [31:0] fadd;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            s = {1'b0, a} + {1'b0, b};
            if (s >= {1'b0, PRIME})
                s = s - {1'b0, PRIME};
            fadd = s[31:0];
        end
    endfunction

    function [31:0] fsub;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            if (a >= b)
                s = {1'b0, a} - {1'b0, b};
            else
                s = {1'b0, a} + {1'b0, PRIME} - {1'b0, b};
            fsub = s[31:0];
        end
    endfunction

    function [31:0] fmul;
        input [31:0] a;
        input [31:0] b;
        reg [63:0] p;
        reg [35:0] t;
        reg [35:0] u;
        begin
            p = {32'd0, a} * {32'd0, b};
            t = {4'd0, p[31:0]} + {4'd0, p[63:32]} * 36'd5;
            u = {4'd0, t[31:0]} + {32'd0, t[35:32]} * 36'd5;
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            fmul = u[31:0];
        end
    endfunction

    reg [3:0] ra, rb, rd;
    reg [1:0] opc;
    always @(*) begin
        ra  = 4'd0;
        rb  = 4'd0;
        rd  = 4'd6;
        opc = OP_MUL;
        case (step)
            32'd1:  begin ra = 4'd1;  rb = mode ? 4'd4 : 4'd1; rd = 4'd6;  opc = OP_MUL; end
            32'd2:  begin ra = 4'd0;  rb = 4'd6;  rd = 4'd7;  opc = OP_MUL; end
            32'd3:  begin ra = 4'd0;  rb = mode ? 4'd3 : 4'd0; rd = 4'd8;  opc = OP_MUL; end
            32'd4:  begin ra = 4'd8;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd5:  begin ra = 4'd9;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd6:  begin ra = 4'd9;  rb = 4'd9;  rd = 4'd10; opc = OP_MUL; end
            32'd7:  begin ra = 4'd7;  rb = 4'd7;  rd = 4'd11; opc = OP_ADD; end
            32'd8:  begin ra = 4'd10; rb = 4'd11; rd = 4'd12; opc = OP_SUB; end
            32'd9:  begin ra = mode ? 4'd2 : 4'd1; rb = mode ? 4'd5 : 4'd2; rd = 4'd13; opc = OP_MUL; end
            32'd10: begin ra = 4'd6;  rb = 4'd6;  rd = 4'd15; opc = OP_MUL; end
            default: begin ra = 4'd0; rb = 4'd0; rd = 4'd6; opc = OP_MUL; end
        endcase
    end

    wire [31:0] opa = rf[ra];
    wire [31:0] opb = rf[rb];
    reg  [31:0] res;
    always @(*) begin
        case (opc)
            OP_MUL:  res = fmul(opa, opb);
            OP_ADD:  res = fadd(opa, opb);
            OP_SUB:  res = fsub(opa, opb);
            default: res = opa;
        endcase
    end

    wire [31:0] y3 = fsub(fmul(rf[9], fsub(rf[7], rf[12])), rf[15]);
    wire [31:0] z3 = fadd(rf[13], rf[13]);

    always @(posedge clk) begin
        if (rst) begin
            armed   <= 1'b0;
            started <= 1'b0;
            done    <= 1'b0;
            pre_clr <= 1'b1;
            mode    <= 1'b0;
            step    <= 32'd0;
            acc     <= 32'd0;
        end else if (en) begin
            if (clr) begin
                armed   <= 1'b0;
                started <= 1'b0;
                done    <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (arm)
                    armed <= 1'b1;
                if (start && armed && step == 32'd0)
                    started <= 1'b1;
                if (step == LAST)
                    done <= 1'b1;
            end
            if (step == 32'd0) begin
                if (start && armed && !clr) begin
                    step <= 32'd1;
                    mode <= sel_add;
                end
            end else if (step == LAST) begin
                step <= 32'd0;
                acc  <= y3;
            end else begin
                step <= step + 32'd1;
                acc  <= res;
            end
        end
    end

    always @(posedge clk) begin
        if (!rst && en) begin
            if (step == 32'd0) begin
                if (wr_en)
                    rf[wr_addr] <= wr_data;
            end else if (step == LAST) begin
                rf[0] <= rf[12];
                rf[1] <= y3;
                rf[2] <= z3;
            end else begin
                rf[rd] <= res;
            end
        end
    end

    assign o_done = done;
    assign o_acc  = acc;
    assign o_x3   = rf[0];

    always @(*)
        if (pre_clr && done)
            assert (started && armed);
    assign armed_o = armed;
    assign done_o = done;
    assign pre_clr_o = pre_clr;
    assign started_o = started;
    assign step_o = step;
endmodule

module lim_mod_fold (
    input wire clk,
    input wire rst,
    input wire en,
    input wire start,
    input wire vld,
    input wire [63:0] chunk,
    output wire [15:0] res,
    output wire done
,
    output wire [8:0] idx_o,
    output wire [63:0] wexp_o,
    output wire [63:0] wreg_o
);
    localparam [63:0] M = 64'd65521;

    function [63:0] two64;
        input [31:0] dummy;
        integer i;
        reg [63:0] r;
        begin
            r = 64'd1;
            for (i = 0; i < 64; i = i + 1)
                r = (r * 64'd2) % M;
            two64 = r;
        end
    endfunction

    localparam [63:0] K = two64(0);

    function [63:0] kpow;
        input [31:0] n;
        integer i;
        reg [63:0] r;
        begin
            r = 64'd1;
            for (i = 0; i < n; i = i + 1)
                r = (r * K) % M;
            kpow = r;
        end
    endfunction

    localparam [63:0] C = kpow(256);

    reg [63:0] acc;
    reg [63:0] wreg;
    reg [8:0]  idx;
    reg        armed;
    initial acc = 64'd0;
    initial wreg = 64'd1;
    initial idx = 9'd0;
    initial armed = 1'b0;

    wire [64*257-1:0] wflat;
    genvar g;
    generate
        for (g = 0; g < 257; g = g + 1) begin : G_ROM
            localparam [63:0] WV = kpow(g);
            assign wflat[g*64 +: 64] = WV;
        end
    endgenerate

    wire [63:0] wexp = wflat[idx*64 +: 64];

    always @(posedge clk) begin
        if (rst) begin
            acc   <= 64'd0;
            wreg  <= 64'd1;
            idx   <= 9'd0;
            armed <= 1'b0;
        end else if (en) begin
            if (start) begin
                acc   <= 64'd0;
                wreg  <= 64'd1;
                idx   <= 9'd0;
                armed <= 1'b1;
            end else if (vld && (idx < 9'd256)) begin
                acc  <= (acc + (chunk % M) * wreg) % M;
                wreg <= (wreg * K) % M;
                idx  <= idx + 9'd1;
            end
        end
    end

    assign res  = acc[15:0];
    assign done = (idx == 9'd256);

    always @(posedge clk)
        if (armed && idx == 9'd256)
            assert (wreg == C);
    assign idx_o = idx;
    assign wexp_o = wexp;
    assign wreg_o = wreg;
endmodule

module ec_fold_top (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        arm,
    input  wire        start,
    input  wire        clr,
    input  wire        sel_add,
    input  wire        wr_en,
    input  wire [3:0]  wr_addr,
    input  wire [31:0] wr_data,
    input  wire        fold_en,
    input  wire        fold_start,
    output wire        o_done,
    output wire [31:0] o_acc,
    output wire [31:0] o_x3,
    output wire [15:0] fold_res,
    output wire        fold_done,
    output wire [1:0]  q_cnt_o,
    output wire [1:0]  q_v_o,
    output wire        q_wr_o,
    output wire        q_rd_o,
    output wire        q_ovf_o,
    output wire [31:0] q_head_o
);
    wire        a_done;
    wire [31:0] a_acc;
    wire [31:0] a_x3;
    wire        a_armed;
    wire        a_done_m;
    wire        a_pre_clr;
    wire        a_started;
    wire [31:0] a_step;

    wire [15:0] b_res;
    wire        b_done;
    wire [8:0]  b_idx;
    wire [63:0] b_wexp;
    wire [63:0] b_wreg;

    reg        done_q;
    reg [1:0]  q_cnt;
    reg        q_wr;
    reg        q_rd;
    reg [1:0]  q_v;
    reg        q_ovf;
    reg [31:0] q_d [0:1];

    integer k;
    initial begin
        done_q = 1'b0;
        q_cnt  = 2'd0;
        q_wr   = 1'b0;
        q_rd   = 1'b0;
        q_v    = 2'b00;
        q_ovf  = 1'b0;
        for (k = 0; k < 2; k = k + 1)
            q_d[k] = 32'd0;
    end

    wire        a_fin   = a_done && !done_q;
    wire        q_vld   = (q_cnt != 2'd0);
    wire        b_start = fold_start || (b_done && q_vld);
    wire        q_pop   = q_vld && fold_en && !b_start && (b_idx < 9'd256);
    wire        q_push  = a_fin && (q_cnt != 2'd2);
    wire [31:0] q_head  = q_d[q_rd];
    wire [63:0] q_chunk = {32'd0, q_head};

    ec_jdbl_seq u_a (
        .clk(clk), .rst(rst), .en(en), .arm(arm), .start(start), .clr(clr),
        .sel_add(sel_add), .wr_en(wr_en), .wr_addr(wr_addr), .wr_data(wr_data),
        .o_done(a_done), .o_acc(a_acc), .o_x3(a_x3),
        .armed_o(a_armed), .done_o(a_done_m), .pre_clr_o(a_pre_clr),
        .started_o(a_started), .step_o(a_step)
    );

    lim_mod_fold u_b (
        .clk(clk), .rst(rst), .en(fold_en), .start(b_start), .vld(q_vld),
        .chunk(q_chunk), .res(b_res), .done(b_done),
        .idx_o(b_idx), .wexp_o(b_wexp), .wreg_o(b_wreg)
    );

    always @(posedge clk) begin
        if (rst) begin
            done_q <= 1'b0;
            q_cnt  <= 2'd0;
            q_wr   <= 1'b0;
            q_rd   <= 1'b0;
            q_v    <= 2'b00;
            q_ovf  <= 1'b0;
            for (k = 0; k < 2; k = k + 1)
                q_d[k] <= 32'd0;
        end else begin
            done_q <= a_done;
            if (a_fin && q_cnt == 2'd2)
                q_ovf <= 1'b1;
            if (q_push) begin
                q_d[q_wr] <= a_acc;
                q_v[q_wr] <= 1'b1;
                q_wr      <= ~q_wr;
            end
            if (q_pop) begin
                q_v[q_rd] <= 1'b0;
                q_rd      <= ~q_rd;
            end
            case ({q_push, q_pop})
                2'b10:   q_cnt <= q_cnt + 2'd1;
                2'b01:   q_cnt <= q_cnt - 2'd1;
                default: q_cnt <= q_cnt;
            endcase
        end
    end

    always @(*)
        if (q_pop)
            assert (q_v[q_rd]);

    assign o_done    = a_done;
    assign o_acc     = a_acc;
    assign o_x3      = a_x3;
    assign fold_res  = b_res;
    assign fold_done = b_done;
    assign q_cnt_o   = q_cnt;
    assign q_v_o     = q_v;
    assign q_wr_o    = q_wr;
    assign q_rd_o    = q_rd;
    assign q_ovf_o   = q_ovf;
    assign q_head_o  = q_head;
endmodule

module tplan_px_drain (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire abort_req,
   input wire frame_act,
   input wire push,
   input wire push_eof,
   input wire [7:0] push_pix,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire ready,
   output wire drained,
   output wire eof_pend_o,
   output wire [2:0] fill_o,
   output wire [4:0] col_o,
   output wire [7:0] px_o,
   output wire px_vld_o,
   output wire px_eol_o,
   output wire hblank_o,
   output wire [7:0] sig_o,
   output wire [7:0] stall_o
);
   localparam [2:0] DEPTH = 3'd4;
   localparam [4:0] LINE_LAST = 5'd23;

   reg [7:0] fifo [0:3];
   reg [1:0] wr_ptr;
   reg [1:0] rd_ptr;
   reg [2:0] cnt;
   reg [3:0] cfg_div;
   reg [3:0] cfg_hblank;
   reg       cfg_inv;
   reg [7:0] cfg_blank;
   reg [3:0] div_cnt;
   reg [3:0] hb_cnt;
   reg [4:0] col_out;
   reg [7:0] px_q;
   reg       px_vld;
   reg       px_eol;
   reg       eof_pend;
   reg [7:0] sig_run;
   reg [7:0] sig_last;
   reg [7:0] stall_cnt;

   integer j;
   initial begin
       for (j = 0; j < 4; j = j + 1)
           fifo[j] = 8'h00;
   end
   initial wr_ptr = 2'd0;
   initial rd_ptr = 2'd0;
   initial cnt = 3'd0;
   initial cfg_div = 4'd0;
   initial cfg_hblank = 4'd0;
   initial cfg_inv = 1'b0;
   initial cfg_blank = 8'h00;
   initial div_cnt = 4'd0;
   initial hb_cnt = 4'd0;
   initial col_out = 5'd0;
   initial px_q = 8'h00;
   initial px_vld = 1'b0;
   initial px_eol = 1'b0;
   initial eof_pend = 1'b0;
   initial sig_run = 8'h00;
   initial sig_last = 8'h00;
   initial stall_cnt = 8'd0;

   function [7:0] crc8_step;
       input [7:0] c;
       input [7:0] d;
       integer b;
       reg [7:0] x;
       begin
           x = c ^ d;
           for (b = 0; b < 8; b = b + 1)
               x = x[7] ? ((x << 1) ^ 8'h07) : (x << 1);
           crc8_step = x;
       end
   endfunction

   wire full = (cnt == DEPTH);
   wire empty = (cnt == 3'd0);
   wire tick = (div_cnt == 4'd0);
   wire in_hb = (hb_cnt != 4'd0);
   wire acc = push && !full;
   wire pop = tick && !in_hb && !empty;
   wire [7:0] head_pix = fifo[rd_ptr] ^ {8{cfg_inv}};

   assign ready = !full;
   assign drained = eof_pend && empty && tick && !in_hb;
   assign eof_pend_o = eof_pend;
   assign fill_o = cnt;
   assign col_o = col_out;
   assign px_o = px_q;
   assign px_vld_o = px_vld;
   assign px_eol_o = px_eol;
   assign hblank_o = in_hb;
   assign sig_o = sig_last;
   assign stall_o = stall_cnt;

   always @(posedge clk) begin
       if (!rst_n) begin
           for (j = 0; j < 4; j = j + 1)
               fifo[j] <= 8'h00;
           wr_ptr <= 2'd0;
           rd_ptr <= 2'd0;
           cnt <= 3'd0;
           cfg_div <= 4'd0;
           cfg_hblank <= 4'd0;
           cfg_inv <= 1'b0;
           cfg_blank <= 8'h00;
           div_cnt <= 4'd0;
           hb_cnt <= 4'd0;
           col_out <= 5'd0;
           px_q <= 8'h00;
           px_vld <= 1'b0;
           px_eol <= 1'b0;
           eof_pend <= 1'b0;
           sig_run <= 8'h00;
           sig_last <= 8'h00;
           stall_cnt <= 8'd0;
       end else if (en) begin
           if (frame_act && full && !abort_req && (stall_cnt != 8'hFF))
               stall_cnt <= stall_cnt + 8'd1;
           if (csr_we) begin
               case (csr_addr)
                   3'd4: cfg_div <= csr_wdata[3:0];
                   3'd5: cfg_hblank <= csr_wdata[3:0];
                   3'd6: begin
                       cfg_inv <= csr_wdata[0];
                       if (csr_wdata[7])
                           stall_cnt <= 8'd0;
                   end
                   3'd7: cfg_blank <= csr_wdata;
               endcase
           end
           if (abort_req) begin
               wr_ptr <= 2'd0;
               rd_ptr <= 2'd0;
               cnt <= 3'd0;
               div_cnt <= 4'd0;
               hb_cnt <= 4'd0;
               col_out <= 5'd0;
               px_q <= cfg_blank;
               px_vld <= 1'b0;
               px_eol <= 1'b0;
               eof_pend <= 1'b0;
               sig_run <= 8'h00;
           end else begin
               if (acc) begin
                   fifo[wr_ptr] <= push_pix;
                   wr_ptr <= wr_ptr + 2'd1;
                   if (push_eof)
                       eof_pend <= 1'b1;
               end
               if (acc && !pop)
                   cnt <= cnt + 3'd1;
               else if (pop && !acc)
                   cnt <= cnt - 3'd1;
               if (!tick)
                   div_cnt <= div_cnt - 4'd1;
               else if (pop || in_hb)
                   div_cnt <= cfg_div;
               if (tick) begin
                   if (in_hb) begin
                       hb_cnt <= hb_cnt - 4'd1;
                       px_q <= cfg_blank;
                       px_vld <= 1'b0;
                       px_eol <= 1'b0;
                   end else if (pop) begin
                       px_q <= head_pix;
                       px_vld <= 1'b1;
                       rd_ptr <= rd_ptr + 2'd1;
                       sig_run <= crc8_step(sig_run, head_pix);
                       if (col_out == LINE_LAST) begin
                           col_out <= 5'd0;
                           hb_cnt <= cfg_hblank;
                           px_eol <= 1'b1;
                       end else begin
                           col_out <= col_out + 5'd1;
                           px_eol <= 1'b0;
                       end
                   end else begin
                       px_q <= cfg_blank;
                       px_vld <= 1'b0;
                       px_eol <= 1'b0;
                   end
               end
               if (drained) begin
                   eof_pend <= 1'b0;
                   sig_last <= sig_run;
                   sig_run <= 8'h00;
               end
           end
       end
   end
endmodule
module tplan_seq_ctrl (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire [1:0] phase_i,
   input wire start_req,
   input wire abort_req,
   input wire frame_end,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire start_ack,
   output wire fire,
   output wire rearm,
   output wire busy,
   output wire pend_o,
   output wire loop_pend_o,
   output wire ovr_o,
   output wire [3:0] delay_o,
   output wire [3:0] loops_o
);
   reg [3:0] cfg_preroll;
   reg [3:0] cfg_loops;
   reg       cfg_auto;
   reg       pend;
   reg [3:0] delay_cnt;
   reg       loop_pend;
   reg [3:0] loops_left;
   reg       ovr;
   initial cfg_preroll = 4'd0;
   initial cfg_loops = 4'd0;
   initial cfg_auto = 1'b0;
   initial pend = 1'b0;
   initial delay_cnt = 4'd0;
   initial loop_pend = 1'b0;
   initial loops_left = 4'd0;
   initial ovr = 1'b0;
   wire armed = (phase_i == 2'd1);
   wire fin = (phase_i == 2'd3);
   assign start_ack = armed && !pend && !abort_req && (start_req || loop_pend);
   assign fire = pend && (delay_cnt == 4'd0) && !abort_req;
   assign rearm = fin && loop_pend && !abort_req;
   assign busy = pend || loop_pend;
   assign pend_o = pend;
   assign loop_pend_o = loop_pend;
   assign ovr_o = ovr;
   assign delay_o = delay_cnt;
   assign loops_o = loops_left;
   always @(posedge clk) begin
       if (!rst_n) begin
           cfg_preroll <= 4'd0;
           cfg_loops <= 4'd0;
           cfg_auto <= 1'b0;
           pend <= 1'b0;
           delay_cnt <= 4'd0;
           loop_pend <= 1'b0;
           loops_left <= 4'd0;
           ovr <= 1'b0;
       end else if (en) begin
           if (csr_we) begin
               case (csr_addr)
                   3'd0: cfg_preroll <= csr_wdata[3:0];
                   3'd1: cfg_loops <= csr_wdata[3:0];
                   3'd2: cfg_auto <= csr_wdata[0];
                   3'd3: ovr <= 1'b0;
               endcase
           end
           if (start_req && pend && !abort_req)
               ovr <= 1'b1;
           if (abort_req) begin
               pend <= 1'b0;
               delay_cnt <= 4'd0;
               loop_pend <= 1'b0;
               loops_left <= 4'd0;
           end else begin
               if (start_ack) begin
                   pend <= 1'b1;
                   delay_cnt <= cfg_preroll;
                   if (loop_pend) begin
                       loop_pend <= 1'b0;
                       loops_left <= loops_left - 4'd1;
                   end else begin
                       loops_left <= cfg_loops;
                   end
               end else if (pend) begin
                   if (delay_cnt == 4'd0)
                       pend <= 1'b0;
                   else
                       delay_cnt <= delay_cnt - 4'd1;
               end
               if (frame_end && cfg_auto && (loops_left != 4'd0))
                   loop_pend <= 1'b1;
           end
       end
   end
endmodule
module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire o_seq_busy,
  output wire [10:0] o_seq_stat,
  output wire [7:0] o_scan_pix,
  output wire o_scan_vld,
  output wire o_scan_eol,
  output wire o_scan_hblank,
  output wire o_scan_ready,
  output wire o_drain_busy,
  output wire [7:0] o_scan_fill_col,
  output wire [7:0] o_frame_sig,
  output wire [7:0] o_scan_stall
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire seq_start_ack, seq_fire, seq_rearm, seq_busy;
   wire seq_pend, seq_loop_pend, seq_ovr;
   wire [3:0] seq_delay;
   wire [3:0] seq_loops;
  wire dr_ready, dr_drained, dr_eof_pend;
  wire dr_px_vld, dr_px_eol, dr_hblank;
  wire [2:0] dr_fill;
  wire [4:0] dr_col;
  wire [7:0] dr_px;
  wire [7:0] dr_sig;
  wire [7:0] dr_stall;
  wire [7:0] gen_pix = font_row(cur_char, row_cnt[2:0]);
  wire px_push = (phase == RUN) && !abort_req && dr_ready;
  wire frame_end = px_push && last_col && last_row;
   wire csr_we = wr_en && (wr_addr[4:3] == 2'b11);
   tplan_seq_ctrl u_seq (
       .clk(clk),
       .rst_n(rst_n),
       .en(en),
       .phase_i(phase),
       .start_req(start_req),
       .abort_req(abort_req),
       .frame_end(frame_end),
       .csr_we(csr_we),
       .csr_addr(wr_addr[2:0]),
       .csr_wdata(wr_data[7:0]),
       .start_ack(seq_start_ack),
       .fire(seq_fire),
       .rearm(seq_rearm),
       .busy(seq_busy),
       .pend_o(seq_pend),
       .loop_pend_o(seq_loop_pend),
       .ovr_o(seq_ovr),
       .delay_o(seq_delay),
       .loops_o(seq_loops)
   );
  tplan_px_drain u_drain (
      .clk(clk),
      .rst_n(rst_n),
      .en(en),
      .abort_req(abort_req),
      .frame_act(phase == RUN),
      .push(px_push),
      .push_eof(last_col && last_row),
      .push_pix(gen_pix),
      .csr_we(csr_we),
      .csr_addr(wr_addr[2:0]),
      .csr_wdata(wr_data[7:0]),
      .ready(dr_ready),
      .drained(dr_drained),
      .eof_pend_o(dr_eof_pend),
      .fill_o(dr_fill),
      .col_o(dr_col),
      .px_o(dr_px),
      .px_vld_o(dr_px_vld),
      .px_eol_o(dr_px_eol),
      .hblank_o(dr_hblank),
      .sig_o(dr_sig),
      .stall_o(dr_stall)
  );

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                       if (seq_start_ack) begin
                           start_seen <= 1'b1;
                           col_cnt <= 64'd0;
                           row_cnt <= 64'd0;
                       end
                       if (seq_fire)
                           phase <= RUN;
                    end
                    RUN: begin
                      if (dr_ready) begin
                       pix_row <= gen_pix;
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                      end
                    end
                    FIN: begin
                      if ((arm_req || seq_rearm) && !dr_eof_pend) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
              if (dr_drained)
                  done <= 1'b1;
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_seq_busy = seq_busy;
   assign o_seq_stat = {seq_pend, seq_loop_pend, seq_ovr, seq_loops, seq_delay};
  assign o_scan_pix = dr_px;
  assign o_scan_vld = dr_px_vld;
  assign o_scan_eol = dr_px_eol;
  assign o_scan_hblank = dr_hblank;
  assign o_scan_ready = dr_ready;
  assign o_drain_busy = dr_eof_pend;
  assign o_scan_fill_col = {dr_fill, dr_col};
  assign o_frame_sig = dr_sig;
  assign o_scan_stall = dr_stall;

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

// frame preemption controller
// A HOLD control symbol (K-code 0) sent while a frame is in flight suspends
// it so a higher-priority frame can be framed in between; a HOLD sent
// between frames resumes the most recently suspended one. Up to four frames
// can be stacked; o_ready drops when the stack is full and further HOLDs
// inside a frame are refused and counted rather than silently lost.
module fm_preempt_ctl (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [1:0]  i_phase,
    input  wire        i_rd,
    input  wire        i_sof,
    input  wire        i_eof,
    input  wire        i_data_sym,
    input  wire [15:0] i_cur_len,
    output wire        o_suspend,
    output wire        o_resume,
    output wire [9:0]  o_ctl_sym,
    output wire [15:0] o_rest_len,
    output reg  [2:0]  o_depth,
    output wire        o_ready,
    output reg  [15:0] o_preempt_cnt,
    output reg  [15:0] o_resume_cnt,
    output reg  [7:0]  o_refuse_cnt,
    output reg  [11:0] o_max_hold,
    output reg  [7:0]  o_frag_frames,
    output reg  [15:0] o_intr_bytes,
    output reg  [7:0]  o_status
);
    localparam [1:0]  K_HOLD   = 2'd0;
    localparam [1:0]  PH_ALIGN = 2'd1, PH_PKT = 2'd2;
    localparam [2:0]  DEPTH    = 3'd4;
    localparam [11:0] AGE_MAX  = 12'hFFF;
    localparam [3:0]  FRAG_MAX = 4'hF;

    // per-slot context of a suspended frame
    reg [15:0] sv_len  [0:3];
    reg [3:0]  sv_frag [0:3];
    reg [11:0] sv_age  [0:3];
    reg [3:0]  cur_frag;
    reg        full_seen;
    reg        last_was_resume;
    integer i;

    initial begin
        o_depth = 3'd0; o_preempt_cnt = 16'd0; o_resume_cnt = 16'd0; o_refuse_cnt = 8'd0;
        o_max_hold = 12'd0; o_frag_frames = 8'd0; o_intr_bytes = 16'd0; o_status = 8'd0;
        cur_frag = 4'd0; full_seen = 1'b0; last_was_resume = 1'b0;
        for (i = 0; i < 4; i = i + 1) begin
            sv_len[i] = 16'd0; sv_frag[i] = 4'd0; sv_age[i] = 12'd0;
        end
    end

    wire       hold_k   = i_ce && i_k && (i_kcode == K_HOLD);
    wire       full     = (o_depth == DEPTH);
    wire       empty    = (o_depth == 3'd0);
    wire       refused  = hold_k && (i_phase == PH_PKT) && full;
    wire [1:0] push_idx = o_depth[1:0];
    wire [1:0] top_idx  = o_depth[1:0] - 2'd1;
    wire       stale    = !empty && (sv_age[top_idx] == AGE_MAX);
    wire [3:0] frag_nxt = (cur_frag != FRAG_MAX) ? (cur_frag + 4'd1) : cur_frag;

    assign o_ready    = !full;
    assign o_suspend  = hold_k && (i_phase == PH_PKT) && !full;
    assign o_resume   = hold_k && (i_phase == PH_ALIGN) && !empty;
    assign o_rest_len = sv_len[top_idx];
    // K28.0 marks a suspend, K28.4 a resume; both are disparity neutral
    assign o_ctl_sym  = o_suspend ? (i_rd ? 10'b1100001011 : 10'b0011110100)
                                  : (i_rd ? 10'b1100001101 : 10'b0011110010);

    always @(posedge clk) begin
        if (rst) begin
            o_depth <= 3'd0; o_preempt_cnt <= 16'd0; o_resume_cnt <= 16'd0; o_refuse_cnt <= 8'd0;
            o_max_hold <= 12'd0; o_frag_frames <= 8'd0; o_intr_bytes <= 16'd0; o_status <= 8'd0;
            cur_frag <= 4'd0; full_seen <= 1'b0; last_was_resume <= 1'b0;
            for (i = 0; i < 4; i = i + 1) begin
                sv_len[i] <= 16'd0; sv_frag[i] <= 4'd0; sv_age[i] <= 12'd0;
            end
        end else begin
            // slot context: capture on suspend, age while parked
            for (i = 0; i < 4; i = i + 1) begin
                if (o_suspend && (i == push_idx)) begin
                    sv_len[i]  <= i_cur_len;
                    sv_frag[i] <= frag_nxt;
                    sv_age[i]  <= 12'd0;
                end else if (i_ce && (i < o_depth) && (sv_age[i] != AGE_MAX)) begin
                    sv_age[i]  <= sv_age[i] + 12'd1;
                end
            end
            // stack pointer and per-frame fragment tracking
            if (o_suspend) begin
                o_depth         <= o_depth + 3'd1;
                last_was_resume <= 1'b0;
                if (o_depth == DEPTH - 3'd1) full_seen <= 1'b1;
                if (o_preempt_cnt != 16'hFFFF) o_preempt_cnt <= o_preempt_cnt + 16'd1;
            end else if (o_resume) begin
                o_depth         <= o_depth - 3'd1;
                cur_frag        <= sv_frag[top_idx];
                last_was_resume <= 1'b1;
                if (sv_age[top_idx] > o_max_hold) o_max_hold <= sv_age[top_idx];
                if (o_resume_cnt != 16'hFFFF) o_resume_cnt <= o_resume_cnt + 16'd1;
            end else if (i_sof) begin
                cur_frag <= 4'd0;
            end else if (i_eof) begin
                cur_frag <= 4'd0;
                if ((cur_frag != 4'd0) && (o_frag_frames != 8'hFF)) o_frag_frames <= o_frag_frames + 8'd1;
            end
            if (refused && (o_refuse_cnt != 8'hFF)) o_refuse_cnt <= o_refuse_cnt + 8'd1;
            // bytes of other frames sent while at least one frame is parked
            if (i_data_sym && !empty && (o_intr_bytes != 16'hFFFF)) o_intr_bytes <= o_intr_bytes + 16'd1;
            o_status <= {full, empty, stale, last_was_resume, full_seen,
                         (cur_frag != 4'd0), (o_refuse_cnt != 8'd0), (o_intr_bytes != 16'd0)};
        end
    end
endmodule

module fm_link_8b10b_framer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [7:0]  i_data,
    output reg  [9:0]  o_sym,
    output reg         o_rd,
    output reg  [31:0] o_sym_cnt,
output reg  [31:0] o_pkt_cnt,
output reg  [15:0] o_err_cnt,
output reg  [15:0] o_max_len,
output reg         o_wdog,
output reg  [7:0]  o_mon_status,
output wire [2:0]  o_pre_depth,
output wire        o_pre_ready,
output wire [15:0] o_pre_cnt,
output wire [15:0] o_pre_resume_cnt,
output wire [7:0]  o_pre_refuse_cnt,
output wire [11:0] o_pre_max_hold,
output wire [7:0]  o_pre_frag_frames,
output wire [15:0] o_pre_intr_bytes,
output wire [7:0]  o_pre_status
);
    localparam [1:0] K_COMMA = 2'd1, K_SOF = 2'd2, K_EOF = 2'd3;
    localparam [1:0] PH_IDLE = 2'd0, PH_ALIGN = 2'd1, PH_PKT = 2'd2;

    reg [1:0] phase;
    reg seen_comma, seen_start, seen_end;
// link monitor / statistics (debug visibility only)
localparam [11:0] WDOG_LIMIT = 12'd2047;
reg [15:0] idle_cnt;
reg [11:0] wdog_cnt;
reg [15:0] cur_len;
reg [7:0]  rd_hist;
reg [1:0]  last_kcode;
reg        bad_k_seen;

    initial begin
        phase = PH_IDLE; seen_comma = 1'b0; seen_start = 1'b0; seen_end = 1'b0;
        o_sym = 10'd0; o_rd = 1'b0; o_sym_cnt = 32'd0; o_pkt_cnt = 32'd0;
idle_cnt = 16'd0; wdog_cnt = 12'd0; cur_len = 16'd0; rd_hist = 8'd0;
last_kcode = 2'd0; bad_k_seen = 1'b0;
o_err_cnt = 16'd0; o_max_len = 16'd0; o_wdog = 1'b0; o_mon_status = 8'd0;
    end

    function [5:0] enc6;
        input [4:0] x;
        begin
            case (x)
                5'd0:  enc6 = 6'b100111;
                5'd1:  enc6 = 6'b011101;
                5'd2:  enc6 = 6'b101101;
                5'd3:  enc6 = 6'b110001;
                5'd4:  enc6 = 6'b110101;
                5'd5:  enc6 = 6'b101001;
                5'd6:  enc6 = 6'b011001;
                5'd7:  enc6 = 6'b111000;
                5'd8:  enc6 = 6'b111001;
                5'd9:  enc6 = 6'b100101;
                5'd10: enc6 = 6'b010101;
                5'd11: enc6 = 6'b110100;
                5'd12: enc6 = 6'b001101;
                5'd13: enc6 = 6'b101100;
                5'd14: enc6 = 6'b011100;
                5'd15: enc6 = 6'b010111;
                5'd16: enc6 = 6'b011011;
                5'd17: enc6 = 6'b100011;
                5'd18: enc6 = 6'b010011;
                5'd19: enc6 = 6'b110010;
                5'd20: enc6 = 6'b001011;
                5'd21: enc6 = 6'b101010;
                5'd22: enc6 = 6'b011010;
                5'd23: enc6 = 6'b111010;
                5'd24: enc6 = 6'b110011;
                5'd25: enc6 = 6'b100110;
                5'd26: enc6 = 6'b010110;
                5'd27: enc6 = 6'b110110;
                5'd28: enc6 = 6'b001110;
                5'd29: enc6 = 6'b101110;
                5'd30: enc6 = 6'b011110;
                default: enc6 = 6'b101011;
            endcase
        end
    endfunction

    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
                3'd5: enc4 = 4'b1010;
                3'd6: enc4 = 4'b0110;
                default: enc4 = 4'b1110;
            endcase
        end
    endfunction

    function [2:0] ones6;
        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
    wire do_comma = i_ce && i_k && (i_kcode == K_COMMA);
    wire do_sof   = i_ce && i_k && (i_kcode == K_SOF) && (phase == PH_ALIGN);
    wire do_eof   = i_ce && i_k && (i_kcode == K_EOF) && (phase == PH_PKT);
    wire do_data  = i_ce && !i_k;
    // frame preemption: K-code 0 (HOLD) suspends / resumes the frame in flight
    wire        pre_suspend, pre_resume;
    wire [9:0]  pre_sym;
    wire [15:0] pre_rest_len;
    wire [2:0]  pre_depth;
    assign o_pre_depth = pre_depth;
    fm_preempt_ctl u_preempt (
        .clk           (clk),
        .rst           (rst),
        .i_ce          (i_ce),
        .i_k           (i_k),
        .i_kcode       (i_kcode),
        .i_phase       (phase),
        .i_rd          (o_rd),
        .i_sof         (do_sof),
        .i_eof         (do_eof),
        .i_data_sym    (do_data),
        .i_cur_len     (cur_len),
        .o_suspend     (pre_suspend),
        .o_resume      (pre_resume),
        .o_ctl_sym     (pre_sym),
        .o_rest_len    (pre_rest_len),
        .o_depth       (pre_depth),
        .o_ready       (o_pre_ready),
        .o_preempt_cnt (o_pre_cnt),
        .o_resume_cnt  (o_pre_resume_cnt),
        .o_refuse_cnt  (o_pre_refuse_cnt),
        .o_max_hold    (o_pre_max_hold),
        .o_frag_frames (o_pre_frag_frames),
        .o_intr_bytes  (o_pre_intr_bytes),
        .o_status      (o_pre_status)
    );
// monitor-side decodes
wire bad_k        = i_ce && i_k && !do_comma && !do_sof && !do_eof && !pre_suspend && !pre_resume;
wire mon_pkt_data = do_data && (phase == PH_PKT);
wire [15:0] len_nxt = cur_len + 16'd1;

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
idle_cnt <= 16'd0; wdog_cnt <= 12'd0; cur_len <= 16'd0; rd_hist <= 8'd0;
last_kcode <= 2'd0; bad_k_seen <= 1'b0;
o_err_cnt <= 16'd0; o_max_len <= 16'd0; o_wdog <= 1'b0; o_mon_status <= 8'd0;
        end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (pre_suspend) begin
            o_sym      <= pre_sym;
            phase      <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (pre_resume) begin
            o_sym      <= pre_sym;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
if (!rst) begin
// idle cycle counter (saturating)
if (!i_ce && (idle_cnt != 16'hFFFF)) idle_cnt <= idle_cnt + 16'd1;
// illegal / out-of-sequence control symbol logger
if (bad_k) begin
bad_k_seen <= 1'b1;
if (o_err_cnt != 16'hFFFF) o_err_cnt <= o_err_cnt + 16'd1;
end
if (i_ce && i_k) last_kcode <= i_kcode;
// comma watchdog
if (do_comma) begin
wdog_cnt <= 12'd0;
o_wdog   <= 1'b0;
end else if (wdog_cnt != WDOG_LIMIT) begin
wdog_cnt <= wdog_cnt + 12'd1;
end else begin
o_wdog   <= 1'b1;
end
// packet payload length tracker
if (do_sof) begin
cur_len <= 16'd0;
end else if (pre_resume) begin
cur_len <= pre_rest_len;
end else if (mon_pkt_data && (cur_len != 16'hFFFF)) begin
cur_len <= len_nxt;
if (len_nxt > o_max_len) o_max_len <= len_nxt;
end
// running disparity history
if (i_ce) rd_hist <= {rd_hist[6:0], o_rd};
o_mon_status <= {bad_k_seen, (idle_cnt[15:12] != 4'd0), last_kcode, rd_hist[3:0]};
end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));
endmodule

module toast_spi_cs_keeper (
   input  wire        clk,
   input  wire        rst,
   input  wire        en,
   input  wire        hold_done,
   input  wire        gap_end,
   input  wire        launch,
   input  wire        q_empty,
   input  wire [4:0]  head_slv,
   input  wire [4:0]  sel,
   output wire        keep,
   output wire        merge,
   output wire [23:0] rel_mask,
   output wire        held_o,
   output wire [2:0]  burst_o,
   output wire [2:0]  peak_o,
   output wire [7:0]  merge_cnt_o,
   output wire [7:0]  brk_cnt_o,
  output wire [23:0] merged_mask_o,
  output wire [2:0]  burst_nx_o
);
   localparam [2:0] MAX_BURST = 3'd4;

   reg        held        = 1'b0;
   reg [2:0]  burst       = 3'd0;
   reg [2:0]  peak        = 3'd0;
   reg [7:0]  merge_cnt   = 8'd0;
   reg [7:0]  brk_cnt     = 8'd0;
   reg [23:0] merged_mask = 24'd0;

   // CS is carried into the gap when the burst has room and the next frame
   // targets the same slave, or the queue is empty (linger for a follow-up).
   wire       same_slv = (head_slv == sel);
   wire       room     = (burst < MAX_BURST);
   wire       cont     = held && launch && same_slv;
   wire       broken   = held && gap_end && !cont;
   wire [2:0] burst_nx = cont ? burst + 3'd1 : 3'd0;

   assign keep          = hold_done && room && (q_empty || same_slv);
   assign merge         = held && same_slv;
   assign rel_mask      = held ? (24'd1 << sel) : 24'd0;
   assign held_o        = held;
   assign burst_o       = burst;
   assign peak_o        = peak;
   assign merge_cnt_o   = merge_cnt;
   assign brk_cnt_o     = brk_cnt;
   assign merged_mask_o = merged_mask;
  assign burst_nx_o    = burst_nx;

   always @(posedge clk) begin
       if (rst) begin
           held        <= 1'b0;
           burst       <= 3'd0;
           peak        <= 3'd0;
           merge_cnt   <= 8'd0;
           brk_cnt     <= 8'd0;
           merged_mask <= 24'd0;
       end else if (en) begin
           if (hold_done)
               held <= keep;
           else if (gap_end)
               held <= 1'b0;

           if (launch) begin
               burst <= burst_nx;
               if (burst_nx > peak)
                   peak <= burst_nx;
           end

           if (cont) begin
               if (merge_cnt != 8'hFF)
                   merge_cnt <= merge_cnt + 8'd1;
               merged_mask <= merged_mask | (24'd1 << sel);
           end

           if (broken && brk_cnt != 8'hFF)
               brk_cnt <= brk_cnt + 8'd1;
       end
   end
endmodule

module toast_spi_cs_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         push,
    input  wire [4:0]   push_slv,
    input  wire [127:0] push_data,
    input  wire [7:0]   cfg_setup,
    input  wire [7:0]   cfg_hold,
    input  wire [7:0]   cfg_gap,
    output wire [23:0]  cs_n,
    output wire         mosi,
    output wire         busy,
   output wire         full,
   output wire         cs_held,
   output wire [2:0]   cs_burst,
   output wire [2:0]   cs_peak_burst,
   output wire [7:0]   cs_merge_count,
   output wire [7:0]   cs_break_count,
  output wire [23:0]  cs_merged_slaves,
  output wire         trc_d,
  output wire         trc_frm,
  output wire         trc_eor,
  output wire         trc_rdy,
  output wire         trc_busy,
  output wire [3:0]   trc_level,
  output wire [3:0]   trc_hwm,
  output wire [4:0]   trc_last_slv,
  output wire [7:0]   trc_seq
);
    localparam [2:0] ST_IDLE  = 3'd0;
    localparam [2:0] ST_SETUP = 3'd1;
    localparam [2:0] ST_XFER  = 3'd2;
    localparam [2:0] ST_HOLD  = 3'd3;
    localparam [2:0] ST_GAP   = 3'd4;

    reg [2:0]   st     = ST_IDLE;
    reg [4:0]   sel    = 5'd0;
    reg [7:0]   dly    = 8'd0;
    reg [6:0]   bitcnt = 7'd0;
    reg [23:0]  cs_vec = 24'd0;
    reg [127:0] shreg  = 128'd0;

    reg [4:0]   q_slv [0:23];
    reg [127:0] q_dat [0:23];
    reg [4:0]   wptr  = 5'd0;
    reg [4:0]   rptr  = 5'd0;
    reg [4:0]   count = 5'd0;

   // Trace port: every launched frame posts a record into an 8-entry
   // record FIFO; a serializer ships records out on trc_d with a CRC-8.
   localparam [1:0] TX_IDLE = 2'd0;
   localparam [1:0] TX_BODY = 2'd1;
   localparam [1:0] TX_CRC  = 2'd2;
   localparam [1:0] TX_GAP  = 2'd3;
   localparam [7:0] TX_LAST = 8'd178;
   localparam [7:0] TX_IFG  = 8'd3;

   reg [4:0]   lg_slv [0:7];
   reg [2:0]   lg_pos [0:7];
   reg         lg_mrg [0:7];
   reg         lg_fst [0:7];
   reg [7:0]   lg_tsu [0:7];
   reg [7:0]   lg_prv [0:7];
   reg [7:0]   lg_seq [0:7];
   reg [15:0]  lg_ts  [0:7];
   reg [127:0] lg_dat [0:7];
   reg [3:0]   lg_wp  = 4'd0;
   reg [3:0]   lg_rp  = 4'd0;
   reg [3:0]   lg_hwm = 4'd0;
   reg [7:0]   fr_seq = 8'd0;
   reg [15:0]  ts_gap = 16'd0;

   // Per-slave history: sequence number of the last frame sent to a slave
   reg [7:0]   sl_seq [0:23];
   reg [23:0]  sl_seen = 24'd0;

   // Output stage between the record FIFO and the serializer
   reg         oh_vld = 1'b0;
   reg [4:0]   oh_slv = 5'd0;
   reg [2:0]   oh_pos = 3'd0;
   reg         oh_mrg = 1'b0;
   reg         oh_fst = 1'b0;
   reg [7:0]   oh_tsu = 8'd0;
   reg [7:0]   oh_prv = 8'd0;
   reg [7:0]   oh_seq = 8'd0;
   reg [15:0]  oh_ts  = 16'd0;
   reg [127:0] oh_dat = 128'd0;

   reg [1:0]   tx_st  = TX_IDLE;
   reg [7:0]   tx_cnt = 8'd0;
   reg [178:0] tx_sh  = 179'd0;
   reg [7:0]   tx_crc = 8'd0;
   reg         tx_out = 1'b0;
   reg         tx_frm = 1'b0;
   reg         tx_eor = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) begin
            q_slv[i] = 5'd0;
            q_dat[i] = 128'd0;
           sl_seq[i] = 8'd0;
        end
       for (i = 0; i < 8; i = i + 1) begin
           lg_slv[i] = 5'd0;
           lg_pos[i] = 3'd0;
           lg_mrg[i] = 1'b0;
           lg_fst[i] = 1'b0;
           lg_tsu[i] = 8'd0;
           lg_prv[i] = 8'd0;
           lg_seq[i] = 8'd0;
           lg_ts[i]  = 16'd0;
           lg_dat[i] = 128'd0;
       end
    end

    wire [4:0]   head_raw = q_slv[rptr];
    wire [4:0]   head_slv = (head_raw < 5'd24) ? head_raw : 5'd0;
    wire [127:0] head_dat = q_dat[rptr];

   wire [2:0]   lg_wi    = lg_wp[2:0];
   wire [2:0]   lg_ri    = lg_rp[2:0];
   wire [2:0]   lg_last  = lg_wi - 3'd1;
   wire [3:0]   lg_used  = lg_wp - lg_rp;
   wire         lg_empty = (lg_wp == lg_rp);
   wire         lg_full  = (lg_wp == {~lg_rp[3], lg_rp[2:0]});
   wire         lg_rdy   = !lg_full;
   wire         tx_take  = (tx_st == TX_IDLE) && oh_vld;
   wire         oh_load  = !lg_empty && (!oh_vld || tx_take);
   wire         tx_bit   = tx_sh[178];
   wire         tx_cnt_z = (tx_cnt == 8'd0);
   wire         crc_fb   = tx_crc[7] ^ tx_bit;
   wire [7:0]   crc_nx   = {tx_crc[6:0], 1'b0} ^ (crc_fb ? 8'h07 : 8'h00);
   wire [178:0] tx_rec   = {1'b1, oh_slv, oh_pos, oh_mrg, oh_fst, oh_tsu,
                            oh_prv, oh_seq, oh_ts, oh_dat};


   wire can_pop = (count != 5'd0) && lg_rdy &&
                   ((st == ST_IDLE) || ((st == ST_GAP) && (dly == 8'd0)));
   wire [3:0] lg_used_nx = lg_used + {3'd0, can_pop} - {3'd0, oh_load};
    wire do_push = push && (count < 5'd24);

    wire [4:0] wptr_nx = (wptr == 5'd23) ? 5'd0 : wptr + 5'd1;
    wire [4:0] rptr_nx = (rptr == 5'd23) ? 5'd0 : rptr + 5'd1;

   wire        hold_done = (st == ST_HOLD) && (dly == 8'd0);
   wire        gap_end   = (st == ST_GAP) && (dly == 8'd0);
   wire        cs_keep;
   wire        cs_merge;
   wire [23:0] cs_rel;
   wire        kp_held;
   wire [2:0]  kp_burst;
   wire [2:0]  kp_peak;
  wire [2:0]  kp_burst_nx;

   toast_spi_cs_keeper u_keeper (
       .clk           (clk),
       .rst           (rst),
       .en            (en),
       .hold_done     (hold_done),
       .gap_end       (gap_end),
       .launch        (can_pop),
       .q_empty       (count == 5'd0),
       .head_slv      (head_slv),
       .sel           (sel),
       .keep          (cs_keep),
       .merge         (cs_merge),
       .rel_mask      (cs_rel),
       .held_o        (kp_held),
       .burst_o       (kp_burst),
       .peak_o        (kp_peak),
       .merge_cnt_o   (cs_merge_count),
       .brk_cnt_o     (cs_break_count),
      .merged_mask_o (cs_merged_slaves),
      .burst_nx_o    (kp_burst_nx)
   );

   assign cs_held       = kp_held;
   assign cs_burst      = kp_burst;
   assign cs_peak_burst = kp_peak;

    assign cs_n = ~cs_vec;
    assign mosi = shreg[127];
    assign busy = (st != ST_IDLE);
    assign full = (count == 5'd24);

   assign trc_d        = tx_out;
   assign trc_frm      = tx_frm;
   assign trc_eor      = tx_eor;
   assign trc_rdy      = lg_rdy;
   assign trc_busy     = !lg_empty || oh_vld || (tx_st != TX_IDLE);
   assign trc_level    = lg_used;
   assign trc_hwm      = lg_hwm;
   assign trc_last_slv = lg_slv[lg_last];
   assign trc_seq      = fr_seq;

    always @(posedge clk) begin
        if (rst) begin
            st     <= ST_IDLE;
            sel    <= 5'd0;
            dly    <= 8'd0;
            bitcnt <= 7'd0;
            cs_vec <= 24'd0;
            shreg  <= 128'd0;
            wptr   <= 5'd0;
            rptr   <= 5'd0;
            count  <= 5'd0;
           lg_wp   <= 4'd0;
           lg_rp   <= 4'd0;
           lg_hwm  <= 4'd0;
           fr_seq  <= 8'd0;
           ts_gap  <= 16'd0;
           sl_seen <= 24'd0;
           oh_vld  <= 1'b0;
           oh_slv  <= 5'd0;
           oh_pos  <= 3'd0;
           oh_mrg  <= 1'b0;
           oh_fst  <= 1'b0;
           oh_tsu  <= 8'd0;
           oh_prv  <= 8'd0;
           oh_seq  <= 8'd0;
           oh_ts   <= 16'd0;
           oh_dat  <= 128'd0;
           tx_st   <= TX_IDLE;
           tx_cnt  <= 8'd0;
           tx_sh   <= 179'd0;
           tx_crc  <= 8'd0;
           tx_out  <= 1'b0;
           tx_frm  <= 1'b0;
           tx_eor  <= 1'b0;
        end else if (en) begin
            if (do_push) begin
                q_slv[wptr] <= (push_slv < 5'd24) ? push_slv : 5'd0;
                q_dat[wptr] <= push_data;
                wptr <= wptr_nx;
            end
            if (can_pop)
                rptr <= rptr_nx;
            if (do_push && !can_pop)
                count <= count + 5'd1;
            else if (!do_push && can_pop)
                count <= count - 5'd1;

           // Trace capture: every launch posts one record. Launches are
           // held off by lg_rdy, so a record is never dropped.
           if (can_pop) begin
               lg_slv[lg_wi]    <= head_slv;
               lg_pos[lg_wi]    <= kp_burst_nx;
               lg_mrg[lg_wi]    <= cs_merge;
               lg_fst[lg_wi]    <= !sl_seen[head_slv];
               lg_tsu[lg_wi]    <= cs_merge ? 8'd0 : cfg_setup;
               lg_prv[lg_wi]    <= sl_seq[head_slv];
               lg_seq[lg_wi]    <= fr_seq;
               lg_ts[lg_wi]     <= ts_gap;
               lg_dat[lg_wi]    <= head_dat;
               lg_wp            <= lg_wp + 4'd1;
               fr_seq           <= fr_seq + 8'd1;
               sl_seq[head_slv] <= fr_seq;
               sl_seen          <= sl_seen | (24'd1 << head_slv);
               ts_gap           <= 16'd0;
           end else if (ts_gap != 16'hFFFF)
               ts_gap <= ts_gap + 16'd1;
           if (lg_used_nx > lg_hwm)
               lg_hwm <= lg_used_nx;

           // Output stage refills whenever empty or being handed over
           if (oh_load) begin
               oh_vld <= 1'b1;
               oh_slv <= lg_slv[lg_ri];
               oh_pos <= lg_pos[lg_ri];
               oh_mrg <= lg_mrg[lg_ri];
               oh_fst <= lg_fst[lg_ri];
               oh_tsu <= lg_tsu[lg_ri];
               oh_prv <= lg_prv[lg_ri];
               oh_seq <= lg_seq[lg_ri];
               oh_ts  <= lg_ts[lg_ri];
               oh_dat <= lg_dat[lg_ri];
               lg_rp  <= lg_rp + 4'd1;
           end else if (tx_take)
               oh_vld <= 1'b0;

           // Serializer: start bit + record body, then CRC-8, then a gap
           if ((tx_st != TX_IDLE) && !tx_cnt_z)
               tx_cnt <= tx_cnt - 8'd1;
           tx_eor <= 1'b0;
           case (tx_st)
               TX_IDLE: begin
                   if (tx_take) begin
                       tx_sh  <= tx_rec;
                       tx_cnt <= TX_LAST;
                       tx_crc <= 8'd0;
                       tx_st  <= TX_BODY;
                   end
               end
               TX_BODY: begin
                   tx_out <= tx_bit;
                   tx_frm <= 1'b1;
                   tx_crc <= crc_nx;
                   tx_sh  <= {tx_sh[177:0], 1'b0};
                   if (tx_cnt_z) begin
                       tx_cnt <= 8'd7;
                       tx_st  <= TX_CRC;
                   end
               end
               TX_CRC: begin
                   tx_out <= tx_crc[7];
                   tx_crc <= {tx_crc[6:0], 1'b0};
                   if (tx_cnt_z) begin
                       tx_cnt <= TX_IFG;
                       tx_eor <= 1'b1;
                       tx_st  <= TX_GAP;
                   end
               end
               default: begin
                   tx_out <= 1'b0;
                   tx_frm <= 1'b0;
                   if (tx_cnt_z)
                       tx_st <= TX_IDLE;
               end
           endcase

            case (st)
                ST_IDLE: begin
                    if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                    end
                end
                ST_SETUP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        bitcnt <= 7'd127;
                        st     <= ST_XFER;
                    end
                end
                ST_XFER: begin
                    shreg <= {shreg[126:0], 1'b0};
                    if (bitcnt != 7'd0)
                        bitcnt <= bitcnt - 7'd1;
                    else begin
                        dly <= cfg_hold;
                        st  <= ST_HOLD;
                    end
                end
                ST_HOLD: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                       if (!cs_keep)
                           cs_vec <= cs_vec & ~(24'd1 << sel);
                        dly    <= cfg_gap;
                        st     <= ST_GAP;
                    end
                end
                ST_GAP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else if (can_pop) begin
                        sel    <= head_slv;
                       cs_vec <= (cs_vec & ~cs_rel) | (24'd1 << head_slv);
                        shreg  <= head_dat;
                       dly    <= cs_merge ? 8'd0 : cfg_setup;
                        st     <= ST_SETUP;
                   end else begin
                       cs_vec <= cs_vec & ~cs_rel;
                       st     <= ST_IDLE;
                   end
                end
                default: st <= ST_IDLE;
            endcase
        end
    end

    // No two slave selects asserted at once while the sequencer is active
    always @(posedge clk)
        if (st != ST_IDLE)
            assert ((cs_vec & (cs_vec - 24'd1)) == 24'd0);

   // While a frame is on the wire, the newest trace record names the
   // asserted slave select and the keeper's burst position for it.
   always @(posedge clk)
       if (st == ST_SETUP || st == ST_XFER || st == ST_HOLD)
           assert (cs_vec == (24'd1 << lg_slv[lg_last]) &&
                   lg_pos[lg_last] == kp_burst);
endmodule

// link-level replay buffer
// The framer keeps a copy of the most recently completed frame (up to 15
// payload bytes) so the far end can ask for it again without involving the
// sender. Payload is captured into one bank while the other bank holds the
// last committed frame; a clean end-of-frame swaps them. A K-code 3 seen
// between frames is the far end's replay request, relayed in band by the
// sender. It is answered after a randomised backoff whose window widens with
// every retry of the same frame; after three retries the frame is released.
// While a replay is pending, on the wire or in its trailing guard gap,
// o_busy tells the sender to hold its symbols.
module fm_replay_buf (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_sof,
    input  wire        i_eof,
    input  wire        i_wr,
    input  wire [7:0]  i_byte,
    input  wire        i_suspend,
    input  wire        i_req,
    output wire        o_busy,
    output wire        o_accept,
    output wire        o_tx_sof,
    output wire        o_tx_data,
    output wire        o_tx_eof,
    output wire [7:0]  o_tx_byte,
    output reg  [1:0]  o_state,
    output reg         o_have,
    output wire [3:0]  o_len,
    output wire [3:0]  o_seq,
    output reg  [1:0]  o_retry,
    output reg  [15:0] o_replay_cnt,
    output reg  [15:0] o_replay_bytes,
    output reg  [7:0]  o_miss_cnt,
    output reg  [7:0]  o_giveup_cnt,
    output reg  [7:0]  o_dup_cnt,
    output reg  [7:0]  o_skip_cnt,
    output reg  [7:0]  o_crc_err_cnt,
    output reg  [7:0]  o_max_backoff,
    output wire [23:0] o_retry_hist,
    output reg  [7:0]  o_status
);
    localparam [1:0] RP_IDLE = 2'd0, RP_WAIT = 2'd1, RP_SEND = 2'd2, RP_GAP = 2'd3;
    localparam [3:0] CAP_MAX   = 4'd15;
    localparam [1:0] RETRY_MAX = 2'd3;
    localparam [1:0] GAP_TICKS = 2'd3;
    localparam [7:0] HOLDOFF   = 8'hFF;
    localparam [7:0] CRC_INIT  = 8'hFF;

    reg [7:0] mem  [0:31];
    reg [3:0] blen [0:1];
    reg [7:0] bcrc [0:1];
    reg [3:0] bseq [0:1];
    reg [7:0] hist [0:2];
    reg       wbank;
    reg       cap_on;
    reg       cap_ok;
    reg [3:0] cap_ptr;
    reg [7:0] cap_crc;
    reg [3:0] commit_seq;
    reg [3:0] rd_ptr;
    reg [7:0] chk_crc;
    reg [7:0] bo_cnt;
    reg [1:0] gap_cnt;
    reg [7:0] holdoff;
    reg [7:0] seed;
    reg       last_crc_bad;
    integer j;

    initial begin
        o_state = RP_IDLE; o_have = 1'b0; o_retry = 2'd0;
        o_replay_cnt = 16'd0; o_replay_bytes = 16'd0; o_miss_cnt = 8'd0; o_giveup_cnt = 8'd0;
        o_dup_cnt = 8'd0; o_skip_cnt = 8'd0; o_crc_err_cnt = 8'd0; o_max_backoff = 8'd0; o_status = 8'd0;
        wbank = 1'b0; cap_on = 1'b0; cap_ok = 1'b0; cap_ptr = 4'd0; cap_crc = CRC_INIT;
        commit_seq = 4'd0; rd_ptr = 4'd0; chk_crc = CRC_INIT; bo_cnt = 8'd0; gap_cnt = 2'd0;
        holdoff = 8'd0; seed = 8'd0; last_crc_bad = 1'b0;
        for (j = 0; j < 32; j = j + 1) mem[j] = 8'd0;
        for (j = 0; j < 2; j = j + 1) begin
            blen[j] = 4'd0; bcrc[j] = CRC_INIT; bseq[j] = 4'd0;
        end
        for (j = 0; j < 3; j = j + 1) hist[j] = 8'd0;
    end

    // CRC-8 (x^8 + x^2 + x + 1) over one payload byte
    function [7:0] crc8_step;
        input [7:0] c;
        input [7:0] d;
        reg   [7:0] x;
        integer b;
        begin
            x = c ^ d;
            for (b = 0; b < 8; b = b + 1)
                x = x[7] ? ({x[6:0], 1'b0} ^ 8'h07) : {x[6:0], 1'b0};
            crc8_step = x;
        end
    endfunction

    wire       rbank      = ~wbank;
    wire [4:0] wr_addr    = {wbank, cap_ptr};
    wire [4:0] rd_addr    = {rbank, rd_ptr};
    wire [7:0] rd_byte    = mem[rd_addr];
    wire [7:0] ref_crc    = bcrc[rbank];
    // capture side: payload of a frame opened by a fresh SOF
    wire       cap_live   = i_wr && cap_on && cap_ok;
    wire       cap_wr     = cap_live && (cap_ptr != CAP_MAX);
    wire       cap_ovf    = cap_live && (cap_ptr == CAP_MAX);
    wire       commit     = i_eof && cap_on && cap_ok;
    // request classification, only meaningful while no replay is running
    wire       req_idle   = i_req && (o_state == RP_IDLE);
    wire       quiet      = (holdoff == 8'd0);
    wire       req_miss   = req_idle && !o_have;
    wire       req_dup    = req_idle && o_have && !quiet;
    wire       req_giveup = req_idle && o_have && quiet && (o_retry == RETRY_MAX);
    wire       req_ok     = req_idle && o_have && quiet && (o_retry != RETRY_MAX);
    // truncated binary exponential backoff drawn from a free-running slot count
    wire [7:0] bo_mask    = (o_retry == 2'd0) ? 8'h0F : ((o_retry == 2'd1) ? 8'h3F : 8'hFF);
    wire [7:0] bo_load    = seed & bo_mask;
    wire       send_done  = (rd_ptr == o_len);
    wire       crc_bad    = (chk_crc != ref_crc);

    assign o_busy       = (o_state != RP_IDLE);
    assign o_accept     = req_ok;
    assign o_len        = blen[rbank];
    assign o_seq        = bseq[rbank];
    assign o_tx_byte    = rd_byte;
    assign o_tx_sof     = i_ce && (o_state == RP_WAIT) && (bo_cnt == 8'd0);
    assign o_tx_data    = i_ce && (o_state == RP_SEND) && !send_done;
    assign o_tx_eof     = i_ce && (o_state == RP_SEND) && send_done;
    assign o_retry_hist = {hist[2], hist[1], hist[0]};

    always @(posedge clk) begin
        if (rst) begin
            o_state <= RP_IDLE; o_have <= 1'b0; o_retry <= 2'd0;
            o_replay_cnt <= 16'd0; o_replay_bytes <= 16'd0; o_miss_cnt <= 8'd0; o_giveup_cnt <= 8'd0;
            o_dup_cnt <= 8'd0; o_skip_cnt <= 8'd0; o_crc_err_cnt <= 8'd0; o_max_backoff <= 8'd0; o_status <= 8'd0;
            wbank <= 1'b0; cap_on <= 1'b0; cap_ok <= 1'b0; cap_ptr <= 4'd0; cap_crc <= CRC_INIT;
            commit_seq <= 4'd0; rd_ptr <= 4'd0; chk_crc <= CRC_INIT; bo_cnt <= 8'd0; gap_cnt <= 2'd0;
            holdoff <= 8'd0; seed <= 8'd0; last_crc_bad <= 1'b0;
            for (j = 0; j < 32; j = j + 1) mem[j] <= 8'd0;
            for (j = 0; j < 2; j = j + 1) begin
                blen[j] <= 4'd0; bcrc[j] <= CRC_INIT; bseq[j] <= 4'd0;
            end
            for (j = 0; j < 3; j = j + 1) hist[j] <= 8'd0;
        end else begin
            seed <= seed + 8'd1;
            // capture into the write bank; a clean end of frame commits it
            if (i_sof) begin
                cap_on  <= 1'b1;
                cap_ok  <= 1'b1;
                cap_ptr <= 4'd0;
                cap_crc <= CRC_INIT;
            end else if (i_suspend) begin
                // a parked frame comes back in pieces and is not replayable
                cap_on  <= 1'b0;
            end else if (commit) begin
                cap_on      <= 1'b0;
                blen[wbank] <= cap_ptr;
                bcrc[wbank] <= cap_crc;
                bseq[wbank] <= commit_seq;
                commit_seq  <= commit_seq + 4'd1;
                wbank       <= ~wbank;
                o_have      <= 1'b1;
                o_retry     <= 2'd0;
            end else if (i_eof) begin
                cap_on <= 1'b0;
                if (o_skip_cnt != 8'hFF) o_skip_cnt <= o_skip_cnt + 8'd1;
            end else if (cap_wr) begin
                mem[wr_addr] <= i_byte;
                cap_ptr      <= cap_ptr + 4'd1;
                cap_crc      <= crc8_step(cap_crc, i_byte);
            end else if (cap_ovf) begin
                cap_ok <= 1'b0;
            end
            // duplicate filter: requests right after a replay echo the same NAK
            if (commit) begin
                holdoff <= 8'd0;
            end else if ((o_state == RP_GAP) && i_ce && (gap_cnt == 2'd0)) begin
                holdoff <= HOLDOFF;
            end else if (i_ce && !quiet) begin
                holdoff <= holdoff - 8'd1;
            end
            // replay sequencer
            case (o_state)
                RP_IDLE: begin
                    if (req_ok) begin
                        o_state <= RP_WAIT;
                        bo_cnt  <= bo_load;
                        o_retry <= o_retry + 2'd1;
                        if (bo_load > o_max_backoff) o_max_backoff <= bo_load;
                    end else if (req_giveup) begin
                        o_have <= 1'b0;
                        if (o_giveup_cnt != 8'hFF) o_giveup_cnt <= o_giveup_cnt + 8'd1;
                    end else if (req_dup) begin
                        if (o_dup_cnt != 8'hFF) o_dup_cnt <= o_dup_cnt + 8'd1;
                    end else if (req_miss) begin
                        if (o_miss_cnt != 8'hFF) o_miss_cnt <= o_miss_cnt + 8'd1;
                    end
                end
                RP_WAIT: begin
                    if (i_ce) begin
                        if (bo_cnt == 8'd0) begin
                            o_state <= RP_SEND;
                            rd_ptr  <= 4'd0;
                            chk_crc <= CRC_INIT;
                        end else begin
                            bo_cnt  <= bo_cnt - 8'd1;
                        end
                    end
                end
                RP_SEND: begin
                    if (i_ce) begin
                        if (send_done) begin
                            o_state      <= RP_GAP;
                            gap_cnt      <= GAP_TICKS;
                            last_crc_bad <= crc_bad;
                            if (crc_bad && (o_crc_err_cnt != 8'hFF)) o_crc_err_cnt <= o_crc_err_cnt + 8'd1;
                            if (o_replay_cnt != 16'hFFFF) o_replay_cnt <= o_replay_cnt + 16'd1;
                        end else begin
                            rd_ptr  <= rd_ptr + 4'd1;
                            chk_crc <= crc8_step(chk_crc, rd_byte);
                            if (o_replay_bytes != 16'hFFFF) o_replay_bytes <= o_replay_bytes + 16'd1;
                        end
                    end
                end
                default: begin
                    if (i_ce) begin
                        if (gap_cnt == 2'd0) o_state <= RP_IDLE;
                        else gap_cnt <= gap_cnt - 2'd1;
                    end
                end
            endcase
            // accepted replays binned by the retry level they were issued at
            for (j = 0; j < 3; j = j + 1) begin
                if (req_ok && (o_retry == j) && (hist[j] != 8'hFF)) hist[j] <= hist[j] + 8'd1;
            end
            o_status <= {o_busy, o_have, (o_retry == RETRY_MAX), last_crc_bad,
                         cap_on, cap_ok, wbank, !quiet};
        end
    end
endmodule

// frame preemption controller
// A HOLD control symbol (K-code 0) sent while a frame is in flight suspends
// it so a higher-priority frame can be framed in between; a HOLD sent
// between frames resumes the most recently suspended one. Up to four frames
// can be stacked; o_ready drops when the stack is full and further HOLDs
// inside a frame are refused and counted rather than silently lost.
module fm_preempt_ctl (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [1:0]  i_phase,
    input  wire        i_rd,
    input  wire        i_sof,
    input  wire        i_eof,
    input  wire        i_data_sym,
    input  wire [15:0] i_cur_len,
    output wire        o_suspend,
    output wire        o_resume,
    output wire [9:0]  o_ctl_sym,
    output wire [15:0] o_rest_len,
    output reg  [2:0]  o_depth,
    output wire        o_ready,
    output reg  [15:0] o_preempt_cnt,
    output reg  [15:0] o_resume_cnt,
    output reg  [7:0]  o_refuse_cnt,
    output reg  [11:0] o_max_hold,
    output reg  [7:0]  o_frag_frames,
    output reg  [15:0] o_intr_bytes,
    output reg  [7:0]  o_status
);
    localparam [1:0]  K_HOLD   = 2'd0;
    localparam [1:0]  PH_ALIGN = 2'd1, PH_PKT = 2'd2;
    localparam [2:0]  DEPTH    = 3'd4;
    localparam [11:0] AGE_MAX  = 12'hFFF;
    localparam [3:0]  FRAG_MAX = 4'hF;

    // per-slot context of a suspended frame
    reg [15:0] sv_len  [0:3];
    reg [3:0]  sv_frag [0:3];
    reg [11:0] sv_age  [0:3];
    reg [3:0]  cur_frag;
    reg        full_seen;
    reg        last_was_resume;
    integer i;

    initial begin
        o_depth = 3'd0; o_preempt_cnt = 16'd0; o_resume_cnt = 16'd0; o_refuse_cnt = 8'd0;
        o_max_hold = 12'd0; o_frag_frames = 8'd0; o_intr_bytes = 16'd0; o_status = 8'd0;
        cur_frag = 4'd0; full_seen = 1'b0; last_was_resume = 1'b0;
        for (i = 0; i < 4; i = i + 1) begin
            sv_len[i] = 16'd0; sv_frag[i] = 4'd0; sv_age[i] = 12'd0;
        end
    end

    wire       hold_k   = i_ce && i_k && (i_kcode == K_HOLD);
    wire       full     = (o_depth == DEPTH);
    wire       empty    = (o_depth == 3'd0);
    wire       refused  = hold_k && (i_phase == PH_PKT) && full;
    wire [1:0] push_idx = o_depth[1:0];
    wire [1:0] top_idx  = o_depth[1:0] - 2'd1;
    wire       stale    = !empty && (sv_age[top_idx] == AGE_MAX);
    wire [3:0] frag_nxt = (cur_frag != FRAG_MAX) ? (cur_frag + 4'd1) : cur_frag;

    assign o_ready    = !full;
    assign o_suspend  = hold_k && (i_phase == PH_PKT) && !full;
    assign o_resume   = hold_k && (i_phase == PH_ALIGN) && !empty;
    assign o_rest_len = sv_len[top_idx];
    // K28.0 marks a suspend, K28.4 a resume; both are disparity neutral
    assign o_ctl_sym  = o_suspend ? (i_rd ? 10'b1100001011 : 10'b0011110100)
                                  : (i_rd ? 10'b1100001101 : 10'b0011110010);

    always @(posedge clk) begin
        if (rst) begin
            o_depth <= 3'd0; o_preempt_cnt <= 16'd0; o_resume_cnt <= 16'd0; o_refuse_cnt <= 8'd0;
            o_max_hold <= 12'd0; o_frag_frames <= 8'd0; o_intr_bytes <= 16'd0; o_status <= 8'd0;
            cur_frag <= 4'd0; full_seen <= 1'b0; last_was_resume <= 1'b0;
            for (i = 0; i < 4; i = i + 1) begin
                sv_len[i] <= 16'd0; sv_frag[i] <= 4'd0; sv_age[i] <= 12'd0;
            end
        end else begin
            // slot context: capture on suspend, age while parked
            for (i = 0; i < 4; i = i + 1) begin
                if (o_suspend && (i == push_idx)) begin
                    sv_len[i]  <= i_cur_len;
                    sv_frag[i] <= frag_nxt;
                    sv_age[i]  <= 12'd0;
                end else if (i_ce && (i < o_depth) && (sv_age[i] != AGE_MAX)) begin
                    sv_age[i]  <= sv_age[i] + 12'd1;
                end
            end
            // stack pointer and per-frame fragment tracking
            if (o_suspend) begin
                o_depth         <= o_depth + 3'd1;
                last_was_resume <= 1'b0;
                if (o_depth == DEPTH - 3'd1) full_seen <= 1'b1;
                if (o_preempt_cnt != 16'hFFFF) o_preempt_cnt <= o_preempt_cnt + 16'd1;
            end else if (o_resume) begin
                o_depth         <= o_depth - 3'd1;
                cur_frag        <= sv_frag[top_idx];
                last_was_resume <= 1'b1;
                if (sv_age[top_idx] > o_max_hold) o_max_hold <= sv_age[top_idx];
                if (o_resume_cnt != 16'hFFFF) o_resume_cnt <= o_resume_cnt + 16'd1;
            end else if (i_sof) begin
                cur_frag <= 4'd0;
            end else if (i_eof) begin
                cur_frag <= 4'd0;
                if ((cur_frag != 4'd0) && (o_frag_frames != 8'hFF)) o_frag_frames <= o_frag_frames + 8'd1;
            end
            if (refused && (o_refuse_cnt != 8'hFF)) o_refuse_cnt <= o_refuse_cnt + 8'd1;
            // bytes of other frames sent while at least one frame is parked
            if (i_data_sym && !empty && (o_intr_bytes != 16'hFFFF)) o_intr_bytes <= o_intr_bytes + 16'd1;
            o_status <= {full, empty, stale, last_was_resume, full_seen,
                         (cur_frag != 4'd0), (o_refuse_cnt != 8'd0), (o_intr_bytes != 16'd0)};
        end
    end
endmodule

module fm_link_8b10b_framer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [7:0]  i_data,
    output reg  [9:0]  o_sym,
    output reg         o_rd,
    output reg  [31:0] o_sym_cnt,
output reg  [31:0] o_pkt_cnt,
output reg  [15:0] o_err_cnt,
output reg  [15:0] o_max_len,
output reg         o_wdog,
output reg  [7:0]  o_mon_status,
output wire [2:0]  o_pre_depth,
output wire        o_pre_ready,
output wire [15:0] o_pre_cnt,
output wire [15:0] o_pre_resume_cnt,
output wire [7:0]  o_pre_refuse_cnt,
output wire [11:0] o_pre_max_hold,
output wire [7:0]  o_pre_frag_frames,
output wire [15:0] o_pre_intr_bytes,
output wire [7:0]  o_pre_status,
output wire        o_tx_ready,
output wire [1:0]  o_rp_state,
output wire        o_rp_have,
output wire [3:0]  o_rp_len,
output wire [3:0]  o_rp_seq,
output wire [1:0]  o_rp_retry,
output wire [15:0] o_rp_cnt,
output wire [15:0] o_rp_bytes,
output wire [7:0]  o_rp_miss_cnt,
output wire [7:0]  o_rp_giveup_cnt,
output wire [7:0]  o_rp_dup_cnt,
output wire [7:0]  o_rp_skip_cnt,
output wire [7:0]  o_rp_crc_err_cnt,
output wire [7:0]  o_rp_max_backoff,
output wire [23:0] o_rp_retry_hist,
output wire [7:0]  o_rp_status
);
    localparam [1:0] K_COMMA = 2'd1, K_SOF = 2'd2, K_EOF = 2'd3;
    localparam [1:0] PH_IDLE = 2'd0, PH_ALIGN = 2'd1, PH_PKT = 2'd2;

    reg [1:0] phase;
    reg seen_comma, seen_start, seen_end;
// link monitor / statistics (debug visibility only)
localparam [11:0] WDOG_LIMIT = 12'd2047;
reg [15:0] idle_cnt;
reg [11:0] wdog_cnt;
reg [15:0] cur_len;
reg [7:0]  rd_hist;
reg [1:0]  last_kcode;
reg        bad_k_seen;

    initial begin
        phase = PH_IDLE; seen_comma = 1'b0; seen_start = 1'b0; seen_end = 1'b0;
        o_sym = 10'd0; o_rd = 1'b0; o_sym_cnt = 32'd0; o_pkt_cnt = 32'd0;
idle_cnt = 16'd0; wdog_cnt = 12'd0; cur_len = 16'd0; rd_hist = 8'd0;
last_kcode = 2'd0; bad_k_seen = 1'b0;
o_err_cnt = 16'd0; o_max_len = 16'd0; o_wdog = 1'b0; o_mon_status = 8'd0;
    end

    function [5:0] enc6;
        input [4:0] x;
        begin
            case (x)
                5'd0:  enc6 = 6'b100111;
                5'd1:  enc6 = 6'b011101;
                5'd2:  enc6 = 6'b101101;
                5'd3:  enc6 = 6'b110001;
                5'd4:  enc6 = 6'b110101;
                5'd5:  enc6 = 6'b101001;
                5'd6:  enc6 = 6'b011001;
                5'd7:  enc6 = 6'b111000;
                5'd8:  enc6 = 6'b111001;
                5'd9:  enc6 = 6'b100101;
                5'd10: enc6 = 6'b010101;
                5'd11: enc6 = 6'b110100;
                5'd12: enc6 = 6'b001101;
                5'd13: enc6 = 6'b101100;
                5'd14: enc6 = 6'b011100;
                5'd15: enc6 = 6'b010111;
                5'd16: enc6 = 6'b011011;
                5'd17: enc6 = 6'b100011;
                5'd18: enc6 = 6'b010011;
                5'd19: enc6 = 6'b110010;
                5'd20: enc6 = 6'b001011;
                5'd21: enc6 = 6'b101010;
                5'd22: enc6 = 6'b011010;
                5'd23: enc6 = 6'b111010;
                5'd24: enc6 = 6'b110011;
                5'd25: enc6 = 6'b100110;
                5'd26: enc6 = 6'b010110;
                5'd27: enc6 = 6'b110110;
                5'd28: enc6 = 6'b001110;
                5'd29: enc6 = 6'b101110;
                5'd30: enc6 = 6'b011110;
                default: enc6 = 6'b101011;
            endcase
        end
    endfunction

    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
                3'd5: enc4 = 4'b1010;
                3'd6: enc4 = 4'b0110;
                default: enc4 = 4'b1110;
            endcase
        end
    endfunction

    function [2:0] ones6;
        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // link-level replay: while the buffer re-sends a frame it owns the line
    wire        rp_busy, rp_accept, rp_tx_sof, rp_tx_data, rp_tx_eof;
    wire [7:0]  rp_tx_byte;
    wire [1:0]  rp_state;
    wire        rp_have;
    wire        up_ce    = i_ce && !rp_busy;
    wire [7:0]  enc_byte = rp_tx_data ? rp_tx_byte : i_data;

    // 5b/6b sub-block with running-disparity selection
wire [5:0] c6m    = enc6(enc_byte[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
wire       alt6   = !bal6 || (enc_byte[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
wire [3:0] c4m    = enc4(enc_byte[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
wire       alt4   = !bal4 || (enc_byte[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
wire do_comma = up_ce && i_k && (i_kcode == K_COMMA);
wire do_sof   = up_ce && i_k && (i_kcode == K_SOF) && (phase == PH_ALIGN);
wire do_eof   = up_ce && i_k && (i_kcode == K_EOF) && (phase == PH_PKT);
wire do_data  = up_ce && !i_k;
// K-code 3 between frames: the far end asks for the last frame again
wire rp_req   = up_ce && i_k && (i_kcode == K_EOF) && (phase == PH_ALIGN);
    // frame preemption: K-code 0 (HOLD) suspends / resumes the frame in flight
    wire        pre_suspend, pre_resume;
    wire [9:0]  pre_sym;
    wire [15:0] pre_rest_len;
    wire [2:0]  pre_depth;
    assign o_pre_depth = pre_depth;
    fm_preempt_ctl u_preempt (
        .clk           (clk),
        .rst           (rst),
.i_ce          (up_ce),
        .i_k           (i_k),
        .i_kcode       (i_kcode),
        .i_phase       (phase),
        .i_rd          (o_rd),
        .i_sof         (do_sof),
        .i_eof         (do_eof),
        .i_data_sym    (do_data),
        .i_cur_len     (cur_len),
        .o_suspend     (pre_suspend),
        .o_resume      (pre_resume),
        .o_ctl_sym     (pre_sym),
        .o_rest_len    (pre_rest_len),
        .o_depth       (pre_depth),
        .o_ready       (o_pre_ready),
        .o_preempt_cnt (o_pre_cnt),
        .o_resume_cnt  (o_pre_resume_cnt),
        .o_refuse_cnt  (o_pre_refuse_cnt),
        .o_max_hold    (o_pre_max_hold),
        .o_frag_frames (o_pre_frag_frames),
        .o_intr_bytes  (o_pre_intr_bytes),
        .o_status      (o_pre_status)
    );
// monitor-side decodes
wire bad_k        = up_ce && i_k && !do_comma && !do_sof && !do_eof && !pre_suspend && !pre_resume && !rp_accept;
wire mon_pkt_data = do_data && (phase == PH_PKT);
wire [15:0] len_nxt = cur_len + 16'd1;
    // replay buffer: captures fresh frames, re-sends the last one on request
    fm_replay_buf u_replay (
        .clk            (clk),
        .rst            (rst),
        .i_ce           (i_ce),
        .i_sof          (do_sof),
        .i_eof          (do_eof),
        .i_wr           (mon_pkt_data),
        .i_byte         (i_data),
        .i_suspend      (pre_suspend),
        .i_req          (rp_req),
        .o_busy         (rp_busy),
        .o_accept       (rp_accept),
        .o_tx_sof       (rp_tx_sof),
        .o_tx_data      (rp_tx_data),
        .o_tx_eof       (rp_tx_eof),
        .o_tx_byte      (rp_tx_byte),
        .o_state        (rp_state),
        .o_have         (rp_have),
        .o_len          (o_rp_len),
        .o_seq          (o_rp_seq),
        .o_retry        (o_rp_retry),
        .o_replay_cnt   (o_rp_cnt),
        .o_replay_bytes (o_rp_bytes),
        .o_miss_cnt     (o_rp_miss_cnt),
        .o_giveup_cnt   (o_rp_giveup_cnt),
        .o_dup_cnt      (o_rp_dup_cnt),
        .o_skip_cnt     (o_rp_skip_cnt),
        .o_crc_err_cnt  (o_rp_crc_err_cnt),
        .o_max_backoff  (o_rp_max_backoff),
        .o_retry_hist   (o_rp_retry_hist),
        .o_status       (o_rp_status)
    );
    assign o_tx_ready = !rp_busy;
    assign o_rp_state = rp_state;
    assign o_rp_have  = rp_have;

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
idle_cnt <= 16'd0; wdog_cnt <= 12'd0; cur_len <= 16'd0; rd_hist <= 8'd0;
last_kcode <= 2'd0; bad_k_seen <= 1'b0;
o_err_cnt <= 16'd0; o_max_len <= 16'd0; o_wdog <= 1'b0; o_mon_status <= 8'd0;
        end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (pre_suspend) begin
            o_sym      <= pre_sym;
            phase      <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (pre_resume) begin
            o_sym      <= pre_sym;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (rp_tx_sof) begin
            // a replayed frame opens with the ordinary SOF code
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (rp_tx_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (rp_tx_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
if (!rst) begin
// idle cycle counter (saturating)
if (!i_ce && (idle_cnt != 16'hFFFF)) idle_cnt <= idle_cnt + 16'd1;
// illegal / out-of-sequence control symbol logger
if (bad_k) begin
bad_k_seen <= 1'b1;
if (o_err_cnt != 16'hFFFF) o_err_cnt <= o_err_cnt + 16'd1;
end
if (i_ce && i_k) last_kcode <= i_kcode;
// comma watchdog
if (do_comma) begin
wdog_cnt <= 12'd0;
o_wdog   <= 1'b0;
end else if (wdog_cnt != WDOG_LIMIT) begin
wdog_cnt <= wdog_cnt + 12'd1;
end else begin
o_wdog   <= 1'b1;
end
// packet payload length tracker
if (do_sof) begin
cur_len <= 16'd0;
end else if (pre_resume) begin
cur_len <= pre_rest_len;
end else if (mon_pkt_data && (cur_len != 16'hFFFF)) begin
cur_len <= len_nxt;
if (len_nxt > o_max_len) o_max_len <= len_nxt;
end
// running disparity history
if (i_ce) rd_hist <= {rd_hist[6:0], o_rd};
o_mon_status <= {bad_k_seen, (idle_cnt[15:12] != 4'd0), last_kcode, rd_hist[3:0]};
end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));
endmodule

module ec_jdbl_seq (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        arm,
    input  wire        start,
    input  wire        clr,
    input  wire        sel_add,
    input  wire        wr_en,
    input  wire [3:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire        o_done,
    output wire [31:0] o_acc,
output wire [31:0] o_x3,
output wire        o_cmd_ready,
output wire [3:0]  o_cmd_level,
output wire        o_cmd_ovf,
output wire [3:0]  o_pend_go,
output wire        o_busy,
output wire [7:0]  o_seq_cnt,
output wire [7:0]  o_stall_cnt,
output wire [15:0] o_dirty,
output wire        o_lq_ready,
output wire [2:0]  o_lq_level,
output wire [3:0]  o_lq_vld,
output wire [2:0]  o_lq_alt,
output wire [3:0]  o_lq_gap,
output wire        o_lq_ovf,
output wire [2:0]  o_lq_hwm,
output wire [7:0]  o_lq_hwait,
output wire [7:0]  o_lq_maxwait,
output wire        o_run_src
);
    localparam [31:0] PRIME = 32'hFFFFFFFB;
    localparam [31:0] LAST  = 32'd11;
    localparam [1:0]  OP_MUL = 2'd0;
    localparam [1:0]  OP_ADD = 2'd1;
    localparam [1:0]  OP_SUB = 2'd2;

    reg        armed;
    reg        started;
    reg        done;
    reg        pre_clr;
    reg        mode;
    reg [31:0] step;
    reg [31:0] acc;
    reg [31:0] rf [0:15];
reg        cq_we   [0:7];
reg [3:0]  cq_addr [0:7];
reg [31:0] cq_data [0:7];
reg        cq_go   [0:7];
reg        cq_mode [0:7];
reg [3:0]  cq_wptr;
reg [3:0]  cq_rptr;
reg        cs_v;
reg        cs_we;
reg [3:0]  cs_addr;
reg [31:0] cs_data;
reg        cs_go;
reg        cs_mode;
reg        cq_ovf;
reg [7:0]  seq_cnt;
reg [7:0]  stall_cnt;
reg [15:0] rf_dirty;
reg        lq_mode [0:3];
reg [3:0]  lq_bar  [0:3];
reg [2:0]  lq_wptr;
reg [2:0]  lq_rptr;
reg        lq_ovf;
reg [2:0]  lq_hwm;
reg [7:0]  lq_hwait;
reg [7:0]  lq_maxwait;
reg        cs_src;
reg        run_src;

    integer i;
    initial begin
        armed   = 1'b0;
        started = 1'b0;
        done    = 1'b0;
        pre_clr = 1'b1;
        mode    = 1'b0;
        step    = 32'd0;
        acc     = 32'd0;
        for (i = 0; i < 16; i = i + 1)
            rf[i] = 32'd0;
cq_wptr   = 4'd0;
cq_rptr   = 4'd0;
cs_v      = 1'b0;
cs_we     = 1'b0;
cs_addr   = 4'd0;
cs_data   = 32'd0;
cs_go     = 1'b0;
cs_mode   = 1'b0;
cq_ovf    = 1'b0;
seq_cnt   = 8'd0;
stall_cnt = 8'd0;
rf_dirty  = 16'd0;
lq_wptr    = 3'd0;
lq_rptr    = 3'd0;
lq_ovf     = 1'b0;
lq_hwm     = 3'd0;
lq_hwait   = 8'd0;
lq_maxwait = 8'd0;
cs_src     = 1'b0;
run_src    = 1'b0;
for (i = 0; i < 4; i = i + 1) begin
lq_mode[i] = 1'b0;
lq_bar[i]  = 4'd0;
end
for (i = 0; i < 8; i = i + 1) begin
cq_we[i]   = 1'b0;
cq_addr[i] = 4'd0;
cq_data[i] = 32'd0;
cq_go[i]   = 1'b0;
cq_mode[i] = 1'b0;
end
    end

    function [31:0] fadd;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            s = {1'b0, a} + {1'b0, b};
            if (s >= {1'b0, PRIME})
                s = s - {1'b0, PRIME};
            fadd = s[31:0];
        end
    endfunction

    function [31:0] fsub;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            if (a >= b)
                s = {1'b0, a} - {1'b0, b};
            else
                s = {1'b0, a} + {1'b0, PRIME} - {1'b0, b};
            fsub = s[31:0];
        end
    endfunction

    function [31:0] fmul;
        input [31:0] a;
        input [31:0] b;
        reg [63:0] p;
        reg [35:0] t;
        reg [35:0] u;
        begin
            p = {32'd0, a} * {32'd0, b};
            t = {4'd0, p[31:0]} + {4'd0, p[63:32]} * 36'd5;
            u = {4'd0, t[31:0]} + {32'd0, t[35:32]} * 36'd5;
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            fmul = u[31:0];
        end
    endfunction

    reg [3:0] ra, rb, rd;
    reg [1:0] opc;
    always @(*) begin
        ra  = 4'd0;
        rb  = 4'd0;
        rd  = 4'd6;
        opc = OP_MUL;
        case (step)
            32'd1:  begin ra = 4'd1;  rb = mode ? 4'd4 : 4'd1; rd = 4'd6;  opc = OP_MUL; end
            32'd2:  begin ra = 4'd0;  rb = 4'd6;  rd = 4'd7;  opc = OP_MUL; end
            32'd3:  begin ra = 4'd0;  rb = mode ? 4'd3 : 4'd0; rd = 4'd8;  opc = OP_MUL; end
            32'd4:  begin ra = 4'd8;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd5:  begin ra = 4'd9;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd6:  begin ra = 4'd9;  rb = 4'd9;  rd = 4'd10; opc = OP_MUL; end
            32'd7:  begin ra = 4'd7;  rb = 4'd7;  rd = 4'd11; opc = OP_ADD; end
            32'd8:  begin ra = 4'd10; rb = 4'd11; rd = 4'd12; opc = OP_SUB; end
            32'd9:  begin ra = mode ? 4'd2 : 4'd1; rb = mode ? 4'd5 : 4'd2; rd = 4'd13; opc = OP_MUL; end
            32'd10: begin ra = 4'd6;  rb = 4'd6;  rd = 4'd15; opc = OP_MUL; end
            default: begin ra = 4'd0; rb = 4'd0; rd = 4'd6; opc = OP_MUL; end
        endcase
    end

    wire [31:0] opa = rf[ra];
    wire [31:0] opb = rf[rb];
    reg  [31:0] res;
    always @(*) begin
        case (opc)
            OP_MUL:  res = fmul(opa, opb);
            OP_ADD:  res = fadd(opa, opb);
            OP_SUB:  res = fsub(opa, opb);
            default: res = opa;
        endcase
    end

    wire [31:0] y3 = fsub(fmul(rf[9], fsub(rf[7], rf[12])), rf[15]);
    wire [31:0] z3 = fadd(rf[13], rf[13]);
wire        cq_empty  = (cq_wptr == cq_rptr);
wire        cq_full   = (cq_wptr[3] != cq_rptr[3]) && (cq_wptr[2:0] == cq_rptr[2:0]);
wire [3:0]  cq_level  = cq_wptr - cq_rptr;
wire [2:0]  cq_widx   = cq_wptr[2:0];
wire [2:0]  cq_ridx   = cq_rptr[2:0];
wire        cq_flush  = en && clr;
wire        cmd_go    = start && armed && !cq_flush;
wire        lq_req    = cmd_go && !wr_en;
wire        cmd_req   = wr_en;
wire        cq_push   = cmd_req && !cq_full;
wire        cs_fire   = en && !clr && cs_v && (step == 32'd0);
wire        cs_launch = cs_fire && cs_go;
wire        lq_empty  = (lq_wptr == lq_rptr);
wire        lq_full   = (lq_wptr[2] != lq_rptr[2]) && (lq_wptr[1:0] == lq_rptr[1:0]);
wire [2:0]  lq_level  = lq_wptr - lq_rptr;
wire [1:0]  lq_widx   = lq_wptr[1:0];
wire [1:0]  lq_ridx   = lq_rptr[1:0];
wire        lq_push   = lq_req && !lq_full;
wire [3:0]  lq_gap    = lq_bar[lq_ridx] - cq_rptr;
wire        lq_head_rdy = !lq_empty && (lq_gap == 4'd0);
wire        cs_slot   = en && !clr && (!cs_v || cs_fire);
wire        lq_pop    = cs_slot && lq_head_rdy;
wire        cq_pop    = cs_slot && !cq_empty && !lq_head_rdy;
reg [3:0] cq_pend_go;
reg [2:0] cq_off;
integer   j;
always @(*) begin
cq_pend_go = 4'd0;
for (j = 0; j < 8; j = j + 1) begin
cq_off = j - cq_ridx;
if (cq_go[j] && ({1'b0, cq_off} < cq_level))
cq_pend_go = cq_pend_go + 4'd1;
end
end
reg [3:0] lq_vld;
reg [2:0] lq_alt;
reg [1:0] lq_off;
integer   n;
always @(*) begin
lq_vld = 4'd0;
lq_alt = 3'd0;
for (n = 0; n < 4; n = n + 1) begin
lq_off = n - lq_ridx;
if ({1'b0, lq_off} < lq_level) begin
lq_vld[n] = 1'b1;
if (lq_mode[n])
lq_alt = lq_alt + 3'd1;
end
end
end

    always @(posedge clk) begin
        if (rst) begin
            armed   <= 1'b0;
            started <= 1'b0;
            done    <= 1'b0;
            pre_clr <= 1'b1;
            mode    <= 1'b0;
            step    <= 32'd0;
            acc     <= 32'd0;
cq_wptr   <= 4'd0;
cq_rptr   <= 4'd0;
cs_v      <= 1'b0;
cs_we     <= 1'b0;
cs_addr   <= 4'd0;
cs_data   <= 32'd0;
cs_go     <= 1'b0;
cs_mode   <= 1'b0;
cq_ovf    <= 1'b0;
seq_cnt   <= 8'd0;
stall_cnt <= 8'd0;
rf_dirty  <= 16'd0;
lq_wptr    <= 3'd0;
lq_rptr    <= 3'd0;
lq_ovf     <= 1'b0;
lq_hwm     <= 3'd0;
lq_hwait   <= 8'd0;
lq_maxwait <= 8'd0;
cs_src     <= 1'b0;
run_src    <= 1'b0;
for (i = 0; i < 4; i = i + 1) begin
lq_mode[i] <= 1'b0;
lq_bar[i]  <= 4'd0;
end
for (i = 0; i < 8; i = i + 1) begin
cq_we[i]   <= 1'b0;
cq_addr[i] <= 4'd0;
cq_data[i] <= 32'd0;
cq_go[i]   <= 1'b0;
cq_mode[i] <= 1'b0;
end
end else begin
if (en) begin
            if (clr) begin
                armed   <= 1'b0;
                started <= 1'b0;
                done    <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (arm)
                    armed <= 1'b1;
if (cs_launch)
                    started <= 1'b1;
                if (step == LAST)
                    done <= 1'b1;
            end
            if (step == 32'd0) begin
if (cs_launch) begin
                    step <= 32'd1;
mode <= cs_mode;
                end
            end else if (step == LAST) begin
                step <= 32'd0;
                acc  <= y3;
            end else begin
                step <= step + 32'd1;
                acc  <= res;
            end
        end
if (cq_push) begin
cq_we[cq_widx]   <= wr_en;
cq_addr[cq_widx] <= wr_addr;
cq_data[cq_widx] <= wr_data;
cq_go[cq_widx]   <= cmd_go;
cq_mode[cq_widx] <= sel_add;
cq_wptr          <= cq_wptr + 4'd1;
end
if (lq_push) begin
lq_mode[lq_widx] <= sel_add;
lq_bar[lq_widx]  <= cq_wptr;
lq_wptr          <= lq_wptr + 3'd1;
if (lq_level >= lq_hwm)
lq_hwm <= lq_level + 3'd1;
end
if (cq_flush) begin
cq_rptr   <= cq_wptr;
cs_v      <= 1'b0;
cq_ovf    <= 1'b0;
stall_cnt <= 8'd0;
lq_rptr   <= lq_wptr;
lq_ovf    <= 1'b0;
lq_hwait  <= 8'd0;
end else begin
if (cq_pop) begin
cs_v    <= 1'b1;
cs_we   <= cq_we[cq_ridx];
cs_addr <= cq_addr[cq_ridx];
cs_data <= cq_data[cq_ridx];
cs_go   <= cq_go[cq_ridx];
cs_mode <= cq_mode[cq_ridx];
cq_rptr <= cq_rptr + 4'd1;
cs_src  <= 1'b0;
end else if (lq_pop) begin
cs_v    <= 1'b1;
cs_we   <= 1'b0;
cs_go   <= 1'b1;
cs_mode <= lq_mode[lq_ridx];
cs_src  <= 1'b1;
lq_rptr <= lq_rptr + 3'd1;
end else if (cs_fire) begin
cs_v <= 1'b0;
end
if (cs_fire) begin
if (cs_go)
rf_dirty <= 16'd0;
else if (cs_we)
rf_dirty[cs_addr] <= 1'b1;
end
if (cs_launch)
seq_cnt <= seq_cnt + 8'd1;
if (cs_launch)
run_src <= cs_src;
if (cs_v && !cs_fire && stall_cnt != 8'hFF)
stall_cnt <= stall_cnt + 8'd1;
if (lq_pop) begin
lq_hwait <= 8'd0;
if (lq_hwait > lq_maxwait)
lq_maxwait <= lq_hwait;
end else if (!lq_empty && lq_hwait != 8'hFF) begin
lq_hwait <= lq_hwait + 8'd1;
end
end
if (cmd_req && cq_full)
cq_ovf <= 1'b1;
if (lq_req && lq_full)
lq_ovf <= 1'b1;
end
    end

    always @(posedge clk) begin
        if (!rst && en) begin
            if (step == 32'd0) begin
if (cs_fire && cs_we)
rf[cs_addr] <= cs_data;
            end else if (step == LAST) begin
                rf[0] <= rf[12];
                rf[1] <= y3;
                rf[2] <= z3;
            end else begin
                rf[rd] <= res;
            end
        end
    end

    assign o_done = done;
    assign o_acc  = acc;
    assign o_x3   = rf[0];
assign o_cmd_ready = !cq_full;
assign o_cmd_level = cq_level;
assign o_cmd_ovf   = cq_ovf;
assign o_pend_go   = cq_pend_go + {1'b0, lq_level} + {3'd0, cs_v && cs_go};
assign o_busy      = (step != 32'd0) || cs_v || !cq_empty || !lq_empty;
assign o_seq_cnt   = seq_cnt;
assign o_stall_cnt = stall_cnt;
assign o_dirty     = rf_dirty;
assign o_lq_ready  = !lq_full;
assign o_lq_level  = lq_level;
assign o_lq_vld    = lq_vld;
assign o_lq_alt    = lq_alt;
assign o_lq_gap    = lq_empty ? 4'd0 : lq_gap;
assign o_lq_ovf    = lq_ovf;
assign o_lq_hwm    = lq_hwm;
assign o_lq_hwait  = lq_hwait;
assign o_lq_maxwait = lq_maxwait;
assign o_run_src   = run_src;

    always @(*)
        if (pre_clr && done)
            assert (started && armed);
endmodule

module tplan_commit_gov (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire launch_i,
   input wire restart_i,
   input wire abort_req,
   input wire frame_end_i,
   input wire [2:0] slot_i,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [15:0] csr_wdata,
   output wire go_o,
   output wire pend_o,
   output wire rdy_o,
   output wire irq_o,
   output wire forced_o,
   output wire [3:0] settle_o,
   output wire [3:0] age_o,
   output wire [3:0] stall_o,
   output wire [2:0] why_o,
   output wire [2:0] credits_o,
   output wire [2:0] debt_o,
   output wire [2:0] cred_min_o,
   output wire [3:0] refill_o,
   output wire [3:0] waste_o,
   output wire [3:0] stall_max_o,
   output wire [3:0] cancel_o,
   output wire [3:0] force_cnt_o,
   output wire [5:0] evt_o,
   output wire [7:0] since_o,
   output wire [6:0] log_o,
   output wire [5:0] log_aux_o,
   output wire [2:0] log_cred_o,
   output wire [3:0] log_vld_o,
   output wire [3:0] lat_o,
   output wire [3:0] rsn_o,
   output wire [3:0] slot_cnt_o,
   output wire [3:0] stab_o,
   output wire [7:0] slot_seen_o,
   output wire [3:0] epoch_o,
   output wire [3:0] burst_max_o,
   output wire [2:0] drift_max_o
);
   reg [3:0] cfg_settle;
   reg [1:0] cfg_lsel;
   reg       cfg_stab_en;
   reg       cfg_rate_en;
   reg [2:0] cfg_cap;
   reg       cfg_mode;
   reg       cfg_wd_en;
   reg [3:0] cfg_period;
   reg [2:0] cfg_lowat;
   reg [3:0] cfg_wd_lim;
   reg [2:0] cfg_ssel;
   reg [5:0] cfg_ie;
   reg [7:0] cfg_min_gap;
   reg [7:0] cfg_blk;
   reg [3:0] stab [0:7];
   reg       pend;
   reg [3:0] settle_cnt;
   reg [2:0] pend_slot;
   reg [3:0] pend_age;
   reg [3:0] stall_cnt;
   reg [2:0] why;
   reg [2:0] credits;
   reg [2:0] debt;
   reg [3:0] rf_cnt;
   reg [2:0] cred_min;
   reg [3:0] waste_cnt;
   reg [3:0] stall_max;
   reg [3:0] cancel_cnt;
   reg [3:0] force_cnt;
   reg [5:0] evt;
   reg [7:0] since_cnt;
   reg [3:0] epoch_cnt;
   reg [3:0] burst_max;
   reg [2:0] drift_max;
   reg [6:0] log_ent [0:3];
   reg [5:0] log_aux [0:3];
   reg [2:0] log_cred [0:3];
   reg [3:0] log_vld;
   reg [3:0] lat_bin [0:3];
   reg [3:0] stall_rsn [0:3];
   reg [3:0] slot_cnt [0:7];
   reg [7:0] slot_seen;
   integer p;
   integer q;
   initial begin
       for (p = 0; p < 8; p = p + 1) begin
           stab[p] = 4'd0;
           slot_cnt[p] = 4'd0;
       end
       for (p = 0; p < 4; p = p + 1) begin
           log_ent[p] = 7'd0;
           log_aux[p] = 6'd0;
           log_cred[p] = 3'd0;
           lat_bin[p] = 4'd0;
           stall_rsn[p] = 4'd0;
       end
   end
   initial cfg_settle = 4'd0;
   initial cfg_lsel = 2'd0;
   initial cfg_stab_en = 1'b0;
   initial cfg_rate_en = 1'b0;
   initial cfg_cap = 3'd0;
   initial cfg_mode = 1'b0;
   initial cfg_wd_en = 1'b0;
   initial cfg_period = 4'd0;
   initial cfg_lowat = 3'd0;
   initial cfg_wd_lim = 4'd0;
   initial cfg_ssel = 3'd0;
   initial cfg_ie = 6'd0;
   initial cfg_min_gap = 8'd0;
   initial cfg_blk = 8'd0;
   initial pend = 1'b0;
   initial settle_cnt = 4'd0;
   initial pend_slot = 3'd0;
   initial pend_age = 4'd0;
   initial stall_cnt = 4'd0;
   initial why = 3'd0;
   initial credits = 3'd0;
   initial debt = 3'd0;
   initial rf_cnt = 4'd0;
   initial cred_min = 3'd7;
   initial waste_cnt = 4'd0;
   initial stall_max = 4'd0;
   initial cancel_cnt = 4'd0;
   initial force_cnt = 4'd0;
   initial evt = 6'd0;
   initial since_cnt = 8'hFF;
   initial epoch_cnt = 4'd0;
   initial burst_max = 4'd0;
   initial drift_max = 3'd0;
   initial log_vld = 4'd0;
   initial slot_seen = 8'd0;
   // commit gate: settle time, frame credits, minimum spacing, blocked slots
   wire [3:0] settle_load = cfg_stab_en ? stab[slot_i] : cfg_settle;
   wire settled = pend && (settle_cnt == 4'd0);
   wire credit_ok = !cfg_rate_en || (credits != 3'd0);
   wire space_ok = (since_cnt >= cfg_min_gap);
   wire slot_ok = !cfg_blk[slot_i];
   wire gate_ok = credit_ok && space_ok && slot_ok;
   wire [2:0] why_now = {!slot_ok, !space_ok, !credit_ok};
   wire wd_fire = cfg_wd_en && (cfg_wd_lim != 4'd0) && (stall_cnt >= cfg_wd_lim);
   wire kill = abort_req || restart_i;
   wire direct = launch_i && !pend && (settle_load == 4'd0) && gate_ok;
   wire held_go = settled && (gate_ok || wd_fire) && !kill;
   assign go_o = direct || held_go;
   wire forced = held_go && !gate_ok;
   wire capture = launch_i && !direct && !pend;
   wire cancel = pend && kill;
   wire stalled = settled && !gate_ok && !wd_fire && !kill;
   wire settling = pend && (settle_cnt != 4'd0) && !kill;
   wire starve = stalled && (stall_cnt == 4'hE);
   // credit bucket: timer refill or one credit returned per finished frame
   wire take = go_o && cfg_rate_en && (credits != 3'd0);
   wire owe = forced && cfg_rate_en && (credits == 3'd0);
   wire rf_tick = !cfg_mode && (rf_cnt >= cfg_period);
   wire ret_tick = cfg_mode && frame_end_i;
   wire refill = rf_tick || ret_tick;
   wire pay = refill && !owe && (debt != 3'd0);
   wire give = refill && !owe && (debt == 3'd0) && (credits < cfg_cap);
   wire waste = refill && !owe && (debt == 3'd0) && (credits >= cfg_cap);
   wire grow = owe && !refill;
   wire low = cfg_rate_en && (credits <= cfg_lowat);
   wire [2:0] l_slot = pend ? pend_slot : slot_i;
   wire [2:0] drift = slot_i - l_slot;
   wire [3:0] c_wait = pend ? pend_age : 4'd0;
   wire [2:0] c_why = pend ? (why | (forced ? why_now : 3'd0)) : 3'd0;
   wire [1:0] c_bin = (c_wait == 4'd0) ? 2'd0 : ((c_wait < 4'd4) ? 2'd1 : ((c_wait < 4'd8) ? 2'd2 : 2'd3));
   wire pol_ovr = go_o && !(space_ok && slot_ok);
   wire [3:0] rsn_hit = {settling, stalled ? why_now : 3'd0};
   wire cap_wr = csr_we && (csr_addr == 3'd1);
   wire stab_wr = csr_we && (csr_addr == 3'd4) && csr_wdata[7];
   wire log_clr = csr_we && (csr_addr == 3'd3) && csr_wdata[6];
   wire st_clr = csr_we && (csr_addr == 3'd3) && csr_wdata[7];
   wire [5:0] evt_clr = (csr_we && (csr_addr == 3'd6)) ? csr_wdata[5:0] : 6'd0;
   wire [5:0] evt_set = {pol_ovr, low, starve, forced, cancel, go_o};
   assign pend_o = pend;
   assign rdy_o = !pend && gate_ok;
   assign irq_o = |(evt & cfg_ie);
   assign forced_o = forced;
   assign settle_o = settle_cnt;
   assign age_o = pend_age;
   assign stall_o = stall_cnt;
   assign why_o = why;
   assign credits_o = credits;
   assign debt_o = debt;
   assign cred_min_o = cred_min;
   assign refill_o = rf_cnt;
   assign waste_o = waste_cnt;
   assign stall_max_o = stall_max;
   assign cancel_o = cancel_cnt;
   assign force_cnt_o = force_cnt;
   assign evt_o = evt;
   assign since_o = since_cnt;
   assign log_o = log_ent[cfg_lsel];
   assign log_aux_o = log_aux[cfg_lsel];
   assign log_cred_o = log_cred[cfg_lsel];
   assign log_vld_o = log_vld;
   assign lat_o = lat_bin[cfg_lsel];
   assign rsn_o = stall_rsn[cfg_lsel];
   assign slot_cnt_o = slot_cnt[cfg_ssel];
   assign stab_o = stab[cfg_ssel];
   assign slot_seen_o = slot_seen;
   assign epoch_o = epoch_cnt;
   assign burst_max_o = burst_max;
   assign drift_max_o = drift_max;
   always @(posedge clk) begin
       if (!rst_n) begin
           cfg_settle <= 4'd0;
           cfg_lsel <= 2'd0;
           cfg_stab_en <= 1'b0;
           cfg_rate_en <= 1'b0;
           cfg_cap <= 3'd0;
           cfg_mode <= 1'b0;
           cfg_wd_en <= 1'b0;
           cfg_period <= 4'd0;
           cfg_lowat <= 3'd0;
           cfg_wd_lim <= 4'd0;
           cfg_ssel <= 3'd0;
           cfg_ie <= 6'd0;
           cfg_min_gap <= 8'd0;
           cfg_blk <= 8'd0;
           pend <= 1'b0;
           settle_cnt <= 4'd0;
           pend_slot <= 3'd0;
           pend_age <= 4'd0;
           stall_cnt <= 4'd0;
           why <= 3'd0;
           credits <= 3'd0;
           debt <= 3'd0;
           rf_cnt <= 4'd0;
           cred_min <= 3'd7;
           waste_cnt <= 4'd0;
           stall_max <= 4'd0;
           cancel_cnt <= 4'd0;
           force_cnt <= 4'd0;
           evt <= 6'd0;
           since_cnt <= 8'hFF;
           epoch_cnt <= 4'd0;
           burst_max <= 4'd0;
           drift_max <= 3'd0;
           log_vld <= 4'd0;
           slot_seen <= 8'd0;
           for (q = 0; q < 8; q = q + 1) begin
               stab[q] <= 4'd0;
               slot_cnt[q] <= 4'd0;
           end
           for (q = 0; q < 4; q = q + 1) begin
               log_ent[q] <= 7'd0;
               log_aux[q] <= 6'd0;
               log_cred[q] <= 3'd0;
               lat_bin[q] <= 4'd0;
               stall_rsn[q] <= 4'd0;
           end
       end else if (en) begin
           if (csr_we) begin
               case (csr_addr)
                   3'd0: begin
                       cfg_settle <= csr_wdata[3:0];
                       cfg_lsel <= csr_wdata[5:4];
                       cfg_stab_en <= csr_wdata[6];
                   end
                   3'd1: begin
                       cfg_rate_en <= csr_wdata[0];
                       cfg_cap <= csr_wdata[3:1];
                       cfg_mode <= csr_wdata[4];
                       cfg_wd_en <= csr_wdata[5];
                   end
                   3'd2: begin
                       cfg_period <= csr_wdata[3:0];
                       cfg_lowat <= csr_wdata[6:4];
                   end
                   3'd3: cfg_wd_lim <= csr_wdata[3:0];
                   3'd4: cfg_ssel <= csr_wdata[6:4];
                   3'd5: cfg_ie <= csr_wdata[5:0];
                   3'd7: begin
                       cfg_min_gap <= csr_wdata[7:0];
                       cfg_blk <= csr_wdata[15:8];
                   end
               endcase
           end
           for (q = 0; q < 8; q = q + 1) begin
               if (stab_wr && (csr_wdata[6:4] == q))
                   stab[q] <= csr_wdata[3:0];
           end
           evt <= (evt & ~evt_clr) | evt_set;
           if (cfg_mode || rf_tick)
               rf_cnt <= 4'd0;
           else
               rf_cnt <= rf_cnt + 4'd1;
           if (cap_wr) begin
               credits <= csr_wdata[3:1];
               debt <= 3'd0;
           end else begin
               if (give && !take)
                   credits <= credits + 3'd1;
               else if (take && !give)
                   credits <= credits - 3'd1;
               if (grow && (debt != 3'd7))
                   debt <= debt + 3'd1;
               else if (pay)
                   debt <= debt - 3'd1;
           end
           if (st_clr) begin
               waste_cnt <= 4'd0;
               stall_max <= 4'd0;
               cancel_cnt <= 4'd0;
               force_cnt <= 4'd0;
               burst_max <= 4'd0;
               drift_max <= 3'd0;
               slot_seen <= 8'd0;
               for (q = 0; q < 8; q = q + 1)
                   slot_cnt[q] <= 4'd0;
               for (q = 0; q < 4; q = q + 1) begin
                   lat_bin[q] <= 4'd0;
                   stall_rsn[q] <= 4'd0;
               end
           end
           if (st_clr)
               cred_min <= 3'd7;
           else if (cfg_rate_en && (credits < cred_min))
               cred_min <= credits;
           if (log_clr)
               log_vld <= 4'd0;
           if (waste && (waste_cnt != 4'hF))
               waste_cnt <= waste_cnt + 4'd1;
           if (cancel && (cancel_cnt != 4'hF))
               cancel_cnt <= cancel_cnt + 4'd1;
           for (q = 0; q < 4; q = q + 1) begin
               if (rsn_hit[q] && (stall_rsn[q] != 4'hF))
                   stall_rsn[q] <= stall_rsn[q] + 4'd1;
           end
           if (go_o)
               since_cnt <= 8'd0;
           else if (since_cnt != 8'hFF)
               since_cnt <= since_cnt + 8'd1;
           if (refill) begin
               epoch_cnt <= go_o ? 4'd1 : 4'd0;
               if (epoch_cnt > burst_max)
                   burst_max <= epoch_cnt;
           end else if (go_o && (epoch_cnt != 4'hF)) begin
               epoch_cnt <= epoch_cnt + 4'd1;
           end
           // pending commit record
           if (kill || held_go) begin
               pend <= 1'b0;
               settle_cnt <= 4'd0;
               pend_age <= 4'd0;
               stall_cnt <= 4'd0;
               why <= 3'd0;
           end else if (capture) begin
               pend <= 1'b1;
               settle_cnt <= settle_load;
               pend_slot <= slot_i;
               pend_age <= 4'd0;
               stall_cnt <= 4'd0;
               why <= 3'd0;
           end else if (pend) begin
               if (settle_cnt != 4'd0)
                   settle_cnt <= settle_cnt - 4'd1;
               if (pend_age != 4'hF)
                   pend_age <= pend_age + 4'd1;
               if (stalled) begin
                   why <= why | why_now;
                   if (stall_cnt != 4'hF)
                       stall_cnt <= stall_cnt + 4'd1;
               end
           end
           // commit log and statistics
           if (go_o) begin
               log_ent[0] <= {drift, c_wait};
               log_aux[0] <= {c_why, slot_i};
               log_cred[0] <= credits;
               for (q = 1; q < 4; q = q + 1) begin
                   log_ent[q] <= log_ent[q - 1];
                   log_aux[q] <= log_aux[q - 1];
                   log_cred[q] <= log_cred[q - 1];
               end
               log_vld <= {log_vld[2:0], 1'b1};
               slot_seen[slot_i] <= 1'b1;
               for (q = 0; q < 8; q = q + 1) begin
                   if ((slot_i == q) && (slot_cnt[q] != 4'hF))
                       slot_cnt[q] <= slot_cnt[q] + 4'd1;
               end
               for (q = 0; q < 4; q = q + 1) begin
                   if ((c_bin == q) && (lat_bin[q] != 4'hF))
                       lat_bin[q] <= lat_bin[q] + 4'd1;
               end
               if (forced && (force_cnt != 4'hF))
                   force_cnt <= force_cnt + 4'd1;
               if (stall_cnt > stall_max)
                   stall_max <= stall_cnt;
               if (drift > drift_max)
                   drift_max <= drift;
           end
       end
   end
endmodule
module tplan_launch_sched (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire [1:0] phase_i,
   input wire fire_i,
   input wire restart_i,
   input wire abort_req,
   input wire frame_end_i,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire launch_o,
   output wire hold_o,
   output wire tok_o,
   output wire late_o,
   output wire [2:0] slot_o,
   output wire [2:0] last_slot_o,
   output wire [3:0] wait_max_o,
   output wire [3:0] skip_o,
   output wire [3:0] gap_o,
   output wire [6:0] hist_o,
   output wire [3:0] hist_vld_o
);
   reg [3:0] cfg_div;
   reg       cfg_align;
   reg       cfg_gap_en;
   reg       cfg_force;
   reg [3:0] cfg_dl;
   reg [3:0] cfg_gap;
   reg [1:0] cfg_hsel;
   reg [7:0] cfg_mask;
   reg [3:0] div_cnt;
   reg [2:0] slot_idx;
   reg       tok;
   reg [3:0] wait_cnt;
   reg [3:0] wait_max;
   reg       late;
   reg [3:0] skip_cnt;
   reg [3:0] gap_cnt;
   reg [2:0] last_slot;
   reg [6:0] hist [0:3];
   reg [3:0] hist_vld;
   integer g;
   integer h;
   initial begin
       for (g = 0; g < 4; g = g + 1)
           hist[g] = 7'd0;
   end
   initial cfg_div = 4'd0;
   initial cfg_align = 1'b0;
   initial cfg_gap_en = 1'b0;
   initial cfg_force = 1'b0;
   initial cfg_dl = 4'd0;
   initial cfg_gap = 4'd0;
   initial cfg_hsel = 2'd0;
   initial cfg_mask = 8'd0;
   initial div_cnt = 4'd0;
   initial slot_idx = 3'd0;
   initial tok = 1'b0;
   initial wait_cnt = 4'd0;
   initial wait_max = 4'd0;
   initial late = 1'b0;
   initial skip_cnt = 4'd0;
   initial gap_cnt = 4'd0;
   initial last_slot = 3'd0;
   initial hist_vld = 4'd0;
   // slot timebase: one slot every cfg_div+1 cycles, eight slots per window
   wire armed = (phase_i == 2'd1);
   wire slot_tick = (div_cnt >= cfg_div);
   wire slot_ok = (cfg_mask == 8'd0) || cfg_mask[slot_idx];
   wire aligned = !cfg_align || (slot_tick && slot_ok);
   wire dl_hit = (cfg_dl != 4'd0) && (wait_cnt >= cfg_dl);
   wire forced = cfg_force && tok && dl_hit;
   wire want = tok || fire_i;
   assign launch_o = armed && want && !abort_req && !restart_i && (aligned || forced);
   wire skipped = tok && cfg_align && slot_tick && !slot_ok && !launch_o;
   wire stat_clr = csr_we && (csr_addr == 3'd5) && csr_wdata[2];
   assign hold_o = cfg_gap_en && (gap_cnt != 4'd0);
   assign tok_o = tok;
   assign late_o = late;
   assign slot_o = slot_idx;
   assign last_slot_o = last_slot;
   assign wait_max_o = wait_max;
   assign skip_o = skip_cnt;
   assign gap_o = gap_cnt;
   assign hist_o = hist[cfg_hsel];
   assign hist_vld_o = hist_vld;
   always @(posedge clk) begin
       if (!rst_n) begin
           cfg_div <= 4'd0;
           cfg_align <= 1'b0;
           cfg_gap_en <= 1'b0;
           cfg_force <= 1'b0;
           cfg_dl <= 4'd0;
           cfg_gap <= 4'd0;
           cfg_hsel <= 2'd0;
           cfg_mask <= 8'd0;
           div_cnt <= 4'd0;
           slot_idx <= 3'd0;
           tok <= 1'b0;
           wait_cnt <= 4'd0;
           wait_max <= 4'd0;
           late <= 1'b0;
           skip_cnt <= 4'd0;
           gap_cnt <= 4'd0;
           last_slot <= 3'd0;
           hist_vld <= 4'd0;
           for (h = 0; h < 4; h = h + 1)
               hist[h] <= 7'd0;
       end else if (en) begin
           if (csr_we) begin
               case (csr_addr)
                   3'd4: cfg_div <= csr_wdata[3:0];
                   3'd5: begin
                       cfg_align <= csr_wdata[0];
                       cfg_gap_en <= csr_wdata[1];
                       cfg_force <= csr_wdata[3];
                       cfg_dl <= csr_wdata[7:4];
                   end
                   3'd6: begin
                       cfg_gap <= csr_wdata[3:0];
                       cfg_hsel <= csr_wdata[5:4];
                   end
                   3'd7: cfg_mask <= csr_wdata;
               endcase
           end
           if (stat_clr) begin
               wait_max <= 4'd0;
               late <= 1'b0;
               skip_cnt <= 4'd0;
               hist_vld <= 4'd0;
           end
           if (slot_tick) begin
               div_cnt <= 4'd0;
               slot_idx <= slot_idx + 3'd1;
           end else begin
               div_cnt <= div_cnt + 4'd1;
           end
           if (abort_req) begin
               tok <= 1'b0;
               wait_cnt <= 4'd0;
               gap_cnt <= 4'd0;
           end else begin
               if (restart_i || !armed) begin
                   tok <= 1'b0;
                   wait_cnt <= 4'd0;
               end else if (launch_o) begin
                   tok <= 1'b0;
                   wait_cnt <= 4'd0;
                   last_slot <= slot_idx;
                   if (wait_cnt > wait_max)
                       wait_max <= wait_cnt;
                   hist[0] <= {slot_idx, wait_cnt};
                   for (h = 1; h < 4; h = h + 1)
                       hist[h] <= hist[h - 1];
                   hist_vld <= {hist_vld[2:0], 1'b1};
               end else if (fire_i) begin
                   tok <= 1'b1;
                   if (!tok)
                       wait_cnt <= 4'd0;
               end else if (tok) begin
                   if (wait_cnt != 4'hF)
                       wait_cnt <= wait_cnt + 4'd1;
               end
               if (tok && dl_hit)
                   late <= 1'b1;
               if (skipped && (skip_cnt != 4'hF))
                   skip_cnt <= skip_cnt + 4'd1;
               if (frame_end_i)
                   gap_cnt <= cfg_gap_en ? cfg_gap : 4'd0;
               else if (slot_tick && (gap_cnt != 4'd0))
                   gap_cnt <= gap_cnt - 4'd1;
           end
       end
   end
endmodule
module tplan_seq_ctrl (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire [1:0] phase_i,
   input wire start_req,
   input wire abort_req,
   input wire frame_end,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire start_ack,
   output wire fire,
   output wire rearm,
   output wire busy,
   output wire pend_o,
   output wire loop_pend_o,
   output wire ovr_o,
   output wire [3:0] delay_o,
   output wire [3:0] loops_o
);
   reg [3:0] cfg_preroll;
   reg [3:0] cfg_loops;
   reg       cfg_auto;
   reg       pend;
   reg [3:0] delay_cnt;
   reg       loop_pend;
   reg [3:0] loops_left;
   reg       ovr;
   initial cfg_preroll = 4'd0;
   initial cfg_loops = 4'd0;
   initial cfg_auto = 1'b0;
   initial pend = 1'b0;
   initial delay_cnt = 4'd0;
   initial loop_pend = 1'b0;
   initial loops_left = 4'd0;
   initial ovr = 1'b0;
   wire armed = (phase_i == 2'd1);
   wire fin = (phase_i == 2'd3);
   assign start_ack = armed && !pend && !abort_req && (start_req || loop_pend);
   assign fire = pend && (delay_cnt == 4'd0) && !abort_req;
   assign rearm = fin && loop_pend && !abort_req;
   assign busy = pend || loop_pend;
   assign pend_o = pend;
   assign loop_pend_o = loop_pend;
   assign ovr_o = ovr;
   assign delay_o = delay_cnt;
   assign loops_o = loops_left;
   always @(posedge clk) begin
       if (!rst_n) begin
           cfg_preroll <= 4'd0;
           cfg_loops <= 4'd0;
           cfg_auto <= 1'b0;
           pend <= 1'b0;
           delay_cnt <= 4'd0;
           loop_pend <= 1'b0;
           loops_left <= 4'd0;
           ovr <= 1'b0;
       end else if (en) begin
           if (csr_we) begin
               case (csr_addr)
                   3'd0: cfg_preroll <= csr_wdata[3:0];
                   3'd1: cfg_loops <= csr_wdata[3:0];
                   3'd2: cfg_auto <= csr_wdata[0];
                   3'd3: ovr <= 1'b0;
               endcase
           end
           if (start_req && pend && !abort_req)
               ovr <= 1'b1;
           if (abort_req) begin
               pend <= 1'b0;
               delay_cnt <= 4'd0;
               loop_pend <= 1'b0;
               loops_left <= 4'd0;
           end else begin
               if (start_ack) begin
                   pend <= 1'b1;
                   delay_cnt <= cfg_preroll;
                   if (loop_pend) begin
                       loop_pend <= 1'b0;
                       loops_left <= loops_left - 4'd1;
                   end else begin
                       loops_left <= cfg_loops;
                   end
               end else if (pend) begin
                   if (delay_cnt == 4'd0)
                       pend <= 1'b0;
                   else
                       delay_cnt <= delay_cnt - 4'd1;
               end
               if (frame_end && cfg_auto && (loops_left != 4'd0))
                   loop_pend <= 1'b1;
           end
       end
   end
endmodule
module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire o_seq_busy,
  output wire [10:0] o_seq_stat,
  output wire o_arm_rdy,
  output wire [20:0] o_lnch_stat,
  output wire [10:0] o_lnch_hist,
  output wire o_gov_rdy,
  output wire o_gov_irq,
  output wire [30:0] o_gov_stat,
  output wire [29:0] o_gov_mon,
  output wire [19:0] o_gov_log,
  output wire [23:0] o_gov_slot,
  output wire [10:0] o_gov_burst
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire seq_start_ack, seq_fire, seq_rearm, seq_busy;
   wire seq_pend, seq_loop_pend, seq_ovr;
   wire [3:0] seq_delay;
   wire [3:0] seq_loops;
   wire frame_end = (phase == RUN) && last_col && last_row && !abort_req;
   wire csr_we = wr_en && (wr_addr[4:3] == 2'b11);
   tplan_seq_ctrl u_seq (
       .clk(clk),
       .rst_n(rst_n),
       .en(en),
       .phase_i(phase),
       .start_req(start_req),
       .abort_req(abort_req),
       .frame_end(frame_end),
       .csr_we(csr_we),
       .csr_addr(wr_addr[2:0]),
       .csr_wdata(wr_data[7:0]),
       .start_ack(seq_start_ack),
       .fire(seq_fire),
       .rearm(seq_rearm),
       .busy(seq_busy),
       .pend_o(seq_pend),
       .loop_pend_o(seq_loop_pend),
       .ovr_o(seq_ovr),
       .delay_o(seq_delay),
       .loops_o(seq_loops)
   );
  wire lnch_go, lnch_hold, lnch_tok, lnch_late;
  wire [2:0] lnch_slot, lnch_last;
  wire [3:0] lnch_wait_max, lnch_skip, lnch_gap;
  wire [6:0] lnch_hist;
  wire [3:0] lnch_hist_vld;
  tplan_launch_sched u_lnch (
      .clk(clk),
      .rst_n(rst_n),
      .en(en),
      .phase_i(phase),
      .fire_i(seq_fire),
      .restart_i(seq_start_ack),
      .abort_req(abort_req),
      .frame_end_i(frame_end),
      .csr_we(csr_we),
      .csr_addr(wr_addr[2:0]),
      .csr_wdata(wr_data[7:0]),
      .launch_o(lnch_go),
      .hold_o(lnch_hold),
      .tok_o(lnch_tok),
      .late_o(lnch_late),
      .slot_o(lnch_slot),
      .last_slot_o(lnch_last),
      .wait_max_o(lnch_wait_max),
      .skip_o(lnch_skip),
      .gap_o(lnch_gap),
      .hist_o(lnch_hist),
      .hist_vld_o(lnch_hist_vld)
  );
  wire gov_go, gov_pend, gov_rdy, gov_irq, gov_forced;
  wire [2:0] gov_why, gov_credits, gov_debt, gov_cred_min, gov_log_cred, gov_drift_max;
  wire [3:0] gov_settle, gov_age, gov_stall, gov_refill, gov_waste;
  wire [3:0] gov_stall_max, gov_cancel, gov_force_cnt, gov_epoch, gov_burst_max;
  wire [3:0] gov_log_vld, gov_lat, gov_rsn, gov_slot_cnt, gov_stab;
  wire [5:0] gov_evt, gov_log_aux;
  wire [6:0] gov_log;
  wire [7:0] gov_since, gov_slot_seen;
  tplan_commit_gov u_gov (
      .clk(clk),
      .rst_n(rst_n),
      .en(en),
      .launch_i(lnch_go),
      .restart_i(seq_start_ack),
      .abort_req(abort_req),
      .frame_end_i(frame_end),
      .slot_i(lnch_slot),
      .csr_we(csr_we),
      .csr_addr(wr_addr[2:0]),
      .csr_wdata(wr_data[23:8]),
      .go_o(gov_go),
      .pend_o(gov_pend),
      .rdy_o(gov_rdy),
      .irq_o(gov_irq),
      .forced_o(gov_forced),
      .settle_o(gov_settle),
      .age_o(gov_age),
      .stall_o(gov_stall),
      .why_o(gov_why),
      .credits_o(gov_credits),
      .debt_o(gov_debt),
      .cred_min_o(gov_cred_min),
      .refill_o(gov_refill),
      .waste_o(gov_waste),
      .stall_max_o(gov_stall_max),
      .cancel_o(gov_cancel),
      .force_cnt_o(gov_force_cnt),
      .evt_o(gov_evt),
      .since_o(gov_since),
      .log_o(gov_log),
      .log_aux_o(gov_log_aux),
      .log_cred_o(gov_log_cred),
      .log_vld_o(gov_log_vld),
      .lat_o(gov_lat),
      .rsn_o(gov_rsn),
      .slot_cnt_o(gov_slot_cnt),
      .stab_o(gov_stab),
      .slot_seen_o(gov_slot_seen),
      .epoch_o(gov_epoch),
      .burst_max_o(gov_burst_max),
      .drift_max_o(gov_drift_max)
  );

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                       if (seq_start_ack) begin
                           start_seen <= 1'b1;
                           col_cnt <= 64'd0;
                           row_cnt <= 64'd0;
                       end
                     if (gov_go)
                           phase <= RUN;
                    end
                    RUN: begin
                        pix_row <= font_row(cur_char, row_cnt[2:0]);
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                done <= 1'b1;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                    end
                    FIN: begin
                      if ((arm_req || seq_rearm) && !lnch_hold) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_seq_busy = seq_busy;
   assign o_seq_stat = {seq_pend, seq_loop_pend, seq_ovr, seq_loops, seq_delay};
  assign o_arm_rdy = !lnch_hold;
  assign o_lnch_stat = {lnch_tok, lnch_late, lnch_hold, lnch_slot, lnch_last, lnch_wait_max, lnch_skip, lnch_gap};
  assign o_lnch_hist = {lnch_hist_vld, lnch_hist};
 assign o_gov_rdy = gov_rdy;
 assign o_gov_irq = gov_irq;
 assign o_gov_stat = {gov_pend, gov_forced, gov_go, gov_settle, gov_age, gov_stall, gov_why, gov_credits, gov_debt, gov_cred_min, gov_refill};
 assign o_gov_mon = {gov_waste, gov_stall_max, gov_cancel, gov_force_cnt, gov_evt, gov_since};
 assign o_gov_log = {gov_log_vld, gov_log, gov_log_aux, gov_log_cred};
 assign o_gov_slot = {gov_slot_seen, gov_slot_cnt, gov_stab, gov_lat, gov_rsn};
 assign o_gov_burst = {gov_drift_max, gov_burst_max, gov_epoch};

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

module wake_alloc_q #(
   parameter DEPTH = 4,
   parameter AW    = 2,
   parameter SLOTS = 32
) (
   input  wire          clk,
   input  wire          rst_n,
   input  wire          en,
   input  wire          in_vld,
   input  wire [31:0]   in_deps,
   output wire          in_rdy,
   input  wire          slot_ret,
   input  wire [31:0]   slot_clr,
   output wire          out_vld,
   output wire [31:0]   out_deps,
   output wire [5:0]    credits_o,
   output wire [AW:0]   count_o,
   output wire [7:0]    stall_o
);
   reg [31:0]   q_deps [0:DEPTH-1];
   reg [AW-1:0] wr_ptr   = {AW{1'b0}};
   reg [AW-1:0] rd_ptr   = {AW{1'b0}};
   reg [AW:0]   q_cnt    = {(AW+1){1'b0}};
   reg [5:0]    credits  = SLOTS;
   reg          stg_v    = 1'b0;
   reg [31:0]   stg_deps = 32'd0;
   reg [7:0]    stall    = 8'd0;

   integer i;
   initial for (i = 0; i < DEPTH; i = i + 1) q_deps[i] = 32'd0;
   initial wr_ptr   = {AW{1'b0}};
   initial rd_ptr   = {AW{1'b0}};
   initial q_cnt    = {(AW+1){1'b0}};
   initial credits  = SLOTS;
   initial stg_v    = 1'b0;
   initial stg_deps = 32'd0;
   initial stall    = 8'd0;

   wire q_empty = (q_cnt == {(AW+1){1'b0}});
   wire q_full  = (q_cnt == DEPTH);
   wire no_cred = (credits == 6'd0);
   wire push    = in_vld && !q_full;
   wire pop     = !q_empty && !no_cred;
   wire [31:0]   head_deps = q_deps[rd_ptr] & ~slot_clr;
   wire [AW-1:0] wr_nxt = (wr_ptr == DEPTH-1) ? {AW{1'b0}} : wr_ptr + 1'b1;
   wire [AW-1:0] rd_nxt = (rd_ptr == DEPTH-1) ? {AW{1'b0}} : rd_ptr + 1'b1;

   assign in_rdy    = !q_full;
   assign out_vld   = stg_v;
   assign out_deps  = stg_deps;
   assign credits_o = credits;
   assign count_o   = q_cnt;
   assign stall_o   = stall;

   integer j;
   always @(posedge clk) begin
       if (!rst_n) begin
           wr_ptr   <= {AW{1'b0}};
           rd_ptr   <= {AW{1'b0}};
           q_cnt    <= {(AW+1){1'b0}};
           credits  <= SLOTS;
           stg_v    <= 1'b0;
           stg_deps <= 32'd0;
           stall    <= 8'd0;
           for (j = 0; j < DEPTH; j = j + 1)
               q_deps[j] <= 32'd0;
       end else if (en) begin
           for (j = 0; j < DEPTH; j = j + 1)
               q_deps[j] <= q_deps[j] & ~slot_clr;
           if (push) begin
               q_deps[wr_ptr] <= in_deps & ~slot_clr;
               wr_ptr <= wr_nxt;
           end
           if (pop)
               rd_ptr <= rd_nxt;
           q_cnt    <= q_cnt + {{AW{1'b0}}, push} - {{AW{1'b0}}, pop};
           credits  <= credits + {5'd0, slot_ret} - {5'd0, pop};
           stg_v    <= pop;
           stg_deps <= pop ? head_deps : 32'd0;
           if (!q_empty && no_cred && (stall != 8'hff))
               stall <= stall + 8'd1;
       end
   end
endmodule

module pico_wakeup (
    input wire        clk,
    input wire        rst_n,
    input wire        en,
    input wire        alloc,
    input wire [31:0] alloc_deps,
    input wire        issue,
   input wire [4:0]  issue_idx,
   output wire       alloc_rdy,
   output wire       alloc_stg_v,
   output wire [5:0] alloc_credits,
   output wire [2:0] alloc_q_cnt,
   output wire [7:0] alloc_stall
);
    reg [31:0]   valid    = 32'd0;
    reg [1023:0] dep_flat = 1024'd0;
    reg [31:0]   pend     = 32'd0;
    reg [63:0]   occ      = 64'd0;
    reg [63:0]   wake_cnt = 64'd0;

    initial valid    = 32'd0;
    initial dep_flat = 1024'd0;
    initial pend     = 32'd0;
    initial occ      = 64'd0;
    initial wake_cnt = 64'd0;

    wire full = &valid;

    // lowest free index
    reg [4:0] free_idx;
    integer a;
    always @(*) begin
        free_idx = 5'd0;
        for (a = 31; a >= 0; a = a - 1)
            if (!valid[a]) free_idx = a[4:0];
    end

    // popcount of valid (status helper)
    reg [63:0] valid_cnt;
    integer b;
    always @(*) begin
        valid_cnt = 64'd0;
        for (b = 0; b < 32; b = b + 1)
            valid_cnt = valid_cnt + {63'd0, valid[b]};
    end

    // per-row OR of dependency matrix (status helper)
    reg [31:0] dep_or;
    integer c;
    always @(*) begin
        for (c = 0; c < 32; c = c + 1)
            dep_or[c] = |dep_flat[c*32 +: 32];
    end

   wire [31:0] aq_deps;
   wire alloc_fire = alloc_stg_v;
    wire issue_fire = issue && valid[issue_idx] && !pend[issue_idx];
    wire [31:0] clr_mask   = issue_fire ? (32'd1 << issue_idx) : 32'd0;
    wire [31:0] alloc_mask = alloc_fire ? (32'd1 << free_idx)  : 32'd0;
   wire [31:0] new_deps   = aq_deps & valid & ~clr_mask;

   // allocation request queue with slot credits
   wake_alloc_q #(.DEPTH(4), .AW(2), .SLOTS(32)) u_aq (
       .clk(clk),
       .rst_n(rst_n),
       .en(en),
       .in_vld(alloc),
       .in_deps(alloc_deps),
       .in_rdy(alloc_rdy),
       .slot_ret(issue_fire),
       .slot_clr(clr_mask),
       .out_vld(alloc_stg_v),
       .out_deps(aq_deps),
       .credits_o(alloc_credits),
       .count_o(alloc_q_cnt),
       .stall_o(alloc_stall)
   );

    reg [1023:0] dep_nxt;
    reg [31:0]   pend_nxt;
    reg [63:0]   woke;
    integer k;
    always @(*) begin
        woke = 64'd0;
        dep_nxt = dep_flat;
        pend_nxt = pend;
        for (k = 0; k < 32; k = k + 1) begin
            if (alloc_mask[k]) begin
                dep_nxt[k*32 +: 32] = new_deps;
                pend_nxt[k] = |new_deps;
            end else if (clr_mask[k]) begin
                dep_nxt[k*32 +: 32] = 32'd0;
                pend_nxt[k] = 1'b0;
            end else begin
                dep_nxt[k*32 +: 32] = dep_flat[k*32 +: 32] & ~clr_mask;
                pend_nxt[k] = pend[k] && (|(dep_flat[k*32 +: 32] & ~clr_mask));
                if (pend[k] && !pend_nxt[k])
                    woke = woke + 64'd1;
            end
        end
    end

    wire [31:0] valid_nxt = (valid | alloc_mask) & ~clr_mask;

    always @(posedge clk) begin
        if (!rst_n) begin
            valid    <= 32'd0;
            dep_flat <= 1024'd0;
            pend     <= 32'd0;
            occ      <= 64'd0;
            wake_cnt <= 64'd0;
        end else if (en) begin
            valid    <= valid_nxt;
            dep_flat <= dep_nxt;
            pend     <= pend_nxt;
            wake_cnt <= wake_cnt + woke;
            if (alloc_fire && !issue_fire)
                occ <= occ + 64'd1;
            else if (issue_fire && !alloc_fire)
                occ <= occ - 64'd1;
        end
    end

    always @(posedge clk)
        if (|valid) assert (occ <= 64'd32);
endmodule

module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
    output reg  [6:0]  rsp_rule
,
    output wire busy_o,
    output wire [6:0] idx_o,
    output wire [7:0] timer_o
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
    wire last = (idx == 7'd127);

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
                if (req) begin
                    busy  <= 1'b1;
                    idx   <= 7'd0;
                    timer <= 8'd128;
                    q_key <= req_key;
                    q_len <= {48'd0, req_len};
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
    assign busy_o = busy;
    assign idx_o = idx;
    assign timer_o = timer;
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
    output reg         fault
,
    output wire hit_q_o,
    output wire miss_q_o
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
            fault  <= miss_q;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
    assign hit_q_o = hit_q;
    assign miss_q_o = miss_q;
endmodule

module flow_mpu_top (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    output wire        grant,
    output wire        fault,
    output wire [6:0]  rsp_rule,
    output wire        g_valid_o,
    output wire [15:0] g_addr_o,
    output wire        g_write_o
);
    wire        rsp_valid;
    wire        rsp_hit;
    wire [31:0] rsp_action;
    wire        busy_a;
    wire [6:0]  idx_a;
    wire [7:0]  timer_a;
    wire        hit_q;
    wire        miss_q;

    // pending destination-buffer access handed from the classifier to the MPU
    reg        g_valid;
    reg [15:0] g_addr;
    reg        g_write;

    initial begin
        g_valid = 1'b0;
        g_addr  = 16'd0;
        g_write = 1'b0;
    end

    flow_match_table u_flow (
        .clk(clk),
        .rst(rst),
        .i_ce(i_ce),
        .req(req),
        .req_key(req_key),
        .req_len(req_len),
        .wr_en(wr_en),
        .wr_idx(wr_idx),
        .wr_key(wr_key),
        .wr_action(wr_action),
        .rsp_valid(rsp_valid),
        .rsp_hit(rsp_hit),
        .rsp_action(rsp_action),
        .rsp_rule(rsp_rule),
        .busy_o(busy_a),
        .idx_o(idx_a),
        .timer_o(timer_a)
    );

    always @(posedge clk) begin
        if (rst) begin
            g_valid <= 1'b0;
            g_addr  <= 16'd0;
            g_write <= 1'b0;
        end else if (i_ce) begin
            g_valid <= rsp_valid && rsp_hit;
            if (rsp_valid && rsp_hit) begin
                g_addr  <= rsp_action[15:0];
                g_write <= rsp_action[16];
            end
        end
    end

    mpu_region_checker u_mpu (
        .clk(clk),
        .i_ce(i_ce),
        .cfg_we(cfg_we),
        .cfg_idx(cfg_idx),
        .cfg_base(cfg_base),
        .cfg_limit(cfg_limit),
        .cfg_perm(cfg_perm),
        .lock_req(lock_req),
        .acc_valid(g_valid),
        .acc_write(g_write),
        .acc_addr(g_addr),
        .grant(grant),
        .fault(fault),
        .hit_q_o(hit_q),
        .miss_q_o(miss_q)
    );

    assign g_valid_o = g_valid;
    assign g_addr_o  = g_addr;
    assign g_write_o = g_write;

    // the MPU never holds two packet steering decisions in its check stage at once
    always @(posedge clk)
        if (g_valid)
            assert (!(hit_q || miss_q));
endmodule

module lin_hdr_queue #(
   parameter DEPTH = 4,
   parameter PW = 2,
   parameter MAX_RETRY = 3
) (
   input wire clk,
   input wire rst,
   input wire i_push,
   input wire [5:0] i_id,
   input wire [3:0] i_len,
   input wire i_enh,
   input wire i_done,
   input wire i_fail,
   output wire o_ready,
   output wire o_valid,
   output wire [5:0] o_id,
   output wire [4:0] o_flen,
   output wire o_enh,
   output wire [PW:0] o_count,
   output wire [PW-1:0] o_rd_ptr,
   output wire [PW-1:0] o_wr_ptr,
   output wire o_dropped,
   output wire [5:0] o_drop_id
);
   reg [5:0] q_id [0:DEPTH-1];
   reg [3:0] q_len [0:DEPTH-1];
   reg q_enh [0:DEPTH-1];
   integer j;
   initial begin
       for (j = 0; j < DEPTH; j = j + 1) begin
           q_id[j] = 6'd0;
           q_len[j] = 4'd0;
           q_enh[j] = 1'b0;
       end
   end
   reg [PW-1:0] rd_ptr = {PW{1'b0}};
   reg [PW-1:0] wr_ptr = {PW{1'b0}};
   reg [PW:0] count = {(PW+1){1'b0}};
   reg [1:0] retries = 2'd0;
   reg dropped = 1'b0;
   reg [5:0] drop_id = 6'd0;

   // a header is retired when its frame completes, or after too many aborts
   wire push_ok = i_push && o_ready;
   wire retry_out = i_fail && (retries == MAX_RETRY);
   wire pop = o_valid && (i_done || retry_out);

   always @(posedge clk) begin
       if (push_ok) begin
           q_id[wr_ptr] <= i_id;
           q_len[wr_ptr] <= i_len;
           q_enh[wr_ptr] <= i_enh;
       end
   end

   always @(posedge clk) begin
       if (rst) begin
           rd_ptr <= {PW{1'b0}};
           wr_ptr <= {PW{1'b0}};
           count <= {(PW+1){1'b0}};
           retries <= 2'd0;
           dropped <= 1'b0;
           drop_id <= 6'd0;
       end else begin
           if (push_ok) wr_ptr <= wr_ptr + 1'b1;
           if (pop) rd_ptr <= rd_ptr + 1'b1;
           if (push_ok && !pop) count <= count + 1'b1;
           else if (pop && !push_ok) count <= count - 1'b1;
           if (i_done || retry_out) retries <= 2'd0;
           else if (i_fail && o_valid) retries <= retries + 2'd1;
           if (pop && retry_out) begin
               dropped <= 1'b1;
               drop_id <= q_id[rd_ptr];
           end
       end
   end

   assign o_ready = (count != DEPTH);
   assign o_valid = (count != 0);
   assign o_id = q_id[rd_ptr];
   assign o_flen = {1'b0, q_len[rd_ptr]} + 5'd1;
   assign o_enh = q_enh[rd_ptr];
   assign o_count = count;
   assign o_rd_ptr = rd_ptr;
   assign o_wr_ptr = wr_ptr;
   assign o_dropped = dropped;
   assign o_drop_id = drop_id;
endmodule

module lin_master_tx (
    input wire clk,
    input wire rst,
    input wire i_tick,
    input wire i_start,
    input wire i_abort,
    input wire i_enhanced,
    input wire [5:0] i_id,
    input wire [3:0] i_len,
    input wire i_wr_en,
    input wire [3:0] i_wr_addr,
    input wire [31:0] i_wr_data,
    output wire o_busy,
    output wire o_bus_low,
   output wire [31:0] o_tx_byte,
   output wire o_req_ready,
   output wire [2:0] o_q_count,
   output wire o_dropped,
   output wire [5:0] o_drop_id
);
    // one-hot frame phase: 0 IDLE, 1 BREAK, 2 SYNC, 3 PID, 4 DATA, 5 CSUM
    reg [5:0] phase;
    initial phase = 6'b000001;
    reg [31:0] brk_cnt = 32'd0;
    reg [31:0] byte_idx = 32'd0;
    reg [31:0] bytes_left = 32'd0;
    reg [31:0] csum = 32'd0;
    reg [31:0] tx_byte = 32'd0;
    reg [7:0] pid_reg = 8'd0;
    reg [31:0] data_buf [0:15];
    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) data_buf[i] = 32'd0;
    end
    reg armed = 1'b1;
    reg pv = 1'b0;

   // header request queue: i_start enqueues, the transmitter launches from the head
   localparam QDEPTH = 4;
   localparam QPW = 2;
   wire q_ready, hd_valid, hd_enh, q_dropped;
   wire [5:0] hd_id, q_drop_id;
   wire [4:0] hd_flen;
   wire [QPW:0] q_count;
   wire [QPW-1:0] q_rd_ptr, q_wr_ptr;
   wire [31:0] frame_len = {27'd0, hd_flen};
   wire q_done = i_tick && phase[5] && !i_abort;
   wire q_fail = i_abort && !phase[0];

   lin_hdr_queue #(.DEPTH(QDEPTH), .PW(QPW), .MAX_RETRY(3)) u_hdr_q (
       .clk(clk), .rst(rst),
       .i_push(i_start), .i_id(i_id), .i_len(i_len), .i_enh(i_enhanced),
       .i_done(q_done), .i_fail(q_fail),
       .o_ready(q_ready), .o_valid(hd_valid),
       .o_id(hd_id), .o_flen(hd_flen), .o_enh(hd_enh),
       .o_count(q_count), .o_rd_ptr(q_rd_ptr), .o_wr_ptr(q_wr_ptr),
       .o_dropped(q_dropped), .o_drop_id(q_drop_id)
   );

    wire [7:0] cur_byte = data_buf[byte_idx[3:0]][7:0];
    wire [8:0] csum_sum = {1'b0, csum[7:0]} + {1'b0, cur_byte};
    wire [7:0] csum_next = csum_sum[8] ? (csum_sum[7:0] + 8'd1) : csum_sum[7:0];
   wire p0 = hd_id[0] ^ hd_id[1] ^ hd_id[2] ^ hd_id[4];
   wire p1 = ~(hd_id[1] ^ hd_id[3] ^ hd_id[4] ^ hd_id[5]);
   wire [7:0] pid_calc = {p1, p0, hd_id};

    always @(posedge clk) begin
        pv <= 1'b1;
        if (i_abort) armed <= 1'b0;
    end

    always @(posedge clk) begin
        if (i_wr_en) data_buf[i_wr_addr] <= i_wr_data;
    end

    always @(posedge clk) begin
        if (rst || i_abort) begin
            phase <= 6'b000001;
            brk_cnt <= 32'd0;
            byte_idx <= 32'd0;
            bytes_left <= 32'd0;
        end else if (i_tick) begin
           if (phase[0] && hd_valid) begin
                phase[0] <= 1'b0;
                phase[1] <= 1'b1;
                brk_cnt <= 32'd0;
                pid_reg <= pid_calc;
               csum <= hd_enh ? {24'd0, pid_calc} : 32'd0;
            end
            if (phase[1]) begin
                if (brk_cnt == 32'd12) begin
                    phase[1] <= 1'b0;
                    phase[2] <= 1'b1;
                end
                brk_cnt <= brk_cnt + 32'd1;
            end
            if (phase[2]) begin
                tx_byte <= 32'h00000055;
                phase[2] <= 1'b0;
                phase[3] <= 1'b1;
            end
            if (phase[3]) begin
                tx_byte <= {24'd0, pid_reg};
                byte_idx <= 32'd0;
                bytes_left <= frame_len;
                phase[3] <= 1'b0;
                phase[4] <= 1'b1;
            end
            if (phase[4]) begin
                tx_byte <= {24'd0, cur_byte};
                csum <= {24'd0, csum_next};
                byte_idx <= byte_idx + 32'd1;
                bytes_left <= bytes_left - 32'd1;
                if (byte_idx == frame_len - 32'd1) phase[4] <= 1'b0;
                if (bytes_left == 32'd1) phase[5] <= 1'b1;
            end
            if (phase[5]) begin
                tx_byte <= {24'd0, ~csum[7:0]};
                phase[5] <= 1'b0;
                phase[0] <= 1'b1;
            end
        end
    end

    assign o_busy = !phase[0];
    assign o_bus_low = phase[1];
    assign o_tx_byte = tx_byte;
   assign o_req_ready = q_ready;
   assign o_q_count = q_count;
   assign o_dropped = q_dropped;
   assign o_drop_id = q_drop_id;

    // Absence, before first abort: checksum phase never begins while data phase is still active
    always @(posedge clk)
        if (pv && armed && $rose(phase[5]))
            assert (!phase[4]);
endmodule

module prbs_win_log #(
   parameter DEPTH = 4,
   parameter AW    = 2
) (
   input  wire        clk,
   input  wire        i_reset,
   input  wire        i_ce,
   input  wire        i_close,
   input  wire [63:0] i_tally,
   input  wire [63:0] i_end,
   output wire [AW:0] o_fill,
   output wire [63:0] o_last_tally,
   output wire [63:0] o_last_end,
   output wire [63:0] o_worst,
   output wire [7:0]  o_clean,
   output wire        o_wrap,
   output wire        o_rising
);
   reg [63:0]   tally [0:DEPTH-1];
   reg [63:0]   ends  [0:DEPTH-1];
   reg [AW-1:0] wr_ptr;
   reg [AW:0]   fill;
   reg [63:0]   worst;
   reg [7:0]    clean;
   reg          wrap;
   integer i;

   initial begin
       for (i = 0; i < DEPTH; i = i + 1) begin
           tally[i] = 64'd0;
           ends[i]  = 64'd0;
       end
   end
   initial wr_ptr = {AW{1'b0}};
   initial fill   = {(AW+1){1'b0}};
   initial worst  = 64'd0;
   initial clean  = 8'd0;
   initial wrap   = 1'b0;

   wire [AW-1:0] last_idx = wr_ptr - 1'b1;
   wire [AW-1:0] prev_idx = wr_ptr - 2'd2;
   wire          full     = (fill == DEPTH);
   wire          push     = i_ce && i_close;

   always @(posedge clk) begin
       if (i_reset) begin
           for (i = 0; i < DEPTH; i = i + 1) begin
               tally[i] <= 64'd0;
               ends[i]  <= 64'd0;
           end
           wr_ptr <= {AW{1'b0}};
           fill   <= {(AW+1){1'b0}};
           worst  <= 64'd0;
           clean  <= 8'd0;
           wrap   <= 1'b0;
       end else if (push) begin
           // record the closing window and advance the ring
           tally[wr_ptr] <= i_tally;
           ends[wr_ptr]  <= i_end;
           wr_ptr        <= wr_ptr + 1'b1;
           if (full)
               wrap <= 1'b1;
           else
               fill <= fill + 1'b1;
           if (i_tally > worst)
               worst <= i_tally;
           if ((i_tally == 64'd0) && (clean != 8'hFF))
               clean <= clean + 8'd1;
       end
   end

   assign o_fill       = fill;
   assign o_last_tally = tally[last_idx];
   assign o_last_end   = ends[last_idx];
   assign o_worst      = worst;
   assign o_clean      = clean;
   assign o_wrap       = wrap;
   assign o_rising     = (fill >= 2) && (tally[last_idx] > tally[prev_idx]);
endmodule

module prbs_win_checker (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_bit,
    input  wire        i_arm,
    input  wire        i_disarm,
    output wire        o_sync,
   output wire [63:0] o_errs,
   output wire [2:0]  o_log_fill,
   output wire [63:0] o_log_last,
   output wire [63:0] o_log_last_end,
   output wire [63:0] o_log_worst,
   output wire [7:0]  o_log_clean,
   output wire        o_log_wrap,
   output wire        o_log_rising
);
    localparam [63:0] SYNC_LEN = 64'd8;
    localparam [63:0] LOSS_LEN = 64'd4;
    localparam [63:0] MAXV     = 64'hFFFFFFFFFFFFFFFF;
   localparam LOG_DEPTH = 4;
   localparam LOG_AW    = 2;

    reg [63:0] ref_sr;
    reg        sync;
    reg [63:0] match_run;
    reg [63:0] bad_run;
    reg [63:0] err_cnt;
    reg        win;
    reg [63:0] err_snap;
    reg [63:0] win_errs;

    initial ref_sr    = 64'h1;
    initial sync      = 1'b0;
    initial match_run = 64'd0;
    initial bad_run   = 64'd0;
    initial err_cnt   = 64'd0;
    initial win       = 1'b0;
    initial err_snap  = 64'd0;
    initial win_errs  = 64'd0;

    // PRBS x^64 + x^63 + x^61 + x^60 + 1 prediction
    wire        pred    = ref_sr[63] ^ ref_sr[62] ^ ref_sr[60] ^ ref_sr[59];
    wire        mism    = sync && (i_bit != pred);
    wire        cnt_inc = mism && (err_cnt != MAXV);
    wire [63:0] err_nxt = cnt_inc ? (err_cnt + 64'd1) : err_cnt;
    wire        lose    = mism && ((bad_run + 64'd1) >= LOSS_LEN);
    wire        open_w  = i_arm && sync && !lose && !i_disarm;
    wire        close_w = i_disarm || lose;

   // window history log: one entry per closed window
   wire              log_close = win && close_w;
   wire [63:0]       win_fin   = cnt_inc ? (win_errs + 64'd1) : win_errs;
   wire [LOG_AW:0]   log_fill;
   wire [63:0]       log_last_tally;
   wire [63:0]       log_last_end;
   wire [63:0]       log_worst;
   wire [7:0]        log_clean;
   wire              log_wrap;
   wire              log_rising;

   prbs_win_log #(.DEPTH(LOG_DEPTH), .AW(LOG_AW)) u_log (
       .clk          (clk),
       .i_reset      (i_reset),
       .i_ce         (i_ce),
       .i_close      (log_close),
       .i_tally      (win_fin),
       .i_end        (err_nxt),
       .o_fill       (log_fill),
       .o_last_tally (log_last_tally),
       .o_last_end   (log_last_end),
       .o_worst      (log_worst),
       .o_clean      (log_clean),
       .o_wrap       (log_wrap),
       .o_rising     (log_rising)
   );

    always @(posedge clk) begin
        if (i_reset) begin
            ref_sr    <= 64'h1;
            sync      <= 1'b0;
            match_run <= 64'd0;
            bad_run   <= 64'd0;
            err_cnt   <= 64'd0;
            win       <= 1'b0;
            err_snap  <= 64'd0;
            win_errs  <= 64'd0;
        end else if (i_ce) begin
            err_cnt <= err_nxt;
            if (!sync) begin
                // self-synchronising: load incoming stream into reference
                ref_sr  <= {ref_sr[62:0], i_bit};
                bad_run <= 64'd0;
                if (i_bit == pred) begin
                    if ((match_run + 64'd1) >= SYNC_LEN) begin
                        sync      <= 1'b1;
                        match_run <= 64'd0;
                    end else begin
                        match_run <= match_run + 64'd1;
                    end
                end else begin
                    match_run <= 64'd0;
                end
            end else begin
                // locked: free-run the local reference
                ref_sr    <= {ref_sr[62:0], pred};
                match_run <= 64'd0;
                if (mism) begin
                    if (lose) begin
                        sync    <= 1'b0;
                        bad_run <= 64'd0;
                    end else begin
                        bad_run <= bad_run + 64'd1;
                    end
                end else begin
                    bad_run <= 64'd0;
                end
            end
            // measurement window: opened by arm while locked, closed by disarm or sync loss
            if (win) begin
                if (close_w) win <= 1'b0;
                if (cnt_inc) win_errs <= win_errs + 64'd1;
            end else if (open_w) begin
                win      <= 1'b1;
                err_snap <= err_nxt;
                win_errs <= 64'd0;
            end
        end
    end

    assign o_sync = sync;
    assign o_errs = err_cnt;
   assign o_log_fill     = log_fill;
   assign o_log_last     = log_last_tally;
   assign o_log_last_end = log_last_end;
   assign o_log_worst    = log_worst;
   assign o_log_clean    = log_clean;
   assign o_log_wrap     = log_wrap;
   assign o_log_rising   = log_rising;

    // Precedence inside the window: a nonzero window tally requires the global
    // counter to have advanced past the snapshot recorded when the window opened.
    always @(*)
        if (win && (win_errs != 64'd0))
            assert (err_cnt != err_snap);

    // With no window errors, the global counter must still equal the snapshot.
    always @(*)
        if (win && (win_errs == 64'd0))
            assert (err_cnt == err_snap);

   // Windows are ordered: the last logged window ended no later than the
   // point where the currently open window started.
   always @(*)
       if (win && (log_fill != 3'd0))
           assert (log_last_end <= err_snap);
endmodule

module neo_ringstop (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        ring_in_vld,
    input  wire [63:0] ring_in_data,
    input  wire [3:0]  ring_in_dst,
    input  wire        push,
    input  wire [63:0] push_data,
    input  wire [3:0]  my_id,
    output wire        ring_hold,
    output wire        eject_vld,
    output wire [63:0] eject_data,
    output wire        out_vld,
    output wire [63:0] out_data,
    output wire [3:0]  out_dst
,
    output wire [4:0] q_count_o,
    output wire [4:0] q_head_o,
    output wire [4:0] q_tail_o
);
    reg        slot_vld = 1'b0;
    reg [63:0] slot_data = 64'd0;
    reg [3:0]  slot_dst = 4'd0;
    reg [63:0] fifo [0:15];
    reg [4:0]  q_head = 5'd0;
    reg [4:0]  q_tail = 5'd0;
    reg [4:0]  q_count = 5'd0;
    reg [63:0] starve_cnt = 64'd0;
    reg        rsv = 1'b0;
    reg [63:0] inj_total = 64'd0;
    reg        pre_rsv = 1'b1;
    reg        pv = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) fifo[i] = 64'd0;
    end

    wire through   = ring_in_vld && (ring_in_dst != my_id);
    wire nonempty  = (q_head != q_tail);
    wire free_slot = (!through) || rsv;
    wire pop       = nonempty && free_slot;
    wire push_ok   = push && (q_count < 5'd16);
    wire dec       = pop && (q_count != 5'd0);

    assign ring_hold  = rsv && through;
    assign eject_vld  = ring_in_vld && (ring_in_dst == my_id);
    assign eject_data = ring_in_data;
    assign out_vld    = slot_vld;
    assign out_data   = slot_data;
    assign out_dst    = slot_dst;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            slot_vld   <= 1'b0;
            slot_data  <= 64'd0;
            slot_dst   <= 4'd0;
            q_head     <= 5'd0;
            q_tail     <= 5'd0;
            q_count    <= 5'd0;
            starve_cnt <= 64'd0;
            rsv        <= 1'b0;
            inj_total  <= 64'd0;
            pre_rsv    <= 1'b1;
        end else if (en) begin
            if (pop) begin
                slot_vld  <= 1'b1;
                slot_data <= fifo[q_head[3:0]];
                slot_dst  <= fifo[q_head[3:0]][3:0];
                q_head    <= q_head + 5'd1;
                inj_total <= inj_total + 64'd1;
            end else if (through) begin
                slot_vld  <= 1'b1;
                slot_data <= ring_in_data;
                slot_dst  <= ring_in_dst;
            end else begin
                slot_vld  <= 1'b0;
            end

            if (push_ok) begin
                fifo[q_tail[3:0]] <= push_data;
                q_tail <= q_tail + 5'd1;
            end

            q_count <= q_count + {4'd0, push_ok} - {4'd0, dec};

            if (pop)
                starve_cnt <= 64'd0;
            else if (nonempty)
                starve_cnt <= starve_cnt + 64'd1;

            if (pop)
                rsv <= 1'b0;
            else if (starve_cnt == 64'd1000) begin
                rsv     <= 1'b1;
                pre_rsv <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (pv && !$past(rst) && pre_rsv && $stable(q_tail) && $stable(q_count))
            assert ($stable(q_head));
    assign q_count_o = q_count;
    assign q_head_o = q_head;
    assign q_tail_o = q_tail;
endmodule

module pretrig_capture (
    input  wire        clk,
    input  wire        ce,
    input  wire        rearm,
    input  wire        trig,
    input  wire [63:0] sample,
    input  wire [5:0]  rd_idx,
    output wire [63:0] rd_data,
    output wire        is_frozen,
    output wire [63:0] captured
,
    output wire [63:0] count_o,
    output wire frozen_o,
    output wire [47:0] valid_o
);
    localparam [63:0] DEPTH = 64'd48;
    reg [63:0] chain [0:47];
    reg [47:0] valid;
    reg [63:0] count;
    reg        frozen;
    reg        pv;
    integer i;

    initial begin
        for (i = 0; i < 48; i = i + 1) chain[i] = 64'd0;
        valid  = 48'd0;
        count  = 64'd0;
        frozen = 1'b0;
        pv     = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rearm) begin
            frozen <= 1'b0;
            count  <= 64'd0;
            valid  <= 48'd0;
        end else if (ce && !frozen) begin
            if (trig && count == DEPTH) begin
                frozen <= 1'b1;
            end else begin
                chain[0] <= sample;
                for (i = 1; i < 48; i = i + 1) chain[i] <= chain[i-1];
                valid <= {valid[46:0], 1'b1};
                if (count != DEPTH) count <= count + 64'd1;
            end
        end
    end

    assign rd_data   = (rd_idx < 6'd48) ? chain[rd_idx] : 64'd0;
    assign is_frozen = frozen;
    assign captured  = count;

    always @(posedge clk)
        if (pv && $rose(frozen))
            assert (valid == 48'hFFFFFFFFFFFF);
    assign count_o = count;
    assign frozen_o = frozen;
    assign valid_o = valid;
endmodule

module ringstop_trace (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        ring_in_vld,
    input  wire [63:0] ring_in_data,
    input  wire [3:0]  ring_in_dst,
    input  wire        push,
    input  wire [63:0] push_data,
    input  wire [3:0]  my_id,
    input  wire        trig,
    input  wire        rearm,
    input  wire [5:0]  rd_idx,
    output wire        ring_hold,
    output wire        out_vld,
    output wire [63:0] out_data,
    output wire [3:0]  out_dst,
    output wire        eject_vld,
    output wire [63:0] eject_data,
    output wire [63:0] rd_data,
    output wire        is_frozen,
    output wire [63:0] captured,
    output wire        trace_vld,
    output wire [63:0] trace_data,
    output wire [5:0]  trace_offered_o,
    output wire [5:0]  trace_missed
);
    wire [4:0]  a_q_count;
    wire [4:0]  a_q_head;
    wire [4:0]  a_q_tail;
    wire [63:0] b_count;
    wire        b_frozen;
    wire [47:0] b_valid;

    reg        g_vld = 1'b0;
    reg [63:0] g_data = 64'd0;
    reg [5:0]  trace_offered = 6'd0;

    neo_ringstop u_ring (
        .clk(clk),
        .rst(rst),
        .en(en),
        .ring_in_vld(ring_in_vld),
        .ring_in_data(ring_in_data),
        .ring_in_dst(ring_in_dst),
        .push(push),
        .push_data(push_data),
        .my_id(my_id),
        .ring_hold(ring_hold),
        .eject_vld(eject_vld),
        .eject_data(eject_data),
        .out_vld(out_vld),
        .out_data(out_data),
        .out_dst(out_dst),
        .q_count_o(a_q_count),
        .q_head_o(a_q_head),
        .q_tail_o(a_q_tail)
    );

    always @(posedge clk) begin
        if (rst) begin
            g_vld  <= 1'b0;
            g_data <= 64'd0;
        end else begin
            g_vld <= eject_vld;
            if (eject_vld)
                g_data <= eject_data;
        end
    end

    always @(posedge clk) begin
        if (rearm)
            trace_offered <= 6'd0;
        else if (g_vld && (trace_offered != 6'd63))
            trace_offered <= trace_offered + 6'd1;
    end

    pretrig_capture u_trace (
        .clk(clk),
        .ce(g_vld),
        .rearm(rearm),
        .trig(trig),
        .sample(g_data),
        .rd_idx(rd_idx),
        .rd_data(rd_data),
        .is_frozen(is_frozen),
        .captured(captured),
        .count_o(b_count),
        .frozen_o(b_frozen),
        .valid_o(b_valid)
    );

    assign trace_vld       = g_vld;
    assign trace_data      = g_data;
    assign trace_offered_o = trace_offered;
    assign trace_missed    = trace_offered - b_count[5:0];

    always @(posedge clk)
        if (b_frozen)
            assert (trace_offered > 6'd48);
endmodule

module lookup_req_queue #(
   parameter DEPTH = 4,
   parameter AW    = 2
) (
   input  wire          clk,
   input  wire          rst,
   input  wire          ce,
   input  wire          push,
   input  wire [63:0]   push_key,
   input  wire [15:0]   push_len,
   input  wire          pop,
   input  wire          tbl_wr,
   input  wire [6:0]    tbl_idx,
   output wire          ready,
   output wire          avail,
   output wire [63:0]   head_key,
   output wire [15:0]   head_len,
   output reg  [AW:0]   count,
   output reg  [6:0]    hwm,
   output wire [6:0]    scan_lim
);
   reg [63:0]   key_q [0:DEPTH-1];
   reg [15:0]   len_q [0:DEPTH-1];
   reg [AW-1:0] wr_ptr;
   reg [AW-1:0] rd_ptr;

   integer n;
   initial begin
       for (n = 0; n < DEPTH; n = n + 1) begin
           key_q[n] = 64'd0;
           len_q[n] = 16'd0;
       end
       wr_ptr = {AW{1'b0}};
       rd_ptr = {AW{1'b0}};
       count  = {(AW+1){1'b0}};
       hwm    = 7'd0;
   end

   assign ready    = (count != DEPTH);
   assign avail    = (count != {(AW+1){1'b0}});
   assign head_key = key_q[rd_ptr];
   assign head_len = len_q[rd_ptr];
   // highest rule index that can hold a valid entry, including a write landing this cycle
   assign scan_lim = (tbl_wr && (tbl_idx > hwm)) ? tbl_idx : hwm;

   wire do_push = push && ready;
   wire do_pop  = pop && avail;

   always @(posedge clk) begin
       if (rst) begin
           wr_ptr <= {AW{1'b0}};
           rd_ptr <= {AW{1'b0}};
           count  <= {(AW+1){1'b0}};
           hwm    <= 7'd0;
       end else if (ce) begin
           if (do_push) begin
               key_q[wr_ptr] <= push_key;
               len_q[wr_ptr] <= push_len;
               wr_ptr        <= wr_ptr + 1'b1;
           end
           if (do_pop)
               rd_ptr <= rd_ptr + 1'b1;
           if (do_push && !do_pop)
               count <= count + 1'b1;
           else if (do_pop && !do_push)
               count <= count - 1'b1;
           if (tbl_wr)
               hwm <= scan_lim;
       end
   end
endmodule

module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
output reg  [6:0]  rsp_rule,
output wire        req_ready,
output wire [2:0]  req_pending,
output wire [6:0]  scan_limit
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;
reg [6:0]  q_lim;

wire        rq_ready;
wire        rq_avail;
wire [63:0] rq_key;
wire [15:0] rq_len;
wire [2:0]  rq_count;
wire [6:0]  rq_hwm;
wire [6:0]  rq_scan_lim;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
q_lim      = 7'd0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
wire last = (idx == q_lim);

lookup_req_queue #(.DEPTH(4), .AW(2)) u_req_q (
    .clk      (clk),
    .rst      (rst),
    .ce       (i_ce),
    .push     (req),
    .push_key (req_key),
    .push_len (req_len),
    .pop      (!busy),
    .tbl_wr   (wr_en && !busy),
    .tbl_idx  (wr_idx),
    .ready    (rq_ready),
    .avail    (rq_avail),
    .head_key (rq_key),
    .head_len (rq_len),
    .count    (rq_count),
    .hwm      (rq_hwm),
    .scan_lim (rq_scan_lim)
);

assign req_ready   = rq_ready;
assign req_pending = rq_count;
assign scan_limit  = rq_hwm;

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
q_lim     <= 7'd0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
if (rq_avail) begin
                    busy  <= 1'b1;
                    idx   <= 7'd0;
timer <= {1'b0, rq_scan_lim} + 8'd1;
q_key <= rq_key;
q_len <= {48'd0, rq_len};
q_lim <= rq_scan_lim;
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
endmodule

// Host-side scheduler for the flow classifier. The flow table only takes a
// lookup or a rule write while it is not scanning, so both are queued here
// and handed over while no lookup is outstanding; every accepted lookup is
// given a sequence tag that comes back with its completion.
module lookup_scheduler #(
   parameter RQ_AW = 2,
   parameter WQ_AW = 2,
   parameter TAG_W = 4
) (
   input  wire             clk,
   input  wire             rst,
   input  wire             i_ce,
   input  wire             in_req,
   input  wire [63:0]      in_key,
   input  wire [15:0]      in_len,
   output wire             in_ready,
   output wire [TAG_W-1:0] in_tag,
   input  wire             in_wr,
   input  wire [6:0]       in_wr_idx,
   input  wire [63:0]      in_wr_key,
   input  wire [31:0]      in_wr_action,
   output wire             wr_ready,
   input  wire             tb_rsp_valid,
   input  wire             tb_rsp_hit,
   output wire             tb_req,
   output wire [63:0]      tb_key,
   output wire [15:0]      tb_len,
   output wire             tb_wr,
   output wire [6:0]       tb_wr_idx,
   output wire [63:0]      tb_wr_key,
   output wire [31:0]      tb_wr_action,
   output wire             done_valid,
   output wire             done_hit,
   output wire [TAG_W-1:0] done_tag,
   output wire             pend_o,
   output wire [RQ_AW:0]   rq_cnt_o,
   output wire [WQ_AW:0]   wq_cnt_o,
   output wire [RQ_AW:0]   rq_hwm_o,
   output wire [15:0]      miss_cnt_o
);
   localparam RQ_DEPTH = 1 << RQ_AW;
   localparam WQ_DEPTH = 1 << WQ_AW;
   reg [63:0]      rq_key [0:RQ_DEPTH-1];
   reg [15:0]      rq_len [0:RQ_DEPTH-1];
   reg [TAG_W-1:0] rq_tag [0:RQ_DEPTH-1];
   reg [RQ_AW-1:0] rq_wp;
   reg [RQ_AW-1:0] rq_rp;
   reg [RQ_AW:0]   rq_cnt;
   reg [RQ_AW:0]   rq_hwm;
   reg [TAG_W-1:0] tag_ctr;
   reg [6:0]       wq_idx [0:WQ_DEPTH-1];
   reg [63:0]      wq_key [0:WQ_DEPTH-1];
   reg [31:0]      wq_act [0:WQ_DEPTH-1];
   reg [WQ_AW-1:0] wq_wp;
   reg [WQ_AW-1:0] wq_rp;
   reg [WQ_AW:0]   wq_cnt;
   reg             pend;
   reg [TAG_W-1:0] cur_tag;
   reg [15:0]      miss_cnt;
   integer k;
   initial begin
       for (k = 0; k < RQ_DEPTH; k = k + 1) begin
           rq_key[k] = 64'd0;
           rq_len[k] = 16'd0;
           rq_tag[k] = {TAG_W{1'b0}};
       end
       for (k = 0; k < WQ_DEPTH; k = k + 1) begin
           wq_idx[k] = 7'd0;
           wq_key[k] = 64'd0;
           wq_act[k] = 32'd0;
       end
       rq_wp    = {RQ_AW{1'b0}};
       rq_rp    = {RQ_AW{1'b0}};
       rq_cnt   = {(RQ_AW+1){1'b0}};
       rq_hwm   = {(RQ_AW+1){1'b0}};
       tag_ctr  = {TAG_W{1'b0}};
       wq_wp    = {WQ_AW{1'b0}};
       wq_rp    = {WQ_AW{1'b0}};
       wq_cnt   = {(WQ_AW+1){1'b0}};
       pend     = 1'b0;
       cur_tag  = {TAG_W{1'b0}};
       miss_cnt = 16'd0;
   end
   wire rq_full  = (rq_cnt == RQ_DEPTH);
   wire rq_empty = (rq_cnt == 0);
   wire wq_full  = (wq_cnt == WQ_DEPTH);
   wire wq_empty = (wq_cnt == 0);
   // the table is handed work only while none of ours is outstanding
   assign tb_req = !pend && !rq_empty;
   assign tb_wr  = !pend && !wq_empty;
   wire rq_pop  = i_ce && tb_req;
   wire wq_pop  = i_ce && tb_wr;
   wire rq_push = i_ce && in_req && !rq_full;
   // a rule write to the same index as the newest queued write replaces it
   // in place, unless that entry is the one leaving for the table this cycle
   wire [WQ_AW-1:0] wq_tail = wq_wp - 1'b1;
   wire wq_tail_leaving = tb_wr && (wq_cnt == 1);
   wire wr_merge = !wq_empty && !wq_tail_leaving && (wq_idx[wq_tail] == in_wr_idx);
   wire wr_take  = i_ce && in_wr && (!wq_full || wr_merge);
   wire wr_push  = wr_take && !wr_merge;
   assign in_ready = !rq_full;
   assign in_tag   = tag_ctr;
   assign wr_ready = !wq_full || wr_merge;
   assign tb_key       = rq_key[rq_rp];
   assign tb_len       = rq_len[rq_rp];
   assign tb_wr_idx    = wq_idx[wq_rp];
   assign tb_wr_key    = wq_key[wq_rp];
   assign tb_wr_action = wq_act[wq_rp];
   wire done = tb_rsp_valid && pend;
   always @(posedge clk) begin
       if (rst) begin
           rq_wp   <= {RQ_AW{1'b0}};
           rq_rp   <= {RQ_AW{1'b0}};
           rq_cnt  <= {(RQ_AW+1){1'b0}};
           rq_hwm  <= {(RQ_AW+1){1'b0}};
           tag_ctr <= {TAG_W{1'b0}};
       end else if (i_ce) begin
           if (rq_push) begin
               rq_key[rq_wp] <= in_key;
               rq_len[rq_wp] <= in_len;
               rq_tag[rq_wp] <= tag_ctr;
               rq_wp         <= rq_wp + 1'b1;
               tag_ctr       <= tag_ctr + 1'b1;
           end
           if (rq_pop)
               rq_rp <= rq_rp + 1'b1;
           if (rq_push && !rq_pop)
               rq_cnt <= rq_cnt + 1'b1;
           else if (rq_pop && !rq_push)
               rq_cnt <= rq_cnt - 1'b1;
           if (rq_cnt > rq_hwm)
               rq_hwm <= rq_cnt;
       end
   end
   always @(posedge clk) begin
       if (rst) begin
           wq_wp  <= {WQ_AW{1'b0}};
           wq_rp  <= {WQ_AW{1'b0}};
           wq_cnt <= {(WQ_AW+1){1'b0}};
       end else if (i_ce) begin
           if (wr_take && wr_merge) begin
               wq_key[wq_tail] <= in_wr_key;
               wq_act[wq_tail] <= in_wr_action;
           end else if (wr_push) begin
               wq_idx[wq_wp] <= in_wr_idx;
               wq_key[wq_wp] <= in_wr_key;
               wq_act[wq_wp] <= in_wr_action;
               wq_wp         <= wq_wp + 1'b1;
           end
           if (wq_pop)
               wq_rp <= wq_rp + 1'b1;
           if (wr_push && !wq_pop)
               wq_cnt <= wq_cnt + 1'b1;
           else if (wq_pop && !wr_push)
               wq_cnt <= wq_cnt - 1'b1;
       end
   end
   always @(posedge clk) begin
       if (rst) begin
           pend     <= 1'b0;
           cur_tag  <= {TAG_W{1'b0}};
           miss_cnt <= 16'd0;
       end else if (i_ce) begin
           if (rq_pop) begin
               pend    <= 1'b1;
               cur_tag <= rq_tag[rq_rp];
           end else if (tb_rsp_valid) begin
               pend <= 1'b0;
           end
           if (done && !tb_rsp_hit && (miss_cnt != 16'hFFFF))
               miss_cnt <= miss_cnt + 16'd1;
       end
   end
   assign done_valid = done;
   assign done_hit   = tb_rsp_hit;
   assign done_tag   = cur_tag;
   assign pend_o     = pend;
   assign rq_cnt_o   = rq_cnt;
   assign wq_cnt_o   = wq_cnt;
   assign rq_hwm_o   = rq_hwm;
   assign miss_cnt_o = miss_cnt;
endmodule
module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
    output reg  [6:0]  rsp_rule
,
    output wire busy_o,
    output wire [6:0] idx_o,
    output wire [7:0] timer_o
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
    wire last = (idx == 7'd127);

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
                if (req) begin
                    busy  <= 1'b1;
                    idx   <= 7'd0;
                    timer <= 8'd128;
                    q_key <= req_key;
                    q_len <= {48'd0, req_len};
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
    assign busy_o = busy;
    assign idx_o = idx;
    assign timer_o = timer;
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
    output reg         fault
,
    output wire hit_q_o,
    output wire miss_q_o
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
            fault  <= miss_q;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
    assign hit_q_o = hit_q;
    assign miss_q_o = miss_q;
endmodule

module flow_mpu_top (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    output wire        grant,
    output wire        fault,
    output wire [6:0]  rsp_rule,
    output wire        g_valid_o,
    output wire [15:0] g_addr_o,
   output wire        g_write_o,
   output wire        req_ready,
   output wire [3:0]  req_tag,
   output wire        wr_ready,
   output wire        lk_done,
   output wire        lk_hit,
   output wire [3:0]  lk_tag,
   output wire        sch_pend_o,
   output wire [2:0]  rq_cnt_o,
   output wire [2:0]  wq_cnt_o,
   output wire [2:0]  rq_hwm_o,
   output wire [15:0] miss_cnt_o
);
    wire        rsp_valid;
    wire        rsp_hit;
    wire [31:0] rsp_action;
    wire        busy_a;
    wire [6:0]  idx_a;
    wire [7:0]  timer_a;
    wire        hit_q;
    wire        miss_q;
   wire        s_req;
   wire [63:0] s_key;
   wire [15:0] s_len;
   wire        s_wr;
   wire [6:0]  s_wr_idx;
   wire [63:0] s_wr_key;
   wire [31:0] s_wr_action;
   wire        sch_pend;
   wire [2:0]  rq_cnt;
   wire [2:0]  wq_cnt;
   wire [2:0]  rq_hwm;

    // pending destination-buffer access handed from the classifier to the MPU
    reg        g_valid;
    reg [15:0] g_addr;
    reg        g_write;

    initial begin
        g_valid = 1'b0;
        g_addr  = 16'd0;
        g_write = 1'b0;
    end

    flow_match_table u_flow (
        .clk(clk),
        .rst(rst),
        .i_ce(i_ce),
       .req(s_req),
       .req_key(s_key),
       .req_len(s_len),
       .wr_en(s_wr),
       .wr_idx(s_wr_idx),
       .wr_key(s_wr_key),
       .wr_action(s_wr_action),
        .rsp_valid(rsp_valid),
        .rsp_hit(rsp_hit),
        .rsp_action(rsp_action),
        .rsp_rule(rsp_rule),
        .busy_o(busy_a),
        .idx_o(idx_a),
        .timer_o(timer_a)
    );

    always @(posedge clk) begin
        if (rst) begin
            g_valid <= 1'b0;
            g_addr  <= 16'd0;
            g_write <= 1'b0;
        end else if (i_ce) begin
            g_valid <= rsp_valid && rsp_hit;
            if (rsp_valid && rsp_hit) begin
                g_addr  <= rsp_action[15:0];
                g_write <= rsp_action[16];
            end
        end
    end

    mpu_region_checker u_mpu (
        .clk(clk),
        .i_ce(i_ce),
        .cfg_we(cfg_we),
        .cfg_idx(cfg_idx),
        .cfg_base(cfg_base),
        .cfg_limit(cfg_limit),
        .cfg_perm(cfg_perm),
        .lock_req(lock_req),
        .acc_valid(g_valid),
        .acc_write(g_write),
        .acc_addr(g_addr),
        .grant(grant),
        .fault(fault),
        .hit_q_o(hit_q),
        .miss_q_o(miss_q)
    );

    assign g_valid_o = g_valid;
    assign g_addr_o  = g_addr;
    assign g_write_o = g_write;
   lookup_scheduler #(
       .RQ_AW(2),
       .WQ_AW(2),
       .TAG_W(4)
   ) u_sched (
       .clk(clk),
       .rst(rst),
       .i_ce(i_ce),
       .in_req(req),
       .in_key(req_key),
       .in_len(req_len),
       .in_ready(req_ready),
       .in_tag(req_tag),
       .in_wr(wr_en),
       .in_wr_idx(wr_idx),
       .in_wr_key(wr_key),
       .in_wr_action(wr_action),
       .wr_ready(wr_ready),
       .tb_rsp_valid(rsp_valid),
       .tb_rsp_hit(rsp_hit),
       .tb_req(s_req),
       .tb_key(s_key),
       .tb_len(s_len),
       .tb_wr(s_wr),
       .tb_wr_idx(s_wr_idx),
       .tb_wr_key(s_wr_key),
       .tb_wr_action(s_wr_action),
       .done_valid(lk_done),
       .done_hit(lk_hit),
       .done_tag(lk_tag),
       .pend_o(sch_pend),
       .rq_cnt_o(rq_cnt),
       .wq_cnt_o(wq_cnt),
       .rq_hwm_o(rq_hwm),
       .miss_cnt_o(miss_cnt_o)
   );
   assign sch_pend_o = sch_pend;
   assign rq_cnt_o   = rq_cnt;
   assign wq_cnt_o   = wq_cnt;
   assign rq_hwm_o   = rq_hwm;
   // every response the flow table produces belongs to a lookup the scheduler handed it
   always @(posedge clk)
       if (rsp_valid)
           assert (sch_pend);

    // the MPU never holds two packet steering decisions in its check stage at once
    always @(posedge clk)
        if (g_valid)
            assert (!(hit_q || miss_q));
endmodule

module pico_wakeup (
    input wire        clk,
    input wire        rst_n,
    input wire        en,
    input wire        alloc,
    input wire [31:0] alloc_deps,
    input wire        issue,
    input wire [4:0]  issue_idx
,
    output wire [31:0] dep_or_o,
    output wire [63:0] occ_o,
    output wire [31:0] pend_o,
    output wire [31:0] valid_o,
    output wire [63:0] valid_cnt_o
);
    reg [31:0]   valid    = 32'd0;
    reg [1023:0] dep_flat = 1024'd0;
    reg [31:0]   pend     = 32'd0;
    reg [63:0]   occ      = 64'd0;
    reg [63:0]   wake_cnt = 64'd0;

    initial valid    = 32'd0;
    initial dep_flat = 1024'd0;
    initial pend     = 32'd0;
    initial occ      = 64'd0;
    initial wake_cnt = 64'd0;

    wire full = &valid;

    // lowest free index
    reg [4:0] free_idx;
    integer a;
    always @(*) begin
        free_idx = 5'd0;
        for (a = 31; a >= 0; a = a - 1)
            if (!valid[a]) free_idx = a[4:0];
    end

    // popcount of valid (status helper)
    reg [63:0] valid_cnt;
    integer b;
    always @(*) begin
        valid_cnt = 64'd0;
        for (b = 0; b < 32; b = b + 1)
            valid_cnt = valid_cnt + {63'd0, valid[b]};
    end

    // per-row OR of dependency matrix (status helper)
    reg [31:0] dep_or;
    integer c;
    always @(*) begin
        for (c = 0; c < 32; c = c + 1)
            dep_or[c] = |dep_flat[c*32 +: 32];
    end

    wire alloc_fire = alloc && !full;
    wire issue_fire = issue && valid[issue_idx] && !pend[issue_idx];
    wire [31:0] clr_mask   = issue_fire ? (32'd1 << issue_idx) : 32'd0;
    wire [31:0] alloc_mask = alloc_fire ? (32'd1 << free_idx)  : 32'd0;
    wire [31:0] new_deps   = alloc_deps & valid & ~clr_mask;

    reg [1023:0] dep_nxt;
    reg [31:0]   pend_nxt;
    reg [63:0]   woke;
    integer k;
    always @(*) begin
        woke = 64'd0;
        dep_nxt = dep_flat;
        pend_nxt = pend;
        for (k = 0; k < 32; k = k + 1) begin
            if (alloc_mask[k]) begin
                dep_nxt[k*32 +: 32] = new_deps;
                pend_nxt[k] = |new_deps;
            end else if (clr_mask[k]) begin
                dep_nxt[k*32 +: 32] = 32'd0;
                pend_nxt[k] = 1'b0;
            end else begin
                dep_nxt[k*32 +: 32] = dep_flat[k*32 +: 32] & ~clr_mask;
                pend_nxt[k] = pend[k] && (|(dep_flat[k*32 +: 32] & ~clr_mask));
                if (pend[k] && !pend_nxt[k])
                    woke = woke + 64'd1;
            end
        end
    end

    wire [31:0] valid_nxt = (valid | alloc_mask) & ~clr_mask;

    always @(posedge clk) begin
        if (!rst_n) begin
            valid    <= 32'd0;
            dep_flat <= 1024'd0;
            pend     <= 32'd0;
            occ      <= 64'd0;
            wake_cnt <= 64'd0;
        end else if (en) begin
            valid    <= valid_nxt;
            dep_flat <= dep_nxt;
            pend     <= pend_nxt;
            wake_cnt <= wake_cnt + woke;
            if (alloc_fire && !issue_fire)
                occ <= occ + 64'd1;
            else if (issue_fire && !alloc_fire)
                occ <= occ - 64'd1;
        end
    end

    always @(posedge clk)
        if (|valid) assert (occ <= 64'd32);
    assign dep_or_o = dep_or;
    assign occ_o = occ;
    assign pend_o = pend;
    assign valid_o = valid;
    assign valid_cnt_o = valid_cnt;
endmodule

module age_matrix_iq (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_alloc,
    input  wire        i_alloc_ready,
    input  wire [31:0] i_alloc_tag,
    input  wire        i_issue,
    input  wire [3:0]  i_wake,
    output reg  [31:0] o_issue_tag,
    output wire        o_issue_valid,
    output wire [31:0] o_issue_cnt
,
    output wire [15:0] age_o,
    output wire [3:0] valid_o
);
    // age[i*4+j] == 1 means entry i is older than entry j
    reg [3:0]   valid = 4'b0000;
    reg [3:0]   ready = 4'b0000;
    reg [15:0]  age = 16'h0000;
    reg [127:0] tags = 128'd0;
    reg [31:0]  issue_cnt = 32'd0;
    reg         armed = 1'b0;
    reg         pv = 1'b0;

    reg [3:0] grant;
    reg [3:0] free_sel;
    integer i, j, k;

    wire [3:0] rv = valid & ready;
    wire issue_fire = i_ce & i_issue & (|rv);
    wire alloc_fire = i_ce & i_alloc & ~(&valid);

    // oldest-ready select: an entry wins if no other ready entry is older
    always @(*) begin
        for (i = 0; i < 4; i = i + 1) begin
            grant[i] = rv[i];
            for (j = 0; j < 4; j = j + 1)
                if (j != i && rv[j] && age[j*4+i]) grant[i] = 1'b0;
        end
        if (!valid[0])      free_sel = 4'b0001;
        else if (!valid[1]) free_sel = 4'b0010;
        else if (!valid[2]) free_sel = 4'b0100;
        else if (!valid[3]) free_sel = 4'b1000;
        else                free_sel = 4'b0000;
        o_issue_tag = 32'd0;
        for (k = 0; k < 4; k = k + 1)
            if (grant[k]) o_issue_tag = o_issue_tag | tags[k*32 +: 32];
    end

    assign o_issue_valid = issue_fire;
    assign o_issue_cnt = issue_cnt;

    always @(posedge clk) begin
        if (issue_fire) begin
            issue_cnt <= issue_cnt + 32'd1;
            armed <= 1'b1;
        end
        for (i = 0; i < 4; i = i + 1) begin
            if (alloc_fire && free_sel[i]) begin
                valid[i] <= 1'b1;
                ready[i] <= i_alloc_ready;
                tags[i*32 +: 32] <= i_alloc_tag;
                for (j = 0; j < 4; j = j + 1)
                    if (j != i) begin
                        age[i*4+j] <= 1'b0;
                        age[j*4+i] <= valid[j];
                    end
            end else begin
                if (issue_fire && grant[i]) valid[i] <= 1'b0;
                if (i_ce && valid[i] && i_wake[i]) ready[i] <= 1'b1;
            end
        end
    end

    always @(posedge clk) pv <= 1'b1;

    // after the first issue: if the valid set did not change, no issue was counted
    always @(posedge clk)
        if (pv && armed && $stable(valid))
            assert ($stable(issue_cnt));
    assign age_o = age;
    assign valid_o = valid;
endmodule

module sched_select_wakeup (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        alloc,
    input  wire [31:0] alloc_deps,
    input  wire        iq_alloc,
    input  wire        iq_alloc_ready,
    input  wire [31:0] iq_alloc_tag,
    input  wire        iq_issue,
    input  wire [3:0]  iq_wake,
    output wire [31:0] issue_tag_o,
    output wire        issue_valid_o,
    output wire [31:0] issue_cnt_o,
    output wire [31:0] wk_valid_o,
    output wire [31:0] wk_pend_o,
    output wire [63:0] wk_occ_o,
    output wire        bc_v_o,
    output wire [4:0]  bc_idx_o,
    output wire [3:0]  seq_in_o,
    output wire [3:0]  seq_out_o
);
    wire [31:0] a_dep_or;
    wire [63:0] a_occ;
    wire [31:0] a_pend;
    wire [31:0] a_valid;
    wire [63:0] a_valid_cnt;

    wire [31:0] b_issue_tag;
    wire        b_issue_valid;
    wire [31:0] b_issue_cnt;
    wire [15:0] b_age;
    wire [3:0]  b_valid;

    // grant broadcast stage between select and wakeup
    reg       bc_v    = 1'b0;
    reg [4:0] bc_idx  = 5'd0;
    reg [3:0] seq_in  = 4'd0;
    reg [3:0] seq_out = 4'd0;

    initial bc_v    = 1'b0;
    initial bc_idx  = 5'd0;
    initial seq_in  = 4'd0;
    initial seq_out = 4'd0;

    age_matrix_iq u_sel (
        .clk(clk),
        .i_ce(en),
        .i_alloc(iq_alloc),
        .i_alloc_ready(iq_alloc_ready),
        .i_alloc_tag(iq_alloc_tag),
        .i_issue(iq_issue),
        .i_wake(iq_wake),
        .o_issue_tag(b_issue_tag),
        .o_issue_valid(b_issue_valid),
        .o_issue_cnt(b_issue_cnt),
        .age_o(b_age),
        .valid_o(b_valid)
    );

    always @(posedge clk) begin
        if (!rst_n) begin
            bc_v    <= 1'b0;
            bc_idx  <= 5'd0;
            seq_in  <= 4'd0;
            seq_out <= 4'd0;
        end else if (en) begin
            bc_v <= b_issue_valid;
            if (b_issue_valid) begin
                bc_idx <= b_issue_tag[4:0];
                seq_in <= seq_in + 4'd1;
            end
            if (bc_v)
                seq_out <= seq_out + 4'd1;
        end
    end

    pico_wakeup u_wake (
        .clk(clk),
        .rst_n(rst_n),
        .en(en),
        .alloc(alloc),
        .alloc_deps(alloc_deps),
        .issue(bc_v),
        .issue_idx(bc_idx),
        .dep_or_o(a_dep_or),
        .occ_o(a_occ),
        .pend_o(a_pend),
        .valid_o(a_valid),
        .valid_cnt_o(a_valid_cnt)
    );

    // at most one grant is ever staged ahead of the wakeup broadcast
    always @(posedge clk)
        assert ((seq_in - seq_out) <= 4'd1);

    assign issue_tag_o   = b_issue_tag;
    assign issue_valid_o = b_issue_valid;
    assign issue_cnt_o   = b_issue_cnt;
    assign wk_valid_o    = a_valid;
    assign wk_pend_o     = a_pend;
    assign wk_occ_o      = a_occ;
    assign bc_v_o        = bc_v;
    assign bc_idx_o      = bc_idx;
    assign seq_in_o      = seq_in;
    assign seq_out_o     = seq_out;
endmodule

module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
    output reg  [6:0]  rsp_rule
,
    output wire busy_o,
    output wire [6:0] idx_o,
    output wire [7:0] timer_o
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
    wire last = (idx == 7'd127);

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
                if (req) begin
                    busy  <= 1'b1;
                    idx   <= 7'd0;
                    timer <= 8'd128;
                    q_key <= req_key;
                    q_len <= {48'd0, req_len};
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
    assign busy_o = busy;
    assign idx_o = idx;
    assign timer_o = timer;
endmodule

module usb_route_lookup (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_pkt_valid,
    input wire [31:0] i_dest,
    input wire cfg_we,
    input wire [4:0] cfg_addr,
    input wire [31:0] cfg_data,
    output wire o_done,
    output wire [31:0] o_port
,
    output wire fin_q_o,
    output wire [1:0] phase_o,
    output wire [31:0] step_cnt_o
);
    localparam [1:0] P_IDLE = 2'd0, P_ARM = 2'd1, P_START = 2'd2, P_FIN = 2'd3;

    reg [1:0]  phase    = 2'd0;
    reg [31:0] step_cnt = 32'd0;
    reg        fin_q    = 1'b0;
    reg [31:0] dest_q   = 32'd0;
    reg [31:0] port_q   = 32'd0;

    reg [31:0] rt_mem [0:31];
    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1)
            rt_mem[i] = 32'd0;
    end

    // routing table configuration write port
    always @(posedge clk)
        if (!i_reset && i_ce && cfg_we)
            rt_mem[cfg_addr] <= cfg_data;

    // lookup sequencer: arm (capture dest) -> start (table read) -> finish (port valid)
    always @(posedge clk) begin
        if (i_reset) begin
            phase    <= P_IDLE;
            step_cnt <= 32'd0;
            fin_q    <= 1'b0;
            dest_q   <= 32'd0;
            port_q   <= 32'd0;
        end else if (i_ce) begin
            fin_q <= (step_cnt == 32'd2);
            case (phase)
                P_IDLE:  if (i_pkt_valid) begin
                             phase  <= P_ARM;
                             dest_q <= i_dest;
                         end
                P_ARM:   phase <= P_START;
                P_START: begin
                             phase  <= P_FIN;
                             port_q <= rt_mem[dest_q[4:0]];
                         end
                default: phase <= P_IDLE;
            endcase
            case (step_cnt)
                32'd0:   if (i_pkt_valid) step_cnt <= 32'd1;
                32'd3:   step_cnt <= 32'd0;
                default: step_cnt <= step_cnt + 32'd1;
            endcase
        end
    end

    assign o_done = fin_q;
    assign o_port = port_q;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && fin_q)
            assert (($past(phase) == P_START) || ($past(phase) == P_FIN));
    assign fin_q_o = fin_q;
    assign phase_o = phase;
    assign step_cnt_o = step_cnt;
endmodule

module flow_route_pipe (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_addr,
    input  wire [31:0] cfg_data,
    output wire        o_done,
    output wire [31:0] o_port,
    output wire [6:0]  o_rule,
    output wire        o_miss,
    output wire        o_stall,
    output wire        pend_v_o,
    output wire        fly_v_o
);
    // flow table side
    wire        a_rsp_valid;
    wire        a_rsp_hit;
    wire [31:0] a_rsp_action;
    wire [6:0]  a_rsp_rule;
    wire        a_busy;
    wire [6:0]  a_idx;
    wire [7:0]  a_timer;

    // route lookup side
    wire        b_done;
    wire [31:0] b_port;
    wire        b_fin_q;
    wire [1:0]  b_phase;
    wire [31:0] b_step_cnt;

    // forwarding register between classifier and router
    reg        pend_v;
    reg [31:0] pend_dest;
    reg [6:0]  pend_rule;
    // rule tag for the packet currently inside the route lookup
    reg        fly_v;
    reg [6:0]  fly_rule;

    initial begin
        pend_v    = 1'b0;
        pend_dest = 32'd0;
        pend_rule = 7'd0;
        fly_v     = 1'b0;
        fly_rule  = 7'd0;
    end

    // classifier only advances while the forwarding slot is free
    wire a_ce   = i_ce && !pend_v;
    // matched response accepted into the forwarding slot
    wire a_fwd  = !pend_v && a_rsp_valid && a_rsp_hit;
    // route lookup takes the slot when idle
    wire b_take = pend_v && (b_phase == 2'd0);

    flow_match_table u_fmt (
        .clk(clk),
        .rst(rst),
        .i_ce(a_ce),
        .req(req),
        .req_key(req_key),
        .req_len(req_len),
        .wr_en(wr_en),
        .wr_idx(wr_idx),
        .wr_key(wr_key),
        .wr_action(wr_action),
        .rsp_valid(a_rsp_valid),
        .rsp_hit(a_rsp_hit),
        .rsp_action(a_rsp_action),
        .rsp_rule(a_rsp_rule),
        .busy_o(a_busy),
        .idx_o(a_idx),
        .timer_o(a_timer)
    );

    usb_route_lookup u_rt (
        .clk(clk),
        .i_reset(rst),
        .i_ce(i_ce),
        .i_pkt_valid(pend_v),
        .i_dest(pend_dest),
        .cfg_we(cfg_we),
        .cfg_addr(cfg_addr),
        .cfg_data(cfg_data),
        .o_done(b_done),
        .o_port(b_port),
        .fin_q_o(b_fin_q),
        .phase_o(b_phase),
        .step_cnt_o(b_step_cnt)
    );

    always @(posedge clk) begin
        if (rst) begin
            pend_v    <= 1'b0;
            pend_dest <= 32'd0;
            pend_rule <= 7'd0;
            fly_v     <= 1'b0;
            fly_rule  <= 7'd0;
        end else if (i_ce) begin
            if (b_take) begin
                pend_v   <= 1'b0;
                fly_v    <= 1'b1;
                fly_rule <= pend_rule;
            end else if (a_fwd) begin
                pend_v    <= 1'b1;
                pend_dest <= a_rsp_action;
                pend_rule <= a_rsp_rule;
            end
            if (b_done)
                fly_v <= 1'b0;
        end
    end

    assign o_done   = b_done;
    assign o_port   = b_port;
    assign o_rule   = fly_rule;
    assign o_miss   = a_rsp_valid && !a_rsp_hit;
    assign o_stall  = pend_v;
    assign pend_v_o = pend_v;
    assign fly_v_o  = fly_v;

    // every routed result must belong to a tagged, forwarded packet
    always @(posedge clk)
        if (b_done)
            assert (fly_v);
endmodule

module neo_ringstop (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        ring_in_vld,
    input  wire [63:0] ring_in_data,
    input  wire [3:0]  ring_in_dst,
    input  wire        push,
    input  wire [63:0] push_data,
    input  wire [3:0]  my_id,
    output wire        ring_hold,
    output wire        eject_vld,
    output wire [63:0] eject_data,
    output wire        out_vld,
    output wire [63:0] out_data,
   output wire [3:0]  out_dst,
   output wire [4:0]  pool_credits,
   output wire [2:0]  rsp_level,
   output wire        rsp_drop
);
    reg        slot_vld = 1'b0;
    reg [63:0] slot_data = 64'd0;
    reg [3:0]  slot_dst = 4'd0;
    reg [63:0] fifo [0:15];
    reg [4:0]  q_head = 5'd0;
    reg [4:0]  q_tail = 5'd0;
    reg [4:0]  q_count = 5'd0;
    reg [63:0] starve_cnt = 64'd0;
    reg        rsv = 1'b0;
    reg [63:0] inj_total = 64'd0;
    reg        pre_rsv = 1'b1;
    reg        pv = 1'b0;

   localparam CHANNELS  = 2;
   localparam RSP_DEPTH = 4;
   localparam [4:0] POOL = 5'd16;

   reg [63:0] rsp_q [0:RSP_DEPTH-1];
   reg [1:0]  r_head = 2'd0;
   reg [1:0]  r_tail = 2'd0;
   reg [2:0]  r_count = 3'd0;
   reg [4:0]  pool_free = POOL;
   reg        rr_last = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) fifo[i] = 64'd0;
       for (i = 0; i < RSP_DEPTH; i = i + 1) rsp_q[i] = 64'd0;
    end

    wire through   = ring_in_vld && (ring_in_dst != my_id);
    wire nonempty  = (q_head != q_tail);
    wire free_slot = (!through) || rsv;
   wire rsp_req   = eject_vld && ring_in_data[63];
   wire [63:0] rsp_word = {1'b0, ring_in_data[62:8], my_id, ring_in_data[7:4]};
   wire r_take    = rsp_req && (r_count < RSP_DEPTH) && (pool_free != 5'd0);
   wire [CHANNELS-1:0] req = {(r_count != 3'd0), nonempty} & {CHANNELS{free_slot}};
   wire gnt_rsp   = req[1] && (!req[0] || (!rr_last && !rsv));
   wire pop       = req[0] && !gnt_rsp;
   wire push_ok   = push && (pool_free > {4'd0, r_take});
    wire dec       = pop && (q_count != 5'd0);

    assign ring_hold  = rsv && through;
    assign eject_vld  = ring_in_vld && (ring_in_dst == my_id);
    assign eject_data = ring_in_data;
    assign out_vld    = slot_vld;
    assign out_data   = slot_data;
    assign out_dst    = slot_dst;
   assign pool_credits = pool_free;
   assign rsp_level    = r_count;
   assign rsp_drop     = rsp_req && !r_take;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            slot_vld   <= 1'b0;
            slot_data  <= 64'd0;
            slot_dst   <= 4'd0;
            q_head     <= 5'd0;
            q_tail     <= 5'd0;
            q_count    <= 5'd0;
            starve_cnt <= 64'd0;
            rsv        <= 1'b0;
            inj_total  <= 64'd0;
            pre_rsv    <= 1'b1;
           r_head     <= 2'd0;
           r_tail     <= 2'd0;
           r_count    <= 3'd0;
           pool_free  <= POOL;
           rr_last    <= 1'b0;
        end else if (en) begin
            if (pop) begin
                slot_vld  <= 1'b1;
                slot_data <= fifo[q_head[3:0]];
                slot_dst  <= fifo[q_head[3:0]][3:0];
                q_head    <= q_head + 5'd1;
                inj_total <= inj_total + 64'd1;
               rr_last   <= 1'b0;
           end else if (gnt_rsp) begin
               slot_vld  <= 1'b1;
               slot_data <= rsp_q[r_head];
               slot_dst  <= rsp_q[r_head][3:0];
               r_head    <= r_head + 2'd1;
               rr_last   <= 1'b1;
           end else if (through) begin
                slot_vld  <= 1'b1;
                slot_data <= ring_in_data;
                slot_dst  <= ring_in_dst;
            end else begin
                slot_vld  <= 1'b0;
            end

            if (push_ok) begin
                fifo[q_tail[3:0]] <= push_data;
                q_tail <= q_tail + 5'd1;
            end

            q_count <= q_count + {4'd0, push_ok} - {4'd0, dec};

           if (r_take) begin
               rsp_q[r_tail] <= rsp_word;
               r_tail        <= r_tail + 2'd1;
           end

           r_count   <= r_count + {2'd0, r_take} - {2'd0, gnt_rsp};
           pool_free <= pool_free + {4'd0, dec} + {4'd0, gnt_rsp}
                                  - {4'd0, push_ok} - {4'd0, r_take};

            if (pop)
                starve_cnt <= 64'd0;
            else if (nonempty)
                starve_cnt <= starve_cnt + 64'd1;

            if (pop)
                rsv <= 1'b0;
            else if (starve_cnt == 64'd1000) begin
                rsv     <= 1'b1;
                pre_rsv <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (pv && !$past(rst) && pre_rsv && $stable(q_tail) && $stable(q_count))
            assert ($stable(q_head));

   always @(posedge clk)
       if (pv)
           assert (pool_free <= POOL);
endmodule

module lin_master_tx (
    input wire clk,
    input wire rst,
    input wire i_tick,
    input wire i_start,
    input wire i_abort,
    input wire i_enhanced,
    input wire [5:0] i_id,
    input wire [3:0] i_len,
    input wire i_wr_en,
    input wire [3:0] i_wr_addr,
    input wire [31:0] i_wr_data,
    output wire o_busy,
    output wire o_bus_low,
output wire [31:0] o_tx_byte,
output wire o_diag_busy,
output wire o_diag_bus_low,
output wire [31:0] o_diag_tx_byte
);
    // one-hot frame phase: 0 IDLE, 1 BREAK, 2 SYNC, 3 PID, 4 DATA, 5 CSUM
    reg [5:0] phase;
    initial phase = 6'b000001;
    reg [31:0] brk_cnt = 32'd0;
    reg [31:0] byte_idx = 32'd0;
    reg [31:0] bytes_left = 32'd0;
    reg [31:0] frame_len = 32'd1;
    reg [31:0] csum = 32'd0;
    reg [31:0] tx_byte = 32'd0;
    reg [7:0] pid_reg = 8'd0;
    reg [31:0] data_buf [0:15];
    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) data_buf[i] = 32'd0;
    end
    reg armed = 1'b1;
    reg pv = 1'b0;
   // second (diagnostic) bus: frame IDs 0x3C-0x3F, classic checksum, shares the data_buf read port
   localparam CHANNELS = 2;
   localparam [2:0] L1_IDLE = 3'd0, L1_BRK = 3'd1, L1_SYNC = 3'd2, L1_PID = 3'd3, L1_DATA = 3'd4, L1_CSUM = 3'd5;
   reg [2:0] l1_st = 3'd0;
   reg [3:0] l1_brk = 4'd0;
   reg [4:0] l1_idx = 5'd0;
   reg [4:0] l1_len = 5'd1;
   reg [31:0] l1_csum = 32'd0;
   reg [31:0] l1_tx = 32'd0;
   reg [7:0] l1_pid = 8'd0;
   reg rd_busy = 1'b0;
   reg rd_owner = 1'b0;
   wire diag_id = (i_id[5:2] == 4'b1111);
   wire [CHANNELS-1:0] rd_req = {(l1_st == L1_PID), phase[3]};
   wire gnt_sel = (&rd_req) ? !rd_owner : rd_req[1];
   wire gnt_any = i_tick && !rd_busy && (|rd_req);
   wire gnt0 = gnt_any && !gnt_sel;
   wire gnt1 = gnt_any && gnt_sel;
   wire rel0 = i_tick && phase[4] && (byte_idx == frame_len - 32'd1);
   wire rel1 = i_tick && (l1_st == L1_DATA) && (l1_idx == l1_len - 5'd1);
   wire [3:0] rd_addr = rd_owner ? l1_idx[3:0] : byte_idx[3:0];
   wire [7:0] csum_acc = rd_owner ? l1_csum[7:0] : csum[7:0];

   wire [7:0] cur_byte = data_buf[rd_addr][7:0];
   wire [8:0] csum_sum = {1'b0, csum_acc} + {1'b0, cur_byte};
    wire [7:0] csum_next = csum_sum[8] ? (csum_sum[7:0] + 8'd1) : csum_sum[7:0];
    wire p0 = i_id[0] ^ i_id[1] ^ i_id[2] ^ i_id[4];
    wire p1 = ~(i_id[1] ^ i_id[3] ^ i_id[4] ^ i_id[5]);
    wire [7:0] pid_calc = {p1, p0, i_id};

    always @(posedge clk) begin
        pv <= 1'b1;
        if (i_abort) armed <= 1'b0;
    end

    always @(posedge clk) begin
        if (i_wr_en) data_buf[i_wr_addr] <= i_wr_data;
    end

    always @(posedge clk) begin
        if (rst || i_abort) begin
            phase <= 6'b000001;
            brk_cnt <= 32'd0;
            byte_idx <= 32'd0;
            bytes_left <= 32'd0;
        end else if (i_tick) begin
           if (phase[0] && i_start && !diag_id) begin
                phase[0] <= 1'b0;
                phase[1] <= 1'b1;
                brk_cnt <= 32'd0;
                frame_len <= {28'd0, i_len} + 32'd1;
                pid_reg <= pid_calc;
                csum <= i_enhanced ? {24'd0, pid_calc} : 32'd0;
            end
            if (phase[1]) begin
                if (brk_cnt == 32'd12) begin
                    phase[1] <= 1'b0;
                    phase[2] <= 1'b1;
                end
                brk_cnt <= brk_cnt + 32'd1;
            end
            if (phase[2]) begin
                tx_byte <= 32'h00000055;
                phase[2] <= 1'b0;
                phase[3] <= 1'b1;
            end
            if (phase[3]) begin
                tx_byte <= {24'd0, pid_reg};
                byte_idx <= 32'd0;
                bytes_left <= frame_len;
               if (gnt0) begin
                   phase[3] <= 1'b0;
                   phase[4] <= 1'b1;
               end
            end
            if (phase[4]) begin
                tx_byte <= {24'd0, cur_byte};
                csum <= {24'd0, csum_next};
                byte_idx <= byte_idx + 32'd1;
                bytes_left <= bytes_left - 32'd1;
                if (byte_idx == frame_len - 32'd1) phase[4] <= 1'b0;
                if (bytes_left == 32'd1) phase[5] <= 1'b1;
            end
            if (phase[5]) begin
                tx_byte <= {24'd0, ~csum[7:0]};
                phase[5] <= 1'b0;
                phase[0] <= 1'b1;
            end
        end
    end

    assign o_busy = !phase[0];
    assign o_bus_low = phase[1];
    assign o_tx_byte = tx_byte;
   assign o_diag_busy = (l1_st != L1_IDLE);
   assign o_diag_bus_low = (l1_st == L1_BRK);
   assign o_diag_tx_byte = l1_tx;

   always @(posedge clk) begin
       if (rst || i_abort) begin
           l1_st <= L1_IDLE;
           l1_brk <= 4'd0;
           l1_idx <= 5'd0;
       end else if (i_tick) begin
           case (l1_st)
               L1_IDLE: if (i_start && diag_id) begin
                   l1_st <= L1_BRK;
                   l1_brk <= 4'd0;
                   l1_len <= {1'b0, i_len} + 5'd1;
                   l1_pid <= pid_calc;
                   l1_csum <= 32'd0;
               end
               L1_BRK: begin
                   l1_brk <= (l1_brk == 4'd12) ? 4'd0 : l1_brk + 4'd1;
                   if (l1_brk == 4'd12) l1_st <= L1_SYNC;
               end
               L1_SYNC: begin
                   l1_tx <= 32'h00000055;
                   l1_st <= L1_PID;
               end
               L1_PID: begin
                   l1_tx <= {24'd0, l1_pid};
                   l1_idx <= 5'd0;
                   if (gnt1) l1_st <= L1_DATA;
               end
               L1_DATA: begin
                   l1_tx <= {24'd0, cur_byte};
                   l1_csum <= {24'd0, csum_next};
                   l1_idx <= l1_idx + 5'd1;
                   if (l1_idx == l1_len - 5'd1) l1_st <= L1_CSUM;
               end
               L1_CSUM: begin
                   l1_tx <= {24'd0, ~l1_csum[7:0]};
                   l1_st <= L1_IDLE;
               end
               default: l1_st <= L1_IDLE;
           endcase
       end
   end

   // read-port lock: taken on the PID->DATA grant, dropped on the last data byte
   always @(posedge clk) begin
       if (rst || i_abort) begin
           rd_busy <= 1'b0;
           rd_owner <= 1'b0;
       end else if (gnt_any) begin
           rd_busy <= 1'b1;
           rd_owner <= gnt_sel;
       end else if (rel0 || rel1) begin
           rd_busy <= 1'b0;
       end
   end

    // Absence, before first abort: checksum phase never begins while data phase is still active
    always @(posedge clk)
        if (pv && armed && $rose(phase[5]))
            assert (!phase[4]);

   // Shared buffer port: the LIN bus and the diagnostic bus never stream data bytes in the same cycle
   always @(posedge clk)
       if (pv)
           assert (!(phase[4] && (l1_st == L1_DATA)));
endmodule

module prbs_win_log #(
   parameter DEPTH = 4,
   parameter AW    = 2
) (
   input  wire        clk,
   input  wire        i_reset,
   input  wire        i_ce,
   input  wire        i_close,
   input  wire [63:0] i_tally,
   input  wire [63:0] i_end,
   output wire [AW:0] o_fill,
   output wire [63:0] o_last_tally,
   output wire [63:0] o_last_end,
   output wire [63:0] o_worst,
   output wire [7:0]  o_clean,
   output wire        o_wrap,
   output wire        o_rising
);
   reg [63:0]   tally [0:DEPTH-1];
   reg [63:0]   ends  [0:DEPTH-1];
   reg [AW-1:0] wr_ptr;
   reg [AW:0]   fill;
   reg [63:0]   worst;
   reg [7:0]    clean;
   reg          wrap;
   integer i;

   initial begin
       for (i = 0; i < DEPTH; i = i + 1) begin
           tally[i] = 64'd0;
           ends[i]  = 64'd0;
       end
   end
   initial wr_ptr = {AW{1'b0}};
   initial fill   = {(AW+1){1'b0}};
   initial worst  = 64'd0;
   initial clean  = 8'd0;
   initial wrap   = 1'b0;

   wire [AW-1:0] last_idx = wr_ptr - 1'b1;
   wire [AW-1:0] prev_idx = wr_ptr - 2'd2;
   wire          full     = (fill == DEPTH);
   wire          push     = i_ce && i_close;

   always @(posedge clk) begin
       if (i_reset) begin
           for (i = 0; i < DEPTH; i = i + 1) begin
               tally[i] <= 64'd0;
               ends[i]  <= 64'd0;
           end
           wr_ptr <= {AW{1'b0}};
           fill   <= {(AW+1){1'b0}};
           worst  <= 64'd0;
           clean  <= 8'd0;
           wrap   <= 1'b0;
       end else if (push) begin
           // record the closing window and advance the ring
           tally[wr_ptr] <= i_tally;
           ends[wr_ptr]  <= i_end;
           wr_ptr        <= wr_ptr + 1'b1;
           if (full)
               wrap <= 1'b1;
           else
               fill <= fill + 1'b1;
           if (i_tally > worst)
               worst <= i_tally;
           if ((i_tally == 64'd0) && (clean != 8'hFF))
               clean <= clean + 8'd1;
       end
   end

   assign o_fill       = fill;
   assign o_last_tally = tally[last_idx];
   assign o_last_end   = ends[last_idx];
   assign o_worst      = worst;
   assign o_clean      = clean;
   assign o_wrap       = wrap;
   assign o_rising     = (fill >= 2) && (tally[last_idx] > tally[prev_idx]);
endmodule

module prbs_win_checker (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_bit,
    input  wire        i_arm,
    input  wire        i_disarm,
    output wire        o_sync,
   output wire [63:0] o_errs,
   output wire [2:0]  o_log_fill,
   output wire [63:0] o_log_last,
   output wire [63:0] o_log_last_end,
   output wire [63:0] o_log_worst,
   output wire [7:0]  o_log_clean,
   output wire        o_log_wrap,
  output wire        o_log_rising,
  output wire [15:0] o_st_acq,
  output wire [15:0] o_st_loss,
  output wire [15:0] o_st_wins,
  output wire [15:0] o_st_flap,
  output wire [31:0] o_st_sync_bits,
  output wire [7:0]  o_st_burst_max,
  output wire [15:0] o_st_epoch_last,
  output wire [15:0] o_st_epoch_peak,
  output wire        o_st_wdog_trip
);
    localparam [63:0] SYNC_LEN = 64'd8;
    localparam [63:0] LOSS_LEN = 64'd4;
    localparam [63:0] MAXV     = 64'hFFFFFFFFFFFFFFFF;
   localparam LOG_DEPTH = 4;
   localparam LOG_AW    = 2;

    reg [63:0] ref_sr;
    reg        sync;
    reg [63:0] match_run;
    reg [63:0] bad_run;
    reg [63:0] err_cnt;
    reg        win;
    reg [63:0] err_snap;
    reg [63:0] win_errs;

    initial ref_sr    = 64'h1;
    initial sync      = 1'b0;
    initial match_run = 64'd0;
    initial bad_run   = 64'd0;
    initial err_cnt   = 64'd0;
    initial win       = 1'b0;
    initial err_snap  = 64'd0;
    initial win_errs  = 64'd0;

    // PRBS x^64 + x^63 + x^61 + x^60 + 1 prediction
    wire        pred    = ref_sr[63] ^ ref_sr[62] ^ ref_sr[60] ^ ref_sr[59];
    wire        mism    = sync && (i_bit != pred);
    wire        cnt_inc = mism && (err_cnt != MAXV);
    wire [63:0] err_nxt = cnt_inc ? (err_cnt + 64'd1) : err_cnt;
    wire        lose    = mism && ((bad_run + 64'd1) >= LOSS_LEN);
    wire        open_w  = i_arm && sync && !lose && !i_disarm;
    wire        close_w = i_disarm || lose;

   // window history log: one entry per closed window
   wire              log_close = win && close_w;
   wire [63:0]       win_fin   = cnt_inc ? (win_errs + 64'd1) : win_errs;
   wire [LOG_AW:0]   log_fill;
   wire [63:0]       log_last_tally;
   wire [63:0]       log_last_end;
   wire [63:0]       log_worst;
   wire [7:0]        log_clean;
   wire              log_wrap;
   wire              log_rising;

   prbs_win_log #(.DEPTH(LOG_DEPTH), .AW(LOG_AW)) u_log (
       .clk          (clk),
       .i_reset      (i_reset),
       .i_ce         (i_ce),
       .i_close      (log_close),
       .i_tally      (win_fin),
       .i_end        (err_nxt),
       .o_fill       (log_fill),
       .o_last_tally (log_last_tally),
       .o_last_end   (log_last_end),
       .o_worst      (log_worst),
       .o_clean      (log_clean),
       .o_wrap       (log_wrap),
       .o_rising     (log_rising)
   );

    always @(posedge clk) begin
        if (i_reset) begin
            ref_sr    <= 64'h1;
            sync      <= 1'b0;
            match_run <= 64'd0;
            bad_run   <= 64'd0;
            err_cnt   <= 64'd0;
            win       <= 1'b0;
            err_snap  <= 64'd0;
            win_errs  <= 64'd0;
        end else if (i_ce) begin
            err_cnt <= err_nxt;
            if (!sync) begin
                // self-synchronising: load incoming stream into reference
                ref_sr  <= {ref_sr[62:0], i_bit};
                bad_run <= 64'd0;
                if (i_bit == pred) begin
                    if ((match_run + 64'd1) >= SYNC_LEN) begin
                        sync      <= 1'b1;
                        match_run <= 64'd0;
                    end else begin
                        match_run <= match_run + 64'd1;
                    end
                end else begin
                    match_run <= 64'd0;
                end
            end else begin
                // locked: free-run the local reference
                ref_sr    <= {ref_sr[62:0], pred};
                match_run <= 64'd0;
                if (mism) begin
                    if (lose) begin
                        sync    <= 1'b0;
                        bad_run <= 64'd0;
                    end else begin
                        bad_run <= bad_run + 64'd1;
                    end
                end else begin
                    bad_run <= 64'd0;
                end
            end
            // measurement window: opened by arm while locked, closed by disarm or sync loss
            if (win) begin
                if (close_w) win <= 1'b0;
                if (cnt_inc) win_errs <= win_errs + 64'd1;
            end else if (open_w) begin
                win      <= 1'b1;
                err_snap <= err_nxt;
                win_errs <= 64'd0;
            end
        end
    end

    assign o_sync = sync;
    assign o_errs = err_cnt;
   assign o_log_fill     = log_fill;
   assign o_log_last     = log_last_tally;
   assign o_log_last_end = log_last_end;
   assign o_log_worst    = log_worst;
   assign o_log_clean    = log_clean;
   assign o_log_wrap     = log_wrap;
   assign o_log_rising   = log_rising;

  // ------------------------------------------------------------------
  // Link statistics / debug bank (observability only)
  // ------------------------------------------------------------------
  localparam [31:0] ST_WDOG_LIM = 32'd1024;
  localparam [9:0]  ST_EPOCH_END = 10'd1023;
  localparam [15:0] ST_FLAP_LIM = 16'd64;

  reg [15:0] st_acq;
  reg [15:0] st_loss;
  reg [15:0] st_wins;
  reg [15:0] st_flap;
  reg [15:0] st_since_acq;
  reg [31:0] st_sync_bits;
  reg [7:0]  st_burst_cur;
  reg [7:0]  st_burst_max;
  reg [9:0]  st_epoch_pos;
  reg [15:0] st_epoch_errs;
  reg [15:0] st_epoch_last;
  reg [15:0] st_epoch_peak;
  reg [31:0] st_wdog;
  reg        st_wdog_trip;

  initial st_acq        = 16'd0;
  initial st_loss       = 16'd0;
  initial st_wins       = 16'd0;
  initial st_flap       = 16'd0;
  initial st_since_acq  = 16'd0;
  initial st_sync_bits  = 32'd0;
  initial st_burst_cur  = 8'd0;
  initial st_burst_max  = 8'd0;
  initial st_epoch_pos  = 10'd0;
  initial st_epoch_errs = 16'd0;
  initial st_epoch_last = 16'd0;
  initial st_epoch_peak = 16'd0;
  initial st_wdog       = 32'd0;
  initial st_wdog_trip  = 1'b0;

  wire        st_acq_ev    = !sync && (i_bit == pred) && ((match_run + 64'd1) >= SYNC_LEN);
  wire        st_loss_ev   = sync && lose;
  wire        st_open_ev   = !win && open_w;
  wire [15:0] st_epoch_tot = st_epoch_errs + (mism ? 16'd1 : 16'd0);
  wire [7:0]  st_burst_nxt = (st_burst_cur != 8'hFF) ? (st_burst_cur + 8'd1) : st_burst_cur;

  always @(posedge clk) begin
      if (i_reset) begin
          st_acq        <= 16'd0;
          st_loss       <= 16'd0;
          st_wins       <= 16'd0;
          st_flap       <= 16'd0;
          st_since_acq  <= 16'd0;
          st_sync_bits  <= 32'd0;
          st_burst_cur  <= 8'd0;
          st_burst_max  <= 8'd0;
          st_epoch_pos  <= 10'd0;
          st_epoch_errs <= 16'd0;
          st_epoch_last <= 16'd0;
          st_epoch_peak <= 16'd0;
          st_wdog       <= 32'd0;
          st_wdog_trip  <= 1'b0;
      end else begin
          // watchdog: cycles elapsed without a clock enable
          if (i_ce)
              st_wdog <= 32'd0;
          else if (st_wdog != 32'hFFFFFFFF)
              st_wdog <= st_wdog + 32'd1;
          if (!i_ce && (st_wdog >= ST_WDOG_LIM))
              st_wdog_trip <= 1'b1;
          if (i_ce) begin
              if (st_acq_ev && (st_acq != 16'hFFFF))
                  st_acq <= st_acq + 16'd1;
              if (st_loss_ev && (st_loss != 16'hFFFF))
                  st_loss <= st_loss + 16'd1;
              if (st_open_ev && (st_wins != 16'hFFFF))
                  st_wins <= st_wins + 16'd1;
              // flap detection: losses shortly after an acquisition
              if (st_acq_ev)
                  st_since_acq <= 16'd0;
              else if (sync && (st_since_acq != 16'hFFFF))
                  st_since_acq <= st_since_acq + 16'd1;
              if (st_loss_ev && (st_since_acq < ST_FLAP_LIM) && (st_flap != 16'hFFFF))
                  st_flap <= st_flap + 16'd1;
              if (sync && (st_sync_bits != 32'hFFFFFFFF))
                  st_sync_bits <= st_sync_bits + 32'd1;
              // longest run of consecutive mismatches
              if (mism) begin
                  st_burst_cur <= st_burst_nxt;
                  if (st_burst_nxt > st_burst_max)
                      st_burst_max <= st_burst_nxt;
              end else begin
                  st_burst_cur <= 8'd0;
              end
              // per-epoch error totals while locked
              if (sync) begin
                  if (st_epoch_pos == ST_EPOCH_END) begin
                      st_epoch_pos  <= 10'd0;
                      st_epoch_errs <= 16'd0;
                      st_epoch_last <= st_epoch_tot;
                      if (st_epoch_tot > st_epoch_peak)
                          st_epoch_peak <= st_epoch_tot;
                  end else begin
                      st_epoch_pos  <= st_epoch_pos + 10'd1;
                      st_epoch_errs <= st_epoch_tot;
                  end
              end
          end
      end
  end

  assign o_st_acq        = st_acq;
  assign o_st_loss       = st_loss;
  assign o_st_wins       = st_wins;
  assign o_st_flap       = st_flap;
  assign o_st_sync_bits  = st_sync_bits;
  assign o_st_burst_max  = st_burst_max;
  assign o_st_epoch_last = st_epoch_last;
  assign o_st_epoch_peak = st_epoch_peak;
  assign o_st_wdog_trip  = st_wdog_trip;

    // Precedence inside the window: a nonzero window tally requires the global
    // counter to have advanced past the snapshot recorded when the window opened.
    always @(*)
        if (win && (win_errs != 64'd0))
            assert (err_cnt != err_snap);

    // With no window errors, the global counter must still equal the snapshot.
    always @(*)
        if (win && (win_errs == 64'd0))
            assert (err_cnt == err_snap);

   // Windows are ordered: the last logged window ended no later than the
   // point where the currently open window started.
   always @(*)
       if (win && (log_fill != 3'd0))
           assert (log_last_end <= err_snap);
endmodule

module neo_ringstop (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        ring_in_vld,
    input  wire [63:0] ring_in_data,
    input  wire [3:0]  ring_in_dst,
    input  wire        push,
    input  wire [63:0] push_data,
    input  wire [3:0]  my_id,
    output wire        ring_hold,
    output wire        eject_vld,
    output wire [63:0] eject_data,
    output wire        out_vld,
    output wire [63:0] out_data,
    output wire [3:0]  out_dst
,
    output wire [4:0] q_count_o,
    output wire [4:0] q_head_o,
    output wire [4:0] q_tail_o
);
    reg        slot_vld = 1'b0;
    reg [63:0] slot_data = 64'd0;
    reg [3:0]  slot_dst = 4'd0;
    reg [63:0] fifo [0:15];
    reg [4:0]  q_head = 5'd0;
    reg [4:0]  q_tail = 5'd0;
    reg [4:0]  q_count = 5'd0;
    reg [63:0] starve_cnt = 64'd0;
    reg        rsv = 1'b0;
    reg [63:0] inj_total = 64'd0;
    reg        pre_rsv = 1'b1;
    reg        pv = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) fifo[i] = 64'd0;
    end

    wire through   = ring_in_vld && (ring_in_dst != my_id);
    wire nonempty  = (q_head != q_tail);
    wire free_slot = (!through) || rsv;
    wire pop       = nonempty && free_slot;
    wire push_ok   = push && (q_count < 5'd16);
    wire dec       = pop && (q_count != 5'd0);

    assign ring_hold  = rsv && through;
    assign eject_vld  = ring_in_vld && (ring_in_dst == my_id);
    assign eject_data = ring_in_data;
    assign out_vld    = slot_vld;
    assign out_data   = slot_data;
    assign out_dst    = slot_dst;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            slot_vld   <= 1'b0;
            slot_data  <= 64'd0;
            slot_dst   <= 4'd0;
            q_head     <= 5'd0;
            q_tail     <= 5'd0;
            q_count    <= 5'd0;
            starve_cnt <= 64'd0;
            rsv        <= 1'b0;
            inj_total  <= 64'd0;
            pre_rsv    <= 1'b1;
        end else if (en) begin
            if (pop) begin
                slot_vld  <= 1'b1;
                slot_data <= fifo[q_head[3:0]];
                slot_dst  <= fifo[q_head[3:0]][3:0];
                q_head    <= q_head + 5'd1;
                inj_total <= inj_total + 64'd1;
            end else if (through) begin
                slot_vld  <= 1'b1;
                slot_data <= ring_in_data;
                slot_dst  <= ring_in_dst;
            end else begin
                slot_vld  <= 1'b0;
            end

            if (push_ok) begin
                fifo[q_tail[3:0]] <= push_data;
                q_tail <= q_tail + 5'd1;
            end

            q_count <= q_count + {4'd0, push_ok} - {4'd0, dec};

            if (pop)
                starve_cnt <= 64'd0;
            else if (nonempty)
                starve_cnt <= starve_cnt + 64'd1;

            if (pop)
                rsv <= 1'b0;
            else if (starve_cnt == 64'd1000) begin
                rsv     <= 1'b1;
                pre_rsv <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (pv && !$past(rst) && pre_rsv && $stable(q_tail) && $stable(q_count))
            assert ($stable(q_head));
    assign q_count_o = q_count;
    assign q_head_o = q_head;
    assign q_tail_o = q_tail;
endmodule

module pretrig_capture (
    input  wire        clk,
    input  wire        ce,
    input  wire        rearm,
    input  wire        trig,
    input  wire [63:0] sample,
    input  wire [5:0]  rd_idx,
    output wire [63:0] rd_data,
    output wire        is_frozen,
    output wire [63:0] captured
,
    output wire [63:0] count_o,
    output wire frozen_o,
    output wire [47:0] valid_o
);
    localparam [63:0] DEPTH = 64'd48;
    reg [63:0] chain [0:47];
    reg [47:0] valid;
    reg [63:0] count;
    reg        frozen;
    reg        pv;
    integer i;

    initial begin
        for (i = 0; i < 48; i = i + 1) chain[i] = 64'd0;
        valid  = 48'd0;
        count  = 64'd0;
        frozen = 1'b0;
        pv     = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rearm) begin
            frozen <= 1'b0;
            count  <= 64'd0;
            valid  <= 48'd0;
        end else if (ce && !frozen) begin
            if (trig && count == DEPTH) begin
                frozen <= 1'b1;
            end else begin
                chain[0] <= sample;
                for (i = 1; i < 48; i = i + 1) chain[i] <= chain[i-1];
                valid <= {valid[46:0], 1'b1};
                if (count != DEPTH) count <= count + 64'd1;
            end
        end
    end

    assign rd_data   = (rd_idx < 6'd48) ? chain[rd_idx] : 64'd0;
    assign is_frozen = frozen;
    assign captured  = count;

    always @(posedge clk)
        if (pv && $rose(frozen))
            assert (valid == 48'hFFFFFFFFFFFF);
    assign count_o = count;
    assign frozen_o = frozen;
    assign valid_o = valid;
endmodule

module ringstop_trace (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        ring_in_vld,
    input  wire [63:0] ring_in_data,
    input  wire [3:0]  ring_in_dst,
    input  wire        push,
    input  wire [63:0] push_data,
    input  wire [3:0]  my_id,
    input  wire        trig,
    input  wire        rearm,
    input  wire [5:0]  rd_idx,
    output wire        ring_hold,
    output wire        out_vld,
    output wire [63:0] out_data,
    output wire [3:0]  out_dst,
    output wire        eject_vld,
    output wire [63:0] eject_data,
    output wire [63:0] rd_data,
    output wire        is_frozen,
    output wire [63:0] captured,
    output wire        trace_vld,
    output wire [63:0] trace_data,
    output wire [5:0]  trace_offered_o,
   output wire [5:0]  trace_missed,
   output wire        push_ready,
   output wire [3:0]  stg_level_o,
   output wire [3:0]  stg_hwm_o,
   output wire [15:0] push_stalls,
   output wire [1:0]  inj_tokens_o,
   output wire        inj_busy,
   output wire        lb_busy,
   output wire        inj_fault
);
    wire [4:0]  a_q_count;
    wire [4:0]  a_q_head;
    wire [4:0]  a_q_tail;
    wire [63:0] b_count;
    wire        b_frozen;
    wire [47:0] b_valid;

    reg        g_vld = 1'b0;
    reg [63:0] g_data = 64'd0;
    reg [5:0]  trace_offered = 6'd0;
   localparam integer STG_DEPTH = 8;
   localparam integer STG_AW    = 3;
   localparam [4:0]   RING_CAP  = 5'd16;
   localparam [1:0]   INJ_BURST = 2'd3;
   reg [63:0]     stg_mem [0:STG_DEPTH-1];
   reg [7:0]      stg_par [0:STG_DEPTH-1];
   reg [STG_AW:0] stg_wp    = 4'd0;
   reg [STG_AW:0] stg_rp    = 4'd0;
   reg            inj_vld   = 1'b0;
   reg [63:0]     inj_data  = 64'd0;
   reg [7:0]      inj_par   = 8'd0;
   reg            lb_vld    = 1'b0;
   reg [63:0]     lb_data   = 64'd0;
   reg [7:0]      lb_par    = 8'd0;
   reg [1:0]      inj_tok   = 2'd3;
   reg [15:0]     stall_cnt = 16'd0;
   reg [3:0]      stg_hwm   = 4'd0;
   integer        s;
   integer        b;
   initial begin
       for (s = 0; s < STG_DEPTH; s = s + 1) begin
           stg_mem[s] = 64'd0;
           stg_par[s] = 8'd0;
       end
   end

    neo_ringstop u_ring (
        .clk(clk),
        .rst(rst),
        .en(en),
        .ring_in_vld(ring_in_vld),
        .ring_in_data(ring_in_data),
        .ring_in_dst(ring_in_dst),
       .push(inj_vld),
       .push_data(inj_data),
        .my_id(my_id),
        .ring_hold(ring_hold),
        .eject_vld(eject_vld),
        .eject_data(eject_data),
        .out_vld(out_vld),
        .out_data(out_data),
        .out_dst(out_dst),
        .q_count_o(a_q_count),
        .q_head_o(a_q_head),
        .q_tail_o(a_q_tail)
    );

    always @(posedge clk) begin
        if (rst) begin
            g_vld  <= 1'b0;
            g_data <= 64'd0;
        end else begin
           g_vld <= eject_vld || lb_vld;
            if (eject_vld)
                g_data <= eject_data;
           else if (lb_vld)
               g_data <= lb_data;
        end
    end
   // byte parity: generated on the host write, checked at each handoff
   reg [7:0] wr_bpar;
   reg [7:0] inj_chk;
   reg [7:0] lb_chk;
   always @(*) begin
       for (b = 0; b < 8; b = b + 1) begin
           wr_bpar[b] = ^push_data[8*b +: 8];
           inj_chk[b] = ^inj_data[8*b +: 8];
           lb_chk[b]  = ^lb_data[8*b +: 8];
       end
   end
   wire [STG_AW-1:0] stg_wa    = stg_wp[STG_AW-1:0];
   wire [STG_AW-1:0] stg_ra    = stg_rp[STG_AW-1:0];
   wire [3:0]  stg_level  = stg_wp - stg_rp;
   wire        stg_empty  = (stg_wp == stg_rp);
   wire        stg_full   = (stg_wp[STG_AW] != stg_rp[STG_AW]) && (stg_wa == stg_ra);
   wire [63:0] stg_head   = stg_mem[stg_ra];
   wire [7:0]  stg_hpar   = stg_par[stg_ra];
   wire        head_local = (stg_head[3:0] == my_id);
   wire        inj_take   = inj_vld && en;
   wire        lb_take    = lb_vld && !eject_vld;
   wire        inj_free   = !inj_vld || inj_take;
   wire        lb_free    = !lb_vld || lb_take;
   wire        ring_room  = (a_q_count + {4'd0, inj_take}) < RING_CAP;
   wire        tok_ok     = (inj_tok != 2'd0);
   wire        tok_earn   = en && !ring_in_vld;
   wire        issue_ring = !stg_empty && !head_local && inj_free && ring_room && tok_ok;
   wire        issue_lb   = !stg_empty && head_local && lb_free;
   wire        stg_rd     = issue_ring || issue_lb;
   wire        stg_wr     = push && !stg_full;
   wire        inj_bad    = inj_take && ((inj_chk != inj_par) || (a_q_count == RING_CAP));
   wire        lb_bad     = lb_take && (lb_chk != lb_par);
   wire        xfer_fault = inj_bad || lb_bad;
   always @(posedge clk) begin
       if (rst) begin
           stg_wp <= 4'd0;
           stg_rp <= 4'd0;
       end else begin
           if (stg_wr) begin
               stg_mem[stg_wa] <= push_data;
               stg_par[stg_wa] <= wr_bpar;
               stg_wp <= stg_wp + 4'd1;
           end
           if (stg_rd)
               stg_rp <= stg_rp + 4'd1;
       end
   end
   always @(posedge clk) begin
       if (rst) begin
           inj_vld  <= 1'b0;
           inj_data <= 64'd0;
           inj_par  <= 8'd0;
       end else if (issue_ring) begin
           inj_vld  <= 1'b1;
           inj_data <= stg_head;
           inj_par  <= stg_hpar;
       end else if (inj_take) begin
           inj_vld  <= 1'b0;
       end
   end
   always @(posedge clk) begin
       if (rst) begin
           lb_vld  <= 1'b0;
           lb_data <= 64'd0;
           lb_par  <= 8'd0;
       end else if (issue_lb) begin
           lb_vld  <= 1'b1;
           lb_data <= stg_head;
           lb_par  <= stg_hpar;
       end else if (lb_take) begin
           lb_vld  <= 1'b0;
       end
   end
   always @(posedge clk) begin
       if (rst)
           inj_tok <= INJ_BURST;
       else if (issue_ring && !tok_earn)
           inj_tok <= inj_tok - 2'd1;
       else if (tok_earn && !issue_ring && (inj_tok != INJ_BURST))
           inj_tok <= inj_tok + 2'd1;
   end
   always @(posedge clk) begin
       if (rst) begin
           stall_cnt <= 16'd0;
           stg_hwm   <= 4'd0;
       end else begin
           if (push && stg_full && (stall_cnt != 16'hFFFF))
               stall_cnt <= stall_cnt + 16'd1;
           if (stg_level > stg_hwm)
               stg_hwm <= stg_level;
       end
   end

    always @(posedge clk) begin
        if (rearm)
            trace_offered <= 6'd0;
        else if (g_vld && (trace_offered != 6'd63))
            trace_offered <= trace_offered + 6'd1;
    end

    pretrig_capture u_trace (
        .clk(clk),
        .ce(g_vld),
        .rearm(rearm),
        .trig(trig),
        .sample(g_data),
        .rd_idx(rd_idx),
        .rd_data(rd_data),
        .is_frozen(is_frozen),
        .captured(captured),
        .count_o(b_count),
        .frozen_o(b_frozen),
        .valid_o(b_valid)
    );

    assign trace_vld       = g_vld;
    assign trace_data      = g_data;
    assign trace_offered_o = trace_offered;
    assign trace_missed    = trace_offered - b_count[5:0];

    always @(posedge clk)
        if (b_frozen)
            assert (trace_offered > 6'd48);
   always @(posedge clk)
       if (inj_take || lb_take)
           assert (!xfer_fault);
   assign push_ready   = !stg_full;
   assign stg_level_o  = stg_level;
   assign stg_hwm_o    = stg_hwm;
   assign push_stalls  = stall_cnt;
   assign inj_tokens_o = inj_tok;
   assign inj_busy     = inj_vld;
   assign lb_busy      = lb_vld;
   assign inj_fault    = xfer_fault;
endmodule

// Fault log for the packet steering MPU. Every steering decision the MPU
// rejects is recorded with its destination, deliver flag, matching rule and
// a timestamp. Software reads the oldest entry and manages the log through
// the region indexes the MPU table does not implement (24 and up). A new
// lookup is only admitted when the log can absorb a fault from every
// decision still travelling down the steering pipeline.
module mpu_fault_log #(
    parameter DEPTH   = 4,
    parameter PTR_W   = 2,
    parameter CNT_W   = 3,
    parameter STAMP_W = 8
) (
    input  wire               clk,
    input  wire               rst,
    input  wire               i_ce,
    input  wire               lk_busy,
    input  wire               rsp_fire,
    input  wire [6:0]         rsp_rule,
    input  wire               acc_pending,
    input  wire [15:0]        acc_addr,
    input  wire               acc_write,
    input  wire               chk_hit,
    input  wire               chk_miss,
    input  wire               csr_we,
    input  wire [4:0]         csr_idx,
    input  wire [15:0]        csr_wdata,
    input  wire               lk_req,
    output wire               lk_ready,
    output wire               lk_req_gated,
    output wire [CNT_W-1:0]   log_count,
    output wire               log_empty,
    output wire               log_full,
    output wire [15:0]        head_addr,
    output wire               head_write,
    output wire [6:0]         head_rule,
    output wire [STAMP_W-1:0] head_stamp,
    output wire [3:0]         head_rep,
    output wire [CNT_W+2:0]   ctrl_rb,
    output wire               irq,
    output wire [7:0]         ok_cnt,
    output wire [7:0]         flt_cnt
);
    localparam [4:0]       CSR_CTRL  = 5'd24;
    localparam [4:0]       CSR_POP   = 5'd25;
    localparam [4:0]       CSR_FLUSH = 5'd26;
    localparam [4:0]       CSR_STCLR = 5'd27;
    localparam [PTR_W-1:0] LAST_PTR  = DEPTH - 1;
    localparam [CNT_W-1:0] FULL_CNT  = DEPTH;
    localparam [CNT_W-1:0] ONE_CNT   = 1;
    // log storage
    reg [15:0]        ent_addr  [0:DEPTH-1];
    reg               ent_write [0:DEPTH-1];
    reg [6:0]         ent_rule  [0:DEPTH-1];
    reg [STAMP_W-1:0] ent_stamp [0:DEPTH-1];
    reg [3:0]         ent_rep   [0:DEPTH-1];
    reg [PTR_W-1:0]   wr_ptr;
    reg [PTR_W-1:0]   rd_ptr;
    reg [CNT_W-1:0]   count;
    // shadow of the decision in the access register (rule) and of the
    // decision in the MPU check stage (rule, destination, deliver flag)
    reg [6:0]         g_rule;
    reg [15:0]        c_addr;
    reg               c_write;
    reg [6:0]         c_rule;
    // control, timestamp and statistics
    reg [STAMP_W-1:0] stamp;
    reg               irq_en;
    reg               halt_en;
    reg               coal_en;
    reg [CNT_W-1:0]   wmark;
    reg               irq_q;
    reg [7:0]         ok_q;
    reg [7:0]         flt_q;
    integer k;
    initial begin
        for (k = 0; k < DEPTH; k = k + 1) begin
            ent_addr[k]  = 16'd0;
            ent_write[k] = 1'b0;
            ent_rule[k]  = 7'd0;
            ent_stamp[k] = {STAMP_W{1'b0}};
            ent_rep[k]   = 4'd0;
        end
        wr_ptr  = {PTR_W{1'b0}};
        rd_ptr  = {PTR_W{1'b0}};
        count   = {CNT_W{1'b0}};
        g_rule  = 7'd0;
        c_addr  = 16'd0;
        c_write = 1'b0;
        c_rule  = 7'd0;
        stamp   = {STAMP_W{1'b0}};
        irq_en  = 1'b0;
        halt_en = 1'b0;
        coal_en = 1'b0;
        wmark   = {CNT_W{1'b0}};
        irq_q   = 1'b0;
        ok_q    = 8'd0;
        flt_q   = 8'd0;
    end
    // CSR decode on the region indexes the MPU table does not implement
    wire csr_ctrl  = csr_we && (csr_idx == CSR_CTRL);
    wire csr_pop   = csr_we && (csr_idx == CSR_POP);
    wire csr_flush = csr_we && (csr_idx == CSR_FLUSH);
    wire csr_stclr = csr_we && (csr_idx == CSR_STCLR);
    wire empty = (count == {CNT_W{1'b0}});
    wire full  = (count == FULL_CNT);
    // ring pointers; wr_prev names the newest entry
    wire [PTR_W-1:0] wr_prev = (wr_ptr == {PTR_W{1'b0}}) ? LAST_PTR : wr_ptr - 1'b1;
    wire [PTR_W-1:0] wr_nxt  = (wr_ptr == LAST_PTR) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
    wire [PTR_W-1:0] rd_nxt  = (rd_ptr == LAST_PTR) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
    wire pop = csr_pop && !empty && !csr_flush;
    // a fault repeating the newest entry is folded into it when enabled,
    // unless that entry is being popped in the same cycle
    wire same_as_newest = (ent_addr[wr_prev] == c_addr) &&
                          (ent_write[wr_prev] == c_write) &&
                          (ent_rule[wr_prev] == c_rule);
    wire coalesce = chk_miss && coal_en && !empty && !csr_flush && same_as_newest &&
                    !(pop && (count == ONE_CNT));
    wire push = chk_miss && !coalesce && !full;
    // every decision still in the steering pipeline may turn into a fault;
    // a new lookup is only started when the log can absorb all of them
    wire [CNT_W:0] reserved = {1'b0, count}
                            + {{CNT_W{1'b0}}, lk_busy}
                            + {{CNT_W{1'b0}}, rsp_fire}
                            + {{CNT_W{1'b0}}, acc_pending}
                            + {{CNT_W{1'b0}}, chk_miss};
    wire room   = (reserved < DEPTH);
    wire halted = halt_en && !empty;
    assign lk_ready     = room && !halted;
    assign lk_req_gated = lk_req && lk_ready;
    always @(posedge clk) begin
        if (rst) begin
            for (k = 0; k < DEPTH; k = k + 1) begin
                ent_addr[k]  <= 16'd0;
                ent_write[k] <= 1'b0;
                ent_rule[k]  <= 7'd0;
                ent_stamp[k] <= {STAMP_W{1'b0}};
                ent_rep[k]   <= 4'd0;
            end
            wr_ptr  <= {PTR_W{1'b0}};
            rd_ptr  <= {PTR_W{1'b0}};
            count   <= {CNT_W{1'b0}};
            g_rule  <= 7'd0;
            c_addr  <= 16'd0;
            c_write <= 1'b0;
            c_rule  <= 7'd0;
            stamp   <= {STAMP_W{1'b0}};
            irq_en  <= 1'b0;
            halt_en <= 1'b0;
            coal_en <= 1'b0;
            wmark   <= {CNT_W{1'b0}};
            irq_q   <= 1'b0;
            ok_q    <= 8'd0;
            flt_q   <= 8'd0;
        end else if (i_ce) begin
            stamp <= stamp + 1'b1;
            if (rsp_fire)
                g_rule <= rsp_rule;
            if (acc_pending) begin
                c_addr  <= acc_addr;
                c_write <= acc_write;
                c_rule  <= g_rule;
            end
            if (csr_ctrl) begin
                irq_en  <= csr_wdata[0];
                halt_en <= csr_wdata[1];
                coal_en <= csr_wdata[2];
                wmark   <= csr_wdata[8 +: CNT_W];
            end
            if (push) begin
                ent_addr[wr_ptr]  <= c_addr;
                ent_write[wr_ptr] <= c_write;
                ent_rule[wr_ptr]  <= c_rule;
                ent_stamp[wr_ptr] <= stamp;
                ent_rep[wr_ptr]   <= 4'd0;
                wr_ptr            <= wr_nxt;
            end
            if (coalesce && (ent_rep[wr_prev] != 4'hF))
                ent_rep[wr_prev] <= ent_rep[wr_prev] + 4'd1;
            if (csr_flush) begin
                rd_ptr <= wr_ptr;
                count  <= push ? ONE_CNT : {CNT_W{1'b0}};
            end else begin
                if (pop)
                    rd_ptr <= rd_nxt;
                count <= count + {{(CNT_W-1){1'b0}}, push} - {{(CNT_W-1){1'b0}}, pop};
            end
            if (csr_stclr) begin
                ok_q  <= 8'd0;
                flt_q <= 8'd0;
            end else begin
                if (chk_hit && (ok_q != 8'hFF))
                    ok_q <= ok_q + 8'd1;
                if (chk_miss && (flt_q != 8'hFF))
                    flt_q <= flt_q + 8'd1;
            end
            irq_q <= irq_en && (((wmark != {CNT_W{1'b0}}) && (count >= wmark)) || halted);
        end
    end
    assign log_count  = count;
    assign log_empty  = empty;
    assign log_full   = full;
    assign head_addr  = empty ? 16'd0 : ent_addr[rd_ptr];
    assign head_write = !empty && ent_write[rd_ptr];
    assign head_rule  = empty ? 7'd0 : ent_rule[rd_ptr];
    assign head_stamp = empty ? {STAMP_W{1'b0}} : ent_stamp[rd_ptr];
    assign head_rep   = empty ? 4'd0 : ent_rep[rd_ptr];
    assign ctrl_rb    = {wmark, coal_en, halt_en, irq_en};
    assign irq        = irq_q;
    assign ok_cnt     = ok_q;
    assign flt_cnt    = flt_q;
endmodule

module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
    output reg  [6:0]  rsp_rule
,
    output wire busy_o,
    output wire [6:0] idx_o,
    output wire [7:0] timer_o
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
    wire last = (idx == 7'd127);

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
                if (req) begin
                    busy  <= 1'b1;
                    idx   <= 7'd0;
                    timer <= 8'd128;
                    q_key <= req_key;
                    q_len <= {48'd0, req_len};
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
    assign busy_o = busy;
    assign idx_o = idx;
    assign timer_o = timer;
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
    output reg         fault
,
    output wire hit_q_o,
    output wire miss_q_o
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
            fault  <= miss_q;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
    assign hit_q_o = hit_q;
    assign miss_q_o = miss_q;
endmodule

module flow_mpu_top (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    output wire        grant,
    output wire        fault,
    output wire [6:0]  rsp_rule,
    output wire        g_valid_o,
    output wire [15:0] g_addr_o,
    output wire        g_write_o
,
    output wire        lookup_ready,
    output wire        flog_irq,
    output wire [2:0]  flog_count_o,
    output wire        flog_empty_o,
    output wire        flog_full_o,
    output wire [15:0] flog_head_addr,
    output wire        flog_head_write,
    output wire [6:0]  flog_head_rule,
    output wire [7:0]  flog_head_stamp,
    output wire [3:0]  flog_head_rep,
    output wire [5:0]  flog_ctrl,
    output wire [7:0]  steer_ok_cnt,
    output wire [7:0]  steer_flt_cnt
);
    wire        rsp_valid;
    wire        rsp_hit;
    wire [31:0] rsp_action;
    wire        busy_a;
    wire [6:0]  idx_a;
    wire [7:0]  timer_a;
    wire        hit_q;
    wire        miss_q;
    // fault log in front of the lookup request: every steering decision
    // still in flight holds one log slot in reserve
    localparam FLOG_DEPTH = 4;
    wire        flow_req;
    wire [2:0]  flog_count;
    wire        steer_fire = rsp_valid && rsp_hit;

    // pending destination-buffer access handed from the classifier to the MPU
    reg        g_valid;
    reg [15:0] g_addr;
    reg        g_write;

    initial begin
        g_valid = 1'b0;
        g_addr  = 16'd0;
        g_write = 1'b0;
    end

    flow_match_table u_flow (
        .clk(clk),
        .rst(rst),
        .i_ce(i_ce),
        .req(flow_req),
        .req_key(req_key),
        .req_len(req_len),
        .wr_en(wr_en),
        .wr_idx(wr_idx),
        .wr_key(wr_key),
        .wr_action(wr_action),
        .rsp_valid(rsp_valid),
        .rsp_hit(rsp_hit),
        .rsp_action(rsp_action),
        .rsp_rule(rsp_rule),
        .busy_o(busy_a),
        .idx_o(idx_a),
        .timer_o(timer_a)
    );

    always @(posedge clk) begin
        if (rst) begin
            g_valid <= 1'b0;
            g_addr  <= 16'd0;
            g_write <= 1'b0;
        end else if (i_ce) begin
            g_valid <= rsp_valid && rsp_hit;
            if (rsp_valid && rsp_hit) begin
                g_addr  <= rsp_action[15:0];
                g_write <= rsp_action[16];
            end
        end
    end

    mpu_region_checker u_mpu (
        .clk(clk),
        .i_ce(i_ce),
        .cfg_we(cfg_we),
        .cfg_idx(cfg_idx),
        .cfg_base(cfg_base),
        .cfg_limit(cfg_limit),
        .cfg_perm(cfg_perm),
        .lock_req(lock_req),
        .acc_valid(g_valid),
        .acc_write(g_write),
        .acc_addr(g_addr),
        .grant(grant),
        .fault(fault),
        .hit_q_o(hit_q),
        .miss_q_o(miss_q)
    );
    mpu_fault_log #(
        .DEPTH(FLOG_DEPTH),
        .PTR_W(2),
        .CNT_W(3),
        .STAMP_W(8)
    ) u_flog (
        .clk(clk),
        .rst(rst),
        .i_ce(i_ce),
        .lk_busy(busy_a),
        .rsp_fire(steer_fire),
        .rsp_rule(rsp_rule),
        .acc_pending(g_valid),
        .acc_addr(g_addr),
        .acc_write(g_write),
        .chk_hit(hit_q),
        .chk_miss(miss_q),
        .csr_we(cfg_we),
        .csr_idx(cfg_idx),
        .csr_wdata(cfg_base),
        .lk_req(req),
        .lk_ready(lookup_ready),
        .lk_req_gated(flow_req),
        .log_count(flog_count),
        .log_empty(flog_empty_o),
        .log_full(flog_full_o),
        .head_addr(flog_head_addr),
        .head_write(flog_head_write),
        .head_rule(flog_head_rule),
        .head_stamp(flog_head_stamp),
        .head_rep(flog_head_rep),
        .ctrl_rb(flog_ctrl),
        .irq(flog_irq),
        .ok_cnt(steer_ok_cnt),
        .flt_cnt(steer_flt_cnt)
    );
    assign flog_count_o = flog_count;

    assign g_valid_o = g_valid;
    assign g_addr_o  = g_addr;
    assign g_write_o = g_write;

    // the MPU never holds two packet steering decisions in its check stage at once
    always @(posedge clk)
        if (g_valid)
            assert (!(hit_q || miss_q));
    // a steering decision the MPU rejects always finds a free fault-log slot
    always @(posedge clk)
        if (miss_q)
            assert (flog_count < FLOG_DEPTH);
endmodule

module neo_ringstop (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        ring_in_vld,
    input  wire [63:0] ring_in_data,
    input  wire [3:0]  ring_in_dst,
    input  wire        push,
    input  wire [63:0] push_data,
    input  wire [3:0]  my_id,
    output wire        ring_hold,
    output wire        eject_vld,
    output wire [63:0] eject_data,
    output wire        out_vld,
    output wire [63:0] out_data,
output wire [3:0]  out_dst,
output wire        out_xcls,
output wire [4:0]  pool_used
);
    reg        slot_vld = 1'b0;
    reg [63:0] slot_data = 64'd0;
    reg [3:0]  slot_dst = 4'd0;
    reg [63:0] fifo [0:15];
    reg [4:0]  q_head = 5'd0;
    reg [4:0]  q_tail = 5'd0;
    reg [4:0]  q_count = 5'd0;
    reg [63:0] starve_cnt = 64'd0;
    reg        rsv = 1'b0;
    reg [63:0] inj_total = 64'd0;
    reg        pre_rsv = 1'b1;
    reg        pv = 1'b0;
localparam CHANNELS = 2;
localparam XDEPTH   = 4;
localparam XPW      = 3;
localparam [4:0] POOL = 5'd16;
reg [63:0]    xq [0:XDEPTH-1];
reg [XPW-1:0] x_head = {XPW{1'b0}};
reg [XPW-1:0] x_tail = {XPW{1'b0}};
reg [4:0]     occ = 5'd0;
reg           slot_xcls = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) fifo[i] = 64'd0;
for (i = 0; i < XDEPTH; i = i + 1) xq[i] = 64'd0;
    end

    wire through   = ring_in_vld && (ring_in_dst != my_id);
    wire nonempty  = (q_head != q_tail);
    wire free_slot = (!through) || rsv;
wire [XPW-1:0] x_used = x_tail - x_head;
wire x_nonempty = (x_head != x_tail);
wire pool_ok    = (occ < POOL);
wire urgent     = rsv && nonempty;
wire [CHANNELS-1:0] req = {x_nonempty, nonempty};
wire [CHANNELS-1:0] gnt = !free_slot ? {CHANNELS{1'b0}} :
                          (urgent || !req[1]) ? {1'b0, req[0]} : 2'b10;
wire pop       = gnt[0];
wire x_pop     = gnt[1];
wire x_cls     = push_data[63];
wire push_ok   = push && !x_cls && (q_count < 5'd16) && pool_ok;
wire x_push_ok = push && x_cls && (x_used < XDEPTH) && pool_ok;
    wire dec       = pop && (q_count != 5'd0);
wire occ_dec   = (pop || x_pop) && (occ != 5'd0);

    assign ring_hold  = rsv && through;
    assign eject_vld  = ring_in_vld && (ring_in_dst == my_id);
    assign eject_data = ring_in_data;
    assign out_vld    = slot_vld;
    assign out_data   = slot_data;
    assign out_dst    = slot_dst;
assign out_xcls   = slot_xcls;
assign pool_used  = occ;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            slot_vld   <= 1'b0;
            slot_data  <= 64'd0;
            slot_dst   <= 4'd0;
            q_head     <= 5'd0;
            q_tail     <= 5'd0;
            q_count    <= 5'd0;
            starve_cnt <= 64'd0;
            rsv        <= 1'b0;
            inj_total  <= 64'd0;
            pre_rsv    <= 1'b1;
x_head     <= {XPW{1'b0}};
x_tail     <= {XPW{1'b0}};
occ        <= 5'd0;
slot_xcls  <= 1'b0;
        end else if (en) begin
if (x_pop) begin
    slot_vld  <= 1'b1;
    slot_data <= xq[x_head[XPW-2:0]];
    slot_dst  <= xq[x_head[XPW-2:0]][3:0];
    slot_xcls <= 1'b1;
    x_head    <= x_head + 1'b1;
    inj_total <= inj_total + 64'd1;
end else if (pop) begin
                slot_vld  <= 1'b1;
                slot_data <= fifo[q_head[3:0]];
                slot_dst  <= fifo[q_head[3:0]][3:0];
slot_xcls <= 1'b0;
                q_head    <= q_head + 5'd1;
                inj_total <= inj_total + 64'd1;
            end else if (through) begin
                slot_vld  <= 1'b1;
                slot_data <= ring_in_data;
                slot_dst  <= ring_in_dst;
slot_xcls <= 1'b0;
            end else begin
                slot_vld  <= 1'b0;
            end

            if (push_ok) begin
                fifo[q_tail[3:0]] <= push_data;
                q_tail <= q_tail + 5'd1;
            end

            q_count <= q_count + {4'd0, push_ok} - {4'd0, dec};
if (x_push_ok) begin
    xq[x_tail[XPW-2:0]] <= push_data;
    x_tail <= x_tail + 1'b1;
end
occ <= occ + {4'd0, push_ok | x_push_ok} - {4'd0, occ_dec};

            if (pop)
                starve_cnt <= 64'd0;
            else if (nonempty)
                starve_cnt <= starve_cnt + 64'd1;

            if (pop)
                rsv <= 1'b0;
            else if (starve_cnt == 64'd1000) begin
                rsv     <= 1'b1;
                pre_rsv <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (pv && !$past(rst) && pre_rsv && $stable(q_tail) && $stable(q_count))
            assert ($stable(q_head));
always @(posedge clk)
    if (pv && $stable(x_tail) && $stable(occ) && $stable(q_tail))
        assert ($stable(x_head));
endmodule

module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
    output reg  [6:0]  rsp_rule
,
    output wire busy_o,
    output wire [6:0] idx_o,
    output wire [7:0] timer_o
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
    wire last = (idx == 7'd127);

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
                if (req) begin
                    busy  <= 1'b1;
                    idx   <= 7'd0;
                    timer <= 8'd128;
                    q_key <= req_key;
                    q_len <= {48'd0, req_len};
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
    assign busy_o = busy;
    assign idx_o = idx;
    assign timer_o = timer;
endmodule

module usb_route_lookup (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_pkt_valid,
    input wire [31:0] i_dest,
    input wire cfg_we,
    input wire [4:0] cfg_addr,
    input wire [31:0] cfg_data,
    output wire o_done,
    output wire [31:0] o_port
,
    output wire fin_q_o,
    output wire [1:0] phase_o,
    output wire [31:0] step_cnt_o
);
    localparam [1:0] P_IDLE = 2'd0, P_ARM = 2'd1, P_START = 2'd2, P_FIN = 2'd3;

    reg [1:0]  phase    = 2'd0;
    reg [31:0] step_cnt = 32'd0;
    reg        fin_q    = 1'b0;
    reg [31:0] dest_q   = 32'd0;
    reg [31:0] port_q   = 32'd0;

    reg [31:0] rt_mem [0:31];
    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1)
            rt_mem[i] = 32'd0;
    end

    // routing table configuration write port
    always @(posedge clk)
        if (!i_reset && i_ce && cfg_we)
            rt_mem[cfg_addr] <= cfg_data;

    // lookup sequencer: arm (capture dest) -> start (table read) -> finish (port valid)
    always @(posedge clk) begin
        if (i_reset) begin
            phase    <= P_IDLE;
            step_cnt <= 32'd0;
            fin_q    <= 1'b0;
            dest_q   <= 32'd0;
            port_q   <= 32'd0;
        end else if (i_ce) begin
            fin_q <= (step_cnt == 32'd2);
            case (phase)
                P_IDLE:  if (i_pkt_valid) begin
                             phase  <= P_ARM;
                             dest_q <= i_dest;
                         end
                P_ARM:   phase <= P_START;
                P_START: begin
                             phase  <= P_FIN;
                             port_q <= rt_mem[dest_q[4:0]];
                         end
                default: phase <= P_IDLE;
            endcase
            case (step_cnt)
                32'd0:   if (i_pkt_valid) step_cnt <= 32'd1;
                32'd3:   step_cnt <= 32'd0;
                default: step_cnt <= step_cnt + 32'd1;
            endcase
        end
    end

    assign o_done = fin_q;
    assign o_port = port_q;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && fin_q)
            assert (($past(phase) == P_START) || ($past(phase) == P_FIN));
    assign fin_q_o = fin_q;
    assign phase_o = phase;
    assign step_cnt_o = step_cnt;
endmodule

module flow_route_pipe (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_addr,
    input  wire [31:0] cfg_data,
    output wire        o_done,
    output wire [31:0] o_port,
    output wire [6:0]  o_rule,
    output wire        o_miss,
    output wire        o_stall,
    output wire        pend_v_o,
    output wire        fly_v_o
,
    output wire a_busy_o,
    output wire [6:0] a_idx_o,
    output wire a_rsp_valid_o,
    output wire [7:0] a_timer_o,
    output wire b_fin_q_o,
    output wire [1:0] b_phase_o,
    output wire [31:0] b_step_cnt_o,
    output wire fly_v_obs,
    output wire pend_v_obs
);
    // flow table side
    wire        a_rsp_valid;
    wire        a_rsp_hit;
    wire [31:0] a_rsp_action;
    wire [6:0]  a_rsp_rule;
    wire        a_busy;
    wire [6:0]  a_idx;
    wire [7:0]  a_timer;

    // route lookup side
    wire        b_done;
    wire [31:0] b_port;
    wire        b_fin_q;
    wire [1:0]  b_phase;
    wire [31:0] b_step_cnt;

    // forwarding register between classifier and router
    reg        pend_v;
    reg [31:0] pend_dest;
    reg [6:0]  pend_rule;
    // rule tag for the packet currently inside the route lookup
    reg        fly_v;
    reg [6:0]  fly_rule;

    initial begin
        pend_v    = 1'b0;
        pend_dest = 32'd0;
        pend_rule = 7'd0;
        fly_v     = 1'b0;
        fly_rule  = 7'd0;
    end

    // classifier only advances while the forwarding slot is free
    wire a_ce   = i_ce && !pend_v;
    // matched response accepted into the forwarding slot
    wire a_fwd  = !pend_v && a_rsp_valid && a_rsp_hit;
    // route lookup takes the slot when idle
    wire b_take = pend_v && (b_phase == 2'd0);

    flow_match_table u_fmt (
        .clk(clk),
        .rst(rst),
        .i_ce(a_ce),
        .req(req),
        .req_key(req_key),
        .req_len(req_len),
        .wr_en(wr_en),
        .wr_idx(wr_idx),
        .wr_key(wr_key),
        .wr_action(wr_action),
        .rsp_valid(a_rsp_valid),
        .rsp_hit(a_rsp_hit),
        .rsp_action(a_rsp_action),
        .rsp_rule(a_rsp_rule),
        .busy_o(a_busy),
        .idx_o(a_idx),
        .timer_o(a_timer)
    );

    usb_route_lookup u_rt (
        .clk(clk),
        .i_reset(rst),
        .i_ce(i_ce),
        .i_pkt_valid(pend_v),
        .i_dest(pend_dest),
        .cfg_we(cfg_we),
        .cfg_addr(cfg_addr),
        .cfg_data(cfg_data),
        .o_done(b_done),
        .o_port(b_port),
        .fin_q_o(b_fin_q),
        .phase_o(b_phase),
        .step_cnt_o(b_step_cnt)
    );

    always @(posedge clk) begin
        if (rst) begin
            pend_v    <= 1'b0;
            pend_dest <= 32'd0;
            pend_rule <= 7'd0;
            fly_v     <= 1'b0;
            fly_rule  <= 7'd0;
        end else if (i_ce) begin
            if (b_take) begin
                pend_v   <= 1'b0;
                fly_v    <= 1'b1;
                fly_rule <= pend_rule;
            end else if (a_fwd) begin
                pend_v    <= 1'b1;
                pend_dest <= a_rsp_action;
                pend_rule <= a_rsp_rule;
            end
            if (b_done)
                fly_v <= 1'b0;
        end
    end

    assign o_done   = b_done;
    assign o_port   = b_port;
    assign o_rule   = fly_rule;
    assign o_miss   = a_rsp_valid && !a_rsp_hit;
    assign o_stall  = pend_v;
    assign pend_v_o = pend_v;
    assign fly_v_o  = fly_v;

    // every routed result must belong to a tagged, forwarded packet
    always @(posedge clk)
        if (b_done)
            assert (fly_v);
    assign a_busy_o = a_busy;
    assign a_idx_o = a_idx;
    assign a_rsp_valid_o = a_rsp_valid;
    assign a_timer_o = a_timer;
    assign b_fin_q_o = b_fin_q;
    assign b_phase_o = b_phase;
    assign b_step_cnt_o = b_step_cnt;
    assign fly_v_obs = fly_v;
    assign pend_v_obs = pend_v;
endmodule

module mcast_demux (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_arm,
    input  wire [7:0] i_mask,
    input  wire [7:0] i_data,
    input  wire [7:0] i_ready,
    output wire [7:0] o_valid,
    output wire [7:0] o_data,
    output wire       o_done,
    output wire       o_busy
,
    output wire [7:0] delivered_o,
    output wire [7:0] mask_o,
    output wire [1:0] phase_o
);
    localparam IDLE  = 2'd0;
    localparam ARMED = 2'd1;
    localparam SEND  = 2'd2;
    localparam FIN   = 2'd3;

    reg [1:0] phase;
    reg [7:0] mask;
    reg [7:0] delivered;
    reg [7:0] data;
    initial phase = IDLE;
    initial mask = 8'd0;
    initial delivered = 8'd0;
    initial data = 8'd0;

    assign o_valid = (phase == SEND) ? (mask & ~delivered) : 8'd0;
    assign o_data  = data;
    assign o_done  = (phase == FIN);
    assign o_busy  = (phase != IDLE);

    wire [7:0] accepted = o_valid & i_ready;
    wire [7:0] next_del = delivered | accepted;

    always @(posedge clk) begin
        if (i_reset) begin
            phase     <= IDLE;
            mask      <= 8'd0;
            delivered <= 8'd0;
            data      <= 8'd0;
        end else if (i_ce) begin
            case (phase)
                IDLE: begin
                    if (i_arm && (i_mask != 8'd0)) begin
                        mask      <= i_mask;
                        data      <= i_data;
                        delivered <= 8'd0;
                        phase     <= ARMED;
                    end
                end
                ARMED: begin
                    phase <= SEND;
                end
                SEND: begin
                    delivered <= next_del;
                    if (next_del == mask)
                        phase <= FIN;
                end
                FIN: begin
                    phase     <= IDLE;
                    mask      <= 8'd0;
                    delivered <= 8'd0;
                end
            endcase
        end
    end

    // finish implies a copy was started (at least one delivery)
    always @(*)
        if (phase == FIN) assert (delivered != 8'd0);

    // finish implies an arm with a non-empty destination mask happened
    always @(*)
        if (phase == FIN) assert (mask != 8'd0);
    assign delivered_o = delivered;
    assign mask_o = mask;
    assign phase_o = phase;
endmodule

module flow_mcast_forwarder (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_addr,
    input  wire [31:0] cfg_data,
    input  wire [7:0]  i_ready,
    output wire [7:0]  o_valid,
    output wire [7:0]  o_data,
    output wire        o_done,
    output wire        o_busy,
    output wire        o_miss,
    output wire        o_stall,
    output wire        hold_v_o,
    output wire [7:0]  hold_mask_o,
    output wire [6:0]  hold_tag_o
);
    // flow classifier + route pipe side
    wire        f_done;
    wire [31:0] f_port;
    wire [6:0]  f_rule;
    wire        f_miss;
    wire        f_stall;
    wire        f_pend_v;
    wire        f_fly_v;
    wire        fa_busy;
    wire [6:0]  fa_idx;
    wire        fa_rsp_valid;
    wire [7:0]  fa_timer;
    wire        fr_fin_q;
    wire [1:0]  fr_phase;
    wire [31:0] fr_step_cnt;
    wire        f_fly_v_obs;
    wire        f_pend_v_obs;

    // multicast demux side
    wire [7:0]  m_valid;
    wire [7:0]  m_data;
    wire        m_done;
    wire        m_busy;
    wire [7:0]  m_delivered;
    wire [7:0]  m_mask;
    wire [1:0]  m_phase;

    // hold register: one routed result waiting to be replicated
    reg        g_v;
    reg [7:0]  g_mask;
    reg [6:0]  g_tag;
    initial begin
        g_v    = 1'b0;
        g_mask = 8'd0;
        g_tag  = 7'd0;
    end

    // classifier advances only when the hold is empty and the demux is free
    wire a_ce    = i_ce && !g_v && !m_busy;
    // routed result leaves the classifier pipe into the hold
    wire g_load  = a_ce && f_done;
    // demux is idle and takes the held result as a new multicast
    wire g_issue = i_ce && g_v && !m_busy;

    flow_route_pipe u_frp (
        .clk(clk),
        .rst(rst),
        .i_ce(a_ce),
        .req(req),
        .req_key(req_key),
        .req_len(req_len),
        .wr_en(wr_en),
        .wr_idx(wr_idx),
        .wr_key(wr_key),
        .wr_action(wr_action),
        .cfg_we(cfg_we),
        .cfg_addr(cfg_addr),
        .cfg_data(cfg_data),
        .o_done(f_done),
        .o_port(f_port),
        .o_rule(f_rule),
        .o_miss(f_miss),
        .o_stall(f_stall),
        .pend_v_o(f_pend_v),
        .fly_v_o(f_fly_v),
        .a_busy_o(fa_busy),
        .a_idx_o(fa_idx),
        .a_rsp_valid_o(fa_rsp_valid),
        .a_timer_o(fa_timer),
        .b_fin_q_o(fr_fin_q),
        .b_phase_o(fr_phase),
        .b_step_cnt_o(fr_step_cnt),
        .fly_v_obs(f_fly_v_obs),
        .pend_v_obs(f_pend_v_obs)
    );

    mcast_demux u_mc (
        .clk(clk),
        .i_reset(rst),
        .i_ce(i_ce),
        .i_arm(g_v),
        .i_mask(g_mask),
        .i_data({1'b0, g_tag}),
        .i_ready(i_ready),
        .o_valid(m_valid),
        .o_data(m_data),
        .o_done(m_done),
        .o_busy(m_busy),
        .delivered_o(m_delivered),
        .mask_o(m_mask),
        .phase_o(m_phase)
    );

    always @(posedge clk) begin
        if (rst) begin
            g_v    <= 1'b0;
            g_mask <= 8'd0;
            g_tag  <= 7'd0;
        end else if (i_ce) begin
            if (g_load) begin
                g_v    <= 1'b1;
                g_mask <= f_port[7:0];
                g_tag  <= f_rule;
            end else if (g_issue) begin
                g_v    <= 1'b0;
            end
        end
    end

    assign o_valid     = m_valid;
    assign o_data      = m_data;
    assign o_done      = m_done;
    assign o_busy      = m_busy;
    assign o_miss      = f_miss;
    assign o_stall     = f_stall || g_v || m_busy;
    assign hold_v_o    = g_v;
    assign hold_mask_o = g_mask;
    assign hold_tag_o  = g_tag;

    // a multicast can only finish while no further routed result is parked
    always @(*)
        if (m_done)
            assert (!g_v);
endmodule

module flow_hint_cache #(
  parameter ENTRIES = 4,
  parameter EW      = 2,
  parameter RW      = 7
) (
  input  wire                  clk,
  input  wire                  rst,
  input  wire                  ce,
  input  wire                  inv_en,
  input  wire [RW-1:0]         inv_idx,
  input  wire                  lk_en,
  input  wire [63:0]           lk_key,
  input  wire                  fill_en,
  input  wire [63:0]           fill_key,
  input  wire [RW-1:0]         fill_rule,
  output reg                   lk_hit,
  output reg  [RW-1:0]         lk_rule,
  output wire [ENTRIES-1:0]    ent_vld,
  output wire [ENTRIES*RW-1:0] ent_rules,
  output reg  [EW:0]           occ,
  output reg  [15:0]           hit_cnt,
  output reg  [15:0]           evict_cnt
);
  // cached flow key -> lowest matching rule index
  reg [63:0]        c_key  [0:ENTRIES-1];
  reg [RW-1:0]      c_rule [0:ENTRIES-1];
  reg [ENTRIES-1:0] c_vld;
  // second-chance reference bits and clock hand for replacement
  reg [ENTRIES-1:0] c_ref;
  reg [EW-1:0]      hand;

  integer n;
  initial begin
      for (n = 0; n < ENTRIES; n = n + 1) begin
          c_key[n]  = 64'd0;
          c_rule[n] = {RW{1'b0}};
      end
      c_vld     = {ENTRIES{1'b0}};
      c_ref     = {ENTRIES{1'b0}};
      hand      = {EW{1'b0}};
      hit_cnt   = 16'd0;
      evict_cnt = 16'd0;
  end

  assign ent_vld = c_vld;

  genvar g;
  generate
      for (g = 0; g < ENTRIES; g = g + 1) begin : g_rule_out
          assign ent_rules[g*RW +: RW] = c_rule[g];
      end
  endgenerate

  // lookup port: lowest-numbered valid entry holding the key
  reg [EW-1:0] lk_slot;
  integer jl;
  always @(*) begin
      lk_hit  = 1'b0;
      lk_rule = {RW{1'b0}};
      lk_slot = {EW{1'b0}};
      for (jl = ENTRIES - 1; jl >= 0; jl = jl - 1) begin
          if (c_vld[jl] && (c_key[jl] == lk_key)) begin
              lk_hit  = 1'b1;
              lk_rule = c_rule[jl];
              lk_slot = jl;
          end
      end
  end

  // fill port: refresh in place if the key is already cached
  reg          fl_hit;
  reg [EW-1:0] fl_slot;
  integer jf;
  always @(*) begin
      fl_hit  = 1'b0;
      fl_slot = {EW{1'b0}};
      for (jf = ENTRIES - 1; jf >= 0; jf = jf - 1) begin
          if (c_vld[jf] && (c_key[jf] == fill_key)) begin
              fl_hit  = 1'b1;
              fl_slot = jf;
          end
      end
  end

  // first free entry
  reg          fr_any;
  reg [EW-1:0] fr_slot;
  integer jv;
  always @(*) begin
      fr_any  = 1'b0;
      fr_slot = {EW{1'b0}};
      for (jv = ENTRIES - 1; jv >= 0; jv = jv - 1) begin
          if (!c_vld[jv]) begin
              fr_any  = 1'b1;
              fr_slot = jv;
          end
      end
  end

  // clock replacement: first entry from the hand with its reference bit clear
  reg          sc_any;
  reg [EW-1:0] sc_slot;
  reg [EW-1:0] sc_probe;
  integer js;
  always @(*) begin
      sc_any   = 1'b0;
      sc_slot  = hand;
      sc_probe = hand;
      for (js = ENTRIES - 1; js >= 0; js = js - 1) begin
          sc_probe = hand + js;
          if (!c_ref[sc_probe]) begin
              sc_any  = 1'b1;
              sc_slot = sc_probe;
          end
      end
  end

  // reference bits after the hand sweeps past the entries it skipped
  reg [ENTRIES-1:0] ref_swept;
  reg [EW-1:0]      sc_dist;
  reg [EW-1:0]      ent_dist;
  integer jr;
  always @(*) begin
      sc_dist   = sc_slot - hand;
      ent_dist  = {EW{1'b0}};
      ref_swept = {ENTRIES{1'b0}};
      for (jr = 0; jr < ENTRIES; jr = jr + 1) begin
          ent_dist      = jr - hand;
          ref_swept[jr] = c_ref[jr] && sc_any && (ent_dist > sc_dist);
      end
  end

  // a rule written at inv_idx can shadow any cached result at or above it
  reg [ENTRIES-1:0] inv_mask;
  integer ji;
  always @(*) begin
      for (ji = 0; ji < ENTRIES; ji = ji + 1)
          inv_mask[ji] = c_vld[ji] && (c_rule[ji] >= inv_idx);
  end

  integer jo;
  always @(*) begin
      occ = {(EW+1){1'b0}};
      for (jo = 0; jo < ENTRIES; jo = jo + 1)
          occ = occ + c_vld[jo];
  end

  wire [EW-1:0] vic_slot = fl_hit ? fl_slot : (fr_any ? fr_slot : sc_slot);

  always @(posedge clk) begin
      if (rst) begin
          c_vld     <= {ENTRIES{1'b0}};
          c_ref     <= {ENTRIES{1'b0}};
          hand      <= {EW{1'b0}};
          hit_cnt   <= 16'd0;
          evict_cnt <= 16'd0;
      end else if (ce) begin
          if (inv_en) begin
              c_vld <= c_vld & ~inv_mask;
              c_ref <= c_ref & ~inv_mask;
          end else begin
              if (lk_en && lk_hit) begin
                  c_ref[lk_slot] <= 1'b1;
                  if (hit_cnt != 16'hffff)
                      hit_cnt <= hit_cnt + 16'd1;
              end
              if (fill_en) begin
                  c_key[vic_slot]  <= fill_key;
                  c_rule[vic_slot] <= fill_rule;
                  c_vld[vic_slot]  <= 1'b1;
                  if (fl_hit)
                      c_ref[vic_slot] <= 1'b1;
                  else if (fr_any)
                      c_ref[vic_slot] <= 1'b0;
                  else begin
                      c_ref <= ref_swept;
                      hand  <= sc_slot + 1'b1;
                      if (evict_cnt != 16'hffff)
                          evict_cnt <= evict_cnt + 16'd1;
                  end
              end
          end
      end
  end
endmodule

module lookup_req_queue #(
   parameter DEPTH = 4,
   parameter AW    = 2
) (
   input  wire          clk,
   input  wire          rst,
   input  wire          ce,
   input  wire          push,
   input  wire [63:0]   push_key,
   input  wire [15:0]   push_len,
   input  wire          pop,
   input  wire          tbl_wr,
   input  wire [6:0]    tbl_idx,
   output wire          ready,
   output wire          avail,
   output wire [63:0]   head_key,
   output wire [15:0]   head_len,
   output reg  [AW:0]   count,
   output reg  [6:0]    hwm,
   output wire [6:0]    scan_lim
);
   reg [63:0]   key_q [0:DEPTH-1];
   reg [15:0]   len_q [0:DEPTH-1];
   reg [AW-1:0] wr_ptr;
   reg [AW-1:0] rd_ptr;

   integer n;
   initial begin
       for (n = 0; n < DEPTH; n = n + 1) begin
           key_q[n] = 64'd0;
           len_q[n] = 16'd0;
       end
       wr_ptr = {AW{1'b0}};
       rd_ptr = {AW{1'b0}};
       count  = {(AW+1){1'b0}};
       hwm    = 7'd0;
   end

   assign ready    = (count != DEPTH);
   assign avail    = (count != {(AW+1){1'b0}});
   assign head_key = key_q[rd_ptr];
   assign head_len = len_q[rd_ptr];
   // highest rule index that can hold a valid entry, including a write landing this cycle
   assign scan_lim = (tbl_wr && (tbl_idx > hwm)) ? tbl_idx : hwm;

   wire do_push = push && ready;
   wire do_pop  = pop && avail;

   always @(posedge clk) begin
       if (rst) begin
           wr_ptr <= {AW{1'b0}};
           rd_ptr <= {AW{1'b0}};
           count  <= {(AW+1){1'b0}};
           hwm    <= 7'd0;
       end else if (ce) begin
           if (do_push) begin
               key_q[wr_ptr] <= push_key;
               len_q[wr_ptr] <= push_len;
               wr_ptr        <= wr_ptr + 1'b1;
           end
           if (do_pop)
               rd_ptr <= rd_ptr + 1'b1;
           if (do_push && !do_pop)
               count <= count + 1'b1;
           else if (do_pop && !do_push)
               count <= count - 1'b1;
           if (tbl_wr)
               hwm <= scan_lim;
       end
   end
endmodule

module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
output reg  [6:0]  rsp_rule,
output wire        req_ready,
output wire [2:0]  req_pending,
output wire [6:0]  scan_limit,
output reg         rsp_cached,
output wire [2:0]  cache_occ,
output wire [15:0] cache_hits,
output wire [15:0] cache_evicts
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;
reg [6:0]  q_lim;

wire        rq_ready;
wire        rq_avail;
wire [63:0] rq_key;
wire [15:0] rq_len;
wire [2:0]  rq_count;
wire [6:0]  rq_hwm;
wire [6:0]  rq_scan_lim;
reg         q_hint;
wire        fc_hit;
wire [6:0]  fc_rule;
wire [3:0]  fc_vld;
wire [27:0] fc_rules;
// start the scan at the cached rule unless a rule write lands this cycle
wire [6:0]  scan_start = (fc_hit && !wr_en) ? fc_rule : 7'd0;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
q_lim      = 7'd0;
       q_hint     = 1'b0;
       rsp_cached = 1'b0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
wire last = (idx == q_lim);

lookup_req_queue #(.DEPTH(4), .AW(2)) u_req_q (
    .clk      (clk),
    .rst      (rst),
    .ce       (i_ce),
    .push     (req),
    .push_key (req_key),
    .push_len (req_len),
    .pop      (!busy),
    .tbl_wr   (wr_en && !busy),
    .tbl_idx  (wr_idx),
    .ready    (rq_ready),
    .avail    (rq_avail),
    .head_key (rq_key),
    .head_len (rq_len),
    .count    (rq_count),
    .hwm      (rq_hwm),
    .scan_lim (rq_scan_lim)
);

assign req_ready   = rq_ready;
assign req_pending = rq_count;
assign scan_limit  = rq_hwm;

flow_hint_cache #(.ENTRIES(4), .EW(2), .RW(7)) u_fcache (
   .clk       (clk),
   .rst       (rst),
   .ce        (i_ce),
   .inv_en    (wr_en && !busy),
   .inv_idx   (wr_idx),
   .lk_en     (!busy && rq_avail && !wr_en),
   .lk_key    (rq_key),
   .fill_en   (busy && hit),
   .fill_key  (q_key),
   .fill_rule (idx),
   .lk_hit    (fc_hit),
   .lk_rule   (fc_rule),
   .ent_vld   (fc_vld),
   .ent_rules (fc_rules),
   .occ       (cache_occ),
   .hit_cnt   (cache_hits),
   .evict_cnt (cache_evicts)
);

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
q_lim     <= 7'd0;
           q_hint     <= 1'b0;
           rsp_cached <= 1'b0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
if (rq_avail) begin
                    busy  <= 1'b1;
                   idx   <= scan_start;
timer <= {1'b0, rq_scan_lim} + 8'd1 - {1'b0, scan_start};
q_key <= rq_key;
q_len <= {48'd0, rq_len};
q_lim <= rq_scan_lim;
q_hint <= fc_hit && !wr_en;
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                   rsp_cached    <= q_hint;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                   rsp_cached    <= 1'b0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
endmodule

module wake_slot_recycle #(
  parameter RDEPTH = 4,
  parameter RAW    = 2,
  parameter COOL   = 3,
  parameter TW     = 2
) (
  input  wire                clk,
  input  wire                rst_n,
  input  wire                en,
  input  wire                starve,
  input  wire                free_vld,
  input  wire [4:0]          free_idx,
  output wire                free_rdy,
  output wire                ret_vld,
  output wire [31:0]         quar_mask,
  output wire [RAW:0]        cnt_o,
  output wire [RAW:0]        hwm_o,
  output wire [7:0]          rel_cnt_o,
  output wire [7:0]          blk_cnt_o,
  output wire [7:0]          early_cnt_o,
  output wire [RDEPTH*5-1:0] hist_o
);
  localparam [TW-1:0] COOL_V = COOL;

  // slots freed by issue, held until their cooldown expires
  reg [4:0]     r_idx [0:RDEPTH-1];
  reg [TW-1:0]  r_tmr [0:RDEPTH-1];
  // most recently released slots, newest in entry 0
  reg [4:0]     hist  [0:RDEPTH-1];
  reg [RAW-1:0] wr_ptr    = {RAW{1'b0}};
  reg [RAW-1:0] rd_ptr    = {RAW{1'b0}};
  reg [RAW:0]   r_cnt     = {(RAW+1){1'b0}};
  reg [RAW:0]   hwm       = {(RAW+1){1'b0}};
  reg [7:0]     rel_cnt   = 8'd0;
  reg [7:0]     blk_cnt   = 8'd0;
  reg [7:0]     early_cnt = 8'd0;

  integer i;
  initial for (i = 0; i < RDEPTH; i = i + 1) r_idx[i] = 5'd0;
  initial for (i = 0; i < RDEPTH; i = i + 1) r_tmr[i] = {TW{1'b0}};
  initial for (i = 0; i < RDEPTH; i = i + 1) hist[i]  = 5'd0;
  initial wr_ptr    = {RAW{1'b0}};
  initial rd_ptr    = {RAW{1'b0}};
  initial r_cnt     = {(RAW+1){1'b0}};
  initial hwm       = {(RAW+1){1'b0}};
  initial rel_cnt   = 8'd0;
  initial blk_cnt   = 8'd0;
  initial early_cnt = 8'd0;

  wire r_empty   = (r_cnt == {(RAW+1){1'b0}});
  wire r_full    = (r_cnt == RDEPTH);
  wire head_hot  = (r_tmr[rd_ptr] != {TW{1'b0}});
  // release the head once cooled, or early when the allocator is starved
  wire rel       = !r_empty && (!head_hot || starve);
  wire rel_early = rel && head_hot;
  wire push      = free_vld && free_rdy;
  wire [RAW-1:0] wr_nxt  = (wr_ptr == RDEPTH-1) ? {RAW{1'b0}} : wr_ptr + 1'b1;
  wire [RAW-1:0] rd_nxt  = (rd_ptr == RDEPTH-1) ? {RAW{1'b0}} : rd_ptr + 1'b1;
  wire [RAW:0]   cnt_nxt = r_cnt + {{RAW{1'b0}}, push} - {{RAW{1'b0}}, rel};

  // slots whose cooldown is still running
  reg [31:0]    qmask;
  reg [RAW-1:0] qp;
  integer q;
  always @(*) begin
      qmask = 32'd0;
      qp    = rd_ptr;
      for (q = 0; q < RDEPTH; q = q + 1) begin
          if ((q < r_cnt) && (r_tmr[qp] != {TW{1'b0}}))
              qmask = qmask | (32'd1 << r_idx[qp]);
          qp = (qp == RDEPTH-1) ? {RAW{1'b0}} : qp + 1'b1;
      end
  end

  // flattened release history
  reg [RDEPTH*5-1:0] hist_flat;
  integer h;
  always @(*) begin
      for (h = 0; h < RDEPTH; h = h + 1)
          hist_flat[h*5 +: 5] = hist[h];
  end

  assign free_rdy    = !r_full || rel;
  assign ret_vld     = rel;
  assign quar_mask   = qmask;
  assign cnt_o       = r_cnt;
  assign hwm_o       = hwm;
  assign rel_cnt_o   = rel_cnt;
  assign blk_cnt_o   = blk_cnt;
  assign early_cnt_o = early_cnt;
  assign hist_o      = hist_flat;

  integer j;
  always @(posedge clk) begin
      if (!rst_n) begin
          wr_ptr    <= {RAW{1'b0}};
          rd_ptr    <= {RAW{1'b0}};
          r_cnt     <= {(RAW+1){1'b0}};
          hwm       <= {(RAW+1){1'b0}};
          rel_cnt   <= 8'd0;
          blk_cnt   <= 8'd0;
          early_cnt <= 8'd0;
          for (j = 0; j < RDEPTH; j = j + 1) begin
              r_idx[j] <= 5'd0;
              r_tmr[j] <= {TW{1'b0}};
              hist[j]  <= 5'd0;
          end
      end else if (en) begin
          for (j = 0; j < RDEPTH; j = j + 1)
              if (r_tmr[j] != {TW{1'b0}})
                  r_tmr[j] <= r_tmr[j] - 1'b1;
          if (push) begin
              r_idx[wr_ptr] <= free_idx;
              r_tmr[wr_ptr] <= COOL_V;
              wr_ptr        <= wr_nxt;
          end
          if (rel) begin
              rd_ptr  <= rd_nxt;
              hist[0] <= r_idx[rd_ptr];
              for (j = 1; j < RDEPTH; j = j + 1)
                  hist[j] <= hist[j-1];
              if (rel_cnt != 8'hff)
                  rel_cnt <= rel_cnt + 8'd1;
          end
          if (rel_early && (early_cnt != 8'hff))
              early_cnt <= early_cnt + 8'd1;
          if (free_vld && !free_rdy && (blk_cnt != 8'hff))
              blk_cnt <= blk_cnt + 8'd1;
          r_cnt <= cnt_nxt;
          if (cnt_nxt > hwm)
              hwm <= cnt_nxt;
      end
  end
endmodule

module wake_alloc_q #(
   parameter DEPTH = 4,
   parameter AW    = 2,
   parameter SLOTS = 32
) (
   input  wire          clk,
   input  wire          rst_n,
   input  wire          en,
   input  wire          in_vld,
   input  wire [31:0]   in_deps,
   output wire          in_rdy,
   input  wire          slot_ret,
   input  wire [31:0]   slot_clr,
   output wire          out_vld,
   output wire [31:0]   out_deps,
   output wire [5:0]    credits_o,
   output wire [AW:0]   count_o,
   output wire [7:0]    stall_o
);
   reg [31:0]   q_deps [0:DEPTH-1];
   reg [AW-1:0] wr_ptr   = {AW{1'b0}};
   reg [AW-1:0] rd_ptr   = {AW{1'b0}};
   reg [AW:0]   q_cnt    = {(AW+1){1'b0}};
   reg [5:0]    credits  = SLOTS;
   reg          stg_v    = 1'b0;
   reg [31:0]   stg_deps = 32'd0;
   reg [7:0]    stall    = 8'd0;

   integer i;
   initial for (i = 0; i < DEPTH; i = i + 1) q_deps[i] = 32'd0;
   initial wr_ptr   = {AW{1'b0}};
   initial rd_ptr   = {AW{1'b0}};
   initial q_cnt    = {(AW+1){1'b0}};
   initial credits  = SLOTS;
   initial stg_v    = 1'b0;
   initial stg_deps = 32'd0;
   initial stall    = 8'd0;

   wire q_empty = (q_cnt == {(AW+1){1'b0}});
   wire q_full  = (q_cnt == DEPTH);
   wire no_cred = (credits == 6'd0);
   wire push    = in_vld && !q_full;
   wire pop     = !q_empty && !no_cred;
   wire [31:0]   head_deps = q_deps[rd_ptr] & ~slot_clr;
   wire [AW-1:0] wr_nxt = (wr_ptr == DEPTH-1) ? {AW{1'b0}} : wr_ptr + 1'b1;
   wire [AW-1:0] rd_nxt = (rd_ptr == DEPTH-1) ? {AW{1'b0}} : rd_ptr + 1'b1;

   assign in_rdy    = !q_full;
   assign out_vld   = stg_v;
   assign out_deps  = stg_deps;
   assign credits_o = credits;
   assign count_o   = q_cnt;
   assign stall_o   = stall;

   integer j;
   always @(posedge clk) begin
       if (!rst_n) begin
           wr_ptr   <= {AW{1'b0}};
           rd_ptr   <= {AW{1'b0}};
           q_cnt    <= {(AW+1){1'b0}};
           credits  <= SLOTS;
           stg_v    <= 1'b0;
           stg_deps <= 32'd0;
           stall    <= 8'd0;
           for (j = 0; j < DEPTH; j = j + 1)
               q_deps[j] <= 32'd0;
       end else if (en) begin
           for (j = 0; j < DEPTH; j = j + 1)
               q_deps[j] <= q_deps[j] & ~slot_clr;
           if (push) begin
               q_deps[wr_ptr] <= in_deps & ~slot_clr;
               wr_ptr <= wr_nxt;
           end
           if (pop)
               rd_ptr <= rd_nxt;
           q_cnt    <= q_cnt + {{AW{1'b0}}, push} - {{AW{1'b0}}, pop};
           credits  <= credits + {5'd0, slot_ret} - {5'd0, pop};
           stg_v    <= pop;
           stg_deps <= pop ? head_deps : 32'd0;
           if (!q_empty && no_cred && (stall != 8'hff))
               stall <= stall + 8'd1;
       end
   end
endmodule

module pico_wakeup (
    input wire        clk,
    input wire        rst_n,
    input wire        en,
    input wire        alloc,
    input wire [31:0] alloc_deps,
    input wire        issue,
   input wire [4:0]  issue_idx,
   output wire       alloc_rdy,
   output wire       alloc_stg_v,
   output wire [5:0] alloc_credits,
   output wire [2:0] alloc_q_cnt,
  output wire [7:0] alloc_stall,
  output wire       issue_rdy,
  output wire [2:0] recyc_cnt,
  output wire [2:0] recyc_hwm,
  output wire [31:0] recyc_quar,
  output wire [7:0] recyc_rel,
  output wire [7:0] recyc_blk,
  output wire [7:0] recyc_early,
  output wire [19:0] recyc_hist,
  output wire [7:0] alloc_fb_o
);
    reg [31:0]   valid    = 32'd0;
    reg [1023:0] dep_flat = 1024'd0;
    reg [31:0]   pend     = 32'd0;
    reg [63:0]   occ      = 64'd0;
    reg [63:0]   wake_cnt = 64'd0;
   reg [7:0]    alloc_fb = 8'd0;

    initial valid    = 32'd0;
    initial dep_flat = 1024'd0;
    initial pend     = 32'd0;
    initial occ      = 64'd0;
    initial wake_cnt = 64'd0;
   initial alloc_fb = 8'd0;

    wire full = &valid;

    // lowest free index
   reg [4:0] fb_idx;
    integer a;
    always @(*) begin
       fb_idx = 5'd0;
        for (a = 31; a >= 0; a = a - 1)
           if (!valid[a]) fb_idx = a[4:0];
    end

   // prefer a free slot that is not still cooling down after its issue
   wire [31:0] avail_cool = ~valid & ~recyc_quar;
   reg [4:0] pref_idx;
   integer p;
   always @(*) begin
       pref_idx = 5'd0;
       for (p = 31; p >= 0; p = p - 1)
           if (avail_cool[p]) pref_idx = p[4:0];
   end
   wire [4:0] free_idx = (|avail_cool) ? pref_idx : fb_idx;

    // popcount of valid (status helper)
    reg [63:0] valid_cnt;
    integer b;
    always @(*) begin
        valid_cnt = 64'd0;
        for (b = 0; b < 32; b = b + 1)
            valid_cnt = valid_cnt + {63'd0, valid[b]};
    end

    // per-row OR of dependency matrix (status helper)
    reg [31:0] dep_or;
    integer c;
    always @(*) begin
        for (c = 0; c < 32; c = c + 1)
            dep_or[c] = |dep_flat[c*32 +: 32];
    end

   wire [31:0] aq_deps;
   wire alloc_fire = alloc_stg_v;
   wire issue_req  = issue && valid[issue_idx] && !pend[issue_idx];
   wire issue_fire = issue_req && issue_rdy;
    wire [31:0] clr_mask   = issue_fire ? (32'd1 << issue_idx) : 32'd0;
    wire [31:0] alloc_mask = alloc_fire ? (32'd1 << free_idx)  : 32'd0;
   wire [31:0] new_deps   = aq_deps & valid & ~clr_mask;
  wire rc_ret;
  wire aq_starve = (alloc_credits == 6'd0) && (alloc_q_cnt != 3'd0);

   // allocation request queue with slot credits
   wake_alloc_q #(.DEPTH(4), .AW(2), .SLOTS(32)) u_aq (
       .clk(clk),
       .rst_n(rst_n),
       .en(en),
       .in_vld(alloc),
       .in_deps(alloc_deps),
       .in_rdy(alloc_rdy),
      .slot_ret(rc_ret),
       .slot_clr(clr_mask),
       .out_vld(alloc_stg_v),
       .out_deps(aq_deps),
       .credits_o(alloc_credits),
       .count_o(alloc_q_cnt),
       .stall_o(alloc_stall)
   );

  // slot recycle: an issued slot cools down before its credit returns
  wake_slot_recycle #(.RDEPTH(4), .RAW(2), .COOL(3), .TW(2)) u_rc (
      .clk(clk),
      .rst_n(rst_n),
      .en(en),
      .starve(aq_starve),
      .free_vld(issue_req),
      .free_idx(issue_idx),
      .free_rdy(issue_rdy),
      .ret_vld(rc_ret),
      .quar_mask(recyc_quar),
      .cnt_o(recyc_cnt),
      .hwm_o(recyc_hwm),
      .rel_cnt_o(recyc_rel),
      .blk_cnt_o(recyc_blk),
      .early_cnt_o(recyc_early),
      .hist_o(recyc_hist)
  );

  assign alloc_fb_o = alloc_fb;

    reg [1023:0] dep_nxt;
    reg [31:0]   pend_nxt;
    reg [63:0]   woke;
    integer k;
    always @(*) begin
        woke = 64'd0;
        dep_nxt = dep_flat;
        pend_nxt = pend;
        for (k = 0; k < 32; k = k + 1) begin
            if (alloc_mask[k]) begin
                dep_nxt[k*32 +: 32] = new_deps;
                pend_nxt[k] = |new_deps;
            end else if (clr_mask[k]) begin
                dep_nxt[k*32 +: 32] = 32'd0;
                pend_nxt[k] = 1'b0;
            end else begin
                dep_nxt[k*32 +: 32] = dep_flat[k*32 +: 32] & ~clr_mask;
                pend_nxt[k] = pend[k] && (|(dep_flat[k*32 +: 32] & ~clr_mask));
                if (pend[k] && !pend_nxt[k])
                    woke = woke + 64'd1;
            end
        end
    end

    wire [31:0] valid_nxt = (valid | alloc_mask) & ~clr_mask;

    always @(posedge clk) begin
        if (!rst_n) begin
            valid    <= 32'd0;
            dep_flat <= 1024'd0;
            pend     <= 32'd0;
            occ      <= 64'd0;
            wake_cnt <= 64'd0;
           alloc_fb <= 8'd0;
        end else if (en) begin
            valid    <= valid_nxt;
            dep_flat <= dep_nxt;
            pend     <= pend_nxt;
            wake_cnt <= wake_cnt + woke;
           if (alloc_fire && !(|avail_cool) && (alloc_fb != 8'hff))
               alloc_fb <= alloc_fb + 8'd1;
            if (alloc_fire && !issue_fire)
                occ <= occ + 64'd1;
            else if (issue_fire && !alloc_fire)
                occ <= occ - 64'd1;
        end
    end

    always @(posedge clk)
        if (|valid) assert (occ <= 64'd32);
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5,
    parameter DEPTH = 4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b,
    output wire [$clog2(DEPTH):0] queued,
    output wire         head_cached
);
    localparam NBF = NCOEF / 2;
    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W = ADDR_W + 1;
    localparam [ADDR_W-1:0] LAST_SLOT = DEPTH - 1;

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    reg [W-1:0] q_a [0:DEPTH-1];
    reg [W-1:0] q_b [0:DEPTH-1];
    reg [W-1:0] q_w [0:DEPTH-1];
    reg [W-1:0] q_lat [0:DEPTH-1];
    reg [PTR_W-1:0] q_wr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] q_rd = {PTR_W{1'b0}};
    reg head_valid = 1'b0;
    integer init_slot;
    wire [ADDR_W-1:0] head_slot = q_rd[ADDR_W-1:0];
    wire q_empty = (q_wr == q_rd);
    wire q_full = (q_wr[ADDR_W] != q_rd[ADDR_W]) &&
                  (q_wr[ADDR_W-1:0] == q_rd[ADDR_W-1:0]);
    initial begin
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            q_a[init_slot] = 16'd0;
            q_b[init_slot] = 16'd0;
            q_w[init_slot] = 16'd0;
            q_lat[init_slot] = 16'd0;
        end
    end
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end
    assign queued = (q_wr[ADDR_W] == q_rd[ADDR_W]) ?
        ({1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]}) :
        (DEPTH + {1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]});
    assign head_cached = head_valid;

    assign in_ready = !q_full;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);
    wire cache_read = ce && !head_valid && !q_empty;
    wire bypass_head = ce && accept && q_empty;
    wire start = ce && head_valid && !busy && !out_valid;
    wire retire = busy && ce && last;

    wire [31:0] prod = w_r * b_r;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];
    always @(posedge clk) begin
        if (accept) begin
            q_a[q_wr[ADDR_W-1:0]] <= in_a;
            q_b[q_wr[ADDR_W-1:0]] <= in_b;
            q_w[q_wr[ADDR_W-1:0]] <= in_w;
            q_lat[q_wr[ADDR_W-1:0]] <= lat_eff;
            if (q_wr[ADDR_W-1:0] == LAST_SLOT)
                q_wr <= {!q_wr[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_wr <= q_wr + 1'b1;
        end
        if (retire) begin
            if (q_rd[ADDR_W-1:0] == LAST_SLOT)
                q_rd <= {!q_rd[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_rd <= q_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (cache_read) begin
            a_r <= q_a[head_slot];
            b_r <= q_b[head_slot];
            w_r <= q_w[head_slot];
            lat_q <= q_lat[head_slot];
            head_valid <= 1'b1;
        end else if (bypass_head) begin
            a_r <= in_a;
            b_r <= in_b;
            w_r <= in_w;
            lat_q <= lat_eff;
            head_valid <= 1'b1;
        end else if (retire) begin
            head_valid <= 1'b0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load_cfg) lat_cfg <= cfg_lat;
        if (start) begin
            cd    <= lat_q;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
        end else if (busy && ce) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - 16'd1;
                phase <= phase + 16'd1;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted,
    output reg [31:0] debug_status
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;
    reg [31:0] dbg_cycles, dbg_input_stalls, dbg_output_stalls;
    reg [31:0] dbg_frames, dbg_cfg_writes;
    reg [15:0] dbg_stall_run, dbg_stall_max, dbg_idle_age;
    reg [7:0] dbg_high_water;
    reg [3:0] dbg_flags;
    reg dbg_enable;
    wire dbg_input_blocked = i_valid && !i_ready;
    wire dbg_output_blocked = o_valid && !o_ready;
    wire dbg_clear = cfg_we && (cfg_addr == 4'd15) && cfg_data[0];
    initial begin
        dbg_cycles = 32'd0;
        dbg_input_stalls = 32'd0;
        dbg_output_stalls = 32'd0;
        dbg_frames = 32'd0;
        dbg_cfg_writes = 32'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_max = 16'd0;
        dbg_idle_age = 16'd0;
        dbg_high_water = 8'd0;
        dbg_flags = 4'd0;
        dbg_enable = 1'b1;
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (rst) begin
            dbg_cycles <= 32'd0;
            dbg_input_stalls <= 32'd0;
            dbg_output_stalls <= 32'd0;
            dbg_frames <= 32'd0;
            dbg_cfg_writes <= 32'd0;
            dbg_stall_run <= 16'd0;
            dbg_stall_max <= 16'd0;
            dbg_idle_age <= 16'd0;
            dbg_high_water <= 8'd0;
            dbg_flags <= 4'd0;
            dbg_enable <= 1'b1;
            debug_status <= 32'd0;
        end else begin
            if (cfg_we && cfg_addr == 4'd9)
                dbg_enable <= cfg_data[0];
            if (dbg_clear) begin
                dbg_cycles <= 32'd0;
                dbg_input_stalls <= 32'd0;
                dbg_output_stalls <= 32'd0;
                dbg_frames <= 32'd0;
                dbg_cfg_writes <= 32'd0;
                dbg_stall_run <= 16'd0;
                dbg_stall_max <= 16'd0;
                dbg_idle_age <= 16'd0;
                dbg_high_water <= 8'd0;
                dbg_flags <= 4'd0;
            end else if (dbg_enable) begin
                if (!(&dbg_cycles))
                    dbg_cycles <= dbg_cycles + 32'd1;
                if (dbg_input_blocked && !(&dbg_input_stalls))
                    dbg_input_stalls <= dbg_input_stalls + 32'd1;
                if (dbg_output_blocked && !(&dbg_output_stalls))
                    dbg_output_stalls <= dbg_output_stalls + 32'd1;
                if (out_fire && o_last && !(&dbg_frames))
                    dbg_frames <= dbg_frames + 32'd1;
                if (cfg_we && cfg_addr <= 4'd8 && !(&dbg_cfg_writes))
                    dbg_cfg_writes <= dbg_cfg_writes + 32'd1;
                if (ingress_level > dbg_high_water)
                    dbg_high_water <= (ingress_level > 255) ? 8'hff : ingress_level;
                if (dbg_output_blocked) begin
                    if (!(&dbg_stall_run))
                        dbg_stall_run <= dbg_stall_run + 16'd1;
                    if (dbg_stall_run >= dbg_stall_max && !(&dbg_stall_run))
                        dbg_stall_max <= dbg_stall_run + 16'd1;
                end else
                    dbg_stall_run <= 16'd0;
                if ((ingress_valid || o_valid) && !out_fire) begin
                    if (!(&dbg_idle_age))
                        dbg_idle_age <= dbg_idle_age + 16'd1;
                    if (&dbg_idle_age)
                        dbg_flags[2] <= 1'b1;
                end else
                    dbg_idle_age <= 16'd0;
                if (dbg_input_blocked)
                    dbg_flags[0] <= 1'b1;
                if (dbg_output_blocked)
                    dbg_flags[1] <= 1'b1;
                if (cfg_we && armed)
                    dbg_flags[3] <= 1'b1;
            end
            case (cfg_addr)
                4'd9: debug_status <= {31'd0, dbg_enable};
                4'd10: debug_status <= dbg_cycles;
                4'd11: debug_status <= dbg_input_stalls;
                4'd12: debug_status <= dbg_output_stalls;
                4'd13: debug_status <= dbg_frames;
                4'd14: debug_status <= {dbg_stall_max, dbg_stall_run};
                4'd15: debug_status <= {dbg_high_water, dbg_flags, 4'd0, dbg_idle_age};
                default: debug_status <= dbg_cfg_writes;
            endcase
        end
    end

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
endmodule

module branch_resolve_unit #(
    parameter XLEN = 64,
    parameter INST_BYTES = 4
) (
    input  wire            clk,
    input  wire            rst_n,
    // resolved branch packet from execute (valid/ready)
    input  wire            br_valid,
    output wire            br_ready,
    input  wire [XLEN-1:0] br_pc,
    input  wire            br_pred_taken,
    input  wire [XLEN-1:0] br_pred_target,
    input  wire            br_taken,
    input  wire [XLEN-1:0] br_target,
    // redirect / flush request to fetch (valid/ready)
    output reg             redir_valid,
    input  wire            redir_ready,
    output reg  [XLEN-1:0] redir_addr,
    output wire            flush,
    // monitor window control
    input  wire            mon_open,
    input  wire            mon_close
,
    output wire [XLEN-1:0] mispred_cnt_o,
    output wire [XLEN-1:0] redir_cnt_o
);
    localparam [XLEN-1:0] ONE  = 1;
    localparam [XLEN-1:0] STEP = INST_BYTES;

    reg [XLEN-1:0] pred_target_q = 0;
    reg            pred_taken_q  = 1'b0;
    reg            act_taken_q   = 1'b0;
    reg [XLEN-1:0] mispred_cnt   = 0;
    reg [XLEN-1:0] correct_cnt   = 0;
    reg [XLEN-1:0] redir_cnt     = 0;
    reg            win           = 1'b0;
    reg            pv            = 1'b0;
    initial begin redir_valid = 1'b0; redir_addr = 0; end

    assign br_ready = !redir_valid;
    wire accept   = br_valid && br_ready;
    wire send     = redir_valid && redir_ready;
    assign flush  = send;

    wire mispredict = (br_pred_taken != br_taken) ||
                      (br_taken && (br_pred_target != br_target));
    wire [XLEN-1:0] fix_addr = br_taken ? br_target : (br_pc + STEP);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pred_target_q <= 0;
            pred_taken_q  <= 1'b0;
            act_taken_q   <= 1'b0;
            mispred_cnt   <= 0;
            correct_cnt   <= 0;
            redir_cnt     <= 0;
            redir_valid   <= 1'b0;
            redir_addr    <= 0;
        end else begin
            if (accept) begin
                pred_target_q <= br_pred_target;
                pred_taken_q  <= br_pred_taken;
                act_taken_q   <= br_taken;
                if (mispredict) begin
                    mispred_cnt <= mispred_cnt + ONE;
                    redir_valid <= 1'b1;
                    redir_addr  <= fix_addr;
                end else begin
                    correct_cnt <= correct_cnt + ONE;
                end
            end else if (send) begin
                redir_valid <= 1'b0;
                redir_cnt   <= redir_cnt + ONE;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            win <= 1'b0;
        end else begin
            if (mon_open)       win <= 1'b1;
            else if (mon_close) win <= 1'b0;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && win && $rose(redir_valid))
            assert (mispred_cnt == redir_cnt + ONE);
    assign mispred_cnt_o = mispred_cnt;
    assign redir_cnt_o = redir_cnt;
endmodule

module frac_xmul_cmp #(
    parameter W = 32
) (
    input  wire           clk,
    input  wire           rst,
    // input channel: op=0 loads two fractions a/b and c/d, op=1 takes the reciprocal of both held fractions
    input  wire           in_valid,
    output wire           in_ready,
    input  wire           in_op,
    input  wire [W-1:0]   in_a,
    input  wire [W-1:0]   in_b,
    input  wire [W-1:0]   in_c,
    input  wire [W-1:0]   in_d,
    // output channel: registered cross products and relation result
    output reg            out_valid,
    input  wire           out_ready,
    output reg [2*W-1:0]  p_ad,
    output reg [2*W-1:0]  p_cb,
    output reg            lt_q,
    output reg            gt_q,
    output wire           eq_q
);
    initial begin
        out_valid = 1'b0;
        p_ad      = {2*W{1'b0}};
        p_cb      = {2*W{1'b0}};
        lt_q      = 1'b0;
        gt_q      = 1'b0;
    end

    // cross multiply: a/b vs c/d  <=>  a*d vs c*b (no division)
    wire [2*W-1:0] m_ad = in_a * in_d;
    wire [2*W-1:0] m_cb = in_c * in_b;

    assign in_ready = !out_valid || out_ready;
    wire in_fire  = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    assign eq_q = !lt_q && !gt_q;

    always @(posedge clk) begin
        if (rst) begin
            out_valid <= 1'b0;
            p_ad      <= {2*W{1'b0}};
            p_cb      <= {2*W{1'b0}};
            lt_q      <= 1'b0;
            gt_q      <= 1'b0;
        end else if (in_fire) begin
            out_valid <= 1'b1;
            if (in_op) begin
                // reciprocal of both fractions: b/a vs d/c -> b*c vs d*a, products and relation swap
                p_ad <= p_cb;
                p_cb <= p_ad;
                lt_q <= gt_q;
                gt_q <= lt_q;
            end else begin
                p_ad <= m_ad;
                p_cb <= m_cb;
                lt_q <= (m_ad < m_cb);
                gt_q <= (m_ad > m_cb);
            end
        end else if (out_fire) begin
            out_valid <= 1'b0;
        end
    end

    // Absence: the 'greater' result flag and products that are not greater never coexist
    wire prod_le = (p_ad <= p_cb);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv)
            assert (!($past(gt_q) && $past(prod_le)));
endmodule

module rational_branch_unit #(
    parameter DEPTH = 4
) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire in_op,
    input wire [31:0] in_a, in_b, in_c, in_d,
    input wire [63:0] br_pc,
    input wire br_pred_taken,
    input wire [63:0] br_pred_target, br_target,
    input wire redir_ready,
    input wire mon_open, mon_close,
    output wire redir_valid,
    output wire [63:0] redir_addr,
    output wire flush,
    output wire [63:0] a_mispred_cnt, a_redir_cnt,
    output wire a_br_ready,
    output wire b_out_valid, b_out_ready,
    output wire [63:0] b_p_ad, b_p_cb,
    output wire b_lt_q, b_gt_q, b_eq_q,
    output reg [$clog2(DEPTH+1)-1:0] q_count,
    output wire [$clog2(DEPTH+1)-1:0] unissued_count,
    output wire head_valid, retire,
    output wire [63:0] head_pc, head_pred_target, head_target,
    output wire head_pred_taken, head_taken,
    output wire [63:0] head_p_ad, head_p_cb
);
    localparam COUNT_W = $clog2(DEPTH+1);
    localparam [63:0] STEP = 64'd4;
    wire rst = !rst_n;
    wire issue = in_valid && in_ready;
    reg [63:0] meta_pc, meta_pred_target, meta_target;
    reg meta_pred_taken;
    reg [63:0] q_pc [0:DEPTH-1];
    reg [63:0] q_pred_target [0:DEPTH-1];
    reg [63:0] q_target [0:DEPTH-1];
    reg [63:0] q_p_ad [0:DEPTH-1];
    reg [63:0] q_p_cb [0:DEPTH-1];
    reg q_pred_taken [0:DEPTH-1];
    reg q_taken [0:DEPTH-1];

    assign head_valid = (q_count != 0);
    assign head_pc = q_pc[0];
    assign head_pred_target = q_pred_target[0];
    assign head_target = q_target[0];
    assign head_pred_taken = q_pred_taken[0];
    assign head_taken = q_taken[0];
    assign head_p_ad = q_p_ad[0];
    assign head_p_cb = q_p_cb[0];
    wire head_mispredict = (head_pred_taken != head_taken) ||
                          (head_taken && (head_pred_target != head_target));
    wire [63:0] head_fix_addr = head_taken ? head_target : head_pc + STEP;
    wire a_br_valid = head_valid && !redir_valid;
    wire branch_accept = a_br_valid && a_br_ready;
    assign retire = head_valid &&
                    ((branch_accept && !head_mispredict) || flush);
    assign b_out_ready = (q_count < DEPTH);
    wire enqueue = b_out_valid && b_out_ready;
    wire [COUNT_W-1:0] enqueue_index = q_count - {{(COUNT_W-1){1'b0}}, retire};
    assign unissued_count = q_count - {{(COUNT_W-1){1'b0}}, redir_valid};

    frac_xmul_cmp #(.W(32)) compare (
        .clk(clk), .rst(rst), .in_valid(in_valid), .in_ready(in_ready),
        .in_op(in_op), .in_a(in_a), .in_b(in_b), .in_c(in_c), .in_d(in_d),
        .out_valid(b_out_valid), .out_ready(b_out_ready),
        .p_ad(b_p_ad), .p_cb(b_p_cb),
        .lt_q(b_lt_q), .gt_q(b_gt_q), .eq_q(b_eq_q)
    );
    branch_resolve_unit #(.XLEN(64), .INST_BYTES(4)) resolve (
        .clk(clk), .rst_n(rst_n), .br_valid(a_br_valid), .br_ready(a_br_ready),
        .br_pc(head_pc), .br_pred_taken(head_pred_taken),
        .br_pred_target(head_pred_target), .br_taken(head_taken),
        .br_target(head_target), .redir_valid(redir_valid),
        .redir_ready(redir_ready), .redir_addr(redir_addr), .flush(flush),
        .mon_open(mon_open), .mon_close(mon_close),
        .mispred_cnt_o(a_mispred_cnt), .redir_cnt_o(a_redir_cnt)
    );

    // Metadata advances on exactly the comparator's input handshake.
    initial begin
        meta_pc = 0;
        meta_pred_target = 0;
        meta_target = 0;
        meta_pred_taken = 1'b0;
    end
    always @(posedge clk) begin
        if (rst) begin
            meta_pc <= 0;
            meta_pred_target <= 0;
            meta_target <= 0;
            meta_pred_taken <= 1'b0;
        end else if (issue) begin
            meta_pc <= br_pc;
            meta_pred_target <= br_pred_target;
            meta_target <= br_target;
            meta_pred_taken <= br_pred_taken;
        end
    end

    // Keep the oldest completion available until its redirect has been sent.
    integer init_i;
    initial begin
        q_count = 0;
        for (init_i = 0; init_i < DEPTH; init_i = init_i + 1) begin
            q_pc[init_i] = 0;
            q_pred_target[init_i] = 0;
            q_target[init_i] = 0;
            q_p_ad[init_i] = 0;
            q_p_cb[init_i] = 0;
            q_pred_taken[init_i] = 1'b0;
            q_taken[init_i] = 1'b0;
        end
    end
    integer i;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            q_count <= 0;
            for (i = 0; i < DEPTH; i = i + 1) begin
                q_pc[i] <= 0;
                q_pred_target[i] <= 0;
                q_target[i] <= 0;
                q_p_ad[i] <= 0;
                q_p_cb[i] <= 0;
                q_pred_taken[i] <= 1'b0;
                q_taken[i] <= 1'b0;
            end
        end else begin
            if (retire) begin
                for (i = 0; i < DEPTH-1; i = i + 1) begin
                    q_pc[i] <= q_pc[i+1];
                    q_pred_target[i] <= q_pred_target[i+1];
                    q_target[i] <= q_target[i+1];
                    q_p_ad[i] <= q_p_ad[i+1];
                    q_p_cb[i] <= q_p_cb[i+1];
                    q_pred_taken[i] <= q_pred_taken[i+1];
                    q_taken[i] <= q_taken[i+1];
                end
            end
            if (enqueue) begin
                q_pc[enqueue_index] <= meta_pc;
                q_pred_target[enqueue_index] <= meta_pred_target;
                q_target[enqueue_index] <= meta_target;
                q_p_ad[enqueue_index] <= b_p_ad;
                q_p_cb[enqueue_index] <= b_p_cb;
                q_pred_taken[enqueue_index] <= meta_pred_taken;
                q_taken[enqueue_index] <= b_lt_q;
            end
            case ({enqueue, retire})
                2'b10: q_count <= q_count + 1'b1;
                2'b01: q_count <= q_count - 1'b1;
                default: q_count <= q_count;
            endcase
        end
    end

    wire comparison_taken = (head_p_ad < head_p_cb);
    wire comparison_mispredict = (head_pred_taken != comparison_taken) ||
                                (comparison_taken && (head_pred_target != head_target));
    wire [63:0] comparison_fix_addr =
        comparison_taken ? head_target : head_pc + STEP;
    always @(posedge clk)
        if (retire)
            assert ((redir_valid == comparison_mispredict) &&
                    (!redir_valid || (redir_addr == comparison_fix_addr)));
endmodule

module ckpt_regfile #(
    parameter W = 32,
    parameter NREG = 4,
    parameter NCKPT = 4,
    parameter [31:0] TIMEOUT = 32'd6,
    parameter SW = $clog2(NCKPT),
    parameter RW = $clog2(NREG),
    parameter TRACE_DEPTH = 4,
    parameter QW = $clog2(TRACE_DEPTH),
    parameter BW = $clog2(TIMEOUT + 32'd1)
) (
    input wire clk,
    input wire rst,
    input wire step,
    input wire branch,
    input wire resolve,
    input wire mispredict,
    input wire [SW-1:0] rsv_id,
    input wire wr_en,
    input wire [RW-1:0] wr_addr,
    input wire [W-1:0] wr_data,
    output wire [NCKPT-1:0] o_mask,
    output wire [W-1:0] o_acc0,
    output wire o_busy,
    output wire o_branch_ready,
    output wire o_trace_valid,
    output wire o_trace_emit,
    output wire [W-1:0] o_trace_data,
    output wire [SW-1:0] o_trace_slot,
    output wire [BW-1:0] o_trace_budget,
    output wire [QW:0] o_trace_pending
);
    // active accumulator register file and checkpoint shadow copies
    reg [NREG*W-1:0] regs_q;
    reg [NCKPT*NREG*W-1:0] shadow_q;
    reg [NCKPT-1:0] ckpt_mask;
    reg [31:0] n_live;
    reg [31:0] wd;
    reg armed;
    reg [QW:0] trace_rptr, trace_wptr;
    reg [W-1:0] trace_data [0:TRACE_DEPTH-1];
    reg [SW-1:0] trace_slot [0:TRACE_DEPTH-1];
    reg [BW-1:0] trace_budget [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_out_data;
    reg [SW-1:0] trace_out_slot;
    reg [BW-1:0] trace_out_budget;
    reg trace_out_valid;
    integer ti;
    wire [QW:0] trace_count = trace_wptr - trace_rptr;
    wire [QW:0] trace_pending = trace_count + trace_out_valid;
    wire trace_empty = (trace_wptr == trace_rptr);
    wire trace_full = (trace_wptr[QW] != trace_rptr[QW]) &&
                      (trace_wptr[QW-1:0] == trace_rptr[QW-1:0]);
    wire trace_emit = step && !wr_en && trace_out_valid;
    wire trace_pop = step && !trace_empty &&
                     (!trace_out_valid || trace_emit);

    initial begin
        regs_q = {NREG*W{1'b0}};
        shadow_q = {NCKPT*NREG*W{1'b0}};
        ckpt_mask = {NCKPT{1'b0}};
        n_live = 32'd0;
        wd = 32'd0;
        armed = 1'b1;
        trace_rptr = {(QW+1){1'b0}};
        trace_wptr = {(QW+1){1'b0}};
        trace_out_data = {W{1'b0}};
        trace_out_slot = {SW{1'b0}};
        trace_out_budget = {BW{1'b0}};
        trace_out_valid = 1'b0;
        for (ti = 0; ti < TRACE_DEPTH; ti = ti + 1) begin
            trace_data[ti] = {W{1'b0}};
            trace_slot[ti] = {SW{1'b0}};
            trace_budget[ti] = {BW{1'b0}};
        end
    end

    // lowest free checkpoint slot
    reg [SW-1:0] free_slot;
    integer k;
    always @(*) begin
        free_slot = {SW{1'b0}};
        for (k = NCKPT-1; k >= 0; k = k - 1)
            if (!ckpt_mask[k]) free_slot = k;
    end

    wire live        = (n_live != 32'd0);
    wire timeout     = live && (wd == 32'd1);
    wire do_rollback = mispredict && ckpt_mask[rsv_id];
    wire do_free     = resolve && ckpt_mask[rsv_id];
    wire do_alloc    = branch && o_branch_ready;
    wire trace_push = step && !timeout && !do_rollback && do_alloc;
    assign o_branch_ready = step && !timeout && !do_rollback &&
                            (n_live != NCKPT) && !trace_full &&
                            (live || (trace_empty && !trace_out_valid));

    reg [NCKPT-1:0] mask_nxt;
    reg [31:0] live_nxt;
    always @(*) begin
        mask_nxt = ckpt_mask;
        live_nxt = n_live;
        if (do_free) begin
            mask_nxt[rsv_id] = 1'b0;
            live_nxt = live_nxt - 32'd1;
        end
        if (do_alloc) begin
            mask_nxt[free_slot] = 1'b1;
            live_nxt = live_nxt + 32'd1;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            regs_q <= {NREG*W{1'b0}};
            ckpt_mask <= {NCKPT{1'b0}};
            n_live <= 32'd0;
            wd <= 32'd0;
        end else if (step) begin
            if (timeout) begin
                // deadline reached: force-commit all outstanding checkpoints
                ckpt_mask <= {NCKPT{1'b0}};
                n_live <= 32'd0;
                wd <= 32'd0;
            end else if (do_rollback) begin
                regs_q <= shadow_q[rsv_id*NREG*W +: NREG*W];
                ckpt_mask <= {NCKPT{1'b0}};
                n_live <= 32'd0;
                wd <= 32'd0;
                armed <= 1'b0;
            end else begin
                if (do_alloc)
                    shadow_q[free_slot*NREG*W +: NREG*W] <= regs_q;
                if (wr_en)
                    regs_q[wr_addr*W +: W] <= wr_data;
                ckpt_mask <= mask_nxt;
                n_live <= live_nxt;
                if (live_nxt == 32'd0)
                    wd <= 32'd0;
                else if (!live)
                    wd <= TIMEOUT;
                else
                    wd <= wd - 32'd1;
            end
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            trace_rptr <= {(QW+1){1'b0}};
            trace_wptr <= {(QW+1){1'b0}};
            trace_out_data <= {W{1'b0}};
            trace_out_slot <= {SW{1'b0}};
            trace_out_budget <= {BW{1'b0}};
            trace_out_valid <= 1'b0;
            for (ti = 0; ti < TRACE_DEPTH; ti = ti + 1) begin
                trace_data[ti] <= {W{1'b0}};
                trace_slot[ti] <= {SW{1'b0}};
                trace_budget[ti] <= {BW{1'b0}};
            end
        end else begin
            if (trace_push) begin
                trace_data[trace_wptr[QW-1:0]] <= regs_q[W-1:0];
                trace_slot[trace_wptr[QW-1:0]] <= free_slot;
                trace_budget[trace_wptr[QW-1:0]] <= live ? wd - 32'd1 : TIMEOUT;
                trace_wptr <= trace_wptr + 1'b1;
            end
            if (trace_pop) begin
                trace_out_data <= trace_data[trace_rptr[QW-1:0]];
                trace_out_slot <= trace_slot[trace_rptr[QW-1:0]];
                trace_out_budget <= trace_budget[trace_rptr[QW-1:0]];
                trace_out_valid <= 1'b1;
                trace_rptr <= trace_rptr + 1'b1;
            end else if (trace_emit)
                trace_out_valid <= 1'b0;
        end
    end

    assign o_mask = ckpt_mask;
    assign o_acc0 = regs_q[W-1:0];
    assign o_busy = live;
    assign o_trace_valid = trace_out_valid;
    assign o_trace_emit = trace_emit;
    assign o_trace_data = trace_out_data;
    assign o_trace_slot = trace_out_slot;
    assign o_trace_budget = trace_out_budget;
    assign o_trace_pending = trace_pending;

    // before the first rollback: an outstanding checkpoint never sees an expired deadline
    always @(*) assert (!armed || ckpt_mask == {NCKPT{1'b0}} || wd != 32'd0);
    always @(*) assert (!o_trace_emit ||
        (o_trace_budget != {BW{1'b0}} && wd <= o_trace_budget));
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag,
    output wire [31:0] debug_status
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;

    assign in_ready  = (state == S_ACCUM);
    assign out_valid = (state == S_DONE);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready;

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
            if (in_mag < min1) begin
                min2    <= min1;
                min1    <= in_mag;
                min_idx <= count;
            end else if (in_mag < min2) begin
                min2 <= in_mag;
            end
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = min1;
    assign out_min2 = min2;
    assign out_idx  = min_idx;
    assign out_sign = sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;
    reg [7:0] dbg_accept_count;
    reg [7:0] dbg_complete_count;
    reg [7:0] dbg_stall_cycles;
    reg [7:0] dbg_peak_stall;
    reg       dbg_timeout;
    initial dbg_accept_count = 8'd0;
    initial dbg_complete_count = 8'd0;
    initial dbg_stall_cycles = 8'd0;
    initial dbg_peak_stall = 8'd0;
    initial dbg_timeout = 1'b0;
    always @(posedge clk) begin
        if (acc) begin
            if (dbg_accept_count != 8'hff)
                dbg_accept_count <= dbg_accept_count + 1'b1;
        end
        if (rel) begin
            if (dbg_complete_count != 8'hff)
                dbg_complete_count <= dbg_complete_count + 1'b1;
        end
        if (out_valid && !out_ready) begin
            if (dbg_stall_cycles != 8'hff) begin
                dbg_stall_cycles <= dbg_stall_cycles + 1'b1;
                if (dbg_stall_cycles >= dbg_peak_stall)
                    dbg_peak_stall <= dbg_stall_cycles + 1'b1;
            end
            if (dbg_stall_cycles >= 8'd63)
                dbg_timeout <= 1'b1;
        end else begin
            dbg_stall_cycles <= 8'd0;
        end
    end
    assign debug_status = {dbg_timeout, 7'd0, dbg_peak_stall,
                           dbg_complete_count, dbg_accept_count};

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
endmodule

module axi_cdc_bridge #(
    parameter DEPTH = 24,
    parameter PW = 5
) (
    input  wire        clk,
    input  wire        s_ce,
    input  wire        m_ce,
    input  wire        i_load,
    input  wire [15:0] i_lim,
    input  wire        s_aw_valid,
    input  wire [15:0] s_aw_addr,
    output wire        s_aw_ready,
    output wire        m_aw_valid,
    output wire [15:0] m_aw_addr,
    input  wire        m_aw_ready,
    input  wire        s_w_valid,
    input  wire [15:0] s_w_data,
    output wire        s_w_ready,
    output wire        m_w_valid,
    output wire [15:0] m_w_data,
    input  wire        m_w_ready,
    input  wire        m_b_valid,
    input  wire [15:0] m_b_resp,
    output wire        m_b_ready,
    output wire        s_b_valid,
    output wire [15:0] s_b_resp,
    input  wire        s_b_ready,
    input  wire        s_ar_valid,
    input  wire [15:0] s_ar_addr,
    output wire        s_ar_ready,
    output wire        m_ar_valid,
    output wire [15:0] m_ar_addr,
    input  wire        m_ar_ready,
    input  wire        m_r_valid,
    input  wire [15:0] m_r_data,
    output wire        m_r_ready,
    output wire        s_r_valid,
    output wire [15:0] s_r_data,
    input  wire        s_r_ready
,
    output wire [15:0] lim_o,
    output wire [15:0] occ_w_o,
    output wire [15:0] rc_w_o,
    output wire [PW-1:0] rp_w_o,
    output wire [15:0] wc_w_o,
    output wire [PW-1:0] wp_w_o
);
    localparam [15:0]   DEPTH16 = DEPTH;
    localparam [PW-1:0] LAST    = DEPTH - 1;

    reg [15:0] lim = DEPTH16;

    reg [15:0] mem_aw [0:DEPTH-1];
    reg [15:0] mem_w  [0:DEPTH-1];
    reg [15:0] mem_b  [0:DEPTH-1];
    reg [15:0] mem_ar [0:DEPTH-1];
    reg [15:0] mem_r  [0:DEPTH-1];
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) begin
            mem_aw[i] = 16'd0;
            mem_w[i]  = 16'd0;
            mem_b[i]  = 16'd0;
            mem_ar[i] = 16'd0;
            mem_r[i]  = 16'd0;
        end
    end

    reg [PW-1:0] wp_aw = 0, rp_aw = 0, wp_w = 0, rp_w = 0, wp_b = 0, rp_b = 0;
    reg [PW-1:0] wp_ar = 0, rp_ar = 0, wp_r = 0, rp_r = 0;
    reg [15:0] wc_aw = 0, rc_aw = 0, occ_aw = 0;
    reg [15:0] wc_w  = 0, rc_w  = 0, occ_w  = 0;
    reg [15:0] wc_b  = 0, rc_b  = 0, occ_b  = 0;
    reg [15:0] wc_ar = 0, rc_ar = 0, occ_ar = 0;
    reg [15:0] wc_r  = 0, rc_r  = 0, occ_r  = 0;

    wire full_aw  = (occ_aw >= lim);
    wire empty_aw = (wc_aw == rc_aw);
    wire full_w   = (occ_w >= lim);
    wire empty_w  = (wc_w == rc_w);
    wire full_b   = (occ_b >= lim);
    wire empty_b  = (wc_b == rc_b);
    wire full_ar  = (occ_ar >= lim);
    wire empty_ar = (wc_ar == rc_ar);
    wire full_r   = (occ_r >= lim);
    wire empty_r  = (wc_r == rc_r);

    wire push_aw = s_ce && s_aw_valid && !full_aw;
    wire pop_aw  = m_ce && m_aw_ready && !empty_aw;
    wire push_w  = s_ce && s_w_valid  && !full_w;
    wire pop_w   = m_ce && m_w_ready  && !empty_w;
    wire push_b  = m_ce && m_b_valid  && !full_b;
    wire pop_b   = s_ce && s_b_ready  && !empty_b;
    wire push_ar = s_ce && s_ar_valid && !full_ar;
    wire pop_ar  = m_ce && m_ar_ready && !empty_ar;
    wire push_r  = m_ce && m_r_valid  && !full_r;
    wire pop_r   = s_ce && s_r_ready  && !empty_r;

    assign s_aw_ready = !full_aw;
    assign m_aw_valid = !empty_aw;
    assign m_aw_addr  = mem_aw[rp_aw];
    assign s_w_ready  = !full_w;
    assign m_w_valid  = !empty_w;
    assign m_w_data   = mem_w[rp_w];
    assign m_b_ready  = !full_b;
    assign s_b_valid  = !empty_b;
    assign s_b_resp   = mem_b[rp_b];
    assign s_ar_ready = !full_ar;
    assign m_ar_valid = !empty_ar;
    assign m_ar_addr  = mem_ar[rp_ar];
    assign m_r_ready  = !full_r;
    assign s_r_valid  = !empty_r;
    assign s_r_data   = mem_r[rp_r];

    wire quiet = (occ_aw == 16'd0) && (occ_w == 16'd0) && (occ_b == 16'd0) && (occ_ar == 16'd0) && (occ_r == 16'd0);

    always @(posedge clk)
        if (i_load && quiet)
            lim <= ((i_lim == 16'd0) || (i_lim > DEPTH16)) ? DEPTH16 : i_lim;

    always @(posedge clk) begin
        if (push_aw) begin
            mem_aw[wp_aw] <= s_aw_addr;
            wp_aw <= (wp_aw == LAST) ? {PW{1'b0}} : wp_aw + 1'b1;
            wc_aw <= wc_aw + 16'd1;
        end
        if (pop_aw) begin
            rp_aw <= (rp_aw == LAST) ? {PW{1'b0}} : rp_aw + 1'b1;
            rc_aw <= rc_aw + 16'd1;
        end
        occ_aw <= occ_aw + {15'd0, push_aw} - {15'd0, pop_aw};
    end

    always @(posedge clk) begin
        if (push_w) begin
            mem_w[wp_w] <= s_w_data;
            wp_w <= (wp_w == LAST) ? {PW{1'b0}} : wp_w + 1'b1;
            wc_w <= wc_w + 16'd1;
        end
        if (pop_w) begin
            rp_w <= (rp_w == LAST) ? {PW{1'b0}} : rp_w + 1'b1;
            rc_w <= rc_w + 16'd1;
        end
        occ_w <= occ_w + {15'd0, push_w} - {15'd0, pop_w};
    end

    always @(posedge clk) begin
        if (push_b) begin
            mem_b[wp_b] <= m_b_resp;
            wp_b <= (wp_b == LAST) ? {PW{1'b0}} : wp_b + 1'b1;
            wc_b <= wc_b + 16'd1;
        end
        if (pop_b) begin
            rp_b <= (rp_b == LAST) ? {PW{1'b0}} : rp_b + 1'b1;
            rc_b <= rc_b + 16'd1;
        end
        occ_b <= occ_b + {15'd0, push_b} - {15'd0, pop_b};
    end

    always @(posedge clk) begin
        if (push_ar) begin
            mem_ar[wp_ar] <= s_ar_addr;
            wp_ar <= (wp_ar == LAST) ? {PW{1'b0}} : wp_ar + 1'b1;
            wc_ar <= wc_ar + 16'd1;
        end
        if (pop_ar) begin
            rp_ar <= (rp_ar == LAST) ? {PW{1'b0}} : rp_ar + 1'b1;
            rc_ar <= rc_ar + 16'd1;
        end
        occ_ar <= occ_ar + {15'd0, push_ar} - {15'd0, pop_ar};
    end

    always @(posedge clk) begin
        if (push_r) begin
            mem_r[wp_r] <= m_r_data;
            wp_r <= (wp_r == LAST) ? {PW{1'b0}} : wp_r + 1'b1;
            wc_r <= wc_r + 16'd1;
        end
        if (pop_r) begin
            rp_r <= (rp_r == LAST) ? {PW{1'b0}} : rp_r + 1'b1;
            rc_r <= rc_r + 16'd1;
        end
        occ_r <= occ_r + {15'd0, push_r} - {15'd0, pop_r};
    end

    reg armed = 1'b0;
    always @(posedge clk)
        if (push_w)
            armed <= 1'b1;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed)
            assert (!($past(full_w) && $past(empty_w)));
    assign lim_o = lim;
    assign occ_w_o = occ_w;
    assign rc_w_o = rc_w;
    assign rp_w_o = rp_w;
    assign wc_w_o = wc_w;
    assign wp_w_o = wp_w;
endmodule

module uart_tx_word #(
    parameter DATA_W = 32
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire              baud_tick,
    input  wire              s_valid,
    output wire              s_ready,
    input  wire [DATA_W-1:0] s_data,
    output wire              txd,
    output wire              o_busy
,
    output wire [31:0] bitcnt_o,
    output wire busy_o,
    output wire in_frame_o,
    output wire [FRAME_W-1:0] shreg_o
);
    localparam integer FRAME_W = DATA_W + 3;
    localparam [31:0] LAST = FRAME_W - 1;
    localparam [FRAME_W-1:0] ONE = 1;

    reg [FRAME_W-1:0] shreg = {FRAME_W{1'b0}};
    reg [31:0] bitcnt = 32'd0;
    reg busy = 1'b0;
    reg in_frame = 1'b0;

    assign s_ready = !busy;
    assign txd = busy ? shreg[0] : 1'b1;
    assign o_busy = busy;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shreg <= {FRAME_W{1'b0}};
            bitcnt <= 32'd0;
            busy <= 1'b0;
            in_frame <= 1'b0;
        end else if (s_valid && s_ready) begin
            shreg <= {1'b1, ^s_data, s_data, 1'b0};
            bitcnt <= 32'd0;
            busy <= 1'b1;
            in_frame <= 1'b1;
        end else if (baud_tick && busy) begin
            bitcnt <= bitcnt + 32'd1;
            if (shreg == ONE) begin
                shreg <= {FRAME_W{1'b0}};
                busy <= 1'b0;
                in_frame <= 1'b0;
            end else begin
                shreg <= shreg >> 1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && in_frame && $rose(txd))
            assert (bitcnt <= LAST);
    assign bitcnt_o = bitcnt;
    assign busy_o = busy;
    assign in_frame_o = in_frame;
    assign shreg_o = shreg;
endmodule

module axi_uart_tx (
    input wire clk,
    input wire rst_n,
    input wire s_ce, m_ce,
    input wire i_load,
    input wire [15:0] i_lim,
    input wire baud_tick,
    input wire s_aw_valid,
    input wire [15:0] s_aw_addr,
    output wire s_aw_ready,
    input wire s_w_valid,
    input wire [15:0] s_w_data,
    output wire s_w_ready,
    output wire s_b_valid,
    output wire [15:0] s_b_resp,
    input wire s_b_ready,
    input wire s_ar_valid,
    input wire [15:0] s_ar_addr,
    output wire s_ar_ready,
    output wire s_r_valid,
    output wire [15:0] s_r_data,
    input wire s_r_ready,
    output wire txd,
    output wire [15:0] a_lim, a_occ_w, a_rc_w, a_wc_w,
    output wire [4:0] a_rp_w, a_wp_w,
    output wire [31:0] uart_bitcnt,
    output wire uart_busy, uart_in_frame,
    output wire [10:0] uart_shreg,
    output wire [15:0] address_o,
    output wire address_pending_o, tx_wait_o,
    output wire response_pending_o, response_error_o,
    output wire uart_online_o
);
    localparam [15:0] TX_ADDR = 16'h0000;
    localparam [15:0] COUNT_ADDR = 16'h0004;

    wire a_aw_valid, a_aw_ready, a_w_valid, a_w_ready;
    wire [15:0] a_aw_addr, a_w_data;
    wire a_b_valid, a_b_ready;
    wire [15:0] a_b_resp;
    wire a_ar_valid, a_ar_ready, a_r_valid, a_r_ready;
    wire [15:0] a_ar_addr, a_r_data;
    wire uart_valid, uart_ready;

    reg [15:0] address_hold = 16'd0;
    reg address_pending = 1'b0;
    reg tx_wait = 1'b0;
    reg response_pending = 1'b0;
    reg response_error = 1'b0;
    reg uart_online = 1'b0;

    assign address_o = address_hold;
    assign address_pending_o = address_pending;
    assign tx_wait_o = tx_wait;
    assign response_pending_o = response_pending;
    assign response_error_o = response_error;
    assign uart_online_o = uart_online;

    wire address_is_tx = (address_hold == TX_ADDR);
    assign a_aw_ready = uart_online && !address_pending;
    assign a_w_ready = uart_online && address_pending && !tx_wait &&
                       !response_pending && (!address_is_tx || uart_ready);
    assign uart_valid = m_ce && uart_online && address_pending &&
                        !tx_wait && !response_pending && address_is_tx && a_w_valid;
    wire address_take = m_ce && a_aw_valid && a_aw_ready;
    wire write_take = m_ce && a_w_valid && a_w_ready;
    wire uart_take = uart_valid && uart_ready;
    wire write_reject = write_take && !address_is_tx;

    assign a_b_valid = response_pending;
    assign a_b_resp = response_error ? 16'd3 : 16'd0;
    wire response_take = m_ce && a_b_valid && a_b_ready;

    // The read port reports status without disturbing a pending write.
    assign a_r_valid = uart_online && a_ar_valid;
    assign a_ar_ready = uart_online && a_r_ready;
    assign a_r_data = (a_ar_addr == TX_ADDR) ? {15'd0, uart_busy} :
                      (a_ar_addr == COUNT_ADDR) ? uart_bitcnt[15:0] : 16'hffff;

    axi_cdc_bridge bridge (
        .clk(clk), .s_ce(s_ce), .m_ce(m_ce),
        .i_load(i_load), .i_lim(i_lim),
        .s_aw_valid(s_aw_valid), .s_aw_addr(s_aw_addr),
        .s_aw_ready(s_aw_ready),
        .m_aw_valid(a_aw_valid), .m_aw_addr(a_aw_addr),
        .m_aw_ready(a_aw_ready),
        .s_w_valid(s_w_valid), .s_w_data(s_w_data),
        .s_w_ready(s_w_ready),
        .m_w_valid(a_w_valid), .m_w_data(a_w_data),
        .m_w_ready(a_w_ready),
        .m_b_valid(a_b_valid), .m_b_resp(a_b_resp),
        .m_b_ready(a_b_ready),
        .s_b_valid(s_b_valid), .s_b_resp(s_b_resp),
        .s_b_ready(s_b_ready),
        .s_ar_valid(s_ar_valid), .s_ar_addr(s_ar_addr),
        .s_ar_ready(s_ar_ready),
        .m_ar_valid(a_ar_valid), .m_ar_addr(a_ar_addr),
        .m_ar_ready(a_ar_ready),
        .m_r_valid(a_r_valid), .m_r_data(a_r_data),
        .m_r_ready(a_r_ready),
        .s_r_valid(s_r_valid), .s_r_data(s_r_data),
        .s_r_ready(s_r_ready),
        .lim_o(a_lim), .occ_w_o(a_occ_w),
        .rc_w_o(a_rc_w), .rp_w_o(a_rp_w),
        .wc_w_o(a_wc_w), .wp_w_o(a_wp_w)
    );

    uart_tx_word #(.DATA_W(8)) uart (
        .clk(clk), .rst_n(rst_n), .baud_tick(baud_tick),
        .s_valid(uart_valid), .s_ready(uart_ready),
        .s_data(a_w_data[7:0]), .txd(txd), .o_busy(),
        .bitcnt_o(uart_bitcnt), .busy_o(uart_busy),
        .in_frame_o(uart_in_frame), .shreg_o(uart_shreg)
    );

    // Allow the UART and the bus-side join to leave reset together.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            uart_online <= 1'b0;
        else
            uart_online <= 1'b1;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            address_hold <= 16'd0;
            address_pending <= 1'b0;
            tx_wait <= 1'b0;
            response_pending <= 1'b0;
            response_error <= 1'b0;
        end else if (m_ce) begin
            // AW may run ahead while a previous character is shifting.
            if (address_take) begin
                address_hold <= a_aw_addr;
                address_pending <= 1'b1;
            end
            if (write_take)
                address_pending <= 1'b0;
            if (uart_take) begin
                tx_wait <= 1'b1;
                response_error <= 1'b0;
            end
            if (write_reject) begin
                response_pending <= 1'b1;
                response_error <= 1'b1;
            end
            // Completion is retained until the response FIFO has space.
            if (tx_wait && !uart_busy) begin
                tx_wait <= 1'b0;
                response_pending <= 1'b1;
                response_error <= 1'b0;
            end
            if (response_take)
                response_pending <= 1'b0;
        end
    end

    always @(posedge clk)
        if (response_pending_o && !response_error_o)
            assert (!uart_busy && uart_bitcnt == 32'd11);
endmodule

module ntt_phase_dispatch #(
    parameter W = 16,
    parameter PROFILES = 4,
    parameter MAX_BURST = 4
) (
    input  wire clk,
    input  wire cfg_valid,
    output wire cfg_ready,
    input  wire [W-1:0] cfg_data,
    input  wire [W-1:0] profile_select,
    input  wire start,
    input  wire run,
    input  wire finish,
    input  wire [W-1:0] remaining,
    input  wire [W-1:0] launch_latency,
    output reg  [W-1:0] step = 16'd0,
    output reg  [W-1:0] quantum = 16'd1,
    output wire [W*PROFILES-1:0] profiles,
    output reg  [1:0] cfg_state = 2'd0,
    output reg  [$clog2(PROFILES)-1:0] cfg_index = 0,
    output reg  [W-1:0] cfg_pending = 16'd0,
    output reg  [W-1:0] cfg_prepared = 16'd1,
    output wire cfg_apply
);
    localparam INDEX_W = $clog2(PROFILES);
    localparam [INDEX_W-1:0] LAST_PROFILE = PROFILES - 1;
    reg [W-1:0] cap [0:PROFILES-1];
    wire [INDEX_W-1:0] selected = profile_select % PROFILES;
    integer init_profile;
    initial begin
        for (init_profile = 0; init_profile < PROFILES; init_profile = init_profile + 1) begin
            cap[init_profile] = 16'd1;
        end
    end
    genvar p;
    generate
        for (p = 0; p < PROFILES; p = p + 1) begin: expose_profiles
            assign profiles[p*W +: W] = cap[p];
        end
    endgenerate
    assign cfg_ready = (cfg_state == 2'd0);
    assign cfg_apply = (cfg_state == 2'd2);

    function [W-1:0] choose_step;
        input [W-1:0] left;
        input [W-1:0] limit;
        begin
            if (left <= 16'd1)
                choose_step = 16'd1;
            else if (left - 16'd1 < limit)
                choose_step = left - 16'd1;
            else
                choose_step = limit;
        end
    endfunction

    always @(posedge clk) begin
        case (cfg_state)
            2'd0: begin
                if (cfg_valid && cfg_ready) begin
                    cfg_pending <= cfg_data;
                    cfg_state <= 2'd1;
                end
            end
            2'd1: begin
                if (cfg_pending == 16'd0)
                    cfg_prepared <= 16'd1;
                else if (cfg_pending > MAX_BURST)
                    cfg_prepared <= MAX_BURST;
                else
                    cfg_prepared <= cfg_pending;
                cfg_state <= 2'd2;
            end
            2'd2: begin
                cap[cfg_index] <= cfg_prepared;
                if (cfg_index == LAST_PROFILE)
                    cfg_index <= {INDEX_W{1'b0}};
                else
                    cfg_index <= cfg_index + 1'b1;
                cfg_state <= 2'd0;
            end
            default: cfg_state <= 2'd0;
        endcase
    end

    always @(posedge clk) begin
        if (start) begin
            quantum <= cap[selected];
            step <= choose_step(launch_latency, cap[selected]);
        end else if (finish) begin
            step <= 16'd0;
        end else if (run) begin
            step <= choose_step(remaining - step, quantum);
        end
    end
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5,
    parameter DEPTH = 4,
    parameter BURST_PROFILES = 4,
    parameter MAX_BURST = 4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b,
    output wire [$clog2(DEPTH):0] queued,
    output wire         head_cached,
    output wire         cfg_ready,
    output wire         cfg_busy,
    output wire [W-1:0] burst_step,
    output wire [W*BURST_PROFILES-1:0] burst_profiles
);
    localparam NBF = NCOEF / 2;
    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W = ADDR_W + 1;
    localparam [ADDR_W-1:0] LAST_SLOT = DEPTH - 1;

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    reg [W-1:0] q_a [0:DEPTH-1];
    reg [W-1:0] q_b [0:DEPTH-1];
    reg [W-1:0] q_w [0:DEPTH-1];
    reg [W-1:0] q_lat [0:DEPTH-1];
    reg [PTR_W-1:0] q_wr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] q_rd = {PTR_W{1'b0}};
    reg head_valid = 1'b0;
    integer init_slot;
    wire [ADDR_W-1:0] head_slot = q_rd[ADDR_W-1:0];
    wire q_empty = (q_wr == q_rd);
    wire q_full = (q_wr[ADDR_W] != q_rd[ADDR_W]) &&
                  (q_wr[ADDR_W-1:0] == q_rd[ADDR_W-1:0]);
    initial begin
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            q_a[init_slot] = 16'd0;
            q_b[init_slot] = 16'd0;
            q_w[init_slot] = 16'd0;
            q_lat[init_slot] = 16'd0;
        end
    end
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end
    assign queued = (q_wr[ADDR_W] == q_rd[ADDR_W]) ?
        ({1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]}) :
        (DEPTH + {1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]});
    assign head_cached = head_valid;

    assign in_ready = !q_full;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);
    wire cache_read = ce && !head_valid && !q_empty;
    wire bypass_head = ce && accept && q_empty;
    wire start = ce && head_valid && !busy && !out_valid;
    wire retire = busy && ce && last;
    wire [W-1:0] burst_quantum;
    wire [1:0] cfg_state;
    wire [$clog2(BURST_PROFILES)-1:0] cfg_write_index;
    wire [W-1:0] cfg_pending;
    wire [W-1:0] cfg_prepared;
    wire cfg_apply;
    assign cfg_busy = (cfg_state != 2'd0);

    ntt_phase_dispatch #(
        .W(W), .PROFILES(BURST_PROFILES), .MAX_BURST(MAX_BURST)
    ) phase_dispatch (
        .clk(clk), .cfg_valid(load_cfg), .cfg_ready(cfg_ready),
        .cfg_data(cfg_lat), .profile_select(stage),
        .start(start), .run(busy && ce && !last), .finish(retire),
        .remaining(cd), .launch_latency(lat_q),
        .step(burst_step), .quantum(burst_quantum),
        .profiles(burst_profiles), .cfg_state(cfg_state),
        .cfg_index(cfg_write_index), .cfg_pending(cfg_pending),
        .cfg_prepared(cfg_prepared), .cfg_apply(cfg_apply)
    );

    wire [31:0] prod = w_r * b_r;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];
    always @(posedge clk) begin
        if (accept) begin
            q_a[q_wr[ADDR_W-1:0]] <= in_a;
            q_b[q_wr[ADDR_W-1:0]] <= in_b;
            q_w[q_wr[ADDR_W-1:0]] <= in_w;
            q_lat[q_wr[ADDR_W-1:0]] <= lat_eff;
            if (q_wr[ADDR_W-1:0] == LAST_SLOT)
                q_wr <= {!q_wr[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_wr <= q_wr + 1'b1;
        end
        if (retire) begin
            if (q_rd[ADDR_W-1:0] == LAST_SLOT)
                q_rd <= {!q_rd[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_rd <= q_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (cache_read) begin
            a_r <= q_a[head_slot];
            b_r <= q_b[head_slot];
            w_r <= q_w[head_slot];
            lat_q <= q_lat[head_slot];
            head_valid <= 1'b1;
        end else if (bypass_head) begin
            a_r <= in_a;
            b_r <= in_b;
            w_r <= in_w;
            lat_q <= lat_eff;
            head_valid <= 1'b1;
        end else if (retire) begin
            head_valid <= 1'b0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (cfg_apply) lat_cfg <= cfg_pending;
        if (start) begin
            cd    <= lat_q;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
        end else if (busy && ce) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - burst_step;
                phase <= phase + burst_step;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

module div3_serial #(
    parameter W = 16,
    parameter MAXBITS = 16,
    parameter DEPTH = 4 // power-of-two capture depth
) (
    input  wire         clk,
    input  wire         arm,
    input  wire         clr,
    input  wire         load,
    input  wire [W-1:0] load_len,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire         in_bit,
    output wire         done,
    output wire         div3,
    output wire [1:0]   o_rem,
    output wire [$clog2(DEPTH):0] buffered,
    output wire [W-1:0] capture_value,
    output wire [W-1:0] next_prefix
);
    localparam [1:0] S_IDLE = 2'd0, S_ARM = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [1:0]   phase   = S_IDLE;
    reg [1:0]   rem     = 2'd0;
    reg [W-1:0] val     = {W{1'b0}};
    reg [W-1:0] cnt     = {W{1'b0}};
    reg [W-1:0] limit   = 16'd8;
    reg         started = 1'b0;
    reg         win     = 1'b0;

    localparam PTR_W = $clog2(DEPTH);
    reg [W-1:0] prefix_mem [0:DEPTH-1];
    reg [W-1:0] capture_prefix = {W{1'b0}};
    reg [PTR_W:0] wr_ptr = {(PTR_W+1){1'b0}};
    reg [PTR_W:0] rd_ptr = {(PTR_W+1){1'b0}};
    reg [W-1:0] queued_prefix [0:DEPTH-1];
    wire [PTR_W:0] q_used = wr_ptr - rd_ptr;
    wire q_empty = (wr_ptr == rd_ptr);
    wire q_full = (wr_ptr[PTR_W] != rd_ptr[PTR_W]) &&
                  (wr_ptr[PTR_W-1:0] == rd_ptr[PTR_W-1:0]);
    wire [W-1:0] accepted_bits = cnt + q_used;
    wire consume = (phase == S_RUN) && !q_empty;
    integer init_i;
    integer view_i;
    integer clear_i;

    assign in_ready = ((phase == S_ARM) || (phase == S_RUN)) &&
                      !q_full && (accepted_bits < limit);
    wire acc = in_valid && in_ready;
    assign buffered = q_used;
    assign capture_value = capture_prefix;
    assign next_prefix = q_empty ? {W{1'b0}} : queued_prefix[0];

    function [1:0] rnext;
        input [1:0] r;
        input       b;
        begin
            case ({r, b})
                3'b000: rnext = 2'd0;
                3'b001: rnext = 2'd1;
                3'b010: rnext = 2'd2;
                3'b011: rnext = 2'd0;
                3'b100: rnext = 2'd1;
                3'b101: rnext = 2'd2;
                default: rnext = 2'd0;
            endcase
        end
    endfunction

    wire [W-1:0] load_clamped = (load_len == 16'd0) ? 16'd1 :
                                (load_len > MAXBITS) ? MAXBITS : load_len;

    initial begin
        for (init_i = 0; init_i < DEPTH; init_i = init_i + 1)
            prefix_mem[init_i] = {W{1'b0}};
    end

    always @(*) begin
        for (view_i = 0; view_i < DEPTH; view_i = view_i + 1) begin
            queued_prefix[view_i] =
                prefix_mem[(rd_ptr[PTR_W-1:0] + view_i) % DEPTH];
        end
    end

    always @(posedge clk) begin
        if (((phase == S_IDLE) && arm) ||
            ((phase == S_DONE) && clr)) begin
            wr_ptr <= {(PTR_W+1){1'b0}};
            rd_ptr <= {(PTR_W+1){1'b0}};
            capture_prefix <= {W{1'b0}};
            for (clear_i = 0; clear_i < DEPTH; clear_i = clear_i + 1) begin
                prefix_mem[clear_i] <= {W{1'b0}};
            end
        end else begin
            if (acc) begin
                prefix_mem[wr_ptr[PTR_W-1:0]] <=
                    {capture_prefix[W-2:0], in_bit};
                capture_prefix <= {capture_prefix[W-2:0], in_bit};
                wr_ptr <= wr_ptr + 1'b1;
            end
            if (consume) rd_ptr <= rd_ptr + 1'b1;
        end
    end

    always @(posedge clk) begin
        if (phase == S_IDLE) begin
            if (load) limit <= load_clamped;
            if (arm) begin
                phase   <= S_ARM;
                rem     <= 2'd0;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b1;
            end
        end else if (phase == S_DONE) begin
            if (clr) begin
                phase   <= S_IDLE;
                rem     <= 2'd0;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b0;
            end
        end else if (phase == S_ARM) begin
            if (acc && ((q_used == DEPTH-1) ||
                        (accepted_bits + 16'd1 == limit)))
                phase <= S_RUN;
        end else if (consume) begin
            rem     <= rnext(rem, queued_prefix[0][0]);
            val     <= queued_prefix[0];
            cnt     <= cnt + 16'd1;
            started <= 1'b1;
            if (cnt + 16'd1 == limit) phase <= S_DONE;
            else                      phase <= S_RUN;
        end
    end

    assign done  = (phase == S_DONE);
    assign div3  = (rem == 2'd0);
    assign o_rem = rem;

    always @(posedge clk)
        if (acc)
            assert ((capture_prefix >> accepted_bits) == {W{1'b0}});

    always @(posedge clk)
        if (win && $rose(done))
            assert (started && (div3 == ((val % 16'd3) == 16'd0)));
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag,
    input  wire         peer_valid,
    output wire         peer_ready,
    input  wire [W-1:0] peer_mag,
    input  wire         peer_sign,
    output wire         peer_out_valid,
    input  wire         peer_out_ready,
    output wire [W-1:0] peer_out_min1,
    output wire [W-1:0] peer_out_min2,
    output wire [W-1:0] peer_out_idx,
    output wire         peer_out_sign,
    output wire [31:0] debug_status
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
    localparam CHANNELS = 2, PCW = (DEG > 1) ? $clog2(DEG) : 1;
    reg [W-1:0] peer_min1 [1:CHANNELS-1], peer_min2 [1:CHANNELS-1];
    reg [PCW-1:0] peer_count [1:CHANNELS-1], peer_idx [1:CHANNELS-1];
    reg peer_done [1:CHANNELS-1], peer_sign_prod [1:CHANNELS-1];
    reg cache_owner;
    reg [W-1:0] shared_min;
    initial cache_owner = 1'b1;
    initial shared_min = {W{1'b1}};
    integer lane;
    initial begin
        for (lane = 1; lane < CHANNELS; lane = lane + 1) begin
            peer_min1[lane] = {W{1'b1}}; peer_min2[lane] = {W{1'b1}};
            peer_count[lane] = {PCW{1'b0}}; peer_idx[lane] = {PCW{1'b0}};
            peer_done[lane] = 1'b0; peer_sign_prod[lane] = 1'b0;
        end
    end
    wire lane_req = in_valid && (state == S_ACCUM);
    wire peer_req = peer_valid && !peer_done[1];

    assign in_ready = (state == S_ACCUM) && !(peer_req && !cache_owner);
    assign peer_ready = !peer_done[1] && !(lane_req && cache_owner);
    wire peer_acc = peer_valid && peer_ready;
    wire peer_rel = peer_out_valid && peer_out_ready;
    assign out_valid = (state == S_DONE);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready;
    wire fold_fire = acc || peer_acc;
    wire [W-1:0] fold_mag = peer_acc ? peer_mag : in_mag;
    wire [W-1:0] fold_floor = (cache_owner == peer_acc) ? shared_min : (peer_acc ? peer_min1[1] : min1);
    wire [W-1:0] fold_limit = peer_acc ? peer_min2[1] : min2;
    wire fold_lower = fold_mag < fold_floor;
    wire [W-1:0] fold_min1 = fold_lower ? fold_mag : fold_floor;
    wire [W-1:0] fold_min2 = fold_lower ? fold_floor :
                           ((fold_mag < fold_limit) ? fold_mag : fold_limit);

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
            min1 <= fold_min1;
            min2 <= fold_min2;
            if (fold_lower) min_idx <= count;
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = min1;
    assign out_min2 = min2;
    assign out_idx  = min_idx;
    assign out_sign = sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;
    always @(posedge clk) begin
        for (lane = 1; lane < CHANNELS; lane = lane + 1) begin
            if (peer_acc) begin
                peer_min1[lane] <= fold_min1; peer_min2[lane] <= fold_min2;
                peer_sign_prod[lane] <= peer_sign_prod[lane] ^ peer_sign;
                if (fold_lower) peer_idx[lane] <= peer_count[lane];
                if (peer_count[lane] == DEG - 1) begin
                    peer_count[lane] <= {PCW{1'b0}}; peer_done[lane] <= 1'b1;
                end else peer_count[lane] <= peer_count[lane] + 1'b1;
            end else if (peer_rel) begin
                peer_min1[lane] <= {W{1'b1}}; peer_min2[lane] <= {W{1'b1}};
                peer_idx[lane] <= {PCW{1'b0}}; peer_sign_prod[lane] <= 1'b0; peer_done[lane] <= 1'b0;
            end
        end
        if (fold_fire) begin
            shared_min <= fold_min1; cache_owner <= peer_acc;
        end else if ((!cache_owner && rel) || (cache_owner && peer_rel))
            shared_min <= {W{1'b1}};
    end
    assign peer_out_valid = peer_done[1];
    assign peer_out_min1 = peer_min1[1];
    assign peer_out_min2 = peer_min2[1];
    assign peer_out_idx = peer_idx[1];
    assign peer_out_sign = peer_sign_prod[1];
    always @(posedge clk) if (peer_acc && cache_owner) assert (fold_min2 >= shared_min);
    reg [7:0] dbg_accept_count;
    reg [7:0] dbg_complete_count;
    reg [7:0] dbg_stall_cycles;
    reg [7:0] dbg_peak_stall;
    reg       dbg_timeout;
    initial dbg_accept_count = 8'd0;
    initial dbg_complete_count = 8'd0;
    initial dbg_stall_cycles = 8'd0;
    initial dbg_peak_stall = 8'd0;
    initial dbg_timeout = 1'b0;
    always @(posedge clk) begin
        if (acc) begin
            if (dbg_accept_count != 8'hff)
                dbg_accept_count <= dbg_accept_count + 1'b1;
        end
        if (rel) begin
            if (dbg_complete_count != 8'hff)
                dbg_complete_count <= dbg_complete_count + 1'b1;
        end
        if (out_valid && !out_ready) begin
            if (dbg_stall_cycles != 8'hff) begin
                dbg_stall_cycles <= dbg_stall_cycles + 1'b1;
                if (dbg_stall_cycles >= dbg_peak_stall)
                    dbg_peak_stall <= dbg_stall_cycles + 1'b1;
            end
            if (dbg_stall_cycles >= 8'd63)
                dbg_timeout <= 1'b1;
        end else begin
            dbg_stall_cycles <= 8'd0;
        end
    end
    assign debug_status = {dbg_timeout, 7'd0, dbg_peak_stall,
                           dbg_complete_count, dbg_accept_count};

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
endmodule

module ddr3_cmd_queue #(
    parameter DEPTH = 12,
    parameter DW = 32
) (
    input  wire          clk,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data,
    input  wire          cfg_load,
    input  wire [31:0]   cfg_wm,
    output wire          almost_full,
    output wire [31:0]   occupancy
,
    output wire [31:0] count_o,
    output wire rd_lap_o,
    output wire [AW-1:0] rptr_o,
    output wire [AW-1:0] wptr_o,
    output wire wr_lap_o
);
    localparam AW = $clog2(DEPTH);
    localparam [AW-1:0] LAST = DEPTH - 1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] wptr = {AW{1'b0}};
    reg [AW-1:0] rptr = {AW{1'b0}};
    reg          wr_lap = 1'b0;
    reg          rd_lap = 1'b0;
    reg [31:0]   count = 32'd0;
    reg [31:0]   wm = 32'd8;
    reg          armed = 1'b1;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = {DW{1'b0}};
    end

    wire full  = (wptr == rptr) && (wr_lap != rd_lap);
    wire empty = (wptr == rptr) && (wr_lap == rd_lap);
    assign in_ready  = !full;
    assign out_valid = !empty;
    assign out_data  = mem[rptr];

    wire push = in_valid && in_ready;
    wire pop  = out_valid && out_ready;

    // T inputs of the two lap toggle flip-flops
    wire wr_t = push && (wptr == LAST);
    wire rd_t = pop  && (rptr == LAST);

    always @(posedge clk) begin
        if (push) begin
            mem[wptr] <= in_data;
            wptr <= (wptr == LAST) ? {AW{1'b0}} : wptr + 1'b1;
        end
        if (pop)
            rptr <= (rptr == LAST) ? {AW{1'b0}} : rptr + 1'b1;
        if (wr_t) wr_lap <= ~wr_lap;
        if (rd_t) rd_lap <= ~rd_lap;
        case ({push, pop})
            2'b10:   count <= count + 32'd1;
            2'b01:   count <= count - 32'd1;
            default: count <= count;
        endcase
        if (cfg_load) begin
            wm    <= cfg_wm;
            armed <= 1'b0;
        end
    end

    assign almost_full = (count >= wm);
    assign occupancy   = count;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $rose(wr_lap))
            assert (count <= DEPTH);
    assign count_o = count;
    assign rd_lap_o = rd_lap;
    assign rptr_o = rptr;
    assign wptr_o = wptr;
    assign wr_lap_o = wr_lap;
endmodule

module qp_zins_mux #(
    parameter DEPTH = 16,
    parameter DW = 32,
    parameter SW = $clog2(DEPTH)
) (
    input  wire          clk,
    input  wire          i_reset,
    input  wire          i_load,
    input  wire [31:0]   i_limit,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [SW-1:0] in_qp,
    input  wire [DW-1:0] in_data,
    input  wire          i_drain,
    output wire [DW-1:0] o_data,
    output wire          o_valid
,
    output wire [31:0] cnt_o,
    output wire [DEPTH-1:0] mask_o
);
    reg [DEPTH*DW-1:0] data_flat;
    reg [DEPTH-1:0]    mask;
    reg [SW-1:0]       sel;
    reg [31:0]         cnt;
    reg [31:0]         limit;
    reg                win;

    initial data_flat = {(DEPTH*DW){1'b0}};
    initial mask = {DEPTH{1'b0}};
    initial sel = {SW{1'b0}};
    initial cnt = 32'd0;
    initial limit = DEPTH;
    initial win = 1'b0;

    wire hit = mask[sel];
    assign in_ready = !mask[in_qp] && (cnt < limit);
    wire in_fire = in_valid && in_ready;
    wire drn_hit = i_drain && hit;

    wire [DEPTH-1:0] one_m = {{(DEPTH-1){1'b0}}, 1'b1};
    wire [DEPTH-1:0] set_m = in_fire ? (one_m << in_qp) : {DEPTH{1'b0}};
    wire [DEPTH-1:0] clr_m = drn_hit ? (one_m << sel) : {DEPTH{1'b0}};

    // zero-insertion multiplexer: selected slot if valid, else constant zero
    assign o_valid = hit;
    assign o_data  = hit ? data_flat[sel*DW +: DW] : {DW{1'b0}};

    always @(posedge clk) begin
        if (i_reset) begin
            mask  <= {DEPTH{1'b0}};
            sel   <= {SW{1'b0}};
            cnt   <= 32'd0;
            win   <= 1'b0;
            limit <= i_limit;
        end else begin
            if (i_load)
                limit <= i_limit;
            if (in_fire)
                data_flat[in_qp*DW +: DW] <= in_data;
            mask <= (mask & ~clr_m) | set_m;
            cnt  <= cnt + (in_fire ? 32'd1 : 32'd0) - (drn_hit ? 32'd1 : 32'd0);
            if (i_drain)
                sel <= (sel == DEPTH-1) ? {SW{1'b0}} : sel + 1'b1;
            if (i_load)
                win <= 1'b0;
            else if (in_fire)
                win <= 1'b1;
        end
    end

    always @(posedge clk)
        if (win) assert (cnt <= DEPTH);

    always @(posedge clk)
        if (win) assert (cnt != 32'd0 || o_data == {DW{1'b0}});
    assign cnt_o = cnt;
    assign mask_o = mask;
endmodule

module ddr3_qp_window #(
    parameter DW = 32,
    parameter QDEPTH = 4,
    parameter FLIGHT_LIMIT = 8
) (
    input wire clk,
    input wire i_reset,
    input wire in_valid,
    output wire in_ready,
    input wire [DW-1:0] in_data,
    input wire cfg_load,
    input wire [31:0] cfg_wm,
    input wire i_load,
    input wire [31:0] i_limit,
    input wire i_drain,
    output wire [DW-1:0] o_data,
    output wire o_valid,
    output wire almost_full,
    output wire [31:0] occupancy,
    output wire [31:0] a_count_o,
    output wire [3:0] a_rptr_o,
    output wire [3:0] a_wptr_o,
    output wire a_rd_lap_o,
    output wire a_wr_lap_o,
    output wire a_out_valid,
    output wire a_out_ready,
    output wire [DW-1:0] a_out_data,
    output wire [31:0] b_cnt_o,
    output wire [15:0] b_mask_o,
    output reg [$clog2(QDEPTH+1)-1:0] q_count_o,
    output reg [$clog2(QDEPTH)-1:0] q_rptr_o,
    output reg [$clog2(QDEPTH)-1:0] q_wptr_o,
    output reg [$clog2(FLIGHT_LIMIT+1)-1:0] flight_o
);
    localparam A_DEPTH = 12;
    localparam B_DEPTH = 16;
    localparam SW = $clog2(B_DEPTH);
    localparam QAW = $clog2(QDEPTH);
    localparam QCW = $clog2(QDEPTH+1);
    localparam FCW = $clog2(FLIGHT_LIMIT+1);
    localparam [QAW-1:0] QLAST = QDEPTH-1;

    reg [DW-1:0] q_mem [0:QDEPTH-1];
    wire [DW-1:0] q_head = q_mem[q_rptr_o];
    wire [SW-1:0] b_in_qp = q_head[SW-1:0];
    wire b_in_ready;
    wire b_in_valid = !i_reset && (q_count_o != 0);
    wire q_push = a_out_valid && a_out_ready;
    wire q_pop = b_in_valid && b_in_ready;
    wire retire = !i_reset && i_drain && o_valid;

    // Reserve an end-to-end credit until the selected QP is drained.
    assign a_out_ready = !i_reset && (q_count_o < QDEPTH) &&
                         (flight_o < FLIGHT_LIMIT);

    ddr3_cmd_queue #(.DEPTH(A_DEPTH), .DW(DW)) cmd_queue (
        .clk(clk), .in_valid(in_valid), .in_ready(in_ready),
        .in_data(in_data), .out_valid(a_out_valid),
        .out_ready(a_out_ready), .out_data(a_out_data),
        .cfg_load(cfg_load), .cfg_wm(cfg_wm),
        .almost_full(almost_full), .occupancy(occupancy),
        .count_o(a_count_o), .rd_lap_o(a_rd_lap_o),
        .rptr_o(a_rptr_o), .wptr_o(a_wptr_o),
        .wr_lap_o(a_wr_lap_o)
    );

    qp_zins_mux #(.DEPTH(B_DEPTH), .DW(DW), .SW(SW)) qp_mux (
        .clk(clk), .i_reset(i_reset), .i_load(i_load),
        .i_limit(i_limit), .in_valid(b_in_valid),
        .in_ready(b_in_ready), .in_qp(b_in_qp),
        .in_data(q_head), .i_drain(i_drain), .o_data(o_data),
        .o_valid(o_valid), .cnt_o(b_cnt_o), .mask_o(b_mask_o)
    );

    integer j;
    initial begin
        q_count_o = {QCW{1'b0}};
        q_rptr_o = {QAW{1'b0}};
        q_wptr_o = {QAW{1'b0}};
        flight_o = {FCW{1'b0}};
        for (j = 0; j < QDEPTH; j = j + 1)
            q_mem[j] = {DW{1'b0}};
    end

    always @(posedge clk) begin
        if (i_reset) begin
            q_count_o <= {QCW{1'b0}};
            q_rptr_o <= {QAW{1'b0}};
            q_wptr_o <= {QAW{1'b0}};
            flight_o <= {FCW{1'b0}};
            for (j = 0; j < QDEPTH; j = j + 1)
                q_mem[j] <= {DW{1'b0}};
        end else begin
            if (q_push) begin
                q_mem[q_wptr_o] <= a_out_data;
                q_wptr_o <= (q_wptr_o == QLAST) ?
                            {QAW{1'b0}} : q_wptr_o + 1'b1;
            end
            if (q_pop)
                q_rptr_o <= (q_rptr_o == QLAST) ?
                            {QAW{1'b0}} : q_rptr_o + 1'b1;
            case ({q_push, q_pop})
                2'b10: q_count_o <= q_count_o + 1'b1;
                2'b01: q_count_o <= q_count_o - 1'b1;
                default: q_count_o <= q_count_o;
            endcase
            case ({q_push, retire})
                2'b10: flight_o <= flight_o + 1'b1;
                2'b01: flight_o <= flight_o - 1'b1;
                default: flight_o <= flight_o;
            endcase
        end
    end

    always @(posedge clk)
        assert ((q_count_o + b_cnt_o) <= FLIGHT_LIMIT);
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    input  wire         peer_valid,
    output wire         peer_ready,
    input  wire [W-1:0] peer_in_mag,
    input  wire         peer_in_sign,
    output wire         out_peer,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
    localparam CHANNELS = 2, PEER_DEPTH = 4;
    localparam PCW = $clog2(PEER_DEPTH + 1);
    reg [W-1:0] peer_mag [0:PEER_DEPTH-1];
    reg peer_sign [0:PEER_DEPTH-1];
    reg [PCW-1:0] peer_count;
    reg [$clog2(CHANNELS+1)-1:0] grant;
    reg [W-1:0] peer_min1, peer_min2, peer_idx;
    reg peer_parity;
    integer p, j;
    initial begin
        peer_count = 0; grant = 0;
        for (j = 0; j < PEER_DEPTH; j = j + 1) begin peer_mag[j] = {W{1'b1}}; peer_sign[j] = 0; end
    end
    always @(*) begin
        peer_min1 = {W{1'b1}}; peer_min2 = {W{1'b1}}; peer_idx = 0; peer_parity = 0;
        for (p = 0; p < PEER_DEPTH; p = p + 1) begin
            peer_parity = peer_parity ^ peer_sign[p];
            if (peer_mag[p] < peer_min1) begin peer_min2 = peer_min1; peer_min1 = peer_mag[p]; peer_idx = p; end
            else if (peer_mag[p] < peer_min2) peer_min2 = peer_mag[p];
        end
    end

    assign in_ready  = (state == S_ACCUM);
    assign out_valid = (grant != 0) || (state == S_DONE) || (peer_count == PEER_DEPTH);
    assign out_peer = (grant == 2'd2) || ((grant == 0) && (state != S_DONE) && (peer_count == PEER_DEPTH));
    assign peer_ready = (peer_count < PEER_DEPTH);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready && !out_peer;
    wire peer_rel = out_valid && out_ready && out_peer;
    always @(posedge clk) begin
        if (peer_valid && peer_ready) begin
            peer_mag[peer_count] <= peer_in_mag; peer_sign[peer_count] <= peer_in_sign;
            peer_count <= peer_count + 1'b1;
        end else if (peer_rel) peer_count <= 0;
        if (out_valid && !out_ready && (grant == 0)) grant <= out_peer ? 2'd2 : 2'd1;
        else if (out_ready) grant <= 0;
    end

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
            if (in_mag < min1) begin
                min2    <= min1;
                min1    <= in_mag;
                min_idx <= count;
            end else if (in_mag < min2) begin
                min2 <= in_mag;
            end
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = out_peer ? peer_min1 : min1;
    assign out_min2 = out_peer ? peer_min2 : min2;
    assign out_idx  = out_peer ? peer_idx : min_idx;
    assign out_sign = out_peer ? peer_parity : sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
    always @(posedge clk) if (pv && out_valid && out_ready) assert (out_peer ? (peer_count == PEER_DEPTH) : (state == S_DONE));
endmodule

module ntt_phase_dispatch #(
    parameter W = 16,
    parameter PROFILES = 4,
    parameter MAX_BURST = 4
) (
    input  wire clk,
    input  wire cfg_valid,
    output wire cfg_ready,
    input  wire [W-1:0] cfg_data,
    input  wire [W-1:0] profile_select,
    input  wire start,
    input  wire run,
    input  wire finish,
    input  wire [W-1:0] remaining,
    input  wire [W-1:0] launch_latency,
    output reg  [W-1:0] step = 16'd0,
    output reg  [W-1:0] quantum = 16'd1,
    output wire [W*PROFILES-1:0] profiles,
    output reg  [1:0] cfg_state = 2'd0,
    output reg  [$clog2(PROFILES)-1:0] cfg_index = 0,
    output reg  [W-1:0] cfg_pending = 16'd0,
    output reg  [W-1:0] cfg_prepared = 16'd1,
    output wire cfg_apply
);
    localparam INDEX_W = $clog2(PROFILES);
    localparam [INDEX_W-1:0] LAST_PROFILE = PROFILES - 1;
    reg [W-1:0] cap [0:PROFILES-1];
    wire [INDEX_W-1:0] selected = profile_select % PROFILES;
    integer init_profile;
    initial begin
        for (init_profile = 0; init_profile < PROFILES; init_profile = init_profile + 1) begin
            cap[init_profile] = 16'd1;
        end
    end
    genvar p;
    generate
        for (p = 0; p < PROFILES; p = p + 1) begin: expose_profiles
            assign profiles[p*W +: W] = cap[p];
        end
    endgenerate
    assign cfg_ready = (cfg_state == 2'd0);
    assign cfg_apply = (cfg_state == 2'd2);

    function [W-1:0] choose_step;
        input [W-1:0] left;
        input [W-1:0] limit;
        begin
            if (left <= 16'd1)
                choose_step = 16'd1;
            else if (left - 16'd1 < limit)
                choose_step = left - 16'd1;
            else
                choose_step = limit;
        end
    endfunction

    always @(posedge clk) begin
        case (cfg_state)
            2'd0: begin
                if (cfg_valid && cfg_ready) begin
                    cfg_pending <= cfg_data;
                    cfg_state <= 2'd1;
                end
            end
            2'd1: begin
                if (cfg_pending == 16'd0)
                    cfg_prepared <= 16'd1;
                else if (cfg_pending > MAX_BURST)
                    cfg_prepared <= MAX_BURST;
                else
                    cfg_prepared <= cfg_pending;
                cfg_state <= 2'd2;
            end
            2'd2: begin
                cap[cfg_index] <= cfg_prepared;
                if (cfg_index == LAST_PROFILE)
                    cfg_index <= {INDEX_W{1'b0}};
                else
                    cfg_index <= cfg_index + 1'b1;
                cfg_state <= 2'd0;
            end
            default: cfg_state <= 2'd0;
        endcase
    end

    always @(posedge clk) begin
        if (start) begin
            quantum <= cap[selected];
            step <= choose_step(launch_latency, cap[selected]);
        end else if (finish) begin
            step <= 16'd0;
        end else if (run) begin
            step <= choose_step(remaining - step, quantum);
        end
    end
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5,
    parameter DEPTH = 4,
    parameter BURST_PROFILES = 4,
    parameter MAX_BURST = 4,
    parameter JOURNAL_DEPTH = 4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b,
    output wire [$clog2(DEPTH):0] queued,
    output wire         head_cached,
    output wire         cfg_ready,
    output wire         cfg_busy,
    output wire [W-1:0] burst_step,
    output wire [W*BURST_PROFILES-1:0] burst_profiles,
    output wire         journal_ready,
    output wire [$clog2(JOURNAL_DEPTH):0] journal_queued,
    output wire         telemetry_valid,
    output wire [W-1:0] telemetry_stage,
    output wire [W-1:0] telemetry_budget,
    output wire [W-1:0] telemetry_issued,
    output wire [W-1:0] telemetry_saved,
    output wire [W-1:0] telemetry_paused,
    output wire [W*STAGES-1:0] stage_samples,
    output wire [W*STAGES-1:0] stage_budget_totals,
    output wire [W*STAGES-1:0] stage_issue_totals,
    output wire [W*STAGES-1:0] stage_saving_totals,
    output wire [W*STAGES-1:0] stage_pause_totals,
    output wire [W*STAGES-1:0] stage_min_issues,
    output wire [W*STAGES-1:0] stage_max_issues,
    output wire [W*STAGES-1:0] stage_peak_budgets
);
    localparam NBF = NCOEF / 2;
    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W = ADDR_W + 1;
    localparam [ADDR_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam JOURNAL_ADDR_W = $clog2(JOURNAL_DEPTH);
    localparam JOURNAL_PTR_W = JOURNAL_ADDR_W + 1;
    localparam STAGE_ADDR_W = (STAGES > 1) ? $clog2(STAGES) : 1;
    localparam [JOURNAL_ADDR_W-1:0] LAST_JOURNAL = JOURNAL_DEPTH - 1;
    localparam [1:0] AUDIT_IDLE = 2'd0;
    localparam [1:0] AUDIT_MEASURE = 2'd1;
    localparam [1:0] AUDIT_ACCUMULATE = 2'd2;
    localparam [1:0] AUDIT_COMMIT = 2'd3;

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    reg [W-1:0] q_a [0:DEPTH-1];
    reg [W-1:0] q_b [0:DEPTH-1];
    reg [W-1:0] q_w [0:DEPTH-1];
    reg [W-1:0] q_lat [0:DEPTH-1];
    reg [PTR_W-1:0] q_wr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] q_rd = {PTR_W{1'b0}};
    reg head_valid = 1'b0;
    reg [W-1:0] issued_steps = 16'd0;
    reg [W-1:0] pause_cycles = 16'd0;
    reg [W-1:0] event_budget [0:JOURNAL_DEPTH-1];
    reg [W-1:0] event_issued [0:JOURNAL_DEPTH-1];
    reg [W-1:0] event_paused [0:JOURNAL_DEPTH-1];
    reg [STAGE_ADDR_W-1:0] event_stage [0:JOURNAL_DEPTH-1];
    reg [JOURNAL_PTR_W-1:0] journal_wr = {JOURNAL_PTR_W{1'b0}};
    reg [JOURNAL_PTR_W-1:0] journal_rd = {JOURNAL_PTR_W{1'b0}};
    reg [1:0] audit_state = AUDIT_IDLE;
    reg [W-1:0] audit_budget = 16'd1;
    reg [W-1:0] audit_issued = 16'd1;
    reg [W-1:0] audit_saved = 16'd0;
    reg [W-1:0] audit_paused = 16'd0;
    reg [STAGE_ADDR_W-1:0] audit_tag = {STAGE_ADDR_W{1'b0}};
    reg [W-1:0] pending_samples = 16'd0;
    reg [W-1:0] pending_budget = 16'd0;
    reg [W-1:0] pending_issued = 16'd0;
    reg [W-1:0] pending_saved = 16'd0;
    reg [W-1:0] pending_paused = 16'd0;
    reg [W-1:0] pending_min = 16'd0;
    reg [W-1:0] pending_max = 16'd0;
    reg [W-1:0] pending_peak_budget = 16'd0;
    reg [W-1:0] stat_samples [0:STAGES-1];
    reg [W-1:0] stat_budget [0:STAGES-1];
    reg [W-1:0] stat_issued [0:STAGES-1];
    reg [W-1:0] stat_saved [0:STAGES-1];
    reg [W-1:0] stat_paused [0:STAGES-1];
    reg [W-1:0] stat_min [0:STAGES-1];
    reg [W-1:0] stat_max [0:STAGES-1];
    reg [W-1:0] stat_peak_budget [0:STAGES-1];
    integer init_journal;
    integer init_stat;
    wire [JOURNAL_ADDR_W-1:0] journal_head = journal_rd[JOURNAL_ADDR_W-1:0];
    wire journal_empty = (journal_wr == journal_rd);
    wire journal_full = (journal_wr[JOURNAL_ADDR_W] != journal_rd[JOURNAL_ADDR_W]) &&
                        (journal_wr[JOURNAL_ADDR_W-1:0] == journal_rd[JOURNAL_ADDR_W-1:0]);
    wire journal_pop = ce && (audit_state == AUDIT_IDLE) &&
                       !journal_empty;
    wire [JOURNAL_PTR_W:0] telemetry_held;
    integer init_slot;
    wire [ADDR_W-1:0] head_slot = q_rd[ADDR_W-1:0];
    wire q_empty = (q_wr == q_rd);
    wire q_full = (q_wr[ADDR_W] != q_rd[ADDR_W]) &&
                  (q_wr[ADDR_W-1:0] == q_rd[ADDR_W-1:0]);
    initial begin
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            q_a[init_slot] = 16'd0;
            q_b[init_slot] = 16'd0;
            q_w[init_slot] = 16'd0;
            q_lat[init_slot] = 16'd0;
        end
    end
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end
    initial begin
        for (init_journal = 0; init_journal < JOURNAL_DEPTH; init_journal = init_journal + 1) begin
            event_budget[init_journal] = 16'd0;
            event_issued[init_journal] = 16'd0;
            event_paused[init_journal] = 16'd0;
            event_stage[init_journal] = {STAGE_ADDR_W{1'b0}};
        end
        for (init_stat = 0; init_stat < STAGES; init_stat = init_stat + 1) begin
            stat_samples[init_stat] = 16'd0;
            stat_budget[init_stat] = 16'd0;
            stat_issued[init_stat] = 16'd0;
            stat_saved[init_stat] = 16'd0;
            stat_paused[init_stat] = 16'd0;
            stat_min[init_stat] = 16'd0;
            stat_max[init_stat] = 16'd0;
            stat_peak_budget[init_stat] = 16'd0;
        end
    end
    function [W-1:0] saturated_add;
        input [W-1:0] left;
        input [W-1:0] right;
        reg [W:0] total;
        begin
            total = {1'b0, left} + {1'b0, right};
            if (total[W])
                saturated_add = {W{1'b1}};
            else
                saturated_add = total[W-1:0];
        end
    endfunction
    assign queued = (q_wr[ADDR_W] == q_rd[ADDR_W]) ?
        ({1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]}) :
        (DEPTH + {1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]});
    assign head_cached = head_valid;
    assign journal_ready = !journal_full;
    assign journal_queued = (journal_wr[JOURNAL_ADDR_W] == journal_rd[JOURNAL_ADDR_W]) ?
        ({1'b0, journal_wr[JOURNAL_ADDR_W-1:0]} - {1'b0, journal_rd[JOURNAL_ADDR_W-1:0]}) :
        (JOURNAL_DEPTH + {1'b0, journal_wr[JOURNAL_ADDR_W-1:0]} - {1'b0, journal_rd[JOURNAL_ADDR_W-1:0]});
    assign telemetry_held = {1'b0, journal_queued} +
        ((audit_state != AUDIT_IDLE) ? 1'b1 : 1'b0);
    assign telemetry_valid = ce && (audit_state == AUDIT_COMMIT);
    assign telemetry_stage = audit_tag;
    assign telemetry_budget = audit_budget;
    assign telemetry_issued = audit_issued;
    assign telemetry_saved = audit_saved;
    assign telemetry_paused = audit_paused;
    genvar s;
    generate
        for (s = 0; s < STAGES; s = s + 1) begin: expose_stage_statistics
            assign stage_samples[s*W +: W] = stat_samples[s];
            assign stage_budget_totals[s*W +: W] = stat_budget[s];
            assign stage_issue_totals[s*W +: W] = stat_issued[s];
            assign stage_saving_totals[s*W +: W] = stat_saved[s];
            assign stage_pause_totals[s*W +: W] = stat_paused[s];
            assign stage_min_issues[s*W +: W] = stat_min[s];
            assign stage_max_issues[s*W +: W] = stat_max[s];
            assign stage_peak_budgets[s*W +: W] = stat_peak_budget[s];
        end
    endgenerate

    assign in_ready = !q_full;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);
    wire cache_read = ce && !head_valid && !q_empty;
    wire bypass_head = ce && accept && q_empty;
    wire start = ce && head_valid && !busy && !out_valid;
    wire retire = busy && ce && last && journal_ready;
    wire [W-1:0] burst_quantum;
    wire [1:0] cfg_state;
    wire [$clog2(BURST_PROFILES)-1:0] cfg_write_index;
    wire [W-1:0] cfg_pending;
    wire [W-1:0] cfg_prepared;
    wire cfg_apply;
    assign cfg_busy = (cfg_state != 2'd0);

    ntt_phase_dispatch #(
        .W(W), .PROFILES(BURST_PROFILES), .MAX_BURST(MAX_BURST)
    ) phase_dispatch (
        .clk(clk), .cfg_valid(load_cfg), .cfg_ready(cfg_ready),
        .cfg_data(cfg_lat), .profile_select(stage),
        .start(start), .run(busy && ce && !last), .finish(retire),
        .remaining(cd), .launch_latency(lat_q),
        .step(burst_step), .quantum(burst_quantum),
        .profiles(burst_profiles), .cfg_state(cfg_state),
        .cfg_index(cfg_write_index), .cfg_pending(cfg_pending),
        .cfg_prepared(cfg_prepared), .cfg_apply(cfg_apply)
    );

    wire [31:0] prod = w_r * b_r;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];
    always @(posedge clk) begin
        if (accept) begin
            q_a[q_wr[ADDR_W-1:0]] <= in_a;
            q_b[q_wr[ADDR_W-1:0]] <= in_b;
            q_w[q_wr[ADDR_W-1:0]] <= in_w;
            q_lat[q_wr[ADDR_W-1:0]] <= lat_eff;
            if (q_wr[ADDR_W-1:0] == LAST_SLOT)
                q_wr <= {!q_wr[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_wr <= q_wr + 1'b1;
        end
        if (retire) begin
            if (q_rd[ADDR_W-1:0] == LAST_SLOT)
                q_rd <= {!q_rd[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_rd <= q_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (cache_read) begin
            a_r <= q_a[head_slot];
            b_r <= q_b[head_slot];
            w_r <= q_w[head_slot];
            lat_q <= q_lat[head_slot];
            head_valid <= 1'b1;
        end else if (bypass_head) begin
            a_r <= in_a;
            b_r <= in_b;
            w_r <= in_w;
            lat_q <= lat_eff;
            head_valid <= 1'b1;
        end else if (retire) begin
            head_valid <= 1'b0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (cfg_apply) lat_cfg <= cfg_pending;
        if (start) begin
            cd    <= lat_q;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
        end else if (busy && ce && (!last || journal_ready)) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - burst_step;
                phase <= phase + burst_step;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end
    always @(posedge clk) begin
        if (start || retire) begin
            issued_steps <= 16'd0;
            pause_cycles <= 16'd0;
        end else if (busy) begin
            if (ce && !last)
                issued_steps <= issued_steps + 16'd1;
            if (!ce && !last)
                pause_cycles <= saturated_add(pause_cycles, 16'd1);
        end
    end
    always @(posedge clk) begin
        if (retire) begin
            event_budget[journal_wr[JOURNAL_ADDR_W-1:0]] <= lat_q;
            event_issued[journal_wr[JOURNAL_ADDR_W-1:0]] <= issued_steps + 16'd1;
            event_paused[journal_wr[JOURNAL_ADDR_W-1:0]] <= pause_cycles;
            event_stage[journal_wr[JOURNAL_ADDR_W-1:0]] <= stage[STAGE_ADDR_W-1:0];
            if (journal_wr[JOURNAL_ADDR_W-1:0] == LAST_JOURNAL)
                journal_wr <= {!journal_wr[JOURNAL_ADDR_W], {JOURNAL_ADDR_W{1'b0}}};
            else
                journal_wr <= journal_wr + 1'b1;
        end
        if (journal_pop) begin
            if (journal_rd[JOURNAL_ADDR_W-1:0] == LAST_JOURNAL)
                journal_rd <= {!journal_rd[JOURNAL_ADDR_W], {JOURNAL_ADDR_W{1'b0}}};
            else
                journal_rd <= journal_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (ce) begin
            case (audit_state)
                AUDIT_IDLE: begin
                    if (journal_pop) begin
                        audit_budget <= event_budget[journal_head];
                        audit_issued <= event_issued[journal_head];
                        audit_paused <= event_paused[journal_head];
                        audit_tag <= event_stage[journal_head];
                        audit_state <= AUDIT_MEASURE;
                    end
                end
                AUDIT_MEASURE: begin
                    audit_saved <= audit_budget - audit_issued;
                    audit_state <= AUDIT_ACCUMULATE;
                end
                AUDIT_ACCUMULATE: begin
                    pending_samples <= saturated_add(
                        stat_samples[audit_tag], 16'd1);
                    pending_budget <= saturated_add(
                        stat_budget[audit_tag], audit_budget);
                    pending_issued <= saturated_add(
                        stat_issued[audit_tag], audit_issued);
                    pending_saved <= saturated_add(
                        stat_saved[audit_tag], audit_saved);
                    pending_paused <= saturated_add(
                        stat_paused[audit_tag], audit_paused);
                    if ((stat_min[audit_tag] == 16'd0) ||
                        (audit_issued < stat_min[audit_tag]))
                        pending_min <= audit_issued;
                    else
                        pending_min <= stat_min[audit_tag];
                    if (audit_issued > stat_max[audit_tag])
                        pending_max <= audit_issued;
                    else
                        pending_max <= stat_max[audit_tag];
                    if (audit_budget > stat_peak_budget[audit_tag])
                        pending_peak_budget <= audit_budget;
                    else
                        pending_peak_budget <= stat_peak_budget[audit_tag];
                    audit_state <= AUDIT_COMMIT;
                end
                AUDIT_COMMIT: begin
                    stat_samples[audit_tag] <= pending_samples;
                    stat_budget[audit_tag] <= pending_budget;
                    stat_issued[audit_tag] <= pending_issued;
                    stat_saved[audit_tag] <= pending_saved;
                    stat_paused[audit_tag] <= pending_paused;
                    stat_min[audit_tag] <= pending_min;
                    stat_max[audit_tag] <= pending_max;
                    stat_peak_budget[audit_tag] <= pending_peak_budget;
                    audit_state <= AUDIT_IDLE;
                end
                default: audit_state <= AUDIT_IDLE;
            endcase
        end
    end
    always @(posedge clk) begin
        if (telemetry_valid)
            assert ((audit_saved < audit_budget) &&
                    (audit_tag < STAGES));
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

module ldpc_edge_ingress #(
    parameter W = 32,
    parameter FRAME = 24,
    parameter DEPTH = 4,
    parameter IW = $clog2(FRAME),
    parameter CW = $clog2(DEPTH + 1)
) (
    input wire clk,
    input wire offer,
    output wire ready,
    input wire [W-1:0] mag_i,
    input wire sign_i,
    input wire take,
    output wire valid,
    output wire [W-1:0] mag_o,
    output wire sign_o,
    output wire [IW-1:0] index_o,
    output reg [CW-1:0] queued,
    output reg [IW-1:0] next_idx,
    output wire [DEPTH*IW-1:0] queued_idx
);
    reg [W-1:0] magnitude [0:DEPTH-1];
    reg polarity [0:DEPTH-1];
    reg [IW-1:0] edge_index [0:DEPTH-1];
    integer i, n;
    wire pop = valid && take;
    wire push = offer && ready;
    assign valid = (queued != 0);
    assign ready = (queued < DEPTH) || pop;
    assign mag_o = magnitude[0];
    assign sign_o = polarity[0];
    assign index_o = edge_index[0];
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin: export_tags
            assign queued_idx[g*IW +: IW] = edge_index[g];
        end
    endgenerate
    initial begin
        queued = 0;
        next_idx = 0;
        for (n = 0; n < DEPTH; n = n + 1) begin
            magnitude[n] = {W{1'b0}};
            polarity[n] = 1'b0;
            edge_index[n] = 0;
        end
    end
    always @(posedge clk) begin
        case ({push, pop})
            2'b10: queued <= queued + 1'b1;
            2'b01: queued <= queued - 1'b1;
            default: queued <= queued;
        endcase
        if (pop) begin
            for (i = 0; i < DEPTH-1; i = i + 1) begin
                magnitude[i] <= magnitude[i+1];
                polarity[i] <= polarity[i+1];
                edge_index[i] <= edge_index[i+1];
            end
        end
        if (push) begin
            magnitude[queued - pop] <= mag_i;
            polarity[queued - pop] <= sign_i;
            edge_index[queued - pop] <= next_idx;
            if (next_idx == FRAME - 1)
                next_idx <= 0;
            else
                next_idx <= next_idx + 1'b1;
        end
    end
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    input  wire         peer_valid,
    output wire         peer_ready,
    input  wire [W-1:0] peer_in_mag,
    input  wire         peer_in_sign,
    output wire         out_peer,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] pending_edges
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
    localparam CHANNELS = 2, PEER_DEPTH = 4;
    localparam PCW = $clog2(PEER_DEPTH + 1);
    reg [W-1:0] peer_mag [0:PEER_DEPTH-1];
    reg peer_sign [0:PEER_DEPTH-1];
    reg [PCW-1:0] peer_count;
    reg [$clog2(CHANNELS+1)-1:0] grant;
    reg [W-1:0] peer_min1, peer_min2, peer_idx;
    reg peer_parity;
    integer p, j;
    initial begin
        peer_count = 0; grant = 0;
        for (j = 0; j < PEER_DEPTH; j = j + 1) begin peer_mag[j] = {W{1'b1}}; peer_sign[j] = 0; end
    end
    always @(*) begin
        peer_min1 = {W{1'b1}}; peer_min2 = {W{1'b1}}; peer_idx = 0; peer_parity = 0;
        for (p = 0; p < PEER_DEPTH; p = p + 1) begin
            peer_parity = peer_parity ^ peer_sign[p];
            if (peer_mag[p] < peer_min1) begin peer_min2 = peer_min1; peer_min1 = peer_mag[p]; peer_idx = p; end
            else if (peer_mag[p] < peer_min2) peer_min2 = peer_mag[p];
        end
    end

    localparam IIW = $clog2(DEG);
    wire ingress_valid, ingress_sign;
    wire [W-1:0] ingress_mag;
    wire [IIW-1:0] ingress_idx, ingress_next_idx;
    wire [INGRESS_DEPTH*IIW-1:0] ingress_tags;
    wire ingress_take = (state == S_ACCUM);
    ldpc_edge_ingress #(
        .W(W), .FRAME(DEG), .DEPTH(INGRESS_DEPTH)
    ) ingress (
        .clk(clk), .offer(in_valid), .ready(in_ready),
        .mag_i(in_mag), .sign_i(in_sign), .take(ingress_take),
        .valid(ingress_valid), .mag_o(ingress_mag),
        .sign_o(ingress_sign), .index_o(ingress_idx),
        .queued(pending_edges), .next_idx(ingress_next_idx),
        .queued_idx(ingress_tags)
    );
    assign out_valid = (grant != 0) || (state == S_DONE) || (peer_count == PEER_DEPTH);
    assign out_peer = (grant == 2'd2) || ((grant == 0) && (state != S_DONE) && (peer_count == PEER_DEPTH));
    assign peer_ready = (peer_count < PEER_DEPTH);
    wire acc = ingress_valid && ingress_take;
    wire rel = out_valid && out_ready && !out_peer;
    wire peer_rel = out_valid && out_ready && out_peer;
    always @(posedge clk) begin
        if (peer_valid && peer_ready) begin
            peer_mag[peer_count] <= peer_in_mag; peer_sign[peer_count] <= peer_in_sign;
            peer_count <= peer_count + 1'b1;
        end else if (peer_rel) peer_count <= 0;
        if (out_valid && !out_ready && (grant == 0)) grant <= out_peer ? 2'd2 : 2'd1;
        else if (out_ready) grant <= 0;
    end

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ ingress_sign;
            if (ingress_mag < min1) begin
                min2    <= min1;
                min1    <= ingress_mag;
                min_idx <= ingress_idx;
            end else if (ingress_mag < min2) begin
                min2 <= ingress_mag;
            end
            if (ingress_idx == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = out_peer ? peer_min1 : min1;
    assign out_min2 = out_peer ? peer_min2 : min2;
    assign out_idx  = out_peer ? peer_idx : min_idx;
    assign out_sign = out_peer ? peer_parity : sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
    always @(posedge clk) if (pv && out_valid && out_ready) assert (out_peer ? (peer_count == PEER_DEPTH) : (state == S_DONE));
    always @(posedge clk) if (pv && rel && ingress_valid) assert (ingress_idx == 0);
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted,
    output reg [31:0] debug_status
,
    output wire [W-1:0] in_cnt_o,
    output wire [W-1:0] out_cnt_o
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;
    reg [31:0] dbg_cycles, dbg_input_stalls, dbg_output_stalls;
    reg [31:0] dbg_frames, dbg_cfg_writes;
    reg [15:0] dbg_stall_run, dbg_stall_max, dbg_idle_age;
    reg [7:0] dbg_high_water;
    reg [3:0] dbg_flags;
    reg dbg_enable;
    wire dbg_input_blocked = i_valid && !i_ready;
    wire dbg_output_blocked = o_valid && !o_ready;
    wire dbg_clear = cfg_we && (cfg_addr == 4'd15) && cfg_data[0];
    initial begin
        dbg_cycles = 32'd0;
        dbg_input_stalls = 32'd0;
        dbg_output_stalls = 32'd0;
        dbg_frames = 32'd0;
        dbg_cfg_writes = 32'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_max = 16'd0;
        dbg_idle_age = 16'd0;
        dbg_high_water = 8'd0;
        dbg_flags = 4'd0;
        dbg_enable = 1'b1;
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (rst) begin
            dbg_cycles <= 32'd0;
            dbg_input_stalls <= 32'd0;
            dbg_output_stalls <= 32'd0;
            dbg_frames <= 32'd0;
            dbg_cfg_writes <= 32'd0;
            dbg_stall_run <= 16'd0;
            dbg_stall_max <= 16'd0;
            dbg_idle_age <= 16'd0;
            dbg_high_water <= 8'd0;
            dbg_flags <= 4'd0;
            dbg_enable <= 1'b1;
            debug_status <= 32'd0;
        end else begin
            if (cfg_we && cfg_addr == 4'd9)
                dbg_enable <= cfg_data[0];
            if (dbg_clear) begin
                dbg_cycles <= 32'd0;
                dbg_input_stalls <= 32'd0;
                dbg_output_stalls <= 32'd0;
                dbg_frames <= 32'd0;
                dbg_cfg_writes <= 32'd0;
                dbg_stall_run <= 16'd0;
                dbg_stall_max <= 16'd0;
                dbg_idle_age <= 16'd0;
                dbg_high_water <= 8'd0;
                dbg_flags <= 4'd0;
            end else if (dbg_enable) begin
                if (!(&dbg_cycles))
                    dbg_cycles <= dbg_cycles + 32'd1;
                if (dbg_input_blocked && !(&dbg_input_stalls))
                    dbg_input_stalls <= dbg_input_stalls + 32'd1;
                if (dbg_output_blocked && !(&dbg_output_stalls))
                    dbg_output_stalls <= dbg_output_stalls + 32'd1;
                if (out_fire && o_last && !(&dbg_frames))
                    dbg_frames <= dbg_frames + 32'd1;
                if (cfg_we && cfg_addr <= 4'd8 && !(&dbg_cfg_writes))
                    dbg_cfg_writes <= dbg_cfg_writes + 32'd1;
                if (ingress_level > dbg_high_water)
                    dbg_high_water <= (ingress_level > 255) ? 8'hff : ingress_level;
                if (dbg_output_blocked) begin
                    if (!(&dbg_stall_run))
                        dbg_stall_run <= dbg_stall_run + 16'd1;
                    if (dbg_stall_run >= dbg_stall_max && !(&dbg_stall_run))
                        dbg_stall_max <= dbg_stall_run + 16'd1;
                end else
                    dbg_stall_run <= 16'd0;
                if ((ingress_valid || o_valid) && !out_fire) begin
                    if (!(&dbg_idle_age))
                        dbg_idle_age <= dbg_idle_age + 16'd1;
                    if (&dbg_idle_age)
                        dbg_flags[2] <= 1'b1;
                end else
                    dbg_idle_age <= 16'd0;
                if (dbg_input_blocked)
                    dbg_flags[0] <= 1'b1;
                if (dbg_output_blocked)
                    dbg_flags[1] <= 1'b1;
                if (cfg_we && armed)
                    dbg_flags[3] <= 1'b1;
            end
            case (cfg_addr)
                4'd9: debug_status <= {31'd0, dbg_enable};
                4'd10: debug_status <= dbg_cycles;
                4'd11: debug_status <= dbg_input_stalls;
                4'd12: debug_status <= dbg_output_stalls;
                4'd13: debug_status <= dbg_frames;
                4'd14: debug_status <= {dbg_stall_max, dbg_stall_run};
                4'd15: debug_status <= {dbg_high_water, dbg_flags, 4'd0, dbg_idle_age};
                default: debug_status <= dbg_cfg_writes;
            endcase
        end
    end

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
    assign in_cnt_o = in_cnt;
    assign out_cnt_o = out_cnt;
endmodule

module transpose_buf #(
    parameter ROWS  = 4,
    parameter COLS  = 8,
    parameter DEPTH = ROWS * COLS,
    parameter DW    = 32
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data
,
    output wire [1:0] chain_o,
    output wire phase_o,
    output wire [31:0] rd_col_o,
    output wire [31:0] rd_row_o,
    output wire [31:0] wr_col_o,
    output wire [31:0] wr_row_o
);
    localparam AW = $clog2(DEPTH);
    localparam [1:0] C_IDLE  = 2'd0;
    localparam [1:0] C_ARM   = 2'd1;
    localparam [1:0] C_START = 2'd2;
    localparam PH_FILL  = 1'b0;
    localparam PH_DRAIN = 1'b1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg        phase    = 1'b0;
    reg [31:0] wr_row   = 32'd0;
    reg [31:0] wr_col   = 32'd0;
    reg [31:0] rd_row   = 32'd0;
    reg [31:0] rd_col   = 32'd0;
    reg [1:0]  chain    = 2'd0;
    reg        before_r = 1'b1;
    reg        pv       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = {DW{1'b0}};
    end

    assign in_ready  = (phase == PH_FILL);
    assign out_valid = (phase == PH_DRAIN);

    wire wr_fire = in_valid && in_ready;
    wire rd_fire = out_valid && out_ready;
    wire wr_last = (wr_row == ROWS - 1) && (wr_col == COLS - 1);
    wire rd_last = (rd_row == ROWS - 1) && (rd_col == COLS - 1);

    wire [31:0] wr_addr = wr_row * COLS + wr_col;
    wire [31:0] rd_addr = rd_row * COLS + rd_col;

    assign out_data = mem[rd_addr[AW-1:0]];

    // row-order write into the tile
    always @(posedge clk) begin
        if (wr_fire)
            mem[wr_addr[AW-1:0]] <= in_data;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase    <= PH_FILL;
            wr_row   <= 32'd0;
            wr_col   <= 32'd0;
            rd_row   <= 32'd0;
            rd_col   <= 32'd0;
            chain    <= C_IDLE;
            before_r <= 1'b1;
        end else begin
            if (wr_fire) begin
                if (wr_col == COLS - 1) begin
                    wr_col <= 32'd0;
                    if (wr_row == ROWS - 1) wr_row <= 32'd0;
                    else                    wr_row <= wr_row + 32'd1;
                end else begin
                    wr_col <= wr_col + 32'd1;
                end
                if (wr_last) begin
                    phase <= PH_DRAIN;
                    chain <= C_START;
                end else if (chain == C_IDLE) begin
                    chain <= C_ARM;
                end
            end
            // column-order read out of the tile
            if (rd_fire) begin
                if (rd_row == ROWS - 1) begin
                    rd_row <= 32'd0;
                    if (rd_col == COLS - 1) rd_col <= 32'd0;
                    else                    rd_col <= rd_col + 32'd1;
                end else begin
                    rd_row <= rd_row + 32'd1;
                end
                if (rd_last) begin
                    phase    <= PH_FILL;
                    chain    <= C_IDLE;
                    before_r <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    // Chain precedence (arm -> start -> finish), before first tile completes:
    // while the chain FSM sits unchanged short of START, no column-order read may advance.
    always @(posedge clk) begin
        if (pv && before_r && $stable(chain) && chain != C_START)
            assert ($stable(rd_row) && $stable(rd_col));
    end
    assign chain_o = chain;
    assign phase_o = phase;
    assign rd_col_o = rd_col;
    assign rd_row_o = rd_row;
    assign wr_col_o = wr_col;
    assign wr_row_o = wr_row;
endmodule

module rgb_ycc_tile_pipeline #(
    parameter INGRESS_DEPTH = 4,
    parameter BRIDGE_DEPTH = 4,
    parameter TILE_ROWS = 4,
    parameter TILE_COLS = 4
) (
    input wire clk,
    input wire rst,
    input wire cfg_we,
    input wire [3:0] cfg_addr,
    input wire [31:0] cfg_data,
    input wire i_valid,
    output wire i_ready,
    input wire [7:0] i_r, i_g, i_b,
    input wire i_first, i_last,
    output wire o_valid,
    input wire o_ready,
    output wire [23:0] o_data,
    output wire a_o_valid, a_o_ready,
    output wire [7:0] a_o_y, a_o_cb, a_o_cr,
    output wire a_o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] a_ingress_level,
    output wire [31:0] a_ingress_accepted,
    output wire [31:0] a_in_cnt, a_out_cnt,
    output wire [31:0] a_debug_status,
    output wire b_in_valid, b_in_ready,
    output wire [1:0] b_chain,
    output wire b_phase,
    output wire [31:0] b_rd_col, b_rd_row, b_wr_col, b_wr_row,
    output reg [$clog2(BRIDGE_DEPTH+1)-1:0] bridge_level,
    output reg [31:0] delivered_pixels,
    output wire [31:0] tile_held,
    output wire [31:0] pending_pixels,
    output reg pipeline_active,
    output wire busy
);
    localparam TILE_PIXELS = TILE_ROWS * TILE_COLS;
    localparam TOTAL_CAPACITY = INGRESS_DEPTH + 1 + BRIDGE_DEPTH + TILE_PIXELS;
    localparam BRIDGE_PTR_W = $clog2(BRIDGE_DEPTH);
    wire rst_n = !rst;
    reg [23:0] bridge_mem [0:BRIDGE_DEPTH-1];
    reg [BRIDGE_PTR_W-1:0] bridge_rd_ptr, bridge_wr_ptr;
    wire [23:0] b_in_data = bridge_mem[bridge_rd_ptr];
    wire bridge_push = a_o_valid && a_o_ready;
    wire bridge_pop = b_in_valid && b_in_ready;
    wire sink_fire = o_valid && o_ready;
    integer j;

    // A completed tile blocks its input until column-order draining finishes.
    assign b_in_valid = pipeline_active && (bridge_level != 0);
    assign a_o_ready = pipeline_active &&
                       ((bridge_level < BRIDGE_DEPTH) || bridge_pop);
    assign tile_held = b_phase
                     ? TILE_PIXELS - (b_rd_col * TILE_ROWS + b_rd_row)
                     : b_wr_row * TILE_COLS + b_wr_col;
    assign pending_pixels = a_ingress_accepted - delivered_pixels;
    assign busy = !pipeline_active || (a_ingress_level != 0) ||
                  a_o_valid || (bridge_level != 0) || (tile_held != 0);

    csc_rgb2ycc #(.W(32), .FRAC(16), .INGRESS_DEPTH(INGRESS_DEPTH)) color (
        .clk(clk), .rst(rst),
        .cfg_we(cfg_we), .cfg_addr(cfg_addr), .cfg_data(cfg_data),
        .i_valid(i_valid), .i_ready(i_ready),
        .i_r(i_r), .i_g(i_g), .i_b(i_b),
        .i_first(i_first), .i_last(i_last),
        .o_valid(a_o_valid), .o_ready(a_o_ready),
        .o_y(a_o_y), .o_cb(a_o_cb), .o_cr(a_o_cr), .o_last(a_o_last),
        .ingress_level(a_ingress_level), .ingress_accepted(a_ingress_accepted),
        .debug_status(a_debug_status), .in_cnt_o(a_in_cnt), .out_cnt_o(a_out_cnt)
    );
    transpose_buf #(
        .ROWS(TILE_ROWS), .COLS(TILE_COLS), .DEPTH(TILE_PIXELS), .DW(24)
    ) tile (
        .clk(clk), .rst_n(rst_n),
        .in_valid(b_in_valid), .in_ready(b_in_ready), .in_data(b_in_data),
        .out_valid(o_valid), .out_ready(o_ready), .out_data(o_data),
        .chain_o(b_chain), .phase_o(b_phase),
        .rd_col_o(b_rd_col), .rd_row_o(b_rd_row),
        .wr_col_o(b_wr_col), .wr_row_o(b_wr_row)
    );

    initial begin
        pipeline_active = 1'b0;
        bridge_level = 0;
        delivered_pixels = 32'd0;
        bridge_rd_ptr = {BRIDGE_PTR_W{1'b0}};
        bridge_wr_ptr = {BRIDGE_PTR_W{1'b0}};
        for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
            bridge_mem[j] = 24'd0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipeline_active <= 1'b0;
            bridge_level <= 0;
            delivered_pixels <= 32'd0;
            bridge_rd_ptr <= {BRIDGE_PTR_W{1'b0}};
            bridge_wr_ptr <= {BRIDGE_PTR_W{1'b0}};
            for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
                bridge_mem[j] <= 24'd0;
        end else begin
            pipeline_active <= 1'b1;
            case ({bridge_push, bridge_pop})
                2'b10: bridge_level <= bridge_level + 1'b1;
                2'b01: bridge_level <= bridge_level - 1'b1;
                default: ;
            endcase
            if (bridge_push) begin
                bridge_mem[bridge_wr_ptr] <= {a_o_y, a_o_cb, a_o_cr};
                bridge_wr_ptr <= (bridge_wr_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_wr_ptr + 1'b1;
            end
            if (bridge_pop)
                bridge_rd_ptr <= (bridge_rd_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_rd_ptr + 1'b1;
            if (sink_fire)
                delivered_pixels <= delivered_pixels + 32'd1;
        end
    end

    always @(posedge clk) begin
        if (pipeline_active)
            assert (pending_pixels <= TOTAL_CAPACITY);
    end
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5,
parameter DEPTH = 4,
parameter TRACE_DEPTH = 4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b,
    output wire [$clog2(DEPTH):0] queued,
output wire         head_cached,
output wire         trace_valid,
output reg  [W-1:0] trace_data,
output wire [2:0]   trace_kind,
output wire         trace_last,
output wire [$clog2(TRACE_DEPTH):0] trace_pending,
output wire         completion_wait
);
    localparam NBF = NCOEF / 2;
    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W = ADDR_W + 1;
    localparam [ADDR_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam TRACE_ADDR_W = $clog2(TRACE_DEPTH);
    localparam TRACE_PTR_W = TRACE_ADDR_W + 1;
    localparam [TRACE_ADDR_W-1:0] TRACE_LAST_SLOT = TRACE_DEPTH - 1;
    localparam TRACE_WORDS = 8;
    localparam TRACE_WORD_W = $clog2(TRACE_WORDS);

    reg [W-1:0] trace_stage_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_bf_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_a_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_b_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_w_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_cycles_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_sum_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_dif_mem [0:TRACE_DEPTH-1];
    reg [TRACE_PTR_W-1:0] trace_wr = {TRACE_PTR_W{1'b0}};
    reg [TRACE_PTR_W-1:0] trace_rd = {TRACE_PTR_W{1'b0}};
    reg [W-1:0] trace_stage_r = 16'd0;
    reg [W-1:0] trace_bf_r = 16'd0;
    reg [W-1:0] trace_a_r = 16'd0;
    reg [W-1:0] trace_b_r = 16'd0;
    reg [W-1:0] trace_w_r = 16'd0;
    reg [W-1:0] trace_cycles_r = 16'd0;
    reg [W-1:0] trace_sum_r = 16'd0;
    reg [W-1:0] trace_dif_r = 16'd0;
    reg trace_active = 1'b0;
    reg [TRACE_WORD_W-1:0] trace_word = {TRACE_WORD_W{1'b0}};
    integer trace_init;

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    reg [W-1:0] q_a [0:DEPTH-1];
    reg [W-1:0] q_b [0:DEPTH-1];
    reg [W-1:0] q_w [0:DEPTH-1];
    reg [W-1:0] q_lat [0:DEPTH-1];
    reg [PTR_W-1:0] q_wr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] q_rd = {PTR_W{1'b0}};
    reg head_valid = 1'b0;
    integer init_slot;
    wire [ADDR_W-1:0] head_slot = q_rd[ADDR_W-1:0];
    wire q_empty = (q_wr == q_rd);
    wire q_full = (q_wr[ADDR_W] != q_rd[ADDR_W]) &&
                  (q_wr[ADDR_W-1:0] == q_rd[ADDR_W-1:0]);
    initial begin
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            q_a[init_slot] = 16'd0;
            q_b[init_slot] = 16'd0;
            q_w[init_slot] = 16'd0;
            q_lat[init_slot] = 16'd0;
        end
    end
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end
    assign queued = (q_wr[ADDR_W] == q_rd[ADDR_W]) ?
        ({1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]}) :
        (DEPTH + {1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]});
    assign head_cached = head_valid;

    wire [TRACE_ADDR_W-1:0] trace_head_slot = trace_rd[TRACE_ADDR_W-1:0];
    wire [TRACE_ADDR_W-1:0] trace_tail_slot =
        (trace_wr[TRACE_ADDR_W-1:0] == 0) ? TRACE_LAST_SLOT : trace_wr[TRACE_ADDR_W-1:0] - 1'b1;
    wire trace_empty = (trace_wr == trace_rd);
    wire trace_full = (trace_wr[TRACE_ADDR_W] != trace_rd[TRACE_ADDR_W]) &&
                      (trace_wr[TRACE_ADDR_W-1:0] == trace_rd[TRACE_ADDR_W-1:0]);
    wire trace_load = ce && !trace_active && !trace_empty;
    wire trace_beat = trace_active && out_ready;
    wire trace_pop = trace_beat && trace_last;
    assign trace_valid = trace_active;
    assign trace_kind = trace_word;
    assign trace_last = (trace_word == TRACE_WORDS - 1);
    assign completion_wait = busy && trace_full && (phase == lat_q - 16'd1);
    assign trace_pending = (trace_wr[TRACE_ADDR_W] == trace_rd[TRACE_ADDR_W]) ?
        ({1'b0, trace_wr[TRACE_ADDR_W-1:0]} - {1'b0, trace_rd[TRACE_ADDR_W-1:0]}) :
        (TRACE_DEPTH + {1'b0, trace_wr[TRACE_ADDR_W-1:0]} - {1'b0, trace_rd[TRACE_ADDR_W-1:0]});

    initial begin
        for (trace_init = 0; trace_init < TRACE_DEPTH; trace_init = trace_init + 1) begin
            trace_stage_mem[trace_init] = 16'd0;
            trace_bf_mem[trace_init] = 16'd0;
            trace_a_mem[trace_init] = 16'd0;
            trace_b_mem[trace_init] = 16'd0;
            trace_w_mem[trace_init] = 16'd0;
            trace_cycles_mem[trace_init] = 16'd0;
            trace_sum_mem[trace_init] = 16'd0;
            trace_dif_mem[trace_init] = 16'd0;
        end
    end

    always @(*) begin
        case (trace_word)
            3'd0: trace_data = trace_stage_r;
            3'd1: trace_data = trace_bf_r;
            3'd2: trace_data = trace_a_r;
            3'd3: trace_data = trace_b_r;
            3'd4: trace_data = trace_w_r;
            3'd5: trace_data = trace_cycles_r;
            3'd6: trace_data = trace_sum_r;
            3'd7: trace_data = trace_dif_r;
            default: trace_data = 16'd0;
        endcase
    end

    assign in_ready = !q_full;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);
    wire cache_read = ce && !head_valid && !q_empty;
    wire bypass_head = ce && accept && q_empty;
    wire start = ce && head_valid && !busy && !out_valid;
wire retire = busy && ce && last && !trace_full;

    wire [31:0] prod = w_r * b_r;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];
    always @(posedge clk) begin
        if (retire) begin
            trace_stage_mem[trace_wr[TRACE_ADDR_W-1:0]] <= stage;
            trace_bf_mem[trace_wr[TRACE_ADDR_W-1:0]] <= bf_idx;
            trace_a_mem[trace_wr[TRACE_ADDR_W-1:0]] <= a_r;
            trace_b_mem[trace_wr[TRACE_ADDR_W-1:0]] <= b_r;
            trace_w_mem[trace_wr[TRACE_ADDR_W-1:0]] <= w_r;
            trace_cycles_mem[trace_wr[TRACE_ADDR_W-1:0]] <= phase + 16'd1;
            trace_sum_mem[trace_wr[TRACE_ADDR_W-1:0]] <= sum_mod;
            trace_dif_mem[trace_wr[TRACE_ADDR_W-1:0]] <= dif_mod;
            if (trace_wr[TRACE_ADDR_W-1:0] == TRACE_LAST_SLOT)
                trace_wr <= {!trace_wr[TRACE_ADDR_W], {TRACE_ADDR_W{1'b0}}};
            else
                trace_wr <= trace_wr + 1'b1;
        end
        if (trace_pop) begin
            if (trace_rd[TRACE_ADDR_W-1:0] == TRACE_LAST_SLOT)
                trace_rd <= {!trace_rd[TRACE_ADDR_W], {TRACE_ADDR_W{1'b0}}};
            else
                trace_rd <= trace_rd + 1'b1;
        end
    end

    always @(posedge clk) begin
        if (trace_load) begin
            trace_stage_r <= trace_stage_mem[trace_head_slot];
            trace_bf_r <= trace_bf_mem[trace_head_slot];
            trace_a_r <= trace_a_mem[trace_head_slot];
            trace_b_r <= trace_b_mem[trace_head_slot];
            trace_w_r <= trace_w_mem[trace_head_slot];
            trace_cycles_r <= trace_cycles_mem[trace_head_slot];
            trace_sum_r <= trace_sum_mem[trace_head_slot];
            trace_dif_r <= trace_dif_mem[trace_head_slot];
            trace_active <= 1'b1;
            trace_word <= {TRACE_WORD_W{1'b0}};
        end else if (trace_beat) begin
            if (trace_pop) begin
                trace_active <= 1'b0;
                trace_word <= {TRACE_WORD_W{1'b0}};
            end else begin
                trace_word <= trace_word + 1'b1;
            end
        end
    end

    always @(posedge clk) begin
        if (trace_active)
            assert ((trace_cycles_r != 16'd0) &&
                    (trace_stage_r < STAGES) && (trace_bf_r < NBF) &&
                    (!(out_valid && (trace_pending == 1)) ||
                     ((trace_sum_r == out_a) && (trace_dif_r == out_b))));
    end

    always @(posedge clk) begin
        if (accept) begin
            q_a[q_wr[ADDR_W-1:0]] <= in_a;
            q_b[q_wr[ADDR_W-1:0]] <= in_b;
            q_w[q_wr[ADDR_W-1:0]] <= in_w;
            q_lat[q_wr[ADDR_W-1:0]] <= lat_eff;
            if (q_wr[ADDR_W-1:0] == LAST_SLOT)
                q_wr <= {!q_wr[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_wr <= q_wr + 1'b1;
        end
        if (retire) begin
            if (q_rd[ADDR_W-1:0] == LAST_SLOT)
                q_rd <= {!q_rd[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_rd <= q_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (cache_read) begin
            a_r <= q_a[head_slot];
            b_r <= q_b[head_slot];
            w_r <= q_w[head_slot];
            lat_q <= q_lat[head_slot];
            head_valid <= 1'b1;
        end else if (bypass_head) begin
            a_r <= in_a;
            b_r <= in_b;
            w_r <= in_w;
            lat_q <= lat_eff;
            head_valid <= 1'b1;
        end else if (retire) begin
            head_valid <= 1'b0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load_cfg) lat_cfg <= cfg_lat;
        if (start) begin
            cd    <= lat_q;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
end else if (busy && ce && (!last || !trace_full)) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - 16'd1;
                phase <= phase + 16'd1;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

module div3_serial #(
    parameter W = 16,
    parameter MAXBITS = 16
) (
    input  wire         clk,
    input  wire         arm,
    input  wire         clr,
    input  wire         load,
    input  wire [W-1:0] load_len,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire         in_bit,
    output wire         done,
    output wire         div3,
output wire [1:0]   o_rem,
input  wire         peer_valid, peer_bit, peer_clr,
output wire         peer_ready, peer_done, peer_div3,
output wire [1:0]   peer_rem,
output wire [W-1:0] peer_value
);
    localparam [1:0] S_IDLE = 2'd0, S_ARM = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;
localparam integer CHANNELS = 2, PCW = $clog2(MAXBITS + 1);

    reg [1:0]   phase   = S_IDLE;
wire [1:0] rem;
    reg [W-1:0] val     = {W{1'b0}};
    reg [W-1:0] cnt     = {W{1'b0}};
    reg [W-1:0] limit   = 16'd8;
    reg         started = 1'b0;
    reg         win     = 1'b0;
reg [$clog2(CHANNELS)-1:0] owner = 0;
reg [1:0] alu_rem = 2'd0, parked_rem = 2'd0;
reg [W-1:0] peer_val = {W{1'b0}};
reg [PCW-1:0] peer_cnt = {PCW{1'b0}};

wire lane_active = (phase == S_ARM) || (phase == S_RUN);
wire grant_peer = peer_valid && !peer_done && (!lane_active || !in_valid || owner == 0);
assign in_ready = lane_active && !grant_peer;
assign peer_ready = !peer_done && (!lane_active || !in_valid || owner == 0);
    wire acc = in_valid && in_ready;
wire peer_acc = peer_valid && peer_ready;

    function [1:0] rnext;
        input [1:0] r;
        input       b;
        begin
            case ({r, b})
                3'b000: rnext = 2'd0;
                3'b001: rnext = 2'd1;
                3'b010: rnext = 2'd2;
                3'b011: rnext = 2'd0;
                3'b100: rnext = 2'd1;
                3'b101: rnext = 2'd2;
                default: rnext = 2'd0;
            endcase
        end
    endfunction

    wire [W-1:0] load_clamped = (load_len == 16'd0) ? 16'd1 :
                                (load_len > MAXBITS) ? MAXBITS : load_len;
assign rem = (owner == 0) ? alu_rem : parked_rem;
assign peer_rem = (owner == 0) ? parked_rem : alu_rem;
assign peer_done = (peer_cnt == MAXBITS);
assign peer_div3 = (peer_rem == 2'd0);
assign peer_value = peer_val;
wire main_clear = ((phase == S_IDLE) && arm) || ((phase == S_DONE) && clr);
wire peer_clear = peer_done && peer_clr;
wire [1:0] active_ctx = (owner ? peer_clear : main_clear) ? 2'd0 : alu_rem;
wire [1:0] parked_ctx = (owner ? main_clear : peer_clear) ? 2'd0 : parked_rem;
always @(posedge clk) begin
    if (acc || peer_acc) begin
        alu_rem <= rnext((owner == grant_peer) ? active_ctx : parked_ctx,
                         grant_peer ? peer_bit : in_bit);
        parked_rem <= (owner == grant_peer) ? parked_ctx : active_ctx;
        owner <= grant_peer;
    end else begin
        alu_rem <= active_ctx;
        parked_rem <= parked_ctx;
    end
    if (peer_clear) begin
        peer_cnt <= {PCW{1'b0}};
        peer_val <= {W{1'b0}};
    end else if (peer_acc) begin
        peer_cnt <= peer_cnt + 1'b1;
        peer_val <= {peer_val[W-2:0], peer_bit};
    end
end

    always @(posedge clk) begin
        if (phase == S_IDLE) begin
            if (load) limit <= load_clamped;
            if (arm) begin
                phase   <= S_ARM;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b1;
            end
        end else if (phase == S_DONE) begin
            if (clr) begin
                phase   <= S_IDLE;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b0;
            end
        end else if (acc) begin
            val     <= {val[W-2:0], in_bit};
            cnt     <= cnt + 16'd1;
            started <= 1'b1;
            if (cnt + 16'd1 == limit) phase <= S_DONE;
            else                      phase <= S_RUN;
        end
    end

    assign done  = (phase == S_DONE);
    assign div3  = (rem == 2'd0);
    assign o_rem = rem;

    always @(posedge clk)
        if (win && $rose(done))
            assert (started && (div3 == ((val % 16'd3) == 16'd0)));
always @(posedge clk)
    if (peer_done)
        assert (peer_div3 == ((peer_val % 16'd3) == 16'd0));
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted,
    output reg [31:0] debug_status
,
    output wire [W-1:0] in_cnt_o,
    output wire [W-1:0] out_cnt_o
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;
    reg [31:0] dbg_cycles, dbg_input_stalls, dbg_output_stalls;
    reg [31:0] dbg_frames, dbg_cfg_writes;
    reg [15:0] dbg_stall_run, dbg_stall_max, dbg_idle_age;
    reg [7:0] dbg_high_water;
    reg [3:0] dbg_flags;
    reg dbg_enable;
    wire dbg_input_blocked = i_valid && !i_ready;
    wire dbg_output_blocked = o_valid && !o_ready;
    wire dbg_clear = cfg_we && (cfg_addr == 4'd15) && cfg_data[0];
    initial begin
        dbg_cycles = 32'd0;
        dbg_input_stalls = 32'd0;
        dbg_output_stalls = 32'd0;
        dbg_frames = 32'd0;
        dbg_cfg_writes = 32'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_max = 16'd0;
        dbg_idle_age = 16'd0;
        dbg_high_water = 8'd0;
        dbg_flags = 4'd0;
        dbg_enable = 1'b1;
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (rst) begin
            dbg_cycles <= 32'd0;
            dbg_input_stalls <= 32'd0;
            dbg_output_stalls <= 32'd0;
            dbg_frames <= 32'd0;
            dbg_cfg_writes <= 32'd0;
            dbg_stall_run <= 16'd0;
            dbg_stall_max <= 16'd0;
            dbg_idle_age <= 16'd0;
            dbg_high_water <= 8'd0;
            dbg_flags <= 4'd0;
            dbg_enable <= 1'b1;
            debug_status <= 32'd0;
        end else begin
            if (cfg_we && cfg_addr == 4'd9)
                dbg_enable <= cfg_data[0];
            if (dbg_clear) begin
                dbg_cycles <= 32'd0;
                dbg_input_stalls <= 32'd0;
                dbg_output_stalls <= 32'd0;
                dbg_frames <= 32'd0;
                dbg_cfg_writes <= 32'd0;
                dbg_stall_run <= 16'd0;
                dbg_stall_max <= 16'd0;
                dbg_idle_age <= 16'd0;
                dbg_high_water <= 8'd0;
                dbg_flags <= 4'd0;
            end else if (dbg_enable) begin
                if (!(&dbg_cycles))
                    dbg_cycles <= dbg_cycles + 32'd1;
                if (dbg_input_blocked && !(&dbg_input_stalls))
                    dbg_input_stalls <= dbg_input_stalls + 32'd1;
                if (dbg_output_blocked && !(&dbg_output_stalls))
                    dbg_output_stalls <= dbg_output_stalls + 32'd1;
                if (out_fire && o_last && !(&dbg_frames))
                    dbg_frames <= dbg_frames + 32'd1;
                if (cfg_we && cfg_addr <= 4'd8 && !(&dbg_cfg_writes))
                    dbg_cfg_writes <= dbg_cfg_writes + 32'd1;
                if (ingress_level > dbg_high_water)
                    dbg_high_water <= (ingress_level > 255) ? 8'hff : ingress_level;
                if (dbg_output_blocked) begin
                    if (!(&dbg_stall_run))
                        dbg_stall_run <= dbg_stall_run + 16'd1;
                    if (dbg_stall_run >= dbg_stall_max && !(&dbg_stall_run))
                        dbg_stall_max <= dbg_stall_run + 16'd1;
                end else
                    dbg_stall_run <= 16'd0;
                if ((ingress_valid || o_valid) && !out_fire) begin
                    if (!(&dbg_idle_age))
                        dbg_idle_age <= dbg_idle_age + 16'd1;
                    if (&dbg_idle_age)
                        dbg_flags[2] <= 1'b1;
                end else
                    dbg_idle_age <= 16'd0;
                if (dbg_input_blocked)
                    dbg_flags[0] <= 1'b1;
                if (dbg_output_blocked)
                    dbg_flags[1] <= 1'b1;
                if (cfg_we && armed)
                    dbg_flags[3] <= 1'b1;
            end
            case (cfg_addr)
                4'd9: debug_status <= {31'd0, dbg_enable};
                4'd10: debug_status <= dbg_cycles;
                4'd11: debug_status <= dbg_input_stalls;
                4'd12: debug_status <= dbg_output_stalls;
                4'd13: debug_status <= dbg_frames;
                4'd14: debug_status <= {dbg_stall_max, dbg_stall_run};
                4'd15: debug_status <= {dbg_high_water, dbg_flags, 4'd0, dbg_idle_age};
                default: debug_status <= dbg_cfg_writes;
            endcase
        end
    end

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
    assign in_cnt_o = in_cnt;
    assign out_cnt_o = out_cnt;
endmodule

module transpose_buf #(
    parameter ROWS  = 4,
    parameter COLS  = 8,
    parameter DEPTH = ROWS * COLS,
    parameter DW    = 32
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data
,
    output wire [1:0] chain_o,
    output wire phase_o,
    output wire [31:0] rd_col_o,
    output wire [31:0] rd_row_o,
    output wire [31:0] wr_col_o,
    output wire [31:0] wr_row_o
);
    localparam AW = $clog2(DEPTH);
    localparam [1:0] C_IDLE  = 2'd0;
    localparam [1:0] C_ARM   = 2'd1;
    localparam [1:0] C_START = 2'd2;
    localparam PH_FILL  = 1'b0;
    localparam PH_DRAIN = 1'b1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg        phase    = 1'b0;
    reg [31:0] wr_row   = 32'd0;
    reg [31:0] wr_col   = 32'd0;
    reg [31:0] rd_row   = 32'd0;
    reg [31:0] rd_col   = 32'd0;
    reg [1:0]  chain    = 2'd0;
    reg        before_r = 1'b1;
    reg        pv       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = {DW{1'b0}};
    end

    assign in_ready  = (phase == PH_FILL);
    assign out_valid = (phase == PH_DRAIN);

    wire wr_fire = in_valid && in_ready;
    wire rd_fire = out_valid && out_ready;
    wire wr_last = (wr_row == ROWS - 1) && (wr_col == COLS - 1);
    wire rd_last = (rd_row == ROWS - 1) && (rd_col == COLS - 1);

    wire [31:0] wr_addr = wr_row * COLS + wr_col;
    wire [31:0] rd_addr = rd_row * COLS + rd_col;

    assign out_data = mem[rd_addr[AW-1:0]];

    // row-order write into the tile
    always @(posedge clk) begin
        if (wr_fire)
            mem[wr_addr[AW-1:0]] <= in_data;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase    <= PH_FILL;
            wr_row   <= 32'd0;
            wr_col   <= 32'd0;
            rd_row   <= 32'd0;
            rd_col   <= 32'd0;
            chain    <= C_IDLE;
            before_r <= 1'b1;
        end else begin
            if (wr_fire) begin
                if (wr_col == COLS - 1) begin
                    wr_col <= 32'd0;
                    if (wr_row == ROWS - 1) wr_row <= 32'd0;
                    else                    wr_row <= wr_row + 32'd1;
                end else begin
                    wr_col <= wr_col + 32'd1;
                end
                if (wr_last) begin
                    phase <= PH_DRAIN;
                    chain <= C_START;
                end else if (chain == C_IDLE) begin
                    chain <= C_ARM;
                end
            end
            // column-order read out of the tile
            if (rd_fire) begin
                if (rd_row == ROWS - 1) begin
                    rd_row <= 32'd0;
                    if (rd_col == COLS - 1) rd_col <= 32'd0;
                    else                    rd_col <= rd_col + 32'd1;
                end else begin
                    rd_row <= rd_row + 32'd1;
                end
                if (rd_last) begin
                    phase    <= PH_FILL;
                    chain    <= C_IDLE;
                    before_r <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    // Chain precedence (arm -> start -> finish), before first tile completes:
    // while the chain FSM sits unchanged short of START, no column-order read may advance.
    always @(posedge clk) begin
        if (pv && before_r && $stable(chain) && chain != C_START)
            assert ($stable(rd_row) && $stable(rd_col));
    end
    assign chain_o = chain;
    assign phase_o = phase;
    assign rd_col_o = rd_col;
    assign rd_row_o = rd_row;
    assign wr_col_o = wr_col;
    assign wr_row_o = wr_row;
endmodule

module rgb_ycc_tile_pipeline #(
    parameter INGRESS_DEPTH = 4,
    parameter BRIDGE_DEPTH = 4,
    parameter TILE_ROWS = 4,
parameter TILE_COLS = 4,
parameter ANALYTICS_DEPTH = 4
) (
    input wire clk,
    input wire rst,
    input wire cfg_we,
    input wire [3:0] cfg_addr,
    input wire [31:0] cfg_data,
    input wire i_valid,
    output wire i_ready,
    input wire [7:0] i_r, i_g, i_b,
    input wire i_first, i_last,
    output wire o_valid,
    input wire o_ready,
    output wire [23:0] o_data,
    output wire a_o_valid, a_o_ready,
    output wire [7:0] a_o_y, a_o_cb, a_o_cr,
    output wire a_o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] a_ingress_level,
    output wire [31:0] a_ingress_accepted,
    output wire [31:0] a_in_cnt, a_out_cnt,
    output wire [31:0] a_debug_status,
    output wire b_in_valid, b_in_ready,
    output wire [1:0] b_chain,
    output wire b_phase,
    output wire [31:0] b_rd_col, b_rd_row, b_wr_col, b_wr_row,
    output reg [$clog2(BRIDGE_DEPTH+1)-1:0] bridge_level,
    output reg [31:0] delivered_pixels,
    output wire [31:0] tile_held,
    output wire [31:0] pending_pixels,
    output reg pipeline_active,
output wire busy,
output wire analysis_ready,
output wire [$clog2(ANALYTICS_DEPTH):0] analysis_level,
output reg analysis_enabled,
output reg analysis_report_valid,
output reg [7:0] analysis_min_y,
output reg [7:0] analysis_max_y,
output reg [7:0] analysis_peak_edge,
output reg [7:0] analysis_chroma_separation,
output reg [23:0] analysis_first_pixel,
output reg [23:0] analysis_last_pixel
);
    localparam TILE_PIXELS = TILE_ROWS * TILE_COLS;
    localparam TOTAL_CAPACITY = INGRESS_DEPTH + 1 + BRIDGE_DEPTH + TILE_PIXELS;
    localparam BRIDGE_PTR_W = $clog2(BRIDGE_DEPTH);
    wire rst_n = !rst;
    reg [23:0] bridge_mem [0:BRIDGE_DEPTH-1];
    reg [BRIDGE_PTR_W-1:0] bridge_rd_ptr, bridge_wr_ptr;
    wire [23:0] b_in_data = bridge_mem[bridge_rd_ptr];
    wire bridge_push = a_o_valid && a_o_ready;
    wire bridge_pop = b_in_valid && b_in_ready;
    wire sink_fire = o_valid && o_ready;
    integer j;

    localparam ANALYSIS_PTR_W = $clog2(ANALYTICS_DEPTH);
    localparam TILE_POS_W = (TILE_PIXELS > 1) ? $clog2(TILE_PIXELS) : 1;
    reg [23:0] analysis_pixels [0:ANALYTICS_DEPTH-1];
    reg [TILE_POS_W-1:0] analysis_pos [0:ANALYTICS_DEPTH-1];
    reg [ANALYSIS_PTR_W:0] analysis_rd_ptr, analysis_wr_ptr;
    reg [TILE_POS_W-1:0] analysis_cursor;
    reg analysis_work_valid, analysis_work_phase;
    reg analysis_work_first, analysis_work_last;
    reg [23:0] analysis_work_pixel;
    reg [TILE_POS_W-1:0] analysis_work_pos;
    reg [7:0] analysis_min_acc, analysis_max_acc;
    reg [7:0] analysis_edge_acc, analysis_chroma_acc;
    reg [7:0] analysis_previous_y;
    reg [23:0] analysis_first_acc;
    reg [7:0] analysis_next_min, analysis_next_max;
    reg [7:0] analysis_next_edge, analysis_next_chroma;
    reg [7:0] analysis_y_delta, analysis_chroma_delta;
    integer aj;

    wire bridge_offer = pipeline_active && (bridge_level != 0);
    wire analysis_empty = analysis_rd_ptr == analysis_wr_ptr;
    wire analysis_full =
        (analysis_rd_ptr[ANALYSIS_PTR_W-1:0] ==
         analysis_wr_ptr[ANALYSIS_PTR_W-1:0]) &&
        (analysis_rd_ptr[ANALYSIS_PTR_W] !=
         analysis_wr_ptr[ANALYSIS_PTR_W]);
    wire analysis_take = analysis_enabled && !analysis_empty &&
                         !analysis_work_valid;
    wire analysis_put = bridge_pop;
    wire analysis_finish = analysis_work_valid && analysis_work_phase;
    wire [23:0] analysis_head_pixel =
        analysis_pixels[analysis_rd_ptr[ANALYSIS_PTR_W-1:0]];
    wire [TILE_POS_W-1:0] analysis_head_pos =
        analysis_pos[analysis_rd_ptr[ANALYSIS_PTR_W-1:0]];
    wire [7:0] analysis_y = analysis_work_pixel[23:16];
    wire [7:0] analysis_cb = analysis_work_pixel[15:8];
    wire [7:0] analysis_cr = analysis_work_pixel[7:0];
    wire [ANALYSIS_PTR_W+1:0] analysis_held =
        {1'b0, analysis_level} + analysis_work_valid;

    function [ANALYSIS_PTR_W:0] analysis_advance;
        input [ANALYSIS_PTR_W:0] ptr;
        begin
            if (ptr[ANALYSIS_PTR_W-1:0] == ANALYTICS_DEPTH-1)
                analysis_advance = {!ptr[ANALYSIS_PTR_W],
                                    {ANALYSIS_PTR_W{1'b0}}};
            else
                analysis_advance = ptr + 1'b1;
        end
    endfunction

    assign analysis_level =
        (analysis_wr_ptr[ANALYSIS_PTR_W] ==
         analysis_rd_ptr[ANALYSIS_PTR_W])
        ? analysis_wr_ptr[ANALYSIS_PTR_W-1:0] -
          analysis_rd_ptr[ANALYSIS_PTR_W-1:0]
        : ANALYTICS_DEPTH + analysis_wr_ptr[ANALYSIS_PTR_W-1:0] -
          analysis_rd_ptr[ANALYSIS_PTR_W-1:0];
    assign analysis_ready = !analysis_full || analysis_take;

    // Row boundaries suppress transitions between unrelated row endpoints.
    always @(*) begin
        analysis_y_delta = (analysis_y >= analysis_previous_y)
                         ? analysis_y - analysis_previous_y
                         : analysis_previous_y - analysis_y;
        analysis_chroma_delta = (analysis_cb >= analysis_cr)
                              ? analysis_cb - analysis_cr
                              : analysis_cr - analysis_cb;
        analysis_next_min = analysis_min_acc;
        analysis_next_max = analysis_max_acc;
        analysis_next_edge = analysis_edge_acc;
        analysis_next_chroma = analysis_chroma_acc;
        if (analysis_work_first) begin
            analysis_next_min = analysis_y;
            analysis_next_max = analysis_y;
            analysis_next_edge = 8'd0;
            analysis_next_chroma = analysis_chroma_delta;
        end else begin
            if (analysis_y < analysis_min_acc)
                analysis_next_min = analysis_y;
            if (analysis_y > analysis_max_acc)
                analysis_next_max = analysis_y;
            if (analysis_chroma_delta > analysis_chroma_acc)
                analysis_next_chroma = analysis_chroma_delta;
        end
        if ((analysis_work_pos % TILE_COLS) != 0 &&
            analysis_y_delta > analysis_next_edge)
            analysis_next_edge = analysis_y_delta;
    end

    // A completed tile blocks its input until column-order draining finishes.
    assign b_in_valid = bridge_offer && analysis_ready;
    assign a_o_ready = pipeline_active &&
                       ((bridge_level < BRIDGE_DEPTH) || bridge_pop);
    assign tile_held = b_phase
                     ? TILE_PIXELS - (b_rd_col * TILE_ROWS + b_rd_row)
                     : b_wr_row * TILE_COLS + b_wr_col;
    assign pending_pixels = a_ingress_accepted - delivered_pixels;
    assign busy = !pipeline_active || (a_ingress_level != 0) ||
                  a_o_valid || (bridge_level != 0) || (tile_held != 0);

    csc_rgb2ycc #(.W(32), .FRAC(16), .INGRESS_DEPTH(INGRESS_DEPTH)) color (
        .clk(clk), .rst(rst),
        .cfg_we(cfg_we), .cfg_addr(cfg_addr), .cfg_data(cfg_data),
        .i_valid(i_valid), .i_ready(i_ready),
        .i_r(i_r), .i_g(i_g), .i_b(i_b),
        .i_first(i_first), .i_last(i_last),
        .o_valid(a_o_valid), .o_ready(a_o_ready),
        .o_y(a_o_y), .o_cb(a_o_cb), .o_cr(a_o_cr), .o_last(a_o_last),
        .ingress_level(a_ingress_level), .ingress_accepted(a_ingress_accepted),
        .debug_status(a_debug_status), .in_cnt_o(a_in_cnt), .out_cnt_o(a_out_cnt)
    );
    transpose_buf #(
        .ROWS(TILE_ROWS), .COLS(TILE_COLS), .DEPTH(TILE_PIXELS), .DW(24)
    ) tile (
        .clk(clk), .rst_n(rst_n),
        .in_valid(b_in_valid), .in_ready(b_in_ready), .in_data(b_in_data),
        .out_valid(o_valid), .out_ready(o_ready), .out_data(o_data),
        .chain_o(b_chain), .phase_o(b_phase),
        .rd_col_o(b_rd_col), .rd_row_o(b_rd_row),
        .wr_col_o(b_wr_col), .wr_row_o(b_wr_row)
    );

    initial begin
        pipeline_active = 1'b0;
        bridge_level = 0;
        delivered_pixels = 32'd0;
        bridge_rd_ptr = {BRIDGE_PTR_W{1'b0}};
        bridge_wr_ptr = {BRIDGE_PTR_W{1'b0}};
        for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
            bridge_mem[j] = 24'd0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipeline_active <= 1'b0;
            bridge_level <= 0;
            delivered_pixels <= 32'd0;
            bridge_rd_ptr <= {BRIDGE_PTR_W{1'b0}};
            bridge_wr_ptr <= {BRIDGE_PTR_W{1'b0}};
            for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
                bridge_mem[j] <= 24'd0;
        end else begin
            pipeline_active <= 1'b1;
            case ({bridge_push, bridge_pop})
                2'b10: bridge_level <= bridge_level + 1'b1;
                2'b01: bridge_level <= bridge_level - 1'b1;
                default: ;
            endcase
            if (bridge_push) begin
                bridge_mem[bridge_wr_ptr] <= {a_o_y, a_o_cb, a_o_cr};
                bridge_wr_ptr <= (bridge_wr_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_wr_ptr + 1'b1;
            end
            if (bridge_pop)
                bridge_rd_ptr <= (bridge_rd_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_rd_ptr + 1'b1;
            if (sink_fire)
                delivered_pixels <= delivered_pixels + 32'd1;
        end
    end

    initial begin
        analysis_rd_ptr = {(ANALYSIS_PTR_W+1){1'b0}};
        analysis_wr_ptr = {(ANALYSIS_PTR_W+1){1'b0}};
        analysis_cursor = {TILE_POS_W{1'b0}};
        analysis_enabled = 1'b1;
        analysis_work_valid = 1'b0;
        analysis_work_phase = 1'b0;
        analysis_work_first = 1'b0;
        analysis_work_last = 1'b0;
        analysis_work_pixel = 24'd0;
        analysis_work_pos = {TILE_POS_W{1'b0}};
        analysis_min_acc = 8'hff;
        analysis_max_acc = 8'd0;
        analysis_edge_acc = 8'd0;
        analysis_chroma_acc = 8'd0;
        analysis_previous_y = 8'd0;
        analysis_first_acc = 24'd0;
        analysis_report_valid = 1'b0;
        analysis_min_y = 8'd0;
        analysis_max_y = 8'd0;
        analysis_peak_edge = 8'd0;
        analysis_chroma_separation = 8'd0;
        analysis_first_pixel = 24'd0;
        analysis_last_pixel = 24'd0;
        for (aj = 0; aj < ANALYTICS_DEPTH; aj = aj + 1) begin
            analysis_pixels[aj] = 24'd0;
            analysis_pos[aj] = {TILE_POS_W{1'b0}};
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            analysis_rd_ptr <= {(ANALYSIS_PTR_W+1){1'b0}};
            analysis_wr_ptr <= {(ANALYSIS_PTR_W+1){1'b0}};
            analysis_cursor <= {TILE_POS_W{1'b0}};
            analysis_enabled <= 1'b1;
            analysis_work_valid <= 1'b0;
            analysis_work_phase <= 1'b0;
            analysis_work_first <= 1'b0;
            analysis_work_last <= 1'b0;
            analysis_work_pixel <= 24'd0;
            analysis_work_pos <= {TILE_POS_W{1'b0}};
            analysis_min_acc <= 8'hff;
            analysis_max_acc <= 8'd0;
            analysis_edge_acc <= 8'd0;
            analysis_chroma_acc <= 8'd0;
            analysis_previous_y <= 8'd0;
            analysis_first_acc <= 24'd0;
            analysis_report_valid <= 1'b0;
            analysis_min_y <= 8'd0;
            analysis_max_y <= 8'd0;
            analysis_peak_edge <= 8'd0;
            analysis_chroma_separation <= 8'd0;
            analysis_first_pixel <= 24'd0;
            analysis_last_pixel <= 24'd0;
            for (aj = 0; aj < ANALYTICS_DEPTH; aj = aj + 1) begin
                analysis_pixels[aj] <= 24'd0;
                analysis_pos[aj] <= {TILE_POS_W{1'b0}};
            end
        end else begin
            analysis_report_valid <= 1'b0;
            if (cfg_we && cfg_addr == 4'd9)
                analysis_enabled <= cfg_data[1];

            // Fork only transfers that were also accepted by the tile.
            if (analysis_put) begin
                analysis_pixels[analysis_wr_ptr[ANALYSIS_PTR_W-1:0]] <=
                    b_in_data;
                analysis_pos[analysis_wr_ptr[ANALYSIS_PTR_W-1:0]] <=
                    b_wr_row * TILE_COLS + b_wr_col;
                analysis_wr_ptr <= analysis_advance(analysis_wr_ptr);
            end
            if (analysis_take) begin
                analysis_work_valid <= 1'b1;
                analysis_work_phase <= 1'b0;
                analysis_work_pixel <= analysis_head_pixel;
                analysis_work_pos <= analysis_head_pos;
                analysis_work_first <= analysis_cursor == 0;
                analysis_work_last <= analysis_cursor == TILE_PIXELS-1;
                analysis_rd_ptr <= analysis_advance(analysis_rd_ptr);
                analysis_cursor <= (analysis_cursor == TILE_PIXELS-1)
                                 ? {TILE_POS_W{1'b0}}
                                 : analysis_cursor + 1'b1;
            end

            // Luma and chroma passes share the held pixel, not the FIFO port.
            if (analysis_work_valid) begin
                if (!analysis_work_phase) begin
                    analysis_min_acc <= analysis_next_min;
                    analysis_max_acc <= analysis_next_max;
                    analysis_edge_acc <= analysis_next_edge;
                    analysis_previous_y <= analysis_y;
                    if (analysis_work_first)
                        analysis_first_acc <= analysis_work_pixel;
                    analysis_work_phase <= 1'b1;
                end else begin
                    analysis_chroma_acc <= analysis_next_chroma;
                    analysis_work_valid <= 1'b0;
                    if (analysis_work_last) begin
                        analysis_report_valid <= 1'b1;
                        analysis_min_y <= analysis_min_acc;
                        analysis_max_y <= analysis_max_acc;
                        analysis_peak_edge <= analysis_edge_acc;
                        analysis_chroma_separation <= analysis_next_chroma;
                        analysis_first_pixel <= analysis_first_acc;
                        analysis_last_pixel <= analysis_work_pixel;
                    end
                end
            end
        end
    end

    always @(posedge clk) begin
        if (pipeline_active && analysis_take)
            assert (analysis_head_pos == analysis_cursor);
    end

    always @(posedge clk) begin
        if (pipeline_active)
            assert (pending_pixels <= TOTAL_CAPACITY);
    end
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag,
    output wire [31:0] debug_status,
    output wire [95:0] perf_status
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;

    assign in_ready  = (state == S_ACCUM);
    assign out_valid = (state == S_DONE);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready;

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
            if (in_mag < min1) begin
                min2    <= min1;
                min1    <= in_mag;
                min_idx <= count;
            end else if (in_mag < min2) begin
                min2 <= in_mag;
            end
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = min1;
    assign out_min2 = min2;
    assign out_idx  = min_idx;
    assign out_sign = sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;
    reg [7:0] dbg_accept_count;
    reg [7:0] dbg_complete_count;
    reg [7:0] dbg_stall_cycles;
    reg [7:0] dbg_peak_stall;
    reg       dbg_timeout;
    initial dbg_accept_count = 8'd0;
    initial dbg_complete_count = 8'd0;
    initial dbg_stall_cycles = 8'd0;
    initial dbg_peak_stall = 8'd0;
    initial dbg_timeout = 1'b0;
    always @(posedge clk) begin
        if (acc) begin
            if (dbg_accept_count != 8'hff)
                dbg_accept_count <= dbg_accept_count + 1'b1;
        end
        if (rel) begin
            if (dbg_complete_count != 8'hff)
                dbg_complete_count <= dbg_complete_count + 1'b1;
        end
        if (out_valid && !out_ready) begin
            if (dbg_stall_cycles != 8'hff) begin
                dbg_stall_cycles <= dbg_stall_cycles + 1'b1;
                if (dbg_stall_cycles >= dbg_peak_stall)
                    dbg_peak_stall <= dbg_stall_cycles + 1'b1;
            end
            if (dbg_stall_cycles >= 8'd63)
                dbg_timeout <= 1'b1;
        end else begin
            dbg_stall_cycles <= 8'd0;
        end
    end
    assign debug_status = {dbg_timeout, 7'd0, dbg_peak_stall,
                           dbg_complete_count, dbg_accept_count};
    reg [15:0] perf_frame_cycles;
    reg [15:0] perf_peak_cycles;
    reg [15:0] perf_negative_samples;
    reg [15:0] perf_zero_samples;
    reg [15:0] perf_minimum_ties;
    reg [15:0] perf_idle_cycles;
    reg        perf_active;
    initial perf_frame_cycles = 16'd0;
    initial perf_peak_cycles = 16'd0;
    initial perf_negative_samples = 16'd0;
    initial perf_zero_samples = 16'd0;
    initial perf_minimum_ties = 16'd0;
    initial perf_idle_cycles = 16'd0;
    initial perf_active = 1'b0;
    always @(posedge clk) begin
        if (acc && !perf_active) begin
            perf_active <= 1'b1;
            perf_frame_cycles <= 16'd1;
        end else if (perf_active && !rel) begin
            if (perf_frame_cycles != 16'hffff) begin
                perf_frame_cycles <= perf_frame_cycles + 1'b1;
            end
        end
        if (rel) begin
            perf_active <= 1'b0;
            if (perf_frame_cycles > perf_peak_cycles) begin
                perf_peak_cycles <= perf_frame_cycles;
            end
        end
        if (acc) begin
            if (in_sign && perf_negative_samples != 16'hffff) begin
                perf_negative_samples <= perf_negative_samples + 1'b1;
            end
            if ((in_mag == {W{1'b0}}) && perf_zero_samples != 16'hffff) begin
                perf_zero_samples <= perf_zero_samples + 1'b1;
            end
            if ((in_mag == min1) && perf_minimum_ties != 16'hffff) begin
                perf_minimum_ties <= perf_minimum_ties + 1'b1;
            end
        end
        if (in_ready && !in_valid) begin
            if (perf_idle_cycles != 16'hffff) begin
                perf_idle_cycles <= perf_idle_cycles + 1'b1;
            end
        end
    end
    assign perf_status = {perf_peak_cycles, perf_frame_cycles,
                          perf_negative_samples, perf_zero_samples,
                          perf_minimum_ties, perf_idle_cycles};

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
output wire [W-1:0] q_mag,
input  wire         peer_in_valid,
output wire         peer_in_ready,
input  wire [W-1:0] peer_in_mag,
output wire         peer_out_valid,
input  wire         peer_out_ready,
output wire [W-1:0] peer_out_min1,
output wire [W-1:0] peer_out_min2
);
localparam CHANNELS = 2, MINIMA = 2, PEER_CW = (DEG > 1) ? $clog2(DEG) : 1;
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

reg [W-1:0] minima [0:CHANNELS*MINIMA-1];
wire [W-1:0] min1 = minima[0], min2 = minima[1];
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
integer mi;
initial for (mi = 0; mi < CHANNELS*MINIMA; mi = mi + 1) minima[mi] = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
reg [PEER_CW-1:0] peer_count;
reg peer_done;
reg [$clog2(CHANNELS)-1:0] owner_peer;
initial begin peer_count = 0; peer_done = 0; owner_peer = 1; end
wire frames_idle = (count == 0) && (peer_count == 0);
wire select_peer = frames_idle ? (peer_in_valid && !peer_done && (!in_valid || state != S_ACCUM || !owner_peer)) : owner_peer;
assign peer_in_ready = select_peer && !peer_done;
wire peer_acc = peer_in_valid && peer_in_ready;
wire [W-1:0] cmp_mag = select_peer ? peer_in_mag : in_mag;
wire [W-1:0] cmp_min1 = select_peer ? minima[MINIMA] : min1;
wire [W-1:0] cmp_min2 = select_peer ? minima[MINIMA+1] : min2;
wire new_first = cmp_mag < cmp_min1;
wire [W-1:0] step_min1 = new_first ? cmp_mag : cmp_min1;
wire [W-1:0] step_min2 = new_first ? cmp_min1 : ((cmp_mag < cmp_min2) ? cmp_mag : cmp_min2);
assign peer_out_valid = peer_done;
assign peer_out_min1 = minima[MINIMA], peer_out_min2 = minima[MINIMA+1];

assign in_ready  = (state == S_ACCUM) && !select_peer;
    assign out_valid = (state == S_DONE);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready;
wire [CHANNELS-1:0] lane_acc = {peer_acc, acc}, lane_rel = {peer_out_valid && peer_out_ready, rel};
integer lane;
always @(posedge clk) begin
    for (lane = 0; lane < CHANNELS; lane = lane + 1) begin
        if (lane_acc[lane] || lane_rel[lane]) begin
            minima[lane*MINIMA] <= lane_acc[lane] ? step_min1 : {W{1'b1}};
            minima[lane*MINIMA+1] <= lane_acc[lane] ? step_min2 : {W{1'b1}};
        end
    end
    if (acc || peer_acc) owner_peer <= select_peer;
    if (peer_acc) begin
        if (peer_count == DEG - 1) begin peer_count <= 0; peer_done <= 1; end
        else peer_count <= peer_count + 1'b1;
    end else if (lane_rel[1]) peer_done <= 0;
end

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
if (new_first) min_idx <= count;
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = min1;
    assign out_min2 = min2;
    assign out_idx  = min_idx;
    assign out_sign = sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
always @(posedge clk) if (pv) assert ((count == 0) || (peer_count == 0));
endmodule

module column_predictive_encoder #(
    parameter ROWS = 4,
    parameter COLS = 4,
    parameter DEPTH = 4,
    parameter POS_W = (ROWS*COLS > 1) ? $clog2(ROWS*COLS) : 1
) (
    input wire clk,
    input wire rst_n,
    input wire s_valid,
    output wire s_ready,
    input wire [23:0] s_pixel,
    input wire [POS_W-1:0] s_position,
    output reg m_valid,
    input wire m_ready,
    output reg [23:0] m_delta,
    output reg [POS_W-1:0] m_position,
    output reg m_seed,
    output reg m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [$clog2(DEPTH)-1:0] rd_ptr,
    output reg [$clog2(DEPTH)-1:0] wr_ptr,
    output reg [POS_W-1:0] cursor,
    output wire taking,
    output wire [POS_W-1:0] head_position,
    output reg [DEPTH*POS_W-1:0] queued_positions,
    output reg work_valid
);
    localparam PTR_W = $clog2(DEPTH);
    localparam PIXELS = ROWS * COLS;
    reg [23:0] pixels [0:DEPTH-1];
    reg [POS_W-1:0] positions [0:DEPTH-1];
    reg [23:0] row_history [0:ROWS-1];
    reg work_phase;
    reg [23:0] work_pixel;
    reg [23:0] work_base;
    reg [23:0] work_delta;
    reg [POS_W-1:0] work_position;
    reg work_seed, work_last;
    integer q;
    integer r;
    integer p;

    wire putting = s_valid && s_ready;
    wire publishing = work_valid && work_phase && (!m_valid || m_ready);
    assign taking = m_ready && (level != 0) && !work_valid;
    assign s_ready = (level < DEPTH) || taking;
    assign head_position = positions[rd_ptr];

    always @(*) begin
        for (p = 0; p < DEPTH; p = p + 1)
            queued_positions[p*POS_W +: POS_W] = positions[p];
    end

    initial begin
        level = 0;
        rd_ptr = {PTR_W{1'b0}};
        wr_ptr = {PTR_W{1'b0}};
        cursor = {POS_W{1'b0}};
        work_valid = 1'b0;
        work_phase = 1'b0;
        work_pixel = 24'd0;
        work_base = 24'd0;
        work_delta = 24'd0;
        work_position = {POS_W{1'b0}};
        work_seed = 1'b0;
        work_last = 1'b0;
        m_valid = 1'b0;
        m_delta = 24'd0;
        m_position = {POS_W{1'b0}};
        m_seed = 1'b0;
        m_last = 1'b0;
        for (q = 0; q < DEPTH; q = q + 1) begin
            pixels[q] = 24'd0;
            positions[q] = {POS_W{1'b0}};
        end
        for (r = 0; r < ROWS; r = r + 1)
            row_history[r] = 24'd0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            level <= 0;
            rd_ptr <= {PTR_W{1'b0}};
            wr_ptr <= {PTR_W{1'b0}};
            cursor <= {POS_W{1'b0}};
            work_valid <= 1'b0;
            work_phase <= 1'b0;
            work_pixel <= 24'd0;
            work_base <= 24'd0;
            work_delta <= 24'd0;
            work_position <= {POS_W{1'b0}};
            work_seed <= 1'b0;
            work_last <= 1'b0;
            m_valid <= 1'b0;
            m_delta <= 24'd0;
            m_position <= {POS_W{1'b0}};
            m_seed <= 1'b0;
            m_last <= 1'b0;
            for (q = 0; q < DEPTH; q = q + 1) begin
                pixels[q] <= 24'd0;
                positions[q] <= {POS_W{1'b0}};
            end
            for (r = 0; r < ROWS; r = r + 1)
                row_history[r] <= 24'd0;
        end else begin
            case ({putting, taking})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (putting) begin
                pixels[wr_ptr] <= s_pixel;
                positions[wr_ptr] <= s_position;
                wr_ptr <= (wr_ptr == DEPTH-1)
                        ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end

            // Each row retains the preceding column's reconstructed pixel.
            // The first column is transmitted as independent seed samples.
            if (taking) begin
                work_valid <= 1'b1;
                work_phase <= 1'b0;
                work_pixel <= pixels[rd_ptr];
                work_position <= head_position;
                work_seed <= cursor < ROWS;
                work_last <= cursor == PIXELS-1;
                work_base <= (cursor < ROWS)
                           ? 24'd0 : row_history[cursor % ROWS];
                cursor <= (cursor == PIXELS-1)
                        ? {POS_W{1'b0}} : cursor + 1'b1;
                rd_ptr <= (rd_ptr == DEPTH-1)
                        ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
            end

            // Byte-wise modular subtraction is lossless; no saturation.
            if (work_valid && !work_phase) begin
                work_delta[23:16] <= work_pixel[23:16] - work_base[23:16];
                work_delta[15:8] <= work_pixel[15:8] - work_base[15:8];
                work_delta[7:0] <= work_pixel[7:0] - work_base[7:0];
                row_history[work_position % ROWS] <= work_pixel;
                work_phase <= 1'b1;
            end

            // A stalled output never prevents queue writes or corrupts history.
            if (m_valid && m_ready)
                m_valid <= 1'b0;
            if (publishing) begin
                m_valid <= 1'b1;
                m_delta <= work_delta;
                m_position <= work_position;
                m_seed <= work_seed;
                m_last <= work_last;
                work_valid <= 1'b0;
            end
        end
    end
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted,
    output reg [31:0] debug_status
,
    output wire [W-1:0] in_cnt_o,
    output wire [W-1:0] out_cnt_o
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;
    reg [31:0] dbg_cycles, dbg_input_stalls, dbg_output_stalls;
    reg [31:0] dbg_frames, dbg_cfg_writes;
    reg [15:0] dbg_stall_run, dbg_stall_max, dbg_idle_age;
    reg [7:0] dbg_high_water;
    reg [3:0] dbg_flags;
    reg dbg_enable;
    wire dbg_input_blocked = i_valid && !i_ready;
    wire dbg_output_blocked = o_valid && !o_ready;
    wire dbg_clear = cfg_we && (cfg_addr == 4'd15) && cfg_data[0];
    initial begin
        dbg_cycles = 32'd0;
        dbg_input_stalls = 32'd0;
        dbg_output_stalls = 32'd0;
        dbg_frames = 32'd0;
        dbg_cfg_writes = 32'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_max = 16'd0;
        dbg_idle_age = 16'd0;
        dbg_high_water = 8'd0;
        dbg_flags = 4'd0;
        dbg_enable = 1'b1;
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (rst) begin
            dbg_cycles <= 32'd0;
            dbg_input_stalls <= 32'd0;
            dbg_output_stalls <= 32'd0;
            dbg_frames <= 32'd0;
            dbg_cfg_writes <= 32'd0;
            dbg_stall_run <= 16'd0;
            dbg_stall_max <= 16'd0;
            dbg_idle_age <= 16'd0;
            dbg_high_water <= 8'd0;
            dbg_flags <= 4'd0;
            dbg_enable <= 1'b1;
            debug_status <= 32'd0;
        end else begin
            if (cfg_we && cfg_addr == 4'd9)
                dbg_enable <= cfg_data[0];
            if (dbg_clear) begin
                dbg_cycles <= 32'd0;
                dbg_input_stalls <= 32'd0;
                dbg_output_stalls <= 32'd0;
                dbg_frames <= 32'd0;
                dbg_cfg_writes <= 32'd0;
                dbg_stall_run <= 16'd0;
                dbg_stall_max <= 16'd0;
                dbg_idle_age <= 16'd0;
                dbg_high_water <= 8'd0;
                dbg_flags <= 4'd0;
            end else if (dbg_enable) begin
                if (!(&dbg_cycles))
                    dbg_cycles <= dbg_cycles + 32'd1;
                if (dbg_input_blocked && !(&dbg_input_stalls))
                    dbg_input_stalls <= dbg_input_stalls + 32'd1;
                if (dbg_output_blocked && !(&dbg_output_stalls))
                    dbg_output_stalls <= dbg_output_stalls + 32'd1;
                if (out_fire && o_last && !(&dbg_frames))
                    dbg_frames <= dbg_frames + 32'd1;
                if (cfg_we && cfg_addr <= 4'd8 && !(&dbg_cfg_writes))
                    dbg_cfg_writes <= dbg_cfg_writes + 32'd1;
                if (ingress_level > dbg_high_water)
                    dbg_high_water <= (ingress_level > 255) ? 8'hff : ingress_level;
                if (dbg_output_blocked) begin
                    if (!(&dbg_stall_run))
                        dbg_stall_run <= dbg_stall_run + 16'd1;
                    if (dbg_stall_run >= dbg_stall_max && !(&dbg_stall_run))
                        dbg_stall_max <= dbg_stall_run + 16'd1;
                end else
                    dbg_stall_run <= 16'd0;
                if ((ingress_valid || o_valid) && !out_fire) begin
                    if (!(&dbg_idle_age))
                        dbg_idle_age <= dbg_idle_age + 16'd1;
                    if (&dbg_idle_age)
                        dbg_flags[2] <= 1'b1;
                end else
                    dbg_idle_age <= 16'd0;
                if (dbg_input_blocked)
                    dbg_flags[0] <= 1'b1;
                if (dbg_output_blocked)
                    dbg_flags[1] <= 1'b1;
                if (cfg_we && armed)
                    dbg_flags[3] <= 1'b1;
            end
            case (cfg_addr)
                4'd9: debug_status <= {31'd0, dbg_enable};
                4'd10: debug_status <= dbg_cycles;
                4'd11: debug_status <= dbg_input_stalls;
                4'd12: debug_status <= dbg_output_stalls;
                4'd13: debug_status <= dbg_frames;
                4'd14: debug_status <= {dbg_stall_max, dbg_stall_run};
                4'd15: debug_status <= {dbg_high_water, dbg_flags, 4'd0, dbg_idle_age};
                default: debug_status <= dbg_cfg_writes;
            endcase
        end
    end

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
    assign in_cnt_o = in_cnt;
    assign out_cnt_o = out_cnt;
endmodule

module transpose_buf #(
    parameter ROWS  = 4,
    parameter COLS  = 8,
    parameter DEPTH = ROWS * COLS,
    parameter DW    = 32
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data
,
    output wire [1:0] chain_o,
    output wire phase_o,
    output wire [31:0] rd_col_o,
    output wire [31:0] rd_row_o,
    output wire [31:0] wr_col_o,
    output wire [31:0] wr_row_o
);
    localparam AW = $clog2(DEPTH);
    localparam [1:0] C_IDLE  = 2'd0;
    localparam [1:0] C_ARM   = 2'd1;
    localparam [1:0] C_START = 2'd2;
    localparam PH_FILL  = 1'b0;
    localparam PH_DRAIN = 1'b1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg        phase    = 1'b0;
    reg [31:0] wr_row   = 32'd0;
    reg [31:0] wr_col   = 32'd0;
    reg [31:0] rd_row   = 32'd0;
    reg [31:0] rd_col   = 32'd0;
    reg [1:0]  chain    = 2'd0;
    reg        before_r = 1'b1;
    reg        pv       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = {DW{1'b0}};
    end

    assign in_ready  = (phase == PH_FILL);
    assign out_valid = (phase == PH_DRAIN);

    wire wr_fire = in_valid && in_ready;
    wire rd_fire = out_valid && out_ready;
    wire wr_last = (wr_row == ROWS - 1) && (wr_col == COLS - 1);
    wire rd_last = (rd_row == ROWS - 1) && (rd_col == COLS - 1);

    wire [31:0] wr_addr = wr_row * COLS + wr_col;
    wire [31:0] rd_addr = rd_row * COLS + rd_col;

    assign out_data = mem[rd_addr[AW-1:0]];

    // row-order write into the tile
    always @(posedge clk) begin
        if (wr_fire)
            mem[wr_addr[AW-1:0]] <= in_data;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase    <= PH_FILL;
            wr_row   <= 32'd0;
            wr_col   <= 32'd0;
            rd_row   <= 32'd0;
            rd_col   <= 32'd0;
            chain    <= C_IDLE;
            before_r <= 1'b1;
        end else begin
            if (wr_fire) begin
                if (wr_col == COLS - 1) begin
                    wr_col <= 32'd0;
                    if (wr_row == ROWS - 1) wr_row <= 32'd0;
                    else                    wr_row <= wr_row + 32'd1;
                end else begin
                    wr_col <= wr_col + 32'd1;
                end
                if (wr_last) begin
                    phase <= PH_DRAIN;
                    chain <= C_START;
                end else if (chain == C_IDLE) begin
                    chain <= C_ARM;
                end
            end
            // column-order read out of the tile
            if (rd_fire) begin
                if (rd_row == ROWS - 1) begin
                    rd_row <= 32'd0;
                    if (rd_col == COLS - 1) rd_col <= 32'd0;
                    else                    rd_col <= rd_col + 32'd1;
                end else begin
                    rd_row <= rd_row + 32'd1;
                end
                if (rd_last) begin
                    phase    <= PH_FILL;
                    chain    <= C_IDLE;
                    before_r <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    // Chain precedence (arm -> start -> finish), before first tile completes:
    // while the chain FSM sits unchanged short of START, no column-order read may advance.
    always @(posedge clk) begin
        if (pv && before_r && $stable(chain) && chain != C_START)
            assert ($stable(rd_row) && $stable(rd_col));
    end
    assign chain_o = chain;
    assign phase_o = phase;
    assign rd_col_o = rd_col;
    assign rd_row_o = rd_row;
    assign wr_col_o = wr_col;
    assign wr_row_o = wr_row;
endmodule

module rgb_ycc_tile_pipeline #(
    parameter INGRESS_DEPTH = 4,
    parameter BRIDGE_DEPTH = 4,
    parameter TILE_ROWS = 4,
parameter TILE_COLS = 4,
parameter ANALYTICS_DEPTH = 4,
parameter PREDICTION_DEPTH = 4
) (
    input wire clk,
    input wire rst,
    input wire cfg_we,
    input wire [3:0] cfg_addr,
    input wire [31:0] cfg_data,
    input wire i_valid,
    output wire i_ready,
    input wire [7:0] i_r, i_g, i_b,
    input wire i_first, i_last,
    output wire o_valid,
    input wire o_ready,
    output wire [23:0] o_data,
    output wire a_o_valid, a_o_ready,
    output wire [7:0] a_o_y, a_o_cb, a_o_cr,
    output wire a_o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] a_ingress_level,
    output wire [31:0] a_ingress_accepted,
    output wire [31:0] a_in_cnt, a_out_cnt,
    output wire [31:0] a_debug_status,
    output wire b_in_valid, b_in_ready,
    output wire [1:0] b_chain,
    output wire b_phase,
    output wire [31:0] b_rd_col, b_rd_row, b_wr_col, b_wr_row,
    output reg [$clog2(BRIDGE_DEPTH+1)-1:0] bridge_level,
    output reg [31:0] delivered_pixels,
    output wire [31:0] tile_held,
    output wire [31:0] pending_pixels,
    output reg pipeline_active,
output wire busy,
output wire analysis_ready,
output wire [$clog2(ANALYTICS_DEPTH):0] analysis_level,
output reg analysis_enabled,
output reg analysis_report_valid,
output reg [7:0] analysis_min_y,
output reg [7:0] analysis_max_y,
output reg [7:0] analysis_peak_edge,
output reg [7:0] analysis_chroma_separation,
output reg [23:0] analysis_first_pixel,
output reg [23:0] analysis_last_pixel,
output wire prediction_valid,
output wire [23:0] prediction_delta,
output wire [((TILE_ROWS*TILE_COLS > 1) ? $clog2(TILE_ROWS*TILE_COLS) : 1)-1:0] prediction_position,
output wire prediction_seed,
output wire prediction_last,
output wire prediction_ready,
output wire [$clog2(PREDICTION_DEPTH+1)-1:0] prediction_level
);
    localparam TILE_PIXELS = TILE_ROWS * TILE_COLS;
    localparam TOTAL_CAPACITY = INGRESS_DEPTH + 1 + BRIDGE_DEPTH + TILE_PIXELS;
    localparam BRIDGE_PTR_W = $clog2(BRIDGE_DEPTH);
    localparam PREDICTION_PTR_W = $clog2(PREDICTION_DEPTH);
    localparam PREDICTION_POS_W = (TILE_PIXELS > 1) ? $clog2(TILE_PIXELS) : 1;
    wire tile_output_valid, tile_output_ready;
    wire [23:0] tile_output_data;
    wire [PREDICTION_PTR_W-1:0] prediction_rd_ptr, prediction_wr_ptr;
    wire [PREDICTION_POS_W-1:0] prediction_cursor;
    wire [PREDICTION_POS_W-1:0] prediction_head_position;
    wire [PREDICTION_DEPTH*PREDICTION_POS_W-1:0] prediction_positions;
    wire prediction_take, prediction_work_valid;
    wire [PREDICTION_POS_W-1:0] prediction_input_position =
        b_rd_col * TILE_ROWS + b_rd_row;

    // Original pixels and encoder requests fork atomically at the tile.
    // Both output interfaces use o_ready for consumer pacing.
    assign o_valid = tile_output_valid && prediction_ready;
    assign o_data = tile_output_data;
    assign tile_output_ready = o_ready && prediction_ready;
    wire rst_n = !rst;
    reg [23:0] bridge_mem [0:BRIDGE_DEPTH-1];
    reg [BRIDGE_PTR_W-1:0] bridge_rd_ptr, bridge_wr_ptr;
    wire [23:0] b_in_data = bridge_mem[bridge_rd_ptr];
    wire bridge_push = a_o_valid && a_o_ready;
    wire bridge_pop = b_in_valid && b_in_ready;
    wire sink_fire = o_valid && o_ready;
    integer j;

    localparam ANALYSIS_PTR_W = $clog2(ANALYTICS_DEPTH);
    localparam TILE_POS_W = (TILE_PIXELS > 1) ? $clog2(TILE_PIXELS) : 1;
    reg [23:0] analysis_pixels [0:ANALYTICS_DEPTH-1];
    reg [TILE_POS_W-1:0] analysis_pos [0:ANALYTICS_DEPTH-1];
    reg [ANALYSIS_PTR_W:0] analysis_rd_ptr, analysis_wr_ptr;
    reg [TILE_POS_W-1:0] analysis_cursor;
    reg analysis_work_valid, analysis_work_phase;
    reg analysis_work_first, analysis_work_last;
    reg [23:0] analysis_work_pixel;
    reg [TILE_POS_W-1:0] analysis_work_pos;
    reg [7:0] analysis_min_acc, analysis_max_acc;
    reg [7:0] analysis_edge_acc, analysis_chroma_acc;
    reg [7:0] analysis_previous_y;
    reg [23:0] analysis_first_acc;
    reg [7:0] analysis_next_min, analysis_next_max;
    reg [7:0] analysis_next_edge, analysis_next_chroma;
    reg [7:0] analysis_y_delta, analysis_chroma_delta;
    integer aj;

    wire bridge_offer = pipeline_active && (bridge_level != 0);
    wire analysis_empty = analysis_rd_ptr == analysis_wr_ptr;
    wire analysis_full =
        (analysis_rd_ptr[ANALYSIS_PTR_W-1:0] ==
         analysis_wr_ptr[ANALYSIS_PTR_W-1:0]) &&
        (analysis_rd_ptr[ANALYSIS_PTR_W] !=
         analysis_wr_ptr[ANALYSIS_PTR_W]);
    wire analysis_take = analysis_enabled && !analysis_empty &&
                         !analysis_work_valid;
    wire analysis_put = bridge_pop;
    wire analysis_finish = analysis_work_valid && analysis_work_phase;
    wire [23:0] analysis_head_pixel =
        analysis_pixels[analysis_rd_ptr[ANALYSIS_PTR_W-1:0]];
    wire [TILE_POS_W-1:0] analysis_head_pos =
        analysis_pos[analysis_rd_ptr[ANALYSIS_PTR_W-1:0]];
    wire [7:0] analysis_y = analysis_work_pixel[23:16];
    wire [7:0] analysis_cb = analysis_work_pixel[15:8];
    wire [7:0] analysis_cr = analysis_work_pixel[7:0];
    wire [ANALYSIS_PTR_W+1:0] analysis_held =
        {1'b0, analysis_level} + analysis_work_valid;

    function [ANALYSIS_PTR_W:0] analysis_advance;
        input [ANALYSIS_PTR_W:0] ptr;
        begin
            if (ptr[ANALYSIS_PTR_W-1:0] == ANALYTICS_DEPTH-1)
                analysis_advance = {!ptr[ANALYSIS_PTR_W],
                                    {ANALYSIS_PTR_W{1'b0}}};
            else
                analysis_advance = ptr + 1'b1;
        end
    endfunction

    assign analysis_level =
        (analysis_wr_ptr[ANALYSIS_PTR_W] ==
         analysis_rd_ptr[ANALYSIS_PTR_W])
        ? analysis_wr_ptr[ANALYSIS_PTR_W-1:0] -
          analysis_rd_ptr[ANALYSIS_PTR_W-1:0]
        : ANALYTICS_DEPTH + analysis_wr_ptr[ANALYSIS_PTR_W-1:0] -
          analysis_rd_ptr[ANALYSIS_PTR_W-1:0];
    assign analysis_ready = !analysis_full || analysis_take;

    // Row boundaries suppress transitions between unrelated row endpoints.
    always @(*) begin
        analysis_y_delta = (analysis_y >= analysis_previous_y)
                         ? analysis_y - analysis_previous_y
                         : analysis_previous_y - analysis_y;
        analysis_chroma_delta = (analysis_cb >= analysis_cr)
                              ? analysis_cb - analysis_cr
                              : analysis_cr - analysis_cb;
        analysis_next_min = analysis_min_acc;
        analysis_next_max = analysis_max_acc;
        analysis_next_edge = analysis_edge_acc;
        analysis_next_chroma = analysis_chroma_acc;
        if (analysis_work_first) begin
            analysis_next_min = analysis_y;
            analysis_next_max = analysis_y;
            analysis_next_edge = 8'd0;
            analysis_next_chroma = analysis_chroma_delta;
        end else begin
            if (analysis_y < analysis_min_acc)
                analysis_next_min = analysis_y;
            if (analysis_y > analysis_max_acc)
                analysis_next_max = analysis_y;
            if (analysis_chroma_delta > analysis_chroma_acc)
                analysis_next_chroma = analysis_chroma_delta;
        end
        if ((analysis_work_pos % TILE_COLS) != 0 &&
            analysis_y_delta > analysis_next_edge)
            analysis_next_edge = analysis_y_delta;
    end

    // A completed tile blocks its input until column-order draining finishes.
    assign b_in_valid = bridge_offer && analysis_ready;
    assign a_o_ready = pipeline_active &&
                       ((bridge_level < BRIDGE_DEPTH) || bridge_pop);
    assign tile_held = b_phase
                     ? TILE_PIXELS - (b_rd_col * TILE_ROWS + b_rd_row)
                     : b_wr_row * TILE_COLS + b_wr_col;
    assign pending_pixels = a_ingress_accepted - delivered_pixels;
    assign busy = !pipeline_active || (a_ingress_level != 0) ||
                  a_o_valid || (bridge_level != 0) || (tile_held != 0) ||
                  (prediction_level != 0) || prediction_work_valid ||
                  prediction_valid;

    csc_rgb2ycc #(.W(32), .FRAC(16), .INGRESS_DEPTH(INGRESS_DEPTH)) color (
        .clk(clk), .rst(rst),
        .cfg_we(cfg_we), .cfg_addr(cfg_addr), .cfg_data(cfg_data),
        .i_valid(i_valid), .i_ready(i_ready),
        .i_r(i_r), .i_g(i_g), .i_b(i_b),
        .i_first(i_first), .i_last(i_last),
        .o_valid(a_o_valid), .o_ready(a_o_ready),
        .o_y(a_o_y), .o_cb(a_o_cb), .o_cr(a_o_cr), .o_last(a_o_last),
        .ingress_level(a_ingress_level), .ingress_accepted(a_ingress_accepted),
        .debug_status(a_debug_status), .in_cnt_o(a_in_cnt), .out_cnt_o(a_out_cnt)
    );
    transpose_buf #(
        .ROWS(TILE_ROWS), .COLS(TILE_COLS), .DEPTH(TILE_PIXELS), .DW(24)
    ) tile (
        .clk(clk), .rst_n(rst_n),
        .in_valid(b_in_valid), .in_ready(b_in_ready), .in_data(b_in_data),
        .out_valid(tile_output_valid), .out_ready(tile_output_ready),
        .out_data(tile_output_data),
        .chain_o(b_chain), .phase_o(b_phase),
        .rd_col_o(b_rd_col), .rd_row_o(b_rd_row),
        .wr_col_o(b_wr_col), .wr_row_o(b_wr_row)
    );

    column_predictive_encoder #(
        .ROWS(TILE_ROWS), .COLS(TILE_COLS), .DEPTH(PREDICTION_DEPTH),
        .POS_W(PREDICTION_POS_W)
    ) predictor (
        .clk(clk), .rst_n(rst_n),
        .s_valid(tile_output_valid && o_ready),
        .s_ready(prediction_ready), .s_pixel(tile_output_data),
        .s_position(prediction_input_position),
        .m_valid(prediction_valid), .m_ready(o_ready),
        .m_delta(prediction_delta), .m_position(prediction_position),
        .m_seed(prediction_seed), .m_last(prediction_last),
        .level(prediction_level),
        .rd_ptr(prediction_rd_ptr), .wr_ptr(prediction_wr_ptr),
        .cursor(prediction_cursor), .taking(prediction_take),
        .head_position(prediction_head_position),
        .queued_positions(prediction_positions),
        .work_valid(prediction_work_valid)
    );

    initial begin
        pipeline_active = 1'b0;
        bridge_level = 0;
        delivered_pixels = 32'd0;
        bridge_rd_ptr = {BRIDGE_PTR_W{1'b0}};
        bridge_wr_ptr = {BRIDGE_PTR_W{1'b0}};
        for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
            bridge_mem[j] = 24'd0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipeline_active <= 1'b0;
            bridge_level <= 0;
            delivered_pixels <= 32'd0;
            bridge_rd_ptr <= {BRIDGE_PTR_W{1'b0}};
            bridge_wr_ptr <= {BRIDGE_PTR_W{1'b0}};
            for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
                bridge_mem[j] <= 24'd0;
        end else begin
            pipeline_active <= 1'b1;
            case ({bridge_push, bridge_pop})
                2'b10: bridge_level <= bridge_level + 1'b1;
                2'b01: bridge_level <= bridge_level - 1'b1;
                default: ;
            endcase
            if (bridge_push) begin
                bridge_mem[bridge_wr_ptr] <= {a_o_y, a_o_cb, a_o_cr};
                bridge_wr_ptr <= (bridge_wr_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_wr_ptr + 1'b1;
            end
            if (bridge_pop)
                bridge_rd_ptr <= (bridge_rd_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_rd_ptr + 1'b1;
            if (sink_fire)
                delivered_pixels <= delivered_pixels + 32'd1;
        end
    end

    initial begin
        analysis_rd_ptr = {(ANALYSIS_PTR_W+1){1'b0}};
        analysis_wr_ptr = {(ANALYSIS_PTR_W+1){1'b0}};
        analysis_cursor = {TILE_POS_W{1'b0}};
        analysis_enabled = 1'b1;
        analysis_work_valid = 1'b0;
        analysis_work_phase = 1'b0;
        analysis_work_first = 1'b0;
        analysis_work_last = 1'b0;
        analysis_work_pixel = 24'd0;
        analysis_work_pos = {TILE_POS_W{1'b0}};
        analysis_min_acc = 8'hff;
        analysis_max_acc = 8'd0;
        analysis_edge_acc = 8'd0;
        analysis_chroma_acc = 8'd0;
        analysis_previous_y = 8'd0;
        analysis_first_acc = 24'd0;
        analysis_report_valid = 1'b0;
        analysis_min_y = 8'd0;
        analysis_max_y = 8'd0;
        analysis_peak_edge = 8'd0;
        analysis_chroma_separation = 8'd0;
        analysis_first_pixel = 24'd0;
        analysis_last_pixel = 24'd0;
        for (aj = 0; aj < ANALYTICS_DEPTH; aj = aj + 1) begin
            analysis_pixels[aj] = 24'd0;
            analysis_pos[aj] = {TILE_POS_W{1'b0}};
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            analysis_rd_ptr <= {(ANALYSIS_PTR_W+1){1'b0}};
            analysis_wr_ptr <= {(ANALYSIS_PTR_W+1){1'b0}};
            analysis_cursor <= {TILE_POS_W{1'b0}};
            analysis_enabled <= 1'b1;
            analysis_work_valid <= 1'b0;
            analysis_work_phase <= 1'b0;
            analysis_work_first <= 1'b0;
            analysis_work_last <= 1'b0;
            analysis_work_pixel <= 24'd0;
            analysis_work_pos <= {TILE_POS_W{1'b0}};
            analysis_min_acc <= 8'hff;
            analysis_max_acc <= 8'd0;
            analysis_edge_acc <= 8'd0;
            analysis_chroma_acc <= 8'd0;
            analysis_previous_y <= 8'd0;
            analysis_first_acc <= 24'd0;
            analysis_report_valid <= 1'b0;
            analysis_min_y <= 8'd0;
            analysis_max_y <= 8'd0;
            analysis_peak_edge <= 8'd0;
            analysis_chroma_separation <= 8'd0;
            analysis_first_pixel <= 24'd0;
            analysis_last_pixel <= 24'd0;
            for (aj = 0; aj < ANALYTICS_DEPTH; aj = aj + 1) begin
                analysis_pixels[aj] <= 24'd0;
                analysis_pos[aj] <= {TILE_POS_W{1'b0}};
            end
        end else begin
            analysis_report_valid <= 1'b0;
            if (cfg_we && cfg_addr == 4'd9)
                analysis_enabled <= cfg_data[1];

            // Fork only transfers that were also accepted by the tile.
            if (analysis_put) begin
                analysis_pixels[analysis_wr_ptr[ANALYSIS_PTR_W-1:0]] <=
                    b_in_data;
                analysis_pos[analysis_wr_ptr[ANALYSIS_PTR_W-1:0]] <=
                    b_wr_row * TILE_COLS + b_wr_col;
                analysis_wr_ptr <= analysis_advance(analysis_wr_ptr);
            end
            if (analysis_take) begin
                analysis_work_valid <= 1'b1;
                analysis_work_phase <= 1'b0;
                analysis_work_pixel <= analysis_head_pixel;
                analysis_work_pos <= analysis_head_pos;
                analysis_work_first <= analysis_cursor == 0;
                analysis_work_last <= analysis_cursor == TILE_PIXELS-1;
                analysis_rd_ptr <= analysis_advance(analysis_rd_ptr);
                analysis_cursor <= (analysis_cursor == TILE_PIXELS-1)
                                 ? {TILE_POS_W{1'b0}}
                                 : analysis_cursor + 1'b1;
            end

            // Luma and chroma passes share the held pixel, not the FIFO port.
            if (analysis_work_valid) begin
                if (!analysis_work_phase) begin
                    analysis_min_acc <= analysis_next_min;
                    analysis_max_acc <= analysis_next_max;
                    analysis_edge_acc <= analysis_next_edge;
                    analysis_previous_y <= analysis_y;
                    if (analysis_work_first)
                        analysis_first_acc <= analysis_work_pixel;
                    analysis_work_phase <= 1'b1;
                end else begin
                    analysis_chroma_acc <= analysis_next_chroma;
                    analysis_work_valid <= 1'b0;
                    if (analysis_work_last) begin
                        analysis_report_valid <= 1'b1;
                        analysis_min_y <= analysis_min_acc;
                        analysis_max_y <= analysis_max_acc;
                        analysis_peak_edge <= analysis_edge_acc;
                        analysis_chroma_separation <= analysis_next_chroma;
                        analysis_first_pixel <= analysis_first_acc;
                        analysis_last_pixel <= analysis_work_pixel;
                    end
                end
            end
        end
    end

    always @(posedge clk) begin
        if (pipeline_active && analysis_take)
            assert (analysis_head_pos == analysis_cursor);
    end

    always @(posedge clk) begin
        if (pipeline_active && prediction_take)
            assert (prediction_head_position == prediction_cursor);
    end

    always @(posedge clk) begin
        if (pipeline_active)
            assert (pending_pixels <= TOTAL_CAPACITY);
    end
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
output wire [W-1:0] q_mag,
input  wire         peer_in_valid,
output wire         peer_in_ready,
input  wire [W-1:0] peer_in_mag,
output wire         peer_out_valid,
input  wire         peer_out_ready,
output wire [W-1:0] peer_out_min1,
output wire [W-1:0] peer_out_min2,
input  wire         aux_in_valid,
output wire         aux_in_ready,
input  wire [W-1:0] aux_in_mag,
input  wire         aux_in_sign,
output wire         aux_out_valid,
input  wire         aux_out_ready,
output wire [W-1:0] aux_out_min1,
output wire [W-1:0] aux_out_min2,
output wire         aux_out_sign
);
localparam CHANNELS = 3, MINIMA = 2, PEER_CW = (DEG > 1) ? $clog2(DEG) : 1;
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

reg [W-1:0] minima [0:CHANNELS*MINIMA-1];
wire [W-1:0] min1 = minima[0], min2 = minima[1];
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
integer mi;
initial for (mi = 0; mi < CHANNELS*MINIMA; mi = mi + 1) minima[mi] = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
reg [PEER_CW-1:0] peer_count;
reg peer_done;
reg owner_peer;
initial begin peer_count = 0; peer_done = 0; owner_peer = 1; end
reg [PEER_CW-1:0] aux_count;
reg aux_done, aux_owner, aux_sign_prod;
initial begin
    aux_count = 0;
    aux_done = 0;
    aux_owner = 1;
    aux_sign_prod = 0;
end
wire frames_idle = (count == 0) && (peer_count == 0);
wire all_frames_idle = frames_idle && (aux_count == 0);
wire pair_request = (in_valid && state == S_ACCUM) ||
                    (peer_in_valid && !peer_done);
wire select_aux = all_frames_idle ?
    (aux_in_valid && !aux_done && (!pair_request || !aux_owner)) : aux_owner;
wire select_peer = frames_idle ? (peer_in_valid && !peer_done && (!in_valid || state != S_ACCUM || !owner_peer)) : owner_peer;
assign peer_in_ready = select_peer && !peer_done && !select_aux;
assign aux_in_ready = select_aux && !aux_done;
wire peer_acc = peer_in_valid && peer_in_ready;
wire aux_acc = aux_in_valid && aux_in_ready;
wire [W-1:0] cmp_mag = select_aux ? aux_in_mag :
                          (select_peer ? peer_in_mag : in_mag);
wire [W-1:0] cmp_min1 = select_aux ? minima[2*MINIMA] :
                           (select_peer ? minima[MINIMA] : min1);
wire [W-1:0] cmp_min2 = select_aux ? minima[2*MINIMA+1] :
                           (select_peer ? minima[MINIMA+1] : min2);
wire new_first = cmp_mag < cmp_min1;
wire [W-1:0] step_min1 = new_first ? cmp_mag : cmp_min1;
wire [W-1:0] step_min2 = new_first ? cmp_min1 : ((cmp_mag < cmp_min2) ? cmp_mag : cmp_min2);
assign peer_out_valid = peer_done;
assign peer_out_min1 = minima[MINIMA], peer_out_min2 = minima[MINIMA+1];
assign aux_out_valid = aux_done;
assign aux_out_min1 = minima[2*MINIMA];
assign aux_out_min2 = minima[2*MINIMA+1];
assign aux_out_sign = aux_sign_prod;

assign in_ready  = (state == S_ACCUM) && !select_peer && !select_aux;
    assign out_valid = (state == S_DONE);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready;
wire [CHANNELS-1:0] lane_acc = {aux_acc, peer_acc, acc};
wire [CHANNELS-1:0] lane_rel = {aux_out_valid && aux_out_ready,
                              peer_out_valid && peer_out_ready, rel};
integer lane;
always @(posedge clk) begin
    for (lane = 0; lane < CHANNELS; lane = lane + 1) begin
        if (lane_acc[lane] || lane_rel[lane]) begin
            minima[lane*MINIMA] <= lane_acc[lane] ? step_min1 : {W{1'b1}};
            minima[lane*MINIMA+1] <= lane_acc[lane] ? step_min2 : {W{1'b1}};
        end
    end
    if (acc || peer_acc) owner_peer <= select_peer;
    if (acc || peer_acc || aux_acc) aux_owner <= select_aux;
    if (peer_acc) begin
        if (peer_count == DEG - 1) begin peer_count <= 0; peer_done <= 1; end
        else peer_count <= peer_count + 1'b1;
    end else if (lane_rel[1]) peer_done <= 0;
end
always @(posedge clk) begin
    if (aux_acc) begin
        aux_sign_prod <= aux_sign_prod ^ aux_in_sign;
        if (aux_count == DEG - 1) begin
            aux_count <= 0;
            aux_done <= 1;
        end else begin
            aux_count <= aux_count + 1'b1;
        end
    end else if (lane_rel[2]) begin
        aux_done <= 0;
        aux_sign_prod <= 0;
    end
end

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
if (new_first) min_idx <= count;
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = min1;
    assign out_min2 = min2;
    assign out_idx  = min_idx;
    assign out_sign = sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
always @(posedge clk) if (pv) assert ((count == 0) || (peer_count == 0));
always @(posedge clk) if (pv) assert ((aux_count == 0) || ((count == 0) && (peer_count == 0)));
endmodule

